-- Almokhtasar News Platform Seed for Turso LibSQL
PRAGMA foreign_keys = OFF;
CREATE TABLE IF NOT EXISTS admin_records (
    id TEXT PRIMARY KEY,
    resource TEXT NOT NULL,
    title TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'نشط',
    data TEXT NOT NULL DEFAULT '{}',
    deleted INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
CREATE TABLE IF NOT EXISTS admin_settings (
    section TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    updated_by TEXT NOT NULL
  );
CREATE TABLE IF NOT EXISTS admin_audit_logs (
    id TEXT PRIMARY KEY,
    actor TEXT NOT NULL,
    action TEXT NOT NULL,
    resource TEXT NOT NULL,
    record_id TEXT,
    details TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL
  );
CREATE TABLE IF NOT EXISTS source_refresh_runs (
    id TEXT PRIMARY KEY,
    source_id TEXT,
    status TEXT NOT NULL,
    report TEXT NOT NULL DEFAULT '{}',
    started_at TEXT NOT NULL,
    finished_at TEXT NOT NULL,
    actor TEXT NOT NULL
  );
CREATE TABLE IF NOT EXISTS social_trends (
    id TEXT PRIMARY KEY,
    platform TEXT NOT NULL,
    account TEXT NOT NULL,
    handle TEXT NOT NULL DEFAULT '',
    verified INTEGER NOT NULL DEFAULT 0,
    text TEXT NOT NULL,
    topic TEXT NOT NULL DEFAULT '',
    published_at TEXT,
    metrics TEXT NOT NULL DEFAULT '[]',
    url TEXT NOT NULL,
    source TEXT NOT NULL,
    retrieved_at TEXT NOT NULL
  , normalized TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS social_refresh_status (
    platform TEXT PRIMARY KEY,
    status TEXT NOT NULL,
    message TEXT NOT NULL DEFAULT '',
    item_count INTEGER NOT NULL DEFAULT 0,
    started_at TEXT NOT NULL,
    finished_at TEXT NOT NULL
  );
CREATE TABLE IF NOT EXISTS retrieval_schedules (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    enabled INTEGER NOT NULL DEFAULT 0,
    target_type TEXT NOT NULL,
    target_id TEXT,
    frequency TEXT NOT NULL,
    interval_hours INTEGER NOT NULL DEFAULT 1,
    fixed_time TEXT NOT NULL DEFAULT '00:00',
    weekdays TEXT NOT NULL DEFAULT '[]',
    timezone TEXT NOT NULL DEFAULT 'Asia/Riyadh',
    workflow TEXT NOT NULL DEFAULT 'review',
    next_run_at TEXT,
    last_run_at TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  , frequency_minutes INTEGER NOT NULL DEFAULT 10, last_status TEXT NOT NULL DEFAULT 'pending', last_error TEXT NOT NULL DEFAULT '');
