INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3628f874-805b-406c-9aa2-88e8e0ea3e5c','imported-3628f874-805b-406c-9aa2-88e8e0ea3e5c','الكاتبة وصانعة الأفلام والممثلة السعودية فاطمة البنوي: إرثي الأهم ليس في حجم الأعمال بل في ترك الأثر','الكاتبة وصانعة الأفلام والممثلة السعودية فاطمة البنوي إرثي الأهم ليس في حجم الأعمال بل في ترك الأثر','قبل عشرةِ أعوامٍ، أطلَّت علينا فاطمة البنوي، لتُسجِّل حضوراً لافتاً بوصفها واحدةً من الوجوه الواعدةِ في السينما السعوديَّة.','["اليوم، وبعد عقدٍ من التحوُّلاتِ الجذريَّةِ في المشهدِ الثقافي والفنِّي بالمملكةِ تحت مظلَّةِ \"رؤيةِ 2030\"، تعودُ البنوي بخبرةٍ أعمقَ، ورؤيةٍ أشملَ، لتجمعَ بين التأليفِ، والإخراجِ، والتمثيل، وتضع بصمتَها الخاصَّةَ على أعمالٍ، تُناقِش قضايا إنسانيَّةً ونفسيَّةً مُركَّبةً. من عودتها القويَّةِ للدراما عبر حفرة جهنم إلى تجربتها الشاملةِ في فيلمِ بسمة، وحضورها البارزِ في الكوميديا بـ العميل صفر، نستكشفُ في هذا الحوارِ…"]','الثقافة','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%A8%D9%84%D8%B3/%D9%82%D8%B5%D8%B5-%D9%85%D9%84%D9%87%D9%85%D8%A9/1835287-%D9%81%D8%A7%D8%B7%D9%85%D8%A9-%D8%A7%D9%84%D8%A8%D9%86%D9%88%D9%8A','https://www.sayidaty.net/%D8%A8%D9%84%D8%B3/%D9%82%D8%B5%D8%B5-%D9%85%D9%84%D9%87%D9%85%D8%A9/1835287-%D9%81%D8%A7%D8%B7%D9%85%D8%A9-%D8%A7%D9%84%D8%A8%D9%86%D9%88%D9%8A','','','المجلة','','2026-06-16T12:00:00.000Z',NULL,'2026-07-21T18:11:40.495Z','https://static.sayidaty.net/styles/681x999/public/2026-06/497072.jpg.webp?VersionId=iMVZtREcr4hTVK07ZDAAjpYBPCeE6jEt','/api/media/3628f874-805b-406c-9aa2-88e8e0ea3e5c','/api/media/3628f874-805b-406c-9aa2-88e8e0ea3e5c?variant=thumbnail','الكاتبة وصانعة الأفلام والممثلة السعودية فاطمة البنوي: إرثي الأهم ليس في حجم الأعمال بل في ترك الأثر',681,999,'valid','published','archived','valid',96,'1fdaa465a552e8466d28f132d47d103632384301982a0e4f58b06147f58f2aff','fe899dde4553a4737bea01755acf85c6c90808fa779977766f4eb13786972e72',NULL,'2026-07-20T14:34:37.602Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون"]','["الثقافة والفنون"]','classified','cultural_content_verified','[{"category":"الثقافة","score":3},{"category":"السيارات","score":1.5},{"category":"الطاقة والصناعة","score":1.5}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
