INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b13eb31c-2d15-445c-8863-1bd0605abf5e','imported-b13eb31c-2d15-445c-8863-1bd0605abf5e','الفرق الكورية. تأثير يتجاوز المسرح','الفرق الكورية تأثير يتجاوز المسرح','لم تعد ظاهرةُ الـ K-Pop مجرَّد موسيقى تتردَّدُ أصداؤها في أنحاءِ العالم، بل تحوَّلت إلى لغةٍ بصريَّةٍ متكاملةٍ، تُعيد رسمَ ملامحِ الموضةِ المعاصرة، إذ، ومن شوارعِ سول Seoul النابضةِ بالحياة إلى منصَّاتِ العروضِ العالميَّة، استطاع نجومُ هذا الفنِّ أن يخلقوا…','["مع اتَّساعِ ما يُعرَف بـ «الموجةِ الكوريَّة»، لم يقتصر التأثيرُ على الأغنياتِ والعروضِ الفنيَّة فقط، بل وامتدَّ أيضاً إلى تفاصيلِ المظهرِ الشخصي من تنسيقِ الأزياءِ والألوان إلى صيحاتِ الجمالِ والإكسسوارات. في عالمٍ تتسارعُ فيه الاتِّجاهات، برزت مجتمعاتُ المعجبين بوصفها قوَّةً فاعلةً في نشرِ هذا الأسلوبِ وتطويره، لتُصبح الموضةُ المستوحاةُ من K-Pop ظاهرةً عالميَّةً تتجاوزُ حدودَ الثقافةِ والجغرافيا. هكذا، لم تعد…"]','الثقافة','فنون وتراث','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%A3%D9%86%D8%A7%D9%82%D8%A9/%D8%A3%D8%B2%D9%8A%D8%A7%D8%A1/1836702-%D8%A7%D9%84%D9%81%D8%B1%D9%82-%D8%A7%D9%84%D9%83%D9%88%D8%B1%D9%8A%D8%A9-%D8%AA%D8%A3%D8%AB%D9%8A%D8%B1-%D9%8A%D8%AA%D8%AC%D8%A7%D9%88%D8%B2-%D8%A7%D9%84%D9%85%D8%B3%D8%B1%D8%AD%C2%A0','https://www.sayidaty.net/%D8%A3%D9%86%D8%A7%D9%82%D8%A9/%D8%A3%D8%B2%D9%8A%D8%A7%D8%A1/1836702-%D8%A7%D9%84%D9%81%D8%B1%D9%82-%D8%A7%D9%84%D9%83%D9%88%D8%B1%D9%8A%D8%A9-%D8%AA%D8%A3%D8%AB%D9%8A%D8%B1-%D9%8A%D8%AA%D8%AC%D8%A7%D9%88%D8%B2-%D8%A7%D9%84%D9%85%D8%B3%D8%B1%D8%AD%C2%A0','','','سارة مرتضى','','2026-07-17T14:00:00.000Z',NULL,'2026-07-20T19:45:37.200Z','https://static.sayidaty.net/styles/681x999/public/2026-07/500098.jpg.webp?VersionId=jiujOf034OptD7lBc9J8Af226TJfXyWZ','/api/media/b13eb31c-2d15-445c-8863-1bd0605abf5e','/api/media/b13eb31c-2d15-445c-8863-1bd0605abf5e?variant=thumbnail','الفرق الكورية.. تأثير يتجاوز المسرح',681,999,'valid','published','archived','valid',58,'4f8326e6b091f778f953c2fc8baa77614ccd3c886d9d3cc6f518f1496c0b29e7','a843ef9b3c57dc8bcfb6141dd68a501bc9ff4cd5b120b7a9b53c8b496041e210',NULL,'2026-07-20T14:34:49.672Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["فنون وتراث","الثقافة والفنون"]','["فنون وتراث","الثقافة والفنون"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('636714f4-0a06-4335-84b2-2a33f6207d8f','imported-636714f4-0a06-4335-84b2-2a33f6207d8f','7 أفكار لتنسيق المجوهرات الفاخرة على طريقة أصالة','7 أفكار لتنسيق المجوهرات الفاخرة على طريقة أصالة','تُعرف الفنانة أصالة بأنها من أكثر النجمات العربيات امتلاكًا لأسلوب متجدد في اختيار الأزياء، لكن ما يميز إطلالاتها حقًا هو شغفها الواضح ب المجوهرات الفاخرة التي تمنح كل ظهور لها لمسة مختلفة من الرقي.','["على مدار السنوات، أثبتت أصالة أن المجوهرات ليست مجرد أكسسوار مكمل للإطلالة، بل عنصر أساسي يعكس شخصيتها ويبرز ذوقها الرفيع، إذ تتنقل بين تصاميم الذهب الأصفر الكلاسيكية، و الألماس البراق، و الأحجار الملونة، واللآلئ، وحتى القطع المستوحاة من التراث العربي، لتؤكد أن الأناقة الحقيقية تكمن في حسن تنسيق التفاصيل، وما يلفت الأنظار أيضًا هو قدرتها على اختيار القطع التي تنسجم مع طبيعة المناسبة والأزياء التي تعتمدها، سواء كانت…"]','الثقافة','فنون وتراث','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%A3%D9%86%D8%A7%