INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('29c83b7e-e7e2-45ef-9e4f-0fcd5852b72d','imported-29c83b7e-e7e2-45ef-9e4f-0fcd5852b72d','مجوهرات بريانكا شوبرا. إبداعات أفخم العلامات تبرز ذوقها الراقي في اختيار القطع الفاخرة','مجوهرات بريانكا شوبرا إبداعات أفخم العلامات تبرز ذوقها الراقي في اختيار القطع الفاخرة','تُعد نجمة بوليود بريانكا شوبرا Priyanka Chopra واحدة من أكثر النجمات اللواتي ينجحن في توظيف المجوهرات الراقية لإكمال إطلالاتهن على السجادة الحمراء، فاختياراتها لا تعتمد على حجم القطع أو قيمتها فحسب، بل ترتكز على تنسيق كل تصميم بما ينسجم مع الأزياء والمناسب…','["بين العقود المرصعة بالألماس والزمرد، والأقراط الماسية اللافتة، وخاتم خطوبتها الأيقوني من تيفاني آند كو Tiffany & Co، استطاعت بريانكا أن ترسخ أسلوبًا يجمع بين الفخامة الكلاسيكية واللمسات العصرية الجريئة، وفي السطور التالية نستعرض أبرز مجوهراتها التي لا تزال عالقة في الأذهان. لفتنا هذا العقد الفخم الذي أدرجته بريانكا شوبرا Priyanka Chopra من بولغاري Bvlgari بأحدث إطلالاتها خلال حضورها حفل Gold Gala الذي أُقيم في 9…"]','أخبار السعودية','فنون وتراث','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%A3%D9%86%D8%A7%D9%82%D8%A9/%D9%85%D8%AC%D9%88%D9%87%D8%B1%D8%A7%D8%AA-%D9%88%D8%B3%D8%A7%D8%B9%D8%A7%D8%AA/1836747-%D9%85%D8%AC%D9%88%D9%87%D8%B1%D8%A7%D8%AA-%D8%A8%D8%B1%D9%8A%D8%A7%D9%86%D9%83%D8%A7-%D8%B4%D9%88%D8%A8%D8%B1%D8%A7-%D8%A5%D8%A8%D8%AF%D8%A7%D8%B9%D8%A7%D8%AA-%D8%A3%D9%81%D8%AE%D9%85-%D8%A7%D9%84%D8%B9%D9%84%D8%A7%D9%85%D8%A7%D8%AA-%D8%AA%D8%A8%D8%B1%D8%B2-%D8%B0%D9%88%D9%82%D9%87%D8%A7-%D8%A7%D9%84%D8%B1%D8%A7%D9%82%D9%8A-%D9%81%D9%8A','https://www.sayidaty.net/%D8%A3%D9%86%D8%A7%D9%82%D8%A9/%D9%85%D8%AC%D9%88%D9%87%D8%B1%D8%A7%D8%AA-%D9%88%D8%B3%D8%A7%D8%B9%D8%A7%D8%AA/1836747-%D9%85%D8%AC%D9%88%D9%87%D8%B1%D8%A7%D8%AA-%D8%A8%D8%B1%D9%8A%D8%A7%D9%86%D9%83%D8%A7-%D8%B4%D9%88%D8%A8%D8%B1%D8%A7-%D8%A5%D8%A8%D8%AF%D8%A7%D8%B9%D8%A7%D8%AA-%D8%A3%D9%81%D8%AE%D9%85-%D8%A7%D9%84%D8%B9%D9%84%D8%A7%D9%85%D8%A7%D8%AA-%D8%AA%D8%A8%D8%B1%D8%B2-%D8%B0%D9%88%D9%82%D9%87%D8%A7-%D8%A7%D9%84%D8%B1%D8%A7%D9%82%D9%8A-%D9%81%D9%8A','','','هاجر حاتم','','2026-07-18T06:18:00.000Z',NULL,'2026-07-20T19:45:39.386Z','https://static.sayidaty.net/styles/681x999/public/2026-07/GettyImages-2275399770_0.jpg.webp?VersionId=zWI6NA09cyZ9kI_LEqtE4GB1QlrOIdKr','/api/media/29c83b7e-e7e2-45ef-9e4f-0fcd5852b72d','/api/media/29c83b7e-e7e2-45ef-9e4f-0fcd5852b72d?variant=thumbnail','مجوهرات بريانكا شوبرا.. إبداعات أفخم العلامات تبرز ذوقها الراقي في اختيار القطع الفاخرة',681,999,'valid','published','archived','valid',35,'4485e6109593fffbce9afd1c63fe48afb38e7a616e2315b42843685c5e962944','6ac56126ab2b1219ede5ae3eabb8613b09065f360ee6f1065b4288a268cad3bb',NULL,'2026-07-20T14:34:52.474Z','2026-10-07T20:24:27.209Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["فنون وتراث"]','["فنون وتراث"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active',NULL,NULL