INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e26c54f1-3dac-418a-b5ca-9d2b748c72c5','imported-e26c54f1-3dac-418a-b5ca-9d2b748c72c5','إثراء يطلق معرض الكتاب للأطفال في نسخته السادسة وسوريا ضيف شرف','إثراء يطلق معرض الكتاب للأطفال في نسخته السادسة وسوريا ضيف شرف','أعلن مركز الملك عبد العزيز الثقافي العالمي (إثراء)، إطلاق مبادرة أرامكو السعودية- معرض الكتاب للأطفال في دورته السادسة وذلك في الفترة من 20 إلى 25 يوليو 2026م، وحلّت الجمهورية العربية السورية كدولة ضيف هذا العام، ويحقق المعرض رسالة إثراء المتمثلة على إلهام…','["افتتح القائم بأعمال سفارة الجمهورية العربية السورية لدى المملكة العربية السعودية محسن مهباش، الجناح السوري الذي يضم أكثر من 250 عنوانًا تتمحور في أدب الطفل، وأوضحت السفارة السورية في تصريح لها، أن استضافة سورية كضيف شرف في هذه الدورة يأتي تقديرًا للمكانة التي يحتلها أدب الطفل السوري، ولإسهاماته الرائدة في تأسيس وتطوير أدب الطفل العربي الحديث وإثراء الثقافة العربية الموجّهة للأطفال، الذين يمثلون صُنّاع المستقبل.…"]','الثقافة','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%A8%D9%84%D8%B3/%D8%AB%D9%82%D8%A7%D9%81%D8%A9-%D9%88%D9%81%D9%86%D9%88%D9%86/1836861-%D8%A5%D8%AB%D8%B1%D8%A7%D8%A1','https://www.sayidaty.net/%D8%A8%D9%84%D8%B3/%D8%AB%D9%82%D8%A7%D9%81%D8%A9-%D9%88%D9%81%D9%86%D9%88%D9%86/1836861-%D8%A5%D8%AB%D8%B1%D8%A7%D8%A1','','','نت','','2026-07-20T18:17:03.000Z',NULL,'2026-07-21T18:16:31.704Z','https://static.sayidaty.net/styles/681x999/public/2026-07/501908.jpg.webp?VersionId=mA2DiqKdsWEtM78FCMC442mbOYZ6ZBdr','/api/media/e26c54f1-3dac-418a-b5ca-9d2b748c72c5','/api/media/e26c54f1-3dac-418a-b5ca-9d2b748c72c5?variant=thumbnail','إثراء يطلق معرض الكتاب للأطفال في نسخته السادسة وسوريا ضيف شرف',681,999,'valid','published','archived','valid',99,'b383799dc40ed60aa0f64faa1e752a230df4bfb9ac9c36330105b5f59efa53e9','2c32e17b88cd11cb488587d10c24c53928bf4d1bdc14bc0c46ee5efd8316b058',NULL,'2026-07-20T19:40:08.956Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","سوريا"]','["الثقافة والفنون"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"السياسة","score":1.5},{"category":"المناطق","score":0}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d28375b4-02bb-4a1a-a49e-e03043bd49eb','imported-d28375b4-02bb-4a1a-a49e-e03043bd49eb','الأحمر كما تختاره الملكة رانيا. إطلالات تنبض بالأناقة والفخامة','الأحمر كما تختاره الملكة رانيا إطلالات تنبض بالأناقة والفخامة','تميل الملكة رانيا العبد الله إلى اعتماد اللون الأحمر في العديد من إطلالاتها، وهو ما تعكسه صورها الرسمية التي تزخر بإطلالات أنيقة تتدرج بين الأحمر الياقوتي والكرزي والبرغندي.','["ويمثل هذا اللون أحد أبرز الخيارات في خزانتها، إذ يعكس أسلوبها الراقي في تنسيق الأزياء. لا يقتصر الأحمر على كونه لوناً جذاباً، بل يحمل دلالات ترتبط بالقوة والثقة والجرأة. فمن الناحية النفسية، يُعرف بقدرته على لفت الأنظار وإضفاء إحساس بالحيوية والطاقة، لذلك غالبًا ما يُعتمد في عالم الموضة لإحداث انطباع مميز وإبراز الشخصية بأناقة."]','الثقافة','فنون وتراث','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%A3%D9%86%D8%A7%D9%82%D8%A9/%D8%A5%D8%B7%D9%84%D8%A7%D9%84%D8%A7%D8%AA-%D8%A7%D9%84%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/1836810-%D8%A3%D8%B3%D8%B1%D8%A7%D8%B1-%D8%AA%D9%86%D8%B3%D9%8A%D9%82-%D8%A7%D9%84%D9%85%D9%84%D9%83%D8%A9-%D8%B1%D8%A7%D9%86%D9%8A%D8%A7-%D9%84%D9%84%D9%88%D9%86-%D8%A7%D9%84%D8%A3%D8%AD%D9%85%D8%B1','https://www.sayidaty.net/%D8%A3%D9%86%D8%A7%D9%82%D8%A9/%D8%A5%D8%B7%D9%84%D8%A7%D9%84%D8%A7%D8%AA-%D8%A7%D9%84%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/1836810-%D8%A3%D8%B3%D8%B1%D8%A7%D8%B1-%D8%AA%D9%86%D8%B3%D9%8A%D9%82-%D8%A7%D9%84%D9%85%D9%84%D9%83%D8%A9-%D8%B1%D8%A7%D9%86%D9%8A%D8%A7-%D9%84%D9%84%D9%88%D9%86-%D8%A7%D9%84%D8%A3%D8%AD%D9%85%D8%B1','','','كارلا باسيل','','2026-07-21T05:21:08.000Z',NULL,'2026-07-21T18:16:29.414Z','https://static.sayidaty.net/styles/681x999/public/2026-07/480903_2.jpg.webp?VersionId=_qMzzO.1un0RttxpTaM.cRavG_2Lt5.H','/api/media/d28375b4-02bb-4a1a-a49e-e03043bd49eb','/api/media/d28375b4-02bb-4a1a-a49e-e03043bd49eb?variant=thumbnail','الأحمر كما تختاره الملكة رانيا.. إطلالات تنبض بالأناقة والفخامة',681,999,'valid','published','archived','valid',41,'002c741b81b8562a9019c416cb7eaaee0fa904044a99c583548c7cf656e788ea','f066a535854a7734754a2e1afcca3c6028e41953d493ec226b687468d457aaab',NULL,'2026-07-21T18:08:12.659Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["فنون وتراث","الطاقة والنفط","الثقافة والفنون"]','["فنون وتراث","الطاقة والنفط","الثقافة والفنون"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ccab8825-d24e-4ae2-bfe4-b0c53f4356bc','imported-ccab8825-d24e-4ae2-bfe4-b0c53f4356bc','أميرة أديب تكشف تفاصيل معاناتها من الاكتئاب: منظوري عن الحياة اختلف تماماً','أميرة أديب تكشف تفاصيل معاناتها من الاكتئاب منظوري عن الحياة اختلف تماما','كشفت الفنانة المصرية أميرة أديب عن تفاصيل مؤثرة من رحلتها مع مرض الاكتئاب، مؤكدة أنها عاشت واحدة من أصعب الفترات في حياتها على مدار عامين كاملين، عانت خلالها من العزلة وفقدان الشغف، ووصلت إلى مرحلة راودتها فيها أفكار لإيذاء نفسها، قبل أن تاستطاع من تجاوز تلك الأزمة بمساعدة الأطب…','["أضافت في تصريحاتها بأنها طالما عُرِفت بشخصيتيها الإيجابية والبسيطة التي تُصدّر الأمل والمرح للجميع، وكان المتابعون يخبرونها دائماً بأنها مصدر طاقتهم الإيجابية، لكن الواقع كان مختلفاً. حيث عاشت عامين كاملين وهي لا تستطيع النهوض من الفراش. كشفت أميرة أديب عن أخطر ما مرت به خلال تلك الفترة، مؤكدة أن أفكاراً لإيذاء نفسها كانت تراودها، لكنها لم تنفذها بفضل تمسكها بإيمانها، حيث قالت: منظوري عن الحياة اختلف تماماً."]','أخبار السعودية','تنمية','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1-%D8%A7%D9%84%D8%B9%D8%B1%D8%A8/1836895-%D8%A3%D9%85%D9%8A%D8%B1%D8%A9-%D8%A3%D8%AF%D9%8A%D8%A8-%D8%AA%D9%83%D8%B4%D9%81-%D8%AA%D9%81%D8%A7%D8%B5%D9%8A%D9%84-%D9%85%D8%B9%D8%A7%D9%86%D8%A7%D8%AA%D9%87%D8%A7-%D9%85%D9%86-%D8%A7%D9%84%D8%A7%D9%83%D8%AA%D8%A6%D8%A7%D8%A8','https://www.sayidaty.net/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1-%D8%A7%D9%84%D8%B9%D8%B1%D8%A8/1836895-%D8%A3%D9%85%D9%8A%D8%B1%D8%A9-%D8%A3%D8%AF%D9%8A%D8%A8-%D8%AA%D9%83%D8%B4%D9%81-%D8%AA%D9%81%D8%A7%D8%B5%D9%8A%D9%84-%D9%85%D8%B9%D8%A7%D9%86%D8%A7%D8%AA%D9%87%D8%A7-%D9%85%D9%86-%D8%A7%D9%84%D8%A7%D9%83%D8%AA%D8%A6%D8%A7%D8%A8','','','محمد المعصراوى','','2026-07-21T16:24:29.000Z',NULL,'2026-07-21T18:16:31.098Z','https://static.sayidaty.net/styles/681x999/public/2026-07/502041.jpg.webp?VersionId=FJzjG7Fpd52It24nGkAgHNaRiAbB.aP1','/api/media/ccab8825-d24e-4ae2-bfe4-b0c53f4356bc','/api/media/ccab8825-d24e-4ae2-bfe4-b0c53f4356bc?variant=thumbnail','أميرة أديب تكشف تفاصيل معاناتها من الاكتئاب: منظوري عن ...',681,999,'valid','published','archived','valid',35,'0e82449df237aea3908c67f598730bc5d28a9d9eaebb5090c71a95ab2cbdd77a','ca9e50c20660cd3ebae5ce97a01633afe4a8ba23684db7de7c744d13a8d9f748',NULL,'2026-07-21T18:08:15.395Z','2026-10-07T20:24:27.216Z','','',0,0,'saudi_national','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["تنمية"]','[]','manual_approved','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3d71a0ec-239c-40e6-a214-2267d20e1c4a','imported-3d71a0ec-239c-40e6-a214-2267d20e1c4a','تامر حسني يُشوّق جمهوره لألبوم مش هتكرر بـ لغة الأرقام. ما القصة','تامر حسني يشوق جمهوره لألبوم مش هتكرر بـ لغة الأرقام ما القصة','حمّس الفنان تامر حسني، جمهوره لألبومه الجديد "مش هتكرر" المُرتقب طرحه خلال الأيام القليلة المُقبلة ضمن موسم أغاني صيف 2026، بطريقة مبتكرة، حيث كشف عن أسماء الأغاني بأسلوب غير تقليدي يستند إلى "لغة الأرقام" والشفرات التفاعلية لإثارة فضول جمهوره قبل الطرح ال…','["تأتي القائمة المتوقعة لأسماء الأغاني الـ14 كالتالي: \"بنت مين\"، \"وش الخير\"، \"يا خسارتنا\"، \"ما تيجي\"، \"مولعينها\"، \"عايزك توعديني\"، \"قال فاكرني\"، \"مش هتكرر\"، \"في القلب\"، \"ماتمشيش\"، \"بعيش على الذكرى\"، \"دهب قشرة\"، \"متأثر بغيابه\"، وأخيراً \"اتحامى فيّا\". بتوقيع تامر حسني. ياسين رشدي يفاجئ نور عمرو دياب بأغنية تحمل اسمها."]','أخبار السعودية','فنون وتراث','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1-%D8%A7%D9%84%D8%B9%D8%B1%D8%A8/1836894-%D8%A3%D9%84%D8%A8%D9%88%D9%85-%D8%AA%D8%A7%D9%85%D8%B1-%D8%AD%D8%B3%D9%86%D9%8A','https://www.sayidaty.net/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1-%D8%A7%D9%84%D8%B9%D8%B1%D8%A8/1836894-%D8%A3%D9%84%D8%A8%D9%88%D9%85-%D8%AA%D8%A7%D9%85%D8%B1-%D8%AD%D8%B3%D9%86%D9%8A','','','أحمد حسين','','2026-07-21T16:10:41.000Z',NULL,'2026-07-21T18:16:31.253Z','https://static.sayidaty.net/styles/681x999/public/2026-07/502078.jpg.webp?VersionId=3XKVrQpYZA9uS0BDOqkjdm9mrD_WNhWV','/api/media/3d71a0ec-239c-40e6-a214-2267d20e1c4a','/api/media/3d71a0ec-239c-40e6-a214-2267d20e1c4a?variant=thumbnail','تامر حسني يُشوّق جمهوره لألبوم مش هتكرر بـ لغة الأرقام....',681,999,'valid','published','archived','valid',35,'ff47688f6e7f39df14c8039c4eb4a7840a3d635b6f2910a878decbcf15949d26','f117e5589d028aa1c81a19bf9703754d11937cec78914698be0ccb2c5e65e694',NULL,'2026-07-21T18:08:15.969Z','2026-10-07T20:24:27.218Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["فنون وتراث"]','["فنون وتراث"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('11ac4d48-8cae-4646-86fa-fb784a1784cd','imported-11ac4d48-8cae-4646-86fa-fb784a1784cd','حين تلتقي الموضة بالسينما. قصة شغف تتجاوز حدود الأزياء','حين تلتقي الموضة بالسينما قصة شغف تتجاوز حدود الأزياء','لطالما ارتبطت دورُ الأزياءِ الفاخرة بصناعةِ الأفلام السينمائيَّة، بل وسعت إلى تولي إنتاجها أيضاً، لتتجاوزَ المضمون التقليدي، وتخلق قصصاً عاطفيَّةً ترتبطُ بهويَّتها.','["من خلال تمويلِ الأفلام، أو إنتاجِ أعمالٍ وثائقيَّةٍ قصيرةٍ، تسعى علاماتٌ تجاريَّةٌ مثل سان لوران Saint Laurent، وغوتشي Gucci، وشانيل Chanel، وبرادا Prada إلى ترسيخِ مكانتها بوصفها «صانعةَ ثقافةٍ» لا مجرَّد علامةٍ لتصميمِ الأزياء. في التالي، نُعرِّفكم على أبرزِ الأفلامِ المرتبطةِ بعالمِ الموضة، والدوافعِ التي حملت الدورَ إلى إنتاجها، كما نتوقَّفُ عند رأي المخرجِ جوزيف حنا حول ذلك، ونستعرضُ تجربته في إخراجِ أفلامٍ…"]','الثقافة','أدب ونشر','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%A3%D9%86%D8%A7%D9%82%D8%A9/%D8%A3%D8%B2%D9%8A%D8%A7%D8%A1/1836717-%D8%A7%D9%84%D8%B2%D9%8A-%D8%A8%D8%B7%D9%84-%D8%A7%D9%84%D9%82%D8%B5%D8%A9','https://www.sayidaty.net/%D8%A3%D9%86%D8%A7%D9%82%D8%A9/%D8%A3%D8%B2%D9%8A%D8%A7%D8%A1/1836717-%D8%A7%D9%84%D8%B2%D9%8A-%D8%A8%D8%B7%D9%84-%D8%A7%D9%84%D9%82%D8%B5%D8%A9','','','كارلا باسيل','','2026-07-21T10:00:00.000Z',NULL,'2026-07-21T18:16:33.615Z','https://static.sayidaty.net/styles/681x999/public/2026-07/501403.jpg.webp?VersionId=AvlPAvn.I_JKPZ2Mq1Yt9_hrcRzrsMVL','/api/media/11ac4d48-8cae-4646-86fa-fb784a1784cd','/api/media/11ac4d48-8cae-4646-86fa-fb784a1784cd?variant=thumbnail','حين تلتقي الموضة بالسينما... قصة شغف تتجاوز حدود الأزياء',681,999,'valid','published','archived','valid',53,'7102835e00a16de57a3f98a4fc756c86761f7fb11abda63389ed38b717f09980','672a2b43eab27a05c31a20b729ead0e74e0b0d33472eb2f7991b794e26c8348a',NULL,'2026-07-21T18:08:18.900Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["أدب ونشر","الثقافة والفنون"]','["أدب ونشر","الثقافة والفنون"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('187c5235-282a-44d7-ac4b-e151558ddc6b','imported-187c5235-282a-44d7-ac4b-e151558ddc6b','لاعبة التنس المحترفة المصرية ميار شريف: انتصارات متتالية ووجهة واحدة. القمة','لاعبة التنس المحترفة المصرية ميار شريف انتصارات متتالية ووجهة واحدة القمة','لا تُقاس رحلةُ البطلاتِ بعددِ الألقابِ في رصيدهن فحسب، بل وأيضاً بالقصصِ التي تقفُ خلفَ كلِّ انتصارٍ يُحقِّقنه، والصلابةِ التي تُبنى من الهزائمِ قبل النجاحات.','["هذا ما تبدو عليه المصريَّةُ ميار شريف، لاعبةُ التنس والملقبة بـ «فتاة مصر الذهبية»، التي صنعت اسمَها في واحدةٍ من أكثر الرياضاتِ الفرديَّةِ قسوةً، لتُصبح رمزاً للإصرارِ والطموحِ العربي على الساحةِ العالميَّة. في هذا اللقاءِ الخاصِّ معها، تفتحُ ميار قلبها لـ «سيدتي»، فتتحدَّثُ عن بداياتها مع التنس، والدورِ الكبيرِ الذي لعبته شقيقتُها وعائلتها في رسمِ ملامحِ مسيرتها، كما تستعيدُ أبرزَ محطَّاتها الاحترافيَّةِ من…"]','الرياضة','طيران','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%A8%D9%84%D8%B3/%D9%82%D8%B5%D8%B5-%D9%85%D9%84%D9%87%D9%85%D8%A9/1836885-%D9%84%D8%A7%D8%B9%D8%A8%D8%A9-%D8%A7%D9%84%D8%AA%D9%86%D8%B3-%D8%A7%D9%84%D9%85%D8%B5%D8%B1%D9%8A%D8%A9-%D9%85%D9%8A%D8%A7%D8%B1-%D8%B4%D8%B1%D9%8A%D9%81','https://www.sayidaty.net/%D8%A8%D9%84%D8%B3/%D9%82%D8%B5%D8%B5-%D9%85%D9%84%D9%87%D9%85%D8%A9/1836885-%D9%84%D8%A7%D8%B9%D8%A8%D8%A9-%D8%A7%D9%84%D8%AA%D9%86%D8%B3-%D8%A7%D9%84%D9%85%D8%B5%D8%B1%D9%8A%D8%A9-%D9%85%D9%8A%D8%A7%D8%B1-%D8%B4%D8%B1%D9%8A%D9%81','','','المجلة','','2026-07-21T18:00:00.000Z',NULL,'2026-07-21T18:16:28.141Z','https://static.sayidaty.net/styles/681x999/public/2026-07/502005.jpg.webp?VersionId=v2P7ZrQPwZmdMUjLBFPqWqKT7OI8xvFr','/api/media/187c5235-282a-44d7-ac4b-e151558ddc6b','/api/media/187c5235-282a-44d7-ac4b-e151558ddc6b?variant=thumbnail','لاعبة التنس المحترفة المصرية ميار شريف: انتصارات متتالية ووجهة واحدة.. القمة',681,999,'valid','published','archived','valid',50,'071a9b83f436537a0656ae2c5da1faaff8dec4e1753199041c09913131b9158c','fbef6df9f614be88f3d7a5b5f11fa14128e9ad430ca5e0fbaef8565435d2e9a9',NULL,'2026-07-21T18:16:28.150Z','2026-10-07T20:24:27.223Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["طيران","الاقتصاد والأسواق","الرياض"]','["الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"السفر","score":3},{"category":"المناطق","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('12f52569-c803-4ccc-9fca-991735d6cd1a','news-12f52569-c803-4ccc-9fca-991735d6cd1a','النفط ينخفض بشكل طفيف بعد أكبر قفزة يومية في أسبوعين','النفط ينخفض بشكل طفيف بعد اكبر قفزه يوميه في اسبوعين','تراجعت أسعار النفط اليوم الخميس بشكل طفيف، بعد أكبر قفزة يومية في أكثر من أسبوعين، في وقت شنت أمريكا ضربات على أهداف عسكرية في إيران.','["مزيج \"برنت\" تداول عند 89 دولارا للبرميل بعدما ارتفع 8% الجلسة السابقة، في حين كان خام \"نايمكس\" دون 84 دولارا بعدما ارتفع 7%.","أسعار النفط تقفز 7% وسط تصاعد التوتر في الشرق الأوسط","قفزت أسعار النفط 7% اليوم الأربعاء وسط تبدد آمال إنهاء وشيك لحرب...","أمريكا شنت موجة جديدة من الضربات بعد عدة أيام من الهدوء، وقالت أنها تهدف إلى تقليص التهديدات التي تشكلها إيران ووكلائها على قواتها وحلفائها والشحن التجاري\\\\\\\"، مشيرة إلى أن الأهداف شملت مراكز قيادة، ومنشآت صواريخ ومسيرات، ومواقع مراقبة ودفاع ساحلية، وقدرات البحرية.","وجاءت هذه الضربات كرد على محاولات الهجوم الإيرانية التي استهدفت القوات الأميركية المتمركزة في الشرق الأوسط أمس، وبعدما توعد الرئيس الأميركي بتنفيذ ضربات \\\\\\\"قوية\\\\\\\" ضد إيران.","يبدو أن صراع واشنطن وطهران مرشح للاستمرار لأشهر، مع عجز الطرفين عن كسر الجمود بشأن مضيق هرمز والتوصل لاتفاق دائم لوقف إطلاق النار، وفقا لعدد من المسؤولين الحاليين والسابقين.","في أمريكا سجلت مخزونات الخام التجارية أكبر انخفاض منذ منتصف يونيو، ما عزز مؤشرات شح السوق الفعلية بعد أشهر من الحرب، وانخفض الاحتياطي البترولي الاستراتيجي للأسبوع الـ 18، ليبلغ أدنى مستوى منذ 1983.","كبيرة تجار الطاقة في مجموعة \\\\\\\"سي آي بي سي\\\\\\\" لإدارة الثروات الخاصة ريبيكا بابين قالت \\\\\\\"قد لا تكون المخزونات هي العامل الرئيسي، لكن من المرجح أن يجذب السحب من مخزونات الخام، الأكبر من المتوقع، واقتراب المخزونات التجارية من مستوى 400 مليون برميل، مزيدا من الاهتمام\\\\\\\"."]','الطاقة والصناعة','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82/%D8%A7%D9%84%D9%86%D9%81%D8%B7-%D9%8A%D9%86%D8%AE%D9%81%D8%B6-%D8%A8%D8%B4%D9%83%D9%84-%D8%B7%D9%81%D9%8A%D9%81-%D8%A8%D8%B9%D8%AF-%D8%A3%D9%83%D8%A8%D8%B1-%D9%82%D9%81%D8%B2%D8%A9-%D9%8A%D9%88%D9%85%D9%8A%D8%A9-%D9%81%D9%8A-%D8%A3%D8%B3%D8%A8%D9%88%D8%B9%D9%8A%D9%86-12651','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82/%D8%A7%D9%84%D9%86%D9%81%D8%B7-%D9%8A%D9%86%D8%AE%D9%81%D8%B6-%D8%A8%D8%B4%D9%83%D9%84-%D8%B7%D9%81%D9%8A%D9%81-%D8%A8%D8%B9%D8%AF-%D8%A3%D9%83%D8%A8%D8%B1-%D9%82%D9%81%D8%B2%D8%A9-%D9%8A%D9%88%D9%85%D9%8A%D8%A9-%D9%81%D9%8A-%D8%A3%D8%B3%D8%A8%D9%88%D8%B9%D9%8A%D9%86-12651','','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82/%D8%A7%D9%84%D9%86%D9%81%D8%B7-%D9%8A%D9%86%D8%AE%D9%81%D8%B6-%D8%A8%D8%B4%D9%83%D9%84-%D8%B7%D9%81%D9%8A%D9%81-%D8%A8%D8%B9%D8%AF-%D8%A3%D9%83%D8%A8%D8%B1-%D9%82%D9%81%D8%B2%D8%A9-%D9%8A%D9%88%D9%85%D9%8A%D8%A9-%D9%81%D9%8A-%D8%A3%D8%B3%D8%A8%D9%88%D8%B9%D9%8A%D9%86-12651','','السعودية','2026-07-30T05:03:00.000Z','2026-07-30T05:03:26.000Z','2026-07-30T06:04:00.811Z','','','/api/media/fallback/%D8%A7%D9%84%D8%B3%D9%8A%D8%A7%D8%B3%D8%A9','النفط ينخفض بشكل طفيف بعد أكبر قفزة يومية في أسبوعين',NULL,NULL,'fallback','review','archived','valid',79,'4d849e197b428ee2f4f6fc5f9f5f51c4c738f6344b1dac4bd0eeb9d85b75af9d','39069ca93f1d59f0103a0cbde607e0cffe5129bfa4fe43021e528b257795a16e',NULL,'2026-07-30T06:04:00.812Z','2026-08-24T20:31:35.610Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والصناعة","الطاقة والنفط","إيران","الشرق الأوسط","ينخفض بشكل","النفط ينخفض","بشكل طفيف أكبر","طفيف أكبر قفزة"]','["الطاقة والصناعة","الطاقة والنفط","الشرق الأوسط","ينخفض بشكل","النفط ينخفض","بشكل طفيف أكبر"]','classified','','[]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b33311e3-06bb-4139-958f-e5d4790747b7','news-b33311e3-06bb-4139-958f-e5d4790747b7','الذهب والفضة يرتفعان بعد الإبقاء على الفائدة دون تغيير','الذهب والفضه يرتفعان بعد الابقاء علي الفائده دون تغيير','ارتفعت أسعار المعادن النفيسة بنحو 1% اليوم الخميس بعدما أبقى الفيدرالي أسعار الفائدة دون تغيير، رغم تصاعد مخاطر التضخم الناجمة عن الحرب في الشرق الأوسط.','["صعد الذهب ليلامس مستوى 4100 دولار للأونصة، فيما قفزت الفضة إلى 58.28 دولار للأونصة.","\\\\\\\"الفيدرالي\\\\\\\" يثبت الفائدة للمرة الخامسة مع استمرار مراقبة التضخم","أبقى مجلس الاحتياطي الفيدرالي الأمريكي، اليوم، سعر الفائدة...","صوت الفيدرالي بأغلبية 9 أصوات مقابل 3 لمصلحة الإبقاء على الفائدة دون تغيير، رغم أن انقسام التصويت أشار إلى تزايد قناعة بعض صناع السياسة بأن ارتفاع تكاليف الاقتراض، الذي يشكل عادة عامل ضغط على الذهب الذي لا يدر عائدا، قد يكون ضروريا لكبح ضغوط الأسعار المتجددة.","أكد رئيس الفيدرالي كيفن وارش، أن القرار الأخير لم يكن مؤشرا على التراخي في البنك المركزي، وقال \\\\\\\"إذا ظل التضخم مرتفعا طوال فترة التوقعات، فقد تكون أسعار الفائدة بالفعل جزءا من ذلك الحل، لكنني لا أقول إنها الحل بمعزل عن غيرها\\\\\\\".","المركزي الصيني يرفع مشتريات الذهب لأعلى مستوى منذ أكتوبر 2023","واصل البنك المركزي الصيني شراء الذهب خلال يونيو، مسجلاً أطول...","انخفض الذهب بأكثر من الخمس منذ اندلاع حرب أمريكا وإيران قبل 5 أشهر، إذ غذت أسعار الطاقة المرتفعة ضغوط التضخم وزادت احتمال بقاء الفائدة مرتفعة لفترة أطول، مع ذلك ظل المعدن قريبا من مستوى 4000 دولار للأونصة منذ أواخر يونيو، بدعم موجة الشراء عند انخفاض الأسعار."]','الاقتصاد','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82/%D8%A7%D9%84%D8%B0%D9%87%D8%A8-%D9%8A%D8%B1%D8%AA%D9%81%D8%B9-%D9%88%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82-%D8%AA%D9%82%D9%8A%D9%85-%D8%B1%D8%B3%D8%A7%D9%84%D8%A9-%D8%B1%D8%A6%D9%8A%D8%B3-%D8%A7%D9%84%D9%85%D8%B1%D9%83%D8%B2%D9%8A-%D8%A7%D9%84%D8%A3%D9%85%D8%B1%D9%8A%D9%83%D9%8A-%D8%A8%D8%B4%D8%A3%D9%86-%D8%A7%D9%84%D8%AA%D8%B6%D8%AE%D9%85-12652','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82/%D8%A7%D9%84%D8%B0%D9%87%D8%A8-%D9%8A%D8%B1%D8%AA%D9%81%D8%B9-%D9%88%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82-%D8%AA%D9%82%D9%8A%D9%85-%D8%B1%D8%B3%D8%A7%D9%84%D8%A9-%D8%B1%D8%A6%D9%8A%D8%B3-%D8%A7%D9%84%D9%85%D8%B1%D9%83%D8%B2%D9%8A-%D8%A7%D9%84%D8%A3%D9%85%D8%B1%D9%8A%D9%83%D9%8A-%D8%A8%D8%B4%D8%A3%D9%86-%D8%A7%D9%84%D8%AA%D8%B6%D8%AE%D9%85-12652','','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82/%D8%A7%D9%84%D8%B0%D9%87%D8%A8-%D9%8A%D8%B1%D8%AA%D9%81%D8%B9-%D9%88%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82-%D8%AA%D9%82%D9%8A%D9%85-%D8%B1%D8%B3%D8%A7%D9%84%D8%A9-%D8%B1%D8%A6%D9%8A%D8%B3-%D8%A7%D9%84%D9%85%D8%B1%D9%83%D8%B2%D9%8A-%D8%A7%D9%84%D8%A3%D9%85%D8%B1%D9%8A%D9%83%D9%8A-%D8%A8%D8%B4%D8%A3%D9%86-%D8%A7%D9%84%D8%AA%D8%B6%D8%AE%D9%85-12652','','السعودية','2026-07-30T04:41:00.000Z','2026-07-30T04:44:26.000Z','2026-07-30T06:04:01.099Z','','','/api/media/fallback/%D8%A7%D9%84%D8%B3%D9%8A%D8%A7%D8%B3%D8%A9','الذهب والفضة يرتفعان بعد الإبقاء على الفائدة دون تغيير',NULL,NULL,'fallback','review','archived','valid',79,'32f1e40d3f7143a91d0cc7cc78e567edd5a93c6af6d701665e9eacec6785b0ae','8f9f186bfdb2f29785c064a04b59e175f27f68b5f3b34017ff589269c7fa445a',NULL,'2026-07-30T06:04:01.099Z','2026-08-24T20:30:03.550Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","البنك المركزي وقال إذا ظل","رئيس الفيدرالي كيفن وارش أن","مجلس الاحتياطي الفيدرالي الأمريكي اليوم","الطاقة والنفط","الاقتصاد والأسواق","السياسة والعلاقات الدولية","إيران"]','["البنك المركزي وقال إذا ظل","رئيس الفيدرالي كيفن وارش أن","مجلس الاحتياطي الفيدرالي الأمريكي اليوم","الطاقة والنفط","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','classified','','[]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
