INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7a9b04eb-77c2-4d59-8aac-5d9c04ba9449','news-7a9b04eb-77c2-4d59-8aac-5d9c04ba9449','صندوق النقد: اقتصاد السعودية أثبت صمودا مع نمو متوقع 5.5% في 2027','صندوق النقد اقتصاد السعوديه اثبت صمودا مع نمو متوقع 5 5 في 2027','أكد صندوق النقد الدولي أن الاقتصاد السعودي يثبت صموده أمام التوترات الجيوسياسية الأخيرة في المنطقة، متوقعا أن يحقق نموا بـ 5.5% العام المقبل، مع تعافي النشاطين النفطي وغير النفطي واستمرار دعم الاستهلاك والاستثمار للنمو.','["صندوق النقد قال في تقرير حول مشاورات المادة الرابعة لعام 2026 اليوم الأربعاء إن السعودية تمكنت من التعامل بكفاءة مع الصدمات الخارجية بفضل الإصلاحات الاقتصادية والهيكلية التي نفذتها ضمن رؤية السعودية 2030، والسياسات الاقتصادية السليمة، والهوامش المالية القوية، والاستثمارات في البنية التحتية للطاقة والخدمات اللوجستية، إلى جانب كفاءة إدارة الأزمات.","وتوقع أن الذكاء الاصطناعي قد يرفع نمو الناتج المحلي الإجمالي السعودي حتى 6% خلال العقد القادم، مشيرا إلى تصدر السعودية عالميًا في تبني الذكاء الاصطناعي عبر عدة قطاعات.","لفت صندوق النقد كذلك إلى أن إستراتيجية صندوق الاستثمارات العامة السعودي الجديدة للفترة 2026-2030 تعزز دور القطاع الخاص.","بحسب صندوق النقد، فإن قطاع المنشآت الصغيرة والمتوسطة يساهم بنحو 23% من الناتج المحلي الإجمالي السعودي، بينما ترتفع مشاركة المرأة السعودية في القوى العاملة إلى 35%."]','الاقتصاد','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D8%B5%D9%86%D8%AF%D9%88%D9%82-%D8%A7%D9%84%D9%86%D9%82%D8%AF-%D8%A7%D9%82%D8%AA%D8%B5%D8%A7%D8%AF-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%A3%D8%AB%D8%A8%D8%AA-%D8%B5%D9%85%D9%88%D8%AF%D8%A7-%D9%85%D8%B9-55-%D9%86%D9%85%D9%88-%D9%85%D8%AA%D9%88%D9%82%D8%B9-%D9%81%D9%8A-2027-12641','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D8%B5%D9%86%D8%AF%D9%88%D9%82-%D8%A7%D9%84%D9%86%D9%82%D8%AF-%D8%A7%D9%82%D8%AA%D8%B5%D8%A7%D8%AF-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%A3%D8%AB%D8%A8%D8%AA-%D8%B5%D9%85%D9%88%D8%AF%D8%A7-%D9%85%D8%B9-55-%D9%86%D9%85%D9%88-%D9%85%D8%AA%D9%88%D9%82%D8%B9-%D9%81%D9%8A-2027-12641','','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D8%B5%D9%86%D8%AF%D9%88%D9%82-%D8%A7%D9%84%D9%86%D9%82%D8%AF-%D8%A7%D9%82%D8%AA%D8%B5%D8%A7%D8%AF-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%A3%D8%AB%D8%A8%D8%AA-%D8%B5%D9%85%D9%88%D8%AF%D8%A7-%D9%85%D8%B9-55-%D9%86%D9%85%D9%88-%D9%85%D8%AA%D9%88%D9%82%D8%B9-%D9%81%D9%8A-2027-12641','','السعودية','2026-07-29T15:58:00.000Z','2026-07-29T17:18:15.000Z','2026-07-30T06:04:03.674Z','https://static.aleqt.com/aleqt/uploads/images/2026/07/29/2232243.webp?w=800&q=75','/api/media/7a9b04eb-77c2-4d59-8aac-5d9c04ba9449','/api/media/7a9b04eb-77c2-4d59-8aac-5d9c04ba9449?variant=thumbnail','مركز الملك عبد الله المالي ',1200,798,'valid','published','archived','valid',99,'bb616ee9c8a82185cf3205f4cb492d08368bedb26380ccd646a0bee103a0abc3','c560ec58883b38d6c28d07459367e07c5b101496b5a12ec3def8fe0d354466c4','محدّث','2026-07-30T06:04:03.674Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الاقتصاد والأسواق"]','["الطاقة والنفط","الاقتصاد والأسواق"]','classified','','[{"category":"أخبار السعودية","score":8.5},{"category":"الوظائف وسوق العمل","score":4},{"category":"الطاقة والصناعة","score":3}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bd95fb4e-584c-47af-84b5-6fee855f8641','news-bd95fb4e-584c-47af-84b5-6fee855f8641','أصول "فيفا" على طاولة المستثمرين .. هل يصمد مشروع إنفانتينو؟','اصول فيفا علي طاوله المستثمرين هل يصمد مشروع انفانتينو','يدفع الاتحاد الدولي ل كرة القدم \\\" فيفا \\\" نحو تنفيذ واحدة من أكبر عمليات إعادة هيكلة أصوله التجارية، عبر إنشاء شركة مستقلة تُقدَّر قيمتها بنحو 20 مليار يورو، تمهيداً لطرح حصة منها أمام مستثمرين من القطاع الخاص، في خطوة تستهدف تنويع مصادر التمويل واستقطاب رؤوس الأموال للاستثمار في الحقوق التجارية.','["وبحسب ما أوردته صحيفة “التايمز”، طلب رئيس \\\\\\\"فيفا\\\\\\\" جياني إنفانتينو من الاتحادات الوطنية الأعضاء حسم موقفها من المشروع قبل 19 سبتمبر، في وقت يواجه فيه المقترح معارضة متزايدة من الاتحاد الأوروبي لكرة القدم \\\\\\\"يويفا\\\\\\\" وعدد من الاتحادات والهيئات الكروية.","المشروع ، يقوم على تأسيس ذراع تجارية جديدة تتولى إدارة جزء من الحقوق التجارية للفيفا، مع بيع حصة تبلغ 20% من الشركة لمستثمرين من القطاع الخاص، بما يسمح بجمع أكثر من 4 مليارات يورو، وفق الخطة المطروحة.","ولم يكشف \\\\\\\"فيفا\\\\\\\" حتى الآن عن طبيعة الأصول أو الحقوق التجارية التي ستُنقل إلى الشركة الجديدة، إلا أن المشروع يُعد من أكبر المبادرات الاستثمارية في صناعة الرياضة العالمية إذا حظي بموافقة الاتحادات الأعضاء.","رصد \\\\\\\"فيفا\\\\\\\" حزمة تمويل تبلغ 10 مليارات دولار للاتحادات التي تؤيد المشروع، على أن يبدأ توزيعها اعتباراً من الأول من يناير/كانون الثاني 2027، بما يمنح كل اتحاد نحو 40 مليون دولار."]','الرياضة','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%A7%D9%84%D8%B1%D9%8A%D8%A7%D8%B6%D8%A9/%D8%A3%D8%B5%D9%88%D9%84-%D9%81%D9%8A%D9%81%D8%A7-%D8%B9%D9%84%D9%89-%D8%B7%D8%A7%D9%88%D9%84%D8%A9-%D8%A7%D9%84%D9%85%D8%B3%D8%AA%D8%AB%D9%85%D8%B1%D9%8A%D9%86-%D9%87%D9%84-%D9%8A%D8%B5%D9%85%D8%AF-%D9%85%D8%B4%D8%B1%D9%88%D8%B9-%D8%A5%D9%86%D9%81%D8%A7%D9%86%D8%AA%D9%8A%D9%86%D9%88-12648','https://www.aleqt.com/%D8%A7%D9%84%D8%B1%D9%8A%D8%A7%D8%B6%D8%A9/%D8%A3%D8%B5%D9%88%D9%84-%D9%81%D9%8A%D9%81%D8%A7-%D8%B9%D9%84%D9%89-%D8%B7%D8%A7%D9%88%D9%84%D8%A9-%D8%A7%D9%84%D9%85%D8%B3%D8%AA%D8%AB%D9%85%D8%B1%D9%8A%D9%86-%D9%87%D9%84-%D9%8A%D8%B5%D9%85%D8%AF-%D9%85%D8%B4%D8%B1%D9%88%D8%B9-%D8%A5%D9%86%D9%81%D8%A7%D9%86%D8%AA%D9%8A%D9%86%D9%88-12648','','https://www.aleqt.com/%D8%A7%D9%84%D8%B1%D9%8A%D8%A7%D8%B6%D8%A9/%D8%A3%D8%B5%D9%88%D9%84-%D9%81%D9%8A%D9%81%D8%A7-%D8%B9%D9%84%D9%89-%D8%B7%D8%A7%D9%88%D9%84%D8%A9-%D8%A7%D9%84%D9%85%D8%B3%D8%AA%D8%AB%D9%85%D8%B1%D9%8A%D9%86-%D9%87%D9%84-%D9%8A%D8%B5%D9%85%D8%AF-%D9%85%D8%B4%D8%B1%D9%88%D8%B9-%D8%A5%D9%86%D9%81%D8%A7%D9%86%D8%AA%D9%8A%D9%86%D9%88-12648','','السعودية','2026-07-29T15:38:00.000Z',NULL,'2026-07-30T06:04:04.235Z','https://static.aleqt.com/aleqt/uploads/images/2026/07/29/2232242.webp?w=800&q=75','/api/media/bd95fb4e-584c-47af-84b5-6fee855f8641','/api/media/bd95fb4e-584c-47af-84b5-6fee855f8641?variant=thumbnail','أصول "فيفا" على طاولة المستثمرين .. هل يصمد مشروع إنفانتينو؟',1200,800,'valid','published','archived','valid',53,'41df2fd76e4eb87e0efd43a1d01c12729b1ae1846efd65c093b36782dd502de0','6296f2e0aa58355e076b2178e3b16fc33373b2b3c859c353775fd54a9874e1fd',NULL,'2026-07-30T06:04:04.235Z','2026-10-07T20:24:27.228Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس فيفا جياني إنفانتينو من","الرياضة السعودية","الاقتصاد والأسواق","الرياض"]','["رئيس فيفا جياني إنفانتينو من","الرياضة السعودية","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":4},{"category":"التقنية","score":2},{"category":"المناطق","score":1.5}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('005ad868-e287-4f0b-ad0d-fb4ddfdefa76','news-005ad868-e287-4f0b-ad0d-fb4ddfdefa76','الهيئة تُكرَّم ضمن الجهات المتميزة في دعم الصحة النفسية','الهيئه تكرم ضمن الجهات المتميزه في دعم الصحه النفسيه','في إنجازٍ يعكس اهتمام الهيئة بتعزيز جودة بيئة العمل والارتقاء بصحة ورفاه منسوبيها، كرّم المركز الوطني لتعزيز الصحة النفسية الهيئة العامة للغذاء والدواء، تقديرًا لجهودها وتميزها في دعم وتعزيز الصحة النفسية في بيئة العمل .','["ويأتي هذا التكريم تتويجًا للمبادرات والبرامج التي نفذتها الهيئة في مجال الصحة النفسية تحت مظلة برنامج \" صحتك أولى \" ، وهو برنامج يُعنى بتعزيز صحة ورفاه الموظفين من خلال منظومة متكاملة تشمل الصحة النفسية، والصحة البدنية، والتوعية الصحية، والصحة والسلامة المهنية، بما يسهم في بناء بيئة عمل صحية وآمنة ومحفزة، والارتقاء بجودة الحياة الوظيفية لمنسوبي الهيئة .","وتضمنت هذه الجهود تنفيذ برامج توعوية، وورش عمل متخصصة، وتوفير مساحات آمنة للحوار للموظفين وعائلاتهم، إلى جانب إطلاق مبادرات تسهم في رفع الوعي بالصحة النفسية، وتعزيز الوقاية، وترسيخ ثقافة طلب الدعم في بيئة آمنة وسرية .","ويؤكد هذا الإنجاز التزام الهيئة بالاستثمار في الإنسان باعتباره الركيزة الأساسية للنجاح المؤسسي، وحرصها على تبني أفضل الممارسات التي تعزز صحة الموظفين ورفاههم، بما ينعكس إيجابًا على جودة الحياة الوظيفية، ويرفع مستويات الأداء، ويسهم في تحقيق التميز المؤسسي .","وتواصل الهيئة تطوير برامجها ومبادراتها ضمن برنامج \"صحتك أولى \"، انطلاقًا من إيمانها بأن صحة الموظف ورفاهه بمختلف أبعادها تمثل ركيزة أساسية لبناء بيئة عمل مستدامة ومحفزة، وداعمًا رئيسًا لتحقيق رسالتها المؤسسية."]','الصحة','','7548f886-42c0-48e1-b296-5bfe53b96e3f','الهيئة العامة للغذاء والدواء','https://www.sfda.gov.sa/ar/news/5522070','https://www.sfda.gov.sa/ar/news/5522070','','https://www.sfda.gov.sa/ar/news/5522070','','','2026-07-23T12:00:00.000Z',NULL,'2026-07-30T06:06:37.404Z','https://www.sfda.gov.sa/sites/default/files/2026-07/%D8%AA%D9%83%D8%B1%D9%8A%D9%85%20%D8%A7%D9%84%D9%87%D9%8A%D9%8A%D9%94%D8%A9%20%28%D8%B5%D8%AD%D8%AA%D9%83%20%D8%A7%D9%94%D9%88%D9%84%D9%89%29.jpg','/api/media/005ad868-e287-4f0b-ad0d-fb4ddfdefa76','/api/media/005ad868-e287-4f0b-ad0d-fb4ddfdefa76?variant=thumbnail','الهيئة تُكرَّم ضمن الجهات المتميزة في دعم الصحة النفسية',1600,2819,'valid','review','archived','valid',77,'684f1cacefc6e51dc8134c5a14f6c44e4eb74fdc5cd8244ff9e3badf4a802806','b8d8221d5261c6e9e5ea3ded94f2b3128ddfead0860162d83cfb93f8d2d89ddb',NULL,'2026-07-30T06:06:37.404Z','2026-10-07T19:51:59.123Z','','',0,0,'saudi_national','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة","رئيس ا لتحقيق رسالتها المؤسسية","الاقتصاد والأسواق","دعم الصحة","المتميزة دعم","الجهات المتميزة","دعم الصحة النفسية","المتميزة دعم الصحة"]','["رئيس ا لتحقيق رسالتها المؤسسية","الاقتصاد والأسواق","دعم الصحة","المتميزة دعم","الجهات المتميزة","دعم الصحة النفسية"]','manual_approved','','[]','Removed','2026-10-07T19:51:59.123Z',404,77,0,'source_confirmed_removed_http_404','','2026-10-07T19:51:59.123Z','published','body:395923392f3e788d8c824463525cfb7ff44e27a0700ebc95b2d993fe755f0f34','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('16fbc188-3895-4786-a4fc-09b0733603b0','news-16fbc188-3895-4786-a4fc-09b0733603b0','الرئيس التنفيذي لـ "الغذاء والدواء" يلتقي رئيس هيئة الدستور الغذائي','الرئيس التنفيذي لـ الغذاء والدواء يلتقي رئيس هيئه الدستور الغذائي','التقى معالي الرئيس التنفيذي للهيئة العامة للغذاء والدواء الدكتور هشام بن سعد الجضعي، رئيس هيئة الدستور الغذائي الدكتور آلن أزجيلي في اجتماع ثنائي عُقد على هامش أعمال الدورة التاسعة والأربعين للهيئة، المنعقدة في مدينة جنيف السويسرية خلال الفترة 6 - 10 يوليو الجاري.','["التقى معالي الرئيس التنفيذي للهيئة العامة للغذاء والدواء الدكتور هشام بن سعد الجضعي، رئيس هيئة الدستور الغذائي الدكتور آلن أزجيلي في اجتماع ثنائي عُقد على هامش أعمال الدورة التاسعة والأربعين للهيئة، المنعقدة في مدينة جنيف السويسرية خلال الفترة 6 - 10 يوليو الجاري. وجرى خلال اللقاء الذي حضره نواب رئيس هيئة الدستور الغذائي وهم خالد الزهراني من المملكة العربية السعودية، وبيتول فازغيتشر من جمهورية تركيا، وجينغ تيان من جمهورية الصين، مناقشة عدد من الموضوعات ذات الاهتمام المشترك، وبحث فرص تنفيذ برامج تدريبية وورش عمل مشتركة للدول الأعضاء والمراقبين، إلى جانب استعراض جهود المملكة في بناء القدرات من خلال أكاديمية الهيئة العامة للغذاء والدواء. وأكد معاليه دعم المملكة المتواصل لأعمال هيئة الدستور الغذائي والخطة الإستراتيجية 2026 - 2031، انطلاقًا من أهمية الدور الذي تضطلع به الهيئة في تطوير المعايير الغذائية الدولية، وتعزيز سلامة الغذاء، وحماية صحة المستهلكين على المستوى العالمي. واستعرض الدكتور الجضعي خلال اللقاء كتاب \"جداول تراكيب الأغذية السعودي\"، الذي يُبرز تنوع الأطباق السعودية وقيمها الغذائية، وأشاد رئيس هيئة الدستور الغذائي، وأمانة الهيئة، وممثل منظمة الأغذية والزراعة، بالجهود التي بذلتها المملكة، ممثلةً بالهيئة العامة للغذاء والدواء، في إعداد هذا الكتاب، وما يمثله من مرجع علمي يدعم بيانات الأغذية ويعكس ثراء الموروث الغذائي السعودي. يُذكر أن منظمة الأغذية والزراعة FAO وثّقت كتاب جداول تراكيب الأغذية السعودي على موقعها الإلكتروني، إضافة إلى توثيق قاعدة بيانات تراكيب الأغذية السعودية في منصة INFOODS التابعة للمنظمة، بما يؤكد تأثير الهيئة والمملكة في المحافل الدولية، ويبرز القيمة العلمية لمخرجاتها على مستوى المنظمات العالمية."]','أخبار السعودية','','7548f886-42c0-48e1-b296-5bfe53b96e3f','الهيئة العامة للغذاء والدواء','https://www.sfda.gov.sa/ar/news/5522015','https://www.sfda.gov.sa/ar/news/5522015','','https://www.sfda.gov.sa/ar/news/5522015','','','2026-07-29T12:00:00.000Z',NULL,'2026-07-30T06:06:37.580Z','https://www.sfda.gov.sa/sites/default/files/2026-07/DSC_6922.JPG','/api/media/16fbc188-3895-4786-a4fc-09b0733603b0','/api/media/16fbc188-3895-4786-a4fc-09b0733603b0?variant=thumbnail','الرئيس التنفيذي لـ "الغذاء والدواء" يلتقي رئيس هيئة الدستور الغذائي',1500,1001,'valid','review','archived','valid',44,'936c6b4fd574820b77c08c110bc62dc7c04710bd9a3ce36f391d4abd3bcb555b','927fc5d013da129c60c595dfae2e7817eb731561023cb306da36476d64937267',NULL,'2026-07-30T06:06:37.580Z','2026-10-07T19:51:55.859Z','','',0,0,'saudi_national','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية","رئيس هيئة الدستور الغذائي التقى","هيئة الدستور الغذائي التقى معالي","التعليم والتدريب","تركيا","الصين","يلتقي رئيس هيئة","الرئيس التنفيذي"]','["أخبار السعودية","رئيس هيئة الدستور الغذائي التقى","هيئة الدستور الغذائي التقى معالي","التعليم والتدريب","يلتقي رئيس هيئة","الرئيس التنفيذي"]','manual_approved','below_category_threshold','[{"category":"الصحة","score":3},{"category":"العالم","score":3},{"category":"التعليم","score":1.5}]','Removed','2026-10-07T19:51:55.859Z',404,77,0,'source_confirmed_removed_http_404','','2026-10-07T19:51:55.859Z','published','body:df14f6ef0016f8199ef1a1d953b8af17ffd81e75bb46ca88ff51bddc09e647a5','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dc3daa35-0f3e-4629-b22c-6f152c520b6f','news-dc3daa35-0f3e-4629-b22c-6f152c520b6f','إعادة انتخاب المملكة نائبًا لرئيس هيئة الدستور الغذائي الدولية (CODEX) حتى عام 2027','اعاده انتخاب المملكه نائبا لرئيس هيئه الدستور الغذائي الدوليه codex حتي عام 2027','أُعيد انتخاب المملكة العربية السعودية، ممثلةً بالهيئة العامة للغذاء والدواء، نائبًا لرئيس هيئة الدستور الغذائي الدولية (CODEX)، وذلك خلال أعمال الدورة التاسعة والأربعين للهيئة المنعقدة في مدينة جنيف السويسرية، لتستمر في عضوية رئاسة هيئة الدستور الغذائي حتى نهاية الدورة العادية المقبلة (الدورة الخمسين) المقرر عقدها عام 2027.','["&nbsp;ويعكس هذا الانتخاب الثقة الدولية في الدور المتنامي للمملكة في دعم أعمال هيئة الدستور الغذائي، وإسهاماتها في تطوير المواصفات الغذائية الدولية القائمة على الأسس العلمية، ودعم التوافق بين الدول الأعضاء، والمشاركة في بناء القدرات من خلال تنفيذ برامج تدريبية وورش عمل مشتركة تستهدف الدول الأعضاء والمراقبين.","&nbsp;من جانبه، أعرب معالي الرئيس التنفيذي للهيئة العامة للغذاء والدواء الأستاذ الدكتور هشام بن سعد الجضعي عن اعتزازه بإعادة انتخاب المملكة لهذا المنصب، مؤكدًا أن ذلك يجسد ما تحظى به من دعم وتمكين من القيادة الرشيدة -أيدها الله-، ويعكس المكانة التي وصلت إليها على المستوى الدولي في مجالات سلامة الغذاء والصحة العامة.","&nbsp;وأشار معاليه إلى أن المملكة ستواصل دعم أعمال هيئة الدستور الغذائي والخطة الإستراتيجية للأعوام 2026 - 2031، والإسهام الفاعل في تطوير المعايير الغذائية الدولية ومواءمتها مع المستجدات العلمية، بما يعزز سلامة الغذاء، ويحمي صحة المستهلكين، ويدعم استدامة سلاسل الإمداد الغذائية والتجارة الدولية.","&nbsp;ويشغل المنصب خالد بن سعود الزهراني، الذي انتُخب في عام 2024، وأُعيد انتخابه نائبًا لرئيس هيئة الدستور الغذائي في العام 2025، ويشارك في دعم أعمال الهيئة ولجانها المختلفة، بما يعزز حضور المملكة وإسهامها في صياغة السياسات والمعايير الغذائية الدولية.","&nbsp;وتُعد هيئة الدستور الغذائي الدولية (CODEX)، التي تأسست عام 1963، الجهة الدولية المعنية بوضع المواصفات الغذائية والمعايير والإرشادات ذات الصلة بسلامة الغذاء وجودته، وتضم في عضويتها (189) دولة، وتعمل تحت مظلة منظمة الأغذية والزراعة للأمم المتحدة (FAO) ومنظمة الصحة العالمية (WHO)، وانضمت المملكة إلى عضويتها عام 1968، وتشغل حاليًا منصب نائب رئيس الهيئة منذ انتخابها في عام 2024، إلى جانب عضويتها في اللجنة التنفيذية لهيئة الدستور الغذائي."]','الصحة','','7548f886-42c0-48e1-b296-5bfe53b96e3f','الهيئة العامة للغذاء والدواء','https://www.sfda.gov.sa/ar/news/5522014','https://www.sfda.gov.sa/ar/news/5522014','','https://www.sfda.gov.sa/ar/news/5522014','','','2026-07-29T12:00:00.000Z',NULL,'2026-07-30T06:06:37.773Z','https://www.sfda.gov.sa/sites/default/files/2026-07/1000109563.jpg','/api/media/dc3daa35-0f3e-4629-b22c-6f152c520b6f','/api/media/dc3daa35-0f3e-4629-b22c-6f152c520b6f?variant=thumbnail','إعادة انتخاب المملكة نائبًا لرئيس هيئة الدستور الغذائي الدولية (CODEX) حتى عام 2027',992,1748,'valid','review','archived','valid',87,'1af111e4901abae880f4b517d90762fa2be545145f765a2160bbf1724a0a3c34','7727e4872a08eacde8140293a84a5f445d7f78d5b8a78272617fae558e80bb18',NULL,'2026-07-30T06:06:37.773Z','2026-10-07T19:51:57.839Z','','',0,0,'saudi_national','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة","هيئة الدستور الغذائي الدولية CODEX","التعليم والتدريب","الاقتصاد والأسواق","نائب لرئيس هيئة","المملكة نائب لرئيس","لرئيس هيئة الدستور","انتخاب المملكة نائب"]','["هيئة الدستور الغذائي الدولية CODEX","التعليم والتدريب","الاقتصاد والأسواق","نائب لرئيس هيئة","المملكة نائب لرئيس","لرئيس هيئة الدستور"]','classified','','[{"category":"الطاقة والصناعة","score":4},{"category":"أخبار السعودية","score":3},{"category":"الاقتصاد","score":1.5}]','Removed','2026-10-07T19:51:57.839Z',404,77,0,'source_confirmed_removed_http_404','','2026-10-07T19:51:57.839Z','published','body:969196291f3d3e4db4c8d8a043b5410d40254dca3337d5e8da32b2f55d3fd430','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2a5f4683-19d5-4824-b40a-31836e4d8ccc','news-2a5f4683-19d5-4824-b40a-31836e4d8ccc','وزارة الصحة السعودية','وزاره الصحه السعوديه','​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​تعمل وزارة الصحة على توفير الرعاية الصحية بجميع مستوياتها، وتعزيز الصحة العامة، والوقاية من الأمراض، ووضع القوانين واللوائح المنظمة للقطاع الصحي العام والخاص، ومراقبة أدائه، مع الاهتمام بالجانب البحثي، والتدريب الأكاديمي، ومجالات الاستثمار الصحي.','["​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​​تعمل وزارة الصحة على توفير الرعاية الصحية بجميع مستوياتها، وتعزيز الصحة العامة، والوقاية من الأمراض، ووضع القوانين واللوائح المنظمة للقطاع الصحي العام والخاص، ومراقبة أدائه، مع الاهتمام بالجانب البحثي، والتدريب الأكاديمي، ومجالات الاستثمار الصحي. وتقدم الوزارة الرعاية الصحية في المرافق الطبية الحكومية للمواطنين بشكل مجاني، وحسب نظام الرعاية الصحية الجديد المواكب لاحتياجات القطاع…"]','الصحة','','d4708bd5-44da-4bc5-aff0-585d7d20f5c6','وزارة الصحة السعودية','https://www.moh.gov.sa/Ministry/Structure/Pages/default.aspx','https://www.moh.gov.sa/ministry/structure/pages/default.aspx','','https://www.moh.gov.sa/Ministry/Structure/Pages/default.aspx','فريق بوابة وزارة الصحة','','2026-07-29T09:07:08.000Z','Wed, 07 Oct 2026 19:52:43 GMT','2026-07-30T06:07:08.049Z','','','/api/media/fallback/%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1%20%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9','وزارة الصحة السعودية',NULL,NULL,'invalid','published','archived','valid',99,'40b6a47ad5d7a6f5e39bb953822b36c39fe8b68f9dfd8bf11de17e8063e19f43','3468dd9e7821fc02d7c6e2833bc381fbbc4db922824349894e3bfb08b16e1569',NULL,'2026-07-30T06:07:08.049Z','2026-10-07T20:24:27.230Z','','',0,0,'saudi_national','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الاقتصاد والأسواق"]','["التعليم والتدريب","الاقتصاد والأسواق"]','classified','','[{"category":"الصحة","score":14.5},{"category":"الاقتصاد","score":4},{"category":"المجتمع","score":1.5}]','Updated','2026-10-07T19:52:47.114Z',200,80,0,'source_content_changed','',NULL,NULL,'body:f8a19861983e49c5d6f76e259990ecb04894bab5e5c2ecdac9e58dcbc9830d5d','Wed, 07 Oct 2026 19:52:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9d334f42-ca20-448f-a0b7-23f21e2d89fe','news-9d334f42-ca20-448f-a0b7-23f21e2d89fe','أحمد مكي يكسر غياب 13 عاماً عن السينما بفيلم مع ماجد الكدواني','احمد مكي يكسر غياب 13 عاما عن السينما بفيلم مع ماجد الكدواني','يستعد الفنان أحمد مكي للعودة إلى شاشة السينما بعد غياب استمر 13 عاماً، من خلال فيلم جديد يحمل عنوان " فرصة سعيدة "، يجمعه بالفنان ماجد الكدواني ، ويتولى إخراجه أحمد الجندي ، ويعيد هذا العمل الثلاثي الذي حقق نجاحات كبيرة في السينما والدراما خلال السنوات الماضية، حيث من المقرر أن يبدأ أحمد مكي تصوير أول مشاهد الفيلم الأسبوع المقبل.','["أشرف زكي يحذر الفنانين بعد تفعيل حق الأداء العلني.. وتحركات لوضع آليات التنفيذ","وخلال السنوات الماضية، دخل أحمد مكي في مفاوضات وتحضيرات لأكثر من مشروع سينمائي بهدف العودة إلى الشاشة الكبيرة، إلا أن تلك الأعمال لم ترَ النور، وتوقفت جميعها قبل بدء التصوير، لتظل عودته مؤجلة حتى استقر أخيراً على فيلم \" فرصة سعيدة \" الذي يراهن عليه بقوة من أجل استعادة بريقه السينمائي مرة أخرى.","آخر مشاركات أحمد مكي الدرامية، جاءت خلال مسلسل \" الغاوي \" والذي تم عرضه في شهر رمضان من عام 2025، والعمل ينتمى لنوعية الـ15 حلقة، وهو من تأليف طارق كاشف ومحمود زهران وإخراج ماندو العدل وإنتاج شركة سينرجى وبطولة أحمد مكى وعائشة بن أحمد وعمرو عبد الجليل، أحمد بدير، أحمد كمال، محمد لطفى، ولاء الشريف، كرم جابر، هاجر عفيفى، أبيوسف، تامر شلتوت، وضيف الشرف كزبرة."]','الثقافة','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1-%D8%A7%D9%84%D8%B9%D8%B1%D8%A8/1837263-%D8%A3%D8%AD%D9%85%D8%AF-%D9%85%D9%83%D9%8A-%D9%8A%D9%83%D8%B3%D8%B1-%D8%BA%D9%8A%D8%A7%D8%A8-13-%D8%B9%D8%A7%D9%85%D8%A7%D9%8B-%D8%B9%D9%86-%D8%A7%D9%84%D8%B3%D9%8A%D9%86%D9%85%D8%A7-%D8%A8%D9%81%D9%8A%D9%84%D9%85-%D9%85%D8%B9-%D9%85%D8%A7%D8%AC%D8%AF-%D8%A7%D9%84%D9%83%D8%AF%D9%88%D8%A7%D9%86%D9%8A','https://www.sayidaty.net/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1-%D8%A7%D9%84%D8%B9%D8%B1%D8%A8/1837263-%D8%A3%D8%AD%D9%85%D8%AF-%D9%85%D9%83%D9%8A-%D9%8A%D9%83%D8%B3%D8%B1-%D8%BA%D9%8A%D8%A7%D8%A8-13-%D8%B9%D8%A7%D9%85%D8%A7%D9%8B-%D8%B9%D9%86-%D8%A7%D9%84%D8%B3%D9%8A%D9%86%D9%85%D8%A7-%D8%A8%D9%81%D9%8A%D9%84%D9%85-%D9%85%D8%B9-%D9%85%D8%A7%D8%AC%D8%AF-%D8%A7%D9%84%D9%83%D8%AF%D9%88%D8%A7%D9%86%D9%8A','1837263 at https://www.sayidaty.net','1837263 at https://www.sayidaty.net','محمد المعصراوى','السعودية','2026-07-29T18:00:01.000Z','2026-07-29T18:00:01.000Z','2026-07-30T06:11:21.947Z','https://static.sayidaty.net/styles/1375_scale/public/2026-07/503185.jpg?VersionId=EnL0pUzZFpFoUyX_WlKKHV8mZRQKMtwv','/api/media/9d334f42-ca20-448f-a0b7-23f21e2d89fe','/api/media/9d334f42-ca20-448f-a0b7-23f21e2d89fe?variant=thumbnail','أحمد مكي يكسر غياب 13 عاماً عن السينما بفيلم مع ماجد الكدواني',1375,1031,'valid','published','archived','valid',52,'23dcdfe2e30c1db3a2468ded300df11ead3d952fc7ca2aeb4d6aabaea104ba00','92d43677bd8a061e21f6c66b3d6ad303a8a45f3e86c6ef969af8958c3a8f1464','محدّث','2026-07-30T06:11:21.947Z','2026-10-07T20:24:27.232Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة سينرجى وبطولة أحمد مكى","الثقافة والفنون","الرياضة السعودية","السياسة والعلاقات الدولية"]','["شركة سينرجى وبطولة أحمد مكى","الثقافة والفنون","الرياضة السعودية","السياسة والعلاقات الدولية"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"الرياضة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5b0498c3-2760-44e0-97f3-ed09f0eb6ad4','news-5b0498c3-2760-44e0-97f3-ed09f0eb6ad4','هل يرفع الصيام المتقطع خطر الوفاة؟.. "الصحة" تحسم الجدل','هل يرفع الصيام المتقطع خطر الوفاه الصحه تحسم الجدل','نفت وزارة الصحة السعودية عبر منصتها التوعوية "عش بصحة" صحة المعلومات المتداولة على نطاق واسع، التي تزعم أن الصيام المتقطع يرفع خطر الوفاة بأمراض القلب بنسبة 91%.','["وأوضحت الوزارة أن هذا الرقم مصدره بحث أولي لم يبلغ مستوى الإثبات العلمي المعتمد، في حين أثبتت الدراسات المحكّمة مأمونية الصيام المتقطع، لا سيما لدى الأشخاص الذين لا يعانون من أمراض مزمنة.","وشددت الوزارة على أن الصيام المتقطع لا يقتصر على تقليص ساعات الأكل، بل تتكامل فوائده الحقيقية حين يُقرن بنظام غذائي متوازن يلبّي الاحتياجات اليومية للجسم.","ونبّهت إلى ضرورة استشارة الطبيب المختص قبل اتباع هذا النظام الغذائي لمرضى القلب وأصحاب الأمراض المزمنة، لضمان السلامة الصحية وتفادي أي مضاعفات محتملة."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/26y16qo','https://sabq.org/article/26y16qo','','https://sabq.org/article/26y16qo','صحيفة سبق','السعودية','2026-07-29T19:33:54.665Z','2026-07-29T19:34:48.681Z','2026-07-30T06:11:22.000Z','','','/api/media/fallback/%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1%20%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9','هل يرفع الصيام المتقطع خطر الوفاة؟.. "الصحة" تحسم الجدل',NULL,NULL,'fallback','review','archived','valid',83,'92bcf727e223e4e1ab7cd3d973fc9a31650d1bdd639827db5b22a6b398ab0b53','038c8483b0b65c7a5c334aa8f5a56a3e82b72bf400c76fdcb1e6673804713ba7',NULL,'2026-07-30T06:11:22.000Z','2026-10-07T19:51:26.964Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية","الصحة العامة","يرفع الصيام","الصيام المتقطع","خطر الوفاة الصحة","الصحة تحسم الجدل","الوفاة الصحة تحسم","الصيام المتقطع خطر"]','["أخبار السعودية","الصحة العامة","يرفع الصيام","الصيام المتقطع","خطر الوفاة الصحة","الصحة تحسم الجدل"]','classified','','[]','Active','2026-10-07T19:51:26.964Z',200,73,0,'source_article_available','',NULL,NULL,'body:fae2346946dabf4f1528f4a10f7a7d7d71ac08d3ddc4e9401a6f19b7020ece30','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1361a058-6db5-4286-b265-252fa8131385','news-1361a058-6db5-4286-b265-252fa8131385','ميغان ماركل تكشف نصيحة الأمير هاري لمواجهة الأيام الصعبة','ميغان ماركل تكشف نصيحه الامير هاري لمواجهه الايام الصعبه','كشفت دوقة ساسكس، ميغان ماركل Meghan Markle عن النصيحة التي استمدتها من زوجها الأمير هاري Prince Harry لتجاوز الضغوط والأوقات القاسية، وذلك خلال مشاركتها كضيفة رئيسية في الجلسة الحوارية للعرض الخاص للفيلم الوثائقي "Cookie Queens" في لوس أنجلوس، والذي شارك الثنائي في إنتاجه تنفيذياً.','["ولا يقتصر هذا الدعم المعنوي على طرف واحد؛ إذ سبق وأكد الأمير هاري اعتماده الدائم على نصيحة موجزة وقيمة من ميغان وهي: \"تمسك بالحقيقة دائماً\"، موضحاً أنها الأسلوب الأكثر فاعلية لمواجهة أي شيء في الحياة.","يذكر أن ميغان ماركل كانت قد خطفت الأنظار مؤخراً خلال ظهورها المتميز كضيفة شرف في برنامج الطهي الشهير \"ماستر شيف أستراليا\". وشهدت الحلقة لحظة استثنائية عندما تلقت مكالمة فيديو مفاجئة من الأمير هاري على الهواء مباشرة أثناء تقييم الأطباق؛ حيث تبادل الزوجان المزاح والتعليقات العفوية وسط تصفيق الحكام والمتسابقين لتتحول اللحظة التي جمعت بين الطرافة والرومانسية إلى حديث الجمهور على مواقع التواصل الاجتماعي.","الأمير هاري يكشف عن نصيحة تربوية تعلمها من والدته الأميرة ديانا"]','أخبار السعودية','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/%D8%B9%D8%A7%D8%A6%D9%84%D8%A7%D8%AA-%D9%85%D9%84%D9%83%D9%8A%D8%A9/1837261-%D9%85%D9%8A%D8%BA%D8%A7%D9%86-%D9%85%D8%A7%D8%B1%D9%83%D9%84-%D8%AA%D9%83%D8%B4%D9%81-%D9%86%D8%B5%D9%8A%D8%AD%D8%A9-%D8%A7%D9%84%D8%A3%D9%85%D9%8A%D8%B1-%D9%87%D8%A7%D8%B1%D9%8A-%D9%84%D9%85%D9%88%D8%A7%D8%AC%D9%87%D8%A9-%D8%A7%D9%84%D8%A3%D9%8A%D8%A7%D9%85-%D8%A7%D9%84%D8%B5%D8%B9%D8%A8%D8%A9','https://www.sayidaty.net/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/%D8%B9%D8%A7%D8%A6%D9%84%D8%A7%D8%AA-%D9%85%D9%84%D9%83%D9%8A%D8%A9/1837261-%D9%85%D9%8A%D8%BA%D8%A7%D9%86-%D9%85%D8%A7%D8%B1%D9%83%D9%84-%D8%AA%D9%83%D8%B4%D9%81-%D9%86%D8%B5%D9%8A%D8%AD%D8%A9-%D8%A7%D9%84%D8%A3%D9%85%D9%8A%D8%B1-%D9%87%D8%A7%D8%B1%D9%8A-%D9%84%D9%85%D9%88%D8%A7%D8%AC%D9%87%D8%A9-%D8%A7%D9%84%D8%A3%D9%8A%D8%A7%D9%85-%D8%A7%D9%84%D8%B5%D8%B9%D8%A8%D8%A9','1837261 at https://www.sayidaty.net','1837261 at https://www.sayidaty.net','نت','السعودية','2026-07-29T16:26:58.000Z','2026-07-29T16:26:58.000Z','2026-07-30T06:11:22.150Z','https://static.sayidaty.net/styles/1375_scale/public/2026-07/503180.jpg?VersionId=n7z.bMkypN69T0CcspQeoL6UZ_ECuBbh','/api/media/1361a058-6db5-4286-b265-252fa8131385','/api/media/1361a058-6db5-4286-b265-252fa8131385?variant=thumbnail','ميغان ماركل تكشف نصيحة الأمير هاري لمواجهة الأيام الصعبة',1375,917,'valid','published','archived','valid',40,'bfa45b271f104974df7d38dc5ff6e09d7d98e5aaef9684fd054a4560d317840f','4b01b3e35644e64a6220fcc5d3dbae7a5608e359b0e5832d2f210fa6c49bfc3d','محدّث','2026-07-30T06:11:22.150Z','2026-10-07T20:24:27.234Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع"]','[]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('02c182bf-782e-45fb-87ae-e0fea473a255','news-02c182bf-782e-45fb-87ae-e0fea473a255','تكافل الراجحي تحقق أعلى مستوى للتوافق مع المعايير العالمية للمراجعة الداخلية','تكافل الراجحي تحقق اعلي مستوي للتوافق مع المعايير العالميه للمراجعه الداخليه','حققت تكافل الراجحي إنجازًا في مجال الحوكمة، بعد حصول إدارة المراجعة الداخلية على تصنيف التوافق التام (Full Conformance)، وهو أعلى مستوى للتوافق مع المعايير العالمية للمراجعة الداخلية (GIAS) الصادرة عن معهد المراجعين الداخليين (IIA)، وذلك وفقًا لنتائج تقييم الجودة الخارجي المستقل الذي أجرته شركة إيكوفيس السبتي.','["وتكتسب هذه النتيجة أهمية خاصة، لكون التقييم أُجري وفق المعايير العالمية المحدّثة للمراجعة الداخلية، التي دخلت حيز التطبيق اعتبارًا من 9 يناير 2025، وتضمنت تحديثات جوهرية تهدف إلى تعزيز جودة وفاعلية أعمال المراجعة الداخلية، ورفع مستوى الحوكمة والاستراتيجية وقياس الأداء والمساءلة المهنية.","وشمل التقييم أعمال إدارة المراجعة الداخلية والأدلة المرتبطة بها خلال الفترة من عام 2025 وحتى الربع الأول من عام 2026، وأكد تحقيق التوافق التام مع المعايير العالمية للمراجعة الداخلية، التي تتكون من خمسة نطاقات و15 مبدأً و52 معيارًا مهنيًا، بما يعكس نضج الممارسات المهنية، وكفاءة المنهجيات المطبقة، والالتزام بمتطلبات الجودة والاستقلالية والحوكمة المهنية.","كما أظهرت نتائج القياس المعياري المصاحب للتقييم أداءً تجاوز المتوسط المرجعي في جميع النطاقات، بما يعكس التقدم المحقق في تطوير وظيفة المراجعة الداخلية، ويسهم في تعزيز منظومة الحوكمة والرقابة الداخلية، ويجسد التزام تكافل الراجحي المستمر بالارتقاء بممارسات الحوكمة والشفافية والتميز المؤسسي."]','العالم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/giwriko','https://sabq.org/article/giwriko','','https://sabq.org/article/giwriko','صحيفة سبق','السعودية','2026-07-29T19:19:41.091Z','2026-07-29T19:19:59.609Z','2026-07-30T06:11:22.209Z','https://media.sabq.org/news/2026/07/3e7972f7-9a92-4be8-9838-7ad81469d293/w1200.webp','/api/media/02c182bf-782e-45fb-87ae-e0fea473a255','/api/media/02c182bf-782e-45fb-87ae-e0fea473a255?variant=thumbnail','تكافل الراجحي تحقق أعلى مستوى للتوافق مع المعايير العالمية للمراجعة الداخلية',1200,675,'valid','published','archived','valid',44,'121d01db35dcb8bc9f5e609b11f974b9e67f19860a599305d6af3965764b237a','9b3542f05ef5feddfc5d16a163f8cc5d24a5df6c4c7b609d608b7a73a20184f7',NULL,'2026-07-30T06:11:22.209Z','2026-10-07T20:24:27.236Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية"]','[]','manual_approved','below_category_threshold','[{"category":"العالم","score":3},{"category":"الصحة","score":1.5},{"category":"التقنية","score":1.5}]','Active','2026-10-07T19:51:22.984Z',200,74,0,'source_article_available','',NULL,NULL,'body:2d4b6acd49fcd5d5e50a7b2024e9ff2c0ae7bafa9e16bda8e87656f8d1e9e0f0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a407d23b-95a3-48b6-9f15-bf48de43d8b8','news-a407d23b-95a3-48b6-9f15-bf48de43d8b8','الهلال يخسر أمام مولودية الجزائر بهدفين في معسكره بالنمسا','الهلال يخسر امام مولوديه الجزائر بهدفين في معسكره بالنمسا','مُني فريق الهلال بخسارته الودية الثالثة في معسكره الإعدادي بالنمسا، إذ سقط أمام مولودية الجزائر بهدفين دون مقابل، مساء الأربعاء، على ملعب أوبيربوخ، ضمن البرنامج الإعدادي للموسم الرياضي المقبل.','["وأدار المدير الفني سيمونه إنزاغي المباراة بتشكيلة ضمّت: محمد العويس في المرمى، وخاليدو كوليبالي، وعلي لاجامي، ومتعب الحربي، ومحمد محرزي، وصهيب، ومالكوم فيليب، وناصر الدوسري، وسيرجي ساڤيتش، وميتي، ونونيز.","وتُمثّل هذه المواجهة خطوة تحضيرية ضمن مسار الجهاز الفني الرامي إلى رفع الجاهزية الفنية والبدنية للاعبين، وتعزيز الانسجام بين عناصر الفريق، وتطبيق المنهج التكتيكي استعداداً للاستحقاقات المقبلة.","ويفتتح الهلال مشواره في دوري روشن السعودي للمحترفين للموسم الرياضي 2026-2027 بمواجهة الفيصلي، يوم الجمعة الموافق 14 أغسطس المقبل، على ملعب المملكة أرينا."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/5x9brty','https://sabq.org/article/5x9brty','','https://sabq.org/article/5x9brty','صحيفة سبق','السعودية','2026-07-29T19:26:38.225Z','2026-07-29T19:26:46.958Z','2026-07-30T06:11:22.265Z','https://media.sabq.org/news/2026/07/4a441fde-96db-4cc2-8681-2f050cb22224/w1600.webp','/api/media/a407d23b-95a3-48b6-9f15-bf48de43d8b8','/api/media/a407d23b-95a3-48b6-9f15-bf48de43d8b8?variant=thumbnail','الهلال يخسر أمام مولودية الجزائر بهدفين في معسكره بالنمسا',1600,1192,'valid','published','archived','valid',97,'fecf29fd37141039c9df54e0bb64342a7225ef2264786c958b33751d034b3096','7b3769524ec3d93d2cd57e167d5be80a339946ce477ac57cb05c627346a5afb3',NULL,'2026-07-30T06:11:22.265Z','2026-10-07T19:51:21.147Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":1.5},{"category":"الصحة","score":1.5}]','Active','2026-10-07T19:51:21.147Z',200,76,0,'source_article_available','',NULL,NULL,'body:9ecd4ce611325e0f1465c9704491549a24e18fc279b1dddcf960a8573b0341ce','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7afd00f8-2667-4003-ab6c-9109208f133d','news-7afd00f8-2667-4003-ab6c-9109208f133d','أنغام تعلن تفاصيل وموعد إطلاق ميني ألبوم دي روحي','انغام تعلن تفاصيل وموعد اطلاق ميني البوم دي روحي','تستعد الفنانة أنغام لافتتاح مفاجآتها الفنية لموسم صيف 2026، حيث تُطلق غداً في تمام الساعة السادسة مساءً أحدث أعمالها الغنائية، الميني ألبوم الجديد " دي روحي "، وذلك عبر مختلف المنصات الموسيقية الرقمية.','["وأعلنت أنغام عن موعد إطلاق الألبوم بنشر مقطع ترويجي \"تيزر\" كشفت خلاله عن البوستر الرسمي وقائمة الأغاني الأربع التي يتألف منها العمل، وهي: \"دي روحي\"، \"بعدك وجع\"، \"محاصرني\"، و\"مسافرة بعيد\". وأرفقت الفيديو بتعليق قالت فيه: \"انتظروا ميني ألبوم دي روحي بكرة 7/30 الساعة 6:00 مساءً\".","وجاء الإعلان ليُشعل حالة واسعة من الترقب بين المتابعين؛ حيث حظيت إطلالتها الفضية الأنيقة بثناء واسع، إلى جانب التفاعل الكبير مع اللمسات الموسيقية التي تضمنها المقطع الترويجي.","يجمع هذا الإصدار أنغام بنخبة من أبرز صناع الأغنية العربية؛ حيث تتشارك ألحان الألبوم مع الملحن عزيز الشافعي في عملين، إلى جانب مشاركة الملحنين خالد عز وإيهاب عبد الواحد. بينما كتب الكلمات الشاعران تامر حسين ومحمود عليم، وتولى المهمة الموسيقية للتوزيع كل من نادر حمدي، شريف مكاوي، وطارق مدكور، مع اللمسات الصوتية لمهندس الصوت أمير محروس.","وكانت أنغام قد مهدت لهذه الخطوة خلال الأيام الماضية عبر نشر مقاطع ترويجية للأغاني الأربعة، تقدمتهما الأغنية الرئيسية \"دي روحي\" والتي تأتي من كلمات محمود عليم، ألحان عزيز الشافعي، وتوزيع شريف مكاوي. ومن المقرر أن تُكشف التفاصيل الكاملة لصناع باقي الأغنيات بالتزامن مع الطرح الرسمي غداً."]','السفر','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1-%D8%A7%D9%84%D8%B9%D8%B1%D8%A8/1837262-%D8%A3%D9%86%D8%BA%D8%A7%D9%85-%D8%AA%D8%B9%D9%84%D9%86-%D8%AA%D9%81%D8%A7%D8%B5%D9%8A%D9%84-%D9%88%D9%85%D9%88%D8%B9%D8%AF-%D8%A5%D8%B7%D9%84%D8%A7%D9%82-%D9%85%D9%8A%D9%86%D9%8A-%D8%A3%D9%84%D8%A8%D9%88%D9%85-%D8%AF%D9%8A-%D8%B1%D9%88%D8%AD%D9%8A','https://www.sayidaty.net/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1-%D8%A7%D9%84%D8%B9%D8%B1%D8%A8/1837262-%D8%A3%D9%86%D8%BA%D8%A7%D9%85-%D8%AA%D8%B9%D9%84%D9%86-%D8%AA%D9%81%D8%A7%D8%B5%D9%8A%D9%84-%D9%88%D9%85%D9%88%D8%B9%D8%AF-%D8%A5%D8%B7%D9%84%D8%A7%D9%82-%D9%85%D9%8A%D9%86%D9%8A-%D8%A3%D9%84%D8%A8%D9%88%D9%85-%D8%AF%D9%8A-%D8%B1%D9%88%D8%AD%D9%8A','1837262 at https://www.sayidaty.net','1837262 at https://www.sayidaty.net','نت','السعودية','2026-07-29T17:47:33.000Z','2026-07-29T17:47:33.000Z','2026-07-30T06:11:22.354Z','https://static.sayidaty.net/styles/1375_scale/public/2026-07/503190.jpeg?VersionId=.W7tGQ43rk__HCezTDqFvFNSvxdNU841','/api/media/7afd00f8-2667-4003-ab6c-9109208f133d','/api/media/7afd00f8-2667-4003-ab6c-9109208f133d?variant=thumbnail','أنغام تعلن تفاصيل وموعد إطلاق ميني ألبوم دي روحي',1375,957,'valid','published','archived','valid',46,'f5c778f267c97c39182a9ebe2f75202798291cd2455daa846150f38a1da601ed','24a790a1add3bcf7f678f549e6