INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2c5596d1-5d8d-4ff6-bb4c-c2b23415781c','news-2c5596d1-5d8d-4ff6-bb4c-c2b23415781c','SDAIA Publications','sdaia publications','The "SDAIA Publications" page offers reliable and informative knowledge content that showcases the efforts of the Saudi Data & AI Authority in advancing the data and AI ecosystem within the Kingdom of Saudi Arabia.','["The \"SDAIA Publications\" page offers reliable and informative knowledge content that showcases the efforts of the Saudi Data & AI Authority in advancing the data and AI ecosystem within the Kingdom of Saudi Arabia. The page offers a collection of specialized publications designed to raise awareness, provide access to comprehensive information and recent developments, support decision-making, and realize the objectives of Saudi Vision 2030.","The publications include studies and reports highlighting the latest technological trends, guides that help practitioners apply best practices, and regulatory documents. The page also features the \"Glossary,\" which unifies technological concepts and enriches specialized Arabic content. It also includes \"Data & AI Radar,\" which tracks the latest data and AI technologies, classifies them by maturity and adoption, explains their uses, and highlights leading solution providers.","These publications serve as a valuable knowledge resource that supports the growth of the Kingdom’s technological sector and demonstr​ates SDAIA’s commitment to fostering knowledge integration by offering reliable content that meets the needs of decision-makers, enhances institutional performance, and promotes innovation across various sectors.​"]','الذكاء الاصطناعي','','fa86b2f1-ecdb-4cb4-9873-d22289ea127c','الهيئة السعودية للبيانات والذكاء الاصطناعي (سدايا)','https://sdaia.gov.sa/en/MediaCenter/KnowledgeCenter/Pages/SDAIAPublications.aspx','https://sdaia.gov.sa/en/MediaCenter/KnowledgeCenter/Pages/SDAIAPublications.aspx','','https://sdaia.gov.sa/en/MediaCenter/KnowledgeCenter/Pages/SDAIAPublications.aspx','','','2026-08-05T07:49:17.000Z',NULL,'2026-08-06T20:11:10.466Z','','','/api/media/fallback/%D8%A7%D9%84%D8%B0%D9%83%D8%A7%D8%A1%20%D8%A7%D9%84%D8%A7%D8%B5%D8%B7%D9%86%D8%A7%D8%B9%D9%8A','SDAIA Publications',NULL,NULL,'invalid_image_content_type','rejected','rejected','invalid',71,'f7be28dfab252de2e2c3f2f841e6cbfa3746f479e06784028c2fe6869647871f','bc9f30711432b11c47a7b379d33ee7a48e24fe389388439b47bbd47e32213a7a',NULL,'2026-08-06T20:11:10.466Z','2026-08-07T19:33:47.387Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'[]','[]','classified','','[]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
