INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ea899137-a752-42d7-a216-dd83408b0711','news-ea899137-a752-42d7-a216-dd83408b0711','SDAIA Role During Covid-19 Pandemic','sdaia role during covid 19 pandemic','The COVID-19 pandemic left far-reaching consequences and challenges beyond the spread of the disease itself.','["The COVID-19 pandemic left far-reaching consequences and challenges beyond the spread of the disease itself. It also called for many efforts to contain the spread of the virus. The beginning was difficult for everyone, as many challenges emerged consecutively, creating many exceptional circumstances that required an urgent response.","SDAIA effectively achieved many achievements rapidly through the initiatives it launched.","+1580 remote training seats have been benefited by \"SDAIA\" employees during the curfew period.","+190 thousand global experiences have been leveraged using data and artificial intelligence to combat the pandemic.","+200 thousand meetings were held remotely, which enabled the country''s leadership to hold meetings during the crisis through \"BOROOG\" platform.","+90 thousand electronic requests for the return of residents to their countries were submitted through \"AWDAH\" service.","+70 thousand electronic review requests submitted to the emirates regions and sectors of the Ministry of Interior.","+4 thousand electronic requests were submitted for the return of citizens stranded abroad."]','الذكاء الاصطناعي','','fa86b2f1-ecdb-4cb4-9873-d22289ea127c','الهيئة السعودية للبيانات والذكاء الاصطناعي (سدايا)','https://sdaia.gov.sa/en/MediaCenter/Pages/CoronaPandemic.aspx','https://sdaia.gov.sa/en/MediaCenter/Pages/CoronaPandemic.aspx','','https://sdaia.gov.sa/en/MediaCenter/Pages/CoronaPandemic.aspx','','','2026-08-05T07:49:17.000Z',NULL,'2026-08-06T20:11:11.874Z','','','/api/media/fallback/%D8%A7%D9%84%D8%B0%D9%83%D8%A7%D8%A1%20%D8%A7%D9%84%D8%A7%D8%B5%D8%B7%D9%86%D8%A7%D8%B9%D9%8A','SDAIA Role During Covid-19 Pandemic',NULL,NULL,'invalid_image_content_type','rejected','rejected','invalid',71,'7374750ebfa72b0154611ad07a729a949f6796581d05a4d08b15d6e592440357','8f29209414eeba68489d0b38cd8fcfe1ce52b06959d83fdebc5b2ca93d2faedb',NULL,'2026-08-06T20:11:11.874Z','2026-08-07T19:33:47.387Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["Role During","During Covid-19","Covid-19 Pandemic","Role During Covid-19","During Covid-19 Pandemic"]','["Role During","During Covid-19","Covid-19 Pandemic","Role During Covid-19","During Covid-19 Pandemic"]','classified','','[]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bc4e95c2-8a2b-4b56-8285-9ee030501a76','news-bc4e95c2-8a2b-4b56-8285-9ee030501a76','SDAIA AI Newsletter','sdaia ai newsletter','A weekly knowledge newsletter issued by the Saudi Data & AI Authority (SDAIA) that highlights key AI news and technological developments on the global stage.','["A weekly knowledge newsletter issued by the Saudi Data & AI Authority (SDAIA) that highlights key AI news and technological developments on the global stage. The newsletter draws on reliable sources that track and analyze developments in AI, covering technological innovations, regulatory policies, research trends, as well as reports, analyses, and advanced standards issued by leading authorities in the field.​","The newsletter aims to help interested individuals, decision-makers, and researchers stay abreast of the latest trends shaping the present and future of technology through focused weekly content that reflects global progress in the adoption of AI across various sectors.","This newsletter is also part of SDAIA’s continuous efforts to promote digital awareness and spread specialized knowledge, emphasizing the importance of keeping pace with global developments. This step is a cornerstone for shaping national policies, enhancing digital preparedness, and fostering knowledge integration, in alignment with the objectives of Saudi Vision 2030 to build a robust digital economy and a globally competitive knowledge society.​"]','الذكاء الاصطناعي','','fa86b2f1-ecdb-4cb4-9873-d22289ea127c','الهيئة السعودية للبيانات والذكاء الاصطناعي (سدايا)','https://sdaia.gov.sa/en/MediaCenter/KnowledgeCenter/Pages/AI-Newsletter.aspx','https://sdaia.gov.sa/en/MediaCenter/KnowledgeCenter/Pages/AI-Newsletter.aspx','','https://sdaia.gov.sa/en/MediaCenter/KnowledgeCenter/Pages/AI-Newsletter.aspx','','','2026-08-05T07:49:17.000Z',NULL,'2026-08-06T20:11:12.036Z','','','/api/media/fallback/%D8%A7%D9%84%D8%B0%D9%83%D8%A7%D8%A1%20%D8%A7%D9%84%D8%A7%D8%B5%D8%B7%D9%86%D8%A7%D8%B9%D9%8A','SDAIA AI Newsletter',NULL,NULL,'invalid_image_content_type','rejected','rejected','invalid',71,'f73045ab176b46ac4c5a39566aec4c997a24ed1ae38456f822bb890fb0f6569e','e0f99a08b296ee97bd527f213d3473fc9870bf1707b1152da5351db4622ba4e9',NULL,'2026-08-06T20:11:12.036Z','2026-08-07T19:33:47.387Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'[]','[]','classified','','[]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('263eca2a-517a-475b-b7cc-dfb9b2cb67b4','news-263eca2a-517a-475b-b7cc-dfb9b2cb67b4','The Year of AI','the year of ai','At its session held on Tuesday, March 10, 2026, chaired by His Royal Highness Prince Mohammed bin Salman bin Abdulaziz Al Saud, Crown Prince and Prime Minister, the Council of Ministers approved the designation of 2026 as the Year of Artificial Intelligence in Saudi Arabia, a step that reflects the Kingdom’s growing national focus on future technologies and','["The announcement builds on Saudi Arabia’s ongoing efforts to establish its position as a global hub for data and AI, in line with Saudi Vision 2030, which places advanced technologies at the forefront of the Kingdom’s national transformation and its drive to enhance global competitiveness.","The Saudi Data & AI Authority (SDAIA) is leading these efforts through the implementation of the National Strategy for Data & AI, the development of digital infrastructure, the advancement of national capabilities, and the promotion of innovation and investment in advanced technologies.","The Year of Artificial Intelligence 2026 reflects the accelerating national momentum toward harnessing AI technologies across a wide range of sectors, contributing to the development of a data-driven knowledge economy and enhancing quality of life.","\" I hereby invite all dreamers, innovators, investors, and thinkers to join us here in the Kingdom to achieve our ambitions together and to build a pioneering model; to unlock the value of data and AI. \"","\" The Council of Ministers’ resolution designating 2026 as the Year of Artificial Intelligence in Saudi Arabia reflects the vision of His Royal Highness Prince Mohammed bin Salman bin Abdulaziz Al Saud, Crown Prince, Prime Minister, and Chairman of SDAIA’s Board of Directors, to strengthen the Kingdom’s global leadership in advanced technologies. It also represents a significant step toward fostering broad national momentum for advanced technologies and their role in shaping a smarter, more sustainable future for the Kingdom.","The Year of Artificial Intelligence clearly underscores Saudi Arabia’s steadfast commitment to its scientific, civilizational, and humanitarian role in harnessing AI for the benefit of humanity, making it a powerful tool for building a better future for people everywhere. The national celebration of the Year of Artificial Intelligence also highlights the Kingdom’s position as an international hub for advanced technologies and a country that plays an influential role in shaping global decision-making in this field, as well as the positive impact it will have on our society and national economy.","AI has become one of the most powerful drivers of the global economy. Advanced nations increasingly rely on AI to strengthen their economies, empower their societies, enhance the quality of life, and improve the efficiency of vital sectors such as healthcare, education, transportation, energy, and security. It also accelerates innovation and strengthens global competitiveness. Saudi Arabia has emerged as one of the world’s leading nations in data and AI technologies and actively contributes to shaping international decision-making in this field through its participation and membership in a number of influential international organizations and committees.","I call upon all members of society, as well as the public and private sectors, to actively participate in the Year of Artificial Intelligence as a national occasion in which we all take pride. It represents a new chapter in the Kingdom’s journey of digital empowerment and provides an opportunity to unify national efforts and showcase Saudi Arabia’s capabilities and talent in data and AI. This will further position the Kingdom as a global platform that attracts international attention and reflects the aspirations of the Kingdom’s wise leadership to build a thriving, data- and AI-driven economy for the nation. \""]','الذكاء الاصطناعي','','fa86b2f1-ecdb-4cb4-9873-d22289ea127c','الهيئة السعودية للبيانات والذكاء الاصطناعي (سدايا)','https://sdaia.gov.sa/en/MediaCenter/Pages/ai-year.aspx','https://sdaia.gov.sa/en/MediaCenter/Pages/ai-year.aspx','','https://sdaia.gov.sa/en/MediaCenter/Pages/ai-year.aspx','','','2026-08-05T07:49:17.000Z',NULL,'2026-08-06T20:11:12.114Z','','','/api/media/fallback/%D8%A7%D9%84%D8%B0%D9%83%D8%A7%D8%A1%20%D8%A7%D9%84%D8%A7%D8%B5%D8%B7%D9%86%D8%A7%D8%B9%D9%8A','The Year of AI',NULL,NULL,'invalid_image_content_type','rejected','rejected','invalid',71,'e20d63d36577c6ecebb7294eeb976146780e242940f7e9acebbc58d0ee427604','de63df4f1710004a17a3110932d14d6b10de77db9cc1439ad87c09471aa58388',NULL,'2026-08-06T20:11:12.114Z','2026-08-07T19:33:47.387Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'[]','[]','classified','','[]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
