tiatives',NULL,NULL,'invalid_image_content_type','rejected','rejected','invalid',71,'a66a39f2c0d35e67828b40216793794b5d54a36eb460ff473d702a0b0664c191','14ca5ceb5cbd08f56ad6c54293711f213010024897817f9c27f0e3aa07e57406',NULL,'2026-08-06T20:11:13.623Z','2026-08-07T19:33:47.387Z','','',0,0,'saudi_national','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'[]','[]','classified','','[]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('67176b86-41d3-491a-a481-3e3a294c5b79','news-67176b86-41d3-491a-a481-3e3a294c5b79','الأهلي يطالب ماتياس بـ 12 مليون يورو والهولندي بوسيتش بديلا عنه','الاهلي يطالب ماتياس بـ 12 مليون يورو والهولندي بوسيتش بديلا عنه','تبلغ قيمة الشرط الجزائي التي ستتلقاها خزينة النادي الأهلي السعودي من الألماني ماتياس يايسله 12 مليون يورو، وذلك جراء فسخ عقده التدريبي قبيل انتهاء المدة، وفقاً لمصادر \\\"الاقتصادية\\\".','["يايسله فسخ عقده مع الأهلي قبيل بدء منافسات الموسم الرياضي الجديد بأسبوعين تحديداً بعد نهاية المعسكر الإعدادي للفريق الذي أقيم في البرتغال.","وبحسب المصادر: \\\\\\\"الأهلي يطالب المدرب ماتياس يايسله بقيمة الشرط الجزائي المقدّرة بـ12 مليون يورو وفق بنود العقد بينه وبين النادي\\\\\\\".","وقالت: \\\\\\\"ينبغي على ماتياس يايسله سداد المبلغ خلال 30 يوما والتي تأتي وفق المدة الزمينة للسداد بناء على ما نصّ عليه العقد\\\\\\\".","بوسيتش مدرباً للأهلي أنهت إدارة النادي الأهلي إجراءات التعاقد مع الهولندي مارينو بوسيتش مدرباً لفريق كرة القدم حتى يونيو 2028، وذلك وفقاً للموقع الرسمي للنادي الأهلي في منصة \\\\\\\"إكس\\\\\\\"."]','الرياضة','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%A7%D9%84%D8%B1%D9%8A%D8%A7%D8%B6%D8%A9/%D8%A7%D9%84%D8%A3%D9%87%D9%84%D9%8A-%D9%8A%D8%B7%D8%A7%D9%84%D8%A8-%D9%85%D8%A7%D8%AA%D9%8A%D8%A7%D8%B3-%D8%A8-12-%D9%85%D9%84%D9%8A%D9%88%D9%86-%D9%8A%D9%88%D8%B1%D9%88-%D9%88%D8%A7%D9%84%D9%87%D9%88%D9%84%D9%86%D8%AF%D9%8A-%D8%A8%D9%88%D8%B3%D9%8A%D8%AA%D8%B4-%D8%A8%D8%AF%D9%8A%D9%84%D8%A7-%D8%B9%D9%86%D9%87-12908','https://www.aleqt.com/%D8%A7%D9%84%D8%B1%D9%8A%D8%A7%D8%B6%D8%A9/%D8%A7%D9%84%D8%A3%D9%87%D9%84%D9%8A-%D9%8A%D8%B7%D8%A7%D9%84%D8%A8-%D9%85%D8%A7%D8%AA%D9%8A%D8%A7%D8%B3-%D8%A8-12-%D9%85%D9%84%D9%8A%D9%88%D9%86-%D9%8A%D9%88%D8%B1%D9%88-%D9%88%D8%A7%D9%84%D9%87%D9%88%D9%84%D9%86%D8%AF%D9%8A-%D8%A8%D9%88%D8%B3%D9%8A%D8%AA%D8%B4-%D8%A8%D8%AF%D9%8A%D9%84%D8%A7-%D8%B9%D9%86%D9%87-12908','','https://www.aleqt.com/%D8%A7%D9%84%D8%B1%D9%8A%D8%A7%D8%B6%D8%A9/%D8%A7%D9%84%D8%A3%D9%87%D9%84%D9%8A-%D9%8A%D8%B7%D8%A7%D9%84%D8%A8-%D9%85%D8%A7%D8%AA%D9%8A%D8%A7%D8%B3-%D8%A8-12-%D9%85%D9%84%D9%8A%D9%88%D9%86-%D9%8A%D9%88%D8%B1%D9%88-%D9%88%D8%A7%D9%84%D9%87%D9%88%D9%84%D9%86%D8%AF%D9%8A-%D8%A8%D9%88%D8%B3%D9%8A%D8%AA%D8%B4-%D8%A8%D8%AF%D9%8A%D9%84%D8%A7-%D8%B9%D9%86%D9%87-12908','','السعودية','2026-08-06T17:01:00.000Z',NULL,'2026-08-06T20:20:55.922Z','https://static.aleqt.com/aleqt/uploads/images/2026/08/06/2234448.webp?w=800&q=75','/api/media/67176b86-41d3-491a-a481-3e3a294c5b79','/api/media/67176b86-41d3-491a-a481-3e3a294c5b79?variant=thumbnail','الأهلي يطالب ماتياس بـ 12 مليون يورو والهولندي بوسيتش بديلا عنه',1200,1500,'valid','published','archived','valid',95,'7346b91e125332f2ce7fcde01c6439d7ed46682d586f39a63cec7fe710d35e02','21b41775218d700679f77456bb412b00de0960616049d2b53d0064e01a42f427',NULL,'2026-08-06T20:20:55.922Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','classified','','[{"category":"العالم","score":3},{"category":"التعليم","score":1.5},{"category":"الثقافة","score":1.5}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7857642e-46b3-46e5-a7a3-6d9485507cd1','news-7857642e-46b3-46e5-a7a3-6d9485507cd1','ترمب يجري اتصالات مع وارش وسط مساعٍ لتعزيز نفوذه على الفيدرالي','ترمب يجري اتصالات مع وارش وسط مساع لتعزيز نفوذه علي الفيدرالي','أجرى الرئيس الأمريكي دونالد ترمب اتصالات هاتفية بشكل دوري مع رئيس مجلس الاحتياطي الفيدرالي كيفن وارش منذ توليه المنصب، بحسب أشخاص مطلعين، في أحدث مؤشر على سعي ترمب إلى ممارسة نفوذ أكبر على البنك المركزي.','["وأوضح أحد الأشخاص، الذي طلب عدم الكشف عن هويته نظراً لخصوصية المحادثات، أن ترمب ووارش تحدثا عدة مرات منذ تعيين الأخير في منصبه في مايو، حيث استفسر ترمب عن توقعات وارش وآرائه، من دون أن يضغط عليه لاتخاذ مسار محدد. وقال شخص آخر إن الاتصالات بينهما تتم على فترات غير منتظمة، فيما أشار ثالث إلى أن المكالمات متباعدة، ولا يزال من غير الواضح ما إذا كانا قد ناقشا السياسة النقدية.","قال المتحدث باسم البيت الأبيض كوش ديساي في بيان أرسله عبر البريد الإلكتروني: \\\\\\\"أكد الرئيس ترمب مراراً أنه يمنح رئيس الفيدرالي وارش المساحة التي يحتاجها لاستعادة الثقة والكفاءة في عملية صنع القرار داخل الاحتياطي الفيدرالي. وبينما يتمتع الرئيس بحقه المكفول، بموجب التعديل الأول للدستور الأمريكي في التعبير عن آرائه بشأن الفيدرالي كمواطن أميركي، ويضطلع بواجبه بصفته القائد الأعلى للقوات المسلحة، فإنه أكد مراراً…","وامتنع الاحتياطي الفيدرالي عن التعليق. وكانت صحيفة \\\\\\\"وول ستريت جورنال\\\\\\\" أول من أورد نبأ هذه الاتصالات.","رغم أن طبيعة المحادثات بين ترمب ووارش لا تزال غير واضحة بالكامل، فإن ترمب دأب منذ فترة طويلة على مطالبة الاحتياطي الفيدرالي بخفض أسعار الفائدة. ورغم أن رؤساء الولايات المتحدة ورؤساء الاحتياطي الفيدرالي سبق أن أجروا اتصالات واجتماعات في الماضي، فإنها كانت نادرة، إلا أن مساعي ترمب للتأثير على السياسة النقدية تُعدّ أقوى تدخل في عملية صنع القرار داخل البنك المركزي منذ عقود."]','الاقتصاد','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82/%D8%AA%D8%B1%D9%85%D8%A8-%D9%8A%D8%AC%D8%B1%D9%8A-%D8%A7%D8%AA%D8%B5%D8%A7%D9%84%D8%A7%D8%AA-%D9%85%D8%B9-%D9%88%D8%A7%D8%B1%D8%B4-%D9%88%D8%B3%D8%B7-%D9%85%D8%B3%D8%A7%D8%B9-%D9%84%D8%AA%D8%B9%D8%B2%D9%8A%D8%B2-%D9%86%D9%81%D9%88%D8%B0%D9%87-%D8%B9%D9%84%D9%89-%D8%A7%D9%84%D9%81%D9%8A%D8%AF%D8%B1%D8%A7%D9%84%D9%8A-12907','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82/%D8%AA%D8%B1%D9%85%D8%A8-%D9%8A%D8%AC%D8%B1%D9%8A-%D8%A7%D8%AA%D8%B5%D8%A7%D9%84%D8%A7%D8%AA-%D9%85%D8%B9-%D9%88%D8%A7%D8%B1%D8%B4-%D9%88%D8%B3%D8%B7-%D9%85%D8%B3%D8%A7%D8%B9-%D9%84%D8%AA%D8%B9%D8%B2%D9%8A%D8%B2-%D9%86%D9%81%D9%88%D8%B0%D9%87-%D8%B9%D9%84%D9%89-%D8%A7%D9%84%D9%81%D9%8A%D8%AF%D8%B1%D8%A7%D9%84%D9%8A-12907','','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82/%D8%AA%D8%B1%D9%85%D8%A8-%D9%8A%D8%AC%D8%B1%D9%8A-%D8%A7%D8%AA%D8%B5%D8%A7%D9%84%D8%A7%D8%AA-%D9%85%D8%B9-%D9%88%D8%A7%D8%B1%D8%B4-%D9%88%D8%B3%D8%B7-%D9%85%D8%B3%D8%A7%D8%B9-%D9%84%D8%AA%D8%B9%D8%B2%D9%8A%D8%B2-%D9%86%D9%81%D9%88%D8%B0%D9%87-%D8%B9%D9%84%D9%89-%D8%A7%D9%84%D9%81%D9%8A%D8%AF%D8%B1%D8%A7%D9%