INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fe31cff2-5629-4c89-bb1a-a14c7d1aaa8e','news-fe31cff2-5629-4c89-bb1a-a14c7d1aaa8e','تنافس 19 شركة ناشئة على مليون ريال في حاضنة وادي جدة للابتكار','تنافس 19 شركه ناشئه علي مليون ريال في حاضنه وادي جده للابتكار','تتنافس 19 شركة ناشئة ضمن معسكر حاضنة وادي جدة للابتكار التابعة لشركة وادي جدة، المملوكة لجامعة الملك عبدالعزيز للفوز باستثمارات بقيمة مليون ريال.','["كما يجري العمل على إطلاق صندوق استثماري جديد بالشراكة مع جهة خاصة للاستثمار المباشر في الشركات الناشئة، وذلك ضمن جهود دعم منظومة ريادة الأعمال والابتكار، بحسب ماذكره لـ \\\\\\\"الاقتصادية\\\\\\\" أحمد مرسي، مدير برامج ريادة الأعمال والمشرف على مجمع وادي جدة للابتكار.","أوضح مرسي، على هامش إطلاق معسكر حاضنه وادي جدة للابتكار، الذي سيختتم أعماله الأحد القادم الموافق ٩ أغسطس، أن المعسكر سيختتم باختيار 10 شركات من أصل 19 شركة مشاركة، سيعلن عنها الأحد القادم.","وستحصل كل منها على 100 ألف ريال، بمجموع مليون ريال، إلى جانب برنامج احتضان يمتد 6 أشهر يتضمن التأهيل الاستثماري، وتطوير المنتجات، ورفع جاهزية المؤسسين، وتقديم الخدمات التي تتناسب مع احتياجات كل شركة.","وأضاف أن الحاضنة تضم حاليا 30 شركة ناشئة، وسيرتفع العدد إلى 40 شركة بعد انضمام الدفعة الجديدة، ونستهدف أن تصل عدد الشركات إلى 70 شركة في نهاية 2026."]','الاقتصاد','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D8%AA%D9%86%D8%A7%D9%81%D8%B3-19-%D8%B4%D8%B1%D9%83%D8%A9-%D9%86%D8%A7%D8%B4%D8%A6%D8%A9-%D8%B9%D9%84%D9%89-%D9%85%D9%84%D9%8A%D9%88%D9%86-%D8%B1%D9%8A%D8%A7%D9%84-%D9%81%D9%8A-%D8%AD%D8%A7%D8%B6%D9%86%D8%A9-%D9%88%D8%A7%D8%AF%D9%8A-%D8%AC%D8%AF%D8%A9-%D9%84%D9%84%D8%A7%D8%A8%D8%AA%D9%83%D8%A7%D8%B1-12909','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D8%AA%D9%86%D8%A7%D9%81%D8%B3-19-%D8%B4%D8%B1%D9%83%D8%A9-%D9%86%D8%A7%D8%B4%D8%A6%D8%A9-%D8%B9%D9%84%D9%89-%D9%85%D9%84%D9%8A%D9%88%D9%86-%D8%B1%D9%8A%D8%A7%D9%84-%D9%81%D9%8A-%D8%AD%D8%A7%D8%B6%D9%86%D8%A9-%D9%88%D8%A7%D8%AF%D9%8A-%D8%AC%D8%AF%D8%A9-%D9%84%D9%84%D8%A7%D8%A8%D8%AA%D9%83%D8%A7%D8%B1-12909','','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D8%AA%D9%86%D8%A7%D9%81%D8%B3-19-%D8%B4%D8%B1%D9%83%D8%A9-%D9%86%D8%A7%D8%B4%D8%A6%D8%A9-%D8%B9%D9%84%D9%89-%D9%85%D9%84%D9%8A%D9%88%D9%86-%D8%B1%D9%8A%D8%A7%D9%84-%D9%81%D9%8A-%D8%AD%D8%A7%D8%B6%D9%86%D8%A9-%D9%88%D8%A7%D8%AF%D9%8A-%D8%AC%D8%AF%D8%A9-%D9%84%D9%84%D8%A7%D8%A8%D8%AA%D9%83%D8%A7%D8%B1-12909','','السعودية','2026-08-06T17:07:00.000Z','2026-08-06T17:55:36.000Z','2026-08-06T20:20:56.638Z','https://static.aleqt.com/aleqt/uploads/images/2026/08/06/2234453.webp?w=800&q=75','/api/media/fe31cff2-5629-4c89-bb1a-a14c7d1aaa8e','/api/media/fe31cff2-5629-4c89-bb1a-a14c7d1aaa8e?variant=thumbnail','تنافس 19 شركة ناشئة على مليون ريال في حاضنة وادي جدة للابتكار',1200,900,'valid','published','archived','valid',95,'aa0ae13a6c3fe10e4bdf4e85097d6751574179d256516a07e3f44990bba06b18','119a2d6b52b64fb317136f4a214def8c4036a662dbff66e1d8b4848d8dca49f7',NULL,'2026-08-06T20:20:56.638Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة ناشئة على مليون ريال","الاقتصاد والأسواق","جدة"]','["شركة ناشئة على مليون ريال","الاقتصاد والأسواق"]','classified','','[{"category":"المناطق","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"التعليم","score":1.5}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('941f577b-db51-4727-8271-f9e05408b61c','news-941f577b-db51-4727-8271-f9e05408b61c','طيران الرياض يوقع اتفاقية مع "ترافل سكاي" لاستكشاف الفرص في الصين','طيران الرياض يوقع اتفاقيه مع ترافل سكاي لاستكشاف الفرص في الصين','وقّع طيران الرياض اليوم اتفاقية تعاون في مجال التوزيع مع شركة \\\"ترافل سكاي تكنولوجي المحدودة\\\"، حيث جرت مراسم التوقيع في العاصمة الصينية بكين.','["وسيستفيد طيران الرياض -بموجب الاتفاقية- من منظومة الخدمات الشاملة والقدرات التقنية لشركة \\\\\\\"ترافل سكاي\\\\\\\" في قطاعي السفر الجوي والسياحة، للتعاون في مجالات التوزيع عبر قنوات متعددة، وخدمات التجزئة الحديثة لشركات الطيران، والابتكار الرقمي، وتطوير تجربة الضيوف.","الاتفاقية تدعم دخول طيران الرياض إلى السوق الصينية، ويحسن تجربة وكالات السفر الصينية وشركاء القطاع والضيوف المسافرين، إلى جانب استكشاف فرص جديدة تدعم التوسع الدولي المستمر لشبكة طيران الرياض، وتحفز نموها في السوق الصينية."]','السفر','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','ht