INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4f498c93-e1e4-44b5-beef-a45ac9385245','news-4f498c93-e1e4-44b5-beef-a45ac9385245','أرباح "المملكة القابضة" تتراجع 17.7% في الربع الثاني','ارباح المملكه القابضه تتراجع 17 7 في الربع الثاني','تراجعت الأرباح الصافية لشركة "المملكة القابضة" السعودية 17.7% على أساس سنوي إلى نحو 333 مليون ريال في الربع الثاني من العام الماضي، وفقا للنتائج المالية المعلنة من قبل الشركة على "تداول" اليوم الخميس.','["الشركة أرجعت تراجع صافي الربح إلى عوامل بينها الانخفاض في ربح من بيع شركة مستثمر فيها بطريقة حقوق الملكية، والانخفاض في إيرادات توزيعات أرباح، والارتفاع في ضريبة الاستقطاع وضريبة الدخل، والانخفاض في ربح من بيع عقارات استثمارية، إضافة إلى الارتفاع في مصاريف عمومية وإدارية وتسويقية.","الإيرادات الفصلية ارتفعت 1.34% على أساس سنوي إلى 631 مليون ريال في الربع الثاني من العام، مع ارتفاع إيرادات الفنادق والإيرادات التشغيلية الأخرى، على الرغم من الانخفاض في إيرادات توزيعات الأرباح.","طالع أيضا: الوليد بن طلال يراهن على «لوسيد» في ذروة المخاوف"]','الاقتصاد','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%A7%D9%84%D8%B4%D8%B1%D9%83%D8%A7%D8%AA/%D8%A3%D8%B1%D8%A8%D8%A7%D8%AD-%D8%A7%D9%84%D9%85%D9%85%D9%84%D9%83%D8%A9-%D8%A7%D9%84%D9%82%D8%A7%D8%A8%D8%B6%D8%A9-%D8%AA%D8%AA%D8%B1%D8%A7%D8%AC%D8%B9-177-%D9%81%D9%8A-%D8%A7%D9%84%D8%B1%D8%A8%D8%B9-%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A-12905','https://www.aleqt.com/%D8%A7%D9%84%D8%B4%D8%B1%D9%83%D8%A7%D8%AA/%D8%A3%D8%B1%D8%A8%D8%A7%D8%AD-%D8%A7%D9%84%D9%85%D9%85%D9%84%D9%83%D8%A9-%D8%A7%D9%84%D9%82%D8%A7%D8%A8%D8%B6%D8%A9-%D8%AA%D8%AA%D8%B1%D8%A7%D8%AC%D8%B9-177-%D9%81%D9%8A-%D8%A7%D9%84%D8%B1%D8%A8%D8%B9-%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A-12905','','https://www.aleqt.com/%D8%A7%D9%84%D8%B4%D8%B1%D9%83%D8%A7%D8%AA/%D8%A3%D8%B1%D8%A8%D8%A7%D8%AD-%D8%A7%D9%84%D9%85%D9%85%D9%84%D9%83%D8%A9-%D8%A7%D9%84%D9%82%D8%A7%D8%A8%D8%B6%D8%A9-%D8%AA%D8%AA%D8%B1%D8%A7%D8%AC%D8%B9-177-%D9%81%D9%8A-%D8%A7%D9%84%D8%B1%D8%A8%D8%B9-%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A-12905','','السعودية','2026-08-06T15:36:00.000Z','2026-08-06T17:22:30.000Z','2026-08-06T20:20:59.962Z','https://static.aleqt.com/aleqt/uploads/images/2026/08/06/2234431.webp?w=800&q=75','/api/media/4f498c93-e1e4-44b5-beef-a45ac9385245','/api/media/4f498c93-e1e4-44b5-beef-a45ac9385245?variant=thumbnail','أرباح "المملكة القابضة" تتراجع 17.7% في الربع الثاني',1200,675,'valid','published','archived','valid',54,'8bf23141abc3647a5d4d470d3df887c9156fd217cc610ea57c3349e028deb00f','c027b72136da35481c7cf9a8799e41de3ece85369eea631295f7ac65d0ed26be',NULL,'2026-08-06T20:20:59.962Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة مستثمر فيها بطريقة حقوق","الاقتصاد والأسواق"]','["شركة مستثمر فيها بطريقة حقوق","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"السيارات","score":2},{"category":"المناطق","score":0}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('100afc6c-f35b-4eab-be79-a65ae8c16213','news-100afc6c-f35b-4eab-be79-a65ae8c16213','"ألفابت" تسعى لجمع 25 مليار دولار في اختبار لسندات الذكاء الاصطناعي','الفابت تسعي لجمع 25 مليار دولار في اختبار لسندات الذكاء الاصطناعي','سعى شركة "ألفابت" (Alphabet) لجمع ما يصل إلى 25 مليار دولار من أحدث طرح لها لسندات أمريكية من الدرجة الاستثمارية، وفقاً لأشخاص مطلعين على الأمر، في صفقة ستختبر إقبال المستثمرين على الديون المرتبطة ب الذكاء الاصطناعي بعد موجة البيع التي شهدها يوليو.','["وأضاف الأشخاص، الذين طلبوا عدم الكشف عن هوياتهم لعدم تخويلهم بالتحدث علناً، أنه لم يُتخذ قرار نهائي بشأن حجم الطرح.","الشركة الأم لـ\"جوجل\" (Google) و\"يوتيوب\" (YouTube) تطرح سندات على ما يصل إلى 10 شرائح، بآجال استحقاق تتراوح بين عامين و40 عاماً، وفقاً لشخص آخر. وتشير المناقشات الأولية بشأن التسعير إلى علاوة تبلغ نحو 1.55 نقطة مئوية فوق عوائد سندات الخزانة للشريحة الأطول أجلاً.","يأتي طرح \"ألفابت\" بعد أسبوعين من رفع الشركة توقعاتها للإنفاق في 2026، وهو ما ساهم في إثارة مخاوف جديدة بشأن ما إذا كانت الاستثمارات الضخمة في الذكاء الاصطناعي ستؤتي ثمارها. وتراجع إقبال المستثمرين في يوليو على السندات التي تساعد في تمويل هذا الإنفاق، بعدما رفعت \"ألفابت\" توقعاتها إلى ما يصل إلى 205 مليارات دولار، أي أكثر من ضعف إنفاقها في 2025."]','الذكاء الاصطناعي','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%A7%D9%84%D8%AA%D9%83%D9%86%D9%88%D9%84%D9%88%D8%AC%D9%8A%D8%A7/%D8%A3%D9%84%D9%81%D8%A7%D8%A8%D8%AA-%D8%AA%D8%B3%D8%B9%D9%89-%D9%84%D8%AC%D9%85%D8%B9-25-%D9%85%D9%84%D9%8A%D8%A7%D8%B1-%D8%AF%D9%88%D9%84%D8%A7%D8%B1-%D9%81%D9%8A-%D8%A7%D8%AE%D8%AA%D8%A8%D8%A7%D8%B1-%D9%84%D8%B3%D9%86%D8%AF%D8%A7%D8%AA-%D8%A7%D9%84%D8%B0%D9%83%D8%A7%D8%A1-%D8%A7%D9%84%D8%A7%D8%B5%D8%B7%D9%86%D8%A7%D8%B9%D9%8A-12906','https://www.aleqt.com/%D8%A7%D9%84%D8%AA%D9%83%D9%86%D9%88%D9%84%D9%88%D8%AC%D9%8A%D8%A7/%D8%A3%D9%84%D9%81%D8%A7%D8%A8%D8%AA-%D8%AA%D8%B3%D8%B9%D9%89-%D9%84%D8%AC%D9%85%D8%B9-25-%D9%85%D9%84%D9%8A%D8%A7%D8%B1-%D8%AF%D9%88%D9%84%D8%A7%D8%B1-%D9%81%D9%8A-%D8%A7%D8%AE%D8%AA%D8%A8%D8%A7%D8%B1-%D9%84%D8%B3%D9%86%D8%AF%D8%A7%D8%AA-%D8%A7%D9%84%D8%B0%D9%83%D8%A7%D8%A1-%D8%A7%D9%84%D8%A7%D8%B5%D8%B7%D9%86%D8%A7%D8%B9%D9%8A-12906','','https://www.aleqt.com/%D8%A7%D9%84%D8%AA%D9%83%D9%86%D9%88%D9%84%D9%88%D8%AC%D9%8A%D8%A7/%D8%A3%D9%84%D9%81%D8%A7%D8%A8%D8%AA-%D8%AA%D8%B3%D8%B9%D9%89-%D9%84%D8%AC%D9%85%D8%B9-25-%D9%85%D9%84%D9%8A%D8%A7%D8%B1-%D8%AF%D9%88%D9%84%D8%A7%D8%B1-%D9%81%D9%8A-%D8%A7%D8%AE%D8%AA%D8%A8%D8%A7%D8%B1-%D9%84%D8%B3%D9%86%D8%AF%D8%A7%D8%AA-%D8%A7%D9%84%D8%B0%D9%83%D8%A7%D8%A1-%D8%A7%D9%84%D8%A7%D8%B5%D8%B7%D9%86%D8%A7%D8%B9%D9%8A-12906','','السعودية','2026-08-06T16:23:00.000Z',NULL,'2026-08-06T20:21:00.255Z','https://static.aleqt.com/aleqt/uploads/images/2026/08/06/2234439.webp?w=800&q=75','/api/media/100afc6c-f35b-4eab-be79-a65ae8c16213','/api/media/100afc6c-f35b-4eab-be79-a65ae8c16213?variant=thumbnail','"ألفابت" تسعى لجمع 25 مليار دولار في اختبار لسندات الذكاء الاصطناعي',1200,677,'va