INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e37a1b65-eedf-426d-82b7-4026d29c10a8','news-e37a1b65-eedf-426d-82b7-4026d29c10a8','السفير الصيني: إنشاء منظومات لمبيعات سياراتنا في السعودية','السفير الصيني انشاء منظومات لمبيعات سياراتنا في السعوديه','كشف السفير الصيني في الرياض تشانغ هوا، أن شركات السيارات الصينية تعمل مع شركائها السعودية على إنشاء منظومات للمبيعات وخدمات ما بعد البيع والتدريب، بما يوفر الدعم التقني ويسهم في إعداد الكفاءات لتطوير صناعة مركبات الطاقة الجديدة في السعودية.','["وقال في حوار مع \\\\\\\"الاقتصادية\\\\\\\"، إن بلاده حافظت على مكانتها كأكبر شريك تجاري للسعودية للعام الـ13 على التوالي، فيما تجاوز حجم التجارة الثنائية 100 مليار دولار لـ4 سنوات متتالية.","أكد تشانغ هوا أن المنتجات الصينية، وفي مقدمتها المعدات الميكانيكية والكهربائية، والسيارات، ومنتجات الحديد والصلب، والأثاث، أصبحت من أبرز السلع في السوق السعودية، مشيراً إلى أن السعودية تصدرت الدول المستوردة للسيارات الصينية من حيث عدد المركبات، في ظل تنامي إقبال المستهلكين السعوديين عليها.","وأشار إلى أن حجم التبادل التجاري بين البلدين بلغ 108.1 مليار دولار خلال 2025، مع اقترابه من 50 مليار دولار خلال النصف الأول من العام الجاري.","السفير الصيني لفت إلى أن المرحلة المقبلة ستشهد توسعاً أكبر في التعاون بين البلدين في قطاعات التصنيع، والاقتصاد الرقمي، والذكاء الاصطناعي، والطاقة الجديدة، والتقنيات المتقدمة، ضمن مواءمة \\\\\\\"رؤية السعودية 2030\\\\\\\" مع مبادرة \\\\\\\"الحزام والطريق\\\\\\\" .. فإلى نص الحوار:"]','أخبار السعودية','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%AA%D8%AD%D9%82%D9%8A%D9%82%D8%A7%D8%AA-%D9%88%D8%AD%D9%88%D8%A7%D8%B1%D8%A7%D8%AA/%D8%A7%D9%84%D8%B3%D9%81%D9%8A%D8%B1-%D8%A7%D9%84%D8%B5%D9%8A%D9%86%D9%8A-%D8%A5%D9%86%D8%B4%D8%A7%D8%A1-%D9%85%D9%86%D8%B8%D9%88%D9%85%D8%A7%D8%AA-%D9%84%D9%85%D8%A8%D9%8A%D8%B9%D8%A7%D8%AA-%D8%B3%D9%8A%D8%A7%D8%B1%D8%A7%D8%AA%D9%86%D8%A7-%D9%81%D9%8A-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-12858','https://www.aleqt.com/%D8%AA%D8%AD%D9%82%D9%8A%D9%82%D8%A7%D8%AA-%D9%88%D8%AD%D9%88%D8%A7%D8%B1%D8%A7%D8%AA/%D8%A7%D9%84%D8%B3%D9%81%D9%8A%D8%B1-%D8%A7%D9%84%D8%B5%D9%8A%D9%86%D9%8A-%D8%A5%D9%86%D8%B4%D8%A7%D8%A1-%D9%85%D9%86%D8%B8%D9%88%D9%85%D8%A7%D8%AA-%D9%84%D9%85%D8%A8%D9%8A%D8%B9%D8%A7%D8%AA-%D8%B3%D9%8A%D8%A7%D8%B1%D8%A7%D8%AA%D9%86%D8%A7-%D9%81%D9%8A-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-12858','','https://www.aleqt.com/%D8%AA%D8%AD%D9%82%D9%8A%D9%82%D8%A7%D8%AA-%D9%88%D8%AD%D9%88%D8%A7%D8%B1%D8%A7%D8%AA/%D8%A7%D9%84%D8%B3%D9%81%D9%8A%D8%B1-%D8%A7%D9%84%D8%B5%D9%8A%D9%86%D9%8A-%D8%A5%D9%86%D8%B4%D8%A7%D8%A1-%D9%85%D9%86%D8%B8%D9%88%D9%85%D8%A7%D8%AA-%D9%84%D9%85%D8%A8%D9%8A%D8%B9%D8%A7%D8%AA-%D8%B3%D9%8A%D8%A7%D8%B1%D8%A7%D8%AA%D9%86%D8%A7-%D9%81%D9%8A-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-12858','','السعودية','2026-08-06T14:24:00.000Z',NULL,'2026-08-06T20:21:02.922Z','https://static.aleqt.com/aleqt/uploads/images/2026/08/05/2234032.webp?w=800&q=75','/api/media/e37a1b65-eedf-426d-82b7-4026d29c10a8','/api/media/e37a1b65-eedf-426d-82b7-4