INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5122baae-f0c6-45e1-9424-aee3bdfc6846','news-5122baae-f0c6-45e1-9424-aee3bdfc6846','الأسهم السعودية تكسر أطول سلسلة ارتفاع في 5 أشهر بضغط من "أرامكو"','الاسهم السعوديه تكسر اطول سلسله ارتفاع في 5 اشهر بضغط من ارامكو','أنهت الأسهم السعودية سلسلة مكاسب امتدت 5 جلسات، بعدما تحولت البداية الإيجابية إلى موجة بيع شملت معظم السوق، كاسرة أطول سلسلة ارتفاع في 5 أشهر.','["أنهت الأسهم السعودية سلسلة مكاسب امتدت 5 جلسات، بعدما تحولت البداية الإيجابية إلى موجة بيع شملت معظم السوق. وجاء الضغط الأكبر من سهم \\\\\\\"أرامكو\\\\\\\" إلى جانب \\\\\\\"أكوا\\\\\\\".","وأغلق مؤشر \\\\\\\"تاسي\\\\\\\" عند 10811 نقطة، متراجعا 0.7%، في أكبر انخفاض يومي خلال أسبوع.","وجاء التراجع بعد أطول سلسلة صعود للمؤشر في نحو خمسة أشهر. إلا أن السوق لم تستطع الحفاظ على مكاسبها المبكرة.","وما لم تتغير العوامل، قد يمتد التراجع إلى مستويات 10750 نقطة، ثم تبحث السوق لإعادة اختبار 10900 نقطة وصولا إلى مستويات قريبة من 11 ألف نقطة."]','أخبار السعودية','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82/%D8%A7%D9%84%D8%A3%D8%B3%D9%87%D9%85-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%AA%D9%83%D8%B3%D8%B1-%D8%A3%D8%B7%D9%88%D9%84-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D8%A7%D8%B1%D8%AA%D9%81%D8%A7%D8%B9-%D9%81%D9%8A-5-%D8%A3%D8%B4%D9%87%D8%B1-%D8%A8%D8%B6%D8%BA%D8%B7-%D9%85%D9%86-%D8%A3%D8%B1%D8%A7%D9%85%D9%83%D9%88-12902','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82/%D8%A7%D9%84%D8%A3%D8%B3%D9%87%D9%85-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%AA%D9%83%D8%B3%D8%B1-%D8%A3%D8%B7%D9%88%D9%84-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D8%A7%D8%B1%D8%AA%D9%81%D8%A7%D8%B9-%D9%81%D9%8A-5-%D8%A3%D8%B4%D9%87%D8%B1-%D8%A8%D8%B6%D8%BA%D8%B7-%D9%85%D9%86-%D8%A3%D8%B1%D8%A7%D9%85%D9%83%D9%88-12902','','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%B3%D9%88%D8%A7%D9%82/%D8%A7%D9%84%D8%A3%D8%B3%D9%87%D9%85-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%AA%D9%83%D8%B3%D8%B1-%D8%A3%D8%B7%D9%88%D9%84-%D8%B3%D9%84%D8%B3%D9%84%D8%A9-%D8%A7%D8%B1%D8%AA%D9%81%D8%A7%D8%B9-%D9%81%D9%8A-5-%D8%A3%D8%B4%D9%87%D8%B1-%D8%A8%D8%B6%D8%BA%D8%B7-%D9%85%D9%86-%D8%A3%D8%B1%D8%A7%D9%85%D9%83%D9%88-12902','','السعودية','2026-08-06T14:05:00.000Z','2026-08-06T15:10:12.000Z','2026-08-06T20:21:03.536Z','https://static.aleqt.com/aleqt/uploads/images/2026/08/06/2234425.webp?w=800&q=75','/api/media/5122baae-f0c6-45e1-9424-aee3bdfc6846','/api/media/5122baae-f0c6-45e1-9424-aee3bdfc6846?variant=thumbnail','الأسهم السعودية تكسر أطول سلسلة ارتفاع في 5 أشهر بضغط من "أرامكو"',1200,675,'valid','published','archived','valid',56,'6d6f2d0bf3feb278138869f4069236a42e544db9df4a542c30551bcb1bf32e53','576203b79742d657b5d9f3811d6d9cb39d6f0edcba60d2a86bf0e7d81fd7c554',NULL,'2026-08-06T20:21:03.536Z','2026-10-07T20:24:27.524Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"categor