INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b7b01b02-52dd-4eee-aad9-fad5dfdc7059','news-b7b01b02-52dd-4eee-aad9-fad5dfdc7059','أرباح "أكوا" السعودية تتراجع 28% في النصف الأول مع توسع محفظتها','ارباح اكوا السعوديه تتراجع 28 في النصف الاول مع توسع محفظتها','تراجعت أرباح شركة "أكوا" السعودية بنحو 28% على أساس سنوي خلال النصف الأول من العام الجاري إلى 653 مليون ريال، وفقا للنتائج المالية المعلنة اليوم الخميس.','["الشركة كانت حققت ربحا صافيا بلغ نحو 909 ملايين ريال في الفترة ذاتها من العام الماضي.","تأثرت أرباح الشركة نصف السنوية بتوقيت إنجاز عدد من مشاريع التطوير والإغلاقات المالية، رغم استمرار الأداء التشغيلي القوي لمحفظة الأصول التشغيلية، بحسب ما ذكرته في بيان.","الدخل التشغيلي قبل احتساب خسائر انخفاض القيمة والمصروفات الأخرى انخفض إلى 1.44 مليار ريال من 2.21 مليار ريال في النصف الأول من العام الماضي.","في الربع الثاني، بلغ صافي ربح \"أكوا\" 308 ملايين ريال، بانخفاض بنحو 36% على أساس سنوي، وهو ما أرجعته الشركة إلى نخفاض الإيرادات التشغيلية الأخرى، وانخفاض في نتائج الشركات المستثمر فيها بطريقة حقوق الملكية، وارتفاع المصروفات العمومية والإدارية."]','أخبار السعودية','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%A7%D9%84%D8%B4%D8%B1%D9%83%D8%A7%D8%AA/%D8%A3%D8%B1%D8%A8%D8%A7%D8%AD-%D8%A3%D9%83%D9%88%D8%A7-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%AA%D8%AA%D8%B1%D8%A7%D8%AC%D8%B9-28-%D9%81%D9%8A-%D8%A7%D9%84%D9%86%D8%B5%D9%81-%D8%A7%D9%84%D8%A3%D9%88%D9%84-%D9%85%D8%B9-%D8%AA%D9%88%D8%B3%D8%B9-%D9%85%D8%AD%D9%81%D8%B8%D8%AA%D9%87%D8%A7-12904','https://www.aleqt.com/%D8%A7%D9%84%D8%B4%D8%B1%D9%83%D8%A7%D8%AA/%D8%A3%D8%B1%D8%A8%D8%A7%D8%AD-%D8%A3%D9%83%D9%88%D8%A7-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%AA%D8%AA%D8%B1%D8%A7%D8%AC%D8%B9-28-%D9%81%D9%8A-%D8%A7%D9%84%D9%86%D8%B5%D9%81-%D8%A7%D9%84%D8%A3%D9%88%D9%84-%D9%85%D8%B9-%D8%AA%D9%88%D8%B3%D8%B9-%D9%85%D8%AD%D9%81%D8%B8%D8%AA%D9%87%D8%A7-12904','','https://www.aleqt.com/%D8%A7%D9%84%D8%B4%D8%B1%D9%83%D8%A7%D8%AA/%D8%A3%D8%B1%D8%A8%D8%A7%D8%AD-%D8%A3%D9%83%D9%88%D8%A7-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%AA%D8%AA%D8%B1%D8%A7%D8%AC%D8%B9-28-%D9%81%D9%8A-%D8%A7%D9%84%D9%86%D8%B5%D9%81-%D8%A7%D9%84%D8%A3%D9%88%D9%84-%D9%85%D8%B9-%D8%AA%D9%88%D8%B3%D8%B9-%D9%85%D8%AD%D9%81%D8%B8%D8%AA%D9%87%D8%A7-12904','','السعودية','2026-08-06T15:13:00.000Z',NULL,'2026-08-06T20:21:03.583Z','https://static.aleqt.com/aleqt/uploads/images/2026/08/06/2234427.webp?w=800&q=75','/api/media/b7b01b02-52dd-4eee-aad9-fad5dfdc7059','/api/media/b7b01b02-52dd-4eee-aad9-fad5dfdc7059?variant=thumbnail','أرباح "أكوا" السعودية تتراجع 28% في النصف الأول مع توسع محفظتها',1200,662,'valid','published','archived','valid',44,'c52813ac43d1c760219eadd0c3b3707fcd8d7e2e539ed147ba46fc8972f0bd59','9dbb85d8f852f757d46574b2f936049d0961907b0c9722e9390e9774006f04d1',NULL,'2026-08-06T20:21:03.583Z','2026-10-07T20:24:27.526Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد"]','[]','manual_approved','below_category_threshold','[{