INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0b55ee50-5c49-4329-8973-f76cd2179aa2','news-0b55ee50-5c49-4329-8973-f76cd2179aa2','ارتفاع طفيف في طلبات إعانة البطالة في أمريكا وتراجع حالات التسريح','ارتفاع طفيف في طلبات اعانه البطاله في امريكا وتراجع حالات التسريح','ارتفع عدد الأمريكيين المتقدمين بطلبات للحصول على إعانات البطالة ارتفاعا طفيفا الأسبوع الماضي، في حين انخفضت حالات التسريح من العمل إلى أدنى مستوياتها منذ عامين في يوليو تموز، وهو ما يتماشى مع استقرار سوق العمل.','["وأعلنت وزارة العمل الأمريكية اليوم الخميس أن الطلبات الجديدة زادت ألفا إلى 199 ألف طلب خلال الأسبوع المنتهي في الأول من أغسطس، وذلك بعد التعديل في ضوء العوامل الموسمية.","وكان خبراء اقتصاد توقعوا في استطلاع لرويترز تسجيل 202 ألف طلب خلال ذلك الأسبوع.","وانخفضت الطلبات بنحو ملحوظ منذ الارتفاع الحاد الذي شهدته في أوائل يونيو. وعلى الرغم من أن هذا الانخفاض يعكس في جانب منه الصعوبات في تعديل البيانات لمراعاة التقلبات الموسمية في الصيف، فإن حالات التسريح ظلت منخفضة جدا على الرغم من صدمة أسعار النفط الناجمة عن الحرب الأمريكية الإسرائيلية على إيران."]','الطاقة والصناعة','','c53fca26-0c5f-439c-8302-fab5c672f3a8','الاقتصادية','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D8%A7%D8%B1%D8%AA%D9%81%D8%A7%D8%B9-%D8%B7%D9%81%D9%8A%D9%81-%D9%81%D9%8A-%D8%B7%D9%84%D8%A8%D8%A7%D8%AA-%D8%A5%D8%B9%D8%A7%D9%86%D8%A9-%D8%A7%D9%84%D8%A8%D8%B7%D8%A7%D9%84%D8%A9-%D9%81%D9%8A-%D8%A3%D9%85%D8%B1%D9%8A%D9%83%D8%A7-%D9%88%D8%AA%D8%B1%D8%A7%D8%AC%D8%B9-%D8%AD%D8%A7%D9%84%D8%A7%D8%AA-%D8%A7%D9%84%D8%AA%D8%B3%D8%B1%D9%8A%D8%AD-12900','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D8%A7%D8%B1%D8%AA%D9%81%D8%A7%D8%B9-%D8%B7%D9%81%D9%8A%D9%81-%D9%81%D9%8A-%D8%B7%D9%84%D8%A8%D8%A7%D8%AA-%D8%A5%D8%B9%D8%A7%D9%86%D8%A9-%D8%A7%D9%84%D8%A8%D8%B7%D8%A7%D9%84%D8%A9-%D9%81%D9%8A-%D8%A3%D9%85%D8%B1%D9%8A%D9%83%D8%A7-%D9%88%D8%AA%D8%B1%D8%A7%D8%AC%D8%B9-%D8%AD%D8%A7%D9%84%D8%A7%D8%AA-%D8%A7%D9%84%D8%AA%D8%B3%D8%B1%D9%8A%D8%AD-12900','','https://www.aleqt.com/%D8%A7%D9%84%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D8%A7%D8%B1%D8%AA%D9%81%D8%A7%D8%B9-%D8%B7%D9%81%D9%8A%D9%81-%D9%81%D9%8A-%D8%B7%D9%84%D8%A8%D8%A7%D8%AA-%D8%A5%D8%B9%D8%A7%D9%86%D8%A9-%D8%A7%D9%84%D8%A8%D8%B7%D8%A7%D9%84%D8%A9-%D9%81%D9%8A-%D8%A3%D9%85%D8%B1%D9%8A%D9%83%D8%A7-%D9%88%D8%AA%D8%B1%D8%A7%D8%AC%D8%B9-%D8%AD%D8%A7%D9%84%D8%A7%D8%AA-%D8%A7%D9%84%D8%AA%D8%B3%D8%B1%D9%8A%D8%AD-12900','','السعودية','2026-08-06T13:54:00.000Z','2026-08-06T13:56:15.000Z','2026-08-06T20:21:06.863Z','https://static.aleqt.com/aleqt/uploads/images/2026/08/06/2234414.webp?w=800&q=75','/api/media/0b55ee50-5c49-4329-8973-f76cd2179aa2','/api/media/0b55ee50-5c49-4329-8973-f76cd2179aa2?variant=thumbnail','ارتفاع طفيف في طلبات إعانة البطالة في أمريكا وتراجع حالات التسريح',1200,800,'valid','published','archived','valid',46,'50cc9acf37f12370dd43a346f73c93b5e718f73d8189646f06d5c9ad9e5d7054','b3fe5dbe28a278069d1476081e620c59e361e39d44bfa92c6b06eedade3cdf2a',NULL,'2026-08-06T20:21:06.863Z','2026-10-07T20:24:27.528Z','','',0,0,'saudi_r