INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7e44d082-9e94-42e6-8d90-1ba02bdccf36','news-7e44d082-9e94-42e6-8d90-1ba02bdccf36','أفضل تمرين لنحت الخصر وتصغير البطن: خطوة واحدة نحو قوام أكثر تناسقاً','افضل تمرين لنحت الخصر وتصغير البطن خطوه واحده نحو قوام اكثر تناسقا','يحلم الكثيرون بالحصول على خصر متناسق وبطن مشدود، إلا أن الحقيقة العلمية تؤكد أن تصغير البطن لا يتحقق من خلال تمارين هذه المنطقة وحدها، بل يعتمد على تقليل نسبة الدهون في الجسم بشكل عام، إلى جانب تقوية عضلات البطن والخصر.','["يحلم الكثيرون بالحصول على خصر متناسق وبطن مشدود، إلا أن الحقيقة العلمية تؤكد أن تصغير البطن لا يتحقق من خلال تمارين هذه المنطقة وحدها، بل يعتمد على تقليل نسبة الدهون في الجسم بشكل عام، إلى جانب تقوية عضلات البطن والخصر. يُعد تمرين البلانك من أفضل التمارين التي تستهدف عضلات البطن العميقة، حيث يساعد على تحسين الثبات وشد عضلات الجذع من دون الحاجة إلى معدات رياضية. كما يُعتبر البلانك الجانبي خياراً ممتازاً لتقوية عضلات…","يُعد البلانك الجانبي من أفضل التمارين لنحت الخصر، لأنه يستهدف العضلات المائلة في جانبي البطن، والتي تمنح الخصر مظهراً أكثر تحديداً. استلقي على جانبك مع الاستناد على الساعد. ارفعي الجسم بحيث يشكّل خطاً مستقيماً من الرأس حتى القدمين. حافظي على شد عضلات البطن. اثبتي لمدة 20–45 ثانية، ثم بدلي الجهة. كرّري التمرين 3 مرات لكل جانب.","• تمرين الدراجة (Bicycle Crunch): يقوي عضلات البطن العلوية والسفلية والجانبية. • تمرين متسلقي الجبال (Mountain Climbers): يحرق السعرات ويقوي عضلات البطن في الوقت نفسه. • تمرين البلانك التقليدي (Plank): يعزز قوة عضلات الجذع ويحسن ثبات الجسم. • تمرين اللف الروسي (Russian Twist): يستهدف عضلات الخصر، ويفضل أداؤه من دون وزن أو بوزن خفيف.","• مارسي تمارين المقاومة 3 إلى 4 مرات أسبوعياً. • أضيفي 20–30 دقيقة من المشي السريع أو تمارين الكارديو معظم أيام الأسبوع. • احرصي على تناول كمية كافية من البروتين والخضروات وتقليل السكريات والأطعمة المصنعة. • نامي من 7 إلى 9 ساعات يومياً؛ لأن النوم الجيد يدعم حرق الدهون والتعافي العضلي. • لا يوجد تمرين واحد يزيل دهون البطن أو ينحت الخصر بمفرده، لكن البلانك الجانبي يُعد من أفضل التمارين لتقوية عضلات الخصر، وعند دمجه…"]','المناطق','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%B5%D8%AD%D8%A9-%D9%88%D8%B1%D8%B4%D8%A7%D9%82%D8%A9/%D8%B1%D8%B4%D8%A7%D9%82%D8%A9-%D9%88%D8%AA%D8%BA%D8%B0%D9%8A%D8%A9/1837581-%D8%AA%D9%85%D8%B1%D9%8A%D9%86-%D9%84%D9%86%D8%AD%D8%AA-%D8%A7%D9%84%D8%AE%D8%B5%D8%B1','https://www.sayidaty.net/%D8%B5%D8%AD%D8%A9-%D9%88%D8%B1%D8%B4%D8%A7%D9%82%D8%A9/%D8%B1%D8%B4%D8%A7%D9%82%D8%A9-%D9%88%D8%AA%D8%BA%D8%B0%D9%8A%D8%A9/1837581-%D8%AA%D9%85%D8%B1%D9%8A%D9%86-%D9%84%D9%86%D8%AD%D8%AA-%D8%A7%D9%84%D8%AE%D8%B5%D8%B1','1837581 at https://www.sayidaty.net','1837581 at https://www.sayidaty.net','عفت شهاب الدين','السعودية','2026-08-06T10:50:00.000Z','2026-08-06T07:52:58.000Z','2026-08-06T20:21:11.668Z','https://static.sayidaty.net/styles/1375_scale/public/2026-08/shutterstock_1918078742_0.jpg?VersionId=xcHXvNVTGy4JSPBjzU0Imv3YfMVTjiV9','/api/media/7e44d082-9e94-42e6-8d90-1ba02bdccf36','/api/media/7e44d082-9e94-42e6-8d90-1ba02bdccf36?variant=thumbnail','أفضل تمرين لنحت الخصر وتصغير البطن: خطوة واحدة نحو قوام أكثر تناسقاً',1375,867,'valid','published','archived','valid',44,'2b9abb2c3d4fecc4dc0fe7338e9b084a5ab1f8c1fbf270a41be32c50464caf6e','65cda227afca974c4af0ed4c398884c61ca1b778ad26ae43b07d809bcbab1e91',NULL,'2026-08-06T20:21:11.668Z','2026-10-07T20:24:27.531Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع"]','[]','manual_approved','below_category_threshold','[{"category":"الطاقة والصناعة","score":3},{"category":"المناطق","score":1.5},{"category":"المجتمع","score":1.5}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e47a5849-bf80-42b8-b371-53f42917bbd7','news-e47a5849-bf80-42b8-b371-53f42917bbd7','الساعات الفاخرة التي يعشقها رونالدو وجورجينا رودريغيز','الساعات الفاخره التي يعشقها رونالدو وجورجينا رودريغيز','لم تعد الساعات الفاخرة مجرد وسيلة لمعرفة الوقت بالنسبة للمشاهير، بل أصبحت قطعة أساسية تعكس الذوق الشخصي والمكانة الاجتماعية والاستثمار طويل الأمد، ويعد كريستيانو رونالدو Cristiano Ronaldo و شريكته جورجينا رودريغيز Georgina Rodríguez من أبرز الثنائيات التي تلفت الأنظار في كل ظهور بفضل اختياراتهما الاستثنائية من أشهر دور الساعات العالمية ، إذ يملكان مجموعة تضم','["لم تعد الساعات الفاخرة مجرد وسيلة لمعرفة الوقت بالنسبة للمشاهير، بل أصبحت قطعة أساسية تعكس الذوق الشخصي والمكانة الاجتماعية والاستثمار طويل الأمد، ويعد كريستيانو رونالدو Cristiano Ronaldo و شريكته جورجينا رودريغيز Georgina Rodríguez من أبرز الثنائيات التي تلفت الأنظار في كل ظهور بفضل اختياراتهما الاستثنائية من أشهر دور الساعات العالمية ، إذ يملكان مجموعة تضم نماذج نادرة مرصعة ب الألماس و الأحجار الكريمة ، تصل قيمة…","رغم عشقه للساعات المبالغ في تصميمها، لا يتخلى رونالدو عن الكلاسيكيات، وتحديدًا رولكس Rolex Daytona، وقد ظهر أكثر من مرة مرتديًا نسخًا مختلفة من ساعة Cosmograph Daytona، سواء المصنوعة من الذهب الأبيض أو المرصعة بالألماس. وتعد هذه الساعة من أكثر موديلات رولكس طلبًا في سوق الساعات الفاخرة، بفضل تصميمها الرياضي الأنيق وقيمتها الاستثمارية التي ارتفعت بشكل كبير خلال السنوات الأخيرة. ويفضل رونالدو عادة الإصدارات النادرة…","لا تقتصر مجموعة رونالدو على التصاميم اللافتة فقط، بل تضم أيضًا ساعات كلاسيكية راقية من باتيك فيليب Patek Philippe، ومن أبرزها ساعة Patek Philippe Nautilus، التي تعد واحدة من أكثر الساعات الرياضية الفاخرة طلبًا في العالم، وتتميز هذه الساعة بتصميمها الأنيق وسوارها المعدني المتكامل، كما ارتفعت أسعارها بصورة كبيرة بسبب محدودية الإنتاج، ما جعلها خيارًا مفضلًا لهواة جمع الساعات. ويختار رونالدو هذا النوع غالبًا خلال…","من الساعات المفضلة أيضًا لدى رونالدو هي ساعة Franck Muller Cintrée Curvex Tourbillon Piece Unique، وتعد هذه القطعة من أندر ساعات الدار السويسرية، إذ تأتي بهيكل منحني مميز مرصع بالكامل بماسات Baguette Cut، مع حركة Tourbillon المعقدة، ويُقدّر سعرها بنحو 1.5 مليون دولار، ما جعلها واحدة من أغلى الساعات التي ارتداها النجم البرتغالي في مناسبة عامة، وقد لفتت الساعة الأنظار بقدر ما لفتت إطلالة رونالدو نفسها، لتؤكد شغفه…"]','الاقتصاد','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%A3%D9%86%D8%A7%D9%82%D8%A9/%D9%85%D8%AC%D9%88%D9%87%D8%B1%D8%A7%D8%AA-%D9%88%D8%B3%D8%A7%D8%B9%D8%A7%D8%AA/1837574-%D8%B3%D8%A7%D8%B9%D8%A7%D8%AA-%D8%B1%D9%88%D9%86%D8%A7%D9%84%D8%AF%D9%88-%D9%88%D8%AC%D9%88%D8%B1%D8%AC%D9%8A%D9%86%D8%A7-%D8%B1%D9%88%D8%AF%D8%B1%D9%8A%D8%BA%D9%8A%D8%B2','https://www.sayidaty.net/%D8%A3%D9%86%D8%A7%D9%82%D8%A9/%D9%85%D8%AC%D9%88%D9%87%D8%B1%D8%A7%D8%AA-%D9%88%D8%B3%D8%A7%D8%B9%D8%A7%D8%AA/1837574-%D8%B3%D8%A7%D8%B9%D8%A7%D8%AA-%D8%B1%D9%88%D9%86%D8%A7%D9%84%D8%AF%D9%88-%D9%88%D8%AC%D9%88%D8%B1%D8%AC%D9%8A%D9%86%D8%A7-%D8%B1%D9%88%D8%AF%D8%B1%D9%8A%D8%BA%D9%8A%D8%B2','1837574 at https://www.sayidaty.net','1837574 at https://www.sayidaty.net','هاجر حاتم','السعودية','2026-08-06T11:00:14.000Z','2026-08-06T08:24:15.000Z','2026-08-06T20:21:11.982Z','https://static.sayidaty.net/styles/1375_scale/public/2026-08/GettyImages-1052754612_0.jpg?VersionId=AySGMPSgH9IFHYOhEwYJ.TAk6AWhduwM','/api/media/e47a5849-bf80-42b8-b371-53f42917bbd7','/api/media/e47a5849-bf80-42b8-b371-53f42917bbd7?variant=thumbnail','الساعات الفاخرة التي يعشقها رونالدو وجورجينا رودريغيز',1375,917,'valid','published','archived','valid',85,'ab0e62884a6d475663c83ce5f1504d03dd1703f5a30df9710385ed467f2f51f0','d8ee815129ec5b4902808afa99e9fb11cd80c072d19abe16915c396fc7730a7e',NULL,'2026-08-06T20:21:11.982Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","الرياض"]','["الاقتصاد والأسواق"]','classified','','[{"category":"السيارات","score":4.5},{"category":"المناطق","score":1.5},{"category":"التقنية","score":1.5}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9e14a72e-3f13-4d9b-aa08-230ebb72a80f','news-9e14a72e-3f13-4d9b-aa08-230ebb72a80f','معرض كنوز غارقة.. رحلة معرفية تستكشف التراث البحري للبحر الأحمر','معرض كنوز غارقه رحله معرفيه تستكشف التراث البحري للبحر الاحمر','يجسد معرض "كنوز غارقة: التراث البحري للبحر الأحمر"، الذي يحتضنه متحف البحر الأحمر في جدة التاريخية، إحدى أبرز المبادرات الثقافية التي تسلط الضوء على الإرث البحري للمملكة، من خلال تجربة معرفية تستعرض تاريخ البحر الأحمر بوصفه ممرًا حضاريًا أسهم عبر آلاف السنين في ازدهار التجارة البحرية، ورحلات الحج، والتواصل بين الحضارات.','["وبحسب ما نشرته وكالة الأنباء السعودية \"واس\"، فيقدم المعرض، المستمر حتى 15 أغسطس 2026، رحلة تفاعلية عبر مقتنيات أثرية وخرائط تاريخية وأدوات ملاحة، إلى جانب مكتشفات من مواقع التراث الثقافي المغمور بالمياه، تكشف جانبًا من تاريخ الملاحة البحرية، وتبرز دور البحر الأحمر في ربط شبه الجزيرة العربية بإفريقيا وآسيا، وما شهدته مياهه من حركة تجارية وثقافية أسهمت في تشكيل تاريخ المنطقة عبر العصور.","ويستعرض المعرض نماذج من حطام السفن واللقى الأثرية التي حفظتها أعماق البحر لقرون، بوصفها شواهد مادية توثق مسارات التجارة والرحلات البحرية، إلى جانب إبراز جهود البحث الأثري في إعادة قراءة هذا الإرث وتحويله إلى محتوى معرفي يعزز الوعي بقيمة التراث الثقافي المغمور بالمياه. ويُجسد المعرض ثمرة التعاون بين هيئة المتاحف وهيئة التراث وبرنامج جدة التاريخية، من خلال توظيف أحدث تقنيات العرض المتحفي، بما يسهم في تقديم تجربة…","ويتيح المعرض لزواره، بمن فيهم الأطفال، تجارب تعليمية وتفاعلية تجمع بين الاستكشاف والمعرفة، وتسهم في تعزيز الوعي بأهمية الحفاظ على التراث البحري والبيئي للبحر الأحمر، وتحويله إلى مصدر للإلهام والحوار الثقافي بين مختلف فئات المجتمع. ويؤكد معرض \"كنوز غارقة\" الدور المتنامي للمؤسسات الثقافية في توثيق التراث البحري للمملكة وإبرازه بأساليب عرض حديثة، تسهم في تحويل المكتشفات الأثرية إلى روايات معرفية تستحضر تاريخ البحر…"]','الثقافة','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%A8%D9%84%D8%B3/%D8%AB%D9%82%D8%A7%D9%81%D8%A9-%D9%88%D9%81%D9%86%D9%88%D9%86/1837599-%D8%A7%D9%84%D8%A8%D8%AD%D8%B1-%D8%A7%D9%84%D8%A3%D8%AD%D9%85%D8%B1','https://www.sayidaty.net/%D8%A8%D9%84%D8%B3/%D8%AB%D9%82%D8%A7%D9%81%D8%A9-%D9%88%D9%81%D9%86%D9%88%D9%86/1837599-%D8%A7%D9%84%D8%A8%D8%AD%D8%B1-%D8%A7%D9%84%D8%A3%D8%AD%D9%85%D8%B1','1837599 at https://www.sayidaty.net','1837599 at https://www.sayidaty.net','نت','السعودية','2026-08-06T11:12:30.000Z','2026-08-06T12:22:34.000Z','2026-08-06T20:21:12.101Z','https://static.sayidaty.net/styles/1375_scale/public/2026-08/504213.jpg?VersionId=ke3kbQUHOoIWtRMp5jTw9I6H4jLnJaUU','/api/media/9e14a72e-3f13-4d9b-aa08-230ebb72a80f','/api/media/9e14a72e-3f13-4d9b-aa08-230ebb72a80f?variant=thumbnail','معرض كنوز غارقة.. رحلة معرفية تستكشف التراث البحري للبحر الأحمر',1375,909,'valid','published','archived','valid',44,'7f157748e2a514420e1aecc794d3ffa06f4aef6d9e77436a47879cb708b91548','2c6e957e00977eabaf0a1953b255448855a42bc56d3d5785dbc9d19adeb32a07',NULL,'2026-08-06T20:21:12.101Z','2026-10-07T20:24:27.535Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة المتاحف وهيئة التراث وبرنامج","التعليم والتدريب","الاقتصاد والأسواق","جدة"]','["هيئة المتاحف وهيئة التراث وبرنامج","التعليم والتدريب","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":1.5}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7b283a9b-2e7a-4cd1-8e50-32ff2db7e551','news-7b283a9b-2e7a-4cd1-8e50-32ff2db7e551','من هي هيلين إلفيرين بطلة «ما زلت في السابعة عشر»؟ عمرها وبدايتها الفنية وقصة شخصية دينيز','من هي هيلين الفيرين بطله ما زلت في السابعه عشر عمرها وبدايتها الفنيه وقصه شخصيه دينيز','من عالم صناعة المحتوى على مواقع التواصل الاجتماعي إلى خشبة المسرح ، ومنها إلى الشاشة، تخطو هيلين إلفيرين خطواتها الأولى في عالم التمثيل بثبات، لتصبح واحدة من الوجوه التركية الشابة التي بدأت تستحوذ على اهتمام الجمهور، خاصة بعد ظهورها في مسلسل «ما زلت في السابعة عشر» بشخصية «دينيز»، التي كشفت من خلالها عن حضور عفوي وأداء طبيعي لفتا الأنظار.','["ولم تبدأ رحلة هيلين إلفيرين من أمام الكاميرا، إذ صنعت لنفسها حضورًا مبكرًا عبر منصة تيك توك من خلال المحتوى القصير، قبل أن تنتقل تدريجيًا إلى عالم التمثيل ، مستفيدة من اهتمامها بالفنون وخبرتها المسرحية وتدريباتها في مجالات مختلفة مثل الرقص والموسيقى. ومع مشاركتها في عدد من المشاريع التلفزيونية، تواصل الفنانة الشابة توسيع مسيرتها في السينما والتلفزيون والمشاريع الرقمية.","وفي الوقت الذي يتزايد فيه اهتمام الجمهور العربي بالمسلسل التركي « ما زلت في السابعة عشر »، تبرز هيلين إلفيرين باعتبارها واحدة من الوجوه الشابة التي تستحق المتابعة، خاصة مع ما كشفته عن شخصية «دينيز» ومشاعرها تجاه «أراس»، وكذلك مستقبل علاقتها المتوترة مع «تيومان».","هيلين إلفيرين (Helin Elveren) ممثلة تركية شابة من مواليد مدينة إسطنبول، بدأت طريقها نحو الشهرة من خلال مواقع التواصل الاجتماعي، قبل أن تنتقل إلى التمثيل وتلفت الأنظار بموهبتها وحضورها الطبيعي أمام الكاميرا.","ولدت هيلين إلفيرين في 20 أبريل 2006 في إسطنبول، وعاشت معظم حياتها في المدينة التي شهدت أيضًا بداياتها التعليمية والفنية. وعلى الرغم من صغر سنها، تمكنت من خوض أكثر من تجربة في المجال الفني، بداية من المسرح ثم الانتقال إلى الأعمال التي تُعرض على الشاشة."]','الثقافة','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1-%D8%A7%D9%84%D8%B9%D8%A7%D9%84%D9%85/1837600-%D9%85%D9%86-%D9%87%D9%8A-%D9%87%D9%8A%D9%84%D9%8A%D9%86-%D8%A5%D9%84%D9%81%D9%8A%D8%B1%D9%8A%D9%86-%D8%A8%D8%B7%D9%84%D8%A9-%C2%AB%D9%85%D8%A7-%D8%B2%D9%84%D8%AA-%D9%81%D9%8A-%D8%A7%D9%84%D8%B3%D8%A7%D8%A8%D8%B9%D8%A9-%D8%B9%D8%B4%D8%B1%C2%BB%D8%9F-%D8%B9%D9%85%D8%B1%D9%87%D8%A7-%D9%88%D8%A8%D8%AF%D8%A7%D9%8A%D8%AA%D9%87%D8%A7','https://www.sayidaty.net/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1/%D9%85%D8%B4%D8%A7%D9%87%D9%8A%D8%B1-%D8%A7%D9%84%D8%B9%D8%A7%D9%84%D9%85/1837600-%D9%85%D9%86-%D9%87%D9%8A-%D9%87%D9%8A%D9%84%D9%8A%D9%86-%D8%A5%D9%84%D9%81%D9%8A%D8%B1%D9%8A%D9%86-%D8%A8%D8%B7%D9%84%D8%A9-%C2%AB%D9%85%D8%A7-%D8%B2%D9%84%D8%AA-%D9%81%D9%8A-%D8%A7%D9%84%D8%B3%D8%A7%D8%A8%D8%B9%D8%A9-%D8%B9%D8%B4%D8%B1%C2%BB%D8%9F-%D8%B9%D9%85%D8%B1%D9%87%D8%A7-%D9%88%D8%A8%D8%AF%D8%A7%D9%8A%D8%AA%D9%87%D8%A7','1837600 at https://www.sayidaty.net','1837600 at https://www.sayidaty.net','عمرو رضا','السعودية','2026-08-06T11:15:18.000Z','2026-08-06T11:15:18.000Z','2026-08-06T20:21:13.298Z','https://static.sayidaty.net/styles/1375_scale/public/2026-08/504211.jpg?VersionId=NEnJhQMRaYfIMaILPSe_IGM8mJFyoJLK','/api/media/7b283a9b-2e7a-4cd1-8e50-32ff2db7e551','/api/media/7b283a9b-2e7a-4cd1-8e50-32ff2db7e551?variant=thumbnail','من هي هيلين إلفيرين بطلة «ما زلت في السابعة عشر»؟ عمرها وبدايتها الفنية وقصة شخصية دينيز',1375,916,'valid','published','archived','valid',56,'b134a7126c2bafd3febe2f1fcb512910efdf3319b97282f60a7a9f91f006f730','fe3af965d97248c62f075367a21b6bca1dac61228ec20ae68b9ae2f883278253',NULL,'2026-08-06T20:21:13.298Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","التعليم والتدريب","التقنية والتحول الرقمي"]','["الثقافة والفنون","التعليم والتدريب","التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"التعليم","score":3},{"category":"الاقتصاد","score":1.5},{"category":"الصحة","score":1.5}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4d17a3d4-94df-49b6-82c9-b7f00be62708','news-4d17a3d4-94df-49b6-82c9-b7f00be62708','في إطار حضورها الدولي.. تشارك ''''مداد العقارية'''' راعيًا فضيًّا في معرض العقارات الفاخرة السعودي لعام 2026 بلندن','في اطار حضورها الدولي تشارك مداد العقاريه راعيا فضيا في معرض العقارات الفاخره السعودي لعام 2026 بلندن','أعلنت شركة "مداد للاستثمار والتطوير العقاري" عن مشاركتها بصفتها راعيًا فضيًّا في معرض العقارات الفاخرة السعودي 2026 «SLRE»، الذي تستضيفه العاصمة البريطانية لندن في فندق «ذا بينينسولا لندن»، خلال الفترة من 24 إلى 28 أغسطس 2026.','["وتُجسِّد هذه المشاركة حضور ''''مداد العقارية'''' في النسخة الافتتاحية للمعرض، المنعقد بمشاركة نخبةٍ من المطوّرين والمستثمرين المؤسّسين، والمكاتب العائلية، والشركاء الإستراتيجيين، والمستثمرين من ذوي الملاءة المالية العالية من مختلف الأسواق العالمية.","وتُتوّج ''''مداد العقارية'''' مشاركتها بالتعريف بملامح محفظتها العقارية المكوَّنة من المشاريع والوجهات ذات العلامات العالمية الفاخرة، القائمة على فلسفاتٍ معماريةٍ تصوغ أصولًا خالدةً تجمع بين التميُّز التصميمي العالمي والتجذّر في الرقي؛ مُبرزةً أمام المحافل الدولية قوة القطاع العقاري السعودي، وما يزخر به من فرصٍ استثماريةٍ نوعيةٍ في المملكة العربية السعودية أمام المستثمرين الدوليين.","وفي صدارة الأيقونات المعمارية التي تسلِّط ''''مداد العقارية'''' الضوء عليها خلال المعرض، يتصدَّر مشروع «فندق ومساكن فورسيزونز الخاصة جدة على الكورنيش» مشهد العرض؛ تحفة معمارية تضمُّ أربعة أبراجٍ متصلةٍ عبر جسورٍ معلّقةٍ متعددة الطوابق؛ لتُعيد تعريف الحياة الساحلية الفاخرة على البحر الأحمر، وتتجسَّد فيه الشراكة مع علامة «فورسيزونز» العالمية صياغةً استثنائيةً تدمج نُبل الضيافة الفارهة بخصوصية العيش السكني؛ لتُحيل الرؤية…","نبذة عن شركة \"مداد للاستثمار والتطوير العقاري\": تتجلَّى الفلسفة الاستثمارية لـ\"مداد العقارية\" في نسج تحالفاتٍ إستراتيجية مع أعرق العلامات التجارية وقادة الضيافة على مستوى العالم، صوغًا لرؤيةٍ معماريةٍ تتجاوز المفهوم التقليدي للتطوير إلى رحاب ابتكار الأيقونات؛ حيث تترأس محفظتها النخبوية شواهد معمارية فارقة بالتعاون مع أرقى العلامات الدولية، وفي صدارتها «فورسيزونز الدرعية»، و«أتلانتس جدة»، و«ون آند أونلي جدة»،…"]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ma2x10i','https://sabq.org/article/ma2x10i','','https://sabq.org/article/ma2x10i','صحيفة سبق','السعودية','2026-08-06T12:40:02.470Z','2026-08-06T12:40:25.158Z','2026-08-06T20:21:13.334Z','https://media.sabq.org/news/2026/08/6fdf039f-f735-4808-bbb1-5fe455530dba/w1600.webp','/api/media/4d17a3d4-94df-49b6-82c9-b7f00be62708','/api/media/4d17a3d4-94df-49b6-82c9-b7f00be62708?variant=thumbnail','في إطار حضورها الدولي.. تشارك ''''مداد العقارية'''' راعيًا فضيًّا في معرض العقارات الفاخرة السعودي لعام 2026 بلندن',1600,900,'valid','published','archived','valid',54,'c935d99d9618db3e265bfd8242da992a01e818c44763c268e36e993ca75055c4','3a5dd1260689aad1e203e308486c84ef36de96fa5ee4afb4dfc8807f3fcd483c',NULL,'2026-08-06T20:21:13.334Z','2026-10-07T19:41:17.369Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة مداد للاستثمار والتطوير العقاري","السفر والسياحة","الثقافة والفنون","الاقتصاد والأسواق","جدة"]','["شركة مداد للاستثمار والتطوير العقاري","السفر والسياحة","الثقافة والفنون","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":1.5},{"category":"السفر","score":1.5}]','Temporarily Unreachable','2026-10-07T19:41:17.369Z',NULL,88,4,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5a188881-3775-47c3-9d6b-72a40d128eca','news-5a188881-3775-47c3-9d6b-72a40d128eca','رصد الشروق الاحتراقي لنجم الشِّعرى في سماء رفحاء بعد غياب 70 يوماً','رصد الشروق الاحتراقي لنجم الشعري في سماء رفحاء بعد غياب 70 يوما','رُصد الشروق الاحتراقي لنجم الشِّعرى في سماء محافظة رفحاء بمنطقة الحدود الشمالية، إذ بدا مرئياً بوضوح من جهة الشرق مع بداية الفجر، بعد غياب استمر قرابة 70 يوماً منذ آخر ظهور له في جهة الغرب.','["وتُعدّ هذه الظاهرة من أبرز المحطات الفلكية السنوية في رصد النجوم، وتؤذن ببدء الدورة الشمسية المرتبطة بهذا النجم.","وأوضح عضو جمعية «آفاق» لعلوم الفلك برجس الفليح، في تصريح لوكالة الأنباء السعودية «واس»، أن الشروق الاحتراقي لنجم الشِّعرى يمثل أول ظهور فجري له من جهة الشرق عقب فترة احتجاب سنوية، مشيراً إلى أن التقويم النجمي الشمسي المعتمد على هذا النجم يُعدّ من أدق أنظمة التقويم التي عرفتها الحضارات القديمة، إذ استُخدم في تحديد مواسم السنة وارتبط بالسنة المائية، فضلاً عن كونه دليلاً للمسافرين في رحلتَي الشتاء والصيف.","وأضاف الفليح أن نجم الشِّعرى يتكوّن من نجمَين؛ أحدهما ضخم الحجم والآخر أصغر يدور حوله، ويبعد عن الأرض نحو 8 سنوات ضوئية، ليكون من أقرب النجوم إليها.","وعلى الرغم من بُعده الهائل، فإن كتلته تفوق كتلة الشمس بمرتين تقريباً، كما يتميز بدرجة حرارة سطحية مرتفعة جداً تمنحه توهجاً وسطوعاً لافتَين."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/pkcz3s4','https://sabq.org/article/pkcz3s4','','https://sabq.org/article/pkcz3s4','صحيفة سبق','السعودية','2026-08-06T12:14:20.088Z','2026-08-06T12:15:39.412Z','2026-08-06T20:21:13.676Z','https://media.sabq.org/news/2026/08/c8c001e2-fe5e-4329-82d6-0040f34e0273/w870.webp','/api/media/5a188881-3775-47c3-9d6b-72a40d128eca','/api/media/5a188881-3775-47c3-9d6b-72a40d128eca?variant=thumbnail','رصد الشروق الاحتراقي لنجم الشِّعرى في سماء رفحاء بعد غياب 70 يوماً',870,1600,'valid','published','archived','valid',40,'770ac77d5404ca0c488f22455103fd6ff52fe06cbaa1fafc38862bb81093ecf6','ffb49d4ab22dbb45a4b295c11e2dfcf243b76d6ee9d7275ffbcb0ec78d2dd9db',NULL,'2026-08-06T20:21:13.676Z','2026-10-07T19:41:17.372Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ"]','["الطقس والمناخ"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"السفر","score":1.5},{"category":"الثقافة","score":1.5}]','Temporarily Unreachable','2026-10-07T19:41:17.372Z',NULL,83,4,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6d68d973-1f95-44d2-9f6f-648ce561e8e2','news-6d68d973-1f95-44d2-9f6f-648ce561e8e2','دراسة سعودية عن «دحول الصمّان» تتصدر أسئلة أولمبياد العلوم النووية الدولي','دراسه سعوديه عن دحول الصمان تتصدر اسئله اولمبياد العلوم النوويه الدولي','تصدّرت «دحول الصمّان» السؤال الرئيس في الاختبار النظري لأولمبياد العلوم النووية الدولي «إنسو 2026»، المنعقد في جامعة الملك عبدالعزيز بجدة خلال الفترة من 2 إلى 9 أغسطس الجاري، بمشاركة نحو 120 طالباً ومختصاً علمياً يمثلون 19 دولة.','["وأوضح رئيس اللجنة العلمية للأولمبياد الدكتور أنس الوافي، أن اللجنة حرصت على أن تكون أسئلة هذه النسخة أصيلة وقائمة على أبحاث وتطبيقات علمية واقعية، مبيناً أن السؤال الرئيس استند إلى دراسة سعودية نُشرت في مجلة «نيتشر» العلمية العالمية، وأنجزتها هيئة التراث السعودية، وتناولت السجل المناخي للمملكة في منطقة «دحول الصمّان» باستخدام التقنيات النووية والتأريخ الإشعاعي.","وقال الوافي: «لم نذهب بعيداً، إذ اخترنا دراسة سعودية عن دحول الصمّان نُشرت العام الماضي في مجلة نيتشر، وهي من أعرق المجلات العلمية العالمية، وأُنجزت من قبل هيئة التراث السعودية».","وتُعدّ «دحول الصمّان» من أبرز التكوينات الكارستية في المملكة، وتقع شمال شرق الرياض، وتضم شبكة من الكهوف الطبيعية التي حفظت ترسباتها سجلاً جيولوجياً ومناخياً يمتد عبر عصور سحيقة، ما جعلها موقعاً علمياً مهماً لدراسة تاريخ المناخ في شبه الجزيرة العربية.","وأضاف الوافي أن البيانات العلمية أثبتت أن المملكة العربية السعودية كانت خضراء خلال فترات طويلة، وشهدت أوقاتاً مطيرة امتدت على مدى 8 ملايين سنة، مشيراً إلى أن ذلك يُعدّ من أطول السجلات المناخية المرصودة، وأن الطالب يستفيد في الاختبار من هذه البيانات لتحديد السجل المناخي باستخدام التقنيات النووية والمعادلات الرياضية المرتبطة بهذا المجال."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/vmr3hey','https://sabq.org/article/vmr3hey','','https://sabq.org/article/vmr3hey','صحيفة سبق','السعودية','2026-08-06T12:16:14.270Z','2026-08-06T12:17:34.979Z','2026-08-06T20:21:13.849Z','https://media.sabq.org/news/2026/08/f28593ec-8609-4281-84a0-e558e5dd40b4/w1600.webp','/api/media/6d68d973-1f95-44d2-9f6f-648ce561e8e2','/api/media/6d68d973-1f95-44d2-9f6f-648ce561e8e2?variant=thumbnail','دراسة سعودية عن «دحول الصمّان» تتصدر أسئلة أولمبياد العلوم النووية الدولي',1600,1066,'valid','published','archived','valid',86,'426db6125a123234f6e4e17a18f126c399228fb2accc1cca450a804d4d4e8741','f20e4d6c73122998d9059d58960a4bfa1a269d2063d1331f65c3288942dce5ba',NULL,'2026-08-06T20:21:13.849Z','2026-10-07T20:24:27.543Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة التراث السعودية وتناولت السجل","رئيس اللجنة العلمية للأولمبياد الدكتور","الطقس والمناخ","الاقتصاد والأسواق","الرياض"]','["هيئة التراث السعودية وتناولت السجل","رئيس اللجنة العلمية للأولمبياد الدكتور","الطقس والمناخ","الاقتصاد والأسواق"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T19:36:13.926Z',200,88,0,'source_article_available','',NULL,NULL,'body:fc03baa1e1964bb5de0d05cc2c5d0ff85a140a2c3465f82240c25d4fab2399c6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d753b8ae-336a-4a26-a28f-4323711f0b9e','news-d753b8ae-336a-4a26-a28f-4323711f0b9e','متى يكون السفر بالطائرة أو السيارة خطراً على الحامل؟','متي يكون السفر بالطائره او السياره خطرا علي الحامل','لا يختلف اثنان على أن للسفر خلال الإجازات والأعياد فوائد كثيرة، حيث يمثل فرصة مثالية لكل أسرة لكسر وتغيير روتين الحياة اليومية، والاستمتاع أيضاً بأجواء جديدة تمنح الشعور بالراحة أكثر وتجدد النشاط والطاقة، إلا أن تزامن حمل الأم مع التخطيط لفرصة السفر قد يجعلها مترددة بشأن اتخاذ قرار فيه خوف من تأثيره على صحتها أو صحة جنينها، لذلك فمن الضروري أن تكون على دراية','["لا يختلف اثنان على أن للسفر خلال الإجازات والأعياد فوائد كثيرة، حيث يمثل فرصة مثالية لكل أسرة لكسر وتغيير روتين الحياة اليومية، والاستمتاع أيضاً بأجواء جديدة تمنح الشعور بالراحة أكثر وتجدد النشاط والطاقة، إلا أن تزامن حمل الأم مع التخطيط لفرصة السفر قد يجعلها مترددة بشأن اتخاذ قرار فيه خوف من تأثيره على صحتها أو صحة جنينها، لذلك فمن الضروري أن تكون على دراية بأبرز الاحتياطات والنصائح التي ينبغي مراعاتها قبل التخطيط…","قد يهمك أيضاً: في الشهر الثالث إليك دليلكِ الشامل لعلامات الحمل السليم","* ملاحظة من «سيدتي»: قبل تطبيق هذه الوصفة أو هذا العلاج، عليك استشارة طبيب متخصص."]','الصحة','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%B3%D9%8A%D8%AF%D8%AA%D9%8A-%D9%88%D8%B7%D9%81%D9%84%D9%83/%D8%A7%D9%84%D8%AD%D9%85%D9%84-%D9%88%D8%A7%D9%84%D9%88%D9%84%D8%A7%D8%AF%D8%A9/1837573-%D9%85%D8%AD%D8%A7%D8%B0%D9%8A%D8%B1-%D8%B3%D9%81%D8%B1-%D8%A7%D9%84%D8%AD%D8%A7%D9%85%D9%84','https://www.sayidaty.net/%D8%B3%D9%8A%D8%AF%D8%AA%D9%8A-%D9%88%D8%B7%D9%81%D9%84%D9%83/%D8%A7%D9%84%D8%AD%D9%85%D9%84-%D9%88%D8%A7%D9%84%D9%88%D9%84%D8%A7%D8%AF%D8%A9/1837573-%D9%85%D8%AD%D8%A7%D8%B0%D9%8A%D8%B1-%D8%B3%D9%81%D8%B1-%D8%A7%D9%84%D8%AD%D8%A7%D9%85%D9%84','1837573 at https://www.sayidaty.net','1837573 at https://www.sayidaty.net','ميسون عبد الرحيم','السعودية','2026-08-06T11:30:00.000Z','2026-08-06T09:02:40.000Z','2026-08-06T20:21:13.861Z','https://static.sayidaty.net/styles/1375_scale/public/2026-08/503479.jpg?VersionId=A8bf9flF3.zd629cryvvJ2T7Pq_mMtoZ','/api/media/d753b8ae-336a-4a26-a28f-4323711f0b9e','/api/media/d753b8ae-336a-4a26-a28f-4323711f0b9e?variant=thumbnail','متى يكون السفر بالطائرة أو السيارة خطراً على الحامل؟',1375,753,'valid','published','archived','valid',83,'87ebc57ef05c1f7b7c2fda8ee89ed9c8878c21ee62efef54c514819de9104ca6','e570f2fe35b83431ee509f46d7d12c63b14380f06f509ddfc465c35cc9458dfd',NULL,'2026-08-06T20:21:13.861Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الطاقة والنفط","السفر والسياحة"]','["الصحة العامة","الطاقة والنفط","السفر والسياحة"]','manual_approved','','[]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fb33ad18-e2d5-4ba4-aae0-08755373a168','news-fb33ad18-e2d5-4ba4-aae0-08755373a168','موسى ديابي يتفق مع ليفركوزن','موسي ديابي يتفق مع ليفركوزن','توصل نادي باير ليفركوزن الألماني إلى اتفاق مع نجم الاتحاد موسى ديابي للانضمام إلى صفوفه خلال فترة الانتقالات الصيفية الحالية.','["وبحسب صحيفة «بيلد» الألمانية، توصل باير ليفركوزن وديابي إلى اتفاق حول النقاط الرئيسية للعقد، ومن المتوقع أن يبلغ راتب اللاعب 6 ملايين يورو، إضافة إلى مكافآت سنوية، على أن يوقع عقداً حتى عام 2031.","وأضافت أن الجناح الفرنسي، الذي سبق له اللعب مع ليفركوزن بين عامي 2019 و2023، يفضّل العودة إلى النادي الألماني على عروض من إنتر ميلان وبنفيكا، حيث يبدو من الممكن إتمام الصفقة خلال الأسبوع القادم.","وتابع التقرير الألماني أن المفاوضات بين ليفركوزن والاتحاد بشأن صفقة ديابي وصلت إلى مراحلها النهائية، ومن المتوقع أن تقل قيمة الصفقة عن 30 مليون يورو، لكن العقبة الرئيسية تتمثل في المبلغ الذي سيكون ديابي مستعداً للتنازل عنه للاتحاد لإتمام انتقاله إلى النادي الألماني."]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/sport/international/2260242','https://www.okaz.com.sa/sport/international/2260242','','https://www.okaz.com.sa/sport/international/2260242','محمد جمعة (القاهرة)','السعودية','2026-08-06T19:31:43.000Z','Wed, 07 Oct 2026 19:35:52 GMT','2026-08-06T20:21:14.351Z','https://www.okaz.com.sa/okaz/uploads/images/2026/08/06/2747514.webp','/api/media/fb33ad18-e2d5-4ba4-aae0-08755373a168','/api/media/fb33ad18-e2d5-4ba4-aae0-08755373a168?variant=thumbnail',' ',678,452,'valid','published','archived','valid',47,'cdbaf247573d0d3e551d4fb893c227d80eb8dbb2ec5f8e621aed509888ae6a47','fa1dad4548a263fd3d78f1614f858f33a3487b61ffc23ec6f60f572dbaaa893a',NULL,'2026-08-06T20:21:14.351Z','2026-10-07T20:24:27.547Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","السياسة والعلاقات الدولية"]','["الرياضة السعودية","السياسة والعلاقات الدولية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Updated','2026-10-07T19:35:54.260Z',200,94,0,'source_content_changed','',NULL,NULL,'body:d45ca72b461febd88e48e6d8fc4cc59013c9d4403a995beacdd643c2afd3128b','Wed, 07 Oct 2026 19:35:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fdcb5220-9889-4777-88b0-6c6dee13970b','news-fdcb5220-9889-4777-88b0-6c6dee13970b','مقابل 50 مليون يورو.. سان جيرمان يضم أكليوش','مقابل 50 مليون يورو سان جيرمان يضم اكليوش','أعلن نادي باريس سان جيرمان الفرنسي، اليوم (الخميس)، تعاقده مع لاعب الوسط الهجومي ماغنيس أكليوش قادماً من موناكو.','["وقال النادي في بيان عبر موقعه الرسمي: «يسرّ نادي باريس سان جيرمان أن يعلن عن ضم ماغنيس أكليوش، إذ وقّع لاعب خط الوسط البالغ من العمر 24 عاماً، الذي سيرتدي القميص رقم 11، عقداً حتى عام 2031.","ولم يكشف نادي باريس سان جيرمان عن قيمة الصفقة، لكن تقارير صحفية ذكرت أنها كلفت خزينة العملاق الباريسي 50 مليون يورو.","وكان أكليوش قد خاض مباراته الأولى مع موناكو الأول في ​2021، وشارك منذ ذلك الحين ​في 139 مباراة مع النادي وسجل 23 هدفاً، كما ساهم في حصد الميدالية الفضية ⁠في ​أولمبياد باريس 2024، وكان ​ضمن تشكيلة المنتخب في كأس العالم 2026.","وقد يخوض أكليوش أول مباراة رسمية له مع باريس سان جيرمان ضد أستون فيلا في نهائي كأس السوبر الأوروبي في 12 أغسطس الجاري، على أن تأتي مباراة كأس الأبطال ضد لانس بعد 4 أيام."]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/sport/international/2260241','https://www.okaz.com.sa/sport/international/2260241','','https://www.okaz.com.sa/sport/international/2260241','محمد جمعة (القاهرة)','السعودية','2026-08-06T19:31:20.000Z','Wed, 07 Oct 2026 19:35:41 GMT','2026-08-06T20:21:14.566Z','https://www.okaz.com.sa/okaz/uploads/images/2026/08/06/2747512.webp','/api/media/fdcb5220-9889-4777-88b0-6c6dee13970b','/api/media/fdcb5220-9889-4777-88b0-6c6dee13970b?variant=thumbnail',' ',1600,900,'valid','published','archived','valid',88,'6c350d28b40c047a9c3370f2c13333d0efc342bf55ba9164428b6e341141f088','9092c7790a80da7b2fa9f336fb3440140b936f8de3a3beaa9748aab1b1a2c721',NULL,'2026-08-06T20:21:14.566Z','2026-10-07T19:35:43.503Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"التقنية","score":6},{"category":"أخبار السعودية","score":0},{"category":"الصحة","score":0}]','Updated','2026-10-07T19:35:43.503Z',200,90,0,'source_content_changed','',NULL,NULL,'body:2fcce4e3849e50cb65580302a3ee08009613ad35042ace583d1a5c16d7c294cb','Wed, 07 Oct 2026 19:35:41 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c197448c-b2c3-4743-8b93-313f424b6228','news-c197448c-b2c3-4743-8b93-313f424b6228','جمعية البر بمكة تنفّذ معسكري «اكتشاف» و«الجيل التقني» لتأهيل المستفيدين','جمعيه البر بمكه تنفذ معسكري اكتشاف و الجيل التقني لتاهيل المستفيدين','نفّذت جمعية البر بمكة المكرمة «بركم» معسكرين تدريبيين نوعيين ضمن مسار «تنمية بركم»، هما معسكر «اكتشاف» ومعسكر «الجيل التقني»، في إطار جهودها الرامية إلى تمكين المستفيدين وتنمية قدراتهم وتأهيلهم لمواكبة متطلبات العصر الرقمي.','["وأوضح مدير عام جمعية بركم الدكتور عبدالرحمن الغامدي أن معسكر «اكتشاف» صُمِّم لتنمية المهارات الشخصية والذهنية، وتعزيز التفكير الإبداعي، وصقل مهارات حل المشكلات والعمل الجماعي، من خلال أنشطة تدريبية وتطبيقات عملية أسهمت في اكتشاف قدرات المشاركين وتنمية مواهبهم.","أما معسكر «الجيل التقني» فقدّم تجربة تعليمية متخصصة في أساسيات الذكاء الاصطناعي والبرمجة الرقمية وبرمجة الروبوت والتطبيقات التقنية، بما يواكب متطلبات الثورة الصناعية الرابعة ويعزز الثقافة التقنية لدى المستفيدين.","وأكد الدكتور الغامدي أن هذه البرامج تجسّد رؤية الجمعية في الاستثمار في الإنسان وتمكين المستفيدين بالمعارف والمهارات التي تسهم في بناء مستقبلهم، منطلقةً من إيمانها بأن التنمية الحقيقية تبدأ بتأهيل القدرات وصناعة الكفاءات، بما يحقق أثراً مستداماً ينعكس على الفرد والمجتمع.","وتواصل جمعية البر بمكة المكرمة تنفيذ برامجها التنموية النوعية ضمن مسار «تنمية بركم»، سعياً إلى إعداد جيل قادر على الإبداع والابتكار ومؤهل للمشاركة الفاعلة في مسيرة التنمية الوطنية، بما ينسجم مع مستهدفات رؤية المملكة 2030."]','الذكاء الاصطناعي','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wz90tmq','https://sabq.org/article/wz90tmq','','https://sabq.org/article/wz90tmq','صحيفة سبق','السعودية','2026-08-06T12:09:43.097Z','2026-08-06T12:12:23.959Z','2026-08-06T20:21:15.144Z','https://media.sabq.org/news/2026/08/43fb16bb-cee8-4177-b9d9-8e0457fa055b/w1280.webp','/api/media/c197448c-b2c3-4743-8b93-313f424b6228','/api/media/c197448c-b2c3-4743-8b93-313f424b6228?variant=thumbnail','جمعية البر بمكة تنفّذ معسكري «اكتشاف» و«الجيل التقني» لتأهيل المستفيدين',1280,853,'valid','published','archived','valid',53,'a18dd233cbd3c8fbeba0bdb5bc9cd10902e3d4c13c8b1d2ffcde849c3c5ccaa8','f52c2cefefb691fefe2121f3574696bc1024c92a99d6418ede0ed75220bcc3ad',NULL,'2026-08-06T20:21:15.144Z','2026-10-07T20:24:27.552Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي","مكة"]','["الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":4.5},{"category":"المناطق","score":3},{"category":"التعليم","score":3}]','Active','2026-10-07T19:41:54.509Z',200,85,0,'source_article_available','',NULL,NULL,'body:6033ea3bd0130605729cd11db6fff8a89dab00d23ccc0455797dae1205e6d3d4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('397c3ef3-a11c-4da6-bf2e-91252008d882','news-397c3ef3-a11c-4da6-bf2e-91252008d882','جدة تستضيف النسخة الخامسة من معرض «سيريدو» العقاري في سبتمبر','جده تستضيف النسخه الخامسه من معرض سيريدو العقاري في سبتمبر','تستضيف مدينة جدة النسخة الخامسة من معرض «سيريدو» للتطوير والتملك العقاري 2026، خلال الفترة من 6 إلى 8 سبتمبر المقبل في «جدة سوبر دوم»، وذلك برعاية ومشاركة وزارة البلديات والإسكان.','["ويُشكّل المعرض منصةً رائدة تهدف إلى تعزيز فرص الاستثمار واستعراض أحدث المشاريع والحلول المبتكرة في القطاع العقاري بالمملكة، إذ يجمع نخبة من المطورين العقاريين والمستثمرين وجهات التمويل لبناء شراكات وفتح آفاق جديدة للتعاون.","ويتضمن المعرض برنامجاً معرفياً يشمل ورش عمل وجلسات حوارية يقودها خبراء ومتخصصون، لمناقشة التوجهات الحديثة والتحديات في السوق العقارية، واستعراض أفضل الممارسات الداعمة للتنمية العمرانية بما يتماشى مع مستهدفات رؤية 2030.","وأعربت الأميرة دينا بنت سعود بن عبد العزيز، رئيس مجلس إدارة معرض «سيريدو 2026»، عن شكرها لوزارة البلديات والإسكان على دعمها ورعايتها، مؤكدةً أن هذه النسخة تمثل محطة جديدة في مسيرة المعرض نحو منصة متكاملة تُعزز فرص التعاون وتواكب النمو المتسارع في القطاع العقاري بالمملكة.","وأشار عبد الرحمن الزهراني، المدير التنفيذي لمعرض «سيريدو 2026»، إلى القيمة العالية التي يحققها الحدث من خلال ربط أبرز المطورين والمستثمرين والهيئات الحكومية لاستكشاف آفاق النمو وسبل التعاون."]','العقارات','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/iloy9a9','https://sabq.org/article/iloy9a9','','https://sabq.org/article/iloy9a9','صحيفة سبق','السعودية','2026-08-06T12:11:29.387Z','2026-08-06T12:12:02.404Z','2026-08-06T20:21:15.174Z','https://media.sabq.org/news/2026/08/170652b4-0cc2-4e7f-ab57-8f635f23f362/w1280.webp','/api/media/397c3ef3-a11c-4da6-bf2e-91252008d882','/api/media/397c3ef3-a11c-4da6-bf2e-91252008d882?variant=thumbnail','جدة تستضيف النسخة الخامسة من معرض «سيريدو» العقاري في سبتمبر',1280,853,'valid','published','archived','valid',53,'e1765583f671f681b232a3e056b1e5d6b9fd8214ed739248ba373138e696a88a','ef9f5fb89f9327ceb552dca372890115d73f5a34529d8534035c5dd7989379d8',NULL,'2026-08-06T20:21:15.174Z','2026-10-07T20:24:27.554Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إدارة معرض سيريدو","رئيس مجلس إدارة معرض سيريدو","الاقتصاد والأسواق","جدة"]','["مجلس إدارة معرض سيريدو","رئيس مجلس إدارة معرض سيريدو","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":4},{"category":"المناطق","score":3},{"category":"المجتمع","score":3}]','Temporarily Unreachable','2026-10-07T19:41:17.365Z',NULL,86,4,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8eff38d7-4dfa-4a89-8c17-9b84808890a7','news-8eff38d7-4dfa-4a89-8c17-9b84808890a7','الذكاء الاجتماعي العكسي: حين يتحول فهم مشاعرك إلى أداة تُستغل ضدك','الذكاء الاجتماعي العكسي حين يتحول فهم مشاعرك الي اداه تستغل ضدك','قد تقابل شخصاً يفهم أفكارك قبل أن تقولها، إلى حد يجعلك مطمئناً للتعامل معه.','["قد تقابل شخصاً يفهم أفكارك قبل أن تقولها، إلى حد يجعلك مطمئناً للتعامل معه. لكن في حين يبدو الأمر إيجابياً ومطلوباً، قد يكون السبب في شقائك وقلقك؛ لأن الطرف الآخر الذي قد يتمتع بالذكاء الاجتماعي، ربما يستخدم فهمه عنك بشكل عكسي. على الرغم من أن الذكاء الاجتماعي مهارةٌ يقول عنها الخبراء إنها مهمة لإقامة علاقات سوية، غير أن ثمة أشخاصاً يستخدمونها لمصالح شخصية، أو لكسب فرص والسيطرة على علاقات على نحو مخطط وسلبي. وهنا…","بحسب تقرير نشره موقع \"Psychology Today\" الأمريكي المتخصص في علم النفس؛ فإن الذكاء الاجتماعي في أصله مهارةٌ إيجابية تدفع الشخص لفهم مشاعر الآخرين والتفاعل معهم بحكمة، تساعد على بناء علاقات صحية والنجاح في العمل والحياة. لكن في صورته السلبية، يمكن أن يتحول إلى فن التلاعب الاجتماعي بالآخرين لتحقيق مكاسب شخصية أنانية بحتة؛ فيتحول الطرف الآخر إلى مجرد أداة تُستخدم للوصول إلى هدف معيّن؛ حتى ولو كان الثمن إيذاءه. ويلفت…","يوضح موقع \"Psych Central\" أن ما يُعرف بـ\"علم النفس المظلم\" يهتم بدراسة كيفية استخدام بعض الأشخاص لفهمهم العميق للعواطف والمشاعر الاجتماعية؛ للتلاعب بالآخرين أو السيطرة عليهم بطرق مؤذية. ويربط الموقع هذا السلوك بثلاث سمات شخصية معروفة باسم \"الثالوث المظلم\":","والمفارقة، بحسب الموقع، أن الشخص صاحب الذكاء العاطفي المرتفع، يمتلك بالفعل مهارات التعاطف والتكيّف الاجتماعي وحل المشاكل بسلاسة. لكن هذه المهارات ذاتها يمكن أن تُوجّه في اتجاه مظلم تماماً حين تُستخدم لأغراض، الهدف منها التلاعب بدلاً عن التواصل الإيجابي والواضح."]','التقنية','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%A8%D9%84%D8%B3/%D8%B4%D8%A8%D8%A7%D8%A8-%D9%88%D8%A8%D9%86%D8%A7%D8%AA/1837586-%D8%A7%D9%84%D8%B0%D9%83%D8%A7%D8%A1-%D8%A7%D9%84%D8%A7%D8%AC%D8%AA%D9%85%D8%A7%D8%B9%D9%8A-%D8%A7%D9%84%D8%B9%D9%83%D8%B3%D9%8A','https://www.sayidaty.net/%D8%A8%D9%84%D8%B3/%D8%B4%D8%A8%D8%A7%D8%A8-%D9%88%D8%A8%D9%86%D8%A7%D8%AA/1837586-%D8%A7%D9%84%D8%B0%D9%83%D8%A7%D8%A1-%D8%A7%D9%84%D8%A7%D8%AC%D8%AA%D9%85%D8%A7%D8%B9%D9%8A-%D8%A7%D9%84%D8%B9%D9%83%D8%B3%D9%8A','1837586 at https://www.sayidaty.net','1837586 at https://www.sayidaty.net','نت','السعودية','2026-08-06T12:00:08.000Z','2026-08-06T09:44:30.000Z','2026-08-06T20:21:15.729Z','https://static.sayidaty.net/styles/1375_scale/public/2026-08/shutterstock_731680072%283%29_0.jpg?VersionId=3eeY__1QVRQ0SAj2rtwd82BWC6RxZNnJ','/api/media/8eff38d7-4dfa-4a89-8c17-9b84808890a7','/api/media/8eff38d7-4dfa-4a89-8c17-9b84808890a7?variant=thumbnail','الذكاء الاجتماعي العكسي: حين يتحول فهم مشاعرك إلى أداة تُستغل ضدك',1375,936,'valid','published','archived','valid',42,'d3994bb8d17180ee9859cb7bfbd93990df47ee04b7ccaf26fbc6a0ae787707dd','e4fb97587929cca43c86856c2210ae878d34697ea49eff8b3dfeb0d47a55018e',NULL,'2026-08-06T20:21:15.729Z','2026-10-07T20:24:27.557Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع"]','[]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":1.5},{"category":"الرياضة","score":1.5},{"category":"الثقافة","score":1.5}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('43f4a848-7afb-48ea-b953-52823000f1ce','news-43f4a848-7afb-48ea-b953-52823000f1ce','مطار روسي خطر ..يتجنبه المسافرون السعوديون حاليا لهذه الاسباب','مطار روسي خطر يتجنبه المسافرون السعوديون حاليا لهذه الاسباب','تحوّل مطار سوتشي الدولي، أحد أهم بوابات السياحة الروسية على البحر الأسود، إلى خيار سفر محفوف بالاضطرابات، بعدما تصدّر المطارات الروسية الأكثر تأثرًا بالقيود المؤقتة المرتبطة بتهديدات الطائرات المسيّرة خلال النصف الأول من عام 2026.','["وكشف تحليل استند إلى بيانات وكالة النقل الجوي الروسية «روسافياتسيا» أن مطار سوتشي خضع لقيود مؤقتة على الإقلاع والهبوط خلال 70 يومًا منفصلًا في الأشهر الستة الأولى من العام، متجاوزًا مطارات روسية رئيسية، بينها قازان وفنوكوفو ودوموديدوفو.","ولا يعني ذلك إغلاق المطار لمدة 70 يومًا كاملة؛ إذ كانت القيود تُفرض غالبًا لعدة ساعات عند رصد تهديدات محتملة، ثم تُرفع بعد التأكد من سلامة المجال الجوي.","لكن تكرارها أدى إلى اضطراب الجداول وتأخير الرحلات وتحويل بعضها إلى مطارات بديلة.","وفي بعض الأيام، تعرضت حركة الطيران في سوتشي للتعليق ما بين 3 و5 مرات خلال اليوم الواحد، وتراوحت مدة القيود بين ثماني دقائق وقرابة 17 ساعة."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/jy9s7b5','https://sabq.org/article/jy9s7b5','','https://sabq.org/article/jy9s7b5','خالد خليل','السعودية','2026-08-06T12:12:47.898Z','2026-08-06T12:13:30.842Z','2026-08-06T20:21:15.760Z','https://media.sabq.org/news/2026/08/06cb4778-706f-4b54-9ec0-9fdc75e4ae72/w980.webp','/api/media/43f4a848-7afb-48ea-b953-52823000f1ce','/api/media/43f4a848-7afb-48ea-b953-52823000f1ce?variant=thumbnail','مطار روسي خطر ..يتجنبه المسافرون السعوديون حاليا لهذه الاسباب',980,656,'valid','published','archived','valid',94,'cfaa045cd739e329bc70de3c2ea045d1b624cba3966161ccf583d523d05b8a5b','d85210d2faed2491db3f642ca708d074864c88c0f053f4e7fa9b0c5bbce5b64d',NULL,'2026-08-06T20:21:15.760Z','2026-10-07T19:36:10.720Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة"]','["السفر والسياحة"]','classified','','[{"category":"أخبار السعودية","score":1.5},{"category":"الثقافة","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T19:36:10.720Z',200,81,0,'source_article_available','',NULL,NULL,'body:54305cf28a578e33e9e05b7e097043f81a276aca6130831109a251e8a5db8c29','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fe69d21f-d38f-471f-8a81-6ea88340d9b2','news-fe69d21f-d38f-471f-8a81-6ea88340d9b2','رسمياً.. فينيسيوس مستمر مع ريال مدريد حتى 2032','رسميا فينيسيوس مستمر مع ريال مدريد حتي 2032','أعلن نادي ريال مدريد الإسباني، اليوم (الخميس)، تمديد عقد نجمه البرازيلي فينيسيوس جونيور، ليقطع الطريق على أرسنال الإنجليزي، الذي سعى للتعاقد معه.','["وقال النادي في بيان عبر موقعه الرسمي: «توصل ريال مدريد إلى اتفاق مع فينيسيوس جونيور لتمديد عقده حتى 30 يونيو 2032».","ومنذ انضمامه إلى «الميرنغي» في عام 2018، خاض فينيسيوس 375 مباراة، سجل خلالها 128 هدفاً، وتوج بـ14 لقباً، هي: دوري أبطال أوروبا (مرتين)، وكأس العالم للأندية (3 مرات)، وكأس السوبر الأوروبي (مرتين)، والدوري الإسباني (3 مرات)، وكأس ملك إسبانيا (مرة واحدة)، وكأس السوبر الإسباني (3 مرات).","وخلال مسيرته مع ريال مدريد، فاز فينيسيوس بجائزة «ذا بيست» لأفضل لاعب في العالم من الاتحاد الدولي لكرة القدم (فيفا) لعام 2024، كما اختير أفضل لاعب في كأس الإنتركونتيننتال 2024، وأفضل لاعب في دوري أبطال أوروبا لموسم 2023-2024، وأفضل لاعب في كأس العالم للأندية 2022، وأفضل لاعب شاب في دوري أبطال أوروبا لموسم 2021-2022."]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/sport/international/2260240','https://www.okaz.com.sa/sport/international/2260240','','https://www.okaz.com.sa/sport/international/2260240','محمد جمعة (القاهرة)','السعودية','2026-08-06T19:31:06.000Z','Wed, 07 Oct 2026 19:35:54 GMT','2026-08-06T20:21:15.778Z','https://www.okaz.com.sa/okaz/uploads/images/2026/08/06/2747511.webp','/api/media/fe69d21f-d38f-471f-8a81-6ea88340d9b2','/api/media/fe69d21f-d38f-471f-8a81-6ea88340d9b2?variant=thumbnail',' ',1200,800,'valid','published','archived','valid',99,'6328e0fbdff16de67f08cd870a92179b3ce7ce38b3f49d8cb9d7fd2ed74c6e46','691747a4ed1d501d8ff6ff737ae9d8ba55b2640a1af50add0b4e8dd1b168cb6e',NULL,'2026-08-06T20:21:15.778Z','2026-10-07T19:35:56.218Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","أوروبا"]','["الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"الصحة","score":0},{"category":"التعليم","score":0}]','Updated','2026-10-07T19:35:56.218Z',200,95,0,'source_content_changed','',NULL,NULL,'body:648c4b7a46a878b71977a90f9ea5077dd6e3e1da3873c9ef6fb0cc93b4971370','Wed, 07 Oct 2026 19:35:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e30597dd-15b8-407c-84f6-e9a82348596a','news-e30597dd-15b8-407c-84f6-e9a82348596a','تحت رعاية خادم الحرمين الشريفين.. انطلاق مسابقة الملك عبدالعزيز الدولية لحفظ القرآن الكريم وتلاوته وتفسيره','تحت رعايه خادم الحرمين الشريفين انطلاق مسابقه الملك عبدالعزيز الدوليه لحفظ القران الكريم وتلاوته وتفسيره','تحت رعاية خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود -حفظه الله- تبدأ اليوم الخميس 6 أغسطس 2026، أعمال الدورة السادسة والأربعين لمسابقة الملك عبدالعزيز الدولية لحفظ القرآن الكريم وتلاوته وتفسيره، التي تنظمها وزارة الشؤون الإسلامية والدعوة والإرشاد في مكة المكرمة، خلال الفترة من 23 صفر إلى 6 ربيع الأول 1448هـ، بمشاركة (334) متسابقًا ومتسابقة يمثلو','["وبحسب ما نشرته وكالة الأنباء السعودية \"واس\"، فتهدف المسابقة إلى تشجيع أبناء وبنات المسلمين على الإقبال على كتاب الله حفظًا وفهمًا وتدبرًا، وإذكاء روح المنافسة الشريفة، وربط الناشئة بكتاب الله، وإبراز جهود المملكة العربية السعودية وريادتها في خدمة القرآن الكريم وتعليمه ورعاية حفظته.","وتقام التصفيات النهائية والحفل الختامي للبنين في رحاب المسجد الحرام، فيما تُقام منافسات قسم الإناث والحفل الختامي في فندق هيلتون المؤتمرات بمكة المكرمة، في خطوة تاريخية تشهدها المسابقة بإقامة منافسات مستقلة للمرة الأولى، بما يعكس التطور الذي تشهده المسابقة واتساع نطاق المشاركة الدولية والاهتمام بالمرأة التي تعد نواة المجتمع الإسلامي.","وتتضمن المسابقة خمسة فروع تشمل حفظ القرآن الكريم كاملًا بالقراءات السبع المتواترة، وحفظه كاملًا مع تفسير مفرداته، وحفظه كاملًا، وحفظ خمسة عشر جزءًا، وحفظ خمسة أجزاء متتالية، فيما تبلغ القيمة الإجمالية لجوائزها (10,260,000) ريال، وهي الأعلى منذ بدء المسابقة. واستكملت الوزارة جميع الترتيبات التنظيمية والفنية واللوجستية لاستقبال المتسابقين وتهيئة مقار إقامة الوفود بجوار المسجد الحرام، إلى جانب تجهيز مواقع المنافسات…"]','أخبار السعودية','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%A8%D9%84%D8%B3/%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/1837602-%D9%85%D8%B3%D8%A7%D8%A8%D9%82%D8%A9-%D8%AD%D9%81%D8%B8-%D8%A7%D9%84%D9%82%D8%B1%D8%A2%D9%86-%D8%A7%D9%84%D9%83%D8%B1%D9%8A%D9%85','https://www.sayidaty.net/%D8%A8%D9%84%D8%B3/%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/1837602-%D9%85%D8%B3%D8%A7%D8%A8%D9%82%D8%A9-%D8%AD%D9%81%D8%B8-%D8%A7%D9%84%D9%82%D8%B1%D8%A2%D9%86-%D8%A7%D9%84%D9%83%D8%B1%D9%8A%D9%85','1837602 at https://www.sayidaty.net','1837602 at https://www.sayidaty.net','نت','السعودية','2026-08-06T11:57:56.000Z','2026-08-06T12:01:54.000Z','2026-08-06T20:21:15.800Z','https://static.sayidaty.net/styles/1375_scale/public/2026-08/504217.jpg?VersionId=JUPnyDFLGKvH2p68xIPgWL8rjH1y3o2a','/api/media/e30597dd-15b8-407c-84f6-e9a82348596a','/api/media/e30597dd-15b8-407c-84f6-e9a82348596a?variant=thumbnail','تحت رعاية خادم الحرمين الشريفين.. انطلاق مسابقة الملك عبدالعزيز الدولية لحفظ القرآن الكريم وتلاوته وتفسيره',1375,761,'valid','published','archived','valid',99,'4c1d58bc9666d03c55dc1516955de41f3548a46fa9f5cfb36d3730a1e14597e7','51429494603416abc784c93c9e73c6d02c208e5ed13be78a7a5f7aa84f0dabfa',NULL,'2026-08-06T20:21:15.800Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["خادم الحرمين الشريفين انطلاق مسابقة","السفر والسياحة","التعليم والتدريب","مكة"]','["خادم الحرمين الشريفين انطلاق مسابقة","السفر والسياحة","التعليم والتدريب"]','classified','','[{"category":"المناطق","score":3},{"category":"المجتمع","score":3},{"category":"الثقافة","score":3}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4f6c08d7-b199-49bd-85ec-30b4635d5bd5','news-4f6c08d7-b199-49bd-85ec-30b4635d5bd5','تساقط الشعر عند الأطفال.. مشكلة عابرة أم مؤشر طبي؟','تساقط الشعر عند الاطفال مشكله عابره ام مؤشر طبي','قد يكون تساقط الشعر عند الأطفال ناتجاً عن أسباب طبية وغير طبية، وقد يكون مزعجاً للطفل ووالديه ورغم ذلك، توجد العديد من العلاجات المنزلية للحدّ من تساقط الشعر وتشجيع نمو شعر صحي، فقد يكون رؤية أطفالك يعانون من تساقط الشعر أمراً مقلقاً ومؤلماً ونظراً لأسبابه الطبية، ونقص بعض العناصر الغذائية، أو الإصابة بالثعلبة، فقد لا يكون من الممكن دائماً الوقاية منه وبعيدا','["قد يكون تساقط الشعر عند الأطفال ناتجاً عن أسباب طبية وغير طبية، وقد يكون مزعجاً للطفل ووالديه ورغم ذلك، توجد العديد من العلاجات المنزلية للحدّ من تساقط الشعر وتشجيع نمو شعر صحي، فقد يكون رؤية أطفالك يعانون من تساقط الشعر أمراً مقلقاً ومؤلماً ونظراً لأسبابه الطبية، ونقص بعض العناصر الغذائية، أو الإصابة بالثعلبة، فقد لا يكون من الممكن دائماً الوقاية منه وبعيداً عن السبب، فإن العلاج في الوقت المناسب والرعاية المناسبة…","حوالي ثلاثة بالمئة من زياراتهم لطبيب الأطفال، ورغم أن تساقط الشعر المؤقت لدى الأطفال أمر شائع قبل نمو الشعر الدائم، إلا أن تساقط الشعر بمعدل متزايد وظهور بقع صلعاء قد يكون مدعاة للقلق. وبالرغم من إمكانية السيطرة على تساقط الشعر المبكر لدى الأطفال بالعلاج والرعاية والأدوية المناسبة، إلا أن رؤية الطفل يفقد كل هذا الشعر في هذه السن المبكرة قد يكون أمراً مؤلماً في البداية و تشمل الأسباب الأكثر شيوعاً لهذه المشكلة لدى…","سعفة الرأس أو القوباء الحلقية هي السبب الأكثر شيوعاً لتساقط الشعر عند الأطفال. وهي عدوى فطرية سطحية معدية يمكن أن تصيب فروة الرأس والحواجب والرموش.","وتُعدّ هذه العلامات مفيدة للتشخيص الأولي من قِبل الوالدين ورغم ذلك، قد يستخدم طبيب طفلك تقنيات سريرية أخرى للتشخيص و قد يصف الطبيب كريمات وشامبو مضاداً للفطريات و قد لا يكون الأطفال الذين يخضعون للعلاج معديين، لذا يمكن إرسالهم إلى المدرسة بعد بدء العلاج."]','الصحة','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D8%B3%D9%8A%D8%AF%D8%AA%D9%8A-%D9%88%D8%B7%D9%81%D9%84%D9%83/%D8%B5%D8%AD%D8%A9-%D8%A7%D9%84%D8%B7%D9%81%D9%84/1837577-%D8%AA%D8%B3%D8%A7%D9%82%D8%B7-%D8%A7%D9%84%D8%B4%D8%B9%D8%B1-%D8%B9%D9%86%D8%AF-%D8%A7%D9%84%D8%A3%D8%B7%D9%81%D8%A7%D9%84','https://www.sayidaty.net/%D8%B3%D9%8A%D8%AF%D8%AA%D9%8A-%D9%88%D8%B7%D9%81%D9%84%D9%83/%D8%B5%D8%AD%D8%A9-%D8%A7%D9%84%D8%B7%D9%81%D9%84/1837577-%D8%AA%D8%B3%D8%A7%D9%82%D8%B7-%D8%A7%D9%84%D8%B4%D8%B9%D8%B1-%D8%B9%D9%86%D8%AF-%D8%A7%D9%84%D8%A3%D8%B7%D9%81%D8%A7%D9%84','1837577 at https://www.sayidaty.net','1837577 at https://www.sayidaty.net','لمياء جمال','السعودية','2026-08-06T11:45:00.000Z','2026-08-06T09:07:13.000Z','2026-08-06T20:21:15.824Z','https://static.sayidaty.net/styles/1375_scale/public/2026-08/503989.jpg?VersionId=18Xygfe7B0HAICWgrPS28pPey1Do2IQM','/api/media/4f6c08d7-b199-49bd-85ec-30b4635d5bd5','/api/media/4f6c08d7-b199-49bd-85ec-30b4635d5bd5?variant=thumbnail','تساقط الشعر عند الأطفال.. مشكلة عابرة أم مؤشر طبي؟',1375,750,'valid','published','archived','valid',83,'4c48ba448d1c90763839832c6f786425ba2e24f734763f77f32c8fbac7f29884','be468dd1b9b654cb304e7d1db9cf2199859146057b3f109a466d6ccba6642358',NULL,'2026-08-06T20:21:15.824Z','2026-08-28T20:48:32.795Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","التعليم والتدريب"]','["الصحة العامة","التعليم والتدريب"]','manual_approved','','[]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e5433627-7d0b-43ef-94a2-52a6e4886018','news-e5433627-7d0b-43ef-94a2-52a6e4886018','متحدث الدفاع: تهديدات حقيقية في المنطقة وتحالف اليمن يحقق إنجازات بحرية كبيرة','متحدث الدفاع تهديدات حقيقيه في المنطقه وتحالف اليمن يحقق انجازات بحريه كبيره','أكد متحدث وزارة الدفاع اللواء الركن تركي المالكي أن المنطقة والعالم يشهدان تهديدات حقيقية وناشئة تستوجب اليقظة والتعامل الحازم، مشدداً على أن لكل دولة الحق في اتخاذ الإجراءات العسكرية أو السياسية اللازمة لحماية مصالحها والتعامل مع هذه التهديدات.','["وأوضح المالكي في تصريحات لقناة «الإخبارية» أن تحالف دعم الشرعية في اليمن حقق إنجازات كبيرة في مواجهة التهديدات البحرية، إذ واجه على مدى السنوات الماضية تحديات متعددة شملت الطائرات المسيّرة والقوارب السريعة والألغام البحرية.","وأشار إلى أن التحالف البحري يضطلع بمهمة محورية تتمثل في حماية خطوط الملاحة والممرات المائية الحيوية وناقلات النفط، لافتاً إلى أن أي عمليات إرهابية أو إرهاب بحري ستطال تداعياتها جميع دول العالم دون استثناء."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/hnheohn','https://sabq.org/article/hnheohn','','https://sabq.org/article/hnheohn','صحيفة سبق','السعودية','2026-08-06T11:40:42.794Z','2026-08-06T11:41:23.355Z','2026-08-06T20:21:16.976Z','','','/api/media/fallback/%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1%20%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9','متحدث الدفاع: تهديدات حقيقية في المنطقة وتحالف اليمن يحقق إنجازات بحرية كبيرة',NULL,NULL,'fetch failed','review','archived','valid',40,'8d0a5cd4fb5c126f78d69460791b3e67b4e735d00b616d2f84645025649c2dce','ecf4cd0644d24cbd495544f6fed77a4f84aa45c701332395955e031b5ced69c9',NULL,'2026-08-06T20:21:16.976Z','2026-10-07T19:41:38.626Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية","الطاقة والنفط","اليمن","وتحالف اليمن يحقق","اليمن يحقق إنجازات","يحقق إنجازات بحرية","متحدث الدفاع تهديدات","المنطقة وتحالف اليمن"]','["أخبار السعودية","الطاقة والنفط","وتحالف اليمن يحقق","اليمن يحقق إنجازات","يحقق إنجازات بحرية","متحدث الدفاع تهديدات"]','needs_review','below_category_threshold','[{"category":"العالم","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Temporarily Unreachable','2026-10-07T19:41:38.626Z',NULL,79,4,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('82661a58-2504-4875-a5ee-cb847bfa96b3','news-82661a58-2504-4875-a5ee-cb847bfa96b3','واتساب يختبر ميزة جديدة لتمييز المحتوى المُولّد بالذكاء الاصطناعي','واتساب يختبر ميزه جديده لتمييز المحتوي المولد بالذكاء الاصطناعي','يستعد تطبيق "واتساب" لتطوير ميزة جديدة تتيح لمسؤولي القنوات وضع علامة توضح أن الصور أو مقاطع الفيديو المنشورة تم إنشاؤها باستخدام الذكاء الاصطناعي، في خطوة تهدف إلى تعزيز الشفافية ومساعدة المستخدمين على التمييز بين المحتوى الحقيقي والمحتوى المُولد آليًا.','["يستعد تطبيق \"واتساب\" لتطوير ميزة جديدة تتيح لمسؤولي القنوات وضع علامة توضح أن الصور أو مقاطع الفيديو المنشورة تم إنشاؤها باستخدام الذكاء الاصطناعي، في خطوة تهدف إلى تعزيز الشفافية ومساعدة المستخدمين على التمييز بين المحتوى الحقيقي والمحتوى المُولد آليًا. وتأتي هذه الميزة بعد أسابيع من بدء \"واتساب\" طرح ملصق \"شراكة مدفوعة\" (Paid Partnership) الذي يسمح لمسؤولي القنوات بالإفصاح عن المنشورات الدعائية على نظامي أندرويد…","وبحسب موقع \"WaBetaInfo\"، ظهرت الميزة الجديدة في النسخة التجريبية 2.26.31.1 من \"واتساب\" على نظام أندرويد، والمتوفرة عبر متجر \"غوغل بلاي\". وعند إطلاقها رسميًا، سيتمكن مسؤولو القنوات من الضغط مطولًا على أي منشور يحتوي على صورة أو فيديو تم إنشاؤه بالذكاء الاصطناعي، ثم اختيار خيار جديد يحمل اسم \"إضافة علامة لمحتوى الذكاء الاصطناعي\" (Add AI content label) من القائمة. وبمجرد تفعيل الخيار، ستظهر علامة واضحة على المنشور…","ولن تُطبق هذه العلامة على الرسائل النصية، حتى إذا تمت كتابتها باستخدام أداة Writing Help المدمجة في \"واتساب\"، إذ تقتصر الميزة على الصور ومقاطع الفيديو المُنشأة بالذكاء الاصطناعي. كما لن تقتصر العلامة على محتوى تم إنشاؤه بأداة معينة، إذ ستُستخدم مع جميع الوسائط المنتجة عبر أدوات الذكاء الاصطناعي، سواء كانت Meta AI أو تشات جي بي تي أو جيميناي أو أي خدمة أخرى. ولا تزال الميزة قيد التطوير داخل النسخة التجريبية من…"]','الذكاء الاصطناعي','','6075a271-65b9-4e02-a57e-7529518e4e2a','سيدتي','https://www.sayidaty.net/%D9%84%D8%A7%D9%8A%D9%81-%D8%B3%D8%AA%D8%A7%D9%8A%D9%84/%D8%AA%D9%83%D9%86%D9%88%D9%84%D9%88%D8%AC%D9%8A%D8%A7/1837605-%D9%88%D8%A7%D8%AA%D8%B3%D8%A7%D8%A8','https://www.sayidaty.net/%D9%84%D8%A7%D9%8A%D9%81-%D8%B3%D8%AA%D8%A7%D9%8A%D9%84/%D8%AA%D9%83%D9%86%D9%88%D9%84%D9%88%D8%AC%D9%8A%D8%A7/1837605-%D9%88%D8%A7%D8%AA%D8%B3%D8%A7%D8%A8','1837605 at https://www.sayidaty.net','1837605 at https://www.sayidaty.net','نت','السعودية','2026-08-06T12:21:46.000Z','2026-08-06T12:24:50.000Z','2026-08-06T20:21:17.490Z','https://static.sayidaty.net/styles/1375_scale/public/2026-08/504235.jpg?VersionId=e9drhhUq6FB1YiGQFWcpL6ZTq440JDa3','/api/media/82661a58-2504-4875-a5ee-cb847bfa96b3','/api/media/82661a58-2504-4875-a5ee-cb847bfa96b3?variant=thumbnail','واتساب يختبر ميزة جديدة لتمييز المحتوى المُولّد بالذكاء الاصطناعي',1375,929,'valid','published','archived','valid',48,'f92a92fdb6e4f9de7b4a0ce572d58d0d9a0d101cbf5a64275378e7048a322cb4','76b50acb7465b138e2ccd5c84f903c9e3354b7f7e0b705d648ecaf33c828b4b6',NULL,'2026-08-06T20:21:17.490Z','2026-10-07T20:24:27.566Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع"]','[]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"الصحة","score":1.5},{"category":"الثقافة","score":1.5}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e73b6020-0c65-4995-bb2d-5a5974540f71','news-e73b6020-0c65-4995-bb2d-5a5974540f71','فنانة مصرية تستغيث بـ«الداخلية» بعد تعرُّضها لواقعة احتيال','فنانه مصريه تستغيث بـ الداخليه بعد تعرضها لواقعه احتيال','تصدّرت الفنانة المصرية الشابة نيجار محمد اهتمام منصات التواصل الاجتماعي بعد أن وجّهت استغاثة عاجلة إلى وزارة الداخلية، مطالبة بالتدخل السريع لاتخاذ الإجراءات القانونية ضد شخص تتهمه بالاستيلاء على أموالها بطرق غير مشروعة.','["وأوضحت نيجار، في مقطع فيديو نشرته عبر حسابها الرسمي على (إنستغرام)، أنها سلكت جميع المسارات القانونية وتقدمت ببلاغات رسمية، إلا أنها تواجه صعوبة في الوصول إلى المشكو في حقه لاستكمال إجراءات القضية، مؤكدةً ثقتها في قدرة الأجهزة الأمنية على كشف ملابسات الواقعة وضمان استرداد حقوقها.","وشهدت الأزمة تطورًا لافتًا عقب نشر الفيديو الأول، إذ كشفت نيجار أن عددًا من الأشخاص تواصلوا معها وأبلغوها بتعرضهم لوقائع مشابهة مع الشخص ذاته، بل أرسلوا مستندات ووثائق تدعم -وفق روايتها- وجود حالات أخرى تتقاطع مع شكواها. وأشارت إلى أن هذه الشهادات تُرجّح أن الأمر يتجاوز حدود تجربتها الفردية، داعيةً الجهات الأمنية والقضائية إلى فحص تلك البلاغات والوثائق والتحقق من صحتها واتخاذ ما يلزم قانونًا في حال ثبوتها.","وتأتي هذه التطورات فيما تحظى نيجار محمد بحضور متزايد في الدراما المصرية خلال السنوات الأخيرة، بعد مشاركتها في أعمال بارزة مثل (الاختيار 3)، و(جعفر العمدة)، و(حق عرب)، قبل أن يتصدر اسمها المشهد على منصات التواصل بسبب أزمتها الأخيرة."]','التقنية','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/culture/art/2260186','https://www.okaz.com.sa/culture/art/2260186','','https://www.okaz.com.sa/culture/art/2260186','«عكاظ» (القاهرة) Okaz-Online@','السعودية','2026-08-06T12:16:23.000Z','Wed, 07 Oct 2026 19:42:01 GMT','2026-08-06T20:21:17.573Z','https://www.okaz.com.sa/okaz/uploads/images/2026/08/06/2747273.webp','/api/media/e73b6020-0c65-4995-bb2d-5a5974540f71','/api/media/e73b6020-0c65-4995-bb2d-5a5974540f71?variant=thumbnail','فنانة مصرية تستغيث بـ«الداخلية» بعد تعرُّضها لواقعة احتيال',600,338,'valid','published','archived','valid',45,'8f7ddc9bfdcb61f88c3ba8b3a65b73fe4977f1cde6fdb64c8bd89e9a9e98c8e4','24a37da1c2da8b3808ab2d795920bfff6c425de2305c26bd16e022ce6b8e9d8c',NULL,'2026-08-06T20:21:17.573Z','2026-10-07T20:24:27.569Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Updated','2026-10-07T19:42:03.137Z',200,84,0,'source_content_changed','',NULL,NULL,'body:98b064e21389f7a071691a57ee6867973597a35f192ff41a77b90041654949a6','Wed, 07 Oct 2026 19:42:01 GMT');
