INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4ec3e43d-acc0-46b1-9f89-f64cdf10d8f4','news-4ec3e43d-acc0-46b1-9f89-f64cdf10d8f4','الليلة.. الهلال يوقع عقدا جديدا','الليله الهلال يوقع عقدا جديدا','يوقع الهلال مساء الأربعاء، عقد رعاية جديدًا مع شركة ريف، يمتد نحو 5 مواسم، بملعب «المملكة أرينا» في الرياض، وفق مصدر خاص بـ«الرياضية».','["يوقع الهلال مساء الأربعاء، عقد رعاية جديدًا مع شركة ريف، يمتد نحو 5 مواسم، بملعب «المملكة أرينا» في الرياض، وفق مصدر خاص بـ«الرياضية». وأشار المصدر ذاته، إلى أن عقد الشراكة الذي يحضره الأمير نواف بن سعد رئيس النادي، والإسباني ستيف كالزادا، الرئيس التنفيذي، وممثلو الشركة، يأتي ضمن سلسلة الشراكات التي أبرمتها إدارة القطب العاصمي وكان آخرها التوقيع مع «NHC» راعيًا رسميًا. من جانب آخر، يستعد لاعبو فريق الهلال للعودة…"]','الرياضة','','3f4e91c6-d3a5-4718-8296-4aed4e425952','الرياضية','https://arriyadiyah.com/897269/%D8%A7%D9%84%D9%84%D9%8A%D9%84%D8%A9..-%D8%A7%D9%84%D9%87%D9%84%D8%A7%D9%84-%D9%8A%D9%88%D9%82%D8%B9-%D8%B9%D9%82%D8%AF%D8%A7-%