INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('daebd008-0ca0-47ad-831f-81d511df899d','news-daebd008-0ca0-47ad-831f-81d511df899d','لوبي بعد التوقيع مع الاتحاد: أصبحت نمرا مقاتلا','لوبي بعد التوقيع مع الاتحاد اصبحت نمرا مقاتلا','أعلن نادي الاتحاد، الأربعاء، رسميًا التعاقد مع السنغالي ديون لوبي لتدعيم صفوف الفريق الأول لكرة القدم حتى 2029 قادمًا من ألميريا الإسباني.','["أعلن نادي الاتحاد، الأربعاء، رسميًا التعاقد مع السنغالي ديون لوبي لتدعيم صفوف الفريق الأول لكرة القدم حتى 2029 قادمًا من ألميريا الإسباني. وكتب النادي الجداوي عبر حسابه الرسمي في منصة «إكس»: «مـن أرض التيرانجا إلـى عرين النمور»، وأرفق العبارة بفيديو للاعب الوسط السنغالي، قال فيه: «من أول لمسة للكرة تعلمت أن المباريات لا تحسم بالأهداف فقط بل بالإصرار والقتالية داخل الملعب، وفي كل محطة مررت بها كنت أبحث عن تحد جديد،…"]','الرياضة','','3f4e91c6-d3a5-4718-8296-4aed4e425952','الرياضية','https://arriyadiyah.com/897292/%D9%84%D9%88%D8%A8%D9%8A-%D8%A8%D8%B9%D8%AF-%D8%A7%D9%84%D8%AA%D9%88%D9%82%D9%8A%D8%B9-%D9