INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a577534a-ccca-4443-ac93-47ae23ff29f2','news-a577534a-ccca-4443-ac93-47ae23ff29f2','اقتصادي / محطة الحناكية (1) للطاقة الشمسية بالمدينة المنورة تكفي لتزويد حوالي 190 ألف منزل بالكهرباء سنويًا','اقتصادي محطه الحناكيه 1 للطاقه الشمسيه بالمدينه المنوره تكفي لتزويد حوالي 190 الف منزل بالكهرباء سنويا','المدينة المنورة 22 صفر 1448 هـ الموافق 05 أغسطس 2026 م واس تُعدّ محطة الحناكية (1) للطاقة الشمسية الكهروضوئية أحد مشروعات البرنامج الوطني للطاقة المتجددة الذي تُشرف على تنفيذه وزارة الطاقة، حيث تبلغ سعة المشروع 1100 ميجاواط، وتكفي لتزويد حوالي 190 ألف منزل بالكهرباء سنويًا.','["وتقع المحطة، التي بدأت أعمال تشغيلها خلال صيف عام 2025م، جنوب محافظة الحناكية بمنطقة المدينة المنورة، فيما يبلغ سعر شراء الكهرباء المنتجة منها 1.68420 سنتًا أمريكيًا لكل كيلوواط ساعة، مما يؤكد تنافسية مشروعات الطاقة المتجددة في المملكة، وقدرتها على تحقيق أسعار إنتاج كهرباء منافسة عالميًا.","ويأتي المشروع في إطار جهود المملكة للتوسع في استخدام مصادر الطاقة المتجددة وأنظمة تخزين الطاقة، ودعم مستهدفات برنامج إزاحة الوقود السائل، وخفض الانبعاثات.","كما يُعد مشروع الحناكية (1) أحد مشروعات المرحلة الرابعة من البرنامج الوطني للطاقة المتجددة، ويواكب مستهدفات رؤية السعودية 2030 الرامية إلى رفع مساهمة الطاقة المتجددة وأنظمة تخزين الطاقة إلى ما يقارب 50% من مزيج الطاقة لإنتاج الكهرباء بحلول عام 2030م، حسب نمو الطلب على الكهرباء، ويدعم تنويع مصادر الطاقة، ويعزز أمنها واستدامتها.","يذكر أن الشركة السعودية لشراء الطاقة (المشتري الرئيس) هي الجهة المسؤولة عن إعداد الدراسات التمهيدية، وطرح مشروعات توليد الكهرباء وتوقيع اتفاقيات شراء الطاقة، واتفاقيات خدمات تخزين الطاقة مع التحالفات المطوِّرة."]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2647956?type=news&uuid=N2647956','https://spa.gov.sa/ar/N2647956?type=news&uuid=N2647956','N2647956','N2647956','','السعودية','2026-08-05T08:29:00.000Z',NULL,'2026-08-06T20:54:04.753Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10562027.jpg','/api/media/a577534a-ccca-4443-ac93-47ae23ff29f2','/api/media/a577534a-ccca-4443-ac93-47ae23ff29f2?variant=thumbnail','اقتصادي / محطة الحناكية (1) للطاقة الشمسية بالمدينة المنورة تكفي لتزويد حوالي 190 ألف منزل بالكهرباء سنويًا',1600,899,'valid','published','archived','valid',56,'f8a8ac97e172ce3ae40e90942b3eeb9a4f7ae181b17aa9933365951ce5e3326e','9b38056e09be11aa2d97804349dcd340b4c1f4be0fb0f49450360c820d27dca0',NULL,'2026-08-06T20:54:04.753Z','2026-10-07T20:24:27.644Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الاقتصاد والأسواق","المدينة المنورة"]','["الطاقة والنفط","الاقتصاد والأسواق","المدينة المنورة"]','manual_approved','ambiguous_category','[{"category":"الطاقة والصناعة","score":7},{"category":"الاقتصاد","score":4.5},{"category":"أخبار السعودية","score":3}]','Active','2026-10-07T19:51:13.516Z',200,78,0,'source_article_available','',NULL,NULL,'body:778ac6325db37a3d64da41932065ddc3b2e0e29ac5d90d8432553483a109e0cd','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0d80d408-2804-477d-9b0d-a64e058c36d4','news-0d80d408-2804-477d-9b0d-a64e058c36d4','علوم وتقنيات / "كاوست" تطور تقنية جديدة للأغشية تقلل استهلاك الطاقة في عمليات فصل الغازات الصناعية','علوم وتقنيات كاوست تطور تقنيه جديده للاغشيه تقلل استهلاك الطاقه في عمليات فصل الغازات الصناعيه','جدة 22 صفر 1448 هـ الموافق 05 أغسطس 2026 م واس طوّرت جامعة الملك عبدالله للعلوم والتقنية "كاوست" تقنية جديدة للأغشية تسهم في خفض استهلاك الطاقة في عمليات فصل الغازات الصناعية، التي تمثل نحو 15% من إجمالي استهلاك الطاقة عالميًا، وذلك بالتعاون مع شركاء أكاديميين من الصين وفرنسا.','["وأوضحت الجامعة أن الدراسة، المنشورة في مجلة \"نيتشر\"، ركزت على الأطر المعدنية العضوية (MOFs)، وهي مواد فائقة المسامية تمتاز بقدرتها العالية على فصل الجزيئات، إذ نجح الفريق البحثي في تطوير بنية جديدة للأغشية تتكون من أكثر من 90% من هذه المادة، مع الحفاظ على مرونتها ومتانتها وتوافقها مع تقنيات التصنيع الصناعية.","وتمكَّن الباحثون من تجاوز أحد أبرز التحديات التقنية باستخدام مرساة جزيئية صغيرة تربط الصفائح النانوية للأطر المعدنية العضوية بسلاسل البوليمرات؛ بما يضمن أداءً عاليًا وإمكانية تصنيع الأغشية على نطاق واسع.","ولإثبات جدوى التقنية صناعيًا، نجح الفريق في إنتاج لفائف أغشية متصلة بطول 20 مترًا باستخدام تقنية التصنيع المستمر (Roll-to-Roll)، في خطوة تؤكد إمكانية دمجها ضمن خطوط الإنتاج الصناعية القائمة.","وأكد أستاذ علوم الكيمياء في \"كاوست\" وأحد المؤلفين المراسلين للدراسة البروفيسور محمد الداوودي، أن الابتكار يمثل مسارًا عمليًا لتصنيع أغشية متقدمة بالحجم الذي تتطلبه الصناعة، بما يقرب هذه التقنية من مرحلة التطبيق الفعلي، مشيرًا إلى أن عمليات الفصل الصناعية تستهلك كميات كبيرة من الطاقة يوميًا."]','الطاقة والصناعة','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2647840?type=news&uuid=N2647840','https://spa.gov.sa/ar/N2647840?type=news&uuid=N2647840','N2647840','N2647840','','السعودية','2026-08-05T05:43:00.000Z','2026-06-24T11:20:00.000Z','2026-08-06T20:54:05.005Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10561150.jpg','/api/media/0d80d408-2804-477d-9b0d-a64e058c36d4','/api/media/0d80d408-2804-477d-9b0d-a64e058c36d4?variant=thumbnail','علوم وتقنيات / "كاوست" تطور تقنية جديدة للأغشية تقلل استهلاك الطاقة في عمليات فصل الغازات الصناعية',1600,988,'valid','published','archived','valid',86,'4eb8cc84929a37343d22899f1d43f3fc6852776fed1832c7ca2c568a93f4e50a','1bfe96e474ebdbfbff10831189255d443a005618731ca9c85060fcfa1c9f911a','محدّث','2026-08-06T20:54:05.005Z','2026-10-07T19:45:10.878Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","التعليم والتدريب","التقنية والتحول الرقمي"]','["الطاقة والنفط","التعليم والتدريب","التقنية والتحول الرقمي"]','classified','','[{"category":"التقنية","score":4.5},{"category":"الوظائف وسوق العمل","score":3},{"category":"الصحة","score":1.5}]','Active','2026-10-07T19:45:10.878Z',200,73,0,'source_article_available','',NULL,NULL,'body:53f9cbd7226e79a5afb6888c9176980935d53be6d28c3b7fef514932abd1424d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8f9d44b7-0a36-48b9-9893-959ea25e31fe','news-8f9d44b7-0a36-48b9-9893-959ea25e31fe','عام / "هيئة الطرق": أكثر من 5 آلاف تصريح لتنظيم الأعمال على شبكة الطرق خلال يوليو الماضي','عام هيئه الطرق اكثر من 5 الاف تصريح لتنظيم الاعمال علي شبكه الطرق خلال يوليو الماضي','الرياض 22 صفر 1448 هـ الموافق 05 أغسطس 2026 م واس أعلنت الهيئة العامة للطرق إصدار أكثر من 5 آلاف تصريح لتنظيم الأعمال على شبكة الطرق خلال شهر يوليو الماضي، وذلك في إطار جهودها المستمرة؛ لضمان سلامة الطرق، ورفع كفاءتها التشغيلية.','["وتهدف هذه الخدمات إلى تسهيل طلبات التصاريح، ورفع مستوى السلامة، وتعزيز تجربة الشركات من خلال تحسين مستوى الخدمات المقدمة لها، انطلاقًا من دور الهيئة في تنظيم قطاع الطرق والإشراف عليه.","وأوضحت الهيئة أن إجمالي التصاريح الصادرة خلال شهر يوليو الماضي بلغ 5,500 تصريح، شملت 5,250 تصريحًا للحمولات الاستثنائية، و192 تصريحًا للحفر، و28 تصريحًا لتمديد الحفر، و83 طلبًا لإخلاء الطرف، مشيرةً إلى أن هذه الإحصاءات تعكس فعالية خدمة إصدار التصاريح على شبكة الطرق خارج النطاق العمراني، التي أطلقتها الهيئة عبر موقعها الإلكتروني.","وتسعى الهيئة من خلال هذه الجهود إلى رفع مستوى السلامة والجاهزية على شبكة الطرق، وتحقيق أهداف برنامج قطاع الطرق، بخفض عدد الوفيات على الطرق إلى أقل من 5 حالات لكل 100 ألف نسمة، كما تهدف إلى تغطية شبكة الطرق بعوامل السلامة المرورية وفقًا لتصنيف البرنامج الدولي لتقييم الطرق (IRAP)، والحفاظ على مستوى متقدم من خدمات شبكة الطرق."]','السيارات','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2647924?type=news&uuid=N2647924','https://spa.gov.sa/ar/N2647924?type=news&uuid=N2647924','N2647924','N2647924','','السعودية','2026-08-05T07:23:00.000Z',NULL,'2026-08-06T20:54:05.098Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10561545.png','/api/media/8f9d44b7-0a36-48b9-9893-959ea25e31fe','/api/media/8f9d44b7-0a36-48b9-9893-959ea25e31fe?variant=thumbnail','عام / "هيئة الطرق": أكثر من 5 آلاف تصريح لتنظيم الأعمال على شبكة الطرق خلال يوليو الماضي',1600,2991,'valid','published','archived','valid',50,'3f87b3e7803476680f0d32ff7d2abef524b29592f2bc9fe69e91d4ae7bb2bab5','584f06db6b96b0562f39ef4754c82828ed107ed2bcb363fd1dfb3ad5bc565ec9',NULL,'2026-08-06T20:54:05.098Z','2026-10-07T20:24:27.649Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الطرق أكثر من"]','["هيئة الطرق أكثر من"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Temporarily Unreachable','2026-10-07T19:50:17.664Z',NULL,76,8,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e152ab39-0d4a-4d66-9356-bdc119c04813','news-e152ab39-0d4a-4d66-9356-bdc119c04813','ثقافي / معرض "كنوز غارقة".. رحلة معرفية تستكشف التراث البحري للبحر الأحمر','ثقافي معرض كنوز غارقه رحله معرفيه تستكشف التراث البحري للبحر الاحمر','جدة 22 صفر 1448 هـ الموافق 05 أغسطس 2026 م واس يجسد معرض "كنوز غارقة: التراث البحري للبحر الأحمر"، الذي يحتضنه متحف البحر الأحمر في جدة التاريخية، إحدى أبرز المبادرات الثقافية التي تسلط الضوء على الإرث البحري للمملكة، من خلال تجربة معرفية تستعرض تاريخ البحر الأحمر بوصفه ممرًا حضاريًا أسهم عبر آلاف السنين في ازدهار التجارة البحرية، ورحلات الحج، والتواصل بين ا','["ويقدم المعرض، المستمر حتى 15 أغسطس 2026، رحلة تفاعلية عبر مقتنيات أثرية وخرائط تاريخية وأدوات ملاحة، إلى جانب مكتشفات من مواقع التراث الثقافي المغمور بالمياه، تكشف جانبًا من تاريخ الملاحة البحرية، وتبرز دور البحر الأحمر في ربط شبه الجزيرة العربية بإفريقيا وآسيا، وما شهدته مياهه من حركة تجارية وثقافية أسهمت في تشكيل تاريخ المنطقة عبر العصور.","ويستعرض المعرض نماذج من حطام السفن واللقى الأثرية التي حفظتها أعماق البحر لقرون، بوصفها شواهد مادية توثق مسارات التجارة والرحلات البحرية، إلى جانب إبراز جهود البحث الأثري في إعادة قراءة هذا الإرث وتحويله إلى محتوى معرفي يعزز الوعي بقيمة التراث الثقافي المغمور بالمياه.","ويُجسد المعرض ثمرة التعاون بين هيئة المتاحف وهيئة التراث وبرنامج جدة التاريخية، من خلال توظيف أحدث تقنيات العرض المتحفي، بما يسهم في تقديم تجربة ثقافية تفاعلية، وترسيخ دور المتاحف بوصفها منصات لإنتاج المعرفة، ودعم البحث العلمي، وتعزيز مستهدفات رؤية السعودية 2030 في صون الهوية الوطنية وإبراز الإرث الثقافي للمملكة.","ويعزز معرض \"كنوز غارقة\" الحراك الثقافي الذي تشهده جدة خلال موسم الصيف، بوصفه أحد أبرز التجارب المعرفية ضمن فعاليات \"صيفنا على كيفنا\"، إذ يقدم للزوار تجربة متحفية تجمع بين التاريخ والآثار والبيئة البحرية، وتسهم في إثراء المشهد الثقافي، وتعزيز المشاركة المجتمعية، وترسيخ مكانة جدة وجهةً للسياحة الثقافية والمعرفية."]','الثقافة','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2648284?type=news&uuid=N2648284','https://spa.gov.sa/ar/N2648284?type=news&uuid=N2648284','N2648284','N2648284','','السعودية','2026-08-05T17:00:00.000Z','2026-07-03T09:18:00.000Z','2026-08-06T20:54:07.203Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10564369.jpg','/api/media/e152ab39-0d4a-4d66-9356-bdc119c04813','/api/media/e152ab39-0d4a-4d66-9356-bdc119c04813?variant=thumbnail','ثقافي / معرض "كنوز غارقة".. رحلة معرفية تستكشف التراث البحري للبحر الأحمر',1600,1066,'valid','published','archived','valid',44,'23eac3407c143f731de5a5b4807dcab0f7a3081c95bdeb9c65a41ecd14873c72','ae8a19b4f917f4159538cb323891e4ebbe60efb51ab85300698abd1a7400c942','محدّث','2026-08-06T20:54:07.203Z','2026-10-07T20:24:27.663Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة المتاحف وهيئة التراث وبرنامج","السفر والسياحة","الاقتصاد والأسواق","جدة"]','["هيئة المتاحف وهيئة التراث وبرنامج","السفر والسياحة","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":1.5}]','Active','2026-10-07T19:45:10.813Z',200,79,0,'source_article_available','',NULL,NULL,'body:d4ba3d1ceb3297c49eda9f1dc6b81096b5fae5b30ee99cd52b1b3786433824c6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c5e2ffe8-3744-4430-b85c-00c72bb88ffb','news-c5e2ffe8-3744-4430-b85c-00c72bb88ffb','ثقافي / العمارة الحجرية التقليدية تستعيد حضورها في مهرجان الأطاولة التراثي بالباحة','ثقافي العماره الحجريه التقليديه تستعيد حضورها في مهرجان الاطاوله التراثي بالباحه','الباحة 22 صفر 1448 هـ الموافق 05 أغسطس 2026 م واس تستحضر فعاليات مهرجان الأطاولة التراثي التاسع بمنطقة الباحة جانبًا من الموروث العمراني للمنطقة؛ عبر عروض حية تحاكي أساليب بناء المنازل الحجرية القديمة، في مشهدٍ يجذب الزوار ويعرّف الأجيال الجديدة بالحرف التقليدية التي شكّلت هوية القرى الجبلية في الباحة على مدى عقود.','["ويقدّم عددٌ من الحرفيين أمام الزوار نماذج تطبيقية لطرق تشييد الجدران الحجرية باستخدام الأحجار المحلية، مستعرضين مراحل اختيار الأحجار وتهذيبها وتنسيقها ورصّها بعناية، وفق الأساليب التقليدية التي اشتهرت بها قرى المنطقة، وأسهمت في إنشاء مبانٍ تميّزت بالمتانة والانسجام مع البيئة الجبلية.","كما تتضمن الفعالية عرضًا حيًا لعمليات نحت الأحجار وتهيئتها بأدوات يدوية تقليدية، في تجربةٍ تبرز براعة البنّاء القديم، ودقة عمله التي مكّنته من تشييد المباني والأسوار دون الحاجة إلى معدات حديثة، مع الحفاظ على الطابع المعماري الفريد لمنطقة الباحة.","وأوضح عددٌ من المشاركين أن البناء الحجري التقليدي يعتمد على خبرات متوارثة في اختيار نوعية الحجر المناسب، وتشكيله بما يحقق التوازن والتماسك بين مكونات البناء، مؤكدين أن هذه الحرفة تمثل جزءًا أصيلًا من التراث العمراني في المنطقة، وتوثّق أساليب الحياة التي عاشها الأهالي قديمًا.","وقد شهد ركن البناء الحجري إقبالًا لافتًا من الزوار الذين تابعوا مراحل تنفيذ الأعمال، وتعرّفوا على الأدوات المستخدمة وتقنيات البناء التقليدية، في فعاليةٍ تسهم في تعزيز الوعي بقيمة الموروث العمراني، والمحافظة على الحرف اليدوية، وإبراز الهوية الثقافية التي تزخر بها منطقة الباحة ضمن برامج صيفها السياحي."]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2647964?type=news&uuid=N2647964','https://spa.gov.sa/ar/N2647964?type=news&uuid=N2647964','N2647964','N2647964','','السعودية','2026-08-05T08:42:00.000Z','2026-06-23T08:06:00.000Z','2026-08-06T20:54:08.645Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10562084.jpeg','/api/media/c5e2ffe8-3744-4430-b85c-00c72bb88ffb','/api/media/c5e2ffe8-3744-4430-b85c-00c72bb88ffb?variant=thumbnail','ثقافي / العمارة الحجرية التقليدية تستعيد حضورها في مهرجان الأطاولة التراثي بالباحة',1600,892,'valid','published','archived','valid',86,'737b74556bc43ff003f0f090dd9903638e8206cf8a8a8ee8962685e1ae4896df','a3551f569f7f20ec8a21d235b9fa3c8c2e459537608b91b7336f2d7c822a374b','محدّث','2026-08-06T20:54:08.645Z','2026-10-07T19:50:17.660Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","الباحة"]','["الاقتصاد والأسواق"]','classified','','[{"category":"الاقتصاد","score":3},{"category":"الصحة","score":1.5},{"category":"التقنية","score":1.5}]','Temporarily Unreachable','2026-10-07T19:50:17.660Z',NULL,75,11,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1ccc9b93-c7de-40fc-b937-47004c2159e2','news-1ccc9b93-c7de-40fc-b937-47004c2159e2','سياحة وترفيه / الرمان ينعش سياحة الطائف','سياحه وترفيه الرمان ينعش سياحه الطائف','الطائف 22 صفر 1448 هـ الموافق 05 أغسطس 2026 م واس مع بداية نضج ثمار الرمان تدخل محافظة الطائف أحد أكثر مواسمها الزراعية حيوية، حيث تتحول المزارع إلى وجهات يقصدها الأهالي والمصطافون، في مشهد تتداخل فيه بساتين الرمان الممتدة على سفوح الجبال، لتقدم تجربة تجمع الزراعة، والسياحة، والاقتصاد المحلي في آنٍ واحد.','["ولا يُنظر إلى موسم الرمان بوصفه موسمًا للحصاد فحسب، بل جزءًا من الهوية الزراعية للطائف، التي اشتهرت بتنوع محاصيلها الموسمية، إذ تتعاقب مواسم الورد، والعنب، والمشمش والبخارى والبرشومي والتوت، والحماط، والرمان، في دورة زراعية تعكس ثراء البيئة الطبيعية، وتمنح المحافظة حضورًا متجددًا على مدار العام.","وتشهد المزارع خلال الموسم حركة متواصلة منذ ساعات الصباح الأولى، مع بدء عمليات قطف الثمار وفرزها وتجهيزها للتسويق، فيما يفضل كثير من الزوار شراء الرمان مباشرة من المزارع، والتجول بين الأشجار، والتعرف على طرق الزراعة التقليدية، الأمر الذي أوجد نمطًا من السياحة الزراعية بات يحظى باهتمام متزايد من العائلات ومحبي التجارب الريفية.","وأوضح المطور الزراعي فايز السفياني، في حديثه لـ\"واس\"، أن اعتدال مناخ الطائف وارتفاعها عن سطح البحر ووفرة الأمطار الموسمية أسهمت في إنتاج ثمار رمان ذات جودة عالية، مؤكدًا أن موسم الرمان لم يعد يقتصر على تسويق المنتج، بل أصبح مناسبة يلتقي فيها المزارعون بالزوار، ويتعرف من خلالها المصطافون على تفاصيل العمل الزراعي، فيما تشارك الأسر المنتجة في عرض منتجات غذائية متنوعة يدخل الرمان في إعدادها، إلى جانب المنتجات المحلية…","وأشار إلى أن موسم الرمان يؤكد عامًا بعد عام قدرة الطائف على تحويل مواسمها الزراعية إلى تجارب سياحية متكاملة، تجمع جودة المنتج، وجمال الطبيعة، وكرم الضيافة، ليبقى الرمان أحد أبرز رموز المحافظة الزراعية، ووجهة ينتظرها الزوار مع كل موسم حصاد."]','السفر','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2648151?type=news&uuid=N2648151','https://spa.gov.sa/ar/N2648151?type=news&uuid=N2648151','N2648151','N2648151','','السعودية','2026-08-05T13:35:00.000Z','2026-07-14T01:47:00.000Z','2026-08-06T20:54:09.216Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10563416.jpg','/api/media/1ccc9b93-c7de-40fc-b937-47004c2159e2','/api/media/1ccc9b93-c7de-40fc-b937-47004c2159e2?variant=thumbnail','سياحة وترفيه / الرمان ينعش سياحة الطائف',1600,1065,'valid','published','archived','valid',49,'9448c481064edda8c9fa13247cde542d409c1da2617a8eef6e173e23ba1eb3df','cba0937603cfe7b55a3531f1116d2104d1998448bd3b5dc02de446001ca8aa18','محدّث','2026-08-06T20:54:09.216Z','2026-10-07T20:24:27.668Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","السفر والسياحة","الاقتصاد والأسواق"]','["الطقس والمناخ","السفر والسياحة","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"البيئة والمناخ","score":4.5},{"category":"المناطق","score":4},{"category":"الاقتصاد","score":3}]','Active','2026-10-07T19:44:53.668Z',200,74,0,'source_article_available','',NULL,NULL,'body:a9639f2953e9832ff682ac8ce2c6be78d0b86c85d92b8e94f805cb7c067aacc9','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('abc34bc8-e978-4eb2-8aaa-c1b9ea35efca','news-abc34bc8-e978-4eb2-8aaa-c1b9ea35efca','اقتصادي / تبوك تتصدّر إنتاج المملكة من العنب بنسبة 40% تحققها أكثر من مليون ونصف شجرة مثمرة بالمنطقة','اقتصادي تبوك تتصدر انتاج المملكه من العنب بنسبه 40 تحققها اكثر من مليون ونصف شجره مثمره بالمنطقه','تبوك 23 صفر 1448 هـ الموافق 06 أغسطس 2026 م واس تصدرت منطقة تبوك الإنتاج العام للعنب بالمملكة بنسبة تناهز الـ40% لتشكل واحدة من أبرز قصص النجاح الزراعي بأكثر من مليون ونصف شجرة عنب مثمرة بالمنطقة.','["وأوضح مدير عام فرع وزارة البيئة والمياه والزراعة بمنطقة تبوك المهندس أمجد بن عبدالله ثلاب أن تصدر المنطقة إنتاج العنب يعكس ما يمتلكه القطاع الزراعي في المنطقة من إمكانات واعدة، وما يبذله المزارعون من جهود في تطوير ممارساتهم الزراعية وتحسين كفاءة الإنتاج وجودة الثمار، مشيرًا إلى أن الوزارة تعمل على دعم المزارعين وتقديم الخدمات الإرشادية والفنية لهم، وتشجيع استخدام التقنيات الزراعية الحديثة، بما يسهم في ترشيد استهلاك…","وبين أن الأصناف المزروعة في المزارع من العنب تشمل البرايم، والسبريور، والريد جلوب، والأوتوم رويال، والمون بولز، والإيفانس، وهي أصناف عالية الجودة وتلقى رواجًا في الأسواق المحلية، مشيرًا إلى أهمية التوسع في الصناعات التحويلية المرتبطة بالمحصول، مثل إنتاج الزبيب والعصائر والدبس، بما يحقق قيمة مضافة ويوفر فرصًا استثمارية جديدة للمزارعين ورواد الأعمال.","ويحظى العنب المنتج في تبوك بإقبال المستهلكين خلال موسم الحصاد، وسط تنوع في الأصناف المزروعة وارتفاع مستوى الجودة، فيما تسهم الأسواق والمنافذ التسويقية الزراعية في التعريف بالمنتج المحلي وتعزيز حضوره أمام المستهلك، ولا تتوقف الفرص الاقتصادية للمحصول عند بيع العنب الطازج، بل تمتد إلى مجالات التعبئة والتغليف والتبريد والنقل والتصنيع الغذائي، إضافة إلى السياحة الزراعية التي تتيح للزوار التعرف على المزارع ومراحل الإنتاج…","ويعزز تصدر تبوك إنتاج العنب قدرتها على جذب الاستثمارات الزراعية والغذائية، ويدعم استمرار الجهود الرامية إلى تطوير سلاسل الإمداد والتسويق وتقليل الفاقد، بما يرفع العائد الاقتصادي للمزارعين ويعزز مساهمة المنطقة في تحقيق مستهدفات الأمن الغذائي بالمملكة."]','الاقتصاد','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2648527?type=news&uuid=N2648527','https://spa.gov.sa/ar/N2648527?type=news&uuid=N2648527','N2648527','N2648527','','السعودية','2026-08-06T06:48:00.000Z',NULL,'2026-08-06T20:54:11.337Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10566887.jpg','/api/media/abc34bc8-e978-4eb2-8aaa-c1b9ea35efca','/api/media/abc34bc8-e978-4eb2-8aaa-c1b9ea35efca?variant=thumbnail','اقتصادي / تبوك تتصدّر إنتاج المملكة من العنب بنسبة 40% تحققها أكثر من مليون ونصف شجرة مثمرة بالمنطقة',1600,1066,'valid','published','archived','valid',85,'687a512cbcf8860d445ddc3eb30031b17923de9b69fe7cb81ba134d80fa0d868','187d509df30ddf4f35454ecba70d7fd0c822db57d720a158a5bd72e99ca79498',NULL,'2026-08-06T20:54:11.337Z','2026-10-07T19:45:14.397Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البيئة والمياه والزراعة بمنطقة","السفر والسياحة","الاقتصاد والأسواق","تبوك"]','["وزارة البيئة والمياه والزراعة بمنطقة","السفر والسياحة","الاقتصاد والأسواق"]','classified','','[{"category":"الطاقة والصناعة","score":4},{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":3}]','Active','2026-10-07T19:45:14.397Z',200,79,0,'source_article_available','',NULL,NULL,'body:ace972d8b7b428ebdbfa9805d4a4757eb677232bc92456ce2a5b8b9a453ee307','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3cb12f7e-fd52-4d1d-aa19-80b1d3366318','news-3cb12f7e-fd52-4d1d-aa19-80b1d3366318','سياحة وترفيه / أودية الباحة.. مشاهد طبيعية متجددة تعزز جاذبية صيف المنطقة','سياحه وترفيه اوديه الباحه مشاهد طبيعيه متجدده تعزز جاذبيه صيف المنطقه','الباحة 23 صفر 1448 هـ الموافق 06 أغسطس 2026 م واس تُعد أودية منطقة الباحة من أبرز المقومات الطبيعية التي تضفي على المنطقة جمالًا استثنائيًا خلال موسم الصيف؛ إذ تسهم الأمطار الموسمية في جريان المياه وتجدد الغطاء النباتي على امتداد ضفافها، لترسم لوحات طبيعية تستقطب الأهالي والزوار للاستمتاع بالأجواء المعتدلة والمناظر الخلابة.','["وأسهم التنوع الجغرافي الذي تتميز به المنطقة بين مرتفعات السراة وسهول تهامة في تعدد الأودية واختلاف خصائصها؛ فتمتد مجاريها عبر الجبال والسهول، محاطة بالأشجار الكثيفة والنباتات البرية والمزارع التي تستفيد من المياه الموسمية وخصوبة التربة، مما يعزز استدامة النشاط الزراعي في العديد من المحافظات.","وتزخر منطقة الباحة بعدد من الأودية الشهيرة، يأتي في مقدمتها وادي بيدة، ووادي ثراد بمحافظة العقيق، ووادي الأحسبة بمحافظة المخواة، والتي تمتاز بتنوع تضاريسها وغناها بالغطاء النباتي، فضلًا عما تمثله من روافد بيئية وزراعية تعكس ثراء الطبيعة في المنطقة.","ومع هطول الأمطار، تشهد هذه الأودية إقبالًا متزايدًا من المتنزهين وهواة التصوير ومحبي رياضة المشي، للاستمتاع بجريان المياه والمشاهد الخضراء التي تكسو جنباتها، في صورة تجسد التنوع البيئي والجاذبية السياحية التي تتمتع بها منطقة الباحة خلال فصل الصيف.","وفي هذا السياق، تؤكد الجهات المعنية أهمية الحفاظ على نظافة الأودية وسلامة مكوناتها الطبيعية، مع ضرورة الالتزام بإرشادات السلامة وتجنب الاقتراب من مجاري السيول أثناء هطول الأمطار أو جريانها؛ حرصًا على سلامة الزوار، وضمانًا لاستدامة هذه المواقع بوصفها من أهم المقومات الطبيعية والسياحية في المنطقة."]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2648616?type=news&uuid=N2648616','https://spa.gov.sa/ar/N2648616?type=news&uuid=N2648616','N2648616','N2648616','','السعودية','2026-08-06T08:30:00.000Z','2026-06-23T08:06:00.000Z','2026-08-06T20:54:11.398Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10568040.jpeg','/api/media/3cb12f7e-fd52-4d1d-aa19-80b1d3366318','/api/media/3cb12f7e-fd52-4d1d-aa19-80b1d3366318?variant=thumbnail','سياحة وترفيه / أودية الباحة.. مشاهد طبيعية متجددة تعزز جاذبية صيف المنطقة',1600,1065,'valid','published','archived','valid',85,'d0df06d2e202a7597e9f05c093d89fba83dcfc4104c3edae9a96508719d8e8df','db9779a8405092ebf5de5efc8e8551399fb212c10deeb24bae0fdee4384ef9db','محدّث','2026-08-06T20:54:11.398Z','2026-10-07T19:50:17.667Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","السفر والسياحة","الرياضة السعودية","الاقتصاد والأسواق","الباحة"]','["الطقس والمناخ","السفر والسياحة","الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[{"category":"السفر","score":4.5},{"category":"الصحة","score":3},{"category":"البيئة والمناخ","score":3}]','Temporarily Unreachable','2026-10-07T19:50:17.667Z',NULL,76,8,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d8c7eaf4-efd9-41ea-b6a4-af5e9ee745d1','news-d8c7eaf4-efd9-41ea-b6a4-af5e9ee745d1','علوم وتقنيات / التربيع الأخير لقمر شهر صفر يُزيّن سماء المملكة','علوم وتقنيات التربيع الاخير لقمر شهر صفر يزين سماء المملكه','عرعر 23 صفر 1448 هـ الموافق 06 أغسطس 2026 م واس شهدت سماء المملكة فجر اليوم، التربيع الأخير لقمر شهر صفر لعام 1448هـ، في مشهد فلكي يُعد إحدى المراحل الرئيسة لدورة القمر الشهرية، حيث بدا نصف قرصه مضاءً، بينما غطّى الظل النصف الآخر، في ظاهرة فلكية يمكن مشاهدتها بالعين المجردة عند صفاء الأجواء.','["وأوضح عضو نادي الفضاء والفلك عدنان خليفة أن القمر في هذه المرحلة يكون قد قطع نحو ثلاثة أرباع مداره حول الأرض، ويقع في وضع هندسي يجعل نصفه المواجه للأرض مضاءً بأشعة الشمس، فيما يشرق بعد منتصف الليل ويظل مرئيًا حتى ساعات الظهيرة.","وأشار إلى أن مرحلة التربيع الأخير تُعد من المحطات الفلكية المهمة التي تسبق طور الهلال المتناقص ثم المحاق، وصولًا إلى ولادة هلال شهر ربيع الأول، مبينًا أن هذه الفترة تُعد مناسبة لرصد تفاصيل سطح القمر باستخدام المناظير والتلسكوبات؛ إذ تُبرز الحدود الفاصلة بين الضوء والظل الفوهات والجبال والسهول القمرية بصورة أكثر وضوحًا.","وأضاف أن أطوار القمر تتكرر بانتظام كل نحو 29.5 يومًا، وتشمل المحاق، والتربيع الأول، والبدر، والتربيع الأخير، وهي ظواهر فلكية تعكس الحركة المدارية للقمر حول الأرض، وتسهم في تعزيز الوعي الفلكي لدى المهتمين والراصدين، فضلًا عن أهميتها في التقويم الهجري ورصد الظواهر السماوية."]','أخبار السعودية','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2648390?type=news&uuid=N2648390','https://spa.gov.sa/ar/N2648390?type=news&uuid=N2648390','N2648390','N2648390','','السعودية','2026-08-05T21:28:00.000Z',NULL,'2026-08-06T20:54:13.126Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10565246.jpg','/api/media/d8c7eaf4-efd9-41ea-b6a4-af5e9ee745d1','/api/media/d8c7eaf4-efd9-41ea-b6a4-af5e9ee745d1?variant=thumbnail','علوم وتقنيات / التربيع الأخير لقمر شهر صفر يُزيّن سماء المملكة',1600,2400,'valid','published','archived','valid',46,'ca6cb4d620e06b9196f478c9c56e056e11a91997e7c8209a65c087cf3a209e31','528f1466d3d5353274319b35c32e451bf98899f44339d3394f3174ced50e8dc8',NULL,'2026-08-06T20:54:13.126Z','2026-10-07T19:45:00.568Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T19:45:00.568Z',200,91,0,'source_article_available','',NULL,NULL,'body:a70889b03183c43baf557cb8c83d02069137bc3be47545a5ea98cf8d1e896e2b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7c94bc04-173e-4478-ad4f-9ea90c41d826','news-7c94bc04-173e-4478-ad4f-9ea90c41d826','سياحة وترفيه / نفود الأشياخ.. أعلى قمة رملية تجسد مشهد التقاء رمال الدهناء بالنفود الكبير','سياحه وترفيه نفود الاشياخ اعلي قمه رمليه تجسد مشهد التقاء رمال الدهناء بالنفود الكبير','رفحاء 23 صفر 1448 هـ الموافق 06 أغسطس 2026 م واس تُشكّل التلال الرملية في نفود الأشياخ، الواقعة على بُعد نحو 130 كيلومترًا جنوب غرب محافظة رفحاء، أحد أبرز التكوينات الرملية في صحراء الدهناء، إذ تحتضن وفقًا لهيئة المساحة الجيولوجية أعلى قمة رملية في الدهناء بارتفاع يبلغ 779 مترًا فوق سطح البحر تقع في رملة الأشياخ، شرق بلدة الحيانية، قرب التقاء رمال الدهناء مـ','["وأوضح عضو جمعية الآثار عبدالرحمن التويجري لـ\"واس\" أن نفود الأشياخ يُعد من أبرز المواقع الرملية في شمال المملكة، إذ يتميز الموقع بتكويناته الجيومورفولوجية الفريدة التي تشكلت عبر آلاف السنين بفعل حركة الرياح.","وبيّن أن التكوينات الرملية في نفود الأشياخ تعد نقطة التقاء وتداخل بين رمال صحراء الدهناء والنفود الكبير، في مشهد طبيعي تتعاقب فيه الكثبان ذات الألوان الذهبية والحمراء، وتنتشر بينها النباتات الصحراوية التي تضفي على الموقع تنوعًا بصريًا يعكس خصائص البيئة الصحراوية في شمال المملكة.","وأشار إلى أن التلال الرملية تُظهر انحدارات وتشكيلات جيومورفولوجية متنوعة كوّنتها حركة الرياح عبر فترات زمنية طويلة، لتُشكّل كثبانًا شاهقة ومتداخلة تُعد من أبرز الملامح الطبيعية التي تستقطب هواة الرحلات البرية والتصوير الفوتوغرافي، خاصة خلال مواسم اعتدال الأجواء.","ويُعد نفود الأشياخ من المواقع الطبيعية البارزة، بما يمتلكه من مقومات جغرافية ومناظر صحراوية فريدة تُسهم في إبراز التنوع الطبيعي الذي تزخر به المملكة، وتعزز حضوره بوصفه وجهة واعدة للسياحة البيئية ورحلات الاستكشاف."]','السفر','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2648637?type=news&uuid=N2648637','https://spa.gov.sa/ar/N2648637?type=news&uuid=N2648637','N2648637','N2648637','','السعودية','2026-08-06T08:46:00.000Z',NULL,'2026-08-06T20:54:15.302Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10568210.jpeg','/api/media/7c94bc04-173e-4478-ad4f-9ea90c41d826','/api/media/7c94bc04-173e-4478-ad4f-9ea90c41d826?variant=thumbnail','سياحة وترفيه / نفود الأشياخ.. أعلى قمة رملية تجسد مشهد التقاء رمال الدهناء بالنفود الكبير',1600,900,'valid','published','archived','valid',46,'d654ea632940e892e51a6692d43bfdcc7f264a2d1d0193238c491cf26b61fde1','dba7383c0d28bfae8b4640c9a37b58778e935a5c22b35cc271f61cec91f26c96',NULL,'2026-08-06T20:54:15.303Z','2026-10-07T20:24:27.675Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الاقتصاد والأسواق"]','["السفر والسياحة","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الاقتصاد","score":1.5},{"category":"المجتمع","score":1.5}]','Temporarily Unreachable','2026-10-07T19:50:39.044Z',NULL,76,8,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3d0ef45c-fd82-4611-8202-f3a242b11671','news-3d0ef45c-fd82-4611-8202-f3a242b11671','علوم وتقنيات / اقتران الثريا بالقمر يعلن دخول "قران 23" إيذانًا باقتراب نهاية الصيف','علوم وتقنيات اقتران الثريا بالقمر يعلن دخول قران 23 ايذانا باقتراب نهايه الصيف','عرعر 24 صفر 1448 هـ الموافق 07 أغسطس 2026 م واس شهدت سماء المملكة فجر اليوم، اقتران نجوم الثريا بالقمر في ظاهرة فلكية تُعرف في الموروث الشعبي العربي بـ"قران 23"، وتُعد من العلامات الزمنية التي اعتمد عليها العرب قديمًا في معرفة المواسم والتقويم الزراعي؛ إذ تشير إلى دخول الشهر الثالث من فصل الصيف، واقتراب انكسار حدة الحرارة، تمهيدًا لظهور نجم سهيل.','["وأوضح عضو نادي الفلك محمد عناد الهزيمي أن \"قران 23\" يتزامن مع دخول منزلة الكليبين، التي تستمر خلال الأسبوعين الأولين من هذه الفترة، فيما يظهر نجم سهيل في أواخرها، مبينًا أن أهل البادية يعدّون هذا الاقتران مؤشرًا على قرب انتهاء جمرة القيظ، وبداية تراجع شدة الحر تدريجيًا، مع ارتفاع نسبة الرطوبة في المناطق الساحلية، وهي ظروف تُسهم في تهيئة الأجواء لتكوّن السحب والغيوم بإذن الله.","وأضاف أن هذه المرحلة تمتد قرابة 27 يومًا، وتحظى باهتمام المزارعين؛ لتزامنها مع نضج العنب والرطب، وبداية موسم جني ثمار النخيل.","واستشهد بالموروث الشعبي الذي يقول: \"ثاني عشر من آب يطيح العنب وينضج الأرطاب\"، في إشارة إلى وفرة المحاصيل خلال هذه الفترة، لافتًا الانتباه إلى أنها تُعد أيضًا من الأوقات المناسبة للعناية بالمزروعات والإكثار من ريّها.","وأشار الهزيمي إلى أن اقتران الثريا بالقمر يُعد من أبرز الظواهر الفلكية التي استرعت اهتمام العرب منذ القدم، إذ اعتمدوا عليه في تحديد المواسم وتقلبات الطقس، ومتابعة بدايات المراحل المناخية، ضمن منظومة دقيقة تقوم على منازل القمر وحركة النجوم، ولا يزال يحظى باهتمام المهتمين بالفلك والموروث الشعبي بوصفه علامة طبيعية تُنبئ بقرب نهاية فصل الصيف، واقتراب دخول موسم سهيل وما يصاحبه من اعتدال تدريجي في الأجواء."]','البيئة والمناخ','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2649100?type=news&uuid=N2649100','https://spa.gov.sa/ar/N2649100?type=news&uuid=N2649100','N2649100','N2649100','','السعودية','2026-08-06T22:26:00.000Z','2026-07-08T06:01:00.000Z','2026-08-07T19:54:09.754Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10571565.jpg','/api/media/3d0ef45c-fd82-4611-8202-f3a242b11671','/api/media/3d0ef45c-fd82-4611-8202-f3a242b11671?variant=thumbnail','علوم وتقنيات / اقتران الثريا بالقمر يعلن دخول "قران 23" إيذانًا باقتراب نهاية الصيف',1600,1066,'valid','published','archived','valid',46,'151aeb619672b4e394785caf019cf205668a15b087bb4b36135f8b9adfdd6165','901ac03473df7b71f6beca83fd96c1ba2a92cd8321aae490ceeb2d1c787252c8','محدّث','2026-08-07T19:54:09.754Z','2026-10-07T20:24:27.678Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","الرياضة السعودية"]','["الطقس والمناخ","الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"الصحة","score":1.5},{"category":"الرياضة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T19:35:48.924Z',200,92,0,'source_article_available','',NULL,NULL,'body:98cb8c0a7b5131e35212bd2c7ed60cb1aa75f74945de0345eacc24897d2f593e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fdfc9d88-c679-467d-ac05-f92c7ef826ad','news-fdfc9d88-c679-467d-ac05-f92c7ef826ad','عام / خطبة الجمعة من المسجد الحرام','عام خطبه الجمعه من المسجد الحرام','مكة المكرمة 24 صفر 1448 هـ الموافق 07 أغسطس 2026 م واس أوصى إمام وخطيب المسجد الحرام فضيلة الشيخ الدكتور فيصل بن جميل غزاوي، المسلمين بتقوى الله واستشعار أعظم نعمه على المسلمين، ألا وهي نعمة الأخوة في الدين.','["وقال في خطبته التي ألقاها اليوم، بالمسجد الحرام: \"إن التآخي والتلاحم بين المسلمين فريضتان شرعيتان، وقد ضرب لنا النبي -صلى الله عليه وسلم- أروع الأمثلة في بيان هذه الرابطة حين قال: \"مثل المؤمنين في توادهم وتراحمهم وتعاطفهم مثل الجسد، إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى\".","وأوضح أن التلاحم بين المسلمين ليس أمرًا كماليًا، بل هو أساس من أسس الحياة الإيمانية، وبه تدوم النعم وتدفع النقم.","وشدد فضيلته على أن يتكافل أفراد الأمة فيما بينهم، ويتعاون بعضهم مع بعض عملًا بقوله تعالى: (وَتَعَاونوا عَلَى البِرِّ والتقْوَى).","وبيّن فضيلته أن من أفضل وجوه التعاون، هو التعاون على تعليم الخير والدعوة إلى الله، وذلك بالأمر بالمعروف والنهي عن المنكر."]','المجتمع','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2649216?type=news&uuid=N2649216','https://spa.gov.sa/ar/N2649216?type=news&uuid=N2649216','N2649216','N2649216','','السعودية','2026-08-07T07:33:00.000Z','2026-06-24T04:31:00.000Z','2026-08-07T19:54:10.036Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10572103.jpeg','/api/media/fdfc9d88-c679-467d-ac05-f92c7ef826ad','/api/media/fdfc9d88-c679-467d-ac05-f92c7ef826ad?variant=thumbnail','عام / خطبة الجمعة من المسجد الحرام',1600,1066,'valid','published','archived','valid',98,'1be8f58d9233a0a0443d72d305bff9bac1c26558c1745b593644e1804c7a14c7','8b7e9f524daad412d9339d4a93edeaf93103ca2ad4cf8af0231a907ff2a59534','محدّث','2026-08-07T19:54:10.036Z','2026-10-07T19:35:52.037Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','classified','','[{"category":"التعليم","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T19:35:52.037Z',200,94,0,'source_article_available','',NULL,NULL,'body:4b5e3e9c1c05c95c6485b7459984c9b6bcab94d2c6c91913d5163a9dc5e299c6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('aea4f629-d60f-449b-a33b-346e5651c9ff','news-aea4f629-d60f-449b-a33b-346e5651c9ff','سياسي / البيان المشترك لقمة مكة المكرمة للدفاع المشترك بين المملكة وتركيا وباكستان','سياسي البيان المشترك لقمه مكه المكرمه للدفاع المشترك بين المملكه وتركيا وباكستان','مكة المكرمة 24 صفر 1448هـ الموافق 7 أغسطس 2026م واس صدر اليوم بيان مشترك لقمة مكة المكرمة للدفاع المشترك بين المملكة العربية السعودية والجمهورية التركية وجمهورية باكستان الإسلامية، فيما يلي نصه: تلبية لدعوة كريمة من خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، قام كل من فخامة رئيس الجمهورية التركية السيد/ رجب طيب أردوغان، ودولة رئيس وزراء جمهورية','["وقد استقبل صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء، فخامة رئيس الجمهورية التركية، ودولة رئيس وزراء جمهورية باكستان الإسلامية، في الديوان الملكي بقصر الصفا في مكة المكرمة.","وعقدت قمة مكة المكرمة للدفاع المشترك، واستُعرضت خلالها العلاقات المتميزة بين كل من المملكة العربية السعودية وجمهورية باكستان الإسلامية والجمهورية التركية، وعدد من القضايا ذات الاهتمام المشترك.","وانطلاقًا من الروابط التاريخية الراسخة، بين الدول الثلاث، وبناءً على روابط الأخوة والتضامن الإسلامي التي تجمعها، واستنادًا إلى المصالح الإستراتيجية المشتركة والتعاون الدفاعي الوثيق، وقّع كُل من صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء -حفظه الله-، وفخامة رئيس الجمهورية التركية السيد/ رجب طيب أردوغان، ودولة رئيس وزراء جمهورية باكستان الإسلامية محمد شهباز شريف، \"اتفاقية…","وتهدف الاتفاقية إلى تعزيز الردع المشترك ضد أي اعتداء، وتنص على أن أي هجوم مسلح على أي من الدول الثلاث هو هجوم على الجميع، كما تُعنى الاتفاقية بتطوير كافة أوجه التعاون الدفاعي بينهم."]','أخبار السعودية','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2649223?type=news&uuid=N2649223','https://spa.gov.sa/ar/N2649223?type=news&uuid=N2649223','N2649223','N2649223','','السعودية','2026-08-07T07:46:00.000Z',NULL,'2026-08-07T19:54:11.960Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10573062.jpg','/api/media/aea4f629-d60f-449b-a33b-346e5651c9ff','/api/media/aea4f629-d60f-449b-a33b-346e5651c9ff?variant=thumbnail','سياسي / البيان المشترك لقمة مكة المكرمة للدفاع المشترك بين المملكة وتركيا وباكستان',1600,1107,'valid','published','archived','valid',99,'31dca6637563670519fee32e8f02098b1f35c342ee47a03855a00cbc25d479b2','201f16452012774945c0f5827e89fe6ab3eb9a57ca61cf9de587725bb33bf6f2',NULL,'2026-08-07T19:54:11.960Z','2026-10-07T19:36:09.065Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","رئيس مجلس الوزراء فخامة رئيس","مجلس الوزراء فخامة رئيس الجمهورية","مكة","تركيا"]','["ولي العهد رئيس مجلس الوزراء","رئيس مجلس الوزراء فخامة رئيس","مجلس الوزراء فخامة رئيس الجمهورية"]','classified','','[{"category":"المناطق","score":3},{"category":"العالم","score":1.5},{"category":"السياسة","score":0}]','Active','2026-10-07T19:36:09.065Z',200,94,0,'source_article_available','',NULL,NULL,'body:1484fddd61c2101b1bd71ffe6f68f8211d66defcd219bef73ddc712fb0b851a1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c99f553f-c6e9-4135-a9cb-b50c00ba8e37','news-c99f553f-c6e9-4135-a9cb-b50c00ba8e37','سياحة وترفيه / كيف تشكّل جبل أبو الهول بمنطقة حائل؟','سياحه وترفيه كيف تشكل جبل ابو الهول بمنطقه حائل','حائل 24 صفر 1448 هـ الموافق 07 أغسطس 2026 م واس تشكّل جبل "أبو الهول" الواقع في قرية أبا الحيران جنوب غرب منطقة حائل، على بُعد نحو 120 كيلومترًا، ضمن سلسلة جبال أجا، نتيجة عوامل التعرية والتجوية التي تعرض لها عبر آلاف السنين؛ ما أوجد تكوينًا صخريًا فريدًا يشبه رأس الإنسان، وأكسبه هذه التسمية، وجعله أحد أبرز المعالم الطبيعية والسياحية في المنطقة.','["ووفق الباحث في التاريخ والفلك القديم مشاري النشمي، أن الجبل يتميز بتنوع جيولوجي لافت، إذ تنتشر حوله تشكيلات صخرية متعددة الأشكال والأحجام، تشكلت بفعل تداخل عوامل التجوية الفيزيائية والكيميائية مع تأثيرات الأمطار والرطوبة عبر فترات زمنية طويلة؛ ما أوجد مشاهد طبيعية فريدة تتباين ملامحها باختلاف زوايا الرؤية والمسافات.","ويُعد الموقع من البيئات الغنية بالظواهر الجيولوجية المتنوعة، الأمر الذي يعزز قيمته الطبيعية، ويجعله مقصدًا للمهتمين بالتكوينات الصخرية والزوار القادمين إلى منطقة حائل."]','السفر','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2649259?type=news&uuid=N2649259','https://spa.gov.sa/ar/N2649259?type=news&uuid=N2649259','N2649259','N2649259','','السعودية','2026-08-07T08:46:00.000Z','2026-06-23T06:05:00.000Z','2026-08-07T19:54:12.840Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10572310.jpg','/api/media/c99f553f-c6e9-4135-a9cb-b50c00ba8e37','/api/media/c99f553f-c6e9-4135-a9cb-b50c00ba8e37?variant=thumbnail','سياحة وترفيه / كيف تشكّل جبل أبو الهول بمنطقة حائل؟',1600,1066,'valid','published','archived','valid',52,'cbf352529c18a71fd463cd7fec41c59ff5272cdefd86ddab626e147d24c4ef39','823d9a9f3b84d9eb81542692623c69a456d8895c7fe81f341014ad9801fdf2fb',NULL,'2026-08-07T19:54:12.840Z','2026-10-07T20:24:27.684Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","السفر والسياحة"]','["الطقس والمناخ","السفر والسياحة"]','manual_approved','below_category_threshold','[{"category":"الصحة","score":1.5},{"category":"البيئة والمناخ","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T19:36:11.629Z',200,97,0,'source_article_available','',NULL,NULL,'body:4a1c87172d5d0ac5883ffbcd706fdafac401e7154a9a89d39602ce4acb408871','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d4f0a007-55b6-41e7-b3e0-585992aa238f','news-d4f0a007-55b6-41e7-b3e0-585992aa238f','سياسي / سمو ولي العهد يلتقي رئيس وزراء جمهورية باكستان الإسلامية','سياسي سمو ولي العهد يلتقي رئيس وزراء جمهوريه باكستان الاسلاميه','مكة المكرمة 24 صفر 1448 هـ الموافق 07 أغسطس 2026 م واس التقى صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء، في مكة المكرمة اليوم، دولة السيد محمد شهباز شريف رئيس الوزراء في جمهورية باكستان الإسلامية.','["وجرى خلال اللقاء استعراض العلاقات الثنائية بين البلدين الشقيقين، ومجالات التعاون والسبل الكفيلة بتطويره في شتى المجالات، بالإضافة إلى بحث مستجدات الأحداث الإقليمية، والجهود المبذولة تجاهها.","حضر اللقاء، صاحب السمو الملكي الأمير عبدالله بن بندر بن عبدالعزيز وزير الحرس الوطني، وصاحب السمو الملكي الأمير خالد بن سلمان بن عبدالعزيز وزير الدفاع، وصاحب السمو الأمير فيصل بن فرحان بن عبدالله وزير الخارجية، ومعالي وزير الدولة عضو مجلس الوزراء مستشار الأمن الوطني الدكتور مساعد بن محمد العيبان، ومعالي وزير البيئة والمياه والزراعة المهندس عبدالرحمن بن عبدالمحسن الفضلي (الوزير المرافق)، ومعالي سكرتير سمو ولي العهد…"]','السياسة','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2649312?type=news&uuid=N2649312','https://spa.gov.sa/ar/N2649312?type=news&uuid=N2649312','N2649312','N2649312','','السعودية','2026-08-07T10:50:00.000Z','2026-06-23T05:57:00.000Z','2026-08-07T19:54:14.193Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10572684.jpg','/api/media/d4f0a007-55b6-41e7-b3e0-585992aa238f','/api/media/d4f0a007-55b6-41e7-b3e0-585992aa238f?variant=thumbnail','سياسي / سمو ولي العهد يلتقي رئيس وزراء جمهورية باكستان الإسلامية',1600,1076,'valid','published','archived','valid',99,'db9aa541345e1ccdbcfffe2a500c9674e4e3c2e7a507fbffa3f29afeef5d2f1b','dc67d6bfb8f6fc590abacadee737fcbdfe2bf6de5420123a0f17358afcfd4ae2',NULL,'2026-08-07T19:54:14.193Z','2026-10-07T20:24:27.686Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد يلتقي رئيس وزراء","وزير الحرس الوطني وصاحب السمو","مجلس الوزراء مستشار الأمن الوطني","رئيس وزراء جمهورية باكستان الإسلامية"]','["ولي العهد يلتقي رئيس وزراء","وزير الحرس الوطني وصاحب السمو","مجلس الوزراء مستشار الأمن الوطني","رئيس وزراء جمهورية باكستان الإسلامية"]','classified','','[{"category":"البيئة والمناخ","score":1.5},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T19:35:50.372Z',200,92,0,'source_article_available','',NULL,NULL,'body:57822774d9e7bef50a414131416b1834ce522057915b3081b37b3887cbb75b00','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('94b28b4b-2b94-4887-84c0-74d426118638','news-94b28b4b-2b94-4887-84c0-74d426118638','سياسي / سمو ولي العهد يلتقي رئيس الجمهورية التركية','سياسي سمو ولي العهد يلتقي رئيس الجمهوريه التركيه','مكة المكرمة 24 صفر 1448 هـ الموافق 07 أغسطس 2026 م واس التقى صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء، في مكة المكرمة اليوم، فخامة الرئيس رجب طيب أردوغان رئيس الجمهورية التركية.','["وجرى خلال اللقاء بحث أوجه العلاقات السعودية التركية، والسبل الكفيلة بتعزيزها وتطويرها في مختلف المجالات، بالإضافة إلى استعراض مستجدات الأوضاع في المنطقة.","حضر اللقاء، صاحب السمو الملكي الأمير عبدالله بن بندر بن عبدالعزيز وزير الحرس الوطني، وصاحب السمو الملكي الأمير خالد بن سلمان بن عبدالعزيز وزير الدفاع، وصاحب السمو الأمير فيصل بن فرحان بن عبدالله وزير الخارجية، ومعالي وزير الدولة عضو مجلس الوزراء مستشار الأمن الوطني الدكتور مساعد بن محمد العيبان، ومعالي وزير الدولة عضو مجلس الوزراء لشؤون مجلس الشورى الدكتور عصام بن سعد بن سعيد (الوزير المرافق)، ومعالي سكرتير سمو ولي…"]','أخبار السعودية','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2649315?type=news&uuid=N2649315','https://spa.gov.sa/ar/N2649315?type=news&uuid=N2649315','N2649315','N2649315','','السعودية','2026-08-07T10:53:00.000Z','2026-06-23T05:57:00.000Z','2026-08-07T19:54:16.252Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10572863.jpg','/api/media/94b28b4b-2b94-4887-84c0-74d426118638','/api/media/94b28b4b-2b94-4887-84c0-74d426118638?variant=thumbnail','سياسي / سمو ولي العهد يلتقي رئيس الجمهورية التركية',1600,1164,'valid','published','archived','valid',99,'0d1801c34b3502b1998d3c25b05bfd0d105fb1df25299f249fd25d2f0ff55676','b0ef536bab5fbb1c6fcb0062c8387f8c4741ea651b3e86c569fdb503a7f4e68f',NULL,'2026-08-07T19:54:16.252Z','2026-10-07T19:35:50.509Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الحرس الوطني وصاحب السمو","ولي العهد يلتقي رئيس الجمهورية","مجلس الوزراء مستشار الأمن الوطني","رئيس الجمهورية التركية وجرى خلال"]','["وزير الحرس الوطني وصاحب السمو","ولي العهد يلتقي رئيس الجمهورية","مجلس الوزراء مستشار الأمن الوطني","رئيس الجمهورية التركية وجرى خلال"]','classified','','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T19:35:50.509Z',200,93,0,'source_article_available','',NULL,NULL,'body:bfeeca3173efa4d481fb0b9f9fb30d41291053e9c108e33ec3894c39f2245708','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a50c9844-7624-4b5b-a797-ce2d6561b1fd','news-a50c9844-7624-4b5b-a797-ce2d6561b1fd','الأردن يدين اعتداء ميليشيا الحوثي على نجران ويصفه بالانتهاك السافر','الاردن يدين اعتداء ميليشيا الحوثي علي نجران ويصفه بالانتهاك السافر','أدانت المملكة الأردنية الهاشمية اليوم الاعتداء الذي نفّذته ميليشيا الحوثي واستهدف الأعيان المدنية في منطقة نجران باستخدام المقاذيف العشوائية، وأدّى إلى إصابة عددٍ من المدنيّين؛ واعتباره انتهاكًا سافرًا لسيادة المملكة العربية السعودية، وتهديدًا لأمنها واستقرارها وسلامة أراضيها، وخرقًا صارخًا للقانون الدولي وميثاق الأمم المتحدة.','["وأكّدت وزارة الخارجية الاردنية في بيانٍ، تضامنَ الأردن المطلق مع المملكة، ووقوفَها معها في كلّ ما تتخذه من خطوات لحماية سيادتها وأمنها وسلامة مواطنيها والمُقيمين فيها."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/mzmly5v','https://sabq.org/article/mzmly5v','','https://sabq.org/article/mzmly5v','صحيفة سبق','السعودية','2026-08-07T05:06:00.000Z','2026-08-07T08:08:00.000Z','2026-08-07T20:06:37.988Z','','','/api/media/fallback/%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1%20%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9','الأردن يدين اعتداء ميليشيا الحوثي على نجران ويصفه بالانتهاك السافر',NULL,NULL,'fetch failed','review','archived','valid',99,'a7365e628401e189676fd6b5de959fd67c8ecf993f47353e019a5a3e8de8fc7f','1c9513782e737c5addc4a8937a88ec02c628eb03b94f29c7d3445ad6488c7768','محدّث','2026-08-07T20:06:37.988Z','2026-10-07T19:34:57.234Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية","وزارة الخارجية الاردنية في بيان","نجران","على نجران ويصفه","الحوثي على نجران","الأردن يدين اعتداء","ميليشيا الحوثي على","يدين اعتداء ميليشيا"]','["أخبار السعودية","وزارة الخارجية الاردنية في بيان","على نجران ويصفه","الحوثي على نجران","الأردن يدين اعتداء","ميليشيا الحوثي على"]','needs_review','below_category_threshold','[{"category":"السياسة","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T19:34:57.234Z',200,84,0,'source_article_available','',NULL,NULL,'body:9e28cfef0e4bbf433baffde126c86d13d216df4e7fe28d7b37760eafb2ac0ff9','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f27a1889-802d-4def-b8a6-5b38686b24ea','news-f27a1889-802d-4def-b8a6-5b38686b24ea','وزير الخزانة الأمريكي:  سنلاحق شبكات إيران المالية.. بالدولار أو الريال أو العملات المشفرة','وزير الخزانه الامريكي سنلاحق شبكات ايران الماليه بالدولار او الريال او العملات المشفره','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية أعلنت وزارة الخزانة الأمريكية ، عبر مكتب مراقبة الأصول الأجنبية (OFAC)، اتخاذ إجراءات ضد منصات لتداول الأصول الرقمية وشبكات شركات تقول إنها مرتبطة بعمليات غسل أموال لصالح النظام الإيراني والحرس الثوري الإيراني، في إطار حملة واشنطن لتجفيف مص','["أعلنت وزارة الخزانة الأمريكية ، عبر مكتب مراقبة الأصول الأجنبية (OFAC)، اتخاذ إجراءات ضد منصات لتداول الأصول الرقمية وشبكات شركات تقول إنها مرتبطة بعمليات غسل أموال لصالح النظام الإيراني والحرس الثوري الإيراني، في إطار حملة واشنطن لتجفيف مصادر التمويل التي تستخدمها طهران للالتفاف على العقوبات.","وقالت وزارة الخزانة الأمريكية إن الإجراءات تستهدف منصتي أصول رقمية رئيسيتين تستخدمهما جهات إيرانية، إلى جانب مسؤول شبكة من الشركات الواجهة التي تعمل عبر عدة دول وتتهمها واشنطن بتسهيل أنشطة مرتبطة بالعملات المشفرة والتهرب من العقوبات.","اتهامات أمريكية باستخدام العملات الرقمية للالتفاف على العقوبات"]','السياسة','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/atkuuewn6','https://ajel.sa/international/atkuuewn6','https://ajel.sa/international/atkuuewn6','https://ajel.sa/international/atkuuewn6','فريق التحرير','السعودية','2026-08-07T13:50:00.000Z','Wed, 07 Oct 2026 19:35:39 GMT','2026-08-08T02:12:37.830Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%88%D8%B2%D9%8A%D8%B1-%D8%A7%D9%84%D8%AE%D8%B2%D8%A7%D9%86%D8%A9-%D8%A7%D9%84%D8%A3%D9%85%D8%B1%D9%8A%D9%83%D9%8A-%D8%B3%D9%83%D9%88%D8%AA-%D8%A8%D9%8A%D8%B3%D9%86%D8%AA-lDwkE8Mq.jpg','/api/media/f27a1889-802d-4def-b8a6-5b38686b24ea','/api/media/f27a1889-802d-4def-b8a6-5b38686b24ea?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',99,'6bff067299ab14ee3289712d0d9ba4af3affc1a9bac21d10351fbfa3186177cb','4165c7ce61c969ed07472216e9bb1b26b7dceccb97382ec93872379bc9163176','محدّث','2026-08-08T02:12:37.830Z','2026-10-07T20:24:27.690Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","وزارة الخزانة الأمريكية عبر مكتب","وزير الخزانة الأمريكي سنلاحق شبكات","التقنية والتحول الرقمي","إيران"]','["وزارة الخزانة الأمريكية عبر مكتب","وزير الخزانة الأمريكي سنلاحق شبكات","التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"السياسة","score":1.5},{"category":"التقنية","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T19:35:41.186Z',200,84,0,'source_content_changed','',NULL,NULL,'body:881e28e236fe5c13c02218c88da0ca4eea357fc6f7d7fba9e6506e2e9bf06b16','Wed, 07 Oct 2026 19:35:39 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e2bdfd21-27cd-4e88-aa36-ea7f5575ebb1','news-e2bdfd21-27cd-4e88-aa36-ea7f5575ebb1','بطولة البلوت تجذب الشباب في مهرجان صيف صوير 2026','بطوله البلوت تجذب الشباب في مهرجان صيف صوير 2026','استقطبت بطولة البلوت، إحدى أبرز فعاليات مهرجان "صيف صوير 2026" المقام في منتزه صوير الجنوبي، أعدادًا كبيرة من الشباب الذين خاضوا منافسات حماسية وسط حضور وتفاعل من الأهالي والزوار.','["وتأتي البطولة ضمن برنامج المهرجان المتنوع الذي يشمل فعاليات ترفيهية واجتماعية تلبي اهتمامات مختلف فئات المجتمع، وتسهم في إيجاد بيئة ترفيهية جاذبة وتعزيز تفاعل الأهالي والزوار.","وانطلقت منافسات البلوت مع بداية المهرجان بمشاركة فرق ثنائية من الشباب. وأوضح المشاركون أن البطولة تلبي تطلعاتهم، وعبّروا عن تقديرهم لجهود بلدية صوير في تخصيص فعاليات رياضية للشباب.","من جهته، أوضح رئيس بلدية محافظة صوير المهندس سميحان الشمري أن اللجنة المنظمة رصدت جوائز مالية للفائزين بالمراكز الثلاثة الأولى، حيث يحصل الفائز بالمركز الأول على 3,000 ريال، والثاني على 2,000 ريال، والثالث على 1,000 ريال."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/entertainment/etpxyynd1','https://ajel.sa/entertainment/etpxyynd1','https://ajel.sa/entertainment/etpxyynd1','https://ajel.sa/entertainment/etpxyynd1','فريق التحرير','السعودية','2026-08-07T13:55:00.000Z','Wed, 07 Oct 2026 19:35:36 GMT','2026-08-08T02:12:39.380Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-08/source-GhgLX7dj.jpg','/api/media/e2bdfd21-27cd-4e88-aa36-ea7f5575ebb1','/api/media/e2bdfd21-27cd-4e88-aa36-ea7f5575ebb1?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',89,'f8a6c887dcd0a97173be53607afdfea474b50ea4b51dac4a36a95f3f9bd3074e','a512a5170ac3e75c371ca82be8cc9f637abc36de83e877d5a2b134a396310744','محدّث','2026-08-08T02:12:39.380Z','2026-10-07T19:35:37.610Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس بلدية محافظة صوير المهندس","الرياضة السعودية"]','["رئيس بلدية محافظة صوير المهندس","الرياضة السعودية"]','classified','','[{"category":"الرياضة","score":3},{"category":"الاقتصاد","score":1.5},{"category":"المجتمع","score":1.5}]','Updated','2026-10-07T19:35:37.610Z',200,81,0,'source_content_changed','',NULL,NULL,'body:f8d85480bc41ee77d7dde0828cd66fd425913898b3a83d717503b6c7f3cab69f','Wed, 07 Oct 2026 19:35:36 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0f55eef7-94c6-4e40-bfa9-02c94819e79d','news-0f55eef7-94c6-4e40-bfa9-02c94819e79d','معرض كنوز غارقة يستعرض مكتشفات مسجد عثمان بن عفان في جدة التاريخية','معرض كنوز غارقه يستعرض مكتشفات مسجد عثمان بن عفان في جده التاريخيه','ويضم المعرض قطعًا أثرية اكتُشفت خلال أعمال التنقيب في مسجد الخليفة عثمان بن عفان ، أحد أقدم المعالم الإسلامية في جدة التاريخية، وتعود إلى الفترة الممتدة بين القرنين السابع عشر والتاسع عشر الميلاديين، ما يعكس استمرارية النشاط التجاري والحضاري في المدينة خلال تلك الحقبة.','["يستعرض معرض \"كنوز غارقة\" المقام في متحف البحر الأحمر ب جدة التاريخية مجموعة من المكتشفات الأثرية التي توثق مكانة مدينة جدة كميناء رئيسي على البحر الأحمر وبوابة للحجاج إلى مكة المكرمة، ومركز للتبادل التجاري والثقافي بين الجزيرة العربية وأفريقيا وآسيا.","ومن بين المعروضات مصباح زيتي يعود إلى عام 1880م من جنوب شبه الجزيرة العربية، وقطع خزفية مستوردة من الصين تعود إلى القرنين السابع عشر والتاسع عشر الميلاديين، في دلالة على اتساع شبكة العلاقات التجارية التي ربطت ميناء جدة بموانئ الشرق الأقصى ودور البحر الأحمر في انتقال السلع والثقافات بين القارات.","تكشف المقتنيات الأثرية، بتنوعها وأصولها الجغرافية، عن ازدهار حركة التجارة البحرية في جدة، وتؤكد ما أثبتته الدراسات من أن مسجد عثمان بن عفان، الذي تعود جذوره إلى القرن الأول الهجري، ظل شاهدًا على تعاقب الحضارات لأكثر من ثلاثة عشر قرنًا."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/tourism/a85oyjjwu','https://ajel.sa/tourism/a85oyjjwu','https://ajel.sa/tourism/a85oyjjwu','https://ajel.sa/tourism/a85oyjjwu','فريق التحرير','السعودية','2026-08-07T13:56:00.000Z','Wed, 07 Oct 2026 19:35:35 GMT','2026-08-08T02:12:40.708Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-08/source-4hXWfDOl.jpg','/api/media/0f55eef7-94c6-4e40-bfa9-02c94819e79d','/api/media/0f55eef7-94c6-4e40-bfa9-02c94819e79d?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',50,'05bd698c5f4095fdbf5f37c2ae8a802205ffe41f1ade5c0c395c10b6c6765157','5cbb2ea38830023ade83d524bebfa4ede9c6b9ddf4b66cf8697a66065301ca95','محدّث','2026-08-08T02:12:40.708Z','2026-10-07T20:24:27.694Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","مكة","جدة","الصين"]','["الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"العالم","score":3},{"category":"الاقتصاد","score":1.5}]','Updated','2026-10-07T19:35:37.473Z',200,84,0,'source_content_changed','',NULL,NULL,'body:02a9075f0a9377443369aa5f9f81ee4addf68d778e907c518deb4607b1283885','Wed, 07 Oct 2026 19:35:35 GMT');
