INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('40ad25c9-a3d6-4b93-91e8-6fbb38835516','news-40ad25c9-a3d6-4b93-91e8-6fbb38835516','قاهر مرموش قريب من مزاملة صلاح في طرابزون','قاهر مرموش قريب من مزامله صلاح في طرابزون','بات الأرجنتيني لياندرو باريديس، لاعب وسط بوكا جونيورز، قريبًا من الانتقال إلى الدوري التركي، بعدما دخل نادي طرابزون سبور في مفاوضات أولية للحصول على خدماته، في صفقة قد تجمعه بالمصري محمد صلاح، في حال إتمام انتقال النجم الأرجنتيني إلى الفريق.','["وذكر موقع \"هابر61\" التركي أن طرابزون سبور أجرى أول تحرك رسمي للاستفسار عن شروط التعاقد مع باريديس، بناءً على رغبة المدير الفني فاتح تيكي، مشيرًا إلى أن اللاعب بات أكثر انفتاحًا على فكرة الانتقال إلى تركيا مقارنة بالفترات السابقة.","وأوضح المصدر أن مطالب باريديس المالية تتراوح بين 6 و7 ملايين يورو سنويًا، بينما يطلب بوكا جونيورز نحو 10 ملايين يورو للموافقة على رحيل اللاعب، الذي يمتد عقده مع النادي الأرجنتيني حتى ديسمبر 2028.","ويملك باريديس، البالغ من العمر 32 عامًا، خلفية خاصة مع الكرة المصرية، بعدما لعب دورًا حاسمًا في إقصاء منتخب مصر من كأس العالم 2026، خلال مواجهة المنتخبين في دور الـ16.","ففي اللحظات الأخيرة من المباراة، ومع تعادل مصر والأرجنتين بنتيجة 2-2، انطلق عمر مرموش في هجمة مرتدة سريعة، وحاول إرسال تمريرة إلى محمود حسن تريزيجيه الذي كان في طريقه للانفراد بالحارس إيميليانو مارتينيز، لكن باريديس قرأ التمريرة في اللحظة الأخيرة وتدخل لقطع الكرة."]','الرياضة','العالم','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://www.kooora.com/%D9%83%D8%B1%D8%A9-%D9%82%D8%AF%D9%85/%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D9%82%D8%A7%D9%87%D8%B1-%D9%85%D8%B1%D9%85%D9%88%D8%B4-%D9%82%D8%B1%D9%8A%D8%A8-%D9%85%D9%86-%D9%85%D8%B2%D8%A7%D9%85%D9%84%D8%A9-%D8%B5%D9%84%D8%A7%D8%AD-%D9%81%D9%8A-%D8%B7%D8%B1%D8%A7%D8%A8%D8%B2%D9%88%D9%86/bltd0de84c5d3595a92','https://www.kooora.com/%D9%83%D8%B1%D8%A9-%D9%82%D8%AF%D9%85/%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D9%82%D8%A7%D9%87%D8%B1-%D9%85%D8%B1%D9%85%D9%88%D8%B4-%D9%82%D8%B1%D9%8A%D8%A8-%D9%85%D9%86-%D9%85%D8%B2%D8%A7%D9%85%D9%84%D8%A9-%D8%B5%D9%84%D8%A7%D8%AD-%D9%81%D9%8A-%D8%B7%D8%B1%D8%A7%D8%A8%D8%B2%D9%88%D9%86/bltd0de84c5d3595a92','','','','السعودية','2026-08-10T06:36:00.000Z','Wed, 07 Oct 2026 19:07:00 GMT','2026-08-10T14:27:51.143Z','https://assets.kooora.com/images/v3/getty-2285140012/crop/MM5DIMZUG45DENBUGU5G433XMU5DAORSGI3A====/GettyImages-2285140012.jpg','/api/media/40ad25c9-a3d6-4b93-91e8-6fbb38835516','/api/media/40ad25c9-a3d6-4b93-91e8-6fbb38835516?variant=thumbnail','قاهر مرموش قريب من مزاملة صلاح في طرابزون',4347,2445,'valid','published','archived','valid',95,'e028a84d3a2a90dfce1c5987fb6fdcfcc91b722c25a356992a20142801f5a748','6e86e0c93f5e3c6c36aaf73f5edd12f6ec6670c48f47b11d2867dddfe5ca12ec',NULL,'2026-08-10T14:27:51.143Z','2026-10-07T19:07:03.459Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["العالم","الرياضة السعودية","تركيا"]','["الرياضة السعودية"]','manual_approved','','[]','Updated','2026-10-07T19:07:03.459Z',200,75,0,'source_content_changed','',NULL,NULL,'"1793nhxhylz4g2e"','Wed, 07 Oct 2026 19:07:00 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('44f00c53-bcd2-44b6-b79b-5ff0c6139948','news-44f00c53-bcd2-44b6-b79b-5ff0c6139948','صندوق تنمية الموارد البشرية يضيف 12 شهادة مهنية لتطوير الكوادر الوطنية في القطاع الصحي','صندوق تنميه الموارد البشريه يضيف 12 شهاده مهنيه لتطوير الكوادر الوطنيه في القطاع الصحي','أضاف صندوق تنمية الموارد البشرية 12 شهادة مهنية احترافية في المجال الصحي إلى قائمة الشهادات المعتمدة ضمن منتج الشهادات المهنية الاحترافية، لترتفع إلى 417 شهادة في مختلف القطاعات الحيوية، سعياً لرفع كفاءة الكوادر الوطنية وتزويدها بأحدث المهارات المعرفية والعملية.','["وتأتي هذه الإضافة استجابةً لمتطلبات سوق العمل في القطاع الصحي، وتمكيناً للكفاءات الوطنية من مواكبة التطورات والتقنيات الحديثة في المجالات السريرية والعلاجية والإدارية، بما ينسجم مع مستهدفات رؤية 2030 في تعزيز مشاركة الكفاءات الوطنية في القطاعات الواعدة.","وتتنوع الشهادات المضافة بين تخصصات حيوية تشمل: اضطرابات طيف التوحد والاضطرابات النمائية المماثلة لأخصائي النطق والتخاطب، والبرنامج المهني المتخصص في جودة الرعاية الصحية، وبرنامج التميز في الرعاية العاجلة لتدريب أطباء الرعاية الأولية، والبرنامج المهني المتخصص لحساب الكربوهيدرات لمرضى السكري، وبرنامج سلامة المرضى، وبرنامج تشغيل المحاكاة في الرعاية الصحية، والبرنامج المهني المتخصص في مسعف أطفال، والبرنامج المهني…","كما شملت الشهادات المضافة في مجال طب الأسنان: شهادة الكفاءة المهنية في تلبيس وجسور الأسنان، وشهادة الكفاءة المهنية في علاج عصب وجذور أضراس الأسنان، والتدريب السريري في طب الأسنان العام المتقدم.","ويعكس هذا التوسع جهود الصندوق في تحفيز المواطنين والمواطنات على التطوير المهني والارتقاء بمهاراتهم، وزيادة إنتاجية سوق العمل وتلبية احتياجاته المتغيرة، والوصول إلى المعايير الدولية في الكفاءات المهنية، وخلق فرص وظيفية نوعية عبر التخصص الدقيق والإحلال في القطاعات الواعدة."]','الوظائف وسوق العمل','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/yp4031d','https://sabq.org/article/yp4031d','','https://sabq.org/article/yp4031d','صحيفة سبق','السعودية','2026-08-10T02:45:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T14:27:59.439Z','https://media.sabq.org/news/2026/08/c83ac843-5e31-420b-b803-576f61ab501d/w1600.webp','/api/media/44f00c53-bcd2-44b6-b79b-5ff0c6139948','/api/media/44f00c53-bcd2-44b6-b79b-5ff0c6139948?variant=thumbnail','صندوق تنمية الموارد البشرية يضيف 12 شهادة مهنية لتطوير الكوادر الوطنية في القطاع الصحي',1600,2844,'valid','published','archived','valid',99,'d70e85a72a3251162c3f8fcf514c7e55e7fc282623951d29ad66cf47cd464cb3','7f548bd3ed46d597f98c89723b74811f553edb8e41609fca5bbae7da6eb9ec6f',NULL,'2026-08-10T14:27:59.439Z','2026-10-07T19:06:48.488Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","التعليم والتدريب"]','["الصحة العامة","التعليم والتدريب"]','classified','','[{"category":"المجتمع","score":4.5},{"category":"الصحة","score":4.5},{"category":"أخبار السعودية","score":4}]','Active','2026-10-07T19:06:48.488Z',200,73,0,'source_article_available','',NULL,NULL,'body:312cc67ffe30b893a392c0780b5eb9376598c7bb6a83cb4662bb6f076f93c900','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('87b6ed1e-1efd-4ca5-9efc-3b0eae920ca6','news-87b6ed1e-1efd-4ca5-9efc-3b0eae920ca6','القبض على مواطنين بتبوك لترويج الحشيش والإمفيتامين وأقراص طبية','القبض علي مواطنين بتبوك لترويج الحشيش والامفيتامين واقراص طبيه','ألقت المديرية العامة لمكافحة المخدرات القبض على مواطنين بمنطقة تبوك؛ لترويجهما الحشيش والإمفيتامين المخدرين وأقراصًا خاضعة لتنظيم التداول الطبي.','["وجرى إيقافهما واتخاذ الإجراءات النظامية بحقهما، وإحالتهما إلى النيابة العامة.","وأهابت المديرية العامة لمكافحة المخدرات بالإبلاغ عن أي نشاطات مرتبطة بتهريب أو ترويج المخدرات، عبر الرقم (995) أو البريد الإلكتروني 995@gdnc.gov.sa ، مؤكدةً أن جميع البلاغات تُعامل بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ss8obk6','https://sabq.org/article/ss8obk6','','https://sabq.org/article/ss8obk6','صحيفة سبق','السعودية','2026-08-10T02:35:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T14:27:59.913Z','https://media.sabq.org/news/2026/08/4c678266-ac5b-473f-9173-e040b047e2ba/w1063.webp','/api/media/87b6ed1e-1efd-4ca5-9efc-3b0eae920ca6','/api/media/87b6ed1e-1efd-4ca5-9efc-3b0eae920ca6?variant=thumbnail','القبض على مواطنين بتبوك لترويج الحشيش والإمفيتامين وأقراص طبية',1063,693,'valid','published','archived','valid',44,'186d9e2fb071c9ed550aec2bb983fbd7e6cc2ae3c19ae817158dc0b39f9bec5e','70c13a7e8d5dd39c65aa972ae9618d386fb998b443b3118606bf3c0bedb0b33d',NULL,'2026-08-10T14:27:59.913Z','2026-10-07T20:24:28.120Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["تبوك"]','[]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"الصحة","score":3},{"category":"التقنية","score":2}]','Active','2026-10-07T19:06:36.489Z',200,76,0,'source_article_available','',NULL,NULL,'body:fbb63aa0762f6994392aded80f356db7b1fab5e635d2027ee3e499e1afc5fc84','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3a52291e-44f4-469e-aecc-c0e6bf3d25b6','news-3a52291e-44f4-469e-aecc-c0e6bf3d25b6','حرس الحدود بجازان يحبط تهريب 31,500 قرص خاضع لتنظيم التداول الطبي','حرس الحدود بجازان يحبط تهريب 31 500 قرص خاضع لتنظيم التداول الطبي','أحبطت الدوريات البرية لحرس الحدود في قطاع الدائر بمنطقة جازان محاولة تهريب 31,500 قرص خاضع لتنظيم التداول الطبي.','["وجرى استكمال الإجراءات النظامية الأولية، وتسليم المضبوطات لجهة الاختصاص.","وأهابت المديرية العامة لحرس الحدود بالإبلاغ عن أي عمليات تهريب أو مخالفات عبر الاتصال بالرقم (994)، أو الرقم (911) في مناطق مكة المكرمة والمدينة المنورة والرياض والشرقية، و(999) في بقية مناطق المملكة، مؤكدةً أن جميع البلاغات تُعامل بسرية تامة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/yx0s7rx','https://sabq.org/article/yx0s7rx','','https://sabq.org/article/yx0s7rx','صحيفة سبق','السعودية','2026-08-10T02:38:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T14:27:59.936Z','https://media.sabq.org/news/2026/08/5f518f49-fbf9-4a89-a50b-e3df99657667/w911.webp','/api/media/3a52291e-44f4-469e-aecc-c0e6bf3d25b6','/api/media/3a52291e-44f4-469e-aecc-c0e6bf3d25b6?variant=thumbnail','حرس الحدود بجازان يحبط تهريب 31,500 قرص خاضع لتنظيم التداول الطبي',911,668,'valid','published','archived','valid',95,'b17a85a478ac79b49a0343c407fe75199f72d7aa28fd981ebd5d864315050edc','ffb59fae78ba42d70d5fde6e92a69332c5c56453903b96003cd0fe2368bc14c6',NULL,'2026-08-10T14:27:59.936Z','2026-10-07T20:24:28.122Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","جازان","الرياض","المدينة المنورة"]','["المدينة المنورة"]','manual_approved','','[]','Active','2026-10-07T19:06:49.291Z',200,72,0,'source_article_available','',NULL,NULL,'body:d1b5e61966fdac5c73cbe1c79f662206fd6a58046e0e40ee933eedbbc46be12a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7ec35633-7054-4caa-96b6-b17d29a03747','news-7ec35633-7054-4caa-96b6-b17d29a03747','مكافحة المخدرات تقبض على مواطن لترويجه 8,265 قرصًا خاضعًا لتنظيم التداول الطبي بالرياض','مكافحه المخدرات تقبض علي مواطن لترويجه 8 265 قرصا خاضعا لتنظيم التداول الطبي بالرياض','ألقت المديرية العامة لمكافحة المخدرات القبض على مواطن بمنطقة الرياض؛ لترويجه 8,265 قرصًا خاضعًا لتنظيم التداول الطبي.','["وجرى إيقافه واتخاذ الإجراءات النظامية بحقه، وإحالته إلى النيابة العامة.","وأهابت المديرية العامة لمكافحة المخدرات بالإبلاغ عن أي نشاطات مرتبطة بتهريب أو ترويج المخدرات، عبر الرقم (995) أو البريد الإلكتروني [ 995@gdnc.gov.sa ]( mailto:995@gdnc.gov.sa)، مؤكدةً أن جميع البلاغات تعامل بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/k2lz8pl','https://sabq.org/article/k2lz8pl','','https://sabq.org/article/k2lz8pl','صحيفة سبق','السعودية','2026-08-10T02:30:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T14:28:01.045Z','https://media.sabq.org/news/2026/08/d302214a-0a5c-46c5-9ba9-d89612249581/w1122.webp','/api/media/7ec35633-7054-4caa-96b6-b17d29a03747','/api/media/7ec35633-7054-4caa-96b6-b17d29a03747?variant=thumbnail','مكافحة المخدرات تقبض على مواطن لترويجه 8,265 قرصًا خاضعًا لتنظيم التداول الطبي بالرياض',1122,707,'valid','published','archived','valid',44,'2dda8ffb5dfc2a2334afa74112c6ad30620a318fb9142ad52d6cbd27ced6fd51','5a3b9e81c34a64950bd63980e565648eb590dee496616a4be94fc0c2269505dc',NULL,'2026-08-10T14:28:01.045Z','2026-10-07T20:24:28.125Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض"]','[]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"الصحة","score":3},{"category":"التقنية","score":2}]','Active','2026-10-07T19:07:08.937Z',200,76,0,'source_article_available','',NULL,NULL,'body:17679f74f27dc094688fc6cdf980dc1dcddcbc340824e3b9a5751ae2f258a441','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('21137202-b866-436f-a274-98e2e561d4ef','news-21137202-b866-436f-a274-98e2e561d4ef','«صحة الافتراضي» ينجز 11 عملية جراحية روبوتية عن بُعد.. بينها الثانية عالميًا لاستئصال فص رئوي','صحه الافتراضي ينجز 11 عمليه جراحيه روبوتيه عن بعد بينها الثانيه عالميا لاستئصال فص رئوي','نجح مستشفى صحة الافتراضي في إجراء 11 عملية جراحية روبوتية متتالية عن بُعد في تخصصات نوعية دقيقة، وذلك ضمن شراكة وطنية متكاملة ضمّت تجمع حائل الصحي، والمدينة الطبية الجامعية بجامعة الملك سعود، و "زين السعودية"، وشركة إيدج المتخصصة في الأجهزة والحلول الروبوتية، ممثلةً في شركة الأمين، تجسيدًا لتقدم المنظومة الصحية في نقل الخبرات الطبية الدقيقة بين مختلف المناطق','["نجح مستشفى صحة الافتراضي في إجراء 11 عملية جراحية روبوتية متتالية عن بُعد في تخصصات نوعية دقيقة، وذلك ضمن شراكة وطنية متكاملة ضمّت تجمع حائل الصحي، والمدينة الطبية الجامعية بجامعة الملك سعود، و \"زين السعودية\"، وشركة إيدج المتخصصة في الأجهزة والحلول الروبوتية، ممثلةً في شركة الأمين، تجسيدًا لتقدم المنظومة الصحية في نقل الخبرات الطبية الدقيقة بين مختلف المناطق، كما توسّع نطاق الوصول إلى الخدمات الجراحية المتقدمة، بما…","وأوضح \"صحة الافتراضي\" أن الفريق الجراحي في الرياض تمكن من إجراء العمليات عن بُعد للمستفيدين الذي كانوا يتلقون الرعاية في حائل ومواقع أخرى في الرياض، ضمن شبكة متكاملة تتوسع لتغطي مجموعة من المواقع في مناطق المملكة منها مناطق طرفية، وشملت العمليات استئصال الفص السفلي الأيمن من الرئة، في عملية تُعد الثانية عالميًا في استئصال الفص الرئوي عن بُعد، والخامسة عالميًا ضمن عمليات الاستئصال الرئوي عن بُعد، إلى جانب جراحات…","وجاء ذلك ضمن مشروع \"البروتوكول السعودي للعمليات الجراحية عن بُعد\"، الذي أطلقه \"صحة الافتراضي\" بوصفه إطارًا وطنيًّا مرجعيًّا ينظم التدخلات الطبية الروبوتية وفق أعلى معايير الجودة والسلامة، ويسهم في نقل الخبرات المتقدمة بين مناطق المملكة، وتمكين المستفيدين من الوصول إلى الكفاءات التخصصية أينما كانوا.","وحصلت أنظمة الجراحة الروبوتية المستخدمة في المشروع على اعتماد الهيئة العامة للغذاء والدواء، بما يؤكد جاهزيتها للاستخدام السريري، ويدعم أعلى معايير السلامة وفق المتطلبات التنظيمية المعتمدة في المملكة، حيث سبق المشروع تنفيذ سلسلة من الاختبارات والمحاكاة السريرية والفنية والتدريبية، للتحقق من جاهزية الأنظمة والكوادر الطبية والتقنية، بما يعزز موثوقية النموذج التشغيلي، ويرسّخ ريادة المملكة في تبني أحدث التقنيات الطبية…"]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/g1fmzmn','https://sabq.org/article/g1fmzmn','','https://sabq.org/article/g1fmzmn','صحيفة سبق','السعودية','2026-08-10T02:21:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T14:28:01.151Z','https://media.sabq.org/news/2026/08/6d12aa1d-b686-4d8e-b68c-e549a4f5d2da/w1280.webp','/api/media/21137202-b866-436f-a274-98e2e561d4ef','/api/media/21137202-b866-436f-a274-98e2e561d4ef?variant=thumbnail','«صحة الافتراضي» ينجز 11 عملية جراحية روبوتية عن بُعد.. بينها الثانية عالميًا لاستئصال فص رئوي',1280,853,'valid','published','archived','valid',100,'44930099248848d493298f8f8249f99b6c538b0a567e6e2eb39e8abc5a377fc0','4b93a57d30cb06600331e79326206846d6d8b92f242c882157a349b99e8e1770','محدّث','2026-08-10T14:28:01.151Z','2026-10-07T20:24:28.128Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة الأمين تجسيد ا لتقدم","الصحة العامة","الثقافة والفنون","التعليم والتدريب","التقنية والتحول الرقمي","الرياض"]','["شركة الأمين تجسيد ا لتقدم","الصحة العامة","الثقافة والفنون","التعليم والتدريب","التقنية والتحول الرقمي"]','manual_approved','','[]','Active','2026-10-07T19:06:46.106Z',200,76,0,'source_article_available','',NULL,NULL,'body:118b7b8612ff81fc821bcdc9b0ee9f1ceb33add54d4cfd6dc24987e35498f0af','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bd357033-b392-4680-b8e3-0e13791f84ad','news-bd357033-b392-4680-b8e3-0e13791f84ad','الأرصاد ينبه من رياح نشطة وأمطار رعدية في حائل ونجران','الارصاد ينبه من رياح نشطه وامطار رعديه في حائل ونجران','نبَّه المركز الوطني للأرصاد اليوم، من هبوب رياح نشطة على منطقة حائل، تشمل المناطق المفتوحة والطرق السريعة، تؤدي إلى تدنٍ في مدى الرؤية الأفقية إلى (3 - 5) كلم، وتستمر الحالة -بمشيئة الله تعالى- حتى الساعة السادسة مساءً.','["كما نبَّه المركز من هطول أمطار خفيفة على منطقة نجران، تشمل تأثيراتها رياحًا نشطة وتدنيًا في مدى الرؤية الأفقية وصواعق رعدية، على مدينة نجران ومحافظات بدر الجنوب وحبونا وثار ويدمة وخباش، وتستمر الحالة -بمشيئة الله تعالى- حتى الساعة الثامنة مساءً."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/54ifwo3','https://sabq.org/article/54ifwo3','','https://sabq.org/article/54ifwo3','صحيفة سبق','السعودية','2026-08-10T02:26:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T14:28:01.466Z','https://media.sabq.org/news/2026/08/b28938db-dd74-473b-9786-e8fab47464f6/w1600.webp','/api/media/bd357033-b392-4680-b8e3-0e13791f84ad','/api/media/bd357033-b392-4680-b8e3-0e13791f84ad?variant=thumbnail','الأرصاد ينبه من رياح نشطة وأمطار رعدية في حائل ونجران',1600,1600,'valid','published','archived','valid',86,'cddf9e4e9f2c8c9bc4b506e71fa07cf89ce2730e2fd4ae6d4f38ade2ef1ad6af','a9c9858b175738cc9f5e801bf953b83520df28c0d60f474850b6737f4a3eb1bb','محدّث','2026-08-10T14:28:01.466Z','2026-10-07T19:06:43.732Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","نجران"]','["الطقس والمناخ"]','classified','','[{"category":"المناطق","score":3},{"category":"السفر","score":3},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T19:06:43.732Z',200,73,0,'source_article_available','',NULL,NULL,'body:412260ed797976c80732ca3e9ce378ba74eab44f92f368651a36e361f85280e1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('944a0a86-9bea-445f-980e-1e3ef1d3470f','news-944a0a86-9bea-445f-980e-1e3ef1d3470f','شباب مكة يحلقون بأشرعة «الكايت سيرف» فوق مياه الشعيبة.. مغامرة بحرية تجمع الإثارة والمهارة','شباب مكه يحلقون باشرعه الكايت سيرف فوق مياه الشعيبه مغامره بحريه تجمع الاثاره والمهاره','تعد رياضة "الكايت سيرف" من الرياضات المائية الحديثة نسبيًا خلال العقود الأخيرة، وانتشرت في عدد من الوجهات الساحلية حول العالم، مستفيدة من تطور صناعة الطائرات الشراعية والألواح وأنظمة التحكم والسلامة، قبل أن تتوسع قاعدة ممارسيها وتصبح إحدى الرياضات البحرية التي تستقطب الباحثين عن المغامرة والتحدي.','["وأسهم امتداد السواحل وتنوع المواقع البحرية بالمملكة في إيجاد بيئة مناسبة لممارسة عدد من الرياضات المائية، ومنها \"الكايت سيرف\"، وشهدت السنوات الماضية تنظيم فعاليات ومنافسات مرتبطة بهذه الرياضة، بالتزامن مع تنامي الاهتمام المجتمعي بالرياضات البحرية والأنشطة الخارجية.","وتقوم فكرة \"الكايت سيرف\" على استخدام طائرة ورقية كبيرة \"شراع\" متصلة بالرياضي بواسطة حبال ونظام تحكم، فيما يقف الممارس على لوح مخصص للانزلاق فوق سطح الماء، مستفيدًا من قوة الرياح في الحركة واكتساب السرعة وتنفيذ المناورات والقفزات، الأمر الذي يجعلها رياضة تعتمد على التوازن والتركيز والقدرة على قراءة اتجاهات الرياح والتعامل مع الظروف البحرية المختلفة.","ويقصد عدد من هواة الرياضات البحرية من شباب مكة المكرمة منطقة الشعيبة؛ لممارسة رياضة \"الكايت سيرف\" أو التزلج الشراعي على الماء، التي اكتسبت حضورًا متناميًا بين محبي المغامرة؛ لما توفره من تجربة رياضية تجمع بين الإثارة واللياقة البدنية والمهارة في التعامل مع حركة الرياح والمياه.","ويجد شباب مكة المكرمة في شواطئ الشعيبة وجهة مناسبة لممارسة هواياتهم البحرية خلال عطلة نهاية الأسبوع، مستفيدين من قرب المنطقة من العاصمة المقدسة وطبيعتها الساحلية المفتوحة، إذ عُرفت الشعيبة منذ سنوات بأنها إحدى الوجهات التي يقصدها شباب مكة لممارسة الأنشطة البحرية والاستمتاع بأجواء البحر."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/p72mb9t','https://sabq.org/article/p72mb9t','','https://sabq.org/article/p72mb9t','صحيفة سبق','السعودية','2026-08-10T02:17:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T14:28:02.579Z','https://media.sabq.org/news/2026/08/37194af2-9928-4256-ab71-8172689bd6a4/w1600.webp','/api/media/944a0a86-9bea-445f-980e-1e3ef1d3470f','/api/media/944a0a86-9bea-445f-980e-1e3ef1d3470f?variant=thumbnail','صورة من الألبوم',1600,900,'valid','published','archived','valid',52,'c69b269c1924861a4154aaa2090f8e4405e7fd62f6bdd12ea8f85c43d72b380e','8c3436d71690a5d5d926da0c6133de1d7542d312bbf7e7f0364ef884e19ad123','محدّث','2026-08-10T14:28:02.579Z','2026-10-07T20:24:28.132Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الاقتصاد والأسواق","مكة","الرياض"]','["الرياضة السعودية","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الاقتصاد","score":1.5},{"category":"الصحة","score":1.5}]','Active','2026-10-07T19:07:38.137Z',200,77,0,'source_article_available','',NULL,NULL,'body:62328e59042eed5c2f3ba4b27fcaf10dce5552ee12c14e8571e43a882c30d30b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c001b294-6ecd-4c66-aa6c-fc9083b112e9','news-c001b294-6ecd-4c66-aa6c-fc9083b112e9','تكليف المهندس حسام اليوبي عميدًا للكلية التقنية بالعلا','تكليف المهندس حسام اليوبي عميدا للكليه التقنيه بالعلا','صدر قرار وزير التعليم، رئيس مجلس إدارة المؤسسة العامة للتدريب التقني والمهني، بتكليف المهندس حسام بن عبدالرحمن اليوبي عميدًا للكلية التقنية بالعلا، ضمن قرارات تكليف عدد من القيادات التدريبية بالمؤسسة.','["ويُعد المهندس حسام اليوبي من الكفاءات الوطنية في مجال التدريب التقني والمهني، ويحمل مؤهلًا في الهندسة الميكانيكية، إلى جانب خبرات قيادية وإشرافية اكتسبها خلال مسيرته المهنية، التي شغل خلالها عددًا من المهام والمناصب في الكلية التقنية بالعلا.","وأسهم اليوبي خلال مسيرته في دعم وتطوير العملية التدريبية، وتنفيذ عدد من البرامج والمبادرات النوعية، إلى جانب تطوير بيئة التدريب وتعزيز المبادرات الهادفة إلى رفع جودة المخرجات التدريبية، بما يواكب احتياجات سوق العمل ويسهم في تحقيق مستهدفات منظومة التدريب التقني والمهني."]','الوظائف وسوق العمل','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ZuoVYN4','https://sabq.org/article/ZuoVYN4','','https://sabq.org/article/ZuoVYN4','فهد العتيبي','السعودية','2026-08-10T01:19:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T14:28:02.765Z','https://media.sabq.org/news/2026/08/a427c4bb-dca8-4d54-9602-c69b5aa0d609/w1079.webp','/api/media/c001b294-6ecd-4c66-aa6c-fc9083b112e9','/api/media/c001b294-6ecd-4c66-aa6c-fc9083b112e9?variant=thumbnail','تكليف المهندس حسام اليوبي عميدًا للكلية التقنية بالعلا',1079,977,'valid','published','archived','valid',54,'d3623292f4b62e77073aa9be952f54627334d522e12d92608ae573df9ff7fa4d','4954b4940062999b9c50baf9d0b8a06fc137bc84a5c106647ea3a7509df36227','محدّث','2026-08-10T14:28:02.765Z','2026-10-07T20:24:28.134Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":3},{"category":"الاقتصاد","score":1.5},{"category":"التعليم","score":1.5}]','Active','2026-10-07T19:07:04.926Z',200,72,0,'source_article_available','',NULL,NULL,'body:8ba34e0bded17da1c442c74b1874b76bad0f234fbc0b4826a761552f69430e3c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8166f66d-2713-4fe7-8004-83201a4948ae','news-8166f66d-2713-4fe7-8004-83201a4948ae','اكتتاب صكوك بنك الرياض يشهد إقبالاً واسعاَ بقيمة طلبات بلغت 13.6 مليار والبنك يقرر رفع حجم الإصدار الى 10 مليارات ريال','اكتتاب صكوك بنك الرياض يشهد اقبالا واسعا بقيمه طلبات بلغت 13 6 مليار والبنك يقرر رفع حجم الاصدار الي 10 مليارات ريال','أعلن بنك الرياض عن انتهاء الاكتتاب العام في إصدار صكوك الشريحة الأولى المقومة بالريال السعودي، والذي اختتم يوم الاثنين 3 أغسطس 2026م، محققاً نتائج تجاوزت المستهدفات المعلنة، في تأكيد جديد على ثقة المستثمرين بمكانة البنك وقوة مركزه المالي.','["وشهد الطرح إقبالاً واسعاً من المستثمرين، حيث بلغت قيمة اجمالي الطلبات 13.6 مليار ريال، محققًة نسبة تغطية قاربت ال300% من حجم الإصدار الأصلي ، وعليه فقد قرر البنك رفع قيمة الطرح لتصل الى 10 مليارات ريال.","فيما استقطب الإصدار أكثر من 25 ألف مستثمراً من الأفراد والمؤسسات والشركات والجمعيات الخيرية وصناديق الاستثمار.","ويأتي هذا الإصدار ضمن برنامج صكوك بنك الرياض الهادف إلى تنويع مصادر التمويل وتعزيز القاعدة الرأسمالية للبنك، بما يدعم استراتيجيته للنمو المستدام ويعزز قدرته على تلبية احتياجات العملاء وتمويل الفرص الاستثمارية في مختلف القطاعات الاقتصادية بالمملكة.","وقال الأستاذ نادر الكريّع، الرئيس التنفيذي لبنك الرياض: “تعكس نتائج الاكتتاب الثقة الكبيرة التي يحظى بها بنك الرياض لدى المستثمرين، كما تؤكد قوة مركزنا المالي وقدرتنا على تنفيذ خططنا الاستراتيجية بكفاءة."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/f1lu4hx','https://sabq.org/article/f1lu4hx','','https://sabq.org/article/f1lu4hx','صحيفة سبق','السعودية','2026-08-10T01:34:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T14:28:03.146Z','https://media.sabq.org/news/2026/08/d671f758-1a46-4d1a-af8f-bc02710d1323/w1600.webp','/api/media/8166f66d-2713-4fe7-8004-83201a4948ae','/api/media/8166f66d-2713-4fe7-8004-83201a4948ae?variant=thumbnail','اكتتاب صكوك بنك الرياض يشهد إقبالاً واسعاَ بقيمة طلبات بلغت 13.6 مليار والبنك يقرر رفع حجم الإصدار الى 10 مليارات ريال',1600,899,'valid','published','archived','valid',99,'217285570558680352e80b458eb6ef2914363a7e9847958a678ad8c5674050a0','cd93509a849cfa17b2c0eb1fb39ee371cbdb0e22d759e5a438741cb17a86c39e','محدّث','2026-08-10T14:28:03.146Z','2026-10-07T19:07:15.385Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الاقتصاد والأسواق","الرياض"]','["الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"الرياضة","score":1.5},{"category":"الصحة","score":0}]','Active','2026-10-07T19:07:15.385Z',200,72,0,'source_article_available','',NULL,NULL,'body:3fa9d84114dc60151cb3c730ba2f985aad28973c68a2bfbcc6baeed3b6ccb564','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4e38bc27-c653-41fa-84f7-7bf2e4b08c66','news-4e38bc27-c653-41fa-84f7-7bf2e4b08c66','مصطفى الشنقيطي يحتفل بعقد قران ابنته بمكة المكرمة','مصطفي الشنقيطي يحتفل بعقد قران ابنته بمكه المكرمه','احتفل مصطفى الشنقيطي بعقد قران ابنته لينا على المهندس عمار القاضي، وسط حضور أهالي العروسين والمدعوين، وذلك في إحدى قاعات الأفراح بمكة المكرمة.','["وأقيم الحفل في أجواء تراثية عكست عبق الموروث الأصيل، وسط حضور كبير غصت به جنبات القاعة.","وشهدت المناسبة مشاركة نخبة من الفنانين والفرق الشعبية، التي أحيت الأمسية بألوان من الفلكلورات الحجازية الأصيلة، وسط تفاعل الحضور ببهجة وسرور، ما أضفى على الحفل أجواءً استثنائية وزاد من رونقه وخصوصيته التراثية."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/s2ho8qw','https://sabq.org/article/s2ho8qw','','https://sabq.org/article/s2ho8qw','صحيفة سبق','السعودية','2026-08-10T01:16:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T14:28:04.266Z','https://media.sabq.org/news/2026/08/8c5081bc-f937-481b-8287-7a24b4f7ded2/w642.webp','/api/media/4e38bc27-c653-41fa-84f7-7bf2e4b08c66','/api/media/4e38bc27-c653-41fa-84f7-7bf2e4b08c66?variant=thumbnail','مصطفى الشنقيطي يحتفل بعقد قران ابنته بمكة المكرمة',642,480,'valid','published','archived','valid',46,'52b91d1dbc5ba8273b3d6ec8c2a57afcf880e27f11c775cfc3c697aa6099b121','f2f65a9d2e82434b5c3b303c808e41ddf14f876e5d4b13a3280f2e668ceb550f','محدّث','2026-08-10T14:28:04.266Z','2026-10-07T20:24:28.138Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة"]','[]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T19:06:53.547Z',200,71,0,'source_article_available','',NULL,NULL,'body:bb2756455b1b38bf6450b52d9002a42ec0582dae70e0442990e6615730613d5c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('64c5532a-bb16-47dd-a0db-c89d1455ca28','news-64c5532a-bb16-47dd-a0db-c89d1455ca28','اتفاقية مكة .. الدفاع والردع','اتفاقيه مكه الدفاع والردع','احتضنت مكة المكرمة، مهبط الوحي وقبلة المسلمين أول بيت وضع للناس ومنطلق رسالة التوحيد وخاتمة الرسالات وأرض الحرم والكرم والرسول «اتفاقية مكة للدفاع المشترك» بين المملكة العربية السعودية وتركيا وباكستان، في حدث يحمل من دلالة المكان وأهمية الاتفاق ما يجعله رسالة واضحة بأن السلام يحتاج إلى قوة تحميه، وأن أمن الدول لا يصان بالتمنيات، وإنما بالحكمة والقدرة والردع.','["وجاءت الاتفاقية لتؤكد عمق الروابط والمصالح الاستراتيجية بين الدول الثلاث، ولتعزز تعاونها الدفاعي وأمنها المشترك، وكان أبرز ما فيها أن أي هجوم مسلح على إحدى الدول الموقعة يُعد هجومًا على الجميع.","وهنا تكمن قوة الاتفاقية ورسالتها الحقيقية؛ فهي ليست دعوة إلى الحرب، وإنما وسيلة لمنعها.","فالردع الناجح هو الذي يجعل من يفكر في العدوان يدرك قبل أن يقدم عليه أن كلفته ستكون أكبر من مكاسبه، وأن الاعتداء على دولة لن يبقى شأنًا بينها وبين المعتدي، بل سيواجه موقفًا دفاعيًا مشتركًا.","والمملكة العربية السعودية، منذ تأسيسها، قامت سياستها على الوضوح والاعتدال ومد يد السلام والتعاون، مع الاحتفاظ بالقوة اللازمة لحماية أرضها ومقدساتها وشعبها وسيادتها."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/l832nso','https://sabq.org/article/l832nso','','https://sabq.org/article/l832nso','عبدالعزيز بن سعيد بن ذياب','السعودية','2026-08-10T01:00:00.000Z','2026-08-10T04:00:00.000Z','2026-08-10T14:28:04.374Z','https://media.sabq.org/news/2026/08/3cf2f6ce-dd2e-49df-babb-769e0f39c882/w1600.webp','/api/media/64c5532a-bb16-47dd-a0db-c89d1455ca28','/api/media/64c5532a-bb16-47dd-a0db-c89d1455ca28?variant=thumbnail','اتفاقية مكة .. الدفاع والردع',1600,893,'valid','published','archived','valid',99,'beb485da29f51675ee294497f32ed52c23aa1be0bb05a4e7e2f9b30bb72ae3a4','0f9f6946d45612371f6eada3d6adc2a7b41011cf696d9174cee319cf267536ad','محدّث','2026-08-10T14:28:04.374Z','2026-10-07T19:07:15.996Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة"]','[]','classified','','[{"category":"المناطق","score":3},{"category":"الاقتصاد","score":1.5},{"category":"السيارات","score":1.5}]','Active','2026-10-07T19:07:15.996Z',200,72,0,'source_article_available','',NULL,NULL,'body:7b17cdb7682e9e07d5bc477820c0263c337fb979e177a092507a64f66c44c8cc','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1ffb4de4-7f9f-4966-bb9c-b1ee3b30d58c','news-1ffb4de4-7f9f-4966-bb9c-b1ee3b30d58c','من الطباعة إلى اللوحات والحروف البارزة.. 4 شركات تقدم خدمات متكاملة في المملكة','من الطباعه الي اللوحات والحروف البارزه 4 شركات تقدم خدمات متكامله في المملكه','تبحث الشركات اليوم عن شريك قادر على تنفيذ جميع احتياجاتها الإعلانية تحت سقف واحد، بدءًا من تصميم الهوية البصرية، مرورًا بالمطبوعات التجارية، وصولًا إلى اللوحات الخارجية والحروف البارزة وواجهات الكلادينج.','["لذلك أصبح اختيار الشركة المناسبة عنصرًا مؤثرًا في نجاح أي نشاط تجاري، لأن جودة التنفيذ تنعكس مباشرة على صورة العلامة التجارية أمام العملاء.","ومع التطور الكبير الذي تشهده المملكة العربية السعودية في قطاعات الأعمال والتجزئة والمعارض، ازداد الطلب على الشركات التي تجمع بين التصميم الاحترافي، وجودة التصنيع، وسرعة التنفيذ، مع توفير حلول متكاملة تناسب مختلف القطاعات.","في هذا الدليل نستعرض أربع شركات تقدم خدمات متكاملة في مجال الدعاية والإعلان والطباعة داخل المملكة، وهي: شركة اتجاه الفخامة للدعاية والإعلان.","مؤسسة العلمين المتحدة للدعاية والإعلان وكالة كود الاعلانيه ."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/iljp62x','https://sabq.org/article/iljp62x','','https://sabq.org/article/iljp62x','صحيفة سبق','السعودية','2026-08-10T01:13:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T14:28:04.462Z','https://media.sabq.org/news/2026/08/9853e3e3-f02c-410b-be10-b87b248459ff/w1536.webp','/api/media/1ffb4de4-7f9f-4966-bb9c-b1ee3b30d58c','/api/media/1ffb4de4-7f9f-4966-bb9c-b1ee3b30d58c?variant=thumbnail','من الطباعة إلى اللوحات والحروف البارزة.. 4 شركات تقدم خدمات متكاملة في المملكة',1536,1024,'valid','published','archived','valid',53,'af189f58b7b98e72d5436ae5fad707f9329906ac8bddd52b7e63796e34a3d960','0c30f8a7e3c962f227b6b99b3c1b8383dc82ef35522e6dd4d60ab051f6f3d639','محدّث','2026-08-10T14:28:04.462Z','2026-10-07T19:07:39.683Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة اتجاه الفخامة للدعاية والإعلان"]','["شركة اتجاه الفخامة للدعاية والإعلان"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T19:07:39.683Z',200,74,0,'source_article_available','',NULL,NULL,'body:36d9ce0d50ecd0a6c65b0d1c679c0ce1571a52518567a6572f6ad776927212da','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('11212744-b611-4776-94a7-8fad420ea256','news-11212744-b611-4776-94a7-8fad420ea256','القمة العالمية للاستثمار 2026 في باريس.. مبادرات للطاقة النظيفة وتوقعات بضخ 28.59 مليار دولار في الخليج','القمه العالميه للاستثمار 2026 في باريس مبادرات للطاقه النظيفه وتوقعات بضخ 28 59 مليار دولار في الخليج','تطلق القمة العالمية للاستثمار 2026، المقرر عقدها في العاصمة الفرنسية باريس يومي 1 و2 سبتمبر المقبل، مجموعة من المبادرات النوعية في قطاع الطاقة، تستهدف رفع كفاءة الاستهلاك، ودعم مشروعات الطاقة المتجددة والنظيفة، وتوسيع تطبيق ممارسات الاستدامة في العمليات التشغيلية.','["وتعكس المبادرات توجه القمة نحو دعم التحول في قطاع الطاقة، وربط الفرص الاستثمارية بالحلول التي تسهم في رفع الكفاءة وخفض الأثر البيئي، إلى جانب تطوير مشروعات أكثر توافقًا مع متطلبات الاستدامة والتحولات الاقتصادية حتى عام 2030.","ويتضمن برنامج القمة عددًا من ورش العمل المتخصصة في مجالات الطاقة والاستدامة، من أبرزها اتفاقيات شراء الهيدروجين الأخضر، والتمويل الأخضر، والامتثال لمعايير الاستدامة والحوكمة «ESG»، بما يتيح مناقشة آليات التمويل والتنفيذ، وتطوير نماذج شراكة تجمع المستثمرين بالمطورين والمؤسسات المالية.","وتستهدف القمة توجيه 25% من الاستثمارات نحو التقنيات الحديثة، واعتماد معايير الاستدامة البيئية والاجتماعية والحوكمة «ESG» في 55% من المشروعات المستهدفة، بما يدعم تطوير مشروعات أكثر كفاءة واستدامة وقدرة على تحقيق أثر اقتصادي طويل الأمد.","وبحسب بيانات القمة، يُتوقع أن تصل التدفقات الاستثمارية الأوروبية إلى دول مجلس التعاون الخليجي إلى 28.59 مليار دولار، إلى جانب تطوير 15 مشروعًا مشتركًا وبناء 8 شراكات استراتيجية خلال العام الأول، بما يفتح مسارات جديدة للاستثمار في الطاقة النظيفة والبنية التحتية والتقنيات المرتبطة بالاستدامة."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/iuewqu4','https://sabq.org/article/iuewqu4','','https://sabq.org/article/iuewqu4','مسلّم الهواملة','السعودية','2026-08-10T04:03:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T16:33:39.794Z','https://media.sabq.org/news/2026/08/8eb0e3d3-926a-41ff-8c36-a458abc67b4e/w1200.webp','/api/media/11212744-b611-4776-94a7-8fad420ea256','/api/media/11212744-b611-4776-94a7-8fad420ea256?variant=thumbnail','القمة العالمية للاستثمار 2026 في باريس.. مبادرات للطاقة النظيفة وتوقعات بضخ 28.59 مليار دولار في الخليج',1200,675,'valid','published','archived','valid',97,'914bb5caa998c244639a065fe777d30234e6439224ebbec3a83e7dde2e848d65','50fb20c33d61cee8aec0351727a16b58c9d26967b3083b95c3ae41f022ad52be','محدّث','2026-08-10T16:33:39.794Z','2026-10-07T19:05:51.578Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس التعاون الخليجي إلى","الطاقة والنفط","الاقتصاد والأسواق"]','["مجلس التعاون الخليجي إلى","الطاقة والنفط","الاقتصاد والأسواق"]','classified','','[{"category":"الطاقة والصناعة","score":3},{"category":"العالم","score":3},{"category":"التقنية","score":2}]','Active','2026-10-07T19:05:51.578Z',200,75,0,'source_article_available','',NULL,NULL,'body:7bb864bda0f12a137c89f80dd158190649c2f036b2806a0ef6608b011f5c1fb6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c617c873-5bc9-4447-8a5f-f40f1e9b96e0','news-c617c873-5bc9-4447-8a5f-f40f1e9b96e0','وصول 9 توربينات رياح إلى ينبع لدعم مشروعي «ستارة» و«شقراء» بقدرة 3 آلاف ميجاواط','وصول 9 توربينات رياح الي ينبع لدعم مشروعي ستاره و شقراء بقدره 3 الاف ميجاواط','استقبل ميناء الملك فهد الصناعي في ينبع، بالتنسيق مع وزارة الطاقة والجهات المعنية، السفينة «باسيفيك تايتان» (Pacific Titan)، وعلى متنها شحنة تضم 9 توربينات رياح بكامل أجزائها وملحقاتها، من بينها 27 شفرة، إضافة إلى عدد من المكونات اللازمة لتوليد الكهرباء من طاقة الرياح، وذلك لصالح مشروعي «ستارة» في محافظة الأفلاج و«شقراء» لطاقة الرياح، ضمن منظومة مشروعات الطاق','["وتأتي الشحنة في إطار جهود المملكة للتوسع في استخدام مصادر الطاقة المتجددة وأنظمة تخزين الطاقة، ودعم مستهدفات البرنامج الوطني للطاقة المتجددة، الذي يستهدف تعزيز مساهمة مصادر الطاقة النظيفة في مزيج إنتاج الكهرباء لتصل إلى نحو 50% بحلول عام 2030، وفقًا لنمو الطلب على الكهرباء.","ويُعد مشروعا «ستارة» و«شقراء» من مشروعات البرنامج الوطني للطاقة المتجددة، الذي تشرف وزارة الطاقة على تنفيذه من خلال الشركة السعودية لشراء الطاقة بصفتها «المشتري الرئيس»، حيث تتولى إعداد الدراسات التمهيدية، وطرح مشروعات توليد الكهرباء، وإبرام اتفاقيات شراء الطاقة واتفاقيات خدمات تخزين الطاقة مع التحالفات المطورة.","ويُعد مشروع «ستارة» لطاقة الرياح في محافظة الأفلاج، بقدرة إنتاجية تبلغ 2000 ميجاواط (2 جيجاواط)، من أكبر مشروعات طاقة الرياح في الشرق الأوسط، فيما تبلغ القدرة الإنتاجية لمشروع «شقراء» 1000 ميجاواط، بإجمالي 3000 ميجاواط للمشروعين، بما يعزز قدرة المملكة على التوسع في إنتاج الكهرباء من مصادر الطاقة المتجددة."]','الطاقة والصناعة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/lh79f3f','https://sabq.org/article/lh79f3f','','https://sabq.org/article/lh79f3f','مسلّم الهواملة','السعودية','2026-08-10T04:08:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T16:33:39.847Z','https://media.sabq.org/news/2026/08/9bef437a-d6cc-4fbc-9be6-b06e69dad246/w1600.webp','/api/media/c617c873-5bc9-4447-8a5f-f40f1e9b96e0','/api/media/c617c873-5bc9-4447-8a5f-f40f1e9b96e0?variant=thumbnail','وصول 9 توربينات رياح إلى ينبع لدعم مشروعي «ستارة» و«شقراء» بقدرة 3 آلاف ميجاواط',1600,899,'valid','published','archived','valid',87,'004cf491dbc9daca52d10b1bf35c5b9516978d23f8bd8b38a164452afc1142a8','8fbbda97b940d8a232e213cece3c23a5e556519f717cfff07647bdeeebf37849','محدّث','2026-08-10T16:33:39.847Z','2026-10-07T19:06:11.041Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الطاقة على تنفيذه من","الطاقة والنفط","الشرق الأوسط"]','["وزارة الطاقة على تنفيذه من","الطاقة والنفط","الشرق الأوسط"]','classified','','[{"category":"المناطق","score":4},{"category":"أخبار السعودية","score":3},{"category":"السياسة","score":0}]','Active','2026-10-07T19:06:11.041Z',200,78,0,'source_article_available','',NULL,NULL,'body:b424b49e650c3cf18cb287aa0b3908c2adf402b35d20e140ad6a2f308212ddbf','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c8542368-519f-4f67-bf7f-e51b32b58c03','news-c8542368-519f-4f67-bf7f-e51b32b58c03','قد تصل لمعركة .. هذه أكثر شكوى لموظفي كاونترات السفر بالمطارات من المسافرين ','قد تصل لمعركه هذه اكثر شكوي لموظفي كاونترات السفر بالمطارات من المسافرين','تتكرر الشكوى بصورة أكبر في مواسم الذروة والإجازات، عندما تسافر العائلات بحقائب متعددة، أو يعود المسافرون بعد التسوق بأوزان تفوق ما كان مسموحًا لهم عند بداية الرحلة.','["يبدأ المشهد غالبًا بجملة قصيرة: «الحقيبة زائدة عن الوزن المسموح»، لتتحول بعدها دقائق إنهاء إجراءات السفر إلى نقاش طويل بين الراكب وموظف الكاونتر؛ فبين من يرى أن زيادة كيلوغرام أو اثنين لا تستحق الرسوم، وموظف ملزم بتطبيق شروط التذكرة، يبقى الوزن الزائد للأمتعة واحدًا من أكثر المواقف اليومية حساسية عند منصات إنهاء إجراءات السفر في المطارات.","وتؤكد قواعد الاتحاد الدولي للنقل الجوي IATA أن وزن الأمتعة المسموح به ليس رقمًا موحدًا عالميًا، وإنما يختلف بحسب شركة الطيران والمسار ودرجة السفر ونوع التذكرة. «إنها كيلوغرامات قليلة» من أكثر المشاهد التي يواجهها موظف الكاونتر اعتراض بعض الركاب على رسوم الوزن الزائد، خصوصًا عندما يكون التجاوز محدودًا.","ويرى الراكب أحيانًا أن زيادة كيلوغرام أو اثنين يمكن التغاضي عنها، بينما يجد الموظف نفسه أمام نظام إلكتروني وسياسة محددة للوزن المرتبط بفئة التذكرة وربما تتطور الأمور ويتحول النقاش الى معركة بسبب التأخر عن موعد الاقلاع وتبدأ عندها محاولات إعادة توزيع محتويات الحقائب، أو نقل بعض الأغراض إلى حقيبة أخرى، أو إخراجها ووضعها في حقيبة اليد، فيما قد يضطر المسافر في النهاية إلى شراء وزن إضافي.","التذكرة هي التي تحدد وتختلف أوزان الأمتعة بصورة كبيرة من ناقلة إلى أخرى، بل إن الاختلاف قد يكون موجودًا داخل الرحلة نفسها بحسب فئة السعر."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/m3015o1','https://sabq.org/article/m3015o1','','https://sabq.org/article/m3015o1','خالد خليل','السعودية','2026-08-10T03:57:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T16:33:40.016Z','https://media.sabq.org/news/2026/08/56f2e0d3-792c-4b89-a0bf-ba2a6924caba/w857.webp','/api/media/c8542368-519f-4f67-bf7f-e51b32b58c03','/api/media/c8542368-519f-4f67-bf7f-e51b32b58c03?variant=thumbnail','قد تصل لمعركة .. هذه أكثر شكوى لموظفي كاونترات السفر بالمطارات من المسافرين ',857,559,'valid','published','archived','valid',98,'e11ee13da57fba912ce44ae6f915b1d13e5f1e324e2f8a7ac38d44604d83136a','bf00e0edd3266d74cc68172fd62c61782d9c66261551fe2e6c2d5d003e438530','محدّث','2026-08-10T16:33:40.016Z','2026-10-07T19:06:37.245Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة الطيران والمسار ودرجة السفر","السفر والسياحة","السياسة والعلاقات الدولية"]','["شركة الطيران والمسار ودرجة السفر","السفر والسياحة","السياسة والعلاقات الدولية"]','classified','','[{"category":"الاقتصاد","score":1.5},{"category":"الصحة","score":1.5},{"category":"التقنية","score":1.5}]','Active','2026-10-07T19:06:37.245Z',200,76,0,'source_article_available','',NULL,NULL,'body:49d96d6a17a470e285abedfaaaa384c84729cf94297b5dc6e05d062d176eb497','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('65ce5ea3-10c8-4ff0-ba7c-66661b71fa12','news-65ce5ea3-10c8-4ff0-ba7c-66661b71fa12','غدًا.. الإداريون والمشرفون أول العائدين للمدارس استعدادًا للعام الدراسي الجديد.. والمعلمون الأحد والطلاب 23 أغسطس','غدا الاداريون والمشرفون اول العائدين للمدارس استعدادا للعام الدراسي الجديد والمعلمون الاحد والطلاب 23 اغسطس','تنطلق غداً الثلاثاء 28 صفر 1448هـ، الموافق 11 أغسطس 2026، أولى مراحل العودة المدرسية في مدارس التعليم العام بمختلف مناطق ومحافظات المملكة، إذ يعود الإداريون والمشرفون التربويون إلى مدارسهم استعداداً لانطلاقة العام الدراسي الجديد 1448هـ.','["وتتواصل مراحل العودة تباعاً، بعودة المعلمين والمعلمات الممارسين للتدريس الأحد المقبل 3 ربيع الأول 1448هـ، الموافق 16 أغسطس الجاري، إيذاناً ببدء الاستعدادات النهائية لتجهيز المدارس والفصول الدراسية لاستقبال الطلاب.","وتُستثنى من موعد عودة الإداريين والمشرفين غداً إدارات التعليم في مكة المكرمة والمدينة المنورة وجدة والطائف، وفق المواعيد المحددة في التقويم الدراسي. 59 يوماً من الإجازة الصيفية يعود الطلاب والطالبات إلى مقاعد الدراسة الأحد 10 ربيع الأول 1448هـ، الموافق 23 أغسطس 2026، بعد إجازة صيفية امتدت 59 يوماً بدأت في 25 يونيو 2026، لتنطلق بذلك الدراسة الفعلية للعام الدراسي الجديد رسمياً في المناطق المشمولة بهذا الموعد، فيما…","وتأتي عودة الكوادر الإدارية والتعليمية على مراحل متتالية قبل انتظام الطلاب والطالبات، ضمن الاستعدادات النهائية لانطلاقة عام دراسي جديد، وتهيئة المدارس لاستقبال منسوبيها في مختلف مناطق ومحافظات المملكة."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/GtzjiyV','https://sabq.org/article/GtzjiyV','','https://sabq.org/article/GtzjiyV','عبدالحكيم شار','السعودية','2026-08-10T03:44:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T16:33:40.925Z','https://media.sabq.org/news/2026/08/6fb56b03-b6dd-4415-86b2-05333af1ee5f/w1600.webp','/api/media/65ce5ea3-10c8-4ff0-ba7c-66661b71fa12','/api/media/65ce5ea3-10c8-4ff0-ba7c-66661b71fa12?variant=thumbnail','غدًا.. الإداريون والمشرفون أول العائدين للمدارس استعدادًا للعام الدراسي الجديد.. والمعلمون الأحد والطلاب 23 أغسطس',1600,900,'valid','published','archived','valid',98,'242d4d09816dfe26b61b2fe945ecc9fa6aec02835bfb8fea86f3e0462e2a866b','05b9b92557ffcbe6084a7896cf5638115436b9f7f69898979d7a1ca4f3473336','محدّث','2026-08-10T16:33:40.925Z','2026-10-07T19:05:50.962Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","مكة","جدة","المدينة المنورة"]','["التعليم والتدريب","المدينة المنورة"]','classified','','[{"category":"المناطق","score":4.5},{"category":"أخبار السعودية","score":1.5},{"category":"السياسة","score":0}]','Active','2026-10-07T19:05:50.962Z',200,71,0,'source_article_available','',NULL,NULL,'body:e77790c8a31e8c2ed9885882e3d97a1306e560e64a454ac6d83cd0372fd8c1b8','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3731e012-bf23-412a-98f7-c382a7359e1b','news-3731e012-bf23-412a-98f7-c382a7359e1b','صندوق النمر العربي يفتح باب التقديم لمنح بحثية تصل إلى 94 ألف ريال','صندوق النمر العربي يفتح باب التقديم لمنح بحثيه تصل الي 94 الف ريال','أعلن صندوق النمر العربي فتح باب التقديم لبرنامج المنح الصغيرة لعام 2026؛ لدعم الأبحاث والمبادرات الميدانية التي تسهم في صون النمر العربي وموائله الطبيعية، وتعزيز المعرفة العلمية اللازمة لاتخاذ قرارات أكثر فاعلية في حماية هذا النوع المصنف ضمن الأنواع المهددة بالانقراض بشكل حرج.','["ويستهدف البرنامج توسيع قاعدة البحث والعمل الميداني المرتبط بالنمر العربي، من خلال دعم الأبحاث والمبادرات التي تثري المعرفة العلمية حول سلوكه وموائله وفرائسه، وتعزز الاستفادة من نتائج الأبحاث والرصد في تطوير ممارسات الصون وإدارة الموائل.","ويقدم البرنامج دعماً مالياً يصل إلى نحو 19 ألف ريال للمبادرات، ونحو 94 ألف ريال للمشاريع البحثية، فيما تصل مدة المشاريع المؤهلة للتمويل إلى عام واحد، بما يتيح دعم مشاريع قابلة للتنفيذ تسهم في إنتاج معرفة جديدة وتطوير حلول عملية.","ويفتح البرنامج المجال أمام الباحثين والمؤسسات البحثية والأكاديمية والجهات والمنظمات ذات العلاقة والمختصين والخبراء وطلاب البكالوريوس والدراسات العليا، للتقدم بمقترحات في مجالات تشمل البحث العلمي والرصد البيئي، وصون الحياة الفطرية والموائل الطبيعية، والطب البيطري، وعلم البيئة.","وينفَّذ البرنامج عبر دورتين خلال عام 2026، بما يتيح دعم نطاق أوسع من الأبحاث والمبادرات المتخصصة، وتعزيز مشاركة الباحثين والمختصين والمؤسسات في بناء قاعدة معرفية تسهم في رفع كفاءة الرصد والحماية."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/CpHMGU4','https://sabq.org/article/CpHMGU4','','https://sabq.org/article/CpHMGU4','صحيفة سبق','السعودية','2026-08-10T03:39:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T16:33:41.117Z','https://media.sabq.org/news/2026/08/d17c80b8-0302-48d2-8bca-bfb0c7fe1e21/w619.webp','/api/media/3731e012-bf23-412a-98f7-c382a7359e1b','/api/media/3731e012-bf23-412a-98f7-c382a7359e1b?variant=thumbnail','صندوق النمر العربي يفتح باب التقديم لمنح بحثية تصل إلى 94 ألف ريال',619,323,'valid','published','archived','valid',52,'44ee5a62c2c0b69db31725ef74f4881acf7dc4ad221f0129b06eff00df1ffca3','4bad1373c1a111d3e050e8e8ea5ffafe49a79222f5266734094c8c3157d44c45','محدّث','2026-08-10T16:33:41.117Z','2026-10-07T19:06:51.364Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"البيئة والمناخ","score":5.5},{"category":"الاقتصاد","score":3},{"category":"التقنية","score":2}]','Active','2026-10-07T19:06:51.364Z',200,73,0,'source_article_available','',NULL,NULL,'body:e8c2ac60bb18be76d79a4728d9eba3458cb38611fb0e012fe4b680486936c557','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('326ec571-383c-4f63-8c31-8e7363445d90','news-326ec571-383c-4f63-8c31-8e7363445d90','طيران ناس يوقع اتفاقية إطارية موحدة لتقديم خدمات الإركاب الحكومي بدءاً من الربع الرابع 2026 ','طيران ناس يوقع اتفاقيه اطاريه موحده لتقديم خدمات الاركاب الحكومي بدءا من الربع الرابع 2026','أعلن طيران ناس، الناقل السعودي الاقتصادي الرائد في العالم والأول في الشرق الأوسط، توقيع اتفاقية إطارية موحدة للإركاب الحكومي مع هيئة كفاءة الإنفاق والمشروعات الحكومية، وتأتي هذه الاتفاقية لتقديم خدمات السفر الحكومي (الإركاب الحكومي) ضمن قطاع الطيران الاقتصادي للجهات الحكومية، وذلك لأول مره في تاريخ الشركة.','["وأوضحت الشركة أنها تعمل حالياً بالتعاون مع الجهات الحكومية المختصة على استكمال أعمال الربط التقني اللازم لتفعيل الاتفاقية، مشيرةً إلى أنه من المتوقع الانتهاء من الربط وبدء تفعيل خدمة الإركاب الحكومي مطلع الربع الرابع من العام الجاري 2026.","وأضافت الشركة أنه في حال اكتمال الربط التقني وفق الجدول الزمني المستهدف، فمن المتوقع أن يبدأ الأثر المالي للشركة لهذه الاتفاقية الإطارية اعتباراً من الربع الرابع من عام 2026.","وأكد طيران ناس أنه سيعلن عن أي تطورات جوهرية ذات صلة بهذه الاتفاقية وفقاً للأنظمة والتعليمات ذات العلاقة.","طيران ناس الناقل الجوي الاقتصادي الرائد في العالم والأول في الشرق الأوسط، هو أول طيران مُدرج في السوق السعودية الرئيسية (تداول)، يشغّل أكثر من 2000 رحلة أسبوعياً إلى أكثر من 80 وجهة داخلية ودولية في 38 دولة عبر 156 خط سير، ونقل 110 ملايين مسافر منذ إطلاقه في عام 2007، ويستهدف الوصول إلى 165 وجهة ضمن خطته للنمو والتوسع، بالتواؤم مع أهداف رؤية السعودية 2030."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7zjgeii','https://sabq.org/article/7zjgeii','','https://sabq.org/article/7zjgeii','صحيفة سبق','السعودية','2026-08-10T03:25:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T16:33:41.593Z','https://media.sabq.org/news/2026/08/d35a849a-c82b-4f6b-8190-4c022945280c/w1600.webp','/api/media/326ec571-383c-4f63-8c31-8e7363445d90','/api/media/326ec571-383c-4f63-8c31-8e7363445d90?variant=thumbnail','طيران ناس يوقع اتفاقية إطارية موحدة لتقديم خدمات الإركاب الحكومي بدءاً من الربع الرابع 2026 ',1600,1066,'valid','published','archived','valid',52,'a990ace3a991f1f018f5fffdd170a92492c4b593ae7e5f6faf628a8ef1cf9c2c','fd6f4475b4a74c9abb7e57db848d7401acf6f03e54b9ca0827558d0326fc4a8a','محدّث','2026-08-10T16:33:41.593Z','2026-10-07T19:06:02.662Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","التعليم والتدريب","الاقتصاد والأسواق","الشرق الأوسط"]','["السفر والسياحة","التعليم والتدريب","الاقتصاد والأسواق","الشرق الأوسط"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الاقتصاد","score":1.5},{"category":"التعليم","score":1.5}]','Active','2026-10-07T19:06:02.662Z',200,76,0,'source_article_available','',NULL,NULL,'body:9c01485c07caf952df8edd0180090065ad05ccea8c9a5b190156968c03d27002','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fa75e234-67f3-4f9b-8790-94cfbf64983f','news-fa75e234-67f3-4f9b-8790-94cfbf64983f','"زين السعودية" تمكّن 11 جراحة روبوتية متتالية عن بُعد ببنية رقمية متقدمة بينها استئصال رئوي يسجل إنجازا عالمياَ ','زين السعوديه تمكن 11 جراحه روبوتيه متتاليه عن بعد ببنيه رقميه متقدمه بينها استئصال رئوي يسجل انجازا عالميا','في إنجاز جديد يجسد دورها كممكن رقمي للقطاعات الحيوية، مكّنت زين السعودية، بالتعاون مع مركز تمكين الابتكار التابع لمستشفى صحة الافتراضي، إجراء 11 عملية جراحية روبوتية متتالية عن بُعد عبر بنية تحتية رقمية متطورة صُممت خصيصاً لتوفير زمن استجابة منخفض جدا (Ultra-low Latency) واعتمادية عالية، بما يضمن استمرارية ودقة العمليات الجراحية الحساسة.','["وشهدت المرحلة التشغيلية الأولى نجاح تنفيذ أربع عمليات جراحية روبوتية متتالية في يوم واحد بين مستشفى صحة الافتراضي ومستشفى الملك خالد الجامعي بالرياض، في خطوة أكدت جاهزية البنية الرقمية وكفاءتها في دعم هذا النوع من الإجراءات الدقيقة.","وتواصل تشغيل النموذج خلال الأسبوع ذاته بتنفيذ عدد من العمليات الجراحية الروبوتية عن بُعد في تخصصات متنوعة، شملت تكميم المعدة، واستئصال الرحم، وإصلاح الفتق الإربي، واستئصال المرارة، واستئصال أورام الزائدة الدودية، إضافة إلى عمليات أورام نسائية متقدمة، كما شملت استئصال الفص السفلي الأيمن للرئة، في عملية تُعد الثانية عالميًا في جراحات استئصال الفص الرئوي عن بُعد، والخامسة عالميًا ضمن عمليات الاستئصال الرئوي الروبوتية…","وجاء هذا الإنجاز من خلال البنية الرقمية التي وفرتها زين السعودية بالتعاون مع مركز تمكين الابتكار التابع لمستشفى صحة الافتراضي، والتي أتاحت ربط وحدة تحكم الجرّاح بالنظام الجراحي الروبوتي داخل غرفة العمليات في الوقت الفعلي، لنقل أوامر الجرّاح والفيديو الحي والصوت والبيانات التشغيلية عبر شبكة مخصصة ذات زمن استجابة منخفض واعتمادية عالية.","واعتمدت زين السعودية في تصميم الحل على شبكة رقمية مخصصة تتضمن اتصالًا رئيسيًا وآخر احتياطيًا مستقلًا في كل موقع، مع نطاق ترددي معزول عن حركة البيانات الأخرى، إضافة إلى مراقبة لحظية للخدمة من طرف إلى طرف طوال العملية."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/dw3krlj','https://sabq.org/article/dw3krlj','','https://sabq.org/article/dw3krlj','صحيفة سبق','السعودية','2026-08-10T03:18:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T16:33:42.723Z','https://media.sabq.org/news/2026/08/52b8d7c3-7207-4445-b2ee-296aa84d9c78/w1600.webp','/api/media/fa75e234-67f3-4f9b-8790-94cfbf64983f','/api/media/fa75e234-67f3-4f9b-8790-94cfbf64983f?variant=thumbnail','"زين السعودية" تمكّن 11 جراحة روبوتية متتالية عن بُعد ببنية رقمية متقدمة بينها استئصال رئوي يسجل إنجازا عالمياَ ',1600,900,'valid','published','archived','valid',49,'1081fead6fb10eb0f5e8d00c728f3a9bcf70cf738e0cd6cdad9f860062761cae','d352dc86a800de71b50b133dd16477fee5d2cdf660d456c14c4521cba384cc69','محدّث','2026-08-10T16:33:42.723Z','2026-10-07T19:06:43.744Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","التقنية والتحول الرقمي","الرياض"]','["الصحة العامة","التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":4},{"category":"المجتمع","score":4},{"category":"أخبار السعودية","score":3}]','Active','2026-10-07T19:06:43.744Z',200,73,0,'source_article_available','',NULL,NULL,'body:7734ab2dbdc3f522163552b5837a1212b263174f38417879201d4e4351c539a6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a2226c0e-e98e-4d0e-8be3-a13e3512ed2e','news-a2226c0e-e98e-4d0e-8be3-a13e3512ed2e','رعاية ماسية لـ"الماجدية" في معرض العقارات الفاخرة السعودي 2026 بلندن','رعايه ماسيه لـ الماجديه في معرض العقارات الفاخره السعودي 2026 بلندن','تشارك شركة دار الماجد العقارية “ الماجدية ” بصفتها راعيًا ماسيًّا في معرض العقارات الفاخرة السعودي 2026 “SLRE”، المقرر إقامته في لندن خلال الفترة من 24 إلى 28 أغسطس الجاري، في خطوةٍ تعكس توجُّه الشركة نحو تعزيز حضورها في المحافل العقارية الدولية، والتعريف بمحفظة مشروعاتها أمام المستثمرين والشركاء من مختلف الأسواق.','["ويستضيف فندق “ذا بينينسولا لندن” النسخة الأولى من المعرض، الذي يُقام بشراكةٍ إستراتيجيةٍ مع الهيئة العامة للعقار ، ويجمع نخبةً من المطوِّرين العقاريين والمستثمرين المؤسسين، والمكاتب العائلية، ومديري الثروات، بالتزامن مع تنامي الاهتمام الدولي بالفرص الاستثمارية التي يوفّرها القطاع العقاري السعودي، والتحولات المتسارعة التي تشهدها مدن المملكة.","وتستعرض “الماجدية” خلال مشاركتها في المعرض مجموعةً من أبرز مشروعاتها السكنية والتجارية، تشمل برج مكانة ، وبرج مَعاد، وبرج ذُرى، وبرج قرار، ومشراف الماجدية .","وفي هذا السياق، صرَّح الأستاذ معاذ عبدالعزيز الخريف، مدير عام الأعمال التجارية في \"الماجدية\"، قائلًا: “مشاركتنا راعيًا ماسيًّا في معرض العقارات الفاخرة السعودي في لندن تتجاوز الحضور في حدثٍ عقاريٍّ دوليّ؛ فهي فرصةٌ لعرض ما وصلت إليه تجربة التطوير في المملكة، والتواصل بصورةٍ مباشرةٍ مع مستثمرين يبحثون عن أسواقٍ تتمتع بفرص نموٍّ حقيقية، ومشاريع قادرة على خلق قيمةٍ مستدامة”.","وأضاف: “خلال السنوات الماضية ركَّزنا في الماجدية على بناء مجتمعاتٍ ومنتجاتٍ عقاريةٍ تستجيب لاحتياجات العملاء الفعلية، وتواكب تطوّر المدن السعودية، واليوم نرى أهمية تقديم هذه التجربة للمستثمر الدولي بصورةٍ واضحة، ليس فقط من خلال حجم المشاريع، وإنما عبر جودة المنتج، وفهم السوق والقدرة على تطوير مشاريع تتوافق مع التحوُّلات العمرانية والاقتصادية التي تشهدها المملكة”."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/pdkqrhw','https://sabq.org/article/pdkqrhw','','https://sabq.org/article/pdkqrhw','صحيفة سبق','السعودية','2026-08-10T03:10:00.000Z','2026-08-10T07:24:00.000Z','2026-08-10T16:33:42.762Z','https://media.sabq.org/news/2026/08/132570e8-3f86-4fb3-a5e9-0768cefefee1/w998.webp','/api/media/a2226c0e-e98e-4d0e-8be3-a13e3512ed2e','/api/media/a2226c0e-e98e-4d0e-8be3-a13e3512ed2e?variant=thumbnail','رعاية ماسية لـ"الماجدية" في معرض العقارات الفاخرة السعودي 2026 بلندن',998,544,'valid','published','archived','valid',91,'ed1ef6f8eb2d4ad2341338e1d1b965abb5f833b5226467066e788c7e1552545b','dc7ac8402d524eb59eb286290def739a60209d34e358431da4eaf29202282414','محدّث','2026-08-10T16:33:42.762Z','2026-10-07T20:24:28.158Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الثقافة والفنون","الاقتصاد والأسواق"]','["السفر والسياحة","الثقافة والفنون","الاقتصاد والأسواق"]','classified','','[{"category":"الاقتصاد","score":5.5},{"category":"أخبار السعودية","score":3},{"category":"الرياضة","score":1.5}]','Active','2026-10-07T19:06:49.313Z',200,72,0,'source_article_available','',NULL,NULL,'body:40a2c4989b1492b4e3ff46d8898c5c246745ffb861ed6e42feb9c6ad3dc1ac65','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ebbf5149-d8c5-459a-b411-0c205c134ce2','news-ebbf5149-d8c5-459a-b411-0c205c134ce2','وفد رفيع من النيجر يُثمّن دور الندوة العالمية للشباب الإسلامي في خدمة المجتمع','وفد رفيع من النيجر يثمن دور الندوه العالميه للشباب الاسلامي في خدمه المجتمع','أشاد وفد رفيع المستوى من كبار المسؤولين في جمهورية النيجر بجهود الندوة العالمية للشباب الإسلامي، مُثمِّنًا ما تنفذه من برامج ومشروعات تنموية وإنسانية في البلاد، وذلك خلال حضوره مراسم توزيع مئات السلال الغذائية على الفقراء والمحتاجين.','["وأكد أعضاء الوفد أهمية تعزيز التعاون والعمل المشترك بين الندوة العالمية والجهات الحكومية النيجرية، بما يُسهم في دعم البرامج الإنسانية والتنموية وتوسيع نطاق الاستفادة منها.","وضمّ الوفد كلاً من: السيد إنسا حسن، مدير منظمات وجمعيات التنمية بوزارة الداخلية، والسيد ثالث إبراهيم، مستشار وزير الداخلية المكلف بالمنظمات والجمعيات المحلية والخارجية، والسيد محمد عتوري، المستشار الخاص لرئيس الجمهورية، والسيد عبد الله حسن، نائب في مجلس إعادة التأسيس وعضو لجنة العدل وحقوق الإنسان.","من جانبه، استعرض مدير مكتب الندوة العالمية في النيجر، الأستاذ محمد نور، أبرز المشروعات التنموية والإنسانية التي تنفذها الندوة في مختلف المجالات، موضحًا أهدافها في خدمة المجتمع النيجري وتحسين الظروف المعيشية للفئات المستفيدة.","وأشاد مدير المكتب بالجهود الإنسانية المتواصلة التي تبذلها المملكة العربية السعودية، حكومةً وشعبًا، في دعم المبادرات والبرامج الإنسانية والتنموية التي ترعاها المملكة في النيجر."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/nhj137m','https://sabq.org/article/nhj137m','','https://sabq.org/article/nhj137m','صحيفة سبق','السعودية','2026-08-10T02:47:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T16:33:44.278Z','https://media.sabq.org/news/2026/08/ce08b242-a6a7-4f3a-9638-42f7eafab4f5/w1080.webp','/api/media/ebbf5149-d8c5-459a-b411-0c205c134ce2','/api/media/ebbf5149-d8c5-459a-b411-0c205c134ce2?variant=thumbnail','وفد رفيع من النيجر يُثمّن دور الندوة العالمية للشباب الإسلامي في خدمة المجتمع',1080,608,'valid','published','archived','valid',91,'c82b93aadfa6e626cc1bef5e628d14c9ba1fccbac83e63b79b30fbb593bdeb77','b2a1c7efef6666540123f4165518992adf50b9cbaf1a077699b132c40597c5bd','محدّث','2026-08-10T16:33:44.278Z','2026-10-07T19:06:36.462Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إعادة التأسيس وعضو لجنة","وزير الداخلية المكلف بالمنظمات والجمعيات"]','["مجلس إعادة التأسيس وعضو لجنة","وزير الداخلية المكلف بالمنظمات والجمعيات"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"العالم","score":3},{"category":"السياسة","score":1.5}]','Active','2026-10-07T19:06:36.462Z',200,75,0,'source_article_available','',NULL,NULL,'body:09b4e46a2cf6e8b89297df29a9d21d643f8c7efcd1ad14aeeaf34b947e6002a7','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1ce669c8-aaf2-4f59-b828-374ffb7d89ba','news-1ce669c8-aaf2-4f59-b828-374ffb7d89ba','اللعب يصنع التعلم.. مدرسة العقل الأولى قبل الصفوف والامتحانات','اللعب يصنع التعلم مدرسه العقل الاولي قبل الصفوف والامتحانات','يتجاوز اللعب حدود التسلية ليكون الطريق الأول الذي اكتسبت به البشرية مهاراتها؛ فقد تعلّم الأطفال عبر آلاف السنين اللغةَ والحرفةَ وقواعد العيش المشترك وهم يلعبون، قبل أن تظهر المدرسة بصفوفها وامتحاناتها في وقت متأخر من تاريخ الإنسان.','["يقلب عالم النفس الأمريكي بيتر غراي هذه الفكرة في كتابه «الحرية في التعلم» الصادر عام 2013، إذ يرى أن اللعب الحر هو المدرسة الأصلية التي صُمّم الدماغ البشري للتعلم فيها، في مواجهة الاعتقاد السائد بأن التعلم يبدأ حين يجلس الطفل في الصف وينتهي حين يغادره.","ويتتبع غراي حياة الأطفال في عدد من المجتمعات البدائية، فيجد أنهم تعلّموا الصيد وجمع النبات وصناعة الأدوات ومهارات التفاوض باللعب والمراقبة والمحاولة، دون معلم يحدد درساً أو امتحان يقيس النتائج.","ويخلص إلى أن أجيالاً متعاقبة بلغت الكفاءة الكاملة في حياتها بهذه الطريقة وحدها، وأن الصف المدرسي بشكله الحالي اختراع حديث لا يتجاوز عمره قروناً قليلة.","الطفل يلعب كأنه أكبر من عمره فسّر عالم النفس الروسي ليف فيغوتسكي، في أبحاثه خلال عشرينيات القرن الماضي وثلاثينياته، سرَّ هذه القدرة، إذ لاحظ أن الطفل يتصرف داخل اللعب فوق مستوى عمره الفعلي؛ فالطفل الذي يؤدي دور البائع يواجه مهام الحساب والتفاوض والالتزام بقواعد الدور، فيما يضبط المشارك في لعبة جماعية حركته وكلامه وفق قاعدة اتفق عليها رفاقه."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/05irlk4','https://sabq.org/article/05irlk4','','https://sabq.org/article/05irlk4','صحيفة سبق','السعودية','2026-08-10T02:55:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T16:33:44.578Z','https://media.sabq.org/news/2026/08/5b9f5ca8-b451-4fda-8567-ebb98ed229c5/w1600.webp','/api/media/1ce669c8-aaf2-4f59-b828-374ffb7d89ba','/api/media/1ce669c8-aaf2-4f59-b828-374ffb7d89ba?variant=thumbnail','اللعب يصنع التعلم.. مدرسة العقل الأولى قبل الصفوف والامتحانات',1600,1066,'valid','published','archived','valid',56,'008caebb8f37a76db49b84fe22bccc64de863901ce694e312ab9907bc01ba980','758e3f767a4db88e4252401820806c2d5300ac3bfcccf9aa896ba723f1284704','محدّث','2026-08-10T16:33:44.578Z','2026-10-07T19:06:36.480Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"الطاقة والصناعة","score":3},{"category":"التقنية","score":2},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T19:06:36.480Z',200,76,0,'source_article_available','',NULL,NULL,'body:1bf0239e6e13858bafd8173dbd7fbf5a84d409d77d474d484fcbeda761f640ef','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8bb9c038-3ee4-46cd-9e3f-2143ac30d375','news-8bb9c038-3ee4-46cd-9e3f-2143ac30d375','خالد الفقيه يحتفل بزواج نجله الوليد وسط حضور الأهل والأصدقاء','خالد الفقيه يحتفل بزواج نجله الوليد وسط حضور الاهل والاصدقاء','احتفل الأستاذ خالد الفقيه بزواج نجله الوليد، في إحدى قاعات الأفراح بمدينة الرياض، وسط حضور كريم من الأهل والأقارب والأصدقاء، الذين شاركوا الأسرة فرحتها بهذه المناسبة السعيدة، وقدموا التهاني والتبريكات للعريس، متمنين له حياة زوجية هانئة يسودها المودة والاستقرار.','["وعبّر والد العريس عن خالص شكره وتقديره لجميع من شرّفوه بالحضور وشاركوه فرحته، وقدموا التهاني والتبريكات، سائلًا الله أن يديم على الجميع الأفراح والمسرات."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/xgzxht6','https://sabq.org/article/xgzxht6','','https://sabq.org/article/xgzxht6','صحيفة سبق','السعودية','2026-08-10T02:52:00.000Z','2026-08-10T07:10:00.000Z','2026-08-10T16:33:44.630Z','https://media.sabq.org/news/2026/08/63422f0b-43e6-4a83-aaae-399410aa1399/w1280.webp','/api/media/8bb9c038-3ee4-46cd-9e3f-2143ac30d375','/api/media/8bb9c038-3ee4-46cd-9e3f-2143ac30d375?variant=thumbnail','خالد الفقيه يحتفل بزواج نجله الوليد وسط حضور الأهل والأصدقاء',1280,853,'valid','published','archived','valid',35,'47b1ab10fab9299ea8c03f06b27d3dbca4e7aa9feaccdd7da5a27161d4b4eec0','d4414c115de9ec20fcbab052b459d18cfd31922bc0e2daca75980b1bcbc8150b','محدّث','2026-08-10T16:33:44.630Z','2026-10-07T19:06:36.622Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T19:06:36.622Z',200,75,0,'source_article_available','',NULL,NULL,'body:1c001502468c72366ac33235c2a3a8e34b05ad713087f58a0c03a37e1f07e3a2','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6cba581b-db80-4081-8118-459119751827','news-6cba581b-db80-4081-8118-459119751827','«حساب المواطن» يوضح موعد دراسة أهلية التابع بعد إضافته','حساب المواطن يوضح موعد دراسه اهليه التابع بعد اضافته','أوضح برنامج حساب المواطن موعد دراسة أهلية التابع بعد إضافته إلى حساب المستفيد، مبينًا أن توقيت إضافة التابع يحدد الدورة التي ستتم فيها دراسة أهليته. وأضاف أنه إذا تمت إضافة التابع بعد تاريخ 10 من الشهر، فستتم دراسة أهليته ضمن الدورة التي تلي الدورة القادمة.','["أوضح برنامج حساب المواطن موعد دراسة أهلية التابع بعد إضافته إلى حساب المستفيد، مبينًا أن توقيت إضافة التابع يحدد الدورة التي ستتم فيها دراسة أهليته.","وأشار البرنامج، عبر صفحته الرسمية في منصة «إكس»، إلى أنه في حال إضافة التابع قبل تاريخ 10 من الشهر، فستتم دراسة أهليته ضمن دورة الأهلية القادمة.","وأضاف أنه إذا تمت إضافة التابع بعد تاريخ 10 من الشهر، فستتم دراسة أهليته ضمن الدورة التي تلي الدورة القادمة."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/nustj6mke','https://ajel.sa/thehour/nustj6mke','https://ajel.sa/thehour/nustj6mke','https://ajel.sa/thehour/nustj6mke','فريق التحرير','السعودية','2026-08-10T11:04:00.000Z','Wed, 07 Oct 2026 19:05:55 GMT','2026-08-10T18:34:59.073Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/3708-crop-dE6Zh5sZ.jpg','/api/media/6cba581b-db80-4081-8118-459119751827','/api/media/6cba581b-db80-4081-8118-459119751827?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',45,'d3705960b5d222e3b316817ef4fbc2b78c9f231e9362c47ae33861dcbc6975df','9b0ab1f5dcb18a530ecdf57d6774039778f556fa8ccf7b92fbced9cc37ca7f23',NULL,'2026-08-10T18:34:59.073Z','2026-10-07T19:05:56.883Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع"]','[]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T19:05:56.883Z',200,70,0,'source_content_changed','',NULL,NULL,'body:396158be5f861503c426776e4481d4d4ff6c7a2bf941a636fc8788cf72349075','Wed, 07 Oct 2026 19:05:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7e975163-f0f4-493e-a0ae-48b713156adf','news-7e975163-f0f4-493e-a0ae-48b713156adf','مختص يوضح: هل تعد &#8220;القرفة&#8221; والأعشاب بديلًا عن أدوية السكري؟','مختص يوضح هل تعد 8220 القرفه 8221 والاعشاب بديلا عن ادويه السكري','حذّر الدكتور عبدالرحمن بخاري، استشاري أمراض السكري، من الاعتماد على القرفة أو غيرها من الأعشاب كبديل لعلاج مرض السكري، مؤكدًا أهمية الالتزام بالأدوية الموصوفة طبيًا وعدم إيقافها دون استشارة الطبيب.','["وضرب بخاري مثالًا بمريض مصاب بالسكري منذ سنوات، قرر ترك الأدوية والاعتماد على القرفة والأعشاب، قبل أن تكشف التحاليل عن ارتفاع مستوى السكر التراكمي إلى 11.5%، وسكر صائم بلغ 252.","وبعد اقتناع المريض بالعودة إلى العلاج الدوائي، أظهرت التحاليل بعد 3 أشهر تحسنًا ملحوظًا، حيث انخفض السكر التراكمي إلى 6.6%، فيما وصل سكر الصيام إلى 82.","وأكد بخاري أن القرفة والأعشاب لا تُعد بديلًا عن أدوية السكري لمن يحتاج إليها، مشددًا على ضرورة عدم إيقاف العلاج أو تغييره إلا بعد استشارة الطبيب."]','الصحة','','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://shafaq-e.sa/477561.html','https://shafaq-e.sa/477561.html','CBMiRkFVX3lxTE1xTXRjd2tyY0h0RHZNVmZSenJLY1FYeDJMbHdTV3dXcXpSYnVHUkVkYVg0WUZuNnBVTDdUTzVKQi1OcWY2Z1E','CBMiRkFVX3lxTE1xTXRjd2tyY0h0RHZNVmZSenJLY1FYeDJMbHdTV3dXcXpSYnVHUkVkYVg0WUZuNnBVTDdUTzVKQi1OcWY2Z1E','عمر فتحي','السعودية','2026-08-10T11:42:00.000Z','2026-08-10T17:42:00.000Z','2026-08-10T18:39:51.186Z','https://shafaq-e.sa/wp-content/uploads/2026/08/9-8.jpg','/api/media/7e975163-f0f4-493e-a0ae-48b713156adf','/api/media/7e975163-f0f4-493e-a0ae-48b713156adf?variant=thumbnail','صورة عمر فتحي',700,429,'valid','published','archived','valid',89,'433b04eb43ce9b1995dc5043757fccf805055f9df91512a2a1541a0fa2397f52','6aaf2aedbb8b1aa0462204835fe9ddf15bee517dd015c234fcd636bf0bb74515',NULL,'2026-08-10T18:39:51.186Z','2026-10-07T19:06:43.122Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة"]','["الصحة العامة"]','manual_approved','','[]','Active','2026-10-07T19:06:43.122Z',200,72,0,'source_article_available','',NULL,NULL,'body:43635b99d1f5da0ff7b15fb2504bf50c2db8e25787149f99e84478aaa7bf1043','');
