INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('76f13d0a-72c8-4f73-b609-93d054d0eafe','news-76f13d0a-72c8-4f73-b609-93d054d0eafe','لينوفو تستعد للكشف عن حاسوب محمول بشاشة قابلة للتمدد أفقياً','لينوفو تستعد للكشف عن حاسوب محمول بشاشه قابله للتمدد افقيا','تستعد شركة \"لينوفو\" للكشف عن حاسوب محمول جديد من سلسلة ThinkBook المخصصة للأعمال، يتميز بشاشة قابلة للتمدد أفقياً، في أحدث محاولات الشركة لتطوير تصاميم تتجاوز الشكل التقليدي.ونشر موقع Windows Latest صوراً عالية الدقة قال إنها تقدم أول نظرة على الجهاز، الذي يحمل الاسم الرمزي Project Swan، مرجحاً أن يكون لا يزال في مرحلة النموذج الاختباري أو ما قبل الإنتاج،','["تستعد شركة \\\"لينوفو\\\" للكشف عن حاسوب محمول جديد من سلسلة ThinkBook المخصصة للأعمال، يتميز بشاشة قابلة للتمدد أفقياً، في أحدث محاولات الشركة لتطوير تصاميم تتجاوز الشكل التقليدي.ونشر موقع Windows Latest صوراً عالية الدقة قال إنها تقدم أول نظرة على الجهاز، الذي يحمل الاسم الرمزي Project Swan، مرجحاً أن يكون لا يزال في مرحلة النموذج الاختباري أو ما قبل الإنتاج، مع توقعات بأن تقترب الشركة من الكشف الرسمي عنه.مواصفات…","أبرز منتجات لينوفو في MWC 2025عرضت شركة لينوفو (Lenovo) الصينية، مجموعة أفكار تستهدف بها تغيير مفهوم الجمهور عما هو ممكن في سوق الحواسيب الشخصية، وذلك خلال مشاركتها في MWC 2025 في برشلونة.ويضم الجانب الأيسر من الجهاز منفذي USB-C على الأقل، بينما لا تزال المنافذ الموجودة على الجانب الأيمن غير معروفة، لعدم توفر صور واضحة له حتى الآن.أما الجزء الخلفي من الشاشة، فيأتي بتصميم ثنائي اللون، مع فتحات تهوية أو مكونات ظاهرة…","تصميم ينتظر الانتشارتأتي مواصلة لينوفو تجاربها مع الحواسيب ذات الشاشات القابلة للتمدد في وقت يشهد فيه سوق الهواتف القابلة للطي زخماً متزايداً، من دون أن تحظى التصاميم المرنة بالزخم نفسه حتى الآن في سوق الحواسيب المحمولة.وفي سوق الهواتف، تواصل الشركات الكبرى الاستثمار في الأجهزة القابلة للطي، وسط مؤشرات على اتساع المنافسة في هذا القطاع، بينما تستعد شركات أخرى لدخول السوق للمرة الأولى.وحققت سلسلة هواتف سامسونج Galaxy…"]','التقنية','الأعمال','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://asharq.com/technology/192792/%D9%84%D9%8A%D9%86%D9%88%D9%81%D9%88-%D8%AA%D8%B3%D8%AA%D8%B9%D8%AF-%D9%84%D9%84%D9%83%D8%B4%D9%81-%D8%B9%D9%86-%D8%AD%D8%A7%D8%B3%D9%88%D8%A8-%D9%85%D8%AD%D9%85%D9%88%D9%84-%D8%A8%D8%B4%D8%A7%D8%B4%D8%A9-%D9%82%D8%A7%D8%A8%D9%84%D8%A9-%D9%84%D9%84%D8%AA%D9%85%D8%AF%D8%AF-%D8%A3%D9%81%D9%82%D9%8A%D8%A7/','https://asharq.com/technology/192792/%D9%84%D9%8A%D9%86%D9%88%D9%81%D9%88-%D8%AA%D8%B3%D8%AA%D8%B9%D8%AF-%D9%84%D9%84%D9%83%D8%B4%D9%81-%D8%B9%D9%86-%D8%AD%D8%A7%D8%B3%D9%88%D8%A8-%D9%85%D8%AD%D9%85%D9%88%D9%84-%D8%A8%D8%B4%D8%A7%D8%B4%D8%A9-%D9%82%D8%A7%D8%A8%D9%84%D8%A9-%D9%84%D9%84%D8%AA%D9%85%D8%AF%D8%AF-%D8%A3%D9%81%D9%82%D9%8A%D8%A7/','','','','السعودية','2026-08-11T19:50:00.000Z','2026-08-11T22:51:00.000Z','2026-08-12T03:48:44.829Z','https://assets-news.asharq.com/images/articles/1200x630/social-image/pFB6v0SZcC_1786465736.webp','/api/media/76f13d0a-72c8-4f73-b609-93d054d0eafe','/api/media/76f13d0a-72c8-4f73-b609-93d054d0eafe?variant=thumbnail','حاسوب تجريبي ضمن مشروع Project Swan من شركة لينوفو - Windows Latest',1200,630,'valid','published','archived','valid',100,'905ad7236d4a040b0d2fa61071a95d6b49c7c94708922f7bb68212b98a20b75b','18b3e96f0e9764bba64e010285b4c82aeaad3fed3e3605ba7ce9c55ac3858b56',NULL,'2026-08-12T03:48:44.829Z','2026-10-07T21:11:34.161Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["الأعمال","شركة لينوفو للكشف عن حاسوب","الاقتصاد والأسواق","الصين"]','["شركة لينوفو للكشف عن حاسوب","الاقتصاد والأسواق"]','manual_approved','','[]','Updated','2026-10-07T21:11:34.161Z',200,83,0,'source_content_changed','',NULL,NULL,'"mg63hzyfv33t4"','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f8480b39-cd9b-4dfe-9b18-152eb14c5329','news-f8480b39-cd9b-4dfe-9b18-152eb14c5329','الاتحاد يكشف موعد عملية روجر فيرنانديز وجراح الرباط الصليبي','الاتحاد يكشف موعد عمليه روجر فيرنانديز وجراح الرباط الصليبي','أعلن نادي الاتحاد السعودي أن جناحه البرتغالي روجر فيرنانديز سيخضع لعملية جراحية لعلاج إصابته بقطع في الرباط الصليبي الأمامي للركبة اليسرى، يوم 18 أغسطس الجاري، في مدينة ليون الفرنسية.','["وأوضح النادي في بيان نشره عبر حسابه الرسمي على منصة «إكس»، أن العملية ستُجرى تحت إشراف البروفيسور بيرتراند سونيري كوتيه، المتخصص في جراحات الرباط الصليبي.","وأشار البيان إلى أن اللاعب يواصل حالياً برنامجه التأهيلي داخل النادي، تحت إشراف الجهاز الطبي للفريق الأول، في إطار تحضيراته للعملية القادمة.","وكان النادي قد أعلن قبل يومين تعرّض اللاعب البالغ من العمر 20 عاماً للإصابة خلال تدريبات الفريق.","وكان فيرنانديز قد انضم إلى صفوف الاتحاد الموسم الماضي، مرتبطاً مع النادي بعقد يمتد لخمس سنوات."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/o3ot8oq','https://sabq.org/article/o3ot8oq','','https://sabq.org/article/o3ot8oq','صحيفة سبق','السعودية','2026-08-11T09:48:00.000Z','2026-08-11T12:51:00.000Z','2026-08-12T03:49:02.622Z','https://media.sabq.org/news/2026/08/ac58f866-b210-41fd-b162-969f662c63fc/w993.webp','/api/media/f8480b39-cd9b-4dfe-9b18-152eb14c5329','/api/media/f8480b39-cd9b-4dfe-9b18-152eb14c5329?variant=thumbnail','الاتحاد يكشف موعد عملية روجر فيرنانديز وجراح الرباط الصليبي',993,507,'valid','published','archived','valid',52,'a20878ac5266a674ef0114448ff24b7b137d03e9f74591099bcc09a169fab07a','cce5d32c0a28de10647c4ed101a813728d72d92626b66420c5e9dbbcc72276d0','محدّث','2026-08-12T03:49:02.622Z','2026-10-07T21:19:44.091Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الرياضة السعودية"]','["التعليم والتدريب","الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"الصحة","score":1.5},{"category":"التعليم","score":1.5}]','Active','2026-10-07T21:19:44.091Z',200,87,0,'source_article_available','',NULL,NULL,'body:c3eb668ecdf90c23914c47e8a0c82c25dab40bfdd10b60b618e5bb8f3a2b8b7b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('88403118-62f4-41e5-8f63-8db98fcd5688','news-88403118-62f4-41e5-8f63-8db98fcd5688','بأكثر من 130 ألف متخصص.. الرياض تستضيف ملتقى الصحة العالمي أكتوبر المقبل','باكثر من 130 الف متخصص الرياض تستضيف ملتقي الصحه العالمي اكتوبر المقبل','تستعد مدينة الرياض لاستضافة النسخة التاسعة من ملتقى الصحة العالمي تحت شعار “استثمر في الصحة” خلال الفترة من 26 إلى 29 أكتوبر 2026، بمشاركة واسعة من قادة القطاع الصحي والمستثمرين وصنّاع القرار والخبراء من مختلف دول العالم وأبرز الجهات في القطاع الصحي دوليًا ومحليًا، وذلك في مركز الرياض للمعارض والمؤتمرات (ملهم)، برعاية وزارة الصحة ، وتمكين من برنامج تحول…','["ومن المتوقع أن يستقطب الملتقى أكثر من 130 ألف متخصص في الرعاية الصحية، ومشاركة أكثر من 2200 علامة تجارية، إلى جانب مشاركة ما يزيد عن 100 دولة، وما يتجاوز الـ 1000 مستثمر، و500 متحدث وخبير مشارك، إضافة إلى تقديم أكثر من 120 ساعة من برامج التعليم الطبي المستمر الموجهة للممارسين الصحيين، ويستعرض الملتقى أحدث الحلول والابتكارات في عدة مجالات منها: علوم الحياة، والصحة الرقمية، والأدوية والأجهزة، والمواد الاستهلاكية،…","ويتضمن الملتقى 4 منصات رئيسة، تشمل قمّة القادة التي تجمع صناع السياسات وقادة الرعاية الصحية لمناقشة مستقبل القطاع، ومنتدى المستثمرين الهادف إلى تعزيز فرص الاستثمار وبناء الشراكات، ومنتدى الصحة الرقمية لاستعراض أحدث الابتكارات والتحول الرقمي في الرعاية الصحية، إضافة إلى منتدى التميز الطبي الذي يركز على تطوير الكفاءات الصحية، والطب الشخصي، والتمريض، وممارسات المختبرات السريرية.","ويأتي تنظيم النسخة التاسعة امتدادًا للنجاحات التي حققها الملتقى في دوراته السابقة، حيث شهدت النسخة الماضية توقيع اتفاقيات واستثمارات تجاوزت قيمتها 133 مليار ريال، مما يجعل الملتقى الوجهة الأكثر جذبًا في قطاع الرعاية الصحية العالمي، حيث يجمع قادة القطاعين العام والخاص لتعزيز الاستثمار، واستعراض أحدث الابتكارات الصحية، وبناء شراكات نوعية تسهم في تشكيل مستقبل الرعاية الصحية، بما يرسخ مكانة المملكة الرائدة في الابتكار…"]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/eqiszt559','https://ajel.sa/local/eqiszt559','https://ajel.sa/local/eqiszt559','https://ajel.sa/local/eqiszt559','فريق التحرير','السعودية','2026-08-12T11:39:00.000Z','Wed, 07 Oct 2026 21:07:55 GMT','2026-08-12T18:08:41.364Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/L69hV_hSX67y5Z30.jpg','/api/media/88403118-62f4-41e5-8f63-8db98fcd5688','/api/media/88403118-62f4-41e5-8f63-8db98fcd5688?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',54,'6467256e963adfc0c4fe10f461aea6faa498872357edb5c4c9cdeba8300c231c','ae80d6866fea1f1fe89accf3119bdac27c9b77f3453baa29e2a3decc6a1be411',NULL,'2026-08-12T18:08:41.364Z','2026-10-07T21:07:57.487Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي","الرياض"]','["الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":3},{"category":"الصحة","score":3},{"category":"العالم","score":3}]','Updated','2026-10-07T21:07:57.487Z',200,83,0,'source_content_changed','',NULL,NULL,'body:10e8e4dca14a041c5ece68cbd2f66f3c782633c1506e7fd5d46bb3e26e54c819','Wed, 07 Oct 2026 21:07:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('71801f79-d3f3-4d3d-aae6-024de59cf8dd','news-71801f79-d3f3-4d3d-aae6-024de59cf8dd','السفير الدوسري يبحث العلاقات الثنائية مع رئيس الوزراء اللبناني السابق','السفير الدوسري يبحث العلاقات الثنائيه مع رئيس الوزراء اللبناني السابق','التقى سفير خادم الحرمين الشريفين لدى لبنان ، فهد بن عبدالرحمن الدوسري، اليوم الأربعاء، برئيس الوزراء اللبناني السابق تمام سلام في بيروت . وجرى خلال اللقاء استعراض العلاقات الثنائية بين المملكة العربية السعودية ولبنان، إلى جانب مناقشة التطورات السياسية في لبنان والمنطقة.','["التقى سفير خادم الحرمين الشريفين لدى لبنان ، فهد بن عبدالرحمن الدوسري، اليوم الأربعاء، برئيس الوزراء اللبناني السابق تمام سلام في بيروت .","وجرى خلال اللقاء استعراض العلاقات الثنائية بين المملكة العربية السعودية ولبنان، إلى جانب مناقشة التطورات السياسية في لبنان والمنطقة.","يأتي هذا اللقاء في إطار حرص المملكة على تعزيز التعاون مع لبنان ودعم الاستقرار الإقليمي."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/wojsygmh9','https://ajel.sa/local/wojsygmh9','https://ajel.sa/local/wojsygmh9','https://ajel.sa/local/wojsygmh9','فريق التحرير','السعودية','2026-08-12T11:43:00.000Z','Wed, 07 Oct 2026 21:07:59 GMT','2026-08-12T18:08:41.709Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/0-crop-HGiNsT0l.jpg','/api/media/71801f79-d3f3-4d3d-aae6-024de59cf8dd','/api/media/71801f79-d3f3-4d3d-aae6-024de59cf8dd?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',88,'1e2af261704d75e585aa43b90fc2bde02888825f44a21ea3bc583fc059ef2925','30ee5595749c105bd9b8e96894eebec273819c5ec83c4cfb262b7ddb10f8fbc3',NULL,'2026-08-12T18:08:41.709Z','2026-10-07T21:08:00.818Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["خادم الحرمين الشريفين لدى لبنان","رئيس الوزراء اللبناني السابق صحيفة","لبنان"]','["خادم الحرمين الشريفين لدى لبنان","رئيس الوزراء اللبناني السابق صحيفة"]','classified','','[{"category":"أخبار السعودية","score":7},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"المناطق","score":0}]','Updated','2026-10-07T21:08:00.818Z',200,81,0,'source_content_changed','',NULL,NULL,'body:8c622b0e8f7cea6bd54aaaa2635e60b060e4e5d0247574b0313e6013f83b0359','Wed, 07 Oct 2026 21:07:59 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a6299bb7-1620-42c0-a760-dec24c274506','news-a6299bb7-1620-42c0-a760-dec24c274506','اختتام ورشة دراسة مشاريع الربط المائي بين دول الخليج في الدمام','اختتام ورشه دراسه مشاريع الربط المائي بين دول الخليج في الدمام','وأوضح الرئيس التنفيذي لهيئة الربط الكهربائي الخليجي، المهندس أحمد بن علي الإبراهيم، أهمية الاستفادة من تجربة الربط الكهربائي الخليجي في دراسة الربط المائي، بما يعزز استدامة الإمدادات في المنطقة.','["اختتمت الأمانة العامة لمجلس التعاون لدول الخليج العربية ، بالتعاون مع هيئة الربط الكهربائي الخليجي، اليوم الأربعاء، أعمال ورشة العمل المشتركة حول دراسة إمكانية بناء مشاريع للربط المائي بين دول المجلس، وذلك في المقر الرئيسي للهيئة بمدينة الدمام .","شارك في الورشة ممثلو الجهات المختصة والخبراء في مجالات المياه والبنية التحتية والأمن المائي، واستمرت لمدة يومين. وركزت أعمال الورشة على استعراض مخرجات المرحلة الأولى من الدراسة، وتشخيص البنية التحتية لإمدادات المياه والاحتياجات الفعلية للدول الأعضاء، بالإضافة إلى المتطلبات الفنية والبيانات اللازمة لاستكمال الدراسة.","تضمنت أعمال اليوم الثاني جولة في مركز التحكم ومركز إدارة صحة الأصول، حيث اطلع المشاركون على أحدث التقنيات وخطط الهيئة المستقبلية. وأشار المشاركون إلى أن نتائج الدراسة ستسهم في الوصول إلى خيارات عملية وحلول قابلة للتنفيذ، إضافة إلى إعداد خارطة طريق واضحة للربط المائي المشترك."]','الثقافة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/za6ujn167','https://ajel.sa/local/za6ujn167','https://ajel.sa/local/za6ujn167','https://ajel.sa/local/za6ujn167','فريق التحرير','السعودية','2026-08-12T11:45:00.000Z','Wed, 07 Oct 2026 21:07:54 GMT','2026-08-12T18:08:41.941Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-08/source-QCuQLF24.jpg','/api/media/a6299bb7-1620-42c0-a760-dec24c274506','/api/media/a6299bb7-1620-42c0-a760-dec24c274506?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',45,'ac9645ab116d17f4ff775c145c346eb5325f51ee65b17d927ea9710e6c06f890','cfe5d1052e6c1aec7628a0b051cf40344e98a053ae40eb347d08dc8c6ae43630',NULL,'2026-08-12T18:08:41.941Z','2026-10-07T21:07:56.353Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الربط الكهربائي الخليجي اليوم","الصحة العامة","الثقافة والفنون","الدمام","الخليج العربي"]','["هيئة الربط الكهربائي الخليجي اليوم","الصحة العامة","الثقافة والفنون","الخليج العربي"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"الثقافة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T21:07:56.353Z',200,82,0,'source_content_changed','',NULL,NULL,'body:9af20ecc912494f1bbb527dc06bf594168c8b1090979dc6dd20150e5c6a6e6b6','Wed, 07 Oct 2026 21:07:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5b5ac097-af2f-444e-baa3-80a302011a93','news-5b5ac097-af2f-444e-baa3-80a302011a93','محافظ الطائف يزور مصنع ومزرعة الكمال السياحية لتعزيز التجربة السياحية','محافظ الطائف يزور مصنع ومزرعه الكمال السياحيه لتعزيز التجربه السياحيه','وأشاد سمو محافظ الطائف بما شاهده من جهود في توظيف المقومات الزراعية والسياحية، مؤكدًا أهمية تطوير المشروعات النوعية والاستفادة من مزايا المحافظة لإثراء التجربة السياحية ودعم المنتجات المحلية.','["زار صاحب السمو الملكي الأمير فواز بن سلطان بن عبدالعزيز، محافظ الطائف ، اليوم مصنع ومزرعة الكمال السياحية بالمحافظة، في إطار اهتمامه بالاطلاع على المشروعات السياحية والزراعية ودورها في تنويع الوجهات وتعزيز المقومات السياحية للطائف.","وتجوّل سموه في مرافق المزرعة، واطّلع على المساحات الزراعية والمنتجات المحلية والمرافق المهيأة لاستقبال الزوار، مستمعًا إلى شرح حول الأنشطة الزراعية والسياحية والترفيهية التي تستفيد من طبيعة الطائف ومناخها المميز.","كما شملت الزيارة مصنع الورد الطائفي، حيث اطلع الأمير فواز على آليات العمل ومراحل تصنيع المنتجات العطرية، بدءًا من استقبال الورد، مرورًا بعمليات الإنتاج والتعبئة، وصولًا إلى المنتجات النهائية."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/tourism/o00mwku4k','https://ajel.sa/tourism/o00mwku4k','https://ajel.sa/tourism/o00mwku4k','https://ajel.sa/tourism/o00mwku4k','فريق التحرير','السعودية','2026-08-12T11:41:00.000Z','Wed, 07 Oct 2026 21:07:49 GMT','2026-08-12T18:08:42.036Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-08/source-eZrwLTv8.jpg','/api/media/5b5ac097-af2f-444e-baa3-80a302011a93','/api/media/5b5ac097-af2f-444e-baa3-80a302011a93?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',48,'ebca1d011e6f0706750d2efd5bd6b2b42864e2123eca01c805291efc5ad86ced','233db450bc89d49de0d73b65bebec5bb6618ef653e22ecc001e9b44b741b59e9',NULL,'2026-08-12T18:08:42.036Z','2026-10-07T21:07:54.053Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ"]','["الطقس والمناخ"]','manual_approved','below_category_threshold','[{"category":"الطاقة والصناعة","score":3},{"category":"المجتمع","score":1.5},{"category":"الصحة","score":1.5}]','Updated','2026-10-07T21:07:54.053Z',200,84,0,'source_content_changed','',NULL,NULL,'body:a964f9ef0a26573f357c7c002bd0ceb0913e88729aba829eae834e5d26f1adea','Wed, 07 Oct 2026 21:07:49 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('70e568d9-e054-4e22-920f-71074a2bf651','news-70e568d9-e054-4e22-920f-71074a2bf651','محلل: نتنياهو يحاول تجنب الصدام مع ترامب قبل الانتخابات','محلل نتنياهو يحاول تجنب الصدام مع ترامب قبل الانتخابات','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية قال المحلل السياسي عصمت منصور ، إن رئيس وزراء الاحتلال بنيامين نتنياهو يحاول تجنب الصدام مع الرئيس الأمريكي دونالد ترامب قبل الانتخابات رغم المماطلة في تنفيذ خطة السلام في غزة .','["قال المحلل السياسي عصمت منصور ، إن رئيس وزراء الاحتلال بنيامين نتنياهو يحاول تجنب الصدام مع الرئيس الأمريكي دونالد ترامب قبل الانتخابات رغم المماطلة في تنفيذ خطة السلام في غزة .","وأضاف منصور عبر \"العربية إف إم\"، أن رئيس وزراء الاحتلال يواجه مشكلة لأن الثقة التي يمنحها الرئيس الأمريكي لرئيس وزراء الاحتلال تؤثر على موقفه أمام الناخبين.","وأكمل المحلل السياسي، أنَّ موافقة نتنياهو على مطالب ترامب سيواجه مشكلة أمام ناخبيه خصوصا من ائتلافه، ولو رفض سيواجه مشكلة مع الإدارة الأمريكية، مشيرا إلى أن نتنياهو يدرك كيف يقرأ مسار الإدارة الأمريكية."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/b8jch51ih','https://ajel.sa/international/b8jch51ih','https://ajel.sa/international/b8jch51ih','https://ajel.sa/international/b8jch51ih','فريق التحرير','السعودية','2026-08-12T11:49:00.000Z','Wed, 07 Oct 2026 21:02:00 GMT','2026-08-12T18:08:42.378Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D9%86%D8%AA%D9%86%D9%8A%D8%A7%D9%87%D9%88-%D9%88%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-2-QXwDEKRj.jpg','/api/media/70e568d9-e054-4e22-920f-71074a2bf651','/api/media/70e568d9-e054-4e22-920f-71074a2bf651?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',94,'1c67c5b1f1d3dfda3709f173d9dda06d343bfec8adfaa70d2d8a4e323d77445f','1ef043977758b8646d57d6044df54720c56210fb719ab66f1023bf337031f3b5',NULL,'2026-08-12T18:08:42.378Z','2026-10-07T21:02:04.507Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس وزراء الاحتلال بنيامين نتنياهو","السياسة والعلاقات الدولية","غزة"]','["رئيس وزراء الاحتلال بنيامين نتنياهو","السياسة والعلاقات الدولية"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Updated','2026-10-07T21:02:04.507Z',200,82,0,'source_content_changed','',NULL,NULL,'body:59d0f0cd428c41bf2367e11a7f6d128b4e90008988ea338862700a66dd3ebdce','Wed, 07 Oct 2026 21:02:00 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('036eb83c-e74c-4fed-9df4-c09e88c476e3','news-036eb83c-e74c-4fed-9df4-c09e88c476e3','مانشستر سيتي يتعاقد مع الحارس الأرجنتيني جيرونيمو رولي','مانشستر سيتي يتعاقد مع الحارس الارجنتيني جيرونيمو رولي','تعاقد نادي مانشستر سيتي الإنجليزي مع حارس المرمى الدولي الأرجنتيني جيرونيمو رولي ، قادمًا من أولمبيك مارسيليا الفرنسي، بعقد يمتد عامين حتى 2028م. ويعود رولي -البالغ من العمر 34 عامًا- إلى مانشستر سيتي بعد تجربة سابقة مع النادي خلال موسم 2016 - 2017م، دون أن يسجل ظهورًا مع الفريق الأول، ويمتلك مسيرة احترافية شملت أندية ( ريال سوسيداد و فياريال الإسبانيين،…','["تعاقد نادي مانشستر سيتي الإنجليزي مع حارس المرمى الدولي الأرجنتيني جيرونيمو رولي ، قادمًا من أولمبيك مارسيليا الفرنسي، بعقد يمتد عامين حتى 2028م.","ويعود رولي -البالغ من العمر 34 عامًا- إلى مانشستر سيتي بعد تجربة سابقة مع النادي خلال موسم 2016 - 2017م، دون أن يسجل ظهورًا مع الفريق الأول، ويمتلك مسيرة احترافية شملت أندية ( ريال سوسيداد و فياريال الإسبانيين، و أياكس الهولندي، و مونبلييه وأولمبيك مارسيليا الفرنسيين) وتوج خلالها بلقب الدوري الأوروبي مع فياريال خلال موسم 2020 - 2021م."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/supmlqbj2','https://ajel.sa/sports/supmlqbj2','https://ajel.sa/sports/supmlqbj2','https://ajel.sa/sports/supmlqbj2','فريق التحرير','السعودية','2026-08-12T11:50:00.000Z','Wed, 07 Oct 2026 21:07:54 GMT','2026-08-12T18:08:42.627Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%85%D8%A7%D9%86-%D8%B3%D9%8A%D8%AA%D9%8A-PIq9z3z0.jpg','/api/media/036eb83c-e74c-4fed-9df4-c09e88c476e3','/api/media/036eb83c-e74c-4fed-9df4-c09e88c476e3?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',52,'b0c0e73d90d955821a26f77e673b989e5cafa990695cc7f971c6b0002f8cdcf2','1c10da862c60fa73f07ead7c6037883f9e17a70d8792a81a7b327423e01d8fde',NULL,'2026-08-12T18:08:42.627Z','2026-10-07T21:07:56.264Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T21:07:56.264Z',200,81,0,'source_content_changed','',NULL,NULL,'body:9bc1861e0f1ba66bc7aef90650a6ae4cd21cb7253e46058e01dee25a4c5a7b3c','Wed, 07 Oct 2026 21:07:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2d9b2650-1c95-4f3a-ab97-0133720fe790','news-2d9b2650-1c95-4f3a-ab97-0133720fe790','القوات اليمنية: قتلى حوثيين في استهدافات بالطيران المسير شمال الضالع','القوات اليمنيه قتلي حوثيين في استهدافات بالطيران المسير شمال الضالع','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية أعلنت القوات اليمنية سقوط قتلى من الحوثيين في استهدافات بالطيران المسير شمال الضالع .','["أعلنت القوات اليمنية سقوط قتلى من الحوثيين في استهدافات بالطيران المسير شمال الضالع .","وكان قائد عسكري يمني، أعلن أن مليشيات الحوثي استهدفت ميناء المخا بصاروخين باليستيين، في سياق محاولات الميليشيات تهديد المصالح اليمنية، وفق \" الحدث \".","وأكد رئيس مجلس القيادة الرئاسي اليمني رشاد العليمي على أهمية تحويل جرائم ميليشيا الحوثي إلى ملفات قانونية وقضائية مكتملة لضمان الحقوق ومحاسبة مرتكبيها."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/oefu4vypn','https://ajel.sa/international/oefu4vypn','https://ajel.sa/international/oefu4vypn','https://ajel.sa/international/oefu4vypn','فريق التحرير','السعودية','2026-08-12T11:50:00.000Z','Wed, 07 Oct 2026 21:02:08 GMT','2026-08-12T18:08:43.145Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-rpxIQaxj.png','/api/media/2d9b2650-1c95-4f3a-ab97-0133720fe790','/api/media/2d9b2650-1c95-4f3a-ab97-0133720fe790?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',46,'5294f0551b994c61f75f0670dd00f24c4e0c2c6ec47ce88622e3ea8e685353ab','eb981e7760c76749d53f823406364d2eee938be30e468288e888857d628fcec9',NULL,'2026-08-12T18:08:43.145Z','2026-10-07T21:02:09.830Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس القيادة الرئاسي اليمني رشاد","رئيس مجلس القيادة الرئاسي اليمني","السفر والسياحة","اليمن"]','["مجلس القيادة الرئاسي اليمني رشاد","رئيس مجلس القيادة الرئاسي اليمني","السفر والسياحة"]','manual_approved','below_category_threshold','[{"category":"السيارات","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T21:02:09.830Z',200,81,0,'source_content_changed','',NULL,NULL,'body:60daa421b965d75235af38f6ea7ba06aa6affa44500255190afe5cb79033310d','Wed, 07 Oct 2026 21:02:08 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('16c66c6e-4c4d-4ea7-a9f4-132b85766e10','news-16c66c6e-4c4d-4ea7-a9f4-132b85766e10','مدير السلك الدبلوماسي بالخارجية يتسلم أوراق اعتماد سفيرة الدنمارك بالمملكة','مدير السلك الدبلوماسي بالخارجيه يتسلم اوراق اعتماد سفيره الدنمارك بالمملكه','تسلم مدير السلك الدبلوماسي ب وزارة الخارجية ، علي بن عبدالله الشهري، أوراق اعتماد سفيرة الدنمارك ب المملكة . وكتب الحساب الرسمي لوزارة الخارجية على منصة «إكس»، «نيابةً عن وزير الخارجية، تسلم مدير عام الإدارة العامة لشؤون السلك الدبلوماسي، علي بن عبدالله الشهري، نسخة من أوراق اعتماد سفيرة مملكة الدنمارك المعّينة لدى المملكة السيدة ميريته يول».','["تسلم مدير السلك الدبلوماسي ب وزارة الخارجية ، علي بن عبدالله الشهري، أوراق اعتماد سفيرة الدنمارك ب المملكة ."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/0ktxjvkq7','https://ajel.sa/local/0ktxjvkq7','https://ajel.sa/local/0ktxjvkq7','https://ajel.sa/local/0ktxjvkq7','فريق التحرير','السعودية','2026-08-12T11:53:00.000Z','Wed, 07 Oct 2026 21:07:53 GMT','2026-08-12T18:08:43.161Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%AF%D9%86%D9%85%D8%A7%D8%B1%D9%83-U2mnlbRj.jpg','/api/media/16c66c6e-4c4d-4ea7-a9f4-132b85766e10','/api/media/16c66c6e-4c4d-4ea7-a9f4-132b85766e10?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',52,'40ba4fb9f0ff9756c0df4576a7305c48955162d0c7bba9ed6d17d622829393f6','e39d9eb9a3a940446ad7f6973e5e539f52b4703b64d5e3d167813a796449684d',NULL,'2026-08-12T18:08:43.161Z','2026-10-07T21:07:55.515Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الخارجية علي بن عبدالله","السياسة والعلاقات الدولية"]','["وزارة الخارجية علي بن عبدالله","السياسة والعلاقات الدولية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"المناطق","score":0}]','Updated','2026-10-07T21:07:55.515Z',200,82,0,'source_content_changed','',NULL,NULL,'body:70b75fd07abf5ab76bddf3e8a47c2540c4104519c6976f11a25adeadbcd4e3c0','Wed, 07 Oct 2026 21:07:53 GMT');
