INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6cfeb3be-4709-49dd-8045-0a6036015936','news-6cfeb3be-4709-49dd-8045-0a6036015936','هواوي تستعد لطرح لون جديد لهاتف Pura X Max القابل للطي','هواوي تستعد لطرح لون جديد لهاتف pura x max القابل للطي','ذكرت تسريبات حديثة أن هواوي تخطط لإضافة لون جديد إلى مجموعة ألوان هاتف Pura X Max القابل للطي، ليعزز بذلك خيارات التصميم المتاحة حالياً للمستخدمين.','["وفقاً لما نشره المسرب عبر منصة Weibo، من المتوقع أن تعلن الشركة قريباً عن لون واحد جديد على الأقل، دون تحديد التفاصيل حول اللون أو موعد الإطلاق الدقيق.","وتنقسم ألوان سلسلة Pura X Max الحالية إلى نمطين: النسخة العادية التي تتوفر بثلاثة ألوان هي Phantom Black وOlive Gold وZero Degree White، وإصدار Collector’s Edition باللونين Interstellar Blue وVibrant Orange مع تصميم فريد للخطوط على الجهة الخلفية يميز هذا الإصدار الاحتفالي.","ولا يستبعد أن تطرح الشركة أكثر من خيار لون جديد استكمالاً لتوجهها السابق، حيث أضافت في وقت سابق للهاتف نفسه درجات Stylish Orange وStylish Purple، ما وفر للمستخدمين تنوعاً أكبر في الألوان.","حتى الآن، لم تعلن هواوي بشكل رسمي عن اللون الجديد أو موعد توفره في الأسواق، لكن من المنتظر أن تظهر تفاصيل إضافية خلال الأسابيع المقبلة، في ظل تحضيرات الشركة لإطلاق عدة أجهزة جديدة خلال الفترة القادمة."]','التقنية','','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://www.tech-wd.com/wd/2026/08/12/%D9%87%D9%88%D8%A7%D9%88%D9%8A-%D8%AA%D8%B3%D8%AA%D8%B9%D8%AF-%D9%84%D8%B7%D8%B1%D8%AD-%D9%84%D9%88%D9%86-%D8%AC%D8%AF%D9%8A%D8%AF-%D9%84%D9%87%D8%A7%D8%AA%D9%81-pura-x-max-%D8%A7%D9%84%D9%82%D8%A7/','https://www.tech-wd.com/wd/2026/08/12/%D9%87%D9%88%D8%A7%D9%88%D9%8A-%D8%AA%D8%B3%D8%AA%D8%B9%D8%AF-%D9%84%D8%B7%D8%B1%D8%AD-%D9%84%D9%88%D9%86-%D8%AC%D8%AF%D9%8A%D8%AF-%D9%84%D9%87%D8%A7%D8%AA%D9%81-pura-x-max-%D8%A7%D9%84%D9%82%D8%A7/','','','فريق التحرير','السعودية','2026-08-12T10:56:00.000Z','2026-08-12T16:56:00.000Z','2026-08-12T18:08:45.209Z','https://www.tech-wd.com/wd/wp-content/uploads/2026/08/huawei-pura-x-max.jpg','/api/media/6cfeb3be-4709-49dd-8045-0a6036015936','/api/media/6cfeb3be-4709-49dd-8045-0a6036015936?variant=thumbnail','Google Icon',1200,675,'valid','published','archived','valid',77,'437b9ef4d82d1e4058c1e0720560dacebcc09665ee3d0d25ec3ba292e17e56a1','c7ba8a0fdd6014694cf072edd4b3eb4909a924fb01d5a935a3b265ef16f64077',NULL,'2026-08-12T18:08:45.209Z','2026-10-07T21:11:10.642Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد"]','[]','manual_approved','','[]','Temporarily Unreachable','2026-10-07T21:11:10.642Z',NULL,74,1,'temporary_network_error: This operation was aborted','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ad0198c6-45c4-4f94-b60a-111b7ebd5a82','news-ad0198c6-45c4-4f94-b60a-111b7ebd5a82','عدد تثبيتات HarmonyOS 6 يقترب من 79 مليون مع استمرار النمو السريع','عدد تثبيتات harmonyos 6 يقترب من 79 مليون مع استمرار النمو السريع','تواصل هواوي تسجيل معدلات نمو قوية لنظام التشغيل HarmonyOS 6، حيث يقترب عدد التثبيتات حالياً من حاجز 79 مليون جهاز.','["وكشفت أرقام مسربة أن عدد الأجهزة التي تعمل بالإصدار الجديد وصل حتى الآن إلى 78.7 مليون، مع متوسط يومي يتراوح بين 170 و180 ألف تثبيت جديد.","وتُظهر البيانات أن معدل التثبيت اليومي للنظام حقق زيادة بنسبة 0.7% يومياً خلال الفترة الأخيرة، مع تسجيل أعلى رقم يومي عند 461 ألف تثبيت، مقابل أدنى معدل يومي بلغ نحو 72 ألف جهاز.","كما تشير الإحصائيات إلى نمو سريع بين مايو ويوليو، حيث تمت إضافة ما يقارب 17 مليون عملية تثبيت خلال هذه الفترة.","وفي ضوء هذا الزخم، تستعد هواوي لإطلاق تحديثات جديدة لمنظومة HarmonyOS، والتي ستدعم شرائح Kirin القادمة لعام 2026 مع تعزيز ميزات الذكاء الاصطناعي والأداء."]','الذكاء الاصطناعي','','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://www.tech-wd.com/wd/2026/08/12/%D8%B9%D8%AF%D8%AF-%D8%AA%D8%AB%D8%A8%D9%8A%D8%AA%D8%A7%D8%AA-harmonyos-6-%D9%8A%D9%82%D8%AA%D8%B1%D8%A8-%D9%85%D9%86-79-%D9%85%D9%84%D9%8A%D9%88%D9%86-%D9%85%D8%B9-%D8%A7%D8%B3%D8%AA%D9%85%D8%B1/','https://www.tech-wd.com/wd/2026/08/12/%D8%B9%D8%AF%D8%AF-%D8%AA%D8%AB%D8%A8%D9%8A%D8%AA%D8%A7%D8%AA-harmonyos-6-%D9%8A%D9%82%D8%AA%D8%B1%D8%A8-%D9%85%D9%86-79-%D9%85%D9%84%D9%8A%D9%88%D9%86-%D9%85%D8%B9-%D8%A7%D8%B3%D8%AA%D9%85%D8%B1/','','','فريق التحرير','السعودية','2026-08-12T10:59:00.000Z','2026-08-12T16:59:00.000Z','2026-08-12T18:08:46.039Z','https://www.tech-wd.com/wd/wp-content/uploads/2026/08/harmonyos-6.jpg','/api/media/ad0198c6-45c4-4f94-b60a-111b7ebd5a82','/api/media/ad0198c6-45c4-4f94-b60a-111b7ebd5a82?variant=thumbnail','Google Icon',1200,675,'valid','published','archived','valid',77,'191df6c75b50f06b4f881965013935e87d010530383ee8de3b9be655fb5079cd','60dcc9af6f6ff971968122928e9dad3bb35b46cca23ed5341067b009a9a07319',NULL,'2026-08-12T18:08:46.039Z','2026-10-07T21:11:10.639Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد"]','[]','manual_approved','','[]','Temporarily Unreachable','2026-10-07T21:11:10.639Z',NULL,74,1,'temporary_network_error: This operation was aborted','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('25fb729c-7064-49a5-9929-1e70aa2dc766','news-25fb729c-7064-49a5-9929-1e70aa2dc766','اقتصادي / وزارة البلديات والإسكان: 45 يومًا على انتهاء المهلة التصحيحية لملاك الأراضي الفضاء لمعالجة المخالفات','اقتصادي وزاره البلديات والاسكان 45 يوما علي انتهاء المهله التصحيحيه لملاك الاراضي الفضاء لمعالجه المخالفات','الرياض 29 صفر 1448 هـ الموافق 12 أغسطس 2026 م واس أكدت وزارة البلديات والإسكان أن المهلة التصحيحية الممنوحة لملاك الأراضي الفضاء تنتهي بعد 45 يومًا، في 15 ربيع الآخر 1448هـ (26 سبتمبر 2026م)، داعيةً الملاك إلى المبادرة بتصحيح أوضاع أراضيهم والالتزام بالاشتراطات والضوابط البلدية المعتمدة قبل انتهاء المهلة.','["وأوضحت الوزارة أن المهلة تستهدف تعزيز مستوى الامتثال في الأراضي الفضاء، ومعالجة الاستخدامات والممارسات المخالفة التي تؤثر في المظهر العام للمدن والمحافظات، ومن أبرزها تجميع مخلفات البناء ونواتج الحفر، واستغلال الأراضي بطرق غير نظامية.","وبيّنت أن الأمانات والبلديات تنفذ أعمال المتابعة والرقابة الميدانية على الأراضي الفضاء في مختلف مناطق المملكة، لرصد المخالفات ومعالجتها وفق الأنظمة والاشتراطات البلدية المعتمدة، بما يسهم في رفع مستوى الامتثال والحد من مظاهر التشوه البصري.","وأشارت الوزارة إلى أن الالتزام بالاشتراطات المنظمة للأراضي الفضاء يسهم في تحسين المشهد الحضري، ورفع جودة البيئة العمرانية، وتعزيز جودة الحياة في المدن والمحافظات.","ودعت ملاك الأراضي الفضاء إلى الاستفادة من الفترة المتبقية من المهلة، والمبادرة بمعالجة أوضاع أراضيهم قبل انتهائها؛ تجنبًا للإجراءات النظامية المترتبة على المخالفات."]','العقارات','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2652157?type=news&uuid=N2652157','https://spa.gov.sa/ar/N2652157?type=news&uuid=N2652157','N2652157','N2652157','','السعودية','2026-08-12T05:10:00.000Z',NULL,'2026-08-12T18:08:48.192Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10594472.jpg','/api/media/25fb729c-7064-49a5-9929-1e70aa2dc766','/api/media/25fb729c-7064-49a5-9929-1e70aa2dc766?variant=thumbnail','اقتصادي / وزارة البلديات والإسكان: 45 يومًا على انتهاء المهلة التصحيحية لملاك الأراضي الفضاء لمعالجة المخالفات',1600,2144,'valid','published','archived','valid',90,'d6298adbc4527ea2763e2e83fac822fd94bf3eeb63781e8c453b6b21d2dd867e','9e0acced6de168ba86f58fa45d4577af88e4f94691fa9c5948cbbcd67400184e',NULL,'2026-08-12T18:08:48.192Z','2026-10-07T21:11:33.519Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البلديات والإسكان","الاقتصاد والأسواق"]','["وزارة البلديات والإسكان","الاقتصاد والأسواق"]','classified','','[{"category":"المناطق","score":4},{"category":"الاقتصاد","score":3},{"category":"أخبار السعودية","score":1.5}]','Active','2026-10-07T21:11:33.519Z',200,87,0,'source_article_available','',NULL,NULL,'body:363167aba52d2b89a85fe8e0b49d5b21ef2bf1cba1e703f93936650e7baa9a77','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e3497421-e852-4ff7-80cc-3d6479b7e52d','news-e3497421-e852-4ff7-80cc-3d6479b7e52d','اقتصادي / نوادر التمور ببريدة.. أصناف نادرة تحفظ ذاكرة النخيل وتستقطب المهتمين','اقتصادي نوادر التمور ببريده اصناف نادره تحفظ ذاكره النخيل وتستقطب المهتمين','بريدة 29 صفر 1448 هـ الموافق 12 أغسطس 2026 م واس تتجلى في كرنفال بريدة للتمور ثروة متنوعة من أصناف التمور التي تزخر بها منطقة القصيم، والتي تتجاوز 100 صنف من التمور، من بينها عدد من الأصناف النادرة التي تحظى باهتمام المزارعين والمهتمين بالتمور؛ لما تتميز به من خصائص في الشكل والطعم واللون، وما تمثله من امتداد للإرث الزراعي المتوارث في المنطقة كنبتة سيف ونبتة','["وتستوقف تلك النوادر زوار الكرنفال بما تحمله من تنوع لافت، إذ يعرض المزارعون أصنافًا محدودة الإنتاج، بعضها لا يُزرع على نطاق واسع، فيما تمثل أخرى أصنافًا محلية قديمة ارتبطت بالمزارع والبيئة الزراعية في المنطقة على مدى عقود.","ويُسهم الكرنفال في التعريف بهذه الأصناف وإبراز قيمتها الزراعية والتراثية، إلى جانب إتاحة الفرصة للمزارعين والمهتمين للتعرف على خصائصها وتبادل الخبرات المتعلقة بزراعتها والعناية بها وطرق حفظها وتسويقها.","ويؤكد حضور نوادر التمور في السوق أهمية المحافظة على التنوع الوراثي للنخيل، بوصفه جزءًا من الثروة الزراعية التي تتمتع بها منطقة القصيم، ورافدًا مهمًّا للتنوع في قطاع التمور، الذي يشهد نموًا متواصلًا في مجالات الإنتاج والتسويق والتصنيع.","وتمثل هذه الأصناف فرصة أمام المزارعين لتوسيع خياراتهم الإنتاجية، وإعادة إحياء بعض الأصناف التي تراجعت زراعتها خلال السنوات الماضية، بما يسهم في المحافظة على الموروث الزراعي وتعزيز استدامته للأجيال القادمة."]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2652096?type=news&uuid=N2652096','https://spa.gov.sa/ar/N2652096?type=news&uuid=N2652096','N2652096','N2652096','','السعودية','2026-08-12T02:21:00.000Z','2026-08-12T03:07:00.000Z','2026-08-12T18:08:48.247Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10594003.jpeg','/api/media/e3497421-e852-4ff7-80cc-3d6479b7e52d','/api/media/e3497421-e852-4ff7-80cc-3d6479b7e52d?variant=thumbnail','اقتصادي / نوادر التمور ببريدة.. أصناف نادرة تحفظ ذاكرة النخيل وتستقطب المهتمين',1600,894,'valid','published','archived','valid',54,'5b9dcea1766e481609dca34004c341e2fd5e32d8115bfd426a3865be689b6939','65cca05ad244bf12416313c35efa9c944987e5a4dc83ff87115578fec8d8aacb','محدّث','2026-08-12T18:08:48.247Z','2026-10-07T21:11:33.551Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","القصيم"]','["الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T21:11:33.551Z',200,87,0,'source_article_available','',NULL,NULL,'body:c0697acbd37cf2f7abf5a21a535d3d81d064a4f60b4be373703075c110285dfd','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8c29b7c6-74c8-4d14-bf27-9be39b9299b3','news-8c29b7c6-74c8-4d14-bf27-9be39b9299b3','علوم وتقنيات / الحكومة الرقمية تعلن ارتفاع مؤشر نضج التجربة الرقمية لعام 2026 إلى (87.06%)','علوم وتقنيات الحكومه الرقميه تعلن ارتفاع مؤشر نضج التجربه الرقميه لعام 2026 الي 87 06','الرياض 29 صفر 1448 هـ الموافق 12 أغسطس 2026 م واس أعلنت هيئة الحكومة الرقمية نتائج مؤشر نضج التجربة الرقمية لعام (2026)، الذي حقق نسبة (87.06%) بمستوى "متقدم"، بعد تقييم شامل لـ(59) منصة رقمية وفق أربعة مناظير رئيسية تضمنت (20) محورًا، تشمل رضا المستفيد وتجربة المستخدم، والتعامل مع الشكاوى، والتقنيات والأدوات؛ بما يدعم تحسين الخدمات الرقمية والارتقاء بتجربة','["وأوضح معالي محافظ هيئة الحكومة الرقمية المهندس أحمد بن محمد الصويان، أن نتائج المؤشر تعكس ما تشهده الخدمات الرقمية في المملكة من تطور متواصل، والتزام الجهات الحكومية بتحسين خدماتها والاستفادة من آراء المستفيدين، بما يسهم في تقديم خدمات رقمية أكثر سهولة وكفاءة وموثوقية، ورفع جودة الحياة وتعزيز كفاءة الأداء الحكومي، مؤكدًا أن هذا التطور يأتي امتدادًا للدعم والتمكين اللذين تحظى بهما منظومة الحكومة الرقمية من خادم…","وسجل المؤشر خلال عام (2026) نموًا مقارنة بنتائج العام السابق، إذ ارتفع عدد المنصات المشمولة بالتقييم إلى (59) منصة، مقابل (50) منصة في عام (2025)، فيما تجاوز عدد المشاركين في استبيان \"قيّم تجربتك الرقمية\" (805,500) ألف مشارك، مقارنة بـ(374) ألف مشارك في العام السابق، بما يعكس اتساع أثر المؤشر ودوره في دعم رحلة التحسين المستمر للخدمات الحكومية الرقمية، كما حقق المؤشر الفرعي للشمولية الرقمية نموًا بنسبة (76.98%) ضمن…","وأظهرت النتائج تميز أعلى (10) منصات رقمية، وجاءت النتائج على النحو الآتي: منصة \"أبشر\" بنسبة (94.38 %)، ومنصة \"اعتماد\" بنسبة (%94.36)، ومنصة \"صناعي\" بنسبة (92.83%), ومنصة \"بلدي\" بنسبة (92.56 %)، ومنصة \"توكلنا\" بنسبة (92.50%)، ومنصة \"مساند\" بنسبة (92.20 %)، وبوابة \"قوى\" بنسبة (92.14 %)، وبوابة \"لوجستي\" بنسبة (91.72 %)، ومنصة \"نما\" بنسبة (91.53 %)، وبوابة \"وزارة السياحة\" بنسبة (91.16 %).","يُذكر أن هيئة الحكومة الرقمية أطلقت مؤشر نضج التجربة الرقمية في عام (2022)؛ لقياس مستوى نضج المنصات والخدمات الرقمية، وتمكين الجهات الحكومية من تطوير خدماتها استنادًا إلى آراء المستفيدين وأفضل الممارسات العالمية، حيث يواصل المؤشر تطوير منهجيته بشكل سنوي بما يواكب التوجهات الحديثة في تصميم التجارب الرقمية وقياسها، وقد انعكس هذا التطور على مكانة المملكة في المؤشرات الدولية، إذ حققت المركز الثاني عالميًا في مؤشر نضج…"]','التقنية','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2652286?type=news&uuid=N2652286','https://spa.gov.sa/ar/N2652286?type=news&uuid=N2652286','N2652286','N2652286','','السعودية','2026-08-12T07:58:00.000Z',NULL,'2026-08-12T18:08:48.302Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10595439.jpeg','/api/media/8c29b7c6-74c8-4d14-bf27-9be39b9299b3','/api/media/8c29b7c6-74c8-4d14-bf27-9be39b9299b3?variant=thumbnail','علوم وتقنيات / الحكومة الرقمية تعلن ارتفاع مؤشر نضج التجربة الرقمية لعام 2026 إلى (87.06%)',1600,3247,'valid','published','archived','valid',99,'673e4fae8b7e3540c22df8ba99ce4254346fe8bf152c8276388d16b6aa77078b','816d391db1f83770c18bdbe9ee09e316ab5890ec4e3afb8ff5dfac065f97b906',NULL,'2026-08-12T18:08:48.302Z','2026-10-07T21:11:30.628Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة السياحة بنسبة","هيئة الحكومة الرقمية المهندس أحمد","السفر والسياحة","التقنية والتحول الرقمي"]','["وزارة السياحة بنسبة","هيئة الحكومة الرقمية المهندس أحمد","السفر والسياحة","التقنية والتحول الرقمي"]','classified','','[{"category":"المجتمع","score":5.5},{"category":"السياسة","score":5},{"category":"التقنية","score":5}]','Active','2026-10-07T21:11:30.628Z',200,88,0,'source_article_available','',NULL,NULL,'body:e891edbdd7494fba23c074d3197f8e749641448f4f73f96657c66b7cfa22047c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a423fd98-ac5f-4009-9209-637278de44aa','news-a423fd98-ac5f-4009-9209-637278de44aa','ما القنوات الناقلة لمباراة الدرعية والأهلي في دوري روشن السعودي 2026-2027؟ وكيف تشاهدها عبر الإنترنت؟','ما القنوات الناقله لمباراه الدرعيه والاهلي في دوري روشن السعودي 2026 2027 وكيف تشاهدها عبر الانترنت','يستضيف الدرعية، نظيره الأهلي، في مواجهة قوية في فاتحة جولات الدوري السعودي وذلك على ملعب الأمير فيصل بن فهد.','["الأهلي يدخل المباراة وعينه على تحقيق الفوز وافتتاح الموسم بشكل رائع لضمان المنافسة على لقب دوري روشن السعودي.","وفي السطور التالية نستعرض لكم القنوات الناقلة لمباراة الدرعية والأهلي في دوري روشن السعودي 2026-2027، وكيف تشاهدها عبر الإنترنت.","موعد مباراة الدرعية والأهلي في دوري روشن السعودي 2026-2027 لحساب الجولة الأولى من المسابقة هو يوم الخميس 13 أغسطس 2026، على استاد الأمير فيصل بن فهد.","وتنطلق صافرة بداية المباراة في التاسعة مساءً بتوقيت السعودية، العاشرة مساءً بتوقيت الإمارات."]','الرياضة','السعودية','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://www.goal.com/ar/%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D9%85%D8%A7-%D8%A7%D9%84%D9%82%D9%86%D9%88%D8%A7%D8%AA-%D8%A7%D9%84%D9%86%D8%A7%D9%82%D9%84%D8%A9-%D9%84%D9%85%D8%A8%D8%A7%D8%B1%D8%A7%D8%A9-%D8%A7%D9%84%D8%AF%D8%B1%D8%B9%D9%8A%D8%A9-%D9%88%D8%A7%D9%84%D8%A7%D9%94%D9%87%D9%84%D9%8A-%D9%81%D9%8A-%D8%AF%D9%88%D8%B1%D9%8A-%D8%B1%D9%88%D8%B4%D9%86-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A-2026-2027-%D9%88%D9%83%D9%8A%D9%81-%D8%AA%D8%B4%D8%A7%D9%87%D8%AF%D9%87%D8%A7-%D8%B9%D8%A8%D8%B1-%D8%A7%D9%84%D8%A7%D9%95%D9%86%D8%AA%D8%B1%D9%86%D8%AA/blt8bc14583b88baa6e','https://www.goal.com/ar/%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D9%85%D8%A7-%D8%A7%D9%84%D9%82%D9%86%D9%88%D8%A7%D8%AA-%D8%A7%D9%84%D9%86%D8%A7%D9%82%D9%84%D8%A9-%D9%84%D9%85%D8%A8%D8%A7%D8%B1%D8%A7%D8%A9-%D8%A7%D9%84%D8%AF%D8%B1%D8%B9%D9%8A%D8%A9-%D9%88%D8%A7%D9%84%D8%A7%D9%94%D9%87%D9%84%D9%8A-%D9%81%D9%8A-%D8%AF%D9%88%D8%B1%D9%8A-%D8%B1%D9%88%D8%B4%D9%86-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A-2026-2027-%D9%88%D9%83%D9%8A%D9%81-%D8%AA%D8%B4%D8%A7%D9%87%D8%AF%D9%87%D8%A7-%D8%B9%D8%A8%D8%B1-%D8%A7%D9%84%D8%A7%D9%95%D9%86%D8%AA%D8%B1%D9%86%D8%AA/blt8bc14583b88baa6e','','','','السعودية','2026-08-12T02:37:00.000Z','Wed, 07 Oct 2026 21:11:54 GMT','2026-08-12T18:08:49.265Z','https://assets.goal.com/images/v3/blt4c55693ebfa71de0/crop/MM5DKMBQGM5DEOBRGQ5G433XMU5DAORSGYYQ====/2263200754.jfif','/api/media/a423fd98-ac5f-4009-9209-637278de44aa','/api/media/a423fd98-ac5f-4009-9209-637278de44aa?variant=thumbnail','team-logo',5003,2814,'valid','published','archived','valid',100,'23c5036097358a23b52f8e8332e87bb3a6e866fa22f998088da264063bb61f7a','a48ec3b90c8f5404c2d429571527cd677834ffb77b4f59ff7b6f786621238589','محدّث','2026-08-12T18:08:49.265Z','2026-10-07T21:11:56.263Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","التقنية والتحول الرقمي"]','["الرياضة السعودية","التقنية والتحول الرقمي"]','manual_approved','','[]','Updated','2026-10-07T21:11:56.263Z