INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5a17e5fc-129b-452d-aa5c-892e89065a6b','news-5a17e5fc-129b-452d-aa5c-892e89065a6b','سياحة وترفيه / صيف 2026.. جدة تتصدر الوجهات السياحية البحرية على البحر الأحمر','سياحه وترفيه صيف 2026 جده تتصدر الوجهات السياحيه البحريه علي البحر الاحمر','جدة 29 صفر 1448 هـ الموافق 12 أغسطس 2026 م واس على ضفاف البحر الأحمر، حيث تتعانق زرقة المياه مع امتداد الأفق، ترسم محافظة جدة في صيف 2026م مشهدًا سياحيًا نابضًا بالحياة، وتفتح لزوارها أبواب البحر على تجارب تتجاوز الشاطئ إلى عالم من الرحلات والرياضات المائية والغوص والاستكشاف؛ فيما تتناثر الجزر وسط المياه كأنها عقد من اللآلئ يحتضنه البحر، وتحف بها الشعاب المر','["وتعزز جدة مكانتها بوصفها بوابةً رئيسة للسياحة والترفيه البحري على ساحل البحر الأحمر، مستندةً إلى تنوع شواطئها ومواقعها البحرية، وتنامي الرحلات والأنشطة والرياضات المائية، لتفتح أمام الزوار آفاقًا واسعة من الترفيه والرياضات البحرية للغوص والاستكشاف والمغامرة.","وتشهد 13 شاطئًا وموقعًا بحريًا نشاطًا متزايدًا، وسط منظومة ميدانية تضم 34 مشرفًا ميدانيًا و66 منقذًا ومنقذة، للإسهام في تعزيز سلامة مرتادي المواقع البحرية ورفع مستوى الجاهزية، بما يدعم جودة تجربة الزائر ويواكب الإقبال على الأنشطة الساحلية والبحرية.","وتتنوع الخيارات المتاحة أمام الزوار بين أربع رياضات وتجارب بحرية متنوعة، إلى جانب الرحلات بالقوارب إلى الجزر ومواقع الشعاب المرجانية، بما يتيح استكشاف جانب من التنوع الطبيعي الذي يتميز به البحر الأحمر، وممارسة الأنشطة المائية في بيئة تجمع الترفيه والرياضة والطبيعة.","وفي إطار تنظيم السياحة الساحلية وتمكينها، تسهم الهيئة السعودية للبحر الأحمر في تطوير وتنظيم الأنشطة السياحية الساحلية، من خلال الأطر التنظيمية والتراخيص ذات الصلة، بما يدعم جودة التجارب البحرية، ويرفع مستوى الجاهزية والسلامة، ويعزز نمو القطاع السياحي الساحلي واستدامته."]','أخبار السعودية','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2652547?type=news&uuid=N2652547','https://spa.gov.sa/ar/N2652547?type=news&uuid=N2652547','N2652547','N2652547','','السعودية','2026-08-12T12:44:00.000Z','2026-08-09T04:47:00.000Z','2026-08-12T18:08:49.387Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10597345.jpg','/api/media/5a17e5fc-129b-452d-aa5c-892e89065a6b','/api/media/5a17e5fc-129b-452d-aa5c-892e89065a6b?variant=thumbnail','سياحة وترفيه / صيف 2026.. جدة تتصدر الوجهات السياحية البحرية على البحر الأحمر',1600,898,'valid','published','archived','valid',95,'b8550ddc62b34fc650de7979bf21ef16cff7069a6baa77f1e6a02ce093bbb624','9f14030358958c1f655fc491b61ef5b1b2adce9d0ad061c90662d4e49c22f694',NULL,'2026-08-12T18:08:49.387Z','2026-10-07T21:07:55.555Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الرياضة السعودية","جدة","الرياض"]','["السفر والسياحة","الرياضة السعودية"]','classified','','[{"category":"السفر","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T21:07:55.555Z',200,79,0,'source_article_available','',NULL,NULL,'body:ef93150304ca70111629a1ecc399c04fce8918613b0a40be3f977efe0790cb67','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0042e3ff-266f-4b70-839f-6bab0bd6e506','news-0042e3ff-266f-4b70-839f-6bab0bd6e506','اقتصادي / من المزرعة إلى المتسوق.. كرنفال بريدة الدولي للتمور ينظم رحلة تسويق التمور','اقتصادي من المزرعه الي المتسوق كرنفال بريده الدولي للتمور ينظم رحله تسويق التمور','بريدة 29 صفر 1448 هـ الموافق 12 أغسطس 2026 م واس ينظم كرنفال بريدة الدولي للتمور رحلة تسويق المحصول من المزرعة إلى المتسوق، عبر منظومة تستقبل إنتاج المزارعين، وتنظم عرضه وتداوله، بما يسهم في انسيابية حركة البيع خلال الموسم.','["وتبرز أهمية هذه المنظومة في منطقة القصيم التي تضم نحو 11 مليون نخلة، بإنتاج يتجاوز 580 ألف طن من التمور، فيما يزيد عدد أصنافها على 100 نوع، مlا يعكس حجم قطاع النخيل والتمور في المنطقة وتنوع إنتاجه.","وتبدأ رحلة التسويق مع وصول المركبات المحملة بالتمور قبل شروق الشمس إلى موقع الكرنفال، حيث تُنظم حركة دخولها وانتقالها إلى مواقع العرض والبيع، بما ييسر تداول الكميات الواردة ويواكب الحركة اليومية للسوق.","وتمثل البورصة اليومية للتمور محورًا رئيسًا في هذه الرحلة، إذ يلتقي فيها المزارعون والمسوقون والتجار والمتسوقون، وتُعرض من خلالها الأصناف والكميات الواردة، بما يتيح للمزارعين تسويق محاصيلهم، ويمنح المتسوقين فرصة الاطلاع على المعروض والمفاضلة بين الأصناف.","وتساند حركة التداول خدمات تشمل تنظيم مواقع العرض، وإدارة حركة الدخول والخروج، وتنسيق استقبال التمور، لتتكامل مراحل الرحلة من وصول المحصول إلى السوق حتى انتقاله إلى المتسوق ضمن مسار منظم يخدم المزارعين ويرفع فاعلية تسويق التمور."]','الاقتصاد','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2652333?type=news&uuid=N2652333','https://spa.gov.sa/ar/N2652333?type=news&uuid=N2652333','N2652333','N2652333','','السعودية','2026-08-12T08:56:00.000Z','2026-08-04T07:08:00.000Z','2026-08-12T18:08:49.394Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10595947.jpeg','/api/media/0042e3ff-266f-4b70-839f-6bab0bd6e506','/api/media/0042e3ff-266f-4b70-839f-6bab0bd6e506?variant=thumbnail','اقتصادي / من المزرعة إلى المتسوق.. كرنفال بريدة الدولي للتمور ينظم رحلة تسويق التمور',1600,2401,'valid','published','archived','valid',88,'5b08e7f2da2bbd26ca4b88371345d5b90133d1f452353b8398289cd3f0869185','49bce22a19385f17b0ad2304da9499f063a08bcb19b81871d05300db6423c306',NULL,'2026-08-12T18:08:49.394Z','2026-10-07T21:11:32.225Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس ا في هذه الرحلة","الاقتصاد والأسواق","القصيم"]','["رئيس ا في هذه الرحلة","الاقتصاد والأسواق"]','classified','','[{"category":"السيارات","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T21:11:32.225Z',200,87,0,'source_article_available','',NULL,NULL,'body:fc7a7a710748370657d2ea6ad840dff67534bb9fc7e3773c54c18b7e2c591e9f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ce6f6ed8-b91b-47f5-9c36-b8e08a322e31','news-ce6f6ed8-b91b-47f5-9c36-b8e08a322e31','كيف تُطعم هولندا العالم؟','كيف تطعم هولندا العالم','رغم أن مساحة هولندا أصغر من الولايات المتحدة الأميركية بنحو 270 مرة، ورغم مناخها البارد، فإنها نجحت بفضل التكنولوجيا والتخطيط في أن تصبح ثاني أكبر مُصدّر للغذاء في العالم من حيث القيمة بعد أميركا.','["رغم أن مساحة هولندا أصغر من الولايات المتحدة الأميركية بنحو 270 مرة، ورغم مناخها البارد، فإنها نجحت بفضل التكنولوجيا والتخطيط في أن تصبح ثاني أكبر مُصدّر للغذاء في العالم من حيث القيمة بعد أميركا. تبنت هولندا توجهاً وطنياً نحو الزراعة المستدامة تحت شعار «ضعف كمية الغذاء باستخدام نصف الموارد».","ومنذ أن أطلقت استراتيجيتها، تضافرت جهود الجميع فنجحوا مثلاً في خفض استخدام المياه بنسبة بلغت 90 في المائة منذ عام 2000، مع المحافظة على إنتاجية مرتفعة. وتمكنت عائلة «دويفستين» العريقة من زراعة الطماطم في بيئة يُتحكم في مناخها، حيث لا تنمو النباتات في التربة وإنما في ألياف مصنوعة من مواد طبيعية، فاختارتها لجنة دولية من خبراء «البستنة» عام 2015، كأكثر مزارعي الطماطم ابتكاراً في العالم. وصار لدى المزرعة اكتفاء شبه ذاتي، فهي تنتج تقريباً كل احتياجاتها من الطاقة والأسمدة، وحتى بعض مواد التغليف، إذ تعيد تدوير النباتات القديمة لصناعة صناديق التعبئة، بحسب مقال منشور في مجلة «ناشيونال جيوغرافيك».","الهولنديون يستخدمون بدائل طبيعية للمبيدات الكيميائية، منها حشرات وكائنات دقيقة تفترس الآفات الزراعية. وتقف خلف كثير من هذه الابتكارات «جامعة ومركز أبحاث فاخينينغن» جنوب شرقي أمستردام، التي أصبحت أشبه بمختبر عالمي للزراعة. ومن عجائب ما توصلت إليه الشركات الهولندية أن بذرة طماطم واحدة، يقل سعرها عن نصف دولار، يمكن أن تنتج نحو 150 رطلاً من الطماطم. ولذلك لا نستغرب حين نقرأ أن أكثر من ثلث التجارة العالمية في بذور الخضراوات يأتي من هولندا.","ولم يحتفظ الهولنديون بهذه المعرفة لأنفسهم، فقد شاركت الجامعة في أكثر من ألف مشروع في نحو 140 دولة، لنقل تقنيات الزراعة وتحسين الأمن الغذائي.","لم تعد هولندا «بلد الزهور» فحسب، بل أصبحت مختبراً لما قد تبدو عليه زراعة المستقبل، ومدرسة للعالم. وتذكرنا تجربتها بأن الدول لا تتقدم بالضرورة بوفرة الموارد بل بحسن الاستثمار والتخطيط واستشراف «تحديات» المستقبل قبل أن تتحول إلى «أزمات» يصعب تداركها."]','الاقتصاد','العالم','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://aawsat.com/%D8%A7%D9%84%D8%B1%D8%A3%D9%8A/5305592-%D9%83%D9%8A%D9%81-%D8%AA%D9%8F%D8%B7%D8%B9%D9%85-%D9%87%D9%88%D9%84%D9%86%D8%AF%D8%A7-%D8%A7%D9%84%D8%B9%D8%A7%D9%84%D9%85%D8%9F','https://aawsat.com/%D8%A7%D9%84%D8%B1%D8%A3%D9%8A/5305592-%D9%83%D9%8A%D9%81-%D8%AA%D9%8F%D8%B7%D8%B9%D9%85-%D9%87%D9%88%D9%84%D9%86%D8%AF%D8%A7-%D8%A7%D9%84%D8%B9%D8%A7%D9%84%D9%85%D8%9F','','','د. محمد النغيمش','السعودية','2026-08-10T18:05:00.000Z','Wed, 07 Oct 2026 19:05:07 GMT','2026-08-12T18:08:50.112Z','','','/api/media/fallback/%D8%A7%D9%84%D8%A7%D9%82%D8%AA%D8%B5%D8%A7%D8%AF','كيف تُطعم هولندا العالم؟',NULL,NULL,'invalid_image_dimensions','review','archived','valid',83,'7f704585caa16bc281d9155a7724e211ed3ff203e77a4518a58db5bbd3be3de2','ffd2cdf13c90881df5d8046e32760f59241bba1c792b68c47f8bcd675afb74b7','محدّث','2026-08-12T18:08:50.112Z','2026-10-07T19:05:10.827Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["العالم","الاقتصاد","جامعة ومركز أبحاث فاخينينغن جنوب","الطاقة والنفط","الطقس والمناخ","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق"]','["جامعة ومركز أبحاث فاخينينغن جنوب","الطاقة والنفط","الطقس والمناخ","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[]','Updated','2026-10-07T19:05:10.827Z',200,76,0,'source_content_changed','',NULL,NULL,'body:75f126bdefe6d1bd0b17c6460083615853454c5cb5f65ecaa2a2fed783b2e9f2','Wed, 07 Oct 2026 19:05:07 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2c451b0a-8a1b-41b0-9506-dcfb047efffe','news-2c451b0a-8a1b-41b0-9506-dcfb047efffe','البرتغال تشهد كسوفاً كلياً للشمس للمرة الأولى منذ 113 عاماً','البرتغال تشهد كسوفا كليا للشمس للمره الاولي منذ 113 عاما','تشهد البرتغال اليوم الأربعاء كسوفاً كلياً للشمس للمرة الأولى منذ عام 1912، غير أن نطاق الرؤية الكلية سيقتصر على منطقة صغيرة من متنزه مونتيزينيو الطبيعي في مدينة «براغانسا» شمال شرق البلاد.','["ومن المرتقب أن تستمر مرحلة الكسوف الكلي في تلك المنطقة نحو 26 ثانية فحسب، فيما سيكون الكسوف جزئياً في سائر أنحاء البلاد، بنسبة حجب للشمس تتراوح بين 92 و99% في البر الرئيس، وبين 74 و77% في منطقتي الأزور وماديرا.","ويبدأ الكسوف نحو الساعة السادسة والنصف مساءً بالتوقيت المحلي، ليبلغ ذروته قرابة السابعة والنصف، قبل أن ينتهي نحو الثامنة والنصف مساءً، لتستغرق الظاهرة في مجملها نحو ساعتين.","وتنظم مراصد فلكية وبلديات وجمعيات ومراكز «سيينسيا فيفا» في مختلف أنحاء البرتغال جلسات لمتابعة الظاهرة، باستخدام تلسكوبات مزودة بمرشحات شمسية ونظارات حماية معتمدة.","ويُشار إلى أن الكسوف الكلي القادم للشمس الذي ستشهده البرتغال لن يتكرر قبل عام 2144، ما يجعل هذه الظاهرة حدثاً فلكياً استثنائياً نادراً."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/l3ra17f','https://sabq.org/article/l3ra17f','','https://sabq.org/article/l3ra17f','صحيفة سبق','السعودية','2026-08-12T05:53:00.000Z','2026-08-12T08:54:00.000Z','2026-08-12T18:08:51.426Z','https://media.sabq.org/news/2026/08/5b829fd5-b15b-45c2-8fe1-6e49ec361928/w1200.webp','/api/media/2c451b0a-8a1b-41b0-9506-dcfb047efffe','/api/media/2c451b0a-8a1b-41b0-9506-dcfb047efffe?variant=thumbnail','البرتغال تشهد كسوفاً كلياً للشمس للمرة الأولى منذ 113 عاماً',1200,675,'valid','published','archived','valid',35,'3f77e4aab6537722400b09c3666c690bc76c51931d4bcc999a40dbdccb3d0104','d1275c5e96d2087889ba8aaf47b605f29aa5ddcb5289383a66c260d31708d11c','محدّث','2026-08-12T18:08:51.426Z','2026-10-07T21:08:00.082Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T21:08:00.082Z',200,80,0,'source_article_available','',NULL,NULL,'body:08cac938b0eefd8c0b9f40fc65e90be15ef9a77d33f230b6022537fffe362937','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('090e1c10-daee-4a4b-b641-a147c05c3308','news-090e1c10-daee-4a4b-b641-a147c05c3308','المملكة تحقق 87% في مؤشر نضج التجربة الرقمية لعام 2026 بمستوى متقدم','المملكه تحقق 87 في مؤشر نضج التجربه الرقميه لعام 2026 بمستوي متقدم','أعلنت هيئة الحكومة الرقمية نتائج مؤشر نضج التجربة الرقمية لعام 2026، محققةً نسبة 87.06% بمستوى «متقدم»، وذلك بعد تقييم شامل لـ59 منصة رقمية حكومية وفق أربعة مناظير رئيسية تضمنت 20 محوراً، شملت رضا المستفيد وتجربة المستخدم، والتعامل مع الشكاوى، والتقنيات والأدوات.','["وأكد محافظ هيئة الحكومة الرقمية المهندس أحمد بن محمد الصويان أن نتائج المؤشر تعكس التطور المتواصل في الخدمات الرقمية بالمملكة، والتزام الجهات الحكومية بتحسين خدماتها والاستفادة من آراء المستفيدين، بما يُسهم في تقديم خدمات رقمية أكثر سهولةً وكفاءةً وموثوقية، ورفع جودة الحياة وتعزيز كفاءة الأداء الحكومي.","وأشار إلى أن هذا التطور يأتي امتداداً للدعم والتمكين اللذين تحظى بهما منظومة الحكومة الرقمية من خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، وولي العهد رئيس مجلس الوزراء الأمير محمد بن سلمان بن عبدالعزيز آل سعود -حفظهما الله-، لتحقيق مستهدفات رؤية السعودية 2030.","وسجّل المؤشر نمواً ملحوظاً مقارنةً بعام 2025، إذ ارتفع عدد المنصات المُقيَّمة من 50 إلى 59 منصة، فيما تجاوز عدد المشاركين في استبيان «قيّم تجربتك الرقمية» 805 آلاف مشارك، مقارنةً بـ374 ألف مشارك في العام السابق.","كما حقق المؤشر الفرعي للشمولية الرقمية نسبة 76.98% ضمن مستوى «متمكن»، مما يعكس اهتمام الجهات الحكومية بتصميم خدمات رقمية شاملة تُمكّن مختلف فئات المجتمع، بما فيها الأشخاص ذوو الإعاقة وكبار السن."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/hc9pkgo','https://sabq.org/article/hc9pkgo','','https://sabq.org/article/hc9pkgo','صحيفة سبق','السعودية','2026-08-12T05:39:00.000Z','2026-08-12T08:39:00.000Z','2026-08-12T18:08:51.627Z','https://media.sabq.org/news/2026/08/5f25b654-45e5-4bea-bfb7-3fdd1452d33a/w1024.webp','/api/media/090e1c10-daee-4a4b-b641-a147c05c3308','/api/media/090e1c10-daee-4a4b-b641-a147c05c3308?variant=thumbnail','المملكة تحقق 87% في مؤشر نضج التجربة الرقمية لعام 2026 بمستوى متقدم',1024,640,'valid','published','archived','valid',99,'361e400d7814ccc7a7fe1587c7b6caf7314ffe76d78a11de360ff47374649b29','37da95c68a171dc5713843321f98f908b6a9c05452c23fe9bbf412c849257995','محدّث','2026-08-12T18:08:51.627Z','2026-10-07T21:11:18.166Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس الوزراء الأمير محمد بن","رئيس مجلس الوزراء الأمير محمد","هيئة الحكومة الرقمية المهندس أحمد","خادم الحرمين الشريفين الملك سلمان","التقنية والتحول الرقمي"]','["مجلس الوزراء الأمير محمد بن","رئيس مجلس الوزراء الأمير محمد","هيئة الحكومة الرقمية المهندس أحمد","خادم الحرمين الشريفين الملك سلمان","التقنية والتحول الرقمي"]','classified','','[{"category":"المجتمع","score":5.5},{"category":"السياسة","score":3.5},{"category":"السفر","score":3.5}]','Active','2026-10-07T21:11:18.166Z',200,80,0,'source_article_available','',NULL,NULL,'body:a0498b5baf445234837158719840345594f8502980b55a0fc03b98bc1d39480e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e40ef170-0df6-4ac0-aa3e-a93972a19dda','news-e40ef170-0df6-4ac0-aa3e-a93972a19dda','مستعمرون يقتحمون الأقصى ويؤدون جولات استفزازية بحماية قوات الاحتلال','مستعمرون يقتحمون الاقصي ويؤدون جولات استفزازيه بحمايه قوات الاحتلال','اقتحم عشرات المستعمرين الإسرائيليين المسجد الأقصى المبارك في القدس المحتلة، على شكل مجموعات متتالية عبر باب المغاربة، ونفّذوا جولات استفزازية في باحاته، في ظل حماية مشددة من قوات الاحتلال الإسرائيلي.','["وفرضت قوات الاحتلال إجراءات عسكرية مشددة على أبواب المسجد الأقصى، أعاقت دخول الزوار والمصلين إلى المسجد.","وتزامن الاقتحام مع شروع مستعمرين في توسعة بؤرة استعمارية شمال مدينة القدس، في خضم تصاعد ملحوظ في اعتداءات قوات الاحتلال والمستعمرين على المدن والبلدات الفلسطينية، بهدف التوسع الاستعماري.","وعلى صعيد آخر، أصيب عدد من الفلسطينيين بحالات اختناق جراء استنشاق الغاز السام، خلال اقتحام قوات الاحتلال الإسرائيلي سوق مخيم بلاطة شرق مدينة نابلس."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/d3pa1i2','https://sabq.org/article/d3pa1i2','','https://sabq.org/article/d3pa1i2','صحيفة سبق','السعودية','2026-08-12T05:17:00.000Z','2026-08-12T08:18:00.000Z','2026-08-12T18:08:52.005Z','https://media.sabq.org/news/2026/08/5f81db0b-0d71-4181-a8f1-e6103ae45734/w1600.webp','/api/media/e40ef170-0df6-4ac0-aa3e-a93972a19dda','/api/media/e40ef170-0df6-4ac0-aa3e-a93972a19dda?variant=thumbnail','مستعمرون يقتحمون الأقصى ويؤدون جولات استفزازية بحماية قوات الاحتلال',1600,900,'valid','published','archived','valid',42,'43762ecf83a745f7df7ae62c9f056feb5138a07f931bb0abc2adf40cf2fedf59','dd560a45a0703f4335d1900903f25b9a2d95971b0daeb1b33aa6725e0e86a357','محدّث','2026-08-12T18:08:52.005Z','2026-10-07T21:11:18.201Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","فلسطين"]','["الطاقة والنفط"]','manual_approved','below_category_threshold','[{"category":"الطاقة والصناعة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T21:11:18.201Z',200,79,0,'source_article_available','',NULL,NULL,'body:cd733f52d984660737d9665d2e13a5bf1f0cca2d6b5b96c0704b70807a59d8cb','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d0ff3c6a-002e-4111-9474-251cf9a3ef90','news-d0ff3c6a-002e-4111-9474-251cf9a3ef90','اللومي الحساوي.. موروث زراعي يعزز القيمة الاقتصادية ويدعم الصناعات التحويلية في الأحساء','اللومي الحساوي موروث زراعي يعزز القيمه الاقتصاديه ويدعم الصناعات التحويليه في الاحساء','في واحة الأحساء حيث تتعانق خبرة المزارعين المتوارثة مع البيئة الزراعية الفريدة، يبرز اللومي الحساوي بوصفه أحد المحاصيل الموسمية التي ارتبطت بحياة الأهالي ومائدتهم اليومية، بصفته موروثًا زراعيًّا اجتماعيًّا، وقيمة غذائية عالية.','["ويشهد اللومي الحساوي هذه الأيام حضورًا لافتًا في الأسواق المركزية المحلية، ومحال بيع الخضار والفواكه، مع تسويقه خليجيًا، بعد تطبيق الضوابط والاشتراطات، من أنظمة التعبئة والتغليف، وإنشاء علامة تجارية موحدة، فضلًا عن التوسع في الصناعات التحويلية، مثل إنتاج العصائر الطبيعية، والزيوت العطرية، واللومي المجفف عالي الجودة، والمنتجات الأخرى التي ترفع العائد الاقتصادي للمزارع.","ويعد الليمون من الفواكه الزراعية الصيفية وأشهرها في الأحساء، بما يمثله من قيمة اقتصادية واستثمارية نتيجة وفرته الكبيرة في مختلف البساتين الزراعية، مع ما يلقى من اهتمام وعناية في الحفاظ على جودته من قبل المزارعين، جعلته يحظى بثقة المستهلكين، ويحتل مكانة بارزة بين المنتجات الزراعية في الواحة.","ويتميز اللومي الحساوي بالقشرة الرقيقة، ونسبة العصير العالية، وقوة الرائحة العطرية، والتوازن المميز بين الحموضة والطعم، إضافة إلى احتفاظه بجودته عند التجفيف، وهي صفات لا ترجع إلى اختلاف النوع النباتي، وإنما إلى التفاعل الفريد بين الظروف البيئية للأحساء والخبرة الزراعية المتوارثة لدى مزارعيها، وما وفرته الواحة من بيئة مثالية لإنتاج هذا المحصول.","ويؤدي مهرجان اللومي الحساوي السنوي دورًا محوريًا في دعم هذا المنتج، إذ أصبح منصة تجمع المزارعين والباحثين والجهات الحكومية والخاصة والمستثمرين، وتسهم في التعريف بالمنتج، وتشجيع الابتكار، ونقل التقنيات الحديثة، وتحفيز الصناعات والإنتاجات المتعددة المرتبطة باللومي، وتعزيز الوعي بأهميته الثقافية والاقتصادية."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/rkwrw02','https://sabq.org/article/rkwrw02','','https://sabq.org/article/rkwrw02','صحيفة سبق','السعودية','2026-08-12T04:35:00.000Z','2026-08-12T07:36:00.000Z','2026-08-12T18:08:52.380Z','https://media.sabq.org/news/2026/08/15c048f5-ae77-4dab-90cc-858950f8d661/w1600.webp','/api/media/d0ff3c6a-002e-4111-9474-251cf9a3ef90','/api/media/d0ff3c6a-002e-4111-9474-251cf9a3ef90?variant=thumbnail','صورة من الألبوم',1600,1291,'valid','published','archived','valid',86,'4977076ea66e90ff2b49847c14ce98d31f387c0e7842a963ed55f25656879329','53a1f74b31c15dddbda939a4dbaf7cf06fb0f18e4f975701cab95b7613334e99','محدّث','2026-08-12T18:08:52.380Z','2026-10-07T21:11:19.428Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","الاقتصاد والأسواق"]','["الثقافة والفنون","الاقتصاد والأسواق"]','classified','','[{"category":"التعليم","score":3},{"category":"البيئة والمناخ","score":3},{"category":"أخبار السعودية","score":1.5}]','Active','2026-10-07T21:11:19.428Z',200,82,0,'source_article_available','',NULL,NULL,'body:58d82e16a46d2eb3d0b3a6fba70e84e18db0427e88062918d0ca229c928492d2','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('79db8f94-8578-4e22-9111-e8c58b53809a','news-79db8f94-8578-4e22-9111-e8c58b53809a','المطارات السعودية تتصدر الشرق الأوسط وأفريقيا..  8 ملايين مقعد مجدول في أغسطس2026','المطارات السعوديه تتصدر الشرق الاوسط وافريقيا 8 ملايين مقعد مجدول في اغسطس2026','تصدرت المملكة العربية السعودية أسواق الطيران في الشرق الأوسط وأفريقيا من حيث السعة المقعدية المجدولة خلال شهر أغسطس 2026، بعدما بلغ إجمالي المقاعد المجدولة على الرحلات من وإلى وداخل المملكة نحو 7.86 مليون مقعد، متقدمة على الإمارات ومصر وجميع أسواق الطيران في المنطقتين.','["وبحسب أحدث بيانات مؤسسة OAG العالمية المتخصصة في بيانات الطيران وجداول الرحلات، ارتفعت السعة المقعدية في السوق السعودي بنسبة 4.1% مقارنة بأغسطس من العام الماضي، بما يعادل إضافة نحو 306 آلاف مقعد خلال عام واحد.","وتعكس الأرقام النشاط الكبير الذي تشهده شبكة المطارات السعودية، التي تضم قرابة 30 مطارًا مدنيًا بين مطارات دولية ومحلية، وتخدم شبكة متنامية من الوجهات الداخلية والدولية.","السعودية تتجاوز الإمارات ومصر وأظهرت المقارنة بين بيانات OAG للشرق الأوسط وأفريقيا أن السعودية جاءت في الصدارة بنحو 7.86 مليون مقعد، تلتها الإمارات بنحو 7.17 مليون مقعد، بينما تصدرت مصر القارة الأفريقية بنحو 3.2 ملايين مقعد فقط.","وبذلك يزيد عدد المقاعد المجدولة في السوق السعودي خلال أغسطس بنحو 690 ألف مقعد على الإمارات، وبأكثر من 4.6 ملايين مقعد على مصر، أكبر سوق طيران في أفريقيا خلال الشهر نفسه."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/5p7qdt4','https://sabq.org/article/5p7qdt4','','https://sabq.org/article/5p7qdt4','خالد خليل','السعودية','2026-08-12T04:52:00.000Z','2026-08-12T07:52:00.000Z','2026-08-12T18:08:52.408Z','https://media.sabq.org/news/2026/08/1978bf07-1d9c-4a50-84d3-6be871cb7f71/w1600.webp','/api/media/79db8f94-8578-4e22-9111-e8c58b53809a','/api/media/79db8f94-8578-4e22-9111-e8c58b53809a?variant=thumbnail','المطارات السعودية تتصدر الشرق الأوسط وأفريقيا..  8 ملايين مقعد مجدول في أغسطس2026',1600,1066,'valid','published','archived','valid',49,'d9e354c0b7342ed1a61a3e0a34e896fa378f20c0ca23878b2a5be48950d59c4b','1bc58ce55393799b7aef1f6af4a8a3300cca2af2a470685177874b3492797de5','محدّث','2026-08-12T18:08:52.408Z','2026-10-07T21:11:19.423Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الشرق الأوسط"]','["السفر والسياحة","الشرق الأوسط"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":4.5},{"category":"السفر","score":4.5},{"category":"العالم","score":4.5}]','Active','2026-10-07T21:11:19.423Z',200,84,0,'source_article_available','',NULL,NULL,'body:db4fc03d120e3efd59e8ecade3cad3a6fe97dd6c261137038a5ffe98490534b4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9e754bd8-c206-4a2a-818d-929fdfb3c64a','news-9e754bd8-c206-4a2a-818d-929fdfb3c64a','أمانة نجران تفحص 675 عينة غذائية ومائية خلال يوليو لتعزيز سلامة الغذاء','امانه نجران تفحص 675 عينه غذائيه ومائيه خلال يوليو لتعزيز سلامه الغذاء','نفّذ مختبر صحة البيئة وسلامة الغذاء بأمانة منطقة نجران، خلال شهر يوليو الماضي، سلسلة من الإجراءات الرقابية والتحاليل المخبرية المكثفة للكشف عن الأغذية والمياه ومسببات التلوث الغذائي، وذلك ضمن خطة الأمانة الشاملة لضمان سلامة وجودة المنتجات المقدمة للمستهلكين وتطبيق أعلى معايير الوقاية الصحية بالمنطقة.','["وبلغت إحصائيات الفحوصات المخبرية لشهر يوليو لعام 2026م، 675 عينة متنوعة، شملت فحص 310 عينات غذائية، و275 عينة من الخضار والفواكه بواقع 177 عينة للخضار و98 عينة للفواكه، إضافة إلى فحص 90 عينة من المياه.","وتأتي هذه الفحوصات بالتكامل مع الجهود الميدانية المستمرة للأمانة، التي تضمنت تنفيذ أكثر من 2700 زيارة رقابية شهرية للمنشآت الغذائية، وفحص ما يزيد على 4000 عينة تراكمية على مدار الفترات الماضية، حيث يؤدي المختبر دورًا محوريًا في هذا الجانب عبر استخدام أجهزة وتقنيات دقيقة في كل من المختبر المركزي والمختبر المتنقل، مما يتيح سحب العينات وتحليلها فوريًا، واتخاذ الإجراءات النظامية حيال أي مخالفات تتعلق بالاشتراطات الصحية.","وأوضح المتحدث الرسمي لأمانة المنطقة عبدالله آل فاضل، أن أعمال الرقابة تشمل سحب عينات عشوائية من المطاعم، والمخابز، ومنافذ بيع الأغذية، حيث تُخضع العينات لفحوصات متقدمة للكشف عن الملوثات الكيميائية والميكروبية، والتأكد من مطابقتها الكاملة للمعايير والمواصفات القياسية المعتمدة؛ لضمان امتثالها لمتطلبات السلامة والجودة، مؤكدًا أن هذه الجهود المتواصلة تأتي في سياق حرص أمانة منطقة نجران على تعزيز منظومة الأمن الغذائي،…"]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/y1ilvgu','https://sabq.org/article/y1ilvgu','','https://sabq.org/article/y1ilvgu','صحيفة سبق','السعودية','2026-08-12T04:43:00.000Z','2026-08-12T07:44:00.000Z','2026-08-12T18:08:52.710Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/0d0a5edf-4830-4450-9816-d2531462a300/public','/api/media/9e754bd8-c206-4a2a-818d-929fdfb3c64a','/api/media/9e754bd8-c206-4a2a-818d-929fdfb3c64a?variant=thumbnail','أمانة نجران تفحص 675 عينة غذائية ومائية خلال يوليو لتعزيز سلامة الغذاء',1230,800,'valid','published','archived','valid',58,'839f33232704a73051913c5983ad25b96255144c39ea50a97237d8fc586a35ee','f43b484ccef0d88f8b6e231d727a0abc6dc149422ab43a19b0ba6fb8df7de30b','محدّث','2026-08-12T18:08:52.710Z','2026-10-07T21:11:19.452Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["نجران"]','[]','manual_approved','ambiguous_category','[{"category":"الصحة","score":5.5},{"category":"المجتمع","score":1.5},{"category":"التقنية","score":1.5}]','Active','2026-10-07T21:11:19.452Z',200,85,0,'source_article_available','',NULL,NULL,'body:a36ae1ec4c321b69c1ca3a7761792f95b9e4e1afe39c220131ad4d901d32edfc','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('52133402-c836-4f6a-a521-6cc24ff1f249','news-52133402-c836-4f6a-a521-6cc24ff1f249','أمانة القصيم تنفذ 105 آلاف جولة لمعالجة التشوه البصري ببريدة','امانه القصيم تنفذ 105 الاف جوله لمعالجه التشوه البصري ببريده','نفذت أمانة منطقة القصيم أكثر من 105 آلاف جولة رقابية لمعالجة التشوه البصري في مدينة بريدة خلال النصف الأول من عام 2026، ضمن جهودها المستمرة للارتقاء بالمشهد الحضري وتعزيز جودة الحياة.','["وأوضح المتحدث الرسمي لأمانة منطقة القصيم نايف بن عبدربه النفيعي، أن الجولات الرقابية استهدفت رصد مظاهر التشوه البصري ومعالجتها، بما يسهم في تحسين المظهر العام للمدينة ورفع مستوى الامتثال وجاذبيتها والارتقاء بجودة الحياة.","وأكد أن الأمانة تواصل تنفيذ خططها الرقابية من خلال الفرق الميدانية والزيارات الدورية، بما يضمن سرعة معالجة الملاحظات والحد من مسببات التشوه البصري."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/k8c0y15','https://sabq.org/article/k8c0y15','','https://sabq.org/article/k8c0y15','صحيفة سبق','السعودية','2026-08-12T03:53:00.000Z','2026-08-12T06:54:00.000Z','2026-08-12T18:08:52.985Z','https://media.sabq.org/news/2026/08/572626be-b378-4598-a4a9-3d050b9d381c/w1600.webp','/api/media/52133402-c836-4f6a-a521-6cc24ff1f249','/api/media/52133402-c836-4f6a-a521-6cc24ff1f249?variant=thumbnail','أمانة القصيم تنفذ 105 آلاف جولة لمعالجة التشوه البصري ببريدة',1600,974,'valid','published','archived','valid',48,'d9bb04660d0ec5b091314a54f2dfada70632c522c67f0b0ab2f4b03f4eaceb6a','94d2a9e51341fff37c175135a61f646ea0f71577aded26fb5b84131f244b8457','محدّث','2026-08-12T18:08:52.985Z','2026-10-07T21:11:18.818Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","القصيم"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":3},{"category":"الرياضة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:11:18.818Z',200,80,0,'source_article_available','',NULL,NULL,'body:1554b42c89cc8aac6ba01c7c653ee7374208009048c46961a80c7f9aaadc1f3b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f14dd207-3dd7-4382-a6ee-e870a16ba1f5','news-f14dd207-3dd7-4382-a6ee-e870a16ba1f5','شهداء غزة يتجاوزون 73 ألفاً وخروقات إسرائيلية تتواصل رغم اتفاق وقف النار','شهداء غزه يتجاوزون 73 الفا وخروقات اسرائيليه تتواصل رغم اتفاق وقف النار','ارتفعت حصيلة ضحايا عدوان الاحتلال الإسرائيلي على قطاع غزة إلى 73,388 شهيدًا و 174,259 مصابًا بينهم أطفال ونساء وعائلات بأكملها، فيما تتواصل عمليات انتشال جثامين الشهداء من تحت ركام المنازل والبنايات السكنية المدمرة في مناطق مختلفة من القطاع، بعد عامين من العدوان.','["وفي السياق نفسه، أفادت مصادر طبية فلسطينية، بوصول شهيد ومصابين إلى مستشفيات قطاع غزة، خلال 24 ساعة الماضية، جرّاء استمرار الخروقات الإسرائيلية لاتفاق وقف إطلاق النار في غزة."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/bjk29wp','https://sabq.org/article/bjk29wp','','https://sabq.org/article/bjk29wp','صحيفة سبق','السعودية','2026-08-12T04:06:00.000Z','2026-08-12T07:08:00.000Z','2026-08-12T18:08:53.004Z','https://media.sabq.org/news/2026/08/32d1a77c-7cf2-43d0-9db3-546702d1d3ef/w1280.webp','/api/media/f14dd207-3dd7-4382-a6ee-e870a16ba1f5','/api/media/f14dd207-3dd7-4382-a6ee-e870a16ba1f5?variant=thumbnail','شهداء غزة يتجاوزون 73 ألفاً وخروقات إسرائيلية تتواصل رغم اتفاق وقف النار',1280,720,'valid','published','archived','valid',77,'02f6ff78d3a79716e8a1579178465ffae58ea59dada0b09bd0919dc23a19ccd0','b12e62db411e4aceaeaa11d6c0e0f52b38b27497e6a2571084e4cbb076be3bf8','محدّث','2026-08-12T18:08:53.004Z','2026-10-07T21:11:18.822Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","غزة","فلسطين"]','["الصحة العامة"]','manual_approved','','[]','Active','2026-10-07T21:11:18.822Z',200,82,0,'source_article_available','',NULL,NULL,'body:eb65a195732b597e36c3fb60c01b869c19d54d84587ce8bccb7b47c4bba57bcf','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a5cfaa19-be68-46b1-b50f-11c07ed57cce','news-a5cfaa19-be68-46b1-b50f-11c07ed57cce','الجوازات تعزز كفاءة المنافذ الدولية وتدعو للمحافظة على جوازات السفر والتحقق من صلاحيتها قبل السفر','الجوازات تعزز كفاءه المنافذ الدوليه وتدعو للمحافظه علي جوازات السفر والتحقق من صلاحيتها قبل السفر','عززت المديرية العامة للجوازات جهودها في المنافذ، لإنهاء إجراءات المسافرين بانسيابية، من خلال منظومة عمل متكاملة تهدف إلى تسهيل الإجراءات ورفع كفاءة الأداء، ومواكبة الأعداد المتزايدة من المسافرين عبر مختلف منافذ المملكة.','["ودعمت المديرية العامة للجوازات المنافذ الدولية بالإمكانات البشرية المؤهلة، المزودة بأحدث الحلول التقنية، بما يسهم في تسريع الإجراءات وتحسين تجربة السفر.","ودعت الجوازات المواطنين إلى المحافظة على جوازات سفرهم داخل وخارج المملكة، وحمايتها من التلف أو الفقدان أو السرقة، وعدم إهمالها أو رهنها أو إساءة استعمالها، والتحقق من سلامة وصلاحية الوثيقة قبل السفر بوقت كافٍ.","ويأتي ذلك في إطار حرص المديرية العامة للجوازات على تعزيز مستوى الوعي لدى المسافرين، وتقديم منظومة متكاملة ترتقي بجودة الخدمات المقدمة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/q0v60c3','https://sabq.org/article/q0v60c3','','https://sabq.org/article/q0v60c3','صحيفة سبق','السعودية','2026-08-12T04:05:00.000Z','2026-08-12T07:06:00.000Z','2026-08-12T18:08:53.171Z','https://media.sabq.org/news/2026/08/cb988e30-2be9-47f8-8dcd-446a90c9ea16/w1600.webp','/api/media/a5cfaa19-be68-46b1-b50f-11c07ed57cce','/api/media/a5cfaa19-be68-46b1-b50f-11c07ed57cce?variant=thumbnail','صورة من الألبوم',1600,900,'valid','published','archived','valid',91,'8bf2e0ba16e5bd8dc18f2908fe07ea6352884711a860da4ba42c691aaf7e0d74','345a85d20ed555117939ee747b49da36db7bed8de10ce6584185112d5776025e','محدّث','2026-08-12T18:08:53.171Z','2026-10-07T21:11:17.319Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","التقنية والتحول الرقمي"]','["السفر والسياحة","التقنية والتحول الرقمي"]','classified','','[{"category":"السفر","score":4.5},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T21:11:17.319Z',200,82,0,'source_article_available','',NULL,NULL,'body:52d0e3af8f1d69d5678f63de22a98b487aac360cae22ffb72777b42dd23a77ba','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a955a14f-9c3a-41ee-95f1-d209f5897a61','news-a955a14f-9c3a-41ee-95f1-d209f5897a61','حرس الحدود يضبط 3 مخالفين بحوزتهم 66 كجم من القات','حرس الحدود يضبط 3 مخالفين بحوزتهم 66 كجم من القات','قبضت الدوريات البرية لحرس الحدود في قطاع الربوعة بمنطقة عسير على 3 مخالفين لنظام أمن الحدود من الجنسية الإثيوبية، بحوزتهم 66 كيلوجرامًا من نبات القات المخدر.','["وجرى استكمال الإجراءات النظامية بحقهم، وتسليمهم والمضبوطات لجهة الاختصاص.","وأكد حرس الحدود استمرار جهوده في التصدي لمحاولات تهريب وترويج المخدرات، داعيًا إلى الإبلاغ عن أي نشاطات مرتبطة بتهريب أو ترويج المخدرات عبر الأرقام 911 في مناطق مكة المكرمة والمدينة المنورة والرياض والشرقية، و999 في بقية مناطق المملكة، أو 995 لمكافحة المخدرات، أو عبر البريد الإلكتروني [ 995@gdnc.gov.sa ]( mailto:995@gdnc.gov.sa )."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/g5sq94a','https://sabq.org/article/g5sq94a','','https://sabq.org/article/g5sq94a','صحيفة سبق','السعودية','2026-08-12T02:21:00.000Z','2026-08-12T05:22:00.000Z','2026-08-12T18:08:53.409Z','https://media.sabq.org/news/2026/08/9a951187-f0c5-4082-817c-f8af46b1beed/w905.webp','/api/media/a955a14f-9c3a-41ee-95f1-d209f5897a61','/api/media/a955a14f-9c3a-41ee-95f1-d209f5897a61?variant=thumbnail','حرس الحدود يضبط 3 مخالفين بحوزتهم 66 كجم من القات',905,666,'valid','published','archived','valid',51,'3822a0925984adcab1ca2dca2fda5810426e2e0c7d6aa6b196031f8ba028e1a9','cbf176b5c56547e1d88c03df2f05f341b061518b83e6ff5f940cc827de001457','محدّث','2026-08-12T18:08:53.409Z','2026-10-07T21:11:18.828Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","الرياض","المدينة المنورة"]','["المدينة المنورة"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"السياسة","score":0}]','Active','2026-10-07T21:11:18.828Z',200,83,0,'source_article_available','',NULL,NULL,'body:88b65187fd05eacc107acb2eaa1a1122bff26467282e7a0199ed40714c450571','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2a041291-dc90-4e17-aa5b-7fe53e0c8635','news-2a041291-dc90-4e17-aa5b-7fe53e0c8635','45 يوماً لتصحيح أوضاع الأراضي الفضاء قبل انتهاء المهلة في سبتمبر 2026','45 يوما لتصحيح اوضاع الاراضي الفضاء قبل انتهاء المهله في سبتمبر 2026','أكدت وزارة البلديات والإسكان أن المهلة التصحيحية الممنوحة لملاك الأراضي الفضاء تنتهي بعد 45 يومًا، في 15 ربيع الآخر 1448هـ (26 سبتمبر 2026م)، داعيةً الملاك إلى المبادرة بتصحيح أوضاع أراضيهم والالتزام بالاشتراطات والضوابط البلدية المعتمدة قبل انتهاء المهلة.','["وأوضحت الوزارة أن المهلة تستهدف تعزيز مستوى الامتثال في الأراضي الفضاء، ومعالجة الاستخدامات والممارسات المخالفة التي تؤثر في المظهر العام للمدن والمحافظات، ومن أبرزها تجميع مخلفات البناء ونواتج الحفر، واستغلال الأراضي بطرق غير نظامية.","وبيّنت أن الأمانات والبلديات تنفذ أعمال المتابعة والرقابة الميدانية على الأراضي الفضاء في مختلف مناطق المملكة، لرصد المخالفات ومعالجتها وفق الأنظمة والاشتراطات البلدية المعتمدة، بما يسهم في رفع مستوى الامتثال والحد من مظاهر التشوه البصري.","وأشارت الوزارة إلى أن الالتزام بالاشتراطات المنظمة للأراضي الفضاء يسهم في تحسين المشهد الحضري، ورفع جودة البيئة العمرانية، وتعزيز جودة الحياة في المدن والمحافظات.","ودعت ملاك الأراضي الفضاء إلى الاستفادة من الفترة المتبقية من المهلة، والمبادرة بمعالجة أوضاع أراضيهم قبل انتهائها؛ تجنبًا للإجراءات النظامية المترتبة على المخالفات."]','العقارات','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/nahw5do','https://sabq.org/article/nahw5do','','https://sabq.org/article/nahw5do','صحيفة سبق','السعودية','2026-08-12T03:06:00.000Z','2026-08-12T06:07:00.000Z','2026-08-12T18:08:53.567Z','https://media.sabq.org/news/2026/08/1120a65d-750e-4eca-b2bd-6cc3a75d2158/w1600.webp','/api/media/2a041291-dc90-4e17-aa5b-7fe53e0c8635','/api/media/2a041291-dc90-4e17-aa5b-7fe53e0c8635?variant=thumbnail','45 يوماً لتصحيح أوضاع الأراضي الفضاء قبل انتهاء المهلة في سبتمبر 2026',1600,2144,'valid','published','archived','valid',53,'cd5e9a95281b366df06b32e58e16315fd694e4d7edd8078a176e24e453f94a7f','0c357adddcb412f4f988fdc0ed39c048ab0fefeed1470d96485977438342a513','محدّث','2026-08-12T18:08:53.567Z','2026-10-07T21:11:18.786Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":4},{"category":"أخبار السعودية","score":1.5},{"category":"البيئة والمناخ","score":1.5}]','Active','2026-10-07T21:11:18.786Z',200,82,0,'source_article_available','',NULL,NULL,'body:27171528b1c3764b65e025d4e54a3d37450b27ba928b22084828022963213528','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('74901976-ea08-4d9f-93f6-211f36506468','news-74901976-ea08-4d9f-93f6-211f36506468','استشاري: 10 نصائح للوقاية من خطر الجلطات','استشاري 10 نصائح للوقايه من خطر الجلطات','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية أوضح د.','["عبد الرحمن كاتب، الاستشاري المشارك بطب الباطنية ب مستشفى الملك فيصل التخصصي ، الوقاية من مخاطر الجلطات.","وأضاف عبر أثير \"إذاعة الإخبارية\"، أنالفحوصات الدورية خط دفاع أول، مع الحذر من الأمراض المزمنة والأمراض الصامتة ما يستوجب الالتزام بالخطة العلاجية، وتجنب التدخين وأنقاص الوزن لعلاج السمنة المفرطة.","وأكمل، أن بعض المرضى يتوقفون عن أدوية الضغط والسكري لمجرد الشعور بتحسن؛ بينما الدواء يحفظ استقرار الحالة، مشيرا إلى أهمية نمط الحياة الصحي والصحة النفسية والابتعاد عن الأطعمة المشبعة بالدهون وتقليل الملح في الطعام، منوها بأهمية الالتزام بتعليمات الطبيب والحركة المبكرة ولبس الجوارب الضاغطة حال ملازمة السرير طويلا لمرض طارئ."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/goc39f5ea','https://ajel.sa/misc/goc39f5ea','https://ajel.sa/misc/goc39f5ea','https://ajel.sa/misc/goc39f5ea','فريق التحرير','السعودية','2026-08-12T13:02:00.000Z','Wed, 07 Oct 2026 21:00:54 GMT','2026-08-12T20:10:19.073Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/123456-crop-5GM1hkND.png','/api/media/74901976-ea08-4d9f-93f6-211f36506468','/api/media/74901976-ea08-4d9f-93f6-211f36506468?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',100,'c212c992495cddfa46f2858189f2975c3a0dfee7bfa34dfec05b06a40307b004','19995f29246cee2b5d9c78c443a18bd265d6538a6ae731b428d78d7443a0f7a8',NULL,'2026-08-12T20:10:19.073Z','2026-10-07T21:00:56.220Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الثقافة والفنون","التعليم والتدريب","الرياضة السعودية"]','["الصحة العامة","الثقافة والفنون","التعليم والتدريب","الرياضة السعودية"]','manual_approved','','[]','Updated','2026-10-07T21:00:56.220Z',200,74,0,'source_content_changed','',NULL,NULL,'body:90ea4b16b84bf67eab8a60334ad2e0988a905ef460349b2f2af614568b2b2135','Wed, 07 Oct 2026 21:00:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8cdf3378-025f-47f5-a8fe-1e54cba043cb','news-8cdf3378-025f-47f5-a8fe-1e54cba043cb','"الأمن البيئي" يضبط مواطنا لارتكابه مخالفة رعي في محمية الملك عبدالعزيز الملكية','الامن البيئي يضبط مواطنا لارتكابه مخالفه رعي في محميه الملك عبدالعزيز الملكيه','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية ضبطت القوات الخاصة للأمن البيئي مواطنًا مخالفًا لنظام البيئة، لارتكابه مخالفة رعي (15) متنًا من الإبل في مواقع محظور الرعي فيها في محمية الملك عبدالعزيز الملكية، وطبقت الإجراءات النظامية بحقه.','["ضبطت القوات الخاصة للأمن البيئي مواطنًا مخالفًا لنظام البيئة، لارتكابه مخالفة رعي (15) متنًا من الإبل في مواقع محظور الرعي فيها في محمية الملك عبدالعزيز الملكية، وطبقت الإجراءات النظامية بحقه.","وأكدت القوات أن عقوبة رعي الإبل غرامة (500) ريال لكل متن، حاثةً على الإبلاغ عن أي حالات تمثل اعتداءً على البيئة أو الحياة الفطرية على الرقم (911) بمناطق مكة المكرمة والمدينة المنورة و الرياض و الشرقية ، و(999) و(996) في بقية مناطق المملكة ، وستعامل جميع البلاغات بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/4mxc7y7ex','https://ajel.sa/local/4mxc7y7ex','https://ajel.sa/local/4mxc7y7ex','https://ajel.sa/local/4mxc7y7ex','فريق التحرير','السعودية','2026-08-12T13:02:00.000Z','Wed, 07 Oct 2026 21:07:44 GMT','2026-08-12T20:10:20.407Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%A3%D9%85%D9%86-%D8%A7%D9%84%D8%A8%D9%8A%D8%A6%D9%8A-4sUsfw4O.jpg','/api/media/8cdf3378-025f-47f5-a8fe-1e54cba043cb','/api/media/8cdf3378-025f-47f5-a8fe-1e54cba043cb?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',100,'041208878298577812a5dac71cd17ba854f0ccd175d61e469812ddc3a41b3940','9c6402fe45fecd174d6ae85a9959f3fa71118540dd14267d6f8a0dfb3ad223f4',NULL,'2026-08-12T20:10:20.407Z','2026-10-07T21:07:49.056Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","الرياض","المدينة المنورة"]','["المدينة المنورة"]','manual_approved','','[]','Active','2026-10-07T21:07:49.056Z',200,83,0,'source_article_available','',NULL,NULL,'body:ad239062c52daae387a36595f4336166b985e3e99f548ebe963292ce5844bee0','Wed, 07 Oct 2026 21:07:44 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('59736cd8-47cc-4e6f-88f9-3a88655cd672','news-59736cd8-47cc-4e6f-88f9-3a88655cd672','"الأمن البيئي" يضبط مواطنا لارتكابه مخالفة التخييم في محمية الإمام فيصل بن تركي الملكية','الامن البيئي يضبط مواطنا لارتكابه مخالفه التخييم في محميه الامام فيصل بن تركي الملكيه','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية ضبطت القوات الخاصة للأمن البيئي مواطنًا مخالفًا لنظام البيئة؛ لارتكابه مخالفة التخييم دون ترخيص في محمية الإمام فيصل بن تركي الملكية ، وطبقت الإجراءات النظامية بحقه.','["ضبطت القوات الخاصة للأمن البيئي مواطنًا مخالفًا لنظام البيئة؛ لارتكابه مخالفة التخييم دون ترخيص في محمية الإمام فيصل بن تركي الملكية ، وطبقت الإجراءات النظامية بحقه.","وأوضحت القوات أن عقوبة مخالفة التخييم في الغابات أو المتنزهات الوطنية دون ترخيص غرامة تصل إلى (3,000) ريال، حاثةً على الإبلاغ عن أي حالات تمثل اعتداءً على البيئة أو الحياة الفطرية على الرقم (911) بمناطق مكة المكرمة والمدينة المنورة و الرياض و الشرقية ، و(999) و(996) في بقية مناطق المملكة ، وستعامل جميع البلاغات بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/p5ds1ct6a','https://ajel.sa/local/p5ds1ct6a','https://ajel.sa/local/p5ds1ct6a','https://ajel.sa/local/p5ds1ct6a','فريق التحرير','السعودية','2026-08-12T13:02:00.000Z','Wed, 07 Oct 2026 21:07:48 GMT','2026-08-12T20:10:20.428Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%A3%D9%85%D9%86-%D8%A7%D9%84%D8%A8%D9%8A%D8%A6%D9%8A-JTi_KFP0.jpg','/api/media/59736cd8-47cc-4e6f-88f9-3a88655cd672','/api/media/59736cd8-47cc-4e6f-88f9-3a88655cd672?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',100,'dd062f851d25ab98a404b294886720dec6626d460b6fdb42cfe7b302fe334af8','c6c6392f71b24ee99242f3e6c57b402a37028fd46fa7a914b0bc381c0904593a',NULL,'2026-08-12T20:10:20.428Z','2026-10-07T21:07:53.179Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","الرياض","المدينة المنورة"]','["المدينة المنورة"]','manual_approved','','[]','Active','2026-10-07T21:07:53.179Z',200,83,0,'source_article_available','',NULL,NULL,'body:fc6a95aae449e649c06a09b7e5640eeba63e6fdaf5414409b13533803a503a02','Wed, 07 Oct 2026 21:07:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fe31fa88-632b-4da9-a445-c09096241d7b','news-fe31fa88-632b-4da9-a445-c09096241d7b','وزير الخارجية السوري يبحث هاتفيًا مع رئيس الوزراء اللبناني التطورات الإقليمية','وزير الخارجيه السوري يبحث هاتفيا مع رئيس الوزراء اللبناني التطورات الاقليميه','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية بحث وزير الخارجية السوري أسعد الشيباني ، في اتصال هاتفي اليوم، مع رئيس الوزراء اللبناني نواف سلام ، آخر المستجدات على الساحتين الإقليمية والدولية وانعكاساتها على البلدين.','["بحث وزير الخارجية السوري أسعد الشيباني ، في اتصال هاتفي اليوم، مع رئيس الوزراء اللبناني نواف سلام ، آخر المستجدات على الساحتين الإقليمية والدولية وانعكاساتها على البلدين.","ونُوقش -خلال الاتصال- سبل تعزيز التعاون والتنسيق بين البلدين بما يخدم المصالح المشتركة ويدعم أمنهما واستقرارهما.","وأكد الجانبان أهمية استمرار التنسيق والتعاون بين البلدين لمعالجة مختلف القضايا ذات الاهتمام المشترك."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/lxu63r1dw','https://ajel.sa/international/lxu63r1dw','https://ajel.sa/international/lxu63r1dw','https://ajel.sa/international/lxu63r1dw','فريق التحرير','السعودية','2026-08-12T13:08:00.000Z','Wed, 07 Oct 2026 21:02:16 GMT','2026-08-12T20:10:21.743Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%B3%D9%88%D8%B1%D9%8A%D8%A7-%D9%88%D9%84%D8%A8%D9%86%D8%A7%D9%86-_IzG5Sxt.jpg','/api/media/fe31fa88-632b-4da9-a445-c09096241d7b','/api/media/fe31fa88-632b-4da9-a445-c09096241d7b?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',94,'dc740da905dac24ccbc87b3d9852fb2f5ba2d6628b82f677a4acc83a4c8d50a0','2487575f77764a917bc234f338938d415e2cf27eaf5e5047617b00c50475985b',NULL,'2026-08-12T20:10:21.743Z','2026-10-07T21:02:17.524Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الخارجية السوري يبحث هاتفي","رئيس الوزراء اللبناني التطورات الإقليمية","لبنان"]','["وزير الخارجية السوري يبحث هاتفي","رئيس الوزراء اللبناني التطورات الإقليمية"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T21:02:17.524Z',200,81,0,'source_article_available','',NULL,NULL,'body:ae6ba3703601a8fc0392c71a187411ac631cd8c00120e7ae9271e243c6234f08','Wed, 07 Oct 2026 21:02:16 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('345f01aa-e6aa-4c87-a9a2-80d939ed8a07','news-345f01aa-e6aa-4c87-a9a2-80d939ed8a07','رومانو: تشافي يوافق على تدريب منتخب هولندا','رومانو تشافي يوافق علي تدريب منتخب هولندا','أعلن فابريزيو رومانو ، الصحفي الإيطالي المتخصص في أخبار الانتقالات، أن الإسباني تشافي هيرنانديز قد وافق على أن يصبح مدرب المنتخب الهولندي الوطني الجديد.','["وأشار عبر حسابه على منصة إكس أن تشافي يريد باتريك كلويبرت كجزء من طاقم عمله الخلفي."]','التعليم','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/yzd36ig6k','https://ajel.sa/sports/yzd36ig6k','https://ajel.sa/sports/yzd36ig6k','https://ajel.sa/sports/yzd36ig6k','فريق التحرير','السعودية','2026-08-12T13:32:00.000Z','Wed, 07 Oct 2026 18:40:00 GMT','2026-08-12T20:10:21.796Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%86%D8%B4%D8%AA%D8%A7%D9%81%D9%8A-2-Pq8vmeKo.jpg','/api/media/345f01aa-e6aa-4c87-a9a2-80d939ed8a07','/api/media/345f01aa-e6aa-4c87-a9a2-80d939ed8a07?variant=thumbnail','فريق التحرير',1200,675,'valid','rejected','archived','invalid',46,'585b37cd333aba974b01e9284cd942f6f15998ca748de2ef453c6970bdaf86fc','5b12d7c56a9c4b330418f4b54828f361de5c5e164703d430fc9a0bfe0b68c3a7',NULL,'2026-08-12T20:10:21.796Z','2026-10-07T19:24:38.659Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T18:40:02.515Z',200,71,0,'source_content_changed','',NULL,NULL,'body:5c16f6115c039ca95badc7830d71793af7ba09b139138b016829bffa4127aa54','Wed, 07 Oct 2026 18:40:00 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('964ff023-82cc-4a7c-a22b-5c4b68b3fa49','news-964ff023-82cc-4a7c-a22b-5c4b68b3fa49','هيئة إدارة مضيق هرمز : ادعاءات المسؤولين الأمريكيين المتكررة بشأن المضيق لا تغير واقع غلقه','هيئه اداره مضيق هرمز ادعاءات المسؤولين الامريكيين المتكرره بشان المضيق لا تغير واقع غلقه','قالت هيئة إدارة مضيق هرمز الإيرانية، إن ادعاءات المسؤولين الأمريكيين المتكررة أن المضيق مفتوح لا تغير واقع أنه مغلق. وكان الحرس الثوري الإيراني ، أكد أن طهران لم تُعد فتح هرمز أو تُغير سياستها بشأنه والمضيق لا يزال تحت مراقبة وإدارة الجانب الإيران.','["قالت هيئة إدارة مضيق هرمز الإيرانية، إن ادعاءات المسؤولين الأمريكيين المتكررة أن المضيق مفتوح لا تغير واقع أنه مغلق.","وتابعت هيئة إدارة مضيق هرمز الإيرانية، أنه لن يعاد فتح مضيق هرمز حتى تقبل شروط إيران.","وكان الحرس الثوري الإيراني ، أكد أن طهران لم تُعد فتح هرمز أو تُغير سياستها بشأنه والمضيق لا يزال تحت مراقبة وإدارة الجانب الإيران."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/1iho6ul2l','https://ajel.sa/international/1iho6ul2l','https://ajel.sa/international/1iho6ul2l','https://ajel.sa/international/1iho6ul2l','فريق التحرير','السعودية','2026-08-12T13:32:00.000Z','Wed, 07 Oct 2026 21:00:57 GMT','2026-08-12T20:10:30.821Z','https://cdn.ajel.sa/articles/2026-07/%D9%87%D8%B1%D9%85%D8%B2-%D8%AD%D8%B5%D8%A7%D8%B1-5CBgPo1y.avif','/api/media/964ff023-82cc-4a7c-a22b-5c4b68b3fa49','/api/media/964ff023-82cc-4a7c-a22b-5c4b68b3fa49?variant=thumbnail','فريق التحرير',900,600,'valid','published','archived','valid',99,'277362a1ffa2c7d3b9952543aa36d7819de340a13e17d2836b622b921a19b51d','c740e96c993b9fef22224e18bdd115e61b4d9f828d07e5d9194a0b084453155a',NULL,'2026-08-12T20:10:30.821Z','2026-10-07T21:00:59.160Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة إدارة مضيق هرمز ادعاءات","إيران"]','["هيئة إدارة مضيق هرمز ادعاءات"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Updated','2026-10-07T21:00:59.160Z',200,73,0,'source_content_changed','',NULL,NULL,'body:aee23698476e1a41f8cd3cc6ebee60274aae1d0277f2d1564fc093e881965ec5','Wed, 07 Oct 2026 21:00:57 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('17ab619f-fb30-4622-a9ec-bdf5f21ac463','news-17ab619f-fb30-4622-a9ec-bdf5f21ac463','سياحة وترفيه / على ضفاف حنيفة.. مشهد آخر للصيف في الرياض','سياحه وترفيه علي ضفاف حنيفه مشهد اخر للصيف في الرياض','الرياض 29 صفر 1448 هـ الموافق 12 أغسطس 2026 م واس في قلب الرياض، يرسم وادي حنيفة مشهدًا طبيعيًا تتناغم فيه التضاريس مع المساحات الخضراء والممرات المفتوحة، ليمنح زواره متنفسًا تتبدل معه إيقاعات المدينة، ووجهة تستحضر جمال المكان وعمقه الطبيعي، ضمن الخيارات السياحية والترفيهية التي يبرزها برنامج "صيفنا على كيفنا" خلال الموسم الصيفي.','["ويحضر الوادي ضمن المشهد السياحي والترفيهي الذي تشهده العاصمة تزامنًا مع برنامج \"صيفنا على كيفنا\"، الذي يبرز تنوع الوجهات والأنشطة الصيفية في مناطق المملكة، ويتيح للزوار التعرف على مواقع تجمع بين المقومات الطبيعية والخيارات الترفيهية والخدمات المساندة.","ويمتد وادي حنيفة عبر أجزاء واسعة من مدينة الرياض، مشكّلًا محورًا طبيعيًا ارتبط بتاريخ المدينة ونموها العمراني، فيما أسهمت أعمال التأهيل والتطوير في المحافظة على خصائصه البيئية وإعادة توظيف محيطه ليكون متنفسًا طبيعيًا تتكامل فيه عناصر البيئة مع المرافق المهيأة للزوار.","وتتنوع المواقع الممتدة على طول الوادي بين المساحات الخضراء والممرات ومناطق الجلوس والمتنزهات، إلى جانب المواقع المطلة على الوادي، ما جعله مقصدًا للعائلات وهواة المشي وممارسة الأنشطة الخارجية.","ويبرز سد وادي حنيفة ومحيطه بوصفه أحد المواقع التي يقصدها الزوار، إلى جانب عدد من المتنزهات والمواقع الطبيعية المتوزعة على امتداد الوادي، التي أسهمت في توسيع خيارات التنزه داخل العاصمة وإيجاد مساحات تجمع بين الهدوء والطبيعة والمشهد الحضري."]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2652622?type=news&uuid=N2652622','https://spa.gov.sa/ar/N2652622?type=news&uuid=N2652622','N2652622','N2652622','','السعودية','2026-08-12T14:13:00.000Z','2026-08-12T14:13:00.000Z','2026-08-12T20:10:42.867Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10598306.jpeg','/api/media/17ab619f-fb30-4622-a9ec-bdf5f21ac463','/api/media/17ab619f-fb30-4622-a9ec-bdf5f21ac463?variant=thumbnail','سياحة وترفيه / على ضفاف حنيفة.. مشهد آخر للصيف في الرياض',1600,1066,'valid','published','archived','valid',86,'169d001cbbd20a168bcf720e3bbb830ee46bd3bdc53dd095d69a99c5770892a0','99161d04a6fc7297e8d85bc36888f03f313295d63afd93ef1a6a4ac51f69683e',NULL,'2026-08-12T20:10:42.867Z','2026-10-07T21:01:54.163Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الاقتصاد والأسواق","الرياض"]','["السفر والسياحة","الاقتصاد والأسواق"]','classified','','[{"category":"السفر","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T21:01:54.163Z',200,79,0,'source_article_available','',NULL,NULL,'body:7950ea38e1419a9d109ec2d530b2bd458fc27a18281f6eb42b2fc3f2cd41e3e8','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e0c3f226-dccd-415e-97e8-2ab54011bcb2','news-e0c3f226-dccd-415e-97e8-2ab54011bcb2','مباشر مباراة ريال مدريد ضد ديبورتيفو لاكورونيا الودية - 365Scores','مباشر مباراه ريال مدريد ضد ديبورتيفو لاكورونيا الوديه 365scores','مباشر مباراة ريال مدريد ضد ديبورتيفو لاكورونيا ، في مواجهة ودية تجمع الفريقين ضمن التحضيرات الجارية لخوض المنافسات القادمة.','["ويسعى النادي الملكي من خلال هذه المباراة إلى إعداد لاعبيه بدقة واختبار بعض العناصر الجديدة في مختلف الخطوط.","وتكتسب المباراة أهمية خاصة لدى الجهاز الفني للريال، حيث يطمح إلى تجربة خيارات تكتيكية متنوعة وزيادة الانسجام بين عناصر الفريق الأساسية والبديلة قبل خوض الاستحقاقات الرسمية.","وتترقب الجماهير مشاهدة أداء الميرنجي في هذه التجربة الودية ضد خصم يملك تاريخًا حافلًا في الكرة الإسبانية.","يقدم لكم 365Scores مباشر مباراة ريال مدريد ضد ديبورتيفو لاكورونيا الودية، التي يطمح من خلالها المدير الفني جوزيه مورينيو الوقوف على جاهزية جميع العناصر واستعراض القدرات الهجومية والدفاعية للتشكيل الذي يخوض به اللقاء منذ الدقيقة الأولى."]','الرياضة','','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://www.365scores.com/ar/news/magazine/%D9%85%D8%A8%D8%A7%D8%B4%D8%B1-%D9%85%D8%A8%D8%A7%D8%B1%D8%A7%D8%A9-%D8%B1%D9%8A%D8%A7%D9%84-%D9%85%D8%AF%D8%B1%D9%8A%D8%AF-%D8%B6%D8%AF-%D8%AF%D9%8A%D8%A8%D9%88%D8%B1%D8%AA%D9%8A%D9%81%D9%88-%D9%84/','https://www.365scores.com/ar/news/magazine/%d9%85%d8%a8%d8%a7%d8%b4%d8%b1-%d9%85%d8%a8%d8%a7%d8%b1%d8%a7%d8%a9-%d8%b1%d9%8a%d8%a7%d9%84-%d9%85%d8%af%d8%b1%d9%8a%d8%af-%d8%b6%d8%af-%d8%af%d9%8a%d8%a8%d9%88%d8%b1%d8%aa%d9%8a%d9%81%d9%88-%d9%84/','','','محمود الشوادفي','السعودية','2026-08-12T13:07:00.000Z','Thu, 03 Sep 2026 21:03:59 GMT','2026-08-12T20:15:06.843Z','https://www.365scores.com/ar/news/magazine/wp-content/uploads/2026/08/6039742702814240909.jpg','/api/media/e0c3f226-dccd-415e-97e8-2ab54011bcb2','/api/media/e0c3f226-dccd-415e-97e8-2ab54011bcb2?variant=thumbnail','ريال مدريد ضد ديبورتيفو لاكورونيا',1100,675,'valid','published','archived','valid',100,'1c852a901fe2c7f046b8d5f79be79892a4141d527f33ac6e3170e5073f6daff7','81af83745c90e34c3ec59448897512cb29947c7ba3187ec6fd386bc323e1da9f',NULL,'2026-08-12T20:15:06.843Z','2026-10-07T19:49:56.282Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','manual_approved','','[]','Temporarily Unreachable','2026-10-07T19:49:56.282Z',NULL,62,42,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('73122c38-dc75-4f36-a8a2-e6b6d0bfc1af','news-73122c38-dc75-4f36-a8a2-e6b6d0bfc1af','9 مناطق و18 ملعبًا تستضيف دوري يلو للمحترفين في موسم 2026-2027','9 مناطق و18 ملعبا تستضيف دوري يلو للمحترفين في موسم 2026 2027','تنتشر مباريات دوري يلو لأندية الدرجة الأولى للمحترفين في موسم 2026-2027 عبر 9 مناطق من أصل 13 في المملكة، على 18 ملعبًا، في حضور جغرافي واسع يعكس التوسّع المتنامي للدوري وتنافسيته العالية المتوقعة حتى الجولات الأخيرة.','["نصيب الأسد بـ4 أندية تتصدّر منطقة القصيم المشهد الجغرافي في الدوري بمشاركة 4 أندية دفعةً واحدة، هي: الرائد، والنجمة، والبكيرية، والصقر.","وستحتضن المنطقة 4 ملاعب لاستضافة مباريات هذا الرباعي، هي: ملعب مدينة الملك عبدالله الرياضية في بريدة، وملعب نادي الرائد، وملعب نادي النجمة، وملعب نادي البكيرية.","3 أندية وملعبان تشارك منطقة الأحساء بثلاثة أندية هي: هجر، والعدالة، والجيل، وتخوض مبارياتها على ملعبَي نادي هجر ومدينة الأمير عبدالله بن جلوي الرياضية.","من الزلفي إلى حوطة بني تميم تمثّل منطقة الرياض فريقان؛ يخوض الزلفي مبارياته على ملعبه في الزلفي، فيما يستضيف الأنوار مبارياته على ملعبه في حوطة بني تميم."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/fh0xw2v','https://sabq.org/article/fh0xw2v','','https://sabq.org/article/fh0xw2v','صحيفة سبق','السعودية','2026-08-12T08:37:00.000Z','2026-08-12T11:38:00.000Z','2026-08-12T20:15:13.565Z','https://media.sabq.org/news/2026/08/d75560e1-e74b-444e-a02e-c5cb857bbb1b/w680.webp','/api/media/73122c38-dc75-4f36-a8a2-e6b6d0bfc1af','/api/media/73122c38-dc75-4f36-a8a2-e6b6d0bfc1af?variant=thumbnail','9 مناطق و18 ملعبًا تستضيف دوري يلو للمحترفين في موسم 2026-2027',680,453,'valid','published','archived','valid',87,'7dba7f2fd817e582f879c8833d4afad8d6665a6198e418e46320aa15fdc3cc36','1f59a4975fdf17c2c7fb43505faac8acc2abd77221f03ff506517f16fcfac68e',NULL,'2026-08-12T20:15:13.565Z','2026-10-07T21:07:54.571Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض","القصيم"]','["الرياضة السعودية"]','classified','','[{"category":"المناطق","score":4},{"category":"أخبار السعودية","score":1.5},{"category":"التعليم","score":1.5}]','Active','2026-10-07T21:07:54.571Z',200,80,0,'source_article_available','',NULL,NULL,'body:95a05e3b65031fcdd7526b769542b2d1154a1f1f3b3fde74a0845bd5f643a0f2','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2ad97095-5e81-465a-ad37-1c679bf6fb85','news-2ad97095-5e81-465a-ad37-1c679bf6fb85','«توكلنا» يتصدر رضا المستفيدين في مؤشر نضج التجربة الرقمية الحكومية 2026','توكلنا يتصدر رضا المستفيدين في مؤشر نضج التجربه الرقميه الحكوميه 2026','حقّق التطبيق الوطني الشامل «توكلنا» المرتبة الأولى في محور رضا المستفيد ضمن مؤشر نضج التجربة الرقمية للخدمات الحكومية لعام 2026، الصادر عن هيئة الحكومة الرقمية، في إنجاز يعكس مستوى ثقة المستفيدين بالخدمات التي يقدمها التطبيق وما يشهده من تطوير مستمر.','["ودخل «توكلنا» ضمن أعلى عشر منصات رقمية حكومية في النتيجة العامة للمؤشر محتلاً المرتبة الخامسة، كما حلّ تاسعاً في منظور تجربة المستخدم بين أعلى عشر منصات حكومية، بما يعكس قدرة التطبيق على مواكبة احتياجات المستفيدين وتقديم خدمات حكومية عبر تجربة رقمية موحدة ومتكاملة.","ويأتي هذا التقدم امتداداً للتطوير المستمر الذي يشهده التطبيق، الذي يعمل على تجميع الخدمات والمعلومات والوثائق الحكومية في منصة واحدة، وتسهيل الوصول إليها بما يختصر رحلة المستفيد ويرفع كفاءة الاستفادة من الخدمات الحكومية الرقمية.","ويُعدّ مؤشر نضج التجربة الرقمية للخدمات الحكومية أحد المؤشرات التي تطوّرها هيئة الحكومة الرقمية لقياس نضج أبرز المنصات والخدمات الحكومية الرقمية سنوياً، ويستند في تقييمه إلى أربعة مناظير هي: رضا المستفيد، وتجربة المستخدم، والتعامل مع الشكاوى، والتقنيات والأدوات، بهدف دعم الجهات الحكومية في رفع مستوى جودة خدماتها الرقمية."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/8ws1h98','https://sabq.org/article/8ws1h98','','https://sabq.org/article/8ws1h98','صحيفة سبق','السعودية','2026-08-12T08:34:00.000Z','2026-08-12T11:35:00.000Z','2026-08-12T20:15:14.573Z','https://media.sabq.org/news/2026/08/b652803a-95b0-44b7-81ff-404e5f2e2000/w547.webp','/api/media/2ad97095-5e81-465a-ad37-1c679bf6fb85','/api/media/2ad97095-5e81-465a-ad37-1c679bf6fb85?variant=thumbnail','«توكلنا» يتصدر رضا المستفيدين في مؤشر نضج التجربة الرقمية الحكومية 2026',547,365,'valid','published','archived','valid',52,'553e0680b5eb5ed53fe69caf06ee75c87d54fe23cb276f1b017689ef9888690c','9ec60494861db8de773bc083b99880ce391c52f2ed76fc1666c93922aaef7ff6',NULL,'2026-08-12T20:15:14.573Z','2026-10-07T21:07:55.299Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الحكومة الرقمية لقياس نضج","التقنية والتحول الرقمي"]','["هيئة الحكومة الرقمية لقياس نضج","التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"السياسة","score":1.5},{"category":"الصحة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:07:55.299Z',200,77,0,'source_article_available','',NULL,NULL,'body:c44bd1b461199e76ddc12794e78bd6f2f6704cfebc8d97414b51ab1789f3fc93','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f3218fae-25c9-4408-bd76-5771d56cb831','news-f3218fae-25c9-4408-bd76-5771d56cb831','بطولة موسم جدة للشطرنج 2026 تتواصل وأنظار المتنافسين على النهائيات','بطوله موسم جده للشطرنج 2026 تتواصل وانظار المتنافسين علي النهائيات','تتواصل منافسات بطولة موسم جدة للشطرنج 2026 المقامة في ميدان الثقافة بجدة التاريخية، ضمن فعاليات موسم جدة التي تنظمها جمعية كتايا للرياضات الذهنية خلال شهر أغسطس الجاري، بمشاركة لاعبين ولاعبات من مختلف الجنسيات والفئات العمرية.','["وشهدت البطولة منذ انطلاقها منافسات قوية بين المشاركين في أجواء تنافسية تُسهم في تعزيز حضور الرياضات الذهنية ونشر ثقافة الشطرنج بين أفراد المجتمع، فيما تتجه الأنظار إلى الأدوار النهائية المقررة يومي 13 و14 أغسطس الجاري.","وتأتي البطولة ضمن سلسلة من الفعاليات الرياضية والمجتمعية الهادفة إلى اكتشاف المواهب وصقل مهارات اللاعبين، إلى جانب توفير بيئة تنافسية تجمع الاحترافية والتفاعل المجتمعي.","وتتضمن البطولة برامج تعريفية وأنشطة مصاحبة تُسهم في التعريف برياضة الشطرنج وتشجيع ممارستها، بما يعزز انتشار الرياضات الذهنية بين مختلف شرائح المجتمع.","وتسعى البطولة إلى إبراز جدة التاريخية وجهةً للفعاليات الرياضية والثقافية النوعية، من خلال استثمار مكانتها التراثية في تقديم تجربة تجمع المنافسة الرياضية والإثراء الثقافي، بما ينعكس إيجاباً على تجربة الزوار والمشاركين."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wabpl5r','https://sabq.org/article/wabpl5r','','https://sabq.org/article/wabpl5r','صحيفة سبق','السعودية','2026-08-12T08:36:00.000Z','2026-08-12T11:36:00.000Z','2026-08-12T20:15:14.746Z','https://media.sabq.org/news/2026/08/7c91b396-5166-45bf-a312-46aba8e90928/w1600.webp','/api/media/f3218fae-25c9-4408-bd76-5771d56cb831','/api/media/f3218fae-25c9-4408-bd76-5771d56cb831?variant=thumbnail','صورة من الألبوم',1600,1066,'valid','published','archived','valid',49,'77713a5eb2b180cdf788a2dc858c1fa03f21af30cc0603e17c91745c5c7a9375','b9b9f68938f5cc61cc68928aa795467a1dfacaee17eee1c3a5a2630185f15206',NULL,'2026-08-12T20:15:14.746Z','2026-10-07T21:08:05.821Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق","جدة","الرياض"]','["الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":4.5},{"category":"الاقتصاد","score":4},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T21:08:05.821Z',200,77,0,'source_article_available','',NULL,NULL,'body:d639bcb4aa12b1a9c649409a20d6da6cf1483230934f1ac85b39bdae16c43190','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4fcdbe13-536c-49e4-ad88-98851770ff27','news-4fcdbe13-536c-49e4-ad88-98851770ff27','بندر فلقي نائباً للرئيس التنفيذي للعمليات في شركة علاقات للعلاقات العامة والاتصال','بندر فلقي نائبا للرئيس التنفيذي للعمليات في شركه علاقات للعلاقات العامه والاتصال','أعلنت شركة علاقات للعلاقات العامة والاتصال، في الرياض، تعيين بندر بن محمد فلقي نائباً للرئيس التنفيذي للعمليات، استناداً إلى كفاءاته القيادية وخبرته الممتدة في مجالات الاتصال والإعلام وإدارة العمليات والمشاريع.','["ويمتلك فلقي مسيرة مهنية تتجاوز 23 عاماً في قطاع الإعلام والاتصال، تنقّل خلالها بين العمل الصحفي والاتصال المؤسسي، إذ بدأ مشواره في الصحافة وعمل في عدد من المؤسسات الإعلامية البارزة، من بينها المجموعة السعودية للأبحاث والنشر، وصحيفة الرياضي، ومؤسسة عكاظ للصحافة والنشر، متدرجاً في مناصب تحريرية متعددة حتى بلغ منصب مدير تحرير.","وعقب مرحلته الصحفية، انتقل فلقي إلى قيادة أعمال الاتصال والإعلام للمؤسسات والمشاريع الوطنية، مساهماً في بناء استراتيجيات الاتصال، وإدارة السمعة، وتطوير المحتوى، وقيادة الفرق الإعلامية، والتعامل مع مختلف أصحاب المصلحة محلياً ودولياً.","ومنذ انضمامه إلى شركة علاقات في أواخر عام 2021، أسهم في تطوير خدماتها الإعلامية والاتصالية، وتقلّد عدة مناصب قيادية متصاعدة، بدأت بمنصب المشرف العام على إدارة وصناعة المحتوى، ثم رئيساً للعمليات الإعلامية، فمديراً تنفيذياً للإعلام والمشاريع الخاصة، وصولاً إلى منصبه الحالي.","ويأتي هذا التعيين في إطار خطط الشركة التوسعية الرامية إلى تعزيز حضورها في قطاع العلاقات العامة والاتصال، وتقديم حلول اتصالية متكاملة لعملائها داخل المملكة العربية السعودية وخارجها."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/o3yrxk8','https://sabq.org/article/o3yrxk8','','https://sabq.org/article/o3yrxk8','صحيفة سبق','السعودية','2026-08-12T08:26:00.000Z','2026-08-12T11:27:00.000Z','2026-08-12T20:15:16.018Z','https://media.sabq.org/news/2026/08/eb97fe85-eb2f-4e24-95fb-ba38e78e8c53/w1207.webp','/api/media/4fcdbe13-536c-49e4-ad88-98851770ff27','/api/media/4fcdbe13-536c-49e4-ad88-98851770ff27?variant=thumbnail','بندر فلقي نائباً للرئيس التنفيذي للعمليات في شركة علاقات للعلاقات العامة والاتصال',1207,1303,'valid','published','archived','valid',46,'3dd17836de1b6ea74879c26d22ed06e78da9e8f537cae4437b31f798a72dc89a','4a1d438c81bf737d56deec6e66c1fe4594a883e91f080ef3664d5f969cb86361',NULL,'2026-08-12T20:15:16.018Z','2026-10-07T21:11:14.239Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة علاقات للعلاقات العامة والاتصال","الاقتصاد والأسواق","الرياض"]','["شركة علاقات للعلاقات العامة والاتصال","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"الاقتصاد","score":1.5},{"category":"السيارات","score":1.5}]','Active','2026-10-07T21:11:14.239Z',200,80,0,'source_article_available','',NULL,NULL,'body:1f1959753a451df14f48923de99e994ef3d373687423eda3c9f1047fc511845a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4b53ab21-29c1-4b21-a905-8db8a3a14c8f','news-4b53ab21-29c1-4b21-a905-8db8a3a14c8f','الرئيس التنفيذي لجمعية «ترابط» تحصل على الاعتماد الدولي في المسؤولية الاجتماعية','الرئيس التنفيذي لجمعيه ترابط تحصل علي الاعتماد الدولي في المسؤوليه الاجتماعيه','حصلت الدكتورة فاطمة بنت عبد الباقي البخيت، الرئيس التنفيذي لجمعية «ترابط» لرعاية المرضى، على الاعتماد الدولي في المسؤولية الاجتماعية والتنمية المستدامة، الممنوح من مؤسسة اعتماد المسؤولية الاجتماعية البريطانية (CSR Accreditation) بالشراكة مع جامعة «باكنجهامشير نيو» (Buckinghamshire New University) في المملكة المتحدة.','["ويُعدّ هذا البرنامج الأول من نوعه على مستوى إعداد القيادات في مجالَي الاستدامة والمسؤولية المجتمعية، إذ يُمكّن المشاركين من اكتساب المعارف والمهارات المتقدمة اللازمة لتعزيز الممارسات المستدامة، وبناء استراتيجيات ذات أثر ملموس يخدم المجتمع ويدعم مستهدفات التنمية المستدامة.","ويأتي هذا الإنجاز ليعزز مكانة القطاع غير الربحي السعودي على الصعيد الدولي، ويُسهم في رفع كفاءة قياداته وتأهيلهم وفق أعلى المعايير العالمية المعتمدة."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/alhn16r','https://sabq.org/article/alhn16r','','https://sabq.org/article/alhn16r','صحيفة سبق','السعودية','2026-08-12T08:03:00.000Z','2026-08-12T11:04:00.000Z','2026-08-12T20:15:16.261Z','https://media.sabq.org/news/2026/08/240689c5-77f7-4a56-830d-f1086b809597/w1280.webp','/api/media/4b53ab21-29c1-4b21-a905-8db8a3a14c8f','/api/media/4b53ab21-29c1-4b21-a905-8db8a3a14c8f?variant=thumbnail','الرئيس التنفيذي لجمعية «ترابط» تحصل على الاعتماد الدولي في المسؤولية الاجتماعية',1280,854,'valid','published','archived','valid',58,'6324d10619522c6d0012d39a058c67d6f8c315705b9cf86dd0459d402f6489a6','4a5659536ef25ec36d6cf9773b3a320020c7fd13b78747cd4c4cdd0c0f134640','محدّث','2026-08-12T20:15:16.261Z','2026-10-07T21:07:58.941Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السياسة"]','[]','manual_approved','below_category_threshold','[{"category":"العالم","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T21:07:58.941Z',200,78,0,'source_article_available','',NULL,NULL,'body:ad514bd9d6f12acb3d460c6692a1d2527d7e10a2e1d5350e8cc4ee45eb2f42b0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('61ee5ac5-cfb3-4fd2-87ba-985981e6fdb6','news-61ee5ac5-cfb3-4fd2-87ba-985981e6fdb6','أغسطس 90 و اتفاقية مكة','اغسطس 90 و اتفاقيه مكه','إحنا" كبرنا ونحن نسمع هذا السؤال في واحد من أشهر الأوبريتات الوطنية الكويتية، وكانت الإجابة تبدو بسيطة وواثقة، تخرج من أفواه الأطفال قبل أن يعرفوا شيئاً عن موازين القوى والتحالفات، نحن من يحميها.','["ثم جاء أغسطس 1990، وأصبح السؤال الذي غنّيناه يوماً أكثر تعقيداً،عرفنا أن الوطن يحتاج أبناءه، لكنه يحتاج أيضاً إلى محيط آمن، وحلفاء، وشبكة علاقات تتحرك عندما يصبح الخطر أكبر من حدود دولة واحدة.","مرّت ستة وثلاثون عاماً، وتغيّر شكل الخطر، لكن السؤال لم يمت، فالحروب اليوم لا تحتاج دائماً إلى دبابات أو جيوش تعبر الحدود، فقد تبدأ بصاروخ، أو مسيّرة، أو هجوم إلكتروني، أو تهديد لممر بحري، وكلها قادرة على إرباك دولة، وربما منطقة بأكملها.","ولم يعد ذلك احتمالاً نظرياً بعد ما شهده الخليج في 2026، حين امتدت المواجهة مع إيران إلى دول المنطقة، وتعرضت منشآت وقواعد لضربات صاروخية ومسيّرة، وتعطلت الملاحة في مضيق هرمز،يومها اتضح أن الأمن والأمان لا يعني فقط سلامة الحدود وإنما استقرار الدولة بكافة تفاصيلها.","لهذا تستحق اتفاقية مكة للدفاع المشترك، التي وقّعتها السعودية وتركيا وباكستان في السابع من أغسطس، أن تُقرأ بما يتجاوز أسماء الدول الثلاث."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/5ol8evi','https://sabq.org/article/5ol8evi','','https://sabq.org/article/5ol8evi','بدور خالد المطيري','السعودية','2026-08-12T08:32:00.000Z','2026-08-12T11:32:00.000Z','2026-08-12T20:15:16.425Z','https://media.sabq.org/news/2026/08/6c2a7270-e77b-40e9-9b3a-864cdd6e994e/w1600.webp','/api/media/61ee5ac5-cfb3-4fd2-87ba-985981e6fdb6','/api/media/61ee5ac5-cfb3-4fd2-87ba-985981e6fdb6?variant=thumbnail','أغسطس 90 و اتفاقية مكة',1600,893,'valid','published','archived','valid',46,'11664b94457a4b9e13f0a3b455fcd17965be54e5936803b4cda42d5e2d199b1d','4b93b435af5ee231252ee1d9cfc3df735ccec728af034fce852ce38d2977995b',NULL,'2026-08-12T20:15:16.425Z','2026-10-07T21:08:05.904Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","إيران","تركيا"]','[]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الاقتصاد","score":1.5},{"category":"الثقافة","score":1.5}]','Active','2026-10-07T21:08:05.904Z',200,79,0,'source_article_available','',NULL,NULL,'body:7287321c4c22314ab2d6771cbda5ff54c5758211544459ea9246bcaf55e88591','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('726f9f18-ee47-400d-beba-7015240c7b44','news-726f9f18-ee47-400d-beba-7015240c7b44','تحطم مقاتلة تركية إف-16 خلال تدريب في يالوفا ونجاة طيارها','تحطم مقاتله تركيه اف 16 خلال تدريب في يالوفا ونجاه طيارها','تحطمت مقاتلة تركية من طراز إف-16 اليوم خلال رحلة تدريبية في إقليم يالوفا شمال غرب تركيا، وأعلنت وزارة الدفاع التركية نجاة الطيار من الحادث سالماً.','["وأوضحت الوزارة أن الطائرة تحطمت أثناء تنفيذها مهمة تدريبية، مؤكدةً أن التحقيقات اللازمة ستُجرى لتحديد أسباب الحادث.","ولم تُفصح الوزارة حتى الآن عن مزيد من التفاصيل المتعلقة بملابسات الحادث، في انتظار نتائج التحقيق الرسمي."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/irrdrtm','https://sabq.org/article/irrdrtm','','https://sabq.org/article/irrdrtm','صحيفة سبق','السعودية','2026-08-12T08:00:00.000Z','2026-08-12T11:01:00.000Z','2026-08-12T20:15:17.679Z','https://media.sabq.org/news/2026/08/b4ad1422-9a8d-4c37-9b86-dcdedb89271b/w1500.webp','/api/media/726f9f18-ee47-400d-beba-7015240c7b44','/api/media/726f9f18-ee47-400d-beba-7015240c7b44?variant=thumbnail','تحطم مقاتلة تركية إف-16 خلال تدريب في يالوفا ونجاة طيارها',1500,848,'valid','published','archived','valid',46,'fb1e657a15c4883e5a684cb1ec6570fdb283cf16cb0c96c3c02ae966b4a10024','0a2103a22e36c9d5dc09f1f56916fb349ec0ea573518141d9c14b68cb255e363','محدّث','2026-08-12T20:15:17.679Z','2026-10-07T21:07:59.518Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T21:07:59.518Z',200,80,0,'source_article_available','',NULL,NULL,'body:bedd47863f4f580facc056516f8e3d25de9cdb43b543608ffbd9476b85681fc0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e814748b-0d93-4df5-98e2-ad905771bc4f','news-e814748b-0d93-4df5-98e2-ad905771bc4f','الكويت.. إحباط مخطط إرهابي وضبط مواطن منضم إلى «داعش» خطط لاستهداف منشأة حيوية','الكويت احباط مخطط ارهابي وضبط مواطن منضم الي داعش خطط لاستهداف منشاه حيويه','أعلنت وزارة الداخلية الكويتية، الأربعاء، إحباط جهاز أمن الدولة مخططاً إرهابياً كان يستهدف إحدى المنشآت الحيوية في البلاد، وضبط مواطن منضم إلى تنظيم «داعش» الإرهابي قبل تنفيذ مخططه، وذلك في إطار عمليات رصد ومتابعة أمنية دقيقة.','["وكشفت التحريات، وفق بيان الوزارة، أن المتهم تلقّى تدريبات متخصصة في صناعة المفرقعات وتشغيل الطائرات المسيّرة، وأقدم على تصنيع طائرة مسيّرة بقصد توظيفها في استهداف المنشأة الحيوية.","وأفادت الوزارة باتخاذ الإجراءات القانونية اللازمة بحق المتهم، وإحالته إلى جهة الاختصاص لاستكمال التحقيقات واتخاذ ما يلزم وفقاً للقانون.","وأكدت وزارة الداخلية الكويتية استمرار أجهزتها الأمنية في العمل الاستباقي لرصد أي أنشطة أو مخططات من شأنها تهديد أمن البلاد واستقرارها، مشددةً على أنها لن تتهاون مع كل من تسوّل له نفسه المساس بأمن الوطن وسلامة المواطنين والمقيمين، وأنها ستتعامل بحزم مع أي أنشطة مشبوهة وفقاً لأحكام القانون."]','الوظائف وسوق العمل','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/8zzqqkc','https://sabq.org/article/8zzqqkc','','https://sabq.org/article/8zzqqkc','صحيفة سبق','السعودية','2026-08-12T07:49:00.000Z','2026-08-12T10:58:00.000Z','2026-08-12T20:15:18.081Z','https://media.sabq.org/news/2026/08/a039130a-9112-4208-9c32-55ad2d0b1e12/w900.webp','/api/media/e814748b-0d93-4df5-98e2-ad905771bc4f','/api/media/e814748b-0d93-4df5-98e2-ad905771bc4f?variant=thumbnail','الكويت.. إحباط مخطط إرهابي وضبط مواطن منضم إلى «داعش» خطط لاستهداف منشأة حيوية',900,530,'valid','published','archived','valid',44,'98b8c377ba7103c0bd57e50870f14ad976a249512e5a1568d1bba0dea1f1ecb3','d11b22dcd8479dd8093b99293cd2a34ac1e591d2982f69b2bab26443cb5a92fe','محدّث','2026-08-12T20:15:18.081Z','2026-10-07T21:08:01.362Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية الكويتية استمرار أجهزتها","التعليم والتدريب"]','["وزارة الداخلية الكويتية استمرار أجهزتها","التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":3},{"category":"التعليم","score":1.5},{"category":"الطاقة والصناعة","score":1.5}]','Active','2026-10-07T21:08:01.362Z',200,81,0,'source_article_available','',NULL,NULL,'body:d82da5000506cb2467d6c3798f90f1ad24a8b5bfc649feec5c2d5b06fa08e390','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3154448e-7d46-4d5d-a3b0-0e119250e118','news-3154448e-7d46-4d5d-a3b0-0e119250e118','«سيدة السحاب» وجهة سياحية جديدة في الباحة بإطلالات بانورامية على تهامة','سيده السحاب وجهه سياحيه جديده في الباحه باطلالات بانوراميه علي تهامه','أطلقت أمانة منطقة الباحة مشروع «سيدة السحاب»، أحد مشروعاتها الاستثمارية النوعية، وجهةً سياحية بارزة لزوار موسم صيف الباحة؛ إذ يتربّع في موقع مرتفع داخل متنزه الخلب بمحافظة المندق، مانحاً زواره إطلالات بانورامية تمتد نحو سهول تهامة وأجزاء واسعة من المحافظة.','["يمتد المشروع على مساحة تتجاوز 29 ألف متر مربع، ويتميز بطابع معماري ينسجم مع طبيعة المنطقة، فيما يتيح تصميمه الدائري للزوار مشاهدة المناظر المحيطة من زوايا متعددة.","وتجمع إطلالاته بين السحب والضباب والطبيعة الجبلية وسهول تهامة، مما يجعله وجهة مفضّلة لهواة التصوير والباحثين عن المشاهد الطبيعية الخلّابة.","ويضم المشروع 15 مجسّماً جمالياً مخصصاً للتصوير، استُلهم عدد منها من بيئة الباحة وهويتها الطبيعية، لتشكّل نقاط جذب بصرية تتيح للزوار التقاط الصور التذكارية وسط الطبيعة المحيطة.","وتشتمل مرافق المشروع على حديقة خارجية، و30 جلسة مغلقة ومستقلة توفر الخصوصية للزوار، إضافةً إلى مطعمين، وثلاثة مقاهٍ، وسبعة أكشاك للأسر المنتجة، ومطعم خارجي."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/unvpxod','https://sabq.org/article/unvpxod','','https://sabq.org/article/unvpxod','صحيفة سبق','السعودية','2026-08-12T07:46:00.000Z','2026-08-12T10:47:00.000Z','2026-08-12T20:15:18.159Z','https://media.sabq.org/news/2026/08/880f7e58-5dde-4636-bc5e-81a07a34c182/w1600.webp','/api/media/3154448e-7d46-4d5d-a3b0-0e119250e118','/api/media/3154448e-7d46-4d5d-a3b0-0e119250e118?variant=thumbnail','صورة من الألبوم',1600,1066,'valid','published','archived','valid',88,'857f61433652ff62de19e219780356fd0269d0c4a914a3117204e3bf0068deed','2dd062bf32e5fa7d77aa43cec1a7bdc643ffa451a0731b0bc956726c0c19e6b0','محدّث','2026-08-12T20:15:18.159Z','2026-10-07T21:08:05.144Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الباحة"]','[]','classified','','[{"category":"المناطق","score":7},{"category":"الصحة","score":1.5},{"category":"السيارات","score":1.5}]','Active','2026-10-07T21:08:05.144Z',200,75,0,'source_article_available','',NULL,NULL,'body:8290acba3188288acd71d1ae9df31a9583f8b08d5e1922634680ad8c56b38d9c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('78b2d5eb-bccf-49e7-a5d0-1c49adaee52c','news-78b2d5eb-bccf-49e7-a5d0-1c49adaee52c','مؤشر الأسهم السعودية يرتفع 10.94 نقطة ويُغلق عند 10844 نقطة','مؤشر الاسهم السعوديه يرتفع 10 94 نقطه ويغلق عند 10844 نقطه','أغلق مؤشر الأسهم السعودية الرئيس مرتفعاً بمقدار 10.94 نقطة، ليقفل عند مستوى 10844.12 نقطة، بتداولات بلغت قيمتها 5 مليارات ريال.','["وبلغت كمية الأسهم المتداولة 256 مليون سهم، وفق النشرة الاقتصادية اليومية لوكالة الأنباء السعودية، سجّلت فيها أسهم 141 شركة ارتفاعاً في قيمتها، فيما أغلقت أسهم 112 شركة على تراجع.","وجاءت أسهم شركات «تبوك الزراعية» و«مدينة المعرفة» و«الأسماك» و«جازادكو» و«ثمار» الأكثر ارتفاعاً، في حين تصدّرت أسهم شركات «لازوردي» و«أسواق العثيم» و«دراية» و«إكسترا» و«سابك» قائمة الأكثر انخفاضاً، وتراوحت نسب الارتفاع والانخفاض بين 4.31% و10%.","وعلى صعيد النشاط، احتلّت أسهم شركات «أمريكانا» و«بترو رابغ» و«الرياض» و«أسواق العثيم» و«الصناعات الكهربائية» المراتب الأولى من حيث الكمية، فيما تصدّرت أسهم «بترو رابغ» و«الرياض» و«الراجحي» و«الأسماك» و«أرامكو السعودية» قائمة الأكثر نشاطاً من حيث القيمة.","في المقابل، أغلق مؤشر الأسهم السعودية الموازية «نمو» مرتفعاً بمقدار 113.43 نقطة، ليقفل عند مستوى 21781.04 نقطة، بتداولات بلغت قيمتها 28 مليون ريال، وبكمية أسهم متداولة بلغت 2.7 مليون سهم."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/oj3g9se','https://sabq.org/article/oj3g9se','','https://sabq.org/article/oj3g9se','صحيفة سبق','السعودية','2026-08-12T07:37:00.000Z','2026-08-12T10:40:00.000Z','2026-08-12T20:15:19.202Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/32e171d7-196f-4eef-cfac-5f0083425200/public','/api/media/78b2d5eb-bccf-49e7-a5d0-1c49adaee52c','/api/media/78b2d5eb-bccf-49e7-a5d0-1c49adaee52c?variant=thumbnail','مؤشر الأسهم السعودية يرتفع 10.94 نقطة ويُغلق عند 10844 نقطة',2400,1339,'valid','published','archived','valid',56,'c8180359d91c67d3824a0e5fd1e9f86ca2bdea914d31ef931eff73e7d0e245fc','28846ba845c25a19cc440ae9f14ad8ec1cdea6fc195b670c8749e78e03a43110','محدّث','2026-08-12T20:15:19.202Z','2026-10-07T21:08:01.358Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة ارتفاعا في قيمتها فيما","الاقتصاد والأسواق","تبوك","الرياض"]','["شركة ارتفاعا في قيمتها فيما","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":3},{"category":"التقنية","score":2}]','Active','2026-10-07T21:08:01.358Z',200,78,0,'source_article_available','',NULL,NULL,'body:253b89cc3979b283edeb24d3d09a696a50bcd6ef81b0febe465a507d953a9600','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a254c58c-ab41-4087-977a-c2d5cdc5c59c','news-a254c58c-ab41-4087-977a-c2d5cdc5c59c','أمطار ورياح ورعد.. الأرصاد تحذّر من حالة جوية تشمل الرياض ومحيطها','امطار ورياح ورعد الارصاد تحذر من حاله جويه تشمل الرياض ومحيطها','نبّه المركز الوطني للأرصاد من هطول أمطار خفيفة على منطقة الرياض، تصحبها رياح نشطة وتدنٍّ في مدى الرؤية الأفقية وصواعق رعدية.','["وأوضح المركز أن الحالة الجوية تستمر حتى الساعة الثامنة مساءً، وتشمل كلاً من: العاصمة الرياض، والدرعية، والحريق، والخرج، والدلم، والمزاحمية، وحوطة بني تميم، وحريملاء، وضرما."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ktl7jwt','https://sabq.org/article/ktl7jwt','','https://sabq.org/article/ktl7jwt','صحيفة سبق','السعودية','2026-08-12T07:38:00.000Z','2026-08-12T10:39:00.000Z','2026-08-12T20:15:19.469Z','https://media.sabq.org/news/2026/08/834624de-faf3-4a6f-9db9-03cb506ae567/w1200.webp','/api/media/a254c58c-ab41-4087-977a-c2d5cdc5c59c','/api/media/a254c58c-ab41-4087-977a-c2d5cdc5c59c?variant=thumbnail','أمطار ورياح ورعد.. الأرصاد تحذّر من حالة جوية تشمل الرياض ومحيطها',1200,676,'valid','published','archived','valid',44,'5f1cb843a07b34499af9a6021f1510b80b9e76a4081d3837919f3f2f2e11cf7a','964322aeb1305d7acc1904b13b248b04306c1b4205f3c314022d66ce893eaafe','محدّث','2026-08-12T20:15:19.469Z','2026-10-07T21:08:00.613Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","الرياض"]','["الطقس والمناخ"]','manual_approved','below_category_threshold','[{"category":"السفر","score":3},{"category":"البيئة والمناخ","score":3},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:08:00.613Z',200,80,0,'source_article_available','',NULL,NULL,'body:c252003a4c4302cb006b11d787484eab7ce14510135f860377d7766d5660f000','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5ad7973f-71d9-47e7-94b5-33ecd6b95a47','news-5ad7973f-71d9-47e7-94b5-33ecd6b95a47','"بر جدة" وجمعية عاصم توقعان مذكرة تعاون لتأهيل وتمكين الأيتام','بر جده وجمعيه عاصم توقعان مذكره تعاون لتاهيل وتمكين الايتام','وقّعت جمعية البر بجدة مذكرة تعاون مع جمعية عاصم لتأهيل وتمكين الأيتام بمنطقة مكة المكرمة، بهدف تعزيز فرص التأهيل والتمكين الوظيفي للأيتام المسجلين لدى الجمعية، وتهيئتهم للانخراط في سوق العمل بما يتناسب مع مؤهلاتهم وقدراتهم، في إطار من الشراكة التكاملية بين منظمات القطاع غير الربحي.','["مثّل جمعية البر بجدة في توقيع المذكرة الرئيس التنفيذي بالإنابة الأستاذ مبارك حسين آل سراج، فيما مثّل جمعية عاصم المدير التنفيذي الدكتور عبد الله بن عجلان الشهري.","وتنص المذكرة على تقديم جمعية عاصم حزمة متكاملة من البرامج والدورات التدريبية والتأهيلية لمستفيدي جمعية البر بجدة، بما يسهم في تطوير مهاراتهم ورفع جاهزيتهم المهنية، وصولاً إلى توظيفهم في الفرص الوظيفية الملائمة لتخصصاتهم ومؤهلاتهم عبر منصة عصامي، بما يعزز استقلاليتهم الاقتصادية ويدعم انتقالهم من مرحلة الرعاية إلى التمكين.","كما تتيح المذكرة فرصاً لمشاركة منسوبي الجمعيتين ومستفيديهما في مختلف المناسبات والبرامج والفعاليات، بما يسهم في تبادل التجارب والخبرات، وتوسيع مجالات التعاون المشترك، والاستفادة من الإمكانات والخبرات المتاحة لدى الجانبين.","ويأتي توقيع المذكرة امتداداً لنهج الجمعيتين في بناء الشراكات الفاعلة مع مختلف مكونات القطاع غير الربحي، وتطوير منظومة متكاملة لخدمة المستفيدين، بما يواكب التحول من مفهوم تقديم الرعاية إلى صناعة الأثر المستدام، ويعزز فرص التمكين والتنمية الذاتية للمستفيدين."]','الوظائف وسوق العمل','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/yupzwhy','https://sabq.org/article/yupzwhy','','https://sabq.org/article/yupzwhy','صحيفة سبق','السعودية','2026-08-12T07:44:00.000Z','2026-08-12T10:45:00.000Z','2026-08-12T20:15:19.485Z','https://media.sabq.org/news/2026/08/f9fd5711-4223-4ff3-aa6c-1cdecc3a8bd6/w1600.webp','/api/media/5ad7973f-71d9-47e7-94b5-33ecd6b95a47','/api/media/5ad7973f-71d9-47e7-94b5-33ecd6b95a47?variant=thumbnail','صورة من الألبوم',1600,898,'valid','published','archived','valid',49,'93d55a50e05669b4152eb99c80898deaadc6483187b6219c7718132610dbfde4','8ab37f278e130e0e408c95ce931518afd3524615ae3d4503ab9b9750e969cfec','محدّث','2026-08-12T20:15:19.485Z','2026-10-07T21:11:19.414Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الاقتصاد والأسواق","جدة"]','["التعليم والتدريب","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":4.5},{"category":"المناطق","score":3},{"category":"أخبار السعودية","score":1.5}]','Active','2026-10-07T21:11:19.414Z',200,81,0,'source_article_available','',NULL,NULL,'body:4954fa478a04116ef3054c4f91704fbcb34fdc25e09a8eb3c3c503d591b93a24','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e738b750-b337-4e19-82a4-3490d9e7fba0','news-e738b750-b337-4e19-82a4-3490d9e7fba0','كريستيانو رونالدو يتوج قصة حبه مع جورجينا بالزواج.. وغياب مرتقب عن أولى مباريات النصر','كريستيانو رونالدو يتوج قصه حبه مع جورجينا بالزواج وغياب مرتقب عن اولي مباريات النصر','أعلن كريستيانو رونالدو وخطيبته جورجينا رودريغيز زواجهما رسمياً عبر حساباتهما على منصات التواصل الاجتماعي، بعد أن عقدا قرانهما في مراسم خاصة وحميمية أُقيمت في البرتغال بحضور المقربين منهما، وذلك عقب نحو 10 سنوات من الارتباط العاطفي.','["وبحسب ما أوردته صحيفة «الرياضية»، فإن النجم البرتغالي سيغيب عن أول مباراتين لنادي النصر في الموسم الرياضي الجديد 2026-2027، على أن يعود إلى صفوف الفريق عقب انتهاء فترة الإجازة الإضافية الممنوحة له.","وكان رونالدو قد حصل على فترة راحة إضافية إثر مشاركته مع منتخب البرتغال في كأس العالم 2026، مما أبعده عن جزء من البرنامج الإعدادي للنصر للموسم الجديد، قبل أن يستثمر هذه الفترة في إتمام زفافه بجورجينا.","وكان النصر قد انطلق في استعداداته للموسم الجديد خلال يوليو الماضي، إذ أقام المرحلة الأولى من تحضيراته في مدينة أبها، ثم انتقل إلى البرتغال لخوض المرحلة الخارجية من معسكره الإعدادي، ضمن برنامج شامل يهدف إلى تجهيز الفريق للمنافسة على مختلف البطولات."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/186b1j2','https://sabq.org/article/186b1j2','','https://sabq.org/article/186b1j2','صحيفة سبق','السعودية','2026-08-12T11:03:00.000Z','2026-08-12T14:03:00.000Z','2026-08-12T22:21:14.676Z','https://media.sabq.org/news/2026/08/977c9726-c020-4f06-9619-1a36a565a3f3/w679.webp','/api/media/e738b750-b337-4e19-82a4-3490d9e7fba0','/api/media/e738b750-b337-4e19-82a4-3490d9e7fba0?variant=thumbnail','كريستيانو رونالدو يتوج قصة حبه مع جورجينا بالزواج.. وغياب مرتقب عن أولى مباريات النصر',679,452,'valid','published','archived','valid',89,'244c3cb8f951f247b514f24f29b0be0cf7728445367e75cab4d80054320ffaa3','51743c68b70a4ac4047a1864f150b7d408cca6c53f3c425b971dc56de93a1400',NULL,'2026-08-12T22:21:14.676Z','2026-10-07T21:01:55.107Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T21:01:55.107Z',200,84,0,'source_article_available','',NULL,NULL,'body:df76ed8747ecd32f2d0772a311225b1520a90168ffde384e076b68df5f9f034a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f1d72902-d489-4a92-8296-c1b7da3e278a','news-f1d72902-d489-4a92-8296-c1b7da3e278a','الفتح يتعاقد مع الدولي السلوفاكي هراسلين حتى 2029','الفتح يتعاقد مع الدولي السلوفاكي هراسلين حتي 2029','أعلن نادي الفتح تعاقده مع المهاجم الدولي السلوفاكي لوكاس هراسلين، البالغ من العمر 30 عاماً، قادماً من نادي سبارتا براغ التشيكي، في إطار تدعيم صفوف الفريق الأول لكرة القدم استعداداً لمنافسات الموسم الرياضي 2026-2027.','["ويُعدّ هراسلين أحد أبرز عناصر منتخب سلوفاكيا، إذ يمتلك رصيداً دولياً واسعاً شارك خلاله في عدد من الاستحقاقات الأوروبية والدولية، ويُصنَّف ضمن أبرز العناصر الهجومية في المنتخب السلوفاكي.","وخاض هراسلين مسيرة احترافية حافلة في عدد من الدوريات الأوروبية، بدأها مع بارما الإيطالي، ثم انتقل إلى ليخيا غدانسك البولندي، قبل أن يعود إلى الدوري الإيطالي مع ساسولو، ليلتحق بعدها بسبارتا براغ عام 2021 حيث أصبح أحد ركائز الفريق الأساسية.","وقدّم اللاعب مستويات لافتة خلال سنواته مع سبارتا براغ، وأسهم في تحقيق الفريق لقب الدوري التشيكي في موسمَي 2022-2023 و2023-2024، إلى جانب التتويج بكأس التشيك في موسم 2023-2024، كما سجّل 13 هدفاً في 27 مباراة بالدوري خلال موسم 2025-2026."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/9dmggoa','https://sabq.org/article/9dmggoa','','https://sabq.org/article/9dmggoa','صحيفة سبق','السعودية','2026-08-12T10:56:00.000Z','2026-08-12T13:57:00.000Z','2026-08-12T22:21:15.830Z','https://media.sabq.org/news/2026/08/ccb33d99-554b-4396-9ff7-fc79eb1b6094/w1280.webp','/api/media/f1d72902-d489-4a92-8296-c1b7da3e278a','/api/media/f1d72902-d489-4a92-8296-c1b7da3e278a?variant=thumbnail','الفتح يتعاقد مع الدولي السلوفاكي هراسلين حتى 2029',1280,1024,'valid','published','archived','valid',59,'61e74050ca9b1fce7725cf489bcaedc930bbc7ca27cd8477d3a6033ba7b80e08','c11ca4eab9b86aaf2055c2e9e92186fe46530504526036e3e4767180eb280684',NULL,'2026-08-12T22:21:15.830Z','2026-10-07T21:02:17.378Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الاقتصاد والأسواق"]','["الرياضة السعودية","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الصحة","score":0},{"category":"التعليم","score":0}]','Active','2026-10-07T21:02:17.378Z',200,82,0,'source_article_available','',NULL,NULL,'body:b7ceb00ec1b97943dc8809de3dd28724e1f1e5eb784f0cf1c4b429d6787598ef','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('06eec6bc-e6e6-47f3-a8d7-6beb38e7121d','news-06eec6bc-e6e6-47f3-a8d7-6beb38e7121d','«آفاق الخير» تختتم ناديها الصيفي بـ 296 برنامجًا وأكثر من 350 طالبًا','افاق الخير تختتم ناديها الصيفي بـ 296 برنامجا واكثر من 350 طالبا','أسدلت جمعية آفاق الخير الشبابية بجدة الستار على فعاليات «نادي آفاق الصيفي الثاني 2026»، الذي استهدف استثمار أوقات الشباب والطلاب خلال الإجازة الصيفية، وتنمية مهاراتهم وقدراتهم عبر برامج تعليمية وتدريبية ورياضية متنوعة.','["وجاء الاختتام خلال حفل أُقيم مساء أمس، بحضور نائب مدير مركز التنمية الاجتماعية بجدة علي الأسمري، وعدد من منسوبي الجمعية والجهات ذات العلاقة وأولياء الأمور، احتفاءً بأكثر من 350 طالبًا خاضوا تجربة صيفية جمعت بين التعلم والمتعة وتنمية المهارات.","وأُقيم النادي بإشراف المجلس التخصصي للجمعيات الشبابية، وقدّم خلال فترة تنفيذه 296 برنامجًا وفعالية بإجمالي 598 ساعة تنفيذية، اشتملت على 82 ورشة ولقاءً تدريبيًا، و76 منافسة ومسابقة عزّزت روح التنافس بين المشاركين، وأسفرت عن تقديم 117 جائزة للفائزين، فضلًا عن 80 نشاطًا رياضيًا رسّخ قيم اللياقة البدنية والعمل الجماعي.","وصُمِّمت البرامج والأنشطة ضمن مسارات متكاملة، هدفت إلى صقل مهارات المشاركين واكتشاف مواهبهم وتنمية قدراتهم الشخصية والاجتماعية، بما يعزز الاستفادة من الإجازة الصيفية ويوفر بيئة محفزة للشباب.","وشهد الحفل الختامي استعراضًا لأبرز منجزات النادي ومخرجاته، إلى جانب تكريم المشاركين والجهات والأفراد المساهمين في إنجاح فعالياته، تقديرًا لجهودهم في تحقيق أهداف النادي."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/LHqIi3H','https://sabq.org/article/LHqIi3H','','https://sabq.org/article/LHqIi3H','عبدالحكيم شار','السعودية','2026-08-12T10:47:00.000Z','2026-08-12T13:47:00.000Z','2026-08-12T22:21:16.086Z','https://media.sabq.org/news/2026/08/bf4271ac-c8ee-48d4-a800-6bfd5d263f19/w1280.webp','/api/media/06eec6bc-e6e6-47f3-a8d7-6beb38e7121d','/api/media/06eec6bc-e6e6-47f3-a8d7-6beb38e7121d?variant=thumbnail','«آفاق الخير» تختتم ناديها الصيفي بـ 296 برنامجًا وأكثر من 350 طالبًا',1280,854,'valid','published','archived','valid',49,'ceaa6710fdcaed91ee3dd57d634e77cc9371b666a45877b9416644f0e7bc7c46','35ab0561228ea7dcb08602f4953f91d263348d226bc3b0b263318a8c7dade616',NULL,'2026-08-12T22:21:16.086Z','2026-10-07T21:07:53.879Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","التعليم والتدريب","الرياضة السعودية","جدة"]','["السفر والسياحة","التعليم والتدريب","الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":4},{"category":"الرياضة","score":3},{"category":"التعليم","score":1.5}]','Active','2026-10-07T21:07:53.879Z',200,82,0,'source_article_available','',NULL,NULL,'body:5f569a3662105d7813c9d4f45ea73470f5bade47ee42de544895a0989abf722a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1c301129-634c-4c12-b9b8-b5d94e777396','news-1c301129-634c-4c12-b9b8-b5d94e777396','الذهب يتجاوز 4416 دولاراً مدعوماً بضعف الدولار وتوقعات تثبيت الفائدة','الذهب يتجاوز 4416 دولارا مدعوما بضعف الدولار وتوقعات تثبيت الفائده','ارتفعت أسعار الذهب اليوم مدعومةً بانخفاض الدولار وتوقعات تثبيت أسعار الفائدة في الولايات المتحدة الأمريكية.','["وصعد الذهب في المعاملات الفورية إلى 4416.29 دولاراً للأوقية، فيما ارتفعت العقود الأمريكية الآجلة للذهب بنسبة 0.8% لتصل إلى 4476.10 دولاراً للأوقية.","وعلى صعيد المعادن النفيسة الأخرى، ارتفعت الفضة في المعاملات الفورية بنسبة 1.9% إلى 65.87 دولاراً للأوقية، فيما صعد البلاتين 1.6% ليبلغ 1380.75 دولاراً للأوقية."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ut5qu4k','https://sabq.org/article/ut5qu4k','','https://sabq.org/article/ut5qu4k','صحيفة سبق','السعودية','2026-08-12T10:27:00.000Z','2026-08-12T13:28:00.000Z','2026-08-12T22:21:17.182Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/c0433d79-06e1-4a2c-99a6-2c7a540ed500/public','/api/media/1c301129-634c-4c12-b9b8-b5d94e777396','/api/media/1c301129-634c-4c12-b9b8-b5d94e777396?variant=thumbnail','الذهب يتجاوز 4416 دولاراً مدعوماً بضعف الدولار وتوقعات تثبيت الفائدة',770,513,'valid','published','archived','valid',47,'491f7bdb96a853b949e600ff77fd8b35d8151d538e0a2e6713481c28b97d0ba3','e273e50112e8b078ea76a3164c6539a1357e907424586147f6ed7f35d5e862cc',NULL,'2026-08-12T22:21:17.182Z','2026-10-07T21:07:59.457Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T21:07:59.457Z',200,80,0,'source_article_available','',NULL,NULL,'body:afdfa87f4149e2e11f2b7107e7b9d155ae452d56fb48b9f9f9acd45ff1e7853b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3268c31a-4a98-44e7-b44e-87a683c82486','news-3268c31a-4a98-44e7-b44e-87a683c82486','خبيرة في الأبنية الخضراء: المدرسة الخضراء تبدأ من المبنى لا من الشجرة','خبيره في الابنيه الخضراء المدرسه الخضراء تبدا من المبني لا من الشجره','أكدت ماجدة بنت عبدالهادي القاضي، زميلة «سعف» وعضو المنتدى السعودي للأبنية الخضراء، أن مفهوم «المدرسة الخضراء» يتجاوز التشجير وإعادة التدوير والأنشطة التوعوية، ليشمل المبنى التعليمي وكفاءة تشغيله وجودة البيئة الداخلية، إلى جانب التعليم والحوكمة والشراكات المجتمعية.','["وأوضحت القاضي في تصريح لـ«سبق»، أن اليونسكو طوّرت ضمن «شراكة تخضير التعليم» معياراً موحداً لتعريف المدرسة الخضراء، يقوم على نهج شامل يغطي التدريس والمرافق والتشغيل والحوكمة والشراكات المجتمعية، وليس الجانب التوعوي أو التشجير فقط.","وأشارت إلى أن اليونسكو تستهدف أن تعتمد كل دولة عضو مدارس خضراء بنسبة لا تقل عن 50% بحلول عام 2030، مبيّنةً أن أكثر من 110 آلاف مدرسة حول العالم انسجمت حتى الآن مع هذا المعيار، فيما أفادت بأنه لا تتوفر لديها بيانات موثقة عن عدد المدارس السعودية الحاصلة على هذا الاعتماد حتى تاريخه.","جهود بيئية وفجوة في المفهوم وبيّنت القاضي أن القطاع التعليمي شهد خلال السنوات الماضية مبادرات وممارسات بيئية داخل المدارس، من بينها التشجير وإعادة التدوير والأنشطة التوعوية، غير أن هذه الممارسات كانت في كثير من الأحيان تُقدَّم باعتبارها التجسيد الكامل لمفهوم «المدرسة الخضراء».","وأضافت أن مقارنة هذه الجهود بالتعريف الأشمل الذي تتبناه اليونسكو تكشف عن فجوة بين الواقع والمأمول، مؤكدةً أن هذه الفجوة لا تعني غياب الجهود، وإنما ترتبط بـ«غياب الوجهة وتشتت التطبيق»، مع تركيز ملحوظ على الجوانب المرئية، في حين يظل الجانب المرتبط بالمبنى نفسه أقل حضوراً في الوعي العام، لا سيما ما يتعلق بكفاءة الطاقة وإدارة المياه وجودة الهواء والإضاءة الداخلية."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7K20wNs','https://sabq.org/article/7K20wNs','','https://sabq.org/article/7K20wNs','عبدالحكيم شار','السعودية','2026-08-12T10:37:00.000Z','2026-08-12T13:37:00.000Z','2026-08-12T22:21:17.336Z','https://media.sabq.org/news/2026/08/ef85a29e-5672-44bd-87ae-69ab78f5f9a2/w1170.webp','/api/media/3268c31a-4a98-44e7-b44e-87a683c82486','/api/media/3268c31a-4a98-44e7-b44e-87a683c82486?variant=thumbnail','خبيرة في الأبنية الخضراء: المدرسة الخضراء تبدأ من المبنى لا من الشجرة',1170,1589,'valid','published','archived','valid',85,'db03442d001555f8764bbf452f0b0fbc4dde706e32c27274275e8b8f0dec86a7','cf05b36cea4386fc103618ec0ffb34b8090e0360dd653e70f34e6f598aa1cbc5',NULL,'2026-08-12T22:21:17.336Z','2026-10-07T21:07:53.350Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","التعليم والتدريب"]','["الطاقة والنفط","التعليم والتدريب"]','classified','','[{"category":"المجتمع","score":5.5},{"category":"أخبار السعودية","score":3},{"category":"الصحة","score":1.5}]','Active','2026-10-07T21:07:53.350Z',200,84,0,'source_article_available','',NULL,NULL,'body:888e2c327206cfcdc0dc5dc7d0fe538d0ae5197a305479567db1cd485138e859','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6e3a6621-6b7c-4d62-bfcb-13ed1285c21d','news-6e3a6621-6b7c-4d62-bfcb-13ed1285c21d','جمعية نماء المكية تحصل على وثيقة تأسيس وحدة الإسناد الحكومي','جمعيه نماء المكيه تحصل علي وثيقه تاسيس وحده الاسناد الحكومي','حصلت جمعية نماء المكية للسقاية والرفادة على «وثيقة تأسيس وحدة الإسناد الحكومي»، في إنجاز نوعي يُضاف إلى مسيرتها، ضمن المشروع الوطني لتأسيس وحدات الإسناد الحكومي في المنظمات غير الربحية، المدعوم من صندوق دعم الجمعيات.','["وأكد رئيس مجلس إدارة الجمعية الدكتور عبدالعزيز بن محمد الغامدي أن منح هذه الوثيقة جاء بعد استيفاء الجمعية كامل المتطلبات والمعايير التنظيمية اللازمة، مشيراً إلى أن الإسناد الحكومي يعزز دور الجمعية بوصفها شريكاً فاعلاً في التنمية الوطنية، ويرفع جودة خدماتها ويحقق استدامتها المالية.","وأضاف الغامدي أن الجمعية ستُسهم عبر هذا الإسناد في تعزيز التعاون مع منظمات القطاع غير الربحي، بما ينعكس إيجاباً على المجتمع المحلي ويدعم ازدهار الاقتصاد الوطني.","ووجّه الغامدي شكره للمركز الوطني لتنمية القطاع غير الربحي على جهوده في تفعيل منظومة الإسناد الحكومي، مؤكداً أنها تصبّ في تحقيق مستهدفات رؤية السعودية 2030 من خلال رفع كفاءة الخدمات التنموية وتعزيز استدامتها المالية.","كما أثنى على جهود أعضاء الجمعية العمومية ومجلس الإدارة وفريق العمل، معتبراً هذا الإنجاز مرحلةً انتقالية في مأسسة العمل المؤسسي وتطوير الأداء، في خدمة ضيوف الرحمن."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/f5VBR-k','https://sabq.org/article/f5VBR-k','','https://sabq.org/article/f5VBR-k','فهد العتيبي','السعودية','2026-08-12T10:46:00.000Z','2026-08-12T13:46:00.000Z','2026-08-12T22:21:17.937Z','https://media.sabq.org/news/2026/08/3e4f9247-01dc-456c-80d5-33cc4c37607e/w1536.webp','/api/media/6e3a6621-6b7c-4d62-bfcb-13ed1285c21d','/api/media/6e3a6621-6b7c-4d62-bfcb-13ed1285c21d?variant=thumbnail','جمعية نماء المكية تحصل على وثيقة تأسيس وحدة الإسناد الحكومي',1536,1024,'valid','published','archived','valid',58,'3a9208d892268d37918d57623bdacf77a461fed44625e045f0ce53515e42b32c','b75c4d7c9e9e9b45fea9ca767c8b175fb592ddec5b3c297cb9370533b527c185',NULL,'2026-08-12T22:21:17.937Z','2026-10-07T21:07:58.919Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس إدارة الجمعية الدكتور","مجلس إدارة الجمعية الدكتور عبدالعزيز","الاقتصاد والأسواق"]','["رئيس مجلس إدارة الجمعية الدكتور","مجلس إدارة الجمعية الدكتور عبدالعزيز","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الاقتصاد","score":1.5},{"category":"الرياضة","score":1.5}]','Active','2026-10-07T21:07:58.919Z',200,83,0,'source_article_available','',NULL,NULL,'body:d250af0adf1324398b31daa7b5aea9dac67c7b55e580a9f7a428de260dffe59e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('62a258ab-a472-4818-b43f-b22dc9f8bf2c','news-62a258ab-a472-4818-b43f-b22dc9f8bf2c','163 لاعباً من 9 دول يتنافسون في بطولة السعودية الكبرى للمبارزة بالدمام','163 لاعبا من 9 دول يتنافسون في بطوله السعوديه الكبري للمبارزه بالدمام','تنطلق غداً الخميس منافسات بطولة السعودية الكبرى للمبارزة في صالة المبارزة بمدينة الأمير سعود بن جلوي الرياضية بالدمام، وتستمر على مدى ثلاثة أيام، بمشاركة 163 لاعباً ولاعبة يمثلون 9 دول، هي: السعودية والبحرين وقطر والكويت والإمارات ومصر وعُمان وتشاد والجزائر.','["ويتنافس المشاركون في الأسلحة الثلاثة: سلاح الإبيه، والسيبر، والشيش، وسط مشاركة واسعة في مختلف المنافسات التي يتضمنها برنامج البطولة.","وتُعدّ بطولة السعودية الكبرى من البطولات المفتوحة أمام اللاعبين واللاعبات من مختلف الجنسيات، بهدف منح المبارزين السعوديين فرصة الاحتكاك بمنافسين من مدارس متنوعة، ورفع مستوى التنافس والخبرة الفنية.","وعلى هامش البطولة، يُكرَّم 30 لاعباً ولاعبة من أبطال الموسم الماضي، ممن أحرزوا المركز الأول في مختلف الفئات العمرية، تقديراً لإنجازاتهم خلال الموسم المنصرم."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/vj3a5t8','https://sabq.org/article/vj3a5t8','','https://sabq.org/article/vj3a5t8','صحيفة سبق','السعودية','2026-08-12T10:25:00.000Z','2026-08-12T13:27:00.000Z','2026-08-12T22:21:19.099Z','https://media.sabq.org/news/2026/08/1d691e88-6e24-4e1f-b7de-a90ab199e268/w1200.webp','/api/media/62a258ab-a472-4818-b43f-b22dc9f8bf2c','/api/media/62a258ab-a472-4818-b43f-b22dc9f8bf2c?variant=thumbnail','163 لاعباً من 9 دول يتنافسون في بطولة السعودية الكبرى للمبارزة بالدمام',1200,675,'valid','published','archived','valid',56,'f226c29718d51414c5cd538f8ae2878bc406541647a8807de389b31d0d3e55c8','090d10239dea8aa47727b2395aebebccf817f029d2c47128045bfb935884dd2f',NULL,'2026-08-12T22:21:19.099Z','2026-10-07T21:08:00.603Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الدمام"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":3},{"category":"الثقافة","score":1.5}]','Active','2026-10-07T21:08:00.603Z',200,79,0,'source_article_available','',NULL,NULL,'body:6d0789b6a68e131fe9438d80892d90742cbd9038c7c42c01203d4898e884a470','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cf89b7f7-2cce-49af-b75b-69adf5ddc853','news-cf89b7f7-2cce-49af-b75b-69adf5ddc853','5 أندية سعودية في دوري أبطال آسيا للنخبة 2026-2027 لأول مرة تاريخياً','5 انديه سعوديه في دوري ابطال اسيا للنخبه 2026 2027 لاول مره تاريخيا','تُسجّل الأندية السعودية حضوراً تاريخياً غير مسبوق في دوري أبطال آسيا للنخبة 2026-2027، بمشاركة خمسة أندية في نسخة واحدة للمرة الأولى في تاريخ المشاركات السعودية، في رقم يعكس المستوى الفني الرفيع الذي باتت تقدمه الأندية السعودية على مستوى القارة الآسيوية.','["ويأتي هذا الحضور التاريخي في ظل استمرار المملكة في صدارة تصنيف الاتحاد الآسيوي لكرة القدم لمسابقات الأندية للموسم السادس على التوالي، وفق التحديث الأخير للتصنيف، بفضل النتائج المتميزة التي حققتها الأندية السعودية خلال مشاركاتها في السنوات الأخيرة.","وتأهّل نادي الأهلي بصفته بطل نسختَي دوري أبطال آسيا للنخبة 2024-2025 و2025-2026، فيما تأهّل نادي النصر بوصفه بطل دوري روشن السعودي للمحترفين لموسم 2025-2026، وتأهّل ناديا الهلال والقادسية وفق ترتيبهما في الدوري ذاته، في حين أكمل نادي الاتحاد القائمة السعودية بعد فوزه على نادي الجزيرة الإماراتي في الدور التمهيدي.","وكان الاتحاد الآسيوي لكرة القدم قد اعتمد توسيع عدد الأندية المشاركة في دوري أبطال آسيا للنخبة من 24 إلى 32 ناديًا، مع إعادة توزيع مقاعد الاتحادات الوطنية، إذ نالت الأندية السعودية الحد الأقصى المتاح بواقع 3 مقاعد مباشرة و2 عبر الدور التمهيدي.","ويتزامن هذا الحضور التاريخي مع استمرار استضافة المملكة للأدوار النهائية من دوري أبطال آسيا للنخبة، بعد نجاحها في استضافة ثلاث نسخ سابقة، حيث منح الاتحاد الآسيوي الاتحادَ السعودي لكرة القدم حقوق استضافة الأدوار النهائية لثلاثة مواسم متتالية: 2026-2027 و2027-2028 و2028-2029، في شهادة على الإمكانات التنظيمية والتشغيلية التي تتمتع بها المملكة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/xkn7q6w','https://sabq.org/article/xkn7q6w','','https://sabq.org/article/xkn7q6w','صحيفة سبق','السعودية','2026-08-12T10:26:00.000Z','2026-08-12T13:27:00.000Z','2026-08-12T22:21:19.212Z','https://media.sabq.org/news/2026/08/f30c7697-648f-4747-91e6-88a5b6eebeab/w1024.webp','/api/media/cf89b7f7-2cce-49af-b75b-69adf5ddc853','/api/media/cf89b7f7-2cce-49af-b75b-69adf5ddc853?variant=thumbnail','5 أندية سعودية في دوري أبطال آسيا للنخبة 2026-2027 لأول مرة تاريخياً',1024,1280,'valid','published','archived','valid',99,'c31e86af067b30022e6040fd209f4f0c7d297006366d85a471c15590164905c0','7176b2881e0422c6301f25972a58d7fa414447c700ce9f635ae709ae95cc9826',NULL,'2026-08-12T22:21:19.212Z','2026-10-07T21:02:11.394Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T21:02:11.394Z',200,83,0,'source_article_available','',NULL,NULL,'body:bf7f23e37d7591dfe1ef5260863c9a84ed38145a44ac3a4f24580f0ade7ca628','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b6dfbf3e-b4c7-41b8-b4eb-9881f2ae24b0','news-b6dfbf3e-b4c7-41b8-b4eb-9881f2ae24b0','أمير جازان يؤدي صلاة الميت على أم وأطفالها من أسرة محنشي بصامطة','امير جازان يؤدي صلاه الميت علي ام واطفالها من اسره محنشي بصامطه','أدى صاحب السمو الملكي الأمير محمد بن عبدالعزيز بن محمد بن عبدالعزيز أمير منطقة جازان, اليوم، صلاة الميت على المتوفين في حادث الاختناق جراء حريق اندلع في منزلهم بمحافظة صامطة، ونتج عنه وفاة أم وأطفالها الأربعة.','["وعقب الصلاة، قدّم سمو أمير منطقة جازان العزاء والمواساة لأسرة المتوفين، سائلًا الله تعالى أن يتغمدهم بواسع رحمته ومغفرته، وأن يسكنهم فسيح جناته، وأن يلهم ذويهم الصبر والسلوان، وأن يمنّ على والد الأسرة بالشفاء العاجل.","فيما أعربت أسرة المتوفين عن شكرهم وتقديرهم لسمو أمير منطقة جازان على تعازيه ومواساته."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ye43t42','https://sabq.org/article/ye43t42','','https://sabq.org/article/ye43t42','عمر عريبي','السعودية','2026-08-12T10:05:00.000Z','2026-08-12T14:54:00.000Z','2026-08-12T22:21:19.361Z','https://media.sabq.org/news/2026/08/eb04cf09-94f2-41e0-b61c-7146737082f9/w1280.webp','/api/media/b6dfbf3e-b4c7-41b8-b4eb-9881f2ae24b0','/api/media/b6dfbf3e-b4c7-41b8-b4eb-9881f2ae24b0?variant=thumbnail','صورة من الألبوم',1280,1004,'valid','published','archived','valid',44,'6ac9308f12c3540868612eea1ae9032843e101ce29fca88a47ed23e495d4f8a0','9e073d5ec899246dbb19c44e431709d6931f55746e95b1f9a28027342f257753','محدّث','2026-08-12T22:21:19.361Z','2026-10-07T21:07:53.881Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["جازان"]','[]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T21:07:53.881Z',200,82,0,'source_article_available','',NULL,NULL,'body:8a6193e63c268d6361ea2212cfd599826eea5310e91dfb3f53718a9021168dd0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a4f5cf58-f69b-4480-b292-00de395745e0','news-a4f5cf58-f69b-4480-b292-00de395745e0','الملك سلمان وولي العهد يهنئان رئيس المجر بمناسبة انتخابه','الملك سلمان وولي العهد يهنئان رئيس المجر بمناسبه انتخابه','بعث خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود برقية تهنئة إلى فخامة الرئيس الدكتور أندراش باكا، بمناسبة انتخابه وأدائه اليمين الدستورية رئيساً للمجر.','["وأعرب الملك المفدى في برقيته عن أصدق التهاني وأطيب التمنيات لفخامته بالتوفيق والسداد، متمنياً لشعب المجر الصديق المزيد من التقدم والازدهار.","وفي السياق ذاته، بعث صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود، ولي العهد رئيس مجلس الوزراء، برقية تهنئة مماثلة إلى فخامة الرئيس الدكتور أندراش باكا، بالمناسبة نفسها.","وعبَّر سمو ولي العهد في برقيته عن أصدق التهاني وأطيب التمنيات لفخامته بالتوفيق والسداد، ولشعب المجر الصديق المزيد من التقدم والرقي."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/cajpz5k','https://sabq.org/article/cajpz5k','','https://sabq.org/article/cajpz5k','صحيفة سبق','السعودية','2026-08-12T09:49:00.000Z','2026-08-12T12:49:00.000Z','2026-08-12T22:21:20.572Z','https://media.sabq.org/news/2026/08/aa20d67e-2456-4ef7-8edc-6fdc0cdf3e66/w1600.webp','/api/media/a4f5cf58-f69b-4480-b292-00de395745e0','/api/media/a4f5cf58-f69b-4480-b292-00de395745e0?variant=thumbnail','الملك سلمان وولي العهد يهنئان رئيس المجر بمناسبة انتخابه',1600,899,'valid','published','archived','valid',99,'c1e94e2ac0136c22de6da7fac7bb443626e58d4248b325e9e7337ce3381a7e77','04a132c61752dc3b62f438c6cc433a52ac612a17539fef89e06b0e3b9bc5a101','محدّث','2026-08-12T22:21:20.572Z','2026-10-07T21:07:54.554Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء برقية تهنئة مماثلة","رئيس المجر بمناسبة انتخابه وأعرب"]','["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء برقية تهنئة مماثلة","رئيس المجر بمناسبة انتخابه وأعرب"]','classified','','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T21:07:54.554Z',200,82,0,'source_article_available','',NULL,NULL,'body:478509ef0cb5b390400b0a6efcda342033a626e6848173e5c816ae36ee2bd7d0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9b221829-fb0c-4c84-a1c9-2f4eac99e4e5','news-9b221829-fb0c-4c84-a1c9-2f4eac99e4e5','من العاصمة النيجيرية أبوجا.. وبرعاية فخامة رئيس الجمهورية: د.العيسى يطلق مبادرةَ رابطة العالم الإسلامي للسِّلم المجتمعيّ في غرب أفريقيا','من العاصمه النيجيريه ابوجا وبرعايه فخامه رئيس الجمهوريه د العيسي يطلق مبادره رابطه العالم الاسلامي للسلم المجتمعي في غرب افريقيا','أطلَقَ ‏معالي الأمين العام لرابطة العالم الإسلامي، رئيسُ هيئة علماء المسلمين، فضيلةُ الشيخ الدكتور محمد بن عبدالكريم العيسى، مبادرةَ الرابطة للسِّلم المجتمعيّ في غرب أفريقيا، من خلال مؤتمرها الدّولي: "التنوُّع والسِّلم المجتمعيّ..','["الشراكة من أجلِ مُستقبلٍ واعِدٍ\"، في العاصمة النيجيرية \"أبوجا\".","وحظِيَ المؤتمرُ برعاية فخامة رئيس جمهورية نيجيريا الاتحادية، السيد بولا أحمد تينوبو، ومشاركة قياداتٍ دينيةٍ \"إسلامية ومسيحية\"، وعددٍ من الوزراء والبرلمانيين، وقيادات المجتمع المدني. ‏وشهِدَ المؤتمرُ الاتفاقَ على \"إعلان أبوجا\"، بإجماع القيادات الدينية الممثِّلة لكافة الأديان والمذاهب في المنطقة، متضمّنًا إقرارَ خطة العمل المُشتركة بين المؤسسات الحكومية، وتضامُن القيادات الدينية \"الإسلامية والمسيحية\"، ومنظّمات…","الجدير بالذِّكر أنّ المبادرةَ تقوم على ركائزَ تعالجُ جذورَ المشكِلات الفكرية والاجتماعية، المتمثلة في الأفكار المُتطرفة، وتضمن الالتزامَ والشراكةَ والاستدامةَ باتفاقاتٍ مُلْزِمةٍ بين كافّة الأطراف ذات العلاقة."]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/8injdx4','https://sabq.org/article/8injdx4','','https://sabq.org/article/8injdx4','صحيفة سبق','السعودية','2026-08-12T09:58:00.000Z','2026-08-12T12:58:00.000Z','2026-08-12T22:21:20.600Z','https://media.sabq.org/news/2026/08/78f5a92a-342a-4cf3-81ff-e98b8310ee93/w1280.webp','/api/media/9b221829-fb0c-4c84-a1c9-2f4eac99e4e5','/api/media/9b221829-fb0c-4c84-a1c9-2f4eac99e4e5?variant=thumbnail','صورة من الألبوم',1280,854,'valid','published','archived','valid',55,'d45b47da1cfc600d30d0b6feb30742741772e64541fb3591f0a8b4ad6ac62a9d','ca9e3f32d62ace40435f15e235ad34386574d310cfa32b3b1a4e1455651a2694','محدّث','2026-08-12T22:21:20.600Z','2026-10-07T21:02:15.538Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس الجمهورية د العيسى يطلق","السياسة والعلاقات الدولية"]','["رئيس الجمهورية د العيسى يطلق","السياسة والعلاقات الدولية"]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":4.5},{"category":"السياسة","score":4},{"category":"المجتمع","score":3}]','Active','2026-10-07T21:02:15.538Z',200,83,0,'source_article_available','',NULL,NULL,'body:a93d9625a5309e05aa49133df76e731e0bd2e0df1466e713e292c3ac54c5f16e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d91b022a-6f82-4126-8dfc-fa50238538bc','news-d91b022a-6f82-4126-8dfc-fa50238538bc','جدة بوابة البحر الأحمر.. سياحة بحرية تتسع بين الغوص والرياضات والرحلات','جده بوابه البحر الاحمر سياحه بحريه تتسع بين الغوص والرياضات والرحلات','تُعزز محافظة جدة مكانتها بوابةً رئيسة للسياحة البحرية على ساحل البحر الأحمر خلال صيف 2026م، إذ تتيح لزوارها تجارب متنوعة تشمل الرحلات البحرية والرياضات المائية والغوص واستكشاف الجزر والشعاب المرجانية.','["وتشهد 13 شاطئاً وموقعاً بحرياً في جدة نشاطاً متزايداً خلال الموسم، تدعمها منظومة ميدانية متكاملة تضم 34 مشرفاً ميدانياً و66 منقذاً ومنقذة، بهدف تعزيز سلامة مرتادي المواقع البحرية ورفع مستوى الجاهزية، بما يضمن جودة تجربة الزائر.","وتتنوع الخيارات أمام الزوار بين أربع رياضات وتجارب بحرية، إلى جانب رحلات بالقوارب إلى الجزر ومواقع الشعاب المرجانية، مما يتيح استكشاف التنوع الطبيعي الذي يتميز به البحر الأحمر في بيئة تجمع الترفيه والرياضة والطبيعة.","وتُسهم الهيئة السعودية للبحر الأحمر في تطوير هذا القطاع وتنظيمه من خلال الأطر التنظيمية والتراخيص ذات الصلة، بما يرفع مستوى جودة التجارب البحرية ويعزز استدامة القطاع السياحي الساحلي.","وتبرز جزيرة «بياضة» قبالة سواحل جدة وجهةً بحرية بارزة تستقطب الرحلات خلال الموسم، بما تتميز به من مياه صافية وطبيعة بحرية خلابة، فيما تمتد خارطة التجارب جنوباً لتشمل رحلات بحرية إلى جزر «الأخوات الأربع» بمحافظة الليث، التي تُعدّ وجهة فريدة لمحبي الغوص ومحترفيه بما تزخر به مياهها من شعاب مرجانية وبيئات بحرية نادرة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/n746n6h','https://sabq.org/article/n746n6h','','https://sabq.org/article/n746n6h','صحيفة سبق','السعودية','2026-08-12T09:53:00.000Z','2026-08-12T12:54:00.000Z','2026-08-12T22:21:20.798Z','https://media.sabq.org/news/2026/08/99418677-94c9-40a7-acc1-34a848a97ef8/w1600.webp','/api/media/d91b022a-6f82-4126-8dfc-fa50238538bc','/api/media/d91b022a-6f82-4126-8dfc-fa50238538bc?variant=thumbnail','صورة من الألبوم',1600,878,'valid','published','archived','valid',95,'8b541b675da94995d35407475ea52ad3c3c9528ac81f2b429cc22b29c57fabf2','efc20c0c00934954f47077639686c04bb26197c6281971f0a8bed255f3df61f0','محدّث','2026-08-12T22:21:20.798Z','2026-10-07T21:08:00.056Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الرياضة السعودية","جدة","الرياض"]','["السفر والسياحة","الرياضة السعودية"]','classified','','[{"category":"السفر","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T21:08:00.056Z',200,79,0,'source_article_available','',NULL,NULL,'body:64042b3750a75a568b3bd94b85abaa69cdcf63056b792a4a62b1ee0381aad58c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('03b38d9b-31e8-4a75-9172-642a28a47201','news-03b38d9b-31e8-4a75-9172-642a28a47201','وكالة الطاقة الدولية: أسواق النفط تواجه عجزًا بـ1.8 مليون برميل يوميا','وكاله الطاقه الدوليه اسواق النفط تواجه عجزا بـ1 8 مليون برميل يوميا','أكدت وكالة الطاقة الدولية اليوم، بأن أسواق النفط العالمية تواجه عجزًا في الإمدادات يقدر بنحو (1.8) مليون برميل يوميًا، في ظل الاضطرابات التي تقوض تعافي الإنتاج، مرجحةً أن يكون العجز الأكبر خلال خمس سنوات.','["وتوقعت الوكالة انخفاض مخزونات النفط العالمية خلال الربع الحالي من العام بوتيرة تزيد على ضعف المعدل الذي قدرته سابقًا، في ظل استمرار الأزمة في الشرق الأوسط وتأثيرها في الإمدادات وحركة الأسواق.","وأشارت إلى أن استمرار الاضطرابات في الإنتاج والإمدادات يزيد الضغوط على توازن السوق العالمية، بالتزامن مع حالة عدم اليقين المرتبطة بتطورات الأوضاع في المنطقة."]','الطاقة والصناعة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/plwbrq0ln','https://ajel.sa/economy/plwbrq0ln','https://ajel.sa/economy/plwbrq0ln','https://ajel.sa/economy/plwbrq0ln','فريق التحرير','السعودية','2026-08-12T13:39:00.000Z','Wed, 07 Oct 2026 21:00:52 GMT','2026-08-13T00:22:40.560Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/ajel-2026-06-15-yjmebz5i-%D9%86%D9%81%D8%B7-Q2zBd0WX.jpg','/api/media/03b38d9b-31e8-4a75-9172-642a28a47201','/api/media/03b38d9b-31e8-4a75-9172-642a28a47201?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',99,'7f494a51c6910d6f703011d535885dbfdcacb2715ac1e083ded58200e1b4ea38','347f5516ce73495e5b694bd9ad20172782f851d2faae47574f7272ef045562fe',NULL,'2026-08-13T00:22:40.560Z','2026-10-07T21:00:53.968Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الشرق الأوسط"]','["الطاقة والنفط","الشرق الأوسط"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Updated','2026-10-07T21:00:53.968Z',200,72,0,'source_content_changed','',NULL,NULL,'body:503f7de383fdb80e306b98c9276a1e0614bc178822f775c35f6ff149c2739aa3','Wed, 07 Oct 2026 21:00:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('98525cf6-e816-4a0f-9834-fc12347e332c','news-98525cf6-e816-4a0f-9834-fc12347e332c','عام / من الجير إلى الشاهين.. خصائص تميز أنواع الصقور في المزاد الدولي لمزارع إنتاج الصقور','عام من الجير الي الشاهين خصائص تميز انواع الصقور في المزاد الدولي لمزارع انتاج الصقور','الرياض 29 صفر 1448 هـ الموافق 12 أغسطس 2026 م واس تضم قائمة الصقور المعروضة في المزاد الدولي لمزارع إنتاج الصقور 2026، الذي ينظمه المركز الوطني للصقور في مقره بمَلهم شمال مدينة الرياض، أنواعًا وفئات متعددة تشمل الجير والشاهين والحر والهجين، ولكل منها خصائص تميزها من حيث الحجم واللون والبنية والأداء، وهي صفات تحظى باهتمام الصقارين عند التعرف على الصقور واختيا','["وأوضح سامر ذياب السليمي، ممثل مزرعة محلية مشاركة في المزاد، أن صقور الجير تتميز بكبر حجمها وقوة بنيتها وتعدد ألوانها، التي تتدرج من الأبيض إلى الرمادي والألوان الداكنة، مشيرًا إلى أن مزارع الإنتاج تعمل على تطوير خطوط مختلفة منها وفق الصفات المستهدفة في كل خط إنتاج.","وأشار إلى أن الشاهين يُعرف بسرعته وبنيته الانسيابية وأجنحته المدببة، ويحظى باهتمام الصقارين لما يتمتع به من قدرات في الطيران والانقضاض، فيما يتميز الحر بقوة بنيته ومكانته المعروفة لدى الصقارين، وارتباطه منذ وقت طويل بممارسة الصقارة والصيد في المنطقة.","وبيّن السليمي أن إنتاج المزارع لا يقتصر على الأنواع الخالصة، بل يشمل أنواعًا هجينة تجمع صفات من أكثر من نوع، من بينها فئات متداولة في أوساط الصقارين ومسابقات الصقور، مثل: الجير شاهين ومثلوث الجير وغيرها، إذ يسعى المنتجون من خلال اختيار خطوط الإنتاج إلى الوصول إلى صفات محددة تتعلق بالسرعة أو الحجم أو اللون أو الأداء.","وأضاف أن الاختلاف بين الصقور لا يقتصر على مسمى النوع أو الفئة، إذ يولي الصقار اهتمامًا كذلك بخط الإنتاج والصفات الفردية للصقر ونتائج عائلته والغرض من اقتنائه، لا سيما مع اختلاف المواصفات المطلوبة بين صقور السباقات وغيرها من مجالات الصقارة."]','الثقافة','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2652657?type=news&uuid=N2652657','https://spa.gov.sa/ar/N2652657?type=news&uuid=N2652657','N2652657','N2652657','','السعودية','2026-08-12T15:15:00.000Z',NULL,'2026-08-13T00:23:02.277Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10599679.jpg','/api/media/98525cf6-e816-4a0f-9834-fc12347e332c','/api/media/98525cf6-e816-4a0f-9834-fc12347e332c?variant=thumbnail','عام / من الجير إلى الشاهين.. خصائص تميز أنواع الصقور في المزاد الدولي لمزارع إنتاج الصقور',1600,1066,'valid','published','archived','valid',41,'5ba28b37fcb86fa73ff99c67e3e9b5c600267949e4772cefc47e6ca59e490c43','b8f052375263808fac4bb53d206a42c0fb6ebac7dd39186a484beb5f345c75c2',NULL,'2026-08-13T00:23:02.277Z','2026-10-07T21:07:51.345Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الثقافة والفنون"]','["السفر والسياحة","الثقافة والفنون"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T21:07:51.345Z',200,75,0,'source_article_available','',NULL,NULL,'body:3bfc0bfc7944254eb5209db2a824e5e52320b7e2622a45d229ae6c13bb8e2b43','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2453a4a2-855e-425e-9520-a0be47efac01','news-2453a4a2-855e-425e-9520-a0be47efac01','سياحة وترفيه / ممشى القفيل بالمخواة.. متنفس حضري يجمع الرياضة والترفيه','سياحه وترفيه ممشي القفيل بالمخواه متنفس حضري يجمع الرياضه والترفيه','الباحة 29 صفر 1448 هـ الموافق 12 أغسطس 2026 م واس أنهت بلدية محافظة المخواة أعمال تطوير وتأهيل ممشى وملاعب رياضية ومسطحات خضراء بحي القفيل، على مساحة إجمالية تبلغ نحو (27) ألف متر مربع؛ بهدف توفير متنفس حضري يخدم السكان والزوار، ويعزز ممارسة الأنشطة الرياضية والترفيهية.','["ويضم الموقع ممشى بطول (500) متر، ومسارًا مخصصًا للسكوترات والدراجات بالطول نفسه، إلى جانب أرصفة وممرات تبلغ مساحتها (4) آلاف متر مربع، بما يسهّل حركة الزوار ووصولهم إلى مرافق الموقع.","وشملت الأعمال إنشاء ملاعب رياضية على مساحة إجمالية تبلغ (3300) متر مربع، تتضمن ملعبًا لكرة القدم مفروشًا بالنجيل الصناعي، وملعبًا للكرة الطائرة، إضافة إلى تجهيزها بكشافات للإنارة.","وتتجاوز مساحة المسطحات الخضراء (8) آلاف متر مربع، وتضم أكثر من (70) شجرة، فيما تعتزم البلدية زيادة أعداد الأشجار مستقبلًا؛ للإسهام في تنمية الغطاء النباتي وتحسين المشهد الحضري، كما زُوّد الموقع بإنارة تجميلية ودورات مياه مخصصة للرجال والنساء.","وتضمنت أعمال التطوير تأهيل الجدران المحيطة بالحديقة والممشى، البالغة مساحتها نحو (6) آلاف متر مربع، وتكسيتها بالحجر الطبيعي وتزيينها بنقوش من أحجار المرو؛ بما ينسجم مع الطابع العمراني للموقع."]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2652702?type=news&uuid=N2652702','https://spa.gov.sa/ar/N2652702?type=news&uuid=N2652702','N2652702','N2652702','','السعودية','2026-08-12T15:50:00.000Z',NULL,'2026-08-13T00:23:02.284Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10598442.png','/api/media/2453a4a2-855e-425e-9520-a0be47efac01','/api/media/2453a4a2-855e-425e-9520-a0be47efac01?variant=thumbnail','سياحة وترفيه / ممشى القفيل بالمخواة.. متنفس حضري يجمع الرياضة والترفيه',1600,906,'valid','published','archived','valid',96,'2cec301b39dccbfee7186e21e3da2b0097db3b37d998adebb60c0559fe0169b0','0cdf088d3cf2b51656b338863dcb79d3c3faa304f1d25d32a4390894649dd47f',NULL,'2026-08-13T00:23:02.284Z','2026-10-07T21:01:52.178Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الرياضة السعودية","الرياض"]','["السفر والسياحة","الرياضة السعودية"]','classified','','[{"category":"المجتمع","score":5.5},{"category":"الرياضة","score":5.5},{"category":"السفر","score":4.5}]','Active','2026-10-07T21:01:52.178Z',200,77,0,'source_article_available','',NULL,NULL,'body:d767a1a1e16b9ab29895fe033717e1cca83f87a7302b75cee1d1d2fb48a3db6f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fbee5969-fe5d-4e18-9b39-10711da4bb0a','news-fbee5969-fe5d-4e18-9b39-10711da4bb0a','السعودية بين أكبر 10 دول في استثمارات الذكاء الاصطناعي.. و440 ميجاوات لسعة مراكز البيانات','السعوديه بين اكبر 10 دول في استثمارات الذكاء الاصطناعي و440 ميجاوات لسعه مراكز البيانات','صنّف تقرير التنمية في العالم 2026 الصادر عن مجموعة البنك الدولي، بعنوان «وعد الذكاء الاصطناعي»، المملكةَ العربية السعودية ضمن أكبر عشر دول عالمياً في الاستثمار الخاص بالذكاء الاصطناعي، وأبرزها وجهةً جاذبة للكفاءات المتخصصة، ونموذجاً في تكامل البيانات الحكومية.','["ويُعدّ التقرير أول تقييم شامل يُصدره البنك الدولي لآثار الذكاء الاصطناعي في الاقتصادات النامية، والفرص التي يتيحها للأفراد والمنشآت والحكومات، والمتطلبات اللازمة لتعظيم أثره التنموي وإدارة مخاطره.","ويرتكز التقرير على ثلاثة محاور رئيسة: القدرات التي يتيحها الذكاء الاصطناعي لتوسيع الوصول إلى الخبرات ودعم اتخاذ القرار، والتركّز الناتج عن تمركز إنتاج النماذج المتقدمة والرقائق ومراكز البيانات في عدد محدود من الدول والشركات، والعوامل المكمّلة المتمثلة في البنية التحتية والبيانات والمهارات والمؤسسات.","وفي محور التركّز، أشار التقرير إلى أن المملكة تجمع بين الحوافز الضريبية والمناطق الاقتصادية الخاصة لاستقطاب الاستثمارات في مراكز البيانات وبناء قدرات الحوسبة، في نهج وطني يربط جذب رأس المال بتطوير منظومة تشمل الكفاءات والشركات الناشئة والطاقة والبنية التحتية.","وتتجلى ثمار هذا النهج في النمو المتسارع للبنية التحتية الرقمية؛ إذ ارتفعت سعة مراكز البيانات من 68 ميجاوات عام 2021 إلى 440 ميجاوات عام 2025، لتواصل نموها وتبلغ 467 ميجاوات خلال الربع الأول من 2026، بزيادة تجاوزت 6% منذ مطلع العام، وبما يقارب سبعة أضعاف مقارنة بعام 2021."]','الذكاء الاصطناعي','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/owfqjan','https://sabq.org/article/owfqjan','','https://sabq.org/article/owfqjan','صحيفة سبق','السعودية','2026-08-12T11:58:00.000Z','2026-08-12T14:58:00.000Z','2026-08-13T00:27:23.624Z','https://media.sabq.org/news/2026/08/c4f471bb-6b34-47be-af5b-3e32c465067b/w1290.webp','/api/media/fbee5969-fe5d-4e18-9b39-10711da4bb0a','/api/media/fbee5969-fe5d-4e18-9b39-10711da4bb0a?variant=thumbnail','السعودية بين أكبر 10 دول في استثمارات الذكاء الاصطناعي.. و440 ميجاوات لسعة مراكز البيانات',1290,847,'valid','published','archived','valid',96,'bdfa3c9f3499590c7ac2e3cbfa7a5ef3c81a03bd696fba55103eb0976e84d107','1e5aafd9d9740c1f85436579158b07d69de47bf0fbe46e5f2ed1434ec31b1756','محدّث','2026-08-13T00:27:23.624Z','2026-10-07T21:01:48.394Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["الطاقة والنفط","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"التقنية","score":8.5},{"category":"أخبار السعودية","score":4.5},{"category":"الطاقة والصناعة","score":1.5}]','Active','2026-10-07T21:01:48.394Z',200,77,0,'source_article_available','',NULL,NULL,'body:1d731c930905a842f6b1a0e44e0b50140cb534ee80e438053091c70312d8f7ec','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('965a5bc8-fae3-4809-9f9a-04caf73b7338','news-965a5bc8-fae3-4809-9f9a-04caf73b7338','جازان تشيّع أماً وأطفالها الأربعة ضحايا حريق منزل في صامطة','جازان تشيع اما واطفالها الاربعه ضحايا حريق منزل في صامطه','شيّع أهالي محافظة صامطة بمنطقة جازان، اليوم، جثامين أم وأطفالها الأربعة من أسرة عبدالرحمن حسن محنشي —رحمهم الله— إلى مثواهم الأخير، بعد أن لقوا حتفهم اختناقاً إثر حريق مروّع اندلع في منزل الأسرة بالمحافظة.','["وأُقيمت صلاة الميت على الضحايا الخمسة في جامع معاذ بن جبل بأبو حجر، قبل أن تُوارَى جثامينهم الثرى في مقبرة قرية اللقية، وسط حضور كبير من الأهالي والأقارب الذين وقفوا إلى جانب الأسرة في مصابها الأليم.","وتعالت أدعية المشيّعين بأن يتغمّد الله الضحايا بواسع رحمته، ويُسكنهم فسيح جناته، وأن يُلهم ذويهم الصبر والسلوان على هذا الفقد المؤلم."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7ntza5p','https://sabq.org/article/7ntza5p','','https://sabq.org/article/7ntza5p','عمر عريبي','السعودية','2026-08-12T11:53:00.000Z','2026-08-12T15:00:00.000Z','2026-08-13T00:27:24.448Z','https://media.sabq.org/news/2026/08/1ad18310-2253-47ef-a9a1-6c34f21e808f/w778.webp','/api/media/965a5bc8-fae3-4809-9f9a-04caf73b7338','/api/media/965a5bc8-fae3-4809-9f9a-04caf73b7338?variant=thumbnail','جازان تشيّع أماً وأطفالها الأربعة ضحايا حريق منزل في صامطة',778,559,'valid','published','archived','valid',46,'340537b34db17ef33e74b9d930004a0012d8f98b07eb1f627b6a842e3b9fd7e3','3030665081e76a7e10775ec058ff2c46ba6cca42ed14c4bc29a61b4ba61ada84','محدّث','2026-08-13T00:27:24.448Z','2026-10-07T21:00:45.560Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["جازان"]','[]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T21:00:45.560Z',200,74,0,'source_article_available','',NULL,NULL,'body:ab04c859a61a9e16a73303a9557fbaa452d82ca021fc1c4073dfcf4dc54e1bdc','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('704fe289-b3e7-49a7-81bb-9bfef6294bf6','news-704fe289-b3e7-49a7-81bb-9bfef6294bf6',' "العليمي": الحوثيون يستغلون الهدن لإعادة بناء قدراتهم.. واليمن مستعد لمواجهة مشروع الحرب','العليمي الحوثيون يستغلون الهدن لاعاده بناء قدراتهم واليمن مستعد لمواجهه مشروع الحرب','أكد رئيس مجلس القيادة الرئاسي اليمني الدكتور رشاد محمد العليمي، القائد الأعلى للقوات المسلحة، أن الدولة اليمنية باتت أكثر قدرة واستعداداً لحماية سيادتها، بعد سنوات من العمل على توحيد القوى السياسية والعسكرية في مواجهة مليشيات الحوثيين.','["جاء ذلك خلال اجتماع موسع مع قيادات وممثلي المؤسسات الرسمية والمحلية، أكد فيه العليمي أن موقف الدولة اليوم يختلف اختلافاً جوهرياً عن المراحل السابقة، في ظل وحدة داخلية راسخة، وجبهة سياسية وعسكرية متماسكة، واحتضان شعبي متنامٍ.","وشدد العليمي على أن تجربة السنوات الماضية مع مليشيات الحوثيين أثبتت أن الهدنة لا تمثل لديها سوى مرحلة لإعادة بناء قدراتها العسكرية تمهيداً للعودة إلى الحرب، مؤكداً أن الحكومة باتت مدركة تماماً أن هذه المليشيات مشروع حرب وسلاح لا مشروع سلام.","وأوضح أن الهدف الأساسي من تشكيل مجلس القيادة الرئاسي هو توحيد القوى السياسية والعسكرية لمواجهة المليشيات الحوثية وإسقاطها واستعادة الدولة، لافتاً إلى أن القوات المسلحة باتت جاهزة للدفاع عن اليمنيين ومنشآتهم الوطنية.","وعلى الصعيد الاقتصادي، أشار العليمي إلى أن استهداف المليشيات الحوثية للمنشآت النفطية في أكتوبر 2022 كلّف الحكومة خسارة نحو 70% من إيراداتها النفطية، فيما تجاوزت تكاليف الإصلاح 40 مليون دولار."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/e7kojrh','https://sabq.org/article/e7kojrh','','https://sabq.org/article/e7kojrh','صحيفة سبق','السعودية','2026-08-12T11:50:00.000Z','2026-08-12T14:54:00.000Z','2026-08-13T00:27:25.036Z','https://media.sabq.org/news/2026/08/29c1d5a5-6bf6-4833-876a-aba4481c2277/w850.webp','/api/media/704fe289-b3e7-49a7-81bb-9bfef6294bf6','/api/media/704fe289-b3e7-49a7-81bb-9bfef6294bf6?variant=thumbnail',' "العليمي": الحوثيون يستغلون الهدن لإعادة بناء قدراتهم.. واليمن مستعد لمواجهة مشروع الحرب',850,516,'valid','published','archived','valid',48,'10c1f30f9388bdf66c98b88fe3171b6f58fb973e88e90d977d4092ab3c6ef983','d4116a1d69b011e289c3569d0383d75ffa48a59da038246028caf9cd13c83d22','محدّث','2026-08-13T00:27:25.036Z','2026-10-07T21:01:54.784Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس القيادة الرئاسي هو توحيد","الطاقة والنفط","الثقافة والفنون","الاقتصاد والأسواق","اليمن"]','["مجلس القيادة الرئاسي هو توحيد","الطاقة والنفط","الثقافة والفنون","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"الطاقة والصناعة","score":3},{"category":"السياسة","score":1.5}]','Active','2026-10-07T21:01:54.784Z',200,77,0,'source_article_available','',NULL,NULL,'body:727cbadf524f0253f0bc33ff1c6e9b8394f040f1409a12cbfb75cd136077118d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7068fbd7-ffdf-410d-bcca-1eda978d43a5','news-7068fbd7-ffdf-410d-bcca-1eda978d43a5','نادي سباقات الخيل يلغي موسم الطائف الشتوي ضمن تحديثات البرنامج السباقي','نادي سباقات الخيل يلغي موسم الطائف الشتوي ضمن تحديثات البرنامج السباقي','أعلن نادي سباقات الخيل السعودي عدم إقامة موسم سباقات الطائف الشتوي على ميدان الملك خالد للفروسية بالطائف، مشيراً إلى أن هذا القرار يأتي ضمن التحديثات التنظيمية التي أجرتها الجهة المعنية على البرنامج السباقي.','["ولم يُفصح النادي عن تفاصيل إضافية تتعلق بأسباب الإلغاء أو البدائل المقررة، في حين يترقب المهتمون بسباقات الخيل صدور الجدول الزمني المعدَّل للمواسم القادمة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/5hxh2uo','https://sabq.org/article/5hxh2uo','','https://sabq.org/article/5hxh2uo','صحيفة سبق','السعودية','2026-08-12T11:27:00.000Z','2026-08-12T14:28:00.000Z','2026-08-13T00:27:26.291Z','https://media.sabq.org/news/2026/08/02105cfc-25a6-4013-b6a5-9fa898e9986b/w1200.webp','/api/media/7068fbd7-ffdf-410d-bcca-1eda978d43a5','/api/media/7068fbd7-ffdf-410d-bcca-1eda978d43a5?variant=thumbnail','نادي سباقات الخيل يلغي موسم الطائف الشتوي ضمن تحديثات البرنامج السباقي',1200,675,'valid','published','archived','valid',47,'ca12c41b3db1340d2afc885ba45d8d8134377fe0ea1dc828794f98ad7f69a833','1cda6ecd063fbe871432c34ef917ac9e142ff68b2cd199921a738891ea36d14a','محدّث','2026-08-13T00:27:26.291Z','2026-10-07T21:00:58.654Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T21:00:58.654Z',200,74,0,'source_article_available','',NULL,NULL,'body:66c9703589681ba3d98cfb1ca1c0be1f0c8a15059d3e991a93daf8d7b6b0dfa9','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('35a3f321-3a5d-4a8d-8e0f-185eaa1d9735','news-35a3f321-3a5d-4a8d-8e0f-185eaa1d9735','مكتبة الملك عبدالعزيز تحتفي باليوم العالمي للخط العربي بمعارض وورش متنوعة','مكتبه الملك عبدالعزيز تحتفي باليوم العالمي للخط العربي بمعارض وورش متنوعه','تحتفل مكتبة الملك عبدالعزيز العامة بالرياض باليوم العالمي للخط العربي الذي يوافق الثالث عشر من أغسطس من كل عام، بتنظيم سلسلة من الفعاليات والمعارض الثقافية التي تُعلي من شأن هذا الفن البصري العريق وتُعزز الصلة بين الثقافة المعاصرة والتراث العربي.','["وأقامت المكتبة «المعرض العالمي للخط العربي» الذي ضم أكثر من 200 كتاب تتناول جماليات الخط العربي وفنونه، إلى جانب لوحات متنوعة بأنواع الخطوط المختلفة من توقيع كبار الخطاطين وأبرزهم.","ونظمت المكتبة 15 ورشة عمل استهدفت المتقدمين في مجال الخط والمبتدئين والناشئة على حدٍّ سواء، فضلاً عن مسابقة ارتجالية للأطفال، وأتاحت متجراً لبيع الأدوات الخاصة بالخط العربي.","وفي إطار اهتمامها بالموروث الخطي، تقتني المكتبة مجموعة نادرة من مخطوطات المصاحف الشريفة المذهبة والمزخرفة، وأكثر من 7000 مخطوط تتنوع فيها الخطوط وتتعدد أحجامها، مشكّلةً منظومة فنية تراثية ثرية، إضافة إلى مجموعة من المخطوطات والوثائق الأندلسية التي تُجلّي روائع الخط العربي في الأندلس.","وأقامت المكتبة معرضاً للمصاحف الشريفة عرضت فيه مجموعات منتقاة من أكثر من 350 مصحفاً تقتنيها، نُسخت خلال قرون متعاقبة بخطوط متنوعة من بينها النسخ والكوفي والثلث والتمبكتي والسوداني وخطوط الشام والعراق ومصر واليمن، وأبدى فيها الناسخون والفنانون قيم الخط العربي والفنون الزخرفية الإسلامية بأساليب المشجّرات والمنمنمات والمذهبات."]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/uwmhyhp','https://sabq.org/article/uwmhyhp','','https://sabq.org/article/uwmhyhp','صحيفة سبق','السعودية','2026-08-12T11:18:00.000Z','2026-08-12T14:19:00.000Z','2026-08-13T00:27:26.761Z','https://media.sabq.org/news/2026/08/92b574dd-b828-446b-b0f7-21d542867ff4/w1600.webp','/api/media/35a3f321-3a5d-4a8d-8e0f-185eaa1d9735','/api/media/35a3f321-3a5d-4a8d-8e0f-185eaa1d9735?variant=thumbnail','صورة من الألبوم',1600,994,'valid','published','archived','valid',44,'95b32d7a171a5cc560337258cc1b65ebabd64e04f175fd129ac4e43712292db3','bd4c248b05b907940892684df0b78eb01594625fcc08e3b376ae99f98312bad9','محدّث','2026-08-13T00:27:26.761Z','2026-10-07T21:01:54.770Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","اليمن","العراق"]','["الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"العالم","score":3},{"category":"الاقتصاد","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:01:54.770Z',200,81,0,'source_article_available','',NULL,NULL,'body:1514c3db9b7d157d8e8b3eea3c1f1ac0e51be567f5eaaa5fd282f27afac6ba8f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('be9b1927-1545-41b1-98b9-e062cfef16ce','news-be9b1927-1545-41b1-98b9-e062cfef16ce','رابطة الهواة تُقرّ تعديلات اللوائح وتُحيل شراكة تسويقية للدراسة','رابطه الهواه تقر تعديلات اللوائح وتحيل شراكه تسويقيه للدراسه','عقد مجلس إدارة رابطة الهواة لكرة القدم اجتماعه الـ46 في مقر اللجنة الأولمبية والبارالمبية السعودية بالرياض، برئاسة عادل الفقي، واستعرض خلاله تقارير اللجان الفنية والقضائية، ومستجدات تحديث اللوائح، والتقرير المالي، وعدداً من الملفات التنظيمية والتسويقية.','["وشملت تقارير اللجان الفنية المعروضة ملفات المسابقات والحكام وشؤون اللاعبين، إلى جانب إحصائيات البطولات وأبرز الأعمال المنجزة خلال الفترة الماضية.","كما اطّلع المجلس على مستجدات اللجان القضائية والتحديثات التي طرأت عليها، فضلاً عن نتائج لجنة تحديث اللوائح في إطار تطوير الأنظمة المنظِّمة لعمل الرابطة ومسابقاتها.","وفي الشأن التسويقي، استعرض المجلس التصور المقترح للشراكة التسويقية مع شركة متخصصة، وأقرّ إحالته إلى لجنة الاستثمار لدراسته ومراجعته قبل استكمال إجراءات التوقيع.","وتناول الاجتماع أيضاً تقرير تسجيل فرق الهواة في بطولات الواعدين والبراعم، واستعرض التقرير المالي للرابطة ونوقشت أبرز بنوده."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/21oyjvt','https://sabq.org/article/21oyjvt','','https://sabq.org/article/21oyjvt','صحيفة سبق','السعودية','2026-08-12T11:13:00.000Z','2026-08-12T14:15:00.000Z','2026-08-13T00:27:26.770Z','https://media.sabq.org/news/2026/08/02d671d0-076c-4133-9da3-c83040ee1b0a/w1600.webp','/api/media/be9b1927-1545-41b1-98b9-e062cfef16ce','/api/media/be9b1927-1545-41b1-98b9-e062cfef16ce?variant=thumbnail','رابطة الهواة تُقرّ تعديلات اللوائح وتُحيل شراكة تسويقية للدراسة',1600,1066,'valid','published','archived','valid',50,'4cf816fa919522d543bb5bc1e6e4caab93580bab33b89e7bd98c9250da02bb7d','44ba1375de14bb67e7f8b4f3750030047ca12257fce98b313da97b592e7df4df','محدّث','2026-08-13T00:27:26.770Z','2026-10-07T21:02:11.401Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة متخصصة وأقر إحالته إلى","الاقتصاد والأسواق"]','["شركة متخصصة وأقر إحالته إلى","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:02:11.401Z',200,82,0,'source_article_available','',NULL,NULL,'body:1dd3bf1d96e4b8faa7be4ea0aa499f76b99729f5b45c2398ab70f9dafe3ab443','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dd514cbc-9584-48fb-acef-f4d5b5d76ff8','news-dd514cbc-9584-48fb-acef-f4d5b5d76ff8','وكالة الطاقة الدولية: عجز في إمدادات النفط يبلغ 1.8 مليون برميل يومياً','وكاله الطاقه الدوليه عجز في امدادات النفط يبلغ 1 8 مليون برميل يوميا','كشفت وكالة الطاقة الدولية أن أسواق النفط العالمية تواجه عجزاً حاداً في الإمدادات يُقدَّر بنحو 1.8 مليون برميل يومياً، في ظل اضطرابات متواصلة تُقوّض تعافي الإنتاج، مرجّحةً أن يكون هذا العجز الأكبر منذ خمس سنوات.','["وتوقعت الوكالة انخفاض المخزونات النفطية العالمية خلال الربع الحالي من العام بوتيرة تتجاوز ضعف المعدل الذي قدّرته في تقديراتها السابقة، وذلك في ظل استمرار الأزمة في الشرق الأوسط وتأثيرها المتصاعد على حركة الإمدادات وأسواق الطاقة.","وأشارت الوكالة إلى أن استمرار الاضطرابات في الإنتاج والإمدادات يُفاقم الضغوط على توازن السوق العالمية، بالتزامن مع حالة من عدم اليقين المرتبطة بتطورات الأوضاع الإقليمية وانعكاساتها على قطاع الطاقة."]','الطاقة والصناعة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/y1sl4mf','https://sabq.org/article/y1sl4mf','','https://sabq.org/article/y1sl4mf','صحيفة سبق','السعودية','2026-08-12T11:05:00.000Z','2026-08-12T14:06:00.000Z','2026-08-13T00:27:27.792Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/bc35cd7d-2b19-4a4d-b565-55710a478300/public','/api/media/dd514cbc-9584-48fb-acef-f4d5b5d76ff8','/api/media/dd514cbc-9584-48fb-acef-f4d5b5d76ff8?variant=thumbnail','وكالة الطاقة الدولية: عجز في إمدادات النفط يبلغ 1.8 مليون برميل يومياً',960,540,'valid','published','archived','valid',59,'77986c1432e5db308bff82aca44bad1003a773f1d7d5efad3ec9f0038ca51054','b2d9df95dcbb1fee8624c316cc6bdd005d15764ca39171fd1be74587fedb7cfd','محدّث','2026-08-13T00:27:27.792Z','2026-10-07T21:07:53.873Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الشرق الأوسط"]','["الطاقة والنفط","الشرق الأوسط"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T21:07:53.873Z',200,83,0,'source_article_available','',NULL,NULL,'body:e5abf6463f9cd8923a4c43766e5d45dd2535221d80e3c127ee797267934429dd','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('787808a5-12da-4ee7-897b-2896fa39d04b','news-787808a5-12da-4ee7-897b-2896fa39d04b','إدارة تعليم الباحة تختتم برامجها لصيف 2026','اداره تعليم الباحه تختتم برامجها لصيف 2026','اختتمت الإدارة العامة للتعليم بمنطقة الباحة أمس برامجها التعليمية والرياضية، التي نفذتها ضمن فعاليات "صيف الباحة 2026". وهدفت هذه البرامج الصيفية إلى استثمار أوقات الطلبة خلال الإجازة، وتنمية مهاراتهم، وتعزيز انخراطهم في أنشطة متنوعة ضمن بيئة تعليمية جاذبة وآمنة.','["اختتمت الإدارة العامة للتعليم بمنطقة الباحة أمس برامجها التعليمية والرياضية، التي نفذتها ضمن فعاليات \"صيف الباحة 2026\".","وتضمنت البرامج باقة متنوعة من الأنشطة التعليمية والثقافية والرياضية والترفيهية؛ أبرزها البرنامج الصيفي الذي نُفذ بالتعاون مع جامعة الملك عبدالله للعلوم والتقنية \"كاوست\" بمشاركة (58) طالبًا وطالبة، بهدف تنمية مهاراتهم العلمية والمعرفية، وتعزيز قدراتهم في مجالي الابتكار والتقنية.","كما شملت الفعاليات بطولة \"كينزا القمم\" لكرة القدم، التي أقيمت بالشراكة مع الاتحاد السعودي للرياضة المدرسية، ومسار \"كينزا للذكاء والتحدي\" المخصص للأشخاص ذوي الإعاقة؛ لتعزيز مشاركتهم في الأنشطة الذهنية وتنمية قدراتهم."]','الرياضة','رياضة','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/qnvk368co','https://ajel.sa/local/qnvk368co','https://ajel.sa/local/qnvk368co','https://ajel.sa/local/qnvk368co','فريق التحرير','السعودية','2026-08-12T14:56:00.000Z','Wed, 07 Oct 2026 21:00:47 GMT','2026-08-13T02:28:34.296Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-crop-g5Nmzs88.png','/api/media/787808a5-12da-4ee7-897b-2896fa39d04b','/api/media/787808a5-12da-4ee7-897b-2896fa39d04b?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',54,'06d96ff7cafc656a04a14dc9edb453746120901e1a076d0d23a31c886dfacee4','2ceceb32e1169cadd36e47c21bec55ddb1cec7e7b000bf8839cc01b91ec8b44b',NULL,'2026-08-13T02:28:34.296Z','2026-10-07T21:00:49.250Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["رياضة","جامعة الملك عبدالله للعلوم والتقنية","التعليم والتدريب","الرياضة السعودية","التقنية والتحول الرقمي","الرياض","الباحة"]','["جامعة الملك عبدالله للعلوم والتقنية","التعليم والتدريب","الرياضة السعودية","التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":5.5},{"category":"المناطق","score":4.5},{"category":"الاقتصاد","score":4}]','Updated','2026-10-07T21:00:49.250Z',200,73,0,'source_content_changed','',NULL,NULL,'body:74ddd62c5f68830118082b31392c07c4dbaf6711122aa7d67ff40d9bdfe9703b','Wed, 07 Oct 2026 21:00:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4e62ea04-6ae3-45c7-945d-eadd9886ebbf','news-4e62ea04-6ae3-45c7-945d-eadd9886ebbf','مقتل جنديين أمريكيين في تحطم هليكوبتر أباتشي بولاية تكساس','مقتل جنديين امريكيين في تحطم هليكوبتر اباتشي بولايه تكساس','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية لقي جنديان أمريكيان حتفهما، اليوم الأربعاء، إثر تحطم هليكوبتر عسكرية من طراز «أباتشي» تابعة لقاعدة فورت هود في حقل بمقاطعة بيل بولاية تكساس ، ما أدى إلى اندلاع حريق واسع في المنطقة.','["لقي جنديان أمريكيان حتفهما، اليوم الأربعاء، إثر تحطم هليكوبتر عسكرية من طراز «أباتشي» تابعة لقاعدة فورت هود في حقل بمقاطعة بيل بولاية تكساس ، ما أدى إلى اندلاع حريق واسع في المنطقة.","وقال مسؤولون إن الحادث وقع في مقاطعة بيل، التي تبعد نحو 100 كيلومتر شمال أوستن ، عاصمة ولاية تكساس.","وأكد جريج أبوت ، حاكم ولاية تكساس، عبر منصة «إكس»، تحطم هليكوبتر من طراز «أباتشي» في مقاطعة بيل أثناء تنفيذ عمليات في فورت هود، مشيرًا إلى مقتل اثنين من أفراد الجيش الأمريكي."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/y2w3nta1s','https://ajel.sa/international/y2w3nta1s','https://ajel.sa/international/y2w3nta1s','https://ajel.sa/international/y2w3nta1s','فريق التحرير','السعودية','2026-08-12T17:38:00.000Z','Wed, 07 Oct 2026 21:00:44 GMT','2026-08-13T04:34:03.364Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-crop-YiziA4BY.png','/api/media/4e62ea04-6ae3-45c7-945d-eadd9886ebbf','/api/media/4e62ea04-6ae3-45c7-945d-eadd9886ebbf?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',40,'a1446f735da32f9d8c3d7506cad378ab9916f1b21d4c3545689b31f9fbe87caf','adb95e4d66b3a0da0d67fc5eee8ea6c650aae32230db03f3d8efed0636d9d237',NULL,'2026-08-13T04:34:03.364Z','2026-10-07T21:00:45.951Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السياسة"]','[]','manual_approved','below_category_threshold','[{"category":"السفر","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T21:00:45.951Z',200,76,0,'source_content_changed','',NULL,NULL,'body:988824cdd740b8191dcc08d23288dde73bafb5258b900bbdd908f567fa647b5e','Wed, 07 Oct 2026 21:00:44 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a350e0f8-098f-4960-8cf6-e3276fa9cf3f','news-a350e0f8-098f-4960-8cf6-e3276fa9cf3f','لأول مرة منذ 120 عاماً.. كسوف كلي نادر للشمس يعبر أوروبا وجزئي يلامس شمال أفريقيا','لاول مره منذ 120 عاما كسوف كلي نادر للشمس يعبر اوروبا وجزئي يلامس شمال افريقيا','شهدت عدة مناطق في نصف الكرة الشمالي، اليوم الأربعاء، كسوفاً كلياً للشمس هو الوحيد من نوعه في عام 2026، إذ عبر مسار الكسوف الكلي أقصى شمال شرق سيبيريا الروسية، فغطاء غرينلاند الجليدي، فالحافة الغربية لأيسلندا، ثم شمال إسبانيا وطرفاً صغيراً من البرتغال، في مشهد فلكي وصفه خبراء بالنادر.','["وبلغت مدة الكسوف الكلي القصوى دقيقتين و18 ثانية على امتداد خط مساره البالغ عرضه نحو 290 كيلومتراً، فيما شهدت مناطق واسعة من أوروبا وكندا وشمال الولايات المتحدة وشمال غرب أفريقيا كسوفاً جزئياً ، إذ رصدت مدن كبرى كمدريد ولندن وباريس تغطية تجاوزت 90% من قرص الشمس.","أول كسوف كلي في إسبانيا منذ 1905 ويكتسب الحدث أهمية خاصة لكونه أول كسوف كلي يمرّ فوق البرّ الأوروبي الإسباني منذ عام 1905، أي منذ 120 عاماً، وهو ما دفع آلاف هواة الفلك والسياح إلى التوافد نحو شمال إسبانيا لمتابعته قبيل غروب الشمس.","ويُعد هذا الكسوف الأول في «ثلاثية» فلكية نادرة ستشهدها إسبانيا، إذ يتبعه كسوفان آخران في أغسطس 2027 ويناير 2028.","لم يكن مرئياً في المملكة وفلكياً، لم يكن الكسوف مرئياً من سماء المملكة ودول الخليج ، إذ وقع في ساعات ما بعد غروب الشمس بالتوقيت المحلي، فيما اقتصر ما طال العالم العربي على كسوف جزئي محدود شوهد في أقصى شمال غرب أفريقيا."]','العالم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/46xolip','https://sabq.org/article/46xolip','','https://sabq.org/article/46xolip','صحيفة سبق','السعودية','2026-08-12T12:11:00.000Z','2026-08-12T15:12:00.000Z','2026-08-13T04:38:45.981Z','https://media.sabq.org/news/2026/08/200c7e2d-09ee-453f-803c-c5801ec71a49/w1600.webp','/api/media/a350e0f8-098f-4960-8cf6-e3276fa9cf3f','/api/media/a350e0f8-098f-4960-8cf6-e3276fa9cf3f?variant=thumbnail','لأول مرة منذ 120 عاماً.. كسوف كلي نادر للشمس يعبر أوروبا وجزئي يلامس شمال أفريقيا',1600,1067,'valid','published','archived','valid',92,'e42067b35e387623740f7b187c3f2f42ff6246a9886f18d71fe5e852a128c946','6cd66dcf8894b251636952f2dae34674c65068048786eeda8430f74cffb1980a','محدّث','2026-08-13T04:38:45.981Z','2026-10-07T21:00:46.598Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["أوروبا","الولايات المتحدة"]','["الولايات المتحدة"]','classified','','[{"category":"الرياضة","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T21:00:46.598Z',200,75,0,'source_article_available','',NULL,NULL,'body:1077cc09907ac234ccf3cbe68b0242e0080822b550ed656e47428db04351f1bb','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('72b523c5-9dce-479c-93d8-418779e74256','news-72b523c5-9dce-479c-93d8-418779e74256','رغم رباعية الجزيرة.. "فلاتة" يصعّد ضد رئيس الاتحاد: "غادر.. ففي الترك راحة"','رغم رباعيه الجزيره فلاته يصعد ضد رئيس الاتحاد غادر ففي الترك راحه','لم تمنع الرباعية التي سجلها الاتحاد في شباك الجزيرة الإماراتي، وفوزه 4-1 وتأهله إلى مرحلة الدوري من دوري أبطال آسيا للنخبة، استمرار الانتقادات الموجهة إلى إدارة النادي، إذ أعاد الإعلامي الرياضي عبدالله فلاتة فتح ملف فهد سندي رئيس مجلس إدارة النادي.','["وأكد فلاتة أن الانتصار القاري لا ينبغي أن يصرف الأنظار عن المطالب التي يراها أساسية داخل النادي، مشيراً إلى أن موعد رحيل سندي قد حان، وكتب عبر حسابه في منصة «إكس»: «فوز الاتحاد بـ4 أهداف وتأهله للنخبة لن يخدعنا ونترك المطالب الأساسية».","واستشهد فلاتة بما وصفه بقول أحد الاتحاديين، من أن سندي نجح في توحيد جماهير النادي على مطلب واحد، قبل أن يوجّه رسالة مباشرة إليه، مؤكداً أن ما يتعرض له لا يستحق الاستمرار من أجله، وأنه غير مُجبر على البقاء في منصبه.","واختتم فلاتة رسالته بعبارة حاسمة دعا فيها سندي إلى رفض أي مطالب بالاستمرار، قائلاً: «غادر، ففي الترك راحة»."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/a4i382u','https://sabq.org/article/a4i382u','','https://sabq.org/article/a4i382u','صحيفة سبق','السعودية','2026-08-12T12:05:00.000Z','2026-08-12T15:06:00.000Z','2026-08-13T04:38:46.593Z','https://media.sabq.org/news/2026/08/f4dd0257-64c3-4bb1-94e4-42381383d865/w1200.webp','/api/media/72b523c5-9dce-479c-93d8-418779e74256','/api/media/72b523c5-9dce-479c-93d8-418779e74256?variant=thumbnail','رغم رباعية الجزيرة.. "فلاتة" يصعّد ضد رئيس الاتحاد: "غادر.. ففي الترك راحة"',1200,675,'valid','published','archived','valid',41,'10a06bb648df334014efd6f7183c8e6908bac5a40ef867a248ca0faaef4cfbe1','5a7bfb1ae89de43f0215cd2864fce245f5b726f302ffbfaf79235cf1f91f3a8e','محدّث','2026-08-13T04:38:46.593Z','2026-10-07T21:00:57.584Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس الاتحاد غادر ففي الترك","الرياضة السعودية"]','["رئيس الاتحاد غادر ففي الترك","الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T21:00:57.584Z',200,74,0,'source_article_available','',NULL,NULL,'body:c66c83357aee7ff2fe021800c5ff9534ee493dcdf8257b6161e75292fedcd0f4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('612fded8-4a20-4e28-a15c-bab7b40c1952','news-612fded8-4a20-4e28-a15c-bab7b40c1952','زلزال بقوة 5.5 درجة قبالة سواحل السلفادور','زلزال بقوه 5 5 درجه قباله سواحل السلفادور','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية أفادت هيئة المسح الجيولوجي الأمريكية بأن زلزالا بقوة 5.5 درجة ضرب قبالة سواحل السلفادور يوم الأربعاء.','["أفادت هيئة المسح الجيولوجي الأمريكية بأن زلزالا بقوة 5.5 درجة ضرب قبالة سواحل السلفادور يوم الأربعاء.","وأوضحت الهيئة أن الزلزال وقع على عمق 56.8 كيلومتر.","وقال شهود من رويترز إن سكان العاصمة شعروا بالزلزال الذي وصفوه بأنه متوسط."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/14z5x2nt0','https://ajel.sa/international/14z5x2nt0','https://ajel.sa/international/14z5x2nt0','https://ajel.sa/international/14z5x2nt0','فريق التحرير','السعودية','2026-08-12T20:46:00.000Z','Wed, 07 Oct 2026 21:00:53 GMT','2026-08-13T06:39:43.100Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%B2%D9%84%D8%B2%D8%A7%D9%84-tOEN0YWk.jpg','/api/media/612fded8-4a20-4e28-a15c-bab7b40c1952','/api/media/612fded8-4a20-4e28-a15c-bab7b40c1952?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',40,'20abb72a9866ef929bc3b682137ea31701165f7ec576670c1110a2735085fd5c','173b0ac8298993c7a6a460c994a3f9c507cc6b55481ea4dba81d89bd52eb3c99',NULL,'2026-08-13T06:39:43.100Z','2026-10-07T21:00:55.185Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة المسح الجيولوجي الأمريكية بأن"]','["هيئة المسح الجيولوجي الأمريكية بأن"]','manual_approved','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Updated','2026-10-07T21:00:55.185Z',200,73,0,'source_content_changed','',NULL,NULL,'body:98ddcd66ed9829f378165650eb59255cda446bbdd423b6a77d8418ad617c4888','Wed, 07 Oct 2026 21:00:53 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8d5ccc1b-19f3-4221-8c06-cf7e9a391c58','news-8d5ccc1b-19f3-4221-8c06-cf7e9a391c58','بقعة نفطية ضخمة تضرب سواحل عُمان وتهدد محمية بحرية نادرة','بقعه نفطيه ضخمه تضرب سواحل عمان وتهدد محميه بحريه نادره','أعلنت هيئة البيئة العمانية، الأربعاء، أن تسرباً نفطياً هائلاً من ناقلة جانحة بات يطال السواحل العمانية، محذّرةً من أن يتحول إلى واحدة من أسوأ الكوارث البيئية البحرية في العالم منذ سنوات، بعد أن انتشر دون موانع تُذكر على مدى أسابيع.','["وأوضحت الهيئة في بيانها أن «نتائج الرصد أظهرت تأثر بعض الشواطئ في منطقة رأس مدركة بالتلوث الزيتي، مع توقع تأثر نطاق شاطئي يصل طوله إلى 40 كيلومتراً في المنطقة ذاتها، فضلاً عن احتمال تأثر الشواطئ الجنوبية لجزيرة مصيرة خلال الساعات القادمة بنطاق يتراوح بين 10 و20 كيلومتراً».","وأفاد جون آموس، المتخصص في حوادث تسرب النفط والرئيس التنفيذي لمنظمة «سكاي تروث» غير الربحية، بعد مراجعته صور الأقمار الصناعية، بأن البقعة باتت تغطي مساحة تتجاوز 2000 كيلومتر مربع.","ناقلة محمّلة بنفط روسي وخاضعة للعقوبات كانت ناقلة النفط «كارولين بيزنجي»، التي تحمل نحو 800 ألف برميل من النفط الروسي وتخضع لعقوبات دولية، قد جنحت في 30 يونيو قبالة جزيرة عمانية تُشكّل جزءاً من محمية طبيعية بحرية تضم أنواعاً نادرة من الحياة البرية، من بينها الحيتان الحدباء وطائر الغاق السقطري المعروف بـ«اللُوه».","وكانت الناقلة قد أبلغت لأول مرة عن تعرضها لصعوبات قبالة سواحل اليمن في الثامن من يونيو، وأشارت مصادر من القطاع البحري إلى وقوع انفجار على متنها."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/cov87e6','https://sabq.org/article/cov87e6','','https://sabq.org/article/cov87e6','صحيفة سبق','السعودية','2026-08-12T13:04:00.000Z','2026-08-12T16:04:00.000Z','2026-08-13T06:44:25.342Z','https://media.sabq.org/news/2026/08/0771be39-509b-4189-b737-636c63e52609/w640.webp','/api/media/8d5ccc1b-19f3-4221-8c06-cf7e9a391c58','/api/media/8d5ccc1b-19f3-4221-8c06-cf7e9a391c58?variant=thumbnail','بقعة نفطية ضخمة تضرب سواحل عُمان وتهدد محمية بحرية نادرة',640,431,'valid','published','archived','valid',92,'2087b6292315d3bd8c45a7380cb3e1ef77443d807448875fe63dd2d41cf9592b','118dc32169381ab385fe2930d6bb698d5b154d2897c3c1392c4cdd224380ef66','محدّث','2026-08-13T06:44:25.342Z','2026-10-07T21:00:44.524Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","اليمن"]','["الطاقة والنفط"]','manual_approved','below_category_threshold','[{"category":"العالم","score":3},{"category":"التقنية","score":2},{"category":"السياسة","score":1.5}]','Active','2026-10-07T21:00:44.524Z',200,75,0,'source_article_available','',NULL,NULL,'body:309785f94e9740e931bbe6639fab778001c656545ffa20fc4a7dbd8e567cd274','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('48440dec-4f38-464f-bfa6-399e5dca2596','news-48440dec-4f38-464f-bfa6-399e5dca2596','وفاة ماجد الحميدان مدير إدارة تنفيذ حلول الأعمال بـ«البلديات والإسكان» إثر حادث غرق خارج المملكة.. والصلاة عليه غداً الخميس','وفاه ماجد الحميدان مدير اداره تنفيذ حلول الاعمال بـ البلديات والاسكان اثر حادث غرق خارج المملكه والصلاه عليه غدا الخميس','انتقل إلى رحمة الله الأستاذ ماجد بن يحيى الحميدان، مدير إدارة تنفيذ حلول الأعمال في وزارة البلديات والإسكان، إثر تعرضه لحادث غرق خارج المملكة خلال رحلة سياحية برفقة زوجته وأطفاله.','["وبذلت سفارة المملكة جهوداً كبيرة في متابعة حالته منذ وقوع الحادث، فيما خلّفت الفاجعة أثراً بالغاً في نفوس منسوبي السفارة والمواطنين السعوديين هناك.","وعُرف الفقيد — رحمه الله — بدماثة أخلاقه وطيب معشره وجميل سيرته، فكان خبر رحيله موجعاً لكل من عرفه من زملائه ومحبيه.","ويُصلى على الفقيد غداً الخميس 13 أغسطس بعد صلاة العصر في جامع المهيني، على أن يوارى جثمانه الثرى في مقبرة الشمال.","نسأل الله أن يتغمده بواسع رحمته ومغفرته، وأن يسكنه فسيح جناته، وأن يتقبله في الشهداء، وأن يلهم أهله وذويه الصبر والسلوان.."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/fnphu07','https://sabq.org/article/fnphu07','','https://sabq.org/article/fnphu07','صحيفة سبق','السعودية','2026-08-12T12:55:00.000Z','2026-08-12T15:55:00.000Z','2026-08-13T06:44:25.550Z','https://media.sabq.org/news/2026/08/dddfbb50-9fb7-452c-baa6-61e5fe652041/w1205.webp','/api/media/48440dec-4f38-464f-bfa6-399e5dca2596','/api/media/48440dec-4f38-464f-bfa6-399e5dca2596?variant=thumbnail','وفاة ماجد الحميدان مدير إدارة تنفيذ حلول الأعمال بـ«البلديات والإسكان» إثر حادث غرق خارج المملكة.. والصلاة عليه غداً الخميس',1205,764,'valid','published','archived','valid',100,'e7d685248d58565dcf5ec586c7dd779fe7e8d91899422fcf072caf47b7e25fc1','2f09b4c3afaffc505d3027ab459b1fa73e0c30b297861d74ef1422f83d6a87b7','محدّث','2026-08-13T06:44:25.550Z','2026-10-07T21:01:49.559Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','','[]','Active','2026-10-07T21:01:49.559Z',200,79,0,'source_article_available','',NULL,NULL,'body:afc3e5cb7b1d6406d948d296a736fd5818c6a104fb5df2c400ef693d32b07c19','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f2fa1cda-332f-465e-b84c-623886f5d627','news-f2fa1cda-332f-465e-b84c-623886f5d627','مركز الملك سلمان للإغاثة يواصل عملياته الإنسانية في غزة وأفغانستان والسودان','مركز الملك سلمان للاغاثه يواصل عملياته الانسانيه في غزه وافغانستان والسودان','واصل مركز الملك سلمان للإغاثة والأعمال الإنسانية تنفيذ سلسلة من العمليات الإغاثية المتزامنة في عدد من الدول المتضررة، في إطار الجهود الإنسانية التي ترعاها المملكة العربية السعودية.','["واصل مركز الملك سلمان للإغاثة والأعمال الإنسانية تنفيذ سلسلة من العمليات الإغاثية المتزامنة في عدد من الدول المتضررة، في إطار الجهود الإنسانية التي ترعاها المملكة العربية السعودية. 25 ألف وجبة ساخنة في غزة وزّع المطبخ المركزي التابع للمركز 25,000 وجبة غذائية ساخنة على الفئات الأكثر احتياجاً وسط وجنوب قطاع غزة، استفاد منها 25,000 فرد، وذلك ضمن الحملة الشعبية السعودية لإغاثة الشعب الفلسطيني.","مشروع التمكين الاقتصادي لذوي الإعاقة في غزة واصل المركز تنفيذ مشروع التمكين الاقتصادي للفئات الأشد ضعفاً والأشخاص ذوي الإعاقة في قطاع غزة، إذ أحرز المتدربون تقدماً ملحوظاً في اكتساب المهارات العملية عبر مسارات متنوعة، تشمل: الخياطة، والحلاقة الرجالية، والتجميل للنساء، وصناعة الإكسسوارات والأشغال اليدوية، والترجمة والعمل الحر، إلى جانب التدريب على المهارات الحياتية.","وأعرب المستفيدون عن شكرهم للمملكة العربية السعودية ممثلةً بمركز الملك سلمان للإغاثة، مؤكدين أن المشروع أسهم في تطوير مهاراتهم وفتح آفاق جديدة أمامهم في سوق العمل.","ويستهدف المشروع تدريب أكثر من 1,000 فرد عبر برامج متخصصة تمتد لنحو 130 ساعة تدريبية، موزّعة على 8 مسارات مهنية ورقمية، ويحصل المستفيدون في ختامها على شهادة دبلوم وحقيبة مهنية متخصصة. 60 سلة غذائية لمتضرري الفيضانات في أفغانستان وزّع المركز 60 سلة غذائية على المتضررين من الفيضانات في مدينة ميدان شهر بمركز ولاية ميدان وردك في أفغانستان، استفاد منها 420 فرداً يمثلون 60 أسرة، ضمن مشروع الأمن الغذائي والطوارئ لمتضرري…"]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/12plg3n','https://sabq.org/article/12plg3n','','https://sabq.org/article/12plg3n','صحيفة سبق','السعودية','2026-08-12T12:58:00.000Z','2026-08-12T15:58:00.000Z','2026-08-13T06:44:26.308Z','https://media.sabq.org/news/2026/08/d15346dd-1bc3-4659-a7ae-2fc91d4abb8e/w1600.webp','/api/media/f2fa1cda-332f-465e-b84c-623886f5d627','/api/media/f2fa1cda-332f-465e-b84c-623886f5d627?variant=thumbnail','مركز الملك سلمان للإغاثة يواصل عملياته الإنسانية في غزة وأفغانستان والسودان',1600,900,'valid','published','archived','valid',90,'1b465956cc74915b787a334bffb7a4ad76eeb03fdbcfdcee54a09379a907cae0','46ca68acbca4c12db1ac490cf0eb9834b0c331a3d08077c22dd6bcabe802cd2a','محدّث','2026-08-13T06:44:26.308Z','2026-10-07T21:01:49.568Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي","غزة","فلسطين"]','["الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"الوظائف وسوق العمل","score":5.5},{"category":"الاقتصاد","score":3},{"category":"التعليم","score":1.5}]','Active','2026-10-07T21:01:49.568Z',200,75,0,'source_article_available','',NULL,NULL,'body:6616686ea0d9a7cb43ef9c8ce833a30210a72d0b6a1e1bd3d12ba673074a5f93','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0ae2acaf-ce66-4cf9-95c9-5451f7718217','news-0ae2acaf-ce66-4cf9-95c9-5451f7718217','ضيوف برنامج خادم الحرمين للعمرة يزورون مجمع كسوة الكعبة المشرفة','ضيوف برنامج خادم الحرمين للعمره يزورون مجمع كسوه الكعبه المشرفه','زار ضيوف الدفعة الثانية من برنامج خادم الحرمين الشريفين للعمرة والزيارة، الذي تنفذه وزارة الشؤون الإسلامية والدعوة والإرشاد، مجمعَ الملك عبدالعزيز لكسوة الكعبة المشرفة بمكة المكرمة، ضمن البرنامج الثقافي المصاحب الذي أعدته الوزارة لإثراء تجربة المستضافين خلال إقامتهم في العاصمة المقدسة.','["واطّلع الضيوف خلال الزيارة على تاريخ صناعة كسوة الكعبة المشرفة ومراحل إنشاء المجمع وتطوره، واستمعوا إلى شرح مفصّل عن المراحل التاريخية التي مرّت بها هذه الصناعة العريقة، وشاهدوا نماذج وصوراً توثّق مسيرتها وما شهدته من تطور في أساليب التنفيذ ودقة الصنعة.","وتعرّف الضيوف على مراحل صناعة الكسوة كاملةً، بدءاً من إعداد النسيج وتجهيزه، مروراً بمراحل الحياكة والتطريز، وصولاً إلى التجميع النهائي، فضلاً عن التعرف على المواد الخام المستخدمة وما تستلزمه هذه الصناعة من مهارات دقيقة وأعمال فنية متقنة تنفذها كوادر وطنية متخصصة.","وأعرب الضيوف عن إعجابهم بما شاهدوه من دقة وإتقان في صناعة الكسوة، مشيدين بالمهارات العالية التي تمتلكها الكوادر الوطنية، ومؤكدين أن هذه الجهود تعكس عناية المملكة العربية السعودية واهتمامها ببيت الله الحرام وخدمة الحرمين الشريفين."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/1pzea75','https://sabq.org/article/1pzea75','','https://sabq.org/article/1pzea75','صحيفة سبق','السعودية','2026-08-12T12:48:00.000Z','2026-08-12T15:48:00.000Z','2026-08-13T06:44:27.346Z','https://media.sabq.org/news/2026/08/273362e6-6e04-4443-8f76-3e77e37ce180/w1600.webp','/api/media/0ae2acaf-ce66-4cf9-95c9-5451f7718217','/api/media/0ae2acaf-ce66-4cf9-95c9-5451f7718217?variant=thumbnail','صورة من الألبوم',1600,1066,'valid','published','archived','valid',99,'fff722454038f894cb79936398f4f10de95a51b5224f17e12ad6890adc897662','a26268fb19aff3ebef8b98b02b8f8331745fa5b0763c92d30733413a007b627b','محدّث','2026-08-13T06:44:27.346Z','2026-10-07T21:01:52.775Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["خادم الحرمين للعمرة يزورون مجمع"]','["خادم الحرمين للعمرة يزورون مجمع"]','classified','','[{"category":"المجتمع","score":1.5},{"category":"الثقافة","score":1.5},{"category":"الطاقة والصناعة","score":1.5}]','Active','2026-10-07T21:01:52.775Z',200,78,0,'source_article_available','',NULL,NULL,'body:b0a799ef5d39eaa7fcfc458997513066d27f0495641866330fdbdecff527e8ad','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('768bd760-60c7-4a7b-b791-bd3dc677c15d','news-768bd760-60c7-4a7b-b791-bd3dc677c15d','"ترامب" يعلن السيطرة الكاملة على مضيق هرمز ويصف إيران بـ«كلام بلا فعل»','ترامب يعلن السيطره الكامله علي مضيق هرمز ويصف ايران بـ كلام بلا فعل','أعلن الرئيس الأمريكي دونالد ترامب، الأربعاء، أن «الولايات المتحدة تسيطر سيطرة كاملة على مضيق هرمز»، وذلك في منشور نشره عبر حسابه على منصة «تروث سوشيال».','["وقال ترامب: «أعتقد أننا سنحافظ على هذه السيطرة، ويُطلق الجميع على حصارنا البحري اسم جدار من فولاذ».","وأكد الرئيس الأمريكي أن إيران «لا تستطيع فعل أي شيء حياله»، مستعرضاً ما وصفه بضعف الجانب الإيراني، إذ قال: «ليس لديهم أسطول بحري، ولا سلاح جو، وجنودهم المتبقون لا يتقاضون رواتبهم، والحرس الثوري الإيراني مُنهك ويهرب، وقيادتهم غير مستقرة في أحسن الأحوال».","وتطرّق ترامب إلى الأوضاع الاقتصادية في إيران، كاتباً: «ليس لديهم مال، بلادهم في حالة يُرثى لها، كل ما لديهم أخبار كاذبة وتضخم بنسبة 300%، والوضع يزداد سوءاً.","إيران مجرد كلام بلا فعل، ولم تعد مستبدة الشرق الأوسط»."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/geg8sl2','https://sabq.org/article/geg8sl2','','https://sabq.org/article/geg8sl2','صحيفة سبق','السعودية','2026-08-12T12:42:00.000Z','2026-08-12T15:42:00.000Z','2026-08-13T06:44:27.439Z','https://media.sabq.org/news/2026/08/29abb1a8-d8a8-4f2a-955f-e613ff5a7c72/w801.webp','/api/media/768bd760-60c7-4a7b-b791-bd3dc677c15d','/api/media/768bd760-60c7-4a7b-b791-bd3dc677c15d?variant=thumbnail','"ترامب" يعلن السيطرة الكاملة على مضيق هرمز ويصف إيران بـ«كلام بلا فعل»',801,451,'valid','published','archived','valid',99,'9256347364fbad1a8b44743a17f2f9a00b5866706e5041c14cc7a14a0d35d6af','76fbb28e0aba72e3a28ac39129cc4efca1fa005ce28288b9b0f2e42c2c48adea','محدّث','2026-08-13T06:44:27.439Z','2026-10-07T21:00:43.068Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","الاقتصاد والأسواق","إيران","الشرق الأوسط"]','["الثقافة والفنون","الاقتصاد والأسواق","الشرق الأوسط"]','classified','','[{"category":"الاقتصاد","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"العالم","score":1.5}]','Active','2026-10-07T21:00:43.068Z',200,72,0,'source_article_available','',NULL,NULL,'body:a6165acf0a2f31c684d01103683de50c5a6c2a0e4f4698ec8f164980f4203863','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('36f54aec-2d0e-46ac-ae90-fbc26c487b91','news-36f54aec-2d0e-46ac-ae90-fbc26c487b91','وفد أمني عراقي رفيع يزور المملكة لبحث ملفات أمنية مشتركة','وفد امني عراقي رفيع يزور المملكه لبحث ملفات امنيه مشتركه','يتوجه وفد أمني عراقي رفيع المستوى إلى المملكة العربية السعودية، يوم غد الخميس، لإجراء مباحثات أمنية مع الجانب السعودي حول عدد من القضايا المشتركة، وفق ما أعلنته وكالة الأنباء الرسمية العراقية.','["ويترأس الوفد كلٌّ من مدير مكتب القائد العام للقوات المسلحة الفريق أول الركن عبد الأمير الشمري، ورئيس جهاز المخابرات حميد الشطري، وقائد الدفاع الجوي الفريق مهند الأسدي، ورئيس جهاز مكافحة الإرهاب الفريق الركن زيد حوشي.","وتشمل أجندة المباحثات ملف الاعتداءات التي تعرضت لها المملكة العربية السعودية، وملف الطائرات المسيّرة، إلى جانب بحث سبل تعزيز التنسيق والتعاون الأمني بين البلدين في مختلف المجالات."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/c985883','https://sabq.org/article/c985883','','https://sabq.org/article/c985883','صحيفة سبق','السعودية','2026-08-12T12:52:00.000Z','2026-08-12T15:52:00.000Z','2026-08-13T06:44:27.772Z','https://media.sabq.org/news/2026/08/5471ff49-4cab-4905-a78e-e9ec287d07fe/w801.webp','/api/media/36f54aec-2d0e-46ac-ae90-fbc26c487b91','/api/media/36f54aec-2d0e-46ac-ae90-fbc26c487b91?variant=thumbnail','وفد أمني عراقي رفيع يزور المملكة لبحث ملفات أمنية مشتركة',801,451,'valid','published','archived','valid',100,'19d8b4c4e8458b4bae7e48bf7887453c62cdf8e28811907bc174390a9ad46edd','38757a1f66185b9cbee076d2b7a50e58da1a6a06d22314b2783a534575ac5524','محدّث','2026-08-13T06:44:27.773Z','2026-10-07T21:00:57.579Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','','[]','Active','2026-10-07T21:00:57.579Z',200,74,0,'source_article_available','',NULL,NULL,'body:95eb98e4754922cce1337246d78435f3373869268678a4cd1c74cb06ea30d47f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7b258526-3eb7-4d9b-82cc-04ac2f437d57','news-7b258526-3eb7-4d9b-82cc-04ac2f437d57','805.5 ألف مستفيد يقودون تقييم الحكومة الرقمية.. 87.06% نضجًا و«أبشر» تتصدر 59 منصة','805 5 الف مستفيد يقودون تقييم الحكومه الرقميه 87 06 نضجا و ابشر تتصدر 59 منصه','اتسعت دائرة تقييم الخدمات الحكومية الرقمية في المملكة خلال عام 2026 إلى مستوى غير مسبوق، بعدما تجاوز عدد المشاركين في استبيان «قيّم تجربتك الرقمية» 805.5 ألف مستفيد، لتخضع 59 منصة حكومية للتقييم، في قياس يركز على تجربة المستخدم الفعلية عند الحصول على الخدمة، وليس مجرد إتاحتها عبر القنوات الرقمية.','["وتعكس أعداد المشاركين خلال الأعوام الأربعة الماضية تنامي حضور المستفيد في عملية تطوير الخدمات الحكومية؛ إذ تجاوز عدد المشاركين 374 ألفًا في عام 2025، مقابل نحو 175 ألفًا في 2024، وأكثر من 134 ألفًا في 2023.","وبذلك ارتفع عدد المشاركين خلال عام واحد إلى أكثر من ضعف مستواه في العام السابق، وتجاوز ستة أضعاف ما كان عليه قبل ثلاثة أعوام، بما يعكس تنامي الاهتمام المجتمعي بتقييم الخدمات الحكومية الرقمية، وتحول آراء المستفيدين إلى مدخل رئيس في تحسين المنصات وتطويرها.","تجربة المستفيد تتجاوز شاشة التقييم ولا تقتصر أهمية المشاركة في الاستبيان على حجم الاستجابات، بل تمتد إلى طبيعة التجربة التي يجري قياسها؛ إذ يختبر المستفيد سهولة الدخول إلى المنصة، والعثور على الخدمة، وفهم متطلباتها، وتنفيذ إجراءاتها، إلى جانب جودة التفاعل مع قنوات الدعم وآليات التعامل مع الملاحظات والشكاوى.","ومع اتساع قاعدة المشاركين، تتوافر أمام الجهات الحكومية مجموعة أكبر من التجارب الفعلية التي تساعد على تحديد مكامن القوة ونقاط التعثر، واتخاذ قرارات تطويرية تستند إلى ما يواجهه المستخدم خلال رحلته الرقمية."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/QgTKGdx','https://sabq.org/article/QgTKGdx','','https://sabq.org/article/QgTKGdx','زيد الخمشي','السعودية','2026-08-12T12:32:00.000Z','2026-08-12T15:32:00.000Z','2026-08-13T06:44:28.794Z','https://media.sabq.org/news/2026/08/55a52363-8b84-43a4-9094-a41294d02d94/w1191.webp','/api/media/7b258526-3eb7-4d9b-82cc-04ac2f437d57','/api/media/7b258526-3eb7-4d9b-82cc-04ac2f437d57?variant=thumbnail','805.5 ألف مستفيد يقودون تقييم الحكومة الرقمية.. 87.06% نضجًا و«أبشر» تتصدر 59 منصة',1191,2000,'valid','published','archived','valid',52,'a51ffdb98251278c910233539f0383e169421daf99ec429522c6bcf45777440f','a3e7689a44a8a838737690df378e07240bba9db3491ef19df09f59d6cb9f4607','محدّث','2026-08-13T06:44:28.794Z','2026-10-07T21:01:56.350Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس في تحسين المنصات وتطويرها","التقنية والتحول الرقمي"]','["رئيس في تحسين المنصات وتطويرها","التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"السياسة","score":3},{"category":"المجتمع","score":1.5},{"category":"الصحة","score":1.5}]','Active','2026-10-07T21:01:56.350Z',200,80,0,'source_article_available','',NULL,NULL,'body:f35db56c3f6937bccaba0559e6cd3f5a332c90b234581a4fe4e81a506751ce30','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fbe1fd87-ad71-4b52-b73a-005671c57bf1','news-fbe1fd87-ad71-4b52-b73a-005671c57bf1','من الجير إلى الهجين.. تعرّف على أبرز أنواع الصقور في المزاد الدولي لمزارع الإنتاج 2026','من الجير الي الهجين تعرف علي ابرز انواع الصقور في المزاد الدولي لمزارع الانتاج 2026','تضم قائمة الصقور المعروضة في المزاد الدولي لمزارع إنتاج الصقور 2026، الذي ينظمه المركز الوطني للصقور في مقره بمَلهم شمال مدينة الرياض، أنواعاً وفئات متعددة تشمل الجير والشاهين والحر والهجين، ولكل منها خصائص تميزها من حيث الحجم واللون والبنية والأداء، وهي صفات تحظى باهتمام الصقارين عند اختيار ما يتناسب مع احتياجاتهم وأغراض الاقتناء.','["وأوضح سامر ذياب السليمي، ممثل مزرعة محلية مشاركة في المزاد، أن صقور الجير تتميز بكبر حجمها وقوة بنيتها وتعدد ألوانها التي تتدرج من الأبيض إلى الرمادي والألوان الداكنة، مشيراً إلى أن مزارع الإنتاج تعمل على تطوير خطوط مختلفة منها وفق الصفات المستهدفة في كل خط إنتاج.","وأشار السليمي إلى أن الشاهين يُعرف بسرعته وبنيته الانسيابية وأجنحته المدببة، ويحظى باهتمام واسع لدى الصقارين لما يتمتع به من قدرات في الطيران والانقضاض، فيما يتميز الحر بقوة بنيته ومكانته الراسخة في أوساط الصقارين، وارتباطه التاريخي العميق بممارسة الصقارة والصيد في المنطقة.","وبيّن أن إنتاج المزارع لا يقتصر على الأنواع الخالصة، بل يشمل أنواعاً هجينة تجمع صفات من أكثر من نوع، من بينها فئات متداولة في أوساط الصقارين ومسابقات الصقور، كـ«الجير شاهين» و«مثلوث الجير» وغيرها، إذ يسعى المنتجون من خلال اختيار خطوط الإنتاج إلى الوصول إلى صفات محددة تتعلق بالسرعة أو الحجم أو اللون أو الأداء.","وأضاف أن الاختلاف بين الصقور لا يقتصر على مسمى النوع أو الفئة، إذ يولي الصقار اهتماماً كذلك بخط الإنتاج والصفات الفردية للصقر ونتائج عائلته والغرض من اقتنائه، لا سيما مع اختلاف المواصفات المطلوبة بين صقور السباقات وسائر مجالات الصقارة."]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/1Fwyaaa','https://sabq.org/article/1Fwyaaa','','https://sabq.org/article/1Fwyaaa','صحيفة سبق','السعودية','2026-08-12T12:26:00.000Z','2026-08-12T15:28:00.000Z','2026-08-13T06:44:28.810Z','https://media.sabq.org/news/2026/08/4fb503d6-112b-49ec-aeed-404dcaca7e65/w1280.webp','/api/media/fbe1fd87-ad71-4b52-b73a-005671c57bf1','/api/media/fbe1fd87-ad71-4b52-b73a-005671c57bf1?variant=thumbnail','من الجير إلى الهجين.. تعرّف على أبرز أنواع الصقور في المزاد الدولي لمزارع الإنتاج 2026',1280,854,'valid','published','archived','valid',41,'3598ff5682ce3e0495fe158b818a02a8da15f07c3e0a64b9c9c523efe19790a5','706b4b6bc446057f538fc4f2f9b872a7bc7687c2740ccf4243b63172b82ddf1d','محدّث','2026-08-13T06:44:28.810Z','2026-10-07T21:00:44.518Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الثقافة والفنون"]','["السفر والسياحة","الثقافة والفنون"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T21:00:44.518Z',200,72,0,'source_article_available','',NULL,NULL,'body:80dd9fae9f28545d88be5ef7048519dbcd96136c6b3b7ae0ea32f5499ec29d2f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dc4210f7-13cc-44b4-bb43-1bb0240d2793','news-dc4210f7-13cc-44b4-bb43-1bb0240d2793','«الرياض» و«اليمامة» تطويان 6 عقود من الورق.. وسجال واسع حول مستقبل الصحافة','الرياض و اليمامه تطويان 6 عقود من الورق وسجال واسع حول مستقبل الصحافه','أثار قرار مؤسسة اليمامة الصحفية إيقاف النسختين الورقيتين من صحيفة «الرياض» ومجلة «اليمامة» اعتباراً من 24 أغسطس 2026، موجة واسعة من ردود الفعل في الأوساط الإعلامية والثقافية السعودية، بين من رأى في الخطوة استجابة طبيعية للتحول الرقمي وتغيّر عادات القراءة، ومن تلقّاها بحزن باعتبارها نهاية فصل طويل من تاريخ الصحافة الورقية في المملكة.','["ويأتي القرار بعد مسيرة صحفية امتدت نحو 6 عقود، إذ تأسست صحيفة «الرياض» عام 1965م لتصبح واحدة من أبرز الصحف السعودية وأكثرها حضوراً وتأثيراً، فيما تُعدّ «اليمامة» إحدى أقدم المطبوعات التابعة للمؤسسة.","و«نعي» لرفيق العمر على منصة «إكس»، استحضر عدد من الكتّاب والإعلاميين علاقتهم الطويلة بالصحافة الورقية، معتبرين أن الانتقال الكامل إلى البيئة الرقمية لا يعني مجرد تغيير وسيلة النشر، بل طيّ صفحة من الذاكرة الشخصية والمهنية.","وقال الدكتور عبدالواحد الحميد، عضو هيئة التدريس بجامعة الملك فهد للبترول والمعادن سابقاً، إن التقنية أتاحت الوصول إلى الصحف حول العالم بسهولة، مؤكداً في الوقت ذاته أنه ما زال يشعر بالحنين إلى الصحافة الورقية رغم اقتناعه بتفوق الصحافة الرقمية.","وأوضح أن اشتراكه في النسخة الورقية من «الرياض» و«اليمامة» كان يمنحه متعة خاصة، واصفاً رسالة المؤسسة بشأن إيقاف النسختين بأنها كانت بالنسبة إليه «نعياً» لرحلة طويلة مع الصحافة الورقية، بما تحمله من ملمس ورائحة وطقوس لا تعوضها الشاشة."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/iDCdCcV','https://sabq.org/article/iDCdCcV','','https://sabq.org/article/iDCdCcV','عبدالحكيم شار','السعودية','2026-08-12T12:26:00.000Z','2026-08-12T16:59:00.000Z','2026-08-13T06:44:29.009Z','https://media.sabq.org/news/2026/08/1b6a5477-2756-4793-95f7-25c7724e50d9/w1050.webp','/api/media/dc4210f7-13cc-44b4-bb43-1bb0240d2793','/api/media/dc4210f7-13cc-44b4-bb43-1bb0240d2793?variant=thumbnail','«الرياض» و«اليمامة» تطويان 6 عقود من الورق.. وسجال واسع حول مستقبل الصحافة',1050,575,'valid','published','archived','valid',52,'849bd66f86239b3f5fda2d3980b7cac1509f707ca763f2729c8a173762c7983e','28d7c14bd5c7c5f22a8f13f84a7b9ecca85cc2a1691ff7e66c00145d3da76f70','محدّث','2026-08-13T06:44:29.009Z','2026-10-07T21:01:46.831Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة التدريس بجامعة الملك فهد","الطاقة والنفط","التعليم والتدريب","التقنية والتحول الرقمي","الرياض"]','["هيئة التدريس بجامعة الملك فهد","الطاقة والنفط","التعليم والتدريب","التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T21:01:46.831Z',200,75,0,'source_article_available','',NULL,NULL,'body:cf491edc319672dacda4c46db07ea313654f14bf8c6000fd1d9664b3da678232','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('55c69e2e-0138-4cf6-aafc-852987fc89ce','news-55c69e2e-0138-4cf6-aafc-852987fc89ce','القادسية ينفّذ مبادرة «القادسية أقرب» لخدمة الأسر المحتاجة في الخبر','القادسيه ينفذ مبادره القادسيه اقرب لخدمه الاسر المحتاجه في الخبر','نفّذ نادي القادسية مبادرة «القادسية أقرب» بالتعاون مع جمعية ترميم، تزامنًا مع اليوم العالمي للعمل الإنساني، في أحياء العقربية والثقبة بمدينة الخبر، مستهدفًا الأسر الأشد حاجة وذوي الدخل المحدود.','["وتضمّنت المبادرة تنفيذ أعمال صيانة للمكيفات ومعالجة الأعطال الكهربائية البسيطة، إلى جانب التحقق من سلامة التشغيل، بمشاركة فنيين ومتطوعين، بما يُسهم في تحسين جودة حياة الأسر المستفيدة ورفع مستوى السلامة المنزلية.","كما شملت المبادرة تقديم توعية مباشرة للمستفيدين من قِبل المختصين عقب تنفيذ أعمال الصيانة، تناولت الاستخدام الصحيح للمكيفات، والمحافظة على التمديدات الكهربائية، وتجنّب الأحمال الزائدة، وأهمية إجراء الصيانة الدورية.","وتأتي مبادرة «القادسية أقرب» ضمن جهود نادي القادسية في تعزيز الشراكات المجتمعية مع القطاع غير الربحي، وتفعيل دوره في خدمة المجتمع، انطلاقًا من مفهوم أن العمل الإنساني يبدأ من المحيط القريب ويستهدف تلبية الاحتياجات الفعلية لأفراد المجتمع.","وسعت المبادرة إلى تحقيق أثر مستدام يتجاوز أعمال الصيانة، من خلال رفع وعي الأسر بأساليب المحافظة على منازلهم وسلامتها، بما يعزز جودة الحياة ويُرسّخ أثرًا إيجابيًا مستمرًا لدى المستفيدين."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ljxf1sx','https://sabq.org/article/ljxf1sx','','https://sabq.org/article/ljxf1sx','صحيفة سبق','السعودية','2026-08-12T12:16:00.000Z','2026-08-12T15:16:00.000Z','2026-08-13T06:44:30.231Z','https://media.sabq.org/news/2026/08/fa6d6e02-44f7-4eeb-a1ec-e95959031a52/w1600.webp','/api/media/55c69e2e-0138-4cf6-aafc-852987fc89ce','/api/media/55c69e2e-0138-4cf6-aafc-852987fc89ce?variant=thumbnail','القادسية ينفّذ مبادرة «القادسية أقرب» لخدمة الأسر المحتاجة في الخبر',1600,1066,'valid','published','archived','valid',54,'58973a21dedd143214a1786bde9f98b3c94df551925f5159d5b47f2c352ce4d4','75a72c5a4cb0fefec07eb3a8b79b09f6982c97da435e1d4160c8b53916319e64','محدّث','2026-08-13T06:44:30.231Z','2026-10-07T21:00:43.064Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":3},{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:00:43.064Z',200,70,0,'source_article_available','',NULL,NULL,'body:46693f04e1c26b893cabfc118d6ce5a5bdc56503d3424103a48a8f8af68c5f6c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3591e259-af8f-4216-beca-8d935e12d4f0','news-3591e259-af8f-4216-beca-8d935e12d4f0','طقس المملكة الخميس.. أمطار رعدية ورياح نشطة على عدة مناطق','طقس المملكه الخميس امطار رعديه ورياح نشطه علي عده مناطق','توقّع المركز الوطني للأرصاد في تقريره عن حالة الطقس هذا اليوم هطول أمطار رعدية متوسطة إلى غزيرة تؤدي إلى جريان السيول مصحوبة بزخات من البرد على أجزاء من منطقتي جازان و عسير ، في حين تكون خفيفة إلى متوسطة على أجزاء من مناطق نجران ، الباحة ، ومرتفعات منطقة مكة المكرمة، وتكوّن السحب الرعدية الممطرة على أجزاء من منطقتي الرياض و الشرقية ، خاصة الجنوبية منها.','["وتؤثّر الرياح النشطة المثيرة للأتربة والغبار على أجزاء من تلك المناطق، وتصل إلى شبه انعدام في مدى الرؤية الأفقية على الأجزاء الساحلية من منطقتي المدينة المنورة ومكة المكرمة، بينما تظل درجات الحرارة العظمى مرتفعة على المنطقة الشرقية وأجزاء من مناطق الرياض، مكة المكرمة والمدينة المنورة.","وأشار التقرير إلى أن حركة الرياح السطحية على البحر الأحمر شمالية غربية إلى غربية بسرعة 20-45 كم/ساعة على الجزء الشمالي والأوسط وبسرعة 15-35 كم/ساعة على الجزء الجنوبي تصل إلى أكثر من 50 كم/ساعة على الجزء الأوسط كذلك تكوّن السحب الرعدية الممطرة على الجزء الجنوبي، وارتفاع الموج من متر إلى مترين يصل إلى مترين ونصف على الجزء الأوسط كذلك مع تكوّن السحب الرعدية الممطرة على الجزء الجنوبي، وحـالة البحر متوسط الموج يصل إلى…","فيما ستكون حركة الرياح على الخليج العربي جنوبية غربية إلى جنوبية شرقية على الجزء الشمالي والأوسط وشمالية شرقية إلى شمالية غربية على الجزء الجنوبي بسرعة 10-28 كم/ساعة وارتفاع الموج من نصف المتر إلى متر وحالة البحـر خفيف الموج."]','البيئة والمناخ','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/ulj4ymc15','https://ajel.sa/local/ulj4ymc15','https://ajel.sa/local/ulj4ymc15','https://ajel.sa/local/ulj4ymc15','فريق التحرير','السعودية','2026-08-12T22:33:00.000Z','Wed, 07 Oct 2026 21:00:39 GMT','2026-08-13T08:45:36.240Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%B7%D9%82%D8%B3-5-qmpEo8ov.jpg','/api/media/3591e259-af8f-4216-beca-8d935e12d4f0','/api/media/3591e259-af8f-4216-beca-8d935e12d4f0?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',86,'899b129566dd4bd3d1a9b00fb64479ec813c02da0682b6fe6c2a60602471446f','6d90f4638b263f4783dff4e96f98c457fff3defa8c7f2fc27b1fb665d6f41312',NULL,'2026-08-13T08:45:36.240Z','2026-10-07T21:00:41.280Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة","الرياض","الخليج العربي","المدينة المنورة"]','["الطقس والمناخ","الخليج العربي","المدينة المنورة"]','classified','','[{"category":"المناطق","score":4.5},{"category":"أخبار السعودية","score":3},{"category":"السفر","score":3}]','Updated','2026-10-07T21:00:41.280Z',200,71,0,'source_content_changed','',NULL,NULL,'body:7e89832eefaec8e1b652e8aec87edc5b11cabc44ea29514305d13de8a642aee9','Wed, 07 Oct 2026 21:00:39 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f4ef1f9a-4361-4855-8813-c1c39214737a','news-f4ef1f9a-4361-4855-8813-c1c39214737a','وزيرة الدفاع الإسبانية: أي اعتداء على سبتة ومليلية هجوم على إسبانيا كلها','وزيره الدفاع الاسبانيه اي اعتداء علي سبته ومليليه هجوم علي اسبانيا كلها','أكدت وزيرة الدفاع الإسبانية مرغريتا روبليس أن أي اعتداء على مدينتي سبتة ومليلية ذاتيتَي الحكم يُعدّ هجوماً على إسبانيا بأسرها، مشددةً على أن القوات المسلحة ستدعم قوات الأمن في المدينتين في مواجهة أي تهديد.','["جاءت تصريحات الوزيرة روبليس رداً على ما أدلى به وزير العدل المغربي عبد اللطيف وهبي خلال مقابلة مع قناة «الشرق بلومبيرغ»، إذ أكد أن الرباط لم تتخلَّ عن مطالبتها باستعادة سيادتها على المدينتين، وأنها تطرح هذا الملف باستمرار على طاولة المباحثات مع مدريد.","وقال وهبي في تصريحه: «نتمسك بأراضينا ونريد حل الإشكال مع إسبانيا بالحوار.","سياسة المغرب هي التعامل بنفَس طويل مع استعادتهما إلى التراب المغربي، ونحن نطرح الموضوع على الإسبان باستمرار في الاجتماعات بيننا».","وردّت الوزيرة الإسبانية في تصريح لوسائل الإعلام بالقول: «لا يمكن لأحد أن يتعدى على سبتة ومليلية."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/xqpdwhx','https://sabq.org/article/xqpdwhx','','https://sabq.org/article/xqpdwhx','صحيفة سبق','السعودية','2026-08-12T13:50:00.000Z','2026-08-12T16:50:00.000Z','2026-08-13T08:50:18.253Z','https://media.sabq.org/news/2026/08/6d520904-1255-4b51-96e5-2fac182abc3b/w846.webp','/api/media/f4ef1f9a-4361-4855-8813-c1c39214737a','/api/media/f4ef1f9a-4361-4855-8813-c1c39214737a?variant=thumbnail','وزيرة الدفاع الإسبانية: أي اعتداء على سبتة ومليلية هجوم على إسبانيا كلها',846,551,'valid','published','archived','valid',93,'706dd43effa3cde8405cfdbc65f8b8ce6ba18eb98cd509395c1eddf2fcd1c2ba','7496d8487f53051ed69557bc8e762c5d154252c99d79006819a2fbf08a9073e4','محدّث','2026-08-13T08:50:18.253Z','2026-10-07T21:00:02.525Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير العدل المغربي عبد اللطيف","السياسة والعلاقات الدولية"]','["وزير العدل المغربي عبد اللطيف","السياسة والعلاقات الدولية"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T21:00:02.525Z',200,75,0,'source_article_available','',NULL,NULL,'body:7c1e402e51008a1d89e1653d3b42392d8fef52a7faed456ef33d629e178986c2','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3abe63df-0c4c-4f85-8af2-601ce080f394','news-3abe63df-0c4c-4f85-8af2-601ce080f394','من «طريق الموت» إلى شريان حياة.. السعودية تعيد نبض الحياة لـ 5 ملايين يمني في «هيجة العبد»','من طريق الموت الي شريان حياه السعوديه تعيد نبض الحياه لـ 5 ملايين يمني في هيجه العبد','في إطار الدعم السخي والمتواصل من المملكة العربية السعودية للسكان في اليمن عبر ذراعها التنموي البرنامج السعودي لتنمية وإعمار اليمن،​ يواصل البرنامج كتابة صفحات مضيئة من العمل الإنساني والتنموي في الأراضي اليمنية، متجاوزاً التضاريس الجغرافية المعقدة ليعيد صياغة واقع الحياة اليومية لملايين السكان.','["وفي هذا السياق، يبرز مشروع تأهيل طريق «هيجة العبد» الاستراتيجي الذي يُعد أحد أهم شرايين الربط الحيوي بين محافظة تعز والمحافظات الجنوبية مسجلاً نسبة إنجاز متقدمة بلغت نحو 92%، ليسدل الستار تدريجياً على مرحلة حالكة لطالما ارتبط فيها هذا الطريق بألقاب مرعبة جعلته يُعرف شعبياً بـ«طريق الموت». ​تضاريس بالغة الوعورة ومخاطر تاريخية و​يمثل طريق «هيجة العبد» معبراً هندسياً فريداً بقدر ما يحمله من قسوة طبيعية بالغة؛ إذ يزخر…","وطوال سنوات طويلة، شكلت هذه المنعطفات تحدياً جسيماً وعقبة كؤوداً أمام حركة المركبات الثقيلة وشاحنات نقل البضائع، وتسببت في سلسلة لا تنتهي من الحوادث المرورية المأساوية وانقلابات الشاحنات، الأمر الذي أفضى إلى تضاعف تكاليف النقل وإطالة أضعاف زمن الرحلات المعتادة. ​ولم تكن الأضرار مقتصرة على الجانب الاقتصادي فحسب، بل دفع المواطنون العابرون ثمنها أرواحاً غالية؛تشير التقارير الحقوقية والرسمية الموثقة إلى أن الفترة…","وترتكز الأعمال الجارية على رفع المعايير الفنية ومستويات السلامة المرورية، وتوسعة المنعطفات الخطرة، وتسهيل حركة تنقل المواطنين والمركبات، إلى جانب ضمان انسيابية نقل السلع الأساسية والمواد الغذائية والدوائية الحيوية دون عوائق. ​ولا تقتصر ثمار هذا الإنجاز على الجانب الخدمي البحت، بل تمتد لتنعكس بشكل مباشر على الاقتصاد المعيشي للمواطنين؛ حيث ستسهم هذه النقلة النوعية في خفض تكاليف النقل المرتفعة، واختصار زمن السفر بشكل…","جدير بالذكر أن البرنامج السعودي لتنمية وإعمار اليمن نجح في تحويل طريق ارتبط طويلًا بمشاهد المخاطر والمعاناة، إلى مسار آمن، مستقر، وأكثر انسيابية، مجسداً التزاماً راسخاً ومستداماً لدعم السكان في اليمن وتثبيت ركائز التنمية والاستقرار في مختلف المحافظات. #هيجة_العبد #طريق_هيجة_العبد #تنمية_اليمن #البرنامج السعودي لتنمية وإعمار اليمن"]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/sjc0vvo','https://sabq.org/article/sjc0vvo','','https://sabq.org/article/sjc0vvo','صحيفة سبق','السعودية','2026-08-12T13:38:00.000Z','2026-08-12T16:38:00.000Z','2026-08-13T08:50:19.751Z','https://media.sabq.org/news/2026/08/827f26d7-130c-4ac7-9079-b11faa9434f4/w942.webp','/api/media/3abe63df-0c4c-4f85-8af2-601ce080f394','/api/media/3abe63df-0c4c-4f85-8af2-601ce080f394?variant=thumbnail','من «طريق الموت» إلى شريان حياة.. السعودية تعيد نبض الحياة لـ 5 ملايين يمني في «هيجة العبد»',942,540,'valid','published','archived','valid',91,'d56fbf7c7df24428f8c0edc8607ac25505b6e6e2f214129bf0abdf66c2df5859','93cf7c0bba5d324ef439047b86bfaff3803a1752cdcbe8e02dcf21798d9bd521','محدّث','2026-08-13T08:50:19.751Z','2026-10-07T21:00:43.932Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الاقتصاد والأسواق","اليمن"]','["السفر والسياحة","الاقتصاد والأسواق"]','classified','','[{"category":"المناطق","score":4},{"category":"أخبار السعودية","score":3},{"category":"الاقتصاد","score":3}]','Active','2026-10-07T21:00:43.932Z',200,74,0,'source_article_available','',NULL,NULL,'body:e57c42c8a2e6728b48ccfc1f7e86fd3cb30a6135b05b9ca51a760c63652ecb1b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ce8db32e-5cbb-4685-aece-140d638ee333','news-ce8db32e-5cbb-4685-aece-140d638ee333','ضغوط 8 أشهر في البحر تهز طاقم «أبراهام لينكولن».. محاولات قفز من الحاملة','ضغوط 8 اشهر في البحر تهز طاقم ابراهام لينكولن محاولات قفز من الحامله','كشفت صحيفة «ميليتاري تايمز» الأمريكية المتخصصة في الشؤون العسكرية أن عدداً من بحارة حاملة الطائرات «يو إس إس أبراهام لينكولن» حاولوا الانتحار عبر القفز من السفينة، وذلك في ظل ضغوط نفسية متصاعدة جراء إطالة فترة الانتشار.','["وتضم حاملة الطائرات نحو 5000 بحار وجندي من مشاة البحرية، يرابطون في عرض البحر منذ 21 نوفمبر 2024، أي ما يقارب 8 أشهر متواصلة.","وكان مقرراً في الأصل أن تنتهي مهمتهم في مايو الماضي، غير أنها مُدِّدت إلى أجل غير مسمى على خلفية التوترات المتصاعدة مع إيران.","وتتمركز «يو إس إس أبراهام لينكولن» في منطقة الشرق الأوسط منذ يناير 2025، ضمن العمليات العسكرية الأمريكية في المنطقة.","وأفادت الصحيفة بأن البحرية الأمريكية أكدت أن قيادة السفينة تُراقب الحالة النفسية لأفرادها بصفة مستمرة، وتوفر لهم إمكانية الوصول إلى أخصائيين نفسيين ورجال دين ومسعفين."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/rhvg0af','https://sabq.org/article/rhvg0af','','https://sabq.org/article/rhvg0af','صحيفة سبق','السعودية','2026-08-12T13:46:00.000Z','2026-08-12T16:46:00.000Z','2026-08-13T08:50:19.845Z','https://media.sabq.org/news/2026/08/42bc0da9-84da-4a89-8662-33e14d1e5640/w846.webp','/api/media/ce8db32e-5cbb-4685-aece-140d638ee333','/api/media/ce8db32e-5cbb-4685-aece-140d638ee333?variant=thumbnail','ضغوط 8 أشهر في البحر تهز طاقم «أبراهام لينكولن».. محاولات قفز من الحاملة',846,551,'valid','published','archived','valid',41,'da9d5806d63dd48bcde2d198a8eabb3a7a0d2ffce6b1276564a4fcd9f7cdae33','cf9230987726dd7419b09b0ce32d0489656ce5bc68f557b3c2bdb58423542f46','محدّث','2026-08-13T08:50:19.845Z','2026-10-07T20:59:58.910Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["إيران","الشرق الأوسط"]','["الشرق الأوسط"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:59:58.910Z',200,80,0,'source_article_available','',NULL,NULL,'body:fbab4e1c55446e1a3832377f58bd10f73f99c6ca65e15d11e863c46c81a8819d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d32354ea-6cfd-4006-b94f-826c8f289ec2','news-d32354ea-6cfd-4006-b94f-826c8f289ec2','"محمود عباس" من أنقرة: لن نقبل التهجير وإسرائيل تحتجز 6.5 مليارات دولار من أموالنا','محمود عباس من انقره لن نقبل التهجير واسرائيل تحتجز 6 5 مليارات دولار من اموالنا','أكد الرئيس الفلسطيني محمود عباس، الأربعاء، أن الشعب الفلسطيني باقٍ على أرضه ولن يقبل بالتهجير ولا بسرقة الأرض الفلسطينية المحتلة، وذلك خلال مؤتمر صحفي مشترك مع الرئيس التركي رجب طيب أردوغان في العاصمة أنقرة.','["وشدد عباس على أن «قطاع غزة جزء لا يتجزأ من الدولة الفلسطينية»، مؤكداً أن «أي ترتيبات متعلقة بقطاع غزة يجب أن تتم من خلال الدولة الفلسطينية».","وكشف الرئيس الفلسطيني أن «إسرائيل تحتجز 6.5 مليارات دولار من الأموال الفلسطينية المستحقة»، مشيراً إلى أنه ناقش مع أردوغان «التصعيد الإسرائيلي الخطير في الضفة الغربية والقدس».","وأعرب عباس عن أمله في أن يكون «اتفاق الدفاع المشترك بين تركيا والسعودية وباكستان بداية لاتفاق أشمل يسهم في تعزيز الأمن والاستقرار»، مشدداً على «أهمية وحدة الصف الفلسطيني وتعزيز المشاركة الوطنية الشاملة».","وأثنى عباس على الدور التركي، مؤكداً أن «تركيا تؤدي دوراً مهماً في علاج الفلسطينيين وتوفير فرص التعليم لطلبتنا في جامعاتها»."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/mb3ajve','https://sabq.org/article/mb3ajve','','https://sabq.org/article/mb3ajve','صحيفة سبق','السعودية','2026-08-12T13:36:00.000Z','2026-08-12T16:36:00.000Z','2026-08-13T08:50:21.031Z','https://media.sabq.org/news/2026/08/57060e87-5f56-4ac7-a143-8d6793be712f/w846.webp','/api/media/d32354ea-6cfd-4006-b94f-826c8f289ec2','/api/media/d32354ea-6cfd-4006-b94f-826c8f289ec2?variant=thumbnail','"محمود عباس" من أنقرة: لن نقبل التهجير وإسرائيل تحتجز 6.5 مليارات دولار من أموالنا',846,551,'valid','published','archived','valid',40,'0a899018d59a1e3dd74b14c325c899c40b16bc487d39c4df65936bbbf4813f20','471687b311bad6c9d868a10d6c51de6ef579d04215ae0571d51ecc227a48db54','محدّث','2026-08-13T08:50:21.031Z','2026-10-07T21:00:37.340Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","التعليم والتدريب","غزة","تركيا","فلسطين"]','["الصحة العامة","التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"الصحة","score":1.5},{"category":"التعليم","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T21:00:37.340Z',200,74,0,'source_article_available','',NULL,NULL,'body:81bf41f52e3405f6c4aaf48052f1f6111ec83f6a33d4b6136283faaee930cc2b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6eaf8440-dcbe-4c4c-91e0-746700342b8d','news-6eaf8440-dcbe-4c4c-91e0-746700342b8d','"أولي واتكينز" على رادار الهلال  في صفقة إنجليزية قوية .. خلال فترة الميركاتو الصيفي ','اولي واتكينز علي رادار الهلال في صفقه انجليزيه قويه خلال فتره الميركاتو الصيفي','كشفت مصادر إعلامية أن نادي الهلال السعودي دخل دائرة المهتمين بالتعاقد مع المهاجم الإنجليزي أولي واتكينز، نجم أستون فيلا، لتعزيز خطه الهجومي خلال فترة الانتقالات الصيفية الحالية.','["ويبلغ واتكينز من العمر 30 عاماً، ويجيد اللعب في مركز رأس الحربة إلى جانب قدرته على شغل مركزي الجناحين، فيما تُقدَّر قيمته السوقية بنحو 25 مليون يورو وفق موقع «ترانسفير ماركت»، ويمتد عقده مع أستون فيلا حتى صيف 2028.","وبدأ المهاجم الإنجليزي مسيرته الاحترافية مع إكستر سيتي، قبل أن ينتقل إلى برينتفورد عام 2017، حيث تألق بشكل لافت وأثار اهتمام الأندية الكبرى، ليحسم أستون فيلا التعاقد معه في سبتمبر 2020 مقابل نحو 34 مليون يورو.","ومنذ انضمامه إلى الفريق الأرجواني، أصبح واتكينز أحد أبرز العناصر الهجومية في صفوفه، كما فرض نفسه على حسابات المنتخب الإنجليزي الذي خاض معه 24 مباراة دولية سجل خلالها 7 أهداف، من بينها هدفه الشهير أمام هولندا في نصف نهائي بطولة أمم أوروبا 2024."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/35as52o','https://sabq.org/article/35as52o','','https://sabq.org/article/35as52o','صحيفة سبق','السعودية','2026-08-12T13:26:00.000Z','2026-08-12T16:26:00.000Z','2026-08-13T08:50:21.071Z','https://media.sabq.org/news/2026/08/95ac02cf-d1ca-46d4-909d-d02b2f282aeb/w1199.webp','/api/media/6eaf8440-dcbe-4c4c-91e0-746700342b8d','/api/media/6eaf8440-dcbe-4c4c-91e0-746700342b8d?variant=thumbnail','"أولي واتكينز" على رادار الهلال  في صفقة إنجليزية قوية .. خلال فترة الميركاتو الصيفي ',1199,800,'valid','published','archived','valid',51,'a3b7e91a993d249a1d5a6fe5bbda737ae4a71109cb6a029f92e4f058ef17a115','ac086628a7cc4351db15b6bbbc39b2d3b17dc73576643a3e51dce3c5be8d3849','محدّث','2026-08-13T08:50:21.071Z','2026-10-07T21:00:02.538Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","أوروبا"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"السيارات","score":2},{"category":"العالم","score":1.5}]','Active','2026-10-07T21:00:02.538Z',200,75,0,'source_article_available','',NULL,NULL,'body:59fba63a0d4f2b5f286223e38d74c46fdc02126d4c67b9ae2995c6494ed1797d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4646f160-5615-4fdd-b850-fa9a846a2e86','news-4646f160-5615-4fdd-b850-fa9a846a2e86','حاملة "بوش" تدعم الحصار الأمريكي على إيران.. 59 سفينة غيّرت مسارها و3 عُطّلت','حامله بوش تدعم الحصار الامريكي علي ايران 59 سفينه غيرت مسارها و3 عطلت','كثّفت القوات البحرية الأمريكية عملياتها البحرية في إطار ما وصفته بـ«الحصار الفولاذي» المفروض على إيران، مستعينةً بحاملة الطائرات يو إس إس جورج إتش.','["بوش (CVN 77) التي تبحر في المياه الإقليمية لدعم هذه العمليات.","وأفادت المعطيات المتاحة بأن القوات الأمريكية أعادت تغيير مسار 59 سفينة تجارية، وعطّلت 3 سفن، واعتلت سفينتين للتحقق من امتثالها الكامل لشروط الحصار، وذلك حتى الثاني عشر من أغسطس.","وتُعدّ حاملة الطائرات CVN 77 من أبرز الأصول البحرية الأمريكية المنتشرة في المنطقة، إذ تضم على متنها طائرات مقاتلة من طراز F/A-18 قادرة على الإقلاع والعمليات الجوية لدعم المهام البحرية.","ولم تصدر حتى الآن تصريحات رسمية من الجانب الإيراني بشأن هذه العمليات، فيما تترقب الأوساط الدبلوماسية تداعيات هذا التصعيد على مسار المفاوضات النووية."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/pxn6ro1','https://sabq.org/article/pxn6ro1','','https://sabq.org/article/pxn6ro1','صحيفة سبق','السعودية','2026-08-12T13:30:00.000Z','2026-08-12T16:30:00.000Z','2026-08-13T08:50:21.322Z','https://media.sabq.org/news/2026/08/480d83d2-6518-400b-82f5-3c29b3053bab/w1200.webp','/api/media/4646f160-5615-4fdd-b850-fa9a846a2e86','/api/media/4646f160-5615-4fdd-b850-fa9a846a2e86?variant=thumbnail','حاملة "بوش" تدعم الحصار الأمريكي على إيران.. 59 سفينة غيّرت مسارها و3 عُطّلت',1200,675,'valid','published','archived','valid',40,'2c50bc46058c191625178c67f33fef985d00b1d5f3426be9cd3c583534afa19c','8ea35f0d42570a2d0521f03fd372c42c3388e7018dc7e7c0e40f56848190090c','محدّث','2026-08-13T08:50:21.322Z','2026-10-07T21:00:41.910Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السياسة والعلاقات الدولية","إيران"]','["السياسة والعلاقات الدولية"]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T21:00:41.910Z',200,72,0,'source_article_available','',NULL,NULL,'body:aadbb62f1c406dc9397885f327f15b744f08a271c97154f09d59e0c34d313018','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('037c9095-2d12-45fa-b030-57d88a3e4e4d','news-037c9095-2d12-45fa-b030-57d88a3e4e4d','4 دول بينها بريطانيا وإيطاليا مرشحة للتحقق من نزع سلاح حزب الله.. وتفتيش القرى اللبنانية مطروح','4 دول بينها بريطانيا وايطاليا مرشحه للتحقق من نزع سلاح حزب الله وتفتيش القري اللبنانيه مطروح','كشف أشخاص مطلعون على الأمر أن لبنان وإسرائيل اتفقا على قائمة قصيرة تضم أربع دول مرشحة للمشاركة في آلية مقترحة قد تتضمن نشر قوات أجنبية في لبنان للتحقق من نزع سلاح حزب الله، وهي: بريطانيا وإيطاليا وسويسرا وإندونيسيا.','["وجرى الاتفاق على هذه القائمة خلال محادثات عُقدت في روما الأسبوع الماضي برعاية أمريكية، في أحدث جولة من المفاوضات بين البلدين حول تنفيذ اتفاق يونيو الماضي، الذي يربط الانسحاب الإسرائيلي التدريجي من لبنان بنزع سلاح حزب الله.","وأوضحت ثلاثة مصادر أن الدول المرشحة يمكن أن تُسهم في تحديد نطاق الآلية، أو توفير أفراد للإشراف على تنفيذها، أو المشاركة في عمليات المراقبة والتفتيش المرتبطة بالتحقق من نزع السلاح.","وأكد مسؤول لبناني لوكالة «رويترز» أن إسرائيل ولبنان اتفقا على قائمة بالدول المرشحة، غير أنه امتنع عن الإفصاح عن أسمائها، مشيراً إلى أن الولايات المتحدة هي التي ستتخذ القرار النهائي بشأن المشاركين. **إسرائيل تطالب بتفتيش المنازل** يحتل الجيش الإسرائيلي منطقة أمنية تمتد نحو 10 كيلومترات داخل جنوب لبنان، وأعلن رفضه الانسحاب من جانب واحد قبل التحقق من نزع سلاح حزب الله.","وكشف مصدران أن الآلية المقترحة تنص على تفتيش القرى في جنوب لبنان والتحقق من خلوها من الأسلحة، مع إصرار إسرائيل على أن تشمل عمليات التفتيش المنازل الخاصة."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/h2wopzi','https://sabq.org/article/h2wopzi','','https://sabq.org/article/h2wopzi','صحيفة سبق','السعودية','2026-08-12T13:20:00.000Z','2026-08-12T16:20:00.000Z','2026-08-13T08:50:22.566Z','https://media.sabq.org/news/2026/08/986763cb-ae21-4d42-909a-2b7a6a91da75/w640.webp','/api/media/037c9095-2d12-45fa-b030-57d88a3e4e4d','/api/media/037c9095-2d12-45fa-b030-57d88a3e4e4d?variant=thumbnail','4 دول بينها بريطانيا وإيطاليا مرشحة للتحقق من نزع سلاح حزب الله.. وتفتيش القرى اللبنانية مطروح',640,427,'valid','published','archived','valid',53,'b636cc4683014d3598118aab7ae24436158973455142f1e805f7f96d91bb0e34','50e7d2ccfebf902b26f0afe64a50a3f46518276ed9e3a1c578b2d9dc1cec1a0e','محدّث','2026-08-13T08:50:22.566Z','2026-10-07T21:00:45.556Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السياسة والعلاقات الدولية","لبنان","الولايات المتحدة"]','["السياسة والعلاقات الدولية","الولايات المتحدة"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"المجتمع","score":1.5},{"category":"العالم","score":1.5}]','Active','2026-10-07T21:00:45.556Z',200,74,0,'source_article_available','',NULL,NULL,'body:3bf813cc533c14bceb40f2e89e6180e1b7b7475df823de74165bafc4b9f07f9a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('72ed7d88-d2af-47a4-b06a-838866ed03fe','news-72ed7d88-d2af-47a4-b06a-838866ed03fe','النفط يتراجع رغم توترات الشرق الأوسط مع خفض توقعات الطلب العالمي','النفط يتراجع رغم توترات الشرق الاوسط مع خفض توقعات الطلب العالمي','تراجعت أسعار النفط الأربعاء في تداولات متقلبة، بعد أن سجّلت في وقت سابق ارتفاعاً بلغ نحو دولار للبرميل، قبل أن تتحول إلى الانخفاض تحت وطأة توقعات الطلب العالمي المنخفضة، رغم استمرار الهجمات على السفن في الشرق الأوسط وجمود محادثات إنهاء الحرب.','["وانخفضت العقود الآجلة لخام برنت 49 سنتاً أو 0.55% لتبلغ 88.42 دولاراً للبرميل بحلول الساعة 13:15 بتوقيت غرينتش، فيما نزل خام غرب تكساس الوسيط الأمريكي 25 سنتاً بما يعادل 0.3% إلى 82.95 دولاراً.","وكشف التقرير الشهري لمنظمة البلدان المصدرة للبترول «أوبك» أن المنظمة خفّضت توقعاتها لنمو الطلب العالمي على الخام لعام 2026 إلى 580 ألف برميل يومياً.","وفي السياق ذاته، خفّضت وكالة الطاقة الدولية توقعاتها للطلب لعام 2026، متوقعةً انكماشاً قدره 1.6 مليون برميل يومياً خلال العام الجاري.","غير أن الوكالة ومقرها باريس توقّعت في المقابل انخفاضاً في العرض قدره 4.3 مليون برميل يومياً خلال العام الجاري، وعجزاً إجمالياً في 2026 يبلغ نحو 1.27 مليون برميل يومياً."]','الطاقة والصناعة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/83brbzd','https://sabq.org/article/83brbzd','','https://sabq.org/article/83brbzd','صحيفة سبق','السعودية','2026-08-12T13:08:00.000Z','2026-08-12T16:08:00.000Z','2026-08-13T08:50:22.606Z','https://media.sabq.org/news/2026/08/9ea992b9-5a32-48f0-96ab-81f4182b315c/w640.webp','/api/media/72ed7d88-d2af-47a4-b06a-838866ed03fe','/api/media/72ed7d88-d2af-47a4-b06a-838866ed03fe?variant=thumbnail','النفط يتراجع رغم توترات الشرق الأوسط مع خفض توقعات الطلب العالمي',640,427,'valid','published','archived','valid',57,'b4f7521a4931be6df321646093d91420320e68cb835f4775ea6dffaf778e0de9','184fcf690e2906f09dc30760d985d954fca25acc7ce6b9b59b9ff75806eb79d3','محدّث','2026-08-13T08:50:22.606Z','2026-10-07T21:00:44.534Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الشرق الأوسط"]','["الطاقة والنفط","الشرق الأوسط"]','manual_approved','below_category_threshold','[{"category":"العالم","score":4.5},{"category":"التقنية","score":2},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T21:00:44.534Z',200,74,0,'source_article_available','',NULL,NULL,'body:dda09ed2615a0110e0159a9fdef75a0a4bcf5eeb63d611b7de7813fad4b05e13','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5cd58724-2886-4e43-8f98-762cbfd8a6b2','news-5cd58724-2886-4e43-8f98-762cbfd8a6b2','بعد 40 عاماً من الفراق.. تحليل الحمض النووي يكشف أن صديقتين هنديتين شقيقتان','بعد 40 عاما من الفراق تحليل الحمض النووي يكشف ان صديقتين هنديتين شقيقتان','أودعت مينا ومينال وهما رضيعتان في دار للأيتام بالهند، ونشأت كل منهما لدى عائلة هولندية بالتبني، على مسافة قريبة من الأخرى.','["وبعد مرور أكثر من 40 عاماً، أظهر تحليل الحمض النووي (DNA) أن الصديقتين منذ الطفولة هما شقيقتان بيولوجيتان.","خلال طفولتهما، لم تكن أي منهما تعلم بوجود شقيقة لها.","ثم في عام 1996، التقتا في تجمع للأطفال المتبنين وهما تعيشان على بعد 160 كيلومتراً فحسب، وشعرتا برابطة قوية غير عادية.","واندهش أصدقاؤهما من الشبه الكبير بينهما، فتبادلتا عناوينهما وراحتا تتراسلان، بل كانتا تناديان بعضهما «بأختي» على سبيل المزاح، قبل أن ينقطع التواصل بينهما نحو 15 عاماً."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/dx93tvh','https://sabq.org/article/dx93tvh','','https://sabq.org/article/dx93tvh','صحيفة سبق','السعودية','2026-08-12T13:14:00.000Z','2026-08-12T16:14:00.000Z','2026-08-13T08:50:22.631Z','https://media.sabq.org/news/2026/08/461355b7-491f-4135-98c1-22d8cefad3b4/w960.webp','/api/media/5cd58724-2886-4e43-8f98-762cbfd8a6b2','/api/media/5cd58724-2886-4e43-8f98-762cbfd8a6b2?variant=thumbnail','بعد 40 عاماً من الفراق.. تحليل الحمض النووي يكشف أن صديقتين هنديتين شقيقتان',960,641,'valid','published','archived','valid',40,'66549e6574159e774c72bd9a2844945f13514019449147515c7e4f51389ab3b4','a006e84ad02f149c66ff78a0ed38bc78e842fdd74411b1a6dffa74681a7612e3','محدّث','2026-08-13T08:50:22.631Z','2026-10-07T21:00:38.569Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T21:00:38.569Z',200,73,0,'source_article_available','',NULL,NULL,'body:60214823a413acb2e949a2f8c548f65629e0d871b5765378534040bca5a4f61b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('99c19a15-2289-4446-91f1-55aa4a3f87fb','news-99c19a15-2289-4446-91f1-55aa4a3f87fb','مصر تكشف حقيقة استهداف «الحوثيين» سفينة تابعة لها قبالة السواحل اليمنية','مصر تكشف حقيقه استهداف الحوثيين سفينه تابعه لها قباله السواحل اليمنيه','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية أكدت وزارة النقل المصرية، أن «ما تردد بشأن سفينه تدعى (TIHAMA)، التي استهدفتها جماعة “الحوثيين” في اليمن غير صحيح»، موضحة أن «السفينة ليست مسجلة في غرف الملاحة المصرية وغير صادر لها ترخيص مزاولة أعمال وكالة بحرية عن طريق قطاع النقل البحري و','["أكدت وزارة النقل المصرية، أن «ما تردد بشأن سفينه تدعى (TIHAMA)، التي استهدفتها جماعة “الحوثيين” في اليمن غير صحيح»، موضحة أن «السفينة ليست مسجلة في غرف الملاحة المصرية وغير صادر لها ترخيص مزاولة أعمال وكالة بحرية عن طريق قطاع النقل البحري واللوجيستيات المصري، ولا يقع عنوان الشركة المشغلة لها في مدينة الإسكندرية ب مصر ».","وبحسب بيان أصدرته الوزارة، اليوم الخميس، فإن «السفينة تحمل علم تنزانيا، وأن مالكها يمني الجنسية، والشركة المشغلة لها هي Blue Sea for Managemet Marine، وتدار عن طريق فرعها في دولة الإمارات العربية المتحدة ب دبي ».","وأشارت «النقل» إلى أن «السفينة (TIHAMA)، التي كانت أمام سواحل اليمن حال استهدافها، لم يسبق لها الدخول إلى الموانئ المصرية من قبل، ولم تكن في طريقها إلى مصر، ولا تحمل أية بضائع تخص مصريين»، مؤكدة حرصها الدائم على متابعة كافة الأحداث المتعلقة بالمياه الإقليمية المصرية وأمن وسلامة البحرين المتوسط والأحمر، وأيضا سلامة وأمن الشركات والسفن والبحارة المصريين."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/whm3ukiq1','https://ajel.sa/international/whm3ukiq1','https://ajel.sa/international/whm3ukiq1','https://ajel.sa/international/whm3ukiq1','فريق التحرير','السعودية','2026-08-13T02:29:00.000Z','Wed, 07 Oct 2026 20:59:51 GMT','2026-08-13T10:51:38.897Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/1000195916-crop-5L3ApzgY.jpg','/api/media/99c19a15-2289-4446-91f1-55aa4a3f87fb','/api/media/99c19a15-2289-4446-91f1-55aa4a3f87fb?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',40,'880d8afcb8cdf5edf062a4c5a06e53298d451f61319f7b25b9d06b53b17562fc','cf9f1ea54269ff204481b1d088d85cf42f23b0522229aa35e92a1304f72ccbe4',NULL,'2026-08-13T10:51:38.897Z','2026-10-07T20:59:53.124Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة النقل المصرية أن ما","اليمن"]','["وزارة النقل المصرية أن ما"]','manual_approved','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Updated','2026-10-07T20:59:53.124Z',200,76,0,'source_content_changed','',NULL,NULL,'body:8fee08b0491575ac3030648abe069a8dc128b56df3b20603e13184772c605554','Wed, 07 Oct 2026 20:59:51 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bfff2ff6-0810-4591-9459-527e5e06985f','news-bfff2ff6-0810-4591-9459-527e5e06985f','اقتصادي / "إنفاذ" يشرف على 95 مزادًا عقاريًا لبيع 1043 أصلًا عقاريًا في مختلف مناطق المملكة خلال النصف الثاني من أغسطس 2026','اقتصادي انفاذ يشرف علي 95 مزادا عقاريا لبيع 1043 اصلا عقاريا في مختلف مناطق المملكه خلال النصف الثاني من اغسطس 2026','الرياض 30 صفر 1448 هـ الموافق 13 أغسطس 2026 م واس أعلن مركز الإسناد والتصفية "إنفاذ"، إقامة 95 مزادًا عقاريًا في مختلف مناطق المملكة، تتضمن طرح 1043 أصلًا عقاريًا متنوعًا، وذلك خلال الفترة من 15 إلى 31 أغسطس 2026م.','["وتتصدر منطقة الرياض عدد المزادات بـ 31 مزادًا، تشمل 299 أصلًا عقاريًا، فيما تأتي منطقة مكة المكرمة في المرتبة الثانية بـ 23 مزادًا، تتضمن 277 أصلًا عقاريًا، تليها المنطقة الشرقية بـ 9 مزادات، تشمل 86 أصلًا عقاريًا، ثم منطقة القصيم بـ 8 مزادات، تتضمن 120 أصلًا عقاريًا، تليها منطقة عسير بـ 5 مزادات، تشمل 55 أصلًا عقاريًا.","كما تُقام 3 مزادات في كل من المدينة المنورة وتبوك وحائل، ومزادان في كل من الجوف، وجازان، ونجران، والحدود الشمالية، والباحة.","ويمكن الاطلاع على التفاصيل عبر الموقع: https://infath.gov.sa."]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2652866?type=news&uuid=N2652866','https://spa.gov.sa/ar/N2652866?type=news&uuid=N2652866','N2652866','N2652866','','السعودية','2026-08-13T03:19:00.000Z','2026-06-22T06:52:00.000Z','2026-08-15T21:39:00.922Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10600501.png','/api/media/bfff2ff6-0810-4591-9459-527e5e06985f','/api/media/bfff2ff6-0810-4591-9459-527e5e06985f?variant=thumbnail','اقتصادي / "إنفاذ" يشرف على 95 مزادًا عقاريًا لبيع 1043 أصلًا عقاريًا في مختلف مناطق المملكة خلال النصف الثاني من أغسطس 2026',801,801,'valid','published','archived','valid',99,'2487bc2ff9f7bda7925f1743956f526b04f3ccc200ea53a100cd7bb13ff463bc','9d17930173479cef543e6c76a89df00576464b6a25d4302c67596f71c821ad0f','محدّث','2026-08-13T10:52:01.592Z','2026-10-07T20:59:45.835Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","مكة","عسير","تبوك","جازان","نجران","الجوف","الرياض"]','["الاقتصاد والأسواق","المدينة المنورة"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"الاقتصاد","score":3},{"category":"السياسة","score":0}]','Active','2026-10-07T20:59:45.835Z',200,77,0,'source_article_available','',NULL,NULL,'body:ccf0729018b2303d0e7757c29b0002cf36a380f2e8331372f58539f7ed4dc796','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('09c3acd9-0790-4bf7-8dd2-f6d0128c61c2','news-09c3acd9-0790-4bf7-8dd2-f6d0128c61c2','اقتصادي / وزارة البلديات والإسكان: 47 مشروعًا للمسح الجوي خلال 56 عامًا توفر قاعدة بيانات جيومكانية تغطي أكثر من 771 ألف كم²','اقتصادي وزاره البلديات والاسكان 47 مشروعا للمسح الجوي خلال 56 عاما توفر قاعده بيانات جيومكانيه تغطي اكثر من 771 الف كم2','الرياض 30 صفر 1448 هـ الموافق 13 أغسطس 2026 م واس كشفت وزارة البلديات والإسكان، ممثلةً بوكالة التخطيط الحضري والأراضي، عن تنفيذ (47) مشروعًا للمسح الجوي وإنتاج الخرائط منذ عام 1970م، أسهمت في بناء قاعدة بيانات جيومكانية تغطي أكثر من (771,172) كيلومترًا مربعًا؛ مما دعم أعمال التخطيط العمراني، ووفّر صورًا جوية تاريخية وحديثة للنطاق العمراني في مختلف مناطق المم','["وتوثق هذه البيانات مسيرة ممتدة على مدى (56) عامًا، شهدت تطورًا متواصلًا في أعمال المسح الجوي، بدءًا من الصور التناظرية الفيلمية إلى التصوير الرقمي عالي الدقة، وذلك في إطار تطوير منظومة المعلومات الجيومكانية التي تعتمد عليها الجهات الحكومية في التخطيط وإدارة التنمية الحضرية.","وأوضحت الوزارة أن مشروعات المسح الجوي نُفذت على مراحل متتابعة شملت مختلف مناطق المملكة، وأسهمت في تكوين أرشيف وطني متكامل للصور الجوية، وتحديث البيانات المكانية، بما يرفع كفاءة التخطيط العمراني، ويعزز دقة الدراسات والمخططات، ويوفر مرجعًا مكانيًا موثوقًا لمشروعات التنمية.","وبيّنت البيانات أن منظومة المسح الجوي شهدت انتقالًا تدريجيًا في استخدام التقنيات؛ بدءًا من التصوير بالأبيض والأسود، مرورًا بالتصوير الملون، ثم التصوير الرقمي عالي الدقة، وصولًا إلى إنتاج الخرائط العقارية الرقمية، بما يعكس التطور الذي شهدته أعمال المساحة ونظم المعلومات في المملكة خلال العقود الماضية.","وفي محطة مهمة ضمن مسيرة تطوير الجودة، حصلت الوزارة على شهادة الآيزو لنظام إدارة الجودة (ISO 9001:2008) بتاريخ 19 أكتوبر 2010، وشمل نطاق الشهادة أنشطة إنتاج وتوفير المعلومات المكانية، بما في ذلك المسح الجوي، والمسح الأرضي، والخرائط المصورة، والخرائط الطبوغرافية، والمسح العقاري، والخرائط العقارية، والاستشعار عن بُعد، وأنظمة معلومات الأراضي، ونظم المعلومات الجغرافية، بما يعكس التزام الوزارة بتطبيق معايير الجودة…"]','العقارات','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2652903?type=news&uuid=N2652903','https://spa.gov.sa/ar/N2652903?type=news&uuid=N2652903','N2652903','N2652903','','السعودية','2026-08-13T04:53:00.000Z',NULL,'2026-08-13T10:52:02.092Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10600968.jpg','/api/media/09c3acd9-0790-4bf7-8dd2-f6d0128c61c2','/api/media/09c3acd9-0790-4bf7-8dd2-f6d0128c61c2?variant=thumbnail','اقتصادي / وزارة البلديات والإسكان: 47 مشروعًا للمسح الجوي خلال 56 عامًا توفر قاعدة بيانات جيومكانية تغطي أكثر من 771 ألف كم²',1600,2527,'valid','published','archived','valid',51,'838879a2170cff981713d48f621df91b0b2cfa4198bec3f1851e1819baa7a7a0','6a722b04ce82ec7e15e8b2fbad36b5b2b8ca44301c98bf99d8590bfe006a8375',NULL,'2026-08-13T10:52:02.092Z','2026-10-07T21:00:01.903Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البلديات والإسكان","الثقافة والفنون","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["وزارة البلديات والإسكان","الثقافة والفنون","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":4.5},{"category":"التقنية","score":3},{"category":"أخبار السعودية","score":1.5}]','Active','2026-10-07T21:00:01.903Z',200,81,0,'source_article_available','',NULL,NULL,'body:bcc776d17f0ef6b273450694402c98bcb5e340ee2a7c1c8b73acfd782da5cd20','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f0200a74-d3d8-41db-9527-5794ef645214','news-f0200a74-d3d8-41db-9527-5794ef645214','منظمة الصحة العالمية: تفشّي إيبولا يتجه ليصبح الأكثر فتكاً على الإطلاق','منظمه الصحه العالميه تفشي ايبولا يتجه ليصبح الاكثر فتكا علي الاطلاق','قال المدير العام لمنظمة الصحة العالمية، تيدروس أدهانوم غيبريسوس، إن التفشي الحالي لفيروس إيبولا في جمهورية الكونغو الديمقراطية يتجه ليتجاوز أعداد الوفيات المسجلة في أسوأ تفشٍ للمرض على الإطلاق.','["وأضاف في تصريح صحفي أن تفشّي المرض هذا العام \"بالوتيرة الحالية\"، قد \"يتجاوز بكثير\" التفشي الذي شهده فيروس إيبولا في منطقة غرب أفريقيا بين عامي 2014 و2016، وأسفر عن وفاة ما لا يقل عن 11 ألف شخص.","وسَجل تفشّي المرض هذا العام، ما لا يقل عن 4300 إصابة، بينما تجاوزت أعداد الوفيات ألفَيْ حالة.","ولم يُعلن رسمياً عن تفشّي الوباء إلا في 15 مايو/أيار الماضي، لكنّ مسؤولين صحيين قالوا هذا الأسبوع إنه من المرجح أن يكون قد بدأ قبل ذلك بثلاثة أشهر على الأقل.","وقالت منظمة الصحة العالمية، الأربعاء، إنها تأمل في وقف انتشار المرض خلال ثلاثة أشهر، لكنها حذّرت من أن ذلك يعني السيطرة على انتقال الفيروس، وليس القضاء على التفشي بشكل كامل."]','الصحة','العالم','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://www.bbc.com/arabic/articles/c5y499enzqeo','https://www.bbc.com/arabic/articles/c5y499enzqeo','CBMiXEFVX3lxTFBDSHNRX2Y4dG16c0tfLVpPUC1qaS1SUEJPdjFFYUlBU2V0WXlLVk04MU9ieXQzMlEwbGFBMVJ4Q1ZOczhYb1JuZVpZT0JLanQ5Wk5TWERKVFdJMjZC0gFiQVVfeXFMTUxpVGdiUWtCR2lIc3czeHl0b2RHLVdkamlVTG1PbzFxVEVpa1JtTldKeTlIWnhuYUdrcFlQdXhPdTdCcnZNMXpKcjJJMU9fMng2X0NyQ1dpd0VBUWU0bE9lZlE','CBMiXEFVX3lxTFBDSHNRX2Y4dG16c0tfLVpPUC1qaS1SUEJPdjFFYUlBU2V0WXlLVk04MU9ieXQzMlEwbGFBMVJ4Q1ZOczhYb1JuZVpZT0JLanQ5Wk5TWERKVFdJMjZC0gFiQVVfeXFMTUxpVGdiUWtCR2lIc3czeHl0b2RHLVdkamlVTG1PbzFxVEVpa1JtTldKeTlIWnhuYUdrcFlQdXhPdTdCcnZNMXpKcjJJMU9fMng2X0NyQ1dpd0VBUWU0bE9lZlE','تابي ويلسون','السعودية','2026-08-13T02:14:00.000Z','2026-08-13T05:14:00.000Z','2026-08-13T10:56:26.295Z','https://ichef.bbci.co.uk/news/1200/branded_arabic/45e0/live/2fd6c2d0-96a5-11f1-b2ab-0dd01740f9f6.jpg','/api/media/f0200a74-d3d8-41db-9527-5794ef645214','/api/media/f0200a74-d3d8-41db-9527-5794ef645214?variant=thumbnail','منظمة الصحة العالمية: تفشّي إيبولا يتجه ليصبح الأكثر فتكاً على الإطلاق',1024,576,'valid','published','archived','valid',100,'0ec6d10878f2d83f1a39d266c32ebcef58b80f47c4a9d2b5f7ea5dec3af1824f','8ad065d35b4b3109e7783c1011a0d3d53078e47db345181f7e83a791dd4f7c3d',NULL,'2026-08-13T10:56:26.295Z','2026-10-07T20:59:49.178Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["العالم","الصحة العامة","السفر والسياحة"]','["الصحة العامة","السفر والسياحة"]','manual_approved','','[]','Active','2026-10-07T20:59:49.178Z',200,80,0,'source_article_available','',NULL,NULL,'body:da8091a12057428a29b8408770c1a0b1b645bb9e204920dc16a7efec6ffb2ca7','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d41466b1-812d-45cb-8cc9-6c35691c0127','news-d41466b1-812d-45cb-8cc9-6c35691c0127','علامات سرطان الدم قد تظهر في الحمض النووي قبل تشخيصه بسنوات','علامات سرطان الدم قد تظهر في الحمض النووي قبل تشخيصه بسنوات','كشفت دراسة علمية حديثة عن إمكانية ظهور مؤشرات وراثية على تطور بعض سرطانات الدم قبل سنوات من اكتشاف التغيرات في تحاليل الدم المعتادة.','["وبحسب شبكة «فوكس نيوز» الأميركية؛ فقد تابعت الدراسة 30 مريضاً مصابين بالأورام التكاثرية النخاعية، وهي مجموعة من أمراض الدم المزمنة والنادرة، التي ينتج فيها نخاع العظم أعداداً زائدة من خلايا الدم.","راقب الباحثون الحمض النووي في دم المرضى ونخاع عظامهم بحثاً عن تغيرات جينية، ثم فحصوا ما إذا كانت هذه التغيرات مرتبطة بعدد خلايا الدم، أو استقرار المرض، أو تطوره إلى تليف نخاعي أو سرطان الدم الحاد.","وأظهرت النتائج أن المرضى الذين ظلت حالتهم مستقرة غالباً ما حافظوا على أنماط وراثية مستقرة، بينما أظهر المرضى الذين ساءت حالتهم تغيرات في الحمض النووي قبل سنوات من اكتشاف تطور المرض في فحوصات الدم الروتينية، وذلك مع ظهور مجموعات جديدة من الخلايا غير الطبيعية ونموها، وفقاً للدراسة.","وتطور المرض لدى تسعة مشاركين إلى سرطان الدم النخاعي الحاد، لكن الباحثين لاحظوا أن مسار التطور لم يكن متشابهاً لدى الجميع؛ ففي بعض الحالات تراكمت الطفرات الضارة تدريجياً داخل الخلايا، في حين أنه في حالات أخرى بدا أن سرطان الدم ينشأ من مجموعة منفصلة من خلايا الدم غير الطبيعية. وظهرت اختلافات مشابهة لدى المرضى الذين تطور لديهم تليف نخاع العظم."]','الصحة','','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://aawsat.com/%D8%B5%D8%AD%D8%AA%D9%83/5306450-%D8%B9%D9%84%D8%A7%D9%85%D8%A7%D8%AA-%D8%B3%D8%B1%D8%B7%D8%A7%D9%86-%D8%A7%D9%84%D8%AF%D9%85-%D9%82%D8%AF-%D8%AA%D8%B8%D9%87%D8%B1-%D9%81%D9%8A-%D8%A7%D9%84%D8%AD%D9%85%D8%B6-%D8%A7%D9%84%D9%86%D9%88%D9%88%D9%8A-%D9%82%D8%A8%D9%84-%D8%AA%D8%B4%D8%AE%D9%8A%D8%B5%D9%87-%D8%A8%D8%B3%D9%86%D9%88%D8%A7%D8%AA','https://aawsat.com/%D8%B5%D8%AD%D8%AA%D9%83/5306450-%D8%B9%D9%84%D8%A7%D9%85%D8%A7%D8%AA-%D8%B3%D8%B1%D8%B7%D8%A7%D9%86-%D8%A7%D9%84%D8%AF%D9%85-%D9%82%D8%AF-%D8%AA%D8%B8%D9%87%D8%B1-%D9%81%D9%8A-%D8%A7%D9%84%D8%AD%D9%85%D8%B6-%D8%A7%D9%84%D9%86%D9%88%D9%88%D9%8A-%D9%82%D8%A8%D9%84-%D8%AA%D8%B4%D8%AE%D9%8A%D8%B5%D9%87-%D8%A8%D8%B3%D9%86%D9%88%D8%A7%D8%AA','','','«الشرق الأوسط»','السعودية','2026-08-13T03:26:00.000Z','Wed, 07 Oct 2026 20:59:05 GMT','2026-08-13T10:56:29.404Z','https://static.srpcdigital.com/styles/1200x600/public/2026-08/1717203.jpeg.webp?VersionId=E1cWtdG0tvBFixyCk8GhbfZ_uIOggShY','/api/media/d41466b1-812d-45cb-8cc9-6c35691c0127','/api/media/d41466b1-812d-45cb-8cc9-6c35691c0127?variant=thumbnail','علامات سرطان الدم قد تظهر في الحمض النووي قبل تشخيصه بسنوات',838,468,'valid','published','archived','valid',95,'99578115ddf7ca8e4835a48aaea2d8c8f799c8ee4981aad535c340e6571cc6aa','e0b7b9467d5e3d301a5669033053195d42e702ad82fd8206340e36e68e28617a',NULL,'2026-08-13T10:56:29.404Z','2026-10-07T21:00:05.508Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة"]','["الصحة العامة"]','manual_approved','','[]','Updated','2026-10-07T21:00:05.508Z',200,82,0,'source_content_changed','',NULL,NULL,'body:1ede8412512bf90050de426cf1fdb9b9f3d8d7b4d0e61145c97ff7c2c2d55970','Wed, 07 Oct 2026 20:59:05 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d682abf0-407e-4d1d-9e49-b464f1efaf82','news-d682abf0-407e-4d1d-9e49-b464f1efaf82','الأخضر تحت 20 يواصل معسكره في قطر استعداداً لتصفيات كأس آسيا 2027','الاخضر تحت 20 يواصل معسكره في قطر استعدادا لتصفيات كاس اسيا 2027','واصل المنتخب السعودي تحت 20 عاماً لكرة القدم، الأربعاء، تدريباته ضمن معسكره الإعدادي في قطر، الممتد حتى الثامن والعشرين من أغسطس الجاري، في إطار الاستعداد للتصفيات المؤهلة لكأس آسيا تحت 20 عاماً 2027.','["وأجرى «الأخضر» حصته التدريبية المسائية تحت إشراف المدرب الإسباني سيرجيو بيرناس والجهاز الفني المساعد، إذ طبّق اللاعبون تمارين لياقية وتكتيكية، اختُتمت بمناورة مصغّرة.","ويستأنف المنتخب تدريباته صباح الخميس ضمن المعسكر ذاته في الدوحة.","وتجدر الإشارة إلى أن المنتخب السعودي تحت 20 عاماً صُنِّف في المجموعة الخامسة من التصفيات المؤهلة لكأس آسيا تحت 20 عاماً 2027، إلى جانب منتخبات قطر وعُمان وهونغ كونغ."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/e41yyq7','https://sabq.org/article/e41yyq7','','https://sabq.org/article/e41yyq7','صحيفة سبق','السعودية','2026-08-12T15:02:00.000Z','2026-08-12T18:03:00.000Z','2026-08-13T10:56:36.328Z','https://media.sabq.org/news/2026/08/d8788b9e-64fe-4b70-a11c-6c1547cb0843/w1600.webp','/api/media/d682abf0-407e-4d1d-9e49-b464f1efaf82','/api/media/d682abf0-407e-4d1d-9e49-b464f1efaf82?variant=thumbnail','صورة من الألبوم',1600,1197,'valid','published','archived','valid',54,'23220845b2a4c82c655b9d4624525763c9d11c4acd3cd79d98aa92c4d962d11b','0614d409a72da5f98ac17dd7dd6a5bf9caa61cc62c6057bb1a89eef80c0dd7fe','محدّث','2026-08-13T10:56:36.328Z','2026-10-07T21:00:41.955Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"التعليم","score":1.5},{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:00:41.955Z',200,73,0,'source_article_available','',NULL,NULL,'body:001dc93b03e05a391016b6556cd308fe4ce8340ecb0d06ed52b262ca2909addd','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9e58fba5-13c6-4610-8596-59c616df964f','news-9e58fba5-13c6-4610-8596-59c616df964f','"الفرساوسيات" تزيّن سماء المملكة الليلة.. "المسند": 80 شهاباً في الساعة وذروة قبل الفجر','الفرساوسيات تزين سماء المملكه الليله المسند 80 شهابا في الساعه وذروه قبل الفجر','كشف الدكتور عبدالله المسند، أستاذ المناخ بجامعة القصيم، أن زخات شهب الفرساوسيات ستكون مرئية الليلة وليلتين تاليتين، بمعدل يصل إلى 80 شهاباً في الساعة في أفضل الظروف الجوية، مع توقع بلوغ الذروة قُبيل الفجر.','["وأوضح المسند أن أفضل وقت للمشاهدة يبدأ بعد منتصف الليل وحتى قُبيل الفجر، مشيراً إلى ضرورة التوجه نحو الشمال الشرقي بعيداً عن مناطق التلوث الضوئي، والتركيز على المنطقة التي تعلو نجمَي «الغول» و«المرفق»، وهما نجمان نيّران يقعان فوق يسار نجم الثريا، إذ تنبثق منها الزخات الشهابية.","وبيّن أن الفرساوسيات عبارة عن حبيبات وغبار كوني خلّفها مذنب «سويفت-تتل» في مداره حول الشمس، وحين تعبر الأرض هذا المسار تدخل تلك الجسيمات الغلاف الجوي وتحترق، فتظهر على هيئة شهب متساقطة.","ولفت المسند إلى أن بعض هذه الشهب قد يبلغ من السطوع درجةً تجعله يُلقي ظلالاً للأشياء المحيطة، مؤكداً أن أفضل شروط المشاهدة تتوفر في مكان مظلم تحت سماء صافية بعد منتصف الليل."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/2djx1un','https://sabq.org/article/2djx1un','','https://sabq.org/article/2djx1un','صحيفة سبق','السعودية','2026-08-12T14:42:00.000Z','2026-08-12T17:43:00.000Z','2026-08-13T10:56:36.366Z','https://media.sabq.org/news/2026/08/ddb7e786-108a-4660-9d81-a35421e5e125/w596.webp','/api/media/9e58fba5-13c6-4610-8596-59c616df964f','/api/media/9e58fba5-13c6-4610-8596-59c616df964f?variant=thumbnail','"الفرساوسيات" تزيّن سماء المملكة الليلة.. "المسند": 80 شهاباً في الساعة وذروة قبل الفجر',596,335,'valid','published','archived','valid',47,'c38a743ef5e7c47c59cc1a6035e47b7708c52c4f2cd01a19b17ea7763f5b0056','5e18b0f965487f7bee15330ff57dc97f757b92fb3f2f37e76279ab9618c983bb','محدّث','2026-08-13T10:56:36.366Z','2026-10-07T21:00:02.533Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة شهب متساقطة ولفت المسند"]','["هيئة شهب متساقطة ولفت المسند"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T21:00:02.533Z',200,76,0,'source_article_available','',NULL,NULL,'body:b33b1f9e894f6979dbd950b00b0f2689392e27311a0f70f8df9b10946be8373d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3a528432-81f4-49e4-9908-fd24c2ea3c91','news-3a528432-81f4-49e4-9908-fd24c2ea3c91','«الرواد الشبابية» تحصد المركز الثاني في جائزة التنمية الشبابية على مستوى المملكة','الرواد الشبابيه تحصد المركز الثاني في جائزه التنميه الشبابيه علي مستوي المملكه','حققت جمعية الرواد الشبابية المركز الثاني في جائزة التنمية الشبابية على مستوى المملكة، وتسلّمت التكريم من معالي نائب وزير الموارد البشرية والتنمية الاجتماعية.','["وقالت الجمعية إن الإنجاز جاء ثمرة «شغف فريق، وثقة شركاء، وطموح شباب آمنوا بأن الأثر يُصنع ويكبر بالعمل»، مؤكدة مواصلة برامجها ومبادراتها الموجهة لتنمية قدرات الشباب وتعزيز أثرهم المجتمعي.","وتُعنى جائزة التنمية الشبابية بإبراز الجهات والمبادرات المتميزة في مجال العمل الشبابي، وتحفيز المنافسة على تطوير البرامج النوعية التي تخدم فئة الشباب في مختلف مناطق المملكة."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/n30vjgl','https://sabq.org/article/n30vjgl','','https://sabq.org/article/n30vjgl','صحيفة سبق','السعودية','2026-08-12T14:49:00.000Z','2026-08-12T17:50:00.000Z','2026-08-13T10:56:36.903Z','https://media.sabq.org/news/2026/08/ecf2da5e-ea45-4054-b1d2-c6c16153ec30/w1600.webp','/api/media/3a528432-81f4-49e4-9908-fd24c2ea3c91','/api/media/3a528432-81f4-49e4-9908-fd24c2ea3c91?variant=thumbnail','«الرواد الشبابية» تحصد المركز الثاني في جائزة التنمية الشبابية على مستوى المملكة',1600,900,'valid','published','archived','valid',56,'12bda5050b59c79632c01a62c1c9483c384a7f6ca9c26549dc00db1897fa4edd','9043aedb50a982cd26ada05ffae0d3f221012ea91795b16de57a6034c11cec38','محدّث','2026-08-13T10:56:36.903Z','2026-10-07T20:59:59.531Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"الرياضة","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T20:59:59.531Z',200,74,0,'source_article_available','',NULL,NULL,'body:453e9a6c16028a724bb0103ed3acbcd406b50876a6d5d592400562537f53f8d3','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('90aa7a0f-a467-4f39-ba69-358ad98a161f','news-90aa7a0f-a467-4f39-ba69-358ad98a161f','مسيّرات أوكرانية تُسقط لواءً مدرعاً أميركياً في محاكاة بألمانيا.. ماذا كشفت التجربة؟','مسيرات اوكرانيه تسقط لواء مدرعا اميركيا في محاكاه بالمانيا ماذا كشفت التجربه','أثبتت وحدات الطائرات المسيّرة الأوكرانية تفوقاً لافتاً على قوات الجيش الأميركي خلال تمرين عسكري أُجري في ألمانيا في وقت سابق من العام الجاري، بعدما تمكّنت من رصد قوات ومركبات مدرعة أميركية والقضاء عليها في محاكاة للقتال.','["ووفقاً لتقرير نشرته صحيفة «وول ستريت جورنال» الأميركية، جرى التمرين ضمن مناورات «كومبايند ريزولف» (Combined Resolve)، التي شاركت فيها قوات أميركية مدرعة من قاعدة فورت هود في ولاية تكساس.","وأفاد أشخاص مطّلعون على مجريات التمرين ومسؤولون أميركيون بأن مشغّلي الطائرات المسيّرة الأوكرانيين تمكّنوا بسهولة من تحديد مواقع القوات والمركبات المدرعة الأميركية قبل استهدافها في محاكاة للمعارك، مشيراً أحد المشاركين إلى أن الوحدات الأوكرانية تمكّنت عملياً من القضاء على لواء مدرع أميركي بالكامل ضمن سيناريو التمرين.","الغبار كشف تحركات المدرعات وأوضح المصدر أن القوات الأميركية دفعت إلى الميدان بمركبات مدرعة ثقيلة أثارت كميات كبيرة من الغبار أثناء تحركها، مما جعل اكتشافها أكثر سهولة بواسطة طائرات الاستطلاع المسيّرة الأوكرانية.","وبعد تحديد الأهداف، جرى استخدام طائرات مسيّرة لإسقاط متفجرات، إلى جانب طائرات مسيّرة من طراز «إف بي في» (FPV) المُعدّة لتنفيذ هجمات مباشرة عبر الاصطدام بالأهداف."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ktdnx1g','https://sabq.org/article/ktdnx1g','','https://sabq.org/article/ktdnx1g','صحيفة سبق','السعودية','2026-08-12T14:15:00.000Z','2026-08-12T17:15:00.000Z','2026-08-13T10:56:37.832Z','https://media.sabq.org/news/2026/08/15004503-1135-4df8-97b2-5538c888fd42/w801.webp','/api/media/90aa7a0f-a467-4f39-ba69-358ad98a161f','/api/media/90aa7a0f-a467-4f39-ba69-358ad98a161f?variant=thumbnail','مسيّرات أوكرانية تُسقط لواءً مدرعاً أميركياً في محاكاة بألمانيا.. ماذا كشفت التجربة؟',801,451,'valid','published','archived','valid',48,'101497a457b8fb7d9e08654afb6ec9d60ee1107368fd076ac08bbde5a7e1062a','1c211bb641c3b997109cebbecb2bfa5f69b6d9bb3351155be1b6261b0719e55e','محدّث','2026-08-13T10:56:37.832Z','2026-10-07T21:00:37.344Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','manual_approved','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":3},{"category":"التعليم","score":1.5},{"category":"السيارات","score":1.5}]','Active','2026-10-07T21:00:37.344Z',200,71,0,'source_article_available','',NULL,NULL,'body:a86f0c533b68e63bd4b31843cc350e591bdb9279ed03e5708cb6367fbfcdd7c1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0d050c0f-8df0-486b-924a-8a82ff0704a2','news-0d050c0f-8df0-486b-924a-8a82ff0704a2','القنصلية السعودية في إسطنبول تحذّر: رياح عاصفة وأمطار غزيرة تضرب المدينة الخميس','القنصليه السعوديه في اسطنبول تحذر رياح عاصفه وامطار غزيره تضرب المدينه الخميس','حذّرت القنصلية العامة للمملكة العربية السعودية لدى جمهورية تركيا في إسطنبول، المواطنين السعوديين المقيمين والزائرين، من أحوال جوية سيئة متوقعة صباح غدٍ الخميس الموافق 13 أغسطس.','["وأشارت القنصلية، استناداً إلى تقييم المديرية العامة للأرصاد الجوية التركية، إلى توقع هبوب رياح قوية باتجاه الشمال والشمال الشرقي تتراوح سرعتها بين 50 و70 كيلومتراً في الساعة، وقد تصل في بعض المناطق إلى 80 كيلومتراً في الساعة، مصحوبةً بهطول أمطار غزيرة وعواصف رعدية على ولاية إسطنبول خلال ساعات الصباح والظهيرة.","عرض التغريدة ونبّهت القنصلية إلى أن هذه الظروف الجوية قد تُلقي بظلالها على حركة المرور في المدينة، وقد تتسبب في سقوط الأشجار والأعمدة وطيران الأسقف.","ودعت القنصلية المواطنين إلى توخي الحيطة والحذر، واتخاذ التدابير الاحترازية اللازمة لتجنب مخاطر هذه الظروف الجوية."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/xz2tdri','https://sabq.org/article/xz2tdri','','https://sabq.org/article/xz2tdri','صحيفة سبق','السعودية','2026-08-12T14:29:00.000Z','2026-08-12T17:30:00.000Z','2026-08-13T10:56:37.864Z','https://media.sabq.org/news/2026/08/c0e3453f-d19c-471f-8582-5ca9149aa5ec/w1080.webp','/api/media/0d050c0f-8df0-486b-924a-8a82ff0704a2','/api/media/0d050c0f-8df0-486b-924a-8a82ff0704a2?variant=thumbnail','القنصلية السعودية في إسطنبول تحذّر: رياح عاصفة وأمطار غزيرة تضرب المدينة الخميس',1080,1080,'valid','published','archived','valid',94,'10320c71563a8f3d65359955a16d66888a3d3822632565c1fa80cf45c0812a49','24bab2db836692d8bd8a4719b82636c801ab9e4903442039bc5334f4812a1deb','محدّث','2026-08-13T10:56:37.864Z','2026-10-07T21:00:03.148Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","السفر والسياحة"]','["الطقس والمناخ","السفر والسياحة"]','classified','','[{"category":"السفر","score":4.5},{"category":"أخبار السعودية","score":3},{"category":"المجتمع","score":3}]','Active','2026-10-07T21:00:03.148Z',200,78,0,'source_article_available','',NULL,NULL,'body:d952e51bbb9d1a150748fa482cc3bceebb989fce09804e4d1d07832bc8fbcf42','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6fa5a54a-6d7c-45ea-8219-a5c304817b91','news-6fa5a54a-6d7c-45ea-8219-a5c304817b91','إجلاء 1200 شخص من مخيمات شمال فرنسا جراء حرائق الغابات','اجلاء 1200 شخص من مخيمات شمال فرنسا جراء حرائق الغابات','أجلت السلطات الفرنسية نحو 1200 شخص من مخيمات في منطقة باد كاليه شمال فرنسا، الأربعاء، إثر اندلاع حريقَي غابات في محيط الشاطئ، وجرى نقل السكان المتضررين إلى مآوٍ طارئة.','["وأفادت إدارة منطقة باد كاليه، الواقعة في أقصى شمال البلاد والمتاخمة لمضيق دوفر، بأن أحد الحريقين جرى إخماده، غير أن الظروف «غير مواتية» للسيطرة على الحريق الثاني، الذي يواصل امتداده باتجاه الجنوب في ظل صعوبة الوصول إلى موقعه.","وتشهد فرنسا والقارة الأوروبية موسماً استثنائياً لحرائق الغابات هذا العام، إذ أسهم شتاء رطب نسبياً في نمو الغطاء النباتي الذي جف لاحقاً بفعل موجات حر متعاقبة، مما هيّأ بيئة خصبة لاتساع رقعة الحرائق.","وكانت وزيرة التحول البيئي الفرنسية مونيك باربو قد حذّرت في وقت سابق من اليوم من أن موجات الحرارة قد تُفضي إلى تكاليف مباشرة وغير مباشرة تصل إلى 15 مليار يورو (نحو 17 مليار دولار)."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/qeudylg','https://sabq.org/article/qeudylg','','https://sabq.org/article/qeudylg','صحيفة سبق','السعودية','2026-08-12T14:36:00.000Z','2026-08-12T17:36:00.000Z','2026-08-13T10:56:37.898Z','https://media.sabq.org/news/2026/08/e626863c-8f71-4763-a0fd-734ef8462f01/w960.webp','/api/media/6fa5a54a-6d7c-45ea-8219-a5c304817b91','/api/media/6fa5a54a-6d7c-45ea-8219-a5c304817b91?variant=thumbnail','إجلاء 1200 شخص من مخيمات شمال فرنسا جراء حرائق الغابات',960,640,'valid','published','archived','valid',46,'87e16ae7630b6dee13df1c70cd3fa568069551b01e1c778b74f7b45f7cfabc6c','f7eeaf91e6425a079e9e9441f18d9684ed5088b54a5b9e3842538d7e5b0ee425','محدّث','2026-08-13T10:56:37.898Z','2026-10-07T21:00:03.203Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","الاقتصاد والأسواق"]','["الطقس والمناخ","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T21:00:03.203Z',200,73,0,'source_article_available','',NULL,NULL,'body:8956f24cc3d08a271eb38b7ecb72c0d6a9d036638459c1392eed87ab06f3e3f4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f3bb8581-2285-47b4-9c1c-182c957ec5ae','news-f3bb8581-2285-47b4-9c1c-182c957ec5ae','«أسبيدس» الأوروبية تؤمّن عبور دفعة ثانية من السفن التجارية في البحر الأحمر','اسبيدس الاوروبيه تؤمن عبور دفعه ثانيه من السفن التجاريه في البحر الاحمر','أعلن الاتحاد الأوروبي أن أصوله الحربية وفّرت الحماية لدفعة من السفن التجارية أثناء عبورها البحر الأحمر غربي اليمن، وذلك في خضم استئناف جماعة الحوثيين هجماتها على حركة الشحن التجاري الدولي في المنطقة.','["وقالت مهمة «أسبيدس» البحرية التابعة للاتحاد الأوروبي في تدوينة على حسابها في منصة «إكس» الأربعاء: «أكملت السفن التجارية العابرة للبحر الأحمر رحلتها بأمان تحت حماية أصولنا العسكرية المتواجدة في المنطقة».","وتُعدّ هذه الدفعة الثانية خلال الشهر الجاري، في أعقاب استئناف الحوثيين هجماتهم على السفن التجارية المارّة في البحر الأحمر وخليج عدن.","وأكدت «أسبيدس» أن القوة البحرية الأوروبية «تساهم بفعالية في الحفاظ على أحد أهم الممرات المائية في العالم مفتوحاً وآمناً».","وتتألف المهمة حالياً من وحدتين بحريتين وأكثر من 390 بحاراً من 21 دولة أوروبية، وتشمل منطقة عملياتها مضيقَي باب المندب وهرمز، فضلاً عن المياه الدولية في البحر الأحمر وخليج عدن وبحر العرب وخليج عُمان والخليج العربي."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/i7bf3of','https://sabq.org/article/i7bf3of','','https://sabq.org/article/i7bf3of','صحيفة سبق','السعودية','2026-08-12T14:07:00.000Z','2026-08-12T17:08:00.000Z','2026-08-13T10:56:38.872Z','https://media.sabq.org/news/2026/08/85ed4bf9-0bd7-4ed6-8b75-d1f44ddf83af/w801.webp','/api/media/f3bb8581-2285-47b4-9c1c-182c957ec5ae','/api/media/f3bb8581-2285-47b4-9c1c-182c957ec5ae?variant=thumbnail','«أسبيدس» الأوروبية تؤمّن عبور دفعة ثانية من السفن التجارية في البحر الأحمر',801,451,'valid','published','archived','valid',46,'89e5ded719067a87950d27515ff584768e37a34cabe5e3fb2a450e48a55af1d0','89a31e8ae77778551896c619e53c0ae04c4aa98ce715ab1cca1de568cea5174f','محدّث','2026-08-13T10:56:38.872Z','2026-10-07T21:00:08.252Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["جدة","الخليج العربي"]','["الخليج العربي"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"العالم","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:00:08.252Z',200,74,0,'source_article_available','',NULL,NULL,'body:20d5764e71633fcb1e58182f62148f8e5d7a47d8560960bd2f8361c3d7af375c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b493b22a-3234-4d4c-958d-a97ca0891134','news-b493b22a-3234-4d4c-958d-a97ca0891134','5 حصص يومياً لحماية القلب.. "النمر" يحدد الكمية المثالية وأبرز الاستثناءات','5 حصص يوميا لحمايه القلب النمر يحدد الكميه المثاليه وابرز الاستثناءات','أوضح الدكتور خالد النمر، استشاري أمراض القلب وقسطرة الشرايين، أن الكمية الموصى بها يومياً للحفاظ على صحة القلب هي خمس حصص من الخضار والفاكهة، وأن الحصة الواحدة للبالغ تُقدَّر بنحو 80 جراماً، أي ما يعادل قبضة اليد تقريباً.','["وأشار إلى أن التوزيع الأمثل يكون بثلاث حصص من الخضار وحصتين من الفاكهة يومياً، مع الحرص على تنويع الألوان للحصول على أكبر قدر من الفوائد الغذائية.","ونبّه الدكتور النمر إلى أن البطاطس العادية لا تُحتسب ضمن الحصص الخمس، كونها تُصنَّف ضمن النشويات لا الخضار.","أمثلة على الحصة الواحدة: - فاكهة متوسطة الحجم: تفاحة أو موزة أو برتقالة. - فاكهة صغيرة الحجم: حبتان من المشمش أو الكيوي، أو 7 حبات فراولة. - خضار مطبوخة: 3 ملاعق كبيرة. - سلطة ورقية: كوب مليء. - بقوليات (عدس أو حمص أو فاصوليا): 3 ملاعق كبيرة، وتُحتسب حصة واحدة فقط بصرف النظر عن الكمية المتناولة. - عصير أو سموذي: 150 مل كحد أقصى. - فاكهة مجففة: 30 جراماً فقط، وليس 80 جراماً."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ff2zgny','https://sabq.org/article/ff2zgny','','https://sabq.org/article/ff2zgny','صحيفة سبق','السعودية','2026-08-12T14:00:00.000Z','2026-08-12T17:03:00.000Z','2026-08-13T10:56:39.100Z','https://media.sabq.org/news/2026/08/ee27322d-6994-4f31-804a-e4a07ebf8e90/w801.webp','/api/media/b493b22a-3234-4d4c-958d-a97ca0891134','/api/media/b493b22a-3234-4d4c-958d-a97ca0891134?variant=thumbnail','5 حصص يومياً لحماية القلب.. "النمر" يحدد الكمية المثالية وأبرز الاستثناءات',801,450,'valid','published','archived','valid',35,'5bbbba06c658e8243cd1e1294215bd83593c9950bf66d17326f9bedc63615897','092a81f9797fe01e4ea90824bb6e8e43d6a4be404a1617a6d3fad44ab60c46eb','محدّث','2026-08-13T10:56:39.100Z','2026-10-07T21:00:37.321Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T21:00:37.321Z',200,71,0,'source_article_available','',NULL,NULL,'body:ce695b0b54f87d75a70c848e339481f8602b199084032c3d1add5b51d2f32e35','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bf83632a-21fa-4586-ab3a-4a0a17006f0e','news-bf83632a-21fa-4586-ab3a-4a0a17006f0e','الذهب يتجاوز 4430 دولاراً للأونصة مع تصاعد التوترات في الشرق الأوسط','الذهب يتجاوز 4430 دولارا للاونصه مع تصاعد التوترات في الشرق الاوسط','ارتفعت أسعار المعادن النفيسة، الأربعاء، بقيادة الذهب الذي تجاوز 4430 دولاراً للأونصة، مع تزايد الطلب على الملاذات الآمنة في ظل التوترات المتصاعدة في منطقة الشرق الأوسط.','["وفي التعاملات الفورية، صعد الذهب بأكثر من 1.1% ليبلغ 4431 دولاراً للأونصة بحلول الساعة 10:30 بتوقيت غرينتش، مستفيداً من إقبال المستثمرين على الأصول الآمنة وسط استمرار حالة عدم اليقين الجيوسياسي.","وتلقّى المعدن الأصفر دعماً إضافياً من تراجع مؤشر الدولار إلى ما دون 100 نقطة، فضلاً عن تراجع توقعات رفع أسعار الفائدة الأمريكية.","ولم يقتصر الصعود على الذهب، إذ ارتفعت الفضة في التعاملات الفورية 2.5% لتبلغ 67 دولاراً للأونصة، مدفوعةً بتزايد الطلب الصناعي والتكنولوجي، كما صعد البلاتين 1.8% إلى 1781 دولاراً للأونصة.","وتأتي مكاسب المعادن النفيسة في سياق تقلبات حادة تشهدها الأسواق العالمية، على خلفية التوترات العسكرية في المنطقة والمفاوضات المتعثرة بين الولايات المتحدة وإيران، في ظل مخاوف متصاعدة على إمدادات الطاقة والتجارة عبر مضيق هرمز الاستراتيجي."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/2piarx2','https://sabq.org/article/2piarx2','','https://sabq.org/article/2piarx2','صحيفة سبق','السعودية','2026-08-12T13:56:00.000Z','2026-08-12T16:56:00.000Z','2026-08-13T10:56:39.338Z','https://media.sabq.org/news/2026/08/23cab98e-4416-49b0-bb6b-12b423e2e068/w864.webp','/api/media/bf83632a-21fa-4586-ab3a-4a0a17006f0e','/api/media/bf83632a-21fa-4586-ab3a-4a0a17006f0e?variant=thumbnail','الذهب يتجاوز 4430 دولاراً للأونصة مع تصاعد التوترات في الشرق الأوسط',864,486,'valid','published','archived','valid',56,'b51281b7f4b8e927e513a9e1b3ab84b6971020a083f738129dafbd7dff510ae8','e309a022b8329c2f2cf8481123f35b866885a00817764d496124e44d63b26f60','محدّث','2026-08-13T10:56:39.338Z','2026-10-07T21:00:06.076Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الاقتصاد والأسواق","السياسة والعلاقات الدولية","إيران","الشرق الأوسط","الولايات المتحدة"]','["الطاقة والنفط","الاقتصاد والأسواق","السياسة والعلاقات الدولية","الشرق الأوسط","الولايات المتحدة"]','manual_approved','below_category_threshold','[{"category":"العالم","score":3},{"category":"الطاقة والصناعة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:00:06.076Z',200,71,0,'source_article_available','',NULL,NULL,'body:4e47c3aa51090f9f70a716f26574b2736c8de09c184aa9fb75b78c2c26f27865','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ad070f16-ddea-49c8-885b-0e4b06351965','news-ad070f16-ddea-49c8-885b-0e4b06351965','«الوطني للأرصاد» يعلن استمرار تطور ظاهرة النينيو ومتابعة المؤشرات','الوطني للارصاد يعلن استمرار تطور ظاهره النينيو ومتابعه المؤشرات','أكد المركز الوطني للأرصاد أن ظاهرة النينيو تواصل تطورها، مشيرًا إلى أن أحدث التقارير من المركز الإقليمي للتغير المناخي أفادت بأن الظاهرة لا تزال في مرحلة التطور، ويجري متابعة اكتمال اقتران الاحترار بين المحيط الهادئ والغلاف الجوي. من جهته، يواصل المركز الإقليمي للتغير المناخي متابعة كافة المؤشرات المناخية ذات الصلة، وتحديث التوقعات المتعلقة بتطور ظاهرة…','["وأوضح المركز أن أحدث قيمة أسبوعية لمؤشر Nino 3.4 بلغت 2.02+ درجة مئوية للأسبوع المنتهي في 2 أغسطس 2026، ما يشير إلى استمرار ظروف النينيو فائقة القوة.","وأضاف أن الرصد مستمر لمتابعة تطورات الظاهرة، مع تحديث التوقعات بناءً على أحدث النماذج المناخية المتوفرة.","من جهته، يواصل المركز الإقليمي للتغير المناخي متابعة كافة المؤشرات المناخية ذات الصلة، وتحديث التوقعات المتعلقة بتطور ظاهرة النينيو."]','البيئة والمناخ','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/kydni5x7b','https://ajel.sa/local/kydni5x7b','https://ajel.sa/local/kydni5x7b','https://ajel.sa/local/kydni5x7b','فريق التحرير','السعودية','2026-08-13T05:57:00.000Z','Wed, 07 Oct 2026 20:59:37 GMT','2026-08-13T12:57:41.840Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D9%85%D8%B1%D9%83%D8%B2-%D8%A7%D9%84%D9%88%D8%B7%D9%86%D9%8A-%D9%84%D9%84%D8%A3%D8%B1%D8%B5%D8%A7%D8%AF-2-pHcA4qCW.jpg','/api/media/ad070f16-ddea-49c8-885b-0e4b06351965','/api/media/ad070f16-ddea-49c8-885b-0e4b06351965?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',56,'32c5ba4b9dda18f60f77395263392b8c7c1576dc34cc71d278f4734e103ef2a0','f1a69562a56b79544fe8a1fc813a2df73522d3bf5ccb2f802e15d6de6182be02',NULL,'2026-08-13T12:57:41.840Z','2026-10-07T20:59:39.210Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ"]','["الطقس والمناخ"]','manual_approved','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Updated','2026-10-07T20:59:39.210Z',200,83,0,'source_content_changed','',NULL,NULL,'body:434a26d2f8251d7d77a44c0d96018e69362cbe46bc44e3c98506bd8a4548c51d','Wed, 07 Oct 2026 20:59:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c5b557ec-422d-4bd0-b0fc-a2233457b787','news-c5b557ec-422d-4bd0-b0fc-a2233457b787','اقتصادي / 9 أصناف تين تنتج أكثر من 880 طنًا سنويًا بالجوف','اقتصادي 9 اصناف تين تنتج اكثر من 880 طنا سنويا بالجوف','سكاكا 30 صفر 1448 هـ الموافق 13 أغسطس 2026 م واس تتميز منطقة الجوف بتنوع محاصيلها الزراعية، مستفيدةً من خصوبة التربة وجودة المياه؛ ما أسهم في تنوع إنتاجها من الفواكه الموسمية، ومن بينها محصول التين الذي يشهد زراعته وإنتاجه حضورًا في عدد من مزارع المنطقة.','["وأوضح مدير مكتب وزارة البيئة والمياه والزراعة بمدينة سكاكا الدكتور عقاب بن مخيلف الرويلي، أن إنتاج المنطقة من أصناف التين يتجاوز 880 طنًا سنويًا، مشيرًا إلى أن من أبرز الأصناف المزروعة: براون التركي، والسلطاني، والبلدي، والإسباني الأصفر، والغاني، والعبيد، والفرنسي، والعسلي، والإسباني الأسود، في تنوع يعكس تعدد التجارب الزراعية في المنطقة.","وتأتي زراعة التين ضمن منظومة الإنتاج الزراعي المتنوع الذي تشتهر به الجوف، في ظل ما تتمتع به من مقومات طبيعية أسهمت في نجاح زراعة العديد من أصناف الفواكه، إلى جانب جهود المزارعين في تطوير أساليب الزراعة والعناية بالمحاصيل وتحسين جودة الإنتاج.","ويعد المزارع مساعد الشمري أحد المزارعين الذين خاضوا تجربة زراعة أصناف متعددة من التين في منطقة الجوف، مستفيدًا من المقومات الزراعية التي تتميز بها المنطقة، حيث يعمل على زراعة عدد من الأصناف ومتابعة مراحل نموها وإنتاجها وصولًا إلى مرحلة الحصاد.","وأوضح الشمري أن تنوع أصناف التين يتيح للمزارعين خيارات متعددة في الإنتاج، مبينًا أن العناية بالمحصول تبدأ من اختيار الصنف المناسب، وتمر بمراحل الري والتسميد والمتابعة المستمرة للأشجار، وصولًا إلى الحصاد في الوقت المناسب لضمان جودة الثمار."]','الاقتصاد','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2653053?type=news&uuid=N2653053','https://spa.gov.sa/ar/N2653053?type=news&uuid=N2653053','N2653053','N2653053','','السعودية','2026-08-13T08:31:00.000Z',NULL,'2026-08-13T12:58:04.913Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10601924.jpg','/api/media/c5b557ec-422d-4bd0-b0fc-a2233457b787','/api/media/c5b557ec-422d-4bd0-b0fc-a2233457b787?variant=thumbnail','اقتصادي / 9 أصناف تين تنتج أكثر من 880 طنًا سنويًا بالجوف',1600,1066,'valid','published','archived','valid',50,'aa264c09c126e0ce05ff97df125be741f744e04539703f334b567a8d5a1ea743','adfbd72925871c34687d16baa8a68f5b895d46caa6b06d372c17d85e47c33525',NULL,'2026-08-13T12:58:04.913Z','2026-10-07T20:59:04.615Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البيئة والمياه والزراعة بمدينة","الاقتصاد والأسواق","الجوف"]','["وزارة البيئة والمياه والزراعة بمدينة","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":3},{"category":"الصحة","score":1.5},{"category":"البيئة والمناخ","score":1.5}]','Active','2026-10-07T20:59:04.615Z',200,86,0,'source_article_available','',NULL,NULL,'body:a70432414bc30b28de7ac16d2f32b259cd9acabaa29efe941e142c9d572417bb','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('088bc26d-4106-4413-8a5d-6d87f224fa01','news-088bc26d-4106-4413-8a5d-6d87f224fa01','علوم وتقنيات / "العناية بالحرمين" تدعو المعتمرين إلى التخطيط المبكر واختيار أوقات الكثافة الأقل','علوم وتقنيات العنايه بالحرمين تدعو المعتمرين الي التخطيط المبكر واختيار اوقات الكثافه الاقل','مكة المكرمة 30 صفر 1448 هـ الموافق 13 أغسطس 2026 م واس دعت الهيئة العامة للعناية بشؤون المسجد الحرام والمسجد النبوي ضيوف الرحمن إلى التخطيط المبكر لأداء مناسك العمرة، والتعرّف على أوقات كثافة المعتمرين في المسجد الحرام، واختيار الأوقات المناسبة، بما يسهم في أداء النسك بيسر وسهولة، ويعزز انسيابية الحركة في المطاف والمسعى.','["وأوضحت الهيئة، في دليلها التوعوي لأوقات الكثافة، أن الفترة من الساعة العاشرة مساءً حتى الرابعة صباحًا تشهد كثافة خفيفة، وكذلك الفترة من الساعة التاسعة صباحًا حتى الرابعة مساءً، فيما تكون الكثافة متوسطة خلال الفترة من الخامسة صباحًا حتى الثامنة صباحًا، وترتفع إلى كثافة عالية خلال الفترة من الخامسة مساءً حتى التاسعة مساءً.","ويأتي التعريف بأوقات الكثافة ضمن جهود الهيئة الرامية إلى مساعدة قاصدي المسجد الحرام على تنظيم أوقاتهم قبل التوجه لأداء العمرة، والاستفادة من الفترات الأقل ازدحامًا، بما يسهم في تعزيز الراحة والسلامة، وتحسين تجربة ضيف الرحمن منذ وصوله إلى المسجد الحرام حتى إتمام نسكه.","وأكدت الهيئة العامة للعناية بشؤون المسجد الحرام والمسجد النبوي أن التخطيط المسبق واختيار الوقت المناسب لأداء العمرة يسهمان في رفع مستوى انسيابية حركة المعتمرين داخل المسجد الحرام، داعيةً ضيوف الرحمن إلى متابعة المؤشرات الإرشادية المتعلقة بالكثافة، والاستفادة من الخدمات الرقمية المتاحة لمعرفة حالة المطاف والمسعى، بما يعينهم على اختيار الوقت والمكان الأنسب لأداء النسك.","وتتيح الهيئة عبر موقعها الإلكتروني خدمة رقمية لمعرفة حالة الكثافة في مواقع المطاف والمسعى، تشمل صحن المطاف وأدواره المختلفة، إلى جانب أدوار المسعى، بما يمكّن المعتمرين من الاطلاع على مستويات الكثافة والاستفادة من المعلومات المتاحة قبل وجودهم في المسجد الحرام وأثناءه."]','المجتمع','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2653008?type=news&uuid=N2653008','https://spa.gov.sa/ar/N2653008?type=news&uuid=N2653008','N2653008','N2653008','','السعودية','2026-08-13T07:36:00.000Z',NULL,'2026-08-13T12:58:04.919Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10601510.jpeg','/api/media/088bc26d-4106-4413-8a5d-6d87f224fa01','/api/media/088bc26d-4106-4413-8a5d-6d87f224fa01?variant=thumbnail','علوم وتقنيات / "العناية بالحرمين" تدعو المعتمرين إلى التخطيط المبكر واختيار أوقات الكثافة الأقل',1600,2852,'valid','published','archived','valid',48,'b4ee46a70f20d1ebe5226e1c44e74fd90b109b9d85707f93100aa5040bf46a83','87ff9925db8ea06189c2f72b49b4389c11f8593b2e7c7e4f4607fb7307e58f26',NULL,'2026-08-13T12:58:04.919Z','2026-10-07T20:59:06.062Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي"]','["التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":3},{"category":"الصحة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:59:06.062Z',200,87,0,'source_article_available','',NULL,NULL,'body:0f74f8a78ddbf30e70c03f07b4d3d61e80106c7f3ebd558e4923cef4ac5db32b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6fe230b4-d366-47d2-8c48-e5334f2c58fb','news-6fe230b4-d366-47d2-8c48-e5334f2c58fb','جمعية البر ببني حسن تُكرّم رواد التطوع 2026 بحضور السديس ورعاية أمير الباحة','جمعيه البر ببني حسن تكرم رواد التطوع 2026 بحضور السديس ورعايه امير الباحه','احتفت جمعية البر الخيرية بمحافظة بني حسن بالفائزين في جائزة رواد العمل التطوعي 2026، في حفل أُقيم مساء أمس بقصر المصيف للاحتفالات ببني حسن، برعاية صاحب السمو الملكي الأمير الدكتور حسام بن سعود بن عبدالعزيز أمير منطقة الباحة، وبحضور عدد من المسؤولين والأعيان والمهتمين بالعمل الخيري والتطوعي.','["وشرّف الحفلَ ضيفُ الجائزة معالي رئيس شؤون المسجد الحرام والمسجد النبوي الشيخ الأستاذ الدكتور عبدالرحمن بن عبدالعزيز السديس، الذي أمّ الحضور في صلاة المغرب، في مستهل مناسبة جسّدت قيم التكافل والعطاء وأبرزت النماذج المجتمعية المُسهمة في خدمة الإنسان والمجتمع.","وتضمّن الحفل فقرات استعرضت رسالة الجائزة وأهدافها في تعزيز ثقافة التطوع وتحفيز المبادرات النوعية، وإبراز النماذج الملهمة في العمل الخيري والاجتماعي، إلى جانب تسليط الضوء على جهود المتطوعين والداعمين في تنمية المجتمع وترسيخ قيم المسؤولية الاجتماعية.","وكرّمت الجمعية الفائزين بالجائزة في عدد من المجالات، إذ فاز الشيخ مبارك بن منسي آل عصيدان في مجال إصلاح ذات البين، وعلي بن محمد أبو ملحه الغامدي في مجال الدعوة التطوعية، ورجل الأعمال جمعان بن حسن آل بردان بجائزة الشخصية العامة، ومحمد بن عبدالله غنام الغامدي في مجال تحفيظ القرآن الكريم، والدكتور سعيد بن سعد جمعان العمري في مجال البر التطوعي، وجمعان بن علي الكرت الغامدي في مجال الإعلام التطوعي، ومسفر بن يحيى الهرش في…","وفي مجالات التطوع العام، فاز الدكتور سعيد بن سعد المرطان في مجال رعاية المسنين، والدكتور سعيد بن محمد البهلوان الغامدي في مجال خدمة بيوت الله، وعادل بن جمعان الحريري الزهراني في مجال كفالة الأيتام، ومحمد بن مسفر القريشي في مجال العمل التطوعي العام، ورباب بنت علي الغامدي في مجال خدمة ذوي الإعاقة، ورجاء بنت عيظة الزهراني في مجال الفرق التطوعية."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/lc7ogsq','https://sabq.org/article/lc7ogsq','','https://sabq.org/article/lc7ogsq','عبدالعزيز الشهري ','السعودية','2026-08-12T16:16:00.000Z','2026-08-12T19:16:00.000Z','2026-08-13T13:02:26.971Z','https://media.sabq.org/news/2026/08/2aa8a6b1-1d42-470e-b5dc-fd079309ddff/w1280.webp','/api/media/6fe230b4-d366-47d2-8c48-e5334f2c58fb','/api/media/6fe230b4-d366-47d2-8c48-e5334f2c58fb?variant=thumbnail','جمعية البر ببني حسن تُكرّم رواد التطوع 2026 بحضور السديس ورعاية أمير الباحة',1280,720,'valid','published','archived','valid',99,'2b3700c31b0371d2cd8584a4535543a806b36b74269881b1024a794caf5687fb','b8e21810bc4fd57169466607eeb99a245833c2efa161ccb8259f6b94b014bd01','محدّث','2026-08-13T13:02:26.971Z','2026-10-07T20:59:37.366Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس شؤون المسجد الحرام والمسجد","السفر والسياحة","الثقافة والفنون","الباحة"]','["رئيس شؤون المسجد الحرام والمسجد","السفر والسياحة","الثقافة والفنون"]','classified','','[{"category":"التعليم","score":4.5},{"category":"المناطق","score":3},{"category":"الاقتصاد","score":3}]','Active','2026-10-07T20:59:37.366Z',200,74,0,'source_article_available','',NULL,NULL,'body:381eab52185e664ea141fefa0977414dc37d097f0f044701a40782b1cc5eeb3f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7cc458bd-4be5-47f0-8d3b-6797ab059c9e','news-7cc458bd-4be5-47f0-8d3b-6797ab059c9e','ثورة الفحص الجيني.. آلاف المواليد تحت المجهر لكشف أمراض نادرة قبل ظهور الأعراض','ثوره الفحص الجيني الاف المواليد تحت المجهر لكشف امراض نادره قبل ظهور الاعراض','سلّط باحثون من نيويورك وبوسطن الضوء، في يونيو الماضي، على حالة طفلة تبلغ من العمر 6 أشهر شُخِّصت بمرض «باتن»، وهو اضطراب وراثي نادر ومميت يؤثر في الجهاز العصبي — وذلك قبل ظهور أي أعراض، وربما قبل سنوات من الموعد المعتاد لاكتشاف المرض، بحسب تقرير نشره موقع «CNBC».','["وعادةً ما يُكتشف مرض «باتن» بعد ظهور أعراض مثل تغيرات مفاجئة في الرؤية أو نوبات الصرع، غير أن الجهاز العصبي يكون قد تعرّض بحلول ذلك الوقت لأضرار بالغة لا يمكن عكسها.","فحص 100 ألف مولود بحثاً عن أمراض نادرة كانت الطفلة ضمن دراسة «GUARDIAN»، وهي مبادرة بحثية أطلقتها جامعة كولومبيا في ولاية نيويورك، تهدف إلى توفير تسلسل مجاني لكامل الجينوم وفحص ما يصل إلى 100 ألف مولود جديد للكشف عن أمراض وراثية نادرة.","وتقود الدراسة عالمة الوراثة السريرية والجزيئية ويندي تشونج، فيما حصلت المبادرة على تمويل من شركات «Sanofi» و«Illumina» و«GeneDx».","ويختلف هذا الفحص جذرياً عن برامج فحص حديثي الولادة التقليدية المعتمدة في الولايات المتحدة، التي تبحث عادةً عن نحو 30 إلى 50 مرضاً فحسب، إذ يفحص برنامج «GUARDIAN» نحو 450 حالة وراثية دون الحاجة إلى أخذ عينات دم إضافية من الطفل."]','العالم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/g26pxbv','https://sabq.org/article/g26pxbv','','https://sabq.org/article/g26pxbv','صحيفة سبق','السعودية','2026-08-12T16:00:00.000Z','2026-08-12T19:00:00.000Z','2026-08-13T13:02:27.346Z','https://media.sabq.org/news/2026/08/37346019-b74a-4e1a-b043-5babafde04ff/w801.webp','/api/media/7cc458bd-4be5-47f0-8d3b-6797ab059c9e','/api/media/7cc458bd-4be5-47f0-8d3b-6797ab059c9e?variant=thumbnail','ثورة الفحص الجيني.. آلاف المواليد تحت المجهر لكشف أمراض نادرة قبل ظهور الأعراض',801,451,'valid','published','archived','valid',89,'cd6985ae21f52d64d74a4e00411820bca86cac8c87be6f68b522e958a42ed608','9eeb1c4eddafa2ed43184aa3b3afb07d96ae2cd18347b817bfe00f286a1639c8','محدّث','2026-08-13T13:02:27.346Z','2026-10-07T21:00:09.428Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة كولومبيا في ولاية نيويورك","الصحة العامة","التعليم والتدريب","الولايات المتحدة"]','["جامعة كولومبيا في ولاية نيويورك","الصحة العامة","التعليم والتدريب","الولايات المتحدة"]','manual_approved','','[]','Active','2026-10-07T21:00:09.428Z',200,73,0,'source_article_available','',NULL,NULL,'body:1d09562174889287316a8774553f6d476d8bdf8f8454e37b0e1a2d05ac43f72b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a2aaa70d-1eb7-465e-98e7-adab520439e9','news-a2aaa70d-1eb7-465e-98e7-adab520439e9','دوري روشن ينطلق بثلاث مواجهات منتظره .. وسباق مفتوح على اللقب ','دوري روشن ينطلق بثلاث مواجهات منتظره وسباق مفتوح علي اللقب','تنطلق اليوم الخميس منافسات موسم 2026-2027 من دوري روشن السعودي للمحترفين، بمشاركة 18 فريقاً يخوض كل منها 34 مباراة، بإجمالي 306 مباريات، في ظل سباق مفتوح على اللقب يضم النصر حامل البطولة، والهلال الساعي لاستعادتها، والأهلي بطل دوري أبطال آسيا للنخبة، والقادسية والاتحاد.','["ارتفاع الإيرادات 115% يأتي انطلاق الموسم الجديد في وقت تشهد فيه رابطة الدوري السعودي نمواً ملحوظاً في إيراداتها؛ إذ أوضح رئيس مجلس إدارة الرابطة المهندس عمر مغربل أن الإيرادات ارتفعت بنسبة 115% خلال السنوات الثلاث الماضية، مبيناً أن 82% من هذه الإيرادات تُوزَّع على الأندية، بما يعكس اتساع القاعدة الاستثمارية للمسابقة وتنامي مواردها.","استهداف قائمة أفضل 10 دوريات عالمياً يستهدف الاتحاد السعودي لكرة القدم رفع القيمة الفنية والتنظيمية والاستثمارية للدوري، وصولاً به إلى قائمة أفضل 10 دوريات في العالم، في ظل التطور المتسارع الذي تشهده كرة القدم السعودية على مختلف المستويات.","وتكتسب النسخة الجديدة أهميتها من تقارب مستويات فرق المقدمة في الموسم الماضي؛ إذ لم يفصل بين النصر المتصدر بـ86 نقطة والقادسية الرابع سوى 9 نقاط، فيما حُسم اللقب في الجولة الأخيرة، لتعود المنافسة هذا الموسم بمتغيرات فنية وأهداف مختلفة.","رحلة الحفاظ على اللقب يدخل النصر الموسم الجديد بصفته حامل اللقب، بعدما حقق الموسم الماضي 28 انتصاراً من أصل 34 مباراة، وسجل 91 هدفاً واستقبل 28، وأنهى المسابقة برصيد 86 نقطة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/zrrvtvi','https://sabq.org/article/zrrvtvi','','https://sabq.org/article/zrrvtvi','صحيفة سبق','السعودية','2026-08-12T16:06:00.000Z','2026-08-12T19:07:00.000Z','2026-08-13T13:02:27.781Z','https://media.sabq.org/news/2026/08/4c9fcddd-b7d7-4fc5-8378-1e2b8ba21c3f/w1600.webp','/api/media/a2aaa70d-1eb7-465e-98e7-adab520439e9','/api/media/a2aaa70d-1eb7-465e-98e7-adab520439e9?variant=thumbnail','دوري روشن ينطلق بثلاث مواجهات منتظره .. وسباق مفتوح على اللقب ',1600,1067,'valid','published','archived','valid',99,'ea59dc4ae1d216cc576d3f46ae7bcd02f4844c4fc8aaf234f786429533497361','941a5ac0e12a562e1a6b6c22a74c951811ae14e286c26741a9584c16215b7523','محدّث','2026-08-13T13:02:27.781Z','2026-10-07T21:00:09.413Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إدارة الرابطة المهندس عمر","رئيس مجلس إدارة الرابطة المهندس","الرياضة السعودية","الاقتصاد والأسواق"]','["مجلس إدارة الرابطة المهندس عمر","رئيس مجلس إدارة الرابطة المهندس","الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[{"category":"أخبار السعودية","score":1.5},{"category":"السفر","score":1.5},{"category":"السيارات","score":1.5}]','Active','2026-10-07T21:00:09.413Z',200,73,0,'source_article_available','',NULL,NULL,'body:d05e46c97c0a83c80959f53989e0c5b631a6e6b395e1b8b10585bfff2c6f757a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e89fdaa4-27e6-427d-bca1-3ca96c1400b7','news-e89fdaa4-27e6-427d-bca1-3ca96c1400b7','رائد فضاء روسي يوثّق كسوف الشمس من ارتفاع 400 كيلومتر','رائد فضاء روسي يوثق كسوف الشمس من ارتفاع 400 كيلومتر','نشرت وكالة الفضاء الروسية «روس كوسموس» صوراً استثنائية لكسوف شمسي، التقطها رائد الفضاء بيوتر دوبروف من على متن محطة الفضاء الدولية، في توثيق علمي نادر لإحدى أبرز الظواهر الفلكية.','["وعلّقت «روس كوسموس» على الصور التي نُشرت عبر منصة «ماكس»: «كسوف شمسي من ارتفاع 400 كيلومتر.","التقط رائد الفضاء بيوتر دوبروف واحدة من أكثر الظواهر الفلكية انتظاراً هذا العام من على متن محطة الفضاء الدولية، كاشفاً كيف بدت الشمس في لحظات اقتراب قرص القمر منها».","وبدأ الكسوف في الساعة 18:34 بتوقيت موسكو، وبلغ ذروته في الساعة 20:46، قبل أن ينتهي في الساعة 22:58.","وشمل الكسوف الكلي للشمس مناطق في إسبانيا وأيسلندا وشرق غرينلاند، فيما رُصد في روسيا من منطقة تايمير، ولوحظت مراحله الجزئية في شمال روسيا وشمال غربها، إضافةً إلى أوروبا وأفريقيا وأمريكا الشمالية، ومياه المحيطات الثلاثة."]','العالم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/gng100b','https://sabq.org/article/gng100b','','https://sabq.org/article/gng100b','صحيفة سبق','السعودية','2026-08-12T15:46:00.000Z','2026-08-12T18:46:00.000Z','2026-08-13T13:02:28.939Z','https://media.sabq.org/news/2026/08/0447427b-0f9d-46cf-b083-6dec91ccf4fe/w846.webp','/api/media/e89fdaa4-27e6-427d-bca1-3ca96c1400b7','/api/media/e89fdaa4-27e6-427d-bca1-3ca96c1400b7?variant=thumbnail','رائد فضاء روسي يوثّق كسوف الشمس من ارتفاع 400 كيلومتر',846,551,'valid','published','archived','valid',52,'4376baf9771f637d26b50d5305fd53720496712512a78d8ac90d66434af5d18f','33dbe8c9d8d9c074f1c95f046f585c364c82ae40480c6bb2f93414cbe2c632f2','محدّث','2026-08-13T13:02:28.939Z','2026-10-07T21:00:03.141Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["روسيا","أوروبا"]','[]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T21:00:03.141Z',200,74,0,'source_article_available','',NULL,NULL,'body:50e7264185ef1be7748ef4f8ec571694e0f22280934da6c7c03f14c42a240400','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('aab3d6b2-9f5b-46ee-8bb9-9f95adaf7c6a','news-aab3d6b2-9f5b-46ee-8bb9-9f95adaf7c6a','بعد أحكام إعدام الأسد وشقيقه.. العدل السورية تتحرك دولياً لملاحقة الفارين','بعد احكام اعدام الاسد وشقيقه العدل السوريه تتحرك دوليا لملاحقه الفارين','كشف معاون وزير العدل السوري مصطفى القاسم عن تشكيل وزارة العدل لجنةً متخصصة للتواصل مع مكتب الشرطة الجنائية الدولية (الإنتربول)، بهدف ملاحقة وتسليم المتهمين الفارين إلى الخارج.','["وأوضح القاسم في تصريحات لقناة «الإخبارية» السورية، الأربعاء، أن التعاون الدولي مع سوريا من شأنه تسريع إنهاء ملف العدالة، من خلال تعاون الدول في تسليم المتهمين الذين فروا إلى أراضيها.","وأضاف أن الوزارة أسّست مكاتب لتلقي الشكاوى المتعلقة بجرائم العدالة الانتقالية، بهدف تسهيل الإجراءات على المواطنين، مشيراً إلى أن الوزارة تسعى كذلك إلى استعادة الأموال السورية المنهوبة في الخارج وملاحقة المتورطين في استثمارها.","وأكد القاسم أن وزارة العدل تعمل على تحقيق أعلى مستويات التوافق بين القضاء السوري والمعايير الدولية للمحاكمات، مشدداً على مبدأ السيادة الوطنية السورية في إطار مسار العدالة الانتقالية.","وجاءت هذه التصريحات في اليوم التالي لإصدار محكمة الجنايات الرابعة في دمشق حكماً بالإعدام حضورياً بحق الرئيس السابق لفرع «الأمن السياسي» في درعا عاطف نجيب، وغيابياً بحق الرئيس السوري السابق بشار الأسد وشقيقه، إضافةً إلى كلٍّ من: فهد الفريج، ولؤي العلي، وقصي ميهوب، ووفيق ناصر، وطلال العيسمي."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/d1upjmi','https://sabq.org/article/d1upjmi','','https://sabq.org/article/d1upjmi','صحيفة سبق','السعودية','2026-08-12T15:56:00.000Z','2026-08-12T18:56:00.000Z','2026-08-13T13:02:29.119Z','https://media.sabq.org/news/2026/08/65a59c3f-5bb3-44aa-be8c-f3d299aad970/w846.webp','/api/media/aab3d6b2-9f5b-46ee-8bb9-9f95adaf7c6a','/api/media/aab3d6b2-9f5b-46ee-8bb9-9f95adaf7c6a?variant=thumbnail','بعد أحكام إعدام الأسد وشقيقه.. العدل السورية تتحرك دولياً لملاحقة الفارين',846,551,'valid','published','archived','valid',50,'6a734bda5dd6bd1c9a6d80b12f2f937acda05e2b1d44a987b445e639d9bf12e3','0d95b02ac48d80af906ccf20ade225e0ac536051e99648b7630e8b5d6f1ca114','محدّث','2026-08-13T13:02:29.119Z','2026-10-07T20:59:39.844Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة العدل تعمل على تحقيق","الثقافة والفنون","الاقتصاد والأسواق","سوريا"]','["وزارة العدل تعمل على تحقيق","الثقافة والفنون","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"السياسة","score":1.5},{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:59:39.844Z',200,77,0,'source_article_available','',NULL,NULL,'body:025013471da65aeb9a1f8dd72d5fbfdcfc2983f10e51e9d5ca0c758545381822','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4f948c08-126b-406d-9eaf-f3a91e8e9788','news-4f948c08-126b-406d-9eaf-f3a91e8e9788','الاتحاد يوافق على إعارة فيصل الغامدي لنادي نيوم حتى نهاية الموسم','الاتحاد يوافق علي اعاره فيصل الغامدي لنادي نيوم حتي نهايه الموسم','وافقت إدارة نادي الاتحاد رسمياً على طلب نادي نيوم باستعارة لاعب الفريق الأول فيصل الغامدي حتى نهاية الموسم الرياضي الحالي.','["وتأتي هذه الإعارة في إطار منح اللاعب فرصة احترافية جديدة، تتيح له المشاركة بصورة أكبر خلال المرحلة المقبلة، بما يسهم في تطوير مستواه واكتساب المزيد من الخبرات الفنية.","وأعربت إدارة نادي الاتحاد عن أمنياتها للاعب بالتوفيق والنجاح في تجربته الجديدة مع نيوم، آملةً أن يحقق أقصى استفادة ممكنة منها بما يعزز مسيرته الاحترافية."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/pNl5JrN','https://sabq.org/article/pNl5JrN','','https://sabq.org/article/pNl5JrN','جمال المرشدي','السعودية','2026-08-12T15:40:00.000Z','2026-08-12T18:40:00.000Z','2026-08-13T13:02:29.225Z','https://media.sabq.org/news/2026/08/6d2cba41-84eb-40ca-80bf-c22e7ec57719/w1600.webp','/api/media/4f948c08-126b-406d-9eaf-f3a91e8e9788','/api/media/4f948c08-126b-406d-9eaf-f3a91e8e9788?variant=thumbnail','الاتحاد يوافق على إعارة فيصل الغامدي لنادي نيوم حتى نهاية الموسم',1600,989,'valid','published','archived','valid',52,'e5bb69c7de50d8cd0313b5c40ab92fadb1d09491ef4d2d8d19a18ba78cd2238b','552cf0e38c2754c2c4d18c5cc8306d4e5ba9646b29f22ceadf68d8723ad27712','محدّث','2026-08-13T13:02:29.225Z','2026-10-07T20:59:58.897Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:59:58.897Z',200,72,0,'source_article_available','',NULL,NULL,'body:a74fdb4306aa3633f37fa42e7adf95981d2bc79e49189f8ca148366822a12b00','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('17599958-e860-4455-8d83-b4d8c7b940f6','news-17599958-e860-4455-8d83-b4d8c7b940f6','مرور جازان يضبط قائد مركبة اخترق وادياً جارياً وغرامته تبلغ 10 آلاف ريال','مرور جازان يضبط قائد مركبه اخترق واديا جاريا وغرامته تبلغ 10 الاف ريال','ضبطت إدارة المرور في منطقة جازان، بالتنسيق مع الرئاسة العامة للدفاع المدني، قائد مركبة ارتكب مخالفة عبور الأودية والشعاب أثناء جريانها، وذلك إثر انتشار مقطع مرئي يوثّق الواقعة على منصات التواصل الاجتماعي.','["وأكدت الجهات المختصة أنه جرى التعرف على القائد المخالف وتطبيق الإجراءات النظامية بحقه فور رصد المقطع، في إطار جهود المرور المستمرة لردع السلوكيات الخطرة على الطرق.","وشددت الجهات المختصة على أن عبور الأودية والشعاب أثناء جريانها يُعدّ تهوراً بالغ الخطورة قد يودي بحياة قائد المركبة ومن معه، محذّرةً من الإقدام على مثل هذه السلوكيات في موسم الأمطار.","وتُصنَّف مخالفة عبور الأودية والشعاب أثناء جريانها ضمن المخالفات المرورية الجسيمة، وتتراوح غرامتها بين 5000 ريال و10,000 ريال وفق درجة المخالفة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/yfhzpg3','https://sabq.org/article/yfhzpg3','','https://sabq.org/article/yfhzpg3','صحيفة سبق','السعودية','2026-08-12T15:34:00.000Z','2026-08-12T18:37:00.000Z','2026-08-13T13:02:30.398Z','https://media.sabq.org/news/2026/08/11ec194d-0872-4390-8649-652b78b03949/w1600.webp','/api/media/17599958-e860-4455-8d83-b4d8c7b940f6','/api/media/17599958-e860-4455-8d83-b4d8c7b940f6?variant=thumbnail','مرور جازان يضبط قائد مركبة اخترق وادياً جارياً وغرامته تبلغ 10 آلاف ريال',1600,805,'valid','published','archived','valid',44,'688338366adc3b30efa9d4286a5712e24ebe4e38c1b0269413ae6dabd52d485a','fd44e339b0afeb7b6c0878f3ec6073dbf0028e9f1b3a048299891b130ac8f81d','محدّث','2026-08-13T13:02:30.398Z','2026-10-07T21:00:02.544Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","جازان"]','["الطقس والمناخ"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":3},{"category":"المجتمع","score":3},{"category":"الصحة","score":1.5}]','Active','2026-10-07T21:00:02.544Z',200,75,0,'source_article_available','',NULL,NULL,'body:34491e9da430c51aa03c461d4c8067e36b7f29a7bc2bdc6916d8d3449946adc1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c16e5f55-4b5f-41df-913c-d963588ad4ad','news-c16e5f55-4b5f-41df-913c-d963588ad4ad',' لماذا يقاوم الجسم فقدان الوزن؟ العلم يكشف دور الدماغ و"ذاكرة الوزن"','لماذا يقاوم الجسم فقدان الوزن العلم يكشف دور الدماغ و ذاكره الوزن','ساد اعتقاد لعقود بأن فقدان الوزن يعتمد ببساطة على قوة الإرادة: تناول كميات أقل من الطعام وممارسة المزيد من النشاط البدني.','["لكن العلم الحديث يكشف أن الأمر أكثر تعقيداً بكثير، وأن البيولوجيا تلعب دوراً رئيسياً في صعوبة فقدان الوزن والحفاظ عليه.","ولفهم ذلك، علينا العودة مئات الآلاف من السنين إلى أسلاف البشر الأوائل، الذين كان مخزون الدهون في أجسامهم وسيلةً للبقاء؛ إذ كان نقصه الشديد يعني المجاعة، بينما كان الإفراط فيه يمثل عبئاً يحد من الحركة.","ومع مرور الوقت، طوّر الجسم آليات بيولوجية معقدة يتحكم فيها الدماغ للحفاظ على مخزون الطاقة.","غير أن هذه الآليات التي ساعدت أسلافنا على البقاء تحولت في عالم اليوم — حيث تتوفر الأطعمة عالية السعرات بسهولة وتراجعت الحاجة إلى الحركة — إلى أحد أسباب صعوبة فقدان الوزن."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/zfuxqw0','https://sabq.org/article/zfuxqw0','','https://sabq.org/article/zfuxqw0','صحيفة سبق','السعودية','2026-08-12T15:20:00.000Z','2026-08-12T18:20:00.000Z','2026-08-13T13:02:30.417Z','https://media.sabq.org/news/2026/08/11742ed3-7502-4776-a44d-a6f5eeef4a8b/w801.webp','/api/media/c16e5f55-4b5f-41df-913c-d963588ad4ad','/api/media/c16e5f55-4b5f-41df-913c-d963588ad4ad?variant=thumbnail',' لماذا يقاوم الجسم فقدان الوزن؟ العلم يكشف دور الدماغ و"ذاكرة الوزن"',801,451,'valid','published','archived','valid',83,'1fccb250cad679e9eda63927c29dc96a8a451612eb74e063498d6703143c718f','d8e1da6321a8aee6485bf0d745ccad2467d6969b5f8024ad1076d747150a7d29','محدّث','2026-08-13T13:02:30.417Z','2026-10-07T20:59:39.848Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط"]','["الطاقة والنفط"]','manual_approved','','[]','Active','2026-10-07T20:59:39.848Z',200,76,0,'source_article_available','',NULL,NULL,'body:bfae66d11282b9d907472c4a578a8c6456d0c3ee8ad314e7370e794dbd5e569f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('05aa36fa-818e-484e-8db6-2fbbb59fb66a','news-05aa36fa-818e-484e-8db6-2fbbb59fb66a','جهود الإنقاذ في كولومبيا تدخل مرحلتها الحرجة بعد زلزال راح ضحيته 250 شخصاً','جهود الانقاذ في كولومبيا تدخل مرحلتها الحرجه بعد زلزال راح ضحيته 250 شخصا','سابقت فرق الإنقاذ في كولومبيا الزمن، الأربعاء، للبحث عن ناجين ما زالوا محاصرين تحت أنقاض مبانٍ منهارة، بعد يومين من زلزال عنيف أودى بحياة نحو 250 شخصاً في الأودية الغربية للبلاد ومنطقة زراعة البن.','["وقال رئيس بلدية مدينة كالي، أليخاندرو إيدر، للصحفيين: «نحن في سباق مع الزمن لإنقاذ الأرواح»، محذراً من أنه لم يتبقَّ سوى أقل من يوم واحد من الأيام الثلاثة الأولى الحاسمة، التي تتضاعف خلالها فرص العثور على ناجين.","وأضاف: «سنواصل العمل بعد انتهاء هذه الفترة، لكن من المهم إنقاذ أكبر عدد ممكن من الأشخاص خلال اليوم المتبقي»، مشيراً إلى أن عمال الإنقاذ بحاجة إلى الهدوء والنظام لرصد أي ناجٍ تحت الأنقاض.","وتشير التقديرات الرسمية إلى أن الزلزال الذي بلغت شدته 7.4 درجة على مقياس ريختر، وضرب البلاد بُعيد الساعة السابعة صباحاً بالتوقيت المحلي يوم الاثنين، تسبّب في إصابة 3770 شخصاً، ودمار أكثر من 9550 منزلاً، وأثّر على ما يزيد على 30300 أسرة.","وانهار أكثر من 56 مبنى في كالي، ثالث أكبر مدن كولومبيا، ما أسفر عن مقتل ما لا يقل عن 95 شخصاً وإصابة نحو ألف آخرين، وفقاً لبيانات رابطة «أسوكابيتاليس» التي تضم عواصم المناطق الكولومبية."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/w0cwc32','https://sabq.org/article/w0cwc32','','https://sabq.org/article/w0cwc32','صحيفة سبق','السعودية','2026-08-12T15:29:00.000Z','2026-08-12T18:30:00.000Z','2026-08-13T13:02:30.487Z','https://media.sabq.org/news/2026/08/9fe41f5e-d122-485b-aec3-862fce30b314/w960.webp','/api/media/05aa36fa-818e-484e-8db6-2fbbb59fb66a','/api/media/05aa36fa-818e-484e-8db6-2fbbb59fb66a?variant=thumbnail','جهود الإنقاذ في كولومبيا تدخل مرحلتها الحرجة بعد زلزال راح ضحيته 250 شخصاً',960,540,'valid','published','archived','valid',55,'81321e68a3b619eb5e2d722c517527d830909694c567d8898c8c4e9ec889e443','fdaa799a412bf173656ff2168c47cdef2576ed1c64a9491cbafd99c382188092','محدّث','2026-08-13T13:02:30.487Z','2026-10-07T21:00:08.205Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس بلدية مدينة كالي أليخاندرو","السفر والسياحة"]','["رئيس بلدية مدينة كالي أليخاندرو","السفر والسياحة"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":4},{"category":"السياسة","score":1.5},{"category":"السفر","score":1.5}]','Active','2026-10-07T21:00:08.205Z',200,74,0,'source_article_available','',NULL,NULL,'body:2574dfc299df2ee451282e8f116a688c13462424c085de17e93fff7796cd0e94','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('184f5a24-6a68-4871-8356-119361d52f91','news-184f5a24-6a68-4871-8356-119361d52f91','الحوثيون يقصفون مدرسة ومسجداً في تعز خلال 24 ساعة.. تصعيد يهدد المدنيين','الحوثيون يقصفون مدرسه ومسجدا في تعز خلال 24 ساعه تصعيد يهدد المدنيين','صعّدت ميليشيا الحوثي هجماتها في مديرية موزع بالريف الغربي لمحافظة تعز، جنوب غرب اليمن، مستهدفةً منشآت مدنية للمرة الثانية خلال يومين متتاليين، في تصعيد يكشف عن استمرار انتهاك الجماعة لحرمة المرافق التعليمية والدينية.','["وأفادت مصادر محلية، نقلاً عن «العربية.نت»، بأن ميليشيا الحوثي قصفت الأربعاء مسجد «الجيل الجديد» في قرية المقصب بمنطقة العتقة التابعة لمديرية موزع، بعدد من قذائف الهاون، ما أسفر عن أضرار مادية في المسجد.","وجاء هذا القصف بعد أقل من 24 ساعة على استهداف مدرسة «الجيل الجديد» في المنطقة ذاتها بقذائف مماثلة، في هجوم يضع حياة الطلاب والمدنيين في دائرة الخطر المباشر.","ويُثير استهداف المدرسة ثم المسجد في غضون يومين تساؤلات جدية حول طبيعة الأهداف التي تنتقيها الميليشيا، لا سيما أن المنشآت التعليمية ودور العبادة تُصنَّف مرافق مدنية محمية بموجب القانون الدولي الإنساني.","ويأتي هذا التصعيد في وقت تشهد فيه جبهات تعز توتراً متواصلاً، بالتزامن مع تحركات عسكرية حوثية في عدد من مناطق التماس، مما يُعمّق المخاوف من اتساع دائرة المواجهة وعودة التصعيد إلى مستويات أشد خطورة."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7bukwqw','https://sabq.org/article/7bukwqw','','https://sabq.org/article/7bukwqw','صحيفة سبق','السعودية','2026-08-12T15:11:00.000Z','2026-08-12T18:12:00.000Z','2026-08-13T13:02:31.391Z','https://media.sabq.org/news/2026/08/b4eccf09-de68-4db4-9fbc-fe6bf669e25e/w801.webp','/api/media/184f5a24-6a68-4871-8356-119361d52f91','/api/media/184f5a24-6a68-4871-8356-119361d52f91?variant=thumbnail','الحوثيون يقصفون مدرسة ومسجداً في تعز خلال 24 ساعة.. تصعيد يهدد المدنيين',801,451,'valid','published','archived','valid',58,'fed79fe9e0ada5deed5b55bc9d687d6f0bee6be968158659173e22a1a284ae14','348e0fe000f9c9cf5e6e3f2afd0b4d23692d7deee07772411ec9ad7a0031c5ec','محدّث','2026-08-13T13:02:31.391Z','2026-10-07T20:59:39.795Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","التعليم والتدريب"]','["السفر والسياحة","التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"الصحة","score":1.5},{"category":"السفر","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:59:39.795Z',200,76,0,'source_article_available','',NULL,NULL,'body:401d3c550b98bef381e2bc7ab933326bf5328d851f7aa916c63913d1ef3a5c47','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7a753f94-592f-4e4c-9e44-3f443d3d85bc','news-7a753f94-592f-4e4c-9e44-3f443d3d85bc','حتى 30 أكتوبر.. «التجارة» تعلن أكثر من مليون منتج مخفّض ضمن تخفيضات 2026','حتي 30 اكتوبر التجاره تعلن اكثر من مليون منتج مخفض ضمن تخفيضات 2026','أعلنت وزارة التجارة عن طرح أكثر من مليون منتج مخفّض لدى المنشآت التجارية والمتاجر الإلكترونية ضمن «تخفيضات 2026م»، التي بدأت مطلع أغسطس الجاري وتستمر حتى 30 أكتوبر 2026م.','["وتشمل التخفيضات المنشآت التجارية والمتاجر الإلكترونية، فيما تواصل الوزارة أعمال الرقابة للتحقق من التزام المنشآت بضوابط التخفيضات واشتراطاتها.","وأوضحت الوزارة أن التقديم على رخص التخفيضات متاح إلكترونيًا للمنشآت والمتاجر، من خلال المنصة المخصصة لذلك عبر: https://sales.mc.gov.sa/home .","ودعت الوزارة المنشآت التجارية إلى الاستفادة من «المدة الاستثنائية للتخفيضات»، التي تتيح إجراء التخفيضات لمدة ثلاثة أشهر دون فقدان أيام من الرصيد السنوي المخصص لتخفيضات المنشأة التجارية."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/q4y0to66p','https://ajel.sa/economy/q4y0to66p','https://ajel.sa/economy/q4y0to66p','https://ajel.sa/economy/q4y0to66p','فريق التحرير','السعودية','2026-08-13T07:22:00.000Z','Wed, 07 Oct 2026 20:58:58 GMT','2026-08-13T15:03:52.895Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%88%D8%B2%D8%A7%D8%B1%D8%A9-%D8%A7%D9%84%D8%AA%D8%AC%D8%A7%D8%B1%D8%A9-6T-HfTKf.jpg','/api/media/7a753f94-592f-4e4c-9e44-3f443d3d85bc','/api/media/7a753f94-592f-4e4c-9e44-3f443d3d85bc?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',46,'768143b079e4eb22f271ca6774812691b61dbcb6c11476678bc7731a61e50dcc','ac16994e030443b0d4b22bd1976c8abd7f34e16fd0ff404dacbc6555e2863a93',NULL,'2026-08-13T15:03:52.895Z','2026-10-07T20:59:00.613Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Updated','2026-10-07T20:59:00.613Z',200,84,0,'source_content_changed','',NULL,NULL,'body:288d76095b38548c5060235e6ba400f5c1ba4640db2d9719587e086e6efd1c07','Wed, 07 Oct 2026 20:58:58 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('49ac65bc-e2e1-4782-bd93-025d7d83cc9a','news-49ac65bc-e2e1-4782-bd93-025d7d83cc9a','اقتصادي / الباحة.. 140 ألف نخلة تنتج أكثر من ألفي طن من التمور سنويًا','اقتصادي الباحه 140 الف نخله تنتج اكثر من الفي طن من التمور سنويا','الباحة 30 صفر 1448 هـ الموافق 13 أغسطس 2026 م واس تُعد زراعة النخيل في منطقة الباحة نشاطًا زراعيًا حيويًا؛ لما تحمله من قيمة اقتصادية وغذائية كبيرة، وما توفره من فرص واعدة لتنمية المنتجات الزراعية والصناعات التحويلية المرتبطة بالتمور، لا سيما في محافظة العقيق التي تُعد من أبرز المواقع الملائمة لزراعة النخيل في المنطقة.','["وتشتهر مزارع النخيل في الباحة بإنتاج أصناف متنوعة من التمور، من أبرزها: الصفري، والخلاص، والسكري، والبرحي، وهي أصناف تختلف في مواسم نضجها وخصائصها، مما يتيح للمزارعين تنويع الإنتاج وتلبية احتياجات الأسواق المحلية.","وفي هذا السياق، أوضح مدير إدارة القطاع غير الربحي والحلول الزراعية بفرع وزارة البيئة والمياه والزراعة بمنطقة الباحة المهندس سعيد بن مسفر الغامدي، أن الإحصاءات تشير إلى وجود أكثر من (140) ألف نخلة في المنطقة، تنتج سنويًا ما يزيد على ألفي طن من التمور، مؤكدًا أهمية هذا النشاط في دعم القطاع الزراعي وتمكين المزارعين من الاستفادة المثلى من الموارد والمقومات المتاحة.","وبيّن أن زراعة النخيل تتركز بشكل أكبر في المواقع ذات الظروف البيئية والزراعية الملائمة، وفي مقدمتها محافظة العقيق، التي أسهمت طبيعتها في التوسع في زراعة النخيل وإنتاج أصناف متعددة، إذ يعمل الفرع على خدمة مزارعي النخيل في مختلف محافظات المنطقة من خلال تنفيذ برامج إرشادية، وورش عمل متخصصة، وزيارات ميدانية للمزارع؛ بهدف رفع مستوى وعي المزارعين بأفضل الممارسات الزراعية، وتعزيز كفاءة عمليات الزراعة، والري، والتسميد،…","كما أفاد المهندس الغامدي بأن هذه الجهود تستهدف تطوير الإنتاج وتحسين جودته، والحد من الفاقد الزراعي، ورفع كفاءة المزارع؛ بما يسهم في زيادة العائد الاقتصادي للمزارعين، وتعزيز قدرة المنتجات المحلية على المنافسة والوصول إلى المستهلك بجودة عالية، مضيفًا أن البرامج الإرشادية تتضمن تعريف مزارعي النخيل بمسارات الدعم والخدمات المقدمة، وفي مقدمتها برنامج الزراعة العضوية، الذي يشجع المزارعين على تبني الممارسات العضوية وتطبيق…"]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2652993?type=news&uuid=N2652993','https://spa.gov.sa/ar/N2652993?type=news&uuid=N2652993','N2652993','N2652993','','السعودية','2026-08-13T07:23:00.000Z','2026-06-24T05:03:00.000Z','2026-08-13T15:04:16.471Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10602410.jpeg','/api/media/49ac65bc-e2e1-4782-bd93-025d7d83cc9a','/api/media/49ac65bc-e2e1-4782-bd93-025d7d83cc9a?variant=thumbnail','اقتصادي / الباحة.. 140 ألف نخلة تنتج أكثر من ألفي طن من التمور سنويًا',1600,1200,'valid','published','archived','valid',85,'f9b4aff8d1a3108b6f280b3d5312a9dcf08738af676eae9e81f7c153d4a69e45','0ad5a6fb7d23a58447e740dce83a7f192d794b95cc15a6783bce92ba041448ee',NULL,'2026-08-13T15:04:16.471Z','2026-10-07T20:59:47.446Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البيئة والمياه والزراعة بمنطقة","السفر والسياحة","الاقتصاد والأسواق","الباحة"]','["وزارة البيئة والمياه والزراعة بمنطقة","السفر والسياحة","الاقتصاد والأسواق"]','classified','','[{"category":"الاقتصاد","score":4.5},{"category":"الصحة","score":1.5},{"category":"التقنية","score":1.5}]','Active','2026-10-07T20:59:47.446Z',200,83,0,'source_article_available','',NULL,NULL,'body:ef8ba6763d9bec824da8c5bf706769d63a9888107005fe392ed85fdd985f7e64','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6b113bb5-9637-4979-a294-cc0eadeb411a','news-6b113bb5-9637-4979-a294-cc0eadeb411a','الذهب يلامس أعلى مستوى في شهرين متجاوزاً 4433 دولاراً','الذهب يلامس اعلي مستوي في شهرين متجاوزا 4433 دولارا','سجّل الذهب اليوم الخميس أعلى مستوياته منذ أكثر من شهرين، إذ ارتفع في المعاملات الفورية بنسبة 0.6% ليصل إلى 4433.62 دولاراً للأونصة بحلول الساعة 01:08 بتوقيت غرينتش، بعد أن قفز بنحو 1% في وقت سابق من الجلسة إلى أعلى مستوى له منذ الخامس من يونيو الماضي.','["وعلى صعيد العقود الآجلة، صعدت العقود الأمريكية للذهب تسليم ديسمبر بنسبة 0.6% لتبلغ 4493 دولاراً للأونصة.","وفي سياق ارتفاع المعادن النفيسة، قفزت الفضة في المعاملات الفورية بنحو 1% لتصل إلى 65.91 دولاراً للأوقية، وذلك عقب تسجيلها في الجلسة السابقة أعلى مستوى لها منذ 22 يونيو.","كما ارتفع البلاتين بنسبة 0.3% ليبلغ 1762.70 دولاراً، فيما زاد البلاديوم بنسبة 0.1% ليصل إلى 1371.20 دولاراً للأونصة."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/zb0VIuR','https://sabq.org/article/zb0VIuR','','https://sabq.org/article/zb0VIuR','صحيفة سبق','السعودية','2026-08-12T22:26:00.000Z','2026-08-13T02:20:00.000Z','2026-08-13T15:08:37.348Z','https://media.sabq.org/news/2026/08/5b16a01a-10ae-49bb-b453-2aeb2c4e7813/w1280.webp','/api/media/6b113bb5-9637-4979-a294-cc0eadeb411a','/api/media/6b113bb5-9637-4979-a294-cc0eadeb411a?variant=thumbnail','الذهب يلامس أعلى مستوى في شهرين متجاوزاً 4433 دولاراً',1280,911,'valid','published','archived','valid',47,'42d3d9fbfa4fb26a50b1ffac3c693f162b8d826de506182d9c1dc8ecb449dabe','2717d2a3dd3a9e4d51da59d0c7b92b6fbdca870b107ad8dd0c7d1f0fa60fa377','محدّث','2026-08-13T15:08:37.348Z','2026-10-07T20:59:01.215Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:59:01.215Z',200,71,0,'source_article_available','',NULL,NULL,'body:933dbe62902bff6ce300c5d83fa0be36daddbf4909045dffd219b6e5ae65e0c8','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4a07c64a-e18d-4c78-bceb-65d7eb8a600f','news-4a07c64a-e18d-4c78-bceb-65d7eb8a600f','الكفاح والإرادة الصادقة قادران على أن يهزما أيَّ ظروفٍ','الكفاح والاراده الصادقه قادران علي ان يهزما اي ظروف','كانت طفولتها مختلفة عن كثير من الأطفال، فقد حملتها الحياة مبكرًا إلى دروب المسؤولية والتحدي.','["كانت تسكنها رغبة عارمة تفوق سنواتها الغضة؛ رغبة في العلم، وشغف يمتد بها نحو آفاق القراءة والدراسة.","ولأن الشغف صادق، فقد احتضنت والدتها الراحلة هذا الطموح المبكر، وألحقتها بالمدرسة المسائية، لتكون تلك الخطوة بداية رحلتها الفريدة.","كانت حينها في العاشرة من عمرها حين اعتادت الذهاب وحدها إلى مدرستها المسائية، في وقت الظهيرة تحديدًا، حين تستسلم المدن للصمت وتغفو البيوت خلف أبوابها الموصدة.","كانت الشوارع خالية تمامًا من المارة، والطرقات ساكنة إلا من حرارة الشمس التي تلتهم الأرصفة، بينما كانت تلك الصغيرة تسير بخطوات متعبة وحقيبة العلم على كتفها، مؤمنة في أعماقها بأن المعرفة تستحق كل هذا العناء."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/88n44vd','https://sabq.org/article/88n44vd','','https://sabq.org/article/88n44vd','فوزية الشيخي','السعودية','2026-08-12T21:00:00.000Z','2026-08-13T00:00:00.000Z','2026-08-13T15:08:38.162Z','https://media.sabq.org/news/2026/08/5b54e963-2d50-42c7-b537-98b7a3c5c5d1/w1600.webp','/api/media/4a07c64a-e18d-4c78-bceb-65d7eb8a600f','/api/media/4a07c64a-e18d-4c78-bceb-65d7eb8a600f?variant=thumbnail','الكفاح والإرادة الصادقة قادران على أن يهزما أيَّ ظروفٍ',1600,893,'valid','published','archived','valid',40,'3ee71d9286959222e145014c5f35c85ffd190425ca9d9a8e5d5844f7e8071b25','509ef5071211fc41f421b8b4368ddc02e850dc6c01284aa837ccab627a5be52f','محدّث','2026-08-13T15:08:38.162Z','2026-10-07T20:59:01.211Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","التعليم والتدريب"]','["الطقس والمناخ","التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"البيئة والمناخ","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:59:01.211Z',200,73,0,'source_article_available','',NULL,NULL,'body:9f449a2c9a9c37ad1a8e7f12c0f2dbc9a130f6a7a44a2818d51cf33feec19440','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f61e1691-43d1-4eed-b1f2-e14854aa0a34','news-f61e1691-43d1-4eed-b1f2-e14854aa0a34','"الأرصاد" يحذر من حرارة تبلغ 48 درجة وأمطار رعدية ورياح وأتربة تضرب عدة مناطق','الارصاد يحذر من حراره تبلغ 48 درجه وامطار رعديه ورياح واتربه تضرب عده مناطق','توقّع المركز الوطني للأرصاد أن يستمر الطقس اليوم الخميس حارًا إلى شديد الحرارة على أجزاء من مناطق الشرقية والرياض والمدينة المنورة ومكة المكرمة، مع نشاط الرياح المثيرة للأتربة والغبار على أجزاء من مكة المكرمة والمدينة المنورة وجدة.','["وأوضح المركز أن الفرصة قائمة لهطول أمطار رعدية متوسطة إلى غزيرة مصحوبة برياح نشطة وأتربة مثارة على أجزاء من مناطق عسير وجازان والباحة، مع احتمالية تأثر أجزاء من مكة المكرمة والمدينة المنورة بالسحب الرعدية والرياح النشطة.","الدمام تُسجّل 48 درجة تتراوح درجات الحرارة العظمى المتوقعة في المدن المشمولة بالنشرة بين 30 و48 درجة مئوية ، فيما تتراوح الصغرى بين 19 و34 درجة ، مع تفاوت ملحوظ في نسب الرطوبة والظواهر الجوية من منطقة إلى أخرى.","وتُسجّل الدمام أعلى درجة حرارة متوقعة بـ48 درجة مئوية ، تليها الرياض ومكة المكرمة والمدينة المنورة بـ46 درجة، ثم بريدة بـ45 درجة.","وجاءت أبرز التوقعات للمدن الرئيسية على النحو الآتي: • الرياض: عظمى 46° وصغرى 32°، رطوبة 30%، غائم جزئي. • مكة المكرمة: عظمى 46° وصغرى 34°، رطوبة 50%، سحب رعدية ممطرة ورياح نشطة وأتربة مثارة. • المدينة المنورة: عظمى 46° وصغرى 34°، رطوبة 25%، غائم جزئي ورياح نشطة وأتربة مثارة. • جدة: عظمى 41° وصغرى 31°، رطوبة 65%، غائم جزئي ورياح نشطة وأتربة مثارة. • الدمام: عظمى 48° وصغرى 32°، رطوبة 80%، عوالق وغائم جزئي. • أبها:…"]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/vncgr6a','https://sabq.org/article/vncgr6a','','https://sabq.org/article/vncgr6a','صحيفة سبق','السعودية','2026-08-12T17:00:00.000Z','2026-08-12T20:00:00.000Z','2026-08-13T15:08:38.333Z','https://media.sabq.org/news/2026/08/c4381aed-4a3b-4f1f-9976-a879d6b37a7e/w1600.webp','/api/media/f61e1691-43d1-4eed-b1f2-e14854aa0a34','/api/media/f61e1691-43d1-4eed-b1f2-e14854aa0a34?variant=thumbnail','"الأرصاد" يحذر من حرارة تبلغ 48 درجة وأمطار رعدية ورياح وأتربة تضرب عدة مناطق',1600,893,'valid','published','archived','valid',99,'1e617057bf3f4c31ee9e1afbe37d18b7e4587dbc35928d0efd235a6f807c4da7','29cf43dcaba529b325a305afda15a073dd432093bc29aa17dd6d7a927256fef1','محدّث','2026-08-13T15:08:38.333Z','2026-10-07T20:59:41.343Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة","جدة","عسير","جازان","الرياض","الدمام","الباحة"]','["الطقس والمناخ","المدينة المنورة"]','classified','','[{"category":"البيئة والمناخ","score":12},{"category":"السفر","score":3},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:59:41.343Z',200,75,0,'source_article_available','',NULL,NULL,'body:1cb63c4e0557549fdfc482425d302f3974ff18c9c32545c10c96cf452ca88441','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('edb60b7b-a734-4d26-bd38-ecd5f1dd0ace','news-edb60b7b-a734-4d26-bd38-ecd5f1dd0ace','البنك الدولي يشيد بتجربة «سدايا».. نموذج سعودي لتكامل بيانات 60 جهة حكومية','البنك الدولي يشيد بتجربه سدايا نموذج سعودي لتكامل بيانات 60 جهه حكوميه','استشهد البنك الدولي بتجربة المملكة العربية السعودية ممثلةً في الهيئة السعودية للبيانات والذكاء الاصطناعي «سدايا»، عادّاً إياها نموذجاً يُحتذى به في بناء منظومة متكاملة للبيانات ودعم تكاملها بين الجهات الحكومية.','["جاء ذلك في تقرير التنمية في العالم 2026 الذي أصدرته مجموعة البنك الدولي تحت عنوان «وعد الذكاء الاصطناعي»، مشيراً إلى أن «سدايا» تتيح تكامل بيانات أكثر من 60 جهة حكومية مع إبقاء البيانات داخل أنظمتها، ووضع هذه التجربة ضمن النماذج الداعمة لتبادل البيانات بصورة منظمة بين الجهات الحكومية.","وتناول التقرير التجربة السعودية في المشهد العالمي للذكاء الاصطناعي، إذ صنّف المملكة ضمن أكبر 10 دول عالمياً في الاستثمار الخاص بالذكاء الاصطناعي، وأبرزها وجهةً جاذبة للكفاءات المتخصصة، في انعكاس لمسار وطني متكامل أسسته رؤية السعودية 2030 لبناء اقتصاد قائم على البيانات والحوسبة والابتكار.","وفي محور القدرات البشرية، أفاد التقرير بأن المملكة سجّلت عام 2025 حضوراً متقدماً في استقطاب الكفاءات المتخصصة، ضمن الاقتصادات التي سجّلت أعلى معدلات صافي تدفق للعاملين في الذكاء الاصطناعي لكل 10 آلاف عضو على منصة «لينكدإن»، كما بلغ صافي تدفق نخبة مواهب الذكاء الاصطناعي 3.08 في العام ذاته، بما يعكس جاذبية البيئة التقنية السعودية للخبرات النوعية.","ويتزامن نشر هذا التقرير مع تسمية عام 2026 «عام الذكاء الاصطناعي» في المملكة، الذي يُجسّد الاهتمام الوطني بتقنيات البيانات والذكاء الاصطناعي ودورها في دعم التنمية والابتكار وتعزيز التنافسية، تحقيقاً لمستهدفات رؤية السعودية 2030."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/srlqrkh','https://sabq.org/article/srlqrkh','','https://sabq.org/article/srlqrkh','صحيفة سبق','السعودية','2026-08-12T16:46:00.000Z','2026-08-12T19:48:00.000Z','2026-08-13T15:08:39.387Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/c248eebb-cb2d-46ee-d31d-f2eca4581300/public','/api/media/edb60b7b-a734-4d26-bd38-ecd5f1dd0ace','/api/media/edb60b7b-a734-4d26-bd38-ecd5f1dd0ace?variant=thumbnail','البنك الدولي يشيد بتجربة «سدايا».. نموذج سعودي لتكامل بيانات 60 جهة حكومية',535,332,'valid','published','archived','valid',88,'b33a3f601ab1f8613b5b2b9dc9ffdfc45d94b69595fc15e5ca74277a5488a8d0','1d069828e5424a0d050ae48432bd0ed65169425f6b444b2f26189e4ee3db5c34','محدّث','2026-08-13T15:08:39.387Z','2026-10-07T20:59:37.363Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"الذكاء الاصطناعي","score":6},{"category":"أخبار السعودية","score":3},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T20:59:37.363Z',200,74,0,'source_article_available','',NULL,NULL,'body:88aaf006bd48d8344e7bf0f07fde26ab16c2a6647dc5cc1a0163d9541fe49639','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('957a287d-2111-46cd-895e-cd7af03bf33b','news-957a287d-2111-46cd-895e-cd7af03bf33b','ابتلعت الشمس أمام أعينهم.. 10 صور مذهلة لكسوف حوّل النهار إلى مشهد من عالم آخر','ابتلعت الشمس امام اعينهم 10 صور مذهله لكسوف حول النهار الي مشهد من عالم اخر','حجب القمر الشمس تدريجيًا خلال الكسوف الذي شوهد في عدد من مناطق أوروبا ، ليتحول قرصها المضيء إلى هلال رفيع قبل أن يختفي خلف القمر وتظهر الهالة الشمسية حوله.','["وتابع آلاف الأشخاص الظاهرة من مدن ومواقع مفتوحة في إسبانيا و ألمانيا ومالطا وصربيا، بينما وثقت عدسات المصورين مراحل الكسوف ومشاهد المتابعين وهم يرفعون رؤوسهم وهواتفهم نحو السماء ليشاهدوا الظاهرة الفلكية الفريدة.","وفي هذا الألبوم، نستعرض 10 من أبرز الصور التي التقطتها \" رويترز\" للكسوف، من لحظة احتجاب الشمس بالكامل إلى مشاهد الغروب والظلال والتتابع البصري لمراحل الظاهرة."]','العالم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/5i99gmy','https://sabq.org/article/5i99gmy','','https://sabq.org/article/5i99gmy','ياسر نجدي','السعودية','2026-08-12T16:42:00.000Z','2026-08-13T01:27:00.000Z','2026-08-13T15:08:39.464Z','https://media.sabq.org/news/2026/08/dec0ab15-5406-44c2-9d7e-6c6570d981b3/w1600.webp','/api/media/957a287d-2111-46cd-895e-cd7af03bf33b','/api/media/957a287d-2111-46cd-895e-cd7af03bf33b?variant=thumbnail','ابتلعت الشمس أمام أعينهم.. 10 صور مذهلة لكسوف حوّل النهار إلى مشهد من عالم آخر',1600,1067,'valid','published','archived','valid',35,'3e8870adce3b5aad1a2e600dd305ff5c8063dd9339abcffd55ac295be1add09c','aba910dc60c437bdf12e9d1e0f882ec3f9497526d9df25f4431e20d6660de6ad','محدّث','2026-08-13T15:08:39.464Z','2026-10-07T20:59:58.851Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T20:59:58.851Z',200,76,0,'source_article_available','',NULL,NULL,'body:e572110e52929f726f510bcfa7fd1f062f5629bdf0c5d2519b2415b2ef693cd6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f351353d-fb12-4742-8063-e45f63e46d6e','news-f351353d-fb12-4742-8063-e45f63e46d6e','هجمات الحوثيين تعطل الإغاثة في الساحل الغربي لليمن وتهدد حياة المدنيين','هجمات الحوثيين تعطل الاغاثه في الساحل الغربي لليمن وتهدد حياه المدنيين','علّقت لجنة الإنقاذ الدولية عملياتها الميدانية وبرامجها الإنسانية في الساحل الغربي اليمني، إثر هجمات ميليشيا الحوثي المتكررة على مدينة المخا ومينائها، في تطور يُفاقم معاناة المدنيين ويهدد وصول المساعدات إلى المحتاجين.','["وأعلنت اللجنة (IRC) في بيان الأربعاء، أن الضربات الأخيرة التي استهدفت مناطق مأهولة في المخا ومحيطها أثارت مخاوف جدية من اتساع نطاق الصراع، وتعريض حياة المدنيين والعاملين في المجال الإنساني للخطر، مما دفعها إلى تعليق عملياتها وتقييد حركة موظفيها مؤقتاً في المنطقة.","وحذّرت اللجنة من أن هذا القرار سيُعطّل تنفيذ برامج الإغاثة ويحدّ من قدرتها على الوصول إلى المجتمعات المحتاجة، مشيرةً إلى أن خدمات الصحة والحماية الأساسية ستستمر عبر العيادات التي تدعمها في المنطقة.","وأكدت اللجنة أن التصعيد الحوثي في المخا يندرج ضمن نمط أوسع من التوتر المتصاعد في اليمن، محذّرةً من أن استمرار الهجمات قد يُقوّض الهدنة الهشة ويهدد بانهيار منظومة المساعدات الإنسانية التي يعتمد عليها ملايين اليمنيين.","وطالبت اللجنة بضمان حماية المدنيين والعاملين في الإغاثة، وكفالة وصول المساعدات بصورة آمنة ودون عوائق، داعيةً المجتمع الدولي والمانحين إلى التحرك العاجل لتوفير التمويل اللازم والخدمات الأساسية للمتضررين."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/14c54sp','https://sabq.org/article/14c54sp','','https://sabq.org/article/14c54sp','صحيفة سبق','السعودية','2026-08-12T16:56:00.000Z','2026-08-12T19:56:00.000Z','2026-08-13T15:08:39.476Z','https://media.sabq.org/news/2026/08/7881cc77-192c-47c5-86fa-3dd0607f7fd6/w801.webp','/api/media/f351353d-fb12-4742-8063-e45f63e46d6e','/api/media/f351353d-fb12-4742-8063-e45f63e46d6e?variant=thumbnail','هجمات الحوثيين تعطل الإغاثة في الساحل الغربي لليمن وتهدد حياة المدنيين',801,451,'valid','published','archived','valid',41,'c9e7cf97d61912346d25f3f13b3eacf7186bfe79f688bf8aeeaedbea69fd4509','770f2df36fae2cc40ded0d48d4c9d106cbb9668c48071600e6283912a4311056','محدّث','2026-08-13T15:08:39.476Z','2026-10-07T20:59:06.671Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","اليمن"]','["الصحة العامة"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:59:06.671Z',200,75,0,'source_article_available','',NULL,NULL,'body:046888568fe624d525fe7a02c9762967034b16b07c72dee8a08dca27d3c7b8c6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5f3f850e-0985-465f-8e80-01da5e9851d8','news-5f3f850e-0985-465f-8e80-01da5e9851d8','"ترامب" يعلن مغادرة "ليفيت" منصب المتحدثة باسم البيت الأبيض نهاية أغسطس','ترامب يعلن مغادره ليفيت منصب المتحدثه باسم البيت الابيض نهايه اغسطس','أعلن الرئيس الأمريكي دونالد ترامب أن المتحدثة باسم البيت الأبيض كارولين ليفيت ستغادر منصبها في نهاية أغسطس الجاري، مشيراً إلى أن قرارها جاء رغبةً منها في تخصيص مزيد من الوقت لأطفالها وعائلتها.','["وكتب ترامب عبر منصة «تروث سوشيال»: «ستغادر متحدثتنا الرائعة باسم البيت الأبيض وإحدى أكثر مساعديّ موثوقية، كارولين ليفيت، منصبها في نهاية الشهر، لتقضي مزيداً من الوقت مع أطفالها الصغار الرائعين وعائلتها.","وتُعدّ ليفيت البالغة من العمر 28 عاماً الأصغر في تاريخ الولايات المتحدة التي تتولى منصب المتحدث باسم البيت الأبيض.","وتأتي مغادرتها بعد نحو 4 أشهر من إنجابها طفلتها الثانية «فيفي» في مايو الماضي، إذ صرّحت بأنها وجدت صعوبة بالغة في التوفيق بين متطلبات منصبها الضخمة وواجباتها كأم لطفلين.","وأوضح ترامب أن ليفيت لن تبتعد كلياً عن المشهد السياسي، بل ستنتقل إلى دور مستشارة خارجية بارزة له، وصوت مؤثر داخل الحزب الجمهوري لدعمه في انتخابات التجديد النصفي للكونغرس المقررة في نوفمبر المقبل."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/uzbq873','https://sabq.org/article/uzbq873','','https://sabq.org/article/uzbq873','صحيفة سبق','السعودية','2026-08-12T16:20:00.000Z','2026-08-12T19:20:00.000Z','2026-08-13T15:08:40.635Z','https://media.sabq.org/news/2026/08/afa50a3d-6f4e-4265-b5f2-98aa157fe3ce/w846.webp','/api/media/5f3f850e-0985-465f-8e80-01da5e9851d8','/api/media/5f3f850e-0985-465f-8e80-01da5e9851d8?variant=thumbnail','"ترامب" يعلن مغادرة "ليفيت" منصب المتحدثة باسم البيت الأبيض نهاية أغسطس',846,551,'valid','published','archived','valid',50,'20b113b93763c128f2d566571a183f16181ef06104bd71cf72df410aaf3772f2','7cda703e848d56a247b1009b71b5c59746ba1a28eec16ce82928105aef1295a5','محدّث','2026-08-13T15:08:40.635Z','2026-10-07T20:59:38.551Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السياسة والعلاقات الدولية","الولايات المتحدة"]','["السياسة والعلاقات الدولية","الولايات المتحدة"]','manual_approved','below_category_threshold','[{"category":"العالم","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:59:38.551Z',200,76,0,'source_article_available','',NULL,NULL,'body:1a65e210cdd6e841c51ad6e2c9531cf9ed1be754051418a726a12932191134f7','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c65ae4f0-a2cc-4cef-85e5-9250edc7da91','news-c65ae4f0-a2cc-4cef-85e5-9250edc7da91','5 سنوات على حكم طالبان.. 2.4 مليون فتاة أفغانية لا تزال محرومة من التعليم','5 سنوات علي حكم طالبان 2 4 مليون فتاه افغانيه لا تزال محرومه من التعليم','لا تزال نحو 2.4 مليون فتاة أفغانية محرومة من التعليم الثانوي، بعد خمس سنوات من عودة حركة طالبان إلى السلطة في أفغانستان، في تراجع حاد عن المكاسب التعليمية التي تحققت للنساء والفتيات خلال العقدين السابقين.','["وقالت منظمة الأمم المتحدة للتربية والعلم والثقافة «اليونسكو» إن أفغانستان باتت الدولة الوحيدة في العالم التي تفرض رسمياً حظراً على تعليم الفتيات والنساء بعد المرحلة الابتدائية، مجددةً دعوتها إلى إعادة حقهن في التعليم «فوراً ودون شروط».","وحذرت المنظمة من أن تداعيات سياسات طالبان تجاوزت حدود المدارس، في ظل القيود المفروضة على عمل النساء في معظم الوظائف والمهن التي تتطلب الظهور في المجال العام، فضلاً عن القيود المفروضة على سفرهن دون مرافقة رجل من أقاربهن.","وجاء في بيان اليونسكو أن «النساء مُحيت أدوارهن من الحياة العامة، ومع نشوء جيل جديد من الفتيات من دون تعليم، يصبح مستقبلهن أكثر قتامة على نحو متزايد».","توسع القيود لتشمل الجامعات والعمل عادت طالبان إلى السلطة في 15 أغسطس 2021، بالتزامن مع انسحاب القوات الأمريكية وقوات حلف شمال الأطلسي «الناتو» من أفغانستان، بعد نحو عقدين من الحرب."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/sg4bpgo','https://sabq.org/article/sg4bpgo','','https://sabq.org/article/sg4bpgo','صحيفة سبق','السعودية','2026-08-12T16:41:00.000Z','2026-08-12T19:44:00.000Z','2026-08-13T15:08:40.672Z','https://media.sabq.org/news/2026/08/63b02b3e-9cd0-4db1-8c3e-e979aa03cd0f/w801.webp','/api/media/c65ae4f0-a2cc-4cef-85e5-9250edc7da91','/api/media/c65ae4f0-a2cc-4cef-85e5-9250edc7da91?variant=thumbnail','5 سنوات على حكم طالبان.. 2.4 مليون فتاة أفغانية لا تزال محرومة من التعليم',801,451,'valid','published','archived','valid',46,'dce5839e4f1f8822c95a3e2f6f37ef96f9c23aebe2cd760bc59a8099b652041f','c9d9f631e31d3dc6c6136c382d8a2e467345b8abb37e0ee148ba854942002608','محدّث','2026-08-13T15:08:40.672Z','2026-10-07T20:59:59.503Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الأمم المتحدة للتربية والعلم والثقافة","السفر والسياحة","الثقافة والفنون","التعليم والتدريب"]','["الأمم المتحدة للتربية والعلم والثقافة","السفر والسياحة","الثقافة والفنون","التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"التعليم","score":3},{"category":"السفر","score":1.5},{"category":"الثقافة","score":1.5}]','Active','2026-10-07T20:59:59.503Z',200,74,0,'source_article_available','',NULL,NULL,'body:2fcef5606d2c2a852aea6e752f050c3dada2fb7860be7d0ff71d8c1149609000','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c92a465f-0e92-41e0-8d96-b2a6008db4e4','news-c92a465f-0e92-41e0-8d96-b2a6008db4e4','ما الأطعمة التي ينبغي تجنبها بعد الأربعين؟.. خبيرة تكشف قائمة غذائية','ما الاطعمه التي ينبغي تجنبها بعد الاربعين خبيره تكشف قائمه غذائيه','حذّرت خبيرة التغذية الدكتورة ماريات موخينا من أن الجسم يشهد بعد سن الأربعين تغيرات جوهرية تستدعي مراجعة النظام الغذائي، مشيرةً إلى أن التمثيل الغذائي يتباطأ في هذه المرحلة، ويرتفع خطر الإصابة بأمراض القلب والأوعية الدموية نتيجة التغيرات في استقلاب الكوليسترول.','["وأوضحت الخبيرة أن عظام النساء تبدأ بالضعف بعد هذا السن، مؤكدةً أن اتباع نظام غذائي سليم يُعدّ من أفضل السبل للحفاظ على الصحة وتحسين الحالة الجسدية العامة.","السكريات والكربوهيدرات السريعة أشارت الدكتورة موخينا إلى أن الخطوة الأولى بعد سن الأربعين تتمثل في التخلي عن المشروبات المحلاة والسكريات الموجودة في الحلويات، لافتةً إلى ضرورة ألا تتجاوز الكربوهيدرات السريعة 30 إلى 40 غراماً يومياً، أي ما يعادل كمية الكربوهيدرات الموجودة في الفاكهة.","ونصحت بتجنب الخبز الأبيض الذي يتحول بسرعة إلى غلوكوز في الجسم، مقترحةً استبداله بخبز الحبوب الكاملة بوصفه خياراً أكثر صحةً في هذه المرحلة.","الدهون المتحولة والأطعمة المصنعة أكدت الخبيرة ضرورة تجنب الأطعمة التي تحتوي على الدهون المتحولة تماماً، وفي مقدمتها المخبوزات الصناعية ورقائق البطاطس وسائر الأطعمة المصنعة، محذّرةً من احتوائها على مواد ضارة قد تُضعف منظومة المناعة التي تصبح أقل قدرةً على اكتشاف الخلايا غير الطبيعية بعد هذا السن."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/vss4a0e','https://sabq.org/article/vss4a0e','','https://sabq.org/article/vss4a0e','صحيفة سبق','السعودية','2026-08-12T16:30:00.000Z','2026-08-12T19:30:00.000Z','2026-08-13T15:08:41.040Z','https://media.sabq.org/news/2026/08/8f50dbf2-ecf0-4864-afff-247dd3cbc2b9/w846.webp','/api/media/c92a465f-0e92-41e0-8d96-b2a6008db4e4','/api/media/c92a465f-0e92-41e0-8d96-b2a6008db4e4?variant=thumbnail','ما الأطعمة التي ينبغي تجنبها بعد الأربعين؟.. خبيرة تكشف قائمة غذائية',846,551,'valid','published','archived','valid',77,'89aee3a67a4f57a9c088c59d47c77609fcaa35ea443411e98e615c16ece5f1a1','6ea9d8979df7618146b8634953f2a75b6a3ba8b8204856ef573c49fb9f13df1e','محدّث','2026-08-13T15:08:41.040Z','2026-10-07T20:59:58.864Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة"]','["الصحة العامة"]','manual_approved','','[]','Active','2026-10-07T20:59:58.864Z',200,76,0,'source_article_available','',NULL,NULL,'body:90b5fcbeef0eb5b8c62440059330fb256ed3d575dfa60755a9af917505bf27cc','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6e9b6bcd-c784-4a9d-a2ae-f4107b301aee','news-6e9b6bcd-c784-4a9d-a2ae-f4107b301aee','«الأرصاد» يحذّر من موجة حارة تبلغ 50 درجة مئوية على المنطقة الشرقية','الارصاد يحذر من موجه حاره تبلغ 50 درجه مئويه علي المنطقه الشرقيه','حذّر المركز الوطني للأرصاد اليوم من موجة حارة تصل درجات حرارتها إلى (49 - 50) درجة مئوية، يصاحبها هبوب رياح نشطة مثيرة للأتربة، تطال مناطق واسعة من المنطقة الشرقية.','["وتشمل الموجة الحارة مدينتَي الدمام والظهران، فضلاً عن محافظات: حفر الباطن، والخفجي، والنعيرية، وقرية العليا، والجبيل، ورأس تنورة، والقطيف، والخبر، وبقيق، والعديد، وذعبلوتن، والأحساء، والهجر والمراكز التابعة لها.","وأوضح المركز أن هذه الحالة الجوية تستمر حتى الساعة الخامسة مساءً."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/iz6xqp3','https://sabq.org/article/iz6xqp3','','https://sabq.org/article/iz6xqp3','صحيفة سبق','السعودية','2026-08-12T23:51:00.000Z','2026-08-13T02:52:00.000Z','2026-08-13T17:14:30.651Z','https://media.sabq.org/news/2026/08/237c9882-a8e3-48cd-ba74-326cd7476e5d/w640.webp','/api/media/6e9b6bcd-c784-4a9d-a2ae-f4107b301aee','/api/media/6e9b6bcd-c784-4a9d-a2ae-f4107b301aee?variant=thumbnail','«الأرصاد» يحذّر من موجة حارة تبلغ 50 درجة مئوية على المنطقة الشرقية',640,376,'valid','published','archived','valid',41,'7f2d5c0ffd4bc36d2b5cbdbfefc95d9503f6275fc542774ab4860145f1a5392d','2011fbe352f5cb04701b282cf8650ebb7bb1360972d3b9bdcca0ca9474d4b80e','محدّث','2026-08-13T17:14:30.651Z','2026-10-07T20:59:02.228Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الدمام"]','[]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T20:59:02.228Z',200,78,0,'source_article_available','',NULL,NULL,'body:40e24510622692edbba9c3180eff6d0f6f437dedd0aa4ea700d97b7d677f8147','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('32977c92-26d6-446e-86ba-5d87deb49f2f','news-32977c92-26d6-446e-86ba-5d87deb49f2f','ثوران «إتنا» يمدد إغلاق مطار كاتانيا ويشل حركة الطيران في صقلية','ثوران اتنا يمدد اغلاق مطار كاتانيا ويشل حركه الطيران في صقليه','مددت السلطات الإيطالية إغلاق مطار «كاتانيا» في جزيرة صقلية حتى الساعة الثانية من فجر الجمعة (00:00 بتوقيت غرينتش)، وذلك بسبب استمرار النشاط البركاني لجبل «إتنا» وتصاعد سحب الرماد الكثيفة، مما تسبب في اضطراب واسع بحركة الطيران وتأثر آلاف المسافرين خلال ذروة موسم العطلات الصيفية.','["وأعلن مشغّل المطار تمديد الإغلاق بعدما كان مقرراً استمرار تعليق الرحلات حتى الساعة الرابعة من مساء اليوم، فيما لم تستبعد السلطات تمديد فترة الإغلاق مجدداً في حال استمرار النشاط البركاني والظروف المؤثرة على سلامة الملاحة الجوية.","وامتدت تداعيات ثوران «إتنا»، الذي يُعد أكثر البراكين نشاطاً في أوروبا، إلى مالطا الواقعة جنوب صقلية، حيث أُلغيت عدد من الرحلات الجوية نتيجة انتشار سحب الرماد البركاني في الأجواء المحيطة.","وأوضح المعهد الوطني الإيطالي للجيوفيزياء وعلم البراكين أن «إتنا» يواصل منذ الجمعة الماضي قذف كميات كبيرة من الرماد وشظايا الصخور المتوهجة، إلى جانب تدفق الحمم البركانية من فتحتين تقعان على ارتفاعَي 2360 و2750 متراً."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/yZMcynF','https://sabq.org/article/yZMcynF','','https://sabq.org/article/yZMcynF','صحيفة سبق','السعودية','2026-08-12T23:49:00.000Z','2026-08-13T02:50:00.000Z','2026-08-13T17:14:31.806Z','https://media.sabq.org/news/2026/08/7487a9c3-7d4d-47d1-ac07-c545c36907c5/w603.webp','/api/media/32977c92-26d6-446e-86ba-5d87deb49f2f','/api/media/32977c92-26d6-446e-86ba-5d87deb49f2f?variant=thumbnail','ثوران «إتنا» يمدد إغلاق مطار كاتانيا ويشل حركة الطيران في صقلية',603,331,'valid','published','archived','valid',58,'d43525a8d38e599eab6c10bd59ff42705894f2b111f671363e5a19885374bf27','a509e521051de965fc11e6174e5247f2e664859f02afbf11e9567fbb9871f54a','محدّث','2026-08-13T17:14:31.806Z','2026-10-07T20:58:59.246Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","أوروبا"]','["السفر والسياحة"]','manual_approved','below_category_threshold','[{"category":"العالم","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:58:59.246Z',200,76,0,'source_article_available','',NULL,NULL,'body:f188c6f65198ac9bf74add5b89fa5d70bbf3966ecaabab1c25ea220a52428330','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fa20724b-591b-41d6-92d9-f4a2bb0c6c1d','news-fa20724b-591b-41d6-92d9-f4a2bb0c6c1d','«المرور» يحذر من عبور الأودية أثناء جريانها بغرامة تصل إلى 10 آلاف ريال','المرور يحذر من عبور الاوديه اثناء جريانها بغرامه تصل الي 10 الاف ريال','حذّرت الإدارة العامة للمرور قائدي المركبات من المجازفة بعبور الأودية والشعاب أثناء جريانها، مؤكدةً أن هذا السلوك يُعد تهوراً يعرّض حياة السائق ومرافقيه للخطر.','["وأوضح المرور أن عبور الأودية والشعاب أثناء جريانها يُصنَّف مخالفةً مرورية صريحة، تتراوح غرامتها المالية بين 5 آلاف ريال و10 آلاف ريال وفق ملابسات المخالفة.","ودعت الإدارة العامة للمرور جميع مستخدمي الطريق إلى الالتزام التام بتعليمات السلامة المرورية، وتجنب الاقتراب من المواقع التي تشهد تجمعات مائية أو جريان السيول، حفاظاً على الأرواح وصوناً لسلامة مستخدمي الطريق."]','السيارات','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/uWGeLQG','https://sabq.org/article/uWGeLQG','','https://sabq.org/article/uWGeLQG','صحيفة سبق','السعودية','2026-08-12T23:26:00.000Z','2026-08-13T02:28:00.000Z','2026-08-13T17:14:32.621Z','https://media.sabq.org/news/2026/08/9a1233b4-9a79-452a-874e-5f33e11f340d/w1600.webp','/api/media/fa20724b-591b-41d6-92d9-f4a2bb0c6c1d','/api/media/fa20724b-591b-41d6-92d9-f4a2bb0c6c1d?variant=thumbnail','«المرور» يحذر من عبور الأودية أثناء جريانها بغرامة تصل إلى 10 آلاف ريال',1600,1600,'valid','published','archived','valid',48,'02432f1fb6ca1db72bb1e7dddf820811149350000d066b7a79a002d9a53a0d38','b079a19e0d4d5728ba222373dfd6aa8c6106d78da1565b100797774ecf237309','محدّث','2026-08-13T17:14:32.621Z','2026-10-07T20:58:48.691Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":3},{"category":"المجتمع","score":3},{"category":"التعليم","score":1.5}]','Active','2026-10-07T20:58:48.691Z',200,82,0,'source_article_available','',NULL,NULL,'body:56b8a920d12fe804ae7fc06bf8a667f97d606fc8d6186cae3a3a1aefbc8759a2','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6d12d381-aebe-4cfd-bf73-3321c1c92436','news-6d12d381-aebe-4cfd-bf73-3321c1c92436','عندما يتحول نقد الآخرين إلى أسلوب حياة !!','عندما يتحول نقد الاخرين الي اسلوب حياه','يُحكى في الأثر الشعبي أن رجلاً وابنه كانا يسافران بالدابة ، فكلما اتخذا وضعاً في الركوب أو المشي ، انهالت عليهما انتقادات العابرين ، فإن ركبا الدابة معاً اتُهما بالقسوة، وإن مشيا معاً اتُهما بالغباء، وإن ركب أحدهما وترجل الآخر اتُهم الراكب بعدم الرحمة ، هذه القصة القديمة تلخص حقيقة بسيطة لكنها عميقة( مُرضي الناس كالقابض على الماء ) .','["مجتمعاتنا اليوم يتجلى فيها هذا المشهد بوضوح في التفاصيل اليومية ، فالبعض يُنصًبون أنفسهم أوصياء وحكاماً على قرارات الآخرين وخياراتهم الشخصية ، متناسين أن لكل إنسان ظروفه وإمكانياته ، ونظرته الخاصة للحياة ، والمتأمل في سلوك المتدخلين في شؤون غيرهم يجد عجباً ، فالأمر لا يتعلق بالصواب والخطأ ،بل برغبة ملحة في إيجاد النقص مهما كانت الصورة مكتملة .","ففي البناء والسكن إذا أنشأ أحدهم بيتاً واسعاً ، قالوا لو أنه قلل مساحته ، فما الحاجةلكل هذا البناء الكبير ، وإذا بنى عمارة صغيرة أو متواضعة ، قالوا بتذمر لو أنه كبرهاواستغل المساحة بشكل أفضل .","وفي المناسبات والكرم إذا أقام شخصا مأدبة كبيرة وجاد بما لديه، اتهموه بالاسراف والتبذير ، ولو قصر اتهموه بالبخل والتقشف .","وفي الضيافة والصلة من اقتصرت ضيافته على أقاربه وجيرانه مراعاة لظروفه الماديةأو رغبة في البساطة ، فإنه ينال نصيبه من العتاب والملامة لأنه لم يتوسع في الدعوةوتجاهل فلان وغيره ، وفي المظهر واللباس إن ارتدى المرء لباساً فاخراً وأنيقاً نعتوهبالتكبر والمباهاة ، وإن ارتدى لباساً بسيطاً منخفض التكلفة ، اتهموه بالبخل والتقصيرفي حق نفسه ."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/v3c37of','https://sabq.org/article/v3c37of','','https://sabq.org/article/v3c37of','صالح مطر الغامدي','السعودية','2026-08-12T23:16:00.000Z','2026-08-13T02:16:00.000Z','2026-08-13T17:14:33.854Z','https://media.sabq.org/news/2026/08/e4213794-17c8-42d4-bb8b-a6e797f65bfa/w1600.webp','/api/media/6d12d381-aebe-4cfd-bf73-3321c1c92436','/api/media/6d12d381-aebe-4cfd-bf73-3321c1c92436?variant=thumbnail','عندما يتحول نقد الآخرين إلى أسلوب حياة !!',1600,893,'valid','published','archived','valid',40,'413cd0ad8c7c31ddce8ed23220b8db1448f2e774d2b0b27c3f13f2fb45fd8b2d','5c4a95d38879193cd41755d7c88ceb8f7f745b769f5c20adb4fab5ba33540de1','محدّث','2026-08-13T17:14:33.854Z','2026-10-07T20:59:06.694Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية"]','[]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:59:06.694Z',200,77,0,'source_article_available','',NULL,NULL,'body:fc12c38ef54af82d5d9ee9263caa0a5c0af01a0b2ff8baa9847977e320c13dc0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9a632575-b36a-4e4c-84dd-7412b9fd2fc6','news-9a632575-b36a-4e4c-84dd-7412b9fd2fc6','نتفليكس ورايترز هاوس يختتمان برنامج "اكتب المستقبل" التدريبي في ثلاث مناطق سعودية','نتفليكس ورايترز هاوس يختتمان برنامج اكتب المستقبل التدريبي في ثلاث مناطق سعوديه','أعلنت نتفليكس بالتعاون مع رايترز هاوس عن اختتام برنامج "اكتب المستقبل – مختبر كتّاب الأفلام الروائية" في المملكة العربية السعودية بنجاح.','["امتد البرنامج عبر ثلاث مناطق في المملكة، بهدف دعم الأصوات الإبداعية الأقل تمثيلاً وتمكينها من تطوير مشاريع سينمائية.","وفي إطار التزام البرنامج بتنمية المواهب المحلية وتعزيز حضور الكتّاب السعوديين، اعتمد البرنامج على تقدّيم تدريباً احترافياً متخصصاً للمجتمعات الإبداعية في عسير والمدينة المنورة والمنطقة الشرقية.","وانطلق المختبر بدعوة مفتوحة في السعودية لكتّاب السيناريو الناشئين، ليختتم باعتباره استثمارًا في مستقبل السرد القصصي في المملكة.","تم اختيار ثمانية عشر كاتبًا من بين مجموعة واسعة من المتقدمين من مختلف أنحاء المملكة، وقد مكّنهم البرنامج من تطوير تصور متكامل لفيلم روائي طويل باللغة العربية، يشمل الفكرة الرئيسية، ملخصًا للأحداث، معالجة درامية، ملفعرض بصري، وعرضًا تقديميًا مسجّلًا."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/nrt0nhg','https://sabq.org/article/nrt0nhg','','https://sabq.org/article/nrt0nhg','صحيفة سبق','السعودية','2026-08-12T23:15:00.000Z','2026-08-13T02:16:00.000Z','2026-08-13T17:14:34.138Z','https://media.sabq.org/news/2026/08/8d9ca6e3-289c-478d-bb85-48a7fc994d96/w1046.webp','/api/media/9a632575-b36a-4e4c-84dd-7412b9fd2fc6','/api/media/9a632575-b36a-4e4c-84dd-7412b9fd2fc6?variant=thumbnail','نتفليكس ورايترز هاوس يختتمان برنامج "اكتب المستقبل" التدريبي في ثلاث مناطق سعودية',1046,756,'valid','published','archived','valid',49,'a2c1930eda468dfe6768f943bf89cee745402e4191c615017ff40def768b8f3b','3f5add07a9a41e9b026c4f8e2a3e0e7707b175d0f9c3f231c715687a3496cea3','محدّث','2026-08-13T17:14:34.138Z','2026-10-07T20:59:40.741Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","عسير","المدينة المنورة"]','["الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","المدينة المنورة"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":4},{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":3}]','Active','2026-10-07T20:59:40.741Z',200,75,0,'source_article_available','',NULL,NULL,'body:4c1a278b12215dc7aa5e6e0ed973c5e880d5fe9b966945efaf11555fa4d403cf','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('69fd39c0-5190-4d6d-9095-c33781a85f4c','news-69fd39c0-5190-4d6d-9095-c33781a85f4c','«الأمن السيبراني» يحذر من ثغرات في منتجات HP ويدعو لتحديثها فورًا','الامن السيبراني يحذر من ثغرات في منتجات hp ويدعو لتحديثها فورا','حذّر المركز الوطني الإرشادي للأمن السيبراني من ثغرات أمنية تؤثر في عدد من منتجات HP، داعيًا المستخدمين والجهات المستفيدة إلى المبادرة بتطبيق التحديثات الأمنية التي أصدرتها الشركة؛ للحد من المخاطر المرتبطة باستغلال هذه الثغرات.','["وأوضح المركز أن التحديثات الأمنية تمثل خطوة أساسية لتعزيز حماية الأجهزة والأنظمة، وتقليل احتمالات تعرضها للاستغلال أو الاختراق، مشددًا على أهمية التأكد من استخدام أحدث الإصدارات المتاحة للمنتجات المتأثرة.","ودعا المركز المستخدمين إلى مراجعة تفاصيل التحذير الأمني المنشور عبر موقعه الرسمي، والتحقق من المنتجات المشمولة، واتباع التوصيات والإرشادات الفنية الصادرة بشأنها؛ بما يسهم في رفع مستوى الحماية وتعزيز السلامة السيبرانية."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ysiXbUm','https://sabq.org/article/ysiXbUm','','https://sabq.org/article/ysiXbUm','صحيفة سبق','السعودية','2026-08-12T23:24:00.000Z','2026-08-13T02:24:00.000Z','2026-08-13T17:14:34.933Z','https://media.sabq.org/news/2026/08/2ba00887-f5e6-4bc7-b380-de3938c6d212/w572.webp','/api/media/69fd39c0-5190-4d6d-9095-c33781a85f4c','/api/media/69fd39c0-5190-4d6d-9095-c33781a85f4c?variant=thumbnail','«الأمن السيبراني» يحذر من ثغرات في منتجات HP ويدعو لتحديثها فورًا',572,286,'valid','published','archived','valid',100,'ff9709a83181d0aaf73b1a53675043da792ef7bd6a0dfbfa7050be4b1a57ca2c','eabae315f9569ab6e1d97202a53c8d17c3c9ba9b5db5efd08488e5b3b6b25993','محدّث','2026-08-13T17:14:34.933Z','2026-10-07T20:59:06.656Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي"]','["التقنية والتحول الرقمي"]','manual_approved','','[]','Active','2026-10-07T20:59:06.656Z',200,75,0,'source_article_available','',NULL,NULL,'body:fbe867a2bf9c748df9505efeea15044758e8217b23d16a3816caea601c3fa68b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('33b5ccca-fa19-433b-ba9b-9d83b2ae56c0','news-33b5ccca-fa19-433b-ba9b-9d83b2ae56c0','"الأرصاد" أمطار رعدية غزيرة وسيول متوقعة على جازان وعسير','الارصاد امطار رعديه غزيره وسيول متوقعه علي جازان وعسير','توقّع المركز الوطني للأرصاد في تقريره عن حالة الطقس هذا اليوم- بمشيئة الله تعالى- هطول أمطار رعدية متوسطة إلى غزيرة تؤدي إلى جريان السيول مصحوبة بزخات من البرد على أجزاء من منطقتي جازان وعسير، في حين تكون خفيفة إلى متوسطة على أجزاء من مناطق نجران، الباحة، ومرتفعات منطقة مكة المكرمة، وتكوّن السحب الرعدية الممطرة على أجزاء من منطقتي الرياض والشرقية، خاصة الجنو','["وتؤثّر الرياح النشطة المثيرة للأتربة والغبار على أجزاء من تلك المناطق، وتصل إلى شبه انعدام في مدى الرؤية الأفقية على الأجزاء الساحلية من منطقتي المدينة المنورة ومكة المكرمة، بينما تظل درجات الحرارة العظمى مرتفعة على المنطقة الشرقية وأجزاء من مناطق الرياض، مكة المكرمة والمدينة المنورة.","وأشار التقرير إلى أن حركة الرياح السطحية على البحر الأحمر شمالية غربية إلى غربية بسرعة 20-45 كم/ساعة على الجزء الشمالي والأوسط وبسرعة 15-35 كم/ساعة على الجزء الجنوبي تصل إلى أكثر من 50 كم/ساعة على الجزء الأوسط كذلك تكوّن السحب الرعدية الممطرة على الجزء الجنوبي، وارتفاع الموج من متر إلى مترين يصل إلى مترين ونصف على الجزء الأوسط كذلك مع تكوّن السحب الرعدية الممطرة على الجزء الجنوبي، وحـالة البحر متوسط الموج يصل إلى…","فيما ستكون حركة الرياح على الخليج العربي جنوبية غربية إلى جنوبية شرقية على الجزء الشمالي والأوسط وشمالية شرقية إلى شمالية غربية على الجزء الجنوبي بسرعة 10-28 كم/ساعة وارتفاع الموج من نصف المتر إلى متر وحالة البحـر خفيف الموج."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/rnb4qoq','https://sabq.org/article/rnb4qoq','','https://sabq.org/article/rnb4qoq','صحيفة سبق','السعودية','2026-08-12T23:08:00.000Z','2026-08-13T02:09:00.000Z','2026-08-13T17:14:36.418Z','https://media.sabq.org/news/2026/08/333cc176-1357-436d-bfca-444f15548ea4/w1600.webp','/api/media/33b5ccca-fa19-433b-ba9b-9d83b2ae56c0','/api/media/33b5ccca-fa19-433b-ba9b-9d83b2ae56c0?variant=thumbnail','"الأرصاد" أمطار رعدية غزيرة وسيول متوقعة على جازان وعسير',1600,893,'valid','published','archived','valid',92,'ffd072696bcdd6486f4a0b79f22c43be990338e75b070529620da01de91c34c1','3d0b84fbd0d95bcc3a500a1c9d58a82877134835887dbbed15ec13a3877b4745','محدّث','2026-08-13T17:14:36.418Z','2026-10-07T20:59:06.689Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة","عسير","جازان","الرياض","الخليج العربي","المدينة المنورة"]','["الطقس والمناخ","الخليج العربي","المدينة المنورة"]','classified','','[{"category":"البيئة والمناخ","score":7.5},{"category":"السفر","score":3},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:59:06.689Z',200,77,0,'source_article_available','',NULL,NULL,'body:b4ac83b6096048dac1b11adc6d204df997d6d6161a79f934135864f5f902d509','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b890735f-54ec-4484-9ece-44186bafc519','news-b890735f-54ec-4484-9ece-44186bafc519','«أوتشا» يحذّر من تصاعد العنف في السودان ونزوح آلاف الأسر','اوتشا يحذر من تصاعد العنف في السودان ونزوح الاف الاسر','حذّر مكتب الأمم المتحدة لتنسيق الشؤون الإنسانية «أوتشا» من تصاعد العنف في السودان وما يخلّفه من خسائر بشرية فادحة في صفوف المدنيين ونزوح متزايد يُثقل كاهل البنية التحتية والخدمات الأساسية.','["وأفاد «أوتشا» بمقتل أكثر من 20 مدنياً وإصابة آخرين في اشتباكات اندلعت بمدينة قيسان في ولاية النيل الأزرق، أسفرت عن نزوح نحو 2500 شخص من منازلهم.","وفي السياق ذاته، استهدفت طائرات مسيّرة مدينة الأبيض في ولاية شمال كردفان، وأصابت إحداها محطةً للمياه، مما يُهدد وصول السكان إلى هذا المورد الحيوي.","وكشف المكتب الأممي عن نزوح نحو 15 ألف أسرة إلى مدينة الأبيض خلال الأسابيع الثلاثة الماضية، مما أوجد ضغطاً متزايداً على مراكز الإيواء والخدمات الأساسية في المدينة التي باتت تستقبل أعداداً تفوق طاقتها الاستيعابية.","وجدّد «أوتشا» دعوته جميع الأطراف إلى الالتزام بأحكام القانون الإنساني الدولي، وحماية المدنيين والبنية التحتية، وضمان وصول المساعدات الإنسانية بأمان ودون عوائق إلى المناطق المتضررة."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/3cDNeDQ','https://sabq.org/article/3cDNeDQ','','https://sabq.org/article/3cDNeDQ','صحيفة سبق','السعودية','2026-08-12T22:38:00.000Z','2026-08-13T01:39:00.000Z','2026-08-13T17:14:36.445Z','https://media.sabq.org/news/2026/08/e0cb5bcf-b030-48cb-a3d4-67e8e9ece13f/w1024.webp','/api/media/b890735f-54ec-4484-9ece-44186bafc519','/api/media/b890735f-54ec-4484-9ece-44186bafc519?variant=thumbnail','«أوتشا» يحذّر من تصاعد العنف في السودان ونزوح آلاف الأسر',1024,682,'valid','published','archived','valid',52,'da2feed1b56b187059716ecea70564f8775dec75ef31fdfbe183773f03aaccf9','ffbc7c88c440c8edb4a49cfee6d9208b6a176f6dd86d2d689943d1815c5e081a','محدّث','2026-08-13T17:14:36.445Z','2026-10-07T20:59:05.298Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة"]','["السفر والسياحة"]','manual_approved','below_category_threshold','[{"category":"السفر","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:59:05.298Z',200,71,0,'source_article_available','',NULL,NULL,'body:7e286282e376e5270b3d126aa88c95d37b104e19485e43eef4e0b0d386ab3095','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c26ad17c-f03f-467e-9b2b-22ca9bccbbc8','news-c26ad17c-f03f-467e-9b2b-22ca9bccbbc8','265 قتيلاً وآلاف المفقودين في زلزال ضرب كولومبيا','265 قتيلا والاف المفقودين في زلزال ضرب كولومبيا','ارتفعت حصيلة ضحايا الزلزال الذي ضرب كولومبيا إلى 265 قتيلاً على الأقل، في كارثة طبيعية تُلقي بظلالها الثقيلة على آلاف الأسر الكولومبية.','["وأعلن الرئيس الكولومبي أبيلاردو دي لا إسبرييلا مساء الأربعاء أن نحو 500 شخص لا يزالون في عداد المفقودين، غير أن قواعد البيانات التي تديرها الجهات المدنية ترفع هذا الرقم إلى أكثر من 4100 شخص، مشيراً إلى أن إجمالي الأسر المتضررة تجاوز 25800 أسرة.","وبلغت قوة الزلزال 4.7 درجات على مقياس ريختر، فيما رصدت هيئة المسح الجيولوجي الكولومبية 130 هزة ارتدادية منذ وقوع الكارثة، مما يُبقي المخاوف قائمة من تفاقم الأوضاع الإنسانية في المناطق المتضررة."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/XOT93IP','https://sabq.org/article/XOT93IP','','https://sabq.org/article/XOT93IP','صحيفة سبق','السعودية','2026-08-12T22:33:00.000Z','2026-08-13T01:34:00.000Z','2026-08-13T17:14:36.453Z','https://media.sabq.org/news/2026/08/091c1834-e4fe-4d56-b461-788e7c6d9816/w1280.webp','/api/media/c26ad17c-f03f-467e-9b2b-22ca9bccbbc8','/api/media/c26ad17c-f03f-467e-9b2b-22ca9bccbbc8?variant=thumbnail','265 قتيلاً وآلاف المفقودين في زلزال ضرب كولومبيا',1280,911,'valid','published','archived','valid',41,'3eaca61b110341d05dd00212f73fd9eac721d398e256d47f99558c4b49ff5cb4','e285c017633ef386c28aa5f93cbe9a68849fe59491791fa1e12c3162c6ee671d','محدّث','2026-08-13T17:14:36.453Z','2026-10-07T20:58:59.952Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة المسح الجيولوجي الكولومبية"]','["هيئة المسح الجيولوجي الكولومبية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:58:59.952Z',200,75,0,'source_article_available','',NULL,NULL,'body:e5413383a6b1f64008fa4e51e66b139feb66c443b065564c8b363eff6994cfa4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('89318e3a-b48e-4af6-bfb6-93ae8ec324b5','news-89318e3a-b48e-4af6-bfb6-93ae8ec324b5','وزير الدفاع: المملكة تقف إلى جانب العراق وتواصل دعم أمنه واستقراره','وزير الدفاع المملكه تقف الي جانب العراق وتواصل دعم امنه واستقراره','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية أكد الأمير خالد بن سلمان بن عبدالعزيز ، وزير الدفاع، حرص المملكة على مواصلة التعاون والتنسيق مع العراق في المجالات العسكرية والدفاعية، بما يسهم في تعزيز أمن البلدين واستقرار المنطقة.','["أكد الأمير خالد بن سلمان بن عبدالعزيز ، وزير الدفاع، حرص المملكة على مواصلة التعاون والتنسيق مع العراق في المجالات العسكرية والدفاعية، بما يسهم في تعزيز أمن البلدين واستقرار المنطقة.","وقال الأمير خالد بن سلمان، عبر حسابه على منصة «إكس»، إنه التقى الفريق الأول الركن عبدالأمير الشمري، مدير مكتب القائد العام للقوات المسلحة العراقية، إذ بحث الجانبان العلاقات السعودية العراقية في المجالين العسكري والدفاعي، إلى جانب التطورات الإقليمية.","وأوضح وزير الدفاع أنه جرى التأكيد خلال اللقاء على أهمية استمرار التنسيق والتعاون بين البلدين بما يخدم مصالحهما المشتركة، ويدعم أمن المنطقة واستقرارها."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/e08f522fm','https://ajel.sa/local/e08f522fm','https://ajel.sa/local/e08f522fm','https://ajel.sa/local/e08f522fm','فريق التحرير','السعودية','2026-08-13T11:11:00.000Z','Wed, 07 Oct 2026 20:58:49 GMT','2026-08-13T19:15:45.204Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/HPnVeneXQAAvxEA-L4hSmnNJ.jpg','/api/media/89318e3a-b48e-4af6-bfb6-93ae8ec324b5','/api/media/89318e3a-b48e-4af6-bfb6-93ae8ec324b5?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',100,'06e64bf526c313ccda5ff8805e4ed13e2f9eb20fb6fa5110fc30fe6414ed64e3','4e5cb9ad4b4fce62831d87a0e1d30cc177d084f6d0cb8a9de86ac1618ae8f25a',NULL,'2026-08-13T19:15:45.204Z','2026-10-07T20:58:51.514Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الدفاع المملكة تقف إلى","العراق"]','["وزير الدفاع المملكة تقف إلى"]','manual_approved','','[]','Updated','2026-10-07T20:58:51.514Z',200,89,0,'source_content_changed','',NULL,NULL,'body:4a7cbf9244e3e90f2e9711b438157ec83872f3d4068b6e48ffa466fe64d52344','Wed, 07 Oct 2026 20:58:49 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4f5b2ffe-64c3-4026-83e3-e1d79b51ea90','news-4f5b2ffe-64c3-4026-83e3-e1d79b51ea90','علوم وتقنيات / رصد زخة شهب البرشاويات من سماء العُلا','علوم وتقنيات رصد زخه شهب البرشاويات من سماء العلا','العُلا 30 صفر 1448 هـ الموافق 13 أغسطس 2026 م واس رُصدت في سماء محمية الغراميل بمحافظة العُلا زخة شهب البرشاويات، بالتزامن مع بلوغها ذروة نشاطها السنوي، في ظاهرة فلكية تتكرر خلال شهر أغسطس من كل عام.','["وبدأ تصوير الزخة منذ مساء أمس وحتى فجر اليوم الخميس، توالت الشهب خلالها في سماء الغراميل وسط ظروف ملائمة للرصد، أسهم فيها انخفاض التلوث الضوئي وظلام السماء، ما أتاح توثيق الظاهرة بوضوح.","وتُعد البرشاويات من أشهر زخات الشهب السنوية، وتتميز بنشاطها الملحوظ وظهور عدد من الشهب الساطعة والكرات النارية، ويمكن أن يبلغ معدل ظهورها في ذروة النشاط، وتحت سماء مظلمة وظروف رصد مثالية، نحو 75 إلى 100 شهاب في الساعة.","ويعود مصدر زخة البرشاويات إلى الغبار والحطام الذي خلّفه المذنب \"سويفت-تتل\" على طول مداره، إذ تعبر الأرض أثناء دورانها حول الشمس المسار الذي خلّفته هذه الجسيمات، فتدخل الغلاف الجوي بسرعات عالية وتتوهج نتيجة تفاعلها مع الغلاف الجوي، لتظهر على هيئة خطوط ضوئية سريعة في السماء.","واكتسبت الزخة اسمها من كوكبة \"برشاوس\"، المعروفة عربيًا بـ\"حامل رأس الغول\"، إذ تبدو الشهب ظاهريًا كأنها تنطلق من منطقة في السماء تقع أمام هذه الكوكبة، ويُعرف هذا الموضع باسم \"نقطة الإشعاع\"، في حين يمكن مشاهدة الشهب في أنحاء واسعة من السماء."]','الاقتصاد','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2653381?type=news&uuid=N2653381','https://spa.gov.sa/ar/N2653381?type=news&uuid=N2653381','N2653381','N2653381','','السعودية','2026-08-13T15:21:00.000Z','2026-08-12T06:30:00.000Z','2026-08-13T19:16:06.586Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10604533.jpeg','/api/media/4f5b2ffe-64c3-4026-83e3-e1d79b51ea90','/api/media/4f5b2ffe-64c3-4026-83e3-e1d79b51ea90?variant=thumbnail','علوم وتقنيات / رصد زخة شهب البرشاويات من سماء العُلا',1600,1066,'valid','published','archived','valid',50,'ef63d2bb465f38cc38b8e4597d05da3f9ac33e478410dd49452cb6a7a546a7a3','c9a9da4ed092f4e619396b9080860a7e4c3664d397b7f707b439dcc3b558bf02',NULL,'2026-08-13T19:16:06.586Z','2026-10-07T20:58:55.338Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة خطوط ضوئية سريعة في","الاقتصاد والأسواق"]','["هيئة خطوط ضوئية سريعة في","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":1.5},{"category":"الصحة","score":1.5},{"category":"السفر","score":1.5}]','Active','2026-10-07T20:58:55.338Z',200,78,0,'source_article_available','',NULL,NULL,'body:5f4a9a06f0756672ab2f71c004277d7985e0828c67c36683945bd8190080e8d1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('51c39355-8791-4d56-9a2e-90d7300e7533','news-51c39355-8791-4d56-9a2e-90d7300e7533','سياحة وترفيه / مسارات العُلا البرية.. تجارب سياحية تثري رحلة الوصول بتنوع الطبيعة والمعالم','سياحه وترفيه مسارات العلا البريه تجارب سياحيه تثري رحله الوصول بتنوع الطبيعه والمعالم','العُلا 30 صفر 1448 هـ الموافق 13 أغسطس 2026 م واس تتيح العُلا لزوارها خلال فصل الصيف فرصة اكتشاف تنوع المملكة الطبيعي والثقافي عبر ثلاثة مسارات برية تنطلق من جدة والمدينة المنورة وتبوك، وتمر بسواحل البحر الأحمر والتضاريس البركانية والمشاهد الصحراوية، لتصبح رحلة الوصول تجربة سياحية بحد ذاتها، بما تزخر به من محطات ومعالم متنوعة على امتداد الطريق.','["وتسهم شبكة الطرق السريعة التي تربط العُلا بمدن الانطلاق، إلى جانب توفر خدمات استئجار السيارات، في منح الزوار مرونة أكبر لاختيار المسار المناسب والتوقف عند الوجهات الواقعة على الطريق.","ويبدأ المسار الأول من جدة إلى العُلا عبر البحر الأحمر بمحاذاة الساحل، قبل أن يتجه شرقًا نحو الواحة التاريخية، مارًا بعدد من الوجهات الساحلية.","ومن جدة، يتجه الطريق شمالًا نحو ينبع، المدينة الساحلية المعروفة بكورنيشها وشواطئها وأنشطتها البحرية، وفي مقدمتها الغوص، ثم يواصل المسار شمالًا، حيث يمكن التوقف في وجهة \"البحر الأحمر\" للاستمتاع بالشواطئ البكر والمياه الصافية والتجارب البحرية الفاخرة، قبل الوصول إلى مدينة الوجه، التي تحتفظ ببلدتها التاريخية وتراثها البحري العريق.","ومن الوجه، تتجه الرحلة شرقًا نحو العُلا، حيث تتبدل ملامح الطريق تدريجيًا، فتفسح سواحل البحر الأحمر المجال أمام التكوينات الرملية الشاهقة والأودية الصحراوية، وصولًا إلى الواحة الخضراء التي أسهمت في تشكيل هوية العُلا ومشهدها الطبيعي المميز."]','الصحة','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2653248?type=news&uuid=N2653248','https://spa.gov.sa/ar/N2653248?type=news&uuid=N2653248','N2653248','N2653248','','السعودية','2026-08-13T12:54:00.000Z',NULL,'2026-08-13T19:16:06.594Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10603537.jpeg','/api/media/51c39355-8791-4d56-9a2e-90d7300e7533','/api/media/51c39355-8791-4d56-9a2e-90d7300e7533?variant=thumbnail','سياحة وترفيه / مسارات العُلا البرية.. تجارب سياحية تثري رحلة الوصول بتنوع الطبيعة والمعالم',1600,1067,'valid','published','archived','valid',86,'93fc1deedc12aeaa96b72df7d12ac286606cc0252f24c653cddd87ccb2ec1823','ee999c08c81ab53e666dbd4833c8e8daa0caaf8ad848f13ed387a3e39e24edba',NULL,'2026-08-13T19:16:06.594Z','2026-10-07T20:58:56.829Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الاقتصاد والأسواق","جدة"]','["السفر والسياحة","الاقتصاد والأسواق"]','classified','','[{"category":"الصحة","score":3},{"category":"السفر","score":3},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T20:58:56.829Z',200,79,0,'source_article_available','',NULL,NULL,'body:a16957d53f57e4ab05347c6976eb1b8deb1d1e13f3cd6cca2af053fb2f3b0ddc','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('51500be9-f5d4-4363-a415-b772c8aa6a5d','news-51500be9-f5d4-4363-a415-b772c8aa6a5d','جامعة شقراء تعلن التقويم الأكاديمي للفصل الأول 1448.. 19 أسبوعًا دراسيًا ومواعيد الإجازات والاختبارات','جامعه شقراء تعلن التقويم الاكاديمي للفصل الاول 1448 19 اسبوعا دراسيا ومواعيد الاجازات والاختبارات','أعلنت جامعة شقراء التقويم الأكاديمي للفصل الدراسي الأول من العام الجامعي 1448هـ، متضمنًا مواعيد بدء الدراسة والإجازات والاختبارات، إلى جانب مواعيد الحذف والإضافة والاعتذار والانسحاب وتغيير التخصص والكلية وإعلان النتائج، وذلك وفق جدول زمني يمتد على 19 أسبوعًا دراسيًا.','["وتبدأ الدراسة يوم الأحد 23 أغسطس 2026م، الموافق 10 ربيع الأول 1448هـ، فيما تتضمن الفترة الدراسية عددًا من المواعيد الأكاديمية والإجازات والإجراءات المرتبطة بالطلاب والطالبات.","وتتخلل الفصل الدراسي إجازة الخريف، التي تبدأ من الأحد 22 نوفمبر 2026م، الموافق 12 جمادى الآخرة 1448هـ، وتستمر حتى الخميس 26 نوفمبر 2026م، الموافق 16 جمادى الآخرة 1448هـ.","وتضمن التقويم أن يكون الثلاثاء 25 أغسطس 2026م، الموافق 12 ربيع الأول 1448هـ، آخر موعد للزيارة إلى خارج الجامعة، فيما حُدد الأربعاء 26 أغسطس 2026م، الموافق 13 ربيع الأول 1448هـ، موعدًا نهائيًا للحذف والإضافة.","وتشمل إجازات الفصل الدراسي إجازة اليوم الوطني، التي تمتد من الأربعاء 23 سبتمبر 2026م، الموافق 12 ربيع الآخر 1448هـ، إلى الخميس 24 سبتمبر 2026م، الموافق 13 ربيع الآخر 1448هـ، إضافة إلى الإجازة المطولة يوم الأحد 27 سبتمبر 2026م، الموافق 16 ربيع الآخر 1448هـ."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/raleyvc','https://sabq.org/article/raleyvc','','https://sabq.org/article/raleyvc','فلاح الجوفان','السعودية','2026-08-13T02:16:00.000Z','2026-08-13T05:17:00.000Z','2026-08-13T19:20:26.724Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/bd7c25d3-2c51-4dc5-9542-68d8e8886000/public','/api/media/51500be9-f5d4-4363-a415-b772c8aa6a5d','/api/media/51500be9-f5d4-4363-a415-b772c8aa6a5d?variant=thumbnail','جامعة شقراء تعلن التقويم الأكاديمي للفصل الأول 1448.. 19 أسبوعًا دراسيًا ومواعيد الإجازات والاختبارات',1168,768,'valid','published','archived','valid',52,'a1a8835291e7c2f8df081280dd1189941112c8c8cfd2c6302b8e643cf7ad4a57','363fc84925e099b89a261163905ae252d7d0f87f32be962c6617dfdf43df13b5','محدّث','2026-08-13T19:20:26.724Z','2026-10-07T20:58:49.238Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة شقراء تعلن التقويم الأكاديمي","التعليم والتدريب"]','["جامعة شقراء تعلن التقويم الأكاديمي","التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"السياسة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:58:49.238Z',200,87,0,'source_article_available','',NULL,NULL,'body:6a3bbac3e85eed31142c1f1391a7c7d2d56e33b37b1db8d67370b33f2a1a7611','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6287baaa-b096-4956-a87f-fe2cf048319f','news-6287baaa-b096-4956-a87f-fe2cf048319f','عشرات المستعمرين يقتحمون الأقصى بحماية قوات الاحتلال','عشرات المستعمرين يقتحمون الاقصي بحمايه قوات الاحتلال','اقتحم عشرات المستعمرين المسجد الأقصى المبارك بمدينة القدس المحتلة اليوم، من جهة باب المغاربة، على شكل مجموعات متتالية، وأدّوا جولات استفزازية في باحاته بحماية من قوات الاحتلال الإسرائيلي، التي تعرقل وصول المصلين للأقصى وتدقق في هوياتهم الشخصية.','["وفي موضوع آخر، اعتقلت قوات الاحتلال 30 فلسطينيًا على الأقل، خلال عمليات دهم وتفتيش واسعة طالت مناطق متفرقة بالضفة الغربية، تركّزت في مدن سلفيت وقلقيلة وطولكرم، تزامن ذلك مع هجوم مجموعة من المستعمرين على منازل وممتلكات الفلسطينيين في بلدة المنيا شرق مدينة بيت لحم."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/l1wxit4','https://sabq.org/article/l1wxit4','','https://sabq.org/article/l1wxit4','صحيفة سبق','السعودية','2026-08-13T02:04:00.000Z','2026-08-13T05:04:00.000Z','2026-08-13T19:20:30.302Z','https://media.sabq.org/news/2026/08/5f81db0b-0d71-4181-a8f1-e6103ae45734/w1600.webp','/api/media/6287baaa-b096-4956-a87f-fe2cf048319f','/api/media/6287baaa-b096-4956-a87f-fe2cf048319f?variant=thumbnail','عشرات المستعمرين يقتحمون الأقصى بحماية قوات الاحتلال',1600,900,'valid','published','archived','valid',35,'6da7cee9ec0303c303ec468cb68f0c3f07ab39b3f1df886756d4483cd0495c3a','cc0f5340a4bafed23c3d59071d1dc07ac6ef4d9ef013beba8715c524973df6dd','محدّث','2026-08-13T19:20:30.302Z','2026-10-07T20:58:55.930Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["فلسطين"]','[]','manual_approved','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T20:58:55.930Z',200,85,0,'source_article_available','',NULL,NULL,'body:d94d515a95de4990281003dd3cc12aeeb0e83fa443205d1d0fcfb132af313077','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('42f050a4-3fa0-43c2-aa2c-92110f3794bd','news-42f050a4-3fa0-43c2-aa2c-92110f3794bd','وزارة البلديات تُنجز 47 مشروعاً للمسح الجوي خلال 56 عاماً بتغطية 771,172 كم²','وزاره البلديات تنجز 47 مشروعا للمسح الجوي خلال 56 عاما بتغطيه 771 172 كم2','كشفت وزارة البلديات والإسكان، ممثلةً بوكالة التخطيط الحضري والأراضي، عن تنفيذ 47 مشروعاً للمسح الجوي وإنتاج الخرائط منذ عام 1970، أسهمت في بناء قاعدة بيانات جيومكانية تغطي أكثر من 771,172 كيلومتراً مربعاً، مما دعم أعمال التخطيط العمراني ووفّر صوراً جوية تاريخية وحديثة للنطاق العمراني في مختلف مناطق المملكة، بما يعزز صناعة القرار ويدعم تنفيذ المشروعات التنموي','["وتوثّق هذه البيانات مسيرة ممتدة على مدى 56 عاماً، شهدت تطوراً متواصلاً في أعمال المسح الجوي، بدءاً من الصور التناظرية الفيلمية إلى التصوير الرقمي عالي الدقة، في إطار تطوير منظومة المعلومات الجيومكانية التي تعتمد عليها الجهات الحكومية في التخطيط وإدارة التنمية الحضرية.","وأوضحت الوزارة أن مشروعات المسح الجوي نُفذت على مراحل متتابعة شملت مختلف مناطق المملكة، وأسهمت في تكوين أرشيف وطني متكامل للصور الجوية وتحديث البيانات المكانية، بما يرفع كفاءة التخطيط العمراني ويعزز دقة الدراسات والمخططات، ويوفر مرجعاً مكانياً موثوقاً لمشروعات التنمية.","وبيّنت البيانات أن منظومة المسح الجوي شهدت انتقالاً تدريجياً في استخدام التقنيات، بدءاً من التصوير بالأبيض والأسود، مروراً بالتصوير الملون، ثم التصوير الرقمي عالي الدقة، وصولاً إلى إنتاج الخرائط العقارية الرقمية، مما يعكس التطور الذي شهدته أعمال المساحة ونظم المعلومات في المملكة خلال العقود الماضية.","وفي محطة بارزة ضمن مسيرة تطوير الجودة، حصلت الوزارة على شهادة الآيزو لنظام إدارة الجودة «ISO 9001:2008» بتاريخ 19 أكتوبر 2010، وشمل نطاق الشهادة أنشطة إنتاج وتوفير المعلومات المكانية، بما فيها المسح الجوي والأرضي، والخرائط المصورة والطبوغرافية، والمسح العقاري، والاستشعار عن بُعد، ونظم المعلومات الجغرافية، مما يعكس التزام الوزارة بتطبيق معايير الجودة العالمية في إدارة مشروعات المسح الجوي وإنتاج البيانات الجيومكانية."]','العقارات','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/s92wAkX','https://sabq.org/article/s92wAkX','','https://sabq.org/article/s92wAkX','صحيفة سبق','السعودية','2026-08-13T02:02:00.000Z','2026-08-13T05:05:00.000Z','2026-08-13T19:20:30.394Z','https://media.sabq.org/news/2026/08/140ff3ea-4b1e-4d79-a690-9c95a2bc8abc/w1600.webp','/api/media/42f050a4-3fa0-43c2-aa2c-92110f3794bd','/api/media/42f050a4-3fa0-43c2-aa2c-92110f3794bd?variant=thumbnail','وزارة البلديات تُنجز 47 مشروعاً للمسح الجوي خلال 56 عاماً بتغطية 771,172 كم²',1600,2527,'valid','published','archived','valid',45,'304ce626750731ded54e15affa8e7dcc628f3e896fb5db5d2364dd214aa080d1','9ae8fc2154fd3df7666718c7a0171655b5e7c34f1d86a395a812db4de017b3a9','محدّث','2026-08-13T19:20:30.394Z','2026-10-07T20:58:55.920Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البلديات ت نجز","الثقافة والفنون","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["وزارة البلديات ت نجز","الثقافة والفنون","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T20:58:55.920Z',200,83,0,'source_article_available','',NULL,NULL,'body:4e860e03d307b889518ca92cb77b8bdf74e5e4835ae7dfc58844f5f1506a1139','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('767a3fd5-99a6-4239-a492-ffa46b196f99','news-767a3fd5-99a6-4239-a492-ffa46b196f99','250 طناً من التمور يومياً في سوق البكيرية بنسخته السابعة عشرة','250 طنا من التمور يوميا في سوق البكيريه بنسخته السابعه عشره','يشهد سوق تمور البكيرية في نسخته السابعة عشرة حراكاً اقتصادياً متنامياً، مع تسجيل مبيعات يومية تتجاوز 250 طناً من مختلف أصناف التمور، وسط إقبال واسع من المتسوقين والمزارعين والتجار من محافظة البكيرية والمحافظات المجاورة.','["ويمتد السوق على مدى 75 يوماً في مقره على طريق الملك سلمان بن عبدالعزيز، تحت إشراف محافظة البكيرية، وبتنظيم مشترك من مكتب وزارة البيئة والمياه والزراعة بالمحافظة، والمركز الوطني للنخيل والتمور، والشركة الوطنية للخدمات الزراعية، بالتعاون مع بلدية البكيرية ولجنة الأهالي وعدد من الجهات المشاركة.","وتتنوع أصناف التمور المعروضة في السوق بين «السكري» و«الهشيشي» و«المناصيف» و«البرحي» و«الونانة» و«الصقعي» و«المجدول»، فيما يضم السوق 20 مساراً لخدمة المزارعين وباعة التمور، إلى جانب حراج يُقام على فترتين يومياً، بما يسهم في تنظيم عمليات البيع والشراء واستيعاب الكميات الواردة.","ويُعدّ سوق تمور البكيرية رافداً اقتصادياً مهماً ونقطة انطلاق لأسواق التمور في منطقة القصيم، مستفيداً من وفرة إنتاج مزارع النخيل بالمحافظة وتنوع أصنافها وجودتها، بما يلبّي الطلب المتزايد على التمور ويدعم النشاط الزراعي والتجاري في المنطقة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/rN-43st','https://sabq.org/article/rN-43st','','https://sabq.org/article/rN-43st','صحيفة سبق','السعودية','2026-08-13T01:27:00.000Z','2026-08-13T04:27:00.000Z','2026-08-13T19:20:31.280Z','https://media.sabq.org/news/2026/08/4185fb6f-2f28-4b6b-8175-f998ff2e7b93/w547.webp','/api/media/767a3fd5-99a6-4239-a492-ffa46b196f99','/api/media/767a3fd5-99a6-4239-a492-ffa46b196f99?variant=thumbnail','250 طناً من التمور يومياً في سوق البكيرية بنسخته السابعة عشرة',547,365,'valid','published','archived','valid',95,'f414a6fe00095d6040d8390bef706df9c546f9fd4d218cea56d191ac1ffaa485','2b44212a63c37771ac8ba46d287c49b42ae6401782188f8b508afcacf345ee8f','محدّث','2026-08-13T19:20:31.280Z','2026-10-07T20:58:53.884Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البيئة والمياه والزراعة بالمحافظة","الاقتصاد والأسواق","القصيم"]','["وزارة البيئة والمياه والزراعة بالمحافظة","الاقتصاد والأسواق"]','classified','','[{"category":"أخبار السعودية","score":2},{"category":"الاقتصاد","score":1.5},{"category":"البيئة والمناخ","score":1.5}]','Active','2026-10-07T20:58:53.884Z',200,85,0,'source_article_available','',NULL,NULL,'body:2463f6b3eaa1707e14df3da9cf148d2eeb61fbf22a3a7c8f78aa3a9f977862cb','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3fa43b48-a035-4107-a7ea-4a672a2de364','news-3fa43b48-a035-4107-a7ea-4a672a2de364','المملكة تشارك في مؤتمر مكافحة التصحر بمنغوليا وتسلّم رئاسة الدورة إلى منغوليا','المملكه تشارك في مؤتمر مكافحه التصحر بمنغوليا وتسلم رئاسه الدوره الي منغوليا','تشارك المملكة العربية السعودية الاثنين المقبل في أعمال الدورة السابعة عشرة لمؤتمر الأطراف في اتفاقية الأمم المتحدة لمكافحة التصحر، التي تستضيفها جمهورية منغوليا خلال الفترة من 17 إلى 28 أغسطس الجاري، بمشاركة الدول الأطراف، والمنظمات الدولية، والجهات المعنية، كما تسلّم المملكة رئاسة المؤتمر إلى جمهورية منغوليا بعد فترة رئاسة شهدت تنفيذ عددٍ من المبادرات والشر','["وتأتي مشاركة المملكة في المؤتمر امتدادًا لدورها الريادي في دعم الجهود الدولية لمواجهة التحديات البيئية، حيث تستعرض أبرز المبادرات الدولية التي قادتها خلال رئاستها وما تحقق فيها من تقدّم، ومن أبرزها شراكة الرياض العالمية من أجل مقاومة الجفاف (RGDRP)، وأجندة عمل الرياض (Riyadh Action Agenda) التي نمت من 35 إلى أكثر من 100 مبادرة، والمبادرة الدولية للإنذار المبكر من العواصف الرملية والترابية، إضافةً إلى تفعيل مبادرة…","وكانت المملكة قد استضافت الدورة السادسة عشرة للاتفاقية في ديسمبر 2024م بمدينة الرياض، وهي الأكبر في تاريخ الاتفاقية، بمشاركة 197 طرفًا (196 دولة والاتحاد الأوروبي)، واعتماد 39 قرارًا، وحشد أكثر من 12 مليار دولار لدعم استعادة الأراضي ومقاومة الجفاف.","ويمثّل المؤتمر منصة دولية لتعزيز التعاون بين الدول الأطراف والمنظمات الدولية والجهات ذات العلاقة، وتبادل الخبرات واستعراض التجارب الناجحة في إدارة الأراضي واستعادتها وتعزيز استدامة الموارد الطبيعية، بما يدعم الجهود العالمية الرامية إلى الحد من آثار تدهور الأراضي والجفاف، ويعزّز الشراكات الهادفة إلى بناء مستقبل أكثر استدامة.","وتشارك المملكة في فعاليات المؤتمر، من خلال جناح وطني في المنطقة الزرقاء يضم برنامجًا متكاملًا بأكثر من 40 فعالية جانبية، وجناحًا مخصّصًا لمبادرة الشرق الأوسط الأخضر، فيما تترأس الاجتماع الأخير لمكتب مؤتمر الأطراف (COP Bureau) قبل تسليم الرئاسة إلى منغوليا، وتعقد الاجتماع الثاني للجنة التوجيهية والاجتماع الأول لجمعية الشركاء لشراكة الرياض العالمية من أجل مقاومة الجفاف، استكمالًا لما قادته من \"حوار تفاؤل\" حول الإطار…"]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/xp2iqk5','https://sabq.org/article/xp2iqk5','','https://sabq.org/article/xp2iqk5','صحيفة سبق','السعودية','2026-08-13T01:40:00.000Z','2026-08-13T04:42:00.000Z','2026-08-13T19:20:32.473Z','https://media.sabq.org/news/2026/08/42292c23-ba2d-4e53-be3b-3e541c274379/w1024.webp','/api/media/3fa43b48-a035-4107-a7ea-4a672a2de364','/api/media/3fa43b48-a035-4107-a7ea-4a672a2de364?variant=thumbnail','المملكة تشارك في مؤتمر مكافحة التصحر بمنغوليا وتسلّم رئاسة الدورة إلى منغوليا',1024,768,'valid','published','archived','valid',54,'89965d6c6bbf31b8d4d9c8e3a2b282d3d5eac9e50bad5ed9f8bb2f47e623110a','f3f95e708941d449c799c88094974afd165da91692cc6d4f015e4587dd5a957e','محدّث','2026-08-13T19:20:32.473Z','2026-10-07T20:58:53.900Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض","الشرق الأوسط"]','["الشرق الأوسط"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T20:58:53.900Z',200,81,0,'source_article_available','',NULL,NULL,'body:b86a180601ae775c77a64e55a1fa9e6f785d825ef8b3dc0baa84c336b63f5803','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1af62aeb-e92b-4545-b50f-6a1886abe245','news-1af62aeb-e92b-4545-b50f-6a1886abe245','التعاقب الوظيفي في المنظمات .. استثمار في استدامة المستقبل','التعاقب الوظيفي في المنظمات استثمار في استدامه المستقبل','لم يعد نجاح المنظمات في وقتنا الراهن، في ظل تسارع المتغيرات وتزايد التحديات، مرهوناَ بما تحققه من نتائج فحسب، بل بقدرتها على الاستعداد للمستقبل، مع استدامة أدائها، ومواصلة تحقيق أهدافها بكفاءة وفاعلية مهما تغيرت الظروف.','["ومن هنا يأتي التعاقب الوظيفي بوصفه أحد أهم الممارسات الإدارية التي تساعد المنظمات على الاستعداد للمستقبل، وضمان استمرارية الأعمال، وبناء قيادات قادرة على تحمل المسؤولية في الوقت المناسب.","فالتعاقب الوظيفي لا يعني البحث عن بديل عند شغور وظيفة قيادية، وإنما هو عملية استباقية تبدأ بتحديد الوظائف الحرجة، واكتشاف الكفاءات الواعدة، ثم تطويرها وتأهيلها لتولي مسؤوليات أكبر في المستقبل.","فالمنظمة التي تنتظر شغور المنصب حتى تبدأ في البحث عن البديل، تكون قد دخلت في مرحلة ردة الفعل، بينما المنظمة التي تعمل مسبقاَ على إعداد الكفاءات، تكون أكثر قدرة على التعامل مع التغيير دون أن تتأثر أعمالها أو تتعطل قراراتها.","وتزداد أهمية التعاقب الوظيفي في الوظائف القيادية والحساسة التي يرتبط بها جانب كبير من المعرفة والخبرة واتخاذ القرار."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/gKl9GFI','https://sabq.org/article/gKl9GFI','','https://sabq.org/article/gKl9GFI','حمد بن إبراهيم المنيف','السعودية','2026-08-13T01:00:00.000Z','2026-08-13T04:00:00.000Z','2026-08-13T19:20:33.753Z','https://media.sabq.org/news/2026/08/1d9b22fb-a0ea-4573-a0d8-f74383420e1b/w1600.webp','/api/media/1af62aeb-e92b-4545-b50f-6a1886abe245','/api/media/1af62aeb-e92b-4545-b50f-6a1886abe245?variant=thumbnail','التعاقب الوظيفي في المنظمات .. استثمار في استدامة المستقبل',1600,893,'valid','published','archived','valid',91,'97601c48165d2bdb5839df1511c43675aa922633d59de6204e56b152bbd32593','adf22c9dc9fed311df93952fff9c8b7bbf1dbb871e3df11500d0d5c87df99826','محدّث','2026-08-13T19:20:33.753Z','2026-10-07T20:58:59.957Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','classified','','[{"category":"المناطق","score":4},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:58:59.957Z',200,77,0,'source_article_available','',NULL,NULL,'body:d9ccfd455122da2359ae5952a536a6ff2390cb38b91301f06cc08daa9371cf37','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cc400d75-d308-44b0-baae-a258f7191ddd','news-cc400d75-d308-44b0-baae-a258f7191ddd','رجل الدولة.. حين تصبح القيادة أثراً','رجل الدوله حين تصبح القياده اثرا','ما الذي ميّز المملكة عن كثير من الدول، وجعلها تحقق أغلب مستهدفات رؤية 2030 قبل موعدها المحددة؟','["خلف الأرقام قصص، وخلف الإنجازات قرارات، وخلف القرارات قيادات.","أحد أهم عناصر هذه التجربة وجود قيادات بمستوى رجالات دولة ؛ رجال يمتلكون رؤية تتجاوز حدود المنصب، ويدركون أن بناء الدولة لا يقاس فقط بما يُنجز اليوم، وإنما بما يُترك للأجيال القادمة.","هو شخصية تحمل كاريزما مختلفة؛ كاريزما هادئة تستمد قوتها من وضوح الرؤية، وثقة القرار، والقدرة على تحويل الطموح إلى واقع.","رجل الدولة يعرف أن النظام وُضع لحماية الإنسان وتنظيم حياته، فيقرأ القانون بعين المقصد، ويسخّر الصلاحيات لصناعة الحلول، ويبحث عن المساحة التي تجعل الإجراءات أكثر سهولة، والخدمات أكثر قرباً، والفرص أكثر اتساعاً."]','السيارات','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/fkjhm3v','https://sabq.org/article/fkjhm3v','','https://sabq.org/article/fkjhm3v','أحمد الظفيري','السعودية','2026-08-13T01:00:00.000Z','2026-08-13T04:00:00.000Z','2026-08-13T19:20:33.873Z','https://media.sabq.org/news/2026/08/41dde9d8-16f0-4a16-bf5c-fd4a641a6b3e/w1600.webp','/api/media/cc400d75-d308-44b0-baae-a258f7191ddd','/api/media/cc400d75-d308-44b0-baae-a258f7191ddd?variant=thumbnail','رجل الدولة.. حين تصبح القيادة أثراً',1600,893,'valid','published','archived','valid',46,'7030c339779ae5d8e84cc1ee9f1d6903bee758b20a621fc645bec0f5b73fce91','7d255c918f395880428948c4e91fbba08958a0fbc9554091affb96f88a35c50b','محدّث','2026-08-13T19:20:33.873Z','2026-10-07T20:58:53.866Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"الطاقة والصناعة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:58:53.866Z',200,80,0,'source_article_available','',NULL,NULL,'body:d7e1f215e7428c92f3a644f58a888be4ae7ccfe273552658d817e29f163f9f1f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b8132d95-9e1d-435e-be46-fb5fc8e17574','news-b8132d95-9e1d-435e-be46-fb5fc8e17574','«إنفاذ» يطرح 1043 أصلاً عقارياً في 95 مزاداً بمناطق المملكة خلال أغسطس','انفاذ يطرح 1043 اصلا عقاريا في 95 مزادا بمناطق المملكه خلال اغسطس','أعلن مركز الإسناد والتصفية «إنفاذ» عن إقامة 95 مزاداً عقارياً في مختلف مناطق المملكة العربية السعودية، تتضمن طرح 1043 أصلاً عقارياً متنوعاً، وذلك خلال الفترة الممتدة من 15 إلى 31 أغسطس 2026م.','["وتتصدر منطقة الرياض قائمة المناطق من حيث عدد المزادات بـ 31 مزاداً تشمل 299 أصلاً عقارياً، فيما تحتل منطقة مكة المكرمة المرتبة الثانية بـ 23 مزاداً تتضمن 277 أصلاً عقارياً.","وتأتي المنطقة الشرقية في المرتبة الثالثة بـ 9 مزادات تشمل 86 أصلاً عقارياً، تليها منطقة القصيم بـ 8 مزادات تتضمن 120 أصلاً عقارياً، ثم منطقة عسير بـ 5 مزادات تشمل 55 أصلاً عقارياً.","كما تُقام 3 مزادات في كل من المدينة المنورة وتبوك وحائل، ومزادان في كل من منطقتَي الجوف وجازان ونجران والحدود الشمالية والباحة.","ويمكن الاطلاع على تفاصيل المزادات وشروط المشاركة عبر الموقع الرسمي لمركز «إنفاذ»: infath.gov.sa"]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/I7HbopW','https://sabq.org/article/I7HbopW','','https://sabq.org/article/I7HbopW','صحيفة سبق','السعودية','2026-08-13T00:29:00.000Z','2026-08-13T03:40:00.000Z','2026-08-13T19:20:34.732Z','https://media.sabq.org/news/2026/08/dd97c069-c2fa-4ec1-a014-35262648a6a7/w801.webp','/api/media/b8132d95-9e1d-435e-be46-fb5fc8e17574','/api/media/b8132d95-9e1d-435e-be46-fb5fc8e17574?variant=thumbnail','«إنفاذ» يطرح 1043 أصلاً عقارياً في 95 مزاداً بمناطق المملكة خلال أغسطس',801,801,'valid','published','archived','valid',99,'1ac35f700190d810167dc6ee0a0f21f21f9bbadef795e1431c977a36c2be588c','0d1e883403846b452bbad10343597e695d037fa887b50bff74b9557f9da0fc9c','محدّث','2026-08-13T19:20:34.732Z','2026-10-07T20:59:02.231Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","عسير","تبوك","جازان","نجران","الجوف","الرياض","القصيم"]','["المدينة المنورة"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T20:59:02.231Z',200,82,0,'source_article_available','',NULL,NULL,'body:604add9e740c41db3d553284cc72e7cfb53ead9c584e83f84ac458c34b0cb85d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('af0ab204-dcce-4ef3-9994-90eb8f009729','news-af0ab204-dcce-4ef3-9994-90eb8f009729','«الإحصاء»: التضخم السنوي في المملكة يبلغ 1.8% خلال يوليو 2026','الاحصاء التضخم السنوي في المملكه يبلغ 1 8 خلال يوليو 2026','سجّل معدل التضخم السنوي في المملكة العربية السعودية 1.8% خلال يوليو 2026 مقارنةً بالشهر ذاته من عام 2025، فيما ارتفع مؤشر أسعار المستهلك على أساس شهري بنسبة 0.2% مقارنةً بيونيو الماضي، وفق بيانات الهيئة العامة للإحصاء.','["وأظهرت البيانات ارتفاع أسعار «السكن والمياه والكهرباء والغاز وأنواع الوقود الأخرى» بنسبة 4.2% على أساس سنوي، لتحتل صدارة القطاعات الأكثر ارتفاعاً، تلتها أسعار «العناية الشخصية والحماية الاجتماعية والسلع والخدمات الأخرى» بنسبة 2.9%، و«الترويح والرياضة والثقافة» بنسبة 2.4%، و«المطاعم وخدمات الإقامة» بنسبة 2%.","كما سجّلت أسعار «الأغذية والمشروبات» زيادةً بنسبة 1.5%، وارتفعت أسعار «النقل» بنسبة 1.4%، و«التأمين والخدمات المالية» بنسبة 1.4%، و«خدمات التعليم» بنسبة 1.2%، و«المعلومات والاتصالات» بنسبة 0.6%، و«الصحة» بنسبة 0.3%.","في المقابل، سجّلت بعض القطاعات انخفاضاً في الأسعار، إذ تراجعت أسعار «الأثاث والأجهزة المنزلية والصيانة الدورية للمنزل» بنسبة 0.5%، وأسعار «الملابس والأحذية» بنسبة 0.4%، فيما ارتفعت أسعار «التبغ» بنسبة 0.4%."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/zrLz174','https://sabq.org/article/zrLz174','','https://sabq.org/article/zrLz174','صحيفة سبق','السعودية','2026-08-13T00:27:00.000Z','2026-08-13T03:28:00.000Z','2026-08-13T19:20:35.684Z','https://media.sabq.org/news/2026/08/8bb66794-3491-47f2-b82b-6fffff6987f4/w1600.webp','/api/media/af0ab204-dcce-4ef3-9994-90eb8f009729','/api/media/af0ab204-dcce-4ef3-9994-90eb8f009729?variant=thumbnail','«الإحصاء»: التضخم السنوي في المملكة يبلغ 1.8% خلال يوليو 2026',1600,1600,'valid','published','archived','valid',97,'a17f4d6682c621d4884ca69964ac1f7607485e680896ebdcd00ebb37f1c59f41','4f2f9751d967693c6dbf23711e10ea1a4ef4f0cbc8b2b9cf81714d931d453520','محدّث','2026-08-13T19:20:35.684Z','2026-10-07T20:58:57.525Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الطاقة والنفط","الثقافة والفنون","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق","الرياض"]','["الصحة العامة","الطاقة والنفط","الثقافة والفنون","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"التقنية","score":2},{"category":"المناطق","score":1.5}]','Active','2026-10-07T20:58:57.525Z',200,75,0,'source_article_available','',NULL,NULL,'body:261207d17ae0b597c77ecd21b7d35c74d6eef2f336880d713031003039644b95','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6aea4970-25c1-49f2-88f8-9adf2b7be63d','news-6aea4970-25c1-49f2-88f8-9adf2b7be63d','سياحة وترفيه / "بيش" تزدان بألوان المطر.. ومشاهد تجذب المتنزهين','سياحه وترفيه بيش تزدان بالوان المطر ومشاهد تجذب المتنزهين','بيش 30 صفر 1448 هـ الموافق 13 أغسطس 2026 م واس جددت الأمطار الغزيرة التي شهدتها محافظة بيش خلال الأيام الماضية المشهد الطبيعي والزراعي، ودفعت بمياه الأودية نحو السهول والمزارع، لتتسع رقعة الخضرة وتبرز الملامح الزراعية للمحافظة في مشاهد استوقفت الأهالي والزوار ومحبي التصوير، خلال الإجازة الصيفية.','["وأعادت الأمطار إلى واجهة المشهد العلاقة الوثيقة بين أودية بيش وأراضيها الزراعية، مع جريان عدد من الأودية، من بينها وادي \"قُرى\"، أحد روافد وادي بيش، وامتداد المياه عبر السهول والمنخفضات نحو مساحات زراعية واسعة، بما يعكس أهمية الأودية في تغذية الأراضي وتجدد الغطاء النباتي الذي يميز أجزاء واسعة من المحافظة.","ورصدت عدسة \"واس\" من مدخل بيش امتداد المياه بين المزارع والمساحات الخضراء وعلى جانبي الطريق، في لوحة رسمتها الأمطار واستوقفت العابرين والمتنزهين، وجذبت محبي التصوير لتوثيق تداخل المياه والخضرة مع الامتداد الزراعي للمحافظة.","وتحولت المواقع المطلة على هذه المشاهد إلى نقاط جذب للأهالي والزوار، مع تنامي الرحلات العائلية خلال الإجازة الصيفية، إذ أتاحت الأجواء الماطرة فرصة للتنزه ومشاهدة اتساع الرقعة الخضراء وتدفقات المياه، وأضافت إلى الوجهات الطبيعية في منطقة جازان مشاهد مختلفة ترتبط بطبيعة بيش السهلية والزراعية.","وتمنح الأمطار بيش قيمة تتجاوز المشهد الموسمي، فهي عنصر رئيس في تجدد بيئتها الزراعية وتغذية أراضيها، وتكشف عند هطولها عن جانب من هوية المحافظة التي ارتبطت بالزراعة وخصوبة سهولها، لتلتقي في موسم المطر قيمة المكان الزراعية مع جاذبيته الطبيعية والسياحية."]','السفر','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2653343?type=news&uuid=N2653343','https://spa.gov.sa/ar/N2653343?type=news&uuid=N2653343','N2653343','N2653343','','السعودية','2026-08-13T14:32:00.000Z',NULL,'2026-08-13T21:22:11.460Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10605049.jpg','/api/media/6aea4970-25c1-49f2-88f8-9adf2b7be63d','/api/media/6aea4970-25c1-49f2-88f8-9adf2b7be63d?variant=thumbnail','سياحة وترفيه / "بيش" تزدان بألوان المطر.. ومشاهد تجذب المتنزهين',1600,899,'valid','published','archived','valid',53,'4d232e24feeb1586bf14b5e57cc7a102ebd405adc27d041b8a6ea47aff4b2770','b787188810f2482bb5138c9523b0e2cfe2b07258b674eefc679011298a096b7c',NULL,'2026-08-13T21:22:11.460Z','2026-10-07T20:58:46.914Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس في تجدد بيئتها الزراعية","الطقس والمناخ","السفر والسياحة","جازان"]','["رئيس في تجدد بيئتها الزراعية","الطقس والمناخ","السفر والسياحة"]','manual_approved','below_category_threshold','[{"category":"السفر","score":4.5},{"category":"الصحة","score":1.5},{"category":"البيئة والمناخ","score":1.5}]','Active','2026-10-07T20:58:46.914Z',200,75,0,'source_article_available','',NULL,NULL,'body:1a97040c8a0978f4e04085962ee849efc4d960774d2c46b41089137976f9017b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('beabe3ed-0331-4fdf-b983-81e96c29b432','news-beabe3ed-0331-4fdf-b983-81e96c29b432','سياحة وترفيه / ليل أبها.. أجواء جبلية تنعش الحركة السياحية وتستقطب الزوار','سياحه وترفيه ليل ابها اجواء جبليه تنعش الحركه السياحيه وتستقطب الزوار','أبها 30 صفر 1448 هـ الموافق 13 أغسطس 2026 م واس تتحول مدينة أبها مع حلول المساء إلى مشهد سياحي نابض بالحياة، تتداخل فيه برودة الأجواء الجبلية مع أضواء المدينة وحركة الزوار، في تجربة صيفية تستند إلى تنوع المقومات الطبيعية والترفيهية التي تمنح المدينة حضورًا لافتًا خلال ساعات الليل.','["ويشهد عدد من المواقع السياحية والوجهات المفتوحة في أبها إقبالًا متزايدًا من الزوار والعائلات، الذين يجدون في الأجواء المعتدلة متنفسًا للاستمتاع بالمماشي والحدائق والمطاعم والمقاهي والإطلالات الجبلية، وسط حركة تستمر حتى ساعات متأخرة من الليل.","ويأتي حزام أبها ضمن أبرز الوجهات التي يقصدها الزوار مساءً، لما يوفره من مشاهد بانورامية للمدينة، إلى جانب تنوع المرافق والخدمات والخيارات التي تلائم العائلات والشباب، وتتيح قضاء أوقات ممتعة في أجواء جبلية هادئة.","وتمنح السحب والضباب التي تتشكل على المرتفعات المشهد الليلي طابعًا مختلفًا، إذ تتداخل مع أضواء المدينة وتضاريسها الجبلية، لتصنع مشاهد بصرية تجسد خصوصية أبها بوصفها وجهة صيفية تجمع الطبيعة والحياة العصرية.","وفي المقابل، تواصل الحدائق والمماشي والوجهات السياحية المفتوحة استقبال مرتاديها، وسط تنوع في الأنشطة والمواقع، ما أسهم في تعزيز الخيارات المتاحة أمام الزوار لقضاء أمسياتهم والاستمتاع بالأجواء الخارجية."]','السفر','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2653408?type=news&uuid=N2653408','https://spa.gov.sa/ar/N2653408?type=news&uuid=N2653408','N2653408','N2653408','','السعودية','2026-08-13T16:02:00.000Z',NULL,'2026-08-13T21:22:11.466Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10604863.jpg','/api/media/beabe3ed-0331-4fdf-b983-81e96c29b432','/api/media/beabe3ed-0331-4fdf-b983-81e96c29b432?variant=thumbnail','سياحة وترفيه / ليل أبها.. أجواء جبلية تنعش الحركة السياحية وتستقطب الزوار',1600,894,'valid','published','archived','valid',45,'001f82093dddb8116964a678d76d6e25caa9445cc4da9f0e186fad942900aad2','7eaceea0caa72016c0a79286bde077572cf7e2cee82efa339b8979b4ad90c578',NULL,'2026-08-13T21:22:11.466Z','2026-10-07T20:58:46.147Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الاقتصاد والأسواق"]','["السفر والسياحة","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"الصحة","score":1.5},{"category":"البيئة والمناخ","score":1.5}]','Active','2026-10-07T20:58:46.147Z',200,75,0,'source_article_available','',NULL,NULL,'body:148a421f5b40dfac4d7bc28fe4e7d8b16f082bf803a26fef38ebdf7ab6db3c5a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('986b6d18-2794-4bdf-bba3-dc8382421df8','news-986b6d18-2794-4bdf-bba3-dc8382421df8','الأمن البيئي يضبط مواطنًا لمخالفته نظام البيئة داخل محمية الإمام عبدالعزيز بن محمد','الامن البيئي يضبط مواطنا لمخالفته نظام البيئه داخل محميه الامام عبدالعزيز بن محمد','ضبطت القوات الخاصة للأمن البيئي مواطنًا مخالفًا لنظام البيئة لدخوله بمركبته في الفياض والروضات البرية المحمية في الإمام عبدالعزيز بن محمد الملكية، واتخذت الإجراءات النظامية بحقه.','["وأوضحت القوات أن عقوبة دخول المركبات والسيارات في الفياض والروضات البرية المحمية تصل إلى (2,000) ريال، حاثةً على الإبلاغ عن أي حالات تمثل اعتداءً على البيئة أو الحياة الفطرية على الرقم (911) بمناطق مكة المكرمة والمدينة المنورة والرياض والشرقية، و(999) و(996) في بقية مناطق المملكة، وستعامل جميع البلاغات بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/brzfmix','https://sabq.org/article/brzfmix','','https://sabq.org/article/brzfmix','صحيفة سبق','السعودية','2026-08-13T04:15:00.000Z','2026-08-13T07:15:00.000Z','2026-08-13T21:26:30.996Z','','','/api/media/fallback/%D8%A7%D9%84%D9%85%D8%AC%D8%AA%D9%85%D8%B9','الأمن البيئي يضبط مواطنًا لمخالفته نظام البيئة داخل محمية الإمام عبدالعزيز بن محمد',NULL,NULL,'fetch failed','review','archived','valid',95,'950fc129a26046e59ce29af7f933b56c9a8ee520ce59a14daef84d4e11364cec','79d890fee2170b09391304de26658b60f5b22cfcd69af0357635a253c8c92a3a','محدّث','2026-08-13T21:26:30.996Z','2026-10-07T20:58:51.048Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع","مكة","الرياض","المدينة المنورة","نظام البيئة داخل","الأمن البيئي يضبط","البيئي يضبط مواطن","البيئة داخل محمية"]','["المدينة المنورة","نظام البيئة داخل","الأمن البيئي يضبط","البيئي يضبط مواطن","البيئة داخل محمية","داخل محمية الإمام"]','classified','','[]','Active','2026-10-07T20:58:51.048Z',200,89,0,'source_article_available','',NULL,NULL,'body:ff7b2999aa45d7df5b42c168724c961737986703cda62e6de5aea0061a7b6b95','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dd6d897d-cc15-42c1-985a-f861fe340c42','news-dd6d897d-cc15-42c1-985a-f861fe340c42','3 مراكز صحية في المدينة المنورة تنال اعتماد «سباهي» للجودة','3 مراكز صحيه في المدينه المنوره تنال اعتماد سباهي للجوده','أعلن تجمع المدينة المنورة الصحي حصول ثلاثة مراكز للرعاية الصحية الأولية على شهادة الاعتماد من المركز السعودي لاعتماد المنشآت الصحية «سباهي CBAHI»، وذلك بعد استيفائها كامل متطلبات ومعايير الاعتماد، واجتيازها التقييم الشامل المعتمد.','["وشمل الاعتماد كلاً من مركز صحي المسيجيد، ومركز صحي الضليعة، ومركز صحي الرايس، في خطوة تعكس جهود التجمع المستمرة لتعزيز جودة خدمات الرعاية الصحية الأولية وكفاءتها، وتطبيق أعلى معايير الجودة وسلامة المرضى.","ويرمي الاعتماد إلى تحقيق المتطلبات الأساسية للسلامة، والالتزام بأرقى معايير الجودة في تقديم الخدمات الصحية والعلاجية، بما يسهم في رفع مستوى الخدمات المقدمة وتعزيز ثقة المستفيدين بجودتها.","وأكد تجمع المدينة المنورة الصحي أن حصول هذه المراكز على اعتماد «سباهي» يندرج ضمن مساعيه المتواصلة لتطوير منظومة الرعاية الصحية الأولية، وتحسين تجربة المستفيد، وتعزيز جودة الخدمات الصحية وسلامتها في مختلف منشآته."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/nu3gm5i','https://sabq.org/article/nu3gm5i','','https://sabq.org/article/nu3gm5i','صحيفة سبق','السعودية','2026-08-13T03:46:00.000Z','2026-08-13T06:47:00.000Z','2026-08-13T21:26:33.934Z','https://media.sabq.org/news/2026/08/ca73ff18-5616-41b6-80e8-b02d5b4fa7ed/w642.webp','/api/media/dd6d897d-cc15-42c1-985a-f861fe340c42','/api/media/dd6d897d-cc15-42c1-985a-f861fe340c42?variant=thumbnail','3 مراكز صحية في المدينة المنورة تنال اعتماد «سباهي» للجودة',642,480,'valid','published','archived','valid',50,'0cacd4b4c1afcad79f4330b04a8a409a0c24f674fc6c7c95a5696edfa2461b6a','4fbc6831d3fb3313ab39483f9327f2ec354341d0f6655da2623795b66de05cfa','محدّث','2026-08-13T21:26:33.934Z','2026-10-07T20:58:48.152Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","المدينة المنورة"]','["الصحة العامة","المدينة المنورة"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":3},{"category":"التقنية","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:58:48.152Z',200,89,0,'source_article_available','',NULL,NULL,'body:bd07fd0215caed744c63aa420ad1b12f4077a1006d934c08f504ec11701f863d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('baf8940a-deb8-4d72-9eb2-8b0617b3fbed','news-baf8940a-deb8-4d72-9eb2-8b0617b3fbed','إجازة المعلمين الصيفية تنتهي اليوم والعودة للمدارس الأحد باستثناء 4 إدارات','اجازه المعلمين الصيفيه تنتهي اليوم والعوده للمدارس الاحد باستثناء 4 ادارات','تُختتم اليوم الخميس الإجازة الصيفية للمعلمين والمعلمات في معظم إدارات التعليم بالمملكة، بعد إجازة امتدت لنحو شهر و20 يومًا، على أن يباشروا أعمالهم في المدارس الأحد المقبل 3 ربيع الأول 1448هـ الموافق 16 أغسطس 2026م، استعدادًا لانطلاقة العام الدراسي الجديد 1448/1449هـ (2026/2027م).','["وتستثنى من موعد العودة أربع إدارات تعليمية، هي إدارات التعليم في مكة المكرمة والمدينة المنورة ومحافظتي جدة والطائف، التي حدد التقويم الدراسي الخاص بها موعد عودة المعلمين والمعلمات الأحد 10 ربيع الأول 1448هـ الموافق 23 أغسطس 2026م، أي بعد أسبوع من عودة زملائهم في بقية إدارات التعليم.","وكان مديرو ومديرات المدارس والهيئة الإدارية في مدارس التعليم العام، بمن فيهم المكلفون بالتوجيه الطلابي ورواد النشاط ومحضرو المختبرات، قد باشروا أعمالهم الثلاثاء الماضي؛ لتهيئة المدارس واستكمال الاستعدادات لاستقبال المعلمين والمعلمات، ثم الطلاب والطالبات مع انطلاقة العام الدراسي الجديد.","ومع عودة الكوادر التعليمية إلى الميدان، يتضمن العام الدراسي الجديد ست إجازات مدرسية؛ تبدأ بإجازة اليوم الوطني لمدة يومين، تليها إجازة الخريف التي تمتد 9 أيام، ثم إجازة منتصف العام الدراسي لمدة 9 أيام، وإجازة يوم التأسيس لمدة يومين، فيما تمتد إجازتا عيد الفطر وعيد الأضحى إلى 16 يومًا لكل منهما.","عودة المعلمين الأحد بعد المقبل حدد التقويم الدراسي الخاص بإدارات التعليم في مكة المكرمة والمدينة المنورة ومحافظتي جدة والطائف موعد عودة المعلمين والمعلمات إلى مدارسهم الأحد 10 ربيع الأول 1448هـ الموافق 23 أغسطس 2026م، على أن تبدأ الدراسة فعليًا بعودة الطلاب والطالبات إلى مقاعد الدراسة الأحد 17 ربيع الأول 1448هـ الموافق 30 أغسطس 2026م."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/63BBGDM','https://sabq.org/article/63BBGDM','','https://sabq.org/article/63BBGDM','عبدالحكيم شار','السعودية','2026-08-13T03:30:00.000Z','2026-08-13T06:31:00.000Z','2026-08-13T21:26:35.152Z','https://media.sabq.org/news/2026/08/a2dc0fc8-a4d4-4c8e-be86-5e35fe120e26/w1600.webp','/api/media/baf8940a-deb8-4d72-9eb2-8b0617b3fbed','/api/media/baf8940a-deb8-4d72-9eb2-8b0617b3fbed?variant=thumbnail','إجازة المعلمين الصيفية تنتهي اليوم والعودة للمدارس الأحد باستثناء 4 إدارات',1600,900,'valid','published','archived','valid',94,'98f1a701a091ccdadac4124a06d143184ade7e8e5469e700a1c9c17b775a34df','72c1c1fa72c9ddfac6b477800937e5aa650aeef8320a210ffbaebc0d9c57fbc4','محدّث','2026-08-13T21:26:35.152Z','2026-10-07T20:58:59.249Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","مكة","جدة","المدينة المنورة"]','["التعليم والتدريب","المدينة المنورة"]','classified','','[{"category":"المناطق","score":4.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:58:59.249Z',200,79,0,'source_article_available','',NULL,NULL,'body:41be792e166578f4767b234e2a535de3e0a06306fea9cde186bd5c70e8abfaef','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('62ed1540-827b-4658-ac62-badd8d1805b1','news-62ed1540-827b-4658-ac62-badd8d1805b1','الأرصاد تحذر من رياح نشطة وأتربة مثارة في حائل ونجران','الارصاد تحذر من رياح نشطه واتربه مثاره في حائل ونجران','أصدر المركز الوطني للأرصاد تنبيهاً من هبوب رياح نشطة على منطقة حائل، تشمل المناطق المفتوحة والطرق السريعة، مما يؤدي إلى تدنٍّ في مدى الرؤية الأفقية بين 3 و5 كيلومترات، مع توقع استمرار الحالة حتى الساعة الثامنة مساءً.','["وفي السياق ذاته، نبّه المركز من أتربة مثارة تضرب منطقة نجران، مصحوبة برياح نشطة تصل سرعتها إلى 49 كم/ساعة، تتسبب في تدنٍّ مماثل في مدى الرؤية الأفقية بين 3 و5 كيلومترات، وتطال محافظات ثار ويدمة وخباش، على أن تستمر الحالة حتى الساعة السابعة مساءً.","ويُوصي المركز الوطني للأرصاد السائقين وقاطني المناطق المتأثرة بتوخي الحذر وتجنب التنقل غير الضروري خلال فترة سريان التنبيهين."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ko385i2','https://sabq.org/article/ko385i2','','https://sabq.org/article/ko385i2','صحيفة سبق','السعودية','2026-08-13T02:28:00.000Z','2026-08-13T05:29:00.000Z','2026-08-13T21:26:35.182Z','https://media.sabq.org/news/2026/08/90af67fd-979d-40a5-a6b2-45a85478e1be/w739.webp','/api/media/62ed1540-827b-4658-ac62-badd8d1805b1','/api/media/62ed1540-827b-4658-ac62-badd8d1805b1?variant=thumbnail','الأرصاد تحذر من رياح نشطة وأتربة مثارة في حائل ونجران',739,417,'valid','published','archived','valid',45,'98886681b6f8fa338276407c9841f9c8ce1c5256c85e463e8aac611a182bc1d0','73fe53d966de1bbdafd0feacaedf9c0b3bd977bdba6c5246413891b800d2a8a6','محدّث','2026-08-13T21:26:35.182Z','2026-10-07T20:58:48.111Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["نجران"]','[]','manual_approved','below_category_threshold','[{"category":"البيئة والمناخ","score":2},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:58:48.111Z',200,90,0,'source_article_available','',NULL,NULL,'body:1e6d17d088c19fbf9fe5fb582e419c63f0338cd57635ccda021bfb846acbf880','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('29e9a8b3-5bfe-40c8-bb53-25e1c235598d','news-29e9a8b3-5bfe-40c8-bb53-25e1c235598d','حرس الحدود بالوجه يضبط مواطنين مارسا الصيد دون تصريح بأدوات محظورة','حرس الحدود بالوجه يضبط مواطنين مارسا الصيد دون تصريح بادوات محظوره','ضبطت الدوريات الساحلية لحرس الحدود في محافظة الوجه بمنطقة تبوك مواطنَين مخالفَين للائحة الأمن والسلامة لمزاولي الأنشطة البحرية في المناطق البحرية للمملكة، وذلك لممارستهما الصيد دون تصريح واستخدامهما أدوات محظورة، وطُبِّقت الإجراءات النظامية بحقهما بالتنسيق مع الجهات المختصة.','["وأهاب حرس الحدود بالجميع الالتزام بالأنظمة والتعليمات المتعلقة بحماية الثروات المائية الحية، والإبلاغ عن أي حالات تمثّل اعتداءً على البيئة أو الحياة الفطرية، وذلك بالاتصال على الرقم 911 في مناطق مكة المكرمة والمدينة المنورة والرياض والمنطقة الشرقية، والرقم 994 في بقية مناطق المملكة، مع ضمان السرية التامة لجميع البلاغات دون أي مسؤولية على المُبلِّغ."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/z8m1rkw','https://sabq.org/article/z8m1rkw','','https://sabq.org/article/z8m1rkw','صحيفة سبق','السعودية','2026-08-13T03:14:00.000Z','2026-08-13T06:15:00.000Z','2026-08-13T21:26:36.903Z','https://media.sabq.org/news/2026/08/e79e9278-5564-40f9-85ba-c6bc5026f01a/w1600.webp','/api/media/29e9a8b3-5bfe-40c8-bb53-25e1c235598d','/api/media/29e9a8b3-5bfe-40c8-bb53-25e1c235598d?variant=thumbnail','حرس الحدود بالوجه يضبط مواطنين مارسا الصيد دون تصريح بأدوات محظورة',1600,981,'valid','published','archived','valid',50,'def8e2bb7cf5c30902337e732b56db07355daeda2e7eff5dc02f08e06f8b05aa','d9248566170331c3abdbe1a26cdc4d8576b36718ea20ceb82c4c77f1fc59543c','محدّث','2026-08-13T21:26:36.903Z','2026-10-07T20:58:18.161Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","مكة","الرياض","المدينة المنورة"]','["التعليم والتدريب","المدينة المنورة"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5}]','Temporarily Unreachable','2026-10-07T20:58:18.161Z',NULL,87,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fe532223-e231-4386-a80a-98b02371e318','news-fe532223-e231-4386-a80a-98b02371e318','الحزم يضرب أبها بثنائية في افتتاح مشواره بالدوري السعودي','الحزم يضرب ابها بثنائيه في افتتاح مشواره بالدوري السعودي','حقق فريق الحزم فوزًا مهمًا على مضيفه أبها بنتيجة 2-1، في المباراة التي جمعت الفريقين مساء اليوم الخميس، ضمن منافسات الجولة الأولى من الدوري السعودي "دوري روشن".','["وضع عبد العزيز سليمان الضويحي الحزم في المقدمة مبكرًا، بعدما سجل الهدف الأول في الدقيقة الثالثة، قبل أن يضيف أحمد محمد الشمراني الهدف الثاني عند الدقيقة 40، لينهي الفريق الشوط الأول متقدمًا بثنائية نظيفة.","وحاول أبها العودة إلى المباراة في الشوط الثاني، ونجح محمد الدوسري في تقليص الفارق بتسجيل هدف أصحاب الأرض في الدقيقة 64، إلا أن الحزم حافظ على تقدمه حتى صافرة النهاية، ليحصد أول ثلاث نقاط له في المسابقة.","ويستعد الحزم لمواجهة الدرعية يوم 21 أغسطس الجاري، ضمن منافسات الجولة الثانية من الدوري السعودي، بينما يحل أبها ضيفًا على الأهلي السعودي يوم 22 أغسطس في الجولة ذاتها."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/1nmlogac1','https://ajel.sa/sports/1nmlogac1','https://ajel.sa/sports/1nmlogac1','https://ajel.sa/sports/1nmlogac1','فريق التحرير','السعودية','2026-08-13T12:45:00.000Z','Wed, 07 Oct 2026 20:58:57 GMT','2026-08-13T23:27:45.970Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-EKEI5s7u.jpg','/api/media/fe532223-e231-4386-a80a-98b02371e318','/api/media/fe532223-e231-4386-a80a-98b02371e318?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',99,'d6c5f26594757bcbe386cfa61fa2c6b0415e160827e8c3512ce2538a9d0e55b6','03d23dab706b771e40fefbc493597ec5c51c241e00799039ae0e50277e5be07a',NULL,'2026-08-13T23:27:45.970Z','2026-10-07T20:58:59.434Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Updated','2026-10-07T20:58:59.434Z',200,79,0,'source_content_changed','',NULL,NULL,'body:6edea2e2a96f63ab64aeb95b1ea45101a72685340a4b960ba21ce2950b74362c','Wed, 07 Oct 2026 20:58:57 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e9615f85-ffaa-4e16-aef5-c25964d703ae','news-e9615f85-ffaa-4e16-aef5-c25964d703ae','المملكة تعزي مصر في ضحايا حادث الإسماعيلية وتعلن تضامنها مع أسر الضحايا','المملكه تعزي مصر في ضحايا حادث الاسماعيليه وتعلن تضامنها مع اسر الضحايا','أعربت وزارة الخارجية عن خالص تعازي المملكة وصادق مواساتها إلى حكومة وشعب جمهورية مصر العربية في ضحايا الحادث المروري الذي وقع في محافظة الإسماعيلية . وأكدت الوزارة تضامن المملكة مع مصر في هذا المصاب الأليم، معربةً عن خالص تعازيها ومواساتها لأسر الضحايا، وتمنياتها للمصابين بالشفاء العاجل.','["أعربت وزارة الخارجية عن خالص تعازي المملكة وصادق مواساتها إلى حكومة وشعب جمهورية مصر العربية في ضحايا الحادث المروري الذي وقع في محافظة الإسماعيلية .","وأكدت الوزارة تضامن المملكة مع مصر في هذا المصاب الأليم، معربةً عن خالص تعازيها ومواساتها لأسر الضحايا، وتمنياتها للمصابين بالشفاء العاجل."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/f16d92aq4','https://ajel.sa/local/f16d92aq4','https://ajel.sa/local/f16d92aq4','https://ajel.sa/local/f16d92aq4','فريق التحرير','السعودية','2026-08-13T12:45:00.000Z','Wed, 07 Oct 2026 20:58:48 GMT','2026-08-13T23:27:46.449Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D9%85%D9%85%D9%84%D9%83%D8%A9-%D8%A7%D9%84%D8%B9%D8%B1%D8%A8%D9%8A%D8%A9-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-AtSrtwkP.jpg','/api/media/e9615f85-ffaa-4e16-aef5-c25964d703ae','/api/media/e9615f85-ffaa-4e16-aef5-c25964d703ae?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',49,'30da02e82188e9d5f51d3bc8f2ece5e810d8f8200123ca3723ec96dca9113bf1','27ac0acbc2729450eff0fba0b5377a7abf8997daee89c64495324d5b35fc2a4c',NULL,'2026-08-13T23:27:46.449Z','2026-10-07T20:58:50.519Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الخارجية عن خالص تعازي"]','["وزارة الخارجية عن خالص تعازي"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":4},{"category":"السياسة","score":3.5},{"category":"أخبار السعودية","score":3}]','Updated','2026-10-07T20:58:50.519Z',200,79,0,'source_content_changed','',NULL,NULL,'body:8fdf11cc5326d9c4bf744fea2dec30001850ae4561e8831264ef6def8683d9e0','Wed, 07 Oct 2026 20:58:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('61fabac6-3f79-4c42-9beb-2e0918a6c52d','news-61fabac6-3f79-4c42-9beb-2e0918a6c52d','رسميًا.. فلاهوفيتش ينتقل إلى بشكتاش في صفقة انتقال حر','رسميا فلاهوفيتش ينتقل الي بشكتاش في صفقه انتقال حر','تعاقد نادي بشكتاش التركي، اليوم، مع المهاجم الصربي دوشان فلاهوفيتش في صفقة انتقال حر، لتدعيم صفوف الفريق خلال الموسم الجديد. وبانتقاله إلى بشكتاش، يخوض فلاهوفيتش تجربة جديدة في الدوري التركي، بعدما أنهى مسيرته مع يوفنتوس الذي انضم إليه قادمًا من فيورنتينا .','["تعاقد نادي بشكتاش التركي، اليوم، مع المهاجم الصربي دوشان فلاهوفيتش في صفقة انتقال حر، لتدعيم صفوف الفريق خلال الموسم الجديد.","وأعلن النادي التركي، في بيان رسمي، تعاقده مع الدولي الصربي لمدة 3 مواسم، بعد رحيله عن صفوف يوفنتوس عقب انتهاء عقده مع النادي الإيطالي.","وكان عقد فلاهوفيتش مع يوفنتوس قد انتهى في 30 يونيو الماضي، دون التوصل إلى اتفاق بين الطرفين بشأن التجديد، ليصبح اللاعب حرًا في تحديد وجهته الجديدة."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/w83534typ','https://ajel.sa/sports/w83534typ','https://ajel.sa/sports/w83534typ','https://ajel.sa/sports/w83534typ','فريق التحرير','السعودية','2026-08-13T13:13:00.000Z','Wed, 07 Oct 2026 20:52:55 GMT','2026-08-13T23:27:47.832Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%81%D9%84%D8%A7%D9%87%D9%88%D9%81%D9%8A%D8%AA%D8%B4-03_SOgFf.jpg','/api/media/61fabac6-3f79-4c42-9beb-2e0918a6c52d','/api/media/61fabac6-3f79-4c42-9beb-2e0918a6c52d?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',58,'fbd0335b6815664c35e2079a82da34b5b96369248ab970a5005d26c69355f845','d03d8cc97002f6a92c8c2e051ae0c9c5ae607c76ee4dad77f35cd77bcffb3cbb',NULL,'2026-08-13T23:27:47.832Z','2026-10-07T20:52:56.652Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:52:56.652Z',200,77,0,'source_article_available','',NULL,NULL,'body:1ba2b6b83ffe7c19d647f4b1ed62ca3ae7630e9d2ad265a737d67c0ef04ccdb1','Wed, 07 Oct 2026 20:52:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3de113fe-30ff-4475-a5b3-b23e9a63bfe2','news-3de113fe-30ff-4475-a5b3-b23e9a63bfe2','خطوة رئيسية نحو تفعيله.. عقد اجتماع التخطيط الثالث للتحالف الدفاعي بمشاركة 39 دولة في جدة','خطوه رئيسيه نحو تفعيله عقد اجتماع التخطيط الثالث للتحالف الدفاعي بمشاركه 39 دوله في جده','عُقد في قيادة الأسطول الغربي بمدينة جدة اجتماع التخطيط الثالث للتحالف البحري الدفاعي متعدد الجنسيات (MMDC)، بمشاركة ممثلين عن (39) دولة شقيقة وصديقة، في خطوة رئيسية نحو تفعيل التحالف.','["وبلغ عدد الدول الموقعة على البيان المشترك (15) دولة، فيما استكملت (13) دولة إجراءاتها الوطنية ووقعت على ميثاق التحالف وأعلنت انضمامها رسميًا، بما يمثل الانطلاقة الفعلية للتحالف نحو مرحلة التفعيل المؤسسي والعملياتي، فيما تواصل بقية الدول استكمال إجراءاتها الوطنية اللازمة للانضمام إلى التحالف.","ويأتي هذا التطور بالتوازي مع التقدم المتسارع في استكمال عناصر البناء المؤسسي للتحالف، بما في ذلك تعيين قائد التحالف من المملكة العربية السعودية ، والتوافق على أن يكون نائب قائد التحالف في دورته الأولى من جمهورية باكستان الإسلامية ، وتحديد المقر المخصص لقيادة التحالف واعتماد شعاره، إلى جانب استكمال الأطر التنظيمية والتخطيطية والأدلة المرجعية اللازمة لبدء أعماله.","كما أسهم اجتماع التخطيط الثالث في استكمال الترتيبات العملية لتفعيل أجهزة التحالف وقيادته متعددة الجنسيات، تمهيدًا لبدء استقبال الضباط والكوادر المشاركة من الدول الأعضاء ومجمعهم ضمن هيكل القيادة والأركان المشتركة، ومركز العمليات والتنسيق البحري المشترك، ومركز استخبارات التحالف، بما يسرّع بناء قدراته العملياتية ويعزز جاهزيته للاطلاع بمهامه الدفاعية ضمن قطاع مسؤوليته."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/u9x8xmnhh','https://ajel.sa/local/u9x8xmnhh','https://ajel.sa/local/u9x8xmnhh','https://ajel.sa/local/u9x8xmnhh','فريق التحرير','السعودية','2026-08-13T13:18:00.000Z','Wed, 07 Oct 2026 20:52:56 GMT','2026-08-13T23:27:49.408Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/1000940689-crop-isZTytKh.jpg','/api/media/3de113fe-30ff-4475-a5b3-b23e9a63bfe2','/api/media/3de113fe-30ff-4475-a5b3-b23e9a63bfe2?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',48,'50c27ffc1b814c3405c6e815f9a3c18950f19bd364490b010f0e5afa10f8acfa','5e3ddb4c5dc5322ee8c93447eb0509d54d3fafd67c691b9111378a995b4ca8a8',NULL,'2026-08-13T23:27:49.408Z','2026-10-07T20:52:57.395Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","جدة"]','["الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":3},{"category":"الاقتصاد","score":3}]','Active','2026-10-07T20:52:57.395Z',200,77,0,'source_article_available','',NULL,NULL,'body:f4b8fa2370dcf82b9cd161762a1cbdffad7d93f09a1d575ef646f1fb60798218','Wed, 07 Oct 2026 20:52:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('152a3947-c620-424c-9b3a-63b1e1c73be0','news-152a3947-c620-424c-9b3a-63b1e1c73be0','اتفاقية مكة مسمار في نعش مشاريع ملوك الطوائف','اتفاقيه مكه مسمار في نعش مشاريع ملوك الطوائف','لم أكتب في السياسة لا لأنني لا أعرف الكتابة، ولكن لأنني لم أقرأ ما يكفي من التاريخ.','["لم أكتب في السياسة لا لأنني لا أعرف الكتابة، ولكن لأنني لم أقرأ ما يكفي من التاريخ. التاريخ في نظري هو (تدفق السياسة عبر الزمن). من يقرأ الحادثة السياسية ولا يتداعى مسارها التاريخي وأشباهها من حوادث التاريخ - في ذهنه أثناء الكتابة - لا علاقة له بالكتابة السياسية.","من يكتب عن اتفاقية مكة وهو لا يعرف كيف مُحيت الحضارة الإسلامية في الأندلس من وجه الأرض بعد ثمانية قرون من الحضارة والازدهار لا يعرف عن ماذا يكتب.","ما الذي يجري في العراق الآن؟ سيقول كاتب التعليق السياسي: إيران هي من تقف وراء هذه الفوضى. غياب الوعي بالتاريخ عن ثقافة هؤلاء هو الذي يقودهم إلى هذا الجواب السهل والمباشر. إليك قطعة صغيرة من تدفق التاريخ.","لو عدنا قليلاً قبل أن تتغلغل إيران في العراق سنرى أن أمريكا غزت العراق وأول شيء فعلته أن هدمت الدولة العراقية. ولو رجعنا قليلاً قبل هذا سنرى أن صدام حسين غزا الكويت ودمر ما تبقى من التضامن العربي. ثم لو رجعنا بالزمن أكثر قليلاً سنرى أن صدام حسين استغل اضطرابات الثورة الإيرانية فمزق اتفاقية الجزائر بين إيران الشاه والعراق، تلك الاتفاقية التي وقعها بيده ثم أعلن الحرب على إيران. كانت إيران حينها متضعضعة. اندلعت فيها…"]','الثقافة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/na/2261239','https://www.okaz.com.sa/articles/na/2261239','','https://www.okaz.com.sa/articles/na/2261239','عبدالله بن بخيت','السعودية','2026-08-13T18:07:00.000Z','Wed, 07 Oct 2026 18:31:07 GMT','2026-08-13T23:27:49.648Z','https://www.okaz.com.sa/uploads/authors/1503.jpg','/api/media/152a3947-c620-424c-9b3a-63b1e1c73be0','/api/media/152a3947-c620-424c-9b3a-63b1e1c73be0?variant=thumbnail','اتفاقية مكة مسمار في نعش مشاريع ملوك الطوائف',400,396,'valid','published','archived','valid',44,'e17e0f97c9aa2559b72c2a2f6b6c4d7ff761331314dbbb67e4815a80a7c50d0d','5090432384b883a09758f0a20ba1447fb4d1642a5bd18863873d677cbb94c77f',NULL,'2026-08-13T23:27:49.648Z','2026-10-07T20:51:48.860Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","السياسة والعلاقات الدولية","مكة","إيران","العراق"]','["الثقافة والفنون","السياسة والعلاقات الدولية"]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":3},{"category":"المجتمع","score":1.5},{"category":"الرياضة","score":1.5}]','Active','2026-10-07T20:51:48.860Z',304,78,0,'source_article_available','',NULL,NULL,'body:ea1f03076dee5933236dc03cf092965825c93ff37b0b519bb41ed0071446f25b','Wed, 07 Oct 2026 18:31:07 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f8f39467-573a-49f5-94e8-65132a56901d','news-f8f39467-573a-49f5-94e8-65132a56901d','من الموهبة إلى منصات العالم.. إنجازات سعودية تتحدث عن نفسها','من الموهبه الي منصات العالم انجازات سعوديه تتحدث عن نفسها','تواصل المملكة العربية السعودية ترسيخ حضورها في المحافل العالمية عبر سلسلة من الإنجازات التي يحققها أبناء وبنات الوطن في المجالات العلمية والرياضية والثقافية، في صورة تعكس حجم التحول الذي تشهده المملكة، وثمرة الاستثمار في الإنسان، وتمكين المواهب والكفاءات الوطنية من المنافسة وصناعة الإنجاز، وصولًا إلى منصات التتويج العالمية.','["ويأتي هذا الحضور ثمرة منظومة متكاملة لاكتشاف المواهب وتأهيلها وصقل قدراتها، وتوفير بيئة داعمة للإبداع والابتكار والتميز. وفي ميادين العلم والرياضة والثقافة تتجسد هذه الجهود في مواهب سعودية تشق طريقها بثقة نحو المنافسات الدولية، وتحول قدراتها وطموحاتها إلى إنجازات ترفع اسم الوطن في المحافل العالمية.","وفي المجال العلمي، سجل أبناء الوطن حضورًا مشرفًا في أولمبياد الرياضيات الدولي 2026، الذي استضافته مدينة شنغهاي الصينية بمشاركة 117 دولة، في مشاركة تعكس تنامي القدرات العلمية لدى الطلبة السعوديين وتطور منظومة رعاية الموهوبين وتأهيلهم للمنافسات الدولية.","وفي إنجاز علمي جديد، توّج الأمين العام لمؤسسة الملك عبدالعزيز ورجاله للموهبة والإبداع «موهبة»، الأستاذ عبدالعزيز الكريديس، الطالب السعودي أمجد آل درويش بالمركز الأول في أولمبياد العلوم النووية الدولي، إلى جانب حصوله على لقب سفير العلوم النووية، في إنجاز يضاف إلى سجل النجاحات العلمية السعودية، ويجسد ما يمتلكه أبناء الوطن من قدرات متميزة في المجالات العلمية النوعية والمستقبلية.","وفي إنجاز علمي لافت، حققت الطالبة السعودية جنى صالح عبدالله السبيل الميدالية الذهبية في النسخة الثالثة من أولمبياد العلوم النووية الدولي 2026، إلى جانب فوزها بجائزة «أفضل طالبة» المقدمة من الوكالة الدولية للطاقة الذرية، تقديرًا لتميزها العلمي وأدائها في منافسات الأولمبياد."]','أخبار السعودية','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/na/2261237','https://www.okaz.com.sa/articles/na/2261237','','https://www.okaz.com.sa/articles/na/2261237','عبدالله العبيدي','السعودية','2026-08-13T18:07:00.000Z','Wed, 07 Oct 2026 18:31:09 GMT','2026-08-13T23:27:50.146Z','https://www.okaz.com.sa/okaz/uploads/authors/1903.jpg?v=1781805134','/api/media/f8f39467-573a-49f5-94e8-65132a56901d','/api/media/f8f39467-573a-49f5-94e8-65132a56901d?variant=thumbnail','من الموهبة إلى منصات العالم.. إنجازات سعودية تتحدث عن نفسها',400,400,'valid','published','archived','valid',52,'6d02a9f54ab9cb95fa4e3df80c32040d688f076062c3560bca142af03674342d','b1fba6caf001fa6b820bc55da0c330b0458137cb40de700f8896f52e5a21fea8',NULL,'2026-08-13T23:27:50.146Z','2026-10-07T20:51:50.803Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق","الصين","الرياض"]','["الطاقة والنفط","الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T20:51:50.803Z',304,78,0,'source_article_available','',NULL,NULL,'body:071d0cb47274d2ea70b4f8f85deb4f82ebe7486526ccb93677b78a6b991f2625','Wed, 07 Oct 2026 18:31:09 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('63338137-3d28-4db9-86b4-5bae2a00e2eb','news-63338137-3d28-4db9-86b4-5bae2a00e2eb','خبير يكشف سر الإنجاز التاريخي لميناء جدة الإسلامي: الاستثمارات رفعت كفاءة المناولة','خبير يكشف سر الانجاز التاريخي لميناء جده الاسلامي الاستثمارات رفعت كفاءه المناوله','وأوضح الدلبحي، في تصريحات عبر قناة «الإخبارية»، أن إجمالي عدد الحاويات التي تمت مناولتها في الميناء خلال يوليو بلغ 540.107 حاويات قياسية، وهو أعلى مستوى تسجله عمليات المناولة في تاريخ ميناء جدة الإسلامي.','["أكد المحكم والخبير الهندسي المهندس سعود الدلبحي أن الاستثمارات في الأرصفة والمعدات والحلول الرقمية رفعت كفاءة المناولة في ميناء جدة الإسلامي وعززت الربط بخطوط الشحن العالمية، بالتزامن مع تسجيل الميناء أعلى مستوى في تاريخه لمناولة الحاويات خلال يوليو 2026.","وبحسب المعطيات الصادرة عن الهيئة العامة للموانئ « موانئ »، توزعت عمليات المناولة بين 155.270 حاوية صادرة و206.927 حاوية واردة، إضافة إلى 138.615 حاوية مسافنة و39,295 حاوية ترانزيت.","وأشار الدلبحي إلى أن نشاط الميناء لا يقتصر على حركة الحاويات، إذ شهدت بواباته حركة عبور للشاحنات دخولًا وخروجًا بلغت نحو 20 ألف شاحنة يوميًا."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/zp08l5yyl','https://ajel.sa/local/zp08l5yyl','https://ajel.sa/local/zp08l5yyl','https://ajel.sa/local/zp08l5yyl','فريق التحرير','السعودية','2026-08-13T14:08:00.000Z','Wed, 07 Oct 2026 20:58:48 GMT','2026-08-13T23:27:51.196Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%85%D9%8A%D9%86%D8%A7%D8%A1-%D8%AC%D8%AF%D8%A9-36hp6ZvM.webp','/api/media/63338137-3d28-4db9-86b4-5bae2a00e2eb','/api/media/63338137-3d28-4db9-86b4-5bae2a00e2eb?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',92,'bb854f5b78c47001be74d73683bf19f9813d0c9b4c47f7819659436bb60078be','6c61be1e86005eb0075a992124e7135709aedc5c13d6dd1f874518bf6dbc6289',NULL,'2026-08-13T23:27:51.196Z','2026-10-07T20:58:50.511Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","التقنية والتحول الرقمي","جدة"]','["الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"المناطق","score":3},{"category":"التقنية","score":1.5},{"category":"الثقافة","score":1.5}]','Updated','2026-10-07T20:58:50.511Z',200,76,0,'source_content_changed','',NULL,NULL,'body:d937e7ffc3641b5ab0bdec1d96e74cbca6bce979ac61a15f55976f68168a0458','Wed, 07 Oct 2026 20:58:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('575dc0cf-6562-4095-8f61-1491dab18eb6','news-575dc0cf-6562-4095-8f61-1491dab18eb6','الشرق الأوسط بين الحرب والسلام','الشرق الاوسط بين الحرب والسلام','يقف الشرق الأوسط اليوم عند مفترق طرق تاريخي، تتجاذبه احتمالات الحرب من جهة، وآمال السلام من جهة أخرى، فمنذ عقود لم تعرف المنطقة استقرارًا طويل الأمد، إذ سرعان ما تتحوّل محاولات التهدئة إلى موجات جديدة من التوتر، لتعود الأزمات إلى الواجهة، ومع التطورات الأخيرة وعودة المواجهات العسكرية بين الولايات المتحدة وإيران، يتجدّد السؤال القديم: هل يستطيع الشرق الأوسط أ','["لا تقتصر آثار الحروب على ساحات القتال، بل تمتد إلى الاقتصاد والتعليم والصحة والاستثمار وفرص العمل وجودة الحياة، وكلما اندلعت أزمة جديدة تراجعت خطط التنمية وارتفعت مستويات القلق وتأثرت حركة التجارة وتحولت الأولويات إلى محاولة إدارة الأزمات بدلًا من صناعة المستقبل، ورغم ذلك فقد أظهرت السنوات الأخيرة تحوّلًا مهمًا في توجهات عدد من دول المنطقة، فقد أصبح الاستثمار في الاقتصاد وتنويع مصادر الدخل وتطوير البنية التحتية…","غير أن طريق السلام لا يزال مليئًا بالعقبات؛ فالشرق الأوسط يحمل إرثًا طويلًا من الخلافات السياسية والأمنية، كما أن تشابك المصالح الإقليمية والدولية يجعل أي أزمة محلية قابلة للتحوّل إلى أزمة أوسع، ولهذا فإن أي تصعيد عسكري لا يبقى محصورًا داخل حدود دولة واحدة، بل تمتد آثاره إلى المنطقة بأسرها -وربما إلى الاقتصاد العالمي- خاصة عندما يتعلق الأمر بأمن الممرات البحرية أو أسواق الطاقة.","من المؤكد أن السلام لا يعني غياب الخلافات، بل يعني وجود آليات قادرة على إدارتها دون اللجوء إلى السلاح، وهذا هو التحدي الحقيقي الذي يواجه الشرق الأوسط اليوم، فقد تتباين الدول فيما يتعلق بالرؤى والمصالح، لكن نجاحها في معالجة هذه الخلافات بالحوار يمنع تحوّلها إلى نزاعات مفتوحة تستنزف الجميع، وقد أثبتت العديد من التجارب أن الحرب مهما حققت من مكاسب عسكرية مؤقتة، لا تستطيع وحدها أن تفرض استقرارًا دائمًا، فبعد كل جولة من…","كما أن المجتمع الدولي يتحمّل مسؤولية كبيرة في دعم الاستقرار الإقليمي، فالمنطقة تمثل أهمية إستراتيجية للعالم، سواء من حيث الطاقة أو التجارة أو الموقع الجغرافي، ومن ثم فإن أي اضطراب فيها ينعكس على الاقتصاد العالمي، ويؤثر في سلاسل الإمداد، ويزيد من حالة عدم اليقين في الأسواق الدولية، لذلك فإن دعم جهود الوساطة وتشجيع الحلول السياسية ليس مصلحة إقليمية فحسب، بل مصلحة دولية أيضًا."]','المجتمع','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2261235','https://www.okaz.com.sa/articles/authors/2261235','','https://www.okaz.com.sa/articles/authors/2261235','محمد مفتي','السعودية','2026-08-13T18:07:00.000Z','Wed, 07 Oct 2026 18:31:07 GMT','2026-08-13T23:27:51.407Z','https://www.okaz.com.sa/okaz/uploads/authors/294.jpg?v=1762092635','/api/media/575dc0cf-6562-4095-8f61-1491dab18eb6','/api/media/575dc0cf-6562-4095-8f61-1491dab18eb6?variant=thumbnail','الشرق الأوسط بين الحرب والسلام',400,400,'valid','published','archived','valid',89,'397b8072c83ef386015cd1d703c1a6213144df3546f423c57cb403176f31d20d','69a41650a507a04085a7087dcb69f356d571844767715a894a79a3212e1c1835',NULL,'2026-08-13T23:27:51.407Z','2026-10-07T20:51:48.867Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الطاقة والنفط","التعليم والتدريب","الاقتصاد والأسواق","الشرق الأوسط"]','["الصحة العامة","الطاقة والنفط","التعليم والتدريب","الاقتصاد والأسواق","الشرق الأوسط"]','manual_approved','','[]','Active','2026-10-07T20:51:48.867Z',304,77,0,'source_article_available','',NULL,NULL,'body:4b52f12f88fb27fd986450f869f9345e6107367fa7dbd20415c397d5a9279f7e','Wed, 07 Oct 2026 18:31:07 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f722c00d-9a38-4a56-82eb-915a39de186d','news-f722c00d-9a38-4a56-82eb-915a39de186d','جدة مزاجي وأمواجي..','جده مزاجي وامواجي','لجدة ذاكرة لا تشبه المدن؛ ذاكرة تفوح منها رائحة البحر، وتختبئ في ظلال الرواشين، وتنساب في الأزقة القديمة كحكاية لا تريد أن تنتهي في وجدان المتلقي، مدينة كانت تستقبل القادمين من البحر، وتودّع الراحلين إليه، وتفتح أبوابها للتجارة والحجاج والثقافات، حتى أصبح البحر جزءًا من شخصيتها، لا مجرد امتداد جغرافي أمامها.','["وحين أتأمل جدة التاريخية اليوم، أتخيل تلك العلاقة القديمة وهي تستعيد شيئًا من نبضها؛ كأن البحر الذي ظل طويلًا على مسافة من «البلد» يقترب منها من جديد، وكأن المدينة تستعيد نافذة كانت تطل منها على العالم.","من هنا تبدو فكرة مشروع وزارة الثقافة بإنشاء بوابة بحرية ومارينا متكامل في جدة التاريخية أكبر من مشروع عمراني أو وجهة سياحية جديدة؛ إنها محاولة لإعادة وصل جدة بذاكرتها البحرية، واستعادة جزء من صورتها الأولى وهي تنظر إلى البحر بوصفه طريقًا للحياة والعالم.","تخيّل معي ستكون واجهة البلد في جدة التاريخية مرسى ونادي يخوت ومطاعم ومقاهي فارهة بمعنى ستصبح جدة التاريخية ذاكرة جديدة معجونة بالذاكرة الأولى؛ فجدة التاريخية ليست بيوتًا قديمة وأزقة تحفظ ذاكرة المكان فحسب؛ إنها مدينة كانت نابضة بالحركة، مفتوحة على البحر، وعلى التجارة والثقافات وحكايات العابرين. ولذلك فإن إعادة البحر إلى قلب تجربتها يمكن أن تمنح «البلد» حياة جديدة، من دون أن تفقد ملامحها القديمة.","تخيّل معي أيضًا أن يبدأ الزائر رحلته بين الرواشين والأبواب والأسواق، ثم ينتهي به الطريق عند البحر؛ فيرى المراكب أمامه، وتبقى العمارة التاريخية خلفه، فيلتقي في مشهد واحد ماضي جدة بمستقبلها ! هنا لا يصبح المرسى مجرد مكان للقوارب، بل مساحة للحياة؛ مطاعم ومقاهٍ، أنشطة بحرية، مساحات عامة، فعاليات ثقافية، وتجارب تحكي قصة جدة مع البحر الأحمر."]','السفر','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2261234','https://www.okaz.com.sa/articles/authors/2261234','','https://www.okaz.com.sa/articles/authors/2261234','منى العتيبي','السعودية','2026-08-13T18:07:00.000Z','Wed, 07 Oct 2026 18:31:09 GMT','2026-08-13T23:27:51.446Z','https://www.okaz.com.sa/uploads/authors/1112.jpg','/api/media/f722c00d-9a38-4a56-82eb-915a39de186d','/api/media/f722c00d-9a38-4a56-82eb-915a39de186d?variant=thumbnail','جدة مزاجي وأمواجي..',709,709,'valid','published','archived','valid',52,'eca2ef652fa125bed7f56deadeb1efe77532a280b9fb9a0d30121d5c764bd98f','d01da4bf8ad88323bdc5728b07cbe2589f9fdaa615174e8727c4412047b6b7b3',NULL,'2026-08-13T23:27:51.446Z','2026-10-07T20:51:50.332Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الثقافة بإنشاء بوابة بحرية","الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق","جدة"]','["وزارة الثقافة بإنشاء بوابة بحرية","الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":5},{"category":"الاقتصاد","score":3},{"category":"الرياضة","score":1.5}]','Active','2026-10-07T20:51:50.332Z',304,76,0,'source_article_available','',NULL,NULL,'body:8b014b5f98743c3db61d849067ee79f2cd21e171e346a98a4383ea16fcab2dff','Wed, 07 Oct 2026 18:31:09 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('583e8c8d-e0ba-4e6b-a67e-93fe3336cf63','news-583e8c8d-e0ba-4e6b-a67e-93fe3336cf63','النموذج الذي تريده إيران على دول المنطقة..','النموذج الذي تريده ايران علي دول المنطقه','وصلت الحرب الأمريكية-الإيرانية إلى تقاطع طرق سوف يحدد ليس فقط شكل المنطقة بل أيضًا العالم.','["وصلت الحرب الأمريكية-الإيرانية إلى تقاطع طرق سوف يحدد ليس فقط شكل المنطقة بل أيضًا العالم. إيران عبر تاريخها، تعتمد على سياسة الاستنزاف وتستفيد منها ليس فقط للحفاظ على وجود نظامها، بل أيضًا لاستثمار «ثقافة الصمود» في الحروب على المستويين الخارجي والداخلي.","ففي الداخل، كانت تستثمر لعبة التهديد الوجودي وصمود النظام لإحكام القبضة العسكرية على الداخل. أما خارجيًا، وهنا الأهم، استطاعت إيران رغم الحروب ورغم الحصار والإخفاقات التي تعرّضت لها، أن تبني ترسانة نفوذها عبر تقوية وكلائها الممتدين بشكل مباشر في اليمن والعراق ولبنان وفلسطين وسوريا، سياسيًا وإعلاميًا واقتصاديًا واجتماعيًا وعسكريًا. من «درّة تاجها» حزب الله مرورًا بالحوثيين في اليمن، والفصائل الأخرى في العراق، أنتجت…","كما أن أخطر ما أنتجته إيران في المنطقة هو لا مركزية العمل لوكلائها على مستوى العمليات، وفي الوقت نفسه بناء شبكة معرفية عملياتية مرتبطة ببعضها البعض تتبادل الخبرات العسكرية والموارد المالية وغيرها. فعلى سبيل المثال لا الحصر، تم اختبار تكتيكات وقدرات جديدة في ساحات القتال وتطوير الأدوات والإستراتيجيات في استخدام الطائرات المسيّرة والعمل على الاستفادة من الأخطاء التي وقعت في الحروب الماضية. هذه الاختبارات استفادت منها…","تسعى إيران عبر نظامها إلى تثبيت نموذج إقليمي يقوم على دول تحتفظ بحدودها ومؤسساتها الرسمية، فيما تبقى قراراتها السيادية الكبرى ومستقبلها رهينة قوى مسلّحة موازية للدولة، تمتلك حق التعطيل في الداخل وترتبط إستراتيجيًا بطهران. فمن خلال هؤلاء، تحقق إيران موطئ قدم لها إستراتيجي قرب المضائق المؤدية إلى القرن الإفريقي. وفي أدوات الحروب الحالية، من يسيطر على الممرّات والمضائق يبني النفوذ."]','السياسة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2261233','https://www.okaz.com.sa/articles/authors/2261233','','https://www.okaz.com.sa/articles/authors/2261233','حياة الحريري','السعودية','2026-08-13T18:07:00.000Z','Wed, 07 Oct 2026 18:31:09 GMT','2026-08-13T23:27:52.637Z','https://www.okaz.com.sa/okaz/uploads/authors/1911.jpg?v=1786031254','/api/media/583e8c8d-e0ba-4e6b-a67e-93fe3336cf63','/api/media/583e8c8d-e0ba-4e6b-a67e-93fe3336cf63?variant=thumbnail','النموذج الذي تريده إيران على دول المنطقة..',400,400,'valid','published','archived','valid',53,'ceea02cbce043de86f97f12142cb99b2d0524cfc69a903e30a466d52b2bbcf84','379431c0a5a095cb69038ceaaa3523a3c0b082f96809f1c248453f6a894019e5',NULL,'2026-08-13T23:27:52.637Z','2026-10-07T20:51:50.494Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","الاقتصاد والأسواق","السياسة والعلاقات الدولية","سوريا","لبنان","اليمن","إيران","فلسطين"]','["الثقافة والفنون","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":4},{"category":"المجتمع","score":3},{"category":"العالم","score":3}]','Active','2026-10-07T20:51:50.494Z',304,78,0,'source_article_available','',NULL,NULL,'body:fd539747fc52210edf20ddcdea4ab392d8aeb10258962aa9822e3b1ab3566fad','Wed, 07 Oct 2026 18:31:09 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dbdf7e51-68d2-45f9-94fb-8fc4c066b28c','news-dbdf7e51-68d2-45f9-94fb-8fc4c066b28c','عندما يصير الرقم إنسانًا','عندما يصير الرقم انسانا','غير أنه عندما يصبح الرقم مطلبًا وهاجسًا يسعى المرء إلى تحقيق السبق فيه، فعندئذ يكون هناك خلل يوجب التوقف عنده. لأن تحول الوسيلة (الرقم) إلى غاية، يعد أحد أمراض العصر الحديث.','["الاهتمام بالتميّز في الأرقام وما تعكسه من تفرد وسبق، له ما يبرره. غير أنه عندما يصبح الرقم مطلبًا وهاجسًا يسعى المرء إلى تحقيق السبق فيه، فعندئذ يكون هناك خلل يوجب التوقف عنده. لأن تحول الوسيلة (الرقم) إلى غاية، يعد أحد أمراض العصر الحديث. نعم، الرقم الأول قد يعني الفوز في مضمار سباق الخيل أو السيارات، وقد يعني باكورة الإنتاج.","الأرقام تتنوع من ناحية الدلالة، فهناك الرقم الأول والرقم الأكبر والرقم الأطول، وكل رقم يُشار إليه كسبق أو ضخامة أو تمييز في عالم الأرقام، لا يكشف أبعاد الصورة.","الرقم تجريدٌ لا يعكس الكنه: الرقم الأول في السباق لا يخبرك بجهد المتسابق، والرقم الأكبر في المبيعات لا يخبرك بجودة المنتج، والرقم الأطول في المبنى لا يخبرك بمتانته. إنه «قشر» المعنى، وليس لبّه.","الهوس بالسبق يُفسد الغاية: عندما يصبح الرقم هاجسًا، يتحول العمل إلى مجرد «منافسة رقمية»، فيُضخم الإنجاز ظاهريًا على حساب الجوهر، وقد يُلجأ إلى الالتفاف أو التضخيم أو حتى التزوير للفوز بالرقم. الأرقام وحدها صورة باهتة: هي كالخريطة، مفيدة للملاحة، لكنها ليست الأرض نفسها. التميّز الحقيقي يُقاس بآثارٍ نوعية لا تدخل في الإحصاء: الأثر الأخلاقي، الإتقان، السعادة، الاستدامة."]','التقنية','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2261232','https://www.okaz.com.sa/articles/authors/2261232','','https://www.okaz.com.sa/articles/authors/2261232','أسامة يماني','السعودية','2026-08-13T18:07:00.000Z','Wed, 07 Oct 2026 18:31:08 GMT','2026-08-15T14:35:29.082Z','https://www.okaz.com.sa/uploads/authors/372.jpg','/api/media/dbdf7e51-68d2-45f9-94fb-8fc4c066b28c','/api/media/dbdf7e51-68d2-45f9-94fb-8fc4c066b28c?variant=thumbnail','عندما يصير الرقم إنسانًا',709,709,'valid','published','archived','valid',46,'ea90d7335fcc62b691a0e47e1bc4d9ddbf65c5e3400ce64fcc0bc64667cba252','75770ad4089496135a6da796d31fb51d56051373cab7a31c9f7066200c4b7fa5','محدّث','2026-08-13T23:27:52.697Z','2026-10-07T20:51:50.336Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي"]','["التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"التقنية","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:51:50.336Z',304,77,0,'source_article_available','',NULL,NULL,'body:c8af3de9ca759468a22d4b9cee3457fc62b9f76cf725bdcfc693ff02376290b8','Wed, 07 Oct 2026 18:31:08 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('76d9e7ed-91da-421f-8ee0-cea2ff034ce4','news-76d9e7ed-91da-421f-8ee0-cea2ff034ce4','دراسات أظهرت أن رؤى المنام أهم محرك للإرهابيين','دراسات اظهرت ان رؤي المنام اهم محرك للارهابيين','في الغرب تخصص علماء بدراسة دوافع الجماعات الإسلاموية الإرهابية وكانت أكثر نتيجة صادمة هي أن العامل الأساسي المشترك بين الجماعات الإرهابية الإسلاموية؛ اعتمادها في بقراراتها على رؤى المنام بشكل كامل، ففي الخطب التي بثها جهيمان داخل الحرم أثناء حصاره وبرسائله، ذكر بالأسماء اثنين من الجماعة جمعا 50 رؤيا تزعم أن صهره هو المهدي، وصهره كان لا يعتقد أنه المهدي رغم إ','["في الغرب تخصص علماء بدراسة دوافع الجماعات الإسلاموية الإرهابية وكانت أكثر نتيجة صادمة هي أن العامل الأساسي المشترك بين الجماعات الإرهابية الإسلاموية؛ اعتمادها في بقراراتها على رؤى المنام بشكل كامل، ففي الخطب التي بثها جهيمان داخل الحرم أثناء حصاره وبرسائله، ذكر بالأسماء اثنين من الجماعة جمعا 50 رؤيا تزعم أن صهره هو المهدي، وصهره كان لا يعتقد أنه المهدي رغم إصرار جهيمان بسبب حلم رآه، فقام صهره باستخارة وزعم أنه رأى…","المركز الدولي لمكافحة الإرهاب (ICCT) بهولندا قام بدراسة للأحلام التي نشرتها داعش بمجلتها الرسمية «دابق»، وبالعدد/14 نشرت الأحلام التي قالت إنها سبب هجومين ببروكسل وباريس، والدكتور Iain Edgar عالم الأنثروبولوجيا تخصص بالدراسات عن دور الأحلام الرئيسي بصناعة قرارات الإرهابيين الإسلامويين وكتب كتباً عنها، ووثق أن الملا عمر نصب نفسه حاكماً بسبب رؤيا لبس فيها عباءة النبي (صلى الله عليه وسلم)، وبعد هزيمة طالبان 2001م…","وللعلم؛ الدافع الرئيسي لانضمام الأوروبيين للحملات الصليبية كان رؤية أحلام تأمرهم بهذا."]','السيارات','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2261230','https://www.okaz.com.sa/articles/authors/2261230','','https://www.okaz.com.sa/articles/authors/2261230','بشرى فيصل السباعي','السعودية','2026-08-13T18:07:00.000Z','Wed, 07 Oct 2026 18:31:08 GMT','2026-08-13T23:27:53.774Z','https://www.okaz.com.sa/okaz/uploads/authors/287.jpg?v=1762092549','/api/media/76d9e7ed-91da-421f-8ee0-cea2ff034ce4','/api/media/76d9e7ed-91da-421f-8ee0-cea2ff034ce4?variant=thumbnail','دراسات أظهرت أن رؤى المنام أهم محرك للإرهابيين',400,400,'valid','published','archived','valid',40,'f18d185d29b20ff3f3086fab2b0603259620933009d09326f9f93c8716e71b2f','c3c4137072e3f66a672d55b58add3da5de682a98fc5ccb54800eae93b64eda14',NULL,'2026-08-13T23:27:53.774Z','2026-10-07T20:51:49.171Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":1.5},{"category":"الثقافة","score":1.5},{"category":"الطاقة والصناعة","score":1.5}]','Active','2026-10-07T20:51:49.171Z',304,78,0,'source_article_available','',NULL,NULL,'body:f7f90069eac761170bbdaaf3a474118883605b0bb2943a2d4950b98c75b84890','Wed, 07 Oct 2026 18:31:08 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('05d3f78e-4fb4-4515-8ce6-9dd145f1e0a8','news-05d3f78e-4fb4-4515-8ce6-9dd145f1e0a8','السعودية.. الحروب لا تصنع السلام','السعوديه الحروب لا تصنع السلام','السعودية دولة محورية لها ثقلها السياسي والاقتصادي، وبعدها الديني، وتعرف حجم هذه المسؤولية، ومن هذا المنطلق تدرك أن القرارات السيادية لا تُتخذ لإرضاء هذه العاصمة، أو تلك، إنما وفق حسابات الأمن الوطني والمصالح العليا واستقرار المنطقة.','["السعودية دولة محورية لها ثقلها السياسي والاقتصادي، وبعدها الديني، وتعرف حجم هذه المسؤولية، ومن هذا المنطلق تدرك أن القرارات السيادية لا تُتخذ لإرضاء هذه العاصمة، أو تلك، إنما وفق حسابات الأمن الوطني والمصالح العليا واستقرار المنطقة. لهذا فإن أي ضغوط أو إملاءات غير مقبولة. وتتمتع الرياض بعلاقات متوازنة مع الأشقاء والأصدقاء، ومن يسعى إلى التمسك بتلك العلاقات التاريخية وتوثيق الشراكة عليه أن يفهم الرسالة. ومن الخطأ…"]','أخبار السعودية','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/na/2261238','https://www.okaz.com.sa/articles/na/2261238','','https://www.okaz.com.sa/articles/na/2261238','خالد سيف','السعودية','2026-08-13T18:07:00.000Z','Wed, 07 Oct 2026 18:31:56 GMT','2026-08-13T23:27:53.958Z','https://www.okaz.com.sa/uploads/authors/1612.jpg','/api/media/05d3f78e-4fb4-4515-8ce6-9dd145f1e0a8','/api/media/05d3f78e-4fb4-4515-8ce6-9dd145f1e0a8?variant=thumbnail','السعودية.. الحروب لا تصنع السلام',400,400,'valid','published','archived','valid',52,'f945960ed04845fc6fd895b4473e27bbed823f9f9d5466cbfbebd0d622041d8f','a9382c54d24d075c93904ab529510d738e868b6b5b961569e01b34a3ebb4655b',NULL,'2026-08-13T23:27:53.958Z','2026-10-07T20:52:54.823Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","الرياض"]','["الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"السياسة","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T20:52:54.823Z',304,76,0,'source_article_available','',NULL,NULL,'body:36121ff6d773de22c1aa4871fced8dd612ac82bcb0fd37a940754f3ec1ff6d0e','Wed, 07 Oct 2026 18:31:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c0b1714d-19d5-4b2e-8970-587837efbd9b','news-c0b1714d-19d5-4b2e-8970-587837efbd9b','بالنيّة ما هي بالمظهريّة','بالنيه ما هي بالمظهريه','صبّحتْ (شفيعة) على عمّتها (مشفوعة) بالخير، والعجوز مسرّحة، تحرك شفاهها بكلمات لا يتضح معناها، وكأنها ناقمة على حِلم شافته في منامها البارحة فنغص عليها، لم تسمع التصبيح؛ فقربت منها وقالت بصوت مرتفع «وش أصبحتِ يا عمّة» انتغزت وقالت؛ أخرعتيني الله يخشعك، وازدادت العجوز احتقاناً وهي تقول؛ يا غبيرة يا دبيرة، بغيتِ تأخذين عقلي اللي ماعاد معي منه ما يملا زبدية القه','["صبّحتْ (شفيعة) على عمّتها (مشفوعة) بالخير، والعجوز مسرّحة، تحرك شفاهها بكلمات لا يتضح معناها، وكأنها ناقمة على حِلم شافته في منامها البارحة فنغص عليها، لم تسمع التصبيح؛ فقربت منها وقالت بصوت مرتفع «وش أصبحتِ يا عمّة» انتغزت وقالت؛ أخرعتيني الله يخشعك، وازدادت العجوز احتقاناً وهي تقول؛ يا غبيرة يا دبيرة، بغيتِ تأخذين عقلي اللي ماعاد معي منه ما يملا زبدية القهوة! احمرّتْ وجنات زوجة ابنها الودود، بسبب ردة فعل سيدة…","اشتلت (شفيعة) قفتها واخترجت المحش من بين حجارة مندر الدرجة، ولفّت حوكتها على رأسها، وأدخلت قدميها في كنادر بلاستيك، إذا دخلها شيء الماء تصدر أصواتاً فاضحة، اجتهدت في مسح المكان، ولم تظفر بقبضة كف من عشب، والغدران تحوم الهمجة على ما بقي من نقيع آسن، وافتقدت أصوات العصافير؛ فذهب بها ظنها إلى أن القريّة أغضبت ربي وإلا ما كان قطع عنها المطر، ظهر عليها الفقيه من السند قائلاً (بعوه) فقبعته بخشبة المحش في المضاغة وعجرمت،…","يطيب للقحم (شردان)، الذي لم يبق من أنداده ولا مخلوق، أن يفرش جاعداً ويتمدد في ركن الساحة ليرصد السارحات والرايحات؛ وكلما لمحته كهلته استلمته؛ قم من عندك يا شيبة يا هلبة يا المخرّف ما تستحي تتلمح في نسوان خلق الله؛ ويردّ عليها؛ كُلي تراب أربني باكلهنه يا كهلة عثبر؛ ويضيف مُحل رشاي فوق محّالة بيرك، والفراص ينكب، والديك يوذّن مدنّي ما معه قدرة يرفع راسه، علّقت؛ استح على نفسك من ربي، ما تسدنا الشحاحة اللي انحن فيها،…","مرّتْ بهم (شفيعة) وهي رايحة بقفتها الفاضية؛ ألقت عليهم تحيتها العذبة؛ (ولعون)، وهي منكسرة الخاطر، مسحت بطرف الحوكة رشحها الناضح من جبهتها، وصاحت باتلى نشغة في صوتها؛ يا الله في المزى، وشبك يا عمّ (شردان) انحن في وقت، ما لنا فيه إلا مرضاة ربي؛ وانته على ضعيفة الله سمّيتاها وهميتاها؛ وضع سبابته على شفتيه؛ في إشارة تحذير تعني؛ التزام الصمت، وبدع (وش معا زارع الثومة من الثوم فود؛ غير فتق المحاجي لا غمض نونها) فأدارت له…"]','الثقافة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2261231','https://www.okaz.com.sa/articles/authors/2261231','','https://www.okaz.com.sa/articles/authors/2261231','علي بن محمد الرباعي','السعودية','2026-08-13T18:07:00.000Z','Wed, 07 Oct 2026 18:31:11 GMT','2026-08-13T23:27:54.055Z','https://www.okaz.com.sa/okaz/uploads/authors/239.jpg?v=1766066191','/api/media/c0b1714d-19d5-4b2e-8970-587837efbd9b','/api/media/c0b1714d-19d5-4b2e-8970-587837efbd9b?variant=thumbnail','بالنيّة ما هي بالمظهريّة',400,400,'valid','published','archived','valid',44,'42e1cc638d74344255ecbee0e6099080d91da9b41ac1c56f72c1c11176ca79e5','a19a7e44963795b0a89101de5f74ae00e1658fc9a3585202cdd0f8ba4b617a3a',NULL,'2026-08-13T23:27:54.055Z','2026-10-07T20:51:51.403Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الاقتصاد والأسواق"]','["الصحة العامة","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":3},{"category":"المناطق","score":1.5},{"category":"الصحة","score":1.5}]','Active','2026-10-07T20:51:51.403Z',304,78,0,'source_article_available','',NULL,NULL,'body:2ee2b0815ed8777f88158fd550034786f08f001d5c7b0a0e56016aeba03bcf1f','Wed, 07 Oct 2026 18:31:11 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9e572445-e498-4a5b-87fb-e60ba00e8500','news-9e572445-e498-4a5b-87fb-e60ba00e8500','أمراض مناعية لم نسمع بها من قبل.. العلم يكشف ما كان مجهولا','امراض مناعيه لم نسمع بها من قبل العلم يكشف ما كان مجهولا','خبرني - تسجل أمراض المناعة الذاتية حضورا متزايدا في الأنظمة الصحية حول العالم، وسط محاولات علمية لفهم أسباب ارتفاع معدلات بعضها، ودور التغيرات البيئية ونمط الحياة والعدوى والتطور الكبير في أدوات التشخيص في كشف أمراض لم يكن الطب يعرفها قبل سنوات قليلة.','["وتشير تقديرات حديثة إلى أن أمراض المناعة الذاتية بمختلف أنواعها قد تصيب ما بين 5% و10% من سكان العالم. وفي دراسة واسعة شملت السجلات الصحية لنحو 22 مليون شخص في بريطانيا، تبيّن أن 19 مرضا مناعيا ذاتيا شملتها الدراسة أصابت مجتمعة نحو 10% من السكان.","ولا تتحرك جميع هذه الأمراض في الاتجاه نفسه؛ إذ تختلف معدلات الانتشار والإصابة من مرض إلى آخر ومن منطقة إلى أخرى، لكنّ دراسات حديثة تشير إلى أن العبء الإجمالي للأمراض المناعية مرشح للارتفاع خلال العقود المقبلة، مع زيادة أعداد الحالات وتغير التعرض للعوامل البيئية وأنماط الحياة.","تحدث أمراض المناعة الذاتية عندما يفقد جهاز المناعة قدرته الطبيعية على التمييز بين مكونات الجسم والعوامل الغريبة، فيوجه استجابته ضد خلايا وأنسجة سليمة، مما يؤدي إلى التهاب مزمن قد يُسبب مع الوقت تلف الأعضاء أو اضطراب وظائفها.","ولا يزال السبب الدقيق وراء معظم هذه الأمراض غير معروف، لكنّ الأدلة تشير إلى تفاعل معقّد بين الاستعداد الجيني وعوامل خارجية قد تشمل العدوى والتدخين وبعض المواد الكيميائية والنظام الغذائي والسمنة وتغير الميكروبيوم (Microbiome) والتلوث وعوامل أخرى مرتبطة بنمط الحياة والبيئة."]','المجتمع','العالم','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://www.khaberni.com/news/838159-%D8%A7%D9%85%D8%B1%D8%A7%D8%B6-%D9%85%D9%86%D8%A7%D8%B9%D9%8A%D8%A9-%D9%84%D9%85-%D9%86%D8%B3%D9%85%D8%B9-%D8%A8%D9%87%D8%A7-%D9%85%D9%86-%D9%82%D8%A8%D9%84-%D8%A7%D9%84%D8%B9%D9%84%D9%85-%D9%8A%D9%83%D8%B4%D9%81-%D9%85%D8%A7-%D9%83%D8%A7%D9%86-%D9%85%D8%AC%D9%87%D9%88%D9%84%D8%A7','https://www.khaberni.com/news/838159-%D8%A7%D9%85%D8%B1%D8%A7%D8%B6-%D9%85%D9%86%D8%A7%D8%B9%D9%8A%D8%A9-%D9%84%D9%85-%D9%86%D8%B3%D9%85%D8%B9-%D8%A8%D9%87%D8%A7-%D9%85%D9%86-%D9%82%D8%A8%D9%84-%D8%A7%D9%84%D8%B9%D9%84%D9%85-%D9%8A%D9%83%D8%B4%D9%81-%D9%85%D8%A7-%D9%83%D8%A7%D9%86-%D9%85%D8%AC%D9%87%D9%88%D9%84%D8%A7','','','','السعودية','2026-08-13T18:00:00.000Z','2026-08-13T21:00:00.000Z','2026-08-13T23:32:39.719Z','https://www.khaberni.com/upload/news/thumb/news_model/2026/08/6a7e37f427e7b.webp','/api/media/9e572445-e498-4a5b-87fb-e60ba00e8500','/api/media/9e572445-e498-4a5b-87fb-e60ba00e8500?variant=thumbnail','أمراض مناعية لم نسمع بها من قبل.. العلم يكشف ما كان مجهولا',1280,852,'valid','published','archived','valid',83,'e57cb2d0ae61840e5b948f77cdd5f539bfa646a3b58fb42c5e9389bd264bdbd0','69e996ce7e88fa7c117503da3e0a60ce152f86df63373b27d0b741751755f171',NULL,'2026-08-13T23:32:39.719Z','2026-10-07T20:57:56.956Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["العالم","الصحة العامة"]','["الصحة العامة"]','manual