INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('06d6f7dc-8ddc-4fd4-804f-a795397690e4','news-06d6f7dc-8ddc-4fd4-804f-a795397690e4','التوسع الإقليمي والدولي يدعم مسيرة نمو استثمار القابضة خلال النصف الأول من عام 2026','التوسع الاقليمي والدولي يدعم مسيره نمو استثمار القابضه خلال النصف الاول من عام 2026','أعلنت استثمار القابضة ش.م.ع.ق عن نتائجها المالية للنصف الأول من العام 2026 والمنتهية في 30 يونيو 2026، وذلك عقب اعتمادها من مجلس إدارة الشركة.','["تمتد أعمال استثمار القابضة اليوم عبر 10 دول، من قطر، ثم المملكة العربية السعودية، والعراق، وسوريا، والجزائر، والأردن، وليبيا، ومصر، وجزر المالديف، وكازاخستان.","ويبرز هذا الحضور الإقليمي والدولي نجاح استراتيجية المجموعة في التوسع خارج دولة قطر، مع تنامي مساهمة عملياتها الدولية في دعم أدائها المالي وتعزيز متانة نموذج أعمالها المتنوع.","وسجلت الشركة إيرادات بلغت 3.159 مليار ريال قطري مقارنة بـ 3.073 مليار ريال قطري خلال الفترة نفسها من عام 2025.","كما ارتفعت الأرباح قبل اقتطاع الفائدة والضريبة والاستهلاك والإطفاء بنسبة 20% لتبلغ 880 مليون ريال قطري مقارنة بـ 732 مليون ريال قطري، فيما ارتفع صافي الأرباح بنسبة 21% ليصل إلى 561 مليون ريال قطري مقارنة بـ 465 مليون ريال قطري خلال الفترة ذاتها من العام الماضي."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/diooeki','https://sabq.org/article/diooeki','','https://sabq.org/article/diooeki','صحيفة سبق','السعودية','2026-08-13T04:35:00.000Z','2026-08-13T07:38:00.000Z','2026-08-13T23:32:52.024Z','https://media.sabq.org/news/2026/08/7433ba1f-fe15-4471-bace-d2f2fb1796e7/w600.webp','/api/media/06d6f7dc-8ddc-4fd4-804f-a795397690e4','/api/media/06d6f7dc-8ddc-4fd4-804f-a795397690e4?variant=thumbnail','التوسع الإقليمي والدولي يدعم مسيرة نمو استثمار القابضة خلال النصف الأول من عام 2026',600,500,'valid','published','archived','valid',99,'530c9a162ee89a9556ad50f35c9d9eb4e4b71ccf18de729a83d7be2294fdb6ab','affa09e9da5cf7e45b289a2fa53c88330b30b688cbd270592bbd4b63224fa910','محدّث','2026-08-13T23:32:52.024Z','2026-10-07T20:58:48.157Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","سوريا","العراق"]','["الاقتصاد والأسواق"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":0},{"category":"الصحة","score":0}]','Active','2026-10-07T20:58:48.157Z',200,87,0,'source_article_available','',NULL,NULL,'body:1a4928e7ceea91e99a018f88c78bbdba90260a9d0b2b90a810126cdf94a7d366','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f13d50af-b860-42d3-baab-a844fd493716','news-f13d50af-b860-42d3-baab-a844fd493716','القوات الخاصة للأمن البيئي تضبط 3 مقيمين استغلوا الرواسب في الرياض','القوات الخاصه للامن البيئي تضبط 3 مقيمين استغلوا الرواسب في الرياض','ضبطت القوات الخاصة للأمن البيئي (3) مقيمين مخالفين لنظام البيئة من الجنسية اليمنية؛ لاستغلالهم الرواسب في منطقة الرياض، وطُبقت الإجراءات النظامية بحقهم.','["وأوضحت القوات أنه تم ضبط (9) معدات تستخدم في تجريف ونقل التربة، حاثةً على الإبلاغ عن أي حالات تمثل اعتداءً على البيئة أو الحياة الفطرية على الأرقام (911) بمناطق مكة المكرمة، والمدينة المنورة، والرياض، والشرقية، و(999) و(996) في بقية مناطق المملكة، وستعامل جميع البلاغات بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/x0z0nyb','https://sabq.org/article/x0z0nyb','','https://sabq.org/article/x0z0nyb','صحيفة سبق','السعودية','2026-08-13T04:30:00.000Z','2026-08-13T07:31:00.000Z','2026-08-13T23:32:52.079Z','https://media.sabq.org/news/2026/08/523614bf-bfce-4387-997c-8032a928ea55/w1000.webp','/api/media/f13d50af-b860-42d3-baab-a844fd493716','/api/media/f13d50af-b860-42d3-baab-a844fd493716?variant=thumbnail','القوات الخاصة للأمن البيئي تضبط 3 مقيمين استغلوا الرواسب في الرياض',1000,500,'valid','published','archived','valid',100,'be06c32dc5915d67ff8774c043232357108d128f5931712d4066a9bbf9597e9e','54f28e01c7d47fa464998a461b6afa2274da7e6504e637f3b656ccc0894255da','محدّث','2026-08-13T23:32:52.079Z','2026-10-07T20:58:18.168Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","الرياض","المدينة المنورة"]','["المدينة المنورة"]','manual_approved','','[]','Temporarily Unreachable','2026-10-07T20:58:18.168Z',NULL,87,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8bd21584-31ec-4e2b-9d96-85532d39f9ce','news-8bd21584-31ec-4e2b-9d96-85532d39f9ce','"العناية بالحرمين" تدعو ضيوف الرحمن للتخطيط المبكر للعمرة وتوضح أوقات كثافة المعتمرين بالمسجد الحرام','العنايه بالحرمين تدعو ضيوف الرحمن للتخطيط المبكر للعمره وتوضح اوقات كثافه المعتمرين بالمسجد الحرام','دعت الهيئة العامة للعناية بشؤون المسجد الحرام والمسجد النبوي ضيوف الرحمن إلى التخطيط المبكر لأداء مناسك العمرة، والتعرّف على أوقات كثافة المعتمرين في المسجد الحرام، واختيار الأوقات المناسبة، بما يسهم في أداء النسك بيسر وسهولة، ويعزز انسيابية الحركة في المطاف والمسعى.','["وأوضحت الهيئة، في دليلها التوعوي لأوقات الكثافة، أن الفترة من الساعة العاشرة مساءً حتى الرابعة صباحًا تشهد كثافة خفيفة، وكذلك الفترة من الساعة التاسعة صباحًا حتى الرابعة مساءً، فيما تكون الكثافة متوسطة خلال الفترة من الخامسة صباحًا حتى الثامنة صباحًا، وترتفع إلى كثافة عالية خلال الفترة من الخامسة مساءً حتى التاسعة مساءً.","ويأتي التعريف بأوقات الكثافة ضمن جهود الهيئة الرامية إلى مساعدة قاصدي المسجد الحرام على تنظيم أوقاتهم قبل التوجه لأداء العمرة، والاستفادة من الفترات الأقل ازدحامًا، بما يسهم في تعزيز الراحة والسلامة، وتحسين تجربة ضيف الرحمن منذ وصوله إلى المسجد الحرام حتى إتمام نسكه.","وأكدت الهيئة العامة للعناية بشؤون المسجد الحرام والمسجد النبوي أن التخطيط المسبق واختيار الوقت المناسب لأداء العمرة يسهمان في رفع مستوى انسيابية حركة المعتمرين داخل المسجد الحرام، داعيةً ضيوف الرحمن إلى متابعة المؤشرات الإرشادية المتعلقة بالكثافة، والاستفادة من الخدمات الرقمية المتاحة لمعرفة حالة المطاف والمسعى، بما يعينهم على اختيار الوقت والمكان الأنسب لأداء النسك.","وتتيح الهيئة عبر موقعها الإلكتروني خدمة رقمية لمعرفة حالة الكثافة في مواقع المطاف والمسعى، تشمل صحن المطاف وأدواره المختلفة، إلى جانب أدوار المسعى، بما يمكّن المعتمرين من الاطلاع على مستويات الكثافة والاستفادة من المعلومات المتاحة قبل وجودهم في المسجد الحرام وأثناءه."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/xevw46b','https://sabq.org/article/xevw46b','','https://sabq.org/article/xevw46b','صحيفة سبق','السعودية','2026-08-13T04:51:00.000Z','2026-08-13T07:56:00.000Z','2026-08-13T23:32:52.152Z','https://media.sabq.org/news/2026/08/444b3b9f-1245-4b14-a20f-837c197b2600/w1600.webp','/api/media/8bd21584-31ec-4e2b-9d96-85532d39f9ce','/api/media/8bd21584-31ec-4e2b-9d96-85532d39f9ce?variant=thumbnail','"العناية بالحرمين" تدعو ضيوف الرحمن للتخطيط المبكر للعمرة وتوضح أوقات كثافة المعتمرين بالمسجد الحرام',1600,2852,'valid','published','archived','valid',48,'e47dcc4e52f7c809025e2d3d9d36b18c1b02d185d9dab5ed5c16c53c4039c2f4','fd263a2e6a800094aea79a4473626d4d7e05d0bff27cca2b5725f08cb0b11455','محدّث','2026-08-13T23:32:52.152Z','2026-10-07T20:58:44.888Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي"]','["التقنية والتحول الرقمي"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":3},{"category":"الصحة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:58:44.888Z',200,86,0,'source_article_available','',NULL,NULL,'body:3161e8fa8bb91072f6eb59dbe69654c655f25e1f942b9c5e1e9f1fd4cb32f2ce','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5ac4d012-d200-4ebb-9b0f-b95927049633','news-5ac4d012-d200-4ebb-9b0f-b95927049633','ليلة كسوف الشمس .. 500 ألف سائح لإسبانيا والمغرب تقرر عدم اقامة الصلاة لهذا السبب ','ليله كسوف الشمس 500 الف سائح لاسبانيا والمغرب تقرر عدم اقامه الصلاه لهذا السبب','شهدت أمس الأربعاء 13 أغسطس 2026 عدة دول أوروبية طفرة سياحية واستثنائية غير مسبوقة بالتزامن مع الظاهرة الفلكية النادرة وهي الكسوف الكلي للشمس، حيث تدفق مئات الآلاف من السياح نحو المناطق الواقعة ضمن مسار الإظلام التام، ما أدى إلى قفزات قياسية في أسعار الفنادق وإشغال كامل لأماكن الإقامة.','["قفزات جنونية في الأسعار وبحسب تقرير لصحيفة «الجارديان» البريطانية، استقبلت إسبانيا وحدها نحو 460 ألف سائح أجنبي وصلوا خصيصًا لمتابعة الحدث، ما جعل القرى والبلدات الواقعة في مسار الكسوف الكلي تحظى بإشغال فندقي بنسبة 100% منذ عدة أشهر.","ووفقاً لبيانات منصة «لايتهاوس إنتليجنس» فإن العاصمة الآيسلندية ريكيافيك ارتفع متوسط سعر الغرفة الفندقية لليلة الكسوف بنسبة 98% ليصل إلى 793 دولاراً ومدينة لا كورونيا (شمال إسبانيا): سجلت أضخم زيادة في الأسعار بنسبة 135% ليبلغ سعر الليلة 451 دولاراً وهي ابرز المدن التى شهدت الكسوف بشكل واضح اما مدن مايوركا وبيلباو وسانتياجو فقد شهدت ارتفاعات متصاعدة تراوحت بين 24% و67%.","كما شهدت المغرب الظاهرة بوضوح ولكن أعلنت وزارة الأوقاف والشؤون الإسلامية بالمملكة المغربية أن صلاة الكسوف لن تُقام في المساجد بالمناطق التي يُشاهد فيها الكسوف بالمملكة.","وأوضحت الوزارة في بيان رسمي أن سبب المنع يعود لوقوع الكسوف بعد صلاة العصر وحتى ما قبل غروب الشمس، وهو وقت يوافق شرعاً \"فترة كراهة النافلة\"."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/rm8m8lv','https://sabq.org/article/rm8m8lv','','https://sabq.org/article/rm8m8lv','خالد خليل','السعودية','2026-08-13T04:20:00.000Z','2026-08-13T07:38:00.000Z','2026-08-13T23:32:53.378Z','https://media.sabq.org/news/2026/08/a5d0278a-5776-4a44-ac1b-e07285e3bcdf/w800.webp','/api/media/5ac4d012-d200-4ebb-9b0f-b95927049633','/api/media/5ac4d012-d200-4ebb-9b0f-b95927049633?variant=thumbnail','ليلة كسوف الشمس .. 500 ألف سائح لإسبانيا والمغرب تقرر عدم اقامة الصلاة لهذا السبب ',800,441,'valid','published','archived','valid',46,'17fa98fbbd3a647246597082e75d964d3d5890385c1e629ae8f30480ddda033b','4e128f9d2ac22ae955236823aad0eda61b2df0bb89e5b5bb6e9c8475b71c86bb','محدّث','2026-08-13T23:32:53.378Z','2026-10-07T20:58:48.682Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الأوقاف والشؤون الإسلامية بالمملكة","السفر والسياحة"]','["وزارة الأوقاف والشؤون الإسلامية بالمملكة","السفر والسياحة"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5},{"category":"السفر","score":1.5}]','Active','2026-10-07T20:58:48.682Z',200,84,0,'source_article_available','',NULL,NULL,'body:6ee487b0d85a49327be622823a2fbd2d21aede228063e8d131adcb6401d1c451','');
