INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fca03da7-4f84-424b-bd90-45ec95d4c9ad','news-fca03da7-4f84-424b-bd90-45ec95d4c9ad','تركي آل الشيخ يعلن رعاية موسم الرياض لكأس السوبر الإسباني 2027 في إسطنبول','تركي ال الشيخ يعلن رعايه موسم الرياض لكاس السوبر الاسباني 2027 في اسطنبول','أعلن معالي المستشار تركي بن عبدالمحسن آل الشيخ، رئيس مجلس إدارة الهيئة العامة للترفيه (GEA)، عن رعاية موسم الرياض لبطولة كأس السوبر الإسباني 2027، والتي تقام فعالياتها في مدينة إسطنبول التركية، وذلك في إطار حضور موسم الرياض المتواصل في أبرز الفعاليات الرياضية العالمية، وتأتي استضافة إسطنبول لكأس السوبر الإسباني بموجب اتفاقية تجمع الاتحاد الملكي الإسباني لكرة','["وتقام منافسات البطولة على ملعب أتاتورك الأولمبي، الذي يُعد أحد أبرز الملاعب في تاريخ كرة القدم، حيث استضاف نهائي دوري أبطال أوروبا في نسختي 2005، و2023؛ ليحتضن منافسات نخبة الأندية الإسبانية.","وفي إطار هذا التعاون، ستكون شركة صلة الجهة المشرفة على بطولة كأس السوبر الإسباني في إسطنبول، وتتولى مسؤولية إدارة الحقوق التجارية والتنفيذ التشغيلي للبطولة، بالتعاون مع الاتحادين الملكي الإسباني لكرة القدم، والتركي لكرة القدم، بما يضمن تقديم تجربة عالمية المستوى للأندية واللاعبين والجهات الناقلة والشركاء والجماهير.","وتمثل رعاية موسم الرياض للبطولة امتدادًا لدوره في دعم الفعاليات الرياضية الكبرى وتعزيز حضوره الدولي، من خلال شراكات تجمعه بأبرز المؤسسات والبطولات الرياضية العالمية، بما يسهم في الوصول إلى جماهير جديدة وتعزيز حضور موسم الرياض على الساحة العالمية.","وسيشارك في البطولة كل من أندية برشلونة، وريال مدريد، وريال سوسيداد، وأتلتيكو مدريد، فيما سيعلن لاحقاً عن جدول المباريات، وآليات طرح التذاكر، إلى جانب البرامج والفعاليات الجماهيرية المصاحبة للبطولة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/pydrrup','https://sabq.org/article/pydrrup','','https://sabq.org/article/pydrrup','صحيفة سبق','السعودية','2026-08-13T04:58:00.000Z','2026-08-13T07:58:00.000Z','2026-08-14T01:39:36.332Z','https://media.sabq.org/news/2026/08/d1044035-bc5b-4f9f-9b3b-58de913b5712/w1600.webp','/api/media/fca03da7-4f84-424b-bd90-45ec95d4c9ad','/api/media/fca03da7-4f84-424b-bd90-45ec95d4c9ad?variant=thumbnail','تركي آل الشيخ يعلن رعاية موسم الرياض لكأس السوبر الإسباني 2027 في إسطنبول',1600,2133,'valid','published','archived','valid',91,'dc7d77693554245330a2e83a4a2d2b1eb5141ea2bdd00d92755cb941d9a56d7f','2d5bd157d6557ec73e30f0a3699adfa981fa07228078bf40522f97df76ec555a','محدّث','2026-08-14T01:39:36.332Z','2026-10-07T20:57:33.743Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة صلة الجهة المشرفة على","الرياضة السعودية","الرياض","أوروبا"]','["شركة صلة الجهة المشرفة على","الرياضة السعودية"]','classified','','[{"category":"المناطق","score":3},{"category":"العالم","score":3},{"category":"الاقتصاد","score":1.5}]','Temporarily Unreachable','2026-10-07T20:57:33.743Z',NULL,84,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1b87d713-d176-4d63-a6a6-07aae61a68b9','news-1b87d713-d176-4d63-a6a6-07aae61a68b9','الأرصاد عن طقس الجمعة: أمطار رعدية ورياح نشطة على عدة مناطق','الارصاد عن طقس الجمعه امطار رعديه ورياح نشطه علي عده مناطق','توقع المركز الوطني للأرصاد في تقريره اليومي، هطول أمطار رعدية مصحوبة بزخات من البرد ورياح نشطة على أجزاء من مناطق نجران ، جازان ، عسير ، الباحة ومرتفعات منطقة مكة المكرمة، اليوم الخميس.','["أوضح التقرير استمرار تأثير الرياح النشطة المثيرة للأتربة والغبار على أجزاء من منطقتي المدينة المنورة ومكة المكرمة، خاصة المناطق الساحلية منهما.","كما أشار إلى أن درجات الحرارة العظمى ستظل مرتفعة على المنطقة الشرقية وأجزاء من منطقة الرياض ، مع تكوّن الضباب خلال ساعات الصباح الباكر على الأجزاء الساحلية من المنطقة الشرقية، خاصة الجنوبية منها.","أفاد التقرير بأن حركة الرياح السطحية على البحر الأحمر ستكون شمالية غربية إلى غربية بسرعة 20-40 كم/ساعة على الجزأين الشمالي والجنوبي، وشمالية غربية إلى شمالية بسرعة 18-45 كم/ساعة على الجزء الأوسط، وقد تتجاوز 50 كم/ساعة مع تكوّن السحب الرعدية الممطرة على الجزء الجنوبي."]','البيئة والمناخ','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/1yf5ujub3','https://ajel.sa/local/1yf5ujub3','https://ajel.sa/local/1yf5ujub3','https://ajel.sa/local/1yf5ujub3','فريق التحرير','السعودية','2026-08-13T22:25:00.000Z','Wed, 07 Oct 2026 20:52:51 GMT','2026-08-14T07:54:57.233Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%B7%D9%82%D8%B3-5-klSRJeVj.jpg','/api/media/1b87d713-d176-4d63-a6a6-07aae61a68b9','/api/media/1b87d713-d176-4d63-a6a6-07aae61a68b9?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',86,'9cb34113c4561c643f42c8bbd2a64e572365f49f4ce4a3e22c76205af9cf210b','451a3be7bdba1e754a3248ad4ebcd934e5b500f590f8d1bbcdf1daab4293736d',NULL,'2026-08-14T07:54:57.233Z','2026-10-07T20:52:53.361Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة","الرياض","المدينة المنورة"]','["الطقس والمناخ","المدينة المنورة"]','classified','','[{"category":"المناطق","score":4.5},{"category":"السفر","score":3},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:52:53.361Z',200,75,0,'source_content_changed','',NULL,NULL,'body:bc88e99ad22f5f1e0c83eaa1ef7bb0b86b1946ca2725ece9b8133990089fcac2','Wed, 07 Oct 2026 20:52:51 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('76099c36-3a05-4beb-8a51-89f6a1cab666','news-76099c36-3a05-4beb-8a51-89f6a1cab666','مختبر مستشفى الولادة والأطفال بالمدينة المنورة يحصل على اعتماد الكلية الأمريكية لعلم الأمراض','مختبر مستشفي الولاده والاطفال بالمدينه المنوره يحصل علي اعتماد الكليه الامريكيه لعلم الامراض','حقق مختبر مستشفى الولادة والأطفال بمدينة الملك سلمان الطبية في المدينة المنورة إنجازاً نوعياً بحصوله على اعتماد الكلية الأمريكية لعلم الأمراض (College of American Pathologists - CAP)، الذي يُعدّ من أبرز الاعتمادات الدولية المتخصصة في جودة المختبرات الطبية وأكثرها صرامة.','["وجاء هذا الإنجاز بعد اجتياز المختبر عملية تقييم شاملة نفّذها فريق من مفتشي الكلية الأمريكية وخبرائها، شملت مراجعة الأنظمة التشغيلية وإجراءات الجودة وكفاءة الكوادر البشرية ودقة النتائج المخبرية، فضلاً عن التحقق من تطبيق أفضل الممارسات العالمية في السلامة وإدارة المخاطر وضبط الجودة.","ويعكس هذا الاعتماد التزام مدينة الملك سلمان الطبية بتطوير خدماتها التشخيصية وفق أعلى المعايير الدولية، بما يُسهم في تعزيز سلامة المرضى، ورفع موثوقية النتائج المخبرية، ودعم القرارات الطبية المبنية على أسس علمية دقيقة.","ويأتي هذا الإنجاز في إطار مساعي مدينة الملك سلمان الطبية لتحقيق التميز المؤسسي وترسيخ ثقافة الجودة والتحسين المستمر، بما يتوافق مع مستهدفات القطاع الصحي في المملكة العربية السعودية ويرتقي بمستوى الخدمات المقدمة للمستفيدين."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/gc2t6nn','https://sabq.org/article/gc2t6nn','','https://sabq.org/article/gc2t6nn','صحيفة سبق','السعودية','2026-08-13T06:57:00.000Z','2026-08-13T09:59:00.000Z','2026-08-14T07:59:39.596Z','https://media.sabq.org/news/2026/08/bd69db5f-7b6d-4449-a8d1-7d35fe5d91e2/w1280.webp','/api/media/76099c36-3a05-4beb-8a51-89f6a1cab666','/api/media/76099c36-3a05-4beb-8a51-89f6a1cab666?variant=thumbnail','مختبر مستشفى الولادة والأطفال بالمدينة المنورة يحصل على اعتماد الكلية الأمريكية لعلم الأمراض',1280,720,'valid','published','archived','valid',54,'ebd80e7a5bfebe03dc5ffb0c36fd89029baba6f4bf026c943dafa800624954c0','c61fbdf6873fc97d628bdffdc7564a5ef7c810d84ad980d7cc292089b81fbffb','محدّث','2026-08-14T07:59:39.596Z','2026-10-07T20:57:56.969Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الثقافة والفنون","المدينة المنورة"]','["الصحة العامة","الثقافة والفنون","المدينة المنورة"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":5},{"category":"المناطق","score":3},{"category":"الرياضة","score":1.5}]','Temporarily Unreachable','2026-10-07T20:57:56.969Z',NULL,83,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0dbd5b7e-ef11-4863-83ba-12979f18a6a8','news-0dbd5b7e-ef11-4863-83ba-12979f18a6a8','أوامر ملكية: إعادة تشكيل مجلس الوزراء برئاسة ولي العهد.. وتغييران في قمة «السوق المالية» و«المحتوى المحلي»','اوامر ملكيه اعاده تشكيل مجلس الوزراء برئاسه ولي العهد وتغييران في قمه السوق الماليه و المحتوي المحلي','صدرت اليوم حزمة من الأوامر الملكية، تقضي بإعادة تشكيل مجلس الوزراء برئاسة صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود، ولي العهد رئيس مجلس الوزراء، وبأعضائه الحاليين — إلى جانب تغييرين قياديين في رئاسة مجلسي هيئة السوق المالية وهيئة المحتوى المحلي والمشتريات الحكومية، وفق ما أوردته وكالة الأنباء السعودية (واس).','["تجديد مجلس الوزراء فقد قضى الأمر الملكي الأول بإعادة تشكيل مجلس الوزراء برئاسة سمو ولي العهد وبأعضائه الحاليين، في تجديدٍ يعكس استمرار الفريق الحكومي القائم على تنفيذ مستهدفات رؤية السعودية 2030 وبرامجها.","وزير الطاقة رئيساً لـ«المحتوى المحلي» كما قضى أمر ملكي بإعفاء معالي الأستاذ بندر بن إبراهيم بن عبدالله الخريف من رئاسة مجلس إدارة هيئة المحتوى المحلي والمشتريات الحكومية، وتعيين صاحب السمو الملكي الأمير عبدالعزيز بن سلمان بن عبدالعزيز آل سعود، وزير الطاقة، رئيساً لمجلس إدارة الهيئة — المعنية بتنمية المحتوى المحلي وتوطين الصناعات وتعظيم أثر المشتريات الحكومية في الاقتصاد الوطني.","السديري إلى قمة «السوق المالية» بمرتبة وزير وقضى أمر ملكي بإعفاء معالي الأستاذ محمد بن عبدالله بن إبراهيم القويز، رئيس مجلس هيئة السوق المالية، من منصبه، وتعيين معالي الأستاذ مازن بن تركي بن عبدالله السديري رئيساً لمجلس الهيئة بمرتبة وزير .","ويتسلم السديري — المستشار بالأمانة العامة لمجلس الوزراء والرئيس السابق لإدارة الأبحاث في «الراجحي المالية» — قيادة الجهاز المنظم لأحد أكبر أسواق المال في المنطقة، خلفاً للقويز الذي قادها منذ 2017 في مرحلة شهدت الطرح التاريخي لأرامكو السعودية، وتوسعاً غير مسبوق في الطروحات، وانضمام السوق للمؤشرات العالمية الكبرى."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/th8meix','https://sabq.org/article/th8meix','','https://sabq.org/article/th8meix','صحيفة سبق','السعودية','2026-08-13T06:35:00.000Z','2026-08-13T14:08:00.000Z','2026-08-14T07:59:40.063Z','https://media.sabq.org/news/2026/08/487c8193-2f28-4bfd-8a64-518a76e12b32/w1600.webp','/api/media/0dbd5b7e-ef11-4863-83ba-12979f18a6a8','/api/media/0dbd5b7e-ef11-4863-83ba-12979f18a6a8?variant=thumbnail','أوامر ملكية: إعادة تشكيل مجلس الوزراء برئاسة ولي العهد.. وتغييران في قمة «السوق المالية» و«المحتوى المحلي»',1600,899,'valid','published','archived','valid',99,'142079ff5c86b1bffeca57e1df18bdcdbde2b341c3ff28ecbc196acdb03c63cf','8128053f1ad35aa76d704c739b4b096c974130a35fdc1ad04c02ccf17a4a0cc6','محدّث','2026-08-14T07:59:40.063Z','2026-10-07T20:57:56.964Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد وتغييران في قمة","رئيس مجلس هيئة السوق المالية","وزير الطاقة رئيسا لـ المحتوى","مجلس الوزراء برئاسة ولي العهد","هيئة المحتوى المحلي والمشتريات الحكومية","الطاقة والنفط","الاقتصاد والأسواق"]','["ولي العهد وتغييران في قمة","رئيس مجلس هيئة السوق المالية","وزير الطاقة رئيسا لـ المحتوى","مجلس الوزراء برئاسة ولي العهد","هيئة المحتوى المحلي والمشتريات الحكومية","الطاقة والنفط"]','classified','','[{"category":"الاقتصاد","score":11.5},{"category":"الوظائف وسوق العمل","score":4},{"category":"الطاقة والصناعة","score":3.5}]','Temporarily Unreachable','2026-10-07T20:57:56.964Z',NULL,81,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fe0b1da6-3e57-42b3-81ec-eb6a3dc0a9bb','news-fe0b1da6-3e57-42b3-81ec-eb6a3dc0a9bb','مطار هيثرو في لندن  يفقد 2 مليون راكب من الشرق الأوسط.. وإسطنبول يخطفهم','مطار هيثرو في لندن يفقد 2 مليون راكب من الشرق الاوسط واسطنبول يخطفهم','يواجه مطار «لندن هيثرو» -أحد أكبر وأبرز مراكز الطيران الدولي في العالم- تحولاً جغرافياً وتسويقياً لافتاً في حركة الطيران، إثر فقدانه نحو مليونين من ركابه القادمين والمتجهين نحو منطقة الشرق الأوسط وحتى منتصف العام الجاري.','["وأظهرت البيانات الإحصائية الخاصة بتدفقات الطيران والربط الجوي تراجعاً كبيراً في مؤشرات المطار البريطاني: خسارة ربع المسافرين: سجل المطار تراجعاً حاداً بنسبة 25% في حركة الركاب مع دول الشرق الأوسط، وهو ما يعادل فقدان ما يقارب مليوني مسافر من أصل حصته السنوية المعتادة من المنطقة.","تقلص الطائرات والرحلات: انخفض عدد الرحلات الجوية المباشرة بين هيثرو والشرق الأوسط بنسبة 21%.","هبوط الحركة الإجمالية: تراجع إجمالي المسافرين في المطار بنسبة 1.5%، مما فرض ضغوطاً تشغيلية واقتصادية على إدارة المطار والشركات العاملة فيه.","إسطنبول تسحب البساط وتنتزع الصدارة وفي الوقت الذي يعاني فيه المطار اللندني من تراجع حركته الجوية، استغلت مطارات منافسة هذا التحول الرقمي والجغرافي؛ إذ نجح «مطار إسطنبول الدولي» في سحب البساط واختطاف النصيب الأكبر من حركة السياحة والترانزيت مسجلاً نمواً بنسبة 2.3%."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/4an241w','https://sabq.org/article/4an241w','','https://sabq.org/article/4an241w','خالد خليل','السعودية','2026-08-13T06:32:00.000Z','2026-08-13T09:32:00.000Z','2026-08-14T07:59:40.326Z','https://media.sabq.org/news/2026/08/bec63681-778e-4764-8041-7ae7f913c214/w710.webp','/api/media/fe0b1da6-3e57-42b3-81ec-eb6a3dc0a9bb','/api/media/fe0b1da6-3e57-42b3-81ec-eb6a3dc0a9bb?variant=thumbnail','مطار هيثرو في لندن  يفقد 2 مليون راكب من الشرق الأوسط.. وإسطنبول يخطفهم',710,532,'valid','published','archived','valid',94,'91d4aecb5685d5dd0ec72219d36cea1d46611f42e3e9fcee498a8ff2f348422f','f1e0b7c1a141eff20271db745d06e3aefab42da01a139c24a1ebbae6bc248536','محدّث','2026-08-14T07:59:40.326Z','2026-10-07T20:58:46.691Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي","الشرق الأوسط"]','["السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي","الشرق الأوسط"]','classified','','[{"category":"الاقتصاد","score":1.5},{"category":"التقنية","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:58:46.691Z',200,87,0,'source_article_available','',NULL,NULL,'body:6118201f7fb3ee995ad8ff9b2adcbc676b86bf40926a5bc870af90ca65c4f524','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('22cd5182-ab05-459a-92fa-3c4c341d3aea','news-22cd5182-ab05-459a-92fa-3c4c341d3aea','ضبط مواطن صاد «وعلاً» مهدداً بالانقراض في عسير بحوزته مسدس وذخيرة','ضبط مواطن صاد وعلا مهددا بالانقراض في عسير بحوزته مسدس وذخيره','أوقفت شرطة منطقة عسير، بالتعاون مع القوة الخاصة للأمن البيئي بالمنطقة، المواطن حسين ظافر حسين القحطاني، بعد ضبطه متلبساً بصيد كائنات فطرية مهددة بالانقراض من نوع «الوعل»، وبحوزته مسدس و20 طلقة ذخيرة متنوعة و4 كائنات فطرية مصيدة.','["وأفاد الأمن العام بأن الإجراءات النظامية اتُّخذت بحق الموقوف، وأُحيل إلى الجهة المختصة للبت في قضيته.","وشدّد الأمن العام على وجوب الالتزام بنظام البيئة ولوائحه التنفيذية التي تحظر صيد الكائنات الفطرية، مبيّناً أن العقوبات المقررة على المخالفين تشمل: غرامة 60,000 ريال لصيد الوعل، وغرامة 10,000 ريال للصيد دون ترخيص، وغرامة 5,000 ريال للصيد في المناطق المحظورة.","ودعا الأمن العام المواطنين إلى الإبلاغ الفوري عن أي اعتداء على البيئة أو الحياة الفطرية، عبر الاتصال بالرقم 911 في مناطق مكة المكرمة والمدينة المنورة والرياض والمنطقة الشرقية، والرقمين 999 و996 في بقية مناطق المملكة، مؤكداً أن جميع البلاغات تُعامَل بسرية تامة دون أي مسؤولية على المبلِّغ."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/1qoedul','https://sabq.org/article/1qoedul','','https://sabq.org/article/1qoedul','صحيفة سبق','السعودية','2026-08-13T06:24:00.000Z','2026-08-13T09:44:00.000Z','2026-08-14T07:59:41.585Z','https://media.sabq.org/news/2026/08/ac9a5e7b-f228-4422-b66d-f28179833839/w1170.webp','/api/media/22cd5182-ab05-459a-92fa-3c4c341d3aea','/api/media/22cd5182-ab05-459a-92fa-3c4c341d3aea?variant=thumbnail','ضبط مواطن صاد «وعلاً» مهدداً بالانقراض في عسير بحوزته مسدس وذخيرة',1170,1280,'valid','published','archived','valid',89,'2a3bf4959ce1ac24c01c6c785ec6d4e5a65a955548b597ef7f24d1c4ecef8a8b','edc53f857a984d9f1af00886b135e12904838d0912499fc436c3ed0cd823b3c5','محدّث','2026-08-14T07:59:41.585Z','2026-10-07T20:57:56.959Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي","مكة","عسير","الرياض","المدينة المنورة"]','["التقنية والتحول الرقمي","المدينة المنورة"]','classified','','[{"category":"التقنية","score":3.5},{"category":"المجتمع","score":3},{"category":"أخبار السعودية","score":1.5}]','Temporarily Unreachable','2026-10-07T20:57:56.959Z',NULL,85,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b619b8ef-0a30-489a-9c3f-a690ba95e698','news-b619b8ef-0a30-489a-9c3f-a690ba95e698','الجوف تنتج أكثر من 880 طناً من التين سنوياً بتسعة أصناف متنوعة','الجوف تنتج اكثر من 880 طنا من التين سنويا بتسعه اصناف متنوعه','تتميز منطقة الجوف بتنوع محاصيلها الزراعية، مستفيدةً من خصوبة التربة وجودة المياه، مما أسهم في تنوع إنتاجها من الفواكه الموسمية، ومن أبرزها محصول التين الذي يشهد حضوراً متنامياً في مزارع المنطقة.','["وأوضح مدير مكتب وزارة البيئة والمياه والزراعة بمدينة سكاكا الدكتور عقاب بن مخيلف الرويلي، أن إنتاج المنطقة من أصناف التين يتجاوز 880 طناً سنوياً، مشيراً إلى أن أبرز الأصناف المزروعة تشمل: «براون التركي»، و«السلطاني»، و«البلدي»، و«الإسباني الأصفر»، و«الغاني»، و«العبيد»، و«الفرنسي»، و«العسلي»، و«الإسباني الأسود»، في تنوع يعكس تعدد التجارب الزراعية بالمنطقة.","وتأتي زراعة التين ضمن منظومة الإنتاج الزراعي المتنوع الذي تشتهر به الجوف، في ظل مقوماتها الطبيعية التي أسهمت في نجاح زراعة أصناف عديدة من الفواكه، إلى جانب جهود المزارعين في تطوير أساليب الزراعة وتحسين جودة الإنتاج.","ومن أبرز المزارعين في هذا المجال مساعد الشمري، الذي يزرع عدة أصناف من التين ويتابع مراحل نموها وإنتاجها حتى الحصاد، مستفيداً من المقومات الزراعية التي تتميز بها المنطقة.","وأوضح الشمري أن تنوع أصناف التين يتيح للمزارعين خيارات متعددة في الإنتاج، مبيناً أن العناية بالمحصول تبدأ من اختيار الصنف المناسب، وتمر بمراحل الري والتسميد والمتابعة المستمرة، وصولاً إلى الحصاد في الوقت الملائم لضمان جودة الثمار."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ofaujnu','https://sabq.org/article/ofaujnu','','https://sabq.org/article/ofaujnu','صحيفة سبق','السعودية','2026-08-13T05:46:00.000Z','2026-08-13T08:47:00.000Z','2026-08-14T07:59:41.830Z','https://media.sabq.org/news/2026/08/0cc973d8-d9a6-465d-be5a-aa7fdfde60c8/w1600.webp','/api/media/b619b8ef-0a30-489a-9c3f-a690ba95e698','/api/media/b619b8ef-0a30-489a-9c3f-a690ba95e698?variant=thumbnail','صورة من الألبوم',1600,1066,'valid','published','archived','valid',45,'33cf6d83a0b406c3075af8ab3b9d6427e67fbaacf33f3785897c13b3ac9ac467','37993bd605cc902478a3c23d718a52c975c939974d31318ceac27f3ba81efc78','محدّث','2026-08-14T07:59:41.830Z','2026-10-07T20:57:33.741Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البيئة والمياه والزراعة بمدينة","الاقتصاد والأسواق","الجوف"]','["وزارة البيئة والمياه والزراعة بمدينة","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"الاقتصاد","score":1.5},{"category":"الصحة","score":1.5}]','Temporarily Unreachable','2026-10-07T20:57:33.741Z',NULL,82,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b5c9812b-d7d9-49f3-98e4-e4f9cdd80afb','news-b5c9812b-d7d9-49f3-98e4-e4f9cdd80afb','تأهيل شامل لحديقة الأندلس بعسير بمساحة 28 ألف م² ومساحات خضراء وألعاب عائلية آمنة','تاهيل شامل لحديقه الاندلس بعسير بمساحه 28 الف م2 ومساحات خضراء والعاب عائليه امنه','تستكمل أمانة منطقة عسير، ممثلةً في وكالة البنية التحتية، أعمال تأهيل وتطوير حديقة الأندلس، ضمن جهودها الرامية إلى تطوير الحدائق والوجهات العامة ورفع كفاءة المرافق، بما يعزز جودة البيئة الحضرية.','["وشملت أعمال المشروع تأهيل الحديقة على مساحة إجمالية تبلغ نحو 28,300 متر مربع، إلى جانب تطوير منطقة الألعاب وإعادة تأهيلها على مساحة 2,650 متراً مربعاً، بما يوفر بيئة ترفيهية آمنة ومهيأة للأطفال والعائلات.","كما تضمنت الأعمال إعادة زراعة نحو 17,400 متر مربع من المسطحات الخضراء، بما يسهم في تعزيز الغطاء النباتي والارتقاء بالمشهد الحضري للحديقة.","وتأتي أعمال تأهيل حديقة الأندلس ضمن مشاريع أمانة منطقة عسير لتطوير الحدائق والمتنزهات ورفع كفاءة المرافق العامة، ومن المقرر افتتاح الحديقة قريباً عقب استكمال الأعمال والتجهيزات النهائية، لتنضم إلى منظومة الوجهات الترفيهية التي تعمل الأمانة على تطويرها وتهيئتها."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/pv53ZYA','https://sabq.org/article/pv53ZYA','','https://sabq.org/article/pv53ZYA','سعيد بن محيا ','السعودية','2026-08-13T06:15:00.000Z','2026-08-13T09:15:00.000Z','2026-08-14T07:59:41.888Z','https://media.sabq.org/news/2026/08/b27fbbb7-cdf4-4e62-ae75-8da707902dfb/w1280.webp','/api/media/b5c9812b-d7d9-49f3-98e4-e4f9cdd80afb','/api/media/b5c9812b-d7d9-49f3-98e4-e4f9cdd80afb?variant=thumbnail','تأهيل شامل لحديقة الأندلس بعسير بمساحة 28 ألف م² ومساحات خضراء وألعاب عائلية آمنة',1280,750,'valid','published','archived','valid',46,'a15c7a3a35962535e753f9331dde3b126cdec1b6c6c02837e43d076a84439e44','75c6d8957ddce5e651124833f11b43fdd4fd2cd84a356e5aa7164c1c9b1e172f','محدّث','2026-08-14T07:59:41.888Z','2026-10-07T20:58:44.884Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["عسير"]','[]','manual_approved','below_category_threshold','[{"category":"البيئة والمناخ","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:58:44.884Z',200,84,0,'source_article_available','',NULL,NULL,'body:dcada77ca6c89c1c66dcac33d559dad7a24aedfc47ef43942c442fad2541fe25','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f6e1c743-c15a-4dc6-9f58-ceeb5709e656','news-f6e1c743-c15a-4dc6-9f58-ceeb5709e656','5 كؤوس وجوائز 1.7 مليون ريال في الأسبوع الرابع من موسم سباقات الطائف 2026','5 كؤوس وجوائز 1 7 مليون ريال في الاسبوع الرابع من موسم سباقات الطائف 2026','تنطلق غداً الجمعة منافسات الأسبوع الرابع من موسم سباقات الطائف 2026، على ميدان الملك خالد للفروسية بمحافظة الطائف، حيث تُقام الأمسيتان السابعة والثامنة يومي الجمعة والسبت، بواقع أحد عشر شوطاً في كل أمسية، وبإجمالي جوائز مالية يبلغ 1,700,000 ريال.','["وتتجه الأنظار إلى عدد من المواجهات القوية والكؤوس المرتقبة، وسط مشاركة نخبة من الجياد الساعية إلى حصد الانتصارات.","كؤوس يوم الجمعة تُفتتح كؤوس يوم الجمعة بـ«كأس تحدي نادي سباقات الخيل»، المقام على مسافة 1600 متر بجائزة مالية قدرها 150 ألف ريال، ويبرز فيه الجواد «تحزيم» الفائز في آخر مشاركاته بكأس الاتحاد الآسيوي ضمن أمسية كأس السعودية بشعار الأمير فيصل بن خالد بن عبدالعزيز، إلى جانب «كافلهم» بشعار أبناء الملك عبدالله بن عبدالعزيز.","وفي «كأس جامعة أم القرى للأفراس»، على مسافة 1600 متر بجائزة مالية تبلغ 150 ألف ريال، تتقدم الترشيحات «الخنساء» الفائزة بالشوط التحضيري للكأس بشعار عبدالله سعيد المداح، إلى جانب «غرامي» و«دانس ديسير» بشعار الشيخ عبدالله حمود المالك الصباح، و«نوافع» بشعار أبناء الملك عبدالله بن عبدالعزيز.","ويشهد «كأس الورد الطائفي»، على مسافة 2000 متر بجائزة قدرها 150 ألف ريال، منافسة قوية يتقدمها الجواد «مستحسن» بشعار أبناء الملك عبدالله بن عبدالعزيز، إلى جانب «يرعبهم» بشعار فهد ضيدان العتيبي، و«داربي» بشعار عبدالله عبدالعزيز العدساني."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/96vj89v','https://sabq.org/article/96vj89v','','https://sabq.org/article/96vj89v','صحيفة سبق','السعودية','2026-08-13T05:40:00.000Z','2026-08-13T08:41:00.000Z','2026-08-14T07:59:43.026Z','https://media.sabq.org/news/2026/08/40f8a561-ae45-4083-94ae-968303836de0/w660.webp','/api/media/f6e1c743-c15a-4dc6-9f58-ceeb5709e656','/api/media/f6e1c743-c15a-4dc6-9f58-ceeb5709e656?variant=thumbnail','5 كؤوس وجوائز 1.7 مليون ريال في الأسبوع الرابع من موسم سباقات الطائف 2026',660,440,'valid','published','archived','valid',46,'5df59d8bbdaa656e28afd58b4fbca184254a2a66cab2fd660e1ca385fefef53c','24a31596146a2f9e657b392806e6d0161668cf5062a24a98fcdbbd14c70091d5','محدّث','2026-08-14T07:59:43.026Z','2026-10-07T20:58:47.580Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة أم القرى للأفراس على","التعليم والتدريب","الرياضة السعودية"]','["جامعة أم القرى للأفراس على","التعليم والتدريب","الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الصحة","score":1.5},{"category":"التعليم","score":1.5}]','Active','2026-10-07T20:58:47.580Z',200,85,0,'source_article_available','',NULL,NULL,'body:94de4c2af477442d46696ad949864152f34e69f448be06de87b40cf9375928cb','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7f754b8a-992d-4fbf-9c05-9547c4cef4e7','news-7f754b8a-992d-4fbf-9c05-9547c4cef4e7','420 مليون ريال إنفاق يومي للسعوديين على السياحة في المملكة','420 مليون ريال انفاق يومي للسعوديين علي السياحه في المملكه','أظهرت قراءة رقمية تحليليّة لبيانات السياحة المحلية صدارةً غير مسبوقة للقطاع السياحي في المملكة العربية السعودية مع بداية هذا العام؛ حيث وصل متوسط الإنفاق اليومي للسياح المحليين داخل المملكة إلى نحو 420 مليون ريال سعودي يومياً خلال الأشهر الثلاثة الأولى من العام الجاري.','["وفقاً للتسلسل الإحصائي الصادر رسمياً عن وزارة السياحة (وكالة البيانات ودعم القرار)، بلغ إجمالي الإنفاق السياحي للسياحة المحلية خلال الربع الأول من عام 2026م ما قيمته 37.8 مليار ريال سعودي، محققاً نمواً قياسياً بنسبة 17% مقارنة بالربع الأول من عام 2025م.","وترافق هذا المعدل المالي الضخم مع حركة سياحية نشطة عبر مختلف مناطق المملكة؛ حيث سجلت المؤشرات الرسمية: إجمالي عدد السياح المحليين: بلغ 26.6 مليون سائح (من زوار المبيت)، بنسبة نمو بلغت 7% مقارنة بالفترة نفسها من العام الماضي.","معدل مدة الإقامة: بلغ متوسط إقامة السائح السعودي 5.9 ليلة، بينما سجل متوسط إقامة السائح غير السعودي 7.0 ليالٍ.","خريطة الوجهات والدوافع الرئيسية توزعت الحركة السياحية للمواطنين والمقيمين على عدد من المناطق الرئيسية، حيث استمرت منطقة مكة المكرمة في الصدارة بـ 5.9 مليون زائر سعودي و3.3 مليون زائر غير سعودي، تلتها منطقة الرياض بـ 4.7 مليون زائر سعودي، ثم المنطقة الشرقية بـ 2.6 مليون زائر سعودي."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/x2mxhjs','https://sabq.org/article/x2mxhjs','','https://sabq.org/article/x2mxhjs','خالد خليل','السعودية','2026-08-13T05:22:00.000Z','2026-08-13T08:23:00.000Z','2026-08-14T07:59:43.034Z','https://media.sabq.org/news/2026/08/bf10c3c4-f204-453e-b648-b2f46d7c3044/w600.webp','/api/media/7f754b8a-992d-4fbf-9c05-9547c4cef4e7','/api/media/7f754b8a-992d-4fbf-9c05-9547c4cef4e7?variant=thumbnail','420 مليون ريال إنفاق يومي للسعوديين على السياحة في المملكة',600,336,'valid','published','archived','valid',58,'23c5fb9820849dfa3684bd1e99e65d8bae126e2c48f1bafae57b6a96201b2d99','0e75308645876dd89df423e566d0c9e186067d0287e8a8cfa92d94173ce8b9d4','محدّث','2026-08-14T07:59:43.034Z','2026-10-07T20:58:47.584Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة السياحة وكالة البيانات ودعم","السفر والسياحة","مكة","الرياض"]','["وزارة السياحة وكالة البيانات ودعم","السفر والسياحة"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":3},{"category":"الاقتصاد","score":3}]','Active','2026-10-07T20:58:47.584Z',200,84,0,'source_article_available','',NULL,NULL,'body:7ed6681a84d1992218f01ebadace1133a66242ddcb335da21fc14637acedee30','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dc253fa2-19ce-4ce6-8f17-19456760bebd','news-dc253fa2-19ce-4ce6-8f17-19456760bebd','جمعية المودة تطلق حملة «رؤية أوضح» لتعزيز دور الأسرة في تمكين الشباب','جمعيه الموده تطلق حمله رؤيه اوضح لتعزيز دور الاسره في تمكين الشباب','أطلقت جمعية المودة للتنمية الأسرية حملة «رؤية أوضح» التوعوية، بالتزامن مع اليوم العالمي للشباب الموافق 12 أغسطس من كل عام، بهدف تعزيز الوعي بالدور المحوري الذي تؤدّيه الأسرة في دعم الشباب، ومساندتهم في قراراتهم، والإيمان بقدراتهم، وبناء بيئة أسرية تساعدهم على مواجهة تحدّيات المستقبل بوعي وثقة.','["وتنطلق الحملة من مستهدفات رؤية السعودية 2030 وأهداف التنمية المستدامة للأمم المتحدة، التي تؤكّد أهمية تمكين الشباب وتعزيز مشاركتهم في التنمية، وبناء مجتمعات أكثر استقراراً واستدامة، مع إبراز دور الأسرة شريكاً أساسياً في دعم الشباب وتنمية قدراتهم.","وترتكز «رؤية أوضح» على أربعة محاور أساسية، هي: أسرة توجّه وتدعم القرارات، والحوار الأسري الإيجابي الفعّال، والتقنية الآمنة التي تعزّز التواصل، والبداية المسؤولة للحياة الزوجية؛ إذ تقدّم الحملة رسائل توعوية ومعرفية تُعزّز وعي الشباب وأسرهم، وتدعم قدرتهم على اتخاذ قرارات أكثر رشداً.","وأكّد الرئيس التنفيذي لجمعية المودة للتنمية الأسرية، محمد بن علي آل رضي، أن إطلاق حملة «رؤية أوضح» يأتي امتداداً لاهتمام الجمعية بمرحلة الشباب، وحرصها على تطوير البرامج والمبادرات التي تستجيب لاحتياجاتهم واحتياجات أسرهم، مشيراً إلى أن تمكين الشباب يبدأ من بيئة أسرية واعية تؤمن بقدراتهم، وتستمع إليهم، وتمنحهم الدعم اللازم لاتخاذ قرارات أكثر وعياً.","وأوضح آل رضي أن الحملة تركّز على تعزيز دور الأسرة شريكاً في رحلة الشباب، من خلال دعم الحوار الفعّال، وبناء الثقة، والمساندة في اتخاذ القرارات، إلى جانب تعزيز الاستخدام الواعي للتقنية بما يحافظ على جودة التواصل الأسري، مؤكداً أن هذه الجوانب تمثّل عناصر مترابطة في بناء أسر أكثر قدرة على دعم أبنائها في مراحل النمو وصناعة المستقبل."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7bkpsyx','https://sabq.org/article/7bkpsyx','','https://sabq.org/article/7bkpsyx','صحيفة سبق','السعودية','2026-08-13T05:25:00.000Z','2026-08-13T08:26:00.000Z','2026-08-14T07:59:43.064Z','https://media.sabq.org/news/2026/08/b43c3168-f887-426c-b254-3208157ce66d/w761.webp','/api/media/dc253fa2-19ce-4ce6-8f17-19456760bebd','/api/media/dc253fa2-19ce-4ce6-8f17-19456760bebd?variant=thumbnail','جمعية المودة تطلق حملة «رؤية أوضح» لتعزيز دور الأسرة في تمكين الشباب',761,786,'valid','published','archived','valid',91,'c18f166870e6c4485a1c720aea5dba2ca7f17fe27acf03da99218df388030385','3ad6e0e536dcfba2294fb6e1762c09432d0a9ae5d0b5c27c45af942d18312bd1','محدّث','2026-08-14T07:59:43.064Z','2026-10-07T20:58:44.961Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي"]','["التقنية والتحول الرقمي"]','classified','','[{"category":"الاقتصاد","score":4},{"category":"أخبار السعودية","score":1.5},{"category":"التعليم","score":1.5}]','Active','2026-10-07T20:58:44.961Z',200,86,0,'source_article_available','',NULL,NULL,'body:f0d8a16be2f4d8f05802ec28990139456c51f57a2fd6808164b493bda315a9be','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0f89004b-3ba2-4a21-99e4-41149b3c665a','news-0f89004b-3ba2-4a21-99e4-41149b3c665a','ناقش مستجدات الأوضاع بالمنطقة.. لقاء أخوي بين وزراء خارجية المملكة ومصر وتركيا في العلمين','ناقش مستجدات الاوضاع بالمنطقه لقاء اخوي بين وزراء خارجيه المملكه ومصر وتركيا في العلمين','عقد لقاء أخوي يوم الخميس، بين وزراء خارجية المملكة الأمير فيصل بن فرحان ، و مصر بدر عبدالعاطي، وتركيا هاكان فيدان ، في مدينة العلمين المصرية. وأوضحت في بيان مقتضب، أن اللقاء ناقش خلاله الوزراء مستجدات الأوضاع في المنطقة.','["عقد لقاء أخوي يوم الخميس، بين وزراء خارجية المملكة الأمير فيصل بن فرحان ، و مصر بدر عبدالعاطي، وتركيا هاكان فيدان ، في مدينة العلمين المصرية.","وقالت وزارة الخارجية المصرية في بيان صادر عنها، إن لقاء أخويًا جمع بدر عبد العاطى وزير الخارجية والتعاون الدولى والمصريين بالخارج، ووزير الخارجية السعودي الأمير فيصل بن فرحان، وهاكان فيدان وزير خارجية تركيا، في مدينة العلمين يوم الخميس.","وأوضحت في بيان مقتضب، أن اللقاء ناقش خلاله الوزراء مستجدات الأوضاع في المنطقة."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/1muec0ahg','https://ajel.sa/local/1muec0ahg','https://ajel.sa/local/1muec0ahg','https://ajel.sa/local/1muec0ahg','فريق التحرير','السعودية','2026-08-13T23:22:00.000Z','Wed, 07 Oct 2026 20:51:53 GMT','2026-08-14T10:00:47.708Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/1000941036-crop-U2WKjOwT.jpg','/api/media/0f89004b-3ba2-4a21-99e4-41149b3c665a','/api/media/0f89004b-3ba2-4a21-99e4-41149b3c665a?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',44,'8bd9b34a7d8dce5ce072a168eaab4b1e0a214df28079581370bf4a3fdf5a0af8','61c33bff9c8927a0907f4fd34a8600962bbe6d2b28fbbbee284a0009f5f490e6',NULL,'2026-08-14T10:00:47.708Z','2026-10-07T20:51:54.798Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الخارجية المصرية في بيان","وزير الخارجية والتعاون الدولى والمصريين","تركيا"]','["وزارة الخارجية المصرية في بيان","وزير الخارجية والتعاون الدولى والمصريين"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":3},{"category":"السياسة","score":2},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:51:54.798Z',200,77,0,'source_content_changed','',NULL,NULL,'body:91545966ab57cbb4123aebd40979fd578ea7d3ce66e6ad19a5e9f67bbd9cea6a','Wed, 07 Oct 2026 20:51:53 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b1abd573-d742-47f9-8849-9b567a2c35d9','news-b1abd573-d742-47f9-8849-9b567a2c35d9','انفجار يهز مصنع ذخائر تابعاً لمجموعة دفاع ألمانية قرب روما','انفجار يهز مصنع ذخائر تابعا لمجموعه دفاع المانيه قرب روما','وقع انفجار عنيف بعد ظهر اليوم في مصنع لإنتاج الذخائر ببلدة كوليفيرو، الواقعة جنوب شرقي العاصمة الإيطالية روما.','["وأفادت قوات الدرك الإيطالية «كارابينييري» بأن الانفجار اندلع في المصنع التابع لمجموعة الدفاع الألمانية «KNDS»، المتخصص في إنتاج الذخائر متوسطة وكبيرة العيار المخصصة للدفاع البري والبحري.","وأشارت القوات إلى أن فرق الإطفاء تعمل على السيطرة على الحريق الناجم عن الانفجار، فيما لم تُكشف بعد تفاصيل إضافية حول الخسائر البشرية أو المادية."]','الطاقة والصناعة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/p73cdfb','https://sabq.org/article/p73cdfb','','https://sabq.org/article/p73cdfb','صحيفة سبق','السعودية','2026-08-13T09:05:00.000Z','2026-08-13T12:07:00.000Z','2026-08-14T10:05:31.786Z','https://media.sabq.org/news/2026/08/4b002979-29d9-466b-b204-e824011b85b8/w600.webp','/api/media/b1abd573-d742-47f9-8849-9b567a2c35d9','/api/media/b1abd573-d742-47f9-8849-9b567a2c35d9?variant=thumbnail','انفجار يهز مصنع ذخائر تابعاً لمجموعة دفاع ألمانية قرب روما',600,346,'valid','published','archived','valid',47,'f4ea50189dd246bcdd4d15d11626e079959d5c07c7d74260ecaccd3182848d72','bbbd44a850e96178dbc24694836a9b6d013dc19fb233a275c41e252c7b31087b','محدّث','2026-08-14T10:05:31.786Z','2026-10-07T20:52:47.989Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والصناعة"]','["الطاقة والصناعة"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:52:47.989Z',200,80,0,'source_article_available','',NULL,NULL,'body:b224965a24ae2acaae7e31cb8491671b8cda66890760620bd718ab1b49a00412','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('80fa2be2-b7f3-48b6-82c5-cb08952a569c','news-80fa2be2-b7f3-48b6-82c5-cb08952a569c','جامعة الدول العربية تدين اقتحام المستوطنين للمسجد الأقصى وتطالب بوقفه فوراً','جامعه الدول العربيه تدين اقتحام المستوطنين للمسجد الاقصي وتطالب بوقفه فورا','أدانت الأمانة العامة لجامعة الدول العربية بأشد العبارات اقتحام مئات المستوطنين الإسرائيليين المسجد الأقصى المبارك، بحماية شرطة الاحتلال الإسرائيلي، وما رافق ذلك من أداء طقوس وصلوات تلمودية داخل باحات المسجد، واصفةً ذلك بأنه انتهاك صارخ لحرمة المسجد الأقصى وللقانون الدولي وقرارات الشرعية الدولية.','["وحذّرت الأمانة العامة في بيان أصدرته قطاع فلسطين والأراضي العربية المحتلة من خطورة استمرار هذه الممارسات الإسرائيلية، مؤكدةً أنها تمثّل مساساً مباشراً بالوضع التاريخي والقانوني القائم في المسجد الأقصى، ومحاولةً ممنهجة لتكريس التقسيم الزماني والمكاني للمسجد، بما يشكّل تهديداً خطيراً لحرية العبادة وللسلم والأمن في المنطقة.","وأكدت الأمانة أن المسجد الأقصى المبارك بكامل مساحته البالغة 144 دونماً هو مكان عبادة خالص للمسلمين، وأن إدارة أوقاف القدس وشؤون المسجد الأقصى هي الجهة صاحبة الاختصاص في إدارة شؤونه وفق الوضع التاريخي والقانوني القائم.","وحمّلت الأمانة إسرائيل -بوصفها القوة القائمة بالاحتلال- المسؤولية الكاملة عن هذه الانتهاكات المتكررة، مطالبةً إياها بالوقف الفوري لجميع الاقتحامات والاستفزازات والممارسات الهادفة إلى تغيير هوية المسجد الأقصى ووضعه التاريخي والقانوني، واحترام القانون الدولي والقانون الدولي الإنساني وقرارات الأمم المتحدة ذات الصلة.","ودعت الأمانة العامة المجتمع الدولي، ولا سيما مجلس الأمن، إلى تحمّل مسؤولياته في وقف هذه الانتهاكات الإسرائيلية المتصاعدة، وتوفير الحماية للشعب الفلسطيني ومقدساته، وعدم السماح باستمرار الإفلات من العقاب أو فرض الأمر الواقع بالقوة."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/8la552k','https://sabq.org/article/8la552k','','https://sabq.org/article/8la552k','صحيفة سبق','السعودية','2026-08-13T08:35:00.000Z','2026-08-13T11:35:00.000Z','2026-08-14T10:05:33.346Z','https://media.sabq.org/news/2026/08/82abb305-cc66-4ff2-af0c-c92c347705a2/w770.webp','/api/media/80fa2be2-b7f3-48b6-82c5-cb08952a569c','/api/media/80fa2be2-b7f3-48b6-82c5-cb08952a569c?variant=thumbnail','جامعة الدول العربية تدين اقتحام المستوطنين للمسجد الأقصى وتطالب بوقفه فوراً',770,513,'valid','published','archived','valid',48,'aca56b6042c17dd84147445dc0541e388236de41b3636897504176077bef5453','6bfa2eefdf6fd404823705151e859afe996dfa8c777814f7bb9be9abfeee7f17','محدّث','2026-08-14T10:05:33.346Z','2026-10-07T20:53:02.560Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس الأمن إلى تحم ل","الأمم المتحدة ذات الصلة ودعت","جامعة الدول العربية تدين اقتحام","التعليم والتدريب","فلسطين"]','["مجلس الأمن إلى تحم ل","الأمم المتحدة ذات الصلة ودعت","جامعة الدول العربية تدين اقتحام","التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"التعليم","score":3},{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:53:02.560Z',200,82,0,'source_article_available','',NULL,NULL,'body:c0c2faf4960c41f369fa5ba9b02d6c58438dbb8f2a951ad67cdc0354ce8cf063','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('54389009-f2e4-4ab5-924c-00527289a7f1','news-54389009-f2e4-4ab5-924c-00527289a7f1','الأمينُ العامُّ لرابطة العالم الإسلامي يَشهَد اجتماعَ الطاولةِ المُستديرة للقيادات الإسلامية والمسيحية في نيجيريا.. وتوقيع اتفاقياتها','الامين العام لرابطه العالم الاسلامي يشهد اجتماع الطاوله المستديره للقيادات الاسلاميه والمسيحيه في نيجيريا وتوقيع اتفاقياتها','التزامًا بمبادرة رابطة العالم الإسلامي للسِّلم المجتمعيّ في غرب أفريقيا، وما نتجَ عن مؤتمرها من قراراتٍ تضمَّنَها "إعلانُ أبوجا"، الذي اعتُمِدَ بإجماع القيادات الدينية الممثِّلة لكافّة الأديان والمذاهب في المنطقة، برعاية فخامة رئيس جمهورية نيجيريا الاتحادية، السيد بولا أحمد تينوبو، شهِدَ معالي الأمين العام لرابطة العالم الإسلامي، رئيسُ هيئة علماء المسلمين، ف','["التزامًا بمبادرة رابطة العالم الإسلامي للسِّلم المجتمعيّ في غرب أفريقيا، وما نتجَ عن مؤتمرها من قراراتٍ تضمَّنَها \"إعلانُ أبوجا\"، الذي اعتُمِدَ بإجماع القيادات الدينية الممثِّلة لكافّة الأديان والمذاهب في المنطقة، برعاية فخامة رئيس جمهورية نيجيريا الاتحادية، السيد بولا أحمد تينوبو، شهِدَ معالي الأمين العام لرابطة العالم الإسلامي، رئيسُ هيئة علماء المسلمين، فضيلةُ الشيخ الدكتور محمد بن عبدالكريم العيسى، اجتماعَ…","وأثمرَ الاجتماعُ عن توقيع حزمةٍ أوّليةٍ من الاتفاقيات، من أبرزها: مذكرة تفاهمٍ بين رابطة العالم الإسلامي ومركز الوساطة بين الأديان في نيجيريا، ومذكرة تفاهمٍ بين جماعة إزالة البدعة وإقامة السُّنَّة في نيجيريا ومجلس القيادات الدينية المسيحية في شمال نيجيريا، وكذلك توقيع مذكرة تفاهمٍ بين جماعة نصر الإسلام في نيجيريا ومبادرة الشباب المسيحي من أجل السلام والتنمية، إضافةً إلى مذكرة تفاهمٍ بين اتحاد منظمات أهل السنّة في…"]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/6fns3mi','https://sabq.org/article/6fns3mi','','https://sabq.org/article/6fns3mi','صحيفة سبق','السعودية','2026-08-13T08:58:00.000Z','2026-08-13T12:00:00.000Z','2026-08-14T10:05:33.354Z','https://media.sabq.org/news/2026/08/e79ed6bc-69c4-4d6f-842e-290fe87b29e4/w1600.webp','/api/media/54389009-f2e4-4ab5-924c-00527289a7f1','/api/media/54389009-f2e4-4ab5-924c-00527289a7f1?variant=thumbnail','صورة من الألبوم',1600,1066,'valid','published','archived','valid',50,'03c6091b8f8036507ad62b6e769b09164a6728b2616bb2bd3bfbd51f3797eb14','f5a5b067f9b21dbd7cb98be1ee459642bec7f959d7758196b32ddaa0c7270312','محدّث','2026-08-14T10:05:33.354Z','2026-10-07T20:53:00.147Z','','',0,0,'saudi_region','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة علماء المسلمين فضيلة الشيخ","رئيس جمهورية نيجيريا الاتحادية السيد"]','["هيئة علماء المسلمين فضيلة الشيخ","رئيس جمهورية نيجيريا الاتحادية السيد"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"الرياضة","score":3},{"category":"الطاقة والصناعة","score":1.5}]','Active','2026-10-07T20:53:00.147Z',200,80,0,'source_article_available','',NULL,NULL,'body:02c46d8131f7a08d26536e2b4e53a2f939bea0a2c36d50726c1a1e7d3b157dc0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('acfe9d20-0914-4cba-a046-07b6edb86394','news-acfe9d20-0914-4cba-a046-07b6edb86394','المملكة ترفع نسبة التخلص من مواد مستنفدة لطبقة الأوزون إلى 69% في النصف الأول من 2026','المملكه ترفع نسبه التخلص من مواد مستنفده لطبقه الاوزون الي 69 في النصف الاول من 2026','رفعت المملكة العربية السعودية نسبة التخلص من المواد المستنفدة لطبقة الأوزون إلى 69% خلال النصف الأول من عام 2026، في خطوة تعزز التزامها بتنفيذ بروتوكول مونتريال والتخلص التدريجي من غازات الهيدروكلوروفلوروكربون (HCFC)، وفق بيانات المركز الوطني للرقابة على الالتزام البيئي.','["وأعلن المركز فسح أكثر من 8 آلاف طن متري من المواد المستنفدة لطبقة الأوزون وموارد (HFC) منذ بداية العام الجاري، ضمن مشروع الخفض التدريجي لهذه المواد، بما يضمن تنظيم استيرادها وتداولها وفق الاشتراطات البيئية والالتزامات الدولية.","وأوضح المتحدث الرسمي للمركز الوطني للرقابة على الالتزام البيئي سعد المطرفي، أن هذا التقدم تزامن مع تعزيز المنظومة الرقابية على المواد المستنفدة لطبقة الأوزون عبر نظام الفسح البيئي الذي ينظم عمليات الاستيراد والتداول، مبيناً أن المركز أصدر منذ عام 2023 أكثر من 3200 إذن فسح للمواد الخاضعة لأحكام بروتوكول مونتريال، بما يعزز الامتثال البيئي ويضمن الالتزام بالحصص والكميات المقررة.","وأشار المطرفي إلى أن التعاون بين المركز الوطني للرقابة على الالتزام البيئي وهيئة الزكاة والضريبة والجمارك، من خلال الربط الإلكتروني، أسهم في تسريع إجراءات فسح الشحنات ورفع كفاءة الخدمات المقدمة للمستفيدين، مع المحافظة على مستويات الرقابة البيئية.","وأفاد بأن مصادقة المملكة على تعديل كيغالي لبروتوكول مونتريال في سبتمبر 2025 مثّلت خطوة نوعية في خفض الغازات ذات الأثر العالي على المناخ، تعكس التزام المملكة بدعم الجهود الدولية لمواجهة التغير المناخي، مؤكداً أن التعاون الخليجي في حماية طبقة الأوزون يعزز تكامل الجهود الإقليمية ويجسد الدور الريادي للمملكة في هذا المجال."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/uwdverc','https://sabq.org/article/uwdverc','','https://sabq.org/article/uwdverc','صحيفة سبق','السعودية','2026-08-13T08:02:00.000Z','2026-08-13T11:03:00.000Z','2026-08-14T10:05:34.332Z','https://media.sabq.org/news/2026/08/ddf42779-d224-4400-a638-3e58916deb0e/w1280.webp','/api/media/acfe9d20-0914-4cba-a046-07b6edb86394','/api/media/acfe9d20-0914-4cba-a046-07b6edb86394?variant=thumbnail','المملكة ترفع نسبة التخلص من مواد مستنفدة لطبقة الأوزون إلى 69% في النصف الأول من 2026',1280,720,'valid','published','archived','valid',53,'e45fe2ae4ecbd4fe80046e5ed3bb8e736ab1d64971d33331e6fa165bf807ee78','eb6ccf9ccda7ae6275ea191bf72db726655bdfe517b1480b7fb35d829c885913','محدّث','2026-08-14T10:05:34.332Z','2026-10-07T20:52:47.394Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الطقس والمناخ","الاقتصاد والأسواق"]','["الطاقة والنفط","الطقس والمناخ","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":4},{"category":"أخبار السعودية","score":3},{"category":"الاقتصاد","score":3}]','Active','2026-10-07T20:52:47.394Z',200,79,0,'source_article_available','',NULL,NULL,'body:cf66278bd73b49683bfe0f224831db79574b05cc48e79e5d871964076f3e4fd5','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d82bf768-e23e-42f8-982d-eb47e188002a','news-d82bf768-e23e-42f8-982d-eb47e188002a','هيئة الأفلام تُعلن قواعد ترشيح الفيلم السعودي لجوائز الأوسكار الـ99','هيئه الافلام تعلن قواعد ترشيح الفيلم السعودي لجوائز الاوسكار الـ99','أعلنت هيئة الأفلام القواعد الرسمية ومعايير الأهلية وآلية الترشيح لاختيار الفيلم الذي سيمثّل المملكة العربية السعودية رسمياً في فئة أفضل فيلم روائي دولي ضمن الدورة الـ99 من جوائز الأوسكار، وذلك تماشياً مع أنظمة أكاديمية فنون وعلوم الصور المتحركة.','["ويأتي هذا الإعلان امتداداً لجهود الهيئة في دعم وصول الأفلام السعودية إلى أبرز الجوائز والمحافل السينمائية الدولية، وتعزيز حضورها التنافسي على المستوى العالمي، من خلال توفير إطار تنظيمي واضح يضمن تطبيق معايير الأهلية وإجراءات الترشيح وفق أفضل الممارسات.","وشكّلت الهيئة لجنة ترشيح مستقلة تضم نخبة من المتخصصين والخبراء في القطاع السينمائي، تتولى مراجعة الطلبات المؤهَّلة وتقييمها والتصويت لاختيار الفيلم الممثّل للمملكة، وفق إرشادات أكاديمية الأوسكار.","وتشترط القواعد جملةً من متطلبات الأهلية، أبرزها: - أن يكون الفيلم روائياً طويلاً تتجاوز مدته 40 دقيقة. - أن تتجاوز نسبة الحوارات بغير اللغة الإنجليزية 50%. - أن يُعرض تجارياً داخل المملكة لمدة لا تقل عن سبعة أيام متتالية بتذاكر مدفوعة. - ألا يكون قد أُتيح للبث أو التوزيع قبل عرضه السينمائي المؤهَّل.","ودعت الهيئة صنّاع الأفلام الراغبين في الترشح إلى مراجعة القواعد الكاملة المتاحة عبر الموقع الرسمي للأوسكار، والتأكد من استيفاء جميع المتطلبات قبل التقديم."]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wt3noey','https://sabq.org/article/wt3noey','','https://sabq.org/article/wt3noey','صحيفة سبق','السعودية','2026-08-13T08:21:00.000Z','2026-08-13T11:22:00.000Z','2026-08-14T10:05:34.471Z','https://media.sabq.org/news/2026/08/22bcd780-b8db-480d-9168-2172885ac0a8/w739.webp','/api/media/d82bf768-e23e-42f8-982d-eb47e188002a','/api/media/d82bf768-e23e-42f8-982d-eb47e188002a?variant=thumbnail','هيئة الأفلام تُعلن قواعد ترشيح الفيلم السعودي لجوائز الأوسكار الـ99',739,415,'valid','published','archived','valid',46,'b506230f3817f1f818df05a8984130e817c518594757932d88672719aea4e994','242436dee48e7e8e29879818b61e7f63186ec0672d813c832f290d61bcc2e923','محدّث','2026-08-14T10:05:34.471Z','2026-10-07T20:52:49.185Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الأفلام ت علن قواعد","الثقافة والفنون"]','["هيئة الأفلام ت علن قواعد","الثقافة والفنون"]','manual_approved','below_category_threshold','[{"category":"الصحة","score":1.5},{"category":"التقنية","score":1.5},{"category":"الثقافة","score":1.5}]','Active','2026-10-07T20:52:49.185Z',200,79,0,'source_article_available','',NULL,NULL,'body:0b62fdd14fcc96ef7f7ed00398497758603c4db3ae02f16587965c321aafa78a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9dba8997-0419-4487-835a-a122a07b194d','news-9dba8997-0419-4487-835a-a122a07b194d','الهتلان يكشف تفاصيل مركز الماجدية الرياضي الجديد لتدريبات الهلال','الهتلان يكشف تفاصيل مركز الماجديه الرياضي الجديد لتدريبات الهلال','احتفت شركة نادي الهلال بالصحافيين من خلال جولة ميدانية في مركز الماجدية الرياضي، المقر الحديث لتدريبات الفريق الأول لكرة القدم، الواقع في جامعة الأميرة نورة بالعاصمة الرياض.','["وتولّى سليمان الهتلان، كبير الإداريين وعضو مجلس إدارة شركة نادي الهلال، شرح أبرز مستجدات المرافق الحديثة للصحافيين المشاركين في الجولة.","وأكد الهتلان أن إدارة النادي زارت أغلب الأندية الرائدة حول العالم، واستقت أبرز مميزات مراكز تدريبها، ثم طبّقتها في مركز الماجدية الرياضي، ليكون بيئة احترافية متكاملة تخدم اللاعبين والجهاز الفني والإداري على حدٍّ سواء.","وكشف الهتلان أن المركز يضم 50 غرفة مخصصة للاعبين، فيما تبلغ مساحته الإجمالية 65 ألف متر مربع، استُغل منها حتى الآن 45 ألف متر مربع، في حين تبقى 20 ألف متر مربع إضافية مرصودة لمشاريع تطوير مستقبلية.","وتجدر الإشارة إلى أن الهلال يُدشّن موسمه في دوري روشن السعودي للمحترفين غداً الجمعة، حين يستقبل الفيصلي في افتتاح الجولة الأولى من المسابقة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/safvm2g','https://sabq.org/article/safvm2g','','https://sabq.org/article/safvm2g','صحيفة سبق','السعودية','2026-08-13T08:10:00.000Z','2026-08-13T11:11:00.000Z','2026-08-14T10:05:34.586Z','https://media.sabq.org/news/2026/08/f6e4fac2-ccb1-4594-9c16-1afe1c7819fb/w828.webp','/api/media/9dba8997-0419-4487-835a-a122a07b194d','/api/media/9dba8997-0419-4487-835a-a122a07b194d?variant=thumbnail','صورة من الألبوم',828,595,'valid','published','archived','valid',91,'ceefa523d957921d15b409c3a1c47c2200bd4af44095d2765719311fbf68b2a9','e05c0313768c4ee0da68a73bfd077fb086bea6703ffdbadb63500a78617ae9bd','محدّث','2026-08-14T10:05:34.586Z','2026-10-07T20:53:01.642Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة نادي الهلال شرح أبرز","مجلس إدارة شركة نادي الهلال","التعليم والتدريب","الرياضة السعودية","الرياض"]','["شركة نادي الهلال شرح أبرز","مجلس إدارة شركة نادي الهلال","التعليم والتدريب","الرياضة السعودية"]','classified','','[{"category":"التعليم","score":3},{"category":"الثقافة","score":1.5},{"category":"البيئة والمناخ","score":1.5}]','Active','2026-10-07T20:53:01.642Z',200,80,0,'source_article_available','',NULL,NULL,'body:d5ab1afa4d3121381b144f8a28af9a61073ca5b845ed146bca2b66b8811f7f44','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('88b599a4-eff1-4e1f-bb9e-5f560b9dd228','news-88b599a4-eff1-4e1f-bb9e-5f560b9dd228','مؤشر الأسهم السعودية يتراجع 20.52 نقطة ويغلق عند 10823.60','مؤشر الاسهم السعوديه يتراجع 20 52 نقطه ويغلق عند 10823 60','أغلق مؤشر الأسهم السعودية الرئيس اليوم منخفضاً بمقدار 20.52 نقطة، ليستقر عند مستوى 10823.60 نقطة، وسط تداولات بلغت قيمتها 4.4 مليارات ريال.','["وبلغت كمية الأسهم المتداولة 245 مليون سهم، وفق النشرة الاقتصادية اليومية لوكالة الأنباء السعودية، سجّلت خلالها أسهم 103 شركات ارتفاعاً في قيمتها، فيما أغلقت أسهم 154 شركة على تراجع، وتراوحت نسب الارتفاع والانخفاض بين 9.96% و4.24%.","وجاءت أسهم شركات «سينومي ريتيل» و«الآمار» و«إم آي إس» و«المسار الشامل» و«الاتحاد» الأكثر ارتفاعاً خلال الجلسة، في حين تصدّرت أسهم شركات «الوسائل الصناعية» و«المواساة» و«الأسماك» و«علم» و«أنعام القابضة» قائمة الأكثر انخفاضاً.","وعلى صعيد النشاط، احتلّت أسهم شركات «أمريكانا» و«الجزيرة» و«بترو رابغ» و«الوسائل الصناعية» و«أرامكو السعودية» المراتب الأولى في الأكثر نشاطاً بالكمية، فيما تصدّرت أسهم «الراجحي» و«الجزيرة» و«أرامكو السعودية» و«بترو رابغ» و«علم» قائمة الأكثر نشاطاً بالقيمة.","في المقابل، أغلق مؤشر السوق الموازية «نمو» مرتفعاً بمقدار 40.69 نقطة، ليقفل عند مستوى 21821.73 نقطة، بتداولات بلغت قيمتها 13 مليون ريال، وكمية أسهم متداولة بلغت 1.7 مليون سهم."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/kcc2ra3','https://sabq.org/article/kcc2ra3','','https://sabq.org/article/kcc2ra3','صحيفة سبق','السعودية','2026-08-13T07:52:00.000Z','2026-08-13T10:54:00.000Z','2026-08-14T10:05:35.630Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/6246fb81-e49d-4a4b-d7ed-3f9b1b3bfc00/public','/api/media/88b599a4-eff1-4e1f-bb9e-5f560b9dd228','/api/media/88b599a4-eff1-4e1f-bb9e-5f560b9dd228?variant=thumbnail','مؤشر الأسهم السعودية يتراجع 20.52 نقطة ويغلق عند 10823.60',2400,1339,'valid','published','archived','valid',56,'28ad86c9a2b7ad448add414300c9a4bd097c23a56ea751b35b3c7bf9d78c1064','dddc072a926da2e0631d0f0f2c0735a484f47d0f6d3a7f38aeaa951bd080a7c4','محدّث','2026-08-14T10:05:35.630Z','2026-10-07T20:58:18.165Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة على تراجع وتراوحت نسب","الاقتصاد والأسواق"]','["شركة على تراجع وتراوحت نسب","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"التقنية","score":2},{"category":"الطاقة والصناعة","score":2}]','Temporarily Unreachable','2026-10-07T20:58:18.165Z',NULL,82,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('302c2ab8-92fa-4fdf-81e2-515c43abfc2b','news-302c2ab8-92fa-4fdf-81e2-515c43abfc2b','وزارة التجارة تطلق «تخفيضات 2026» بأكثر من مليون منتج مخفّض حتى أكتوبر','وزاره التجاره تطلق تخفيضات 2026 باكثر من مليون منتج مخفض حتي اكتوبر','أعلنت وزارة التجارة عن انطلاق «تخفيضات 2026م» في بداية شهر أغسطس الجاري، وتشمل أكثر من مليون منتج مخفّض لدى المنشآت التجارية والمتاجر الإلكترونية على حدٍّ سواء، وتستمر حتى 30 أكتوبر 2026م.','["وتواصل الوزارة أعمال الرقابة الميدانية على المنشآت التجارية والمتاجر الإلكترونية، للتحقق من التزامها بضوابط التخفيضات واشتراطاتها المعتمدة.","وأوضحت الوزارة أن التقديم على رخص التخفيضات متاح إلكترونياً عبر منصة sales.mc.gov.sa، داعيةً المنشآت والمتاجر إلى الاستفادة من «المدة الاستثنائية للتخفيضات»، التي تتيح إجراء التخفيضات لمدة ثلاثة أشهر دون خصم أيام من الرصيد السنوي المخصص لتخفيضات المنشأة التجارية."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/u3jbu5s','https://sabq.org/article/u3jbu5s','','https://sabq.org/article/u3jbu5s','صحيفة سبق','السعودية','2026-08-13T07:01:00.000Z','2026-08-13T10:03:00.000Z','2026-08-14T10:05:35.746Z','https://media.sabq.org/news/2026/08/4421573a-d4e1-4215-af32-2e2135fcfe95/w674.webp','/api/media/302c2ab8-92fa-4fdf-81e2-515c43abfc2b','/api/media/302c2ab8-92fa-4fdf-81e2-515c43abfc2b?variant=thumbnail','وزارة التجارة تطلق «تخفيضات 2026» بأكثر من مليون منتج مخفّض حتى أكتوبر',674,377,'valid','published','archived','valid',47,'7a4cf53c934fa15f965f302672cb0390e81c47f347af2030ca8128c9bf6dd760','fd41837020228e9fa1ccdc2d020176ac8b191d7fba3d6cd2aa92ab0cb179d638','محدّث','2026-08-14T10:05:35.746Z','2026-10-07T20:52:51.605Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة التجارة تطلق تخفيضات","الاقتصاد والأسواق"]','["وزارة التجارة تطلق تخفيضات","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:52:51.605Z',200,81,0,'source_article_available','',NULL,NULL,'body:78ebfd092eb84bf97b3123355aa50a36d118c9fa419bf0bee4c3e06e9d8bb442','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('364ee5bd-b3f4-48c1-bf15-7545f621a5d3','news-364ee5bd-b3f4-48c1-bf15-7545f621a5d3','استثمارات الخليج في الطاقة والتقنية والصناعة ترتفع إلى 62.45 مليار دولار بحلول 2030','استثمارات الخليج في الطاقه والتقنيه والصناعه ترتفع الي 62 45 مليار دولار بحلول 2030','كشفت بيانات القمة العالمية للاستثمار 2026، المقررة في باريس يومي 1 و2 سبتمبر، عن توقعات بارتفاع إجمالي الاستثمارات في قطاعات الطاقة المتجددة والهيدروجين والصناعات المتقدمة والبنية الرقمية بدول مجلس التعاون الخليجي من 32.87 مليار دولار عام 2023 إلى 62.45 مليار دولار بحلول 2030، بزيادة قدرها 29.58 مليار دولار ونمو يقارب 90%.','["وتتصدر الطاقة المتجددة والهيدروجين قائمة القطاعات الأعلى نمواً، إذ تشير التوقعات إلى ارتفاع استثماراتها من 10.37 مليارات دولار عام 2023 إلى 22.77 مليار دولار بحلول 2030، بزيادة تبلغ 12.4 مليار دولار ونمو يقارب 120%، مدفوعاً بتوسع دول الخليج في مشروعات الطاقة النظيفة وتطوير مشروعات الهيدروجين وارتفاع الطلب على حلول خفض الانبعاثات وتحسين كفاءة الطاقة.","وعلى صعيد البنية الرقمية، يُتوقع ارتفاع الاستثمارات من 9.45 مليارات دولار عام 2023 إلى 18.36 مليار دولار بحلول 2030، بزيادة قدرها 8.91 مليارات دولار ونمو يتجاوز 94%، في ظل التوسع المتسارع في مراكز البيانات والخدمات السحابية وشبكات الاتصالات، والنمو المتصاعد في تطبيقات الذكاء الاصطناعي والتحول الرقمي لدى القطاعات الحكومية والمالية والصناعية.","أما الصناعات المتقدمة، فتشير التقديرات إلى ارتفاع استثماراتها من 13.05 مليار دولار عام 2023 إلى 21.32 مليار دولار بحلول 2030، بزيادة قدرها 8.27 مليارات دولار ونمو يتجاوز 63%، مدفوعاً بتوسع دول الخليج في توطين الصناعات ذات القيمة المضافة وتطوير سلاسل الإمداد وزيادة الاعتماد على الأتمتة والتقنيات الصناعية الحديثة.","وتعكس هذه المؤشرات مجتمعةً تنامي الترابط بين القطاعات الثلاثة؛ إذ يدعم توسع البنية الرقمية التحول الصناعي، فيما توفر الطاقة النظيفة والهيدروجين مصادر أكثر استدامة للمشروعات الصناعية، مما يفتح مسارات استثمارية جديدة تجمع بين التقنية والتصنيع والاستدامة."]','الطاقة والصناعة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/n8ij4ea','https://sabq.org/article/n8ij4ea','','https://sabq.org/article/n8ij4ea','مسلّم الهواملة','السعودية','2026-08-13T06:59:00.000Z','2026-08-13T09:59:00.000Z','2026-08-14T10:05:36.035Z','https://media.sabq.org/news/2026/08/e338145f-e058-4fe5-9cc7-513e186ba926/w1600.webp','/api/media/364ee5bd-b3f4-48c1-bf15-7545f621a5d3','/api/media/364ee5bd-b3f4-48c1-bf15-7545f621a5d3?variant=thumbnail','استثمارات الخليج في الطاقة والتقنية والصناعة ترتفع إلى 62.45 مليار دولار بحلول 2030',1600,900,'valid','published','archived','valid',99,'a9901b80ef5f18925550cbab212c19059092720cdfc8053c527f11a9c13e4cd2','919d0dac9544d9e9237933572394b1658d53be89f65f442c2823efd49ce9317d','محدّث','2026-08-14T10:05:36.035Z','2026-10-07T20:53:01.661Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["الطاقة والنفط","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"الاقتصاد","score":10.5},{"category":"التقنية","score":8},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T20:53:01.661Z',200,82,0,'source_article_available','',NULL,NULL,'body:2016998ebbaf8bd3c720725432ac76d9fb8b5ff9583c6b15da9ebfe6fb87eead','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('703c7e24-75f5-4b8c-8437-f6ab1b9630cf','news-703c7e24-75f5-4b8c-8437-f6ab1b9630cf','مسؤول بـ«المواصفات السعودية»: مشاركتنا في الأولمبياد الدولي استثمار علمي في أبنائنا','مسؤول بـ المواصفات السعوديه مشاركتنا في الاولمبياد الدولي استثمار علمي في ابنائنا','ويشارك المنتخب السعودي للمواصفات في منافسات النسخة الحادية والعشرين من الأولمبياد الدولي للمواصفات 2026، التي تقام خلال الفترة من 12 إلى 14 أغسطس 2026 في جمهورية كوريا الجنوبية، بمشاركة 35 فريقًا يمثلون 11 دولة من مختلف أنحاء العالم','["قال مدير مركز البحوث والدراسات بالمواصفات السعودية د. صالح العتيبي، إن مشاركتنا في الأولمبياد الدولي استثمار علمي في أبنائنا للإسهام في منظومة المواصفات.","وأضاف خلال مداخلة مع قناة «الإخبارية» نقدم المعرفة للطلاب بمشاركتهم في مشروع حقيقي، لافتا إلى أن المركز يؤسس لجيل يمتلك المعرفة والمهارة بما يدعم تنافسية المملكة واقتصادها."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/aptpjsl4r','https://ajel.sa/local/aptpjsl4r','https://ajel.sa/local/aptpjsl4r','https://ajel.sa/local/aptpjsl4r','فريق التحرير','السعودية','2026-08-14T02:10:00.000Z','Wed, 07 Oct 2026 20:52:37 GMT','2026-08-14T12:07:39.899Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%A7%D9%88%D9%84%D9%85%D8%A8%D9%8A%D8%A7%D8%AF-Muvs3wfF.jpg','/api/media/703c7e24-75f5-4b8c-8437-f6ab1b9630cf','/api/media/703c7e24-75f5-4b8c-8437-f6ab1b9630cf?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',95,'fadf1d70c8bd15e40a3dfd39642682a46969bcea2c7d743cacdcb5d18f924226','12161c07023fb35a042b2665daa3e8b7ff95bc46bab953790b7b767858fbc0aa',NULL,'2026-08-14T12:07:39.899Z','2026-10-07T20:52:39.475Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الاقتصاد والأسواق"]','["التعليم والتدريب","الاقتصاد والأسواق"]','classified','','[{"category":"أخبار السعودية","score":4.5},{"category":"التعليم","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:52:39.475Z',200,80,0,'source_content_changed','',NULL,NULL,'body:cc2ea570466c26d7f4c8f82e6efe500f3d7e78edde49716e534251d80cbf8b34','Wed, 07 Oct 2026 20:52:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1c6cc77d-d4a7-4030-9108-8327fd4cc068','news-1c6cc77d-d4a7-4030-9108-8327fd4cc068','نادي سباقات الخيل يطلق موسم الرياض 2026/2027 بـ 69 شوطاً وجوائز 197.8 مليون ريال','نادي سباقات الخيل يطلق موسم الرياض 2026 2027 بـ 69 شوطا وجوائز 197 8 مليون ريال','أعلن نادي سباقات الخيل برنامج موسم سباقات الرياض 2026/2027، الذي تنطلق منافساته يوم الجمعة 16 أكتوبر المقبل على ميدان الملك عبدالعزيز للفروسية، وتستمر حتى 17 أبريل 2027، متضمناً حزمة من التطويرات النوعية والمستجدات البارزة التي تعكس تطور البرنامج السباقي والدعم المستمر للإنتاج المحلي، وتسهم في ترسيخ مكانة الرياض على خارطة سباقات الخيل العالمية.','["ويشتمل البرنامج على 69 شوطاً من الكؤوس الكبرى بإجمالي جوائز مالية تبلغ 197.8 مليون ريال، ضمن منافسات تمتد على مدى ستة أشهر.","وبهذه المناسبة، رفع الأمير بندر بن خالد الفيصل، المستشار بالديوان الملكي رئيس مجلس إدارة هيئة الفروسية ورئيس مجلس إدارة نادي سباقات الخيل، الشكرَ لخادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، ولصاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء، على ما يحظى به قطاع الفروسية وسباقات الخيل من دعم مستمر.","وقال الأمير بندر: «أسهم هذا الدعم في ترسيخ مكانة المملكة على خارطة سباقات الخيل العالمية، ويأتي موسم الرياض 2026/2027 امتداداً لهذه المسيرة، ببرنامج يحمل مبادرات وتوجهات نوعية تعكس طموحنا في تقديم موسم أكثر قوة وتنافسية، ومواصلة الارتقاء بمستوى السباقات بما يواكب المكانة التي وصلت إليها المملكة عالمياً».","رفع الجوائز المالية لعدد من الكؤوس الكبرى شملت أبرز مستجدات البرنامج رفع الجوائز المالية لعدد من الكؤوس الكبرى؛ إذ ارتفعت جائزة كأس خادم الحرمين الشريفين، الشوط المفتوح الفئة الثالثة (G3) والمؤهل لكأس السعودية، من 1.5 مليون ريال إلى مليوني ريال، كما ارتفعت جائزة كأس ولي العهد، الشوط المفتوح المصنف (Listed)، من مليون ريال إلى 1.5 مليون ريال."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/oshhimv','https://sabq.org/article/oshhimv','','https://sabq.org/article/oshhimv','صحيفة سبق','السعودية','2026-08-13T10:43:00.000Z','2026-08-13T15:12:00.000Z','2026-08-14T12:12:28.733Z','https://media.sabq.org/news/2026/08/c8033a4e-4170-41a9-ad34-94179615ddfd/w1152.webp','/api/media/1c6cc77d-d4a7-4030-9108-8327fd4cc068','/api/media/1c6cc77d-d4a7-4030-9108-8327fd4cc068?variant=thumbnail','نادي سباقات الخيل يطلق موسم الرياض 2026/2027 بـ 69 شوطاً وجوائز 197.8 مليون ريال',1152,2048,'valid','published','archived','valid',99,'f3588cc1b4eff5c10352dc4728fa770297eb6db4f5ec5272db2ef1e2d56935d3','af6c7ca3c7d465ed463194c82c4c3f20b85a197b82ef4468bf29d03565f82205','محدّث','2026-08-14T12:12:28.733Z','2026-10-07T20:52:58.153Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","رئيس مجلس إدارة هيئة الفروسية","هيئة الفروسية ورئيس مجلس إدارة","مجلس إدارة هيئة الفروسية ورئيس","خادم الحرمين الشريفين الشوط المفتوح","الرياضة السعودية","الاقتصاد والأسواق","الرياض"]','["ولي العهد رئيس مجلس الوزراء","رئيس مجلس إدارة هيئة الفروسية","هيئة الفروسية ورئيس مجلس إدارة","مجلس إدارة هيئة الفروسية ورئيس","خادم الحرمين الشريفين الشوط المفتوح","الرياضة السعودية"]','classified','','[{"category":"الاقتصاد","score":4.5},{"category":"الرياضة","score":3},{"category":"الثقافة","score":1.5}]','Active','2026-10-07T20:52:58.153Z',200,80,0,'source_article_available','',NULL,NULL,'body:41e57ab5fbf2a0db2b5f72c2f893f7d53fd0b00316bf7ae715d6d863fdad2e09','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c3a7d773-83e1-4cae-95fe-6425f59f8a59','news-c3a7d773-83e1-4cae-95fe-6425f59f8a59','إنزاغي: الهلال جاهز لافتتاح دوري روشن بأسلوب هجومي أمام الفيصلي','انزاغي الهلال جاهز لافتتاح دوري روشن باسلوب هجومي امام الفيصلي','أكد مدرب الفريق الكروي الأول لنادي الهلال سيموني إنزاغي أن فريقه بات جاهزاً لافتتاح موسمه في دوري روشن السعودي للمحترفين، إذ يواجه الفيصلي في الجولة الأولى من المسابقة.','["وقال إنزاغي في المؤتمر الصحفي قبل المباراة: «الفيصلي فريق كبير، وسيبذل لاعبونا قصارى جهدهم لتحقيق الفوز، لا سيما أن هذه بداية الموسم»، مشيراً إلى أن أسلوب الفريق في الموسم الجديد سيكون هجومياً بامتياز.","وأوضح المدرب الإيطالي أن تأخر بعض اللاعبين في الانضمام إلى معسكر الإعداد أمر طبيعي في ظل مشاركتهم في كأس العالم، مؤكداً أن ذلك لن يؤثر على جاهزية الفريق.","وفيما يخص وضع المدافع علي البليهي الذي لم يتدرب مع الفريق، أشار إنزاغي إلى وجود لاعبين شباب يرغب في تجربتهم والاعتماد عليهم خلال الموسم.","وكشف إنزاغي أن المدافع السنغالي كاليدو كوليبالي متواجد مع الفريق وفي أتم الجاهزية البدنية للمشاركة في المباريات."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/5ssy4re','https://sabq.org/article/5ssy4re','','https://sabq.org/article/5ssy4re','صحيفة سبق','السعودية','2026-08-13T10:20:00.000Z','2026-08-13T13:20:00.000Z','2026-08-14T12:12:29.746Z','https://media.sabq.org/news/2026/08/ee8d5f16-3078-49ff-a87f-b29673988077/w1536.webp','/api/media/c3a7d773-83e1-4cae-95fe-6425f59f8a59','/api/media/c3a7d773-83e1-4cae-95fe-6425f59f8a59?variant=thumbnail','إنزاغي: الهلال جاهز لافتتاح دوري روشن بأسلوب هجومي أمام الفيصلي',1536,2048,'valid','published','archived','valid',99,'182667ba1838ff58a4a5b9cc51cdc09dcdf462b4301c9f1da0be366ebad8d3af','a4647451969f0eafd09cbd8daf3863e006490f2586c0bbb47c18aa82c632dd90','محدّث','2026-08-14T12:12:29.746Z','2026-10-07T20:53:01.017Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"الصحة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:53:01.017Z',200,79,0,'source_article_available','',NULL,NULL,'body:ccc7d2bd0706aba90454829862f563564c92def436641a578cca7dda35a188a7','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1a247221-331c-4ceb-9f4b-7f42e4fde5d5','news-1a247221-331c-4ceb-9f4b-7f42e4fde5d5','ثلاثة مسارات برية تقودك إلى العُلا هذا الصيف عبر أجمل مناطق المملكة','ثلاثه مسارات بريه تقودك الي العلا هذا الصيف عبر اجمل مناطق المملكه','تتيح العُلا لزوارها خلال فصل الصيف فرصة اكتشاف تنوع المملكة الطبيعي والثقافي عبر ثلاثة مسارات برية تنطلق من جدة والمدينة المنورة وتبوك، تمر بسواحل البحر الأحمر والتضاريس البركانية والمشاهد الصحراوية، لتصبح رحلة الوصول تجربة سياحية بحد ذاتها، بما تزخر به من محطات ومعالم متنوعة على امتداد الطريق.','["وتسهم شبكة الطرق السريعة الرابطة بين العُلا ومدن الانطلاق، إلى جانب توفر خدمات استئجار السيارات، في منح الزوار مرونة أكبر لاختيار المسار المناسب والتوقف عند الوجهات الواقعة على الطريق.","المسار الأول: جدة - العُلا عبر الساحل (700 كيلومتر) يبدأ المسار الأول من جدة بمحاذاة ساحل البحر الأحمر شمالاً نحو ينبع، المدينة الساحلية المعروفة بكورنيشها وشواطئها وأنشطتها البحرية وفي مقدمتها الغوص، ثم يواصل شمالاً نحو وجهة «البحر الأحمر» للاستمتاع بالشواطئ البكر والمياه الصافية والتجارب البحرية الفاخرة، قبل الوصول إلى مدينة الوجه التي تحتفظ ببلدتها التاريخية وتراثها البحري العريق.","ومن الوجه، تتجه الرحلة شرقاً نحو العُلا، حيث تتبدل ملامح الطريق تدريجياً، فتفسح سواحل البحر الأحمر المجال أمام التكوينات الرملية الشاهقة والأودية الصحراوية، وصولاً إلى الواحة الخضراء.","وتبلغ المسافة المباشرة بين جدة والعُلا نحو 700 كيلومتر، وتستغرق الرحلة ما بين سبع وثماني ساعات، فيما تمتد المرحلة الأخيرة من الوجه إلى العُلا لمسافة تقارب 245 كيلومتراً وتستغرق نحو ثلاث إلى أربع ساعات."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/izdo8vr','https://sabq.org/article/izdo8vr','','https://sabq.org/article/izdo8vr','صحيفة سبق','السعودية','2026-08-13T10:28:00.000Z','2026-08-13T13:28:00.000Z','2026-08-14T12:12:30.094Z','https://media.sabq.org/news/2026/08/bb3fe8a3-0496-4a7f-a92a-d08f5e7ef307/w1600.webp','/api/media/1a247221-331c-4ceb-9f4b-7f42e4fde5d5','/api/media/1a247221-331c-4ceb-9f4b-7f42e4fde5d5?variant=thumbnail','صورة من الألبوم',1600,1067,'valid','published','archived','valid',44,'13256a5163b0a7728d36d9e956dcafb28aca3d2ae11bd3d525481d6e8a89a066','3c57d11665e7c36a44272ea2c3555ac94199f294568f59b652ab688d8ece3f39','محدّث','2026-08-14T12:12:30.094Z','2026-10-07T20:52:49.211Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["جدة"]','[]','manual_approved','below_category_threshold','[{"category":"المناطق","score":3},{"category":"الصحة","score":1.5},{"category":"السيارات","score":1.5}]','Active','2026-10-07T20:52:49.211Z',200,76,0,'source_article_available','',NULL,NULL,'body:8be58b9d3d1b8178ac3ed97f61a95987ef122de01c76fdb8f879d6629ec65037','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9197a78e-2178-4965-942d-59fc3268e887','news-9197a78e-2178-4965-942d-59fc3268e887','سوق موسم التمور بالمذنب يستقطب الزوار بأكثر من 50 صنفاً','سوق موسم التمور بالمذنب يستقطب الزوار باكثر من 50 صنفا','يشهد سوق موسم التمور بمحافظة المذنب منذ انطلاقته حركةً تسويقية نشطة وإقبالاً كبيراً من الأهالي والزوار والتجار، مع تنوع لافت في الأصناف المعروضة التي تجاوزت 50 صنفاً من إنتاج مزارع المحافظة.','["ويُقام السوق بإشراف إمارة منطقة القصيم ممثلةً بمحافظة المذنب، وبتنظيم من المركز الوطني للنخيل والتمور ممثلاً بمنصة الأسواق الموسمية، ومكتب وزارة البيئة والمياه والزراعة بالمحافظة، وبرعاية رسمية من الغرفة التجارية، وبمشاركة وزارة التجارة وبلدية محافظة المذنب.","وتُسهم منصة الأسواق الموسمية في دعم قطاع النخيل والتمور عبر توفير الخدمات الزراعية والتسويقية، والاستفادة من التقنيات الحديثة بما يعزز كفاءة التسويق ويدعم المزارعين والمنتجين، ويزيد من استهلاك التمور السعودية.","ويهدف موسم التمور بالمذنب من خلال المنصة إلى تنظيم عمليات البيع والتسويق، وتمكين المزارعين من عرض إنتاجهم وتسويقه، ورفع جودة الخدمات المقدمة لهم.","ويعكس تنوع الأصناف المعروضة المكانةَ الزراعية المتميزة لمحافظة المذنب، وأهمية هذا الموسم في تنشيط الحركة الاقتصادية وتعزيز فرص الاستثمار في قطاع النخيل والتمور بمنطقة القصيم."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/nq1t4d5','https://sabq.org/article/nq1t4d5','','https://sabq.org/article/nq1t4d5','صحيفة سبق','السعودية','2026-08-13T09:54:00.000Z','2026-08-13T12:55:00.000Z','2026-08-14T12:12:31.121Z','https://media.sabq.org/news/2026/08/efa34284-cbe4-4ed8-a3b7-447e1ebeea21/w1600.webp','/api/media/9197a78e-2178-4965-942d-59fc3268e887','/api/media/9197a78e-2178-4965-942d-59fc3268e887?variant=thumbnail','صورة من الألبوم',1600,1066,'valid','published','archived','valid',90,'9a3898b3709e56e8bd9443ddea0fb03bd2fe7e372a4926309606b94b2caf5a84','460545f9ea7100199a3643447bf54c2a5698bad5e35694a7716433a4430684b7','محدّث','2026-08-14T12:12:31.121Z','2026-10-07T20:53:01.054Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البيئة والمياه والزراعة بالمحافظة","الثقافة والفنون","الاقتصاد والأسواق","القصيم"]','["وزارة البيئة والمياه والزراعة بالمحافظة","الثقافة والفنون","الاقتصاد والأسواق"]','classified','','[{"category":"الاقتصاد","score":7},{"category":"أخبار السعودية","score":1.5},{"category":"البيئة والمناخ","score":1.5}]','Active','2026-10-07T20:53:01.054Z',200,76,0,'source_article_available','',NULL,NULL,'body:3bafd1d3caf88c1bc129572e697b01e59239f9f79c0f948bc162e09f8596e3bd','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('343326f4-81a2-452e-9f6b-0b162c5fa9a1','news-343326f4-81a2-452e-9f6b-0b162c5fa9a1','وزير الدفاع الأمير خالد بن سلمان يستقبل مدير مكتب القائد العام للقوات المسلحة العراقية','وزير الدفاع الامير خالد بن سلمان يستقبل مدير مكتب القائد العام للقوات المسلحه العراقيه','استقبل صاحب السمو الملكي الأمير خالد بن سلمان بن عبدالعزيز وزير الدفاع، في مكتبه بالرياض، الفريق الأول الركن عبدالأمير الشمري مدير مكتب القائد العام للقوات المسلحة العراقية.','["وجرى خلال اللقاء استعراض العلاقات السعودية العراقية في المجال العسكري والدفاعي، وبحث التطورات الإقليمية، والتأكيد على أهمية مواصلة التنسيق والتعاون بين البلدين بما يخدم مصالحهما المشتركة ويحقق أمن المنطقة واستقرارها.","وحضر اللقاء من الجانب السعودي: رئيس الاستخبارات العامة خالد بن علي الحميدان، ورئيس هيئة الأركان العامة الفريق الأول الركن فياض بن حامد الرويلي، وقائد القوات المشتركة الفريق الركن فهد بن حمد السلمان، ومستشار سمو وزير الدفاع لشؤون الاستخبارات هشام بن عبدالعزيز بن سيف.","فيما حضر اللقاء من الجانب العراقي: رئيس جهاز المخابرات حميد الشطري، ورئيس جهاز مكافحة الإرهاب الفريق الركن زيد حوشي الموسوي، وقائد الدفاع الجوي الفريق الركن مهند الأسدي."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/8103cqo','https://sabq.org/article/8103cqo','','https://sabq.org/article/8103cqo','صحيفة سبق','السعودية','2026-08-13T10:16:00.000Z','2026-08-13T13:25:00.000Z','2026-08-14T12:12:31.580Z','https://media.sabq.org/news/2026/08/466e1aff-6634-43c7-8ebd-a7d87ce306e4/w1200.webp','/api/media/343326f4-81a2-452e-9f6b-0b162c5fa9a1','/api/media/343326f4-81a2-452e-9f6b-0b162c5fa9a1?variant=thumbnail','وزير الدفاع الأمير خالد بن سلمان يستقبل مدير مكتب القائد العام للقوات المسلحة العراقية',1200,765,'valid','published','archived','valid',40,'3f5a639a21d21498a2792e8513817fd79ed2f3655b47bbd23e2d625268faf713','72edfe0c2dcbcd8813ef7e54bcc710735ed6954b7ada2596fe81f57e788b0001','محدّث','2026-08-14T12:12:31.580Z','2026-10-07T20:52:46.764Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الدفاع الأمير خالد بن","رئيس الاستخبارات العامة خالد بن","هيئة الأركان العامة الفريق الأول","العراق"]','["وزير الدفاع الأمير خالد بن","رئيس الاستخبارات العامة خالد بن","هيئة الأركان العامة الفريق الأول"]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:52:46.764Z',200,77,0,'source_article_available','',NULL,NULL,'body:017a7b2619d83cc7d4964d06200e64de6a25c53f5b9834a92cc24cc74a78affa','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a70a2d04-30f6-4ccc-ae90-299631f0d54c','news-a70a2d04-30f6-4ccc-ae90-299631f0d54c','نائب وزير الخارجية الخريجي يستقبل وزيرة خارجية كوت ديفوار في الرياض','نائب وزير الخارجيه الخريجي يستقبل وزيره خارجيه كوت ديفوار في الرياض','استقبل نائب وزير الخارجية المهندس وليد بن عبدالكريم الخريجي، في مقر الوزارة بالرياض، وزيرة الدولة وزيرة الشؤون الخارجية والتعاون الدولي بجمهورية كوت ديفوار نيالي كابا.','["وجرى خلال الاستقبال استعراض العلاقات الثنائية بين البلدين وسبل تعزيزها بما يخدم المصالح المشتركة، إضافة إلى مناقشة الموضوعات ذات الاهتمام المشترك.","وحضر الاستقبال سفير جمهورية كوت ديفوار لدى المملكة العربية السعودية كوليبالي دريسا."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/c4wg0rc','https://sabq.org/article/c4wg0rc','','https://sabq.org/article/c4wg0rc','صحيفة سبق','السعودية','2026-08-13T09:33:00.000Z','2026-08-13T12:34:00.000Z','2026-08-14T12:12:31.611Z','https://media.sabq.org/news/2026/08/53b5f1da-78a6-44e0-aa1d-bf5048b823dd/w1280.webp','/api/media/a70a2d04-30f6-4ccc-ae90-299631f0d54c','/api/media/a70a2d04-30f6-4ccc-ae90-299631f0d54c?variant=thumbnail','نائب وزير الخارجية الخريجي يستقبل وزيرة خارجية كوت ديفوار في الرياض',1280,854,'valid','published','archived','valid',44,'ae762e98e2ad4f3f7b9900d0921625ec40b55bfffee145265827b2aed904bf7b','c0690f089128ba9eb08fa0ef053a5a33dfd5757a17d7c6c7b24dec2187fe7846','محدّث','2026-08-14T12:12:31.611Z','2026-10-07T20:52:47.364Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الخارجية الخريجي يستقبل وزيرة","الرياض"]','["وزير الخارجية الخريجي يستقبل وزيرة"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":3},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T20:52:47.364Z',200,78,0,'source_article_available','',NULL,NULL,'body:1a641e1fef55fe301ceadb9eddc9eea86fef726d0811b361911074b8d875b533','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c8bc4763-7234-4143-b362-c716bc4ce2af','news-c8bc4763-7234-4143-b362-c716bc4ce2af','بوستيكوجلو: تركيزنا على العمل والدوري ينطلق السبت','بوستيكوجلو تركيزنا علي العمل والدوري ينطلق السبت','أكد المدير الفني لفريق النصر الأسترالي إنج بوستيكوجلو جاهزية «العالمي» لانطلاقة منافسات الدوري، مشدداً على أن تركيزه ينصب على العمل والإعداد داخل الملعب، بعيداً عن الوعود والتصريحات الإعلامية.','["وقال بوستيكوجلو خلال المؤتمر الصحفي الذي عُقد قُبيل انطلاق الموسم: «مهما كانت التحديات، يبقى تركيزنا منصباً على العمل.","الدوري ينطلق يوم السبت، ولا يهمنا الحديث بقدر ما يهمنا الإعداد والاستعداد للموسم».","وعن تحركات النصر في سوق الانتقالات الصيفية، ومدى الاكتفاء بالتعاقد مع اللاعب كوستا، أوضح المدرب الأسترالي أنه يبحث باستمرار عن أفضل العناصر القادرة على خدمة الفريق، مؤكداً رضاه التام عن الصفقة، وقال: «أنا أبحث دائماً عن أفضل اللاعبين، وأنا راضٍ تماماً عن صفقة كوستا».","وفيما يخص فلسفته الفنية وأسلوب اللعب الذي يسعى إلى تطبيقه مع النصر، أكد بوستيكوجلو أن منهجه يرتكز على كرة القدم الهجومية وتسجيل الأهداف، قائلاً: «أحب كرة القدم التي تبحث عن الانتصار وتسجيل الأهداف»."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/CNzdJS9','https://sabq.org/article/CNzdJS9','','https://sabq.org/article/CNzdJS9','جمال المرشدي','السعودية','2026-08-13T09:22:00.000Z','2026-08-13T12:23:00.000Z','2026-08-14T12:12:32.788Z','https://media.sabq.org/news/2026/08/6e4daf5c-c9bf-4d0e-a058-b337d8b9fd52/w970.webp','/api/media/c8bc4763-7234-4143-b362-c716bc4ce2af','/api/media/c8bc4763-7234-4143-b362-c716bc4ce2af?variant=thumbnail','بوستيكوجلو: تركيزنا على العمل والدوري ينطلق السبت',970,904,'valid','published','archived','valid',99,'0a962d9676c100daba51b7eccc1f8db51bc650122c5f5cb1050712f403e2a2b3','8ea1042d91a90e9e57a20e195089d9150119ee87f20898c694e5e4647cc8fc5e','محدّث','2026-08-14T12:12:32.788Z','2026-10-07T20:57:33.740Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"الاقتصاد","score":1.5},{"category":"الصحة","score":1.5},{"category":"التقنية","score":1.5}]','Temporarily Unreachable','2026-10-07T20:57:33.740Z',NULL,76,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f5615c73-bac8-433b-82fc-54f41f76a5ea','news-f5615c73-bac8-433b-82fc-54f41f76a5ea','القبض على مواطنين بمنطقة الجوف لترويجها الحشيش المخدر','القبض علي مواطنين بمنطقه الجوف لترويجها الحشيش المخدر','ألقت المديرية العامة لمكافحة المخدرات القبض على مواطنين، ب منطقة الجوف ، لترويجهما 2 كيلوجرام من مادة الحشيش المخدر. وتهيب الجهات الأمنية بالإبلاغ عن كل ما يتوافر من معلومات لدى المواطنين والمقيمين عن أي نشاطات ذات صلة بتهريب أو ترويج المخدرات، وذلك من خلال الاتصال بالأرقام (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض و الشرقية و(999) و(994) في…','["ألقت المديرية العامة لمكافحة المخدرات القبض على مواطنين، ب منطقة الجوف ، لترويجهما 2 كيلوجرام من مادة الحشيش المخدر.","وقالت \"مكافحة المخدرات\"، عبر حسابها على منصة \"إكس\"، إنه جرى إيقاف المخالفين، واتخاذ الإجراءات النظامية بحقهما. وإحالتهما إلى النيابة العامة.","وتهيب الجهات الأمنية بالإبلاغ عن كل ما يتوافر من معلومات لدى المواطنين والمقيمين عن أي نشاطات ذات صلة بتهريب أو ترويج المخدرات، وذلك من خلال الاتصال بالأرقام (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض و الشرقية و(999) و(994) في بقية مناطق المملكة ، ورقم بلاغات المديرية العامة لمكافحة المخدرات (995)، وعبر البريد الإلكتروني: (Email: [email&#160;protected] )، وستعالج جميع البلاغات بسرية تامة دون أدنى مسؤولية…"]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/zgvabnwck','https://ajel.sa/local/zgvabnwck','https://ajel.sa/local/zgvabnwck','https://ajel.sa/local/zgvabnwck','فريق التحرير','السعودية','2026-08-14T05:16:00.000Z','Wed, 07 Oct 2026 20:52:41 GMT','2026-08-14T14:13:58.143Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-PpoBU2L_.jpg','/api/media/f5615c73-bac8-433b-82fc-54f41f76a5ea','/api/media/f5615c73-bac8-433b-82fc-54f41f76a5ea?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',88,'1475393e3420d13fccbd71d6d45284bbc10ba12a6ed23eeee20b07734d6d9bcb','f10f9dd36e72a12ac91ab82b564f643fb02d585a05c0ef00ecdbe90f8aa56472',NULL,'2026-08-14T14:13:58.143Z','2026-10-07T20:52:43.434Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","الجوف","الرياض","المدينة المنورة"]','["المدينة المنورة"]','classified','','[{"category":"المجتمع","score":3},{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5}]','Updated','2026-10-07T20:52:43.434Z',200,82,0,'source_content_changed','',NULL,NULL,'body:a48d7c95c13c29d871f6f6e811c84ed3a32c76a1381c7889b4bbd50e081dd26f','Wed, 07 Oct 2026 20:52:41 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ebae71c2-f9f9-4bc4-a473-ff34006ac743','news-ebae71c2-f9f9-4bc4-a473-ff34006ac743','ثقافي / ما الصخرة "المتوأمة" التي تجمع فرادة التكوين وثراء الإرث التاريخي؟','ثقافي ما الصخره المتوامه التي تجمع فراده التكوين وثراء الارث التاريخي','وتبرز شهرة الصخرة "المتوأمة" في كونها من أبرز الشواهد الجيولوجية الطبيعية في المملكة، وأنها تجمع فرادة التكوين الصخري وثراء الإرث التاريخي بنقوشها؛ لتروي مشهدًا تشكّل عبر السنين من التحولات الطبيعية.','["تبوك 01 ربيع الأول 1448 هـ الموافق 14 أغسطس 2026 م واس يقف تكوين صخري في جنوب غرب محافظة تيماء بمنطقة تبوك يُعرف باسم صخرة أو حصاة \"النصلة\"، وهي عبارة عن صخرتين متجاورتين يفصلهما عن بعضهما مسافة تبدو على شكل خط مستقيم، وسُمّيت \"النصلة\" لأنها نصلت أو انفردت عن الجبال التي تقرب منها، وتحتوي واجهتها على مجموعة من النقوش والرسوم الصخرية لأشكال متنوعة، فيما يبلغ طولها قرابة 8 أمتار، وتتربع على قاعدتين تحملان الصخرتين…","ووفق هيئة التراث تقع الصخرة \"المتوأمة\"، ضمن نطاق جغرافي اشتهر بتنوع شواهده الحضارية ونقوشه الصخرية التي تؤكد المكانة التاريخية التي تمتعت بها منطقة تبوك بشكل عام ومحافظة تيماء بشكل خاص، عبر العصور بوصفها إحدى المحطات المهمة على طرق التجارة القديمة في شمال غرب الجزيرة العربية."]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2653693?type=news&uuid=N2653693','https://spa.gov.sa/ar/N2653693?type=news&uuid=N2653693','N2653693','N2653693','','السعودية','2026-08-14T08:30:00.000Z',NULL,'2026-08-15T14:25:01.348Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10607113.jpg','/api/media/ebae71c2-f9f9-4bc4-a473-ff34006ac743','/api/media/ebae71c2-f9f9-4bc4-a473-ff34006ac743?variant=thumbnail','ثقافي / ما الصخرة "المتوأمة" التي تجمع فرادة التكوين وثراء الإرث التاريخي؟',1600,900,'valid','published','archived','valid',56,'86f63ba30f56110244fef1708301965c220275a2eb853ffefed0a26d25a52154','0d4a277ec31104d4918d92d8549f3fcd9c6471e109335e2dd771fc37822e68ad','محدّث','2026-08-14T14:14:20.523Z','2026-10-07T20:52:42.401Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة التراث تقع الصخرة المتوأمة","الاقتصاد والأسواق","تبوك"]','["هيئة التراث تقع الصخرة المتوأمة","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:52:42.401Z',200,88,0,'source_article_available','',NULL,NULL,'body:a6ccd8da4f6f9ebccc38f68313d02840644165d8b6aaeb8a7d7eff53290e1c68','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('02d43d1d-3d04-4f62-b333-b75c8427a419','news-02d43d1d-3d04-4f62-b333-b75c8427a419','وزارة الخارجية تعرب عن تعازي ومواساة المملكة لحكومة وشعب مصر في ضحايا الحادث المروري الذي وقع في محافظة الإسماعيلية','وزاره الخارجيه تعرب عن تعازي ومواساه المملكه لحكومه وشعب مصر في ضحايا الحادث المروري الذي وقع في محافظه الاسماعيليه','أعربت وزارة الخارجية عن خالص تعازي المملكة وصادق مواساتها لحكومة وشعب جمهورية مصر العربية في ضحايا الحادث المروري الذي وقع بمحافظة الإسماعيلية.','["وعبرت الوزارة عن تضامن المملكة مع الأشقاء في جمهورية مصر العربية في هذا المصاب الأليم، وخالص تعازيها لأسر الضحايا، وتمنياتها للمصابين بالشفاء العاجل."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/3Ba-3Uv','https://sabq.org/article/3Ba-3Uv','','https://sabq.org/article/3Ba-3Uv','صحيفة سبق','السعودية','2026-08-13T11:58:00.000Z','2026-08-13T14:58:00.000Z','2026-08-14T14:18:42.091Z','https://media.sabq.org/news/2026/08/8c7f38e0-d2f7-46fd-8186-03acca6b41c5/w1200.webp','/api/media/02d43d1d-3d04-4f62-b333-b75c8427a419','/api/media/02d43d1d-3d04-4f62-b333-b75c8427a419?variant=thumbnail','وزارة الخارجية تعرب عن تعازي ومواساة المملكة لحكومة وشعب مصر في ضحايا الحادث المروري الذي وقع في محافظة الإسماعيلية',1200,675,'valid','published','archived','valid',62,'07f43462dbe159a25e5fc25daadc7e4671e1cf7d5911de785266446f29c7af57','24e8df43ca3e1aae25e9856149d00e9915c96f3cd709a3a3d2a6a633a86b1906','محدّث','2026-08-14T14:18:42.091Z','2026-10-07T20:52:42.959Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الخارجية تعرب عن تعازي"]','["وزارة الخارجية تعرب عن تعازي"]','manual_approved','ambiguous_category','[{"category":"السياسة","score":9},{"category":"المجتمع","score":6},{"category":"أخبار السعودية","score":3}]','Active','2026-10-07T20:52:42.959Z',200,78,0,'source_article_available','',NULL,NULL,'body:e7c0874496135ac524eb813ea34620892698bae493cf526eb033248c7ba50cb1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ebff4910-e8ab-4b88-b52a-fdfb3ab7261c','news-ebff4910-e8ab-4b88-b52a-fdfb3ab7261c','11 طالباً من تعليم الطائف يتأهلون لملتقى النخبة الأول في الرياض','11 طالبا من تعليم الطائف يتاهلون لملتقي النخبه الاول في الرياض','تأهّل 11 طالباً وطالبة من الإدارة العامة للتعليم بمحافظة الطائف للمشاركة في ملتقى النخبة الأول، الهادف إلى تأهيل طلبة المنتخبات السعودية العلمية للمشاركة في المنافسات الدولية.','["ويُقام الملتقى في مدينة الرياض خلال الفترة من 10 إلى 21 أغسطس 2026م، وفقاً للخطة السنوية للجنة التنفيذية المشتركة بين وزارة التعليم ومؤسسة «موهبة» للمسابقات والأولمبيادات الدولية.","ويستهدف الملتقى تدريب وتأهيل طلبة المنتخبات السعودية العلمية المرشحين من أولمبياد العلوم والرياضيات «نسمو»، ورفع جاهزيتهم العلمية والمهارية، وإعدادهم للمشاركة في المنافسات العلمية الدولية، بما يُسهم في تعزيز حضور المملكة وتمثيلها في المحافل العلمية العالمية.","وعلى صعيد آخر، يشارك الطالب يزن بن أحمد المالكي في الأولمبياد الدولي للمواصفات 2026، الذي تستضيفه كوريا الجنوبية.","وهنّأ المدير العام للتعليم بالطائف الدكتور سعيد بن عبدالله الغامدي الطلبةَ ومدارسهم وأسرهم ومعلميهم، مؤكداً أن هذا الإنجاز ثمرةٌ للتكامل بين الأسرة والمدرسة، مشيراً إلى أنه يُضاف إلى سلسلة الإنجازات التي حققها طلبة تعليم الطائف على المستويين الوطني والدولي، متمنياً لهم مزيداً من التوفيق والسداد."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/qDEIbRx','https://sabq.org/article/qDEIbRx','','https://sabq.org/article/qDEIbRx','فهد العتيبي','السعودية','2026-08-13T11:45:00.000Z','2026-08-13T14:45:00.000Z','2026-08-14T14:18:42.594Z','https://media.sabq.org/news/2026/08/52bf9024-ca06-4d9d-8689-6a171a0b54c5/w750.webp','/api/media/ebff4910-e8ab-4b88-b52a-fdfb3ab7261c','/api/media/ebff4910-e8ab-4b88-b52a-fdfb3ab7261c?variant=thumbnail','11 طالباً من تعليم الطائف يتأهلون لملتقى النخبة الأول في الرياض',750,575,'valid','published','archived','valid',99,'231684bf5a51df38f061f287c92f2e56b684981bac5bb4e8ee6b28538c1cc490','03baa64c3e4aad5286a91a22e893fcb0075decdb32d7ad0ebb0b230e4ccf0689','محدّث','2026-08-14T14:18:42.594Z','2026-10-07T20:51:58.749Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة التعليم ومؤسسة موهبة للمسابقات","التعليم والتدريب","الرياض"]','["وزارة التعليم ومؤسسة موهبة للمسابقات","التعليم والتدريب"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"المجتمع","score":1.5},{"category":"العالم","score":1.5}]','Active','2026-10-07T20:51:58.749Z',200,78,0,'source_article_available','',NULL,NULL,'body:84ecf31907c3296ad378a1a104103d5910688c6c3ad6dce3e3d386e47c046935','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b6d1ba48-9487-4f6c-8cfa-2a4f060950dc','news-b6d1ba48-9487-4f6c-8cfa-2a4f060950dc','بيش تزدان بألوان المطر.. ومشاهد تجذب المتنزهين','بيش تزدان بالوان المطر ومشاهد تجذب المتنزهين','جددت الأمطار الغزيرة التي شهدتها محافظة بيش خلال الأيام الماضية المشهد الطبيعي والزراعي، ودفعت بمياه الأودية نحو السهول والمزارع، لتتسع رقعة الخضرة وتبرز الملامح الزراعية للمحافظة في مشاهد استوقفت الأهالي والزوار ومحبي التصوير، خلال الإجازة الصيفية.','["وأعادت الأمطار إلى واجهة المشهد العلاقة الوثيقة بين أودية بيش وأراضيها الزراعية، مع جريان عدد من الأودية، من بينها وادي \"قُرى\"، أحد روافد وادي بيش، وامتداد المياه عبر السهول والمنخفضات نحو مساحات زراعية واسعة، بما يعكس أهمية الأودية في تغذية الأراضي وتجدد الغطاء النباتي الذي يميز أجزاء واسعة من المحافظة.","ورصدت عدسة \"واس\" من مدخل بيش امتداد المياه بين المزارع والمساحات الخضراء وعلى جانبي الطريق، في لوحة رسمتها الأمطار واستوقفت العابرين والمتنزهين، وجذبت محبي التصوير لتوثيق تداخل المياه والخضرة مع الامتداد الزراعي للمحافظة.","وتحولت المواقع المطلة على هذه المشاهد إلى نقاط جذب للأهالي والزوار، مع تنامي الرحلات العائلية خلال الإجازة الصيفية، إذ أتاحت الأجواء الماطرة فرصة للتنزه ومشاهدة اتساع الرقعة الخضراء وتدفقات المياه، وأضافت إلى الوجهات الطبيعية في منطقة جازان مشاهد مختلفة ترتبط بطبيعة بيش السهلية والزراعية.","وتمنح الأمطار بيش قيمة تتجاوز المشهد الموسمي، فهي عنصر رئيس في تجدد بيئتها الزراعية وتغذية أراضيها، وتكشف عند هطولها عن جانب من هوية المحافظة التي ارتبطت بالزراعة وخصوبة سهولها، لتلتقي في موسم المطر قيمة المكان الزراعية مع جاذبيته الطبيعية والسياحية."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/Gbr6b2i','https://sabq.org/article/Gbr6b2i','','https://sabq.org/article/Gbr6b2i','صحيفة سبق','السعودية','2026-08-13T11:46:00.000Z','2026-08-13T14:46:00.000Z','2026-08-14T14:18:43.233Z','https://media.sabq.org/news/2026/08/9887971a-2a83-451c-92d5-c11f05022346/w1126.webp','/api/media/b6d1ba48-9487-4f6c-8cfa-2a4f060950dc','/api/media/b6d1ba48-9487-4f6c-8cfa-2a4f060950dc?variant=thumbnail','صورة من الألبوم',1126,2000,'valid','published','archived','valid',56,'93ab58a5f93b06404ff093f08b69b3d559f1b37ea4b6256f7cefee3712cf57e7','d52f5ceaaf24031ace290dbd35e5d030784aa2214bbdf9c94b6e2072147ebc67','محدّث','2026-08-14T14:18:43.233Z','2026-10-07T20:51:58.755Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس في تجدد بيئتها الزراعية","الطقس والمناخ","جازان"]','["رئيس في تجدد بيئتها الزراعية","الطقس والمناخ"]','manual_approved','below_category_threshold','[{"category":"الصحة","score":1.5},{"category":"السفر","score":1.5},{"category":"البيئة والمناخ","score":1.5}]','Active','2026-10-07T20:51:58.755Z',200,80,0,'source_article_available','',NULL,NULL,'body:0d6535b67908f89463d4b968f8fcef0ab70cb1a8ae134ca5eab80e87afecfa22','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('df07440e-d6b4-4d94-8805-38a66c95b196','news-df07440e-d6b4-4d94-8805-38a66c95b196','قافلة مساعدات سعودية جديدة تصل غزة بسلال غذائية لآلاف الأسر','قافله مساعدات سعوديه جديده تصل غزه بسلال غذائيه لالاف الاسر','وصلت قافلة مساعدات إغاثية جديدة إلى قطاع غزة، تحمل على متنها سلالاً غذائية مقدَّمة من مركز الملك سلمان للإغاثة والأعمال الإنسانية، وذلك ضمن الحملة الشعبية السعودية لإغاثة الشعب الفلسطيني في القطاع.','["وتسلَّم هذه المساعدات المركزُ السعودي للثقافة والتراث، الشريك المنفذ لمركز الملك سلمان للإغاثة في قطاع غزة، إذ ستُسهم هذه الإمدادات الغذائية في توسيع نطاق عمليات التوزيع اليومية، بما يتيح الوصول إلى أكبر عدد من الأسر المحتاجة في مختلف محافظات القطاع.","وتأتي هذه القافلة في ظل استمرار الأوضاع الإنسانية الصعبة التي يعيشها سكان غزة، حيث يُشكّل تأمين الغذاء أحد أبرز الاحتياجات اليومية لآلاف الأسر، في وقت تتصاعد فيه التحديات المعيشية جراء الظروف الراهنة."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/w6gz1tk','https://sabq.org/article/w6gz1tk','','https://sabq.org/article/w6gz1tk','صحيفة سبق','السعودية','2026-08-13T10:52:00.000Z','2026-08-13T13:53:00.000Z','2026-08-14T14:18:44.319Z','https://media.sabq.org/news/2026/08/9534a461-b0a3-4267-ace2-f95ca4ebd23a/w1280.webp','/api/media/df07440e-d6b4-4d94-8805-38a66c95b196','/api/media/df07440e-d6b4-4d94-8805-38a66c95b196?variant=thumbnail','قافلة مساعدات سعودية جديدة تصل غزة بسلال غذائية لآلاف الأسر',1280,852,'valid','published','archived','valid',42,'98c9d893cb5210e5cc822194fac57f15a1e025e37a79c4b81936407c5ba287d7','d5fbd21dadd32c36e7fd405c8ab1b167bbae08932bdc7ff14f7eb0bdd0b9c16e','محدّث','2026-08-14T14:18:44.319Z','2026-10-07T20:52:45.307Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","غزة"]','["الثقافة والفنون"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"الثقافة","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T20:52:45.307Z',200,78,0,'source_article_available','',NULL,NULL,'body:5d203f718cfa650ab64b5d2adfb258cd7ec12c72265dda2928a1d3af8b8501a1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('119f6b26-a2ed-4fc2-8bc3-98602c56b034','news-119f6b26-a2ed-4fc2-8bc3-98602c56b034','نائب وزير الخارجية الخريجي يستقبل سفير الصين لدى المملكة','نائب وزير الخارجيه الخريجي يستقبل سفير الصين لدي المملكه','استقبل نائب وزير الخارجية المهندس وليد بن عبدالكريم الخريجي، في مقر الوزارة بالرياض، سفير جمهورية الصين الشعبية لدى المملكة تشانغ هوا.','["وجرى خلال الاستقبال استعراض العلاقات الثنائية بين البلدين، ومناقشة التطورات الإقليمية والدولية، والجهود المبذولة بشأنها."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/r1gfax7','https://sabq.org/article/r1gfax7','','https://sabq.org/article/r1gfax7','صحيفة سبق','السعودية','2026-08-13T10:53:00.000Z','2026-08-13T13:53:00.000Z','2026-08-14T14:18:44.804Z','https://media.sabq.org/news/2026/08/7295dad0-e870-481e-ba78-f43a48f0e2d2/w1280.webp','/api/media/119f6b26-a2ed-4fc2-8bc3-98602c56b034','/api/media/119f6b26-a2ed-4fc2-8bc3-98602c56b034?variant=thumbnail','نائب وزير الخارجية الخريجي يستقبل سفير الصين لدى المملكة',1280,854,'valid','published','archived','valid',44,'c33d08aa71bb5178515abcc18ce3d9cbe643445a49f661809d3a74ddd3b2ed5b','2551c510ded28d76f2f4d60d645d7f475e0c3931cf08997b1f20b40fa6962f90','محدّث','2026-08-14T14:18:44.804Z','2026-10-07T20:52:45.891Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الخارجية الخريجي يستقبل سفير","الصين"]','["وزير الخارجية الخريجي يستقبل سفير"]','manual_approved','below_category_threshold','[{"category":"العالم","score":3},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:52:45.891Z',200,74,0,'source_article_available','',NULL,NULL,'body:ada05c42b504f9e9be7655245158c37efe20dfa194f4dac414237f13a696bd1d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('703c0ac8-36a8-4ad0-91bf-8c26375f6fc5','news-703c0ac8-36a8-4ad0-91bf-8c26375f6fc5','بعد توقيفه في السفارة السورية.. لبنان يستجوب اللواء عادل عيسى ويقرر تسليمه إلى دمشق','بعد توقيفه في السفاره السوريه لبنان يستجوب اللواء عادل عيسي ويقرر تسليمه الي دمشق','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية استجوب القضاء اللبناني اللواء السوري السابق عادل عيسى، قائد الفرقة 17 في نظام الأسد، بعد توقيفه داخل السفارة السورية في منطقة بعبدا بقضاء جبل لبنان ، فيما تقرر تسليمه إلى القضاء السوري وفق اتفاقية التعاون القضائي بين البلدين، بحسب مصادر مطل','["استجوب القضاء اللبناني اللواء السوري السابق عادل عيسى، قائد الفرقة 17 في نظام الأسد، بعد توقيفه داخل السفارة السورية في منطقة بعبدا بقضاء جبل لبنان ، فيما تقرر تسليمه إلى القضاء السوري وفق اتفاقية التعاون القضائي بين البلدين، بحسب مصادر مطلعة نقلت عنها قناة «العربية».","وأفادت المصادر بأن مدعي عام التمييز القاضي أحمد رامي الحاج استجوب عيسى بشأن اتهامات تتعلق بارتكاب جرائم عسكرية خلال خدمته في الجيش السوري السابق، قبل أن يقرر تسليمه إلى القضاء السوري، استنادًا إلى الاتفاقية التي تلزم البلدين باسترداد وتسليم الملاحقين من مواطني كل دولة.","وكان عيسى قد دخل إلى السفارة السورية الأسبوع الماضي، اعتقادًا منه بعدم وجود ملاحقات بحقه، إلا أن موظفي السفارة أبلغوا السلطات القضائية اللبنانية بوجوده، لتتوجه عناصر المباحث إلى السفارة وتتسلمه، قبل اقتياده إلى المخفر في القصر العدلي في بيروت ."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/bcfbjptgv','https://ajel.sa/international/bcfbjptgv','https://ajel.sa/international/bcfbjptgv','https://ajel.sa/international/bcfbjptgv','فريق التحرير','السعودية','2026-08-14T07:08:00.000Z','Wed, 07 Oct 2026 20:51:45 GMT','2026-08-14T16:19:49.250Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D9%84%D9%88%D8%A7%D8%A1-%D8%A7%D9%84%D8%B3%D9%88%D8%B1%D9%8A-%D8%A7%D9%84%D8%B3%D8%A7%D8%A8%D9%82-%D8%B9%D8%A7%D8%AF%D9%84-%D8%B9%D9%8A%D8%B3%D9%89-zjC8b5gX.jpg','/api/media/703c0ac8-36a8-4ad0-91bf-8c26375f6fc5','/api/media/703c0ac8-36a8-4ad0-91bf-8c26375f6fc5?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',45,'f3da5b19afa589f77ddcd68088a540dc40d83ee03b73e97b2dedb2a9eb326e7e','0453c89c4785fdf519c6ad94d473c5fa4c86ffa8155c28bb8f909f2c39f12157',NULL,'2026-08-14T16:19:49.250Z','2026-10-07T20:51:46.877Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["لبنان"]','[]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"المجتمع","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:51:46.877Z',200,79,0,'source_content_changed','',NULL,NULL,'body:7bff0b2c1fd03b701834edb88a2900ce5e12adbd7ae2e39da420a6a9e808f971','Wed, 07 Oct 2026 20:51:45 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b5e8cdf5-08bc-4944-99fc-2421d0021eb8','news-b5e8cdf5-08bc-4944-99fc-2421d0021eb8','برنامج رياضي صيفي بالطائف يستهدف أكثر من 10 آلاف طالب','برنامج رياضي صيفي بالطائف يستهدف اكثر من 10 الاف طالب','وقف المدير العام للتعليم بمحافظة الطائف الدكتور سعيد بن عبدالله الغامدي، على فعاليات البرنامج الرياضي الصيفي 2026م، الذي يستهدف أكثر من 10 آلاف طالب وطالبة، ويقدم برامج رياضية نوعية تجمع بين التدريب والترفيه وتنمية المهارات، واستثمار أوقات الطلبة خلال الإجازة الصيفية، وسط إقبال وتفاعل لافت.','["ويأتي البرنامج، الذي يستمر ثلاثة أسابيع، ضمن شراكة استراتيجية بين وزارة التعليم ووزارة الرياضة والاتحاد السعودي للرياضة المدرسية، ويهدف إلى توفير بيئة رياضية جاذبة للطلاب والطالبات، وتعزيز الممارسة الرياضية، إلى جانب اكتشاف المواهب الواعدة في مختلف الألعاب وصقل مهاراتها وتطوير قدراتها.","وأكد الدكتور الغامدي أن البرنامج يمثل امتدادًا للشراكة الاستراتيجية بين الجهات المعنية بالرياضة المدرسية، ويجسد أهمية استثمار الإجازة الصيفية في برامج نوعية تتيح للطلبة ممارسة الأنشطة الرياضية في بيئة محفزة تجمع بين المتعة والتدريب وبناء المهارات.","وأشار إلى أن البرامج الرياضية تسهم في رفع مستوى اللياقة البدنية لدى الطلبة، وتنمية مهاراتهم الرياضية الأساسية، وتعزيز قيم الانضباط والعمل الجماعي والمنافسة الإيجابية، بما يدعم حضور الرياضة في حياة الطلبة بوصفها نمطًا صحيًا مستدامًا.","وشهدت الفعاليات تفاعلًا وإقبالًا مميزًا من الطلاب والطالبات، فيما ثمّن مدير عام تعليم الطائف جهود الفرق العاملة وشركاء النجاح في تنفيذ البرنامج، وإتاحة فرص رياضية نوعية تسهم في اكتشاف المواهب الطلابية وتنمية قدراتهم."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/nwJ_3We','https://sabq.org/article/nwJ_3We','','https://sabq.org/article/nwJ_3We','فهد العتيبي','السعودية','2026-08-13T14:51:00.000Z','2026-08-13T17:53:00.000Z','2026-08-14T16:24:32.504Z','https://media.sabq.org/news/2026/08/61ccf549-a90b-4768-8036-b25df5716224/w1600.webp','/api/media/b5e8cdf5-08bc-4944-99fc-2421d0021eb8','/api/media/b5e8cdf5-08bc-4944-99fc-2421d0021eb8?variant=thumbnail','برنامج رياضي صيفي بالطائف يستهدف أكثر من 10 آلاف طالب',1600,1254,'valid','published','archived','valid',90,'92da7022a5338d1fe1ef29dcd4a76f8973a33503afaa23f230d222f2a4118558','a969883384b4398c502dbba733bd1505959c2074f0f8c8ab1cbe743bb217a1a4','محدّث','2026-08-14T16:24:32.504Z','2026-10-07T20:51:56.627Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة التعليم ووزارة الرياضة والاتحاد","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق","الرياض"]','["وزارة التعليم ووزارة الرياضة والاتحاد","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[{"category":"الاقتصاد","score":4},{"category":"المناطق","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T20:51:56.627Z',200,74,0,'source_article_available','',NULL,NULL,'body:05727c3876182e8fc802573f1a150b25c64077c3f80c4daf661f50c9d879d132','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a5cf0b4c-1730-482a-95b1-b320e2443e87','news-a5cf0b4c-1730-482a-95b1-b320e2443e87','«بيئة مكة» و«التجارة» يعززان التنسيق في أعمال لجانهما المشتركة','بيئه مكه و التجاره يعززان التنسيق في اعمال لجانهما المشتركه','عقد مكتب وزارة البيئة والمياه والزراعة بالعاصمة المقدسة اجتماعًا تنسيقيًا مع فرع وزارة التجارة بالعاصمة المقدسة، بهدف تعزيز أوجه التعاون والتكامل بين الجهتين، ورفع مستوى التنسيق في الأعمال والمهام المشتركة.','["وتناول الاجتماع مناقشة أعمال اللجان المشتركة والمرتبطة بين الجهتين، واستعراض أوجه التعاون والتنسيق القائم، فضلًا عن بحث سبل تطوير آليات العمل وتعزيز التكامل في أعمال اللجان المقبلة، بما يُسهم في رفع كفاءة الأداء وتوحيد الجهود وتحقيق الأهداف المشتركة.","وأكد مدير مكتب وزارة البيئة والمياه والزراعة بالعاصمة المقدسة المهندس غالب بن يحيى حامظي، أن الاجتماع يأتي في إطار حرص المكتب على تعزيز الشراكة والتنسيق مع الجهات الحكومية ذات العلاقة، مشيرًا إلى أن التكامل بين الجهات يُسهم في رفع كفاءة أعمال اللجان المشتركة وتسريع إنجاز المهام وتحقيق مستهدفاتها بكفاءة وفاعلية.","وقال حامظي: «نحرص على استمرار التنسيق والتعاون مع فرع وزارة التجارة بالعاصمة المقدسة، وتبادل الخبرات وتوحيد الجهود بما يحقق الأهداف المشتركة، ويُسهم في الارتقاء بجودة الأعمال والخدمات المقدمة للمستفيدين»."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/aY6yQTE','https://sabq.org/article/aY6yQTE','','https://sabq.org/article/aY6yQTE','فهد العتيبي','السعودية','2026-08-13T14:15:00.000Z','2026-08-13T17:16:00.000Z','2026-08-14T16:24:32.989Z','https://media.sabq.org/news/2026/08/259a9bb1-f7b9-4d73-9cff-e2b57327c0fc/w1600.webp','/api/media/a5cf0b4c-1730-482a-95b1-b320e2443e87','/api/media/a5cf0b4c-1730-482a-95b1-b320e2443e87?variant=thumbnail','«بيئة مكة» و«التجارة» يعززان التنسيق في أعمال لجانهما المشتركة',1600,1200,'valid','published','archived','valid',44,'ca7ea9697c388ed49a6488c1389f56067fa368a2e64a20b5bba99081648d123c','9345027dbb5fb827a11fbfa499c701bc702addf06ccfcc2b9251b7bb18e3bf7c','محدّث','2026-08-14T16:24:32.989Z','2026-10-07T20:51:53.201Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البيئة والمياه والزراعة بالعاصمة","الاقتصاد والأسواق","مكة"]','["وزارة البيئة والمياه والزراعة بالعاصمة","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":3},{"category":"البيئة والمناخ","score":3},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:51:53.201Z',200,77,0,'source_article_available','',NULL,NULL,'body:5ce89404ea82f94259d195d0bb40658c8f91970fdc1043a613b0148978872c6e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f56e8501-b0b3-47a9-aeb5-7364bfa504ec','news-f56e8501-b0b3-47a9-aeb5-7364bfa504ec','القادسية يقلب الطاولة على الشباب بثلاثية في الجولة الأولى من دوري روشن','القادسيه يقلب الطاوله علي الشباب بثلاثيه في الجوله الاولي من دوري روشن','قلب فريق القادسية تأخره بهدف أمام مضيفه الشباب إلى فوز ثمين بثلاثة أهداف مقابل هدف، في مستهل مشوار الفريقين بمنافسات دوري روشن السعودي للمحترفين موسم 2026-2027.','["افتتح الشباب التسجيل عبر همام الهمامي في الدقيقة 15 من عمر الشوط الأول، قبل أن يرد القادسية بالتعادل بهدف محمد أبو الشامات في الدقيقة 36، لينتهي الشوط الأول بالتعادل الإيجابي بهدف لكل فريق.","وفي الشوط الثاني، أحدث المكسيكي جوليان كينونيس، هداف دوري روشن في الموسم الماضي، الفارق لمصلحة القادسية بهدف غالٍ في الدقيقة 80، قبل أن يُسدل تركي العمار الستار على المباراة بالهدف الثالث في الوقت بدل الضائع، ليختطف القادسية النقاط الثلاث كاملةً."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/TbxVCUE','https://sabq.org/article/TbxVCUE','','https://sabq.org/article/TbxVCUE','صحيفة سبق','السعودية','2026-08-13T14:27:00.000Z','2026-08-13T17:48:00.000Z','2026-08-14T16:24:33.285Z','https://media.sabq.org/news/2026/08/73302cc9-657a-42e1-9576-e775d44544b2/w1600.webp','/api/media/f56e8501-b0b3-47a9-aeb5-7364bfa504ec','/api/media/f56e8501-b0b3-47a9-aeb5-7364bfa504ec?variant=thumbnail','القادسية يقلب الطاولة على الشباب بثلاثية في الجولة الأولى من دوري روشن',1600,2000,'valid','published','archived','valid',99,'8b799fd8d8ba83b3d55ebfff2806036b879f6bb5086dbe8b1af75c2cfd559503','87a23d681640b011ed45cdb61e75bcadf68e58f09dc8bdccd114a3a6506f5ce7','محدّث','2026-08-14T16:24:33.285Z','2026-10-07T20:51:51.697Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الصحة","score":0}]','Active','2026-10-07T20:51:51.697Z',200,74,0,'source_article_available','',NULL,NULL,'body:cdd79d820968a5c380b76bc6725c94bdc3db62e8717ba1309a8fa85d72a6b2c8','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9765c702-30a3-4108-9cc5-61b6ae20bc95','news-9765c702-30a3-4108-9cc5-61b6ae20bc95','بقيادة سعودية ونيابة باكستانية.. «التحالف البحري متعدد الجنسيات» ينتقل من التأسيس إلى التفعيل باجتماع 39 دولة في جدة','بقياده سعوديه ونيابه باكستانيه التحالف البحري متعدد الجنسيات ينتقل من التاسيس الي التفعيل باجتماع 39 دوله في جده','دخل التحالف البحري الدفاعي متعدد الجنسيات (MMDC) مرحلة التفعيل الفعلي؛ إذ أعلنت وزارة الدفاع انعقاد اجتماع التخطيط الثالث للتحالف في مقر قيادة الأسطول الغربي بمدينة جدة، بمشاركة ممثلين عن 39 دولة شقيقة وصديقة، في خطوة رئيسية وصفها بيان الوزارة، اليوم الخميس، بأنها «الانطلاقة الفعلية نحو مرحلة التفعيل المؤسسي والعملياتي».','["وبحسب البيان، بلغ عدد الدول الموقعة على البيان المشترك 15 دولة، فيما استكملت 13 دولة إجراءاتها الوطنية ووقعت على ميثاق التحالف وأعلنت انضمامها رسمياً، على أن تواصل بقية الدول استكمال إجراءاتها الوطنية اللازمة للانضمام.","قائد سعودي ونائب باكستاني ومقر وشعار وكشف البيان عن اكتمال عناصر البناء المؤسسي للتحالف، وفي مقدمتها تعيين قائد التحالف من المملكة العربية السعودية، والتوافق على أن يكون نائب القائد في الدورة الأولى من جمهورية باكستان الإسلامية، إلى جانب تحديد المقر المخصص لقيادة التحالف واعتماد شعاره، واستكمال الأطر التنظيمية والتخطيطية والأدلة المرجعية اللازمة لبدء أعماله.","ثلاثة أجهزة تدخل الخدمة وأسهم الاجتماع الثالث في استكمال الترتيبات العملية لتفعيل أجهزة التحالف وقيادته متعددة الجنسيات، تمهيداً لبدء استقبال الضباط والكوادر من الدول الأعضاء ودمجهم ضمن هيكل القيادة والأركان المشتركة، ومركز العمليات والتنسيق البحري المشترك، ومركز استخبارات التحالف — بما يسرّع بناء قدراته العملياتية ويعزز جاهزيته للاضطلاع بمهامه الدفاعية ضمن قطاع مسؤوليته.","أمن بحري جماعي لحماية الممرات وأكد البيان أن الانتقال إلى هذه المرحلة يمثل خطوة متقدمة في بناء تحالف دفاعي بحري متعدد الجنسيات ومستدام، يهدف إلى «ترسيخ مفهوم الأمن البحري الجماعي، وحماية حرية الملاحة والممرات والمضائق البحرية، ودعم استمرارية التجارة الدولية وسلاسل الإمداد العالمية» — في توقيت تتعرض فيه الملاحة الإقليمية لتهديدات متصاعدة جعلت أمن الممرات أولوية دولية جامعة."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/svKSbue','https://sabq.org/article/svKSbue','','https://sabq.org/article/svKSbue','صحيفة سبق','السعودية','2026-08-13T13:13:00.000Z','2026-08-13T16:17:00.000Z','2026-08-14T16:24:34.457Z','https://media.sabq.org/news/2026/08/80587846-cb9c-4d9a-be8d-9912ef5e48d5/w680.webp','/api/media/9765c702-30a3-4108-9cc5-61b6ae20bc95','/api/media/9765c702-30a3-4108-9cc5-61b6ae20bc95?variant=thumbnail','صورة من الألبوم',680,454,'valid','published','archived','valid',48,'24346aaea7a3b64b1cbddd1b25306bac6459f33b9a37cbf3a3c437dde95851e2','a5f143b519af827d8b013ba4b42470b381a617eeee69f937353a0a62ba5cccc1','محدّث','2026-08-14T16:24:34.457Z','2026-10-07T20:51:58.756Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الاقتصاد والأسواق","جدة"]','["التعليم والتدريب","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":3},{"category":"الاقتصاد","score":3}]','Active','2026-10-07T20:51:58.756Z',200,79,0,'source_article_available','',NULL,NULL,'body:6f7c04fc2400cc1006e26079e11479fe93e2f204da97184c4dc88615a7588e80','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8cc089c0-b0ec-4658-a416-872cf2391fbc','news-8cc089c0-b0ec-4658-a416-872cf2391fbc','الأخضر تحت 17 عاماً يواصل معسكر الطائف استعداداً لكأس العالم 2026','الاخضر تحت 17 عاما يواصل معسكر الطائف استعدادا لكاس العالم 2026','واصل المنتخب السعودي تحت 17 عاماً لكرة القدم، اليوم الخميس، تدريباته ضمن معسكره في مدينة الطائف، المقام في إطار برنامج الإعداد لكأس العالم تحت 17 عاماً 2026.','["وأجرى لاعبو «الأخضر» حصتهم التدريبية المسائية تحت إشراف المدرب الوطني أحمد الحنفوش والجهاز الفني المساعد، إذ تركّزت على تمارين اللياقة البدنية، أعقبها العمل على الجوانب التكتيكية، قبل أن تُختتم الحصة بمناورة فنية على كامل مساحة الملعب.","وسيخوض المنتخب السعودي منافسات كأس العالم تحت 17 عاماً 2026 ضمن المجموعة الرابعة، التي تضم إلى جانبه منتخبات فرنسا والأوروغواي وهايتي."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/JP--g12','https://sabq.org/article/JP--g12','','https://sabq.org/article/JP--g12','صحيفة سبق','السعودية','2026-08-13T14:14:00.000Z','2026-08-13T17:14:00.000Z','2026-08-14T16:24:34.473Z','https://media.sabq.org/news/2026/08/b6fbb7f3-e5e8-4e73-80f3-8e7bc4e09b32/w1280.webp','/api/media/8cc089c0-b0ec-4658-a416-872cf2391fbc','/api/media/8cc089c0-b0ec-4658-a416-872cf2391fbc?variant=thumbnail','الأخضر تحت 17 عاماً يواصل معسكر الطائف استعداداً لكأس العالم 2026',1280,1017,'valid','published','archived','valid',99,'e478427615d0399d373eceaa5fcdb0daa8ee5a2575b982fbaef5abb61caddd4f','a3ffe8a4d36be2e6e02a2690574196806585a83238739fec8d32747f823a80d2','محدّث','2026-08-14T16:24:34.473Z','2026-10-07T20:51:51.096Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','classified','','[{"category":"التعليم","score":1.5},{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:51:51.096Z',200,73,0,'source_article_available','',NULL,NULL,'body:e677135aa7ba72506d0b07d1553c62f6df28d136dfbe2be432a6a30cb04883d9','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('18c4514d-d805-4034-92e2-38e4c3dcb3d7','news-18c4514d-d805-4034-92e2-38e4c3dcb3d7','الأهلي يقص شريط دوري روشن بفوز ثمين على ضيفه الدرعية.. بهدف دون رد','الاهلي يقص شريط دوري روشن بفوز ثمين علي ضيفه الدرعيه بهدف دون رد','حقق فريق الأهلي فوزاً ثميناً في افتتاح الجولة الأولى من دوري روشن السعودي للمحترفين للموسم 2026/2027، إذ تغلب على ضيفه الدرعية — الوجه الجديد في الدوري — بهدف دون مقابل، في اللقاء الذي أُقيم مساء الخميس على ملعب الأول بارك في العاصمة الرياض.','["جاء الهدف الوحيد في الشوط الأول على قدم اللاعب إدوارد سبيرتسيان في الدقيقة 26، بتسديدة قوية لم يتمكن حارس الدرعية من التصدي لها، ليُغلق الشوط الأول بتقدم الأهلي بهدف دون مقابل.","في الشوط الثاني، لم تتغير موازين اللقاء، وحافظ الأهلي على تقدمه حتى الصافرة النهائية، ليحسم الفوز ويحصد أولى نقاطه الثلاث في الدوري، فيما خرج الدرعية بخُفَّي حنين من مباراته الافتتاحية في دوري روشن."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/-wKngmW','https://sabq.org/article/-wKngmW','','https://sabq.org/article/-wKngmW','صحيفة سبق','السعودية','2026-08-13T14:11:00.000Z','2026-08-13T17:14:00.000Z','2026-08-14T16:24:34.716Z','https://media.sabq.org/news/2026/08/fb6901f8-1e61-4353-974d-e638c4f429e3/w1600.webp','/api/media/18c4514d-d805-4034-92e2-38e4c3dcb3d7','/api/media/18c4514d-d805-4034-92e2-38e4c3dcb3d7?variant=thumbnail','الأهلي يقص شريط دوري روشن بفوز ثمين على ضيفه الدرعية.. بهدف دون رد',1600,2000,'valid','published','archived','valid',99,'42cdb1cbddec24d26145ec15b2b5e426f7bc5271806c2a9c4999455c458e2b12','aec42a5f63020895423e70ea052f3af0a7505de980254112db76d4020133d02a','محدّث','2026-08-14T16:24:34.716Z','2026-10-07T20:51:57.525Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:51:57.525Z',200,80,0,'source_article_available','',NULL,NULL,'body:9fd6883adccac1be92227f97f3f4e9de55bdc4edb0d963d95a75642ba657be8f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0dbaed07-cdb1-4ada-8aab-81f69d98e816','news-0dbaed07-cdb1-4ada-8aab-81f69d98e816','رصد زخة شهب البرشاويات في سماء العُلا','رصد زخه شهب البرشاويات في سماء العلا','رُصدت في سماء محمية الغراميل بمحافظة العُلا زخة شهب البرشاويات، بالتزامن مع بلوغها ذروة نشاطها السنوي، في ظاهرة فلكية تتكرر خلال شهر أغسطس من كل عام.','["وبدأ تصوير الزخة منذ مساء أمس وحتى فجر اليوم الخميس، توالت الشهب خلالها في سماء الغراميل وسط ظروف ملائمة للرصد، أسهم فيها انخفاض التلوث الضوئي وظلام السماء، ما أتاح توثيق الظاهرة بوضوح.","وتُعد البرشاويات من أشهر زخات الشهب السنوية، وتتميز بنشاطها الملحوظ وظهور عدد من الشهب الساطعة والكرات النارية، ويمكن أن يبلغ معدل ظهورها في ذروة النشاط، وتحت سماء مظلمة وظروف رصد مثالية، نحو 75 إلى 100 شهاب في الساعة.","ويعود مصدر زخة البرشاويات إلى الغبار والحطام الذي خلّفه المذنب \"سويفت-تتل\" على طول مداره، إذ تعبر الأرض أثناء دورانها حول الشمس المسار الذي خلّفته هذه الجسيمات، فتدخل الغلاف الجوي بسرعات عالية وتتوهج نتيجة تفاعلها مع الغلاف الجوي، لتظهر على هيئة خطوط ضوئية سريعة في السماء.","واكتسبت الزخة اسمها من كوكبة \"برشاوس\"، المعروفة عربيًا بـ\"حامل رأس الغول\"، إذ تبدو الشهب ظاهريًا كأنها تنطلق من منطقة في السماء تقع أمام هذه الكوكبة، ويُعرف هذا الموضع باسم \"نقطة الإشعاع\"، في حين يمكن مشاهدة الشهب في أنحاء واسعة من السماء."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/DqUDZdb','https://sabq.org/article/DqUDZdb','','https://sabq.org/article/DqUDZdb','صحيفة سبق','السعودية','2026-08-13T13:13:00.000Z','2026-08-13T16:13:00.000Z','2026-08-14T16:24:35.674Z','https://media.sabq.org/news/2026/08/61ed9b33-f050-4a9a-8ce6-bcfa1eb7f75a/w1200.webp','/api/media/0dbaed07-cdb1-4ada-8aab-81f69d98e816','/api/media/0dbaed07-cdb1-4ada-8aab-81f69d98e816?variant=thumbnail','رصد زخة شهب البرشاويات في سماء العُلا',1200,800,'valid','published','archived','valid',50,'c4ea36acb9f57851d1c4874b688bcd2fc2b3d81490a48e8ca8ab6ccbc1495f26','9fe4b5ae8ede3776947c5e316c7f4f8757b651dae16b6a90a7e85bc64aff82ca','محدّث','2026-08-14T16:24:35.674Z','2026-10-07T20:52:37.930Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة خطوط ضوئية سريعة في","الاقتصاد والأسواق"]','["هيئة خطوط ضوئية سريعة في","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":1.5},{"category":"الصحة","score":1.5},{"category":"السفر","score":1.5}]','Active','2026-10-07T20:52:37.930Z',200,76,0,'source_article_available','',NULL,NULL,'body:c80696304dd61237eff8928eb2430d0bc6ed82c774f30a71b16935bdb202da40','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('88e99249-5e19-42b5-bef0-9b2d40ebc64f','news-88e99249-5e19-42b5-bef0-9b2d40ebc64f','بمشاركة 40 جهة واستفادة 3900 شخص.. «منشآت» بالشراكة مع «سدايا» تختتم «أسبوع الذكاء الاصطناعي» بالرياض','بمشاركه 40 جهه واستفاده 3900 شخص منشات بالشراكه مع سدايا تختتم اسبوع الذكاء الاصطناعي بالرياض','اختتمت الهيئة العامة للمنشآت الصغيرة والمتوسطة (منشآت)، بالشراكة مع الهيئة السعودية للبيانات والذكاء الاصطناعي (سدايا)، فعاليات "أسبوع الذكاء الاصطناعي"، ضمن سلسلة "أسابيع الأعمال"، بمشاركة أكثر من 40 جهة من القطاعين الحكومي والخاص والمؤسسات التعليمية، واستفادة أكثر من 3900 مستفيد من فعاليات الأسبوع، الذي أُقيم خلال الفترة من 9 حتى 13 أغسطس، تزامنًا مع عام ا','["وشهد الأسبوع مشاركة 17 جهة عارضة، وتنظيم 6 جلسات رئيسية، و78 لقاءً رياديًا، وأقيمت فعالياته عبر مراكز دعم المنشآت في الرياض، وجدة، والخبر، والمدينة المنورة، إضافة إلى منطقة عسير في حاضنة \"ورك كورنر\" بالتعاون مع هيئة تطوير منطقة عسير، ومنطقة جازان في \"جادة 30\" التابعة لبنك التنمية الاجتماعية، ومنطقة القصيم في مقر الغرفة التجارية بالمنطقة، إلى جانب منطقة الباحة.","وسعى أسبوع الذكاء الاصطناعي إلى زيادة وعي رواد الأعمال وأصحاب المنشآت الصغيرة والمتوسطة بتطبيقات الذكاء الاصطناعي، وتعريفهم بكيفية توظيفها وتطوير المنتجات والخدمات مع رفع كفاءة الأعمال وتعزيز تنافسيتها، وشاركت \"سدايا\" عبر جلسة دعم الاستثمار في مجال الذكاء الاصطناعي من خلال المدير العام للإدارة العامة للاستثمار في \"سدايا\" هشام الشدي، وجناح مصاحب قدمت فيه عددًا من الحلول الرقمية حول البيانات والذكاء الاصطناعي، إضافة…","وفي إحدى جلسات الأسبوع أكد نائب المحافظ لقطاع التقنية في هيئة الاتصالات والفضاء والتقنية رائد الفايز، أهمية تبني تطبيقات الذكاء الاصطناعي والحوسبة السحابية في قطاع الأعمال، مشددًا على ضرورة ربط الاستخدام التقني بقيمة مضافة وعائد فعلي يرفع إنتاجية المنشآت ويحقق كفاءتها التشغيلية، مبيّنًا أن الحلول السحابية تسهم في تسريع الأعمال وتمكين المنشآت من الاستفادة من الخدمات المتقدمة دون الحاجة لتأسيس بنية تحتية تكاملية.","وسلّط الضوء على المكتسبات التي حققها القطاع التقني في المملكة، مشيرًا إلى قوة البنية التحتية وجاهزية السوق المحلي الذي يزخر بآلاف الشركات التقنية والمنتجات الوطنية المطوّرة في مجالات الذكاء الاصطناعي، إلى جانب الحضور القوي لكبار مقدمي الخدمات السحابية العالميين، داعيًا أصحاب المنشآت الصغيرة والمتوسطة إلى استثمار هذه الحلول المتاحة لتعزيز تنافسية منتجاتهم والوصول بها إلى المستويات الدولية."]','الذكاء الاصطناعي','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/HkaVYk0','https://sabq.org/article/HkaVYk0','','https://sabq.org/article/HkaVYk0','صحيفة سبق','السعودية','2026-08-13T12:35:00.000Z','2026-08-13T15:35:00.000Z','2026-08-14T16:24:35.934Z','https://media.sabq.org/news/2026/08/362685fc-b34f-4037-8984-27db1b1cef25/w1600.webp','/api/media/88e99249-5e19-42b5-bef0-9b2d40ebc64f','/api/media/88e99249-5e19-42b5-bef0-9b2d40ebc64f?variant=thumbnail','بمشاركة 40 جهة واستفادة 3900 شخص.. «منشآت» بالشراكة مع «سدايا» تختتم «أسبوع الذكاء الاصطناعي» بالرياض',1600,1066,'valid','published','archived','valid',96,'e98e33dd577f330f189463205f1603f6b30a5f8e75c986a54f13ffcc7ba9850c','cfc2e0b9c47eb2f96017c699730e6b97464d68d23bfeb98748a19c9fa2e0f335','محدّث','2026-08-14T16:24:35.934Z','2026-10-07T20:51:58.157Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة تطوير منطقة عسير ومنطقة","الاقتصاد والأسواق","التقنية والتحول الرقمي","جدة","عسير","جازان","الرياض","القصيم"]','["هيئة تطوير منطقة عسير ومنطقة","الاقتصاد والأسواق","التقنية والتحول الرقمي","المدينة المنورة"]','classified','','[{"category":"التقنية","score":8.5},{"category":"الاقتصاد","score":7},{"category":"الذكاء الاصطناعي","score":6}]','Active','2026-10-07T20:51:58.157Z',200,73,0,'source_article_available','',NULL,NULL,'body:07f77cda24332f045fd1d11f3a96c1ee40fe5eead154b7e4b4ec7a81d0d0a7e7','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8e765c0f-e256-423e-9e98-4299152b6d7f','news-8e765c0f-e256-423e-9e98-4299152b6d7f','في افتتاح الجولة الأولى من دوري روشن.. حزم الصمود يعبر محطة أبها بثنائية','في افتتاح الجوله الاولي من دوري روشن حزم الصمود يعبر محطه ابها بثنائيه','قص الفريق الكروي الأول بنادي الحزم شريط دوري روشن السعودي للموسم الجديد 2026-2027 بفوز ثمين على حساب مضيفه أبها بهدفين مقابل هدف، ضمن لقاءات الجولة الأولى للمسابقة.','["تقدم الحزم بهدف في الدقيقة 4 بواسطة عبدالعزيز الضويحي الذي نجح في تسجيل أول أهداف الموسم الجديد من روشن.","وعزز للحزم اللاعب أحمد الشمراني في الدقيقة 40، لينتهي الشوط الأول بتقدم الضيوف بثنائية نظيفة.","وتمكن أبها من تضييق الفارق في الدقيقة 64 عن طريق لاعبه محمد الدوسري، وباءت محاولات أصحاب الأرض في التعادل بالفشل."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/KVanxwO','https://sabq.org/article/KVanxwO','','https://sabq.org/article/KVanxwO','صحيفة سبق','السعودية','2026-08-13T12:51:00.000Z','2026-08-13T15:51:00.000Z','2026-08-14T16:24:35.968Z','https://media.sabq.org/news/2026/08/e81bbf25-b738-4ff6-9e47-f2ed4caaf7c7/w1600.webp','/api/media/8e765c0f-e256-423e-9e98-4299152b6d7f','/api/media/8e765c0f-e256-423e-9e98-4299152b6d7f?variant=thumbnail','في افتتاح الجولة الأولى من دوري روشن.. حزم الصمود يعبر محطة أبها بثنائية',1600,1600,'valid','published','archived','valid',99,'45ac9de9337361b016bedf90094c73cff4876911463fc8692bb23f79c0b27ce3','4f4a344db51cb7243a3c194ea2dc6b52554806a4c0fb39ba1312bd31655361fa','محدّث','2026-08-14T16:24:35.968Z','2026-10-07T20:51:55.410Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:51:55.410Z',200,75,0,'source_article_available','',NULL,NULL,'body:c3a8a8f829bf0f15fcb526432b2703c3e09ee52c3d9c10cfe43caca877bb8d04','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9102e622-c3bd-482e-bef6-bb696d03c72f','news-9102e622-c3bd-482e-bef6-bb696d03c72f','القادسية يحسم صفقة تجاني ريندرز من مانشستر سيتي','القادسيه يحسم صفقه تجاني ريندرز من مانشستر سيتي','حسم نادي القادسية السعودي صفقة مدوية في سوق الانتقالات الصيفية، بعد التوصل إلى اتفاق مع مانشستر سيتي للتعاقد مع الدولي الهولندي تيجاني رايندرز مقابل نحو 61 مليون يورو، وفقاً لما كشفه الصحفي المتخصص في صفقات الانتقالات فابريزيو رومانو.','["ونجحت إدارة القادسية في حسم الصفقة خلال الساعات الأخيرة، رغم وجود اهتمام من أندية أوروبية باللاعب، إذ ارتفعت قيمة الصفقة من نحو 60 مليون يورو وفق التقديرات الأولية إلى 61 مليوناً عقب التوصل إلى اتفاق نهائي بين الطرفين.","وتكتسب الصفقة أهمية خاصة، كون رايندرز لم يقضِ سوى موسم واحد مع مانشستر سيتي، الذي انتقل إليه في صيف 2025 قادماً من ميلان الإيطالي، قبل أن يوافق على الرحيل خلال فترة الانتقالات الحالية.","وخلال موسمه مع الفريق الإنجليزي، شارك لاعب الوسط في نحو 50 مباراة بمختلف المسابقات.","ويبلغ رايندرز من العمر 28 عاماً، وبدأ مسيرته الكروية في هولندا مع نادي بي إي سي زفوله، قبل الانتقال إلى ألكمار، تخللتها إعارة إلى فالفيك."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/pEd2uVk','https://sabq.org/article/pEd2uVk','','https://sabq.org/article/pEd2uVk','صحيفة سبق','السعودية','2026-08-13T12:17:00.000Z','2026-08-13T15:17:00.000Z','2026-08-14T16:24:36.908Z','https://media.sabq.org/news/2026/08/fba73b40-f1ae-4491-87ea-a96792ae89b7/w1024.webp','/api/media/9102e622-c3bd-482e-bef6-bb696d03c72f','/api/media/9102e622-c3bd-482e-bef6-bb696d03c72f?variant=thumbnail','القادسية يحسم صفقة تجاني ريندرز من مانشستر سيتي',1024,683,'valid','published','archived','valid',99,'fea4cf4b87e3958287a6b10b99226ff238959f518d097feb5a3e55c3c17e8c5d','1272947fcebe1e682f4ccda1f7d30586f65d0d8813b5c93f0b9c674e3581a1b9','محدّث','2026-08-14T16:24:36.908Z','2026-10-07T20:52:37.288Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"الصحة","score":0},{"category":"التعليم","score":0}]','Active','2026-10-07T20:52:37.288Z',200,76,0,'source_article_available','',NULL,NULL,'body:5d37df83232e09fba6ac46197f86c3efaf11c2e6d535bef3568512c36aa7ebf6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a3404a22-8d02-4aac-9db2-021fc576e38c','news-a3404a22-8d02-4aac-9db2-021fc576e38c','«شبكة الإمارات» ترصد أكثر من 800 شهاب في ذروة زخة «البرشاويات»','شبكه الامارات ترصد اكثر من 800 شهاب في ذروه زخه البرشاويات','وثّقت شبكة الإمارات لرصد الشهب والنيازك التابعة لمركز الفلك الدولي نشاطاً استثنائياً لزخة شهب «البرشاويات»، إذ التقطت خلال ليلة 12-13 أغسطس 2026م أكثر من 800 صورة لشهب اخترقت سماء الإمارات، معظمها تابع لهذه الزخة الفلكية البارزة.','["وأكد المهندس محمد شوكت عودة، مدير مركز الفلك الدولي وعضو منظمة الشهب الدولية، أن الشبكة تعمل بصورة آلية كاملة لتصوير الشهب فور ظهورها، وتتألف من ثلاث محطات موزّعة في مواقع مختلفة بصحراء أبوظبي، تحتوي كل منها على 17 كاميرا فيديو عالية الحساسية قادرة على رصد شهب حتى القدر 6.5 تقريباً.","وأوضح «عودة» أن الشبكة تمكّنت من رسم مدار 265 شهاباً أثناء دخوله الغلاف الجوي مساء الأمس، مشيراً إلى أن رسم المدار يعني تحديد العناصر المدارية للحبيبة الغبارية التي كانت تدور حول الشمس قبل اصطدامها بالأرض، وهو ما لا يتأتى إلا بتصوير الشهاب ذاته من أكثر من محطة في آنٍ واحد، ليُحسب موقعه بدقة عبر حسابات المثلثات.","وكشف أن تحليل العناصر المدارية أثبت أن 198 شهاباً من المرصودة تنتمي إلى زخة «البرشاويات»، جرى تصويرها خلال فترة الرصد الممتدة من نحو العاشرة مساءً حتى طلوع الفجر.","وكان ألمع شهاب رُصد مساء الأمس من القدر سالب 8.5، وهو لمعان يقارب القمر حين يكون أقل من نصف مكتمل بقليل، وقد ظهر في تمام الساعة 02:41:18 بالتوقيت المحلي."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/eHF_x2j','https://sabq.org/article/eHF_x2j','','https://sabq.org/article/eHF_x2j','فهد العتيبي','السعودية','2026-08-13T12:00:00.000Z','2026-08-13T15:00:00.000Z','2026-08-14T16:24:37.135Z','https://media.sabq.org/news/2026/08/5df396cb-788b-4dc8-99b9-5d5be16e0132/w1380.webp','/api/media/a3404a22-8d02-4aac-9db2-021fc576e38c','/api/media/a3404a22-8d02-4aac-9db2-021fc576e38c?variant=thumbnail','«شبكة الإمارات» ترصد أكثر من 800 شهاب في ذروة زخة «البرشاويات»',1380,1572,'valid','published','archived','valid',41,'48b9ee68891a6faa4651a53eea31d37221087690b54dfbefced99059625280bd','bfb8ac59c2da699afdc9a0a6a5897e22267687293da829de9602a0e54499a0fa','محدّث','2026-08-14T16:24:37.135Z','2026-10-07T20:52:37.307Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:52:37.307Z',200,80,0,'source_article_available','',NULL,NULL,'body:c2b28868182bd248b8a1f0f153276912f66da110999d2c7f9a3580a1a7f318d3','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('36a7697c-d957-4872-b4a4-4c68ad0a48f8','news-36a7697c-d957-4872-b4a4-4c68ad0a48f8','جدة.. إجازة مميزة على البحر الأحمر بين فخامة ريكسوس أبحر ومتعة مرجانة','جده اجازه مميزه علي البحر الاحمر بين فخامه ريكسوس ابحر ومتعه مرجانه','تتيح جدة العديد من الخيارات المتنوعة لقضاء الإجازات والاستمتاع بالواجهة البحرية للبحر الأحمر، من الشواطئ والأنشطة المائية إلى المطاعم والمرافق الترفيهية والمنتجعات التي توفر للزوار خيارات متعددة للإقامة والاسترخاء.','["وتبرز منتجعات ريكسوس في أبحر ومرجانة ضمن هذه الخيارات باعتبارها من الوجهات التي تجمع بين الإقامة والترفيه والخدمات المتكاملة في موقع ساحلي واحد.","ويأتي ريكسوس أبحر جدة في مقدمة هذه الخيارات، حيث يقع في خليج أبحر ويقدم مفهومًا مختلفًا للإقامة الشاطئية من خلال نظام شامل كليًا (Ultra All-Inclusive)، يتيح للزوار الاستفادة من مجموعة واسعة من الخدمات والمرافق ضمن الإقامة نفسها، بما يجعل المنتجع مناسبًا للعائلات والأفراد الباحثين عن قضاء عطلة تجمع بين الراحة والأنشطة الترفيهية.","ويضم المنتجع 250 وحدة سكنية بإطلالات بحرية، ما يمنح النزلاء فرصة للاستمتاع بأجواء البحر الأحمر من داخل أماكن الإقامة، إلى جانب مجموعة من المرافق والخدمات التي صُممت لتوفير خيارات متنوعة للزوار، سواء للراغبين في الاسترخاء أو الباحثين عن الأنشطة والتجارب البحرية.","وتشكل الطبيعة الساحلية جزءًا أساسيًا من تجربة الإقامة في ريكسوس أبحر، حيث يمكن للزوار الاستمتاع بالشاطئ والمياه والأنشطة المرتبطة بالبحر، إلى جانب قضاء أوقات هادئة بعيدًا عن صخب المدينة، مع إمكانية الجمع بين الإقامة في المنتجع واستكشاف ما توفره جدة من مطاعم ومراكز تسوق وفعاليات ومناطق ترفيهية."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/rX-1BJO','https://sabq.org/article/rX-1BJO','','https://sabq.org/article/rX-1BJO','صحيفة سبق','السعودية','2026-08-13T12:33:00.000Z','2026-08-13T15:34:00.000Z','2026-08-14T16:24:37.250Z','https://media.sabq.org/news/2026/08/6e7ab0a6-0ba8-4ca3-982a-ec3a67e49b68/w1600.webp','/api/media/36a7697c-d957-4872-b4a4-4c68ad0a48f8','/api/media/36a7697c-d957-4872-b4a4-4c68ad0a48f8?variant=thumbnail','جدة.. إجازة مميزة على البحر الأحمر بين فخامة ريكسوس أبحر ومتعة مرجانة',1600,900,'valid','published','archived','valid',46,'7343ce2f1f4d83a9793a706001a3cf34921d4b8d2f0eebc749cae167f5221e67','94338ad6cab7a64ad104bbb70a3168742e4f39e72e1c21f7254a8336e839c07b','محدّث','2026-08-14T16:24:37.250Z','2026-10-07T20:51:56.606Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["جدة"]','[]','manual_approved','below_category_threshold','[{"category":"الصحة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:51:56.606Z',200,76,0,'source_article_available','',NULL,NULL,'body:7f6fdacb2f3506e325afefa1e6065bfaa751e39ef28bc618b69fb7dc0103b777','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ad113723-50ac-4bdd-bfd0-464eb5ffd9bb','news-ad113723-50ac-4bdd-bfd0-464eb5ffd9bb','«أم القرى» تنشر تفاصيل اللائحة التنفيذية للمراقبة والالتزام بمعايير كفاءة وترشيد المياه','ام القري تنشر تفاصيل اللائحه التنفيذيه للمراقبه والالتزام بمعايير كفاءه وترشيد المياه','نشرت الجريدة الرسمية " أم القرى "، قرار اعتماد وزير البيئة والمياه والزراعة المهندس عبدالرحمن بن عبدالمحسن الفضلي اللائحة التنفيذية للمراقبة والالتزام بمعايير كفاءة وترشيد المياه.','["ووفق القرار يعد مخالفًا كلُّ من قام بأي من الأفعال التالية في القطاع الحضري. والتي جاءت كما يلي:","01 استخدام أدوات صحية غير مرشدة لكل أداة على سبيل المثال لا الحصر: خلاطات، صنابير مراوش شطافات صناديق طرد","02 العبث أو إزالة الجزء المرشد من الأدوات الصحية المرشدة لكل أداة)."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/g2pal4hoh','https://ajel.sa/local/g2pal4hoh','https://ajel.sa/local/g2pal4hoh','https://ajel.sa/local/g2pal4hoh','فريق التحرير','السعودية','2026-08-14T10:31:00.000Z','Wed, 07 Oct 2026 20:51:43 GMT','2026-08-14T18:26:04.805Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-ClEybgaw.jpg','/api/media/ad113723-50ac-4bdd-bfd0-464eb5ffd9bb','/api/media/ad113723-50ac-4bdd-bfd0-464eb5ffd9bb?variant=thumbnail','فريق التحرير',1200,675,'valid','published','archived','valid',40,'b3def3600cec20b7fb48e38c48c5bff165d45253a1582997ea9c5f2109614013','41e6272631f359d35b732131bec57e4428776f792f1ad7145414c493f5ff7619',NULL,'2026-08-14T18:26:04.805Z','2026-10-07T20:51:44.574Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Updated','2026-10-07T20:51:44.574Z',200,78,0,'source_content_changed','',NULL,NULL,'body:b1f709534701b5d4cce690faf87f48f2803fe0c62f5b58a56341e6db9a5f6c46','Wed, 07 Oct 2026 20:51:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7418caf6-f34e-48ec-bbfc-75045325c5a7','news-7418caf6-f34e-48ec-bbfc-75045325c5a7','القناة 13 الإسرائيلية: الولايات المتحدة وضعت فيتو على طلب إسرائيلي بقصف أهداف في سوريا','القناه 13 الاسرائيليه الولايات المتحده وضعت فيتو علي طلب اسرائيلي بقصف اهداف في سوريا','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية في الوقت الذي تشهد فيه مناطق الجنوب السوري تصعيدا ميدانيا وتوغلات إسرائيلية متكررة؛ وضعت الولايات المتحدة "فيتو" على طلب إسرائيلي لتنفيذ ضربات ضد أهداف في سوريا .','["في الوقت الذي تشهد فيه مناطق الجنوب السوري تصعيدا ميدانيا وتوغلات إسرائيلية متكررة؛ وضعت الولايات المتحدة \"فيتو\" على طلب إسرائيلي لتنفيذ ضربات ضد أهداف في سوريا .","وأفادت القناة 13 الإسرائيلية، اليوم، أن واشنطن رفضت طلبا إسرائيليا بشن غارات على أهداف داخل الأراضي السورية، من دون أن توضح طبيعة الأهداف التي طلب الاحتلال الإسرائيلي استهدافها.","ويتزامن ذلك مع تصعيد ميداني في جنوب سوريا، حيث أفاد التلفزيون السوري بأن القوات الإسرائيلية احتجزت عدداً من المواطنين بعد توغلها في ريف القنيطرة وإقامة حاجز للتفتيش. وفي ريف درعا الغربي، أطلقت القوات الإسرائيلية، الجمعة، نيران أسلحتها الرشاشة باتجاه منازل في قرية معرية."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/yr7pyq2rt','https://ajel.sa/international/yr7pyq2rt','https://ajel.sa/international/yr7pyq2rt','https://ajel.sa/international/yr7pyq2rt','فريق التحرير','السعودية','2026-08-14T12:59:00.000Z','Wed, 07 Oct 2026 20:50:54 GMT','2026-08-14T21:26:33.987Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-m6uECgSx.jpg','/api/media/7418caf6-f34e-48ec-bbfc-75045325c5a7','/api/media/7418caf6-f34e-48ec-bbfc-75045325c5a7?variant=thumbnail','القناة 13 الإسرائيلية: الولايات المتحدة وضعت فيتو على طلب إسرائيلي بقصف أهداف في سوريا',1200,675,'valid','published','archived','valid',99,'3394852dd132c5d0157cf744d3cef85cd351e629a33ed4705483674290f32f5d','e2910974b8c046b0a317641c4440acba8ed74df255cc395ee40b3f2a05d304b8',NULL,'2026-08-14T21:26:33.987Z','2026-10-07T20:50:56.175Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["سوريا","الولايات المتحدة"]','["الولايات المتحدة"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"الصحة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:50:56.175Z',200,81,0,'source_content_changed','',NULL,NULL,'body:f81454ef45ea96fca27320fe65e75028e9556d927de1982a29e065dc8c561ab9','Wed, 07 Oct 2026 20:50:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('feb9e402-bf75-44ae-b165-dc73860db9b6','news-feb9e402-bf75-44ae-b165-dc73860db9b6','بمشاركة تريزيجيه وهاتريك ديمبلي.. الرياض يسقط أمام الاتفاق في الدوري السعودي','بمشاركه تريزيجيه وهاتريك ديمبلي الرياض يسقط امام الاتفاق في الدوري السعودي','سقط فريق الرياض في فخ الخسارة أمام الاتفاق، بأربعة أهداف مقابل هدفين اثنين، ضمن منافسات بطولة الدوري السعودي للمحترفين في الموسم الجديد 2026/2027.','["وحل فريق الرياض ضيفًا على نظيره الاتفاق، مساء اليوم الجمعة، ضمن منافسات الجولة الأولى من عمر مسابقة الدوري السعودي للمحترفين، على ملعب \"إيجو\" في الخُبر.","وشارك تريزيجيه بشكل أساسي مع الرياض، منذ الدقيقة الأولى وحتى نهاية اللقاء، لكنه أخفق في تقديم الإضافة الهجومية المرتقبة أمام الاتفاق.","الرياض يسقط أمام الاتفاق بمشاركة تريزيجيه ضم تشكيل الرياض الرسمي أمام الاتفاق: \"بوريان - سلطان - أباسكال - سليمان - فهد - الخيبري - فيكتور - مينساه - تريزيجيه - أوكو - لياندرو\".","بينما ضم تشكيل الاتفاق: \"بالجوش - هندري - خطيب - العتيبي - العليان - دودا - ميدران - الشمري - الغامدي - ديمبيلي - جلوشيفيتش\"."]','الرياضة','','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://www.yallakora.com/ksa-league/3040/news/562275/%D8%A8%D9%85%D8%B4%D8%A7%D8%B1%D9%83%D8%A9-%D8%AA%D8%B1%D9%8A%D8%B2%D9%8A%D8%AC%D9%8A%D9%87-%D9%88%D9%87%D8%A7%D8%AA%D8%B1%D9%8A%D9%83-%D8%AF%D9%8A%D9%85%D8%A8%D9%84%D9%8A-%D8%A7%D9%84%D8%B1%D9%8A%D8%A7%D8%B6-%D9%8A%D8%B3%D9%82%D8%B7-%D8%A3%D9%85%D8%A7%D9%85-%D8%A7%D9%84%D8%A7%D8%AA%D9%81%D8%A7%D9%82-%D9%81%D9%8A-%D8%A7%D9%84%D8%AF%D9%88%D8%B1%D9%8A-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A','https://www.yallakora.com/ksa-league/3040/news/562275/%d8%a8%d9%85%d8%b4%d8%a7%d8%b1%d9%83%d8%a9-%d8%aa%d8%b1%d9%8a%d8%b2%d9%8a%d8%ac%d9%8a%d9%87-%d9%88%d9%87%d8%a7%d8%aa%d8%b1%d9%8a%d9%83-%d8%af%d9%8a%d9%85%d8%a8%d9%84%d9%8a-%d8%a7%d9%84%d8%b1%d9%8a%d8%a7%d8%b6-%d9%8a%d8%b3%d9%82%d8%b7-%d8%a3%d9%85%d8%a7%d9%85-%d8%a7%d9%84%d8%a7%d8%aa%d9%81%d8%a7%d9%82-%d9%81%d9%8a-%d8%a7%d9%84%d8%af%d9%88%d8%b1%d9%8a-%d8%a7%d9%84%d8%b3%d8%b9%d9%88%d8%af%d9%8a','','','عمر عبد العزيز','السعودية','2026-08-14T17:09:00.000Z','Wed, 07 Oct 2026 20:50:42 GMT','2026-08-14T21:31:22.392Z','https://mediayk.gemini.media/img/yallakora/xlarge/2026/8/14/image-2026-08-14t225640-4002026_8_14_22_55.webp','/api/media/feb9e402-bf75-44ae-b165-dc73860db9b6','/api/media/feb9e402-bf75-44ae-b165-dc73860db9b6?variant=thumbnail','بمشاركة تريزيجيه وهاتريك ديمبلي.. الرياض يسقط أمام الاتفاق في الدوري السعودي',1200,798,'valid','published','archived','valid',100,'44396abce04b2239e2f1dbe514334f6cd4e8630643cc9895d76d37a8e32762d8','8eb992e5fc436b854595a440e2b2857de5745b5a1bbe53b3b0fa8608ec3e6558',NULL,'2026-08-14T21:31:22.392Z','2026-10-07T20:50:44.103Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','manual_approved','','[]','Updated','2026-10-07T20:50:44.103Z',200,86,0,'source_content_changed','',NULL,NULL,'body:d1523fdd697ba4a2ee0a0b8ad98feca2cdbeb353183789d3698580e7258e9891','Wed, 07 Oct 2026 20:50:42 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('36f3b6df-6870-4b95-96e2-397e0b07c771','news-36f3b6df-6870-4b95-96e2-397e0b07c771','ترامب يقول إنه سيعلن مضيق هرمز "أرضاً أمريكية" ومقتل ثمانية إثر هجوم على مينا المخا اليمني','ترامب يقول انه سيعلن مضيق هرمز ارضا امريكيه ومقتل ثمانيه اثر هجوم علي مينا المخا اليمني','قال الرئيس الأمريكي دونالد ترامب، الجمعة، إنه سيعلن "قريباً" مضيق هرمز جزءاً من أراضي الولايات المتحدة، معتبراً أن إيران تتعرض لهزيمة قاسية، في وقت امتد فيه التصعيد الإقليمي إلى اليمن والسعودية، مع هجمات للحوثيين على ميناء المخا ومنشآت نفطية.','["وقال ترامب ضاحكاً، خلال تجمع سياسي في أكاديمية للشرطة بولاية نيويورك: \"بعد أن ننتهي من هزيمة إيران، التي تتعرض لهزيمة قاسية للغاية، سأعلن قريباً مضيق هرمز أرضاً تابعة للولايات المتحدة\".","وجاءت تصريحات ترامب في ظل استمرار حالة الجمود بين واشنطن وطهران بشأن المضيق، الذي تمر عبره كميات كبيرة من إمدادات الطاقة والسلع في العالم.","وفرضت إيران سيطرة على جزء كبير من المضيق، ومنعت مرور عدد كبير من سفن الشحن المدنية، فيما فرضت البحرية الأمريكية حصاراً على الموانئ الإيرانية في محاولة لإضعاف اقتصاد البلاد.","وقال ترامب أمام حشد من أنصاره وعناصر الشرطة: \"نحن نفرض الحصار. لا تمر أي سفينة إلا إذا أردنا لها أن تمر\"."]','السياسة','السعودية','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://www.bbc.com/arabic/articles/cn4nr0j8prko','https://www.bbc.com/arabic/articles/cn4nr0j8prko','CBMiXEFVX3lxTE9YdWwwdHF5YlR6NHNlMmdNZUNta2xITGFWZzdraDg5V1RBWHNkaWc2V2lhU2pCTmZ3bVhZNFpJRTIxQTZSU0J5ZW1hZGZrcU5CczkzNjczakpRWXND0gFiQVVfeXFMTTdDalhRZUV6MDdBdnRMUU9hVVlCZWZzWmRsZ09Wa3ZJSk9oRnBtNHptSG1IOXJOVEZtM3lBLWhNNTI2ay0wQk42NkJKV29vSTN4NlhDRlROSG9uQWpjWERvR1E','CBMiXEFVX3lxTE9YdWwwdHF5YlR6NHNlMmdNZUNta2xITGFWZzdraDg5V1RBWHNkaWc2V2lhU2pCTmZ3bVhZNFpJRTIxQTZSU0J5ZW1hZGZrcU5CczkzNjczakpRWXND0gFiQVVfeXFMTTdDalhRZUV6MDdBdnRMUU9hVVlCZWZzWmRsZ09Wa3ZJSk9oRnBtNHptSG1IOXJOVEZtM3lBLWhNNTI2ay0wQk42NkJKV29vSTN4NlhDRlROSG9uQWpjWERvR1E','BBC News عربي','السعودية','2026-08-14T12:52:00.000Z','2026-08-14T17:47:00.000Z','2026-08-14T21:31:23.573Z','https://ichef.bbci.co.uk/news/1200/branded_arabic/075a/live/7bf6f8e0-981e-11f1-b03a-f5b5b6d6dfc0.jpg','/api/media/36f3b6df-6870-4b95-96e2-397e0b07c771','/api/media/36f3b6df-6870-4b95-96e2-397e0b07c771?variant=thumbnail','الرئيس الأمريكي دونالد ترامب يغادر طائرة الرئاسة "إير فورس ون" في مطار نيوارك ليبرتي الدولي في 7 أغسطس/آب 2026 في نيوارك، نيو جيرسي. يقضي الرئيس ترامب عطلة نهاية الأسبوع في نادي ترامب الوطني للغولف في بيدمينستر.',1024,576,'valid','published','archived','valid',89,'49f2568a9a9aa2b9770275365a4c305364b1434173fe9582dc9153d9e4fc066a','9d66bae52c572604b8ef9f0d64d7602623b4c73ed6e1f38698eda32d4efebaba',NULL,'2026-08-14T21:31:23.573Z','2026-10-07T20:51:01.880Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الاقتصاد والأسواق","اليمن","إيران"]','["الطاقة والنفط","الاقتصاد والأسواق"]','manual_approved','','[]','Active','2026-10-07T20:51:01.880Z',200,77,0,'source_article_available','',NULL,NULL,'body:bf980a3c740b28912edc53633e80e8bf84f6611ec71e4ae2c0793ea57b9ada19','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b078324b-5e60-4919-9a54-02b04231831f','news-b078324b-5e60-4919-9a54-02b04231831f','بالفيديو.. هاتريك ركلات جزاء ينقذ الهلال من أول فخ في دوري روشن','بالفيديو هاتريك ركلات جزاء ينقذ الهلال من اول فخ في دوري روشن','أفلت الهلال من أول فخ في الموسم الجديد من دوري روشن السعودي (2026-2027)، وذلك بفضل هاتريك ركلات جزاء.','["وفاز الهلال على الفيصلي بنتيجة 4-2 ، خلال المباراة التي جمعت بينهما، اليوم الجمعة، على ملعب المملكة أرينا، في الجولة الأولى من دوري روشن.","الغريب أن الهلال لم يسجل سوى هدف وحيد من اللعب المفتوح، وهو الهدف الثاني عن طريق الجناح البرازيلي مالكوم، وذلك في الدقيقة 26 من عمر المباراة.","في المقابل، سجل المهاجم الفرنسي كريم بنزيما الهدف الأول لـ\"الزعيم\" في الدقيقة 19 من ركلة جزاء، ولاعب الوسط البرتغالي روبين نيفيز الهدفين الثالث والرابع في الدقيقتين 28 و82، من ركلتي جزاء أيضًا.","ورغم أنه أنهى الشوط الأول متقدمًا بثلاثية نظيفة، فقد كاد الهلال أن يفقد المباراة، بعدما سجل الفيصلي هدفين متتاليين، عن طريق ألكسندر ميندي وثيو بونجوندا في الدقيقتين 59 و64."]','الرياضة','','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://www.kooora.com/%D9%83%D8%B1%D8%A9-%D9%82%D8%AF%D9%85/%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D8%A8%D8%A7%D9%84%D9%81%D9%8A%D8%AF%D9%8A%D9%88--%D9%87%D8%A7%D8%AA%D8%B1%D9%8A%D9%83-%D8%B1%D9%83%D9%84%D8%A7%D8%AA-%D8%AC%D8%B2%D8%A7%D8%A1-%D9%8A%D9%86%D9%82%D8%B0-%D8%A7%D9%84%D9%87%D9%84%D8%A7%D9%84-%D9%85%D9%86-%D8%A7%D9%94%D9%88%D9%84-%D9%81%D8%AE-%D9%81%D9%8A-%D8%AF%D9%88%D8%B1%D9%8A-%D8%B1%D9%88%D8%B4%D9%86/blt6d21bab685d8ec2e','https://www.kooora.com/%D9%83%D8%B1%D8%A9-%D9%82%D8%AF%D9%85/%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1/%D8%A8%D8%A7%D9%84%D9%81%D9%8A%D8%AF%D9%8A%D9%88--%D9%87%D8%A7%D8%AA%D8%B1%D9%8A%D9%83-%D8%B1%D9%83%D9%84%D8%A7%D8%AA-%D8%AC%D8%B2%D8%A7%D8%A1-%D9%8A%D9%86%D9%82%D8%B0-%D8%A7%D9%84%D9%87%D9%84%D8%A7%D9%84-%D9%85%D9%86-%D8%A7%D9%94%D9%88%D9%84-%D9%81%D8%AE-%D9%81%D9%8A-%D8%AF%D9%88%D8%B1%D9%8A-%D8%B1%D9%88%D8%B4%D9%86/blt6d21bab685d8ec2e','','','','السعودية','2026-08-14T14:03:00.000Z','Wed, 07 Oct 2026 20:51:04 GMT','2026-08-14T21:31:30.291Z','https://assets.kooora.com/images/v3/imago-sport-1081064779/crop/MM5DKMBQGQ5DEOBRGU5G433XMU5DAORSGYYQ====/imago-image.jpeg','/api/media/b078324b-5e60-4919-9a54-02b04231831f','/api/media/b078324b-5e60-4919-9a54-02b04231831f?variant=thumbnail','بالفيديو.. هاتريك ركلات جزاء ينقذ الهلال من أول فخ في دوري روشن',5004,2815,'valid','published','archived','valid',100,'f3533ad31dfb875261cfd8624bc507ca615244863f27bd7139e1c43679c15864','1b1a5a8a9c6fa2734e57833cab3e2d1597a8e97a708c0064c2cd78fe22432a4a',NULL,'2026-08-14T21:31:30.291Z','2026-10-07T20:51:06.003Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','manual_approved','','[]','Updated','2026-10-07T20:51:06.003Z',200,76,0,'source_content_changed','',NULL,NULL,'"n7wqw7aopn4in6"','Wed, 07 Oct 2026 20:51:04 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2fc3ade2-fc59-40e2-99ef-5c9b964b570a','news-2fc3ade2-fc59-40e2-99ef-5c9b964b570a','أربعة أيام على صهوة الحلم.. عبدالرحمن الراجحي يمثل المملكة في مونديال الفروسية بألمانيا','اربعه ايام علي صهوه الحلم عبدالرحمن الراجحي يمثل المملكه في مونديال الفروسيه بالمانيا','يشد الفارس الأولمبي السعودي عبدالرحمن بدر الراجحي الرحال إلى مدينة آخن الألمانية، ممثلاً للمملكة في منافسات قفز الحواجز ضمن بطولة العالم للفروسية 2026، التي تنطلق الأربعاء المقبل 19 أغسطس وتتواصل حتى 23 منه، على الميدان الرئيسي لأعرق ملاعب الفروسية في العالم.','["ويفتتح الراجحي مشواره الأربعاء بالجولة الأولى التأهيلية للفردي والفرق في العاشرة والربع صباحاً بتوقيت السعودية، على أن يخوض الخميس والجمعة منافسات الجولة الثانية للفردي ونهائي الفرق (التاسعة و45 دقيقة صباحاً، ثم السابعة و35 دقيقة مساءً بتوقيت المملكة)، قبل أن تُختتم البطولة الأحد 23 أغسطس بالنهائي الفردي الكبير في الثالثة وخمس دقائق عصراً بتوقيت السعودية — حيث يحلم كل فرسان العالم بالوقوف على منصته.","جدول منافسات الراجحي (بتوقيت السعودية): الأربعاء 19 أغسطس — 10:15 صباحاً : الجولة الأولى التأهيلية (فرق وفردي) الخميس 20 أغسطس — 9:45 صباحاً : الجولة الثانية الفردية ونهائي الفرق الجمعة 21 أغسطس — 7:35 مساءً : استكمال الجولة الثانية ونهائي الفرق الأحد 23 أغسطس — 3:05 عصراً : النهائي الفردي وتُنقل المنافسات مباشرةً عبر قنوات «بي إن سبورت» و«CNBC Global» ومنصتي « FEI.TV » و« ClipMyHorse.tv »، فيما يترقب عشاق الفروسية…"]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/75k0f8y','https://sabq.org/article/75k0f8y','','https://sabq.org/article/75k0f8y','صحيفة سبق','السعودية','2026-08-14T08:19:00.000Z','2026-08-14T11:21:00.000Z','2026-08-14T21:31:36.647Z','https://media.sabq.org/news/2026/08/b5f0c701-3bd7-405c-b209-b3c41a39c5d3/w720.webp','/api/media/2fc3ade2-fc59-40e2-99ef-5c9b964b570a','/api/media/2fc3ade2-fc59-40e2-99ef-5c9b964b570a?variant=thumbnail','أربعة أيام على صهوة الحلم.. عبدالرحمن الراجحي يمثل المملكة في مونديال الفروسية بألمانيا',720,432,'valid','published','archived','valid',52,'9d1023f6a948507e4600a91196527b976c2e9190b22cae1ed31bb84945c249eb','23cf9bfe775c812aed9c5c4cece78cb46c9247b0d9c509a3eaf8564303471e52','محدّث','2026-08-14T21:31:36.647Z','2026-10-07T20:51:00.322Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"العالم","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T20:51:00.322Z',200,85,0,'source_article_available','',NULL,NULL,'body:618e09d40e1f72c12a4a6ce234792963a06ead079e552617592af249a28cd77c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f9d137cb-c139-4de0-8fe9-25e4eb329f63','news-f9d137cb-c139-4de0-8fe9-25e4eb329f63','بـ60 مليار دولار.. «سبيس إكس» تُتم رسمياً الاستحواذ على «كيرسور» في واحدة من أضخم صفقات الذكاء الاصطناعي','بـ60 مليار دولار سبيس اكس تتم رسميا الاستحواذ علي كيرسور في واحده من اضخم صفقات الذكاء الاصطناعي','أتمت شركة «سبيس إكس» (Space Exploration Technologies) رسمياً استحواذها على شركة «أنيسفير» المطوّرة لأداة البرمجة بالذكاء الاصطناعي «كيرسور»، في صفقة أسهم تقوم على قيمة ضمنية تبلغ 60 مليار دولار (نحو 225 مليار ريال)، بحسب إفصاح رسمي (نموذج 8-K) أودعته الشركة لدى هيئة الأوراق المالية والبورصات الأمريكية، وأصبحت الصفقة نافذة اليوم الجمعة 14 أغسطس 2026.','["وبموجب هيكل الصفقة، اندمجت «إكس 67» — الشركة التابعة لسبيس إكس والمنشأة لغرض الاستحواذ — في «أنيسفير»، لتبقى الأخيرة كياناً قائماً بوصفها شركة تابعة مملوكة بالكامل لسبيس إكس، مع احتفاظ «كيرسور» بعلامتها.","تفاصيل التحويل وجرى تحويل الأسهم العادية والممتازة لـ«كيرسور» إلى حق في الحصول على نحو 389.3 مليون سهم من أسهم سبيس إكس من الفئة (أ)، فيما حُوّلت وحدات الأسهم المقيدة المستحقة إلى نحو 1.75 مليون سهم إضافي قبل الاستقطاعات الضريبية، على أن تُدفع كسور الأسهم نقداً.","كما تولت سبيس إكس التزامات الحوافز غير المستحقة؛ إذ حُوّلت وحدات الأسهم المقيدة غير المستحقة إلى نحو 29.1 مليون وحدة من وحدات سبيس إكس، وخيارات شراء الأسهم إلى نحو 44.4 مليون خيار على أسهم الفئة (أ).","واستند سعر التحويل إلى القيمة الضمنية البالغة 60 مليار دولار مقسومةً على المتوسط المرجح بحجم التداول لسعر إغلاق سهم سبيس إكس «SPCX» في جلسات التداول السبع السابقة للإتمام، فيما صدرت الأسهم بموجب إعفاء التسجيل المنصوص عليه في المادة 4(a)(2) باعتبارها معاملة لا تنطوي على طرح عام."]','الذكاء الاصطناعي','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/hxj9v0m','https://sabq.org/article/hxj9v0m','','https://sabq.org/article/hxj9v0m','صحيفة سبق','السعودية','2026-08-14T08:16:00.000Z','2026-08-14T11:18:00.000Z','2026-08-14T21:31:37.463Z','https://media.sabq.org/news/2026/08/f17daa79-f907-4e20-9a29-753f73c28181/w1600.webp','/api/media/f9d137cb-c139-4de0-8fe9-25e4eb329f63','/api/media/f9d137cb-c139-4de0-8fe9-25e4eb329f63?variant=thumbnail','بـ60 مليار دولار.. «سبيس إكس» تُتم رسمياً الاستحواذ على «كيرسور» في واحدة من أضخم صفقات الذكاء الاصطناعي',1600,761,'valid','published','archived','valid',40,'c342a2df193f78fba0e7fcd355702dd17c90af726440f707175b657042bb61fd','9341908542cf80d0707ad361eac8be63e4cda89992e66fa06a2974a6bcca5a27','محدّث','2026-08-14T21:31:37.463Z','2026-10-07T20:50:51.514Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة تابعة مملوكة بالكامل لسبيس","الاقتصاد والأسواق"]','["شركة تابعة مملوكة بالكامل لسبيس","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":1.5},{"category":"العالم","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:50:51.514Z',200,83,0,'source_article_available','',NULL,NULL,'body:45857b449b019ff56da989e25a4f0ac1c44eba3710bb587106a77d7f7bf9ecde','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('19301550-ab3f-42ed-b300-cdd6125c8d20','news-19301550-ab3f-42ed-b300-cdd6125c8d20','هولندي أسّس مزرعة صقور بعد شغف بدأ في المدينة المنورة','هولندي اسس مزرعه صقور بعد شغف بدا في المدينه المنوره','قاد شغفٌ بدأ قبل أربعة أعوام في المدينة المنورة الهولنديَّ «سام» إلى عالم الصقارة؛ إذ أمضى ستة أشهر في المملكة العربية السعودية لتعلُّم اللغة العربية، قبل أن يعود إلى بلاده محمَّلاً بإعجاب متنامٍ بهذا الموروث الأصيل، تحوَّل لاحقاً إلى اهتمام عملي دفعه إلى تأسيس مزرعة متخصصة لإنتاج الصقور.','["وأوضح «سام» أن مشاركته الحالية في المزاد الدولي لمزارع إنتاج الصقور هي الثالثة على التوالي؛ إذ استهلَّ حضوره بأربعة صقور، ثم شارك العام الماضي بسبعة صقور، فيما يعود هذا العام بأربعة صقور جديدة، مواصلاً مسيرةً ارتبطت بدايتها بزيارته للمملكة وولعه بفن الصقارة.","وامتدت تجربته هذا العام لتشمل أسرته، التي اصطحبها معه إلى المملكة للتعرف عن قرب على المزاد وما تشهده المملكة من تطور متسارع، مشيراً إلى استمتاع أفراد أسرته بالتجربة وبما يجمعه المزاد من موروث أصيل وحضور دولي متميز.","وأشاد «سام» بما شهده المزاد هذا العام من ارتقاء ملحوظ في مستوى التنظيم، مؤكداً أن الاحترافية التي يلمسها تعكس الجهود المبذولة لاستقطاب المنتجين من مختلف دول العالم وتعزيز حضورهم في هذا المحفل المتخصص.","وثمَّن دعم المركز الوطني للصقور للمنتجين المشاركين وما يوفره من خدمات متكاملة، مشيراً إلى أن هذه الجهود أسهمت في توسيع قاعدة المشاركة الدولية، وتهيئة بيئة جاذبة للمزارع الراغبة في الوصول إلى السوق السعودية والتعرف على احتياجاتها."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/bwqnbcb','https://sabq.org/article/bwqnbcb','','https://sabq.org/article/bwqnbcb','صحيفة سبق','السعودية','2026-08-14T08:03:00.000Z','2026-08-14T11:04:00.000Z','2026-08-14T21:31:37.820Z','https://media.sabq.org/news/2026/08/81f97ff9-72fd-4675-a676-42bda9b8f729/w1600.webp','/api/media/19301550-ab3f-42ed-b300-cdd6125c8d20','/api/media/19301550-ab3f-42ed-b300-cdd6125c8d20?variant=thumbnail','هولندي أسّس مزرعة صقور بعد شغف بدأ في المدينة المنورة',1600,1066,'valid','published','archived','valid',44,'bec406fd9ccc50de65f9c01eaadaf9a06594e552786d283496197d97c0d3268d','bd0cc581e8ed750b5184b0e6ba55a69c52c6bd6a7a46b6cb35f9608a13babcdb','محدّث','2026-08-14T21:31:37.820Z','2026-10-07T20:51:37.261Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","المدينة المنورة"]','["الاقتصاد والأسواق","المدينة المنورة"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":3},{"category":"الاقتصاد","score":1.5},{"category":"الثقافة","score":1.5}]','Active','2026-10-07T20:51:37.261Z',200,82,0,'source_article_available','',NULL,NULL,'body:d407eb4b6ebc4555835403f1ef5ec53235c0a8b0519f7d0955cbd3a46dab5070','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c846ec77-6bc7-4b91-b843-4dd989d43fef','news-c846ec77-6bc7-4b91-b843-4dd989d43fef','163 كجم من القات و87 ألف قرص محظور.. حرس الحدود يُحبط ثلاث محاولات تهريب في عسير وجازان','163 كجم من القات و87 الف قرص محظور حرس الحدود يحبط ثلاث محاولات تهريب في عسير وجازان','أحبطت الدوريات البرية لحرس الحدود ثلاث محاولات تهريب في منطقتي عسير وجازان خلال يوم واحد، أسفرت عن ضبط 163 كيلوجراماً من نبات القات المخدر و87 ألف قرص من الأقراص الخاضعة لتنظيم التداول الطبي، والقبض على سبعة مخالفين لنظام أمن الحدود.','["ففي قطاع الربوعة بمنطقة عسير ، قبضت الدوريات على ثلاثة مخالفين لنظام أمن الحدود من الجنسية الإثيوبية، لتهريبهم 63 كيلوجراماً من نبات القات المخدر.","وفي قطاع الدائر بمنطقة جازان ، أوقفت الدوريات أربعة مخالفين من الجنسية الإثيوبية أيضاً، لتهريبهم 100 كيلوجرام من النبات المخدر ذاته.","وفي القطاع نفسه، أحبطت الدوريات محاولة تهريب 87 ألف قرص خاضع لتنظيم التداول الطبي.","وأوضحت المديرية العامة لحرس الحدود أنه جرى استكمال الإجراءات النظامية الأولية بحق المقبوض عليهم، وتسليمهم مع المضبوطات كافة إلى جهة الاختصاص لاتخاذ الإجراءات اللازمة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/4c8k2xp','https://sabq.org/article/4c8k2xp','','https://sabq.org/article/4c8k2xp','صحيفة سبق','السعودية','2026-08-14T06:19:00.000Z','2026-08-14T09:20:00.000Z','2026-08-14T21:31:38.833Z','https://media.sabq.org/news/2026/08/c1d1d2ef-9cd6-4033-9d06-971a3b0c9376/w1200.webp','/api/media/c846ec77-6bc7-4b91-b843-4dd989d43fef','/api/media/c846ec77-6bc7-4b91-b843-4dd989d43fef?variant=thumbnail','163 كجم من القات و87 ألف قرص محظور.. حرس الحدود يُحبط ثلاث محاولات تهريب في عسير وجازان',1200,675,'valid','published','archived','valid',98,'397975c1db4a01994ccd912d7636b887c6dce849984ee204f123370bfe55c868','8ccb703682136e5b804e2feda8ad0544204d1e2d6b1a8bd9018d1252cf5e46b1','محدّث','2026-08-14T21:31:38.833Z','2026-10-07T20:51:37.266Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","عسير","جازان"]','["الرياضة السعودية"]','classified','','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T20:51:37.266Z',200,75,0,'source_article_available','',NULL,NULL,'body:a79ea24e941f93d27594d728ebed8a2ad04617b5464f917c691a90530d9a31e4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('16a946c0-2067-4349-9644-9b7d8eb1d78c','news-16a946c0-2067-4349-9644-9b7d8eb1d78c','في الجوف والشرقية والقصيم.. «مكافحة المخدرات» تطيح بخمسة مروجين للحشيش و«الشبو» والهيروين والأقراص المحظورة','في الجوف والشرقيه والقصيم مكافحه المخدرات تطيح بخمسه مروجين للحشيش و الشبو والهيروين والاقراص المحظوره','كثّفت المديرية العامة لمكافحة المخدرات ضرباتها الاستباقية لشبكات الترويج، معلنةً اليوم القبض على خمسة مروجين في ثلاث مناطق مختلفة من المملكة، ضُبطت بحوزتهم مواد مخدرة متنوعة شملت الحشيش والهيروين والميثامفيتامين (الشبو) وأقراصاً خاضعة لتنظيم التداول الطبي.','["ففي منطقة الجوف ، قبضت المديرية على مواطنَين لترويجهما كيلوجرامين من مادة الحشيش المخدر.","وفي المنطقة الشرقية ، أطاحت بمقيمَين من الجنسية البنجلاديشية لترويجهما مادتي الهيروين والميثامفيتامين (الشبو) المخدرتين.","وفي منطقة القصيم ، قبضت على مواطن روّج أقراصاً خاضعة لتنظيم التداول الطبي.","وأوضحت «مكافحة المخدرات»، عبر حسابها في منصة «إكس»، أنه جرى إيقاف المقبوض عليهم جميعاً واتخاذ الإجراءات النظامية بحقهم، وإحالتهم إلى النيابة العامة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/09rzo7e','https://sabq.org/article/09rzo7e','','https://sabq.org/article/09rzo7e','صحيفة سبق','السعودية','2026-08-14T06:18:00.000Z','2026-08-14T09:18:00.000Z','2026-08-14T21:31:38.845Z','https://media.sabq.org/news/2026/08/db8505d9-90f6-4826-9e8d-ca9447b42f9c/w1200.webp','/api/media/16a946c0-2067-4349-9644-9b7d8eb1d78c','/api/media/16a946c0-2067-4349-9644-9b7d8eb1d78c?variant=thumbnail','في الجوف والشرقية والقصيم.. «مكافحة المخدرات» تطيح بخمسة مروجين للحشيش و«الشبو» والهيروين والأقراص المحظورة',1200,675,'valid','published','archived','valid',96,'62808599d5a6e19fe3372638e162fe4174b003b7164dae99dba141f2142a1dda','f6b50ece79b767b313efd4b2a14334aabfb98876ca5f1767f739e1ab7bea8ad7','محدّث','2026-08-14T21:31:38.845Z','2026-10-07T20:51:02.609Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الجوف","القصيم"]','[]','classified','','[{"category":"التقنية","score":3.5},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T20:51:02.609Z',200,79,0,'source_article_available','',NULL,NULL,'body:b08679dda739411948451ddfc529c82fbd96070113a452709c5f13bb18c02c2b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f533b124-e6c8-4491-a633-411b3df750cf','news-f533b124-e6c8-4491-a633-411b3df750cf','صعود تاريخي لسلة الفاروق إلى الممتاز واعتماد هوية بصرية جديدة يعززان طموحات النادي','صعود تاريخي لسله الفاروق الي الممتاز واعتماد هويه بصريه جديده يعززان طموحات النادي','حقق نادي الفاروق الرياضي بمحافظة المجاردة في منطقة عسير جملةً من الإنجازات الرياضية والإدارية، في مقدمتها صعود الفريق الأول لكرة السلة إلى الدوري الممتاز للموسم الرياضي 2026-2027، وذلك بعد أن أنهى الفريق منافسات دوري الدرجة الأولى محتلاً المركز الثالث.','["وأعلن رئيس مجلس إدارة النادي صديق بيه الشهري البشرى لجماهير الفاروق بهذا الصعود، مؤكداً أن النادي يواصل خطواته نحو تعزيز حضوره في المنافسات المحلية.","وعلى صعيد كرة القدم، أفاد مدير المركز الإعلامي بالنادي محمد آل عمر بأن رئيس مجلس الإدارة اعتمد مشاركة فريق السيدات لكرة القدم في دوري الدرجة الثانية للموسم الرياضي 2026-2027، إلى جانب اعتماد مشاركة الفريق الأول «رجال» في منافسات الموسم ذاته.","وعلى صعيد الهوية المؤسسية، يستعد النادي للكشف عن شعاره الجديد وهويته البصرية المحدّثة خلال الأيام المقبلة، بعد أن أقرّها أعضاء الجمعية العمومية، في انتظار استكمال إجراءات اعتمادها من وزارة الرياضة.","ويأتي ذلك كله ضمن مرحلة تطوير شاملة يخوضها نادي الفاروق، تجمع بين تجديد الهوية وتوسيع المشاركة الرياضية وتعزيز الحضور في المنافسات المحلية، بما يواكب تطلعات جماهيره وأهدافه المستقبلية."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/26k455j','https://sabq.org/article/26k455j','','https://sabq.org/article/26k455j','عبدالعزيز الشهري ','السعودية','2026-08-14T06:31:00.000Z','2026-08-14T09:32:00.000Z','2026-08-14T21:31:39.000Z','https://media.sabq.org/news/2026/08/d41e28b3-7192-4dd4-b008-c6a0224dbacf/w1200.webp','/api/media/f533b124-e6c8-4491-a633-411b3df750cf','/api/media/f533b124-e6c8-4491-a633-411b3df750cf?variant=thumbnail','صعود تاريخي لسلة الفاروق إلى الممتاز واعتماد هوية بصرية جديدة يعززان طموحات النادي',1200,675,'valid','published','archived','valid',97,'18d78c622ab1041e5df6224e9216225e11a6255ecb099ce94a5971ee8d3a66f2','348363b4653e360d4a75ac6fc8ec154a6222be9691a5abb78839f8b4c9411b73','محدّث','2026-08-14T21:31:39.000Z','2026-10-07T20:50:54.688Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إدارة النادي صديق بيه","وزارة الرياضة ويأتي ذلك كله","رئيس مجلس إدارة النادي صديق","الرياضة السعودية","الرياض"]','["مجلس إدارة النادي صديق بيه","وزارة الرياضة ويأتي ذلك كله","رئيس مجلس إدارة النادي صديق","الرياضة السعودية"]','classified','','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:50:54.688Z',200,82,0,'source_article_available','',NULL,NULL,'body:de8d07d388f31c7c41a37414fbc7763436cb5d6c65c57f0196f1f079a9d21305','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2180ee0a-e49b-4036-8939-0e88e83c9a61','news-2180ee0a-e49b-4036-8939-0e88e83c9a61','العودة إلى كيرالا تتحول إلى «رحلة باهظة».. تذاكر الطيران من الخليج تقفز إلى 10 أضعاف قبيل مهرجان أونام','العوده الي كيرالا تتحول الي رحله باهظه تذاكر الطيران من الخليج تقفز الي 10 اضعاف قبيل مهرجان اونام','يواجه المغتربون الكيراليون في السعودية ودول الخليج أزمة حادة في أسعار تذاكر الطيران إلى ولايتهم مع اقتراب موسم مهرجان «أونام» — أكبر أعياد كيرالا وموسم عودتها السنوي الكبير — إذ كشفت وسائل إعلام هندية أن الأسعار قفزت إلى ما بين ثلاثة وعشرة أضعاف مستوياتها الاعتيادية، وسط شُح واضح في المقاعد المتاحة.','["وتتصدر المشهد معاناة القادمين من دول الخليج؛ فقد بلغ سعر تذكرة الرحلة بين أبوظبي وتيروفانانتابورام ما بين 40 و60 ألف روبية (نحو 1,700 إلى 2,600 ريال تقريباً) للنصف الأول من سبتمبر المقبل، بعد أن كانت تتراوح اعتيادياً بين 15 و25 ألف روبية (نحو 640 إلى 1,070 ريالاً)، فيما تسجل الرحلات المنطلقة من السعودية ودبي والكويت وقطر ارتفاعات مماثلة.","حتى الداخلية لم تسلم ولم تقتصر الموجة على الرحلات الدولية؛ إذ تضاعفت أسعار التذاكر الداخلية في الهند من نطاق 5 إلى 8 آلاف روبية إلى نحو 30 ألفاً خلال الموسم، بل تجاوزت في بعض المسارات حاجز 40 ألف روبية وصولاً إلى 150 ألفاً (نحو 6,400 ريال) — وهو رقم يفوق كلفة رحلات دولية طويلة.","مطالبات بسقوف سعرية وتتصاعد المطالبات الموجهة إلى الهيئة العامة للطيران المدني الهندية (DGCA) للتدخل العاجل وكبح زيادات وصفها المتضررون بـ«غير العادلة»، معتبرين أن شركات الطيران تستغل ذروة الطلب الموسمي دون رقابة كافية، وأن غياب سقوف سعرية في المواسم يجعل المسافرين «رهينة ممارسات احتكارية» في مناسبة يحرصون فيها على العودة إلى ذويهم.","يُذكر أن الجالية الكيرالية تُعد من أكبر مكونات الجالية الهندية في السعودية ودول الخليج، ويرتبط كثير من أبنائها بموعد سنوي ثابت للعودة خلال «أونام»، مهرجان الحصاد التقليدي الذي تتزين له كيرالا بموائدها وقواربها وسجاد أزهارها."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/fp9fr9n','https://sabq.org/article/fp9fr9n','','https://sabq.org/article/fp9fr9n','صحيفة سبق','السعودية','2026-08-14T06:00:00.000Z','2026-08-14T09:00:00.000Z','2026-08-14T21:31:40.322Z','https://media.sabq.org/news/2026/08/85daeaa8-df5b-48c4-887d-a6dc8d81ddbc/w800.webp','/api/media/2180ee0a-e49b-4036-8939-0e88e83c9a61','/api/media/2180ee0a-e49b-4036-8939-0e88e83c9a61?variant=thumbnail','العودة إلى كيرالا تتحول إلى «رحلة باهظة».. تذاكر الطيران من الخليج تقفز إلى 10 أضعاف قبيل مهرجان أونام',800,532,'valid','published','archived','valid',50,'744f7961a2df73e8f9e05cf061dc35594d37b34b69f3152d26534c97fbd305d7','ecb5512bf04fd07cdc56842d6d5224835354c422b987f9968e2c2bafd34b24b8','محدّث','2026-08-14T21:31:40.322Z','2026-10-07T20:50:50.901Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة"]','["السفر والسياحة"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T20:50:50.901Z',200,85,0,'source_article_available','',NULL,NULL,'body:da6730d2d7ff782db6b23634d25aeb777414c88afae18dc58516051327c07dca','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d2546e09-2580-4965-ad62-a4f691bec449','news-d2546e09-2580-4965-ad62-a4f691bec449','السعودية «مقر الإقامة الرسمي».. وثائق زواج رونالدو وجورجينا تكشف: فصلٌ تام للثروات ولا تبادل للألقاب','السعوديه مقر الاقامه الرسمي وثائق زواج رونالدو وجورجينا تكشف فصل تام للثروات ولا تبادل للالقاب','كشفت صحيفة «جورنال دي نوتيسياس» البرتغالية تفاصيل عقد زواج النجم البرتغالي كريستيانو رونالدو، قائد نادي النصر، وعارضة الأزياء جورجينا رودريغيز؛ إذ وقّع الثنائي اتفاقية مالية لما قبل الزواج في مكتب توثيق رسمي بالعاصمة لشبونة في العاشر من أغسطس، قبل يوم واحد من حفل زفافهما الذي أقيم بصورة خاصة على الأراضي البرتغالية.','["وبموجب الاتفاقية التي أوردتها وثائق تسجيل الزواج الرسمية، اختار الطرفان نظام الفصل التام للممتلكات ؛ فكل ما يملكه كل منهما قبل الزواج، وأي أصول أو دخل يكتسبه بعده، يبقى حقاً خالصاً لصاحبه، ولا تُعد الأصول مشتركة إلا إذا اقتُنيت أو سُجلت رسمياً باسم الزوجين معاً.","مليار رونالدو وتكتسب الاتفاقية أهميتها من التفاوت الكبير في الثروة بين الطرفين؛ إذ تقدّر مجلة «فوربس» ثروة رونالدو بنحو 1.2 مليار دولار، فيما يتصدر قائمة أعلى الرياضيين دخلاً في العالم لعام 2026 بعائد سنوي يناهز 300 مليون دولار.","الرياض بيت العائلة اللافت للقارئ السعودي أن الوثائق سجّلت المملكة العربية السعودية مقراً رسمياً لإقامة الزوجين — تأكيد رسمي لما تعنيه الرياض للعائلة منذ انتقال «الدون» إلى النصر نهاية عام 2022، ولما يوحي به من استمرار ارتباطه بالمملكة.","كما أفادت الوثائق بأن الزوجين لن يتبادلا اللقب العائلي، وسيحتفظ كل منهما باسمه الأصلي."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/p7sdmmz','https://sabq.org/article/p7sdmmz','','https://sabq.org/article/p7sdmmz','صحيفة سبق','السعودية','2026-08-14T06:06:00.000Z','2026-08-14T09:07:00.000Z','2026-08-14T21:31:40.332Z','https://media.sabq.org/news/2026/08/46770980-ab82-48f4-82fe-d579328f9433/w768.webp','/api/media/d2546e09-2580-4965-ad62-a4f691bec449','/api/media/d2546e09-2580-4965-ad62-a4f691bec449?variant=thumbnail','السعودية «مقر الإقامة الرسمي».. وثائق زواج رونالدو وجورجينا تكشف: فصلٌ تام للثروات ولا تبادل للألقاب',768,711,'valid','published','archived','valid',52,'7413099e4b891e1932f7205b2d8475a04e6a765221fc617d6d2663f63d820925','05d9be9ac8406512c7a80cb51a593352e44407393022ad4efe4d882e02b3db2f','محدّث','2026-08-14T21:31:40.332Z','2026-10-07T20:50:51.471Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض"]','[]','manual_approved','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"العالم","score":1.5},{"category":"السياسة","score":0}]','Active','2026-10-07T20:50:51.471Z',200,83,0,'source_article_available','',NULL,NULL,'body:e0c66528d16fcbd0cda4226c093da6ba3729d0653dcd7f2331ea9e35647f3fe7','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('875fefe4-441b-473c-b298-67f18152d96d','news-875fefe4-441b-473c-b298-67f18152d96d','«من نُزع منه الحياء صنع ما شاء».. خطيب المسجد النبوي: الحياء حجابٌ بين العبد والمعصية وقلته علامة شقاء','من نزع منه الحياء صنع ما شاء خطيب المسجد النبوي الحياء حجاب بين العبد والمعصيه وقلته علامه شقاء','أكد إمام وخطيب المسجد النبوي الشيخ الدكتور خالد المهنا أن الحياء «هو الحجاب بين العبد وبين معصية مولاه، وقلته من علامات الشقاء وموت الروح والقلب»، مبيناً في خطبة الجمعة اليوم من المسجد النبوي أن الحياء شعبة من شعب الإيمان، وفطرة في نفوس البشر، وخلق الأنبياء والمرسلين وأولياء الله الصالحين.','["وأوضح المهنا أن خلق الحياء «خصلة محمودة في جميع الشرائع، والخلة المعظمة عند جميع الأنبياء»، مستشهداً بقول رسول الله صلى الله عليه وسلم: «الإيمان بضع وسبعون - أو قال بضع وستون - شعبة، أفضلها قول: لا إله إلا الله، وأدناها إماطة الأذى عن الطريق، والحياء شعبة من الإيمان».","صفة تزكّي صاحبها وبيّن أن الحياء «صفة في النفس تحمل الإنسان على فعل ما يزكيه ويزينه، وترك ما يدنسه ويشينه»، وأنه خلق راسخ في نفس المؤمن يبعثه إلى أداء حقوق ربه ويقصر به عن الغي، «فمن تحلى وتجمل به فقد جمع من الخير ما تفرق في غيره».","وقال: «لا كمال للمسلم إلا بالحياء؛ فالحياء في أصله فطرة في نفوس البشر، لا ينتكس عنه إلا من ارتكس في أوحال الذنوب، فانطمست بصيرته وعمي قلبه».","وذكر أن المؤمن الحق «يستحيي من ربه إجلالاً لمعرفته بعظمته وكماله، ويستحيي أن يستعمل نعمه عليه في معصيته، ويستحيي ذو النفس الشريفة من نفسه أن تقنع بالدون وترضى بالنقص»."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/zrnaalk','https://sabq.org/article/zrnaalk','','https://sabq.org/article/zrnaalk','صحيفة سبق','السعودية','2026-08-14T05:44:00.000Z','2026-08-14T08:45:00.000Z','2026-08-14T21:31:40.449Z','https://media.sabq.org/news/2026/08/31181b57-ceda-4138-ad99-771e27abce31/w1600.webp','/api/media/875fefe4-441b-473c-b298-67f18152d96d','/api/media/875fefe4-441b-473c-b298-67f18152d96d?variant=thumbnail','«من نُزع منه الحياء صنع ما شاء».. خطيب المسجد النبوي: الحياء حجابٌ بين العبد والمعصية وقلته علامة شقاء',1600,1066,'valid','published','archived','valid',99,'692d94b5a9c86313814a77dd0d5ca71f91025831487f75f2ba2778970d732b88','29c5569b56f602ceee4d9984de79120ef2141ca527ea775dc291de91a42dd153','محدّث','2026-08-14T21:31:40.449Z','2026-10-07T20:51:38.726Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع"]','[]','classified','','[{"category":"السيارات","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:51:38.726Z',200,76,0,'source_article_available','',NULL,NULL,'body:35d378ceb905a8b88502d953fd2078e52ee1c48a6148a541bef2e1aa9a6e6df6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2541b030-2558-4e9b-8c36-4b349f9647d1','news-2541b030-2558-4e9b-8c36-4b349f9647d1','«الرؤيا فتوى لا يتكلم فيها إلا عالم».. خطيب المسجد الحرام يحذر من الكهان و«أبراج الحظ» ويبين أنواع الرؤى الثلاثة','الرؤيا فتوي لا يتكلم فيها الا عالم خطيب المسجد الحرام يحذر من الكهان و ابراج الحظ ويبين انواع الرؤي الثلاثه','حذر إمام وخطيب المسجد الحرام الشيخ الدكتور صالح بن عبدالله بن حميد من تعلق النفوس بمعرفة المستقبل عبر المنجمين والعرافين، مبيناً في خطبة الجمعة اليوم بالمسجد الحرام أن تعبير الرؤيا «علم شرعي بضوابطه، لا يجوز الإقدام عليه بغير علم؛ فالرؤيا فتوى لا يتحدث فيها أحد إلا بعلم».','["وقال ابن حميد بعد أن أوصى المسلمين بتقوى الله عز وجل: «تتعلق النفوس البشرية بمعرفة المستور من الغيب، وتقوى الأفئدة للاطلاع على المجهول من المستقبل، حتى تعلقوا بالمنجمين والرمالين والكهان وأبراج الحظ، فضَلُّوا وأضَلُّوا إلا من رحم الله»، مستشهداً بالحديث: «من أتى كاهناً أو عرافاً فصدقه بما يقول فقد كفر بما أنزل على محمد».","بشرى لا مستند وأوضح أن في مقابل ذلك تأتي الرؤى الصادقة؛ فالرؤيا الصالحة «جزء من ستة وأربعين جزءاً من النبوة» كما صح الخبر عن النبي صلى الله عليه وسلم، وأصدق الناس لهجة في اليقظة أصدقهم رؤيا، مستشهداً بقول ابن القيم رحمه الله: «الرؤيا أمثلة مضروبة يستدل بها الرائي بما ضُرب له من المثل على نظيره، ولهذا سمي تأويلها تعبيراً».","وقسّم الرؤى ثلاثة أنواع: أولها الرؤيا الصالحة وهي من الله، «رؤيا حق وبشرى صادقة تسر المؤمن ولا تغره، يستأنس بها ويستبشر ولا يستند إليها»، مبيناً أن من أراد أن تصدق رؤياه «فليتحرَّ الصدق وأكل الحلال والمحافظة على أوامر الله واجتناب نواهيه، وليكثر من ذكر الله».","ومن رأى ما يحب فليحمد الله وليخبر بها من يحب من أهل وده وأهل العلم والنصح؛ «فالعالم يعبّرها على الخير ما أمكنه، والحبيب إذا عرف قال، وإذا جهل سكت»."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/2yrt0mb','https://sabq.org/article/2yrt0mb','','https://sabq.org/article/2yrt0mb','صحيفة سبق','السعودية','2026-08-14T05:42:00.000Z','2026-08-14T08:43:00.000Z','2026-08-14T21:31:41.798Z','https://media.sabq.org/news/2026/08/486593c2-c046-4b21-bed8-81c4b2c0d3af/w1600.webp','/api/media/2541b030-2558-4e9b-8c36-4b349f9647d1','/api/media/2541b030-2558-4e9b-8c36-4b349f9647d1?variant=thumbnail','«الرؤيا فتوى لا يتكلم فيها إلا عالم».. خطيب المسجد الحرام يحذر من الكهان و«أبراج الحظ» ويبين أنواع الرؤى الثلاثة',1600,1066,'valid','published','archived','valid',96,'c5e23d77f53bbc7af48c28ea41dcc62b4624fdb4cc844b8dd728d8bc016bfe1c','bceacb74be4cbd766d5855ad60f95816de701321893992f2888567db20760d87','محدّث','2026-08-14T21:31:41.798Z','2026-10-07T20:51:39.789Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع"]','[]','classified','','[{"category":"المناطق","score":4},{"category":"التقنية","score":2},{"category":"العالم","score":1.5}]','Active','2026-10-07T20:51:39.789Z',200,75,0,'source_article_available','',NULL,NULL,'body:018abfa48e688999500a0441d244efa2a0d95195244abc24d9bd65fb07e2f032','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('75a8239f-c5cd-4ec8-83b1-b18e3bde57cd','news-75a8239f-c5cd-4ec8-83b1-b18e3bde57cd','طريق «الهيجة» في جازان.. 20 كيلومتراً من الطبيعة الجبلية بين العارضة وفيفاء','طريق الهيجه في جازان 20 كيلومترا من الطبيعه الجبليه بين العارضه وفيفاء','يُشكّل طريق «الهيجة» أحد أبرز المسارات السياحية في منطقة جازان، إذ يتناغم على امتداده الطبيعة الجبلية مع المشاهد الريفية الخلّابة، ممتداً بين محافظتي العارضة وفيفاء ليمنح العابرين رحلة تتدرج من السفوح والمزارع والقرى الريفية وصولاً إلى مرتفعات فيفاء، إحدى أبرز الوجهات السياحية في المنطقة.','["ويمتد الطريق نحو 20 كيلومتراً، مارّاً بقرية الصيّابة والدقيقة في محافظة العارضة، وصولاً إلى الهيجة بمحافظة فيفاء، وسط تضاريس متنوعة تجمع بين الجبال والأودية والمساحات الزراعية، فيما ترسم المزارع والأشجار المنتشرة على جانبيه ملامح المشهد الريفي الأصيل، وتزداد كثافة الغطاء النباتي خلال موسم الأمطار لتتحول الرحلة عبره إلى تجربة سياحية قائمة بذاتها قبل الوصول إلى الوجهة.","ويبرز الطريق بوصفه رابطاً بين محافظتين من أشهر محافظات جازان سياحياً؛ إذ تجمع العارضة بين الطبيعة الريفية والجبلية والمزارع والأودية، فيما تتميز فيفاء بجبالها ومدرجاتها الزراعية وقراها الممتدة على السفوح والقمم، مما يمنح الطريق قيمة سياحية تتجاوز دوره في التنقل بين المحافظتين.","ورصدت عدسة وكالة الأنباء السعودية «واس» امتداد الطريق وسط الجبال وتعرجاته بين السفوح والمزارع، في مشاهد تتبدل على طول المسار بين الطرق الحديثة والقرى الريفية والمزارع والأشجار، وصولاً إلى المرتفعات التي تزداد معها كثافة الخضرة وتتداخل القمم مع السحب في الأجواء الماطرة.","وتُضفي الأمطار التي تشهدها منطقة جازان خلال أغسطس مزيداً من الجاذبية على الطريق، مع تجدد الغطاء النباتي واخضرار السفوح، لتبرز على امتداده مواقع طبيعية تستوقف المتنزهين ومحبي التصوير، لا سيما مع اعتدال الأجواء في المرتفعات خلال موسم الإجازة الصيفية."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/tmumd5e','https://sabq.org/article/tmumd5e','','https://sabq.org/article/tmumd5e','صحيفة سبق','السعودية','2026-08-14T05:33:00.000Z','2026-08-14T08:35:00.000Z','2026-08-14T21:31:42.083Z','https://media.sabq.org/news/2026/08/fdaf1f67-1b90-4bb2-9541-90827a669b2c/w1600.webp','/api/media/75a8239f-c5cd-4ec8-83b1-b18e3bde57cd','/api/media/75a8239f-c5cd-4ec8-83b1-b18e3bde57cd?variant=thumbnail','طريق «الهيجة» في جازان.. 20 كيلومتراً من الطبيعة الجبلية بين العارضة وفيفاء',1600,900,'valid','published','archived','valid',86,'f846c0b64367918a82fae264039b07074d5c769e262221b4f5fc784fc4f8b291','970a70b46533126576538bb95d950d75d794e0e7689bc0647c94d784c87ef87c','محدّث','2026-08-14T21:31:42.083Z','2026-10-07T20:51:01.198Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","جازان"]','["الطقس والمناخ"]','classified','','[{"category":"الصحة","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"السفر","score":1.5}]','Active','2026-10-07T20:51:01.198Z',200,83,0,'source_article_available','',NULL,NULL,'body:b075e01a3c2ee0593cd36fdf4da1dd64e7ef7a584c6b9d228c810f95b1bc7a4b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4679239a-5794-46d1-b5f1-01e246748c36','news-4679239a-5794-46d1-b5f1-01e246748c36','بالفيديو.. الأهلي ينتزع الفوز من الدرعية بهدف سبيرتسيان.. وجماهير الصاعد: «لسه ما شافوا شيء»','بالفيديو الاهلي ينتزع الفوز من الدرعيه بهدف سبيرتسيان وجماهير الصاعد لسه ما شافوا شيء','رصدت «سبق»، مساء أمس، من ملعب الأول بارك في العاصمة الرياض، آراء جماهير الأهلي والدرعية عقب المواجهة التي جمعت الفريقين في افتتاح مشوارهما بدوري روشن السعودي للمحترفين، وانتهت بفوز الأهلي بهدف دون مقابل، في مواجهة اتسمت بالندية، قدّم خلالها الدرعية الصاعد حديثاً إلى دوري روشن ظهوراً لافتاً رغم الخسارة.','["وحسم الأهلي المواجهة بهدف إدوارد سبيرتسيان في الدقيقة 26، ليخرج بالنقاط الثلاث، فيما غادر الدرعية المباراة وسط إشادة جماهيره بمستواه، مؤكدين أن الفريق كان قادراً على الخروج بنتيجة أفضل لو استثمر الفرص التي سنحت له.","المهم الفوز» عبّر الطفل بندر، مشجع الأهلي، عن سعادته بفوز فريقه في مستهل مشواره بالدوري، مؤكداً أن الأهم هو حصد النقاط الثلاث حتى لو جاء الانتصار بهدف وحيد.","والدرعية «فريق ثقيل» قال مشجع الأهلي مفلح الشهري إنه يعشق الفريق منذ صغره، مشيراً إلى أن الحضور الجماهيري لم يكن مُرضياً مقارنةً بحجم شعبية النادي، مستحضراً العبارة الشهيرة: «جدة أهلي وبحر».","وأشاد الشهري بالمستوى الذي قدّمه الدرعية في ظهوره الأول، مؤكداً أن الفريق الصاعد ظهر بصورة قوية ونجح في مقارعة الأهلي رغم الفارق في الخبرة والإمكانات."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/1zklirp','https://sabq.org/article/1zklirp','','https://sabq.org/article/1zklirp','صحيفة سبق','السعودية','2026-08-14T05:23:00.000Z','2026-08-14T08:45:00.000Z','2026-08-14T21:31:48.526Z','https://img.youtube.com/vi/wSogArXAKNk/maxresdefault.jpg','/api/media/4679239a-5794-46d1-b5f1-01e246748c36','/api/media/4679239a-5794-46d1-b5f1-01e246748c36?variant=thumbnail','بالفيديو.. الأهلي ينتزع الفوز من الدرعية بهدف سبيرتسيان.. وجماهير الصاعد: «لسه ما شافوا شيء»',1280,720,'valid','published','archived','valid',99,'eb0e58823ae8386f209c3aa1baa9d547a92fd1873bc1b1df4a56f8d90bdd7fd1','a0f7245b36c4500b5e249a0240f5aa405704f4edd6786dc573702a4951d1563c','محدّث','2026-08-14T21:31:48.526Z','2026-10-07T20:51:39.755Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","جدة"]','["الرياضة السعودية"]','classified','','[{"category":"الصحة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"التعليم","score":0}]','Active','2026-10-07T20:51:39.755Z',200,79,0,'source_article_available','',NULL,NULL,'body:c99f3bb839be91160581977f5f93048309b3b5450d4fcda20441f60e268ea773','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('867b4076-697d-439e-9c7d-e8c50a325fc6','news-867b4076-697d-439e-9c7d-e8c50a325fc6','القيادة تعزي الرئيس الصيني في وفاة رئيس مجلس الدولة الأسبق','القياده تعزي الرئيس الصيني في وفاه رئيس مجلس الدوله الاسبق','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية بعث خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، برقية عزاء ومواساة، للرئيس شي جين بينغ رئيس جمهورية الصين الشعبية في وفاة رئيس مجلس الدولة (الأسبق) في جمهورية الصين الشعبية تشو رونغ جي.','["بعث خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، برقية عزاء ومواساة، للرئيس شي جين بينغ رئيس جمهورية الصين الشعبية في وفاة رئيس مجلس الدولة (الأسبق) في جمهورية الصين الشعبية تشو رونغ جي.","وقال الملك المفدى: \"تلقينا نبأ وفاة رئيس مجلس الدولة (الأسبق) في جمهورية الصين الشعبية السيد تشو رونغ جي، ونعرب لفخامتكم ولأسرة الفقيد ولشعبكم الصديق عن أحر التعازي، وأصدق المواساة، متمنين ألا تروا أي سوء أو مكروه\".","كما بعث صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء، برقية عزاء ومواساة، للرئيس شي جين بينغ رئيس جمهورية الصين الشعبية."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/famythteg','https://ajel.sa/local/famythteg','https://ajel.sa/local/famythteg','https://ajel.sa/local/famythteg','فريق التحرير','السعودية','2026-08-14T12:54:00.000Z','Wed, 07 Oct 2026 20:50:52 GMT','2026-08-14T23:33:24.183Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D9%82%D9%8A%D8%A7%D8%AF%D8%A9-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-59_WyzfC.webp','/api/media/867b4076-697d-439e-9c7d-e8c50a325fc6','/api/media/867b4076-697d-439e-9c7d-e8c50a325fc6?variant=thumbnail','القيادة',1200,675,'valid','published','archived','valid',99,'6d701351b4f012d57e4c938a7d7f54cb805bcf5b50397073c47380c429ed1586','717e11d7a7b1ed3127042a8d3c577dab4a2548f3bd7f944dcfbb4adb15acffd0',NULL,'2026-08-14T23:33:24.183Z','2026-10-07T20:50:54.049Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","رئيس مجلس الدولة الأسبق صحيفة","خادم الحرمين الشريفين الملك سلمان","مجلس الدولة الأسبق صحيفة إلكترونية","الصين"]','["ولي العهد رئيس مجلس الوزراء","رئيس مجلس الدولة الأسبق صحيفة","خادم الحرمين الشريفين الملك سلمان","مجلس الدولة الأسبق صحيفة إلكترونية"]','classified','','[{"category":"المجتمع","score":4.5},{"category":"العالم","score":3},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:50:54.049Z',200,81,0,'source_content_changed','',NULL,NULL,'body:0a44fb9c727687579780f12d3bbe87c993e642cfcfebec42eebcd67b90f27de7','Wed, 07 Oct 2026 20:50:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8a4cd233-f412-43bb-be82-a1e65b930b2e','news-8a4cd233-f412-43bb-be82-a1e65b930b2e','الدفاع المدني بحفر الباطن يخمد حريقًا في محال تجارية بحي فليج','الدفاع المدني بحفر الباطن يخمد حريقا في محال تجاريه بحي فليج','وقالت المديرية العامة للدفاع المدني، عبر منصة "إكس"، إن الحريق تم إخماده، دون إصابات. يأتي ذلك ضمن الجهود التي تباشرها المديرية للتعامل مع الحرائق بتوقيت قياسي لسرعة السيطرة عليها ومنع خطر امتدادها.','["أخمد الدفاع المدني، ب حفر الباطن ، حريقًا في محال تجارية بحي فليج.","وقالت المديرية العامة للدفاع المدني، عبر منصة \"إكس\"، إن الحريق تم إخماده، دون إصابات.","يأتي ذلك ضمن الجهود التي تباشرها المديرية للتعامل مع الحرائق بتوقيت قياسي لسرعة السيطرة عليها ومنع خطر امتدادها."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/0ecvg2p68','https://ajel.sa/local/0ecvg2p68','https://ajel.sa/local/0ecvg2p68','https://ajel.sa/local/0ecvg2p68','فريق التحرير','السعودية','2026-08-14T13:00:00.000Z','Wed, 07 Oct 2026 20:51:37 GMT','2026-08-14T23:33:24.728Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-D6sqfi3Q.jpg','/api/media/8a4cd233-f412-43bb-be82-a1e65b930b2e','/api/media/8a4cd233-f412-43bb-be82-a1e65b930b2e?variant=thumbnail','الدفاع المدني بحفر الباطن يخمد حريقًا في محال تجارية بحي فليج',1200,675,'valid','published','archived','valid',58,'ab85a7f809210b9c5cfa19c50928586e6e01bbebed20a5f820c6897e9397b233','f665730fa54e27432a5dbd26aea3d42212ad564f2c03a703988b46f91aa3bb41',NULL,'2026-08-14T23:33:24.728Z','2026-10-07T20:51:39.144Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Updated','2026-10-07T20:51:39.144Z',200,78,0,'source_content_changed','',NULL,NULL,'body:d2733e023e3aba4b981797e552ddc1765a9a63c75ac722858dfdb1954c2628d7','Wed, 07 Oct 2026 20:51:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('22eb2e50-9fd3-439a-baba-5157e8a836c2','news-22eb2e50-9fd3-439a-baba-5157e8a836c2','وزير النفط العراقي: صادرات الخام بلغت مليوني برميل يوميا منذ الشهر الجاري','وزير النفط العراقي صادرات الخام بلغت مليوني برميل يوميا منذ الشهر الجاري','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية أعلن وزير النفط العراقي باسم محمد خضير، اليوم، ارتفاع الصادرات النفطية العراقية إلى نحو مليوني برميل يوميا منذ مطلع أغسطس الجاري، في مؤشر على تعافي حركة التصدير بعد تداعيات أزمة مضيق هرمز .','["أعلن وزير النفط العراقي باسم محمد خضير، اليوم، ارتفاع الصادرات النفطية العراقية إلى نحو مليوني برميل يوميا منذ مطلع أغسطس الجاري، في مؤشر على تعافي حركة التصدير بعد تداعيات أزمة مضيق هرمز .","وقال خضير وفق بيان رسمي إن \"المفاوضات لا تزال مستمرة مع الأطراف المعنية فيما يخص تصدير النفط، موضحًا أن أربع ناقلات نفطية تحمل حاليًا الخام العراقي، فيما بلغ معدل الصادرات منذ بداية آب/أغسطس نحو مليوني برميل يوميا\".","وأشار خضير إلى أن أكثر من 85 بالمئة من الموازنة العراقية تعتمد على الإيرادات النفطية، ما يجعل تأمين منافذ تصدير متعددة وتعزيز البنية التحتية للقطاع النفطي أولوية اقتصادية للبلاد."]','الطاقة والصناعة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/9x28fbwe1','https://ajel.sa/international/9x28fbwe1','https://ajel.sa/international/9x28fbwe1','https://ajel.sa/international/9x28fbwe1','فريق التحرير','السعودية','2026-08-14T13:07:00.000Z','Wed, 07 Oct 2026 20:50:36 GMT','2026-08-14T23:33:26.459Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-X1gyMNdn.jpg','/api/media/22eb2e50-9fd3-439a-baba-5157e8a836c2','/api/media/22eb2e50-9fd3-439a-baba-5157e8a836c2?variant=thumbnail','وزير النفط العراقي: صادرات الخام بلغت مليوني برميل يوميا منذ الشهر الجاري',1200,675,'valid','published','archived','valid',46,'cefd334e39c96942116559636af14ac93fefb0ca7cbe5ed363e4f54305587822','3f9af86a0bf88766cc53d004e21b43118e4b3d7e4d9ff0a545a57ab9ae892dee',NULL,'2026-08-14T23:33:26.459Z','2026-10-07T20:50:38.453Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير النفط العراقي صادرات الخام","الطاقة والنفط","الاقتصاد والأسواق","السياسة والعلاقات الدولية","العراق"]','["وزير النفط العراقي صادرات الخام","الطاقة والنفط","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','manual_approved','below_category_threshold','[{"category":"السياسة","score":1.5},{"category":"الاقتصاد","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:50:38.453Z',200,91,0,'source_content_changed','',NULL,NULL,'body:d2153094b0b4a1cf1d293c5b7cf711ff6e9c0d954f238bba8bfd771c2360b3c4','Wed, 07 Oct 2026 20:50:36 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('42c4accd-25df-43d5-899f-0fe1c78049c9','news-42c4accd-25df-43d5-899f-0fe1c78049c9','الجيش اليمني يكشف تفاصيل هجوم حوثي بـ4 صواريخ على ميناء المخا','الجيش اليمني يكشف تفاصيل هجوم حوثي بـ4 صواريخ علي ميناء المخا','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية استهدفت مليشيا الحوثي، اليوم، ميناء المخا بأربعة صواريخ باليستية، في هجوم طال الأعيان المدنية والمقدرات الوطنية، وأسفر عن خسائر بشرية، وفق المركز الإعلامي للقوات المسلحة اليمنية.','["استهدفت مليشيا الحوثي، اليوم، ميناء المخا بأربعة صواريخ باليستية، في هجوم طال الأعيان المدنية والمقدرات الوطنية، وأسفر عن خسائر بشرية، وفق المركز الإعلامي للقوات المسلحة اليمنية.","وقال الناطق الرسمي باسم القوات المسلحة اليمنية، العقيد الركن ماجد النزيلي، إن استهداف المليشيا الحوثية للموانئ يمثل، بحسب وصفه، محاولة لحصار وتجويع الشعب اليمني، مؤكدًا وقوع خسائر بشرية جراء الهجوم.","وأضاف النزيلي أن الفرق المختصة تواصل أعمالها لحصر الأضرار الناجمة عن الهجوم الحوثي الذي استهدف ميناء المخا، في وقت تتواصل فيه عمليات تقييم الخسائر الناتجة عن القصف."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/9whv5askb','https://ajel.sa/international/9whv5askb','https://ajel.sa/international/9whv5askb','https://ajel.sa/international/9whv5askb','فريق التحرير','السعودية','2026-08-14T13:01:00.000Z','Wed, 07 Oct 2026 20:50:51 GMT','2026-08-14T23:33:26.514Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%85%D8%A7%D8%AC%D8%AF-%D8%A7%D9%84%D9%86%D8%B2%D9%8A%D9%84%D9%8A-y--jnnRZ.jpg','/api/media/42c4accd-25df-43d5-899f-0fe1c78049c9','/api/media/42c4accd-25df-43d5-899f-0fe1c78049c9?variant=thumbnail','ماجد النزيلي',1200,675,'valid','published','archived','valid',40,'a3410d141bee361047a24bd89fa35009a016652e4d53a7e51b2a03b770e814f5','81e6ff1a72a205f45e56eef9961e564fa7865d93c1d85962633e894c366d177e',NULL,'2026-08-14T23:33:26.514Z','2026-10-07T20:50:53.000Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","اليمن"]','["السفر والسياحة"]','manual_approved','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Updated','2026-10-07T20:50:53.000Z',200,84,0,'source_content_changed','',NULL,NULL,'body:eecc0d2b971bff45bfd11ae784de4056320c0e7795e8f0dd3da7d7676ec0a6df','Wed, 07 Oct 2026 20:50:51 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('20a89ff7-82ee-46c6-a5e9-9332581b8bee','news-20a89ff7-82ee-46c6-a5e9-9332581b8bee','8 فرص استثمارية جديدة في حبونا.. أمانة نجران تكشف التفاصيل والمواعيد','8 فرص استثماريه جديده في حبونا امانه نجران تكشف التفاصيل والمواعيد','طرحت أمانة منطقة نجران ، ممثلةً في بلدية محافظة حبونا ، 8 فرص استثمارية متنوعة في منافسة عامة عبر بوابة الاستثمار البلدي «فرص»، في إطار جهودها لتعزيز الشراكة مع القطاع الخاص ودعم التنمية الاقتصادية والخدمية بالمنطقة.','["وتشمل الفرص المطروحة مشاريع في قطاعات تجارية وسكنية وترفيهية ورياضية وخدمية وصناعية ومالية، من بينها إنشاء وترميم وتشغيل وصيانة مجمع تجاري وسكني بالمنشّر على مساحة 5,594 مترًا مربعًا، إلى جانب إنشاء وترميم وتشغيل وصيانة محال تجارية بحبونا على مساحة 1,650 مترًا مربعًا.","كما تتضمن الحزمة الاستثمارية مشروع إنشاء وترميم وتشغيل وصيانة أسواق تجارية متعددة بمدخل حبونا الشرقي على مساحة تتجاوز 10,724 مترًا مربعًا، إضافة إلى إنشاء وترميم وتشغيل وصيانة قصر أفراح للنساء بالمنشّر على مساحة 5,195 مترًا مربعًا.","وفي القطاع الرياضي والترفيهي، تشمل الفرص المطروحة ترميم وتشغيل وصيانة ملعب كرة قدم بالجفجة على مساحة تقارب 3,740 مترًا مربعًا، وإنشاء وترميم وتشغيل وصيانة كشك بجانب حديقة الحباية على مساحة 15 مترًا مربعًا.","ويمتد الطرح إلى القطاع الخدمي والصناعي من خلال مشروع لإنشاء وترميم وتشغيل وصيانة ورش وتشاليح ومعارض السيارات بصناعية العباية على مساحة تتجاوز 103,700 متر مربع، إلى جانب فرصة لإنشاء وترميم وتفعيل وصيانة صراف آلي سيار بحبونا على مساحة 12 مترًا مربعًا.","وحددت بلدية محافظة حبونا يوم 20 أغسطس 2026 موعدًا نهائيًا للفرص الخاصة بالكشك وملعب كرة القدم، فيما حُدد يوم 21 سبتمبر 2026 آخر موعد لبقية الفرص الاستثمارية المطروحة.","ودعت البلدية المستثمرين ورواد الأعمال الراغبين في التنافس إلى الاطلاع على تفاصيل الفرص الاستثمارية وشراء كراسات الشروط والمواصفات، وتقديم عطاءاتهم إلكترونيًا عبر تطبيق «فرص» أو الموقع الإلكتروني للبوابة."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/790pg0pg3','https://ajel.sa/local/790pg0pg3','https://ajel.sa/local/790pg0pg3','https://ajel.sa/local/790pg0pg3','فريق التحرير','السعودية','2026-08-14T13:52:00.000Z','2026-08-14T16:52:00.000Z','2026-08-14T23:33:27.827Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A3%D9%85%D8%A7%D9%86%D8%A9-%D9%85%D9%86%D8%B7%D9%82%D8%A9-%D9%86%D8%AC%D8%B1%D8%A7%D9%86-2-OJEnb43c.jpg','/api/media/20a89ff7-82ee-46c6-a5e9-9332581b8bee','/api/media/20a89ff7-82ee-46c6-a5e9-9332581b8bee?variant=thumbnail','أمانة نجران',1200,675,'valid','review','archived','valid',97,'3e3ad2926c64c5c60901a193c7323878423104f01184703e8cb4f542c376fa24','76be3a5d0d722a020d6e64d15944fb63610ec37548e588d4a75c2cbd2320c48c',NULL,'2026-08-14T23:33:27.827Z','2026-10-07T20:50:03.716Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["المناطق","الاقتصاد والأسواق","نجران","الرياض","فرص استثمارية","أمانة نجران تكشف","جديدة حبونا أمانة","حبونا أمانة نجران"]','["الاقتصاد والأسواق","فرص استثمارية","أمانة نجران تكشف","جديدة حبونا أمانة","حبونا أمانة نجران","فرص استثمارية جديدة"]','classified','','[{"category":"الاقتصاد","score":9},{"category":"الرياضة","score":4},{"category":"الصحة","score":1.5}]','Removed','2026-10-07T20:50:03.716Z',404,87,0,'source_confirmed_removed_http_404','','2026-10-07T20:50:03.716Z','published','body:19f400e6b76f8ddcf62e88a77868b6bdbf0e17634b3272a5c1b72e77ae374848','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('685b1023-f3b2-41a7-bdab-017740584e85','news-685b1023-f3b2-41a7-bdab-017740584e85','خدمة «تواصل».. الجوازات توضح طريقة إنجاز المعاملات المتعذرة إلكترونيًا عبر «أبشر»','خدمه تواصل الجوازات توضح طريقه انجاز المعاملات المتعذره الكترونيا عبر ابشر','أوضحت المديرية العامة للجوازات أن خدمة «تواصل» عبر منصة «أبشر» تتيح للمستفيدين تقديم طلبات إنجاز المعاملات التي يتعذر تنفيذها إلكترونيًا، دون الحاجة إلى مراجعة مقار إدارات الجوازات.','["وبينت المديرية، عبر حسابها الرسمي على منصة «إكس»، أن الخدمة تتيح رفع الطلبات إلكترونيًا واستكمال الإجراءات عبر «أبشر»، بما يسهم في تسهيل إنجاز المعاملات وتوفير الوقت والجهد على المستفيدين.","وللاستفادة من خدمة «تواصل»، يتعين على المستفيد تسجيل الدخول إلى منصة «أبشر»، ثم اختيار «خدماتي»، والدخول إلى «الجوازات»، واختيار خدمة «تواصل».","بعد ذلك، يتم الضغط على «تقديم طلب جديد»، ثم تحديد القسم والخدمة الفرعية المطلوبة، وكتابة وصف الطلب وإرفاق المستندات اللازمة، قبل إرسال الطلب إلكترونيًا."]','الثقافة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/2jk30hpfm','https://ajel.sa/local/2jk30hpfm','https://ajel.sa/local/2jk30hpfm','https://ajel.sa/local/2jk30hpfm','فريق التحرير','السعودية','2026-08-14T13:52:00.000Z','Wed, 07 Oct 2026 20:50:06 GMT','2026-08-14T23:33:27.878Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%84%D8%A7%D9%89%D9%89%D9%89-7FoTRiXl.png','/api/media/685b1023-f3b2-41a7-bdab-017740584e85','/api/media/685b1023-f3b2-41a7-bdab-017740584e85?variant=thumbnail','خدمة «تواصل»',1200,675,'valid','published','archived','valid',40,'bc70fabafb40d5939cb7654eb98f03354ff0beb13a12da680e87f5580c0cfb7d','288dda4147a98636b4cb57122319b7b89bb68446a738a0d7a4c3a3eaf79ce2c2',NULL,'2026-08-14T23:33:27.878Z','2026-10-07T20:50:08.798Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السيارات"]','[]','manual_approved','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Updated','2026-10-07T20:50:08.798Z',200,89,0,'source_content_changed','',NULL,NULL,'body:8ffd3187023b0ed8d77b54b3107a9c906463a93a248cddae25a5014bc38fc432','Wed, 07 Oct 2026 20:50:06 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0fc3c4a6-307b-492a-81c3-5d3256a26764','news-0fc3c4a6-307b-492a-81c3-5d3256a26764','كندا تفرض عقوبات على 5 مسؤولين إيرانيين بسبب تهديد الملاحة في مضيق هرمز','كندا تفرض عقوبات علي 5 مسؤولين ايرانيين بسبب تهديد الملاحه في مضيق هرمز','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية أعلنت كندا فرض عقوبات إضافية على خمسة أفراد إيرانيين، على خلفية ما وصفته أنشطتهم العسكرية والقانونية والإعلامية التي تقوض السلام والأمن والاستقرار الدوليين، وفي مقدمتها ما يتعلق بعرقلة حقوق الملاحة في مضيق هرمز والمناطق المحيطة به.','["أعلنت كندا فرض عقوبات إضافية على خمسة أفراد إيرانيين، على خلفية ما وصفته أنشطتهم العسكرية والقانونية والإعلامية التي تقوض السلام والأمن والاستقرار الدوليين، وفي مقدمتها ما يتعلق بعرقلة حقوق الملاحة في مضيق هرمز والمناطق المحيطة به.","وقالت وزيرة الخارجية الكندية أنيتا أناند ، في بيان صدر اليوم الجمعة، إن العقوبات تأتي بموجب لوائح التدابير الاقتصادية الخاصة المتعلقة ب إيران ، وتستهدف مسؤولين كبارًا في الجمهورية الإسلامية الإيرانية، بينهم أعضاء في الحرس الثوري الإيراني .","وأوضحت الحكومة الكندية أن الإجراءات تستهدف أنشطة قالت إنها هددت ممرًا مائيًا دوليًا حيويًا وعرقلت حقوق الملاحة في مضيق هرمز وحوله، معتبرة أن هذه الممارسات تمثل انتهاكًا للقانون الدولي وتقوض السلام والأمن الدوليين."]','السياسة','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/vepjsc8ex','https://ajel.sa/international/vepjsc8ex','https://ajel.sa/international/vepjsc8ex','https://ajel.sa/international/vepjsc8ex','فريق التحرير','السعودية','2026-08-14T13:52:00.000Z','Wed, 07 Oct 2026 20:50:37 GMT','2026-08-14T23:33:27.976Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%88%D8%B2%D9%8A%D8%B1%D8%A9-%D8%A7%D9%84%D8%AE%D8%A7%D8%B1%D8%AC%D9%8A%D8%A9-%D8%A7%D9%84%D9%83%D9%86%D8%AF%D9%8A%D8%A9-%D8%A3%D9%86%D9%8A%D8%AA%D8%A7-%D8%A3%D9%86%D8%A7%D9%86%D8%AF-pIhogOJd.jpg','/api/media/0fc3c4a6-307b-492a-81c3-5d3256a26764','/api/media/0fc3c4a6-307b-492a-81c3-5d3256a26764?variant=thumbnail','وزيرة الخارجية الكندية أنيتا أناند',1200,675,'valid','published','archived','valid',58,'f942744beec85256e5cb878085e9eb094ef4c43303ce32a6a4419fc627a0b0fd','5e44cf22cc1244f03d51a5100e919c4202869954e8b149a3677671ce81f306b4',NULL,'2026-08-14T23:33:27.976Z','2026-10-07T20:50:39.476Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","الاقتصاد والأسواق","إيران"]','["الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":1.5},{"category":"الطاقة والصناعة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:50:39.476Z',200,85,0,'source_content_changed','',NULL,NULL,'body:49aad048f7f1eb28c17179fa57208332e6cb36a5b51b5d89d93876d878c6ef48','Wed, 07 Oct 2026 20:50:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c90e197a-8366-4f53-b1c1-2285f40d99c0','news-c90e197a-8366-4f53-b1c1-2285f40d99c0','القنصلية السعودية في نيويورك تحذر المواطنين من فيضانات إنديانا','القنصليه السعوديه في نيويورك تحذر المواطنين من فيضانات انديانا','حذرت القنصلية العامة للمملكة العربية السعودية في نيويورك المواطنين السعوديين الموجودين في ولاية إنديانا والمناطق المجاورة لها من الفيضانات التي تشهدها المنطقة، مشيرة إلى احتمالية استمرارها حتى يوم السبت 15 أغسطس 2026.','["ودعت القنصلية المواطنين إلى توخي الحيطة والحذر خلال الفترة المقبلة، مع ضرورة متابعة ما تصدره السلطات المحلية المختصة من تحديثات بشأن تطورات الفيضانات والتعليمات والإرشادات المرتبطة بها.","وشددت على أهمية الالتزام بتوجيهات الجهات المعنية ومتابعة المستجدات، في ظل استمرار الحالة التي تشهدها إنديانا والمناطق المحيطة بها.","وأعلنت القنصلية أرقامًا مخصصة للتواصل في حالات الطوارئ، داعية المواطنين السعوديين إلى استخدامها عند الحاجة:"]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/rq3os6ymo','https://ajel.sa/local/rq3os6ymo','https://ajel.sa/local/rq3os6ymo','https://ajel.sa/local/rq3os6ymo','فريق التحرير','السعودية','2026-08-14T13:58:00.000Z','Wed, 07 Oct 2026 20:50:40 GMT','2026-08-14T23:33:29.334Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-KiMGWNqs.jpg','/api/media/c90e197a-8366-4f53-b1c1-2285f40d99c0','/api/media/c90e197a-8366-4f53-b1c1-2285f40d99c0?variant=thumbnail','القنصلية السعودية في نيويورك',1200,675,'valid','published','archived','valid',44,'9adbf7d30b8569f219a2cf1315d3a8232912db0a59ef4674986a84430ff09d4f','7bc4dc5ddaceb5a0d17fe13532defb82ad72afea65a362dad618e72ed3be21b0',NULL,'2026-08-14T23:33:29.334Z','2026-10-07T20:50:41.705Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"التعليم","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:50:41.705Z',200,85,0,'source_content_changed','',NULL,NULL,'body:2b24dc2cfd55c95c8da89913fe212d3d22830edc4ad2b370993cb2c055d43584','Wed, 07 Oct 2026 20:50:40 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('977a0ddb-9d7e-42ec-8a29-4e22fd21c41a','news-977a0ddb-9d7e-42ec-8a29-4e22fd21c41a','قتيل و8 مصابين بقصف حوثي على المخا.. واستهداف الميناء بـ6 صواريخ باليستية','قتيل و8 مصابين بقصف حوثي علي المخا واستهداف الميناء بـ6 صواريخ باليستيه','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية قُتل مدني وأصيب 8 آخرون جراء قصف صاروخي حوثي استهدف مدينة المخا مساء اليوم، وفق مصادر طبية يمنية تحدثت إلى قناة «العربية»، بالتزامن مع استهداف ميناء المخا بـ6 صواريخ باليستية، بحسب القوات الحكومية اليمنية.','["قُتل مدني وأصيب 8 آخرون جراء قصف صاروخي حوثي استهدف مدينة المخا مساء اليوم، وفق مصادر طبية يمنية تحدثت إلى قناة «العربية»، بالتزامن مع استهداف ميناء المخا بـ6 صواريخ باليستية، بحسب القوات الحكومية اليمنية.","وقال الناطق الرسمي باسم القوات المسلحة اليمنية، العقيد الركن ماجد النزيلي، إن مليشيا الحوثي استهدفت ميناء المخا بستة صواريخ باليستية، في هجوم طال الأعيان المدنية والمقدرات الوطنية، مؤكدًا وقوع خسائر بشرية جراء القصف.","وأضاف النزيلي أن استهداف الموانئ يمثل، بحسب وصفه، محاولة من الحوثيين لحصار وتجويع الشعب اليمني، مشيرًا إلى أن الفرق المختصة تواصل العمل على حصر الأضرار الناجمة عن الهجوم وتقييم حجم الخسائر."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/f36lboiy7','https://ajel.sa/international/f36lboiy7','https://ajel.sa/international/f36lboiy7','https://ajel.sa/international/f36lboiy7','فريق التحرير','السعودية','2026-08-14T13:58:00.000Z','Wed, 07 Oct 2026 20:50:40 GMT','2026-08-14T23:33:29.442Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%85%D9%8A%D9%86%D8%A7%D8%A1-%D8%A7%D9%84%D9%85%D8%AE%D8%A7-DksJENOm.webp','/api/media/977a0ddb-9d7e-42ec-8a29-4e22fd21c41a','/api/media/977a0ddb-9d7e-42ec-8a29-4e22fd21c41a?variant=thumbnail','تصعيد واسع في المخا',1200,675,'valid','published','archived','valid',40,'6d2c59a2839317da92f74dbf7c97123d233f92f1cd00b680ecc36e2529342312','6a76b8cabcb020ebbad05a3d8b3e308b340bb2cedcf3609412937c38ce35303d',NULL,'2026-08-14T23:33:29.442Z','2026-10-07T20:50:41.824Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["اليمن"]','[]','manual_approved','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Updated','2026-10-07T20:50:41.824Z',200,90,0,'source_content_changed','',NULL,NULL,'body:2fefad4980a343c033097da23064caca65386505ff5f290918963f2e695437cf','Wed, 07 Oct 2026 20:50:40 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6c8ed441-679d-4af2-b9c6-442fa19792c5','news-6c8ed441-679d-4af2-b9c6-442fa19792c5','القبض على شخص ظهر في مقطع يسرق بطارية مركبة بالرياض.. وضبط 9 بطاريات بحوزته','القبض علي شخص ظهر في مقطع يسرق بطاريه مركبه بالرياض وضبط 9 بطاريات بحوزته','ألقت دوريات الأمن بمنطقة الرياض القبض على شخص ظهر في محتوى مرئي أثناء سرقته بطارية مركبة متوقفة في مدينة الرياض، وضُبط بحوزته 9 بطاريات. وجرى إيقاف المتهم واتخاذ الإجراءات النظامية بحقه، قبل إحالته إلى النيابة العامة لاستكمال الإجراءات.','["ألقت دوريات الأمن بمنطقة الرياض القبض على شخص ظهر في محتوى مرئي أثناء سرقته بطارية مركبة متوقفة في مدينة الرياض، وضُبط بحوزته 9 بطاريات.","وجرى إيقاف المتهم واتخاذ الإجراءات النظامية بحقه، قبل إحالته إلى النيابة العامة لاستكمال الإجراءات."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/3ckzutdvw','https://ajel.sa/local/3ckzutdvw','https://ajel.sa/local/3ckzutdvw','https://ajel.sa/local/3ckzutdvw','فريق التحرير','السعودية','2026-08-14T13:58:00.000Z','Wed, 07 Oct 2026 20:50:05 GMT','2026-08-14T23:33:29.458Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-cBCqHJhQ.png','/api/media/6c8ed441-679d-4af2-b9c6-442fa19792c5','/api/media/6c8ed441-679d-4af2-b9c6-442fa19792c5?variant=thumbnail','المتهم',1200,675,'valid','published','archived','valid',46,'79dc2e1a42383e5ed6bce20b26f2ee208796fd7e32adce4e04e63d14c8941c74','ad14f2f7e6395bbe523a8580abb995f9f1c5e3af371b3a4f3f4e02b784593c52',NULL,'2026-08-14T23:33:29.458Z','2026-10-07T20:50:07.330Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T20:50:07.330Z',200,87,0,'source_content_changed','',NULL,NULL,'body:cb585904d2b460104909b3b51fe88efd9d6c26e16baa20204e96c263e8407a64','Wed, 07 Oct 2026 20:50:05 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('56ea1e77-3fac-48de-bfbb-69b60cbc9094','news-56ea1e77-3fac-48de-bfbb-69b60cbc9094','خاص| ‏&quot;ليس ميسي أو رونالدو&quot;.. أسطورة ليفربول يقلل من بيلينجهام','خاص quot ليس ميسي او رونالدو quot اسطوره ليفربول يقلل من بيلينجهام','تألق نجم ريال مدريد في كأس العالم لم يكن كافيًا قال جون بارنز لموقع GOAL إن جود بيلينجهام «ليس ليونيل ميسي أو كريستيانو رونالدو» ولا يستطيع «حسم المباريات بمفرده»، إذ يُنظر إلى نجم إنجلترا وريال مدريد على أنه أقرب إلى صانع ألعاب في مركز الرقم 8 على غرار براين روبسون، أكثر من كونه صانع ألعاب مبدعًا في مركز الرقم 10.','["تألق نجم ريال مدريد في كأس العالم لم يكن كافيًا","فكثيرًا ما دُفع لاعب الوسط كثير الحركة إلى مركز أكثر تقدمًا، لكن قدراته تبلغ أقصاها عندما يؤدي دوره في مركز أكثر تراجعًا.","لعب بيلينجهام في كلا هذين المركزين خلال مسيرته حتى الآن. فقد ظهر على الساحة كمراهق موهوب بشكل مبكر بينما كان يشغل مركزًا في وسط ملعب بيرمينجهام سيتي. وفي تلك المرحلة، لم يكن مفاجئًا أن تُعقد مقارنات بينه وبين أسطورة ليفربول ستيفن جيرارد.","ولم يستغرق الأمر وقتًا طويلًا، عقب انتقاله إلى بوروسيا دورتموند، حتى يحظى بالاعتراف على مستوى المنتخب الأول. فقد أصبح اللاعب البالغ من العمر 23 عامًا حضورًا ملهمًا لمنتخب إنجلترا، إذ أعقب احتفاله الأيقوني في يورو 2024 وتسجيله سبعة أهداف في كأس العالم 2026."]','الرياضة','العالم','ed850016-06a2-4cc9-adb8-88cd8a2fc9dc','أخبار Google','https://www.goal.com/ar/%D8%A7%D9%84%D9%82%D9%88%D8%A7%D8%A6%D9%85/%D8%AE%D8%A7%D8%B5-%D8%A8%D8%A7%D8%B1%D9%86%D8%B2%E2%80%8F-%D9%84%D9%8A%D8%B3-%D9%85%D9%8A%D8%B3%D9%8A-%D8%A7%D9%94%D9%88-%D8%B1%D9%88%D9%86%D8%A7%D9%84%D8%AF%D9%88--%D8%A7%D9%94%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D9%84%D9%8A%D9%81%D8%B1%D8%A8%D9%88%D9%84-%D9%8A%D9%82%D9%84%D9%84-%D9%85%D9%86-%D8%A8%D9%8A%D9%84%D9%8A%D9%86%D8%AC%D9%87%D8%A7%D9%85/blt7bdb92f2ac6b7924','https://www.goal.com/ar/%D8%A7%D9%84%D9%82%D9%88%D8%A7%D8%A6%D9%85/%D8%AE%D8%A7%D8%B5-%D8%A8%D8%A7%D8%B1%D9%86%D8%B2%E2%80%8F-%D9%84%D9%8A%D8%B3-%D9%85%D9%8A%D8%B3%D9%8A-%D8%A7%D9%94%D9%88-%D8%B1%D9%88%D9%86%D8%A7%D9%84%D8%AF%D9%88--%D8%A7%D9%94%D8%B3%D8%B7%D9%88%D8%B1%D8%A9-%D9%84%D9%8A%D9%81%D8%B1%D8%A8%D9%88%D9%84-%D9%8A%D9%82%D9%84%D9%84-%D9%85%D9%86-%D8%A8%D9%8A%D9%84%D9%8A%D9%86%D8%AC%D9%87%D8%A7%D9%85/blt7bdb92f2ac6b7924','','','','السعودية','2026-08-14T02:16:00.000Z','Wed, 07 Oct 2026 18:37:48 GMT','2026-08-14T23:38:21.974Z','https://assets.goal.com/images/v3/bltc43b59614e963c63/GOAL%20-%20Multiple%20Images%20-%203%20Split%20-%20Facebook%20-%202026-08-12T104613.402.png','/api/media/56ea1e77-3fac-48de-bfbb-69b60cbc9094','/api/media/56ea1e77-3fac-48de-bfbb-69b60cbc9094?variant=thumbnail','Jude Bellingham Cristiano Ronaldo Lionel Messi 2026',1920,1080,'valid','published','archived','valid',89,'4105be8e4a3ade80d621b02be9d29ec9cfea07ebfc875a8c672488e866a8075d','18d27897fb071a8ef7e2fa551e3148512ac6639868d90f620cfd0a9fa9a52066','محدّث','2026-08-14T23:38:21.974Z','2026-10-07T20:57:12.522Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["العالم","روسيا"]','[]','manual_approved','','[]','Temporarily Unreachable','2026-10-07T20:57:12.522Z',NULL,81,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('566fb1a9-5c2f-4506-ac6d-23e256a10250','news-566fb1a9-5c2f-4506-ac6d-23e256a10250','المنتخب السعودي يحقق الميدالية البلاتينية الأولى في تاريخه بأولمبياد المواصفات الدولي','المنتخب السعودي يحقق الميداليه البلاتينيه الاولي في تاريخه باولمبياد المواصفات الدولي','حقق المنتخب السعودي للمواصفات إنجازاً تاريخياً بفوزه بالميدالية البلاتينية للمرة الأولى في تاريخ مشاركاته، إلى جانب ميداليتَي الفضة والبرونز، في الدورة الحادية والعشرين من الأولمبياد الدولي للمواصفات «The 21st International Standards Olympiad»، المُقام في جمهورية كوريا خلال الفترة من 12 حتى 14 أغسطس الجاري، بمشاركة 105 طلاب وطالبات يمثلون 11 دولة.','["وتُعدّ الميدالية البلاتينية أعلى جوائز الأولمبياد، إذ تُمنح لفريق واحد فقط من بين جميع الفرق المشاركة، وتحمل جائزة رئيس وزراء جمهورية كوريا.","وجاء الفوز بالميدالية البلاتينية من نصيب فريق الطالبات في المرحلة المتوسطة، الذي ضمّ: زهراء بنت رياض أبو كبوس من الإدارة العامة للتعليم بالمنطقة الشرقية، ويمان بنت أيمن الزهر من الإدارة العامة للتعليم بمنطقة عسير، وهيا بنت عادل آل سليمان من الإدارة العامة للتعليم بالمنطقة الشرقية.","فيما حصد فريق الطلاب في المرحلة المتوسطة الميدالية الفضية، وضمّ: حسن بن إبراهيم حسوبة من الإدارة العامة للتعليم بمنطقة المدينة المنورة، وعبدالإله بن سهيل باجمال من الإدارة العامة للتعليم بمحافظة جدة، وريان بن محمد اللقماني من الإدارة العامة للتعليم بالمنطقة الشرقية.","ونالت الميدالية البرونزية فريقُ الطالبات في المرحلة المتوسطة أيضاً، وضمّ: لينة بنت أشرف الفقيه من الإدارة العامة للتعليم بالمنطقة الشرقية، ووجد بنت إيهاب حسوبة من الإدارة العامة للتعليم بمنطقة المدينة المنورة، وميان بنت زهير خان من الإدارة العامة للتعليم بمنطقة مكة المكرمة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/g8bzy6m','https://sabq.org/article/g8bzy6m','','https://sabq.org/article/g8bzy6m','صحيفة سبق','السعودية','2026-08-14T09:42:00.000Z','2026-08-14T12:44:00.000Z','2026-08-14T23:38:27.847Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/655af83e-404d-4478-dfca-2c61b74cc600/public','/api/media/566fb1a9-5c2f-4506-ac6d-23e256a10250','/api/media/566fb1a9-5c2f-4506-ac6d-23e256a10250?variant=thumbnail','المنتخب السعودي يحقق الميدالية البلاتينية الأولى في تاريخه بأولمبياد المواصفات الدولي',1600,1200,'valid','published','archived','valid',58,'95a4fdbf8594ce63a7ff01a844f03b3d7131a8e3cd171115a5e4c3bb83796985','e77ea31567eb5c2c4db03b7ece3cb8d920f45c9e695380531b4c1f1b0c06430e','محدّث','2026-08-14T23:38:27.847Z','2026-10-07T20:50:56.781Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس وزراء جمهورية كوريا وجاء","التعليم والتدريب","مكة","جدة","عسير","المدينة المنورة"]','["رئيس وزراء جمهورية كوريا وجاء","التعليم والتدريب","المدينة المنورة"]','manual_approved','ambiguous_category','[{"category":"التعليم","score":7},{"category":"أخبار السعودية","score":3},{"category":"الاقتصاد","score":3}]','Active','2026-10-07T20:50:56.781Z',200,84,0,'source_article_available','',NULL,NULL,'body:413d37715472a7888c425945d1f220e928f1a94428a5ffffabe89578261ec6ab','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d2067ed6-60ec-4680-880c-067a14d6a4b4','news-d2067ed6-60ec-4680-880c-067a14d6a4b4','السفير الأميركي في لبنان: تسليم حزب الله سلاحه يوقف الحرب فوراً','السفير الاميركي في لبنان تسليم حزب الله سلاحه يوقف الحرب فورا','أكد السفير الأميركي في لبنان ميشال عيسى، عقب لقائه رئيس مجلس النواب اللبناني نبيه بري في منطقة عين التينة، أن «كل شيء سيتوقف إذا سلّم حزب الله سلاحه»، مشيراً إلى أن المفاوضات بين لبنان وإسرائيل «مستمرة»، وأن موعد الجولة التالية «لم يُحدَّد بعد»، واصفاً الأجواء العامة بأنها «إيجابية».','["وردّاً على أسئلة الصحفيين حول موعد وقف الحرب، قال السفير: «الحرب ستتوقف عندما يحين الوقت»، مضيفاً: «قولوا لحزب الله أن يسلّم سلاحه، فيتوقف كل شيء».","وبشأن المناطق التجريبية، أوضح عيسى أن الأولوية تكمن في «تحديد وضع المناطق الحالية أولاً، قبل الانتقال إلى مناطق أخرى»، لافتاً إلى أن «هناك لائحة من الدول التي يجري التفاوض معها للمشاركة في آلية المراقبة، غير أنه لم يُحدَّد حتى الآن أي منها».","وأشار إلى أن زيارته لبري «تهدف إلى إطلاعه مباشرة على ما يجري، وشرح التطورات والخيارات المطروحة بعيداً عمّا يُتداول عبر وسائل الإعلام».","في المقابل، أكد رئيس مجلس النواب اللبناني نبيه بري، خلال لقائه السفير عيسى ورئيس مجموعة التنسيق العسكري الخاصة بلبنان الجنرال جوزيف كليرفيلد، أن «مفتاح الاستقرار يكمن في إلزام إسرائيل وقف حربها والانسحاب إلى الحدود الدولية»."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/d1t1169','https://sabq.org/article/d1t1169','','https://sabq.org/article/d1t1169','صحيفة سبق','السعودية','2026-08-14T10:09:00.000Z','2026-08-14T13:09:00.000Z','2026-08-14T23:38:28.459Z','https://media.sabq.org/news/2026/08/d978681c-b6f2-496a-b584-c135f477107c/w801.webp','/api/media/d2067ed6-60ec-4680-880c-067a14d6a4b4','/api/media/d2067ed6-60ec-4680-880c-067a14d6a4b4?variant=thumbnail','السفير الأميركي في لبنان: تسليم حزب الله سلاحه يوقف الحرب فوراً',801,451,'valid','published','archived','valid',71,'daa3fb2d3e2b927fa444ef6b49b792b3f7907a5e1dda087f9352d22040b4be3b','c6b1a3e09a55a2507f6f2de196c3747a12e3e7eca988df515665b68cb7d5ba63','محدّث','2026-08-14T23:38:28.459Z','2026-10-07T20:50:50.269Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس النواب اللبناني نبيه بري","رئيس مجلس النواب اللبناني نبيه","لبنان"]','["مجلس النواب اللبناني نبيه بري","رئيس مجلس النواب اللبناني نبيه"]','manual_approved','','[]','Active','2026-10-07T20:50:50.269Z',200,82,0,'source_article_available','',NULL,NULL,'body:58889943ea88afec07af0f5b581c95edb1b19cef514bb3cfa7f678bc6286629b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b258fca6-a677-483e-b610-265da0f5a808','news-b258fca6-a677-483e-b610-265da0f5a808','بقعتا نفط في الخليج وكارثة بيئية تتصاعد قبالة عُمان وسط حرب الناقلات','بقعتا نفط في الخليج وكارثه بيئيه تتصاعد قباله عمان وسط حرب الناقلات','كشفت صور أقمار صناعية ولقطات فيديو تحققت منها وكالة رويترز عن ظهور بقعتين نفطيتين في المياه الإيرانية بالخليج، في وقت تُثير فيه الهجمات المتبادلة بين طهران وواشنطن على ناقلات النفط والسفن التجارية مخاوف متصاعدة بشأن الأضرار البيئية التي قد تلحق بالمنطقة.','["وتتكشّف بالتوازي كارثة بيئية محتملة قبالة سواحل سلطنة عُمان خارج مضيق هرمز، إذ تتسرب كميات من النفط الخام الروسي من الناقلة «كارولاين بيزينجي» الجانحة في منطقة بحرية محمية، مما أفضى إلى تكوّن بقعة نفطية ضخمة تُقدّر بعض التقديرات مساحتها بنحو ألفي كيلومتر مربع.","ولم يُربط حادث هذه الناقلة بالحرب الأمريكية الإسرائيلية على إيران.","بقعة قرب جزيرة قشم رصدت صور أقمار «سينتينيل-2» الصناعية التابعة لبرنامج كوبرنيكوس بقعةً نفطية قبالة الطرف الجنوبي لجزيرة قشم الكبيرة في مضيق هرمز.","وأوضح الباحث البيئي فيم زفينينبرج من منظمة «باكس» الهولندية للسلام أن اللون الداكن في أجزاء من البقعة يدل على أنها زيت وقود ثقيل، فيما امتدت بقعة مخففة أفتح لوناً على مسافة 160 كيلومتراً تقريباً."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7thd9p5','https://sabq.org/article/7thd9p5','','https://sabq.org/article/7thd9p5','صحيفة سبق','السعودية','2026-08-14T09:48:00.000Z','2026-08-14T12:49:00.000Z','2026-08-14T23:38:29.609Z','https://media.sabq.org/news/2026/08/2468f79d-793c-44c9-8829-e549dff3fc4d/w960.webp','/api/media/b258fca6-a677-483e-b610-265da0f5a808','/api/media/b258fca6-a677-483e-b610-265da0f5a808?variant=thumbnail','بقعتا نفط في الخليج وكارثة بيئية تتصاعد قبالة عُمان وسط حرب الناقلات',960,695,'valid','published','archived','valid',100,'06b3353d4931fe76e4b1647c08744dd7d4bcf14ff87bedf7041b52d11003f2e6','06ee81c65a293df26316c419a97514a46bf6a2447cfa21293f536ec46cc4b92d','محدّث','2026-08-14T23:38:29.609Z','2026-10-07T20:50:50.271Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","إيران"]','["الطاقة والنفط"]','manual_approved','','[]','Active','2026-10-07T20:50:50.271Z',200,81,0,'source_article_available','',NULL,NULL,'body:9308ca2fdb9c406ecab2e0d0ac3d266d61b54ec10b3e2081193e49556588bd2d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('77066c91-9a6d-4dcb-a2e5-302c7e6096d7','news-77066c91-9a6d-4dcb-a2e5-302c7e6096d7','صوف الأغنام قد يفتح بابًا جديدًا لترميم العظام.. تفوق بنيوي على الكولاجين','صوف الاغنام قد يفتح بابا جديدا لترميم العظام تفوق بنيوي علي الكولاجين','في اكتشاف قد يُعيد رسم خريطة المواد المستخدمة في الطب التجديدي، توصل باحثون إلى أن الكيراتين المستخلص من صوف الأغنام يمكن أن يدعم تجدد العظام المتضررة، وذلك بعد أن أظهرت تجارب على الحيوانات قدرة المادة على المساعدة في تكوين أنسجة عظمية جديدة أكثر انتظاماً من الناحية البنيوية وأقرب إلى العظام الطبيعية السليمة مقارنةً بالأنسجة التي تشكّلت باستخدام دعامات الكول','["ويستند الاكتشاف إلى «الكيراتين»، وهو بروتين بنيوي طبيعي يُشكّل أحد المكونات الرئيسية للصوف، إذ أظهرت التجارب أن تحويل هذا البروتين إلى أغشية ودعامات مخصصة يمكن أن يساعد في توجيه نمو عظام جديدة داخل المناطق المتضررة.","ويرى الباحثون أن هذه النتائج قد تمهّد الطريق أمام تطوير مواد حيوية جديدة لإصلاح العظام، وفق ما نشره موقع «Science Daily».","ولا تقتصر أهمية الاكتشاف على الجانب الطبي؛ إذ يرى باحثون من كلية طب الأسنان وعلوم الفم والوجه والفكين في كلية كينغز لندن أن استخدام الصوف يحمل أيضاً ميزة بيئية واستدامية، فالصوف مادة طبيعية متجددة، وكثيراً ما يُتخلص من كميات منه باعتبارها مخلفات في القطاع الزراعي.","وقال الباحث في كلية كينغز لندن شريف الشرقاوي: «نحن متحمسون للغاية لإظهار، للمرة الأولى، كيفية اختبار مادة قائمة على الصوف بنجاح داخل كائن حي لإصلاح العظام»."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/4gap1eu','https://sabq.org/article/4gap1eu','','https://sabq.org/article/4gap1eu','صحيفة سبق','السعودية','2026-08-14T09:38:00.000Z','2026-08-14T12:39:00.000Z','2026-08-14T23:38:30.823Z','https://media.sabq.org/news/2026/08/148ebd60-50f6-4b31-afdb-479c41198307/w801.webp','/api/media/77066c91-9a6d-4dcb-a2e5-302c7e6096d7','/api/media/77066c91-9a6d-4dcb-a2e5-302c7e6096d7?variant=thumbnail','صوف الأغنام قد يفتح بابًا جديدًا لترميم العظام.. تفوق بنيوي على الكولاجين',801,451,'valid','published','archived','valid',40,'e02c37fbbdf56af97d9eab402c4282b6e92623096c0780126734d54557a6118a','a6d020aefba4c42f2451982994dfca3ee7dd6bc523dbb994e7fcfc7d5ffe87e2','محدّث','2026-08-14T23:38:30.823Z','2026-10-07T20:50:53.639Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"الصحة","score":1.5},{"category":"البيئة والمناخ","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:50:53.639Z',200,81,0,'source_article_available','',NULL,NULL,'body:787dca3494548d392ea8e91103e8aa6f5e3a25d4485c1b874e792ea33e90c50f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9e3d7020-0385-4c38-b503-28e34fea08e7','news-9e3d7020-0385-4c38-b503-28e34fea08e7','واشنطن تطالب "نتنياهو" بإدانة حصار المستوطنين لمنازل فلسطينيين في قصرة','واشنطن تطالب نتنياهو بادانه حصار المستوطنين لمنازل فلسطينيين في قصره','تضغط الولايات المتحدة على رئيس الوزراء الإسرائيلي بنيامين نتنياهو لإدانة المستوطنين المتشددين علناً، بعد محاصرتهم فلسطينيين داخل منازلهم في بلدة قصرة بالضفة الغربية المحتلة منذ نحو أسبوع.','["وبحسب وكالة رويترز، قال مسؤول أمريكي وآخر إسرائيلي، الجمعة، إن مسؤولين في البيت الأبيض يريدون من نتنياهو التنديد علناً بتصرفات المستوطنين، وسط تصاعد الانتقادات لما يجري في البلدة الواقعة جنوب نابلس.","وأوضح المسؤولان، اللذان طلبا عدم الكشف عن هويتيهما، أن التحرك الأمريكي بدأ بعدما علمت واشنطن بأن منزلاً يعود لفلسطيني يحمل الجنسية الأمريكية كان من بين المنازل المستهدفة.","ولم يعلق نتنياهو حتى الآن على حصار المنازل في قصرة، كما لم يرد مكتبه أو البيت الأبيض على طلبات رويترز للتعليق. «إرهابيون إسرائيليون» وكان السفير الأمريكي لدى إسرائيل مايك هاكابي قد وجّه، الخميس، انتقاداً علنياً حاداً للمستوطنين المشاركين في حصار أحد المنازل الفلسطينية، واصفاً إياهم بأنهم «إرهابيون إسرائيليون».","ويكتسب موقف هاكابي أهمية خاصة بالنظر إلى مواقفه المعروفة بتأييد الاستيطان الإسرائيلي في الضفة الغربية."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/4idtwky','https://sabq.org/article/4idtwky','','https://sabq.org/article/4idtwky','صحيفة سبق','السعودية','2026-08-14T09:33:00.000Z','2026-08-14T12:34:00.000Z','2026-08-14T23:38:31.078Z','https://media.sabq.org/news/2026/08/954dc039-c32c-40e3-b719-3211243de1a1/w801.webp','/api/media/9e3d7020-0385-4c38-b503-28e34fea08e7','/api/media/9e3d7020-0385-4c38-b503-28e34fea08e7?variant=thumbnail','واشنطن تطالب "نتنياهو" بإدانة حصار المستوطنين لمنازل فلسطينيين في قصرة',801,451,'valid','published','archived','valid',98,'c168c5dd743e23a71f36c00ab4fbdf9975d8dce00639a7d3de069166928e0c61','7376b6666fdcf0ac7c210d6e836c82c9c662ce7327c933b373d2c0a4a067f5d2','محدّث','2026-08-14T23:38:31.078Z','2026-10-07T20:51:02.628Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["فلسطين"]','[]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:51:02.628Z',200,80,0,'source_article_available','',NULL,NULL,'body:9ed849e8f00260915c745f2f2e25666be74bab95cd2d4c9090bb25da5f2b8be1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('809736be-107b-41fe-a436-79a56ad002e7','news-809736be-107b-41fe-a436-79a56ad002e7','القوات اليمنية تحبط هجوماً حوثياً واسعاً في تعز وتكبّد المليشيا خسائر فادحة','القوات اليمنيه تحبط هجوما حوثيا واسعا في تعز وتكبد المليشيا خسائر فادحه','أحبطت القوات المسلحة اليمنية، فجر اليوم، هجوماً شنّته مليشيات الحوثي الإرهابية المدعومة من النظام الإيراني على مواقعها في جبهة البرح غربي محافظة تعز، وذلك بعد مواجهات عنيفة أسفرت عن تكبيد المليشيا خسائر فادحة في الأرواح والعتاد.','["وأوضح مصدر عسكري لوكالة الأنباء اليمنية «سبأ»، أن المليشيات دفعت بأعداد كبيرة من عناصرها في هجوم على مواقع القوات المسلحة، مستخدمةً مختلف أنواع الأسلحة، بما فيها المدفعية وقذائف الهاون والطيران المسيّر، غير أن القوات المسلحة كانت على أهبة الاستعداد، وتمكّنت من رصد التحركات المعادية والتعامل معها بكفاءة عالية.","وأشار المصدر إلى أن المواجهات أسفرت عن مقتل وإصابة العشرات من عناصر المليشيات الحوثية، فضلاً عن تدمير وإحراق عدد من الأطقم والثكنات والمدافع والآليات العسكرية التابعة لها.","ولفت المصدر إلى أن الهجوم يأتي في إطار محاولات المليشيات الحوثية التعويض عن خسائرها الأخيرة في الجبهات الغربية، مؤكداً أن القوات المسلحة نجحت في إفشال الهجوم وإلحاق خسائر فادحة بالمهاجمين، وإجبار من تبقّى منهم على الفرار."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7oruwz1','https://sabq.org/article/7oruwz1','','https://sabq.org/article/7oruwz1','صحيفة سبق','السعودية','2026-08-14T09:17:00.000Z','2026-08-14T12:18:00.000Z','2026-08-14T23:38:32.111Z','https://media.sabq.org/news/2026/08/2bb43a3a-6497-4b74-8d89-b89d2b82ee71/w497.webp','/api/media/809736be-107b-41fe-a436-79a56ad002e7','/api/media/809736be-107b-41fe-a436-79a56ad002e7?variant=thumbnail','القوات اليمنية تحبط هجوماً حوثياً واسعاً في تعز وتكبّد المليشيا خسائر فادحة',497,280,'valid','published','archived','valid',46,'07c8a788b47546622d4e72a09689221ceb207178f081ff4f2ae42a115c0500c1','7d710c4a589eb63212fe439de0248eb375814831056867c1b226cb1d2606e537','محدّث','2026-08-14T23:38:32.111Z','2026-10-07T20:50:50.266Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","اليمن"]','["السفر والسياحة"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:50:50.266Z',200,84,0,'source_article_available','',NULL,NULL,'body:854535e7262773abe786d48014b9bf6b6bfdb3b6d2202d341c28adae3d601440','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('edb81ef2-2e97-4755-93e5-9ab0b545cd04','news-edb81ef2-2e97-4755-93e5-9ab0b545cd04','هلال ربيع الأول يزيّن سماء المملكة الليلة.. فرصة للرصد والتصوير بعد الغروب','هلال ربيع الاول يزين سماء المملكه الليله فرصه للرصد والتصوير بعد الغروب','تشهد سماء المملكة بعد غروب شمس اليوم فرصة لرصد هلال شهر ربيع الأول باتجاه الأفق الغربي، في مشهد مناسب للرصد والتصوير عند صفاء الأجواء.','["وأفاد رئيس الجمعية الفلكية بجدة المهندس ماجد أبو زاهرة أن القمر وصل إلى منزلة الاقتران يوم الأربعاء 12 أغسطس عند الساعة 08:37 مساءً بتوقيت مكة المكرمة، إيذانًا ببداية دورة قمرية جديدة، ليبدأ بعدها الهلال بالابتعاد تدريجيًا عن الشمس والارتفاع في سماء المساء.","وأشار إلى أنه يمكن خلال رصد الهلال ملاحظة ظاهرة نور الأرض التي تظهر الجزء غير المضاء من القمر بإضاءة خافتة نتيجة انعكاس ضوء الشمس عن سطح الأرض، فيما يواصل القمر انتقاله شرقًا بين النجوم من ليلة إلى أخرى."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/a6b7z14','https://sabq.org/article/a6b7z14','','https://sabq.org/article/a6b7z14','صحيفة سبق','السعودية','2026-08-14T08:49:00.000Z','2026-08-14T11:49:00.000Z','2026-08-14T23:38:33.245Z','https://media.sabq.org/news/2026/08/e0398d18-01fb-44f3-ad69-dac063c27eff/w828.webp','/api/media/edb81ef2-2e97-4755-93e5-9ab0b545cd04','/api/media/edb81ef2-2e97-4755-93e5-9ab0b545cd04?variant=thumbnail','هلال ربيع الأول يزيّن سماء المملكة الليلة.. فرصة للرصد والتصوير بعد الغروب',828,554,'valid','published','archived','valid',44,'2bb2dcd8d61b942e87614c6536c01ed32ff527b7da741470403da4e37a3ce6f5','d3728f59b5f089d903681a2a2374e9c9ee93fa33432fda00b3a2910adc8d517e','محدّث','2026-08-14T23:38:33.245Z','2026-10-07T20:50:54.709Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس الجمعية الفلكية بجدة المهندس","مكة","جدة"]','["رئيس الجمعية الفلكية بجدة المهندس"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":3},{"category":"المجتمع","score":1.5},{"category":"السياسة","score":0}]','Active','2026-10-07T20:50:54.709Z',200,80,0,'source_article_available','',NULL,NULL,'body:5c842dd4fa501d98e2ac81989f3bd68df279a09d4ab88a4c7d9e76bb14b07db7','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b19cecf4-48c2-4eea-bb33-99732c8de9ce','news-b19cecf4-48c2-4eea-bb33-99732c8de9ce','حريق ضخم يلتهم غابات كرواتيا ويُصيب 40 شخصاً ويُجلي آلاف السياح','حريق ضخم يلتهم غابات كرواتيا ويصيب 40 شخصا ويجلي الاف السياح','أصيب 40 شخصاً على الأقل، عشرة منهم بحالات خطرة، جراء حريق ضخم اندلع في غابات الساحل الكرواتي منذ مساء الخميس واستمر حتى الجمعة، مطالاً مناطق سكنية وسياحية.','["وأعلن رئيس جهاز الإطفاء الكرواتي سلافكو توكاكوفيتش، في بيان رسمي، أن هذا الحريق يُعدّ الأسوأ في تاريخ كرواتيا، مشيراً إلى أن النيران دمّرت ما بين 900 و1000 هكتار من الأراضي، وتسببت في أضرار جسيمة أجبرت أكثر من ألفي سائح ومقيم على إخلاء أماكن إقامتهم.","وأوضح توكاكوفيتش أن الحريق اندلع في منطقة «لوكفا روغوزنيتسا» الساحلية، وأجّجته الرياح الشديدة التي أشعلت في البداية غابات الصنوبر والنباتات، قبل أن تمتد النيران إلى المنازل في هذه المنطقة السياحية، ثم تتوسع لكيلومترات نحو بلدات وقرى أخرى باتجاه مدينة «أوميش».","وأشار إلى أن 300 عنصر إطفاء شاركوا في عمليات الإخماد، غير أن النيران كانت تتقدم بوتيرة أسرع من جهودهم الميدانية."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/46vzxns','https://sabq.org/article/46vzxns','','https://sabq.org/article/46vzxns','صحيفة سبق','السعودية','2026-08-14T08:43:00.000Z','2026-08-14T11:44:00.000Z','2026-08-14T23:38:33.318Z','https://media.sabq.org/news/2026/08/bf98e64e-789b-4405-a394-fe8b34ce5ecc/w1600.webp','/api/media/b19cecf4-48c2-4eea-bb33-99732c8de9ce','/api/media/b19cecf4-48c2-4eea-bb33-99732c8de9ce?variant=thumbnail','حريق ضخم يلتهم غابات كرواتيا ويُصيب 40 شخصاً ويُجلي آلاف السياح',1600,900,'valid','published','archived','valid',35,'c2be62c2cfe53c7ceea300de43ea6024aaab5343233168a84b798112bcb1e9b9','0691a81dece83d21b90edf92383c3d74585f0a3f496e66e1d6dd75a32be01c43','محدّث','2026-08-14T23:38:33.318Z','2026-10-07T20:50:50.879Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس جهاز الإطفاء الكرواتي سلافكو"]','["رئيس جهاز الإطفاء الكرواتي سلافكو"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T20:50:50.879Z',200,81,0,'source_article_available','',NULL,NULL,'body:d5591aeb8d7936a1e4d852278f29a40c8f58ceadff18f5ef4574166626cb8277','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f1b4f4b9-a151-47e0-861c-bcdeeefb71c2','news-f1b4f4b9-a151-47e0-861c-bcdeeefb71c2','8 قتلى في فيضانات وأمطار غزيرة اجتاحت شرقي اليابان','8 قتلي في فيضانات وامطار غزيره اجتاحت شرقي اليابان','لقي ثمانية أشخاص حتفهم جراء أمطار غزيرة اجتاحت شرقي اليابان منذ يوم الخميس وامتدت حتى الجمعة، في كارثة طبيعية أثارت حالة من الطوارئ في عدد من المحافظات.','["وأعلنت وكالة الأرصاد الجوية اليابانية أنها أصدرت أعلى مستويات التحذير من الأمطار الغزيرة «المستوى 5» في أكثر من ثلث بلديات محافظة تشيبا المجاورة للعاصمة طوكيو، مع رصد فيضانات واسعة النطاق في الطرق العامة.","وحثّت السلطات المواطنين في مدينتي تشيبا وإيتشيكاوا وعدد من البلدات المجاورة على اتخاذ إجراءات السلامة الفورية، في ظل تصاعد خطر الفيضانات وانهيار البنية التحتية.","كما أصدرت الوكالة تحذيرات من انهيارات أرضية عند «المستوى 5» لعدد من بلدات المحافظة، شملت تشيبا ومجاورتها إيتشيهارا، قبل أن تُخفَّض جميع مستويات التحذير لاحقاً في اليوم ذاته."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ylwhfoa','https://sabq.org/article/ylwhfoa','','https://sabq.org/article/ylwhfoa','صحيفة سبق','السعودية','2026-08-14T08:55:00.000Z','2026-08-14T11:55:00.000Z','2026-08-14T23:38:33.334Z','https://media.sabq.org/news/2026/08/477e53eb-b0ff-4a77-a6cb-db3c8c9e960c/w770.webp','/api/media/f1b4f4b9-a151-47e0-861c-bcdeeefb71c2','/api/media/f1b4f4b9-a151-47e0-861c-bcdeeefb71c2?variant=thumbnail','8 قتلى في فيضانات وأمطار غزيرة اجتاحت شرقي اليابان',770,470,'valid','published','archived','valid',48,'b94311bf1d0a7a8dbd7dc4ebcee2a9df560817df48593386b5c89cfa2dffcdd4','be2c4346202027ea2798ff961565968eda883e8e624cc060acd320dafe200e7d','محدّث','2026-08-14T23:38:33.334Z','2026-10-07T20:51:37.257Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ"]','["الطقس والمناخ"]','manual_approved','below_category_threshold','[{"category":"السفر","score":3},{"category":"البيئة والمناخ","score":3},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T20:51:37.257Z',200,84,0,'source_article_available','',NULL,NULL,'body:781cb8d61241503b87e4c272220e280ec09e0a49964bebf107bd91ae631d68d9','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cfc33753-2d24-4903-b2f3-b6ada704ed9c','news-cfc33753-2d24-4903-b2f3-b6ada704ed9c','ماجد الهجلة يحتفل بزواجه في المدينة المنورة بحضور الشعراء والأقارب','ماجد الهجله يحتفل بزواجه في المدينه المنوره بحضور الشعراء والاقارب','احتفل الشاب ماجد عبدالله الهجلة بزواجه في إحدى قاعات الأفراح بالمدينة المنورة، وسط حضور لفيف من الأقارب والأصدقاء والمدعوين.','["وشارك في الحفل عدد من الشعراء الذين أضفوا على المناسبة بهجة خاصة، وقدّموا للعريس التهاني والتبريكات بهذه المناسبة السعيدة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/vlctnqo','https://sabq.org/article/vlctnqo','','https://sabq.org/article/vlctnqo','صحيفة سبق','السعودية','2026-08-14T08:32:00.000Z','2026-08-14T11:33:00.000Z','2026-08-14T23:38:34.874Z','https://media.sabq.org/news/2026/08/6b34defe-fc23-4f39-b3e0-ca8cecb38987/w1280.webp','/api/media/cfc33753-2d24-4903-b2f3-b6ada704ed9c','/api/media/cfc33753-2d24-4903-b2f3-b6ada704ed9c?variant=thumbnail','ماجد الهجلة يحتفل بزواجه في المدينة المنورة بحضور الشعراء والأقارب',1280,853,'valid','published','archived','valid',47,'49078d28a2dcf839dfeb08ce93300f4d548b0730a018d42024209330c42eec69','6bee4ec48cb6adcb4b4885e1fcdff0644bbcd32d447fe702d029eea246288ab7','محدّث','2026-08-14T23:38:34.874Z','2026-10-07T20:51:38.729Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["المدينة المنورة"]','["المدينة المنورة"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T20:51:38.729Z',200,82,0,'source_article_available','',NULL,NULL,'body:563dc5d554ddaf687edb2eb9bb1729329549f08b834ed3c6b3021e3e2092fb71','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('77655e80-2422-435f-b764-75a9e60d8c49','news-77655e80-2422-435f-b764-75a9e60d8c49','ترامب: سأعلن قريبًا مضيق هرمز أرضاً تابعة للولايات المتحدة','ترامب ساعلن قريبا مضيق هرمز ارضا تابعه للولايات المتحده','الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية أكد الرئيس الأمريكي السابق دونالد ترامب ، أنه سيعلن قريبًا أن مضيق هرمز أرض تابعة للولايات المتحدة، مع استمرار التوترات في المنطقة، والحصار المتبادل مع إيران .','["أكد الرئيس الأمريكي السابق دونالد ترامب ، أنه سيعلن قريبًا أن مضيق هرمز أرض تابعة للولايات المتحدة، مع استمرار التوترات في المنطقة، والحصار المتبادل مع إيران .","وتابع ترامب، في تصريحات لقناة \" فوكس نيوز \"، أن الحصار البحري المفروض على إيران سيظل قائمًا، مشددًا على أن أي سفن لن تعبر مضيق هرمز إلا بإذن من الولايات المتحدة .","وأوضح ترامب أن واشنطن ستضرب إيران اقتصاديًا بقوة خلال الفترة المقبلة، معتبرًا أن ما تقوم به الإدارة الأمريكية مع إيران يمثل خدمة عظيمة للعالم بأسره وليس للولايات المتحدة فقط."]','العالم','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/i0uwkdtap','https://ajel.sa/international/i0uwkdtap','https://ajel.sa/international/i0uwkdtap','https://ajel.sa/international/i0uwkdtap','فريق التحرير','السعودية','2026-08-14T14:10:00.000Z','Wed, 07 Oct 2026 20:50:36 GMT','2026-08-15T01:39:30.744Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-rfHRvi6C.webp','/api/media/77655e80-2422-435f-b764-75a9e60d8c49','/api/media/77655e80-2422-435f-b764-75a9e60d8c49?variant=thumbnail','ترامب: سأعلن قريبًا مضيق هرمز أرضاً تابعة للولايات المتحدة',1200,675,'valid','published','archived','valid',46,'989c5aff978f8426545493dc9dd58b7d1d56e283d91449b1c9522327d38819d5','89a09c114ed22349ec58b052a72f6635cc016283b4f7ee284916ee746477b267',NULL,'2026-08-15T01:39:30.744Z','2026-10-07T20:50:37.955Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","إيران","الولايات المتحدة"]','["الاقتصاد والأسواق","الولايات المتحدة"]','manual_approved','below_category_threshold','[{"category":"السياسة","score":1.5},{"category":"الاقتصاد","score":1.5},{"category":"المجتمع","score":1.5}]','Updated','2026-10-07T20:50:37.955Z',200,87,0,'source_content_changed','',NULL,NULL,'body:c57c923627be0dc0fcbd26f35610a1178dfd00a9d59894130e83305f884fafd8','Wed, 07 Oct 2026 20:50:36 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('41268641-3a43-4084-97f3-9685f56477a1','news-41268641-3a43-4084-97f3-9685f56477a1','صندوق الاستثمارات العامة و«فورمولا إي» يطوران منصة «Driving Force» التعليمية بعد استفادة 111,200 طالب','صندوق الاستثمارات العامه و فورمولا اي يطوران منصه driving force التعليميه بعد استفاده 111 200 طالب','أطلق صندوق الاستثمارات العامة، بالشراكة مع «فورمولا إي»، نسخة مطورة من المنصة التعليمية «Driving Force Presented by PIF»، بهدف توسيع نطاق التعلم الإلكتروني وإتاحة محتوى تعليمي تفاعلي لعدد أكبر من الشباب حول العالم، يُمكّنهم من استكشاف مستقبل رياضة المحركات الكهربائية عبر مجالات العلوم والتقنية والهندسة والرياضيات.','["ويأتي هذا التطوير امتداداً للنجاح الذي حققه البرنامج منذ إطلاقه في أبريل 2025م، إذ استفاد منه 111,200 طالب في 1,100 مدرسة بالمملكة العربية السعودية والولايات المتحدة الأمريكية والمملكة المتحدة، من بينهم أكثر من 4,500 طالب داخل المملكة، من خلال نموذج تعليمي متكامل شمل ورش عمل مباشرة في الرياض وجدة وعدد من المدن العالمية، إضافةً إلى محتوى وخطط تدريسية للمعلمين ومواد تعليمية تفاعلية عبر المنصة الإلكترونية.","وتوفر النسخة المطورة تجارب رقمية مخصصة لثلاث فئات: الشباب الذين يحصلون على تحديات تفاعلية واختبارات وألعاب وجوائز تُقدّم مجالات العلوم والتقنية والهندسة والرياضيات بأسلوب جذاب، وأولياء الأمور الذين يجدون محتوى يساعدهم على دعم اهتمامات أبنائهم واستكشاف المسارات المهنية في مجال التنقل، فضلاً عن المعلمين الذين يحصلون على خطط وأنشطة تعليمية جاهزة للاستخدام داخل الفصول الدراسية.","ويرتكز المحتوى الجديد للمنصة على سيارة «فورمولا إي» من الجيل الرابع التي أُطلقت مؤخراً، مما يتيح للمستخدمين التفاعل مع أجواء السباقات والتعرف على أحدث التقنيات ومعايير الاستدامة، على أن يُحدَّث المحتوى بصورة دورية لتعزيز التجربة التفاعلية والتشاركية لجميع المستخدمين حول العالم.","وفي هذا السياق، أوضح مدير إدارة الهوية المؤسسية في صندوق الاستثمارات العامة محمد الصياد، أن البرنامج «صُمم لإلهام الشباب وتمكينهم وتحفيزهم على الابتكار في مستقبل التنقل، إضافةً إلى تعزيز المهارات الفنية للكفاءات الوطنية في المجالات المرتبطة بقطاعات المستقبل»، مشيراً إلى أن وصول البرنامج إلى آلاف الطلبة في المملكة والعالم خلال عامه الأول يعكس أثر شراكات الصندوق ومبادراته."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/do333im','https://sabq.org/article/do333im','','https://sabq.org/article/do333im','صحيفة سبق','السعودية','2026-08-14T10:13:00.000Z','2026-08-14T13:14:00.000Z','2026-08-15T01:44:33.793Z','https://media.sabq.org/news/2026/08/e8bab3ea-cb60-459b-a69d-4fe70457b698/w1010.webp','/api/media/41268641-3a43-4084-97f3-9685f56477a1','/api/media/41268641-3a43-4084-97f3-9685f56477a1?variant=thumbnail','صندوق الاستثمارات العامة و«فورمولا إي» يطوران منصة «Driving Force» التعليمية بعد استفادة 111,200 طالب',1010,535,'valid','published','archived','valid',89,'429d2eee044274ead6edf661af7cb77554553be2ba18c262715b103cdbe4b129','c921bb6ce9dd9f4bfe9b0c50fb9226710e95bcf2463f924be38c4dbdc000458d','محدّث','2026-08-15T01:44:33.793Z','2026-10-07T20:50:48.419Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق","التقنية والتحول الرقمي","جدة","الرياض","الولايات المتحدة"]','["التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق","التقنية والتحول الرقمي","الولايات المتحدة"]','classified','','[{"category":"التعليم","score":6},{"category":"السيارات","score":4.5},{"category":"أخبار السعودية","score":3}]','Active','2026-10-07T20:50:48.419Z',200,90,0,'source_article_available','',NULL,NULL,'body:3f190d15eb7632ab6f7056caaf4bd18b326967d24894d0e74b264e6c35127431','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0360ec09-af9d-4ee1-9bd0-34d6e7985879','news-0360ec09-af9d-4ee1-9bd0-34d6e7985879','دوريات الأمن بالرياض تضبط سارق بطاريات مركبات بحوزته 9 بطاريات','دوريات الامن بالرياض تضبط سارق بطاريات مركبات بحوزته 9 بطاريات','ضبطت دوريات الأمن بمنطقة الرياض شخصاً رصدته كاميرات المراقبة في مقطع مرئي متداول، وهو يسرق بطارية مركبة متوقفة بمدينة الرياض.','["وأسفر الضبط عن العثور بحوزة الموقوف على 9 بطاريات، فيما جرى اتخاذ الإجراءات النظامية بحقه وإحالته إلى النيابة العامة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/prenmfe','https://sabq.org/article/prenmfe','','https://sabq.org/article/prenmfe','صحيفة سبق','السعودية','2026-08-14T10:24:00.000Z','2026-08-14T13:27:00.000Z','2026-08-15T03:50:06.857Z','https://media.sabq.org/news/2026/08/cea57fd6-6fdc-4599-a8e2-b18ea9e2d183/w1508.webp','/api/media/0360ec09-af9d-4ee1-9bd0-34d6e7985879','/api/media/0360ec09-af9d-4ee1-9bd0-34d6e7985879?variant=thumbnail','دوريات الأمن بالرياض تضبط سارق بطاريات مركبات بحوزته 9 بطاريات',1508,953,'valid','published','archived','valid',100,'9ca77f14f583f7e09fedeec601e705b82a60ad3a576a86f8044bf059a2dddaeb','df0e8a1887300dde896185097f0f4960e1879420bbb4de0e3adeff485a032e46','محدّث','2026-08-15T03:50:06.857Z','2026-10-07T20:50:49.670Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الرياضة السعودية","الرياض"]','["السفر والسياحة","الرياضة السعودية"]','manual_approved','','[]','Active','2026-10-07T20:50:49.670Z',200,80,0,'source_article_available','',NULL,NULL,'body:fa630d37201c55a92e633290365192b6ab7fb78f6773f5d1c9cdcfe3da56307a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7640b5e7-34fa-44c9-a9b6-fc1f17b69d57','news-7640b5e7-34fa-44c9-a9b6-fc1f17b69d57','عام / إجراءات تنظيمية متكاملة تعزز شفافية صفقات المزاد الدولي لمزارع إنتاج الصقور','عام اجراءات تنظيميه متكامله تعزز شفافيه صفقات المزاد الدولي لمزارع انتاج الصقور','الرياض 01 ربيع الأول 1448 هـ الموافق 14 أغسطس 2026 م واس يطبق المركز الوطني للصقور منظومة متكاملة من الإجراءات التنظيمية والقانونية والمالية في المزاد الدولي لمزارع إنتاج الصقور، المقام في مقره بمَلهم شمال مدينة الرياض حتى 25 أغسطس الجاري، لضمان حقوق البائعين والمشترين، وتوثيق عمليات المبايعة، وتعزيز الشفافية في جميع مراحل انتقال ملكية الصقور.','["وأوضح المتحدث الرسمي بالمركز الوطني للصقور وليد الطويل أن المركز يبذل جهودًا كبيرة لضمان حقوق جميع الأطراف في صفقات البيع، مشيرًا إلى أن رحلة البيع تبدأ باتفاق صاحب المزرعة والمشتري على قيمة الصقر، ثم التوجه إلى قسم المبيعات لإتمام إجراءات المبايعة الرسمية، التي تمر بعدة مراحل تضمن دقة البيانات وسلامة عملية التعاقد.","وقال الطويل: عقب الاتفاق ينقل الصقر إلى لجنة الفرز والعبث، التي تتولى التحقق من موقعه ضمن الفئة المناسبة وقياس مواصفاته بدقة بما يشمل الحجم والطول والعرض، للتأكد من مطابقة البيانات المسجلة للصقر المعروض.","وأضاف: بعد ذلك تنتقل المعاملة إلى اللجنة القانونية، حيث تُستكمل إجراءات المبايعة بتوقيع الطرفين بما يثبت عملية البيع ويحفظ حقوق البائع والمشتري ثم تحول المعاملة إلى القسم المالي، الذي يتولى استكمال إجراءات السداد وضمان تسليم قيمة الصقر من المشتري إلى صاحب مزرعة الإنتاج.","وأشار المتحدث الرسمي إلى أن الإجراءات تتواصل بتركيب الحجل للصقر، ثم الانتقال إلى قسم التسجيل لإدراجه في نظام السباقات بالمركز، بما يتيح توثيق بياناته وربطها بسجلاته الرسمية، ثم يمنح المشتري في المرحلة الأخيرة ورقة خروج معتمدة، تخوله إخراج الصقر من بوابة المزاد، بعد اكتمال جميع الإجراءات النظامية، لتختتم بذلك رحلة البيع ضمن مسار متكامل يجمع بين التنظيم والدقة وحماية الحقوق."]','الثقافة','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2653813?type=news&uuid=N2653813','https://spa.gov.sa/ar/N2653813?type=news&uuid=N2653813','N2653813','N2653813','','السعودية','2026-08-14T14:28:00.000Z','2026-08-04T11:55:00.000Z','2026-08-15T05:51:54.919Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10608120.jpg','/api/media/7640b5e7-34fa-44c9-a9b6-fc1f17b69d57','/api/media/7640b5e7-34fa-44c9-a9b6-fc1f17b69d57?variant=thumbnail','عام / إجراءات تنظيمية متكاملة تعزز شفافية صفقات المزاد الدولي لمزارع إنتاج الصقور',1600,1066,'valid','published','archived','valid',41,'9a431fc6d08b16af9dc132fdbb090a5d27b1c99ed9bf1889ad191811ede822b0','5b7c3bfe9135f24c8405b5196ac7885e160813923550b9e4d76c5bc236ed21bc','محدّث','2026-08-15T05:51:54.919Z','2026-10-07T20:50:59.748Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:50:59.748Z',200,77,0,'source_article_available','',NULL,NULL,'body:80f0d4747aeff484b2ec44e2f15cb8628f9c9bece95736d5645093638648c577','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9ff2fe8b-de1d-4fa8-b6a9-10dc1b4270b6','news-9ff2fe8b-de1d-4fa8-b6a9-10dc1b4270b6','"سنتكوم" تعترض 62 سفينة وتُعطّل 3 أخرى ضمن الحصار الأمريكي على إيران','سنتكوم تعترض 62 سفينه وتعطل 3 اخري ضمن الحصار الامريكي علي ايران','تواصل القوات البحرية الأمريكية عملياتها في بحر العرب لتطبيق الحصار المفروض على إيران، إذ كشفت القيادة المركزية الأمريكية «سنتكوم» أنه حتى 14 أغسطس، جرى تغيير مسار 62 سفينة تجارية، وتعطيل 3 سفن، فضلاً عن الصعود على متن سفينتين للتحقق من امتثالهما لقواعد الحصار.','["وتُشارك في هذه العمليات مروحيات من طراز MH-60R Sea Hawk، التي تُنفّذ طلعات جوية ليلية انطلاقاً من الطرّاد المزوّد بصواريخ موجّهة يو إس إس برينستون (CG 59)، الذي يُعدّ أحد أبرز الأصول البحرية الأمريكية المنتشرة في المنطقة.","وتأتي هذه العمليات في إطار الجهود الأمريكية الرامية إلى تشديد الضغط على إيران عبر تطبيق إجراءات بحرية صارمة تستهدف السفن التجارية المشتبه في انتهاكها قواعد الحصار."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/x8d9rkd','https://sabq.org/article/x8d9rkd','','https://sabq.org/article/x8d9rkd','صحيفة سبق','السعودية','2026-08-14T10:26:00.000Z','2026-08-14T13:26:00.000Z','2026-08-15T05:56:13.974Z','https://media.sabq.org/news/2026/08/b5f23525-eb27-439b-8da2-07406f26f240/w1200.webp','/api/media/9ff2fe8b-de1d-4fa8-b6a9-10dc1b4270b6','/api/media/9ff2fe8b-de1d-4fa8-b6a9-10dc1b4270b6?variant=thumbnail','"سنتكوم" تعترض 62 سفينة وتُعطّل 3 أخرى ضمن الحصار الأمريكي على إيران',1200,800,'valid','published','archived','valid',94,'5caf1ad3f12fd210ce4206aada9bd7607d0a139e8bce419d96a268facddc0f8e','7d469a20306ec8f10010739b85262d897e67b667ac0bdae1b76438fab3c9effa','محدّث','2026-08-15T05:56:13.974Z','2026-10-07T20:50:49.650Z','','',0,0,'saudi_region','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["إيران"]','[]','manual_approved','below_category_threshold','[{"category":"التقنية","score":1.5},{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:50:49.650Z',200,88,0,'source_article_available','',NULL,NULL,'body:4f40eb87327f5fa373c0c9c764b1c6d55dc33757a408fd6ebd5778efdc1a730c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('478b7ef8-8e36-4e11-adbc-4ab6e49f4869','news-478b7ef8-8e36-4e11-adbc-4ab6e49f4869','وزارة البلديات والإسكان: 45 يومًا على انتهاء المهلة التصحيحية لملاك الأراضي الفضاء لمعالجة المخالفات','وزاره البلديات والاسكان 45 يوما علي انتهاء المهله التصحيحيه لملاك الاراضي الفضاء لمعالجه المخالفات','أكدت وزارة البلديات والإسكان أن المهلة التصحيحية الممنوحة لملاك الأراضي الفضاء تنتهي بعد 45 يومًا، في 15 ربيع الآخر 1448هـ (26 سبتمبر 2026م)، داعيةً الملاك إلى المبادرة بتصحيح أوضاع أراضيهم والالتزام بالاشتراطات والضوابط البلدية المعتمدة قبل انتهاء المهلة.','["وأوضحت الوزارة أن المهلة تستهدف تعزيز مستوى الامتثال في الأراضي الفضاء، ومعالجة الاستخدامات والممارسات المخالفة التي تؤثر على المظهر العام للمدن والمحافظات، ومن أبرزها تجميع مخلفات البناء ونواتج الحفر، واستغلال الأراضي بطرق غير نظامية.","وبيّنت أن الأمانات والبلديات تنفذ أعمال المتابعة والرقابة الميدانية على الأراضي الفضاء في مختلف مناطق المملكة، لرصد المخالفات ومعالجتها وفق الأنظمة والاشتراطات البلدية المعتمدة، بما يسهم في رفع مستوى الامتثال والحد من مظاهر التشوه البصري.","وأشارت الوزارة إلى أن الالتزام بالاشتراطات المنظمة للأراضي الفضاء يسهم في تحسين المشهد الحضري، ورفع جودة البيئة العمرانية، وتعزيز جودة الحياة في المدن والمحافظات. ودعت ملاك الأراضي الفضاء إلى الاستفادة من الفترة المتبقية من المهلة، والمبادرة بمعالجة أوضاع أراضيهم قبل انتهائها، تجنبًا للإجراءات النظامية المترتبة على المخالفات.","وأكدت الوزارة استمرار الأمانات والبلديات في تنفيذ برامج ومبادرات تحسين المشهد الحضري في مختلف مناطق المملكة، بما يدعم مستهدفات جودة الحياة والتنمية الحضرية المستدامة."]','العقارات','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-45','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-45','','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-45','','','2026-08-13T01:57:00.000Z','Wed, 07 Oct 2026 12:06:05 GMT','2026-08-15T07:57:55.251Z','','','','وزارة البلديات والإسكان: 45 يومًا على انتهاء المهلة التصحيحية لملاك الأراضي الفضاء لمعالجة المخالفات',NULL,NULL,'no_article_image_candidates','published','archived','valid',90,'0f769f3a5a22ae1470b952360a44cdf47f6be22651af98e7738a92bf780e43b0','a40459807c0d261f2bcba9566a8badc5b508a4d972221a4a93ed0e9c6ce5d6d4',NULL,'2026-08-15T07:57:55.251Z','2026-10-07T20:59:49.851Z','','',0,0,'saudi_national','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع"]','[]','classified','','[{"category":"المناطق","score":4},{"category":"أخبار السعودية","score":1.5},{"category":"البيئة والمناخ","score":1.5}]','Active','2026-10-07T20:59:49.851Z',304,85,0,'source_article_available','',NULL,NULL,'"1791374765"','Wed, 07 Oct 2026 12:06:05 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('41c26940-f28c-4fbb-807b-6449c89b03db','news-41c26940-f28c-4fbb-807b-6449c89b03db','وزارة البلديات والإسكان: 47 مشروعًا للمسح الجوي خلال 56 عامًا توفر قاعدة بيانات جيومكانية تغطي أكثر من 771 ألف كم²','وزاره البلديات والاسكان 47 مشروعا للمسح الجوي خلال 56 عاما توفر قاعده بيانات جيومكانيه تغطي اكثر من 771 الف كم2','كشفت وزارة البلديات والإسكان، ممثلةً بوكالة التخطيط الحضري والأراضي، عن تنفيذ (47) مشروعًا للمسح الجوي وإنتاج الخرائط منذ عام 1970، أسهمت في بناء قاعدة بيانات جيومكانية تغطي أكثر من (771,172) كيلومترًا مربعًا؛ مما دعم أعمال التخطيط العمراني، ووفّر صورًا جوية تاريخية وحديثة للنطاق العمراني في مختلف مناطق المملكة، بما يعزز صناعة القرار ويدعم تنفيذ المشروعات ال','["وتوثق هذه البيانات مسيرة ممتدة على مدى (56) عامًا، شهدت تطورًا متواصلًا في أعمال المسح الجوي، بدءًا من الصور التناظرية الفيلمية إلى التصوير الرقمي عالي الدقة، وذلك في إطار تطوير منظومة المعلومات الجيومكانية التي تعتمد عليها الجهات الحكومية في التخطيط وإدارة التنمية الحضرية.","وأوضحت الوزارة أن مشروعات المسح الجوي نُفذت على مراحل متتابعة شملت مختلف مناطق المملكة، وأسهمت في تكوين أرشيف وطني متكامل للصور الجوية، وتحديث البيانات المكانية، بما يرفع كفاءة التخطيط العمراني، ويعزز دقة الدراسات والمخططات، ويوفر مرجعًا مكانيًا موثوقًا لمشروعات التنمية.","وبيّنت البيانات أن منظومة المسح الجوي شهدت انتقالًا تدريجيًا في استخدام التقنيات؛ بدءًا من التصوير بالأبيض والأسود، مرورًا بالتصوير الملون، ثم التصوير الرقمي عالي الدقة، وصولًا إلى إنتاج الخرائط العقارية الرقمية، بما يعكس التطور الذي شهدته أعمال المساحة ونظم المعلومات في المملكة خلال العقود الماضية.","وفي محطة مهمة ضمن مسيرة تطوير الجودة، حصلت الوزارة على شهادة الآيزو لنظام إدارة الجودة (ISO 9001:2008) بتاريخ 19 أكتوبر 2010، وشمل نطاق الشهادة أنشطة إنتاج وتوفير المعلومات المكانية، بما في ذلك المسح الجوي، والمسح الأرضي، والخرائط المصورة، والخرائط الطبوغرافية، والمسح العقاري، والخرائط العقارية، والاستشعار عن بُعد، وأنظمة معلومات الأراضي، ونظم المعلومات الجغرافية، بما يعكس التزام الوزارة بتطبيق معايير الجودة العالمية في إدارة مشروعات المسح الجوي وإنتاج البيانات الجيومكانية.","وأكدت الوزارة استمرارها في تطوير منظومة المصورات الجوية والخرائط الطبوغرافية والعقارية، بما يعزز تكامل المعلومات المكانية، ويرفع كفاءة التخطيط الحضري، ويدعم تنفيذ المبادرات والمشروعات التنموية، انسجامًا مع مستهدفات التنمية العمرانية المستدامة وجودة الحياة .","وزارة البلديات والإسكان: 45 يومًا على انتهاء المهلة التصحيحية لملاك الأراضي الفضاء لمعالجة المخالفات","أكدت وزارة البلديات والإسكان أن المهلة التصحيحية الممنوحة لملاك الأراضي الفضاء تنتهي بعد 45 يومًا، في 15 ربيع الآخر 14","كشفت وزارة البلديات والإسكان، ممثلةً بوكالة التخطيط الحضري والأراضي، عن تنفيذ (47) مشروعًا للمسح الجوي وإنتاج الخرائط"]','العقارات','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-47','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-47','','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-47','','','2026-08-13T02:28:00.000Z','Wed, 07 Oct 2026 14:13:53 GMT','2026-08-15T07:59:06.068Z','','','','وزارة البلديات والإسكان: 47 مشروعًا للمسح الجوي خلال 56 عامًا توفر قاعدة بيانات جيومكانية تغطي أكثر من 771 ألف كم²',NULL,NULL,'no_article_image_candidates','review','archived','valid',99,'2a9ac5eb26001e361d43b336419be460e47e57c83acc16fc5e0617ecc962095d','429abac82191079bb266977d099ea571bca6546a3d03e911d80ad1a617364ef2',NULL,'2026-08-15T07:59:06.068Z','2026-10-07T20:59:48.962Z','','',0,0,'saudi_national','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية","الاقتصاد والأسواق","التقنية والتحول الرقمي","الجوي عام توفر","عام توفر قاعدة","للمسح الجوي عام","مشروع للمسح الجوي","توفر قاعدة بيانات"]','["أخبار السعودية","الاقتصاد والأسواق","التقنية والتحول الرقمي","الجوي عام توفر","عام توفر قاعدة","للمسح الجوي عام"]','needs_review','below_category_threshold','[{"category":"التقنية","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T20:59:48.962Z',304,85,0,'source_article_available','',NULL,NULL,'"1791382433"','Wed, 07 Oct 2026 14:13:53 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6d55ccb6-7872-45d8-ac53-88eb17cdcc62','news-6d55ccb6-7872-45d8-ac53-88eb17cdcc62','«الأرصاد» يتوقع طقسًا شديد الحرارة وأمطارًا رعدية على عدة مناطق اليوم','الارصاد يتوقع طقسا شديد الحراره وامطارا رعديه علي عده مناطق اليوم','توقع المركز الوطني للأرصاد في تقريره اليوم السبت 15 أغسطس 2026، استمرار الأجواء الحارة إلى شديدة الحرارة على المنطقة الشرقية وأجزاء من منطقتي الرياض و القصيم .','["وأوضح التقرير أن أمطارًا رعدية مصحوبة بزخات من البرد ستتساقط على أجزاء من مرتفعات مناطق جازان ، عسير ، الباحة ومكة المكرمة.","وأشار إلى استمرار تأثير الرياح النشطة المثيرة للأتربة والغبار على أجزاء من منطقتي تبوك و نجران ، والتي قد تؤدي إلى انعدام أو شبه انعدام في مدى الرؤية الأفقية، خاصة على الأجزاء الساحلية من منطقتي المدينة المنورة ومكة المكرمة، وتمتد على طول الطريق الساحلي حتى جازان.","ذكر التقرير أن الرياح السطحية على البحر الأحمر ستكون شمالية غربية إلى شمالية بسرعة 15–32 كم/ساعة على الجزء الشمالي، وشمالية غربية إلى غربية بسرعة 22–46 كم/ساعة على الجزء الأوسط والجنوبي، وقد تصل إلى أكثر من 55 كم/ساعة مع تكوّن السحب الرعدية الممطرة على الجزء الجنوبي."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/0xbd6amu9','https://ajel.sa/local/0xbd6amu9','https://ajel.sa/local/0xbd6amu9','https://ajel.sa/local/0xbd6amu9','فريق التحرير','السعودية','2026-08-14T22:51:00.000Z','Wed, 07 Oct 2026 20:50:02 GMT','2026-08-15T07:59:16.943Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%A7%D9%85%D8%B7%D8%A7%D8%B1-%D8%A7%D9%84%D8%B7%D9%82%D8%B3-J1Eqn8AE.jpg','/api/media/6d55ccb6-7872-45d8-ac53-88eb17cdcc62','/api/media/6d55ccb6-7872-45d8-ac53-88eb17cdcc62?variant=thumbnail','«الأرصاد» يتوقع طقسًا شديد الحرارة وأمطارًا رعدية على عدة مناطق اليوم',1200,675,'valid','published','archived','valid',68,'37457cf1a45c46186f3e2bb387c7d8ad67413b3020eb8fb245f30d96b82c8585','17b066847c57a3a78472449383a570ac2c1c0c646884cbad42f582f9a5ebe7cb',NULL,'2026-08-15T07:59:16.943Z','2026-10-07T20:50:05.085Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة","عسير","تبوك","جازان","نجران","الباحة","المدينة المنورة"]','["الطقس والمناخ","المدينة المنورة"]','manual_approved','ambiguous_category','[{"category":"البيئة والمناخ","score":9},{"category":"السفر","score":3},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:50:05.085Z',200,84,0,'source_content_changed','',NULL,NULL,'body:2497458c09916365a1753587669db2bd3d2e41892696093304d825a7e8e75c65','Wed, 07 Oct 2026 20:50:02 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5f43357a-71d1-4d0c-bdfe-15927933d52b','news-5f43357a-71d1-4d0c-bdfe-15927933d52b','"ترامب" يُحجم عن دعم "نتنياهو" انتخابياً وسط خلافات متصاعدة حول غزة وإيران','ترامب يحجم عن دعم نتنياهو انتخابيا وسط خلافات متصاعده حول غزه وايران','مع اقتراب الانتخابات الإسرائيلية المقررة في 27 أكتوبر، يواجه رئيس الوزراء بنيامين نتنياهو تحدياً سياسياً لافتاً، فيما يمتنع الرئيس الأمريكي دونالد ترامب حتى الآن عن منحه دعماً انتخابياً علنياً، رغم العلاقة الوثيقة التي جمعت الرجلين خلال السنوات الماضية.','["وقد سئل ترامب أربع مرات خلال الأسابيع الأخيرة عما إذا كان يؤيد نتنياهو في الانتخابات، لكنه تجنّب في كل مرة إعلان دعمه له، وسط تباينات متزايدة بين الإدارة الأمريكية وحكومة تل أبيب بشأن ملفات غزة وإيران ولبنان.","صورة غائمة في استطلاعات الرأي كشفت مصادر مطلعة نقلاً عن موقع «أكسيوس» أن الانتخابات حضرت خلال لقاء ترامب ونتنياهو في المكتب البيضاوي قبل نحو أسبوعين، إذ سأل الرئيس الأمريكي رئيس الوزراء الإسرائيلي عن وضعه في استطلاعات الرأي.","وكشف مسؤول أمريكي مطلع على الحوار أن نتنياهو توقف للحظات قبل أن يتدخل أحد مستشاريه قائلاً: «سيدي الرئيس، إنه يفوز».","غير أن استطلاعات الرأي ترسم صورة مغايرة؛ إذ يتراوح عدد المقاعد المتوقع حصول ائتلاف نتنياهو عليها بين 49 و53 مقعداً، مقارنةً بـ68 مقعداً يمتلكها حالياً، فيما يستلزم تشكيل الحكومة الحصول على 61 مقعداً على الأقل."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/mjbpjth','https://sabq.org/article/mjbpjth','','https://sabq.org/article/mjbpjth','صحيفة سبق','السعودية','2026-08-14T11:10:00.000Z','2026-08-14T14:10:00.000Z','2026-08-15T08:03:59.932Z','https://media.sabq.org/news/2026/08/94f5c789-4053-44fd-9d0b-a16051e3cd01/w801.webp','/api/media/5f43357a-71d1-4d0c-bdfe-15927933d52b','/api/media/5f43357a-71d1-4d0c-bdfe-15927933d52b?variant=thumbnail','"ترامب" يُحجم عن دعم "نتنياهو" انتخابياً وسط خلافات متصاعدة حول غزة وإيران',801,451,'valid','published','archived','valid',99,'9fe87ea70755882d7eb77390343f76832f1e3ead00b2a07b00b64496a67fb5db','0af4dd0dc8c600db6a983af3f22e28ce726b4c467b675e2fb29611ec4650cce1','محدّث','2026-08-15T08:03:59.932Z','2026-10-07T20:50:51.504Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس الوزراء الإسرائيلي عن وضعه","السياسة والعلاقات الدولية","غزة","لبنان","إيران"]','["رئيس الوزراء الإسرائيلي عن وضعه","السياسة والعلاقات الدولية"]','classified','','[{"category":"التقنية","score":2},{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:50:51.504Z',200,80,0,'source_article_available','',NULL,NULL,'body:da5759c796c6d259b656eb1c86fca91b2d2e21affea65df87ac8445cf557fca6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bdd57403-113a-4a3d-9cdd-0a5f80ecde3c','news-bdd57403-113a-4a3d-9cdd-0a5f80ecde3c','«السعودية للطاقة» و«إكسبو 2030 الرياض» توقّعان اتفاقية لإمداد الموقع بالكهرباء','السعوديه للطاقه و اكسبو 2030 الرياض توقعان اتفاقيه لامداد الموقع بالكهرباء','وقّعت «السعودية للطاقة» و«إكسبو 2030 الرياض» اتفاقية لتنفيذ أعمال إيصال إمدادات الطاقة الكهربائية إلى موقع إكسبو 2030 الرياض، في خطوة رئيسة تعكس الجهود المتواصلة التي يشهدها المشروع مع انتقاله إلى مرحلة التطوير، ومُضيّه قُدُماً نحو إقامة معرض استثنائي وغير مسبوق.','["حضر توقيع الاتفاقية الرئيس التنفيذي للشركة السعودية للطاقة المهندس خالد بن سالم الغامدي، والرئيس التنفيذي لإكسبو 2030 الرياض المهندس طلال المري، فيما وقّعها الرئيس التنفيذي للشركة الوطنية لنقل الكهرباء المهندس وليد السعدي، والمهندس عبدالعزيز العقل الرئيس التنفيذي للتطوير في إكسبو 2030 الرياض.","وأكد المهندس خالد الغامدي أن الاتفاقية تعكس الدور المحوري الذي تضطلع به الشركة في تمكين المشروعات الوطنية الكبرى بإشراف وزارة الطاقة، مشيراً إلى أن «السعودية للطاقة» ستُسخّر خبراتها وإمكاناتها لتنفيذ أعمال الإمداد الكهربائي وفق أعلى معايير الجودة والموثوقية، بما يدعم الجاهزية لهذا الحدث العالمي ويواكب مستهدفات المملكة التنموية.","من جانبه، أوضح المهندس طلال المري أن الاتفاقية تمثّل خطوة مهمة تعكس التقدم المتسارع في مختلف مسارات العمل بالموقع، وتعزز جاهزيته وفق الجدول الزمني المعتمد، مؤكداً أن التعاون مع «السعودية للطاقة» يعكس الثقة بالكفاءات الوطنية وقدرتها على تنفيذ مشروعات بهذا الحجم والطموح وفق أعلى المعايير الفنية والتشغيلية.","وتشمل الاتفاقية تطوير البنية التحتية الكهربائية اللازمة للموقع، بما في ذلك إنشاء محطة إمداد رئيسة وثلاث محطات تحويل أولية، إلى جانب أعمال شبكات نقل وتوزيع الكهرباء، وسيتولى تنفيذ هذه الأعمال كلٌّ من شركات «الفنار» و«هيف» و«التضامنية» و«البابطين»، مما يعكس دور الكفاءات الوطنية في دعم تنفيذ إكسبو 2030 الرياض."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/2f9uheq','https://sabq.org/article/2f9uheq','','https://sabq.org/article/2f9uheq','صحيفة سبق','السعودية','2026-08-14T11:00:00.000Z','2026-08-14T14:00:00.000Z','2026-08-15T08:04:01.128Z','https://media.sabq.org/news/2026/08/da9ebcdc-25df-4cd4-866f-4cb61722caef/w1600.webp','/api/media/bdd57403-113a-4a3d-9cdd-0a5f80ecde3c','/api/media/bdd57403-113a-4a3d-9cdd-0a5f80ecde3c?variant=thumbnail','«السعودية للطاقة» و«إكسبو 2030 الرياض» توقّعان اتفاقية لإمداد الموقع بالكهرباء',1600,910,'valid','published','archived','valid',51,'6f1c92ecaad664d464668feb3422fba915a0d99b06f3cffca162e47850300605','3ac7f17f58052301941f2742904f76937fbc80f969b977aeefdb52f9d2d56864','محدّث','2026-08-15T08:04:01.128Z','2026-10-07T20:50:47.540Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الطاقة مشيرا إلى أن","الطاقة والنفط","الرياض"]','["وزارة الطاقة مشيرا إلى أن","الطاقة والنفط"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":4.5},{"category":"المناطق","score":3},{"category":"الثقافة","score":1.5}]','Active','2026-10-07T20:50:47.540Z',200,94,0,'source_article_available','',NULL,NULL,'body:19ffdc5db099a10a25cbf2ba9bea726a474f36c8af5948122ad86ce6c6260b62','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c12c411c-4461-4fe1-b1b5-c0f4e499ac98','news-c12c411c-4461-4fe1-b1b5-c0f4e499ac98','مسيرة تتحطم قرب الحدود الأوكرانية الرومانية بعد إفلاتها من الرادار','مسيره تتحطم قرب الحدود الاوكرانيه الرومانيه بعد افلاتها من الرادار','أعلنت وزارة الدفاع الرومانية، الجمعة، تحطّم طائرة مسيرة حلّقت على ارتفاع منخفض وأفلتت من رصد أنظمة الرادار، في منطقة غابات قرب قرية لونكافيتا بجنوب شرق البلاد، على بعد 5 كيلومترات من الحدود مع أوكرانيا.','["وأوضحت الوزارة أن المسيرة لم تُسبب أضراراً على ما يبدو، مشيرةً إلى أنها لم تحدد مصدر الطائرة حتى الآن.","وتشترك رومانيا، العضو في حلف شمال الأطلسي «الناتو»، في حدود برية تمتد 614 كيلومتراً مع أوكرانيا.","وعلى مدى السنوات الأربع الماضية، شهدت رومانيا مراراً اختراق طائرات مسيرة روسية لمجالها الجوي، فضلاً عن رصد ألغام عائمة في البحر الأسود تهدد طرق التجارة والطاقة الرئيسية."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ob85dfd','https://sabq.org/article/ob85dfd','','https://sabq.org/article/ob85dfd','صحيفة سبق','السعودية','2026-08-14T10:50:00.000Z','2026-08-14T13:50:00.000Z','2026-08-15T08:04:01.133Z','https://media.sabq.org/news/2026/08/4c51d303-d5e0-48fe-991a-203f458091a8/w640.webp','/api/media/c12c411c-4461-4fe1-b1b5-c0f4e499ac98','/api/media/c12c411c-4461-4fe1-b1b5-c0f4e499ac98?variant=thumbnail','مسيرة تتحطم قرب الحدود الأوكرانية الرومانية بعد إفلاتها من الرادار',640,427,'valid','published','archived','valid',40,'b9706e7bda97ffc7a03ace409447fb92c0df14c4b617659d36f44db62fb1e75a','9fdb1b025428fc53834bcd663ee646d6912e3043141a67604c246ae55d5bd5fa','محدّث','2026-08-15T08:04:01.133Z','2026-10-07T20:50:49.013Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الاقتصاد والأسواق","أوكرانيا"]','["الطاقة والنفط","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الطاقة والصناعة","score":1.5},{"category":"العالم","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:50:49.013Z',200,88,0,'source_article_available','',NULL,NULL,'body:b645bbc97817bc9b5a8e73c82ac5e8d1a9d66e8dabfb729b96d88f7c85e65f9e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4bb3e4bb-b54e-48f5-a0d0-f7fb038d5ab7','news-4bb3e4bb-b54e-48f5-a0d0-f7fb038d5ab7','حرائق غابات جديدة تشتعل في مناطق متعددة وسط اليونان وجنوبها','حرائق غابات جديده تشتعل في مناطق متعدده وسط اليونان وجنوبها','اندلعت حرائق غابات جديدة اليوم في مناطق متعددة وسط اليونان وجنوبها، في وقت ترفع فيه السلطات مستوى الخطر إلى درجته القصوى بالتزامن مع رياح عاصفة تُذكي النيران.','["وأفادت إدارة الإطفاء المحلية بأن حريقاً اندلع في منطقة أحراش قرب مدينة تريبولي بإقليم أركاديا جنوب البلاد، وجرى تسخير طائرتين وعدد من رجال الإطفاء مدعومين بسيارات مجهزة للسيطرة على النيران.","وفي منطقة نافباكتوس وسط اليونان، اندلع حريق آخر في أحراش قرب قرية غالاتاس، وتواصل فرق الإطفاء جواً وبراً جهودها للحدّ من امتداد النيران.","ورفعت السلطات المدنية مستوى خطر اندلاع حرائق الغابات إلى الدرجة القصوى، وهي المستوى الخامس على مقياس من خمس درجات، وذلك في منطقة أتيكا وأثينا الكبرى، إلى جانب مناطق فيوتيا وإيفيا وكورنثيا وأرجوليدا."]','السيارات','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/tmxuqlo','https://sabq.org/article/tmxuqlo','','https://sabq.org/article/tmxuqlo','صحيفة سبق','السعودية','2026-08-14T10:40:00.000Z','2026-08-14T13:40:00.000Z','2026-08-15T08:04:02.300Z','https://media.sabq.org/news/2026/08/4c08a349-523c-4730-b472-92075cfba323/w547.webp','/api/media/4bb3e4bb-b54e-48f5-a0d0-f7fb038d5ab7','/api/media/4bb3e4bb-b54e-48f5-a0d0-f7fb038d5ab7?variant=thumbnail','حرائق غابات جديدة تشتعل في مناطق متعددة وسط اليونان وجنوبها',547,365,'valid','published','archived','valid',41,'b842cd8bbd735bf7e88dbec99355adfcd69513f30e978f2d94b61dcec769f014','f7ecb69a426414d6b9a40dac14e3be8fcc1e83548fa84d118094ce314802232e','محدّث','2026-08-15T08:04:02.300Z','2026-10-07T20:50:48.442Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:50:48.442Z',200,94,0,'source_article_available','',NULL,NULL,'body:f8d20a9f4a610a21426a3e5e8503399af5af0ebf0071f4e40a66d31b8dc62318','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f837cd35-d07b-40d7-89e7-a8eac2c5b71b','news-f837cd35-d07b-40d7-89e7-a8eac2c5b71b','أمانة نجران تطرح 8 فرص استثمارية في محافظة حبونا عبر بوابة «فرص»','امانه نجران تطرح 8 فرص استثماريه في محافظه حبونا عبر بوابه فرص','أتاحت أمانة منطقة نجران، ممثلةً في بلدية محافظة حبونا، 8 فرص استثمارية متنوعة في منافسة عامة عبر بوابة الاستثمار البلدي «فرص»، تشمل قطاعات تجارية وسكنية وترفيهية وخدمية وصناعية، في إطار جهودها الرامية إلى تعزيز الشراكة مع القطاع الخاص ودعم عجلة التنمية الاقتصادية والخدمية بالمنطقة.','["وتضم الحزمة الاستثمارية المطروحة في القطاع التجاري والسكني ثلاثة مشاريع رئيسية؛ أبرزها مشروع إنشاء وترميم وتشغيل وصيانة مجمع تجاري وسكني بالمنشّر على مساحة 5,594 مترًا مربعًا، وإنشاء وترميم وتشغيل وصيانة محال تجارية بحبونا على مساحة 1,650 مترًا مربعًا، فضلًا عن إنشاء وترميم وتشغيل وصيانة أسواق تجارية متعددة بمدخل حبونا الشرقي على مساحة تتجاوز 10,724 مترًا مربعًا.","وفي الجانب الاجتماعي والترفيهي، تشمل الفرص إنشاء وترميم وتشغيل وصيانة قصر أفراح للنساء بالمنشّر على مساحة 5,195 مترًا مربعًا، إلى جانب ترميم وتشغيل وصيانة ملعب كرة قدم بالجفجة على مساحة 3,740 مترًا مربعًا، وإنشاء وترميم وتشغيل وصيانة كشك بجانب حديقة الحباية على مساحة 15 مترًا مربعًا.","ويمتد نطاق الفرص ليشمل القطاع الخدمي والصناعي، إذ يُطرح مشروع إنشاء وترميم وتشغيل وصيانة ورش وتشاليح ومعارض سيارات بصناعية العباية على مساحة تتجاوز 103,700 متر مربع، إضافةً إلى فرصة إنشاء وترميم وتفعيل وصيانة صراف آلي سيار بحبونا على مساحة 12 مترًا مربعًا.","وحددت البلدية المواعيد النهائية لتقديم العطاءات وشراء الكراسات؛ إذ يُعدّ يوم 20 أغسطس 2026م الموعد الأخير للفرص الخاصة بالكشك وملعب كرة القدم، فيما حُدد يوم 21 سبتمبر 2026م آخر موعد لبقية الفرص الاستثمارية المطروحة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/d40m9j2','https://sabq.org/article/d40m9j2','','https://sabq.org/article/d40m9j2','صحيفة سبق','السعودية','2026-08-14T10:30:00.000Z','2026-08-14T13:30:00.000Z','2026-08-15T08:04:02.343Z','https://media.sabq.org/news/2026/08/69c1133b-5cb4-42d5-832b-6106f18b8387/w1200.webp','/api/media/f837cd35-d07b-40d7-89e7-a8eac2c5b71b','/api/media/f837cd35-d07b-40d7-89e7-a8eac2c5b71b?variant=thumbnail','أمانة نجران تطرح 8 فرص استثمارية في محافظة حبونا عبر بوابة «فرص»',1200,775,'valid','published','archived','valid',99,'c2b10a92ae9fde84773d0f25bcc5fa9eafc94cd248d6a635250bab51fc49fe99','4ab5c5d90e3e160a7fe990d681f227bf606c93bf0cea3017042105adf0ebba63','محدّث','2026-08-15T08:04:02.343Z','2026-10-07T20:50:49.030Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","نجران"]','["الاقتصاد والأسواق"]','classified','','[{"category":"الاقتصاد","score":9},{"category":"الرياضة","score":4},{"category":"الصحة","score":1.5}]','Active','2026-10-07T20:50:49.030Z',200,90,0,'source_article_available','',NULL,NULL,'body:82838eef967446f26a94f5ad667d9c0a0384a0ea9e241fa8106ac7551b79a3d5','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ff57ccb0-3b8c-4665-9728-680fe198fa8e','news-ff57ccb0-3b8c-4665-9728-680fe198fa8e','أم ناصر.. قصة طاهية دمجت ثقافة المائدة النجدية والعسيرية للسائحين','ام ناصر قصه طاهيه دمجت ثقافه المائده النجديه والعسيريه للسائحين','قررت الطاهية أم ناصر دمج ثقافة المائدة النجدية والعسيرية في طريقة واحدة جديدة، وتقديمها إلى السياح. وقطعت "أم ناصر" مساعة 1000 كليومتر من قرى نجد لتسجل حضورا لافتا في موسم صيف عسير ، وفق " الإخبارية ".','["قررت الطاهية أم ناصر دمج ثقافة المائدة النجدية والعسيرية في طريقة واحدة جديدة، وتقديمها إلى السياح.","وقطعت \"أم ناصر\" مساعة 1000 كليومتر من قرى نجد لتسجل حضورا لافتا في موسم صيف عسير ، وفق \" الإخبارية \".","وروت \"أم ناصر\" تجربتها قائلة: إنها التجربة الأولى لي في عسير وستكون انطلاقة لصعود مهارتي التي أحبها لتكون علامة تجارية داخل وخارج المملكة ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/tourism/pu8hpyqb3','https://ajel.sa/tourism/pu8hpyqb3','https://ajel.sa/tourism/pu8hpyqb3','https://ajel.sa/tourism/pu8hpyqb3','فريق التحرير','السعودية','2026-08-15T02:19:00.000Z','Wed, 07 Oct 2026 20:50:05 GMT','2026-08-15T10:05:24.987Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/ai-edited/2026-08/IMHNg9MwCCIZyx9i.png','/api/media/ff57ccb0-3b8c-4665-9728-680fe198fa8e','/api/media/ff57ccb0-3b8c-4665-9728-680fe198fa8e?variant=thumbnail','أم ناصر.. قصة طاهية دمجت ثقافة المائدة النجدية والعسيرية للسائحين',1200,675,'valid','published','archived','valid',44,'44e4bd2d8ec3a3d01a4ab3d85f7caab6666025ce4c13e0ed2984c4b8e207520e','b3b3213dae8150fcf3392677eed5c8896cf5d647a57b62bf7a8bd6369bd4f34e',NULL,'2026-08-15T10:05:24.987Z','2026-10-07T20:50:07.189Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","عسير"]','["الثقافة والفنون"]','manual_approved','below_category_threshold','[{"category":"الثقافة","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:50:07.189Z',200,90,0,'source_content_changed','',NULL,NULL,'body:dfeeed01a28c0d60784f3d9543e2028cb4cac3179ae283ef8dabc86a740996bf','Wed, 07 Oct 2026 20:50:05 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7cc7c436-03bd-44d9-a839-7cde06f66a25','news-7cc7c436-03bd-44d9-a839-7cde06f66a25','مدير تعليم الطائف يتابع تفاعل الطلبة مع برنامج «نادينا»','مدير تعليم الطائف يتابع تفاعل الطلبه مع برنامج نادينا','اطّلع مدير عام الإدارة العامة للتعليم في محافظة الطائف الدكتور سعيد بن عبدالله الغامدي على برامج وفعاليات «نادينا»، التي تستهدف الطلاب والطالبات خلال الإجازة الصيفية، وتابع تفاعل الطلبة مع التجارب النوعية التي تجمع بين التعلم والترفيه وتنمية المهارات في بيئات تعليمية جاذبة.','["وأوضح الدكتور سعيد الغامدي أن الطلاب والطالبات يواصلون استثمار الإجازة الصيفية عبر برنامج «نادينا» من خلال منظومة متكاملة من البرامج التعليمية والرياضية والترفيهية، الهادفة إلى تنمية المهارات، وصقل المواهب، وتعزيز جودة الحياة لدى الطلبة في بيئات تعليمية محفزة.","وأضاف أن البرنامج يقدم باقة متنوعة من الفعاليات التي تجمع بين المعرفة والفائدة، في إطار يسهم في بناء الشخصية، وترسيخ القيم الإيجابية، وتعزيز الصحة البدنية والنفسية، بما يواكب مستهدفات وزارة التعليم في الاستثمار الأمثل للإجازة الصيفية، وتوفير برامج نوعية تلبي اهتمامات الطلبة وتستثمر طاقاتهم.","وبيّن الغامدي أن أنشطة «نادينا» تتنوع بين البرامج الرياضية والتعليمية والترفيهية، إلى جانب برامج مهارية وتفاعلية تثري خبرات المشاركين، وتنمي روح المنافسة والعمل الجماعي، وتسهم في اكتشاف المواهب وتطوير القدرات، مثمناً جهود فرق العمل ومتمنياً للجميع التوفيق والسداد."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/kSKQ9ql','https://sabq.org/article/kSKQ9ql','','https://sabq.org/article/kSKQ9ql','فهد العتيبي','السعودية','2026-08-14T12:10:00.000Z','2026-08-14T15:10:00.000Z','2026-08-15T10:10:09.717Z','https://media.sabq.org/news/2026/08/8667184f-c400-4c72-8868-457d65b51f47/w1600.webp','/api/media/7cc7c436-03bd-44d9-a839-7cde06f66a25','/api/media/7cc7c436-03bd-44d9-a839-7cde06f66a25?variant=thumbnail','مدير تعليم الطائف يتابع تفاعل الطلبة مع برنامج «نادينا»',1600,1523,'valid','published','archived','valid',88,'c0165127579cf6e87c2e07fd501daecdca03150ae1cb9d40b054f1afe464efdd','afb546328db3bfc41e11960312ae0a8da795c60c35d7268cac18868362d43f02','محدّث','2026-08-15T10:10:09.717Z','2026-10-07T20:49:57.591Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة التعليم في الاستثمار الأمثل","الصحة العامة","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق","الرياض"]','["وزارة التعليم في الاستثمار الأمثل","الصحة العامة","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[{"category":"المجتمع","score":5.5},{"category":"الاقتصاد","score":4},{"category":"الرياضة","score":3}]','Active','2026-10-07T20:49:57.591Z',200,88,0,'source_article_available','',NULL,NULL,'body:9f628db6367e1d2204dbced8e517bf5e24dc74aeab992104b207890ef539bfb9','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e0615e01-1c29-4a82-8d00-dfed5698d5d6','news-e0615e01-1c29-4a82-8d00-dfed5698d5d6','انقطاع متزامن للكهرباء في أربع دول بآسيا الوسطى','انقطاع متزامن للكهرباء في اربع دول باسيا الوسطي','أعلنت كل من قازاخستان وقيرغيزستان وطاجيكستان وأوزبكستان، اليوم، حدوث انقطاعات متزامنة في التيار الكهربائي في الدول الأربع.','["وأفادت وزارة الطاقة في قازاخستان، في بيان، بأن انقطاع التيار الكهربائي نجم عن «تغير مفاجئ في تدفق الكهرباء» من شبكة آسيا الوسطى.","وأكدت وزارات الطاقة في الدول الأربع، التي ترتبط شبكاتها الكهربائية ببعضها البعض، وقوع الانقطاعات، مشيرةً إلى أن العمل جارٍ لإعادة التيار الكهربائي إلى طبيعته."]','الطاقة والصناعة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/8u6bdvg','https://sabq.org/article/8u6bdvg','','https://sabq.org/article/8u6bdvg','صحيفة سبق','السعودية','2026-08-14T12:00:00.000Z','2026-08-14T15:00:00.000Z','2026-08-15T10:10:10.092Z','https://media.sabq.org/news/2026/08/c823c151-c749-481c-923e-31ab98cbc94b/w777.webp','/api/media/e0615e01-1c29-4a82-8d00-dfed5698d5d6','/api/media/e0615e01-1c29-4a82-8d00-dfed5698d5d6?variant=thumbnail','انقطاع متزامن للكهرباء في أربع دول بآسيا الوسطى',777,437,'valid','published','archived','valid',48,'86c14036d363dc46f0aa79950beaf0dd923827925487a021f9ddd356a6d4e7e7','1c28515ff385d7f307e0530aaa14d85e480696158d17c1426397e0c4e5fc6d81','محدّث','2026-08-15T10:10:10.092Z','2026-10-07T20:50:42.458Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الطاقة في قازاخستان في","الطاقة والنفط"]','["وزارة الطاقة في قازاخستان في","الطاقة والنفط"]','manual_approved','below_category_threshold','[{"category":"الصحة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:50:42.458Z',200,91,0,'source_article_available','',NULL,NULL,'body:73800e9d4c87e0d8eef3821796c66899553995a3b844e3044b4094df5c2ad433','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('91826f05-4bc6-4ddf-b956-554ca50167f8','news-91826f05-4bc6-4ddf-b956-554ca50167f8','الذهب يتجاوز 4376 دولاراً مع تراجع الدولار وتوقعات تثبيت الفائدة الأمريكية','الذهب يتجاوز 4376 دولارا مع تراجع الدولار وتوقعات تثبيت الفائده الامريكيه','ارتفعت أسعار الذهب الجمعة، مدعومةً بانخفاض الدولار الأمريكي، إثر بيانات تضخم رجّحت إبقاء مجلس الاحتياطي الاتحادي (البنك المركزي الأمريكي) أسعار الفائدة دون تغيير في اجتماعه المقبل.','["وزاد الذهب في المعاملات الفورية 0.6% ليصل إلى 4376.02 دولار للأوقية بحلول الساعة 13:09 بتوقيت غرينتش، بعد أن تراجع 1.3% في الجلسة السابقة جراء جني المستثمرين للأرباح إثر بلوغه أعلى مستوياته منذ الخامس من يونيو.","وعلى صعيد أسبوعي، ارتفع المعدن النفيس بنحو 0.7%.","وصعدت العقود الأمريكية الآجلة للذهب 0.3% إلى 4433.90 دولار للأوقية.","وقال جيم ويكوف، محلل الأسواق في بورصة الذهب الأمريكية: «يُعدّ انخفاض مؤشر الدولار عاملاً إيجابياً خارج السوق، وهو ما يدعم الذهب اليوم»."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/81s138z','https://sabq.org/article/81s138z','','https://sabq.org/article/81s138z','صحيفة سبق','السعودية','2026-08-14T11:50:00.000Z','2026-08-14T14:50:00.000Z','2026-08-15T10:10:10.454Z','https://media.sabq.org/news/2026/08/b0ed48c8-6451-4a49-abc0-9a9ce036d996/w960.webp','/api/media/91826f05-4bc6-4ddf-b956-554ca50167f8','/api/media/91826f05-4bc6-4ddf-b956-554ca50167f8?variant=thumbnail','الذهب يتجاوز 4376 دولاراً مع تراجع الدولار وتوقعات تثبيت الفائدة الأمريكية',960,640,'valid','published','archived','valid',99,'520a0ee7c0a25861554e0170fe046366ad3538cca212b611695e7cda1366b2cc','44bf25200064d641d22812914a0151c62194253acdecc70dcf28d1f91c349922','محدّث','2026-08-15T10:10:10.454Z','2026-10-07T20:50:03.915Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','classified','','[{"category":"الطاقة والصناعة","score":1.5},{"category":"العالم","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:50:03.915Z',200,94,0,'source_article_available','',NULL,NULL,'body:4a6350ec71a767b4378d2a1560810bc2922d31a6b4403127bd2b7916ac10a7b1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('aa0d4f4a-5733-4319-bb01-e6748b9c8e06','news-aa0d4f4a-5733-4319-bb01-e6748b9c8e06','حرائق ضخمة تدمر 19 منزلاً وتلحق أضراراً بـ18 آخر في وسط إنجلترا','حرائق ضخمه تدمر 19 منزلا وتلحق اضرارا بـ18 اخر في وسط انجلترا','دمّرت حرائق واسعة النطاق 19 منزلاً بالكامل، وألحقت أضراراً جسيمة بـ18 منزلاً آخر في منطقة ويست ميدلاندز وسط إنجلترا، في حوادث أثارت قلقاً واسعاً لدى السلطات المحلية.','["وأفادت هيئة الإذاعة البريطانية «بي بي سي»، نقلاً عن خدمات الطوارئ، بأن 54 شخصاً تلقّوا العلاج جراء ثمانية حرائق شهدتها المنطقة، نُقل منهم 19 إلى المستشفى لتلقّي الرعاية اللازمة.","وتواصل فرق الإطفاء التعامل مع بؤر الحرائق المنتشرة في الأراضي المفتوحة والحدائق العامة، وعلى امتداد خطوط السكك الحديدية، فيما تعمل السلطات المحلية على تحديد الأسباب الكامنة وراء اندلاع هذه الحرائق."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/4yqbieb','https://sabq.org/article/4yqbieb','','https://sabq.org/article/4yqbieb','صحيفة سبق','السعودية','2026-08-14T11:20:00.000Z','2026-08-14T14:20:00.000Z','2026-08-15T10:10:11.669Z','https://media.sabq.org/news/2026/08/82610685-16f3-420c-8873-2a6b607dac1a/w1280.webp','/api/media/aa0d4f4a-5733-4319-bb01-e6748b9c8e06','/api/media/aa0d4f4a-5733-4319-bb01-e6748b9c8e06?variant=thumbnail','حرائق ضخمة تدمر 19 منزلاً وتلحق أضراراً بـ18 آخر في وسط إنجلترا',1280,960,'valid','published','archived','valid',47,'b83f7c76559f49dd588c0150abc20d3add476f6a29fd7655255f8695604e6149','3f61b6293b6e46822b8c31e514fe3969d237bf8a7c16b42936111fb8a298a8ec','محدّث','2026-08-15T10:10:11.669Z','2026-10-07T20:50:41.279Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الإذاعة البريطانية بي بي","الصحة العامة"]','["هيئة الإذاعة البريطانية بي بي","الصحة العامة"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:50:41.279Z',200,91,0,'source_article_available','',NULL,NULL,'body:db503443982f520c71de63e2d5065110b27b2213262b5aba991a5cfcfc49b2b9','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1b67ebd2-4251-4342-9ae5-b47daabf6c7a','news-1b67ebd2-4251-4342-9ae5-b47daabf6c7a','"ميسي" يدعم صفوف الاتفاق  بنظام الإعارة لمدة موسم واحد','ميسي يدعم صفوف الاتفاق بنظام الاعاره لمده موسم واحد','أعلن نادي الاتفاق تعاقده مع لاعب منتخب فرنسا تحت 19 سنة رايان ميسي، بنظام الإعارة لمدة موسم واحد، مع تضمين العقد أفضلية شراء اللاعب بعد انتهاء الإعارة.','["ويأتي التعاقد مع ميسي ضمن توجه نادي الاتفاق لدعم صفوف الفريق بالمواهب الواعدة، بهدف تعزيز خيارات الجهاز الفني خلال الموسم الرياضي الجديد.","ووقّع اللاعب البالغ من العمر 19 عامًا على عقد انتقاله إلى نادي الاتفاق لمدة موسم واحد على سبيل الإعارة، ليعود مجددًا إلى الملاعب السعودية بعد تجربة سابقة خاضها مع فريق نيوم.","وسبق لميسي أن ارتدى قميص نيوم في الموسم الماضي، أيضًا بنظام الإعارة من نادي ستراسبورغ، حيث شارك مع الفريق في 13 مباراة، سجّل خلالها هدفًا وصنع آخر."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/2vz7r8w','https://sabq.org/article/2vz7r8w','','https://sabq.org/article/2vz7r8w','صحيفة سبق','السعودية','2026-08-14T11:40:00.000Z','2026-08-14T14:40:00.000Z','2026-08-15T10:10:11.830Z','https://media.sabq.org/news/2026/08/06725432-a3ff-4547-bc38-c57b98ab94eb/w1080.webp','/api/media/1b67ebd2-4251-4342-9ae5-b47daabf6c7a','/api/media/1b67ebd2-4251-4342-9ae5-b47daabf6c7a?variant=thumbnail','"ميسي" يدعم صفوف الاتفاق  بنظام الإعارة لمدة موسم واحد',1080,1350,'valid','published','archived','valid',58,'a877571cea6d98745aab55a4c31f3ace505b4e409b9281faaf2bdcb5fb923ab4','4446d16ca33f7a8c9e5b8c5e650a3a44afd7edbb2b9c5a950cab614c01fd47e6','محدّث','2026-08-15T10:10:11.830Z','2026-10-07T20:50:49.602Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الثقافة","score":1.5},{"category":"الصحة","score":0}]','Active','2026-10-07T20:50:49.602Z',200,86,0,'source_article_available','',NULL,NULL,'body:9dd14c7c7392d588045a8c5ea4a1d1bb4475bece7521fad7885f2f2d165d589a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5913bd67-0392-499d-ba34-5918934e61a4','news-5913bd67-0392-499d-ba34-5918934e61a4','الجيش الإسرائيلي يعلن مقتل قائد سرية في لواء خان يونس التابع لحماس','الجيش الاسرائيلي يعلن مقتل قائد سريه في لواء خان يونس التابع لحماس','أعلن الجيش الإسرائيلي، الجمعة، مقتل قائد سرية في لواء خان يونس التابع للجناح العسكري لحركة حماس، إثر غارة جوية استهدفته في جنوب قطاع غزة يوم الخميس.','["وأفاد الجيش في بيان رسمي بأن الغارة أسفرت عن مقتل «حذيفة خالد سليمان كوارع»، واصفاً إياه بأنه قائد سرية في لواء خان يونس.","ووفق البيان الإسرائيلي، شارك كوارع خلال فترة الحرب في تدريب عناصر السرية ونقل الأسلحة في مناطق متعددة من جنوب القطاع، فضلاً عن إسهامه في محاولات إعادة بناء القدرات العسكرية لحركة حماس.","وأضاف الجيش أن كوارع واصل في الفترة الأخيرة التخطيط لشنّ هجمات ضد القوات الإسرائيلية، مؤكداً أنه كان يُمثّل «تهديداً فورياً» قبل استهدافه.","ولم يصدر عن حركة حماس أي تعليق فوري يؤكد مقتل كوارع أو يردّ على ما أورده الجيش الإسرائيلي بشأن دوره."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/4zwbw6c','https://sabq.org/article/4zwbw6c','','https://sabq.org/article/4zwbw6c','صحيفة سبق','السعودية','2026-08-14T11:30:00.000Z','2026-08-14T14:31:00.000Z','2026-08-15T10:10:11.930Z','https://media.sabq.org/news/2026/08/897d9ae4-15cf-4451-babb-994b6e57060f/w801.webp','/api/media/5913bd67-0392-499d-ba34-5918934e61a4','/api/media/5913bd67-0392-499d-ba34-5918934e61a4?variant=thumbnail','الجيش الإسرائيلي يعلن مقتل قائد سرية في لواء خان يونس التابع لحماس',801,451,'valid','published','archived','valid',40,'4a5783889da36ee0e51b469224952f1cf3cb95c69aa0823e2b38ea6705a9fe6b','d0adff299b5306474a6911b786cf80a8d586c63b69d1524b173dd5176f120d15','محدّث','2026-08-15T10:10:11.930Z','2026-10-07T20:50:49.632Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","التعليم والتدريب"]','["السفر والسياحة","التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"السفر","score":1.5},{"category":"السيارات","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:50:49.632Z',200,90,0,'source_article_available','',NULL,NULL,'body:9ff3d592eb2417d6c3553b4cbb844d37c223b99adb501d1f252959dfda02341a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3729168c-b0ba-4a5e-b5c1-7ec3976a2c20','news-3729168c-b0ba-4a5e-b5c1-7ec3976a2c20','الاتحاد يعير الإسباني أوناي هيرنانديز إلى جيرونا حتى 2027','الاتحاد يعير الاسباني اوناي هيرنانديز الي جيرونا حتي 2027','وافقت إدارة نادي الاتحاد على إعارة لاعب الفريق الأول لكرة القدم الإسباني أوناي هيرنانديز إلى نادي جيرونا الإسباني حتى نهاية الموسم الرياضي 2026/ 2027م.','["وتأتي هذه الخطوة من جانب إدارة الاتحاد في إطار إعادة ترتيب أوراق الفريق، وإتاحة الفرصة أمام اللاعب لخوض تجربة احترافية جديدة في الدوري الإسباني واستعادة حساسية المباريات.","وانضم اللاعب الإسباني إلى صفوف الاتحاد في فبراير 2025، بموجب عقد يمتد لثلاثة أعوام، قادمًا من برشلونة.","ومنذ انضمامه إلى الفريق شارك في 10 مباريات، سجل خلالها هدفًا واحدًا وصنع ثلاثة أهداف، قبل أن تتم إعارته في النصف الثاني من الموسم ذاته إلى نادي الشباب؛ حيث شارك في 31 مباراة، دون أن يسجل أي هدف، وأسهم في صناعة هدف واحد."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/xcci3rp','https://sabq.org/article/xcci3rp','','https://sabq.org/article/xcci3rp','صحيفة سبق','السعودية','2026-08-14T11:15:00.000Z','2026-08-14T14:16:00.000Z','2026-08-15T10:10:13.209Z','https://media.sabq.org/news/2026/08/a8f994c2-5777-4acd-aaf3-318a891b0fa9/w467.webp','/api/media/3729168c-b0ba-4a5e-b5c1-7ec3976a2c20','/api/media/3729168c-b0ba-4a5e-b5c1-7ec3976a2c20?variant=thumbnail','الاتحاد يعير الإسباني أوناي هيرنانديز إلى جيرونا حتى 2027',467,324,'valid','published','archived','valid',89,'69e5255fd871e6eafd8da904ed12ffcd537d81bde45b1a91218bbf918d3c9fed','4c697c332e42253c02db2d434c6341990010b400e5898b987aba1583bc9240be','محدّث','2026-08-15T10:10:13.209Z','2026-10-07T20:50:43.778Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الاقتصاد والأسواق"]','["الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[{"category":"الطاقة والصناعة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الصحة","score":0}]','Active','2026-10-07T20:50:43.778Z',200,92,0,'source_article_available','',NULL,NULL,'body:b090955c555fe1d123b404d8e81f274d6cdb35fdc58051e8bf32bd5e9717a873','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4282f761-122f-46d3-b009-84397d9c73f2','news-4282f761-122f-46d3-b009-84397d9c73f2','«الأرصاد»: الدمام الأعلى حرارة بـ48 مئوية.. وأبها الأدنى','الارصاد الدمام الاعلي حراره بـ48 مئويه وابها الادني','توقَّع المركز الوطني للأرصاد، درجات الحرارة الكبرى والصغرى، على بعض مدن المملكة؛ مشيرًا إلى أن الدمام تسجل أعلى درجة حرارة بـ 48 درجة مئوية، فيما تسجل أبها أدنى درجة حرارة بـ 20 درجة مئوية.','["وذكر مركز الأرصاد، عبر موقعه الرسمي، أن درجات الحرارة الكبرى المتوقعة اليوم الدمام 48، الرياض 46، مكة المكرمة 44، جدة 40، المدينة المنورة 43 درجة مئوية.","وأضاف: كما تبلغ درجات الحرارة الكبرى على مدن أبها 31، عرعر 41، نجران 42، تبوك 36، جازان 37 درجة مئوية.","وتابع: أما درجات الحرارة الصغرى على بعض المدن، فجاءت كالآتي: أبها 20، الباحة 22، الرياض 32، مكة المكرمة 34، المدينة المنورة 30، جدة 31، نجران 28، جازان 32، تبوك 27 درجة مئوية."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/dj41vnn9w','https://ajel.sa/local/dj41vnn9w','https://ajel.sa/local/dj41vnn9w','https://ajel.sa/local/dj41vnn9w','فريق التحرير','السعودية','2026-08-15T05:03:00.000Z','Wed, 07 Oct 2026 20:50:05 GMT','2026-08-15T12:11:20.067Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%AF%D8%B1%D8%AC%D8%A7%D8%AA-%D8%A7%D9%84%D8%AD%D8%B1%D8%A7%D8%A9-2-pd3FyLzF.jpg','/api/media/4282f761-122f-46d3-b009-84397d9c73f2','/api/media/4282f761-122f-46d3-b009-84397d9c73f2?variant=thumbnail','«الأرصاد»: الدمام الأعلى حرارة بـ48 مئوية.. وأبها الأدنى',1200,675,'valid','published','archived','valid',99,'d3167ae917a32e501f70b6ee2d71b185a9291ff4187dd03f7bdaf5ca7922fe69','6a52ed058effc2055eadddb2586dadb09c6dc6d771e876fced92cfc80b0c4f67',NULL,'2026-08-15T12:11:20.067Z','2026-10-07T20:50:07.197Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة","جدة","تبوك","جازان","نجران","الرياض","الدمام"]','["الطقس والمناخ","المدينة المنورة"]','classified','','[{"category":"البيئة والمناخ","score":3},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T20:50:07.197Z',200,91,0,'source_content_changed','',NULL,NULL,'body:0b5bf1aac50a868d0e5747173b5e4641c9811f944393f2f4ac7650507f3e25d1','Wed, 07 Oct 2026 20:50:05 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('167342b3-282d-4e5e-afdc-fc38400da118','news-167342b3-282d-4e5e-afdc-fc38400da118','صنبورك وخزانك تحت المراقبة.. غرامات تصل إلى 200 ألف ريال لثماني مخالفات مائية «حضرية» والعمل باللائحة من 21 مارس 2027','صنبورك وخزانك تحت المراقبه غرامات تصل الي 200 الف ريال لثماني مخالفات مائيه حضريه والعمل باللائحه من 21 مارس 2027','اعتمد وزير البيئة والمياه والزراعة المهندس عبدالرحمن بن عبدالمحسن الفضلي، بقراره رقم (481530197) وتاريخ 19/2/1448هـ، اللائحة التنفيذية «المحدثة» للمراقبة والالتزام بمعايير كفاءة وترشيد المياه، التي نشرت صحيفة «أم القرى» نصها الكامل في عددها الصادر اليوم الجمعة، متضمنةً — للمرة الأولى — جدولاً تفصيلياً بالغرامات يبدأ من 500 ريال ويصل إلى 200 ألف ريال، على أن','["وتسري أحكام اللائحة على جميع الأشخاص ذوي الصفة الطبيعية أو الاعتبارية، عامةً كانت أم خاصة، والقطاع غير الربحي، في القطاعات الحضري والزراعي والصناعي، فيما يتولى المركز الوطني لكفاءة وترشيد المياه ضبط المخالفات والتحقيق فيها بتفويض من الوزير، وتُحال محاضر الضبط إلى اللجنة المنصوص عليها في نظام المياه للفصل وإيقاع العقوبات.","هذه غراماتها قسمت اللائحة المخالفات الثماني إلى فئتين بحسب جسامتها: ست مخالفات «غير جسيمة» تبدأ بإنذار ومهلة تصحيحية 14 يوماً، فإن لم يصحح المخالف وضعه توقَّع الغرامة متدرجةً بين المرة الأولى فالثانية فالثالثة: الأدوات الصحية غير المرشّدة (خلاطات، صنابير، مراوش، شطافات، صناديق طرد): 1,000 ريال، ثم 2,000، ثم 10,000 — عن كل أداة .","العبث بالجزء المرشّد أو إزالته : 500 ريال، ثم 1,000، ثم 2,000 — عن كل أداة.","هدر مياه الشرب من الخزان الأرضي أو العلوي بسبب تشققات أو عطل أو غياب العوامة: 5,000 ريال، ثم 10,000، ثم 50,000 — عن كل خزان ."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/xw2yzww','https://sabq.org/article/xw2yzww','','https://sabq.org/article/xw2yzww','صحيفة سبق','السعودية','2026-08-14T14:19:00.000Z','2026-08-14T17:19:00.000Z','2026-08-15T12:16:13.807Z','https://media.sabq.org/news/2026/08/0eaf1e5d-9aa2-45b1-9cdd-edbabacda8ed/w1188.webp','/api/media/167342b3-282d-4e5e-afdc-fc38400da118','/api/media/167342b3-282d-4e5e-afdc-fc38400da118?variant=thumbnail','صنبورك وخزانك تحت المراقبة.. غرامات تصل إلى 200 ألف ريال لثماني مخالفات مائية «حضرية» والعمل باللائحة من 21 مارس 2027',1188,646,'valid','published','archived','valid',46,'e81577610486bf6fb012fafda28112c5ec96592a6f6ce14d4a4a39c39c70fc1f','e99813e72c4266cd48e7df6b26ae280f9b4847bd5a02ab4b6e64cd37572e9fb3','محدّث','2026-08-15T12:16:13.807Z','2026-10-07T20:49:58.140Z','','',0,0,'saudi_region','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','manual_approved','below_category_threshold','[{"category":"السياسة","score":1.5},{"category":"الصحة","score":1.5},{"category":"الرياضة","score":1.5}]','Active','2026-10-07T20:49:58.140Z',200,81,0,'source_article_available','',NULL,NULL,'body:e6733bd23bcfa4b7d3f23a55cd6c13e0c0c134fe2be45dc77a0392665f59b8f5','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('314bb759-498b-4ffe-b1a1-b0b0f012707c','news-314bb759-498b-4ffe-b1a1-b0b0f012707c','مقره الرياض ونشاطه يمتد إلى دول اليونسكو كافة.. صدور النظام الأساس للمركز الدولي لأبحاث وأخلاقيات الذكاء الاصطناعي','مقره الرياض ونشاطه يمتد الي دول اليونسكو كافه صدور النظام الاساس للمركز الدولي لابحاث واخلاقيات الذكاء الاصطناعي','صدر النظام الأساس للمركز الدولي لأبحاث وأخلاقيات الذكاء الاصطناعي، الذي يتخذ من الرياض مقراً رئيساً له بوصفه مركزاً دولياً يعمل تحت رعاية منظمة الأمم المتحدة للتربية والعلم والثقافة (اليونسكو)، ويتمتع بالشخصية الاعتبارية والاستقلال المالي والإداري، فيما يشمل نطاق أنشطته جميع الدول الأعضاء في المنظمة، مع جواز إنشاء فروع ومكاتب له داخل المملكة وخارجها.','["وبموجب النظام، يعمل المركز في أربعة مجالات رئيسية: دعم البحث والتطوير في الذكاء الاصطناعي، وتعزيز الوعي والتواصل في شأن أبحاثه وأخلاقياته، وتقديم التوصيات ذات الصلة، وبناء القدرات — إقليمياً ودولياً.","وخوّله النظام صلاحيات واسعة تشمل تقديم الخدمات الاستشارية الفنية، وبناء منصات دولية لتبادل الخبرات، وإبرام الاتفاقيات مع المنظمات والجهات الداخلية والخارجية، وقبول التبرعات والأوقاف، وتحديد مقابل مالي لخدماته.","رئاسة سعودية وتمثيل دولي ونص النظام على أن يرأس مجلس إدارة المركز رئيس الهيئة السعودية للبيانات والذكاء الاصطناعي «سدايا»، بعضوية ممثل عن المدير العام لليونسكو، وما يصل إلى سبعة أعضاء يمثلون دولاً أعضاء في المنظمة، وخمسة يمثلون هيئات ومؤسسات وطنية حكومية أو خاصة، وممثلَين لهيئات دولية — على أن تكون العضوية عملاً تطوعياً بلا أجر مدتها أربع سنوات.","ويُعيَّن المدير العام للمركز بقرار من رئيس المجلس لمدة أربع سنوات قابلة للتجديد، ويتولى تمثيل المركز قانونياً في المحافل الدولية."]','الذكاء الاصطناعي','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ruhify3','https://sabq.org/article/ruhify3','','https://sabq.org/article/ruhify3','صحيفة سبق','السعودية','2026-08-14T14:10:00.000Z','2026-08-14T17:11:00.000Z','2026-08-15T12:16:14.114Z','https://media.sabq.org/news/2026/08/a91493d8-d5f5-4993-8428-0a6506e31ae0/w1200.webp','/api/media/314bb759-498b-4ffe-b1a1-b0b0f012707c','/api/media/314bb759-498b-4ffe-b1a1-b0b0f012707c?variant=thumbnail','مقره الرياض ونشاطه يمتد إلى دول اليونسكو كافة.. صدور النظام الأساس للمركز الدولي لأبحاث وأخلاقيات الذكاء الاصطناعي',1200,675,'valid','published','archived','valid',46,'8f0320b450bc9b914f839d51841db7f9bc397a367cde49fd6bd3044766451160','09176bef53a8dd8caba2e5def2e46683213b7d544f9d340e97c0649284de0ba6','محدّث','2026-08-15T12:16:14.114Z','2026-10-07T20:49:57.073Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إدارة المركز رئيس الهيئة","رئيس الهيئة السعودية للبيانات والذكاء","الثقافة والفنون","الرياض"]','["مجلس إدارة المركز رئيس الهيئة","رئيس الهيئة السعودية للبيانات والذكاء","الثقافة والفنون"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":3},{"category":"الذكاء الاصطناعي","score":2}]','Active','2026-10-07T20:49:57.073Z',200,79,0,'source_article_available','',NULL,NULL,'body:195234a749550944e4b7d2210f85e3b30db4843bcbc1200daa9802bb43613436','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dd7343d4-a6f7-45ab-b358-e6b2b1bf3849','news-dd7343d4-a6f7-45ab-b358-e6b2b1bf3849','الهلال يمزّق شباك الفيصلي برباعية في انطلاقة دوري روشن','الهلال يمزق شباك الفيصلي برباعيه في انطلاقه دوري روشن','استهل الهلال مشواره في دوري روشن للمحترفين بالفوز على ضيفه الفيصلي بنتيجة 4/2، في اللقاء الذي جمع الفريقين مساء اليوم الجمعة على ملعب المملكة أرينا في العاصمة الرياض، بقيادة الحكم الإسباني خيسوس، وشهدت المباراة احتساب ثلاث ركلات جزاء للأزرق.','["وانتهى الشوط الأول بتقدم الهلال بثلاثة أهداف دون مقابل، حيث افتتح كريم بنزيما التسجيل من ركلة جزاء في الدقيقة 19.","وأضاف مالكوم الهدف الثاني للهلال بتسديدة قوية في الدقيقة 26، قبل أن يختتم نيفز ثلاثية الأزرق في الدقيقة 28 من ركلة جزاء.","وفي الشوط الثاني ظهر الفيصلي بصورة لافتة، وقلّص الفارق بتسجيل هدفه الأول عن طريق الكسندري مندي في الدقيقة 59.","وأضاف ثيو بوجندا الهدف الثاني للفيصلي في الدقيقة 64 بضربة رأسية من بين مدافعي الهلال."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/19oe4ij','https://sabq.org/article/19oe4ij','','https://sabq.org/article/19oe4ij','صحيفة سبق','السعودية','2026-08-14T14:09:00.000Z','2026-08-14T17:09:00.000Z','2026-08-15T12:16:15.182Z','https://media.sabq.org/news/2026/08/2ff3e29d-636d-48ad-b83a-2d014bb2690c/w1600.webp','/api/media/dd7343d4-a6f7-45ab-b358-e6b2b1bf3849','/api/media/dd7343d4-a6f7-45ab-b358-e6b2b1bf3849?variant=thumbnail','الهلال يمزّق شباك الفيصلي برباعية في انطلاقة دوري روشن',1600,2000,'valid','published','archived','valid',99,'a66eb22388890e8c67b1fe68bbed3a3dd532ad92e53c8116bdf0d8b1de5ca2e2','e17d96d399b5bcb86fadb811fd073a77d2b42d3f54ab1b1c6a5607d4ee4eb431','محدّث','2026-08-15T12:16:15.182Z','2026-10-07T20:49:57.015Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:49:57.015Z',200,82,0,'source_article_available','',NULL,NULL,'body:39c4ee0d53f18bbc34ec266c2d900c2379e9edda1b52752c09ae3f5d9cf5bfee','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8ae8d6d3-7e61-424f-8631-3444966abde7','news-8ae8d6d3-7e61-424f-8631-3444966abde7','وفاة علي آل مدهش في جدة','وفاه علي ال مدهش في جده','انتقل إلى رحمة الله تعالى اليوم الجمعة في مدينة جدة الشيخ علي بن عبدالله آل مدهش، عمّ الدكتور سعيد بن صالح آل مدهش، أحد رواد الكشافة بمنطقة الرياض.','["ويُعد الفقيد من الشخصيات التي عُرفت بحسن السيرة وطيب المعشر، سائلين الله أن يجعل ما قدّمه في حياته في ميزان حسناته، وأن يتغمّده بواسع رحمته ومغفرته، ويسكنه فسيح جنّاته.","وتتقدّم «سبق» بخالص العزاء وصادق المواساة للدكتور سعيد بن صالح آل مدهش، ولأسرة الفقيد وذويه ومحبيه، سائلين المولى عز وجل أن يجبر مصابهم، ويربط على قلوبهم، ويلهمهم الصبر والسلوان."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/89gqnea','https://sabq.org/article/89gqnea','','https://sabq.org/article/89gqnea','صحيفة سبق','السعودية','2026-08-14T13:47:00.000Z','2026-08-14T16:47:00.000Z','2026-08-15T12:16:16.321Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/4539a577-cdfd-40b0-a458-47605962bc00/w=1200,h=675,q=90,fit=cover,gravity=auto','/api/media/8ae8d6d3-7e61-424f-8631-3444966abde7','/api/media/8ae8d6d3-7e61-424f-8631-3444966abde7?variant=thumbnail','وفاة علي آل مدهش في جدة',1200,675,'valid','published','archived','valid',100,'e0fd6bfb54415fe0b739e2d3e007a36ff3d54465e703a1aa8a40c1cf709a0a30','276c729024492981433525b6c783810bed1f8cf5a5155698df618912c1230149','محدّث','2026-08-15T12:16:16.322Z','2026-10-07T20:49:57.071Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["جدة"]','[]','manual_approved','','[]','Active','2026-10-07T20:49:57.071Z',200,79,0,'source_article_available','',NULL,NULL,'body:9a40d0aac7c60d1faf77f0389977b2de35840fc96f75185a2e7308e4460b2795','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5b08776f-d35e-4f40-a9ae-4154e465950e','news-5b08776f-d35e-4f40-a9ae-4154e465950e','«ذاكرة الرياض» توثق تطور ملاعب العاصمة حتى مونديال 2034','ذاكره الرياض توثق تطور ملاعب العاصمه حتي مونديال 2034','استعرضت أمانة منطقة الرياض جانبًا من رحلة تطور كرة القدم في العاصمة من زاوية عمارة منشآتها الرياضية وملاعبها، وذلك ضمن سلسلة توثيقية يستعيدها مشروع «ذاكرة الرياض» تحت عنوان «نصف قرن من العمارة 1950م–2000م»، تزامنًا مع انطلاق موسم جديد من دوري روشن السعودي.','["وأوضحت الأمانة، عبر حسابها الرسمي على منصة «إكس»، أن المنشآت الرياضية في المراحل المبكرة من كرة القدم السعودية كانت تُبنى حول احتياجات الأندية، وتضم ملاعب للتدريب والمباريات، إلى جانب مرافق مخصصة للفرق والإدارة.","وبيّنت أن هذا النموذج يظهر في منشآت أندية الهلال والشباب والنصر والرياض، التي وثقها مشروع «ذاكرة الرياض» ورتّبها وفق سنوات افتتاحها، في رصد للتحولات التي شهدتها المنشآت الرياضية في العاصمة على مدى عقود.","نقلة في عمارة الاستادات ومع توسع كرة القدم السعودية واستضافتها منافسات أكبر، برزت الحاجة في الرياض إلى منشآت بمقياس مختلف؛ لتبدأ عام 1983م أعمال تشييد استاد الملك فهد الدولي، استعدادًا لاستضافة العاصمة دورة كأس الخليج التاسعة، قبل افتتاحه رسميًا عام 1988م بالتزامن مع البطولة.","وبحسب ما أوردته أمانة منطقة الرياض، صُمّم الاستاد من قِبل آين فريزر، وجون روبرتز وشركاؤهما، بسعة جماهيرية كبيرة وسقف مستلهم من الخيمة التقليدية، ليصبح أحد أبرز المعالم الرياضية والمعمارية في الرياض، ومنشأة تستضيف المباريات والبطولات الكبرى وتخدم المشهد الرياضي في العاصمة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/bzXkkQv','https://sabq.org/article/bzXkkQv','','https://sabq.org/article/bzXkkQv','سعد الراشد','السعودية','2026-08-14T13:33:00.000Z','2026-08-14T16:33:00.000Z','2026-08-15T12:16:16.535Z','https://media.sabq.org/news/2026/08/f76d8436-d5ef-4417-ac5d-b22bc279b17f/w1280.webp','/api/media/5b08776f-d35e-4f40-a9ae-4154e465950e','/api/media/5b08776f-d35e-4f40-a9ae-4154e465950e?variant=thumbnail','«ذاكرة الرياض» توثق تطور ملاعب العاصمة حتى مونديال 2034',1280,1600,'valid','published','archived','valid',99,'32d1115942ca9d95a81e411459f67d49b32f94e552dfcf3b7e1b2333e2bdc69f','f5f5169192be4970cf982c54bbc477c20e2fea28032009f60a5facfee42c48b8','محدّث','2026-08-15T12:16:16.535Z','2026-10-07T20:49:56.460Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الرياضة السعودية","الرياض"]','["التعليم والتدريب","الرياضة السعودية"]','classified','','[{"category":"المناطق","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T20:49:56.460Z',200,75,0,'source_article_available','',NULL,NULL,'body:0b99c33e00c5103cd3b2bd3d9d6a8fe2f7fb4589c672f0c1647e250b046f2ae7','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('110b11a0-8e00-4706-93c5-eeb72cf6823f','news-110b11a0-8e00-4706-93c5-eeb72cf6823f','مصرع شخصين في تحطم طائرة خفيفة شمال ويلز','مصرع شخصين في تحطم طائره خفيفه شمال ويلز','لقي شخصان مصرعهما في حادث تحطم طائرة خفيفة بمنطقة نائية بالقرب من بلدة تراوسفينيد في شمال ويلز.','["وأفادت شرطة شمال ويلز بالعثور على الطائرة بعد عمليات بحث جوية وبرية شاركت فيها عدة جهات، مؤكدةً مصرع الشخصين اللذين كانا على متنها في موقع الحادث.","وأوضحت الشرطة أن فرع التحقيق في حوادث الطيران «AAIB» أرسل فريقًا من المحققين إلى موقع تحطم الطائرة، للوقوف على ملابسات الحادث بالتعاون مع الشرطة المحلية."]','العالم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/rg3ic9q','https://sabq.org/article/rg3ic9q','','https://sabq.org/article/rg3ic9q','صحيفة سبق','السعودية','2026-08-14T14:04:00.000Z','2026-08-14T17:04:00.000Z','2026-08-15T12:16:17.528Z','https://media.sabq.org/news/2026/08/15bef9ed-058b-4f68-9851-08d89278d3a6/w380.webp','/api/media/110b11a0-8e00-4706-93c5-eeb72cf6823f','/api/media/110b11a0-8e00-4706-93c5-eeb72cf6823f?variant=thumbnail','مصرع شخصين في تحطم طائرة خفيفة شمال ويلز',380,200,'valid','published','archived','valid',40,'116a30b787cb27cfd46a901ec5e1b48d111079faf8cf517ef790b9157c04240f','60051c1cfee0008ff1791e5926eb5dd508b4f97793ea59b72c3fba480207c02d','محدّث','2026-08-15T12:16:17.528Z','2026-10-07T20:49:55.925Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة"]','["السفر والسياحة"]','manual_approved','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"السفر","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:49:55.925Z',200,74,0,'source_article_available','',NULL,NULL,'body:ed39b58c7c88f1236901fe22ca934022677aa685826bb0f5993940199809f6e8','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a839ce81-2e76-4b45-8cde-612f17e68903','news-a839ce81-2e76-4b45-8cde-612f17e68903','إجراءات تنظيمية متكاملة تعزّز شفافية المزاد الدولي للصقور','اجراءات تنظيميه متكامله تعزز شفافيه المزاد الدولي للصقور','يطبّق المركز الوطني للصقور منظومة متكاملة من الإجراءات التنظيمية والقانونية والمالية في المزاد الدولي لمزارع إنتاج الصقور، المقام في مقر المركز بمَلهم شمال مدينة الرياض حتى 25 أغسطس الجاري، بهدف ضمان حقوق البائعين والمشترين، وتوثيق عمليات المبايعة، وتعزيز الشفافية في جميع مراحل انتقال ملكية الصقور.','["وأوضح المتحدث الرسمي بالمركز الوطني للصقور وليد الطويل أن المركز يبذل جهودًا كبيرة لضمان حقوق جميع الأطراف في صفقات البيع، مشيرًا إلى أن رحلة البيع تبدأ باتفاق صاحب المزرعة والمشتري على قيمة الصقر، ثم التوجه إلى قسم المبيعات لإتمام إجراءات المبايعة الرسمية، التي تمر بعدة مراحل تضمن دقة البيانات وسلامة عملية التعاقد.","وبيّن الطويل أنه عقب الاتفاق يُنقل الصقر إلى لجنة الفرز والعبث، التي تتولى التحقق من موقعه ضمن الفئة المناسبة، وقياس مواصفاته بدقة بما يشمل الحجم والطول والعرض، للتأكد من مطابقة البيانات المسجلة للصقر المعروض.","وأضاف أن المعاملة تنتقل بعد ذلك إلى اللجنة القانونية، حيث تُستكمل إجراءات المبايعة بتوقيع الطرفين بما يثبت عملية البيع ويحفظ حقوق البائع والمشتري، ثم تُحوّل المعاملة إلى القسم المالي، الذي يتولى استكمال إجراءات السداد وضمان تسليم قيمة الصقر من المشتري إلى صاحب مزرعة الإنتاج.","وأشار المتحدث الرسمي إلى أن الإجراءات تتواصل بتركيب الحجل للصقر، ثم الانتقال إلى قسم التسجيل لإدراجه في نظام السباقات بالمركز، بما يتيح توثيق بياناته وربطها بسجلاته الرسمية، ثم يُمنح المشتري في المرحلة الأخيرة ورقة خروج معتمدة تخوّله إخراج الصقر من بوابة المزاد، بعد اكتمال جميع الإجراءات النظامية، لتُختتم بذلك رحلة البيع ضمن مسار متكامل يجمع بين التنظيم والدقة وحماية الحقوق."]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/bxppmud','https://sabq.org/article/bxppmud','','https://sabq.org/article/bxppmud','صحيفة سبق','السعودية','2026-08-14T13:18:00.000Z','2026-08-14T16:19:00.000Z','2026-08-15T12:16:18.734Z','https://media.sabq.org/news/2026/08/2719161d-07ff-4c54-a6fc-5415763bea44/w1600.webp','/api/media/a839ce81-2e76-4b45-8cde-612f17e68903','/api/media/a839ce81-2e76-4b45-8cde-612f17e68903?variant=thumbnail','إجراءات تنظيمية متكاملة تعزّز شفافية المزاد الدولي للصقور',1600,1066,'valid','published','archived','valid',41,'79f549046cc587ea055f481d0b3c986cb536126189e7980b22aed7502a2faf61','06855adae42644cb78580c7ac38acc9b634b850ea9daa8a426ed99a4c5fae4a6','محدّث','2026-08-15T12:16:18.734Z','2026-10-07T20:49:57.585Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:49:57.585Z',200,82,0,'source_article_available','',NULL,NULL,'body:4f8a7240c520d47706ad486a865d3f308aae20e8b86dbd770c874ed4242ab04c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('614838d9-504e-41c3-9d41-2a678209133e','news-614838d9-504e-41c3-9d41-2a678209133e','شقيقتان من تبوك تحصدان ذهبية وبرونزية في معرض عالمي بسنغافورة','شقيقتان من تبوك تحصدان ذهبيه وبرونزيه في معرض عالمي بسنغافوره','حققت الشقيقتان السعوديتان اعتزاز ورند النفيعي، من منطقة تبوك، إنجازًا دوليًا بحصدهما الميدالية الذهبية والميدالية البرونزية خلال مشاركتهما في معرض سنغافورة العالمي للاختراعات «WorldInvent Singapore 2026».','["وجاء الإنجاز من خلال مشاركتهما بمشروعين ابتكاريين؛ الأول في مجال الهندسة الزراعية ضمن مشروع «ARCN»، فيما تناول المشروع الآخر تطوير بطاريات الليثيوم والابتكار في مجال الطاقة.","وأعربت الشقيقتان عبر «سبق» عن سعادتهما بهذا الإنجاز، مؤكدتين أن ما تحقق يمثل ثمرةً للدعم الذي يحظى به الموهوبون والمبتكرون في المملكة، ومشيدتين بما يقدمه التعليم من بيئة محفزة على الابتكار وتنمية مهارات الطلبة، وما توفره البرامج التعليمية والتدريبية من فرص للمشاركة في المحافل الدولية.","وقدمتا شكرهما وتقديرهما لوالديهما، اللذين كان لدعمهما وتشجيعهما المستمر دور كبير في مسيرتهما، مؤكدتين أن وقوف الأسرة إلى جانب أبنائها يمثل دافعًا مهمًا لتحقيق الطموحات والوصول إلى منصات التتويج الدولية.","ويضاف هذا الإنجاز إلى سلسلة النجاحات التي يحققها أبناء وبنات منطقة تبوك في المحافل المحلية والدولية، ويعكس ما تتمتع به المواهب الوطنية من قدرات متميزة في مجالات البحث والابتكار والاختراع."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/uebxsk9','https://sabq.org/article/uebxsk9','','https://sabq.org/article/uebxsk9','بدر الجبل ','السعودية','2026-08-14T13:06:00.000Z','2026-08-14T16:07:00.000Z','2026-08-15T12:16:18.749Z','https://media.sabq.org/news/2026/08/34927ef6-6c3d-4894-808b-022cc9d168cb/w1214.webp','/api/media/614838d9-504e-41c3-9d41-2a678209133e','/api/media/614838d9-504e-41c3-9d41-2a678209133e?variant=thumbnail','شقيقتان من تبوك تحصدان ذهبية وبرونزية في معرض عالمي بسنغافورة',1214,873,'valid','published','archived','valid',44,'5ed367b55e39103289c9ab962a2c1c0c6621d989406a2a93f57cd3c1ec82abd4','fb747d9b7b4b53452ef82ae8d2c9a817ed4614b46a6ed0e04800f8692e2235d6','محدّث','2026-08-15T12:16:18.749Z','2026-10-07T20:48:56.657Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","التعليم والتدريب","الاقتصاد والأسواق","تبوك"]','["الطاقة والنفط","التعليم والتدريب","الاقتصاد والأسواق"]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":3},{"category":"المجتمع","score":3},{"category":"التعليم","score":3}]','Temporarily Unreachable','2026-10-07T20:48:56.657Z',NULL,78,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9412113a-1e55-43db-98d5-037f5cd4e4d0','news-9412113a-1e55-43db-98d5-037f5cd4e4d0','نيوم يهزم الفيحاء بثنائية في افتتاح دوري روشن','نيوم يهزم الفيحاء بثنائيه في افتتاح دوري روشن','حصد فريق نيوم فوزاً ثميناً في افتتاح الجولة الأولى من دوري روشن السعودي للمحترفين للموسم 2026/2027، بعد تغلبه على ضيفه الفيحاء بهدفين مقابل هدف، في اللقاء الذي أُقيم مساء الجمعة على ملعب مدينة الملك خالد الرياضية في تبوك، بقيادة الحكم علي القحطاني.','["سجّل نيوم الهدف الأول في الشوط الأول برأسية أمادوكوني عند الدقيقة 26، قبل أن يضيف سعيد بن رحمه الهدف الثاني لفريقه في الدقيقة 36، لينتهي الشوط الأول بتقدم نيوم بهدفين دون مقابل.","وفي الشوط الثاني، قلّص الفيحاء الفارق بتسجيله الهدف الأول عن طريق هوغو مورا برأسية جميلة عند الدقيقة 76.","بهذه النتيجة، حسم نيوم الانتصار وحصد أولى نقاطه الثلاث في الدوري، فيما خرج الفيحاء من مباراته الافتتاحية في دوري روشن من دون نقاط."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/z8uki60','https://sabq.org/article/z8uki60','','https://sabq.org/article/z8uki60','صحيفة سبق','السعودية','2026-08-14T12:53:00.000Z','2026-08-14T15:54:00.000Z','2026-08-15T12:16:21.409Z','https://media.sabq.org/news/2026/08/58fbd7f1-9713-4260-9dd2-61ef8ed08849/w1600.webp','/api/media/9412113a-1e55-43db-98d5-037f5cd4e4d0','/api/media/9412113a-1e55-43db-98d5-037f5cd4e4d0?variant=thumbnail','نيوم يهزم الفيحاء بثنائية في افتتاح دوري روشن',1600,2000,'valid','published','archived','valid',99,'60c1cb3778a728615b3f066d93d97d57c978fafbc281b9de7106cdc8b75968eb','9c6e996d6be7516643bfb442f5190a21c03d158cb6d19425a2feebbf1c677f86','محدّث','2026-08-15T12:16:21.409Z','2026-10-07T20:50:00.018Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:50:00.018Z',200,84,0,'source_article_available','',NULL,NULL,'body:e9f1375ff4d7df54765116ba25585c5a60e4d2e07d47258d0b621a2500bed31d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('da0c31de-e0d9-478c-88a6-3eca915def98','news-da0c31de-e0d9-478c-88a6-3eca915def98','الملك وولي العهد يعزيان رئيس الصين في وفاة تشو رونغ جي','الملك وولي العهد يعزيان رئيس الصين في وفاه تشو رونغ جي','بعث خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، برقية عزاء ومواساة، إلى فخامة الرئيس شي جين بينغ رئيس جمهورية الصين الشعبية، في وفاة رئيس مجلس الدولة الأسبق في جمهورية الصين الشعبية السيد تشو رونغ جي.','["وقال الملك المفدى: «تلقينا نبأ وفاة رئيس مجلس الدولة الأسبق في جمهورية الصين الشعبية السيد تشو رونغ جي، ونعرب لفخامتكم ولأسرة الفقيد ولشعبكم الصديق عن أحرّ التعازي وأصدق المواساة، متمنين ألّا تروا أي سوء أو مكروه».","وقال سمو ولي العهد: «تلقيت نبأ وفاة رئيس مجلس الدولة الأسبق في جمهورية الصين الشعبية السيد تشو رونغ جي، وأعرب لفخامتكم ولأسرة الفقيد كافة عن بالغ التعازي وصادق المواساة، متمنيًا لكم دوام الصحة والسلامة، وألّا تروا أي سوء»."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/rfnq9wb','https://sabq.org/article/rfnq9wb','','https://sabq.org/article/rfnq9wb','صحيفة سبق','السعودية','2026-08-14T12:22:00.000Z','2026-08-14T15:22:00.000Z','2026-08-15T12:16:22.589Z','','','','الملك وولي العهد يعزيان رئيس الصين في وفاة تشو رونغ جي',NULL,NULL,'all_candidates_failed (og:fetch failed | structured:fetch failed | structured:fetch failed | structured:fetch failed)','review','archived','valid',91,'054bce670dd181c60563a130222662a6267c81bdb8f40376fd54286571b6b123','43218b90ad85b9dd500f95fd34ef51cec46d4bf1a74dcc48733864629a9d41b4','محدّث','2026-08-15T12:16:22.589Z','2026-10-07T20:49:58.256Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السياسة","رئيس الصين في وفاة تشو","ولي العهد تلقيت نبأ وفاة","الصحة العامة","الصين","الملك وولي","وفاة تشو رونغ","الصين وفاة تشو"]','["رئيس الصين في وفاة تشو","ولي العهد تلقيت نبأ وفاة","الصحة العامة","الملك وولي","وفاة تشو رونغ","الصين وفاة تشو"]','classified','','[]','Active','2026-10-07T20:49:58.256Z',200,90,0,'source_article_available','',NULL,NULL,'body:3af7f836d6b460345175cb9dfc2b9fb9848e031483c6809283e7b44286370e5e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('492faa96-9de1-4b85-9f7e-08c2797d7339','news-492faa96-9de1-4b85-9f7e-08c2797d7339','مطالب بتنظيم تقاطع طريق جديد شمال حائل ورفع رصيف مخالفات أمام المشاتل','مطالب بتنظيم تقاطع طريق جديد شمال حائل ورفع رصيف مخالفات امام المشاتل','طالب مستفيدو الطريق الجديد الذي يربط حي المصيف باللقيطة ويُسهّل الوصول إلى المدينة الجامعية لجامعة حائل، عبر «سبق»، أمانة منطقة حائل وإدارة المرور بالمنطقة بتأمين بداية مساره عند تقاطع طريق مشار الفرعي مع طريق أمير المؤمنين علي بن أبي طالب رضي الله عنه.','["كما طالب الأهالي بمنع بعض المركبات من تجاوز الرصيف أمام المشاتل الواقعة على طريق القاعد شمال حائل بهدف الدوران بصورة غير نظامية، مؤكدين أن الموقعين يشكلان خطرًا على قائدي المركبات، خصوصًا مع قرب بدء الدراسة وارتفاع كثافة الحركة على الطرق المؤدية إلى الجامعة.","وأظهرت صور من الموقع اتساع التقاطع الواقع عند التقاء طريق مشار الفرعي، المتفرع من طريق مشار–بقعاء الرئيسي، بطريق أمير المؤمنين علي بن أبي طالب رضي الله عنه، ودخول المركبات وخروجها عبر مساحة مفتوحة تتداخل فيها اتجاهات الحركة، وسط مطالب بتنظيم الموقع قبل تزايد أعداد مستخدميه.","وأشاد الأهالي بالطريق الجديد، مؤكدين أنه يمثل إضافة مهمة لشبكة الطرق شمال حائل، ويختصر الوقت والمسافة أمام طلاب الجامعة وموظفيها، ولا سيما القادمين من أحياء المصيف وأجا ودرة مشار وغيرها من الأحياء الشمالية.","وأوضحوا أن الطريق الجديد من شأنه تخفيف الضغط عن المسار الحالي الممتد من ميدان قصر أجا إلى المدينة الجامعية عبر طريق القاعد، الذي يشهد كثافة مرورية عالية في ذروة الصباح، تتكرر عند انتهاء الدوام الرسمي وانصراف طلاب الجامعة بعد الظهر."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/z2oqdfb','https://sabq.org/article/z2oqdfb','','https://sabq.org/article/z2oqdfb','صحيفة سبق','السعودية','2026-08-14T12:46:00.000Z','2026-08-14T15:46:00.000Z','2026-08-15T12:16:23.293Z','https://media.sabq.org/news/2026/08/10835056-f73c-40eb-9d42-c8a927dd476f/w1600.webp','/api/media/492faa96-9de1-4b85-9f7e-08c2797d7339','/api/media/492faa96-9de1-4b85-9f7e-08c2797d7339?variant=thumbnail','مطالب بتنظيم تقاطع طريق جديد شمال حائل ورفع رصيف مخالفات أمام المشاتل',1600,900,'valid','published','archived','valid',54,'ae1867699876436496e890321b27c2a56251d7f8da2f3b6b1b6fb510f2b9d168','14fdd1c69dcf39e6832ed2602ae228178737d2ca81559b3d4bb0a230d90a7588','محدّث','2026-08-15T12:16:23.293Z','2026-10-07T20:50:49.037Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"التعليم","score":3},{"category":"التقنية","score":2},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T20:50:49.037Z',200,92,0,'source_article_available','',NULL,NULL,'body:fc440e914ee0834c41c1a6df1abe77b572982a6273d80813319427f7f75e428a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9a0859d2-7256-4d83-b7d1-bc9fae2c39c9','news-9a0859d2-7256-4d83-b7d1-bc9fae2c39c9','تصعيد حوثي واسع يهز المخا.. 44 مسيّرة و6 زوارق وصواريخ باليستية','تصعيد حوثي واسع يهز المخا 44 مسيره و6 زوارق وصواريخ باليستيه','شهد الساحل الغربي لليمن، اليوم الجمعة، تصعيداً عسكرياً واسعاً مع تجدد الهجمات الحوثية على ميناء المخا ومناطق محيطة به، باستخدام الطائرات المسيّرة والزوارق المفخخة والصواريخ الباليستية، وفق مصادر عسكرية يمنية.','["وقال مصدر عسكري يمني لقناة «العربية» إن الحوثيين أطلقوا 44 طائرة مسيّرة باتجاه ميناء المخا ومنشآت مدنية في الساحل الغربي، مؤكداً أن الدفاعات تمكّنت من إسقاط 15 منها.","كما أشار المصدر إلى إحباط 3 هجمات بزوارق مفخخة من أصل 6 استهدفت ميناء المخا، مضيفاً أن بعض تلك الهجمات حاول استهداف ناقلة نفطية قرب مضيق باب المندب.","هجوم بحري قبالة المخا وفي تطور آخر، كشف المصدر عن إحباط هجوم بحري للحوثيين قبالة سواحل منطقة واحجة في المخا، موضحاً أن العملية نُفذت باستخدام زوارق مأهولة وطائرات مسيّرة.","وبحسب المصدر، أسفرت المواجهات خلال محاولة الهجوم عن مقتل 8 من عناصر الحوثيين.","وفي المقابل، أفاد مصدر عسكري يمني بتنفيذ عشرات الهجمات بالطائرات المسيّرة على مواقع للحوثيين في الساحل الغربي، بالتزامن مع استمرار القصف المدفعي على مواقع للجماعة في جبهات غربي تعز.","قصف بصواريخ باليستية على الميناء ولم يتوقف التصعيد عند الهجمات بالطائرات المسيّرة والزوارق، إذ عاود الحوثيون قصف ميناء المخا بصواريخ باليستية، وفق ما أعلنت القوات الحكومية اليمنية.","وأظهرت صور مباشرة تجدد القصف على منطقة الميناء، في أحدث موجة من الهجمات التي يتعرض لها الساحل الغربي خلال الأيام الأخيرة.","وكان ميناء المخا قد تعرّض قبل أيام لهجوم واسع بالصواريخ والطائرات المسيّرة، أدى، وفق الجيش اليمني، إلى سقوط قتلى وجرحى وإلحاق أضرار بمنشآت مدنية وخدمية."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/5oxzrho','https://sabq.org/article/5oxzrho','','https://sabq.org/article/5oxzrho','صحيفة سبق','السعودية','2026-08-14T12:37:00.000Z','2026-08-14T15:41:00.000Z','2026-08-15T12:16:23.704Z','','','','تصعيد حوثي واسع يهز المخا.. 44 مسيّرة و6 زوارق وصواريخ باليستية',NULL,NULL,'all_candidates_failed (og:image_file_too_small | structured:image_file_too_small | structured:image_file_too_small | structured:image_file_too_small)','review','archived','valid',99,'d821cb6e6d0ef61dd43121aeb522a763baef4251d153a83d81458c558dc68a07','c1632100f0202930f1b4e696b9d107075b9a3c213f9badb0a32fff633d742558','محدّث','2026-08-15T12:16:23.704Z','2026-10-07T20:50:48.427Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية","الطاقة والنفط","السفر والسياحة","اليمن","تصعيد حوثي","حوثي واسع يهز","يهز المخا مسي","واسع يهز المخا"]','["أخبار السعودية","الطاقة والنفط","السفر والسياحة","تصعيد حوثي","حوثي واسع يهز","يهز المخا مسي"]','needs_review','below_category_threshold','[{"category":"السفر","score":1.5},{"category":"الطاقة والصناعة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:50:48.427Z',200,92,0,'source_article_available','',NULL,NULL,'body:bd7d12d7066b5c1a5d0a3b8540c3f75cbd4f556441f3e570c2259e23d4ae266f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('deb68e1f-896f-4b61-8774-71473c352c8c','news-deb68e1f-896f-4b61-8774-71473c352c8c','«الصحة اللبنانية»: 9 شهداء وعدد من الجرحى بغارات الاحتلال على جنوبي البلاد','الصحه اللبنانيه 9 شهداء وعدد من الجرحي بغارات الاحتلال علي جنوبي البلاد','أعلنت وزارة الصحة اللبنانية، عن 9 شهداء وعدد من الجرحى في غارات إسرائيلية على بلدتي أنصار و دير الزهراني جنوبي البلاد. جاء ذلك بعد غارات شنها جيش الاحتلال على جنوب لبنان ليلا، بزعم أنها رد على خرق خطير للاتفاق من حزب الله بعد أن هاجم قوات الاحتلال بالمنطقة الأمنية.','["أعلنت وزارة الصحة اللبنانية، عن 9 شهداء وعدد من الجرحى في غارات إسرائيلية على بلدتي أنصار و دير الزهراني جنوبي البلاد.","جاء ذلك بعد غارات شنها جيش الاحتلال على جنوب لبنان ليلا، بزعم أنها رد على خرق خطير للاتفاق من حزب الله بعد أن هاجم قوات الاحتلال بالمنطقة الأمنية.","وقال رئيس الوزراء اللبناني نواف سلام ، إن التعامل مع أي بنى عسكرية مسؤولية الدولةحصرا ولا يمنح الاحتلال حق استباحة أراضينا."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/p93mzon9d','https://ajel.sa/international/p93mzon9d','https://ajel.sa/international/p93mzon9d','https://ajel.sa/international/p93mzon9d','فريق التحرير','السعودية','2026-08-15T05:17:00.000Z','Wed, 07 Oct 2026 20:49:58 GMT','2026-08-15T14:17:09.465Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%AC%D9%86%D9%88%D8%A8-%D9%84%D8%A8%D9%86%D8%A7%D9%86-9kI1gk-3.jpg','/api/media/deb68e1f-896f-4b61-8774-71473c352c8c','/api/media/deb68e1f-896f-4b61-8774-71473c352c8c?variant=thumbnail','«الصحة اللبنانية»: 9 شهداء وعدد من الجرحى بغارات الاحتلال على جنوبي البلاد',1200,675,'valid','published','archived','valid',47,'69ea2fa4d4dbad1e6245c2ca14837ef39b602d6d690ffd2a50e33c94c99bf093','5ee9775006ec1c9d2e5c4a2aa542bdbcd4f5a8fefaf8df38db70ac2eac577c5e',NULL,'2026-08-15T14:17:09.465Z','2026-10-07T20:50:02.130Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الصحة اللبنانية عن","رئيس الوزراء اللبناني نواف سلام","الصحة العامة","لبنان"]','["وزارة الصحة اللبنانية عن","رئيس الوزراء اللبناني نواف سلام","الصحة العامة"]','manual_approved','below_category_threshold','[{"category":"الصحة","score":4},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T20:50:02.130Z',200,87,0,'source_content_changed','',NULL,NULL,'body:70f9f3e1c40be78379a1d36b781f6ecc14040a41864bea077bb391d18728fe85','Wed, 07 Oct 2026 20:49:58 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('123a4e84-7168-4ebb-80b7-7c790aa3c5e3','news-123a4e84-7168-4ebb-80b7-7c790aa3c5e3','«المنافذ الجمركية»: تسجيل 1260 حالة ضبط للممنوعات خلال أسبوع','المنافذ الجمركيه تسجيل 1260 حاله ضبط للممنوعات خلال اسبوع','أعلنت المنافذ الجمركية البرية والبحرية والجوية، تسجيل 1260 حالة ضبط للممنوعات، وذلك في إطار الجهود المستمرة التي تبذلها هيئة الزكاة والضريبة والجمارك «زاتكا»؛ لتعزيز الجانب الأمني وحماية المجتمع من الممنوعات بمختلف أنواعها وأشكالها.','["وشملت الأصناف المضبوطة 72 صنفًا من المواد المخدرة، مثل: الحشيش، والكوكايين، والهيروين، والشبو، وحبوب الكبتاجون وغيرها، إضافةً إلى 410 صنفًا من المواد المحظورة.","كما شهدت المنافذ الجمركية إحباط 928 من التبغ ومشتقاته، إلى جانب 26 صنفًا لمبالغ مالية، و4 أصناف لأسلحة ومستلزماتها.","وأكدت \"زاتكا\" أنها ماضية في إحكام الرقابة الجمركية على واردات المملكة وصادراتها؛ تحقيقًا لأمن المجتمع وحمايته، وذلك بالتعاون والتنسيق المتواصل مع جميع شركائها من الجهات ذات العلاقة."]','أخبار السعودية','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/9lsdjn843','https://ajel.sa/local/9lsdjn843','https://ajel.sa/local/9lsdjn843','https://ajel.sa/local/9lsdjn843','فريق التحرير','السعودية','2026-08-15T05:18:00.000Z','Wed, 07 Oct 2026 20:45:00 GMT','2026-08-15T14:17:09.676Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%AA%D9%87%D8%B1%D9%8A%D8%A8-ImbwFXwG.jpg','/api/media/123a4e84-7168-4ebb-80b7-7c790aa3c5e3','/api/media/123a4e84-7168-4ebb-80b7-7c790aa3c5e3?variant=thumbnail','«المنافذ الجمركية»: تسجيل 1260 حالة ضبط للممنوعات خلال أسبوع',1200,675,'valid','published','archived','valid',40,'5d9220a851cfec790af68664c58e2245b6fc48119189762f4417d5bf75beddd4','50c2e11adbf4046deb6fa4bd8d0310c6e1b60d5fde4d8c949e1a7dda2d8461a6',NULL,'2026-08-15T14:17:09.676Z','2026-10-07T20:45:02.371Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد"]','[]','manual_approved','below_category_threshold','[{"category":"الاقتصاد","score":1.5},{"category":"المجتمع","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:45:02.371Z',200,82,0,'source_content_changed','',NULL,NULL,'body:18bf65ab4edcfd084db6b054a08edd86ad1c5326acf3eb00465ba072682cabf0','Wed, 07 Oct 2026 20:45:00 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('780c9d63-4a19-471f-bed2-816169e7ede2','news-780c9d63-4a19-471f-bed2-816169e7ede2','إرادة التوحد بنجران تطلق أكثر من 400 جلسة علاج سلوكي','اراده التوحد بنجران تطلق اكثر من 400 جلسه علاج سلوكي','ويستهدف البرنامج تقديم أكثر من 400 جلسة علاجية في مجال تعديل السلوك، تُنفَّذ وفق أسس علمية وخطط علاجية فردية تتناسب مع احتياجات كل مستفيد، بما يسهم في تنمية المهارات السلوكية والاجتماعية والتواصلية، وتحسين جودة الحياة للأشخاص ذوي اضطراب طيف التوحد وأسرهم.','["أطلقت جمعية إرادة التوحد بمنطقة نجران برنامج جلسات العلاج السلوكي «تعديل السلوك» للمستفيدين من ذوي اضطراب طيف التوحد، بدعم من أرامكو السعودية عبر منصة إحسان للعمل الخيري، في إطار شراكة مجتمعية تهدف إلى تعزيز جودة الخدمات المقدمة وتمكين المستفيدين من الوصول إلى برامج تأهيلية متخصصة.","وأكد المدير التنفيذي للجمعية الأستاذ منصور سمران أن هذا الدعم يمثل رافدًا مهمًّا لاستمرار البرامج التأهيلية المتخصصة، ويجسّد دور القطاع الخاص في دعم المبادرات الاجتماعية ذات الأثر المستدام، بما ينعكس إيجابًا على المستفيدين وأسرهم.","وثمّن سمران الدعم المقدم من أرامكو السعودية، مؤكدًا أن هذه المبادرة تعزّز من قدرة الجمعية على تقديم خدمات نوعية تحقق رسالتها في تمكين الأشخاص ذوي اضطراب طيف التوحد وتنمية إمكاناتهم، بما يسهم في تحقيق مستهدفات التنمية المجتمعية."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7qbzldz','https://sabq.org/article/7qbzldz','','https://sabq.org/article/7qbzldz','صحيفة سبق','السعودية','2026-08-14T15:05:00.000Z','2026-08-14T18:05:00.000Z','2026-08-15T14:17:10.246Z','https://media.sabq.org/news/2026/08/8d51e7d3-6118-4af9-b617-a36aebabfeab/w1600.webp','/api/media/780c9d63-4a19-471f-bed2-816169e7ede2','/api/media/780c9d63-4a19-471f-bed2-816169e7ede2?variant=thumbnail','إرادة التوحد بنجران تطلق أكثر من 400 جلسة علاج سلوكي',1600,1005,'valid','published','archived','valid',95,'6a1e74dd3d38d034680f3bede1d3c48d699390fcb091738b9a8749f8cfeb30c8','2e75846eeb36edbe23d9ef4d7299938487668af473cbd5ea21a0fbb307b92589','محدّث','2026-08-15T14:17:10.246Z','2026-10-07T20:48:22.546Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","نجران"]','["الصحة العامة"]','manual_approved','','[]','Temporarily Unreachable','2026-10-07T20:48:22.546Z',NULL,80,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3d415ec8-0681-401a-8b58-7128274cb9f4','news-3d415ec8-0681-401a-8b58-7128274cb9f4','القبض على باكستاني لترويجه 1.3 كيلوجراما من الكوكايين المخدر بمنطقة الرياض','القبض علي باكستاني لترويجه 1 3 كيلوجراما من الكوكايين المخدر بمنطقه الرياض','ألقت المديرية العامة لمكافحة المخدرات، القبض على مقيم من الجنسية الباكستانية، بمنطقة الرياض ، لترويجه 1.30 كيلوجراما من مادة الكوكايين المخدر. وقالت "مكافحة المخدرات" عبر حسابها على منصة "إكس"، إنه تم إيقاف المخالف، واتخاذ الإجراءات النظامية بحقه، وإحالته إلى النيابة العامة.','["ألقت المديرية العامة لمكافحة المخدرات، القبض على مقيم من الجنسية الباكستانية، بمنطقة الرياض ، لترويجه 1.30 كيلوجراما من مادة الكوكايين المخدر.","وقالت \"مكافحة المخدرات\" عبر حسابها على منصة \"إكس\"، إنه تم إيقاف المخالف، واتخاذ الإجراءات النظامية بحقه، وإحالته إلى النيابة العامة.","وحثت الجهات الأمنية الجميع على الإبلاغ عن كل ما يتوافر من معلومات لدى المواطنين والمقيمين عن أي نشاطات ذات صلة بتهريب أو ترويج المخدرات، بالاتصال بالأرقام (911) في مناطق مكة المكرمة والرياض و الشرقية و(999) في بقية مناطق المملكة ، ورقم بلاغات المديرية العامة لمكافحة المخدرات (995)، وعبر البريد الإلكتروني [email&#160;protected] ، وستعالج جميع البلاغات بسرية تامة."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/u9gotu7m0','https://ajel.sa/local/u9gotu7m0','https://ajel.sa/local/u9gotu7m0','https://ajel.sa/local/u9gotu7m0','فريق التحرير','السعودية','2026-08-15T05:18:00.000Z','Wed, 07 Oct 2026 20:45:02 GMT','2026-08-15T14:17:10.283Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%85%D8%AE%D8%AF%D8%B1%D8%A7%D8%AA-31h57guX.jpg','/api/media/3d415ec8-0681-401a-8b58-7128274cb9f4','/api/media/3d415ec8-0681-401a-8b58-7128274cb9f4?variant=thumbnail','القبض على باكستاني لترويجه 1.3 كيلوجراما من الكوكايين المخدر بمنطقة الرياض',1200,675,'valid','published','archived','valid',51,'fb1bd1ba0afd8f3e15af1905bac620a038e975faec6bd0c535b0be4c9f1cd01b','00505b3556cebc7082c7d5d3b41ba865a635ffffce10e7560de041c815e68179',NULL,'2026-08-15T14:17:10.283Z','2026-10-07T20:45:03.916Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","الرياض"]','[]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T20:45:03.916Z',200,82,0,'source_article_available','',NULL,NULL,'body:4b73fdb1aa1c62025e26b2253c0cd30ee1b78265967dd628be28e738b9154ea2','Wed, 07 Oct 2026 20:45:02 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('772d1ae9-01fd-4786-8bdc-261a63963a9b','news-772d1ae9-01fd-4786-8bdc-261a63963a9b','الأمين العام لرابطة العالم الإسلامي يلقي خُطبة الجمعة ويؤمُّ المصلّين بالجامع الوطني الكبير في العاصمة النيجيرية','الامين العام لرابطه العالم الاسلامي يلقي خطبه الجمعه ويؤم المصلين بالجامع الوطني الكبير في العاصمه النيجيريه','ألقى معالي الأمين العام لرابطة العالم الإسلامي، رئيس هيئة علماء المسلمين، فضيلة الشيخ الدكتور محمد بن عبدالكريم العيسى، خطبة الجمعة في الجامع الوطني الكبير بالعاصمة النيجيرية أبوجا، وأمَّ جموعًا غفيرة من المصلّين تتقدّمهم القيادات الدينية الإسلامية النيجيرية.','["وتناولت الخطبة معالمَ من \"هداية القرآن الكريم للتي هي أقوم\"، وجملةً من المسائل والوصايا الشرعية المهمّة للمؤمن في دينه ودنياه؛ ومن ذلك الشكر لأنعُم الله، وتعاهُدُ آداب الإسلام التي يميِّزها الثبات وعدم ازدواج المعايير في تطبيقها، وأن يحذر المسلم أن يكون مسيئاً بسلوكه إلى نفسه ودينه.","وأشاد فضيلته في خطبته بالنموذج النيجيري المتميز في قيَمه الدينية والوطنية."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/p1uqtkr','https://sabq.org/article/p1uqtkr','','https://sabq.org/article/p1uqtkr','صحيفة سبق','السعودية','2026-08-14T15:01:00.000Z','2026-08-14T18:02:00.000Z','2026-08-15T14:17:10.305Z','https://media.sabq.org/news/2026/08/024a449f-8c02-4705-b5d6-6d665bc4781d/w1280.webp','/api/media/772d1ae9-01fd-4786-8bdc-261a63963a9b','/api/media/772d1ae9-01fd-4786-8bdc-261a63963a9b?variant=thumbnail','الأمين العام لرابطة العالم الإسلامي يلقي خُطبة الجمعة ويؤمُّ المصلّين بالجامع الوطني الكبير في العاصمة النيجيرية',1280,854,'valid','published','archived','valid',92,'459bc30c1b8c53ef33d340cbe26581c5c8f450f1d0043316436205cde877bec7','a205b1f49a39205ceeefb4751ced8bc0a9af45926b8c155f0b3057033070c550','محدّث','2026-08-15T14:17:10.305Z','2026-10-07T20:49:55.921Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع"]','[]','classified','','[{"category":"العالم","score":3},{"category":"الصحة","score":1.5},{"category":"التقنية","score":1.5}]','Active','2026-10-07T20:49:55.921Z',200,75,0,'source_article_available','',NULL,NULL,'body:0bd41407235b690f1d49181cee3328e4cceaf4837c2d465763cd4ff5cfda12aa','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0199827e-a0e5-42b3-9583-251bc1c9e2ca','news-0199827e-a0e5-42b3-9583-251bc1c9e2ca','بعد رحيله.. مئات التبرعات في حملة «إحسان» لصدقة جارية عن ماجد الحميدان','بعد رحيله مئات التبرعات في حمله احسان لصدقه جاريه عن ماجد الحميدان','وتحمل الحملة الرقم CW-2366339، وتوضح بيانات منصة «إحسان» أنها أُنشئت بواسطة أحد مستخدمي المنصة عبر برنامج الحملات، دون أن تكشف عن اسمه. وأُديت الصلاة عليه الخميس الماضي بعد صلاة العصر في جامع المهيني، قبل أن يُوارى جثمانه الثرى في مقبرة الشمال.','["في مبادرة وفاء للراحل ماجد بن يحيى الحميدان، أُطلقت عبر منصة «إحسان» الوطنية للعمل الخيري حملة تبرعات تحمل اسم «صدقة جارية عن ماجد الحميدان رحمه الله»، بهدف جمع 100 ألف ريال تُخصص لدعم مشاريع رعاية الأيتام في مختلف مناطق المملكة، لتتحول مشاعر الحزن على رحيله إلى أثر خيري ممتد يحمل اسمه.","وتحمل الحملة الرقم CW-2366339، وتوضح بيانات منصة «إحسان» أنها أُنشئت بواسطة أحد مستخدمي المنصة عبر برنامج الحملات، دون أن تكشف عن اسمه.","وخصصت «إحسان» تبرعات الحملة لمجال رعاية الأيتام، للمساهمة في دعم مشاريعهم وتوفير حياة كريمة لهم، بما يعزز الطمأنينة والاستقرار في نفوسهم.","تفاعل واسع وشهدت الحملة تفاعلاً لافتاً منذ إطلاقها؛ إذ أظهرت بياناتها، وقت إعداد هذه السطور، وصول إجمالي التبرعات إلى 34,276 ريالاً، بما يعادل 34% من المبلغ المستهدف البالغ 100 ألف ريال، فيما بلغ عدد عمليات التبرع 443 عملية، في مؤشر على حجم التفاعل مع المبادرة والرغبة في المساهمة بصدقة جارية عن الفقيد."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/op144ar','https://sabq.org/article/op144ar','','https://sabq.org/article/op144ar','ياسر نجدي','السعودية','2026-08-14T14:52:00.000Z','2026-08-14T18:15:00.000Z','2026-08-15T14:17:10.319Z','https://media.sabq.org/news/2026/08/5b4c033c-bc30-4e45-a2ef-7a12107b555f/w1280.webp','/api/media/0199827e-a0e5-42b3-9583-251bc1c9e2ca','/api/media/0199827e-a0e5-42b3-9583-251bc1c9e2ca?variant=thumbnail','بعد رحيله.. مئات التبرعات في حملة «إحسان» لصدقة جارية عن ماجد الحميدان',1280,1404,'valid','published','archived','valid',52,'76af7e532b3d38e27cfc9dc33ee4c5b156deace67a39c431bf5884404f5f000b','b5d45f9ebce064870338c6b4dbfbb042f9c09169a2674ae1bbc8cf1f994061f6','محدّث','2026-08-15T14:17:10.319Z','2026-10-07T20:49:55.397Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','manual_approved','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"السياسة","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T20:49:55.397Z',200,77,0,'source_article_available','',NULL,NULL,'body:d6fd1e098d606702e0edd51c5193ee65246929937fdaab3aef5515f78a71b3fb','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6224e7a7-6b75-4b76-8ce8-50567a8bf71b','news-6224e7a7-6b75-4b76-8ce8-50567a8bf71b','تنفيذ حكم القتل قصاصًا بحق مواطن قتل آخر في الدمام','تنفيذ حكم القتل قصاصا بحق مواطن قتل اخر في الدمام','أوضحت وزارة الداخلية في بيانها أن الجهات الأمنية تمكنت من القبض على الجاني، وبعد استكمال إجراءات التحقيق أُحيل إلى المحكمة المختصة، التي أصدرت بحقه حكمًا بثبوت الجريمة ووجوب القتل قصاصًا.','["نفذت الجهات المختصة في المنطقة الشرقية اليوم السبت 2 ربيع الأول 1448هـ الموافق 15 أغسطس 2026م، حكم القتل قصاصًا بحق شبيب بن عبدالرحمن بن مطلق المقاطي العتيبي، سعودي الجنسية، بعد إدانته بقتل نايف بن حزام بن زيد المقاطي، سعودي الجنسية، بإطلاق النار عليه إثر خلاف بينهما.","وأضاف البيان أن الحكم أصبح نهائيًا بعد استئنافه وتأييده من المحكمة العليا، وصدر أمر ملكي بإنفاذ ما تقرر شرعًا، ليتم تنفيذ حكم القتل قصاصًا بالجاني في الدمام .","أكدت وزارة الداخلية حرص حكومة المملكة على تحقيق الأمن وتنفيذ أحكام الشريعة الإسلامية بحق كل من يعتدي على الآمنين ويسفك الدماء. كما حذرت الوزارة من الإقدام على مثل هذه الجرائم، مشددة على أن العقاب الشرعي سيكون مصير كل من يرتكبها."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/po35ppxy9','https://ajel.sa/local/po35ppxy9','https://ajel.sa/local/po35ppxy9','https://ajel.sa/local/po35ppxy9','فريق التحرير','السعودية','2026-08-15T05:30:00.000Z','Wed, 07 Oct 2026 20:45:04 GMT','2026-08-15T14:17:10.752Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-06/VcwlvthC3YMDvfZf.jpg','/api/media/6224e7a7-6b75-4b76-8ce8-50567a8bf71b','/api/media/6224e7a7-6b75-4b76-8ce8-50567a8bf71b?variant=thumbnail','تنفيذ حكم القتل قصاصًا بحق مواطن قتل آخر في الدمام',1200,675,'valid','published','archived','valid',54,'a39114c17419f92498b692cda7efbcee943b5557e9487daa9bc48f17b9fdf65d','3cfdf93ce049dab38928fb46f1f1b7e40018e296a459224c899c9361a8b82665',NULL,'2026-08-15T14:17:10.752Z','2026-10-07T20:45:05.593Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية حرص حكومة المملكة","الدمام"]','["وزارة الداخلية حرص حكومة المملكة"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":3},{"category":"المجتمع","score":3},{"category":"السياسة","score":1.5}]','Active','2026-10-07T20:45:05.593Z',200,82,0,'source_article_available','',NULL,NULL,'body:6bd4793c9b4843d4e31217a9ea846e4460b793947ad3fdbbc29e67ee410f1f84','Wed, 07 Oct 2026 20:45:04 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5a9fe10f-7140-42e4-bc4e-b1b37686757b','news-5a9fe10f-7140-42e4-bc4e-b1b37686757b','مجلس القيادة اليمني يتوعّد الحوثيين برد قاس على استهداف المدنيين','مجلس القياده اليمني يتوعد الحوثيين برد قاس علي استهداف المدنيين','أكد مصدر مسؤول في مجلس القيادة الرئاسي اليمني أن القوات المسلحة ستتخذ ما يلزم من إجراءات مشروعة لردع مصادر التهديد، بما يحفظ سلامة المدنيين ومصالح الشعب اليمني.','["وشدد المصدر على أن مجلس القيادة الرئاسي سيتعامل مع أي تصعيد من موقع مسؤوليته الدستورية والسيادية في حماية المواطنين والمنشآت الحيوية والمصالح العليا للبلاد، باعتبار ذلك واجباً لا مساومة فيه.","ونوّه المصدر المسؤول بأن تمادي الميليشيات الحوثية في استهداف الأعيان المدنية سيُواجَه برد قاس، مؤكداً أن حماية المدنيين والمنشآت ذات الطابع المدني أولوية لا يمكن التهاون فيها."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/f2xb1f7','https://sabq.org/article/f2xb1f7','','https://sabq.org/article/f2xb1f7','صحيفة سبق','السعودية','2026-08-14T14:42:00.000Z','2026-08-14T17:42:00.000Z','2026-08-15T14:17:10.765Z','https://media.sabq.org/news/2026/08/b5145d03-cae5-4f8a-9e34-c859cc609df5/w1200.webp','/api/media/5a9fe10f-7140-42e4-bc4e-b1b37686757b','/api/media/5a9fe10f-7140-42e4-bc4e-b1b37686757b?variant=thumbnail','مجلس القيادة اليمني يتوعّد الحوثيين برد قاس على استهداف المدنيين',1200,675,'valid','published','archived','valid',46,'d6535d627f3a306f8f416f72e2bdda3d57708897428be54a4d6d8d18e7ff6edd','101c366a7feabae4ab6bdfc0d1f4d2a1641047fc01c1c1aced3629d8960ece8f','محدّث','2026-08-15T14:17:10.765Z','2026-10-07T20:49:55.915Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس القيادة اليمني يتوع د","اليمن"]','["مجلس القيادة اليمني يتوع د"]','manual_approved','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:49:55.915Z',200,76,0,'source_article_available','',NULL,NULL,'body:19febe4fc5a28409346e8c0920d3fa1b22f62088e5238db203996fa040e2fd1c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('010c30ee-6cc4-47a7-ba80-221394fbdf3a','news-010c30ee-6cc4-47a7-ba80-221394fbdf3a','جوزيف عون: انتهاكات الاحتلال جنوبي لبنان رسالة سلبية للمسار التفاوضي','جوزيف عون انتهاكات الاحتلال جنوبي لبنان رساله سلبيه للمسار التفاوضي','وأسفرت الغارات التي شنتها مقاتلات الاحتلال على لبنان، عن استشهاد وإصابة عدد من المدنيين اللبنانيين خلال الساعات الماضية وذلك برغم التزام الدولة اللبنانية بالانخراط في المسار التفاوضي.','["قال الرئيس اللبناني جوزيف عون ، إن الانتهاكات الاحتلال الإسرائيلي جنوبي لبنان تشكل رسالة واضحة للمسار التفاوضي وللجهود الأمريكية.","وأضاف عون، أن الغارات الإسرائيلية تناقض الجهود الأمريكية الرامية لتطبيق اتفاق وقف النار، ورسالة سلبية للمسار التفاوضي.","كما أدان الرئيس اللبناني اعتداءات الاحتلال المستمرة على مناطق الجنوب، ولا سيما على منطقة النبطية ومحيطها، وخروقاتها المتكررة لاتفاق الإطار ولعمل مجموعة التنسيق العسكرية وللقوانين الدولية بحماية المدنيين ما ادى إلى استشهاد عائلة كاملة من بلدة أنصار."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/02z2zlf4n','https://ajel.sa/international/02z2zlf4n','https://ajel.sa/international/02z2zlf4n','https://ajel.sa/international/02z2zlf4n','فريق التحرير','السعودية','2026-08-15T05:20:00.000Z','Wed, 07 Oct 2026 20:45:00 GMT','2026-08-15T14:17:11.068Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/1000196282-crop-hbmADH0i.jpg','/api/media/010c30ee-6cc4-47a7-ba80-221394fbdf3a','/api/media/010c30ee-6cc4-47a7-ba80-221394fbdf3a?variant=thumbnail','جوزيف عون: انتهاكات الاحتلال جنوبي لبنان رسالة سلبية للمسار التفاوضي',1200,675,'valid','published','archived','valid',40,'7126822abc12aa0f385da5311433830785602916a43a3ff842249b779ddb79b7','1cdbe7b0b02809444bcfdd2da2ab91254363bde171d1eb38576b8867e92318f6',NULL,'2026-08-15T14:17:11.068Z','2026-10-07T20:45:02.077Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["لبنان"]','[]','manual_approved','below_category_threshold','[{"category":"التقنية","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:45:02.077Z',200,80,0,'source_article_available','',NULL,NULL,'body:8a9b332bdab02c516e160db54579a8781d4b3b432c31f6752487568b3651e9ba','Wed, 07 Oct 2026 20:45:00 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1dd51e0d-6e9f-40b6-805a-2053d5ce4fcc','news-1dd51e0d-6e9f-40b6-805a-2053d5ce4fcc','الهلال الأحمر يمنح أمانة الباحة شهادة الامتثال للسلامة الإسعافية','الهلال الاحمر يمنح امانه الباحه شهاده الامتثال للسلامه الاسعافيه','منحت هيئة الهلال الأحمر السعودي بمنطقة الباحة أمانة منطقة الباحة شهادة الامتثال للسلامة الإسعافية، بعد استيفائها المعايير والمتطلبات المعتمدة، بما يعزز جاهزية منشآت الأمانة للتعامل مع الحالات الطارئة، ويسهم في توفير بيئة أكثر أمانًا للعاملين والمستفيدين والزوار.','["وشمل جانب التأهيل تقديم دورة «الثمان الأولى» لمنسوبي الأمانة، والتي تهدف إلى رفع جاهزية الأفراد للتعامل مع الحالات الطارئة خلال الدقائق الثمان الأولى قبل وصول الفرق الإسعافية، لما تمثله هذه الفترة من أهمية في سرعة الاستجابة، ورفع فرص النجاة، والحد من المضاعفات.","وتضمّنت الدورة التدريب على عدد من المهارات الإسعافية الأساسية، ومنها استخدام جهاز الصدمات القلبية الآلي، والتعامل الأولي مع مختلف الحالات الطارئة حتى وصول الفرق المختصة.","وأكّدت هيئة الهلال الأحمر السعودي أن منح الشهادة يأتي ضمن جهودها لتعزيز معايير السلامة الإسعافية ورفع جاهزية المنشآت والمواقع الحيوية، مثمنة تعاون أمانة منطقة الباحة وحرصها على تطبيق متطلبات السلامة بما يسهم في حماية العاملين والمستفيدين والزوار."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/LK1MKb2','https://sabq.org/article/LK1MKb2','','https://sabq.org/article/LK1MKb2','أحمد العبدالله','السعودية','2026-08-14T14:50:00.000Z','2026-08-14T17:50:00.000Z','2026-08-15T14:17:11.077Z','https://media.sabq.org/news/2026/08/02d8a3f9-ace6-4528-b99e-d731d8b11c48/w1280.webp','/api/media/1dd51e0d-6e9f-40b6-805a-2053d5ce4fcc','/api/media/1dd51e0d-6e9f-40b6-805a-2053d5ce4fcc?variant=thumbnail','الهلال الأحمر يمنح أمانة الباحة شهادة الامتثال للسلامة الإسعافية',1280,852,'valid','published','archived','valid',56,'9550a6a9f47356bd7c737d2acfabfdb4ae613964a91638919cc1b4a38422864b','f781fabf99032f662f60e83864347c3251838b12ee9d08b9e475edf9933e0833','محدّث','2026-08-15T14:17:11.077Z','2026-10-07T20:49:54.495Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الهلال الأحمر السعودي أن","التعليم والتدريب","الباحة"]','["هيئة الهلال الأحمر السعودي أن","التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"المناطق","score":3},{"category":"الصحة","score":1.5},{"category":"التعليم","score":1.5}]','Active','2026-10-07T20:49:54.495Z',200,75,0,'source_article_available','',NULL,NULL,'body:a094b9916ed349f505cf7510e710eb117396c2486ac4ed144b82193acce7e482','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c0fd3f7c-8494-4844-b326-c8df0b47ab87','news-c0fd3f7c-8494-4844-b326-c8df0b47ab87','منتخب الأخضر تحت 16 عامًا يفتتح معسكره الإعدادي في قطر','منتخب الاخضر تحت 16 عاما يفتتح معسكره الاعدادي في قطر','افتتح المنتخب السعودي تحت 16 عامًا لكرة القدم اليوم الجمعة تدريباته ضمن معسكره الإعدادي في دولة قطر، والمقام حتى الحادي والعشرين من شهر أغسطس الجاري. ويواصل المنتخب السعودي تحت 16 عامًا مساء غدٍ الأربعاء تدريباته ضمن معسكره الإعدادي في قطر.','["وأجرى لاعبو الأخضر حصتهم التدريبية تحت إشراف المدرب البرتغالي تياغو فارينها والجهاز الفني المساعد، حيث طبّق اللاعبون مرانًا لياقيًا، أعقبه مران للاستحواذ على الكرة، تلاه مران تكتيكي.","وتضم قائمة الأخضر للمعسكر 26 لاعبًا، جاءت أسماؤهم على النحو التالي: أحمد صويلح، يوسف بدر الدين، مشاري الشمري، مشاري الشهراني، يوسف موسى، ثامر العتيبي، فواز سفياني، نواف ناجي، حسن الصالح، عبدالرحمن العطاس، نواف البصاص، أحمد المزيعل، إياد القثامي، مروان المولد، أحمد الثقفي، زياد الدوسري، عبدالله الشبيب، ناصر الصقعبي، عبدالعزيز الناهض، خالد السبيعي، يحيى كليبي، حسن اليامي، فاضل السادة، سعد العيد، عبدالملك سفياني، علي…","ويواصل المنتخب السعودي تحت 16 عامًا مساء غدٍ الأربعاء تدريباته ضمن معسكره الإعدادي في قطر."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ahdhaww','https://sabq.org/article/ahdhaww','','https://sabq.org/article/ahdhaww','صحيفة سبق','السعودية','2026-08-14T14:48:00.000Z','2026-08-14T17:48:00.000Z','2026-08-15T14:17:11.094Z','https://media.sabq.org/news/2026/08/d7b3b3d2-407c-4d2a-adc5-b47e71cd8b55/w1280.webp','/api/media/c0fd3f7c-8494-4844-b326-c8df0b47ab87','/api/media/c0fd3f7c-8494-4844-b326-c8df0b47ab87?variant=thumbnail','منتخب الأخضر تحت 16 عامًا يفتتح معسكره الإعدادي في قطر',1280,853,'valid','published','archived','valid',54,'62b89cf32512071590e33792c592d845a32792690be6c829e51d6fd5676e7a84','6c4d5f7a7d969bc09dc872235a61d18d276a25fd5edb5f079f3b7b89a3363b91','محدّث','2026-08-15T14:17:11.094Z','2026-10-07T20:49:18.050Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"التعليم","score":1.5},{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0}]','Temporarily Unreachable','2026-10-07T20:49:18.050Z',NULL,77,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('94d73cac-9276-490a-ae32-cb8ebd7671a6','news-94d73cac-9276-490a-ae32-cb8ebd7671a6','أكاديمية: 4 أسباب لمضاعفة استخدام الذكاء الاصطناعي','اكاديميه 4 اسباب لمضاعفه استخدام الذكاء الاصطناعي','أوضحت الدكتورة رانية أبو العلا، أستاذ مشارك في نظم المعلومات ب جامعة الملك عبد العزيز ، أسباب مضاعفة استخدام الذكاء الاصطناعي. وأضافت، بمداخلة عبر قناة الإخبارية، أن «سهولة الاستخدام وسرعة الوصول إلى المعلومات جعلتا الذكاء الاصطناعي بديلًا عن محركات البحث التقليدية مثل جوجل».','["أوضحت الدكتورة رانية أبو العلا، أستاذ مشارك في نظم المعلومات ب جامعة الملك عبد العزيز ، أسباب مضاعفة استخدام الذكاء الاصطناعي.","وأضافت، بمداخلة عبر قناة الإخبارية، أن «سهولة الاستخدام وسرعة الوصول إلى المعلومات جعلتا الذكاء الاصطناعي بديلًا عن محركات البحث التقليدية مثل جوجل».","وأكملت، أن «ذلك يرتبط أيضا بفضول المستخدمين حيال الذكاء الاصطناعي وفوائده في أي مجال فضلا عن تسريع الوصول ، وكذلك يستخدم كل من الموظف والطالب الذكاء الاصطناعي كل حسب حاجته»."]','الذكاء الاصطناعي','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/1whxrpns0','https://ajel.sa/local/1whxrpns0','https://ajel.sa/local/1whxrpns0','https://ajel.sa/local/1whxrpns0','فريق التحرير','السعودية','2026-08-15T05:28:00.000Z','Wed, 07 Oct 2026 20:45:04 GMT','2026-08-15T14:17:11.356Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-rRScTH8A.png','/api/media/94d73cac-9276-490a-ae32-cb8ebd7671a6','/api/media/94d73cac-9276-490a-ae32-cb8ebd7671a6?variant=thumbnail','أكاديمية: 4 أسباب لمضاعفة استخدام الذكاء الاصطناعي',1200,675,'valid','published','archived','valid',55,'17b7f1e45b31b8daf542507033f3e3f6bd7860d04562047be02906bd7cdf858d','1b63cb3df650f818753a85b268144c33e368ae5a5d667fef775b9112313b6ce4',NULL,'2026-08-15T14:17:11.356Z','2026-10-07T20:45:05.666Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","جامعة الملك عبد العزيز أسباب","التعليم والتدريب"]','["جامعة الملك عبد العزيز أسباب","التعليم والتدريب"]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"التعليم","score":1.5}]','Active','2026-10-07T20:45:05.666Z',200,83,0,'source_article_available','',NULL,NULL,'body:be9897d87d3443b86bedcb0910fdd7d8a6d2a2841fd921d6dd6c32c4219b89f6','Wed, 07 Oct 2026 20:45:04 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4f229e22-b718-4815-8f68-a4809cf2cdba','news-4f229e22-b718-4815-8f68-a4809cf2cdba','حرس الحدود بجازان يقبض على 3 إثيوبيين لتهريبهم 60 كيلوجرامًا من القات المخدر','حرس الحدود بجازان يقبض علي 3 اثيوبيين لتهريبهم 60 كيلوجراما من القات المخدر','ألقت الدوريات البرية لحرس الحدود في قطاع الدائر ب منطقة جازان ، القبض على 3 مخالفين لنظام أمن الحدود من الجنسية الإثيوبية، لتهريبهم 60 كيلوجرامًا من نبات القات المخدر.','["جرى استكمال الإجراءات النظامية الأولية بحقهم، وتسليمهم والمضبوطات لجهة الاختصاص.","وتهيب الجهات الأمنية بالإبلاغ عن كل ما يتوافر من معلومات لدى المواطنين والمقيمين عن أي نشاطات ذات صلة بتهريب أو ترويج المخدرات، وذلك من خلال الاتصال بالأرقام (911) في مناطق مكة المكرمة و الرياض و الشرقية و(999) في بقية مناطق المملكة ، ورقم بلاغات المديرية العامة لمكافحة المخدرات (995)، وعبر البريد الإلكتروني [email&#160;protected] ، وستعالج جميع البلاغات بسرية تامة."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/2rmy0y7ab','https://ajel.sa/local/2rmy0y7ab','https://ajel.sa/local/2rmy0y7ab','https://ajel.sa/local/2rmy0y7ab','فريق التحرير','السعودية','2026-08-15T05:58:00.000Z','Wed, 07 Oct 2026 20:49:52 GMT','2026-08-15T14:17:11.827Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%AD%D8%B1%D8%B3-3-5cn5CfIu.jpg','/api/media/4f229e22-b718-4815-8f68-a4809cf2cdba','/api/media/4f229e22-b718-4815-8f68-a4809cf2cdba?variant=thumbnail','حرس الحدود بجازان يقبض على 3 إثيوبيين لتهريبهم 60 كيلوجرامًا من القات المخدر',1200,675,'valid','published','archived','valid',57,'ee30f0423f8b1e379259a335a3c825197996711a23cbca46227d75978a5a00ae','dd669e9e4a9813e02156b6c6ec05b4a842229b9d8fd853a29966362acd262263',NULL,'2026-08-15T14:17:11.827Z','2026-10-07T20:49:53.955Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","جازان","الرياض"]','[]','manual_approved','below_category_threshold','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5}]','Updated','2026-10-07T20:49:53.955Z',200,87,0,'source_content_changed','',NULL,NULL,'body:85bf1e73c1ae8e0fef967ce18907f43b495b0fa938ca7da328d6ca65e7a3c61d','Wed, 07 Oct 2026 20:49:52 GMT');
