INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('13422f34-1e6f-4e8c-b77d-24a952ca2356','news-13422f34-1e6f-4e8c-b77d-24a952ca2356','آرسنال يفتتح حملة الدفاع عن لقب الدوري الإنجليزي بالفوز على كوفنتري سيتي','ارسنال يفتتح حمله الدفاع عن لقب الدوري الانجليزي بالفوز علي كوفنتري سيتي','واختتم النرويجي مارتن أوديغارد ثلاثية آرسنال بتسجيل الهدف الثالث عند الدقيقة 49. وبهذه النتيجة، حصد آرسنال أول ثلاث نقاط في مستهل حملة الدفاع عن لقبه، فيما بقي رصيد كوفنتري سيتي خاليًا من النقاط بعد الجولة الأولى.','["استهل فريق آرسنال مشواره في الدفاع عن لقب الدوري الإنجليزي الممتاز بتحقيق فوز مستحق على ضيفه كوفنتري سيتي بنتيجة 3-0، في اللقاء الذي جمع الفريقين مساء الجمعة على ملعب \"الإمارات\" بالعاصمة لندن ، ضمن منافسات الجولة الأولى من المسابقة.","وسجل الألماني كاي هافرتز الهدف الأول لآرسنال في الدقيقة 15، قبل أن يعزز الإنجليزي بوكايو ساكا النتيجة بإحراز الهدف الثاني في الدقيقة 23. واختتم النرويجي مارتن أوديغارد ثلاثية آرسنال بتسجيل الهدف الثالث عند الدقيقة 49.","وبهذه النتيجة، حصد آرسنال أول ثلاث نقاط في مستهل حملة الدفاع عن لقبه، فيما بقي رصيد كوفنتري سيتي خاليًا من النقاط بعد الجولة الأولى."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/brvzzg4bk','https://ajel.sa/sports/brvzzg4bk','https://ajel.sa/sports/brvzzg4bk','https://ajel.sa/sports/brvzzg4bk','فريق التحرير','السعودية','2026-08-21T22:25:00.000Z','Wed, 07 Oct 2026 20:08:44 GMT','2026-08-22T07:37:59.662Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-h81kMVAF.png','/api/media/13422f34-1e6f-4e8c-b77d-24a952ca2356','/api/media/13422f34-1e6f-4e8c-b77d-24a952ca2356?variant=thumbnail','آرسنال يفتتح حملة الدفاع عن لقب الدوري الإنجليزي بالفوز على كوفنتري سيتي',1200,675,'valid','published','archived','valid',50,'e10d40cea5262a8545f3aab906dc068f4562fd256ec20cf725263d576e1880a0','ec3ff8aad833eba8b9724694d0cbbcd6152aca6abfcf1e8bfcd4914a2fbf0509',NULL,'2026-08-22T07:37:59.662Z','2026-10-07T20:08:47.294Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الثقافة","score":3},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T20:08:47.294Z',200,93,0,'source_content_changed','',NULL,NULL,'body:680fd2303b9db7b6646cfdb802fec855b12317d89e220f84040676b173868a41','Wed, 07 Oct 2026 20:08:44 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fd3ae992-646e-4682-9b52-1a0deaa0fba2','news-fd3ae992-646e-4682-9b52-1a0deaa0fba2','الرئاسة الفلسطينية:  المسجد الأقصى سيبقى في صدارة القضايا الوطنية والدينية','الرئاسه الفلسطينيه المسجد الاقصي سيبقي في صداره القضايا الوطنيه والدينيه','وأوضحت الرئاسة الفلسطينية، بمناسبة الذكرى الـ57 لجريمة إحراق المسجد الأقصى المبارك، أن القدس الشرقية هي عاصمة دولة فلسطين ، وأن المسجد الأقصى جزء لا يتجزأ من الأرض الفلسطينية المحتلة.','["أكدت الرئاسة الفلسطينية أن المسجد الأقصى سيبقى في صدارة القضايا الوطنية والدينية، معتبرة إياه رمزًا خالدًا للهوية العربية والإسلامية لمدينة القدس .","وشددت الرئاسة على رفض جميع الإجراءات الرامية إلى تغيير هوية المدينة أو فرض أمر واقع جديد على مقدساتها، معتبرة هذه الإجراءات مرفوضة وغير شرعية.","وفي السياق ذاته، أكدت الرئاسة الفلسطينية قدسية المسجد الأقصى بوصفه مكان عبادة خالصًا للمسلمين، وضرورة صون حرمته والحفاظ على الوضع التاريخي والقانوني القائم فيه."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/u1msrrhf0','https://ajel.sa/international/u1msrrhf0','https://ajel.sa/international/u1msrrhf0','https://ajel.sa/international/u1msrrhf0','فريق التحرير','السعودية','2026-08-21T22:30:00.000Z','Mon, 07 Sep 2026 05:35:21 GMT','2026-08-22T07:37:59.954Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-crop-7kJVSeOX.png','/api/media/fd3ae992-646e-4682-9b52-1a0deaa0fba2','/api/media/fd3ae992-646e-4682-9b52-1a0deaa0fba2?variant=thumbnail','الرئاسة الفلسطينية: المسجد الأقصى سيبقى في صدارة القضايا الوطنية والدينية',1200,675,'valid','published','archived','valid',40,'7ac511327a24f557b6c125afcd174e267db210f76712157da0fa9800b0d89d0b','b218b2092d852f5d2f48829e1391a5dc0394c379a3fc6fa8cbb21b3e12ec27f6',NULL,'2026-08-22T07:37:59.954Z','2026-10-07T20:24:29.790Z','','',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["فلسطين"]','[]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Temporarily Unreachable','2026-10-07T20:07:56.461Z',NULL,91,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ab5cff24-42b8-4b08-b141-314b969610a2','news-ab5cff24-42b8-4b08-b141-314b969610a2','الأهلي يعلن رسميا انتقال ماتيو دامس إلى كلوب بروج البلجيكي','الاهلي يعلن رسميا انتقال ماتيو دامس الي كلوب بروج البلجيكي','أعلن النادي الأهلي رحيل مدافعه، ماتيو دامس، إلى نادي كلوب بروج البلجيكي، خلال فترة الانتقالات الصيفية الحالية. وقدم الأهلي الشكر إلى اللاعب على الفترة التي قضاها مع الفريق، متمنيا له التوفيق في خطوته المقبلة مع النادي البلجيكي.','["أعلن النادي الأهلي رحيل مدافعه، ماتيو دامس، إلى نادي كلوب بروج البلجيكي، خلال فترة الانتقالات الصيفية الحالية.","وشارك دامس مع الفريق خلال الفترة الماضية في عدد من المنافسات المحلية والقارية، وكان ضمن قائمة الفريق التي توجت بلقب دوري أبطال آسيا للنخبة لموسم 2025-2026، إلى جانب كأس السوبر السعودي 2025.","وقدم الأهلي الشكر إلى اللاعب على الفترة التي قضاها مع الفريق، متمنيا له التوفيق في خطوته المقبلة مع النادي البلجيكي."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/ow573t5e2','https://ajel.sa/sports/ow573t5e2','https://ajel.sa/sports/ow573t5e2','https://ajel.sa/sports/ow573t5e2','فريق التحرير','السعودية','2026-08-22T03:27:00.000Z','Wed, 07 Oct 2026 20:02:46 GMT','2026-08-22T09:38:40.300Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%AF%D8%A7%D9%85%D8%B3-Is2HQN-L.jpg','/api/media/ab5cff24-42b8-4b08-b141-314b969610a2','/api/media/ab5cff24-42b8-4b08-b141-314b969610a2?variant=thumbnail','الأهلي يعلن رسميا انتقال ماتيو دامس إلى كلوب بروج البلجيكي',1200,675,'valid','published','archived','valid',58,'4f6e81ad6b4491a324f46f91f5cd4df334008ef8d3bb904ff8fba34e19227e9d','88f1656d5b2deafbcde21529a82859c0d6ce7669b5b3ff40d6c7f770de5442d2',NULL,'2026-08-22T09:38:40.300Z','2026-10-07T20:02:48.319Z','','',0,0,'saudi_region','عادي',42,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Updated','2026-10-07T20:02:48.319Z',200,72,0,'source_content_changed','',NULL,NULL,'body:ebc65d22ad7e24fb0d455838bfd3f35961ef008c435a124f94d853f90f103cf5','Wed, 07 Oct 2026 20:02:46 GMT');
