INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('347ed0d3-2547-4449-9286-b9fc206ae2d8','news-347ed0d3-2547-4449-9286-b9fc206ae2d8','الذهب يرتد صعوداً 0.5% بعد خسائر أمس وسط ترقب تصريحات الاحتياطي الفيدرالي','الذهب يرتد صعودا 0 5 بعد خسائر امس وسط ترقب تصريحات الاحتياطي الفيدرالي','ارتفعت أسعار الذهب اليوم بنسبة 0.5% في المعاملات الفورية لتبلغ 4615.27 دولاراً للأوقية، مستعيدةً جزءاً من خسائرها التي تجاوزت 1% في الجلسة السابقة، وسط ترقب الأسواق لتصريحات رئيس مجلس الاحتياطي الفيدرالي الأمريكي كيفن وورش المرتقبة هذا الأسبوع.','["وارتفعت العقود الأمريكية الآجلة للذهب بدورها بنسبة 0.4% لتستقر عند 4669.50 دولاراً للأوقية.","وعلى صعيد المعادن النفيسة الأخرى، صعدت الفضة في المعاملات الفورية بنسبة 1% لتبلغ 68.77 دولاراً للأوقية، فيما ارتفع البلاتين بنسبة 0.7% إلى 1842.88 دولاراً، وزاد البلاديوم بنسبة 0.3% ليصل إلى 1332.34 دولاراً للأوقية."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/VC5jNCv','https://sabq.org/article/VC5jNCv','','https://sabq.org/article/VC5jNCv','صحيفة سبق','','2026-08-26T23:47:00.000Z','2026-08-27T02:47:00.000Z','2026-08-27T05:55:04.307Z','https://media.sabq.org/news/2026/08/1fa4efb6-3b77-4a8d-9240-bb30aa94017a/w678.webp','/api/media/347ed0d3-2547-4449-9286-b9fc206ae2d8','/api/media/347ed0d3-2547-4449-9286-b9fc206ae2d8?variant=thumbnail','الذهب يرتد صعوداً 0.5% بعد خسائر أمس وسط ترقب تصريحات الاحتياطي الفيدرالي',678,452,'valid','published','archived','valid',52,'c4c2e50f9dcbca51c05f2184b0bee10ff5ad70793f3a329374820cf231bf1fed','890d45e4453f185c31a15e17d09f3433899394b3be78095e941fc724ebc0354e','محدّث','2026-08-27T05:55:04.307Z','2026-10-07T19:13:38.153Z','','',0,0,'international','عادي',43,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Temporarily Unreachable','2026-10-07T19:13:38.153Z',NULL,80,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1f0b2f8d-2810-4ebf-ad0f-482b7d40c930','news-1f0b2f8d-2810-4ebf-ad0f-482b7d40c930','جامعة الملك سعود تستضيف «هيلثون 2026» بجوائز تتجاوز مليون ريال لدعم الابتكار الصحي الرقمي','جامعه الملك سعود تستضيف هيلثون 2026 بجوائز تتجاوز مليون ريال لدعم الابتكار الصحي الرقمي','تستعد جامعة الملك سعود لاستضافة «هيلثون 2026»، هاكاثون الابتكار الصحي الرقمي، خلال الفترة من 1 إلى 4 أكتوبر 2026م، في البهو الرئيسي بالجامعة، بمشاركة المبتكرين والمهتمين بتطوير حلول تقنية تسهم في صناعة مستقبل الرعاية الصحية.','["ويأتي «هيلثون 2026» بجوائز مالية تتجاوز مليون ريال، بهدف تحفيز أصحاب الأفكار والمشاريع الواعدة، ودعم تحويل الابتكارات الصحية إلى حلول قابلة للتطوير والتطبيق، بما يعزز دور التقنية في مواجهة التحديات التي يشهدها القطاع الصحي.","وتبلغ جوائز المراكز الثلاثة الأولى 150 ألف ريال، بواقع 70 ألف ريال للمركز الأول، و50 ألف ريال للمركز الثاني، و30 ألف ريال للمركز الثالث، إلى جانب جوائز تشجيعية للمشاركين وسحب على جوائز قيمة للحضور.","وتتجاوز فرص المشاركين في الهيلثون الجانب المالي، إذ تتيح الفعالية للفرق المتميزة الاستفادة من جلسات إرشاد مع خبراء ومتخصصين، إلى جانب فرص الاحتضان والتسريع للمشاريع المتميزة، ودعم تطوير الحلول، مع إمكانية الوصول إلى مسار لتجربة وتطبيق الحلول داخل بيئة صحية حقيقية.","ويهدف «هيلثون 2026» إلى توفير منصة تجمع المبتكرين وأصحاب الأفكار والخبرات المتخصصة للعمل على تحديات صحية واقعية، وتطوير حلول رقمية مبتكرة يمكن أن تسهم في تحسين جودة الخدمات الصحية وتعزيز كفاءة القطاع."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/Wj6LqLX','https://sabq.org/article/Wj6LqLX','','https://sabq.org/article/Wj6LqLX','عبدالحكيم شار','المنطقة الشرقية','2026-08-26T23:54:00.000Z','2026-08-27T02:55:00.000Z','2026-08-27T06:01:04.469Z','https://media.sabq.org/news/2026/08/4756e4f5-19d0-43cb-b929-0983a218e46d/w1024.webp','/api/media/1f0b2f8d-2810-4ebf-ad0f-482b7d40c930','/api/media/1f0b2f8d-2810-4ebf-ad0f-482b7d40c930?variant=thumbnail','جامعة الملك سعود تستضيف «هيلثون 2026» بجوائز تتجاوز مليون ريال لدعم الابتكار الصحي الرقمي',1024,1280,'valid','published','archived','valid',63,'f5b188e16bd3b676130625337461c9fff77290df9a5f7c8ab409dc24c1306e3b','d915534e4448caeca060668b5a49bd9c1a4c994620a5ae315fc1ded9dea2eadb','محدّث','2026-08-27T06:01:04.469Z','2026-10-07T19:15:38.889Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["المنطقة الشرقية","جامعة الملك سعود تستضيف هيلثون","التعليم والتدريب","التقنية والتحول الرقمي"]','["المنطقة الشرقية","جامعة الملك سعود تستضيف هيلثون","التعليم والتدريب","التقنية والتحول الرقمي"]','needs_review','ambiguous_category','[{"category":"التقنية","score":8},{"category":"الاقتصاد","score":3},{"category":"الصحة","score":1.5}]','Temporarily Unreachable','2026-10-07T19:15:38.889Z',NULL,81,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8159452f-62a4-4c21-b202-866df572a1b2','news-8159452f-62a4-4c21-b202-866df572a1b2','الصين.. وفاة 3 وفقدان 558 إثر انهيار طيني ضخم عند الحدود مع نيبال','الصين وفاه 3 وفقدان 558 اثر انهيار طيني ضخم عند الحدود مع نيبال','أعلنت السلطات الصينية، اليوم، وفاة 3 أشخاص وفقدان 558 آخرين، إثر انهيار طيني ضخم ضرب ميناءً حدوديًا يربط بين الصين ونيبال في منطقة "شيتسانغ" ذاتية الحكم، جنوب غرب الصين.','["ووقع الانهيار الطيني -الذي انطلق من الجانب النيبالي- في ميناء \"قييرونغ\" التابع لمحافظة قييرونغ بمدينة \"شيغاتسه\" صباح أمس.","وأطلقت السلطات الصينية، اليوم، عمليات إنقاذ واسعة النطاق، وقامت بتفعيل استجابة طوارئ من المستوى الثاني للكوارث البيولوجية، وأرسلت فريق عمل إلى الموقع المنكوب لتوجيه عمليات الإنقاذ والوقاية من الكوارث الثانوية.","وأدت الكارثة إلى قطع الطرق المؤدية إلى الميناء على الجانب الصيني، وكذلك الاتصالات وإمدادات الطاقة، وذلك وفقًا لمكتب إدارة الطوارئ في محافظة قييرونغ في مدينة شيغاتسه.","ومن جهتها، أفادت السلطات النيبالية، صباح اليوم، بوفاة 162 شخصًا على الأقل بعدما اجتاحت فيضانات هائلة منطقة حدودية بين نيبال والصين، وفقدان مئات السياح والعمال وغيرهم، وتعليق السفر في بعض المناطق."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/0jswf2d','https://sabq.org/article/0jswf2d','','https://sabq.org/article/0jswf2d','صحيفة سبق','','2026-08-27T00:36:00.000Z','2026-08-27T03:37:00.000Z','2026-08-27T06:46:05.032Z','https://media.sabq.org/news/2026/08/3c482827-e2be-401a-ba0f-c8055757c7a7/w1600.webp','/api/media/8159452f-62a4-4c21-b202-866df572a1b2','/api/media/8159452f-62a4-4c21-b202-866df572a1b2?variant=thumbnail','الصين.. وفاة 3 وفقدان 558 إثر انهيار طيني ضخم عند الحدود مع نيبال',1600,900,'valid','published','archived','valid',49,'3a58d63896d533d59c2bf07406734b17f9b195804740e90c1c17d0db7fb5f3fa','29182f34ce5d1924e243a9a5ab03de2445c8c49d99f1b984f70d4eecb96cd346','محدّث','2026-08-27T06:46:05.032Z','2026-10-07T19:33:50.925Z','','',0,0,'international','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","السفر والسياحة","الصين"]','["الطاقة والنفط","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":4},{"category":"العالم","score":3},{"category":"السفر","score":1.5}]','Active','2026-10-07T19:33:50.925Z',200,71,0,'source_article_available','',NULL,NULL,'body:0784e6a4ca460b7849a3ceaeac94efb981c4fbb9549895dcb158681314f56a68','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('06e837ed-295a-4c76-9ad6-52b7ada21a0b','news-06e837ed-295a-4c76-9ad6-52b7ada21a0b','رويترز: 6 عواقب بعد 6 أشهر منذ بدء حرب إيران','رويترز 6 عواقب بعد 6 اشهر منذ بدء حرب ايران','وفقا لاستطلاع رأي أجرته رويترز/ إبسوس ، انخفضت نسبة تأييد ترامب من 40 بالمئة إلى 33 بالمئة منذ بدء الصراع إذ أدى ارتفاع أسعار البنزين إلى تقويض وعده الانتخابي لعام 2024 بخفض التكاليف على الأمريكيين.','["ذكرت وكالة رويترز أن الحرب التي وصفها الرئيس دونالد ترامب بأنها \"رحلة قصيرة\"، أصبحت مأزقا ضج به كثيرون ويهدد بتقويض رئاسته.","وأوضحت الوكالة أن إيران ، لم تستسلم ولا تزال حركة الملاحة عبر مضيق هرمز تشهد اضطرابات شديدة، ولا يوجد مسار واضح لإنهاء الصراع الذي توقع ترامب ذات يوم أن ينتهي في غضون أربعة أسابيع.","وأشارت إلى وجود 6 عواقب بعد مرور 6 أشهر من إندلاع هذه الحرب، على النحو التالي:"]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/np59o153i','https://ajel.sa/international/np59o153i','https://ajel.sa/international/np59o153i','https://ajel.sa/international/np59o153i','فريق التحرير','','2026-08-27T00:36:00.000Z','Wed, 07 Oct 2026 19:35:38 GMT','2026-08-27T06:52:04.104Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%8A%D8%B1%D8%A7%D9%86-1-0yxTrULU.jpg','/api/media/06e837ed-295a-4c76-9ad6-52b7ada21a0b','/api/media/06e837ed-295a-4c76-9ad6-52b7ada21a0b?variant=thumbnail','رويترز: 6 عواقب بعد 6 أشهر منذ بدء حرب إيران',1200,675,'valid','published','archived','valid',46,'ecb37381f97d7b7c8068f31279d119eab1dca729198f201cbfaeffbd2666288e','9243fa2f2ef5b146ff5588bcbce28bd08d77b21df61fb59e98b0a2ddcb8e8cee','محدّث','2026-08-27T06:52:04.104Z','2026-10-07T20:24:30.914Z','','',0,0,'international','عادي',52,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","إيران"]','[]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"الطاقة والصناعة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T19:35:39.967Z',200,85,0,'source_content_changed','',NULL,NULL,'body:70374bd90b71ce4e53be20e945e5854d38485781ec2a9b49f60c320bcf651e1b','Wed, 07 Oct 2026 19:35:38 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('db18bfa1-f19d-4109-8249-ba5c17b2e915','news-db18bfa1-f19d-4109-8249-ba5c17b2e915','"الماجدية" توقع اتفاقية استراتيجية مع "SOM" العالمية خلال معرض العقارات السعودية الفاخرة بلندن','الماجديه توقع اتفاقيه استراتيجيه مع som العالميه خلال معرض العقارات السعوديه الفاخره بلندن','أعلنت شركة دار الماجد العقارية "الماجدية"، الراعي الماسي لمعرض العقارات السعودية الفاخرة (SLRE)، عن توقيع اتفاقية تعاون استراتيجي مع شركة التصميم المعماري والهندسي العالمية "SOM"، بهدف الاستفادة من الخبرات العالمية في تطوير وتصميم مشاريع عقارية نوعية وفاخرة، وفق معايير متقدمة في التصميم المعماري والابتكار.','["وجرى توقيع الاتفاقية في العاصمة البريطانية لندن، على هامش مشاركة \"الماجدية\" في معرض العقارات السعودية الفاخرة، حيث مثّل الشركة الأستاذ معاذ الخريف، مدير عام قطاع الأعمال التجارية، فيما مثّل \"SOM\" السيد توماس بيهر، الشريك المؤسس.","وتركز الاتفاقية على الجمع بين الخبرات العالمية لشركة \"SOM\" في تصميم عدد من أبرز المعالم المعمارية حول العالم، وفي مقدمتها «برج خليفة»، والرؤية التطويرية لـ\"الماجدية\"، بما يسهم في ابتكار مشاريع فاخرة ذات هوية معمارية مميزة، وتعزيز جودة البيئة العمرانية، ودعم مستهدفات جودة الحياة والتطور الحضري في المملكة العربية السعودية.","وقال الأستاذ معاذ الخريف: \"تأتي هذه الشراكة ضمن توجهاتنا الاستراتيجية لتقديم مشاريع فاخرة ترسي معايير ريادية في السوق السعودي من خلال استقطابنا لأفضل الخبرات الدولية، نترجم رؤيتنا لمفهوم \"حياة ملهمة\" إلى معالم معمارية فريدة، ترفع من كفاءة منتجاتنا وتعزز الجاذبية الاستثمارية لمحفظتنا العقارية المتنامية\".","من جانبه، قال السيد توماس بيهر: \"نعتز بشراكتنا مع الماجدية بوصفها من رواد المشهد العقاري في المملكة العربية السعودية، ونطمح من خلال هذا التعاون إلى تقديم تصاميم مبتكرة ومستدامة تشكل إضافة نوعية للمشهد العمراني، وتواكب التطلعات الطموحة والمتسارعة للقطاع العقاري السعودي\"."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/2yqjnku','https://sabq.org/article/2yqjnku','','https://sabq.org/article/2yqjnku','صحيفة سبق','المنطقة الشرقية','2026-08-27T00:48:00.000Z','2026-08-27T03:49:00.000Z','2026-08-27T06:58:04.888Z','https://media.sabq.org/news/2026/08/1fc5349c-11fa-439b-ba14-d601e96f55a6/w1600.webp','/api/media/db18bfa1-f19d-4109-8249-ba5c17b2e915','/api/media/db18bfa1-f19d-4109-8249-ba5c17b2e915?variant=thumbnail','"الماجدية" توقع اتفاقية استراتيجية مع "SOM" العالمية خلال معرض العقارات السعودية الفاخرة بلندن',1600,900,'valid','published','archived','valid',49,'f7927c551e8a09a9b99e28875f208e9650ab2470ebbad1eef140dc1658a51921','6787ce1ff480c9e3924b0a2bfc414dcaefe7ec45d4a4bd38c3c2abae2282c6a4','محدّث','2026-08-27T06:58:04.888Z','2026-10-07T19:35:36.890Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["المنطقة الشرقية","الاقتصاد والأسواق"]','["المنطقة الشرقية","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"العقارات","score":4.5},{"category":"الاقتصاد","score":4},{"category":"المجتمع","score":4}]','Active','2026-10-07T19:35:36.890Z',200,87,0,'source_article_available','',NULL,NULL,'body:ffeee2fec6564c3355090c23db384309abfea8f51aa46837c060cbd1cec91a3f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f32a4695-7063-4dc2-b9bc-50de1368a5d6','news-f32a4695-7063-4dc2-b9bc-50de1368a5d6','إصابة ثلاث فلسطينيات برصاص الاحتلال في بلدة الكرمل جنوب الخليل','اصابه ثلاث فلسطينيات برصاص الاحتلال في بلده الكرمل جنوب الخليل','أصيبت ثلاث فلسطينيات بينهم طفلة برصاص قوات الاحتلال الإسرائيلي اليوم، في عملية إطلاق نار استهدفت مركبة في بلدة الكرمل جنوب مدينة الخليل بالضفة الغربية، ترافق ذلك مع عمليات دهم وتفتيش واسعة طالت عددًا من منازل البلدة.','["وفي موضوع متصل، استولت قوات الاحتلال على أكثر من 15 دونمًا من أراضي مدينة البيرة؛ بهدف التوسع الاستعماري، وتقييد وصول الفلسطينيين إلى أراضيهم."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/u8wd6mo','https://sabq.org/article/u8wd6mo','','https://sabq.org/article/u8wd6mo','صحيفة سبق','','2026-08-27T00:57:00.000Z','2026-08-27T03:58:00.000Z','2026-08-27T07:05:24.922Z','https://media.sabq.org/news/2026/08/27867983-79ac-49cd-bfad-588666d96281/w1200.webp','/api/media/f32a4695-7063-4dc2-b9bc-50de1368a5d6','/api/media/f32a4695-7063-4dc2-b9bc-50de1368a5d6?variant=thumbnail','إصابة ثلاث فلسطينيات برصاص الاحتلال في بلدة الكرمل جنوب الخليل',1200,800,'valid','published','archived','valid',46,'4937897204bb6588afc8234ee6aa1294a083750a670f1fc5dc36c85236083974','b16eb583e267907772429800594a8b8d7a04314522e7310592171343d816009a','محدّث','2026-08-27T07:05:24.922Z','2026-10-07T19:36:05.628Z','','',0,0,'gulf_arab','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["فلسطين"]','[]','needs_review','below_category_threshold','[{"category":"السيارات","score":1.5},{"category":"العقارات","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T19:36:05.628Z',200,96,0,'source_article_available','',NULL,NULL,'body:0fd92b64d87fc169f332b2f5d7e0fecb6a53146cdd89a29acf6d309e0b215cbf','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2d4e3fbd-0c40-44fa-abb6-ffaad85041d9','news-2d4e3fbd-0c40-44fa-abb6-ffaad85041d9','دول الاتحاد الأوروبي تعيد إحياء خطة استخدام الأصول الروسية المجمدة لصالح أوكرانيا','دول الاتحاد الاوروبي تعيد احياء خطه استخدام الاصول الروسيه المجمده لصالح اوكرانيا','وقد انهارت خطط تمويل أوكرانيا باستخدام أكثر من 200 مليار يورو من أصول البنك المركزي الروسي المحتجزة في الاتحاد الأوروبي بموجب العقوبات، الشتاء الماضي، بعد أن عرقلت بلجيكا هذه المبادرة.','["أفادت صحيفة فاينانشال تايمز ، الخميس، بأن دولا في الاتحاد الأوروبي ، منها السويد ‌و هولندا و إسبانيا و بولندا ، تحث بروكسل ‌على ‌إحياء الجهود الرامية إلى استخدام الأصول السيادية ‌الروسية المجمدة ‌لتمويل أوكرانيا، وذلك استجابةً للمخاوف من مواجهة كييف أزمة تمويل جديدة.","ونقلت الصحيفة عن أربعة مصادر أن ‌رسالة موجهة من تحالف من الدول إلى المفوضية الأوروبية ستدعو السلطة التنفيذية في الاتحاد الأوروبي إلى استئناف العمل على خطط لتمويل أوكرانيا باستخدام أصول البنك ‌المركزي الروسي."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/855yhnqea','https://ajel.sa/international/855yhnqea','https://ajel.sa/international/855yhnqea','https://ajel.sa/international/855yhnqea','فريق التحرير','','2026-08-27T00:46:00.000Z','Wed, 07 Oct 2026 19:41:55 GMT','2026-08-27T07:05:34.182Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%A7%D8%AA%D8%AD%D8%A7%D8%AF-%D8%A7%D9%84%D8%A7%D9%88%D8%B1%D9%88%D8%A8%D9%8A-iAgJ0vjp.jpg','/api/media/2d4e3fbd-0c40-44fa-abb6-ffaad85041d9','/api/media/2d4e3fbd-0c40-44fa-abb6-ffaad85041d9?variant=thumbnail','دول الاتحاد الأوروبي تعيد إحياء خطة استخدام الأصول الروسية المجمدة لصالح أوكرانيا',1200,675,'valid','published','archived','valid',46,'a217e0c0a7953515b9109e45bcbe9577eb0810bc64cebba15378613f0091182b','08d8a872bf0ac38b6939d0a6885210cc38ceddad6d55c527683c55f4db8c868e','محدّث','2026-08-27T07:05:34.182Z','2026-10-07T19:41:57.815Z','','',0,0,'international','عادي',43,NULL,0,0,0,'',NULL,NULL,NULL,'["البنك المركزي الروسي","أوكرانيا"]','["البنك المركزي الروسي"]','needs_review','below_category_threshold','[{"category":"العالم","score":3},{"category":"السياسة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T19:41:57.815Z',200,94,0,'source_content_changed','',NULL,NULL,'body:b37a22586ee3d2066b43d7296b9a149b9e94edff62573691395bda75c8332967','Wed, 07 Oct 2026 19:41:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('57ab652e-49f0-4322-92e9-93bd9bf461c0','news-57ab652e-49f0-4322-92e9-93bd9bf461c0','الحياة .. بين معاناة الماضي ونعيم الحاضر !!','الحياه بين معاناه الماضي ونعيم الحاضر','تعد المقارنة بين الماضي والحاضر رحلة بين عالمين مختلفين تماماً ، عالم كانت البساطة فيه ممزوجة بالقسوة والتعب ، وعالم أصبحت الرفاهية والسرعة فيه عنواناً للحياة اليومية .','["لقد عاش أجدادنا وآباؤنا حياة مليئة بالتحديات التي لا نكاد نتخيلها اليوم ، فقد كانت لقمة العيش تتطلب عرقاً وتعباً متواصلين من الفجر حتى المساء ، إما في زراعة شاقة ، أو رعيٍ تحت شمس حارقة ، أو تجارة مضنية ، كان الحصول على قطرة الماء النقية يتطلب السعي لمسافات طويلة ونقلها على الظهور ، وكانت البيوت بسيطة لا تقي حر الصيف ولا برد الشتاء ، وكانت الأمراض البسيطة تفتك بالمجتمعات لقلة الإمكانيات الإستشفائية وتواضع الرعاية…","أما اليوم فنحن نعيش في وفرة ورغد عيش لم تشهده أجيال سابقة ، فقد أصبحت الخدمات الأساسية التي كانت حلماً في الماضي متوفرة بضغطة زر داخل منازلنا .","ومع هذا التحول الهائل ، يبرز السؤال الأهم هل استشعرنا حجم النعم التي نرفل فيها ؟","إن الشكر ليس مجرد كلمة تتردد على الألسنة ، بل هو حالة إيمانية وسلوك عملي ، والواقع يشير إلى أن اعتياد النعمة أحياناً ينسينا قيمتها ، فنشتكي من أمور بسيطة نراها عيوباً في حياتنا ، بينما كانت أقصى أماني من قبلنا في الحصول على جزء يسير مما نملكه اليوم ."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/md96ldx','https://sabq.org/article/md96ldx','','https://sabq.org/article/md96ldx','صالح مطر الغامدي','الرياض','2026-08-27T01:16:00.000Z','2026-08-27T04:16:00.000Z','2026-08-27T07:25:05.271Z','https://media.sabq.org/news/2026/08/c579ed8d-acf3-407a-a125-23fcb136eebb/w1600.webp','/api/media/57ab652e-49f0-4322-92e9-93bd9bf461c0','/api/media/57ab652e-49f0-4322-92e9-93bd9bf461c0?variant=thumbnail','الحياة .. بين معاناة الماضي ونعيم الحاضر !!',1600,893,'valid','published','archived','valid',49,'0a238b01501de844b62cb7a608a4e85c72beb1f59f0ced06eca17b0b12ba39eb','2e7ad4576dd0a606886e854437982741d89e8530d641a1cc4b7f691a54874e03','محدّث','2026-08-27T07:25:05.271Z','2026-10-07T19:44:56.212Z','','',0,0,'saudi_region','مهم',67,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض","الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":4.5},{"category":"أخبار السعودية","score":4},{"category":"المناطق","score":1.5}]','Active','2026-10-07T19:44:56.212Z',200,74,0,'source_article_available','',NULL,NULL,'body:0070787b338cda419eef2e708a7a73e5d19b4baf5b5c1941f632ebfb158dd421','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9bc44b2c-d0db-4d3a-a793-f86deb9f986c','news-9bc44b2c-d0db-4d3a-a793-f86deb9f986c','الأرصاد يُنبّه من أمطار وسيول وبرد على مكة المكرمة وحائل','الارصاد ينبه من امطار وسيول وبرد علي مكه المكرمه وحائل','أصدر المركز الوطني للأرصاد تنبيهاً جوياً من هطول أمطار متوسطة على العاصمة المقدسة ومحافظة الجموم، تشمل تأثيراتها المصاحبة رياحاً شديدة السرعة، وانعداماً في مدى الرؤية الأفقية، وتساقط البرد، وجريان السيول، وصواعق رعدية.','["وأوضح المركز أن هذه الحالة الجوية ستستمر حتى الساعة الثامنة مساءً.","وفي سياق منفصل، نبَّه المركز ذاته من هطول أمطار خفيفة وصواعق رعدية على منطقة حائل، مصحوبة برياح نشطة وتدنٍّ في مدى الرؤية الأفقية، تشمل عدداً من المحافظات والمناطق المفتوحة والطرق السريعة، على أن تستمر الحالة حتى الساعة السادسة مساءً.","ويُوصي المركز الوطني للأرصاد المواطنين والمقيمين في المناطق المشمولة بالتنبيه بتوخّي الحذر، وتجنّب الأودية ومجاري السيول، والابتعاد عن الأماكن المكشوفة خلال فترة الصواعق الرعدية."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/mk3swy9','https://sabq.org/article/mk3swy9','','https://sabq.org/article/mk3swy9','صحيفة سبق','مكة المكرمة','2026-08-27T01:14:00.000Z','2026-08-27T04:15:00.000Z','2026-08-27T07:25:05.301Z','https://media.sabq.org/news/2026/08/e8126fd2-51ad-43f0-a9c0-d3c045fea595/w1000.webp','/api/media/9bc44b2c-d0db-4d3a-a793-f86deb9f986c','/api/media/9bc44b2c-d0db-4d3a-a793-f86deb9f986c?variant=thumbnail','الأرصاد يُنبّه من أمطار وسيول وبرد على مكة المكرمة وحائل',1000,505,'valid','published','archived','valid',97,'6f27326b111783478691f1e6a6e5d27c2d8196f65619e7bd43abab0038e832a2','38fc5f7b081627aa85e224253ee90fcf29901b7a26d838cbf124b0f62734f100','محدّث','2026-08-27T07:25:05.301Z','2026-10-07T19:45:06.539Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة المكرمة","الطقس والمناخ","مكة"]','["مكة المكرمة","الطقس والمناخ"]','classified','','[{"category":"المناطق","score":7},{"category":"السفر","score":3},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T19:45:06.539Z',200,73,0,'source_article_available','',NULL,NULL,'body:ef42b6ca3e805894210ee70a84f625b7ea617e2c2834ca90e0d75b9b24e44a6c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('684ecaad-9748-4acc-b6cf-70f355e2f4fe','news-684ecaad-9748-4acc-b6cf-70f355e2f4fe','الأرصاد تحذر من موجة حارة تضرب الشرقية.. الحرارة تلامس 48 درجة مئوية في عدة محافظات','الارصاد تحذر من موجه حاره تضرب الشرقيه الحراره تلامس 48 درجه مئويه في عده محافظات','نبَّه المركز الوطني للأرصاد اليوم، من موجة حارة تصل درجتها إلى (47 - 48) درجة مئوية على المنطقة الشرقية، تشمل محافظات: حفر الباطن، والخفجي، والنعيرية، وقرية العليا، والعديد، وذعبلوتن، والأحساء، والهجر والمراكز التابعة لها. وتوقع هطول أمطار خفيفة على بعض محافظات المنطقة الشرقية تشمل الأحساء، والعديد، وذعبلوتن.','["وتوقع هطول أمطار خفيفة على بعض محافظات المنطقة الشرقية تشمل الأحساء، والعديد، وذعبلوتن.","وبيّن المركز أن هذه الحالة ستستمر -بمشيئة الله تعالى- حتى الساعة السادسة مساءً."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/fnl5x99','https://sabq.org/article/fnl5x99','','https://sabq.org/article/fnl5x99','صحيفة سبق','المنطقة الشرقية','2026-08-27T01:31:00.000Z','2026-08-27T04:32:00.000Z','2026-08-27T07:43:05.406Z','https://media.sabq.org/news/2026/08/11028880-9bb0-4582-a5e3-1f1c2c7212cf/w1600.webp','/api/media/684ecaad-9748-4acc-b6cf-70f355e2f4fe','/api/media/684ecaad-9748-4acc-b6cf-70f355e2f4fe?variant=thumbnail','الأرصاد تحذر من موجة حارة تضرب الشرقية.. الحرارة تلامس 48 درجة مئوية في عدة محافظات',1600,900,'valid','published','archived','valid',98,'a8fd9511dd9f47488b7c917bec79b785f7421952c9d809a898903a9180ade755','f5a4127d86c6966db28231c45e13525f7ebba86f75ed9531e14cf07390e5cc1f','محدّث','2026-08-27T07:43:05.406Z','2026-10-07T19:51:21.222Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["المنطقة الشرقية","الطقس والمناخ"]','["المنطقة الشرقية","الطقس والمناخ"]','classified','','[{"category":"السفر","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T19:51:21.222Z',200,73,0,'source_article_available','',NULL,NULL,'body:57aa9898425c41e5a193405e482ae24c5a209ff747259ca7d66ec7d17b1ad8fb','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('17c15c26-3b6f-47f3-8728-6c134bee4abc','news-17c15c26-3b6f-47f3-8728-6c134bee4abc','هيئة الاتصالات: استخدام تطبيقات المكالمات الصوتية والمرئية في المملكة يصل إلى 89.7%','هيئه الاتصالات استخدام تطبيقات المكالمات الصوتيه والمرئيه في المملكه يصل الي 89 7','أظهر تقرير «إنترنت السعودية 2025» الصادر عن هيئة الاتصالات والفضاء والتقنية ، وصول نسبة استخدام تطبيقات المكالمات الصوتية والمرئية في المملكة إلى 89.7%، بما يعكس أنماط تفاعل المستخدمين وتفضيلاتهم في التواصل الرقمي.','["وتصدر تطبيق سناب شات قائمة التطبيقات الأكثر استخدامًا بنسبة 72.4%، يليه فيس تايم بنسبة 17.3%، ثم تيليجرام بنسبة 11.9%، وفيسبوك ماسنجر بنسبة 10.6%، فيما بلغت نسبة استخدام تطبيق لاين 3.6%.","ويستعرض تقرير «إنترنت السعودية 2025» مؤشرات استخدام الإنترنت والتقنيات الرقمية في المملكة، إلى جانب أبرز الاتجاهات وأنماط الاستخدام بين المستفيدين."]','التقنية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/nmh5c6a4r','https://ajel.sa/local/nmh5c6a4r','https://ajel.sa/local/nmh5c6a4r','https://ajel.sa/local/nmh5c6a4r','فريق التحرير','','2026-08-27T01:38:00.000Z','Wed, 07 Oct 2026 19:51:49 GMT','2026-08-27T07:55:04.543Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%87%D9%8A%D8%A6%D8%A9-%D8%A7%D9%84%D8%A7%D8%AA%D8%B5%D8%A7%D9%84%D8%A7%D8%AA--Ojp8NqL.webp','/api/media/17c15c26-3b6f-47f3-8728-6c134bee4abc','/api/media/17c15c26-3b6f-47f3-8728-6c134bee4abc?variant=thumbnail','هيئة الاتصالات: استخدام تطبيقات المكالمات الصوتية والمرئية في المملكة يصل إلى 89.7%',1200,675,'valid','published','archived','valid',99,'487aa95074bc45b273ee670ae80efd37cddbd93c83b86fd8d52de8bd8051e24d','c53f9f725e7623f4b75d2be7b2d08b6fe335a60bff1ed060c8a40a7fbdc5f6e6','محدّث','2026-08-27T07:55:04.543Z','2026-10-07T19:51:50.703Z','','',0,0,'saudi_national','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الاتصالات استخدام تطبيقات المكالمات","التقنية والتحول الرقمي"]','["هيئة الاتصالات استخدام تطبيقات المكالمات","التقنية والتحول الرقمي"]','classified','','[{"category":"أخبار السعودية","score":4.5},{"category":"الصحة","score":3},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T19:51:50.703Z',200,76,0,'source_content_changed','',NULL,NULL,'body:131c08c6110caceea59914ba4c829c16e41ba3d0203bf3fda168decf2deecfa9','Wed, 07 Oct 2026 19:51:49 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('007c830d-8b51-4dc9-a9eb-88f6804d4691','news-007c830d-8b51-4dc9-a9eb-88f6804d4691','أسعار الجنيه المصري والعملات العربية مقابل الريال اليوم الخميس 14-3-1448','اسعار الجنيه المصري والعملات العربيه مقابل الريال اليوم الخميس 14 3 1448','استقرت أسعار العملات العربية مقابل الريال اليوم الخميس 14-3-1448 في البنك المركزي لأغلب العملات؛ حيث استقر سعر الريال مقابل الجنيه المصري والدينار الكويتي والعملات العربية الأخرى. وسجل سعر الريال مقابل الجنيه المصري والعملات العربية الأخرى، اليوم الخميس 14-3-1448 في البنك المركزي، كما يلي:','["وسجل سعر الريال مقابل الجنيه المصري والعملات العربية الأخرى، اليوم الخميس 14-3-1448 في البنك المركزي، كما يلي:","سعر الريال مقابل الدينار الجزائري، 0.028 ريال.","وسجل سعر الريال مقابل العملات العربية الأخرى، في البنك المركزي، اليوم الخميس 14-3-1448، كالآتي:"]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/eqzh7k880','https://ajel.sa/thehour/eqzh7k880','https://ajel.sa/thehour/eqzh7k880','https://ajel.sa/thehour/eqzh7k880','فريق التحرير','','2026-08-27T01:38:00.000Z','Wed, 07 Oct 2026 19:51:50 GMT','2026-08-27T07:55:04.908Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-NAdgADmy.jpg','/api/media/007c830d-8b51-4dc9-a9eb-88f6804d4691','/api/media/007c830d-8b51-4dc9-a9eb-88f6804d4691?variant=thumbnail','أسعار الجنيه المصري والعملات العربية مقابل الريال اليوم الخميس 14-3-1448',1200,675,'valid','published','archived','valid',91,'8c19ec657fb2b1e84532cda4ff1ac677ce15f3a8bf89d2f4599a9e5fded140e2','91316114050cd7285f77a557ab1b43f57904a052c32189c289caef8f849fb669','محدّث','2026-08-27T07:55:04.908Z','2026-10-07T19:51:52.050Z','','',0,0,'gulf_arab','عادي',49,NULL,0,0,0,'',NULL,NULL,NULL,'["البنك المركزي كما يلي سعر"]','["البنك المركزي كما يلي سعر"]','classified','','[{"category":"التقنية","score":6},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T19:51:52.050Z',200,75,0,'source_content_changed','',NULL,NULL,'body:292f3973dcea78a529679c3c712dc7e01fc005c746acfa9b47f445a91dea1ae2','Wed, 07 Oct 2026 19:51:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7d28d74e-a64d-42fd-ad3e-299104a39bcd','news-7d28d74e-a64d-42fd-ad3e-299104a39bcd','«واتساب» يتصدر تطبيقات التواصل في المملكة بنسبة 94.4% بين الذكور','واتساب يتصدر تطبيقات التواصل في المملكه بنسبه 94 4 بين الذكور','كشف تقرير «إنترنت السعودية 2025» الصادر عن هيئة الاتصالات والفضاء والتقنية عن أكثر تطبيقات التواصل الاجتماعي استخداماً في المملكة، مسلطاً الضوء على الفروقات بين المستخدمين والمستخدمات في أنماط التفاعل الرقمي.','["وجاء «واتساب» في صدارة التطبيقات الأكثر استخداماً، بنسبة 94.4% بين الذكور و90.4% بين الإناث، محافظاً على موقعه كأكثر منصات التواصل انتشاراً في المملكة.","وحلّ «سناب شات» في المرتبة الثانية، مسجلاً 88.2% بين الإناث مقابل 80.2% بين الذكور، ما يجعله التطبيق الأكثر استخداماً لدى السعوديات بعد «واتساب».","وسجّل «تيك توك» نسب استخدام متقاربة بين الجنسين، بلغت 77.6% لدى الإناث و76.5% لدى الذكور، فيما جاء «يوتيوب» رابعاً بنسبة 81.1% لدى الذكور مقابل 68.8% لدى الإناث.","أما «إنستغرام» فحلّ خامساً بنسبة 42.4% لدى الإناث و39.5% لدى الذكور."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/tG81duS','https://sabq.org/article/tG81duS','','https://sabq.org/article/tG81duS','صحيفة سبق','','2026-08-27T01:59:00.000Z','2026-08-27T05:00:00.000Z','2026-08-27T08:11:05.284Z','https://media.sabq.org/news/2026/08/c10ad48a-1a42-4948-ad1b-1406bf3a0d21/w960.webp','/api/media/7d28d74e-a64d-42fd-ad3e-299104a39bcd','/api/media/7d28d74e-a64d-42fd-ad3e-299104a39bcd?variant=thumbnail','«واتساب» يتصدر تطبيقات التواصل في المملكة بنسبة 94.4% بين الذكور',960,1200,'valid','published','archived','valid',97,'23655528c201e0be4c9f1f9810a17145baf365945529b7a03d699b896e11a03b','4549605253be3148ba2ad1f899019af4b45a143649253b82c1224b1530af838b','محدّث','2026-08-27T08:11:05.284Z','2026-10-07T19:51:47.255Z','','',0,0,'saudi_national','مهم',69,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية"]','[]','classified','','[{"category":"التعليم","score":5.5},{"category":"أخبار السعودية","score":4.5},{"category":"الصحة","score":3}]','Active','2026-10-07T19:51:47.255Z',200,68,0,'source_article_available','',NULL,NULL,'body:4d09a0de332d7b92ed41b15d5a767c1258bc973d568f0e370f0ff492f34b8a99','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f0471660-c6b6-483c-9b81-352588fb69db','news-f0471660-c6b6-483c-9b81-352588fb69db','رئيس نزاهة يبحث التعاون في مكافحة الفساد مع مسؤول أوروبي','رئيس نزاهه يبحث التعاون في مكافحه الفساد مع مسؤول اوروبي','وبحثا خلال اللقاء سبل التعاون المشترك لدعم الجهود الدولية المعلوماتية بمكافحة الفساد والتحقيقات في الجرائم الخطيرة المرتبطة بالفساد العابرة للحدود، ومناقشة عددٍ من الموضوعات ذات الاهتمام المشترك.','["التقى رئيس هيئة الرقابة ومكافحة الفساد (نزاهة) مازن بن إبراهيم الكهموس، رئيس وكالة الاتحاد الأوروبي للتعاون في مجال العدالة الجنائية (يوروجست) مايكل شميد بمقر الأمم المتحدة بمدينة فيينا .","واطَّلع الجانبان على أهم الإجراءات التي تقوم بها هيئة الرقابة ومكافحة الفساد في مجال حماية النزاهة، وتعزيز مبدأ الشفافية ومكافحة الفساد، إضافة إلى الجهود التي تقوم بها الوكالة في مجال التحقيقات في جرائم الفساد العابرة للحدود في أوروبا وخارجها."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/lsr4c679k','https://ajel.sa/local/lsr4c679k','https://ajel.sa/local/lsr4c679k','https://ajel.sa/local/lsr4c679k','فريق التحرير','','2026-08-27T02:10:00.000Z','Mon, 07 Sep 2026 00:50:48 GMT','2026-08-27T08:29:04.794Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%86%D8%B2%D8%A7%D9%87%D8%A9-agTDEfGJ.jpg','/api/media/f0471660-c6b6-483c-9b81-352588fb69db','/api/media/f0471660-c6b6-483c-9b81-352588fb69db?variant=thumbnail','رئيس نزاهة يبحث التعاون في مكافحة الفساد مع مسؤول أوروبي',1200,675,'valid','published','archived','valid',42,'e812344ff8d9bf22d37b937d15d7fe7f8eb0747a400c90090c5e02c8743c1d7c','9548076b76b30cee2b22f60d20e8e3c4cbc321455152b11560a3d2357fa9db7e','محدّث','2026-08-27T08:29:04.794Z','2026-10-07T19:58:56.291Z','','',0,0,'international','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس نزاهة يبحث التعاون في","الأمم المتحدة بمدينة فيينا واط","هيئة الرقابة ومكافحة الفساد نزاهة","أوروبا"]','["رئيس نزاهة يبحث التعاون في","الأمم المتحدة بمدينة فيينا واط","هيئة الرقابة ومكافحة الفساد نزاهة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"العالم","score":1.5},{"category":"أخبار السعودية","score":0}]','Temporarily Unreachable','2026-10-07T19:58:56.291Z',NULL,98,4,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('abb733ef-4ed7-4fda-8aad-a13fe1e5ef31','news-abb733ef-4ed7-4fda-8aad-a13fe1e5ef31','الاحتلال يعتقل 13 فلسطينيًا في اقتحامات واسعة بالضفة','الاحتلال يعتقل 13 فلسطينيا في اقتحامات واسعه بالضفه','اعتقلت قوات الاحتلال الإسرائيلي، اليوم، 13 فلسطينيًا بينهم أسرى سابقون، خلال عملية اقتحام واسعة لعدة مناطق بالضفة الغربية، تركزت في مدن جنين، وطولكرم، وقلقيلية.','["وفي موضوع متصل، واصل مستعمرون بحماية من قوات الاحتلال توسعة بؤرة استعمارية شرق مدينة بيت ساحور، وذلك في ظل تصاعد اعتداءاتهم على المدن والبلدات الفلسطينية لصالح التوسع الاستعماري."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/fved81t','https://sabq.org/article/fved81t','','https://sabq.org/article/fved81t','صحيفة سبق','','2026-08-27T02:43:00.000Z','2026-08-27T05:44:00.000Z','2026-08-27T08:53:05.576Z','https://media.sabq.org/news/2026/08/c299d9d8-896f-4e7a-bca6-d1e0934a7f1d/w700.webp','/api/media/abb733ef-4ed7-4fda-8aad-a13fe1e5ef31','/api/media/abb733ef-4ed7-4fda-8aad-a13fe1e5ef31?variant=thumbnail','الاحتلال يعتقل 13 فلسطينيًا في اقتحامات واسعة بالضفة',700,425,'valid','published','archived','valid',35,'ef5f4bacfc13b61995100e0a9a169f5ae61de816b05ec98feb9b8c3227ce9df2','96e0dea920b41e43a6db9df4c7f3494e11edefd032f7578a2812d416c0ee2ee6','محدّث','2026-08-27T08:53:05.576Z','2026-10-07T20:00:02.300Z','','',0,0,'gulf_arab','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["فلسطين"]','[]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T20:00:02.300Z',200,76,0,'source_article_available','',NULL,NULL,'body:567d024b1f2a0092b25e3312f9c0f7a07f6bb4435fe002a22f58185faa3ec473','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a7c6d2e4-f858-4a76-a24e-f969c0eaf615','news-a7c6d2e4-f858-4a76-a24e-f969c0eaf615','الهيئة الملكية لمدينة الرياض تطلق «الحي الرقمي» لتصبح العاصمة ضمن أفضل 10 مناطق تقنية عالمياً','الهيئه الملكيه لمدينه الرياض تطلق الحي الرقمي لتصبح العاصمه ضمن افضل 10 مناطق تقنيه عالميا','أعلن مجلس إدارة الهيئة الملكية لمدينة الرياض إطلاق «الحي الرقمي بالرياض»، الذي يُعدّ أحد أبرز مبادراتها الإستراتيجية الرامية إلى جعل العاصمة مركزاً عالمياً للمواهب التقنية والإبداع الرقمي، من خلال استقطاب الكفاءات التقنية العالمية، وتأسيس مركز دولي يجمع بين المواهب وريادة الأعمال، وصولاً إلى بناء اقتصاد معرفي متين يرتكز على القيادة الرقمية والابتكار التقني.','["ويرتكز «الحي الرقمي بالرياض» على استقطاب الشركات والكفاءات التقنية المتخصصة في ستة مجالات أساسية، هي: الذكاء الاصطناعي والبيانات الضخمة، والأمن السيبراني، والحوسبة والخدمات السحابية، وإنترنت الأشياء، وتقنية سلاسل الكتل، والروبوتات والطائرات بدون طيار.","وتستحوذ هذه المجالات الستة على الحصة الأكبر من إجمالي الاستثمارات العالمية في شركات الابتكار التقني، مما يؤكد أهميتها المحورية في دفع عجلة النمو والتطور المستقبلي.","وفي هذا السياق، رفع وزير الدولة عضو مجلس الوزراء الرئيس التنفيذي للهيئة الملكية لمدينة الرياض المهندس إبراهيم بن محمد السلطان الشكر والامتنان لخادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، ولصاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء رئيس مجلس إدارة الهيئة الملكية لمدينة الرياض -حفظهما الله-، لما تجده مشروعات الهيئة من دعم ورعاية كريمين.","وقال السلطان إن «هذه المبادرة النوعية تحفّز لجعل الرياض وجهةً عالميةً للمواهب والشركات التقنية، ولريادة الأعمال الرقمية، وتهدف إلى تصنيف المدينة ضمن أفضل 10 مناطق تقنية في العالم»."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/qPIgQGb','https://sabq.org/article/qPIgQGb','','https://sabq.org/article/qPIgQGb','صحيفة سبق','الرياض','2026-08-27T02:40:00.000Z','2026-08-27T03:18:00.000Z','2026-08-27T11:12:07.878Z','https://media.sabq.org/news/2026/08/9665a16f-8621-4bb0-81b7-719e74b4f11c/w1152.webp','/api/media/a7c6d2e4-f858-4a76-a24e-f969c0eaf615','/api/media/a7c6d2e4-f858-4a76-a24e-f969c0eaf615?variant=thumbnail','الهيئة الملكية لمدينة الرياض تطلق «الحي الرقمي» لتصبح العاصمة ضمن أفضل 10 مناطق تقنية عالمياً',1152,2048,'valid','published','archived','valid',99,'e76087d0af2e182ac61f34935bc60b9626feb5e0b5631f468cc6cbca065475b9','7252bceb99d793143e66b36c22dfda6c5cb0f0e618d2cdd4df0a5be0be466323','محدّث','2026-08-27T08:53:05.800Z','2026-10-07T20:24:30.943Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض","رئيس مجلس الوزراء رئيس مجلس","ولي العهد رئيس مجلس الوزراء","وزير الدولة عضو مجلس الوزراء","مجلس الوزراء الرئيس التنفيذي للهيئة","الاقتصاد والأسواق","التقنية والتحول الرقمي","جدة"]','["رئيس مجلس الوزراء رئيس مجلس","ولي العهد رئيس مجلس الوزراء","وزير الدولة عضو مجلس الوزراء","مجلس الوزراء الرئيس التنفيذي للهيئة","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"التقنية","score":13},{"category":"الاقتصاد","score":5.5},{"category":"المناطق","score":4.5}]','Active','2026-10-07T20:00:03.449Z',200,75,0,'source_article_available','',NULL,NULL,'body:c3374be4c108067b2c44fdbd8b1d64b254ae8f8cfc0d14e9502d20e8fbb0fea3','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8e4fd70a-1bd2-4836-989c-03202e83646f','news-8e4fd70a-1bd2-4836-989c-03202e83646f','صندوق التنمية الزراعية: فوز المملكة بجائزة أممية يؤكد ريادتها في استعادة الأراضي وتنمية الغطاء النباتي','صندوق التنميه الزراعيه فوز المملكه بجائزه امميه يؤكد ريادتها في استعاده الاراضي وتنميه الغطاء النباتي','أكد صندوق التنمية الزراعية أن فوز المملكة بجائزة الأمم المتحدة للنماذج العالمية الرائدة لإصلاح الأراضي يؤكد استمرارها في تحقيق تحولات نوعية في إعادة تأهيل الأراضي وتنمية الغطاء النباتي والحفاظ على النظم البيئية.','["وأوضح الصندوق أن التكريم يعكس الدور الريادي للمملكة في مواجهة التحديات البيئية وتعزيز الاستدامة، ضمن مستهدفات مبادرة السعودية الخضراء، مشيرًا إلى ما تجسده هذه الجهود من توجه وطني نحو حماية البيئة واستعادة الأراضي وتعزيز الغطاء النباتي.","وجاء تعليق الصندوق على تكريم البرنامج الوطني للتشجير بجائزة الأمم المتحدة للنماذج العالمية الرائدة لإصلاح الأراضي، بوصفه نموذجًا عالميًا رائدًا في المجال البيئي."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/otd8mtqij','https://ajel.sa/local/otd8mtqij','https://ajel.sa/local/otd8mtqij','https://ajel.sa/local/otd8mtqij','فريق التحرير','','2026-08-27T02:39:00.000Z','Wed, 07 Oct 2026 20:01:41 GMT','2026-08-27T08:59:05.396Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%B5%D9%86%D8%AF%D9%88%D9%82-%D8%A7%D9%84%D8%AA%D9%86%D9%85%D9%8A%D8%A9-%D8%A7%D9%84%D8%B2%D8%B1%D8%A7%D8%B9%D9%8A%D8%A9-saiLtAJf.jpg','/api/media/8e4fd70a-1bd2-4836-989c-03202e83646f','/api/media/8e4fd70a-1bd2-4836-989c-03202e83646f?variant=thumbnail','صندوق التنمية الزراعية: فوز المملكة بجائزة أممية يؤكد ريادتها في استعادة الأراضي وتنمية الغطاء النباتي',1200,675,'valid','published','archived','valid',53,'5e8940aa887a73396f9c1738000060ed211955f95d5de05317deaa8ba1742541','45196baf6235b86a5ef23f6457ea5fcee790d61d9ad00b3ee63a03c31115ce53','محدّث','2026-08-27T08:59:05.396Z','2026-10-07T20:24:30.947Z','','',0,0,'saudi_national','عادي',52,NULL,0,0,0,'',NULL,NULL,NULL,'["الأمم المتحدة للنماذج العالمية الرائدة"]','["الأمم المتحدة للنماذج العالمية الرائدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":4.5},{"category":"المجتمع","score":3},{"category":"العقارات","score":3}]','Updated','2026-10-07T20:01:43.367Z',200,89,0,'source_content_changed','',NULL,NULL,'body:9e1b16d562ca59ef1003834e31df41e1df32773a91c8108e70649a47d837ce14','Wed, 07 Oct 2026 20:01:41 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fea6ddd9-3f4d-410a-9a35-6b01526aa005','news-fea6ddd9-3f4d-410a-9a35-6b01526aa005','ارتفاع أسعار الذهب في المعاملات الفورية','ارتفاع اسعار الذهب في المعاملات الفوريه','ارتفعت أسعار الذهب اليوم، بعد انخفاضها بأكثر من (1%) في الجلسة السابقة، وسط ترقب الأسواق لتصريحات رئيس مجلس الاحتياطي الفيدرالي الأمريكي كيفن وورش هذا الأسبوع.','["وصعد الذهب في المعاملات الفورية بنسبة (0.5%) إلى (4615.27) دولارًا للأوقية، فيما ارتفعت العقود الأمريكية الآجلة للذهب بنسبة (0.4%) إلى (4669.50) دولارًا.","وفي المعادن النفيسة الأخرى، ارتفعت الفضة في المعاملات الفورية بنسبة (1%) إلى (68.77) دولارًا للأوقية، وزاد البلاتين بنسبة (0.7%) إلى (1842.88) دولارًا، وصعد البلاديوم بنسبة (0.3%) إلى (1332.34) دولارًا."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/75nmrjvgv','https://ajel.sa/economy/75nmrjvgv','https://ajel.sa/economy/75nmrjvgv','https://ajel.sa/economy/75nmrjvgv','فريق التحرير','','2026-08-27T02:39:00.000Z','Wed, 07 Oct 2026 20:00:42 GMT','2026-08-27T08:59:05.714Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%B0%D9%87%D8%A8-3-JBg7qFiD.jpg','/api/media/fea6ddd9-3f4d-410a-9a35-6b01526aa005','/api/media/fea6ddd9-3f4d-410a-9a35-6b01526aa005?variant=thumbnail','ارتفاع أسعار الذهب في المعاملات الفورية',1200,675,'valid','published','archived','valid',58,'1feead940fcd08823f83b63bec51193bb3476cac7c389929588c6bc0460a5091','6cfa9e44d00637590dd00cf1ebc46a2ba65c82a65c0304c7478d4db01362377c','محدّث','2026-08-27T08:59:05.714Z','2026-10-07T20:00:44.349Z','','',0,0,'international','عادي',43,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T20:00:44.349Z',200,76,0,'source_content_changed','',NULL,NULL,'body:8fc83b6fa2edee012bcdc7ab2461aacc72c11259689e922315f0ff41b8c0167e','Wed, 07 Oct 2026 20:00:42 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c4dd47f2-5dbe-4d3a-8084-de1f94dbd5b6','news-c4dd47f2-5dbe-4d3a-8084-de1f94dbd5b6','باكستان: نتابع مع الدول الصديقة جهود الوساطة بين أميركا وإيران','باكستان نتابع مع الدول الصديقه جهود الوساطه بين اميركا وايران','أكدت وزارة الخارجية الباكستانية، أنها تتابع مع الدول الصديقة جهود الوساطة بين أميركا و إيران والثلاثاء الماضي، أعلن الجيش الباكستاني ، أن قائده عاصم منير أجرى محادثات مع إيران ركزت على إجراءات تشمل منع المزيد من تصعيد الصراع وإعادة فتح مضيق هرمز .','["أكدت وزارة الخارجية الباكستانية، أنها تتابع مع الدول الصديقة جهود الوساطة بين أميركا و إيران","وأشارت الوزارة إلى أن الجهود مستمرة لحل الأزمة في الشرق الأوسط ، موضحة ان قائد الجيش عاصم منير ، قد زار طهران ضمن جهود الوساطة، وفق ما نقلت «العربية».","والثلاثاء الماضي، أعلن الجيش الباكستاني ، أن قائده عاصم منير أجرى محادثات مع إيران ركزت على إجراءات تشمل منع المزيد من تصعيد الصراع وإعادة فتح مضيق هرمز ."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/gnl8sygtc','https://ajel.sa/international/gnl8sygtc','https://ajel.sa/international/gnl8sygtc','https://ajel.sa/international/gnl8sygtc','فريق التحرير','','2026-08-27T02:48:00.000Z','Wed, 07 Oct 2026 20:01:43 GMT','2026-08-27T09:05:05.099Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D9%88%D8%B3%D8%A7%D8%B7%D8%A9-iD9NSxLi.jpg','/api/media/c4dd47f2-5dbe-4d3a-8084-de1f94dbd5b6','/api/media/c4dd47f2-5dbe-4d3a-8084-de1f94dbd5b6?variant=thumbnail','باكستان: نتابع مع الدول الصديقة جهود الوساطة بين أميركا وإيران',1200,675,'valid','published','archived','valid',42,'ef7ffaaa6a76a18bec97fb544aa82b544ea9791f74407943e84c938d951381a0','f738f0b6da9021eb32229f589208ea687b56a9d2eb3d0f6e9829d97c23b36f5d','محدّث','2026-08-27T09:05:05.099Z','2026-10-07T20:01:45.146Z','','',0,0,'saudi_national','عادي',61,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الخارجية الباكستانية أنها تتابع","إيران","الشرق الأوسط"]','["وزارة الخارجية الباكستانية أنها تتابع","الشرق الأوسط"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T20:01:45.146Z',200,85,0,'source_content_changed','',NULL,NULL,'body:f9ecda84f4da59495b70101469b5a222716065edf3cd558a14b04d1532069c1f','Wed, 07 Oct 2026 20:01:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4ec4951f-825a-4d1c-b06b-ebe52a065c5d','news-4ec4951f-825a-4d1c-b06b-ebe52a065c5d','مليون وظيفة و150 مليون زائر.. "سوق السفر العالمي بالرياض" يفتح ملف الكفاءات السعودية لما بعد 2030','مليون وظيفه و150 مليون زائر سوق السفر العالمي بالرياض يفتح ملف الكفاءات السعوديه لما بعد 2030','وفي اليوم الأخير من المعرض، يستضيف مسرح المستقبل جلسة متخصصة بعنوان: «حلقة نقاش حول المواهب والقيادة: مليون فرصة عمل في قطاع السياحة – تحقيق رؤية المملكة العربية السعودية السياحية لما بعد عام 2030».','["مع انتقال السياحة السعودية من مرحلة التوسع السريع وبناء الوجهات والمشروعات الكبرى إلى مرحلة التشغيل وتعظيم الأثر الاقتصادي، يضع معرض سوق السفر العالمي – سبوت لايت الرياض 2026 ملف رأس المال البشري والكفاءات الوطنية في صدارة نقاشاته، باعتباره أحد أهم مفاتيح المرحلة المقبلة لتحقيق مستهدفات المملكة السياحية والوصول إلى 150 مليون زائر سنويًا بحلول 2030.","ويقام المعرض في نسخته الافتتاحية خلال الفترة من 8 إلى 10 سبتمبر 2026 في مركز واجهة الرياض للمعارض والمؤتمرات، بمشاركة قيادات من القطاع السياحي والحكومي والأكاديمي ومشروعات كبرى، في منصة تستهدف ربط المملكة بالأسواق السياحية الدولية وجذب فرص الأعمال والشراكات والخبرات العالمية.","وأكد الموقع الرسمي للمعرض أن فعالياته تمتد على مدار ثلاثة أيام من الساعة الواحدة ظهرًا حتى التاسعة مساءً.","التحدي لم يعد خلق الوظائف فقط ويقول إبراهيم أوستا، المدير الأول للنمو الاقتصادي والمسؤول العالمي عن قطاع السياحة في شركة كيمونيكس إنترناشيونال، وأستاذ الإدارة في كلية إدارة الأعمال بجامعة جورج واشنطن، إن المرحلة المقبلة تتطلب الانتقال من مجرد زيادة أعداد الوظائف إلى بناء مسارات مهنية حقيقية تتيح للسعوديين الدخول إلى القطاع واكتساب خبرات متخصصة ثم الوصول إلى المناصب القيادية وتأسيس مشروعاتهم الخاصة."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/40wasnp','https://sabq.org/article/40wasnp','','https://sabq.org/article/40wasnp','خالد خليل','الرياض','2026-08-27T03:02:00.000Z','2026-08-27T06:03:00.000Z','2026-08-27T09:09:24.294Z','https://media.sabq.org/news/2026/08/a2248e4d-e543-47bf-9777-d87d1d270568/w1600.webp','/api/media/4ec4951f-825a-4d1c-b06b-ebe52a065c5d','/api/media/4ec4951f-825a-4d1c-b06b-ebe52a065c5d?variant=thumbnail','مليون وظيفة و150 مليون زائر.. "سوق السفر العالمي بالرياض" يفتح ملف الكفاءات السعودية لما بعد 2030',1600,898,'valid','published','archived','valid',92,'c7cf6b07418f1a19275e62bf54201c06c91918daa943aea20af3031ae1269697','ae93424ff29e3335a5eb12656d0d34b242724f1413b8d36d89125155af3ad184','محدّث','2026-08-27T09:09:24.294Z','2026-10-07T20:00:37.057Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض","شركة كيمونيكس إنترناشيونال وأستاذ الإدارة","السفر والسياحة","التعليم والتدريب","الاقتصاد والأسواق"]','["شركة كيمونيكس إنترناشيونال وأستاذ الإدارة","السفر والسياحة","التعليم والتدريب","الاقتصاد والأسواق"]','classified','','[{"category":"أخبار السعودية","score":6.5},{"category":"الوظائف وسوق العمل","score":6},{"category":"المناطق","score":4.5}]','Active','2026-10-07T20:00:37.057Z',200,87,0,'source_article_available','',NULL,NULL,'body:207e0e0fb665ed57b994be4cd79e0b61d0bf46d53b80a98c28268f8940d0fe5c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c9add24d-80c4-4869-8bbc-430b7fdde82d','news-c9add24d-80c4-4869-8bbc-430b7fdde82d','حرس الحدود بتبوك يضبط مواطنين مارسوا الصيد دون تصريح في ضباء','حرس الحدود بتبوك يضبط مواطنين مارسوا الصيد دون تصريح في ضباء','وأوضح حرس الحدود أن الإبلاغ يكون عبر الاتصال على الرقم 911 في مناطق مكة المكرمة والمدينة المنورة والرياض والمنطقة الشرقية، والرقم 994 في بقية مناطق المملكة، مؤكداً أن جميع البلاغات تُعامَل بسرية تامة دون أدنى مسؤولية على المبلِّغ.','["ضبطت الدوريات الساحلية لحرس الحدود في محافظة ضباء بمنطقة تبوك مواطنين اثنين خالفا لائحة الأمن والسلامة لمزاولي الأنشطة البحرية في المناطق البحرية للمملكة العربية السعودية، وذلك لممارستهما الصيد دون تصريح نظامي، واتُّخذت الإجراءات النظامية بحقهما بالتنسيق مع الجهات المختصة.","وأهاب حرس الحدود بجميع المواطنين والمقيمين الالتزام بالأنظمة والتعليمات المتعلقة بحماية الثروات المائية الحية، والإبلاغ عن أي حالات تمثّل اعتداءً على البيئة أو الحياة الفطرية."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/YeWJ0Ss','https://sabq.org/article/YeWJ0Ss','','https://sabq.org/article/YeWJ0Ss','صحيفة سبق','الرياض','2026-08-27T03:02:00.000Z','2026-08-27T06:02:00.000Z','2026-08-27T09:09:24.461Z','https://media.sabq.org/news/2026/08/5e51b040-d75d-4a3d-a016-c64c0d10c898/w545.webp','/api/media/c9add24d-80c4-4869-8bbc-430b7fdde82d','/api/media/c9add24d-80c4-4869-8bbc-430b7fdde82d?variant=thumbnail','حرس الحدود بتبوك يضبط مواطنين مارسوا الصيد دون تصريح في ضباء',545,366,'valid','published','archived','valid',99,'c43e5bca27dd4631a35de1b9c1e31d3d65193b408445fe1da61e16e2a63b0173','99fd2c0895b36c3e7cc7f68c531859002d1c824ff205afc63d4fa70ad553b522','محدّث','2026-08-27T09:09:24.461Z','2026-10-07T20:00:52.042Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض","التعليم والتدريب","الرياضة السعودية","تبوك"]','["التعليم والتدريب","الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"المجتمع","score":3},{"category":"التقنية","score":2}]','Active','2026-10-07T20:00:52.042Z',200,87,0,'source_article_available','',NULL,NULL,'body:597986563b37443a1047426125fafa27baacb71cdc090f94b13893b8e462b0ff','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8bb3fe5b-7665-4fda-9f6d-6a312c694f05','news-8bb3fe5b-7665-4fda-9f6d-6a312c694f05','الملك سلمان وولي العهد يهنئان رئيسة مولدوفا بذكرى الاستقلال','الملك سلمان وولي العهد يهنئان رئيسه مولدوفا بذكري الاستقلال','بعث خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود برقية تهنئة إلى فخامة السيدة مايا ساندو رئيسة جمهورية مولدوفا، بمناسبة ذكرى يوم الاستقلال لبلادها.','["وأعرب الملك المفدى عن أصدق التهاني وأطيب التمنيات لفخامتها بدوام الصحة والسعادة، ولحكومة جمهورية مولدوفا الصديقة وشعبها اطراد التقدم والازدهار.","وفي السياق ذاته، بعث صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء، برقية تهنئة إلى فخامة السيدة مايا ساندو رئيسة جمهورية مولدوفا، بمناسبة الذكرى ذاتها.","وعبّر سمو ولي العهد عن أطيب التهاني وأصدق التمنيات لفخامتها بموفور الصحة والسعادة، ولحكومة جمهورية مولدوفا الصديقة وشعبها المزيد من التقدم والازدهار."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/podpfit','https://sabq.org/article/podpfit','','https://sabq.org/article/podpfit','صحيفة سبق','','2026-08-27T03:39:00.000Z','2026-08-27T06:40:00.000Z','2026-08-27T09:48:06.305Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/09d5fdb1-d359-4870-ac9a-e934c0552000/public','/api/media/8bb3fe5b-7665-4fda-9f6d-6a312c694f05','/api/media/8bb3fe5b-7665-4fda-9f6d-6a312c694f05?variant=thumbnail','الملك سلمان وولي العهد يهنئان رئيسة مولدوفا بذكرى الاستقلال',922,587,'valid','published','archived','valid',99,'860b6b35ca44168f77191ba6cf2ae27a4d74c0ef714eae6737dfe4a308b550ea','9612948cdb53cb52bc954bf2e99f09b0b4747c1c494a21185c51dd8fc259aa16','محدّث','2026-08-27T09:48:06.306Z','2026-10-07T20:02:52.985Z','','',0,0,'saudi_national','مهم',77,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء برقية تهنئة إلى","رئيس مجلس الوزراء برقية تهنئة","الصحة العامة"]','["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء برقية تهنئة إلى","رئيس مجلس الوزراء برقية تهنئة","الصحة العامة"]','classified','','[{"category":"السياسة","score":1.5},{"category":"المناطق","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T20:02:52.985Z',200,75,0,'source_article_available','',NULL,NULL,'body:74437a4dfdc44ebf726679e0a1c8e64cddfe695359c877f78c4d6a3b01864960','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6d8b1213-59d2-473d-b923-5a7af791238c','news-6d8b1213-59d2-473d-b923-5a7af791238c','وكيل إمارة حائل يشهد احتفال المستشفى السعودي الألماني بمرور 10 أعوام على تأسيسه','وكيل اماره حائل يشهد احتفال المستشفي السعودي الالماني بمرور 10 اعوام علي تاسيسه','وأوضح المسيعيد أن التكامل بين المستشفى السعودي الألماني والقطاع الحكومي والجمعيات الصحية في المنطقة يسهم في تعزيز الخدمات الصحية والوصول إلى شرائح أوسع من المستفيدين.','["شهد وكيل إمارة منطقة حائل ، علي بن سالم آل عامر، نيابة عن صاحب السمو الملكي الأمير عبدالعزيز بن سعد بن عبدالعزيز أمير المنطقة، اليوم الأربعاء، احتفال المستشفى السعودي الألماني في حائل بمناسبة مرور عشرة أعوام على تأسيسه.","وأشاد مدير عام فرع وزارة الصحة بالمنطقة، سلطان المسيعيد، خلال الحفل، بالدعم الذي يحظى به القطاع الصحي الحكومي والخاص من القيادة الرشيدة، والمتابعة المستمرة من سمو أمير منطقة حائل وسمو نائبه ومعالي وزير الصحة.","وفي ختام الحفل، رعى وكيل إمارة حائل مراسم توقيع عدد من الاتفاقيات بين المستشفى وعدد من الجمعيات الصحية في المنطقة، وذلك بهدف تعزيز التعاون وتكامل الجهود في المجالات الصحية والمجتمعية."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/8oiy5x7tw','https://ajel.sa/local/8oiy5x7tw','https://ajel.sa/local/8oiy5x7tw','https://ajel.sa/local/8oiy5x7tw','فريق التحرير','','2026-08-27T03:39:00.000Z','Wed, 07 Oct 2026 20:23:00 GMT','2026-08-27T09:56:05.720Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-08/source-AAHO0gqq.jpg','/api/media/6d8b1213-59d2-473d-b923-5a7af791238c','/api/media/6d8b1213-59d2-473d-b923-5a7af791238c?variant=thumbnail','وكيل إمارة حائل يشهد احتفال المستشفى السعودي الألماني بمرور 10 أعوام على تأسيسه',1200,675,'valid','published','archived','valid',85,'d882ed5b4d12d244f96f8bbb4a4c05b1f49304fcbc997d203b564fe1cdb66566','b8251feae16ed1248cbb843560b698581734ba9b6695bc28f4184e8ef88198d2','محدّث','2026-08-27T09:56:05.720Z','2026-10-07T20:23:02.253Z','','',0,0,'international','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الصحة وفي ختام الحفل","وزارة الصحة بالمنطقة سلطان المسيعيد","الصحة العامة"]','["وزير الصحة وفي ختام الحفل","وزارة الصحة بالمنطقة سلطان المسيعيد","الصحة العامة"]','classified','','[{"category":"المجتمع","score":4.5},{"category":"السيارات","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:23:02.253Z',200,69,0,'source_content_changed','',NULL,NULL,'body:298f3dad19c8f919107aa7be86a48379aed405d363f8c8e79ff76bdc489c4520','Wed, 07 Oct 2026 20:23:00 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('be3efb0f-572c-4ea8-9a98-4383d2182f44','news-be3efb0f-572c-4ea8-9a98-4383d2182f44','أسعار الذهب في السعودية اليوم الخميس 14-3-1448 لكل الأعيرة','اسعار الذهب في السعوديه اليوم الخميس 14 3 1448 لكل الاعيره','تراجعت أسعار الذهب في السعودية اليوم الخميس 14-3-1448 لكل الأعيرة؛ إذ تراجع سعر الذهب عيار 21 وبقية الأعيرة في مستهل التعاملات اليوم، بالتزامن مع استقرار سعر المعدن الأصفر عالميا عقب موجة صعود قوية. وسجل سعر الذهب عيار 21 في المملكة، في مستهل التعاملات اليوم، الخميس 485.52 ريال للجرام، فيما كان يسجل في ختام التعاملات أمس الأربعاء 491.56 ريال.','["تراجعت أسعار الذهب في السعودية اليوم الخميس 14-3-1448 لكل الأعيرة؛ إذ تراجع سعر الذهب عيار 21 وبقية الأعيرة في مستهل التعاملات اليوم، بالتزامن مع استقرار سعر المعدن الأصفر عالميا عقب موجة صعود قوية.","وسجل سعر الذهب في البورصة العالمية اليوم الخميس، نحو 4,595 دولارًا للأوقية.","وسجل سعر الذهب عيار 21 في المملكة، في مستهل التعاملات اليوم، الخميس 485.52 ريال للجرام، فيما كان يسجل في ختام التعاملات أمس الأربعاء 491.56 ريال."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/ef3g6vxnr','https://ajel.sa/thehour/ef3g6vxnr','https://ajel.sa/thehour/ef3g6vxnr','https://ajel.sa/thehour/ef3g6vxnr','فريق التحرير','','2026-08-27T03:42:00.000Z','Wed, 07 Oct 2026 20:17:58 GMT','2026-08-27T09:56:05.734Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%B0%D9%87%D8%A8-YehgHHuJ.jpg','/api/media/be3efb0f-572c-4ea8-9a98-4383d2182f44','/api/media/be3efb0f-572c-4ea8-9a98-4383d2182f44?variant=thumbnail','الذهب',1200,675,'valid','published','archived','valid',98,'f363abe26ed6829a83cb1cd1bbbbdf60e67dbf913bdb31a49c92800e34f30f11','66d086e8a27c988ccc8e62581b17edbb11dd1b97a570ee6a246765bd0258ae0b','محدّث','2026-08-27T09:56:05.734Z','2026-10-07T20:18:00.448Z','','',0,0,'saudi_national','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','classified','','[{"category":"أخبار السعودية","score":4.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"العالم","score":1.5}]','Updated','2026-10-07T20:18:00.448Z',200,89,0,'source_content_changed','',NULL,NULL,'body:7840a9a08cd8a8016e885531dcf40c6efaa1f6a6639f8bf0e716f1ee45ba06d3','Wed, 07 Oct 2026 20:17:58 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('93ea5d57-f161-4a21-82aa-aaefe11d0d69','news-93ea5d57-f161-4a21-82aa-aaefe11d0d69','الحقيل: تبوك بيئة جاذبة للاستثمار.. ومشروعات تنموية بأكثر من 2.3 مليار ريال','الحقيل تبوك بيئه جاذبه للاستثمار ومشروعات تنمويه باكثر من 2 3 مليار ريال','نوّه معالي وزير البلديات والإسكان الأستاذ ماجد بن عبدالله الحقيل بما شهدته منطقة تبوك خلال الأعوام الماضية من تطوير للبنية التحتية التي جعلتها بيئة جاذبة للمستثمرين، ومهيأة لنمو مشروعات القطاع الخاص، مؤكدًا أن المنطقة اليوم تشهد حراكًا تنمويًا ومشروعات نوعية تتماشى بصورة كبيرة مع مستهدفات رؤية السعودية 2030، التي وجّهت بوصلة التنمية نحو استثمار المقومات…','["وقال في تصريح لوكالة الأنباء السعودية -عقب حفل توقيع حزمة من العقود والاتفاقيات والمشروعات التنموية والاستثمارية والإسكانية بالمنطقة بتكلفة تجاوزت المليارين و300 مليون ريال-: \"إن الموقع الجغرافي الإستراتيجي لمنطقة تبوك يعزز من مكانتها بوصفها وجهة جاذبة للاستثمار والتنمية، حيث تحظى وكبقية مناطق المملكة بدعم غير محدود من خادم الحرمين الشريفين, وسمو ولي عهده الأمين -حفظهما الله-، وبمتابعة سمو أمير منطقة تبوك، وسمو…","وأعرب معاليه في ختام تصريحه عن سعادته واعتزازه بما تحقق فيها من منجزات ومشروعات نوعية، وما تشهده من نمو متسارع في مختلف المجالات."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/blbgpck','https://sabq.org/article/blbgpck','','https://sabq.org/article/blbgpck','صحيفة سبق','تبوك','2026-08-27T03:40:00.000Z','2026-08-27T06:41:00.000Z','2026-08-27T09:56:06.307Z','https://media.sabq.org/news/2026/08/3c243215-236d-460c-9098-54790b2edab5/w1600.webp','/api/media/93ea5d57-f161-4a21-82aa-aaefe11d0d69','/api/media/93ea5d57-f161-4a21-82aa-aaefe11d0d69?variant=thumbnail','الحقيل: تبوك بيئة جاذبة للاستثمار.. ومشروعات تنموية بأكثر من 2.3 مليار ريال',1600,1065,'valid','published','archived','valid',96,'f0e938dfcc25f8a01408bb3ce8e6f5abfbe65990568c650f369057bc5077635b','a0f0ac8b9f78b73c6bba36135d31dd2eb7cb31a3eae371ba64b4dd2cac9a4a38','محدّث','2026-08-27T09:56:06.307Z','2026-10-07T20:24:30.969Z','','',0,0,'saudi_region','مهم',67,NULL,0,0,0,'',NULL,NULL,NULL,'["تبوك","خادم الحرمين الشريفين وسمو ولي","الاقتصاد والأسواق"]','["خادم الحرمين الشريفين وسمو ولي","الاقتصاد والأسواق"]','classified','','[{"category":"المجتمع","score":8.5},{"category":"أخبار السعودية","score":7},{"category":"المناطق","score":3}]','Active','2026-10-07T20:08:39.077Z',200,95,0,'source_article_available','',NULL,NULL,'body:c85e172dd5008b98ba9ff4a27c80027efe65dc7862f8149daa363ba7a0b8ce3e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d25e93ab-e8f9-430f-9a70-23b87827c7c8','news-d25e93ab-e8f9-430f-9a70-23b87827c7c8','البديوي: دول الخليج حققت مكانة عالمية متقدمة في الأمن السيبراني وعززت جاهزيتها لمواجهة التهديدات','البديوي دول الخليج حققت مكانه عالميه متقدمه في الامن السيبراني وعززت جاهزيتها لمواجهه التهديدات','وأوضح خلال الاجتماع الخامس للجنة الوزارية للأمن السيبراني في المنامة أن التطورات الأخيرة في المنطقة أظهرت جاهزية عالية للمنظومة السيبرانية الخليجية، مدعومة بالتنسيق المستمر والإجراءات الاستباقية.','["أكَّد معالي الأمين العام لمجلس التعاون لدول الخليج العربية جاسم محمد البديوي، أن دول المجلس حققت مكانة عالمية متقدمة في مجال الأمن السيبراني، بفضل تطوير القدرات الوطنية وحماية البيانات والبنى التحتية الرقمية وتعزيز الاستجابة للتهديدات.","وأشار إلى أبرز منجزات العمل الخليجي المشترك، ومنها الخطة التنفيذية للإستراتيجية الخليجية للأمن السيبراني 2024 - 2028، وإطار التعاون الدولي، وآلية مشاركة معلومات التهديدات، وتنظيم التمارين السيبرانية الخليجية سنويًا."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/o720cum','https://sabq.org/article/o720cum','','https://sabq.org/article/o720cum','صحيفة سبق','','2026-08-27T03:58:00.000Z','2026-08-27T06:59:00.000Z','2026-08-27T10:09:06.349Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/9c9135e6-8d4f-4b09-834d-3e7b3e96b100/public','/api/media/d25e93ab-e8f9-430f-9a70-23b87827c7c8','/api/media/d25e93ab-e8f9-430f-9a70-23b87827c7c8?variant=thumbnail','البديوي: دول الخليج حققت مكانة عالمية متقدمة في الأمن السيبراني وعززت جاهزيتها لمواجهة التهديدات',800,620,'valid','published','archived','valid',53,'b28beecce8967461736d82b3b6f06da2fb50f26fdc4b60e8ef1b40564afae454','8e322867d5b589556f1c342b82672145f8755cabb8364c3728f154da8dd9afdf','محدّث','2026-08-27T10:09:06.349Z','2026-10-07T20:18:05.908Z','','',0,0,'gulf_arab','عادي',49,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي","الخليج العربي"]','["التقنية والتحول الرقمي","الخليج العربي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:18:05.908Z',200,65,0,'source_article_available','',NULL,NULL,'body:198fca5077c84fa1b6c1bda23db81bbc2f1366354a6c4c204f7de44cb5b52ffc','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('58ec5769-c1b4-4278-84b1-f8c626ce68d2','news-58ec5769-c1b4-4278-84b1-f8c626ce68d2','حرس الحدود بجازان يقبض على 6 مخالفين ويضبط 100 كجم من القات','حرس الحدود بجازان يقبض علي 6 مخالفين ويضبط 100 كجم من القات','قبضت الدوريات البرية لحرس الحدود في قطاع الدائر بمنطقة جازان على 6 مخالفين لنظام أمن الحدود من الجنسية الإثيوبية، لتورطهم في تهريب 100 كيلوجرام من نبات القات المخدر.','["وأوضحت المديرية العامة لحرس الحدود أنه جرى استكمال الإجراءات النظامية الأولية بحق المقبوض عليهم، وتسليمهم والمضبوطات لجهة الاختصاص.","ودعت الجهات الأمنية إلى الإبلاغ عن أي عمليات تهريب أو ترويج للمخدرات، من خلال الاتصال على الرقم 911 في مناطق مكة المكرمة والمدينة المنورة والرياض والشرقية، والرقم 999 في بقية مناطق المملكة، أو الرقم 994 لبلاغات حرس الحدود، مؤكدةً أن جميع البلاغات تُعامل بسرية تامة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/nk7mymv','https://sabq.org/article/nk7mymv','','https://sabq.org/article/nk7mymv','صحيفة سبق','الرياض','2026-08-27T03:57:00.000Z','2026-08-27T06:57:00.000Z','2026-08-27T10:09:06.533Z','https://media.sabq.org/news/2026/08/efbaa0d3-782f-4612-9f01-5d31476f93db/w897.webp','/api/media/58ec5769-c1b4-4278-84b1-f8c626ce68d2','/api/media/58ec5769-c1b4-4278-84b1-f8c626ce68d2?variant=thumbnail','حرس الحدود بجازان يقبض على 6 مخالفين ويضبط 100 كجم من القات',897,662,'valid','published','archived','valid',89,'7bb46e556885ade3136cfe2e4e9fd41060771ef20bfd7b91078cd0b8f6d95ac3','f8b6c5c7d5a98cfdda1e8ad03562baeb78a82bfa93232f6a6673b0c552c2e686','محدّث','2026-08-27T10:09:06.533Z','2026-10-07T20:18:04.485Z','','',0,0,'saudi_region','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض","مكة","جازان","المدينة المنورة"]','["المدينة المنورة"]','classified','','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"الرياضة","score":1.5}]','Active','2026-10-07T20:18:04.485Z',200,72,0,'source_article_available','',NULL,NULL,'body:f79316bd6183470fb3ec9a67010410f0b24c459595b360f406ca74d3f790032a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3a678ec0-8e89-46dd-aa17-996672c0e9ec','news-3a678ec0-8e89-46dd-aa17-996672c0e9ec','وثيقة نادرة تكشف بدايات دخول الراديو إلى ينبع قبل نحو 90 عامًا.. شاهد التفاصيل','وثيقه نادره تكشف بدايات دخول الراديو الي ينبع قبل نحو 90 عاما شاهد التفاصيل','تكشف وثيقة تاريخية نادرة جانبًا من بدايات دخول أجهزة الراديو إلى مدينة ينبع، عندما كان اقتناء جهاز استقبال لاسلكي يتطلب الحصول على ترخيص رسمي من الجهات المختصة.','["وتحمل الوثيقة رخصة لجهاز استقبال لاسلكي صدرت بتاريخ 26 جمادى الآخرة 1358هـ للسيد حامد محمود الخطيب، أحد أعيان ينبع آنذاك، رحمه الله.","وتظهر الرخصة أن امتلاك أجهزة الراديو في تلك المرحلة لم يكن متاحًا بمجرد شراء الجهاز، بل كان يستلزم إصدار رخصة رسمية من المديرية العامة للبريد والبرق، في صورة تعكس التنظيم المبكر لاستخدام وسائل الاتصال الحديثة في المملكة.","وتكتسب الوثيقة أهميتها من كونها تقدم شاهدًا تاريخيًا على مرحلة كانت فيها أجهزة الراديو تمثل وسيلة تقنية حديثة ونادرة، قبل أن تتحول لاحقًا إلى أحد أبرز وسائل الإعلام والاتصال داخل البيوت السعودية.","كما تحمل الرخصة دلالة خاصة على بدايات انتشار أجهزة الاستقبال اللاسلكي في ينبع، وعلى ارتباط المجتمع المحلي مبكرًا بالتطورات التقنية والإعلامية التي شهدتها المملكة في تلك المرحلة."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/kqg32mj','https://sabq.org/article/kqg32mj','','https://sabq.org/article/kqg32mj','خالد خليل','المدينة المنورة','2026-08-27T04:10:00.000Z','2026-08-27T07:10:00.000Z','2026-08-27T10:21:06.638Z','https://media.sabq.org/news/2026/08/9dadd4dc-cc79-45a1-92dd-f989cf908963/w510.webp','/api/media/3a678ec0-8e89-46dd-aa17-996672c0e9ec','/api/media/3a678ec0-8e89-46dd-aa17-996672c0e9ec?variant=thumbnail','وثيقة نادرة تكشف بدايات دخول الراديو إلى ينبع قبل نحو 90 عامًا.. شاهد التفاصيل ',510,680,'valid','published','archived','valid',46,'da675c5106e12dcaba70ac63b5c7c6262a6d6e0f54451b40679e2daca8c5acb8','a85bc7cef0e000e22bdaba8c8bb555e76453a76fccd3c12ce7c68fdf84bd2f85','محدّث','2026-08-27T10:21:06.638Z','2026-10-07T20:27:57.392Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["المدينة المنورة","التقنية والتحول الرقمي"]','["المدينة المنورة","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"التقنية","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T20:27:57.392Z',200,79,0,'source_article_available','',NULL,NULL,'body:58b572b71bd0c47fa84a7e7a339a0e4b9b5f08375a58568467573a581d5c2f0e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f6a5e954-373e-4a6d-9bbb-22336a55ef76','news-f6a5e954-373e-4a6d-9bbb-22336a55ef76','فييم تستعرض في ليب 2026 حلول مرونة البيانات الموثوقة لعصر الذكاء الاصطناعي وتؤكد التزامها المتنامي تجاه المملكة','فييم تستعرض في ليب 2026 حلول مرونه البيانات الموثوقه لعصر الذكاء الاصطناعي وتؤكد التزامها المتنامي تجاه المملكه','وخلال المعرض، ستقدم فييم أحدث ابتكاراتها في مجالات مرونة البيانات، والتعافي السيبراني، والجاهزية للذكاء الاصطناعي، وحماية البيانات في البيئات السحابية الهجينة، ومرونة مايكروسوفت 365.','["أعلنت شركة فييم سوفتوير، المتخصصة في الثقة في البيانات والذكاء الاصطناعي، مشاركتها في معرض ليب 2026 للعام السادس على التوالي، في خطوة تعكس استمرار استثماراتها في المملكة العربية السعودية والتزامها بدعم القطاعات في بناء بيئة بيانات موثوقة ومرنة تلائم متطلبات عصر الذكاء الاصطناعي.","وتشارك فييم هذا العام تحت شعار «مرونة البيانات الموثوقة لعصر الذكاء الاصطناعي في السعودية»، حيث تستعرض كيف يمكن للقطاعات في المملكة تعزيز مرونتها السيبرانية، وحماية بياناتها الحيوية، وتسريع تبني الذكاء الاصطناعي، والمضي بثقة في رحلتها نحو التحول السحابي، بما يدعم مستهدفات رؤية السعودية 2030.","كما ستتواجد الشركة في جناح AmiViz ضمن DeepFest، إلى جانب رعايتها للصالة المميزة، بما يتيح فرصًا أوسع للتواصل مع القيادات التنفيذية والعملاء والشركاء على مدار أيام المعرض.","وقال مينا مجلي، نائب الرئيس الإقليمي لمنطقة شرق أوروبا والشرق الأوسط وأفريقيا لدى فييم: «تعد السعودية من أسرع الاقتصادات الرقمية نموًا في المنطقة، مع تسارع تبني القطاعات للابتكار السحابي والذكاء الاصطناعي والبيانات."]','الذكاء الاصطناعي','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ra2qu32','https://sabq.org/article/ra2qu32','','https://sabq.org/article/ra2qu32','صحيفة سبق','','2026-08-27T04:14:00.000Z','2026-08-27T07:15:00.000Z','2026-08-27T10:21:06.725Z','https://media.sabq.org/news/2026/08/ac1623b0-7f6b-4ca6-ae5d-255dd1fdd077/w1600.webp','/api/media/f6a5e954-373e-4a6d-9bbb-22336a55ef76','/api/media/f6a5e954-373e-4a6d-9bbb-22336a55ef76?variant=thumbnail','فييم تستعرض في ليب 2026 حلول مرونة البيانات الموثوقة لعصر الذكاء الاصطناعي وتؤكد التزامها المتنامي تجاه المملكة',1600,1414,'valid','published','archived','valid',93,'368827b00215820823fba920aa1ac61096a6edb96399e726558c681e1352004d','c8bee4ac8e72acf282f6ccfcfa9ddc67520bf10386cd68373ee161b8be1d15d0','محدّث','2026-08-27T10:21:06.725Z','2026-10-07T20:27:57.471Z','','',0,0,'saudi_national','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة فييم سوفتوير المتخصصة في","الاقتصاد والأسواق","التقنية والتحول الرقمي","أوروبا","الشرق الأوسط"]','["شركة فييم سوفتوير المتخصصة في","الاقتصاد والأسواق","التقنية والتحول الرقمي","الشرق الأوسط"]','classified','','[{"category":"الاقتصاد","score":5.5},{"category":"أخبار السعودية","score":4.5},{"category":"العالم","score":3}]','Active','2026-10-07T20:27:57.471Z',200,77,0,'source_article_available','',NULL,NULL,'body:c88fe1c0dfdffb97b76c125351eb6ab954c6b6ce7e3026d25044a90eefc24496','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('27b5b7fe-b6fb-4c17-8968-ac3f5f95ec1c','news-27b5b7fe-b6fb-4c17-8968-ac3f5f95ec1c','مستشفى الأمير محمد بن ناصر بجازان يُجري أولى عمليات إزالة الحصوات الكلوية بتقنية PCNL','مستشفي الامير محمد بن ناصر بجازان يجري اولي عمليات ازاله الحصوات الكلويه بتقنيه pcnl','وتُعدّ تقنية «PCNL» من الأساليب المتقدمة لعلاج الحصوات الكبيرة والمعقدة، وتتميز بكونها أقل تدخلاً جراحياً مقارنةً بالأساليب التقليدية في الحالات المناسبة.','["نجح مستشفى الأمير محمد بن ناصر بجازان، أحد مكونات تجمع جازان الصحي، في إجراء أول عملية لإزالة حصوات كلوية معقدة عن طريق الجلد باستخدام تقنية «PCNL» (رأب الكلية عبر الجلد)، في خطوة تعزز قدرات المستشفى في التعامل مع الحالات المتقدمة في جراحة المسالك البولية.","وأُجريت العملية لمريض كان يعاني من حصوات كلوية معقدة، إذ تمكّن الفريق الطبي من الوصول إلى الكلية عبر فتحة صغيرة في الجلد وإزالة الحصوات بنجاح.","وضمّ الفريق الطبي المشارك في العملية كوادر متخصصة من أقسام المسالك البولية والتخدير والتمريض والأشعة، وأسهم هذا التكامل الطبي والفني في إنجاح الإجراء، مؤكداً جاهزية الكوادر والتجهيزات الطبية بالمستشفى لتقديم خدمات تخصصية متقدمة.","ويأتي هذا الإنجاز في إطار جهود مستشفى الأمير محمد بن ناصر لتطوير خدماته الطبية والتوسع في الإجراءات التخصصية، والارتقاء بجودة الرعاية الصحية المقدمة للمرضى، بما ينسجم مع مستهدفات تطوير القطاع الصحي وتحسين تجربة المستفيدين."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wc25v9q','https://sabq.org/article/wc25v9q','','https://sabq.org/article/wc25v9q','عمر عريبي','جازان','2026-08-27T04:14:00.000Z','2026-08-27T07:14:00.000Z','2026-08-27T10:21:06.859Z','https://media.sabq.org/news/2026/08/4aba0f5d-b1fc-47e4-9a3d-40b8f242ca7e/w1280.webp','/api/media/27b5b7fe-b6fb-4c17-8968-ac3f5f95ec1c','/api/media/27b5b7fe-b6fb-4c17-8968-ac3f5f95ec1c?variant=thumbnail','مستشفى الأمير محمد بن ناصر بجازان يُجري أولى عمليات إزالة الحصوات الكلوية بتقنية PCNL',1280,726,'valid','published','archived','valid',92,'4616274dda6178cca1d31aed2777b3c2c6c63b50fa741d52531fe7190f0a5a09','a7953c4c1947386b140ff0005fda48b0fa0f67b2cd4a65976ca180470e75e78a','محدّث','2026-08-27T10:21:06.859Z','2026-10-07T20:27:46.728Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["جازان","الصحة العامة","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["الصحة العامة","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"المناطق","score":3},{"category":"التقنية","score":3},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T20:27:46.728Z',200,79,0,'source_article_available','',NULL,NULL,'body:59d342b3be761f7a24e721791b232d15b9c5e35ba594e5f34ccb8209b18b68be','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0b2c5e0c-7b60-407c-9c2b-d8938d0ed3c6','news-0b2c5e0c-7b60-407c-9c2b-d8938d0ed3c6','المملكة خالية رسميًا من «الدورين».. اعتراف دولي يعزز مكانتها في صحة الخيول ودعم بطولات الفروسية','المملكه خاليه رسميا من الدورين اعتراف دولي يعزز مكانتها في صحه الخيول ودعم بطولات الفروسيه','أعلنت المنظمة العالمية للصحة الحيوانية (WOAH) اعتماد الخلو الذاتي للمملكة رسميًا من مرض "الدورين" الذي يصيب الخيول، إثر استيفائها التام للأنظمة والمعايير القياسية المعتمدة عالميًا.','["وأوضحت أن هذا الاعتراف جاء نتيجة تقييم متكامل للملف الفني المقدم من المركز الوطني للوقاية من الآفات النباتية والأمراض الحيوانية ومكافحتها (وقاء)، الذي وثّق آليات التقصي الوبائي، ودقة المسوح الميدانية، والتدابير الاحترازية المحكمة المطبقة على مستوى مناطق المملكة.","ويؤكد هذا الاعتماد النجاح المتواصل للخطط الوطنية الإستراتيجية في حماية قطاع الخيل وتطوير المنظومة البيطرية، مما ينعكس إيجابًا على تحفيز استضافات البطولات الرياضية العالمية للفروسية، ودعم قطاع سباقات الخيل على أرض المملكة.","ويُبرز هذا التتويج الدولي المستوى المتقدم للخدمات البيطرية في المملكة، ويكرّس كفاءة الكوادر الوطنية وموثوقية إجراءاتها الوقائية للحد من الأمراض العابرة للحدود وتأمين الثروة الحيوانية.","يذكر أن المنظمة العالمية للصحة الحيوانية قد أعلنت خلال هذا العام عن خلو المملكة من مرض التهاب الشرايين الفيروسي في الخيول، وخلال العام الماضي أعلنت عن الخلو من عدة أمراض تصيب الفصيلة الخيلية ومنها الرعام وأنيميا الخيل، وطاعون الخيل الأفريقي، حيث يترجم ذلك كفاءة الإجراءات البيطرية والمسوح التي تطبقها المملكة وفق المعايير الدولية، وتأكيد ريادتها وموثوقيتها في حماية الصحة الحيوانية؛ بما يدعم استضافة كبرى بطولات…"]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/zqe1jeb','https://sabq.org/article/zqe1jeb','','https://sabq.org/article/zqe1jeb','صحيفة سبق','الرياض','2026-08-27T04:29:00.000Z','2026-08-27T07:29:00.000Z','2026-08-27T10:39:06.802Z','https://media.sabq.org/news/2026/08/9284c09e-00ad-4b49-a25b-651decbe065b/w1600.webp','/api/media/0b2c5e0c-7b60-407c-9c2b-d8938d0ed3c6','/api/media/0b2c5e0c-7b60-407c-9c2b-d8938d0ed3c6?variant=thumbnail','المملكة خالية رسميًا من «الدورين».. اعتراف دولي يعزز مكانتها في صحة الخيول ودعم بطولات الفروسية',1600,2409,'valid','published','archived','valid',56,'2e80397eb56a232253259cd701870c7b14a00019383516e2f003ae85796c6d43','95601d4b5f714cad3b6de4a3d3de1320fee122af6164c66de4a889a0309a1b42','محدّث','2026-08-27T10:39:06.802Z','2026-10-07T20:49:18.045Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض","الصحة العامة","الرياضة السعودية"]','["الصحة العامة","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":1.5},{"category":"الصحة","score":1.5}]','Temporarily Unreachable','2026-10-07T20:49:18.045Z',NULL,78,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8d8321d1-0f6b-4b08-96bc-be81b6f57bc6','news-8d8321d1-0f6b-4b08-96bc-be81b6f57bc6','إجراء أول عملية لإزالة حصوات كلوية معقدة عن طريق الجلد بمستشفى الأمير محمد بن ناصر بجازان','اجراء اول عمليه لازاله حصوات كلويه معقده عن طريق الجلد بمستشفي الامير محمد بن ناصر بجازان','نجح مستشفى الأمير محمد بن ناصر ب جازان ، أحد مكونات تجمع جازان الصحي، في إجراء أول عملية لإزالة حصوات كلوية معقدة عن طريق الجلد (PCNL)، في إنجاز طبي يعزز قدراته في التعامل مع الحالات المتقدمة في جراحة المسالك البولية.','["وأُجريت العملية لمريض كان يعاني من حصوات كلوية معقدة، إذ تمكن الفريق الطبي من الوصول إلى الكلية عبر فتحة صغيرة في الجلد وإزالة الحصوات باستخدام تقنية (PCNL). وتُعد هذه التقنية من الأساليب المتقدمة لعلاج الحصوات الكبيرة والمعقدة، كما تتميز بكونها أقل تدخّلًا جراحيًا مقارنة بالأساليب التقليدية، في الحالات المناسبة.","وشارك في إجراء العملية فريق طبي متعدد التخصصات، ضم كوادر من أقسام المسالك البولية والتخدير والتمريض والأشعة. وأسهم هذا التكامل الطبي والفني في نجاح الإجراء، مؤكدًا جاهزية الكوادر والتجهيزات الطبية بالمستشفى لتقديم خدمات تخصصية متقدمة.","ويأتي هذا الإنجاز ضمن جهود مستشفى الأمير محمد بن ناصر لتطوير خدماته الطبية والتوسع في الإجراءات التخصصية، والارتقاء بجودة الرعاية الصحية المقدمة للمرضى، بما ينسجم مع مستهدفات تطوير القطاع الصحي وتحسين تجربة المستفيدين."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/z16l2925x','https://ajel.sa/local/z16l2925x','https://ajel.sa/local/z16l2925x','https://ajel.sa/local/z16l2925x','علي الجريبي','جازان','2026-08-27T04:56:00.000Z','Wed, 07 Oct 2026 20:52:38 GMT','2026-08-27T11:12:06.158Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/f0159de6-9f2a-4585-b201-158f0695a937-crop-HuzaO_3w.jpg','/api/media/8d8321d1-0f6b-4b08-96bc-be81b6f57bc6','/api/media/8d8321d1-0f6b-4b08-96bc-be81b6f57bc6?variant=thumbnail','إجراء أول عملية لإزالة حصوات كلوية معقدة عن طريق الجلد بمستشفى الأمير محمد بن ناصر بجازان',1200,675,'valid','published','archived','valid',92,'f65cb4431614cec47b8c589214b0f65fe5cbb41bdc4dce94501b8addb484fcf9','237a1223125d9a3b0c787129792eabe3a1ff94dac7ed03bfea6389ade64916e5','محدّث','2026-08-27T11:12:06.158Z','2026-10-07T20:52:40.505Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["جازان","الصحة العامة","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["الصحة العامة","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"المناطق","score":3},{"category":"الاقتصاد","score":1.5},{"category":"التقنية","score":1.5}]','Updated','2026-10-07T20:52:40.505Z',200,80,0,'source_content_changed','',NULL,NULL,'body:76b8abcfc32278510cc411cf4080e3be3269fa66c4ae74e6ebb777e4eb96d3c0','Wed, 07 Oct 2026 20:52:38 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('059c8fd9-8617-46e6-a5fe-327790bc6e1b','news-059c8fd9-8617-46e6-a5fe-327790bc6e1b','القيادة تهنئ رئيسة جمهورية مولدوفا بذكرى استقلال بلادها','القياده تهنئ رئيسه جمهوريه مولدوفا بذكري استقلال بلادها','بعث خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، برقية تهنئة، لفخامة السيدة مايا ساندو رئيسة جمهورية مولدوفا ، بمناسبة ذكرى يوم الاستقلال لبلادها.','["وأعرب الملك المفدى، عن أصدق التهاني وأطيب التمنيات بدوام الصحة والسعادة لفخامتها، ولحكومة وشعب جمهورية مولدوفا الصديق اطراد التقدم والازدهار.","كما بعث صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء، برقية تهنئة، لفخامة السيدة مايا ساندو رئيسة جمهورية مولدوفا، بمناسبة ذكرى يوم الاستقلال لبلادها.","وعبّر سمو ولي العهد، عن أطيب التهاني وأصدق التمنيات بموفور الصحة والسعادة لفخامتها، ولحكومة وشعب جمهورية مولدوفا الصديق المزيد من التقدم والازدهار."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/3gvmkrlp6','https://ajel.sa/local/3gvmkrlp6','https://ajel.sa/local/3gvmkrlp6','https://ajel.sa/local/3gvmkrlp6','فريق التحرير','','2026-08-27T04:54:00.000Z','Wed, 07 Oct 2026 20:51:45 GMT','2026-08-27T11:12:06.339Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%AE%D8%A7%D8%AF%D9%85-%D8%A7%D9%84%D8%AD%D8%B1%D9%85%D9%8A%D9%86-%D9%88%D9%88%D9%84%D9%8A-%D8%A7%D9%84%D8%B9%D9%87%D8%AF-Qcuufzxp.jpg','/api/media/059c8fd9-8617-46e6-a5fe-327790bc6e1b','/api/media/059c8fd9-8617-46e6-a5fe-327790bc6e1b?variant=thumbnail','القيادة تهنئ رئيسة جمهورية مولدوفا بذكرى استقلال بلادها',1200,675,'valid','published','archived','valid',99,'d54863fd49c8a6d7998525cb7e809a2af2f5f3921b1e4cc09dc3bf0e85c1885a','c14f19c32c9fe0446d11ea472ca6776c9fe62d195cd160292783a10531e2b702','محدّث','2026-08-27T11:12:06.339Z','2026-10-07T20:51:46.839Z','','',0,0,'saudi_national','مهم',77,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","رئيس مجلس الوزراء برقية تهنئة","مجلس الوزراء برقية تهنئة لفخامة","الصحة العامة"]','["ولي العهد رئيس مجلس الوزراء","رئيس مجلس الوزراء برقية تهنئة","مجلس الوزراء برقية تهنئة لفخامة","الصحة العامة"]','classified','','[{"category":"السيارات","score":3},{"category":"السياسة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T20:51:46.839Z',200,77,0,'source_content_changed','',NULL,NULL,'body:e89ef83d0fe9652d3b2520024694732eb1373d6a3c6d918195e054251df50d18','Wed, 07 Oct 2026 20:51:45 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('de979d3b-b672-4808-9cd9-e1b690afbff5','news-de979d3b-b672-4808-9cd9-e1b690afbff5','137 ألف بلاغ في 3 أشهر.. «عاجل» ترصد خريطة بلاغات المستهلكين والمتاجر الإلكترونية في الصدارة','137 الف بلاغ في 3 اشهر عاجل ترصد خريطه بلاغات المستهلكين والمتاجر الالكترونيه في الصداره','ووفق بيانات وزارة التجارة للربع الثاني من عام 2026، نفذت الفرق الرقابية أكثر من 151 ألف زيارة رقابية على المنشآت التجارية والمتاجر الإلكترونية؛ للتحقق من مدى التزامها بالأنظمة واللوائح الواقعة ضمن اختصاص الوزارة.','["كشفت بيانات حديثة ل وزارة التجارة عن معالجة أكثر من 137 ألف بلاغ تجاري خلال الربع الثاني من عام 2026، فيما تصدرت بلاغات المتاجر الإلكترونية وبلاغات عدم الالتزام بسياسة الاستبدال والاسترجاع قائمة البلاغات الواردة، بالتزامن مع تنفيذ أكثر من 151 ألف زيارة رقابية على المنشآت التجارية والمتاجر الإلكترونية.","ورصدت « عاجل »، استنادًا إلى بيانات وزارة التجارة، أبرز المؤشرات المتعلقة ببلاغات المستهلكين والرقابة على الأسواق خلال ثلاثة أشهر، في ظل التوسع المتواصل في التجارة الإلكترونية وتنامي الاعتماد على التسوق عبر المنصات والمتاجر الرقمية.","ولا تعني أعداد البلاغات بالضرورة ثبوت وجود مخالفة في كل حالة، إذ يخضع كل بلاغ للمعالجة والتحقق وفق الإجراءات المتبعة لدى الجهات المختصة."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/0qkualtnx','https://ajel.sa/local/0qkualtnx','https://ajel.sa/local/0qkualtnx','https://ajel.sa/local/0qkualtnx','ماجد الفريدي','','2026-08-27T04:56:00.000Z','Wed, 07 Oct 2026 20:51:54 GMT','2026-08-27T11:12:06.398Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%AA%D8%AC%D8%A7%D8%B1%D8%A9-CE6RpTqu.jpg','/api/media/de979d3b-b672-4808-9cd9-e1b690afbff5','/api/media/de979d3b-b672-4808-9cd9-e1b690afbff5?variant=thumbnail','137 ألف بلاغ في 3 أشهر.. «عاجل» ترصد خريطة بلاغات المستهلكين والمتاجر الإلكترونية في الصدارة',1200,675,'valid','published','archived','valid',40,'86e8f4fc370d3b0f930154915e5d004125ca61d5c9077194fc751d8b306ba4ad','173567e92c993b4432a69ca8bdf4f61bf822518c74239aa900a4e16f91b3424f','محدّث','2026-08-27T11:12:06.398Z','2026-10-07T20:51:56.007Z','','',0,0,'international','عادي',52,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة التجارة عن معالجة أكثر","الاقتصاد والأسواق","التقنية والتحول الرقمي","السياسة والعلاقات الدولية"]','["وزارة التجارة عن معالجة أكثر","الاقتصاد والأسواق","التقنية والتحول الرقمي","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"التقنية","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T20:51:56.007Z',200,77,0,'source_content_changed','',NULL,NULL,'body:14f472724b0413a5b227556dcd6e498a636c964c29622d806604024162bf3ed5','Wed, 07 Oct 2026 20:51:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0c5225ae-2122-48bb-8109-c7cb03ff0578','news-0c5225ae-2122-48bb-8109-c7cb03ff0578','الصين تعلن فقدان 100 من رعاياها بمناطق الفيضانات على الجانب النيبالي من الحدود','الصين تعلن فقدان 100 من رعاياها بمناطق الفيضانات علي الجانب النيبالي من الحدود','أعلنت وزارة الخارجية الصينية فقدان نحو 100 مواطن صيني في المناطق التي اجتاحتها الفيضانات على الجانب النيبالي من الحدود. وأوضح «لين» أن «الكارثة أسفرت عن خسائر بشرية فادحة، وأسفرت عن فقدان أشخاص على جانبي الحدود الصينية - النيبالية»، مشيرا إلى أن البلدين على تواصل وثيق ويعملان على تنسيق جهود الإنقاذ.','["أعلنت وزارة الخارجية الصينية فقدان نحو 100 مواطن صيني في المناطق التي اجتاحتها الفيضانات على الجانب النيبالي من الحدود.","وقال المتحدث باسم الوزارة لين جيان - في مؤتمر صحفي عقده اليوم، الخميس، ونقلت شبكة «تشانيل نيوز آشيا» مقتطفات منه - إن «السفارة الصينية في نيبال تسعى للحصول على مزيد من المعلومات من السلطات النيبالية بهذا الشأن».","وأوضح «لين» أن «الكارثة أسفرت عن خسائر بشرية فادحة، وأسفرت عن فقدان أشخاص على جانبي الحدود الصينية - النيبالية»، مشيرا إلى أن البلدين على تواصل وثيق ويعملان على تنسيق جهود الإنقاذ."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/y8n8fd6kv','https://ajel.sa/misc/y8n8fd6kv','https://ajel.sa/misc/y8n8fd6kv','https://ajel.sa/misc/y8n8fd6kv','فريق التحرير','','2026-08-27T04:50:00.000Z','Wed, 07 Oct 2026 20:51:43 GMT','2026-08-27T11:12:06.814Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/54545-crop-Kx9Q2mIp.jpg','/api/media/0c5225ae-2122-48bb-8109-c7cb03ff0578','/api/media/0c5225ae-2122-48bb-8109-c7cb03ff0578?variant=thumbnail','الصين تعلن فقدان 100 من رعاياها بمناطق الفيضانات على الجانب النيبالي من الحدود',1200,675,'valid','published','archived','valid',46,'ed5cb9865100d7e0286a0d1063f6e52624746e90cf665868b3a8bc3cef129f74','75ef8e75f21b387aa39643e74c2360dcd38727fca2e94e35151f2188c4ed76bf','محدّث','2026-08-27T11:12:06.814Z','2026-10-07T20:51:44.611Z','','',0,0,'saudi_national','مهم',70,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الخارجية الصينية فقدان نحو","السفر والسياحة","الصين"]','["وزارة الخارجية الصينية فقدان نحو","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"العالم","score":3},{"category":"السفر","score":1.5}]','Updated','2026-10-07T20:51:44.611Z',200,74,0,'source_content_changed','',NULL,NULL,'body:9e7dd41b8c4a3ce5886bc7fa468c7c3a7e8f0c881f099d7016f7c7b909a5c6cf','Wed, 07 Oct 2026 20:51:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f8aca954-33bb-4410-bd8d-cbd565b98558','news-f8aca954-33bb-4410-bd8d-cbd565b98558','ضبط مقيم سوداني اقتحم بمركبته روضات محمية الملك عبدالعزيز الملكية','ضبط مقيم سوداني اقتحم بمركبته روضات محميه الملك عبدالعزيز الملكيه','ضبطت القوات الخاصة للأمن البيئي مقيماً من الجنسية السودانية، بعد دخوله بمركبته في الفياض والروضات البرية المحمية داخل محمية الملك عبدالعزيز الملكية، مخالفاً بذلك نظام البيئة، فيما اتخذت القوات الإجراءات النظامية بحقه.','["وأوضحت القوات الخاصة للأمن البيئي أن عقوبة دخول المركبات والسيارات في الفياض والروضات البرية المحمية تصل إلى 2,000 ريال.","ودعت القوات المواطنين والمقيمين إلى الإبلاغ عن أي حالات تمثّل اعتداءً على البيئة أو الحياة الفطرية، عبر الرقم 911 في مناطق مكة المكرمة والمدينة المنورة والرياض والمنطقة الشرقية، فيما يُخصَّص الرقمان 999 و996 لبقية مناطق المملكة، مع ضمان السرية التامة لجميع البلاغات وعدم تحمّل المبلّغ أي مسؤولية."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/okgklwm','https://sabq.org/article/okgklwm','','https://sabq.org/article/okgklwm','صحيفة سبق','الرياض','2026-08-27T05:10:00.000Z','2026-08-27T08:10:00.000Z','2026-08-27T11:18:06.829Z','https://media.sabq.org/news/2026/07/2c8defd9-d90b-48ff-832a-354086db8447/w738.webp','/api/media/f8aca954-33bb-4410-bd8d-cbd565b98558','/api/media/f8aca954-33bb-4410-bd8d-cbd565b98558?variant=thumbnail','ضبط مقيم سوداني اقتحم بمركبته روضات محمية الملك عبدالعزيز الملكية',738,369,'valid','published','archived','valid',51,'e0be30f20c64ba016dc69fcab2fabd7a7093396d38d57ad0ea3730fd111bff06','70e03c8482fe04cda61d87b92b305f6efeefa7471994250dd85edbca302709d0','محدّث','2026-08-27T11:18:06.830Z','2026-10-07T20:51:56.640Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض","مكة","المدينة المنورة"]','["المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"الاقتصاد","score":1.5}]','Active','2026-10-07T20:51:56.640Z',200,77,0,'source_article_available','',NULL,NULL,'body:c32ac3b7b3660a310ae843270cc3f124d6c4aa67fa955c54412219dd6158f82d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ff3362bd-5734-413b-b384-2aab65c055fe','news-ff3362bd-5734-413b-b384-2aab65c055fe','العُلا.. خمس قصص تراثية تمتد 200 ألف عام وتستقطب العالم','العلا خمس قصص تراثيه تمتد 200 الف عام وتستقطب العالم','تحتضن العُلا شواهد على وجود بشري يمتد إلى 200 ألف عام، إلى جانب تاريخ استيطاني يعود إلى ما لا يقل عن 7 آلاف عام، وتروي مواقعها الأثرية خمس قصص تكشف جوانب من هذا الامتداد التاريخي والتواصل الحضاري.','["ترسم محافظة العُلا عبر شواهدها الأثرية وتنوع موروثها الثقافي فصولاً متعاقبة من تاريخ الإنسان في شمال غرب الجزيرة العربية؛ إذ ارتبطت منذ القدم بطرق التجارة والتواصل الحضاري، وتعاقبت على أرضها ممالك وحضارات تركت إرثاً لا تزال تفاصيله حاضرة في المواقع الأثرية والنقوش والفنون والممارسات الاجتماعية.","أولاً: الحِجر — عمارة الأنباط في الصخر تقف المقابر النبطية المنحوتة في التكوينات الصخرية بالحِجر شاهداً على مستوى متقدم من العمارة والنحت، وعلى ما شهدته المنطقة من تواصل مع حضارات العالم القديم.","ويُعدّ الحِجر أول موقع في المملكة العربية السعودية يُدرج ضمن قائمة التراث العالمي لليونسكو، ويضم نحو 141 مقبرة، منها 93 مقبرة مزخرفة.","وتكشف واجهات المقابر عن تنوع في التأثيرات المعمارية والفنية؛ إذ مزج نحاتو الأنباط بين الأفاريز ذات الطراز المصري وزخارف بلاد الرافدين والأقواس والأعمدة اليونانية والرومانية الكلاسيكية، وصاغوها ضمن أسلوب نبطي مميز يعكس براعتهم وعمق التفاعل الحضاري في المنطقة."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/t9m4g2d','https://sabq.org/article/t9m4g2d','','https://sabq.org/article/t9m4g2d','صحيفة سبق','المدينة المنورة','2026-08-27T05:08:00.000Z','2026-08-27T08:10:00.000Z','2026-08-27T11:18:07.329Z','https://media.sabq.org/news/2026/08/1b990805-a63f-409a-8c95-4375573d5a32/w1600.webp','/api/media/ff3362bd-5734-413b-b384-2aab65c055fe','/api/media/ff3362bd-5734-413b-b384-2aab65c055fe?variant=thumbnail','العُلا.. خمس قصص تراثية تمتد 200 ألف عام وتستقطب العالم',1600,1108,'valid','published','archived','valid',49,'bfc7d4adfcebb7e830eca34517f88f93242cbff7ac32bfafd978e77a0ddadea7','f81922cc8e26891d16bda5a76c0ae3317d84e0617c2d00e20ae77e582b99271f','محدّث','2026-08-27T11:18:07.329Z','2026-10-07T20:51:58.155Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["المدينة المنورة","الاقتصاد والأسواق"]','["المدينة المنورة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المناطق","score":4},{"category":"أخبار السعودية","score":3},{"category":"العالم","score":3}]','Active','2026-10-07T20:51:58.155Z',200,77,0,'source_article_available','',NULL,NULL,'body:d189498d0582c97aab9439042628f4c6a4ad2d5f14d4dcea0e2348d3c1af41df','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9e0228b5-e782-4e47-82a6-87089389b38b','news-9e0228b5-e782-4e47-82a6-87089389b38b','دبلوماسية المضيق: إلى أين؟','دبلوماسيه المضيق الي اين','منح توقيع مذكرة التفاهم بين الولايات المتحدة الأمريكية وإيران، ببنودها الأربعة عشر، بتاريخ الثاني من شهر المحرم، الموافق للسابع عشر من شهر يونيو من هذا العام، بارقةَ أملٍ للمنطقة والعالم بانتهاء حالة الحرب بين الطرفين، والركون إلى الدبلوماسية لتسوية أسباب هذه الحرب والانتقال إلى مرحلة السلام بينهما بعدما يقارب أربعة عقود من الحرب الباردة بينهما، تخللتها…','["منح توقيع مذكرة التفاهم بين الولايات المتحدة الأمريكية وإيران، ببنودها الأربعة عشر، بتاريخ الثاني من شهر المحرم، الموافق للسابع عشر من شهر يونيو من هذا العام، بارقةَ أملٍ للمنطقة والعالم بانتهاء حالة الحرب بين الطرفين، والركون إلى الدبلوماسية لتسوية أسباب هذه الحرب والانتقال إلى مرحلة السلام بينهما بعدما يقارب أربعة عقود من الحرب الباردة بينهما، تخللتها ثلاثة أعوام من بعض الانفراج بعد توقيع الاتفاق النووي مع…","واأسفاه، لقد أثبتت إيران خلال الحرب عليها - بما لا يدع مجالاً للتأويل - أنها كانت تبطن الشر لجيرانها باستهدافهم باعتداءاتها، ثم تبرير ذلك بادعاءات واهية. وإن حديثها الدائم عن النوايا الحسنة لا ينخدع به حصيف. أما الحديث المنمق عن ضرورة وضع إجراءات لبناء الثقة وإقامة علاقات حُسن جوار قائمة على المصالح المشتركة ومبادئ العلاقات الدولية؛ فأمر غير ممكن في ظل استمرار اعتداءاتها على دول الخليج، وتهديداتها المباشرة لها أو…","إن استمرار إيران في استخدام ورقة مضيق هرمز في دبلوماسيتها لإنهاء الحرب لن يضر الولايات المتحدة وحدها؛ بل سيضر إيران نفسها والمنطقة والعالم، فدبلوماسية البرنامج النووي - خلال العقدين الماضيين - لم تمنع الحرب، ودبلوماسية مضيق هرمز وابتزاز المنطقة والعالم بها لن يمنع ما تخشاه إيران إن استمر سلوكها المنافي للقواعد والقوانين والأعراف الدولية. كما أن أذناب إيران في المنطقة مرفوضون من شعوب الدول الموجودين بها؛ فالأولى…","واليوم، وقد انتهت مهلة الستين يوماً التي أُقرَّت في مذكرة التفاهم ليتم التفاوض خلالها، من دون اتفاق، ها نحن نسمع من الطرفين أصوات الوعيد والتهديد بالتصعيد، وفرضت الولايات المتحدة الأمريكية طوقاً اقتصادياً فولاذياً على إيران لكي تتجاوب مع طلباتها، وليقضي الله أمراً كان مفعولاً."]','السياسة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2262998','https://www.okaz.com.sa/articles/authors/2262998','','https://www.okaz.com.sa/articles/authors/2262998','تركي الفيصل','مكة المكرمة','2026-08-26T13:39:00.000Z','Wed, 07 Oct 2026 18:31:09 GMT','2026-08-27T11:18:21.684Z','https://www.okaz.com.sa/okaz/uploads/authors/1916.jpg?v=1787759635','/api/media/9e0228b5-e782-4e47-82a6-87089389b38b','/api/media/9e0228b5-e782-4e47-82a6-87089389b38b?variant=thumbnail','دبلوماسية المضيق: إلى أين؟',400,400,'valid','published','archived','valid',55,'ceb062a373023924c19229ee3c804f4c983343b55a59ea2a8ecd0fea5704cb30','42e7ac0ec85894ff9e6c0bd03eae651f884ebdbb9e3660cd1aedcb650d02c942','محدّث','2026-08-27T11:18:21.684Z','2026-10-07T20:51:50.800Z','','',0,0,'saudi_region','عادي',52,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة المكرمة","الاقتصاد والأسواق","السياسة والعلاقات الدولية","إيران","الولايات المتحدة"]','["مكة المكرمة","الاقتصاد والأسواق","السياسة والعلاقات الدولية","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"العالم","score":4.5},{"category":"أخبار السعودية","score":3.5},{"category":"المجتمع","score":3}]','Active','2026-10-07T20:51:50.800Z',304,76,0,'source_article_available','',NULL,NULL,'body:85ad276e59de4c7262aaa02e47cbff2a4ae53efd63a5fe34e9564254e350d431','Wed, 07 Oct 2026 18:31:09 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2d7a0a0c-f49e-4949-a551-3267c6eaf62f','news-2d7a0a0c-f49e-4949-a551-3267c6eaf62f','ضبط 4 مواطنين صادوا 15 كائناً فطرياً بلا ترخيص في محمية الملك سلمان','ضبط 4 مواطنين صادوا 15 كائنا فطريا بلا ترخيص في محميه الملك سلمان','ضبطت الدوريات الميدانية للقوات الخاصة للأمن البيئي 4 مواطنين خلال تأديتها مهامها في تطبيق نظام البيئة بمحمية الملك سلمان الملكية، وذلك لارتكابهم مخالفة الصيد دون ترخيص، إذ كان بحوزتهم بندقيتان هوائيتان و15 كائناً فطرياً مصيداً، وأُوقفوا واتُّخذت الإجراءات النظامية بحقهم قبل إحالتهم إلى الجهة المختصة.','["وشدّدت القوات الخاصة للأمن البيئي على ضرورة الالتزام بنظام البيئة ولوائحه التنفيذية التي تحظر صيد الكائنات الفطرية، مؤكدةً أن العقوبات المقررة تشمل: غرامة 10,000 ريال على الصيد دون ترخيص، وغرامة 5,000 ريال على الصيد في الأماكن المحظورة، فضلاً عن غرامة 5,000 ريال على صيد طائر الدّخل دون ترخيص.","ودعت القوات الخاصة للأمن البيئي المواطنين والمقيمين إلى المبادرة بالإبلاغ عن أي اعتداء على البيئة أو الحياة الفطرية، عبر الاتصال بالرقم 911 في مناطق مكة المكرمة والمدينة المنورة والرياض والمنطقة الشرقية، والرقمين 999 و996 في بقية مناطق المملكة، مؤكدةً أن جميع البلاغات تُعامَل بسرية تامة دون أي مسؤولية على المُبلِّغ."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/a8n98jg','https://sabq.org/article/a8n98jg','','https://sabq.org/article/a8n98jg','صحيفة سبق','الرياض','2026-08-27T05:20:00.000Z','2026-08-27T08:21:00.000Z','2026-08-27T11:30:06.800Z','https://media.sabq.org/news/2026/08/263270c9-ee27-4662-8cb7-01af1675f4e1/w523.webp','/api/media/2d7a0a0c-f49e-4949-a551-3267c6eaf62f','/api/media/2d7a0a0c-f49e-4949-a551-3267c6eaf62f?variant=thumbnail','ضبط 4 مواطنين صادوا 15 كائناً فطرياً بلا ترخيص في محمية الملك سلمان',523,295,'valid','published','archived','valid',89,'0641af355c73c44c9081e1c1edb071c7123e557cd6d7305671c5c7553c7d06fb','0500bd2b863b7d1b57f31ed0466353da1d1e1879d550c814c89479dad4a3317f','محدّث','2026-08-27T11:30:06.800Z','2026-10-07T20:52:47.982Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض","التقنية والتحول الرقمي","مكة","المدينة المنورة"]','["التقنية والتحول الرقمي","المدينة المنورة"]','classified','','[{"category":"التقنية","score":5},{"category":"المناطق","score":4.5},{"category":"المجتمع","score":3}]','Active','2026-10-07T20:52:47.982Z',200,75,0,'source_article_available','',NULL,NULL,'body:8f60b2517a4691fb0e11a52d52e88d4e0b01bb19c9537a9b8d467d4f27055a11','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c5fd9656-7af6-47d6-acb7-982922721de1','news-c5fd9656-7af6-47d6-acb7-982922721de1','دوريات الأمن بنجران تضبط يمنياً يمارس التسوّل وتحيله للجهات المختصة','دوريات الامن بنجران تضبط يمنيا يمارس التسول وتحيله للجهات المختصه','ضبطت دوريات الأمن بمنطقة نجران مخالفاً لنظام أمن الحدود من الجنسية اليمنية، ضُبط متلبساً بممارسة التسوّل، وجرى إيقافه واتخاذ الإجراءات النظامية بحقه وفق الأنظمة المعمول بها.','["وحثّ الأمن العام المتبرعين على توجيه تبرعاتهم عبر المنصات الرسمية المعتمدة، بما يضمن وصولها إلى مستحقيها الفعليين، وتجنّب تمويل ظاهرة التسوّل غير النظامي.","ويأتي هذا الضبط في إطار الجهود المتواصلة التي تبذلها وزارة الداخلية ممثلةً بالأمن العام، لمكافحة ظاهرة التسوّل بمختلف صورها وأشكالها، والحدّ من انتشارها في مناطق المملكة."]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/fnzzlxa','https://sabq.org/article/fnzzlxa','','https://sabq.org/article/fnzzlxa','صحيفة سبق','نجران','2026-08-27T05:18:00.000Z','2026-08-27T08:19:00.000Z','2026-08-27T11:30:06.901Z','https://media.sabq.org/news/2026/08/f4a01fe7-28e3-496a-aa50-7907742b78b8/w1024.webp','/api/media/c5fd9656-7af6-47d6-acb7-982922721de1','/api/media/c5fd9656-7af6-47d6-acb7-982922721de1?variant=thumbnail','دوريات الأمن بنجران تضبط يمنياً يمارس التسوّل وتحيله للجهات المختصة',1024,576,'valid','published','archived','valid',44,'059bb2793480b3dfa9f43f98aa59f987d766594b18109c3a3ea0072a59fc45d8','fa76562ab6af36006df951abb7cfa2f13eae1aeec0bc51044a5f0dca7281ef49','محدّث','2026-08-27T11:30:06.901Z','2026-10-07T20:52:47.974Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["نجران","وزارة الداخلية ممثلة بالأمن العام","الثقافة والفنون","الرياضة السعودية"]','["وزارة الداخلية ممثلة بالأمن العام","الثقافة والفنون","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الرياضة","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"السياسة","score":0}]','Active','2026-10-07T20:52:47.974Z',200,73,0,'source_article_available','',NULL,NULL,'body:3cb99e66a3ae7e36f68de9734996d26af28ac2d8fbead9d89a2c8b45af90ae5d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f5073885-1a9d-4059-94fe-2990369a6692','news-f5073885-1a9d-4059-94fe-2990369a6692','أكثر من 80 متحدثًا وخبيرًا دوليًا يثرون نقاشات القمة العالمية للاستثمار في باريس','اكثر من 80 متحدثا وخبيرا دوليا يثرون نقاشات القمه العالميه للاستثمار في باريس','تجمع القمة العالمية للاستثمار 2026، المقرر عقدها يومي 1 و2 سبتمبر في قصر المؤتمرات بالعاصمة الفرنسية باريس ، أكثر من 80 متحدثًا وخبيرًا دوليًا، إلى جانب أكثر من 2000 مشارك و40 لقاءً ثنائيًا، ضمن برنامج يضم سلسلة من الجلسات الحوارية واللقاءات المتخصصة عبر المسرح الرئيسي ومسرح «أغورا»، بمشاركة مستثمرين وقادة أعمال ومسؤولين وخبراء وممثلي كبرى الشركات…','["وتقدم القمة عبر مسرحيها برنامجًا يمتد على مدى يومين، ويجمع الخبرات الاقتصادية والاستثمارية والتقنية في حوار يتناول التحولات التي تشهدها حركة رأس المال والأسواق العالمية، ومستقبل الاستثمار في التقنية والطاقة والسياحة والصحة والاقتصاد الإبداعي والاستدامة، إلى جانب القطاعات الجديدة التي تعيد تشكيل خريطة الفرص الاستثمارية عالميًا.","ويجمع المسرح الرئيسي في اليوم الأول عددًا من الشخصيات الاقتصادية والاستثمارية الدولية، من بينهم سيلفيا بيبينو، الزميلة الزائرة الأولى في كلية لندن للاقتصاد والعلوم السياسية ومؤسسة GlobeEye، وبلانكا مورينو دودسون، المستشارة الأولى في الاقتصاد الدولي والمديرة السابقة في الأمم المتحدة وكبيرة الاقتصاديين السابقة في البنك الدولي ، ومايك أوسوليفان، المستثمر والكاتب والخبير الاقتصادي في Harvest Innovation، وماريو سينتينو،…","ويشارك كذلك جوانا فياض، المديرة الأولى لاستراتيجية الأعمال وتحقيق القيمة في Oracle، وجيريمي إلياهو أونتيفيروس، المدير الإداري لأبحاث مراكز البيانات والطاقة والقطاعات الصناعية في SemiAnalysis، وأدريان بينيلي، المدير الإداري ورئيس علاقات المستثمرين في الشرق الأوسط والشؤون العامة العالمية لدى Eurazeo، وإيفان دو لاستور، شريك الاستثمار الجريء في Bpifrance، ودانيال فريدلاندر، نائب الرئيس الأول ورئيس أوروبا في CCIA."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/vfb3ujjgq','https://ajel.sa/economy/vfb3ujjgq','https://ajel.sa/economy/vfb3ujjgq','https://ajel.sa/economy/vfb3ujjgq','فريق التحرير','الرياض','2026-08-27T05:18:00.000Z','Wed, 07 Oct 2026 21:00:46 GMT','2026-08-27T11:36:06.296Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/0-crop-zQvrrz8s.jpg','/api/media/f5073885-1a9d-4059-94fe-2990369a6692','/api/media/f5073885-1a9d-4059-94fe-2990369a6692?variant=thumbnail','أكثر من 80 متحدثًا وخبيرًا دوليًا يثرون نقاشات القمة العالمية للاستثمار في باريس',1200,675,'valid','published','archived','valid',98,'ab197c2360c764f53e0506d6360d6b6003de57fa377280977309528fd12b96f9','58ee3bd6a1379435646b2f5e8d57435f78434157736f12aa78e0d987023468b6','محدّث','2026-08-27T11:36:06.296Z','2026-10-07T21:00:48.187Z','','',0,0,'saudi_region','مهم',67,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","الرياض","الأمم المتحدة وكبيرة الاقتصاديين السابقة","الصحة العامة","الطاقة والنفط","السفر والسياحة","الثقافة والفنون","الاقتصاد والأسواق"]','["الأمم المتحدة وكبيرة الاقتصاديين السابقة","الصحة العامة","الطاقة والنفط","السفر والسياحة","الثقافة والفنون","الاقتصاد والأسواق"]','classified','','[{"category":"العالم","score":6},{"category":"السياسة","score":3.5},{"category":"التعليم","score":3}]','Updated','2026-10-07T21:00:48.187Z',200,74,0,'source_content_changed','',NULL,NULL,'body:691949528f4928e1b4eea2bce49c5d61cfe3b1dc01983c0d14fe657fd09191d7','Wed, 07 Oct 2026 21:00:46 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4ef760b4-1ec6-4c97-a98c-c87b3e74280e','news-4ef760b4-1ec6-4c97-a98c-c87b3e74280e','موعد خسوف القمر الجزئي في سماء المملكة.. وكيفية أداء صلاة الخسوف','موعد خسوف القمر الجزئي في سماء المملكه وكيفيه اداء صلاه الخسوف','وخلال فترة الخسوف الجزئي للقمر، سيغطي ظل الأرض نحو 93% تقريباً من سطح القمر، ويمكن رؤية خسوف القمر في المناطق التي يظهر فيها القمر عند حدوثه، وتشمل أمريكا الشمالية والجنوبية وأجزاء من أوروبا وأفريقيا.','["تشهد سماء المملكة فجر غدا الجمعة، 28 أغسطس 2026 ظاهرة فلكية، وهي خسوف القمر، وسيكون الخسوف جزئيًا وسيؤثر على أنحاء من العالم العربي وعدد من القارات.","ووفقا ل وكالة الفضاء السعودية ، فإن سبب حدوث خسوف القمر عندما تقع الأرض بين الشمس والقمر، فيمر القمر عبر ظل الأرض.","وأوضحت الوكالة أنه ستكون بداية مرحلة خسوف شبه الظل مرئية في جميع مناطق المملكة، كذلك يمكن رصد بداية مرحلة الخسوف الجزئي للقمر في المناطق الغربية والشمالية والجنوبية الغربية، إضافة إلى أجزاء من وسط المملكة، أما المراحل المتبقية لن تكون مرئية، حيث سيكون القمر تحت الأفق في المملكة."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/p6k1izy6u','https://ajel.sa/thehour/p6k1izy6u','https://ajel.sa/thehour/p6k1izy6u','https://ajel.sa/thehour/p6k1izy6u','فريق التحرير','','2026-08-27T05:11:00.000Z','Wed, 07 Oct 2026 21:00:44 GMT','2026-08-27T11:36:06.532Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-i1gmNqc8.jpg','/api/media/4ef760b4-1ec6-4c97-a98c-c87b3e74280e','/api/media/4ef760b4-1ec6-4c97-a98c-c87b3e74280e?variant=thumbnail','خسوف القمر',1200,675,'valid','published','archived','valid',49,'64fd0c3d8d42c56ee478b8ce51d5bb045a97a2a5f764c3a2de62538bb52e6b4e','c4984fc931eb3a590e4e6149af3ffd0eda83de66335180c1e409fc0f2035cf7c','محدّث','2026-08-27T11:36:06.532Z','2026-10-07T21:00:46.018Z','','',0,0,'saudi_national','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','needs_review','below_category_threshold','[{"category":"العالم","score":4.5},{"category":"الرياضة","score":3},{"category":"التعليم","score":1.5}]','Updated','2026-10-07T21:00:46.018Z',200,75,0,'source_content_changed','',NULL,NULL,'body:8f275b937c6eeba66ae4e57d420b3abec3cb4c997f8a68077ab22087a0bfdd0e','Wed, 07 Oct 2026 21:00:44 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c8ab3f32-3855-4919-987d-1632f1dd66e8','news-c8ab3f32-3855-4919-987d-1632f1dd66e8','القبض على 3 إثيوبيين لتهريبهم 60 كيلوجرامًا من القات المخدر بعسير','القبض علي 3 اثيوبيين لتهريبهم 60 كيلوجراما من القات المخدر بعسير','ألقت الدوريات البرية لحرس الحدود في قطاع الربوعة ب منطقة عسير القبض على 3 مخالفين لنظام أمن الحدود من الجنسية الإثيوبية، لتهريبهم (60) كيلوجرامًا من نبات القات المخدر.','["وتم استكمال الإجراءات النظامية الأولية بحقهم، وتسليمهم والمضبوطات لجهة الاختصاص.","وتهيب الجهات الأمنية بالإبلاغ عن كل ما يتوافر من معلومات لدى المواطنين والمقيمين عن أي نشاطات ذات صلة بتهريب أو ترويج المخدرات، وذلك من خلال الاتصال بالأرقام (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض و الشرقية و(999) و(994) في بقية مناطق المملكة ، ورقم بلاغات المديرية العامة لمكافحة المخدرات (995)، وعبر البريد الإلكتروني: (Email: [email&#160;protected] )، وستعالج جميع البلاغات بسرية تامة دون أدنى مسؤولية…"]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/u5qs7kuwx','https://ajel.sa/local/u5qs7kuwx','https://ajel.sa/local/u5qs7kuwx','https://ajel.sa/local/u5qs7kuwx','فريق التحرير','الرياض','2026-08-27T05:11:00.000Z','Wed, 07 Oct 2026 21:00:46 GMT','2026-08-27T11:36:06.580Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Screenshot2026-08-27140114-crop-bvqIAr3a.png','/api/media/c8ab3f32-3855-4919-987d-1632f1dd66e8','/api/media/c8ab3f32-3855-4919-987d-1632f1dd66e8?variant=thumbnail','القبض على 3 إثيوبيين لتهريبهم 60 كيلوجرامًا من القات المخدر بعسير',1200,675,'valid','published','archived','valid',89,'c607c779480f64dbbc01f0afb486e5710d3cb7e5038e56f3d136660dedf399f2','0f2f1654d4aceb6fcae706727a2c7940dc9faabab402042e80eb8ad27241e2f7','محدّث','2026-08-27T11:36:06.580Z','2026-10-07T21:00:48.194Z','','',0,0,'saudi_region','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض","مكة","عسير","المدينة المنورة"]','["المدينة المنورة"]','classified','','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5}]','Updated','2026-10-07T21:00:48.194Z',200,73,0,'source_content_changed','',NULL,NULL,'body:3c231a8f28e893c566091baf026efc9798ca8b2479577e318fa35eebef444ee0','Wed, 07 Oct 2026 21:00:46 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7d9f18ca-8b1f-4998-94b5-b57a7cbda42f','news-7d9f18ca-8b1f-4998-94b5-b57a7cbda42f','ثقافي / خمس قصص تراثية تكشف جوانب من تاريخ العُلا العريق','ثقافي خمس قصص تراثيه تكشف جوانب من تاريخ العلا العريق','وتحتضن العُلا شواهد على وجود بشري يمتد إلى 200 ألف عام، إلى جانب تاريخ من الاستيطان يعود إلى ما لا يقل عن 7 آلاف عام، فيما تروي مواقعها الأثرية وموروثها الثقافي خمس قصص تكشف جوانب من هذا الامتداد التاريخي والتواصل الحضاري.','["العُلا 14 ربيع الأول 1448 هـ الموافق 27 أغسطس 2026 م واس ترسم العُلا عبر شواهدها الأثرية وتنوع موروثها الثقافي فصولًا متعاقبة من تاريخ الإنسان في شمال غرب الجزيرة العربية؛ إذ ارتبطت منذ القدم بطرق التجارة والتواصل، وتعاقبت على أرضها حضارات وممالك تركت إرثًا لا تزال تفاصيله حاضرة في المواقع الأثرية والنقوش والفنون والممارسات الاجتماعية.","وتبدأ أولى هذه القصص من الحِجر؛ حيث تقف المقابر النبطية المنحوتة في التكوينات الصخرية شاهدًا على مستوى متقدم من العمارة والنحت، وعلى ما شهدته المنطقة من تواصل مع حضارات العالم القديم, ويعد الحِجر أول موقع في المملكة العربية السعودية يدرج ضمن قائمة التراث العالمي لليونسكو، ويضم نحو 141 مقبرة، منها 93 مقبرة مزخرفة.","وتكشف واجهات المقابر عن تنوع في التأثيرات المعمارية والفنية؛ إذ مزج نحاتو الحجارة الأنباط بين الأفاريز ذات الطراز المصري، وزخارف بلاد الرافدين، والأقواس والأعمدة والتيجان اليونانية والرومانية الكلاسيكية، وصاغوها ضمن أسلوب نبطي مميز، بما يعكس براعة النحاتين وما شهدته المنطقة من تفاعل حضاري.","وتحمل شواهد الحِجر الأثرية آثار مراحل حضارية متعددة انعكست على العمارة والنقوش ومظاهر الحياة، بما يجسد مكانة الموقع ضمن طرق التجارة والتواصل التي ربطت شمال الجزيرة العربية بمحيطها عبر العصور."]','أخبار السعودية','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://www.spa.gov.sa/ar/N2662845?type=news&uuid=N2662845','https://www.spa.gov.sa/ar/N2662845?type=news&uuid=N2662845','N2662845','N2662845','','المدينة المنورة','2026-08-27T07:52:00.000Z',NULL,'2026-08-27T11:36:30.387Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10679340.jpeg','/api/media/7d9f18ca-8b1f-4998-94b5-b57a7cbda42f','/api/media/7d9f18ca-8b1f-4998-94b5-b57a7cbda42f?variant=thumbnail','ثقافي / خمس قصص تراثية تكشف جوانب من تاريخ العُلا العريق',1600,1108,'valid','published','archived','valid',50,'c65851973f3303ea220edb37c24968d1ea67c0e89e8a3bedea71a5780d3a54c3','5cd08aa71f7cd95c42b2da50ecb591c226bb4f6d3c43241b8d41f2d13065a80f',NULL,'2026-08-27T11:36:30.388Z','2026-10-07T21:00:52.756Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["المدينة المنورة","الاقتصاد والأسواق"]','["المدينة المنورة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"الثقافة","score":3},{"category":"التقنية","score":2}]','Active','2026-10-07T21:00:52.756Z',200,77,0,'source_article_available','',NULL,NULL,'body:dbdf9963644f64894991adbba04d461c2c3470aef7ba25f57005833e91df6388','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dc7104be-c5dc-4db3-9ebf-3dcaa4cf2527','news-dc7104be-c5dc-4db3-9ebf-3dcaa4cf2527','اقتصادي / 800 طن من التين الشوكي تعزز الإنتاج الزراعي في الباحة','اقتصادي 800 طن من التين الشوكي تعزز الانتاج الزراعي في الباحه','وأوضح مدير عام فرع وزارة البيئة والمياه والزراعة بمنطقة الباحة المهندس فهد مفتاح الزهراني أن الوزارة تعمل على تنمية زراعة التين الشوكي وتعزيز الاستفادة الاقتصادية منه، من خلال دعم المزارعين وتطوير منظومة الإنتاج، إلى جانب التوسع في الصناعات التحويلية المرتبطة بالمحصول، بما يسهم في زيادة قيمته المضافة وفتح مجالات أوسع للاستثمار فيه.','["الباحة 14 ربيع الأول 1448 هـ الموافق 27 أغسطس 2026 م واس يبرز التين الشوكي، المعروف محليًا بـ\"البرشومي\"، بوصفه أحد المحاصيل الزراعية الواعدة في منطقة الباحة، إذ يبلغ حجم إنتاجه نحو (800) طن سنويًا، على مساحة مزروعة تقدر بـ(15.2) هكتارًا، في مؤشر يعكس حضور المحصول ضمن منظومة الإنتاج الزراعي بالمنطقة، وما يحمله من فرص اقتصادية قابلة للتوسع في مجالات الإنتاج والتصنيع والتسويق.","وترتبط زراعة التين الشوكي بالبيئة الزراعية في الباحة، التي تتنوع تضاريسها بين المرتفعات الجبلية والأودية والسهول، وتنتشر فيها المدرجات الزراعية التي أسهمت على مدى عقود في تشكيل المشهد الزراعي للمنطقة، فيما يحضر \"البرشومي\" ضمن قائمة المحاصيل الموسمية التي تشتهر بها الباحة وتصل إلى الأسواق المحلية ومناطق أخرى من المملكة.","وبيّن أن الوزارة خصصت مبادرة لدعم زراعة التين الشوكي في المنطقة، شملت توفير خط إنتاج ومعصرة لاستخلاص الزيت يستفيد منها مزارعو المنطقة، إلى جانب العمل على تطوير منظومة متكاملة للاستفادة من المحصول ومكوناته، وعدم اقتصار العائد منه على تسويق الثمار الطازجة.","وتتعدد مجالات الاستفادة من التين الشوكي، إذ يمتد استخدامه إلى الصناعات الغذائية، واستخلاص الزيت من بذوره، والاستفادة منه في بعض منتجات العناية والتجميل، ما يمنح المحصول فرصًا للنمو في قطاع الصناعات التحويلية، ويعزز إمكانية إيجاد منتجات ذات قيمة اقتصادية أعلى ترتبط بالإنتاج الزراعي المحلي."]','الاقتصاد','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://www.spa.gov.sa/ar/N2662816?type=news&uuid=N2662816','https://www.spa.gov.sa/ar/N2662816?type=news&uuid=N2662816','N2662816','N2662816','','الباحة','2026-08-27T07:26:00.000Z','2026-08-27T10:26:00.000Z','2026-08-27T11:36:30.547Z','https://portalcdn.spa.gov.sa/backend/original/202608/F10679328.jpeg','/api/media/dc7104be-c5dc-4db3-9ebf-3dcaa4cf2527','/api/media/dc7104be-c5dc-4db3-9ebf-3dcaa4cf2527?variant=thumbnail','اقتصادي / 800 طن من التين الشوكي تعزز الإنتاج الزراعي في الباحة',1600,1065,'valid','published','archived','valid',91,'386277250433844616707166f952d40e013f934be5cbbeffd550b9679ee56107','a1ce90b5724db93aea5aace11bf9078636f09ac6f3b921db9b78b50cf26c3235','محدّث','2026-08-27T11:36:30.547Z','2026-10-07T21:00:52.935Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["الباحة","الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','classified','','[{"category":"المناطق","score":3},{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5}]','Active','2026-10-07T21:00:52.935Z',200,76,0,'source_article_available','',NULL,NULL,'body:1cbe40dd5afe5ec78fc1adcce0406fa70fcce4a2231ff490421737da39a5e6a8','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fc27ba74-93c6-4e71-bf08-8b4937d52c46','news-fc27ba74-93c6-4e71-bf08-8b4937d52c46','ضيوف مزعجون غابوا عن  صيف عسير والطائف  في 2026.. أين ذهبوا ؟','ضيوف مزعجون غابوا عن صيف عسير والطائف في 2026 اين ذهبوا','وينتشر البابون في عدد من مناطق غرب وجنوب غرب المملكة، من بينها عسير وجازان ونجران والباحة ومكة المكرمة والمدينة المنورة، خاصة على امتداد جبال السروات والحجاز.','["كان المشهد مألوفًا لسنوات على عدد من طرق جنوب وغرب المملكة: قرود البابون تنتشر على جوانب الطرق، تجلس فوق الحواجز الخرسانية، تقترب من السيارات، تنتظر الطعام من المارة، وأحيانًا تعبر الطريق بصورة مفاجئة أو تتجمع حول المركبات في مشهد كان يثير فضول البعض، لكنه تحول مع الوقت إلى مصدر إزعاج وقلق للسكان والمصطافين.","في عدد من المواقع والطرق التي كانت تُعرف بكثافة وجود القرود، تراجعت تلك المشاهد بصورة لافتة، وأصبحت تجمعات البابون أقل حضورًا بالقرب من الإنسان والسيارات مقارنة بما كان عليه الوضع قبل عدة سنوات.","الإجابة لا تعني أن القرود اختفت من جبال عسير أو جنوب المملكة؛ فهي أحد مكونات الحياة الفطرية في موائلها الطبيعية، وإنما تكمن القصة في برنامج استمر سنوات لإبعاد التجمعات المستأنسة عن الطرق والأحياء والمواقع السياحية، ومعالجة الأسباب التي دفعتها أصلًا إلى الاقتراب من الإنسان.","أسماء محلية متعددة ورغم شيوع الحديث عن «أنواع القرود» الموجودة في جنوب المملكة، فإن النوع الطبيعي المعروف في غرب وجنوب غرب الجزيرة العربية هو البابون المقدس أو Hamadryas baboon «Papio hamadryas»."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/2vz9mjl','https://sabq.org/article/2vz9mjl','','https://sabq.org/article/2vz9mjl','خالد خليل','مكة المكرمة','2026-08-27T05:35:00.000Z','2026-08-27T05:36:00.000Z','2026-08-27T13:44:10.191Z','https://media.sabq.org/news/2026/08/ea135599-19ed-400a-ba8e-1961a848feed/w1280.webp','/api/media/fc27ba74-93c6-4e71-bf08-8b4937d52c46','/api/media/fc27ba74-93c6-4e71-bf08-8b4937d52c46?variant=thumbnail','ضيوف مزعجون غابوا عن  صيف عسير والطائف  في 2026.. أين ذهبوا ؟',1280,720,'valid','published','archived','valid',93,'2690d7343c7be899b0b2cdc9fa497284fa56aeae621eb81a0e2f11dc79db970d','d5744095117c10884a085f2bf64299c8d9298d21ed640bf370092bd81d536220','محدّث','2026-08-27T11:42:07.246Z','2026-10-07T21:21:52.918Z','','',0,0,'saudi_region','مهم',69,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة المكرمة","الاقتصاد والأسواق","عسير"]','["مكة المكرمة","الاقتصاد والأسواق"]','classified','','[{"category":"المجتمع","score":7},{"category":"الاقتصاد","score":3},{"category":"السيارات","score":3}]','Active','2026-10-07T21:21:52.918Z',200,78,0,'source_article_available','',NULL,NULL,'body:087d7bd39310706ab2bd80d3b8a278e8a89acf4027906b680177352cff69087f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('30e5c5f4-d0d8-4dd6-86f2-af4c731e8296','news-30e5c5f4-d0d8-4dd6-86f2-af4c731e8296','«شور دلني الشرقية 2026» يحصد رقمًا قياسيًا عالميًا بـ523 استشارة','شور دلني الشرقيه 2026 يحصد رقما قياسيا عالميا بـ523 استشاره','وفي إنجاز عالمي، سجّل «شور دلني الشرقية 2026» رقمًا قياسيًا جديدًا في موسوعة غينيس للأرقام القياسية، بعد تقديم 523 استشارة متخصصة لتطوير المنشآت الناشئة خلال أقل من 8 ساعات في اليوم الأول، ليحقق بذلك أكبر عدد من استشارات تطوير المنشآت الناشئة المقدمة خلال هذه المدة على مستوى العالم.','["برعاية صاحب السمو الملكي الأمير سعود بن نايف بن عبدالعزيز، أمير المنطقة الشرقية، اختُتمت مساء الأربعاء 26 أغسطس 2026 فعاليات ملتقى «شور دلني الشرقية 2026»، الذي نظم بتعاون مشترك بين مركز دلني للأعمال، إحدى مبادرات بنك التنمية الاجتماعية، وغرفة الشرقية ممثلةً بمجلس شباب أعمال الشرقية، وذلك بمقر الغرفة.","وحضر ختام الملتقى رئيس مجلس إدارة غرفة الشرقية فهد بن عبدالله الفراج، ونائب الرئيس التنفيذي لقطاع الأعمال في بنك التنمية الاجتماعية عبدالله بن سعد الرويس، والمدير العام لمركز دلني للأعمال أسامة بن سليمان السلوم.","واستهدف الملتقى، الذي أقيمت فعالياته يومي الثلاثاء والأربعاء 25 و26 أغسطس، تمكين رواد الأعمال وأصحاب المنشآت الناشئة والصغيرة والمتوسطة، عبر توفير المشورة المتخصصة وربطهم بالخبرات النوعية، بما يسهم في دعم خطواتهم القادمة، وتطوير مشاريعهم، وتعزيز فرص نموها واستدامتها.","وتشرّفت غرفة الشرقية بإهداء هذا الإنجاز لراعي الملتقى صاحب السمو الملكي الأمير سعود بن نايف بن عبدالعزيز، أمير المنطقة الشرقية، عبر تقديم شهادة موسوعة غينيس للأرقام القياسية تقديرًا وعرفانًا لدعم سموه ورعايته الدائمة لشباب ورواد أعمال المنطقة."]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/op4uipm','https://sabq.org/article/op4uipm','','https://sabq.org/article/op4uipm','صحيفة سبق','المنطقة الشرقية','2026-08-27T05:34:00.000Z','2026-08-27T08:35:00.000Z','2026-08-27T11:42:07.276Z','https://media.sabq.org/news/2026/08/70c94fa7-3018-4a92-bdb7-0ded263adf12/w1600.webp','/api/media/30e5c5f4-d0d8-4dd6-86f2-af4c731e8296','/api/media/30e5c5f4-d0d8-4dd6-86f2-af4c731e8296?variant=thumbnail','«شور دلني الشرقية 2026» يحصد رقمًا قياسيًا عالميًا بـ523 استشارة',1600,1048,'valid','published','archived','valid',46,'5bb87dd166461d179bb1cbe310997c89baaaf743db3d783df6ce3e8cbc1b16d0','8e78b9eb28fb189e262d8987880e5b659835d7f7959fc932d411d9e6c791c665','محدّث','2026-08-27T11:42:07.276Z','2026-10-07T21:21:46.038Z','','',0,0,'saudi_region','مهم',67,NULL,0,0,0,'',NULL,NULL,NULL,'["المنطقة الشرقية","مجلس إدارة غرفة الشرقية فهد","رئيس مجلس إدارة غرفة الشرقية","الثقافة والفنون"]','["المنطقة الشرقية","مجلس إدارة غرفة الشرقية فهد","رئيس مجلس إدارة غرفة الشرقية","الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"التقنية","score":1.5},{"category":"السفر","score":1.5}]','Active','2026-10-07T21:21:46.038Z',200,77,0,'source_article_available','',NULL,NULL,'body:f399785603a88ccbaae58f0547761d9d43d3505009f1c20b36d62d1f9725b0f6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f74d7421-8034-4e53-b037-6e4f905961cd','news-f74d7421-8034-4e53-b037-6e4f905961cd','"العالمية للصحة الحيوانية" تُعلن اعتماد الخلو الذاتي للمملكة من مرض "الدورين" في الخيول','العالميه للصحه الحيوانيه تعلن اعتماد الخلو الذاتي للمملكه من مرض الدورين في الخيول','أعلنت المنظمة العالمية للصحة الحيوانية (WOAH) اعتماد الخلو الذاتي للمملكة رسميًا من مرض "الدورين" الذي يصيب الخيول، إثر استيفائها التام للأنظمة والمعايير القياسية المعتمدة عالميًا.','["وأوضحت أن هذا الاعتراف جاء نتيجة تقييم متكامل للملف الفني المقدم من المركز الوطني للوقاية من الآفات النباتية والأمراض الحيوانية ومكافحتها (وقاء)، الذي وثّق آليات التقصي الوبائي، ودقة المسوح الميدانية، والتدابير الاحترازية المحكمة المطبقة على مستوى مناطق المملكة .","ويؤكد هذا الاعتماد النجاح المتواصل للخطط الوطنية الإستراتيجية في حماية قطاع الخيل وتطوير المنظومة البيطرية، مما ينعكس إيجابًا على تحفيز استضافات البطولات الرياضية العالمية للفروسية، ودعم قطاع سباقات الخيل على أرض المملكة.","ويُبرز هذا التتويج الدولي المستوى المتقدم للخدمات البيطرية في المملكة، ويكرّس كفاءة الكوادر الوطنية وموثوقية إجراءاتها الوقائية للحد من الأمراض العابرة للحدود وتأمين الثروة الحيوانية."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/yjxdh8fso','https://ajel.sa/local/yjxdh8fso','https://ajel.sa/local/yjxdh8fso','https://ajel.sa/local/yjxdh8fso','فريق التحرير','الرياض','2026-08-27T05:35:00.000Z','Wed, 07 Oct 2026 19:33:44 GMT','2026-08-27T11:48:06.348Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-3v2bjVNs.jpg','/api/media/f74d7421-8034-4e53-b037-6e4f905961cd','/api/media/f74d7421-8034-4e53-b037-6e4f905961cd?variant=thumbnail','"العالمية للصحة الحيوانية" تُعلن اعتماد الخلو الذاتي للمملكة من مرض "الدورين" في الخيول',1200,675,'valid','published','archived','valid',56,'86f9c78c4afb9a035e121b304c781aa8c93e23ad43a5e4e092d756c41c0b9d48','3bdf3b743a1a369298fcfa6dd7b65b01d8006177bfc071758fb2ddd741a3c05c','محدّث','2026-08-27T11:48:06.348Z','2026-10-07T20:24:31.029Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض","الصحة العامة","الرياضة السعودية"]','["الصحة العامة","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الصحة","score":3},{"category":"العالم","score":3},{"category":"أخبار السعودية","score":1.5}]','Updated','2026-10-07T19:33:46.191Z',200,72,0,'source_content_changed','',NULL,NULL,'body:b3d5ffb88294be94307123247bd1f23fb5f7d5c5e670c313ae94d3b3cc1e4643','Wed, 07 Oct 2026 19:33:44 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1908e192-0ef9-41a1-8651-14ab6de4a3c0','news-1908e192-0ef9-41a1-8651-14ab6de4a3c0','أسعار الدولار والعملات الأجنبية مقابل الريال اليوم الخميس 14-3-1448','اسعار الدولار والعملات الاجنبيه مقابل الريال اليوم الخميس 14 3 1448','استقرت أسعار العملات الأجنبية مقابل الريال اليوم الخميس 14-3-1448؛ في البنك المركزي اليوم، حيث استقر سعر الريال مقابل الدولار الأميركي واليورو وبقية العملات الأجنبية الأخرى، فيما ارتفع سعر الدولار عالميًا بشكل طفيف.','["وفي البورصة العالمية، سجل مؤشر الدولار الأميركي مستوى 99.11 مقابل سلة من العملات الأجنبية على رأسها اليورو والإسترليني.","وجاء سعر الدولار مقابل الريال في البنك المركزي، اليوم الخميس 14-3-1448، وسعر العملات الأجنبية الأخرى كالآتي:","سعر الجنيه الإسترليني مقابل الريال، 5.09 ريال."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/z18zpcp4y','https://ajel.sa/thehour/z18zpcp4y','https://ajel.sa/thehour/z18zpcp4y','https://ajel.sa/thehour/z18zpcp4y','فريق التحرير','','2026-08-27T05:34:00.000Z','Wed, 07 Oct 2026 19:33:46 GMT','2026-08-27T11:48:06.799Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%B3%D8%B9%D8%B1-%D8%A7%D9%84%D8%B1%D9%8A%D8%A7%D9%84-2-YfuuRnD8.jpg','/api/media/1908e192-0ef9-41a1-8651-14ab6de4a3c0','/api/media/1908e192-0ef9-41a1-8651-14ab6de4a3c0?variant=thumbnail','أسعار الدولار والعملات الأجنبية مقابل الريال اليوم الخميس 14-3-1448',1200,675,'valid','published','archived','valid',99,'704aa2a07ac01c26cdab7d5bcc23e71e645943a5faa02586d646230e225b85e4','11c38f2d2e6df4008029a38a282cbd2cc7d1847bdfe1fc9d04d8176e8c76133f','محدّث','2026-08-27T11:48:06.799Z','2026-10-07T19:33:47.732Z','','',0,0,'international','عادي',43,NULL,0,0,0,'',NULL,NULL,NULL,'["البنك المركزي اليوم الخميس"]','["البنك المركزي اليوم الخميس"]','classified','','[{"category":"التقنية","score":6},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"العالم","score":1.5}]','Updated','2026-10-07T19:33:47.732Z',200,75,0,'source_content_changed','',NULL,NULL,'body:87ab0f92f63391408ae479e444bba78d18aba77ac503d3f3d9b3776521b39438','Wed, 07 Oct 2026 19:33:46 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('183ccaaf-afb9-422e-863b-f57265014339','news-183ccaaf-afb9-422e-863b-f57265014339','باريس تستضيف القمة العالمية للاستثمار 2026 بمشاركة أكثر من 80 خبيراً دولياً','باريس تستضيف القمه العالميه للاستثمار 2026 بمشاركه اكثر من 80 خبيرا دوليا','تستضيف العاصمة الفرنسية باريس القمة العالمية للاستثمار 2026، يومي 1 و2 سبتمبر، في قصر المؤتمرات، بمشاركة أكثر من 80 متحدثاً وخبيراً دولياً، وأكثر من 2000 مشارك، و40 لقاءً ثنائياً، ضمن برنامج يجمع مستثمرين وقادة أعمال ومسؤولين وممثلي كبرى الشركات والمؤسسات العالمية.','["يمتد برنامج القمة عبر مسرحين رئيسيين؛ المسرح الرئيسي ومسرح «أغورا»، ليتناول التحولات التي تشهدها حركة رأس المال والأسواق العالمية، ومستقبل الاستثمار في التقنية والطاقة والسياحة والصحة والاقتصاد الإبداعي والاستدامة، فضلاً عن القطاعات الناشئة التي تعيد تشكيل خريطة الفرص الاستثمارية عالمياً.","أبرز المشاركين في اليوم الأول يجمع المسرح الرئيسي في اليوم الأول نخبة من الشخصيات الاقتصادية والاستثمارية الدولية، في مقدمتهم سيلفيا بيبينو، الزميلة الزائرة الأولى في كلية لندن للاقتصاد والعلوم السياسية ومؤسسة GlobeEye، وبلانكا مورينو دودسون، المستشارة الأولى في الاقتصاد الدولي والمديرة السابقة في الأمم المتحدة وكبيرة الاقتصاديين السابقة في البنك الدولي، ومايك أوسوليفان، المستثمر والكاتب والخبير الاقتصادي في…","ويشارك أيضاً جوانا فياض، المديرة الأولى لاستراتيجية الأعمال وتحقيق القيمة في Oracle، وجيريمي إلياهو أونتيفيروس، المدير الإداري لأبحاث مراكز البيانات والطاقة والقطاعات الصناعية في SemiAnalysis، وأدريان بينيلي، المدير الإداري ورئيس علاقات المستثمرين في الشرق الأوسط والشؤون العامة العالمية لدى Eurazeo، وإيفان دو لاستور، شريك الاستثمار الجريء في Bpifrance، ودانيال فريدلاندر، نائب الرئيس الأول ورئيس أوروبا في CCIA.","ويضم اليوم الأول كذلك جيروم شالاندار، الرئيس التنفيذي للأعمال في Blue Bridge Group AI، وأرنو أمابيل، قائد المبادرات الاستراتيجية في H Company، ووائل النجيدي، شريك في EY Studio+، ومارتن برونكو، المؤسس والرئيس التنفيذي لشركة Schuman Financial AG، وأنييس ديالو، القيادية التنفيذية وعضوة مجلس الإدارة، إلى جانب معالي ماركو راغو، مستشار وزير الخارجية الإيطالي للدبلوماسية الاقتصادية والتنمية والمبعوث الخاص لسياسات المياه…"]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ejhf42v','https://sabq.org/article/ejhf42v','','https://sabq.org/article/ejhf42v','صحيفة سبق','الرياض','2026-08-27T05:41:00.000Z','2026-08-27T05:42:00.000Z','2026-08-27T13:50:10.792Z','https://media.sabq.org/news/2026/08/a6b9f7a2-b3ae-4666-8bb0-2c545b76e439/w680.webp','/api/media/183ccaaf-afb9-422e-863b-f57265014339','/api/media/183ccaaf-afb9-422e-863b-f57265014339?variant=thumbnail','باريس تستضيف القمة العالمية للاستثمار 2026 بمشاركة أكثر من 80 خبيراً دولياً',680,386,'valid','published','archived','valid',98,'d2b7d77e9fc8ffd29f9714503e57b1d22ef2001211b493cf8c1ad5313fa80bae','929a509567cfe909692abc88fcd6b8b4f92fafbac937a2e848efca48b30f6527','محدّث','2026-08-27T11:48:06.917Z','2026-10-07T19:33:32.488Z','','',0,0,'saudi_region','مهم',67,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض","مجلس الإدارة إلى جانب معالي","الأمم المتحدة وكبيرة الاقتصاديين السابقة","وزير الخارجية الإيطالي للدبلوماسية الاقتصادية","الصحة العامة","الطاقة والنفط","السفر والسياحة","الثقافة والفنون"]','["مجلس الإدارة إلى جانب معالي","الأمم المتحدة وكبيرة الاقتصاديين السابقة","وزير الخارجية الإيطالي للدبلوماسية الاقتصادية","الصحة العامة","الطاقة والنفط","السفر والسياحة"]','classified','','[{"category":"العالم","score":6},{"category":"السياسة","score":3.5},{"category":"الرياضة","score":3}]','Active','2026-10-07T19:33:32.488Z',200,75,0,'source_article_available','',NULL,NULL,'body:2840761b5b5668d786375c9e38afb592c37382e5e964e397b8a55bb05ba3925f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b3fee00f-f775-4753-9c45-a79097ff0417','news-b3fee00f-f775-4753-9c45-a79097ff0417','الرئيس الإيراني: لم نبدأ الحرب ودافعنا عن أنفسنا','الرئيس الايراني لم نبدا الحرب ودافعنا عن انفسنا','أكد الرئيس الإيراني مسعود بزشكيان، أن بلاده لم تبدأ الحرب في فبراير الماضي، موضحا أن الولايات المتحدة و إسرائيل شنتا حرباً على بلاده أثناء سير المفاوضات مع واشنطن».','["وأوضح خلال كلمة ألقاها خلال المؤتمر الدولي للوحدة الإسلامية في طهران : «نحن لم نبدأ الحرب ودافعنا عن أنفسنا».","كما أضاف أن إيران ليست ضعيفة وتعرف كيف تدافع عن نفسها، ولفت إلى أن الدفاع عن البلاد حق مشروع وليس عداء لدول الجوار، وقد استخدمت السلطات الإيرانية هذا الحق."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/lk192ifvf','https://ajel.sa/international/lk192ifvf','https://ajel.sa/international/lk192ifvf','https://ajel.sa/international/lk192ifvf','فريق التحرير','','2026-08-27T05:34:00.000Z','Wed, 07 Oct 202