INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bba51278-3d88-4eb3-b5aa-604293730d8d','news-bba51278-3d88-4eb3-b5aa-604293730d8d','سعر الريال مقابل الدولار والعملات الأجنبية اليوم السبت 16-3-1448','سعر الريال مقابل الدولار والعملات الاجنبيه اليوم السبت 16 3 1448','استقرت أسعار العملات الأجنبية مقابل الريال اليوم السبت 16-3-1448؛ في البنك المركزي اليوم، حيث استقر سعر الريال مقابل الدولار الأميركي واليورو وبقية العملات الأجنبية الأخرى، فيما ارتفع مؤشر الدولار عالميًا.','["وفي البورصة العالمية، سجل مؤشر الدولار الأميركي مستوى 99.64 مرتفعا بنسبة 0.55% مقابل سلة من العملات الأجنبية على رأسها اليورو والإسترليني في ختام تعاملات الأسبوع.","وجاء سعر الدولار مقابل الريال في البنك المركزي، اليوم السبت 16-3-1448، وسعر العملات الأجنبية الأخرى كالآتي:","سعر الجنيه الإسترليني مقابل الريال، 5.09 ريال.","سعر الريال مقابل البيزو الأرجنتيني، 0.003 ريال.","سعر الريال مقابل الروبية السريلانكية، 0.0121 ريال.","سعر الريال مقابل الروبية الإندونيسية، 0.0022 ريال.","سعر الريال مقابل الروبية الباكستانية، 0.0134 ريال."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/drc59xrew','https://ajel.sa/thehour/drc59xrew','https://ajel.sa/thehour/drc59xrew','https://ajel.sa/thehour/drc59xrew','فريق التحرير','','2026-08-29T00:19:00.000Z','Mon, 07 Sep 2026 04:41:24 GMT','2026-08-29T06:34:46.383Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%B3%D8%B9%D8%B1-%D8%A7%D9%84%D8%B1%D9%8A%D8%A7%D9%84-DTfx_JF3.webp','/api/media/bba51278-3d88-4eb3-b5aa-604293730d8d','/api/media/bba51278-3d88-4eb3-b5aa-604293730d8d?variant=thumbnail','سعر الريال مقابل الدولار والعملات الأجنبية اليوم السبت 16-3-1448',1200,675,'valid','published','archived','valid',41,'d77f5cc03d45d8980a5a7af97bb3ab70f2b032cfa5973a4ec20e46b00f96ccbe','b20dd68ae09d2adbde81505f33adfda3202503235f02d0d083549e16884c3e21','محدّث','2026-08-29T06:34:46.383Z','2026-10-07T20:24:31.941Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["البنك المركزي اليوم حيث استقر"]','["البنك المركزي اليوم حيث استقر"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:16:21.202Z',NULL,67,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a770af5e-8b7e-4df2-b877-a71e22793520','news-a770af5e-8b7e-4df2-b877-a71e22793520','متحدث هيئة الزكاة: جاهزية المنافذ الجمركية وتقنياتها وكوادرها المدربة تعزز التصدي لأساليب التهريب','متحدث هيئه الزكاه جاهزيه المنافذ الجمركيه وتقنياتها وكوادرها المدربه تعزز التصدي لاساليب التهريب','أكد متحدث هيئة الزكاة والضريبة والجمارك حمود الحربي، أهمية الجاهزية القائمة في المنافذ الجمركية. وأضاف الحربي، بمداخلة عبر قناة الإخبارية، أن جاهزية المنافذ الجمركية وتقنياتها الحديثة وكوادرها المدربة تعزز التصدي لأساليب التهريب وتحمي المجتمع من آفة المخدرات.','["أكد متحدث هيئة الزكاة والضريبة والجمارك حمود الحربي، أهمية الجاهزية القائمة في المنافذ الجمركية.","وأضاف الحربي، بمداخلة عبر قناة الإخبارية، أن جاهزية المنافذ الجمركية وتقنياتها الحديثة وكوادرها المدربة تعزز التصدي لأساليب التهريب وتحمي المجتمع من آفة المخدرات.","وتابع، أن جميع المنافذ البرية والبحرية والجوية على استعداد تام ولدينا تقنيات أمنية حديثة، مشيرا إلى أن الكوادر الوطنية لديها تدريب عال سواء من خلال التدريب على راس العمل أو الدورات التي يحصلون عليها، فضلا عن التعاون الدائم مع وزارة الداخلية والمديرية العامة لمكافحة المخدرات.","كانت هيئة الزكاة والضريبة والجمارك، أعلنت إحباط محاولة تهريب 1,950,581 حبة من مادة الإمفيتامين المخدرة، كانت مخبأة داخل إرسالية \"عدس\" محمولة على شاحنة قادمة إلى المملكة عبر منفذ الحديثة ."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/vlkh9m67u','https://ajel.sa/international/vlkh9m67u','https://ajel.sa/international/vlkh9m67u','https://ajel.sa/international/vlkh9m67u','فريق التحرير','','2026-08-29T00:16:00.000Z','Mon, 07 Sep 2026 04:41:24 GMT','2026-08-29T06:34:47.691Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-B3PLUkGc.jpg','/api/media/a770af5e-8b7e-4df2-b877-a71e22793520','/api/media/a770af5e-8b7e-4df2-b877-a71e22793520?variant=thumbnail','متحدث هيئة الزكاة: جاهزية المنافذ الجمركية وتقنياتها وكوادرها المدربة تعزز التصدي لأساليب التهريب',1200,675,'valid','published','archived','valid',40,'bf69fd2ab59e2105c3d8837832e20826f7fbca35c7f8766515e07a618fa19e59','719fa618cf3fe44a082192f159ecb3fdfa40f8752812a55e93da730c579921d0','محدّث','2026-08-29T06:34:47.691Z','2026-10-07T20:24:31.944Z','','',0,0,'saudi_national','أولوية قصوى',82,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الزكاة جاهزية المنافذ الجمركية","وزارة الداخلية والمديرية العامة لمكافحة","التعليم والتدريب"]','["هيئة الزكاة جاهزية المنافذ الجمركية","وزارة الداخلية والمديرية العامة لمكافحة","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:16:00.053Z',NULL,66,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5677ac86-d8b1-4ca9-8b54-1c67d58c018e','news-5677ac86-d8b1-4ca9-8b54-1c67d58c018e','سعر الذهب في السعودية اليوم السبت 16-3-1448 بعد هبوطه عالميًا','سعر الذهب في السعوديه اليوم السبت 16 3 1448 بعد هبوطه عالميا','وسجل سعر الذهب في البورصة العالمية اليوم السبت، نحو 4,455 دولارا للأوقية، متراجعا بنسبة 3.19%، في آخر سعر للإغلاق قبل بدء العطلة الأسبوعية للبورصة. وسجل سعر الذهب عيار 21 في المملكة، في مستهل التعاملات اليوم، السبت 469.99 ريال للجرام، فيما بلغ سعر الجرام في ختام التعاملات أمس الجمعة 483.68 ريال.','["تراجعت أسعار الذهب في السعودية اليوم السبت 16-3-1448 لكل الأعيرة؛ حيث تراجع سعر الذهب عيار 21 وبقية الأعيرة في مستهل التعاملات اليوم، بالتزامن مع الانخفاض الكبير في سعر المعدن الأصفر عالميا قبل ختام تعاملات الأسبوع.","وسجل سعر الذهب في البورصة العالمية اليوم السبت، نحو 4,455 دولارا للأوقية، متراجعا بنسبة 3.19%، في آخر سعر للإغلاق قبل بدء العطلة الأسبوعية للبورصة.","وسجل سعر الذهب عيار 21 في المملكة، في مستهل التعاملات اليوم، السبت 469.99 ريال للجرام، فيما بلغ سعر الجرام في ختام التعاملات أمس الجمعة 483.68 ريال.","وجاء سعر الذهب في السعودية اليوم السبت 16-3-1448 لكل الأعيرة كالآتي:","سعر الذهب في السعودية عيار 21 اليوم السبت، 469.99 ريال.","سعر الذهب في السعودية عيار 24 اليوم السبت، 537.13 ريال.","سعر الذهب في السعودية عيار 22 اليوم السبت، 492.37 ريال."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/nawzwx77b','https://ajel.sa/thehour/nawzwx77b','https://ajel.sa/thehour/nawzwx77b','https://ajel.sa/thehour/nawzwx77b','فريق التحرير','','2026-08-29T00:16:00.000Z','Wed, 07 Oct 2026 19:14:11 GMT','2026-08-29T06:34:48.536Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%B3%D8%B9%D8%B1-%D8%A7%D9%84%D8%B0%D9%87%D8%A8-jKKVfDTl.webp','/api/media/5677ac86-d8b1-4ca9-8b54-1c67d58c018e','/api/media/5677ac86-d8b1-4ca9-8b54-1c67d58c018e?variant=thumbnail','سعر الذهب في السعودية اليوم السبت 16-3-1448 بعد هبوطه عالميًا',1200,675,'valid','published','archived','valid',52,'b954b65d4233022808529a09b97c96b2e37f1227c25f6240dc8c50dfb5ad4817','5137743d869fb79ac911250c45c248a71968ee54f084a5af29e5f3832a192d83','محدّث','2026-08-29T06:34:48.536Z','2026-10-07T19:14:13.286Z','','',0,0,'saudi_national','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:14:13.286Z',200,63,0,'source_content_changed','',NULL,NULL,'body:7caffab758c993188bca1cef88cffa79cf507d72e683857b73e27bf6b351846e','Wed, 07 Oct 2026 19:14:11 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('639f9a5b-1fff-44ca-a329-878e6d6a4a50','news-639f9a5b-1fff-44ca-a329-878e6d6a4a50','مديرة صندوق النقد الدولي: الاقتصاد العالمي لا يزال يبدي قدراً من المرونة','مديره صندوق النقد الدولي الاقتصاد العالمي لا يزال يبدي قدرا من المرونه','وكانت جورجييفا، حثت لحكومات على معالجة التحديات المالية المتزايدة، داعية البنوك المركزية إلى مواصلة التزامها بخفض التضخم، في وقت يواجه فيه الاقتصاد العالمي ضغوطاً متنامية.','["قالت مديرة صندوق النقد الدولي ، كريستالينا جورجييفا، إن الاقتصاد العالمي لا يزال يبدي قدراً من المرونة.","وأضافت، بتصريحات لـ « بلومبيرج »، أن قوة الدولار الأمريكي تُعد انعكاساً لقوة اقتصاد الولايات المتحدة ، وتابعت «يجب أن نتقبل الواقع بأن العالم يتغير بشكل سريع».","وأكملت، أن رئيس الفيدرالي كيفن وارش يؤدي عملاً رائعاً وعرض وجهات نظره بوضوح، وشارت إلى أن الابتكار المالي جيد لكنه يزيد من المخاطر."]','الاقتصاد','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/cvhu67dp2','https://ajel.sa/economy/cvhu67dp2','https://ajel.sa/economy/cvhu67dp2','https://ajel.sa/economy/cvhu67dp2','فريق التحرير','','2026-08-29T00:49:00.000Z','Wed, 07 Oct 2026 19:34:48 GMT','2026-08-29T07:05:45.537Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-9qkkuTJI.jpg','/api/media/639f9a5b-1fff-44ca-a329-878e6d6a4a50','/api/media/639f9a5b-1fff-44ca-a329-878e6d6a4a50?variant=thumbnail','مديرة صندوق النقد الدولي: الاقتصاد العالمي لا يزال يبدي قدراً من المرونة',1200,675,'valid','published','archived','valid',41,'20d183c8d6d8a5f1eebdef32b1e7dfa65b967c2e213979f1471aa1548839beb6','7b9891b4130941f6b24cee826c9b342b1f12ee85a38626a3d83a2fdbc6ae6285','محدّث','2026-08-29T07:05:45.538Z','2026-10-07T20:24:31.949Z','','',0,0,'international','عادي',39,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","رئيس الفيدرالي كيفن وارش يؤدي","الاقتصاد والأسواق","الولايات المتحدة"]','["رئيس الفيدرالي كيفن وارش يؤدي","الاقتصاد والأسواق","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:34:50.163Z',200,60,0,'source_content_changed','',NULL,NULL,'body:986763b2da1e6beec725affcc50467e55c1445e543e5eeecbc09529a9644ea56','Wed, 07 Oct 2026 19:34:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('582b186c-d913-4ab4-90d1-d802f7ec23bd','news-582b186c-d913-4ab4-90d1-d802f7ec23bd','كاتب: إنشاء مركز ثقافي سعودي في باريس يعزز التعريف بالإرث الحضاري للمملكة وعمقها التاريخي','كاتب انشاء مركز ثقافي سعودي في باريس يعزز التعريف بالارث الحضاري للمملكه وعمقها التاريخي','قال الكاتب الثقافي عبد الله الحسني، إن إنشاء مركز ثقافي سعودي في باريس يعزز التعريف بالإرث الحضاري للمملكة وعمقها التاريخي والثقافي أمام الجمهور الفرنسي والعالمي.','["وأضاف خلال مداخلة مع قناة «الإخبارية» أن هذه الخطوة تأتي ترجمة لجهود وزارة الثقافة ، وتتويجا لهذه الجهود العظيمة التي تبذلها الوزارة، وهي خطوة لها دلالة رمزية وإستراتيجية.","وكانت قد أعلنت وزارة الثقافة، قبل عدة أيام، عن إنشاء مركز ثقافي سعودي في العاصمة الفرنسية باريس، وذلك على هامش زيارة صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود، ولي العهد رئيس مجلس الوزراء -حفظه الله- إلى الجمهورية الفرنسية ."]','الثقافة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/7e62djnln','https://ajel.sa/local/7e62djnln','https://ajel.sa/local/7e62djnln','https://ajel.sa/local/7e62djnln','فريق التحرير','','2026-08-29T00:40:00.000Z','Wed, 07 Oct 2026 19:34:50 GMT','2026-08-29T07:05:47.630Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%83%D8%A7%D8%AA%D8%A8-%D8%AB%D9%82%D8%A7%D9%81%D9%8A-2Jx3M4uf.jpg','/api/media/582b186c-d913-4ab4-90d1-d802f7ec23bd','/api/media/582b186c-d913-4ab4-90d1-d802f7ec23bd?variant=thumbnail','كاتب: إنشاء مركز ثقافي سعودي في باريس يعزز التعريف بالإرث الحضاري للمملكة وعمقها التاريخي',1200,675,'valid','published','archived','valid',58,'44ab3ca0d67bd517475b8a684fef2ff841dfb6468d510113d2b7f52674a9abe6','f7ae8cd84dabe26a1f4a3e884e68260bfbe2726481fe565714df393ce1841f6d','محدّث','2026-08-29T07:05:47.630Z','2026-10-07T20:24:31.953Z','','',0,0,'saudi_national','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء -حفظه الله- إلى","رئيس مجلس الوزراء -حفظه الله-","وزارة الثقافة وتتويجا لهذه الجهود","الثقافة والفنون"]','["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء -حفظه الله- إلى","رئيس مجلس الوزراء -حفظه الله-","وزارة الثقافة وتتويجا لهذه الجهود","الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:34:52.340Z',200,62,0,'source_content_changed','',NULL,NULL,'body:791ffc005e11ff5a8f171bc4966e5dc77a94273aaad5abc3e61636e4b34578f0','Wed, 07 Oct 2026 19:34:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e5c7225e-144f-499b-9d92-587e7f4a0aa0','news-e5c7225e-144f-499b-9d92-587e7f4a0aa0','أكاديمية: ملتقى أبحاث الحج والعمرة منصة بحثية تستعرض توظيف التقنيات لخدمة ضيوف الرحمن','اكاديميه ملتقي ابحاث الحج والعمره منصه بحثيه تستعرض توظيف التقنيات لخدمه ضيوف الرحمن','سمية شرف، وكيلة معهد البحوث والدراسات ب جامعة أم القرى ، إن الملتقى العلمي لأبحاث الحج والعمرة والزيارة منصة بحثية وابتكارية تستعرض توظيف الذكاء الاصطناعي والتقنية في تطوير خدمات ضيوف الرحمن وتحسين إدارة الحشود.','["وأضافت خلال مداخلة مع قناة «الإخبارية» أن الهدف من الفعاليات المصاحبة للمتلقى، التنبؤ بالحلول الابتكارية في إدارة الحشود وتقديم الخدمات الصحية والإسعافية وخدمات النقل ورفع كفاءة السلامة والإرشاد المكاني.","وتنظّم جامعة أم القرى الملتقى العلمي السادس والعشرين لأبحاث الحج والعمرة والزيارة، خلال الفترة من 20 إلى 21 ربيع الأول 1448هـ، الموافق 2 إلى 3 سبتمبر 2026م، تحت رعاية خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود -حفظه الله-، وذلك بقاعة الملك عبدالعزيز التاريخية بالمدينة الجامعية بالعابدية."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/sr2vd0f6g','https://ajel.sa/local/sr2vd0f6g','https://ajel.sa/local/sr2vd0f6g','https://ajel.sa/local/sr2vd0f6g','فريق التحرير','','2026-08-29T00:40:00.000Z','Wed, 07 Oct 2026 19:34:52 GMT','2026-08-29T07:05:48.152Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D9%85%D8%B3%D8%AC%D8%AF-%D8%A7%D9%84%D8%AD%D8%B1%D8%A7%D9%85-pHZrfNER.jpg','/api/media/e5c7225e-144f-499b-9d92-587e7f4a0aa0','/api/media/e5c7225e-144f-499b-9d92-587e7f4a0aa0?variant=thumbnail','أكاديمية: ملتقى أبحاث الحج والعمرة منصة بحثية تستعرض توظيف التقنيات لخدمة ضيوف الرحمن',1200,675,'valid','published','archived','valid',55,'6fd7be3d36ceb2d37b38e7a9a0cec3fdfa3628e2aea843be41c7c009d48ce4e6','f5f9cb381e74f7e00d75b0d7f39e068dd01a4e145e1b9799d5c4557c9ae898e3','محدّث','2026-08-29T07:05:48.152Z','2026-10-07T19:34:54.526Z','','',0,0,'saudi_national','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة أم القرى إن الملتقى","خادم الحرمين الشريفين الملك سلمان","التعليم والتدريب","التقنية والتحول الرقمي"]','["جامعة أم القرى إن الملتقى","خادم الحرمين الشريفين الملك سلمان","التعليم والتدريب","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":4.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:34:54.526Z',200,53,0,'source_content_changed','',NULL,NULL,'body:5f627987e93a68d74de0ffa7d4dd3191eaee6d88932dc430b842a1f3764e990b','Wed, 07 Oct 2026 19:34:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a93c4b95-8762-4159-ab83-0e3d9fd2e82b','news-a93c4b95-8762-4159-ab83-0e3d9fd2e82b','تراجع أسعار الذهب في المملكة.. وعيار 21 يسجل 469 ريالا','تراجع اسعار الذهب في المملكه وعيار 21 يسجل 469 ريالا','شهدت أسعار الذهب في المملكة ، تراجعا خلال تعاملات اليوم، حيث سجل الجرام من عيار 21، الأكثر تداولًا بالمملكة، نحو 469.99، ريال (125.33 دولار) وسجل سعر الجرام عيار 24 نحو 537.13 ريال، وعيار 22 نحو (492.37) ريال، وعيار 18 (402.85) ريال، وسجل الجرام عيار 14 نحو (313.32)، بحسب ما نشرت منصة سعودي جولد.','["شهدت أسعار الذهب في المملكة ، تراجعا خلال تعاملات اليوم، حيث سجل الجرام من عيار 21، الأكثر تداولًا بالمملكة، نحو 469.99، ريال (125.33 دولار)","وسجل سعر الجرام عيار 24 نحو 537.13 ريال، وعيار 22 نحو (492.37) ريال، وعيار 18 (402.85) ريال، وسجل الجرام عيار 14 نحو (313.32)، بحسب ما نشرت منصة سعودي جولد."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/n4q3ustpe','https://ajel.sa/economy/n4q3ustpe','https://ajel.sa/economy/n4q3ustpe','https://ajel.sa/economy/n4q3ustpe','فريق التحرير','','2026-08-29T01:31:00.000Z','Wed, 07 Oct 2026 20:52:47 GMT','2026-08-29T07:50:46.614Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%B0%D9%87%D8%A8-3-YndtaaaA.jpg','/api/media/a93c4b95-8762-4159-ab83-0e3d9fd2e82b','/api/media/a93c4b95-8762-4159-ab83-0e3d9fd2e82b?variant=thumbnail','تراجع أسعار الذهب في المملكة.. وعيار 21 يسجل 469 ريالا',1200,675,'valid','published','archived','valid',46,'744f886f8ad4686bb0bb3b70e6c55353d15345f71e2575479c4a1a1db16f3657','7b1c2ea7c74e9d261bdcbc1e516fad95861557a392ba190325630fa99d34f564','محدّث','2026-08-29T07:50:46.614Z','2026-10-07T20:52:48.551Z','','',0,0,'saudi_national','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:52:48.551Z',200,61,0,'source_content_changed','',NULL,NULL,'body:67efee56fdda1fff806d1c4fbf916b50565ac7b7c428b8b85d0f7c6b779b9e53','Wed, 07 Oct 2026 20:52:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ca3ac801-f13b-44c8-a5aa-52b807fe1339','news-ca3ac801-f13b-44c8-a5aa-52b807fe1339','المرور يحذر من تطاير حمولة الشاحنات على الطرق','المرور يحذر من تطاير حموله الشاحنات علي الطرق','وشدّدت الإدارة على أهمية التأكد من سلامة تثبيت الحمولة وعدم تجاوزها الحدود المسموح بها، بما يسهم في تعزيز السلامة المرورية والحد من المخاطر المرتبطة بسقوط أو تطاير المواد أثناء التنقل.','["دعت الإدارة العامة للمرور قائدي الشاحنات إلى ضرورة تثبيت الحمولة بإحكام قبل السير على الطرق، مؤكدة أن تطاير الحمولة يشكل خطرًا على سلامة مستخدمي الطريق وقد يتسبب في وقوع حوادث مرورية.","وأكدت أن الالتزام بمتطلبات السلامة عند نقل الحمولة يُعد من الممارسات الأساسية للحفاظ على سلامة السائقين ومستخدمي الطريق، ضمن جهودها المستمرة لتعزيز الوعي المروري والوقاية من الحوادث."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/WMX-tVx','https://sabq.org/article/WMX-tVx','','https://sabq.org/article/WMX-tVx','صحيفة سبق','','2026-08-29T01:54:00.000Z','2026-08-29T04:55:00.000Z','2026-08-29T07:59:46.307Z','https://media.sabq.org/news/2026/08/6c52406b-c579-46e8-83b3-3d4a9db93c68/w680.webp','/api/media/ca3ac801-f13b-44c8-a5aa-52b807fe1339','/api/media/ca3ac801-f13b-44c8-a5aa-52b807fe1339?variant=thumbnail','المرور يحذر من تطاير حمولة الشاحنات على الطرق',680,680,'valid','published','archived','valid',47,'e0bc3e448b8aa9504c0790e71730de5e254eaa4f417876fea318e4a3822cb01a','bf3c2c4d3161105b84a33e02a617727dde38c843511e8b2c361d3f068d4be274','محدّث','2026-08-29T07:59:46.307Z','2026-10-07T21:07:59.488Z','','',0,0,'international','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:07:59.488Z',200,63,0,'source_article_available','',NULL,NULL,'body:d063514152c952db926bd8ab03b8b8d448fa2869058a5435bfa39db8321be60f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8261846a-a240-4046-a92f-e3f47e4b1c91','news-8261846a-a240-4046-a92f-e3f47e4b1c91','خبراء: 4 أنواع أسماك تتصدر  المأكولات البحرية بفوائدها الصحية','خبراء 4 انواع اسماك تتصدر الماكولات البحريه بفوائدها الصحيه','حدد خبراء تغذية، أفضل أربعة أنواع من الأسماك تتصدر الأفضلية بين المأكولات البحرية، للصحة وإنقاص الوزن. ويشمل ذلك أسماك الماكريل وتعد من المصادر الغنية بأحماض "أوميغا-3"، وفيتامين بي 12، وفق " روسيا اليوم ".','["حدد خبراء تغذية، أفضل أربعة أنواع من الأسماك تتصدر الأفضلية بين المأكولات البحرية، للصحة وإنقاص الوزن.","ويشمل ذلك أسماك الماكريل وتعد من المصادر الغنية بأحماض \"أوميغا-3\"، وفيتامين بي 12، وفق \" روسيا اليوم \".","كما تتميز أسماك القد بانخفاض الدهون وارتفاع البروتين، ما يجعلها خيارا مناسبا لمن يرغبون في خفض السعرات الحرارية.","كذلك يوفر سمك القاروص كمية جيدة من البروتين و\"أوميغا-3\"، ما يجعله خيارا مناسبا لمن يفضلون الأسماك البيضاء، كما يحتوي على \"أوميغا-3\" أكثر من بعض الأنواع البيضاء الأخرى، مع الحذر من احتوائه على مستويات عالية من الزئبق.","أيضا يجمع السلمون بين البروتين المرتفع والدهون الغنية بأحماض \"أوميغا-3\"، ما يجعله من أبرز الخيارات الغذائية ضمن الأسماك الدهنية."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/n10vztrl1','https://ajel.sa/misc/n10vztrl1','https://ajel.sa/misc/n10vztrl1','https://ajel.sa/misc/n10vztrl1','فريق التحرير','','2026-08-29T01:55:00.000Z','Wed, 07 Oct 2026 21:11:50 GMT','2026-08-29T08:12:28.520Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-iRKn8P-Q.png','/api/media/8261846a-a240-4046-a92f-e3f47e4b1c91','/api/media/8261846a-a240-4046-a92f-e3f47e4b1c91?variant=thumbnail','خبراء: 4 أنواع أسماك تتصدر المأكولات البحرية بفوائدها الصحية',1200,675,'valid','published','archived','valid',41,'b07b66b480dd42ab2e13648f9734e9959cf64cca3dad446e15d8107f22034fe8','c472008df9a0377f4eeca44e010cc2ef604b7d764593fddf5d8bfa94fad3b95b','محدّث','2026-08-29T08:12:28.520Z','2026-10-07T21:11:51.623Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","روسيا"]','["الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:11:51.623Z',200,64,0,'source_content_changed','',NULL,NULL,'body:44d99c7082302aecf4fb996d0a02e63ad205047237ccdbde80d8025664fc3e2a','Wed, 07 Oct 2026 21:11:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0b6d4bb8-895c-457b-a238-8006e77251b5','news-0b6d4bb8-895c-457b-a238-8006e77251b5','ميدان الهجن بنجران يُسدل الستار على سباق سنّ «اللقايا» بـ9 أشواط','ميدان الهجن بنجران يسدل الستار علي سباق سن اللقايا بـ9 اشواط','اختتم ميدان الهجن بمنطقة نجران سباق سنّ «اللقايا»، الذي شهد منافسات متميزة على مدى 9 أشواط بمسافة 4 كيلومترات لكل شوط. وقد هيمن المالك نواف أبو ساق ونجله نواف محمد أبو ساق على غالبية أشواط السباق، إذ حصدا بين الاثنين 7 مراكز أولى من أصل 9 أشواط.','["اختتم ميدان الهجن بمنطقة نجران سباق سنّ «اللقايا»، الذي شهد منافسات متميزة على مدى 9 أشواط بمسافة 4 كيلومترات لكل شوط.","وجاءت نتائج الأشواط التسعة على النحو التالي: - الشوط الأول: البكرة «قياده» للمالك نواف أبو ساق. - الشوط الثاني: القعود «الجذاب» للمالك هادي العجمي. - الشوط الثالث: البكرة «النادرة» للمالك نواف محمد أبو ساق. - الشوط الرابع: القعود «الزعيم» للمالك نواف أبو ساق. - الشوط الخامس: البكرة «شواهين» للمالك صالح الكربي. - الشوط السادس: القعود «هداد» للمالك نواف أبو ساق. - الشوط السابع: البكرة «الجزيرة» للمالك نواف محمد أبو ساق. - الشوط الثامن: البكرة «المجرة» للمالك نواف أبو ساق. - الشوط التاسع والأخير: البكرة «دهشة» للمالك نواف محمد أبو ساق.","وقد هيمن المالك نواف أبو ساق ونجله نواف محمد أبو ساق على غالبية أشواط السباق، إذ حصدا بين الاثنين 7 مراكز أولى من أصل 9 أشواط."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/mkZJw73','https://sabq.org/article/mkZJw73','','https://sabq.org/article/mkZJw73','صحيفة سبق','نجران','2026-08-29T02:05:00.000Z','2026-08-29T05:05:00.000Z','2026-08-29T08:12:36.566Z','https://media.sabq.org/news/2026/08/104e702b-0994-42eb-a60f-aa31544fb7f2/w570.webp','/api/media/0b6d4bb8-895c-457b-a238-8006e77251b5','/api/media/0b6d4bb8-895c-457b-a238-8006e77251b5?variant=thumbnail','ميدان الهجن بنجران يُسدل الستار على سباق سنّ «اللقايا» بـ9 أشواط',570,350,'valid','published','archived','valid',47,'e85d333686ec151e16f5db74df045c0d19f8c6de25cffc8ef4cb73c12732df42','3747e3ceffa031c2bbe7f0ba602778d8a6bf259d127ee2c2061905a4acddde32','محدّث','2026-08-29T08:12:36.566Z','2026-10-07T21:11:43.451Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["نجران"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:11:43.451Z',200,59,0,'source_article_available','',NULL,NULL,'body:8bbec79aa55d74618e576f1fed9b04ec0d7eaeb8f7bba1d541dcfffc227ebcf7','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('762f0e53-be5c-49c1-9ed9-e7f7fde1d26f','news-762f0e53-be5c-49c1-9ed9-e7f7fde1d26f','وزارة الصحة: السكر البني لا يختلف عن الأبيض في السعرات الحرارية','وزاره الصحه السكر البني لا يختلف عن الابيض في السعرات الحراريه','وأوضحت المنصة أن السكر البني يُصنَّف ضمن السكريات المضافة التي تمنح سعرات حرارية مماثلة لنظيره الأبيض، مما يستوجب الحد من استهلاك النوعين معاً تفادياً للآثار الصحية الناجمة عن الإفراط في تناول السكر.','["نفت منصة «عش بصحة» التابعة لوزارة الصحة الاعتقاد الشائع بأن السكر البني خيار صحي مقارنة بالسكر الأبيض، مؤكدةً أن كلا النوعين متقاربان في السعرات الحرارية، وأن اختلاف اللون لا يُشكّل أي أفضلية صحية.","وأوصت المنصة بألا يتجاوز استهلاك الشخص البالغ 50 غراماً يومياً من السكر، ما يعادل نحو 3 ملاعق طعام، شاملاً السكريات المضافة أثناء الطهي، وذلك تعزيزاً للخيارات الغذائية الصحية والحد من مخاطر ارتفاع نسبة السكر في النظام الغذائي."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ad1zfN9','https://sabq.org/article/ad1zfN9','','https://sabq.org/article/ad1zfN9','صحيفة سبق','','2026-08-29T02:01:00.000Z','2026-08-29T05:03:00.000Z','2026-08-29T08:13:17.676Z','https://media.sabq.org/news/2026/08/0e8e53dd-17f3-4b94-a910-1bd20ede65b1/w800.webp','/api/media/762f0e53-be5c-49c1-9ed9-e7f7fde1d26f','/api/media/762f0e53-be5c-49c1-9ed9-e7f7fde1d26f?variant=thumbnail','وزارة الصحة: السكر البني لا يختلف عن الأبيض في السعرات الحرارية',800,533,'valid','published','archived','valid',35,'c8b9c62e7a943dfcbff3ef795ab62c2ae138553e766a8371eb2712e7a1ff50ee','00ebc58fd0bd261a6b6ef1cb910bd454338570e36f238de33556615197d5a555','محدّث','2026-08-29T08:13:17.676Z','2026-10-07T21:11:40.440Z','','',0,0,'international','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الصحة السكر البني لا","الصحة العامة"]','["وزارة الصحة السكر البني لا","الصحة العامة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:11:40.440Z',200,64,0,'source_article_available','',NULL,NULL,'body:924eb36853b55a0e02a3d11cc51fab510349744bbe3ca1c67e59d9383686e6e6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('48184bc9-a726-4d40-9d1b-a6f67df9f95e','news-48184bc9-a726-4d40-9d1b-a6f67df9f95e','جلسات دولية ترسم تحولات الاستثمار والتقنية في القمة العالمية للاستثمار بباريس 2026','جلسات دوليه ترسم تحولات الاستثمار والتقنيه في القمه العالميه للاستثمار بباريس 2026','تستضيف العاصمة الفرنسية باريس القمة العالمية للاستثمار 2026، يومي 1 و2 سبتمبر، في قصر المؤتمرات، بمشاركة أكثر من 2000 مستثمر وقائد أعمال وخبير دولي، في منصة جامعة للحوار وبناء الشراكات الاستثمارية العابرة للحدود.','["يضم البرنامج جلسات حوارية ونقاشات متخصصة عبر مسرحين رئيسيين؛ المسرح الرئيسي ومسرح أغورا، تغطي ملفات الاقتصاد العالمي، والذكاء الاصطناعي، والطاقة، والمناخ، والصحة، ورأس المال الجريء، والتقنيات العميقة، والاقتصاد الثقافي والإبداعي، إضافة إلى السياحة والضيافة والرياضة.","اليوم الأول — المسرح الرئيسي يفتتح المسرح الرئيسي أعماله بالجلسة الاقتصادية الرئيسة «التمويل متعدد الأقطاب: إلى أين تتجه الثروات غدًا؟»، التي تتناول تحولات حركة رأس المال بين الأسواق العالمية، تليها جلسة «سيادة الذكاء الاصطناعي: بناء البنية التحتية للاستقلال الاستراتيجي»، ثم «أوروبا تقود نشر التقنيات: الذكاء الاصطناعي على نطاق واسع في الاقتصاد الحقيقي».","ويواصل المسرح برنامجه بجلسات «ما الذي يتيحه ترميز الأصول لأوروبا ومنطقة الخليج؟»، و«وضع الإنسان في صميم المستقبل الرقمي لأوروبا»، فضلاً عن ثلاث جلسات مخصصة للمناخ تشمل «المناخ والدبلوماسية البيئية الجديدة»، و«المناخ والاستدامة وأجندة الاستثمار الأخضر»، و«الحفاظ على جاذبية الاستثمار المناخي: تحول الطاقة والنهضة النووية».","اليوم الأول — مسرح أغورا يخصص مسرح أغورا مساحة للموضوعات التقنية والاستثمارية المتخصصة، تبدأ بجلسة «سباق السيادة القادم: الحوسبة الكمية»، تليها «المياه: البنية التحتية الخفية لعصر الذكاء الاصطناعي»، و«ممر رأس المال الجريء: فرنسا والخليج والمؤسسون الساعون إلى جمع التمويل بينهما»، إضافة إلى جلسة «القيمة الإنسانية — القيادة الموثوقة في عالم مؤتمت»، وجلسة «تمويل التقنيات الإبداعية في أوروبا: ما الذي يبحث عنه المستثمرون الملائكيون؟».","اليوم الثاني — المسرح الرئيسي يبدأ اليوم الثاني بجلسة «الجغرافيا الجديدة لرأس المال الموجّه إلى الوجهات»، تليها «ما بعد الحدث: الإرث الاقتصادي والاجتماعي والبيئي للفعاليات الرياضية الكبرى»، و«الاقتصاد الثقافي والإبداعي: حيث يلتقي التراث بالاستثمار»، و«الاقتصاديات الجديدة لقطاع المنتجات الفاخرة».","ويتواصل البرنامج بجلسات «التقنيات المتقدمة وتحديات التمويل: مَن يمول إعادة التصنيع؟»، و«الذكاء الاصطناعي والنموذج الجديد لتمويل تطوير العلاجات»، و«السيادة الصحية: التصنيع المحلي والتقنية الحيوية والصحة الرقمية»، وتختتم بجلسة «سباق القدرات الحاسوبية للذكاء الاصطناعي بقيمة تريليون دولار».","اليوم الثاني — مسرح أغورا يستكمل مسرح أغورا مناقشة القطاعات الجديدة عبر جلسات تشمل «الابتكارات في قطاعات الترفيه والرياضة والضيافة والرفاهية»، و«الاستثمار في الإنسان لحماية رأس المال الطبيعي»، و«العيادة الاستثمارية للتقنية الحيوية»، و«تمويل ما لم تثبت جدواه بعد: دعم التقنيات العميقة»، وصولاً إلى «الخوارزمية الإنسانية: الحقوق والمهارات والانتماء في المدينة الحديثة».","وتستهدف القمة توسيع الحوار حول الفرص الاستثمارية العالمية، وربط رؤوس الأموال بالقطاعات الواعدة، وتعزيز الشراكات الدولية، من خلال لقاءات ثنائية تجمع المستثمرين وقادة الأعمال وممثلي المؤسسات والشركات الكبرى."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/2EpWjeP','https://sabq.org/article/2EpWjeP','','https://sabq.org/article/2EpWjeP','صحيفة سبق','الرياض','2026-08-29T01:59:00.000Z','2026-08-29T02:15:00.000Z','2026-08-29T12:34:51.329Z','https://media.sabq.org/news/2026/08/2d2e0ec3-212b-43d6-9ac7-d1a27619285b/w1600.webp','/api/media/48184bc9-a726-4d40-9d1b-a6f67df9f95e','/api/media/48184bc9-a726-4d40-9d1b-a6f67df9f95e?variant=thumbnail','جلسات دولية ترسم تحولات الاستثمار والتقنية في القمة العالمية للاستثمار بباريس 2026',1600,900,'valid','published','archived','valid',46,'0bdb4260a8a7de5be5c9138bf735dc663fbe0d477a743eb02027948af1294f2c','52fc7aa5be157a12393feb547d15e650623e401ebd980fee1561581d04e74cf0','محدّث','2026-08-29T08:13:17.686Z','2026-10-07T21:11:44.344Z','','',0,0,'saudi_region','مهم',63,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة للحوار وبناء الشراكات الاستثمارية","الصحة العامة","الطاقة والنفط","الطقس والمناخ","السفر والسياحة","الثقافة والفنون","الذكاء الاصطناعي","التعليم والتدريب"]','["جامعة للحوار وبناء الشراكات الاستثمارية","الصحة العامة","الطاقة والنفط","الطقس والمناخ","السفر والسياحة","الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"الرياضة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:11:44.344Z',200,62,0,'source_article_available','',NULL,NULL,'body:6f1b82a4e9ec3b05ebeb8b670f16979720d3f07007bf00bc0cdbf85a8cd7a3b0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('57bc73b8-1305-40be-81cb-aa1da88b7c90','news-57bc73b8-1305-40be-81cb-aa1da88b7c90','استشاري قلب يحذر: التهاب الروماتويد النشط يرفع مخاطر مضاعفات القلب 60%','استشاري قلب يحذر التهاب الروماتويد النشط يرفع مخاطر مضاعفات القلب 60','حذّر استشاري وأستاذ أمراض القلب وقسطرة الشرايين الدكتور خالد النمر من استمرار نشاط التهاب الروماتويد وارتفاع مؤشرات الالتهاب لدى المرضى، مؤكداً أهمية التنسيق بين أطباء القلب والروماتيزم للسيطرة على الالتهاب والحد من مضاعفاته.','["وأوضح الدكتور النمر أن التحكم في التهاب الروماتويد لا يقتصر أثره على تخفيف معاناة المفاصل، بل يمتد إلى الوقاية من المضاعفات القلبية، مشيراً إلى أن مريض الروماتويد الذي لا يخضع التهابه للسيطرة يكون أكثر عرضة للمضاعفات القلبية الخطرة بنحو 60% مقارنة بغير المصابين.","وأكد النمر أن الوقاية من عوامل الخطورة التقليدية، وفي مقدمتها ارتفاع ضغط الدم والسكري واضطرابات الدهون، تظل ركيزة أساسية في حماية هؤلاء المرضى، لافتاً إلى أنها تفسر وحدها نحو نصف الخطر القلبي الكلي لديهم."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ANnFMR-','https://sabq.org/article/ANnFMR-','','https://sabq.org/article/ANnFMR-','صحيفة سبق','','2026-08-29T01:57:00.000Z','2026-08-29T05:08:00.000Z','2026-08-29T08:24:50.348Z','https://media.sabq.org/news/2026/08/184a5a93-6b37-441e-aef5-b52fe4442e84/w678.webp','/api/media/57bc73b8-1305-40be-81cb-aa1da88b7c90','/api/media/57bc73b8-1305-40be-81cb-aa1da88b7c90?variant=thumbnail','استشاري قلب يحذر: التهاب الروماتويد النشط يرفع مخاطر مضاعفات القلب 60%',678,452,'valid','published','archived','valid',35,'6ffc40101ab46e4a2e6e255386efde807a1e37cf6c65a1c462fc25d939529360','3e8d86959c149a9436f689e7f46a4e025759d277597bb3081658be448a1e86ce','محدّث','2026-08-29T08:24:50.349Z','2026-10-07T21:18:07.657Z','','',0,0,'international','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة"]','["الصحة العامة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:18:07.657Z',200,57,0,'source_article_available','',NULL,NULL,'body:d04c757ad1667a7cdcc913993d16e92b92d54e0240a585e76cc8f7900edc4d30','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a373c115-aa3d-45ac-9f56-6b588ac7c481','news-a373c115-aa3d-45ac-9f56-6b588ac7c481','«الأمن السيبراني» يحذّر من ثغرات في منتجات TP-Link ويطالب بالتحديث الفوري','الامن السيبراني يحذر من ثغرات في منتجات tp link ويطالب بالتحديث الفوري','أصدر المركز الوطني الإرشادي للأمن السيبراني تنبيهًا أمنيًا عالي المستوى، دعا فيه مستخدمي منتجات TP-Link إلى المبادرة بإجراء التحديثات الأمنية اللازمة، والتأكد من استخدام أحدث إصدار متاح للمنتجات المتأثرة.','["وأوضح المركز أن شركة TP-Link أصدرت تحديثات لمعالجة عدد من الثغرات الأمنية، مؤكدًا أهمية تطبيقها بشكل عاجل للحد من المخاطر المحتملة وتعزيز حماية الأجهزة والأنظمة.","وشدّد المركز على ضرورة متابعة التحديثات الأمنية الصادرة عن الشركات المصنّعة بصورة مستمرة، والالتزام بإجراءات الحماية الموصى بها، بما يسهم في رفع مستوى الأمن السيبراني وتقليل فرص استغلال الثغرات في الأجهزة المتصلة بالشبكات."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/Ee6oBzZ','https://sabq.org/article/Ee6oBzZ','','https://sabq.org/article/Ee6oBzZ','صحيفة سبق','','2026-08-29T02:32:00.000Z','2026-08-29T05:33:00.000Z','2026-08-29T08:42:47.154Z','https://media.sabq.org/news/2026/08/92150955-cb31-4de4-baca-95fd2df8d10c/w1200.webp','/api/media/a373c115-aa3d-45ac-9f56-6b588ac7c481','/api/media/a373c115-aa3d-45ac-9f56-6b588ac7c481?variant=thumbnail','«الأمن السيبراني» يحذّر من ثغرات في منتجات TP-Link ويطالب بالتحديث الفوري',1200,675,'valid','published','archived','valid',53,'49e1593310ac0c3184ec13cbdc2464a6978cda2bb1eeb120654c0a02e3353ccd','6d107aee6d26d0f06ac1a8edcd48b2daec842f9e3be44b6ad324b4ffea1406d6','محدّث','2026-08-29T08:42:47.154Z','2026-10-07T19:26:24.583Z','','',0,0,'international','عادي',52,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة TP-Link أصدرت تحديثات لمعالجة","التقنية والتحول الرقمي"]','["شركة TP-Link أصدرت تحديثات لمعالجة","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:26:24.583Z',200,65,0,'source_article_available','',NULL,NULL,'body:51f3aea318a59d6e8f03eefd25d5f373ded11e5fc97cf4b099be8563a9e8f1be','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('320f4f3a-c562-482b-ab4f-c393a82f3b6f','news-320f4f3a-c562-482b-ab4f-c393a82f3b6f','كاتب: تشديد الرقابة على منافذ الدولة اليمنية ضرورية لمكافحة تهريب الأسلحة إلى ميليشيات الحوثي','كاتب تشديد الرقابه علي منافذ الدوله اليمنيه ضروريه لمكافحه تهريب الاسلحه الي ميليشيات الحوثي','قال الكاتب السياسي هزاع البيل، إن تشديد الرقابة على المنافذ البرية والبحرية حق سيادي للدولة وخطوة ضرورية لمكافحة تهريب الأسلحة والمواد مزدوجة الاستخدام إلى ميليشيات الحوثي.','["وأضاف خلال مداخلة مع قناة «الإخبارية» أن الميليشيات تستغل كل السواحل اليمنية وبعض المنافذ البرية لإدخال أسلحة تتسبب في قتل اليمنيين وعملياتهم الإرهابية.","وكان قد شدد اجتماع أمني وعسكري موسع، ترأسه نائب رئيس مجلس القيادة الرئاسي اليمني سالم الخنبشي ، يوم الخميس الماضي، على إحكام سيطرة الدولة على المنافذ البرية والبحرية والجوية في محافظة حضرموت ، وإغلاق المنافذ غير القانونية، وتشديد إجراءات مكافحة التهريب."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/1a3d75crk','https://ajel.sa/international/1a3d75crk','https://ajel.sa/international/1a3d75crk','https://ajel.sa/international/1a3d75crk','فريق التحرير','','2026-08-29T02:38:00.000Z','Wed, 07 Oct 2026 19:34:50 GMT','2026-08-29T08:51:45.461Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%87%D8%B2%D8%A7%D8%B9-Xc_SZjc_.jpg','/api/media/320f4f3a-c562-482b-ab4f-c393a82f3b6f','/api/media/320f4f3a-c562-482b-ab4f-c393a82f3b6f?variant=thumbnail','كاتب: تشديد الرقابة على منافذ الدولة اليمنية ضرورية لمكافحة تهريب الأسلحة إلى ميليشيات الحوثي',1200,675,'valid','published','archived','valid',41,'f3e39320d5835bd12673ab7c66c98ca96177b6498ce3ae538d3d1d3f5bfb646f','f68eef9bd4738a72dda0178392878c4caf193355a0d17409375f206e4c6edc0c','محدّث','2026-08-29T08:51:45.461Z','2026-10-07T20:24:31.987Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس القيادة الرئاسي اليمني سالم","رئيس مجلس القيادة الرئاسي اليمني","الثقافة والفنون","اليمن"]','["مجلس القيادة الرئاسي اليمني سالم","رئيس مجلس القيادة الرئاسي اليمني","الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:34:52.216Z',200,61,0,'source_content_changed','',NULL,NULL,'body:640958155c74aab5ba4df54899959a05dadaed1f9a69ab9b9fdfc7d7370edd28','Wed, 07 Oct 2026 19:34:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('09552117-4074-492e-9566-c58444b619a7','news-09552117-4074-492e-9566-c58444b619a7','المرور تحذر من تطاير حمولة الشاحنات: يهدد مستخدمي الطرق','المرور تحذر من تطاير حموله الشاحنات يهدد مستخدمي الطرق','حذرت الإدارة العامة للمرور ، من تطاير حمولة الشاحنات على الطرق. وأضافت الإدارة، عبر منصة (إكس)، أن تثبيت حمولة الشاحنات بإحكام يعزز السلامة المروية، بينما تطاير الحمولة خطر يهدد سلامة مستخدمي الطريق.','["حذرت الإدارة العامة للمرور ، من تطاير حمولة الشاحنات على الطرق.","يأتي ذلك في سياق إجراءات توعوية متواصلة تباشرها الإدارة العامة للمرور، لقائدي المركبات حيث نصحت في وقت سابق بالتأكد من سلامة مساحات زجاج المركبة لرؤية واضحة أثناء هطول الأمطار."]','السيارات','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/4g75tqih6','https://ajel.sa/local/4g75tqih6','https://ajel.sa/local/4g75tqih6','https://ajel.sa/local/4g75tqih6','فريق التحرير','','2026-08-29T02:38:00.000Z','Wed, 07 Oct 2026 19:34:44 GMT','2026-08-29T08:51:48.194Z','https://cdn.ajel.sa/articles/2026-07/%D9%85-%D9%85%D9%85-%D9%85-%D9%85%D9%85%D8%B1%D9%88%D8%B1%D9%88-EPLup6vm.avif','/api/media/09552117-4074-492e-9566-c58444b619a7','/api/media/09552117-4074-492e-9566-c58444b619a7?variant=thumbnail','المرور تحذر من تطاير حمولة الشاحنات: يهدد مستخدمي الطرق',960,611,'valid','published','archived','valid',40,'610a91b662c13e9fafdb03ef0982b7058707e0fddfc016392c8458ba86dce4b0','08f755b5f19284c7c13d4b2be0b422b1966eafa4f83f7939b9d21cf888c96240','محدّث','2026-08-29T08:51:48.194Z','2026-10-07T20:24:31.991Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ"]','["الطقس والمناخ"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:34:46.495Z',200,61,0,'source_content_changed','',NULL,NULL,'body:30311aae6c8ffe41fce0514d43f494cdce82a366d47782da7134320ca98a0cf9','Wed, 07 Oct 2026 19:34:44 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2e90201d-9b63-497f-8d06-d3be22596c20','news-2e90201d-9b63-497f-8d06-d3be22596c20','«سبيس إكس» تنتشل صاروخ «ستارشيب» من المحيط الهندي بعد شهر من إطلاقه','سبيس اكس تنتشل صاروخ ستارشيب من المحيط الهندي بعد شهر من اطلاقه','نجحت شركة «سبيس إكس» في انتشال صاروخها العملاق «ستارشيب» من مياه المحيط الهندي، في أكبر عملية استعادة تنفذها الشركة حتى الآن، بعد نحو شهر من إطلاقه. وتعمل «سبيس إكس» حالياً على نقل الصاروخ إلى قاعدته الرئيسية في ولاية تكساس الأمريكية، في رحلة يُتوقع أن تستغرق عدة أشهر.','["نجحت شركة «سبيس إكس» في انتشال صاروخها العملاق «ستارشيب» من مياه المحيط الهندي، في أكبر عملية استعادة تنفذها الشركة حتى الآن، بعد نحو شهر من إطلاقه.","وتعمل «سبيس إكس» حالياً على نقل الصاروخ إلى قاعدته الرئيسية في ولاية تكساس الأمريكية، في رحلة يُتوقع أن تستغرق عدة أشهر.","وكان «ستارشيب» قد أُطلق في 24 يوليو الماضي من قاعدة «ستار بيس» في تكساس، في رحلته التجريبية الثالثة عشرة بصورته المجمعة بالكامل، إذ شهدت الرحلة أول تحليق للصاروخ فوق سطح الماء لمدة ساعة كاملة مع بقائه سليماً أثناء الطفو.","ويُشكّل «ستارشيب» عنصراً محورياً في خطط استكشاف الفضاء المستقبلية، إذ تعتزم وكالة «ناسا» الأمريكية توظيفه في مهماتها لإعادة البشر إلى سطح القمر، فضلاً عن دوره المرتقب في نقل البشر والمعدات إلى كوكب المريخ."]','الوظائف وسوق العمل','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/NyQSj7D','https://sabq.org/article/NyQSj7D','','https://sabq.org/article/NyQSj7D','صحيفة سبق','الرياض','2026-08-29T03:13:00.000Z','2026-08-29T03:20:00.000Z','2026-08-29T13:42:52.783Z','https://media.sabq.org/news/2026/08/867c4505-bb92-48fc-8f96-e1c249d4a6f2/w596.webp','/api/media/2e90201d-9b63-497f-8d06-d3be22596c20','/api/media/2e90201d-9b63-497f-8d06-d3be22596c20?variant=thumbnail','«سبيس إكس» تنتشل صاروخ «ستارشيب» من المحيط الهندي بعد شهر من إطلاقه',596,335,'valid','published','archived','valid',35,'c79f2437d5a4c6b7ca55f7f78a44bbccff06aa2c3d902a1c12482bcc9c6e442c','37f1b8d85625ce0e7daf2e5d9cf28f7c1d2048027f3bc14be5a2d741af992bec','محدّث','2026-08-29T09:19:47.200Z','2026-10-07T20:24:31.994Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة سبيس إكس في انتشال"]','["شركة سبيس إكس في انتشال"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:53:08.668Z',200,51,0,'source_article_available','',NULL,NULL,'body:0defe998e8dc4961d34a390a4f61436ea96cccc66feaecce05fe53a75755cefe','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e75c7785-9ee2-41e4-83dc-4e61752e06ed','news-e75c7785-9ee2-41e4-83dc-4e61752e06ed','عبر أبشر.. خطوات نقل ملكية المركبة إلى منشأة إلكترونيًا','عبر ابشر خطوات نقل ملكيه المركبه الي منشاه الكترونيا','وأوضح المرور السعودي، عبر منصة إكس ، أنه تمكن الخدمة مالك المركبة من نقل ملكيتها إلى منشأة مسجلة برقم 700 بسهولة ويسر، ضمن خطوات إلكترونية واضحة. وحددت منصة أبشر خطوات إتمام نقل ملكية المركبات وإتمام المبايعة للبائع والمشتري من خلال خدمة أبشر المركبات، وجاءت خطوات خدمة مبايعة المركبات عبر أبشر للبائع كالتالي:','["أتاحت الإدارة العامة للمرور خدمة نقل ملكية المركبة إلى منشأة تابعة للمالك إلكترونيًا عبر منصة أبشر أفراد، دون الحاجة إلى مراجعة المرور حضوريًا.","وأوضح المرور السعودي، عبر منصة إكس ، أنه تمكن الخدمة مالك المركبة من نقل ملكيتها إلى منشأة مسجلة برقم 700 بسهولة ويسر، ضمن خطوات إلكترونية واضحة.","تشمل خطوات تنفيذ الخدمة الدخول إلى منصة أبشر، ثم اختيار المركبات، ومن ثم إدارة المركبات، وأخيرًا تحديد المركبة المراد نقل ملكيتها.","وحددت منصة أبشر خطوات إتمام نقل ملكية المركبات وإتمام المبايعة للبائع والمشتري من خلال خدمة أبشر المركبات، وجاءت خطوات خدمة مبايعة المركبات عبر أبشر للبائع كالتالي:","الضغط على إتمام المبايعة وذلك بعد تحويل المشتري لثمن المركبة لحساب ضامن الخاص بعملية المبايعة","تحويل ثمن المركبة لحساب ضامن الخاص بعملية المبايعة"]','السيارات','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/piqdlsvoc','https://ajel.sa/thehour/piqdlsvoc','https://ajel.sa/thehour/piqdlsvoc','https://ajel.sa/thehour/piqdlsvoc','فريق التحرير','','2026-08-29T03:20:00.000Z','Wed, 07 Oct 2026 19:59:43 GMT','2026-08-29T09:32:18.372Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/1000018024-crop-yND1W-PP.jpg','/api/media/e75c7785-9ee2-41e4-83dc-4e61752e06ed','/api/media/e75c7785-9ee2-41e4-83dc-4e61752e06ed?variant=thumbnail','عبر أبشر.. خطوات نقل ملكية المركبة إلى منشأة إلكترونيًا',1200,675,'valid','published','archived','valid',41,'b4ddbfe1ee7267b3496dc05d8100f19f0b03a9b2c81043d049aeb323b0a59ea1','959235331a941e0f22d88e2203880b4adb37dd7b01161f38ccd5940c2c379dee','محدّث','2026-08-29T09:32:18.373Z','2026-10-07T20:24:31.998Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T19:59:45.192Z',200,75,0,'source_article_available','',NULL,NULL,'body:3c38389375a7246c4f4e995471f418cf2978b7e01761877a446318d1127c6a11','Wed, 07 Oct 2026 19:59:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1f7526e6-3520-4743-9ec9-0e385197eef0','news-1f7526e6-3520-4743-9ec9-0e385197eef0','هيئة الزكاة توضح مدة طلبات استرداد ضريبة التصرفات العقارية','هيئه الزكاه توضح مده طلبات استرداد ضريبه التصرفات العقاريه','قالت هيئة الزكاة والضريبة والجمارك إن دراسة طلبات استرداد ضريبة التصرفات العقارية خلال 15 يوم عمل من تاريخ إلغاء الطلب المسدد قبل الإفراغ. وأوضحت الهيئة، أنه يتم استرداد المبالغ المسددة خلال 10 أيام عمل من تاريخ قبول طلب الاسترداد.','["قالت هيئة الزكاة والضريبة والجمارك إن دراسة طلبات استرداد ضريبة التصرفات العقارية خلال 15 يوم عمل من تاريخ إلغاء الطلب المسدد قبل الإفراغ.","وأوضحت الهيئة، أنه يتم استرداد المبالغ المسددة خلال 10 أيام عمل من تاريخ قبول طلب الاسترداد.","ووفقا لنظام ضريبة التصرفات العقارية، يخضع شراء و بيع الاراضي لضريبة التصرفات العقارية بنسبة 5%، كما تتحمل الدولة ضريبة التصرفات العقارية بنسبة 5% عما لا يزيد عن 1,000,000ريال من مبلغ شراء المسكن الأول ( الجاهز للسكن فقط ) للمواطن، ولايسري الأمر الملكي على شراء الأراضي والبناء الذاتي.","وأوضحت الهيئة، في وقت سابق، أن توزيع تركة يعفى من ضريبة التصرفات العقارية في حال توزيع التركة بين الورثة ويجب إرفاق (قرار قسمة التركة الموثق)، كما يتعين على الوكيل الشرعي تسجيل العقار و اختيار طبيعة مقدم الطلب وكيل الورثة و يجب ادخال نوع هوية احد اطراف الوكالة ، رقم هوية أحد اطراف الوكالة ، رقم الوكالة الشرعية."]','العقارات','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/n8jqmlqq0','https://ajel.sa/thehour/n8jqmlqq0','https://ajel.sa/thehour/n8jqmlqq0','https://ajel.sa/thehour/n8jqmlqq0','فريق التحرير','','2026-08-29T03:06:00.000Z','Mon, 07 Sep 2026 05:24:44 GMT','2026-08-29T09:32:26.859Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%87%D9%8A%D8%A6%D8%A9-%D8%A7%D9%84%D8%B2%D9%83%D8%A7%D8%A9-%D9%88%D8%A7%D9%84%D8%B6%D8%B1%D9%8A%D8%A8%D8%A9-%D9%88%D8%A7%D9%84%D8%AC%D9%85%D8%A7%D8%B1%D9%83-rhVp4zrz.jpg','/api/media/1f7526e6-3520-4743-9ec9-0e385197eef0','/api/media/1f7526e6-3520-4743-9ec9-0e385197eef0?variant=thumbnail','هيئة الزكاة توضح مدة طلبات استرداد ضريبة التصرفات العقارية',1200,675,'valid','published','archived','valid',41,'f7c2b2583715733aafd6c396f8f6ee344d8d6c8ecba5f54cf68b25001fed43d3','3d22dd2867217aefffbb1162ac6e4e79d6b6c616f56ac690a32d3a3559c236ff','محدّث','2026-08-29T09:32:26.860Z','2026-10-07T20:24:32.002Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الزكاة توضح مدة طلبات"]','["هيئة الزكاة توضح مدة طلبات"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:58:14.517Z',NULL,69,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ac2921f1-8594-4caa-b689-95a8c21e30c1','news-ac2921f1-8594-4caa-b689-95a8c21e30c1','غدا.. عودة طلاب وطالبات مكة والمدينة وجدة والطائف إلى مقاعد الدراسة','غدا عوده طلاب وطالبات مكه والمدينه وجده والطائف الي مقاعد الدراسه','تكتمل غدا الأحد عوددة الطلاب والطالبات إلى مقاعد الدراسة في مختلف المناطق بانضمام طلاب وطالبات مكة المكرمة والمدينة ومحافظتي جدة و الطائف إلى زملائهم في بقية المناطق للعام الدراسي الحالي.','["وكانت العام الدراسي قد انطلق في 11 منطقة ب المملكة ، يوم الأحد 3 ربيع الأول 1448هـ الموافق 16 أغسطس 2026."]','التعليم','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/v9iwta0y5','https://ajel.sa/local/v9iwta0y5','https://ajel.sa/local/v9iwta0y5','https://ajel.sa/local/v9iwta0y5','فريق التحرير','مكة المكرمة','2026-08-29T03:20:00.000Z','Mon, 07 Sep 2026 00:50:50 GMT','2026-08-29T09:33:39.953Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D9%85%D8%AF%D8%A7%D8%B1%D8%B3-jbpPFDWW.jpg','/api/media/ac2921f1-8594-4caa-b689-95a8c21e30c1','/api/media/ac2921f1-8594-4caa-b689-95a8c21e30c1?variant=thumbnail','غدا.. عودة طلاب وطالبات مكة والمدينة وجدة والطائف إلى مقاعد الدراسة',1200,675,'valid','published','archived','valid',40,'03426eb98a08910864be48337d08b49905424877e51aaee217c1e3f1d1897859','cb3ad4500cbebac197d5b3a66a22faa4ffec0f71185f2b90c84dce573f6d9e65','محدّث','2026-08-29T09:33:39.953Z','2026-10-07T20:24:32.005Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","مكة","جدة"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:58:56.295Z',NULL,72,5,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4cad2a8d-f3fd-48e0-beca-00dbe2635a8e','news-4cad2a8d-f3fd-48e0-beca-00dbe2635a8e','مختص بالشأن الأمريكي: عامل الوقت ليس في صالح إيران','مختص بالشان الامريكي عامل الوقت ليس في صالح ايران','وأكمل، أن الإدارة الأمريكية تنذر إيران بأن كل يوم يمر الآن سيحمل طهران نتائج كارثية، حيث أدرك الأمريكيون أن مذكرة التفاهم التي وقعت بين الولايات المتحدة وإيران كانت في صالح طهران ومع ذلك لم تحترم الأخيرة بنودها.','["قال الكاتب المختص في الشأن الأمريكي والشرق الأوسط سعيد البستاني، إن عامل الوقت لم يعد في صالح إيران .","وأضاف البستاني، بمداخلة عبر أثير «العربية إف إم»، إن إيران راهنت في الوقت السابق على عامل الوقت على أمل الضغط على الولايات المتحدة بينما يحدث الآن العكس.","وأردف المختص في الشأن الأمريكي، أن إيران هاجمت ناقلات نفط في المسار العماني بالهجوم على ناقلات النفط؛ ما أدى إلى موقف أمريكي أكثر تشددا حيال إيران.","وتباشر الولايات المتحدة الأمريكية حصارها البحري المفروض على إيران، في سياق إجراءات الضغط على طهران لإلزامها بالعودة إلى طاولة المفاوضات مع واشنطن من دون قيد أو شرط."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/ztgqyjpmn','https://ajel.sa/international/ztgqyjpmn','https://ajel.sa/international/ztgqyjpmn','https://ajel.sa/international/ztgqyjpmn','فريق التحرير','','2026-08-29T02:55:00.000Z','Wed, 07 Oct 2026 20:00:43 GMT','2026-08-29T09:44:48.961Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%A3%D9%85%D8%B1%D9%8A%D9%83%D8%A7-%D9%88%D8%A5%D9%8A%D8%B1%D8%A7%D9%86-404U13Z0.jpg','/api/media/4cad2a8d-f3fd-48e0-beca-00dbe2635a8e','/api/media/4cad2a8d-f3fd-48e0-beca-00dbe2635a8e?variant=thumbnail','مختص بالشأن الأمريكي: عامل الوقت ليس في صالح إيران',1200,675,'valid','published','archived','valid',99,'62ec76c6ba90ef99ffaf746eff67b99030c706928b4cc08a0e17c0390ad2c39d','5e9470119b1aeb1c129b189296d73b922f4b4448810fd8ecfa6fcaae15884f54','محدّث','2026-08-29T09:44:48.962Z','2026-10-07T20:24:32.009Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الثقافة والفنون","السياسة والعلاقات الدولية","إيران","الشرق الأوسط","الولايات المتحدة"]','["الطاقة والنفط","الثقافة والفنون","السياسة والعلاقات الدولية","الشرق الأوسط","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T20:00:45.388Z',200,58,0,'source_content_changed','',NULL,NULL,'body:25dd2bb9be26a507f6e74d505c23f6657339178745a047a55cd81e2441b46db4','Wed, 07 Oct 2026 20:00:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6beab2fe-37ef-4c71-a7c4-467aa4d9a74b','news-6beab2fe-37ef-4c71-a7c4-467aa4d9a74b','أخصائية: إقبال الرجال على العمليات التجميلية يزيد و"البوتوكس" الأكثر طلبا','اخصائيه اقبال الرجال علي العمليات التجميليه يزيد و البوتوكس الاكثر طلبا','قالت أخصائية الجلدية والتجميل فاطمة الصطوف، إن إقبال الرجال على العمليات التجميلية يزيد وأكثر ما يطلبونه "البوتوكس". وأردفت، أن الرجال يركزون كذلك على طلب تحديد الفك وعلاجات الشعر مع انتشار الصلع الوراثي في منطقة الشرق الأوسط .','["قالت أخصائية الجلدية والتجميل فاطمة الصطوف، إن إقبال الرجال على العمليات التجميلية يزيد وأكثر ما يطلبونه \"البوتوكس\".","وأضافت الأخصائية، خلال لقائها المذاع عبر أثير \"العربية إف إم\"، أن البوتوكوس لا يغير الملامح ويحفظ الوجه من ظهور علامات تقدم السن.","وأردفت، أن الرجال يركزون كذلك على طلب تحديد الفك وعلاجات الشعر مع انتشار الصلع الوراثي في منطقة الشرق الأوسط .","وتابعت أخصائية الجلدية والتجميل، أن بعض الدراسات تشير إلى أن \"حقن الفيلر\" قد يؤدي إلى تآكل العظام بسبب الأخطاء التنفيذية."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/q4h8lyqzf','https://ajel.sa/misc/q4h8lyqzf','https://ajel.sa/misc/q4h8lyqzf','https://ajel.sa/misc/q4h8lyqzf','فريق التحرير','','2026-08-29T03:58:00.000Z','Wed, 07 Oct 2026 21:11:34 GMT','2026-08-29T10:12:48.287Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/ai-edited/2026-08/YaK0QxjxYN96D1_W.png','/api/media/6beab2fe-37ef-4c71-a7c4-467aa4d9a74b','/api/media/6beab2fe-37ef-4c71-a7c4-467aa4d9a74b?variant=thumbnail','أخصائية: إقبال الرجال على العمليات التجميلية يزيد و"البوتوكس" الأكثر طلبا',1200,675,'valid','published','archived','valid',41,'b716e9c8b5c52a726d6e48d318e18c47b88ff52696617b70bb01da87c19da93f','07b626d48c03f90bb83443c70b255159dcfde2d135fc81d7df41063fc3cf605f','محدّث','2026-08-29T10:12:48.287Z','2026-10-07T21:11:37.868Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الشرق الأوسط"]','["الصحة العامة","الشرق الأوسط"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:11:37.868Z',200,68,0,'source_content_changed','',NULL,NULL,'body:4a3269278e31fa8cdfbd2a6da9020e970212b251c9fec181e8bcd504ed3feac0','Wed, 07 Oct 2026 21:11:34 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b3e92933-5f08-4dc9-8597-e33807b18c2b','news-b3e92933-5f08-4dc9-8597-e33807b18c2b','مختص: أكثر من 8 ملايين شخص يعملون في قطاع المنشآت الصغيرة والمتوسطة','مختص اكثر من 8 ملايين شخص يعملون في قطاع المنشات الصغيره والمتوسطه','محمد مكني، أستاذ المالية والاستثمار في جامعة الإمام محمد بن سعود، إن حجم قطاع المنشآت الصغيرة والمتوسطة يعمل فيه أكثر من 8 ملايين شخص، وترتفع مساهمتها في الناتج المحلي إلى 23%، ومن المستهدف الوصول إلى 35% من الناتج المحلي.','["وأضاف خلال مداخلة مع قناة «الإخبارية» أنه كانت من التحديات التي تواجه تلك القطاعات التمويل بعكس النمو الحالي لها بفضل رؤية المملكة لها.","وأشار مكني إلى أن ذلك القطاع يعد من القطاعات المهمة جدا لخلق التنوع الاقتصادي."]','أخبار السعودية','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/9us2d8yn5','https://ajel.sa/economy/9us2d8yn5','https://ajel.sa/economy/9us2d8yn5','https://ajel.sa/economy/9us2d8yn5','فريق التحرير','','2026-08-29T03:58:00.000Z','Wed, 07 Oct 2026 21:11:37 GMT','2026-08-29T10:12:48.295Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%85%D9%83%D9%86%D9%8A-bMYlMaci.jpg','/api/media/b3e92933-5f08-4dc9-8597-e33807b18c2b','/api/media/b3e92933-5f08-4dc9-8597-e33807b18c2b?variant=thumbnail','مختص: أكثر من 8 ملايين شخص يعملون في قطاع المنشآت الصغيرة والمتوسطة',1200,675,'valid','published','archived','valid',40,'fce044b245f1b441c4f494339c0fc8fe3f1836de4ef5bd55d805390d468b87d3','7c613e13cd64d704326ea1ad8c57da3101787d3053d248f5e1c828b7eae11bf6','محدّث','2026-08-29T10:12:48.295Z','2026-10-07T21:11:38.969Z','','',0,0,'saudi_national','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","جامعة الإمام محمد بن سعود","التعليم والتدريب","الاقتصاد والأسواق"]','["جامعة الإمام محمد بن سعود","التعليم والتدريب","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:11:38.969Z',200,67,0,'source_content_changed','',NULL,NULL,'body:e42483c9ea68916ad17201f5a09a212aea1431151663adf0b0e35a6fe58a72b5','Wed, 07 Oct 2026 21:11:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('05ff5f9d-5a87-42ea-8315-31ee9560e99a','news-05ff5f9d-5a87-42ea-8315-31ee9560e99a','هل السكر البني بديل صحي للأبيض؟.. "عش بصحة" توضح حقيقة الخطأ الشائع','هل السكر البني بديل صحي للابيض عش بصحه توضح حقيقه الخطا الشائع','كشفت منصة عش بصحة التوعوية التابعة ل وزارة الصحة ، حقيقة الاعتقاد بأن السكر البني خيار صحي أكثر من السكر الأبيض، موضحة أن السكر البني والسكر الأبيض متقاربان في السعرات الحرارية.','["وفي منشور عبر منصة إكس، عن حقيقة أن السكر البني بديل صحي للسكر الأبيض، أكدت أن السكر البني يُعد من السكريات المضافة ويمنح سعرات حرارية مقاربة للسكر الأبيض ؛ لذلك لا يعني اختلاف لونه أنه خيار صحي أكثر.","وأوضحت أنه ينصح بألا يتجاوز استهلاك الشخص البالغ 50 غرامًا يوميا (نحو 3 ملاعق طعام)، بما في ذلك السكريات المضافة أثناء الطهي للحد من الإفراط في تناولها و آثارها الصحية."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/ufhfrhhfs','https://ajel.sa/thehour/ufhfrhhfs','https://ajel.sa/thehour/ufhfrhhfs','https://ajel.sa/thehour/ufhfrhhfs','فريق التحرير','','2026-08-29T03:58:00.000Z','Wed, 07 Oct 2026 21:11:37 GMT','2026-08-29T10:12:49.127Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/1000280647-crop--vIGdmh6.jpg','/api/media/05ff5f9d-5a87-42ea-8315-31ee9560e99a','/api/media/05ff5f9d-5a87-42ea-8315-31ee9560e99a?variant=thumbnail','هل السكر البني بديل صحي للأبيض؟.. "عش بصحة" توضح حقيقة الخطأ الشائع',1200,675,'valid','published','archived','valid',41,'e2eaa1f6a2d8acf97b0fa5f3f78d248c1e9b3346ab346db7efae18db3c1cb5c9','8f34597166ce15d01ac2de36ba56a4357d746b866f689a90b6ac7c026f07fbf5','محدّث','2026-08-29T10:12:49.127Z','2026-10-07T21:11:38.988Z','','',0,0,'international','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الصحة حقيقة الاعتقاد بأن","الصحة العامة"]','["وزارة الصحة حقيقة الاعتقاد بأن","الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:11:38.988Z',200,68,0,'source_content_changed','',NULL,NULL,'body:53d0f7362187bce4b2e45af214cc912e64b746f6df57b4acfe3d87c448a1709c','Wed, 07 Oct 2026 21:11:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d7ad133e-12df-4975-bb17-3fc5433cd7d3','news-d7ad133e-12df-4975-bb17-3fc5433cd7d3','الرئيس الإيراني: نسعى لحل مشكلاتنا عبر الحوار دون استسلام للتهديدات','الرئيس الايراني نسعي لحل مشكلاتنا عبر الحوار دون استسلام للتهديدات','قال الرئيس الإيراني، مسعود بزشكيان إن بلاده تسعى لحل مشكلاتها عبر الحوار لكنها لن نستسلم للتهديدات. وكان الرئيس الإيراني أعلن بيع نحو 90 مليون برميل من النفط خلال فترة تنفيذ الاتفاق المؤقت مع الولايات المتحدة الأمريكية.','["قال الرئيس الإيراني، مسعود بزشكيان إن بلاده تسعى لحل مشكلاتها عبر الحوار لكنها لن نستسلم للتهديدات.","وتابع، إننا لا نرغب بالحرب لكننا نقف بحزم في وجه العدوان وندافع عن أنفسنا ولا توجد قوة تستطيع إجبار أمة موحدة تقف دفاعًا عن أرضها على الاستسلام.","وأضاف الرئيس الإيراني، أن طهران اتفقت مع سلطنة عمان على مسار للعبور في مضيق هرمز وفتح المضيق مرهون بالتزام الولايات المتحدة بمذكرة التفاهم.","وكان الرئيس الإيراني أعلن بيع نحو 90 مليون برميل من النفط خلال فترة تنفيذ الاتفاق المؤقت مع الولايات المتحدة الأمريكية."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/rkstrvy07','https://ajel.sa/international/rkstrvy07','https://ajel.sa/international/rkstrvy07','https://ajel.sa/international/rkstrvy07','فريق التحرير','','2026-08-29T03:58:00.000Z','Wed, 07 Oct 2026 21:11:43 GMT','2026-08-29T10:12:52.593Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%85%D8%B3%D8%B9%D9%88%D8%AF-%D8%A8%D8%B2%D8%B4%D9%83%D9%8A%D8%A7%D9%86-D_8j7gUe.jpg','/api/media/d7ad133e-12df-4975-bb17-3fc5433cd7d3','/api/media/d7ad133e-12df-4975-bb17-3fc5433cd7d3?variant=thumbnail','الرئيس الإيراني: نسعى لحل مشكلاتنا عبر الحوار دون استسلام للتهديدات',1200,675,'valid','published','archived','valid',99,'fa86461ce9f7a5ea9c23f095b468251473804bed11716d76a694229392180a44','cff1d2f2f1adbc9be8f16194b8f455599462d3f4875cb515c474791db82acffd','محدّث','2026-08-29T10:12:52.593Z','2026-10-07T21:11:45.474Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","إيران","الولايات المتحدة"]','["الطاقة والنفط","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T21:11:45.474Z',200,67,0,'source_content_changed','',NULL,NULL,'body:b3283e29a44b46368d65df8e5d8b415938d3bca5de84d584873ccfaf15e4c82c','Wed, 07 Oct 2026 21:11:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('61c542b1-ac9a-4fc1-b769-9ccbb3444c2e','news-61c542b1-ac9a-4fc1-b769-9ccbb3444c2e','الداخلية تضبط أكثر من 13 ألف مخالف لأنظمة الإقامة والعمل وأمن الحدود خلال أسبوع','الداخليه تضبط اكثر من 13 الف مخالف لانظمه الاقامه والعمل وامن الحدود خلال اسبوع','أسفرت الحملات الميدانية المشتركة لمتابعة وضبط مخالفي أنظمة الإقامة والعمل وأمن الحدود، التي نُفِّذت في مناطق المملكة كافة خلال الفترة من 7 إلى 13 ربيع الآخر 1448هـ الموافق 20 إلى 26 أغسطس 2026م، عن ضبط 14434 مخالفاً.','["أولاً: المخالفون المضبوطون بلغ إجمالي المخالفين الذين جرى ضبطهم في الحملات الأمنية المشتركة 14434 مخالفاً، موزَّعين على النحو الآتي: 6976 مخالفاً لنظام الإقامة، و4110 مخالفين لنظام أمن الحدود، و3348 مخالفاً لنظام العمل.","ثانياً: مخالفو الحدود بلغ إجمالي من جرى ضبطهم خلال محاولتهم عبور الحدود إلى داخل المملكة بطريقة غير نظامية 1450 شخصاً، توزَّعت جنسياتهم على النحو الآتي: 58% إثيوبيو الجنسية، و41% يمنيو الجنسية، و01% جنسيات أخرى.","كما جرى ضبط 44 شخصاً حاولوا عبور الحدود إلى خارج المملكة بطريقة غير نظامية.","ثالثاً: المتورطون في التسهيل جرى ضبط 27 متورطاً في نقل وإيواء وتشغيل مخالفي أنظمة الإقامة والعمل وأمن الحدود والتستر عليهم.","رابعاً: إجراءات تنفيذ الأنظمة بلغ إجمالي من يخضعون حالياً لإجراءات تنفيذ الأنظمة 29938 وافداً مخالفاً، منهم 27957 رجلاً و1981 امرأة.","وقد جرى إحالة 18914 مخالفاً إلى بعثاتهم الدبلوماسية للحصول على وثائق سفر، وإحالة 2867 مخالفاً لاستكمال حجوزات سفرهم، فيما رُحِّل 14905 مخالفين.","تحذير وزارة الداخلية أكدت وزارة الداخلية أن كل من يُسهِّل دخول مخالفي نظام أمن الحدود إلى المملكة أو نقلهم داخلها أو يوفر لهم المأوى أو يقدم لهم أي مساعدة أو خدمة بأي شكل من الأشكال، يُعرِّض نفسه لعقوبات تصل إلى السجن مدة 15 سنة، وغرامة مالية تصل إلى مليون ريال، ومصادرة وسيلة النقل والسكن المستخدم للإيواء، إضافة إلى التشهير به.","وأوضحت الوزارة أن هذه الجريمة تُعدّ من الجرائم الكبيرة الموجبة للتوقيف والمخلّة بالشرف والأمانة."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/520A-V3','https://sabq.org/article/520A-V3','','https://sabq.org/article/520A-V3','صحيفة سبق','الرياض','2026-08-29T04:15:00.000Z','2026-08-29T07:17:00.000Z','2026-08-29T10:22:51.356Z','https://media.sabq.org/news/2026/08/d0bca28d-9140-48b4-b2ee-857b8df5500e/w740.webp','/api/media/61c542b1-ac9a-4fc1-b769-9ccbb3444c2e','/api/media/61c542b1-ac9a-4fc1-b769-9ccbb3444c2e?variant=thumbnail','الداخلية تضبط أكثر من 13 ألف مخالف لأنظمة الإقامة والعمل وأمن الحدود خلال أسبوع',740,453,'valid','published','archived','valid',50,'c66c0c0a5b85e12ff91074ba42aa4559e9b5862cc9fe92692854ae384bf02f40','217e0f57fdc4e3616c4de4123383f727cb6d116506c0dbea4f3176aebe2d36b0','محدّث','2026-08-29T10:22:51.356Z','2026-10-07T21:11:42.851Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية أكدت وزارة الداخلية","السفر والسياحة","التقنية والتحول الرقمي","السياسة والعلاقات الدولية","مكة","الرياض","المدينة المنورة"]','["وزارة الداخلية أكدت وزارة الداخلية","السفر والسياحة","التقنية والتحول الرقمي","السياسة والعلاقات الدولية","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"التقنية","score":3.5},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T21:11:42.851Z',200,63,0,'source_article_available','',NULL,NULL,'body:17e049e8583c08e7bbc17efde3655f5ffca89ff6914fbd11f072927c00fb08ce','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e8931a9c-f6ae-4bc5-bbdf-ffe26f0ede21','news-e8931a9c-f6ae-4bc5-bbdf-ffe26f0ede21','هل يؤثر عمل التابع على قيمة دعم حساب المواطن؟.. البرنامج يجيب','هل يؤثر عمل التابع علي قيمه دعم حساب المواطن البرنامج يجيب','وأوضح حساب المواطن، عبر منصة إكس، ردًا على أحد المستفيدين بشأن وجود عمل للتابع، أنه لا يؤثر ذلك على الأهلية ، وفي حال وجود دخل للتابع لابد من الإفصاح عنه وسيتم احتسابه ضمن مجموع دخل الأسرة.','["طحدد برنامج حساب المواطن موقف التابع من الدعم في حالة التحاقه بالعمل وهل يؤثر ذلك على قيمة الدعم للأسرة.","وأضاف البرنامج أنه يمكن معرفة قيمة الاستحقاق والحد المانع من الحصول على الدعم بإمكانه استخدام حاسبة الدعم التقديرية.","وقال برنامج حساب المواطن إن زواج التابع يجعله غير مؤهل في حساب المستفيد الرئيس (رب الأسرة).","وأوضح البرنامج أنه «في حال كانت الحالة الاجتماعية: متزوج، ستصبح حالة الأهلية: غير مؤهل، في حساب رب الأسرة/ الأب).","وأكد برنامج حساب المواطن، في وقت سابق، أهمية قيام المتقدم الرئيسي بإضافة جميع التابعين له في بيانات الدعم.","وأضاف البرنامج، أن المتقدم الرئيسي ملزم بإضافة جميع التابعين لديه في البرنامج حتى لايؤثر ذلك على أهليته واستحقاقه."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/pgf5tj2yk','https://ajel.sa/thehour/pgf5tj2yk','https://ajel.sa/thehour/pgf5tj2yk','https://ajel.sa/thehour/pgf5tj2yk','فريق التحرير','','2026-08-29T04:11:00.000Z','Wed, 07 Oct 2026 21:18:15 GMT','2026-08-29T10:34:15.554Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%AD%D8%B3%D8%A7%D8%A8-%D8%A7%D9%84%D9%85%D9%88%D8%A7%D8%B7%D9%86-i15MBl7w.webp','/api/media/e8931a9c-f6ae-4bc5-bbdf-ffe26f0ede21','/api/media/e8931a9c-f6ae-4bc5-bbdf-ffe26f0ede21?variant=thumbnail','هل يؤثر عمل التابع على قيمة دعم حساب المواطن؟.. البرنامج يجيب',1200,675,'valid','published','archived','valid',41,'e3f25d14b8b17ba39b3bf3b4b33497f1b2e335cb74bb45d6079697919504ce15','c1bdf14613b707c11950d0b97baa2724326bd294fd7de25a9923598830638285','محدّث','2026-08-29T10:34:15.555Z','2026-10-07T21:18:17.752Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:18:17.752Z',200,60,0,'source_content_changed','',NULL,NULL,'body:b4ae0ae2242a88a30e3a35e1805d8dec29342240746de808e331776595ad1e01','Wed, 07 Oct 2026 21:18:15 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('33f22249-d2d8-4407-bfa4-f9c5e15ce3bd','news-33f22249-d2d8-4407-bfa4-f9c5e15ce3bd','خالد النمر يوضح أبرز أسباب العجز عن التحكم بالضغط','خالد النمر يوضح ابرز اسباب العجز عن التحكم بالضغط','وأشار عبر حسابه على منصة «إكس» إلى أن عدم الانتظام على الأدوية من أشهر أسباب عدم القدرة على التحكم بالضغط دولياً. ولفت النمر إلى أن بعض الدراسات العلمية قد كشفت أن عدم الانتظام على تناول الأدوية يؤدي وفقا لهذه الدراسات إلى ٤٠% من حالات عدم التحكم في الضغط.','["أوضح إستشاري وبروفيسور أمراض القلب وقسطرة الشرايين ب كلية الطب ، د. خالد النمر، أبرز الأسباب العالمية التي تؤدي إلى عدم القدرة على التحكم في الضغط.","وأشار عبر حسابه على منصة «إكس» إلى أن عدم الانتظام على الأدوية من أشهر أسباب عدم القدرة على التحكم بالضغط دولياً.","ولفت النمر إلى أن بعض الدراسات العلمية قد كشفت أن عدم الانتظام على تناول الأدوية يؤدي وفقا لهذه الدراسات إلى ٤٠% من حالات عدم التحكم في الضغط."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/9jeukjh66','https://ajel.sa/misc/9jeukjh66','https://ajel.sa/misc/9jeukjh66','https://ajel.sa/misc/9jeukjh66','فريق التحرير','','2026-08-29T04:11:00.000Z','Wed, 07 Oct 2026 21:18:15 GMT','2026-08-29T10:34:15.844Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%82%D9%8A%D8%A7%D8%B3-%D8%A7%D9%84%D8%B6%D8%BA%D8%B7-oQoE1CIo.jpg','/api/media/33f22249-d2d8-4407-bfa4-f9c5e15ce3bd','/api/media/33f22249-d2d8-4407-bfa4-f9c5e15ce3bd?variant=thumbnail','خالد النمر يوضح أبرز أسباب العجز عن التحكم بالضغط',1200,675,'valid','published','archived','valid',41,'01c9e0a0327cbaee2ad610f0c5cb691b5841953ec7e1f54e970365c37df8a23a','6f194eb9fa673343c358fd4b9d43dacaba818517dd6a3d41f7e865bd28f48ed2','محدّث','2026-08-29T10:34:15.844Z','2026-10-07T21:18:16.615Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:18:16.615Z',200,59,0,'source_content_changed','',NULL,NULL,'body:2baadef7c81ec4ca1bcc634246261b3d03762477d1a84204f3a40eeaad6371b1','Wed, 07 Oct 2026 21:18:15 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('852d9e9f-93c0-4ef6-b097-6dcf3c835685','news-852d9e9f-93c0-4ef6-b097-6dcf3c835685','«الموارد البشرية» تحث على متابعة الوظائف الشاغرة عبر منصة جدارات','الموارد البشريه تحث علي متابعه الوظائف الشاغره عبر منصه جدارات','حثت وزارة الموارد البشرية والتنمية الاجتماعية على متابعة الوظائف الشاغرة عبر المنصة الوطنية الموحدة للتوظيف. وأضافت الوزارة، عبر حسابها «العناية بالمستفيدين»، بمنصة (إكس) أن المستفيد يمكنه الإطلاع على الوظائف الشاغرة من خلال منصة جدارات.','["حثت وزارة الموارد البشرية والتنمية الاجتماعية على متابعة الوظائف الشاغرة عبر المنصة الوطنية الموحدة للتوظيف.","وأضافت الوزارة، عبر حسابها «العناية بالمستفيدين»، بمنصة (إكس) أن المستفيد يمكنه الإطلاع على الوظائف الشاغرة من خلال منصة جدارات.","يأتي ذلك في سياق حرص الوزارة على توفير فرص العمل، وتشجيع توطين الوظائف في القطاعات كافة، مع التنبيه على فاعلية آليات توفير الوظائف بالطرق الرسمية.","وكانت الوزارة، صممت برنامج «نطاقات» لاحتساب معدل التوطين وتصنيف المنشآت آليًّا، ويشمل: «النطاق البلاتيني» ويتضمن الكيانات المتميزة في التوطين، و«النطاق الأخضر المرتفع» ويشمل الكيانات المتوسطة من حيث نسب التوطين ضمن الثلث الأعلى وفق نسبة التوطين المطلوبة لذلك التصنيف.","كما يشمل تصنيف الوزارة، «النطاق الأخضر المتوسط» كيانات يقع متوسط نسب التوطين لديها ضمن الثلث المتوسط المحدد لذلك النطاق، و«النطاق الأخضر المنخفض»، ويشمل كيانات لديها متوسط نسب توطين ضمن الثلث المنخفض، وفقًا النسبة المحددة لذلك التصنيف، و«النطاق الأصفر»، ويشمل كيانات لم تحقق نسب التوطين المطلوبة، و«النطاق الأحمر» ويشمل الكيانات الأقل نسبة في توطين الوظائف."]','الوظائف وسوق العمل','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/jobs/dmfmar803','https://ajel.sa/jobs/dmfmar803','https://ajel.sa/jobs/dmfmar803','https://ajel.sa/jobs/dmfmar803','فريق التحرير','عسير','2026-08-29T04:11:00.000Z','Wed, 07 Oct 2026 21:18:11 GMT','2026-08-29T10:34:18.667Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=auto/https://cdn.ajel.sa/articles/2026-07/wozDJgh-_mSa5Imb.jpg','/api/media/852d9e9f-93c0-4ef6-b097-6dcf3c835685','/api/media/852d9e9f-93c0-4ef6-b097-6dcf3c835685?variant=thumbnail','«الموارد البشرية» تحث على متابعة الوظائف الشاغرة عبر منصة جدارات',1200,675,'valid','published','archived','valid',89,'d861e15010d11ceef54509a256d3b69a4d3b775731d886421781a9a1855bd4ce','6cf1d339844a5301a8513ae873ae6497d4948affcb5472ce5d3a91b686c55403','محدّث','2026-08-29T10:34:18.667Z','2026-10-07T21:18:14.151Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الموارد البشرية والتنمية الاجتماعية"]','["وزارة الموارد البشرية والتنمية الاجتماعية"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:18:14.151Z',200,58,0,'source_content_changed','',NULL,NULL,'body:1d0d16f315627010541bef256801310239be4fc9bc091c1b39c70abb124b2bfa','Wed, 07 Oct 2026 21:18:11 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e8c56980-0b92-4975-ba33-0ab8847560a1','news-e8c56980-0b92-4975-ba33-0ab8847560a1','فرحة سعودية يقودها الوفاء احتفالا بسوداني في ليلة عرس استثنائية','فرحه سعوديه يقودها الوفاء احتفالا بسوداني في ليله عرس استثنائيه','وثق مواطنون فرحتهم الغامرة بالوفاء احتفالا بسوداني في ليلة عرس استثنائية. وتحولت مظاهر الفرحة إلى فعاليات تؤكد روابط الاحترام والتقدير في تبوك شمال غرب المملكة ، وفق "العربية".','["وثق مواطنون فرحتهم الغامرة بالوفاء احتفالا بسوداني في ليلة عرس استثنائية.","وتحولت مظاهر الفرحة إلى فعاليات تؤكد روابط الاحترام والتقدير في تبوك شمال غرب المملكة ، وفق \"العربية\".","وقال المقيم السوداني بشير الدويحي، لطالما لمست مشاعر أهل المملكة الذين عاملوني كما لو كنت ابنا لهم، ونظموا لي حفل زواج مشرف وأحضروا عائلتي من السودان .","وتابع، أن ذلك مشهود عن أهل المملكة العربية السعودية حيث الطيبة والكرم، وأمضيت سنوات عملي في هذا البلد لم أجد من أهلها إلا كل خير."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/vf7cdhqi6','https://ajel.sa/local/vf7cdhqi6','https://ajel.sa/local/vf7cdhqi6','https://ajel.sa/local/vf7cdhqi6','فريق التحرير','تبوك','2026-08-29T04:31:00.000Z','Wed, 07 Oct 2026 18:59:01 GMT','2026-08-29T10:48:27.596Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/ai-edited/2026-08/CYt1pSusfHB_z77h.png','/api/media/e8c56980-0b92-4975-ba33-0ab8847560a1','/api/media/e8c56980-0b92-4975-ba33-0ab8847560a1?variant=thumbnail','فرحة سعودية يقودها الوفاء احتفالا بسوداني في ليلة عرس استثنائية',1200,675,'valid','published','archived','valid',46,'93c1adff98fb31d4a117fb94a59d10410affa37cc49c7703fe0f28432c5d8c4c','ba749acb48c21046981e230068999366d7ea6a35918c8511a7ed03da92a2e4a9','محدّث','2026-08-29T10:48:27.596Z','2026-10-07T18:59:03.423Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["تبوك"]','[]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T18:59:03.423Z',200,62,0,'source_content_changed','',NULL,NULL,'body:ed59ac17454da7149bb8c3f2ff8d51b8b278b31ae39a9ad1a93a27c0f9c8c49c','Wed, 07 Oct 2026 18:59:01 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1e299384-6e93-4e53-93a5-adadc8e00f64','news-1e299384-6e93-4e53-93a5-adadc8e00f64','استثمار صيني ضخم في المملكة.. السياحة والصناعة في الصدارة .. هذه الأرقام','استثمار صيني ضخم في المملكه السياحه والصناعه في الصداره هذه الارقام','تتجه الاستثمارات الصينية في المملكة العربية السعودية إلى مرحلة أكثر تنوعًا، بعدما تجاوز حضورها القطاعات التقليدية إلى مجالات الصناعة والتكنولوجيا والطاقة والتعدين والبنية التحتية، بالتوازي مع تنامي الاهتمام بقطاع السياحة والضيافة والاستفادة من النمو المتسارع الذي تشهده السوق السعودية. الصناعة في الصدارة وتكشف البيانات عن أن قطاع التصنيع يستحوذ على الحصة…','["وبحسب أحدث البيانات الصينية، بلغ رصيد الاستثمارات المباشرة الصينية في السعودية 4.26 مليارات دولار حتى نهاية عام 2025، في وقت حافظت فيه الصين على موقعها كأكبر شريك تجاري للمملكة، بينما تعد السعودية أكبر شريك تجاري للصين في المنطقة العربية.","وتجاوز حجم التجارة الثنائية بين البلدين 100 مليار دولار سنويًا خلال أربع سنوات متتالية، بما يعكس انتقال العلاقات السعودية الصينية من علاقة قائمة أساسًا على النفط والتجارة إلى شراكة أوسع تشمل الاستثمار والتصنيع ونقل التقنية والمشروعات الجديدة.","الصناعة في الصدارة وتكشف البيانات عن أن قطاع التصنيع يستحوذ على الحصة الأكبر من الاستثمارات الصينية في المملكة.","وكان رصيد الاستثمار الأجنبي المباشر الصيني في السعودية قد ارتفع من 24.1 مليار ريال في 2023 إلى 31.1 مليار ريال في 2024، بنمو بلغ 28.8%، فيما قفزت التدفقات الاستثمارية خلال العام نفسه من 3.2 مليارات ريال إلى 8.6 مليارات ريال، بزيادة 163.9%.","وشملت الاستثمارات الصينية، إلى جانب التصنيع، قطاعات الخدمات المالية والتأمين والإنشاءات والتعدين والتكنولوجيا والتجارة والبنية التحتية والرعاية الصحية.","وتتوافق هذه الاستثمارات مع تحول المملكة إلى قاعدة صناعية إقليمية، بعدما أصدرت وزارة الصناعة والثروة المعدنية خلال 2025 نحو 1,660 ترخيصًا صناعيًا جديدًا باستثمارات تجاوزت 76 مليار ريال، بينما دخل 1,201 مصنع مرحلة الإنتاج باستثمارات تزيد على 31 مليار ريال.","ويشير نائب وزير التجارة الصيني لينغ جي إلى أن الشركات الصينية توسعت في المملكة في مجالات رئيسية تشمل البتروكيماويات والطاقة الجديدة والصلب والصناعة التحويلية.","وهذه القطاعات تحديدًا تتوافق مع جانب رئيسي من خطط التنويع الاقتصادي السعودية، التي تستهدف توطين سلاسل التوريد والصناعات المتقدمة وزيادة المحتوى المحلي بدلًا من الاكتفاء باستيراد المنتجات النهائية."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/1rkv9pd','https://sabq.org/article/1rkv9pd','','https://sabq.org/article/1rkv9pd','خالد خليل','المدينة المنورة','2026-08-29T04:42:00.000Z','2026-08-29T07:43:00.000Z','2026-08-29T10:48:31.034Z','https://media.sabq.org/news/2026/08/a2a8dc18-8559-49e1-8c2a-42b32beea022/w726.webp','/api/media/1e299384-6e93-4e53-93a5-adadc8e00f64','/api/media/1e299384-6e93-4e53-93a5-adadc8e00f64?variant=thumbnail','استثمار صيني ضخم في المملكة.. السياحة والصناعة في الصدارة .. هذه الأرقام',726,484,'valid','published','archived','valid',52,'c003ceaaa0db8c8c9f73a65312974c459bfe6c75ced9739d1864c5e396abfc14','edd3c10513c9959dcf84ef7ed27a4c51bffe80fe1478133d76869f1dc4eab001','محدّث','2026-08-29T10:48:31.034Z','2026-10-07T21:21:57.936Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير التجارة الصيني لينغ جي","وزارة الصناعة والثروة المعدنية خلال","الطاقة والنفط","السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي","الصين"]','["وزير التجارة الصيني لينغ جي","وزارة الصناعة والثروة المعدنية خلال","الطاقة والنفط","السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"التقنية","score":1.5},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T21:21:57.936Z',200,65,0,'source_article_available','',NULL,NULL,'body:fe06c073aba3c85d23ef6523b7d80715eeb95acb73494237b951483251dc1c6f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('33463151-efa1-41d6-9d91-640e86891b91','news-33463151-efa1-41d6-9d91-640e86891b91','جمعية دعم الأوقاف تتولى نظارة وقف «العون» بقيمة تتجاوز 55 مليون ريال','جمعيه دعم الاوقاف تتولي نظاره وقف العون بقيمه تتجاوز 55 مليون ريال','وكشف اليوسف أن حجم الأصول التي تتولى الجمعية نظارتها حتى الآن بلغ نحو 70 مليون ريال، مؤكداً أن إسناد نظارة وقف «العون» يأتي في إطار التوسع في الخدمات التي تقدمها الجمعية للأوقاف والواقفين، وسعيها إلى بناء نماذج احترافية في إدارة الأصول الوقفية وتعظيم أثرها الاجتماعي والتنموي.','["أسندت نظارة وقف «العون» إلى جمعية دعم الأوقاف، وتبلغ قيمته الإجمالية أكثر من 55 مليون ريال، وبموجب هذا الإسناد تتولى الجمعية الإشراف على إدارة الوقف وتنفيذ شرط الواقف، بما يسهم في تعزيز كفاءة إدارة أصوله والمحافظة عليها وتنميتها وتحقيق أهدافه ومصارفه.","وأكد المشرف العام على جمعية دعم الأوقاف، صالح بن عبدالله اليوسف، أن وقف «العون» يمثل نموذجاً مميزاً للأوقاف ذات الأثر المجتمعي نظراً لتعدد مصارفه ومجالات نفعه، مشيراً إلى أن إسناد نظارته للجمعية يأتي امتداداً لجهودها في تطوير منظومة الإدارة الوقفية ورفع كفاءة الأوقاف وتعظيم أثرها.","وأوضح اليوسف أن الجمعية تنطلق في إدارتها للأوقاف من مفهوم متكامل يقوم على المحافظة على أصل الوقف وتنميته، وتحقيق شرط الواقف، وتعزيز الاستدامة المالية، ورفع كفاءة الأداء، وتطبيق الحوكمة والشفافية، بما يضمن استمرار أثر الوقف على المدى الطويل.","وتقدم الجمعية منظومة متكاملة من الخدمات الوقفية تشمل: النظارة والإشراف على الأوقاف، وإدارة الأصول والأملاك، والاستشارات الوقفية، وتنمية الأوقاف وتمكينها، إلى جانب الدعم الإداري والاستثماري وحوكمة الأوقاف.","وتعتمد الجمعية في أعمالها على كوادر وطنية مؤهلة ومتخصصة، جرى تأهيلهم عبر برامج ودبلومات ودورات علمية وعملية متخصصة.","وبيّن المشرف العام أن دور الجمعية في نظارة وقف «العون» يمتد إلى متابعة أداء مجلس النظارة، وإعداد اللوائح والسياسات، وتطبيق معايير الحوكمة والامتثال، ومتابعة الأداء المالي والإداري، وصرف ريع الوقف على مصارفه الخيرية البالغة ثلاثة عشر مصرفاً، من أبرزها: تعليم القرآن الكريم في مدينة الرياض، والعناية بالمساجد، وبرامج رعاية السجناء والمفرج عنهم وأسرهم، ورعاية الأيتام والأرامل، وإيواء المرضى النفسيين، وإكمال الأوقاف المتعثرة، وغيرها من مصارف الخير.","وأشار اليوسف إلى أن صرف هذه المصارف الخيرية سيتم عبر جمعيات خيرية رسمية حددها الواقف، وأن الجمعية ستعمل على تحقيق الاستخدام الأمثل لأصول الوقف من خلال الإشراف على أعمال الصيانة والتطوير، وتنمية الاستثمارات، وتحصيل إيرادات الوقف، وتمثيله أمام الجهات ذات العلاقة وحماية حقوقه."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/Rz_3DXc','https://sabq.org/article/Rz_3DXc','','https://sabq.org/article/Rz_3DXc','عيسى الحربي','الرياض','2026-08-29T04:39:00.000Z','2026-08-29T07:39:00.000Z','2026-08-29T10:49:12.152Z','https://media.sabq.org/news/2026/08/abd291f6-4561-454a-8344-4c9e411eb66f/w1200.webp','/api/media/33463151-efa1-41d6-9d91-640e86891b91','/api/media/33463151-efa1-41d6-9d91-640e86891b91?variant=thumbnail','جمعية دعم الأوقاف تتولى نظارة وقف «العون» بقيمة تتجاوز 55 مليون ريال',1200,675,'valid','published','archived','valid',85,'d983017848f41e3bdab264537a819f61d4d8a43dddce3535983ca4d46e743e35','d6c2512112eafa480393c4e0d190b4a09bea6d3b0052d93f042ba4f633f2df57','محدّث','2026-08-29T10:49:12.152Z','2026-10-07T21:21:43.663Z','','',0,0,'saudi_region','مهم',74,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس النظارة وإعداد اللوائح والسياسات","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق","الرياض"]','["مجلس النظارة وإعداد اللوائح والسياسات","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق"]','classified','','[{"category":"المناطق","score":5.5},{"category":"التقنية","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:21:43.663Z',200,61,0,'source_article_available','',NULL,NULL,'body:3b0d7dfd4afec2a9ff85c98bf72152c9c05116bb81e5630772e12ea4082b09f4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6ed7d9f7-92f2-4233-863f-f6ada54cd204','news-6ed7d9f7-92f2-4233-863f-f6ada54cd204','الداخلية: ضبط 14,434 مخالفًا لأنظمة الإقامة والعمل وأمن الحدود خلال أسبوع','الداخليه ضبط 14 434 مخالفا لانظمه الاقامه والعمل وامن الحدود خلال اسبوع','أسفرت الحملات الميدانية المشتركة لمتابعة وضبط مخالفي أنظمة الإقامة والعمل وأمن الحدود، التي نُفذت في جميع مناطق المملكة خلال الفترة من 20 إلى 26 أغسطس 2026، عن ضبط 14,434 مخالفًا.','["وتوزع المخالفون المضبوطون بين 6,976 مخالفًا لنظام الإقامة، و4,110 مخالفين لنظام أمن الحدود، و3,348 مخالفًا لنظام العمل.","بلغ عدد الأشخاص الذين تم ضبطهم خلال محاولتهم عبور الحدود إلى داخل المملكة 1,450 شخصًا؛ منهم 41٪ من الجنسية اليمنية، و58٪ من الجنسية الإثيوبية، و1٪ من جنسيات أخرى. كما تم ضبط 44 شخصًا لمحاولتهم عبور الحدود إلى خارج المملكة بطريقة غير نظامية.","وضبطت الجهات الأمنية 27 شخصًا لتورطهم في نقل وإيواء وتشغيل مخالفي الأنظمة والتستر عليهم.","يخضع حاليًا 29,938 وافدًا مخالفًا لإجراءات تنفيذ الأنظمة، بينهم 27,957 رجلًا و1,981 امرأة. وأحيل 18,914 مخالفًا إلى بعثاتهم الدبلوماسية للحصول على وثائق سفر، و2,867 مخالفًا لاستكمال حجوزات سفرهم، فيما تم ترحيل 14,905 مخالفين.","أكدت وزارة الداخلية أن كل من يسهل دخول مخالفي نظام أمن الحدود للمملكة أو نقلهم أو إيواءهم أو تقديم أي مساعدة لهم، يعرّض نفسه لعقوبات تصل إلى السجن 15 سنة وغرامة حتى مليون ريال، مع مصادرة وسيلة النقل والسكن المستخدم للإيواء والتشهير بالمخالف.","وأوضحت الوزارة أن هذه الجريمة تعد من الجرائم الكبيرة الموجبة للتوقيف والمخلة بالشرف والأمانة، وحثت على الإبلاغ عن أي حالات مخالفة على الرقم 911 في مناطق مكة المكرمة والمدينة المنورة و الرياض و المنطقة الشرقية ، و999 أو 996 في بقية المناطق."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/i7gnlva5e','https://ajel.sa/local/i7gnlva5e','https://ajel.sa/local/i7gnlva5e','https://ajel.sa/local/i7gnlva5e','فريق التحرير','الرياض','2026-08-29T04:36:00.000Z','Wed, 07 Oct 2026 19:04:53 GMT','2026-08-29T11:00:46.165Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-06/VcwlvthC3YMDvfZf.jpg','/api/media/6ed7d9f7-92f2-4233-863f-f6ada54cd204','/api/media/6ed7d9f7-92f2-4233-863f-f6ada54cd204?variant=thumbnail','الداخلية: ضبط 14,434 مخالفًا لأنظمة الإقامة والعمل وأمن الحدود خلال أسبوع',1200,675,'valid','published','archived','valid',40,'3291bda6e4ef9c4c60b1059d58fe51f70612a5ba6996ffa7cdbacaf04d0e16bb','1b7db1b522449672c57b8f1f37c308d6c14ae93a6ec8bc52292f647efcd18534','محدّث','2026-08-29T11:00:46.166Z','2026-10-07T20:24:32.060Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية أن كل من","السفر والسياحة","السياسة والعلاقات الدولية","مكة","اليمن","الرياض","المدينة المنورة"]','["وزارة الداخلية أن كل من","السفر والسياحة","السياسة والعلاقات الدولية","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:04:56.460Z',200,59,0,'source_content_changed','',NULL,NULL,'body:98993bdf2bdaebedb2bf4c9ca130b4fcc5f5dec07fdc24b38a250b061dd2bef2','Wed, 07 Oct 2026 19:04:53 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0a212ed6-3d91-4921-b93b-b893ba6d06e2','news-0a212ed6-3d91-4921-b93b-b893ba6d06e2','تنفيذ حكم القتل تعزيرًا بحق مواطن أدين بترويج الحشيش بالمدينة المنورة','تنفيذ حكم القتل تعزيرا بحق مواطن ادين بترويج الحشيش بالمدينه المنوره','نفذت الجهات المختصة في منطقة المدينة المنورة، اليوم السبت 16 ربيع الأول 1448هـ الموافق 29 أغسطس 2026م، حكم القتل تعزيرًا بحق فراس بن أحمد بن صالح الصباح (سعودي الجنسية)، بعد إدانته بترويج الحشيش المخدر للمرة الثانية عبر النقل.','["وأوضحت وزارة الداخلية في بيانها أن الجهات الأمنية تمكنت من القبض على الجاني، وأسفرت التحقيقات عن توجيه الاتهام إليه بارتكاب الجريمة. وبإحالته إلى المحكمة المختصة، صدر بحقه حكم يقضي بثبوت ما نُسب إليه وقتله تعزيرًا.","وأضافت الوزارة أن الحكم أصبح نهائيًا بعد استئنافه وتأييده من المحكمة العليا، كما صدر أمر ملكي بإنفاذ ما تقرر شرعًا.","أكدت وزارة الداخلية حرص حكومة المملكة على حماية أمن المواطن والمقيم من آفة المخدرات، مشددة على إيقاع أشد العقوبات بحق مهربيها ومروجيها لما تسببه من أضرار جسيمة على الفرد والمجتمع.","وحذرت الوزارة كل من يقدم على مثل هذه الأفعال بأن العقاب الشرعي سيكون مصيره، وذلك حفاظًا على أمن المجتمع وسلامته."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/b5bzw31n2','https://ajel.sa/local/b5bzw31n2','https://ajel.sa/local/b5bzw31n2','https://ajel.sa/local/b5bzw31n2','فريق التحرير','المدينة المنورة','2026-08-29T04:52:00.000Z','Wed, 07 Oct 2026 19:33:31 GMT','2026-08-29T11:09:46.503Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/P4UIAw0fDvR3GCKg.jpg','/api/media/0a212ed6-3d91-4921-b93b-b893ba6d06e2','/api/media/0a212ed6-3d91-4921-b93b-b893ba6d06e2?variant=thumbnail','تنفيذ حكم القتل تعزيرًا بحق مواطن أدين بترويج الحشيش بالمدينة المنورة',1200,675,'valid','published','archived','valid',56,'bf7af485867eb80444c4e24e3cc6601203aec94d563dad0830c670b8192f0a70','b731f7e6a41fe1de8683e6aa9ceb4a72e6bb38f719902f0fc75a2acdbe4e781c','محدّث','2026-08-29T11:09:46.503Z','2026-10-07T19:33:33.038Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية في بيانها أن","السفر والسياحة","المدينة المنورة"]','["وزارة الداخلية في بيانها أن","السفر والسياحة","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:33:33.038Z',200,51,0,'source_content_changed','',NULL,NULL,'body:eb88d5b1c676bf3800f1795d1f7c575d0c7e0a11d60bd15520e2be2300e12487','Wed, 07 Oct 2026 19:33:31 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('44b0153d-d610-4cf2-a340-91bb02f3cc88','news-44b0153d-d610-4cf2-a340-91bb02f3cc88','هل تحقق أجهزة قياس السكر المنزلية نتائج دقيقة؟.. استشاري يوضح','هل تحقق اجهزه قياس السكر المنزليه نتائج دقيقه استشاري يوضح','يوسف آل زاهب، إن أجهزة السكر المنزلية لها هامش تفاوت مقبول يقدر بحوالي 15% وقد تتأثر بقطرة الدم وطريقة القياس. وأشار عبر حسابه على منصة «إكس» إلى أن الجهاز المنزلي للمتابعة وليس لتشخيص السكري، مؤكدا أن التشخيص يكون بتحليل المختبر.','["قال استشاري أمراض السكري وطب الأسرة، د. يوسف آل زاهب، إن أجهزة السكر المنزلية لها هامش تفاوت مقبول يقدر بحوالي 15% وقد تتأثر بقطرة الدم وطريقة القياس.","وأشار عبر حسابه على منصة «إكس» إلى أن الجهاز المنزلي للمتابعة وليس لتشخيص السكري، مؤكدا أن التشخيص يكون بتحليل المختبر."]','التقنية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/6v6kds28m','https://ajel.sa/misc/6v6kds28m','https://ajel.sa/misc/6v6kds28m','https://ajel.sa/misc/6v6kds28m','فريق التحرير','','2026-08-29T04:49:00.000Z','Wed, 07 Oct 2026 19:33:34 GMT','2026-08-29T11:09:47.742Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%B3%D9%83%D8%B1%D9%8A-8GG31oVI.jpg','/api/media/44b0153d-d610-4cf2-a340-91bb02f3cc88','/api/media/44b0153d-d610-4cf2-a340-91bb02f3cc88?variant=thumbnail','هل تحقق أجهزة قياس السكر المنزلية نتائج دقيقة؟.. استشاري يوضح',1200,675,'valid','published','archived','valid',41,'e9cc02af59ccdd2de46c6e7e040a7e7dadbeae09c0b1e10633f8d821f9631c73','6fb5b4944f66b0111c82387e79621fea63166cc7ca7c526e0e4ba54fe657ee10','محدّث','2026-08-29T11:09:47.742Z','2026-10-07T20:24:32.065Z','','',0,0,'gulf_arab','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:33:37.162Z',200,50,0,'source_content_changed','',NULL,NULL,'body:7159797fcafb2ebf397127ea430be10ecf85c8bfb41052ac0e843d1b4b27db32','Wed, 07 Oct 2026 19:33:34 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4cfce7f3-47cb-45e9-9eb4-104bad6e9bc5','news-4cfce7f3-47cb-45e9-9eb4-104bad6e9bc5','بالصور "حاتوشا".. الوجهة الجديدة للسياح في تركيا..  تضم آثار حكام العالم القديم وأرشيف ملكي مثير وطبيعة خلابة','بالصور حاتوشا الوجهه الجديده للسياح في تركيا تضم اثار حكام العالم القديم وارشيف ملكي مثير وطبيعه خلابه','وتضم المدينة أرشيفًا استثنائيًا يزيد على 30 ألف لوح طيني، أُدرج ضمن برنامج «ذاكرة العالم» التابع لليونسكو، ما يجعلها واحدة من أهم المدن الأثرية في تركيا من حيث القيمة التاريخية والتوثيقية. وبذلك ارتفع عدد المقابر المعروفة من الفترتين الهلنستية المبكرة والغالاتية في حاتوشا إلى 17 مقبرة.','["تستعد حاتوشا، العاصمة القديمة للإمبراطورية الحيثية في تركيا، للظهور بقوة على خريطة السياحة الثقافية، مستفيدة من مزيج نادر يجمع بين آثار إحدى أعظم قوى العالم القديم، وأرشيف ملكي ضخم، واكتشافات أثرية جديدة، إلى جانب الطبيعة المحيطة بالموقع في ولاية تشوروم.","وتقع حاتوشا في منطقة بوغازكالي، وهي مدرجة على قائمة اليونسكو للتراث العالمي، وتعد من أهم المواقع التي توثق حضارة الحيثيين، إحدى أبرز القوى السياسية والعسكرية في العصر البرونزي.","وتضم المدينة أرشيفًا استثنائيًا يزيد على 30 ألف لوح طيني، أُدرج ضمن برنامج «ذاكرة العالم» التابع لليونسكو، ما يجعلها واحدة من أهم المدن الأثرية في تركيا من حيث القيمة التاريخية والتوثيقية.","أسرارًا جديدة وزادت جاذبية الموقع بعد أن كشفت أعمال التنقيب الأخيرة عن ثلاث مقابر جديدة تعود إلى الفترة الممتدة من أواخر القرن الرابع وحتى القرن الثالث قبل الميلاد.","وبذلك ارتفع عدد المقابر المعروفة من الفترتين الهلنستية المبكرة والغالاتية في حاتوشا إلى 17 مقبرة.","ومن أبرز الاكتشافات مقبرة محاطة بجدار حجري دائري يبلغ قطره نحو 7 أمتار، وعُثر داخلها على هيكل عظمي محفوظ وسكين بجوار الكتف الأيمن للمتوفى، فيما يدرس علماء الآثار ما إذا كانت السكين جزءًا من طقوس الدفن أو إحدى ممتلكاته الشخصية.","عاصمة «ملوك العالم القديم» في أوج قوتها، كانت الإمبراطورية الحيثية تمتد من ساحل بحر إيجة إلى شمال سوريا، وتسيطر على طرق تجارية مهمة، بينما شكلت حاتوشا مركز الحكم والإدارة والقرار.","وكانت المدينة تُعرف باسم «مدينة الألف معبد»، وتضم اليوم معابد ضخمة وقصورًا ملكية وأسوارًا وبوابات حجرية مهيبة، من بينها بوابة الأسد وبوابة الملك وبوابة أبو الهول."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ay7cpaa','https://sabq.org/article/ay7cpaa','','https://sabq.org/article/ay7cpaa','خالد خليل','المدينة المنورة','2026-08-29T05:16:00.000Z','2026-08-29T08:16:00.000Z','2026-08-29T11:18:48.950Z','https://media.sabq.org/news/2026/08/e2765f08-be72-400e-b08a-02ba3b80911b/w1600.webp','/api/media/4cfce7f3-47cb-45e9-9eb4-104bad6e9bc5','/api/media/4cfce7f3-47cb-45e9-9eb4-104bad6e9bc5?variant=thumbnail','بالصور "حاتوشا".. الوجهة الجديدة للسياح في تركيا..  تضم آثار حكام العالم القديم وأرشيف ملكي مثير وطبيعة خلابة',1600,900,'valid','published','archived','valid',35,'65e143c251eb32ffc70fd59bb8d110239e89ae53fe571d3fb595073c2ac7e9cd','e35cc93aa0ab84deca947bbe14b05b45be56da4d86c2ae169532f128baa61127','محدّث','2026-08-29T11:18:48.950Z','2026-10-07T20:24:32.069Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","السفر والسياحة","السياسة والعلاقات الدولية","سوريا","تركيا"]','["الطاقة والنفط","السفر والسياحة","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:34:40.565Z',200,61,0,'source_article_available','',NULL,NULL,'body:ad01be21833d9b679961750fff6b4226de35ac5ec3ca698227c5cad94f669461','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('748765d5-71c8-4c89-ae77-4280c60f1c46','news-748765d5-71c8-4c89-ae77-4280c60f1c46','حرارة «روشن» تشعل الجدل: سبتمبر أم تكييف الملاعب لحماية الجماهير؟','حراره روشن تشعل الجدل سبتمبر ام تكييف الملاعب لحمايه الجماهير','فتحت أكثر من 40 حالة إغماء وإعياء رُصدت في مدرجات ملعب الأمير محمد بن فهد بالدمام، خلال مواجهة الهلال والخليج مساء الجمعة 28 أغسطس 2026، ملفَّ توقيت انطلاق منافسات دوري روشن السعودي للمحترفين في ظل ارتفاع درجات الحرارة والرطوبة، وأعادت إلى الواجهة سؤالاً يتجاوز حدود مباراة واحدة: هل يستدعي تغيُّر الظروف المناخية إعادة النظر في موعد بداية الموسم، أم أن…','["وجاءت الواقعة وسط أجواء حارة ورطبة، إذ رصدت تقارير إعلامية أكثر من 40 حالة بين إغماء وهبوط وصداع في محيط البوابة رقم 12 بالملعب، ما وسَّع دائرة النقاش من حدود التعامل مع مباراة بعينها إلى مدى جاهزية المنشآت الرياضية لاستضافة المباريات في أشهر الصيف، ولا سيما في المناطق الساحلية ذات الرطوبة المرتفعة.","وفيما دعا الإعلامي الرياضي وليد الفراج إلى دراسة تأجيل انطلاق دوري روشن من أغسطس إلى سبتمبر، معتبراً أن التغيرات المناخية تستدعي إعادة تقييم الروزنامة الرياضية، يرى منتقدو هذه الفكرة أن تأخير البداية شهراً واحداً قد لا يكون كافياً، خصوصاً مع استمرار الرطوبة في المنطقة الشرقية إلى فترات لاحقة من العام.","أكثر من 40 حالة في محيط بوابة واحدة لم تكن نتيجة المباراة وحدها محور الاهتمام بعد مواجهة الهلال والخليج؛ إذ طغت الظروف المناخية على المشهد، بعدما نقل مراسل برنامج «روتانا سبورت» في المنطقة الشرقية رصد أكثر من 40 حالة بين إغماء وهبوط وصداع في محيط البوابة رقم 12، وسط أجواء اتسمت بارتفاع الحرارة والرطوبة.","ولا يعني تسجيل هذه الحالات بالضرورة أن الحرارة والرطوبة كانتا السبب الطبي المباشر في كل حالة، إذ يتطلب تحديد السبب تقييماً طبياً لكل حالة على حدة، إلا أن تزامنها مع الأجواء المناخية الصعبة أعاد تسليط الضوء على مخاطر الإجهاد الحراري في التجمعات الجماهيرية.","وتكتسب المسألة أهمية أكبر عندما يتعلق الأمر بالأطفال وكبار السن والأشخاص الأكثر تأثراً بالحرارة، إضافة إلى الجماهير التي تنتظر لفترات طويلة عند البوابات أو تتحرك في مناطق مكتظة تفتقر إلى التهوية الكافية.","وفي مشهد لافت، اضطر أحد الأطفال إلى مغادرة المدرجات بين الشوطين بعد عجزه عن تحمُّل الأجواء الحارة والرطبة.","الفراج: «سبتمبر» قد يكون بداية الحل كان الإعلامي الرياضي وليد الفراج، مقدم برنامج «روتانا سبورت مع وليد»، من أبرز من طرحوا إعادة النظر في توقيت بداية الموسم، داعياً إلى دراسة نقل انطلاقة دوري روشن من أغسطس إلى سبتمبر.","وأشار الفراج إلى أن التغيرات المناخية دفعت عدداً من الدول إلى إعادة النظر في توقيت مسابقاتها الرياضية، داعياً لجنة المسابقات في رابطة دوري المحترفين، بالتنسيق مع الاتحاد السعودي لكرة القدم، إلى دراسة بدء الدوري في سبتمبر بدلاً من أغسطس، بما يخفف من تعرض اللاعبين والجماهير للحرارة والرطوبة المرتفعة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/k5XW1eo','https://sabq.org/article/k5XW1eo','','https://sabq.org/article/k5XW1eo','عبدالحكيم شار','الرياض','2026-08-29T05:09:00.000Z','2026-08-29T08:10:00.000Z','2026-08-29T11:18:49.275Z','https://media.sabq.org/news/2026/08/993a89d6-2053-4310-899f-0a5482a8dfa5/w1125.webp','/api/media/748765d5-71c8-4c89-ae77-4280c60f1c46','/api/media/748765d5-71c8-4c89-ae77-4280c60f1c46?variant=thumbnail','حرارة «روشن» تشعل الجدل: سبتمبر أم تكييف الملاعب لحماية الجماهير؟',1125,788,'valid','published','archived','valid',99,'ed9e1401119e5d3258a0ca6d582f85408a643315a998c6526e5d4b6ad236eec5','4dda5453907844344fa98f7fdbb3ff1bf271874cc6a18ba6ce08cb843b44b7e7','محدّث','2026-08-29T11:18:49.275Z','2026-10-07T19:34:36.751Z','','',0,0,'saudi_region','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","الرياضة السعودية","الرياض","الدمام"]','["الطقس والمناخ","الرياضة السعودية"]','classified','','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":-2}]','Active','2026-10-07T19:34:36.751Z',200,61,0,'source_article_available','',NULL,NULL,'body:d3640fb74095eee8df0157835b7313a0f34507000bfbfaf33255e6f0e0dd0437','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('696b9fb3-7ed3-4e0a-b987-817faf8edc01','news-696b9fb3-7ed3-4e0a-b987-817faf8edc01','«زاتكا» تضبط 1078 حالة تهريب في المنافذ الجمركية البرية والبحرية والجوية','زاتكا تضبط 1078 حاله تهريب في المنافذ الجمركيه البريه والبحريه والجويه','وأكدت «زاتكا» أنها ماضية في إحكام الرقابة الجمركية على واردات المملكة وصادراتها، تحقيقاً لأمن المجتمع وحمايته، بالتعاون والتنسيق المتواصل مع جميع الجهات الشريكة ذات العلاقة.','["ضبطت هيئة الزكاة والضريبة والجمارك «زاتكا» 1078 حالة للممنوعات عبر المنافذ الجمركية البرية والبحرية والجوية، وذلك في إطار جهودها المستمرة لتعزيز الرقابة الجمركية وحماية المجتمع من الممنوعات بمختلف أنواعها.","وشملت الأصناف المضبوطة 107 أصناف من المواد المخدرة، من بينها الحشيش والكوكايين والهيروين والشبو وحبوب الكبتاجون وغيرها، فضلاً عن 402 صنف من المواد المحظورة، في حين بلغت ضبطيات التبغ ومشتقاته 2024 حالة، إلى جانب 30 صنفاً لمبالغ مالية، وصنفين من الأسلحة ومستلزماتها.","ودعت الهيئة المواطنين والمقيمين إلى الإسهام في مكافحة التهريب وحماية المجتمع والاقتصاد الوطني، عبر التواصل معها على الرقم المخصص للبلاغات الأمنية (1910)، أو البريد الإلكتروني (1910@zatca.gov.sa)، أو الرقم الدولي (009661910)، مشيرةً إلى أنها تستقبل البلاغات المتعلقة بجرائم التهريب ومخالفات نظام الجمارك الموحد بسرية تامة، مع منح مكافأة مالية للمُبلّغ في حال صحة المعلومات."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/s689kj0','https://sabq.org/article/s689kj0','','https://sabq.org/article/s689kj0','صحيفة سبق','المدينة المنورة','2026-08-29T05:22:00.000Z','2026-08-29T08:23:00.000Z','2026-08-29T11:27:48.158Z','https://media.sabq.org/news/2026/08/3b418265-e237-4b35-8db9-a54b970634e6/w1600.webp','/api/media/696b9fb3-7ed3-4e0a-b987-817faf8edc01','/api/media/696b9fb3-7ed3-4e0a-b987-817faf8edc01?variant=thumbnail','«زاتكا» تضبط 1078 حالة تهريب في المنافذ الجمركية البرية والبحرية والجوية',1600,901,'valid','published','archived','valid',46,'3e3f313465fee266ba7bbedbfe5a478bb2daf4d8e2b933a220ea5b2ba7f7ac19','013cdeb9529f5d16b5ec42e9dde718315c800f5ca923adf9be69f9595841fc4c','محدّث','2026-08-29T11:27:48.159Z','2026-10-07T19:52:48.754Z','','',0,0,'saudi_region','مهم',69,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الزكاة والضريبة والجمارك زاتكا","الصحة العامة","الاقتصاد والأسواق"]','["هيئة الزكاة والضريبة والجمارك زاتكا","الصحة العامة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:52:48.754Z',200,58,0,'source_article_available','',NULL,NULL,'body:5dcc41e10a0524ba7f9b1a833abfb5917a965c9e7ccd6e1b3e5248e2b49b4571','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bd2736cb-4bc4-4ed2-b240-5894f3ba999a','news-bd2736cb-4bc4-4ed2-b240-5894f3ba999a','«المنافذ الجمركية»: تسجيل 1078 حالة ضبط للممنوعات خلال أسبوع','المنافذ الجمركيه تسجيل 1078 حاله ضبط للممنوعات خلال اسبوع','أعلنت المنافذ الجمركية البرية والبحرية والجوية، تسجيل 1078 حالة ضبط للممنوعات، وذلك في إطار الجهود المستمرة التي تبذلها هيئة الزكاة والضريبة والجمارك «زاتكا»؛ لتعزيز الجانب الأمني وحماية المجتمع من الممنوعات بمختلف أنواعها وأشكالها.','["وشملت الأصناف المضبوطة 107 صنفًا من المواد المخدرة، مثل: الحشيش، والكوكايين، والهيروين، والشبو، وحبوب الكبتاجون وغيرها، إضافةً إلى 402 صنفًا من المواد المحظورة.","كما شهدت المنافذ الجمركية إحباط 2024 من التبغ ومشتقاته، إلى جانب 30 صنفًا لمبالغ مالية، وصنفين لأسلحة ومستلزماتها.","وأكدت \"زاتكا\" أنها ماضية في إحكام الرقابة الجمركية على واردات المملكة وصادراتها؛ تحقيقًا لأمن المجتمع وحمايته، وذلك بالتعاون والتنسيق المتواصل مع جميع شركائها من الجهات ذات العلاقة.","ودعت \"زاتكا\" في الوقت ذاته الجميع إلى الإسهام في مكافحة التهريب لحماية المجتمع والاقتصاد الوطني، من خلال التواصل معها عبر الرقم المخصص للبلاغات الأمنية (1910)، أو البريد الإلكتروني ( [email&#160;protected] )، أو الرقم الدولي (009661910)، حيث تستقبل الهيئة من خلال هذه القنوات البلاغات المرتبطة بجرائم التهريب ومخالفات أحكام نظام الجمارك الموحد بسرية تامة، مع منح مكافأة مالية للمُبلّغ في حال صحة معلومات البلاغ."]','أخبار السعودية','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/ybzj5zaw9','https://ajel.sa/local/ybzj5zaw9','https://ajel.sa/local/ybzj5zaw9','https://ajel.sa/local/ybzj5zaw9','فريق التحرير','المدينة المنورة','2026-08-29T05:26:00.000Z','Mon, 07 Sep 2026 00:50:51 GMT','2026-08-29T11:36:47.535Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%AA%D9%87%D8%B1%D9%8A%D8%A8-BKQ3dg9q.jpg','/api/media/bd2736cb-4bc4-4ed2-b240-5894f3ba999a','/api/media/bd2736cb-4bc4-4ed2-b240-5894f3ba999a?variant=thumbnail','«المنافذ الجمركية»: تسجيل 1078 حالة ضبط للممنوعات خلال أسبوع',1200,675,'valid','published','archived','valid',40,'29bf93c05822535c640414e95905948577cb8ce25fd683c56151cf743e59a9e0','4a66505c582d9b9ab1f19ad03f0d7596ee055869e14dbd23b54e99d177a031a4','محدّث','2026-08-29T11:36:47.535Z','2026-10-07T19:59:17.422Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","هيئة الزكاة والضريبة والجمارك زاتكا","الصحة العامة","الاقتصاد والأسواق"]','["هيئة الزكاة والضريبة والجمارك زاتكا","الصحة العامة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:59:17.422Z',NULL,76,5,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('99786a6c-ee3c-4396-a426-e710d2e1f3dd','news-99786a6c-ee3c-4396-a426-e710d2e1f3dd','العالمي للسفر : السعودية تقترب من الاستحواذ على نصف اقتصاد السفر والسياحة في الشرق الأوسط.. 46% حصة تاريخية','العالمي للسفر السعوديه تقترب من الاستحواذ علي نصف اقتصاد السفر والسياحه في الشرق الاوسط 46 حصه تاريخيه','46 دولارًا من كل 100 دولار وتكشف الأرقام حجم القفزة التي حققتها السياحة السعودية؛ إذ بلغت مساهمة السفر والسياحة في اقتصاد الشرق الأوسط ككل نحو 385.8 مليار دولار خلال 2025.','["اقتربت المملكة العربية السعودية من الاستحواذ على نصف اقتصاد السفر والسياحة في الشرق الأوسط، بعدما استحوذت وحدها على 46% من إجمالي مساهمة القطاع في اقتصاد المنطقة خلال عام 2025، وفق أحدث بيانات المجلس العالمي للسفر والسياحة WTTC.","وبحسب نتائج تقرير الأثر الاقتصادي للسفر والسياحة 2026، بلغت مساهمة القطاع في الاقتصاد السعودي خلال 2025 نحو 178 مليار دولار، أي ما يعادل قرابة 667.5 مليار ريال سعودي، لتصبح المملكة أكبر اقتصاد للسفر والسياحة في الشرق الأوسط. 46 دولارًا من كل 100 دولار وتكشف الأرقام حجم القفزة التي حققتها السياحة السعودية؛ إذ بلغت مساهمة السفر والسياحة في اقتصاد الشرق الأوسط ككل نحو 385.8 مليار دولار خلال 2025.","ومن هذا المبلغ، جاءت 178 مليار دولار من السعودية وحدها، وهو ما يعني أن المملكة استحوذت على 46 دولارًا تقريبًا من كل 100 دولار ولدها اقتصاد السفر والسياحة في المنطقة.","وبذلك أصبحت السعودية على بعد 4 نقاط مئوية فقط من الوصول إلى نصف اقتصاد السفر والسياحة في الشرق الأوسط.","نمو سعودي يتفوق ولم يأتِ الرقم التاريخي نتيجة حجم السوق فقط، بل جاء مدعومًا بمعدلات نمو تفوقت على المتوسطين الإقليمي والعالمي.","فقد نما اقتصاد السفر والسياحة في المملكة بنسبة 7.4% خلال 2025، مقابل 5.3% في الشرق الأوسط و4.1% عالميًا.","وهذا يعني أن نمو القطاع السعودي كان أعلى بنحو 40% من متوسط نمو الشرق الأوسط، واقترب من ضعف معدل نمو القطاع عالميًا.","إنفاق يرتفع 8.2% وسجلت المملكة أيضًا أداءً قويًا في إنفاق الزوار الدوليين، الذي ارتفع بنسبة 8.2% خلال 2025."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/hkzfbpk','https://sabq.org/article/hkzfbpk','','https://sabq.org/article/hkzfbpk','صحيفة سبق','','2026-08-29T05:25:00.000Z','2026-08-29T08:26:00.000Z','2026-08-29T11:36:48.432Z','https://media.sabq.org/news/2026/08/0a880818-ea67-40ac-a7bf-ac3205431477/w1200.webp','/api/media/99786a6c-ee3c-4396-a426-e710d2e1f3dd','/api/media/99786a6c-ee3c-4396-a426-e710d2e1f3dd?variant=thumbnail','العالمي للسفر : السعودية تقترب من الاستحواذ على نصف اقتصاد السفر والسياحة في الشرق الأوسط.. 46% حصة تاريخية',1200,675,'valid','published','archived','valid',51,'57cdb7c7883127003d0f4144303657f1f65cdd146e03a72355d366f83bc8b9a1','43acb59146a63fc3795d0de2d360c9d5b62b8e6f8198f664f89f5c3e73f37ed5','محدّث','2026-08-29T11:36:48.432Z','2026-10-07T19:59:38.497Z','','',0,0,'saudi_national','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الاقتصاد والأسواق","الشرق الأوسط"]','["السفر والسياحة","الاقتصاد والأسواق","الشرق الأوسط"]','needs_review','below_category_threshold','[{"category":"التقنية","score":2},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Temporarily Unreachable','2026-10-07T19:59:38.497Z',NULL,75,5,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cc0389d7-db15-4258-8f00-bd1a8f41461c','news-cc0389d7-db15-4258-8f00-bd1a8f41461c','القبض على 3 مقيمين كينيين بالرياض لترويجهم 17 كيلو جراما من الحشيش المخدر','القبض علي 3 مقيمين كينيين بالرياض لترويجهم 17 كيلو جراما من الحشيش المخدر','ألقت المديرية العامة لمكافحة المخدرات القبض على 3 مقيمين من الجنسية الكينية بمنطقة الرياض لترويجهم 17 كيلو جراما من الحشيش المخدر. وتهيب الجهات الأمنية بالمواطنين والمقيمين الإبلاغ عن أي معلومات تتعلق بتهريب أو ترويج المخدرات، وذلك عبر الرقم (911) في مناطق مكة المكرمة والمدينة المنورة والرياض و المنطقة الشرقية ، والرقمين (999) و(994) في بقية مناطق…','["ألقت المديرية العامة لمكافحة المخدرات القبض على 3 مقيمين من الجنسية الكينية بمنطقة الرياض لترويجهم 17 كيلو جراما من الحشيش المخدر.","وتم إيقافهم واتخاذ الإجراءات النظامية بحقهم، وإحالتهم إلى النيابة العامة .","وتهيب الجهات الأمنية بالمواطنين والمقيمين الإبلاغ عن أي معلومات تتعلق بتهريب أو ترويج المخدرات، وذلك عبر الرقم (911) في مناطق مكة المكرمة والمدينة المنورة والرياض و المنطقة الشرقية ، والرقمين (999) و(994) في بقية مناطق المملكة ، أو عبر رقم بلاغات المديرية العامة لمكافحة المخدرات (995)، أو البريد الإلكتروني ( [email&#160;protected] )، مؤكدة أن جميع البلاغات ستُعالج بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/m1x4c8qwi','https://ajel.sa/local/m1x4c8qwi','https://ajel.sa/local/m1x4c8qwi','https://ajel.sa/local/m1x4c8qwi','فريق التحرير','الرياض','2026-08-29T05:26:00.000Z','Mon, 07 Sep 2026 00:50:49 GMT','2026-08-29T11:36:49.142Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%85%D8%AE%D8%AF%D8%B1%D8%A7%D8%AA-3-oE8bg_hP.jpg','/api/media/cc0389d7-db15-4258-8f00-bd1a8f41461c','/api/media/cc0389d7-db15-4258-8f00-bd1a8f41461c?variant=thumbnail','القبض على 3 مقيمين كينيين بالرياض لترويجهم 17 كيلو جراما من الحشيش المخدر',1200,675,'valid','published','archived','valid',40,'e311b614f5e23fae52ed12d1db83e11b24b683e6dd894a8cfcc328f481a4d335','a5bca45a15180a77b1954a8aab4aa19982d5107afeec449dcf786cf13bfbd37d','محدّث','2026-08-29T11:36:49.142Z','2026-10-07T20:24:32.086Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي","مكة","الرياض","المدينة المنورة"]','["التقنية والتحول الرقمي","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:58:56.294Z',NULL,71,4,'temporary_network_error: fetch failed','',NULL,NULL,'','');
