INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4d519ec4-3d7b-402c-ba2f-7eb087dd6686','news-4d519ec4-3d7b-402c-ba2f-7eb087dd6686','«حساب المواطن» يوضح موقف دعم الأسرة في حالة خروج تابع وتسجيله كفرد مستقل','حساب المواطن يوضح موقف دعم الاسره في حاله خروج تابع وتسجيله كفرد مستقل','أوضح برنامج حساب المواطن موقف التابع في البرنامج في حالة تسجيله كفرد مستقبل. وأكد البرنامج، عبر منصة إكس ، ردًا على سؤال أحد المستفيدين بشأن تقديمه كفرد مستقل في حساب المواطن وهل يؤثر ذلك على الدعم لوالده، أنه في حال تم قبول المتقدم كفرد مستقل سيصبح تابع "غير مؤهل" في حساب رب الأسرة، وسيتم دراسة استحقاق رب الأسرة مرة أخرى دون احتسابه.','["أوضح برنامج حساب المواطن موقف التابع في البرنامج في حالة تسجيله كفرد مستقبل.","وأضاف أنه في حال كان مؤهلًا ومستحق سيشمله الدعم، ولمعرفة قيمة الاستحقاق والحد المانع من الحصول على الدعم باستخدام حاسبة الدعم التقديرية portal.ca.gov.sa."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/q9392o0uv','https://ajel.sa/thehour/q9392o0uv','https://ajel.sa/thehour/q9392o0uv','https://ajel.sa/thehour/q9392o0uv','فريق التحرير','','2026-08-29T05:48:00.000Z','Wed, 07 Oct 2026 20:27:59 GMT','2026-08-29T13:51:49.581Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%AD%D8%B3%D8%A7%D8%A8-%D8%A7%D9%84%D9%85%D9%88%D8%A7%D8%B7%D9%86-gTitmVYJ.jpg','/api/media/4d519ec4-3d7b-402c-ba2f-7eb087dd6686','/api/media/4d519ec4-3d7b-402c-ba2f-7eb087dd6686?variant=thumbnail','«حساب المواطن» يوضح موقف دعم الأسرة في حالة خروج تابع وتسجيله كفرد مستقل',1200,675,'valid','published','archived','valid',41,'049b4ac1189a50b97c07aa56fb16a32301a9ee0d1e445efb3c91f32a22c329dc','090fe222ca937c90962051230fbba1db908c804241f871c41205351626caa3fa','محدّث','2026-08-29T11:54:46.323Z','2026-10-07T20:28:01.272Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:28:01.272Z',200,60,0,'source_content_changed','',NULL,NULL,'body:86a10e2dda762f0632936476561b0cafd87996cb4894dabceb7d0022d38f2e99','Wed, 07 Oct 2026 20:27:59 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1ee0b49f-1fa4-41c2-bef4-9582150c34c2','news-1ee0b49f-1fa4-41c2-bef4-9582150c34c2','القبض على 3 مخالفين من الجنسيتين الإثيوبية واليمنية لتهريبهم 40 كيلوجراما من القات','القبض علي 3 مخالفين من الجنسيتين الاثيوبيه واليمنيه لتهريبهم 40 كيلوجراما من القات','ألقت الدوريات البرية لحرس الحدود في قطاع الدائر ب منطقة جازان القبض على 3 مخالفين لنظام أمن الحدود من الجنسيتين الإثيوبية واليمنية، لتهريبهم (40) كيلوجرام من نبات القات المخدر.','["تم استكمال الإجراءات النظامية الأولية بحقهم، وتسليمهم والمضبوطات لجهة الاختصاص.","وتهيب الجهات الأمنية بالإبلاغ عن كل ما يتوافر من معلومات لدى المواطنين والمقيمين عن أي نشاطات ذات صلة بتهريب أو ترويج المخدرات، وذلك من خلال الاتصال بالأرقام (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض و الشرقية و(999) و(994) في بقية مناطق المملكة ، ورقم بلاغات المديرية العامة لمكافحة المخدرات (995)، وعبر البريد الإلكتروني: (Email: [email&#160;protected] )، وستعالج جميع البلاغات بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/dtfibk9n5','https://ajel.sa/local/dtfibk9n5','https://ajel.sa/local/dtfibk9n5','https://ajel.sa/local/dtfibk9n5','فريق التحرير','الرياض','2026-08-29T05:48:00.000Z','Wed, 07 Oct 2026 20:27:56 GMT','2026-08-29T11:54:47.496Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%AD%D8%B1%D8%B3-3333-Vl-pNFAl.jpg','/api/media/1ee0b49f-1fa4-41c2-bef4-9582150c34c2','/api/media/1ee0b49f-1fa4-41c2-bef4-9582150c34c2?variant=thumbnail','القبض على 3 مخالفين من الجنسيتين الإثيوبية واليمنية لتهريبهم 40 كيلوجراما من القات',1200,675,'valid','published','archived','valid',40,'3698e17097b4f9d2b1b3303f4529cc51b93e6002dc0e9d323590043af0a3d929','3ef468562a3877b93e83f8872ab8076a1eeb84755ab7f7a7e05fba4a7f896397','محدّث','2026-08-29T11:54:47.496Z','2026-10-07T20:27:58.527Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","مكة","جازان","اليمن","الرياض","المدينة المنورة"]','["الرياضة السعودية","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:27:58.527Z',200,61,0,'source_content_changed','',NULL,NULL,'body:b261c7edbe6153af8d3dffe9810aa1dabdaaf6e60e29340214bf93b86749d04d','Wed, 07 Oct 2026 20:27:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('72ad0edb-b969-4dce-8d1a-89a1956fa146','news-72ad0edb-b969-4dce-8d1a-89a1956fa146','«شؤون الحرمين» توضح إمكانية حجز العربات الكهربائية بالحرمين عبر رقم جوال خليجي','شؤون الحرمين توضح امكانيه حجز العربات الكهربائيه بالحرمين عبر رقم جوال خليجي','وأوضح الحساب، ردا على أحد المستفيدين بشأن حجز العربات الكهربائية برقم خليجي، أنه يمكن أيضاً إتمام الحجز عبر البريد الإلكتروني الشخصي من خلال منصة التنقل الموحدة.','["قال حساب العناية بضيوف الحرمين، التابع للهيئة العامة للعناية بشؤون الحرمين الشريفين، إنه يتاح حجز العربات الكهربائية من داخل المملكة باستخدام رقم جوال خليجي.","وتتيح الهيئة في المسجد الحرام خدمة توفير عربات كهربائية ويدوية لتسهيل طواف وسعي وتنقل الحجاج والمعتمرين وكبار السن على مدار الساعة.","وتوفر الهيئة لضيوف الرحمن عربات مجانية وكهربائية تساعدهم في أداء مناسكهم بكل يسر وسهولة، من خلال توفير 5000 عربة عادية، بالإضافة إلى الإشراف على أكثر من 6000 دافع عربة مع منحهم تصاريح العمل بعد استيفاء الشروط اللازمة، مع مراقبة جودة الخدمة على مدار الساعة.","كما تم تخصيص مواقع متنوعة للعربات الكهربائية واليدوية ودافعي العربات في المسجد الحرام، مثل الساحات الجنوبية والغربية والشرقية، بالإضافة إلى تواجد عربات القولف في مناطق محددة مثل: جسر أجياد من الداخلي، و الشبكية (بجوار جسر الشبكية)، وتُعتبر هذه الخدمات جزءاً من اهتمام الهيئة بتوفير الراحة للزوار، خاصة كبار السن وذوي الإعاقة وتعمل على تسهيل الطواف والسعي خلال مواسم الحج والعمرة."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/njljo3t1z','https://ajel.sa/thehour/njljo3t1z','https://ajel.sa/thehour/njljo3t1z','https://ajel.sa/thehour/njljo3t1z','فريق التحرير','المنطقة الشرقية','2026-08-29T05:48:00.000Z','Wed, 07 Oct 2026 20:28:02 GMT','2026-08-29T13:51:50.625Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/1000280693-crop-Z2TZ9Z-V.jpg','/api/media/72ad0edb-b969-4dce-8d1a-89a1956fa146','/api/media/72ad0edb-b969-4dce-8d1a-89a1956fa146?variant=thumbnail','«شؤون الحرمين» توضح إمكانية حجز العربات الكهربائية بالحرمين عبر رقم جوال خليجي',1200,675,'valid','published','archived','valid',40,'a1f1c1630ca0cc9e2ca7d566943f1a233660754cb6bdb6d641abd98d08306672','1d5e82c7846f90a9cdc9cb92470394b3a3c32383e3508ba9bd7e86c677617ad6','محدّث','2026-08-29T11:54:49.240Z','2026-10-07T20:28:03.743Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["المنطقة الشرقية"]','["المنطقة الشرقية"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:28:03.743Z',200,59,0,'source_content_changed','',NULL,NULL,'body:bf6fb96d05adf656aca1da3071208ef94f599534889f8f0c6547ea634255a002','Wed, 07 Oct 2026 20:28:02 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('daf76411-7e20-4924-8deb-e3b69199c9e2','news-daf76411-7e20-4924-8deb-e3b69199c9e2','المجلس العسكري بالنيجر يعلن استعادة السيطرة تدريجيا على الوضع','المجلس العسكري بالنيجر يعلن استعاده السيطره تدريجيا علي الوضع','أعلن المجلس العسكري في النيجر استعادة السيطرة تدريجيا على الوضع بعد ساعات من إطلاق نار في عاصمة البلاد. وفي المقابل بدأت قوات الأمن عمليات تفتيش وأعلن مسؤولون تحييد المهاجمين وفرار آخرين منهم، في هذا البلد الذي يحكمه الجيش منذ انقلاب 2023م، عقب الإطاحة بالرئيس محمد بازوم.','["أعلن المجلس العسكري في النيجر استعادة السيطرة تدريجيا على الوضع بعد ساعات من إطلاق نار في عاصمة البلاد.","وشهدتالعاصمة النيجيرية نيامي ، إطلاق نار متواصل وانفجارات سُمع في عدة مناطق منها صباح اليوم السبت.","وهاجم إرهابيون مطار ديوري هاماني الدولي بالمدينة وحاولوا اختراق الطوق الأمني المحيط بمقر الرئاسة، كما استهدف المهاجمون القاعدة 101، وهي منشأة عسكرية رئيسية في نيامي، لكن قوات الأمن استعادت السيطرة عليها.","وفي المقابل بدأت قوات الأمن عمليات تفتيش وأعلن مسؤولون تحييد المهاجمين وفرار آخرين منهم، في هذا البلد الذي يحكمه الجيش منذ انقلاب 2023م، عقب الإطاحة بالرئيس محمد بازوم."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/p4xge2kq8','https://ajel.sa/international/p4xge2kq8','https://ajel.sa/international/p4xge2kq8','https://ajel.sa/international/p4xge2kq8','فريق التحرير','','2026-08-29T05:34:00.000Z','Wed, 07 Oct 2026 20:44:47 GMT','2026-08-29T11:54:49.652Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-etPbfCBn.png','/api/media/daf76411-7e20-4924-8deb-e3b69199c9e2','/api/media/daf76411-7e20-4924-8deb-e3b69199c9e2?variant=thumbnail','المجلس العسكري بالنيجر يعلن استعادة السيطرة تدريجيا على الوضع',1200,675,'valid','published','archived','valid',41,'301c361586c3c499e9a722dabe9a5b8ffb1a8e3d723406a6259b74f2f0004f20','a4e9cef562296c9cc41abdcea88812578e781713e6426b706fd6bf8f14a2368a','محدّث','2026-08-29T11:54:49.652Z','2026-10-07T20:44:48.928Z','','',0,0,'international','عادي',39,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:44:48.928Z',200,59,0,'source_content_changed','',NULL,NULL,'body:f348a8a857cf6db1b948912cbcfaa7f2aad8860ab14cb27375db81efeedbeafd','Wed, 07 Oct 2026 20:44:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c66bdcec-4f08-41bf-ad97-ec5010b7e021','news-c66bdcec-4f08-41bf-ad97-ec5010b7e021','دراسة: الكركمين يحمي الأوعية الدموية لمرضى السكري','دراسه الكركمين يحمي الاوعيه الدمويه لمرضي السكري','أظهرت دراسة حديثة أن الكركمين قد يقلل من تلف الأوعية الدموية المرتبط بالنوع الأول من داء السكري. وبحسب نتائج الدراسة، قلل الكركمين من شدة الالتهاب، ونظم استقلاب الكالسيوم بخلايا الأوعية الدموية، وأعاد توازن بروتين الصدمة الحرارية الذي يمكن أن يضطرب تنظيمه في حالة السكري، ما يؤثر على بنية ووظيفة جدار الأوعية الدموية.','["أظهرت دراسة حديثة أن الكركمين قد يقلل من تلف الأوعية الدموية المرتبط بالنوع الأول من داء السكري.","وذكر الباحثون، في نتائج دراستهم التي اجريت على الفئران، أن الكركمين (أحد مكونات الكركم)، يقلل من الالتهاب ويحسن وظيفة الشريان الأورطي، وفق \" روسيا اليوم \".","لكن الباحثين في الوقت نفسه يؤكدون أن هذه النتائج لا تعني إلزام مرضى السكري تناول الكركمين بمفرده أو أن يزيدوا من كمية الكركم في نظامهم الغذائي، لأن فعاليته وجرعته الآمنة وتوافقه مع الأدوية لا تزال بحاجة إلى مزيد من البحث.","وينصح الأطباء إجمالا بخضوع أي وسائل مساعدة فرعية للعلاج الأساسي للمتابعة الطبية وعدم تصرف المريض منفردا في اللجوء إلى مثل هذه الحلول مراعاة لتقييم كل حالة على حدة."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/a9txh6qzn','https://ajel.sa/misc/a9txh6qzn','https://ajel.sa/misc/a9txh6qzn','https://ajel.sa/misc/a9txh6qzn','فريق التحرير','','2026-08-29T05:58:00.000Z','Wed, 07 Oct 2026 20:50:04 GMT','2026-08-29T12:04:37.044Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%B3%D9%83%D8%B1%D9%8A-EzM6mk3F.jpg','/api/media/c66bdcec-4f08-41bf-ad97-ec5010b7e021','/api/media/c66bdcec-4f08-41bf-ad97-ec5010b7e021?variant=thumbnail','دراسة: الكركمين يحمي الأوعية الدموية لمرضى السكري',1200,675,'valid','published','archived','valid',47,'733dfa985531486898bef05e2b000c980b759f12adbec28172cc13272ee0562f','9aa5cd188ea35d5036174e95dfa45add746d4987cc06807a90ebdf9c77ab4d29','محدّث','2026-08-29T12:04:37.044Z','2026-10-07T20:50:06.142Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","روسيا"]','["الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:50:06.142Z',200,65,0,'source_content_changed','',NULL,NULL,'body:e2f712c6bcc0d7d71e1fcb3188f611a5b5c1ce08e8c456a22a3d8cd72e8b58ef','Wed, 07 Oct 2026 20:50:04 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b0bad610-c427-4e9c-be46-b44b9f4e5df9','news-b0bad610-c427-4e9c-be46-b44b9f4e5df9','أمانة جدة تُتلف 1.3 طن من الملابس المستعملة وتُزيل 270 بسطة عشوائية بالخمرة','امانه جده تتلف 1 3 طن من الملابس المستعمله وتزيل 270 بسطه عشوائيه بالخمره','وأسفرت الأعمال الميدانية عن إزالة وإتلاف 270 بسطة عشوائية، وإتلاف 1.3 طن من الملابس المستعملة، فيما رُحِّل 11 طناً من المضبوطات إلى المردم، بالتزامن مع تنظيف الموقع وإزالة المخلفات وإعادة تهيئته بصورة متكاملة.','["نفّذت أمانة محافظة جدة حملة ميدانية موسّعة في حي الخمرة جنوب المحافظة، استهدفت مواقع انتشار البسطات العشوائية التي رصدتها الفرق الرقابية، وذلك في إطار جهودها المستمرة للحد من الأنشطة التجارية غير النظامية داخل الأحياء.","وأوضحت وكالة البلديات الفرعية بالأمانة أن الحملة جاءت عقب رصد نشاط ممنهج لبيع الملابس المستعملة بطرق غير نظامية في النطاق، إذ باشرت الفرق الميدانية أعمال الإزالة والتعامل مع الكميات الموجودة وفق الإجراءات النظامية المعتمدة.","وشملت الحملة ضبط عدد من المخالفين واتخاذ الإجراءات النظامية بحقهم، في إطار مساعي الأمانة للحد من عودة النشاط العشوائي أو انتقاله إلى مواقع أخرى داخل النطاق.","ونُفِّذت الحملة بتكامل بين إدارات الأمانة والجهات ذات العلاقة، ضمن مسار ميداني يجمع بين الرصد والضبط والإزالة ومعالجة المواقع، مؤكدةً مواصلة حملاتها الرقابية لمتابعة مواقع البيع العشوائي واتخاذ الإجراءات اللازمة بما يعزز المشهد الحضري ويرفع مستوى الامتثال في المحافظة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/65ejzjo','https://sabq.org/article/65ejzjo','','https://sabq.org/article/65ejzjo','صحيفة سبق','مكة المكرمة','2026-08-29T06:23:00.000Z','2026-08-29T06:24:00.000Z','2026-08-29T14:59:52.711Z','https://media.sabq.org/news/2026/08/a2d0cf86-5429-46d7-96eb-0a51175e8f24/w1280.webp','/api/media/b0bad610-c427-4e9c-be46-b44b9f4e5df9','/api/media/b0bad610-c427-4e9c-be46-b44b9f4e5df9?variant=thumbnail','أمانة جدة تُتلف 1.3 طن من الملابس المستعملة وتُزيل 270 بسطة عشوائية بالخمرة',1280,720,'valid','published','archived','valid',89,'21ea5957ca7840eaa291d1916c5a4a1ec3e291e34f1b11fc063386b65e417657','e59bb85d20db04d52975562c544856d632e79d8fde69f289aec1fb32b8ff611f','محدّث','2026-08-29T12:25:49.438Z','2026-10-07T21:00:58.676Z','','',0,0,'saudi_region','مهم',69,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","جدة"]','["السفر والسياحة"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:00:58.676Z',200,59,0,'source_article_available','',NULL,NULL,'body:c36bb5b5ef3326d00820fb74ea322c9f8892551bb6b177b1c5f5fe9e038510e5','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('19f0e9ed-0dcd-4b05-9f8e-d0529fd033c8','news-19f0e9ed-0dcd-4b05-9f8e-d0529fd033c8','حرس الحدود يحبط تهريب 15 كيلوجرامًا من الحشيش في عسير','حرس الحدود يحبط تهريب 15 كيلوجراما من الحشيش في عسير','أحبطت الدوريات البرية لحرس الحدود في قطاع الربوعة ب منطقة عسير تهريب 15 كيلوجرامًا من مادة الحشيش المخدر، قبل استكمال الإجراءات النظامية الأولية وتسليم المضبوطات إلى جهة الاختصاص. وأوضحت الجهات الأمنية أن عملية الضبط جرت في إطار جهود حرس الحدود لمكافحة تهريب المخدرات، فيما جرى اتخاذ الإجراءات النظامية الأولية حيال المضبوطات.','["أحبطت الدوريات البرية لحرس الحدود في قطاع الربوعة ب منطقة عسير تهريب 15 كيلوجرامًا من مادة الحشيش المخدر، قبل استكمال الإجراءات النظامية الأولية وتسليم المضبوطات إلى جهة الاختصاص.","وأوضحت الجهات الأمنية أن عملية الضبط جرت في إطار جهود حرس الحدود لمكافحة تهريب المخدرات، فيما جرى اتخاذ الإجراءات النظامية الأولية حيال المضبوطات.","ودعت الجهات الأمنية المواطنين والمقيمين إلى الإبلاغ عن أي معلومات تتوافر لديهم بشأن أنشطة مرتبطة بتهريب أو ترويج المخدرات، مؤكدة أن جميع البلاغات ستُعالج بسرية تامة.","ويمكن تقديم البلاغات عبر الرقم 911 في مناطق مكة المكرمة و الرياض و المنطقة الشرقية ، والرقم 999 في بقية مناطق المملكة ، إضافة إلى رقم بلاغات المديرية العامة لمكافحة المخدرات 995، أو عبر البريد الإلكتروني [email&#160;protected] ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/xq22e4xch','https://ajel.sa/local/xq22e4xch','https://ajel.sa/local/xq22e4xch','https://ajel.sa/local/xq22e4xch','فريق التحرير','الرياض','2026-08-29T06:40:00.000Z','Wed, 07 Oct 2026 18:58:57 GMT','2026-08-29T12:53:47.816Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-QWw5Proc.png','/api/media/19f0e9ed-0dcd-4b05-9f8e-d0529fd033c8','/api/media/19f0e9ed-0dcd-4b05-9f8e-d0529fd033c8?variant=thumbnail','المضبوطات',1200,675,'valid','published','archived','valid',40,'eeea7c63c68b2053685e48d46e7e97ac7d532280aebc1420bd0044004d1ebe04','fdf5ddba0d33512714376f3e82f3cd69a13fef857514d3c78d9080639579ac32','محدّث','2026-08-29T12:53:47.817Z','2026-10-07T20:24:32.120Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","مكة","عسير","الرياض"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T18:58:59.502Z',200,59,0,'source_content_changed','',NULL,NULL,'body:ba5faacc9f1336657eb361588fcd8942e6fb31512652b63d6dee4396e72a608e','Wed, 07 Oct 2026 18:58:57 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e61cb93b-9144-4d95-be8e-bb9aea6d8638','news-e61cb93b-9144-4d95-be8e-bb9aea6d8638','سوريا تقبض على أحد أبرز تجّار المخدرات وتضبط بحوزته 37 كجم من الحشيش وأسلحة وذخائر','سوريا تقبض علي احد ابرز تجار المخدرات وتضبط بحوزته 37 كجم من الحشيش واسلحه وذخائر','وأسفرت العملية عن ضبط 37 كيلو غراماً من مادة الحشيش المخدر، إلى جانب كمية من مادة الأتش بوز، وأدوية مخدرة تخضع للرقابة الدوائية، بالإضافة إلى أسلحة متنوعة وذخائر.','["نفذ فرع مكافحة المخدرات بمحافظة دير الزور بالتعاون مع مديرية أمن المدينة وقوات المهام الخاصة، عملية مداهمة محكمة، أسفرت عن إلقاء القبض على أحد أبرز تجار المخدرات في المنطقة، وهو المدعو (ش.","وأُحيل المقبوض عليه إلى الجهات القضائية المختصة، لاتخاذ الإجراءات القانونية بحقه ونيل جزائه العادل."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/z98abh2','https://sabq.org/article/z98abh2','','https://sabq.org/article/z98abh2','منصور الشلاقي','','2026-08-29T06:43:00.000Z','2026-08-29T09:43:00.000Z','2026-08-29T12:53:49.533Z','https://media.sabq.org/news/2026/08/7d4f96d7-897d-4d2a-a99b-e4cfd096856e/w1280.webp','/api/media/e61cb93b-9144-4d95-be8e-bb9aea6d8638','/api/media/e61cb93b-9144-4d95-be8e-bb9aea6d8638?variant=thumbnail','سوريا تقبض على أحد أبرز تجّار المخدرات وتضبط بحوزته 37 كجم من الحشيش وأسلحة وذخائر ',1280,960,'valid','published','archived','valid',51,'c674e97f4c356ead2af96d60541c648b47cd90fb9fa81ad031d653229444d018','ec6792f452be36d4a19ac88c878ba913145719fbccce49c80261110204fd82a7','محدّث','2026-08-29T12:53:49.533Z','2026-10-07T21:21:44.445Z','','',0,0,'gulf_arab','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","سوريا"]','["السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:21:44.445Z',200,60,0,'source_article_available','',NULL,NULL,'body:d1ae13ff84c33cd388b08fc5994ffec79ca74b6ad4168af3648ceefaf2f21259','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7b007918-09e3-4c22-9586-b77c0bcedbf8','news-7b007918-09e3-4c22-9586-b77c0bcedbf8','أمطار وبرد وسيول تضرب رهاط ومدركة حتى التاسعة مساءً','امطار وبرد وسيول تضرب رهاط ومدركه حتي التاسعه مساء','وأوضح المركز أن هذه الحالة الجوية ستستمر -بمشيئة الله- حتى الساعة التاسعة مساءً، مُحذِّراً السكان والمسافرين من مخاطر الطريق وضرورة توخّي الحيطة والحذر.','["نبَّه المركز الوطني للأرصاد من هطول أمطار متوسطة على محافظتَي رهاط ومدركة التابعتين لمنطقة مكة المكرمة، مصحوبة برياح شديدة السرعة، وشبه انعدام في مدى الرؤية، وتساقط البرد، وجريان السيول، وصواعق رعدية."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ol0f6dn','https://sabq.org/article/ol0f6dn','','https://sabq.org/article/ol0f6dn','صحيفة سبق','مكة المكرمة','2026-08-29T06:41:00.000Z','2026-08-29T09:42:00.000Z','2026-08-29T12:53:50.589Z','https://media.sabq.org/news/2026/08/72e2a205-70eb-4a75-8acd-e9e75414b340/w1000.webp','/api/media/7b007918-09e3-4c22-9586-b77c0bcedbf8','/api/media/7b007918-09e3-4c22-9586-b77c0bcedbf8?variant=thumbnail','أمطار وبرد وسيول تضرب رهاط ومدركة حتى التاسعة مساءً',1000,565,'valid','published','archived','valid',40,'e5643d6055048d9f1714aae9e9974a4d7eaf06a6c99743c577d9809956494226','ca83a8913ad61141de28a8114ee0aec27c37ca612b76da008a5e09884a401ef3','محدّث','2026-08-29T12:53:50.589Z','2026-10-07T21:21:46.688Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة"]','["الطقس والمناخ"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:21:46.688Z',200,62,0,'source_article_available','',NULL,NULL,'body:7e0571ff45a0ff7e16e0f7ba927ef946d148b284fbb5c66f00b49c042fc9d547','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2a7670e0-144d-484c-b562-4e63c1a94980','news-2a7670e0-144d-484c-b562-4e63c1a94980','أمانة جدة تزيل 270 بسطة عشوائية وتتلف 1.3 طن من الملابس المستعملة','امانه جده تزيل 270 بسطه عشوائيه وتتلف 1 3 طن من الملابس المستعمله','أزالت أمانة محافظة جدة وأتلفت 270 بسطة عشوائية، خلال حملة ميدانية موسعة نفذتها في حي الخمرة جنوب المحافظة، كما أتلفت 1.3 طن من الملابس المستعملة، ورحّلت 11 طنًا من المضبوطات إلى المردم.','["واستهدفت الحملة مواقع انتشار البسطات العشوائية التي رصدتها الفرق الرقابية، ضمن جهود الأمانة للحد من الأنشطة التجارية غير النظامية داخل الأحياء، فيما شملت الأعمال تنظيف الموقع وإزالة المخلفات وإعادة تهيئته بصورة متكاملة.","وأوضحت وكالة البلديات الفرعية بأمانة جدة أن الحملة جاءت بعد رصد نشاط ممنهج لبيع الملابس المستعملة بطرق غير نظامية في النطاق، لتباشر الفرق الميدانية أعمال الإزالة والتعامل مع الكميات الموجودة وفق الإجراءات النظامية المعتمدة.","كما ضبطت الحملة عددًا من المخالفين، واتُخذت بحقهم الإجراءات النظامية، في إطار مساعي الأمانة للحد من عودة النشاط العشوائي أو انتقاله إلى مواقع أخرى داخل النطاق.","ونُفذت الحملة بالتكامل بين إدارات الأمانة والجهات ذات العلاقة، ضمن أعمال ميدانية شملت الرصد والضبط والإزالة ومعالجة المواقع.","وأكدت الأمانة مواصلة حملاتها الرقابية لمتابعة مواقع البيع العشوائي واتخاذ الإجراءات اللازمة، بما يعزز المشهد الحضري ويرفع مستوى الامتثال في المحافظة."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/xmmzds0s8','https://ajel.sa/local/xmmzds0s8','https://ajel.sa/local/xmmzds0s8','https://ajel.sa/local/xmmzds0s8','فريق التحرير','مكة المكرمة','2026-08-29T07:23:00.000Z','Wed, 07 Oct 2026 19:34:56 GMT','2026-08-29T13:33:47.556Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A3%D9%85%D8%A7%D9%86%D8%A9-%D8%AC%D8%AF%D8%A9-TamtCrow.jpg','/api/media/2a7670e0-144d-484c-b562-4e63c1a94980','/api/media/2a7670e0-144d-484c-b562-4e63c1a94980?variant=thumbnail','أمانة محافظة جدة',1200,675,'valid','published','archived','valid',41,'1ee8cf20611165c9a25d58e5f940bd1e5e2ab6ef39608da34daf5c4b786b47bf','90c691ff5fce7a63317eed5c5f32baa1b892ed15125a3ea6f03dd23ffdd88b8d','محدّث','2026-08-29T13:33:47.556Z','2026-10-07T20:24:32.130Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["جدة"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:34:57.748Z',200,52,0,'source_content_changed','',NULL,NULL,'body:ce6c82006f7bf710fc9f30876a3c57a456d291c101acbbd343774f143c81c55d','Wed, 07 Oct 2026 19:34:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6bc7a419-e224-45a7-ada0-4e585c7fdb5d','news-6bc7a419-e224-45a7-ada0-4e585c7fdb5d','رئيس وزراء العراق يوجه برصد مكافآت للمبلغين عن حالات الفساد','رئيس وزراء العراق يوجه برصد مكافات للمبلغين عن حالات الفساد','وأشار رئيس الهيئة إلى إكمال الاستراتيجية الوطنية للنزاهة ومكافحة الفساد، التي تمتد إلى سنة 2030، مؤكداً "استعداد الهيئة للمضي قدماً في مكافحة الفساد والحفاظ على المال العام".','["وجّه رئيس مجلس الوزراء علي فالح الزيدي، اليوم السبت، هيئة النزاهة الاتحادية بتفعيل قانون مكافأة المخبرين عن حالات الفساد، وتقديم تقارير شهرية وفصلية عن جهود مكافحة الفساد ومستوى الإنجاز، إلى جانب اعتماد ثلاثة مستويات لمتابعة المشاريع وفق حجمها وكلفتها.","وشملت توجيهات رئيس الوزراء تعزيز متابعة المنافذ الحدودية، وفضح الفاسدين، وعدم الاكتفاء بالدور الرقابي لهيئة النزاهة، بل توسيعه ليشمل الجانب الوقائي، مع متابعة مشاريع المحافظات أسوة بمشاريع الوزارات.","وحدد الزيدي آلية متابعة المشاريع وفق ثلاثة مستويات تبدأ بالمشاريع ذات الكلف العالية، ثم المشاريع المتوسطة، فالمشاريع الصغيرة، بهدف توجيه الجهد الرقابي بصورة أكثر فاعلية، بحسب بيان للمكتب الإعلامي لرئيس مجلس الوزراء.","وأكد رئيس مجلس الوزراء أن مكافحة الفساد تتطلب عملاً يتجاوز الرقابة إلى الوقاية، مشدداً على \"ضرورة العمل على وأد منظومة الفساد نهائياً، ومتابعة مشاريع المحافظات أسوة بمشاريع الوزارات\".","وجاءت التوجيهات خلال زيارة أجراها الزيدي إلى مقر هيئة النزاهة الاتحادية، حيث التقى رئيس الهيئة وملاكها المتقدم، واطّلع على آليات عملها والجهود التي تبذلها في مكافحة الفساد وحماية المال العام.","من جانبه، أعلن رئيس هيئة النزاهة تشكيل فرق ميدانية لتدقيق العقود في مؤسسات الدولة، موضحاً أن هذه الفرق أنجزت تدقيق عقود ثماني وزارات، فيما يتواصل العمل لاستكمال تدقيق عقود بقية المؤسسات."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/4xku6mr8m','https://ajel.sa/international/4xku6mr8m','https://ajel.sa/international/4xku6mr8m','https://ajel.sa/international/4xku6mr8m','فريق التحرير','','2026-08-29T07:23:00.000Z','Wed, 07 Oct 2026 19:35:37 GMT','2026-08-29T13:33:49.861Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/2-crop-9MdKcFM5.jpg','/api/media/6bc7a419-e224-45a7-ada0-4e585c7fdb5d','/api/media/6bc7a419-e224-45a7-ada0-4e585c7fdb5d?variant=thumbnail','رئيس وزراء العراق',1200,675,'valid','published','archived','valid',41,'e834903f968ebdbe9e1097843fa75491ac568175a4ac45b5ad8d5213c607d34c','1fd86de3acba0825fb14f478bf227aa388153fb1c872d90577c744d3226fe039','محدّث','2026-08-29T13:33:49.861Z','2026-10-07T20:24:32.134Z','','',0,0,'saudi_national','عادي',61,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس وزراء العراق يوجه برصد","مجلس الوزراء علي فالح الزيدي","هيئة النزاهة الاتحادية بتفعيل قانون","العراق"]','["رئيس وزراء العراق يوجه برصد","مجلس الوزراء علي فالح الزيدي","هيئة النزاهة الاتحادية بتفعيل قانون"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:35:38.846Z',200,54,0,'source_content_changed','',NULL,NULL,'body:e0f8fbdf055920239cc5925d37df5370e20e7e572c340ade31ccfb46eb938adb','Wed, 07 Oct 2026 19:35:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c2fc2a86-75ad-42c2-b3a8-7e201bfa32a0','news-c2fc2a86-75ad-42c2-b3a8-7e201bfa32a0','«منشآت» تصدر تقرير النمذجة الأولية وتكشف عن فرص سوق بـ165 مليار ريال','منشات تصدر تقرير النمذجه الاوليه وتكشف عن فرص سوق بـ165 مليار ريال','أصدرت الهيئة العامة للمنشآت الصغيرة والمتوسطة «منشآت» تقرير النمذجة الأولية، الذي يستعرض الفرص والتطورات المرتبطة بهذا المجال محلياً وعالمياً، ودوره في تطوير المنتجات وتسريع الابتكار وتقليل المخاطر المرتبطة بتحويل الأفكار إلى منتجات وحلول قابلة للاختبار والتطوير.','["وأوضح التقرير أن حجم سوق نمذجة المنتجات عالمياً بلغ 86.66 مليار ريال في عام 2025، ومن المتوقع أن يصل إلى 165.7 مليار ريال بحلول عام 2031، بمعدل نمو سنوي مركب يُقدَّر بـ11.41% خلال الفترة 2026 - 2031، مدفوعاً بتغيّر أنماط تطوير المنتجات، وتسارع الابتكار الصناعي، وزيادة الاعتماد على تقنيات التصنيع المتقدم.","وعلى المستوى المحلي، أشار التقرير إلى أن حجم سوق الطباعة ثلاثية الأبعاد بلغ 1.20 مليار ريال في عام 2025، مع توقعات بوصوله إلى 6.47 مليارات ريال بحلول عام 2034، بمعدل نمو سنوي مركب يبلغ 20.52% خلال الفترة 2026 - 2034، في ظل توظيف هذه التقنية في قطاعات تشمل الطيران والسيارات والتعليم والرعاية الصحية والتصنيع.","وبيّن التقرير أن حجم العائد المالي للشركات المحتضنة في مركز الابتكار التابع لـ«منشآت» تجاوز 300 مليون ريال، فيما نُفِّذ عبر المركز 263 نموذجاً أولياً ومنتجاً، واستفاد أكثر من 8,062 رائد أعمال ومبتكر من الخدمات والبرامج المتخصصة.","وسلّط التقرير الضوء على دعم «منشآت» للنمذجة الأولية عبر مراكز الابتكار ومعامل النمذجة، وحاضنات ومسرّعات الأعمال، والاستشارات التقنية والتجارية المتخصصة، إلى جانب تسهيل الوصول إلى برامج التمويل والاستثمار؛ بما يسهم في رفع جاهزية المشاريع وتطوير منتجاتها.","كما تناول التقرير أهمية النمذجة الأولية في منظومات الابتكار، ودورها في تسريع تطوير الأفكار ومواءمة الحلول مع احتياجات المستفيدين، ودعم القرارات المبنية على الأدلة، مستعرضاً رحلة تطوير النموذج الأولي بدءاً من تقييم الفكرة وتحديد احتياجاتها، وصولاً إلى بناء النموذج واختباره وتطويره.","ويأتي التقرير -الذي يُعدّ مرجعاً شاملاً للمهتمين بالنمذجة- ضمن جهود «منشآت» الرامية إلى رفع كفاءة النمذجة الأولية، وتطوير البنية التحتية التقنية والمعامل، وتحفيز الاستثمار في القطاع، وتعزيز الشراكة والتكامل بين رواد الأعمال ومزودي الخدمات."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/zneygdk','https://sabq.org/article/zneygdk','','https://sabq.org/article/zneygdk','صحيفة سبق','','2026-08-29T07:37:00.000Z','2026-08-29T10:38:00.000Z','2026-08-29T13:42:47.768Z','','','','«منشآت» تصدر تقرير النمذجة الأولية وتكشف عن فرص سوق بـ165 مليار ريال',NULL,NULL,'all_candidates_failed (og:fetch failed | structured:fetch failed | structured:fetch failed | structured:fetch failed)','published','archived','valid',49,'27320c826f7d879b4933d2fa56fa16a54057ac734ed84288884a9d9bc403f4eb','848b1158aab1a383496198b0dc85569504e54978b5cc634e3b87636d640940e4','محدّث','2026-08-29T13:42:47.768Z','2026-10-07T20:24:32.139Z','','',0,0,'international','عادي',57,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["السفر والسياحة","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:52:50.024Z',200,56,0,'source_article_available','',NULL,NULL,'body:634fc576d55008f95e1dde1153445725bab0d96f26af36995a571d9e04e66dd9','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('88a03e17-f968-4504-9b41-b8cbb750b0a6','news-88a03e17-f968-4504-9b41-b8cbb750b0a6','«عراقجي»: جهات حكومية أمريكية تستغل وسائل الإعلام للتأثير على أسعار الطاقة','عراقجي جهات حكوميه امريكيه تستغل وسائل الاعلام للتاثير علي اسعار الطاقه','قال وزير الخارجية الإيراني عباس عراقجي ، إن معلومات بلاده الاستخباراتية تشير إلى «وجود جهود حثيثة للتلاعب بأسواق الطاقة». وأضاف عراقجي عبر حسابه على منصة "إكس"، أن «هناك جهات حكومية أمريكية تستغل وسائل الإعلام للتأثير على أسعار الطاقة، لتحقيق مكاسب شخصية».','["قال وزير الخارجية الإيراني عباس عراقجي ، إن معلومات بلاده الاستخباراتية تشير إلى «وجود جهود حثيثة للتلاعب بأسواق الطاقة».","وأضاف عراقجي عبر حسابه على منصة \"إكس\"، أن «هناك جهات حكومية أمريكية تستغل وسائل الإعلام للتأثير على أسعار الطاقة، لتحقيق مكاسب شخصية».","وأشار إلى أن «بعض الجهات تستغل وسائل الإعلام لإبقاء الرئيس الأمريكي غارقًا في حرب خاسرة، فيما تروج جهات موالية لإسرائيل للحرب بتقييمات وردية».","وفي وقت سابق، أكد الرئيس الإيراني مسعود بزشكيان أن بلاده لا تسعى إلى الحرب، لكنها ستدافع عن نفسها في مواجهة أي عدوان، مشددًا على أن الوحدة الداخلية والتماسك الوطني يمثلان مفتاح تجاوز التحديات.","وبحسب وكالة «مهر»، قال بزشكيان، اليوم السبت، إن إيران ستقف إلى جانب شعبها وتصون كرامة البلاد وعزتها بكل ما تملك من قوة، مشيرًا إلى أن جميع الجهود المبذولة خلال الفترة الماضية ركزت على تعزيز الوحدة والتماسك.","وأضاف: «لا نحب الحرب، لكننا سنواجه العدوان بحزم وندافع عن أنفسنا. لا يمكن لأي قوة أن تجبر أمة موحدة متمسكة بأرضها على الاستسلام»، مؤكدا أن بلاده ستواصل السعي إلى حل المشكلات عبر الحوار، لكنها «لن تستسلم للتهديدات والعدوان»."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/gxdupofuj','https://ajel.sa/international/gxdupofuj','https://ajel.sa/international/gxdupofuj','https://ajel.sa/international/gxdupofuj','فريق التحرير','','2026-08-29T07:28:00.000Z','Wed, 07 Oct 2026 20:00:50 GMT','2026-08-29T13:51:48.358Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-BYnLeExs.jpg','/api/media/88a03e17-f968-4504-9b41-b8cbb750b0a6','/api/media/88a03e17-f968-4504-9b41-b8cbb750b0a6?variant=thumbnail','«عراقجي»: جهات حكومية أمريكية تستغل وسائل الإعلام للتأثير على أسعار الطاقة',1200,675,'valid','published','archived','valid',46,'a695ca3d3560e755d621fc3e44ee273c8c0945ef1f2f3ebe82b88642fbcc4ff2','fa500f2a026868be395ce6fda078e9b8462e466bf483105c2754386f2d9159a7','محدّث','2026-08-29T13:51:48.358Z','2026-10-07T20:24:32.141Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الخارجية الإيراني عباس عراقجي","الطاقة والنفط","إيران"]','["وزير الخارجية الإيراني عباس عراقجي","الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T20:00:51.599Z',200,59,0,'source_content_changed','',NULL,NULL,'body:773a913cb7ce80023628ea144b27003d69ecfe6563cd8be4689e2493d5403e20','Wed, 07 Oct 2026 20:00:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('404f4bad-7fdf-4c56-8bce-6d433af726cf','news-404f4bad-7fdf-4c56-8bce-6d433af726cf','"الأرصاد" يحذر من أمطار وسيول وبرد على رهاط ومدركة بمكة المكرمة','الارصاد يحذر من امطار وسيول وبرد علي رهاط ومدركه بمكه المكرمه','نبَّه المركز الوطني للأرصاد اليوم من هطول أمطار متوسطة على محافظتَي رهاط ومدركة التابعتين لمنطقة مكة المكرمة، مصحوبةً برياح شديدة السرعة، وشبه انعدام في مدى الرؤية، وتساقط للبرد، وجريان للسيول، وصواعق رعدية.','["وأوضح المركز أن هذه الحالة المناخية ستستمر حتى الساعة التاسعة مساءً، داعياً المواطنين والمقيمين في المنطقتين إلى توخي الحذر وتجنب الأودية ومجاري السيول."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wc11s3h','https://sabq.org/article/wc11s3h','','https://sabq.org/article/wc11s3h','صحيفة سبق','مكة المكرمة','2026-08-29T07:56:00.000Z','2026-08-29T10:57:00.000Z','2026-08-29T14:09:50.248Z','https://media.sabq.org/news/2026/08/076f14aa-b70d-4864-b783-8541604d72b5/w1513.webp','/api/media/404f4bad-7fdf-4c56-8bce-6d433af726cf','/api/media/404f4bad-7fdf-4c56-8bce-6d433af726cf?variant=thumbnail','"الأرصاد" يحذر من أمطار وسيول وبرد على رهاط ومدركة بمكة المكرمة',1513,829,'valid','published','archived','valid',46,'ac8d45e13c602f3d6952d09fb011c977b344b90bf7cedb0b9f1c0ff873bd790a','9bf59fadd9aa88e2e7e377de3d244677c1cf49893ac0eb246fe4d103ed9ae6fd','محدّث','2026-08-29T14:09:50.248Z','2026-10-07T20:49:54.484Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة"]','["الطقس والمناخ"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:49:54.484Z',200,54,0,'source_article_available','',NULL,NULL,'body:2484349d4e4400d5c24ac04b663426c1fa69356de4b8b36eac89041334146161','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('64b5af33-e848-4e6a-a9b2-2da2c2dde523','news-64b5af33-e848-4e6a-a9b2-2da2c2dde523','حصيلة ضحايا فيضانات نيبال ترتفع إلى 675 شخصاً والمفقودون في تزايد','حصيله ضحايا فيضانات نيبال ترتفع الي 675 شخصا والمفقودون في تزايد','ارتفعت حصيلة ضحايا الفيضانات المدمرة التي اجتاحت شمال نيبال الأربعاء الماضي إلى 675 شخصاً، وفق ما أعلنته هيئة إدارة الحالات الطارئة في نيبال في بيان رسمي.','["وأكدت الهيئة أن الحصيلة لا تزال غير نهائية، مشيرةً إلى ارتفاع حاد في أعداد المفقودين، من بينهم 45 جندياً من الجيش النيبالي، و40 من أفراد الشرطة، و19 من موظفي الهجرة والجمارك."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/x4iqek5','https://sabq.org/article/x4iqek5','','https://sabq.org/article/x4iqek5','صحيفة سبق','','2026-08-29T08:13:00.000Z','2026-08-29T08:14:00.000Z','2026-08-29T15:47:53.433Z','https://media.sabq.org/news/2026/08/34940ca6-25ad-4b71-9dea-53f943daf1a6/w600.webp','/api/media/64b5af33-e848-4e6a-a9b2-2da2c2dde523','/api/media/64b5af33-e848-4e6a-a9b2-2da2c2dde523?variant=thumbnail','حصيلة ضحايا فيضانات نيبال ترتفع إلى 675 شخصاً والمفقودون في تزايد',600,400,'valid','published','archived','valid',35,'08886c9804fd2acb6863b9a9991ab6748a1774ab7b091c4bca155416afb983e6','cb45e89687604bebfb213ba5ab72bd0e00ab05ffd3225c378b9d4bca3c8ca246','محدّث','2026-08-29T14:18:50.062Z','2026-10-07T20:50:53.858Z','','',0,0,'international','عادي',56,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة إدارة الحالات الطارئة في"]','["هيئة إدارة الحالات الطارئة في"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:50:53.858Z',200,59,0,'source_article_available','',NULL,NULL,'body:cfe76fb9c61730950f446b94c79cf0050091fa3b319e6ed6af3093468da90040','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1cfdd1ac-824b-4dbd-8f94-c30f6c8b0d17','news-1cfdd1ac-824b-4dbd-8f94-c30f6c8b0d17','جدة والعلا يتصدران دوري الأولى بعد الجولة الثانية بـ 16 نقاط','جده والعلا يتصدران دوري الاولي بعد الجوله الثانيه بـ 16 نقاط','وحقق العلا فوزاً خارج الديار على مضيفه الأنوار بهدف نظيف، ليواصل انتصاراته ويرتقي إلى المركز الثاني بـ 6 نقاط متساوياً مع جدة بفارق الأهداف، بينما توقف رصيد الأنوار عند نقطة وحيدة في المركز الـ 17.','["تقاسم فريقا جدة والعلا صدارة دوري الدرجة الأولى للمحترفين بالعلامة الكاملة (6 نقاط) عقب اختتام الجولة الثانية من موسم 2026-2027، التي اختُتمت أمس الجمعة.","وشهدت الجولة تسجيل 19 هدفاً، بزيادة هدفين عن الجولة الافتتاحية، إذ حُسمت 5 مباريات بالفوز مقابل 4 تعادلات، وكانت مباراة العدالة والطائي الأكثر غزارةً بتسجيل 7 أهداف.","جدة يواصل انتصاراته واصل جدة مسيرته الانتصارية بفوز ثمين على ضيفه النجمة بهدف نظيف، رافعاً رصيده إلى 6 نقاط في صدارة الترتيب، بينما توقف رصيد النجمة عند 3 نقاط في المركز السادس.","نتائج الجولة الثانية حسم التعادل السلبي مباراة الزلفي مع ضيفه الوحدة، ليرفع أصحاب الأرض رصيدهم إلى 4 نقاط في المركز الثالث، بينما رفع الوحدة رصيده إلى نقطتين في المركز العاشر.","وتعادل الأخدود مع مضيفه البكيرية بهدف لكل منهما، ليصل الأخدود إلى 4 نقاط في المركز الثالث مشاركاً الزلفي بفارق الأهداف، بينما حصد البكيرية نقطته الثانية في المركز الـ 11.","وحقق هجر فوزه الأول هذا الموسم على حساب مضيفه الرائد بنتيجة 3-2، ليتقدم إلى المركز التاسع برصيد 3 نقاط، بينما يحل الرائد خامساً بالرصيد ذاته بفارق الأهداف.","الانتصار الأول للطائي والجبلين سجّل الطائي انتصاره الأول هذا الموسم بعودته من الأحساء بثلاث نقاط، إذ تغلّب على العدالة بنتيجة 4-3 ليتقدم إلى المركز السابع برصيد 3 نقاط، بينما توقف رصيد العدالة عند نقطة وحيدة في المركز الـ 14.","وحقق الجبلين بدوره فوزه الأول بتخطي ضيفه الجيل بهدف نظيف، ليتقدم إلى المركز الثامن برصيد 3 نقاط، بينما لا يزال الجيل بلا رصيد في المركز الـ 18."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/hs2rtqc','https://sabq.org/article/hs2rtqc','','https://sabq.org/article/hs2rtqc','صحيفة سبق','مكة المكرمة','2026-08-29T08:36:00.000Z','2026-08-29T11:36:00.000Z','2026-08-29T14:38:52.989Z','https://media.sabq.org/news/2026/08/2cf017b7-af1b-4d85-8543-0020259465c3/w1489.webp','/api/media/1cfdd1ac-824b-4dbd-8f94-c30f6c8b0d17','/api/media/1cfdd1ac-824b-4dbd-8f94-c30f6c8b0d17?variant=thumbnail','جدة والعلا يتصدران دوري الأولى بعد الجولة الثانية بـ 16 نقاط',1489,953,'valid','published','archived','valid',56,'2afde6eb8fe3df61b00ee0410bff6e352a7824f40fbc1cefddad98ef352d966b','ef36bddd102b6d5335e30d8df7fcec6ff7dbfc61f9cbdaca268577d1f098857e','محدّث','2026-08-29T14:38:52.989Z','2026-10-07T21:07:59.492Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","جدة"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"المناطق","score":3},{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:07:59.492Z',200,59,0,'source_article_available','',NULL,NULL,'body:b12d46b7498abce9c3948bdcbdbc9b88d9090f08793350ebbc57fed6505de425','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9da874f4-92ff-4318-bd79-edb0f0a49bd8','news-9da874f4-92ff-4318-bd79-edb0f0a49bd8','الهيئة الملكية للرياض تعتمد دليلًا ملزمًا لمكافحة غبار البناء.. 10 إجراءات لحماية البيئة والصحة','الهيئه الملكيه للرياض تعتمد دليلا ملزما لمكافحه غبار البناء 10 اجراءات لحمايه البيئه والصحه','ويتضمن الدليل 10 إجراءات رئيسية للسيطرة على الغبار، تشمل رش المياه أثناء عمليات الرفع والتحميل، واستخدام مواد مثبتة للغبار، مثل البوليمرات والمحاليل الملحية، إلى جانب رش الطرق المؤدية إلى داخل المشاريع.','["اعتمدت الهيئة الملكية لمدينة الرياض دليلًا تنظيميًا ملزمًا للتحكم في الغبار الناجم عن الأعمال الإنشائية، متضمنًا إجراءات صارمة تطبق على جميع مواقع البناء، بهدف الحد من الآثار البيئية وتعزيز جودة البيئة الحضرية وجودة الحياة في العاصمة.","كما يلزم الدليل بتغطية الحاويات لمنع تطاير المواد، وكنس الطرق المجاورة لمواقع المشاريع، وتوفير أجهزة لغسل إطارات الشاحنات قبل مغادرتها الموقع، إضافة إلى تغطية أكوام المواد الخام القابلة للتطاير مع هبوب الرياح.","وتشمل الإجراءات كذلك تحديد سرعات حركة الشاحنات داخل حدود المشروع، وإيقاف الأعمال المثيرة للأتربة عند تزايد شدة الرياح، وتركيب أجهزة لرصد الغبار في المشاريع التي تتجاوز مساحتها 2000 متر مربع .","وتهدف التدابير الوقائية إلى حماية الصحة العامة والمناطق الحساسة، مثل المدارس والمستشفيات ، إلى جانب تحديد السرعات على الطرق الترابية وتزويد الكسارات بأنظمة الرذاذ، مع تفعيل الرصد الآني لجودة الهواء في المشاريع عالية الخطورة.","ويستهدف الدليل توحيد ممارسات إدارة الغبار في مدينة الرياض، والحد من آثاره البيئية والصحية، مع التأكيد على ترشيد استهلاك المياه المستخدمة في عمليات مكافحة الغبار.","الإجراءات المعتمدة للتحكم والسيطرة على الغبار الناتج عن الأعمال الإنشائية بالرياض"]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/py9p61f','https://sabq.org/article/py9p61f','','https://sabq.org/article/py9p61f','صحيفة سبق','الرياض','2026-08-29T08:28:00.000Z','2026-08-29T11:30:00.000Z','2026-08-29T14:39:44.473Z','https://media.sabq.org/news/2026/08/c5fe7139-ae8c-4c75-a8d0-fcd71538524a/w854.webp','/api/media/9da874f4-92ff-4318-bd79-edb0f0a49bd8','/api/media/9da874f4-92ff-4318-bd79-edb0f0a49bd8?variant=thumbnail','الهيئة الملكية للرياض تعتمد دليلًا ملزمًا لمكافحة غبار البناء.. 10 إجراءات لحماية البيئة والصحة',854,420,'valid','published','archived','valid',49,'c16e52c0a88bf062eb44f342b2edec3af8db18d66270a5fd362313a8b7409834','688c9060f63583bc8ed76ea6c39e89fbd0f22d4d6000506d9d9d7a88b84a0755','محدّث','2026-08-29T14:39:44.473Z','2026-10-07T21:07:58.897Z','','',0,0,'saudi_region','مهم',69,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الرياض"]','["الصحة العامة"]','needs_review','below_category_threshold','[{"category":"التقنية","score":2},{"category":"المناطق","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:07:58.897Z',200,59,0,'source_article_available','',NULL,NULL,'body:0fbccea47932b5b35b397235753980bc68566b88c98efc2fde79e2f206092750','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('75a240a9-1950-457b-b881-5a76cd79dfde','news-75a240a9-1950-457b-b881-5a76cd79dfde','حواجز خرسانية وتحويلات مرورية لتعزيز السلامة.. حائل تعالج موقعين مروريين خطرين بعد تقارير "سبق"','حواجز خرسانيه وتحويلات مروريه لتعزيز السلامه حائل تعالج موقعين مروريين خطرين بعد تقارير سبق','باشرت أمانة منطقة حائل وإدارة المرور بالمنطقة معالجة موقعين مروريين خطرين شمال المدينة، وذلك عقب تقارير «سبق» التي نقلت مطالب الأهالي بتنظيم التقاطعات وتعزيز السلامة على الطرق المؤدية إلى المدينة الجامعية بجامعة حائل.','["وجاءت المعالجة الأولى عند تقاطع طريق مشار الفرعي مع طريق أمير المؤمنين علي بن أبي طالب رضي الله عنه، في بداية الطريق الجديد الرابط بين حي المصيف واللقيطة والمؤدي إلى المدينة الجامعية؛ إذ جرى تنظيم حركة المركبات باستخدام حواجز خرسانية وبلاستيكية، مع وضع وسائل إرشادية وتحذيرية وتحديد مسارات الحركة في التقاطع.","وكان الأهالي قد أبدوا تخوفهم من اتساع التقاطع وتداخل اتجاهات المركبات فيه، لا سيما مع ارتفاع كثافة الحركة المرورية بالتزامن مع بدء الفصل الدراسي، مطالبين بتنظيم مسارات الدخول والخروج واتخاذ الإجراءات اللازمة لتعزيز السلامة.","أما الموقع الثاني، فيقع أمام المشاتل على طريق القاعد شمال حائل، حيث شرعت الفرق المختصة في وضع حواجز خرسانية على الجزيرة الوسطية لمنع المركبات من تجاوز الرصيف وتنفيذ دوران غير نظامي باتجاه مسار مضاد.","وكانت «سبق» قد وثّقت مطالب الأهالي بمعالجة هذا الموقع، إثر استمرار بعض المركبات في تجاوز الرصيف رغم إغلاق فتحة الدوران السابقة، محذّرين من خطورة خروج المركبات بصورة مفاجئة أمام القادمين من جهة المدينة الجامعية على طريق تبلغ سرعته المحددة 100 كيلومتر في الساعة.","وتُظهر الصور الميدانية الحديثة المعالجات المنفّذة في الموقعين مقارنةً بوضعهما السابق، بما يسهم في تنظيم حركة المركبات والحدّ من الممارسات الخطرة على مستخدمي الطريق.","وقد أسهم التنسيق بين «سبق» وأمانة منطقة حائل وإدارة المرور في الاستجابة السريعة لملاحظات الأهالي الميدانية، بما يعكس أهمية دور الإعلام في نقل صوت المواطن ورصد الاحتياجات الخدمية."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/lcnLzYs','https://sabq.org/article/lcnLzYs','','https://sabq.org/article/lcnLzYs','خالد السليمي','','2026-08-29T08:41:00.000Z','2026-08-29T11:43:00.000Z','2026-08-29T14:50:52.969Z','https://media.sabq.org/news/2026/08/5ce09a72-1d77-44d5-ac43-ab7997018d6b/w960.webp','/api/media/75a240a9-1950-457b-b881-5a76cd79dfde','/api/media/75a240a9-1950-457b-b881-5a76cd79dfde?variant=thumbnail','حواجز خرسانية وتحويلات مرورية لتعزيز السلامة.. حائل تعالج موقعين مروريين خطرين بعد تقارير "سبق"',960,540,'valid','published','archived','valid',35,'a56515b0cec636870c7f4f765be27f3fe9971e3aa9726a29b43b6f1eea818d5d','a321231926b342039d9bb3f86b2c0b0be210f27091634d8f6d0b33cc11b6ddb8','محدّث','2026-08-29T14:50:52.969Z','2026-10-07T21:11:26.413Z','','',0,0,'international','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الاقتصاد والأسواق"]','["التعليم والتدريب","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"الرياضة","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T21:11:26.413Z',200,64,0,'source_article_available','',NULL,NULL,'body:db73f92b67ebb5cf154fb87efc0731afbad2c36ef5ad4e13d245d24f1e453eed','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a885f8b2-9ae9-4029-b1c9-9e92e8fe7bee','news-a885f8b2-9ae9-4029-b1c9-9e92e8fe7bee','58 حالة إغماء في مدرجات الدمام.. استشاري قلب يكشف الأسباب والوقاية','58 حاله اغماء في مدرجات الدمام استشاري قلب يكشف الاسباب والوقايه','رصدت مدرجات ملعب الأمير محمد بن فهد بالدمام 58 حالة إغماء وإعياء خلال مواجهة الهلال والخليج مساء الجمعة، طالت الجماهير والمنظمين على حدٍّ سواء، في مشهد سلّط الضوء على تأثير الظروف المناخية على سلامة الحضور.','["وأرجع استشاري القلب وخبير ضغط الدم، مؤسس برنامج «ترويض الضغط»، الدكتور صالح الغامدي، هذه الحالات إلى تداخل عدة عوامل، في مقدمتها ارتفاع الرطوبة والحرارة والزحام الشديد في المدرجات، وما يترتب عليها من فقدان للسوائل وانخفاض في ضغط الدم.","وأوضح الغامدي عبر حسابه على منصة «إكس» أن «الرطوبة العالية تخفض الضغط بسبب فقد السوائل»، مشيرًا إلى أن اجتماع الحرارة والزحام في المدرجات يحفّز العصب الحائر، مما قد يؤدي إلى إبطاء ضربات القلب وانخفاض ضغط الدم، وبالتالي الشعور بالدوخة أو الإغماء.","وردًّا على من تساءل عن عدم تعرض الجماهير واللاعبين لمثل هذه الحالات في جولات سابقة، شدد الغامدي على أن «التزاحم في المدرج عامل حاسم»، مستشهدًا بتجربة أحد الحضور الذي أفاد بأنه كاد يُغمى عليه قبل أن يتناول الماء ويستعيد توازنه، معلقًا: «العجيب كيف اللاعبين تحملوا».","الماء وقاية من هبوط الضغط وقدّم الغامدي جملةً من النصائح الوقائية للجماهير قبل التوجه إلى المدرجات، أبرزها: - شرب كميات كافية من السوائل قبل المباراة وخلالها. - عدم الذهاب إلى المباراة على معدة فارغة. - تجنب الوقوف لفترات طويلة في أماكن شديدة الحرارة أو تحت أشعة الشمس. - الابتعاد قدر الإمكان عن مناطق الزحام.","ونبّه إلى أن العلامات التي تستدعي الانتباه الفوري تشمل: الدوخة، والغثيان، والتعرق البارد، والشعور بقرب الإغماء، مؤكدًا أن التعامل الأولي معها يكون بالجلوس أو الاستلقاء والانتقال إلى مكان أكثر برودة مع تناول الماء.","الصيام المتقطع وضغط الدم وفي سياق حديثه، أشار الغامدي إلى أن الصيام المتقطع لأكثر من 16 ساعة قد يفيد بعض مرضى ضغط الدم في التحكم بمستوياته، غير أن ذلك يتفاوت من شخص إلى آخر بحسب حالته الصحية وعلاجه.","وأوضح الغامدي أن الإغماء يكون في كثير من الحالات حميدًا وغير خطير، إلا أن ثمة حالات تستدعي التقييم الطبي، لا سيما لدى من يعانون من ضعف في عضلة القلب أو تضيق في صماماته.","ولفت إلى أن خطورة الإغماء قد ترتبط بما يحدث أثناء السقوط، خصوصًا إذا أسفر عن إصابة في الرأس، مؤكدًا أهمية عدم تجاهل الإغماء المتكرر أو غير المفسر لدى أصحاب التاريخ المرضي القلبي."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/hIAm6Zy','https://sabq.org/article/hIAm6Zy','','https://sabq.org/article/hIAm6Zy','عبدالحكيم شار','المدينة المنورة','2026-08-29T08:50:00.000Z','2026-08-29T11:50:00.000Z','2026-08-29T14:56:14.389Z','https://media.sabq.org/news/2026/08/e9a297b8-c5db-4be5-8320-99452d093f5f/w400.webp','/api/media/a885f8b2-9ae9-4029-b1c9-9e92e8fe7bee','/api/media/a885f8b2-9ae9-4029-b1c9-9e92e8fe7bee?variant=thumbnail','58 حالة إغماء في مدرجات الدمام.. استشاري قلب يكشف الأسباب والوقاية',400,400,'valid','published','archived','valid',44,'d227298700570dc09c71b59c634f9a530975250014476721a286ae1d72f6384a','c3871e9bdfa2d012efedf21dc993357e6c3ddb6bbc4ac74bad30c9a295859f6d','محدّث','2026-08-29T14:56:14.389Z','2026-10-07T21:11:25.828Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الهلال الأحمر السعودي والكوادر","الصحة العامة","الطقس والمناخ","السفر والسياحة","الرياضة السعودية","الاقتصاد والأسواق","الدمام"]','["هيئة الهلال الأحمر السعودي والكوادر","الصحة العامة","الطقس والمناخ","السفر والسياحة","الرياضة السعودية","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الرياضة","score":3},{"category":"أخبار السعودية","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T21:11:25.828Z',200,64,0,'source_article_available','',NULL,NULL,'body:d74aa9dcc3a4034cec1786bf372eca96def5599df3643cab93f0bc0e0cd9e16c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('09cadd4f-52ae-40d3-ba49-3167928dc952','news-09cadd4f-52ae-40d3-ba49-3167928dc952','"المرور" يطرح مزاد اللوحات الإلكتروني غدًا عبر «أبشر»','المرور يطرح مزاد اللوحات الالكتروني غدا عبر ابشر','وأوضحت الإدارة العامة للمرور، عبر حسابها الرسمي على منصة «إكس»، أن المشاركة في المزاد تبدأ بالدخول إلى منصة «أبشر»، ثم اختيار «خدماتي»، ومنها «المرور»، وبعد ذلك خدمة «مزاد اللوحات الإلكتروني».','["تطرح الإدارة العامة للمرور ، غدًا الأحد، مزاد اللوحات الإلكتروني عبر منصة «أبشر»، أمام الراغبين في شراء اللوحات المميزة والمشاركة في المزايدة عليها إلكترونيًا.","وبعد الوصول إلى الخدمة، يختار المستخدم نوع لوحات المركبات، لتظهر له اللوحات المتاحة التي يمكن المشاركة في المزايدة عليها إلكترونيًا.","ويأتي طرح المزاد ضمن الخدمات الإلكترونية التي توفرها منصة «أبشر» للراغبين في شراء اللوحات المميزة، بما يتيح إتمام إجراءات المشاركة في المزاد عبر المنصة إلكترونيًا."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/khy451nkv','https://ajel.sa/local/khy451nkv','https://ajel.sa/local/khy451nkv','https://ajel.sa/local/khy451nkv','فريق التحرير','عسير','2026-08-29T08:51:00.000Z','Wed, 07 Oct 2026 19:06:37 GMT','2026-08-29T15:09:49.266Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%84%D9%84%D9%84%D9%84-RqDrmJsL.png','/api/media/09cadd4f-52ae-40d3-ba49-3167928dc952','/api/media/09cadd4f-52ae-40d3-ba49-3167928dc952?variant=thumbnail','مزاد اللوحات الإلكتروني',1200,675,'valid','published','archived','valid',41,'237f2a2337f9e7981a203202b1768bc69a3d06a2810a9a929f7cc06546df3676','b620dd5e6f88a459b2951c613f4f39f90679802542dea803ab95450eb10c97b2','محدّث','2026-08-29T15:09:49.266Z','2026-10-07T20:24:32.165Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["عسير"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:06:38.865Z',200,55,0,'source_content_changed','',NULL,NULL,'body:da9a595ac1f216799f5057d7372a725e9b1012447ac2b26d5dcc0c95afd9728b','Wed, 07 Oct 2026 19:06:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d8850c91-5fba-4cb3-aca2-7c934a9f827d','news-d8850c91-5fba-4cb3-aca2-7c934a9f827d','عرض تمثال برونزي من آثار اليمن للبيع في مزاد بتل أبيب','عرض تمثال برونزي من اثار اليمن للبيع في مزاد بتل ابيب','ويرتبط اسم موساييف بمجموعة كبيرة من القطع الأثرية التي جمعها خلال حياته، بينها مجموعة من القطع المنسوبة إلى حضارات اليمن القديم. أما القطعة المقرر عرضها في مزاد تل أبيب، فتصور شابا بملامح هادئة، دون حسم هوية الشخصية التي تجسدها حتى الآن، وفقا لمحسن الذي تناول تفاصيلها في منشور عبر حسابه على " فيسبوك ".','["تتجه قطعة أثرية مسروقة من آثار اليمن إلى سوق المزادات في كيان الاحتلال الإسرائيلي، بعدما كشف الباحث المتخصص في تتبع الآثار اليمنية المهربة عبدالله محسن أنها عبارة عن تمثال نصفي برونزي سيُعرض للبيع في مزاد بمدينة تل أبيب أواخر سبتمبر المقبل، وكان ضمن المجموعة الخاصة لرجل الأعمال وتاجر المجوهرات شلومو موساييف.","ويرتبط اسم موساييف بمجموعة كبيرة من القطع الأثرية التي جمعها خلال حياته، بينها مجموعة من القطع المنسوبة إلى حضارات اليمن القديم. وكان موساييف، المولود في القدس عام 1925، قد انتقل إلى بريطانيا عام 1963، وتوفي عام 2015.","وتضم القطع المنسوبة إلى اليمن في مجموعته أربعة أسود برونزية من الجوف تعود إلى القرن السادس قبل الميلاد، ورأس ثور من الذهب، وتمثالا برونزيا لحصان يمتطيه فارس يحمل سيفا، وكأسا برونزية تحمل ثلاثة أسطر من نقوش المسند.","كما تشمل المجموعة لوحة برونزية يظهر عليها وجهان لشابين وتحتها كلمة \"ش ي م\"، وتمثالا لابنة ملك قتبان \"يدع أب غيلان\"، وتمثالا لرأس ثور مثبتا على لوحة مستطيلة من المرمر تحمل نقشا يتضمن عبارة \"معمر كلبن بن سنحم\"، إضافة إلى تمثال برونزي لأبي الهول ودورق برونزي يحمل أربعة أسطر من نقوش المسند.","أما القطعة المقرر عرضها في مزاد تل أبيب، فتصور شابا بملامح هادئة، دون حسم هوية الشخصية التي تجسدها حتى الآن، وفقا لمحسن الذي تناول تفاصيلها في منشور عبر حسابه على \" فيسبوك \".","ويتميز التمثال بوجه بيضوي وعينين لوزيتين وأنف مستقيم وفم صغير، فيما يحيط بالشعر غطاء رأس أو إكليل مزين بزخارف نباتية وعناصر تشبه عناقيد الثمار، إلى جانب زخارف ملتوية تمتد فوق الجبهة.","وتظهر خصل الشعر متموجة ومنسدلة حول الصدغين، بينما يوجد على أحد الكتفين عنصر زخرفي يُرجح ارتباطه بالثوب أو رباط مثبت بعقدة، مع شريط مائل يمتد عبر الصدر. ويحمل سطح القطعة طبقة باتينا بألوان خضراء وبنية محمرة، إلى جانب آثار تآكل وترسبات."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/ygp4excar','https://ajel.sa/international/ygp4excar','https://ajel.sa/international/ygp4excar','https://ajel.sa/international/ygp4excar','فريق التحرير','الجوف','2026-08-29T08:50:00.000Z','Wed, 07 Oct 2026 19:06:37 GMT','2026-08-29T15:09:49.881Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%AA%D9%85%D8%AB%D8%A7%D9%84-%D8%A7%D9%84%D8%A8%D8%B1%D9%88%D9%86%D8%B2%D9%8A-%D8%A7%D9%84%D9%8A%D9%85%D9%86%D9%8A-tbnPXVKp.webp','/api/media/d8850c91-5fba-4cb3-aca2-7c934a9f827d','/api/media/d8850c91-5fba-4cb3-aca2-7c934a9f827d?variant=thumbnail','التمثال البرونزي اليمني',1200,675,'valid','published','archived','valid',41,'d72eb46b3d2dcc841e50fc7136e92c9caf56649764a8b9f1f4565e0e99188570','6047aaf8652403fae565d2d38591fffe6c7c0e65f6b9161165e572c128efe510','محدّث','2026-08-29T15:09:49.881Z','2026-10-07T20:24:32.169Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","الجوف","اليمن"]','["الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:06:38.874Z',200,55,0,'source_content_changed','',NULL,NULL,'body:ae3cf3fd03a25bc563471401417a66a2543dfc33e76fa99fbdb5eb27791117f2','Wed, 07 Oct 2026 19:06:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c5a33b11-5404-4930-8738-8156b7f60b54','news-c5a33b11-5404-4930-8738-8156b7f60b54','إصابة 3 فلسطينيين في قصف إسرائيلي استهدف مستودع أدوية بمستشفى شهداء الأقصى','اصابه 3 فلسطينيين في قصف اسرائيلي استهدف مستودع ادويه بمستشفي شهداء الاقصي','وأفادت مصادر طبية فلسطينية بارتفاع إجمالي حصيلة ضحايا العدوان الإسرائيلي المتواصل على قطاع غزة إلى 73,449 شهيداً و174,472 مصاباً، في صفوفهم أطفال ونساء وعائلات بأكملها.','["أصيب ثلاثة فلسطينيين جراء غارة جوية إسرائيلية شنّها الاحتلال اليوم، استهدفت مستودعاً للأدوية داخل مستشفى شهداء الأقصى في مدينة دير البلح وسط قطاع غزة، وذلك في ظل استمرار الخروقات الإسرائيلية لاتفاق وقف إطلاق النار المبرم مع الفصائل الفلسطينية.","وتتواصل في مناطق متفرقة من القطاع عمليات انتشال جثامين الشهداء من تحت ركام المنازل والمباني السكنية المدمرة، بعد عامين من استمرار العدوان الإسرائيلي على غزة."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/krd3s2b','https://sabq.org/article/krd3s2b','','https://sabq.org/article/krd3s2b','صحيفة سبق','','2026-08-29T09:00:00.000Z','2026-08-29T12:00:00.000Z','2026-08-29T15:09:50.834Z','https://media.sabq.org/news/2026/08/37352faf-0aca-40b6-86b9-e601600c836f/w679.webp','/api/media/c5a33b11-5404-4930-8738-8156b7f60b54','/api/media/c5a33b11-5404-4930-8738-8156b7f60b54?variant=thumbnail','إصابة 3 فلسطينيين في قصف إسرائيلي استهدف مستودع أدوية بمستشفى شهداء الأقصى',679,452,'valid','published','archived','valid',99,'13a17ec8cbe480c7ef65d9052fc8196e07f233c6a86905b4b36172929761e92c','25ffde5c33e7fc1f1d2fd0d17fc9e30ea8e51747b7faf6f8c9bb06349ab0d885','محدّث','2026-08-29T15:09:50.834Z','2026-10-07T20:24:32.171Z','','',0,0,'gulf_arab','عادي',56,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","غزة","فلسطين"]','["الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:05:46.342Z',200,52,0,'source_article_available','',NULL,NULL,'body:e03034227b24564789dccc752bd2886a8b73ada606b5dde067d9a53fe8c58168','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('86253b97-cad7-4720-9767-df1c68d1ff70','news-86253b97-cad7-4720-9767-df1c68d1ff70','حرائق الجزائر تصل قلب العاصمة وحصيلة الضحايا ترتفع إلى 12 قتيلاً','حرائق الجزائر تصل قلب العاصمه وحصيله الضحايا ترتفع الي 12 قتيلا','تواصلت حالة الاستنفار في الجزائر مع اندلاع حرائق جديدة طالت مساحات خضراء داخل العاصمة، ما أثار مخاوف واسعة بين السكان من امتداد موجة النيران التي اجتاحت خلال الأيام الماضية عدداً من الولايات، ولا سيما المناطق الساحلية.','["وكثّفت فرق الحماية المدنية والمصالح المعنية جهودها للسيطرة على الحرائق، بمشاركة مواطنين في عمليات الإخماد، وسط متابعة رسمية مستمرة لتطورات الوضع في المناطق المتضررة.","وأعلن وزير الداخلية والجماعات المحلية السعيد سعيود، الأربعاء الماضي، مقتل 12 شخصاً في آخر حصيلة وطنية رسمية متاحة، فيما أثارت الحرائق قلقاً بالغاً لا سيما أنها طالت ولايات ساحلية تشهد خلال أغسطس حركة واسعة للمصطافين على الشواطئ وفي المناطق الغابية.","ومع إعلان السلطات السيطرة على عدد من الحرائق في الولايات المتضررة، اندلع حريق ليل الجمعة-السبت في منطقة بوزريعة بالعاصمة، بالتزامن مع حريق آخر في بلدية براقي جنوب المدينة، ما زاد المخاوف من وصول النيران إلى مناطق مأهولة قريبة من الغابات والمساحات الخضراء. «القبة الحرارية» وراء الكارثة وفي تفسيره للعوامل التي أسهمت في انتشار الحرائق، أوضح المختص في الأرصاد الجوية رابح قاضي أن الظروف المناخية الاستثنائية لعبت دوراً رئيسياً في تهيئة البيئة الملائمة لاندلاع النيران واتساع رقعتها.","وأشار قاضي إلى أن سيطرة مرتفع جوي شديد في طبقات الجو العليا، يُعرف علمياً بـ«القبة الحرارية»، أسهمت في رفع درجات الحرارة وخلق بيئة شديدة الجفاف تساعد على سرعة الاشتعال، مضيفاً أن درجات الحرارة القصوى اقتربت من 50 درجة مئوية في بعض الولايات الشمالية والشرقية، ما أدى إلى جفاف الغطاء النباتي وجعله أكثر قابلية للاشتعال.","ولفت إلى أن العامل البشري، سواء أكان متعمداً أم غير متعمد، يمكن أن يُسهم في اندلاع بعض الحرائق من خلال ممارسات بسيطة كإلقاء النفايات أو أعقاب السجائر المشتعلة بالقرب من المناطق الخضراء والمأهولة.","كما أشار إلى الدور الذي أدّته الرياح القوية في تأجيج ألسنة اللهب ونقل الشرر إلى مناطق جديدة مأهولة بالسكان، وهو ما صعّب في مراحل عدة عمليات الإخماد والتدخل.","وربط قاضي تزايد حدة هذه الحرائق صيفاً بظاهرة التغير المناخي وما يصاحبها من موجات حر وظواهر جوية متطرفة، معتبراً أن تكرار هذه الظواهر يفرض تعزيز إجراءات الوقاية والاستعداد والتكيف مع المخاطر المناخية."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ul306xx','https://sabq.org/article/ul306xx','','https://sabq.org/article/ul306xx','صحيفة سبق','المنطقة الشرقية','2026-08-29T08:56:00.000Z','2026-08-29T11:56:00.000Z','2026-08-29T15:09:51.883Z','https://media.sabq.org/news/2026/08/3184058b-9583-4339-91db-94619acc6483/w801.webp','/api/media/86253b97-cad7-4720-9767-df1c68d1ff70','/api/media/86253b97-cad7-4720-9767-df1c68d1ff70?variant=thumbnail','حرائق الجزائر تصل قلب العاصمة وحصيلة الضحايا ترتفع إلى 12 قتيلاً',801,451,'valid','published','archived','valid',49,'b19cc73e8745fbc088d9adfdce9988de5e6f240accb1854c2b3a62b31bdbc916','4efa6ef5ccfe0da1685898308412ad82aaec164209f28a840afd2f0fece9506c','محدّث','2026-08-29T15:09:51.883Z','2026-10-07T20:24:32.176Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الداخلية والجماعات المحلية السعيد","الطقس والمناخ","الاقتصاد والأسواق"]','["وزير الداخلية والجماعات المحلية السعيد","الطقس والمناخ","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:05:37.221Z',200,50,0,'source_article_available','',NULL,NULL,'body:835a29ec273a60e3d8b5a81d3ab4ce26c8d647893b206e9ebcfebae0f45516a6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f36faf56-c662-4ee0-b672-f75597a2d72b','news-f36faf56-c662-4ee0-b672-f75597a2d72b','روسيا تسيطر على 3 بلدات في جمهورية دونيتسك الشعبية ومقاطعة سومي','روسيا تسيطر علي 3 بلدات في جمهوريه دونيتسك الشعبيه ومقاطعه سومي','أفادت وزارة الدفاع الروسية، اليوم، بأن القوات المسلحة الروسية سيطرت على بلدتين في جمهورية دونيتسك الشعبية ، وبلدة في مقاطعة سومي. وأشار إلى أن الخسائر البشرية الأوكرانية وقعت في بلدات بيلوزيرسكوي وفيسيلوي بولي وسفياغوروفكا وزولوتوي كولوديز، وسيرغييفكا ودوبروبولي ونوفوغريوريفكا في جمهورية دونيتسك الشعبية، ونوفوبافليفكا في مقاطعة دنيبروبتروفسك.','["أفادت وزارة الدفاع الروسية، اليوم، بأن القوات المسلحة الروسية سيطرت على بلدتين في جمهورية دونيتسك الشعبية ، وبلدة في مقاطعة سومي.","وقالت الدفاع الروسية في بيان، نقلا عن \"سبوتنيك الروسية\"، إنه \"تم تحييد ما يصل إلى 50 جنديًا، ومركبتين قتاليتين مدرعتين و13 مركبة ومحطتين للحرب الإلكترونية\".","وأشار البيان إلى أن \"قوات مجموعة \"دنيبر\" الروسية، حيّدت أفرادًا ودمرت معدات تابعة للواء ميكانيكي ولواء أنظمة غير مأهولة من القوات المسلحة الأوكرانية بالقرب من بلدتي بريوبراجينكا وأوريخوف في مقاطعة زابوروجيه، وأنتونيفكا في مقاطعة خيرسون\".","ووفقًا بيان الدفاع الروسية، فإن \"وحدات من قوات مجموعة \"الجنوب\" الروسية، حسّنت مواقعها على طول خط الجبهة، ملحقة الهزائم بتشكيلات من لواءين ميكانيكيين ولواء محمول جوًا ولواء هجوم جبلي، وفوج هجوم تابع للقوات المسلحة الأوكرانية، وذلك بالقرب من بلدات فاسيليفسكايا بوستوش وكراسني مولوتشار وسلافيانسك و كراماتورسك ونيكولايفكا ودروجكوفكا وفيسوكويفانوفكا في جمهورية دونيتسك الشعبية\".","وفي منطقة سيطرة قوات مجموعة \"المركز\" الروسية، جاء في البيان: \"تضررت معدات وأفراد ألوية مشاة آلية وهجومية تابعة للقوات المسلحة الأوكرانية، ولواء من مشاة البحرية، ولواءين من الحرس الوطني\".","وأشار إلى أن الخسائر البشرية الأوكرانية وقعت في بلدات بيلوزيرسكوي وفيسيلوي بولي وسفياغوروفكا وزولوتوي كولوديز، وسيرغييفكا ودوبروبولي ونوفوغريوريفكا في جمهورية دونيتسك الشعبية، ونوفوبافليفكا في مقاطعة دنيبروبتروفسك.","وأكد البيان الصادر عن وزارة الدفاع الروسية، أنه في منطقة سيطرة قوات مجموعة \"الشمال\" الروسية، فقدت القوات المسلحة الأوكرانية أكثر من 250 جنديًا، و9 مركبات، ومدفع ميداني."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/a6tx4gnv6','https://ajel.sa/international/a6tx4gnv6','https://ajel.sa/international/a6tx4gnv6','https://ajel.sa/international/a6tx4gnv6','فريق التحرير','','2026-08-29T09:07:00.000Z','Wed, 07 Oct 2026 19:34:43 GMT','2026-08-29T15:19:48.907Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-jiQKIfva.jpg','/api/media/f36faf56-c662-4ee0-b672-f75597a2d72b','/api/media/f36faf56-c662-4ee0-b672-f75597a2d72b?variant=thumbnail','روسيا تسيطر على 3 بلدات في جمهورية دونيتسك الشعبية ومقاطعة سومي',1200,675,'valid','published','archived','valid',41,'88748b8f18b2420a2acf2af555577cec93710ebe80694a3ca0f9c194c58868a8','a9faaae7e13878659c4ec69041b323a4466d6c38c0e1b2be27a82cade2e23da2','محدّث','2026-08-29T15:19:48.907Z','2026-10-07T20:24:32.179Z','','',0,0,'international','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الدفاع الروسية اليوم بأن","روسيا"]','["وزارة الدفاع الروسية اليوم بأن"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:34:45.425Z',200,60,0,'source_content_changed','',NULL,NULL,'body:a858189372a0b5b300bcee923fc7c904f600bc13f7921ea8259b118de1647bce','Wed, 07 Oct 2026 19:34:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0383def7-445c-4836-858a-f45673cfac03','news-0383def7-445c-4836-858a-f45673cfac03','37 قتيلاً في ضربة روسية تستهدف مستودع ذخائر قرب كييف وأوكرانيا تفتح تحقيقاً بالإهمال','37 قتيلا في ضربه روسيه تستهدف مستودع ذخائر قرب كييف واوكرانيا تفتح تحقيقا بالاهمال','أسفرت ضربة بطائرة مسيّرة روسية استهدفت مستودعاً للذخائر في أطراف العاصمة الأوكرانية كييف عن مقتل ما لا يقلّ عن 37 شخصاً، مع اندلاع حرائق هائلة وانفجارات متتالية، فيما أعلن مكتب المدعي العام الأوكراني فتح تحقيق بشبهة الإهمال الجنائي.','["وأفاد مكتب المدعي العام الأوكراني بأن المستودع الذي يقع في بلدة ميلا كان يُستخدم لتخزين «مواد متفجّرة»، مشيراً إلى أن التحقيق سيركّز على «مدى قانونية تخزين مواد ومقذوفات متفجّرة في حرم المنشأة»، وما إذا كانت الشركة المعنية تمتلك «التصاريح والموافقات اللازمة».","ذخائر ومسيّرات أكد الرئيس الأوكراني فولوديمير زيلينسكي، السبت، أن المستودع المستهدف كان يحوي ذخائر وطائرات مسيّرة ومتفجّرات يستخدمها الجيش، وقال عبر تطبيق تلغرام: «استهدف الهجوم موقعاً خُزِّنت فيه ذخائر كان ينبغي ألا تكون موجودة فيه - مستودع تابع لقوات الدفاع»، متحدثاً عن «انفجار قذائف وألغام وغيرها من الذخائر والطائرات المسيّرة» جراء الهجوم.","وكتب زيلينسكي على منصة «إكس»: «يجب محاسبة مَن سمحوا بحدوث ذلك على قراراتهم...","لا يمكن تخزين الذخائر بالقرب من المنازل أو المناطق السكنية»، مشيراً إلى أن الانفجار ألحق أضراراً بالمناطق السكنية المحيطة، إضافة إلى دار رعاية للمسنين وذوي الإعاقة.","عرض التغريدة إهمال جنائي قرّر مكتب المدعي العام الأوكراني فتح تحقيق في الحادثة بشبهة «الإهمال الجنائي»، في ظل تساؤلات جدية حول مشروعية تخزين هذه الكميات من المواد المتفجّرة داخل نطاق سكني. 267 مسيّرة وصاروخان أطلقت روسيا ما لا يقلّ عن صاروخين و267 طائرة مسيّرة على أوكرانيا بين مساء الجمعة وصباح السبت، وفق ما أعلن سلاح الجو الأوكراني.","وبالإضافة إلى استهداف المستودع في ميلا، أسفرت هجمات روسية فجر السبت عن مقتل شخص في أوديسا جنوب البلاد، وفتاة تبلغ 14 عاماً في ضاحية بوريسبيل بكييف، بحسب مسؤولين محليين.","في المقابل، أعلنت السلطات الروسية مقتل ثلاثة أشخاص في هجمات أوكرانية على منطقة بيلغورود، تسبّبت في اندلاع حريق في مستودع تابع لشركة «أوزون» العملاقة للتجارة الإلكترونية.","كما أسفرت ضربة على مدينة سيفاستوبول في شبه جزيرة القرم عن مقتل شخص، وفقاً للحاكم الذي تعيّنه السلطات الروسية."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/71g9vbd','https://sabq.org/article/71g9vbd','','https://sabq.org/article/71g9vbd','صحيفة سبق','الحدود الشمالية','2026-08-29T09:16:00.000Z','2026-08-29T12:16:00.000Z','2026-08-29T15:19:50.726Z','https://media.sabq.org/news/2026/08/3c2d56a8-044a-47d2-ab04-a65189af6d31/w801.webp','/api/media/0383def7-445c-4836-858a-f45673cfac03','/api/media/0383def7-445c-4836-858a-f45673cfac03?variant=thumbnail','37 قتيلاً في ضربة روسية تستهدف مستودع ذخائر قرب كييف وأوكرانيا تفتح تحقيقاً بالإهمال',801,451,'valid','published','archived','valid',48,'1f486d0fc0e2e94cd7526be1d9c8796b13a993924263a007f437c81a762b7823','b8a905451ee6d256d410411803a616ac17269ffc97b8c28747923d2ec817e2a2','محدّث','2026-08-29T15:19:50.726Z','2026-10-07T20:24:32.183Z','','',0,0,'saudi_region','مهم',63,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مكتب الرئيس الأوكراني السبت","الطاقة والنفط","السفر والسياحة","الاقتصاد والأسواق","روسيا","أوكرانيا"]','["رئيس مكتب الرئيس الأوكراني السبت","الطاقة والنفط","السفر والسياحة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T19:33:39.114Z',200,56,0,'source_article_available','',NULL,NULL,'body:a47e7dbe1205ea73ab2ec76c4f296b5d431d670f27f10b1466370eae294f5717','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e9c26bd5-386d-4742-81d3-ac23b3e145ba','news-e9c26bd5-386d-4742-81d3-ac23b3e145ba','8 ساعات ليست قاعدة ذهبية.. العلم يكشف الاحتياج الحقيقي للنوم','8 ساعات ليست قاعده ذهبيه العلم يكشف الاحتياج الحقيقي للنوم','لعقود، بدت الإجابة عن سؤال مقدار النوم الذي يحتاجه الإنسان بسيطة: «8 ساعات كل ليلة». وقد قدّرت إحدى الدراسات الحديثة متوسط مدة النوم في المجتمعات ما قبل الصناعية بنحو 6.4 ساعة، وإن كان هذا المتوسط يتفاوت بحسب طريقة القياس والموقع الجغرافي والفصل والظروف البيئية.','["لعقود، بدت الإجابة عن سؤال مقدار النوم الذي يحتاجه الإنسان بسيطة: «8 ساعات كل ليلة».","لكن الأدلة العلمية الحديثة ترسم صورة أكثر تعقيداً، إذ لا يوجد رقم سحري يناسب الجميع، وقد تختلف الحاجة إلى النوم باختلاف العمر والشخص والظروف الصحية ونمط الحياة.","وبحسب تقرير نشره موقع «CNA» نقلاً عن مجلة «The Conversation»، أوضح ديرك-يان دايك، أستاذ النوم وعلم وظائف الأعضاء ومدير مركز أبحاث النوم في جامعة ساري، وزميلته آن سكيلدون، أستاذة الرياضيات والفيزياء في الجامعة، أن الأدلة المتراكمة تشكك في اعتبار 8 ساعات المدة المثالية للجميع.","وتتوافق هذه النتائج مع مراجعة سردية حديثة نُشرت في دورية «Brain Medicine»، تناولت الأدلة المتعلقة بمدة النوم المثلى.","مقدار النوم الطبيعي ولمحاولة فهم أنماط النوم بعيداً عن تأثير الحياة الحديثة، درس باحثون مجتمعات تعتمد على الصيد وجمع الثمار، وتعيش مع قدر محدود للغاية من الإضاءة الاصطناعية.","وتبيّن في إحدى الدراسات أن أفراداً في مجتمعات بتنزانيا وناميبيا وبوليفيا كانوا ينامون بين 5.7 و7.1 ساعة ليلاً، وهي مدد لا يمكن تفسيرها بعوامل حديثة كوسائل التواصل الاجتماعي أو الإضاءة الاصطناعية المكثفة.","ولم يكن هؤلاء يعوضون ذلك عادةً بقيلولة نهارية طويلة، كما كانوا يميلون إلى الاستيقاظ قرب الفجر دون الحاجة إلى منبه.","وقد قدّرت إحدى الدراسات الحديثة متوسط مدة النوم في المجتمعات ما قبل الصناعية بنحو 6.4 ساعة، وإن كان هذا المتوسط يتفاوت بحسب طريقة القياس والموقع الجغرافي والفصل والظروف البيئية."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/v2wtb3r','https://sabq.org/article/v2wtb3r','','https://sabq.org/article/v2wtb3r','صحيفة سبق','الرياض','2026-08-29T09:10:00.000Z','2026-08-29T12:10:00.000Z','2026-08-29T15:19:51.802Z','https://media.sabq.org/news/2026/08/e7da3fae-5fe1-4731-815b-d6609f407491/w801.webp','/api/media/e9c26bd5-386d-4742-81d3-ac23b3e145ba','/api/media/e9c26bd5-386d-4742-81d3-ac23b3e145ba?variant=thumbnail','8 ساعات ليست قاعدة ذهبية.. العلم يكشف الاحتياج الحقيقي للنوم',801,451,'valid','published','archived','valid',44,'a7b3cc6003f52a1eaea5425a70a8bef826c4ac7611550f9e8132c4ad6c2d71eb','7fd4f1524168c79d9dabfb4f8f18a546f9623e674c7d6f7a991914b4f2a932bb','محدّث','2026-08-29T15:19:51.802Z','2026-10-07T20:24:32.187Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة ساري وزميلته آن سكيلدون","الصحة العامة","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق","الرياض"]','["جامعة ساري وزميلته آن سكيلدون","الصحة العامة","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الرياضة","score":3},{"category":"المناطق","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T19:33:35.851Z',200,58,0,'source_article_available','',NULL,NULL,'body:3fe4f02698df090e366a6ffaaa6d4513e7711569efb0db6a12753d1a752feb1a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('514cc45d-080d-4871-9b5d-62f0ca210fde','news-514cc45d-080d-4871-9b5d-62f0ca210fde','"الخارجية الفلسطينية" تدين حصار قرية المغير منذ 20 يوماً وتطالب بتدخل دولي عاجل','الخارجيه الفلسطينيه تدين حصار قريه المغير منذ 20 يوما وتطالب بتدخل دولي عاجل','أدانت وزارة الخارجية الفلسطينية بأشد العبارات تصعيد الاحتلال الإسرائيلي في قرية المغير، شمال مدينة رام الله بالضفة الغربية، وفرضه منذ نحو 20 يوماً إجراءات حصار خانقة على القرية، شملت منع سيارات الإسعاف من الدخول، بالتزامن مع استهداف الفلسطينيين بصورة عشوائية في تصعيد متواصل يستهدف الوجود الفلسطيني في المنطقة.','["وأكدت الوزارة أن تصاعد ما وصفته بـ«إرهاب المستعمرين» وجرائم قوات الاحتلال في الضفة الغربية يعكس سياسة ممنهجة تقوم على «خلق واقع من القتل والإرهاب والتهجير القسري».","وحذّرت الوزارة من أن استمرار تغذية التطرف والعنصرية، بالتزامن مع تسليح المستعمرين وتوفير الحماية والغطاء السياسي والقانوني لهم، يفتح مساراً تصعيدياً قد يصعب على أي طرف التحكم في تداعياته، مما يجعل التدخل الدولي العاجل ضرورة لا تحتمل التأخير.","وطالبت وزارة الخارجية الفلسطينية المجتمع الدولي بجملة من الإجراءات العاجلة، أبرزها: اتخاذ خطوات رادعة وملموسة تتناسب مع جسامة الجرائم المتواصلة في الضفة الغربية، وتوفير الحماية الدولية للشعب الفلسطيني، وتفعيل الولاية والاختصاص القضائي الدولي لملاحقة مرتكبي هذه الجرائم وضمان عدم إفلاتهم من العقاب، فضلاً عن العمل على إنهاء الاحتلال الإسرائيلي وتمكين الشعب الفلسطيني من ممارسة حقوقه الوطنية المشروعة."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/jhldszt','https://sabq.org/article/jhldszt','','https://sabq.org/article/jhldszt','صحيفة سبق','','2026-08-29T09:26:00.000Z','2026-08-29T09:27:00.000Z','2026-08-29T17:46:56.579Z','','','','"الخارجية الفلسطينية" تدين حصار قرية المغير منذ 20 يوماً وتطالب بتدخل دولي عاجل',NULL,NULL,'all_candidates_failed (og:fetch failed | structured:fetch failed | structured:fetch failed | structured:fetch failed)','published','archived','valid',41,'308843e88b681006cb0c0c1f49ed3dde76684de41016f6e621562a5027bd1db4','4c037d8bec82f5b66b61873fc41784621b9a26af21926aa841f87de1a8b582c7','محدّث','2026-08-29T15:28:49.145Z','2026-10-07T20:24:32.190Z','','',0,0,'saudi_national','مهم',67,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الخارجية الفلسطينية بأشد العبارات","السياسة والعلاقات الدولية","فلسطين"]','["وزارة الخارجية الفلسطينية بأشد العبارات","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:33:39.161Z',200,57,0,'source_article_available','',NULL,NULL,'body:807191f17f2be07b7f92d86a44f631718dbf3043d700009bdca1052de0fbdedc','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e8dc130e-32a1-4a62-b253-22aab09bd2eb','news-e8dc130e-32a1-4a62-b253-22aab09bd2eb','القبض على 3 مقيمين من الجنسية الكينية لترويجهم الحشيش بالرياض','القبض علي 3 مقيمين من الجنسيه الكينيه لترويجهم الحشيش بالرياض','ألقت المديرية العامة لمكافحة المخدرات القبض على 3 مقيمين من الجنسية الكينية بمنطقة الرياض لترويجهم 17 كيلوجراما من مادة الحشيش المخدر. وقالت "مكافحة المخدرات" عبر حسابها على منصة "إكس"، إنه تم إيقاف المخالفين، واتخاذ الإجراءات النظامية بحقهم، وإحالتهم إلى النيابة العامة.','["ألقت المديرية العامة لمكافحة المخدرات القبض على 3 مقيمين من الجنسية الكينية بمنطقة الرياض لترويجهم 17 كيلوجراما من مادة الحشيش المخدر.","وقالت \"مكافحة المخدرات\" عبر حسابها على منصة \"إكس\"، إنه تم إيقاف المخالفين، واتخاذ الإجراءات النظامية بحقهم، وإحالتهم إلى النيابة العامة.","وتهيب الجهات الأمنية بالمواطنين والمقيمين الإبلاغ عن أي معلومات تتعلق بتهريب أو ترويج المخدرات، وذلك عبر الرقم (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض و المنطقة الشرقية ، والرقمين (999) و(994) في بقية مناطق المملكة ، أو عبر رقم بلاغات المديرية العامة لمكافحة المخدرات (995)، أو البريد الإلكتروني ( [email&#160;protected] )، مؤكدة أن جميع البلاغات ستُعالج بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/6asn6odkt','https://ajel.sa/local/6asn6odkt','https://ajel.sa/local/6asn6odkt','https://ajel.sa/local/6asn6odkt','فريق التحرير','الرياض','2026-08-29T09:20:00.000Z','Wed, 07 Oct 2026 19:34:48 GMT','2026-08-29T15:37:50.717Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-wMPeQm1z.jpg','/api/media/e8dc130e-32a1-4a62-b253-22aab09bd2eb','/api/media/e8dc130e-32a1-4a62-b253-22aab09bd2eb?variant=thumbnail','القبض على 3 مقيمين من الجنسية الكينية لترويجهم الحشيش بالرياض',1200,675,'valid','published','archived','valid',40,'7918de3128eab0291d912ebc6f8d7d9262c7a3842631dc70ecf453b0fca09621','d8565fe535adecce79cfa9a4e65c77704bcedbfc2dd81f17adae8fbc931779d4','محدّث','2026-08-29T15:37:50.717Z','2026-10-07T20:24:32.193Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي","مكة","الرياض","المدينة المنورة"]','["التقنية والتحول الرقمي","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:34:50.108Z',200,57,0,'source_content_changed','',NULL,NULL,'body:c5f4a85891f642746d0c1778c2a5e7740d1e1c5df4ca81b8e5b437d39fefe67f','Wed, 07 Oct 2026 19:34:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('789fdc18-188d-4f5b-ac74-5ab8ca431387','news-789fdc18-188d-4f5b-ac74-5ab8ca431387','تركيا تستدعي سفير أوكرانيا على خلفية استهداف سفينتين في البحر الأسود','تركيا تستدعي سفير اوكرانيا علي خلفيه استهداف سفينتين في البحر الاسود','أفاد مصدر في وزارة الخارجية التركية، بأن الوزارة استدعت سفير أوكرانيا لدى أنقرة ، على خلفية ضربات نفذتها القوات المسلحة الأوكرانية استهدفت سفينتين تركيتين في البحر الأسود .','["ووفق ما نقلته \"الشرق\"، \"تم استدعاء السفير الأوكراني ناريمان جليال في أنقرة إلى مقر وزارة الخارجية التركية في أعقاب الهجمات التي طالت السفينة المملوكة لشركة تركية \"ليدر بوردو مافي\" يوم 26 أغسطس، بالقرب من طوابسي، والضربة التي استهدفت يوم 27 أغسطس، السفينة \"ليدر كوجاتيبي\" التي تم إرسالها لتقديم المساعدة للسفينة الأولى.","فيما تم إبلاغ السفير برد فعل بلادنا تجاه هذه الهجمات، وتحذيره من ضرورة ضمان سلامة الأرواح، والممتلكات، والملاحة البحرية، والبيئة في البحر الأسود\".","وبدأت أوكرانيا باستهداف السفن التجارية التركية المتجهة إلى روسيا أو القادمة منها بشكل منهجي، ما أدى إلى تصعيد الأزمة الأمنية في ممرات التجارة البحرية والخدمات اللوجستية إلى مستويات غير مسبوقة. وأسفرت هجمات كييف على السفن التجارية التركية عن مقتل مواطنين تركيين وإصابة العشرات، فضلاً عن إلحاق أضرار مادية بالسفن."]','العالم','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/3qf99nz35','https://ajel.sa/international/3qf99nz35','https://ajel.sa/international/3qf99nz35','https://ajel.sa/international/3qf99nz35','فريق التحرير','','2026-08-29T09:19:00.000Z','Wed, 07 Oct 2026 19:34:57 GMT','2026-08-29T15:37:52.580Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-s2pq7ApL.jpg','/api/media/789fdc18-188d-4f5b-ac74-5ab8ca431387','/api/media/789fdc18-188d-4f5b-ac74-5ab8ca431387?variant=thumbnail','تركيا تستدعي سفير أوكرانيا على خلفية استهداف سفينتين في البحر الأسود',1200,675,'valid','published','archived','valid',40,'82bb609bc1c574810d298620a75dbca65b10c9c6d39a343c3828f2f400075247','a62ad3466444584a15a3e3e3e6a7d768aba42dc7d767e482f16e7c91d5f9735c','محدّث','2026-08-29T15:37:52.580Z','2026-10-07T20:24:32.197Z','','',0,0,'saudi_national','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الخارجية التركية بأن الوزارة","السفر والسياحة","الاقتصاد والأسواق","تركيا","روسيا","أوكرانيا"]','["وزارة الخارجية التركية بأن الوزارة","السفر والسياحة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:34:58.782Z',200,52,0,'source_content_changed','',NULL,NULL,'body:5d53479511a77ba13d58bd161bc126e7692bb0890e79436fe866506dcf9edc2c','Wed, 07 Oct 2026 19:34:57 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('50a6ea39-5314-45a2-b8a7-63cf041c2566','news-50a6ea39-5314-45a2-b8a7-63cf041c2566','الدفاع المدني يخمد حريقًا في مخلفات حديد بالدمام دون إصابات','الدفاع المدني يخمد حريقا في مخلفات حديد بالدمام دون اصابات','أخمدت قوات الدفاع المدني ب الدمام ، اليوم السبت، حريقًا اندلع في مخلفات حديد، دون تسجيل إصابات جراء الحادث. وأكدت المديرية العامة للدفاع المدني، عبر حسابها على منصة "إكس"، مباشرة فرقها للحريق والتعامل معه حتى إخماده، مشيرة إلى عدم وجود إصابات.','["أخمدت قوات الدفاع المدني ب الدمام ، اليوم السبت، حريقًا اندلع في مخلفات حديد، دون تسجيل إصابات جراء الحادث.","وأكدت المديرية العامة للدفاع المدني، عبر حسابها على منصة \"إكس\"، مباشرة فرقها للحريق والتعامل معه حتى إخماده، مشيرة إلى عدم وجود إصابات."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/fcn4n8p97','https://ajel.sa/local/fcn4n8p97','https://ajel.sa/local/fcn4n8p97','https://ajel.sa/local/fcn4n8p97','فريق التحرير','المنطقة الشرقية','2026-08-29T09:19:00.000Z','Wed, 07 Oct 2026 19:34:55 GMT','2026-08-29T15:37:52.937Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/HQ5NirYWIAEkGI6-cTCvTEBy.jpg','/api/media/50a6ea39-5314-45a2-b8a7-63cf041c2566','/api/media/50a6ea39-5314-45a2-b8a7-63cf041c2566?variant=thumbnail','حريق في مخلفات حديد بالدمام',1200,675,'valid','published','archived','valid',41,'081fff268ced86f2bf014638995c55351f9e549e490b264c2b120b6e0acdd173','ec4774fd1dc6c5939ab61d825ebc7aa1658cd4ee672eff3944bf6d691d55cf6e','محدّث','2026-08-29T15:37:52.937Z','2026-10-07T20:24:32.201Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الدمام"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:34:56.644Z',200,49,0,'source_content_changed','',NULL,NULL,'body:6c358cec26afe7cadace222703575b280a54be8feda9cc683b084ddff8642132','Wed, 07 Oct 2026 19:34:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b279f864-9725-4d03-8f76-5d18e73af575','news-b279f864-9725-4d03-8f76-5d18e73af575','المدينة المنورة تستنفر منظومة خدمات متكاملة لخدمة زوار المسجد النبوي وإثراء تجربتهم','المدينه المنوره تستنفر منظومه خدمات متكامله لخدمه زوار المسجد النبوي واثراء تجربتهم','وتحظى خدمات زوار المسجد النبوي باهتمام بالغ، من خلال تهيئة المسجد وساحاته ومرافقه، وتنظيم حركة دخول المصلين وخروجهم، والعناية بأعمال النظافة والتعقيم، وتوفير مياه زمزم، وتهيئة دورات المياه ومواقع الوضوء، إلى جانب تشغيل منظومة التبريد التي توفر أجواءً معتدلة ومريحة داخل المسجد على مدار اليوم.','["تتضافر جهود الجهات الحكومية والخدمية في المدينة المنورة لتقديم منظومة شاملة من الخدمات لضيوف الرحمن وزوار المسجد النبوي، منذ وصولهم إلى المدينة حتى مغادرتهم، وسط عناية متواصلة تهدف إلى تيسير رحلتهم الإيمانية، وتعزيز سلامتهم وراحتهم، وإثراء تجربتهم في طيبة الطيبة.","وفي محيط المسجد النبوي تتواصل أعمال تحسين المشهد الحضري وتهيئة مسارات المشاة، وزيادة المساحات الخضراء ومناطق الظل، وتحسين الإنارة والمرافق العامة، إلى جانب تهيئة المسارات لخدمة ذوي الإعاقة والمكفوفين، بما يرفع جودة البيئة الحضرية ويمنح الزائر تجربة أكثر راحة وسهولة.","وتكتمل منظومة الخدمات بجهود القطاعات الأمنية والمرورية والبلدية والتجارية، التي تعمل على تنظيم الحركة والمحافظة على السلامة العامة، ومراقبة المنشآت الغذائية ومرافق الضيافة، وضمان جودة الخدمات المقدمة في الفنادق والمطاعم والأسواق والمواقع التي يقصدها الزوار.","وتبرز في المدينة المنورة كذلك الخدمات المقدمة في المواقع التاريخية والدينية، ومنها مسجد قباء وجبل أحد وموقع شهداء أحد ومساجد المنطقة، من خلال تهيئة المواقع وتوفير اللوحات التعريفية والإرشادية، وتنظيم حركة الزائرين، وإتاحة خدمات النقل والمرافق العامة، بما يعزز معرفتهم بالسيرة النبوية وتاريخ المدينة المنورة.","وتجسّد هذه المنظومة المتكاملة ما توليه القيادة من عناية بضيوف الرحمن، وتسخير مختلف الإمكانات البشرية والتقنية لتقديم خدمات عالية الجودة، تتوافق مع مستهدفات رؤية السعودية 2030 في إثراء تجربة الحاج والمعتمر والزائر، وتمكينهم من أداء عباداتهم وزياراتهم بكل يسر وطمأنينة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/pdf5a2w','https://sabq.org/article/pdf5a2w','','https://sabq.org/article/pdf5a2w','صحيفة سبق','المدينة المنورة','2026-08-29T09:42:00.000Z','2026-08-29T09:44:00.000Z','2026-08-29T18:04:55.870Z','https://media.sabq.org/news/2026/08/baf193cc-77be-4c29-951e-a59b56d67dfd/w1600.webp','/api/media/b279f864-9725-4d03-8f76-5d18e73af575','/api/media/b279f864-9725-4d03-8f76-5d18e73af575?variant=thumbnail','المدينة المنورة تستنفر منظومة خدمات متكاملة لخدمة زوار المسجد النبوي وإثراء تجربتهم',1600,852,'valid','published','archived','valid',69,'22c66e95f4cbb393583506dc60aceebb68d6e585b87db7cb9e4ac303d799ce85','1dde7dd7568bcf4e9a730dafc43eb7d8d302d6da6ad6f2e66660950e09bb8215','محدّث','2026-08-29T15:47:51.735Z','2026-10-07T19:53:01.653Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي","المدينة المنورة"]','["التقنية والتحول الرقمي","المدينة المنورة"]','needs_review','ambiguous_category','[{"category":"المجتمع","score":10.5},{"category":"أخبار السعودية","score":1.5},{"category":"التقنية","score":1.5}]','Active','2026-10-07T19:53:01.653Z',200,51,0,'source_article_available','',NULL,NULL,'body:8885f7f21bb540681990a987d40e5dc0cec0ed3ec28ddae7a7691cbf2537c832','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0572d00e-e12b-4f1e-a9de-54183f7fd628','news-0572d00e-e12b-4f1e-a9de-54183f7fd628','هل كان زلزالًا أم انهيارًا جليديًا؟.. "المسند" يكشف حقيقة "كارثة نيبال" ودور "الاحترار"','هل كان زلزالا ام انهيارا جليديا المسند يكشف حقيقه كارثه نيبال ودور الاحترار','وأوضح الدكتور المسند أن الاحترار المناخي «ليس زلزالًا ولا يولّد الزلازل التكتونية»، لكنه قد يضعف الجليد والتربة الصقيعية والسفوح الجبلية، ما يرفع من احتمال وقوع الانهيارات الجليدية والصخرية في المناطق الجبلية الحساسة.','["أكد أستاذ المناخ بجامعة القصيم سابقًا، الدكتور عبدالله المسند، أنه لم يثبت علميًّا أن زلزالًا تكتونيًّا كان سبب كارثة نيبال المفجعة عام 2026، مشيرًا إلى أن الأدلة الجغرافية والزلزالية المتاحة تشير إلى أن انهيارًا هائلًا للجليد والصخور حدث أولًا، وأن هذا الانهيار نفسه هو الذي ولّد إشارة زلزالية قوية التقطتها أجهزة الرصد.","وأشار إلى أن هيئة المسح الجيولوجي الأمريكية قدّرت طاقة الإشارة الناتجة عن الانهيار بما يعادل تقريبًا زلزالًا بقوة 5.2، وهو ما يفسر الالتباس الذي حدث في الساعات الأولى من الكارثة، حيث صُنّفت الإشارة مبدئيًّا كزلزال تقليدي.","وبحسب الشرح العلمي المتداول، فإن التسلسل الأقرب لما حدث في كارثة نيبال 2026 هو أن كتلة ضخمة من الجليد والصخور تفككت من منطقة مرتفعة، ثم بدأت بالانحدار بسرعة شديدة على السفح، في انهيار جليدي صخري كبير.","وخلال سقوط هذه الكتلة الهائلة واصطدامها بالأرض، تولدت موجات زلزالية قوية التقطتها أجهزة الرصد الزلزالي، وتم تصنيفها في البداية كزلزال بقوة 4.4 تقريبًا، قبل أن يتضح أنها ناجمة عن الانهيار نفسه، وليست عن زلزال تكتوني عميق.","وتشير المعطيات إلى أن الحطام والجليد والمياه اندفعت إلى مجرى نهر «Lhende Khola» في الوادي؛ ما أدى إلى تكوّن أو تعزيز سد طبيعي من الركام (الجليد والصخور) في المجرى، فاحتجز المياه مؤقتًا في أعلى الوادي.","ومع انهيار هذا السد الطبيعي لاحقًا، اندفعت المياه والطين والصخور إلى أسفل الوادي، مسببة فيضانات مدمرة وخسائر كبيرة في المنطقة الواقعة على امتداد مجرى النهر.","وفي هذا السياق، يبيّن التحليل العلمي أن الاحترار المناخي يسهم في تهيئة الظروف لانهيارات من هذا النوع عبر مجموعة من العوامل؛ من أبرزها: ذوبان الجليد داخل الشقوق الصخرية.","تراجع الأنهار الجليدية وفقدان الصخور للدعم الذي كانت توفره."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/en4xc55','https://sabq.org/article/en4xc55','','https://sabq.org/article/en4xc55','صحيفة سبق','القصيم','2026-08-29T10:00:00.000Z','2026-08-29T10:25:00.000Z','2026-08-29T18:47:54.315Z','https://media.sabq.org/news/2026/08/ad91fdec-b8f9-417e-a5b8-132ba6003d59/w770.webp','/api/media/0572d00e-e12b-4f1e-a9de-54183f7fd628','/api/media/0572d00e-e12b-4f1e-a9de-54183f7fd628?variant=thumbnail','هل كان زلزالًا أم انهيارًا جليديًا؟.. "المسند" يكشف حقيقة "كارثة نيبال" ودور "الاحترار"',770,513,'valid','published','archived','valid',42,'148926d421d59752b765f9b59b64a51a714680333a3d3dca3a25b4e44d227975','73f81c2452517748961721618e97833aa49c50681d0f0cfc1b76fe75ee85302b','محدّث','2026-08-29T16:05:49.099Z','2026-10-07T20:24:32.207Z','','',0,0,'saudi_region','مهم',72,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة المسح الجيولوجي الأمريكية قد","الطاقة والنفط","الطقس والمناخ","التعليم والتدريب","القصيم"]','["هيئة المسح الجيولوجي الأمريكية قد","الطاقة والنفط","الطقس والمناخ","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T20:00:09.663Z',200,50,0,'source_article_available','',NULL,NULL,'body:e2399e0b771696fc0b7b99ed3f8e036d089616ffd0adbb2b2058ab9544ec8a8c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6f495bd0-45a1-454b-8663-b3843211ce5e','news-6f495bd0-45a1-454b-8663-b3843211ce5e','مركز العواصف: تسجيل 33 ساعة من الحالات الغبارية في الإقليم','مركز العواصف تسجيل 33 ساعه من الحالات الغباريه في الاقليم','أعلن المركز الإقليمي للعواصف الغبارية والرملية عن تسجيل 33 ساعة من الحالات الغبارية في الإقليم ، خلال يوم أمس 28 أغسطس 2026. وقال المركز في بيان عبر حسابه على منصة "إكس"، إن الإمارات تصدرت الدول المسجلة بعدد 10 ساعات، تليها كل من السعودية و باكستان بعدد 7 ساعات.','["أعلن المركز الإقليمي للعواصف الغبارية والرملية عن تسجيل 33 ساعة من الحالات الغبارية في الإقليم ، خلال يوم أمس 28 أغسطس 2026.","وقال المركز في بيان عبر حسابه على منصة \"إكس\"، إن الإمارات تصدرت الدول المسجلة بعدد 10 ساعات، تليها كل من السعودية و باكستان بعدد 7 ساعات.","وأضاف المركز في بيانه أن الأردن سجلت 6 ساعات غبارية، ثم مصر التي جاءت بعدد ساعتان، فيما لم تسجل أي ساعات من الحالات الغبارية في بقية دول الإقليم."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/xx57jz01h','https://ajel.sa/local/xx57jz01h','https://ajel.sa/local/xx57jz01h','https://ajel.sa/local/xx57jz01h','فريق التحرير','','2026-08-29T09:56:00.000Z','Wed, 07 Oct 2026 20:00:42 GMT','2026-08-29T16:05:49.642Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-T4k7N_wS.jpg','/api/media/6f495bd0-45a1-454b-8663-b3843211ce5e','/api/media/6f495bd0-45a1-454b-8663-b3843211ce5e?variant=thumbnail','مركز العواصف: تسجيل 33 ساعة من الحالات الغبارية في الإقليم',1200,675,'valid','published','archived','valid',40,'6719a161ef6c082da670f4579dca54b915e2bd906063bcaf0067661e5930c687','3dd79208c7dc0976d6352171da643c837b4ef5128cbaf8d2e91c5ce1061ccc0d','محدّث','2026-08-29T16:05:49.642Z','2026-10-07T20:00:44.151Z','','',0,0,'saudi_national','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:00:44.151Z',200,53,0,'source_content_changed','',NULL,NULL,'body:4851682d28929e18e82f939d7d957b76afe87c6a8886cf18f5e996b4dc0f7a90','Wed, 07 Oct 2026 20:00:42 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a8aab18f-291f-4a14-b44b-6eddb992b92d','news-a8aab18f-291f-4a14-b44b-6eddb992b92d','الخارجية الأمريكية: توسيع «عملية المنبوذ الاقتصادي» ضد إيران','الخارجيه الامريكيه توسيع عمليه المنبوذ الاقتصادي ضد ايران','أكد المتحدث باسم الخارجية الأمريكية تومي بيجوت استمرار ما وصفه بـ«عملية المنبوذ الاقتصادي» ضد إيران ، معلنًا عن عقوبات وإجراءات تستهدف قنوات مالية قال إنها تتيح للنظام الإيراني الوصول إلى النظام المالي الدولي والدولار الأميركي.','["وقال بيجوت: «تستمر ’عملية المنبوذ الاقتصادي‘ (Operation Economic Outcast) بكامل قوتها»، موضحًا أن الولايات المتحدة فرضت أمس عقوبات على رضا محمد تأييدي، مدير فرع مصرف بنك ملي الإيراني في دبي .","وبحسب المتحدث الأمريكي، كان مصرف بنك ملي بمثابة مركز مالي حيوي للقوات المسلحة الإيرانية، بما في ذلك فيلق القدس التابع للحرس الثوري الإيراني ووزارة الدفاع والشؤون اللوجستية للقوات المسلحة، وهما كيانان خاضعان لعقوبات أميركية.","وفي خطوة أخرى، فرضت الولايات المتحدة عقوبات على شركة مقرها هونج كونج ، قال بيجوت إنها ساعدت أفرادًا وكيانات إيرانية مدرجة على قائمة العقوبات في الوصول إلى النظام المالي الدولي.","كما اقترحت شبكة مكافحة الجرائم المالية التابعة ل وزارة الخزانة الأمريكية (FinCEN) قاعدة من شأنها إلغاء حق فرع بنك مصر في دولة الإمارات العربية المتحدة ، بصفته بنكًا مراسلًا، في الوصول إلى المؤسسات المالية الأميركية.","وترى وزارة الخزانة الأميركية أن فرع بنك مصر في الإمارات يمثل نقطة وصل حاسمة تتيح للنظام الإيراني الوصول إلى الدولار الأمريكي.","وتأتي هذه الإجراءات ضمن ما وصفته الخارجية الأمريكية باستمرار «عملية المنبوذ الاقتصادي» بكامل قوتها، في وقت تستهدف فيه واشنطن قنوات مالية مرتبطة بإيران بإجراءات عقابية وتنظيمية."]','السياسة','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/l4ztm9jdm','https://ajel.sa/international/l4ztm9jdm','https://ajel.sa/international/l4ztm9jdm','https://ajel.sa/international/l4ztm9jdm','فريق التحرير','','2026-08-29T09:53:00.000Z','Wed, 07 Oct 2026 20:00:39 GMT','2026-08-29T16:05:50.531Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-sF32Wd5b.jpg','/api/media/a8aab18f-291f-4a14-b44b-6eddb992b92d','/api/media/a8aab18f-291f-4a14-b44b-6eddb992b92d?variant=thumbnail','تومي بيجوت',1200,675,'valid','published','archived','valid',41,'66eb939a63d583bbe0f29a6780776252412811cb3842466b5e8bd4b17f3d2890','d4c02524275c071ba23c691519d369d21b3583996fe9c3a77e85713613f4dd8e','محدّث','2026-08-29T16:05:50.531Z','2026-10-07T20:24:32.213Z','','',0,0,'gulf_arab','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","شركة مقرها هونج كونج قال","وزارة الخزانة الأمريكية FinCEN قاعدة","الاقتصاد والأسواق","إيران","الولايات المتحدة"]','["شركة مقرها هونج كونج قال","وزارة الخزانة الأمريكية FinCEN قاعدة","الاقتصاد والأسواق","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:00:41.409Z',200,52,0,'source_content_changed','',NULL,NULL,'body:1a54bce0342ea672fbca630af4412d5f0f5e9a9065810c9ff1da5a723236412e','Wed, 07 Oct 2026 20:00:39 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('772a499d-77ac-40c9-a953-c6c485832de7','news-772a499d-77ac-40c9-a953-c6c485832de7','وزير الصحة: متوسط عمر الإنسان في عسير الأعلى بالمملكة','وزير الصحه متوسط عمر الانسان في عسير الاعلي بالمملكه','أكد وزير الصحة فهد الجلاجل أن منطقة عسير تشهد حراكًا صحيًا مستمرًا، مشيرًا إلى أن متوسط عمر الإنسان فيها يُعد الأعلى على مستوى المملكة ، وأن المشاريع الصحية النوعية بالمنطقة أسهمت في خفض نسب الإحالات الطبية إلى المستشفيات التخصصية. وأوضح وزير الصحة أن هذه المشاريع أسهمت في خفض نسب الإحالات الطبية للمستشفيات التخصصية، إلى جانب تسجيل عسير أعلى متوسط لعمر…','["وقال الجلاجل، في تصريحات لقناة «الإخبارية»، إن الحراك الصحي المتواصل في عسير يأتي بالتزامن مع تنفيذ مشاريع نوعية انعكست على الخدمات الصحية في المنطقة.","وأوضح وزير الصحة أن هذه المشاريع أسهمت في خفض نسب الإحالات الطبية للمستشفيات التخصصية، إلى جانب تسجيل عسير أعلى متوسط لعمر الإنسان بالمملكة.","وفي سياق متصل، وقف أمير منطقة عسير الأمير تركي بن طلال بن عبدالعزيز على الخدمات الصحية في المنطقة، بحضور وزير الصحة فهد الجلاجل ووزير التعليم يوسف بن عبدالله البنيان."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/3xifm2u1d','https://ajel.sa/local/3xifm2u1d','https://ajel.sa/local/3xifm2u1d','https://ajel.sa/local/3xifm2u1d','فريق التحرير','عسير','2026-08-29T09:45:00.000Z','Wed, 07 Oct 2026 20:00:42 GMT','2026-08-29T16:05:52.240Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%88%D8%B2%D9%8A%D8%B1-%D8%A7%D9%84%D8%B5%D8%AD%D8%A9-%D9%81%D9%87%D8%AF-%D8%A7%D9%84%D8%AC%D9%84%D8%A7%D8%AC%D9%84-vzTGO4Rj.jpg','/api/media/772a499d-77ac-40c9-a953-c6c485832de7','/api/media/772a499d-77ac-40c9-a953-c6c485832de7?variant=thumbnail','وزير الصحة فهد الجلاجل',1200,675,'valid','published','archived','valid',46,'30995947f5b2db5cf0f8ee1e4a857c2500c480a728db640e7012162b1da8383d','2471f8c2e2619edf91e91b596b198530a7612a8e8110621d962000e9a56cf0c0','محدّث','2026-08-29T16:05:52.240Z','2026-10-07T20:24:32.216Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الصحة متوسط عمر الإنسان","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق","عسير"]','["وزير الصحة متوسط عمر الإنسان","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:00:44.175Z',200,54,0,'source_content_changed','',NULL,NULL,'body:f1fe0b12509c4d9f5639476cec836e7b0b0d79de6c19a4a93281bbea4c79989b','Wed, 07 Oct 2026 20:00:42 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d9c2a002-5fcf-498d-b69c-ba75af15db4b','news-d9c2a002-5fcf-498d-b69c-ba75af15db4b','المياه الوطنية توضح أسباب تأخر خدمة المياه في رتاج مكة وتكشف موعد الضخ','المياه الوطنيه توضح اسباب تاخر خدمه المياه في رتاج مكه وتكشف موعد الضخ','أوضحت شركة المياه الوطنية، رداً على ما نشرته صحيفة «سبق» بتاريخ 27/08/2026 تحت عنوان «سكان رتاج مكة يطالبون باستكمال الخدمات ومعالجة تحديات المياه والمرافق»، أن مشروع تنفيذ شبكات المياه في المنطقة يندرج ضمن أعمال الجهة المطورة للمشروع، ولن يُضخ الماء إلا بعد اكتمال تلك الأعمال وإجراء الاختبارات التشغيلية المطلوبة.','["وأشارت الشركة إلى أنه لم تُستوفَ المتطلبات اللازمة للضخ والتشغيل حتى الآن، إذ تعمل حالياً على إيجاد حلول هندسية تُيسّر إجراء التجارب التشغيلية تمهيداً لبدء الضخ في المنطقة، وذلك عند اكتمال أعمال المطور وفق التصاميم المعتمدة من الشركة.","وفي انتظار اكتمال المشروع، أكدت شركة المياه الوطنية توفير خدمة المياه للأحياء غير المخدومة بالشبكة عبر خدمة طلب الصهاريج المتاحة على مدار الساعة، والتي تتيح للعملاء الحصول على صهريج مياه أو طلب صهريج لسحب مياه الصرف الصحي، من خلال القنوات الرقمية للشركة.","ودعت الشركة عملاءها إلى التواصل معها عبر الفرع الإلكتروني (ebranch.nwc.com.sa)، أو الاتصال بالرقم الموحد 8004411110، للإبلاغ عن أي ملاحظة أو استفسار."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/AHHPM--','https://sabq.org/article/AHHPM--','','https://sabq.org/article/AHHPM--','عبدالرزاق البجالي','مكة المكرمة','2026-08-29T09:49:00.000Z','2026-08-29T12:49:00.000Z','2026-08-29T16:05:52.384Z','https://media.sabq.org/news/2026/08/269aa77b-5db1-4ed0-b9c0-2ebd9a5354f2/w1198.webp','/api/media/d9c2a002-5fcf-498d-b69c-ba75af15db4b','/api/media/d9c2a002-5fcf-498d-b69c-ba75af15db4b?variant=thumbnail','المياه الوطنية توضح أسباب تأخر خدمة المياه في رتاج مكة وتكشف موعد الضخ',1198,931,'valid','published','archived','valid',46,'8207f93655074879efeab7ecf8497938829e7974254f77f194c829cfdf121b80','4b61bde0b858926b42bef8f087d8e870eb0facd99b41ee47900aa5f96cae8802','محدّث','2026-08-29T16:05:52.384Z','2026-10-07T20:00:37.666Z','','',0,0,'saudi_region','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة المياه الوطنية ردا على","التقنية والتحول الرقمي","مكة"]','["شركة المياه الوطنية ردا على","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"المناطق","score":3},{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:00:37.666Z',200,49,0,'source_article_available','',NULL,NULL,'body:05a6b3a45a1cc69b0dac916079d7ef24ca9d86068e76d2b206a9d181341d5162','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0fa28c24-4df1-43c6-ad29-8d6ebc76a658','news-0fa28c24-4df1-43c6-ad29-8d6ebc76a658','"سنتكوم" تكشف حصيلة الحصار البحري على إيران.. تغيير مسار 82 سفينة وتعطيل 3','سنتكوم تكشف حصيله الحصار البحري علي ايران تغيير مسار 82 سفينه وتعطيل 3','كشفت القيادة المركزية الأمريكية (سنتكوم) أن قواتها البحرية نفّذت حتى 28 أغسطس/آب سلسلة من العمليات البحرية لتطبيق الحصار المفروض على إيران، شملت تغيير مسار 82 سفينة تجارية، وتعطيل 3 سفن، وتفتيش سفينتين للتحقق من امتثالها للقيود المفروضة.','["وتضطلع المدمرة «يو إس إس جون بول جونز» (DDG 53) بدور محوري في هذه العمليات، إذ ترابط طواقمها في دوريات مراقبة مستمرة داخل المياه الإقليمية المعنية، بهدف ضمان الالتزام الكامل بشروط الحصار.","وتأتي هذه العمليات في سياق الضغوط العسكرية والاقتصادية التي تمارسها الولايات المتحدة على إيران، في ظل تصاعد التوترات الإقليمية المرتبطة بالملف النووي الإيراني."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/hu7r1uf','https://sabq.org/article/hu7r1uf','','https://sabq.org/article/hu7r1uf','صحيفة سبق','','2026-08-29T09:50:00.000Z','2026-08-29T12:50:00.000Z','2026-08-29T16:05:52.691Z','https://media.sabq.org/news/2026/08/2465b9f3-0fb7-4e21-b4ef-a0c509421320/w1200.webp','/api/media/0fa28c24-4df1-43c6-ad29-8d6ebc76a658','/api/media/0fa28c24-4df1-43c6-ad29-8d6ebc76a658?variant=thumbnail','"سنتكوم" تكشف حصيلة الحصار البحري على إيران.. تغيير مسار 82 سفينة وتعطيل 3',1200,800,'valid','published','archived','valid',40,'bc8920b2bd87bdb25b7bba5247d7d9a5dab49a6127e481352600224f08b24104','a0a3c5b86b8be5e97b326f5007a45fba6d329cc91d2cde14ca36bd929350aa7a','محدّث','2026-08-29T16:05:52.691Z','2026-10-07T20:24:32.223Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الاقتصاد والأسواق","إيران","الولايات المتحدة"]','["الرياضة السعودية","الاقتصاد والأسواق","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"التقنية","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:00:07.192Z',200,53,0,'source_article_available','',NULL,NULL,'body:c33107950d5b48b817d2f80a2f11f8508b6a7e5eff250fdb52edcd37d5650408','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ee7c29cc-8178-49e2-9d72-10a69f524029','news-ee7c29cc-8178-49e2-9d72-10a69f524029','منظومة خدمات متكاملة تعزز تجربة زوار المسجد النبوي بالمدينة المنورة','منظومه خدمات متكامله تعزز تجربه زوار المسجد النبوي بالمدينه المنوره','تكثف الجهات الحكومية والخدمية في المدينة المنورة جهودها لتقديم منظومة متكاملة من الخدمات لضيوف الرحمن وزوار المسجد النبوي، منذ لحظة وصولهم إلى المدينة وحتى مغادرتهم، بهدف تسهيل رحلتهم الإيمانية وتعزيز سلامتهم وراحتهم.','["وتشمل الخدمات تهيئة المسجد النبوي وساحاته ومرافقه، وتنظيم دخول المصلين وخروجهم، إلى جانب العناية بأعمال النظافة والتعقيم، وتوفير مياه زمزم، وتهيئة دورات المياه ومواقع الوضوء. كما يجري تشغيل منظومة التبريد على مدار اليوم لتوفير أجواء معتدلة ومريحة داخل المسجد.","وفي محيط المسجد النبوي، تتواصل أعمال تحسين المشهد الحضري، وتهيئة مسارات المشاة، وزيادة المساحات الخضراء ومناطق الظل، وتحسين الإنارة والمرافق العامة. كما تُخصص مسارات لخدمة ذوي الإعاقة والمكفوفين، ما يسهم في رفع جودة البيئة الحضرية وتوفير تجربة مريحة وسهلة للزوار.","تتكامل جهود القطاعات الأمنية والمرورية والبلدية والتجارية لتنظيم حركة الزوار والحفاظ على السلامة العامة، إضافة إلى مراقبة المنشآت الغذائية ومرافق الضيافة وضمان جودة الخدمات المقدمة في الفنادق والمطاعم والأسواق.","وتبرز أيضًا الخدمات المقدمة في المواقع التاريخية والدينية مثل مسجد قباء و جبل أحد وموقع شهداء أحد ومساجد المنطقة، من خلال تهيئة المواقع وتوفير اللوحات التعريفية والإرشادية، وتنظيم حركة الزائرين وتوفير خدمات النقل والمرافق العامة، بما يعزز معرفة الزوار بتاريخ المدينة المنورة والسيرة النبوية.","وتجسد هذه الجهود المتواصلة العناية التي توليها القيادة الرشيدة لضيوف الرحمن، وتسخير كافة الإمكانات البشرية والتقنية لتقديم خدمات عالية الجودة تتوافق مع مستهدفات رؤية السعودية 2030 في إثراء تجربة الحاج والمعتمر والزائر."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/3wha30g6t','https://ajel.sa/local/3wha30g6t','https://ajel.sa/local/3wha30g6t','https://ajel.sa/local/3wha30g6t','فريق التحرير','المدينة المنورة','2026-08-29T10:13:00.000Z','Wed, 07 Oct 2026 20:50:53 GMT','2026-08-29T16:23:50.597Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-08/source-TZCbYAAR.jpg','/api/media/ee7c29cc-8178-49e2-9d72-10a69f524029','/api/media/ee7c29cc-8178-49e2-9d72-10a69f524029?variant=thumbnail','منظومة خدمات متكاملة تعزز تجربة زوار المسجد النبوي بالمدينة المنورة',1200,675,'valid','published','archived','valid',40,'52d9a993ebc29f152c38789f7f0a0c1ae61b710a278f191c00950838e745182f','67113bc8088a9c5428f6d667be5d0ba4acb1678357c4865a470230b382f53089','محدّث','2026-08-29T16:23:50.598Z','2026-10-07T20:50:55.238Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي","المدينة المنورة"]','["التقنية والتحول الرقمي","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"البيئة والمناخ","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T20:50:55.238Z',200,56,0,'source_content_changed','',NULL,NULL,'body:4191dc3c33b83a7ad015787693444b0489785b2b99f1a25207e3beb9e9a3d265','Wed, 07 Oct 2026 20:50:53 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2984981b-d005-4983-87ce-6be4709b8a56','news-2984981b-d005-4983-87ce-6be4709b8a56','الخارجية الفلسطينية تطالب المجتمع الدولي بإجراءات رادعة ضد جرائم الاحتلال والمستعمرين بالضفة الغربية','الخارجيه الفلسطينيه تطالب المجتمع الدولي باجراءات رادعه ضد جرائم الاحتلال والمستعمرين بالضفه الغربيه','وأكدت الوزارة في بيان رسمي نقلا عن وكالة " وفا " الفلسطينية أن تصاعد إرهاب المستعمرين وجرائم قوات الاحتلال في الضفة الغربية، يعكس سياسة تقوم على خلق واقع من القتل والإرهاب والتهجير القسري.','["أدانت وزارة الخارجية الفلسطينية بأشد العبارات تصعيد الاحتلال الإسرائيلي في قرية المغير ، شمال مدينة رام الله ب الضفة الغربية ، وفرضه منذ نحو 20 يومًا إجراءات حصار خانقة على القرية، إضافة إلى منع سيارات الإسعاف من الدخول، بالتزامن مع استهداف الفلسطينيين بصورة عشوائية، في تصعيد متواصل يستهدف الوجود الفلسطيني في القرية.","وأشارت الخارجية الفلسطينية إلى أن استمرار تغذية الإرهاب والتطرف والعنصرية، بالتزامن مع التسليح والحماية والغطاء السياسي والقانوني للمستعمرين، يفتح مسارًا تصعيديًا قد يصبح من الصعب على أي طرف التحكم بتداعياته؛ مما يجعل التدخل الدولي العاجل ضروريًا لوقف هذا المسار.","وطالبت وزارة الخارجية الفلسطينية المجتمع الدولي باتخاذ خطوات رادعة وملموسة، تتناسب مع جسامة الجرائم المتواصلة في الضفة الغربية، والعمل بصورة عاجلة على توفير الحماية الدولية للشعب الفلسطيني، وتفعيل الولاية والاختصاص القضائي الدولي لملاحقة مرتكبي هذه الجرائم وضمان عدم إفلاتهم من العقاب، والعمل على إنهاء الاحتلال الإسرائيلي لأرض دولة فلسطين المحتلة، وتمكين الشعب الفلسطيني من ممارسة حقوقه الوطنية المشروعة، وفي مقدمتها حقه في تقرير المصير وتجسيد دولته المستقلة على خطوط الرابع من يونيو عام 1967 وعاصمتها القدس ."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/rywa5houm','https://ajel.sa/international/rywa5houm','https://ajel.sa/international/rywa5houm','https://ajel.sa/international/rywa5houm','فريق التحرير','','2026-08-29T10:09:00.000Z','Wed, 07 Oct 2026 20:51:45 GMT','2026-08-29T16:23:53.905Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-wRvINx9h.jpg','/api/media/2984981b-d005-4983-87ce-6be4709b8a56','/api/media/2984981b-d005-4983-87ce-6be4709b8a56?variant=thumbnail','الخارجية الفلسطينية تطالب المجتمع الدولي بإجراءات رادعة ضد جرائم الاحتلال والمستعمرين بالضفة الغربية',1200,675,'valid','published','archived','valid',41,'1a35d002d3cfa66e7bed6b2464d3bf14f71f8bcf93211914cae6941502f4bc27','83e803d1c54c9ea9baa1edee3fa1a4ad67fbbe4d1eca0fff8641c6fdbd5ba445','محدّث','2026-08-29T16:23:53.905Z','2026-10-07T20:51:46.852Z','','',0,0,'saudi_national','عادي',61,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الخارجية الفلسطينية بأشد العبارات","السياسة والعلاقات الدولية","فلسطين"]','["وزارة الخارجية الفلسطينية بأشد العبارات","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:51:46.852Z',200,63,0,'source_content_changed','',NULL,NULL,'body:9972e6f48aa5fba1be3f943f2efb3cb1f1b322c48518e6ab70156a1775f76991','Wed, 07 Oct 2026 20:51:45 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('69f1e1aa-bd10-4182-b593-fa294ec02eee','news-69f1e1aa-bd10-4182-b593-fa294ec02eee','"حافلات مكة" تُصدر دليلاً إرشادياً للطلاب مع بداية العام الدراسي وخصم 50% على التذاكر','حافلات مكه تصدر دليلا ارشاديا للطلاب مع بدايه العام الدراسي وخصم 50 علي التذاكر','أصدرت «حافلات مكة» دليلاً إرشادياً بعنوان «كيف تصل إلى مدرستك»، استعداداً لعودة الطلاب والطالبات إلى مدارسهم في مكة المكرمة، يتضمن معلومات شاملة عن المدارس الواقعة بالقرب من مسارات ومحطات شبكة الحافلات، بهدف مساعدة الطلاب وأولياء الأمور على معرفة خيارات التنقل المتاحة مع انطلاق العام الدراسي.','["ويوضح الدليل آلية الوصول إلى المدارس عبر شبكة الحافلات، من خلال البحث عن اسم المدرسة، والتعرف على رقم المسار ولونه، وتحديد أقرب محطة، إضافةً إلى بيان المسافة التقريبية سيراً على الأقدام من المحطة إلى المدرسة.","وشمل الدليل مدارس في عدد من أحياء ومناطق مكة المكرمة الواقعة على مسارات الشبكة، من بينها: بطحاء قريش، والعزيزية، والعكيشية، وجرول، وكدي، وأجياد، والعوالي، والرصيفة، وأم الجود، والشرائع، والجعرانة، والجامعة، والشهداء، مع تحديد رقم المحطة والمسافة بين كل محطة والمدرسة المدرجة.","وفي إطار دعم تنقلات الطلاب، وفّرت «حافلات مكة» خصماً بنسبة 50% على التذاكر والباقات لطلاب وطالبات مكة المكرمة، تيسيراً للتنقل من المدارس وإليها.","ويأتي إصدار الدليل ضمن استعدادات منظومة «حافلات مكة»، أحد مشاريع المركز العام للنقل التابع للهيئة الملكية لمدينة مكة المكرمة والمشاعر المقدسة، الرامية إلى توفير شبكة نقل متكاملة بالحافلات تربط أحياء ومواقع حيوية في المدينة عبر مسارات ومحطات موزعة في أرجائها."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/dgrc5pq','https://sabq.org/article/dgrc5pq','','https://sabq.org/article/dgrc5pq','صحيفة سبق','مكة المكرمة','2026-08-29T10:24:00.000Z','2026-08-29T13:24:00.000Z','2026-08-29T16:32:51.733Z','https://media.sabq.org/news/2026/08/df68f332-17fd-4ee3-872a-d4ba66d606be/w1149.webp','/api/media/69f1e1aa-bd10-4182-b593-fa294ec02eee','/api/media/69f1e1aa-bd10-4182-b593-fa294ec02eee?variant=thumbnail','"حافلات مكة" تُصدر دليلاً إرشادياً للطلاب مع بداية العام الدراسي وخصم 50% على التذاكر',1149,695,'valid','published','archived','valid',47,'0460cd9f4b10bccc93710ac4db53eecf5e95357b8d43e795fd972ae0615ad6e4','b0efbd9271eda5470b79da27e41b7e56ade77ce79a7a16626e6e0f93851c179d','محدّث','2026-08-29T16:32:51.733Z','2026-10-07T21:00:46.627Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","مكة"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:00:46.627Z',200,57,0,'source_article_available','',NULL,NULL,'body:a25ae4232d6332d20db6ac39763eed50c9b4459d8aacab2a56dd2ae74f8a556f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('07c2da81-9705-4ebc-bdcc-c7715f4103e0','news-07c2da81-9705-4ebc-bdcc-c7715f4103e0','مجموعة السهلي السعودية توقّع مذكرة تفاهم لإنشاء مشاريع متكاملة ونموذجية لقطاع الدواجن في سوريا','مجموعه السهلي السعوديه توقع مذكره تفاهم لانشاء مشاريع متكامله ونموذجيه لقطاع الدواجن في سوريا','وقّعت وزارة الزراعة السورية ومجموعة السهلي السعودية ومجموعة الدروبي السورية مذكرة تفاهم، على هامش معرض دمشق الدولي، بهدف إنشاء مشاريع متكاملة ونموذجية لتطوير قطاع الدواجن وسلاسل القيمة المرتبطة به في سوريا.','["ووقّع المذكرة وزير الزراعة السوري باسل السويدان، ومن جانب مجموعة السهلي السعودية الرئيس التنفيذي سعد بن عبدالمحسن، ومن جانب مجموعة الدروبي السورية رئيس مجلس الإدارة الدكتور مسلم الدروبي.","وتهدف المذكرة إلى تطوير منظومة متكاملة لقطاع الدواجن، بما يسهم في رفع كفاءة الإنتاج وتحقيق استقراره، وخفض التكاليف، ودعم المربين، وتطوير سلاسل القيمة، وصولًا إلى تعزيز الأمن الغذائي واستدامة الإنتاج في سوريا.","وتأتي هذه الخطوة في إطار تعزيز التعاون والاستثمار في القطاع الزراعي والغذائي، والاستفادة من الخبرات والإمكانات الاستثمارية والفنية لتطوير مشاريع نوعية تسهم في دعم الإنتاج المحلي وتعزيز استدامته."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ut00j50','https://sabq.org/article/ut00j50','','https://sabq.org/article/ut00j50','صحيفة سبق','المنطقة الشرقية','2026-08-29T10:31:00.000Z','2026-08-29T10:42:00.000Z','2026-08-29T19:55:55.504Z','https://media.sabq.org/news/2026/08/3073e1b2-c110-4e23-91ad-a702900f3b18/w1280.webp','/api/media/07c2da81-9705-4ebc-bdcc-c7715f4103e0','/api/media/07c2da81-9705-4ebc-bdcc-c7715f4103e0?variant=thumbnail','مجموعة السهلي السعودية توقّع مذكرة تفاهم لإنشاء مشاريع متكاملة ونموذجية لقطاع الدواجن في سوريا',1280,736,'valid','published','archived','valid',47,'a298b74418c23a27bb6820a167c37761079b69b2f468a3e1c9d7d392fc231008','5b02c251887621f9f27b9b5c52c03c5e8ee5c7da7de4af9fad80bd04beb9d6f2','محدّث','2026-08-29T16:41:49.119Z','2026-10-07T21:07:58.909Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس الإدارة الدكتور مسلم","مجلس الإدارة الدكتور مسلم الدروبي","وزير الزراعة السوري باسل السويدان","وزارة الزراعة السورية ومجموعة السهلي","الاقتصاد والأسواق","سوريا"]','["رئيس مجلس الإدارة الدكتور مسلم","مجلس الإدارة الدكتور مسلم الدروبي","وزير الزراعة السوري باسل السويدان","وزارة الزراعة السورية ومجموعة السهلي","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:07:58.909Z',200,59,0,'source_article_available','',NULL,NULL,'body:0881edd7485f68c79119e2b615486b65caccfff7378026aadfc75f3b3d1bdcab','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a4050043-895b-47a1-9495-3d3ebcc10721','news-a4050043-895b-47a1-9495-3d3ebcc10721','سوريا تحبط تهريب 138 كليوجراما من الحشيش و382 ألف حبة مخدرة في السويداء','سوريا تحبط تهريب 138 كليوجراما من الحشيش و382 الف حبه مخدره في السويداء','وأعلنت الإدارة، اليوم السبت، ضبط ومصادرة 138 كيلوجرامًا من مادة الحشيش المخدر و382 ألف حبة مخدرة، كانت بحوزة مجموعات خارجة عن القانون في المحافظة، بحسب وكالة الأنباء السورية «سانا».','["أحبطت إدارة مكافحة المخدرات في وزارة الداخلية السورية محاولة تهريب دولية لشحنة من المواد المخدرة، بعد عملية أمنية نُفذت في الريف الشرقي ل محافظة السويداء ، وأسفرت عن ضبط كميات كبيرة من الحشيش والحبوب المخدرة.","وأوضحت إدارة مكافحة المخدرات عبر قناتها على «تلجرام» أن الجهات المختصة تواصل تحرياتها ومتابعتها الأمنية لكشف المتورطين في محاولة التهريب وملاحقتهم، تمهيدًا لاتخاذ الإجراءات القانونية اللازمة بحقهم.","وتأتي العملية في إطار ملاحقة محاولات تهريب المواد المخدرة، فيما لم تعلن الإدارة عن هوية المتورطين الذين يجري البحث عنهم في القضية.","وفي واقعة منفصلة، أعلن فرع مكافحة المخدرات في محافظة دير الزور إلقاء القبض على أحد تجار المخدرات في المنطقة، خلال عملية مداهمة نفذها بالتعاون مع مديرية أمن المدينة وقوات المهام الخاصة.","وأسفرت العملية عن ضبط 37 كيلوجرامًا من مادة الحشيش المخدر، إلى جانب كمية من مادة الأتش بوز وأدوية مخدرة، بالإضافة إلى أسلحة متنوعة وذخائر."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/mepzsl5bx','https://ajel.sa/international/mepzsl5bx','https://ajel.sa/international/mepzsl5bx','https://ajel.sa/international/mepzsl5bx','فريق التحرير','','2026-08-29T10:47:00.000Z','Wed, 07 Oct 2026 21:11:34 GMT','2026-08-29T16:57:24.498Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/photo-1-2026-08-29-18-02-45-860x573-crop-CRGJO1Nj.jpg','/api/media/a4050043-895b-47a1-9495-3d3ebcc10721','/api/media/a4050043-895b-47a1-9495-3d3ebcc10721?variant=thumbnail','المضبوطات',1200,675,'valid','published','archived','valid',41,'f88e46e339c071826fbc3e819b95809907b36c667f9811de88f42e8ef2152e5f','d0056145dc40c94ed8f8b08f1a09eddd1c6866933f0dece5f422bb5c8c91f8f8','محدّث','2026-08-29T16:57:24.498Z','2026-10-07T21:11:37.854Z','','',0,0,'saudi_national','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية السورية محاولة تهريب","السفر والسياحة","سوريا"]','["وزارة الداخلية السورية محاولة تهريب","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:11:37.854Z',200,63,0,'source_content_changed','',NULL,NULL,'body:d1cbbefa3db2480553a03a1b21d4c47f72c2ca14b0b67940f078f8f18fa4b3a7','Wed, 07 Oct 2026 21:11:34 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8b961336-00eb-4528-acaa-d355f142c3f7','news-8b961336-00eb-4528-acaa-d355f142c3f7','«العليمي» يشيد بالدعم الأخوي المتواصل من الأشقاء في المملكة لبرنامج الإصلاحات الحكومية','العليمي يشيد بالدعم الاخوي المتواصل من الاشقاء في المملكه لبرنامج الاصلاحات الحكوميه','أعرب رئيس مجلس القيادة الرئاسي اليمني الدكتور رشاد العليمي عن خالص شكره بالدعم الأخوي السخي والمتواصل من الأشقاء في المملكة ، لبرنامج الإصلاحات الحكومية، وما شمله من إسناد للموازنة العامة، ودعم انتظام صرف مرتبات الموظفين، وتحسين الخدمات الأساسية، وتمويل البرامج والمشاريع التنموية والإنسانية في مختلف القطاعات.','["واعتبر العليمي الشراكة مع المملكة العربية السعودية نموذجاً يحتذى في جعل الدعم رافعة للإصلاحات والاستقرار والتعافي المؤسسي، موجهاً وزارة التخطيط بالبناء على هذا المسار وتعزيز الثقة مع المانحين والشركاء الإقليميين والدوليين، وتشجيعهم على توسيع تدخلاتهم النوعية، بما يسهم في تحسين قدرة الدولة على الوفاء بالتزاماتها الحتمية تجاه المواطنين.","ووفق ما نقلته وكالة \"سبأ\" اليمنية، شدد رئيس مجلس القيادة الرئاسي اليمني على أهمية الانتقال من إدارة الاحتياجات الطارئة إلى التخطيط للتعافي وإعادة الإعمار، وتحديد المشاريع ذات الأولوية، مع التركيز على عناصر صمود المجتمع، وفي مقدمتها التعليم، والصحة، والمياه، والكهرباء، والأمن الغذائي، وسبل العيش، والبنى التحتية الأساسية.","ووجه الرئيس اليمني في هذا السياق بإيلاء اهتمام خاص للمنظمات الدولية والإنسانية التي استقرت في العمل من العاصمة المؤقتة عدن ، وتسهيل مهامها بالتنسيق مع رئاسة الوزراء والسلطات المحلية والجهات المختصة، ومعالجة أي صعوبات إدارية أو إجرائية تواجه أنشطتها، بما يضمن وصول المساعدات إلى مستحقيها في مختلف المحافظات.","كما حث العليمي على إبقاء النازحين والفئات الأكثر تضرراً من الحرب في صدارة أولويات التعاون الدولي، وتحسين الخدمات الأساسية في مناطق الاستضافة، وربط المساعدات الإنسانية ببرامج أكثر استدامة في مجالات التعليم والصحة وفرص العمل وسبل العيش، بالتوازي مع تهيئة الظروف اللازمة للعودة الطوعية والآمنة والكريمة للنازحين في أقرب وقت ممكن. وشدد رئيس مجلس القيادة على أهمية تطوير قاعدة معلومات وطنية للمشاريع والاحتياجات والتمويلات الدولية، بما يساعد الحكومة على تحديد الفجوات، ورفع كفاءة توجيه الموارد، وقياس الأثر الفعلي للتدخلات الانمائية والإنسانية على حياة المواطنين وقدرات مؤسسات الدولة."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/0z42n3s3y','https://ajel.sa/local/0z42n3s3y','https://ajel.sa/local/0z42n3s3y','https://ajel.sa/local/0z42n3s3y','فريق التحرير','','2026-08-29T10:47:00.000Z','Wed, 07 Oct 2026 21:17:53 GMT','2026-08-29T17:02:06.345Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-upg-yo7n.jpg','/api/media/8b961336-00eb-4528-acaa-d355f142c3f7','/api/media/8b961336-00eb-4528-acaa-d355f142c3f7?variant=thumbnail','«العليمي» يشيد بالدعم الأخوي المتواصل من الأشقاء في المملكة لبرنامج الإصلاحات الحكومية',1200,675,'valid','published','archived','valid',52,'71ef589103ac967e2bf2da2e2be1f0a760e65046500cac6d0e697ed15acdd4b5','092b82131e75c15ceb6e73ea217fb2a459fdbfeffd4813ec84843c85c0de3575','محدّث','2026-08-29T17:02:06.345Z','2026-10-07T21:17:56.376Z','','',0,0,'saudi_national','أولوية قصوى',82,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة التخطيط بالبناء على هذا","رئيس مجلس القيادة الرئاسي اليمني","مجلس القيادة الرئاسي اليمني الدكتور","الصحة العامة","التعليم والتدريب","اليمن"]','["وزارة التخطيط بالبناء على هذا","رئيس مجلس القيادة الرئاسي اليمني","مجلس القيادة الرئاسي اليمني الدكتور","الصحة العامة","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:17:56.376Z',200,49,0,'source_content_changed','',NULL,NULL,'body:5fc8e896cc1d37a5284657ad2d87971c745faba2665ab26649756a28ac259234','Wed, 07 Oct 2026 21:17:53 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b649f7c3-922f-49ad-b281-9502cd61b20b','news-b649f7c3-922f-49ad-b281-9502cd61b20b','استشهاد فلسطينيَّين في قصف إسرائيلي استهدف دراجة نارية غرب غزة','استشهاد فلسطينيين في قصف اسرائيلي استهدف دراجه ناريه غرب غزه','استشهد فلسطينيان وأصيب عدد من المواطنين، مساء اليوم، إثر قصف الاحتلال الإسرائيلي دراجةً ناريةً في حي تل الهوا غرب مدينة غزة. وارتفع بذلك إجمالي عدد الشهداء الفلسطينيين جراء الغارات الإسرائيلية على مناطق متفرقة في قطاع غزة إلى 3 شهداء، بينهم مزارع لقي حتفه في قصف منفصل.','["استشهد فلسطينيان وأصيب عدد من المواطنين، مساء اليوم، إثر قصف الاحتلال الإسرائيلي دراجةً ناريةً في حي تل الهوا غرب مدينة غزة.","وارتفع بذلك إجمالي عدد الشهداء الفلسطينيين جراء الغارات الإسرائيلية على مناطق متفرقة في قطاع غزة إلى 3 شهداء، بينهم مزارع لقي حتفه في قصف منفصل.","وفي السياق ذاته، تواصل القصف المدفعي وإطلاق النار من آليات الاحتلال على المناطق الشمالية والشرقية من القطاع، في ظل استمرار الخروقات الإسرائيلية لاتفاق وقف إطلاق النار المبرم في غزة."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/zsjggqb','https://sabq.org/article/zsjggqb','','https://sabq.org/article/zsjggqb','صحيفة سبق','المنطقة الشرقية','2026-08-29T10:56:00.000Z','2026-08-29T13:56:00.000Z','2026-08-29T17:07:35.452Z','https://media.sabq.org/news/2026/08/0f40a45f-2865-4f23-b8e1-5d70aced340c/w714.webp','/api/media/b649f7c3-922f-49ad-b281-9502cd61b20b','/api/media/b649f7c3-922f-49ad-b281-9502cd61b20b?variant=thumbnail','استشهاد فلسطينيَّين في قصف إسرائيلي استهدف دراجة نارية غرب غزة',714,430,'valid','published','archived','valid',41,'4beb45ed821e8722a0d3886971f58dc07971e549023d9042513b7e4dcc83e0c2','460f0ef57494a4fe6fc208f6451ef9803aa67fe90524efa39c384171118e8c87','محدّث','2026-08-29T17:07:35.452Z','2026-10-07T21:18:50.934Z','','',0,0,'saudi_region','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["غزة","فلسطين"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:18:50.934Z',200,64,0,'source_article_available','',NULL,NULL,'body:8506f90a7cb3e71591919225481893e70f7470a95af9caf1657a048c2759e759','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d82d2f4f-a641-41b4-a3f1-229e6942bf9a','news-d82d2f4f-a641-41b4-a3f1-229e6942bf9a','«الصحة العامة في خطر».. منظمات بريطانية تطالب بفرض «حظر عاجل» على واردات اللحوم البرازيلية','الصحه العامه في خطر منظمات بريطانيه تطالب بفرض حظر عاجل علي واردات اللحوم البرازيليه','طالبت منظمات الزراعة البريطانية وخبراء صحة الحيوان بفرض «حظر عاجل» على واردات اللحوم البرازيلية، وسط مخاوف متزايدة بشأن سلامة هذه الواردات، ووجّه الاتحاد الوطني للمزارعين في إنجلترا ونظراؤه في الإدارات اللامركزية رسالة إلى الحكومة، محذرا من أن «الصحة العامة باتت في خطر».','["وذكرت صحيفة «الجارديان»، اليوم السبت، أن «هذه الهيئات تخشى أن تُربى الأبقار والدواجن في البرازيل باستخدام روتيني للمضادات الحيوية، بعدما فشلت البلاد في إثبات التزامها بقواعد الاتحاد الأوروبي رغم تشديد بعض اللوائح».","يأتي هذا في الزقت الذي يستعد فيه الاتحاد الأوروبي الأسبوع المقبل لحظر واردات لحوم الأبقار والدجاج من البرازيل، لكن خروج بريطانيا من الاتحاد يمنحها حرية عدم الالتزام بالقرار.ط، وقد ارتفعت واردات المملكة المتحدة من البرازيل منذ بريكست من نحو 3 مليارات جنيه في 2021 إلى 5 مليارات في 2025، وتشكل اللحوم جزءًا كبيرًا منها، إذ مثّلت البرازيل في 2024 نحو ثُمن واردات الدجاج البريطانية.","ويخشى المزارعون البريطانيون، الذين يعانون أصلًا من انخفاض أسعار اللحوم وارتفاع تكاليف الأعلاف والطاقة، أن يؤدي إغلاق السوق الأوروبية أمام اللحوم البرازيلية إلى تدفق المزيد منها نحو المملكة المتحدة.","وكشف تحقيق أيرلندي العام الماضي أن المزارعين البرازيليين يحصلون بسهولة على مضادات حيوية تُعد «بالغة الأهمية» في الطب البشري، دون وصفة بيطرية، مع ضعف تطبيق قواعد التتبع.","وتؤكد منظمات الصحة أن «مقاومة المضادات الحيوية أزمة عالمية تتسبب في أكثر من مليون وفاة سنويًا»، محذّرة من أن «مسببات الأمراض المقاومة يمكن أن تنتقل عبر الغذاء. وتواجه الحكومة ضغوطًا إضافية بعد تفشي السالمونيلا في بيض مستورد أدى إلى وفاة شخص وإصابة أكثر من 200»."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/xozoj3sj6','https://ajel.sa/misc/xozoj3sj6','https://ajel.sa/misc/xozoj3sj6','https://ajel.sa/misc/xozoj3sj6','فريق التحرير','','2026-08-29T11:03:00.000Z','Wed, 07 Oct 2026 21:20:45 GMT','2026-08-29T17:19:50.874Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/1000199467-crop-EIhG04o-.jpg','/api/media/d82d2f4f-a641-41b4-a3f1-229e6942bf9a','/api/media/d82d2f4f-a641-41b4-a3f1-229e6942bf9a?variant=thumbnail','«الصحة العامة في خطر».. منظمات بريطانية تطالب بفرض «حظر عاجل» على واردات اللحوم البرازيلية',1200,675,'valid','published','archived','valid',40,'698ac6f241e03d1d1a530f84a888bf0eeaa0b1f1bd2e8f898246628e96e1eda3','ae6b68ca0494b76ae7f9841c32ff206f3bfa91cfd3dc5e90503de58daa7966f7','محدّث','2026-08-29T17:19:50.874Z','2026-10-07T21:20:47.783Z','','',0,0,'saudi_national','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الطاقة والنفط"]','["الصحة العامة","الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"الطاقة والصناعة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T21:20:47.783Z',200,58,0,'source_content_changed','',NULL,NULL,'body:c4ccf85bfcc8a5885adb2e0ebad3e1525ab1b41595524f53e2344818b14a21c1','Wed, 07 Oct 2026 21:20:45 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5c05bd1b-eab1-429a-b1c4-d84d64c86acc','news-5c05bd1b-eab1-429a-b1c4-d84d64c86acc','أتالانتا يُعلن عودة كيسيه القادم من الأهلي السعودي بعد 9 سنوات','اتالانتا يعلن عوده كيسيه القادم من الاهلي السعودي بعد 9 سنوات','أعلن نادي أتالانتا الإيطالي عودة لاعب خط الوسط الإيفواري فرانك كيسيه إلى صفوف الفريق، قادماً من نادي الأهلي السعودي، لينضم مجدداً إلى النادي الذي ارتدى قميصه قبل تسع سنوات.','["وأوضح النادي عبر موقعه الرسمي أن نجم خط وسط منتخب كوت ديفوار يعود بعد مسيرة حافلة بالألقاب والإنجازات، إذ توّج خلال السنوات الماضية بلقب الدوري الإيطالي مع نادي ميلان، ولقب الدوري الإسباني وكأس السوبر الإسباني مع برشلونة، فضلاً عن كأس السوبر السعودي ولقبَين في دوري أبطال آسيا للنخبة مع الأهلي السعودي."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/t9zfez2','https://sabq.org/article/t9zfez2','','https://sabq.org/article/t9zfez2','صحيفة سبق','','2026-08-29T11:14:00.000Z','2026-08-29T14:14:00.000Z','2026-08-29T17:19:51.461Z','https://media.sabq.org/news/2026/08/1b0c7560-e5fd-4605-a1c4-ec9b148ceb47/w1600.webp','/api/media/5c05bd1b-eab1-429a-b1c4-d84d64c86acc','/api/media/5c05bd1b-eab1-429a-b1c4-d84d64c86acc?variant=thumbnail','أتالانتا يُعلن عودة كيسيه القادم من الأهلي السعودي بعد 9 سنوات',1600,1280,'valid','published','archived','valid',59,'3eff0e2f662f76c6dab215d06e920a2ffd02a92e000b722084ff54ee54c1f7d5','54a382a0e8a7b4d6472950bbd6d6627d5c3c105292d87e48469884e74a3cd8c2','محدّث','2026-08-29T17:19:51.461Z','2026-10-07T21:20:37.428Z','','',0,0,'international','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T21:20:37.428Z',200,59,0,'source_article_available','',NULL,NULL,'body:68505e442e99d3964526d489d6ecbaa029ffd8b74fce51e5b9410d31d0b02ae6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a1422a7c-1c5a-4919-92b0-263db955893c','news-a1422a7c-1c5a-4919-92b0-263db955893c','الأونروا: لا فرصة لدينا للقيام بعملنا في القدس الشرقية','الاونروا لا فرصه لدينا للقيام بعملنا في القدس الشرقيه','وأكدت الأونروا أن إغلاق المنشأة حرمها من فرصة القيام بعملها في القدس الشرقية، في وقت شددت فيه على ضرورة احترام الحصانة الدبلوماسية لمنشآت الأمم المتحدة.','["أكدت وكالة الأمم المتحدة لإغاثة وتشغيل اللاجئين الفلسطينيين «الأونروا» أنه «لا فرصة لدينا للقيام بعملنا في القدس الشرقية»، مطالبة دولة الاحتلال الإسرائيلي باحترام الحصانة الدبلوماسية لمنشآت الأمم المتحدة، وذلك بعد سيطرة قوات الجيش والشرطة الإسرائيلية على معهد قلنديا للتعليم المهني المجاني للاجئين الفلسطينيين.","وقالت الأونروا، في تصريحات لقناة «الحدث»، إن دولة الاحتلال الإسرائيلي أغلقت منشأة لا بديل لها لتدريب اللاجئين الفلسطينيين، مشددة على ضرورة احترام الحصانة الدبلوماسية لمنشآت الأمم المتحدة.","وجاءت تصريحات الوكالة عقب سيطرة قوات الجيش والشرطة الإسرائيلية، يوم الثلاثاء، على معهد قلنديا، وهو معهد للتعليم المهني المجاني للاجئين الفلسطينيين في مخيم قلنديا شمال مدينة القدس."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/tsv088w18','https://ajel.sa/international/tsv088w18','https://ajel.sa/international/tsv088w18','https://ajel.sa/international/tsv088w18','فريق التحرير','المنطقة الشرقية','2026-08-29T11:13:00.000Z','Wed, 07 Oct 2026 19:34:51 GMT','2026-08-29T17:37:51.131Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%A3%D9%88%D9%86%D8%B1%D9%88%D8%A7-dsgPc8sc.jpg','/api/media/a1422a7c-1c5a-4919-92b0-263db955893c','/api/media/a1422a7c-1c5a-4919-92b0-263db955893c?variant=thumbnail','معهد قلنديا للتعليم المهني المجاني للاجئين الفلسطينيين',1200,675,'valid','published','archived','valid',41,'376d49f21102d10524fc746bde61c16522e7c741c0b697aca5d58123c65c3c52','02e19292d4a8f961971ba4d7219ee105fd218b1553f2eb3ca66d01bf2cd773ef','محدّث','2026-08-29T17:37:51.131Z','2026-10-07T20:24:32.254Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الأمم المتحدة لإغاثة وتشغيل اللاجئين","التعليم والتدريب","السياسة والعلاقات الدولية","فلسطين"]','["الأمم المتحدة لإغاثة وتشغيل اللاجئين","التعليم والتدريب","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:34:53.483Z',200,50,0,'source_content_changed','',NULL,NULL,'body:627280c7721cb8ed4f0910094f3e3adbbc1fe0b6049b7ab13f0fa808c2ac5437','Wed, 07 Oct 2026 19:34:51 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3a795c4c-0f9b-4e1c-baa1-4ee6dd1396de','news-3a795c4c-0f9b-4e1c-baa1-4ee6dd1396de','1600 مدرسة بالطائف جاهزة لاستقبال 260 ألف طالب وطالبة مع انطلاق العام الدراسي 1448 هـ','1600 مدرسه بالطائف جاهزه لاستقبال 260 الف طالب وطالبه مع انطلاق العام الدراسي 1448 هـ','أعلنت الإدارة العامة للتعليم بالطائف اكتمال جاهزية 1600 مدرسة لاستقبال أكثر من 260 ألف طالب وطالبة، مع انطلاق العام الدراسي الجديد 1448هـ، وذلك بعد استكمال أعمال التهيئة والتجهيز والمتابعة الميدانية للمدارس والمرافق التعليمية كافة.','["وتأتي هذه الجاهزية في إطار استعدادات الإدارة لضمان انتظام الدراسة منذ يومها الأول، من خلال استكمال المتطلبات التعليمية والتنظيمية، ومتابعة جاهزية المباني والتجهيزات، وتهيئة الكوادر التعليمية والإدارية.","وأكد المدير العام للتعليم بالطائف الدكتور سعيد بن عبدالله الغامدي، أهمية المتابعة الميدانية وتكامل الجهود بين الإدارات التعليمية والقيادات المدرسية، لضمان جاهزية المدارس وتوفير بيئة تعليمية آمنة للطلبة والطالبات.","وشدد الغامدي على دور مديري ومديرات المدارس في قيادة العمل الميداني وتنظيم العملية التعليمية، وتعزيز الشراكة مع الأسرة بما يدعم رحلة الطلبة التعليمية ويرفع مستوى نواتج التعلم.","وتواصل الإدارة العامة للتعليم بالطائف متابعتها الميدانية للمدارس مع بدء العام الدراسي، للتأكد من استمرارية الجاهزية وانتظام العملية التعليمية.","وفي سياق الاستعداد للعام الدراسي، نظّمت الإدارة مهرجان «العودة للدراسة» بفعاليات تفاعلية شارك فيها الطلبة والمعلمون وأولياء الأمور، ضمن خطتها الاتصالية للعودة إلى الدراسة تحت شعار «نكتب قصة».","وتجدر الإشارة إلى أن الاصطفاف الصباحي في مدارس التعليم بالطائف يبدأ عند الساعة 6:45 صباحاً، فيما تنطلق الحصة الأولى عند الساعة 7:00 صباحاً."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/avb9EFL','https://sabq.org/article/avb9EFL','','https://sabq.org/article/avb9EFL','فهد العتيبي','','2026-08-29T11:45:00.000Z','2026-08-29T14:45:00.000Z','2026-08-29T17:46:52.500Z','https://media.sabq.org/news/2026/08/abbb699e-fe37-4531-abc1-ee72b235781f/w1280.webp','/api/media/3a795c4c-0f9b-4e1c-baa1-4ee6dd1396de','/api/media/3a795c4c-0f9b-4e1c-baa1-4ee6dd1396de?variant=thumbnail','1600 مدرسة بالطائف جاهزة لاستقبال 260 ألف طالب وطالبة مع انطلاق العام الدراسي 1448 هـ',1280,720,'valid','published','archived','valid',41,'ba742d174d7b63e46ac5e43bba795a222d066a8d271b6c5a2d36bbd84a1a0cec','044e91b97e5d0e5cd1d3bb8edc1cdde40e74d5fa6e40faaa80c03cb86cd2559e','محدّث','2026-08-29T17:46:52.500Z','2026-10-07T20:24:32.258Z','','',0,0,'international','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:34:40.559Z',200,59,0,'source_article_available','',NULL,NULL,'body:aa4ba2f0c727477a8c44b1bbadf930b3e058bb50da23f590f94ec882e3fed27b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d716ca28-a69b-4fc1-aa16-980f9f7ed5cc','news-d716ca28-a69b-4fc1-aa16-980f9f7ed5cc','إحباط محاولة تهريب دولية لـ138 كغ من مادة الحشيش المخدّر و382 ألف حبة مخدّرة','احباط محاوله تهريب دوليه لـ138 كغ من ماده الحشيش المخدر و382 الف حبه مخدره','تمكنت إدارة مكافحة المخدرات في الجمهورية العربية السورية من إحباط محاولة تهريب دولية لشحنة من المواد المخدّرة، إثر عملية أمنية دقيقة نُفذت في الريف الشرقي لمحافظة السويداء. وأسفرت العملية عن ضبط ومصادرة 138 كغ من مادة الحشيش المخدّر و382 ألف حبة مخدّرة، كانت بحوزة مجموعات خارجة عن القانون في المحافظة.','["تمكنت إدارة مكافحة المخدرات في الجمهورية العربية السورية من إحباط محاولة تهريب دولية لشحنة من المواد المخدّرة، إثر عملية أمنية دقيقة نُفذت في الريف الشرقي لمحافظة السويداء.","وأسفرت العملية عن ضبط ومصادرة 138 كغ من مادة الحشيش المخدّر و382 ألف حبة مخدّرة، كانت بحوزة مجموعات خارجة عن القانون في المحافظة.","وتواصل الجهات المختصة تحرياتها ومتابعتها الأمنية لكشف وملاحقة المتورطين في محاولة التهريب، تمهيداً لاتخاذ الإجراءات القانونية اللازمة بحقهم."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/mz3gyr7','https://sabq.org/article/mz3gyr7','','https://sabq.org/article/mz3gyr7','منصور الشلاقي','','2026-08-29T11:44:00.000Z','2026-08-29T14:44:00.000Z','2026-08-29T17:46:53.700Z','https://media.sabq.org/news/2026/08/0ada30eb-134b-49a8-be63-27e9c3cf3e8c/w1280.webp','/api/media/d716ca28-a69b-4fc1-aa16-980f9f7ed5cc','/api/media/d716ca28-a69b-4fc1-aa16-980f9f7ed5cc?variant=thumbnail','إحباط محاولة تهريب دولية لـ138 كغ من مادة الحشيش المخدّر و382 ألف حبة مخدّرة',1280,853,'valid','published','archived','valid',51,'57fad987b5379002737558cd1b7519989441c1ef38d9eb143293d5ae3d31e2bc','196651c5d5c726c17e6666ddd27d83a93975473d3187d8b2c6705d81b972f21b','محدّث','2026-08-29T17:46:53.700Z','2026-10-07T19:34:46.083Z','','',0,0,'international','عادي',58,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة"]','["السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:34:46.083Z',200,55,0,'source_article_available','',NULL,NULL,'body:0b1fcc5231876c91dea68e60f562077f0fe822834553ab0a3120bbfc3a827d77','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('da5c374f-56b1-4976-8583-b3ca7185aac9','news-da5c374f-56b1-4976-8583-b3ca7185aac9','«الذكاء الاصطناعي التوليدي» يعزز جاهزية خريجات جامعة الباحة لسوق العمل','الذكاء الاصطناعي التوليدي يعزز جاهزيه خريجات جامعه الباحه لسوق العمل','وتقام برعاية من وزارة الاتصالات وتقنية المعلومات ، ضمن برنامج صيفك ذكي 2026، وبالتزامن مع عام الذكاء الاصطناعي، بما يسهم في تطوير مهارات الخريجات الرقمية ورفع جاهزيتهن لمواكبة متطلبات سوق العمل المتجددة.','["في إطار جهودها لتنمية المهارات الرقمية ورفع جاهزية الخريجات لمتطلبات سوق العمل، استضافت جامعة الباحة ، ممثلةً بكلية الحاسبات والمعلومات ووكالة شؤون دعم الخريجين بعمادة القبول والتسجيل، الدورة التدريبية «الذكاء الاصطناعي التوليدي وهندسة الأوامر».","ووفق بيان الجامعة عبر حسابها الرسمي على منصة \"إكس\"، تأتي الدورة ضمن سلسلة من الدورات التدريبية المتخصصة في مجالي البيانات والذكاء الاصطناعي، والموجهة إلى خريجات الجامعة من مختلف التخصصات."]','الذكاء الاصطناعي','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/2197dqdib','https://ajel.sa/local/2197dqdib','https://ajel.sa/local/2197dqdib','https://ajel.sa/local/2197dqdib','فريق التحرير','عسير','2026-08-29T11:41:00.000Z','Wed, 07 Oct 2026 19:53:39 GMT','2026-08-29T17:55:51.079Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-PWg_wwfD.jpg','/api/media/da5c374f-56b1-4976-8583-b3ca7185aac9','/api/media/da5c374f-56b1-4976-8583-b3ca7185aac9?variant=thumbnail','«الذكاء الاصطناعي التوليدي» يعزز جاهزية خريجات جامعة الباحة لسوق العمل',1200,675,'valid','published','archived','valid',99,'168e99b63ea7168ec76ee04ddf40bf4b32fe3d5700159055c9d016bb48727667','f3e1b03e5292998589a23d3638fd0a777bfcf831282dbd3ca11f0c1a6f0b3800','محدّث','2026-08-29T17:55:51.079Z','2026-10-07T20:24:32.264Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة الباحة لسوق العمل صحيفة","وزارة الاتصالات وتقنية المعلومات ضمن","الثقافة والفنون","التعليم والتدريب","التقنية والتحول الرقمي","الباحة"]','["جامعة الباحة لسوق العمل صحيفة","وزارة الاتصالات وتقنية المعلومات ضمن","الثقافة والفنون","التعليم والتدريب","التقنية والتحول الرقمي"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:53:40.878Z',200,45,0,'source_content_changed','',NULL,NULL,'body:694ab5301f1634b4f7cd5564d1577c97668e5d181bd595fc079cbb59048d42ca','Wed, 07 Oct 2026 19:53:39 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('df415f95-cf9c-45b8-984e-5ab3818c8ac9','news-df415f95-cf9c-45b8-984e-5ab3818c8ac9','أمانة جدة تتلف أكثر من 1.3 طن ملابس مستعملة وتزيل 270 بسطة عشوائية بالخمرة','امانه جده تتلف اكثر من 1 3 طن ملابس مستعمله وتزيل 270 بسطه عشوائيه بالخمره','وأوضحت وكالة البلديات الفرعية بالأمانة أن الفرق الميدانية أزالت وأتلفت 270 بسطة عشوائية بعد استكمال الإجراءات المتبعة في الموقع، بالتزامن مع استمرار أعمال فرق الرقابة لحصر المخالفات ومعالجة آثار النشاط العشوائي.','["أسفرت حملة ميدانية نفذتها أمانة محافظة جدة في حي الخمرة عن إتلاف أكثر من 1.3 طن من الملابس المستعملة التي كانت تُعرض وتُتداول بشكل عشوائي، وذلك ضمن جهود معالجة مواقع البيع غير النظامية ومتابعة الممارسات المخالفة داخل الأحياء.","شملت الحملة ضبط مخالفين واتخاذ الإجراءات النظامية بحقهم من قبل الجهات المعنية، في إطار متابعة الأنشطة غير النظامية المرتبطة بمواقع البيع العشوائي والحد من عودتها أو انتقالها إلى مواقع أخرى داخل النطاق.","وبيّنت الوكالة أن الفرق الميدانية رحّلت 11 طنًا من المضبوطات إلى المردم، كما امتدت الأعمال إلى تنظيف الموقع وإزالة المخلفات وإعادة تهيئته عقب انتهاء عمليات الضبط والإزالة.","وتواصل أمانة محافظة جدة حملاتها الرقابية والميدانية لمتابعة مواقع البيع العشوائي والأنشطة المخالفة في الأحياء، واتخاذ الإجراءات النظامية حيالها، بما يعزز المشهد الحضري ويرفع مستوى الامتثال في المحافظة."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/ldc1pewh9','https://ajel.sa/local/ldc1pewh9','https://ajel.sa/local/ldc1pewh9','https://ajel.sa/local/ldc1pewh9','فريق التحرير','مكة المكرمة','2026-08-29T11:37:00.000Z','Wed, 07 Oct 2026 19:53:13 GMT','2026-08-29T17:55:51.607Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A3%D9%85%D8%A7%D9%86%D8%A9-%D8%AC%D8%AF%D8%A9-TamtCrow.jpg','/api/media/df415f95-cf9c-45b8-984e-5ab3818c8ac9','/api/media/df415f95-cf9c-45b8-984e-5ab3818c8ac9?variant=thumbnail','أمانة جدة تتلف أكثر من 1.3 طن ملابس مستعملة وتزيل 270 بسطة عشوائية بالخمرة',1200,675,'valid','published','archived','valid',41,'1633cd6feb31ad3005307a990b8c594a6ea40d7a066d8220f45bfe2d7fe41afd','1ba9ad288edeb724ebf372ab53874c7c8f06741939cfb295857ffc648c109170','محدّث','2026-08-29T17:55:51.607Z','2026-10-07T20:24:32.267Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","جدة"]','["السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:53:15.105Z',200,46,0,'source_content_changed','',NULL,NULL,'body:0b2fc36acaa3daec182ef8ae85f352f22c7b3f2b3d2bf2017a30aa529575e14a','Wed, 07 Oct 2026 19:53:13 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8b314092-d135-4f9b-a2f1-f5b1950e6997','news-8b314092-d135-4f9b-a2f1-f5b1950e6997','هطول أمطار خفيفة إلى متوسطة على أجزاء من المدينة المنورة','هطول امطار خفيفه الي متوسطه علي اجزاء من المدينه المنوره','شهدت منطقة المدينة المنورة اليوم السبت هطول أمطار تراوحت بين الخفيفة والمتوسطة على أجزاء متفرقة من المدينة ومحافظاتها. وأشارت مصادر إلى أن السماء لا تزال ملبدة بالغيوم، مع استمرار توافر الفرصة لهطول مزيد من الأمطار خلال الساعات المقبلة.','["شهدت منطقة المدينة المنورة اليوم السبت هطول أمطار تراوحت بين الخفيفة والمتوسطة على أجزاء متفرقة من المدينة ومحافظاتها.","وأشارت مصادر إلى أن السماء لا تزال ملبدة بالغيوم، مع استمرار توافر الفرصة لهطول مزيد من الأمطار خلال الساعات المقبلة.","وفي السياق ذاته، شملت الأمطار عدة مواقع داخل المدينة المنورة والمناطق المحيطة، ما أدى إلى تلطيف الأجواء وتحسن حالة الطقس."]','البيئة والمناخ','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/gq9wpebq2','https://ajel.sa/local/gq9wpebq2','https://ajel.sa/local/gq9wpebq2','https://ajel.sa/local/gq9wpebq2','فريق التحرير','المدينة المنورة','2026-08-29T11:40:00.000Z','Wed, 07 Oct 2026 19:53:12 GMT','2026-08-29T17:55:51.790Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-08/source-oZ_ZnCCc.jpg','/api/media/8b314092-d135-4f9b-a2f1-f5b1950e6997','/api/media/8b314092-d135-4f9b-a2f1-f5b1950e6997?variant=thumbnail','هطول أمطار خفيفة إلى متوسطة على أجزاء من المدينة المنورة',1200,675,'valid','published','archived','valid',99,'2bddf28bf259536200cb6ecccc535007e0eefbc58682825755e90ad140a6ef18','75acee0e3f7e9a43df7cdd846e271389984e23fec2b93fd0822926bf63c98890','محدّث','2026-08-29T17:55:51.790Z','2026-10-07T19:53:14.144Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","المدينة المنورة"]','["الطقس والمناخ","المدينة المنورة"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:53:14.144Z',200,48,0,'source_content_changed','',NULL,NULL,'body:1da984d4acd009e719307745299b0041b0ce71515a99a6999ef696d5f33cebe6','Wed, 07 Oct 2026 19:53:12 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a5e807d2-acca-4901-b0ff-f35c4f52a82d','news-a5e807d2-acca-4901-b0ff-f35c4f52a82d','«فارس» يحسم الجدل: ظهور خيار «المصافحة الذهبية» لا يعني حق التقديم لجميع الموظفين','فارس يحسم الجدل ظهور خيار المصافحه الذهبيه لا يعني حق التقديم لجميع الموظفين','وأوضح الموقع أن الموظفين المستوفين للشروط يُتواصل معهم مباشرة لاستكمال الإجراءات، مشدداً على أن ظهور الخيار في حساب الموظف لا يُعد بحد ذاته دليلاً على الاستحقاق أو إتاحة التقديم.','["حسم موقع «فارس» التعليمي الجدل المثار حول ظهور خيار «المصافحة الذهبية» في نظام «فارس»، مؤكداً أن هذا الخيار مخصص فقط للموظفين الذين تنطبق عليهم الفئات والمعايير المعتمدة، وأن ظهوره في النظام لا يعني أن جميع الموظفين بإمكانهم التقديم.","وجاء في التنبيه التوضيحي المضاف في نظام «فارس»: «خيار المصافحة الذهبية مخصص للموظفين الذين تنطبق عليهم الفئات والمعايير المعتمدة، ويتم التواصل معهم مباشرة لاستكمال الإجراءات، وظهور الخيار في النظام لا يعني إتاحة التقديم لجميع الموظفين».","وبذلك، فإن ظهور أيقونة «المصافحة الذهبية» ضمن خدمات النظام لا يعني أن جميع منسوبي التعليم يحق لهم التقدم عليها، كما لا يُعد موافقةً أو قبولاً أو إثباتاً لاستحقاق الحافز المالي، إذ يبقى الفيصل انطباقَ الفئة والمعايير المعتمدة، ثم التواصل مع الموظف المستفيد لاستكمال الإجراءات النظامية.","وكانت وزارة التعليم قد أتاحت خيار «المصافحة الذهبية» للمعلمين والمعلمات عبر نظام «فارس»، بعد إدراجه ضمن مسار طلب الاستقالة، ما أتاح لمنسوبي الوزارة الوصول إليه من خلال حساباتهم في النظام.","ويظهر الخيار عند الدخول إلى الخدمة الذاتية، ثم اختيار «الاستقالة»، فـ«طلب الاستقالة»، ثم الضغط على خانة «Reason Type»، ليظهر خيار «المصافحة الذهبية» ضمن أسباب طلب الاستقالة المتاحة.","وفي وقت سابق، أوضح المستشار في الموارد البشرية الدكتور خليل الذيابي لـ«سبق» أن «المصافحة الذهبية» لا تُعد تقاعداً مبكراً، ولا يترتب عليها استمرار صرف راتب شهري بعد انتهاء الخدمة، مبيناً أنها استقالة اختيارية مقابل حافز مالي مقطوع وفق الضوابط والمعايير المعتمدة."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/GGoUAsp','https://sabq.org/article/GGoUAsp','','https://sabq.org/article/GGoUAsp','عبدالحكيم شار','','2026-08-29T11:55:00.000Z','2026-08-29T14:55:00.000Z','2026-08-29T17:55:52.043Z','https://media.sabq.org/news/2026/08/1e978e00-19d2-4b46-9412-566cfb96debb/w716.webp','/api/media/a5e807d2-acca-4901-b0ff-f35c4f52a82d','/api/media/a5e807d2-acca-4901-b0ff-f35c4f52a82d?variant=thumbnail','«فارس» يحسم الجدل: ظهور خيار «المصافحة الذهبية» لا يعني حق التقديم لجميع الموظفين',716,508,'valid','published','archived','valid',43,'4af13204ee078ab014c9fd820980f60ef5610cb4f3ce1247b5cb430325bfaf91','824f67b62c8f416c8032a436c8bc75d1325f8f33f22dbaf9be7cee7cdcd6eaee','محدّث','2026-08-29T17:55:52.043Z','2026-10-07T20:24:32.273Z','','',0,0,'international','عادي',52,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة التعليم قد أتاحت خيار","التعليم والتدريب","الاقتصاد والأسواق"]','["وزارة التعليم قد أتاحت خيار","التعليم والتدريب","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:53:02.249Z',200,48,0,'source_article_available','',NULL,NULL,'body:a90382c1440543692be6ad95598bfb9703e3c6ae5ac529e66acc06e44475de1f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1a0b4850-2c05-4054-a0d5-ebee93dfada4','news-1a0b4850-2c05-4054-a0d5-ebee93dfada4','واشنطن تبلغ أربيل بعدم تمديد اتفاق مساعدات البيشمركة','واشنطن تبلغ اربيل بعدم تمديد اتفاق مساعدات البيشمركه','وقالت المصادر إن اتفاق تقديم المساعدات إلى البيشمركة في إقليم كردستان العراق سينتهي في موعده دون تمديد، مشيرة في الوقت نفسه إلى أن عدم تجديد مذكرة التفاهم بين أربيل و واشنطن لا يعني نهاية التعاون بين الجانبين.','["أبلغت وزارة الدفاع الأمريكية قادة إقليم كردستان العراق أن الإدارة لا تخطط لتجديد مذكرة التفاهم الخاصة بتقديم المساعدات الأمنية لقوات البيشمركة، بحسب مصادر أمريكية تحدثت لقناة «الحدث»، في وقت ينتهي فيه الاتفاق في 30 سبتمبر المقبل.","وبحسب المصادر، ستصبح أي مساعدات أمريكية للعراق مرتبطة بإنجازات ومهمات محددة، بما يشير إلى تغيير في إطار تقديم الدعم بعد انتهاء الاتفاق الحالي.","وجاء إبلاغ قادة الإقليم خلال اجتماعات عُقدت مؤخرًا مع مسؤولين أمريكيين، فيما تتزامن نهاية مذكرة التفاهم مع موعد مقرر لانسحاب الولايات المتحدة ودول أخرى لآخر قواتها المتبقية من العراق في 30 سبتمبر.","ويضع انتهاء الاتفاق قوات البيشمركة أمام مرحلة جديدة في العلاقة الأمنية مع واشنطن، بعد أن قاتلت إلى جانب قوات التحالف الدولي خلال الحملة العسكرية ضد تنظيم داعش، التي استهدفت إنهاء سيطرة التنظيم على أجزاء من العراق و سوريا .","ومع الانسحاب المقرر، تنتهي رسميًا الحملة العسكرية الدولية ضد تنظيم داعش، وفق المعطيات الواردة، فيما من المقرر إغلاق القاعدة العسكرية الأمريكية الوحيدة المتبقية في العراق، والواقعة في العاصمة الكردية أربيل، الشهر المقبل بعد مغادرة قوات التحالف."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/08v84iezb','https://ajel.sa/international/08v84iezb','https://ajel.sa/international/08v84iezb','https://ajel.sa/international/08v84iezb','فريق التحرير','المدينة المنورة','2026-08-29T11:34:00.000Z','Wed, 07 Oct 2026 19:53:44 GMT','2026-08-29T17:55:53.381Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-atL20HFp.jpg','/api/media/1a0b4850-2c05-4054-a0d5-ebee93dfada4','/api/media/1a0b4850-2c05-4054-a0d5-ebee93dfada4?variant=thumbnail','البيشمركة',1200,675,'valid','published','archived','valid',41,'22de3565b5fcf602b00a53f6fcb41006889e9faad925b1e84a47d7d80e265c42','324272f8c4df9a5a37e81f2a87fab81021d54e71dde9deb663b95d8c987b8841','محدّث','2026-08-29T17:55:53.381Z','2026-10-07T20:24:32.276Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الدفاع الأمريكية قادة إقليم","سوريا","العراق","الولايات المتحدة"]','["وزارة الدفاع الأمريكية قادة إقليم","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:53:45.926Z',200,47,0,'source_content_changed','',NULL,NULL,'body:04c009617a944c475039a59ce70dd644b138e0d40d96775b6922ffe47436bb0d','Wed, 07 Oct 2026 19:53:44 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('75207d3b-fb16-432f-9e80-10f63097ba26','news-75207d3b-fb16-432f-9e80-10f63097ba26','جامعة نجران تحقق المركز الأول في مسابقة أبحاث الطلاب الدولية 2025','جامعه نجران تحقق المركز الاول في مسابقه ابحاث الطلاب الدوليه 2025','حققت جامعة نجران، ممثَّلةً بكلية الهندسة، المركز الأول في مسابقة أبحاث الطلاب الدولية 2025، التي أُقيمت ضمن أعمال المؤتمر الدولي الثاني حول المستقبل المرن، الذي استضافته جامعة جوس في نيجيريا.','["وجاء الفوز من خلال مشروع بحثي بعنوان «إمكانية تحويل مسجد الملك فهد بنجران إلى مسجد أخضر ومستدام»، إذ ناقش الطلاب توظيف مبادئ العمارة الخضراء والاستدامة في تطوير المسجد ورفع كفاءة موارده.","ويعكس هذا الإنجاز قدرة طلبة الجامعة على تقديم حلول بحثية مبتكرة مرتبطة بالبيئة المحلية، ومنسجمة مع التوجهات العالمية في مجال العمارة المستدامة ورؤية المملكة 2030 نحو الاستدامة البيئية."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/sulebu2','https://sabq.org/article/sulebu2','','https://sabq.org/article/sulebu2','صحيفة سبق','نجران','2026-08-29T11:46:00.000Z','2026-08-29T14:46:00.000Z','2026-08-29T17:55:53.485Z','https://media.sabq.org/news/2026/08/e5a9b083-9c2e-4f4c-824e-f1ca71a0735d/w1000.webp','/api/media/75207d3b-fb16-432f-9e80-10f63097ba26','/api/media/75207d3b-fb16-432f-9e80-10f63097ba26?variant=thumbnail','جامعة نجران تحقق المركز الأول في مسابقة أبحاث الطلاب الدولية 2025',1000,666,'valid','published','archived','valid',46,'27b85269e798c82fe7543ab2dd253828fffa8090c6cb6ad069e42a7c0181eb91','27510d16865650707618ea2a44796564c7981b3ba4225260a400acc7e017ba7a','محدّث','2026-08-29T17:55:53.485Z','2026-10-07T20:24:32.279Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة نجران تحقق المركز الأول","التعليم والتدريب","نجران"]','["جامعة نجران تحقق المركز الأول","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:53:09.739Z',200,49,0,'source_article_available','',NULL,NULL,'body:46080fbbdc2ba02c0c992d3d269faa20829b3bdafe3cec5f27e1533e7ba7449b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('830839d0-412f-4e7a-a5d7-1039ed3bad23','news-830839d0-412f-4e7a-a5d7-1039ed3bad23','استعدادا للعام الدراسي.. «حافلات مكة» تصدر دليلاً يوضح المسارات والمحطات القريبة من المدارس','استعدادا للعام الدراسي حافلات مكه تصدر دليلا يوضح المسارات والمحطات القريبه من المدارس','تحت شعار "كيف تصل إلى مدرستك"؛ استعدت "حافلات مكة" لعودة الطلاب والطالبات للمدارس في مكة المكرمة، بإصدار دليل إرشادي يتضمن معلومات عن المدارس الواقعة بالقرب من مسارات ومحطات شبكة حافلات مكة، بهدف مساعدة الطلاب وأولياء الأمور على معرفة خيارات التنقل المتاحة مع بداية العام الدراسي.','["ووفق بيان الهيئة الملكية لمدينة مكة المكرمة والمشاعر المقدسة عبر حسابها على منصة \"إكس\"، أوضح الدليل آلية الوصول إلى المدارس باستخدام شبكة الحافلات، من خلال البحث عن اسم المدرسة، والتعرف على رقم المسار ولونه، وتحديد أقرب محطة، إضافة إلى بيان المسافة التقريبية سيرًا على الأقدام من المحطة إلى المدرسة.","وشمل الدليل مدارس في عدد من أحياء ومناطق مكة المكرمة الواقعة على مسارات الشبكة، منها بطحاء قريش ، و العزيزية ، والعكيشية، و جرول ، وكدي، و أجياد ، والعوالي، و الرصيفة ، والعزيزية، وأم الجود، والشرائع، والعوالي، وجرول، و جعرانة ، و الجامعة ، والشهداء، مع تحديد رقم المحطة والمسافة بين كل محطة والمدرسة المدرجة في الدليل من خلال توفير معلومات إرشادية للطلاب قبل استخدام الحافلات.","كما وفرت حافلات مكة للطلاب والطالبات في مدينة مكة المكرمة خصمًا بنسبة 50% على التذاكر والباقات، دعمًا وتيسيرًا لتنقلات الطلاب والطالبات من مدارسهم وإليها.","ويأتي إصدار الدليل ضمن استعدادات منظومة حافلات مكة، أحد مشاريع المركز العام للنقل، لعودة الطلاب والطالبات إلى مقاعد الدراسة، وتوفير المعلومات المتعلقة بالمسارات والمحطات للطلاب وأولياء الأمور؛ بما يُساعدهم على تحديد الرحلة المناسبة والوصول إلى المدارس الواقعة ضمن نطاق شبكة حافلات مكة."]','التعليم','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/e9xziwce8','https://ajel.sa/local/e9xziwce8','https://ajel.sa/local/e9xziwce8','https://ajel.sa/local/e9xziwce8','فريق التحرير','مكة المكرمة','2026-08-29T11:35:00.000Z','Wed, 07 Oct 2026 19:53:36 GMT','2026-08-29T17:55:53.533Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-CSA5_4Hg.jpg','/api/media/830839d0-412f-4e7a-a5d7-1039ed3bad23','/api/media/830839d0-412f-4e7a-a5d7-1039ed3bad23?variant=thumbnail','استعدادا للعام الدراسي.. «حافلات مكة» تصدر دليلاً يوضح المسارات والمحطات القريبة من المدارس',1200,675,'valid','published','archived','valid',41,'cfb8035e1a25fb31e8f6b1376df55f30e2a05dc8dd9fdcb111ae3565dd1c93f7','fa02c63ca6528d632334f9485913352e270767cda2323016e8d978e7120b48ed','محدّث','2026-08-29T17:55:53.533Z','2026-10-07T20:24:32.282Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","مكة"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:53:37.739Z',200,46,0,'source_content_changed','',NULL,NULL,'body:749c5b215dde93991c08f0d3eafc7103897b1d54b1d957d0d232eb3360d561d9','Wed, 07 Oct 2026 19:53:36 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1674ea8d-1026-4151-b2a1-713b851fa602','news-1674ea8d-1026-4151-b2a1-713b851fa602','وقاء مكة المكرمة ينظّم حملة تحصين للحيوانات الأليفة بكورنيش الحمراء في جدة','وقاء مكه المكرمه ينظم حمله تحصين للحيوانات الاليفه بكورنيش الحمراء في جده','نظّم فرع المركز الوطني للوقاية من الآفات النباتية والأمراض الحيوانية ومكافحتها «وقاء» بمنطقة مكة المكرمة، حملةً لتحصين الحيوانات الأليفة بكورنيش الحمراء في مدينة جدة، بمشاركة طيف واسع من الجهات الحكومية والخاصة والأهلية.','["وتضمّنت الحملة تقديم التوعية والإرشادات اللازمة حول الوقاية من الأمراض الحيوانية، وفي مقدمتها داء السعار، وسبل التعامل معه وفق مفهوم «الصحة الواحدة»، فضلاً عن تقديم التحصينات الوقائية للحيوانات الأليفة مباشرةً للمواطنين والمقيمين.","وشارك في الحملة كلٌّ من أمانة محافظة جدة، ومديرية شرطة جدة، وحرس الحدود، إلى جانب عدد من العيادات البيطرية، من بينها: «بيتوبيا»، و«هابي بيت»، و«مدار العناية البيطرية».","وتندرج هذه الحملة ضمن جهود «وقاء» المستمرة لتعزيز الوقاية من الأمراض الحيوانية والمشتركة بين الإنسان والحيوان، ورفع مستوى الوعي المجتمعي بأهمية التحصين، بما يُسهم في صون الصحة الحيوانية والصحة العامة، والحدّ من مخاطر الأمراض الحيوانية."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/H2XYkbt','https://sabq.org/article/H2XYkbt','','https://sabq.org/article/H2XYkbt','فهد العتيبي','مكة المكرمة','2026-08-29T11:46:00.000Z','2026-08-29T14:47:00.000Z','2026-08-29T17:55:53.569Z','https://media.sabq.org/news/2026/08/dd47eff9-84e6-4ce0-b63f-275354482598/w1600.webp','/api/media/1674ea8d-1026-4151-b2a1-713b851fa602','/api/media/1674ea8d-1026-4151-b2a1-713b851fa602?variant=thumbnail','وقاء مكة المكرمة ينظّم حملة تحصين للحيوانات الأليفة بكورنيش الحمراء في جدة',1600,1066,'valid','published','archived','valid',95,'8bbb9d1fa39342cce578e7464046217dba863ecde6d1cffd064c20a6bac12191','4637db941b6608643ea07fd9efe1220ad06fab453df642c80bdeeba42a14439b','محدّث','2026-08-29T17:55:53.569Z','2026-10-07T19:53:10.864Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","مكة","جدة"]','["الصحة العامة"]','classified','','[{"category":"المجتمع","score":3},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:53:10.864Z',200,49,0,'source_article_available','',NULL,NULL,'body:e79619c0d28cc44cc4ea979d6e2b4e8e059742e18fd6bb0d1cc5bb6b90f4451d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f143bfe8-4369-4936-bb49-776bc2d5f8a5','news-f143bfe8-4369-4936-bb49-776bc2d5f8a5','القادسية يطلق برنامج «اكتشف» للزيارات المدرسية بأربعة مسارات متخصصة','القادسيه يطلق برنامج اكتشف للزيارات المدرسيه باربعه مسارات متخصصه','أطلق نادي القادسية برنامج «اكتشف» للزيارات المدرسية، إحدى مبادراته المجتمعية الهادفة إلى تقديم تجربة تعليمية وتفاعلية للطلبة، تتيح لهم التعرف على بيئة النادي ومرافقه، واستكشاف عالم الرياضة ومجالات العمل والتخصصات المرتبطة بها.','["ويستقبل البرنامج طلبة المدارس والجامعات ضمن تجربة تجمع بين المعرفة والتفاعل، وتوظّف مرافق النادي وخبراته الرياضية بما يتناسب مع احتياجات المراحل الدراسية المختلفة، بما يسهم في توسيع مدارك الطلبة وتعريفهم بمجالات قد ترتبط بطموحاتهم المستقبلية.","وصُمّم برنامج «اكتشف» عبر أربعة مسارات متخصصة تراعي الفئات العمرية والمراحل الدراسية، وتقدم لكل فئة تجربة مختلفة للتعرف على الرياضة ومرافق النادي والجوانب المتنوعة للمنظومة الرياضية، وهي: مسار التفاعل الممتع — يستهدف طلبة المرحلة الابتدائية من خلال جولات في مرافق النادي والملعب، إلى جانب ألعاب وتجارب حركية ومسابقات رياضية، تمنحهم فرصة لاكتشاف البيئة الرياضية في أجواء تجمع بين المتعة والتعلم.","مسار الشغف والمهارات — يستهدف طلبة المرحلة المتوسطة، ويعرّفهم على المهارات الفنية في مختلف الرياضات عبر جولة تشمل الصالات ومركز الأداء العالي، إلى جانب لقاء إثرائي حول أهمية الرياضة في الحياة اليومية، وتجارب مهارية بإشراف مدربين مختصين تعزز مفاهيم الانضباط والعمل الجماعي.","مسار الهندسة والتشغيل — يُقدَّم لطلبة المرحلة الثانوية والجامعية، ويعرّفهم على الجوانب الهندسية والتشغيلية للمنشآت الرياضية وآليات المحافظة على جاهزيتها واستدامتها، بما يشمل العناية بالملاعب وأنظمة الري والإضاءة والصوت.","مسار الإدارة وصناعة الرياضة — يتيح للطلبة التعرف على الجوانب الإدارية والإعلامية والاقتصادية للقطاع الرياضي، من خلال جولات في المكاتب الإدارية والإعلامية وغرف المؤتمرات، واستكشاف الأدوار والتخصصات التي تسهم في إدارة المنظومة الرياضية وتشغيلها."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/h2pmnkH','https://sabq.org/article/h2pmnkH','','https://sabq.org/article/h2pmnkH','صحيفة سبق','الرياض','2026-08-29T12:09:00.000Z','2026-08-29T15:10:00.000Z','2026-08-29T18:13:53.069Z','https://media.sabq.org/news/2026/08/982a14d9-5a2e-4af0-8ab4-2d768a410cdd/w1280.webp','/api/media/f143bfe8-4369-4936-bb49-776bc2d5f8a5','/api/media/f143bfe8-4369-4936-bb49-776bc2d5f8a5?variant=thumbnail','القادسية يطلق برنامج «اكتشف» للزيارات المدرسية بأربعة مسارات متخصصة',1280,1600,'valid','published','archived','valid',58,'a689c9cb8aa33e4793b72dab81d0343ba213028086942b115b326f56ffb8b077','c6436c478a12a589dfc0b10c41d885588cdb90a95785bf4433ab953304be1ed5','محدّث','2026-08-29T18:13:53.069Z','2026-10-07T20:24:32.287Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق","الرياض"]','["الثقافة والفنون","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"المناطق","score":0.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:02:53.601Z',200,49,0,'source_article_available','',NULL,NULL,'body:17b651ba17c5be8216546abc3e4828e6d1681000d7114a2145f8faec8a054b31','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4c55f421-7514-4bb5-b22f-afbfe0f9ca1d','news-4c55f421-7514-4bb5-b22f-afbfe0f9ca1d','تقارير: الاتحاد يقدم عرضًا لضم نجم بنفيكا لياندرو باريرو','تقارير الاتحاد يقدم عرضا لضم نجم بنفيكا لياندرو باريرو','ويرتبط تحرك الاتحاد أيضًا بالمدرب الهولندي ينس فيسينغ، الذي سبق له العمل مع باريرو خلال فترته في بنفيكا، ويعرف قدراته الفنية جيدًا، ما عزز إمكانية دخول النادي في مفاوضات لضمه.','["قدم نادي الاتحاد عرضًا رسميًا إلى بنفيكا البرتغالي للتعاقد مع لاعب الوسط اللوكسمبورجي لياندرو باريرو، البالغ 26 عامًا، في إطار تحركات النادي لتعزيز صفوفه خلال الأيام الأخيرة من فترة الانتقالات الحالية، وفقًا لتقارير صحفية برتغالية.","وذكرت صحيفة «Record» أن باريرو أصبح أحد أبرز خيارات الاتحاد، فيما أشارت صحيفة «A Bola» في يوليو الماضي إلى أن النادي كان قد وضع اللاعب ضمن حساباته لتعويض البرازيلي فابينيو .","ويملك باريرو مرونة تكتيكية تسمح له باللعب في أكثر من مركز بوسط الملعب، سواء في محور الارتكاز أو في دور أقرب إلى المهاجمين.","وانتقل اللاعب إلى بنفيكا صيف 2024 قادمًا من ماينز الألماني، وخاض خلال موسمه الأول في الدوري البرتغالي 27 مباراة سجل خلالها 3 أهداف، قبل أن يشارك في الموسم الماضي خلال 31 مباراة، سجل فيها 3 أهداف وصنع 5 أخرى.","ولا يقتصر تحرك الاتحاد في سوق الانتقالات على باريرو، إذ يسعى النادي أيضًا للتعاقد مع الياباني ريتسو دوان والجزائري هشام بوداوي لتعزيز الوسط والهجوم، وذلك بعد رحيل الفرنسي موسى ديابي ."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/ostpn0j7f','https://ajel.sa/sports/ostpn0j7f','https://ajel.sa/sports/ostpn0j7f','https://ajel.sa/sports/ostpn0j7f','فريق التحرير','','2026-08-29T12:16:00.000Z','Mon, 07 Sep 2026 03:27:51 GMT','2026-08-29T18:26:40.316Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%84%D9%8A%D8%A7%D9%86%D8%AF%D8%B1%D9%88-%D8%A8%D8%A7%D8%B1%D9%8A%D8%B1%D9%88-f9HmhJsK.jpg','/api/media/4c55f421-7514-4bb5-b22f-afbfe0f9ca1d','/api/media/4c55f421-7514-4bb5-b22f-afbfe0f9ca1d?variant=thumbnail','لياندرو باريرو',1200,675,'valid','published','archived','valid',41,'87bc7667d6db6bffcf014b9f22300eee0b2b6203b850b614c04a373e4f232d88','5ad6179dd900a74fe710230aa4e6a188a84b267ea6c8a87c78ec345c94cde421','محدّث','2026-08-29T18:26:40.316Z','2026-10-07T20:24:32.292Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","السياسة والعلاقات الدولية"]','["الرياضة السعودية","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T20:22:19.032Z',NULL,47,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('adc4fefc-ee8f-4639-8c99-38bf9a1e598d','news-adc4fefc-ee8f-4639-8c99-38bf9a1e598d','غرامة الـ200 ريال تُربك مستخدمي «مواقف الرياض».. ومطالبات بالتفريق بين من لم يدفع ومن نسي التمديد','غرامه الـ200 ريال تربك مستخدمي مواقف الرياض ومطالبات بالتفريق بين من لم يدفع ومن نسي التمديد','قصص من الردود وتكشف جولة في الردود والاقتباسات على منشور القنيبط قصصًا متنوعة، كثير منها لتجارب سلبية مع الخدمة؛ إذ اعتبر داود الشريان أن قيمة المخالفة (200 ريال) مبالغ فيها مقارنة برسوم الخدمة، فيما اقترح آخرون التمييز عند فرض المخالفة بين من لم يدفع الرسوم ابتداءً ومن دفعها ثم نسي التمديد بعد انقضاء الوقت المسموح.','["أبدى عدد من مستخدمي المواقف المدفوعة في العاصمة استياءهم من آلية التعامل مع المخالفات المرصودة على مركباتهم، مطالبين بالنظر في ملاحظاتهم وتطوير الخدمة من لحظة الدفع حتى آلية الاعتراض على المخالفة ومعالجتها.","وفتح الدكتور محمد القنيبط باب النقاش على منصة «إكس» بمقارنة بين تجربة الأمانة وتجربة «المرور»، رأى فيها تفوق الجهة الأخيرة من ثلاثة جوانب: أولها الشفافية والوضوح في تحديد مكان المخالفة، وهو خيار — بحسب رأيه — غير متاح في مخالفات المواقف؛ وثانيها أن مخالفات السرعة تبدأ من 150 ريالًا بينما تبدأ مخالفات المواقف من 200 ريال لحالات قد يكون سببها «النسيان أو الجهل»؛ وثالثها تجربة التطبيق التي وصفها بأنها دون مستوى تطبيق «أبشر».","وجهة نظر مقابلة في المقابل، أشاد فيصل النفيعي بالخدمة التي «يسّرت توفر المواقف لعشرات الخدمات على أرصفة كانت تغص بسيارات يرميها أصحابها لفترات قد تصل إلى أشهر»، مفندًا المقارنة بين الرسوم والغرامة؛ فانخفاض رسوم الموقف — بحسبه — هدفه التيسير على عامة الناس، بينما ارتفاع الغرامة هدفه الردع.","مقترحات للتطوير وشدد إبراهيم البابطين على أهمية تطوير الخدمة، مقترحًا تقليل تقسيم الطرق إلى مناطق دفع متعددة، لأن الخطأ في تحديد المنطقة «لا يجب أن يحاسَب عليه الملتزم بالنظام»، أو — على الأقل — توظيف التقنية لتحديد موقع المركبة تلقائيًا ومساعدة المستخدم على تجنب الخطأ.","يُذكر أن رسوم «مواقف الرياض» جاءت حلًا تنظيميًا لضبط الوقوف العشوائي لآلاف السيارات على جنبات الطرق، وأن الخدمة تشهد تطويرًا مستمرًا استجابةً للملاحظات، كان آخره إضافة الاشتراك الشهري، فيما يمكن الاطلاع على تفاصيل المخالفات المرصودة عبر بوابة الأمانة."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/r537j9y','https://sabq.org/article/r537j9y','','https://sabq.org/article/r537j9y','صحيفة سبق','الرياض','2026-08-29T12:26:00.000Z','2026-08-29T12:27:00.000Z','2026-08-29T22:11:56.937Z','https://media.sabq.org/news/2026/08/82ffc38f-a16e-473b-b538-a2a125282625/w1112.webp','/api/media/adc4fefc-ee8f-4639-8c99-38bf9a1e598d','/api/media/adc4fefc-ee8f-4639-8c99-38bf9a1e598d?variant=thumbnail','غرامة الـ200 ريال تُربك مستخدمي «مواقف الرياض».. ومطالبات بالتفريق بين من لم يدفع ومن نسي التمديد',1112,806,'valid','published','archived','valid',52,'0f6894ddf279534b9bc90ba7f824afb6e419c4c6ff2390cc8414ac6b4aeb69bf','7e36f1493fdcbe9b5aad1f87ea3d353e0c3cf581889117412e09f61b8823526a','محدّث','2026-08-29T18:26:50.189Z','2026-10-07T20:18:04.532Z','','',0,0,'saudi_region','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي","الرياض"]','["التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"المناطق","score":3},{"category":"الرياضة","score":3},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T20:18:04.532Z',200,57,0,'source_article_available','',NULL,NULL,'body:b0a332af522b48e241c1fcf1372b5f5cd828a7166250ce4e89fe8bc50679d1d8','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dce1787f-9178-4372-8017-5e3db3a2b60f','news-dce1787f-9178-4372-8017-5e3db3a2b60f','قاليباف: وزير الخزانة الأمريكي كاذب بشأن عبور 130 مليون برميل نفط من هرمز خلال 14 يوما','قاليباف وزير الخزانه الامريكي كاذب بشان عبور 130 مليون برميل نفط من هرمز خلال 14 يوما','قال رئيس البرلمان الإيراني محمد باقر قاليباف ، إن حديث وزير الخزانة الأمريكي سكوت بيسنت بشأن إجراجهم 130 مليون برميل نفط من مضيق هرمز بآخر 14 يوما "حديث كاذب".','["كانت وزير الخزانة الأمريكي ​قال إن بلاده نقلت 130 مليون برميل من النفط عبر ​مضيق هرمز​ خلال الأسبوعين الماضيين، في حين لم تنقل ​ إيران ​ أي برميل\"، مشيرا إلى أن الحصار البحري، وما وصفها بـ\"عملية الإقصاء الاقتصادي\" سيدمران الاقتصاد الإيراني.","وأضاف قاليباف عبر حسابه على منصة \"إكس\"، قائلا: \"اسأل موظفًا آخر عن حجم الخسائر التي تكبدتها شركة جين ستريت والتي تجاوزت 130 مليون دولار في بيع النفط على المكشوف لصالحك في جولة واحدة فقط من عقود النفط الآجلة\".","في سياق متصل، قال باقر قاليباف، إن القوى الخارجية مثل الولايات المتحدة \"عاجزة\" عن توفير أمن دائم لدول المنطقة، معتبرا أن الاتفاقيات والتعاون بين دول المنطقة \"بشارة ببدء عهد جديد\".","وأوضح رئيس البرلمان الإيراني أن التطورات التي شهدتها المنطقة خلال السنوات الأخيرة أثبتت للدول الإسلامية، بحسب تعبيره، أن القوى الخارجية مثل الولايات المتحدة لا يمكنها تحقيق أمن دائم للجميع."]','السياسة','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/5eexj59nq','https://ajel.sa/international/5eexj59nq','https://ajel.sa/international/5eexj59nq','https://ajel.sa/international/5eexj59nq','فريق التحرير','','2026-08-29T12:10:00.000Z','Wed, 07 Oct 2026 20:27:56 GMT','2026-08-29T18:38:50.487Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-Fzl9YPcY.jpg','/api/media/dce1787f-9178-4372-8017-5e3db3a2b60f','/api/media/dce1787f-9178-4372-8017-5e3db3a2b60f?variant=thumbnail','قاليباف: وزير الخزانة الأمريكي كاذب بشأن عبور 130 مليون برميل نفط من هرمز خلال 14 يوما',1200,675,'valid','published','archived','valid',99,'4889c9fabc6dd855d3e8286f835c3abdfdcc97835628f5a6a84e9d26d1a9e3b1','d0e6d01b5eae8d47a0028edbef67ee1b0871114ccc8d20eecda7de30acd55c61','محدّث','2026-08-29T18:38:50.487Z','2026-10-07T20:27:58.538Z','','',0,0,'international','عادي',39,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","شركة جين ستريت والتي تجاوزت","وزير الخزانة الأمريكي كاذب بشأن","رئيس البرلمان الإيراني محمد باقر","الطاقة والنفط","الاقتصاد والأسواق","السياسة والعلاقات الدولية","إيران"]','["شركة جين ستريت والتي تجاوزت","وزير الخزانة الأمريكي كاذب بشأن","رئيس البرلمان الإيراني محمد باقر","الطاقة والنفط","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T20:27:58.538Z',200,56,0,'source_content_changed','',NULL,NULL,'body:08d3130da9938d6bb481d145485efe60eab60d025fee7becb3236947a1612eee','Wed, 07 Oct 2026 20:27:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ee29f426-bda2-4234-a918-de586b582e74','news-ee29f426-bda2-4234-a918-de586b582e74','بعد البيان الأمريكي.. مصرف الإمارات المركزي يبدأ مراجعة معمقة لفروع بنك مصر','بعد البيان الامريكي مصرف الامارات المركزي يبدا مراجعه معمقه لفروع بنك مصر','وقال المصرف المركزي في بيان إن فروع بنك مصر العاملة في الإمارات تخضع للقوانين واللوائح المعمول بها داخل البلاد، مشيرًا إلى أن الفحص المرتقب سيشمل مراجعة معمقة للفترة الزمنية التي حددتها السلطات الأميركية في بيانها.','["أعلن مصرف الإمارات المركزي إجراء فحص خاص وعاجل لفروع بنك مصر العاملة في دولة الإمارات، يتضمن مراجعة معمقة تغطي الفترة المشار إليها في البيان الصادر عن السلطات الأميركية، مؤكدًا خضوع فروع البنك للقوانين واللوائح السارية داخل الدولة.","وأكد مصرف الإمارات المركزي أنه يتوقع من جميع البنوك المرخصة في الدولة عدم تعريض النظام المالي الإماراتي لمخاطر تتعلق بسمعته.","وقالت وزارة الخزانة الأمريكية ، إنها اتخذت إجراء لقطع تعاملات فروع ‌بنك مصر في الإمارات بالدولار بسبب تعاملاتها مع إيران. وأضافت الوزارة، في بيان، أن «شبكة مكافحة الجرائم المالية» اقترحت قاعدة تلغي إمكانية وصول فروع بنك مصر في الإمارات إلى خدمات الحسابات المصرفية المراسلة لدى المؤسسات المالية الأمريكية."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/2ppl27p0e','https://ajel.sa/international/2ppl27p0e','https://ajel.sa/international/2ppl27p0e','https://ajel.sa/international/2ppl27p0e','فريق التحرير','','2026-08-29T12:07:00.000Z','Wed, 07 Oct 2026 20:27:59 GMT','2026-08-29T18:38:50.898Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A8%D9%86%D9%83-%D9%85%D8%B5%D8%B1-%D8%A8%D8%A7%D9%84%D8%A5%D9%85%D8%A7%D8%B1%D8%A7%D8%AA-aqz5G_gj.jpg','/api/media/ee29f426-bda2-4234-a918-de586b582e74','/api/media/ee29f426-bda2-4234-a918-de586b582e74?variant=thumbnail','بنك مصر',1200,675,'valid','published','archived','valid',41,'05525287cea03f30abe5019b8f19bf7ae244d62b72ae24b1049535a5d3d5e80f','53800150384816db0ef8d3c7b7650f8fa50a129e430522dd3b45bc145a027934','محدّث','2026-08-29T18:38:50.898Z','2026-10-07T20:28:01.262Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الخزانة الأمريكية إنها اتخذت","إيران"]','["وزارة الخزانة الأمريكية إنها اتخذت"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:28:01.262Z',200,55,0,'source_content_changed','',NULL,NULL,'body:91ac8deedb036cd59cca9fc92420ede374eaf06caa0f6f438e9f1e9deba0e6fd','Wed, 07 Oct 2026 20:27:59 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8a46893b-bda8-49ce-957c-d90ca432ccbf','news-8a46893b-bda8-49ce-957c-d90ca432ccbf','الخلود يُسقط الأهلي بثلاثية ويقفز للمركز الثالث في روشن','الخلود يسقط الاهلي بثلاثيه ويقفز للمركز الثالث في روشن','حقق فريق الخلود فوزاً ثميناً على حساب ضيفه الأهلي بثلاثة أهداف مقابل هدف، في ختام منافسات الجولة الرابعة من دوري روشن السعودي للمحترفين، التي أُقيمت اليوم السبت على ملعب نادي الحزم بالرس، بإدارة الحكم شكري الحنفوش.','["شهد الشوط الأول استحواذاً واسعاً من لاعبي الأهلي على مجريات اللعب والسيطرة على منطقة الوسط، غير أن محاولات المهاجمَين إيفان توني وترينكاو لم تُفضِ إلى تهديد مرمى حارس الخلود حامد الشنقيطي.","وفي الدقيقة (32) سجّل إيكر كورتا خارينا الهدف الأول للخلود ليُنهي الشوط الأول بتقدم مضيفيه.","وفي مستهل الشوط الثاني، عادل هداف الأهلي إيفان توني النتيجة في الدقيقة (66) بتسديدة قوية من داخل منطقة جزاء الخلود.","بيد أن جوليان دومينغيز أعاد التقدم للخلود في الدقيقة (85) مستغلاً هفوة دفاعية من الأهلي في إبعاد الكرة عن منطقة الخطر.","وأحكم محمد صوان قفل المباراة بالهدف الثالث في الدقيقة (90+2)، ليضمن النقاط الثلاث لفريقه.","بهذه النتيجة ارتقى الخلود إلى المركز الثالث في ترتيب الدوري برصيد 8 نقاط، فيما تراجع الأهلي إلى المركز السادس برصيد 6 نقاط."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/GSyjQzx','https://sabq.org/article/GSyjQzx','','https://sabq.org/article/GSyjQzx','صحيفة سبق','','2026-08-29T12:12:00.000Z','2026-08-29T15:14:00.000Z','2026-08-29T18:38:53.303Z','https://media.sabq.org/news/2026/08/ee47cfbf-e5e1-41aa-8976-d24ed6aef27e/w1600.webp','/api/media/8a46893b-bda8-49ce-957c-d90ca432ccbf','/api/media/8a46893b-bda8-49ce-957c-d90ca432ccbf?variant=thumbnail','الخلود يُسقط الأهلي بثلاثية ويقفز للمركز الثالث في روشن',1600,2000,'valid','published','archived','valid',99,'eef6049160f84c67497641ccf68d44a7bc0f9a24b06b15f78602ac380b9446f6','a24b77b52220070de46e6c479a33d0e0b27126e7d3f46724ed00cfb9c14b506a','محدّث','2026-08-29T18:38:53.303Z','2026-10-07T20:27:47.658Z','','',0,0,'international','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":-5}]','Active','2026-10-07T20:27:47.658Z',200,55,0,'source_article_available','',NULL,NULL,'body:7e8070706092f19ab764ba59627697afc2b1e2f457eca8fd2b90c028cb5aeb71','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('03c43e1b-92df-419a-af69-48fd94398aae','news-03c43e1b-92df-419a-af69-48fd94398aae','أمير عسير يعلن اعتماد المدينة الطبية بجامعة الملك خالد مدينةً طبية تخصصية لخدمة المناطق الجنوبية','امير عسير يعلن اعتماد المدينه الطبيه بجامعه الملك خالد مدينه طبيه تخصصيه لخدمه المناطق الجنوبيه','أعلن الأمير تركي بن طلال بن عبدالعزيز، أمير منطقة عسير رئيس هيئة تطوير المنطقة، اعتماد المدينة الطبية بجامعة الملك خالد مدينةً طبية تخصصية لخدمة مناطق جنوب المملكة، بطاقة استيعابية تصل إلى (750) سريرًا، وتضم (41) تخصصًا طبيًا، ضمن منظومة متكاملة تجمع العلاج والتعليم والبحث والابتكار، مع استمرار مستشفى الملك فيصل التخصصي ومركز الأبحاث في الإشراف العلمي…','["جاء ذلك خلال رعاية سموه اليوم حفل تدشين عدد من المشروعات والمبادرات الصحية في المنطقة، بحضور معالي وزير التعليم الأستاذ يوسف بن عبدالله البنيان، ومعالي وزير الصحة الأستاذ فهد بن عبدالرحمن الجلاجل، ومعالي الرئيس التنفيذي لمستشفى الملك فيصل التخصصي ومركز الأبحاث الدكتور ماجد بن إبراهيم الفياض، ومعالي رئيس جامعة الملك خالد الدكتور فالح بن رجاء الله السلمي، ومحافظ الهيئة العامة للأوقاف عماد الخراشي، وعدد من المسؤولين والقيادات في القطاعات الحكومية والصحية والتعليمية.","وأوضح الأمير تركي بن طلال أن اعتماد المدينة الطبية جاء ثمرة عمل تكاملي خلال المرحلة الماضية بين وزارة الصحة ووزارة التعليم وجامعة الملك خالد، وبإشراف فني وعلمي من مستشفى الملك فيصل التخصصي ومركز الأبحاث، بهدف الوصول بالخدمات الصحية التخصصية في المنطقة إلى أعلى مستويات التميز والجودة والكفاءة.","وبيّن سموه أن العمل على هذا التوجه بدأ منذ عام، وصولًا إلى اعتماد المدينة الطبية بجامعة الملك خالد لتكون مدينةً طبية تخصصية تخدم مناطق جنوب المملكة، بدلًا من استكمال مشروع مدينة الملك فيصل الطبية للمناطق الجنوبية بصورته السابقة، مع الاستفادة من الصرح الطبي القائم وما اكتمل فيه من بنية وتجهيزات.","وأشار سموه إلى أن المدينة الطبية بجامعة الملك خالد تمثل امتدادًا لمسيرة الجامعة نحو العالمية، وتدعم في الوقت ذاته منظومة الخدمات الصحية التخصصية في مناطق جنوب المملكة، مؤكدًا أن هذا التوجه يجسد الاستخدام الأمثل لموارد الدولة، ويسهم في توجيهها نحو الاحتياجات الصحية ذات الأولوية، وتوفير التخصصات الطبية النوعية، وتقريب الخدمات التخصصية من المستفيدين.","ولفت سموه النظر إلى أن التقدم الصحي في منطقة عسير يمتد إلى صحة المجتمع وجودة الحياة، مبينًا أن حصول أبها ومحايل عسير وطريب ومدينة الملك خالد الجامعية على شهادات اعتماد دولية كمدن صحية، يمثل شاهدًا على ما حققته المنطقة في هذا الجانب، وأن اعتماد المدينة الطبية التخصصية يكمل حلقة أخرى في مسيرة التطوير، من خلال مدن أكثر صحة للعيش، وخدمات أرقى للعلاج، ومنظومة صحية تمضي نحو العالمية.","وأوضح سمو أمير منطقة عسير أن التكامل بين هيئة تطوير منطقة عسير ووزارة الصحة ووزارة التعليم وجامعة الملك خالد ومستشفى الملك فيصل التخصصي ومركز الأبحاث، يجسد مفهوم الحكومة الفاعلة التي تستهدفها رؤية السعودية (2030)، من خلال تكامل الجهات في العمل، وتسابقها في خدمة الإنسان، وقياس النجاح بالأثر المتحقق، مبينًا أنه جرى التوافق مع معالي وزير الصحة على المحافظة على المبنى القائم على طريق الملك عبدالله واستثماره بما يخدم مستقبل المنطقة.","واستهل سمو أمير منطقة عسير وأصحاب المعالي الوزراء البرنامج بالاطلاع على معرض إمارة منطقة عسير، الذي يضم عددًا من المشروعات والمبادرات التي تمثل جانبًا من خطة المنطقة في القطاع الصحي، وشواهد مصوّرة لمنجزات وأعمال صحية في محافظات ومراكز المنطقة.","كما استمع سموه والحضور في غرفة العمليات إلى شرح عن آلية عمل الغرفة وتكوينها ومنهجية العمل فيها، إلى جانب عرض حول حوكمة الدعم والتكامل مع القطاع الصحي."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/0Zd0F0c','https://sabq.org/article/0Zd0F0c','','https://sabq.org/article/0Zd0F0c','صحيفة سبق','المدينة المنورة','2026-08-29T12:50:00.000Z','2026-08-29T13:39:00.000Z','2026-08-29T22:11:53.982Z','https://media.sabq.org/news/2026/08/5facd6ae-e4d5-4fad-906b-c33b38501446/w1200.webp','/api/media/03c43e1b-92df-419a-af69-48fd94398aae','/api/media/03c43e1b-92df-419a-af69-48fd94398aae?variant=thumbnail','أمير عسير يعلن اعتماد المدينة الطبية بجامعة الملك خالد مدينةً طبية تخصصية لخدمة المناطق الجنوبية',1200,731,'valid','published','archived','valid',88,'8bbd215a5beacdbdfd7bf2354c4712a7b0daadb8cd398a031134fb47c65e8b46','69bc09ffff625a8b30edf53eec1a5a9a8fdb7979d47d22172fa517ce7b34e439','محدّث','2026-08-29T18:56:53.150Z','2026-10-07T21:10:41.241Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير التعليم الأستاذ يوسف بن","جامعة الملك خالد الدكتور فالح","رئيس هيئة تطوير المنطقة اعتماد","وزارة الصحة ووزارة التعليم وجامعة","هيئة تطوير المنطقة اعتماد المدينة","الصحة العامة","الطاقة والنفط","التعليم والتدريب"]','["وزير التعليم الأستاذ يوسف بن","جامعة الملك خالد الدكتور فالح","رئيس هيئة تطوير المنطقة اعتماد","وزارة الصحة ووزارة التعليم وجامعة","هيئة تطوير المنطقة اعتماد المدينة","الصحة العامة"]','classified','','[{"category":"المجتمع","score":5.5},{"category":"أخبار السعودية","score":3},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:10:41.241Z',200,50,0,'source_article_available','',NULL,NULL,'body:55117af5bf5afcd2c3dc0cd509a71192ee87691b88a6b4d8daeef778d538c4ce','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9335a616-bb42-4ead-ae33-cd189a4e41f7','news-9335a616-bb42-4ead-ae33-cd189a4e41f7','الخلود يصعق الأهلي بثلاثية في دوري روشن','الخلود يصعق الاهلي بثلاثيه في دوري روشن','حسم الخلود مواجهة الأهلي لصالحه بنتيجة 3-1، بعدما سجل هدفين في الدقائق الأخيرة من المباراة التي جمعتهما مساء السبت ضمن الجولة الرابعة من دوري روشن السعودي للموسم 2026-2027، ليحقق فوزه الثاني هذا الموسم ويصعد إلى المركز الثالث.','["وتقدم الخلود أولًا في الدقيقة 32 عن طريق إيكر كورتاجارينا، لينهي الشوط الأول متفوقًا بهدف دون رد، قبل أن يعيد الإنجليزي إيفان توني الأهلي إلى المباراة بتسجيل هدف التعادل في الدقيقة 67.","وبدا أن الأهلي في طريقه للخروج بنقطة، لكن الخلود انتفض في الدقائق الأخيرة واستغل المساحات في دفاع منافسه، ليسجل جوليان دومينغيز الهدف الثاني في الدقيقة 85، قبل أن يضيف محمد صوعان الهدف الثالث في الدقيقة الثالثة من الوقت بدل الضائع.","ومنح الفوز الخلود دفعة قوية في جدول الترتيب، إذ رفع رصيده إلى 8 نقاط وقفز إلى المركز الثالث، محافظًا على سجله خاليًا من الهزائم بعد مرور 4 جولات.","في المقابل، تلقى الأهلي خسارته الأولى في دوري روشن هذا الموسم، ليتجمد رصيده عند 6 نقاط، ويتراجع إلى المركز السابع، علمًا أنه خاض 3 مباريات فقط."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/p1wnqygbk','https://ajel.sa/sports/p1wnqygbk','https://ajel.sa/sports/p1wnqygbk','https://ajel.sa/sports/p1wnqygbk','فريق التحرير','','2026-08-29T13:07:00.000Z','Wed, 07 Oct 2026 21:18:53 GMT','2026-08-29T19:15:52.313Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/featured-crop-_Wm2pBrK.jpg','/api/media/9335a616-bb42-4ead-ae33-cd189a4e41f7','/api/media/9335a616-bb42-4ead-ae33-cd189a4e41f7?variant=thumbnail','الخلود والأهلي',1200,675,'valid','published','archived','valid',41,'a4d009a0a665f1fe4b9fb25d6f708882220b2b7218998a3ca7c120c6e9dca501','8bcab53dc9b4b82f6abde92608964c043f33d95b32dd5dd40dfaaa16b3ba0ee3','محدّث','2026-08-29T19:15:52.314Z','2026-10-07T21:18:54.850Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:18:54.850Z',200,63,0,'source_content_changed','',NULL,NULL,'body:bbb483e4878623b768339585b9913e08552b231cb925353119aed382a95cdf0b','Wed, 07 Oct 2026 21:18:53 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('382eb619-3484-4c0c-8ce4-8a0b7d36b3c7','news-382eb619-3484-4c0c-8ce4-8a0b7d36b3c7','مخبأة داخل مركبته.. القبض على مواطن لترويجه الحشيش وأقراص مخدرة بمكة لمكرمة','مخباه داخل مركبته القبض علي مواطن لترويجه الحشيش واقراص مخدره بمكه لمكرمه','ألقت القوة الخاصة لأمن الطرق، بمنطقة مكة المكرمة، القبض على مواطن لترويجه 9 كيلوجراما من مادة الحشيش المخدر و14733 قرصا خاضعا لتنظيم التداول الطبي، مخبأة داخل مركبته.','["وقال \"الأمن العام\" عبر حسابه على منصة \"إكس\"، إنه تم إيقاف المخالف، واتخاذ الإجراءات النظامية بحقه وإحالته إلى جهة الاختصاص.","وتهيب الجهات الأمنية بالإبلاغ عن كل ما يتوافر من معلومات لدى المواطنين والمقيمين عن أي نشاطات ذات صلة بتهريب أو ترويج المخدرات، وذلك من خلال الاتصال بالأرقام (911) في مناطق مكة المكرمة و الرياض و الشرقية و(999) في بقية مناطق المملكة ، ورقم بلاغات المديرية العامة لمكافحة المخدرات (995)، وعبر البريد الإلكتروني [email&#160;protected] ، وستعالج جميع البلاغات بسرية تامة."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/nqml1gjg7','https://ajel.sa/local/nqml1gjg7','https://ajel.sa/local/nqml1gjg7','https://ajel.sa/local/nqml1gjg7','فريق التحرير','الرياض','2026-08-29T13:06:00.000Z','Wed, 07 Oct 2026 21:18:55 GMT','2026-08-29T19:15:53.369Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-s9lfjmwc.jpg','/api/media/382eb619-3484-4c0c-8ce4-8a0b7d36b3c7','/api/media/382eb619-3484-4c0c-8ce4-8a0b7d36b3c7?variant=thumbnail','مخبأة داخل مركبته.. القبض على مواطن لترويجه الحشيش وأقراص مخدرة بمكة لمكرمة',1200,675,'valid','published','archived','valid',40,'8584f980fb185e0ffff8cd7cab990bd878fe0aee5d20694c41f2533e37c86184','15a7aa93cd7bfe1902545bc83c1411d6d045571c7d6e41d354ab3e1636566cb0','محدّث','2026-08-29T19:15:53.369Z','2026-10-07T21:18:57.142Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","الرياض"]','[]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:18:57.142Z',200,63,0,'source_content_changed','',NULL,NULL,'body:6234e717760bcc65683504543a22b7dbc0e103e8a83b6cb71bdb6666cb4e2d0d','Wed, 07 Oct 2026 21:18:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a72f80e9-7011-42cf-83a5-a753d1fb1973','news-a72f80e9-7011-42cf-83a5-a753d1fb1973','بالصور .. معهد الإدارة العامة يطلق برامج للدبلوم العالي في تخصصات نوعية','بالصور معهد الاداره العامه يطلق برامج للدبلوم العالي في تخصصات نوعيه','أطلق معهد الإدارة العامة، ممثلًا في مركز الأعمال، عددًا من برامج الدبلوم العالي في تخصصات نوعية، من بينها الدبلوم العالي في الأنظمة والتشريعات العقارية، الذي يقدمه المعهد بالشراكة مع المعهد العقاري السعودي ، والدبلوم العالي في إدارة سلاسل الإمداد واللوجستيات، بالشراكة مع الأكاديمية السعودية اللوجستية، وذلك ضمن سلسلة من فعاليات استقبال الدارسين والدارسات…','["ويأتي إطلاق هذه البرامج استجابةً لاحتياجات القطاعات الحيوية والمتنامية في المملكة ، وحرصًا من المعهد على تطوير برامج متخصصة تسهم في تأهيل الكفاءات الوطنية وتزويدها بالمعارف والمهارات المرتبطة بمتطلبات سوق العمل. ويستهدف الدبلوم العالي في الأنظمة والتشريعات العقارية تطوير كفاءات تجمع بين المعرفة النظامية والفهم المهني لمتطلبات القطاع العقاري، فيما يركز الدبلوم العالي في إدارة سلاسل الإمداد واللوجستيات على تنمية المهارات المتخصصة وتعزيز كفاءة الأداء في القطاع اللوجستي.","كما يواصل المعهد تقديم الدبلوم العالي لإدارة الأعمال التنفيذي في نسخته الثالثة، لتنمية القدرات الإدارية والقيادية وتعزيز معارف الدارسين والدارسات في مجالات التخطيط الاستراتيجي، والتحليل المالي، وإدارة المخاطر، والحوكمة، بما يسهم في رفع كفاءة المنظمات وتحسين أدائها.","ويأتي ذلك امتدادًا لإطلاق الدبلوم العالي لإدارة المنظمات غير الربحية مطلع هذا الأسبوع، بالشراكة مع مؤسسة السبيعي الخيرية وبدعم من المركز الوطني لتنمية القطاع غير الربحي، في خطوة تستهدف الإسهام في تأهيل الكفاءات المتخصصة في إدارة المنظمات غير الربحية وتطوير قدراتها بما يدعم نمو القطاع ورفع كفاءة ممارساته.","كما شهد هذا الأسبوع استقبال الدارسين والدارسات في الدبلوم العالي للعلوم القانونية، إلى جانب بقية برامج الدبلوم التي يقدمها المعهد، بما يعكس تنوع مسارات التأهيل والتطوير التي يوفرها للكوادر الوطنية في المجالات الإدارية والتخصصية المختلفة.","ويحرص المعهد في تقديم برامج الدبلوم العالي على تنوع المسارات وأنماط الدراسة بما يتناسب مع طبيعة البرامج والفئات المستهدفة؛ إذ تُقدّم بعض البرامج خلال نهاية الأسبوع بما يتيح للموظفين والكفاءات العاملة مواصلة تطويرهم وتأهيلهم دون تعارض مع التزاماتهم الوظيفية، فيما تُقدّم برامج أخرى خلال أيام الأسبوع وفق طبيعة البرنامج واحتياجات الدارسين، بما يدعم مستهدفات رؤية السعودية 2030 في تنمية القدرات البشرية ورفع كفاءة الكوادر الوطنية.","وأكد الرئيس التنفيذي لمركز الأعمال الأستاذ محمد بن خالد العقل، أن الاستثمار في الإنسان يمثل أساس التنمية، وأن البرامج التدريبية والتأهيلية المتخصصة تعد من أهم أدوات بناء القدرات الوطنية ورفع جاهزيتها، وتمكينها من مواكبة المتغيرات والاستجابة لمتطلبات المستقبل.","كما جرى خلال حفل الاستقبال الترحيب بالمتدربين والمتدربات وتعريفهم بالجوانب التنظيمية والتدريبية والخدمات المقدمة لهم، إيذانًا بانطلاق رحلتهم في برامج الدبلوم العالي."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/kd5aqdarv','https://ajel.sa/local/kd5aqdarv','https://ajel.sa/local/kd5aqdarv','https://ajel.sa/local/kd5aqdarv','علي الجريبي','','2026-08-29T13:04:00.000Z','Wed, 07 Oct 2026 21:18:54 GMT','2026-08-29T19:15:55.096Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/0e979a53-09f8-48ad-be77-2966c03fdbd6-crop-bw_ZCZ0N.jpg','/api/media/a72f80e9-7011-42cf-83a5-a753d1fb1973','/api/media/a72f80e9-7011-42cf-83a5-a753d1fb1973?variant=thumbnail','معهد الإدارة العامة',1200,675,'valid','published','archived','valid',53,'8261c1634246e3da621f21e4d37faf195fe2417d2ed1ea83101baf9e2b1fd641','25f1cd7eaa753e06c65236b05b76ce0063607d0a758214ceec688172c02b5ded','محدّث','2026-08-29T19:15:55.096Z','2026-10-07T21:18:55.945Z','','',0,0,'saudi_national','مهم',70,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق"]','["الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الطاقة والصناعة","score":4},{"category":"أخبار السعودية","score":3},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T21:18:55.945Z',200,63,0,'source_content_changed','',NULL,NULL,'body:fa6c65e0ce15ae5b3293ed11226ef72a336fb45517865b08dceb60c058d43daa','Wed, 07 Oct 2026 21:18:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c6fac191-a249-4bf5-b6b6-4491e036a7d0','news-c6fac191-a249-4bf5-b6b6-4491e036a7d0','قصف مدفعي للاحتلال على تلة باط الوردة بمحيط بيت جن في ريف دمشق','قصف مدفعي للاحتلال علي تله باط الورده بمحيط بيت جن في ريف دمشق','قصف جيش الاحتلال الإسرائيلي، اليوم، تلة باط الوردة قرب بلدة بيت جن في محافظة ريف دمشق جنوبي سوريا بـ4 قذائف مدفعية، دون تفاصيل بشأن نتائج القصف. وتحتل إسرائيل معظم مساحة الجولان منذ عام 1967، وإثر سقوط نظام بشار الأسد في 8 ديسمبر 2024، أعلنت انهيار اتفاقية فصل القوات الموقعة عام 1974، واحتلت المنطقة السورية العازلة ومواقع أخرى، بينها الجانب السوري من جبل…','["قصف جيش الاحتلال الإسرائيلي، اليوم، تلة باط الوردة قرب بلدة بيت جن في محافظة ريف دمشق جنوبي سوريا بـ4 قذائف مدفعية، دون تفاصيل بشأن نتائج القصف.","ووفق \"العربية\"، نقلا عن « الإخبارية السورية »: يأتي القصف بعد نحو أسبوع من اجتماع عقده وفد سوري برئاسة وزير الخارجية أسعد الشيباني مع وفد إسرائيلي في الأردن ، بوساطة أمريكية، وفق ما نقلته وكالة الأنباء السورية الرسمية «سانا».","وقال المصدر إن الاجتماع جاء «في إطار الجهود الرامية إلى خفض التصعيد في أعقاب القصف الإسرائيلي الأخير للأراضي السورية وتصاعد التوترات في جنوب سوريا».","وأوضح أن المناقشات ركزت على «وضع آليات عملية لوقف الاعتداءات الإسرائيلية وعمليات الاعتقال والاستهداف، وإحياء مسار التفاوض بهدف التوصل إلى اتفاق أمني يمكن أن يشكل أساسًا لاتفاق مستقبلي أكثر شمولًا».","وتحتل إسرائيل معظم مساحة الجولان منذ عام 1967، وإثر سقوط نظام بشار الأسد في 8 ديسمبر 2024، أعلنت انهيار اتفاقية فصل القوات الموقعة عام 1974، واحتلت المنطقة السورية العازلة ومواقع أخرى، بينها الجانب السوري من جبل الشيخ ."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/6x6cca7lq','https://ajel.sa/international/6x6cca7lq','https://ajel.sa/international/6x6cca7lq','https://ajel.sa/international/6x6cca7lq','فريق التحرير','','2026-08-29T13:22:00.000Z','Wed, 07 Oct 2026 19:07:55 GMT','2026-08-29T19:33:51.689Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-A6DwQzFa.jpg','/api/media/c6fac191-a249-4bf5-b6b6-4491e036a7d0','/api/media/c6fac191-a249-4bf5-b6b6-4491e036a7d0?variant=thumbnail','قصف مدفعي للاحتلال على تلة باط الوردة بمحيط بيت جن في ريف دمشق',1200,675,'valid','published','archived','valid',99,'4f69eb0dab09d6fda7b149b55f4a80b768a348fe57da9fdfa3b2d15661e8490a','22a398bbb5c31c3aecf8862b6c6be25f9e84e8d75c9750a5b0301df800413a92','محدّث','2026-08-29T19:33:51.690Z','2026-10-07T20:24:32.323Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الخارجية أسعد الشيباني مع","سوريا"]','["وزير الخارجية أسعد الشيباني مع"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T19:07:56.425Z',200,52,0,'source_article_available','',NULL,NULL,'body:e4a5f841aa73643ab5f827cc77c18d0c16cff745136935f868b320fd8260c961','Wed, 07 Oct 2026 19:07:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e6988c20-2b41-4642-8b7a-547aee388c59','news-e6988c20-2b41-4642-8b7a-547aee388c59','أمريكا لحزب الله: «سلموا أسلحتكم».. نزع السلاح شرط للبنان الآمن','امريكا لحزب الله سلموا اسلحتكم نزع السلاح شرط للبنان الامن','أكدت وزارة الخارجية الأمريكية أن الحكومة اللبنانية هي الجهة الشرعية الوحيدة المخولة بإجراء النقاشات المتعلقة بمستقبل لبنان والتحدث باسم شعبه، مشددة على أن تحقيق لبنان الآمن وذي السيادة يتطلب نزع سلاح حزب الله .','["وقالت الخارجية الأمريكية، في منشور عبر منصة «إكس» اليوم السبت، إن اتفاق «الإطار الثلاثي» بين الولايات المتحدة ولبنان ودولة الاحتلال ينص بوضوح على حصرية دور الحكومة اللبنانية في أي نقاش يتعلق بمستقبل البلاد.","وأكدت واشنطن وقوفها إلى جانب الشعب اللبناني ورغبتها في أن يكون لبنان «بلدًا آمنًا وذا سيادة»، مشيرة إلى أن الوصول إلى هذا الهدف يرتبط بإنهاء وجود سلاح حزب الله خارج إطار الدولة.","وقالت الخارجية الأمريكية إنها «لا تريد شيئًا أكثر من أن يسلم حزب الله أسلحته»، مضيفة أنه عندما يصبح الحزب مستعدًا للقيام بذلك، يمكنه التواصل مع الدولة اللبنانية وإبلاغها باستعداده لتسليم سلاحه، بما يتيح العمل على تقريب وجهات النظر.","واعتبرت واشنطن أن حزب الله لا يريد في الوقت الراهن التحدث مع الدولة اللبنانية أو الولايات المتحدة أو دولة الاحتلال، مضيفة أنه «يتلقى أوامره ببساطة من إيران ».","وختمت الخارجية الأمريكية رسالتها بالتأكيد على أن الوقت حان لكي يقدم حزب الله على ما وصفته بأنه «الأفضل للبنان وللشعب اللبناني».","وجاء الموقف الأمريكي بعد يوم واحد من تجديد الأمين العام لحزب الله نعيم قاسم رفضه اتفاق الإطار بين لبنان والاحتلال، مؤكدًا أن الحزب، لن يستسلم."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/o1k2psort','https://ajel.sa/international/o1k2psort','https://ajel.sa/international/o1k2psort','https://ajel.sa/international/o1k2psort','فريق التحرير','','2026-08-29T13:21:00.000Z','Wed, 07 Oct 2026 19:07:56 GMT','2026-08-29T19:33:53.080Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%AD%D8%B2%D8%A8-%D8%A7%D9%84%D9%84%D9%87-R3qN9lWZ.png','/api/media/e6988c20-2b41-4642-8b7a-547aee388c59','/api/media/e6988c20-2b41-4642-8b7a-547aee388c59?variant=thumbnail','حزب الله',1200,675,'valid','published','archived','valid',41,'9ea785b158d311a2b6d3669e08ee6c5f449abb33d963b8c2d99553360cc2044b','d3943072a5547b319a2a217a144535933e77e3d85cabb0aaea7995796040a70d','محدّث','2026-08-29T19:33:53.080Z','2026-10-07T20:24:32.326Z','','',0,0,'saudi_national','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الخارجية الأمريكية أن الحكومة","لبنان","إيران","الولايات المتحدة"]','["وزارة الخارجية الأمريكية أن الحكومة","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T19:07:58.123Z',200,52,0,'source_article_available','',NULL,NULL,'body:7c6c07e35702ffe37e1cb994034f79ba1e506e3a73255327d84766089a07d611','Wed, 07 Oct 2026 19:07:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7da87139-49b6-4c0b-8ff1-9af48b8b8f42','news-7da87139-49b6-4c0b-8ff1-9af48b8b8f42','بوابة الخدمات القانونية "سند" في وزارة البلديات والإسكان تحصد جائزة "ستيفي" في فئة التميز في الابتكار في منتجات وخدمات الذكاء الاصطناعي','بوابه الخدمات القانونيه سند في وزاره البلديات والاسكان تحصد جائزه ستيفي في فئه التميز في الابتكار في منتجات وخدمات الذكاء الاصطناعي','يُذكر أن بوابة الخدمات القانونية "سند" أحد منتجات الخطة التطويرية لمنظومة الأنظمة والشؤون القانونية في قطاع البلديات والإسكان، حيث تضمنت الخطة تطوير عدد من المسارات القانونية والمتعلقة بالحوكمة والاجراءات، والكوادر البشرية، والتحول الرقمي والذكاء الاصطناعي، وتضم "سند" العديد من الخدمات القانونية ومنها (القضايا، وأعمال لجان هيئة الخبراء، والتشريعات،…','["حصدت وزارة البلديات والإسكان الجائزة الفضية ضمن جوائز ستيفي للشرق الأوسط وشمال أفريقيا 2026، عن بوابة الخدمات القانونية \"سند\"، في فئة التميز في الابتكار في منتجات وخدمات الذكاء الاصطناعي – القطاع الحكومي، ضمن جهودها في تطوير البوابة وتوظيف تقنيات الذكاء الاصطناعي في رفع كفاءة الأعمال والخدمات القانونية الحكومية.","وتُعد جوائز \"ستيفي\" من الجوائز الدولية المتخصصة في تكريم الإنجازات والابتكارات في قطاعات الأعمال والجهات الحكومية والمؤسسات، وتضم برامج ومسارات تنافسية متعددة، فيما تخضع المشاركات للتقييم من لجان تحكيم تضم متخصصين وخبراء من مختلف دول العالم.","يُذكر أن بوابة الخدمات القانونية \"سند\" أحد منتجات الخطة التطويرية لمنظومة الأنظمة والشؤون القانونية في قطاع البلديات والإسكان، حيث تضمنت الخطة تطوير عدد من المسارات القانونية والمتعلقة بالحوكمة والاجراءات، والكوادر البشرية، والتحول الرقمي والذكاء الاصطناعي، وتضم \"سند\" العديد من الخدمات القانونية ومنها (القضايا، وأعمال لجان هيئة الخبراء، والتشريعات، الاستشارات القانونية، والنماذج القانونية) مدعومة بالعديد من حالات الذكاء الاصطناعي متمثلة في المراجع القانونية: توليد إجابات فورية للمستفيدين من خلال قراءة +4000 مادة نظامية سارية، ودراسة القضية: دراسة القضايا ومرفقاتها، وتوليد لوائح الرد مع التفريق بين 19 نمطًا من أنماط القضايا وباختلاف مستوياتها، وتحليل الأحكام القضائية: تحليل الأحكام القضائية لمعرفة الفجوات وإعداد مقترحات لتقليص الفجوات في القضايا، وتعزيز فرص الكسب وفق 41 عنصرًا تحليليًا، والمقارنات المعيارية: إعداد المقارنات المعيارية بين التشريعات المحلية والدولية وتحديثاتها، لتعزيز جودة التشريعات.","وتخدم \"سند\" أكثر 300 جهة، ويتجاوز عدد المستفيدين منها 60 ألف مستخدم من مختلف الجهات الحكومية، ونتج عن ذلك بناء قواعد بيانات مركزية، تسهم في رفع كفاءة وسرعة الأعمال القانونية ومضاعفة الإنتاجية وتعزيز أدوار الجهات الإشرافية، إضافة إلى تمكين الجهات التنفيذية من القيام بأدوارها.","ويأتي هذا الفوز ضمن جهود وزارة البلديات والإسكان في توظيف التقنيات الحديثة والذكاء الاصطناعي لتطوير نماذج العمل الحكومي، ورفع كفاءة الإجراءات، وتعزيز جودة الخدمات والأعمال القانونية"]','الذكاء الاصطناعي','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/olu7t3w','https://sabq.org/article/olu7t3w','','https://sabq.org/article/olu7t3w','صحيفة سبق','المنطقة الشرقية','2026-08-29T07:41:00.000Z','2026-08-29T16:25:00.000Z','2026-08-29T19:44:57.760Z','','','','بوابة الخدمات القانونية "سند" في وزارة البلديات والإسكان تحصد جائزة "ستيفي" في فئة التميز في الابتكار في منتجات وخدمات الذكاء الاصطناعي',NULL,NULL,'all_candidates_failed (og:fetch failed | structured:fetch failed | structured:fetch failed | structured:fetch failed | content:fetch failed)','published','archived','valid',46,'55c35bb48efda5850e673cc3eb0cd1b513b1632163680af9e41c79bd04c18c9c','e2f4bd91c3d06dc0aea7d4386e65a66eb47a449715b60fcd5d45ea76257584e0','محدّث','2026-08-29T19:44:57.760Z','2026-10-07T20:24:32.331Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البلديات والإسكان تحصد جائزة","هيئة الخبراء والتشريعات الاستشارات القانونية","التقنية والتحول الرقمي"]','["وزارة البلديات والإسكان تحصد جائزة","هيئة الخبراء والتشريعات الاستشارات القانونية","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"التقنية","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T19:26:09.046Z',200,61,0,'source_article_available','',NULL,NULL,'body:53da9039a69fe6d069e1b79097e9aa5d5850a541fd52bf2979de7510c93ae3e0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('77e97cec-1054-4d76-ae30-214d09b1fef5','news-77e97cec-1054-4d76-ae30-214d09b1fef5','«المركزي الإماراتي» يأمر بتفتيش عاجل على فروع بنك مصر إثر تحذير أمريكي','المركزي الاماراتي يامر بتفتيش عاجل علي فروع بنك مصر اثر تحذير امريكي','وفيما يخص فروع بنك مصر تحديداً، قرر المصرف المركزي إجراء تفتيش خاص وعاجل يشمل مراجعة معمّقة تغطي الفترة الزمنية المذكورة في البيان الأمريكي، مع التركيز على التعاملات المصرفية للشركات الواردة أسماؤها في ذلك البيان.','["أعلن مصرف الإمارات العربية المتحدة المركزي اطلاعه على البيان الصادر عن السلطات الأمريكية بشأن مقترح التدبير الخاص المتعلق بفروع بنك مصر العاملة في الدولة، والذي يصنّفها مؤسسةً مالية تعمل خارج الولايات المتحدة ذات مخاوف رئيسية في مجال غسل الأموال.","وأكد المصرف المركزي أن فروع بنك مصر في الإمارات خاضعة للقوانين والأنظمة المعمول بها في الدولة، مشدداً على أنه يتوقع من البنوك المرخصة لديه ألا تعرّض النظام المالي الإماراتي لمخاطر السمعة، وأن تحترم قوانين الدول التي تستخدم مؤسساتها المالية في إجراء معاملاتها، وألا تسيء استغلال البنية التحتية المالية المتطورة للدولة.","وأوضح المصرف المركزي أنه يُجري بصفة دورية عمليات تفتيش على إجراءات مواجهة غسل الأموال ومكافحة تمويل الإرهاب لدى البنوك العاملة في الإمارات، ويتحقق من كفاءة الأنظمة الإلكترونية المتعلقة بفحص العقوبات، ويطالب البنوك بتحسين هذه الإجراءات وفق متطلبات القوانين والأنظمة النافذة.","وأشار المصرف المركزي إلى أنه يدرس حالياً الخيارات المتاحة بشأن وضع البنك في حال تقرر اتخاذ التدبير الخاص ضده عقب استيفاء الإجراءات المقررة وفق القوانين الأمريكية، مؤكداً أنه سيتخذ القرار المناسب في حينه، مع مراعاة التزامات البنك تجاه عملائه في دولة الإمارات."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/q0P40-L','https://sabq.org/article/q0P40-L','','https://sabq.org/article/q0P40-L','صحيفة سبق','','2026-08-29T13:48:00.000Z','2026-08-29T16:48:00.000Z','2026-08-29T19:55:53.692Z','https://media.sabq.org/news/2026/08/62c0193b-8121-41e2-b655-8f9a8d0c5d64/w848.webp','/api/media/77e97cec-1054-4d76-ae30-214d09b1fef5','/api/media/77e97cec-1054-4d76-ae30-214d09b1fef5?variant=thumbnail','«المركزي الإماراتي» يأمر بتفتيش عاجل على فروع بنك مصر إثر تحذير أمريكي',848,568,'valid','published','archived','valid',41,'b3423a65ed7aaf7ef11d74965d4d61cc065f4b7446883199bfbba91acafff131','b41dc36689284f37169eb6388fd17fff739a658b09dca5936e3f9ef8b81a94ff','محدّث','2026-08-29T19:55:53.692Z','2026-10-07T20:24:32.335Z','','',0,0,'gulf_arab','عادي',46,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الولايات المتحدة"]','["الرياضة السعودية","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:33:21.286Z',200,51,0,'source_article_available','',NULL,NULL,'body:ed0973145188941fb9fee017c4f0a8fbd51ee912437db216a96d51d7f8ddfced','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('477cd1cb-832c-4ec8-9c77-431fd6959d9b','news-477cd1cb-832c-4ec8-9c77-431fd6959d9b','العارضة والقائم وقفا إلى جانب المستضيف.. الاتحاد والفتح سلبية في دوري روشن','العارضه والقائم وقفا الي جانب المستضيف الاتحاد والفتح سلبيه في دوري روشن','انتهى لقاء الاتحاد والفتح بالتعادل السلبي 0-0، ضمن منافسات الجولة الرابعة من دوري روشن السعودي للمحترفين، الذي أُقيم اليوم السبت على ملعب ميدان تمويل الأولى في الأحساء، بإدارة الحكم فيصل البلوي. في المقابل، تصدى حارس الاتحاد رايكوفيتش لتسديدة لاعب الفتح لوكاس في الدقيقة (84)، في أخطر كرة فتحاوية خلال المباراة.','["انتهى لقاء الاتحاد والفتح بالتعادل السلبي 0-0، ضمن منافسات الجولة الرابعة من دوري روشن السعودي للمحترفين، الذي أُقيم اليوم السبت على ملعب ميدان تمويل الأولى في الأحساء، بإدارة الحكم فيصل البلوي.","هيمن الاتحاد على مجريات الشوط الأول بحيازة الكرة بنسبة تجاوزت 66%، وسيطر على منطقة الوسط، غير أن محاولات المهاجمَين يوسف النصيري وحسام عوار لم تُفضِ إلى تهديد حقيقي لمرمى حارس الفتح أدريان شيمبر، الذي برز بأداء متألق في مشاركته الأولى مع الفريق «النموذجي»، ليستحق لقب نجم الشوط الأول.","وفي مستهل الشوط الثاني، حاول لاعب الاتحاد بيرغوين اختراق شباك الفتح في الدقيقة (47)، إلا أن شيمبر تصدى للكرة ببراعة.","وفي الدقيقة (81)، أنقذت العارضة الفتحاوية مرماها من رأسية مدافع الاتحاد دانيلو بيريرا.","في المقابل، تصدى حارس الاتحاد رايكوفيتش لتسديدة لاعب الفتح لوكاس في الدقيقة (84)، في أخطر كرة فتحاوية خلال المباراة.","وفي الوقت القاتل عند الدقيقة (90)، أنقذ القائم الفتحاوي مرماه من تسديدة لاعب الاتحاد معاذ فقيهي، قبل أن يُهدر الاتحاد فرصة أخرى في الوقت بدلاً من الضائع.","بهذه النتيجة، ارتفع رصيد الاتحاد إلى 8 نقاط في المركز الرابع، فيما بقي الفتح في المركز السادس عشر برصيد نقطتين فقط."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/bkLVdtL','https://sabq.org/article/bkLVdtL','','https://sabq.org/article/bkLVdtL','صحيفة سبق','المنطقة الشرقية','2026-08-29T14:01:00.000Z','2026-08-29T17:01:00.000Z','2026-08-29T20:04:54.156Z','https://media.sabq.org/news/2026/08/f5d18ff3-7732-46d0-994a-e27f3a0b24b7/w1600.webp','/api/media/477cd1cb-832c-4ec8-9c77-431fd6959d9b','/api/media/477cd1cb-832c-4ec8-9c77-431fd6959d9b?variant=thumbnail','العارضة والقائم وقفا إلى جانب المستضيف.. الاتحاد والفتح سلبية في دوري روشن',1600,965,'valid','published','archived','valid',99,'5868db803a378c5349f493755fbd1b7601c3545ddbbb3b611283c8cffdee019d','bee19b4d172f409912406c83dfd95c08bd289ce1b26875b70516bbe1a3b5f8a5','محدّث','2026-08-29T20:04:54.156Z','2026-10-07T19:34:55.611Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T19:34:55.611Z',200,49,0,'source_article_available','',NULL,NULL,'body:0821da0109caa9a8c72bba0f64b2a6e854e180e551f694fd2482b0b9ea0291ba','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('feee7d48-2f03-4f57-b1eb-542f97a74e80','news-feee7d48-2f03-4f57-b1eb-542f97a74e80','الاحتلال يفجر دارا للمسنين في بلدة حولا جنوبي لبنان','الاحتلال يفجر دارا للمسنين في بلده حولا جنوبي لبنان','أفادت الوكالة الوطنية للإعلام اللبنانية بأن جيش الاحتلال الإسرائيلي نفذ عملية تفجير استهدفت دارًا للمسنين في بلدة حولا ، بقضاء مرجعيون ، جنوبي لبنان. وأفادت الوكالة الوطنية للإعلام اللبنانية، وفق " الشرق "، بأن جيش الاحتلال الإسرائيلي قصف بالمدفعية مناطق قرب النبطية في جنوب لبنان .','["أفادت الوكالة الوطنية للإعلام اللبنانية بأن جيش الاحتلال الإسرائيلي نفذ عملية تفجير استهدفت دارًا للمسنين في بلدة حولا ، بقضاء مرجعيون ، جنوبي لبنان.","في سياق آخر أفاد إعلام لبناني، أن المفاوضات حول دخول الجيش اللبناني للمنشأة العسكرية في \"علي الطاهر\" فشلت لرفض إسرائيل الانسحاب.","وأفادت الوكالة الوطنية للإعلام اللبنانية، وفق \" الشرق \"، بأن جيش الاحتلال الإسرائيلي قصف بالمدفعية مناطق قرب النبطية في جنوب لبنان .","وأضافت الوكالة أن القصف الإسرائيلي استهدف بلدتي حداثا وحاريص في محافظة النبطية.","وتأتي هذه الاعتداءات في ظل استمرار التصعيد الإسرائيلي ضد قرى وبلدات جنوب لبنان، رغم اتفاق بين بيروت و تل أبيب بشأن انسحاب إسرائيلي تدريجي ضمن مسار تفاوضي برعاية أمريكية.","وتحتل إسرائيل مناطق في جنوب لبنان، بعضها منذ عقود وأخرى منذ الحرب التي دارت بين عامي 2023 و2024، فيما وسعت نطاق احتلالها داخل الأراضي اللبنانية خلال عدوانها الراهن."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/ous6euy2e','https://ajel.sa/international/ous6euy2e','https://ajel.sa/international/ous6euy2e','https://ajel.sa/international/ous6euy2e','فريق التحرير','','2026-08-29T13:49:00.000Z','Wed, 07 Oct 2026 19:53:43 GMT','2026-08-29T20:13:53.560Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-zeGyBLjw.jpg','/api/media/feee7d48-2f03-4f57-b1eb-542f97a74e80','/api/media/feee7d48-2f03-4f57-b1eb-542f97a74e80?variant=thumbnail','الاحتلال يفجر دارا للمسنين في بلدة حولا جنوبي لبنان',1200,675,'valid','published','archived','valid',41,'7b0b5472184747324fffa1f0f98500a93c9ee3836d4015a74f0b2d60daf24327','33b0b655d465ed8ea10c7ed80e05a80aec178ef52bf3ef48540350260b1cc148','محدّث','2026-08-29T20:13:53.560Z','2026-10-07T20:24:32.341Z','','',0,0,'gulf_arab','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["السياسة والعلاقات الدولية","لبنان"]','["السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:53:44.775Z',200,44,0,'source_content_changed','',NULL,NULL,'body:e87dc769f04f3a196fbc13aa98ab77b10adc98fdef80eb0c479b134aaf4a5751','Wed, 07 Oct 2026 19:53:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('983d3100-209e-43c9-b4d2-0473332d8ef0','news-983d3100-209e-43c9-b4d2-0473332d8ef0','الدرعية يسقط الاتفاق بثلاثية نظيفة ويرتقي إلى المركز الخامس في دوري روشن','الدرعيه يسقط الاتفاق بثلاثيه نظيفه ويرتقي الي المركز الخامس في دوري روشن','حقق فريق الدرعية فوزاً ساحقاً على حساب مضيفه الاتفاق بثلاثة أهداف نظيفة، في مباراة الجولة الرابعة من دوري روشن السعودي للمحترفين التي أُقيمت مساء السبت.','["وانتهى الشوط الأول بتقدم الدرعية بهدف دون رد، سجله المهاجم داروين نونيز في الدقيقة الثامنة، قبل أن يعود الفريقان إلى الملعب في الشوط الثاني ويواصل الدرعية هيمنته على مجريات اللقاء.","وفي الشوط الثاني، ضاعف الدرعية تقدمه بالهدف الثاني عن طريق عادل بولبينة في الدقيقة 53، ثم عاد نونيز ليُسجل هدفه الثاني وثالث أهداف فريقه في الدقيقة 81، مؤمناً بذلك الانتصار والنقاط الثلاث.","وبهذه النتيجة رفع الدرعية رصيده إلى 7 نقاط ليحتل المركز الخامس في جدول ترتيب دوري روشن، في حين مُني الاتفاق بخسارته الثانية على التوالي بعد أن استهل موسمه بفوزين متتاليين، ليتجمد رصيده عند 6 نقاط ويحتل المرتبة التاسعة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/S74uKv9','https://sabq.org/article/S74uKv9','','https://sabq.org/article/S74uKv9','صحيفة سبق','الرياض','2026-08-29T14:12:00.000Z','2026-08-29T17:12:00.000Z','2026-08-29T20:13:54.270Z','https://media.sabq.org/news/2026/08/8b18f9bc-8738-4899-87e7-5cb2e2dfd30c/w1600.webp','/api/media/983d3100-209e-43c9-b4d2-0473332d8ef0','/api/media/983d3100-209e-43c9-b4d2-0473332d8ef0?variant=thumbnail','الدرعية يسقط الاتفاق بثلاثية نظيفة ويرتقي إلى المركز الخامس في دوري روشن',1600,2000,'valid','published','archived','valid',99,'4e9b0ff9bc54660d37729ff254abeecdb22187a75764e172962f137f696356cd','a526a2a3385463e3c17b116b737f007abc8c98ac6baa1cdf435b8db4f8dbb4d7','محدّث','2026-08-29T20:13:54.270Z','2026-10-07T19:53:06.459Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T19:53:06.459Z',200,48,0,'source_article_available','',NULL,NULL,'body:a3ccef62e9893f0abdbb5164aa3f39d31fe6785625812637b2bcd84bcfb4603a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('45c0e698-f189-46f1-bc21-47f57cd1a5ab','news-45c0e698-f189-46f1-bc21-47f57cd1a5ab','الدفاع المدني يخمد حريقًا في شاحنة و4 صهاريج بحي النور في الرياض','الدفاع المدني يخمد حريقا في شاحنه و4 صهاريج بحي النور في الرياض','أخمدت فرق الدفاع المدني في منطقة الرياض حريقًا اندلع في مقدمة شاحنة وأربع صهاريج ب حي النور ، اليوم السبت. وأوضحت المديرية العامة للدفاع المدني، عبر حسابها على منصة «إكس»، أن فرقها باشرت الحريق وتمكنت من إخماده، فيما لم تُسجل أي إصابات جراء الحادث.','["أخمدت فرق الدفاع المدني في منطقة الرياض حريقًا اندلع في مقدمة شاحنة وأربع صهاريج ب حي النور ، اليوم السبت.","وأوضحت المديرية العامة للدفاع المدني، عبر حسابها على منصة «إكس»، أن فرقها باشرت الحريق وتمكنت من إخماده، فيما لم تُسجل أي إصابات جراء الحادث."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/1qe990nui','https://ajel.sa/local/1qe990nui','https://ajel.sa/local/1qe990nui','https://ajel.sa/local/1qe990nui','فريق التحرير','الرياض','2026-08-29T13:49:00.000Z','Wed, 07 Oct 2026 19:53:37 GMT','2026-08-29T20:13:55.545Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/HQ6dlnEXgAAQHha-crop-wBeb4NSs.jpg','/api/media/45c0e698-f189-46f1-bc21-47f57cd1a5ab','/api/media/45c0e698-f189-46f1-bc21-47f57cd1a5ab?variant=thumbnail','الحريق',1200,675,'valid','published','archived','valid',41,'0a05e7469f65a23bf4dad5c05e2ca7ab46633aa8c54100415f2f158dbcbc532d','014b870b5bdc40a0f14231400d4c488db210582d811a95508c85e468ea062b61','محدّث','2026-08-29T20:13:55.546Z','2026-10-07T20:24:32.348Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:53:39.058Z',200,44,0,'source_content_changed','',NULL,NULL,'body:58a1f0943a8bc44f06c8b69745ef76ca9f5d2af9d2430b6ff4667af972342be7','Wed, 07 Oct 2026 19:53:37 GMT');
