INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5b9f4e9c-3bb1-4a4f-988e-0e48845b31ed','news-5b9f4e9c-3bb1-4a4f-988e-0e48845b31ed','نيوكاسل يتغلب على مضيفه توتنهام في الجولة الثانية من الدوري الإنجليزي الممتاز','نيوكاسل يتغلب علي مضيفه توتنهام في الجوله الثانيه من الدوري الانجليزي الممتاز','حقق نيوكاسل يونايتد فوزاً ثميناً على حساب مضيفه توتنهام هوتسبير بنتيجة 2 - 0، في المباراة التي جمعتهما ضمن منافسات الجولة الثانية من الدوري الإنجليزي الممتاز.','["وبهذا الفوز، يرفع نيوكاسل رصيده إلى 4 نقاط، ويتطلع إلى مواصلة انطلاقته القوية باستضافة بورنموث في الجولة الثالثة، السبت المقبل.","في المقابل، يواصل توتنهام تعثره إذ بقي بلا أي رصيد بعد خسارته الثانية على التوالي في الدوري، ولم تُسعفه نتائجه في المسابقات الأخرى، إذ كان قد فاز بنتيجة كاسحة 5 - 1 على تشارلتون في كأس الرابطة، في محاولة للتعافي من الهزيمة الثقيلة بثلاثية أمام برينتفورد في الجولة الأولى من الدوري."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/rHbJBTx','https://sabq.org/article/rHbJBTx','','https://sabq.org/article/rHbJBTx','صحيفة سبق','','2026-08-29T14:21:00.000Z','2026-08-29T17:21:00.000Z','2026-08-29T20:31:54.390Z','https://media.sabq.org/news/2026/08/63a13800-bf4b-426f-93b4-2dd961d82380/w1600.webp','/api/media/5b9f4e9c-3bb1-4a4f-988e-0e48845b31ed','/api/media/5b9f4e9c-3bb1-4a4f-988e-0e48845b31ed?variant=thumbnail','نيوكاسل يتغلب على مضيفه توتنهام في الجولة الثانية من الدوري الإنجليزي الممتاز',1600,2000,'valid','published','archived','valid',51,'a431cbdc46f50dec988952abe93dfdb54a68799cefb40cbfc1d164c282a4b146','3bb5dd43aa56b961d6506b821a57956abc796e9f22bcd5564f5286f28ae4285f','محدّث','2026-08-29T20:31:54.390Z','2026-10-07T20:18:01.860Z','','',0,0,'international','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:18:01.860Z',200,60,0,'source_article_available','',NULL,NULL,'body:0cc2f2b3a7d690226b6a547d5ad4eac11832b693cfb88c83cf95d24d1089b44d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('659751c0-9777-4b2e-8016-d3689f19266f','news-659751c0-9777-4b2e-8016-d3689f19266f','رابطة الدوري السعودي للمحترفين تعلن مواعيد الجولات السابعة حتى الثانية عشرة','رابطه الدوري السعودي للمحترفين تعلن مواعيد الجولات السابعه حتي الثانيه عشره','أعلنت رابطة الدوري السعودي للمحترفين، ممثلةً بإدارة المسابقات، جدول مباريات الجولات من السابعة وحتى الثانية عشرة من منافسات دوري روشن السعودي للموسم الرياضي 2026-2027.','["وأفادت الرابطة بأن إعداد الجدول جاء مراعياً عدداً من الجوانب التنظيمية والفنية المرتبطة بسير المنافسات، إلى جانب متطلبات الروزنامة المحلية والدولية، بما يحقق التوازن بين مختلف الالتزامات.","واعتمدت الرابطة خلال هذه الجولات التوقيت المسائي المبكر في عدد من المباريات، ضمن التوقيتات المعتمدة والمعلن عنها مسبقاً، بما يتيح تنوعاً في مواعيد إقامة المواجهات ويراعي ضغط الروزنامة خلال الموسم.","وتأتي هذه الجدولة في ظل روزنامة رياضية مزدحمة، بالتزامن مع استضافة المملكة العربية السعودية عدداً من البطولات والأحداث الرياضية على المستويين الإقليمي والقاري، مما يستوجب تنسيقاً مستمراً ومراعاةً دقيقة لمتطلبات تنظيم منافسات الدوري.","وتواصل رابطة الدوري السعودي للمحترفين إدارة روزنامة الموسم بما يحقق التوازن بين متطلبات المسابقة والتزامات الأندية والمنتخب الوطني، حرصاً على انتظام المنافسة ومواكبة المكانة المتنامية لدوري روشن السعودي."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/U_StkBL','https://sabq.org/article/U_StkBL','','https://sabq.org/article/U_StkBL','صحيفة سبق','الرياض','2026-08-29T14:45:00.000Z','2026-08-29T17:45:00.000Z','2026-08-29T20:49:55.268Z','https://media.sabq.org/news/2026/08/8dc65da9-69b5-4bfc-b230-36cf16d68059/w1179.webp','/api/media/659751c0-9777-4b2e-8016-d3689f19266f','/api/media/659751c0-9777-4b2e-8016-d3689f19266f?variant=thumbnail','رابطة الدوري السعودي للمحترفين تعلن مواعيد الجولات السابعة حتى الثانية عشرة',1179,651,'valid','published','archived','valid',99,'2dc6cf8fc3dbe9339a20ecfb47a03bf21cf8a6b3fd7ec3d66ec0a30bbdff4428','8485dcd6cc4b55fe1be7ce68e90cdf5f41510870622595aa3a6e95d1ce6a4f23','محدّث','2026-08-29T20:49:55.268Z','2026-10-07T20:57:12.531Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","الرياضة السعودية","الرياض"]','["الثقافة والفنون","الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"المجتمع","score":0},{"category":"التقنية","score":0}]','Temporarily Unreachable','2026-10-07T20:57:12.531Z',NULL,57,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4f48c166-feb2-4393-89f4-46ff89369631','news-4f48c166-feb2-4393-89f4-46ff89369631','الفتح يتعادل سلبيًا مع الاتحاد في الجولة الرابعة من «دوري روشن»','الفتح يتعادل سلبيا مع الاتحاد في الجوله الرابعه من دوري روشن','تعادل فريق الفتح مع ضيفه الاتحاد دون أهداف، في المباراة التي جمعتهما اليوم على ملعب ميدان تمويل الأولى ب الأحساء ، ضمن منافسات الجولة الرابعة من الدوري السعودي للمحترفين "دوري روشن"، للموسم الرياضي 2026 - 2027.','["وبهذا التعادل، رفع الفتح رصيده إلى نقطتين، فيما رفع الاتحاد رصيده إلى 8 نقاط."]','الوظائف وسوق العمل','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/dnou607qz','https://ajel.sa/sports/dnou607qz','https://ajel.sa/sports/dnou607qz','https://ajel.sa/sports/dnou607qz','فريق التحرير','الرياض','2026-08-29T14:48:00.000Z','Wed, 07 Oct 2026 18:39:04 GMT','2026-08-29T21:03:03.914Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-crop-R0ieow3M.png','/api/media/4f48c166-feb2-4393-89f4-46ff89369631','/api/media/4f48c166-feb2-4393-89f4-46ff89369631?variant=thumbnail','الفتح يتعادل سلبيًا مع الاتحاد في الجولة الرابعة من «دوري روشن»',1200,675,'valid','rejected','archived','invalid',41,'2c1020de57047a2d06c67b4140cbb94ccbc85d2d457d54f8b388598109d2d827','c4a0302a2209f33f9f97a92f11543542b73884790753b69a0b715a278a64efae','محدّث','2026-08-29T21:03:03.914Z','2026-10-07T19:24:38.659Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T18:39:05.871Z',200,51,0,'source_content_changed','',NULL,NULL,'body:5b269d689acd9804e90e0ab0a3b974e430d5fc282eaaa332e8cf14abae79d693','Wed, 07 Oct 2026 18:39:04 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5ee1fb8c-4232-4f1a-86ee-a70794be0fbb','news-5ee1fb8c-4232-4f1a-86ee-a70794be0fbb','التعادل الإيجابي يحسم مواجهة الدحيل والعربي في الجولة الثانية بالدوري القطري','التعادل الايجابي يحسم مواجهه الدحيل والعربي في الجوله الثانيه بالدوري القطري','وتقدم الدحيل عن طريق مدافعه البرازيلي لوكاس ميلو في الدقيقة 52، فيما أدرك العربي التعادل بواسطة مهاجمه الكيني مايكل أولونغا في الدقيقة 70. ومن المقرر أن يلتقي الدحيل مع الريان، والعربي مع السيلية في الجولة الثالثة من المسابقة.','["تعادل الدحيل والعربي بهدف لمثله، في المباراة التي جمعتهما اليوم على إستاد البيت، ضمن الجولة الثانية من الدوري القطري لكرة القدم.","وتقدم الدحيل عن طريق مدافعه البرازيلي لوكاس ميلو في الدقيقة 52، فيما أدرك العربي التعادل بواسطة مهاجمه الكيني مايكل أولونغا في الدقيقة 70.","وتواصلت بعد ذلك المحاولات من الفريقين سعيًا نحو اقتناص هدف التقدم، لكن لم يتمكن أي منهما من تسجيل هدف آخر، لتنتهي المباراة بالتعادل ويكتفي كل فريق بنقطة واحدة.","ومن المقرر أن يلتقي الدحيل مع الريان، والعربي مع السيلية في الجولة الثالثة من المسابقة."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/5cms4ztml','https://ajel.sa/sports/5cms4ztml','https://ajel.sa/sports/5cms4ztml','https://ajel.sa/sports/5cms4ztml','فريق التحرير','','2026-08-29T14:36:00.000Z','Wed, 07 Oct 2026 20:59:48 GMT','2026-08-29T21:04:26.999Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-P-LdrdkJ.png','/api/media/5ee1fb8c-4232-4f1a-86ee-a70794be0fbb','/api/media/5ee1fb8c-4232-4f1a-86ee-a70794be0fbb?variant=thumbnail','التعادل الإيجابي يحسم مواجهة الدحيل والعربي في الجولة الثانية بالدوري القطري',1200,675,'valid','published','archived','valid',41,'8e9209005738e737c0ca28df7454f63d49ced92baaece620a14f7aa8d5f88bcb','f6d2cbd545f9bb0fb3c28435b2bf83e30efcd7e95872276bcef09730e78d2c9a','محدّث','2026-08-29T21:04:26.999Z','2026-10-07T20:59:50.319Z','','',0,0,'gulf_arab','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:59:50.319Z',200,55,0,'source_content_changed','',NULL,NULL,'body:7a21792329ba8113b97d6ef38391361d7cb90839d0a0906f1502361b8fb87a30','Wed, 07 Oct 2026 20:59:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0a28aeee-d38c-4b45-903a-a8bf372123fd','news-0a28aeee-d38c-4b45-903a-a8bf372123fd','الدرعية يتغلب على الاتفاق بثلاثية في الجولة الرابعة من الدوري السعودي للمحترفين','الدرعيه يتغلب علي الاتفاق بثلاثيه في الجوله الرابعه من الدوري السعودي للمحترفين','تغلب فريق الدرعية على مضيفه الاتفاق بثلاثة أهداف دون مقابل، في اللقاء الذي جمعهما اليوم على ملعب إيجو ب الدمام ، ضمن منافسات الجولة الرابعة من الدوري السعودي للمحترفين "دوري روشن" للموسم الرياضي 2026 - 2027.','["وسجل للدرعية داروين نونيز هدفين عند الدقيقتين 8 و81، فيما أضاف عادل بولبينة الهدف الثالث عند الدقيقة 53.","وبهذه النتيجة، رفع الدرعية رصيده إلى 7 نقاط، فيما تجمد رصيد الاتفاق عند 6 نقاط."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/oc3gtswm8','https://ajel.sa/sports/oc3gtswm8','https://ajel.sa/sports/oc3gtswm8','https://ajel.sa/sports/oc3gtswm8','فريق التحرير','الرياض','2026-08-29T15:06:00.000Z','Wed, 07 Oct 2026 21:20:43 GMT','2026-08-29T21:34:54.152Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-crop-FxF3iv1g.png','/api/media/0a28aeee-d38c-4b45-903a-a8bf372123fd','/api/media/0a28aeee-d38c-4b45-903a-a8bf372123fd?variant=thumbnail','الدرعية يتغلب على الاتفاق بثلاثية في الجولة الرابعة من الدوري السعودي للمحترفين',1200,675,'valid','published','archived','valid',41,'99136b45ac4f9d7b351b24ed38ddd810397472a1f5eed3bd735e7b212d645268','3f58a7417f82cc97dc8015c0aaaef7eb16cd0306343d73367edf7aa0664da75c','محدّث','2026-08-29T21:34:54.152Z','2026-10-07T21:20:45.210Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض","الدمام"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:20:45.210Z',200,60,0,'source_content_changed','',NULL,NULL,'body:5192dd91b2e3b2a87a9c68259a5aeb45d216377d6ddbcfc45c8858e3d3560c91','Wed, 07 Oct 2026 21:20:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3f829cd6-443e-4806-9c2a-33ace65935e7','news-3f829cd6-443e-4806-9c2a-33ace65935e7','ستراسبورج يفوز على نظيره لانس ضمن منافسات الجولة الثانية من الدوري الفرنسي','ستراسبورج يفوز علي نظيره لانس ضمن منافسات الجوله الثانيه من الدوري الفرنسي','تغلب فريق ستراسبورج على ضيفه لانس بنتيجة 2 - 1، بعدما كان متأخرًا بهدف ليحقق فوزه الأول هذا الموسم، وذلك ضمن منافسات الجولة الثانية من الدوري الفرنسي.','["وخلال المباراة تقدم فريق لانس من خلال ركلة جزاء، وأدرك نظيره ستراسبورج التعادل وخطف نقاط الفوز بفضل ثنائية للاعبه المغربي ياسين جسيم في الدقيقتين 48 و85.","وبهذه النتيجة يحقق ستراسبورج فوزه الأول تحت قيادة مدربه الجديد هوجو أوليفيرا، ليرفع رصيده إلى 3 نقاط، ويتجاوز كبوة الخسارة الثقيلة أمام أولمبيك مارسيليا بنتيجة 0 - 4 في الجولة الأولى.","وسيحل ستراسبورج ضيفًا على تروا ، يوم 6 سبتمبر ضمن منافسات الجولة الثالثة.","أما لانس بقيادة مدربه الألماني دينو توبمولر، فقد تجمد رصيده عند 3 نقاط بعد فوز عريض على أوكسير بنتيجة 5 - 2 في الجولة الأولى، وسيستقبل لوريان في الجولة الثالثة يوم السبت المقبل."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/03ixr7qc0','https://ajel.sa/sports/03ixr7qc0','https://ajel.sa/sports/03ixr7qc0','https://ajel.sa/sports/03ixr7qc0','فريق التحرير','','2026-08-29T15:44:00.000Z','Wed, 07 Oct 2026 19:34:47 GMT','2026-08-29T22:02:51.670Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/Capture-crop-hKxTl9nC.png','/api/media/3f829cd6-443e-4806-9c2a-33ace65935e7','/api/media/3f829cd6-443e-4806-9c2a-33ace65935e7?variant=thumbnail','ستراسبورج يفوز على نظيره لانس ضمن منافسات الجولة الثانية من الدوري الفرنسي',1200,675,'valid','published','archived','valid',41,'1efde282aa0077dc03bf12ad497325053b6ee52b8e0a79a0690b21773365ae74','8712aec3e23df6ad6562d2ada226367f928e8b064cad0732f0df346e997a95f3','محدّث','2026-08-29T22:02:51.670Z','2026-10-07T20:24:32.368Z','','',0,0,'gulf_arab','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:34:48.986Z',200,52,0,'source_content_changed','',NULL,NULL,'body:e0944a45c357ee52b803071204959dd709cb349812610fec61910439a76078f6','Wed, 07 Oct 2026 19:34:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7a16e88d-495d-4777-a45e-6b348c1128a9','news-7a16e88d-495d-4777-a45e-6b348c1128a9','معهد الإدارة العامة يطلق برامج دبلوم عالٍ في التخصصات العقارية واللوجستية والقانونية','معهد الاداره العامه يطلق برامج دبلوم عال في التخصصات العقاريه واللوجستيه والقانونيه','أطلق معهد الإدارة العامة، ممثلًا في مركز الأعمال، عددًا من برامج الدبلوم العالي في تخصصات نوعية متعددة، في إطار سلسلة فعاليات استقبال الدارسين والدارسات التي شهدها المعهد خلال الأسبوع الجاري.','["وتشمل البرامج المُطلقة الدبلوم العالي في الأنظمة والتشريعات العقارية، الذي يُقدَّم بالشراكة مع المعهد العقاري السعودي، ويستهدف تطوير كفاءات تجمع بين المعرفة النظامية والفهم المهني لمتطلبات القطاع العقاري.","كما يشمل الدبلوم العالي في إدارة سلاسل الإمداد واللوجستيات، بالشراكة مع الأكاديمية السعودية اللوجستية، الذي يركز على تنمية المهارات المتخصصة وتعزيز كفاءة الأداء في القطاع اللوجستي.","ويواصل المعهد تقديم الدبلوم العالي لإدارة الأعمال التنفيذي في نسخته الثالثة، الرامي إلى تنمية القدرات الإدارية والقيادية وتعزيز معارف الدارسين في مجالات التخطيط الاستراتيجي، والتحليل المالي، وإدارة المخاطر، والحوكمة، بما يسهم في رفع كفاءة المنظمات وتحسين أدائها.","وامتدادًا لذلك، أُطلق مطلع الأسبوع الدبلوم العالي لإدارة المنظمات غير الربحية، بالشراكة مع مؤسسة السبيعي الخيرية وبدعم من المركز الوطني لتنمية القطاع غير الربحي، بهدف تأهيل الكفاءات المتخصصة في هذا القطاع ورفع كفاءة ممارساته.","كما شهد الأسبوع استقبال الدارسين في الدبلوم العالي للعلوم القانونية.","ويحرص المعهد على تنويع أنماط الدراسة بما يتناسب مع احتياجات الفئات المستهدفة؛ إذ تُقدَّم بعض البرامج خلال نهاية الأسبوع لإتاحة الفرصة للموظفين لمواصلة تطويرهم دون تعارض مع التزاماتهم الوظيفية، فيما تُقدَّم برامج أخرى خلال أيام الأسبوع، وذلك دعمًا لمستهدفات رؤية السعودية 2030 في تنمية القدرات البشرية.","وأكد الرئيس التنفيذي لمركز الأعمال، الأستاذ محمد بن خالد العقل، أن «الاستثمار في الإنسان يمثل أساس التنمية، وأن البرامج التدريبية والتأهيلية المتخصصة تُعدّ من أهم أدوات بناء القدرات الوطنية ورفع جاهزيتها وتمكينها من مواكبة المتغيرات والاستجابة لمتطلبات المستقبل».","وتضمّنت فعاليات الاستقبال تعريف الدارسين بالجوانب التنظيمية والتدريبية والخدمات المقدمة لهم، إيذانًا بانطلاق رحلتهم في برامج الدبلوم العالي."]','العقارات','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/MSpViqo','https://sabq.org/article/MSpViqo','','https://sabq.org/article/MSpViqo','سعود الدعجاني ','','2026-08-29T15:58:00.000Z','2026-08-29T18:58:00.000Z','2026-08-29T22:02:54.581Z','https://media.sabq.org/news/2026/08/bcdee122-cb09-49db-9d8e-c794500ad72e/w1280.webp','/api/media/7a16e88d-495d-4777-a45e-6b348c1128a9','/api/media/7a16e88d-495d-4777-a45e-6b348c1128a9?variant=thumbnail','معهد الإدارة العامة يطلق برامج دبلوم عالٍ في التخصصات العقارية واللوجستية والقانونية',1280,854,'valid','published','archived','valid',40,'95f3973d993b050c42772707f21d6645cfaf02f74bbc6c3b36bff505bc1e9e47','7da94d3864857802b2ba5192008959fef1039c54d113bbe2ebb90022ba12b2ef','محدّث','2026-08-29T22:02:54.581Z','2026-10-07T20:24:32.373Z','','',0,0,'saudi_national','أولوية قصوى',82,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق"]','["الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:33:56.117Z',200,54,0,'source_article_available','',NULL,NULL,'body:be29c2e620cb349c9a25f58284d7963e5740db6b96842ab0f36fc7e3f3cceb26','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fbd8c778-91b4-42d3-9421-460f3567aa49','news-fbd8c778-91b4-42d3-9421-460f3567aa49','“Our Cities Cheer for Our National Team” Draws Widespread Public Engagement at Municipal Squares and Parks in Support of the Green Falcons at the 2026 World Cup','our cities cheer for our national team draws widespread public engagement at municipal squares and parks in support of the green falcons at the 2026 world cup','The initiative enabled fans to watch the match between the Saudi national team and Uruguay as part of the 2026 FIFA World Cup at fully equipped public viewing sites.','["Public squares, parks, and municipal waterfronts prepared by regional municipalities and their affiliated municipalities across the Kingdom witnessed widespread public engagement with the launch of the Ministry of Municipalities and Housing’s “Our Cities Cheer for Our National Team” initiative. The initiative enabled fans to watch the match between the Saudi national team and Uruguay as part of the 2026 FIFA World Cup at fully equipped public viewing sites.","The viewing sites were filled with families, young people, children, and visitors who gathered to support the Green Falcons and share moments of excitement and cheering in a distinctive patriotic atmosphere. The scenes reflected the strong support for the Saudi national team, as well as the sense of pride and belonging shared by citizens and residents across the Kingdom.","The initiative forms part of the Ministry of Municipalities and Housing’s efforts to activate public squares, parks, and waterfronts as vibrant community destinations by allocating and equipping public viewing sites across the Kingdom’s regions, cities, and governorates. This enables residents to follow the national team’s matches close to their homes while enjoying the tournament atmosphere in safe and welcoming environments.","The public viewing sites designated by municipalities across the Kingdom will remain available throughout the Saudi national team’s participation in the 2026 FIFA World Cup, allowing fans to follow the Green Falcons’ matches in a distinctive patriotic atmosphere that reflects the spirit of excitement and support and brings members of the community together in a shared experience of backing the national team.","The Ministry of Municipalities and Housing explained that the “Our Cities Cheer for Our National Team” initiative aims to strengthen community participation in supporting the Green Falcons by activating public squares, parks, and waterfronts as community destinations that host national events. The initiative also contributes to enriching the experiences of residents and visitors and maximizing the use of public facilities across the Kingdom’s cities and governorates.","Municipalities and regional authorities are continuing to implement their operational and service plans at the public viewing sites to ensure a comfortable and safe experience for visitors, while strengthening the role of public facilities as community spaces that bring residents together and accommodate various national occasions and events.","The “Our Cities Cheer for Our National Team” initiative represents an extension of the Ministry of Municipalities and Housing’s efforts to enhance quality of life and activate public destinations and municipal squares as centers for community engagement. It further reinforces their role as attractive destinations that host national experiences and keep pace with major events that capture the community’s interest.","Public squares, parks, and municipal waterfronts prepared by regional municipalities and their affiliated municipalities across the"]','أخبار السعودية','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/en/news/our-cities-cheer-our-national','https://momah.gov.sa/en/news/our-cities-cheer-our-national','','https://momah.gov.sa/en/news/our-cities-cheer-our-national','','','2026-08-31T00:47:00.000Z','Sun, 06 Sep 2026 23:02:46 GMT','2026-09-03T20:28:45.070Z','','','','“Our Cities Cheer for Our National Team” Draws Widespread Public Engagement at Municipal Squares and Parks in Support of the Green Falcons at the 2026 World Cup',NULL,NULL,'no_article_image_candidates','rejected','rejected','invalid',35,'c476d7f24a74f08160ce27b50b388a82879670e485d6749b8371a5c017f2387c','ee798ff3b145d322719d452d03d7c4335c6b82411cfe7e9096944bf30d5d41e4',NULL,'2026-09-03T20:28:45.070Z','2026-10-07T18:20:32.476Z','','',0,0,'international','عادي',38,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-09-07T05:15:28.183Z',304,70,0,'source_article_available','',NULL,NULL,'"1788735766"','Sun, 06 Sep 2026 23:02:46 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('60fff2b8-130e-4f49-b62b-35770759b70b','news-60fff2b8-130e-4f49-b62b-35770759b70b','برعاية وزارة البلديات والإسكان.. انطلاق النسخة الخامسة من "سيريدو 2026" في جدة الأحد المقبل','برعايه وزاره البلديات والاسكان انطلاق النسخه الخامسه من سيريدو 2026 في جده الاحد المقبل','ويتضمن "سيريدو 2026" برنامجًا مصاحبًا من ورش العمل والجلسات الحوارية، بمشاركة عدد من الخبراء والمختصين، لمناقشة مستجدات السوق العقاري السعودي، والفرص الاستثمارية والتطويرية، وأبرز الموضوعات المرتبطة بنمو القطاع وتطوره.','["تنطلق الأحد المقبل في محافظة جدة أعمال النسخة الخامسة من المعرض السعودي للتطوير والتمليك العقاري \"سيريدو 2026\"، برعاية وزارة البلديات والإسكان، وذلك خلال الفترة من 6 إلى 8 سبتمبر 2026 في \"جدة سوبر دوم\"، بمشاركة عدد من الجهات الحكومية والمطورين العقاريين والمستثمرين والجهات التمويلية والمهتمين بالقطاع العقاري.","ويجمع المعرض نخبة من المطورين العقاريين والمستثمرين والجهات التمويلية وذات العلاقة، لعرض المشاريع والفرص المتاحة في مجالات التطوير والتملك والاستثمار العقاري، والتعريف بالحلول والخدمات المرتبطة بالسوق العقاري.","وتشهد النسخة الخامسة مشاركة دولية تتضمن حضور عدد من الجهات والشركات والمستثمرين، بما يتيح فرصًا للتواصل وبحث آفاق التعاون والشراكات وتبادل الخبرات بين مختلف أطراف القطاع العقاري.","وتأتي إقامة النسخة الخامسة من \"سيريدو 2026\" في ظل ما يشهده القطاع العقاري في المملكة من نمو وتوسع في المشاريع والفرص الاستثمارية، بالتزامن مع البرامج والمبادرات المنبثقة عن مستهدفات رؤية السعودية 2030، بما يعزز دور القطاع في التنمية الاقتصادية والعمرانية، ويدعم نمو سوق عقاري أكثر حيوية وتنافسية.","وزارة البلديات والإسكان تعتمد الاشتراطات البلدية لمراكز البيانات التجارية.. لتعزيز جاهزية البنية التحتية الرقمية","اعتمدت وزارة البلديات والإسكان الاشتراطات البلدية لمراكز البيانات التجارية، في خطوة تهدف إلى&nbsp;تعزيز جاهزية البنية","\"البلديات والإسكان\" تحقق أكثر من 3 ملايين ساعة تطوعية بمشاركة 179 ألف متطوع خلال النصف الأول من 2026","حققت منظومة البلديات والإسكان أكثر من 3 ملايين ساعة تطوعية خلال النصف الأول من عام 2026، بمشاركة أكثر من 179 ألف متطوع"]','العقارات','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/ar/news/brayt-wzart-albldyat-walaskan','https://momah.gov.sa/ar/news/brayt-wzart-albldyat-walaskan','','https://momah.gov.sa/ar/news/brayt-wzart-albldyat-walaskan','','مكة المكرمة','2026-09-03T02:25:00.000Z','Wed, 07 Oct 2026 13:09:34 GMT','2026-09-06T15:12:24.341Z','','','','برعاية وزارة البلديات والإسكان.. انطلاق النسخة الخامسة من "سيريدو 2026" في جدة الأحد المقبل',NULL,NULL,'no_article_image_candidates','published','archived','valid',99,'a1161372dc737a062a06296205e5ea97f856b461a769769b264b310255a39f3f','907e4ca4794b1ab531bb0ddbb4c7fc5391b4c3e14984eb22b2d29bc6dacdfea4','محدّث','2026-09-03T20:28:48.213Z','2026-10-07T19:44:47.104Z','','',0,0,'saudi_region','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","التقنية والتحول الرقمي","جدة"]','["الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"المناطق","score":8.5},{"category":"الاقتصاد","score":5.5},{"category":"المجتمع","score":4.5}]','Updated','2026-10-07T19:44:47.104Z',200,73,0,'source_content_changed','',NULL,NULL,'"1791378574"','Wed, 07 Oct 2026 13:09:34 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e773f805-ed31-47e0-82e5-59bc74ec91ed','news-e773f805-ed31-47e0-82e5-59bc74ec91ed','وزارة البلديات والإسكان: طرح أكثر من 9700 قطعة أرض منذ بداية العام وحتى نهاية أغسطس','وزاره البلديات والاسكان طرح اكثر من 9700 قطعه ارض منذ بدايه العام وحتي نهايه اغسطس','أعلنت وزارة البلديات والإسكان طرح أكثر من 9700 قطعة أرض سكنية عبر منصة "سكني" منذ بداية عام 2026 وحتى نهاية أغسطس، استمرارًا لجهودها في زيادة المعروض السكني وتوسيع الخيارات المتاحة أمام الأسر السعودية في مختلف مناطق المملكة.','["وأوضحت الوزارة أن إجمالي ما تم طرحه خلال الفترة بلغ 9733 قطعة أرض ضمن 54 مخططًا سكنيًا، امتدادًا لجهودها في إتاحة الأراضي السكنية وتوفير خيارات متنوعة تواكب الاحتياج والنمو العمراني في المدن والمحافظات.","وبيّنت أن منطقة الرياض تصدرت المناطق من حيث عدد القطع المطروحة بـ 2322 قطعة، تلتها منطقة القصيم بـ 2303 قطع، ثم منطقة حائل بـ 1369 قطعة، فيما جاءت منطقة مكة المكرمة بـ 1227 قطعة، لتشكل هذه المناطق الأربع جانبًا رئيسًا من الأراضي السكنية التي أُتيحت عبر المنصة خلال الفترة، مشيرة إلى أن شهر مايو سجل أعلى حجم للطرح منذ بداية العام بإتاحة 2002 قطعة أرض، يليه يوليو بـ 1830 قطعة، ثم أغسطس بـ 1755 قطعة، فيما شهد فبراير طرح 1549 قطعة.","وأكدت الوزارة أن طرح الأراضي السكنية يأتي ضمن منظومة متكاملة تستهدف تعزيز المعروض السكني وتوسيع نطاق الخيارات المتاحة أمام المستفيدين، إلى جانب المنتجات والحلول السكنية والتمويلية التي توفرها منصة \"سكني\"، بما يدعم الأسر في اختيار الحلول الملائمة لاحتياجاتها وإمكاناتها.","وأشارت إلى أن التوسع في إتاحة الأراضي السكنية يواكب جهود الوزارة في دعم التنمية العمرانية والاستفادة من الأراضي المتاحة وتوفير بيئات سكنية تلبي احتياجات السكان، مع استمرار العمل على تنويع الخيارات السكنية في مدن ومحافظات المملكة.","وتواصل وزارة البلديات والإسكان جهودها لتحقيق مستهدفات برنامج الإسكان - أحد برامج رؤية السعودية 2030 - ورفع نسبة التملك السكني، فيما يمكن للمستفيدين الاطلاع على الأراضي والمخططات والخيارات المتاحة من خلال منصة وتطبيق \"سكني\".","وزارة البلديات والإسكان تعتمد الاشتراطات البلدية لمراكز البيانات التجارية.. لتعزيز جاهزية البنية التحتية الرقمية","اعتمدت وزارة البلديات والإسكان الاشتراطات البلدية لمراكز البيانات التجارية، في خطوة تهدف إلى&nbsp;تعزيز جاهزية البنية","\"البلديات والإسكان\" تحقق أكثر من 3 ملايين ساعة تطوعية بمشاركة 179 ألف متطوع خلال النصف الأول من 2026"]','العقارات','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-trh-0','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-trh-0','','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-trh-0','','الرياض','2026-09-03T02:23:00.000Z','Wed, 07 Oct 2026 13:22:56 GMT','2026-09-06T17:50:35.770Z','','','','وزارة البلديات والإسكان: طرح أكثر من 9700 قطعة أرض منذ بداية العام وحتى نهاية أغسطس',NULL,NULL,'no_article_image_candidates','published','archived','valid',99,'7f1b7af0e7fcdcddf950c855667a620ea5a0c0ed1d003c6c5682d2c40eff363f','add94b96bfdbd48bd827a66e17e14765eb7c5c385f30ffd9c635a68df8c3fa6d','محدّث','2026-09-03T20:28:48.512Z','2026-10-07T19:44:45.992Z','','',0,0,'saudi_region','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس ا من الأراضي السكنية","التقنية والتحول الرقمي","مكة","جدة","الرياض","القصيم"]','["رئيس ا من الأراضي السكنية","التقنية والتحول الرقمي"]','classified','','[{"category":"المناطق","score":11.5},{"category":"المجتمع","score":4.5},{"category":"أخبار السعودية","score":3}]','Updated','2026-10-07T19:44:45.992Z',200,73,0,'source_content_changed','',NULL,NULL,'"1791379376"','Wed, 07 Oct 2026 13:22:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('18d6972f-f0ac-47f0-9a05-057c32305560','news-18d6972f-f0ac-47f0-9a05-057c32305560','وزارة البلديات والإسكان: 7 ملايين متر مربع من الأراضي البيضاء في منطقة عسير دخلت مسارات التطوير','وزاره البلديات والاسكان 7 ملايين متر مربع من الاراضي البيضاء في منطقه عسير دخلت مسارات التطوير','وأوضحت الوزارة أن المساحات شملت 1.5 مليون متر مربع من الأراضي التي تم تطويرها، إلى جانب 5.5 ملايين متر مربع من الأراضي قيد التطوير، ما يعزز الاستفادة من الأراضي غير المطورة ويدعم زيادة المعروض العقاري والسكني في المنطقة.','["كشفت وزارة البلديات والإسكان أن إجمالي مساحات الأراضي البيضاء التي دخلت مسارات التطوير في منطقة عسير بلغ 7 ملايين متر مربع، ضمن نتائج تطبيق نظام رسوم الأراضي البيضاء والعقارات الشاغرة الهادفة إلى تحفيز تطوير الأراضي ورفع كفاءة استخدامها داخل النطاقات الحضرية.","وبيّنت أن إيرادات رسوم الأراضي البيضاء أسهمت في دعم 17 مشروعًا في منطقة عسير، ضمن توجيه عوائد الرسوم لدعم البنية التحتية للمشاريع السكنية وتعزيز التنمية العمرانية في المنطقة.","وأكدت الوزارة أن هذه النتائج تأتي امتدادًا لجهودها في تحفيز ملاك الأراضي على التطوير، وزيادة كفاءة استثمار الأراضي داخل المدن، ودعم التوازن بين العرض والطلب، إلى جانب تعزيز المعروض من المنتجات العمرانية والسكنية.","وأشارت إلى أن برنامج رسوم الأراضي البيضاء والعقارات الشاغرة يواصل دوره في تحفيز التطوير من خلال تطبيق الرسوم على الأراضي الواقعة ضمن النطاقات الجغرافية المحددة نظامًا، مع إتاحة المهل النظامية للمكلفين الجادين في تطوير أراضيهم وفق الضوابط المعتمدة.","وأضافت أن مركز خدمات المطورين العقاريين \"إتمام\" يواصل دعم ملاك الأراضي والمطورين عبر منظومة رقمية تضم أكثر من 35 خدمة تغطي مختلف مراحل التطوير، وتسهل إجراءات التراخيص والموافقات والتنسيق مع الجهات ذات العلاقة، بما يسرّع تنفيذ المشاريع داخل النطاقات العمرانية.","وتواصل وزارة البلديات والإسكان العمل على تعزيز التكامل بين تطبيق الرسوم وتمكين الملاك من الخدمات التطويرية، لرفع كفاءة استخدام الأراضي وتسريع تنميتها وزيادة المعروض العقاري والسكني، انسجامًا مع مستهدفات رؤية السعودية 2030.","وكانت الوزارة قد كشفت في وقت سابق عن نتائج تطبيق رسوم الأراضي البيضاء والعقارات الشاغرة في عدد من مناطق المملكة، حيث بلغ إجمالي مساحات الأراضي التي دخلت التطوير أو التداول نحو 279 مليون متر مربع، منها 146 مليون متر مربع في المنطقة الشرقية، و71 مليونًا في الرياض، و28 مليونًا في مكة المكرمة، و19 مليونًا في المدينة المنورة، و15 مليونًا في القصيم، فيما أسهمت إيرادات الرسوم في دعم 71 مشروعًا في هذه المناطق.","برعاية وزارة البلديات والإسكان.. انطلاق النسخة الخامسة من \"سيريدو 2026\" في جدة الأحد المقبل"]','العقارات','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-7-mlayyn','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-7-mlayyn','','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-7-mlayyn','','الرياض','2026-08-30T01:57:00.000Z','Wed, 07 Oct 2026 13:13:59 GMT','2026-09-03T20:28:48.549Z','','','','وزارة البلديات والإسكان: 7 ملايين متر مربع من الأراضي البيضاء في منطقة عسير دخلت مسارات التطوير',NULL,NULL,'no_article_image_candidates','published','archived','valid',99,'69ccb711e00ebc5dd0ea862f8077d6de15e008838917793cce1638d10a1ef4b4','5e96c2a4bfe30cc90e9e8c774baaddef7696d973efa19445e3d55447d197da7a',NULL,'2026-09-03T20:28:48.549Z','2026-10-07T19:45:16.250Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","التقنية والتحول الرقمي","مكة","جدة","عسير","الرياض","القصيم","المدينة المنورة"]','["الاقتصاد والأسواق","التقنية والتحول الرقمي","المدينة المنورة"]','classified','','[{"category":"المناطق","score":14.5},{"category":"الاقتصاد","score":5.5},{"category":"أخبار السعودية","score":3}]','Updated','2026-10-07T19:45:16.250Z',200,65,0,'source_content_changed','',NULL,NULL,'"1791378839"','Wed, 07 Oct 2026 13:13:59 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2e523bf5-5061-4a7b-aafb-81448c5612f1','news-2e523bf5-5061-4a7b-aafb-81448c5612f1','«حرف» تطلق مسابقة شعرية احتفاءً باليوم الوطني بجوائز تتجاوز 200 ألف ريال','حرف تطلق مسابقه شعريه احتفاء باليوم الوطني بجوائز تتجاوز 200 الف ريال','أعلن «مقهى حرف»، إطلاق مبادرة «حرف» الشعرية، تزامنًا مع احتفالات المملكة باليوم الوطني السعودي الـ96، إذ تتيح المجال أمام الشعراء للتعبير عن الانتماء والهوية الوطنية، بجوائز تتجاوز قيمتها الـ 200 ألف ريال.','["وتستقبل المسابقة المشاركات وتصويت الجمهور حتى منتصف ليل 23 سبتمبر، على أن تُعلن أسماء الفائزين وتُوزع الجوائز في 24 سبتمبر.","وبحسب منظمي المسابقة، يحصل الفائز بالمركز الأول على 100 ألف ريال، والثاني على 50 ألف ريال، والثالث على 25 ألف ريال، فيما خُصصت 25 ألف ريال جوائز للجمهور والمشاركين في التصويت.","وأوضح المشرف العام على المسابقة علي الحربي أن المبادرة تستهدف دعم المواهب الشعرية وإثراء الحراك الأدبي، وإتاحة مساحة للمبدعين للتعبير عن مشاعرهم تجاه الوطن من خلال القصيدة، مؤكدًا أن الشعر ظل حاضرًا في توثيق المناسبات الوطنية وتجسيد قيم الانتماء والاعتزاز بالهوية والثقافة السعودية.","وأضاف الحربي أن تنوع المبادرات الثقافية يسهم في اكتشاف المواهب وتوسيع دائرة المشاركة المجتمعية في الأنشطة الأدبية، مشيرًا إلى ما يشهده القطاع الثقافي في المملكة من تطور، في ظل جهود وزارة الثقافة وهيئاتها المتخصصة في دعم مجالات الإبداع المختلفة.","وتعتمد نتائج المسابقة على تصويت الجمهور، مع السماح لكل شخص بالتصويت مرة واحدة للقصائد المشاركة، من خلال موقع «حرف» وتطبيقه المعتمد."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/6QxEbUX','https://sabq.org/article/6QxEbUX','','https://sabq.org/article/6QxEbUX','صحيفة سبق','','2026-09-03T13:13:00.000Z','2026-09-03T16:14:00.000Z','2026-09-03T20:30:35.261Z','https://media.sabq.org/news/2026/09/75f4997a-2ab9-44f4-a148-9b16b14bfe93/w736.webp','/api/media/2e523bf5-5061-4a7b-aafb-81448c5612f1','/api/media/2e523bf5-5061-4a7b-aafb-81448c5612f1?variant=thumbnail','«حرف» تطلق مسابقة شعرية احتفاءً باليوم الوطني بجوائز تتجاوز 200 ألف ريال',736,1600,'valid','published','archived','valid',46,'a592ffd7487d5602c0fe9e7b11865d51aceccd63e155d857ec445f0528b1bdf0','029fadc0e6e1ba66277229c920c95ac08694817b5f178a352f8934aa77d51545','محدّث','2026-09-03T20:30:35.262Z','2026-10-07T19:42:05.514Z','','',0,0,'saudi_national','مهم',81,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الثقافة وهيئاتها المتخصصة في","الثقافة والفنون"]','["وزارة الثقافة وهيئاتها المتخصصة في","الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"التقنية","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T19:42:05.514Z',200,58,0,'source_article_available','',NULL,NULL,'body:32a1bec013a9ff1553b442ba7589c57329e4dd5fefadf1ecfd0b18f4031399a8','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8afaa51c-bd0c-41b6-9e4f-3fcf5c559c26','news-8afaa51c-bd0c-41b6-9e4f-3fcf5c559c26','القادسية يعبر الدرعية بثنائية في افتتاح الجولة الخامسة من دوري روشن','القادسيه يعبر الدرعيه بثنائيه في افتتاح الجوله الخامسه من دوري روشن','حقق فريق القادسية فوزاً ثميناً على حساب مضيفه الدرعية بهدفين دون رد، مساء الخميس، على ملعب الأول بارك بالرياض، ضمن منافسات الجولة الخامسة من دوري روشن للمحترفين.','["سجّل ثنائية القادسية الإيطالي ماتيو ريتيغي عن طريق ركلة الجزاء، والأرجنتيني جوليان كينيونيس، في الدقيقتين 51 و58 من عمر المباراة.","وأكمل فريق الدرعية اللقاء بعشرة لاعبين، إثر طرد الإسباني أوسكار رودريغيز بالبطاقة الحمراء في الدقيقة 90+6 من الوقت بدلاً من الضائع.","وبهذه النتيجة يرتفع رصيد القادسية إلى 12 نقطة، محتلاً المركز الثالث في جدول ترتيب الدوري، فيما يتجمد رصيد الدرعية عند 7 نقاط في المركز السابع."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/QsQ4aNS','https://sabq.org/article/QsQ4aNS','','https://sabq.org/article/QsQ4aNS','صحيفة سبق','الرياض','2026-09-03T14:13:00.000Z','2026-09-03T17:13:00.000Z','2026-09-03T20:30:36.855Z','https://media.sabq.org/news/2026/09/ccc70031-85ce-4362-82eb-2f8587ac04d3/w1600.webp','/api/media/8afaa51c-bd0c-41b6-9e4f-3fcf5c559c26','/api/media/8afaa51c-bd0c-41b6-9e4f-3fcf5c559c26?variant=thumbnail','القادسية يعبر الدرعية بثنائية في افتتاح الجولة الخامسة من دوري روشن',1600,2000,'valid','published','archived','valid',99,'52812d84c47d5b17ee152b13849b0e2f12bcdf7845ce5a4323f03da5545afbfe','8c21c75aa5bc7308eab00da84678c3f4c39e2ca7d1da45e53a1fc61ea9c13374','محدّث','2026-09-03T20:30:36.855Z','2026-10-07T19:41:58.421Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الرياضة السعودية","الرياض"]','["الطاقة والنفط","الرياضة السعودية"]','classified','','[{"category":"المناطق","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T19:41:58.421Z',200,58,0,'source_article_available','',NULL,NULL,'body:f7770c5687f21288fb238b8afafbe6d72016836053bff4af3cd99a5e9a4f9c6d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d71499e0-0e83-4495-a724-b43713a91de9','news-d71499e0-0e83-4495-a724-b43713a91de9','فانس عن تسليح المعارضة في إيران: «كل الخيارات مطروحة.. لكن لن أفصح عنها»','فانس عن تسليح المعارضه في ايران كل الخيارات مطروحه لكن لن افصح عنها','أكد نائب الرئيس الأمريكي جيه دي فانس ، أن جميع الخيارات مطروحة بشأن تسليح المعارضة في إيران ، رافضًا الكشف عن طبيعة هذه الخيارات. وفي ما يتعلق بالمفاوضات مع طهران ، أكد نائب الرئيس الأمريكي أن الولايات المتحدة لن تتفاوض مع إيران حتى تتوقف عن استهداف السفن التجارية، مشددًا على استمرار الضغط الاقتصادي والعسكري على النظام الإيراني.','["أكد نائب الرئيس الأمريكي جيه دي فانس ، أن جميع الخيارات مطروحة بشأن تسليح المعارضة في إيران ، رافضًا الكشف عن طبيعة هذه الخيارات.","وقال فانس، ردًا على سؤال بشأن تسليح المعارضة الإيرانية: «كل الخيارات مطروحة لكن لن أفصح عنها».","وفي ما يتعلق بالمفاوضات مع طهران ، أكد نائب الرئيس الأمريكي أن الولايات المتحدة لن تتفاوض مع إيران حتى تتوقف عن استهداف السفن التجارية، مشددًا على استمرار الضغط الاقتصادي والعسكري على النظام الإيراني.","وأضاف أن لدى الولايات المتحدة «الكثير من الأدوات للضغط على النظام الإيراني»، مؤكدًا أن واشنطن ستواصل استخدام وسائل الضغط المتاحة لديها.","وأشار فانس إلى أن نحو 15 مليون برميل من النفط عبرت مضيق هرمز أمس، في الوقت الذي يستمر فيه الضغط الاقتصادي والعسكري على إيران.","وشدد نائب الرئيس الأمريكي على أن الولايات المتحدة لا تستهدف المدنيين في إيران على الإطلاق، قائلًا إن ذلك يختلف عن الحرس الثوري الإيراني ."]','السياسة','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/305skm22p','https://ajel.sa/international/305skm22p','https://ajel.sa/international/305skm22p','https://ajel.sa/international/305skm22p','فريق التحرير','','2026-09-03T14:06:00.000Z','Wed, 07 Oct 2026 19:42:07 GMT','2026-09-03T20:30:38.894Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-wivP5Jsi.jpg','/api/media/d71499e0-0e83-4495-a724-b43713a91de9','/api/media/d71499e0-0e83-4495-a724-b43713a91de9?variant=thumbnail','جيه دي فانس',1200,675,'valid','published','archived','valid',99,'26aafb248231608cc67b96c1973a9faebeb3f34a73d7939f079986eb6f855901','411e737eba2b7546478c7a8f2cbfff04b6b5d009a606c438482fa61783427f1a','محدّث','2026-09-03T20:30:38.894Z','2026-10-07T19:42:09.681Z','','',0,0,'international','عادي',39,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","الطاقة والنفط","الاقتصاد والأسواق","السياسة والعلاقات الدولية","إيران","الولايات المتحدة"]','["الطاقة والنفط","الاقتصاد والأسواق","السياسة والعلاقات الدولية","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:42:09.681Z',200,54,0,'source_content_changed','',NULL,NULL,'body:e3ac19b109d4032d804920ba51a2e6be078c989b9c90cfa348421372a42a4deb','Wed, 07 Oct 2026 19:42:07 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e39dd9cd-fa61-410d-b808-53b249f8b603','news-e39dd9cd-fa61-410d-b808-53b249f8b603','الدفاع المدني بالطائف يباشر حريقًا في منطقة جبلية وأعمال الإخماد مستمرة','الدفاع المدني بالطائف يباشر حريقا في منطقه جبليه واعمال الاخماد مستمره','وأوضحت المديرية العامة للدفاع المدني، عبر حسابها الرسمي على منصة «إكس»، أن فرق الدفاع المدني في محافظة الطائف باشرت مباشرة الحريق، مؤكدة استمرار أعمال الإخماد في موقع الحادث.','["باشرت فرق الدفاع المدني بمحافظة الطائف ، أعمال إخماد حريق اندلع في أشجار وأعشاب بمنطقة جبلية، فيما لا تزال عمليات السيطرة على النيران مستمرة."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/561mdo5ro','https://ajel.sa/local/561mdo5ro','https://ajel.sa/local/561mdo5ro','https://ajel.sa/local/561mdo5ro','فريق التحرير','عسير','2026-09-03T14:06:00.000Z','Wed, 07 Oct 2026 19:42:08 GMT','2026-09-03T20:30:43.325Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-1xH-OQx5.jpg','/api/media/e39dd9cd-fa61-410d-b808-53b249f8b603','/api/media/e39dd9cd-fa61-410d-b808-53b249f8b603?variant=thumbnail','الدفاع المدني',1200,675,'valid','published','archived','valid',41,'e57387a5e7ff65b9990f4788300b810c0afdc95f89e08b36e9cae03a85e8fec4','0f63c62b4201df5901a321696eb6b498c7f81dfd732aeedee70e9dcc3f82a189','محدّث','2026-09-03T20:30:43.325Z','2026-10-07T20:24:32.415Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["عسير"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:10.428Z',200,52,0,'source_content_changed','',NULL,NULL,'body:6035a3c803a96889af07ef72be3eb24164b8a1ae8b881134292475f584350e72','Wed, 07 Oct 2026 19:42:08 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9b8f2e98-5654-4fec-bab3-8e219fd0be49','news-9b8f2e98-5654-4fec-bab3-8e219fd0be49','«سمة» توقّع اتفاقات جديدة لتعزيز تكامل منظومة المعلومات الائتمانية خلال LEAP 2026','سمه توقع اتفاقات جديده لتعزيز تكامل منظومه المعلومات الائتمانيه خلال leap 2026','كما يأتي توقيع الاتفاقيات خلال LEAP 2026 متسقًا مع توجه «سمة» نحو تعزيز الشراكات الاستراتيجية، والاستفادة من التقنيات والقدرات الرقمية في تطوير منظومة المعلومات الائتمانية، وبناء تكامل أعمق بين البيانات والتقنية والقطاع المالي، بما يفتح آفاقًا جديدة للتعاون والابتكار وتطوير الحلول ذات القيمة المضافة.','["وقّعت الشركة السعودية للمعلومات الائتمانية «سمة»، على هامش مشاركتها في مؤتمر LEAP 2026، عددًا من اتفاقيات العضوية والخدمات ذات القيمة المضافة، امتدادًا لدورها في تطوير منظومة المعلومات الائتمانية في المملكة، وضمن توجهها نحو توسيع قاعدة أعضائها وتعزيز التكامل والشراكات الاستراتيجية مع مختلف أطراف المنظومة المالية والائتمانية.","وشملت الاتفاقيات الجديدة كلًا من شركة «نايلة للتمويل»، وشركة «موافقة الرقمية للاتصالات وتقنية المعلومات»، و«رينتلي»، بما يعزز مجالات التعاون وتبادل المعلومات، ويدعم تطوير خدمات وحلول ذات قيمة مضافة تسهم في رفع كفاءة الأعمال والقرارات الائتمانية.","وتعكس هذه الاتفاقيات توجه «سمة» نحو بناء منظومة أكثر شمولًا وترابطًا، تقوم على توسيع نطاق المشاركة في المعلومات الائتمانية وتعزيز جودتها وتكاملها، بما يدعم كفاءة القرارات الائتمانية، ويرفع فاعلية إدارة المخاطر، ويسهم في تعزيز موثوقية المنظومة واستدامتها.","وتنظر «سمة» إلى توسع قاعدة أعضائها بوصفه امتدادًا استراتيجيًا لدورها في المنظومة، وليس توسعًا كميًا فحسب؛ إذ يسهم انضمام أعضاء جدد في توسيع نطاق المعلومات وتعزيز شموليتها، ويدعم قدرة الشركة على تعظيم القيمة المستمدة من البيانات والمعلومات الائتمانية وتحويلها إلى معرفة وذكاء يدعمان قرارات أكثر دقة وكفاءة.","وفي هذا السياق، أكّد الرئيس التنفيذي لـ«سمة»، الأستاذ سلطان بن عبدالرحمن القديري، أن الاتفاقيات الجديدة تأتي ضمن توجه استراتيجي أوسع لتعزيز تكامل منظومة المعلومات الائتمانية وتوسيع الشراكات مع مختلف أطراف القطاع، مشيرًا إلى أن «سمة» تنظر إلى نمو قاعدة أعضائها باعتباره نموًا في قيمة المنظومة وأثرها، وليس في حجمها فحسب.","وأضاف: «نعدّ في سمة كل شراكة جديدة إضافة نوعية إلى قوة المنظومة بأكملها؛ فكلما اتسعت دائرة الشراكات، ازدادت شمولية المعلومات، وتعززت قدرتنا على تحويلها إلى معرفة وذكاء يدعمان قرارات أكثر دقة وكفاءة.","ومن هنا، فإن توسع منظومة أعضاء سمة لا يمثل نموًا في العدد بقدر ما يمثل نموًا في القيمة والأثر».","وأشار القديري إلى أنّ توسيع قاعدة الأعضاء يمثّل ركيزة أساسية في تعزيز شمولية منظومة المعلومات الائتمانية، مؤكدًا أن انضمام أعضاء جدد لا يُقاس بعدد الاتفاقيات، وإنما بالقيمة التي يضيفها كل عضو إلى المنظومة، وما ينتج عن ذلك من اتساع نطاق المعلومات وتنوعها وتعزيز قدرتها على دعم قرارات ائتمانية أكثر كفاءة."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wa9CIR6','https://sabq.org/article/wa9CIR6','','https://sabq.org/article/wa9CIR6','صحيفة سبق','','2026-09-03T13:14:00.000Z','2026-09-03T16:14:00.000Z','2026-09-03T20:30:45.448Z','https://media.sabq.org/news/2026/09/c8c9a960-8379-4287-b847-0adb8d95cefc/w1600.webp','/api/media/9b8f2e98-5654-4fec-bab3-8e219fd0be49','/api/media/9b8f2e98-5654-4fec-bab3-8e219fd0be49?variant=thumbnail','«سمة» توقّع اتفاقات جديدة لتعزيز تكامل منظومة المعلومات الائتمانية خلال LEAP 2026',1600,1067,'valid','published','archived','valid',86,'89d4ccd013ab92bfb8bb8cb2b44a2c342c3f985b61808525b7c72c0615b16b6f','380e6f467cb7d7f3316444363425d692d12b27e1b27bc62ba11bfbbad21e7b7b','محدّث','2026-09-03T20:30:45.448Z','2026-10-07T19:42:06.103Z','','',0,0,'saudi_national','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة نايلة للتمويل وشركة موافقة","التقنية والتحول الرقمي"]','["شركة نايلة للتمويل وشركة موافقة","التقنية والتحول الرقمي"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:42:06.103Z',200,50,0,'source_article_available','',NULL,NULL,'body:78c2dea05658993a87cb5778b718b28f12c410b8e2717283cf68cdf12ed48a19','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('105f8548-31a2-47a2-852b-ab30ff63a421','news-105f8548-31a2-47a2-852b-ab30ff63a421','العليمي يحذر الحوثيين: لا تخطئوا مجددًا في قراءة صبر الدولة وحرصها على حقن دماء اليمنيين','العليمي يحذر الحوثيين لا تخطئوا مجددا في قراءه صبر الدوله وحرصها علي حقن دماء اليمنيين','أكد رئيس مجلس القيادة الرئاسي اليمني، الدكتور رشاد محمد العليمي، أن التصعيد الحوثي في جبهات محافظة تعز لن يغير معادلة القوة والردع التي راكمتها القوات المسلحة ، مشددًا على أن هجمات المليشيات لن تحقق لها مكاسب جديدة على الأرض.','["وقال العليمي إن القوات المسلحة لن تتهاون في واجبها الدستوري بحماية المدنيين، مؤكدًا التزام الدولة بالرد الحازم على ما وصفها بـ«مغامرات المليشيات الإرهابية»، ومحذرًا الحوثيين من إساءة قراءة صبر الدولة وحرصها على حقن دماء اليمنيين.","وأضاف رئيس مجلس القيادة أن الشعب اليمني وقواته المسلحة أصبحا أكثر عزمًا على إسقاط الانقلاب واستعادة مؤسسات الدولة وحماية النظام الجمهوري وتحقيق الأمن والاستقرار.","وجاءت تصريحات العليمي خلال اتصالات هاتفية أجراها، اليوم الخميس، مع عضو مجلس القيادة الرئاسي الفريق الركن طارق صالح ، وعضو اللجنة العسكرية العليا اللواء الركن يوسف الشراجي، وقائد المنطقة العسكرية الرابعة اللواء حمدي شكري، وعدد من القادة العسكريين، للاطلاع على تطورات الموقف الميداني وسير العمليات في جبهات محافظة تعز.","واطمأن رئيس مجلس القيادة خلال الاتصالات على مستوى الجاهزية القتالية للقوات والروح المعنوية المرتفعة، وقدرتها على التعامل بكفاءة ومسؤولية مع التصعيد الحوثي وإفشال أهدافه ومخططاته في مختلف الجبهات.","وأشاد العليمي ببسالة القوات المسلحة وكافة التشكيلات العسكرية وثباتها وتضحياتها، مترحمًا على أرواح الشهداء ومتمنيًا الشفاء العاجل للجرحى والمصابين.","ووجّه في هذا السياق برعاية أسر الشهداء وضمان العلاج والرعاية الكاملة للجرحى والمصابين، والوفاء بحقوقهم ومستحقاتهم، مؤكدًا أن ذلك يمثل واجبًا وطنيًا ومسؤولية لا تقبل التهاون.","ودعا رئيس مجلس القيادة أبناء القبائل في مناطق سيطرة الحوثيين إلى عدم الزج بأبنائهم في حروب وصفها بالعبثية، محذرًا من تحويلهم إلى وقود لصراع لا يخدم اليمن ومصالح أبنائه."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/3sti3zaz8','https://ajel.sa/international/3sti3zaz8','https://ajel.sa/international/3sti3zaz8','https://ajel.sa/international/3sti3zaz8','فريق التحرير','المدينة المنورة','2026-09-03T14:06:00.000Z','Wed, 07 Oct 2026 19:42:16 GMT','2026-09-03T20:30:47.235Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-WPCTRpJL.png','/api/media/105f8548-31a2-47a2-852b-ab30ff63a421','/api/media/105f8548-31a2-47a2-852b-ab30ff63a421?variant=thumbnail','العليمي',1200,675,'valid','published','archived','valid',41,'113c5dd2025cc99a65ea6372097e7299eb17cfd064efd0002835429d047ac124','3000474f81c1abf7c752528b8856e3a5c5d3e5de4ad6685aa8226f92fd35ece4','محدّث','2026-09-03T20:30:47.235Z','2026-10-07T20:24:32.432Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس القيادة الرئاسي اليمني","مجلس القيادة الرئاسي اليمني الدكتور","الصحة العامة","اليمن","إيران"]','["رئيس مجلس القيادة الرئاسي اليمني","مجلس القيادة الرئاسي اليمني الدكتور","الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:18.380Z',200,49,0,'source_content_changed','',NULL,NULL,'body:d8ed9a45ea5e30ab14c0c7052de1aa11360c8dcaa0477b44a7e59056a48336be','Wed, 07 Oct 2026 19:42:16 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('400ba563-70c3-4574-a3ee-b7504e974415','news-400ba563-70c3-4574-a3ee-b7504e974415','محلل سياسي: مشاركة المملكة في ذكرى حركة عدم الانحياز تؤكد دعمها خفض التصعيد ونشر السلام','محلل سياسي مشاركه المملكه في ذكري حركه عدم الانحياز تؤكد دعمها خفض التصعيد ونشر السلام','وأكد الخريجي أن المملكة، منذ إسهامها في تأسيس حركة عدم الانحياز، حافظت على التزامها بمبادئها الراسخة، وفي مقدمتها صون سيادة الدول واستقلال قرارها الوطني ورفض استخدام القوة وسيلةً لتسوية الخلافات.','["أكد المحلل السياسي د. عبد المجيد الجلال أن مشاركة المملكة العربية السعودية في الذكرى الـ65 ل حركة عدم الانحياز تؤكد تمسكها بالمبادئ الأساسية للحركة، وفي مقدمتها رفض استخدام القوة، واحترام سيادة الدول واستقلال قرارها، ودعم خفض التصعيد ونشر السلام.","وأضاف الجلال عبر قناة «الإخبارية» أن حضور المملكة في هذه المناسبة يعكس استمرار التزامها بهذه المبادئ، في وقت تشهد فيه الساحة الدولية تحديات متصاعدة، فيما تبرز أهمية التمسك بالحوار والحلول السلمية ودعم الاستقرار.","وشارك نائب وزير الخارجية المهندس وليد بن عبدالكريم الخريجي، نيابةً عن ولي العهد رئيس مجلس الوزراء الأمير محمد بن سلمان بن عبدالعزيز آل سعود، في الاجتماع رفيع المستوى المنعقد في جمهورية صربيا بمناسبة الذكرى الـ65 للمؤتمر الأول لدول حركة عدم الانحياز.","وأشار إلى أن ذلك انعكس في السياسة الخارجية للمملكة، التي اعتمدت الحوار في إدارة القضايا الدولية، وعملت على توسيع علاقات التعاون، ودعم المسارات الكفيلة بتعزيز الأمن والسلم الدوليين.","وشدد نائب وزير الخارجية على أهمية استمرار التنسيق عبر الأمم المتحدة وحركة عدم الانحياز، بما يرسخ أولوية الحلول السياسية السلمية ويعزز الامتثال للقانون الدولي، بما في ذلك ضمان حرية الملاحة في الممرات البحرية الدولية التي أكد عليها قرار مجلس الأمن 2817.","وأوضح الخريجي أن غياب الحلول السياسية يتجلى بوضوح في منطقة الشرق الأوسط، جراء الجرائم المتواصلة التي يرتكبها الاحتلال الإسرائيلي في قطاع غزة وسائر الأراضي الفلسطينية المحتلة ، فضلًا عن الاعتداءات على أراضي الجمهورية العربية السورية، التي تمثل انتهاكًا صارخًا لحقوق الشعوب وسيادة الدول، وتدفع المنطقة نحو مزيد من التوتر وعدم الاستقرار.","وجدد تأكيد المملكة أن السلام هو الخيار الوحيد القادر على توفير الأمن الدائم لجميع دول المنطقة وشعوبها، مؤكدًا أن بلوغ هذا الهدف يستلزم الإسراع في التوصل إلى تسوية منصفة وشاملة ونهائية للقضية الفلسطينية."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/zjh3a277z','https://ajel.sa/local/zjh3a277z','https://ajel.sa/local/zjh3a277z','https://ajel.sa/local/zjh3a277z','فريق التحرير','','2026-09-03T13:28:00.000Z','Wed, 07 Oct 2026 19:42:08 GMT','2026-09-03T20:30:47.859Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-lQO_PDnq.jpg','/api/media/400ba563-70c3-4574-a3ee-b7504e974415','/api/media/400ba563-70c3-4574-a3ee-b7504e974415?variant=thumbnail','نائب وزير الخارجية يشارك في الاجتماع رفيع المستوى بمناسبة الذكرى الـ 65 للمؤتمر الأول لدول حركة عدم الانحياز',1200,675,'valid','published','archived','valid',98,'b90fcfd8d282c6d9b52083df8b0fc39774c414b92419e13c6dc08d7f0dde459b','2326bdb9acfed583e48970386829e780a8497c91eed2287d3afa617aefad366c','محدّث','2026-09-03T20:30:47.859Z','2026-10-07T19:42:10.455Z','','',0,0,'saudi_national','أولوية قصوى',82,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس الوزراء الأمير محمد بن","ولي العهد رئيس مجلس الوزراء","رئيس مجلس الوزراء الأمير محمد","وزير الخارجية المهندس وليد بن","الأمم المتحدة وحركة عدم الانحياز","السياسة والعلاقات الدولية","غزة","فلسطين"]','["مجلس الوزراء الأمير محمد بن","ولي العهد رئيس مجلس الوزراء","رئيس مجلس الوزراء الأمير محمد","وزير الخارجية المهندس وليد بن","الأمم المتحدة وحركة عدم الانحياز","السياسة والعلاقات الدولية"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:10.455Z',200,51,0,'source_content_changed','',NULL,NULL,'body:e9d16660461a31af42976cdc5ca811ab7c1dc5e89b1550e055c9468735151209','Wed, 07 Oct 2026 19:42:08 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5b9218ea-25ad-40a2-8485-c4f1067320e8','news-5b9218ea-25ad-40a2-8485-c4f1067320e8','الخلود يرفض الخسارة أمام الفيحاء ويلحق بالتعادل  في الوقت القاتل','الخلود يرفض الخساره امام الفيحاء ويلحق بالتعادل في الوقت القاتل','رفع التعادل رصيد الخلود إلى 9 نقاط، ليتربع في المركز الرابع مستمراً بلا هزيمة بعد خمس جولات. في المقابل، ارتفع رصيد الفيحاء إلى 5 نقاط، محتلاً المركز العاشر في جدول ترتيب الدوري.','["تعادل فريق الخلود إيجابياً مع مضيفه الفيحاء بنتيجة 2-2، مساء الخميس، في منافسات الجولة الخامسة من دوري روشن السعودي للمحترفين، على ملعب مدينة المجمعة الرياضية.","افتتح الفيحاء التسجيل عبر هوغو مورا في الدقيقة الخامسة، قبل أن يُعادل إيكير كورتاجارينا الميزان للخلود في الدقيقة 14.","وأعاد فاشيون ساكالا التقدم للفيحاء في الدقيقة 57، غير أن جوليان دومينغيش أنقذ الخلود بهدف التعادل القاتل في الدقيقة 89 من الشوط الثاني.","رفع التعادل رصيد الخلود إلى 9 نقاط، ليتربع في المركز الرابع مستمراً بلا هزيمة بعد خمس جولات.","في المقابل، ارتفع رصيد الفيحاء إلى 5 نقاط، محتلاً المركز العاشر في جدول ترتيب الدوري."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7qzc3qY','https://sabq.org/article/7qzc3qY','','https://sabq.org/article/7qzc3qY','صحيفة سبق','الرياض','2026-09-03T12:16:00.000Z','2026-09-03T15:16:00.000Z','2026-09-03T20:30:48.256Z','https://media.sabq.org/news/2026/09/9fcea019-bc38-4615-bf3c-03a3519ce68d/w1600.webp','/api/media/5b9218ea-25ad-40a2-8485-c4f1067320e8','/api/media/5b9218ea-25ad-40a2-8485-c4f1067320e8?variant=thumbnail','الخلود يرفض الخسارة أمام الفيحاء ويلحق بالتعادل  في الوقت القاتل',1600,1280,'valid','published','archived','valid',92,'798e2d045cc453b65195e815a65f386a79a483e7125ccb072aebdb9bbaf1bbc5','15b37cdc3e52cefc4be6bd0bea5acf55ab0f19ff992e0d524348603833e18f36','محدّث','2026-09-03T20:30:48.256Z','2026-10-07T19:42:11.876Z','','',0,0,'saudi_region','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','classified','','[{"category":"التقنية","score":2},{"category":"المناطق","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T19:42:11.876Z',200,49,0,'source_article_available','',NULL,NULL,'body:f0cb1a6c9d2f587258f0a3da739f21a64b184c1f1390773944cae7f50d93ec83','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4f3a685e-bcee-4a1b-9b0a-14385c5b28f6','news-4f3a685e-bcee-4a1b-9b0a-14385c5b28f6','الخلود يخطف تعادلًا قاتلًا من الفيحاء في دوري روشن','الخلود يخطف تعادلا قاتلا من الفيحاء في دوري روشن','خطف الخلود تعادلًا قاتلًا من مضيفه الفيحاء بنتيجة 2-2، بعدما سجل جوليان دومينغيش هدف التعادل في الدقيقة 89، مساء الخميس، ضمن منافسات الجولة الخامسة من دوري روشن السعودي للمحترفين، على ملعب مدينة المجمعة الرياضية .','["وتقدم الفيحاء مبكرًا عن طريق هوغو مورا في الدقيقة الخامسة، قبل أن يدرك إيكير كورتاجارينا التعادل للخلود بعد 9 دقائق.","واستعاد الفيحاء تقدمه في الدقيقة 57 بهدف فاشيون ساكالا ، وظل متقدمًا حتى الدقائق الأخيرة، قبل أن يتمكن دومينغيش من تعديل النتيجة للخلود في الدقيقة 89، لينتهي اللقاء بالتعادل الإيجابي.","ورفع الخلود رصيده إلى 9 نقاط، ليحتل المركز الرابع ويحافظ على سجله خاليًا من الهزائم بعد مرور خمس جولات، بينما وصل رصيد الفيحاء إلى 5 نقاط في المركز العاشر بجدول الترتيب."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/gsgxd8n97','https://ajel.sa/sports/gsgxd8n97','https://ajel.sa/sports/gsgxd8n97','https://ajel.sa/sports/gsgxd8n97','فريق التحرير','الرياض','2026-09-03T13:04:00.000Z','Wed, 07 Oct 2026 19:42:06 GMT','2026-09-03T20:30:48.309Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-6aZ4tYVS.jpg','/api/media/4f3a685e-bcee-4a1b-9b0a-14385c5b28f6','/api/media/4f3a685e-bcee-4a1b-9b0a-14385c5b28f6?variant=thumbnail','الخلود والفيحاء',1200,675,'valid','published','archived','valid',41,'f84409d95a256fe551ed555815d7f99ea1b9d3cf020761ff6f87a2344c8d83c3','7bc93d03bd541bea7a49c4389f1f604e28737f6df4edac59a0d727db2249e80a','محدّث','2026-09-03T20:30:48.309Z','2026-10-07T20:24:32.448Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:07.798Z',200,52,0,'source_content_changed','',NULL,NULL,'body:b0498e6fdc045cef919c88e62e0d6d5cfb87c1b7768d4edbcb3c35be4624feac','Wed, 07 Oct 2026 19:42:06 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f878fcff-4fa1-459d-9f58-9736553b93a6','news-f878fcff-4fa1-459d-9f58-9736553b93a6','سياحة وترفيه / انطلاق فعاليات "واحة مسرح الطفل" بعنيزة بأربعة عروض مسرحية','سياحه وترفيه انطلاق فعاليات واحه مسرح الطفل بعنيزه باربعه عروض مسرحيه','وتقدم الواحة تجربة مسرحية وترفيهية موجهة للأطفال والعائلات، من خلال أربعة عروض مسرحية متنوعة، في أجواء تسهم في إثراء تجربة الطفل الفنية وتعزيز تفاعله مع الفنون المسرحية.','["عنيزة 21 ربيع الأول 1448 هـ الموافق 03 سبتمبر 2026 م واس انطلقت أمس فعاليات \"واحة مسرح الطفل\" في حايط حركان بمحافظة عنيزة، التي تنفذها جمعية المسرح بعنيزة، وتستمر حتى 7 سبتمبر 2026م.","وتأتي \"واحة مسرح الطفل\" ضمن الفعاليات الثقافية والفنية التي تحتضنها محافظة عنيزة، بهدف تقديم محتوى مسرحي نوعي يناسب الطفل والأسرة، وتعريف الأطفال بأشكال متعددة من الفنون المسرحية في قالب ترفيهي جاذب.","وتستقبل الواحة زوارها يوميًا من الساعة الخامسة مساءً حتى العاشرة مساءً، وتقدم تجربة مسرحية وترفيهية موجهة للأطفال والعائلات، عبر أربعة عروض متنوعة تجمع بين المسرح الغنائي ومسرح الماريونيت ومسرح الشارع، بهدف إثراء تجربة الطفل الفنية وتعزيز حضور المسرح بوصفه مساحة للمتعة والخيال والتفاعل. // انتهى // 20:47 ت مـ 0257"]','الثقافة','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2668584?type=news&uuid=N2668584','https://spa.gov.sa/ar/N2668584?type=news&uuid=N2668584','N2668584','N2668584','','القصيم','2026-09-03T14:47:00.000Z','2026-07-20T18:09:00.000Z','2026-09-04T09:15:14.473Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10725908.jpeg','/api/media/f878fcff-4fa1-459d-9f58-9736553b93a6','/api/media/f878fcff-4fa1-459d-9f58-9736553b93a6?variant=thumbnail','سياحة وترفيه / انطلاق فعاليات "واحة مسرح الطفل" بعنيزة بأربعة عروض مسرحية',1600,967,'valid','published','archived','valid',48,'98cef6bfddc998a3204ff754f72fd5654b0a405bc6bbf1d147f2a42a1baaeb55','ecb97dadaebdb056f26e7c06cfa8be0f31f444a5218ec0236d6cc140a09b712b','محدّث','2026-09-03T20:30:48.332Z','2026-10-07T20:24:32.454Z','','',0,0,'saudi_region','مهم',70,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الثقافة والفنون"]','["السفر والسياحة","الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T19:42:38.700Z',200,49,0,'source_article_available','',NULL,NULL,'body:5a304745ce41c11e470f53dce9b682fe744b09660ff9a082b7fe94924b9e220d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('97ab2f40-7795-454c-ae24-8fd30bb949fe','news-97ab2f40-7795-454c-ae24-8fd30bb949fe','«سمك لبن تمر هندي»','سمك لبن تمر هندي','سمك لبن تمر هندي، ربما لا يوجد مثل شعبي أكثر قدرة على اختصار المشهد الذي يراه كثير من الجماهير في سوق الانتقالات، حين تختلف المعايير بين أندية يُفترض أنها تنتمي إلى مشروع استثماري واحد، بينما تتباين قدرتها على الاحتفاظ بالنجوم وتعويض المغادرين واستقطاب الأسماء الكبرى.','["القضية ليست حرباً على الهلال ولا اعتراضاً على نجاحه في استقطاب النجوم. بل العكس، وجود فريق بهذه القوة يرفع سقف المنافسة، شريطة أن تكون لدى الآخرين الأدوات نفسها التي تسمح لهم بمنافسته، ومن الظلم مطالبة الهلال بأن يتراجع أو يضعف حتى يلحق به الآخرون.","الهلال يبحث عن مصلحته، ومن الطبيعي أن يستثمر كل فرصة متاحة لبناء الفريق الأقوى، لكن السؤال الذي يفرض نفسه: هل الفرص المتاحة للجميع متكافئة أصلاً؟","نرى الهلال قادراً على إبرام صفقات ضخمة والاستغناء عن أسماء كبيرة، ثم العودة إلى السوق بحثاً عن أسماء أخرى من الصف الأول، بينما تشاهد جماهير الأندية المنافسة خروج نجوم من فرقها، ثم تنتظر التعويض، فإذا بالبديل في بعض الحالات أقل جودة فنية من اللاعب الذي غادر.","هنا يصبح السؤال أكبر من صفقة ولاعب ونادٍ، بل: كيف تستقيم عدالة المنافسة؟","يزداد الجدل عندما تُنسب بعض صفقات الهلال الكبرى إعلامياً أو جماهيرياً إلى دعم عضو شرف، قبل الاستحواذ، خاصة بعد أن تضاربت البيانات، لتزيد الأمر غموضاً، لذلك لا ينبغي أن يكون النقاش حول حق أي شخصية شرفية في دعم ناديها، وإنما حول كيفية تعامل اللوائح المالية مع هذا النوع من الدعم، إن حدث.","إذا كانت هناك صفقة بمبلغ ضخم يمولها داعم أو عضو شرف أو جهة مرتبطة بالنادي، كما يقال، فهل تدخل قيمتها كاملة ضمن مصروفات النادي والتزاماته؟ وكيف تُسجل محاسبياً؟ وهل تخضع للقواعد نفسها التي يخضع لها نادٍ آخر عندما يريد شراء لاعب بالقيمة ذاتها من ميزانيته؟","هذه الأسئلة تحتاج إلى إجابات معلنة وشفافة، ولا تحتاج إلى بيانات إنشائية ومتضاربة وفقيرة حسابياً.","فاللعب المالي النظيف يفقد معناه إذا أصبح بالإمكان، نظرياً، تجاوز القيود المالية بمجرد نقل فاتورة الصفقة من حساب النادي إلى داعم خارجي، ثم اعتبار الأمر منفصلاً عن القوة المالية الحقيقية للفريق."]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264100','https://www.okaz.com.sa/articles/authors/2264100','','https://www.okaz.com.sa/articles/authors/2264100','خالد سيف','','2026-09-02T18:00:00.000Z','Wed, 07 Oct 2026 19:43:55 GMT','2026-09-03T20:30:48.363Z','https://www.okaz.com.sa/uploads/authors/1612.jpg','/api/media/97ab2f40-7795-454c-ae24-8fd30bb949fe','/api/media/97ab2f40-7795-454c-ae24-8fd30bb949fe?variant=thumbnail','«سمك لبن تمر هندي»',400,400,'valid','published','archived','valid',50,'4c739af5db6084adc412ef02837739458e079b6870860b6250067041cf0f6ccf','7527e39cbb1c6b23ec8ae8b401e6020ee7b01e55961af884179d381f2ba536b0','محدّث','2026-09-03T20:30:48.363Z','2026-10-07T20:24:32.459Z','','',0,0,'gulf_arab','عادي',49,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الاقتصاد والأسواق"]','["الرياضة السعودية","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Updated','2026-10-07T19:43:57.761Z',200,65,0,'source_content_changed','',NULL,NULL,'body:cc87d0aaa6f6c3c0150948dfd0313594fdaa4bc54eb46897921b021bfa375648','Wed, 07 Oct 2026 19:43:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('153578fa-0371-4e08-bc98-12ba570ca5e1','news-153578fa-0371-4e08-bc98-12ba570ca5e1','ثقافي / جامعة الملك فيصل تفتتح قاعة المخطوطات والكتب النادرة','ثقافي جامعه الملك فيصل تفتتح قاعه المخطوطات والكتب النادره','الأحساء 21 ربيع الأول 1448 هـ الموافق 03 سبتمبر 2026 م واس افتتحت جامعة الملك فيصل اليوم قاعة المخطوطات والكتب النادرة، بحضور عدد من الباحثين والمختصين بالمقتنيات العلمية والتراثية ذات القيمة المعرفية والتاريخية.','["وأوضح مدير الإدارة العامة للمكتبات بالجامعة خالد بن مفلح الرشيدي أن القاعة تمثل إضافة نوعية لخدمات المكتبة المركزية، وتسهم في تعزيز حضورها مصدرًا معرفيًّا يخدم الدراسات المتخصصة، ويوفر بيئة مهيأة للتعامل مع المقتنيات النادرة والاستفادة منها.","وأكد أن افتتاح القاعة يأتي ضمن جهود الجامعة لتطوير خدماتها ومرافقها، وإثراء مصادرها العلمية والثقافية، وتهيئة بيئة داعمة للباحثين والمهتمين بالتراث المعرفي.","وأفاد بأن القاعة تضم (11) مخطوطًا أصليًّا، و(27) صورة لمخطوطات، وأكثر من (400) كتابٍ نادرٍ، من بينها (125) كتابًا يعود تاريخ طباعتها إلى أكثر من (80) عامًا، و(280) كتابًا يتراوح تاريخ طباعتها بين (50) و(80) عامًا، إلى جانب (3) خلوات بحثية وتجهيزات تقنية لعرض محتويات القاعة إلكترونيًا والمحافظة على مقتنياتها. // انتهى // 20:58 ت مـ 0260"]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2668590?type=news&uuid=N2668590','https://spa.gov.sa/ar/N2668590?type=news&uuid=N2668590','N2668590','N2668590','','المنطقة الشرقية','2026-09-03T14:58:00.000Z','2026-06-24T11:21:00.000Z','2026-09-03T20:30:48.378Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10725961.jpeg','/api/media/153578fa-0371-4e08-bc98-12ba570ca5e1','/api/media/153578fa-0371-4e08-bc98-12ba570ca5e1?variant=thumbnail','ثقافي / جامعة الملك فيصل تفتتح قاعة المخطوطات والكتب النادرة',1600,1200,'valid','published','archived','valid',51,'4bb19977de8d3d541d2b9e0a6fd0d75544043b3a8d9d76e7fbbf7bde3d3acf08','b9edfddfe823534028a5e10a02bbdde8b5af8f31e9779d63009aa8a61ac648da','محدّث','2026-09-03T20:30:48.379Z','2026-10-07T19:42:13.102Z','','',0,0,'saudi_region','مهم',70,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة الملك فيصل تفتتح قاعة","التعليم والتدريب","التقنية والتحول الرقمي"]','["جامعة الملك فيصل تفتتح قاعة","التعليم والتدريب","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T19:42:13.102Z',200,52,0,'source_article_available','',NULL,NULL,'body:a4889216c699d86305f2649cb051b59801c5a6598bbdb3144a5280114810eec4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e51f0c48-43cd-495b-b9f5-683b39a16e33','news-e51f0c48-43cd-495b-b9f5-683b39a16e33','علوم وتقنيات / وزارة الاتصالات و Google تطلقان مبادرة لتمكين مليون طالب جامعي بتقنيات Gemini مجانًا لمدة عام','علوم وتقنيات وزاره الاتصالات و google تطلقان مبادره لتمكين مليون طالب جامعي بتقنيات gemini مجانا لمده عام','الرياض 21 ربيع الأول 1448 هـ الموافق 03 سبتمبر 2026 م واس أعلنت وزارة الاتصالات وتقنية المعلومات وشركة Google، خلال مؤتمر "ليب 2026"، إطلاق مبادرة وطنية تتيح لمليون طالب وطالبة في الجامعات السعودية استخدام تقنيات الذكاء الاصطناعي المتقدمة من Google مجانًا لمدة عام؛ دعمًا لتنمية المهارات المستقبلية، وتعزيز جاهزية الكفاءات الوطنية للمنافسة والابتكار في…','["وأعلنت المبادرة رئيسة السياسات العامة لدى Google في المملكة وشمال أفريقيا سارة الحسيني، ضمن مشاركة الشركة في المؤتمر، مؤكدةً التزام Google بتوسيع إتاحة تقنيات الذكاء الاصطناعي، ودعم الطلاب للاستفادة منها بصورة مسؤولة وفاعلة في التعلّم والبحث والابتكار.","وتمنح المبادرة الطلاب والطالبات ممن تبلغ أعمارهم 18 عامًا فأكثر اشتراكًا مجانيًا لمدة عام في خطة Google AI Plus، بما يتيح لهم الاستفادة من أدوات Gemini في إعداد الأبحاث، وتحليل المعلومات، وتطوير الأفكار والمشاريع الأكاديمية، ورفع الإنتاجية.","وتواصل هذه الخطوة مسيرة التعاون في بناء القدرات الرقمية بالمملكة، بعد إسهام برامج Google خلال الأعوام الماضية في تدريب أكثر من 600 ألف شخص على مهارات الذكاء الاصطناعي والتسويق الرقمي، من بينها برنامج \"مهارات من Google\".","وقال وكيل وزارة الاتصالات وتقنية المعلومات لقدرات ووظائف المستقبل، المهندس محمد الربيعان: \" تنطلق هذه الشراكة من أولوية وطنية تتمثل في بناء رأس مال بشري قادر على قيادة الاقتصاد الرقمي والمنافسة في العصر الذكي، ولا تقتصر إتاحة تقنيات الذكاء الاصطناعي لمليون طالب وطالبة على توسيع الوصول إلى الأدوات المتقدمة، بل تستهدف دمجها بصورة مسؤولة وفاعلة في رحلة التعلّم، وتعزيز الإنتاجية والابتكار، وربط مخرجات التعليم بمهارات ووظائف المستقبل؛ بما يمكّن الكفاءات الوطنية من الانتقال من استخدام التقنية إلى تطوير تطبيقاتها وصناعة أثرها\".","ويمكن للطلاب والطالبات التسجيل في المبادرة حتى 31 ديسمبر 2026 بعد التحقق من الحالة الجامعية عبر الرابط التالي: https://gemini.google/students/ .","وتتضمن خطة Google AI Plus مجموعة من المزايا، أبرزها: تطبيق Gemini للاستفادة من نماذج الذكاء الاصطناعي المتقدمة في فهم المسائل المركبة، والبحث المعمق، وتحليل المعلومات، ودعم التعلّم، كما تتوفر أدوات توليد الوسائط: لإنشاء الصور ومقاطع الفيديو ودعم المشاريع التعليمية والإبداعية بمختلف تنسيقاتها، كذلك NotebookLM مساعد ذكي لتنظيم المصادر والمراجع، وتلخيص المحتوى الأكاديمي، وإعداد الملخصات الصوتية التفاعلية، كما توفر سعة تخزينية تبلغ 400 غيغابايت لحفظ المواد الدراسية والمراجع والمشاريع الأكاديمية.","وتشمل المبادرة سلسلة من البرامج التدريبية الممتدة على مدى عام، بالتعاون بين وزارة الاتصالات وتقنية المعلومات وGoogle؛ بهدف تمكين الطلاب والطالبات من توظيف أدوات الذكاء الاصطناعي بكفاءة ومسؤولية في مسيرتهم التعليمية.","كما تقدم Google خيارات إضافية للطلاب، تشمل خصمًا يصل إلى 75% على خطة Google AI Pro، التي تتيح أدوات ونماذج متقدمة للمهتمين بالبرمجة والتصميم، إلى جانب باقة خاصة بخصم يصل إلى 70% تجمع بين Google AI Pro وYouTube Premium."]','التقنية','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2668525?type=news&uuid=N2668525','https://spa.gov.sa/ar/N2668525?type=news&uuid=N2668525','N2668525','N2668525','','الرياض','2026-09-03T13:40:00.000Z',NULL,'2026-09-03T20:30:48.394Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10725054.jpg','/api/media/e51f0c48-43cd-495b-b9f5-683b39a16e33','/api/media/e51f0c48-43cd-495b-b9f5-683b39a16e33?variant=thumbnail','علوم وتقنيات / وزارة الاتصالات و Google تطلقان مبادرة لتمكين مليون طالب جامعي بتقنيات Gemini مجانًا لمدة عام',1600,1066,'valid','published','archived','valid',46,'4990f7518d786cd683e1aa42efee718b60c40cdd728330b20235da317338b15c','cef5ea64fda8da93934adaf46e4b7853039786703e43c8812684f5618d53e6b2',NULL,'2026-09-03T20:30:48.394Z','2026-10-07T20:24:32.469Z','','',0,0,'saudi_region','مهم',81,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الاتصالات و Google تطلقان","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي","الرياض"]','["وزارة الاتصالات و Google تطلقان","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"الاقتصاد","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T19:42:14.828Z',200,52,0,'source_article_available','',NULL,NULL,'body:a0e25029e415b5da48b896212ca01d3bd48efad800cf3dbb6cbed8ea791fad53','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ce406be4-75c4-4f3d-8691-af10b405bb72','news-ce406be4-75c4-4f3d-8691-af10b405bb72','«سبعة ونص».. تجربة تنافسية تعزز القيم وتثري حماس العودة إلى الدراسة','سبعه ونص تجربه تنافسيه تعزز القيم وتثري حماس العوده الي الدراسه','أطلقت قنوات عين برنامج «سبعة ونص» تجربةً تفاعليةً تنافسية ضمن حملة العودة إلى الدراسة «نكتب قصة»، تهدف إلى تهيئة طلاب وطالبات التعليم العام للعام الدراسي الجديد من خلال منافسات تجمع بين المهارة والمعرفة والحركة، وتعزز القيم والسلوكيات الإيجابية بأسلوب مشوق.','["يُعرض البرنامج على الهواء مباشرة عبر شاشة قنوات عين وحساباتها، في 12 حلقة مدة كل منها ساعة تلفزيونية، عند الساعة 7:30 مساءً من الأحد إلى الخميس، ويستهدف الطلاب والطالبات والمعلمين وأولياء الأمور.","يشارك في كل حلقة فريقان، بواقع طالبين أو طالبتين في الفريق الواحد، من الصف الخامس الابتدائي حتى الصف الأول المتوسط، وفق معايير تشمل التميز الأكاديمي والسلوكي والثقة بالنفس والقدرة على التواصل.","تتوزع المنافسات على ثلاث جولات تجمع بين السرعة والمعرفة والتحديات الحركية، مع التركيز على التعاون والعمل الجماعي والالتزام بالوقت.","كما يتضمن البرنامج «مكعب التحدي والاستطلاع» الذي يوسّع نطاق التفاعل عبر أسئلة ومواهب وتحديات رياضية ومعلومات وطنية وموضوعات رائجة.","ويسعى البرنامج إلى تقديم العودة إلى الدراسة بصورة مختلفة تجمع بين الحماس والفائدة، وتمنح الطلاب والطالبات مساحةً لإظهار مهاراتهم وثقتهم بأنفسهم، مع إشراك الأسرة والمجتمع في هذه التجربة التعليمية الترفيهية."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/mn0ZgoJ','https://sabq.org/article/mn0ZgoJ','','https://sabq.org/article/mn0ZgoJ','عبدالحكيم شار','','2026-09-03T12:48:00.000Z','2026-09-03T15:48:00.000Z','2026-09-03T20:30:48.491Z','https://media.sabq.org/news/2026/09/2b9e60e7-2019-43c6-a9f5-6e4012cf1c87/w1600.webp','/api/media/ce406be4-75c4-4f3d-8691-af10b405bb72','/api/media/ce406be4-75c4-4f3d-8691-af10b405bb72?variant=thumbnail','«سبعة ونص».. تجربة تنافسية تعزز القيم وتثري حماس العودة إلى الدراسة',1600,900,'valid','published','archived','valid',44,'cccfff283ace8ee93a5e01c48659bec64193883849b686d6a671ea1ca1a38cad','02496856ce837e44bd1b088863c0b41c486be9beceba7b88bbc146c904700c67','محدّث','2026-09-03T20:30:48.491Z','2026-10-07T20:24:32.474Z','','',0,0,'international','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"الرياضة","score":3},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T19:42:05.527Z',200,51,0,'source_article_available','',NULL,NULL,'body:052c81f4b7b147d350caa4a7088aed868d2f730a7ef12c3c59a52432c9099dda','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('be4ea9a5-54c7-4c41-83a6-68584b7592fd','news-be4ea9a5-54c7-4c41-83a6-68584b7592fd','الهلال وأوهام «المظلومية».. حقيقة الدعم والعدالة الرياضية','الهلال واوهام المظلوميه حقيقه الدعم والعداله الرياضيه','- الهلال أيقونة الكرة السعودية؛ فلماذا يُهاجم بهذا الشكل؟ لا تجعلوا من الهلال شماعة لخسائركم، فهل تريدون منه أن يترك لكم الساحة ويقول: «خذوا البطولات»؟','["- الهلال أيقونة الكرة السعودية؛ فلماذا يُهاجم بهذا الشكل؟ لا تجعلوا من الهلال شماعة لخسائركم، فهل تريدون منه أن يترك لكم الساحة ويقول: «خذوا البطولات»؟ هل تدعم وزارة الرياضة الهلال فقط دون بقية الأندية السعودية؟ وهل تنعدم العدالة والمنافسة مع بقية الفرق؟ هل رؤساء جميع اتحادات كرة القدم هلاليون؟ أين أدلتكم وبراهينكم على ذلك؟","- الهلال مثله مثل بقية الأندية السعودية، وليس من المنطقي أن يمنح صندوق الاستثمارات العامة نادياً أفضليات وتسهيلات على حساب بقية الأندية؛ وإلا لما حصل النصر على بطولة الدوري في الموسم الماضي، ولما حقق الأهلي بطولتيه الأخيرتين في النخبة الآسيوية. حدّث العاقل بما يعقل؛ فمستوى الأندية يتفاوت من موسم لآخر بناءً على الاستعدادات، والتعاقدات، وما قدمته مجالس إداراتها قبل بداية الموسم، وقيمة اللاعبين الذين تم استقطابهم.","- تميز الهلال عن غيره منذ بدايات الكرة السعودية بلاعبين يمتلكون قيمة فعلية وتأثيراً كبيراً داخل الملعب، ومواهب صنعت تاريخاً عظيماً للزعيم؛ حيث قدموا للكرة السعودية الكثير، وساهموا مع زملائهم في الأندية الأخرى في تحقيق بطولات قارية والتأهل لكأس العالم. أبعدوا الهلال عن حساباتكم وتفكيركم؛ فالنزاهة حاضرة، وما مَيّز الهلال عن بقية الأندية هو وجود أعضاء شرف داعمين له على مدار هذه الفترة الطويلة، ومجالس إدارات من العيار الثقيل ساهمت بشكل كبير في استمراره بطلاً، وهو لا يليق به إلا أن يكون كذلك.","- يمتلك الهلال داعماً قوياً سانده بكل قوة وهو الأمير الوليد بن طلال، وهذه ميزة حصل عليها الهلال وهو حق مشروع له، كما هو حق مشروع لبقية الأندية في الحصول على الدعم من الجهات التي أصبحت تملكها وتحت إدارتها.","- هناك فكر رياضي جديد مع مشروع الخصخصة، وعلينا التعامل معه بواقعية بعيداً عن التعصب والميول؛ فلا يصح أن نلجأ إلى التشكيك في الفريق الفائز بمجرد عدم تحقيق البطولة، أو أن نضع الأعذار من بداية الموسم بدعوى عدم عدالة المنافسة في استقطاب اللاعبين. ليس ذنب الهلال أن يغادر لاعبون من فريقك، أو أنك لم تستطع التعاقد مع عناصر مؤثرة تمتلك الفارق داخل الملعب.","- صنع الهلال مجده الكبير بعوامل كثيرة كانت سبباً في استمراره على منصات التتويج، ومنها الاهتمام الكبير الذي وجده من أبنائه ومحبيه وعشاقه، شأنه شأن بقية الأندية التي وجدت دعم محبيها وحققت البطولات والإنجازات.","- لا تشوهوا صورة الهلال الجميلة ولا تشككوا في بطولاته؛ فهناك عدالة تحكيمية داخل الملعب من المستحيل أن تتلاعب بسمعتها، فهل جميع من أداروا مباريات الهلال حكام غير عادلين؟ كرة القدم خلقت من أجل المتعة، ولم تُخلق لزرع التعصب والتشكيك في النزاهة، وللأسف فإن بعض الإعلاميين صوروا الهلال كفريق لا يُقهر فقط بسبب ما يزعمونه من غياب العدالة!","- الهلال فريق بطل منذ بداية تأسيسه وأصبحت لديه ثقافة الفوز، مثل بقية الأندية الكبيرة التي تمتلك ثقافة البطولات ولا ترضى إلا بأن تكون على منصات التتويج."]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264098','https://www.okaz.com.sa/articles/authors/2264098','','https://www.okaz.com.sa/articles/authors/2264098','سامي المغامسي','الرياض','2026-09-02T18:00:00.000Z','Tue, 06 Oct 2026 01:15:06 GMT','2026-09-04T02:50:00.703Z','https://www.okaz.com.sa/okaz/uploads/authors/1672.jpg?v=1757438909','/api/media/be4ea9a5-54c7-4c41-83a6-68584b7592fd','/api/media/be4ea9a5-54c7-4c41-83a6-68584b7592fd?variant=thumbnail','الهلال وأوهام «المظلومية».. حقيقة الدعم والعدالة الرياضية',399,400,'valid','published','archived','valid',40,'0bae76c155f1f08f7b02f814f401eece80430ad241e0a61713d916dc2996f643','36115c232e6490ea40fdaf985dd8c1460034c8ae9796d52d198ba5b28d4ae276','محدّث','2026-09-03T20:30:48.679Z','2026-10-07T20:24:32.481Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الرياضة الهلال فقط دون","الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق","جدة","الرياض"]','["وزارة الرياضة الهلال فقط دون","الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"المناطق","score":-0.5},{"category":"الاقتصاد","score":-1}]','Updated','2026-10-07T19:43:54.796Z',200,67,0,'source_content_changed','',NULL,NULL,'body:d7c281da1b4647567b218e25c5e02e1db4b4592431d931282a16a2b03f8e715b','Tue, 06 Oct 2026 01:15:06 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a1f3443b-742b-4465-84ed-b0950babd8a2','news-a1f3443b-742b-4465-84ed-b0950babd8a2','نيوم يأخذ نصيبه من الخليج بثلاثية نظيفة في دوري روشن','نيوم ياخذ نصيبه من الخليج بثلاثيه نظيفه في دوري روشن','حقق نيوم فوزاً ثميناً على حساب الخليج بثلاثة أهداف دون رد، في مباراة الجولة الخامسة من دوري روشن السعودي للمحترفين، التي جمعت الفريقين اليوم الخميس على ملعب مدينة الملك خالد الرياضية في تبوك.','["افتتح الفرنسي ألكسندر لاكازيت التسجيل لنيوم في الدقيقة 37، قبل أن يضاعف مهند السعد التقدم بالهدف الثاني بعد دقيقتين فحسب.","وأتمّ أمادو كوني الثلاثية في الدقيقة 45، ليغادر الفريقان أرض الملعب بنتيجة حاسمة لصالح نيوم.","وبهذا الفوز، يرتفع رصيد نيوم إلى 9 نقاط محتلاً المركز الخامس في جدول ترتيب الدوري، في حين يتجمد رصيد الخليج عند 3 نقاط في المركز الرابع عشر."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/fmhf6kt','https://sabq.org/article/fmhf6kt','','https://sabq.org/article/fmhf6kt','صحيفة سبق','الرياض','2026-09-03T12:50:00.000Z','2026-09-03T15:50:00.000Z','2026-09-03T20:30:48.777Z','https://media.sabq.org/news/2026/09/b8a0eb2e-9e65-4258-9fe2-3334e97370de/w1600.webp','/api/media/a1f3443b-742b-4465-84ed-b0950babd8a2','/api/media/a1f3443b-742b-4465-84ed-b0950babd8a2?variant=thumbnail','نيوم يأخذ نصيبه من الخليج بثلاثية نظيفة في دوري روشن',1600,1600,'valid','published','archived','valid',99,'8c91dca245d18c3d3db90a472487979df1ba7ecf6ebf8d3189f6f7ffa2f926c4','29619e85a18e6677a566ac34cef9549ae0939574b7dc0ec24e39e41b7d74c207','محدّث','2026-09-03T20:30:48.777Z','2026-10-07T19:42:05.492Z','','',0,0,'saudi_region','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","تبوك","الرياض"]','["الرياضة السعودية"]','classified','','[{"category":"المناطق","score":3},{"category":"أخبار السعودية","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T19:42:05.492Z',200,56,0,'source_article_available','',NULL,NULL,'body:0666b1d02f9dd232fd06dce027847dd9013a21eeb726c1fe3c4fd56fcd12e4ab','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6bb41d5d-0ebb-4080-890b-b7a4ece9c7f0','news-6bb41d5d-0ebb-4080-890b-b7a4ece9c7f0','اتحاد الرزيزاء ودعم وزير الرياضة','اتحاد الرزيزاء ودعم وزير الرياضه','استقال ياسر المسحل من رئاسة الاتحاد السعودي لكرة القدم قبل انتهاء فترة ولايته بعام، بعد سلسلة من الإخفاقات التي رافقت المنتخب الوطني، كان آخرها مشاركته الأخيرة في بطولة كأس العالم.','["-ومن وجهة نظري، فإن المشكلة لم تكن في غياب الإمكانات أو نقص الدعم، وإنما في سوء بعض القرارات التي اتخذها المسحل ومجلس إدارته، وهي المشكلة الأكبر التي عانى منها حبيبنا «أبو سلمان» طوال فترة رئاسته للاتحاد.","-ولا شك أن لمجلس إدارة المسحل إيجابيات، ولكنها لم تحظَ بالاهتمام الذي حظيت به سلبياته، وفي مقدمتها القرارات التي لم تكن دائماً بحجم المرحلة ولا بحجم الدعم والإمكانات التي توفرت للاتحاد.","-وكان من المفترض -في رأيي المتواضع- أن يكتفي المسحل بفترته الأولى، وألا يصر على الاستمرار لفترة ثانية، خاصة بعد أن أصبحت مؤشرات عدم الرضا الجماهيري والإعلامي واضحة.. لكن قاتل الله العناد!","-فالإصرار على الاستمرار رغم اتساع دائرة الانتقادات لم يكن في مصلحة المسحل ولا في مصلحة اتحادنا، وكانت النهاية التي وصل إليها اليوم نتيجة طبيعية لمسيرة كان يمكن أن تنتهي بصورة أفضل لو اتخذ قرار الرحيل في الوقت المناسب.","-ومن أهم النقاط التي أرى أن المسحل ومجلس إدارته لم يحسنا استثمارها، الدعم الاستثنائي وغير المسبوق الذي حصل عليه الاتحاد السعودي لكرة القدم، فمن الناحية المالية والإدارية والفنية والاستثمارية والتسويقية، حصل الاتحاد خلال السنوات الماضية على دعم كبير من مختلف مؤسسات الدولة الرياضية، وبالذات من وزارة الرياضة، التي قدمت للاتحاد دعماً لا أعتقد أنه كان متاحاً بهذا الحجم لرئيس اتحاد ومجلس إدارة في فترات سابقة.","-وهنا تحديداً يبرز السؤال الذي يستحق الإجابة.. إذا كان الدعم بهذا الحجم، فأين النتائج التي توازيه؟ولماذا لم ينعكس هذا الدعم الكبير بصورة أوضح على المنتخبات الوطنية، وعلى تطوير المسابقات، وعلى أداء اللجان، وعلى مستوى الاحتراف الإداري والفني؟","-ولهذا أرى أن الدعم وحده لا يصنع النجاح، وإنما حسن استثماره هو الذي يحوّل الإمكانات إلى إنجازات، وهنا تحديداً أعتقد أن المسحل ومجلس إدارته لم يوفقا في استثمار الفرصة كما يجب مما حتم عليهم مغادرة المشهد في غير الموعد له.","-من هذا المنطلق، أتمنى من رئيس اتحاد القدم الحالي بدر الرزيزاء وأعضاء مجلس إدارته، وهم في بداية مهمة صعبة، أن يستفيدوا جيداً من تجربة المسحل ومجلس إدارته، وألا يكرروا الأخطاء نفسها. إن المرحلة الجديدة تحتاج إلى قرارات مدروسة، وإلى مجلس لا يتردد في اتخاذ القرار الصحيح حتى لو كان صعباً، والأهم أن تكون القرارات مبنية على معايير واضحة، بعيداً عن المجاملات أو الحسابات الضيقة، ولعل أول اختبار حقيقي أمام مجلس الرزيزاء سيكون في ملف اللجان."]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264099','https://www.okaz.com.sa/articles/authors/2264099','','https://www.okaz.com.sa/articles/authors/2264099','عدنان جستنيه','الرياض','2026-09-02T18:00:00.000Z','Wed, 07 Oct 2026 19:43:55 GMT','2026-09-03T20:30:48.795Z','https://www.okaz.com.sa/okaz/uploads/authors/1828.jpg?v=1782207910','/api/media/6bb41d5d-0ebb-4080-890b-b7a4ece9c7f0','/api/media/6bb41d5d-0ebb-4080-890b-b7a4ece9c7f0?variant=thumbnail','اتحاد الرزيزاء ودعم وزير الرياضة',400,400,'valid','published','archived','valid',50,'1826818de0f3d8f68157ffeb5dd236e628b3c706429e20a3d3682fdfd00b9585','d08ae42ab1dc75df7d988c991cc4db720e592b845c42a47b6fa97db4c23f0767','محدّث','2026-09-03T20:30:48.795Z','2026-10-07T20:24:32.490Z','','',0,0,'saudi_region','مهم',67,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إدارته وهم في بداية","رئيس اتحاد القدم الحالي بدر","وزارة الرياضة التي قدمت للاتحاد","وزير الرياضة استقال ياسر المسحل","الرياضة السعودية","الاقتصاد والأسواق","الرياض"]','["مجلس إدارته وهم في بداية","رئيس اتحاد القدم الحالي بدر","وزارة الرياضة التي قدمت للاتحاد","وزير الرياضة استقال ياسر المسحل","الرياضة السعودية","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الثقافة","score":1.5},{"category":"المجتمع","score":0}]','Updated','2026-10-07T19:43:57.739Z',200,67,0,'source_content_changed','',NULL,NULL,'body:2e9f2d526cbf10bdab29985e8949abb84a7cf6807b12202d704e2e0e5f67f92a','Wed, 07 Oct 2026 19:43:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1c87c137-b7d0-4f2b-b92c-0fcb20125013','news-1c87c137-b7d0-4f2b-b92c-0fcb20125013','منسقة برامج «الهجرة الدولية» باليمن: سعداء بالدعم المقدم  من «سلمان للإغاثة».. شمل 12 مدرسة في 3 محافظات','منسقه برامج الهجره الدوليه باليمن سعداء بالدعم المقدم من سلمان للاغاثه شمل 12 مدرسه في 3 محافظات','أعربت منسقة البرامج والمشاريع في المنظمة الدولية للهجرة ب اليمن ، كاتيا يورتشي، عن سعادتها بالدعم المقدم من مركز الملك سلمان للإغاثة والأعمال الإنسانية ، والذي استفاد منه 12 مدرسة في 3 محافظات يمنية.','["وقالت يورتشي، في مقابلة مع قناة «الإخبارية»، إن الدعم يُقدم بالتعاون مع وزارة التربية والتعليم بصفتها ممثلة للحكومة اليمنية، موضحة أن المشروع يهدف إلى دعم 12 مدرسة في محافظات عدن ولحج و أبين .","وأكدت أن هذا الدعم يمثل إسهامًا مهمًا في مساندة العملية التعليمية وتحسين البيئة المدرسية، بما يخدم الطلاب والكوادر التعليمية في المحافظات المستفيدة."]','الثقافة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/3bm2njndv','https://ajel.sa/international/3bm2njndv','https://ajel.sa/international/3bm2njndv','https://ajel.sa/international/3bm2njndv','فريق التحرير','','2026-09-03T12:34:00.000Z','Wed, 07 Oct 2026 19:42:39 GMT','2026-09-03T20:30:48.923Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Screenshot2026-09-03151603-crop-1jtAJfzP.png','/api/media/1c87c137-b7d0-4f2b-b92c-0fcb20125013','/api/media/1c87c137-b7d0-4f2b-b92c-0fcb20125013?variant=thumbnail','منسقة برامج «الهجرة الدولية» باليمن: سعداء بالدعم المقدم من «سلمان للإغاثة».. شمل 12 مدرسة في 3 محافظات',1200,675,'valid','published','archived','valid',42,'5360be0098a7fd4e72faca41c095645f622dd4a5bde526d6034b6138241c755e','3996ca2b44c7eb4170774bafa49da4ff2f487d6146543275c00645f32e40fe5c','محدّث','2026-09-03T20:30:48.923Z','2026-10-07T20:24:32.494Z','','',0,0,'gulf_arab','مهم',70,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة التربية والتعليم بصفتها ممثلة","الثقافة والفنون","التعليم والتدريب","اليمن"]','["وزارة التربية والتعليم بصفتها ممثلة","الثقافة والفنون","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"البيئة والمناخ","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:42:41.227Z',200,50,0,'source_content_changed','',NULL,NULL,'body:9fef93da6f125801e4181c50dfe6b80b7b0ceecaab96458d6a5a88280bb40ba6','Wed, 07 Oct 2026 19:42:39 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b9a1c095-5ea5-4608-80ef-b251f017a833','news-b9a1c095-5ea5-4608-80ef-b251f017a833','«غابرييل مارتينيلي» هلاليًا لمدة أربعة أعوام','غابرييل مارتينيلي هلاليا لمده اربعه اعوام','أنهى مجلس إدارة شركة نادي الهلال برئاسة الأمير نواف بن سعد إجراءات توقيع عقد انتقال اللاعب البرازيلي «غابرييل مارتينيلي» قادمًا من نادي «أرسنال الإنجليزي»، ليمثّل فريق الهلال الأول لكرة القدم لمدة أربعة أعوام، وذلك في مراسم أُقيمت مساء الخميس في «مركز الماجدية الرياضي».','["وثمّن مجلس الإدارة تكفّل الأمير الوليد بن طلال بصفقة انتقال «مارتينيلي» إلى صفوف الهلال، مقدّمًا خالص الشكر والتقدير لسموه على دعمه المستمر للنادي وإسهاماته في تعزيز قدراته التنافسية وتحقيق تطلعات جماهيره.","وبدأ «مارتينيلي» البالغ من العمر 25 عامًا مسيرته الكروية مع فريق «إيتوانو البرازيلي»، قبل أن ينتقل إلى «أرسنال الإنجليزي» عام 2019، حيث مثّل الفريق في مختلف المنافسات المحلية والقارية وسجّل بقميصه 62 هدفًا، إلى جانب صناعته العديد من الأهداف.","وتُوّج «مارتينيلي» مع «أرسنال» بعدد من البطولات المحلية، أبرزها: «الدوري الإنجليزي الممتاز» و«كأس الاتحاد الإنجليزي» و«درع المجتمع»، كما شارك مع الفريق في منافسات دوري أبطال أوروبا.","وعلى الصعيد الدولي، مثّل «مارتينيلي» المنتخب البرازيلي في عدد من الاستحقاقات، وشارك معه في بطولتي كأس العالم 2022 و2026، كما سبق له تمثيل المنتخب الأولمبي تحت 23 عامًا، وأسهم في تحقيق الميدالية الذهبية في دورة الألعاب الأولمبية «طوكيو 2020».","وينتظر أن ينتظم «مارتينيلي» في تدريبات فريق الهلال الأول مساء اليوم، استعدادًا لمواجهة «الشباب» غدًا الجمعة ضمن منافسات دوري روشن السعودي للمحترفين."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/TW4mpeO','https://sabq.org/article/TW4mpeO','','https://sabq.org/article/TW4mpeO','صحيفة سبق','الرياض','2026-09-03T11:06:00.000Z','2026-09-03T14:55:00.000Z','2026-09-03T20:30:49.243Z','https://media.sabq.org/news/2026/09/7e888e0f-2bf6-4649-9162-bcbf61e126a5/w1200.webp','/api/media/b9a1c095-5ea5-4608-80ef-b251f017a833','/api/media/b9a1c095-5ea5-4608-80ef-b251f017a833?variant=thumbnail','«غابرييل مارتينيلي» هلاليًا لمدة أربعة أعوام',1200,960,'valid','published','archived','valid',99,'9e90b38f33043ee43b3039c82e5d01efd748c49a8a5ab51175235cf3be5e7361','4350792feb9fdaf73e002240987b12f05f8cd16151fb91391c5d45ebda2311ac','محدّث','2026-09-03T20:30:49.243Z','2026-10-07T19:42:13.670Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إدارة شركة نادي الهلال","شركة نادي الهلال برئاسة الأمير","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق","الرياض","أوروبا"]','["مجلس إدارة شركة نادي الهلال","شركة نادي الهلال برئاسة الأمير","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"التقنية","score":0},{"category":"المجتمع","score":-3.5}]','Active','2026-10-07T19:42:13.670Z',200,50,0,'source_article_available','',NULL,NULL,'body:8fe2e7abc433e3891c3141eb21eeb8d26ffeae0248c6a9a2e59dc9843053bfa2','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ecdb0e77-b9c0-441f-b9a2-15cc599d22e7','news-ecdb0e77-b9c0-441f-b9a2-15cc599d22e7','الرئيس اليمني يشكر السعودية على دعم جديد للبنك المركزي','الرئيس اليمني يشكر السعوديه علي دعم جديد للبنك المركزي','أعرب الرئيس اليمني الدكتور رشاد محمد العليمي، رئيس مجلس القيادة الرئاسي، باسمه وباسم أعضاء المجلس والحكومة والشعب اليمني، عن عظيم الشكر والتقدير للمملكة العربية السعودية بقيادة خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز، وولي عهده صاحب السمو الملكي الأمير محمد بن سلمان، على الدعم الجديد المقدَّم للبنك المركزي اليمني. وأكد العليمي في تدوينة على حسابه…','["وأكد العليمي في تدوينة على حسابه في منصة «إكس» أن هذا الدعم يأتي امتداداً للمواقف الأخوية الثابتة للمملكة إلى جانب الشعب اليمني وقيادته السياسية.","وقال إن «هذا الدعم الكريم يمثّل دفعة مهمة لمسار الإصلاحات الاقتصادية، وتعزيز استقرار العملة الوطنية، وتحسين معيشة المواطنين والخدمات الأساسية».","وأكد رئيس مجلس القيادة الرئاسي مضيَّ الحكومة اليمنية في الوفاء بالتزاماتها، وتعظيم أثر هذه الشراكة الأخوية بين البلدين، وتعزيز الثقة بمؤسسات الدولة ومسار التعافي الشامل.","وكان البرنامج السعودي لتنمية وإعمار اليمن قد أعلن عن هذا الدعم الجديد للبنك المركزي اليمني بهدف تعزيز مقوّمات الاستقرار الاقتصادي والمالي والنقدي، بما يُسهم في رفع القوة الشرائية للمواطنين، وتحسين مستوى المعيشة، وتنشيط الأسواق التجارية، ودعم مسار التعافي المستدام في اليمن."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/prUHNoL','https://sabq.org/article/prUHNoL','','https://sabq.org/article/prUHNoL','صحيفة سبق','','2026-09-03T11:25:00.000Z','2026-09-03T14:25:00.000Z','2026-09-03T20:30:49.256Z','https://media.sabq.org/news/2026/09/051a72f2-965f-4cf7-bfd1-caf3327a88b1/w850.webp','/api/media/ecdb0e77-b9c0-441f-b9a2-15cc599d22e7','/api/media/ecdb0e77-b9c0-441f-b9a2-15cc599d22e7?variant=thumbnail','الرئيس اليمني يشكر السعودية على دعم جديد للبنك المركزي',850,731,'valid','published','archived','valid',98,'d6683135209a8bce9ee4368c4864c5fe9af792c9d58349d8aedb05d8784c9da5','f9600acc317054ef8c4ed7e03bdb825c8c46280952bda738e59e2b24fbde2446','محدّث','2026-09-03T20:30:49.256Z','2026-10-07T20:24:32.502Z','','',0,0,'saudi_national','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس القيادة الرئاسي باسمه","مجلس القيادة الرئاسي باسمه وباسم","خادم الحرمين الشريفين الملك سلمان","الاقتصاد والأسواق","اليمن"]','["رئيس مجلس القيادة الرئاسي باسمه","مجلس القيادة الرئاسي باسمه وباسم","خادم الحرمين الشريفين الملك سلمان","الاقتصاد والأسواق"]','classified','','[{"category":"المجتمع","score":3},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:08.393Z',200,51,0,'source_article_available','',NULL,NULL,'body:eb20d8016a48d9158f76620c158662e0201e224d5ddfb388da49f190183f8d4b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0f6a6a72-ec93-4c40-8197-cb86986954dd','news-0f6a6a72-ec93-4c40-8197-cb86986954dd','الأمن والتاريخ (2)','الامن والتاريخ 2','فالسردية التاريخية بحاجة للاهتمام ومسايرة الأزمان بالتصحيح وبث المعلومة الصحيحة، ولا تقتصر المهمة على التصحيح، بل أصعب منها بثّ الصحيح إلى بقية العالم، من خلال مؤسساتها ومثقفيها واستخدام كل وسيلة تواصل مع العالم..','["التاريخ أحداث سردية، سواء كانت شفوية أو مكتوبة، والشفوي يتحوّل إلى مكتوب ذات يوم، فكيف تتولّد السردية التاريخية المكتوبة؟ وقبل هذا، ليس هناك تاريخ مكتوب من غير سياج أمني للكاتب، حتى المناقض لتلك السردية بحاجة إلى أمن لكي يكتب ما ينقض التاريخ السيار بين الناس.","ولكل أمة سردية خاصة بها، يتم ترسيخها لدى الأجيال المتتابعة، وهناك سرديات تُمحى بفعل الزمن، وتغيّر سلطاتها، إلا أن هناك سرديات تعبر الزمن بزوائد أو نواقص أو مغلطات، يستوجب تصويب كل زائد أو ناقص، وإيضاح مسار المثبت، والسردية عبر التاريخ الأزلي نحن متواجدون به، كون مكة أول بيت وضع للناس، ويصبح تجلية التاريخ من مهامنا الوطنية، وهي مهمة جديرة بأن تنهض بها كل المؤسسات المعنية بالجانب الثقافي والمعرفي، وأعتقد أن دارة الملك عبدالعزيز هي في لبّ هذه المهمة.","فالسردية التاريخية بحاجة للاهتمام ومسايرة الأزمان بالتصحيح وبث المعلومة الصحيحة، ولا تقتصر المهمة على التصحيح، بل أصعب منها بثّ الصحيح إلى بقية العالم، من خلال مؤسساتها ومثقفيها واستخدام كل وسيلة تواصل مع العالم.. سأذكر مثالاً عن السردية التاريخية التي تجتمع عليها الديانات الثلاث، وهي معركة (هرمجدون)، كإشارة إلى أنها علامة من العلامات الكبرى ليوم القيامة. سردية هذه المعركة مثبتة في عقول أناس هذا الزمن، خاصة رجال الديانات الثلاث. ويطيب للبعض استرجاعها حدثاً تاريخياً سيتحقق ذات يوم، وكل منهم لديه سردية مغايرة في استقبالها، وتتحوّل هذه الفكرة إلى أجندات بعيدة المدى يجب العمل على تنفيذ خطواتها، نعم، هي سردية تاريخيّة، وأجزم أن كل سردية يجعل لها أصحابها خاصيّة، والبعض يورّث تلك الحكايات.","وكثير مما نعيشه هذه الأيام من حروب، ما هي إلا مقدمة للأيام القادمة (حتى ولو كانت الحرب الدينية العظيمة مؤجلة إلى زمن غائب)، ويقيناً أحمله بأننا مستهدفون، سواء من خلال السردية التاريخية القديمة أو من خلال السردية المحرّضة حديثاً، والالتصاق بهذه السرديات ونقضها بما هو صائب يحفظ أمننا ويحقق الاستقرار والنمو.","أحياناً، يكون التاريخ له بواعث لا تخطر على البال.. ربما جئت لكم بنقطة خلاف بين الأمم يستوجب بيانها والمسايرة معها حفاظاً على الأمن وتصويب التاريخ.","History is a narrative of events, whether oral or written, and the oral eventually transforms into written form one day. So, how does the written historical narrative come into being? Before this, there is no written history without a security fence for the writer; even the opposer of that narrative needs security to write what contradicts the prevailing history among people.","Every nation has its own narrative, which is instilled in successive generations. Some narratives are erased by the passage of time and the changing of their authorities, yet there are narratives that transcend time with additions, omissions, or distortions, necessitating the correction of every addition or omission, and clarifying the established path. The narrative throughout eternal history is where we exist, as Mecca is the first house established for people, and the manifestation of history becomes one of our national duties, a task worthy of being undertaken by all institutions concerned with cultural and intellectual aspects. I believe that the King Abdulaziz Foundation is at the heart of this mission.","The historical narrative needs attention and to keep pace with the times through correction and dissemination of accurate information. The task is not limited to correction; it is even more challenging to spread the truth to the rest of the world through its institutions and intellectuals, using every means of communication with the world. I will mention an example of the historical narrative that is common among the three religions, which is the Battle of (Armageddon), as a reference to it being one of the major signs of the Day of Judgment. The narrative of this battle is firmly established in the minds of people in this era, especially among the men of the three religions. Some take pleasure in recalling it as a historical event that will one day come to pass, each with a differing narrative in how they perceive it, and this idea transforms into long-term agendas that must be worked on to implement their steps. Yes, it is a historical narrative, and I assert that every narrative gives its owners a unique characteristic, and some pass down those tales."]','الثقافة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264097','https://www.okaz.com.sa/articles/authors/2264097','','https://www.okaz.com.sa/articles/authors/2264097','عبده خال','مكة المكرمة','2026-09-02T18:00:00.000Z','Wed, 07 Oct 2026 19:43:54 GMT','2026-09-04T02:50:02.980Z','https://www.okaz.com.sa/okaz/uploads/authors/238.jpg?v=1768301522','/api/media/0f6a6a72-ec93-4c40-8197-cb86986954dd','/api/media/0f6a6a72-ec93-4c40-8197-cb86986954dd?variant=thumbnail','الأمن والتاريخ (2)',361,400,'valid','published','archived','valid',50,'ed3637ad4325c889a5b3a3e04e76a76b9d69f7a8f1aaed655f50bf59f19e1de4','c7a2fe0ae122a7af7cab0b3483809de955928e7a5cc3508c466b25317f4b422c','محدّث','2026-09-03T20:30:49.402Z','2026-10-07T19:43:56.435Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","مكة"]','["الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Updated','2026-10-07T19:43:56.435Z',200,68,0,'source_content_changed','',NULL,NULL,'body:4c683a8fd753f1dbe887803541fee130acdb4b1a128b35501719b81876234c9d','Wed, 07 Oct 2026 19:43:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e461c22c-8f0f-4932-80f6-3e5697e2f8e4','news-e461c22c-8f0f-4932-80f6-3e5697e2f8e4','ثلاثية في 8 دقائق.. نيوم يقسو على الخليج ويعود للانتصارات','ثلاثيه في 8 دقائق نيوم يقسو علي الخليج ويعود للانتصارات','حسم نيوم مواجهته أمام الخليج بثلاثية نظيفة، رافعًا رصيده إلى 9 نقاط في المركز الخامس بجدول دوري روشن السعودي، بعدما أنهى اللقاء بثلاثة أهداف سجلها قبل نهاية الشوط الأول.','["وجاء الحسم سريعًا في الدقائق الأخيرة من الشوط الأول، إذ افتتح ألكسندر لاكازيت التسجيل لنيوم عند الدقيقة 37، قبل أن يضيف مهند السعد الهدف الثاني بعد دقيقتين.","ولم يتوقف تفوق نيوم عند هذا الحد، إذ أكمل أمادو كوني الثلاثية في الدقيقة 45، لينهي الفريق الشوط الأول متقدمًا بثلاثية نظيفة، ويحافظ على تقدمه حتى نهاية المباراة.","ورفع الفوز رصيد نيوم إلى 9 نقاط ليحتل المركز الخامس، بينما ظل الخليج عند 3 نقاط في المركز الرابع عشر بجدول ترتيب الدوري.","وجاء انتصار نيوم ضمن منافسات الجولة الخامسة من دوري روشن السعودي، ليضع الفريق حدًا لفترة غياب الانتصارات ويعود إلى حصد النقاط بثلاثية أمام الخليج."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/wvzyrwwty','https://ajel.sa/sports/wvzyrwwty','https://ajel.sa/sports/wvzyrwwty','https://ajel.sa/sports/wvzyrwwty','فريق التحرير','','2026-09-03T13:04:00.000Z','Wed, 07 Oct 2026 19:42:17 GMT','2026-09-03T20:30:49.578Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-wpUFekkv.jpg','/api/media/e461c22c-8f0f-4932-80f6-3e5697e2f8e4','/api/media/e461c22c-8f0f-4932-80f6-3e5697e2f8e4?variant=thumbnail','نيوم والخليج',1200,675,'valid','published','archived','valid',41,'10da2fa4b00a5cd7230d03e052e6fd6110ad72a5453ca7843580e3d0c247043b','5cef3dd156dfdac2617ebe36264fd34b1bf8e06a15874467191a3f4b9ec3c2ce','محدّث','2026-09-03T20:30:49.578Z','2026-10-07T20:24:32.510Z','','',0,0,'gulf_arab','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:19.439Z',200,48,0,'source_content_changed','',NULL,NULL,'body:515843132eb790dc848ea90e269391a645a0af440b43a11874ecac11c4f0e8cb','Wed, 07 Oct 2026 19:42:17 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e15f3cc8-904c-46fc-b162-79d0b8778ef4','news-e15f3cc8-904c-46fc-b162-79d0b8778ef4','سياحة وترفيه / متنزهات الباحة الوطنية.. 27 وجهة طبيعية تمتد على أكثر من 10 آلاف هكتار','سياحه وترفيه متنزهات الباحه الوطنيه 27 وجهه طبيعيه تمتد علي اكثر من 10 الاف هكتار','الباحة 21 ربيع الأول 1448 هـ الموافق 03 سبتمبر 2026 م واس تزخر منطقة الباحة ببيئة طبيعية متنوعة جعلت من متنزهاتها الوطنية ركيزة أساسية لمقوماتها البيئية والسياحية؛ إذ يشرف المركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر على (27) متنزهًا وطنيًا في المنطقة، تمتد على مساحة تقدّر بنحو (10,783.78) هكتارًا.','["وتتوزع هذه المتنزهات عبر محافظات ومراكز المنطقة، مستفيدةً من تضاريسها الفريدة التي تجمع بين المرتفعات الجبلية والأودية والغابات، وما تحتضنه من غطاء نباتي وتنوع أحيائي غني، لتشكل مساحات طبيعية تسهم في صون الموارد البيئية، وتوفر في الوقت ذاته متنفسًا حيويًا للأهالي والزوار.","ويعمل المركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر على إدارة هذه المتنزهات وتطويرها، من خلال حماية الغطاء النباتي والموارد الطبيعية وإعادة تأهيلها، إلى جانب تحسين البنية التحتية والخدمات بما يضمن الاستخدام المستدام لهذه المواقع والحفاظ على مكوناتها الطبيعية.","وتكتسب متنزهات الباحة أهمية إستراتيجية بفضل طبيعتها الجبلية وغطائها النباتي، مما يعزز دورها في دعم السياحة البيئية وتوفير مساحات طبيعية للزوار، مع الحرص على تحقيق التوازن الدقيق بين الاستفادة من هذه المواقع وحمايتها من التدهور.","وضمن جهوده المستمرة، يتولى المركز تشغيل وصيانة عدد من المتنزهات، منها متنزه الثروة الوطنية، وناوان، ومليل، وعليب، وذلك في إطار أعمال تهدف إلى الحفاظ على جاهزية المواقع ورفع مستوى الخدمات المقدمة لمرتاديها.","وتعد المتنزهات الوطنية ركيزة أساسية لمنظومة الغطاء النباتي في المنطقة؛ نظرًا لدورها الفاعل في حماية النظم البيئية، والحفاظ على التنوع الأحيائي، والحد من آثار التصحر، فضلًا عن إسهامها في تعزيز جودة الحياة، وخلق فرص واعدة للسياحة البيئية والاستثمارات المرتبطة بالطبيعة.","وتأتي العناية بهذه المتنزهات ضمن اختصاصات المركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر في الإدارة المستدامة للموارد الطبيعية، وتنميتها وإعادة تأهيلها، بما يضمن استدامتها للأجيال القادمة. // انتهى // 13:00 ت مـ 0098"]','المجتمع','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2668052?type=news&uuid=N2668052','https://spa.gov.sa/ar/N2668052?type=news&uuid=N2668052','N2668052','N2668052','','الباحة','2026-09-03T07:00:00.000Z','2026-06-25T05:03:00.000Z','2026-09-03T20:30:49.731Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10721098.jpeg','/api/media/e15f3cc8-904c-46fc-b162-79d0b8778ef4','/api/media/e15f3cc8-904c-46fc-b162-79d0b8778ef4?variant=thumbnail','سياحة وترفيه / متنزهات الباحة الوطنية.. 27 وجهة طبيعية تمتد على أكثر من 10 آلاف هكتار',1600,966,'valid','published','archived','valid',53,'1f89dd5278b1909721bffa5b5eb6cf4477ad7c612a650b1b3f46057b998c2a45','4759058e5f0e1e73df5591a8bf0fc2393808d6212f896a50ad53cf9351911d03','محدّث','2026-09-03T20:30:49.731Z','2026-10-07T19:43:47.574Z','','',0,0,'saudi_region','مهم',72,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الاقتصاد والأسواق","الباحة"]','["السفر والسياحة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الاقتصاد","score":4},{"category":"المناطق","score":3},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T19:43:47.574Z',200,64,0,'source_article_available','',NULL,NULL,'body:4abc81a1bfd9b275e21da2ce3f564803c21fec10afafc0df9b8c5d5bfe9cd3f3','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e18112db-7330-4319-ba7b-44e0bbf47d16','news-e18112db-7330-4319-ba7b-44e0bbf47d16','بيئي / مُحافظ الطائف يطلق كائنات فطرية لتعزيز التنوع الأحيائي بمتنزه سيسد الوطني','بيئي محافظ الطائف يطلق كائنات فطريه لتعزيز التنوع الاحيائي بمتنزه سيسد الوطني','الطائف 21 ربيع الأول 1448 هـ الموافق 03 سبتمبر 2026 م واس أطلق صاحب السمو الملكي الأمير فواز بن سلطان بن عبدالعزيز محافظ الطائف اليوم، (10) كائنات فطرية في متنزه سيسد الوطني بالطائف، وذلك ضمن برامج إعادة توطين الأنواع الفطرية في موائلها الطبيعية وتعزيز التنوع الأحيائي، التي ينفذها المركز الوطني لتنمية الحياة الفطرية بالتعاون مع المركز الوطني لتنمية…','["وشملت عملية الإطلاق (3) من ظباء الإدمي، و(4) من النعام أحمر الرقبة، و(3) أرانب برية، بعد استكمال متطلبات الجاهزية والتأكد من ملاءمة الموقع، بما يدعم تكيفها واستقرارها في المتنزه، ويعزز فرص تكوين جماعات فطرية مستدامة في موائل تتناسب مع طبيعة كل نوع.","واطّلع سمو محافظ الطائف خلال الزيارة على مشروع المركز البحثي المتخصص في أبحاث الغابات بالمتنزه، واستمع إلى عرض عن مستهدفاته ودوره في تطوير الدراسات الداعمة لتنمية الغابات واستدامة الغطاء النباتي.","وأوضح الرئيس التنفيذي للمركز الوطني لتنمية الحياة الفطرية الدكتور محمد قربان، أن هذا الإطلاق يمثل استكمالًا لبرامج المركز في إعادة توطين الأنواع الفطرية، ويجسد أهمية العمل المشترك مع الجهات الوطنية المعنية بتنمية الموائل، مؤكدًا أهمية عمليات الإطلاق في المتنزهات الوطنية، بوصفها ممرات آمنة للكائنات الفطرية بين المحميات الطبيعية، إلى جانب إسهامها في تعزيز الجاذبية السياحية للمتنزهات.","وأضاف أن نجاح برامج إعادة التوطين يرتبط بتكامل مراحل العمل، بدءًا من اختيار الأنواع والمواقع الملائمة، مرورًا بالتأهيل والإطلاق، ووصولًا إلى الرصد والمتابعة، بما يتيح تقييم النتائج وتطوير البرامج المستقبلية وفق أسس علمية تدعم استدامة التنوع الأحيائي في المملكة.","ويأتي الإطلاق امتدادًا للتعاون بين المركز الوطني لتنمية الحياة الفطرية والمركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر، وتكاملًا بين جهود تنمية الموائل الطبيعية وبرامج إكثار وإعادة توطين الكائنات الفطرية، بما يعزز القيمة البيئية للمتنزهات الوطنية. // انتهى // 17:39 ت مـ 0194"]','الوظائف وسوق العمل','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2668379?type=news&uuid=N2668379','https://spa.gov.sa/ar/N2668379?type=news&uuid=N2668379','N2668379','N2668379','','','2026-09-03T11:39:00.000Z',NULL,'2026-09-03T20:30:49.737Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10726522.jpg','/api/media/e18112db-7330-4319-ba7b-44e0bbf47d16','/api/media/e18112db-7330-4319-ba7b-44e0bbf47d16?variant=thumbnail','بيئي / مُحافظ الطائف يطلق كائنات فطرية لتعزيز التنوع الأحيائي بمتنزه سيسد الوطني',1600,1200,'valid','published','archived','valid',46,'43e3c0ae64dd2a2407c0f52976c99d91ca1d0f3602fa04d0d70a2447e53f603b','514200fefba138a8a530a4d16c8d208dbdaf216cf9b5031631d8439ec3514e0e',NULL,'2026-09-03T20:30:49.737Z','2026-10-07T20:24:32.517Z','','',0,0,'saudi_national','مهم',76,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T19:42:47.304Z',200,51,0,'source_article_available','',NULL,NULL,'body:d72ee0ffb2baa311917a72cc549ac6cadc229f2241e322c38bb03f91fec409ce','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e232acd4-6b3b-4b43-9298-0e4601222574','news-e232acd4-6b3b-4b43-9298-0e4601222574','وفاة الشيخ ناصر الخريّف والصلاة عليه عصر الجمعة بجامع الملك خالد في الرياض','وفاه الشيخ ناصر الخريف والصلاه عليه عصر الجمعه بجامع الملك خالد في الرياض','انتقل إلى رحمة الله تعالى الشيخ ناصر بن محمد بن عبدالرحمن الخريّف «أبو محمد»، ويُصلّى عليه بعد صلاة عصر يوم الجمعة 22 ربيع الأول 1448هـ في جامع الملك خالد بحي أم الحمام بمدينة الرياض.','["ويُوارى جثمانه الثرى في مقبرة صفية بمحافظة حريملاء عقب الصلاة عليه.","ويُقام عزاء الرجال من الساعة السادسة حتى الثامنة مساءً في منزل الفقيد بحي الربيع، شمال جامع السلام بمدينة الرياض، فيما يُقام عزاء النساء في المسجد.","والفقيد شقيق عبدالرحمن بن محمد الخريّف، ووالد كلٍّ من: محمد، والدكتور عبدالرحمن، وعبدالله، وعبدالعزيز، وتميم، وسلطان، وعاصم.","نسأل الله أن يتغمد الفقيد بواسع رحمته ومغفرته، وأن يرفع درجته في الفردوس الأعلى، ويُلهم أهله وذويه الصبر والسلوان."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/eclw9q7','https://sabq.org/article/eclw9q7','','https://sabq.org/article/eclw9q7','صحيفة سبق','الرياض','2026-09-03T10:48:00.000Z','2026-09-03T13:49:00.000Z','2026-09-03T20:30:49.742Z','https://media.sabq.org/news/2026/09/43cfc361-d0fa-4e97-baea-d37cee4420bd/w400.webp','/api/media/e232acd4-6b3b-4b43-9298-0e4601222574','/api/media/e232acd4-6b3b-4b43-9298-0e4601222574?variant=thumbnail','وفاة الشيخ ناصر الخريّف والصلاة عليه عصر الجمعة بجامع الملك خالد في الرياض',400,400,'valid','published','archived','valid',86,'ba7d6e50f5e197f3d32f60306afe363da1fd9ed52501537f87976280f1de1398','ba5a4a7b8f255346f52ce42278ee82ecc21ac0a68f989db156afc2cbddaa5047','محدّث','2026-09-03T20:30:49.742Z','2026-10-07T19:42:17.910Z','','',0,0,'saudi_region','مهم',76,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض"]','[]','classified','','[{"category":"المجتمع","score":3},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:17.910Z',200,47,0,'source_article_available','',NULL,NULL,'body:65ee40bc5a3393c6d09a5bf5823fd766217010ce618de6fbc797b3ea382154cb','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cd4366eb-1a05-4d66-abc6-b2047ca9bb1b','news-cd4366eb-1a05-4d66-abc6-b2047ca9bb1b','علوم وتقنيات / من الحدث إلى الأثر.. حكاية تتجاوز أيام "ليب 2026" الأربعة','علوم وتقنيات من الحدث الي الاثر حكايه تتجاوز ايام ليب 2026 الاربعه','وفي هذا السياق، يأتي "ليب 2026" ليقدم، في يومه الرابع، صورة واضحة عن التحول من استشراف المستقبل إلى بناء مقوماته. ويبرز في هذا المشهد قطاع مراكز البيانات بوصفه أحد أهم مقومات المرحلة المقبلة؛ إذ شهد "ليب 2026" إعلانات مرتبطة بتوسعة قدرات مراكز البيانات، إلى جانب إعلان شركة "AWS" عن إطلاق أول منطقة للبنية التحتية السحابية في المملكة خلال ديسمبر 2026، في…','["الرياض 21 ربيع الأول 1448 هـ الموافق 03 سبتمبر 2026 م واس في \"عام الذكاء الاصطناعي 2026\"، تتقدم المملكة إلى مرحلة جديدة في مسيرتها التقنية؛ مرحلة لا يُقاس فيها حضور الذكاء الاصطناعي بعدد الحلول التي تُعرض، وإنما بقدرته على توليد الاستثمار، وبناء البنية التحتية، وتمكين القطاعات، وخلق قدرات وطنية قادرة على المنافسة عالميًا.","وفي هذا السياق، يأتي \"ليب 2026\" ليقدم، في يومه الرابع، صورة واضحة عن التحول من استشراف المستقبل إلى بناء مقوماته.","وجاءت تسمية عام 2026 بـ \"عام الذكاء الاصطناعي\" لتؤكد مكانة هذا القطاع ضمن التوجه الوطني نحو تعزيز موقع المملكة في التقنيات المتقدمة.","وتنسجم هذه الخطوة مع مستهدفات رؤية السعودية 2030، التي جعلت التحول الرقمي والابتكار والاقتصاد القائم على المعرفة من مرتكزات التنمية وتنويع الاقتصاد.","ومن الرياض، يعكس \"ليب 2026\" هذا التوجه بأرقام ترتبط بهذه النسخة تحديدًا؛ فمنذ انطلاق أعمالها في 31 أغسطس 2026، شهدت فعاليات المؤتمر الإعلان عن إطلاقات واستثمارات تقنية تجاوزت قيمتها 15 مليار دولار، وفق ما أعلن في اليوم الأول، فيما سجل اليوم الثاني، في 1 سبتمبر 2026، استثمارات وإطلاقات نوعية بقيمة إجمالية بلغت نحو 2.5 مليار دولار، تركزت في مراكز البيانات والخدمات والتقنيات المتقدمة.","ولا تكمن دلالة هذه الأرقام في قيمتها المالية وحدها، بل في طبيعة ما تقابله من مشروعات؛ إذ تتجه نسبة مهمة من الحراك الذي شهده \"ليب 2026\"إلى أصول وقدرات تمتد آثارها لسنوات، وفي مقدمتها مراكز البيانات والحوسبة المتقدمة والبنية التحتية للذكاء الاصطناعي، وهو انتقال مهم من اقتصاد يستهلك التقنية إلى اقتصاد يستثمر في البنية التي تقوم عليها التقنية نفسها.","كما أعلنت توسيع تعاونها الإستراتيجي مع \"HUMAIN\" لتوفير ما يصل إلى 50 ميجاواط ضمن أول منطقة للذكاء الاصطناعي في المملكة بحلول عام 2028.","وفي قلب هذا التحول، جاءت إعلانات \"HUMAIN\" لتكشف عن توجه يتجاوز تقديم نماذج الذكاء الاصطناعي إلى بناء منظومة متكاملة تشمل القدرة الحوسبية ومراكز البيانات والبنية التحتية والنماذج والتطبيقات، وفي هذا الإطار، أعلنت \"HUMAIN\" و\"Together AI\" التعاون لتوفير قدرات للذكاء الاصطناعي بسعة 55 ميجاوات، إلى جانب إنشاء مركز بيانات جديد في المملكة بسعة 250 ميجاوات."]','التقنية','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2668424?type=news&uuid=N2668424','https://spa.gov.sa/ar/N2668424?type=news&uuid=N2668424','N2668424','N2668424','','الرياض','2026-09-03T12:31:00.000Z',NULL,'2026-09-03T20:30:49.871Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10725293.jpg','/api/media/cd4366eb-1a05-4d66-abc6-b2047ca9bb1b','/api/media/cd4366eb-1a05-4d66-abc6-b2047ca9bb1b?variant=thumbnail','علوم وتقنيات / من الحدث إلى الأثر.. حكاية تتجاوز أيام "ليب 2026" الأربعة',1600,2400,'valid','published','archived','valid',54,'5dccced5e519d72fe9ce476e29fe9ecdea46014a1b4f15d0a5bfdc52661380e3','27ceb028dc829a71f6b10c91f98d2b7db84cc62ed64caf848c8d57e883bb3862',NULL,'2026-09-03T20:30:49.871Z','2026-10-07T20:24:32.525Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة AWS عن إطلاق أول","الاقتصاد والأسواق","التقنية والتحول الرقمي","الرياض"]','["شركة AWS عن إطلاق أول","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T19:42:47.751Z',200,51,0,'source_article_available','',NULL,NULL,'body:565cba6425ed939c1abeacaa67f1043a73803e844dcb1cb817efa5e41e57d0e6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('32b2e397-364c-4eaf-9b46-ba8482ab398e','news-32b2e397-364c-4eaf-9b46-ba8482ab398e','رسوم الأرض البيضاء تغلق أبواب التحايل وتفتح طريق التطوير','رسوم الارض البيضاء تغلق ابواب التحايل وتفتح طريق التطوير','لهذا جاءت رسوم الأراضي البيضاء لتحفيز المالك على اتخاذ قرار اقتصادي: إما أن يطور الأرض، وإما أن يتحمّل تكلفة إبقائها غير مستغلة، وإما أن يبيعها بعد تسوية الالتزامات المترتبة عليها.','["معاناة عاشها الوطن مع مساحات الأراضي الشاسعة المتروكة لسنوات طويلة ساكنة تحت الشمس، لا عمرانَ فوقها، ولا نشاطَ اقتصادياً حولها، ولا قيمةَ مضافةً تتحقق للمجتمع من وجودها. تقضم أوصال المدن، وترفع أسعار السكن، وتشوّه المنظر العام، وتحد من جودة الحياة.","ترتفع قيمتها مع نمو المدن وتوسع الطلب، فتتحوّل الأرض من أصل يفترض أن يدخل دورة التنمية إلى أداة للانتظار والمضاربة، ويصبح ارتفاع السعر بمرور الزمن هو العائد الأساسي من الاحتفاظ بها.","هذه المعادلة تقف خلف التطور المتواصل لمنظومة رسوم الأراضي البيضاء، وتمنح القرار الجديد لمجلس الوزراء أهمية تتجاوز مجرد إجراء إداري يتعلق بتوثيق نقل الملكية وعدم توثيق أي تصرف عقاري ناقل لملكية أرض خاضعة لأحكام نظام رسوم الأراضي البيضاء والعقارات الشاغرة إلا بعد التحقق من سداد الرسوم المستحقة عليها، ليصبح نقل الملكية مرتبطاً بتسوية الالتزام المالي، فلا يتخلص المالك من عبء الرسوم بمجرد نقل الأرض إلى شخص آخر. الملكية العقارية حق أصيل تحميه الأنظمة، لكن هذا الحق يتحرك داخل منظومة اقتصادية واجتماعية أوسع.","الأرض الواقعة داخل النطاق العمراني جزء من مدينة تتوسع، وشبكات طرق تمتد، وخدمات عامة تُقام، وسكان يبحثون عن مساكن، ومستثمرين يبحثون عن فرص، واقتصاد يحتاج إلى أصول تدخل دورة الإنتاج.","لهذا جاءت رسوم الأراضي البيضاء لتحفيز المالك على اتخاذ قرار اقتصادي: إما أن يطور الأرض، وإما أن يتحمّل تكلفة إبقائها غير مستغلة، وإما أن يبيعها بعد تسوية الالتزامات المترتبة عليها. صيغة تضيق مساحة المناورة أمام من يحتفظ بالأرض سنوات، ثم ينقل ملكيتها لتبدأ دورة جديدة من الالتفاف على الالتزامات، فلا يعود تغيير الاسم في الوثيقة وسيلة لإسقاط المستحقات.","فلا يمكن أن يكون تغيير المالك بديلاً عن الوفاء بالالتزام، هذه نقطة مهمة في بناء سوق عقارية أكثر انضباطاً، فالرسوم لا تستهدف تحصيل الأموال، بل تستهدف تغيير السلوك الاقتصادي، لتتحوّل الرسوم إلى حافز اقتصادي لإعادة توجيه رأس المال العقاري نحو النشاط المنتج.","الاقتصاد لا يستفيد من أصل ترتفع قيمته على الورق، بينما يظل مجمّداً خارج دورة الإنتاج، القيمة الحقيقية تظهر عندما تتحوّل الأرض إلى حياة، فزيادة الأراضي المطروحة للتطوير تساعد في تخفيف الاختناقات التي ترفع تكلفة الحصول على الأرض.","الدولة تريد سوقاً تتحرك فيها الأصول، لا سوقاً تتراكم فيها الملكيات دون إنتاج."]','المجتمع','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264094','https://www.okaz.com.sa/articles/authors/2264094','','https://www.okaz.com.sa/articles/authors/2264094','نجيب يماني','حائل','2026-09-02T18:00:00.000Z','Wed, 07 Oct 2026 19:43:55 GMT','2026-09-03T20:30:49.883Z','https://www.okaz.com.sa/okaz/uploads/authors/273.jpg?v=1763304641','/api/media/32b2e397-364c-4eaf-9b46-ba8482ab398e','/api/media/32b2e397-364c-4eaf-9b46-ba8482ab398e?variant=thumbnail','رسوم الأرض البيضاء تغلق أبواب التحايل وتفتح طريق التطوير',400,400,'valid','published','archived','valid',92,'398609db265e1e3ea626d45c33c36cfe11e41856cfc3454ff345f3cff63f69eb','faf74b96196054f6a0b538a5ed175e56b9734eafb6214b5fee1a489e18cca6e1','محدّث','2026-09-03T20:30:49.883Z','2026-10-07T20:24:32.529Z','','',0,0,'saudi_region','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','classified','','[{"category":"المناطق","score":3},{"category":"الاقتصاد","score":3},{"category":"أخبار السعودية","score":1.5}]','Updated','2026-10-07T19:43:57.711Z',200,66,0,'source_content_changed','',NULL,NULL,'body:ea55bffaa001cb7a3a95abc199afcdf3dbe61c8fe09fb3c237daa5b746351b1a','Wed, 07 Oct 2026 19:43:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ffb2c411-f297-44bb-b56b-6b3ae894de22','news-ffb2c411-f297-44bb-b56b-6b3ae894de22','محافظ الطائف يُطلق 10 كائنات فطرية في متنزه سيسد الوطني','محافظ الطائف يطلق 10 كائنات فطريه في متنزه سيسد الوطني','واطّلع سمو محافظ الطائف خلال الزيارة على مشروع المركز البحثي المتخصص في أبحاث الغابات بالمتنزه، واستمع إلى عرض تفصيلي عن مستهدفاته ودوره في تطوير الدراسات الداعمة لتنمية الغابات واستدامة الغطاء النباتي.','["أطلق الأمير فواز بن سلطان بن عبدالعزيز محافظ الطائف، 10 كائنات فطرية في متنزه سيسد الوطني بالطائف، وذلك ضمن برامج إعادة توطين الأنواع الفطرية في موائلها الطبيعية وتعزيز التنوع الأحيائي، التي ينفذها المركز الوطني لتنمية الحياة الفطرية بالتعاون مع المركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر.","وشملت عملية الإطلاق 3 من ظباء الإدمي، و4 من النعام أحمر الرقبة، و3 أرانب برية، بعد استكمال متطلبات الجاهزية والتأكد من ملاءمة الموقع، بما يدعم تكيّفها واستقرارها في المتنزه، ويعزز فرص تكوين جماعات فطرية مستدامة في موائل تتناسب مع طبيعة كل نوع.","وأكد الرئيس التنفيذي للمركز الوطني لتنمية الحياة الفطرية الدكتور محمد قربان، أن هذا الإطلاق يمثل استكمالاً لبرامج المركز في إعادة توطين الأنواع الفطرية، ويجسّد أهمية العمل المشترك مع الجهات الوطنية المعنية بتنمية الموائل، مشيراً إلى أهمية عمليات الإطلاق في المتنزهات الوطنية بوصفها ممرات آمنة للكائنات الفطرية بين المحميات الطبيعية، إلى جانب إسهامها في تعزيز الجاذبية السياحية للمتنزهات.","وأضاف أن نجاح برامج إعادة التوطين يرتبط بتكامل مراحل العمل، بدءاً من اختيار الأنواع والمواقع الملائمة، مروراً بالتأهيل والإطلاق، ووصولاً إلى الرصد والمتابعة، بما يتيح تقييم النتائج وتطوير البرامج المستقبلية وفق أسس علمية تدعم استدامة التنوع الأحيائي في المملكة.","ويأتي هذا الإطلاق امتداداً للتعاون القائم بين المركز الوطني لتنمية الحياة الفطرية والمركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر، وتكاملاً بين جهود تنمية الموائل الطبيعية وبرامج إكثار الكائنات الفطرية وإعادة توطينها، بما يعزز القيمة البيئية للمتنزهات الوطنية."]','الوظائف وسوق العمل','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wEGGLkI','https://sabq.org/article/wEGGLkI','','https://sabq.org/article/wEGGLkI','فهد العتيبي','','2026-09-03T11:03:00.000Z','2026-09-03T14:03:00.000Z','2026-09-03T20:30:50.110Z','https://media.sabq.org/news/2026/09/1979064d-5366-452e-9186-9a4e05dd026e/w1600.webp','/api/media/ffb2c411-f297-44bb-b56b-6b3ae894de22','/api/media/ffb2c411-f297-44bb-b56b-6b3ae894de22?variant=thumbnail','محافظ الطائف يُطلق 10 كائنات فطرية في متنزه سيسد الوطني',1600,1067,'valid','published','archived','valid',46,'a0581427c73f3beaf0133211b0ccf58590bd22a4d8024cb716231bc665bedd2d','11f95f9d53c04ec89ddb9964beb074e29f51affa197f430a8601c532d18d8ce7','محدّث','2026-09-03T20:30:50.110Z','2026-10-07T20:24:32.534Z','','',0,0,'saudi_national','مهم',74,NULL,0,0,0,'',NULL,NULL,NULL,'["المجتمع"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:15.395Z',200,49,0,'source_article_available','',NULL,NULL,'body:c32f1e044f7e83384aad263056759bd8aa6f15a39450327d6218c32c4467c6d2','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d7e4e4c5-0922-476f-a4d9-be3ff2e10488','news-d7e4e4c5-0922-476f-a4d9-be3ff2e10488','سيناريو و«إحراج»','سيناريو و احراج','أتابع بين الحين والآخر الجدل المستمر حول الدراما السعودية ومدى قُرْبِها من الواقع، وقدرتها على تقديم القصة الحقيقية والأصيلة للمجتمع السعودي. هذا الحوار الفاحص المعمّق ليس ترفاً فكرياً، بل دليلٌ جليٌّ على وعيٍ جمعي بأهمية الدراما؛ بصفتها إحدى أكثر لغات التواصل الإنساني تأثيراً بين الشعوب.','["أتابع بين الحين والآخر الجدل المستمر حول الدراما السعودية ومدى قُرْبِها من الواقع، وقدرتها على تقديم القصة الحقيقية والأصيلة للمجتمع السعودي. هذا الحوار الفاحص المعمّق ليس ترفاً فكرياً، بل دليلٌ جليٌّ على وعيٍ جمعي بأهمية الدراما؛ بصفتها إحدى أكثر لغات التواصل الإنساني تأثيراً بين الشعوب. فالدراما لم تعد مجرد أداةٍ للترفيه وقضاء الوقت، بل غدت إحدى أقوى أدوات القوة الناعمة التي تُبْرِز ثقافات الأمم، وتنقُل حكاياتها وثراءها الإنساني إلى العالم.","وبحكم عملي واهتمامي بالمجال الإعلامي والثقافي والأدبي، أجد نفسي على تماسٍ دائم مع هذا النقاش؛ فشغفي الأدبي والروائي يتقاطع حتماً مع العمل الدرامي، فضلاً عن عملي على تحويل بعض أعمالي الأدبية إلى معالجات درامية. ومن هذا المنظور، أرى أن تشخيص واقع الدراما السعودية، وتحديد نقاط قوتها وضعفها، يجب أن يبدأ من النواة الأولى: القصة وكُتّابها.","القصة هي الأساس الصلب الذي تُبنى عليه الصنعة الدرامية بكامل تفاصيلها. وإذا ما تزعزع هذا العمود الفقري، يتداعى البنيان مهما بلغت جودة الإنتاج. إننا اليوم في أمسّ الحاجة إلى قصصٍ تشبهنا، تعبّر عن روحنا وتفاصيل حياتنا اليومية، بدلاً من استيراد حكاياتٍ من ثقافاتٍ أخرى ومحاولة إسقاطها قسراً وإلباسها الزي السعودي.","التعاون مع الكُتّاب والمخرجين السعوديين يمثّل خطوة استراتيجية لبناء صناعةٍ تمتلك رسالةً مؤثرة، لا تخاطب الداخل فحسب، بل تنطلق بثقة نحو المحافل الدولية لتبرز الحراك والتغيير الكبيرين اللذين تشهدهما المملكة. لقد نجحت هوليوود وبوليوود في وضع بصماتٍ عالمية خالدة بفضل أصلية حكاياتهما. والمملكة اليوم، بوصفها قائدة للعالمين العربي والإسلامي والحاضنة لتاريخهما الممتد، أولى بأن تصنع دراما تعكس هذا الثقل التاريخي والثقافي.","ولتحقيق هذه النهضة المنشودة، تحتاج الدراما السعودية إلى تفعيل دور حيوي يُشبه دور «رئيس التحرير» في الصحافة، أو ما يُعرف عالمياً بـ«المُبتكِر» (Creator). إنه الشخص الذي يستوعب قيمة الأبعاد البصرية والثقافية للنص، ويجيد اختيار الأفكار وتوزيع الأدوار وإدارة الرؤية الإبداعية من الفكرة وحتى الشاشة. غياب هذا الدور التوجيهي يترك فراغاً كبيراً، وبوجوده تستقيم الصنعة وتنطلق الدراما السعودية نحو أفقٍ أكثر نضجاً وتأثيراً.","I occasionally follow the ongoing debate about Saudi drama and how close it is to reality, as well as its ability to present the true and authentic story of Saudi society. This deep, probing dialogue is not an intellectual luxury, but a clear indication of a collective awareness of the importance of drama; as one of the most influential languages of human communication among peoples. Drama is no longer just a tool for entertainment and passing time; it has become one of the strongest tools of soft power that highlights the cultures of nations and conveys their stories and human richness to the world.","Due to my work and interest in the media, cultural, and literary fields, I find myself constantly in touch with this discussion; my literary and narrative passion inevitably intersects with dramatic work, in addition to my efforts to adapt some of my literary works into dramatic treatments. From this perspective, I believe that diagnosing the reality of Saudi drama and identifying its strengths and weaknesses should start from the very core: the story and its writers.","The story is the solid foundation upon which the entire craft of drama is built. If this backbone is shaken, the structure collapses regardless of the quality of production. Today, we are in dire need of stories that resemble us, that express our spirit and the details of our daily lives, rather than importing tales from other cultures and forcibly trying to impose them and dress them in Saudi attire."]','أخبار السعودية','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264093','https://www.okaz.com.sa/articles/authors/2264093','','https://www.okaz.com.sa/articles/authors/2264093','سلطان السعد القحطاني','عسير','2026-09-02T18:00:00.000Z','Wed, 07 Oct 2026 19:43:57 GMT','2026-09-04T05:00:21.491Z','https://www.okaz.com.sa/uploads/authors/1785.jpg','/api/media/d7e4e4c5-0922-476f-a4d9-be3ff2e10488','/api/media/d7e4e4c5-0922-476f-a4d9-be3ff2e10488?variant=thumbnail','سيناريو و«إحراج»',600,600,'valid','published','archived','valid',44,'7fcfebcc7104101c1482b99c1601ad8562c5c965807871d762119370fb9636a6','3f0d557b749f11c1b6544bcea52d8b073ee964109192cc764479b23b190e5c14','محدّث','2026-09-03T20:30:50.116Z','2026-10-07T19:43:59.299Z','','',0,0,'saudi_region','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس التحرير في الصحافة أو"]','["رئيس التحرير في الصحافة أو"]','needs_review','below_category_threshold','[{"category":"الثقافة","score":3},{"category":"المجتمع","score":1.5},{"category":"المناطق","score":0}]','Updated','2026-10-07T19:43:59.299Z',200,66,0,'source_content_changed','',NULL,NULL,'body:49309a5ae2e9932ef344278febfc9f74912a88604ce500031088a6e1269fa534','Wed, 07 Oct 2026 19:43:57 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a9e304fa-539b-4af9-addd-88377b197264','news-a9e304fa-539b-4af9-addd-88377b197264','«تنمية البكيرية» تشكّل مجلس إدارتها الجديد برئاسة "الخزيم"','تنميه البكيريه تشكل مجلس ادارتها الجديد برئاسه الخزيم','أعلنت جمعية التنمية الأهلية بمحافظة البكيرية تشكيل مجلس إدارتها الجديد، برئاسة الأستاذ عبدالملك بن ناصر الخزيم، وعضوية كل من الأستاذ محمد بن عبدالله المزيني، وعمر بن محمد الفريح، والدكتور عبدالعزيز بن عبدالله النملة، والدكتور عبدالله بن علي المحسن.','["ويأتي تشكيل المجلس الجديد امتدادًا لمسيرة الجمعية في خدمة المجتمع المحلي، وتعزيز برامج التنمية الاجتماعية، ودعم المبادرات والبرامج التي تسهم في تحقيق أثر تنموي مستدام لأهالي المحافظة.","وبهذه المناسبة، عبّر رئيس مجلس الإدارة عبدالملك الخزيم عن اعتزازه بالثقة، مؤكدًا أن المجلس يتطلع خلال المرحلة المقبلة إلى مواصلة تطوير أعمال الجمعية، وتوسيع نطاق برامجها ومبادراتها، وتعزيز شراكاتها مع مختلف القطاعات بما يحقق أهدافها ورسالتها المجتمعية.","وقال: نسأل الله أن يعيننا على أداء الأمانة، وأن نكون عند حسن الظن، وأن نعمل بروح الفريق الواحد لخدمة محافظة البكيرية وأهلها، وتقديم مبادرات وبرامج نوعية تلامس احتياجات المجتمع وتحقق أثرًا مستدامًا.","كما قدّم \"الخزيم\" شكره وتقديره لرئيس وأعضاء مجلس الإدارة السابق على ما بذلوه من جهود خلال فترة عملهم، وما أسهموا به في خدمة الجمعية ودعم برامجها ومبادراتها، مؤكدًا أن ما تحقق يمثل أساسًا يُبنى عليه لمواصلة مسيرة التطوير والإنجاز."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/society/o56rn7hv9','https://ajel.sa/society/o56rn7hv9','https://ajel.sa/society/o56rn7hv9','https://ajel.sa/society/o56rn7hv9','فريق التحرير','','2026-09-03T12:34:00.000Z','Wed, 07 Oct 2026 19:42:18 GMT','2026-09-03T20:30:50.578Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/150425-crop-e8xXhe_Q.jpg','/api/media/a9e304fa-539b-4af9-addd-88377b197264','/api/media/a9e304fa-539b-4af9-addd-88377b197264?variant=thumbnail','«تنمية البكيرية» تشكّل مجلس إدارتها الجديد برئاسة "الخزيم"',1200,675,'valid','published','archived','valid',41,'a6041d32446d35b7be94cab1223d6ebfb2e79ea06d2d78706586b9db7e898e3a','da8cab9d2a83113b56f4591c68d027c8131cb4f34c9f663095521806699fbdca','محدّث','2026-09-03T20:30:50.578Z','2026-10-07T20:24:32.542Z','','',0,0,'international','عادي',52,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إدارتها الجديد برئاسة الخزيم","رئيس مجلس الإدارة عبدالملك الخزيم","الاقتصاد والأسواق"]','["مجلس إدارتها الجديد برئاسة الخزيم","رئيس مجلس الإدارة عبدالملك الخزيم","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:20.536Z',200,49,0,'source_content_changed','',NULL,NULL,'body:23e41670c81ec47fe688d05534a71f9c2938fb033bfbd465100dd8e6b28b3d97','Wed, 07 Oct 2026 19:42:18 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f8356490-152d-428b-a302-0b0d745eb8d4','news-f8356490-152d-428b-a302-0b0d745eb8d4','نفس النبوءة بعد 95 عامًا!','نفس النبوءه بعد 95 عاما','نتيجة لذلك التفاؤل، توقع أن يصبح الإنسان قادرًا على إنتاج احتياجاته بجهد أقل، حيث قال: «ثلاث ساعات من العمل يوميًا تكفي تمامًا»، متصورًا أن أسبوع العمل قد ينخفض إلى نحو 15 ساعة فقط. عاد إيلون ماسك بعد 95 عاما ليقدم رؤية قريبة الشبه برؤية كينز، لكن هذه المرة بلغة عصر الذكاء الاصطناعي والروبوتات.','["بينما كان العالم يدخل واحدة من أشد أزماته الاقتصادية في العام 1930، نشر الاقتصادي البريطاني جون ماينارد كينز مقالته الشهيرة «الإمكانات الاقتصادية لأحفادنا». على الرغم أن الكساد العظيم كان يضرب كبرى الاقتصادات حينها، إلا أن كينز كان يحاول النظر 100 عام إلى الأمام، متسائلًا عن شكل الحياة الاقتصادية في عام 2030.","كان كينز شديد التفاؤل بقدرة تراكم رأس المال والتقدم التقني على رفع الإنتاجية ومستويات المعيشة. نتيجة لذلك التفاؤل، توقع أن يصبح الإنسان قادرًا على إنتاج احتياجاته بجهد أقل، حيث قال: «ثلاث ساعات من العمل يوميًا تكفي تمامًا»، متصورًا أن أسبوع العمل قد ينخفض إلى نحو 15 ساعة فقط. رأى أن الإنسان سيظل يمارس قدرًا محدودًا من العمل كي يشعر بالرضا الذاتي فقط.","عاد إيلون ماسك بعد 95 عاما ليقدم رؤية قريبة الشبه برؤية كينز، لكن هذه المرة بلغة عصر الذكاء الاصطناعي والروبوتات. في المنتدى الاستثماري السعودي-الأمريكي عام 2025، قال ماسك: «توقعي أن يصبح العمل اختياريًا»، وأكد أن العمل ذاته قد يتحول إلى نشاط يشبه ممارسة الرياضة أو زراعة الخضراوات في المنزل؛ يفعله الإنسان لأنه يستمتع به، لا لأنه يحتاج إليه لكسب رزقه. تستند رؤية ماسك على قاعدة أن الذكاء الاصطناعي والروبوتات البشرية سيوفران كثيرا من السلع والخدمات خلال فترة تتراوح بين 10 و20 عامًا، إلى درجة قد تجعل المال نفسه أقل أهمية.","بين تلك الرؤيتين التاريخ يعيد وعوده. اعتقد كينز أن الآلات ستمنح الإنسان مزيدًا من الوقت. واليوم يعتقد ماسك أن الذكاء الاصطناعي قد يعفيه من العمل تمامًا. لكن التجربة منذ عام 1930 تقول إن التقنية وحدها لا تصنع عصر الفراغ؛ فهي تزيد ما يستطيع الاقتصاد إنتاجه، أما تحويل هذه الزيادة إلى وقت ورفاه مشتركين فيبقى قرارًا اقتصاديًا واجتماعيًا، وليس نتيجة تقنية حتمية.","إلى هذه اللحظة، لم تتحقق رؤية كينز، ولا تزال رؤية ماسك مجرد توقع للمستقبل. صحيح أن الإنتاجية ومستويات المعيشة ارتفعت بصورة كبيرة، وأن متوسط ساعات العمل انخفض في عدد من الدول، إلا أن العالم لم يقترب من أسبوع العمل المكون من 15 ساعة. تشير منظمة التعاون الاقتصادي والتنمية إلى أن مكاسب الإنتاجية لم تتحول بالقدر الذي توقعه كينز إلى وقت فراغ إضافي للعاملين بدوام كامل؛ فقد اختار الناس، أو دفعتهم الأنظمة الاقتصادية، إلى الحصول على أجور واستهلاك أعلى بدلًا من خفض ساعات العمل جذريًا.","لم يكن خطأ كينز في تقدير قدرة التقنية على زيادة الإنتاج، فقد كان قريبًا من الصواب في ذلك، وإنما في افتراضه أن ارتفاع الإنتاجية سيقود تلقائيًا إلى تخفيض ساعات الأعمال والاكتفاء. الاحتياجات الأساسية قد تكون محدودة، لكن الرغبات النسبية لا تتوقف؛ كلما ارتفع مستوى المعيشة ظهرت سلع وخدمات جديدة وتحولت بعض الكماليات إلى ضروريات. هكذا استخدم المجتمع التقنية لإنتاج المزيد من السلع والخدمات، وليس فقط للعمل ساعات أقل.","كلنا نتذكر الثورة الصناعية في القرن التاسع عشر وما ترافق معها من طفرة إنتاجية للسلع، لكن المفارقة أن مكاسب تلك الإنتاجية تركزت في يد فئة محدودة، وحُرمت منها فئة أخرى. من هذا المنطلق، الآلة قد تنتج وفرة اقتصادية، لكن ملكية الآلة هي من تحدد من يحصل على عوائدها، وبذلك نستطيع القول إن نظرة إيلون ماسك إلى هذه اللحظة أغفلت التصور الخاص بمسألة توزيع مكاسب الإنتاجية. إذا تركزت تقنيات الذكاء الاصطناعي والروبوتات في أيدي عدد محدود من الشركات والأفراد، فقد يصبح العمل اختياريًا لمالكي تلك التقنيات، بينما يصبح فقدان الوظيفة تهديدًا لدخل بقية المجتمع. هنا تتضح لنا أن رؤية ماسك أكثر جرأة، لكنها ليست مكتملة اقتصاديًا. القول إن الروبوتات ستنتج كل ما نحتاج إليه، لا يشرح كيف سيحصل من لا يعمل على نصيبه من هذا الإنتاج. تحقق «العمل الاختياري» لا يحتاج إلى تقدم تقني فقط، بل إلى ترتيبات جديدة للدخل والضرائب والملكية وتوزيع عوائد رأس المال.","As the world was entering one of its most severe economic crises in 1930, British economist John Maynard Keynes published his famous article \"The Economic Possibilities for Our Grandchildren.\" Although the Great Depression was hitting major economies at the time, Keynes was trying to look 100 years ahead, questioning what economic life would be like in 2030."]','الذكاء الاصطناعي','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264092','https://www.okaz.com.sa/articles/authors/2264092','','https://www.okaz.com.sa/articles/authors/2264092','علي محمد الحازمي','الرياض','2026-09-02T18:00:00.000Z','Wed, 07 Oct 2026 19:43:59 GMT','2026-09-03T21:25:55.306Z','https://www.okaz.com.sa/uploads/authors/1235.jpg','/api/media/f8356490-152d-428b-a302-0b0d745eb8d4','/api/media/f8356490-152d-428b-a302-0b0d745eb8d4?variant=thumbnail','نفس النبوءة بعد 95 عامًا!',600,600,'valid','published','archived','valid',54,'8d4663d8eec0c9c0f18afb033a5c16e5c2984040c287f679e134f1cbd8eb506f','26b05f680700a997079cf6316b9e620323411c4f2076bf5806fbbccf41257af1','محدّث','2026-09-03T20:30:50.699Z','2026-10-07T20:24:32.547Z','','',0,0,'saudi_region','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الاقتصاد والأسواق","التقنية والتحول الرقمي","الرياض"]','["الرياضة السعودية","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"المناطق","score":1.5},{"category":"أخبار السعودية","score":0}]','Updated','2026-10-07T19:44:01.308Z',200,68,0,'source_content_changed','',NULL,NULL,'body:0d4fce4aebc272291842a908c15a2241d0398cd559132bb8120d07cbb11a8801','Wed, 07 Oct 2026 19:43:59 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('548f807b-6b2b-4b72-bb25-1f4b3ce7e57f','news-548f807b-6b2b-4b72-bb25-1f4b3ce7e57f','بتكوين تفشل في الحفاظ على مستوى 80 ألف دولار','بتكوين تفشل في الحفاظ علي مستوي 80 الف دولار','تصطدم بتكوين بصعوبة الحفاظ على مستوى 80 ألف دولار، في ظل ضعف الطلب الأمريكي واستمرار تقلب تدفقات المستثمرين، بينما تضيف توقعات ارتفاع أسعار الفائدة ضغوطًا جديدة على العملة المشفرة.','["وتكشف حركة صناديق بتكوين الفورية المتداولة في البورصة ب الولايات المتحدة عن تذبذب واضح في الطلب؛ فعلى الرغم من ارتفاع التدفقات إليها خلال أغسطس، سجلت الصناديق يومين من التدفقات الخارجة الكبيرة خلال الأسبوع الماضي.","ولا تزال مؤشرات السوق الأمريكية تعكس ضعف الإقبال على بتكوين، إذ بقي متوسط علاوة «كوين بيس» لسبعة أيام سالبًا لأكثر من أربعة أشهر. ويقيس هذا المؤشر الفارق بين أسعار بتكوين على أكبر بورصة للعملات المشفرة في الولايات المتحدة والمنصات الدولية، كما أن موجة الصعود الأخيرة لم تدفعه إلى المنطقة الموجبة.","وتظهر بيانات «جلاس نود» أن متوسط التدفقات إلى صناديق بتكوين المتداولة بلغ 290 مليون دولار يوميًا خلال موجة الصعود، لكن نشاط التداول ظل أقل من مستويات موجات صعود سابقة.","وترى الشركة أن التدفقات التي تحركها أخبار منفردة مرتبطة بالسياسات، من دون وجود زخم أوسع في السوق، غالبًا ما تتزامن مع تحولات قصيرة الأجل في الأسعار، ما يضعف الرهان على استمرار الارتفاع بالوتيرة نفسها.","وفي سوق المشتقات، يرى توني سيكامور، المحلل لدى «آي جي أستراليا»، أن جزءًا كبيرًا من صعود بتكوين خلال أغسطس جاء نتيجة تغطية مراكز البيع على المكشوف، مشيرًا إلى أن ذلك جعل صافي المراكز قريبًا من الصفر.","ويأتي ذلك في وقت أصبحت فيه البيئة الاقتصادية الكلية أقل دعمًا للعملة، بعدما أعاد خطاب متشدد لرئيس الاحتياطي الفيدرالي الأميركي كيفن وارش خلال ندوة جاكسون هول الأسبوع الماضي إحياء توقعات رفع أسعار الفائدة قريبًا لاحتواء التضخم. وتنعقد اللجنة الفيدرالية للسوق المفتوحة يومي 15 و16 سبتمبر.","وتواجه بتكوين أيضًا مستوى سعريًا قد يحد من صعودها، إذ تقدر «غلاس نود» أن حائزي العملة على المدى الطويل يستهدفون نطاقًا بين 83 ألف دولار و86 ألف دولار لبيع حيازاتهم."]','الاقتصاد','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/d1gshklhj','https://ajel.sa/economy/d1gshklhj','https://ajel.sa/economy/d1gshklhj','https://ajel.sa/economy/d1gshklhj','فريق التحرير','','2026-09-03T12:34:00.000Z','Wed, 07 Oct 2026 19:42:36 GMT','2026-09-03T20:30:50.927Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A8%D8%AA%D9%83%D9%88%D9%8A%D9%86-NA8nI-Ms.jpg','/api/media/548f807b-6b2b-4b72-bb25-1f4b3ce7e57f','/api/media/548f807b-6b2b-4b72-bb25-1f4b3ce7e57f?variant=thumbnail','بتكوين',1200,675,'valid','published','archived','valid',40,'b321cd232c6412b5115b556a9fa656840cf357cd80d1e305df0ba2eeeabe5187','c0b7754c534de701f29ba566cacaffc44b06ddfd49ef947ec83e7ae7df54101c','محدّث','2026-09-03T20:30:50.927Z','2026-10-07T20:24:32.552Z','','',0,0,'international','عادي',43,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","الرياضة السعودية","الاقتصاد والأسواق","الولايات المتحدة"]','["الرياضة السعودية","الاقتصاد والأسواق","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:42:37.658Z',200,49,0,'source_content_changed','',NULL,NULL,'body:e17f8ae2d975b5c9eba61a7154615496dbcf010f67d8a77b2b041be281a4e3e6','Wed, 07 Oct 2026 19:42:36 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b07481b1-e4ad-4334-805c-99cc15be1752','news-b07481b1-e4ad-4334-805c-99cc15be1752','بيئي / نجم سهيل.. طالع فلكي يسطع بالأفق الجنوبي للمملكة ويقود الأجواء نحو الاعتدال الخريفي','بيئي نجم سهيل طالع فلكي يسطع بالافق الجنوبي للمملكه ويقود الاجواء نحو الاعتدال الخريفي','وفي هذا الصدد، بيّن الباحث في التقويم الزراعي محمد الوادعي أن رؤية نجم سهيل يتبعها دخول منازل فلكية متلاحقة ترسم الملامح المناخية والبيئية للمنطقة، لافتًا إلى أن منزلة "الجبهة" التي تبدأ من 6 إلى 18 سبتمبر تعد البوابة الفعلية لفصل الخريف وتحسن الطقس مساءً، تلحق بها منزلة "الزبرة" من 19 سبتمبر إلى 1 أكتوبر ويتساوى خلالها الليل والنهار مع برودة ملموسة في…','["أبها 20 ربيع الأول 1448 هـ الموافق 02 سبتمبر 2026 م واس يُشكّل ظهور نجم \"سهيل\" اليماني في الجهة الجنوبية من سماء المملكة العربية السعودية مؤشرًا فلكيًا رئيسًا لانتهاء موجات الحرّ اللاهب وبداية تبدّل الطقس نحو الاعتدال، مما يبشّر بانخفاض تدريجي في درجات الحرارة يتزامن مع منزلة \"الطرفة\" المستمرة هذه الأيام وحتى الخامس من سبتمبر، التي تُعرف بامتزاج دفء النهار باعتدال أجواء الليل ونشاط التيارات الرطبة فوق القمم الجبلية.","وقال \"إن هذه الأيام تعدّ التوقيت المثالي لمزارعي السهول والمدرجات الجبلية لتهيئة الأراضي وتسميدها وبذر محاصيل الخضراوات الشتوية والورقيات مستفيدين من هبوط مستويات التبخر، مشيرًا إلى ما يتداوله مجتمع الجنوب في موروثه الشعبي من أمثال توثق هذه المرحلة مثل \"إذا طلع سهيل غار السيل\" في دلالة على تزايد فرص الأمطار الموسمية الغزيرة وتغير طبيعة الطقس.","وتلقي هذه التبدلات الكونية بظلالها على تضاريس الجنوب، إذ تسهم الرياح الرطبة المصاحبة لسهيل في تنشيط السحب الركامية وهطول الأمطار على مرتفعات عسير وجازان والباحة، بجانب تشكل غطاء ضبابي كثيف صباحًا نتيجة الفوارق الحرارية بين النهار والليل، مما ينعش الغطاء النباتي ويحفز النشاط الزراعي عبر زيادة رطوبة التربة في السهول والمدرجات الجبلية. // انتهى // 12:24 ت مـ 0075"]','البيئة والمناخ','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2666949?type=news&uuid=N2666949','https://spa.gov.sa/ar/N2666949?type=news&uuid=N2666949','N2666949','N2666949','','عسير','2026-09-02T06:24:00.000Z',NULL,'2026-09-03T20:30:50.933Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10712281.jpg','/api/media/b07481b1-e4ad-4334-805c-99cc15be1752','/api/media/b07481b1-e4ad-4334-805c-99cc15be1752?variant=thumbnail','بيئي / نجم سهيل.. طالع فلكي يسطع بالأفق الجنوبي للمملكة ويقود الأجواء نحو الاعتدال الخريفي',1600,885,'valid','published','archived','valid',50,'f26ca298d586cb439051f69a44a4fbb5efded44d91e0f05e7d1f82a268b912a4','1d8de1872acda7aebf88659dd96ef3b8c9279fa5afe0e47242b6d97826d573a9',NULL,'2026-09-03T20:30:50.933Z','2026-10-07T20:24:32.556Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس ا لانتهاء موجات الحر","الطقس والمناخ","عسير","جازان","الباحة"]','["رئيس ا لانتهاء موجات الحر","الطقس والمناخ"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المجتمع","score":1.5},{"category":"السياسة","score":0}]','Active','2026-10-07T19:44:40.454Z',200,72,0,'source_article_available','',NULL,NULL,'body:eecc083856e54b85702449dbe136d9f6a3287137c4db6d3865dcfece30d55971','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1c39d0a1-73b2-424b-9327-a803cccb1cb9','news-1c39d0a1-73b2-424b-9327-a803cccb1cb9','«فرح» تتحدث باسم الحكومة.. الأردن يطلق أول ناطق رقمي بالذكاء الاصطناعي','فرح تتحدث باسم الحكومه الاردن يطلق اول ناطق رقمي بالذكاء الاصطناعي','وظهرت «فرح» في فيديو ترويجي رسمي من باحة رئاسة الوزراء، قدمت خلاله نفسها باعتبارها الناطق الرقمي باسم الحكومة، وأعلنت أن المبادرة تمثل خطوة سباقة هي الأولى من نوعها في المنطقة والعالم.','["أطلقت الحكومة الأردنية شخصية افتراضية مطوّرة بالذكاء الاصطناعي باسم «فرح»، لتتولى مهمة الناطق الرقمي باسم الحكومة، في خطوة تهدف إلى تطوير أدوات التواصل الرسمية وإيصال المعلومات والقرارات إلى المواطنين عبر المنصات الرقمية.","وتتحدث الشخصية الافتراضية بلهجة أردنية عامية مبسطة، على أن تتواصل مع الجمهور مستقبلًا عبر منصات التواصل الاجتماعي وتطبيق «واتساب»، بهدف تقديم المعلومات الحكومية بطريقة واضحة وشفافة وبسيطة.","وتتولى «فرح» تقديم معلومات عن المشروعات المرتبطة برؤية التحديث الاقتصادي، إلى جانب التطورات والمشروعات الحكومية في قطاعات الصحة والتعليم والبنية التحتية، فضلًا عن القرارات التي تمس الحياة اليومية للمواطنين.","كما ستعمل الشخصية الرقمية على نقل بعض قرارات مجلس الوزراء وشرحها للجمهور، في إطار توجه الحكومة إلى إيصال المعلومات الرسمية بأسرع وقت ممكن وبأسلوب مبسط.","وقال الناطق الرسمي باسم الحكومة ووزير الاتصال محمد المومني إن إطلاق خدمة الناطق الرقمي «فرح» يأتي ضمن سعي الحكومة إلى توظيف التكنولوجيا الرقمية وأدوات الذكاء الاصطناعي في التواصل، وشرح القرارات والسياسات الحكومية وإتاحة المعلومات.","وأوضح المومني أن «فرح» ستكون إحدى أدوات التواصل الحكومية الرقمية، وتهدف إلى تزويد المواطنين والمهتمين بالمعلومات."]','الذكاء الاصطناعي','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/usv9aant6','https://ajel.sa/international/usv9aant6','https://ajel.sa/international/usv9aant6','https://ajel.sa/international/usv9aant6','فريق التحرير','','2026-09-03T12:34:00.000Z','Wed, 07 Oct 2026 19:42:39 GMT','2026-09-03T20:30:50.950Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D9%81%D8%B1%D8%AD-ltjKY8VR.jpg','/api/media/1c39d0a1-73b2-424b-9327-a803cccb1cb9','/api/media/1c39d0a1-73b2-424b-9327-a803cccb1cb9?variant=thumbnail','فرح',1200,675,'valid','published','archived','valid',47,'3a05b16b9e56954189710fe34768165e53c126d265ef59454e9dd14c0270f081','07d27217861299ba1b5c5124dbe124d5d9f4dfc5074c0e424eca1b589b0324e9','محدّث','2026-09-03T20:30:50.950Z','2026-10-07T20:24:32.560Z','','',0,0,'saudi_national','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","مجلس الوزراء وشرحها للجمهور في","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["مجلس الوزراء وشرحها للجمهور في","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:41.104Z',200,49,0,'source_content_changed','',NULL,NULL,'body:f65e12e226e1bdc163db7d5ba4739f265f21bf15bf58d587cd22ac9f9cce184c','Wed, 07 Oct 2026 19:42:39 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ae3f3010-ff45-49fe-a4e6-4afc21bd0fec','news-ae3f3010-ff45-49fe-a4e6-4afc21bd0fec','سياحة وترفيه / "أعمق مما تراه".. حملة توعوية تكشف أدوارًا تنظيمية تسبق التجربة السياحية الساحلية','سياحه وترفيه اعمق مما تراه حمله توعويه تكشف ادوارا تنظيميه تسبق التجربه السياحيه الساحليه','جدة 20 ربيع الأول 1448 هـ الموافق 02 سبتمبر 2026 م واس أطلقت الهيئة السعودية للبحر الأحمر حملتها التوعوية "أعمق مما تراه"؛ بهدف التعريف بالمنظومة التنظيمية التي تقوم عليها الأنشطة السياحية البحرية والملاحية على سواحل البحر الأحمر، وإبراز دور الهيئة بوصفها الجهة المنظّمة والممكّنة لقطاع السياحة الساحلية، وتعزيز الوعي بما يسبق التجربة من أطر وتراخيص…','["وتنطلق الحملة من فكرة محورية مفادها أن التجربة السياحية لا تبدأ من الوجهة ذاتها، بل من الإطار التنظيمي الذي تقوم عليه؛ إذ تسبق كل نشاط سياحي بحري منظومة متكاملة من اللوائح والاشتراطات والتراخيص والتصاريح، تُبنى على أسس فنية ومعايير دولية، وتُترجم إلى إجراءات واضحة تمكّن القطاع من النمو بكفاءة واستدامة.","وتؤكد الهيئة أن هذه المنظومة ليست إجراءً سابقًا على التشغيل ينتهي بصدور الرخصة، بل التزامًا ممتدًا يخضع لتحقق ميداني مستمر عبر زيارات الامتثال في المراسي والسفن ومواقع الأنشطة البحرية؛ بما يضمن مطابقة الواقع التشغيلي لما صدرت به التراخيص.","وتشمل المنظومة التنظيمية للهيئة الأنشطة البحرية والملاحية السياحية، دون اقتصار على نشاط أو حجم بعينه؛ فتخضع لها السفن السياحية (الكروز) والمراسي واليخوت والقوارب والشواطئ والأنشطة البحرية على اختلافها، وتتفاوت الاشتراطات بتفاوت طبيعة النشاط ومستوى المخاطر المرتبطة به، ولا تتفاوت في غايتها: سلامة المستفيد، وجودة التجربة، وحماية البيئة البحرية.","ويرسّخ هذا الشمول اتساق مستوى السلامة والجودة على امتداد القطاع، ويجعل الالتزام بالاشتراطات قاعدة عامة تنطبق على الجميع.","وفي الجانب البيئي، تؤكد الحملة أن الاستدامة ليست حدًا تقف عنده التنمية، بل شرطًا لاستمرارها، وأن تنظيم الأنشطة في المواقع البحرية الحساسة، وفي مقدمتها الموائل البحرية والشعاب المرجانية، لا يهدف إلى الحد من ممارستها، بل إلى ضمان بقائها ممكنة للأجيال القادمة.","وتعمل الهيئة على تحقيق التوازن بين تنمية القطاع والمحافظة على البيئة البحرية، بما يحفظ للبحر الأحمر مقوّماته الطبيعية بوصفها الأصل الذي تقوم عليه التجربة السياحية ذاتها.","وعلى صعيد الاستثمار، تبرز الحملة الأثر المباشر لوضوح البيئة التنظيمية واستقرارها في جذب الاستثمارات النوعية إلى القطاع؛ إذ يرتكز قرار الاستثمار في المشاريع السياحية الساحلية على وضوح الجهة المخوّلة، وترابط الإجراءات من الترخيص إلى التشغيل، وثبات القاعدة التنظيمية على المدى الطويل.","وتسهم الهيئة، من خلال وضع الأطر التنظيمية وإصدار التراخيص والتصاريح وتيسير الإجراءات، في تهيئة بيئة استثمارية مستقرة وجاذبة تدعم نمو القطاع السياحي الساحلي وتوسّع فرصه."]','البيئة والمناخ','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2666847?type=news&uuid=N2666847','https://spa.gov.sa/ar/N2666847?type=news&uuid=N2666847','N2666847','N2666847','','مكة المكرمة','2026-09-02T04:18:00.000Z',NULL,'2026-09-03T20:30:53.334Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10711503.jpeg','/api/media/ae3f3010-ff45-49fe-a4e6-4afc21bd0fec','/api/media/ae3f3010-ff45-49fe-a4e6-4afc21bd0fec?variant=thumbnail','سياحة وترفيه / "أعمق مما تراه".. حملة توعوية تكشف أدوارًا تنظيمية تسبق التجربة السياحية الساحلية',1600,1041,'valid','published','archived','valid',52,'38822be4c0d6a4c5cc2671eaa428269a05aad33439a24e11fa3e214296849c97','ea6498d7a1de92b6eb5d6c923c34922a4f3e942bf781dabdec966fd65dc08a40',NULL,'2026-09-03T20:30:53.334Z','2026-10-07T20:24:32.564Z','','',0,0,'saudi_region','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الاقتصاد والأسواق","جدة"]','["السفر والسياحة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الاقتصاد","score":5.5},{"category":"أخبار السعودية","score":3},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T19:44:58.747Z',200,72,0,'source_article_available','',NULL,NULL,'body:f5b2810216848672ac9cb15d8639bbda060c5c7953506a00464118a1fdd1751a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('509fdc15-6783-4c28-b076-609dd6aafd7e','news-509fdc15-6783-4c28-b076-609dd6aafd7e','أسعار النفط تقترب من أعلى مستوياتها في 6 أسابيع','اسعار النفط تقترب من اعلي مستوياتها في 6 اسابيع','اقتربت أسعار النفط العالمية اليوم من أعلى مستوياتها خلال ستة أسابيع، مسجّلةً ارتفاعاً ملحوظاً في العقود الآجلة لأبرز مرجعَي النفط في الأسواق الدولية. وارتفعت العقود الآجلة لخام برنت 1.76 دولار، بما يعادل 1.8%، لتصل إلى 97.39 دولاراً للبرميل، فيما صعدت العقود الآجلة لخام غرب تكساس الوسيط الأمريكي 1.91 دولار أو ما نسبته 2.1%، مستقرةً عند 92.92 دولاراً للبرميل.','["اقتربت أسعار النفط العالمية اليوم من أعلى مستوياتها خلال ستة أسابيع، مسجّلةً ارتفاعاً ملحوظاً في العقود الآجلة لأبرز مرجعَي النفط في الأسواق الدولية.","وارتفعت العقود الآجلة لخام برنت 1.76 دولار، بما يعادل 1.8%، لتصل إلى 97.39 دولاراً للبرميل، فيما صعدت العقود الآجلة لخام غرب تكساس الوسيط الأمريكي 1.91 دولار أو ما نسبته 2.1%، مستقرةً عند 92.92 دولاراً للبرميل.","ويتجه العقدان نحو تحقيق مكاسب للجلسة الرابعة على التوالي، في مؤشر على زخم إيجابي متصاعد في أسواق الطاقة العالمية."]','الطاقة والصناعة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/dhcagt8','https://sabq.org/article/dhcagt8','','https://sabq.org/article/dhcagt8','صحيفة سبق','','2026-09-03T10:45:00.000Z','2026-09-03T13:45:00.000Z','2026-09-03T20:30:53.575Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/65d0ce4c-1278-49ad-0a62-cc103a981b00/w=1200,h=675,q=90,fit=cover,gravity=auto','/api/media/509fdc15-6783-4c28-b076-609dd6aafd7e','/api/media/509fdc15-6783-4c28-b076-609dd6aafd7e?variant=thumbnail','أسعار النفط تقترب من أعلى مستوياتها في 6 أسابيع',1200,675,'valid','published','archived','valid',35,'bc3ad76a23ceae78b80e70d41f510c3e2c37550682b1c702fce40dd9fa1e6b91','6714f245d5465285f6b78d7cdd958df28268f3cef8a47cb45ec2817d9ff555d1','محدّث','2026-09-03T20:30:53.575Z','2026-10-07T20:24:32.568Z','','',0,0,'international','عادي',49,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط"]','["الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:15.386Z',200,50,0,'source_article_available','',NULL,NULL,'body:df2c7ca2322e6760aef99803e5dd062633f7f4ce8a14af3334b3d7609c8a6e83','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2b09e56e-fd52-4e25-964d-7f63f850bfd9','news-2b09e56e-fd52-4e25-964d-7f63f850bfd9','سياحة وترفيه / بساتين عسير الصيفية.. سلة فواكه تنعش نافذة "السياحة الزراعية" في المملكة','سياحه وترفيه بساتين عسير الصيفيه سله فواكه تنعش نافذه السياحه الزراعيه في المملكه','أبها 21 ربيع الأول 1448 هـ الموافق 03 سبتمبر 2026 م واس حولت موجة الأمطار الأخيرة مرتفعات ومنحدرات منطقة عسير إلى بساط أخضر ممتد، ملقية بظلالها، على معدلات تدفق وإنتاج الفواكه الموسمية التي تزخر بها بساتين المنطقة؛ لتشكل ركيزة أساسية في دعم منظومة الأمن الغذائي والسياحة الريفية المستدامة.','["ورصدت جولة ميدانية لـ\"واس\" حركة تسويقية نشطة لثمار الصيف المفضلة لدى الأهالي والمصطافين، الذين يتوافدون بكثافة على الأرياف والمزارع الممتدة في محافظات وقرى المنطقة؛ للاستمتاع بالطبيعة وتناول الفاكهة الطازجة مباشرة من غصونها.","وتتزامن هذه الوفرة مع الحراك السياحي والاقتصادي المتنامي الذي تشهده المنطقة عبر تنظيم فعاليات \"مهرجان العنب والفواكه الموسمية بالماوين في بللحمر\"، و\"مهرجان الرمان والمنتجات الزراعية بسراة عبيدة\"، التي تحولت إلى منصات تسويقية جاذبة للمنتجين والزوار على حد سواء.","وتتميز عسير بتنوع تضاريسي فريد يسهم في جودة ووفرة المنتجات الشجرية، حيث تصدرت خارطة الإنتاج هذا الموسم محاصيل نوعية شملت الرمان والتين، اللذين يشهدان طلبًا استهلاكيًا واسعًا لمذاقهما المميز وجودتهما العالية، إلى جانب الخوخ والفركس والعنب، وهي من الأصناف الصيفية الملازمة للهوية الزراعية للمنطقة، إضافة إلى البرشومي والجوافة اللذين يسجلان حضورًا لافتًا في الأسواق المحلية والمنافذ السياحية.","وترتكز هذه الوفرة الإنتاجية في المحافظات والمراكز الزراعية الرئيسية بالمنطقة، وفي مقدمتها مدينة أبها، ومحافظات تنومة، والنماص، وسراة عبيدة، وظهران الجنوب، وأحد رفيدة، والحرجة، والفرشة، إلى جانب المزارع الممتدة في مراكز بلحمر، وبلسمر، ووادي بن هشبل.","وتتوزع هذه الثروة النباتية على تلك المواقع التي تمتاز بوفرة مصادر المياه والتربة الخصبة، لتتحول حقول المحافظات والمراكز المستهدفة إلى وجهات جذب واستثمار واعدة، تجمع بين الإنتاج الاقتصادي والجمال الطبيعي الآسر الذي يستهوي عشاق الطبيعة والرحلات. // انتهى // 12:51 ت مـ 0095"]','الاقتصاد','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2668041?type=news&uuid=N2668041','https://spa.gov.sa/ar/N2668041?type=news&uuid=N2668041','N2668041','N2668041','','عسير','2026-09-03T06:51:00.000Z',NULL,'2026-09-03T20:30:53.710Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10720593.jpg','/api/media/2b09e56e-fd52-4e25-964d-7f63f850bfd9','/api/media/2b09e56e-fd52-4e25-964d-7f63f850bfd9?variant=thumbnail','سياحة وترفيه / بساتين عسير الصيفية.. سلة فواكه تنعش نافذة "السياحة الزراعية" في المملكة',1600,1029,'valid','published','archived','valid',54,'42f6d1cee803a3404ff8a7ceb75e814a7657c96a0b91f724fd2dbc4644ba1445','9fc3672ff566ce66c323638d06b0bcca957532ef37534fa426e239f0eb7f327f',NULL,'2026-09-03T20:30:53.710Z','2026-10-07T19:43:47.344Z','','',0,0,'saudi_region','مهم',74,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","السفر والسياحة","الاقتصاد والأسواق","عسير"]','["الطقس والمناخ","السفر والسياحة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":3},{"category":"السياسة","score":0}]','Active','2026-10-07T19:43:47.344Z',200,63,0,'source_article_available','',NULL,NULL,'body:5320dd00945e1a8dc8a4b39edab6395df8db1dc79cfdef1945dd46da17c7b677','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('303c9214-9419-4a97-a2d7-be4493826951','news-303c9214-9419-4a97-a2d7-be4493826951','وزير الخارجية يتلقى اتصالًا هاتفيًا من نظيره اليوناني لبحث العلاقات الثنائية','وزير الخارجيه يتلقي اتصالا هاتفيا من نظيره اليوناني لبحث العلاقات الثنائيه','وأوضحت وزارة الخارجية أن الاتصال تناول بحث العلاقات الثنائية بين المملكة العربية السعودية و اليونان ، إضافة إلى مناقشة المستجدات ذات الاهتمام المشترك.','["تلقى صاحب السمو الأمير فيصل بن فرحان بن عبدالله، وزير الخارجية، اتصالًا هاتفيًا من معالي وزير خارجية الجمهورية الهيلينية جيورجوس جيرابيتريسيس، اليوم الأربعاء."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/hinjc4qxo','https://ajel.sa/local/hinjc4qxo','https://ajel.sa/local/hinjc4qxo','https://ajel.sa/local/hinjc4qxo','فريق التحرير','المدينة المنورة','2026-09-03T12:00:00.000Z','Wed, 07 Oct 2026 19:42:40 GMT','2026-09-03T20:30:53.899Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D9%88%D8%B2%D9%8A%D8%B1-%D8%A7%D9%84%D8%AE%D8%A7%D8%B1%D8%AC%D9%8A%D8%A9-2-7idz5BJR.PNG','/api/media/303c9214-9419-4a97-a2d7-be4493826951','/api/media/303c9214-9419-4a97-a2d7-be4493826951?variant=thumbnail','وزير الخارجية يتلقى اتصالًا هاتفيًا من نظيره اليوناني لبحث العلاقات الثنائية',1200,675,'valid','published','archived','valid',46,'498edc980ef6e659cd3c086539210bf7b1350e46162119fedb2257b79aec7e57','60d2f629f0935dd1e2df8c93df31e5a953073eae1bc1ea8514a819174851b51e','محدّث','2026-09-03T20:30:53.899Z','2026-10-07T19:42:42.544Z','','',0,0,'saudi_region','مهم',70,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الخارجية يتلقى اتصال ا","وزارة الخارجية أن الاتصال تناول"]','["وزير الخارجية يتلقى اتصال ا","وزارة الخارجية أن الاتصال تناول"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:42.544Z',200,49,0,'source_content_changed','',NULL,NULL,'body:c21a7c5eb5e7dedaff87e4369b3494edf3fff1a66f248c57568128161ae2be16','Wed, 07 Oct 2026 19:42:40 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8c39e5ea-b0cf-43b9-a7a7-22d83796fc9e','news-8c39e5ea-b0cf-43b9-a7a7-22d83796fc9e','العليمي يشكر المملكة على دعم البنك المركزي اليمني: دفعة للإصلاح الاقتصادي','العليمي يشكر المملكه علي دعم البنك المركزي اليمني دفعه للاصلاح الاقتصادي','وأشار العليمي إلى أن الدعم السعودي يرتبط بعدة مسارات اقتصادية وخدمية، من بينها دعم استقرار العملة الوطنية وتحسين مستوى معيشة المواطنين والخدمات الأساسية، في إطار جهود الإصلاح الاقتصادي.','["أكد رئيس مجلس القيادة اليمني الدكتور رشاد العليمي أن الدعم الجديد الذي قدمته المملكة العربية السعودية للبنك المركزي اليمني يمثل دفعة لمسار الإصلاحات الاقتصادية وتعزيز استقرار العملة الوطنية وتحسين معيشة المواطنين والخدمات الأساسية.","وعبّر العليمي، عبر حسابه على منصة «إكس»، عن خالص شكره وتقديره لخادم الحرمين الشريفين الملك سلمان بن عبدالعزيز، وولي عهده الأمير محمد بن سلمان ، على الدعم الجديد، معتبرًا إياه امتدادًا للمواقف السعودية الثابتة إلى جانب الشعب اليمني وقيادته السياسية.","وأوضح رئيس مجلس القيادة اليمني أن الحكومة ستواصل الوفاء بالتزاماتها وتعظيم أثر الشراكة بين البلدين، إلى جانب العمل على تعزيز الثقة بمؤسسات الدولة ودعم مسار التعافي الشامل.","وأشاد رئيس مجلس القيادة بالدعم السعودي، مؤكدًا أهميته في دفع مسار الإصلاحات الاقتصادية وتعزيز استقرار مؤسسات الدولة ومسار التعافي."]','أخبار السعودية','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/a7olmunhc','https://ajel.sa/international/a7olmunhc','https://ajel.sa/international/a7olmunhc','https://ajel.sa/international/a7olmunhc','فريق التحرير','','2026-09-03T11:56:00.000Z','Wed, 07 Oct 2026 19:42:40 GMT','2026-09-03T20:30:54.063Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-jjqnXhm4.jpg','/api/media/8c39e5ea-b0cf-43b9-a7a7-22d83796fc9e','/api/media/8c39e5ea-b0cf-43b9-a7a7-22d83796fc9e?variant=thumbnail','العليمي',1200,675,'valid','published','archived','valid',99,'2ab548d7808d73a780afdc141f5ededccc4b1db8b5e0ad8315c7616ef2a56253','66797d46572265d714c815c248ea7398f384ac0b0d914f7d0e21070765d9c03e','محدّث','2026-09-03T20:30:54.063Z','2026-10-07T19:42:42.555Z','','',0,0,'saudi_national','مهم',72,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","مجلس القيادة اليمني الدكتور رشاد","رئيس مجلس القيادة اليمني الدكتور","البنك المركزي اليمني دفعة للإصلاح","الاقتصاد والأسواق","اليمن"]','["مجلس القيادة اليمني الدكتور رشاد","رئيس مجلس القيادة اليمني الدكتور","البنك المركزي اليمني دفعة للإصلاح","الاقتصاد والأسواق"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:42.555Z',200,49,0,'source_content_changed','',NULL,NULL,'body:cb6544db94fb3146b64e55aee86a6bcd8ea17e9fc28bde50828a3d4df4bd48e5','Wed, 07 Oct 2026 19:42:40 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bc711951-1c27-48e6-b5c7-57f91e283a23','news-bc711951-1c27-48e6-b5c7-57f91e283a23','وزارة الرياضة تختتم مشاركتها في «LEAP 2026» بإطلاق مشاريع رقمية طموحة','وزاره الرياضه تختتم مشاركتها في leap 2026 باطلاق مشاريع رقميه طموحه','اختتمت وزارة الرياضة مشاركتها في النسخة الخامسة من الحدث التقني العالمي «LEAP 2026»، التي أُقيمت خلال الفترة من 31 أغسطس إلى 3 سبتمبر 2026م، في مركز الرياض للمعارض والمؤتمرات بملهم، تحت شعار «نحو آفاق جديدة»؛ وذلك من خلال جناحها ضمن منطقة «Sport Tech Hub» (المنطقة الرياضية التقنية)، الذي استعرض رحلة الوزارة في التحول الرقمي، وأبرز المشاريع والمبادرات…','["وشهدت المشاركة الإعلان عن مشروع «الملعب الرقمي» وتطبيق «رياضي»، إلى جانب استعراض عدد من المشاريع والمبادرات الرقمية، شملت: التوأم الرقمي، والتقنيات والحلول الرقمية في مدينة الملك فهد الرياضية، إضافةً إلى تطبيق «أهلاً» الخاص باللجنة المحلية المنظمة لكأس آسيا 2027.","كما تضمنت المشاركة عدداً من الجلسات الحوارية المتخصصة بمشاركة قيادات وخبراء في القطاعين الرياضي والتقني، إلى جانب توقيع مذكرات تفاهم بين شركات ناشئة متخرجة من برامج ابتكارية وجهات رياضية، بما يُسهم في دعم الحلول التقنية وتعزيز فرص التعاون والابتكار في القطاع الرياضي.","وجاءت مشاركة وزارة الرياضة في «LEAP 2026» امتداداً لجهودها في توظيف التقنيات الحديثة وتطوير منظومة الخدمات الرقمية، بما يُسهم في رفع كفاءة القطاع الرياضي وتحسين تجربة المستفيد، ومواكبة مستهدفات التحول الرقمي ضمن رؤية السعودية 2030."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/2e6641s','https://sabq.org/article/2e6641s','','https://sabq.org/article/2e6641s','صحيفة سبق','الرياض','2026-09-03T10:36:00.000Z','2026-09-03T13:37:00.000Z','2026-09-03T20:30:54.087Z','https://media.sabq.org/news/2026/09/41cb9a7b-25c5-4459-b452-c9a660fa1768/w1080.webp','/api/media/bc711951-1c27-48e6-b5c7-57f91e283a23','/api/media/bc711951-1c27-48e6-b5c7-57f91e283a23?variant=thumbnail','وزارة الرياضة تختتم مشاركتها في «LEAP 2026» بإطلاق مشاريع رقمية طموحة',1080,720,'valid','published','archived','valid',56,'41e59a1582b705f9aa29ebbebbe499c06e8d29a14aae024ffd1f60605ef92f31','22474312d1ac050c483e84f1d34412f812a2d83a9d95af23a3c971bdce2a4ab7','محدّث','2026-09-03T20:30:54.087Z','2026-10-07T19:42:17.925Z','','',0,0,'saudi_region','مهم',70,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الرياضة تختتم مشاركتها في","الرياضة السعودية","التقنية والتحول الرقمي","الرياض"]','["وزارة الرياضة تختتم مشاركتها في","الرياضة السعودية","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"المناطق","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"الرياضة","score":1.5}]','Active','2026-10-07T19:42:17.925Z',200,46,0,'source_article_available','',NULL,NULL,'body:3dc2a584af2519b717c6ae66558a9f3342e1a6dc9aef77a7d9eab97f1ea77807','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('787f63ba-c458-4ea8-a295-d6043b758774','news-787f63ba-c458-4ea8-a295-d6043b758774','دوريات المجاهدين بجازان تضبط مواطناً نقل مخالفاً يمنياً لأنظمة أمن الحدود','دوريات المجاهدين بجازان تضبط مواطنا نقل مخالفا يمنيا لانظمه امن الحدود','ضبطت دوريات الإدارة العامة للمجاهدين بمنطقة جازان مواطناً سعودياً كان يقل في مركبته مخالفاً يمنياً لنظام أمن الحدود، وجرى إيقافه واتخاذ الإجراءات النظامية بحقه، فيما أُحيل المخالف إلى جهة الاختصاص، وأُحيل ناقله إلى النيابة العامة.','["وأكد المتحدث الرسمي للإدارة العامة للمجاهدين أن كل من يُسهّل دخول مخالفي نظام أمن الحدود إلى المملكة، أو ينقلهم داخلها، أو يوفر لهم المأوى، أو يقدم لهم أي مساعدة بأي صورة كانت، يتعرض لعقوبات صارمة تشمل السجن مدة تصل إلى 15 سنة، وغرامة مالية تبلغ مليون ريال، فضلاً عن مصادرة وسيلة النقل والسكن المستخدم للإيواء، والتشهير بمرتكب المخالفة.","وأوضح المتحدث أن هذه الجريمة تُصنَّف ضمن الجرائم الكبيرة الموجبة للتوقيف، والمخلّة بالشرف والأمانة، داعياً المواطنين والمقيمين إلى الإبلاغ عن مخالفي أنظمة الإقامة والعمل وأمن الحدود عبر الرقم (911) في مناطق مكة المكرمة والمدينة المنورة والرياض والمنطقة الشرقية، والرقمين (999) و(996) في بقية مناطق المملكة، مؤكداً أن جميع البلاغات تُعامَل بسرية تامة دون أي مسؤولية تقع على عاتق المُبلِّغ."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/vf6biib','https://sabq.org/article/vf6biib','','https://sabq.org/article/vf6biib','صحيفة سبق','الرياض','2026-09-03T10:21:00.000Z','2026-09-03T13:22:00.000Z','2026-09-03T20:30:54.316Z','https://media.sabq.org/news/2026/09/d640488d-5c79-4afa-9b56-b59fb6604870/w1036.webp','/api/media/787f63ba-c458-4ea8-a295-d6043b758774','/api/media/787f63ba-c458-4ea8-a295-d6043b758774?variant=thumbnail','دوريات المجاهدين بجازان تضبط مواطناً نقل مخالفاً يمنياً لأنظمة أمن الحدود',1036,565,'valid','published','archived','valid',87,'2dcedc7161bf80c2db4eaaa81d320482da9f5f9e5848126f6a878a743001bece','90edac56b2a526c0cd3ebeda164ee0b2614b390a3df07b09ab9256e25435b56a','محدّث','2026-09-03T20:30:54.316Z','2026-10-07T19:42:18.959Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","التقنية والتحول الرقمي","مكة","جازان","الرياض","المدينة المنورة"]','["الرياضة السعودية","التقنية والتحول الرقمي","المدينة المنورة"]','classified','','[{"category":"التقنية","score":3.5},{"category":"المجتمع","score":3},{"category":"الرياضة","score":3}]','Active','2026-10-07T19:42:18.959Z',200,49,0,'source_article_available','',NULL,NULL,'body:2b30f138f0946f088f8fa045173ab054f0a134a5175afd81ad788fc863c28078','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b1114da7-1f58-4859-8f03-2c2d463df33e','news-b1114da7-1f58-4859-8f03-2c2d463df33e','الأمير فهد بن جلوي يبحث مع رئيس المركز الدولي للهدنة الأولمبية آفاق التعاون','الامير فهد بن جلوي يبحث مع رئيس المركز الدولي للهدنه الاولمبيه افاق التعاون','وأكد ابن جلوي اعتزاز اللجنة الأولمبية والبارالمبية السعودية بعلاقتها مع المركز الدولي للهدنة الأولمبية، بوصفها عضواً فاعلاً في الحركة الأولمبية العالمية الساعية إلى ترسيخ قيم السلام والحوار من خلال الرياضة.','["التقى الأمير فهد بن جلوي بن عبدالعزيز بن مساعد، نائب رئيس اللجنة الأولمبية والبارالمبية السعودية، بمكتبه في مجمع الأمير فيصل بن فهد الأولمبي بالرياض، رئيسَ المركز الدولي للهدنة الأولمبية جورج باباندريو.","وتناول اللقاء أوجه التعاون بين اللجنة الأولمبية والبارالمبية السعودية والمركز الدولي في مجالات البرامج التعليمية والتدريبية، وترسيخ القيم الأولمبية؛ بما يسهم في تطوير الكوادر الرياضية والأكاديمية، وتعزيز حضور الدراسات الأولمبية في المملكة.","كما استعرض الجانبان مجالات التعاون المشترك مع الاتحاد الرياضي للتضامن الإسلامي، ودوره في تعزيز الحضور الرياضي بين الدول الإسلامية، بما ينسجم مع رسالة المركز في نشر ثقافة السلام والحوار عبر الرياضة.","وتناول اللقاء أيضاً الدور الذي تضطلع به المملكة في نشر السلام وتقريب وجهات النظر من خلال الرياضة، ومساهماتها في استضافة الأحداث الرياضية الكبرى التي تجمع شعوب العالم على قيم التسامح والتفاهم، تجسيداً لالتزامها بتوظيف الرياضة أداةً للحوار الحضاري والتقارب بين الأمم.","من جانبه، أعرب باباندريو عن شكره وتقديره لنائب رئيس اللجنة الأولمبية والبارالمبية السعودية على حسن الاستقبال، مثمّناً الدور المتنامي للمملكة في دعم الحركة الأولمبية العالمية وترسيخ قيم الهدنة الأولمبية، ومتطلعاً إلى توسيع آفاق التعاون مع المؤسسات الرياضية السعودية في المرحلة المقبلة."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/qqvt5nw','https://sabq.org/article/qqvt5nw','','https://sabq.org/article/qqvt5nw','صحيفة سبق','الرياض','2026-09-03T10:25:00.000Z','2026-09-03T13:26:00.000Z','2026-09-03T20:30:54.511Z','https://media.sabq.org/news/2026/09/6d661448-dddd-4ed6-99b5-85368c5e152f/w1600.webp','/api/media/b1114da7-1f58-4859-8f03-2c2d463df33e','/api/media/b1114da7-1f58-4859-8f03-2c2d463df33e?variant=thumbnail','الأمير فهد بن جلوي يبحث مع رئيس المركز الدولي للهدنة الأولمبية آفاق التعاون',1600,1600,'valid','published','archived','valid',46,'4365a4d91271dbb0bf67fd6b6f5cb5e21446a4440b9adfb182ddf0ff42572c24','0f420902d2c4377aa2643b8ed7f160cf5006b48debe6543139849cc8b4fea413','محدّث','2026-09-03T20:30:54.511Z','2026-10-07T19:42:19.989Z','','',0,0,'saudi_region','مهم',69,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس المركز الدولي للهدنة الأولمبية","الثقافة والفنون","التعليم والتدريب","الرياضة السعودية","الرياض"]','["رئيس المركز الدولي للهدنة الأولمبية","الثقافة والفنون","التعليم والتدريب","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"الرياضة","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:42:19.989Z',200,48,0,'source_article_available','',NULL,NULL,'body:39b6485c7f83bb9facaca8091fd1fad9abff8c0533ee361a8a958f88fe9be344','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('81af3aa2-d970-4a1b-a99e-8efd91d92b63','news-81af3aa2-d970-4a1b-a99e-8efd91d92b63','أسعار النفط تسجل أعلى مستوياتها في ستة أسابيع بدعم مكاسب متواصلة','اسعار النفط تسجل اعلي مستوياتها في سته اسابيع بدعم مكاسب متواصله','سجلت أسعار النفط اليوم الأربعاء ارتفاعًا ملحوظًا، لتقترب من أعلى مستوياتها خلال ستة أسابيع، مدعومة بمكاسب مستمرة للجلسة الرابعة على التوالي. وارتفعت العقود الآجلة لخام برنت بقيمة 1.76 دولار، أي بنسبة 1.8٪، لتصل إلى 97.39 دولارًا للبرميل.','["سجلت أسعار النفط اليوم الأربعاء ارتفاعًا ملحوظًا، لتقترب من أعلى مستوياتها خلال ستة أسابيع، مدعومة بمكاسب مستمرة للجلسة الرابعة على التوالي.","وارتفعت العقود الآجلة لخام برنت بقيمة 1.76 دولار، أي بنسبة 1.8٪، لتصل إلى 97.39 دولارًا للبرميل.","كما صعدت العقود الآجلة لخام غرب تكساس الوسيط الأمريكي 1.91 دولار أو 2.1٪، ليبلغ سعر البرميل 92.92 دولارًا.","يُذكر أن هذه الارتفاعات تأتي وسط مؤشرات على استمرار الطلب وتعافي السوق العالمية."]','الطاقة والصناعة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/i586ffs7z','https://ajel.sa/economy/i586ffs7z','https://ajel.sa/economy/i586ffs7z','https://ajel.sa/economy/i586ffs7z','فريق التحرير','','2026-09-03T11:01:00.000Z','Wed, 07 Oct 2026 19:42:40 GMT','2026-09-03T20:30:54.639Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D9%86%D9%81%D8%B7-3-vbiC56n6.jpg','/api/media/81af3aa2-d970-4a1b-a99e-8efd91d92b63','/api/media/81af3aa2-d970-4a1b-a99e-8efd91d92b63?variant=thumbnail','أسعار النفط تسجل أعلى مستوياتها في ستة أسابيع بدعم مكاسب متواصلة',1200,675,'valid','published','archived','valid',46,'c2621aa3e1ac8071cbb07d8d5c55682964d3d32315b24d770e5a775973f943fd','dcb8759cde6b922e1862df63ccb97bdeac60a96932bd3ca342e20038ef057327','محدّث','2026-09-03T20:30:54.639Z','2026-10-07T19:42:42.570Z','','',0,0,'international','عادي',43,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط"]','["الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:42:42.570Z',200,50,0,'source_content_changed','',NULL,NULL,'body:c737ea3dc2129b884a8b304bf797ee4d66f39eccb1a689e39cd5dc5254cc1c7e','Wed, 07 Oct 2026 19:42:40 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('586582eb-b077-4a04-9f6a-e7889a6a925d','news-586582eb-b077-4a04-9f6a-e7889a6a925d','ضبط مواطن بحوزته 48 كيلوجراماً من الحشيش في محافظة الفرشة بعسير','ضبط مواطن بحوزته 48 كيلوجراما من الحشيش في محافظه الفرشه بعسير','قبضت دوريات الأفواج الأمنية بمنطقة عسير على مواطن بتهمة ترويج 48 كيلوجراماً من مادة الحشيش المخدر في محافظة الفرشة، وتم إيقافه واتخاذ الإجراءات النظامية بحقه، وإحالته إلى جهة الاختصاص.','["وتهيب الجهات الأمنية بالمواطنين والمقيمين الإبلاغ عن أي معلومات تتعلق بنشاطات تهريب المخدرات أو ترويجها، عبر الاتصال بالأرقام التالية: (911) في مناطق مكة المكرمة والرياض والمنطقة الشرقية، و(999) في بقية مناطق المملكة، فضلاً عن رقم بلاغات المديرية العامة لمكافحة المخدرات (995)، أو عبر البريد الإلكتروني «995@gdnc.gov.sa»، مع ضمان التعامل مع جميع البلاغات بسرية تامة ودون أي مسؤولية على المُبلِّغ."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/92h2tl1','https://sabq.org/article/92h2tl1','','https://sabq.org/article/92h2tl1','صحيفة سبق','الرياض','2026-09-03T10:05:00.000Z','2026-09-03T13:05:00.000Z','2026-09-03T20:30:54.848Z','https://media.sabq.org/news/2026/09/45f19414-3cec-4a77-b7c4-0f7c465ce828/w600.webp','/api/media/586582eb-b077-4a04-9f6a-e7889a6a925d','/api/media/586582eb-b077-4a04-9f6a-e7889a6a925d?variant=thumbnail','ضبط مواطن بحوزته 48 كيلوجراماً من الحشيش في محافظة الفرشة بعسير',600,400,'valid','published','archived','valid',99,'3302588fae41e5e5de03ea315ef17b5d982a2711e1f017fe0dc3b634bb30f6b4','27905ea3f92d72e3c215bb6818e52ae7756af758f9b78c9ce65a1c46bf86a1d8','محدّث','2026-09-03T20:30:54.848Z','2026-10-07T19:42:36.815Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","مكة","عسير","الرياض"]','["الرياضة السعودية"]','classified','','[{"category":"المجتمع","score":3},{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5}]','Active','2026-10-07T19:42:36.815Z',200,50,0,'source_article_available','',NULL,NULL,'body:5d0ec453abe6d2ba9f35c8d4e2a89f89bea0b9298e01ddcbc340cdd3da76eb59','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c079025b-920f-4611-bfdc-1d763b96377a','news-c079025b-920f-4611-bfdc-1d763b96377a','مكاتب التعليم.. مرّت سنة!','مكاتب التعليم مرت سنه','مع أن تلك المكاتب كانت على مدى عقود تقوم بخدمات كبيرة، من أهمها وأساسها تقديم خدمات النقل بين المدارس، أو لمن انتقل إلى الحي الذي يكون فيه موقع المكتب؛ لأنها تكون في كل جهات المدينة أو المحافظة، ما بين شمال وجنوب وشرق وغرب.','["مرّت سنة ونيّف على إغلاق وزارة التعليم لمكاتب التعليم بكل المناطق، وقد قال بعض المهتمين من التربويين إن سبب الإغلاق هو الهدر في الموارد البشرية الناتج عن تلك المكاتب، من وجود موظفين بها من مشرفين ومشرفات، وإداريين وإداريات، ومستخدمين ومستخدمات، وميزانيات خاصة بها.","إضافة إلى تقديم برامج تدريبية للمعلمين والمعلمات لجميع التخصصات، عبر قاعات تدريبية مخصصة ومجهزة بأجهزة حديثة من «الداتا شو» (Data Show) وكمبيوترات حديثة أيضًا، بعضها تم تجهيزها من قبل رجال أعمال من الألف إلى الياء، مساهمة منهم في تقديم خدماتهم للتعليم!","نتيجة لذلك الإغلاق، كان لزامًا على إدارات التعليم في كل مدينة ومحافظة أن تشكّل لجنة تسمى «لجنة القبول والتسجيل»، يقوم عليها عدد من المشرفين والمشرفات في إحدى المدارس في كل جهة من الجهات الأربع لكل مدينة ومحافظة من بلادنا الغالية؛ لأنه ليس لها مقر ثابت حتى يأتي أولياء الأمور إليها.","مع العلم بأن المكاتب كانت تقوم بتلك المهمة وغيرها من المهام، كالتدريب وبقية الخدمات التربوية في كل مدينة ومحافظة، بل كانت إلى عهد قريب تعتبر بمثابة إدارة تعليم مصغرة في بعض المحافظات!","وأيضًا لا يخفى على مسؤولي التعليم تكدس أولياء الأمور في بعض إدارات التعليم من أجل المطالبة بالنقل من حي لحي آخر، ومن مدرسة لأخرى، من كل مكان في بعض المناطق، وقد يكون بعضهم يأتي من قرية أو هجرة أو محافظة بعيدة لهذه المدينة أو تلك!","هل من عودة لبعض مكاتب التعليم بالمناطق والمحافظات؟","نتمنى من مسؤولي وزارة التعليم إعادة عمل مكاتب التعليم، خاصة في المناطق والمحافظات التي أُغلقت فيها إدارات التعليم؛ لأنه كما أسلفت، بعض المكاتب كانت تمثل حجر الأساس للتعليم في بعض المناطق، وتعد بمثابة إدارة تعليم مصغرة تخدم شريحة كبيرة من السكان، كما تقدم كل الخدمات لمنسوبي تلك المدارس من معلمين ومعلمات، وإداريين وإداريات، ومستخدمين ومستخدمات، فضلًا عن بقية المراجعين من أولياء أمور الطلاب والطالبات.","ولو أن تكون بكادر بسيط للحاجة الماسة لهم، والتقليل ما أمكن من كثرة الموظفين بها من المشرفين والمشرفات والإداريين والإداريات وغيرهم، إذ تعتبر الوزارة أن بعضهم زائد عن الحاجة وفي وجودهم هدر؛ ولذلك قامت بإعادة بعض المشرفين والمشرفات لسد العجز بالمدارس إن وُجد عجز، وكذلك توجيه الإداريين والمستخدمين والمستخدمات بها إلى مدارس البنين والبنات، في خطوة من الوزارة للتقليل ما أمكن من الهدر في الموارد البشرية لأولئك الموظفين!"]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/02e5pnu','https://sabq.org/article/02e5pnu','','https://sabq.org/article/02e5pnu','ماجد مسلم الحربي','','2026-09-03T10:19:00.000Z','2026-09-03T13:19:00.000Z','2026-09-03T20:30:54.967Z','https://media.sabq.org/news/2026/09/08032c3a-fa86-4bb1-975f-52dccd18def7/w1600.webp','/api/media/c079025b-920f-4611-bfdc-1d763b96377a','/api/media/c079025b-920f-4611-bfdc-1d763b96377a?variant=thumbnail','مكاتب التعليم.. مرّت سنة!',1600,893,'valid','published','archived','valid',50,'c4a5335cc1531999ef7bf65d648249eaa12ee97aec8adbc8b74bf5325c8ab163','4834392c220a76f02efa81f6dbec30287702de4ef35199e2230c17e083025fea','محدّث','2026-09-03T20:30:54.967Z','2026-10-07T20:24:32.597Z','','',0,0,'international','عادي',56,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة التعليم لمكاتب التعليم بكل","الثقافة والفنون","التعليم والتدريب"]','["وزارة التعليم لمكاتب التعليم بكل","الثقافة والفنون","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:18.981Z',200,48,0,'source_article_available','',NULL,NULL,'body:9d9f586719f15829c818c274056f64b33127b4f6b085dd8189c78c688a52c914','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('984d4096-52db-475f-9934-7fa3dceb5b6e','news-984d4096-52db-475f-9934-7fa3dceb5b6e','ثلاثة أعاصير تضرب المحيط الهادئ في آنٍ واحد بسبب «إل النينيو»','ثلاثه اعاصير تضرب المحيط الهادئ في ان واحد بسبب ال النينيو','كشف المركز الأمريكي للأعاصير عن ظاهرة نادرة تشهدها مياه المحيط الهادئ، تمثّلت في تزامن ثلاثة أعاصير في وقت واحد، في ظاهرة يُرجعها العلماء إلى ارتفاع درجات حرارة المياه الناجم عن ظاهرة «إل النينيو».','["وقالت عالمة المناخ في جامعة ميشيغان جوليا كول: «إن رؤية ثلاثة أعاصير في آنٍ واحد تُعدّ أمراً نادراً بلا شك»، موضحةً أن ظاهرة الاحترار المرتبطة بـ«إل النينيو» تُهيّئ الظروف الملائمة لنشوء هذه العواصف التي تتغذى بشكل كبير على المياه الدافئة، مبيّنةً أنه «عندما تكون مياه المحيط الهادئ الاستوائية أدفأ من المعتاد، نشهد زيادة ملحوظة في العواصف القوية».","وأوضح المركز أن الإعصار «لويل» كان يقع على بُعد نحو 710 كيلومترات جنوب مدينة هيلو في هاواي، فيما يُسجّل الإعصار «كارينا» تراجعاً في قوته خلال تحرّكه نحو الشمال الغربي، بينما يقترب الإعصار «ماري» قادماً من الشرق، بعد أن كان يتمركز على بُعد 600 كيلومتر إلى جنوب غرب ولاية كاليفورنيا."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/t8eyti9','https://sabq.org/article/t8eyti9','','https://sabq.org/article/t8eyti9','صحيفة سبق','','2026-09-03T09:55:00.000Z','2026-09-03T12:57:00.000Z','2026-09-03T20:30:54.972Z','https://media.sabq.org/news/2026/09/4271ae42-cfd9-48a3-b52f-830d57bde91c/w650.webp','/api/media/984d4096-52db-475f-9934-7fa3dceb5b6e','/api/media/984d4096-52db-475f-9934-7fa3dceb5b6e?variant=thumbnail','ثلاثة أعاصير تضرب المحيط الهادئ في آنٍ واحد بسبب «إل النينيو»',650,365,'valid','published','archived','valid',35,'cd7d11c31f16405e7d5ad760799b2f3332d01a4874964336edaad23710aa9f25','b53438bcdc8b10ac58b29639568f6536065c541145e78dcb866ba92b779d26fc','محدّث','2026-09-03T20:30:54.972Z','2026-10-07T20:24:32.599Z','','',0,0,'international','عادي',45,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة ميشيغان جوليا كول إن","الطقس والمناخ","التعليم والتدريب"]','["جامعة ميشيغان جوليا كول إن","الطقس والمناخ","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:36.811Z',200,49,0,'source_article_available','',NULL,NULL,'body:753cb3b9b78600dfdd6d28dcc408b3e3495db716d47d4f20a6164c003a2596a0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9566b25f-a30c-4a2f-9071-b05121cb5360','news-9566b25f-a30c-4a2f-9071-b05121cb5360','زلزال بقوة 6.2 درجات يضرب جزر ساندويتش الجنوبية في المحيط الأطلسي','زلزال بقوه 6 2 درجات يضرب جزر ساندويتش الجنوبيه في المحيط الاطلسي','ضرب زلزال بقوة 6.2 درجات على مقياس ريختر جزر ساندويتش الجنوبية، وهي من أقاليم ما وراء البحار البريطانية الواقعة في جنوب المحيط الأطلسي. وأفادت هيئة المسح الجيولوجي الأمريكية بأن الزلزال وقع على عمق 125.9 كيلومتراً تحت سطح الأرض.','["ضرب زلزال بقوة 6.2 درجات على مقياس ريختر جزر ساندويتش الجنوبية، وهي من أقاليم ما وراء البحار البريطانية الواقعة في جنوب المحيط الأطلسي.","وأفادت هيئة المسح الجيولوجي الأمريكية بأن الزلزال وقع على عمق 125.9 كيلومتراً تحت سطح الأرض.","وتشهد المنطقة نشاطاً زلزالياً وبركانياً متكرراً، نظراً لوقوعها عند تقاطع الصفائح التكتونية بين الصفيحتين الأمريكية الجنوبية والقطبية الجنوبية «الأنتركتية»."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7s89x9o','https://sabq.org/article/7s89x9o','','https://sabq.org/article/7s89x9o','صحيفة سبق','','2026-09-03T09:27:00.000Z','2026-09-03T12:27:00.000Z','2026-09-03T20:30:55.418Z','https://media.sabq.org/news/2026/09/0b1cfd8f-9ca6-4dc4-8975-35797d5ccf49/w1600.webp','/api/media/9566b25f-a30c-4a2f-9071-b05121cb5360','/api/media/9566b25f-a30c-4a2f-9071-b05121cb5360?variant=thumbnail','زلزال بقوة 6.2 درجات يضرب جزر ساندويتش الجنوبية في المحيط الأطلسي',1600,893,'valid','published','archived','valid',35,'eb2082c46e847688675e4b2e1684f42bc257c1307b4a32f633acf4cc48aa8d42','dbb27e5fd6f43a0b13045366e1dfad5586c6cf978c04187cc67538c5d9a4e827','محدّث','2026-09-03T20:30:55.418Z','2026-10-07T20:24:32.603Z','','',0,0,'international','مهم',63,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة المسح الجيولوجي الأمريكية بأن"]','["هيئة المسح الجيولوجي الأمريكية بأن"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:44.904Z',200,50,0,'source_article_available','',NULL,NULL,'body:85790504cbd96c4b750f671f56f9091c2ad461a0e49d317187a52033a4571d5d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d5a14842-2e12-46ac-84c4-4e9f0ddaaaae','news-d5a14842-2e12-46ac-84c4-4e9f0ddaaaae','اقتصادي / موسم الروبيان بجازان.. 7 أشهر تعزز استدامة المصايد وتدعم الأمن الغذائي','اقتصادي موسم الروبيان بجازان 7 اشهر تعزز استدامه المصايد وتدعم الامن الغذائي','جيزان 19 ربيع الأول 1448 هـ الموافق 01 سبتمبر 2026 م واس مع حلول الأول من سبتمبر، تعود مياه البحر الأحمر قبالة سواحل منطقة جازان إلى استقبال موسم صيد الروبيان، الذي يمتد سبعة أشهر حتى نهاية مارس 2027م، في موسم يمثل أحد أبرز المواسم البحرية بالمنطقة، ويجمع بين النشاط الاقتصادي للصيادين وأهمية المنتجات البحرية في تعزيز الأمن الغذائي واستدامة الموارد الطبيعية.','["وينطلق موسم صيد الروبيان بأسطول يتجاوز 120 قارب صيد، بعد أن استكمل فرع وزارة البيئة والمياه والزراعة بمنطقة جازان استعداداته اللازمة لانطلاق الموسم، بما يشمل تهيئة الخدمات والإجراءات التنظيمية المقدمة للصيادين، وتمكينهم من ممارسة نشاطهم وفق الأنظمة والاشتراطات المعتمدة.","وتتجلى مكانة قطاع الثروة السمكية في منطقة جازان من خلال حجم الإنتاج والمصيد البحري؛ إذ بلغ إجمالي المصيد من مختلف أنواع الأسماك في المنطقة (10,639) طنًا، فيما بلغ إجمالي مصيد الروبيان (953) طنًا، إلى جانب إنتاج الروبيان من مشاريع الاستزراع المائي الذي بلغ (2,234) طنًا، بما يعكس تنوع مصادر المنتجات البحرية ودور المصائد والاستزراع المائي في دعم منظومة الأمن الغذائي.","وأوضح المدير العام لفرع الوزارة المهندس أحمد بن محمد آل مجثل، في تصريح لـ\"واس\"، أن الفرع أكمل جميع الاستعدادات والخدمات اللازمة لانطلاقة موسم صيد الروبيان، من خلال تقديم الدعم للصيادين وإنهاء الإجراءات التي تمكنهم من بدء نشاطهم مع انطلاق الموسم، والتنسيق مع الجهات ذات العلاقة لإصدار الرخص الموسمية لصيد الروبيان عبر منصة \"نما\".","وأشار المهندس آل مجثل إلى أن تحديد موسم خاص لصيد الروبيان يأتي ضمن الجهود الرامية إلى المحافظة على الثروة السمكية وضمان استدامة المصايد وتوفر المنتج بصورة مستمرة، بما يحافظ على التوازن البيئي ويعزز قدرة القطاع على تلبية الطلب على المنتجات البحرية المحلية.","وأكد أهمية التزام الصيادين بالأنظمة والتعليمات المنظمة لموسم الصيد، واستخدام وسائل الصيد النظامية التي تسهم في حماية المخزون السمكي وتنميته بصورة مستدامة، مشددًا على أن عدم الامتثال للأنظمة والتعليمات يعرّض المخالفين لتطبيق العقوبات النظامية.","ويجسد موسم الروبيان في جازان تكامل الجهود بين التنظيم والإنتاج والاستزراع المائي، في منظومة تستهدف تنمية الثروة السمكية والمحافظة على موارد البحر الأحمر، وتعزيز الاستفادة الاقتصادية من الموارد البحرية، بما يدعم مستهدفات رؤية المملكة 2030 في تنمية القطاعات الواعدة وتحقيق الأمن الغذائي واستدامة الموارد الطبيعية. // انتهى // 16:59 ت مـ 0180"]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2666252?type=news&uuid=N2666252','https://spa.gov.sa/ar/N2666252?type=news&uuid=N2666252','N2666252','N2666252','','المدينة المنورة','2026-09-01T10:59:00.000Z','2026-09-01T10:59:00.000Z','2026-09-03T20:30:55.435Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10706448.jpg','/api/media/d5a14842-2e12-46ac-84c4-4e9f0ddaaaae','/api/media/d5a14842-2e12-46ac-84c4-4e9f0ddaaaae?variant=thumbnail','اقتصادي / موسم الروبيان بجازان.. 7 أشهر تعزز استدامة المصايد وتدعم الأمن الغذائي',1600,900,'valid','published','archived','valid',86,'722ab68904996506b07f626956625d2d3013522e5273ba921e3699ea78975509','99fb9cdebe1c5267bbf213c426fa76a3c09776503b41e2d860d7d1ec38afc5f9','محدّث','2026-09-03T20:30:55.435Z','2026-10-07T19:44:40.565Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البيئة والمياه والزراعة بمنطقة","التعليم والتدريب","الاقتصاد والأسواق","جازان"]','["وزارة البيئة والمياه والزراعة بمنطقة","التعليم والتدريب","الاقتصاد والأسواق"]','classified','','[{"category":"الاقتصاد","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"السياسة","score":1.5}]','Active','2026-10-07T19:44:40.565Z',200,73,0,'source_article_available','',NULL,NULL,'body:75c74b4db9408d1d88655dc60e392c9ca9b8f5c40a7e6be30d553a3e4843a607','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d15efe36-959b-4890-8af7-a6ed9e27662b','news-d15efe36-959b-4890-8af7-a6ed9e27662b','إعصار «ماري» يتشكّل في المحيط الهادئ بسرعة رياح 130 كيلومتراً في الساعة','اعصار ماري يتشكل في المحيط الهادئ بسرعه رياح 130 كيلومترا في الساعه','أعلن المركز الوطني للأعاصير تحوّل العاصفة الاستوائية «ماري» إلى إعصار كامل في المحيط الهادئ، في تطور لافت يستدعي المتابعة الدقيقة لمساره وتأثيراته المحتملة.','["وأوضح المركز أن الإعصار «ماري» يقع حالياً على بُعد نحو 375 ميلاً (600 كيلومتر) جنوب غرب الطرف الجنوبي لشبه جزيرة باخا كاليفورنيا.","وبلغت سرعة الرياح القصوى المستمرة المرتبطة بالإعصار نحو 80 ميلاً في الساعة (130 كيلومتراً في الساعة)، وفق نشرة رسمية أصدرها مركز الأعاصير المتخذ من مدينة ميامي مقراً له."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/saqi6e9','https://sabq.org/article/saqi6e9','','https://sabq.org/article/saqi6e9','صحيفة سبق','','2026-09-03T09:06:00.000Z','2026-09-03T12:07:00.000Z','2026-09-03T20:30:55.441Z','https://media.sabq.org/news/2026/08/5d03af69-bff0-47c0-84f4-f3d3d6004401/w1200.webp','/api/media/d15efe36-959b-4890-8af7-a6ed9e27662b','/api/media/d15efe36-959b-4890-8af7-a6ed9e27662b?variant=thumbnail','إعصار «ماري» يتشكّل في المحيط الهادئ بسرعة رياح 130 كيلومتراً في الساعة',1200,630,'valid','published','archived','valid',35,'3b1d26667c29e7d3065200b666e9f993a9a41ee378606cc770dba234d45d1013','41f7a36da55e54b35a159250d164abda35287964dae145a8736b663262491eab','محدّث','2026-09-03T20:30:55.441Z','2026-10-07T20:24:32.609Z','','',0,0,'international','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ"]','["الطقس والمناخ"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:44.323Z',200,56,0,'source_article_available','',NULL,NULL,'body:bf928ed6df4be44cac19ec11d466d1f3c8dfa59ff7b2563087bdfea650e32796','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('89e5f7dd-1481-43d1-8773-e6d3eebe7c66','news-89e5f7dd-1481-43d1-8773-e6d3eebe7c66','اتحاد الغرف السعودية و«عِلم» يدشّنان منصة «تجّار» الرقمية في ليب 2026','اتحاد الغرف السعوديه و علم يدشنان منصه تجار الرقميه في ليب 2026','دشّن اتحاد الغرف السعودية وشركة «عِلم» رائدة الحلول الرقمية، منصة «تجّار» البوابة الرقمية الموحدة لخدمات الغرف التجارية، وذلك على هامش مؤتمر «ليب 2026» في الرياض؛ بهدف توحيد تجربة المستفيدين وتسهيل وصول قطاع الأعمال إلى خدمات الغرف عبر منظومة رقمية متكاملة. ووقّع الاتفاقية الرئيس التنفيذي لشركة «عِلم» محمد بن عبدالعزيز العمير، والأمين العام لاتحاد الغرف…','["وتزامن التدشين مع توقيع اتفاقية تتولى بموجبها «عِلم» تطوير وتشغيل أنظمة الغرف التجارية، وتوحيد تقديم خدمات التصديق والخدمات الأخرى عبر منصة «تجّار»، بما يدعم تكاملها مع الجهات الحكومية والخاصة وفق معايير الحوكمة وحماية الخصوصية.","ووقّع الاتفاقية الرئيس التنفيذي لشركة «عِلم» محمد بن عبدالعزيز العمير، والأمين العام لاتحاد الغرف السعودية المهندس سلطان بن محمد المسلّم.","وتأتي خدمة إدارة التصاديق إلكترونياً في مقدمة خدمات منصة «تجّار»، إذ تتيح لأصحاب المنشآت والمفوّضين تقديم طلبات تصديق الوثائق والعقود والمطبوعات وإدارتها ومتابعة حالتها، كما تمكّن الجهات الحكومية والخاصة والأطراف ذات العلاقة من التحقق من صحة التصاديق وموثوقية الوثائق الصادرة عن الغرف التجارية.","وتشمل المنصة كذلك إصدار العضويات وتجديدها وتحديث بياناتها واستعراضها، وتقديم طلبات التصاريح وإدارتها، وإدارة صلاحيات المفوّضين ومدد التفويض، إلى جانب محفظة إلكترونية لسداد رسوم الخدمات واستعراض الحركات المالية.","ويسهم المشروع في رفع كفاءة الإجراءات وجودة الخدمات المقدمة لقطاع الأعمال، وتعزيز موثوقية الوثائق والتصاديق، واختصار الوقت والجهد على المستفيدين عبر منصة موحدة تتيح لهم إنجاز معاملاتهم مع مختلف الغرف التجارية.","ومن المقرر أن يتوسع نطاق المنصة تدريجياً بإضافة مزيد من الخدمات والتكاملات الرقمية، والاستفادة من أدوات الذكاء الاصطناعي لدعم جودة الطلبات ومساعدة المستفيدين وتسريع عمليات المراجعة، إلى جانب تسهيل الوصول إلى الفرص الاستثمارية واستكشاف فرص النمو."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/w489jhz','https://sabq.org/article/w489jhz','','https://sabq.org/article/w489jhz','صحيفة سبق','الرياض','2026-09-03T09:21:00.000Z','2026-09-03T12:23:00.000Z','2026-09-03T20:30:55.447Z','https://media.sabq.org/news/2026/09/1b46030b-5c6f-4401-8cda-fb8e4508f6a3/w1280.webp','/api/media/89e5f7dd-1481-43d1-8773-e6d3eebe7c66','/api/media/89e5f7dd-1481-43d1-8773-e6d3eebe7c66?variant=thumbnail','اتحاد الغرف السعودية و«عِلم» يدشّنان منصة «تجّار» الرقمية في ليب 2026',1280,853,'valid','published','archived','valid',44,'9968250252522baef065439f8aca66ca754a98d4cc33c3d10392b0e7f469749f','1806b0f87d8d239758cbeebb3a9cf7bba6feb911c479c2c435f91349eedb02ad','محدّث','2026-09-03T20:30:55.447Z','2026-10-07T20:24:32.612Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الاقتصاد والأسواق","التقنية والتحول الرقمي","الرياض"]','["الصحة العامة","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"التقنية","score":3},{"category":"المناطق","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:42:17.920Z',200,49,0,'source_article_available','',NULL,NULL,'body:1bf997565cfd80c7aca5bab0539a7ff1247735e610c0e17bde8c9efc176471e9','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1652d1d0-1230-4fd6-a3d4-89a9df63b104','news-1652d1d0-1230-4fd6-a3d4-89a9df63b104','البحرين توقّع عقد مشاركتها في إكسبو 2030 الرياض وتنطلق نحو التنفيذ','البحرين توقع عقد مشاركتها في اكسبو 2030 الرياض وتنطلق نحو التنفيذ','وأضاف: «نتطلع إلى العمل عن كثب مع فريق مملكة البحرين خلال المرحلة المقبلة، وإلى مشاركة مميزة تعكس رؤيتها وثقافتها وطموحاتها، وتسهم في إثراء تجربة إكسبو 2030 الرياض».','["وقّعت مملكة البحرين عقد مشاركتها الرسمي في إكسبو 2030 الرياض، في خطوة تضع الإطار الرسمي لحضورها خلال أشهر المعرض الستة، وتُتيح لها المضيّ في استكمال الجوانب التنظيمية والتشغيلية كافة، بما فيها تطوير جناحها وبرامجها وتجاربها الموجّهة للزوار.","وقّع العقدَ في مملكة البحرين كلٌّ من الرئيس التنفيذي لإكسبو 2030 الرياض طلال المرّي، والشيخ خليفة بن أحمد بن عبدالله آل خليفة رئيس هيئة البحرين للثقافة والآثار.","وأكد الشيخ خليفة بن أحمد آل خليفة أن مشاركة مملكة البحرين تعكس عمق العلاقات الأخوية والتاريخية التي تجمع المملكة العربية السعودية ومملكة البحرين، وما تشهده من تعاون متنامٍ في مختلف المجالات، مشيراً إلى أن فرق العمل الوطنية تواصل جهودها لاستكمال الجوانب التحضيرية بما يضمن حضوراً بحرينياً متكاملاً يواكب أهمية الحدث.","وقال: «يجسّد توقيع عقد المشاركة حرص مملكة البحرين على الحضور الفاعل في هذا المحفل العالمي، وتقديم مشاركة تعكس هويتها ومنجزاتها وتطلعاتها المستقبلية، بما يعزز حضورها على الساحة الدولية».","من جانبه، أكد الرئيس التنفيذي لإكسبو 2030 الرياض طلال المرّي أن توقيع البحرين يعكس الزخم المتنامي مع انتقال الدول المشاركة من مرحلة تأكيد المشاركة إلى مرحلة التنفيذ الفعلي، مشيراً إلى أن ملامح إكسبو 2030 الرياض باتت تتشكّل بصورة أوضح من خلال الأجنحة والبرامج والتجارب التي ستقدّمها الدول المشاركة.","ومن المخطط أن تُنشئ مملكة البحرين جناحاً مستداماً يستمر لما بعد فترة إقامة المعرض، ليصبح جزءاً من القرية العالمية، أحد مكوّنات الإرث المستدام الذي سيتركه إكسبو 2030 الرياض.","وأكدت أكثر من 145 دولة مشاركتها في المعرض، وبدأت الدول الانتقال إلى مرحلة توقيع عقود المشاركة الرسمية، كان آخرها توقيع فرنسا عقدها الشهر الماضي في باريس على هامش زيارة صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء، حفظه الله.","ويأتي هذا التقدم في أعقاب التوقيع على اتفاقية الامتيازات والمزايا الممنوحة للمشاركين الدوليين بين المملكة العربية السعودية والمكتب الدولي للمعارض، التي تُرسّخ الإطار القانوني والإداري المنظّم لمشاركة الدول والمنظمات الدولية."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/4i56tzp','https://sabq.org/article/4i56tzp','','https://sabq.org/article/4i56tzp','صحيفة سبق','الرياض','2026-09-03T08:45:00.000Z','2026-09-03T11:46:00.000Z','2026-09-03T20:30:55.886Z','https://media.sabq.org/news/2026/09/18d1e54e-37e8-4501-94c5-4264cd8d960a/w1600.webp','/api/media/1652d1d0-1230-4fd6-a3d4-89a9df63b104','/api/media/1652d1d0-1230-4fd6-a3d4-89a9df63b104?variant=thumbnail','البحرين توقّع عقد مشاركتها في إكسبو 2030 الرياض وتنطلق نحو التنفيذ',1600,1066,'valid','published','archived','valid',92,'4549189d2fe90b73bb63fe8c11deb90f4b7cff6a78d98a56cefceec485bcd7f6','b44aedd37c9c89de93b2b024490c60915c7c5f6b15a83a8210e7bb94678c9094','محدّث','2026-09-03T20:30:55.886Z','2026-10-07T19:42:44.279Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء حفظه الله ويأتي","هيئة البحرين للثقافة والآثار وأكد","رئيس هيئة البحرين للثقافة والآثار","الثقافة والفنون","الرياض"]','["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء حفظه الله ويأتي","هيئة البحرين للثقافة والآثار وأكد","رئيس هيئة البحرين للثقافة والآثار","الثقافة والفنون"]','classified','','[{"category":"المناطق","score":3},{"category":"الرياضة","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:42:44.279Z',200,59,0,'source_article_available','',NULL,NULL,'body:ca05a3161276e296b46b48ad0cf0883c7d6491d29916641e96a1c0206997d631','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cca52234-4aee-4cd1-a906-73160817cd28','news-cca52234-4aee-4cd1-a906-73160817cd28','الهلال يحسم صفقة مارتينيلي.. البرازيلي يوقّع 4 سنوات قادمًا من آرسنال','الهلال يحسم صفقه مارتينيلي البرازيلي يوقع 4 سنوات قادما من ارسنال','حسم نادي الهلال صفقة المهاجم البرازيلي غابريال مارتينيلي، بعدما أعلن الأربعاء تعاقده معه قادمًا من آرسنال، بطل الدوري الإنجليزي الممتاز، بعقد يمتد 4 أعوام.','["وسيبدأ مارتينيلي، البالغ من العمر 25 عامًا، تدريباته مع الهلال مساء الخميس، قبل مواجهة الشباب يوم الجمعة ضمن منافسات دوري روشن السعودي .","وأوضح النادي أن مجلس إدارة شركة الهلال برئاسة الأمير نواف بن سعد أنهى إجراءات انتقال اللاعب، فيما جرت مراسم توقيع العقد في مركز الماجدية الرياضي.","ويمثل مارتينيلي ثالث صفقات الهلال الأجنبية في فترة الانتقالات الصيفية الجارية، بعدما تعاقد النادي مع الجناح الهولندي كريسنسيو سامرفيل قادمًا من وست هام يونايتد، وواتكينز من أستون فيلا.","ويخوض المهاجم البرازيلي ثالث تجربة له على مستوى الأندية، بعدما بدأ مسيرته مع إيتوانو البرازيلي، قبل أن ينتقل مباشرة إلى آرسنال في صيف 2019.","كما سبق لمارتينيلي تمثيل منتخب البرازيل في المونديال الأخير، ليبدأ الآن تجربة جديدة مع الهلال في دوري روشن السعودي."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/2qnqez1lv','https://ajel.sa/sports/2qnqez1lv','https://ajel.sa/sports/2qnqez1lv','https://ajel.sa/sports/2qnqez1lv','فريق التحرير','الرياض','2026-09-03T11:01:00.000Z','Wed, 07 Oct 2026 19:42:47 GMT','2026-09-03T20:30:55.892Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/bd1dcc75-a917-4210-9b30-812247f1540c-16x9-1200x676-r-d-87hv.webp','/api/media/cca52234-4aee-4cd1-a906-73160817cd28','/api/media/cca52234-4aee-4cd1-a906-73160817cd28?variant=thumbnail','مارتينيلي',1200,675,'valid','published','archived','valid',41,'a6292001de82bd4ac886f95190a8036df013a33bb688c726d803cf11c0f15efa','164cd9e540404db90ad7e5b5c84cc43b500ed6c33a4a1be4b58ee109f59deeaa','محدّث','2026-09-03T20:30:55.892Z','2026-10-07T20:24:32.619Z','','',0,0,'saudi_region','عادي',49,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إدارة شركة الهلال برئاسة","شركة الهلال برئاسة الأمير نواف","التعليم والتدريب","الرياضة السعودية","الرياض"]','["مجلس إدارة شركة الهلال برئاسة","شركة الهلال برئاسة الأمير نواف","التعليم والتدريب","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:48.886Z',200,49,0,'source_content_changed','',NULL,NULL,'body:c663fe4402e9115097ed3bab32e8ffd338d1e050a9d306e2ed02ab85b1f610fd','Wed, 07 Oct 2026 19:42:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4af2f92e-d001-4370-bc6d-f241ebc9ea27','news-4af2f92e-d001-4370-bc6d-f241ebc9ea27','المجدوعي ديبال DEEPAL شريك و ناقل رسمي لمؤتمرLEAP 2026','المجدوعي ديبال deepal شريك و ناقل رسمي لمؤتمرleap 2026','تشارك المجدوعي كشريك وناقل رسمي لمعرض LEAP 2026 للعام الثالث على التوالي، والذي تستضيفه العاصمة الرياض خلال الفترة من 31 أغسطس إلى 3 سبتمبر، في تأكيد جديد على التزامها بدعم أبرز الفعاليات التقنية والابتكارية في المملكة.','["وتشهد مشاركة هذا العام حضور علامة ديبال (DEEPAL)، التي أطلقتها المجدوعي في المملكة كعلامة متخصصة في حلول التنقل المتقدمة وطرازاتREEV، حيث تشارك العلامة كشريك وناقل رسمي للمؤتمر، بما يعكس توجهها نحو تقديم حلول تنقل ذكية ومتطورة تتماشى مع طبيعة الحدث ومكانته.","وبصفتها الناقل الرسمي للمعرض، توفر ديبال المجدوعي حلول نقل مخصصة خلال مؤتمر LEAP عبر أسطول من مركباتها، يشمل طراز DEEPAL S07وطرازها الرائد الجديد DEEPAL S09، بما يدعم حركة المشاركين والزوار ويسهم في تقديم تجربة تنقل سلسة ومتكاملة تتناسب مع حجم الحدث الذي يستقطب آلاف الزوار من مختلف أنحاء العالم على مدار أيام المعرض الأربعة.","كما تشهد مشاركة ديبال المجدوعي في LEAP 2026 إطلاق طرازها الجديد DEEPAL S09 للمرة الأولى في المملكة العربية السعودية، في خطوة تعكس طموح العلامة لتقديم تجربة جديدة تجمع بين الفخامة والتكنولوجيا وحلول التنقل الذكية والمتقدمة.","ويمثل طراز DEEPAL S09 رؤية ديبال في الجمع بين التصميم الفاخر والتقنيات المتطورة وتجربة التنقل المستقبلية.","وتأتي السيارة بتصميم راقٍ يتسع لستة ركاب ضمن ثلاثة صفوف، لتوفر مستويات عالية من الرحابة والراحة لجميع الركاب، إلى جانب مجموعة من التقنيات المتقدمة التي تعزز تجربة القيادة والتنقل.","وتأتي هذه الشراكة في ظل التطور المتسارع الذي يشهده قطاع التقنية والتنقل في المملكة، حيث أصبحت التكنولوجيا والابتكار من العناصر الأساسية في تطوير تجارب النقل الحديثة.","كما تعكس استمرارية مشاركة المجدوعي فيLEAP توجهها نحو تعزيز حضورها في قطاع التنقل الذكي والمساهمة في دعم الفعاليات والمنصات التي تجمع نخبة من رواد التقنية والأعمال والابتكار من مختلف أنحاء العالم.","ويُعد مؤتمر LEAP من أبرز المنصات العالمية التي تستضيفها المملكة في مجال التكنولوجيا والابتكار، حيث يجمع الشركات العالمية ورواد الأعمال والمستثمرين والخبراء لاستعراض أحدث التقنيات والحلول التي ترسم ملامح المستقبل."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/nw0z5ue','https://sabq.org/article/nw0z5ue','','https://sabq.org/article/nw0z5ue','صحيفة سبق','الرياض','2026-09-03T09:05:00.000Z','2026-09-03T12:06:00.000Z','2026-09-03T20:30:56.006Z','https://media.sabq.org/news/2026/09/c7429a49-7bce-43cb-9bfd-6a98465cae33/w1600.webp','/api/media/4af2f92e-d001-4370-bc6d-f241ebc9ea27','/api/media/4af2f92e-d001-4370-bc6d-f241ebc9ea27?variant=thumbnail','المجدوعي ديبال DEEPAL شريك و ناقل رسمي لمؤتمرLEAP 2026',1600,1066,'valid','published','archived','valid',46,'56b652a2d45c1c999144ff56d0d68b59e4054a18ae5ccc0ff9fe89794b6a9e11','7fcc564d7cce71733dd84dc2eff883e0077ff9d7da969287ddb0acae388ecffe','محدّث','2026-09-03T20:30:56.006Z','2026-10-07T19:42:20.042Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي","الرياض"]','["التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"التقنية","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:42:20.042Z',200,52,0,'source_article_available','',NULL,NULL,'body:036e93883f3ebd93ebd53afef185ff6f74a4d5999e96e2fed11fa4fef87446ce','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f28b1b5f-64b7-441d-8a83-9837d3b4142d','news-f28b1b5f-64b7-441d-8a83-9837d3b4142d','«قسطرة القلب السعودية» تنطلق بنسخة تاسعة أضخم وتُجري 7 عمليات نوعية مباشرة','قسطره القلب السعوديه تنطلق بنسخه تاسعه اضخم وتجري 7 عمليات نوعيه مباشره','ويضم البرنامج العلمي للمؤتمر محاضرات وورش عمل وبرامج تدريبية، إلى جانب إجراء 7 عمليات قسطرة نوعية ومعقدة على الهواء مباشرة لأغراض تعليمية، ينفذ 5 منها خبراء سعوديون في الرياض وجدة وأبها، فيما تُجرى عمليتان بمشاركة خبراء من الولايات المتحدة الأمريكية.','["أطلقت جمعية قسطرة القلب السعودية، خلال مؤتمر صحفي أُقيم في الرياض الخميس، أعمالَ النسخة التاسعة من المؤتمر السعودي الدولي للقسطرة والتداخلات القلبية (SACIS)، في نسخة وصفتها اللجنة العلمية بالأضخم، تستعرض أحدث التطورات العلمية والتقنية في مجال التداخلات القلبية، وتناقش مستقبل التخصص ودور الذكاء الاصطناعي في تحسين الممارسة الطبية.","المحمدي: التقنية الأحدث ليست بالضرورة الأكثر أمانًا أكد نائب رئيس جمعية قسطرة القلب السعودية الدكتور محمد المحمدي أن نسخة هذا العام تتميز بمواكبتها للمشاريع الوطنية، وتعزيز التكامل بين خبرات الجمعية والمؤسسات الوطنية، بما يسهم في تطوير منظومة التداخلات القلبية في المملكة.","وشدد المحمدي على أن مواكبة أحدث التقنيات تمثل أولوية في علاج أمراض القلب، غير أن حداثة التقنية لا تعني بالضرورة أنها الأكثر أمانًا أو فاعلية، مبينًا أن معيار اعتماد أي تقنية يجب أن يرتبط بقيمتها الحقيقية للمريض وقدرتها على تحسين النتائج العلاجية.","وأشار إلى أن الذكاء الاصطناعي يشهد توسعًا متسارعًا في المجال الطبي، إلا أن استخدامه لا يعني الاستغناء عن الطبيب، وإنما توظيفه أداةً مساندة ترفع مستوى الدقة وتحسّن القرار الطبي، لا سيما في تحليل القياسات والصور داخل الأوعية الدموية.","عسيري لـ«سبق»: لسنا أمام منافس للطبيب وفي رده على سؤال «سبق» خلال المؤتمر الصحفي، أكد رئيس اللجنة العلمية الدكتور سالم عسيري أن الحديث عن إحلال الذكاء الاصطناعي محل الطبيب في عمليات القسطرة لا يزال مبكرًا، مشددًا على أن دوره الأكثر واقعية هو دعم الطبيب وتعزيز دقة الإجراءات والقياسات.","وقال عسيري: «ما زال مبكرًا على الذكاء الاصطناعي أن يأخذ منا كل شيء الآن، لكنه سيكون عاملًا مساعدًا لنا، ونحن لا نرى منافسًا من الذكاء الاصطناعي».","وكشف أن اللجنة العلمية استقبلت مئات الأوراق العلمية من أطباء وباحثين داخل المملكة وخارجها، جرى اختيار نحو 26 ورقة علمية منها لتقديمها ومناقشتها خلال المؤتمر، تتضمن حالات معقدة وأبحاثًا ودراسات متخصصة.","وأوضح أن المؤتمر لا يكتفي باستعراض التقنيات الحديثة، بل يسعى إلى الانتقال بالتخصص من مرحلة نقل المعرفة إلى المشاركة في إنتاج الدليل الطبي وصناعة القرار العلمي، مشيرًا إلى أن الجمعية تعمل بالتعاون مع المعهد الوطني للأبحاث على إطلاق دراسات سريرية وفق منهجية التجارب العشوائية المحكمة (Randomized Controlled Trials) على مرضى داخل المملكة."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wOeR3k1','https://sabq.org/article/wOeR3k1','','https://sabq.org/article/wOeR3k1','عبدالحكيم شار','الرياض','2026-09-03T08:46:00.000Z','2026-09-03T13:39:00.000Z','2026-09-03T20:30:56.019Z','https://media.sabq.org/news/2026/09/7b8b57c0-bbe5-4f96-a014-ff641606bf5d/w1600.webp','/api/media/f28b1b5f-64b7-441d-8a83-9837d3b4142d','/api/media/f28b1b5f-64b7-441d-8a83-9837d3b4142d?variant=thumbnail','«قسطرة القلب السعودية» تنطلق بنسخة تاسعة أضخم وتُجري 7 عمليات نوعية مباشرة',1600,1066,'valid','published','archived','valid',49,'828e8293727858f83c41afe71598c39c9d52de8f4ba89b4227882a79fda180f0','b6cacccf951b7543f528cdc60a919bdd083f7020dbeaf8605944eb0bf6a4228c','محدّث','2026-09-03T20:30:56.019Z','2026-10-07T19:43:00.900Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس جمعية قسطرة القلب السعودية","الصحة العامة","التعليم والتدريب","التقنية والتحول الرقمي","جدة","عسير","الرياض","أوروبا"]','["رئيس جمعية قسطرة القلب السعودية","الصحة العامة","التعليم والتدريب","التقنية والتحول الرقمي","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":4.5},{"category":"المجتمع","score":1.5},{"category":"التقنية","score":1.5}]','Active','2026-10-07T19:43:00.900Z',200,60,0,'source_article_available','',NULL,NULL,'body:d5356a6a28bfdc8b8ba1d3a7d440f41a2b7050fbdbe5971e49c60bfd8ce217e2','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('27b0a4b8-d215-4954-8183-07fd9ce543fa','news-27b0a4b8-d215-4954-8183-07fd9ce543fa','ترامب يؤكد امتلاك واشنطن ذخائر "غير محدودة" والقيادة المركزية تعلن تراجع قدرات إيران','ترامب يؤكد امتلاك واشنطن ذخائر غير محدوده والقياده المركزيه تعلن تراجع قدرات ايران','أعلن الرئيس الأمريكي دونالد ترامب امتلاك الولايات المتحدة كميات شبه غير محدودة من الذخائر المتوسطة والعالية الجودة، مؤكداً الجاهزية التامة لأي حرب قد تندلع في أي لحظة، في وقت كشفت فيه القيادة المركزية الأمريكية عن تراجع حاد في القدرات العسكرية الإيرانية جراء الضربات المستمرة.','["ونفى تارمب، في منشور عبر حسابه على منصة « تروث سوشيال » اليوم (الخميس)، صحة التقارير الإعلامية المتعلقة بالعملية العسكرية في إيران ، مبيناً أن مخزونات الذخيرة الحالية تتجاوز بكثير ما يمكن استخدامه في الحرب الحالية أو أي نزاع طارئ آخر مستبعد وقوعه.","وأشار الرئيس الأمريكي إلى أن بلاده تنتج الذخائر بمستويات غير مسبوقة وتعمل على تخزينها لحسابها الخاص بدلاً من بيعها للخارج، معلناً العزم على استئناف مبيعات الذخائر للحلفاء قريباً.","وفي سياق متصل، هدد المتحدث باسم القيادة المركزية الأمريكية، تيموثي هوكينز، باستمرار الضربات العسكرية ضد إيران طالما استمرت تهديداتها، لافتاً إلى أن قدرات طهران العسكرية شهدت تراجعاً شديداً.","وانتقد ترمب الدعم المالي والعسكري الذي قدمته إدارة الرئيس السابق جو بايدن ل أوكرانيا وحلف شمال الأطلسي (الناتو)، موضحاً أن كييف حصلت مجاناً ودون مقابل على ذخائر تفوق بمراحل ما تم استخدامه في العملية العسكرية ضد إيران.","وأضاف الرئيس الأمريكي أن مئات المليارات من الدولارات قُدمت مجاناً، وكان يتوجب على الجانب الأوروبي دفع تكلفتها حال طُلب منه ذلك، متوعداً بالمطالبة بتلك الأموال حتى وإن جاءت الخطوة متأخرة."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/vf6rnqgyi','https://ajel.sa/international/vf6rnqgyi','https://ajel.sa/international/vf6rnqgyi','https://ajel.sa/international/vf6rnqgyi','فريق التحرير','عسير','2026-09-03T10:06:00.000Z','Wed, 07 Oct 2026 19:42:48 GMT','2026-09-03T20:30:56.253Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-2-W0eQbGlL.jpg','/api/media/27b0a4b8-d215-4954-8183-07fd9ce543fa','/api/media/27b0a4b8-d215-4954-8183-07fd9ce543fa?variant=thumbnail','ترامب',1200,675,'valid','published','archived','valid',41,'d0195e16b77c2081f735c71a011ac5839a66019ab10062231282f6078e79aa71','9c22cb3d9bef14cdb8bdfc96e9122d2bc548a48f9278ecceac72c3344a5850fb','محدّث','2026-09-03T20:30:56.253Z','2026-10-07T20:24:32.626Z','','',0,0,'saudi_region','عادي',57,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","إيران","أوكرانيا","الولايات المتحدة"]','["الصحة العامة","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:50.018Z',200,54,0,'source_content_changed','',NULL,NULL,'body:76e526f45865e6898a5d8e6994a75e7c9c0a840f340d079fb58dbc8a0bba1a59','Wed, 07 Oct 2026 19:42:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0d91795c-f1f1-45d8-b0d8-7421384c14c7','news-0d91795c-f1f1-45d8-b0d8-7421384c14c7','بالصور .. هيئة الأدب والنشر والترجمة تدشّن جناح المملكة المشارك في معرض موسكو الدولي للكتاب 2026','بالصور هيئه الادب والنشر والترجمه تدشن جناح المملكه المشارك في معرض موسكو الدولي للكتاب 2026','دشنت هيئة الأدب والنشر والترجمة اليوم، جناح المملكة العربية السعودية المشارك في معرض موسكو الدولي للكتاب 2026، في العاصمة الروسية موسكو، خلال الفترة من 2 إلى 6 سبتمبر.','["وأكد الرئيس التنفيذي لهيئة الأدب والنشر والترجمة، الدكتور عبداللطيف بن عبدالعزيز الواصل، أن مشاركة المملكة في معرض موسكو تأتي تجسيداً لعمق العلاقات الثقافية التاريخية التي تجمع المملكة العربية السعودية و جمهورية روسيا الاتحادية ، وسعياً لإبراز الحراك الأدبي والمعرفي السعودي أمام الجمهور الروسي والدولي، مؤكداً أن الجناح السعودي يمثّل نافذة ثقافية متكاملة تعكس التنوع الفكري والإبداعي الذي تعيشه المملكة في ظل رؤية السعودية 2030.","وأوضح أن الهيئة تهدف من خلال هذا الحضور إلى دعم المبدعين والناشرين السعوديين، وفتح آفاق جديدة للتبادل الثقافي وصناعة النشر، مشيراً إلى أن المعرض يعد منصة حيوية لتعزيز الحوار الثقافي ومد جسور التواصل المعرفي بين المثقفين في مختلف المحافل الدولية.","ويضم الجناح السعودي مجموعة من الجهات الحكومية والكيانات الثقافية بقيادة هيئة الأدب والنشر والترجمة، تشمل مكتبة الملك فهد الوطنية ، و مكتبة الملك عبد العزيز العامة ، ومجمع الملك عبدالعزيز للمكتبات الوقفية، و دارة الملك عبد العزيز ، ووزارة الشؤون الإسلامية والدعوة والإرشاد، و مجمع الملك فهد لطباعة المصحف الشريف ، وشركة ناشر للنشر والتوزيع، ومركز الملك عبدالعزيز للتواصل الحضاري، و الملحقية الثقافية السعودية في تركيا ، وجامعة الأميرة نورة بنت عبدالرحمن، ومركز الأمير محمد بن سلمان للخط العربي، مما يقدم صورة متكاملة للمشهد الثقافي الوطني.","كما أعدت الهيئة برنامجاً ثقافياً مصاحباً يتضمن سلسلة من الندوات الحوارية، والأمسيات الشعرية، التي يشارك فيها نخبة من الأدباء والمثقفين السعوديين، تتناول قضايا الأدب والنشر والترجمة، وتسلط الضوء على المنجز الثقافي السعودي وتأثيره في الفضاء الدولي.","وتأتي هذه المشاركة في إطار جهود هيئة الأدب والنشر والترجمة لتعزيز الحضور الثقافي السعودي في المحافل الدولية الكبرى، والتعريف بالمبادرات الوطنية الداعمة للكتاب والمؤلف، بما يعزز مكانة المملكة كوجهة ثقافية رائدة ومنارة للعطاء المعرفي."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/entertainment/59vs5iw4v','https://ajel.sa/entertainment/59vs5iw4v','https://ajel.sa/entertainment/59vs5iw4v','https://ajel.sa/entertainment/59vs5iw4v','علي الجريبي','المدينة المنورة','2026-09-03T10:31:00.000Z','Wed, 07 Oct 2026 19:42:49 GMT','2026-09-03T20:30:56.467Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/150283-crop-VEMzyaU_.jpg','/api/media/0d91795c-f1f1-45d8-b0d8-7421384c14c7','/api/media/0d91795c-f1f1-45d8-b0d8-7421384c14c7?variant=thumbnail','بالصور .. هيئة الأدب والنشر والترجمة تدشّن جناح المملكة المشارك في معرض موسكو الدولي للكتاب 2026',1200,675,'valid','published','archived','valid',60,'2e145580741c1f0df224a142b7a2d11319407b25c18e155bfdc587efc24e984d','d0993fcec24b5e2f21b9f01ab59b938f31d3515608b81a305cdb32acd20c2aa9','محدّث','2026-09-03T20:30:56.467Z','2026-10-07T19:42:51.126Z','','',0,0,'saudi_region','مهم',79,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الأدب والنشر والترجمة تدش","التعليم والتدريب","تركيا","روسيا"]','["هيئة الأدب والنشر والترجمة تدش","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"الطاقة والصناعة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:42:51.126Z',200,50,0,'source_content_changed','',NULL,NULL,'body:e01a7e850513a486e33ad796f5890aea6f6d5bb38371e49c40a6a82c756eeedf','Wed, 07 Oct 2026 19:42:49 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fb91e711-42ff-48a4-b546-9b96f8604971','news-fb91e711-42ff-48a4-b546-9b96f8604971','أول عملية منذ سقوط الأسد.. سوريا تبدأ تدمير مواد كيميائية على أراضيها','اول عمليه منذ سقوط الاسد سوريا تبدا تدمير مواد كيميائيه علي اراضيها','وتواصل سوريا، في إطار هذا المسار، العمل على كشف مكونات البرنامج الكيميائي السابق وتأمين ما يتم العثور عليه من مواد وذخائر، وصولًا إلى تدميرها وفق الإجراءات الفنية المعتمدة وتحت إشراف منظمة حظر الأسلحة الكيميائية.','["بدأت سوريا تنفيذ عملية لتدمير مواد كيميائية تعود إلى حقبة الرئيس المخلوع بشار الأسد ، وأبلغت مجلس الأمن الدولي، الخميس، بأن العملية تمثل الأولى من نوعها على الأراضي السورية منذ أكثر من عقد، وكذلك الأولى منذ سقوط النظام السابق.","وتندرج الخطوة ضمن تعاون سوريا مع منظمة حظر الأسلحة الكيميائية للعمل على كشف كامل مكونات البرنامج الكيميائي الذي كان يديره النظام المخلوع، بالتوازي مع تأمين المواد والذخائر التي يتم العثور عليها تمهيدًا لتدميرها وفق الإجراءات الفنية المعتمدة وتحت إشراف المنظمة.","وقال مندوب سوريا الدائم لدى الأمم المتحدة، إبراهيم علبي: «هذه هي عملية التدمير الأولى منذ تحررنا من النظام السابق»، مضيفًا: «هي أيضا الأولى من نوعها لتدمير مواد كيميائية على الأراضي السورية منذ أكثر من عقد».","وكانت الحكومة السورية قد بدأت خلال الفترة الماضية، بالتعاون مع شركاء دوليين، جهودًا تستهدف تصفية بقايا مخزون الأسلحة الكيميائية، إلى جانب الكشف عن المواقع والمواد التي لم يعلن عنها النظام المخلوع.","وأكد علبي أن بدء عملية التدمير يحمل دلالة تتجاوز التخلص من المواد التي يتم العثور عليها، قائلاً: «أنها لحظة تثبت فعلاً أن الملف الذي شكل لسنوات مصدراً للخطر على السوريين والعالم أيضاً، يمكن أن يتحول إلى نموذج لما يمكن للدبلوماسية المقترنة بالعزم والإرادة الصادقة وروح التعاون الدولي أن تحققه على الأرض»."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/ursmthszx','https://ajel.sa/international/ursmthszx','https://ajel.sa/international/ursmthszx','https://ajel.sa/international/ursmthszx','فريق التحرير','','2026-09-03T10:31:00.000Z','Wed, 07 Oct 2026 19:42:50 GMT','2026-09-03T20:30:56.518Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-tSFqG7Xe.jpg','/api/media/fb91e711-42ff-48a4-b546-9b96f8604971','/api/media/fb91e711-42ff-48a4-b546-9b96f8604971?variant=thumbnail','إبراهيم علبي',1200,675,'valid','published','archived','valid',41,'ed221c65d33a1e01dbab9882d722ffee92be4185e376e2ef61f25189574f5b93','53706d2f73a02bb7019a729fb5fc5a787d6c3ede74897141df8fad56b72f42ee','محدّث','2026-09-03T20:30:56.518Z','2026-10-07T20:24:32.633Z','','',0,0,'gulf_arab','عادي',43,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس الأمن الدولي الخميس بأن","الأمم المتحدة إبراهيم علبي هذه","السياسة والعلاقات الدولية","سوريا"]','["مجلس الأمن الدولي الخميس بأن","الأمم المتحدة إبراهيم علبي هذه","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:52.501Z',200,54,0,'source_content_changed','',NULL,NULL,'body:d697b98e37acdc8665bcfe34f908967f7e79f6a73935ec1a0178f50fbc3681c7','Wed, 07 Oct 2026 19:42:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c1225d08-c4d9-49d8-b068-c3405b659ea6','news-c1225d08-c4d9-49d8-b068-c3405b659ea6','تكريم المراعي في "ليب 2026" تقديرًا لريادتها في التحول الرقمي','تكريم المراعي في ليب 2026 تقديرا لريادتها في التحول الرقمي','تم تكريم شركة المراعي خلال مؤتمر "ليب 2026" تقديرًا لمبادراتها ونجاحها في تحقيق تقدم كبير في التحول الرقمي وتوظيف التقنيات الرقمية المتقدمة وتبنّي تقنيات إنترنت الأشياء (IoT) في أعمالها وفي إدارة سلاسل الإمداد وأنظمة الإنتاج وغيرها.','["وتسلّم التكريم الرئيس التنفيذي لشركة المراعي، الأستاذ فواز الجاسر، خلال فعاليات المؤتمر الذي يعد أحد أبرز الفعاليات التقنية العالمية التي تستضيفها المملكة، والذي يجمع قادة التكنولوجيا والمبتكرين والمستثمرين وصُنّاع السياسات من مختلف أنحاء العالم لاستعراض التقنيات التحويلية في مختلف القطاعات.","يأتي هذا التكريم تتويجًا لخبرة شركة المراعي، أكبر شركة ألبان متكاملة رأسيًا في العالم، في دمج القدرات الرقمية عبر سلسلة القيمة للإسهام في تحقيق المرونة والكفاءة في أنظمة إنتاج الغذاء والاستثمار في الابتكار والجهود التي تدعم الأمن الغذائي والاستدامة على المدى الطويل لتوفير منتجات عالية الجودة للمستهلكين.","يُذكر أن مؤتمر \"ليب\" يُعقد سنويًا في الرياض، ويُعد منصة عالمية للابتكار والتحول الرقمي، حيث يجمع كبرى شركات التكنولوجيا والشركات الناشئة والمستثمرين والجهات الحكومية لاستكشاف التقنيات التي تُشكّل المستقبل.","وقد انطلق المؤتمر تماشيًا مع مستهدفات رؤية السعودية 2030، وأصبح أحد أكبر التجمعات التقنية في العالم."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ywplmq0','https://sabq.org/article/ywplmq0','','https://sabq.org/article/ywplmq0','صحيفة سبق','الرياض','2026-09-03T08:35:00.000Z','2026-09-03T11:35:00.000Z','2026-09-03T20:30:56.613Z','https://media.sabq.org/news/2026/09/a3083f7f-0801-4279-b33a-c565558b17fe/w1280.webp','/api/media/c1225d08-c4d9-49d8-b068-c3405b659ea6','/api/media/c1225d08-c4d9-49d8-b068-c3405b659ea6?variant=thumbnail','تكريم المراعي في "ليب 2026" تقديرًا لريادتها في التحول الرقمي',1280,720,'valid','published','archived','valid',56,'5711b2b6c98964a816280fb52377da9aa657d04b54f18160444faef5dc44cdc0','157e2d90f32298d3095125a23dbf0d22607cd16110c61ee029d34bb24cc0c9af','محدّث','2026-09-03T20:30:56.613Z','2026-10-07T19:43:00.874Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة المراعي خلال مؤتمر ليب","الاقتصاد والأسواق","التقنية والتحول الرقمي","الرياض"]','["شركة المراعي خلال مؤتمر ليب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:00.874Z',200,58,0,'source_article_available','',NULL,NULL,'body:f5dcad4a1452ee85b8bb476eeb2a8351148a1e67eb133178b4190b49445a230d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9b961871-66f7-433d-94a8-cbfffd137107','news-9b961871-66f7-433d-94a8-cbfffd137107','العلا ينفرد بصدارة دوري الدرجة الأولى بعلامة كاملة بعد 3 جولات','العلا ينفرد بصداره دوري الدرجه الاولي بعلامه كامله بعد 3 جولات','اختتمت منافسات الجولة الثالثة من دوري الدرجة الأولى للمحترفين، وأسفرت نتائجها عن انفراد نادي العلا بالصدارة بالعلامة الكاملة، في جولة لافتة شهدت 6 تعادلات في وقت واحد.','["العلا يواصل انتصاراته حقق العلا انتصاره الثالث تواليًا بتخطي ضيفه الرائد بثنائية نظيفة، رافعًا رصيده إلى 9 نقاط في صدارة الترتيب منفردًا، فيما توقف رصيد الرائد عند 3 نقاط متراجعًا إلى المركز الـ 13.","جدة يتعثر للمرة الأولى بعد انتصارين متتاليين، تعثّر جدة لأول مرة هذا الموسم إثر تعادله السلبي أمام مضيفه الجيل، رافعًا رصيده إلى 7 نقاط ومتراجعًا إلى مركز الوصافة، فيما حصد الجيل نقطته الأولى في المركز الـ 18.","الطائي يواصل الانتصارات واصل الطائي مسيرته المنتصرة بتحقيق فوز ثمين على حساب ضيفه الجندل بنتيجة 2-1، ليتقدم إلى المركز الثالث برصيد 6 نقاط، فيما توقف رصيد الجندل عند نقطة وحيدة في المركز الـ 17.","الصقر يواظب على التعادل لا يزال الصقر متمسكًا بنقطة في كل مباراة؛ إذ خرج بنقطته الثالثة هذا الموسم في المركز الـ 12 إثر التعادل السلبي أمام ضيفه الأخدود، الذي رفع بدوره رصيده إلى 5 نقاط في المركز الرابع.","تعادلات تملأ الجولة خطف الزلفي تعادلًا ثمينًا من ملعب مضيفه العروبة بهدف لكل منهما، ليرفع رصيده إلى 5 نقاط في المركز الخامس، بينما حصد العروبة نقطته الثانية في المركز الـ 14.","وعاد العدالة من ملعب مضيفه البكيرية بفوز بهدف نظيف، رافعًا رصيده إلى 4 نقاط في المركز السادس، فيما توقف رصيد البكيرية عند نقطتين في المركز الـ 15.","وحسم التعادل الإيجابي 1-1 مباراة النجمة مع الجبلين، إذ رفع النجمة رصيده إلى 4 نقاط في المركز السابع بفارق الأهداف عن الجبلين الذي حلّ ثامنًا بالرصيد ذاته.","وبالنتيجة ذاتها تعادل هجر مع ضيفه الأنوار، ليحصد هجر نقطته الرابعة في المركز التاسع، بينما رفع الأنوار رصيده إلى نقطتين في المركز الـ 16."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/3ych7mv','https://sabq.org/article/3ych7mv','','https://sabq.org/article/3ych7mv','صحيفة سبق','مكة المكرمة','2026-09-03T08:43:00.000Z','2026-09-03T12:11:00.000Z','2026-09-03T20:30:56.632Z','https://media.sabq.org/news/2026/09/e8d3abdf-d3ae-419c-a71b-d6444ffaad36/w1600.webp','/api/media/9b961871-66f7-433d-94a8-cbfffd137107','/api/media/9b961871-66f7-433d-94a8-cbfffd137107?variant=thumbnail','العلا ينفرد بصدارة دوري الدرجة الأولى بعلامة كاملة بعد 3 جولات',1600,953,'valid','published','archived','valid',59,'c7a1cc1ba94968990ec10abfa3a8634bde31e40399b276e462190ebf4b5952b1','3fec6545d7a3c1de16ed824bb3e44646c410971e9b71ed8fa0b0fe2f01c1cd23','محدّث','2026-09-03T20:30:56.632Z','2026-10-07T19:43:02.133Z','','',0,0,'saudi_region','عادي',61,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الرياضة السعودية","جدة"]','["السفر والسياحة","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"التقنية","score":0},{"category":"المناطق","score":-3.5}]','Active','2026-10-07T19:43:02.133Z',200,55,0,'source_article_available','',NULL,NULL,'body:fc7c1144cc291bdff76e9ed5e4055ca0c222033d53d5cada83d5178f9fa17e0f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9c7b64bc-cd77-47a2-92ee-427c3af9abb4','news-9c7b64bc-cd77-47a2-92ee-427c3af9abb4','الملك سلمان وولي العهد يهنئان رئيسة إستونيا المنتخبة','الملك سلمان وولي العهد يهنئان رئيسه استونيا المنتخبه','بعث خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود برقية تهنئة إلى فخامة السيدة أوله ماديسي، بمناسبة انتخابها رئيسةً لجمهورية إستونيا. وأعرب الملك المفدى عن أصدق التهاني وأطيب التمنيات بالتوفيق والسداد لفخامتها، متمنياً لشعب جمهورية إستونيا الصديق المزيد من التقدم والازدهار.','["بعث خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود برقية تهنئة إلى فخامة السيدة أوله ماديسي، بمناسبة انتخابها رئيسةً لجمهورية إستونيا.","وأعرب الملك المفدى عن أصدق التهاني وأطيب التمنيات بالتوفيق والسداد لفخامتها، متمنياً لشعب جمهورية إستونيا الصديق المزيد من التقدم والازدهار.","وفي السياق ذاته، بعث صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء، برقية تهنئة إلى فخامة السيدة أوله ماديسي بالمناسبة ذاتها.","وعبّر سمو ولي العهد عن أصدق التهاني وأطيب التمنيات بالتوفيق والسداد لفخامتها، ولشعب جمهورية إستونيا الصديق المزيد من التقدم والرقي."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/x38hilg','https://sabq.org/article/x38hilg','','https://sabq.org/article/x38hilg','صحيفة سبق','عسير','2026-09-03T08:29:00.000Z','2026-09-03T11:30:00.000Z','2026-09-03T20:30:56.705Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/345e0efd-8e7f-4017-5e15-e99572dc9700/public','/api/media/9c7b64bc-cd77-47a2-92ee-427c3af9abb4','/api/media/9c7b64bc-cd77-47a2-92ee-427c3af9abb4?variant=thumbnail','الملك سلمان وولي العهد يهنئان رئيسة إستونيا المنتخبة',500,319,'valid','published','archived','valid',99,'60d4700a5e04cf0aa647e2a7930092f6b0c2ca5fbedfd3009c730adb026320f8','65429c94506e1d024aba88bbd6a6872f5821952d14a3e58c90408c28030d51b6','محدّث','2026-09-03T20:30:56.705Z','2026-10-07T19:42:59.438Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء برقية تهنئة إلى","رئيس مجلس الوزراء برقية تهنئة","خادم الحرمين الشريفين الملك سلمان"]','["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء برقية تهنئة إلى","رئيس مجلس الوزراء برقية تهنئة","خادم الحرمين الشريفين الملك سلمان"]','classified','','[{"category":"المجتمع","score":0},{"category":"الرياضة","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T19:42:59.438Z',200,60,0,'source_article_available','',NULL,NULL,'body:064072f0bee20c79da488315641f626fce16877fe66a6e2e89a4f2e9280a9210','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6cd15e19-9246-4611-a7ce-1ea77751e94a','news-6cd15e19-9246-4611-a7ce-1ea77751e94a','أنس التركي.. حادث مروري لم يوقف طموحه والتقنية تفتح أمامه طريقًا جديدًا للإنجاز','انس التركي حادث مروري لم يوقف طموحه والتقنيه تفتح امامه طريقا جديدا للانجاز','قد يأخذ الطموح طريقًا آخر للوصول، لكن الإرادة قادرة على تجاوز أصعب التحديات، وهو ما تجسده قصة «أنس التركي»، الذي واصل مسيرته في التعلم والتطوير رغم تعرضه لحادث مروري تسبب في شل حركته.','["ويروي أنس أن الصبر كان رفيق رحلته، مؤكدًا أن الثبات كان أصعب ما يواجهه الإنسان حين لا تعود الحياة إلى صورتها الأولى، إلا أن شغفه بالتعلم والتعليم الذاتي منحه دافعًا للاستمرار وتطوير مهاراته في مجال التقنية والبرمجة.","وكان «ليب 2026» إحدى ثمار هذا الصبر والطموح، حيث انتقل أنس من معسكر «طويق» إلى الاحتفاء به خلال المعرض، ليقدم قصة ملهمة أثبت من خلالها أن التقنية يمكن أن تكون امتدادًا للطموح، وتتجاوز حدود الجسد والظروف.","وأكد أنس أنه يسعى لإثبات قدرته على البرمجة والتطوير والمساهمة في بناء وتنمية الوطن باستخدام التقنيات الحديثة، مشددًا على أن الطريق يظل مفتوحًا أمام الإنسان ما دام متمسكًا بإرادته ولا يسمح للعوائق بأن توقفه.","وتختزل قصة أنس رسالة ملهمة لكل من يواجه ابتلاءً أو تحديًا في حياته، مفادها أن الصعوبات قد تغير الطريق، لكنها لا تستطيع إيقاف الطموح، وأن كل إنجاز يمكن أن يكون بداية للإنجاز الذي يليه."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/7w4zeyr50','https://ajel.sa/local/7w4zeyr50','https://ajel.sa/local/7w4zeyr50','https://ajel.sa/local/7w4zeyr50','فريق التحرير','','2026-09-03T09:50:00.000Z','Wed, 07 Oct 2026 19:43:37 GMT','2026-09-03T20:30:57.051Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Screenshot2026-09-03175301-crop-YW0xJG6E.png','/api/media/6cd15e19-9246-4611-a7ce-1ea77751e94a','/api/media/6cd15e19-9246-4611-a7ce-1ea77751e94a?variant=thumbnail','أنس التركي.. حادث مروري لم يوقف طموحه والتقنية تفتح أمامه طريقًا جديدًا للإنجاز',1200,675,'valid','published','archived','valid',41,'fe1c1014dd8964d2a1ff96aef410a8274927be9a696f376298f216d8db63b0b6','7a7c6f39bbf58d1597d2681a6a2d463713ba4177d554a48ca37ea4b92f91dd91','محدّث','2026-09-03T20:30:57.051Z','2026-10-07T20:24:32.645Z','','',0,0,'international','عادي',37,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","التقنية والتحول الرقمي"]','["التعليم والتدريب","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:43:39.114Z',200,55,0,'source_content_changed','',NULL,NULL,'body:0b9fc0c3a4d52985c1697af6d002fb483f09f08e043d2714861fa375ade84a22','Wed, 07 Oct 2026 19:43:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c7e6ac0d-a6ec-45ce-9380-474d4ac47b72','news-c7e6ac0d-a6ec-45ce-9380-474d4ac47b72','غرامات المشاريع الإنشائية المتسببة بالغبار في الرياض تبلغ 20 مليون ريال','غرامات المشاريع الانشائيه المتسببه بالغبار في الرياض تبلغ 20 مليون ريال','كشف المركز الوطني للرقابة على الالتزام البيئي أن إجمالي الغرامات المفروضة على المشاريع الإنشائية المتسببة في إثارة الغبار بمدينة الرياض بلغ 20 مليون ريال، وذلك في إطار جولات تفتيشية ورقابية مكثفة تهدف إلى التحكم في مصادر الغبار الناجمة عن الأعمال الإنشائية وتحسين جودة الهواء في أحياء العاصمة كافة.','["وأوضح مدير فرع المركز بالرياض فواز آل مجثل، أن الجولات التفتيشية تُنفَّذ بالتعاون مع الهيئة الملكية لمدينة الرياض وأمانة العاصمة، منذ الإعلان عن الإجراءات الخاصة وفق ما نصّ عليه الدليل الإجرائي المُعلن في فبراير الماضي، مبيناً أن الفرق الرقابية تعمل على رصد المخالفات والتحقق من تصحيحها قبل اتخاذ الإجراءات النظامية بحق المشاريع غير الملتزمة.","وأشار إلى أن أعمال الرقابة تُنفَّذ على مدار 24 ساعة طوال أيام الأسبوع، بما يضمن استمرارية المتابعة والرصد والتعامل مع مصادر الغبار في مختلف أوقات اليوم، فضلاً عن توفير بيانات رقابية تُسهم في رفع كفاءة التحليل وتوجيه أعمال التفتيش نحو المواقع الأكثر تأثيراً.","وتضم منظومة رصد جودة الهواء 12 محطة ثابتة موزعة في أرجاء منطقة الرياض، إلى جانب 4 محطات متنقلة، تعمل مجتمعةً على رصد وتحليل 22 عنصراً من عناصر جودة الهواء، مما يتيح متابعة مستويات التلوث ورصد أي تجاوزات للمقاييس المعتمدة واتخاذ الإجراءات اللازمة حيالها.","وقد أُعيد توزيع المحطات وفق المواقع الأكثر قرباً من المشاريع الإنشائية الكبرى، كمشروع بوابة الدرعية ومشروع المربع الجديد."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/2fj55to','https://sabq.org/article/2fj55to','','https://sabq.org/article/2fj55to','صحيفة سبق','الرياض','2026-09-03T08:18:00.000Z','2026-09-03T11:19:00.000Z','2026-09-03T20:30:57.341Z','https://media.sabq.org/news/2026/09/0989a164-d147-4f99-95e2-317955b18aed/w1253.webp','/api/media/c7e6ac0d-a6ec-45ce-9380-474d4ac47b72','/api/media/c7e6ac0d-a6ec-45ce-9380-474d4ac47b72?variant=thumbnail','غرامات المشاريع الإنشائية المتسببة بالغبار في الرياض تبلغ 20 مليون ريال',1253,520,'valid','published','archived','valid',46,'b462967e28e27894f442aba9af73c3189c511a43ba82fa79df1960ae4e97af65','e8c38450ee611aac108d17588874accf08d948961bf3c4d51940eacb675b7327','محدّث','2026-09-03T20:30:57.341Z','2026-10-07T19:42:44.302Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض"]','[]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:44.302Z',200,58,0,'source_article_available','',NULL,NULL,'body:b4ac0bfccfc4c2784f1e58882674e5944d2764f3e71d7bb62f9c02edf14f1a57','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6bfe3f06-7406-4f2d-9d63-da7fe959f5d5','news-6bfe3f06-7406-4f2d-9d63-da7fe959f5d5','المملكة تستعرض إستراتيجية الأمن الغذائي الخليجي في اجتماع البحرين','المملكه تستعرض استراتيجيه الامن الغذائي الخليجي في اجتماع البحرين','جاء ذلك خلال الاجتماع الـ38 للجنة الوزارية للتعاون الزراعي والأمن الغذائي بدول مجلس التعاون، الذي عُقد في مملكة البحرين، ورأس وفد المملكة معالي رئيس الهيئة العامة للأمن الغذائي المهندس أحمد بن عبدالعزيز الفارس.','["استعرضت المملكة العربية السعودية سير العمل في تنفيذ إستراتيجية الأمن الغذائي لدول مجلس التعاون الخليجي، والمبادرات ومؤشرات الأداء المعتمدة، في إطار تعزيز التكامل والتنسيق بين دول المجلس، بما يحقق مستهدفات التنمية المستدامة، ويرسّخ منظومة أمن غذائي مرنة تضمن استمرارية سلاسل إمداد السلع الزراعية والغذائية.","وثمّن الاجتماع الجهود التي تبذلها المملكة في إعداد وتطوير إستراتيجية الأمن الغذائي الخليجي، وإعداد التصور الشامل لبنك الأصول الوراثية النباتية، فضلاً عن جهودها في مجال الإنذار المبكر لرصد وتحليل المؤشرات المرتبطة بسلاسل الإمداد، بما يسهم في تعزيز جاهزية منظومة الأمن الغذائي في مواجهة المتغيرات.","وناقش الاجتماع عدداً من الموضوعات المشتركة بين دول المجلس في مجالات الزراعة والثروة الحيوانية والسمكية والأمن الغذائي، واتخذت اللجنة القرارات المناسبة بشأنها.","كما عُرض تقرير مشروع الخدمات الاستشارية لدراسة وتقييم التقنيات الحديثة والذكاء الاصطناعي في إدارة المزرعة وزيادة الإنتاجية بدول المجلس، بالتعاون مع المركز الدولي للبحوث الزراعية في المناطق الجافة «إيكاردا»، والمجموعة الدولية للبحوث الزراعية «سيجار»، إلى جانب متابعة قرارات الاجتماعين الـ34 والـ37 للجنة التعاون الزراعي والأمن الغذائي.","واعتُمد خلال الاجتماع عدد من الأنظمة والقوانين واللوائح التنفيذية الموحدة، أبرزها: - الموافقة على الإستراتيجية الخليجية للأمن الغذائي والعمل بها بصفة توجيهية. - الاتفاق على إنشاء غرفة عمليات مشتركة لمتابعة تنفيذ الإستراتيجية. - التوجه للاستفادة من بنوك الأصول الوراثية ذات الممكنات المناسبة لتكون بنوكاً مرجعية خليجية. - اعتماد التشريع لقوائم المبيدات المحظورة والمقيدة، ومشروع قانون المبيدات المعدّل، ومشروع اللائحة التنفيذية لقانون الأسمدة ومحسنات التربة الزراعية المعدّلة. - اعتماد النظام الموحد بشأن المدخلات والمنتجات العضوية لدول المجلس، ومشروع اللائحة التنفيذية لقانون الحجر البيطري المعدّلة. - اعتماد الجدول الزمني للشراء الموحد للأدوية واللقاحات البيطرية والتسجيل المركزي للمستحضرات البيطرية. - تمديد دراسة القائمة الموحدة للحد الأدنى من الأطوال المسموح بصيدها لبعض أنواع الأسماك المتداولة.","وتأتي مشاركة المملكة في هذا الاجتماع في إطار تعزيز منظومة الأمن الغذائي الخليجي، ورفع مستوى التكامل والتنسيق بين الدول الأعضاء، بما يسهم في تعزيز القدرة على مواجهة التحديات الإقليمية والدولية المؤثرة في سلاسل الإمداد الغذائي.","وفي ختام الاجتماع، رحّبت المملكة العربية السعودية باستضافة ورئاسة أعمال الاجتماع الـ39 للجنة الوزارية للتعاون الزراعي والأمن الغذائي، مؤكدةً تطلعها إلى مواصلة تعزيز العمل الخليجي المشترك وتبادل الخبرات في المجالات الزراعية والغذائية، كما أعربت عن شكرها لمملكة البحرين على حسن الاستضافة والتنظيم."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/5fjm8wn','https://sabq.org/article/5fjm8wn','','https://sabq.org/article/5fjm8wn','صحيفة سبق','المنطقة الشرقية','2026-09-03T08:00:00.000Z','2026-09-03T11:02:00.000Z','2026-09-03T20:30:57.349Z','https://media.sabq.org/news/2026/09/006e2731-0e53-4c64-9ee8-90f95b1e9118/w1280.webp','/api/media/6bfe3f06-7406-4f2d-9d63-da7fe959f5d5','/api/media/6bfe3f06-7406-4f2d-9d63-da7fe959f5d5?variant=thumbnail','المملكة تستعرض إستراتيجية الأمن الغذائي الخليجي في اجتماع البحرين',1280,853,'valid','published','archived','valid',85,'8d515d1b45db1f0ce5bd1642736017f9b817e8c591eb7db3802dcdae2b7cbaab','a674f68f0f89dde2bef530eca5ca546e33756b08058808126ffcda8692692001','محدّث','2026-09-03T20:30:57.349Z','2026-10-07T20:24:32.653Z','','',0,0,'saudi_region','مهم',72,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس الهيئة العامة للأمن الغذائي","مجلس التعاون الخليجي والمبادرات ومؤشرات"]','["رئيس الهيئة العامة للأمن الغذائي","مجلس التعاون الخليجي والمبادرات ومؤشرات"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:43:00.871Z',200,59,0,'source_article_available','',NULL,NULL,'body:701a411c112c45f9a737e94127982b523f197a8e068d5f5ae66ca3250b3694ac','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2f38a000-4dac-4293-ae5b-9184d9f9d189','news-2f38a000-4dac-4293-ae5b-9184d9f9d189','التعاونية للتأمين وموبايلي توقّعان اتفاقية شراكة استراتيجية لإطلاق حلول تأمينية رقمية مبتكرة','التعاونيه للتامين وموبايلي توقعان اتفاقيه شراكه استراتيجيه لاطلاق حلول تامينيه رقميه مبتكره','وقّعت التعاونية، أكبر شركة تأمين في منطقة الشرق الأوسط وشمال إفريقيا، شراكة استراتيجية مع موبايلي لإطلاق مجموعة من الحلول التأمينية الرقمية، بما يؤسس منظومة متكاملة للحماية والتأمين الرقمي لعملاء موبايلي.','["وقّع الاتفاقية كلٌ من الدكتور عثمان القصبي، الرئيس التنفيذي للتعاونية، والأستاذ نزار بانبيله، الرئيس التنفيذي لموبايلي، على هامش مؤتمر ليب 2026، وهي تستند للانتشار وقاعدة العملاء الواسعة لموبايلي، وخبرات التعاونية التأمينية، وينتظر أن تعزز الاتفاقية القيمة المقدمة لعملاء كلتا الشركتين، وتسهل حصولهم على حلول وتجربة التأمين الرقمية.","وبهذه المناسبة، قال الدكتور عثمان القصبي، الرئيس التنفيذي للتعاونية \"تمثل شراكتنا الاستراتيجية مع موبايلي خطوة مهمة نحو إتاحة الحماية التأمينية بصورة أوسع وجعلها أكثر ارتباطًا برحلات العملاء الرقمية.","ومن خلال الجمع بين خبرة التعاونية التأمينية والانتشار الرقمي لموبايلي، نحن نواصل بناء تجربةٍ متكاملةٍ لعملائنا وتسهل حصولهم على الحماية التأمينية عبر القنوات الرقمية المفضلة لديهم.","كذلك، نسعى من خلال هذا التعاون لمواصلة التركيز على الابتكار وتطوير حلول تلبي احتياجاتهم المتغيرة والمخاطر الناشئة التي قد يتعرضون لها\".","من جهته، أوضح الأستاذ نزار بانبيله، الرئيس التنفيذي لموبايلي، قائلًا: \"تجسد هذه الشراكة مع التعاونية التزامنا المستمر بتعزيز القيمة والتجربة التي نقدمها لعملائنا عبر قنواتنا الرقمية.","فمن خلال دمج مجموعة من الحلول التأمينية ضمن تجربة موبايلي، سنمكّن العملاء من الحصول على الحماية التي يحتاجون لها بسهولةٍ وانسيابيةٍ أكبر.","ونتطلع معًا إلى تطوير عروض مبتكرة تستجيب لأنماط الحياة الرقمية المتغيرة واحتياجات العملاء\".","وستمكّن الشراكة الجديدة العملاء من الوصول بسهولة إلى الحلول التأمينية التي تلائمهم عبر قنوات موبايلي الرقمية، وستبدأ بتوفير تأمين السفر وحماية الأجهزة الرقمية، مع خطط لتوسيع نطاق العروض ليشمل حلولًا مبتكرة في مجالات الأمن السيبراني، وحماية المنازل، والتأمين السيبراني."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/t8dyyak','https://sabq.org/article/t8dyyak','','https://sabq.org/article/t8dyyak','صحيفة سبق','','2026-09-03T08:06:00.000Z','2026-09-03T11:06:00.000Z','2026-09-03T20:30:57.377Z','https://media.sabq.org/news/2026/09/c1d54f29-7a9b-45cb-88cd-fc85cdda186f/w1600.webp','/api/media/2f38a000-4dac-4293-ae5b-9184d9f9d189','/api/media/2f38a000-4dac-4293-ae5b-9184d9f9d189?variant=thumbnail','التعاونية للتأمين وموبايلي توقّعان اتفاقية شراكة استراتيجية لإطلاق حلول تأمينية رقمية مبتكرة',1600,1067,'valid','published','archived','valid',52,'56a320f0086880879e0a2521cd6aa468db0905e99ec728e0efb5faf015ac0e0d','509432c88859fb3d87ce80644248324f673e1c721a2385678954ee0538b50c5f','محدّث','2026-09-03T20:30:57.377Z','2026-10-07T19:43:03.360Z','','',0,0,'saudi_national','عادي',57,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة تأمين في منطقة الشرق","السفر والسياحة","التقنية والتحول الرقمي","الشرق الأوسط"]','["شركة تأمين في منطقة الشرق","السفر والسياحة","التقنية والتحول الرقمي","الشرق الأوسط"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الرياضة","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T19:43:03.360Z',200,58,0,'source_article_available','',NULL,NULL,'body:fa4302f7aeff20caa8fd2a0a857fabf5d304161aefe7a435cca133454e894eca','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fba0511a-8a80-4915-8e79-e5e4187359c6','news-fba0511a-8a80-4915-8e79-e5e4187359c6','الاحتلال يفرج عن 5 محتجزين لبنانيين وسلام يشكر واشنطن','الاحتلال يفرج عن 5 محتجزين لبنانيين وسلام يشكر واشنطن','أفرجت السلطات الإسرائيلية، اليوم الخميس، عن خمسة مدنيين لبنانيين كانت قد احتجزتهم خلال المواجهات الأخيرة مع « حزب الله » في جنوب لبنان ، وذلك في خطوة جاءت عقب استجوابهم وإثبات عدم تورطهم في الأعمال القتالية.','["وقال مكتب رئيس الوزراء الإسرائيلي بنيامين نتنياهو ، في بيان رسمي، إنه تقرر الإطلاق الفوري لسراح المحتجزين الخمسة بعدما تبين خلال التحقيقات أنهم مدنيون ولا يتبعون لأي منظمة مسلحة، مؤكداً عدم وجود أي مبرر قانوني أو أمني لمواصلة احتجازهم.","وأوضح بيان مكتب نتنياهو أن قرار الإفراج يرتبط بمساعٍ وجهود جرت بين الجانبين الإسرائيلي واللبناني للعثور على رفات قادة من الطائفة اليهودية في لبنان وإعادتها، بعد أن تعرضوا للاختطاف والقتل إبان الحرب الأهلية اللبنانية في ثمانينيات القرن الماضي.","وفي بيروت ، أكد مصدر عسكري لبناني تسلّم البلاد مواطناً لبنانياً أفرجت عنه القوات الإسرائيلية عبر اللجنة الدولية للصليب الأحمر بعد احتجازه ونقله داخل إسرائيل.","وتأتي هذه التطورات تلبية لمطالب تقدم بها لبنان خلال جولة مفاوضات في أغسطس الماضي للإفراج عن دفعة أولى من اللبنانيين المحتجزين منذ اندلاع حرب عام 2024.","من جانبه، اعتبر رئيس الحكومة اللبنانية نواف سلام أن عودة أي لبناني محرر إلى وطنه سالماً تعد خطوة مهمة في مسار معالجة الملف، موجهاً الشكر للإدارة الأمريكية والسفير ميشال عيسى على الجهود الميدانية والدبلوماسية المبذولة.","وقال سلام في بيان رسمي: \"سنواصل العمل حتى الإفراج عن جميع أسرانا، والكشف عن مصير المفقودين، وتحقيق الانسحاب الإسرائيلي الكامل من الأراضي اللبنانية\".","وأضاف رئيس الحكومة اللبنانية: \"مهما بدا المسار التفاوضي صعباً، سنستمر بحشد كل الجهود المطلوبة لحفظ حقوق لبنان ومصالح اللبنانيين، ولا سيما أهلنا في الجنوب، وتأمين عودتهم الآمنة والكريمة إلى أرضهم وقراهم، وإعادة سيادة الدولة الكاملة على أراضيها\"."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/8r6wiijv7','https://ajel.sa/international/8r6wiijv7','https://ajel.sa/international/8r6wiijv7','https://ajel.sa/international/8r6wiijv7','فريق التحرير','','2026-09-03T10:05:00.000Z','Wed, 07 Oct 2026 19:42:40 GMT','2026-09-03T20:30:57.399Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D9%86%D9%88%D8%A7%D9%81-%D8%B3%D9%84%D8%A7%D9%85-2-0tXpg4Vn.jpg','/api/media/fba0511a-8a80-4915-8e79-e5e4187359c6','/api/media/fba0511a-8a80-4915-8e79-e5e4187359c6?variant=thumbnail','نواف سلام',1200,675,'valid','published','archived','valid',41,'b9206d13723c7a7f92b45500f7967b61d485b59a6c9ca50ca0eef3b4361e4847','d32b209fddb29dc150f2749505c1126767fa86c4d2b5cd715f9b8a43bb740ab0','محدّث','2026-09-03T20:30:57.399Z','2026-10-07T20:24:32.661Z','','',0,0,'gulf_arab','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس الوزراء الإسرائيلي بنيامين نتنياهو","السياسة والعلاقات الدولية","لبنان"]','["رئيس الوزراء الإسرائيلي بنيامين نتنياهو","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:42.779Z',200,53,0,'source_content_changed','',NULL,NULL,'body:7b6a36c27710ef8327b2ded557973399fe575320d6ef50a337ecf9a694288f14','Wed, 07 Oct 2026 19:42:40 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4369e378-d788-4299-a285-d3b18b8a5672','news-4369e378-d788-4299-a285-d3b18b8a5672','الاتحاد السعودي يُطلق موسم البراعم والواعدين في 14 أكتوبر بـ34 ألف مباراة','الاتحاد السعودي يطلق موسم البراعم والواعدين في 14 اكتوبر بـ34 الف مباراه','وأعلن الاتحاد أن أعداد الفرق واللاعبين المسجلين تجاوزت المستهدفات الأولية للمشروع، إذ تخطّى عدد الفرق المسجلة 3,200 فريق، فيما يتجاوز عدد اللاعبين 40 ألف لاعب موزعين على أكثر من 50 مدينة ومحافظة في مختلف أنحاء المملكة.','["يواصل الاتحاد السعودي لكرة القدم استعداداته لانطلاق موسم مسابقات البراعم والواعدين للموسم الرياضي الحالي، عقب إغلاق فترة التسجيل في 27 أغسطس الماضي، في إطار مساعي الاتحاد لتوسيع قاعدة ممارسة كرة القدم واكتشاف المواهب منذ المراحل العمرية المبكرة.","وتنطلق المسابقة رسمياً في 14 أكتوبر، وتشمل إقامة نحو 34 ألف مباراة ضمن فئات تحت 5 و7 و9 و11 و12 و13 و14 عاماً، مع إقامة منافسات الفئات المستحدثة تحت 5 و7 و9 أعوام للمرة الأولى في تاريخ المسابقة.","وبعد اكتمال مرحلة التسجيل، ينتقل المشروع إلى مرحلة الإعداد للمنافسات، التي تركز على استكمال جاهزية الفرق والمشاركين وتهيئة الجوانب التنظيمية والفنية كافة، وتشمل هذه المرحلة مراجعة الفرق المسجلة واعتمادها، واستكمال توزيعها على المدن والمحافظات، وإعداد جداول المباريات، فضلاً عن إقامة ورش عمل تعريفية للفرق والأجهزة الإدارية والفنية المشاركة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/v737w2e','https://sabq.org/article/v737w2e','','https://sabq.org/article/v737w2e','صحيفة سبق','الرياض','2026-09-03T07:40:00.000Z','2026-09-03T10:42:00.000Z','2026-09-03T20:30:57.796Z','https://media.sabq.org/news/2026/09/b5d1cd3c-749f-47b8-b35f-f0c6bce288ac/w512.webp','/api/media/4369e378-d788-4299-a285-d3b18b8a5672','/api/media/4369e378-d788-4299-a285-d3b18b8a5672?variant=thumbnail','الاتحاد السعودي يُطلق موسم البراعم والواعدين في 14 أكتوبر بـ34 ألف مباراة',512,640,'valid','published','archived','valid',97,'76796fc84b8ab2cf7c51a333f254ade593a7a1ff54d3beda3954fae087576fb6','365773bb21a81e3600a8d2bfadb06ba4f66d2e49205707734f595716c493b9fb','محدّث','2026-09-03T20:30:57.796Z','2026-10-07T19:43:05.051Z','','',0,0,'saudi_region','عادي',61,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','classified','','[{"category":"المناطق","score":5.5},{"category":"أخبار السعودية","score":1.5},{"category":"التقنية","score":0}]','Active','2026-10-07T19:43:05.051Z',200,58,0,'source_article_available','',NULL,NULL,'body:ffd80607cee96e64be67a52eab321f1bee445a698196fe703db55613d5f2666f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9aa34aee-c299-4de9-a07a-e3441eaa0b41','news-9aa34aee-c299-4de9-a07a-e3441eaa0b41','مؤشر سوق الأسهم السعودية يغلق مرتفعًا عند 11,032 نقطة بتداولات 3.8 مليارات ريال','مؤشر سوق الاسهم السعوديه يغلق مرتفعا عند 11 032 نقطه بتداولات 3 8 مليارات ريال','أغلق مؤشر الأسهم السعودية الرئيس اليوم الأربعاء عند مستوى 11,032.91 نقطة، بعد ارتفاعه بمقدار 20.73 نقطة، وسط تداولات بلغت قيمتها الإجمالية 3.8 مليارات ريال.','["ووفق النشرة الاقتصادية اليومية ل وكالة الأنباء السعودية ، بلغ عدد الأسهم المتداولة 204 ملايين سهم. سجلت أسهم 141 شركة ارتفاعًا في قيمتها، فيما تراجعت أسهم 111 شركة أخرى.","كانت أسهم شركات المصافي ، وولاء، و ساسكو ، وجازادكو، ومدينة المعرفة، الأكثر ارتفاعًا في السوق. في المقابل، تراجعت أسهم شركات طيبة، وام آي اس، و الخدمات الأرضية ، وعطاء، وأيان، بنسب تراوحت بين 4.85٪ ارتفاعًا و2.49٪ انخفاضًا.","أما من حيث النشاط، تصدرت أسهم الكثيري ، وبان، و كيان السعودية ، و بترو رابغ ، و أمريكانا قائمة الأسهم الأكثر نشاطًا من حيث الكمية، فيما جاءت أسهم الراجحي، وبترو رابغ، و أرامكو السعودية ، والإنماء، وstc ضمن الأكثر نشاطًا في القيمة.","وفي السياق ذاته، أغلق مؤشر الأسهم السعودية الموازية (نمو) مرتفعًا بمقدار 88.42 نقطة، ليصل إلى مستوى 21,786.38 نقطة، وسط تداولات بلغت قيمتها 13 مليون ريال، وكمية أسهم متداولة تجاوزت مليوني سهم."]','الاقتصاد','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/davwxjmul','https://ajel.sa/economy/davwxjmul','https://ajel.sa/economy/davwxjmul','https://ajel.sa/economy/davwxjmul','فريق التحرير','مكة المكرمة','2026-09-03T09:11:00.000Z','Wed, 07 Oct 2026 19:42:50 GMT','2026-09-03T20:30:57.807Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%85%D8%A4%D8%B4%D8%B1-%D8%B3%D9%88%D9%82-%D8%A7%D9%84%D8%A3%D8%B3%D9%87%D9%85-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-XzwBJTLw.webp','/api/media/9aa34aee-c299-4de9-a07a-e3441eaa0b41','/api/media/9aa34aee-c299-4de9-a07a-e3441eaa0b41?variant=thumbnail','مؤشر سوق الأسهم السعودية يغلق مرتفعًا عند 11,032 نقطة بتداولات 3.8 مليارات ريال',1200,675,'valid','published','archived','valid',45,'b8ced38adbf09946a2eca34d591bb0e596a1becbe61e12d57eb10c46c6d4de7a','4cc0b3c0a46d9b6278a4b3dfff22d4785ea90b04d2702008e759692f74a37018','محدّث','2026-09-03T20:30:57.807Z','2026-10-07T20:24:32.667Z','','',0,0,'saudi_region','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","شركة ارتفاع ا في قيمتها","الاقتصاد والأسواق"]','["شركة ارتفاع ا في قيمتها","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الطاقة والصناعة","score":2},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:42:52.474Z',200,54,0,'source_content_changed','',NULL,NULL,'body:4509dc8e2dbed9135d9d4f710297939b63fa8182de4efc733ad7b121ff711ef9','Wed, 07 Oct 2026 19:42:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1e93c402-637d-447a-9d1d-314c1a0b0957','news-1e93c402-637d-447a-9d1d-314c1a0b0957','سامي للإلكترونيات المتقدمة تنضم إلى منظومة «تقنية سعودية»','سامي للالكترونيات المتقدمه تنضم الي منظومه تقنيه سعوديه','حصلت شركة سامي للإلكترونيات المتقدمة، إحدى شركات الشركة السعودية للصناعات العسكرية (SAMI)، على عضوية منصة «تقنية سعودية»، بوصفها خطوة تعكس التزام الشركة بدعم الابتكار وتعزيز التعاون مع الجهات الرائدة في القطاع التقني الوطني.','["وتمثّل هذه العضوية منصةً لتعزيز التكامل بين الشركات الوطنية والجهات الفاعلة في القطاع، إذ تُتيح تبادل المعرفة وتطوير القدرات الوطنية، بما يُسهم في بناء منظومة تقنية أكثر تنافسية واستدامة، وتعزيز مكانة المملكة مركزاً إقليمياً وعالمياً للتقنية والابتكار.","وأعرب الرئيس التنفيذي للشركة المهندس زياد المسلّم عن اعتزازه بهذه العضوية، مؤكداً أنها «تمثّل امتداداً لمسيرة الشركة في دعم قطاع التقنية الوطني وتعزيز مكانتها شريكاً موثوقاً في تطوير الحلول الإلكترونية والتقنيات المتقدمة».","وقال المسلّم: «تعكس عضويتنا في تقنية سعودية التزامنا المستمر بدعم الابتكار وتعزيز التعاون مع مختلف الجهات في منظومة التقنية الوطنية، ونؤمن بأن الشراكات الفاعلة تشكّل ركيزة أساسية لبناء اقتصاد رقمي مزدهر وتعزيز تنافسية المملكة عالمياً، بما يتماشى مع مستهدفات رؤية 2030».","وتواصل سامي للإلكترونيات المتقدمة استثمارها في تطوير الحلول الإلكترونية والتقنيات المتقدمة، وتعزيز البحث والتطوير، وتمكين الكفاءات الوطنية، دعماً للقطاعات الحيوية ومواكبةً لتطلعات المملكة نحو اقتصاد قائم على المعرفة والابتكار."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/w7sizf7','https://sabq.org/article/w7sizf7','','https://sabq.org/article/w7sizf7','صحيفة سبق','','2026-09-03T07:48:00.000Z','2026-09-03T10:48:00.000Z','2026-09-03T20:30:57.830Z','https://media.sabq.org/news/2026/09/064b39a6-7a0e-471c-992a-6a5ed077e74b/w1600.webp','/api/media/1e93c402-637d-447a-9d1d-314c1a0b0957','/api/media/1e93c402-637d-447a-9d1d-314c1a0b0957?variant=thumbnail','سامي للإلكترونيات المتقدمة تنضم إلى منظومة «تقنية سعودية»',1600,1066,'valid','published','archived','valid',85,'6bc7aae09a1a2ea7e002db407ab24bed167fffe84429ba7ee2f0e971dc57db3f','389963db7b07b803274714c75619455e3518b92f3501c4eb53e4ecfe21bf52b2','محدّث','2026-09-03T20:30:57.830Z','2026-10-07T19:42:59.402Z','','',0,0,'saudi_national','مهم',70,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة سامي للإلكترونيات المتقدمة إحدى","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["شركة سامي للإلكترونيات المتقدمة إحدى","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"التقنية","score":4.5},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:42:59.402Z',200,61,0,'source_article_available','',NULL,NULL,'body:e9d85150ba8a57b2190a649abfc2daaac7b83fc0ca9b43dcdb241494eb9fa448','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('11cd03ad-f7f7-4c6b-a117-ce0f5dd0b8f7','news-11cd03ad-f7f7-4c6b-a117-ce0f5dd0b8f7','وزير الخارجية يبحث مع نائب رئيس سيشل تعزيز التعاون الثنائي بالرياض','وزير الخارجيه يبحث مع نائب رئيس سيشل تعزيز التعاون الثنائي بالرياض','استقبل صاحب السمو الأمير فيصل بن فرحان بن عبدالله وزير الخارجية، اليوم الأربعاء بمقر الوزارة في الرياض ، نائب رئيس جمهورية سيشل السيد سيباستيان بيلاي.','["وبحث الجانبان خلال اللقاء العلاقات الثنائية بين المملكة العربية السعودية وجمهورية سيشل، واستعرضا فرص تعزيزها وتطويرها في مختلف المجالات بما يخدم المصالح المشتركة للبلدين.","كما تطرق الاجتماع إلى سبل توسيع التعاون في المجالات الاقتصادية والسياحية، إضافة إلى مناقشة مستجدات الأوضاع الإقليمية والدولية.","وفي السياق ذاته، ناقش الطرفان عددًا من القضايا والموضوعات ذات الاهتمام المشترك."]','أخبار السعودية','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/1ckjex4ol','https://ajel.sa/local/1ckjex4ol','https://ajel.sa/local/1ckjex4ol','https://ajel.sa/local/1ckjex4ol','فريق التحرير','الرياض','2026-09-03T09:10:00.000Z','Wed, 07 Oct 2026 19:43:37 GMT','2026-09-03T20:30:57.838Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-09/source-_aOhGwVn.jpg','/api/media/11cd03ad-f7f7-4c6b-a117-ce0f5dd0b8f7','/api/media/11cd03ad-f7f7-4c6b-a117-ce0f5dd0b8f7?variant=thumbnail','وزير الخارجية يبحث مع نائب رئيس سيشل تعزيز التعاون الثنائي بالرياض',1200,675,'valid','published','archived','valid',46,'6fbb7ecd146dc2240af86d105d4129be7cbf90f360dc26dfe33689d8be7bd4e3','b8f5253d9a787673182587285c22ba0c9091558e27e72bd9e15e2b0924ea34b2','محدّث','2026-09-03T20:30:57.838Z','2026-10-07T19:43:39.013Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","وزير الخارجية يبحث مع نائب","رئيس سيشل تعزيز التعاون الثنائي","الاقتصاد والأسواق","الرياض"]','["وزير الخارجية يبحث مع نائب","رئيس سيشل تعزيز التعاون الثنائي","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:43:39.013Z',200,58,0,'source_content_changed','',NULL,NULL,'body:9f204606fe3de33640ed3be0cc697bda7d29e5e48d0ca468b8308da9bb7f4cfd','Wed, 07 Oct 2026 19:43:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('aa7064c9-15fa-4172-8ff9-3e0cc38a9a74','news-aa7064c9-15fa-4172-8ff9-3e0cc38a9a74','جمعية إرادة التوحد بنجران تُسلّم 100 حقيبة حسية لمستفيديها بدعم منصة إحسان','جمعيه اراده التوحد بنجران تسلم 100 حقيبه حسيه لمستفيديها بدعم منصه احسان','وثمّن المدير التنفيذي لجمعية إرادة التوحد الأستاذ منصور سمران الدعم المقدم من منصة إحسان للعمل الخيري، مؤكداً أن توفير 100 حقيبة وما يزيد على 3,500 أداة ووسيلة حسية إجمالاً يعكس حجم الأثر الذي يمكن أن تحققه مثل هذه المشروعات عند توجيه الدعم نحو احتياجات المستفيدين بصورة مباشرة.','["أنهت جمعية إرادة التوحد في نجران تسليم 100 حقيبة حسية لمستفيديها، ضمن مشروع نُفذ بدعم من منصة إحسان للعمل الخيري، إذ تضم كل حقيبة أكثر من 35 أداة ووسيلة حسية متنوعة، وُفّرت بهدف دعم تنمية المهارات الحسية لدى الأطفال وتعزيز استمرارية التدريب والممارسة في المنزل.","ويأتي المشروع انطلاقاً من أهمية التكامل بين الجمعية والأسرة في رحلة تنمية مهارات الطفل، إذ تتيح محتويات الحقيبة للأسرة مجموعة متنوعة من الأدوات التي تساعدها على مواصلة الأنشطة والتدريبات، وتعزيز ما يكتسبه الطفل خلال البرامج والجلسات المقدمة في الجمعية، بما يسهم في نقل أثر التدريب إلى بيئته اليومية.","وأوضح سمران أن «مثل هذه المشاريع تعزز التكامل بين الأسرة والجمعية في تنمية مهارات الطفل، فالأثر لا يتوقف عند الجلسة المقدمة داخل الجمعية، وإنما يمتد إلى المنزل من خلال تمكين الأسرة وتوفير الأدوات المناسبة التي تساعدها على مواصلة التدريب وتنمية المهارات الحسية بصورة مستمرة».","من جهتها، أكدت رئيسة الجمعية الأستاذة غالية السويدي أن الجمعية تسعى إلى تنفيذ مشروعات لا تقتصر على تقديم الخدمة للمستفيد فحسب، وإنما تُمكّن الأسرة من أن تكون شريكاً في استمرار أثرها، مقدمةً شكرها وتقديرها لمنصة إحسان للعمل الخيري على دعمها وإسهامها في تمكين الجمعية من تنفيذ المشروع والوصول به إلى المستفيدين وأسرهم."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ynrsotc','https://sabq.org/article/ynrsotc','','https://sabq.org/article/ynrsotc','بندر آل عوض','نجران','2026-09-03T07:59:00.000Z','2026-09-03T10:59:00.000Z','2026-09-03T20:30:57.977Z','https://media.sabq.org/news/2026/09/1a268465-68ed-4f71-ae4e-17065fad47b3/w1200.webp','/api/media/aa7064c9-15fa-4172-8ff9-3e0cc38a9a74','/api/media/aa7064c9-15fa-4172-8ff9-3e0cc38a9a74?variant=thumbnail','جمعية إرادة التوحد بنجران تُسلّم 100 حقيبة حسية لمستفيديها بدعم منصة إحسان',1200,1600,'valid','published','archived','valid',56,'e1e724d9c2ddc231c532e7070314024142bf21fd253790ce0fd812840a696bd1','36ce8f78255359f5748e38929d3e21b0139a550014673cfc8f23bc1cc7a4628f','محدّث','2026-09-03T20:30:57.977Z','2026-10-07T19:43:02.715Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","نجران"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"المناطق","score":3},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:43:02.715Z',200,57,0,'source_article_available','',NULL,NULL,'body:593269e87ca77af7bac952b6ac9614c8900761da85156e6faf0830bda9374369','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0bebd7bc-e8c7-4519-a38e-fd92e1070f77','news-0bebd7bc-e8c7-4519-a38e-fd92e1070f77','"كومفولت" تؤكد أهمية المرونة السيبرانية لمواكبة توسع السعودية في استخدام التقنيات السحابية والذكاء الاصطناعي','كومفولت تؤكد اهميه المرونه السيبرانيه لمواكبه توسع السعوديه في استخدام التقنيات السحابيه والذكاء الاصطناعي','وخلال الفعاليات، التقى مسؤولو كومفولت بمجموعة من العملاء والشركاء وممثلي القطاع في أجنحة مايكروسوفت و"Logicom" و"Axelerated"، حيث دارت نقاشاتهم حول تزايد حاجة المؤسسات إلى قدرات أكثر تطورًا في مجال المرونة السيبرانية، خاصة في ظل التوسع الكبير في استخدام تقنيات الذكاء الاصطناعي والحوسبة السحابية، والنمو المتواصل للخدمات الرقمية الحيوية التي تعتمد عليها…','["جددت شركة كومفولت، المتخصصة في حلول حماية البيانات والمرونة السيبرانية للمؤسسات، التزامها بمساعدة المؤسسات السعودية على جعل المرونة السيبرانية جزءًا أساسيًا من التوسع الذي تشهده المملكة في استخدام التقنيات السحابية والذكاء الاصطناعي، وذلك في ختام مشاركتها في مؤتمر \"ليب 2026\" بالرياض.","وامتدت هذه اللقاءات إلى توطيد علاقات كومفولت مع شركائها الرئيسيين وعملائها الحاليين والمحتملين في المنطقة، وفتح آفاق جديدة للتعاون، على أن تكشف الشركة عن مزيد من المستجدات خلال الأشهر المقبلة.","وعكس حضور كومفولت في جناح مايكروسوفت جانبًا من التعاون المتنامي بين الشركتين، والذي يستند إلى شراكة استراتيجية متعددة السنوات أُعلن عنها في يونيو 2026، يتم بموجبها إتاحة تقنيات كومفولت للذكاء الاصطناعي والمرونة السيبرانية مباشرة عبر منصة \"مايكروسوفت أزور\".","ويتيح هذا التعاون للمؤسسات حماية بياناتها وتطبيقاتها وهوياتها ونسخها احتياطيًا واستعادتها مباشرة داخل بيئات \"أزور\" التي تستخدمها لتشغيل أعمالها الأساسية، في حال التعرض لهجمات سيبرانية أو انقطاع الخدمات أو الأخطاء البشرية.","وتكتسب هذه الخطوة أهمية أكبر مع انتقال المزيد من التطبيقات والعمليات الحيوية المرتبطة باستخدام التقنيات السحابية والذكاء الاصطناعي إلى البنية التحتية المحلية في المملكة، حيث تعمل كومفولت على دعم عملائها في مواكبة هذا التوجه.","وتأتي هذه الشراكة في وقت تواصل فيه المملكة تسريع خططها للتوسع في التقنيات السحابية والذكاء الاصطناعي، في إطار مستهدفات رؤية السعودية 2030.","ويظهر ذلك بوضوح في وصول قدرة مراكز البيانات في المملكة إلى 467 ميجاواط مطلع عام 2026، إلى جانب استعداد مايكروسوفت لإتاحة منطقة مراكز البيانات السحابية الجديدة \"Saudi Arabia East\" في شرق السعودية للعملاء خلال الربع الرابع من العام.","ومع تزايد الاعتماد على الخدمات السحابية المحلية، تحتاج المؤسسات إلى بناء بيئاتها السحابية منذ البداية على أسس تضمن لها المرونة السيبرانية."]','الذكاء الاصطناعي','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/rrr9zuj','https://sabq.org/article/rrr9zuj','','https://sabq.org/article/rrr9zuj','صحيفة سبق','الرياض','2026-09-03T07:32:00.000Z','2026-09-03T10:32:00.000Z','2026-09-03T20:30:58.401Z','https://media.sabq.org/news/2026/09/23d1f267-744a-4692-b21f-c91e5450028e/w1600.webp','/api/media/0bebd7bc-e8c7-4519-a38e-fd92e1070f77','/api/media/0bebd7bc-e8c7-4519-a38e-fd92e1070f77?variant=thumbnail','"كومفولت" تؤكد أهمية المرونة السيبرانية لمواكبة توسع السعودية في استخدام التقنيات السحابية والذكاء الاصطناعي',1600,900,'valid','published','archived','valid',88,'92be1fda53b72b06addb9ca375d02e2bfb42827c05a8185d0d86b930d239143a','e1b01daa04857513b0bc5df6172ffebcd284ab0ac96ee78e1d4787a5b5611201','محدّث','2026-09-03T20:30:58.401Z','2026-10-07T20:24:32.681Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة كومفولت المتخصصة في حلول","الثقافة والفنون","التقنية والتحول الرقمي","الرياض"]','["شركة كومفولت المتخصصة في حلول","الثقافة والفنون","التقنية والتحول الرقمي"]','classified','','[{"category":"أخبار السعودية","score":4.5},{"category":"المناطق","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:03.394Z',200,56,0,'source_article_available','',NULL,NULL,'body:c6959e0130caf502d197706149bab25d12fe0cbae7c8dcecd9c11723f2660c95','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7c3b03b0-c4b9-40ce-847e-9a661fee16b3','news-7c3b03b0-c4b9-40ce-847e-9a661fee16b3','تجمع مكة المكرمة الصحي يوقّع مذكرة تفاهم مع برنامج مدينة الجموم الصحية','تجمع مكه المكرمه الصحي يوقع مذكره تفاهم مع برنامج مدينه الجموم الصحيه','ومثّل برنامجَ مدينة الجموم الصحية في توقيع المذكرة محافظُ الجموم ورئيس اللجنة الرئيسية للبرنامج الأستاذ محمد بن ماض السبيعي، فيما مثّل تجمعَ مكة المكرمة الصحي الرئيسُ التنفيذي الدكتور حاتم بن أحمد العمري.','["وقّع تجمع مكة المكرمة الصحي مذكرة تفاهم مع برنامج مدينة الجموم الصحية، بهدف تعزيز التعاون المشترك في مجالات التوعية الصحية وتعزيز الصحة العامة ودعم المبادرات المجتمعية، بما يسهم في تحسين جودة الحياة وتحقيق مستهدفات رؤية السعودية 2030.","وتأتي هذه المذكرة في إطار تعزيز دور المؤسسات الصحية الحكومية في التنمية الصحية، والاستفادة من الإمكانات والقدرات المتاحة لدى الطرفين بما يحقق التكامل ويسهم في تقديم المبادرات والخدمات الصحية للمجتمع وفق احتياجاته.","وتتضمن مجالات التعاون إقامةَ الأنشطة والفعاليات والمبادرات التطوعية التي تخدم برامج التوعية الصحية، إلى جانب رعاية المشاريع والبرامج التي تسهم في التنمية الصحية بمحافظة الجموم، وتعزيز المشاركة المجتمعية ونشر الوعي والسلوكيات الصحية السليمة.","كما تسهم المذكرة في تطوير الشراكات بين القطاعات ذات العلاقة وتعظيم الأثر الصحي والمجتمعي للمبادرات، بما يدعم جهود تعزيز الصحة والوقاية ويحقق أثراً مستداماً يعود بالنفع على أفراد المجتمع.","يُشار إلى أن محافظة الجموم تُعدّ أول مدينة صحية معتمدة على مستوى منطقة مكة المكرمة، وثالث مدينة على مستوى المملكة تحصل على اعتماد منظمة الصحة العالمية."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/uv9cue6','https://sabq.org/article/uv9cue6','','https://sabq.org/article/uv9cue6','صحيفة سبق','مكة المكرمة','2026-09-03T07:29:00.000Z','2026-09-03T10:30:00.000Z','2026-09-03T20:30:58.407Z','https://media.sabq.org/news/2026/09/1008ec7b-74b6-47e7-aa9e-459b308105ca/w1600.webp','/api/media/7c3b03b0-c4b9-40ce-847e-9a661fee16b3','/api/media/7c3b03b0-c4b9-40ce-847e-9a661fee16b3?variant=thumbnail','تجمع مكة المكرمة الصحي يوقّع مذكرة تفاهم مع برنامج مدينة الجموم الصحية',1600,1067,'valid','published','archived','valid',56,'327bbb270581a061a0d31c7f30e2a34ac0b83d7f190b83215cc0ab59e08c4fa7','b4db86740f3b7f61feea3f4119d16b37cd7d5f1e91075ce1c91b1b296212334c','محدّث','2026-09-03T20:30:58.407Z','2026-10-07T20:24:32.702Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","مكة"]','["الصحة العامة"]','needs_review','ambiguous_category','[{"category":"المجتمع","score":7},{"category":"أخبار السعودية","score":3},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:59.420Z',200,63,0,'source_article_available','',NULL,NULL,'body:f2be3dad9e3a932453ef2db59af6f3b28bf573984ae442f0a0601772c3eae307','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7fd7b5b4-029f-4e39-bc58-3b34d8551a44','news-7fd7b5b4-029f-4e39-bc58-3b34d8551a44','مؤشر الأسهم السعودية يرتفع 20.73 نقطة ليتجاوز مستوى 11032 نقطة','مؤشر الاسهم السعوديه يرتفع 20 73 نقطه ليتجاوز مستوي 11032 نقطه','أغلق مؤشر الأسهم السعودية الرئيس جلسة اليوم مرتفعاً بمقدار 20.73 نقطة، ليصل إلى مستوى 11032.91 نقطة، وسط تداولات بلغت قيمتها الإجمالية 3.8 مليارات ريال.','["وبلغت كمية الأسهم المتداولة 204 ملايين سهم، وفق النشرة الاقتصادية اليومية لوكالة الأنباء السعودية لسوق الأسهم السعودية، سجّلت خلالها أسهم 141 شركة ارتفاعاً في قيمتها، فيما تراجعت أسهم 111 شركة، وتراوحت نسب الارتفاع والانخفاض بين 4.85% و2.49%.","وجاءت أسهم شركات «المصافي» و«لاء» و«ساسكو» و«جازادكو» و«مدينة المعرفة» الأكثر ارتفاعاً في التعاملات، في حين تصدّرت أسهم شركات «طيبة» و«MIS» و«الخدمات الأرضية» و«عطاء» و«أيان» قائمة الأكثر انخفاضاً.","وعلى صعيد النشاط، كانت أسهم شركات «الكثيري» و«بان» و«كيان السعودية» و«بترو رابغ» و«أمريكانا» الأكثر نشاطاً بالكمية، بينما تصدّرت أسهم «الراجحي» و«بترو رابغ» و«أرامكو السعودية» و«الإنماء» و«STC» قائمة الأكثر نشاطاً في القيمة.","في المقابل، أغلق مؤشر الأسهم السعودية الموازية «نمو» مرتفعاً بمقدار 88.42 نقطة، ليصل إلى مستوى 21786.38 نقطة، بتداولات بلغت قيمتها 13 مليون ريال، وكمية أسهم تجاوزت مليوني سهم."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/b4hdc94','https://sabq.org/article/b4hdc94','','https://sabq.org/article/b4hdc94','صحيفة سبق','مكة المكرمة','2026-09-03T07:30:00.000Z','2026-09-03T10:31:00.000Z','2026-09-03T20:30:58.832Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/8dd05396-f284-4f1f-5948-78c3f71c5a00/public','/api/media/7fd7b5b4-029f-4e39-bc58-3b34d8551a44','/api/media/7fd7b5b4-029f-4e39-bc58-3b34d8551a44?variant=thumbnail','مؤشر الأسهم السعودية يرتفع 20.73 نقطة ليتجاوز مستوى 11032 نقطة',2400,1339,'valid','published','archived','valid',45,'a3602eb4c4b5c53df5113d6fb9c004357967498402a549d0b809a6fa4cbaf157','cf1cd70d95fe8b84e468af1e0df8d82c7ae59b9be06ff151e38da723d876d164','محدّث','2026-09-03T20:30:58.832Z','2026-10-07T20:24:32.706Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة ارتفاعا في قيمتها فيما","الاقتصاد والأسواق"]','["شركة ارتفاعا في قيمتها فيما","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"التقنية","score":2},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:43:03.331Z',200,55,0,'source_article_available','',NULL,NULL,'body:4a72b175a9c9fc2a8119bd947ffaaa93420730618472b0fe447a8a34a869b634','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4ac9dc1d-63c5-4d1d-81fb-fe4df4944808','news-4ac9dc1d-63c5-4d1d-81fb-fe4df4944808','فواز الشريف: لو كنت مدرب الأهلي أمام الهلال لقيدت الأظهرة وأغلقت المحاور أمام هجوم الزعيم','فواز الشريف لو كنت مدرب الاهلي امام الهلال لقيدت الاظهره واغلقت المحاور امام هجوم الزعيم','أكد الناقد الرياضي فواز الشريف أن الأهلي كان بحاجة إلى التعامل بشكل مختلف مع القوة الهجومية للهلال، مشيرًا إلى أنه لو كان مدرب الفريق لعمل على الحد من خطورة منافسه من خلال إغلاق المساحات أمام لاعبي الوسط والأطراف.','["وقال الشريف، خلال مداخلة مع «العربية FM»: «لو كنت مدرب الأهلي كنت قيّدت الأظهرة وأغلقت المحاور أمام القوة الهجومية للهلال»، موضحًا أن التعامل مع مفاتيح لعب «الزعيم» كان يجب أن يحظى بأولوية كبيرة.","وانتقد الناقد الرياضي بعض الاختيارات داخل الأهلي، قائلًا إن بعض الأسماء الموجودة في الفريق «كأنها تربطها بالمدرب علاقة صداقة»، مؤكدًا أن من حق النادي على جميع لاعبيه أن يبذلوا أقصى مجهود لديهم داخل الملعب.","وكان الهلال حقق فوزاً كبيراً على ضيفه الأهلي بثلاثة أهداف دون رد، الثلاثاء، ضمن منافسات دوري روشن السعودي لكرة القدم، في مباراة شهدت تسجيل المهاجم الإنجليزي أولي واتكينز هدفاً خلال ظهوره الأول مع الفريق."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/u9m1t5i6n','https://ajel.sa/sports/u9m1t5i6n','https://ajel.sa/sports/u9m1t5i6n','https://ajel.sa/sports/u9m1t5i6n','فريق التحرير','الرياض','2026-09-03T09:09:00.000Z','Wed, 07 Oct 2026 19:43:38 GMT','2026-09-03T20:30:59.007Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Screenshot2026-09-03161305-crop-gjBQ7ESv.png','/api/media/4ac9dc1d-63c5-4d1d-81fb-fe4df4944808','/api/media/4ac9dc1d-63c5-4d1d-81fb-fe4df4944808?variant=thumbnail','فواز الشريف: لو كنت مدرب الأهلي أمام الهلال لقيدت الأظهرة وأغلقت المحاور أمام هجوم الزعيم',1200,675,'valid','published','archived','valid',41,'6f005266764e92992d7204d762124f10a478e05ef08c44c65178f3c27fb805f0','93c427f7effd27e5aa826f82978d4ac2949045779d4340a19c7c4052fcf7d719','محدّث','2026-09-03T20:30:59.007Z','2026-10-07T20:24:32.709Z','','',0,0,'saudi_region','عادي',57,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:43:40.496Z',200,59,0,'source_content_changed','',NULL,NULL,'body:140309b109b3e6eb4f17b2c438d0aeab428b79fcf37d2864c37e166673528e9c','Wed, 07 Oct 2026 19:43:38 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('063de4c2-3510-45b2-bdca-1ab4250486ed','news-063de4c2-3510-45b2-bdca-1ab4250486ed','شركات التكنولوجيا العالمية تعزز حضورها في السعودية لمواكبة طفرة الذكاء الاصطناعي والتحول الرقمي','شركات التكنولوجيا العالميه تعزز حضورها في السعوديه لمواكبه طفره الذكاء الاصطناعي والتحول الرقمي','وفي ظل هذا الزخم، تتجه شركات عالمية وإقليمية إلى تعزيز حضورها المحلي وبناء شراكات طويلة الأمد، مستفيدة من الطلب المتنامي على الحلول الرقمية المتقدمة ودورها المتزايد في دعم مستهدفات رؤية السعودية 2030.','["تتسارع وتيرة الاستثمارات التقنية في المملكة العربية السعودية بالتوازي مع المشاريع التنموية الكبرى التي تشهدها المملكة، ما يفتح آفاقاً واسعة أمام شركات التكنولوجيا لتقديم خبراتها وحلولها في مجالات الذكاء الاصطناعي والحوسبة السحابية والبنية التحتية الرقمية ومراكز البيانات وتقنيات بيئة العمل. وفي ظل هذا الزخم، تتجه شركات عالمية وإقليمية إلى تعزيز حضورها المحلي وبناء شراكات طويلة الأمد، مستفيدة من الطلب المتنامي على الحلول الرقمية المتقدمة ودورها المتزايد في دعم مستهدفات رؤية السعودية 2030.","وأكد خالد المناعي، نائب رئيس اللجنة التنفيذية في شركة المناعي لتكنولوجيا المعلومات السعودية التابعة لمجمع شركات المناعي QPSC، أن الزخم التنموي الذي تشهده المملكة وما يرتبط به من مشاريع كبرى يتيح فرصاً واسعة أمام شركات التكنولوجيا التي تمتلك خبرات متخصصة، مشيراً إلى أن الشركة تسعى إلى توظيف خبراتها المتراكمة على مدى نحو 50 عاماً في قطاع تكنولوجيا المعلومات لدعم احتياجات السوق السعودية والمساهمة في مسيرة التحول الرقمي بالمملكة.","وقال المناعي إن الشركة راكمت خبرات واسعة من خلال العمل مع الجهات الحكومية والوزارات والبلديات والبنوك ومؤسسات القطاع الخاص، وتسعى اليوم إلى نقل هذه الخبرات إلى المملكة، في وقت تستعد فيه السعودية لتنفيذ مشاريع تطويرية ضخمة خلال السنوات العشر المقبلة، تتطلب تقنيات متقدمة وشركات تمتلك خبرات متخصصة في مجالات متعددة.","وأشار إلى أن تنظيم المملكة لمعرض إكسبو 2030 الرياض وكأس العالم 2034 يفتح المزيد من الفرص أمام شركات التكنولوجيا، لافتاً إلى أن \"المناعي\" تعمل في مجالات متنوعة تشمل الشبكات والبرمجيات والحلول التقنية المتخصصة.","وأوضح أن مشاركة الشركة في مشاريع مرتبطة بكأس العالم قطر 2022، بما في ذلك البنية التحتية للملاعب والأمن السيبراني، أسهمت في بناء خبرات تسعى الشركة إلى الاستفادة منها وتوظيفها في السوق السعودية.","وأضاف أن مجمع شركات المناعي يتمتع بحضور يمتد لنحو 75 عاماً في قطر، بينما يمتد نشاطه في قطاع تكنولوجيا المعلومات إلى نحو خمسة عقود، مشيراً إلى أن الشركة بدأت دخول السوق السعودية منذ نحو عام وتواصل العمل على توسيع أعمالها والاستفادة من الفرص المتاحة فيها.","وفي سياق متصل، أكد محمد سعادة، المدير الإقليمي لدى IFS في المملكة العربية السعودية، أن نجاح التحول الرقمي يتطلب تكامل عدة عناصر، بدءاً من التطبيقات المتخصصة ووصولاً إلى البنية التحتية السحابية القادرة على دعمها."]','التقنية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/m3obkjb4u','https://ajel.sa/economy/m3obkjb4u','https://ajel.sa/economy/m3obkjb4u','https://ajel.sa/economy/m3obkjb4u','فريق التحرير','الرياض','2026-09-03T07:47:00.000Z','Wed, 07 Oct 2026 19:43:42 GMT','2026-09-03T20:30:59.634Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000964867-crop-xMMgxANs.jpg','/api/media/063de4c2-3510-45b2-bdca-1ab4250486ed','/api/media/063de4c2-3510-45b2-bdca-1ab4250486ed?variant=thumbnail','شركات التكنولوجيا العالمية تعزز حضورها في السعودية لمواكبة طفرة الذكاء الاصطناعي والتحول الرقمي',1200,675,'valid','published','archived','valid',49,'d21e2b13054fcc996fede75e9b6d0714e2d35b0edf77a2d188995cbf9affa4b4','5f5636879f2cce33dad4341be19920d12a85683f1f044b13b27f258c9fa6c541','محدّث','2026-09-03T20:30:59.634Z','2026-10-07T20:24:32.712Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس اللجنة التنفيذية في شركة","شركة المناعي لتكنولوجيا المعلومات السعودية","الطاقة والنفط","الاقتصاد والأسواق","التقنية والتحول الرقمي","الرياض","الشرق الأوسط"]','["رئيس اللجنة التنفيذية في شركة","شركة المناعي لتكنولوجيا المعلومات السعودية","الطاقة والنفط","الاقتصاد والأسواق","التقنية والتحول الرقمي","الشرق الأوسط"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":4.5},{"category":"الطاقة والصناعة","score":3},{"category":"البيئة والمناخ","score":1.5}]','Updated','2026-10-07T19:43:44.108Z',200,58,0,'source_content_changed','',NULL,NULL,'body:6bae7392abad21b820d479a4b1384b2857b77091da6a4b47ae720d2cbd842065','Wed, 07 Oct 2026 19:43:42 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9fcb7d8a-988f-4dfb-a5d1-26de11754bfc','news-9fcb7d8a-988f-4dfb-a5d1-26de11754bfc','كأس الطائف للسرعة يتصدر الأسبوع السابع بجوائز 1.7 مليون ريال','كاس الطائف للسرعه يتصدر الاسبوع السابع بجوائز 1 7 مليون ريال','يستضيف ميدان الملك خالد للفروسية بمحافظة الطائف الأمسيتين الثالثة عشرة والرابعة عشرة ضمن منافسات الأسبوع السابع من موسم سباقات الطائف، وذلك يومَي الجمعة والسبت، في حدث يجمع نخبة من الجياد عبر 22 شوطاً بواقع 11 شوطاً في كل أمسية، وبمجموع جوائز مالية يبلغ 1.7 مليون ريال.','["أبرز أشواط الجمعة تتجه الأنظار في أمسية الجمعة إلى الشوط التحضيري لبطولة ميدان الملك خالد للأفراس، على مسافة 1400 متر وبجائزة مالية قدرها 120 ألف ريال، إذ تبرز الفرس «فالة خير» بشعار إسطبل أبناء الملك عبدالله بن عبدالعزيز، والفرس «جست فور سول» بشعار إسطبل الأمير سلطان بن مشعل بن عبدالعزيز، في منافسة تجمعهما مع الفرس «دانس ديسير» بشعار إسطبل الشيخ عبدالله حمود المالك الصباح، والفرس «كوافل» بشعار إسطبل فواز محارب حمدان المشرافي.","وفي الشوط التحضيري لتحدي نادي سباقات الخيل لعمر السنتين، على مسافة 1600 متر وبجائزة 120 ألف ريال، يتصدر المرشحين المهرُ «عراب» بشعار إسطبل الشيخ عبدالله حمود المالك الصباح، والمهر «النجم الساطي» بشعار إسطبل أبناء الملك عبدالله بن عبدالعزيز، إلى جانب المهر «ميمون» بشعار إسطبل يوسف محمد عبدالرحمن الطريف، والمهر «الزعيم» بشعار إسطبل عبدالله علي جريد المطيري.","كما يُقام الشوط التحضيري لبطولة ميدان الملك خالد مفتوح الدرجات، على مسافة 1600 متر وبجائزة 120 ألف ريال، ويبرز فيه المرشح «جيوقرفي» بشعار إسطبل أبناء الملك عبدالله بن عبدالعزيز، إلى جانب الجوادين «يادار» و«انكل» بشعار إسطبل الشيخ عبدالله حمود المالك الصباح.","كأس الطائف للسرعة يُتوّج السبت تتجه الأنظار في أمسية السبت إلى كأس الطائف للسرعة لخيل عمر السنتين، على مسافة 1200 متر وبجائزة كبرى قدرها 350 ألف ريال، حيث يتنافس المهر «راس المال» بشعار إسطبل الشيخ عبدالله حمود المالك الصباح، والمهر «المنتخب» بشعار إسطبل الأمير فيصل بن خالد بن عبدالعزيز، والمهر «بريف فيكوما» بشعار أيمن ناصر حمد الراجحي.","دعوة للحضور وجّه نادي سباقات الخيل دعوته لأهالي الطائف وزوارها لحضور منافسات الأسبوع السابع والاستمتاع بأجواء السباقات والفعاليات المصاحبة في ميدان الملك خالد للفروسية، إلى جانب أركان الضيافة والمطاعم والباقات المخصصة للجمهور، علماً بأن تذاكر الدخول مجانية عبر تطبيق «ويبوك»."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/1cgjjuj','https://sabq.org/article/1cgjjuj','','https://sabq.org/article/1cgjjuj','صحيفة سبق','','2026-09-03T07:28:00.000Z','2026-09-03T10:28:00.000Z','2026-09-03T20:31:00.372Z','https://media.sabq.org/news/2026/09/84bd0c28-14a7-42d3-af71-13d440a9c1a9/w659.webp','/api/media/9fcb7d8a-988f-4dfb-a5d1-26de11754bfc','/api/media/9fcb7d8a-988f-4dfb-a5d1-26de11754bfc?variant=thumbnail','كأس الطائف للسرعة يتصدر الأسبوع السابع بجوائز 1.7 مليون ريال',659,440,'valid','published','archived','valid',46,'ab09e91f700b1ab182c91fdb9148883725d488347c9a79aeb388ee51aa3e83cf','e36eed2adfd88fc2a799e8f9de6cb4c716a4d0c1ea43b8f8c2ab38907752038a','محدّث','2026-09-03T20:31:00.372Z','2026-10-07T19:43:04.373Z','','',0,0,'international','عادي',45,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"التقنية","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:04.373Z',200,58,0,'source_article_available','',NULL,NULL,'body:ba1147f10e6797f77613c409ec8233c7e8c95f960d8d9fa28faa49f38ad05319','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cd9fde36-4851-4b8d-8130-6bd62b961a2a','news-cd9fde36-4851-4b8d-8130-6bd62b961a2a','الأرصاد تحذّر من أمطار رعدية غزيرة على 6 مناطق حتى الأربعاء','الارصاد تحذر من امطار رعديه غزيره علي 6 مناطق حتي الاربعاء','توقّع المركز الوطني للأرصاد -بمشيئة الله تعالى- استمرار هطول الأمطار الرعدية على عدد من مناطق المملكة خلال الفترة الممتدة من السبت حتى الأربعاء المقبل، الموافق 5 حتى 9 سبتمبر 2026م، متفاوتةً في شدتها بين الخفيفة والغزيرة، ومصحوبةً بجملة من الظواهر الجوية المؤثرة.','["وأوضح المركز في تقريره الصادر اليوم، أن الأمطار يُتوقع أن تكون من متوسطة إلى غزيرة على مناطق جازان وعسير والباحة ومرتفعات منطقة مكة المكرمة، مع اشتداد غزارتها يومَي الاثنين والثلاثاء على أجزاء من منطقتَي جازان وعسير، فيما تمتد الأمطار الخفيفة إلى المتوسطة لتشمل منطقة نجران والأجزاء الجنوبية من منطقتَي الرياض والشرقية.","وفي تفاصيل التوقعات، تشمل الأمطار المتوسطة إلى الغزيرة في منطقة جازان محافظات: الريث، وهروب، والدائر، والعيدابي، وفيفاء، والعارضة، والحرث، وبيش، وصبيا، وضمد، وأبو عريش، وأحد المسارحة، وصامطة، والطوال، مع توقعات باشتداد الغزارة يومَي الاثنين والثلاثاء، فيما تشهد محافظتا جيزان وفرسان أمطاراً متوسطة تصل إلى غزيرة خلال اليومين ذاتهما.","وفي منطقة عسير، تطال الأمطار المتوسطة إلى الغزيرة محافظات: أبها، وخميس مشيط، وأحد رفيدة، وسراة عبيدة، والحرجة، وظهران الجنوب، والفرشة، والنماص، وتنومة، ورجال ألمع، وبارق، ومحايل عسير، والمجاردة، وبلقرن، مع توقعات باشتداد الغزارة يومَي الاثنين والثلاثاء، بينما تكون الأمطار متوسطة على بيشة والأمواه وطريب والبرك.","أما منطقة الباحة، فتشمل التوقعات هطول أمطار متوسطة تصل إلى غزيرة من الاثنين حتى الأربعاء على محافظات: الباحة، وبلجرشي، والمندق، وقلوة، وبني حسن، والقرى، والمخواة، والحجرة، وغامد الزناد، والعقيق.","وفي منطقة مكة المكرمة، يُتوقع هطول أمطار متوسطة تصل إلى غزيرة من الاثنين حتى الأربعاء على محافظات: الطائف، وميسان، وأضم، والعرضيات، في حين تشهد محافظات تربة والمويه والخرمة ورنية أمطاراً خفيفة إلى متوسطة خلال الفترة ذاتها.","وتشمل التوقعات كذلك محافظتَي وادي الدواسر والسليل بمنطقة الرياض، ومحافظات نجران وبدر الجنوب وحبونا وثار ويدمة وخباش وشرورة بمنطقة نجران، بأمطار خفيفة إلى متوسطة من الاثنين حتى الأربعاء، إضافةً إلى محافظة العديد وجنوب محافظة الأحساء بالمنطقة الشرقية يومَي الاثنين والثلاثاء.","وبيّن المركز أن الأمطار الخفيفة التي تتراوح كمياتها بين 1 و4 مليمترات في الساعة قد تصحبها رياح هابطة مثيرة للأتربة والغبار تصل سرعتها إلى 50 كيلومتراً في الساعة، فيما تتراوح كميات الأمطار المتوسطة بين 5 و9 مليمترات في الساعة وتصاحبها رياح تصل سرعتها إلى 60 كيلومتراً في الساعة، مع احتمال جريان السيول وتساقط البرد وارتفاع الأمواج على السواحل.","وأضاف أن كميات الأمطار الغزيرة قد تتراوح بين 10 و50 مليمتراً في الساعة أو أكثر، مصحوبةً برياح هابطة تتجاوز سرعتها 60 كيلومتراً في الساعة، وجريان السيول، وتساقط البرد، وارتفاع الأمواج على السواحل."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/oa96uek','https://sabq.org/article/oa96uek','','https://sabq.org/article/oa96uek','صحيفة سبق','الرياض','2026-09-03T07:25:00.000Z','2026-09-03T10:26:00.000Z','2026-09-03T20:31:00.464Z','https://media.sabq.org/news/2026/09/3446061f-e022-48f6-a99a-a945aeb99a5e/w1000.webp','/api/media/cd9fde36-4851-4b8d-8130-6bd62b961a2a','/api/media/cd9fde36-4851-4b8d-8130-6bd62b961a2a?variant=thumbnail','الأرصاد تحذّر من أمطار رعدية غزيرة على 6 مناطق حتى الأربعاء',1000,748,'valid','published','archived','valid',99,'ae3daa243a750a82b36626d2e35ce19d6dee67704ba5477627eefcd198fa2933','0d360b0bfc20d5d1b50ed49eee24ca13dc5b97e0bfb74b17ce033da6eedb8409','محدّث','2026-09-03T20:31:00.464Z','2026-10-07T19:43:05.074Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","التعليم والتدريب","مكة","عسير","جازان","نجران","الرياض","الباحة"]','["الطقس والمناخ","التعليم والتدريب"]','classified','','[{"category":"أخبار السعودية","score":1.5},{"category":"التقنية","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:05.074Z',200,59,0,'source_article_available','',NULL,NULL,'body:822b67eedfcde72cd8f42aba25162e4a2061fd035d33e2df4c77b0e4f3202fc0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('08f81657-a6db-4155-8277-9df13ed8c5e6','news-08f81657-a6db-4155-8277-9df13ed8c5e6','مستشفى الولادة والأطفال بالمدينة المنورة يُجري 3 عمليات نادرة لعلاج إصابات الضفيرة العصبية العضدية','مستشفي الولاده والاطفال بالمدينه المنوره يجري 3 عمليات نادره لعلاج اصابات الضفيره العصبيه العضديه','وتُمثّل الضفيرة العصبية العضدية شبكة من الأعصاب المسؤولة عن الحركة والإحساس في الكتف والذراع واليد، وقد تُفضي إصابتها إلى درجات متفاوتة من ضعف الحركة ومحدودية الوظائف الحركية للطرف العلوي.','["أجرى قسم جراحة عظام الأطفال بمستشفى الولادة والأطفال في مدينة الملك سلمان الطبية بالمدينة المنورة 3 عمليات جراحية متقدمة لعلاج مضاعفات إصابة الضفيرة العصبية العضدية لدى الأطفال، في إنجاز نوعي يُضاف إلى رصيد الخدمات التخصصية بالتجمع.","وأوضح تجمع المدينة المنورة الصحي أن الحالات الثلاث خضعت لإجراءات جراحية تصحيحية متخصصة تُعرف بـ«Secondary Procedures for Brachial Plexus Palsy Sequelae»، تستهدف تحسين وظائف الطرف العلوي واستعادة أكبر قدر ممكن من الحركة والقدرات الوظيفية لدى المرضى.","وتسعى هذه التدخلات الجراحية إلى تحقيق جملة من الأهداف العلاجية، أبرزها: تحسين مدى الحركة ووظائف الكتف والذراع، وتعزيز قدرة الطفل على ممارسة أنشطته اليومية، والحدّ من المضاعفات والإعاقات الحركية المرتبطة بالإصابة.","ويُعكس إجراء هذه العمليات تطوراً ملموساً في القدرات الجراحية بمدينة الملك سلمان الطبية، إذ يُسهم في توفير خدمات علاجية متقدمة للأطفال وتحسين جودة حياتهم، ضمن مساعي التجمع الصحي لرفع مستوى الرعاية الطبية التخصصية في المنطقة."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/i5v433j','https://sabq.org/article/i5v433j','','https://sabq.org/article/i5v433j','صحيفة سبق','المدينة المنورة','2026-09-03T07:23:00.000Z','2026-09-03T10:24:00.000Z','2026-09-03T20:31:00.470Z','https://media.sabq.org/news/2026/09/6e201c29-033c-4b2f-95d7-cc9847d495a9/w1600.webp','/api/media/08f81657-a6db-4155-8277-9df13ed8c5e6','/api/media/08f81657-a6db-4155-8277-9df13ed8c5e6?variant=thumbnail','مستشفى الولادة والأطفال بالمدينة المنورة يُجري 3 عمليات نادرة لعلاج إصابات الضفيرة العصبية العضدية',1600,1067,'valid','published','archived','valid',45,'d3aad23826439bcaef5de936100920dfe88136739fbe258a2feea8d11b912b0e','03ebf189816b056af09ad03c25588c28f76f7ee7e68efaa59cc1d4cc836cedbc','محدّث','2026-09-03T20:31:00.470Z','2026-10-07T20:24:32.724Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","المدينة المنورة"]','["الصحة العامة","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":2},{"category":"المجتمع","score":1.5},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:43:05.024Z',200,57,0,'source_article_available','',NULL,NULL,'body:298dee47964a6f72202404133ac7c7f1d9e9c44fb0b79787a2f648d337854a1c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('78ff1ae4-3a9b-431c-94ad-f10bfc9e70c5','news-78ff1ae4-3a9b-431c-94ad-f10bfc9e70c5','ولي العهد يتصل بالرئيس المصري ويبحثان تعزيز التعاون والمستجدات الإقليمية','ولي العهد يتصل بالرئيس المصري ويبحثان تعزيز التعاون والمستجدات الاقليميه','أجرى صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود، ولي العهد رئيس مجلس الوزراء، اتصالاً هاتفياً اليوم بفخامة الرئيس عبدالفتاح السيسي، رئيس جمهورية مصر العربية. وجرى خلال الاتصال استعراض علاقات التعاون بين المملكة العربية السعودية وجمهورية مصر العربية الشقيقة، وبحث سبل دعمها وتعزيزها في مختلف المجالات.','["أجرى صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود، ولي العهد رئيس مجلس الوزراء، اتصالاً هاتفياً اليوم بفخامة الرئيس عبدالفتاح السيسي، رئيس جمهورية مصر العربية.","وجرى خلال الاتصال استعراض علاقات التعاون بين المملكة العربية السعودية وجمهورية مصر العربية الشقيقة، وبحث سبل دعمها وتعزيزها في مختلف المجالات.","كما تطرّق الجانبان إلى المستجدات الإقليمية الراهنة، والجهود المبذولة لخفض التصعيد وتعزيز الأمن والاستقرار في المنطقة."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7x3ti7w','https://sabq.org/article/7x3ti7w','','https://sabq.org/article/7x3ti7w','صحيفة سبق','','2026-09-03T07:15:00.000Z','2026-09-03T11:21:00.000Z','2026-09-03T20:31:00.915Z','https://media.sabq.org/news/2026/07/30f8e557-8289-44be-87a2-48ecfbe25edd/w1096.webp','/api/media/78ff1ae4-3a9b-431c-94ad-f10bfc9e70c5','/api/media/78ff1ae4-3a9b-431c-94ad-f10bfc9e70c5?variant=thumbnail','ولي العهد يتصل بالرئيس المصري ويبحثان تعزيز التعاون والمستجدات الإقليمية',1096,832,'valid','published','archived','valid',99,'b2378fc0e440a3c13d1f32524dc6cc130c2d0dee10599d64b5d58d6d47eabc28','da44022bda3d191b489b0d0659536cf59652eeec210bc2e1a0ebb2ba87750e7e','محدّث','2026-09-03T20:31:00.915Z','2026-10-07T19:43:05.031Z','','',0,0,'saudi_national','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد يتصل بالرئيس المصري","رئيس مجلس الوزراء اتصالا هاتفيا","مجلس الوزراء اتصالا هاتفيا اليوم"]','["ولي العهد يتصل بالرئيس المصري","رئيس مجلس الوزراء اتصالا هاتفيا","مجلس الوزراء اتصالا هاتفيا اليوم"]','classified','','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:43:05.031Z',200,56,0,'source_article_available','',NULL,NULL,'body:651475a6a51e46608f19c495770915d796dcaef0c60caff0c220adc5ccf2eae0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e47d26e3-46cb-4791-a5c0-04088f52dc77','news-e47d26e3-46cb-4791-a5c0-04088f52dc77','ترامب: إمدادات النفط عبر مضيق هرمز عادت لمستوياتها السابقة','ترامب امدادات النفط عبر مضيق هرمز عادت لمستوياتها السابقه','أعلن الرئيس الأمريكي دونالد ترامب أن حجم إمدادات النفط العابرة عبر مضيق هرمز عادت بشكل شبه كامل إلى مستوياتها التي كانت سائدة قبل اندلاع الصراع مع إيران.','["ونشر ترامب عبر منصته «تروث سوشيال» بياناً مصحوباً برسوم بيانية، أوضح فيه أن المضيق يشهد حالياً عبور نحو 18 مليون برميل من النفط يومياً، مقارنةً بـ 20 مليون برميل قبل بدء التصعيد، معلّقاً على هذه البيانات بقوله: «أحجام النفط في مضيق هرمز عادت!».","وجاء هذا الإعلان في أعقاب تقرير نشرته شبكة «سي إن إن» الإخبارية، نقلاً عن مسؤولين أمريكيين، أفاد بأن القوات العسكرية الأمريكية رافقت مؤخراً 40 سفينة تجارية عبر المضيق، محملةً بنحو 18 مليون برميل من النفط.","وتُعدّ هذه الكمية الأعلى المسجّلة منذ بداية الأزمة، إذ كان المضيق يشهد عبور نحو 20 مليون برميل من النفط ومشتقاته يومياً قبل اندلاع التوترات في المنطقة، في مؤشر على تحسّن ملحوظ في حركة الملاحة التجارية عبر هذا الممر المائي الحيوي."]','الطاقة والصناعة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/9z7r62x','https://sabq.org/article/9z7r62x','','https://sabq.org/article/9z7r62x','صحيفة سبق','','2026-09-03T07:02:00.000Z','2026-09-03T10:03:00.000Z','2026-09-03T20:31:00.998Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/41bdfec2-1e56-4030-69da-2b4efa2b8900/public','/api/media/e47d26e3-46cb-4791-a5c0-04088f52dc77','/api/media/e47d26e3-46cb-4791-a5c0-04088f52dc77?variant=thumbnail','ترامب: إمدادات النفط عبر مضيق هرمز عادت لمستوياتها السابقة',801,451,'valid','published','archived','valid',35,'e5d13406c277fbe2a0a57666a69e0860c35713555a030d275d141ec6558cec1c','7ad1aa455f7d9db9dcf215c570231455446e3de43963c9068f2af655dead02c4','محدّث','2026-09-03T20:31:00.998Z','2026-10-07T20:24:32.737Z','','',0,0,'international','عادي',43,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","إيران"]','["الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:43:04.402Z',200,57,0,'source_article_available','',NULL,NULL,'body:c55f46a1b5cb7168afba0cd4a49fe6649125e19cb3483248e0680c11a3ac111d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f01518ab-8e46-44a6-be37-ba570ae50fd5','news-f01518ab-8e46-44a6-be37-ba570ae50fd5','الرياض تحتضن المهرجان العربي العاشر للرياضة للجميع بحفل افتتاح بهيج','الرياض تحتضن المهرجان العربي العاشر للرياضه للجميع بحفل افتتاح بهيج','انطلق في العاصمة الرياض المهرجان العربي العاشر للرياضة للجميع، الذي ينظمه الاتحاد السعودي للرياضة للجميع، وسط حضور الوفود العربية المشاركة من مختلف الدول. ويمتد برنامج المهرجان حتى الخامس من سبتمبر، ويشمل أنشطة ولقاءات متنوعة تجمع المشاركين العرب في إطار يعزز قيم الرياضة للجميع.','["انطلق في العاصمة الرياض المهرجان العربي العاشر للرياضة للجميع، الذي ينظمه الاتحاد السعودي للرياضة للجميع، وسط حضور الوفود العربية المشاركة من مختلف الدول.","وتضمّن حفل الافتتاح فقرات ترحيبية ورياضية متنوعة، جمعت بين الموروث الثقافي والنشاط الرياضي في أجواء احتفالية.","ويمتد برنامج المهرجان حتى الخامس من سبتمبر، ويشمل أنشطة ولقاءات متنوعة تجمع المشاركين العرب في إطار يعزز قيم الرياضة للجميع."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/kz53wnv','https://sabq.org/article/kz53wnv','','https://sabq.org/article/kz53wnv','صحيفة سبق','الرياض','2026-09-03T07:10:00.000Z','2026-09-03T10:10:00.000Z','2026-09-03T20:31:01.013Z','https://media.sabq.org/news/2026/09/e4a2c1ca-aa68-4934-893b-ccfa0d511d73/w1600.webp','/api/media/f01518ab-8e46-44a6-be37-ba570ae50fd5','/api/media/f01518ab-8e46-44a6-be37-ba570ae50fd5?variant=thumbnail','الرياض تحتضن المهرجان العربي العاشر للرياضة للجميع بحفل افتتاح بهيج',1600,1067,'valid','published','archived','valid',46,'baa148ce0f127001e3942e9eaf6d425fc934f034bdf0d127a936ff04fc989379','840ee14edcb69bc790401224091fef8f98279e2a3e3f6cc03490e6df9c15dd7c','محدّث','2026-09-03T20:31:01.013Z','2026-10-07T19:43:36.824Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:36.824Z',200,59,0,'source_article_available','',NULL,NULL,'body:dc0c28a1413f483e609fc5cd9497070d921a56b4868d17349cb13be27cce21c2','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e6aa1d59-e6ec-4875-9761-43079eff820c','news-e6aa1d59-e6ec-4875-9761-43079eff820c','CQR  و sirar by stc توقعان اتفاقية لتعزيز قدرات الأمن السيبراني للتقنيات التشغيلية والبنية التحتية الحيوية في المملكة','cqr و sirar by stc توقعان اتفاقيه لتعزيز قدرات الامن السيبراني للتقنيات التشغيليه والبنيه التحتيه الحيويه في المملكه','أعلنت شركة CQR (Absolute Solution for Cybersecurity Co.)، التي تعد أول شركة سعودية متخصصة في الأمن السيبراني للتقنيات التشغيلية وحماية البنية التحتية الحيوية، عن توقيع اتفاقية خدمات رئيسية مع sirar by stc، بهدف وضع إطار للتعاون بين الطرفين لتقديم حلول وخدمات متخصصة لحماية بيئات التقنيات التشغيلية (OT)، وإنترنت الأشياء (IoT)، وإنترنت الأشياء الصناعية…','["وتفتح الاتفاقية المجال أمام الطرفين للجمع بين تقنيات شركة CQR المطورة في المملكة وخبراتها المتخصصة في الأمن السيبراني الصناعي، وبين قدرات sirar by stc في مجال خدمات الأمن السيبراني المُدارة، لتطوير نموذج متكامل يدعم المنشآت في حماية أصولها وعملياتها الحيوية ومواجهة المخاطر السيبرانية المتزايدة في البيئات الصناعية والتشغيلية.","وتأتي منصة FENNEC التي طورتها شركة CQR في صميم هذا التعاون، باعتبارها منصة سعودية التصميم والتطوير مخصصة لحماية البنية التحتية الحيوية والبيئات الصناعية المعقدة.","وتوفر المنصة رؤية شاملة ومحدثة للأصول الحرجة، إلى جانب المراقبة الأمنية المرتبطة بسياق العمليات التشغيلية، والامتثال المستمر، وذكاء المخاطر الديناميكي، بما يساعد المنشآت على بناء رؤية أكثر دقة للمخاطر السيبرانية التي قد تؤثر على السلامة والإنتاج واستمرارية الأعمال.","كما تدعم الاتفاقية تطلعاتCQR وsirar by stc نحو إنشاء مركز سيادي لمراقبة وضمان الأمن السيبراني للتقنيات التشغيلية وإنترنت الأشياء مدعوم بالذكاء الاصطناعي، يجمع بين الخبرات التقنية والصناعية لـCQR وقدرات sirar by stc في خدمات الأمن السيبراني المُدارة، بما يعزز القدرات المحلية في حماية البيئات التشغيلية والبنية التحتية الحيوية في المملكة.","وفي هذا السياق، قال ناصر الدوسري، الرئيس التنفيذي لشركة CQR \"تبدأ السيادة السيبرانية بامتلاك التقنية والمعرفة والقدرات اللازمة لحماية بيئاتنا الأكثر أهمية.","ومن هذا المنطلق، حرصنا في CQR على تطوير منصة FENNEC في المملكة لتلبية المتطلبات المتخصصة للبيئات الصناعية والتشغيلية.","ونؤمن بأن توطين وتطوير التقنيات محليًا يمثل ركيزة أساسية لتعزيز القدرات الوطنية وبناء منظومة سيبرانية أكثر استقلالية واستدامة، بما يتماشى مع مستهدفات رؤية السعودية 2030.","ومن خلال تعاوننا مع sirar by stc، نتطلع إلى توسيع أثر هذه القدرات وتمكين المنشآت من فهم وإدارة المخاطر السيبرانية، وتعزيز حماية بنيتها التحتية وعملياتها الحيوية.\" كما أشار \"الدوسري\" الى أن منصة FENNEC توظف قدرات الذكاء الاصطناعي لدعم المحللين المتخصصين في تفسير التنبيهات الأمنية، وتحديد أولويات المخاطر، وتوجيه عمليات التحقيق، وتقييم الآثار المحتملة على العمليات التشغيلية، مع إبقاء القرارات التي قد تؤثر على عمليات الإنتاج تحت إشراف الخبراء المختصين."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/5zt7nk1','https://sabq.org/article/5zt7nk1','','https://sabq.org/article/5zt7nk1','صحيفة سبق','المنطقة الشرقية','2026-09-03T06:34:00.000Z','2026-09-03T09:35:00.000Z','2026-09-03T20:31:01.443Z','https://media.sabq.org/news/2026/09/334eae1c-257b-4f1b-94bd-5c043b548347/w1280.webp','/api/media/e6aa1d59-e6ec-4875-9761-43079eff820c','/api/media/e6aa1d59-e6ec-4875-9761-43079eff820c?variant=thumbnail','CQR  و sirar by stc توقعان اتفاقية لتعزيز قدرات الأمن السيبراني للتقنيات التشغيلية والبنية التحتية الحيوية في المملكة',1280,853,'valid','published','archived','valid',88,'70bff768c85f85481682addd234dbdb59b09e5a4e46bc254e23908012164e65c','7232efad200075a5c15af42a7d0aab26a34695709f8b246adc97e7dae64bae9c','محدّث','2026-09-03T20:31:01.443Z','2026-10-07T19:43:42.936Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة CQR Absolute Solution for","التعليم والتدريب","التقنية والتحول الرقمي"]','["شركة CQR Absolute Solution for","التعليم والتدريب","التقنية والتحول الرقمي"]','classified','','[{"category":"أخبار السعودية","score":4.5},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:42.936Z',200,66,0,'source_article_available','',NULL,NULL,'body:60409cb3bc140314b1c031eb431690c7dce6d50fbaa4a1b4d6f2cde19f790487','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('866547a5-9873-4007-a447-b71aaf14259e','news-866547a5-9873-4007-a447-b71aaf14259e','NHC توقع 5 اتفاقيات ومذكرات تفاهم تقنية خلال مؤتمر ليب 2026 لتعزيز التحول الرقمي والذكاء الاصطناعي','nhc توقع 5 اتفاقيات ومذكرات تفاهم تقنيه خلال مؤتمر ليب 2026 لتعزيز التحول الرقمي والذكاء الاصطناعي','كما وقعت NHC مذكرة تفاهم مع مجموعة Go للاتصالات، لتفعيل استخدام حلول إنترنت الأشياء للمراقبة في وجهات NHC، إلى جانب تطبيقات الذكاء الاصطناعي التي تسهم في تحسين المشهد الحضري.','["وقعت NHC خمس اتفاقيات ومذكرات تفاهم مع كل من Meta، ومجموعة Go للاتصالات، وهواوي، وGitLab، وstc solutions، ضمن أعمال مؤتمر ليب 2026، المقام خلال الفترة من 31 أغسطس إلى 3 سبتمبر 2026م في مركز الرياض للمعارض والمؤتمرات بملهم، بهدف تعزيز التعاون في المجالات التقنية والاستفادة من الحلول والتقنيات الحديثة في تطوير أعمالها ووجهاتها العمرانية.","وشملت مذكرة التفاهم مع Meta مجال تطوير قنوات التواصل والحلول الرقمية، حيث تهدف إلى تطوير وتفعيل حلول الأعمال عبر منصة واتساب للأعمال، بما يشمل تطبيقات التجارة والحلول المدعومة بالذكاء الاصطناعي.","وفي مجال الاتصالات وحلول المدن الذكية، وقعت NHC مذكرة تفاهم مع هواوي، تهدف إلى تقديم تجربة متطورة لسكان وزوار وجهات NHC، بما يسهم في تعزيز التجربة الرقمية وتوظيف التقنيات الحديثة في الوجهات العمرانية.","كما وقعت NHC مذكرة تفاهم مع GitLab، بهدف تطوير قدراتها في إدارة دورة حياة تطوير البرمجيات وتفعيل الذكاء الاصطناعي، بما يسهم في تعزيز كفاءة عمليات التطوير والاستفادة من التقنيات الحديثة.","وبهدف تطوير قدراتها والاستفادة من خدمات استضافة البنية التحتية السحابية، وقعت NHC اتفاقية مع stc solutions، بما يعزز جاهزية البنية التحتية السحابية ويدعم تطوير الخدمات والحلول الرقمية.","وتأتي هذه الاتفاقيات ومذكرات التفاهم امتدادا لجهود NHC في توسيع شراكاتها مع الشركات التقنية الرائدة، وتوظيف الحلول الرقمية والتقنيات الحديثة بما يدعم تطوير أعمالها ووجهاتها العمرانية، ويرفع كفاءة الخدمات ويرتقي بتجربة العملاء وجودة الحياة.","يذكر أن NHC تواصل قيادة القطاع العقاري على مختلف الأصعدة، بوصفها أكبر مطور عقاري في الشرق الأوسط، والرائدة في تطوير وجهات عمرانية وفق معايير عالية للجودة، إلى جانب العمل على تحسين تجربة الحياة اليومية للعملاء، حيث تتطلع إلى تقديم وجهات متكاملة تلبي تطلعاتهم وتحقق لهم استثمارا طويل الأمد."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/u8xunjk','https://sabq.org/article/u8xunjk','','https://sabq.org/article/u8xunjk','صحيفة سبق','الرياض','2026-09-03T06:51:00.000Z','2026-09-03T09:52:00.000Z','2026-09-03T20:31:01.501Z','https://media.sabq.org/news/2026/09/52c21349-3281-4533-a078-ba8311bbc48c/w1600.webp','/api/media/866547a5-9873-4007-a447-b71aaf14259e','/api/media/866547a5-9873-4007-a447-b71aaf14259e?variant=thumbnail','NHC توقع 5 اتفاقيات ومذكرات تفاهم تقنية خلال مؤتمر ليب 2026 لتعزيز التحول الرقمي والذكاء الاصطناعي',1600,1066,'valid','published','archived','valid',94,'6032b9098a0b4e42f44a4efa89b243139aa609538c6baa57449ba666bcbd36e6','994281e53bec676f00026015078b1067bae65a5371657dca104ec8387f1eaca1','محدّث','2026-09-03T20:31:01.501Z','2026-10-07T19:43:02.767Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","التقنية والتحول الرقمي","الرياض","الشرق الأوسط"]','["الاقتصاد والأسواق","التقنية والتحول الرقمي","الشرق الأوسط"]','classified','','[{"category":"المجتمع","score":5.5},{"category":"المناطق","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T19:43:02.767Z',200,53,0,'source_article_available','',NULL,NULL,'body:e8be762d5a680102bddb8856a2a507ed798cf302bc769e99628ca1392d553966','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fbf70cb8-7d23-4e90-b3ce-c808b94cb9cb','news-fbf70cb8-7d23-4e90-b3ce-c808b94cb9cb','اللجنة المحلية المنظمة لكأس آسيا 2027 السعودية تستعرض تجربة تطبيق "أهلاً" في ليب 2026','اللجنه المحليه المنظمه لكاس اسيا 2027 السعوديه تستعرض تجربه تطبيق اهلا في ليب 2026','وشارك الرئيس التنفيذي للقطاع التجاري وتجربة المشجع في اللجنة المحلية خالد خبتي، في جلسة استعرض خلالها رؤية اللجنة لبناء تجربة رقمية متكاملة ترافق المشجع منذ التخطيط لحضور البطولة وحتى الوصول إلى المملكة ودخول الملعب.','["اختتمت اللجنة المحلية المنظمة لكأس آسيا 2027 السعودية مشاركتها ضمن جناح وزارة الرياضة في النسخة الخامسة من الحدث التقني العالمي \"ليب 2026\"، الذي انطلق الاثنين الماضي في مركز الرياض للمعارض والمؤتمرات بملهم ويختتم اليوم، مستعرضةً تجربتها في توظيف الحلول التقنية لتطوير رحلة المشجع، وفي مقدمتها تطبيق \"أهلًا\".","وأوضح خبتي أن النسخة الحالية من تطبيق \"أهلًا\" تجريبية وتخضع للتطوير وصولًا إلى النسخة المتكاملة المخصصة لكأس آسيا 2027 السعودية، مشيرًا إلى أن التطبيق بدأ مرحلته التجريبية خلال منافسات دوري أبطال آسيا للنخبة التي استضافتها جدة هذا العام، واستفاد منه أكثر من (330) ألف مستخدم.","وقال: \"التطبيق يتيح حاليًا إنشاء الملفات الشخصية، واختيار المنتخبات المفضلة، وشراء التذاكر, ومتابعة أخبار البطولة ومواعيد المباريات والنتائج، فيما يجري العمل على إضافة حجوزات الفنادق والتقدم للحصول على التأشيرة وباقات السفر وخدمة الاتصال عبر \"eSIM\"، وتطوير خدمات التنقل والإرشاد، ودعم اللغتين اليابانية والصينية إلى جانب العربية والإنجليزية\".","وبيّن خبتي أن العمل يشمل تطوير خدمات العناية بالجماهير والدعم على مدار الساعة، إلى جانب منظومة للتحقق والأمان تستهدف تعزيز موثوقية شراء التذاكر والحد من إعادة البيع غير النظامية والشراء الآلي، مؤكدًا أن رؤية التطبيق تمتد لتشمل العاملين والوفود والإعلاميين والشركاء المرتبطين بالبطولة.","وتأتي مشاركة اللجنة في \"ليب 2026\", ضمن استعداداتها المتواصلة لاستضافة كأس آسيا 2027 السعودية، والاستفادة من الأحداث والبطولات التي تستضيفها المملكة في اختبار وتطوير الحلول التشغيلية والتقنية قبل البطولة.","وتستضيف المملكة كأس آسيا 2027 السعودية خلال الفترة من 7 يناير حتى 5 فبراير 2027, بمشاركة (24) منتخبًا يتنافسون في (51) مباراة، تقام في ثلاث مدن، هي: الرياض وجدة والخبر."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/bn16niy','https://sabq.org/article/bn16niy','','https://sabq.org/article/bn16niy','صحيفة سبق','الرياض','2026-09-03T06:38:00.000Z','2026-09-03T09:40:00.000Z','2026-09-03T20:31:01.618Z','https://media.sabq.org/news/2026/09/d9b51b25-f79e-415e-bfb1-6a63e2b65cd4/w1600.webp','/api/media/fbf70cb8-7d23-4e90-b3ce-c808b94cb9cb','/api/media/fbf70cb8-7d23-4e90-b3ce-c808b94cb9cb?variant=thumbnail','اللجنة المحلية المنظمة لكأس آسيا 2027 السعودية تستعرض تجربة تطبيق "أهلاً" في ليب 2026',1600,1066,'valid','published','archived','valid',55,'70080fb043c75053daea647a46979275beb4c724c0f87e64fb6042138a721a91','98f3b5e8da2cdce8f0cfc697391cdb803cba9068f9fc43e76f42e06ce92d3198','محدّث','2026-09-03T20:31:01.618Z','2026-10-07T19:43:36.818Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الرياضة في النسخة الخامسة","السفر والسياحة","الرياضة السعودية","التقنية والتحول الرقمي","جدة","الصين","الرياض"]','["وزارة الرياضة في النسخة الخامسة","السفر والسياحة","الرياضة السعودية","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":4.5},{"category":"الرياضة","score":4.5},{"category":"المناطق","score":-2}]','Active','2026-10-07T19:43:36.818Z',200,57,0,'source_article_available','',NULL,NULL,'body:1d58805213c40b5016198c642803f25620fe23f516a226f3589fc4e128b4d07e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('19df9c46-0c0f-4e11-bd4f-7cf4c5502b16','news-19df9c46-0c0f-4e11-bd4f-7cf4c5502b16','«البديوي»: الزراعة والأمن الغذائي أولوية إستراتيجية لدول الخليج','البديوي الزراعه والامن الغذائي اولويه استراتيجيه لدول الخليج','جاء ذلك خلال ترؤس «البديوي» الاجتماع الـ38 للجنة التعاون الزراعي والأمن الغذائي بدول مجلس التعاون، الذي عُقد اليوم في المنامة ، برئاسة وزير شؤون البلديات والزراعة البحريني وائل المبارك، وبحضور الوزراء المعنيين بالزراعة والأمن الغذائي في دول المجلس.','["أكد الأمين العام لمجلس التعاون ل دول الخليج العربية ، جاسم محمد البديوي، أن «منظومة الزراعة والأمن الغذائي في دول المجلس تمثل أولوية إستراتيجية وركيزة أساسية في مسيرة العمل الخليجي المشترك، وذلك انطلاقًا من اهتمام الدول الأعضاء بتطوير الإنتاج الزراعي والغذائي وتعزيز جاهزيتها لمواجهة التحديات».","وأوضح «البديوي» أن «اللقاء التشاوري التاسع عشر للمجلس الأعلى، المنعقد في جدة في أبريل الماضي، أفضى إلى توجيهات لتعزيز جاهزية دول المجلس في مواجهة الأزمات، من بينها دراسة إنشاء مناطق للخزن الإستراتيجي الخليجي».","وأضاف أن «الجهود الوطنية في هذا المجال تشمل توظيف الإمارات للتقنيات الزراعية في تطوير محاصيل نوعية، وتعزيز المملكة العربية السعودية لمخزونها الإستراتيجي من الأغذية ومنظومة الإنذار المبكر، وتنفيذ قطر لاستراتيجيتها الوطنية للأمن الغذائي 2030، إلى جانب برامج مماثلة في البحرين و عُمان و الكويت ».","وفي السياق ذاته، أكد «البديوي» أن «هذه الجهود تمثل رافدًا أساسيًا لتحقيق أهداف الإستراتيجية الخليجية للأمن الغذائي»."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/m00o40q6w','https://ajel.sa/international/m00o40q6w','https://ajel.sa/international/m00o40q6w','https://ajel.sa/international/m00o40q6w','فريق التحرير','مكة المكرمة','2026-09-03T06:10:00.000Z','Wed, 07 Oct 2026 19:43:50 GMT','2026-09-03T20:31:01.806Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%AC%D8%A7%D8%B3%D9%85-%D9%85%D8%AD%D9%85%D8%AF-%D8%A7%D9%84%D8%A8%D8%AF%D9%8A%D9%88%D9%8A-_VPMNxmJ.jpg','/api/media/19df9c46-0c0f-4e11-bd4f-7cf4c5502b16','/api/media/19df9c46-0c0f-4e11-bd4f-7cf4c5502b16?variant=thumbnail','«البديوي»: الزراعة والأمن الغذائي أولوية إستراتيجية لدول الخليج',1200,675,'valid','published','archived','valid',44,'c2e5355817f9b2cf9c6fdfbc177a4e0dce8ebbe64db4f5c5e112e70871767b1b','3cc1a41ffe99b557750c6f990eecfb6d234cafe930b01db759e7a28bd2597030','محدّث','2026-09-03T20:31:01.806Z','2026-10-07T19:43:52.453Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس التعاون الذي ع قد","وزير شؤون البلديات والزراعة البحريني","جدة","الخليج العربي"]','["مجلس التعاون الذي ع قد","وزير شؤون البلديات والزراعة البحريني","الخليج العربي"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":3},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:43:52.453Z',200,68,0,'source_content_changed','',NULL,NULL,'body:1fe4b707329b69bf65c5e8d6acd9a0442fd8fc7e9d3abf8ae5b1a655e590c66e','Wed, 07 Oct 2026 19:43:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('aa060c02-3aa1-4e91-b061-1ee9427c87d8','news-aa060c02-3aa1-4e91-b061-1ee9427c87d8','حين تتسع الكلمات أكثر مما ينبغي','حين تتسع الكلمات اكثر مما ينبغي','نحزن فنقول إننا حزينون، نقلق قبل موعد مهم، نتألم من علاقة انتهت، ونغضب من شخص أساء إلينا. صرنا نعرف عن الصدمات النفسية، والقلق، والاكتئاب، والعلاقات السامة، والنرجسية، والتلاعب، والحدود النفسية.','["في وقتٍ ما كنا نشعر بالأشياء دون أن نعرف أسماءها.","نحزن فنقول إننا حزينون، نقلق قبل موعد مهم، نتألم من علاقة انتهت، ونغضب من شخص أساء إلينا.","كانت المشاعر، رغم ثقل بعضها، تحمل أسماء بسيطة تشبهها.","اليوم، أصبحنا نملك لغة أوسع بكثير لفهم ما يحدث داخلنا.","صرنا نعرف عن الصدمات النفسية، والقلق، والاكتئاب، والعلاقات السامة، والنرجسية، والتلاعب، والحدود النفسية.","وهذا الوعي منح كثيرين القدرة على فهم تجارب عاشوها طويلاً دون تفسير، وساعد آخرين على طلب المساعدة حين احتاجوها.","لكن ماذا لو اتسعت الكلمات أكثر مما ينبغي؟","ماذا لو أصبح كل حزن اكتئاباً، وكل خوف اضطراباً، وكل علاقة مؤلمة سامة، وكل شخص أناني نرجسياً، وكل موقف ترك أثراً فينا صدمة نفسية؟"]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7g352el','https://sabq.org/article/7g352el','','https://sabq.org/article/7g352el','ملك الحازمي','المدينة المنورة','2026-09-03T06:24:00.000Z','2026-09-03T09:24:00.000Z','2026-09-03T20:31:01.963Z','https://media.sabq.org/news/2026/09/1a69000a-f5d6-4040-9545-1acc0667b9e7/w1600.webp','/api/media/aa060c02-3aa1-4e91-b061-1ee9427c87d8','/api/media/aa060c02-3aa1-4e91-b061-1ee9427c87d8?variant=thumbnail','حين تتسع الكلمات أكثر مما ينبغي',1600,893,'valid','published','archived','valid',41,'ccf853c9c8e2e3b75713a5998e1dde9dd4b5732546701391d8202a4d4bcaf6e4','92c2fc6fb48963271c34b189b4e44c9b772a4123711bc45173319155530e7aed','محدّث','2026-09-03T20:31:01.963Z','2026-10-07T19:43:42.926Z','','',0,0,'saudi_region','عادي',51,NULL,0,0,0,'',NULL,NULL,NULL,'["المدينة المنورة"]','["المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:42.926Z',200,65,0,'source_article_available','',NULL,NULL,'body:27d0cb01b944aae3becb192dad594e830c5c2355d5b181184d81d54dac1ae465','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4e4d1912-dd4f-4f31-b5a9-7b9f3a34e07a','news-4e4d1912-dd4f-4f31-b5a9-7b9f3a34e07a','«الحرف والأعمال اليدوية 2026» يختتم نسخته التاسعة بالشرقية غداً','الحرف والاعمال اليدويه 2026 يختتم نسخته التاسعه بالشرقيه غدا','يختتم «معرض الحرف والأعمال اليدوية 2026» غداً الجمعة فعاليات نسخته التاسعة، التي تنظمها غرفة الشرقية على أرض معارض الظهران إكسبو، وسط إقبال لافت من الزوار على المنتجات الحرفية والتراثية المصنوعة محلياً.','["وشهد المعرض تنوعاً واسعاً في المشاركات، شمل الحرف اليدوية والديكور والإكسسوارات والملابس والعطور والمأكولات والحلويات، فيما أشاد الزوار بجودة المنتجات وتنوعها، وما قدمته من نماذج تجمع بين أصالة الموروث وروح الابتكار.","وشكّل المعرض منصةً للحرفيين والحرفيات لتسويق منتجاتهم والتعريف بمشروعاتهم، والوصول إلى شرائح أوسع من الجمهور، إلى جانب تبادل الخبرات واستكشاف فرص جديدة لتطوير أعمالهم وتحويل مواهبهم إلى مشروعات مستدامة.","ومن أبرز التجارب اللافتة، نجح المتقاعد سعيد العمري في تحويل شغفه بالتراث إلى مشروع لصناعة مجسمات مصغرة تحاكي البيوت والمباني القديمة بتفاصيلها الدقيقة، بعد أن انطلقت الفكرة كهواية لشغل وقت الفراغ قبل أن تتحول إلى مشروع تجاري قائم.","وفي تجربة تجمع بين الفن والاستدامة، قدّم متجر «كرب آرت» أعمالاً فنية تعتمد على إعادة توظيف «كرب النخيل» وتحويله إلى قطع فنية وتشكيلية عصرية، في نموذج يجمع بين الموروث البيئي ومفاهيم الاستدامة وإعادة التدوير.","كما أبرز المعرض نماذج ملهمة من ذوي الإعاقة، الذين عرضوا منتجات يدوية وفنية اتسمت بالدقة والابتكار، في تجارب تعكس أثر برامج التمكين في تطوير مهاراتهم وتعزيز استقلاليتهم الاقتصادية وفتح آفاق أوسع أمامهم للمشاركة في سوق العمل.","وحضرت التجارب النسائية بقوة في فعاليات المعرض، ومن أبرزها تجربة مارية محمد، التي حوّلت شغفها بفن «الكروشيه» إلى مشروع صغير يجمع بين الغرز التراثية والتصاميم الحديثة، سعياً إلى المحافظة على هذا الموروث وتقديمه بصورة عصرية قابلة للتسويق.","ويتجاوز «معرض الحرف والأعمال اليدوية 2026» كونه منصةً لعرض المنتجات، ليُبرز قصص النجاح والطموح، ويدعم المواهب الوطنية في تحويل مهاراتها إلى مشروعات منتجة ومستدامة، بما يعزز حضور المنتج المحلي ويُسهم في صون الإرث الحرفي السعودي."]','الوظائف وسوق العمل','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/mvya3lb','https://sabq.org/article/mvya3lb','','https://sabq.org/article/mvya3lb','صحيفة سبق','المنطقة الشرقية','2026-09-03T06:09:00.000Z','2026-09-03T09:10:00.000Z','2026-09-03T20:31:02.020Z','https://media.sabq.org/news/2026/09/3558a3ea-4bbe-47fe-b661-cad8fd382a7e/w1600.webp','/api/media/4e4d1912-dd4f-4f31-b5a9-7b9f3a34e07a','/api/media/4e4d1912-dd4f-4f31-b5a9-7b9f3a34e07a?variant=thumbnail','«الحرف والأعمال اليدوية 2026» يختتم نسخته التاسعة بالشرقية غداً',1600,1066,'valid','published','archived','valid',49,'9a5147553b6d0c06fc785f510ef0d9a16c5aadaec06110f4570e72aa97440191','700e3b26f8d1b58f257146fb3a4107f16c516d9aabe08e73d875a830f77c1eeb','محدّث','2026-09-03T20:31:02.020Z','2026-10-07T20:24:32.756Z','','',0,0,'saudi_region','مهم',74,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:36.837Z',200,61,0,'source_article_available','',NULL,NULL,'body:35078764c59a902fd9708ae9be96fc347f46775b57e4cedabbbe3df33d4034a6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b405baba-142e-4980-aed6-e4c879dd4864','news-b405baba-142e-4980-aed6-e4c879dd4864','دستي هولدنجز تعيد ابتكار المشتريات بالذكاء الاصطناعي','دستي هولدنجز تعيد ابتكار المشتريات بالذكاء الاصطناعي','ومن هنا تبني دستي هولدنجز نموذجًا جديدًا للمشتريات والتوريد، صُمم من الأساس حول الذكاء الاصطناعي؛ بحيث يكون الذكاء جزءًا جوهريًا من فهم الاحتياج، واكتشاف المنتجات والموردين، وتحليل الخيارات، ودعم قرار الشراء.','["تدخل المملكة العربية السعودية مرحلة جديدة من التجارة الذكية، والمشتريات هي المحطة التالية.","فعلى مدى عقود، اعتمدت عمليات المشتريات على أنظمة متفرقة، والبحث اليدوي عن الموردين، وبيانات غير مترابطة، ومراحل متعددة للوصول إلى قرار الشراء.","وفي قلب هذا النموذج، يعمل الذكاء الاصطناعي على فهم ما تحتاجه الجهة، وليس فقط ما تبحث عنه؛ من خلال مطابقة الطلب مع العرض، وتحليل البدائل، وربط الاحتياج بأفضل الخيارات المتاحة ضمن شبكة واسعة من المنتجات والموردين.","ولا تنطلق هذه الرؤية من تجربة تقنية معزولة عن السوق، بل من خبرة تشغيلية حقيقية.","فقد تجاوز حجم مبيعات دستي مليار ريال سعودي خلال نحو عامين، عبر أكثر من 100 ألف طلب، مع شبكة تضم أكثر من 1,000 علامة تجارية وأكثر من مليون منتج من مصادر محلية ودولية.","وتشير التقديرات إلى أن تطبيق تقنيات الذكاء الاصطناعي المتقدمة يمكن أن يرفع كفاءة وظائف المشتريات بنسبة تتراوح بين 25% و40%، ما يعكس حجم الفرصة لإعادة تطوير هذه العملية على نطاق واسع.","وقال أحمد أبوالعسل، المؤسس والرئيس التنفيذي لدستي هولدنجز: “نؤمن أن أكبر فرصة للذكاء الاصطناعي ليست في أتمتة المهام الفردية، بل في إعادة تصميم طريقة عمل الشركات من الأساس.","والمشتريات واحدة من أكبر الفرص لتحقيق ذلك."]','الذكاء الاصطناعي','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/x3m5txv','https://sabq.org/article/x3m5txv','','https://sabq.org/article/x3m5txv','صحيفة سبق','','2026-09-03T06:22:00.000Z','2026-09-03T09:23:00.000Z','2026-09-03T20:31:02.065Z','https://media.sabq.org/news/2026/09/98332b8f-b1e3-4a44-8e65-037a1a4c4a53/w1600.webp','/api/media/b405baba-142e-4980-aed6-e4c879dd4864','/api/media/b405baba-142e-4980-aed6-e4c879dd4864?variant=thumbnail','دستي هولدنجز تعيد ابتكار المشتريات بالذكاء الاصطناعي',1600,1600,'valid','published','archived','valid',50,'bd58569063a10fd35907b2ee28c0718eb739b59c23b4ac300a9ea6724ac07bec','0dd5e45b010a38093ba1ccd0a829801475a43e6848d33503a52e949f71ac3f7c','محدّث','2026-09-03T20:31:02.065Z','2026-10-07T20:24:32.760Z','','',0,0,'saudi_national','عادي',61,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:02.734Z',200,55,0,'source_article_available','',NULL,NULL,'body:e4b1ebf84699d49b529229b8c041843b80d6df7a76d5ad97895db8b788d05189','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9f560f1f-4f61-461a-95e0-d87484b9acf7','news-9f560f1f-4f61-461a-95e0-d87484b9acf7','وزارة التجارة تنفذ أكثر من 20 ألف جولة ميدانية لمراقبة تخفيضات 2026','وزاره التجاره تنفذ اكثر من 20 الف جوله ميدانيه لمراقبه تخفيضات 2026','نفّذت وزارة التجارة أكثر من 20 ألف جولة ميدانية على الأسواق والمراكز التجارية ومنافذ البيع في مناطق المملكة كافة، للتحقق من التزامها بضوابط وشروط التخفيضات خلال شهر أغسطس 2026.','["وتأتي هذه الجولات التفتيشية تزامناً مع موسم تخفيضات 2026، الذي انطلق مطلع أغسطس ويمتد حتى 31 أكتوبر 2026.","وتحققت الفرق الرقابية للوزارة من جملة من المعايير، أبرزها: تراخيص التخفيضات وإبرازها للمستهلك، والالتزام بالتخفيضات والعروض الحقيقية المرخّص لها، ونسب التخفيضات، وبطاقات الأسعار أو القارئ الإلكتروني المتضمّن السعر قبل التخفيض وبعده، فضلاً عن الإفصاح بوضوح عن سياسة الاستبدال والاسترجاع.","ودعت الوزارة المستهلكين إلى التحقق من نظامية التخفيضات والعروض التجارية وصحتها، عبر مسح «الباركود» الظاهر في الترخيص للاطلاع على كافة البيانات المتعلقة بالتخفيضات، والتي تشمل «نوع التخفيضات ونسبتها ومدتها، إضافة إلى بيانات المنشأة»."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/xfh2hc5','https://sabq.org/article/xfh2hc5','','https://sabq.org/article/xfh2hc5','صحيفة سبق','','2026-09-03T05:50:00.000Z','2026-09-03T08:50:00.000Z','2026-09-03T20:31:02.505Z','https://media.sabq.org/news/2026/09/53e7f62b-8f8d-4ed3-873b-2b18cb8848b3/w554.webp','/api/media/9f560f1f-4f61-461a-95e0-d87484b9acf7','/api/media/9f560f1f-4f61-461a-95e0-d87484b9acf7?variant=thumbnail','وزارة التجارة تنفذ أكثر من 20 ألف جولة ميدانية لمراقبة تخفيضات 2026',554,554,'valid','published','archived','valid',41,'844f931331f563759c7836a666254c21def88a3bc225666c82f16c5464f0526f','324ab53512219fc6bbf0aa8ae8d98c9481437f21d7430bc24c229d9a01f38c56','محدّث','2026-09-03T20:31:02.505Z','2026-10-07T20:24:32.764Z','','',0,0,'saudi_national','مهم',69,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة التجارة تنفذ أكثر من","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','["وزارة التجارة تنفذ أكثر من","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:43:42.290Z',200,64,0,'source_article_available','',NULL,NULL,'body:b8a71e309a8577e99c1325b2d0409c57330ab7edad3d1c03efb6d784f56068fd','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7d8f1020-45d9-46cd-870f-b316a9fccaf5','news-7d8f1020-45d9-46cd-870f-b316a9fccaf5','مطارات الدمام تحصد 6 اعتمادات دولية من مجلس المطارات','مطارات الدمام تحصد 6 اعتمادات دوليه من مجلس المطارات','حصلت مطارات الدمام على 6 شهادات اعتماد دولية من مجلس المطارات الدولي «ACI»، خلال قمة تجربة المطارات العالمية 2026 التي أُقيمت في مدينة إسطنبول، في مجالات تعزيز الوصول، والصحة والسلامة، وتجربة العميل، بما يعكس التطور المستمر في منظومة العمل والخدمات، والجهود المبذولة للارتقاء بتجربة المسافرين في مطار الملك فهد الدولي بالدمام، ومطار الأحساء الدولي، ومطار…','["وشمل الإنجاز حصول مطار الملك فهد الدولي بالدمام، ومطار الأحساء الدولي، ومطار القيصومة الدولي على شهادة اعتماد «تعزيز الوصول – المستوى الأول»، في تأكيد على الجهود التي تبذلها مطارات الدمام لتطوير بيئة مطارية أكثر شمولًا وسهولة في الوصول، وتعزيز الخدمات والتسهيلات المقدمة لمختلف فئات المسافرين، بما يتوافق مع المعايير والممارسات المعتمدة في قطاع المطارات.","كما حصل مطار الملك فهد الدولي بالدمام على شهادة اعتماد «الالتزام بمعايير الصحة والسلامة»، بما يعكس مستوى الالتزام بتطبيق المعايير والممارسات المرتبطة بالصحة والسلامة، وتوفير بيئة مطارية آمنة للمسافرين والعاملين، وتعزيز الجاهزية والكفاءة في مختلف العمليات التشغيلية ذات الصلة.","وفي مجال تجربة المسافر، حصل كل من مطار الأحساء الدولي ومطار القيصومة الدولي على شهادة اعتماد «تجربة العميل – المستوى الأول»، في إنجاز يعكس التطور الذي تشهده منظومة الخدمات في المطارين، والاهتمام بتطوير رحلة المسافر ورفع مستوى جودة الخدمات المقدمة، وتبني الممارسات التي تضع احتياجات المسافر وتوقعاته في صميم عمليات التطوير والتحسين المستمر.","ويعكس حصول المطارات الثلاثة على هذه الاعتمادات الدولية نهج مطارات الدمام في تطوير منظومة متكاملة لإدارة وتشغيل المطارات وفق أفضل الممارسات العالمية، وتعزيز جودة تجربة السفر، إلى جانب مواصلة العمل على تطوير معايير الوصول والصحة والسلامة وتجربة العميل في جميع المطارات التابعة لها.","كما يأتي هذا الإنجاز ثمرة للجهود المتكاملة التي تبذلها فرق العمل في مطارات الدمام، والعمل المستمر على رفع كفاءة الأداء التشغيلي والخدمي، وتطوير الإجراءات والممارسات بما يتوافق مع متطلبات الاعتمادات الدولية، ويعزز قدرة المطارات الثلاثة على تقديم تجربة سفر متكاملة بمستويات متقدمة من الجودة والكفاءة.","وتواصل مطارات الدمام تنفيذ خططها الرامية إلى تطوير تجربة المسافر والارتقاء بجودة الخدمات في مطاراتها الثلاثة، وتعزيز كفاءتها التشغيلية وتنافسيتها إقليميًا ودوليًا، بما يدعم مستهدفات رؤية السعودية 2030 والاستراتيجية الوطنية للطيران، ويعزز دور مطارات المنطقة الشرقية في منظومة النقل الجوي بالمملكة.","ويمثل تحقيق 6 شهادات اعتماد دولية خلال قمة تجربة المطارات العالمية 2026 امتدادًا لمسيرة التطوير التي تشهدها مطارات الدمام، وتأكيدًا على التزامها بمواصلة تبني المعايير والممارسات العالمية في قطاع المطارات، وبناء تجربة سفر أكثر شمولًا وأمانًا وجودة، وتعزيز حضور مطاراتها على خارطة المطارات الإقليمية والدولية."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/pgizlrd','https://sabq.org/article/pgizlrd','','https://sabq.org/article/pgizlrd','صحيفة سبق','المنطقة الشرقية','2026-09-03T06:05:00.000Z','2026-09-03T09:07:00.000Z','2026-09-03T20:31:02.516Z','https://media.sabq.org/news/2026/09/8d15653e-1838-444b-a0d0-bde1b14ceeb2/w1280.webp','/api/media/7d8f1020-45d9-46cd-870f-b316a9fccaf5','/api/media/7d8f1020-45d9-46cd-870f-b316a9fccaf5?variant=thumbnail','مطارات الدمام تحصد 6 اعتمادات دولية من مجلس المطارات',1280,854,'valid','published','archived','valid',44,'c71991bfb997cb5601de0b9899c26fb1eba86c7d9c0742789bd530cc67e6c95f','61406133837fc5cc293f6608d95ab2ab8ded2b180eb1483608d224bc742ecca8','محدّث','2026-09-03T20:31:02.516Z','2026-10-07T20:24:32.769Z','','',0,0,'saudi_region','مهم',67,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس المطارات حصلت مطارات الدمام","الصحة العامة","السفر والسياحة","الدمام"]','["مجلس المطارات حصلت مطارات الدمام","الصحة العامة","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":3},{"category":"التقنية","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:42.932Z',200,65,0,'source_article_available','',NULL,NULL,'body:b9b9c311511f000f921ce5f85b46173f5885d0ea087bd8ea423b5c7af4827e75','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('75809ea0-20b6-4811-a5d3-88d955536542','news-75809ea0-20b6-4811-a5d3-88d955536542','«التخصصي» يستضيف مؤتمر الشرق الأوسط لجراحة القلب الروبوتية في الرياض','التخصصي يستضيف مؤتمر الشرق الاوسط لجراحه القلب الروبوتيه في الرياض','ويتضمن البرنامج جلسات علمية ونقاشات متخصصة، إلى جانب جلسة تطبيقية عملية تتيح للمشاركين التعرّف بصورة أعمق على جراحة القلب الروبوتية، ومناقشة الجوانب العملية المرتبطة باستخدام التقنيات الروبوتية في جراحات القلب.','["ينظّم مستشفى الملك فيصل التخصصي ومركز الأبحاث مؤتمر الشرق الأوسط لجراحة القلب الروبوتية، في السادس عشر من سبتمبر الجاري بقاعة الملك سلمان في الرياض، بمشاركة خبراء ومختصين في الرعاية الصحية، لمناقشة أحدث التطورات في جراحات القلب الروبوتية، واستعراض تطبيقاتها السريرية، وتبادل الخبرات حول توظيفها في تطوير الممارسة الجراحية وتحسين نتائج المرضى.","ويُعنى المؤتمر بمناقشة أسس اختيار المرضى وتقييم المخاطر وفق الممارسات القائمة على الأدلة، وإستراتيجيات التعامل مع أمراض القلب والأوعية الدموية، إلى جانب تعزيز التكامل بين التخصصات الصحية وتثقيف المرضى، بما يدعم اتخاذ قرارات علاجية أكثر ملاءمة لكل حالة واحتياجاتها.","وقال رئيس اللجنة العلمية للمؤتمر ونائب المدير التنفيذي لمركز التميز للقلب في «التخصصي» الدكتور فراس خليل: «يمثل المؤتمر فرصة لربط التطورات العلمية في جراحة القلب الروبوتية بالجانب التطبيقي، ومناقشة مستقبل هذا النوع من الجراحات، وما يتطلبه من معرفة متخصصة ومهارات تقنية، بما يسهم في تعزيز فهم المختصين لهذا المجال».","ويأتي تنظيم المؤتمر ضمن جهود «التخصصي» لتعزيز حضوره العلمي في جراحات القلب المتقدمة، والإسهام في بناء بيئة مهنية تدعم الحوار العلمي حول التقنيات الجراحية الحديثة، وتوسيع نطاق التعاون بين المختصين والمؤسسات المعنية بهذا المجال.","يُذكر أن مستشفى الملك فيصل التخصصي ومركز الأبحاث صُنّف الأول في الشرق الأوسط وأفريقيا والـ12 عالمياً ضمن قائمة أفضل 250 مؤسسة رعاية صحية أكاديمية حول العالم لعام 2026، فضلاً عن كونه العلامة التجارية الصحية الأعلى قيمة في المملكة والشرق الأوسط وفق تصنيف «براند فاينانس» لعام 2026، كما أُدرج ضمن قوائم مجلة «نيوزويك» لأفضل المستشفيات في العالم وأفضل المستشفيات الذكية وأفضل المستشفيات المتخصصة لعام 2026."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/3kcxwq0','https://sabq.org/article/3kcxwq0','','https://sabq.org/article/3kcxwq0','صحيفة سبق','الرياض','2026-09-03T06:02:00.000Z','2026-09-03T09:04:00.000Z','2026-09-03T20:31:02.688Z','https://media.sabq.org/news/2026/09/2813a010-a797-4f6d-9ff5-19b74effb3e3/w1600.webp','/api/media/75809ea0-20b6-4811-a5d3-88d955536542','/api/media/75809ea0-20b6-4811-a5d3-88d955536542?variant=thumbnail','«التخصصي» يستضيف مؤتمر الشرق الأوسط لجراحة القلب الروبوتية في الرياض',1600,1067,'valid','published','archived','valid',46,'eccfb1526375675b99dbaf31a0ff1af5f3c04718cd941fa3e2569b3f3c11da59','eeaea20f76491be71ee6cb0ea3d1bc11756f326b59688aac49fce83eb30b8bee','محدّث','2026-09-03T20:31:02.688Z','2026-10-07T20:24:32.772Z','','',0,0,'saudi_region','مهم',67,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس اللجنة العلمية للمؤتمر ونائب","الصحة العامة","التقنية والتحول الرقمي","الرياض","الشرق الأوسط"]','["رئيس اللجنة العلمية للمؤتمر ونائب","الصحة العامة","التقنية والتحول الرقمي","الشرق الأوسط"]','needs_review','below_category_threshold','[{"category":"المناطق","score":3},{"category":"التقنية","score":3},{"category":"الرياضة","score":1.5}]','Active','2026-10-07T19:43:42.328Z',200,65,0,'source_article_available','',NULL,NULL,'body:a988424529d5ad253d76b14ad9fa0d1e620f884d7d1e1603f1a32fc5b94b6719','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f5fc5aff-27bc-466a-9433-9152cbaf9f4a','news-f5fc5aff-27bc-466a-9433-9152cbaf9f4a','5161 جولة رقابية لمكافحة التستر التجاري في أغسطس تكشف 239 حالة اشتباه','5161 جوله رقابيه لمكافحه التستر التجاري في اغسطس تكشف 239 حاله اشتباه','نفَّذ البرنامج الوطني لمكافحة التستر التجاري 5161 جولة رقابية في مختلف مناطق المملكة خلال شهر أغسطس 2026، استناداً إلى الدلالات ومؤشرات الاشتباه بالتستر.','["واستهدفت الجولات التحقق من امتثال المنشآت التجارية وضبط جرائم ومخالفات نظام مكافحة التستر، وشملت أنشطة تجارية متعددة، أبرزها: البيع بالتجزئة للزهور والورود، ووكالات السفر والسياحة، والمطاعم ذات الخدمة، والبيع بالتجزئة للتمور، وزراعة نباتات الزينة والشتلات «المشاتل»، والبيع بالتجزئة لأصناف العبايات النسائية والفراء.","وأسفرت الجولات عن ضبط 239 حالة اشتباه أولية بالتستر، وأُحيل المخالفون إلى الجهات المختصة للتحقق وتطبيق العقوبات الرادعة بحقهم.","وتتضمن عقوبات نظام مكافحة التستر السجن مدةً تصل إلى خمس سنوات، وغرامة مالية تبلغ حتى خمسة ملايين ريال، فضلاً عن حجز الأموال غير المشروعة ومصادرتها بعد صدور أحكام قضائية نهائية بحق المتورطين.","وتشمل العقوبات التبعية المقررة نظاماً: إغلاق المنشأة، وتصفية النشاط، وشطب السجل التجاري، والمنع من مزاولة النشاط التجاري، واستيفاء الزكاة والرسوم والضرائب، والتشهير، وإبعاد المتستَر عليهم عن المملكة وحظر عودتهم إليها للعمل."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/iqb8jdv','https://sabq.org/article/iqb8jdv','','https://sabq.org/article/iqb8jdv','صحيفة سبق','','2026-09-03T05:25:00.000Z','2026-09-03T08:25:00.000Z','2026-09-03T20:31:03.055Z','https://media.sabq.org/news/2026/09/06186f39-540e-49f3-86c3-65e5eb0d4ff6/w665.webp','/api/media/f5fc5aff-27bc-466a-9433-9152cbaf9f4a','/api/media/f5fc5aff-27bc-466a-9433-9152cbaf9f4a?variant=thumbnail','5161 جولة رقابية لمكافحة التستر التجاري في أغسطس تكشف 239 حالة اشتباه',665,350,'valid','published','archived','valid',40,'4151c6e2c9af9c98dee25e767a176c7ab6c8c68ef3be173e6442b870d5df7bfc','0f68db6a66c275fae67dab3103c29095c644ffaf290757978d37b4d217279eb2','محدّث','2026-09-03T20:31:03.055Z','2026-10-07T20:24:32.775Z','','',0,0,'saudi_national','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة"]','["السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"التقنية","score":1.5},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:42.914Z',200,66,0,'source_article_available','',NULL,NULL,'body:f74acd744eccf928401b80febfc167ced3fa4c75ebb90fff3cb04949b5f0acc5','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('99034098-bd88-4ec8-ba8b-377fcc256a93','news-99034098-bd88-4ec8-ba8b-377fcc256a93','التعاونية للتأمين تعلن إطلاقها الرسمي لـ "  شهاب “  لقيادة منظومة التنقل المتكاملة في المملكة','التعاونيه للتامين تعلن اطلاقها الرسمي لـ شهاب لقياده منظومه التنقل المتكامله في المملكه','في خطوةٍ استراتيجية تعكس توجهات التحول في قطاع التنقل وخدمات المركبات بالمملكة، أعلنت شركة التعاونية للتأمين عن إطلاق " شهاب" الشركة التابعة لها، كمنظومة متكاملة ومبتكرة تهدف إلى إعادة تعريف تجربة التنقل عبر توفير جميع احتياجات العملاء المتعلقة بالمركبات من خلال منصة واحدة.','["ويجسّد هذا الإطلاق التزام \"شهاب\" بتقديم نموذج شامل يغطي مختلف مراحل دورة حياة المركبة، بدءًا من البحث عن السيارة وشرائها، مرورًا باستخدامها وإدارتها، وصولًا إلى صيانتها والعناية بها.","وتسعى المنظومة إلى تقديم تجربة أكثر سلاسة وكفاءة، بما يعزز مستويات الراحة والثقة ويوفر قيمة مضافة للأفراد وقطاع الأعمال على حدٍ سواء.","وبهذه المناسبة، صرّح أ.وليد العنزي، الرئيس التنفيذي لشركة \"شهاب\"، قائلاً:\" يمثل هذا الإطلاق الرّسمي محطة مهمّة في مسيرة \"شهاب\"، ويؤكد التزامنا بتقديم مفهوم جديد لخدمات التنقل في المملكة العربية السعودية.","نحن فخورون بإطلاق منظومة متكاملة صُممت لتبسيط رحلة العميل مع السيارة في كلّ مرحلة، من البداية إلى النهاية، عبر تجربة رقمية مُوحّدة وسهلة الاستخدام تجمع مختلف الخدمات في مكان واحد\".","وأضاف:\"تأتي شهاب لتكون الشريك الموثوق لتلبية جميع احتياجات التنقل، من خلال حلولٍ متكاملة تشمل خدمات الإصلاح، والمساعدة على الطريق، وشبكة مراكز الإصلاح، وقطع الغيار، إلى جانب خدمات التنقل الحديثة مثل سوق السيارات، وتأجير المركبات، والتمويل، وحلول التنقل للشركات، بما يعزّز طموحنا في أن نكون الخيار الأول لكلّ من يحتاج إلى سيارة، أو يستخدمها، أو يعتني بها\".","عبدالله أباحسين، رئيس مجلس إدارة شركة \"شهاب\"، قائلاً:\"يسرّنا الإعلان عن الإطلاق الرّسمي لشركة \"شهاب\"، والذي يمثل تتويجًا لرؤية طموحة تستهدف بناء منظومة تنقل متكاملة في المملكة.","فشهاب ليست مُجرّد منصّة لتقديم خدمات منفصلة، بلْ نموذجٌ شاملٌ يربط بين منظومة التأمين وخدمات المركبات والتنقل تحت مظلّة واحدة، بما يسهم في خلق قيمة مضافة حقيقية للعملاء ومزودي الخدمات والشركاء\".","وأضاف: \"من خلال هذه الخطوة، نؤكد التزامنا بقيادة منظومة التنقل في المملكة، وأن تكون شهاب الخيار الأول لتلبية جميع احتياجات التنقل، مستندين إلى ما تتمتع به من قاعدة قوية من الثقة والخبرة باعتبارها شركة تابعة للتعاونية للتأمين، الأمر الذي يعزّز قدرتها على تقديم حلول رقمية مبتكرة ترتقي بتجربة العملاء وتواكب تطلعات السوق السعودي المتنامية\"."]','السيارات','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/yw9dnez','https://sabq.org/article/yw9dnez','','https://sabq.org/article/yw9dnez','صحيفة سبق','المنطقة الشرقية','2026-09-03T05:30:00.000Z','2026-09-03T08:30:00.000Z','2026-09-03T20:31:03.115Z','https://media.sabq.org/news/2026/09/e10c7863-3e84-4960-b5c8-8814580df150/w1600.webp','/api/media/99034098-bd88-4ec8-ba8b-377fcc256a93','/api/media/99034098-bd88-4ec8-ba8b-377fcc256a93?variant=thumbnail','التعاونية للتأمين تعلن إطلاقها الرسمي لـ "  شهاب “  لقيادة منظومة التنقل المتكاملة في المملكة',1600,1600,'valid','published','archived','valid',52,'8022754d162fba962ce602671d9d0ee93eee4280c026232847f349d88088aea4','d381348b0636c6b8a2a5b88e9655c5a2fe1ef986a4251317dbe1af6422f7a516','محدّث','2026-09-03T20:31:03.115Z','2026-10-07T20:24:32.779Z','','',0,0,'saudi_region','عادي',58,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس إدارة شركة شهاب","مجلس إدارة شركة شهاب قائلا","شركة التعاونية للتأمين عن إطلاق","التقنية والتحول الرقمي"]','["رئيس مجلس إدارة شركة شهاب","مجلس إدارة شركة شهاب قائلا","شركة التعاونية للتأمين عن إطلاق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"التقنية","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T19:43:51.457Z',200,67,0,'source_article_available','',NULL,NULL,'body:2d0196111a9b61ddbebddc263beabbb7e5e1786d8d945460ea8a36a7568b3a5c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c237815d-21fa-466b-ad58-f53360a858c2','news-c237815d-21fa-466b-ad58-f53360a858c2','HONOR تكشف عن أول هاتف روبوتي في العالم Robot Phone خلال LEAP 2026 من أجل حقبة جديدة من صناعة الأفلام السينمائية عبر الهواتف المحمولة والذكاء الاصطناعي المتجسد','honor تكشف عن اول هاتف روبوتي في العالم robot phone خلال leap 2026 من اجل حقبه جديده من صناعه الافلام السينمائيه عبر الهواتف المحموله والذكاء الاصطناعي المتجسد','كشفت HONOR، العلامة الرائدة عالمياً في الأجهزة المدعومة بالذكاء الاصطناعي، عن هاتف HONOR Robot Phone خلال مؤتمر LEAP 2026. ويُعد الهاتف جهازاً ثورياً يؤسس لفئة جديدة بالكامل، حيث يتجاوز الحدود المادية التقليدية لتقنيات الهواتف المحمولة من خلال دمج غيمبال ميكانيكي ثلاثي المحاور مزود بمحركات متكاملة مباشرة ضمن تصميم هاتف ذكي من الطراز الرفيع.','["كشفت HONOR، العلامة الرائدة عالمياً في الأجهزة المدعومة بالذكاء الاصطناعي، عن هاتف HONOR Robot Phone خلال مؤتمر LEAP 2026.","ويُعد الهاتف جهازاً ثورياً يؤسس لفئة جديدة بالكامل، حيث يتجاوز الحدود المادية التقليدية لتقنيات الهواتف المحمولة من خلال دمج غيمبال ميكانيكي ثلاثي المحاور مزود بمحركات متكاملة مباشرة ضمن تصميم هاتف ذكي من الطراز الرفيع.","كما يجمع بين عناصر مختارة من تقنيات ARRI Image Science وسير العمل الاحترافي المستخدم في الإنتاج السينمائي، ليتجاوز مفهوم الهاتف الذكي التقليدي ويؤدي دور رفيق ذكي فعّال واستوديو متكامل للإنتاج الإبداعي المتنقل.","أول هاتف ذكي في القطاع مزود بغيمبال مرن من التيتانيوم بأربع درجات الحرية يدمج HONOR Robot Phone نظاماً ميكانيكياً فائق الصغر بأربع درجات الحرية (4-DoF) يعتمد على غيمبال HONOR Titanium Agile Gimbal.","وقد تم تطوير هذا النظام عبر 60 عملية تصنيع مختلفة، ويضم أكثر من 100 مكون عالي الدقة، مدعوماً بأكثر من 100 براءة اختراع.","وبالمقارنة مع مثبتات الحركة التقليدية الرائجة في السوق، نجحت HONOR في تقليص حجم النظام الإجمالي بنسبة 65% مع تعزيز متانته الهيكلية بنسبة 200%.","ويتيح محرك Titanium Gimbal Motor، الذي لا يتجاوز وزنه 2.6 غرام، سرعات تحكم تصل إلى 360 درجة في الثانية، فيما يوفر محرك HONOR Super Steel Flip Motor كثافة عزم دوران تبلغ 120 N·m/L.","وتعمل هذه التقنيات معاً على توفير حركة سريعة ودقيقة وتموضع مستقر، ضمن تصميم رائد يمكن حمله بسهولة في الجيب."]','الذكاء الاصطناعي','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/66tpudd','https://sabq.org/article/66tpudd','','https://sabq.org/article/66tpudd','صحيفة سبق','المدينة المنورة','2026-09-03T05:45:00.000Z','2026-09-03T08:46:00.000Z','2026-09-03T20:31:03.203Z','https://media.sabq.org/news/2026/09/5f13323e-04fc-4868-a5dd-8465f26f6055/w1600.webp','/api/media/c237815d-21fa-466b-ad58-f53360a858c2','/api/media/c237815d-21fa-466b-ad58-f53360a858c2?variant=thumbnail','HONOR تكشف عن أول هاتف روبوتي في العالم Robot Phone خلال LEAP 2026 من أجل حقبة جديدة من صناعة الأفلام السينمائية عبر الهواتف المحمولة والذكاء الاصطناعي المتجسد',1600,1066,'valid','published','archived','valid',51,'01f2c7c6806762c18621ff8f937c919f23e311877e0897967eb1d083701b1b5f','2995a37adf216193f30b240ff38f1cd3387ab15e4fc049891aa31c26853b3484','محدّث','2026-09-03T20:31:03.203Z','2026-10-07T20:24:32.783Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون"]','["الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:43.548Z',200,64,0,'source_article_available','',NULL,NULL,'body:499698946e6c9cdc7a5469089fd873b7c42e55bcf287f7bb8c9ed93e85c3ec15','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fef98bd3-166f-4c66-8241-106cdae10bd5','news-fef98bd3-166f-4c66-8241-106cdae10bd5','«خيرات» تطلق حملة «حوّل الهدر إلى أجر» في شوارع الرياض','خيرات تطلق حمله حول الهدر الي اجر في شوارع الرياض','أطلقت جمعية خيرات لحفظ النعمة حملة توعوية بعنوان «حوّل الهدر إلى أجر مع خيرات»، انطلقت الأربعاء وتستمر لمدة أسبوع، وتُنفَّذ عبر الشاشات الإعلانية في شوارع مدينة الرياض وميادينها، إلى جانب عدد من المواقع خارج المنطقة.','["وتأتي الحملة بالتعاون مع أمانة منطقة الرياض وشركة ريمات الرياض للتنمية، وبرعاية العربية للإعلانات الخارجية، في نموذج يجسّد تكامل الجهود بين الجهات الحكومية والقطاع الخاص والقطاع غير الربحي لدعم المبادرات التوعوية.","وتهدف الحملة إلى إيصال رسالة واضحة مفادها أن فائض الطعام يمكن أن يتحول من هدر إلى منفعة وأجر، من خلال المحافظة على النعمة وإيصال الفائض الصالح للاستهلاك إلى المستفيدين عبر القنوات النظامية والآمنة التي تعمل من خلالها الجمعية.","وأكد الرئيس التنفيذي لجمعية خيرات لحفظ النعمة عبدالله السبيعي أن الحملة تأتي ضمن سلسلة مبادرات توعوية مستمرة تنفذها الجمعية بهدف ترسيخ ثقافة حفظ النعمة والحد من الهدر الغذائي.","وقال السبيعي: «نحرص في جمعية خيرات على استمرار رسائلنا التوعوية للوصول إلى مختلف شرائح المجتمع، وتعزيز الوعي بأهمية حفظ النعمة والتعامل المسؤول مع فائض الغذاء.","وتحمل حملة «حوّل الهدر إلى أجر» رسالة موجزة في مضمونها وعميقة في أثرها، فكل فائض يمكن الاستفادة منه هو فرصة لحفظ النعمة وصناعة أثر إيجابي يعود بالنفع على المجتمع».","وأشار السبيعي إلى أن نجاح مثل هذه الحملات يعتمد على تكامل الجهود والشراكات الفاعلة، مثمّناً التعاون مع أمانة منطقة الرياض وشركة ريمات الرياض للتنمية، والرعاية المقدمة من العربية للإعلانات الخارجية، مؤكداً دور هذه الشراكات في إيصال الرسالة التوعوية إلى نطاق أوسع من أفراد المجتمع.","وتندرج الحملة ضمن جهود الجمعية المتواصلة في نشر ثقافة حفظ النعمة وتعزيز المسؤولية المجتمعية تجاه الغذاء، والمساهمة في الحد من الهدر والاستفادة من فائض الطعام، بما يعزز قيم التكافل والعطاء والاستدامة في المجتمع."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/5chk4kp','https://sabq.org/article/5chk4kp','','https://sabq.org/article/5chk4kp','صحيفة سبق','الرياض','2026-09-03T04:56:00.000Z','2026-09-03T07:56:00.000Z','2026-09-03T20:31:03.615Z','https://media.sabq.org/news/2026/09/21fcdaae-03c2-4006-bca0-f8231f47f609/w1280.webp','/api/media/fef98bd3-166f-4c66-8241-106cdae10bd5','/api/media/fef98bd3-166f-4c66-8241-106cdae10bd5?variant=thumbnail','«خيرات» تطلق حملة «حوّل الهدر إلى أجر» في شوارع الرياض',1280,854,'valid','published','archived','valid',85,'2444198b2ca28eb6afeb4e0fb4ddcf076d08d18c7760923ed7713223f67d4777','313045c6d3a13fc257718023ccdfbdc1dd6f68665dec1609c7173e7911a75018','محدّث','2026-09-03T20:31:03.615Z','2026-10-07T19:43:50.501Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","الرياض"]','["الثقافة والفنون"]','classified','','[{"category":"المجتمع","score":4.5},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:43:50.501Z',200,66,0,'source_article_available','',NULL,NULL,'body:abd6c0220283fe94d9f17b066034dbdc6e48b1dfe8d2012174d1f4d3f280a12e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cb8c7adb-0a3d-4177-9694-035f8cbc85b6','news-cb8c7adb-0a3d-4177-9694-035f8cbc85b6','على هامش LEAP 2026.. «لين» تعزّز الابتكار الرقمي الصحي باتفاقيتين مع «تيتكو» و «تحكم»','علي هامش leap 2026 لين تعزز الابتكار الرقمي الصحي باتفاقيتين مع تيتكو و تحكم','وفي إطار الاتفاقية مع شركة "تيتكو" يستكشف الطرفان فرصًا للتعاون بين قطاعي التعليم والصحة، تجمع خبرات تيتكو في تصميم وتطوير وتشغيل المنصات والأنظمة الوطنية للقطاع التعليمي، مع خبرات "لين" في الحلول الرقمية وخدمات الأعمال وأتمتة الإجراءات في القطاع الصحي.','["وقّعت شركة لين لخدمات الأعمال، إحدى شركات صندوق الاستثمارات العامة والرائد الوطني في تمكين التحوّل الصحي الرقمي، اتفاقيتي تعاون مع كل من شركة تطوير لتقنيات التعليم (تيتكو) والشركة السعودية للتحكم التقني والأمني الشامل (تحكم)، بهدف استكشاف فرص توظيف الخبرات والقدرات التقنية الوطنية لتطوير حلول ومبادرات رقمية مبتكرة تُسهم في تعزيز كفاءة منظومة الصحة وتطوير خدماتها.","وتشمل مجالات التعاون البحث والابتكار والتحوّل الرقمي، والذكاء الاصطناعي والتحليلات المتقدمّة، والأمن السيبراني، إلى جانب تطوير الحلول والمنصات الرقمية وتشغيلها.","أما مذكرة التفاهم مع \"تحكم\"، فتركّز على استكشاف فرص تطوير حلول ومبادرات مبتكرة في الصحة الرقمية، وتكامل الخبرات والقدرات التقنية لدى الطرفين بما يُسهم في رفع الكفاءة التشغيلية، وتعزيز جودة الخدمات، وتطوير تجربة المستفيد.","وعلّق المهندس مهند بن عبدالله الرشيد، الرئيس التنفيذي لشركة لين: \"تفتح شراكاتنا مع تطوير لتقنيات التعليم وتحكم آفاقًا جديدة لتكامل الخبرات والقدرات التقنية الوطنية، وتطوير حلول توظّف البيانات والتقنيات الحديثة والذكاء الصحي، بما يُثري كفاءة منظومة الصحة ويقدم خدمات أكثر ارتباطًا باحتياجات الإنسان\".","وتأتي الاتفاقيتان امتدادًا لتوجه \"لين\" نحو توسيع نطاق الابتكار الصحي، وبناء شراكات وطنية تجمع الخبرات والقدرات من مختلف القطاعات لتطوير حلول رقمية ذات أثر مستدام، والمساهمة في تشكيل مستقبل الصحة في المملكة بما يواكب مستهدفات رؤية السعودية 2030.","عن لين شركة لين لخدمات الأعمال، إحدى شركات صندوق الاستثمارات العامة، والرائد الوطني في تمكين التحوّل الصحي الرقمي، تعمل على تطوير حلول ومنتجات رقمية مبتكرة تُسهم في بناء منظومة صحية أكثر كفاءة وترابطًا، من خلال توظيف البيانات والذكاء الاصطناعي والتقنيات الحديثة لخدمة الأفراد والممارسين والمنشآت الصحية، وتعزيز جودة الحياة ورفاهية الإنسان الصحية."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/12ka25t','https://sabq.org/article/12ka25t','','https://sabq.org/article/12ka25t','صحيفة سبق','المنطقة الشرقية','2026-09-03T05:00:00.000Z','2026-09-03T08:00:00.000Z','2026-09-03T20:31:03.631Z','https://media.sabq.org/news/2026/09/a1fb9344-9df1-4b37-af23-cf0907adab79/w1280.webp','/api/media/cb8c7adb-0a3d-4177-9694-035f8cbc85b6','/api/media/cb8c7adb-0a3d-4177-9694-035f8cbc85b6?variant=thumbnail','على هامش LEAP 2026.. «لين» تعزّز الابتكار الرقمي الصحي باتفاقيتين مع «تيتكو» و «تحكم»',1280,854,'valid','published','archived','valid',55,'1f3133604488cf2d03d6231010c1f886eb9cde8349ab75bb2d4d634c75436db8','6f9311a1309306f953dddfcc261c7aa031468b51293ca1c2369d6b9d344c7945','محدّث','2026-09-03T20:31:03.631Z','2026-10-07T19:43:43.700Z','','',0,0,'saudi_region','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة لين لخدمات الأعمال إحدى","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["شركة لين لخدمات الأعمال إحدى","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":4},{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":0}]','Active','2026-10-07T19:43:43.700Z',200,66,0,'source_article_available','',NULL,NULL,'body:6f75b2325ca498d2b1861b1d6b589c1561fe1864df0cc74e5c86f56aac334a0a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5d23d996-b49c-4aa8-a51d-8d2335443c72','news-5d23d996-b49c-4aa8-a51d-8d2335443c72','هيئة الطرق تصنّف مرافق مواقف المركبات إلى ثلاثة أنواع رئيسة','هيئه الطرق تصنف مرافق مواقف المركبات الي ثلاثه انواع رئيسه','أوضحت الهيئة العامة للطرق أن كود الطرق السعودي يصنّف مرافق مواقف المركبات إلى ثلاثة أنواع رئيسة، استنادًا إلى مواقعها وتصاميمها، بهدف تنظيمها ومواءمة تخطيطها مع طبيعة الطرق والمنشآت واحتياجات المستخدمين.','["وبيّنت الهيئة أن التصنيف يشمل المواقف الواقعة على الطريق، وهي المساحات المخصصة لوقوف المركبات على جانبي الطريق، والمواقف الواقعة خارج الطريق، التي تُنشأ كمرافق مستقلة بعيدًا عن مسار الطريق، مثل الساحات المخصصة لاستيعاب المركبات خارج الحركة المرورية المباشرة، إضافةً إلى المواقف متعددة الطوابق التي تُنفذ داخل مبانٍ أو منشآت فوق سطح الأرض أو تحتها لتوفير مساحات منظمة لوقوف المركبات.","وأكدت الهيئة أن كود الطرق السعودي يُعد مرجعًا فنيًا شاملًا لجميع الجهات المسؤولة عن قطاع الطرق في المملكة، مثل الوزارات وهيئات تطوير المدن وأمانات المناطق وبلديات المدن والمحافظات. ويتيح الكود لهذه الجهات الوصول إلى المعلومات والإرشادات والرسومات الفنية والإجراءات وقوائم التدقيق اللازمة لتخطيط الطرق وتصميمها وتنفيذها وتشغيلها وصيانتها، مع مراعاة الاشتراطات البيئية ومتطلبات السلامة لتحقيق معايير الجودة والكفاءة الاقتصادية والاستدامة.","وأشارت الهيئة إلى أن كود الطرق السعودي يسهم في تحقيق إستراتيجيتها الهادفة إلى بناء منظومة تشريعية وتنظيمية موحدة لقطاع الطرق، من خلال توحيد المعايير الفنية والتشغيلية على مستوى المملكة. ويساعد ذلك الجهات المالكة للطرق على رفع جودة أعمالها بشكل منهجي ومستدام، عبر معايير شاملة تغطي دورة حياة الطريق من التصميم والإنشاء وصولًا إلى التشغيل والصيانة المستمرة.","وفي السياق ذاته، أكدت الهيئة سعيها لتوفير منظومة تشريعية وتنظيمية موحدة وشفافة تضمن تكامل السياسات وتحقيق الامتثال التنظيمي، عبر تطبيق آليات رقابية مرنة ومحكمة تكفل الالتزام بالأنظمة والتشريعات. كما أشارت إلى مواصلة التوسع في تطبيق المعايير الفنية الحديثة لتحسين تجربة مستخدمي الطرق وتحقيق أعلى مستويات السلامة والكفاءة والاستدامة، انسجامًا مع مستهدفات برنامج قطاع الطرق."]','أخبار السعودية','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/b1y60swhr','https://ajel.sa/local/b1y60swhr','https://ajel.sa/local/b1y60swhr','https://ajel.sa/local/b1y60swhr','فريق التحرير','','2026-09-03T06:08:00.000Z','Wed, 07 Oct 2026 19:43:51 GMT','2026-09-03T20:31:03.891Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000964769-crop-LY0ovXze.jpg','/api/media/5d23d996-b49c-4aa8-a51d-8d2335443c72','/api/media/5d23d996-b49c-4aa8-a51d-8d2335443c72?variant=thumbnail','هيئة الطرق تصنّف مرافق مواقف المركبات إلى ثلاثة أنواع رئيسة',1200,675,'valid','published','archived','valid',40,'2aa05f9442109b285f44c9ac251a12afa00f66ca3a353a36a957183516adb745','6cd8c60f7bcacdcc1cec9db7440bd47d77a4378917c0f1c1f3e5a99d000705bc','محدّث','2026-09-03T20:31:03.891Z','2026-10-07T19:43:52.604Z','','',0,0,'saudi_national','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","هيئة الطرق تصن ف مرافق","الاقتصاد والأسواق"]','["هيئة الطرق تصن ف مرافق","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:43:52.604Z',200,68,0,'source_content_changed','',NULL,NULL,'body:31519d9e62bb73064d61e89e838b6a84ab02bcf5829246c8d54915847ca2f8f7','Wed, 07 Oct 2026 19:43:51 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4f20924f-888c-448d-a091-dbfcc6572fbf','news-4f20924f-888c-448d-a091-dbfcc6572fbf','NHC Innovation و"STC " توقّعان شراكة استراتيجية للتعاون في الحلول السحابية','nhc innovation و stc توقعان شراكه استراتيجيه للتعاون في الحلول السحابيه','وتشمل الشراكة بحث الاستفادة من إمكانات مزودي خدمات الحوسبة السحابية العالميين، إلى جانب دراسة تطوير حلول سحابية من خلال مراكز بيانات NHC Innovation، بما يدعم بناء بنية تحتية رقمية متقدمة وقابلة للتوسع.','["وقّعت NHC Innovation شراكة استراتيجية مع شركة الاتصالات السعودية \"stc\"، على هامش مؤتمر \"ليب 2026\"، بهدف استكشاف فرص التعاون في الحلول السحابية وتطوير البنية التحتية الرقمية.","ووقّع الشراكة من جانب NHC Innovation المهندس مروان الزامل، الرئيس التنفيذي للقطاع الرقمي، ومن جانب \"stc\" الأستاذ فيصل البكري، نائب الرئيس للمبيعات وتطوير الأعمال.","وتهدف مجالات التعاون إلى دعم تطوير الخدمات الرقمية في القطاعين العقاري والبلدي، ورفع كفاءتها التشغيلية، وتعزيز قدرتها على مواكبة النمو في الاحتياجات التقنية والخدمات السحابية.","ويأتي توقيع الشراكة ضمن مشاركة NHC Innovation في مؤتمر \"ليب 2026\" بصفتها شريك تقنيات المستقبل والابتكار، وفي إطار توجهها نحو توسيع شراكاتها التقنية وتطوير منظومة رقمية تدعم تقديم خدمات أكثر كفاءة."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ip69o9o','https://sabq.org/article/ip69o9o','','https://sabq.org/article/ip69o9o','صحيفة سبق','','2026-09-03T05:16:00.000Z','2026-09-03T08:17:00.000Z','2026-09-03T20:31:03.900Z','https://media.sabq.org/news/2026/09/951b1a26-3a1e-4487-ac56-aa96a9c48fc1/w1600.webp','/api/media/4f20924f-888c-448d-a091-dbfcc6572fbf','/api/media/4f20924f-888c-448d-a091-dbfcc6572fbf?variant=thumbnail','NHC Innovation و"STC " توقّعان شراكة استراتيجية للتعاون في الحلول السحابية',1600,900,'valid','published','archived','valid',54,'d16268d201ff89297dcbd9a0a21edaa7b3e57697e6415a1cbe29042f7651ab65','225387e32c0fca194ffa94ca34b662fec9294e1816cfe590e80605024a18f37e','محدّث','2026-09-03T20:31:03.900Z','2026-10-07T19:43:43.522Z','','',0,0,'saudi_national','عادي',61,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة الاتصالات السعودية stc على","التقنية والتحول الرقمي"]','["شركة الاتصالات السعودية stc على","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:43.522Z',200,66,0,'source_article_available','',NULL,NULL,'body:c8aed4884b74eb10ab02f5d6763844cd0a1b33ce9f943403a40014136828bafe','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bd065150-2641-4460-a496-5d96632235c9','news-bd065150-2641-4460-a496-5d96632235c9','السفير بن بيشان: العلاقات السعودية العُمانية ركيزة لدعم التعاون الخليجي','السفير بن بيشان العلاقات السعوديه العمانيه ركيزه لدعم التعاون الخليجي','وأوضح السفير أن العلاقات السعودية العُمانية امتداد لتاريخ طويل من الأخوة وحسن الجوار والاحترام المتبادل، حيث تميزت خلال نصف قرن بالتعاون والتفاهم والتنسيق المستمر بين القيادتين حيال مختلف القضايا الإقليمية والدولية.','["أكد سفير خادم الحرمين الشريفين لدى سلطنة عمان ، إبراهيم بن سعد بن بيشان، أن العلاقات بين المملكة العربية السعودية وسلطنة عُمان تمثل ركيزة أساسية في دعم منظومة مجلس التعاون لدول الخليج العربية، وتعكس التزام البلدين بتعزيز الاستقرار الإقليمي وتنسيق المواقف السياسية والاقتصادية بما يخدم مصالح شعوب المنطقة.","وجاء تصريح السفير بن بيشان بمناسبة الزيارة التي قام بها جلالة السلطان هيثم بن طارق ، سلطان عمان، إلى المملكة، مشيرًا إلى أن الزيارة تؤكد عمق العلاقات التاريخية والأخوية الراسخة بين البلدين والشعبين الشقيقين، وما تحظى به هذه العلاقات من رعاية واهتمام من القيادة في البلدين.","وأشار بن بيشان إلى أن الزيارة تحمل دلالات مهمة في ظل المتغيرات والتحديات التي تشهدها المنطقة، إذ تمثل العلاقات بين البلدين نموذجًا للعلاقات الخليجية القائمة على الحوار والتفاهم والتنسيق، بما يعزز أمن واستقرار المنطقة ويدعم مسارات التنمية والازدهار.","وأضاف أن العلاقات الثنائية لا تقتصر على الجانب السياسي فقط، بل تشمل مجالات الاقتصاد والاستثمار والتجارة والسياحة والثقافة والإعلام.","وبيّن السفير أن العلاقات بين البلدين تتجه نحو مرحلة جديدة من الشراكة المستقبلية، تشمل الطاقة النظيفة والهيدروجين الأخضر، ومشروعات الربط الكهربائي والربط السككي الخليجي، إضافة إلى المبادرات السياحية المشتركة لتطوير المقاصد السياحية من خلال برامج تبادل وخطط تسويقية مشتركة."]','أخبار السعودية','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/vcnm2ayqy','https://ajel.sa/local/vcnm2ayqy','https://ajel.sa/local/vcnm2ayqy','https://ajel.sa/local/vcnm2ayqy','فريق التحرير','المدينة المنورة','2026-09-03T06:12:00.000Z','Wed, 07 Oct 2026 19:43:48 GMT','2026-09-03T20:31:03.996Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000964772-crop-I-BhnWh6.jpg','/api/media/bd065150-2641-4460-a496-5d96632235c9','/api/media/bd065150-2641-4460-a496-5d96632235c9?variant=thumbnail','السفير بن بيشان: العلاقات السعودية العُمانية ركيزة لدعم التعاون الخليجي',1200,675,'valid','published','archived','valid',92,'a1cdae30f4488baee083794218a10c7a207f587adbd0342cf11a4b319859f4a0','623243257a8e147fa50f5cd41baf19339bd1e41418682ed5e1fc7b37a5581b3e','محدّث','2026-09-03T20:31:03.996Z','2026-10-07T19:43:49.918Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","خادم الحرمين الشريفين لدى سلطنة","مجلس التعاون لدول الخليج العربية","الطاقة والنفط","السفر والسياحة","الثقافة والفنون","الاقتصاد والأسواق","الخليج العربي"]','["خادم الحرمين الشريفين لدى سلطنة","مجلس التعاون لدول الخليج العربية","الطاقة والنفط","السفر والسياحة","الثقافة والفنون","الاقتصاد والأسواق"]','classified','','[{"category":"الطاقة والصناعة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:43:49.918Z',200,63,0,'source_content_changed','',NULL,NULL,'body:7df718583a8273353d77338df49c837dd782a3e16bab4de6147bbcd158cc2476','Wed, 07 Oct 2026 19:43:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('66058988-1b95-4533-be2b-2308fe799085','news-66058988-1b95-4533-be2b-2308fe799085','ماذا يعني تحويل البحر الأحمر إلى «ثلاثي الأبعاد»؟.. تقنية تراقب الوجهة لحظة بلحظة وتغيّر تجربة السائح','ماذا يعني تحويل البحر الاحمر الي ثلاثي الابعاد تقنيه تراقب الوجهه لحظه بلحظه وتغير تجربه السائح','لم يعد استخدام الخرائط ثلاثية الأبعاد في الوجهات السياحية مقتصرًا على مشاهدة المباني والجزر بشكل مجسّم، إذ كشفت مجموعة stc والبحر الأحمر الدولية خلال مؤتمر LEAP 2026 في الرياض عن نظام أكثر تطورًا يحوّل أجزاء من وجهات البحر الأحمر إلى ما يشبه نسخة رقمية حية تتحرك وتتغير بالتزامن مع ما يحدث على أرض الواقع.','["والتقنية المستخدمة تعرف باسم «التوأم الرقمي – Digital Twin»، وتعني إنشاء نموذج افتراضي ثلاثي الأبعاد للوجهة الحقيقية، ثم ربط هذا النموذج ببيانات مباشرة قادمة من أجهزة الاستشعار والأنظمة التشغيلية، بحيث لا يشاهد المستخدم مجرد خريطة ثابتة، وإنما صورة رقمية محدثة باستمرار لما يحدث في الموقع.","ويغطي النظام الذي تم استعراضه في «ليب 2026» مناطق تشمل جزيرة شورى وتيرتل باي، مع مراقبة عالية الدقة لنحو 10 كيلومترات مربعة، ويجمع بين صور الأقمار الصناعية والنماذج ثلاثية الأبعاد والبيانات المباشرة المتعلقة بالمباني والمركبات والبيئة والبحر.","الفكرة ببساطة أن المسؤول عن الوجهة يستطيع مشاهدة نموذج ثلاثي الأبعاد للمكان، وفي الوقت نفسه يعرف ما يجري داخله فعليًا.","فمن خلال منصة العمليات الذكية Nucleus يمكن متابعة حركة الزوار والمركبات، وحالة المنشآت، ومؤشرات البيئة وجودة الهواء ودرجات الحرارة وسرعة الرياح وحالة البحر، إضافة إلى متابعة المناطق البحرية المحيطة بالوجهة.","وعندما يتغير أحد المؤشرات عن مستواه الطبيعي، يمكن للنظام إصدار تنبيه بشكل آلي.","وبذلك يصبح النموذج الثلاثي الأبعاد بمثابة غرفة عمليات رقمية للوجهة بأكملها، وليس مجرد صورة تجميلية أو خريطة سياحية.","السائح سيستفيد أيضًا الأمر لن يقتصر على إدارات التشغيل؛ إذ تخطط «البحر الأحمر الدولية» لدمج النظام في موقعها الإلكتروني، بما يسمح للزائر باستكشاف الوجهة بصورة ثلاثية الأبعاد قبل الوصول إليها، والتعرف على الأنشطة المتاحة وتلقي توصيات ترتبط بالظروف الفعلية في الموقع، مع إمكانية الانتقال إلى الحجز مباشرة.","وهذا يعني أن السائح قد يستطيع مستقبلًا، قبل مغادرة غرفته أو حتى قبل السفر، مشاهدة الجزيرة التي سيزورها ومعرفة الظروف البحرية أو الجوية الحالية واختيار النشاط الأنسب في ذلك التوقيت."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7fjfu99','https://sabq.org/article/7fjfu99','','https://sabq.org/article/7fjfu99','خالد خليل','الرياض','2026-09-03T04:31:00.000Z','2026-09-03T07:32:00.000Z','2026-09-03T20:31:04.322Z','https://media.sabq.org/news/2026/09/60be5ded-29df-472d-b948-d9b66cb1d64c/w1536.webp','/api/media/66058988-1b95-4533-be2b-2308fe799085','/api/media/66058988-1b95-4533-be2b-2308fe799085?variant=thumbnail','ماذا يعني تحويل البحر الأحمر إلى «ثلاثي الأبعاد»؟.. تقنية تراقب الوجهة لحظة بلحظة وتغيّر تجربة السائح',1536,1024,'valid','published','archived','valid',52,'339b6672fc41d12bb34785969b83b5ac555cc0a9dca18a2104717d5423905e3c','c2edfe8f0c19830ddcc34a8f39bc7f8b51aeb96835ecbb7c2aa858a2b1fbd8ae','محدّث','2026-09-03T20:31:04.322Z','2026-10-07T19:43:48.181Z','','',0,0,'saudi_region','عادي',49,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي","الرياض"]','["الطقس والمناخ","السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:43:48.181Z',200,69,0,'source_article_available','',NULL,NULL,'body:eb5586efeea21e05412bb57c5c293b99a8506ffc1f43dd0084cc6272fde2b0b3','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('24a2a296-6edc-4175-8b93-19e4a6cafdcc','news-24a2a296-6edc-4175-8b93-19e4a6cafdcc','5 مخاطر يومية أكثر فتكًا للبشر من الطائرات.. وهذه الأرقام تكشف المفاجأة','5 مخاطر يوميه اكثر فتكا للبشر من الطائرات وهذه الارقام تكشف المفاجاه','وبحسب الأرقام التي استعرضها الأحمدي، تأتي خمسة مخاطر في مقدمة ما يفوق حوادث الطيران من حيث احتمالات الوفاة أو التعرض للخطر، وهي: التدخين، حيث أشار إلى أن احتمال الوفاة المرتبط به يصل إلى نحو واحد من كل 200 مدخن.','["رغم أن حوادث الطائرات تحظى عادة باهتمام واسع وتثير حالة كبيرة من الخوف بين المسافرين، فإن احتمالات الوفاة في عدد من المواقف والمخاطر اليومية قد تكون أعلى بكثير من احتمال الموت في حادث جوي.","وتكشف المقارنات التي أوردها الكاتب والإعلامي السعودي فهد عامر الأحمدي أن السفر بالطائرة، رغم ما يحيط به من رهبة، يظل أقل خطورة من مجموعة من الممارسات والحوادث التي قد يتعرض لها الإنسان بصورة شبه يومية.","قيادة السيارات وحوادث الطرق، وهي من أكثر أسباب الوفاة انتشارًا، مع احتمالات تفوق السفر الجوي بفارق كبير.","العمليات الجراحية، إذ أورد أن احتمال الوفاة داخل غرفة العمليات أعلى من احتمالات الوفاة في حادث طائرة.","السقوط من السلالم أو الانزلاق داخل الحمام، وهي حوادث تبدو بسيطة، إلا أن احتمالات الوفاة الناتجة عنها قد تزيد عدة مرات على حوادث الطيران.","المخاطر اليومية والحوادث العرضية المختلفة، التي يتعرض لها الأشخاص بصورة متكررة دون أن تحظى بالخوف نفسه المرتبط بركوب الطائرات.","وأشار الأحمدي إلى أن المفارقة تكمن في أن حجم الخوف من الطائرات لا يعكس دائمًا الحجم الحقيقي للمخاطر، خصوصًا أن حوادث الطيران نادرة مقارنة بعدد الرحلات الضخم الذي يتم تشغيله سنويًا حول العالم.","وأوضح أن عدد المسافرين جوًا ارتفع بصورة كبيرة منذ ثمانينيات وتسعينيات القرن الماضي، فيما استمرت معدلات السلامة الجوية في التحسن، ولم ترتفع أعداد الضحايا بالنسبة نفسها التي ارتفع بها عدد الركاب والرحلات."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/008npre','https://sabq.org/article/008npre','','https://sabq.org/article/008npre','صحيفة سبق','','2026-09-03T04:19:00.000Z','2026-09-03T07:20:00.000Z','2026-09-03T20:31:04.498Z','https://media.sabq.org/news/2026/09/0e11dbbd-62c1-49c9-b663-4f7a77f3cf7b/w1024.webp','/api/media/24a2a296-6edc-4175-8b93-19e4a6cafdcc','/api/media/24a2a296-6edc-4175-8b93-19e4a6cafdcc?variant=thumbnail',' 5 مخاطر يومية أكثر فتكًا للبشر من الطائرات.. وهذه الأرقام تكشف المفاجأة',1024,682,'valid','published','archived','valid',45,'e68d7365054509aea9e8d7e1b4118eabd6f630974e28553a63fef8e208022f71','69f8f715af24c9d9ff3ec4d3384b32391b256d66c69d1964bfa81e7f8801fa21','محدّث','2026-09-03T20:31:04.498Z','2026-10-07T20:24:32.803Z','','',0,0,'international','عادي',45,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الثقافة والفنون"]','["السفر والسياحة","الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T19:43:44.686Z',200,65,0,'source_article_available','',NULL,NULL,'body:669edb47af00dafdbaacb16c2ceedd8cba69e23f7da8acda050a3b3c64ffec84','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4d84bb04-2713-48f0-9f74-321cc7e56dea','news-4d84bb04-2713-48f0-9f74-321cc7e56dea','«الجوازات» توضح كيفية تعديل الاسم المترجم للعمالة المنزلية عبر «أبشر»','الجوازات توضح كيفيه تعديل الاسم المترجم للعماله المنزليه عبر ابشر','أعلنت المديرية العامة للجوازات ، عن إتاحة خدمة تعديل الاسم المترجم للعمالة المنزلية عبر منصة أبشر. تتيح هذه الخدمة لصاحب العمل تعديل الاسم المترجم لأي عامل منزلي يعمل لديه بسهولة إلكترونيًا.','["وأوضحت «الجوازات»، عبر منصة «إكس»، أنه «يمكن لصاحب العمل الاستفادة من الخدمة من خلال تسجيل الدخول إلى منصة أبشر، ثم التوجه إلى قسم العمالة المنزلية، واختيار خدمات المقيمين، ثم تحديد المستفيد المطلوب، واختيار خيار تعديل الاسم المترجم».","وتشمل الخدمة تعديل الاسم المترجم باللغة الإنجليزية للمقيمين من الجنسيات العربية، وتعديل الاسم المترجم باللغة العربية للمقيمين من الجنسيات غير العربية."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/kjxyw4jmk','https://ajel.sa/thehour/kjxyw4jmk','https://ajel.sa/thehour/kjxyw4jmk','https://ajel.sa/thehour/kjxyw4jmk','فريق التحرير','','2026-09-03T06:02:00.000Z','Wed, 07 Oct 2026 19:43:52 GMT','2026-09-03T20:31:04.509Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%AC%D9%88%D8%A7%D8%B2%D8%A7%D8%AA-UK_KKHLu.jpg','/api/media/4d84bb04-2713-48f0-9f74-321cc7e56dea','/api/media/4d84bb04-2713-48f0-9f74-321cc7e56dea?variant=thumbnail','«الجوازات» توضح كيفية تعديل الاسم المترجم للعمالة المنزلية عبر «أبشر»',1200,675,'valid','published','archived','valid',41,'14185ec45bdd7869b4a8e5293ead2c0a5385d4d85a67df9c104cf81caeba5398','a7acb89d7d339b7b1087a60d8c5e2e1452d5a89f595790058729d462fccebded','محدّث','2026-09-03T20:31:04.509Z','2026-10-07T20:24:32.807Z','','',0,0,'international','عادي',31,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:43:53.613Z',200,66,0,'source_content_changed','',NULL,NULL,'body:9df45f4898d3e44da35d53a5182684c169a54af148f55cb0da30cfeb4763abf3','Wed, 07 Oct 2026 19:43:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6593b465-bc53-4e27-b8f6-75871dba0eb3','news-6593b465-bc53-4e27-b8f6-75871dba0eb3','وصول الدفعة الـ81 من العائدين الفلسطينيين إلى معبر رفح','وصول الدفعه الـ81 من العائدين الفلسطينيين الي معبر رفح','وصلت اليوم الدفعة (81) من العائدين الفلسطينيين لقطاع غزة، إلى معبر رفح البري من الجانب المصري، تمهيدًا لعودتهم إلى القطاع. وأفاد مصدر مسؤول بالمعبر أن فريقًا من الهلال الأحمر المصري استقبل العائدين الفلسطينيين لتيسير إجراءات عودتهم إلى قطاع غزة بالتنسيق مع الجهات المختصة، فيما تستقبل السلطات المصرية دفعة جديدة من الجرحى والمرضى الفلسطينيين من قطاع غزة،…','["وصلت اليوم الدفعة (81) من العائدين الفلسطينيين لقطاع غزة، إلى معبر رفح البري من الجانب المصري، تمهيدًا لعودتهم إلى القطاع."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/50060c3','https://sabq.org/article/50060c3','','https://sabq.org/article/50060c3','صحيفة سبق','','2026-09-03T04:15:00.000Z','2026-09-03T07:15:00.000Z','2026-09-03T20:31:04.514Z','https://imagedelivery.net/nU9Yamkp250UHNYBIVAE6w/cb44634a-bbd0-4bb7-cb96-ae1cfcd07900/public','/api/media/6593b465-bc53-4e27-b8f6-75871dba0eb3','/api/media/6593b465-bc53-4e27-b8f6-75871dba0eb3?variant=thumbnail','وصول الدفعة الـ81 من العائدين الفلسطينيين إلى معبر رفح',1000,666,'valid','published','archived','valid',42,'f8b32061e27fc72789e5410a12a356a5c0e971b8e510c573df2918cb1de79f49','c4579c4790aa6bdb2f166345a052507f194ae7bae06aa6f725a3052e0167a190','محدّث','2026-09-03T20:31:04.514Z','2026-10-07T20:24:32.809Z','','',0,0,'gulf_arab','عادي',51,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","غزة","فلسطين"]','["الصحة العامة"]','needs_review','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T19:43:51.387Z',200,66,0,'source_article_available','',NULL,NULL,'body:148fb5aafe78796a4d4fa3cdb8dd2d2f4f64b642e8b3f6cb9826f69f86aca55f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('37bfc13a-0bb4-4a61-aaf4-25a17e173525','news-37bfc13a-0bb4-4a61-aaf4-25a17e173525','إحباط تهريب 37 كيلو جراما من الحشيش المخدر بعسير','احباط تهريب 37 كيلو جراما من الحشيش المخدر بعسير','أحبطت الدوريات البرية لحرس الحدود في قطاع ظهران الجنوب ، ب منطقة عسير ، تهريب 37 كيلو جراما من مادة الحشيش المخدر بعسير. وتهيب الجهات الأمنية بالإبلاغ عن كل ما يتوافر من معلومات لدى المواطنين والمقيمين عن أي نشاطات ذات صلة بتهريب أو ترويج المخدرات، وذلك من خلال الاتصال بالأرقام (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض و الشرقية و(999) و(994)…','["أحبطت الدوريات البرية لحرس الحدود في قطاع ظهران الجنوب ، ب منطقة عسير ، تهريب 37 كيلو جراما من مادة الحشيش المخدر بعسير.","وقالت \"حرس الحدود\" عبر حسابها على منصة \"إكس\"، إنه جرى استكمال الإجراءات النظامية الأولية، وتسليم المضبوطات لجهة الاختصاص.","وتهيب الجهات الأمنية بالإبلاغ عن كل ما يتوافر من معلومات لدى المواطنين والمقيمين عن أي نشاطات ذات صلة بتهريب أو ترويج المخدرات، وذلك من خلال الاتصال بالأرقام (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض و الشرقية و(999) و(994) في بقية مناطق المملكة، ورقم بلاغات المديرية العامة لمكافحة المخدرات (995)، وعبر البريد الإلكتروني: (Email: [email&#160;protected] )، وستعالج جميع البلاغات بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/29o6534q3','https://ajel.sa/local/29o6534q3','https://ajel.sa/local/29o6534q3','https://ajel.sa/local/29o6534q3','فريق التحرير','الرياض','2026-09-03T06:02:00.000Z','Wed, 07 Oct 2026 19:43:43 GMT','2026-09-03T20:31:04.548Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/IMG-%D9%A2%D9%A0%D9%A2%D9%A6%D9%A0%D9%A9%D9%A0%D9%A3-%D9%A1%D9%A3%D9%A2%D9%A4%D9%A1%D9%A0-l4p1YhMt.jpg','/api/media/37bfc13a-0bb4-4a61-aaf4-25a17e173525','/api/media/37bfc13a-0bb4-4a61-aaf4-25a17e173525?variant=thumbnail','إحباط تهريب 37 كيلو جراما من الحشيش المخدر بعسير',1200,675,'valid','published','archived','valid',40,'719591063eb3eb062de78212d02fc63d113a34c02da488c8c1656cc70bc273d4','343626e2c74fcf14dc0dd5bc43773eb7223e6a257251e6785ec78c15a2e4c53e','محدّث','2026-09-03T20:31:04.548Z','2026-10-07T20:24:32.811Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","مكة","عسير","الرياض","المدينة المنورة"]','["الرياضة السعودية","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:43:45.496Z',200,65,0,'source_content_changed','',NULL,NULL,'body:d19201e3ec1ea4213739f92261f081e5b662e123f2fa3e697ed0a401e500da30','Wed, 07 Oct 2026 19:43:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3bab1236-56cd-4474-b77d-ff163c21d09b','news-3bab1236-56cd-4474-b77d-ff163c21d09b','ضبط مقيمين يمنيين خالفا نظام البيئة لاستغلال الرواسب في المدينة المنورة','ضبط مقيمين يمنيين خالفا نظام البيئه لاستغلال الرواسب في المدينه المنوره','ضبطت القوات الخاصة للأمن البيئي مقيمين من الجنسية اليمنية مخالفين لنظام البيئة، لاستغلالهما الرواسب في منطقة المدينة المنورة. وأوضحت القوات أنه جرى ضبط معدتين تُستخدمان في تجريف ونقل التربة، ضمن الجهود الرامية لحماية الموارد الطبيعية ومكافحة التعديات البيئية.','["ضبطت القوات الخاصة للأمن البيئي مقيمين من الجنسية اليمنية مخالفين لنظام البيئة، لاستغلالهما الرواسب في منطقة المدينة المنورة.","وأوضحت القوات أنه جرى ضبط معدتين تُستخدمان في تجريف ونقل التربة، ضمن الجهود الرامية لحماية الموارد الطبيعية ومكافحة التعديات البيئية.","وأضافت الجهات المختصة أنه تم تطبيق الإجراءات النظامية بحق المخالفين وفق الأنظمة المعمول بها.","وحثت القوات الخاصة للأمن البيئي على الإبلاغ عن أي حالات تمثل اعتداءً على البيئة أو الحياة الفطرية من خلال الأرقام (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض و المنطقة الشرقية ، و(999) و(996) في بقية مناطق المملكة ، مؤكدة أن جميع البلاغات ستعامل بسرية تامة دون تحميل المبلّغ أي مسؤولية."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/x42ozmanx','https://ajel.sa/local/x42ozmanx','https://ajel.sa/local/x42ozmanx','https://ajel.sa/local/x42ozmanx','فريق التحرير','الرياض','2026-09-03T06:05:00.000Z','Wed, 07 Oct 2026 19:43:47 GMT','2026-09-03T20:31:04.561Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%A3%D9%85%D9%86-%D8%A7%D9%84%D8%A8%D9%8A%D8%A6%D9%8A-4sUsfw4O.jpg','/api/media/3bab1236-56cd-4474-b77d-ff163c21d09b','/api/media/3bab1236-56cd-4474-b77d-ff163c21d09b?variant=thumbnail','ضبط مقيمين يمنيين خالفا نظام البيئة لاستغلال الرواسب في المدينة المنورة',1200,675,'valid','published','archived','valid',46,'6f8b1836640f493a46d52aadc23587c27d12e947a56b7e143f4beeb49e80691d','6b8eeb275a575286c18a472c6a43db1aaaf699ff76de3e92c9a69f9090c666b7','محدّث','2026-09-03T20:31:04.561Z','2026-10-07T20:24:32.814Z','','',0,0,'saudi_region','عادي',46,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","اليمن","الرياض","المدينة المنورة"]','["المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:43:48.563Z',200,67,0,'source_content_changed','',NULL,NULL,'body:f7caba0167d1312f66f73b29bba39d04f6b7d8707ec74e01c8809c3fe7b32d41','Wed, 07 Oct 2026 19:43:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('da811bfc-d481-4b36-8930-0baf51c06758','news-da811bfc-d481-4b36-8930-0baf51c06758','اختتام النسخة الأولى من مبادرة «البحث الصيفي الدولي في الأمن السيبراني»','اختتام النسخه الاولي من مبادره البحث الصيفي الدولي في الامن السيبراني','اختتمت الهيئة الوطنية للأمن السيبراني أعمال النسخة الأولى من مبادرة «البحث الصيفي الدولي في الأمن السيبراني»، الهادفة إلى تمكين الكفاءات البحثية الواعدة في مجالات الأمن السيبراني ذات الأولوية الوطنية، وتنمية المهارات البحثية والابتكارية المتقدمة في المجال، بما يسهم في تعزيز المعرفة السيبرانية لمواكبة التطورات العالمية، وفتح آفاق أوسع لتطوير الأبحاث…','["وشهدت المبادرة التي نُفذت على مدار 10 أسابيع بالتعاون مع جامعة \"كارنيجي ميلون\" في الولايات المتحدة الأمريكية ، إجراء عدد من الأبحاث الواعدة التي ركزت على الأمن السيبراني في الذكاء الاصطناعي، والتطورات التقنية الحالية والمستقبلية في مجال الأمن السيبراني، وغيرها من المشروعات البحثية، كما تضمنت عقد جلسات إرشادية أسبوعية، وورش عمل متخصصة؛ وذلك تحت إشراف نخبة من الباحثين والخبراء من أعضاء هيئة التدريس في جامعة \"كارنيجي ميلون\".","وتأتي مبادرة البحث الصيفي الدولي في الأمن السيبراني، ضمن «البرنامج الوطني للبحث والتطوير والابتكار في الأمن السيبراني» وفي إطار مبادرات الهيئة الإستراتيجية الرامية إلى تنمية قطاع الأمن السيبراني على المستوى الوطني، حيث تتيح المبادرة فرص الالتحاق في برامج البحث الصيفي لدى أبرز الجامعات العالمية الرائدة في مجالات الأمن السيبراني، والمشاركة في تطوير المشروعات البحثية والابتكارية في المجال."]','التقنية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/5inmga2zf','https://ajel.sa/local/5inmga2zf','https://ajel.sa/local/5inmga2zf','https://ajel.sa/local/5inmga2zf','فريق التحرير','المدينة المنورة','2026-09-03T06:02:00.000Z','Wed, 07 Oct 2026 19:43:48 GMT','2026-09-03T20:31:05.561Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000928998-crop-i-xLvuZK-crop-SmJO50x-OWLQMtyn.jpg','/api/media/da811bfc-d481-4b36-8930-0baf51c06758','/api/media/da811bfc-d481-4b36-8930-0baf51c06758?variant=thumbnail','اختتام النسخة الأولى من مبادرة «البحث الصيفي الدولي في الأمن السيبراني»',1200,675,'valid','published','archived','valid',41,'f288f884b73e2c42172b06e954844e9e2539bb4a74241c9d4a427a765d42cb80','a994ea441443eb175c9e40123c1b533aa553910fe733e4e4c8a9d3658533bd41','محدّث','2026-09-03T20:31:05.561Z','2026-10-07T20:24:32.816Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة التدريس في جامعة كارنيجي","جامعة كارنيجي ميلون في الولايات","التعليم والتدريب","التقنية والتحول الرقمي","الولايات المتحدة"]','["هيئة التدريس في جامعة كارنيجي","جامعة كارنيجي ميلون في الولايات","التعليم والتدريب","التقنية والتحول الرقمي","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:43:49.904Z',200,64,0,'source_content_changed','',NULL,NULL,'body:5a8ce340dba47cb4e1e56e28ce0c5b2b958cd5250256a7f0102afc5c55ab268c','Wed, 07 Oct 2026 19:43:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0c2027aa-0eec-4d1e-a624-5decd9261b6a','news-0c2027aa-0eec-4d1e-a624-5decd9261b6a','الاحتلال الإسرائيلي يعتزم الإفراج عن 5 سجناء لبنانيين في إطار المفاوضات مع بيروت','الاحتلال الاسرائيلي يعتزم الافراج عن 5 سجناء لبنانيين في اطار المفاوضات مع بيروت','كشفت وسائل إعلام إسرائيلية أن دولة الاحتلال الإسرائيلي ستفرج عن 5 سجناء لبنانيين لإثبات (حسن النوايا) في إطار المفاوضات مع الحكومة اللبنانية. وكان قد أكد الرئيس اللبناني جوزيف عون أن بلاده مصممة على إنهاء حالة العداء مع إسرائيل عبر الحلول الدبلوماسية، وليس من خلال الحرب.','["كشفت وسائل إعلام إسرائيلية أن دولة الاحتلال الإسرائيلي ستفرج عن 5 سجناء لبنانيين لإثبات (حسن النوايا) في إطار المفاوضات مع الحكومة اللبنانية.","وكان قد أكد الرئيس اللبناني جوزيف عون أن بلاده مصممة على إنهاء حالة العداء مع إسرائيل عبر الحلول الدبلوماسية، وليس من خلال الحرب. جاء ذلك خلال لقائه الرئيس اليوناني كونستانتينوس تاسولاس في العاصمة أثينا .","وأوضح عون أن هدف التفاوض مع إسرائيل هو إنهاء العداء، مشيرًا إلى أن الشعب اللبناني أنهكته الحروب، وأن الاستقرار في لبنان يمثل عنصرًا أساسيًا لاستقرار المنطقة وأوروبا."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/9nq4wfdjs','https://ajel.sa/international/9nq4wfdjs','https://ajel.sa/international/9nq4wfdjs','https://ajel.sa/international/9nq4wfdjs','فريق التحرير','','2026-09-03T06:02:00.000Z','Wed, 07 Oct 2026 19:43:50 GMT','2026-09-03T20:31:05.647Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/19-2026-639211307546765659-676-pa4jDdn9.jpg','/api/media/0c2027aa-0eec-4d1e-a624-5decd9261b6a','/api/media/0c2027aa-0eec-4d1e-a624-5decd9261b6a?variant=thumbnail','الاحتلال الإسرائيلي يعتزم الإفراج عن 5 سجناء لبنانيين في إطار المفاوضات مع بيروت',1200,675,'valid','published','archived','valid',41,'598164be3dfe54ae3ad1e84aa7784e55178ee2599903c6364765938adda6318e','0464cf6ff7f6c65faf972db58555a7a0c4d9c379c4dcee85317355fabbf52224','محدّث','2026-09-03T20:31:05.647Z','2026-10-07T20:24:32.818Z','','',0,0,'gulf_arab','عادي',46,NULL,0,0,0,'',NULL,NULL,NULL,'["السياسة والعلاقات الدولية","لبنان","أوروبا"]','["السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:43:52.536Z',200,65,0,'source_content_changed','',NULL,NULL,'body:51329511095e54ae074209147eea5a4de13e4b764fac4033b35e32a4707effb9','Wed, 07 Oct 2026 19:43:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d64f20d5-3ed1-4c3c-b480-afd51e13ed3d','news-d64f20d5-3ed1-4c3c-b480-afd51e13ed3d','«الأرصاد»: المدينة المنورة الأعلى حرارة بـ44 مئوية.. وأبها الأدنى','الارصاد المدينه المنوره الاعلي حراره بـ44 مئويه وابها الادني','توقَّع المركز الوطني للأرصاد، درجات الحرارة الكبرى والصغرى، على بعض مدن المملكة؛ مشيرًا إلى أن المدينة المنورة تسجل أعلى درجة حرارة بـ 44 درجة مئوية، فيما تسجل أبها أدنى درجة حرارة بـ 19 درجة مئوية.','["وذكر مركز الأرصاد، عبر موقعه الرسمي، أن درجات الحرارة الكبرى المتوقعة اليوم، المدينة المنورة 44، الرياض ومكة المكرمة 43، جدة 38 درجة مئوية","وأضاف: كما تبلغ درجات الحرارة الكبرى على مدن الدمام 42، أبها 30، تبوك 38، بريدة 44، حائل 41، الباحة 28، عرعر و سكاكا 40، جازان 38، نجران 40 درجة مئوية.","وتابع: أما درجات الحرارة الصغرى على بعض المدن، فجاءت كالآتي: أبها 19، الباحة 22، الرياض والدمام والمدينة المنورة 30، مكة المكرمة 33، جدة 31، نجران 26، جازان 32، تبوك 25 درجة مئوية."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/vbydn6ifa','https://ajel.sa/local/vbydn6ifa','https://ajel.sa/local/vbydn6ifa','https://ajel.sa/local/vbydn6ifa','فريق التحرير','الرياض','2026-09-03T06:02:00.000Z','Wed, 07 Oct 2026 19:43:52 GMT','2026-09-03T20:31:06.168Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/ajel-2026-01-16-0xzry6v5-%D8%AF%D8%B1%D8%AC%D8%A7%D8%AA-%D8%A7%D9%84%D8%AD%D8%B1%D8%A7%D8%B1%D8%A9-1-Rhrr1ke8.jpg','/api/media/d64f20d5-3ed1-4c3c-b480-afd51e13ed3d','/api/media/d64f20d5-3ed1-4c3c-b480-afd51e13ed3d?variant=thumbnail','«الأرصاد»: المدينة المنورة الأعلى حرارة بـ44 مئوية.. وأبها الأدنى',1200,675,'valid','published','archived','valid',54,'f298a98fb78e7e5ef726fc968a09cc09f81bf954dbf4da6f45ea2535e7871c2c','13ec59f159a6b0ae81e2e6cc023ceb801cf67e161a43fc2f885979921ae42f20','محدّث','2026-09-03T20:31:06.168Z','2026-10-07T20:24:32.820Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة","جدة","تبوك","جازان","نجران","الرياض","الدمام"]','["الطقس والمناخ","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:43:53.623Z',200,67,0,'source_content_changed','',NULL,NULL,'body:b04fc317baf9e3e45f7db5f9e7cfd1c32dbffb28ec770f94d54a6f39a22170ce','Wed, 07 Oct 2026 19:43:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('22ac7b10-6c5e-4b24-b7f1-b420cc1494fa','news-22ac7b10-6c5e-4b24-b7f1-b420cc1494fa','هل يؤثر امتلاك منشأة على التسجيل في نظام التأمينات؟.. توضيح من «التأمينات الاجتماعية»','هل يؤثر امتلاك منشاه علي التسجيل في نظام التامينات توضيح من التامينات الاجتماعيه','وأوضحت التأمينات الاجتماعية أن امتلاك منشأة لا يتعارض مع التسجيل في نظام التأمينات الاجتماعية لدى منشأة أخرى في حال وجود علاقة عمل. وكانت المؤسسة العامة للتأمينات الاجتماعية حددت موقف المعاشات التقاعدية في حالة امتلاك السجل التجاري.','["حددت المؤسسة العامة للتأمينات الاجتماعية موقف مستفيدي التأمينات في حالة وجود منشأة لديهم وهل يؤثر ذلك على التسجيل في النظام.","وأوضحت التأمينات الاجتماعية أن امتلاك منشأة لا يتعارض مع التسجيل في نظام التأمينات الاجتماعية لدى منشأة أخرى في حال وجود علاقة عمل.","وكانت المؤسسة العامة للتأمينات الاجتماعية حددت موقف المعاشات التقاعدية في حالة امتلاك السجل التجاري.","وأوضحت التأمينات الاجتماعية أنه لا يؤثر وجود سجل تجاري في استحقاق المنفعة التقاعدية.","وقالت «التأمينات الاجتماعية» إن «عمل المستفيد في وظيفة خاضعة لنظام التأمينات الاجتماعية لا يؤثر في استحقاق المعاش التقاعدي في أنظمة التقاعد».","حذرت المؤسسة العامة للتأمينات الاجتماعية من محاولات الاحتيال وانتحال صفة موظفيها، داعيةً المستفيدين إلى عدم مشاركة بياناتهم الشخصية أو البنكية مع أي جهات أو أشخاص مجهولين.","وأكدت المؤسسة، في تدوينة عبر حسابها الرسمي على منصة «إكس»، أن موظفيها لا يطلبون من المستفيدين عبر الاتصال الهاتفي أي معلومات شخصية أو بنكية، بما في ذلك كلمات المرور أو رموز الدخول الخاصة بمنصة « نفاذ »."]','العقارات','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/60gpl846f','https://ajel.sa/thehour/60gpl846f','https://ajel.sa/thehour/60gpl846f','https://ajel.sa/thehour/60gpl846f','فريق التحرير','عسير','2026-09-03T06:02:00.000Z','Wed, 07 Oct 2026 19:43:52 GMT','2026-09-03T20:31:06.897Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%A7%D9%84%D8%AA%D8%A3%D9%85%D9%8A%D9%86%D8%A7%D8%AA-%D8%A7%D9%84%D8%A5%D8%AC%D8%AA%D9%85%D8%A7%D8%B9%D9%8A%D8%A9-E8ualn3W.png','/api/media/22ac7b10-6c5e-4b24-b7f1-b420cc1494fa','/api/media/22ac7b10-6c5e-4b24-b7f1-b420cc1494fa?variant=thumbnail','هل يؤثر امتلاك منشأة على التسجيل في نظام التأمينات؟.. توضيح من «التأمينات الاجتماعية»',1200,675,'valid','published','archived','valid',47,'745d1618aa1e1ce981ebe4b85161e42bf76a6a77a825a95322d2558d29be9e3a','4525f527f233628a9d1fbb6a21daa3fa7f5e79f9fcbd072bc20d17a5eb2ff860','محدّث','2026-09-03T20:31:06.897Z','2026-10-07T20:24:32.823Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["عسير"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:43:53.641Z',200,65,0,'source_content_changed','',NULL,NULL,'body:0a3a7d2959579cf437e0bc84154a1374b22fdd82bc3d4030de84bf80a15482a3','Wed, 07 Oct 2026 19:43:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1bf94443-1a38-4eb7-942e-91e1cfbf97a4','news-1bf94443-1a38-4eb7-942e-91e1cfbf97a4','دوريات الأمن بمنطقة تبوك تضبط مقيمين بنغاليين لممارستهما التسول','دوريات الامن بمنطقه تبوك تضبط مقيمين بنغاليين لممارستهما التسول','ضبطت دوريات الأمن بمنطقة تبوك مقيمين من الجنسية البنغلاديشية لممارستهما التسول، وأوقفا واتخذت الإجراءات النظامية بحقهما. وحثّ الأمن العام المتبرعين على توجيه تبرعاتهم عبر المنصات الرسمية المعتمدة بما يضمن وصولها إلى مستحقيها.','["ضبطت دوريات الأمن بمنطقة تبوك مقيمين من الجنسية البنغلاديشية لممارستهما التسول، وأوقفا واتخذت الإجراءات النظامية بحقهما.","وحثّ الأمن العام المتبرعين على توجيه تبرعاتهم عبر المنصات الرسمية المعتمدة بما يضمن وصولها إلى مستحقيها.","ويأتي ذلك ضمن الجهود التي تبذلها وزارة الداخلية ممثلة بالأمن العام، في مكافحة ظاهرة التسول بمختلف صورها وأشكالها."]','الثقافة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/2hxl3z6v4','https://ajel.sa/local/2hxl3z6v4','https://ajel.sa/local/2hxl3z6v4','https://ajel.sa/local/2hxl3z6v4','فريق التحرير','تبوك','2026-09-03T06:02:00.000Z','Wed, 07 Oct 2026 19:44:35 GMT','2026-09-03T20:31:07.024Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%A7%D9%85%D9%86-%D8%A7%D9%84%D8%B9%D8%A7%D9%85-JZt6V7uY-jvhHxjua.jpg','/api/media/1bf94443-1a38-4eb7-942e-91e1cfbf97a4','/api/media/1bf94443-1a38-4eb7-942e-91e1cfbf97a4?variant=thumbnail','دوريات الأمن بمنطقة تبوك تضبط مقيمين بنغاليين لممارستهما التسول',1200,675,'valid','published','archived','valid',41,'5b6fd3ec1bf7ecc3707ef6ee079969a1f14639957ec75e56f55fb15baec2bd43','9f631c4d1c2a7612561567377094d499ff00b5e7436feda86f4a42291334cd9e','محدّث','2026-09-03T20:31:07.024Z','2026-10-07T20:24:32.825Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية ممثلة بالأمن العام","الثقافة والفنون","الرياضة السعودية","تبوك"]','["وزارة الداخلية ممثلة بالأمن العام","الثقافة والفنون","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:44:37.526Z',200,69,0,'source_content_changed','',NULL,NULL,'body:115d3a277592720878963bb75285239d9d87d935e116f95256c26b2f4af13af8','Wed, 07 Oct 2026 19:44:35 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d18abfc0-47c0-45ea-bf66-09a62512e421','news-d18abfc0-47c0-45ea-bf66-09a62512e421','جمعية التنمية الأسرية في الأفلاج تحقق 99.25% في تقييم الحوكمة','جمعيه التنميه الاسريه في الافلاج تحقق 99 25 في تقييم الحوكمه','حققت جمعية التنمية الأسرية بمحافظة الأفلاج درجة 99.25% في تقييم الحوكمة، في إنجاز يعكس مستوى التميز المؤسسي الذي وصلت إليه الجمعية، وحرصها على تطبيق معايير الحوكمة والارتقاء بجودة الأداء وتعزيز كفاءة العمل المؤسسي.','["ويؤكد تحقيق هذه النسبة التزام الجمعية بمواصلة مسيرة التطوير والتحسين، وترسيخ الممارسات المؤسسية التي تعزز الشفافية والكفاءة والاستدامة، بما ينعكس إيجاباً على جودة البرامج والخدمات المقدمة للمستفيدين.","ويأتي هذا الإنجاز امتداداً لجهود الجمعية في تطوير منظومة أعمالها ورفع مستوى خدماتها وبرامجها، بما يسهم في تحقيق رسالتها المتمثلة في دعم الأسر نحو واقع أفضل ومستقبل مشرق، وتعزيز الاستقرار الاجتماعي والأسري في المحافظة.","وتواصل الجمعية تنفيذ حزمة متنوعة من البرامج والمشاريع الأسرية التي تستهدف مختلف شرائح المجتمع، من بينها: برامج الإرشاد الأسري، وتأهيل المقبلين على الزواج، والتوفيق بين راغبيه، وبرامج التدريب والتأهيل، وتنمية مهارات الشباب، إلى جانب المبادرات والأنشطة التوعوية والثقافية والاجتماعية."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ppg77iq','https://sabq.org/article/ppg77iq','','https://sabq.org/article/ppg77iq','صحيفة سبق','','2026-09-03T14:33:00.000Z','2026-09-03T17:33:00.000Z','2026-09-03T20:43:39.365Z','https://media.sabq.org/news/2026/09/b9df635f-ea65-4c4b-aed3-ec7fbe56d744/w1200.webp','/api/media/d18abfc0-47c0-45ea-bf66-09a62512e421','/api/media/d18abfc0-47c0-45ea-bf66-09a62512e421?variant=thumbnail','جمعية التنمية الأسرية في الأفلاج تحقق 99.25% في تقييم الحوكمة',1200,675,'valid','published','archived','valid',87,'624b0fb6fd0e29d4c6403f72d2edb991f7e595bfbac35c875391465161bd6868','1175fe0914c1f3897f7055b676a7f9a789ca15940f98ec144988f20b0ac98542','محدّث','2026-09-03T20:43:39.365Z','2026-10-07T20:27:04.626Z','','',0,0,'international','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','classified','','[{"category":"المناطق","score":4},{"category":"التقنية","score":1.5},{"category":"أخبار السعودية","score":0}]','Temporarily Unreachable','2026-10-07T20:27:04.626Z',NULL,49,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5868b973-2fa2-4bc2-a3ab-0e27c712e280','news-5868b973-2fa2-4bc2-a3ab-0e27c712e280','جمعية قسطرة القلب السعودية تطلق أعمال النسخة التاسعة من المؤتمر السعودي الدولي للقسطرة في الرياض','جمعيه قسطره القلب السعوديه تطلق اعمال النسخه التاسعه من المؤتمر السعودي الدولي للقسطره في الرياض','وأكد نائب رئيس جمعية قسطرة القلب السعودية الدكتور محمد المحمدي أن نسخة هذا العام تتميز بمواكبتها للمشاريع الوطنية، من خلال تعزيز الربط بين خبرات الجمعية والمؤسسات الوطنية، بما يسهم في تحقيق الأهداف المشتركة.','["أعلنت جمعية قسطرة القلب السعودية، خلال مؤتمر صحافي أُقيم في الرياض اليوم الخميس، عن انطلاق أعمال النسخة التاسعة من المؤتمر السعودي الدولي للقسطرة والتداخلات القلبية (SACIS)، الذي يستعرض أبرز المستجدات في مجال القسطرة والتداخلات القلبية، ويسلط الضوء على التطورات التقنية والعلمية الحديثة في التخصص، إلى جانب استعراض برنامج المؤتمر ومحاوره وأبرز فعالياته.","وبيّن أن المؤتمر يركز على جمع القيادات وأصحاب الخبرة وصنّاع القرار، لتبادل المعرفة ومناقشة التحديات وإيجاد حلول للمشكلات المشتركة، بما ينعكس إيجابًا على المستفيدين والمواطنين.","وأوضح الدكتور محمد المحمدي أن مواكبة أحدث التقنيات تمثل أولوية في مجال علاج أمراض القلب، مشددًا على أن حداثة التقنية لا تعني بالضرورة أنها الأكثر أمانًا، وأن اختيار التقنيات يجب أن يستند إلى مدى فائدتها للمريض وقدرتها على تحقيق قيمة حقيقية وتحسين النتائج العلاجية.","وأشار إلى أن استخدام الذكاء الاصطناعي في المجال الطبي يشهد تسارعًا كبيرًا، مؤكدًا أنه لا يمكن الاعتماد عليه بشكل كلي، وإنما يُستخدم كأداة مساعدة للطبيب. ولفت إلى أن هذه التقنيات، التي يجري العمل بها منذ سنوات، أصبحت حاضرة بصورة يومية في الممارسة الطبية، وأسهمت في تحسين النتائج، خصوصًا في العمليات، من خلال إتاحة قياسات دقيقة وشاملة داخل الأوعية الدموية، بما في ذلك الشرايين والأوردة، باستخدام تقنيات تصوير داخلية مدعومة بالذكاء الاصطناعي.","من جانبه، أكد رئيس اللجنة العلمية للمؤتمر الدكتور سالم عسيري أن النسخة التاسعة من المؤتمر تُعد الأضخم هذا العام، مشيرًا إلى أن البرنامج يجمع الخبرات المحلية والدولية تحت سقف واحد، مع تنوع كبير في المحاضرات وورش العمل والبرامج التدريبية، إلى جانب إجراء سبع عمليات نوعية متخصصة، من داخل وخارج المملكة، على الهواء مباشرة لأغراض تعليمية، ثلاث منها في الرياض وواحدة في جدة وأخرى في أبها ، ينفذها خبراء سعوديون، واثنتان من الولايات المتحدة الأمريكية.","وأوضح أن ما يميز نسخة هذا العام أيضاً إطلاق برنامج صناع القرار، إلى جانب تخصيص محاور موسعة للذكاء الاصطناعي وأحدث التقنيات في مجال التداخلات القلبية، مؤكدًا أهمية الانتقال من دور المتلقي إلى المشاركة الفاعلة في صناعة مستقبل التخصص والقرار الطبي.","وفيما يتعلق بالذكاء الاصطناعي، أكد أن الهدف منه ليس منافسة الأطباء، وإنما توظيف هذه التقنيات كعامل مساعد يرفع مستوى الدقة، خصوصًا في العمليات والقياسات، بما يخدم الممارسات الطبية ويحسن النتائج العلاجية."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/tfvs8e0st','https://ajel.sa/local/tfvs8e0st','https://ajel.sa/local/tfvs8e0st','https://ajel.sa/local/tfvs8e0st','فريق التحرير','الرياض','2026-09-03T14:47:00.000Z','Wed, 07 Oct 2026 21:20:42 GMT','2026-09-03T20:55:38.560Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000965340-crop-rdSfEmM8.jpg','/api/media/5868b973-2fa2-4bc2-a3ab-0e27c712e280','/api/media/5868b973-2fa2-4bc2-a3ab-0e27c712e280?variant=thumbnail','جمعية قسطرة القلب السعودية تطلق أعمال النسخة التاسعة من المؤتمر السعودي الدولي للقسطرة في الرياض',1200,675,'valid','published','archived','valid',50,'683c4a83f700d434a029a9bbf33e8af03bcab05214472b299afb0d273e8bc9e6','655032093dc3d92cbb7e6e90de7478d8c5654dc6fa84cbd34536303f85da9f18','محدّث','2026-09-03T20:55:38.560Z','2026-10-07T21:20:44.022Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس جمعية قسطرة القلب السعودية","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي","جدة","عسير","الرياض"]','["رئيس جمعية قسطرة القلب السعودية","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":3},{"category":"الطاقة والصناعة","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T21:20:44.022Z',200,60,0,'source_content_changed','',NULL,NULL,'body:68129b1b2baf328c479bf003991ab6b802bbda06020aef1ada103102f816265e','Wed, 07 Oct 2026 21:20:42 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6857c401-3d8a-4a1d-84a4-1ada90649f07','news-6857c401-3d8a-4a1d-84a4-1ada90649f07','ارتفاع أسعار النفط والذهب في التعاملات العالمية','ارتفاع اسعار النفط والذهب في التعاملات العالميه','ارتفعت أسعار النفط والذهب في تعاملات اليوم، مع تجدد التوترات العسكرية بين الولايات المتحدة وإيران، وتراجع الدولار وعوائد سندات الخزانة الأمريكية. واستفادت أسعار النفط من ارتفاع علاوة المخاطر المرتبطة بالإمدادات، فيما تلقى الذهب دعمًا من ضعف الدولار وانحسار توقعات رفع أسعار الفائدة الأمريكية.','["ارتفعت أسعار النفط والذهب في تعاملات اليوم، مع تجدد التوترات العسكرية بين الولايات المتحدة وإيران، وتراجع الدولار وعوائد سندات الخزانة الأمريكية.","وصعدت العقود الآجلة لخام برنت بنسبة (1.1%) إلى نحو (96.70) دولارًا للبرميل، بعدما لامست (97.60) دولارًا خلال الجلسة، وهو أعلى مستوى لها في ستة أسابيع.","واستفادت أسعار النفط من ارتفاع علاوة المخاطر المرتبطة بالإمدادات، فيما تلقى الذهب دعمًا من ضعف الدولار وانحسار توقعات رفع أسعار الفائدة الأمريكية."]','الطاقة والصناعة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ZD6G76s','https://sabq.org/article/ZD6G76s','','https://sabq.org/article/ZD6G76s','صحيفة سبق','','2026-09-03T14:50:00.000Z','2026-09-03T17:50:00.000Z','2026-09-03T21:01:39.537Z','https://media.sabq.org/news/2026/09/9d7daa44-d03e-4ec6-aaf7-6b4226be3bf5/w1600.webp','/api/media/6857c401-3d8a-4a1d-84a4-1ada90649f07','/api/media/6857c401-3d8a-4a1d-84a4-1ada90649f07?variant=thumbnail','ارتفاع أسعار النفط والذهب في التعاملات العالمية',1600,893,'valid','published','archived','valid',35,'00e6c57a4d2bd08e55da2f4603036b5ca7053ba32109b21f7c9315952566c487','e6538dbf2b165f4e8e72701808acf9ad2c8963c1d544f830e7f23a732e4d2483','محدّث','2026-09-03T21:01:39.537Z','2026-10-07T20:24:32.834Z','','',0,0,'international','عادي',56,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الاقتصاد والأسواق","إيران","الولايات المتحدة"]','["الطاقة والنفط","الاقتصاد والأسواق","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:26:21.687Z',200,53,0,'source_article_available','',NULL,NULL,'body:79e80d4aca84a4f8b8aa43055e47af92f305c52556fa34c377e78992552c6dde','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a2ed0523-18ff-4ecf-a48a-fa3ac559497e','news-a2ed0523-18ff-4ecf-a48a-fa3ac559497e','التجارب الحرة ترفع جاهزية السائقين في الجولة الثانية من بطولة السعودية تويوتا كسر الزمن','التجارب الحره ترفع جاهزيه السائقين في الجوله الثانيه من بطوله السعوديه تويوتا كسر الزمن','وانطلق برنامج الجولة ظهر أمس عند الساعة الثانية بإجراءات التدقيق الإداري والفحص الفني للسيارات المشاركة، للتأكد من استيفاء المتطلبات الفنية ومعايير السلامة المعتمدة، بالتزامن مع جولة التعرف على المسار. وبلغ عدد المسجلين في الجولة الثانية 88 متسابقاً ومتسابقة، ضمن 11 فئة، إلى جانب كأس السيدات.','["اختتمت مساء أمس الخميس فعاليات اليوم الأول من الجولة الثانية لبطولة السعودية تويوتا كسر الزمن 2026، التي تقام على حلبة كورنيش جدة، بإشراف الاتحاد السعودي للسيارات والدراجات النارية، بصفته الجهة المالكة للبطولة، وبإدارة باخشب لرياضة المحركات، وبالشراكة مع جميل لرياضة المحركات، الشريك الرسمي للبطولة.","وانطلق برنامج الجولة ظهر أمس عند الساعة الثانية بإجراءات التدقيق الإداري والفحص الفني للسيارات المشاركة، للتأكد من استيفاء المتطلبات الفنية ومعايير السلامة المعتمدة، بالتزامن مع جولة التعرف على المسار.","وبلغ عدد المسجلين في الجولة الثانية 88 متسابقاً ومتسابقة، ضمن 11 فئة، إلى جانب كأس السيدات.","وتواصل البرنامج بعقد الاجتماع الإلزامي للسائقين عند الساعة الخامسة مساءً، بحضور مسؤولي السباق والحكام، قبل أن تنطلق التجارب الحرة عند الساعة السادسة مساءً، بواقع جلسة واحدة لكل فئة.","وشكلت التجارب فرصة للسائقين لاختبار أداء سياراتهم على المسار، وتقييم جاهزيتهم، وإجراء التعديلات اللازمة استعداداً لمنافسات الجمعة.","وتتواصل منافسات الجولة اليوم الجمعة بانطلاق السباق الأول عند الساعة الرابعة عصراً، يليه السباق الثاني عند الساعة السابعة والربع مساءً، حيث يسعى كل متسابق إلى تسجيل أفضل زمن ممكن، فيما يُحدد ترتيب الفائزين في كل فئة وفق أسرع زمن يُسجل خلال جلستي السباق، وتُختتم منافسات الجولة الثانية بإعلان الترتيب النهائي عند الساعة الحادية عشرة ليلاً يليه حفل التتويج وتكريم الفائزين في مختلف الفئات.","وتكتسب الجولة الثانية أهمية خاصة مع دخول البطولة النصف الثاني من موسمها المكوّن من ثلاث جولات، إذ تمثل محطة جديدة للمتسابقين لتعزيز نتائجهم ومواصلة المنافسة، قبل الانتقال إلى الجولة الثالثة والأخيرة المقررة على حلبة كورنيش جدة يومي 15 و16 أكتوبر المقبل."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/Peab4Lb','https://sabq.org/article/Peab4Lb','','https://sabq.org/article/Peab4Lb','صحيفة سبق','مكة المكرمة','2026-09-03T15:07:00.000Z','2026-09-03T18:07:00.000Z','2026-09-03T21:13:39.458Z','https://media.sabq.org/news/2026/09/e0843c58-0d0a-406f-a951-b2d3262ba5f8/w1600.webp','/api/media/a2ed0523-18ff-4ecf-a48a-fa3ac559497e','/api/media/a2ed0523-18ff-4ecf-a48a-fa3ac559497e?variant=thumbnail','التجارب الحرة ترفع جاهزية السائقين في الجولة الثانية من بطولة السعودية تويوتا كسر الزمن',1600,1067,'valid','published','archived','valid',44,'c60377b67f9e46fb79a860cc369fca82114b2e01f2d7ef941f17d1da2f849677','9ad772efa28723406afadc8fe8a462580aabdd0409cdc53f2c62c19a5b96c6b6','محدّث','2026-09-03T21:13:39.458Z','2026-10-07T19:36:05.623Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","جدة"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الرياضة","score":3},{"category":"المناطق","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:36:05.623Z',200,59,0,'source_article_available','',NULL,NULL,'body:9f1911ff7d64f7f3b549b5197b0077f8cc1a8e995bfc94e65f1ef9a7987a9da4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('71a12862-bb55-4212-8605-2bbb18eb2d2c','news-71a12862-bb55-4212-8605-2bbb18eb2d2c','المملكة وسلطنة عُمان.. علاقة أخوية راسخة ومستقبل واعد','المملكه وسلطنه عمان علاقه اخويه راسخه ومستقبل واعد','وقد تجاوزت هذه العلاقات في مسيرتها الممتدة نصف قرن، اتسمت خلالها بالتميز والتعاون والتفاهم، والتنسيق المستمر بين القيادتين حيال مختلف القضايا الإقليمية والدولية.','["تأتي زيارة جلالة السلطان هيثم بن طارق، سلطان عُمان، إلى المملكة العربية السعودية، لتؤكد عمق العلاقات التاريخية والأخوية الراسخة التي تجمع البلدين والشعبين الشقيقين، وما تحظى به هذه العلاقات من رعاية واهتمام من خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز، وصاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز، ولي العهد رئيس مجلس الوزراء، والسلطان هيثم بن طارق -حفظهم الله ورعاهم. العلاقات السعودية العُمانية ليست وليدة الظروف، وإنما هي امتداد لتاريخ طويل من الأخوة وحسن الجوار والاحترام المتبادل، وروابط اجتماعية وثقافية متجذرة بين الشعبين الشقيقين. وقد تجاوزت هذه العلاقات في مسيرتها الممتدة نصف قرن، اتسمت خلالها بالتميز والتعاون والتفاهم، والتنسيق المستمر بين القيادتين حيال مختلف القضايا الإقليمية والدولية.","وقد دعمت هذه العلاقات زيارات متبادلة رفيعة المستوى، من أبرزها زيارة السلطان هيثم بن طارق إلى المملكة في يونيو 2021م، والتي كانت أول زيارة خارجية لجلالته بعد توليه مقاليد الحكم، تلبيةً لدعوة أخيه خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز -حفظهما الله ورعاهما- وأسفرت الزيارة عن إنشاء مجلس التنسيق السعودي العُماني ليكون إطارًا مؤسسيًا لتعزيز التعاون بين البلدين في مختلف المجالات. كما جاءت الزيارة الرسمية لسيدي صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز، ولي العهد رئيس مجلس الوزراء -حفظه الله- إلى سلطنة عُمان في ديسمبر 2021م، ثم زيارته الخاصة في سبتمبر 2023م، لتؤكد عمق التنسيق المشترك، وتعزيز التشاور حول القضايا الإقليمية والدولية، ودعم أمن المنطقة واستقرارها.","ويستند كذلك إلى اللقاءات الثنائية والدولية والمباحثات المستمرة بين وزيري الخارجية في البلدين، صاحب السمو الأمير فيصل بن فرحان بن عبدالله، ومعالي السيد بدر بن حمد البوسعيدي، إلى جانب اللقاءات المتواصلة بين أصحاب السمو والمعالي الوزراء والمسؤولين في مختلف المجالات، بما يعكس مستوى متقدمًا من التفاهم والتنسيق، ويمهد لمستقبل أكثر تكاملاً يخدم مصالح البلدين والشعبين الشقيقين.","وتحمل زيارة السلطان هيثم بن طارق إلى المملكة دلالات مهمة في ظل ما تشهده المنطقة من متغيرات وتحديات، إذ تمثل العلاقات السعودية العُمانية نموذجًا للعلاقات الخليجية القائمة على الحوار والتفاهم والتنسيق، بما يعزز أمن واستقرار المنطقة، ويدعم مسارات التنمية والازدهار.","ولا تقتصر العلاقات بين البلدين على الجانب السياسي، بل تتجاوز ذلك إلى آفاق أوسع تشمل الاقتصاد والاستثمار والتجارة والسياحة والثقافة والإعلام، بما يفتح المجال أمام مرحلة جديدة من الشراكة والتكامل، ويعزز المصالح المشتركة للشعبين الشقيقين.","وتمضي العلاقات السعودية العُمانية اليوم قدمًا في مسار من التعاون والبناء المشترك والتقارب والتكامل الإستراتيجي في مختلف المجالات. ويأتي تأسيس مجلس التنسيق السعودي العُماني ليكون إطارًا مؤسسيًا فاعلاً لتفعيل التعاون المشترك ومتابعة المشاريع والمبادرات بين البلدين، بما في ذلك المبادرات المنبثقة عن رؤية السعودية 2030 ورؤية عُمان 2040، وبما يسهم في تحقيق التكامل الاقتصادي والتنمية المستدامة.","كما تمثل العلاقة بين المملكة وسلطنة عُمان ركيزة أساسية في دعم منظومة مجلس التعاون لدول الخليج العربية، وتعكس التزام البلدين بتعزيز الاستقرار الإقليمي، وتنسيق المواقف السياسية والاقتصادية، بما يخدم مصالح شعوب المنطقة.","وتحظى سلطنة عُمان باهتمام كبير من المملكة العربية السعودية، حيث تم افتتاح مكتب لصندوق الاستثمارات العامة السعودي بهدف تحديد الفرص الاستثمارية المناسبة، ومساعدة شركات محفظة الصندوق والشركاء من القطاع الخاص على التوسع في الأسواق العُمانية."]','أخبار السعودية','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264266','https://www.okaz.com.sa/articles/authors/2264266','','https://www.okaz.com.sa/articles/authors/2264266','إبراهيم بن سعد بن بيشان','المدينة المنورة','2026-09-03T14:49:00.000Z','Wed, 07 Oct 2026 19:43:59 GMT','2026-09-03T22:43:34.961Z','https://www.okaz.com.sa/okaz/uploads/authors/1920.jpg?v=1788459426','/api/media/71a12862-bb55-4212-8605-2bbb18eb2d2c','/api/media/71a12862-bb55-4212-8605-2bbb18eb2d2c?variant=thumbnail','المملكة وسلطنة عُمان.. علاقة أخوية راسخة ومستقبل واعد',259,400,'valid','published','archived','valid',99,'103eae6d7364ca89ab87b8380979f9fb85a8091591db66d086ec034b95d04025','3504ca869dd4321762f74b6cb132353f0230149c4268ee15aa45fb3cb87b7b29','محدّث','2026-09-03T22:43:34.961Z','2026-10-07T19:44:01.624Z','','',0,0,'saudi_region','مهم',79,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء والسلطان هيثم بن","رئيس مجلس الوزراء والسلطان هيثم","خادم الحرمين الشريفين الملك سلمان","السفر والسياحة","الثقافة والفنون","الاقتصاد والأسواق","الخليج العربي"]','["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء والسلطان هيثم بن","رئيس مجلس الوزراء والسلطان هيثم","خادم الحرمين الشريفين الملك سلمان","السفر والسياحة","الثقافة والفنون"]','classified','','[{"category":"الاقتصاد","score":8.5},{"category":"المجتمع","score":3},{"category":"الثقافة","score":1.5}]','Updated','2026-10-07T19:44:01.624Z',200,62,0,'source_content_changed','',NULL,NULL,'body:935a2fb97dd31d034e74796ac4963b9020811de24c0b67cedf684e832b0be4fd','Wed, 07 Oct 2026 19:43:59 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0c3ff762-2e50-49fd-8e75-531dab290d21','news-0c3ff762-2e50-49fd-8e75-531dab290d21','الأخضر السعودي تحت 20 عامًا يكسب نظيره العُماني بثلاثية في التصفيات المؤهلة لكأس آسيا','الاخضر السعودي تحت 20 عاما يكسب نظيره العماني بثلاثيه في التصفيات المؤهله لكاس اسيا','حقق المنتخب السعودي تحت 20 عاماً فوزاً ثميناً على حساب نظيره العُماني بنتيجة 3-2، وذلك على ملعب حمد بن خليفة في العاصمة القطرية الدوحة، ضمن منافسات الجولة الثانية من التصفيات المؤهلة لكأس آسيا تحت 20 عاماً 2027.','["جاءت أهداف «الأخضر» الثلاثة في الدقائق 11 و46 و66 من عمر المباراة؛ إذ سجّل الهدف الأول في مرمى الفريق العُماني بأقدام لاعبيه، فيما أحرز إلياس شيخ الهدف الثاني، قبل أن يُعزز فارس بن سالم التقدم بالهدف الثالث.","يخوض المنتخب السعودي تحت 20 عاماً منافسات المجموعة الخامسة في هذه التصفيات، إلى جانب منتخبات قطر وعُمان وهونغ كونغ، ساعياً إلى التأهل لنهائيات كأس آسيا تحت 20 عاماً 2027."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/AdJZvb5','https://sabq.org/article/AdJZvb5','','https://sabq.org/article/AdJZvb5','صحيفة سبق','','2026-09-03T16:35:00.000Z','2026-09-03T18:01:00.000Z','2026-09-04T11:23:07.056Z','https://media.sabq.org/news/2026/09/91ef2533-cb48-4493-95f4-3626bca4fb8a/w1200.webp','/api/media/0c3ff762-2e50-49fd-8e75-531dab290d21','/api/media/0c3ff762-2e50-49fd-8e75-531dab290d21?variant=thumbnail','الأخضر السعودي تحت 20 عامًا يكسب نظيره العُماني بثلاثية في التصفيات المؤهلة لكأس آسيا',1200,675,'valid','published','archived','valid',61,'99d793861ccd0340ab0c4281cd4a4811b358a346b92a444d7234e4bcd3d53be4','3562b80138f6b258e403d9212145f76ac82d2ba4ee26a846b38204b6554b0118','محدّث','2026-09-03T22:44:02.763Z','2026-10-07T19:44:55.346Z','','',0,0,'gulf_arab','عادي',46,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"التقنية","score":0},{"category":"المناطق","score":-5}]','Active','2026-10-07T19:44:55.346Z',200,56,0,'source_article_available','',NULL,NULL,'body:6115eb77c47bb542e658144e04ccc3fcbb0094337c7442245a3a358c5b039d9d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e13af4ef-b5b0-4fb1-afd4-a6f5c9587060','news-e13af4ef-b5b0-4fb1-afd4-a6f5c9587060','من مضمار الهجن إلى عوالم ليب: صورة السعودية الجديدة','من مضمار الهجن الي عوالم ليب صوره السعوديه الجديده','وبعد فترة وجيزة، كان المتعلمون أنفسهم على موعد مع مشهد آخر في الرياض: ملتقى LEAP، حيث الذكاء الاصطناعي والروبوتات والشركات التقنية والمبتكرون القادمون من أنحاء العالم.','["قبل نحو عامين، كنت برفقة مجموعة من متعلمي اللغة العربية في المملكة، ينتمون إلى نحو ثمانٍ وأربعين جنسية؛ لزيارة إحدى الفعاليات التي تتيح لهم التعرف عن قرب إلى المجتمع السعودي وثقافته. كانت الوجهة يومها سباقاً للهجن في الرياض؛ الصحراء، والبعير، والخيمة، مشهدٌ ربما لم يكن بعيداً عن الصورة النمطية المختزلة، التي حملها بعضهم عن المملكة قبل أن يعيش فيها.","وبعد فترة وجيزة، كان المتعلمون أنفسهم على موعد مع مشهد آخر في الرياض: ملتقى LEAP، حيث الذكاء الاصطناعي والروبوتات والشركات التقنية والمبتكرون القادمون من أنحاء العالم. صورتان عاشهما الوافدون أنفسهم، في المدينة نفسها، وفي الدولة نفسها: إحداهما تمتد عميقاً في الموروث والأصالة، والأخرى تطل على أحدث ما يصنع من تقنيات في عالم رقمي متسارع.","ولعل الأجمل أن الصورة الأولى لم تختفِ لكي تظهر الثانية؛ فهذه بلادٌ تستطيع أن تحمل إرثها معها وهي تتقدم إلى المستقبل؛ فلا الخيمة نقيض لمركز البيانات، ولا الهجن نقيض للذكاء الاصطناعي، ولا الاعتزاز بالهوية يتعارض مع بناء اقتصاد رقمي عالمي. أسوق هذه الذكرى ونحن نعيش هذه الأيام النسخة الخامسة من ملتقى LEAP في الرياض؛ لأن ما يجري فيه لا أراه مجرد مؤتمر تقني آخر، ولا مجرد معرض للشركات والمنتجات فحسب، بقدر ما أراه مشهداً مكثفاً للتحول الذي تعيشه المملكة نفسها.","فالحدث الذي بدأ قبل سنوات قليلة أصبح اليوم يجمع في الرياض أكثر من مئتي ألف زائر، ونحو ألف متحدث، وأكثر من 1900 مستثمر، ومئات الشركات الناشئة، ونحو 1800 علامة تقنية عالمية. غير أن قيمة هذه الأرقام، في تقديري، لا تكمن في ضخامتها وحدها، بل فيما تقوله عن المكان الذي أصبحت تحتله الرياض على خريطة الاقتصاد الرقمي العالمي؛ فالسؤال الأهم لم يعد: كم بلغ عدد الجهات والأفراد الذين شاركوا في ليب؟ بل: ما الذي جعل كل هؤلاء يأتون إلى الرياض؟ ولماذا أصبحت الرياض مهمة لهم؟","ربما نجد جانباً من الإجابة في التحول الذي تشهده المملكة نفسها؛ فالاقتصاد الرقمي السعودي نما، وفق الأرقام المعلنة في الملتقى، من نحو 118 مليار دولار إلى قرابة 199 ملياراً منذ انطلاق LEAP، فيما تجاوزت الاستثمارات والشراكات التقنية المعلنة في نسخة هذا العام 15 مليار دولار. وهذه ليست أرقاماً مهمة لمجرد ضخامتها فحسب، بل لأنها تتجه إلى مجالات ستحدد جانباً كبيراً من اقتصاد المستقبل: الذكاء الاصطناعي، ومراكز البيانات، والحوسبة السحابية، والبنية التحتية الرقمية. وحين تتحرك الاستثمارات بهذا الحجم، فنحن لا نتحدث عن احتفاء بالتقنية بقدر ما نتحدث عن اقتصاد يعيد بناء جزء من قدراته حولها.","ومن هنا يمكن أيضاً فهم حضور أسماء من الصف الأول في صناعة التقنية العالمية؛ من ليزا سو، الرئيسة التنفيذية لـAMD، إلى تشاك روبنز، الرئيس التنفيذي لـCisco، وأندرو فيلدمان، الرئيس التنفيذي لـCerebras، وجاستن هوتارد، الرئيس التنفيذي لـNokia، إلى جانب قيادات سعودية في مقدمتها وزير الاتصالات وتقنية المعلومات المهندس عبدالله السواحة، والرئيس التنفيذي لـHUMAIN طارق أمين. وليست القضية في استعراض الأسماء هنا، على أهميتها، وإنما في دلالة اجتماعها هنا؛ فالشركات العالمية الكبرى ورؤوس الأموال لا تنتقل من قارة إلى أخرى من أجل صورة تذكارية في مؤتمر، بل تتحرك حيث ترى سوقاً وفرصة وبنية تحتية وطموحاً قابلاً للتحول إلى أعمال.","ومن ثَمّ، في تقديري، يكمن أحد التحولات المهمة في قصة المملكة مع التقنية. لقد اعتادت منطقتنا طويلاً أن تكون سوقاً لما ينتجه الآخرون، أما ما يتشكل اليوم فهو طموح إلى موقع مختلف: أن نستثمر في التقنية، ونبني بنيتها التحتية، ونستقطب صناعاتها وعقولها، ونشارك في تطويرها. وعلى سبيل المثال وليس الحصر، الشراكات المعلنة في LEAP بين HUMAIN وشركات عالمية مثل AWS وAMD وQualcomm، وما يصاحبها من استثمارات في الحوسبة والذكاء الاصطناعي ومراكز البيانات، ليست سوى شواهد على هذا الاتجاه. هذه لم تعد دولة تستضيف المستقبل؛ بل أصبحت طرفاً وركناً شديداً في صناعته.","وليس هذا التحول منفصلاً عن المشروع الأكبر الذي تعيشه المملكة منذ انطلاق رؤية السعودية 2030، بقيادة عرّابها سمو ولي العهد الأمير محمد بن سلمان؛ فالرؤية منذ بدايتها لم تكن برنامجاً للإصلاح الاقتصادي فحسب، بل مشروعاً لإعادة صياغة موقع المملكة وطموحها في العالم، وتنويع اقتصادها، والاستثمار في الإنسان والتقنية وصناعات المستقبل. ومن هذه الزاوية يبدو LEAP واحداً من المشاهد التي تتجسد فيها الرؤية أمامنا: الرياض لا تستقبل العالم فحسب، بل تستقطب استثماراته وعقوله وتقنياته، وتقدم نفسها بوصفها شريكاً في تشكيل ما هو قادم."]','أخبار السعودية','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264303','https://www.okaz.com.sa/articles/authors/2264303','','https://www.okaz.com.sa/articles/authors/2264303','حسن الشمراني','الرياض','2026-09-03T18:00:00.000Z','Wed, 07 Oct 2026 18:23:14 GMT','2026-09-03T23:14:21.121Z','https://www.okaz.com.sa/okaz/uploads/authors/1919.jpg?v=1788197211','/api/media/e13af4ef-b5b0-4fb1-afd4-a6f5c9587060','/api/media/e13af4ef-b5b0-4fb1-afd4-a6f5c9587060?variant=thumbnail','من مضمار الهجن إلى عوالم ليب: صورة السعودية الجديدة',400,400,'valid','published','archived','valid',91,'fe505c14cec53e2b66b56cc0288cb845759ada1ae70fcee9f133d4660729b538','e452065b3131fd81bc2fd8c615abf6fae76311744fed55cdb639e9c105c1ea56','محدّث','2026-09-03T23:14:21.121Z','2026-10-07T20:44:49.849Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد الأمير محمد بن","وزير الاتصالات وتقنية المعلومات المهندس","الصحة العامة","الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي","الرياض"]','["ولي العهد الأمير محمد بن","وزير الاتصالات وتقنية المعلومات المهندس","الصحة العامة","الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق"]','classified','','[{"category":"المجتمع","score":8.5},{"category":"الاقتصاد","score":5.5},{"category":"الثقافة","score":3}]','Active','2026-10-07T20:44:49.849Z',304,49,0,'source_article_available','',NULL,NULL,'body:e17833c0e87fc584f4a8de35aac7b56f8420e4dadfb49a554b34cd589ac9cb10','Wed, 07 Oct 2026 18:23:14 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('80b86a8e-fcb8-4a2d-9ae9-c75da2a2ec5d','news-80b86a8e-fcb8-4a2d-9ae9-c75da2a2ec5d','النصر مرشح.. والاتحاد في مهمة إسقاط المنطق','النصر مرشح والاتحاد في مهمه اسقاط المنطق','غدًا، بإذن الله، موعدنا مع كلاسيكو يجمع الاتحاد بالنصر، في مواجهة تأتي هذه المرة مع انطلاقة الدوري، في توقيت لم نعتد عليه خلال المواسم الأخيرة، بعدما كانت لجنة المسابقات تفضّل «وضع الاتحاد في مواجهة الهلال مع بداية الموسم»، وكأن هناك تقليدًا لا ينبغي كسره! الفوارق الفنية والعناصرية تميل لمصلحته، كما أن النتائج التي حققها في الجولات الماضية تؤكد أنه يدخل…','["غدًا، بإذن الله، موعدنا مع كلاسيكو يجمع الاتحاد بالنصر، في مواجهة تأتي هذه المرة مع انطلاقة الدوري، في توقيت لم نعتد عليه خلال المواسم الأخيرة، بعدما كانت لجنة المسابقات تفضّل «وضع الاتحاد في مواجهة الهلال مع بداية الموسم»، وكأن هناك تقليدًا لا ينبغي كسره!","-أما هذا الموسم فقد تغيرت المعادلة، وأصبح الأهلي هو الطرف المقابل للهلال في البداية، ليأتي الاتحاد والنصر في مواجهة مبكرة ربما تحمل كثيرًا من الحسابات، أو هكذا تبدو لي.. وبعيدًا عن النوايا التي لا يعلمها إلا الله ثم أصحابها، فإن السؤال الذي يفرض نفسه: هل أصبحت روزنامة المسابقات مبنية على من سينافس الهلال في كل موسم، سؤال بريء يبحث عن إجابة صادقة.","-المشكلة ليست في الجدولة وحدها، وإنما في الاعتقاد بأن الناس لا تلاحظ ولا تقرأ ما بين السطور، بينما الحقيقة أن الجمهور الرياضي أصبح أكثر وعيًا، وما كان يمر بالأمس أصبح اليوم محل نقاش ومساءلة.","-ما علينا.. لنترك اللجنة وجدولها جانبًا، ولنذهب إلى ما هو أهم نحو الكلاسيكو نفسه.. فعلى الورق، تبدو كفة النصر أرجح بوضوح. الفوارق الفنية والعناصرية تميل لمصلحته، كما أن النتائج التي حققها في الجولات الماضية تؤكد أنه يدخل المباراة وهو في حالة أفضل من الجاهزية والاستقرار.","-نصر كريستيانو وكوكبة من النجوم العالمين لم يفز في مبارياته السابقة مصادفة، وإنما يملك عناصر فنية تمنحه أفضلية واضحة، فضلًا عن رغبة قوية في مواصلة الانتصارات والدفاع عن اللقب الذي حققه الموسم الماضي.","في المقابل، يدخل الاتحاد المواجهة وسط ظروف إدارية وفنية لم تكن سهلة، وتقلبات لا يمكن تجاهل تأثيرها على الفريق، وهو ما يجعل جماهيره أكثر قلقًا على مستقبله هذا الموسم، لكن هناك أمر يستحق التوقف عنده هو أن الاتحاد لم يخسر حتى الآن، وهذه وحدها رسالة تقول إن الفريق، رغم كل ما يحيط به، لا يزال قادرًا على الصمود.","-كما أن التعاقدات التي أبرمتها إدارة النادي خلال اليومين الماضيين مع الجناح «رويس» ولاعب الوسط «أنس» تمثل مؤشرًا إيجابيًا على أن الإدارة تحاول معالجة النقص الذي يعاني منه الفريق، وإن كان من المستبعد أن يكون للاعبين الجديدين حضور في كلاسيكو الغد إلا إذا كانا جاهزين فإن مشاركتهما ربما ستكون في الشوط الثاني.","-إذن، إذا أخذنا الأمور بمنطق كرة القدم، فإن النصر هو المرشح الأقوى للفوز، ولكن كرة القدم لا تلعب دائمًا بمنطق الورق، وهنا يأتي الاتحاد بكل ظروفه، وبكل ما لديه من نقاط قوة وضعف، وبمدرب متحمس وشغوف ما زال في بداية مشواره مع «النمور» وبفريق لم تكتمل صفوفه بعد، ومع ذلك يقاتل في الملعب ويقدم مستويات أفضل مما كان متوقعًا في ظل حجم النقص الذي يعاني منه."]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264302','https://www.okaz.com.sa/articles/authors/2264302','','https://www.okaz.com.sa/articles/authors/2264302','عدنان جستنيه','الرياض','2026-09-03T18:00:00.000Z','Wed, 07 Oct 2026 18:23:15 GMT','2026-09-03T23:14:21.997Z','https://www.okaz.com.sa/okaz/uploads/authors/1828.jpg?v=1782207910','/api/media/80b86a8e-fcb8-4a2d-9ae9-c75da2a2ec5d','/api/media/80b86a8e-fcb8-4a2d-9ae9-c75da2a2ec5d?variant=thumbnail','النصر مرشح.. والاتحاد في مهمة إسقاط المنطق',400,400,'valid','published','archived','valid',41,'44c46d434edbbf5e621dc8207d42b48920e50c571f971711aea417bd7613f336','fe9c503c8f4aaf6c377d20148d97e10524bdf86eff312b4998655c9a02692d98','محدّث','2026-09-03T23:14:21.997Z','2026-10-07T20:44:49.870Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الرياضة السعودية","الاقتصاد والأسواق","الرياض"]','["الصحة العامة","الرياضة السعودية","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":-3.5},{"category":"الاقتصاد","score":-3.5}]','Active','2026-10-07T20:44:49.870Z',304,49,0,'source_article_available','',NULL,NULL,'body:9fa43c433cd90ddfabb842f405af1f4533b5191e47ede68b2f9098dd98ebaed4','Wed, 07 Oct 2026 18:23:15 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('700bd6cb-9d97-440b-ba20-4754df695360','news-700bd6cb-9d97-440b-ba20-4754df695360','أسعد عبدالكريم.. عندما يتحدث الخبير عن هموم الكرة السعودية','اسعد عبدالكريم عندما يتحدث الخبير عن هموم الكره السعوديه','- أجاب عن الوضع الحالي للكرة السعودية وقدم نصائح الخبير بشكل مبسط بعيدًا عن التحليلات المعقدة، وأشار إلى أن الدعم الذي تحظى به الرياضة السعودية لا يوازي ما تقدمه الكرة السعودية؛ فأين الخلل إذن؟','["- عند الكتابة عن قامات سُطّرت أسماؤها بمداد من ذهب، لا تدري من أين تبدأ ومن أين تنتهي؛ لأن تاريخهم حافل بالإنجازات، وعطاءهم كبير، ووطنيتهم جليّة عبر التاريخ.","- الفريق أسعد عبد الكريم، مدير الأمن العام الأسبق، تجمعت في سيرته العطرة صفات من الصعب أن تجتمع في شخص واحد؛ ومثل هذه الأسماء لن تتكرر، فهو رجل أمن من الطراز الأول، وشاعر، وأديب، وكاتب، ورياضي.","- أعماله وإنجازاته خير شاهد على ما قدمه، ولا أريد الإطالة وسيرته مدونة ويعرفها الكثيرون، لكنني أريد الحديث عن ثقافته وفكره وتركيزه الذهني العالي وهو يجيب بكل عفوية وخبرة عريضة عن الرياضة السعودية وما يحدث فيها. أجاب الرجل إجابة الواثق وكان شفافًا إلى أبعد الحدود مع الإعلامي المخضرم بتال القوس، الذي يعتاد استضافة شخصيات لها ثقلها الكبير في المجتمع والوسط الرياضي.","- أجاب عن الوضع الحالي للكرة السعودية وقدم نصائح الخبير بشكل مبسط بعيدًا عن التحليلات المعقدة، وأشار إلى أن الدعم الذي تحظى به الرياضة السعودية لا يوازي ما تقدمه الكرة السعودية؛ فأين الخلل إذن؟ هناك حلقة مفقودة يجب التركيز عليها، فليس من المعقول أن تتراجع المنتخبات السعودية وتتقدم منتخبات أقل دعمًا. نعم، لدينا دوري قوي اكتسب سمعة عالمية، لكننا نبحث عن منتخب قوي يعيد أمجاد الكرة السعودية.","- كما أشار إلى أن القائمين على إدارة الاحتراف والاستقطاب غير معروفين، ولا تُعرف مخصصات كل نادٍ، وكان المفترض أن تكون هناك شفافية ووضوح بعيدًا عن التأويل والضجيج الحالي، فالأمر بسيط ولا يحتاج كل هذا التعقيد.","- شخّص الوضع بصفته خبيرًا رياضيًا عاصر الكرة السعودية وقدم لنا الاتحاد (العميد) في أجمل صورة؛ ذلك الفريق الذي تربع على عرش الكرة الآسيوية بنجوم ومواهب صنعت الفارق بتشكيلة تضاهي منتخبًا لا مجرد نادٍ، استقطبهم من عدة أندية.","- وقال الخبير أسعد عبد الكريم إن المفترض أن يكون عدد اللاعبين الأجانب خمسة فقط؛ لأن اللاعب السعودي أصبح مهمشًا في الملعب ومجرد تكملة عدد، فهل هناك من يستمع إليه وللشارع الرياضي الذي يبحث عن منتخب قوي؟","- أعجبني ضربه للأمثلة واختصاره لكل سؤال يطرحه بتال، الذي أعطى ضيفه حقه وكان نجمًا في إدارته للحوار، كما كان ضيفه نجمًا بارعًا وهو يؤدي رسالته الوطنية بامتياز."]','أخبار السعودية','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264301','https://www.okaz.com.sa/articles/authors/2264301','','https://www.okaz.com.sa/articles/authors/2264301','سامي المغامسي','الرياض','2026-09-03T18:00:00.000Z','Wed, 07 Oct 2026 18:23:14 GMT','2026-09-03T23:14:23.592Z','https://www.okaz.com.sa/okaz/uploads/authors/1672.jpg?v=1757438909','/api/media/700bd6cb-9d97-440b-ba20-4754df695360','/api/media/700bd6cb-9d97-440b-ba20-4754df695360?variant=thumbnail','أسعد عبدالكريم.. عندما يتحدث الخبير عن هموم الكرة السعودية',399,400,'valid','published','archived','valid',54,'23009f9563503fc09720f83188dd8ac9bd8542848cdebb45e97a60806ca5099c','d1a3fa962695958a5255a60ef58b7f96aa758fee896223afa18b074ae1bd97a8','محدّث','2026-09-03T23:14:23.592Z','2026-10-07T20:28:04.138Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق","الرياض"]','["الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"الاقتصاد","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T20:28:04.138Z',304,49,0,'source_article_available','',NULL,NULL,'body:db16c1a9a2c63afe44ac0504c15bc95ae430a4be24c0ca0e4aeb9e92b94d4872','Wed, 07 Oct 2026 18:23:14 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('af637e95-8e68-4e4d-915e-598a03145449','news-af637e95-8e68-4e4d-915e-598a03145449','إحياء اتفاق الهدنة بين لبنان وإسرائيل: واقعية أم مناورة؟','احياء اتفاق الهدنه بين لبنان واسرائيل واقعيه ام مناوره','لعلّ أفضل ما يميّز اتفاق الهدنة الذي وقّع بين لبنان وإسرائيل عام ١٩٤٩، أنه وقّع في فترة زمنية كان لبنان فيها لا يزال دولة فتيّة مستقلة. على الأثر، ارتكبت إسرائيل مجزرة حولا في جنوب لبنان، وبدأت سلسلة من الاعتداءات بذريعة محاربة الفدائيين، فسارع لبنان إلى توقيع اتفاقية الهدنة.','["لعلّ أفضل ما يميّز اتفاق الهدنة الذي وقّع بين لبنان وإسرائيل عام ١٩٤٩، أنه وقّع في فترة زمنية كان لبنان فيها لا يزال دولة فتيّة مستقلة. فلا حزب عقائديّ يحكم ويتحكم بمفاصل وقرارات الدولة، ولا فساد تمدّد إلى قلب المؤسسات حتى تحوّل إلى آلية حكم بحدّ ذاتها.","وعندما وقعت النكبة عام ١٩٤٨، تحوّل لبنان بحكم الجغرافيا إلى ملجأ لعدد كبير من الفلسطينيين الهاربين من عمليات القتل والتهجير الإسرائيليين، كما إلى منطلق للفدائيين في عملياتهم ضد القوات والعصابات الإسرائيلية. على الأثر، ارتكبت إسرائيل مجزرة حولا في جنوب لبنان، وبدأت سلسلة من الاعتداءات بذريعة محاربة الفدائيين، فسارع لبنان إلى توقيع اتفاقية الهدنة.","وبالفعل، استقرّت الأوضاع نسبيّا في الجنوب في الفترة الممتدة بين ١٩٤٩ و١٩٦٧، قبل أن تتهّم إسرائيل الدولة اللبنانية بمخالفة شروط اتفاقية، لا سيّما ما نصّت عليه المادة الأولى بشأن عدم تشكيل تهديد للطرف الآخر وعدم اللجوء إلى القوة العسكرية لتسوية القضية الفلسطينية. ورغم نفي لبنان تلك الاتهامات، يمكن القول إن الاتفاقية سقطت عمليّا مع توقيع لبنان لاتفاق القاهرة عام ١٩٦٩. فآنذاك، كان تآكل الدولة قد بدأ مع انقسام أركانها في صراع المحاور الإقليمية، وخضوع الحكم لضغوط عربية، وتحديدا مصرية بقيادة جمال عبد الناصر، لتشريع العمل الفلسطيني المسلّح انطلاقا من لبنان. ثمّ جاءت الضربة الأخرى تحت عنوان «تنظيم الوجود الفلسطيني المسلّح» مع توقيع اتفاق مالكارت عام ١٩٧٣، والذي يعتبر ملحقا لاتفاق القاهرة.","رغم ذلك، بقيت الاتفاقية إطارا قانونيّا معترفا به في الأمم المتحدة، ومرجعية للاتفاقيات والترتيبات التي تلت بين لبنان وإسرائيل وصولا إلى القرار ١٧٠١ بنسخته المعدّلة.","تكتسب بنود الاتفاقية أهمية للبنان، فهي تعترف بالحدود الدولية التاريخية بين لبنان وإسرائيل (المادة ٥)، وهو ما يحتاجه لبنان في مفاوضاته اليوم في ظلّ الاحتلال الإسرائيلي لأجزاء من جنوبه. كما تمنع استخدام الأراضي اللبنانية ضد إسرائيل، سواء من القوات النظامية أو المجموعات المسلّحة، وتمنع استخدام الأراضي الإسرائيلية ضد لبنان (المادة ٧). كذلك تحدّد مهام القوات العسكرية وعديدها وعتادها على جانبيّ الحدود ضمن طبيعة دفاعية وبأسلحة خفيفة ومحدودة (ملحق قوات الدفاع).","دوليّا، يثير المطالبة بإحياء اتفاقية الهدنة الآن إشكالية، إذ إن الوقائع تشير إلى رغبة الولايات المتحدة، وهي الوسيط التاريخي والراعي لكل الاتفاقيات المرتبطة بالصراع اللبناني-الإسرائيلي، في فصل الملف عن الأمم المتحدة، والدفع، تحت النار، نحو اتفاق جديد ينهي الصراع بين لبنان وإسرائيل بدل الاكتفاء بضبطه كما نصّت الهدنة.","أما لبنانيّا، فتبرز مفارقة ترتبط بالسردية الجديدة لحزب الله وبعض حلفائه والمتقاطعين معه. فجوهر اتفاقية الهدنة يتضمّن تحديدا ما أعلن هؤلاء رفضه مرارا، واستخدموه لاتهام الدولة بالعمل «كشرطي» لدى إسرائيل، لا سيّما في ما يتعلّق بمسألة منع استخدام الأراضي اللبنانية ضدها، ومهام وعتاد الجيش.","من هنا، يثير التمسّك المستجد بإحياء اتفاقية الهدنة، بعد رفض القرار ١٧٠١ ثمّ التمسّك به للتهرّب من اتفاق الإطار، سؤالا يتجاوز موضوع الاتفاقيات نفسها إلى السلوك اللبناني في التعامل معها، وهو يقوم على سياسة الالتفاف والتهرّب الدائم من تنفيذ الالتزامات تحت ذرائع مختلفة، فيما جوهر الصراع الداخلي هو حول من يملك قرار الحرب والسلم في لبنان، الدولة أم قوى الأمر الواقع."]','السياسة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264300','https://www.okaz.com.sa/articles/authors/2264300','','https://www.okaz.com.sa/articles/authors/2264300','حياة الحريري','','2026-09-03T18:00:00.000Z','Wed, 07 Oct 2026 18:23:15 GMT','2026-09-03T23:14:23.640Z','https://www.okaz.com.sa/okaz/uploads/authors/1911.jpg?v=1786031254','/api/media/af637e95-8e68-4e4d-915e-598a03145449','/api/media/af637e95-8e68-4e4d-915e-598a03145449?variant=thumbnail','إحياء اتفاق الهدنة بين لبنان وإسرائيل: واقعية أم مناورة؟',400,400,'valid','published','archived','valid',43,'24c6a38d2307193d970eeba3d97d8082f4f2b1478dcecdba7318466aafa6b36c','56dd0d9b64abaa311b046d70d8a842dfa9102d8a12ca368818553bdce0843b41','محدّث','2026-09-03T23:14:23.640Z','2026-10-07T20:44:50.248Z','','',0,0,'gulf_arab','عادي',51,NULL,0,0,0,'',NULL,NULL,NULL,'["الأمم المتحدة ومرجعية للاتفاقيات والترتيبات","السياسة والعلاقات الدولية","لبنان","فلسطين","الولايات المتحدة"]','["الأمم المتحدة ومرجعية للاتفاقيات والترتيبات","السياسة والعلاقات الدولية","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T20:44:50.248Z',304,48,0,'source_article_available','',NULL,NULL,'body:08e176528701705d2f8248d1bfa2ebb507cfbd9b5d568276a075fc27bec481b2','Wed, 07 Oct 2026 18:23:15 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4edbaa59-7b65-4a6e-92ad-8d3b0714e92e','news-4edbaa59-7b65-4a6e-92ad-8d3b0714e92e','«الأرصاد» يتوقع أمطارًا رعدية وسيولًا على عدة مناطق بالمملكة اليوم','الارصاد يتوقع امطارا رعديه وسيولا علي عده مناطق بالمملكه اليوم','وأشار المركز إلى أن حركة الرياح السطحية على البحر الأحمر ستكون شمالية غربية إلى شمالية بسرعة تتراوح بين 20 و40 كم/ساعة، مع ارتفاع للموج من متر إلى مترين، وحالة البحر متوسط الموج.','["توقّع المركز الوطني للأرصاد في تقريره اليومي عن حالة الطقس، هطول أمطار رعدية متوسطة إلى غزيرة تؤدي إلى جريان السيول، مصحوبة بزخات من البرد، على أجزاء من مناطق نجران ، و جازان ، و عسير ، و الباحة ، مع امتدادها إلى الأجزاء الجنوبية من مرتفعات منطقة مكة المكرمة.","وأوضح التقرير أن الرياح النشطة المثيرة للأتربة والغبار ستستمر بالتأثير على أجزاء من المناطق المذكورة، بالإضافة إلى أجزاء من منطقتي الرياض و الشرقية ، وأجزاء من مناطق تبوك ، والمدينة المنورة، ومكة المكرمة، خاصة في المناطق الساحلية.","وتابع: أما في الخليج العربي ، فستكون الرياح السطحية جنوبية شرقية إلى جنوبية غربية بسرعة 10-30 كم/ساعة، وارتفاع الموج من نصف المتر إلى متر ونصف، وحالة البحر خفيف إلى متوسط الموج."]','البيئة والمناخ','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/b5nexas27','https://ajel.sa/local/b5nexas27','https://ajel.sa/local/b5nexas27','https://ajel.sa/local/b5nexas27','فريق التحرير','الرياض','2026-09-03T22:06:00.000Z','Mon, 07 Sep 2026 04:41:23 GMT','2026-09-04T09:09:12.386Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%B7%D9%82%D8%B3-5-rzKYm5u-.jpg','/api/media/4edbaa59-7b65-4a6e-92ad-8d3b0714e92e','/api/media/4edbaa59-7b65-4a6e-92ad-8d3b0714e92e?variant=thumbnail','«الأرصاد» يتوقع أمطارًا رعدية وسيولًا على عدة مناطق بالمملكة اليوم',1200,675,'valid','published','archived','valid',99,'231789e150835a2c4f98c825284e8f5938be7c3ec20c2308d601fbd07dc0dee4','70b020cf9065866ce60aebc69627258844309474c0c3e2dbd5595702ad75ad86','محدّث','2026-09-04T04:26:45.704Z','2026-10-07T19:16:00.062Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة","عسير","تبوك","جازان","نجران","الرياض","الباحة"]','["الطقس والمناخ","الخليج العربي","المدينة المنورة"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Temporarily Unreachable','2026-10-07T19:16:00.062Z',NULL,54,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('71397482-a2a1-43be-9f66-b05591111995','news-71397482-a2a1-43be-9f66-b05591111995','عن أي رجل و امرأة يتحدثون ..!؟','عن اي رجل و امراه يتحدثون','#ناصية دائماً يقولون: المرأة إذا أحبتك فعلت كذا وكذا، والمرأة تحب من يحمل المسؤولية، والمرأة تريد المال ، ......إلخ. 🔴 والسؤال: أين هي المرأة تلك التي يتحدثون عنها؟!','["ويقولون أيضاً: الرجل يحب الحنان، والرجل يريد التقدير، والرجل يميل إلى المرأة المطيعة، ......إلخ. 🔴 والسؤال: أين هو الرجل هذا الذي يتحدثون عنه؟! 🔴 والسؤال الأهم هنا هو : 👇👇👇👇 هل الرجل عندما يتحدث عن رغبات الرجل، أو المرأة عندما تتحدث عن رغبات المرأة، هل هما يتحدثان عن رغباتهما الخاصة ويغلفانها بسياقات اللغة العامة؟! #قاله_العرفج #نواصي_المرأة"]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/if7gxdo','https://sabq.org/article/if7gxdo','','https://sabq.org/article/if7gxdo','أحمد عبد الرحمن العرفج ','','2026-09-03T22:30:00.000Z','2026-09-04T01:30:00.000Z','2026-09-04T04:35:47.188Z','https://media.sabq.org/news/2026/09/d8269f52-fd70-4993-aa20-817f25688577/w1600.webp','/api/media/71397482-a2a1-43be-9f66-b05591111995','/api/media/71397482-a2a1-43be-9f66-b05591111995?variant=thumbnail','عن أي رجل و امرأة يتحدثون ..!؟',1600,893,'valid','published','archived','valid',35,'58fef0a603c5f52a44ddccb76f6e30af1808b9fd5493228aa9a5543aa8b891ca','f51f063d7e5418e7c5ddd8ab956b1b6b90f13018647e85093df013470436c52e','محدّث','2026-09-04T04:35:47.188Z','2026-10-07T19:41:38.631Z','','',0,0,'international','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Temporarily Unreachable','2026-10-07T19:41:38.631Z',NULL,55,4,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4a2d3f55-12eb-4885-9be3-b286c8ced483','news-4a2d3f55-12eb-4885-9be3-b286c8ced483','تباين أسعار النفط عند التسوية وسط مخاوف من توترات الشرق الأوسط','تباين اسعار النفط عند التسويه وسط مخاوف من توترات الشرق الاوسط','تباينت أسعار النفط عند التسوية اليوم الجمعة، وسط استمرار المخاوف من تعطل الإمدادات نتيجة تجدد التوتر في منطقة الشرق الأوسط . في المقابل، ارتفعت العقود الآجلة لخام غرب تكساس الوسيط الأمريكي 29 سنتًا، أو 0.32٪، لتسجل 91.30 دولارًا للبرميل عند التسوية.','["تباينت أسعار النفط عند التسوية اليوم الجمعة، وسط استمرار المخاوف من تعطل الإمدادات نتيجة تجدد التوتر في منطقة الشرق الأوسط .","وأظهرت بيانات الأسواق انخفاض العقود الآجلة لخام برنت بمقدار 11 سنتًا، أي ما يعادل 0.12٪، ليغلق عند مستوى 95.52 دولارًا للبرميل.","في المقابل، ارتفعت العقود الآجلة لخام غرب تكساس الوسيط الأمريكي 29 سنتًا، أو 0.32٪، لتسجل 91.30 دولارًا للبرميل عند التسوية.","يأتي هذا التباين في الأسعار في ظل ترقب المستثمرين لتطورات الأوضاع الجيوسياسية وتأثيرها على استقرار إمدادات الطاقة العالمية."]','الطاقة والصناعة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/ju8xocpsv','https://ajel.sa/local/ju8xocpsv','https://ajel.sa/local/ju8xocpsv','https://ajel.sa/local/ju8xocpsv','فريق التحرير','','2026-09-03T22:59:00.000Z','Mon, 07 Sep 2026 00:40:29 GMT','2026-09-04T05:05:07.824Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D9%86%D9%81%D8%B7-3-vbiC56n6.jpg','/api/media/4a2d3f55-12eb-4885-9be3-b286c8ced483','/api/media/4a2d3f55-12eb-4885-9be3-b286c8ced483?variant=thumbnail','تباين أسعار النفط عند التسوية وسط مخاوف من توترات الشرق الأوسط',1200,675,'valid','published','archived','valid',52,'8ede6150fc2cec9f43eb60e5c9c6525e35681c0f483823e75de9a3fbc35f1e19','4cefdf9195e8c16ad8e7184a5ed88a3e29cd9c2762809a0fe0a581d77e89f659','محدّث','2026-09-04T05:05:07.824Z','2026-10-07T19:51:00.478Z','','',0,0,'international','عادي',39,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الشرق الأوسط"]','["الطاقة والنفط","الشرق الأوسط"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Temporarily Unreachable','2026-10-07T19:51:00.478Z',NULL,54,7,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('70604dbe-f52e-40e6-8317-5e2fdb5f6987','news-70604dbe-f52e-40e6-8317-5e2fdb5f6987','تكامل القابضة تختتم مشاركتها في «ليب 2026» بتوقيع 34 اتفاقية وإطلاق منتج «تزامن»','تكامل القابضه تختتم مشاركتها في ليب 2026 بتوقيع 34 اتفاقيه واطلاق منتج تزامن','اختتمت تكامل القابضة مشاركتها في مؤتمر «ليب 2026»، بصفتها شريك التحول الاقتصادي، بعد مشاركة حافلة شهدت توقيع 34 اتفاقية للتعاون وتبادل الخبرات في مجالات الاهتمام المشترك، إلى جانب استعراض منظومة أعمال الشركة وحلولها وإطلاق منتجات جديدة، في امتداد لدورها في توظيف التقنية والبيانات والابتكار لدعم التحول الرقمي ورفع كفاءة القطاعات.','["واستعرضت تكامل خلال مشاركتها مجموعة من حلولها وخدماتها عبر تجارب تفاعلية، أتاحت لزوار جناحها التعرف على أعمال الشركة في مجالات متعددة، شملت البيانات، والذكاء الاصطناعي والتقنيات الناشئة، والتحول الرقمي، ورأس المال البشري، بما يعكس تنوع قدراتها في تطوير حلول تستجيب لاحتياجات الأفراد والمنشآت والقطاعات.","وعلى صعيد الإطلاقات، كشفت تكامل عن منتج «تزامن» الجديد، الذي يتيح للشركات ومقدمي خدمات الموارد البشرية أتمتة إجراءات المنشآت والعقود، من خلال ربط أنظمتهم الداخلية بمنصات سوق العمل، مما يمكّنهم من إنجاز الإجراءات مباشرة من أنظمتهم، ويقلل الحاجة إلى التنقل بين المنصات والعمليات اليدوية المتكررة.","وتأتي مشاركة تكامل في «ليب 2026» امتداداً لحرصها على الحضور في المؤتمرات والمعارض المتخصصة، بما يتيح لها التواصل مع المستفيدين والشركاء، والتعريف بحلولها وخدماتها، وتبادل الخبرات والمعرفة مع الجهات ذات العلاقة، والاطلاع على أحدث التوجهات والتقنيات في مجالات عملها."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/-ZqiUAQ','https://sabq.org/article/-ZqiUAQ','','https://sabq.org/article/-ZqiUAQ','صحيفة سبق','المدينة المنورة','2026-09-03T22:59:00.000Z','2026-09-04T02:00:00.000Z','2026-09-04T05:06:18.614Z','https://media.sabq.org/news/2026/09/712c1ff1-af24-40bf-83c7-78eafd44d3f6/w1600.webp','/api/media/70604dbe-f52e-40e6-8317-5e2fdb5f6987','/api/media/70604dbe-f52e-40e6-8317-5e2fdb5f6987?variant=thumbnail','تكامل القابضة تختتم مشاركتها في «ليب 2026» بتوقيع 34 اتفاقية وإطلاق منتج «تزامن»',1600,1066,'valid','published','archived','valid',47,'6c1920e61b4e8f4364b438f3079ec69884b99266a1a985e9309c5b27c6da9484','c9264ec82d2a5a7cd5415f5ae454f005779fd6342784965b92abd164d9e35cd2','محدّث','2026-09-04T05:06:18.614Z','2026-10-07T19:44:57.069Z','','',0,0,'saudi_region','مهم',63,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:44:57.069Z',200,57,0,'source_article_available','',NULL,NULL,'body:55baa7c94990c6be5a095231d6dccda296c093f1514d0a2a73d871898e0e2763','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6734b315-36b9-4975-a1d8-5a9a7551ade6','news-6734b315-36b9-4975-a1d8-5a9a7551ade6','«الأرصاد»: أمطار رعدية غزيرة وسيول وبرد على نجران وجازان وعسير والباحة.. ورياح مثيرة للغبار على الرياض والشرقية','الارصاد امطار رعديه غزيره وسيول وبرد علي نجران وجازان وعسير والباحه ورياح مثيره للغبار علي الرياض والشرقيه','وفي المقابل، يستمر تأثير الرياح النشطة المثيرة للأتربة والغبار على أجزاء من تلك المناطق، وعلى أجزاء من منطقتي الرياض والشرقية، وأجزاء من مناطق تبوك والمدينة المنورة ومكة المكرمة، خاصة الساحلية منها.','["توقّع المركز الوطني للأرصاد، في تقريره عن حالة الطقس لهذا اليوم الجمعة، هطول أمطار رعدية متوسطة إلى غزيرة تؤدي إلى جريان السيول، مصحوبة بزخات من البرد، على أجزاء من مناطق نجران وجازان وعسير والباحة، تمتد إلى الأجزاء الجنوبية من مرتفعات منطقة مكة المكرمة.","حالة البحر وأشار التقرير إلى أن حركة الرياح السطحية على البحر الأحمر ستكون شمالية غربية إلى شمالية بسرعة 20 إلى 40 كم/ساعة، وارتفاع الموج من متر إلى مترين، وحالة البحر متوسط الموج.","أما على الخليج العربي فستكون الرياح السطحية جنوبية شرقية إلى جنوبية غربية بسرعة 10 إلى 30 كم/ساعة، وارتفاع الموج من نصف متر إلى متر ونصف، وحالة البحر خفيف إلى متوسط الموج."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wjrvh10','https://sabq.org/article/wjrvh10','','https://sabq.org/article/wjrvh10','صحيفة سبق','الرياض','2026-09-03T23:11:00.000Z','2026-09-04T02:12:00.000Z','2026-09-04T05:17:47.386Z','','','','«الأرصاد»: أمطار رعدية غزيرة وسيول وبرد على نجران وجازان وعسير والباحة.. ورياح مثيرة للغبار على الرياض والشرقية',NULL,NULL,'all_candidates_failed (og:fetch failed | structured:fetch failed | structured:fetch failed | structured:fetch failed)','published','archived','valid',99,'48e0af17c3083bbbad92eccfd868174ebdbdac714a2339439f1f608631fcbf26','13efa34014a4234406aefd5062a17fc48cd67ff0a38d1397f5db1026b3ba841a','محدّث','2026-09-04T05:17:47.386Z','2026-10-07T20:24:32.870Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة","عسير","تبوك","جازان","نجران","الرياض","الباحة"]','["الطقس والمناخ","الخليج العربي","المدينة المنورة"]','classified','','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:51:25.853Z',200,48,0,'source_article_available','',NULL,NULL,'body:2ae96f076f24e02b715b292245ef610b0254465a56081533b20992f5df54d9b2','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3aa2fa51-b891-4808-9d5f-2e4d9cb707e9','news-3aa2fa51-b891-4808-9d5f-2e4d9cb707e9','المشرف على «مدارس»: المنصة توحد خدمات التعليم الخاص في رحلة رقمية متكاملة','المشرف علي مدارس المنصه توحد خدمات التعليم الخاص في رحله رقميه متكامله','عبد الرحمن السبيهين، إن المنصة توحد خدمات التعليم الخاص في رحلة رقمية متكاملة تربط الطلاب وأولياء الأمور والمدارس ومقدمي الخدمات. وأشار إلى أن المنصة تهدف إلى تطوير تجربة المستفيد ورفع كفاءة وجودة الخدمات المقدمة، وتوفير بيانات متكاملة تساعد على فهم احتياجات المشاركين.','["قال المشرف على منصة «مدارس»، م. عبد الرحمن السبيهين، إن المنصة توحد خدمات التعليم الخاص في رحلة رقمية متكاملة تربط الطلاب وأولياء الأمور والمدارس ومقدمي الخدمات.","وأضاف خلال مداخلة مع قناة « الإخبارية » أن هذه الرحلة تبدأ من عملية البحث عن المدرسة والتسجيل والدفع وصولا إلى الخدمات التعليمية المرتبطة.","وأشار إلى أن المنصة تهدف إلى تطوير تجربة المستفيد ورفع كفاءة وجودة الخدمات المقدمة، وتوفير بيانات متكاملة تساعد على فهم احتياجات المشاركين."]','التعليم','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/n24dasg58','https://ajel.sa/local/n24dasg58','https://ajel.sa/local/n24dasg58','https://ajel.sa/local/n24dasg58','فريق التحرير','','2026-09-03T23:30:00.000Z','Mon, 07 Sep 2026 01:22:22 GMT','2026-09-04T05:35:46.242Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D9%85%D9%86%D8%B5%D8%A9-%D9%85%D8%AF%D8%A7%D8%B1%D8%B3-wDZhhpJq.jpg','/api/media/3aa2fa51-b891-4808-9d5f-2e4d9cb707e9','/api/media/3aa2fa51-b891-4808-9d5f-2e4d9cb707e9?variant=thumbnail','المشرف على «مدارس»: المنصة توحد خدمات التعليم الخاص في رحلة رقمية متكاملة',1200,675,'valid','published','archived','valid',41,'4c80d3e016e0a42064535b233b8e8b0947bb980312a082c6b3941d639a47d1ee','9cca66f059dfa456b1a4a999337d8e20d7e325afb614a6a89f3da689039d162d','محدّث','2026-09-04T05:35:46.242Z','2026-10-07T20:24:32.875Z','','',0,0,'international','عادي',39,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","التقنية والتحول الرقمي"]','["التعليم والتدريب","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T20:22:40.367Z',NULL,37,4,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('78f3c74a-eef6-433f-8e08-2fe1efc8870c','news-78f3c74a-eef6-433f-8e08-2fe1efc8870c','مسؤول: مؤتمر طب أسنان الأطفال بعسير يستعرض أحدث المستجدات في المجال بمشاركة نخبة من الخبراء','مسؤول مؤتمر طب اسنان الاطفال بعسير يستعرض احدث المستجدات في المجال بمشاركه نخبه من الخبراء','محمد آل شايع، الرئيس التنفيذي لمؤتمر طب أسنان الأطفال في عسير ، إن المؤتمر يستعرض أحدث المستجدات والتطورات في طب أسنان الأطفال بمشاركة نخبة من الخبراء والمتخصصين والمتحدثين. وأضاف خلال مداخلة مع قناة «الإخبارية» أن المؤتمر يشمل العديد من المحاضرات والتخصصات المرتبطة بطب أسنان الأطفال.','["قال د. محمد آل شايع، الرئيس التنفيذي لمؤتمر طب أسنان الأطفال في عسير ، إن المؤتمر يستعرض أحدث المستجدات والتطورات في طب أسنان الأطفال بمشاركة نخبة من الخبراء والمتخصصين والمتحدثين.","وأضاف خلال مداخلة مع قناة «الإخبارية» أن المؤتمر يشمل العديد من المحاضرات والتخصصات المرتبطة بطب أسنان الأطفال.","وأوضح آل شايع أن المؤتمر شهد حضورا بارزا من مختلف مناطق المملكة وكذلك من عدة دول خارج المملكة.","واستضافت جامعة الملك خالد المؤتمر الدولي للجمعية السعودية لطب أسنان الأطفال لعام 2026، بمشاركة أكثر من 700 مختص وخبير عالمي لبحث التوجهات الجديدة في طب أسنان الأطفال."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/lpbtwgekk','https://ajel.sa/local/lpbtwgekk','https://ajel.sa/local/lpbtwgekk','https://ajel.sa/local/lpbtwgekk','فريق التحرير','المنطقة الشرقية','2026-09-03T23:59:00.000Z','Wed, 07 Oct 2026 21:11:20 GMT','2026-09-04T06:11:46.503Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%B7%D8%A8-%D8%A3%D8%B3%D9%86%D8%A7%D9%86-%D8%A7%D9%84%D8%A3%D8%B7%D9%81%D8%A7%D9%84-4yDdnPXR.jpg','/api/media/78f3c74a-eef6-433f-8e08-2fe1efc8870c','/api/media/78f3c74a-eef6-433f-8e08-2fe1efc8870c?variant=thumbnail','مسؤول: مؤتمر طب أسنان الأطفال بعسير يستعرض أحدث المستجدات في المجال بمشاركة نخبة من الخبراء',1200,675,'valid','published','archived','valid',46,'f62d4fce111cc0b86c57ffe9dabee0bf0a897f43b6907d1481ae9bdab7c570a5','26e5430fe9b19513f50edc1c5df56a4785c91344a67aaa974e119c155c7a5e40','محدّث','2026-09-04T06:11:46.503Z','2026-10-07T21:11:21.609Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة الملك خالد المؤتمر الدولي","التعليم والتدريب","عسير"]','["جامعة الملك خالد المؤتمر الدولي","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:11:21.609Z',200,50,0,'source_content_changed','',NULL,NULL,'body:13391cb3a03d4849c32d726cb09be4d97973d3f7dce074059ee9bcb7edb06498','Wed, 07 Oct 2026 21:11:20 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('440e65e1-4822-4d69-ae6b-c9e61345e749','news-440e65e1-4822-4d69-ae6b-c9e61345e749','وكيل «الاتصالات»: الاستثمارات في مؤتمر ليب 26 شملت جميع مكونات الذكاء الاصطناعي','وكيل الاتصالات الاستثمارات في مؤتمر ليب 26 شملت جميع مكونات الذكاء الاصطناعي','وأضاف خلال مداخلة مع قناة «الإخبارية» أن الذكاء الاصطناعي هو أحد أهم الأولويات التي تقودها المملكة حاليا، وتمضي قدما في تفعيل دورها المحوري في ربط القارات لوجستيا وفي عالم الذكاء الاصطناعي.','["قال وكيل وزارة الاتصالات وتقنية المعلومات للتكنولوجيا م. ناصر الناصر، إن الاستثمارات التي شهدها مؤتمر ليب 26 شملت جميع مكونات الذكاء الاصطناعي، سواء البنية التحتية أو التطبيقات أو النماذج اللغوية.","وانطلقت قبل عدة أيام في الرياض فعاليات النسخة الخامسة من مؤتمر ليب، تحت شعار «إلى عوالم جديدة»، بمشاركة عدد من الشركات التقنية العالمية والمحلية."]','التقنية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/nijfbsfa7','https://ajel.sa/local/nijfbsfa7','https://ajel.sa/local/nijfbsfa7','https://ajel.sa/local/nijfbsfa7','فريق التحرير','الرياض','2026-09-03T23:46:00.000Z','Wed, 07 Oct 2026 21:11:22 GMT','2026-09-04T06:11:47.830Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D9%88%D9%83%D9%8A%D9%84-%D9%88%D8%B2%D8%A7%D8%B1%D8%A9-%D8%A7%D9%84%D8%A7%D8%AA%D8%B5%D8%A7%D9%84%D8%A7%D8%AA-gfij4lkb.jpg','/api/media/440e65e1-4822-4d69-ae6b-c9e61345e749','/api/media/440e65e1-4822-4d69-ae6b-c9e61345e749?variant=thumbnail','وكيل «الاتصالات»: الاستثمارات في مؤتمر ليب 26 شملت جميع مكونات الذكاء الاصطناعي',1200,675,'valid','published','archived','valid',40,'ba14d0e1e9f86ca81c754940871faad99535b0505c81b6cdd75f54f2c863c035','63cee7f83a6137e28672cbcda7b84308ab528018c4d9285686739619f310337a','محدّث','2026-09-04T06:11:47.830Z','2026-10-07T21:11:24.296Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الاتصالات وتقنية المعلومات للتكنولوجيا","الاقتصاد والأسواق","التقنية والتحول الرقمي","الرياض"]','["وزارة الاتصالات وتقنية المعلومات للتكنولوجيا","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:11:24.296Z',200,51,0,'source_content_changed','',NULL,NULL,'body:cef44f233972ab2bdde7e8ce25bb37023d395bb9e620ea32f85a4cf41b5df6fa','Wed, 07 Oct 2026 21:11:22 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('96ce9bd6-68b8-40dc-b680-898c2a5f84f1','news-96ce9bd6-68b8-40dc-b680-898c2a5f84f1','الرئيس الأمريكي يعين آدم تيل وزيرًا للجيش بالوكالة خلفًا لدان دريسكول','الرئيس الامريكي يعين ادم تيل وزيرا للجيش بالوكاله خلفا لدان دريسكول','أعلن الرئيس الأمريكي دونالد ترمب ، اليوم الأربعاء، تعيين آدم تيل، مساعد وزير الجيش الحالي للشؤون المدنية، وزيرًا للجيش بالوكالة، وذلك خلفًا لدان دريسكول الذي استقال مؤخرًا.','["وأوضح ترمب في منشور على منصة تروث سوشيال أن آدم تيل سيتولى المنصب بشكل فوري، مشيرًا إلى خبرته في الشؤون المدنية داخل وزارة الجيش.","وكان دان دريسكول، وزير الجيش الأمريكي، قد تقدم باستقالته في 1 سبتمبر الجاري وغادر المنصب رسميًا يوم الثلاثاء الماضي.","يُذكر أن وزير الجيش في الولايات المتحدة يُعد المسؤول المدني الأول عن الجيش البري الأمريكي، ويشرف على وزارة الجيش، وهي إحدى الإدارات العسكرية الثلاث ضمن وزارة الحرب الأمريكية ."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/vxfyzdhhi','https://ajel.sa/international/vxfyzdhhi','https://ajel.sa/international/vxfyzdhhi','https://ajel.sa/international/vxfyzdhhi','فريق التحرير','','2026-09-04T00:36:00.000Z','Wed, 07 Oct 2026 19:33:42 GMT','2026-09-04T06:52:46.740Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-2-uLebztZm.jpg','/api/media/96ce9bd6-68b8-40dc-b680-898c2a5f84f1','/api/media/96ce9bd6-68b8-40dc-b680-898c2a5f84f1?variant=thumbnail','الرئيس الأمريكي يعين آدم تيل وزيرًا للجيش بالوكالة خلفًا لدان دريسكول',1200,675,'valid','published','archived','valid',41,'52d86d4defe54df5106a01d99d2d67965547e250d180f28022102f26e9b7e5b8','329940a7b2a3097a383e4c12d231f74cdd25ce5730cf46227f007cbd84b9928a','محدّث','2026-09-04T06:52:46.740Z','2026-10-07T20:24:32.883Z','','',0,0,'international','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير ا للجيش بالوكالة خلف","وزارة الجيش وكان دان دريسكول","الولايات المتحدة"]','["وزير ا للجيش بالوكالة خلف","وزارة الجيش وكان دان دريسكول","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:33:43.806Z',200,45,0,'source_content_changed','',NULL,NULL,'body:b1fafdb40b43681a6ed30c52c127b941893c9c6ef28c71baa9301c06807969b0','Wed, 07 Oct 2026 19:33:42 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0fd1c90b-f799-4956-958b-fde6a2263491','news-0fd1c90b-f799-4956-958b-fde6a2263491','متحدث «سدايا»: عرضنا 12 منتجًا جديدًا خلال مؤتمر «ليب 2026»','متحدث سدايا عرضنا 12 منتجا جديدا خلال مؤتمر ليب 2026','قال متحدث الهيئة السعودية للبيانات والذكاء الاصطناعي ، «سدايا»، سعيد الشهراني ، إن «الهيئة عرضت 12 منتجًا جديدًا خلال مؤتمر ليب 2026». وانطلقت قبل عدة أيام في الرياض فعاليات النسخة الخامسة من مؤتمر ليب، تحت شعار «إلى عوالم جديدة»، بمشاركة عدد من الشركات التقنية العالمية والمحلية.','["قال متحدث الهيئة السعودية للبيانات والذكاء الاصطناعي ، «سدايا»، سعيد الشهراني ، إن «الهيئة عرضت 12 منتجًا جديدًا خلال مؤتمر ليب 2026».","وأضاف خلال مداخلة مع قناة «الإخبارية» أن «هذه المنتجات تتنوع إلى قسمين، الأول مختص بالأفراد، والآخر مختص بالجهات الحكومية».","وأشار «الشهراني» إلى وجود قسم خاص بالجمعيات الخيرية والمؤسسات الغير ربحية، لافتا إلى أن الهيئة احتفلت باكتمال دمج خدمات الجهات الحكومية عبر تطبيق « توكلنا ».","وانطلقت قبل عدة أيام في الرياض فعاليات النسخة الخامسة من مؤتمر ليب، تحت شعار «إلى عوالم جديدة»، بمشاركة عدد من الشركات التقنية العالمية والمحلية."]','التقنية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/mvictn42j','https://ajel.sa/local/mvictn42j','https://ajel.sa/local/mvictn42j','https://ajel.sa/local/mvictn42j','فريق التحرير','الرياض','2026-09-04T00:34:00.000Z','Wed, 07 Oct 2026 19:33:48 GMT','2026-09-04T09:09:51.923Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%B3%D8%AF%D8%A7%D9%8A%D8%A7-7kwqc77n.jpg','/api/media/0fd1c90b-f799-4956-958b-fde6a2263491','/api/media/0fd1c90b-f799-4956-958b-fde6a2263491?variant=thumbnail','متحدث «سدايا»: عرضنا 12 منتجًا جديدًا خلال مؤتمر «ليب 2026»',1200,675,'valid','published','archived','valid',58,'e227077d0ce7b752a0f3256cc6678aeff85238697a5f2243747062ddd4c85b02','84f7a18f8cf79451526b8bd3c09a18eac048ce19180e861448aabeabd79aef86','محدّث','2026-09-04T06:52:47.480Z','2026-10-07T20:24:32.886Z','','',0,0,'saudi_region','مهم',63,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي","الرياض"]','["التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:33:50.329Z',200,47,0,'source_content_changed','',NULL,NULL,'body:24b122d6f5df8672e77e5a357607a34c3cc144edc83d363d9d5540e26facceaf','Wed, 07 Oct 2026 19:33:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ee391259-d220-44e5-ab2e-fdab1d69b4d1','news-ee391259-d220-44e5-ab2e-fdab1d69b4d1','استقرار أسعار الذهب عالميًا مع توجه لمكاسب أسبوعية بسيطة','استقرار اسعار الذهب عالميا مع توجه لمكاسب اسبوعيه بسيطه','حافظت أسعار الذهب على استقرارها في المعاملات الفورية اليوم الجمعة، مع بقائها دون تغير لافت، متجهة نحو تسجيل مكاسب أسبوعية بسيطة. وفي سياق متصل، انخفض سعر الفضة في المعاملات الفورية بنسبة 0.3٪ ليبلغ 66.78 دولارًا للأوقية.','["حافظت أسعار الذهب على استقرارها في المعاملات الفورية اليوم الجمعة، مع بقائها دون تغير لافت، متجهة نحو تسجيل مكاسب أسبوعية بسيطة.","واستقر سعر الذهب في المعاملات الفورية عند 4,477.10 دولارًا للأوقية (الأونصة)، في حين تراجعت العقود الأمريكية الآجلة للذهب تسليم ديسمبر بنسبة 0.4٪ لتصل إلى 4,522.60 دولارًا للأوقية.","وفي سياق متصل، انخفض سعر الفضة في المعاملات الفورية بنسبة 0.3٪ ليبلغ 66.78 دولارًا للأوقية. كما خسر البلاتين 0.8٪ ليصل إلى 1,811.28 دولارًا، وتراجع البلاديوم بنسبة 0.4٪ ليسجل 1,415.75 دولارًا للأوقية."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/0eadbflpk','https://ajel.sa/economy/0eadbflpk','https://ajel.sa/economy/0eadbflpk','https://ajel.sa/economy/0eadbflpk','فريق التحرير','','2026-09-04T00:35:00.000Z','Wed, 07 Oct 2026 19:33:44 GMT','2026-09-04T06:52:47.486Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%B0%D9%87%D8%A8-3-JBg7qFiD.jpg','/api/media/ee391259-d220-44e5-ab2e-fdab1d69b4d1','/api/media/ee391259-d220-44e5-ab2e-fdab1d69b4d1?variant=thumbnail','استقرار أسعار الذهب عالميًا مع توجه لمكاسب أسبوعية بسيطة',1200,675,'valid','published','archived','valid',41,'1e3d86ef502b8f9d6dc05a908d29d35b130eceaa81b2068158e1f56f4723c787','9cbf185a5d9e539b9af5ca497351be5738653d4d7860d6cd37799bdd3b73b990','محدّث','2026-09-04T06:52:47.486Z','2026-10-07T20:24:32.890Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:33:46.390Z',200,47,0,'source_content_changed','',NULL,NULL,'body:cc59ea134f77be8489dc382f7a03df905f7e594c71dc37d478c1f123e5d7ba73','Wed, 07 Oct 2026 19:33:44 GMT');
