/local/b7z8shgy6','فريق التحرير','','2026-09-04T11:55:00.000Z','Wed, 07 Oct 2026 19:07:59 GMT','2026-09-04T18:08:52.792Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-t1CQNBca.jpg','/api/media/abc50908-6e27-4487-aa12-c9c2a3b27235','/api/media/abc50908-6e27-4487-aa12-c9c2a3b27235?variant=thumbnail','الدفاع المدني',1200,675,'valid','published','archived','valid',41,'45d7443c5107aabb7d8f515e18183ada90512085a89e5f5f32537c1a7c95fb15','ae77fe7d1b8595c19253158d342052414c69c28256fa381f955574122746d822','محدّث','2026-09-04T18:08:52.792Z','2026-10-07T20:24:33.215Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T19:08:00.732Z',200,41,0,'source_article_available','',NULL,NULL,'body:5417a31a4cc5b35008351476265cad34106e6f97bc2a4f0cf58f81efe10b415a','Wed, 07 Oct 2026 19:07:59 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bc7538b9-6f4e-435d-a563-7d46e0946eb8','news-bc7538b9-6f4e-435d-a563-7d46e0946eb8','بهدف عكسي من حارس المرمى.. الاتفاق يتجاوز أبها في دوري روشن','بهدف عكسي من حارس المرمي الاتفاق يتجاوز ابها في دوري روشن','وجاء هدف المباراة الوحيد في الدقيقة 80، إذ سجّل دونوفان ليون حارس مرمى أبها هدفاً عكسياً في شباكه، ليمنح الاتفاق التقدم الذي حافظ عليه حتى صافرة النهاية.','["حقّق الاتفاق فوزاً صعباً على مضيفه أبها بهدف دون ردّ، مساء الجمعة، في إطار منافسات الجولة الخامسة من دوري روشن السعودي للمحترفين، على ملعب مدينة الأمير سلطان بن عبدالعزيز في أبها، بإدارة الحكم محمد الشهراني.","وبهذا الفوز، رفع الاتفاق رصيده إلى 9 نقاط في جدول ترتيب دوري روشن، فيما واصل أبها معاناته في ذيل الترتيب مكتفياً بنقطة واحدة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/aLZo3X7','https://sabq.org/article/aLZo3X7','','https://sabq.org/article/aLZo3X7','صحيفة سبق','عسير','2026-09-04T12:13:00.000Z','2026-09-04T15:14:00.000Z','2026-09-04T18:17:54.128Z','https://media.sabq.org/news/2026/09/200f7d10-21f5-45d8-9984-7ff2360b34a7/w1600.webp','/api/media/bc7538b9-6f4e-435d-a563-7d46e0946eb8','/api/media/bc7538b9-6f4e-435d-a563-7d46e0946eb8?variant=thumbnail','بهدف عكسي من حارس المرمى.. الاتفاق يتجاوز أبها في دوري روشن',1600,2000,'valid','published','archived','valid',99,'079b6b058299b142cdfcaa245d8c32c9171a8d54d9580997ac2aeeff7e4cf97a','da2c9879cb254c32dc8063fd713793671ad5af40ffd59fd33c491c6e42d90198','محدّث','2026-09-04T18:17:54.128Z','2026-10-07T19:34:54.997Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T19:34:54.997Z',200,34,0,'source_article_available','',NULL,NULL,'body:9ab9ef64f16f38b6096d04ba37afd2f815b87566b8069e2d5190964387a247aa','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('64a071ea-1bf6-4cfd-85dd-24be2cfcbaed','news-64a071ea-1bf6-4cfd-85dd-24be2cfcbaed','الخثلان: تأكد من سلامتك الصحية قبل نسب أعراضك إلى الحسد أو السحر','الخثلان تاكد من سلامتك الصحيه قبل نسب اعراضك الي الحسد او السحر','وبيّن أن من يعاني أعراضاً معينة ينبغي أن يراجع الأطباء المختصين للتأكد من عدم وجود مرض عضوي، فإن أكدوا سلامته انتقل إلى الأطباء النفسيين، فإن قالوا إنه سليم «هنا ينتقل بعد ذلك لمسألة هل هو عنده مس أو عين أو سحر».','["أكد الشيخ الدكتور سعد بن تركي الخثلان، الأستاذ في كلية الشريعة بجامعة الإمام محمد بن سعود الإسلامية والمدرّس في الحرمين الشريفين، أهمية التأكد أولاً من عدم وجود أمراض عضوية أو نفسية، قبل أن ينسب الإنسان ما يعانيه من أعراض إلى الحسد أو السحر أو المس.","وأوضح الخثلان، في رده على قناة الرسالة حول أعراض المحسود والممسوس والمسحور وطرق العلاج، أن أعراض هذه الحالات قد تشتبه ببعض الأمراض العضوية والنفسية، ولذلك «لا بد أولاً من أن يتأكد» الإنسان من سلامته منها.","وأشار إلى أن بعض الأشخاص قد يصف نفسه بأنه محسود أو مسحور أو ممسوس من باب الهروب من الواقع، موضحاً أن الإنسان قد يميل نفسياً إلى إلقاء مسؤولية ما يواجهه على «طرف خارجي».","وتطرق الخثلان إلى العين، موضحاً أنها ربما تكون الأوضح، خصوصاً إذا كان أحد الأشخاص قد وصف الإنسان وصفاً معيناً ثم أصيب بعد ذلك الوصف مباشرة أو بعد المجلس بمشكلات، مشيراً إلى أن ذلك قد يكون قرينة على الإصابة بالعين.","وأوضح أن أسرع طريق لإزالة أثر العين هو أن يُؤخذ من العائن، مستدلاً بما ورد في السنة النبوية من أمر النبي صلى الله عليه وسلم الرجل الذي أُصيب بالعين بأن يأخذ من الماء الذي توضأ به العائن، مبيناً أن من أصيب بالعين إذا أخذ من أثر العائن «بإذن الله يزول أثر العين مباشرة».","وقال إن العين مرتبطة بالأرواح، وإن طريقة الإصابة بها وطريقة زوال أثرها «فوق مستوى عقول البشر»، مؤكداً أن المسلم يؤمن بما دلت عليه النصوص إلى جانب ما ثبت بالتجارب عبر الناس منذ قديم الزمان.","وفيما يتعلق بالسحر والمس، أوضح الخثلان أن أعراضهما قد تشتبه كذلك بالأمراض النفسية، مشيراً إلى أن وجود بعض الأعراض عند قراءة آيات السحر على الشخص، كالشعور بالضيق والحرج، «ربما تكون هذه قرينة» على الإصابة.","وأضاف أن المس غالباً ما يكون مرتبطاً بالسحر، مؤكداً أن حالات المس «قليلة» وليست بالكثرة التي يشيعها بعض الناس، وأنها في الغالب مرتبطة بالسحر."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/aQAUrfm','https://sabq.org/article/aQAUrfm','','https://sabq.org/article/aQAUrfm','عبدالحكيم شار','المدينة المنورة','2026-09-04T12:10:00.000Z','2026-09-04T15:10:00.000Z','2026-09-04T18:17:55.053Z','https://media.sabq.org/news/2026/09/706fc470-b523-429e-a18f-731d1bddcd67/w1116.webp','/api/media/64a071ea-1bf6-4cfd-85dd-24be2cfcbaed','/api/media/64a071ea-1bf6-4cfd-85dd-24be2cfcbaed?variant=thumbnail','الخثلان: تأكد من سلامتك الصحية قبل نسب أعراضك إلى الحسد أو السحر',1116,624,'valid','published','archived','valid',41,'c4b1d7a14d7193ad9b01d5d208d0424c38448f7a54dc22012764c5ae34ae6446','30212d888cbfe74c95d2980fb6ab353eb03dad1894a5623abbbe9c4c017838b3','محدّث','2026-09-04T18:17:55.053Z','2026-10-07T20:24:33.222Z','','',0,0,'saudi_region','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","التعليم والتدريب"]','["الصحة العامة","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:34:57.250Z',200,35,0,'source_article_available','',NULL,NULL,'body:b9c10bf17d346d77a23f80209ea94f8bdf78f5941da4a81de4cd0689bdfc6954','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('47e1b46a-7ab8-4125-9365-3fab24decaa9','news-47e1b46a-7ab8-4125-9365-3fab24decaa9','أخضر الشاطئية يحقق أفضل تصنيف في تاريخه بالمركز 97 عالمياً','اخضر الشاطئيه يحقق افضل تصنيف في تاريخه بالمركز 97 عالميا','وشهد عام 2022 قفزات كبيرة للمنتخب في سلم التصنيف العالمي، بعدما وصل إلى المركز 50 عالمياً، ثم تقدم إلى المركز 35، قبل أن ينهي العام في المركز 31 عالمياً.','["حقق المنتخب السعودي لكرة القدم الشاطئية أفضل تصنيف في تاريخه، بعدما ارتفع خلال شهر سبتمبر الجاري إلى المركز السابع عشر عالمياً والخامس آسيوياً، وفق التصنيف العالمي الصادر عن منظمة كرة القدم الشاطئية «Beach Soccer».","ويأتي هذا التقدم امتداداً للمسيرة التصاعدية لأخضر الشاطئية منذ عودته للمشاركة الدولية عام 2019، بعد توقف استمر قرابة خمسة أعوام، إذ بدأ رحلة العودة من المركز 114 عالمياً، قبل أن يتقدم إلى المركز 98 عام 2020، ثم المركز 95 عام 2021.","وواصل أخضر الشاطئية تقدمه خلال عام 2023، بصعوده إلى المركز 29 عالمياً، ثم المركز 25، وصولاً إلى المركز 23 عالمياً الذي كان حينها أفضل تصنيف في تاريخ المنتخب.","ويعكس وصول الأخضر إلى المركز السابع عشر عالمياً والخامس آسيوياً التطور المتواصل للمنتخب، الذي نجح في تجاوز 97 مركزاً منذ انطلاق مسيرته الدولية من جديد عام 2019."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/mPtaCty','https://sabq.org/article/mPtaCty','','https://sabq.org/article/mPtaCty','صحيفة سبق','','2026-09-04T12:07:00.000Z','2026-09-04T15:07:00.000Z','2026-09-04T18:17:55.075Z','https://media.sabq.org/news/2026/09/3d804eb4-96ae-4704-8c01-47315cf555f3/w800.webp','/api/media/47e1b46a-7ab8-4125-9365-3fab24decaa9','/api/media/47e1b46a-7ab8-4125-9365-3fab24decaa9?variant=thumbnail','أخضر الشاطئية يحقق أفضل تصنيف في تاريخه بالمركز 97 عالمياً',800,511,'valid','published','archived','valid',59,'69eec1af1999bf4ae270b5d62555e2da185a36000a4e78ba46f0b033f00180e5','0306266bc089f0ec278d99aa3406a424890a8598df8c79d4fff91a0060f226b3','محدّث','2026-09-04T18:17:55.075Z','2026-10-07T19:34:47.133Z','','',0,0,'international','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T19:34:47.133Z',200,38,0,'source_article_available','',NULL,NULL,'body:0a608e7860e09cf84173a232c701e945fa118d0ac14286d91558bffe3c48927b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('33f13d38-e447-4c19-a734-8656aab47ace','news-33f13d38-e447-4c19-a734-8656aab47ace','محمية الملك سلمان الملكية تشدّد على منع الصيد بالمناطق التي تقع في نطاقها','محميه الملك سلمان الملكيه تشدد علي منع الصيد بالمناطق التي تقع في نطاقها','وتهدف الهيئة من خلال هذا الإجراء إلى تعزيز التوازن البيئي والمحافظة على التنوع في المحمية والمناطق التابعة لها والحد من الآثار السلبية التي يسبّبها الصيد.','["في إطار الجهود المبذولة للحفاظ على البيئة الطبيعية وحماية الكائنات الفطرية من الانقراض؛ شددت هيئة تطوير محمية الملك سلمان بن عبدالعزيز الملكية على منع الصيد داخل نطاق المناطق التابعة لها،","وأكدت الهيئة أنها ستتخذ الإجراءات اللازمة في حق المخالفين بالتعاون مع القوات الخاصة للأمن البيئي والجهات الأخرى ذات العلاقة من أجل حماية الموارد الطبيعية؛","وشددت محمية الملك سلمان بن عبدالعزيز الملكية، إلى أن فرق الهيئة الرقابية تكثف من جهودها الميدانية باستخدام أحدث التقنيات وتطبيق القوانين والأنظمة بحق المخالفين."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/510pjfput','https://ajel.sa/local/510pjfput','https://ajel.sa/local/510pjfput','https://ajel.sa/local/510pjfput','فريق التحرير','المدينة المنورة','2026-09-04T12:04:00.000Z','Wed, 07 Oct 2026 19:43:37 GMT','2026-09-04T18:26:53.609Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-8cKRoj7B.jpg','/api/media/33f13d38-e447-4c19-a734-8656aab47ace','/api/media/33f13d38-e447-4c19-a734-8656aab47ace?variant=thumbnail','محمية الملك سلمان الملكية تشدّد على منع الصيد بالمناطق التي تقع في نطاقها',1200,675,'valid','published','archived','valid',56,'f93c1563491d1aba9790fe8370ab4e1f75994576ad1214d3b17efdc91c96c02b','81dcf768efade07d31237d26b9376d2b8fef517a1b31245127c6bb71a5597922','محدّث','2026-09-04T18:26:53.609Z','2026-10-07T19:43:39.296Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة تطوير محمية الملك سلمان","الطاقة والنفط"]','["هيئة تطوير محمية الملك سلمان","الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"الطاقة والصناعة","score":3},{"category":"البيئة والمناخ","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5}]','Updated','2026-10-07T19:43:39.296Z',200,42,0,'source_content_changed','',NULL,NULL,'body:a6fe5291f2c648e71d08a713453bd32779aef7e6af283264da509ab6b4181ab5','Wed, 07 Oct 2026 19:43:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('17cc8e85-c0dd-4ee6-9768-449e80b17343','news-17cc8e85-c0dd-4ee6-9768-449e80b17343','أميركا والترويكا الأوروبية تحشد لإحالة إيران إلى مجلس الأمن لأول مرة منذ 20 عامًا','اميركا والترويكا الاوروبيه تحشد لاحاله ايران الي مجلس الامن لاول مره منذ 20 عاما','تسعى الولايات المتحدة ودول «الترويكا الأوروبية» (بريطانيا وفرنسا وألمانيا) إلى حشد دعم أعضاء مجلس محافظي الوكالة الدولية للطاقة الذرية لتمرير قرار الأسبوع المقبل يُحيل إيران إلى مجلس الأمن الدولي للمرة الأولى منذ 20 عاماً، بحسب ما نقلته وكالة «رويترز» عن دبلوماسيين.','["ولم يُقدَّم مشروع القرار رسمياً بعد إلى المجلس، فيما لا تزال المفاوضات بشأن الصيغة النهائية للنص جارية بين الدول الأعضاء.","ويأتي مشروع القرار استكمالاً لقرار اعتمده المجلس في 12 يونيو من العام الماضي، خلص إلى أن إيران انتهكت التزاماتها المتعلقة بمنع الانتشار النووي، بسبب عدم تعاونها الكامل مع تحقيق بشأن آثار يورانيوم عُثر عليها في مواقع غير معلنة.","وفي اليوم التالي لذلك القرار، شنّت إسرائيل ضربات على المنشآت النووية الإيرانية، قبل أن تنضم إليها الولايات المتحدة، ما أدى إلى تدمير منشآت تخصيب اليورانيوم الإيرانية أو إلحاق أضرار جسيمة بها.","ومنذ تلك الضربات، لم تسمح طهران لمفتشي الوكالة الدولية للطاقة الذرية بالعودة إلى المواقع المستهدفة أو التحقق من مصير مخزوناتها من اليورانيوم المخصب، بما في ذلك كميات مخصبة بنسبة تصل إلى 60%، وهي نسبة تقترب من المستوى اللازم لصنع الأسلحة النووية.","وتعتقد الوكالة أن أكثر من 200 كيلوغرام من اليورانيوم عالي التخصيب نجا من القصف، ويُحتفظ به في مجمع أنفاق بمدينة أصفهان وفي منشأة نطنز النووية.","وقبيل الضربات الأميركية الإسرائيلية في يونيو 2025، قدّرت الوكالة الدولية للطاقة الذرية أن إيران تمتلك نحو 440 كيلوغراماً من اليورانيوم المخصب بنسبة 60%، وهي نسبة تقترب من مستوى الـ90% اللازم لصنع سلاح ذري، وتتجاوز بكثير حد الـ3.67% الذي نصّ عليه الاتفاق النووي المبرم بين إيران والقوى الكبرى عام 2015.","وتمثل الإحالة إلى مجلس الأمن تتويجاً لخلاف مستمر بين طهران والوكالة بشأن الوصول إلى المواقع النووية، بعدما اعتمد مجلس المحافظين قرارين خلال العام الماضي طالبا إيران بالإفصاح عن مخزوناتها من اليورانيوم المخصب ومنح الوكالة حق الوصول الكامل للتحقق منها.","وبصفتها طرفاً في معاهدة عدم انتشار الأسلحة النووية، تؤكد إيران أن من حقها تطوير التكنولوجيا النووية لأغراض سلمية، نافيةً أي توجه نحو إنتاج أسلحة نووية."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/8oen6uv','https://sabq.org/article/8oen6uv','','https://sabq.org/article/8oen6uv','صحيفة سبق','','2026-09-04T12:30:00.000Z','2026-09-04T15:30:00.000Z','2026-09-04T18:35:53.820Z','https://media.sabq.org/news/2026/09/00b2f118-601c-4242-83a2-abdbd915d584/w801.webp','/api/media/17cc8e85-c0dd-4ee6-9768-449e80b17343','/api/media/17cc8e85-c0dd-4ee6-9768-449e80b17343?variant=thumbnail','أميركا والترويكا الأوروبية تحشد لإحالة إيران إلى مجلس الأمن لأول مرة منذ 20 عامًا',801,450,'valid','published','archived','valid',35,'b66975cf960c9ca66575ba25876cf397713ff17fef3a6084a51a040a720c4000','5c8ab2e612815dc57248f4e2740921d4800319e36765221d7a6b630e26b08bea','محدّث','2026-09-04T18:35:53.820Z','2026-10-07T20:24:33.231Z','','',0,0,'international','عادي',56,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس الأمن لأول مرة منذ","الطاقة والنفط","السياسة والعلاقات الدولية","إيران","الولايات المتحدة"]','["مجلس الأمن لأول مرة منذ","الطاقة والنفط","السياسة والعلاقات الدولية","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:53:03.385Z',200,33,0,'source_article_available','',NULL,NULL,'body:69298c5aa8f92754b50d0e1b73af08eaa6548604dc14943083cacc3ea94d78ae','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('291865ed-c1c8-4a11-a5fb-738f231864f3','news-291865ed-c1c8-4a11-a5fb-738f231864f3','"النمر" يحذر من خرافتين قاتلتين عند الجلطات.. كل دقيقة بلا إنعاش تخفض النجاة 10%','النمر يحذر من خرافتين قاتلتين عند الجلطات كل دقيقه بلا انعاش تخفض النجاه 10','وأشار إلى أن كسور الأضلاع قد تحدث في نحو 30% من حالات الإنعاش، غير أن كل دقيقة تأخير بلا إنعاش تُخفّض فرصة نجاة المريض بنحو 10%، فضلاً عن أن الدماغ يتضرر بصورة لا رجعة فيها خلال دقائق معدودة من انقطاع التروية الدموية.','["حذّر استشاري أمراض القلب وقسطرة الشرايين الدكتور خالد النمر من معلومتين طبيتين خاطئتين تنتشران على نطاق واسع بين الناس، مشيراً إلى أنهما قد تُعرّضان حياة المرضى للخطر.","الخرافة الأولى: وخز أصابع مريض جلطة الدماغ بالإبرة أكد الدكتور النمر أن وخز أصابع مريض جلطة الدماغ بالإبرة لإخراج قطرات من الدم بهدف إعادة الدورة الدموية إلى المخ، معلومة خاطئة تماماً ولا أساس لها من الصحة، مشدداً على أن جلطة الدماغ تستلزم استدعاء سيارة الإسعاف فوراً وإجراء أشعة مقطعية عاجلة لتحديد سبب الجلطة واتخاذ الإجراءات اللازمة لإعادة التروية الدموية.","الخرافة الثانية: تجنّب الإنعاش القلبي خشية كسر الأضلاع أوضح الدكتور النمر أن الاعتقاد بأن الإنعاش القلبي يكسر الأضلاع حتماً، ومن ثَمَّ الأفضل انتظار الإسعاف دون التدخل، معلومة مضللة وخطيرة.","وخلص الاستشاري إلى أن الأولوية المطلقة هي البدء بالإنعاش القلبي فوراً عند الحاجة، مؤكداً: «الضلع يتعالج، أما تلف الدماغ فلا رجعة فيه»."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/idtqjoc','https://sabq.org/article/idtqjoc','','https://sabq.org/article/idtqjoc','صحيفة سبق','','2026-09-04T12:46:00.000Z','2026-09-04T15:46:00.000Z','2026-09-04T18:53:55.952Z','https://media.sabq.org/news/2026/09/f2dc4e25-dddf-40fb-af0c-60d3c2ff5086/w1600.webp','/api/media/291865ed-c1c8-4a11-a5fb-738f231864f3','/api/media/291865ed-c1c8-4a11-a5fb-738f231864f3?variant=thumbnail','"النمر" يحذر من خرافتين قاتلتين عند الجلطات.. كل دقيقة بلا إنعاش تخفض النجاة 10%',1600,893,'valid','published','archived','valid',35,'f027d74f49c83205f3f494444f95274dbd945b2f8f4891abcad6160497d187b4','3a23219ba766584b3cbe477d124df759cc914e3ea89d14fe81cd82d6ebcedfa8','محدّث','2026-09-04T18:53:55.952Z','2026-10-07T20:24:33.234Z','','',0,0,'gulf_arab','عادي',57,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة"]','["الصحة العامة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:18:03.918Z',200,33,0,'source_article_available','',NULL,NULL,'body:8db5fe096656217e79a0965cb4b21c35a01f65b4351c68039a719bf2313528cc','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('63b1167c-a642-489a-b5d8-200379f6ebc0','news-63b1167c-a642-489a-b5d8-200379f6ebc0','القبض على مقيم سوري بحوزته حطب محلي معروض للبيع بالشرقية','القبض علي مقيم سوري بحوزته حطب محلي معروض للبيع بالشرقيه','ضبطت القوة الخاصة لأمن الطرق ب المنطقة الشرقية ، مقيما من الجنسية السورية مخالفا لنظام البيئة، بحوزته حطب محلي معروض للبيع، وتم تسليم المضبوطات لجهة الاختصاص.','["ويأتي ذلك في إطار متابعة وزارة الداخلية لنشاطات تسويق الفحم والحطب المحليين داخل المدن والمحافظات وعلى الطرق التي تربط المناطق، وما ينشر بطرق غير نظامية عن هذا النشاط عبر مختلف المنصات.","وحث الأمن العام عبر حسابه على منصة \"إكس\"، على الإبلاغ عن أي حالات تمثل اعتداء على البيئة أو الحياة الفطرية على الأرقام (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض والشرقية، و (996) و (999) في بقية مناطق المملكة ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/jsncq13br','https://ajel.sa/local/jsncq13br','https://ajel.sa/local/jsncq13br','https://ajel.sa/local/jsncq13br','فريق التحرير','الرياض','2026-09-04T12:57:00.000Z','Wed, 07 Oct 2026 20:50:06 GMT','2026-09-04T19:02:52.722Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-cj8b0o3Z.jpg','/api/media/63b1167c-a642-489a-b5d8-200379f6ebc0','/api/media/63b1167c-a642-489a-b5d8-200379f6ebc0?variant=thumbnail','القبض على مقيم سوري بحوزته حطب محلي معروض للبيع بالشرقية',1200,675,'valid','published','archived','valid',40,'f1de0febbbb36ec7d4b2f559651f4c798dd78f93d8ac956cd11a59e48a6c1727','b32345e0468a3caa806a0b87b3ac4c9d39b3cee6a93d26e31dc392e30f064759','محدّث','2026-09-04T19:02:52.722Z','2026-10-07T20:50:08.575Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية لنشاطات تسويق الفحم","مكة","الرياض","المدينة المنورة"]','["وزارة الداخلية لنشاطات تسويق الفحم","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"البيئة والمناخ","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T20:50:08.575Z',200,50,0,'source_content_changed','',NULL,NULL,'body:e415d189ff2679eaad6a8daaa6067ca851f4a5a80584fcd1aec28316db158c8e','Wed, 07 Oct 2026 20:50:06 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bdc7790f-69fa-481d-ae59-50d11e2a272b','news-bdc7790f-69fa-481d-ae59-50d11e2a272b','سفارة المملكة في واشنطن تعلن إغلاقها الاثنين.. واستئناف العمل الثلاثاء','سفاره المملكه في واشنطن تعلن اغلاقها الاثنين واستئناف العمل الثلاثاء','أعلنت سفارة المملكة العربية السعودية لدى الولايات المتحدة الأمريكية إغلاق مقرها يوم الاثنين الموافق 7 سبتمبر 2026، بمناسبة إجازة فدرالية، على أن تستأنف أعمالها يوم الثلاثاء 8 سبتمبر.','["ودعت السفارة المواطنين إلى أخذ ذلك في الاعتبار، موضحة أن العمل سيُستأنف بإذن الله في الموعد المحدد.","وأشارت إلى استمرار استقبال حالات الطوارئ عبر أرقام الاتصال المخصصة لذلك، وهي:","(202) 746-3555 (202) 746-0666 (202) 746-9777 (202) 746-2888"]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/q1veo0e2l','https://ajel.sa/local/q1veo0e2l','https://ajel.sa/local/q1veo0e2l','https://ajel.sa/local/q1veo0e2l','فريق التحرير','','2026-09-04T12:52:00.000Z','Wed, 