INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bdfc3cea-21c6-44e4-b740-774445beecd7','news-bdfc3cea-21c6-44e4-b740-774445beecd7','روسيا تسجّل دواءً محلياً جديداً مضاداً للجدري وجدري القرود','روسيا تسجل دواء محليا جديدا مضادا للجدري وجدري القرود','أعلنت رئيسة الهيئة الروسية لحماية حقوق المستهلك ورفاه الإنسان «روسبوتريبنادزور» آنا بوبوفا، أن روسيا سجّلت رسمياً دواءً محلياً مضاداً للجدري يحمل اسم «نيوخ-14»، مؤكدةً فعاليته في مواجهة الفيروسات المرتبطة بعائلة الجدري.','["وقالت بوبوفا في تصريحات رسمية: «تم تسجيل دواء نيوخ-14 المضاد للجدري، وهو فعّال».","ويُستخدم الدواء لعلاج العدوى الناجمة عن فيروس الجدري الطبيعي وجدري القرود وجدري البقر، وقد جرى تطويره في المركز العلمي الحكومي لعلم الفيروسات والتكنولوجيا الحيوية «فيكتور»، التابع لهيئة «روسبوتريبنادزور».","وتجدر الإشارة إلى أن منظمة الصحة العالمية أعلنت القضاء على الجدري الطبيعي عام 1980، غير أن مخاوف صحية عادت إلى الواجهة مع تفشّي جدري القرود في عدد من دول العالم، مما دفع روسيا إلى تكثيف جهودها في تطوير أدوية ولقاحات للتصدي لهذه الفيروسات."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/l25zqu5','https://sabq.org/article/l25zqu5','','https://sabq.org/article/l25zqu5','صحيفة سبق','','2026-09-05T02:32:00.000Z','2026-09-05T02:34:00.000Z','2026-09-05T12:11:06.299Z','https://media.sabq.org/news/2026/09/df4bc4ca-9adf-4b9c-a522-adfc8a6fc0d0/w980.webp','/api/media/bdfc3cea-21c6-44e4-b740-774445beecd7','/api/media/bdfc3cea-21c6-44e4-b740-774445beecd7?variant=thumbnail','روسيا تسجّل دواءً محلياً جديداً مضاداً للجدري وجدري القرود',980,551,'valid','published','archived','valid',35,'e62166ac190e87cb348a120e02e90b828e1b0ac7dea6b3f78c060c8386787150','69b440932811e53124bed99ef5d5a986eb1dc55c03774e70a5b924da25a6344d','محدّث','2026-09-05T08:36:06.914Z','2026-10-07T20:52:40.077Z','','',0,0,'international','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","روسيا"]','["الصحة العامة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:52:40.077Z',200,35,0,'source_article_available','',NULL,NULL,'body:ae9564f1ad5319b8cadc7d0bd7563e5aafff28eadd3b63eb8734a3efdcb93b1a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5b93e120-6bfa-4664-9adb-744646f9e590','news-5b93e120-6bfa-4664-9adb-744646f9e590','المرور يحذّر من ترك الأجسام على الطرق: مخالفة تهدد السلامة العامة وغرامتها تصل إلى 2000 ريال','المرور يحذر من ترك الاجسام علي الطرق مخالفه تهدد السلامه العامه وغرامتها تصل الي 2000 ريال','حذّرت الجهات المرورية من ترك الأجسام والمواد على الطرق العامة، مؤكدةً أن هذا السلوك يُشكّل مخالفة مرورية صريحة تُعرّض أرواح مستخدمي الطريق للخطر. وأوضحت الجهات المرورية في رسالة توعوية أن ترك أي جسم أو مادة على الطريق العام يستوجب غرامة مالية تتراوح بين 1000 و2000 ريال بحق مرتكب المخالفة.','["حذّرت الجهات المرورية من ترك الأجسام والمواد على الطرق العامة، مؤكدةً أن هذا السلوك يُشكّل مخالفة مرورية صريحة تُعرّض أرواح مستخدمي الطريق للخطر.","وأوضحت الجهات المرورية في رسالة توعوية أن ترك أي جسم أو مادة على الطريق العام يستوجب غرامة مالية تتراوح بين 1000 و2000 ريال بحق مرتكب المخالفة.","وشددت على أن الحفاظ على سلامة الطرق مسؤولية مشتركة تقع على عاتق جميع قائدي المركبات والأفراد، داعيةً إلى تجنّب إلقاء أي مواد أو أجسام قد تعيق حركة السير أو تُعرّض الآخرين للخطر.","وأكدت الجهات المرورية أن الالتزام بهذه التعليمات يُسهم في تعزيز منظومة السلامة المرورية وصون أرواح جميع مستخدمي الطريق."]','السيارات','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/xo8irza','https://sabq.org/article/xo8irza','','https://sabq.org/article/xo8irza','صحيفة سبق','','2026-09-05T02:30:00.000Z','2026-09-05T05:31:00.000Z','2026-09-05T08:36:06.921Z','https://media.sabq.org/news/2026/09/43ffcc1c-4328-4659-bbaa-ac75c2456381/w1600.webp','/api/media/5b93e120-6bfa-4664-9adb-744646f9e590','/api/media/5b93e120-6bfa-4664-9adb-744646f9e590?variant=thumbnail','المرور يحذّر من ترك الأجسام على الطرق: مخالفة تهدد السلامة العامة وغرامتها تصل إلى 2000 ريال',1600,1600,'valid','published','archived','valid',47,'7b0736036f7a5f07d51aa5c067dc6dddb58f33d63b99a5db7f0454dc40156efb','29e1a1ed21def4ddf681d4c095e8c0055a61c49b14194ffb825cd88201c01ccf','محدّث','2026-09-05T08:36:06.921Z','2026-10-07T20:52:44.353Z','','',0,0,'international','عادي',45,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:52:44.353Z',200,35,0,'source_article_available','',NULL,NULL,'body:b372b845d3b55180cd4107192fa366106cbb1f73d92106853087e37ff545ea56','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fbcdf837-0aef-46c5-af6f-f330ddb7da51','news-fbcdf837-0aef-46c5-af6f-f330ddb7da51','ارتفاع حصيلة ضحايا غارات الاحتلال الإسرائيلي على لبنان إلى 5 أشخاص','ارتفاع حصيله ضحايا غارات الاحتلال الاسرائيلي علي لبنان الي 5 اشخاص','أعلنت وزارة الصحة اللبنانية ارتفاع حصيلة ضحايا غارات قوات الاحتلال الإسرائيلية على الجنوب و البقاع الغربي إلى 5 أشخاص. وكان رئيس مجلس النواب اللبناني نبيه بري ، قد دعا إلى مقاربة وطنية شاملة لمواجهة الحرب الإسرائيلية، محذرًا من مخاطر وجودية يواجهها جنوب لبنان ، ومؤكدًا رفض أي استهداف للجيش اللبناني أو التشكيك في دوره.','["أعلنت وزارة الصحة اللبنانية ارتفاع حصيلة ضحايا غارات قوات الاحتلال الإسرائيلية على الجنوب و البقاع الغربي إلى 5 أشخاص.","وكان رئيس مجلس النواب اللبناني نبيه بري ، قد دعا إلى مقاربة وطنية شاملة لمواجهة الحرب الإسرائيلية، محذرًا من مخاطر وجودية يواجهها جنوب لبنان ، ومؤكدًا رفض أي استهداف للجيش اللبناني أو التشكيك في دوره.","وقال بري، في كلمة ألقاها في الذكرى الثامنة والأربعين لتغييب السيد موسى الصدر ورفيقيه، إن دولة الاحتلال تدمر البنية التحتية للبنان، داعيًا إلى وحدة اللبنانيين لمواجهة التحديات."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/rqla8bh5a','https://ajel.sa/international/rqla8bh5a','https://ajel.sa/international/rqla8bh5a','https://ajel.sa/international/rqla8bh5a','فريق التحرير','','2026-09-05T02:18:00.000Z','Wed, 07 Oct 2026 20:58:50 GMT','2026-09-05T08:40:08.954Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%8A%D8%B1%D8%A7%D9%86-1-6iqDZwlR.jpg','/api/media/fbcdf837-0aef-46c5-af6f-f330ddb7da51','/api/media/fbcdf837-0aef-46c5-af6f-f330ddb7da51?variant=thumbnail','ارتفاع حصيلة ضحايا غارات الاحتلال الإسرائيلي على لبنان إلى 5 أشخاص',1200,675,'valid','published','archived','valid',41,'02c2d02fc2db20c0c744adc549faec61227e4beef58ee242dd14335756ff8f4e','49c6358efc4bb837d605e47d0022748efc9df556557edd8e8518331f6e15391c','محدّث','2026-09-05T08:40:08.954Z','2026-10-07T20:58:51.617Z','','',0,0,'gulf_arab','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس النواب اللبناني نبيه بري","رئيس مجلس النواب اللبناني نبيه","وزارة الصحة اللبنانية ارتفاع حصيلة","الصحة العامة","لبنان"]','["مجلس النواب اللبناني نبيه بري","رئيس مجلس النواب اللبناني نبيه","وزارة الصحة اللبنانية ارتفاع حصيلة","الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:58:51.617Z',200,29,0,'source_content_changed','',NULL,NULL,'body:6617c0cb22d90089179399279693db74a09e181704e57cc8839bb6bf19e4bc83','Wed, 07 Oct 2026 20:58:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cd5f9595-64cc-4f21-b73c-91e2abb8f19d','news-cd5f9595-64cc-4f21-b73c-91e2abb8f19d','إعلام إيراني: استهداف أمريكي لناقلة نفط إيرانية قرب جزيرة خارك','اعلام ايراني استهداف امريكي لناقله نفط ايرانيه قرب جزيره خارك','أكدت وسائل إعلام إيرانية استهداف الجيش الأمريكي لناقلة نفط إيرانية بالقرب من جزيرة خارك . كانت تانكر تراكرز لبيانات الملاحة، أكدت رصد 17 عملية نقل نفط وغاز بين السفن في خليج عمان أمس شملت نحو 24 مليون برميل.','["أكدت وسائل إعلام إيرانية استهداف الجيش الأمريكي لناقلة نفط إيرانية بالقرب من جزيرة خارك .","وأضافت، أن الهجوم الأمريكي استهدف ناقلة نفط صغيرة من دون وقوع خسائر بشرية، وفق \"العربية\".","كانت تانكر تراكرز لبيانات الملاحة، أكدت رصد 17 عملية نقل نفط وغاز بين السفن في خليج عمان أمس شملت نحو 24 مليون برميل.","وأضافت، أن ناقلات نفط وغاز تحمل 7 ملايين برميل نفط تستعد لعبور مضيق هرمز تحت حماية أمريكية."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/smo7ow4dj','https://ajel.sa/international/smo7ow4dj','https://ajel.sa/international/smo7ow4dj','https://ajel.sa/international/smo7ow4dj','فريق التحرير','','2026-09-05T02:17:00.000Z','Wed, 07 Oct 2026 20:58:50 GMT','2026-09-05T08:40:09.068Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%A7%D8%B3%D8%AA%D9%87%D8%AF%D8%A7%D9%81-%D8%B3%D9%81%D9%8A%D9%86%D8%A9-%D9%81%D9%8A-%D9%85%D8%B6%D9%8A%D9%82-%D9%87%D8%B1%D9%85%D8%B2-drbPlFGE.png','/api/media/cd5f9595-64cc-4f21-b73c-91e2abb8f19d','/api/media/cd5f9595-64cc-4f21-b73c-91e2abb8f19d?variant=thumbnail','إعلام إيراني: استهداف أمريكي لناقلة نفط إيرانية قرب جزيرة خارك',1200,675,'valid','published','archived','valid',99,'82d5331e69be005712ab7749286285a4889f131d9f8b7dacca874e4bb809e811','13834d10a26461fbe0ac302b32454ae030af9b878e723878bc6a7c2c4be802ab','محدّث','2026-09-05T08:40:09.068Z','2026-10-07T20:58:52.469Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","إيران"]','["الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T20:58:52.469Z',200,30,0,'source_content_changed','',NULL,NULL,'body:9d70d0aac12c1ca238051ba32e0cb4dad51bf62576a417fdd081e9795bec3a2a','Wed, 07 Oct 2026 20:58:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('340d4347-e847-4a76-82e3-43eb095ea01a','news-340d4347-e847-4a76-82e3-43eb095ea01a','الجيش الإسرائيلي يداهم منزلاً في ريف القنيطرة ويواصل توغلاته جنوب سوريا','الجيش الاسرائيلي يداهم منزلا في ريف القنيطره ويواصل توغلاته جنوب سوريا','وأفادت مصادر بأن قوة عسكرية إسرائيلية داهمت صباح السبت منزلاً في قرية الأصبح بريف القنيطرة الجنوبي، بالتزامن مع إطلاق نار في الهواء بهدف ترهيب المدنيين، دون الإفادة بوقوع أي حالات اعتقال.','["تواصل التصعيد العسكري الإسرائيلي في مناطق متفرقة من الجنوب السوري، لا سيما في المناطق القريبة من خط الفصل بين الجانبين.","ويواصل الجيش الإسرائيلي توغلاته العسكرية في مناطق الجنوب السوري بتغطية من الطيران الحربي والمسيّر، إذ يرصد شهود عيان جملةً من الانتهاكات الميدانية، أبرزها: ترهيب المدنيين وإطلاق النار بشكل عشوائي، وتنفيذ عمليات اعتقال شبه يومية، ونصب الحواجز والتدقيق في هويات المارة، فضلاً عن رفع السواتر الترابية ورش المبيدات، وحرمان المزارعين من الوصول إلى أراضيهم والرعاة من مراعيهم."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/qakfv8n','https://sabq.org/article/qakfv8n','','https://sabq.org/article/qakfv8n','صحيفة سبق','','2026-09-05T02:36:00.000Z','2026-09-05T05:38:00.000Z','2026-09-05T08:50:02.627Z','https://media.sabq.org/news/2026/09/e44d0e7f-e8ca-4e40-aac5-f7b8024f7202/w846.webp','/api/media/340d4347-e847-4a76-82e3-43eb095ea01a','/api/media/340d4347-e847-4a76-82e3-43eb095ea01a?variant=thumbnail','الجيش الإسرائيلي يداهم منزلاً في ريف القنيطرة ويواصل توغلاته جنوب سوريا',846,551,'valid','published','archived','valid',35,'f462778ef3286578834a2b899a4ad43af862d2fe4ff60f47ee8c5bfc7c7f5f04','6d757c4cb112c2c5b19d767c62ffe76021b8ca071cbb5dddf32943809155b68c','محدّث','2026-09-05T08:50:02.627Z','2026-10-07T20:58:48.694Z','','',0,0,'gulf_arab','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","سوريا"]','["السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:58:48.694Z',200,29,0,'source_article_available','',NULL,NULL,'body:abccff6e1431a0b8e10920929be885ad946703b487cc66f22152a2a23cd50f79','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('76f7ac6f-8a68-4bbc-970c-9ba69e29f2d3','news-76f7ac6f-8a68-4bbc-970c-9ba69e29f2d3','بيان أوروبي مشترك يجدد دعوته لكافة أطراف الحرب بالسودان إلى حماية المدنيين','بيان اوروبي مشترك يجدد دعوته لكافه اطراف الحرب بالسودان الي حمايه المدنيين','جدد بيان أوروبي مشترك دعوته لكافة أطراف الحرب في السودان إلى الالتزام بحماية المدنيين. وأدان البيان، الهجوم على قافلة مساعدات تابعة ل برنامج الأغذية العالمي في جنوب كردفان ، وفق "العربية".','["جدد بيان أوروبي مشترك دعوته لكافة أطراف الحرب في السودان إلى الالتزام بحماية المدنيين.","وأدان البيان، الهجوم على قافلة مساعدات تابعة ل برنامج الأغذية العالمي في جنوب كردفان ، وفق \"العربية\".","وأضاف البيان الأوروبي، أن الهجمات ضد العاملين في المجال الإنساني في السودان تنتهك القانون الدولي.","كانت قوات الدعم السريع استهدفت قافلة مساعدات إنسانية تتبع للأمم المتحدة بمدينة الدلنج، كانت في طريقها إلى مدينة كادقلي بولاية جنوب كردفان، وتسببت في مقتل شخص وإصابة اثنين آخرين من سائقي الشاحنات."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/xye3oqfon','https://ajel.sa/international/xye3oqfon','https://ajel.sa/international/xye3oqfon','https://ajel.sa/international/xye3oqfon','فريق التحرير','','2026-09-05T02:38:00.000Z','Wed, 07 Oct 2026 20:59:49 GMT','2026-09-05T08:59:02.106Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-06/7chZOs9ymF07TtYZ.jpg','/api/media/76f7ac6f-8a68-4bbc-970c-9ba69e29f2d3','/api/media/76f7ac6f-8a68-4bbc-970c-9ba69e29f2d3?variant=thumbnail','بيان أوروبي مشترك يجدد دعوته لكافة أطراف الحرب بالسودان إلى حماية المدنيين',1200,675,'valid','published','archived','valid',41,'a35921675ee66342ae4d36a4392c7ba1790b384af46af36c1afd21b2e4cf958b','8f579cf6770a4d875c95dbc8153be261d5cb2757ec676767772e812b7af9cc9f','محدّث','2026-09-05T08:59:02.106Z','2026-10-07T20:59:51.456Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:59:51.456Z',200,34,0,'source_content_changed','',NULL,NULL,'body:db02830420c969a6f0db4a0bbbd2291ff6370217e10e6e838581c4ee60b6f0f4','Wed, 07 Oct 2026 20:59:49 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f2912a2c-120c-4869-b995-1a7303df6b7b','news-f2912a2c-120c-4869-b995-1a7303df6b7b','تقارير استخباراتية تكشف تصعيد إيران لإطالة الحرب وإرباك ترامب قبل انتخابات التجديد النصفي','تقارير استخباراتيه تكشف تصعيد ايران لاطاله الحرب وارباك ترامب قبل انتخابات التجديد النصفي','حذرت تقارير استخباراتية أميركية من تصعيد إيراني محتمل في الشرق الأوسط ، مع تزايد ثقة طهران بقدرتها على مهاجمة أهداف إقليمية، وسعيها لإطالة أمد الصراع بهدف إنهاك الولايات المتحدة وإرباك الرئيس دونالد ترامب قبل انتخابات التجديد النصفي، بحسب صحيفة " نيويورك تايمز ". من جهته، كان ترامب قد توقع نصراً سريعاً عند بدء الحرب في 28 فبراير، إلا أن منتقديه يرون أن…','["وأشارت التقارير إلى أن إيران نفذت مؤخراً هجمات على سفن في مضيق هرمز وقوات أميركية، بينما ردت واشنطن بضربات داخل إيران أوقعت قتلى بين العسكريين والمدنيين.","ورغم محدودية التبادلات العسكرية حتى الآن، رجحت المصادر أن طهران تدرس تصعيداً أكبر، مستفيدة من فهم أعمق لنقاط قوتها العسكرية.","وأكد مسؤولون أميركيون أن إيران قد تكرر هجمات مماثلة لتلك التي وقعت في يوليو، حين استهدفت قواعد أميركية في الشرق الأوسط وأسفرت عن مقتل ثلاثة أميركيين في الأردن ، إضافة إلى هجمات إلكترونية طالت أكثر من 100 نظام مياه في الولايات المتحدة، ورغم عدم تضرر إمدادات المياه، تسببت الهجمات في اضطرابات تشغيلية وتحذيرات احترازية.","وأوضح المسؤولون أن القراصنة المرتبطين بإيران أعادوا تنظيم صفوفهم، مع استمرار محاولاتهم استهداف البنية التحتية للطاقة، وتبقى الهجمات الإلكترونية وسيلة مفضلة لإيران لتقويض الدعم الشعبي الأميركي للحرب.","وفي إفادة صحفية، قلل نائب الرئيس الأميركي جي دي فانس من حجم التهديد، مؤكداً أن قدرة إيران على تعطيل الحياة اليومية للأميركيين محدودة، لكنه أشار إلى استمرار محاولات طهران استهداف الولايات المتحدة.","من جهته، كان ترامب قد توقع نصراً سريعاً عند بدء الحرب في 28 فبراير، إلا أن منتقديه يرون أن الإدارة الأميركية قللت من قدرة إيران على الصمود.","وأوضح النائب جايسون كرو أن القيادة الإيرانية أصبحت أكثر توحداً وتمتلك مخزوناً من الصواريخ والطائرات المسيّرة، مع تعزيز سيطرتها على مضيق هرمز."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/t3i0gzi46','https://ajel.sa/international/t3i0gzi46','https://ajel.sa/international/t3i0gzi46','https://ajel.sa/international/t3i0gzi46','فريق التحرير','','2026-09-05T02:56:00.000Z','Wed, 07 Oct 2026 21:18:42 GMT','2026-09-05T09:13:25.488Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%A3%D9%85%D8%B1%D9%8A%D9%83%D8%A7-%D9%88%D8%A5%D9%8A%D8%B1%D8%A7%D9%86-zQbiuP9P.jpg','/api/media/f2912a2c-120c-4869-b995-1a7303df6b7b','/api/media/f2912a2c-120c-4869-b995-1a7303df6b7b?variant=thumbnail','تقارير استخباراتية تكشف تصعيد إيران لإطالة الحرب وإرباك ترامب قبل انتخابات التجديد النصفي',1200,675,'valid','published','archived','valid',40,'fe8618fdf78866ab3c7c7dc507b2ac3cd065116d37722a5a25ecdc6aeb1bcd0e','84730819a83a4fdd1e319e76fbdaf8cc3409f8c884c49b63e5af8f045a23f699','محدّث','2026-09-05T09:13:25.488Z','2026-10-07T21:18:44.014Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة ميتا بتورط حسابات إيرانية","الطاقة والنفط","السفر والسياحة","السياسة والعلاقات الدولية","إيران","الشرق الأوسط","الولايات المتحدة"]','["شركة ميتا بتورط حسابات إيرانية","الطاقة والنفط","السفر والسياحة","السياسة والعلاقات الدولية","الشرق الأوسط","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Active','2026-10-07T21:18:44.014Z',200,28,0,'source_article_available','',NULL,NULL,'body:7b94deb9186b231b90bb7a50d5632641f0fdf13ed98ad2cdf82550f24d4ec9ed','Wed, 07 Oct 2026 21:18:42 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('eff9646b-97d9-4c8b-a9c9-fa62c2d8b2f8','news-eff9646b-97d9-4c8b-a9c9-fa62c2d8b2f8','الصين تُجلي 599 ألف شخص في فوجيان جراء إعصار «ساوديل» وأمطار غزيرة','الصين تجلي 599 الف شخص في فوجيان جراء اعصار ساوديل وامطار غزيره','أجلت السلطات الصينية 599 ألف شخص من المناطق البرية والبحرية المعرضة للخطر في مقاطعة فوجيان شرقي البلاد، وذلك جراء موجة الأمطار الغزيرة المستمرة خلال الأيام الماضية.','["وأفاد مقر مكافحة الفيضانات والإغاثة من الجفاف بالمقاطعة، وفقاً لوكالة أنباء الصين الجديدة «شينخوا»، بأن عدة مديريات في مقاطعة فوجيان خصصت بشكل عاجل مبلغ 210 ملايين يوان، ما يعادل نحو 31 مليون دولار أمريكي، لتمويل عمليات الإنقاذ الطارئ والإغاثة والتعافي من آثار الكوارث في المناطق الأكثر تضرراً.","وفي السياق ذاته، فعّل المقر استجابة الطوارئ لمكافحة الفيضانات عند المستوى الثالث، وهو ثالث أعلى مستوى استجابة، مع الإبقاء على استجابة الطوارئ من المستوى الرابع لمواجهة الأعاصير.","وكان إعصار «ساوديل»، الإعصار الثامن عشر لعام 2026، قد وصل إلى اليابسة للمرة الثالثة في محافظة تشانغبو التابعة لمدينة تشانغتشو بمقاطعة فوجيان صباح الخميس الماضي، مما أدى إلى إجلاء عشرات الآلاف وسط تحذيرات رسمية من هبوب رياح عاتية وهطول أمطار غزيرة."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/alc4ayq','https://sabq.org/article/alc4ayq','','https://sabq.org/article/alc4ayq','صحيفة سبق','','2026-09-05T03:04:00.000Z','2026-09-05T06:05:00.000Z','2026-09-05T09:14:07.092Z','https://media.sabq.org/news/2026/09/ae5f144e-1f32-49be-9a95-ef50a907cccf/w1000.webp','/api/media/eff9646b-97d9-4c8b-a9c9-fa62c2d8b2f8','/api/media/eff9646b-97d9-4c8b-a9c9-fa62c2d8b2f8?variant=thumbnail','الصين تُجلي 599 ألف شخص في فوجيان جراء إعصار «ساوديل» وأمطار غزيرة',1000,556,'valid','published','archived','valid',50,'2811e8f9670e14107b338fb6ca42f6879e6d60551510635a8059a11e25174f53','de1a4ceec083db53e35f19025f16049d0534cfd6e4ddaef65f336ea4ae209119','محدّث','2026-09-05T09:14:07.092Z','2026-10-07T21:18:47.524Z','','',0,0,'international','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","الصين"]','["الطقس والمناخ"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:18:47.524Z',200,30,0,'source_article_available','',NULL,NULL,'body:c6b2f334ffb083188c223e50fe9d796f4bea8761c5f355ae09373666b3419da3','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bef599e8-cc8e-43ec-bb5d-d76f5a4ab880','news-bef599e8-cc8e-43ec-bb5d-d76f5a4ab880','دراسة: عواقب غير متوقعة للإفطار بعد الظهيرة','دراسه عواقب غير متوقعه للافطار بعد الظهيره','كشفت دراسة حديثة عن ارتباط تأخير وجبة الإفطار إلى ما بعد الظهيرة على الصحة العامة. وبحسب نتائج الدراسة ارتبط تناول وجبة الإفطار بعد الظهيرة بارتفاع خطر الوفاة الناجمة عن أمراض القلب والأوعية الدموية بنسبة 46%، وانخفاض متوسط العمر المتوقع بنحو عامين ونصف العام لدى الأشخاص الذين تجاوزوا سن الخمسين.','["كشفت دراسة حديثة عن ارتباط تأخير وجبة الإفطار إلى ما بعد الظهيرة على الصحة العامة.","وأضافت الدراسة التي عرضتها المجلة الأوروبية للتغذيات السريرية، أن الإفطار في ذلك الموعد يرفع خطر الوفاة المبكرة بنسبة 29% لدى البالغين الذين تزيد أعمارهم على 40 عامًا، لأن نوعية الغذاء توقيت تناول الطعام قد يكون عاملًا مهمًا للصحة، وفق \" سبوتنيك \".","لكن الباحثين أشاروا في الوقت نفسه إلى أن الدراسة تُظهر ارتباطًا بين توقيت تناول الطعام ومخاطر الوفاة، ولا تثبت وجود علاقة سببية مباشرة، مؤكدين أهمية النظر إلى توقيت الوجبات باعتباره عاملًا يمكن تعديله في إطار جهود تحسين الصحة العامة."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/2tu208vd9','https://ajel.sa/misc/2tu208vd9','https://ajel.sa/misc/2tu208vd9','https://ajel.sa/misc/2tu208vd9','فريق التحرير','','2026-09-05T03:14:00.000Z','Wed, 07 Oct 2026 21:19:57 GMT','2026-09-05T09:26:00.409Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop--VZSt-M1.png','/api/media/bef599e8-cc8e-43ec-bb5d-d76f5a4ab880','/api/media/bef599e8-cc8e-43ec-bb5d-d76f5a4ab880?variant=thumbnail','دراسة: عواقب غير متوقعة للإفطار بعد الظهيرة',1200,675,'valid','published','archived','valid',41,'6002a1263b0229d7c56241bb7974bf998671d0620dab0dadec1ee71aa5da059a','5ec6cab3875ae1ad95bb068aa3e09cdca10bf607ff9900b600c83e26bea5ccbc','محدّث','2026-09-05T09:26:00.409Z','2026-10-07T21:19:59.357Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة"]','["الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:19:59.357Z',200,29,0,'source_content_changed','',NULL,NULL,'body:d5168679fc155c888d12159779c387caee4c3b1572c537e2d8423a08f08d28bf','Wed, 07 Oct 2026 21:19:57 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5a00e426-918d-4ffc-a37b-77506db312f7','news-5a00e426-918d-4ffc-a37b-77506db312f7','الاتحاد الأوروبي يدين الاعتداءات الإيرانية على المملكة وعدد من دول المنطقة','الاتحاد الاوروبي يدين الاعتداءات الايرانيه علي المملكه وعدد من دول المنطقه','أدان الاتحاد الأوروبي بشدة الاعتداءات الإيرانية الأخيرة التي استهدفت كلًا من المملكة العربية السعودية ، ودولة الكويت ، و المملكة الأردنية الهاشمية ، ودولة الإمارات العربية المتحدة .','["وأعرب الاتحاد في بيانه عن إدانته الشديدة للهجمات التي استهدفت سفنًا تجارية سعودية أثناء عبورها مضيق هرمز ، مؤكدًا أن مثل هذه الأعمال تمثل انتهاكًا صارخًا للقانون الدولي.","ودعا الاتحاد الأوروبي إلى ضرورة خفض التصعيد والالتزام الكامل بقرار مجلس الأمن الدولي رقم (2817)، مطالبًا في الوقت ذاته بالامتناع عن أي إجراءات من شأنها تهديد أمن المنطقة واستقرارها، أو تقويض الجهود الرامية إلى التوصل إلى حل سلمي ودائم للنزاعات."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/vkx7fe1de','https://ajel.sa/local/vkx7fe1de','https://ajel.sa/local/vkx7fe1de','https://ajel.sa/local/vkx7fe1de','فريق التحرير','','2026-09-05T03:08:00.000Z','Wed, 07 Oct 2026 21:19:56 GMT','2026-09-05T09:26:01.667Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%A7%D9%84%D8%A7%D8%AA%D8%AD%D8%A7%D8%AF-%D8%A7%D9%84%D8%A3%D9%88%D8%B1%D9%88%D8%A8%D9%8A-Pg4C2l6Y.png','/api/media/5a00e426-918d-4ffc-a37b-77506db312f7','/api/media/5a00e426-918d-4ffc-a37b-77506db312f7?variant=thumbnail','الاتحاد الأوروبي يدين الاعتداءات الإيرانية على المملكة وعدد من دول المنطقة',1200,675,'valid','published','archived','valid',99,'6d6a6ebea2cf1541353fd3589791a9be5933d4258c436914dad0f96ddc165255','707f3b54003184414fc40c91c5358445c070d709b7f913d356847eca08e9b96d','محدّث','2026-09-05T09:26:01.667Z','2026-10-07T21:19:58.179Z','','',0,0,'saudi_national','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس الأمن الدولي رقم","إيران"]','["مجلس الأمن الدولي رقم"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:19:58.179Z',200,28,0,'source_content_changed','',NULL,NULL,'body:036ee782b979fcb80c74e39a80568036179c9a5776fbee58d79fdff1df4c6a3c','Wed, 07 Oct 2026 21:19:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2c674081-08b0-4e14-95d2-5ec1d32e724e','news-2c674081-08b0-4e14-95d2-5ec1d32e724e','وزارة الموارد البشرية والتنمية الاجتماعية وشركة روافد الدخل توقعان اتفاقية إطارية لمنتجات البيانات','وزاره الموارد البشريه والتنميه الاجتماعيه وشركه روافد الدخل توقعان اتفاقيه اطاريه لمنتجات البيانات','في خطوة عملية نحو حوكمة العمل الخيري، شهد مقر وزارة الموارد البشرية والتنمية الاجتماعية في الرياض توقيع اتفاقية إطارية لمنتجات البيانات مع شركة روافد الدخل لتقنية المعلومات , وتهدف الاتفاقية إلى تطوير منظومة رقمية مبتكرة ومتكاملة تُمكّن الفئات المشمولة بالرعاية من الوصول بسهولة إلى الخدمات والموارد التي يقدمها القطاع الخاص الداعم.','["تم التوقيع بحضور قيادات وممثلي وكالة الوزارة للتحول الرقمي والبيانات، إلى جانب قيادات شركة روافد الدخل، والفرق الفنية من الجانبين، وذلك في إطار الجهود المشتركة لدعم التحول الرقمي وتوظيف التقنية والبيانات بما يواكب مستهدفات رؤية السعودية 2030 في الارتقاء برفاهية المواطن وبناء مجتمع حيوي وشامل.","وقع الاتفاقية عن الوزارة سعادة وكيل الوزارة للتحول الرقمي المهندس / فيصل بن أحمد باخشوين، وعن شركة روافد الدخل لتقنية المعلومات الأستاذ /عبدالله بن حسن باوزير المدير التنفيذي للشركة، إيذاناً بانطلاق أعمال المنصة رسمياً.","وأعرب الجانبان عن أملهما في أن تحظى المنصة بدعم جميع الداعمين من القطاع الخاص، لتكون قناة محوكمة وموثوقة للوصول إلى مستحقي الدعم، استناداً إلى المعلومات المؤكدة لدى المركز الوطني للبيانات ووزارة الموارد البشرية والتنمية الاجتماعية.","وتعزز الاتفاقية قدرات منصة روافد الدخل الرقمية في ربط المواطنين المستحقين بالفرص والعروض الحصرية التي يقدمها شركاء القطاع الخاص والتجار المحليين للسلع والخدمات الأساسية، مما يسهم في توسيع أثر برامج الدعم الحكومي وتلبية احتياجات الفئات ذات الأولوية، وفي مقدمتها كبار السن والأيتام وذوي الإعاقة والأرامل.","وترتكز الشراكة على الاستفادة من منتجات البيانات وأدوات التحليل المتقدمة لفهم احتياجات المستفيدين بدقة، وتطوير حلول دعم مخصصة عبر قنوات آمنة وموثوقة تحمي الخصوصية وتعتمد على موافقة المواطن ومشاركته لبياناته لتأكيد أهليته، بما يضمن وصول المنافع إلى مستحقيها بأعلى معايير الحوكمة .","وأكد المسؤولون في شركة روافد الدخل أن هذه الشراكة تمثل خطوة مفصلية في مسيرة المنصة، مشيرين إلى أن توظيف منتجات البيانات يهدف أولاً إلى صناعة أثر إنساني ومجتمعي مستدام يتوافق مع أهداف العمل الخيري والتنموي، ومثمنين الدور الريادي للوزارة في دعم الحلول الابتكارية التي تحسّن تجربة المستفيدين.","واختُتمت الفعالية بالتأكيد على استمرار التعاون المشترك للتوسع في إطلاق حلول تقنية متكاملة تغطي كافة قطاعات المستفيدين لدى الوزارة مستقبلاً، وتعزيز التكامل البنّاء بين القطاعين الحكومي والخاص في خدمة المجتمع."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/pr2xcsz','https://sabq.org/article/pr2xcsz','','https://sabq.org/article/pr2xcsz','صحيفة سبق','الرياض','2026-09-05T03:18:00.000Z','2026-09-05T04:56:00.000Z','2026-09-05T13:29:07.506Z','https://media.sabq.org/news/2026/09/65580594-19d1-472c-be52-506c5f3a52a3/w1600.webp','/api/media/2c674081-08b0-4e14-95d2-5ec1d32e724e','/api/media/2c674081-08b0-4e14-95d2-5ec1d32e724e?variant=thumbnail','وزارة الموارد البشرية والتنمية الاجتماعية وشركة روافد الدخل توقعان اتفاقية إطارية لمنتجات البيانات',1600,909,'valid','published','archived','valid',97,'045d59000975f78f655f53fe97da8418d1baef114e95dc88f8e5aa4ee51c4e9c','74f5f3d21b65466755fa089a5a4b9f989e3acea19049b4c83296ed1da2e73295','محدّث','2026-09-05T09:26:02.375Z','2026-10-07T21:19:50.388Z','','',0,0,'saudi_region','مهم',74,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة روافد الدخل لتقنية المعلومات","وزارة الموارد البشرية والتنمية الاجتماعية","الثقافة والفنون","التقنية والتحول الرقمي","الرياض"]','["شركة روافد الدخل لتقنية المعلومات","وزارة الموارد البشرية والتنمية الاجتماعية","الثقافة والفنون","التقنية والتحول الرقمي"]','classified','','[{"category":"التقنية","score":7},{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":1.5}]','Active','2026-10-07T21:19:50.388Z',200,27,0,'source_article_available','',NULL,NULL,'body:0d26ed4a11bf5689d97936274fcbac7f044d4feffa511f847acc02719d2f1287','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('766a8987-385d-4e6a-8733-c1d9d2be7d90','news-766a8987-385d-4e6a-8733-c1d9d2be7d90','اليابان تُصدر أعلى تحذير من انهيارات أرضية في ياكوشيما وسط أمطار قياسية','اليابان تصدر اعلي تحذير من انهيارات ارضيه في ياكوشيما وسط امطار قياسيه','أصدرت وكالة الأرصاد الجوية اليابانية تحذيراً من الدرجة الخامسة — وهو أعلى مستوياتها — من الانهيارات الأرضية الطارئة في بلدة ياكوشيما بمقاطعة كاجوشيما، الواقعة في منطقة كيوشو جنوب غرب اليابان.','["وتعرّضت البلدة لأمطار غزيرة متواصلة منذ الليلة الماضية، تشكّلت بصورة متقطّعة نتيجة آثار إعصار كروفان، الإعصار الـ24 خلال العام الجاري، إلى جانب منخفض استوائي مصاحب.","وسجّلت منطقة أونويدا داخل البلدة رقماً قياسياً في معدلات هطول الأمطار، إذ بلغ منسوب الأمطار خلال 24 ساعة 490.5 ملليمتراً، فيما وصلت أقصى سرعة للرياح إلى 25.9 متراً في الثانية.","وأوضحت وكالة الأرصاد الجوية اليابانية أن «إعصار كروفان يقع فوق البحر شمال مقاطعة أوكيناوا، أقصى جنوب اليابان، بينما يقع المنخفض الاستوائي فوق البحر جنوب شرق المقاطعة ذاتها»."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/exne2sv','https://sabq.org/article/exne2sv','','https://sabq.org/article/exne2sv','صحيفة سبق','','2026-09-05T03:25:00.000Z','2026-09-05T06:26:00.000Z','2026-09-05T09:35:02.799Z','https://media.sabq.org/news/2026/09/37524cb2-f369-4026-a71d-ff90bbd32d68/w1200.webp','/api/media/766a8987-385d-4e6a-8733-c1d9d2be7d90','/api/media/766a8987-385d-4e6a-8733-c1d9d2be7d90?variant=thumbnail','اليابان تُصدر أعلى تحذير من انهيارات أرضية في ياكوشيما وسط أمطار قياسية',1200,675,'valid','published','archived','valid',35,'24414ef12a9960cb53e08b964fce8605f9e4667cde66ef608f78a58bd57cbd5d','d3a3ce2cac604ef6a81bb0d11e36d76305c314f12b813d3fd34376812f6ac1e1','محدّث','2026-09-05T09:35:02.799Z','2026-10-07T20:25:22.788Z','','',0,0,'international','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ"]','["الطقس والمناخ"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:06:10.918Z',200,29,0,'source_article_available','',NULL,NULL,'body:55a3d13ee691ba1343cb212e8551d84d5b3ad874730b40db50b21c715f4c5a53','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5d96d0d4-e37f-4455-91bd-08793510b58a','news-5d96d0d4-e37f-4455-91bd-08793510b58a','اليابان تصدر أعلى تحذير من الانهيارات الأرضية في ياكوشيما بسبب إعصار كروفان','اليابان تصدر اعلي تحذير من الانهيارات الارضيه في ياكوشيما بسبب اعصار كروفان','أصدرت وكالة الأرصاد الجوية اليابانية ، اليوم السبت، أعلى مستوى من التحذير من الانهيارات الأرضية الطارئة عند المستوى الخامس في بلدة ياكوشيما بمقاطعة كاجوشيما، جنوب غرب اليابان . وأوضحت وكالة الأرصاد أن إعصار كروفان يتمركز حاليًا فوق البحر شمال مقاطعة أوكيناوا ، في حين يقع المنخفض الاستوائي فوق البحر جنوب شرق المقاطعة ذاتها.','["أصدرت وكالة الأرصاد الجوية اليابانية ، اليوم السبت، أعلى مستوى من التحذير من الانهيارات الأرضية الطارئة عند المستوى الخامس في بلدة ياكوشيما بمقاطعة كاجوشيما، جنوب غرب اليابان .","وجاء هذا التحذير بعد تعرض البلدة لأمطار غزيرة متواصلة منذ الليلة الماضية، نتيجة التأثر بإعصار كروفان، وهو الإعصار الرابع والعشرون لهذا العام، إضافة إلى تأثير منخفض استوائي.","وفي منطقة أونويدا داخل البلدة، بلغ منسوب هطول الأمطار خلال 24 ساعة 490.5 ملليمترًا، ليسجل رقمًا قياسيًّا محليًا. كما بلغت أقصى سرعة للرياح 25.9 مترًا في الثانية.","وأوضحت وكالة الأرصاد أن إعصار كروفان يتمركز حاليًا فوق البحر شمال مقاطعة أوكيناوا ، في حين يقع المنخفض الاستوائي فوق البحر جنوب شرق المقاطعة ذاتها."]','البيئة والمناخ','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/meja7ofv2','https://ajel.sa/international/meja7ofv2','https://ajel.sa/international/meja7ofv2','https://ajel.sa/international/meja7ofv2','فريق التحرير','','2026-09-05T03:33:00.000Z','Wed, 07 Oct 2026 19:33:43 GMT','2026-09-05T09:44:02.415Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop-hbqXFpfB.png','/api/media/5d96d0d4-e37f-4455-91bd-08793510b58a','/api/media/5d96d0d4-e37f-4455-91bd-08793510b58a?variant=thumbnail','اليابان تصدر أعلى تحذير من الانهيارات الأرضية في ياكوشيما بسبب إعصار كروفان',1200,675,'valid','published','archived','valid',40,'0f8266fbdf8442bbe75ef0a0a585290c3f35f991164bcf32453947fd4d705493','2a2d01874bfb4b631e6d4c79164d17067baab3933e2e79bc85785b0fb9f7fa0c','محدّث','2026-09-05T09:44:02.415Z','2026-10-07T19:33:44.938Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ"]','["الطقس والمناخ"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:33:44.938Z',200,26,0,'source_content_changed','',NULL,NULL,'body:a68b1cafb2d25697e22005b446f07c00c66d476837af999badaa5633a429b202','Wed, 07 Oct 2026 19:33:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8d100c7c-ce1c-43e8-8e23-1cf8c27315d4','news-8d100c7c-ce1c-43e8-8e23-1cf8c27315d4','الكويت: 4 فرق إطفاء تسيطر على حريق مخزن في "جاخور"','الكويت 4 فرق اطفاء تسيطر علي حريق مخزن في جاخور','سيطرت فرق الإطفاء في الكويت ، مساء أمس الجمعة، على حريق اندلع في مخزن داخل جاخور بمنطقة كبد، دون تسجيل إصابات. وذكرت قوة الإطفاء العام ، وفقا لوسائل إعلام كويتية، أن فرق مراكز كبد والاستقلال والقيروان والإسناد هرعت إلى موقع الحادث فور تلقي البلاغ، وباشرت عمليات مكافحة الحريق حتى تمكنت من السيطرة عليه وإخماده.','["سيطرت فرق الإطفاء في الكويت ، مساء أمس الجمعة، على حريق اندلع في مخزن داخل جاخور بمنطقة كبد، دون تسجيل إصابات.","وذكرت قوة الإطفاء العام ، وفقا لوسائل إعلام كويتية، أن فرق مراكز كبد والاستقلال والقيروان والإسناد هرعت إلى موقع الحادث فور تلقي البلاغ، وباشرت عمليات مكافحة الحريق حتى تمكنت من السيطرة عليه وإخماده.","ولم يسفر الحادث عن أي إصابات، فيما باشرت الجهات المختصة الإجراءات اللازمة للوقوف على ملابساته."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/rzpj0xr9p','https://ajel.sa/international/rzpj0xr9p','https://ajel.sa/international/rzpj0xr9p','https://ajel.sa/international/rzpj0xr9p','فريق التحرير','','2026-09-05T03:36:00.000Z','Wed, 07 Oct 2026 19:33:46 GMT','2026-09-05T09:44:02.587Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000285345-crop-_gO3fj-1.jpg','/api/media/8d100c7c-ce1c-43e8-8e23-1cf8c27315d4','/api/media/8d100c7c-ce1c-43e8-8e23-1cf8c27315d4?variant=thumbnail','الكويت: 4 فرق إطفاء تسيطر على حريق مخزن في "جاخور"',1200,675,'valid','published','archived','valid',41,'9fdf29270fb6aafb7028cb4b5505ea047dd904426adb47efefcb62cdb2f771cb','4a74fff8d5df754e5645fab11b5a80a4f0e9986dab49fe5fe3cd93bd41055b67','محدّث','2026-09-05T09:44:02.587Z','2026-10-07T20:25:22.788Z','','',0,0,'gulf_arab','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة"]','["السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:33:47.578Z',200,27,0,'source_content_changed','',NULL,NULL,'body:3a5a0df91c54377ddaa8dc41a296e07fcf179b673d4c5f43d7b69280d42f48a6','Wed, 07 Oct 2026 19:33:46 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2f306468-4d43-49a3-b20e-ac5a959e2310','news-2f306468-4d43-49a3-b20e-ac5a959e2310','1375 قتيلاً وآلاف المفقودين جراء فيضانات نيبال والصين','1375 قتيلا والاف المفقودين جراء فيضانات نيبال والصين','ارتفعت حصيلة ضحايا الفيضانات والانهيارات الطينية التي اجتاحت المناطق الحدودية بين نيبال والصين إلى 1375 قتيلاً، في كارثة طبيعية تُعدّ من أشد الكوارث التي تضرب المنطقة منذ سنوات.','["وأفادت السلطات المحلية في نيبال بأن 1344 شخصاً لقوا حتفهم جراء الفيضانات، في حين لا يزال 4898 آخرون في عداد المفقودين، مشيرةً إلى أنه جرى جمع 2232 عينة من الحمض النووي للمساعدة في عمليات التعرف على هويات الضحايا.","وعلى الجانب الصيني، لقي ما لا يقل عن 31 شخصاً مصرعهم، وفُقد أثر 531 آخرين في منطقة التبّت، ليبلغ إجمالي المفقودين على الجانبين 5429 شخصاً.","وأطلقت الأمم المتحدة وشركاؤها في المجال الإنساني نداءً عاجلاً لجمع 49.6 مليون دولار، بهدف تقديم مساعدات منقذة للحياة للمتضررين من الفيضانات في نيبال.","وكان انهيار جليدي قد تسبّب في اندفاع سيل من الجليد والصخور والطين عبر نهر تريشولي في المنطقة الحدودية بين نيبال والصين في السادس والعشرين من أغسطس الماضي، ما أدى إلى جرف وتدمير عدد كبير من المدن والقرى، وألحق أضراراً واسعة بالطرق والبنية التحتية."]','العالم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/vsjjl7r','https://sabq.org/article/vsjjl7r','','https://sabq.org/article/vsjjl7r','صحيفة سبق','','2026-09-05T03:41:00.000Z','2026-09-05T06:41:00.000Z','2026-09-05T09:44:02.847Z','https://media.sabq.org/news/2026/09/8cbdb1b3-ed5e-4181-a023-3f9cd0d4ad87/w864.webp','/api/media/2f306468-4d43-49a3-b20e-ac5a959e2310','/api/media/2f306468-4d43-49a3-b20e-ac5a959e2310?variant=thumbnail','1375 قتيلاً وآلاف المفقودين جراء فيضانات نيبال والصين',864,648,'valid','published','archived','valid',35,'5690f928bac4e1ac9901ebc5bcbb8957c06b854b948402926df8c892c35e28be','3616c4531266bfe5b0050da59354d76a3b1446bec021652a3c64fbe43e666a55','محدّث','2026-09-05T09:44:02.847Z','2026-10-07T20:25:22.788Z','','',0,0,'gulf_arab','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["الأمم المتحدة وشركاؤها في المجال","الصين"]','["الأمم المتحدة وشركاؤها في المجال"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:33:34.059Z',200,26,0,'source_article_available','',NULL,NULL,'body:df11317534faf23bd3f4ad248bbf469bee2b6c409ab4d98a3d4d59507a7b7b21','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('51490098-a5a2-496d-bc15-f278d301551a','news-51490098-a5a2-496d-bc15-f278d301551a','مصر.. حريق هائل في المنطقة الصناعية بالعبور','مصر حريق هائل في المنطقه الصناعيه بالعبور','اندلع حريق هائل بأحد مصانع مدينة العبور ب محافظة القليوبية ب مصر ، وامتدت النيران إلى مصنع ملابس مجاور . وتلقت السلطات المصرية بلاغا باندلاع الحريق، ودفعت ب قوات الدفاع المدني بإسناد من 30 سيارة إطفاء ببسيطرة على الحريق منعا لتمدده إلى مصانع مجاورة.','["اندلع حريق هائل بأحد مصانع مدينة العبور ب محافظة القليوبية ب مصر ، وامتدت النيران إلى مصنع ملابس مجاور .","وتلقت السلطات المصرية بلاغا باندلاع الحريق، ودفعت ب قوات الدفاع المدني بإسناد من 30 سيارة إطفاء ببسيطرة على الحريق منعا لتمدده إلى مصانع مجاورة.","وتواصلت جهود الإطفاء 5 ساعات إلى أن تمت السيطرة بالكامل على النيران وباشرت فرق الإطفاء أعمال التبريد.","وذكرت تقارير أن التلفيات التي لحقت بالمصنعين كبيرة وقدرت الخسائر المادية بملايين الجنيهات."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/xkonhz8jh','https://ajel.sa/international/xkonhz8jh','https://ajel.sa/international/xkonhz8jh','https://ajel.sa/international/xkonhz8jh','فريق التحرير','','2026-09-05T03:47:00.000Z','Wed, 07 Oct 2026 19:53:37 GMT','2026-09-05T10:02:04.086Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/ai-edited/2026-09/ZxDtLWVmsO7qvArz.png','/api/media/51490098-a5a2-496d-bc15-f278d301551a','/api/media/51490098-a5a2-496d-bc15-f278d301551a?variant=thumbnail','مصر.. حريق هائل في المنطقة الصناعية بالعبور',1200,675,'valid','published','archived','valid',40,'419a9c5d99fcef5ab18ea5daeef2a603ca118518ba2624fe03fcba92d7f69cb2','6928336ce0eb6d9247240a1319a6f3051e30e8d8f4f5c03a3746c9f62884722c','محدّث','2026-09-05T10:02:04.086Z','2026-10-07T20:25:22.788Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والصناعة"]','["الطاقة والصناعة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:53:38.977Z',200,21,0,'source_content_changed','',NULL,NULL,'body:a5734733dc74de045bc87257143d64179dd90ccb1c38d452ca1cfb2b5f41f154','Wed, 07 Oct 2026 19:53:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('333a4b99-eb97-4908-be48-6ee03875d792','news-333a4b99-eb97-4908-be48-6ee03875d792','بزشكيان: أميركا تسعى إلى إثارة الخلاف داخل إيران من خلال الحصار','بزشكيان اميركا تسعي الي اثاره الخلاف داخل ايران من خلال الحصار','قال الرئيس الإيراني، مسعود بزشكيان، إن الولايات المتحدة تسعى إلى إثارة الخلاف داخل إيران من خلال الحصار الذي تفرضه على بلاده. وأكد بزشكيان أن الإيرانيين سيحبطون المؤامرات عبر الوحدة، وفقا لـ« الشرق ».','["قال الرئيس الإيراني، مسعود بزشكيان، إن الولايات المتحدة تسعى إلى إثارة الخلاف داخل إيران من خلال الحصار الذي تفرضه على بلاده.","وأكد بزشكيان أن الإيرانيين سيحبطون المؤامرات عبر الوحدة، وفقا لـ« الشرق ».","وكانت قد ذكرت صحيفة وول ستريت جورنال ، أن الحصار البحري الذي فرضته الولايات المتحدة على إيران قد منعها من تصدير النفط منذ شهر يوليو الماضي.","وكان الجيش الأمريكي ، قد أكد يوم الأربعاء الماضي، أنه أجبر 86 سفينة تجارية على تغيير مسارها وعطل 3 سفن أخرى لضمان الامتثال للحصار البحري على إيران."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/aibwxs4ts','https://ajel.sa/international/aibwxs4ts','https://ajel.sa/international/aibwxs4ts','https://ajel.sa/international/aibwxs4ts','فريق التحرير','','2026-09-05T03:47:00.000Z','Wed, 07 Oct 2026 19:53:36 GMT','2026-09-05T10:02:04.117Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%B1%D8%A6%D9%8A%D8%B3-%D8%A7%D9%84%D8%A7%D9%8A%D8%B1%D8%A7%D9%86%D9%8A-7CpTg3cK.jpg','/api/media/333a4b99-eb97-4908-be48-6ee03875d792','/api/media/333a4b99-eb97-4908-be48-6ee03875d792?variant=thumbnail','بزشكيان: أميركا تسعى إلى إثارة الخلاف داخل إيران من خلال الحصار',1200,675,'valid','published','archived','valid',40,'1c1c2c72af6253eeac75c324a3394f8b486198bedc4804ba842f49e907034817','e5ad6a81f3459c884fc274d95908fabbbd61cabcb237532cb02bb50933ad1a5e','محدّث','2026-09-05T10:02:04.117Z','2026-10-07T20:25:22.788Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","إيران","الولايات المتحدة"]','["الطاقة والنفط","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:53:37.723Z',200,21,0,'source_content_changed','',NULL,NULL,'body:bf611bfc23fd17facf2b88f55f1cd8c5f09cda4d182c56f32abc864a2e4e7f52','Wed, 07 Oct 2026 19:53:36 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('82fe79e4-6f65-4dbd-8418-7e5071403442','news-82fe79e4-6f65-4dbd-8418-7e5071403442','الجيش اليمني يسيطر على مواقع جديدة جنوبي تعز','الجيش اليمني يسيطر علي مواقع جديده جنوبي تعز','كشف مصدر عسكري، أن القوات المسلحة اليمنية تسيطر على مواقع جديدة في جبهة حيفان جنوبي تعز . وكان قد أعلن الجيش اليمني ، اليوم السبت، بدء هجوم معاكس بجبهة جنوب الجراحي ب محافظة الحديدة ، ودمرت بحرية الجيش زورقين حوثيين حاولا استهداف الفجرة وميناء المخا .','["كشف مصدر عسكري، أن القوات المسلحة اليمنية تسيطر على مواقع جديدة في جبهة حيفان جنوبي تعز .","وأشارت مصادر ميدانية إلى أن القوات المسلحة اليمنية تستعيد كافة المناطق في مديرية حيس ، وجاء ذلك عقب اشتباكات عنيفة بين القوات المسلحة اليمنية وميليشيا الحوثي في الكدحة بتعز، وفقا لـ«العربية».","وكان قد أعلن الجيش اليمني ، اليوم السبت، بدء هجوم معاكس بجبهة جنوب الجراحي ب محافظة الحديدة ، ودمرت بحرية الجيش زورقين حوثيين حاولا استهداف الفجرة وميناء المخا ."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/uumbuqq6a','https://ajel.sa/international/uumbuqq6a','https://ajel.sa/international/uumbuqq6a','https://ajel.sa/international/uumbuqq6a','فريق التحرير','','2026-09-05T03:45:00.000Z','Wed, 07 Oct 2026 19:53:43 GMT','2026-09-05T10:02:06.426Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%AC%D9%8A%D8%B4-%D8%A7%D9%84%D9%8A%D9%85%D9%86%D9%8A-UZ9KhEHe.jpg','/api/media/82fe79e4-6f65-4dbd-8418-7e5071403442','/api/media/82fe79e4-6f65-4dbd-8418-7e5071403442?variant=thumbnail','الجيش اليمني يسيطر على مواقع جديدة جنوبي تعز',1200,675,'valid','published','archived','valid',41,'15a577948772141d414dbaa78e576e5720ae1026711d6246db5c558ebf0b9383','df19ac3ba2781da2f058a6c90998ac5e8cbfff510ad1fac54feeb9fea2349282','محدّث','2026-09-05T10:02:06.426Z','2026-10-07T20:25:22.788Z','','',0,0,'gulf_arab','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["اليمن"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:53:44.764Z',200,21,0,'source_content_changed','',NULL,NULL,'body:7ede1df5c0bb0d83d934525a0bad1b5064a1917194441ba3e92fda54c8094c1e','Wed, 07 Oct 2026 19:53:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('919202dd-446e-4203-ab03-a911d75ffae9','news-919202dd-446e-4203-ab03-a911d75ffae9','عبر منصة أبشر.. خطوات إصدار تأشيرة الخروج النهائي للعمالة المنزلية أثناء فترة التجربة','عبر منصه ابشر خطوات اصدار تاشيره الخروج النهائي للعماله المنزليه اثناء فتره التجربه','تتيح المديرية العامة للجوازات خدمة إصدار تأشيرة الخروج النهائي للعمالة خلال فترة التجربة عبر منصة أبشر أعمال، ما يمكّن أصحاب العمل من إصدار التأشيرات إلكترونياً دون الحاجة لمراجعة إدارات الجوازات.','["وتستهدف الخدمة أصحاب العمل للعمالة التجارية، وتتيح لهم إصدار تأشيرة الخروج النهائي خلال فترة تجربة العامل بسهولة وسرعة عبر المنصة الإلكترونية.","تتميز الخدمة بأنها مجانية بالكامل، ولا يمكن إلغاء التأشيرة أو تجديد هوية مقيم بعد تنفيذها، مما يعزز من سرعة الإجراءات ودقتها.","تهدف المديرية من تطوير هذه الخدمة إلى دعم التحول الرقمي، وتسهيل الإجراءات، وتحقيق إدارة بلا ورق في قطاع الجوازات.","ويتاح للمواطنين الذين لديهم أفراد أسرة مقيمة أو العمالة المنزلية إصدار تأشيرة الخروج النهائي، عبر منصة أبشر من خلال الخطوات تسجيل الدخول إلى منصة أبشر.","وبعد ذلك يتم اختيار خدمات التأشيرات من قائمة الخدمات الإلكترونية، واختيار الشخص الذي ترغب فى عمل التأشيرة له (خروج وعودة أو تأشيرة خروج نهائى)، ثم أدخل البيانات المطلوبة، وبعدها اختر أيقونة (إصدار تأشيرة خروج نهائي) وطباعة التأشيرة.","كما أوضحت «الجوازات» أنه في حال تم إصدار تأشيرة خروج نهائي خلال فترة التجربة لا يمكن إلغاءها ويلزم المغادرة قبل انتهاء صلاحية التأشيرة."]','التقنية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/40kmj3rhh','https://ajel.sa/thehour/40kmj3rhh','https://ajel.sa/thehour/40kmj3rhh','https://ajel.sa/thehour/40kmj3rhh','فريق التحرير','','2026-09-05T03:59:00.000Z','Wed, 07 Oct 2026 19:59:55 GMT','2026-09-05T10:12:05.613Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%A7%D9%84%D8%AC%D9%88%D8%A7%D8%B2%D8%A7%D8%AA-Xpsh7POw.jpg','/api/media/919202dd-446e-4203-ab03-a911d75ffae9','/api/media/919202dd-446e-4203-ab03-a911d75ffae9?variant=thumbnail','عبر منصة أبشر.. خطوات إصدار تأشيرة الخروج النهائي للعمالة المنزلية أثناء فترة التجربة',1200,675,'valid','published','archived','valid',41,'2f781e275ffc00c631eff927dad1f3bde4685fde802dc819aff064ea154f138f','ffabb9d6f7fdf49faedf42007285ccc30fca315a0fbaf63a6004615bbf53de05','محدّث','2026-09-05T10:12:05.613Z','2026-10-07T20:25:22.788Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي"]','["التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:59:58.358Z',200,33,0,'source_content_changed','',NULL,NULL,'body:cf61775bca9a54882fb46cf302d959fafc6bc9b3f7b8937bc74715144cab8c39','Wed, 07 Oct 2026 19:59:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4bc9a311-0869-4502-a230-34157186be3e','news-4bc9a311-0869-4502-a230-34157186be3e','"خطوة آمنة" تحاصر مضاعفات القدم السكرية في أكثر من 43 مركزًا بالمملكة لتعزيز الكشف المبكر وتقليل مخاطر البتر','خطوه امنه تحاصر مضاعفات القدم السكريه في اكثر من 43 مركزا بالمملكه لتعزيز الكشف المبكر وتقليل مخاطر البتر','وتأتي المبادرة ثمرة تعاون يجمع وزارة الصحة السعودية، والجمعية السعودية للأشعة التداخلية، وجمعية القدم السكرية، وشركة «بوسطن ساينتيفيك»، في نموذج للشراكة بين القطاعين العام والخاص والجمعيات العلمية، بما يدعم التحول نحو رعاية صحية استباقية تضع الوقاية والكشف المبكر في مقدمة الأولويات.','["توسّع المملكة العربية السعودية جهودها للحد من مضاعفات مرض السكري، عبر مبادرة «خطوة آمنة» التي تستهدف دعم منظومة الوقاية من القدم السكرية، وتطوير إجراءات الفحص المبكر، وتحسين مسارات إحالة المرضى إلى الخدمات التخصصية قبل وصول الحالات إلى مراحل متقدمة.","ويمثل البرنامج خطوة عملية في التعامل مع أحد أخطر مضاعفات السكري وأكثرها تأثيرًا في جودة حياة المرضى؛ إذ قد تتطور الجروح البسيطة في القدم، في ظل تلف الأعصاب الطرفية وضعف الإحساس بالألم، إلى تقرحات والتهابات خطرة تستدعي تدخلات جراحية، وقد تنتهي في بعض الحالات ببتر أحد الأطراف إذا لم تُكتشف وتُعالج في الوقت المناسب.","خطة توسع واسعة وبدأت المرحلة الأولى من «خطوة آمنة» بتنفيذ حزمة من الإجراءات شملت تطوير بروتوكولات الفحص داخل مراكز السكري، وتأهيل الكوادر الصحية، والتعاون مع مستشفيات وزارة الصحة، ضمن خطة توسع تستهدف أكثر من 36 مركزًا للسكري و7 مراكز متخصصة في القدم السكرية بمختلف مناطق المملكة.","ويركز البرنامج على توحيد آليات تقييم مخاطر القدم السكرية، وتدريب الكوادر الطبية والتمريضية على الفحص والتقييم السريري، بما يساعد على اكتشاف المرضى الأكثر عرضة للمضاعفات مبكرًا، والتدخل قبل تفاقم حالتهم.","كما يسعى إلى بناء منظومة مترابطة للإحالة بين مراكز الرعاية الأولية والخدمات الطبية التخصصية، تتيح نقل المريض بسرعة إلى مستوى الرعاية المناسب فور رصد عوامل الخطورة، بما يسهم في خفض المضاعفات وتحسين النتائج العلاجية وتقليل الضغوط على المنشآت الصحية.","أفضل الممارسات العالمية وقال المهندس سعد السدحان، المدير الإقليمي لشركة «بوسطن ساينتيفيك» في المملكة العربية السعودية، إن التعاون مع الجهات المعنية يهدف إلى مشاركة أفضل الممارسات العالمية في الطب وجراحة الأوعية الدموية، ودعم الفحص المبكر، ورفع مستوى وعي المرضى، إلى جانب تبادل المعرفة وتطوير مهارات الكوادر الصحية في المملكة.","وأضاف أن برنامج «خطوة آمنة» يترجم التعاون بين وزارة الصحة و«بوسطن ساينتيفيك» والجمعيات العلمية إلى إجراءات عملية تدعم الوقاية من القدم السكرية، من خلال توحيد ممارسات الفحص المبكر، وتحسين مسارات الإحالة، وتعزيز التنسيق بين التخصصات الطبية المختلفة.","وأوضح السدحان أن الاستثمار في الفحص المبكر والتوعية وبناء القدرات لا يقتصر أثره على تقليل معدلات البتر، بل يمتد إلى تعزيز كفاءة النظام الصحي، ومنح آلاف المرضى فرصة أفضل للحفاظ على حياتهم الطبيعية وجودتها، بما ينسجم مع مستهدفات رؤية السعودية 2030."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/4bwhftg','https://sabq.org/article/4bwhftg','','https://sabq.org/article/4bwhftg','صحيفة سبق','المدينة المنورة','2026-09-05T04:02:00.000Z','2026-09-05T07:03:00.000Z','2026-09-05T10:12:08.038Z','https://media.sabq.org/news/2026/09/076de858-b565-4f6b-a5b9-66bcb5b60857/w640.webp','/api/media/4bc9a311-0869-4502-a230-34157186be3e','/api/media/4bc9a311-0869-4502-a230-34157186be3e?variant=thumbnail','"خطوة آمنة" تحاصر مضاعفات القدم السكرية في أكثر من 43 مركزًا بالمملكة لتعزيز الكشف المبكر وتقليل مخاطر البتر',640,360,'valid','published','archived','valid',52,'8b5136140d098b2a848cca8d447a4428840f7c8ed8c92ed180ffe026c8fcfe09','3934409b656d90eb768bbc9574b972890a029092e80ed47d129d7e203c7a365f','محدّث','2026-09-05T10:12:08.038Z','2026-10-07T20:25:22.788Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الصحة السعودية والجمعية السعودية","الصحة العامة","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق"]','["وزارة الصحة السعودية والجمعية السعودية","الصحة العامة","التعليم والتدريب","الرياضة السعودية","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"الرياضة","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T19:59:50.395Z',200,36,0,'source_article_available','',NULL,NULL,'body:8612501801da6b5a310c3cc90dce993d411445b5238617d940048a0256d8b905','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('34e3402d-ace4-4fec-ae13-1893c1faa8ad','news-34e3402d-ace4-4fec-ae13-1893c1faa8ad','16 فرص عقارية بمزاد رواق','16 فرص عقاريه بمزاد رواق','يطرح المزاد 16 فرص عقارية مميزة/نادرة في مواقع استراتيجية مميزة في أهم المدن الراقية والمميزة جنوب وشمال و شرق مدينة جدة العقار الأول: شقة سكنية — المساحة: 201.16 م² العقار الثاني: فيلا سكنية — المساحة: 822.72 م² العقار الثالث: أرض سكنية — المساحة: 864 م² العقار الرابع: مبنى سكني — المساحة: 400 م² العقار الخامس: عمارة سكنية — المساحة: 675 م² العقار…','["يعلن مكتب شبيب للعقارات وبإشراف مركز الإسناد والتصفية «إنفاذ» وبقرار من محكمة التنفيذ، عن إقامة مزاد \" رواق \" الالكتروني وذلك يوم 12/09/2026 عبر منصة وصلت من الساعة 10:00 صباحاً حتى يوم 14/09/2026 مابين الساعة 04:40 الي 07:10 مساءً .","يطرح المزاد 16 فرص عقارية مميزة/نادرة في مواقع استراتيجية مميزة في أهم المدن الراقية والمميزة جنوب وشمال و شرق مدينة جدة العقار الأول: شقة سكنية — المساحة: 201.16 م² العقار الثاني: فيلا سكنية — المساحة: 822.72 م² العقار الثالث: أرض سكنية — المساحة: 864 م² العقار الرابع: مبنى سكني — المساحة: 400 م² العقار الخامس: عمارة سكنية — المساحة: 675 م² العقار السادس: فيلا سكنية — المساحة: 600 م² العقار السابع: شقة سكنية — المساحة: 108.94 م² العقار الثامن: شقة سكنية — المساحة: 198.58 م² العقار التاسع: مجمع تجاري — المساحة: 2,438 م² العقار العاشر: أرض سكنية — المساحة: 2,438 م² العقار الحادي عشر: فيلا سكنية — المساحة: 2,675 م² العقار الثاني عشر: شقة سكنية — المساحة: 81.62 م² العقار الثالث عشر: شقة سكنية — المساحة: 216.59 م² العقار الرابع عشر: شقة سكنية — المساحة: 258.07 م² العقار الخامس عشر: أرض تجارية — المساحة: 13,115 م² العقار السادس عشر: عمارة سكنية — المساحة: 2,000 م² حيث تقع على أهم الطرق الحيوية والمميزة كـ طريق الملك عبدالعزيز و طريق الملك عبدالله و طريق الأمير ماجد ويعتبر المزاد فرصة جاذبة للراغبين عن الفرص الاستثمارية الواعدة، كما يرحب مكتب شبيب للعقارات بجميع الاستفسارات من خلال التواصل على 0594800081"]','العقارات','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/xdmtj3v','https://sabq.org/article/xdmtj3v','','https://sabq.org/article/xdmtj3v','صحيفة سبق','مكة المكرمة','2026-09-05T04:14:00.000Z','2026-09-05T07:15:00.000Z','2026-09-05T10:21:02.969Z','https://media.sabq.org/news/2026/09/856822dc-79a8-4bda-aad6-44fa680e980a/w1080.webp','/api/media/34e3402d-ace4-4fec-ae13-1893c1faa8ad','/api/media/34e3402d-ace4-4fec-ae13-1893c1faa8ad?variant=thumbnail','16 فرص عقارية بمزاد رواق',1080,1076,'valid','published','archived','valid',41,'600adb80a3cdbe222260a947f98b24960c6b26241387311fd637e91aa9227e94','ec2cf7b02f84aa357f6b270771d1b9aff74fde61855f9da574146c07c695bccd','محدّث','2026-09-05T10:21:02.969Z','2026-10-07T20:25:22.788Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","جدة"]','["الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:02:54.955Z',200,26,0,'sourc