INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3be45f19-b47b-4d1b-93db-000de29e1c16','news-3be45f19-b47b-4d1b-93db-000de29e1c16','مكتب الأمم المتحدة: نزوح 1790 عائلة نتيجة التصعيد في تعز','مكتب الامم المتحده نزوح 1790 عائله نتيجه التصعيد في تعز','أعلن مكتب الأمم المتحدة للشؤون الإنسانية، عن نزوح 1790 عائلة نتيجة التصعيد في محافظة تعز ، وفق "العربية". يأتي ذلك نتيجة التوتر الذي تفرضه الميليشيات الحوثية الانقلابية في اليمن في مختلف المناطق بينما يواصل الجيش اليمني مواجهتها لتحييد أخطارها.','["أعلن مكتب الأمم المتحدة للشؤون الإنسانية، عن نزوح 1790 عائلة نتيجة التصعيد في محافظة تعز ، وفق \"العربية\".","يأتي ذلك نتيجة التوتر الذي تفرضه الميليشيات الحوثية الانقلابية في اليمن في مختلف المناطق بينما يواصل الجيش اليمني مواجهتها لتحييد أخطارها.","وتسيطر القوات المسلحة اليمنية على مواقع جديدة في جبهة حيفان جنوبي تعز، حيث تستعيد كافة المناطق في مديرية حيس ، عقب اشتباكات عنيفة بين القوات المسلحة اليمنية وميليشيا الحوثي في الكدحة بتعز."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/6puptr0g3','https://ajel.sa/international/6puptr0g3','https://ajel.sa/international/6puptr0g3','https://ajel.sa/international/6puptr0g3','فريق التحرير','','2026-09-05T04:28:00.000Z','Wed, 07 Oct 2026 20:18:07 GMT','2026-09-05T10:32:24.687Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/l2m4gYgprbmRThvH.jpg','/api/media/3be45f19-b47b-4d1b-93db-000de29e1c16','/api/media/3be45f19-b47b-4d1b-93db-000de29e1c16?variant=thumbnail','مكتب الأمم المتحدة: نزوح 1790 عائلة نتيجة التصعيد في تعز',1200,675,'valid','published','archived','valid',41,'99fbc3af1ffca3b35c54a3bcb1053396fe8879864a7c94485222f0ea7cd431de','93f83f8dbfb512871e8d35a473d88213165c999f14ec8bf9f207f36986865b29','محدّث','2026-09-05T10:32:24.687Z','2026-10-07T20:25:22.788Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الأمم المتحدة نزوح","اليمن"]','["الأمم المتحدة نزوح"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T20:18:08.658Z',200,27,0,'source_article_available','',NULL,NULL,'body:6ba4f4297f0f3eb398d0b9dfaf24a06c6f06d662885ac24bbb8be7f9812ee0b2','Wed, 07 Oct 2026 20:18:07 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('256e2cc3-8cd8-4765-8770-6e774f9b055d','news-256e2cc3-8cd8-4765-8770-6e774f9b055d','أسعار الذهب في السعودية اليوم السبت 23-3-1448 محليا وعالميا','اسعار الذهب في السعوديه اليوم السبت 23 3 1448 محليا وعالميا','وسجل سعر الذهب في البورصة العالمية اليوم السبت، نحو 4,430 دولارا للأوقية، متراجعا بنسبة 0.96%، في آخر سعر للإغلاق قبل بدء العطلة الأسبوعية للبورصة. وسجل سعر الذهب عيار 21 في المملكة، في مستهل التعاملات اليوم، السبت 467.37 ريال للجرام، فيما بلغ سعر الجرام في ختام التعاملات أمس الجمعة 472.25 ريال.','["تراجعت أسعار الذهب في السعودية اليوم السبت 23-3-1448 لكل الأعيرة؛ حيث تراجع سعر الذهب عيار 21 وبقية الأعيرة في مستهل التعاملات اليوم، بالتزامن مع انخفاض سعر المعدن الأصفر عالميا قبل ختام تعاملات الأسبوع.","وسجل سعر الذهب في البورصة العالمية اليوم السبت، نحو 4,430 دولارا للأوقية، متراجعا بنسبة 0.96%، في آخر سعر للإغلاق قبل بدء العطلة الأسبوعية للبورصة.","وسجل سعر الذهب عيار 21 في المملكة، في مستهل التعاملات اليوم، السبت 467.37 ريال للجرام، فيما بلغ سعر الجرام في ختام التعاملات أمس الجمعة 472.25 ريال.","وجاء سعر الذهب في السعودية اليوم السبت 23-3-1448 لكل الأعيرة كالآتي:","سعر الذهب في السعودية عيار 21 اليوم السبت، 467.37 ريال.","سعر الذهب في السعودية عيار 24 اليوم السبت، 534.13 ريال.","سعر الذهب في السعودية عيار 22 اليوم السبت، 489.62 ريال."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/jy9o76q42','https://ajel.sa/thehour/jy9o76q42','https://ajel.sa/thehour/jy9o76q42','https://ajel.sa/thehour/jy9o76q42','فريق التحرير','','2026-09-05T04:28:00.000Z','Mon, 07 Sep 2026 03:27:50 GMT','2026-09-05T10:32:34.921Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D8%B0%D9%87%D8%A8-2-UY0MkpfJ.jpg','/api/media/256e2cc3-8cd8-4765-8770-6e774f9b055d','/api/media/256e2cc3-8cd8-4765-8770-6e774f9b055d?variant=thumbnail','أسعار الذهب في السعودية اليوم السبت 23-3-1448 محليا وعالميا',1200,675,'valid','published','archived','valid',52,'4c4be5b5d4a18979eba9da85f3c274be41d702aaae6bee0653f6cfb8e6f2031e','396413b96deba2b53d8b66938256b3df9013fd095b17e994bd7fd7cee4504eb0','محدّث','2026-09-05T10:32:34.921Z','2026-10-07T20:25:22.788Z','','',0,0,'saudi_national','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق"]','["الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T20:21:57.713Z',NULL,24,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('61842373-ef29-4af9-8131-e8b42a692e5c','news-61842373-ef29-4af9-8131-e8b42a692e5c','إصابة فلسطينيين أحدهما طفل برصاص الاحتلال الإسرائيلي شمال غزة','اصابه فلسطينيين احدهما طفل برصاص الاحتلال الاسرائيلي شمال غزه','أصيب فلسطينيان، أحدهما طفل، اليوم السبت، برصاص قوات الاحتلال الإسرائيلي خلال عملية إطلاق نار استهدفت خيام النازحين في منطقة السودانية شمال قطاع غزة . وجاءت هذه الإصابات في ظل استمرار الخروقات الإسرائيلية لاتفاق وقف إطلاق النار في القطاع، وسط تدهور الأوضاع الإنسانية.','["أصيب فلسطينيان، أحدهما طفل، اليوم السبت، برصاص قوات الاحتلال الإسرائيلي خلال عملية إطلاق نار استهدفت خيام النازحين في منطقة السودانية شمال قطاع غزة .","وجاءت هذه الإصابات في ظل استمرار الخروقات الإسرائيلية لاتفاق وقف إطلاق النار في القطاع، وسط تدهور الأوضاع الإنسانية.","وفي السياق ذاته، تواصلت عمليات القصف المدفعي وإطلاق النار من الآليات العسكرية والطائرات المسيّرة الإسرائيلية، بالإضافة إلى تنفيذ عمليات نسف للمباني السكنية في المناطق الشمالية والشرقية من قطاع غزة ."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/tix1hmq1u','https://ajel.sa/international/tix1hmq1u','https://ajel.sa/international/tix1hmq1u','https://ajel.sa/international/tix1hmq1u','فريق التحرير','المنطقة الشرقية','2026-09-05T04:13:00.000Z','Wed, 07 Oct 2026 20:18:07 GMT','2026-09-05T10:33:47.324Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%BA%D8%B2%D8%A9-6aNf3cVL.jpg','/api/media/61842373-ef29-4af9-8131-e8b42a692e5c','/api/media/61842373-ef29-4af9-8131-e8b42a692e5c?variant=thumbnail','إصابة فلسطينيين أحدهما طفل برصاص الاحتلال الإسرائيلي شمال غزة',1200,675,'valid','published','archived','valid',41,'5691d791f6eb04686edc8b595ac2558aedbcd32f334d482babd704aa18dd9369','15d184920d2d981b0286e7c33f7aced4745ba0b72b5a2c17ccfe22373d193f5e','محدّث','2026-09-05T10:33:47.324Z','2026-10-07T20:25:22.788Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["غزة","فلسطين"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:18:09.128Z',200,26,0,'source_content_changed','',NULL,NULL,'body:5ce3f679c0c196e92d66b429fb2e4a4c33c03a7bec1ceca2c55e7785623e2944','Wed, 07 Oct 2026 20:18:07 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fd91e285-3549-4e24-8d07-9f425a9f73d1','news-fd91e285-3549-4e24-8d07-9f425a9f73d1','جهود مستمرة لإنقاذ الطفل أيوب العالق في بئر بالجزائر.. صعوبات تواجه العملية','جهود مستمره لانقاذ الطفل ايوب العالق في بئر بالجزائر صعوبات تواجه العمليه','تواصل فرق الحماية المدنية الجزائرية، اليوم السبت، عمليات الحفر لإنقاذ الطفل أيوب، البالغ من العمر 10 أعوام، بعد سقوطه في بئر ارتوازية جافة بولاية البيض جنوب غربي البلاد.','["وتستمر الجهود لليوم الرابع على التوالي وسط استنفار كبير من الجهات المعنية للوصول إلى الطفل وإخراجه من البئر.","دفعت الحماية المدنية بقوات إضافية إلى موقع الحادث، حيث نزل أحد عناصرها إلى عمق البئر لبدء عملية الإنقاذ بعد أكثر من 30 ساعة من العمل المتواصل.","وواجهت الفرق تحديات كبيرة بسبب عمق البئر الذي يبلغ نحو 80 متراً وقطرها الضيق البالغ 40 سنتيمتراً، ما حال دون النزول المباشر إليها.","وأوضح والد الطفل أن الغطاء الخشبي للبئر كان هشاً، وتكسّر عندما وقف عليه أيوب أثناء محاولته أخذ قارورة ماء لأخيه، ما أدى إلى سقوطه.","وأشار إلى أن الطفل ناشده قائلاً: «بابا خرجني» قبل أن ينقطع صوته بعد إرسال مصباح إليه من جانب فرق الإنقاذ.","وصلت عمليات الإنقاذ إلى مرحلة متقدمة، حيث دخل عناصر من الحماية المدنية البئر الموازية التي حفرت بمحاذاة البئر الأصلية، وبدأ العمل على تأمين منفذ أفقي باتجاه موقع الطفل.","وتواجه الفرق صعوبات بسبب وجود طبقات صخرية صلبة وهشاشة التربة، ما يتطلب العمل بحذر لتجنب أي انهيار قد يهدد حياة الطفل أو عناصر الحماية المدنية."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/ady8v671o','https://ajel.sa/misc/ady8v671o','https://ajel.sa/misc/ady8v671o','https://ajel.sa/misc/ady8v671o','فريق التحرير','','2026-09-05T04:11:00.000Z','Wed, 07 Oct 2026 20:27:47 GMT','2026-09-05T10:45:03.519Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000285355-crop-v0lxQ_PN.jpg','/api/media/fd91e285-3549-4e24-8d07-9f425a9f73d1','/api/media/fd91e285-3549-4e24-8d07-9f425a9f73d1?variant=thumbnail','جهود مستمرة لإنقاذ الطفل أيوب العالق في بئر بالجزائر.. صعوبات تواجه العملية',1200,675,'valid','published','archived','valid',41,'fc745b7885442304c9d05e900282e4c87e045fd8dabeb2aad3b0e207a8d81e95','8db1f06ecf75d82dbfd71b3912ff3f0e4f990e3e22b902b2d172d7e34ec4774d','محدّث','2026-09-05T10:45:03.519Z','2026-10-07T20:27:48.925Z','','',0,0,'gulf_arab','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:27:48.925Z',200,31,0,'source_content_changed','',NULL,NULL,'body:4f7cde193a1b5bedaf1d8bab65cae2890124e098b8c3383d657aed75aec131b5','Wed, 07 Oct 2026 20:27:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bd0d8505-20b6-45fa-a26b-fbe513124751','news-bd0d8505-20b6-45fa-a26b-fbe513124751','الجيش اليمني يستعيد جميع المناطق في مديرية حيس','الجيش اليمني يستعيد جميع المناطق في مديريه حيس','استعادت القوات المسلحة اليمنية جميع المناطق في مديرية حيس وخاض اشتباكات عنيفة مع مليشيا الحوثي في تعز . وفرضت القوات المسلحة اليمنية سيطرتها على جميع المناطق في مديرية حيس، بالتوازي مع الاشتباكات التي تخوضها في مختلف الجبهات.','["استعادت القوات المسلحة اليمنية جميع المناطق في مديرية حيس وخاض اشتباكات عنيفة مع مليشيا الحوثي في تعز .","وشهدت المواجهات بين القوات المسلحة اليمنية ومليشيا الحوثي في الكدحة بتعز اشتباكات عنيفة، وفق \" الحدث \"."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/n4vly4o17','https://ajel.sa/international/n4vly4o17','https://ajel.sa/international/n4vly4o17','https://ajel.sa/international/n4vly4o17','فريق التحرير','','2026-09-05T04:09:00.000Z','Wed, 07 Oct 2026 20:27:48 GMT','2026-09-05T10:45:05.033Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%AC%D9%8A%D8%B4-%D8%A7%D9%84%D9%8A%D9%85%D9%86%D9%8A-UZ9KhEHe.jpg','/api/media/bd0d8505-20b6-45fa-a26b-fbe513124751','/api/media/bd0d8505-20b6-45fa-a26b-fbe513124751?variant=thumbnail','الجيش اليمني يستعيد جميع المناطق في مديرية حيس',1200,675,'valid','published','archived','valid',41,'28a17616f14d8b75f6117fe0a772e3e76c442403183891bcced233b1e6e004e9','36e88a96ad9537a5b9063180313082379eaf8e1cb9152473c2704a68f5e51243','محدّث','2026-09-05T10:45:05.033Z','2026-10-07T20:27:50.046Z','','',0,0,'gulf_arab','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["اليمن"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:27:50.046Z',200,30,0,'source_content_changed','',NULL,NULL,'body:3abe9c5e7d6ce794a2d0503eb1975afe6d7690908d7fb7157ebb562cd756e52b','Wed, 07 Oct 2026 20:27:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('288441f7-53c5-4521-8d65-d542b37f914b','news-288441f7-53c5-4521-8d65-d542b37f914b','الفيصلي يعلن رسميا التعاقد مع عبدالعزيز البيشي','الفيصلي يعلن رسميا التعاقد مع عبدالعزيز البيشي','أعلن نادي الفيصلي رسمياً تعاقده مع اللاعب عبد العزيز البيشي ، وذلك قبل إغلاق فترة الانتقالات الصيفية الحالية، في إطار مساعي النادي لتدعيم صفوفه. ويعود البيشي بذلك إلى صفوف الفيصلي مجدداً، بعدما سبق له تمثيل الفريق عام 2018، قبل انتقاله إلى الاتحاد مطلع عام 2019.','["أعلن نادي الفيصلي رسمياً تعاقده مع اللاعب عبد العزيز البيشي ، وذلك قبل إغلاق فترة الانتقالات الصيفية الحالية، في إطار مساعي النادي لتدعيم صفوفه.","ويعود البيشي بذلك إلى صفوف الفيصلي مجدداً، بعدما سبق له تمثيل الفريق عام 2018، قبل انتقاله إلى الاتحاد مطلع عام 2019.","ويملك البيشي مسيرة مع عدد من الأندية، إذ بدأ في الفئات السنية بنادي حطين، قبل انتقاله إلى الشباب عام 2013، ومنه خرج معاراً إلى التعاون عام 2017، ثم انتقل إلى الفيصلي في 2018، قبل أن يغادره إلى الاتحاد مطلع العام التالي."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/1vsoko1rw','https://ajel.sa/sports/1vsoko1rw','https://ajel.sa/sports/1vsoko1rw','https://ajel.sa/sports/1vsoko1rw','فريق التحرير','','2026-09-05T04:09:00.000Z','Wed, 07 Oct 2026 20:27:47 GMT','2026-09-05T10:45:05.178Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%A8%D9%8A%D8%B4%D9%8A-Xo406kl7.jpg','/api/media/288441f7-53c5-4521-8d65-d542b37f914b','/api/media/288441f7-53c5-4521-8d65-d542b37f914b?variant=thumbnail','الفيصلي يعلن رسميا التعاقد مع عبدالعزيز البيشي',1200,675,'valid','published','archived','valid',41,'58c304573e38edba846c1f4b46152d247b9eb8bfba0a6922866eafc02361d658','042ce4c8ef28a23bd9e56becd2530c5ff1505a08b615d12f3154f54dae52f461','محدّث','2026-09-05T10:45:05.178Z','2026-10-07T20:27:48.955Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:27:48.955Z',200,31,0,'source_content_changed','',NULL,NULL,'body:93dd002a13e7ca3e88fd44581244b253114736ba05c3094701e8760e784bc6d8','Wed, 07 Oct 2026 20:27:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('270685a5-c3d1-473d-9db9-18aef3802172','news-270685a5-c3d1-473d-9db9-18aef3802172','خلال أسبوع.. ضبط أكثر من 14 ألف مخالف لأنظمة الإقامة والعمل وأمن الحدود','خلال اسبوع ضبط اكثر من 14 الف مخالف لانظمه الاقامه والعمل وامن الحدود','أسفرت الحملات الميدانية المشتركة لمتابعة وضبط مخالفي أنظمة الإقامة والعمل وأمن الحدود، التي نُفذت في جميع مناطق المملكة خلال الفترة من 27 أغسطس إلى 2 سبتمبر 2026، عن ضبط 14,165 مخالفًا.','["وأوضحت الجهات الأمنية أن المخالفين توزعوا بين 7,121 مخالفًا لنظام الإقامة، و3,636 مخالفًا لنظام أمن الحدود، و3,408 مخالفين لنظام العمل.","في سياق متصل، تم ضبط 1,315 شخصًا خلال محاولتهم عبور الحدود إلى داخل المملكة، 41٪ منهم يمنيو الجنسية، و58٪ إثيوبيو الجنسية، إضافة إلى جنسيات أخرى. كما جرى ضبط 42 شخصًا لمحاولتهم عبور الحدود إلى خارج المملكة بطريقة غير نظامية.","من جهة أخرى، أوقفت الجهات المختصة 21 متورطًا في نقل وإيواء وتشغيل مخالفي الأنظمة والتستر عليهم.","بلغ عدد من يخضعون حاليًا لإجراءات تنفيذ الأنظمة 29,773 وافدًا مخالفًا، بينهم 27,845 رجلًا و1,928 امرأة. كما أُحيل 18,937 مخالفًا إلى بعثاتهم الدبلوماسية لاستكمال وثائق السفر، و3,240 مخالفًا لاستكمال حجوزات سفرهم، وتم ترحيل 12,363 مخالفًا.","أكدت وزارة الداخلية أن كل من يسهل دخول مخالفي نظام أمن الحدود أو نقلهم أو إيواءهم أو تقديم أي مساعدة لهم، يعرّض نفسه لعقوبات تصل إلى السجن 15 سنة، وغرامة تصل إلى مليون ريال، مع مصادرة وسيلة النقل والسكن المستخدمين، والتشهير به. ووصفت الجريمة بأنها من الجرائم الكبيرة الموجبة للتوقيف والمخلة بالشرف والأمانة.","وحثت الوزارة على الإبلاغ عن أي حالات مخالفة عبر الرقم 911 في مناطق مكة المكرمة والمدينة المنورة و الرياض و المنطقة الشرقية ، وأرقام 999 و996 في بقية المناطق."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/95idzxksi','https://ajel.sa/local/95idzxksi','https://ajel.sa/local/95idzxksi','https://ajel.sa/local/95idzxksi','فريق التحرير','الرياض','2026-09-05T04:02:00.000Z','Wed, 07 Oct 2026 20:27:47 GMT','2026-09-05T10:45:05.422Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop-ZY0QWYw1.png','/api/media/270685a5-c3d1-473d-9db9-18aef3802172','/api/media/270685a5-c3d1-473d-9db9-18aef3802172?variant=thumbnail','خلال أسبوع.. ضبط أكثر من 14 ألف مخالف لأنظمة الإقامة والعمل وأمن الحدود',1200,675,'valid','published','archived','valid',40,'a342a472fec5e364595f23c2cf7df9f84ddc8e0c79ad0cf596ed9e57e87558f1','43c6cd6261e44e134bc75f13e029dc62d8edce2d1da95e6d926adbd48f8d2816','محدّث','2026-09-05T10:45:05.422Z','2026-10-07T20:27:48.912Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية أن كل من","السفر والسياحة","السياسة والعلاقات الدولية","مكة","الرياض","المدينة المنورة"]','["وزارة الداخلية أن كل من","السفر والسياحة","السياسة والعلاقات الدولية","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:27:48.912Z',200,31,0,'source_content_changed','',NULL,NULL,'body:49d1e3ab889da419efee4b3d383092c9300f0f9ecc48eb8bbe9923ea8d0e1862','Wed, 07 Oct 2026 20:27:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('eb3c84b4-a718-42f3-bfaa-2f21bc0dbb44','news-eb3c84b4-a718-42f3-bfaa-2f21bc0dbb44','أزقة جدة التاريخية.. حكمة معمارية خففت الحر قبل التكييف','ازقه جده التاريخيه حكمه معماريه خففت الحر قبل التكييف','تكشف أزقة جدة التاريخية ومبانيها المتقاربة عن خبرة معمارية متوارثة في التكيف مع طبيعة المدينة الساحلية وحرارة الصيف ورطوبته؛ إذ أسهم تخطيط المباني والممرات المظللة وتوظيف العناصر الخشبية في تهيئة بيئة أكثر ملاءمة للسكان والمارة، قبل ظهور وسائل التكييف الحديثة.','["وشكّلت السقائف والممرات المظللة، إلى جانب ضيق الأزقة وتقارب المباني، منظومة عمرانية أسهمت في الحد من التعرض المباشر لأشعة الشمس، والاستفادة من الظلال التي تلقيها المباني على بعضها وعلى طرق المشاة خلال ساعات النهار.","وتكاملت هذه المنظومة مع الرواشين الخشبية، إحدى أبرز سمات عمارة جدة التاريخية؛ إذ ساعد تصميمها على تنظيم دخول الضوء والهواء إلى المنازل وتوفير الخصوصية، فيما أسهم بروزها عن الواجهات في زيادة مساحات الظل وتقليل وصول أشعة الشمس المباشرة إلى الجدران والممرات.","واعتمد البنّاؤون على مواد محلية، من أبرزها الحجر المنقبي والأخشاب، وجرى توظيفها ضمن تصميم يراعي الظروف المناخية للمدينة، ويحقق التكامل بين مواد البناء وحركة الهواء ومسار الشمس وطبيعة النسيج العمراني.","وتوضح هذه التفاصيل كيف جمعت العمارة التقليدية في جدة التاريخية بين الوظيفة والجمال؛ فتحوّلت الأزقة الضيقة والرواشين والسقائف والممرات المظللة إلى عناصر مترابطة خففت من آثار المناخ، وأسهمت في تشكيل الهوية البصرية المميزة للمدينة القديمة.","وتبقى هذه الحلول شاهداً على خبرة البنّائين والحرفيين في جدة وقدرتهم على فهم البيئة المحلية والتكيف معها، ضمن إرث معماري يحتضنه موقع «جدة التاريخية، بوابة مكة»، المدرج على قائمة التراث العالمي لليونسكو منذ عام 2014.","وفي امتداد لجهود صون هذا الإرث، تعمل وزارة الثقافة على إعادة إحياء جدة التاريخية في إطار الإستراتيجية الوطنية للثقافة ورؤية السعودية 2030، الهادفة إلى الحفاظ على التراث المادي وغير المادي وتعزيزه، وترسيخ مكانة المنطقة وجهةً ثقافية سياحية رائدة تحتفي بتاريخها العريق وتقدمه بتجارب معاصرة تُثري تجربة الزائر وتدعم النمو الاقتصادي والثقافي."]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/42s4ft8','https://sabq.org/article/42s4ft8','','https://sabq.org/article/42s4ft8','صحيفة سبق','مكة المكرمة','2026-09-05T04:51:00.000Z','2026-09-05T07:52:00.000Z','2026-09-05T11:03:04.124Z','https://media.sabq.org/news/2026/09/019598a0-1a62-44cf-af3a-f668f9fdc77c/w1600.webp','/api/media/eb3c84b4-a718-42f3-bfaa-2f21bc0dbb44','/api/media/eb3c84b4-a718-42f3-bfaa-2f21bc0dbb44?variant=thumbnail','أزقة جدة التاريخية.. حكمة معمارية خففت الحر قبل التكييف',1600,2399,'valid','published','archived','valid',52,'4b182807d79a27ddf319859706005788d2a5a8e394b7f5410b144b409e278a14','774761720dd5584c0f8a2e5a15c2f742c7f8f27c274dbe460afa5c487461e0a7','محدّث','2026-09-05T11:03:04.124Z','2026-10-07T20:59:41.348Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الثقافة على إعادة إحياء","الطقس والمناخ","الثقافة والفنون","الاقتصاد والأسواق","مكة","جدة"]','["وزارة الثقافة على إعادة إحياء","الطقس والمناخ","الثقافة والفنون","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الرياضة","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T20:59:41.348Z',200,33,0,'source_article_available','',NULL,NULL,'body:5c298efb73fd6b73e67038a8d5ee7b18d5c7048bb79bf4395ee37a066aec3271','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a41c2719-8d5d-4ee0-93ab-e04cdeddc6a5','news-a41c2719-8d5d-4ee0-93ab-e04cdeddc6a5','مزيج دوائي يتفوق على «الكيماوي» بعلاج سرطان الدم النخاعي الحاد','مزيج دوائي يتفوق علي الكيماوي بعلاج سرطان الدم النخاعي الحاد','أظهرت تجربة سريرية في الولايات المتحدة ، أن مزيجا دوائيا أطال فترة السيطرة على سرطان الدم النخاعي الحاد، وقلل مدة الإقامة في المستشفى. وخلصت التجارب إلى أن مزيج "أزاسيتيدين" و"فينيتوكلاكس"، تفوق على العلاج الكيميائي التقليدي وقد يكون أكثر فاعلية لبعض مرضى سرطان الدم النخاعي الحاد، وفق " الشرق ".','["أظهرت تجربة سريرية في الولايات المتحدة ، أن مزيجا دوائيا أطال فترة السيطرة على سرطان الدم النخاعي الحاد، وقلل مدة الإقامة في المستشفى.","وخلصت التجارب إلى أن مزيج \"أزاسيتيدين\" و\"فينيتوكلاكس\"، تفوق على العلاج الكيميائي التقليدي وقد يكون أكثر فاعلية لبعض مرضى سرطان الدم النخاعي الحاد، وفق \" الشرق \".","تولى التجربة مركز ماس جنرال بريجهام للسرطان بولاية ماساتشوستس في الولايات المتحدة، أمضى المرضى الذين تلقوا مزيجاً من عقاري \"أزاسيتيدين\" و\"فينيتوكلاكس\" أكثر من ضعف المدة قبل فشل العلاج، أو عودة السرطان، أو تفاقمه، مقارنة بمرضى تلقوا علاجاً كيميائياً مكثفاً.","ولم تقتصر الفائدة على السيطرة على السرطان، إذ سجل المرضى في مجموعة العلاج الأقل كثافة معدلات أقل من العدوى الخطيرة ومضاعفات النزيف."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/jvxcq4wk1','https://ajel.sa/misc/jvxcq4wk1','https://ajel.sa/misc/jvxcq4wk1','https://ajel.sa/misc/jvxcq4wk1','فريق التحرير','المدينة المنورة','2026-09-05T04:57:00.000Z','Wed, 07 Oct 2026 21:17:52 GMT','2026-09-05T11:12:01.838Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-bYqIWSMQ.png','/api/media/a41c2719-8d5d-4ee0-93ab-e04cdeddc6a5','/api/media/a41c2719-8d5d-4ee0-93ab-e04cdeddc6a5?variant=thumbnail','مزيج دوائي يتفوق على «الكيماوي» بعلاج سرطان الدم النخاعي الحاد',1200,675,'valid','published','archived','valid',41,'d2ed8048492f7292cd5a48d0d524c3e8fdaae6fd5279f3360dc129966cd80189','ff55beb2cb5e5836261baec0c37ab6089b916349b55fdd393fe898c4f7129492','محدّث','2026-09-05T11:12:01.838Z','2026-10-07T21:17:54.932Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الولايات المتحدة"]','["الصحة العامة","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:17:54.932Z',200,24,0,'source_content_changed','',NULL,NULL,'body:99fcef3ede2076448679dae263fac48d0f3162b18edc8f8490f7ee5c8f411249','Wed, 07 Oct 2026 21:17:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d9be1d10-136b-49bb-838a-3b609432f0d9','news-d9be1d10-136b-49bb-838a-3b609432f0d9','اليمن.. مقتل مدنيين بهجمات حوثية بصواريخ ومسيرات على مواقع مدنية بتعز','اليمن مقتل مدنيين بهجمات حوثيه بصواريخ ومسيرات علي مواقع مدنيه بتعز','أكدت مصادر يمنية لـ "العربية"، مقتل مدنيين في هجمات حوثية بصواريخ ومسيرات على مواقع مدنية ب تعز . وأضافت المصادر، أن وحدات القوات المسلحة تحقق تقدما كبيرا في جبهة حيس جنوبي الحديدة ، كما نفذ سلاح الجو سلسلة غارات على مواقع حوثية في تعز والحديدة.','["أكدت مصادر يمنية لـ \"العربية\"، مقتل مدنيين في هجمات حوثية بصواريخ ومسيرات على مواقع مدنية ب تعز .","وأضافت المصادر، أن وحدات القوات المسلحة تحقق تقدما كبيرا في جبهة حيس جنوبي الحديدة ، كما نفذ سلاح الجو سلسلة غارات على مواقع حوثية في تعز والحديدة.","كذلك أوقف سلاح الجو اليمني محاولات الحوثي التقدم في عدة محاور، فيما تواصل القوات المسلحة اليمنية سيطرتها على جميع المناطق في مديرية حيس."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/yvfwgrpcv','https://ajel.sa/international/yvfwgrpcv','https://ajel.sa/international/yvfwgrpcv','https://ajel.sa/international/yvfwgrpcv','فريق التحرير','','2026-09-05T04:48:00.000Z','Wed, 07 Oct 2026 21:17:50 GMT','2026-09-05T11:12:02.536Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-no9oVoUW.png','/api/media/d9be1d10-136b-49bb-838a-3b609432f0d9','/api/media/d9be1d10-136b-49bb-838a-3b609432f0d9?variant=thumbnail','اليمن.. مقتل مدنيين بهجمات حوثية بصواريخ ومسيرات على مواقع مدنية بتعز',1200,675,'valid','published','archived','valid',41,'d98c12e2b260b22b686f56131d7188194457f62122614fc249fd534b2124ad63','ca361a60a30260e5bba70ca180b4660dbdd501a11c49dd5072e3e8f0d0055ba2','محدّث','2026-09-05T11:12:02.536Z','2026-10-07T21:17:52.079Z','','',0,0,'gulf_arab','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["اليمن"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:17:52.079Z',200,24,0,'source_content_changed','',NULL,NULL,'body:770259d11fe8362bbabf3c93fbc25b0ef857769031c4e5567af657ad4c8d3fd3','Wed, 07 Oct 2026 21:17:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0a9cf3eb-fc5c-4c06-8c07-e2c131f1fec7','news-0a9cf3eb-fc5c-4c06-8c07-e2c131f1fec7','بهاء سلطان يتعرض لحادث سير أثناء عودته من الساحل الشمالي بمصر','بهاء سلطان يتعرض لحادث سير اثناء عودته من الساحل الشمالي بمصر','تعرض المطرب المصري بهاء سلطان، اليوم السبت، لحادث مروري بسيارته على طريق وادي النطرون أثناء عودته من مدينة العلمين. وتعرضت سيارة بهاء سلطان لتهشّم نتيجة الحادث، بعدما اصطدم سائق السيارة بإحدى السيارات الأخرى.','["تعرض المطرب المصري بهاء سلطان، اليوم السبت، لحادث مروري بسيارته على طريق وادي النطرون أثناء عودته من مدينة العلمين.","وأوضح ناصر بجاتو، مدير أعمال بهاء سلطان، أن حالة الفنان الصحية مستقرة، حيث غادر مستشفى العلمين بعد إجراء بعض الفحوصات، ويتجه حالياً إلى منزله في القاهرة .","وتعرضت سيارة بهاء سلطان لتهشّم نتيجة الحادث، بعدما اصطدم سائق السيارة بإحدى السيارات الأخرى.","يُذكر أن بهاء سلطان كان قد أحيا مؤخراً حفلاً غنائياً في مدينة أبوظبي بدولة الإمارات ، قدّم خلاله مجموعة من أغانيه الشهيرة، منها: دلوقتي عاجبناكوا، الواد قلبه بيوجعه، أنا غلطان، يا ترى، أنا مصمم، في ثانية ولع الجو، وأنا من غيرك.","وفي سياق آخر، طرحت الشركة المتحدة للخدمات الإعلامية أغنية وطنية جديدة بعنوان «بحبك يا بلدي مصر » بصوت بهاء سلطان، من كلمات عليم، وألحان عمرو مصطفى ، وتوزيع نادر حمدي، وإخراج مازن المتجول، ضمن الأعمال الفنية الداعمة للروح الوطنية."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/2zk7dzbjd','https://ajel.sa/misc/2zk7dzbjd','https://ajel.sa/misc/2zk7dzbjd','https://ajel.sa/misc/2zk7dzbjd','فريق التحرير','','2026-09-05T04:49:00.000Z','Wed, 07 Oct 2026 21:17:49 GMT','2026-09-05T11:12:02.573Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000285364-crop-9oz4CYHa.jpg','/api/media/0a9cf3eb-fc5c-4c06-8c07-e2c131f1fec7','/api/media/0a9cf3eb-fc5c-4c06-8c07-e2c131f1fec7?variant=thumbnail','بهاء سلطان يتعرض لحادث سير أثناء عودته من الساحل الشمالي بمصر',1200,675,'valid','published','archived','valid',41,'378df96abaa23e64ba7bd1f2d5d6dc7715a99570146587208af58057d8fd7a62','38e6ee9fb23b2be173e9494c9698efb8273e94d26b0f0b6384a73af0b0b69694','محدّث','2026-09-05T11:12:02.573Z','2026-10-07T21:17:51.243Z','','',0,0,'gulf_arab','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة"]','["الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:17:51.243Z',200,24,0,'source_content_changed','',NULL,NULL,'body:e0dcfe3ea2c78120fe01160aa1811db8bf06ef3b471111800944fc3300e037c7','Wed, 07 Oct 2026 21:17:49 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0433dccd-31fb-423b-ab55-3e5a1dc0bd60','news-0433dccd-31fb-423b-ab55-3e5a1dc0bd60','جامعة الدول العربية تفتتح دورتها الـ 166 بمناقشة القضية الفلسطينية والهجمات الإيرانية','جامعه الدول العربيه تفتتح دورتها الـ 166 بمناقشه القضيه الفلسطينيه والهجمات الايرانيه','انطلقت أعمال الدورة الـ 166 لمجلس جامعة الدول العربية بمقر الأمانة العامة في القاهرة، برئاسة مدير عام المنظمات المغاربية والعربية والإسلامية بالجمهورية التونسية السفير الهاشمي العجيلي، وبمشاركة مستشار الأمين العام للجامعة المشرف على مكتبه السفير شريف كامل. ورأس وفد المملكة العربية السعودية في أعمال الدورة مندوبُها الدائم لدى جامعة الدول العربية السفير…','["ورأس وفد المملكة العربية السعودية في أعمال الدورة مندوبُها الدائم لدى جامعة الدول العربية السفير عبدالعزيز بن عبدالله المطر.","وشهدت الجلسة الافتتاحية تسليم رئاسة الدورة من مملكة البحرين، ممثلةً في مندوبتها الدائمة لدى الجامعة السفيرة فوزية بنت عبدالله زينل، إلى ممثل الجمهورية التونسية.","ويناقش المندوبون الدائمون مشروع جدول أعمال يتضمن بنوداً سياسية واقتصادية واجتماعية وثقافية وقانونية وأمنية، في مقدمتها القضية الفلسطينية، والهجمات الإيرانية غير المشروعة ضد الدول العربية، فضلاً عن إجراء انتخابات لتعيين رؤساء عدد من اللجان الدائمة التابعة للمجلس، منها: لجنة حقوق الإنسان، ولجنة الأرصاد الجوية، واللجنة الدائمة للإعلام، ولجنة القانون الدولي الإنساني، إلى جانب تعيين قضاة المحكمة الإدارية للجامعة العربية.","وفي كلمتها خلال الجلسة الافتتاحية، قالت السفيرة فوزية زينل إن «الهجمات الإيرانية السافرة المتعمدة التي استهدفت دول مجلس التعاون لدول الخليج العربية والمملكة الأردنية الهاشمية تمثل انتهاكاً صارخاً للقانون الدولي، وتقوّض السلم والأمن في المنطقة كافة، لا سيما استهداف المدنيين والأعيان المدنية الذي يُعدّ مخالفة جسيمة لأحكام القانون الدولي الإنساني».","وحذّرت من خطورة هذه الاعتداءات، مشددةً على الموقف العربي الثابت في رفض التهديدات الموجهة لسيادة الدول العربية وأمن مواطنيها، مؤكدةً أن القضية الفلسطينية ستظل القضية المركزية الأولى، مشيرةً إلى أن الدورة الـ 165 شهدت حراكاً دبلوماسياً مكثفاً في مواجهة استمرار الانتهاكات والعدوان الإسرائيلي على قطاع غزة.","ودعت إلى ضرورة العمل على وقف إطلاق النار وإدخال المساعدات الإنسانية، وصون حقوق الشعب الفلسطيني في إقامة دولته المستقلة وعاصمتها القدس الشرقية وفق قرارات الشرعية الدولية ومبادرة السلام العربية، مؤكدةً أهمية الانتهاء من تنفيذ المرحلة الثانية من خطة السلام التي يرأسها الرئيس الأمريكي دونالد ترامب.","وأكدت أن الدورة السابقة انعقدت في مرحلة بالغة الحساسية في ظل ما تشهده المنطقة من صراعات وأزمات وتحديات جسيمة، مما يستوجب تعزيز العمل العربي المشترك وتنسيق المواقف ودعم القضايا العربية انطلاقاً من مبدأ الأمن القومي العربي باعتباره وحدة لا تتجزأ."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/8gs7ecd','https://sabq.org/article/8gs7ecd','','https://sabq.org/article/8gs7ecd','صحيفة سبق','المنطقة الشرقية','2026-09-05T05:06:00.000Z','2026-09-05T08:07:00.000Z','2026-09-05T11:12:03.712Z','https://media.sabq.org/news/2026/09/97cbc48c-efb4-4e87-b844-5a07c53efa0d/w1200.webp','/api/media/0433dccd-31fb-423b-ab55-3e5a1dc0bd60','/api/media/0433dccd-31fb-423b-ab55-3e5a1dc0bd60?variant=thumbnail','جامعة الدول العربية تفتتح دورتها الـ 166 بمناقشة القضية الفلسطينية والهجمات الإيرانية',1200,628,'valid','published','archived','valid',54,'3b26a8ba314da457ebba99e7bfa1363d88367dcd0cd2a874f82a9965ba394c4d','648163ff913abe1190abdba5e151c94f6be1f6014414b538e4b84c9f940f634d','محدّث','2026-09-05T11:12:03.712Z','2026-10-07T21:11:58.152Z','','',0,0,'saudi_region','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة الدول العربية تفتتح دورتها","مجلس التعاون لدول الخليج العربية","الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","السياسة والعلاقات الدولية","غزة","إيران"]','["جامعة الدول العربية تفتتح دورتها","مجلس التعاون لدول الخليج العربية","الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:11:58.152Z',200,23,0,'source_article_available','',NULL,NULL,'body:03cfb1d5a4249b38a2132fb5194102518e2d42ce2d3bc4878cb1b928f94f3310','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e31ea421-7f6d-4880-b3ac-34b3f2cd43a0','news-e31ea421-7f6d-4880-b3ac-34b3f2cd43a0','من هو لاعب ليفربول الذي يتواصل مع محمد صلاح بعد انتقاله إلى طرابزون التركي؟','من هو لاعب ليفربول الذي يتواصل مع محمد صلاح بعد انتقاله الي طرابزون التركي','أوضح محمد صلاح ، نجم فريق طرابزون سبور التركي عن اللاعب الذي يتواصل معه باستمرار من صفوف فريقه السابق ليفربول الإنجليزي. وأوضح أن سوبوسلاي هنأه بالانتقال إلى طرابزون وكان معجبا بالاستقبال الرائع من جماهير طرابزون لصلاح.','["أوضح محمد صلاح ، نجم فريق طرابزون سبور التركي عن اللاعب الذي يتواصل معه باستمرار من صفوف فريقه السابق ليفربول الإنجليزي.","وقال صلاح في مقطع فيديو للمركز الإعلامي لناديه إنه على تواصل مستمر مع زميله الهنغاري دومينيك سوبوسلاي نجم ليفربول الحالي.","وأوضح أن سوبوسلاي هنأه بالانتقال إلى طرابزون وكان معجبا بالاستقبال الرائع من جماهير طرابزون لصلاح.","وكان قد رحل محمد صلاح عن فريق ليفربول في نهاية الموسم الماضي، ووانضم إلى طرابزون سبور في الانتقالات الصيفية الحالية."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/uouu7dycg','https://ajel.sa/sports/uouu7dycg','https://ajel.sa/sports/uouu7dycg','https://ajel.sa/sports/uouu7dycg','فريق التحرير','','2026-09-05T05:11:00.000Z','Wed, 07 Oct 2026 21:19:58 GMT','2026-09-05T11:31:03.792Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D9%85%D8%AD%D9%85%D8%AF-%D8%B5%D9%84%D8%A7%D8%AD-VMcEDkF-.jpg','/api/media/e31ea421-7f6d-4880-b3ac-34b3f2cd43a0','/api/media/e31ea421-7f6d-4880-b3ac-34b3f2cd43a0?variant=thumbnail','من هو لاعب ليفربول الذي يتواصل مع محمد صلاح بعد انتقاله إلى طرابزون التركي؟',1200,675,'valid','published','archived','valid',41,'b95a43758bc27537a4d8ef94d8f205cf37199d7cee43328624ed9c80863bf443','711bb5f0b00253831d86ebfc5f53a98f5c38622e342342e03590f7cbd5ed5e1b','محدّث','2026-09-05T11:31:03.792Z','2026-10-07T21:20:00.541Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:20:00.541Z',200,29,0,'source_content_changed','',NULL,NULL,'body:9466fcd2a72cee2b36c3eafdd06b3cee1363bc88c7320196f5a3dd840a15c959','Wed, 07 Oct 2026 21:19:58 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('192744e9-f62a-4101-acee-afc4e8c2da33','news-192744e9-f62a-4101-acee-afc4e8c2da33','مقتل 4 خبراء إيرانيين ولبنانيين بقصف مركز قيادة حوثي في الجوف','مقتل 4 خبراء ايرانيين ولبنانيين بقصف مركز قياده حوثي في الجوف','أكدت مصادر عسكرية يمنية، ل قناة العربية ، مقتل 4 خبراء إيرانيين ولبنانيين في قصف مركز قيادة حوثي في الجوف . كان أعلن مكتب الأمم المتحدة للشؤون الإنسانية، عن نزوح 1790 عائلة نتيجة التصعيد في محافظة تعز .','["أكدت مصادر عسكرية يمنية، ل قناة العربية ، مقتل 4 خبراء إيرانيين ولبنانيين في قصف مركز قيادة حوثي في الجوف .","وأضافت المصادر، أن وحدات القوات المسلحة تحقق تقدما كبيرا في جبهة حيس جنوبي الحديدة ، كما تتقدم باتجاه مديرية جبل راس في حيس جنوبي الحديدة.","كان أعلن مكتب الأمم المتحدة للشؤون الإنسانية، عن نزوح 1790 عائلة نتيجة التصعيد في محافظة تعز .","ويواصل الجيش اليمني في تلك الأثناء مواجهة الميليشيات الحوثية الانقلابية في الجبهات كافة؛ لفرض الأمن في روبع البلاد."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/jqt9szapm','https://ajel.sa/international/jqt9szapm','https://ajel.sa/international/jqt9szapm','https://ajel.sa/international/jqt9szapm','فريق التحرير','الجوف','2026-09-05T05:10:00.000Z','Wed, 07 Oct 2026 21:20:41 GMT','2026-09-05T11:31:05.568Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-ZMOjppr_.png','/api/media/192744e9-f62a-4101-acee-afc4e8c2da33','/api/media/192744e9-f62a-4101-acee-afc4e8c2da33?variant=thumbnail','مقتل 4 خبراء إيرانيين ولبنانيين بقصف مركز قيادة حوثي في الجوف',1200,675,'valid','published','archived','valid',41,'5ce5d929e194a6caf5a392349b9b3b50e2b58f39d4112d763e5d50a476644fd3','3221498db6f7bd5f6b5074ec81e38212bba6055f429b100cfaf19eb083262fe4','محدّث','2026-09-05T11:31:05.568Z','2026-10-07T21:20:42.917Z','','',0,0,'saudi_region','مهم',63,NULL,0,0,0,'',NULL,NULL,NULL,'["الأمم المتحدة للشؤون الإنسانية عن","الجوف","لبنان","اليمن","إيران"]','["الأمم المتحدة للشؤون الإنسانية عن"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:20:42.917Z',200,30,0,'source_content_changed','',NULL,NULL,'body:1a5022722f74588218429a39b48a244afe049a0931a0a0774d818725121e8e1f','Wed, 07 Oct 2026 21:20:41 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ef227347-81ae-427f-a583-631d1d85b8c5','news-ef227347-81ae-427f-a583-631d1d85b8c5','الحصيني: غدا الأحد أول أيام الخريف فعليا','الحصيني غدا الاحد اول ايام الخريف فعليا','قال الباحث في الطقس والمناخ، عبدالعزيز الحصيني، إن غدا الأحد، هو أول نجوم الصفري وثاني نجوم سهيل وأول ايام الخريف فعلياً وهو الجبهة، وعدد أيامها 14 يوما.','["وأشار عبر حسابه على منصة «إكس» إلى أن موسم الجبهة هو الحد الفاصل بين الحر اللاهب والحر الهازل."]','البيئة والمناخ','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/x6atetcqr','https://ajel.sa/local/x6atetcqr','https://ajel.sa/local/x6atetcqr','https://ajel.sa/local/x6atetcqr','فريق التحرير','','2026-09-05T05:06:00.000Z','Wed, 07 Oct 2026 18:56:47 GMT','2026-09-05T11:31:05.792Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%B7%D9%82%D8%B3-4-UTDXuwmM.jpg','/api/media/ef227347-81ae-427f-a583-631d1d85b8c5','/api/media/ef227347-81ae-427f-a583-631d1d85b8c5?variant=thumbnail','الحصيني: غدا الأحد أول أيام الخريف فعليا',1200,675,'valid','rejected','archived','invalid',46,'253f1f90937bd502efa7f47e0ee2562a4a0d17bf1bf45ac111811ce64bd8bae4','d946ab562e36bbd3b758e7797cd7ae6da3836a31f2219a49a02355c4bd70be6c','محدّث','2026-09-05T11:31:05.792Z','2026-10-07T19:24:38.659Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ"]','["الطقس والمناخ"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T18:56:49.525Z',200,28,0,'source_content_changed','',NULL,NULL,'body:1b07133b15677eb447a51af48b03564737411a8facff60f605ab03811c3cf7db','Wed, 07 Oct 2026 18:56:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9c8f9e75-d185-4a5b-85e9-2a8963a029f9','news-9c8f9e75-d185-4a5b-85e9-2a8963a029f9','«مقر للأعمال» تطلق حملة «خلّي لك في أبحر مقر» لتعزيز مجتمع الأعمال في شمال جدة','مقر للاعمال تطلق حمله خلي لك في ابحر مقر لتعزيز مجتمع الاعمال في شمال جده','أطلقت «مقر للأعمال» التابعة لـ*«شركة مقر العالمية»* حملتها الجديدة «خلّي لك في أبحر مقر»، ضمن توجهها لتعزيز حضورها في شمال جدة، واستقطاب رواد الأعمال وأصحاب المنشآت والشركات والمهنيين الباحثين عن حلول عمل مرنة وبيئة مهنية متكاملة. نريد أن يكون لصاحب العمل في أبحر وشمال جدة مقر مهني قريب منه، يستطيع أن يعمل منه ويستقبل عملاءه ويبني من خلاله علاقاته وفرصه».','["أطلقت «مقر للأعمال» التابعة لـ*«شركة مقر العالمية»* حملتها الجديدة «خلّي لك في أبحر مقر»، ضمن توجهها لتعزيز حضورها في شمال جدة، واستقطاب رواد الأعمال وأصحاب المنشآت والشركات والمهنيين الباحثين عن حلول عمل مرنة وبيئة مهنية متكاملة.","وتركز الحملة على تقديم «مقر للأعمال» بوصفه مجتمع أعمال متكاملًا يتجاوز مفهوم توفير المكاتب ومساحات العمل، ليجمع في مكان واحد بيئة العمل المهنية والخدمات المساندة ومساحات الاجتماعات والفعاليات، بما يساعد أصحاب الأعمال على العمل والتواصل وبناء العلاقات وتطوير فرص النمو.","وتوفر «مقر للأعمال» في أبحر مجموعة متنوعة من حلول العمل تشمل المكاتب الخاصة، ومساحات العمل المشتركة، وغرف الاجتماعات، ومساحات اللقاءات والفعاليات المهنية، إلى جانب عدد من الخدمات المساندة التي تتيح لأصحاب المنشآت والمهنيين بدء أعمالهم واستقبال عملائهم وممارسة أنشطتهم في بيئة جاهزة للعمل.","وتأتي الحملة في إطار توجه «مقر للأعمال» نحو تلبية الاحتياجات المتغيرة لأصحاب المشاريع والمنشآت، خصوصًا مع تنامي الحاجة إلى حلول عمل أكثر مرونة تتيح للشركات والمهنيين الاستفادة من مكاتب جاهزة دون تحمل أعباء تأسيس وتشغيل المكاتب التقليدية.","وقال علي العطية، الرئيس التنفيذي لشركة مقر العالمية: «حملة \"خلّي لك في أبحر مقر\" ليست مجرد دعوة لاستئجار مكتب، بل دعوة للانضمام إلى مجتمع أعمال يجمع المكان والخدمات والعلاقات والفرص في بيئة واحدة.","نريد أن يكون لصاحب العمل في أبحر وشمال جدة مقر مهني قريب منه، يستطيع أن يعمل منه ويستقبل عملاءه ويبني من خلاله علاقاته وفرصه».","وأضاف أن مفهوم «مقر للأعمال» يقوم على صناعة تجربة متكاملة لأصحاب الأعمال، بحيث يصبح المكان جزءًا من رحلة نمو المشروع، وليس مجرد مساحة لأداء المهام اليومية.","كما يتيح «مقر للأعمال» استضافة ورش العمل واللقاءات المهنية والفعاليات ومجتمعات الأعمال، بما يسهم في تعزيز التواصل وتبادل الخبرات بين رواد الأعمال والمختصين وأصحاب المنشآت، وتحويل مساحة العمل إلى بيئة فاعلة لبناء العلاقات والفرص."]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wj7vwlo','https://sabq.org/article/wj7vwlo','','https://sabq.org/article/wj7vwlo','صحيفة سبق','مكة المكرمة','2026-09-05T05:34:00.000Z','2026-09-05T05:35:00.000Z','2026-09-05T14:55:07.061Z','https://media.sabq.org/news/2026/09/c5dc782b-1e4d-4291-a986-d14478a3a5b4/w1600.webp','/api/media/9c8f9e75-d185-4a5b-85e9-2a8963a029f9','/api/media/9c8f9e75-d185-4a5b-85e9-2a8963a029f9?variant=thumbnail','«مقر للأعمال» تطلق حملة «خلّي لك في أبحر مقر» لتعزيز مجتمع الأعمال في شمال جدة',1600,1066,'valid','published','archived','valid',44,'0dcfc8935049193dba31f01bd77c4f8774087b656c330f956f41da0658cd8665','563be1a9f44ec7a75f0a65de89183a30ed27591e924d625ae193b6dc796fd397','محدّث','2026-09-05T11:40:04.183Z','2026-10-07T20:25:22.789Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة مقر العالمية حملتها الجديدة","الثقافة والفنون","جدة"]','["شركة مقر العالمية حملتها الجديدة","الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:06:03.982Z',200,29,0,'source_article_available','',NULL,NULL,'body:c2c014815494e061247e7a27d6d1e98253f05ecc50a3d7f758d232fd15cde1c6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5a3b2b93-d579-442d-bcf6-e9c422cce05a','news-5a3b2b93-d579-442d-bcf6-e9c422cce05a','1075 حالة ضبط للممنوعات في منافذ المملكة الجمركية','1075 حاله ضبط للممنوعات في منافذ المملكه الجمركيه','وأكدت هيئة الزكاة والضريبة والجمارك أنها ماضية في إحكام الرقابة الجمركية على واردات وصادرات المملكة؛ تحقيقًا لأمن المجتمع وحمايته، وذلك بالتعاون والتنسيق المتواصل مع جميع شركائها من الجهات ذات العلاقة.','["سجّلت المنافذ الجمركية البرية والبحرية والجوية 1075 حالة ضبط للممنوعات، وذلك في إطار الجهود المستمرة التي تبذلها هيئة الزكاة والضريبة والجمارك «زاتكا» لتعزيز الجانب الأمني وحماية المجتمع من الممنوعات بمختلف أنواعها وأشكالها.","وشملت الأصناف المضبوطة 71 صنفًا من المواد المخدرة، مثل الحشيش، الكوكايين، الهيروين، الشبو، حبوب الكبتاجون وغيرها، إضافةً إلى 390 من المواد المحظورة.","كما شهدت المنافذ الجمركية إحباط 2234 من التبغ ومشتقاته، إلى جانب 39 صنفًا لمبالغ مالية، وصنفين من الأسلحة ومستلزماتها.","ودعت «زاتكا» في الوقت ذاته الجميع إلى الإسهام في مكافحة التهريب لحماية المجتمع والاقتصاد الوطني، من خلال التواصل معها على الرقم المخصص للبلاغات الأمنية (1910) أو عبر البريد الإلكتروني أو الرقم الدولي (009661910)، حيث تستقبل الهيئة من خلال هذه القنوات البلاغات المرتبطة بجرائم التهريب ومخالفات أحكام نظام الجمارك الموحد بسرية تامة، مع منح مكافأة مالية للمُبلّغ في حال صحة معلومات البلاغ."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/n7iu5ff','https://sabq.org/article/n7iu5ff','','https://sabq.org/article/n7iu5ff','صحيفة سبق','المدينة المنورة','2026-09-05T05:32:00.000Z','2026-09-05T08:33:00.000Z','2026-09-05T11:40:04.263Z','https://media.sabq.org/news/2026/09/22669538-4fe8-40c5-8490-6e0ff6551247/w1280.webp','/api/media/5a3b2b93-d579-442d-bcf6-e9c422cce05a','/api/media/5a3b2b93-d579-442d-bcf6-e9c422cce05a?variant=thumbnail','1075 حالة ضبط للممنوعات في منافذ المملكة الجمركية',1280,720,'valid','published','archived','valid',46,'b2d7d8303eeb18aaf4ea527b292c5a2cf09ee90d41eab4b4326731900fa91e33','996e58f3c3ae60095707f9a92b949825ef3a9082aa98feedfa788a846c12d45e','محدّث','2026-09-05T11:40:04.263Z','2026-10-07T19:06:06.304Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الزكاة والضريبة والجمارك زاتكا","الصحة العامة","الاقتصاد والأسواق"]','["هيئة الزكاة والضريبة والجمارك زاتكا","الصحة العامة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:06:06.304Z',200,28,0,'source_article_available','',NULL,NULL,'body:edd4ff279852b99f9e26688effebe8a75e95cdfbc14c3e3fc7736052c0582daa','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b1b17d68-f7a1-4e70-815f-33a9ace52de5','news-b1b17d68-f7a1-4e70-815f-33a9ace52de5','منصة عش بصحة تحذر من الجلوس الطويل خلال ساعات العمل: يزيد خطر أمراض القلب والسكري','منصه عش بصحه تحذر من الجلوس الطويل خلال ساعات العمل يزيد خطر امراض القلب والسكري','حذرت منصة عش بصحة التوعوية من مخاطر الجلوس لفترات طويلة خلال ساعات العمل، مؤكدة أن ذلك يرهق الجسم أكثر مما يتوقع الكثيرون. وأشارت المنصة، عبر منصة إكس ، إلى أن الجلوس المستمر، خاصة في وضعيات غير مناسبة، يؤدي إلى تيبس وإجهاد العضلات، وبطء تدفق الدم في الساقين، وزيادة خطر الإصابة بأمراض القلب والسكري.','["حذرت منصة عش بصحة التوعوية من مخاطر الجلوس لفترات طويلة خلال ساعات العمل، مؤكدة أن ذلك يرهق الجسم أكثر مما يتوقع الكثيرون.","وأوضحت المنصة أن الحركة البسيطة بين الحين والآخر تساهم في تنشيط الدورة الدموية والحفاظ على الصحة العامة.","وأشارت المنصة، عبر منصة إكس ، إلى أن الجلوس المستمر، خاصة في وضعيات غير مناسبة، يؤدي إلى تيبس وإجهاد العضلات، وبطء تدفق الدم في الساقين، وزيادة خطر الإصابة بأمراض القلب والسكري.","وفي السياق ذاته، شددت عش بصحة على أهمية ممارسة نشاط بدني بسيط بين فترة وأخرى أثناء ساعات العمل، لما له من دور في التخفيف من تيبس العضلات والحفاظ على مرونة الجسم ونشاطه."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/thehour/urfmhjv6n','https://ajel.sa/thehour/urfmhjv6n','https://ajel.sa/thehour/urfmhjv6n','https://ajel.sa/thehour/urfmhjv6n','فريق التحرير','','2026-09-05T05:38:00.000Z','Wed, 07 Oct 2026 19:07:43 GMT','2026-09-05T11:49:28.761Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000285403-crop-hpUxp9YV.jpg','/api/media/b1b17d68-f7a1-4e70-815f-33a9ace52de5','/api/media/b1b17d68-f7a1-4e70-815f-33a9ace52de5?variant=thumbnail','منصة عش بصحة تحذر من الجلوس الطويل خلال ساعات العمل: يزيد خطر أمراض القلب والسكري',1200,675,'valid','published','archived','valid',41,'291b46f8ebc132ed3f1fc8387ef1132f965688961d8a9bf9be91cdc0e8408c2b','1ead0fd3835be399d089b1cd216e19185b44ae0c2f09407e9f1f5c0f9e81272e','محدّث','2026-09-05T11:49:28.761Z','2026-10-07T20:25:22.789Z','','',0,0,'international','عادي',39,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة"]','["الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:07:45.482Z',200,29,0,'source_content_changed','',NULL,NULL,'body:a495faca09fa33e10dc9f76043e323a4ef2444fbd8be7f4e894282cfd93fd048','Wed, 07 Oct 2026 19:07:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7167288f-8bd2-4220-8340-cc1ec97dd5db','news-7167288f-8bd2-4220-8340-cc1ec97dd5db','أمريكا ترصد مكافأة 10 ملايين دولار مقابل معلومات عن أمير يارياب','امريكا ترصد مكافاه 10 ملايين دولار مقابل معلومات عن امير يارياب','رصدت الولايات المتحدة مكافأة 10 ملايين دولار مقابل معلومات عن أمير يارياب المتهم بقيادة العمليات السيبرانية الهجومية للحرس الثوري. يأتي ذلك في سياق برنامج «مكافأة في سبيل العدالة»، الذي يتهم يارياب بالإشراف على ضربات إلكترونية طالت قطاعات الطاقة والدفاع والملاحة والمال في الولايات المتحدة و أوروبا و الشرق الأوسط .','["رصدت الولايات المتحدة مكافأة 10 ملايين دولار مقابل معلومات عن أمير يارياب المتهم بقيادة العمليات السيبرانية الهجومية للحرس الثوري.","يأتي ذلك في سياق برنامج «مكافأة في سبيل العدالة»، الذي يتهم يارياب بالإشراف على ضربات إلكترونية طالت قطاعات الطاقة والدفاع والملاحة والمال في الولايات المتحدة و أوروبا و الشرق الأوسط .","يباشر يارياب إدارة شبكة واسعة تشمل قيادة وحدات هجومية متقدمة وشركات تكنولوجية تعمل كواجهة لأنشطة طهران ، والإشراف على وحدات نخبوية، وتنفيذ أنشطة هجومية."]','التقنية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/9emf6kzj2','https://ajel.sa/international/9emf6kzj2','https://ajel.sa/international/9emf6kzj2','https://ajel.sa/international/9emf6kzj2','فريق التحرير','','2026-09-05T05:34:00.000Z','Wed, 07 Oct 2026 19:07:42 GMT','2026-09-05T11:49:38.425Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/ai-edited/2026-09/bjIsKUznInZ87_BV.png','/api/media/7167288f-8bd2-4220-8340-cc1ec97dd5db','/api/media/7167288f-8bd2-4220-8340-cc1ec97dd5db?variant=thumbnail','أمريكا ترصد مكافأة 10 ملايين دولار مقابل معلومات عن أمير يارياب',1200,675,'valid','published','archived','valid',40,'e70989647e4586cd19affa60bedc8ae4cfa8f058253eecc342a08b424b82dbbc','dcd1be3a28ff149efc688681c904878c39d70e7a17b07c30e3b74337f8104f6b','محدّث','2026-09-05T11:49:38.425Z','2026-10-07T20:25:22.789Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","التقنية والتحول الرقمي","أوروبا","الشرق الأوسط","الولايات المتحدة"]','["الطاقة والنفط","التقنية والتحول الرقمي","الشرق الأوسط","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:07:44.419Z',200,29,0,'source_content_changed','',NULL,NULL,'body:1828dd0d01feaf43990a8dac749c5ec4c0a3adc11ac15909662d3a94d2aa3461','Wed, 07 Oct 2026 19:07:42 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c21f4d28-669c-4000-9205-fdd1bc96dc7d','news-c21f4d28-669c-4000-9205-fdd1bc96dc7d','حسن روحاني يدعو لاستفتاء شعبي حول استمرار المواجهة مع القوى الكبرى','حسن روحاني يدعو لاستفتاء شعبي حول استمرار المواجهه مع القوي الكبري','قال الرئيس الإيراني الأسبق، حسن روحاني ، إنه إذا كان من المقرر أن تواصل إيران القتال مع القوى الكبرى في العالم لمدة 20 عاماً أخرى، فينبغي أولاً سؤال الشعب عن رأيه.','["وبثت مواقع إيرانية قسم جديد من تسجيلات مصورة من لقاء روحاني مع عدد من المحافظين ونواب المحافظين والقائمقامين الذين عملوا خلال حكومتيه، وهو اللقاء الذي عقد في 31 أغسطس الماضي.","وقال روحاني: \"إذا قال الشعب إنه يقبل بذلك فهذا جيد جداً، ولنواصل الطريق.. لكن إذا لم يقبل الشعب وأرشدنا إلى طريق آخر، أفلا نريد أن نقبل؟\".","وأكد روحاني، أن \"كل من يشغل أي منصب في هذا البلد، وفي أي مستوى كان، تلقى منصبه كأمانة من الشعب\"."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/xt4vcpzfn','https://ajel.sa/international/xt4vcpzfn','https://ajel.sa/international/xt4vcpzfn','https://ajel.sa/international/xt4vcpzfn','فريق التحرير','','2026-09-05T05:34:00.000Z','Wed, 07 Oct 2026 19:07:38 GMT','2026-09-05T11:50:51.280Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%B1%D9%88%D8%AD%D8%A7%D9%86%D9%8A-_j9XMB03.jpg','/api/media/c21f4d28-669c-4000-9205-fdd1bc96dc7d','/api/media/c21f4d28-669c-4000-9205-fdd1bc96dc7d?variant=thumbnail','حسن روحاني يدعو لاستفتاء شعبي حول استمرار المواجهة مع القوى الكبرى',1200,675,'valid','published','archived','valid',41,'b7bf982db140cd85226514d79d1e9d7057e1911e95dac15faf43a553e0e2e040','653e95b96663f20b0a776cbe1c82a52c04d9791e07eeb734ba891ddf740dee85','محدّث','2026-09-05T11:50:51.280Z','2026-10-07T20:25:22.789Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["إيران"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:07:40.282Z',200,29,0,'source_content_changed','',NULL,NULL,'body:3a4864bcd0b9f7cd71a79dcb3a322edc3eed48ca94f40ad9c0bc72179243de05','Wed, 07 Oct 2026 19:07:38 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c5f66582-1129-4fba-9f54-218d70856ccf','news-c5f66582-1129-4fba-9f54-218d70856ccf','50 ضابطاً أمريكيا يخضعون لاختبار كشف الكذب بعد تسريبات عن نقص الذخائر','50 ضابطا امريكيا يخضعون لاختبار كشف الكذب بعد تسريبات عن نقص الذخائر','أخضع محققون حكوميون أميركيون نحو 50 ضابطاً وموظفاً في هيئة الأركان المشتركة لاختبارات كشف الكذب، عقب تسريبات إعلامية تضمنت معلومات حول نقص مخزونات ذخائر أساسية بسبب الحرب مع إيران ، بحسب ما نقلته صحيفة « نيويورك تايمز » عن مصادر مطلعة. وأجريت هذه الاختبارات في أغسطس، بعد تقارير كشفت عن تراجع مخزونات صواريخ بعيدة المدى وصواريخ اعتراضية لمنظومة «باتريوت».','["أخضع محققون حكوميون أميركيون نحو 50 ضابطاً وموظفاً في هيئة الأركان المشتركة لاختبارات كشف الكذب، عقب تسريبات إعلامية تضمنت معلومات حول نقص مخزونات ذخائر أساسية بسبب الحرب مع إيران ، بحسب ما نقلته صحيفة « نيويورك تايمز » عن مصادر مطلعة.","وأجريت هذه الاختبارات في أغسطس، بعد تقارير كشفت عن تراجع مخزونات صواريخ بعيدة المدى وصواريخ اعتراضية لمنظومة «باتريوت».","ووجه المحققون أسئلة للضباط والموظفين حول إفشاء معلومات سرية لوسائل الإعلام، خاصة ما يتعلق بتراجع مخزونات الذخائر الأميركية.","وأشارت الصحيفة إلى أن هذه الخطوة غير مسبوقة في تاريخ الجيش الأميركي الحديث، إذ لم يسبق إجراء اختبارات كشف كذب جماعية على هذا المستوى الرفيع، واعتبر الأميرال المتقاعد دونالد جيه. غوتر أن هذا الإجراء غير مسبوق في تجربته.","وأكد المتحدث باسم البنتاغون شون بارنل أن الوزارة لا تعلق على شؤون الموظفين أو التحقيقات، لكنها تتعامل بجدية مع تسريبات الأمن القومي وتجري التحقيقات اللازمة، مشدداً على أهمية حماية المعلومات السرية لأمن الولايات المتحدة وقواتها.","وتأتي الإجراءات في ظل ضغوط من الرئيس الأميركي دونالد ترمب لتكثيف ملاحقة مسربي المعلومات، واصفاً التغطية الإعلامية المنتقدة للنقص في الذخائر بأنها «خيانة».","وأدى ذلك إلى تعميق أجواء الشك داخل البنتاغون، خاصة في عهد وزير الدفاع بيت هيغسيث، الذي عرقل ترقيات عشرات المسؤولين وأقال ناشر ورئيس تحرير صحيفة «ستارز أند سترايبس» الحكومية، وسط انتقادات لإدارته وتغطية الصحافة للأوضاع العسكرية."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/7b1gv1niu','https://ajel.sa/international/7b1gv1niu','https://ajel.sa/international/7b1gv1niu','https://ajel.sa/international/7b1gv1niu','فريق التحرير','','2026-09-05T05:48:00.000Z','Wed, 07 Oct 2026 19:14:09 GMT','2026-09-05T12:02:01.950Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000285404-1QmNNqy9.webp','/api/media/c5f66582-1129-4fba-9f54-218d70856ccf','/api/media/c5f66582-1129-4fba-9f54-218d70856ccf?variant=thumbnail','50 ضابطاً أمريكيا يخضعون لاختبار كشف الكذب بعد تسريبات عن نقص الذخائر',1200,675,'valid','published','archived','valid',41,'388bc70dcd36f33881c1c030651d054b30dd377d1ba008dc2b9a403e8fcdde9e','d96f3c473ed664fc52e9423b6da4bd066dd618c0254c57ab1373a274d75fdf16','محدّث','2026-09-05T12:02:01.950Z','2026-10-07T20:25:22.789Z','','',0,0,'international','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الدفاع بيت هيغسيث الذي","هيئة الأركان المشتركة لاختبارات كشف","إيران","الولايات المتحدة"]','["وزير الدفاع بيت هيغسيث الذي","هيئة الأركان المشتركة لاختبارات كشف","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:14:11.597Z',200,30,0,'source_content_changed','',NULL,NULL,'body:8e2c59bacc2293b643445ae16616242951ef3e7d6d59941095d12e3dbc663314','Wed, 07 Oct 2026 19:14:09 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('042edef7-4e54-4aaf-8d07-368b34afadaa','news-042edef7-4e54-4aaf-8d07-368b34afadaa','«الدفاع المدني» تدعو إلى توخي الحيطة إثر الحالة المناخية في أجزاء من منطقة مكة المكرمة','الدفاع المدني تدعو الي توخي الحيطه اثر الحاله المناخيه في اجزاء من منطقه مكه المكرمه','دعت المديرية العامة للدفاع المدني إلى توخي الحيطة والحذر واتباع الإرشادات والتعليمات، إثر الحالة المناخية التي تشهدها منطقة مكة المكرمة، وذلك بناءً على الإنذار الأحمر الصادر من المركز الوطني للأرصاد.','["وأشارت المديرية عبر حسابها الرسمي على منصة \"إكس\"، إلى تعرض المنطقة لأمطار غزيرة، تستوجب أخذ أقصى درجات الحيطة، والابتعاد عن أماكن تجمعات المياه وبطون الأودية والسدود لضمان السلامة العامة.","وشددت المديرية العامة للدفاع المدني على أهمية الالتزام بتعليمات السلامة أثناء هطول الأمطار، وعدم المجازفة بقطع مجاري السيول."]','البيئة والمناخ','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/963plzmiy','https://ajel.sa/local/963plzmiy','https://ajel.sa/local/963plzmiy','https://ajel.sa/local/963plzmiy','فريق التحرير','مكة المكرمة','2026-09-05T05:45:00.000Z','Wed, 07 Oct 2026 19:14:09 GMT','2026-09-05T12:02:04.425Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%AF%D9%81%D8%A7%D8%B9-%D8%A7%D9%84%D9%85%D8%AF%D9%86%D9%8A-wKcSrRdA.jpg','/api/media/042edef7-4e54-4aaf-8d07-368b34afadaa','/api/media/042edef7-4e54-4aaf-8d07-368b34afadaa?variant=thumbnail','«الدفاع المدني» تدعو إلى توخي الحيطة إثر الحالة المناخية في أجزاء من منطقة مكة المكرمة',1200,675,'valid','published','archived','valid',91,'052421732f1566386dd416f6d3aae243a45896ced6552beda4f575089f98ac73','cfbece4496b0069874a7745fe3405ead7dfc525c02f6704f9c989a80f2ccfd1a','محدّث','2026-09-05T12:02:04.425Z','2026-10-07T19:14:11.620Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","التعليم والتدريب","مكة"]','["الطقس والمناخ","التعليم والتدريب"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:14:11.620Z',200,27,0,'source_content_changed','',NULL,NULL,'body:97e9908fdfdd709eb4064ccbfd57705465d46f110cf5768abb8ba9e811ac7b5e','Wed, 07 Oct 2026 19:14:09 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5b9a8587-1ec6-4297-a53c-a81c3619209f','news-5b9a8587-1ec6-4297-a53c-a81c3619209f','«المنافذ الجمركية»: تسجيل 1075 حالة ضبط للممنوعات خلال أسبوع','المنافذ الجمركيه تسجيل 1075 حاله ضبط للممنوعات خلال اسبوع','أعلنت المنافذ الجمركية البرية والبحرية والجوية، تسجيل 1075 حالة ضبط للممنوعات، وذلك في إطار الجهود المستمرة التي تبذلها هيئة الزكاة والضريبة والجمارك «زاتكا»؛ لتعزيز الجانب الأمني وحماية المجتمع من الممنوعات بمختلف أنواعها وأشكالها.','["وشملت الأصناف المضبوطة 71 صنفًا من المواد المخدرة، مثل: الحشيش، والكوكايين، والهيروين، والشبو، وحبوب الكبتاجون وغيرها، إضافةً إلى 390 صنفًا من المواد المحظورة.","كما شهدت المنافذ الجمركية إحباط 2234 من التبغ ومشتقاته، إلى جانب 39 صنفًا لمبالغ مالية، وصنفين لأسلحة ومستلزماتها.","وأكدت زاتكا أنها ماضية في إحكام الرقابة الجمركية على واردات المملكة وصادراتها؛ تحقيقًا لأمن المجتمع وحمايته، وذلك بالتعاون والتنسيق المتواصل مع جميع شركائها من الجهات ذات العلاقة.","ودعت زاتكا في الوقت ذاته الجميع إلى الإسهام في مكافحة التهريب لحماية المجتمع والاقتصاد الوطني، من خلال التواصل معها عبر الرقم المخصص للبلاغات الأمنية (1910)، أو البريد الإلكتروني ( [email&#160;protected] )، أو الرقم الدولي (009661910)، حيث تستقبل الهيئة من خلال هذه القنوات البلاغات المرتبطة بجرائم التهريب ومخالفات أحكام نظام الجمارك الموحد بسرية تامة، مع منح مكافأة مالية للمُبلّغ في حال صحة معلومات البلاغ."]','أخبار السعودية','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/jlkwc37o1','https://ajel.sa/local/jlkwc37o1','https://ajel.sa/local/jlkwc37o1','https://ajel.sa/local/jlkwc37o1','فريق التحرير','المدينة المنورة','2026-09-05T05:45:00.000Z','Mon, 07 Sep 2026 04:40:53 GMT','2026-09-05T12:02:04.756Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%AA%D9%87%D8%B1%D9%8A%D8%A8-JE1EjSc6.jpg','/api/media/5b9a8587-1ec6-4297-a53c-a81c3619209f','/api/media/5b9a8587-1ec6-4297-a53c-a81c3619209f?variant=thumbnail','«المنافذ الجمركية»: تسجيل 1075 حالة ضبط للممنوعات خلال أسبوع',1200,675,'valid','published','archived','valid',40,'c975fb84ddc9f7c4c55d0417649cf9fbe86ba8bdba1184bcbc8a526810b3d30d','e2a976302208cd44b86ad3a444eb38a397b5594899ed79a373bb18831e8d98b6','محدّث','2026-09-05T12:02:04.756Z','2026-10-07T19:14:56.582Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","هيئة الزكاة والضريبة والجمارك زاتكا","الصحة العامة","الاقتصاد والأسواق"]','["هيئة الزكاة والضريبة والجمارك زاتكا","الصحة العامة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:14:56.582Z',NULL,26,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b9537856-80df-4f71-a953-438fa142b3d3','news-b9537856-80df-4f71-a953-438fa142b3d3','خبراء: شعور الجوع بعد ممارسة الرياضة لا يعني زيادة الشهية بسبب التمرين','خبراء شعور الجوع بعد ممارسه الرياضه لا يعني زياده الشهيه بسبب التمرين','وتشير درسات إلى أن الشهية تتأثر مؤقتا بالنشاط البدني، بينما قد يؤدي استهلاك الطاقة خلال التمرين إلى ظهور شعور حقيقي بالجوع لاحقا، وفق " روسيا اليوم ".','["أكد خبراء بمجال التغذية، أن شعور الجوع بعد ممارسة الرياضة لا يعني زيادة الشهية بسبب التمرين.","وتسيطر ممارسة الرياضة على الشهية لفترة قصيرة بخفض هرمون \"غريلين\" المرتبط بالجوع، وزيادة هرمونات تعزز الشعور بالشبع. لكن هذا التأثير يتلاشى عادة خلال 30 إلى 90 دقيقة، ليعود مستوى الشهية الطبيعي. .","وقد يكون ذلك الشعور بسبب استهلاك الجسم كمية أكبر من الطاقة، فيستجيب لاحقا بزيادة الشعور بالجوع لاستعادة توازن الطاقة.لكن هناك عوامل أخرى قد تدفع إلى تناول المزيد من الطعام، منها الشعور بأن التمرين \"يستحق\" مكافأة، أو الخلط بين العطش والجوع نتيجة فقدان السوائل."]','المناطق','رياضة','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/ut5p9lar1','https://ajel.sa/misc/ut5p9lar1','https://ajel.sa/misc/ut5p9lar1','https://ajel.sa/misc/ut5p9lar1','فريق التحرير','الرياض','2026-09-05T05:29:00.000Z','Mon, 07 Sep 2026 04:40:54 GMT','2026-09-05T12:02:06.529Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-63hZ-GjP.jpg','/api/media/b9537856-80df-4f71-a953-438fa142b3d3','/api/media/b9537856-80df-4f71-a953-438fa142b3d3?variant=thumbnail','خبراء: شعور الجوع بعد ممارسة الرياضة لا يعني زيادة الشهية بسبب التمرين',1200,675,'valid','published','archived','valid',40,'fbc264e29c58636bcc72bfdd2501c7c4517f65c84c2a3cac73a8cff5aafeefc9','88f5ffea657b07f660a7228e2940203acc2da52298af734f4f346e7f99cb60e3','محدّث','2026-09-05T12:02:06.529Z','2026-10-07T20:25:22.789Z','','',0,0,'saudi_region','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["رياضة","الطاقة والنفط","الرياضة السعودية","روسيا","الرياض"]','["الطاقة والنفط","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Temporarily Unreachable','2026-10-07T19:15:17.759Z',NULL,27,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ce3976ea-719c-441f-a63a-326135d2ff0f','news-ce3976ea-719c-441f-a63a-326135d2ff0f','إعلام أمريكي: «ويتكوف» و«كوشنر» يحملان لـ «بوتين» مقترحًا جديدًا بشأن السلام في أوكرانيا','اعلام امريكي ويتكوف و كوشنر يحملان لـ بوتين مقترحا جديدا بشان السلام في اوكرانيا','ذكرت وسائل إعلام أمريكية، أن المبعوثين الأمريكيين جاريد كوشنر و ستيف ويتكوف ، يحملان إلى الرئيس الروسي فلاديمير بوتين مقترحا جديدا بشأن السلام في أوكرانيا .','["جاء ذلك بعد التصعيد الأخير بين روسيا وأوكرانيا، وتصاعد الغضب الأوروبي على إثر العثور على طائرة مسيرة روسية كانت ملغومة في أحد المطارات الألمانية الحيوية.","وكان الرئيس الأمريكي دونالد ترامب أعلن أنه سيرسل مبعوثيه إلى روسيا، في سياق جهود احتواء الصراع ووقف الحرب الروسية الأوكرانية."]','العالم','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/xosoa9ma1','https://ajel.sa/international/xosoa9ma1','https://ajel.sa/international/xosoa9ma1','https://ajel.sa/international/xosoa9ma1','فريق التحرير','','2026-09-05T05:59:00.000Z','Wed, 07 Oct 2026 19:43:37 GMT','2026-09-05T16:46:15.720Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/NZ9YXYEeQO5vY0va.jpg','/api/media/ce3976ea-719c-441f-a63a-326135d2ff0f','/api/media/ce3976ea-719c-441f-a63a-326135d2ff0f?variant=thumbnail','إعلام أمريكي: «ويتكوف» و«كوشنر» يحملان لـ «بوتين» مقترحًا جديدًا بشأن السلام في أوكرانيا',1200,675,'valid','published','archived','valid',41,'a8e272bac42dde7af2f946cc799a83e43daa854bdc13200e2dd04713a85cd0d5','16d0a3708c202a294d1fe34f22a1f085330722006e9ca099095afeb31ff093d4','محدّث','2026-09-05T12:20:02.425Z','2026-10-07T20:25:22.789Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["روسيا","أوكرانيا"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:43:39.055Z',200,30,0,'source_content_changed','',NULL,NULL,'body:bee09fe070c1e78d230a5650d913d566df34d18a6bdcfebdf4787020b8ad5ffa','Wed, 07 Oct 2026 19:43:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('026ff272-737c-4a47-ba83-5a5dd8906c16','news-026ff272-737c-4a47-ba83-5a5dd8906c16','مصدر: مظلوم عبدي لم يتسلم مهام منصبه كمستشار للشرع','مصدر مظلوم عبدي لم يتسلم مهام منصبه كمستشار للشرع','قال مصدر مقرب من مظلوم عبدي المعين مستشارا للرئيس السوري أحمد الشرع ، إنه لم يتسلم مهام منصبه برغم صدور قرار تعيينه. وأضاف المصدر لـ "العربية"، أن عبدي ينوي الانتقال بشكل دائم إلى دمشق بعد إنهاء ملفات عالقة تتعلق بعودة نازحين أكراد وتسليم أسلحة ثقيلة.','["قال مصدر مقرب من مظلوم عبدي المعين مستشارا للرئيس السوري أحمد الشرع ، إنه لم يتسلم مهام منصبه برغم صدور قرار تعيينه.","وأضاف المصدر لـ \"العربية\"، أن عبدي ينوي الانتقال بشكل دائم إلى دمشق بعد إنهاء ملفات عالقة تتعلق بعودة نازحين أكراد وتسليم أسلحة ثقيلة.","ومن المقرر أن تنحصر صلاحيات المنصب الجديد في إدارة الملف الكردي داخليًا وخارجيًا ومتابعة لجان دستورية وقانونية."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/oai7q1iuv','https://ajel.sa/international/oai7q1iuv','https://ajel.sa/international/oai7q1iuv','https://ajel.sa/international/oai7q1iuv','فريق التحرير','','2026-09-05T05:58:00.000Z','Wed, 07 Oct 2026 19:43:38 GMT','2026-09-05T12:20:04.382Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-arvdE5WR.png','/api/media/026ff272-737c-4a47-ba83-5a5dd8906c16','/api/media/026ff272-737c-4a47-ba83-5a5dd8906c16?variant=thumbnail','مصدر: مظلوم عبدي لم يتسلم مهام منصبه كمستشار للشرع',1200,675,'valid','published','archived','valid',41,'96282e516973e24acdae6dad96dc0d20d8d7d969dd180432a9019601e497bd62','d2a498c4c44fed6aab8fe18b903cc80212ddcaf18db7512b13dd912c1eeacad8','محدّث','2026-09-05T12:20:04.382Z','2026-10-07T20:25:22.789Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:43:40.391Z',200,30,0,'source_content_changed','',NULL,NULL,'body:42192ef71342a0fe88eb909a913744ad5c23b2f66b0714cb94d1966c44c46d7b','Wed, 07 Oct 2026 19:43:38 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b0b867cb-4239-42bc-a1d9-e36f060bd640','news-b0b867cb-4239-42bc-a1d9-e36f060bd640','الديوان العام للمحاسبة يوقّع مذكرة تفاهم مع نظيره الماليزي لتعزيز التعاون الرقابي','الديوان العام للمحاسبه يوقع مذكره تفاهم مع نظيره الماليزي لتعزيز التعاون الرقابي','وأكد معالي الدكتور العنقري سعي الديوان العام للمحاسبة المستمر نحو تعزيز التعاون الثنائي وتعظيم الشراكات الاستراتيجية مع الأجهزة النظيرة، انطلاقاً من دور الديوان القيادي في مجتمع الأجهزة العليا للرقابة المالية، وحرصه على مشاركة خبراته المهنية مع الأجهزة الأعضاء في المنظمات الإقليمية والدولية ذات الصلة.','["وقّع معالي رئيس الديوان العام للمحاسبة الدكتور حسام بن عبدالمحسن العنقري، ومعالي المراجع العام لمكتب المراجعة الوطني في ماليزيا وان سورايا وان محمد رادزي، مذكرة تفاهم للتعاون بين الجانبين في مجال العمل المحاسبي والرقابي والمهني، انطلاقاً من سعي الديوان نحو تعزيز تعاونه الاستراتيجي مع الأجهزة النظيرة في الدول الشقيقة والصديقة.","جرت مراسم التوقيع بمقر مكتب المراجعة الوطني في مدينة بوتراجايا الماليزية، بحضور سفير خادم الحرمين الشريفين لدى ماليزيا أسامة بن داخل الأحمدي.","تهدف المذكرة إلى تبادل الخبرات وبناء القدرات المهنية وتطوير أدلة العمل في مجال المراجعة المالية ومراجعة الأداء، عبر ورش عمل مشتركة وبرامج تدريبية متخصصة في الموضوعات ذات الاهتمام المشترك، وذلك في إطار عضوية الجهازين في المنظمة الدولية للأجهزة العليا للرقابة المالية العامة والمحاسبة «الإنتوساي»، والمنظمة الآسيوية للأجهزة العليا للرقابة المالية العامة والمحاسبة «الآسوساي».","من جانبها، نوّهت معالي وان سورايا رادزي بأهمية هذه المذكرة وما تمثله من تعزيز للعمل المشترك بين الجهازين؛ بما يُسهم في رفع كفاءة الأداء وتبادل الخبرات والارتقاء بجودة أعمال المراجعة لديهما.","وعقب التوقيع، عقد الجانبان اجتماعاً ثنائياً لبحث أوجه العمل المشترك وسُبل المواءمة في عدد من الموضوعات ذات العلاقة، بحضور المختصين من كلا الجهازين."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/focsrk7','https://sabq.org/article/focsrk7','','https://sabq.org/article/focsrk7','صحيفة سبق','المدينة المنورة','2026-09-05T06:09:00.000Z','2026-09-05T09:10:00.000Z','2026-09-05T12:20:05.007Z','https://media.sabq.org/news/2026/09/6a6acdf4-37ac-4589-a246-234a0909bbcd/w1600.webp','/api/media/b0b867cb-4239-42bc-a1d9-e36f060bd640','/api/media/b0b867cb-4239-42bc-a1d9-e36f060bd640?variant=thumbnail','الديوان العام للمحاسبة يوقّع مذكرة تفاهم مع نظيره الماليزي لتعزيز التعاون الرقابي',1600,1066,'valid','published','archived','valid',50,'48f82833f910757e1cf6cf6ed651fbb617d122ddd8e5df1af7fd7f5037c1000a','f898c5ba78f9ea9e2e1001e2ce1a6aed5462ceee73ae95aed1ef4427cdfd8e58','محدّث','2026-09-05T12:20:05.007Z','2026-10-07T19:43:04.380Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["خادم الحرمين الشريفين لدى ماليزيا","رئيس الديوان العام للمحاسبة الدكتور","التعليم والتدريب"]','["خادم الحرمين الشريفين لدى ماليزيا","رئيس الديوان العام للمحاسبة الدكتور","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:43:04.380Z',200,29,0,'source_article_available','',NULL,NULL,'body:24515d44df5e6145d64fa3b625d2877fb7585c2dd24fa9f6723651dfd4f63f09','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('de3ed582-3e52-47fc-bfb1-1854b2a4508b','news-de3ed582-3e52-47fc-bfb1-1854b2a4508b','المرور: ترك أجسام على الطرق العامة مخالفة مرورية','المرور ترك اجسام علي الطرق العامه مخالفه مروريه','وتابعت الإدارة، أن ارتكاب ذلك مخالفة مرورية غرامتها من 1000 ريال إلى 2000 ريال، وشددت على أن «الطريق مسؤولية الجميع، فلا ينبغي ترك ما قد يعرّض الآخرين للخطر عليه».','["حذرت الإدارة العامة للمرور ، من ترك أجسام على الطرق العامة."]','الوظائف وسوق العمل','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/3ibm68w8n','https://ajel.sa/local/3ibm68w8n','https://ajel.sa/local/3ibm68w8n','https://ajel.sa/local/3ibm68w8n','فريق التحرير','','2026-09-05T05:53:00.000Z','Mon, 07 Sep 2026 05:14:25 GMT','2026-09-05T12:20:05.837Z','https://cdn.ajel.sa/articles/2026-07/%D9%85-%D9%85%D9%85-%D9%85-%D9%85%D9%85%D8%B1%D9%88%D8%B1%D9%88-EPLup6vm.avif','/api/media/de3ed582-3e52-47fc-bfb1-1854b2a4508b','/api/media/de3ed582-3e52-47fc-bfb1-1854b2a4508b?variant=thumbnail','المرور: ترك أجسام على الطرق العامة مخالفة مرورية',960,611,'valid','rejected','archived','invalid',41,'895dd61f7a8c06a99b77ad5b1e890f7c49683322c2c9378213e6f2b42a1b4112','deb2f609ba7d74c887ac4ed707a4c7f92b2d06d96df5293cecf732d1a79bf817','محدّث','2026-09-05T12:20:05.837Z','2026-10-07T19:24:38.659Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-09-07T05:14:25.765Z',200,29,0,'source_content_changed','',NULL,NULL,'body:bf4c522c8bde4bb1e119640ffc306566abfab43d8c9af7f51d22bf88c9026c9c','Mon, 07 Sep 2026 05:14:25 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b3291532-9b2b-419d-86ec-16f9e991c7db','news-b3291532-9b2b-419d-86ec-16f9e991c7db','الشهراني في شنغهاي: المملكة وجهة استثمارية تجمع الاستقرار بالفرص','الشهراني في شنغهاي المملكه وجهه استثماريه تجمع الاستقرار بالفرص','ودعا الشركات الصينية إلى الاستفادة من الفرص التي توفرها المملكة والمشاركة في بناء الجيل القادم من الصناعات، مبيناً أن المملكة تمثل وجهة استثمارية تجمع بين الاستقرار والمتانة من جهة، والفرص والنمو من جهة أخرى.','["شارك وكيل وزارة الاستثمار للشؤون الاقتصادية ودراسات الاستثمار الدكتور سعد الشهراني في جلسة الحوار الاستراتيجي الاستثماري بين المملكة العربية السعودية وجمهورية الصين الشعبية، ضمن ملتقى الأسواق المالية «سيليكت» في شنغهاي، الذي تنظمه «تداول السعودية».","وأكد الدكتور الشهراني خلال الجلسة أن الصين تمثل شريكاً استثمارياً استراتيجياً للمملكة، مشيراً إلى أن المرحلة المقبلة تتجه نحو تعميق الاستثمارات المتبادلة، وتعزيز الشراكات الصناعية، وبناء سلاسل قيمة تخدم أسواق المملكة والمنطقة والعالم.","واستعرض وكيل وزارة الاستثمار التحولات الاقتصادية والاستثمارية التي شهدتها المملكة منذ إطلاق رؤية 2030، مبيناً أن حجم الاقتصاد السعودي تضاعف خلال العقد الماضي، كما تضاعف الاستثمار المحلي المقاس بتكوين رأس المال الثابت الإجمالي، وارتفعت مساهمة القطاع الخاص في إجمالي الاستثمار المحلي إلى الضعف.","وأشار إلى تضاعف رصيد الاستثمار الأجنبي المباشر في المملكة، وارتفاع تدفقاته بنحو خمسة أضعاف، فيما زاد عدد الشركات الأجنبية العاملة في المملكة بأكثر من عشرة أضعاف، إلى جانب تضاعف مشاركة المرأة في سوق العمل وانخفاض معدل البطالة بين المواطنين السعوديين بنسبة 50%.","وأوضح أن الاستثمار المحلي غير النفطي أصبح يمثل نحو 40% من الناتج المحلي الإجمالي غير النفطي، بما يضع المملكة في المرتبة الثانية بين دول مجموعة العشرين بعد الصين، مشيراً إلى أن الاستراتيجية الوطنية للاستثمار تجاوزت مستهدفاتها للاستثمار المحلي والأجنبي في كل عام منذ إطلاقها، فيما دخلت المملكة ضمن قائمة أفضل عشر دول عالمياً في مؤشر ثقة الاستثمار الأجنبي المباشر.","وأكد الدكتور الشهراني أن ثقة المستثمرين لا تنعكس فقط في دخول رؤوس أموال جديدة إلى المملكة، بل تظهر بصورة متزايدة في توسع الأعمال وإعادة الاستثمار والالتزامات الاستثمارية طويلة الأجل، مشدداً على أن المملكة لا تنتظر الفرص الاستثمارية بل تعمل على خلقها.","وبيّن أن رؤية 2030 لم تقتصر على تحسين البيئة الاستثمارية، وإنما أسهمت في إيجاد قطاعات وصناعات وفرص جديدة في مجالات السياحة والتعدين والتصنيع والخدمات اللوجستية والتقنية والاقتصاد الرقمي وغيرها من القطاعات الناشئة، لتتحول الاستثمارات من نتيجة للنمو إلى أحد محركاته الرئيسة.","وأوضح أن المرحلة المقبلة تركز بصورة أكبر على جذب الاستثمارات الأعلى جودة والأكثر إنتاجية، والانتقال من قياس الاستثمار بحجمه فقط إلى قياس أثره الاقتصادي، من خلال مساهمته في الناتج المحلي الإجمالي، ورفع الإنتاجية، ونقل التقنية والمعرفة، وتوفير الوظائف النوعية، وفتح أسواق جديدة وتعزيز الصادرات."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/84dvyhz','https://sabq.org/article/84dvyhz','','https://sabq.org/article/84dvyhz','صحيفة سبق','','2026-09-05T07:00:00.000Z','2026-09-05T10:01:00.000Z','2026-09-05T13:07:32.416Z','https://media.sabq.org/news/2026/09/ea0134a9-d7dc-4029-b372-d74fb16aed3d/w1600.webp','/api/media/b3291532-9b2b-419d-86ec-16f9e991c7db','/api/media/b3291532-9b2b-419d-86ec-16f9e991c7db?variant=thumbnail','الشهراني في شنغهاي: المملكة وجهة استثمارية تجمع الاستقرار بالفرص',1600,1067,'valid','published','archived','valid',91,'53c770cd3a82e910c2497ced9fa3ccf514eab145c4f45439d77a19ece89f63b4','712774f3c8a914c8912f3fa44ca0e9c4b8e085024f89de4235c9e66101912934','محدّث','2026-09-05T13:07:32.416Z','2026-10-07T20:49:58.857Z','','',0,0,'saudi_national','مهم',77,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الاستثمار للشؤون الاقتصادية ودراسات","الطاقة والنفط","السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي","الصين"]','["وزارة الاستثمار للشؤون الاقتصادية ودراسات","الطاقة والنفط","السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"التقنية","score":3},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:49:58.857Z',200,34,0,'source_article_available','',NULL,NULL,'body:33bbf8b9b845abceed563456c027cfed825a4334246a7a242922053b234cbc69','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a0bca8b7-9696-4f44-9acc-4025ef5836f8','news-a0bca8b7-9696-4f44-9acc-4025ef5836f8','السفير الأمريكي لدى «إسرائيل»: لا خطة لإجبار الفلسطينيين على مغادرة غزة','السفير الامريكي لدي اسرائيل لا خطه لاجبار الفلسطينيين علي مغادره غزه','قال السفير الأمريكي لدى دولة الاحتلال الإسرائيلي مايك هاكابي، اليوم، إنه ​لا توجد خطة لإجبار الفلسطينيين على مغادرة ‌ غزة ، وذلك بعد أن طرح وزيران إسرائيليان الأسبوع الماضي مقترحات لترحيل الفلسطينيين جماعيا من القطاع الساحلي.','["وأضاف هاكابي، وفق وكالة \" رويترز \"، \"أستطيع أن ⁠أؤكد لكم بشكل قاطع أنه لا توجد ​خطة لدى الإسرائيليين لترحيل السكان من غزة ​رغما عنهم\"، مشيرا إلى أن \"هناك انفتاح في التفكير مفاده أنه إذا رغب السكان في المغادرة، فيجب أن يكون لهم الحق ​في ذلك. أما حبسهم في مكان ​لا يرغبون في التواجد فيه، فهذا، في رأيي، أمر ‌مخز ⁠للغاية\".","وأشار السفير الأمريكي لدى إسرائيل \"لا أحد يقترح التهجير القسري.. الإسرائيليون لا يقترحون ذلك. والأمريكيون بالتأكيد لا يقترحونه. ولا أعرف أحدا يؤيد ذلك\".","في سياق آخر، كان وزير الدفاع الإسرائيلي ​ يسرائيل كاتس ، قال الأربعاء ⁠إنه \"لا يوجد في النهاية حل حقيقي لغزة دون هذه الهجرة\"."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/29h4ksbiy','https://ajel.sa/international/29h4ksbiy','https://ajel.sa/international/29h4ksbiy','https://ajel.sa/international/29h4ksbiy','فريق التحرير','','2026-09-05T06:49:00.000Z','Wed, 07 Oct 2026 20:50:04 GMT','2026-09-05T13:07:33.779Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-BuIWC3k7.jpg','/api/media/a0bca8b7-9696-4f44-9acc-4025ef5836f8','/api/media/a0bca8b7-9696-4f44-9acc-4025ef5836f8?variant=thumbnail','السفير الأمريكي لدى «إسرائيل»: لا خطة لإجبار الفلسطينيين على مغادرة غزة',1200,675,'valid','published','archived','valid',41,'69b851c427963ebfbc7b4aa31e80e59df0ba5dad3367f4d42eadfb8cee176fd8','205cd2a19c7a6e24d709d4d6057b540b58da2acae17d2dcd9d5e619cfdc3a6e3','محدّث','2026-09-05T13:07:33.779Z','2026-10-07T20:50:06.155Z','','',0,0,'gulf_arab','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الدفاع الإسرائيلي يسرائيل كاتس","غزة","فلسطين"]','["وزير الدفاع الإسرائيلي يسرائيل كاتس"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:50:06.155Z',200,35,0,'source_content_changed','',NULL,NULL,'body:b6240beefd7258230cb36ad3a79eed6f7bae7cae8fed6e136a783c6f5ad3a0ab','Wed, 07 Oct 2026 20:50:04 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('44b402c3-6da2-48b1-97e1-fd52b268ab47','news-44b402c3-6da2-48b1-97e1-fd52b268ab47','الدفاع المدني يخمد حريقًا في محال تجارية بحي الفيصلية الشمالية بتبوك','الدفاع المدني يخمد حريقا في محال تجاريه بحي الفيصليه الشماليه بتبوك','تمكنت فرق الدفاع المدني في تبوك من إخماد حريق اندلع في محال تجارية بحي الفيصلية الشمالية، دون تسجيل أي إصابات. وأوضحت المديرية العامة للدفاع المدني، عبر منصة «إكس»، أن فرقها باشرت الحريق في المحال التجارية بحي الفيصلية الشمالية، وتمكنت من إخماده.','["تمكنت فرق الدفاع المدني في تبوك من إخماد حريق اندلع في محال تجارية بحي الفيصلية الشمالية، دون تسجيل أي إصابات.","وأوضحت المديرية العامة للدفاع المدني، عبر منصة «إكس»، أن فرقها باشرت الحريق في المحال التجارية بحي الفيصلية الشمالية، وتمكنت من إخماده. وأكدت المديرية عدم تسجيل إصابات جراء الحريق."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/mwld4g7wn','https://ajel.sa/local/mwld4g7wn','https://ajel.sa/local/mwld4g7wn','https://ajel.sa/local/mwld4g7wn','فريق التحرير','تبوك','2026-09-05T06:48:00.000Z','Wed, 07 Oct 2026 20:50:05 GMT','2026-09-05T13:07:34.062Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-51RM45Gy.jpg','/api/media/44b402c3-6da2-48b1-97e1-fd52b268ab47','/api/media/44b402c3-6da2-48b1-97e1-fd52b268ab47?variant=thumbnail','الدفاع المدني',1200,675,'valid','published','archived','valid',41,'cbc9756d5a1bf06e2bbcd94e327307df07247d87c0f857a111d0c3467eec7c24','fc635bac299cc115fdf3feb14a810edf6942383047d74d4da8cf026068b43425','محدّث','2026-09-05T13:07:34.062Z','2026-10-07T20:50:07.340Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["تبوك"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:50:07.340Z',200,35,0,'source_content_changed','',NULL,NULL,'body:8d6b839c74bc3bb160cb9db0165d2eef437522782cc0a76e4d01c0bca707e322','Wed, 07 Oct 2026 20:50:05 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8f175b77-1acc-4b67-afa5-e9ffb05859a8','news-8f175b77-1acc-4b67-afa5-e9ffb05859a8','85 % إنجاز.. جسر طريق الثمامة بالرياض يقترب من الاكتمال','85 انجاز جسر طريق الثمامه بالرياض يقترب من الاكتمال','أعلنت الهيئة الملكية لمدينة الرياض أن الأعمال الميدانية في جسر طريق الثمامة عند تقاطعه مع طريق الأمير محمد بن سلمان تسير بوتيرة متقدمة، إذ تجاوزت نسبة الإنجاز 85%.','["ويُعدّ هذا الجسر أحد المحاور الحيوية في العاصمة الرياض، ويُتوقع أن يُسهم اكتماله في تعزيز كفاءة حركة المرور وتحسين الترابط بين الأحياء المحيطة به.","وتواصل الهيئة الملكية لمدينة الرياض الإشراف على تنفيذ المشروع ضمن جهودها المستمرة لتطوير البنية التحتية للعاصمة ورفع مستوى الخدمات المقدمة لسكانها."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/5m6nhl1','https://sabq.org/article/5m6nhl1','','https://sabq.org/article/5m6nhl1','صحيفة سبق','الرياض','2026-09-05T07:16:00.000Z','2026-09-05T10:17:00.000Z','2026-09-05T13:29:05.386Z','https://media.sabq.org/news/2026/09/b729900f-4d81-4191-8d6e-0584eb705119/w1600.webp','/api/media/8f175b77-1acc-4b67-afa5-e9ffb05859a8','/api/media/8f175b77-1acc-4b67-afa5-e9ffb05859a8?variant=thumbnail','  85 % إنجاز.. جسر طريق الثمامة بالرياض يقترب من الاكتمال',1600,1178,'valid','published','archived','valid',44,'75344dc7ec6ec95f78b3f883129f17a3b83b8dcdb1172cfba275ff89afe3c07b','e84f3d69a0fa93d35eb167155b7b687dfc26f8d9f2b8d9423255e79e1950ea82','محدّث','2026-09-05T13:29:05.386Z','2026-10-07T21:00:46.613Z','','',0,0,'saudi_region','مهم',69,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض"]','[]','needs_review','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"أخبار السعودية","score":2},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:00:46.613Z',200,24,0,'source_article_available','',NULL,NULL,'body:f581fc622fbeed293eabb4ea3d01a56aaa469499cee6ab5568a349033294f7a0','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2f562a74-a3df-4f55-88db-2bde8f8ab0c7','news-2f562a74-a3df-4f55-88db-2bde8f8ab0c7','وكيل وزارة الاستثمار: الصين شريك إستراتيجي والمرحلة المقبلة لبناء الصناعات معاً','وكيل وزاره الاستثمار الصين شريك استراتيجي والمرحله المقبله لبناء الصناعات معا','شارك وكيل وزارة الاستثمار للشؤون الاقتصادية ودراسات الاستثمار الدكتور سعد الشهراني في جلسة الحوار الإستراتيجي الاستثماري بين المملكة العربية السعودية وجمهورية الصين الشعبية، ضمن ملتقى الأسواق المالية «سيليكت» في شنغهاي، الذي تنظمه «تداول السعودية».','["وأكد الدكتور الشهراني خلال الجلسة أن الصين تمثل شريكاً استثمارياً إستراتيجياً للمملكة، مشيراً إلى أن المرحلة المقبلة تتجه نحو تعميق الاستثمارات المتبادلة، وتعزيز الشراكات الصناعية، وبناء سلاسل قيمة تخدم أسواق المملكة والمنطقة والعالم.","ودعا الشركات الصينية إلى الاستفادة من الفرص التي توفرها المملكة والمشاركة في بناء الجيل القادم من الصناعات، مبيناً أن الفصل القادم من الشراكة الاستثمارية السعودية - الصينية يتمثل في الاستثمار والبناء والابتكار والنمو معاً، مؤكداً أن المملكة تجمع بين الاستقرار والمتانة من جهة، والفرص والنمو من جهة أخرى.","واستعرض وكيل وزارة الاستثمار التحولات الاقتصادية والاستثمارية التي شهدتها المملكة منذ إطلاق رؤية 2030، مبيناً أن حجم الاقتصاد السعودي تضاعف خلال العقد الماضي، كما تضاعف الاستثمار المحلي المقاس بتكوين رأس المال الثابت الإجمالي، وارتفعت مساهمة القطاع الخاص في إجمالي الاستثمار المحلي إلى الضعف.","وأشار إلى تضاعف رصيد الاستثمار الأجنبي المباشر في المملكة، وارتفاع تدفقاته بنحو خمسة أضعاف، فيما زاد عدد الشركات الأجنبية العاملة في المملكة بأكثر من عشرة أضعاف، إلى جانب تضاعف مشاركة المرأة في سوق العمل وانخفاض معدل البطالة بين المواطنين السعوديين بنسبة 50%.","وأوضح أن الاستثمار المحلي غير النفطي أصبح يمثل نحو 40% من الناتج المحلي الإجمالي غير النفطي، بما يضع المملكة في المرتبة الثانية بين دول مجموعة العشرين بعد الصين، مشيراً إلى أن الإستراتيجية الوطنية للاستثمار تجاوزت مستهدفاتها للاستثمار المحلي والأجنبي في كل عام منذ إطلاقها، فيما دخلت المملكة ضمن قائمة أفضل عشر دول عالمياً في مؤشر ثقة الاستثمار الأجنبي المباشر.","وأكد الدكتور الشهراني أن ثقة المستثمرين لا تنعكس فقط في دخول رؤوس أموال جديدة إلى المملكة، بل تظهر بصورة متزايدة في توسع الأعمال وإعادة الاستثمار والالتزامات الاستثمارية طويلة الأجل، مشدداً على أن المملكة لا تنتظر الفرص الاستثمارية بل تعمل على خلقها.","وبيّن أن رؤية 2030 لم تقتصر على تحسين البيئة الاستثمارية، وإنما أسهمت في إيجاد قطاعات وصناعات وفرص جديدة في مجالات السياحة والتعدين والتصنيع والخدمات اللوجستية والتقنية والاقتصاد الرقمي وغيرها من القطاعات الناشئة، لتتحول الاستثمارات من نتيجة للنمو إلى أحد محركاته الرئيسة.","وأوضح أن المرحلة المقبلة تركز بصورة أكبر على جذب الاستثمارات الأعلى جودة والأكثر إنتاجية، والانتقال من قياس الاستثمار بحجمه فقط إلى قياس أثره الاقتصادي، من خلال مساهمته في الناتج المحلي الإجمالي، ورفع الإنتاجية، ونقل التقنية والمعرفة، وتوفير الوظائف النوعية، وفتح أسواق جديدة وتعزيز الصادرات."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wmnivp5','https://sabq.org/article/wmnivp5','','https://sabq.org/article/wmnivp5','صحيفة سبق','','2026-09-05T07:30:00.000Z','2026-09-05T10:31:00.000Z','2026-09-05T13:38:04.944Z','https://media.sabq.org/news/2026/09/f0a385d1-a6b6-4804-a683-48b9d24f07d9/w1600.webp','/api/media/2f562a74-a3df-4f55-88db-2bde8f8ab0c7','/api/media/2f562a74-a3df-4f55-88db-2bde8f8ab0c7?variant=thumbnail','وكيل وزارة الاستثمار: الصين شريك إستراتيجي والمرحلة المقبلة لبناء الصناعات معاً',1600,1067,'valid','published','archived','valid',86,'94b67932fe4a4d27d7c293f231d199f6350a1ad1553dd93ec50eb56ce5803777','98127e700a51059c6c75d520fe72647a4b86d199728c3c0c7782117ed48ffedb','محدّث','2026-09-05T13:38:04.944Z','2026-10-07T21:18:09.617Z','','',0,0,'saudi_national','مهم',77,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الاستثمار الصين شريك إستراتيجي","الطاقة والنفط","السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي","الصين"]','["وزارة الاستثمار الصين شريك إستراتيجي","الطاقة والنفط","السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"التقنية","score":3},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:18:09.617Z',200,25,0,'source_article_available','',NULL,NULL,'body:0d3517d2e2e2d26dd89416720441ed781507d0084620eb5a16e9e0520c874bc9','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7b4e59d3-c11d-4162-a93f-595c6d5040c6','news-7b4e59d3-c11d-4162-a93f-595c6d5040c6','"جسر العطاء السعودي" يعبر الحدود إلى 175 دولة بـ9,030 مشروعًا إنسانيًا','جسر العطاء السعودي يعبر الحدود الي 175 دوله بـ9 030 مشروعا انسانيا','يحتفي العالم في الخامس من سبتمبر من كل عام باليوم الدولي للعمل الخيري، وتبرز المملكة العربية السعودية في هذه المناسبة بسجل إنساني حافل، إذ قدّمت 9,030 مشروعًا إنسانيًا وتنمويًا وخيريًا في 175 دولة، بقيمة تجاوزت 145 مليار دولار أمريكي.','["وعلى رأس هذا المنظومة الإنسانية يقف مركز الملك سلمان للإغاثة والأعمال الإنسانية، الذي أسّسه خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود في 13 مايو 2015م، ليكون الذراع الإنساني للمملكة في الخارج.","وقدّم المركز منذ تأسيسه 4,457 مشروعًا إنسانيًا وإغاثيًا في 113 دولة، بقيمة تجاوزت 8 مليارات دولار أمريكي. **التطوع الخارجي: أرقام لافتة** أسهمت «البوابة السعودية للتطوع الخارجي» التابعة للمركز في تنظيم جهود التطوع الإنساني خارج المملكة، إذ شارك فيها 84,388 متطوعًا في 1,446 برنامجًا طبيًا وتدريبيًا وغيرها، استفاد منها 2,857,813 فردًا في 59 دولة، فضلًا عن إجراء 273,350 عملية جراحية. **برنامج التوائم الملتصقة: إنجاز إنساني نوعي** يُعدّ البرنامج السعودي للتوائم الملتصقة من أبرز مبادرات المركز، إذ درس 158 حالة، وأجرى 72 عملية ناجحة لتوائم ملتصقة قادمة من 28 دولة في خمس قارات.","ويتكفّل البرنامج بجميع نفقات الفصل والعلاج والتأهيل، إلى جانب مصاريف النقل واستضافة التوائم وذويهم داخل المملكة طوال فترة الرعاية الطبية.","وفي إطار هذا الإنجاز، اعتمدت الأمم المتحدة عام 2024م، بمبادرة من المملكة، يوم 24 نوفمبر يومًا عالميًا للتوائم الملتصقة، بهدف رفع مستوى الوعي بهذه الحالات والاحتفاء بالإنجازات الطبية في مجال فصلها. **التوثيق والتبرع الإلكتروني** أنشأ المركز منصات متخصصة لتوثيق المساعدات السعودية وتسجيلها دوليًا، من بينها منصة المساعدات السعودية، ومنصة المساعدات المقدمة للاجئين في المملكة، ومنصة التبرع الإلكترونية «ساهم» التي جمعت ما يزيد على مليار و701 مليون ريال، بمشاركة أكثر من 9 ملايين و829 ألف متبرع. **جوائز دولية** حصد المركز جملة من التكريمات الدولية، أبرزها جائزة المؤسسات الصديقة للأسرة والطفولة لعام 2024م من الأمانة العامة لجامعة الدول العربية، تقديرًا لجهوده في دعم الأطفال والأسر الفلسطينية، إضافة إلى جائزة الإنجاز الإنساني العالمي من المجلس الوطني للعلاقات الأمريكية العربية.","وتُوِّجت هذه الجهود باحتلال المملكة المرتبة الثانية عالميًا والأولى عربيًا بين الدول المانحة في تقديم المساعدات الإنسانية والإغاثية لعام 2025م، وفق منصة التتبع المالي التابعة للأمم المتحدة (FTS)، في مسيرة إنسانية تتواصل في ظل رؤية 2030."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/g74o8dt','https://sabq.org/article/g74o8dt','','https://sabq.org/article/g74o8dt','صحيفة سبق','المدينة المنورة','2026-09-05T07:40:00.000Z','2026-09-05T10:40:00.000Z','2026-09-05T13:47:04.973Z','https://media.sabq.org/news/2026/09/1e92099e-a39e-4cbc-9b07-604a711e4f87/w1600.webp','/api/media/7b4e59d3-c11d-4162-a93f-595c6d5040c6','/api/media/7b4e59d3-c11d-4162-a93f-595c6d5040c6?variant=thumbnail','"جسر العطاء السعودي" يعبر الحدود إلى 175 دولة بـ9,030 مشروعًا إنسانيًا',1600,1069,'valid','published','archived','valid',99,'0795d317bca7bb8b19913d137507a6acbbc771f8dace19577e10d30d5391ff0d','9bc1cd6119831021529f84ca8185945657e0a4a9641013d624e12b83bc49b3d7','محدّث','2026-09-05T13:47:04.973Z','2026-10-07T19:04:50.725Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["الأمم المتحدة عام","خادم الحرمين الشريفين الملك سلمان","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق","فلسطين"]','["الأمم المتحدة عام","خادم الحرمين الشريفين الملك سلمان","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق"]','classified','','[{"category":"المناطق","score":0},{"category":"الرياضة","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T19:04:50.725Z',200,25,0,'source_article_available','',NULL,NULL,'body:baa388ae9d96a35b1b999aa7e0f75c00e2eaeb2533d48cb2f90455c73f9c5209','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('54c8fd8f-d32f-4d0f-aaed-ce8edc7be825','news-54c8fd8f-d32f-4d0f-aaed-ce8edc7be825','غدًا الأحد.. «المرور» يطرح مزاد اللوحات الإلكتروني عبر «أبشر»','غدا الاحد المرور يطرح مزاد اللوحات الالكتروني عبر ابشر','يفتح مزاد اللوحات الإلكتروني عبر منصة «أبشر» أمام الراغبين في المزايدة على اللوحات المميزة غدًا الأحد، وفق ما أعلنته الإدارة العامة للمرور ، التي تتيح إتمام المشاركة في المزاد إلكترونيًا عبر المنصة.','["وأوضحت الإدارة العامة للمرور، عبر حسابها الرسمي على منصة «إكس»، أن الراغبين في المشاركة يبدأون بالدخول إلى منصة «أبشر»، ثم اختيار «خدماتي»، ومنها «المرور»، وبعدها خدمة «مزاد اللوحات الإلكتروني».","وبعد الدخول إلى الخدمة، يحدد المستخدم نوع لوحات المركبات، لتظهر أمامه اللوحات المتاحة التي يمكنه المشاركة في المزايدة عليها إلكترونيًا.","ويأتي المزاد ضمن الخدمات الإلكترونية التي توفرها منصة «أبشر» لشراء اللوحات المميزة، بما يتيح للمستخدمين استكمال إجراءات المشاركة في المزاد عبر المنصة."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/d9foocrwt','https://ajel.sa/local/d9foocrwt','https://ajel.sa/local/d9foocrwt','https://ajel.sa/local/d9foocrwt','فريق التحرير','عسير','2026-09-05T07:40:00.000Z','Wed, 07 Oct 2026 19:07:41 GMT','2026-09-05T13:56:03.487Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-LD4CVsoK.png','/api/media/54c8fd8f-d32f-4d0f-aaed-ce8edc7be825','/api/media/54c8fd8f-d32f-4d0f-aaed-ce8edc7be825?variant=thumbnail','مزاد اللوحات الإلكتروني',1200,675,'valid','published','archived','valid',41,'cbdd68e36775c7644c55730ba086aa30a007140e997c31c85ba69f91d1f2071f','bd4a89bd2a2e428dd5459bde8a976a1873e514c4abc0b20783a05cae45d8b0ed','محدّث','2026-09-05T13:56:03.487Z','2026-10-07T20:25:22.789Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["عسير"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:07:43.510Z',200,28,0,'source_content_changed','',NULL,NULL,'body:5390217ef9962ac8021dcc5a9bb519f0ce085a10b4bf463572e394f300667e48','Wed, 07 Oct 2026 19:07:41 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('df319623-6ae4-4c6d-bb6b-c07ca7bf5a1e','news-df319623-6ae4-4c6d-bb6b-c07ca7bf5a1e','الدفاع المدني بتبوك يخمد حريقاً في محال تجارية بحي الفيصلية الشمالية','الدفاع المدني بتبوك يخمد حريقا في محال تجاريه بحي الفيصليه الشماليه','أخمدت فرق الدفاع المدني في منطقة تبوك حريقاً اندلع في عدد من المحال التجارية بحي الفيصلية الشمالية، وأعلنت الجهات المختصة عدم تسجيل أي إصابات بشرية جراء الحادثة.','["وتمكّنت الفرق من السيطرة على النيران وإخمادها، في حين باشرت الجهات المعنية التحقيق في ملابسات الحريق وتحديد أسبابه."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/6vec52r','https://sabq.org/article/6vec52r','','https://sabq.org/article/6vec52r','صحيفة سبق','تبوك','2026-09-05T07:50:00.000Z','2026-09-05T10:50:00.000Z','2026-09-05T13:56:04.668Z','https://media.sabq.org/news/2026/07/1b015d87-fc43-464e-a7ca-111c1472274e/w1164.webp','/api/media/df319623-6ae4-4c6d-bb6b-c07ca7bf5a1e','/api/media/d