INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1e895c63-db3a-4367-a0f8-921e5c957717','news-1e895c63-db3a-4367-a0f8-921e5c957717','«لا موعد لنهاية الحرب مع إيران».. فانس: القتال مستمر ما دام الإيرانيون يطلقون النار على السفن','لا موعد لنهايه الحرب مع ايران فانس القتال مستمر ما دام الايرانيون يطلقون النار علي السفن','رفض نائب الرئيس الأمريكي جيه دي فانس تحديد موعد لإنهاء القتال مع إيران ، مؤكدًا أن استمرار العمليات يرتبط بطبيعة الهجمات الإيرانية على السفن، فيما قال إن العمليات القتالية الرئيسية استمرت نحو 6 أسابيع وحققت أهدافها.','["وقال فانس خلال مؤتمر صحفي إنه لا يرغب في وصف الوضع مع إيران بأنه «حرب»، كما رفض وضع جدول زمني لنهاية القتال، معتبرًا أن السؤال الأهم يتعلق بموعد توقف طهران عن استهداف السفن.","وأضاف أن الموقف الأمريكي يركز حاليًا على تقييم طبيعة الهجمات الإيرانية ضد حركة الملاحة، ومدى مستوى التهديد الذي تمثله لأسواق الطاقة.","وأشار نائب الرئيس الأمريكي إلى أن القتال سيستمر ما دام الإيرانيون يطلقون النار على السفن، في ظل تركيز واشنطن على تطورات الهجمات وتأثيرها على حركة الملاحة وأسواق الطاقة."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/m2ilzwaj8','https://ajel.sa/international/m2ilzwaj8','https://ajel.sa/international/m2ilzwaj8','https://ajel.sa/international/m2ilzwaj8','فريق التحرير','','2026-09-05T07:25:00.000Z','Wed, 07 Oct 2026 19:07:46 GMT','2026-09-05T13:56:05.006Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-dUz6a_B0.jpg','/api/media/1e895c63-db3a-4367-a0f8-921e5c957717','/api/media/1e895c63-db3a-4367-a0f8-921e5c957717?variant=thumbnail','فانس',1200,675,'valid','published','archived','valid',40,'5fd92464c810ecae3d698938d13a22025bb2ecd48297e9eb332193c579b98c2c','2ba7734160d10609425c9b6d1979e6a4fe60eea575fef5cd11d9f6f374783018','محدّث','2026-09-05T13:56:05.006Z','2026-10-07T20:25:22.789Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","إيران"]','["الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:07:48.663Z',200,27,0,'source_content_changed','',NULL,NULL,'body:d12c4e73f89ac6f6920cd4978f500c5754854d2853b02ffa795963eeb24cadaa','Wed, 07 Oct 2026 19:07:46 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('54dcd726-e3a7-4d0d-a455-6821f60e0e80','news-54dcd726-e3a7-4d0d-a455-6821f60e0e80','"سنتكوم": ضربات أمريكية تدمر 3 ناقلات نفط إيرانية بعد استهداف سفينتين حربيتين','سنتكوم ضربات امريكيه تدمر 3 ناقلات نفط ايرانيه بعد استهداف سفينتين حربيتين','وأفادت سنتكوم بأن حاملة طائرات أمريكية ومدمرة موجّهة بالصواريخ تمكّنتا من التهرب من هجمات إيرانية متعددة وُصفت بأنها «غير مستفزة»، مؤكدةً عدم تعرّض أي من أفراد القوات الأمريكية لأي أذى.','["أعلنت القيادة المركزية الأمريكية (سنتكوم) أن قواتها شنّت ضربات على ثلاث ناقلات نفط خام إيرانية تابعة للحرس الثوري الإسلامي (IRGC)، وذلك في الخامس من سبتمبر، في أعقاب إطلاق الحرس الثوري صواريخ باليستية نحو سفينتين حربيتين أمريكيتين كانتا تُجريان دوريات في المياه الإقليمية.","وفي إطار الرد، عطّلت القوات الأمريكية بصفة دائمة ناقلتَي النفط «M/T Downy» قبالة سواحل جزيرة خارك، و«M/T Stark 1» قرب جاسك.","كما دمّرت كلياً ناقلة النفط الخام «M/T Kylo» المعروفة أيضاً بـ«Noxen» في خليج عُمان، إذ استُهدفت في مواقع حيوية متعددة لتعطيلها كلياً، بعد توجيه طاقمها للإخلاء.","وأوضحت سنتكوم أن الناقلات الثلاث تُشكّل جزءاً من شبكة «ظل» بمليارات الدولارات تموّل الحرس الثوري الإيراني ووكلاءه الإقليميين، مشيرةً إلى أن إيران «لا تملك وسيلة للدفاع عنها».","وقال الأدميرال براد كوبر، قائد سنتكوم: «ليكن الرسالة للحرس الثوري واضحة: إذا أطلقتم النار على سفينتين من سفننا، فسنفرض تكلفة اقتصادية أعلى بكثير — بتدمير ثلاث من سفنكم».","وأضاف: «لن نتردد في الدفاع عن قواتنا الأمريكية، وإذا اقتضت الضرورة، سندمر الأسطول النفطي الإيراني المحدود والمكشوف»."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/dh0eycz','https://sabq.org/article/dh0eycz','','https://sabq.org/article/dh0eycz','صحيفة سبق','','2026-09-05T08:00:00.000Z','2026-09-05T11:00:00.000Z','2026-09-05T14:05:04.865Z','https://media.sabq.org/news/2026/09/c5f74658-580b-4870-b5ac-eff34a679e01/w964.webp','/api/media/54dcd726-e3a7-4d0d-a455-6821f60e0e80','/api/media/54dcd726-e3a7-4d0d-a455-6821f60e0e80?variant=thumbnail','"سنتكوم": ضربات أمريكية تدمر 3 ناقلات نفط إيرانية بعد استهداف سفينتين حربيتين',964,560,'valid','published','archived','valid',41,'7ab88075d0a3d4156c5456e63a36647881fc1913c2008174f612137b3996acc5','1ec7f2ca338e9cd26fb13756afbbdee8aef7de9cff08a5bb7db393c1755f0b8f','محدّث','2026-09-05T14:05:04.865Z','2026-10-07T20:25:22.789Z','','',0,0,'gulf_arab','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الرياضة السعودية","الاقتصاد والأسواق","إيران"]','["الطاقة والنفط","الرياضة السعودية","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Temporarily Unreachable','2026-10-07T19:13:38.150Z',NULL,29,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ea0d5010-c9b4-4eb3-89b8-b7947b95faf5','news-ea0d5010-c9b4-4eb3-89b8-b7947b95faf5','«بوتين» يوجه بوقف الضربات على كييف لـ3 أيام في إطار الاستعدادات لاستقبال الوفد الأمريكي','بوتين يوجه بوقف الضربات علي كييف لـ3 ايام في اطار الاستعدادات لاستقبال الوفد الامريكي','وجه الرئيس الروسي فلاديمير بوتين ، اليوم السبت، بعدم شن أي ضربات على كييف لـ3 أيام في إطار الاستعدادات لاستقبال الوفد الأمريكي. ووفق وكالة " سبوتنيك الروسية"، ذكر المتحدث باسم الكرملين ديميتري بيسكوف، أن «الرئيس الروسي فلاديمير بوتين أصدر قرارًا بوقف جميع الضربات الجوية على كييف لمدة ثلاثة أيام، اعتبارًا من منتصف ليل اليوم.','["وجه الرئيس الروسي فلاديمير بوتين ، اليوم السبت، بعدم شن أي ضربات على كييف لـ3 أيام في إطار الاستعدادات لاستقبال الوفد الأمريكي.","ووفق وكالة \" سبوتنيك الروسية\"، ذكر المتحدث باسم الكرملين ديميتري بيسكوف، أن «الرئيس الروسي فلاديمير بوتين أصدر قرارًا بوقف جميع الضربات الجوية على كييف لمدة ثلاثة أيام، اعتبارًا من منتصف ليل اليوم. ويعود ذلك إلى قيام المفاوضين الأمريكيين بالتحضير، وإجراء محادثات هناك».","وحثّ المتحدث باسم الرئاسة الروسية، ديمتري بيسكوف، على عدم التكهن بشأن أفكار التسوية، وانتظار لقاء الرئيس الروسي فلاديمير بوتين مع المفاوضين الأمريكيين.","وقال ديمتري بيسكوف، إن «الكرملين سيُطلع وسائل الإعلام على نتائج اجتماع الرئيس الروسي فلاديمير بوتين مع المبعوث الرئاسي الأمريكي ستيف ويتكوف وصهر الرئيس دونالد ترامب ، جاريد كوشنر ».","وفي وقت سابق من، اليوم، وصل المبعوث الرئاسي الأمريكي ستيف ويتكوف، وصهر الرئيس الأمريكي جاريد كوشنر، إلى العاصمة الروسية موسكو ، لإجراء محادثات بشأن أوكرانيا ."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/xes348et4','https://ajel.sa/international/xes348et4','https://ajel.sa/international/xes348et4','https://ajel.sa/international/xes348et4','فريق التحرير','','2026-09-05T07:55:00.000Z','Wed, 07 Oct 2026 19:36:08 GMT','2026-09-05T16:23:06.472Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-f5oGLyjr.jpg','/api/media/ea0d5010-c9b4-4eb3-89b8-b7947b95faf5','/api/media/ea0d5010-c9b4-4eb3-89b8-b7947b95faf5?variant=thumbnail','«بوتين» يوجه بوقف الضربات على كييف لـ3 أيام في إطار الاستعدادات لاستقبال الوفد الأمريكي',1200,675,'valid','published','archived','valid',41,'a85740045161b2f0eca4f0bd3514fb6c76c80cd266803368c3d293f5c18f1101','6566e0eca45b7c4058e5e49123dac57a9ba0e6c1f2bf5fd7a65f0cea826ea858','محدّث','2026-09-05T14:14:03.833Z','2026-10-07T20:25:22.789Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["أوكرانيا"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:36:10.143Z',200,30,0,'source_content_changed','',NULL,NULL,'body:37e0c2804836fd500879587c844639d802dce39d6797753bb0cc8850b155be8e','Wed, 07 Oct 2026 19:36:08 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ea054e27-5f90-48cd-a5c0-ff9b5dd6fc34','news-ea054e27-5f90-48cd-a5c0-ff9b5dd6fc34','القبض على 9 مخالفين من الجنسيتين اليمنية والإثيوبية لتهريبهم القات بجازان','القبض علي 9 مخالفين من الجنسيتين اليمنيه والاثيوبيه لتهريبهم القات بجازان','ألقت الدوريات البرية لحرس الحدود في قطاع الدائر، ب منطقة جازان ، القبض على 9 مخالفين لنظام أمن الحدود من الجنسيتين اليمنية والإثيوبية، لتهريبهم 200 كيلوجرام من نبات القات المخدر.','["وقالت \"حرس الحدود\"، عبر حسابها على منصة \"إكس\"، إنه جرى استكمال الإجراءات النظامية الأولية بحقهم، وتسليمهم والمضبوطات لجهة الاختصاص.","وتهيب الجهات الأمنية بالإبلاغ عن كل ما يتوافر من معلومات لدى المواطنين والمقيمين عن أي نشاطات ذات صلة بتهريب أو ترويج المخدرات، وذلك من خلال الاتصال بالأرقام (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض و الشرقية و(999) و(994) في بقية مناطق المملكة، ورقم بلاغات المديرية العامة لمكافحة المخدرات (995)، وعبر البريد الإلكتروني: (Email: [email&#160;protected] )، وستعالج جميع البلاغات بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/yj3jzetzn','https://ajel.sa/local/yj3jzetzn','https://ajel.sa/local/yj3jzetzn','https://ajel.sa/local/yj3jzetzn','فريق التحرير','الرياض','2026-09-05T07:55:00.000Z','Wed, 07 Oct 2026 19:36:06 GMT','2026-09-05T14:14:05.082Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-KsoYsnEU.jpg','/api/media/ea054e27-5f90-48cd-a5c0-ff9b5dd6fc34','/api/media/ea054e27-5f90-48cd-a5c0-ff9b5dd6fc34?variant=thumbnail','القبض على 9 مخالفين من الجنسيتين اليمنية والإثيوبية لتهريبهم القات بجازان',1200,675,'valid','published','archived','valid',40,'77ca4b2cea412337155e3d80035e6a336f8f0cc23adf1d1fc5572e21c1967756','7100313651253da6d289827aa6f3adbc54ec68aa58dfad71d8b8e6c0cfaa678f','محدّث','2026-09-05T14:14:05.082Z','2026-10-07T20:25:22.789Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","مكة","جازان","اليمن","الرياض","المدينة المنورة"]','["الرياضة السعودية","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:36:07.785Z',200,30,0,'source_content_changed','',NULL,NULL,'body:be51f5083a4ef731306e7549f0fbf8e1c45cf310b3ab2e05e92e166e6b55ed91','Wed, 07 Oct 2026 19:36:06 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('66d367c5-842f-4c91-9a2e-dcf18e8a6f28','news-66d367c5-842f-4c91-9a2e-dcf18e8a6f28','"القباني" يحطم الرقم القياسي ويتوج بالجولة الثانية من بطولة السعودية تويوتا كسر الزمن','القباني يحطم الرقم القياسي ويتوج بالجوله الثانيه من بطوله السعوديه تويوتا كسر الزمن','الترتيب العام تمكّن المتسابق فيصل القباني من تصدّر الترتيب العام بزمن دقيقة واحدة و11 ثانية و377 جزءاً من الألف من الثانية، مسجلاً بذلك رقماً قياسياً جديداً للبطولة.','["اختتمت منافسات الجولة الثانية من بطولة السعودية تويوتا كسر الزمن 2026، التي أُقيمت على حلبة كورنيش جدة خلال الفترة من 3 إلى 4 سبتمبر، بإشراف الاتحاد السعودي للسيارات والدراجات النارية بوصفه الجهة المالكة للبطولة، وبإدارة باخشب لرياضة المحركات، وبالشراكة مع جميل لرياضة المحركات الشريك الرسمي للبطولة.","وشهدت الجولة مشاركة 67 متسابقاً ومتسابقة، تنافسوا ضمن 11 فئة إلى جانب كأس السيدات.","وحلّ مأمون عمرو القباني في المركز الثاني بزمن دقيقة واحدة و11 ثانية و386 جزءاً من الألف من الثانية، فيما جاء مصطفى نبيل العطاري ثالثاً بزمن دقيقة واحدة و15 ثانية و380 جزءاً من الألف من الثانية.","نتائج الفئات في فئة «Class 1»، حقق فيصل القباني المركز الأول بزمن دقيقة واحدة و11 ثانية و377 جزءاً من الألف من الثانية، تلاه مأمون القباني ثانياً، ومصطفى العطاري ثالثاً.","وفي فئة «Class 2A»، تصدّر رياض بطل المنافسات بزمن دقيقة واحدة و20 ثانية و363 جزءاً من الألف من الثانية، وجاء أيمن خالق سيد وفهد عبدالله مكي في المركزين الثاني والثالث على التوالي.","أما فئة «Class 2B»، فحقق محمد الشريان المركز الأول بزمن دقيقة واحدة و19 ثانية و537 جزءاً من الألف من الثانية، وجاء سلطان حمدي ثانياً، وسامر محمد قربان ثالثاً.","وفي فئة «Class 3A»، تصدّر عبدالعزيز ساب المنافسات بزمن دقيقة واحدة و18 ثانية و629 جزءاً من الألف من الثانية، وجاء أحمد بن خنين ثانياً، وعبدالعزيز مجاهد ثالثاً.","وفي فئة «Class 3B»، توّج نواف علوش بالمركز الأول بزمن دقيقة واحدة و23 ثانية و163 جزءاً من الألف من الثانية، تلاه وسام خليل ثانياً، ثم ريم العبود ثالثةً."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/o0wltp0','https://sabq.org/article/o0wltp0','','https://sabq.org/article/o0wltp0','صحيفة سبق','مكة المكرمة','2026-09-05T08:06:00.000Z','2026-09-05T11:06:00.000Z','2026-09-05T14:14:05.190Z','https://media.sabq.org/news/2026/09/0c16c650-f992-4e32-a652-5aa2f2e79e39/w1600.webp','/api/media/66d367c5-842f-4c91-9a2e-dcf18e8a6f28','/api/media/66d367c5-842f-4c91-9a2e-dcf18e8a6f28?variant=thumbnail','"القباني" يحطم الرقم القياسي ويتوج بالجولة الثانية من بطولة السعودية تويوتا كسر الزمن',1600,1066,'valid','published','archived','valid',44,'e8221d59599e29b78a0fd1c7433a202633a20c9c792c5ec46b8b1d5f1ff5a0af','2bf17d0d579f2b1a6063d301678a0cc834f2c667c15270ccdded1edc96847115','محدّث','2026-09-05T14:14:05.190Z','2026-10-07T19:36:02.628Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","جدة"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الرياضة","score":3},{"category":"المناطق","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:36:02.628Z',200,29,0,'source_article_available','',NULL,NULL,'body:7705ce995bffd5e9fe79b75052f0a4e211f426c556bc9efcfc6aacf9527937de','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b050dee3-cf44-4468-896c-119370278c44','news-b050dee3-cf44-4468-896c-119370278c44','عشرات الملثمين يشلّون ميناء دوفر البريطاني ويعطلون حركة العبارات','عشرات الملثمين يشلون ميناء دوفر البريطاني ويعطلون حركه العبارات','أفادت وسائل إعلام بريطانية، اليوم السبت، بأن عشرات الملثمين تسببوا في شلّ حركة ميناء دوفر، الواقع في مقاطعة كينت جنوب شرق البلاد. وأعلنت شرطة كينت أنها «على علم بالاحتجاجات الجارية» وتتفاوض مع المتظاهرين، فيما لا تزال دوافعهم ومطالبهم مجهولة حتى اللحظة.','["أفادت وسائل إعلام بريطانية، اليوم السبت، بأن عشرات الملثمين تسببوا في شلّ حركة ميناء دوفر، الواقع في مقاطعة كينت جنوب شرق البلاد.","وانتشرت مقاطع مصورة تُظهر أشخاصاً بلباس أسود موحد أخفوا وجوههم بأقنعة، متجمعين في الميادين الرئيسية قرب الميناء الدولي صباح اليوم، مما أدى إلى عرقلة حركة المرور.","وأعلنت شرطة كينت أنها «على علم بالاحتجاجات الجارية» وتتفاوض مع المتظاهرين، فيما لا تزال دوافعهم ومطالبهم مجهولة حتى اللحظة.","وأقرّت سلطات دوفر في بيان رسمي بأن الاحتجاجات منعت سائقي السيارات من دخول الميناء أو مغادرته، وحذّرت شركات العبّارات العاملة على خط فرنسا عملاءها من احتمال حدوث اضطرابات في الخدمة.","ويُعدّ ميناء دوفر البوابةَ البحرية الرئيسية للمملكة المتحدة إلى أوروبا، وأكبر ميناء دولي للعبّارات في البلاد، إذ يتعامل مع بضائع بقيمة تقارب 144 مليار جنيه إسترليني (196 مليار دولار أمريكي) سنوياً، أي ما يعادل ثلث إجمالي تجارة المملكة المتحدة مع الاتحاد الأوروبي تقريباً.","وفي عام 2024، استقبل الميناء 9.35 مليون مسافر و2.16 مليون شاحنة، مما يجعل أي اضطراب فيه ذا تداعيات اقتصادية وخدمية واسعة."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/0fqhcpu','https://sabq.org/article/0fqhcpu','','https://sabq.org/article/0fqhcpu','صحيفة سبق','','2026-09-05T08:16:00.000Z','2026-09-05T11:16:00.000Z','2026-09-05T14:25:17.513Z','https://media.sabq.org/news/2026/09/d7802a1d-bfb1-4901-ac17-aceefd08a1d5/w801.webp','/api/media/b050dee3-cf44-4468-896c-119370278c44','/api/media/b050dee3-cf44-4468-896c-119370278c44?variant=thumbnail','عشرات الملثمين يشلّون ميناء دوفر البريطاني ويعطلون حركة العبارات',801,450,'valid','published','archived','valid',40,'7e4aac644038a739edd839fcb2538874656c02a7043ae43e0297e9382295cf8f','536fa8d6881cb75cfbc5617f8d6c1dbcc1374f9e851b493dd7a1b72f353d1de5','محدّث','2026-09-05T14:25:17.513Z','2026-10-07T20:25:22.789Z','','',0,0,'saudi_national','مهم',64,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","أوروبا"]','["الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:10.225Z',200,26,0,'source_article_available','',NULL,NULL,'body:aba102f1862a168273640ed336e6f2ecb785c0e3a6c3ac0a98f3d787f3e5b6ae','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('62de379d-2451-4080-8512-bc18ecf0bded','news-62de379d-2451-4080-8512-bc18ecf0bded','هل يحوّل سداد الحد الأدنى بطاقتك الائتمانية إلى فخ ديون؟ 41% يفعلونها','هل يحول سداد الحد الادني بطاقتك الائتمانيه الي فخ ديون 41 يفعلونها','كشفت دراسة حديثة أن أكثر من 4 من كل 10 أميركيين (41%) يواظبون على سداد الحد الأدنى فقط من المستحقات الشهرية على واحدة على الأقل من بطاقاتهم الائتمانية، وهي عادة يحذر الخبراء من أنها قد تؤدي إلى الوقوع في فخ الديون لفترات مطوّلة.','["وترتفع هذه النسبة إلى 58% بين أبناء الجيل «زد» الذين تتراوح أعمارهم بين 18 و29 عاماً، وفقاً لمسح أجرته منصة «LendingTree» وشمل أكثر من 1500 مستخدم لبطاقات الائتمان، نقلته شبكة «CNBC» الأمريكية.","رغم أن دفع الحد الأدنى يجنّب صاحب البطاقة رسوم التأخير والعقوبات المرتبطة بالتخلف عن السداد، فإن الجزء الأكبر من هذه الدفعات يذهب عادةً إلى الفوائد بدلاً من تخفيض أصل الدين، مما قد يُطيل فترة السداد لسنوات ويرفع التكلفة الإجمالية بشكل كبير.","وتصف «LendingTree» هذه الممارسة بأنها «واحدة من أسوأ العادات التي يمكن أن يعتاد عليها مستخدم بطاقة الائتمان».","وقالت كورينا روز، المستشارة المالية المعتمدة في شركة «Bell Investment Advisors»: «الحد الأدنى للدفع ليس استراتيجية لسداد الديون، بل استراتيجية للإبقاء عليها»، مضيفةً أن هذه الدفعات تحافظ على الحساب في وضع جيد، لكنها غالباً لا تحقق تقدماً حقيقياً في خفض الرصيد المستحق.","تكلفة باهظة على المدى الطويل بحسب بيانات «LendingTree»، يبلغ متوسط دين بطاقات الائتمان لدى الأمريكيين الذين يحملون أرصدة مستحقة نحو 7756 دولاراً، فيما يبلغ متوسط سعر الفائدة السنوي 20.94%.","وعند هذه المستويات، ومن دون إضافة أي مشتريات جديدة، فإن الاعتماد على الحد الأدنى للسداد قد يستغرق ما يقرب من 27 عاماً للتخلص من الدين بالكامل، مع دفع نحو 13 ألف دولار كفوائد فقط، وفقاً لحسابات «Bankrate».","وتؤكد روز أن كثيراً من حاملي البطاقات يعتقدون خطأً أن دفع الحد الأدنى يعني إحراز تقدم في السداد، في حين أنهم «يبقون في المكان نفسه فيما تواصل الفوائد التراكم».","ينصح الخبراء بمحاولة سداد الرصيد كاملاً كل شهر لتجنب الفوائد المرتفعة."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/lkjxkze','https://sabq.org/article/lkjxkze','','https://sabq.org/article/lkjxkze','صحيفة سبق','المنطقة الشرقية','2026-09-05T08:36:00.000Z','2026-09-05T11:36:00.000Z','2026-09-05T14:37:02.874Z','','','','هل يحوّل سداد الحد الأدنى بطاقتك الائتمانية إلى فخ ديون؟ 41% يفعلونها',NULL,NULL,'no_article_image_candidates','published','archived','valid',35,'b46468e957db3370dbbd2f470ba49d1ba3516743aa0d1b7b051fefdf5ee5b84f','ab1644bb3302129f7932aae8d1220a9d42e413599976ae858925e03cb30a5cc0','محدّث','2026-09-05T14:37:02.874Z','2026-10-07T20:25:22.789Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة Bell Investment Advisors الحد","الطاقة والنفط","الاقتصاد والأسواق"]','["شركة Bell Investment Advisors الحد","الطاقة والنفط","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:43:04.392Z',200,25,0,'source_article_available','',NULL,NULL,'body:f38f46a8a32c7a8ab31ea51a8bdfdb934ae1373ca54b08aca1ad43e2458f7f39','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1ae97a03-1232-41b7-b1ef-bfa608b663ed','news-1ae97a03-1232-41b7-b1ef-bfa608b663ed','أمام آلاف الزوار.. تحطم مقاتلة "إف-4 فانتوم" خلال عرض جوي في اليونان','امام الاف الزوار تحطم مقاتله اف 4 فانتوم خلال عرض جوي في اليونان','أفادت وكالة الأنباء اليونانية «أنا» بأن طائرة عسكرية من طراز «إف-4 فانتوم» تحطمت، السبت، في قاعدة جوية خارج العاصمة أثينا خلال عرض جوي، وسط حضور آلاف الزوار الذين كانوا يتابعون فعاليات «أسبوع أثينا للطيران» السنوي.','["وأوضح صحفي من هيئة الإذاعة والتلفزيون اليونانية العامة «إي آر تي» كان حاضراً في الموقع، أن الطائرة هوت فجأة بُعيد إقلاعها ثم انفجرت، مشيراً إلى أن ملابسات الحادث لم تتضح بعد.","ولا يزال مصير الطيارين اللذين كانا يستقلان الطائرة مجهولاً حتى لحظة إعداد هذا الخبر.","وأفادت «إي آر تي» بأن مروحية تابعة لجهاز الإطفاء أُرسلت فور وقوع الحادث إلى الموقع لإخماد الحريق الناجم عن الانفجار.","وعلى الصعيد الرسمي، ألغى وزير الدفاع اليوناني نيكوس ديندياس زيارة كانت مقررة له إلى معرض سالونيك الدولي، وتوجه فوراً إلى مكان الحادث."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ren5lp2','https://sabq.org/article/ren5lp2','','https://sabq.org/article/ren5lp2','صحيفة سبق','المنطقة الشرقية','2026-09-05T08:26:00.000Z','2026-09-05T11:26:00.000Z','2026-09-05T14:37:06.875Z','https://media.sabq.org/news/2026/09/3b3901b0-35bc-4ace-8f14-10ff036e4ea1/w801.webp','/api/media/1ae97a03-1232-41b7-b1ef-bfa608b663ed','/api/media/1ae97a03-1232-41b7-b1ef-bfa608b663ed?variant=thumbnail','أمام آلاف الزوار.. تحطم مقاتلة "إف-4 فانتوم" خلال عرض جوي في اليونان',801,451,'valid','published','archived','valid',41,'4e07e6a591fdd5b15e9d13cde9b4dd6569d1652f264ead9c5454f2808a0655c1','16f4a3c82780c87d0705f397b2c51f4eaa1b8a30167509559815254c3fdd68ec','محدّث','2026-09-05T14:37:06.875Z','2026-10-07T20:25:22.789Z','','',0,0,'saudi_region','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الدفاع اليوناني نيكوس ديندياس","هيئة الإذاعة والتلفزيون اليونانية العامة","السفر والسياحة"]','["وزير الدفاع اليوناني نيكوس ديندياس","هيئة الإذاعة والتلفزيون اليونانية العامة","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:43:02.737Z',200,22,0,'source_article_available','',NULL,NULL,'body:3a546b56c56269665b1868493116e0415e53681dbb00bd03198ee244bfe7a535','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1c3af9be-dfb1-4e9b-8886-08fdb79adcb9','news-1c3af9be-dfb1-4e9b-8886-08fdb79adcb9','«الاستثمار»: المملكة تتجه لتعميق الاستثمارات مع الصين وبناء سلاسل قيمة تخدم العالم','الاستثمار المملكه تتجه لتعميق الاستثمارات مع الصين وبناء سلاسل قيمه تخدم العالم','أكد وكيل وزارة الاستثمار للشؤون الاقتصادية ودراسات الاستثمار، الدكتور سعد الشهراني، أن « المملكة العربية السعودية تتجه إلى تعميق شراكتها الاستثمارية مع الصين ، عبر زيادة الاستثمارات المتبادلة وتعزيز الشراكات الصناعية وبناء سلاسل قيمة تخدم أسواق المملكة والمنطقة والعالم».','["وقال «الشهراني»، خلال مشاركته في جلسة الحوار الاستراتيجي الاستثماري بين المملكة والصين ضمن ملتقى الأسواق المالية «سيليكت» في شنغهاي، الذي تنظمه تداول السعودية ، إن «المرحلة المقبلة تركز على الاستثمار والبناء والابتكار والنمو المشترك».","ودعا الشركات الصينية إلى الاستفادة من الفرص الاستثمارية التي توفرها المملكة والمشاركة في بناء الجيل القادم من الصناعات، مؤكدًا أن المملكة تمثل وجهة استثمارية تجمع بين الاستقرار والمتانة من جهة، والفرص والنمو من جهة أخرى.","واستعرض وكيل وزارة الاستثمار التحولات التي شهدها الاقتصاد السعودي منذ إطلاق رؤية السعودية 2030، موضحًا أن حجم الاقتصاد تضاعف خلال العقد الماضي، كما تضاعف الاستثمار المحلي المقاس بتكوين رأس المال الثابت الإجمالي، وتضاعفت مساهمة القطاع الخاص في إجمالي الاستثمار المحلي.","وأشار إلى أن رصيد الاستثمار الأجنبي المباشر في المملكة تضاعف، فيما ارتفعت تدفقاته بنحو خمسة أضعاف، وزاد عدد الشركات الأجنبية العاملة في المملكة بأكثر من عشرة أضعاف، بالتزامن مع تضاعف مشاركة المرأة في سوق العمل وانخفاض معدل البطالة بين المواطنين السعوديين بنسبة 50%.","وأوضح «الشهراني» أن «الاستثمار المحلي غير النفطي يمثل نحو 40% من الناتج المحلي الإجمالي غير النفطي، ما يضع المملكة في المرتبة الثانية بين دول مجموعة العشرين بعد الصين»، لافتًا إلى أن الاستراتيجية الوطنية للاستثمار تجاوزت مستهدفاتها للاستثمار المحلي والأجنبي في كل عام منذ إطلاقها.","وأضاف أن «المملكة دخلت ضمن قائمة أفضل عشر دول عالميًا في مؤشر ثقة الاستثمار الأجنبي المباشر»، مشيرًا إلى أن ثقة المستثمرين لا تظهر فقط في تدفق رؤوس أموال جديدة، وإنما أيضًا في توسع الأعمال وإعادة الاستثمار والالتزامات الاستثمارية طويلة الأجل.","وأكد أن «المملكة لا تنتظر الفرص الاستثمارية، بل تعمل على خلقها»، موضحًا أن «رؤية السعودية 2030 لم تقتصر على تحسين البيئة الاستثمارية، وإنما أسهمت في إيجاد قطاعات وصناعات وفرص جديدة في السياحة والتعدين والتصنيع والخدمات اللوجستية والتقنية والاقتصاد الرقمي وغيرها من القطاعات الناشئة»."]','الاقتصاد','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/xr8ddk16w','https://ajel.sa/local/xr8ddk16w','https://ajel.sa/local/xr8ddk16w','https://ajel.sa/local/xr8ddk16w','فريق التحرير','','2026-09-05T08:27:00.000Z','Wed, 07 Oct 2026 19:53:50 GMT','2026-09-05T17:13:12.159Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-vi4nr3C5.jpg','/api/media/1c3af9be-dfb1-4e9b-8886-08fdb79adcb9','/api/media/1c3af9be-dfb1-4e9b-8886-08fdb79adcb9?variant=thumbnail','وكيل وزارة الاستثمار للشؤون الاقتصادية ودراسات الاستثمار الدكتور سعد الشهراني',1200,675,'valid','published','archived','valid',53,'39c60d266502f1f271410941df12318e0325512f24f5be112480f6f3cf0082b5','d759c83cb7ae95cc2da8d8fc5c25983fd620e083221de6d91b5f5116cd54a857','محدّث','2026-09-05T14:55:03.703Z','2026-10-07T20:25:22.789Z','','',0,0,'saudi_national','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","وزارة الاستثمار للشؤون الاقتصادية ودراسات","الطاقة والنفط","السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي","الصين"]','["وزارة الاستثمار للشؤون الاقتصادية ودراسات","الطاقة والنفط","السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":4.5},{"category":"الطاقة والصناعة","score":1.5},{"category":"البيئة والمناخ","score":1.5}]','Updated','2026-10-07T19:53:51.693Z',200,21,0,'source_content_changed','',NULL,NULL,'body:65f9150ab3282056a635f68ef9e2c87a83c97ee7f14e7d1a78b519daf055ee06','Wed, 07 Oct 2026 19:53:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b522b32f-3636-4952-b78c-8a77a22fef48','news-b522b32f-3636-4952-b78c-8a77a22fef48','5 دول أوروبية تسعى لإرسال مهاجرين إلى مراكز خارج الاتحاد الأوروبي','5 دول اوروبيه تسعي لارسال مهاجرين الي مراكز خارج الاتحاد الاوروبي','قالت دول ألمانيا و النمسا و اليونان و الدنمارك و هولندا التي تُعرف باسم "مجموعة الخمس"، إنها اتفقت على خطوات ملموسة نحو إبرام اتفاق لإنشاء مراكز لإعادة المهاجرين خارج أوروبا، دون أن تحدد الوجهات المتوقعة لاستضافة هذه المراكز.','["ووفق ما نقلته \"الشرق\"، لم تسم هذه الدول، المعروفة باسم \"مجموعة الخمس\"، البلدان التي تتوقع استضافة مراكز الإعادة. فيما تعتزم المجموعة، التي عقدت سلسلة اجتماعات هذا العام، الاجتماع مجدداً في ميونخ بألمانيا في نهاية سبتمبر.","كان البرلمان الأوروبي أقر في يونيو الماضي، إصلاحاً شاملاً لسياسة الهجرة يهدف إلى تسريع عمليات الترحيل والسماح للدول الأعضاء بإنشاء مراكز خارج الاتحاد، في خطوة يقول منتقدون إنها قد تضعف الضمانات الممنوحة لطالبي اللجوء.","وقال مجلس أوروبا (هيئة غير تابعة للاتحاد الأوروبي تُعنى بتعزيز حقوق الإنسان والديمقراطية وسيادة القانون في أنحاء القارة) في يوليو الماضي، إن مراكز الإعادة تنطوي على \"مخاطر كبيرة على حقوق الإنسان\"، كما انتقدت عدة جهات أخرى الخطة.","من جانبها قالت الأمينة العامة للمجلس الدنماركي للاجئين شارلوت سلينته، إن من الأفضل تطبيق ميثاق الاتحاد الأوروبي بشأن الهجرة واللجوء، الذي يركز على تشديد إجراءات التدقيق على الحدود وتسريع إجراءات اللجوء والعودة وتوسيع الأنظمة الرقمية لإدارة طلبات اللجوء، مشيرة إلى \"تركز مراكز الإعادة على عدد محدود من الحالات، ولن تمنع الناس من سلوك طرق أكثر خطورة، وقد تنتهك حقوق الإنسان الأساسية\".","فيما قال وزير الهجرة والاندماج الدنماركي مورتن بودسكوف إن الدنمارك تتوقع أن تكون مستعدة لإرسال مهاجرين إلى مركز الإعادة بحلول نهاية عام 2027، مشيرا إلى أن الدول الـ5 ستجري مشاورات بشأن الخطوات المقبلة مع المنظمة الدولية للهجرة التابعة للأمم المتحدة ومفوضية الأمم المتحدة السامية لشؤون اللاجئين.","من جانبها قال متحدث باسم المفوضية إنها لم تتلق أي تفاصيل بشأن المقترح، ولذلك لا يمكنها التعليق على الترتيبات قيد المناقشة.","على الجانب الأخر انتقدت منظمات غير حكومية هذه الخطط، معربة عن مخاوفها بشأن تأثيرها على حقوق الإنسان للمهاجرين المعنيين، ومن المرجح أن تواجه هذه الخطط عددا كبيرا من الطعون القانونية."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/ncrliv4zy','https://ajel.sa/international/ncrliv4zy','https://ajel.sa/international/ncrliv4zy','https://ajel.sa/international/ncrliv4zy','فريق التحرير','','2026-09-05T08:26:00.000Z','Wed, 07 Oct 2026 19:53:48 GMT','2026-09-05T14:55:04.589Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-_L7gk4-I.jpg','/api/media/b522b32f-3636-4952-b78c-8a77a22fef48','/api/media/b522b32f-3636-4952-b78c-8a77a22fef48?variant=thumbnail','5 دول أوروبية تسعى لإرسال مهاجرين إلى مراكز خارج الاتحاد الأوروبي',1200,675,'valid','published','archived','valid',41,'c13752235a08169103fdefb7c8c76d961bce1eb5524cc7f3c9c31ba3a23ab6f1','293ec9bc25b5a9a9c0619aabf81f1cf0e3729ff5f7e60784e82f824be5d696aa','محدّث','2026-09-05T14:55:04.589Z','2026-10-07T20:25:22.789Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس أوروبا هيئة غير تابعة","هيئة غير تابعة للاتحاد الأوروبي","الأمم المتحدة السامية لشؤون اللاجئين","وزير الهجرة والاندماج الدنماركي مورتن","التقنية والتحول الرقمي","السياسة والعلاقات الدولية","أوروبا"]','["مجلس أوروبا هيئة غير تابعة","هيئة غير تابعة للاتحاد الأوروبي","الأمم المتحدة السامية لشؤون اللاجئين","وزير الهجرة والاندماج الدنماركي مورتن","التقنية والتحول الرقمي","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:53:50.273Z',200,20,0,'source_content_changed','',NULL,NULL,'body:b205c7a86c9b8232fd994186334ec0a81f6961b24ecd4032c3315c34d138571e','Wed, 07 Oct 2026 19:53:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('abed7849-043f-4468-b446-46a67efc2577','news-abed7849-043f-4468-b446-46a67efc2577','روسيا تضرب 4 سفن في موانئ أوكرانية وهجوم صاروخي يوقف مصنع صلب ويودي بـ5 أرواح','روسيا تضرب 4 سفن في موانئ اوكرانيه وهجوم صاروخي يوقف مصنع صلب ويودي بـ5 ارواح','وأوضحت الوزارة في بيانها أن مسيرات «غيران-4 سيكير» استهدفت في ميناء تشيرنومورسك سفينتَي شحن للبضائع السائبة وسفينة حاويات، فيما ضربت سفينة شحن رابعة قرب ميناء أوديسا.','["أعلنت وزارة الدفاع الروسية اليوم السبت أن قواتها شنّت ضربات على أربع سفن شحن في ميناءَي تشيرنومورسك وأوديسا جنوب أوكرانيا، مؤكدةً أن هذه السفن كانت تُستخدم لنقل معدات عسكرية إلى القوات المسلحة الأوكرانية.","وأشار البيان إلى أن «لقطات المراقبة العملياتية أظهرت استهداف سفن تستخدم لنقل المعدات العسكرية لصالح القوات المسلحة الأوكرانية».","وأضافت الوزارة أن وحدات قوات المنظومات المسيرة «فارياغ» نفّذت هجوماً أصاب مصنعاً لإنتاج المسيرات في أوكرانيا، مشيرةً إلى اندلاع حريق كبير في المنشأة. **مصنع الصلب: 5 قتلى وتوقف كامل للإنتاج** في سياق متصل، أعلنت شركة «ميت انفست» للصلب أن هجوماً صاروخياً روسياً استهدف مصنع «كاميت ستيل» في منطقة دنيبرو شرق أوكرانيا، ما أسفر عن مقتل 5 أشخاص وإلحاق أضرار جسيمة بالبنية التحتية ومرافق الإنتاج، مما أدى إلى توقف العمليات بالكامل.","ووصفت الشركة الهجوم بأنه «دليل إضافي على الضربات المنهجية التي تشنّها روسيا على القاعدة الصناعية الأوكرانية»، مؤكدةً أن المصنع يقتصر إنتاجه على الحديد الخام والصلب للأغراض المدنية. **ضحايا في لوهانسك وكورسك** على صعيد آخر، أفاد ليونيد باسيتشنيك، الحاكم المعيَّن من موسكو في منطقة لوهانسك، بمقتل 5 أشخاص وإصابة 5 آخرين جراء غارات أوكرانية خلال الـ24 ساعة الماضية في الجزء الخاضع للسيطرة الروسية من المنطقة.","كما أعلن حاكم مقاطعة كورسك الروسية إصابة شخص في هجوم بمسيّرة أوكرانية."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/teyaupk','https://sabq.org/article/teyaupk','','https://sabq.org/article/teyaupk','صحيفة سبق','','2026-09-05T08:46:00.000Z','2026-09-05T11:46:00.000Z','2026-09-05T14:55:05.290Z','https://media.sabq.org/news/2026/09/504fdd68-28c0-4c0a-b44b-d6775b300eff/w801.webp','/api/media/abed7849-043f-4468-b446-46a67efc2577','/api/media/abed7849-043f-4468-b446-46a67efc2577?variant=thumbnail','روسيا تضرب 4 سفن في موانئ أوكرانية وهجوم صاروخي يوقف مصنع صلب ويودي بـ5 أرواح',801,451,'valid','published','archived','valid',41,'75ad02e99350c8c487749bc530f9dceaef6a9b2884bd0ae635db8889562d9c84','489bf8a075d67a74bffd6f3fce94707b375d4dadc5bc93a7f6e19dbb75760233','محدّث','2026-09-05T14:55:05.290Z','2026-10-07T20:25:22.789Z','','',0,0,'international','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة ميت انفست للصلب أن","وزارة الدفاع الروسية اليوم السبت","السفر والسياحة","روسيا","أوكرانيا"]','["شركة ميت انفست للصلب أن","وزارة الدفاع الروسية اليوم السبت","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:53:44.291Z',200,20,0,'source_article_available','',NULL,NULL,'body:0acbd77e98f4d11de815143397cf421812a5cde46383a03e3c132ed954f2611c','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5e2064cd-0b58-4d58-9a32-1cc93c3a79ff','news-5e2064cd-0b58-4d58-9a32-1cc93c3a79ff','«زاتكا» تُحدد 10 سبتمبر موعداً لتقديم نماذج استقطاع الضريبة عن أغسطس','زاتكا تحدد 10 سبتمبر موعدا لتقديم نماذج استقطاع الضريبه عن اغسطس','دعت هيئة الزكاة والضريبة والجمارك «زاتكا» المنشآت الخاضعة لضريبة الاستقطاع في المملكة العربية السعودية إلى تقديم نماذج استقطاع الضريبة عن شهر أغسطس 2026م، وذلك في موعد أقصاه 10 سبتمبر 2026م.','["وحثّت الهيئة المنشآت على المسارعة بتقديم النماذج عبر موقعها الإلكتروني (zatca.gov.sa)، تجنباً لغرامة التأخر عن السداد المقدّرة بـ 1% من الضريبة غير المسددة عن كل ثلاثين يوماً من تاريخ الاستحقاق.","وللاستفسار عن ضريبة الاستقطاع، دعت «زاتكا» المكلفين من قطاع الأعمال إلى التواصل معها عبر الرقم الموحد (19993) العامل على مدى 24 ساعة طوال أيام الأسبوع، أو عبر حساب «اسأل الزكاة والضريبة والجمارك» على منصة إكس (@Zatca_Care)، أو البريد الإلكتروني (info@zatca.gov.sa)، فضلاً عن خدمة المحادثات الفورية على الموقع الإلكتروني للهيئة.","وتُفرض ضريبة الاستقطاع على جميع المبالغ المدفوعة من مصدر في المملكة للجهات غير المقيمة التي لا تمتلك منشأة دائمة فيها، وفق الأسعار المحددة في المادة الثامنة والستين من نظام ضريبة الدخل والمادة الثالثة والستين من لائحته التنفيذية."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7luvyti','https://sabq.org/article/7luvyti','','https://sabq.org/article/7luvyti','صحيفة سبق','','2026-09-05T09:06:00.000Z','2026-09-05T12:08:00.000Z','2026-09-05T15:14:03.404Z','','','','«زاتكا» تُحدد 10 سبتمبر موعداً لتقديم نماذج استقطاع الضريبة عن أغسطس',NULL,NULL,'no_article_image_candidates','published','archived','valid',46,'053259b817acf49f80e8ebc70878b5fb9f298b46a5c1fbd778e704d65298053b','0378f93ecb4e2d886dbd00ce33fa811a6565e068965735e884546d14a6d9d502','محدّث','2026-09-05T15:14:03.404Z','2026-10-07T20:27:26.160Z','','',0,0,'saudi_national','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الزكاة والضريبة والجمارك زاتكا"]','["هيئة الزكاة والضريبة والجمارك زاتكا"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Temporarily Unreachable','2026-10-07T20:27:26.160Z',NULL,26,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('398b667d-551c-47f3-a1d1-6fc22af3039b','news-398b667d-551c-47f3-a1d1-6fc22af3039b','أول مشاركة سعودية تحصد المركز الأول عالميًا في "Hult Prize" باستثمار مليون دولار','اول مشاركه سعوديه تحصد المركز الاول عالميا في hult prize باستثمار مليون دولار','حققت شركة «FlowGuard» الناشئة من جامعة الملك عبدالله للعلوم والتقنية «كاوست» المركز الأول عالمياً في مسابقة «Hult Prize»، في أول مشاركة للمملكة العربية السعودية في هذه المنافسة العالمية المرموقة، بعد رحلة دعم وتمكين قدّمتها الهيئة العامة للمنشآت الصغيرة والمتوسطة «منشآت»، بدأت باستضافة المسابقة محلياً ودعم تنفيذها في المملكة.','["وأسهمت «منشآت» في تمكين انطلاق المشاركة السعودية في «Hult Prize» بالتعاون مع القطاع الخاص، من خلال استضافة المسابقة في المملكة وتوفير المحكّمين والخبرات اللازمة للمنافسة؛ مما أتاح للشركات الناشئة الجامعية السعودية فرصة المشاركة والتأهل إلى مراحلها العالمية للمرة الأولى.","وواصلت «منشآت» دعم فريق «FlowGuard» خلال مراحل مشاركته كافة، عبر تقديم خدمات الإرشاد والاستشارات المتخصصة، إلى جانب توظيف شبكة علاقاتها لربطه بفرص تجارية أسهمت في إغلاق مبيعات دعمت تأهله للمسرّعة، فضلاً عن مساندته في مراحل المنافسة المختلفة.","وشهدت المنافسة مشاركة نحو 18 ألف شركة ناشئة من 130 دولة، وتمكّنت «FlowGuard» من الوصول إلى قائمة أفضل 8 فرق عالمياً بوصفها الممثل الوحيد من الدول العربية في هذه المرحلة، قبل أن تتوّج بالمركز الأول وتحصل على استثمار تأسيسي بقيمة مليون دولار أمريكي لدعم نمو الشركة وتوسّع أعمالها.","ويعكس هذا الإنجاز أثر منظومة الدعم التي تقدّمها «منشآت» لريادة الأعمال الجامعية، بدءاً من إتاحة الفرص والمنصات التنافسية، مروراً بتطوير نماذج الأعمال والإرشاد والاستشارات والربط بالأسواق، وصولاً إلى تمكين الشركات الناشئة السعودية من المنافسة في المحافل الدولية.","وتواصل «منشآت» جهودها في دعم رواد الأعمال والشركات الناشئة الجامعية بالتعاون مع الجامعات وشركاء منظومة ريادة الأعمال؛ بما يسهم في بناء شركات سعودية أكثر قدرة على النمو والتوسع والمنافسة محلياً وعالمياً."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/nryend2','https://sabq.org/article/nryend2','','https://sabq.org/article/nryend2','صحيفة سبق','المنطقة الشرقية','2026-09-05T09:00:00.000Z','2026-09-05T12:00:00.000Z','2026-09-05T15:14:06.996Z','https://media.sabq.org/news/2026/09/0a52a8c4-7bd2-4828-a21e-c31abfb58669/w1600.webp','/api/media/398b667d-551c-47f3-a1d1-6fc22af3039b','/api/media/398b667d-551c-47f3-a1d1-6fc22af3039b?variant=thumbnail','أول مشاركة سعودية تحصد المركز الأول عالميًا في "Hult Prize" باستثمار مليون دولار',1600,1066,'valid','published','archived','valid',46,'03953e922e5e9c4229fa0665e0e640fcdfa1ba3798ec9f3a342603f98bfc4be3','7caac8a332486d3dd04f96a603a46343881ad9bad218bdb28eafea3ee8bfc0af','محدّث','2026-09-05T15:14:06.996Z','2026-10-07T20:27:26.168Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة FlowGuard الناشئة من جامعة","جامعة الملك عبدالله للعلوم والتقنية","الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["شركة FlowGuard الناشئة من جامعة","جامعة الملك عبدالله للعلوم والتقنية","الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"التقنية","score":1.5},{"category":"المناطق","score":0}]','Temporarily Unreachable','2026-10-07T20:27:26.168Z',NULL,27,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f7cd63a5-8525-4432-a1ae-ebf91ab4180d','news-f7cd63a5-8525-4432-a1ae-ebf91ab4180d','أفعى الحقل القرناء.. زاحف صحراوي فريد يتكيف مع بيئات شمال المملكة','افعي الحقل القرناء زاحف صحراوي فريد يتكيف مع بيئات شمال المملكه','وأوضح عضو جمعية أمان البيئية المهتم برصد الحياة الفطرية وتوثيقها، عدنان خليفة، أن أفعى الحقل القرناء تتمتع بقدرة كبيرة على التكيف مع طبيعة موائلها، مبيّناً أن ألوان جسمها ونقوشه تُعينها على الاندماج مع الصخور والتربة، «ما يجعل ملاحظتها في بيئتها الطبيعية أمراً يحتاج إلى دقة وانتباه».','["تُعدّ أفعى الحقل القرناء (Pseudocerastes fieldi)، المعروفة أيضاً بـ«أفعى فيلد المقرنة» و«الأفعى القرناء الكاذبة»، من أنواع الزواحف الصحراوية المنتشرة في منطقة الشرق الأوسط، وقد سُجّل وجودها في شمال المملكة العربية السعودية، حيث تتأقلم مع البيئات الجافة والصخرية والحصوية.","تتميز هذه الأفعى برأس عريض مثلث الشكل واضح الانفصال عن العنق، وخطم قصير، فيما تبرز فوق عينيها نتوءات شبيهة بالقرون تتكوّن من مجموعة حراشف صغيرة متراكبة، وهي من أبرز سماتها الشكلية المميزة، إضافةً إلى نهاية ذيلها الداكنة المائلة إلى السواد.","وتساعد ألوان جسمها المتدرجة بين البني والرمادي ودرجات قريبة من ألوان التربة والصخور على التمويه والاندماج مع البيئة المحيطة.","وتوجد في موائل جافة متنوعة، منها الصحاري الصخرية والجيرية والبازلتية والأودية والسهوب، وتُفضّل البيئات ذات الأسطح الصلبة على الكثبان الرملية المفتوحة.","وقال خليفة: «من أبرز السمات التي تميّز أفعى الحقل القرناء النتوءات الموجودة فوق العينين التي تبدو على هيئة قرون صغيرة، إلى جانب شكل الرأس العريض ونهاية الذيل الداكنة، فضلاً عن لون الجسم المتوافق مع طبيعة البيئة المحيطة، وهي خصائص تمنحها قدرة عالية على التخفي والتمويه».","وبيّن أن الأفعى تتغذى على عدد من الكائنات الصغيرة، منها القوارض والسحالي والطيور، وقد تُظهر سلوكاً افتراسياً نشطاً عند توافر الفرائس، مشيراً إلى أن وجودها يُمثّل جزءاً من التنوع الأحيائي في البيئات الصحراوية، ويُسهم في الحفاظ على التوازن الطبيعي ضمن السلسلة الغذائية.","وحذّر خليفة من الاقتراب من هذه الأفعى أو محاصرتها أو محاولة الإمساك بها عند مشاهدتها، مؤكداً ضرورة ترك مسافة آمنة وعدم استفزازها والابتعاد عن موقعها بهدوء، حفاظاً على سلامة الأشخاص والكائن الفطري في آنٍ واحد.","وأكد أهمية المحافظة على الزواحف والكائنات الفطرية في موائلها الطبيعية وعدم العبث بها، داعياً إلى تعزيز الوعي بالتنوع الأحيائي ودور مختلف الكائنات في صون التوازن البيئي."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ayxqyl7','https://sabq.org/article/ayxqyl7','','https://sabq.org/article/ayxqyl7','صحيفة سبق','','2026-09-05T09:16:00.000Z','2026-09-05T12:17:00.000Z','2026-09-05T15:23:05.900Z','https://media.sabq.org/news/2026/09/7e43de72-df7c-481e-b493-2605cf1ec904/w1600.webp','/api/media/f7cd63a5-8525-4432-a1ae-ebf91ab4180d','/api/media/f7cd63a5-8525-4432-a1ae-ebf91ab4180d?variant=thumbnail','أفعى الحقل القرناء.. زاحف صحراوي فريد يتكيف مع بيئات شمال المملكة',1600,1066,'valid','published','archived','valid',49,'05a6f69bdd505879f4448d1eff0e639d0bbc045c62734c53eab5c25ce35d93f8','0eddc622783ff677484877c4c1b8625a4e7673cb316c3d23fe52bc4b29b47603','محدّث','2026-09-05T15:23:05.900Z','2026-10-07T20:50:53.626Z','','',0,0,'saudi_national','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة قرون صغيرة إلى جانب","الشرق الأوسط"]','["هيئة قرون صغيرة إلى جانب","الشرق الأوسط"]','needs_review','below_category_threshold','[{"category":"المناطق","score":4},{"category":"المجتمع","score":1.5},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:50:53.626Z',200,22,0,'source_article_available','',NULL,NULL,'body:33c13fa475dff892be9b6d2e9d4440831562c90a982587d9ea75d035d81e46bb','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('617611a9-c26e-46d2-8012-9b6cdf555817','news-617611a9-c26e-46d2-8012-9b6cdf555817','السفارة الأمريكية في البحرين تصدر تحذيرا لمواطنيها من تصعيد محتمل في الشرق الأوسط','السفاره الامريكيه في البحرين تصدر تحذيرا لمواطنيها من تصعيد محتمل في الشرق الاوسط','أصدرت السفارة الأمريكية لدى البحرين ، تحذيرا أمنيا للمواطنين الأمريكيين، أكدت خلاله أن الوضع الأمني في الشرق الأوسط لا يزال معقدا مع احتمالية حدوث تصعيد غير متوقع.','["أصدرت السفارة الأمريكية لدى البحرين ، تحذيرا أمنيا للمواطنين الأمريكيين، أكدت خلاله أن الوضع الأمني في الشرق الأوسط لا يزال معقدا مع احتمالية حدوث تصعيد غير متوقع. وأشارت السفارة، عبر حسابها الرسمي على منصة \"إكس\"، في تنبيهها، إلى أن إيران استهدفت سابقا البنية التحتية المدنية في البحرين، بما في ذلك الفنادق في العاصمة المنامة ، داعية المواطنين الأمريكيين الموجودين حاليا في الشرق الأوسط إلى توخي يقظة متزايدة.","وشدد التحذير، وفق بيان السفارة الأمريكية لدى البحرين، على ضرورة إدراك احتمال إلغاء الرحلات الجوية، وإغلاق المجال الجوي، واضطرابات السفر بشكل عام، في ضوء التطورات الأمنية الراهنة."]','السفر','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/828fj3tj0','https://ajel.sa/international/828fj3tj0','https://ajel.sa/international/828fj3tj0','https://ajel.sa/international/828fj3tj0','فريق التحرير','عسير','2026-09-05T09:13:00.000Z','Wed, 07 Oct 2026 21:00:48 GMT','2026-09-05T15:32:04.114Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-r0xgi0Yz.jpg','/api/media/617611a9-c26e-46d2-8012-9b6cdf555817','/api/media/617611a9-c26e-46d2-8012-9b6cdf555817?variant=thumbnail','السفارة الأمريكية في البحرين تصدر تحذيرا لمواطنيها من تصعيد محتمل في الشرق الأوسط',1200,675,'valid','published','archived','valid',41,'c805e16eeca3e1baace76449664a24aed7086380de2d2e47d36b15e8448951c0','2c3982fe3e7d8cb394befdfa577e126c2bea7455113ba9ec91811c0e3a855c06','محدّث','2026-09-05T15:32:04.114Z','2026-10-07T21:00:50.347Z','','',0,0,'saudi_region','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","إيران","الشرق الأوسط"]','["السفر والسياحة","الشرق الأوسط"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:00:50.347Z',200,23,0,'source_content_changed','',NULL,NULL,'body:ef025388fc2c9094696dcdd432d8c0f4d5cef379961e57d52328929bfdb3c4de','Wed, 07 Oct 2026 21:00:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7bea13db-28fb-4b2f-833a-068deebfa868','news-7bea13db-28fb-4b2f-833a-068deebfa868','روسيا: هاجمنا 4 سفن تحمل شحنات عسكرية لأوكرانيا','روسيا هاجمنا 4 سفن تحمل شحنات عسكريه لاوكرانيا','وذكرت الوزارة في بيان، وفق "سبونتيك الروسية"، أن هذه السفن تستخدم لنقل شحنات عسكرية للقوات المسلحة الأوكرانية، موضحة أن قواتها استهدفت السفينتين بمسيرات "غيران-4 سيكير".','["أعلنت وزارة الدفاع الروسية، أن القوات الروسية شنت ضربات على سفينتين لنقل البضائع السائبة وسفينة حاويات في ميناء تشورنومورسك ، بالإضافة إلى سفينة أخرى لنقل البضائع السائبة بالقرب من أوديسا .","وجاء في بيان الوزارة: \"أظهرت لقطات المراقبة العملياتية استهداف سفن تستخدم لنقل المعدات العسكرية لصالح القوات المسلحة الأوكرانية في ميناءي تشيرنومورسك وأوديسا، حيث ضربت مسيرات \"غيران-4 سيكير\" في ميناء تشيرنومورسك سفينتي شحن وسفينة حاويات، كما تم ضرب سفينة شحن معادية أخرى في ميناء أوديسا\".","وأضافت الدفاع الروسية أن هجوماً نفذته وحدات قوات المنظومات المسيرة \"فارياغ\" أسفر عن إصابة مصنع لإنتاج المسيرات في أوكرانيا، مشيراً إلى رصد اندلاع حريق كبير في المصنع.","من جهتها قالت شركة \"ميت انفست\" للصلب، اليوم، إن هجوماً صاروخياً روسيًا على مصنع للصلب بمنطقة دنيبرو شرق أوكرانيا أسفر عن مقتل خمسة أشخاص وإلحاق أضرار بالبنية التحتية ومرافق الإنتاج، مما أدى إلى توقف العمليات بالكامل.","وأضافت الشركة في بيان \"هجوم آخر على منشأة مدنية تابعة لميت انفست لإنتاج الصلب، ودليل إضافي على الضربات المنهجية التي تشنها روسيا على القاعدة الصناعية الأوكرانية\".","من جانبه قال ليونيد باسيتشنيك، الحاكم المعين من جانب موسكو في منطقة لوهانسك ، اليوم إن خمسة أشخاص قتلوا وأصيب 5 آخرون جراء غارات أوكرانية خلال الساعات الـ 24 الماضية في الجزء الخاضع لسيطرة روسيا من المنطقة الأوكرانية."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/y239voxgv','https://ajel.sa/international/y239voxgv','https://ajel.sa/international/y239voxgv','https://ajel.sa/international/y239voxgv','فريق التحرير','','2026-09-05T09:08:00.000Z','Wed, 07 Oct 2026 21:00:52 GMT','2026-09-05T15:32:05.449Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-1O7GOx7w.jpg','/api/media/7bea13db-28fb-4b2f-833a-068deebfa868','/api/media/7bea13db-28fb-4b2f-833a-068deebfa868?variant=thumbnail','روسيا: هاجمنا 4 سفن تحمل شحنات عسكرية لأوكرانيا',1200,675,'valid','published','archived','valid',40,'ae957fd06a2072e8a44541b38c6ce8368fce65e62af321aa042cc9ae565021a3','076f4c28e30c232003ed27bac8f32205522683dd53041c00ba6df5d7a92bade2','محدّث','2026-09-05T15:32:05.449Z','2026-10-07T21:00:54.084Z','','',0,0,'international','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة ميت انفست للصلب اليوم","وزارة الدفاع الروسية أن القوات","السفر والسياحة","روسيا","أوكرانيا"]','["شركة ميت انفست للصلب اليوم","وزارة الدفاع الروسية أن القوات","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T21:00:54.084Z',200,23,0,'source_content_changed','',NULL,NULL,'body:8e215c57e9cf822cac3af4d1ece38c833b7d7f362045fed8f078b2deb07e0023','Wed, 07 Oct 2026 21:00:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e1565259-8b57-4476-8c6c-0591d4bbac78','news-e1565259-8b57-4476-8c6c-0591d4bbac78','الحرس الثوري ينفي تعرض المنشآت النووية في أصفهان لهجوم أمريكي إسرائيلي','الحرس الثوري ينفي تعرض المنشات النوويه في اصفهان لهجوم امريكي اسرائيلي','نفت دائرة العلاقات العامة في الحرس الثوري الإيراني بمحافظة أصفهان ، اليوم السبت، صحة الأنباء المتداولة بشأن تعرض المنشآت النووية في المحافظة لهجوم من قبل الولايات المتحدة أو جيش الاحتلال.','["ووفق وكالة \"تستنيم\" الإيرانية قالت دائرة العلاقات العامة في الحرس الثوري، إن ما يتم تداوله عبر منصات التواصل الاجتماعي بشأن استهداف المنشآت النووية في أصفهان \"عار تمامًا عن الصحة\"، مؤكدة عدم وقوع أي هجوم على تلك المنشآت.","وحذر البيان من تداول هذه الأخبار خلال الظروف الراهنة، معتبرًا أنها تهدف إلى إثارة البلبلة والقلق وزعزعة الاستقرار النفسي للمجتمع، ودعا إلى عدم إعادة نشر المعلومات غير الموثوقة.","كانت استأنفت الولايات المتحدة، في 31 أغسطس الماضي، غاراتها على إيران ، في أول هجوم أمريكي على إيران منذ أواخر يوليو.","وكانت إيران والولايات المتحدة، أعلنتا منتصف يونيو الماضي، التوصل إلى مذكرة تفاهم بوساطة دولية قادتها باكستان ، تتضمن ترتيبات لإنهاء الحرب التي شنتها الولايات المتحدة وإسرائيل ضد إيران، في 28 فبراير الماضي، وتمهيد الطريق أمام مفاوضات تمتد 60 يومًا، حول اتفاق أشمل يتناول الملف النووي الإيراني ورفع العقوبات والقضايا الشائكة الأخرى، قبل تعثر عملية التنفيذ والمفاوضات لاحقًا وانتهاء مدة الستين يومًا في الـ17 أغسطس."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/j04ocgh8i','https://ajel.sa/international/j04ocgh8i','https://ajel.sa/international/j04ocgh8i','https://ajel.sa/international/j04ocgh8i','فريق التحرير','المدينة المنورة','2026-09-05T09:09:00.000Z','Wed, 07 Oct 2026 21:00:48 GMT','2026-09-05T15:32:05.615Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-Fr32M7Uz.jpg','/api/media/e1565259-8b57-4476-8c6c-0591d4bbac78','/api/media/e1565259-8b57-4476-8c6c-0591d4bbac78?variant=thumbnail','الحرس الثوري ينفي تعرض المنشآت النووية في أصفهان لهجوم أمريكي إسرائيلي',1200,675,'valid','published','archived','valid',41,'0fbf2f78f8855cfaf8c1cf09281a8b9cb85c36c6eb0ff75edd72a6c2a695d454','471cdba015e92f713de5d62c63f38aead59713c84ef9c1a748534020d9bdba22','محدّث','2026-09-05T15:32:05.615Z','2026-10-07T21:00:50.273Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","السياسة والعلاقات الدولية","إيران","الولايات المتحدة"]','["الصحة العامة","السياسة والعلاقات الدولية","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:00:50.273Z',200,23,0,'source_content_changed','',NULL,NULL,'body:eee030c5d91252e15c74e6077181e7510869018d1cd7b364896041638830d1af','Wed, 07 Oct 2026 21:00:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1dee3bf7-03d3-48c1-bb74-1c996283193a','news-1dee3bf7-03d3-48c1-bb74-1c996283193a','"هيئة المقاولين" تعزز الشراكات الدولية في سنغافورة وتفتح آفاقًا جديدة للقطاع السعودي','هيئه المقاولين تعزز الشراكات الدوليه في سنغافوره وتفتح افاقا جديده للقطاع السعودي','وفي إطار تعزيز التعاون المؤسسي وتبادل الخبرات، عقد وفد الهيئة اجتماعًا مع وفد هيئة البناء والتشييد السنغافورية (BCA)، تناول فرص تطوير التعاون بين الجانبين، والاطلاع على تجربة سنغافورة في رفع إنتاجية قطاع البناء، والتصميم المسبق والبناء المعياري، والتحول الرقمي.','["عام / الهيئة السعودية للمقاولين تختتم زيارتها إلى سنغافورة بتعزيز الشراكات الدولية واستكشاف فرص تطوير القطاع اختتم وفد الهيئة السعودية للمقاولين، برئاسة رئيس مجلس الإدارة محمد بن عبدالعزيز العجلان، برنامج زيارته إلى جمهورية سنغافورة، التي تضمنت سلسلة من اللقاءات والاجتماعات مع عدد من الجهات والمؤسسات والشركات السنغافورية، إلى جانب المشاركة في أسبوع البيئة العمرانية الدولي IBEW 2026، وذلك في إطار جهود الهيئة لتعزيز حضور قطاع المقاولات السعودي دوليًا، وتوسيع مجالات التعاون وتبادل المعرفة والخبرات.","وركزت الزيارة على عدد من المحاور المرتبطة بتطوير قطاع المقاولات، شملت بناء القدرات القيادية، واستكشاف التقنيات والممارسات المتقدمة في صناعة البناء، وتعزيز التعاون في مجالات التشغيل والخدمات البيئية والاستدامة والتحول الرقمي، إلى جانب بناء قنوات تواصل مباشرة بين شركات المقاولات السعودية ونظيراتها السنغافورية، بما يسهم في إيجاد فرص وشراكات جديدة تخدم القطاع.","وفي مستهل الزيارة، عقد الوفد اجتماعًا مع NUS Business Schoolفي الجامعة الوطنية بسنغافورة، جرى خلاله بحث فرص التعاون في تطوير القيادات بقطاع المقاولات، وإمكانية تطوير برنامج تنفيذي مخصص لقيادات شركات المقاولات في المملكة، يتناول مجالات القيادة والإستراتيجية والإنتاجية والاستدامة والتحول الرقمي، بما يعزز جاهزية القطاع لمواكبة المتغيرات المتسارعة في صناعة البناء.","وضمن برنامج الزيارة، التقى وفد الهيئة بسعادة سفير خادم الحرمين الشريفين لدى جمهورية سنغافورة، محمد بن عبدالله الغامدي، في مقر سفارة المملكة، حيث استعرض اللقاء فرص تعزيز العلاقات مع الجهات والشركات السنغافورية في مجالات المقاولات والتقنيات والخدمات المرتبطة بالقطاع، وبحث سبل دعم بناء قنوات تعاون مستدامة بين الشركات والخبرات في البلدين.","كما عقدت الهيئة اللقاء السعودي–السنغافوري لمقاولي النظافة، بمشاركة عدد من الشركات والخبرات من المملكة وسنغافورة، حيث ناقش المشاركون فرص الاستثمار والتشغيل والخدمات البيئية، وبحثوا سبل بناء قنوات تواصل مباشرة بين الشركات من الجانبين وتحويل العلاقات إلى فرص تعاون وشراكات عملية.","وشهدت الزيارة توقيع مذكرة تفاهم بين الهيئة السعودية للمقاولين وشركة Meinhardt Singapore، ومثّل الهيئة في توقيع المذكرة عضو مجلس الإدارة سعود بن وردي العقيدي.","وتؤسس المذكرة إطارًا للتعاون وتبادل المعرفة والخبرات واستكشاف مجالات العمل المشتركة ذات الصلة بقطاع المقاولات، ضمن توجه الهيئة لتوسيع شبكة شراكات القطاع دوليًا وربط السوق السعودي بالشركات والخبرات العالمية.","كما بحث الاجتماع مسارات التعاون التي من شأنها دعم تطوير قطاع المقاولات وتعزيز تبادل المعرفة والخبرات بين المملكة وسنغافورة."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/spas7er','https://sabq.org/article/spas7er','','https://sabq.org/article/spas7er','صحيفة سبق','المدينة المنورة','2026-09-05T09:26:00.000Z','2026-09-05T12:26:00.000Z','2026-09-05T15:32:05.848Z','https://media.sabq.org/news/2026/09/7d57c5a4-3a7e-496b-8eab-437237a4913b/w1600.webp','/api/media/1dee3bf7-03d3-48c1-bb74-1c996283193a','/api/media/1dee3bf7-03d3-48c1-bb74-1c996283193a?variant=thumbnail','"هيئة المقاولين" تعزز الشراكات الدولية في سنغافورة وتفتح آفاقًا جديدة للقطاع السعودي',1600,1066,'valid','published','archived','valid',86,'1a724edf3a120abf94ae2279f682ae01ff1c482e6d7e5c7664ef13c49f2c760f','cdbc6d924487ae864a42b6e9c485ec05cb0826df38fb9eef212d0103d5899137','محدّث','2026-09-05T15:32:05.848Z','2026-10-07T21:00:41.950Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس الإدارة محمد بن","مجلس الإدارة محمد بن عبدالعزيز","خادم الحرمين الشريفين لدى جمهورية","هيئة المقاولين تعزز الشراكات الدولية","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["رئيس مجلس الإدارة محمد بن","مجلس الإدارة محمد بن عبدالعزيز","خادم الحرمين الشريفين لدى جمهورية","هيئة المقاولين تعزز الشراكات الدولية","التعليم والتدريب","الاقتصاد والأسواق"]','classified','','[{"category":"التقنية","score":3},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T21:00:41.950Z',200,22,0,'source_article_available','',NULL,NULL,'body:5bcbda8e9d80c433b434b290de0d0197b0d1c8d9a9366072138b66395593ea7d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('947ad87a-e402-4b53-adfe-7ebb6c1f197c','news-947ad87a-e402-4b53-adfe-7ebb6c1f197c','تحذير وزاري: بريطانيا ستواجه «ميزانية صعبة» الشهر المقبل بسبب حرب الشرق الأوسط','تحذير وزاري بريطانيا ستواجه ميزانيه صعبه الشهر المقبل بسبب حرب الشرق الاوسط','حذر وزير الخزانة البريطاني جون هيلي ، اليوم السبت، من أن بلاده ستواجه ميزانية صعبة الشهر المقبل بسبب حرب الشرق الأوسط . وفي مقابلة مع صحيفة فايننشال تايمز ، قال جون هيلي إن «الصراع في إيران سيؤثر على الأرجح بشكل كبير على ميزانيته الأولى المقرر تقديمها في 28 أكتوبر المقبل».','["حذر وزير الخزانة البريطاني جون هيلي ، اليوم السبت، من أن بلاده ستواجه ميزانية صعبة الشهر المقبل بسبب حرب الشرق الأوسط .","وفي مقابلة مع صحيفة فايننشال تايمز ، قال جون هيلي إن «الصراع في إيران سيؤثر على الأرجح بشكل كبير على ميزانيته الأولى المقرر تقديمها في 28 أكتوبر المقبل».","وصرح «هيلي»، الذي خلف راشيل ريفز بعد تولي آندي بورنهام رئاسة الوزراء في يوليو الماضي، للصحيفة بأنه «يريد ضمان وجود \"احتياطي\" قوي لدى البلاد لمواجهة حالة عدم اليقين وسط تزايد عدم الاستقرار العالمي».","ومع ذلك، توقع خبراء اقتصاديون أن «هيلي» سيحتاج إلى رفع الضرائب أو تطبيق إجراءات تقشفية كبيرة لحماية هامش الإنفاق البالغ 24 مليار جنيه إسترليني الذي كان متاحًا لريفز بعد بيانها في مارس الماضي.","وقال «هيلي»: ما يحدث في الشرق الأوسط يؤثر سلبًا على التضخم والنمو وتكاليف الاقتراض. إنه جزء من عالم أكثر خطورة وعدم يقين، وهو أحد التحديات التي نواجهها في هذا البلد، وعلينا مواجهتها أيضًا مع الدول الأخرى.","وذكرت الصحيفة أنه«هيلي» يعتزم الالتزام بتعهدات حزب العمال في برنامجه الانتخابي لعام 2024 بعدم رفع الضرائب على \"العاملين\"، مثل ضريبة الدخل ومساهمات التأمين الوطني وضريبة القيمة المضافة، كما أنه من غير المتوقع رفع معدل ضريبة الشركات.","وتتعرض المالية العامة لضغوط من ارتفاع عوائد السندات العالمية، التي بلغت أعلى مستوى لها في 18 عامًا في وقت سابق من هذا الأسبوع. وتؤثر عوائد السندات بشكل كبير على خطط الإنفاق الحكومي، إذ يؤدي ارتفاعها إلى زيادة تكاليف الاقتراض."]','الاقتصاد','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/271591ehf','https://ajel.sa/misc/271591ehf','https://ajel.sa/misc/271591ehf','https://ajel.sa/misc/271591ehf','فريق التحرير','','2026-09-05T09:25:00.000Z','Wed, 07 Oct 2026 21:02:17 GMT','2026-09-05T15:43:31.962Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000202066-crop-i22pLVAP.jpg','/api/media/947ad87a-e402-4b53-adfe-7ebb6c1f197c','/api/media/947ad87a-e402-4b53-adfe-7ebb6c1f197c?variant=thumbnail','تحذير وزاري: بريطانيا ستواجه «ميزانية صعبة» الشهر المقبل بسبب حرب الشرق الأوسط',1200,675,'valid','published','archived','valid',57,'ebf58c0939eb1fd36733eaca597fd0e5d8698647ad6d404133dfdf656f581be4','e23ceba0ca029eeea40a6ae6b7d888dd97cc6e30784ae45874d6a46739113f9c','محدّث','2026-09-05T15:43:31.962Z','2026-10-07T21:02:18.739Z','','',0,0,'international','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","وزير الخزانة البريطاني جون هيلي","وزارة الخزانة بالالتزام بهذا الهدف","الاقتصاد والأسواق","إيران","الشرق الأوسط"]','["وزير الخزانة البريطاني جون هيلي","وزارة الخزانة بالالتزام بهذا الهدف","الاقتصاد والأسواق","الشرق الأوسط"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T21:02:18.739Z',200,30,0,'source_article_available','',NULL,NULL,'body:5a03397e6f66a06e3f0da65d9c8482c72b131a2c50539cf079b8783788d235e8','Wed, 07 Oct 2026 21:02:17 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cf3a9805-2c6c-4303-a9bc-357d5d5fa4eb','news-cf3a9805-2c6c-4303-a9bc-357d5d5fa4eb','القوة الخاصة لأمن الطرق بالشرقية تضبط مقيماً سورياً يبيع حطباً محلياً بصورة مخالفة','القوه الخاصه لامن الطرق بالشرقيه تضبط مقيما سوريا يبيع حطبا محليا بصوره مخالفه','ضبطت القوة الخاصة لأمن الطرق بالمنطقة الشرقية مقيماً من الجنسية السورية بحوزته حطب محلي معروض للبيع، في مخالفة صريحة لنظام البيئة، وتم تسليم المضبوطات إلى الجهة المختصة.','["ويأتي هذا الضبط في إطار متابعة وزارة الداخلية لنشاطات تسويق الفحم والحطب المحليين داخل المدن والمحافظات وعلى الطرق الرابطة بين المناطق، بما في ذلك ما يُروَّج له بصورة غير نظامية عبر مختلف المنصات الرقمية.","وحثّ الأمن العام المواطنين والمقيمين على الإبلاغ عن أي حالات تمثّل اعتداءً على البيئة أو الحياة الفطرية، عبر الاتصال بالرقم (911) في مناطق مكة المكرمة والمدينة المنورة والرياض والمنطقة الشرقية، والرقمين (996) و(999) في بقية مناطق المملكة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wv9hnzz','https://sabq.org/article/wv9hnzz','','https://sabq.org/article/wv9hnzz','صحيفة سبق','الرياض','2026-09-05T09:36:00.000Z','2026-09-05T12:36:00.000Z','2026-09-05T15:43:42.156Z','https://media.sabq.org/news/2026/09/f85012a2-8339-4301-a29c-005555a659b1/w1378.webp','/api/media/cf3a9805-2c6c-4303-a9bc-357d5d5fa4eb','/api/media/cf3a9805-2c6c-4303-a9bc-357d5d5fa4eb?variant=thumbnail','القوة الخاصة لأمن الطرق بالشرقية تضبط مقيماً سورياً يبيع حطباً محلياً بصورة مخالفة',1378,774,'valid','published','archived','valid',50,'3b756f3d68b481dcdf16731283390b791f16b4d84a821075face969279a507b1','658c30c24d558570c91d27db83da88d53ad0a85e42129d9f3e5d0f5c9343c3b8','محدّث','2026-09-05T15:43:42.156Z','2026-10-07T21:02:15.535Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية لنشاطات تسويق الفحم","التقنية والتحول الرقمي","مكة","سوريا","الرياض","المدينة المنورة"]','["وزارة الداخلية لنشاطات تسويق الفحم","التقنية والتحول الرقمي","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"التقنية","score":3.5},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T21:02:15.535Z',200,29,0,'source_article_available','',NULL,NULL,'body:e7e4254f083691aa58485bf5c9ceb2481ecdacb61d44fc4b5618a0be1ccd1185','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('db2bb0a1-b684-4f0e-b748-28f938eab14b','news-db2bb0a1-b684-4f0e-b748-28f938eab14b','بيئي / أفعى الحقل القرناء.. تكيف فريد مع البيئات الصحراوية في شمال المملكة','بيئي افعي الحقل القرناء تكيف فريد مع البيئات الصحراويه في شمال المملكه','عرعر 23 ربيع الأول 1448 هـ الموافق 05 سبتمبر 2026 م واس تُعد أفعى الحقل القرناء (Pseudocerastes fieldi)، المعروفة أيضًا باسم "أفعى فيلد المقرنة" و"الأفعى القرناء الكاذبة"، من أنواع الزواحف التي تعيش في البيئات الصحراوية بالشرق الأوسط، وسُجل وجودها في شمال المملكة العربية السعودية، حيث تتكيف مع البيئات الجافة والصخرية والحصوية.','["وتتميز الأفعى برأس عريض مثلث الشكل، واضح الانفصال عن العنق، وخطم قصير، فيما تبرز فوق عينيها نتوءات شبيهة بالقرون تتكون من مجموعة من الحراشف الصغيرة المتراكبة، وهي من أبرز الصفات الشكلية المميزة لهذا النوع، إضافة إلى النهاية الداكنة المائلة إلى السواد في طرف الذيل.","وتساعد ألوان جسمها، التي تتدرج بين البني والرمادي ودرجات قريبة من ألوان التربة والصخور، على التمويه والاندماج مع البيئة المحيطة، كما توجد في عدد من الموائل الجافة، ومنها الصحاري الصخرية والجيرية والبازلتية والأودية والسهوب، وتميل إلى البيئات ذات الأسطح الصلبة والصخرية أكثر من الكثبان الرملية المفتوحة.","وأوضح عضو جمعية أمان البيئية والمهتم برصد وتوثيق الحياة الفطرية عدنان خليفة أن أفعى الحقل القرناء من الزواحف الصحراوية التي تتمتع بقدرة كبيرة على التكيف مع طبيعة موائلها، مبينًا أن ألوان جسمها ونقوشه تساعدها على الاندماج مع الصخور والتربة، ما يجعل ملاحظتها في بيئتها الطبيعية أمرًا يحتاج إلى دقة وانتباه.","وقال: \"من أبرز السمات التي تميز أفعى الحقل القرناء النتوءات الموجودة فوق العينين، التي تبدو على هيئة قرون صغيرة، إلى جانب شكل الرأس العريض، ونهاية الذيل الداكنة، فضلًا عن لون الجسم المتوافق مع طبيعة البيئة المحيطة، وهي خصائص تمنحها قدرة عالية على التخفي والتمويه\".","وبيّن خليفة أن الأفعى تتغذى على عدد من الكائنات الصغيرة، من بينها القوارض والسحالي والطيور، وقد تُظهر سلوكًا افتراسيًا نشطًا عند توافر الفرائس، مشيرًا إلى أن وجودها يمثل جزءًا من التنوع الأحيائي في البيئات الصحراوية، ويسهم في التوازن الطبيعي ضمن السلسلة الغذائية.","وحذّر من الاقتراب منها أو محاصرتها أو محاولة الإمساك بها عند مشاهدتها، مؤكدًا ضرورة ترك مسافة آمنة وعدم استفزازها، والابتعاد عن موقعها بهدوء، حفاظًا على سلامة الأشخاص والكائن الفطري في الوقت نفسه.","وأكد خليفة أهمية المحافظة على الزواحف والكائنات الفطرية في موائلها الطبيعية، وعدم العبث بها، إلى جانب تعزيز الوعي بالتنوع الأحيائي ودور مختلف الكائنات في المحافظة على التوازن البيئي. // انتهى // 17:35 ت مـ 0054"]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2669448?type=news&uuid=N2669448','https://spa.gov.sa/ar/N2669448?type=news&uuid=N2669448','N2669448','N2669448','','الحدود الشمالية','2026-09-05T11:35:00.000Z','2026-09-05T08:35:00.000Z','2026-09-05T20:31:20.509Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10733248.jpg','/api/media/db2bb0a1-b684-4f0e-b748-28f938eab14b','/api/media/db2bb0a1-b684-4f0e-b748-28f938eab14b?variant=thumbnail','بيئي / أفعى الحقل القرناء.. تكيف فريد مع البيئات الصحراوية في شمال المملكة',1600,1066,'valid','published','archived','valid',49,'64f7eea9ecc316829b5558dc51eac17e45d88ffbd70b41df8b101f22c1289dc5','6a58bdfb50431f93d802a3cc50dd8a35932cdb3ffa2b977149fb2e6de8357fa4','محدّث','2026-09-05T15:43:54.382Z','2026-10-07T21:07:52.094Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة قرون صغيرة إلى جانب","الشرق الأوسط"]','["هيئة قرون صغيرة إلى جانب","الشرق الأوسط"]','needs_review','below_category_threshold','[{"category":"المناطق","score":4},{"category":"المجتمع","score":1.5},{"category":"السياسة","score":0}]','Active','2026-10-07T21:07:52.094Z',200,31,0,'source_article_available','',NULL,NULL,'body:88b05733197b568e2c88b9e96311f04a7b32929b94c1216120563a79a9baf4d1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b638f0ca-489c-4041-a5e4-eec8e08e5947','news-b638f0ca-489c-4041-a5e4-eec8e08e5947','"بلدي" تستعرض مستقبل المدن الذكية وتوسع شراكاتها التقنية خلال LEAP 2026','بلدي تستعرض مستقبل المدن الذكيه وتوسع شراكاتها التقنيه خلال leap 2026','وعكست مشاركة "بلدي" في LEAP 2026 توجهها نحو الانتقال من رقمنة الخدمات إلى بناء منظومة متكاملة لمدن أكثر ذكاءً واستباقية وترابطًا، من خلال توظيف الذكاء الاصطناعي والبيانات والتقنيات المتقدمة، إلى جانب الشراكات الاستراتيجية، بما يسهم في رفع كفاءة المدن، ودعم اتخاذ القرار، وتحسين جودة الخدمات، وتطوير تجارب رقمية أكثر تكاملًا ترتبط باحتياجات المستفيدين…','["شاركت \"بلدي\"، إحدى مبادرات NHC Innovation، في مؤتمرLEAP 2026 ، حيث استعرضت مجموعة من التقنيات والحلول الرقمية التي تسهم في تطوير مدن أكثر ذكاءً وكفاءة، من خلال توظيف الذكاء الاصطناعي والبيانات والتقنيات المتقدمة في تحسين الخدمات البلدية، ورفع كفاءة التشغيل، وتعزيز تجربة المستفيد والمستثمر.","وشملت أبرز التقنيات التي استعرضها \"مركز القيادة والتحكم\"، الذي يقدم نموذجًا تشغيليًا موحدًا للمدينة يعتمد على البيانات والذكاء التشغيلي لدعم اتخاذ القرار ومتابعة أداء الخدمات، إلى جانب \"عدسة بلدي\" التي توظف الذكاء الاصطناعي والرؤية الحاسوبية في رصد وتحليل المشهد الحضري ورفع كفاءة أعمال التفتيش والرقابة، بالإضافة إلى \"مركز المستثمر الذكي\" عبر منصة فرص، الذي يقدم رحلة رقمية متكاملة لاستكشاف وإدارة الفرص الاستثمارية الحكومية، بدءًا من طرح الفرص والتقديم عليها وصولًا إلى الترسية وإدارة العقود والمدفوعات، مدعومة بالذكاء الاصطناعي ومحركات التوصية ولوحات البيانات التي تساهم في تحديد المنافس الانسب للفرصة الاستثمارية.","كما شهدت المشاركة إطلاق خدمة \"تيفو\" عبر تطبيق بلدي+، التي تقدم تجربة رقمية تفاعلية لجماهير كرة القدم، وتتيح للمستخدمين التعبير عن انتمائهم وتشجيع فرقهم من خلال تجربة مرتبطة بالموقع، بما يوسع دور \"بلدي+\" من خدمات الخرائط والتنقل إلى تقديم تجارب محلية رقمية ترتبط باهتمامات المستخدمين والفعاليات والأنشطة داخل المدن.","وبالتزامن مع مشاركتها، عززت \"بلدي\" شراكاتها الاستراتيجية عبر توقيع عدد من مذكرات التفاهم الهادفة إلى توسيع نطاق الحلول الرقمية وتعزيز التكامل مع مختلف القطاعات؛ حيث وقعت مذكرة تفاهم مع شركة القدية للاستثمار لدعم حلول المدن الذكية، كما تعاونت مع TAWAL لتطوير نموذج موحد لإدارة رخص أبراج الاتصالات، فيما شملت الشراكات شركة ATT لاستكشاف تطوير منصة وطنية للأصول الواقعية ورقمنة وترميز الأصول العقارية، وامتدت إلى شركة CHOCO العربية المحدودة لإطلاق منصة وطنية لتتبع الأغذية وسلاسل الإمداد، إضافة إلى عمران تك للتعاون في تشغيل وإدارة الخدمات البلدية وتطوير إجراءات المسار السريع وخدمات المستفيدين."]','الذكاء الاصطناعي','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/3dtkpzf','https://sabq.org/article/3dtkpzf','','https://sabq.org/article/3dtkpzf','صحيفة سبق','','2026-09-05T09:49:00.000Z','2026-09-05T12:50:00.000Z','2026-09-05T15:56:06.201Z','https://media.sabq.org/news/2026/09/07231b3e-4078-4627-a08e-69d045bd0aad/w1600.webp','/api/media/b638f0ca-489c-4041-a5e4-eec8e08e5947','/api/media/b638f0ca-489c-4041-a5e4-eec8e08e5947?variant=thumbnail','"بلدي" تستعرض مستقبل المدن الذكية وتوسع شراكاتها التقنية خلال LEAP 2026',1600,1067,'valid','published','archived','valid',55,'605d7cb8c0b8df9e6ba523c49023204a2a98371b47e490735e105c979c8c8adf','98db844563905274671c5540ff4cae311923ab9632d10ae2384aa22011f8f4db','محدّث','2026-09-05T15:56:06.201Z','2026-10-07T21:10:37.448Z','','',0,0,'international','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة القدية للاستثمار لدعم حلول","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["شركة القدية للاستثمار لدعم حلول","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"المناطق","score":4},{"category":"الرياضة","score":4},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:10:37.448Z',200,26,0,'source_article_available','',NULL,NULL,'body:0fc4b10d4d0bf8d51846453435beb67ee524f93a7a8430a183cb6a2c29195250','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fef0367a-826b-4dd0-b05b-5d0116d04ecc','news-fef0367a-826b-4dd0-b05b-5d0116d04ecc','هل يرهقك الجلوس الطويل أكثر مما تتوقع؟ "الصحة" تحذر من 3 مخاطر صحية','هل يرهقك الجلوس الطويل اكثر مما تتوقع الصحه تحذر من 3 مخاطر صحيه','حذّرت وزارة الصحة عبر منصتها التوعوية «عش بصحة» من المخاطر الصحية الناجمة عن الجلوس لفترات طويلة خلال ساعات العمل، مشيرةً إلى أن الجلوس المستمر يُرهق الجسم أكثر مما يتوقعه كثيرون.','["وأوضحت الوزارة أن الجلوس لفترات مطوّلة، لا سيما بوضعيات غير مناسبة، يُفضي إلى جملة من المشكلات الصحية، أبرزها: تيبّس العضلات وإجهادها، وبطء تدفق الدم في الساقين، فضلاً عن ارتفاع خطر الإصابة بأمراض القلب والسكري.","ودعت الوزارة موظفي القطاعين الحكومي والخاص إلى تخصيص فترات منتظمة للحركة وممارسة نشاط بدني خفيف بين ساعات العمل، مؤكدةً أن ذلك يُساعد على تنشيط الدورة الدموية، والتخفيف من تيبّس العضلات، والحفاظ على مرونة الجسم وحيويته."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/sbg3c5e','https://sabq.org/article/sbg3c5e','','https://sabq.org/article/sbg3c5e','صحيفة سبق','','2026-09-05T09:46:00.000Z','2026-09-05T12:46:00.000Z','2026-09-05T15:56:08.144Z','https://media.sabq.org/news/2026/09/23c0e1c8-32a9-441b-90ad-3fedc474ed95/w1080.webp','/api/media/fef0367a-826b-4dd0-b05b-5d0116d04ecc','/api/media/fef0367a-826b-4dd0-b05b-5d0116d04ecc?variant=thumbnail',' هل يرهقك الجلوس الطويل أكثر مما تتوقع؟ "الصحة" تحذر من 3 مخاطر صحية',1080,831,'valid','published','archived','valid',41,'78ea0fcb3c03c19e8436615071ab8e0f06355f5139d78805aae882260d0bdb53','16974279e6dca1ca673dafef5b2ec8aac7f18ac3f71437168a8b38ce4f230c9b','محدّث','2026-09-05T15:56:08.144Z','2026-10-07T21:10:37.467Z','','',0,0,'international','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الصحة عبر منصتها التوعوية","الصحة العامة"]','["وزارة الصحة عبر منصتها التوعوية","الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:10:37.467Z',200,25,0,'source_article_available','',NULL,NULL,'body:bec47ba9cfe6fb380de73d69cc4aa5758c707b2d7535cec53be4a471559a5b64','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dc073c23-5d16-46b8-936b-348e39575e79','news-dc073c23-5d16-46b8-936b-348e39575e79','أمير الرياض يُعزّي في وفاة الشيخ سعد آل فريان وعمة أمير الفوج الخامس','امير الرياض يعزي في وفاه الشيخ سعد ال فريان وعمه امير الفوج الخامس','كما قدّم سموه تعازيه ومواساته لأمير الفوج الخامس في وزارة الحرس الوطني المقدم جامع بن عبدالعزيز بن جامع في وفاة عمته -رحمها الله-، داعياً الله أن يرحم الفقيدة ويسكنها فسيح جناته، ويلهم ذويها الصبر والسلوان.','["قدّم صاحب السمو الملكي الأمير فيصل بن بندر بن عبدالعزيز أمير منطقة الرياض، تعازيه ومواساته لذوي الشيخ سعد بن محمد بن سعد آل فريان في وفاته -رحمه الله-، سائلاً الله العلي القدير أن يرحم الفقيد ويسكنه فسيح جناته، ويلهم ذويه الصبر والسلوان.","وأعرب ذوو الفقيد عن شكرهم وتقديرهم لسمو أمير منطقة الرياض على تعازيه ومواساته.","وأعرب ابن جامع عن شكره وتقديره لسمو أمير منطقة الرياض على هذه المواساة الكريمة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/mr923bw','https://sabq.org/article/mr923bw','','https://sabq.org/article/mr923bw','صحيفة سبق','الرياض','2026-09-05T09:56:00.000Z','2026-09-05T12:56:00.000Z','2026-09-05T16:05:05.429Z','','','','أمير الرياض يُعزّي في وفاة الشيخ سعد آل فريان وعمة أمير الفوج الخامس',NULL,NULL,'all_candidates_failed (og:fetch failed | structured:fetch failed | structured:fetch failed | structured:fetch failed)','published','archived','valid',44,'edd019d722676728c01c518b6ca43caa6e2d883eebdfa4a469faba7cad7eb9e9','0157bead178c963d13053b40fa048990bab47371f9b95cd4102dcb49b7273a4a','محدّث','2026-09-05T16:05:05.429Z','2026-10-07T21:19:44.683Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الحرس الوطني المقدم جامع","الرياض"]','["وزارة الحرس الوطني المقدم جامع"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":3},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:19:44.683Z',200,25,0,'source_article_available','',NULL,NULL,'body:290e4934f092464e1593bb142f4e54bd0050228bf7b3e576c91ca28363430880','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3e64a976-51d3-4e27-96dc-7a4a2ded3c1d','news-3e64a976-51d3-4e27-96dc-7a4a2ded3c1d','91,500 كيلومتر مربع تحتضن ثراءً طبيعيًا فريدًا في محمية الإمام تركي','91 500 كيلومتر مربع تحتضن ثراء طبيعيا فريدا في محميه الامام تركي','تمتد محمية الإمام تركي بن عبدالله الملكية شمال شرق المملكة العربية السعودية على مساحة 91,500 كيلومتر مربع، لتحتل المرتبة الثانية بين أكبر المحميات الملكية في المملكة، وتحتضن نطاقاً جغرافياً واسعاً تتنوع فيه التضاريس والموائل الطبيعية، من الكثبان الرملية والسهول والجبال والهضاب والسهوب، إلى الأودية والفياض، بما يعزز ثراءها النباتي وتنوع حياتها الفطرية.','["ويُشكّل هذا التنوع التضاريسي أساساً لتعدد الموائل داخل المحمية؛ إذ تستحوذ الكثبان الرملية على المساحة الأكبر، وتحتضن أنواعاً من النباتات الصحراوية، أبرزها: الغضا والأرطى والعرفج والعوسج.","وتوفر الأودية والمجاري المائية الموسمية بيئات ملائمة لنمو النباتات الخشبية، فيما تمثل الفياض منخفضات طبيعية تتجمع فيها مياه الأمطار والجريان السطحي خلال المواسم الرطبة، فتُسهم في إثراء الغطاء النباتي.","ويمتد الثراء الطبيعي للمحمية إلى غطائها النباتي الذي يضم مئات الأنواع المنتمية إلى عشرات العوائل النباتية، من أبرزها: الطلح والسدر والأرطى والغضا والعرفج والعوسج، في تنوع يرتبط بتباين التضاريس واختلاف الظروف البيئية والمناخية ضمن نطاقها الواسع.","وتوفر هذه البيئات المتباينة موائل متعددة للحياة الفطرية التي تضم مئات الأنواع من الكائنات، تشمل الثدييات والطيور والزواحف، إلى جانب أنواع متعددة من اللافقاريات، بما يعكس أهمية المحمية في صون التنوع الأحيائي والمحافظة على التوازن الطبيعي للأنظمة البيئية.","وتعمل هيئة تطوير محمية الإمام تركي بن عبدالله الملكية على حماية هذا التنوع وتنميته عبر برامج تستهدف استعادة الموائل الطبيعية، وتنمية الغطاء النباتي، وإعادة توطين الأنواع النباتية والحيوانية، إلى جانب تنظيم الأنشطة البشرية بما يحدّ من تأثيراتها في البيئة ويحافظ على الموارد الطبيعية واستدامتها.","ويأتي تنظيم الرعي ضمن منظومة الإدارة البيئية للمحمية، من خلال تطبيق ضوابط تراعي حالة المراعي وقدرتها الاستيعابية، بما يدعم تجدد الغطاء النباتي ويحدّ من تدهوره، ويحقق التوازن بين الاستفادة من الموارد الطبيعية والمحافظة عليها.","وتبرز المحمية، بما تمتلكه من اتساع جغرافي وتنوع تضاريسي وثراء أحيائي، نموذجاً متقدماً لإدارة النظم الطبيعية على نطاق واسع، تتكامل فيه المكونات البيئية في منظومة واحدة تدعم استعادة الموائل وتعزيز الحياة الفطرية، وتوفر فرصاً واعدة للبحث والرصد البيئي وتنمية السياحة البيئية المستدامة."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/eppkhhh','https://sabq.org/article/eppkhhh','','https://sabq.org/article/eppkhhh','صحيفة سبق','','2026-09-05T10:00:00.000Z','2026-09-05T13:00:00.000Z','2026-09-05T16:05:06.354Z','https://media.sabq.org/news/2026/09/e444c6e4-833c-451f-b97b-35b79792bd11/w1600.webp','/api/media/3e64a976-51d3-4e27-96dc-7a4a2ded3c1d','/api/media/3e64a976-51d3-4e27-96dc-7a4a2ded3c1d?variant=thumbnail','91,500 كيلومتر مربع تحتضن ثراءً طبيعيًا فريدًا في محمية الإمام تركي',1600,1066,'valid','published','archived','valid',48,'85342cf4e6a6b75866c29abe0c41a5364fa1fa8016e74757c188300a5c0b7e65','cfa20fe163e9f4a29906314407785ae37244d9dfef4dbb10dfb22569252ec12f','محدّث','2026-09-05T16:05:06.354Z','2026-10-07T21:19:44.824Z','','',0,0,'saudi_national','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة تطوير محمية الإمام تركي","الطاقة والنفط","الطقس والمناخ","السفر والسياحة"]','["هيئة تطوير محمية الإمام تركي","الطاقة والنفط","الطقس والمناخ","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المجتمع","score":1.5},{"category":"التقنية","score":1.5}]','Active','2026-10-07T21:19:44.824Z',200,29,0,'source_article_available','',NULL,NULL,'body:f292eb5ff071355710c8264d73ef5b51088938354846099c77763551d2e80db4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('297748e8-56e3-4e0c-9a03-abdd01442716','news-297748e8-56e3-4e0c-9a03-abdd01442716','المقاومة الوطنية باليمن تحبط هجومًا حوثيًا بزورقين مفخخين وتحقق تقدمًا في تعز والحديدة','المقاومه الوطنيه باليمن تحبط هجوما حوثيا بزورقين مفخخين وتحقق تقدما في تعز والحديده','وعلى الأرض، أعلنت مصادر عسكرية يمنية، السبت، أن قوات «المقاومة الوطنية» المدعومة بوحدات من «ألوية العمالقة» حققت تقدمًا في محور الجراحي، بالتزامن مع عمليات هجومية باتجاه جبل راس جنوب الحديدة.','["شهد الساحل الغربي لليمن تصعيدًا متزامنًا على أكثر من محور، بعدما أفشلت قوات «المقاومة الوطنية» هجومًا حوثيًا بزورقين مفخخين، بالتوازي مع تقدمات ميدانية للقوات المدعومة من « ألوية العمالقة » في جبهات غرب تعز وجنوب الحديدة .","وأحبطت القوات البحرية التابعة لـ«المقاومة الوطنية في الساحل الغربي» الهجوم البحري قبل وصول الزورقين إلى ساحل الخوخة جنوبي الحديدة، وتمكنت من تدميرهما، فيما كان أحدهما يستهدف الفجرة بالخوخة والآخر ميناء المخا ، وفق الإعلام العسكري .","وتأتي العملية بعد تفجير زورق مفخخ ثالث في اليوم السابق، بينما واصلت ميليشيا الحوثي هجماتها الصاروخية على المناطق والتجمعات السكنية، إذ استهدفت مكتب التربية والتعليم في مديرية حيس جنوب الحديدة بصاروخ باليستي.","وامتدت المواجهات إلى محيط جبل دباس الاستراتيجي في حيس، حيث شهدت المنطقة معارك عنيفة خلال اليومين الماضيين، قالت المصادر إنها أسفرت عن مقتل وإصابة المئات من عناصر الميليشيات.","وفي غرب تعز، تحدث الإعلام العسكري للمقاومة الوطنية عن خسائر فادحة في صفوف الحوثيين على محور البرح ، بالتزامن مع إسقاط مسيرتين مفخختين واغتنام أسلحة.","كما حققت القوات المسلحة تقدمًا في الجبهة الغربية لتعز، واستعادت عددًا من التباب والمواقع، بينما سيطرت في الجبهة الجنوبية للمحافظة على عدد من المواقع والمرتفعات الحاكمة."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/qevjbgtwn','https://ajel.sa/international/qevjbgtwn','https://ajel.sa/international/qevjbgtwn','https://ajel.sa/international/qevjbgtwn','فريق التحرير','','2026-09-05T10:01:00.000Z','Wed, 07 Oct 2026 19:06:04 GMT','2026-09-05T16:14:04.531Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D9%85%D9%82%D8%A7%D9%88%D9%85%D8%A9-%D8%A7%D9%84%D9%88%D8%B7%D9%86%D9%8A%D8%A9-%D9%81%D9%8A-%D8%A7%D9%84%D8%B3%D8%A7%D8%AD%D9%84-%D8%A7%D9%84%D8%BA%D8%B1%D8%A8%D9%8A-WTnBxKtW.jpg','/api/media/297748e8-56e3-4e0c-9a03-abdd01442716','/api/media/297748e8-56e3-4e0c-9a03-abdd01442716?variant=thumbnail','المقاومة الوطنية',1200,675,'valid','published','archived','valid',41,'f3b1b73e94b64994ea7eef614190a3fe40aec13b2191eff30c39552324c55108','a3ccf238bcc476c718a0643b7d0397487a88dd8411858afdf1abaa617c1f020f','محدّث','2026-09-05T16:14:04.531Z','2026-10-07T20:25:22.790Z','','',0,0,'gulf_arab','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","التعليم والتدريب","اليمن"]','["السفر والسياحة","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:06:05.724Z',200,24,0,'source_content_changed','',NULL,NULL,'body:e9795e935796131651d362d233e58d64a5b43d81d5a43f72915a56d6fe82b24a','Wed, 07 Oct 2026 19:06:04 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f9b1b4ee-3bdc-4e0b-849d-94b73318ae04','news-f9b1b4ee-3bdc-4e0b-849d-94b73318ae04','تحطم مقاتلة يونانية خلال عرض جوي قرب أثينا','تحطم مقاتله يونانيه خلال عرض جوي قرب اثينا','شهد العرض الجوي السنوي في اليونان حادثا مأساويا، اليوم السبت، إثر تحطم طائرة مقاتلة من طراز "إف-4 فانتوم" تابعة للقوات الجوية اليونانية، أثناء تقديمها استعراضا طيرانيا في قاعدة "تاناغرا" الجوية الواقعة شمالي العاصمة أثينا .','["وأظهرت مشاهد متداولة تصاعد الدخان من حطام الطائرة في قاعدة \"تاناغرا\" الجوية باليونان، وسط صدمة الحاضرين الذين كانوا قد تجمعوا لمتابعة العرض.","وأفادت مصادر محلية وشهود عيان، وفق \" سبوتنيك الروسية\"، بأن الطائرة الحربية ثنائية المقعد سقطت فجأة على بعد بضع مئات من الأمتار من المدرج الذي يتواجد فيه آلاف المشاهدين، مما أدى إلى تصاعد أعمدة كثيفة من الدخان الأسود في سماء المنطقة، وسط حالة من الصدمة بين الحاضرين.","وهرعت فرق الإنقاذ ومروحيات الإطفاء على الفور إلى موقع الحادث للسيطرة على النيران المشتعلة وحطام الطائرة، في حين فرضت السلطات طوقاً أمنياً حول المكان.","إلى ذلك لم يصدر بيان رسمي، حتى الآن، يوضح الأسباب التقنية وراء سقوط المقاتلة، أو الكشف عن المصير النهائي لطاقم الطائرة المكون من طيارين اثنين."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/q3jpd4l1l','https://ajel.sa/international/q3jpd4l1l','https://ajel.sa/international/q3jpd4l1l','https://ajel.sa/international/q3jpd4l1l','فريق التحرير','','2026-09-05T10:01:00.000Z','Wed, 07 Oct 2026 19:06:02 GMT','2026-09-05T16:14:05.840Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-Lf6Vg2hU.jpg','/api/media/f9b1b4ee-3bdc-4e0b-849d-94b73318ae04','/api/media/f9b1b4ee-3bdc-4e0b-849d-94b73318ae04?variant=thumbnail','تحطم مقاتلة يونانية خلال عرض جوي قرب أثينا',1200,675,'valid','published','archived','valid',41,'fe2dc906c36e617442346710874ec55aa77f19b153c7c9c9f9408956fd22734a','6620b62fad04ec5cd7afafa1b5dca4c8f54025ba5e2b3d54a1d453ef2dcefe12','محدّث','2026-09-05T16:14:05.840Z','2026-10-07T20:25:22.790Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","التقنية والتحول الرقمي"]','["السفر والسياحة","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:06:04.615Z',200,24,0,'source_content_changed','',NULL,NULL,'body:5ade77f70490d6639f3b0c8d44b2c4883952406302b507e37c547606e043367a','Wed, 07 Oct 2026 19:06:02 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a680e8fd-5dd0-4283-9d68-906dc5b6530d','news-a680e8fd-5dd0-4283-9d68-906dc5b6530d','ضيوف خادم الحرمين يزورون مقبرة شهداء أحد ومسجد قباء في المدينة المنورة','ضيوف خادم الحرمين يزورون مقبره شهداء احد ومسجد قباء في المدينه المنوره','زار ضيوف برنامج خادم الحرمين الشريفين للعمرة والزيارة، الذي تشرف عليه وزارة الشؤون الإسلامية والدعوة والإرشاد لعام 1448هـ، مقبرةَ الشهداء وجبل الرماة ومسجد قباء بالمدينة المنورة، وذلك ضمن البرنامج الثقافي المُعدّ لهم خلال فترة إقامتهم.','["واستمع الضيوف إلى شرح مفصّل حول الآداب الشرعية لزيارة المقابر، فضلاً عن استعراض تاريخي شامل لمعركة أحد، تعرّفوا من خلاله على موقع المعركة وأبرز تحولاتها.","وشملت الزيارة مسجد قباء، إذ اطّلع الضيوف على قيمته التاريخية وفضله الديني، وأدّوا فيه ركعتين اقتداءً بسنة النبي محمد صلى الله عليه وسلم.","وأعرب الضيوف عن شكرهم وامتنانهم لخادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود وولي عهده الأمين - حفظهما الله - على ما وفّرته المملكة من خدمات يسّرت لهم زيارة المعالم الإسلامية التاريخية، مؤكدين أن هذه الرعاية تجسّد عناية المملكة واهتمامها بالإسلام والمسلمين، ومُبدين سعادتهم بهذه الزيارة وما تركته في نفوسهم من أثر عميق.","وتضم الدفعة المشاركة في البرنامج 250 معتمراً ومعتمرة، يمثلون 23 دولة من قارة أفريقيا، هي: مصر، والمغرب، وتونس، والجزائر، والسنغال، وغينيا كوناكري، والكاميرون، ونيجيريا، وغانا، والنيجر، وإثيوبيا، ورواندا، وموريتانيا، وساحل العاج، وبوركينا فاسو، وتشاد، وتنزانيا، وجيبوتي، وجنوب أفريقيا، وزامبيا، وناميبيا، وأنغولا، ومالي."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/aokbbxo','https://sabq.org/article/aokbbxo','','https://sabq.org/article/aokbbxo','صحيفة سبق','المدينة المنورة','2026-09-05T10:10:00.000Z','2026-09-05T10:11:00.000Z','2026-09-05T17:49:08.515Z','https://media.sabq.org/news/2026/09/87a6702b-59b2-4752-befe-2d72991f3879/w1600.webp','/api/media/a680e8fd-5dd0-4283-9d68-906dc5b6530d','/api/media/a680e8fd-5dd0-4283-9d68-906dc5b6530d?variant=thumbnail','ضيوف خادم الحرمين يزورون مقبرة شهداء أحد ومسجد قباء في المدينة المنورة',1600,1066,'valid','published','archived','valid',99,'cd76280831a5ce499ecc0f3ab943ea596decdbbfb243e34a1b1179d183bb140a','d5aff908db5e9050270f5f30918ae6dc20b64e70531f634e821da682df2380b3','محدّث','2026-09-05T16:14:06.822Z','2026-10-07T19:05:52.133Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["خادم الحرمين يزورون مقبرة شهداء","وزارة الشؤون الإسلامية والدعوة والإرشاد","المدينة المنورة"]','["خادم الحرمين يزورون مقبرة شهداء","وزارة الشؤون الإسلامية والدعوة والإرشاد","المدينة المنورة"]','classified','','[{"category":"المناطق","score":3},{"category":"الرياضة","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:05:52.133Z',200,25,0,'source_article_available','',NULL,NULL,'body:d6d3afd6656549e4e1bbae3db72d135be8082c8034ba7fa1e072b16187199000','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7d2473e7-0ab6-46bf-82bb-9e8e8fda4796','news-7d2473e7-0ab6-46bf-82bb-9e8e8fda4796','القوات المسلحة اليمنية تحرر مديرية حيس بالكامل من قبضة الحوثيين','القوات المسلحه اليمنيه تحرر مديريه حيس بالكامل من قبضه الحوثيين','أعلنت القوات المسلحة اليمنية والقوات المشتركة، اليوم السبت، تحرير مديرية حيس بمحافظة الحديدة بالكامل من سيطرة المليشيات الحوثية المدعومة من النظام الإيراني، وذلك عقب استعادة المناطق الريفية التابعة للمديرية وتأمينها.','["وأوضح مصدر عسكري لوكالة الأنباء اليمنية «سبأ»، أن مدينة حيس كانت محررة في وقت سابق، غير أن أجزاء من أريافها ظلت تحت سيطرة مليشيا الحوثي الإرهابية، قبل أن تتمكن القوات اليوم من تحرير كافة المناطق الريفية وتأمينها بالكامل.","وأشار المصدر إلى أن القوات المسلحة استعادت المناطق الواقعة في مفرق البرح، وتوغلت باتجاه مواقع المليشيا، وسط تراجع عناصرها وفرارهم، مع سقوط عشرات القتلى والجرحى في صفوفهم.","وأكد المصدر أن القوات تواصل تأمين المناطق المحررة وتثبيت مواقعها، في أعقاب استكمال تحرير مديرية حيس بالكامل."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/2sipvbr','https://sabq.org/article/2sipvbr','','https://sabq.org/article/2sipvbr','صحيفة سبق','','2026-09-05T10:16:00.000Z','2026-09-05T13:16:00.000Z','2026-09-05T16:23:06.035Z','https://media.sabq.org/news/2026/09/8d3213a7-31fe-4c3c-81d0-b8c799ed5063/w780.webp','/api/media/7d2473e7-0ab6-46bf-82bb-9e8e8fda4796','/api/media/7d2473e7-0ab6-46bf-82bb-9e8e8fda4796?variant=thumbnail','القوات المسلحة اليمنية تحرر مديرية حيس بالكامل من قبضة الحوثيين',780,405,'valid','published','archived','valid',51,'350ce4d59a2344458cec217071edc35ab4dba7bcc182d24982f43a186811cdff','cd3db07660a4395486286c28c356e0a6bd5cdfc78b831520a4a357b27a66f073','محدّث','2026-09-05T16:23:06.035Z','2026-10-07T20:25:22.790Z','','',0,0,'gulf_arab','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["اليمن","إيران"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:33:23.591Z',200,23,0,'source_article_available','',NULL,NULL,'body:03a2e41747dfcbe31e71f2b2e41d16ca3818ae519e64ebf09135a6136a0246c6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c84772de-e556-4da6-b5e7-2dafba545367','news-c84772de-e556-4da6-b5e7-2dafba545367','الأربعاء.. أمير القصيم يرعى حفل «وقار» لتخريج 92 حافظًا للقرآن في رياض الخبراء','الاربعاء امير القصيم يرعي حفل وقار لتخريج 92 حافظا للقران في رياض الخبراء','ويشهد الحفل تكريم 92 حافظًا وحافظة ومجازًا بالسند المتصل، تتويجًا لمسيرتهم في حفظ كتاب الله وإتقانه، وما بذلوه من جهد ومثابرة طوال فترة التحاقهم ببرامج الجمعية.','["يرعى صاحب السمو الملكي الأمير الدكتور فيصل بن مشعل بن سعود بن عبدالعزيز آل سعود، أمير منطقة القصيم ، حفل «وقار» الذي تقيمه جمعية تحفيظ القرآن الكريم بمحافظة رياض الخبراء ، لتخريج الدفعة الثانية عشرة من حفظة كتاب الله.","ويأتي الحفل، المقرر إقامته يوم الأربعاء 27 ربيع الأول 1448هـ، في إطار اهتمام الجمعية بتشجيع حفظ كتاب الله والعناية بأهله، وإبراز ثمار برامجها القرآنية والتعليمية التي تستهدف مختلف فئات المجتمع.","وتجسد رعاية أمير منطقة القصيم للحفل ما يحظى به كتاب الله وحفظته من عناية واهتمام، ودعم للجهود التي تبذلها جمعيات تحفيظ القرآن الكريم في تعليم القرآن الكريم ونشر رسالته وتعزيز أثره في المجتمع."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/tes1xb7li','https://ajel.sa/local/tes1xb7li','https://ajel.sa/local/tes1xb7li','https://ajel.sa/local/tes1xb7li','ماجد الفريدي','المنطقة الشرقية','2026-09-05T10:13:00.000Z','Wed, 07 Oct 2026 19:42:07 GMT','2026-09-05T16:32:04.817Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/WhatsAppImage2026-09-05at60929PM-crop-YAuU76mX.jpg','/api/media/c84772de-e556-4da6-b5e7-2dafba545367','/api/media/c84772de-e556-4da6-b5e7-2dafba545367?variant=thumbnail','أمير منطقة القصيم',1200,675,'valid','published','archived','valid',41,'ec698a50b5744c9050414c74cb1c4bc71dfb6f3e8eb3b0e5fdfa9a2b19b4a5fc','b7331b50782ed9e4ca3217bf11af0ad9cf0b5b05bc1e03cc7e819a46c0af70f2','محدّث','2026-09-05T16:32:04.817Z','2026-10-07T20:25:22.790Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","القصيم"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:42:09.706Z',200,28,0,'source_content_changed','',NULL,NULL,'body:a481977b7ae70a29399c2ff0c6e4844434d867076e9156b7109ca0b810f27631','Wed, 07 Oct 2026 19:42:07 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e13ff4c6-5f57-4cf7-bb10-0c9fdbc92b1f','news-e13ff4c6-5f57-4cf7-bb10-0c9fdbc92b1f','«The STORM ROOM» بنسختها الثالثة تستهدف 60 موهبة إعلامية قبل انطلاق المنتدى السعودي للإعلام','the storm room بنسختها الثالثه تستهدف 60 موهبه اعلاميه قبل انطلاق المنتدي السعودي للاعلام','وتستهدف المبادرة، قبل انطلاق المنتدى السعودي للإعلام، تنفيذ 2 إلى 3 ورش متخصصة بمشاركة تتراوح بين 45 و60 مشاركاً، وبالشراكة مع عدد من الجهات والخبرات الإعلامية.','["يواصل المنتدى السعودي للإعلام مبادرة «The STORM ROOM» في نسختها الثالثة، الهادفة إلى تمكين المواهب الإعلامية وتحفيزها على تطوير أفكار إبداعية وتحويلها إلى مشاريع إعلامية نوعية، بما يسهم في دعم الجيل الجديد من صناع المحتوى والممارسين والمهتمين بصناعة الإعلام.","وتوفر المبادرة بيئة محفزة تجمع بين المعرفة والعصف الذهني والتطبيق والخبرة، من خلال ورش عمل متخصصة تتيح للمشاركين تطوير أفكار وحلول إعلامية مبتكرة بالتعاون مع شركاء متخصصين، واختيار الأفكار المتميزة والعمل على تطويرها ودراسة إمكانية تبنيها وتنفيذها.","وتستهدف كل ورشة مشاركة ما بين 15 و20 مشاركاً، من المواهب الإعلامية الصاعدة وطلاب الإعلام وصناع المحتوى ورواد صناعة الإعلام، إلى جانب المحترفين والممارسين والمهتمين بالمجال الإعلامي.","وتتضمن الورش جانباً معرفياً وتطبيقياً، إلى جانب جلسة عصف ذهني ختامية يعمل خلالها المشاركون على تطوير أفكار مرتبطة بموضوع الورشة، وصولاً إلى اختيار الفكرة الأكثر أثراً وجدوى، مع بحث مراحل تطويرها وإمكانية تنفيذها بالتعاون مع أصحابها.","وتأتي النسخة الثالثة امتداداً لتجربة ناجحة، إذ تبدأ بجلسة تفاعلية للعصف الذهني ضمن فعاليات المنتدى السعودي للإعلام، بهدف توليد الأفكار الإعلامية الأكثر ابتكاراً ودراسة جدواها تمهيداً لتطويرها وتحويلها إلى مشاريع نوعية.","وكشفت نتائج النسخ السابقة عن أثر لافت للمبادرة؛ إذ تقدّم للمشاركة أكثر من 140 موهبة إعلامية، اختير منها 65 موهبة لخوض التجربة، بمشاركة 12 خبيراً ومتخصصاً أسهموا في نقل المعرفة والخبرات، فيما أسفرت المبادرة عن ولادة 14 فكرة إعلامية، توّجت باختيار 3 أفكار فائزة."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/H3W5xTb','https://sabq.org/article/H3W5xTb','','https://sabq.org/article/H3W5xTb','زيد الخمشي','المنطقة الشرقية','2026-09-05T10:30:00.000Z','2026-09-05T13:30:00.000Z','2026-09-05T16:32:06.350Z','https://media.sabq.org/news/2026/09/4330b7bf-bc79-4f26-9515-173a228f6028/w1600.webp','/api/media/e13ff4c6-5f57-4cf7-bb10-0c9fdbc92b1f','/api/media/e13ff4c6-5f57-4cf7-bb10-0c9fdbc92b1f?variant=thumbnail','«The STORM ROOM» بنسختها الثالثة تستهدف 60 موهبة إعلامية قبل انطلاق المنتدى السعودي للإعلام',1600,1066,'valid','published','archived','valid',41,'5f9f644825009ad260ac5e0867d50558bdd9f6fe3d460a094a91dfd2e1bf20a5','247a391591a2b1956b2affb190c476bccfdf183add41af8ccc661dd577dff4af','محدّث','2026-09-05T16:32:06.350Z','2026-10-07T20:25:22.790Z','','',0,0,'saudi_region','مهم',63,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","التعليم والتدريب","الاقتصاد والأسواق"]','["السفر والسياحة","التعليم والتدريب","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:10.945Z',200,25,0,'source_article_available','',NULL,NULL,'body:d1d62231e390c4c54d0ec3c32caf4b2f19bd824e8600695ec36352bd9108a639','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c1d695d2-e134-4dbe-8344-d1118bed8622','news-c1d695d2-e134-4dbe-8344-d1118bed8622','الأمن البيئي يضبط مخالفَين: رعي إبل في محمية الملك عبدالعزيز وإشعال نار في عسير','الامن البيئي يضبط مخالفين رعي ابل في محميه الملك عبدالعزيز واشعال نار في عسير','ضبطت القوات الخاصة للأمن البيئي مواطناً مخالفاً لنظام البيئة، لارتكابه مخالفة رعي 80 متناً من الإبل في مواقع محظور الرعي فيها داخل محمية الملك عبدالعزيز الملكية، وتم تطبيق الإجراءات النظامية بحقه.','["وأوضحت القوات أن عقوبة رعي الإبل في المناطق المحظورة تبلغ 500 ريال لكل متن.","وفي سياق منفصل، ضبطت القوات الخاصة للأمن البيئي مواطناً آخر مخالفاً لنظام البيئة في منطقة عسير، وذلك لإشعاله النار في غير الأماكن المخصصة لها، مما يُعدّ انتهاكاً صريحاً لتعليمات المحافظة على الغطاء النباتي، وتم تطبيق الإجراءات النظامية بحقه.","وأكدت القوات أن عقوبة إشعال النار في غير الأماكن المخصصة لها في الغابات والمتنزهات الوطنية غرامة تصل إلى 3,000 ريال.","ودعت القوات الخاصة للأمن البيئي المواطنين إلى الإبلاغ عن أي حالات تمثل اعتداءً على البيئة أو الحياة الفطرية عبر الرقم 911 في مناطق مكة المكرمة والمدينة المنورة والرياض والمنطقة الشرقية، والرقمَين 999 و996 في بقية مناطق المملكة، مؤكدةً أن جميع البلاغات تُعامَل بسرية تامة دون أي مسؤولية على المبلّغ."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/ursftpf','https://sabq.org/article/ursftpf','','https://sabq.org/article/ursftpf','صحيفة سبق','الرياض','2026-09-05T10:26:00.000Z','2026-09-05T13:27:00.000Z','2026-09-05T16:32:07.116Z','https://media.sabq.org/news/2026/09/d9641337-2dca-40b1-bf7b-0ba645ea92ed/w1445.webp','/api/media/c1d695d2-e134-4dbe-8344-d1118bed8622','/api/media/c1d695d2-e134-4dbe-8344-d1118bed8622?variant=thumbnail','الأمن البيئي يضبط مخالفَين: رعي إبل في محمية الملك عبدالعزيز وإشعال نار في عسير',1445,741,'valid','published','archived','valid',94,'f6412bbf8d37405246c5c282a9cf90b7fec57ee6e536876f4052e5bc551a7dc0','5ace7891ad0bf3fb58c5beaea2207e1f777b884f55b9ca9ff9572358cc729ca9','محدّث','2026-09-05T16:32:07.116Z','2026-10-07T19:42:06.117Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","مكة","عسير","الرياض","المدينة المنورة"]','["التعليم والتدريب","المدينة المنورة"]','classified','','[{"category":"التقنية","score":9},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T19:42:06.117Z',200,27,0,'source_article_available','',NULL,NULL,'body:c4d12cc9d028fc95a820e1b3f1e324ec35ac569d47be69292582882a0d016c73','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b540f549-8888-4a9a-b16e-5e7e156b88af','news-b540f549-8888-4a9a-b16e-5e7e156b88af','من قلب أبوظبي.. تصوير ذراع درب التبانة بتقنية الأشعة تحت الحمراء','من قلب ابوظبي تصوير ذراع درب التبانه بتقنيه الاشعه تحت الحمراء','نجح مدير مركز الفلك الدولي المهندس محمد شوكت عودة في تصوير أحد أذرع مجرة درب التبانة من سطح أحد الأبراج في وسط مدينة أبوظبي، باستخدام كاميرا فلكية عالية الحساسية ومرشح خاص للأشعة تحت الحمراء، في تجربة فلكية استثنائية تتحدى التلوث الضوئي الذي تفرضه المدن الكبرى.','["وأوضح الفلكي «محمد عودة» أن أهمية الصورة تكمن في المكان الذي التُقطت منه، مشيراً إلى أن التلوث الضوئي يمثل أحد أكبر العوائق أمام رصد الأجرام السماوية الخافتة من داخل المدن، إذ يتشتت الضوء الصادر من الشوارع والمباني في الغلاف الجوي، مكوّناً وهجاً يرفع سطوع خلفية السماء ويحجب النجوم الخافتة التي تبدو واضحة في المواقع المظلمة البعيدة.","وللتغلب على هذا التحدي، اعتمد عودة على كاميرا غير ملونة ذات حساسية مرتفعة في نطاق الأشعة تحت الحمراء، إلى جانب مرشح يسمح بمرور هذه الأشعة دون سواها، مما أتاح تقليل أثر الإضاءة الاصطناعية مع الاحتفاظ بضوء قادم من أعداد كبيرة من النجوم.","غير أنه أشار إلى أن هذه التقنية لا تلغي التلوث الضوئي كلياً، وهو ما يظهر في الجزء السفلي الأيسر من الصورة.","وتغطي الصورة مساحة واسعة من السماء تشمل معظم برج العقرب وأجزاء من برج القوس (الرامي)، وهي المنطقة التي يبدو فيها درب التبانة في أكثف صوره وأسطعها، فيما يقع مركز المجرة في هذا الاتجاه على مسافة تقارب 26 ألف سنة ضوئية من الأرض.","وتتألف الصورة من 180 إطاراً منفصلاً، مدة التعريض لكل منها 10 ثوانٍ، بزمن تعريض إجمالي بلغ 30 دقيقة، جرى بعدها تجميع الإطارات وتكديسها رقمياً.","واستُخدمت في التصوير عدسة واسعة المجال ببعد بؤري مكافئ يساوي 19 ملم، مما أتاح تسجيل مساحة كبيرة من السماء في صورة واحدة تظهر فيها أبرز أبراج أبوظبي، ومنها برج محمد بن راشد الذي يُعدّ أعلى أبراج الإمارة.","وأكد عودة أن هذه التجربة تقدم مثالاً عملياً على دور تقنيات التصوير والمعالجة الرقمية في الرصد الفلكي من المدن، مبيناً أن اختيار النطاق الطيفي المناسب واستخدام حساس عالي الكفاءة وتجميع عدد كبير من الإطارات يمكن أن يفتح نافذة لرصد تفاصيل سماوية يصعب تسجيلها بالتصوير التقليدي وسط إضاءة المدن، دون أن يجعل من سماء المدينة بديلاً عن المواقع الفلكية المظلمة.","وأشار إلى أن الصورة تأتي في سياق اهتمام أبوظبي بالحد من التلوث الضوئي، إذ أطلقت دائرة البلديات والنقل في مايو 2024 «سياسة سماء أبوظبي المظلمة»، التي تتضمن إرشادات لتنظيم الإضاءة الخارجية والحد من الضوء المتسرب إلى السماء، بهدف حماية البيئة ودعم البحث العلمي الفلكي."]','البيئة والمناخ','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/0sb844O','https://sabq.org/article/0sb844O','','https://sabq.org/article/0sb844O','فهد العتيبي','','2026-09-05T10:46:00.000Z','2026-09-05T13:46:00.000Z','2026-09-05T16:50:07.209Z','https://media.sabq.org/news/2026/09/02c781a4-4b3a-41da-920c-d6122c4734cd/w1074.webp','/api/media/b540f549-8888-4a9a-b16e-5e7e156b88af','/api/media/b540f549-8888-4a9a-b16e-5e7e156b88af?variant=thumbnail','من قلب أبوظبي.. تصوير ذراع درب التبانة بتقنية الأشعة تحت الحمراء',1074,1568,'valid','published','archived','valid',60,'a4e09fb78a11694c8a81319bd44a2ef7f3d451f3c7e28b46b18d14048284279c','49e552a55aeda3dc24796209f26c099385485245c4099b1ea18282eb5ac25fc2','محدّث','2026-09-05T16:50:07.209Z','2026-10-07T20:25:22.790Z','','',0,0,'international','عادي',57,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","التقنية والتحول الرقمي","السياسة والعلاقات الدولية"]','["الطاقة والنفط","التقنية والتحول الرقمي","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T19:43:42.305Z',200,24,0,'source_article_available','',NULL,NULL,'body:02f3635fa4bfa59e569af2abe51fe05a73e0876dced1f7d3e729839f634ffa46','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('db042449-4974-4043-8c9f-47fd81b915b8','news-db042449-4974-4043-8c9f-47fd81b915b8','اتحاد المبارزة السعودي يعتمد السلوم نائباً للرئيس للدورة الانتخابية 2024–2028','اتحاد المبارزه السعودي يعتمد السلوم نائبا للرئيس للدوره الانتخابيه 2024 2028','اعتمد مجلس إدارة الاتحاد السعودي للمبارزة برئاسة الدكتور واسم آل حسن، عبدالله السلوم نائباً للرئيس، وأعضاء المجلس الجديد للدورة الانتخابية 2024–2028، خلال اجتماع عُقد في مقر الاتحاد، تضمّن التصديق على محضر اجتماع الجلسة الرابعة، والتصديق على محضر اجتماع مجلس الإدارة بالتمرير.','["واستعرض المجلس خلال الاجتماع التقارير المالية للربع الثاني من عام 2026، وناقش خطة النشاط الخارجي للمنتخبات حتى نهاية العام ذاته، فضلاً عن آخر التحديثات المتعلقة بالتعاون مع مركز التدريب السعودي الأولمبي (SOTC)، وآخر مستجدات نظام دعم النقاط للموسم الداخلي 2026–2027.","كما تناول الاجتماع ما تم تنفيذه من برامج تطوير الحكام الدوليين والواعدين، إلى جانب بحث عدد من المستجدات والأعمال المدرجة على جدول الأعمال، واتخاذ القرارات اللازمة حيالها، في إطار تعزيز العمل المؤسسي ومتابعة الخطط والبرامج التطويرية، ودعم مسيرة رياضة المبارزة السعودية."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/hmgcmxm','https://sabq.org/article/hmgcmxm','','https://sabq.org/article/hmgcmxm','صحيفة سبق','','2026-09-05T10:40:00.000Z','2026-09-05T13:40:00.000Z','2026-09-05T16:50:07.541Z','https://media.sabq.org/news/2026/09/2c21aad9-fb22-4b76-948d-30a0ed9a4f40/w1600.webp','/api/media/db042449-4974-4043-8c9f-47fd81b915b8','/api/media/db042449-4974-4043-8c9f-47fd81b915b8?variant=thumbnail','اتحاد المبارزة السعودي يعتمد السلوم نائباً للرئيس للدورة الانتخابية 2024–2028',1600,899,'valid','published','archived','valid',41,'b0c3bcd2da9f65fdb1e3bff7c65a95dc8321692e79c6eaf766bf66063e710228','1a3b8552f067d6c3bc8bfe73839e99748de6bcaaef32d52363e47b81e939bbf4','محدّث','2026-09-05T16:50:07.541Z','2026-10-07T19:43:42.330Z','','',0,0,'saudi_national','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إدارة الاتحاد السعودي للمبارزة","التعليم والتدريب","الرياضة السعودية"]','["مجلس إدارة الاتحاد السعودي للمبارزة","التعليم والتدريب","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":0},{"category":"الرياضة","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T19:43:42.330Z',200,23,0,'source_article_available','',NULL,NULL,'body:a428e284c3b8e0f02317bc055255c24ab7d7e48684f1e8b9ec6701da030019a9','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3e7a27d8-67a5-4c0f-b70d-02f0ee242eb9','news-3e7a27d8-67a5-4c0f-b70d-02f0ee242eb9','القوات المسلحة اليمنية تحرر مديرية حيس بالكامل من سيطرة المليشيات الحوثية','القوات المسلحه اليمنيه تحرر مديريه حيس بالكامل من سيطره المليشيات الحوثيه','حررت القوات المسلحة والقوات المشتركة، اليوم السبت، مديرية حيس ب محافظة الحديدة بالكامل، من سيطرة المليشيات الحوثية المدعومة من النظام الإيراني، عقب استعادة المناطق الريفية التابعة للمديرية وتأمينها. وأكد المصدر لوكالة الأنباء اليمنية (سبأ)، أن القوات تواصل تأمين المناطق المحررة وتثبيت مواقعها، عقب استكمال تحرير مديرية حيس بالكامل.','["حررت القوات المسلحة والقوات المشتركة، اليوم السبت، مديرية حيس ب محافظة الحديدة بالكامل، من سيطرة المليشيات الحوثية المدعومة من النظام الإيراني، عقب استعادة المناطق الريفية التابعة للمديرية وتأمينها.","ووفق مصدر عسكري لوكالة الأنباء اليمنية (سبأ)، قال إن مدينة حيس كانت محررة، في حين ظلت أجزاء من أرياف المديرية تحت سيطرة مليشيات الحوثي الإرهابية، قبل أن تتمكن القوات اليوم من تحرير كافة المناطق الريفية التابعة للمديرية وتأمينها بالكامل.","وأشار إلى أن القوات المسلحة استعادت المناطق الواقعة في مفرق البرح، وتوغلت باتجاه مواقع مليشيا الحوثي، وسط تراجع وفرار عناصرها، وسقوط عشرات القتلى والجرحى في صفوفها.","وأكد المصدر لوكالة الأنباء اليمنية (سبأ)، أن القوات تواصل تأمين المناطق المحررة وتثبيت مواقعها، عقب استكمال تحرير مديرية حيس بالكامل."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/1d4s9m0v8','https://ajel.sa/international/1d4s9m0v8','https://ajel.sa/international/1d4s9m0v8','https://ajel.sa/international/1d4s9m0v8','فريق التحرير','','2026-09-05T10:51:00.000Z','Wed, 07 Oct 2026 19:51:08 GMT','2026-09-05T17:01:14.337Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-CHs6A3H1.jpg','/api/media/3e7a27d8-67a5-4c0f-b70d-02f0ee242eb9','/api/media/3e7a27d8-67a5-4c0f-b70d-02f0ee242eb9?variant=thumbnail','القوات المسلحة اليمنية تحرر مديرية حيس بالكامل من سيطرة المليشيات الحوثية',1200,675,'valid','published','archived','valid',41,'1bf3688f1bde53db9566c94604c5562128657706b90be3b7f8238eae30df7a06','a687fdc60c8f9fa5229618036c7d3ee1cf3a2829a4ba95e3681a71096463f0f5','محدّث','2026-09-05T17:01:14.337Z','2026-10-07T20:25:22.790Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["اليمن","إيران"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:51:10.502Z',200,40,0,'source_content_changed','',NULL,NULL,'body:7d39fc85314cac59c0b0eaa7fa76a0d6f8b667d581ac1d5998fb4e3b0971661f','Wed, 07 Oct 2026 19:51:08 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('82dafcc5-08bd-4e63-ab87-5afc8f5a2b80','news-82dafcc5-08bd-4e63-ab87-5afc8f5a2b80','بيئي / محمية الإمام تركي بن عبدالله الملكية ترسم تنوعًا بيئيًا ثريًا من الكثبان إلى الأودية والفياض وموائل غنية للحياة الفطرية','بيئي محميه الامام تركي بن عبدالله الملكيه ترسم تنوعا بيئيا ثريا من الكثبان الي الاوديه والفياض وموائل غنيه للحياه الفطريه','رفحاء 23 ربيع الأول 1448 هـ الموافق 05 سبتمبر 2026 م واس تمتد محمية الإمام تركي بن عبدالله الملكية شمال شرق المملكة على مساحة 91,500 كيلومترًا مربعًا، لتكون ثاني أكبر المحميات الملكية في المملكة العربية السعودية، وتحتضن نطاقًا جغرافيًا واسعًا تتنوع فيه التضاريس والموائل الطبيعية، من الكثبان الرملية والسهول والجبال والهضاب والسهوب، إلى الأودية والفياض،…','["ويشكل هذا التنوع التضاريسي أساسًا لتعدد الموائل داخل المحمية؛ إذ تستحوذ الكثبان الرملية على المساحة الأكبر، وتحتضن أنواعًا من النباتات الصحراوية، من أبرزها الغضا والأرطى والعرفج والعوسج، فيما توفر الأودية والمجاري المائية الموسمية بيئات ملائمة لنمو النباتات الخشبية، بينما تمثل الفياض منخفضات طبيعية تتجمع فيها مياه الأمطار والجريان السطحي خلال المواسم الرطبة، فتسهم في إثراء الغطاء النباتي.","ويمتد الثراء الطبيعي للمحمية إلى غطائها النباتي الذي يضم مئات الأنواع المنتمية إلى عشرات العوائل النباتية، من أبرزها الطلح والسدر والأرطى والغضا والعرفج والعوسج، في تنوع يرتبط بتباين التضاريس واختلاف الظروف البيئية والمناخية ضمن نطاقها الواسع.","وتوفر هذه البيئات المتباينة موائل متعددة للحياة الفطرية، التي تضم مئات الأنواع من الكائنات، تشمل الثدييات والطيور والزواحف، إلى جانب أنواع متعددة من اللافقاريات، بما يعكس أهمية المحمية في صون التنوع الأحيائي والمحافظة على التوازن الطبيعي للأنظمة البيئية.","وتعمل هيئة تطوير محمية الإمام تركي بن عبدالله الملكية على حماية هذا التنوع وتنميته من خلال برامج تستهدف استعادة الموائل الطبيعية، وتنمية الغطاء النباتي، وإعادة توطين الأنواع النباتية والحيوانية، إلى جانب تنظيم الأنشطة البشرية بما يحد من تأثيراتها في البيئة ويحافظ على الموارد الطبيعية واستدامتها.","ويأتي تنظيم الرعي ضمن منظومة الإدارة البيئية للمحمية، من خلال تطبيق ضوابط تراعي حالة المراعي وقدرتها الاستيعابية، بما يدعم تجدد الغطاء النباتي، ويحد من تدهوره، ويحقق التوازن بين الاستفادة من الموارد الطبيعية والمحافظة عليها.","وتبرز المحمية، بما تمتلكه من اتساع جغرافي وتنوع تضاريسي وثراء أحيائي، نموذجًا متقدمًا لإدارة النظم الطبيعية على نطاق واسع، حيث تتكامل مكوناتها البيئية في منظومة واحدة تدعم استعادة الموائل، وتعزيز الحياة الفطرية، وتوفير فرص واعدة للبحث والرصد البيئي، وتنمية السياحة البيئية المستدامة. // انتهى // 17:31 ت مـ 0053"]','البيئة والمناخ','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2669447?type=news&uuid=N2669447','https://spa.gov.sa/ar/N2669447?type=news&uuid=N2669447','N2669447','N2669447','','الحدود الشمالية','2026-09-05T11:31:00.000Z','2026-06-24T04:35:00.000Z','2026-09-06T08:16:42.520Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10733514.jpeg','/api/media/82dafcc5-08bd-4e63-ab87-5afc8f5a2b80','/api/media/82dafcc5-08bd-4e63-ab87-5afc8f5a2b80?variant=thumbnail','بيئي / محمية الإمام تركي بن عبدالله الملكية ترسم تنوعًا بيئيًا ثريًا من الكثبان إلى الأودية والفياض وموائل غنية للحياة الفطرية',1600,1066,'valid','published','archived','valid',48,'56696be457b3408099f2f00774b2d7e69a2fd9f71c81474b483fddbea5370eea','5fc08bca44cee22269094030fb4d2de96d147f36e330b6d2946900ae4ce6909a','محدّث','2026-09-05T17:01:34.103Z','2026-10-07T20:25:22.790Z','','',0,0,'saudi_region','مهم',79,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة تطوير محمية الإمام تركي","الطاقة والنفط","الطقس والمناخ","السفر والسياحة"]','["هيئة تطوير محمية الإمام تركي","الطاقة والنفط","الطقس والمناخ","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":3},{"category":"المجتمع","score":1.5},{"category":"السياسة","score":0}]','Active','2026-10-07T19:51:13.655Z',200,39,0,'source_article_available','',NULL,NULL,'body:48e5ea208a60e235a0e82940eaf7009d83a93b43daaf65a28bbbd9098a0a2724','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('60404b30-23b2-438f-9ae7-77826760b9e8','news-60404b30-23b2-438f-9ae7-77826760b9e8','هل يجمّد الماء البارد الدهون داخل الشرايين؟ النمر يكشف الحقيقة ويحذر من حالة نادرة','هل يجمد الماء البارد الدهون داخل الشرايين النمر يكشف الحقيقه ويحذر من حاله نادره','وأوضح الدكتور النمر أن الطعام يُهضم داخل الجهاز الهضمي الذي تبلغ درجة حرارته نحو 37 درجة مئوية، وهي درجة حرارة ثابتة لا تتأثر بشرب الماء البارد، ومن ثَمَّ فإن الدهون لا يمكن أن تتجمد في هذه البيئة الحرارية.','["نفى استشاري أمراض القلب وقسطرة الشرايين الدكتور خالد النمر صحة المعلومة المتداولة على نطاق واسع، والقائلة إن شرب الماء البارد عقب تناول الطعام الدسم يؤدي إلى تجمّد الدهون داخل الشرايين، مؤكداً أن هذه المعلومة خاطئة من أساسها.","وأشار الاستشاري إلى أن شرب الماء البارد آمن في الغالب، غير أنه في حالات نادرة جداً قد يُحفّز مستقبلات البرودة في البلعوم والمريء العصبَ العاشر، مما يُسبب تباطؤاً عابراً في النبض أو هبوطاً في ضغط الدم أو كليهما، وقد يصل عند بعض الأشخاص إلى الإغماء.","وتأتي هذه التوضيحات في إطار جهود المختصين الطبيين لتصحيح المفاهيم الصحية الخاطئة المنتشرة على منصات التواصل الاجتماعي، والتي قد تُسهم في نشر قلق غير مبرر لدى عامة الناس."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/9o5nk7n','https://sabq.org/article/9o5nk7n','','https://sabq.org/article/9o5nk7n','صحيفة سبق','','2026-09-05T11:00:00.000Z','2026-09-05T14:00:00.000Z','2026-09-05T17:13:07.961Z','https://media.sabq.org/news/2026/09/524b47bf-3c03-49b5-bc76-b027ff4c4bd0/w480.webp','/api/media/60404b30-23b2-438f-9ae7-77826760b9e8','/api/media/60404b30-23b2-438f-9ae7-77826760b9e8?variant=thumbnail','هل يجمّد الماء البارد الدهون داخل الشرايين؟ النمر يكشف الحقيقة ويحذر من حالة نادرة',480,288,'valid','published','archived','valid',35,'8a4e5573c0aa65819894f5868a0bde562b0fdaac35292727c384bf53dec94bc3','195178df263e3125e535d77181fcbd67a4acee1faece1e5c13687b29fcae9d1d','محدّث','2026-09-05T17:13:07.961Z','2026-10-07T20:25:22.790Z','','',0,0,'international','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الطقس والمناخ"]','["الصحة العامة","الطقس والمناخ"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:51:28.643Z',200,21,0,'source_article_available','',NULL,NULL,'body:7c4a0904c60f12d19a24b30f0862b37e2cb6f0bc5ceb8f154a07c2cfa7176a38','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('404b16af-91f8-40ff-8602-54c3ad3cb451','news-404b16af-91f8-40ff-8602-54c3ad3cb451','«الزعيم» تخطف لقب القعدان في مهرجان ولي العهد للهجن بالطائف','الزعيم تخطف لقب القعدان في مهرجان ولي العهد للهجن بالطائف','وخطفت المطية «الزعيم» لمالكها السعودي موسى الموسى لقبَ الشوط الثاني وكأسَ مهرجان ولي العهد للهجن لفئة الحقايق «قعدان - مفتوح» بتوقيت 2:52.705 دقيقة، مضيفةً إليه التوقيتَ الأفضل في المنافسة.','["توَّج الأمير فهد بن جلوي بن عبدالعزيز بن مساعد، رئيس مجلس إدارة الاتحاد السعودي للهجن، ملاكَ الهجن الفائزين بكؤوس مهرجان ولي العهد للهجن لفئة «الحقايق» وكأسَي المهرجان للإنتاج السعودي، وذلك على أرض ميدان الطائف التاريخي لسباقات الهجن.","وتُقام منافسات المهرجان في نسخته الثامنة تحت رعاية صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود، ولي العهد رئيس مجلس الوزراء -حفظه الله-، وتستمر حتى 13 سبتمبر الجاري، بتنظيم من الاتحاد السعودي للهجن، وبجوائز مالية تتجاوز 50 مليون ريال.","وذهبت كؤوس الأشواط الأول والثالث والرابع للهجن الإماراتية، إذ حققت المطية «فخر» لمالكها حمد العامري لقبَ الشوط الأول «بكار - مفتوح» بتوقيت 2:57.651 دقيقة، فيما أحرزت المطية «صروح» لمالكها مانع الشامسي لقبَ الشوط الثالث «بكار - عام» بتوقيت 2:57.699 دقيقة، وفازت المطية «جلمود» لمالكها حمد العامري بلقب الشوط الرابع «قعدان - عام» بتوقيت 2:57.673 دقيقة.","وفي شوطَي الإنتاج السعودي، نالت المطية «وعد» لمالكها عقاب الدهاسي لقبَ الشوط الخامس وكأسَ مهرجان ولي العهد «بكار - عام» بتوقيت 2:55.901 دقيقة، فيما أحرزت المطية «منادي» لمالكها نايف السهلي لقبَ الشوط السادس وكأسَ مهرجان ولي العهد «قعدان - عام» بتوقيت 3:00.189 دقيقة.","وأُقيم اليوم 33 شوطاً، بواقع 21 شوطاً عاماً، و6 أشواط مفتوحة، و6 أشواط على كأس مهرجان ولي العهد، وسط حضور جماهيري غفير.","وشهدت الفترة الصباحية تتويجَ الهجن السعودية بالمركز الأول في 17 شوطاً من أصل 21 شوطاً، مقابل 3 أشواط للهجن القطرية وشوط واحد للهجن الإماراتية.","ويعزز المهرجان حضوره الدولي بمشاركة واسعة من ملاك الهجن في العالم العربي والدولي، إذ يهدف إلى تأصيل تراث الهجن وتعزيز الثقافة السعودية، فضلاً عن تحقيقه عوائد اقتصادية كبيرة من خلال فعاليات متنوعة تدعم الموروث التراثي وتُسهم في الحفاظ عليه وتنميته، بما يعكس العمق الحضاري للمملكة العربية السعودية."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/40lj9ml','https://sabq.org/article/40lj9ml','','https://sabq.org/article/40lj9ml','صحيفة سبق','','2026-09-05T11:06:00.000Z','2026-09-05T14:07:00.000Z','2026-09-05T17:13:08.156Z','https://media.sabq.org/news/2026/09/be65bcef-3434-4e56-afa0-508091bb9152/w750.webp','/api/media/404b16af-91f8-40ff-8602-54c3ad3cb451','/api/media/404b16af-91f8-40ff-8602-54c3ad3cb451?variant=thumbnail','«الزعيم» تخطف لقب القعدان في مهرجان ولي العهد للهجن بالطائف',750,475,'valid','published','archived','valid',99,'9fcbc48981cd0359dc7cc9740b07e0c2bb3c97017f3826495f19e1a9303762df','62064d2b18f1be9f79a1318af6424247349fc6e13bbc05fc0de825b4ab7152da','محدّث','2026-09-05T17:13:08.156Z','2026-10-07T19:51:38.628Z','','',0,0,'saudi_national','أولوية قصوى',82,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد للهجن بالطائف تو","رئيس مجلس إدارة الاتحاد السعودي","مجلس إدارة الاتحاد السعودي للهجن","الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق"]','["ولي العهد للهجن بالطائف تو","رئيس مجلس إدارة الاتحاد السعودي","مجلس إدارة الاتحاد السعودي للهجن","الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[{"category":"التقنية","score":2},{"category":"الرياضة","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:51:38.628Z',200,21,0,'source_article_available','',NULL,NULL,'body:d09d91bd006d599afd947793c48ab3bcf73c94bb348ea8126ea5c162777bc160','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c1ea1fc0-f59e-48ca-838f-3ac197762b04','news-c1ea1fc0-f59e-48ca-838f-3ac197762b04','سيدات النصر يتوّجن بلقب السوبر السعودي على حساب الهلال برباعية','سيدات النصر يتوجن بلقب السوبر السعودي علي حساب الهلال برباعيه','توّج فريق سيدات نادي النصر لكرة القدم بلقب كأس السوبر السعودي، بعد فوزه الكبير على منافسه الهلال بأربعة أهداف مقابل هدف، في المباراة التي أُقيمت مساء اليوم على ملعب مدينة الملك فهد الرياضية في الطائف.','["وتوزّعت أهداف النصر بين اللاعبة كلارا لوفانجا التي سجّلت ثلاثية «هاتريك» في الدقائق 12 و46 و78، فيما أضافت نسرين بهلولي الهدف الرابع في الدقيقة 82.","وجاء هدف الهلال الوحيد عن طريق أوشوالا في الدقيقة 40.","وكان النصر قد تأهّل إلى نهائي كأس السوبر بعد فوزه على الأهلي بنتيجة (5-2)، فيما بلغ الهلال النهائي بعد قلبه نتيجة مباراته أمام الاتحاد من التأخر إلى الفوز بنتيجة (2-1)."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/znyltza','https://sabq.org/article/znyltza','','https://sabq.org/article/znyltza','صحيفة سبق','الرياض','2026-09-05T11:10:00.000Z','2026-09-05T14:10:00.000Z','2026-09-05T17:13:08.476Z','https://media.sabq.org/news/2026/09/9e97349d-559f-47f6-b8c3-003d30a44b80/w1600.webp','/api/media/c1ea1fc0-f59e-48ca-838f-3ac197762b04','/api/media/c1ea1fc0-f59e-48ca-838f-3ac197762b04?variant=thumbnail','سيدات النصر يتوّجن بلقب السوبر السعودي على حساب الهلال برباعية',1600,1067,'valid','published','archived','valid',99,'007a66687eb64ec14c9d72d0c26ba9f89513e3c108f838ab239a8657d09746e8','3c2075a3df7dba8f4bb5d428d79e30f65d86a101c307f1f603a967579832611a','محدّث','2026-09-05T17:13:08.476Z','2026-10-07T19:51:37.031Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','classified','','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":-3.5}]','Active','2026-10-07T19:51:37.031Z',200,21,0,'source_article_available','',NULL,NULL,'body:e77c0893ff8bc55fe752bede5f34d5bbd6dfde67f46acc843e2fdeb3084b6082','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f2c20f43-4d2c-46f7-a628-2d2ea061651d','news-f2c20f43-4d2c-46f7-a628-2d2ea061651d','إحباط هجمات حوثية بزوارق مفخخة في الخوخة والمخا وتقدمات ميدانية للمقاومة','احباط هجمات حوثيه بزوارق مفخخه في الخوخه والمخا وتقدمات ميدانيه للمقاومه','وفي الجبهة الغربية لتعز، حققت القوات المسلحة تقدمات ميدانية واستعادت عدداً من التباب والمواقع، فيما سيطرت في الجبهة الجنوبية على مواقع ومرتفعات حاكمة استراتيجية.','["أحبطت قوات البحرية في «المقاومة الوطنية في الساحل الغربي» اليمني هجمات جديدة بالزوارق المفخخة شنّتها ميليشيا الحوثي، بالتزامن مع اشتداد المواجهات البرية على مختلف محاور القتال غرب تعز وجنوب الحديدة.","وأعلن الإعلام العسكري أن القوات البحرية دمّرت زورقين مفخخين حاولا استهداف الفجرة بالخوخة وميناء المخا، وذلك غداة تفجير زورق مفخخ ثالث في المنطقة ذاتها.","وفي السياق ذاته، جدّدت ميليشيا الحوثي استهداف المناطق السكنية بالصواريخ، إذ ضربت مكتب التربية والتعليم في مديرية حيس جنوب الحديدة بصاروخ باليستي.","وعلى الصعيد البري، أعلنت مصادر عسكرية يمنية تحقيق تقدمات ميدانية مهمة لقوات المقاومة الوطنية مسنودةً بوحدات من «ألوية العمالقة» في محور الجراحي، تزامناً مع عمليات هجومية باتجاه جبل راس جنوب الحديدة.","وأسفرت المعارك العنيفة في محيط جبل دباس الاستراتيجي بحيس خلال اليومين الماضيين عن سقوط مئات القتلى والجرحى في صفوف الميليشيات.","كما أعلن الإعلام العسكري للمقاومة الوطنية تكبيد الميليشيات خسائر فادحة على محور البرح غرب تعز، وإسقاط مسيّرتين مفخختين واغتنام أسلحة متعددة."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/tef67vg','https://sabq.org/article/tef67vg','','https://sabq.org/article/tef67vg','صحيفة سبق','','2026-09-05T11:16:00.000Z','2026-09-05T14:16:00.000Z','2026-09-05T17:18:26.183Z','https://media.sabq.org/news/2026/09/1cf5dbba-f828-4653-88e7-fbc7e3dfbbfc/w555.webp','/api/media/f2c20f43-4d2c-46f7-a628-2d2ea061651d','/api/media/f2c20f43-4d2c-46f7-a628-2d2ea061651d?variant=thumbnail','إحباط هجمات حوثية بزوارق مفخخة في الخوخة والمخا وتقدمات ميدانية للمقاومة',555,312,'valid','published','archived','valid',35,'f672ceeb42d065417e1b441908d1800aeb881ad2e57e8d3d707b3baf11da7340','feb2e27a0c6f5dc3f5f7689e38d2276971f16a88d0c946c10e828904b745311d','محدّث','2026-09-05T17:18:26.183Z','2026-10-07T20:25:22.790Z','','',0,0,'gulf_arab','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","التعليم والتدريب","اليمن"]','["السفر والسياحة","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:51:37.022Z',200,21,0,'source_article_available','',NULL,NULL,'body:6768fba44a3db2389bd57768454eafc64d5a9893bcc3c83d4f90ae66edc86d36','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9b5970b5-37d6-487a-b3ce-15adca1d4268','news-9b5970b5-37d6-487a-b3ce-15adca1d4268','سفير واشنطن لدى الناتو: لن نتسامح مع الأعمال الهجينة ضد أعضاء الحلف','سفير واشنطن لدي الناتو لن نتسامح مع الاعمال الهجينه ضد اعضاء الحلف','أكد ماثيو ويتيكر، سفير الولايات المتحدة لدى حلف شمال الأطلسي، السبت، أن الدول الأعضاء في الحلف يجب ألا تتسامح مع الأعمال المتعمدة في إطار الحرب الهجينة، مشدداً على أن واشنطن ستقف إلى جانبها في التعامل مع هذه التهديدات.','["وأشار ويتيكر، على هامش مؤتمر أعمال في إيطاليا، إلى أن محاولة الهجوم بطائرات مسيّرة التي وقعت الشهر الماضي في مطار لايبزيغ/هاله الألماني، والتي ألقت برلين بمسؤوليتها على روسيا، كانت «أكثر إثارةً للقلق» مقارنةً بالوقائع الأخرى التي واجهتها دول الحلف مؤخراً، والمرتبطة بطائرات مسيّرة روسية تستهدف أوكرانيا وتنحرف عن مساراتها.","وقال ويتيكر: «هناك ما أسميها الأعمال الهجينة الأكثر إثارةً للقلق، مثل تلك التي شهدناها في لايبزيغ، ومثل تلك التي شهدناها في بولندا».","ودعا ويتيكر دول الحلف إلى أن تكون مستعدة ويقظة، وأن تبعث برسالة قوية حين تواجه مثل هذه التحديات، مؤكداً: «إذا تمكنا من تحديد الجهة المسؤولة، وهو ما فعلته ألمانيا، فإننا نحرص على التعبير بقوة عن أن هذا الأمر غير مقبول ولن نتسامح معه».","وأوضح أن البنية التحتية الحيوية، بما فيها أصول الطاقة، باتت هدفاً محتملاً لهذه الأعمال، مشيراً إلى ضرورة إخضاعها لمراقبة مستمرة من السلطات الوطنية.","وأكد ويتيكر أن الاستجابة لهذه التحديات تقع في المقام الأول على عاتق الدول الأعضاء أنفسها، غير أن الولايات المتحدة ستواصل دعم حلفائها في مواجهة هذه الأعمال الهجينة."]','العالم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/er2kpst','https://sabq.org/article/er2kpst','','https://sabq.org/article/er2kpst','صحيفة سبق','','2026-09-05T11:20:00.000Z','2026-09-05T14:20:00.000Z','2026-09-05T17:31:06.627Z','https://media.sabq.org/news/2026/09/c47ccfe0-e095-4da1-8338-55353e789131/w801.webp','/api/media/9b5970b5-37d6-487a-b3ce-15adca1d4268','/api/media/9b5970b5-37d6-487a-b3ce-15adca1d4268?variant=thumbnail','سفير واشنطن لدى الناتو: لن نتسامح مع الأعمال الهجينة ضد أعضاء الحلف',801,451,'valid','published','archived','valid',35,'9d39cd3949cf222f557fc16badec44467b99647e2f6065ed81080bb6db28412e','f87b42af1df411c96dccbd5b7d8bc10734079ed409548322060e4eeb8d468282','محدّث','2026-09-05T17:31:06.627Z','2026-10-07T20:25:22.790Z','','',0,0,'international','عادي',56,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","روسيا","أوكرانيا","الولايات المتحدة"]','["الطاقة والنفط","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Temporarily Unreachable','2026-10-07T20:21:57.703Z',NULL,20,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7b1784d9-e50c-461b-807b-e2a692e2ebaf','news-7b1784d9-e50c-461b-807b-e2a692e2ebaf','استشاري سكري: رز القرنبيط يحتوي 5 جرامات كربوهيدرات مقابل 45 في الرز العادي','استشاري سكري رز القرنبيط يحتوي 5 جرامات كربوهيدرات مقابل 45 في الرز العادي','5 جرامات كربوهيدرات مقابل 45 في الرز العادي أوضح «جوهرجي» أن «رز القرنبيط» (الزهرة) يُعدّ من الخيارات الغذائية الأقل تأثيراً في مستوى سكر الدم، مشيراً إلى أنه متوفر في كل مكان ورخيص الثمن.','["كشف استشاري التخصص الدقيق في أمراض السكري، الدكتور عبدالرحمن جوهرجي، عبر حسابه على منصة «إكس»، عن جملة من الجوانب المهمة في التعامل مع مرض السكري، شملت الخيارات الغذائية الأنسب، وأهمية علاج السمنة، وضرورة النظر إلى حالة المريض بصورة شاملة عند اختيار العلاج. «رز القرنبيط».. 5 جرامات كربوهيدرات مقابل 45 في الرز العادي أوضح «جوهرجي» أن «رز القرنبيط» (الزهرة) يُعدّ من الخيارات الغذائية الأقل تأثيراً في مستوى سكر الدم، مشيراً إلى أنه متوفر في كل مكان ورخيص الثمن.","وبيّن أن الكوب المطبوخ من رز القرنبيط يحتوي على نحو 5 جرامات من الكربوهيدرات، في حين يحتوي الكوب من الرز التقليدي على نحو 45 جراماً، قائلاً: «يعني لو أكلت منه 9 أكواب كانك أكلت كوب رز عادي».","وشرح طريقة إعداده بتقطيع رأس قرنبيط متوسط الحجم إلى زهرات صغيرة، ثم طحنه بشكل متقطع في محضرة الطعام حتى يصبح بحجم حبات الرز، مع تجنب الإفراط في الطحن حتى لا يتحول إلى معجون.","ثم يُشوَّح في مقلاة واسعة مع ملعقة أو ملعقتين من زيت الزيتون على نار متوسطة إلى عالية لمدة 5 إلى 7 دقائق، ويُضاف الملح والفلفل الأسود، مع إمكانية إضافة الكمون أو الثوم البودرة، ويمكن تغطيته دقيقتين أو ثلاث دقائق إضافية لمن يرغب في قوام أكثر طراوة.","ونبّه إلى إمكانية إضافة قطرات قليلة من الماء إذا بدا القرنبيط جافاً أثناء التشويح، مع عدم الإكثار منها لأن القرنبيط يحتوي أصلاً على نسبة مرتفعة من الماء.","وأكد أن القرنبيط لا يتميز فقط بانخفاض الكربوهيدرات، بل يحتوي كذلك على الألياف الغذائية والفيتامينات والمعادن.","حاجة ماسة لا رفاهية طرح «جوهرجي» تساؤلاً حول أهمية علاج السمنة لدى المصاب بالسكري، مستنداً إلى دراسة أُجريت على أكثر من 100 ألف شخص، وجدت ارتباطاً واضحاً بين السمنة وزيادة الوفيات لدى المصابين بالسكري، حتى بعد ضبط عوامل أخرى كضغط الدم والدهون في الدم.","وأوضح أن كل زيادة بمقدار 5 نقاط في مؤشر كتلة الجسم (BMI) فوق 30 ارتبطت بزيادة خطر الوفاة من جميع الأسباب بنحو 21% لدى الرجال و16% لدى النساء، فيما ارتفعت الوفيات الوعائية تحديداً بنحو 24% لدى الرجال و23% لدى النساء لكل زيادة قدرها 5 كجم/م² في مؤشر كتلة الجسم. «علاج التراكمي» لا يكفي.."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/RUWreeE','https://sabq.org/article/RUWreeE','','https://sabq.org/article/RUWreeE','عبدالحكيم شار','المدينة المنورة','2026-09-05T11:30:00.000Z','2026-09-05T14:30:00.000Z','2026-09-05T17:40:07.495Z','https://media.sabq.org/news/2026/09/8e5f0ff0-4768-470a-8b60-f1aecb738364/w1200.webp','/api/media/7b1784d9-e50c-461b-807b-e2a692e2ebaf','/api/media/7b1784d9-e50c-461b-807b-e2a692e2ebaf?variant=thumbnail','استشاري سكري: رز القرنبيط يحتوي 5 جرامات كربوهيدرات مقابل 45 في الرز العادي',1200,1800,'valid','published','archived','valid',58,'0255488b2f4b8122b61c28ab063d2cc5934a9694d4ced869b308c373534618ef','6a8a40906ab616cfb38564f6d2e4a81db5183591e22eff6d6b866c5c323937b9','محدّث','2026-09-05T17:40:07.495Z','2026-10-07T20:51:48.399Z','','',0,0,'saudi_region','مهم',63,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة"]','["الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T20:51:48.399Z',200,21,0,'source_article_available','',NULL,NULL,'body:30f5019dc229cf7691b10474ef6c77409bb84a81fcd3f4808432865007d6ca04','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('88a92a44-5cd8-4e23-ac25-d4d08d6c8301','news-88a92a44-5cd8-4e23-ac25-d4d08d6c8301','رصد تضاريس القمر في سماء رفحاء يكشف فوهات صدمية وسلاسل جبلية','رصد تضاريس القمر في سماء رفحاء يكشف فوهات صدميه وسلاسل جبليه','كشف رصد القمر في طور التربيع الأخير من سماء محافظة رفحاء بمنطقة الحدود الشمالية عن جملة من أبرز معالم سطحه، في مقدمتها الفوهات الصدمية والمرتفعات والبحار البركانية الداكنة، التي تمثل سجلاً جيولوجياً نادراً يوثق تاريخ تشكّل النظام الشمسي المبكر.','["وأوضح عضو جمعية «آفاق لعلوم الفلك» برجس الفليح لوكالة الأنباء السعودية «واس»، أن عملية الرصد أظهرت عدداً من تفاصيل سطح القمر، مشيراً إلى أن درجة وضوح هذه المعالم تتأثر بمرحلة القمر وتوقيت الرصد وصفاء الأجواء والأدوات الفلكية المستخدمة.","وبيّن الفليح أن تضاريس القمر تشكّلت بصورة رئيسة بفعل الارتطامات النيزكية واسعة النطاق والنشاط البركاني القديم، ولا تزال آثار هذه العمليات محفوظة بدرجة كبيرة نتيجة محدودية عمليات التعرية على سطحه مقارنة بالأرض، مما يجعل تضاريسه مصدراً مهماً لدراسة تاريخه الجيولوجي.","وتُعدّ الفوهات الصدمية من أكثر المعالم انتشاراً على سطح القمر، وهي نتاج اصطدام الكويكبات والنيازك والمذنبات بسطحه على مدى مليارات السنين، وتتباين هذه الفوهات في أحجامها وأشكالها، فيما تكشف بعضها عن مواد من طبقات أعمق في القشرة القمرية، وتوفر مؤشرات على طبيعة الارتطامات التي أسهمت في تشكيل السطح.","وأشار الفليح إلى أن الفوهات القمرية تبدو أكثر وضوحاً عند اقتراب القمر من طور التربيع، إذ تسهم الظلال الممتدة على حوافها ومنحدراتها في إبراز تفاصيلها، مقارنة بفترة البدر التي تقل فيها الظلال وتبدو بعض التضاريس أقل تبايناً.","وتظهر إلى جانب الفوهات ما يُعرف بـ«البحار القمرية»، وهي مناطق داكنة واسعة لا تمثل بحاراً مائية، بل سهول بركانية تشكّلت حين غمرت تدفقات من الحمم البازلتية أحواضاً ومنخفضات واسعة نتجت عن اصطدامات كبرى، وتتميز بلونها الداكن مقارنة بالمرتفعات القمرية الأكثر سطوعاً، وترتبط باختلافات في التركيب المعدني والعمر الجيولوجي لسطح القمر.","كما تكشف التضاريس القمرية عن سلاسل جبلية ومرتفعات شاهقة تختلف في نشأتها عن جبال الأرض؛ إذ ارتبط تشكّل كثير منها بالارتطامات العملاقة التي أحدثت أحواضاً واسعة، فيما أسهمت قوى الاصطدام وارتداد سطح القمر في تشكيل حواف مرتفعة ومعقدة حولها.","وأكد الفليح أن رصد القمر لا يقتصر على الجانب الجمالي، بل يمثل وسيلة مبسّطة للتعرف على تاريخه الجيولوجي، مشيراً إلى أن متابعة تغيّر الإضاءة والظلال على سطحه تساعد على تمييز الفوهات والجبال والسهول البركانية، وتدعم نشر الثقافة الفلكية بين أفراد المجتمع.","وتتيح دراسة هذه المعالم للعلماء إعادة بناء مراحل مهمة من التاريخ الجيولوجي للقمر، وفهم طبيعة الارتطامات والنشاط البركاني الذي مرّ به، فضلاً عن الاستفادة منها في تحديد خصائص المواقع المرشحة للهبوط والاستكشاف في المهمات القمرية المستقبلية."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/2wwmjcd','https://sabq.org/article/2wwmjcd','','https://sabq.org/article/2wwmjcd','صحيفة سبق','الحدود الشمالية','2026-09-05T11:40:00.000Z','2026-09-05T14:40:00.000Z','2026-09-05T17:49:06.825Z','https://media.sabq.org/news/2026/09/73ec9c2d-f13d-4e93-9c5b-f2968aed5637/w1600.webp','/api/media/88a92a44-5cd8-4e23-ac25-d4d08d6c8301','/api/media/88a92a44-5cd8-4e23-ac25-d4d08d6c8301?variant=thumbnail','رصد تضاريس القمر في سماء رفحاء يكشف فوهات صدمية وسلاسل جبلية',1600,1009,'valid','published','archived','valid',50,'37b59b25526734137fc4df75d4c67924065838be34bcddd339fe3065ee21711a','af4fe46fa34a5c092031570c0e3b3cc69063efa9d9220bb0cfa9728d25ac1743','محدّث','2026-09-05T17:49:06.825Z','2026-10-07T21:01:00.712Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","الاقتصاد والأسواق"]','["الثقافة والفنون","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الرياضة","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T21:01:00.712Z',200,24,0,'source_article_available','',NULL,NULL,'body:f7a6188701c5bd96ded4d25dd9085f36ee5053b8fa3aac1835d8b1d3cd6421cf','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2534b854-899b-4568-9b5f-7ab4c16441a9','news-2534b854-899b-4568-9b5f-7ab4c16441a9','إنجاز 85% من جسر طريق الثمامة عند تقاطع طريق الأمير محمد بن سلمان في الرياض','انجاز 85 من جسر طريق الثمامه عند تقاطع طريق الامير محمد بن سلمان في الرياض','أعلنت الهيئة الملكية لمدينة الرياض ، اليوم السبت، ارتفاع نسبة الإنجاز بجسر طريق الثمامة عند تقاطع طريق الأمير محمد بن سلمان إلى 85%. وأكدت الهيئة عبر حسابها على منصة "إكس"، أن الأعمال الميدانية في جسر طريق الثمامة عند تقاطع طريق الأمير محمد بن سلمان تسير بوتيرة متقدمة، بما يعزز كفاءة الحركة والترابط على أحد المحاور الحيوية في الرياض .','["أعلنت الهيئة الملكية لمدينة الرياض ، اليوم السبت، ارتفاع نسبة الإنجاز بجسر طريق الثمامة عند تقاطع طريق الأمير محمد بن سلمان إلى 85%.","الجدير بالذكر أن المشروع يأتي ضمن برنامج تطوير محاور الطرق الدائرية والرئيسية في مدينة الرياض، الذي أطلقته الهيئة الملكية لمدينة الرياض."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/0ed0b3o6x','https://ajel.sa/local/0ed0b3o6x','https://ajel.sa/local/0ed0b3o6x','https://ajel.sa/local/0ed0b3o6x','فريق التحرير','الرياض','2026-09-05T11:43:00.000Z','Wed, 07 Oct 2026 21:11:13 GMT','2026-09-05T17:58:05.477Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000268441-WvM7w_Kb.jpg','/api/media/2534b854-899b-4568-9b5f-7ab4c16441a9','/api/media/2534b854-899b-4568-9b5f-7ab4c16441a9?variant=thumbnail','إنجاز 85% من جسر طريق الثمامة عند تقاطع طريق الأمير محمد بن سلمان في الرياض',1200,675,'valid','published','archived','valid',58,'052778fdff92ed0b815d03effbb72b6e5a2158b4e4923eea25d2bfb8f3ca7be8','fd515fbdcfda823a2d27a7fc078548393d3f688709d6f48926b6774d817797d4','محدّث','2026-09-05T17:58:05.477Z','2026-10-07T21:11:14.759Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياض"]','[]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:11:14.759Z',200,22,0,'source_content_changed','',NULL,NULL,'body:12922f33ecb226c39720b109b74ee5ba9b158d95fdf522f14cca849e64aea7e1','Wed, 07 Oct 2026 21:11:13 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('613ae6c2-adaf-4b68-bc46-005a3685f9fc','news-613ae6c2-adaf-4b68-bc46-005a3685f9fc','قمة الاتحاد والنصر.. فيسينج يعلن تشكيل العميد ورونالدو يقود هجوم العالمي','قمه الاتحاد والنصر فيسينج يعلن تشكيل العميد ورونالدو يقود هجوم العالمي','أعلن ينز فيسينج، المدير الفني لفريق الاتحاد، التشكيل الأساسي الذي يخوض به مواجهة النصر، في قمة منافسات دوري روشن السعودي ، وسط رغبة «العميد» في تحقيق الفوز أمام أحد أبرز منافسيه.','["حراسة المرمى: بريدراج رايكوفيتش. خط الدفاع: أحمد الجليدان، حسن كادش ، دانيلو بيريرا، فارس عابدي. خط الوسط: ديان لوبي، مختار علي ، حسام عوار . خط الهجوم: أحمد الغامدي ، جورج أيلينكينا، ستيفن بيرجوين.","وعلى الجانب الآخر، أعلن الجهاز الفني للنصر بقيادة المدرب الأسترالي آنج بوستيكوجلو تشكيل الفريق أمام الاتحاد، وجاء كالتالي:","حراسة المرمى: نواف العقيدي . خط الدفاع: نواف بوشل ، محمد سيماكان، عبد الإله العمري ، سالم النجدي. خط الوسط: أنجيلو غابرييل، سامو كوستا، كينغسلي كومان . خط الهجوم: ساديو ماني ، جواو فيليكس ، كريستيانو رونالدو ."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/1fcepv1mv','https://ajel.sa/sports/1fcepv1mv','https://ajel.sa/sports/1fcepv1mv','https://ajel.sa/sports/1fcepv1mv','فريق التحرير','','2026-09-05T11:43:00.000Z','Wed, 07 Oct 2026 21:11:11 GMT','2026-09-05T17:58:06.304Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%A7%D8%AA%D8%AD%D8%A7%D8%AF-%D9%88%D8%A7%D9%84%D9%86%D8%B5%D8%B1-9MGo_uRa.jpg','/api/media/613ae6c2-adaf-4b68-bc46-005a3685f9fc','/api/media/613ae6c2-adaf-4b68-bc46-005a3685f9fc?variant=thumbnail','الاتحاد والنصر',1200,675,'valid','published','archived','valid',41,'05bb69cded0c726d6cf6e6c8b5088186c73530c3cf6e64340a3632f7c3c4eb46','3d1b18832cc50bd755e2997d8864f5bfc467e0221ff5dac48af4b498ee98d2a9','محدّث','2026-09-05T17:58:06.304Z','2026-10-07T21:11:13.018Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:11:13.018Z',200,24,0,'source_content_changed','',NULL,NULL,'body:907a57af53fa556299485be03958313f197d574778b0a665cfc6b310d1280dfb','Wed, 07 Oct 2026 21:11:11 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6982f1b5-4250-4738-b936-2fcbb44f4703','news-6982f1b5-4250-4738-b936-2fcbb44f4703','واشنطن ترصد 150 ألف دولار لاعتقال تركي احتال على البنتاغون','واشنطن ترصد 150 الف دولار لاعتقال تركي احتال علي البنتاغون','وبحسب ما أورده موقع «يورو نيوز» باللغة التركية، استخدم شيمشيك وشركاؤه شركةً في ولاية فلوريدا بين أبريل 2019 وفبراير 2022، للحصول على عقود حكومية لتوريد مكونات عسكرية حساسة، إذ قدّمت الشركة نفسها للسلطات الأميركية على أنها جهة تصنيع مؤهلة داخل الولايات المتحدة، بينما كانت القطع تُصنع في تركيا قبل شحنها وإعادة تغليفها لإظهارها وكأنها مصنّعة محلياً وتستوفي…','["أدرج مكتب التحقيقات الفيدرالي الأميركي (FBI) المواطنَ التركي أونور شيمشيك على قائمة أبرز المحتالين المطلوبين، فيما تعتقد السلطات أنه موجود حالياً في تركيا.","وبحسب بيان رسمي صادر عن مكتب التحقيقات الفيدرالي، كان المخطط ينطوي على تقديم معلومات ووثائق مضللة للجهات الحكومية الأميركية، بينها وكالة لوجستيات الدفاع، بهدف تمرير المكونات والحصول على عقود توريد عسكرية.","وقال العميل الخاص المسؤول في فرع الـ FBI بمدينة تامبا، رودني إي.","كروفورد، إن عملية الاحتيال كان يمكن أن تعرّض الأمن القومي الأميركي لخطر جسيم، مشيراً إلى أن التعاون بين أجهزة إنفاذ القانون ساعد في تجنب أسوأ السيناريوهات.","وأضاف أن المكتب وشركاءه ملتزمون بكشف مخططات الاحتيال في المشتريات الحكومية، وحماية الملكية الفكرية والمعلومات الحساسة من الوصول إلى الأيدي الخطأ.","وكشف المدعي العام الأميركي لمنطقة وسط فلوريدا، غريغوري و.","كيهو، أن شيمشيك كان قد مُنع من التعامل مع الحكومة الأميركية منذ عام 2018 بسبب جرائم مماثلة، غير أنه عاد، بحسب الاتهامات، إلى الانخراط في مخطط يستهدف عقود وزارة الدفاع لتحقيق مكاسب شخصية، متهماً إياه بإخفاء معلومات وتقديم بيانات كاذبة للحكومة الأميركية على حساب دافعي الضرائب.","ويواجه شيمشيك اتهامات اتحادية عدة، تشمل: التآمر للاحتيال على الحكومة الأميركية، والاحتيال الإلكتروني، وغسل الأموال، والتآمر لانتهاك قيود التصدير، إضافة إلى انتهاك قوانين مراقبة الصادرات والأسلحة."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/mhl80l0','https://sabq.org/article/mhl80l0','','https://sabq.org/article/mhl80l0','صحيفة سبق','','2026-09-05T11:49:00.000Z','2026-09-05T14:49:00.000Z','2026-09-05T17:58:06.819Z','https://media.sabq.org/news/2026/09/193ccc22-d8ce-4499-8415-cced74c89ee9/w514.webp','/api/media/6982f1b5-4250-4738-b936-2fcbb44f4703','/api/media/6982f1b5-4250-4738-b936-2fcbb44f4703?variant=thumbnail','واشنطن ترصد 150 ألف دولار لاعتقال تركي احتال على البنتاغون',514,360,'valid','published','archived','valid',41,'80d7fa0bffb5b1c4851389f2571c8192cc8b82d6128f3024c875a53cb6d8d81c','1d58444a20ef050ed59f444e09d2614226a3eef8ca089e4daf1a024718aba7e3','محدّث','2026-09-05T17:58:06.819Z','2026-10-07T21:08:05.147Z','','',0,0,'international','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة في ولاية فلوريدا بين","وزارة الدفاع لتحقيق مكاسب شخصية","تركيا","الولايات المتحدة"]','["شركة في ولاية فلوريدا بين","وزارة الدفاع لتحقيق مكاسب شخصية","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:08:05.147Z',200,27,0,'source_article_available','',NULL,NULL,'body:add373f9706b1cb16a58d436d12a5830e1854d0a09b43f65eb1ca87dcec23eec','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8a5ae5a1-4dfc-4b10-b91d-cb609489190e','news-8a5ae5a1-4dfc-4b10-b91d-cb609489190e','القبض على مواطنين لترويج المخدرات والأقراص الخاضعة للتداول الطبي في الجوف ونجران','القبض علي مواطنين لترويج المخدرات والاقراص الخاضعه للتداول الطبي في الجوف ونجران','أعلنت المديرية العامة لمكافحة المخدرات القبض على مواطنين في منطقتي الجوف و نجران ، على خلفية ترويج مواد مخدرة وأقراص خاضعة لتنظيم التداول الطبي، مع اتخاذ الإجراءات النظامية بحقهما وإحالتهما إلى النيابة العامة .','["وفي منطقة الجوف، ألقت المديرية العامة لمكافحة المخدرات القبض على مواطن لترويجه مادتي الحشيش والإمفيتامين المخدرتين، إلى جانب أقراص خاضعة لتنظيم التداول الطبي.","وأوضحت المديرية أنه جرى إيقاف المقبوض عليه في الجوف، واستكمال الإجراءات النظامية بحقه، قبل إحالته إلى النيابة العامة.","وفي منطقة نجران، ضبطت المديرية مواطنًا آخر لترويجه أقراصًا خاضعة لتنظيم التداول الطبي، حيث جرى إيقافه واتخاذ الإجراءات النظامية بحقه وإحالته إلى النيابة العامة.","وجددت الجهات الأمنية دعوتها للمواطنين والمقيمين إلى الإبلاغ عن أي معلومات تتوافر لديهم بشأن أنشطة مرتبطة بتهريب أو ترويج المخدرات، مؤكدة أن جميع البلاغات ستعالج بسرية تامة.","ويمكن الإبلاغ عبر الرقم (911) في مناطق مكة المكرمة و الرياض و الشرقية ، والرقم (999) في بقية مناطق المملكة، إضافة إلى رقم بلاغات المديرية العامة لمكافحة المخدرات (995)، أو عبر البريد الإلكتروني [email&#160;protected] ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/hg8thry1h','https://ajel.sa/local/hg8thry1h','https://ajel.sa/local/hg8thry1h','https://ajel.sa/local/hg8thry1h','فريق التحرير','الرياض','2026-09-05T12:00:00.000Z','Wed, 07 Oct 2026 21:21:39 GMT','2026-09-05T18:19:36.418Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D9%85%D9%83%D8%A7%D9%81%D8%AD%D8%A9-%D8%A7%D9%84%D9%85%D8%AE%D8%AF%D8%B1%D8%A7%D8%AA-P3MdH6Ps.jpg','/api/media/8a5ae5a1-4dfc-4b10-b91d-cb609489190e','/api/media/8a5ae5a1-4dfc-4b10-b91d-cb609489190e?variant=thumbnail','مكافحة المخدرات',1200,675,'valid','published','archived','valid',40,'365e3093e421a709ebab061abf789628ad676610c0b4faa329038723371a4ee8','5c4255e22154830b3d64989ff19e2620c43c9c7b4c19fbf23228c0870407f7cb','محدّث','2026-09-05T18:19:36.418Z','2026-10-07T21:21:41.446Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","نجران","الجوف","الرياض"]','[]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:21:41.446Z',200,23,0,'source_content_changed','',NULL,NULL,'body:57582a208522640644246b237f2c17264948a19fa269ec588100035df55e28f1','Wed, 07 Oct 2026 21:21:39 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ef91f27e-6c90-4ef6-b77d-cd7ff0d502d9','news-ef91f27e-6c90-4ef6-b77d-cd7ff0d502d9','التعاون يتعادل سلبياً مع الفتح بعشرة لاعبين في روشن','التعاون يتعادل سلبيا مع الفتح بعشره لاعبين في روشن','حافظ فريق التعاون على شباكه نظيفة أمام ضيفه الفتح، رغم النقص العددي، إذ انتهت المباراة بالتعادل السلبي 0-0، مساء اليوم السبت، ضمن منافسات الجولة الخامسة من دوري روشن السعودي للمحترفين.','["ولعب التعاون بعشرة لاعبين منذ الدقيقة 66 من عمر المباراة، عقب طرد لاعبه يونس البحراوي، غير أن ذلك لم يُفضِ إلى اختراق دفاعاته.","وواصل التعاون سلسلته السلبية للمرة الخامسة على التوالي دون تحقيق الفوز، ليرفع رصيده إلى 3 نقاط، محتلاً المركز الرابع عشر في جدول ترتيب الدوري.","ولم يختلف الحال كثيراً بالنسبة للفتح، الذي واصل بدوره سلسلة عدم الفوز، ليستقر رصيده عند 3 نقاط أيضاً، محتلاً المركز السادس عشر في الترتيب العام."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7VPJfAv','https://sabq.org/article/7VPJfAv','','https://sabq.org/article/7VPJfAv','صحيفة سبق','','2026-09-05T12:12:00.000Z','2026-09-05T15:12:00.000Z','2026-09-05T18:19:44.710Z','https://media.sabq.org/news/2026/09/337c6733-b432-4fd1-9689-1826846de3a4/w1080.webp','/api/media/ef91f27e-6c90-4ef6-b77d-cd7ff0d502d9','/api/media/ef91f27e-6c90-4ef6-b77d-cd7ff0d502d9?variant=thumbnail','التعاون يتعادل سلبياً مع الفتح بعشرة لاعبين في روشن',1080,1350,'valid','published','archived','valid',99,'079b2b364b0598559fce2bc0e984d1b5f89ebe564d1be724fe72a02c40045d7c','7de3bddc7c4697e38fff423aea29bb3aadf4b3ce672d06529d71a74808cb7c9f','محدّث','2026-09-05T18:19:44.710Z','2026-10-07T21:21:00.507Z','','',0,0,'international','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T21:21:00.507Z',200,24,0,'source_article_available','',NULL,NULL,'body:8a0bdc8bf14f73aa0b66c1b9e2e535522ef87206727ed4dc5f7dd23aa27551da','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f699a435-c975-446c-a5d3-78761478d893','news-f699a435-c975-446c-a5d3-78761478d893','الأمن البيئي يضبط مخالفين في محمية الملك عبدالعزيز وعسير','الامن البيئي يضبط مخالفين في محميه الملك عبدالعزيز وعسير','وفي محمية الملك عبدالعزيز الملكية، ضبطت القوات مواطنًا بعد رعيه 80 متنًا من الإبل في مواقع محظور فيها الرعي، بالمخالفة لتعليمات المحافظة على البيئة داخل المحمية.','["ضبطت القوات الخاصة للأمن البيئي مخالفات لنظام البيئة في محمية الملك عبدالعزيز و منطقة عسير ، شملت رعي الإبل في مواقع محظورة وإشعال النار خارج الأماكن المخصصة لها، مع تطبيق الإجراءات النظامية بحق المخالفين.","وأوضحت القوات أن عقوبة رعي الإبل في المواقع المحظورة تبلغ 500 ريال لكل متن.","وفي منطقة عسير، ضبطت القوات الخاصة للأمن البيئي مواطنًا آخر لمخالفته تعليمات وإرشادات المحافظة على الغطاء النباتي، بعد إشعاله النار في غير الأماكن المخصصة لها، مؤكدة تطبيق الإجراءات النظامية بحقه.","وأكدت القوات أن عقوبة إشعال النار في غير الأماكن المخصصة لها في الغابات والمتنزهات الوطنية تصل إلى 3 آلاف ريال.","ودعت القوات الخاصة للأمن البيئي المواطنين والمقيمين إلى الإبلاغ عن أي حالات تمثل اعتداءً على البيئة أو الحياة الفطرية، عبر الرقم (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض و المنطقة الشرقية ، والرقمين (999) و(996) في بقية مناطق المملكة.","وشددت على أن جميع البلاغات ستُعامل بسرية تامة، دون أدنى مسؤولية على المبلّغ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/luoabzjrx','https://ajel.sa/local/luoabzjrx','https://ajel.sa/local/luoabzjrx','https://ajel.sa/local/luoabzjrx','فريق التحرير','الرياض','2026-09-05T11:59:00.000Z','Wed, 07 Oct 2026 21:21:43 GMT','2026-09-05T18:19:45.485Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D9%82%D9%88%D8%A7%D8%AA-%D8%A7%D9%84%D8%AE%D8%A7%D8%B5%D8%A9-%D9%84%D9%84%D8%A3%D9%85%D9%86-%D8%A7%D9%84%D8%A8%D9%8A%D8%A6%D9%8A-2-9A_5Jwu1.jpg','/api/media/f699a435-c975-446c-a5d3-78761478d893','/api/media/f699a435-c975-446c-a5d3-78761478d893?variant=thumbnail','الأمن البيئي',1200,675,'valid','published','archived','valid',40,'4f60b385c82b27d4e539933731db8ed4070e68128492b09f0f01496d43e5aa12','0dac9c42b28fe6ec8096d5b0c351fa1a4d1899197713c04685a6525b055eb9bf','محدّث','2026-09-05T18:19:45.485Z','2026-10-07T21:21:45.441Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","التقنية والتحول الرقمي","مكة","عسير","الرياض","المدينة المنورة"]','["التعليم والتدريب","التقنية والتحول الرقمي","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"البيئة والمناخ","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T21:21:45.441Z',200,23,0,'source_content_changed','',NULL,NULL,'body:3f41094a4b7407687bbba0e5965df0d9459681a530d7e7d380bc6c53ea885077','Wed, 07 Oct 2026 21:21:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('70deb5c0-834c-4650-99bd-dabe6e5286b3','news-70deb5c0-834c-4650-99bd-dabe6e5286b3','النفيعي يحتفل بزواج ابنه عبد الإله','النفيعي يحتفل بزواج ابنه عبد الاله','احتفل محمد بن عامر النفيعي، المساعد لمدير عام التعليم بالطائف للشؤون التعليمية، بزواج نجله عبدالإله، في حفل أُقيم بمحافظة الطائف. وشهد حفل الزواج حضور عدد من الوجهاء والأعيان والمسؤولين، إلى جانب حشد من الأهل والأصدقاء والمهنئين الذين شاركوا العريس وذويه فرحة هذه المناسبة.','["احتفل محمد بن عامر النفيعي، المساعد لمدير عام التعليم بالطائف للشؤون التعليمية، بزواج نجله عبدالإله، في حفل أُقيم بمحافظة الطائف.","وشهد حفل الزواج حضور عدد من الوجهاء والأعيان والمسؤولين، إلى جانب حشد من الأهل والأصدقاء والمهنئين الذين شاركوا العريس وذويه فرحة هذه المناسبة.","وأعرب والد العريس عن بالغ سعادته بهذه المناسبة، مقدماً شكره وتقديره لجميع الحضور على مشاركتهم في هذه الليلة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/Ryw8cef','https://sabq.org/article/Ryw8cef','','https://sabq.org/article/Ryw8cef','فهد العتيبي','','2026-09-05T12:07:00.000Z','2026-09-05T15:07:00.000Z','2026-09-05T18:20:26.694Z','https://media.sabq.org/news/2026/09/bbeb6df4-c68c-4abf-9b7f-e7cf43d6ddff/w1600.webp','/api/media/70deb5c0-834c-4650-99bd-dabe6e5286b3','/api/media/70deb5c0-834c-4650-99bd-dabe6e5286b3?variant=thumbnail','النفيعي يحتفل بزواج ابنه عبد الإله',1600,1067,'valid','published','archived','valid',51,'4d3b441c4125393646f15416f642594cfe9e492687cfc31819ce932c9709549d','78608154982520836f9a5cc0836c96154fcbf88ccd8948a8857e8ed19a717ebf','محدّث','2026-09-05T18:20:26.694Z','2026-10-07T21:20:58.849Z','','',0,0,'international','عادي',58,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:20:58.849Z',200,21,0,'source_article_available','',NULL,NULL,'body:eaac81d5ece4695a80b413b0ff449eb6092167fd5b621ebef7ce72860bfd44be','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3c4aa677-744c-44ff-818e-688418abb298','news-3c4aa677-744c-44ff-818e-688418abb298','التعادل السلبي يحسم مواجهة الفيصلي والحزم في دوري روشن','التعادل السلبي يحسم مواجهه الفيصلي والحزم في دوري روشن','حسم التعادل السلبي مباراة الفيصلي والحزم، التي أُقيمت مساء السبت ضمن منافسات الجولة الخامسة من دوري روشن السعودي للمحترفين. وبهذه النتيجة، ارتفع رصيد الحزم إلى 5 نقاط ليحتل المركز العاشر في جدول ترتيب الدوري، فيما رفع الفيصلي رصيده إلى نقطتين محتلاً المركز السابع عشر.','["حسم التعادل السلبي مباراة الفيصلي والحزم، التي أُقيمت مساء السبت ضمن منافسات الجولة الخامسة من دوري روشن السعودي للمحترفين.","جاءت المباراة باهتة من الجانبين، وغابت عنها الإثارة والأهداف طوال 90 دقيقة، في لقاء لم يُسعد محبّي الفريقين.","وبهذه النتيجة، ارتفع رصيد الحزم إلى 5 نقاط ليحتل المركز العاشر في جدول ترتيب الدوري، فيما رفع الفيصلي رصيده إلى نقطتين محتلاً المركز السابع عشر."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/an8wmSR','https://sabq.org/article/an8wmSR','','https://sabq.org/article/an8wmSR','صحيفة سبق','','2026-09-05T12:05:00.000Z','2026-09-05T15:06:00.000Z','2026-09-05T18:20:26.701Z','https://media.sabq.org/news/2026/09/eb72e223-8e0e-4e90-9147-88c77c53ce90/w1080.webp','/api/media/3c4aa677-744c-44ff-818e-688418abb298','/api/media/3c4aa677-744c-44ff-818e-688418abb298?variant=thumbnail','التعادل السلبي يحسم مواجهة الفيصلي والحزم في دوري روشن',1080,1350,'valid','published','archived','valid',99,'1fbced165f99d03f0a5709ce2f49dc5ec14c1c17c599f8d43e727b2f3d885c15','99317056a8bb245b1d6d3aefee393752e5a221668592970484a13e7f5f9d0f3f','محدّث','2026-09-05T18:20:26.701Z','2026-10-07T21:20:55.490Z','','',0,0,'international','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T21:20:55.490Z',200,24,0,'source_article_available','',NULL,NULL,'body:65878fc8bca209aa0e75f15672bcd4ed0750cd3ca9ef43dbfd636fceb74884d1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('885d5937-ada7-46bc-9e98-9172eb54ca0f','news-885d5937-ada7-46bc-9e98-9172eb54ca0f','الطائي يتفوق على البكيرية بثنائية في افتتاح دوري الدرجة الأولى تحت 16 عامًا','الطائي يتفوق علي البكيريه بثنائيه في افتتاح دوري الدرجه الاولي تحت 16 عاما','تغلب فريق الطائي على ضيفه البكيرية بهدفين دون مقابل، في اللقاء الذي جمع الفريقين عصر اليوم السبت على ملعب الطائي بمدينة حائل ، ضمن أولى مواجهاتهما في منافسات دوري الدرجة الأولى تحت 16 عامًا.','["وانتهى الشوط الأول بالتعادل السلبي، قبل أن ينجح لاعب الطائي فيصل الطوالة في افتتاح التسجيل عند الدقيقة 64، ليعود اللاعب نفسه ويضيف الهدف الثاني عند الدقيقة 89، مؤكدًا تفوق فريقه وحصده نقاط المباراة الثلاث.","وبهذه النتيجة، يستهل الطائي مشواره في الدوري بانتصار ثمين، فيما يتطلع البكيرية إلى التعويض والعودة بنتيجة إيجابية في مواجهاته المقبلة."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/r00oa01sf','https://ajel.sa/sports/r00oa01sf','https://ajel.sa/sports/r00oa01sf','https://ajel.sa/sports/r00oa01sf','ماجد الفريدي','','2026-09-05T11:59:00.000Z','Wed, 07 Oct 2026 21:21:39 GMT','2026-09-05T18:20:47.963Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/1000268436-PWsPllbR.jpg','/api/media/885d5937-ada7-46bc-9e98-9172eb54ca0f','/api/media/885d5937-ada7-46bc-9e98-9172eb54ca0f?variant=thumbnail','الطائي يتفوق على البكيرية بثنائية في افتتاح دوري الدرجة الأولى تحت 16 عامًا',1200,675,'valid','published','archived','valid',41,'c3671ad9941727589a8389a20cbcfe2b4d157268b95977679372eb958a48a774','42e4e91b312885ce65294afab029014e1a02f24292683c28a260d84c05b96570','محدّث','2026-09-05T18:20:47.963Z','2026-10-07T21:21:41.463Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:21:41.463Z',200,23,0,'source_content_changed','',NULL,NULL,'body:1b3181e653f5c70018fbe37cea081da3e2f37184cd78b1790e57f8303db3f35c','Wed, 07 Oct 2026 21:21:39 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('984859d9-9f33-4690-8371-8f6850e9a949','news-984859d9-9f33-4690-8371-8f6850e9a949','«زاتكا» تدعو المنشآت الخاضعة لضريبة الاستقطاع إلى تقديم نماذج استقطاع الضريبة عن شهر أغسطس','زاتكا تدعو المنشات الخاضعه لضريبه الاستقطاع الي تقديم نماذج استقطاع الضريبه عن شهر اغسطس','دعت هيئة الزكاة والضريبة والجمارك ، المنشآت الخاضعة لضريبة الاستقطاع في المملكة إلى تقديم نماذج استقطاع الضريبة عن شهر أغسطس 2026م، وذلك في موعدٍ أقصاه 10 سبتمبر 2026م.','["وحثّت \"زاتكا\" عبر حسابها الرسمي على منصة \"إكس\"، المنشآت على المسارعة بتقديم نماذج استقطاع الضريبة من خلال موقعها الإلكتروني ( zatca.gov.sa )، وذلك تجنبًا لغرامة التأخر عن السداد في المدة المحددة، بواقع 1% من الضريبة غير المسددة عن كل ثلاثين يوم تأخير من تاريخ الاستحقاق.","ودعت \"زاتكا\" المكلفين من قطاع الأعمال الراغبين في الحصول على مزيد من المعلومات بشأن ضريبة الاستقطاع، إلى التواصل معها عبر الرقم الموحد لمركز الاتصال (19993)، الذي يعمل على مدار 24 ساعة طوال أيام الأسبوع، أو حساب \"اسأل الزكاة والضريبة والجمارك\" على منصة (إكس) ( @Zatca_Care ) أو البريد الإلكتروني ( [email&#160;protected] )، أو من خلال المحادثات الفورية عبر الموقع الإلكتروني للهيئة.","وتُفرض ضريبة الاستقطاع على كافة المبالغ المدفوعة من مصدر في المملكة للجهات غير المقيمة التي ليس لديها منشأة دائمة في المملكة، وذلك وفقًا للأسعار المحددة في المادة الثامنة والستون من نظام ضريبة الدخل والمادة الثالثة والستين من لائحته التنفيذية."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/9ovqmdr6t','https://ajel.sa/economy/9ovqmdr6t','https://ajel.sa/economy/9ovqmdr6t','https://ajel.sa/economy/9ovqmdr6t','فريق التحرير','عسير','2026-09-05T12:18:00.000Z','Wed, 07 Oct 2026 18:58:57 GMT','2026-09-05T18:32:05.664Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-LGQWugmz.jpg','/api/media/984859d9-9f33-4690-8371-8f6850e9a949','/api/media/984859d9-9f33-4690-8371-8f6850e9a949?variant=thumbnail','«زاتكا» تدعو المنشآت الخاضعة لضريبة الاستقطاع إلى تقديم نماذج استقطاع الضريبة عن شهر أغسطس',1200,675,'valid','published','archived','valid',40,'ddcc4066c0e17987fa2514c5a676241e3fbd5df810d6d97502bebf18415a9bfd','19d56d469605e64e052da582e47392fac6d9e02a8c1b4c0acde0c6aef398fa14','محدّث','2026-09-05T18:32:05.664Z','2026-10-07T18:58:59.454Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الزكاة والضريبة والجمارك المنشآت"]','["هيئة الزكاة والضريبة والجمارك المنشآت"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T18:58:59.454Z',200,22,0,'source_content_changed','',NULL,NULL,'body:ae51e1b8be2524c959473a4b4c22c8e6e24d6a081f03bba1740a46d0122cb291','Wed, 07 Oct 2026 18:58:57 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ee7986da-3de0-4ed1-adf1-454cc5f17d13','news-ee7986da-3de0-4ed1-adf1-454cc5f17d13','مليون ملف حساس تُسرق من برلين وتُنشر على «الدارك ويب» بعد رفض فدية مليوني يورو','مليون ملف حساس تسرق من برلين وتنشر علي الدارك ويب بعد رفض فديه مليوني يورو','وأكدت مجموعة «آر بي بي» الإعلامية العامة أن القراصنة نشروا الجمعة أكثر من مليون ملف من هذه البيانات عبر الإنترنت المظلم «دارك ويب»، وذلك عقب رفض برلين تلبية طلبهم بدفع فدية تناهز مليوني يورو.','["أقرّ عمدة برلين كاي فيغنر، في مقابلة نشرتها صحيفة «بيلد» السبت، بأن بيانات حساسة سُرقت جراء هجوم سيبراني تعرّضت له بلدية العاصمة الألمانية في 14 أغسطس، مجدداً رفضه القاطع الرضوخ لابتزاز القراصنة.","وكشفت أسبوعية «دير شبيغل» أن البيانات المسروقة تشمل إجراءات الحماية الداخلية لجهاز الإطفاء في برلين، وقوائم الرواتب، ومعلومات مصرفية، ونسخاً رقمية لهويات رسمية، ومعلومات سرية تخص الموظفين، فضلاً عن ملفات تتعلق بتوسعة مقر المستشارية الألمانية.","وتساءل فيغنر: «من يضمن أنه في حال دفعنا الفدية، لن تبقى هذه البيانات موجودة لوقت طويل في مكان آخر؟».","وتتابع حكومة المستشار فريدريش ميرتس «عن كثب المعلومات والتحقيق المتعلق بتسريب هذه البيانات»، وفق ما أفاد متحدث باسمها لوكالة فرانس برس.","وبحسب التقارير المحلية، تقف خلف الهجوم مجموعة قراصنة تُعرف باسم «رايزيدا» (Rhysida)، سبق لها تبنّي هجمات بارزة، أبرزها الهجوم على المكتبة البريطانية في لندن خريف 2023، حين طالبتها بفدية تتجاوز 760 ألف يورو، وإثر رفض المكتبة الاستجابة، نشرت المجموعة نحو 500 ألف ملف عبر الإنترنت المظلم تضمّنت بيانات شخصية للزوار والمشتركين والموظفين.","وعلى إثر الهجوم الذي وقع في 14 أغسطس، عجزت عدة إدارات في العاصمة الألمانية، ولا سيما المعنية بالسكن والبيئة، عن الوصول إلى الشبكة لمدة أسبوع كامل، مما أعاق تقديم طلبات إعانات السكن وصرفها لأيام."]','التقنية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7ev14my','https://sabq.org/article/7ev14my','','https://sabq.org/article/7ev14my','صحيفة سبق','','2026-09-05T12:20:00.000Z','2026-09-05T15:20:00.000Z','2026-09-05T18:32:07.509Z','https://media.sabq.org/news/2026/09/a30e589a-cf2a-48ab-a481-86e75007a78e/w801.webp','/api/media/ee7986da-3de0-4ed1-adf1-454cc5f17d13','/api/media/ee7986da-3de0-4ed1-adf1-454cc5f17d13?variant=thumbnail','مليون ملف حساس تُسرق من برلين وتُنشر على «الدارك ويب» بعد رفض فدية مليوني يورو',801,451,'valid','published','archived','valid',57,'4ddde34434b48b402ed3b1d6cc8479ea1632ff6bd02c5c512c134bb0deb3c683','01593b034e911c37990b8ebfbaacf363db2f14e7957873aa033a5df69ac0b541','محدّث','2026-09-05T18:32:07.509Z','2026-10-07T21:21:56.879Z','','',0,0,'gulf_arab','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي"]','["التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"المناطق","score":4},{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T21:21:56.879Z',200,22,0,'source_article_available','',NULL,NULL,'body:cc8de7dcf418480aeb2febf8f1cbff48b28db28786c3b9d0678f34d8cbfa5295','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('07009085-c8e3-41fc-a42a-139cf8970aaa','news-07009085-c8e3-41fc-a42a-139cf8970aaa','«سنتكوم» تُدمر 3 ناقلات نفط تابعة للحرس الثوري الإيراني بعد استهداف إيران لسفينتين','سنتكوم تدمر 3 ناقلات نفط تابعه للحرس الثوري الايراني بعد استهداف ايران لسفينتين','شنت قوات القيادة المركزية الأمريكية (سنتكوم) هجوما على 3 ناقلات نفط خام إيرانية في الخامس من سبتمبر، وذلك بعد أن أطلق الحرس الثوري الإيراني صواريخ باليستية باتجاه سفينتين حربيتين تابعتين للبحرية الأمريكية كانتا تقومان بدوريات في المياه الإقليمية.','["وقالت \"سنتكوم\" وفق بيان رسمي عبر حسابها على منصة \"إكس\"، إن حاملة طائرات أمريكية ومدمرة مُجهزة بصواريخ مّوجهة نجحت في تفادي هجمات إيرانية متعددة وغير مبررة. لم يُصب أي من الأفراد الأمريكيين بأذى.","وأضافت أنه عقب الهجمات الإيرانية الفاشلة، قامت القيادة المركزية الأمريكية بتعطيل ناقلتي النفط الخام التابعتين للحرس الثوري داوني (M/T Downy) قبالة سواحل جزيرة خارك وستارك ١ (M/T Stark 1) بالقرب من جاسك بشكل دائم.","كما دمرت القوات الأمريكية بالكامل ناقلة النفط الخام الفارغة كيلو (M/T Kylo) (المعروفة أيضاً باسم نوكسن Noxen) في خليج عُمان ، حيث استهدفت السفينة في عدة مواقع حيوية لجعلها غير صالحة للعمل، وذلك بعد توجيه الطاقم لمغادرة السفينة.","وتُعد ناقلات النفط الخام الإيرانية الثلاث جزءاً من شبكة سرية بمليارات الدولارات تموّل الحرس الثوري الإيراني ووكلاءه في المنطقة. لا تملك إيران أي وسيلة للدفاع عنها.","قال الأدميرال براد كوبر ، قائد القيادة المركزية الأمريكية: \"لتكن الرسالة الموجهة إلى الحرس الثوري واضحة: إذا أطلقتم النار على اثنتين من سفننا، فسنفرض عليكم تكلفة اقتصادية أعلى بكثير من خلال تدمير ثلاث من سفنكم\". وأضاف: \"لن نتردد في الدفاع عن القوات الأمريكية، وتدمير أسطول النفط الإيراني المحدود والمكشوف إذا لزم الأمر\"."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/93eibe0mu','https://ajel.sa/international/93eibe0mu','https://ajel.sa/international/93eibe0mu','https://ajel.sa/international/93eibe0mu','فريق التحرير','عسير','2026-09-05T12:18:00.000Z','Wed, 07 Oct 2026 21:22:00 GMT','2026-09-05T18:32:08.266Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-yn-3ZMLy.jpg','/api/media/07009085-c8e3-41fc-a42a-139cf8970aaa','/api/media/07009085-c8e3-41fc-a42a-139cf8970aaa?variant=thumbnail','«سنتكوم» تُدمر 3 ناقلات نفط تابعة للحرس الثوري الإيراني بعد استهداف إيران لسفينتين',1200,675,'valid','published','archived','valid',46,'51759afdc448a6de3f2ac17a15283cb1a0e23e92e9ef69360e5784e4d9eadfaa','3de57b0bae7d5f13c50c7e4efd7b70402d25ac45383f9352188dacbbc2016d0a','محدّث','2026-09-05T18:32:08.266Z','2026-10-07T21:22:02.424Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الرياضة السعودية","الاقتصاد والأسواق","إيران"]','["الطاقة والنفط","الرياضة السعودية","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T21:22:02.424Z',200,24,0,'source_content_changed','',NULL,NULL,'body:859abf99842daa923f09e532ffd3f2c03b3ca9994655e1e925bde070a0f886a7','Wed, 07 Oct 2026 21:22:00 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d92762b8-1aec-49a6-b513-be8047809559','news-d92762b8-1aec-49a6-b513-be8047809559','«أصابع من الضوء» تزين سماء جدة.. ما سر المشهد الذي ظهر وقت الغروب؟','اصابع من الضوء تزين سماء جده ما سر المشهد الذي ظهر وقت الغروب','شهدت سماء جدة عند غروب الشمس مشهدًا جويًا لافتًا، بعدما ظهرت الأشعة الشفقية في صورة حزم متباينة من الضوء والظل امتدت من جهة الأفق، لتبدو وكأنها «أصابع من الضوء» تتداخل مع ألوان الغروب.','["وأوضح المهندس ماجد أبو زاهرة، رئيس الجمعية الفلكية بجدة، أن هذا المشهد ينتج عن مرور أشعة الشمس عبر فجوات بين السحب، بعدما تحجب السحب أجزاء من الضوء، فتظهر مناطق مضيئة وأخرى داكنة بفعل ظلالها.","وأشار أبو زاهرة إلى أن تشتت ضوء الشمس في الغلاف الجوي يسهم في إظهار هذه الحزم بصورة واضحة، بينما تساعد الجسيمات الدقيقة من الغبار والهباء الجوي المعلقة في الهواء على تعزيز ظهورها.","وبيّن أن أشعة الشمس تصل إلى سطح الأرض في اتجاهات متوازية تقريبًا، إلا أن العين البشرية تراها وكأنها تتباعد من نقطة واحدة قرب الأفق، وهو تأثير ناتج عن المنظور البصري.","وأوضح رئيس الجمعية الفلكية بجدة أن الأشعة الشفقية من الظواهر البصرية الشائعة نسبيًا، لكن درجة وضوحها تختلف بحسب موقع السحب وسمكها، وكمية الجسيمات العالقة في الغلاف الجوي، إلى جانب زاوية ارتفاع الشمس.","وتظهر هذه الأشعة بصورة أكثر وضوحًا عند الغروب، عندما تكون الشمس منخفضة وقريبة من الأفق، فتزداد زاوية الرؤية المناسبة لملاحظة الحزم المتكونة بين الضوء والظل.","وشهدت سماء جدة خلال الظاهرة تدرجًا لونيًا امتد من الأزرق والبنفسجي إلى الوردي والذهبي والبرتقالي، تخللته حزم متباينة من الضوء والظل، في مشهد بصري نتج عن تفاعل ضوء الشمس مع السحب والغلاف الجوي."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/pjlzqj610','https://ajel.sa/misc/pjlzqj610','https://ajel.sa/misc/pjlzqj610','https://ajel.sa/misc/pjlzqj610','فريق التحرير','مكة المكرمة','2026-09-05T11:57:00.000Z','Wed, 07 Oct 2026 21:22:00 GMT','2026-09-05T18:32:09.765Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%AC%D9%85%D8%B9%D9%8A%D8%A9-%D8%A7%D9%84%D9%81%D9%84%D9%83%D9%8A%D8%A9-%D8%A8%D8%AC%D8%AF%D8%A9-eVS1UHEa.png','/api/media/d92762b8-1aec-49a6-b513-be8047809559','/api/media/d92762b8-1aec-49a6-b513-be8047809559?variant=thumbnail','الجمعية الفلكية بجدة',1200,675,'valid','published','archived','valid',41,'1ab364184ca17f764824b63b32861790dde3c6ad7ba8c288b81a2c6e33e27a42','c6afe11ae09922ee56025ff7036ebd3f1c598e95f7577662d3109caf6a360273','محدّث','2026-09-05T18:32:09.765Z','2026-10-07T21:22:02.476Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس الجمعية الفلكية بجدة أن","الاقتصاد والأسواق","مكة","جدة"]','["رئيس الجمعية الفلكية بجدة أن","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:22:02.476Z',200,23,0,'source_content_changed','',NULL,NULL,'body:8e91094f11af36a729ca2c0dc3ec42f863e2ed4a7511fa84a51c0f5677c8789c','Wed, 07 Oct 2026 21:22:00 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0fa11891-43da-4764-b956-27e306f34d61','news-0fa11891-43da-4764-b956-27e306f34d61','إسبانيا توافق على مخيم للمهاجرين في ميناء سبتة رغم اعتراض السلطات المحلية','اسبانيا توافق علي مخيم للمهاجرين في ميناء سبته رغم اعتراض السلطات المحليه','إي» ووسائل إعلام إسبانية أخرى، اليوم السبت، أن وزير النقل أوسكار بوينتي وقّع قرارًا يسمح بإقامة مخيم مؤقت من الخيام في منطقة الميناء، بعدما كانت السلطات المحلية قد أصدرت قرارًا مخالفًا.','["أقرت الحكومة الإسبانية إقامة مخيم مؤقت للمهاجرين في منطقة ميناء سبتة، متجاوزةً اعتراض السلطات المحلية التي رفضت استخدام الميناء لهذا الغرض، في أحدث فصول الخلاف بشأن كيفية إيواء المهاجرين في الجيب الإسباني الواقع شمال أفريقيا.","وكان خوان خيسوس فيفاس، رئيس الحكومة المحلية في سبتة، قد أعلن الجمعة رفضه إقامة المخيم في الميناء، مستندًا إلى أهمية المنطقة في تزويد الجيب باحتياجاته، إضافة إلى وجود مستودع كبير للوقود بالقرب منها.","ولم يقتصر الخلاف على موقع الميناء، إذ عارضت السلطات المحلية في وقت سابق خيارات أخرى لإيواء المهاجرين مؤقتًا، شملت مصنعًا مهجورًا ومستشفى عسكريًا سابقًا ومراكز رياضية.","وفي حي لوس روساليس، يتواصل في الوقت نفسه إنشاء مخيم إضافي يتسع لنحو 900 شخص، فيما شهد الموقع احتجاجات من السكان.","وتأتي هذه الإجراءات في ظل ارتفاع أعداد المهاجرين الموجودين في سبتة، بعدما سبح نحو 72 ألف مهاجر من المغرب إلى الجيب أو تسلقوا الأسوار الحدودية يومي 30 و31 يوليو، وفق أرقام حكومية، قبل أن يعود معظمهم خلال ساعات.","ورغم عودة الغالبية، بقي نحو 5 آلاف مهاجر في سبتة بعد أكثر من شهر، داخل منطقة لا تتجاوز مساحتها نحو 18 كيلومترًا مربعًا، بينهم 1200 قاصر، بحسب البيانات الحكومية."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/kk15vdujl','https://ajel.sa/international/kk15vdujl','https://ajel.sa/international/kk15vdujl','https://ajel.sa/international/kk15vdujl','فريق التحرير','','2026-09-05T11:57:00.000Z','Wed, 07 Oct 2026 18:58:56 GMT','2026-09-05T18:32:10.113Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%B3%D8%A8%D8%AA%D8%A9-cO9axl5_.jpg','/api/media/0fa11891-43da-4764-b956-27e306f34d61','/api/media/0fa11891-43da-4764-b956-27e306f34d61?variant=thumbnail','سبتة',1200,675,'valid','published','archived','valid',40,'add0d40da313840b38c26c5172fc9bfee43b8972cc3634a994b3f12f7b54371b','c64a1174bedb41c3dedda575b898726078777976849be70f25265abcdfe6be37','محدّث','2026-09-05T18:32:10.113Z','2026-10-07T20:25:22.790Z','','',0,0,'gulf_arab','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير النقل أوسكار بوينتي وق","رئيس الحكومة المحلية في سبتة","هيئة الإذاعة والتلفزيون الإسبانية الرسمية","الصحة العامة"]','["وزير النقل أوسكار بوينتي وق","رئيس الحكومة المحلية في سبتة","هيئة الإذاعة والتلفزيون الإسبانية الرسمية","الصحة العامة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T18:58:58.225Z',200,22,0,'source_content_changed','',NULL,NULL,'body:5464ea2574fb907ed4ab1b4862d845e197e0f5a4af61be5e90ae22d03fd459d5','Wed, 07 Oct 2026 18:58:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b09004cd-86d1-499f-a250-3f1e8665530c','news-b09004cd-86d1-499f-a250-3f1e8665530c','السلطان: «التواصل الاستراتيجي» شريك في صناعة القرار','السلطان التواصل الاستراتيجي شريك في صناعه القرار','وقال "السلطان" خلال الحفل إن فكرة الكتاب جاءت استجابة للحاجة إلى مراجع عربية متخصصة في التواصل الاستراتيجي، وسعيا إلى نقل الخبرات والتجارب المهنية إلى الأجيال الجديدة من العاملين والمهتمين بمجالات الإعلام والتواصل.','["استضافت ديوانية القلم الذهبي بالرياض، اليوم، حفل توقيع كتاب «التواصل الاستراتيجي..","دليلك العملي من النظرية إلى التطبيق» للكاتب وخبير التواصل الاستراتيجي عبدالرحمن بن سلطان السلطان، بحضور عدد من المهتمين بالإعلام والتواصل.","وأوضح أن التواصل لم يعد وظيفة ثانوية داخل المؤسسات، وإنما أصبح عنصرا أساسيا ومحوريا في عمل الأفراد والمنظمات، مشيرا إلى أن مفهوم «التواصل الاستراتيجي» يرتقي بالوظيفة الاتصالية لتصبح مرتبطة بالأهداف العليا للمنظمة وتسهم في تحقيقها.","وأكد أهمية مواكبة التطورات المتسارعة في مجال التواصل من خلال التدريب المستمر ونقل المعرفة، لافتا إلى مسؤولية أصحاب الخبرات في توثيق تجاربهم ومشاركتها مع الزملاء والأجيال المقبلة، بما يسهم في تراكم المعرفة المهنية وتطوير الممارسة.","وأشار إلى وجود فجوة لمسها خلال تعامله مع متدربين من جامعات مختلفة بين ما يقدم في الجانب الأكاديمي ومتطلبات العمل الاتصالي اليومي، موضحا أن الكتاب جاء محاولة للإسهام في تقليص هذه الفجوة، عبر تقديم المعرفة بصورة مختصرة وعملية بعيدا عن الإفراط في التنظير.","وبين أن فكرة الكتاب تقوم على تبسيط موضوعات التواصل وتلخيصها في مساحات محدودة وسهلة القراءة، مستفيدا من تجربة المقالات التي تراوح حجمها بين 400 و500 كلمة، بما يساعد القارئ على الانتقال من المفاهيم النظرية إلى التطبيق في بيئة العمل.","واستعرض \"السلطان\" مسيرته المهنية التي تمتد لأكثر من 25 عاما في مجال التواصل في القطاعات الحكومي والخاص وغير الربحي، موضحا أن فكرة الكتاب انطلقت من محاضرات ومقالات كتبها في صحيفة «الرياض»، قبل أن تتطور إلى عمل يجمع بين الخبرة المهنية والمعرفة الأكاديمية.","وأشار إلى أن الكتاب يعتمد لغة بسيطة ومباشرة، ويستعين بقصص وتجارب واقعية للنجاح والإخفاق، إلى جانب إحصاءات حديثة، بهدف تقديم محتوى عملي يساعد المختصين والمهتمين على تطبيق مفاهيم التواصل الاستراتيجي."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/NYQ22cd','https://sabq.org/article/NYQ22cd','','https://sabq.org/article/NYQ22cd','صحيفة سبق','الرياض','2026-09-05T12:34:00.000Z','2026-09-05T13:41:00.000Z','2026-09-06T05:13:15.461Z','https://media.sabq.org/news/2026/09/8dd5957b-7340-4e18-87fd-f7b214369bd9/w1280.webp','/api/media/b09004cd-86d1-499f-a250-3f1e8665530c','/api/media/b09004cd-86d1-499f-a250-3f1e8665530c?variant=thumbnail','السلطان: «التواصل الاستراتيجي» شريك في صناعة القرار',1280,854,'valid','published','archived','valid',46,'b4a49dcdf1c08b858d310eb59b49d041993801905ed834e6fbd10d8c67711c1e','cdb2fee5df6ba6501a1316acf19322a342b1313e11061c3a3649a78ab6a9237f','محدّث','2026-09-05T18:41:07.505Z','2026-10-07T20:25:22.790Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس إدارة الهيئة العامة","مجلس إدارة الهيئة العامة للترفيه","الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","الرياض"]','["رئيس مجلس إدارة الهيئة العامة","مجلس إدارة الهيئة العامة للترفيه","الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"التقنية","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:08:08.289Z',200,25,0,'source_article_available','',NULL,NULL,'body:dd634eb5f60ad0b4f7857073771c0a2de4e1c8a6dd779e8b87d77a6d13dd9835','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b1f131a9-180a-4d8d-aefe-385cdae5aa72','news-b1f131a9-180a-4d8d-aefe-385cdae5aa72','حورية الشمراني.. صفقة دفاعية جديدة لفارسات القادسية  قادمةً من النادي الأهلي','حوريه الشمراني صفقه دفاعيه جديده لفارسات القادسيه قادمه من النادي الاهلي','وتمتلك الشمراني سجلاً حافلاً بالإنجازات خلال مسيرتها مع النادي الأهلي الذي مثّلته من عام 2022 حتى 2026، إذ توّجت معه بكأس الاتحاد السعودي للسيدات في موسميّ 2023/2024 و2024/2025، فضلاً عن تحقيق وصافة الدوري السعودي الممتاز للسيدات في ثلاثة مواسم متتالية، ووصافة كأس السوبر السعودي للسيدات في موسم 2025/2026.','["أتمّ نادي القادسية إجراءات التعاقد مع المدافعة السعودية حورية الشمراني، القادمة من النادي الأهلي، لتنضم إلى الفريق الأول لكرة القدم للسيدات بعقد لموسم رياضي واحد، في إطار تعزيز الخط الدفاعي استعداداً للموسم الرياضي الجديد.","وعلى الصعيد الدولي، مثّلت الشمراني المنتخب السعودي الأول للسيدات في عدد من المحافل الدولية، لتُضيف إلى رصيدها المحلي تجربة دولية تُعزز حضورها بوصفها إحدى العناصر الدفاعية الوطنية المميزة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/qm38f_l','https://sabq.org/article/qm38f_l','','https://sabq.org/article/qm38f_l','صحيفة سبق','الرياض','2026-09-05T12:42:00.000Z','2026-09-05T15:42:00.000Z','2026-09-05T18:50:07.512Z','https://media.sabq.org/news/2026/09/a2d871cc-5175-4db0-802d-b82f5d8be8c8/w1600.webp','/api/media/b1f131a9-180a-4d8d-aefe-385cdae5aa72','/api/media/b1f131a9-180a-4d8d-aefe-385cdae5aa72?variant=thumbnail','حورية الشمراني.. صفقة دفاعية جديدة لفارسات القادسية  قادمةً من النادي الأهلي',1600,1410,'valid','published','archived','valid',99,'8b5c05e8805cde0f8d6c60129686c58f43345a094505cc7c187a85a7502c96ae','3b7b106a7015d7760ce293e2013e23bc32f66487169fcac16a19443b80960c20','محدّث','2026-09-05T18:50:07.512Z','2026-10-07T19:34:58.375Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T19:34:58.375Z',200,23,0,'source_article_available','',NULL,NULL,'body:1738bea2018cb9583c27b0e159b9eac25f63ca21eb105e1b43bbc58bf9adfb62','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ac8a5e11-e845-4094-8a0a-ae7de97356e9','news-ac8a5e11-e845-4094-8a0a-ae7de97356e9','السلطان: التواصل الفعال يبدأ من فهم أهداف المنظمة','السلطان التواصل الفعال يبدا من فهم اهداف المنظمه','وقال "السلطان" خلال الحفل إن فكرة الكتاب جاءت استجابة للحاجة إلى مراجع عربية متخصصة في التواصل الاستراتيجي، وسعيا إلى نقل الخبرات والتجارب المهنية إلى الأجيال الجديدة من العاملين والمهتمين بمجالات الإعلام والتواصل.','["استضافت ديوانية القلم الذهبي ب الرياض ، اليوم، حفل توقيع كتاب «التواصل الاستراتيجي.. دليلك العملي من النظرية إلى التطبيق» للكاتب وخبير التواصل الاستراتيجي عبدالرحمن بن سلطان السلطان، بحضور عدد من المهتمين بالإعلام والتواصل.","وأوضح أن التواصل لم يعد وظيفة ثانوية داخل المؤسسات، وإنما أصبح عنصرا أساسيا ومحوريا في عمل الأفراد والمنظمات، مشيرا إلى أن مفهوم «التواصل الاستراتيجي» يرتقي بالوظيفة الاتصالية لتصبح مرتبطة بالأهداف العليا للمنظمة وتسهم في تحقيقها.","وأكد أهمية مواكبة التطورات المتسارعة في مجال التواصل من خلال التدريب المستمر ونقل المعرفة، لافتا إلى مسؤولية أصحاب الخبرات في توثيق تجاربهم ومشاركتها مع الزملاء والأجيال المقبلة، بما يسهم في تراكم المعرفة المهنية وتطوير الممارسة.","وأشار إلى وجود فجوة لمسها خلال تعامله مع متدربين من جامعات مختلفة بين ما يقدم في الجانب الأكاديمي ومتطلبات العمل الاتصالي اليومي، موضحا أن الكتاب جاء محاولة للإسهام في تقليص هذه الفجوة، عبر تقديم المعرفة بصورة مختصرة وعملية بعيدا عن الإفراط في التنظير.","وبين أن فكرة الكتاب تقوم على تبسيط موضوعات التواصل وتلخيصها في مساحات محدودة وسهلة القراءة، مستفيدا من تجربة المقالات التي تراوح حجمها بين 400 و500 كلمة، بما يساعد القارئ على الانتقال من المفاهيم النظرية إلى التطبيق في بيئة العمل.","واستعرض \"السلطان\" مسيرته المهنية التي تمتد لأكثر من 25 عاما في مجال التواصل في القطاعات الحكومي والخاص وغير الربحي، موضحا أن فكرة الكتاب انطلقت من محاضرات ومقالات كتبها في صحيفة «الرياض»، قبل أن تتطور إلى عمل يجمع بين الخبرة المهنية والمعرفة الأكاديمية.","وأشار إلى أن الكتاب يعتمد لغة بسيطة ومباشرة، ويستعين بقصص وتجارب واقعية للنجاح والإخفاق، إلى جانب إحصاءات حديثة، بهدف تقديم محتوى عملي يساعد المختصين والمهتمين على تطبيق مفاهيم التواصل الاستراتيجي."]','التعليم','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/9fsrmfbr5','https://ajel.sa/local/9fsrmfbr5','https://ajel.sa/local/9fsrmfbr5','https://ajel.sa/local/9fsrmfbr5','فريق التحرير','الرياض','2026-09-05T12:50:00.000Z','Wed, 07 Oct 2026 19:51:09 GMT','2026-09-05T19:08:06.834Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/3b711a1f-36f7-4e09-b4df-45d262a95ba2-vmQL9CyH.jpg','/api/media/ac8a5e11-e845-4094-8a0a-ae7de97356e9','/api/media/ac8a5e11-e845-4094-8a0a-ae7de97356e9?variant=thumbnail','عبدالرحمن بن سلطان السلطان',1200,675,'valid','published','archived','valid',44,'f8c63e622f2ffea2fdaa43e5b308e3637e5df11e7566139036afb3bba342d27b','7924bae7f3d7105008294fb67bfda133f9f87218edc63dc956abb088769355f3','محدّث','2026-09-05T19:08:06.834Z','2026-10-07T20:25:22.790Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس إدارة الهيئة العامة","مجلس إدارة الهيئة العامة للترفيه","الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","الرياض"]','["رئيس مجلس إدارة الهيئة العامة","مجلس إدارة الهيئة العامة للترفيه","الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":3},{"category":"البيئة والمناخ","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:51:11.249Z',200,40,0,'source_content_changed','',NULL,NULL,'body:7de42f6b02d3af2d2ad5784d2d7cce16318821ec3b5e902a212a8be11805d127','Wed, 07 Oct 2026 19:51:09 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dd0d029c-bce8-4549-88bd-e0fb6a32b7f5','news-dd0d029c-bce8-4549-88bd-e0fb6a32b7f5','الأخضر تحت 20 عامًا يختتم تصفيات كأس آسيا بمواجهة قطر','الاخضر تحت 20 عاما يختتم تصفيات كاس اسيا بمواجهه قطر','يخوض المنتخب السعودي تحت 20 عامًا مباراته في الجولة الثالثة من التصفيات المؤهلة لكأس آسيا تحت 20 عامًا 2027، وذلك مساء الأحد في تمام السابعة على استاد عبدالله بن خليفة في العاصمة الدوحة، ضيفًا على نظيره القطري.','["وعلى الصعيد التحضيري، أجرى لاعبو الأخضر حصتهم التدريبية مساء السبت تحت إشراف المدرب الإسباني سيرجيو بيرناس والجهاز الفني المساعد، اشتملت على تمارين تكتيكية أعقبها العمل على الكرات الثابتة.","ويخوض المنتخب السعودي تحت 20 عامًا منافسات المجموعة الخامسة في هذه التصفيات، إلى جانب منتخبات قطر وعُمان وهونغ كونغ."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/cxB3EUv','https://sabq.org/article/cxB3EUv','','https://sabq.org/article/cxB3EUv','صحيفة سبق','','2026-09-05T13:11:00.000Z','2026-09-05T16:11:00.000Z','2026-09-05T19:17:07.616Z','https://media.sabq.org/news/2026/09/f69b2148-19df-4baf-9b95-a9b807b8cc4d/w1280.webp','/api/media/dd0d029c-bce8-4549-88bd-e0fb6a32b7f5','/api/media/dd0d029c-bce8-4549-88bd-e0fb6a32b7f5?variant=thumbnail','الأخضر تحت 20 عامًا يختتم تصفيات كأس آسيا بمواجهة قطر',1280,936,'valid','published','archived','valid',55,'f763ebbb36cdae58238f9ddd9ea472b2ce05232b6a9c4b811786deab50bed253','aef43d3f2e25e574d0001d8d345a5c80c23b0f3f0b015b4be1adedea92003e7e','محدّث','2026-09-05T19:17:07.616Z','2026-10-07T19:51:28.680Z','','',0,0,'gulf_arab','عادي',46,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T19:51:28.680Z',200,19,0,'source_article_available','',NULL,NULL,'body:d2ab3864ddcf04afee8755dce83d056facad6cfe923bb3566ba7ef39ceec9a5e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c57b934d-5aa4-4b0d-a538-0a4db930cb0b','news-c57b934d-5aa4-4b0d-a538-0a4db930cb0b','محمية الإمام تركي بن عبدالله الملكية تحتضن تنوعًا بيئيًا فريدًا شمال شرق المملكة','محميه الامام تركي بن عبدالله الملكيه تحتضن تنوعا بيئيا فريدا شمال شرق المملكه','تمتد محمية الإمام تركي بن عبدالله الملكية شمال شرق المملكة العربية السعودية على مساحة 91,500 كيلومتر مربع، ما يجعلها ثاني أكبر المحميات الملكية في المملكة.','["تمتد محمية الإمام تركي بن عبدالله الملكية شمال شرق المملكة العربية السعودية على مساحة 91,500 كيلومتر مربع، ما يجعلها ثاني أكبر المحميات الملكية في المملكة. وتتميز المحمية بتنوع تضاريسها، من الكثبان الرملية والسهول والجبال والهضاب والسهوب، إلى الأودية والفياض، ما يعزز ثراءها النباتي وتنوع الحياة الفطرية فيها.","وتستحوذ الكثبان الرملية على المساحة الأكبر من المحمية، وتحتضن نباتات صحراوية مثل الغضا والأرطى والعرفج والعوسج، بينما توفر الأودية والمجاري المائية الموسمية بيئات مناسبة لنمو النباتات الخشبية. وتعد الفياض منخفضات طبيعية تتجمع فيها مياه الأمطار والجريان السطحي خلال المواسم الرطبة، فتسهم في إثراء الغطاء النباتي للمحمية.","يضم الغطاء النباتي للمحمية مئات الأنواع التي تنتمي إلى عشرات العوائل النباتية، من أبرزها الطلح والسدر والأرطى والغضا والعرفج والعوسج. ويرتبط هذا التنوع بتباين التضاريس واختلاف الظروف البيئية والمناخية ضمن نطاق المحمية الواسع.","وتوفر البيئات المتنوعة داخل المحمية موائل متعددة للحياة الفطرية، تشمل مئات الأنواع من الثدييات والطيور والزواحف، إلى جانب أنواع عديدة من اللافقاريات، ما يعكس أهمية المحمية في صون التنوع الأحيائي والمحافظة على التوازن الطبيعي للأنظمة البيئية.","تعمل هيئة تطوير محمية الإمام تركي بن عبدالله الملكية على حماية هذا التنوع وتنميته عبر برامج لاستعادة الموائل الطبيعية، وتنمية الغطاء النباتي، وإعادة توطين الأنواع النباتية والحيوانية. كما تنظم الهيئة الأنشطة البشرية داخل المحمية للحد من تأثيراتها على البيئة وضمان استدامة الموارد الطبيعية.","ويشمل ذلك تنظيم الرعي ضمن منظومة الإدارة البيئية، من خلال تطبيق ضوابط تراعي حالة المراعي وقدرتها الاستيعابية، بما يدعم تجدد الغطاء النباتي ويحقق التوازن بين الاستفادة من الموارد الطبيعية والمحافظة عليها.","وتبرز المحمية، بما تمتلكه من اتساع جغرافي وتنوع تضاريسي وثراء أحيائي، كنموذج متقدم لإدارة النظم الطبيعية على نطاق واسع. كما تدعم مكوناتها البيئية جهود استعادة الموائل وتعزيز الحياة الفطرية، وتوفر فرصًا واعدة للبحث البيئي وتنمية السياحة البيئية المستدامة."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/mhwv1drqy','https://ajel.sa/local/mhwv1drqy','https://ajel.sa/local/mhwv1drqy','https://ajel.sa/local/mhwv1drqy','فريق التحرير','','2026-09-05T13:17:00.000Z','Wed, 07 Oct 2026 19:52:48 GMT','2026-09-05T19:22:40.523Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-09/source-Zk_L8Ed3.jpg','/api/media/c57b934d-5aa4-4b0d-a538-0a4db930cb0b','/api/media/c57b934d-5aa4-4b0d-a538-0a4db930cb0b?variant=thumbnail','محمية الإمام تركي بن عبدالله الملكية تحتضن تنوعًا بيئيًا فريدًا شمال شرق المملكة',1200,675,'valid','published','archived','valid',49,'65e94b86d0d0f8635c752b8bd1ca1de9c84aa9c9c66c7b274e598256848fdcf2','0b611885b6aa826cd4dec81f850c3894ae6394d57a625ba50d126269250ed576','محدّث','2026-09-05T19:22:40.523Z','2026-10-07T19:52:50.540Z','','',0,0,'saudi_national','أولوية قصوى',82,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة تطوير محمية الإمام تركي","الطقس والمناخ","السفر والسياحة"]','["هيئة تطوير محمية الإمام تركي","الطقس والمناخ","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"البيئة والمناخ","score":4.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:52:50.540Z',200,29,0,'source_content_changed','',NULL,NULL,'body:e7a053c3aad7cc1e10acba0f8a38c835f32245d0296fdf4b1a3816d703879c84','Wed, 07 Oct 2026 19:52:48 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2903e75d-8dd1-479b-89da-9a62027b10d6','news-2903e75d-8dd1-479b-89da-9a62027b10d6','وكيل وزارة الاستثمار: الصين شريك استثماري إستراتيجي والمملكة تركز على بناء الصناعات المشتركة','وكيل وزاره الاستثمار الصين شريك استثماري استراتيجي والمملكه تركز علي بناء الصناعات المشتركه','استعرض وكيل وزارة الاستثمار التحولات الاقتصادية التي شهدتها المملكة منذ إطلاق رؤية السعودية 2030، حيث تضاعف حجم الاقتصاد السعودي خلال العقد الماضي، كما تضاعف الاستثمار المحلي وارتفعت مساهمة القطاع الخاص إلى الضعف.','["شارك وكيل وزارة الاستثمار للشؤون الاقتصادية ودراسات الاستثمار الدكتور سعد الشهراني في جلسة الحوار الإستراتيجي الاستثماري بين المملكة العربية السعودية و جمهورية الصين الشعبية ، وذلك ضمن ملتقى الأسواق المالية سيليكت في شنغهاي الذي تنظمه تداول السعودية .","وأوضح الدكتور الشهراني أن الصين تمثل شريكًا استثماريًا إستراتيجيًا للمملكة، مشيرًا إلى أن المرحلة المقبلة ستشهد تعميق الاستثمارات المتبادلة وتعزيز الشراكات الصناعية، إلى جانب بناء سلاسل قيمة تخدم أسواق المملكة والمنطقة والعالم.","ودعا الشهراني الشركات الصينية للاستفادة من الفرص التي توفرها المملكة والمساهمة في بناء الجيل القادم من الصناعات، مبينًا أن الشراكة الاستثمارية السعودية - الصينية ستركز على الاستثمار والبناء والابتكار والنمو المشترك، مؤكدًا أن المملكة تجمع بين الاستقرار والفرص والنمو.","وأشار الشهراني إلى تضاعف رصيد الاستثمار الأجنبي المباشر في المملكة وارتفاع تدفقاته بنحو خمسة أضعاف، وزيادة عدد الشركات الأجنبية العاملة بأكثر من عشرة أضعاف. كما تضاعفت مشاركة المرأة في سوق العمل وانخفض معدل البطالة بين المواطنين السعوديين بنسبة 50٪.","أوضح الشهراني أن الاستثمار المحلي غير النفطي أصبح يمثل نحو 40٪ من الناتج المحلي الإجمالي غير النفطي، ما يضع المملكة في المرتبة الثانية بين دول مجموعة العشرين بعد الصين. كما تجاوزت الاستراتيجية الوطنية للاستثمار مستهدفاتها السنوية، ودخلت المملكة قائمة أفضل عشر دول عالميًا في مؤشر ثقة الاستثمار الأجنبي المباشر.","وأضاف أن ثقة المستثمرين تظهر في توسع الأعمال وإعادة الاستثمار والالتزامات طويلة الأجل، مشددًا على أن المملكة تخلق الفرص الاستثمارية ولا تنتظرها.","وبيّن أن رؤية السعودية 2030 أسهمت في إيجاد قطاعات جديدة في السياحة والتعدين والتصنيع والخدمات اللوجستية والتقنية والاقتصاد الرقمي، لتتحول الاستثمارات إلى أحد محركات النمو الرئيسة."]','الاقتصاد','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/jb2kr3ldn','https://ajel.sa/local/jb2kr3ldn','https://ajel.sa/local/jb2kr3ldn','https://ajel.sa/local/jb2kr3ldn','فريق التحرير','','2026-09-05T13:17:00.000Z','Wed, 07 Oct 2026 19:53:03 GMT','2026-09-05T19:22:41.394Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-09/source-TMqiI2Ry.jpg','/api/media/2903e75d-8dd1-479b-89da-9a62027b10d6','/api/media/2903e75d-8dd1-479b-89da-9a62027b10d6?variant=thumbnail','وكيل وزارة الاستثمار: الصين شريك استثماري إستراتيجي والمملكة تركز على بناء الصناعات المشتركة',1200,675,'valid','published','archived','valid',53,'0744ad5e4cb541e6f63f5a93a2ddf3a90acb30b6f62c5acdd3684077df922c4b','4744e2d8b3752938ff9b7ed264e6a30499e3d3427a347de32c56515b601b2d8c','محدّث','2026-09-05T19:22:41.394Z','2026-10-07T20:25:22.790Z','','',0,0,'saudi_national','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","وزارة الاستثمار الصين شريك استثماري","الطاقة والنفط","السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي","الصين"]','["وزارة الاستثمار الصين شريك استثماري","الطاقة والنفط","السفر والسياحة","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":4.5},{"category":"الطاقة والصناعة","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:53:05.875Z',200,29,0,'source_content_changed','',NULL,NULL,'body:1d0c82678e162040cb7549ed3756d1b298e1783b61b256b713387490b29c848f','Wed, 07 Oct 2026 19:53:03 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4a060b5b-8470-4f87-9d60-1ab8a593fa7c','news-4a060b5b-8470-4f87-9d60-1ab8a593fa7c','الجزائر تعلن وفاة الطفل أيوب بعد سقوطه قبل 4 أيام فى بئر.. وانتشال الجثمان','الجزائر تعلن وفاه الطفل ايوب بعد سقوطه قبل 4 ايام في بئر وانتشال الجثمان','أعلنت الجزائر ، وفاة الطفل أيوب، وانتشال جثمانه، اليوم، بعد سقوطه قبل 4 أيام، في بئر ارتوازية بقرية الركنة ببلدية غسول بولاية البيض ، جنوبي غرب البلاد.','["وأفادت الحماية المدنية الجزائرية، في بيان: \"تبعاً لعملية إنقاذ طفل سقط في بئر ارتوازية جافة بالمكان المسمى قرية الركنة بلدية غسول بولاية البيض. حالياً، تم العثور على مكان الطفل وانتشاله متوفى\".","وتابعت: \"لقد سخرت الحماية المدنية، رفقة السلطات المحلية وكال الهيئات والخواص، كافة الإمكانيات البشرية والمادية لهذه العملية\".","كان الطفل أيوب البالغ من العمر 10 سنوات، سقط الأربعاء، داخل بئر جافة يبلغ عمقها نحو 80 متراً، فيما لا يتجاوز قطرها 40 سنتيمتراً، ما جعل مهمة الوصول إليه بالغة الصعوبة.","ووفق \"الشرق\"، تحدث محمد هادف، والد الطفل أيوب، في وقت سابق عن تفاصيل الحادث قائلاً إنه سقط داخل البئر بعدما داس على قطعة خشب مهترئة كانت تغطي البئر.","وأضاف: \"عندما وصلت إليه وبدأت أنادي أيوب أيوب، رد عليّ: بابا أخرجني، وبدأ يبكي فقلت له لا تبكي، ستأتي الحماية المدنية وتخرجك\"، مشيرا إلى أن عناصر الحماية المدنية بدأت في الحفر، فيما كانوا يواصلون الحديث معه.","وواجهت مهمة الإنقاذ صعوبات كبيرة بسبب طبيعة التربة في المنطقة، ما فرض على فرق الإنقاذ العمل بحذر شديد."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/4bkyemuqw','https://ajel.sa/international/4bkyemuqw','https://ajel.sa/international/4bkyemuqw','https://ajel.sa/international/4bkyemuqw','فريق التحرير','','2026-09-05T13:00:00.000Z','Wed, 07 Oct 2026 19:52:47 GMT','2026-09-05T19:22:43.162Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-C9Hwipc0.jpg','/api/media/4a060b5b-8470-4f87-9d60-1ab8a593fa7c','/api/media/4a060b5b-8470-4f87-9d60-1ab8a593fa7c?variant=thumbnail','الجزائر تعلن وفاة الطفل أيوب بعد سقوطه قبل 4 أيام فى بئر.. وانتشال الجثمان',1200,675,'valid','published','archived','valid',41,'49b454ba551711eeaf2b20078efa6955c3738e41626f180c8fa54662cf5ff84a','3ec3f1ed0909f4ae8327c15aa7e87ec5c3beaa2e0eefa0fc4fb41a36aea7672a','محدّث','2026-09-05T19:22:43.162Z','2026-10-07T20:25:22.790Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:52:49.373Z',200,29,0,'source_content_changed','',NULL,NULL,'body:cbf23192197c4ab9c7246a4430f28f4358f840e163e6e5a0ab5f29edcee11f74','Wed, 07 Oct 2026 19:52:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d1a6ab4d-8a30-45d4-8c6f-d83d3a7605da','news-d1a6ab4d-8a30-45d4-8c6f-d83d3a7605da','حرس الحدود يختتم معرض وطن بلا مخالف في المنطقة الشرقية','حرس الحدود يختتم معرض وطن بلا مخالف في المنطقه الشرقيه','ودعا حرس الحدود إلى التعاون مع الجهات الأمنية والإبلاغ عن مخالفي نظام أمن الحدود عبر أرقام الطوارئ (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض والمنطقة الشرقية، و(994) و(999) في بقية مناطق المملكة.','["اختتمت المديرية العامة لحرس الحدود ب المنطقة الشرقية معرضها التوعوي \"وطن بلا مخالف\"، الذي أقيم في نادي وزارة الداخلية بالمنطقة الشرقية، بهدف استعراض جهود وزارة الداخلية وقطاعاتها الأمنية في ضبط مخالفي نظام أمن الحدود.","واستعرض المعرض العقوبات المترتبة على من يسهل دخول المخالفين أو نقلهم داخل المملكة ، أو يوفر لهم المأوى، أو يقدم لهم أي مساعدة أو خدمة بأي شكل من الأشكال."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/h3tl07gy5','https://ajel.sa/local/h3tl07gy5','https://ajel.sa/local/h3tl07gy5','https://ajel.sa/local/h3tl07gy5','فريق التحرير','الرياض','2026-09-05T13:08:00.000Z','Wed, 07 Oct 2026 19:52:47 GMT','2026-09-05T19:22:43.378Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-09/source-n6AVNVzB.jpg','/api/media/d1a6ab4d-8a30-45d4-8c6f-d83d3a7605da','/api/media/d1a6ab4d-8a30-45d4-8c6f-d83d3a7605da?variant=thumbnail','حرس الحدود يختتم معرض وطن بلا مخالف في المنطقة الشرقية',1200,675,'valid','published','archived','valid',40,'e793b71ec850a8bddf145610d863edcc44f1b3c5498f14262515e98ae6ac1539','675c12a956cee17525b22a74efc5637014e5ee2fbb1e9af3144b31f1b10b2b71','محدّث','2026-09-05T19:22:43.378Z','2026-10-07T19:52:49.444Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية بالمنطقة الشرقية بهدف","الرياضة السعودية","مكة","الرياض","المدينة المنورة"]','["وزارة الداخلية بالمنطقة الشرقية بهدف","الرياضة السعودية","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:52:49.444Z',200,29,0,'source_content_changed','',NULL,NULL,'body:ad5fc1958b8e0c472dc9475d5dec93d895fd96fb3962319e15090a22df77ab0e','Wed, 07 Oct 2026 19:52:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9922c59e-ff3d-42f3-8d2b-827f03b5b992','news-9922c59e-ff3d-42f3-8d2b-827f03b5b992','«العليمي» يحيي انتصارات القوات المسلحة.. ويؤكد التزام الدولة بتحرير كامل أراضيها ودحر الميليشيات','العليمي يحيي انتصارات القوات المسلحه ويؤكد التزام الدوله بتحرير كامل اراضيها ودحر الميليشيات','أشاد رئيس مجلس القيادة الرئاسي اليمني الدكتور رشاد محمد العليمي، القائد الأعلى للقوات المسلحة، بما حققته القوات المسلحة وكافة التشكيلات العسكرية من انتصارات ومكاسب ميدانية خلال الساعات الماضية في جبهتَي تعز والحديدة.','["وأشاد العليمي بوحدات ألوية المقاومة الوطنية والعمالقة والتهامية، التي أتمّت تحرير مديرية حيس بمحافظة الحديدة وتأمينها، فضلاً عن إشادته بأبطال القوات المسلحة في جبهة حيفان، مُثمِّناً الدور الفاعل لسلاح الجو في إسناد القوات البرية والتعامل بكفاءة مع التهديدات المعادية في مختلف مسارح العمليات.","واطّلع القائد الأعلى، خلال اتصالاته بالقادة العسكريين والميدانيين، على مستجدات العمليات والمكاسب المحققة على الأرض، ومستوى الجاهزية القتالية، وإجراءات تثبيت المناطق المحررة وتأمينها، وتطهير المواقع التي تسلّلت إليها المليشيات، موجِّهاً بمواصلة أداء المهام العسكرية بمسؤولية واقتدار، والحفاظ على زمام المبادرة، ورفع مستوى التنسيق بين مختلف الوحدات والتشكيلات.","وقال العليمي إن «المليشيات الحوثية التي اختارت هذه المغامرة ستتحمل كامل عواقبها»، مؤكداً أن تعز «لن تكون ممراً آمناً لمشاريع وأجندة داعميها»، وأن القوات المسلحة التي تصدّت للهجوم وانتزعت المبادرة على الأرض قادرة على استعادة كامل الأراضي ومواصلة واجبها الدستوري في الدفاع عن المواطنين والمصالح العليا للبلاد.","وأضاف: «لقد اختارت المليشيات اختبار الدولة وقواتها المسلحة في واحدة من أكثر جبهات اليمن صلابة، وعليها الآن أن تدرك أن حساباتها الخاطئة ستفتح عليها أبواب السقوط الشامل».","ووجّه القائد الأعلى جميع القادة والوحدات والتشكيلات العسكرية بالالتزام الصارم بأحكام القانون الدولي الإنساني وقواعد الاشتباك، وحماية المدنيين والممتلكات، وتسهيل وصول المساعدات وإغاثة النازحين، وحسن معاملة المحتجزين وصون كرامتهم وحقوقهم، قائلاً: «إن اليد التي تحمل السلاح دفاعاً عن الجمهورية يجب أن تبقى أيضاً يد الدولة وسيادة القانون».","وترحّم العليمي على أرواح شهداء القوات المسلحة، مؤكداً أن تضحياتهم «ستظل محل إجلال ووفاء الدولة والشعب»، وموجِّهاً الجهات المختصة بتوفير الرعاية والعلاج اللازمَين للجرحى، والعناية بأسر الشهداء والوفاء بحقوقهم ومستحقاتهم، «باعتبار ذلك واجباً وطنياً وأخلاقياً لا يقبل التهاون أو التأخير».","وحمّل الرئيس المليشيات الحوثية المسؤولية الكاملة عن الانتهاكات التي رافقت تصعيدها، واستهدافها المناطق السكنية والطرق العامة بالقصف والقنص والطائرات المسيّرة، وما نتج عن ذلك من سقوط ضحايا مدنيين واختطافات ونزوح مئات الأسر، مؤكداً أن «هذه الجرائم لن تسقط بالتقادم».","ودعا العليمي كافة القوى السياسية والاجتماعية ووسائل الإعلام إلى توحيد الصف الوطني وتعزيز الثقة بالقوات المسلحة، وعدم الانجرار وراء حملات التشكيك والتخوين التي «لا تخدم سوى المليشيات الإرهابية»، مؤكداً أن القوات المسلحة «ماضية بثبات نحو الهدف الوطني الجامع في استعادة مؤسسات الدولة، باعتباره خياراً لا رجعة عنه مهما بلغت التضحيات»."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wlzV128','https://sabq.org/article/wlzV128','','https://sabq.org/article/wlzV128','صحيفة سبق','المدينة المنورة','2026-09-05T13:30:00.000Z','2026-09-05T13:31:00.000Z','2026-09-06T06:53:16.396Z','https://media.sabq.org/news/2026/09/44cb9335-6fcd-4b04-b948-4742128f4d01/w250.webp','/api/media/9922c59e-ff3d-42f3-8d2b-827f03b5b992','/api/media/9922c59e-ff3d-42f3-8d2b-827f03b5b992?variant=thumbnail','«العليمي» يحيي انتصارات القوات المسلحة.. ويؤكد التزام الدولة بتحرير كامل أراضيها ودحر الميليشيات',250,215,'valid','published','archived','valid',50,'606a482484dc466c90916a9fc513b2b9eaf0aee0917e37d0f64b2d524b7ca416','4dc144b2716778a0ce67e4a49af7da9549dc1e91729dfefbfca3023ecd279405','محدّث','2026-09-05T19:36:03.631Z','2026-10-07T20:25:22.790Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس القيادة الرئاسي اليمني","مجلس القيادة الرئاسي اليمني الدكتور","الصحة العامة","اليمن"]','["رئيس مجلس القيادة الرئاسي اليمني","مجلس القيادة الرئاسي اليمني الدكتور","الصحة العامة"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:00:55.637Z',200,25,0,'source_article_available','',NULL,NULL,'body:e3db6a6eafab50a3255fc6e861821e208fd386f132167791f1de431e89da0e48','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('00920fbf-c46e-49e3-89f1-4b0ce52ddba6','news-00920fbf-c46e-49e3-89f1-4b0ce52ddba6','السفير الشمري يُقدّم أوراق اعتماده لرئيس رومانيا','السفير الشمري يقدم اوراق اعتماده لرئيس رومانيا','قدَّم سفير خادم الحرمين الشريفين لدى رومانيا خالد بن عيد الشمري، أوراق اعتماده، لفخامة الرئيس نيكوشور دانيال دان، رئيس رومانيا. ونقل السفير الشمري لفخامته، تحيات خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، وصاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء -حفظهما الله-.','["قدَّم سفير خادم الحرمين الشريفين لدى رومانيا خالد بن عيد الشمري، أوراق اعتماده، لفخامة الرئيس نيكوشور دانيال دان، رئيس رومانيا.","ونقل السفير الشمري لفخامته، تحيات خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، وصاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء -حفظهما الله-.","فيما حمَّله فخامته، تحياته لخادم الحرمين الشريفين ولسمو ولي العهد، معبرًا عن تقديره للمملكة حكومة وشعبًا، وتطلع بلاده إلى العمل المشترك وتعزيز التعاون في مختلف المجالات."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/cthqyp3mx','https://ajel.sa/local/cthqyp3mx','https://ajel.sa/local/cthqyp3mx','https://ajel.sa/local/cthqyp3mx','فريق التحرير','','2026-09-05T13:34:00.000Z','Wed, 07 Oct 2026 21:01:56 GMT','2026-09-05T19:55:03.144Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-JEVjlc2W.jpg','/api/media/00920fbf-c46e-49e3-89f1-4b0ce52ddba6','/api/media/00920fbf-c46e-49e3-89f1-4b0ce52ddba6?variant=thumbnail','السفير الشمري يُقدّم أوراق اعتماده لرئيس رومانيا',1200,675,'valid','published','archived','valid',99,'99d63075efd3c4bca2646a439048bc9f6caed64f63707d104d725eabbc161b88','9428d0c6288be6ea4b3651895bc52dea791b5f0689715c2d0b99e80a59eab058','محدّث','2026-09-05T19:55:03.144Z','2026-10-07T21:01:58.563Z','','',0,0,'saudi_national','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء -حفظهما الله- فيما","رئيس رومانيا ونقل السفير الشمري","خادم الحرمين الشريفين لدى رومانيا"]','["ولي العهد رئيس مجلس الوزراء","مجلس الوزراء -حفظهما الله- فيما","رئيس رومانيا ونقل السفير الشمري","خادم الحرمين الشريفين لدى رومانيا"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:01:58.563Z',200,23,0,'source_content_changed','',NULL,NULL,'body:ef2637e466a1a4f2a1d132d23662a868d6c3f6d378d4b8ce5b3dd50c89e91af1','Wed, 07 Oct 2026 21:01:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6c393a54-85dc-4861-8343-42149d992a5c','news-6c393a54-85dc-4861-8343-42149d992a5c','الزكري: المملكة قدّمت نموذجاً متقدماً في تنظيم العمل الخيري وتعزيز حوكمته','الزكري المملكه قدمت نموذجا متقدما في تنظيم العمل الخيري وتعزيز حوكمته','أكد رئيس مجلس الجمعيات الأهلية بمنطقة الرياض عبدالعزيز بن محمد الزكري، أن اليوم العالمي للعمل الخيري يمثّل مناسبة لإبراز ما حققته المملكة العربية السعودية من تطور نوعي في منظومة العمل الخيري، في ظل الدعم والاهتمام الذي يحظى به القطاع غير الربحي من القيادة الرشيدة، مما عزّز دوره شريكاً فاعلاً في التنمية الوطنية.','["وقال الزكري إن المملكة قدّمت نموذجاً متقدماً في تنظيم العمل الخيري وتعزيز حوكمته وكفاءته وموثوقيته، إذ انتقل من نطاق المساعدات المباشرة إلى مسارات أوسع تقوم على التنمية والتمكين والاستدامة وصناعة الأثر، بما ينسجم مع مستهدفات رؤية 2030 الرامية إلى تنمية القطاع غير الربحي وتعظيم أثره الاجتماعي والاقتصادي.","وأضاف أن التطور الذي تشهده الجمعيات الأهلية، وتنامي شراكاتها مع القطاعين الحكومي والخاص، يعكسان حجم التحول في العمل المؤسسي، وأهمية التكامل بين مختلف القطاعات لتقديم مبادرات وبرامج أكثر استدامة واستجابة لاحتياجات المجتمع.","واختتم الزكري بالتأكيد على أن اليوم العالمي للعمل الخيري فرصة لتجديد المسؤولية تجاه تطوير هذا القطاع، وتعزيز الشراكات والابتكار في برامجه ومبادراته، وتحويل العطاء إلى أثر تنموي مستدام يسهم في تحسين جودة الحياة وتحقيق مستهدفات الوطن."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/iVm4j4A','https://sabq.org/article/iVm4j4A','','https://sabq.org/article/iVm4j4A','صحيفة سبق','الرياض','2026-09-05T13:45:00.000Z','2026-09-05T16:45:00.000Z','2026-09-05T19:55:04.165Z','https://media.sabq.org/news/2026/09/d05c153b-17d9-4680-aeab-b5582b605419/w603.webp','/api/media/6c393a54-85dc-4861-8343-42149d992a5c','/api/media/6c393a54-85dc-4861-8343-42149d992a5c?variant=thumbnail','الزكري: المملكة قدّمت نموذجاً متقدماً في تنظيم العمل الخيري وتعزيز حوكمته',603,783,'valid','published','archived','valid',62,'e48b32054a4801592afc467dc24e2fe91de663b183613727209909d67cd49072','d51dd32d029c15de6b18038110edad7498c6ae6b94fc81b7735a308a8890cd27','محدّث','2026-09-05T19:55:04.165Z','2026-10-07T21:01:55.695Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس الجمعيات الأهلية بمنطقة","مجلس الجمعيات الأهلية بمنطقة الرياض","الاقتصاد والأسواق","الرياض"]','["رئيس مجلس الجمعيات الأهلية بمنطقة","مجلس الجمعيات الأهلية بمنطقة الرياض","الاقتصاد والأسواق"]','needs_review','ambiguous_category','[{"category":"المجتمع","score":7},{"category":"المناطق","score":1.5},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:01:55.695Z',200,25,0,'source_article_available','',NULL,NULL,'body:a95689c0b75ad1f5f258995325507086c28adfabf361a2a7e82ee9b74ae7d6e6','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e044353e-f444-457d-96b7-85c0c89acaaa','news-e044353e-f444-457d-96b7-85c0c89acaaa','«من القصيم إلى العالم».. كرنفال بريدة الدولي للتمور يبرز تنوع أشهر أصناف التمور','من القصيم الي العالم كرنفال بريده الدولي للتمور يبرز تنوع اشهر اصناف التمور','ويأتي الكرنفال بوصفه نافذة للتعريف بتمور القصيم وإبراز تنوعها وجودتها، إلى جانب تعزيز حضورها لدى المستهلكين والمهتمين، ودعم فرص تسويقها والوصول بها إلى نطاق أوسع من القصيم إلى العالم.','["يواصل كرنفال بريدة الدولي للتمور تقديم صورة واسعة عن ما تزخر به منطقة القصيم من أصناف متنوعة من التمور، في رسالة تؤكد حضور هذا المنتج الزراعي البارز من القصيم إلى العالم، بما يعكس المكانة التي تحتلها المنطقة في إنتاج وتسويق التمور.","ويستعرض الكرنفال عددًا من الأصناف المعروفة التي تشتهر بها المنطقة، من بينها السكري، والصقعي، وخلاص القصيم، وتمر البرحي، والبرحي الرطب، والمجدول، والرشودية، وهي أصناف تتنوع في أشكالها ومذاقها ودرجات نضجها، بما يعكس ثراء منتجات النخيل في القصيم.","ويعكس الكرنفال ما يحظى به قطاع التمور في منطقة القصيم من اهتمام متواصل، ودوره في دعم المزارعين والمنتجين وتعزيز تسويق التمور، بما يسهم في إبراز جودة المنتج المحلي وتنوع أصنافه، وتعزيز حضوره في الأسواق المحلية والخارجية."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/ci9rif736','https://ajel.sa/local/ci9rif736','https://ajel.sa/local/ci9rif736','https://ajel.sa/local/ci9rif736','ماجد الفريدي','القصيم','2026-09-05T13:52:00.000Z','Wed, 07 Oct 2026 21:18:42 GMT','2026-09-05T20:07:03.396Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-zkQuIlP1.jpg','/api/media/e044353e-f444-457d-96b7-85c0c89acaaa','/api/media/e044353e-f444-457d-96b7-85c0c89acaaa?variant=thumbnail','«من القصيم إلى العالم».. كرنفال بريدة الدولي للتمور يبرز تنوع أشهر أصناف التمور',1200,675,'valid','published','archived','valid',41,'b81c6e28bad5b6bab6235fb58880b7c03b82a5dc7766bc028a1f27986465d465','3bc97e197641a9c9e823d1a028dd1dffb3c252be265afdf9bdab55da495e35d5','محدّث','2026-09-05T20:07:03.396Z','2026-10-07T21:18:43.882Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["القصيم"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T21:18:43.882Z',200,20,0,'source_article_available','',NULL,NULL,'body:41003aa252481fb0dadd07a454b4dee8cfe48b525debc2b049a6868731d2bc0c','Wed, 07 Oct 2026 21:18:42 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b59cb23e-ef52-448e-b0fa-28496d7952a8','news-b59cb23e-ef52-448e-b0fa-28496d7952a8','حرس الحدود يحبط تهريب حشيش وقات ويضبط 45 ألف قرص في عسير','حرس الحدود يحبط تهريب حشيش وقات ويضبط 45 الف قرص في عسير','وفي عملية أخرى بقطاع الربوعة، ألقت الدوريات البرية القبض على 4 مخالفين لنظام أمن الحدود من الجنسية الإثيوبية، بعد تورطهم في تهريب 80 كيلوجرامًا من نبات القات المخدر.','["ضبطت الدوريات البرية التابعة للمديرية العامة لحرس الحدود في قطاع الربوعة ب منطقة عسير كميات من المخدرات والأقراص الخاضعة لتنظيم التداول الطبي، في عمليتين ميدانيتين أسفرتا عن إحباط تهريب 45 ألف قرص و37 كيلوغرامًا من الحشيش المخدر، إلى جانب ضبط 80 كيلوجرامًا من نبات القات المخدر والقبض على 4 مخالفين لنظام أمن الحدود.","وفي العملية الأولى، أحبطت الدوريات محاولة تهريب شحنة تضمنت 45 ألف قرص خاضعًا لتنظيم التداول الطبي و37 كيلوغرامًا من مادة الحشيش المخدر، ضمن العمليات الميدانية الاستباقية لتأمين الحدود الجنوبية للمملكة.","وأكدت الجهات الأمنية استكمال الإجراءات النظامية الأولية المتعلقة بواقعة الضبط، وتسليم المضبوطات المحرزة إلى جهة الاختصاص لمتابعة التحقيقات الجنائية.","وجرى استكمال الإجراءات النظامية الأولية بحق المقبوض عليهم في الواقعة الثانية، وتسليمهم والمضبوطات إلى جهة الاختصاص.","وتهيب الجهات الأمنية بالمواطنين والمقيمين الإبلاغ عن أي معلومات تتوافر لديهم بشأن أنشطة مرتبطة بتهريب أو ترويج المخدرات، عبر الاتصال بالرقم (911) في مناطق مكة المكرمة والمدينة المنورة و الرياض و المنطقة الشرقية ، والرقمين (999) و(994) في بقية مناطق المملكة.","كما يمكن تقديم البلاغات إلى المديرية العامة لمكافحة المخدرات عبر الرقم (995)، أو من خلال البريد الإلكتروني ( [email&#160;protected] )، مؤكدة أن جميع البلاغات ستُعالج بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/wv6454tvk','https://ajel.sa/local/wv6454tvk','https://ajel.sa/local/wv6454tvk','https://ajel.sa/local/wv6454tvk','فريق التحرير','الرياض','2026-09-05T13:52:00.000Z','Wed, 07 Oct 2026 21:18:40 GMT','2026-09-05T20:07:03.745Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/2-crop-hMymn6dh.jpg','/api/media/b59cb23e-ef52-448e-b0fa-28496d7952a8','/api/media/b59cb23e-ef52-448e-b0fa-28496d7952a8?variant=thumbnail','حرس الحدود',1200,675,'valid','published','archived','valid',40,'cd5fc17956be74eb74e3ef403b931743adf3bd6156e5743634f43077debd812c','9b4be3136d3e6f4c527832baefd376f98157fd9626362e03095304007d3ba3f8','محدّث','2026-09-05T20:07:03.745Z','2026-10-07T21:18:42.424Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الرياضة السعودية","التقنية والتحول الرقمي","مكة","عسير","الرياض","المدينة المنورة"]','["السفر والسياحة","الرياضة السعودية","التقنية والتحول الرقمي","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:18:42.424Z',200,22,0,'source_content_changed','',NULL,NULL,'body:0d3e6479d373adf04a27e727cbd86f777bc2358912fcffa583e013e1699930d2','Wed, 07 Oct 2026 21:18:40 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b346c0ae-4d8b-424c-b1b9-9fecfd520771','news-b346c0ae-4d8b-424c-b1b9-9fecfd520771','مقر خاتم الأنبياء الإيراني: الضربات ضد السفن الحربية الأمريكية ستكون أشدّ','مقر خاتم الانبياء الايراني الضربات ضد السفن الحربيه الامريكيه ستكون اشد','أعلن مقر خاتم الأنبياء الإيراني، اليوم السبت، أن الضربات الإيرانية على السفن الأمريكية ستكون أشد إذا واصلت واشنطن أعمالها العدائية والحصار. كانت القيادة المركزية الأمريكية "سنتكوم"، قالت اليوم، إنها دمرت 3 ناقلات نفط تابعة للحرس الثوري الإيراني بعد استهداف إيران سفينتين حربيتين تابعتين للبحرية الأمريكية.','["أعلن مقر خاتم الأنبياء الإيراني، اليوم السبت، أن الضربات الإيرانية على السفن الأمريكية ستكون أشد إذا واصلت واشنطن أعمالها العدائية والحصار.","وقال المتحدث باسم المقر إبراهيم ذو الفقاري ، في بيان، وفق وكالة \"تسنيم\"، إنه \"في حال استمرار أعماله العدائية، والتسبب في انعدام الأمن والمضايقة للسفن الإيرانية، وفرض حصار بحري على إيران ، فإن ضربات القوات المسلحة للجمهورية الإسلامية الإيرانية ضد السفن الحربية الأمريكية في المنطقة ستكون أشد من ذي قبل، وهناك إمكانية لتوسّعها أيضًا\".","ويأتي ذلك في وقت قال فيه وزير الحرب الأمريكي، بيت هيغسيث، مساء اليوم، إن الولايات المتحدة ستدمر ناقلات النفط الإيرانية وتغرقها في حال أطلقت إيران النار على السفن الأمريكية.","كانت القيادة المركزية الأمريكية \"سنتكوم\"، قالت اليوم، إنها دمرت 3 ناقلات نفط تابعة للحرس الثوري الإيراني بعد استهداف إيران سفينتين حربيتين تابعتين للبحرية الأمريكية.","وقالت سنتكوم، في منشور على منصة \"إكس\"، إن قواتها شنت غارات جوية على 3 ناقلات نفط خام إيرانية، في الخامس من سبتمبر، بعد أن أطلق الحرس الثوري الإيراني صواريخ باليستية باتجاه سفينتين حربيتين تابعتين للبحرية الأمريكية كانتا تقومان بدوريات في المياه الإقليمية."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/lvx52xia7','https://ajel.sa/international/lvx52xia7','https://ajel.sa/international/lvx52xia7','https://ajel.sa/international/lvx52xia7','فريق التحرير','','2026-09-05T13:51:00.000Z','Wed, 07 Oct 2026 21:18:41 GMT','2026-09-05T20:07:04.156Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-q-g1NL9c.jpg','/api/media/b346c0ae-4d8b-424c-b1b9-9fecfd520771','/api/media/b346c0ae-4d8b-424c-b1b9-9fecfd520771?variant=thumbnail','مقر خاتم الأنبياء الإيراني: الضربات ضد السفن الحربية الأمريكية ستكون أشدّ',1200,675,'valid','published','archived','valid',40,'8488893d78ecb10ca9ac6dbecb7c1494efefb0dfff9d8cfdfa471cea74bf650c','96b2a97a37bd7a7a8b91e5ee964c2adc5169db7b6d32f0733b25163df96a5fc1','محدّث','2026-09-05T20:07:04.156Z','2026-10-07T21:18:43.121Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الحرب الأمريكي بيت هيغسيث","الطاقة والنفط","الرياضة السعودية","إيران","الولايات المتحدة"]','["وزير الحرب الأمريكي بيت هيغسيث","الطاقة والنفط","الرياضة السعودية","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Active','2026-10-07T21:18:43.121Z',200,21,0,'source_article_available','',NULL,NULL,'body:318f16f1bd93697db4d1484b382463f9f7a96fe3b6e2e3de7f8afd25da4d2bd7','Wed, 07 Oct 2026 21:18:41 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('912fbb0c-728c-4c15-8e17-218a6b419e42','news-912fbb0c-728c-4c15-8e17-218a6b419e42','إيران أمام مأزق مضيق هرمز.. النفط الخليجي يتدفق والاقتصاد الإيراني يتراجع','ايران امام مازق مضيق هرمز النفط الخليجي يتدفق والاقتصاد الايراني يتراجع','وقدرت شركة «تانكر تراكرز» خروج نحو 5 ملايين برميل يوميًا من النفط الخام، معظمها من خارج إيران، عبر مضيق هرمز خلال الأيام الـ28 السابقة، إضافة إلى نحو 2.5 مليون برميل عبر موانئ خليج عُمان .','["بدأ عامل الوقت يضغط على إيران في معركة الحصار حول مضيق هرمز ، بعدما تراجعت قدرتها على استخدام الممر النفطي كورقة ضغط فعالة، في وقت تتزايد فيه كلفة الحصار على الاقتصاد الإيراني، وفق تحليل نشرته صحيفة « وول ستريت جورنال » الأمريكية.","وبحسب الصحيفة، راهنت طهران عند إغلاق مضيق هرمز قبل ستة أشهر على قدرتها على عرقلة أحد أهم الممرات النفطية في العالم، الذي كان يحتجز نحو خمس إمدادات النفط الخام العالمية، على أمل أن يؤدي ذلك إلى أزمة اقتصادية دولية تدفع الرئيس الأميركي دونالد ترامب إلى إنهاء الحرب وفق شروطها.","لكن هذه الحسابات لم تتحقق، إذ تمكن الحصار البحري الأمريكي منذ يوليو من منع إيران من تصدير النفط عبر الخليج، بينما ساعدت واشنطن دول الخليج العربي على مواصلة نقل كميات كبيرة من نفطها عبر المضيق، رغم الهجمات الإيرانية بالصواريخ والطائرات المسيّرة.","وقدرت شركة «تانكر تراكرز» خروج نحو 5 ملايين برميل يوميًا من النفط الخام، معظمها من خارج إيران، عبر مضيق هرمز خلال الأيام الـ28 السابقة، إضافة إلى نحو 2.5 مليون برميل عبر موانئ خليج عُمان . وتمثل هذه الكميات أكثر من 40% من تدفقات النفط التي كانت تمر بالمنطقة قبل الحرب.","وقال سمير مدني، الشريك المؤسس لشركة «تانكر تراكرز»، إن «الحصار الإيراني أكثر تسرباً من الحصار الأميركي»، مضيفًا أن الإيرانيين «غير قادرين على إغلاق المضيق بالكامل».","وترى «وول ستريت جورنال» أن استمرار تدفق النفط الخليجي يكشف تراجع قدرة إيران على استخدام مضيق هرمز لخنق صادرات جيرانها، رغم مواصلة استهداف السفن.","في المقابل، تتزايد الضغوط الاقتصادية داخل إيران، مع تراجع التجارة بنسبة تتراوح بين 25 و35%، وانخفاض قيمة الريال، وارتفاع التضخم، إلى جانب زيادة شيوع أزمة الوقود."]','السياسة','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/n360raps3','https://ajel.sa/international/n360raps3','https://ajel.sa/international/n360raps3','https://ajel.sa/international/n360raps3','فريق التحرير','','2026-09-05T13:52:00.000Z','Wed, 07 Oct 2026 21:18:43 GMT','2026-09-05T20:07:04.172Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D9%85%D8%B6%D9%8A%D9%82-%D9%87%D8%B1%D9%85%D8%B2-2-Qo258c6t.jpg','/api/media/912fbb0c-728c-4c15-8e17-218a6b419e42','/api/media/912fbb0c-728c-4c15-8e17-218a6b419e42?variant=thumbnail','مضيق هرمز',1200,675,'valid','published','archived','valid',99,'091a433470f171a7293c0b9257143a3c87a39b6e49a612283e903a972d39ecee','2f29f4d7e879825cbd7ffeb831155da5443afe65fb649a19027229e3641f6ba3','محدّث','2026-09-05T20:07:04.172Z','2026-10-07T21:18:44.789Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","شركة تانكر تراكرز خروج نحو","جامعة جونز هوبكنز إن التصعيد","الطاقة والنفط","التعليم والتدريب","الاقتصاد والأسواق","السياسة والعلاقات الدولية","إيران"]','["شركة تانكر تراكرز خروج نحو","جامعة جونز هوبكنز إن التصعيد","الطاقة والنفط","التعليم والتدريب","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Active','2026-10-07T21:18:44.789Z',200,21,0,'source_article_available','',NULL,NULL,'body:1327d0caea63cb4393bb6dcf383f29fc888abb62cf2b2edf0a1dfa1823fddba0','Wed, 07 Oct 2026 21:18:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('5411bd29-9a60-4097-b0fc-f85427643b26','news-5411bd29-9a60-4097-b0fc-f85427643b26','نزيف النقاط مستمر.. التعاون والفتح يتعادلان سلبيًا في دوري روشن','نزيف النقاط مستمر التعاون والفتح يتعادلان سلبيا في دوري روشن','واصل التعاون والفتح نتائجهما السلبية في دوري روشن السعودي ، بعدما انتهت المواجهة التي جمعتهما مساء السبت على ملعب التعاون بالتعادل السلبي، ضمن منافسات الجولة الخامسة من المسابقة. ورفع التعادل رصيد التعاون إلى 3 نقاط، ليحتل المركز الرابع عشر، بعدما أخفق في تحقيق الفوز للمباراة الخامسة على التوالي منذ انطلاق المسابقة.','["واصل التعاون والفتح نتائجهما السلبية في دوري روشن السعودي ، بعدما انتهت المواجهة التي جمعتهما مساء السبت على ملعب التعاون بالتعادل السلبي، ضمن منافسات الجولة الخامسة من المسابقة.","وتلقى التعاون ضربة مؤثرة في الدقيقة 66 بطرد لاعبه يونس البحراوي، ليكمل الفريق المباراة بعشرة لاعبين، لكنه حافظ على شباكه نظيفة حتى صافرة النهاية، مكتفيًا بنقطة واحدة.","ورفع التعادل رصيد التعاون إلى 3 نقاط، ليحتل المركز الرابع عشر، بعدما أخفق في تحقيق الفوز للمباراة الخامسة على التوالي منذ انطلاق المسابقة.","ولم يتمكن الفتح أيضًا من كسر سلسلة نتائجه السلبية، بعدما اكتفى بالتعادل الذي رفع رصيده إلى 3 نقاط، ليستقر في المركز السادس عشر بجدول الترتيب.","وتتواصل مهمة الفريقين في الجولة السادسة، عندما يواجه التعاون نظيره الحزم، فيما يلتقي الفتح مع الدرعية."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/nf1gk7vq3','https://ajel.sa/sports/nf1gk7vq3','https://ajel.sa/sports/nf1gk7vq3','https://ajel.sa/sports/nf1gk7vq3','فريق التحرير','الرياض','2026-09-05T13:51:00.000Z','Wed, 07 Oct 2026 21:18:41 GMT','2026-09-05T20:07:04.569Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%AA%D8%B9%D8%A7%D9%88%D9%86-%D9%88%D8%A7%D9%84%D9%81%D8%AA%D8%AD-_bzCULyi.jpg','/api/media/5411bd29-9a60-4097-b0fc-f85427643b26','/api/media/5411bd29-9a60-4097-b0fc-f85427643b26?variant=thumbnail','التعاون والفتح',1200,675,'valid','published','archived','valid',41,'3b19d31c67a6033afac96b2ca1a2c2b24632fb130657f8944c2f30437dd60577','5ca9cbf0da87f1b4cbd698caf0422b5f8d709b39a060f1a922ab64c9739588dd','محدّث','2026-09-05T20:07:04.569Z','2026-10-07T21:18:43.182Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T21:18:43.182Z',200,21,0,'source_article_available','',NULL,NULL,'body:1deff32a7238f77ec59e74c914160485a932c6570955fc23d974c98ac229db84','Wed, 07 Oct 2026 21:18:41 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2c80ea8b-2e4a-49c0-a1c1-bbcd2e3bab10','news-2c80ea8b-2e4a-49c0-a1c1-bbcd2e3bab10','إعلام عبري: الاحتلال يستعد لخفض قواته بجنوب لبنان عقب تدمير الأنفاق بمنطقة علي الطاهر','اعلام عبري الاحتلال يستعد لخفض قواته بجنوب لبنان عقب تدمير الانفاق بمنطقه علي الطاهر','أفادت هيئة البث الإسرائيلية، اليوم، أن جيش الاحتلال يستعد لخفض قواته في جنوب لبنان ، وذلك عقب تدمير الأنفاق في منطقة علي الطاهر. وقالت الهيئة، وفق " الشرق "، إن المؤسسة الأمنية الإسرائيلية تبحث إنشاء حزام أمني جديد بجنوب لبنان يكون أقرب إلى الحدود ويبعد ما بين 3 و4 كيلومترات من الحدود مع لبنان.','["أفادت هيئة البث الإسرائيلية، اليوم، أن جيش الاحتلال يستعد لخفض قواته في جنوب لبنان ، وذلك عقب تدمير الأنفاق في منطقة علي الطاهر.","وقالت الهيئة، وفق \" الشرق \"، إن المؤسسة الأمنية الإسرائيلية تبحث إنشاء حزام أمني جديد بجنوب لبنان يكون أقرب إلى الحدود ويبعد ما بين 3 و4 كيلومترات من الحدود مع لبنان.","وأضافت الهيئة الإسرائيلية أن التصور المطروح حاليا يقضي بالتخلي عن مناطق معينة من داخل ما يعرف \"بالخط الأصفر\"، والذي يشمل الحزام الأمني الإسرائيلي داخل الأراضي اللبنانية، بما في ذلك مناطق تقع شمال نهر الليطاني ، مثل منطقة قلعة الشقيف.","وتابعت الهيئة إنه بدلا من ذلك، ستنسحب القوات إلى مواقع أقرب إلى الحدود، حيث ستقام تحصينات ومواقع عسكرية داخل الأراضي اللبنانية، في انتشار يطلق عليه اسم \"الخط الرمادي\".","وأوضحت هيئة البث الإسرائيلية، في الوقت نفسه، إن الخطة لا تزال في مراحلها الأولية، ولم تحصل بعد على مصادقة المستوى السياسي، مشيرة إلى أنها تواجه عدة عقبات؛ أهمها مسألة نقل السيطرة على المناطق التي ستنسحب منها القوات الإسرائيلية إلى الجيش اللبناني، إلى جانب مسار المفاوضات بين إسرائيل ولبنان."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/68yk1664m','https://ajel.sa/international/68yk1664m','https://ajel.sa/international/68yk1664m','https://ajel.sa/international/68yk1664m','فريق التحرير','','2026-09-05T13:51:00.000Z','Wed, 07 Oct 2026 21:18:42 GMT','2026-09-05T20:07:04.582Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-wx4B4jez.jpg','/api/media/2c80ea8b-2e4a-49c0-a1c1-bbcd2e3bab10','/api/media/2c80ea8b-2e4a-49c0-a1c1-bbcd2e3bab10?variant=thumbnail','إعلام عبري: الاحتلال يستعد لخفض قواته بجنوب لبنان عقب تدمير الأنفاق بمنطقة علي الطاهر',1200,675,'valid','published','archived','valid',41,'3592c5c5bdc64d0d950cd7193481e71be9886797774f70bae06ac29983ed210e','7bcdb00b103c956fff07cb4f958aec35af28adea37f21f6d47c9840d4142d12e','محدّث','2026-09-05T20:07:04.582Z','2026-10-07T21:18:44.028Z','','',0,0,'gulf_arab','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة البث الإسرائيلية اليوم أن","السياسة والعلاقات الدولية","لبنان"]','["هيئة البث الإسرائيلية اليوم أن","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T21:18:44.028Z',200,22,0,'source_article_available','',NULL,NULL,'body:94374079195444a31d54404fd75c210c382e58e18bfcf7c9b57f7ec3cdbdf31f','Wed, 07 Oct 2026 21:18:42 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3ebb9078-5c37-4d02-8468-9c025dc7251c','news-3ebb9078-5c37-4d02-8468-9c025dc7251c','إنتر يعبر نابولي ويواصل التحليق في صدارة الدوري الإيطالي','انتر يعبر نابولي ويواصل التحليق في صداره الدوري الايطالي','واصل إنتر ميلان انطلاقته القوية في الدوري الإيطالي، بعدما عاد بفوز ثمين على مضيفه نابولي بنتيجة 3-2، مساء اليوم، ضمن منافسات الجولة الثالثة من المسابقة.','["ورفع حامل اللقب رصيده إلى 9 نقاط، ليتربع على صدارة جدول الترتيب، متقدمًا بفارق نقطتين على كومو صاحب المركز الثاني.","واستفاد إنتر من انتصاره ليبتعد بفارق ثلاث نقاط عن ميلان و يوفنتوس ، قبل المواجهة المرتقبة بين الفريقين غدًا ضمن منافسات الجولة نفسها.","في المقابل، تجمد رصيد نابولي عند 3 نقاط، ليتراجع إلى المركز العاشر في جدول ترتيب الدوري الإيطالي."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/wur85g0ix','https://ajel.sa/sports/wur85g0ix','https://ajel.sa/sports/wur85g0ix','https://ajel.sa/sports/wur85g0ix','فريق التحرير','','2026-09-05T13:51:00.000Z','Wed, 07 Oct 2026 21:18:43 GMT','2026-09-05T20:07:04.625Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A5%D9%86%D8%AA%D8%B1-%D9%85%D9%8A%D9%84%D8%A7%D9%86-%D9%88%D9%86%D8%A7%D8%A8%D9%88%D9%84%D9%8A-P1LExei0.webp','/api/media/3ebb9078-5c37-4d02-8468-9c025dc7251c','/api/media/3ebb9078-5c37-4d02-8468-9c025dc7251c?variant=thumbnail','إنتر ميلان ونابولي',1200,675,'valid','published','archived','valid',41,'56746ee3f8fe31135f5b9f95089445aeb6329f3d1abd98522c7b9fbe365a6b5d','45a6b150344e8f7cbba3a506ff4da3a4d51b4a8b9b27b8bc16f4dedd6629188b','محدّث','2026-09-05T20:07:04.625Z','2026-10-07T21:18:44.716Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T21:18:44.716Z',200,21,0,'source_article_available','',NULL,NULL,'body:b7e8429c731b51b66d9ba75558c283bdd8b345b42f66d05d26f2fd8e373a4e08','Wed, 07 Oct 2026 21:18:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('17c9742a-ff42-41fa-b8b1-3ffd3a51c7c9','news-17c9742a-ff42-41fa-b8b1-3ffd3a51c7c9','العليمي للحوثيين: «حساباتكم الخاطئة ستفتح أبواب السقوط الشامل»','العليمي للحوثيين حساباتكم الخاطئه ستفتح ابواب السقوط الشامل','وأضاف: «لقد اختارت المليشيات اختبار الدولة وقواتها المسلحة في واحدة من أكثر جبهات اليمن صلابة، وعليها الآن أن تدرك أن حساباتها الخاطئة ستفتح عليها أبواب السقوط الشامل».','["أشاد رئيس مجلس القيادة الرئاسي اليمني رشاد محمد العليمي بما وصفها بالانتصارات والمكاسب الميدانية التي حققتها القوات المسلحة والتشكيلات العسكرية خلال الساعات الماضية في جبهتي تعز و الحديدة ، مؤكدًا أن القوات الحكومية ماضية في استعادة المناطق الخاضعة لسيطرة مليشيا الحوثي.","وقال العليمي، خلال اتصالات أجراها مع عدد من القادة العسكريين والميدانيين، إنه اطّلع على مستجدات العمليات ومستوى الجاهزية القتالية، إلى جانب الإجراءات المتخذة لتثبيت وتأمين المناطق المحررة واستكمال تطهير المواقع التي تسللت إليها المليشيات.","وأشاد رئيس مجلس القيادة بوحدات ألوية المقاومة الوطنية و ألوية العمالقة والألوية التهامية، بعد استكمال تحرير وتأمين مديرية حيس بمحافظة الحديدة، كما أثنى على أداء القوات المسلحة في جبهة حيفان ، مشيدًا في الوقت نفسه بدور سلاح الجو في إسناد القوات على الأرض والتعامل مع التهديدات خلال العمليات.","وأكد العليمي أن مليشيا الحوثي ستتحمل كامل نتائج ما وصفها بـ«المغامرة» التي اختارت خوضها، مشددًا على أن تعز لن تكون ممرًا آمنًا للمشاريع والأجندات التي تدعمها الجماعة.","وقال إن القوات المسلحة التي تصدت للهجمات وانتزعت زمام المبادرة على الأرض قادرة، بحسب وصفه، على مواصلة استعادة الأراضي والقيام بواجبها في الدفاع عن المواطنين والمصالح العليا للبلاد.","ووجّه رئيس مجلس القيادة جميع القادة والوحدات العسكرية بالالتزام بالقانون الدولي الإنساني وقواعد الاشتباك، وحماية المدنيين والممتلكات العامة والخاصة، وتسهيل وصول المساعدات وإغاثة النازحين، إلى جانب حسن معاملة المحتجزين وصون حقوقهم وكرامتهم.","وقال: «إن اليد التي تحمل السلاح دفاعًا عن الجمهورية يجب أن تبقى أيضًا يد الدولة، وسيادة القانون»."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/27z3m6jf1','https://ajel.sa/international/27z3m6jf1','https://ajel.sa/international/27z3m6jf1','https://ajel.sa/international/27z3m6jf1','فريق التحرير','','2026-09-05T13:48:00.000Z','Wed, 07 Oct 2026 21:19:56 GMT','2026-09-05T20:13:04.025Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-Eu5jnwLy.png','/api/media/17c9742a-ff42-41fa-b8b1-3ffd3a51c7c9','/api/media/17c9742a-ff42-41fa-b8b1-3ffd3a51c7c9?variant=thumbnail','رشاد محمد العليمي',1200,675,'valid','published','archived','valid',41,'0548aedc4eb53070fc1b82ea26afc545b7ddab6c4516e5eda47575e3686d8402','09a76f1000cd2740a9101c9ff3262a4850c6494e1d255ac3ba9e774f678bb2b5','محدّث','2026-09-05T20:13:04.025Z','2026-10-07T21:19:58.006Z','','',0,0,'gulf_arab','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس القيادة الرئاسي اليمني رشاد","رئيس مجلس القيادة الرئاسي اليمني","اليمن"]','["مجلس القيادة الرئاسي اليمني رشاد","رئيس مجلس القيادة الرئاسي اليمني"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:19:58.006Z',200,21,0,'source_content_changed','',NULL,NULL,'body:efbb5d55318bbfb614482b0c36245a8ce786f6ce2924c40ec110889a5e10cc27','Wed, 07 Oct 2026 21:19:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ad6818ee-71b4-4b04-9d46-38f300f53a47','news-ad6818ee-71b4-4b04-9d46-38f300f53a47','الاتحاد يُسقط النصر بثنائية ويقفز للمركز الرابع في دوري روشن','الاتحاد يسقط النصر بثنائيه ويقفز للمركز الرابع في دوري روشن','حقق الاتحاد فوزاً ثميناً على حساب ضيفه النصر بنتيجة 2-1، مساء السبت، في منافسات الجولة الخامسة من دوري روشن السعودي للمحترفين، على ملعب الإنماء بمدينة الملك عبدالله الرياضية في جدة، بإدارة الحكم خالد الطريس، ليقفز الاتحاد بهذا الفوز إلى المركز الرابع في جدول الترتيب.','["وافتتح الاتحاد التسجيل مبكراً في الدقيقة الرابعة، إذ استثمر جورج إلينيخينا كرةً مرتدة من القائم إثر تسديدة زميله بيرغوين، ليحولها برأسه داخل شباك حارس النصر نواف العقيدي.","وعاد إلينيخينا ليضاعف التقدم بهدف ثانٍ في الدقيقة 22، قبل أن يُقلص انجلو الفارق بهدف للنصر في الدقيقة 36، لتنتهي الشوط الأول بتقدم الاتحاد 2-1.","وفي الشوط الثاني، أبدى حارس الاتحاد رايكوفيتش حضوراً استثنائياً، إذ تصدى لتسديدتَي جواو فيليكس وقائد النصر كريستيانو رونالدو في الدقيقتين 56 و58، ثم أبعد رأسية لاعب النصر كوستا ببراعة في الدقيقة 64، منقذاً فريقه من هدف التعادل.","وختم رايكوفيتش عرضه المتميز بتصدٍّ أخير لتسديدة ساديو ماني في الوقت القاتل عند الدقيقة 90، ليحسم الاتحاد الفوز ويُحكم قبضته على النتيجة.","وبهذا الفوز يرتقي الاتحاد إلى «مربع الكبار» برصيد 11 نقطة، فيما يبقى النصر في المركز الثاني برصيد 12 نقطة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/3yOYNbG','https://sabq.org/article/3yOYNbG','','https://sabq.org/article/3yOYNbG','صحيفة سبق','الرياض','2026-09-05T14:07:00.000Z','2026-09-05T17:07:00.000Z','2026-09-05T20:13:24.305Z','https://media.sabq.org/news/2026/09/0fba4459-895a-455a-9749-3d92a880884c/w1600.webp','/api/media/ad6818ee-71b4-4b04-9d46-38f300f53a47','/api/media/ad6818ee-71b4-4b04-9d46-38f300f53a47?variant=thumbnail','الاتحاد يُسقط النصر بثنائية ويقفز للمركز الرابع في دوري روشن',1600,1378,'valid','published','archived','valid',99,'ac6b2b44d9bc556c452919cf65c7c9acab7930104cad7ac875f8ace4788e2665','d6ee0c6084d4df31d3e6acd6cab5ecb007f4ea982071634787a6a19e2ce88f51','محدّث','2026-09-05T20:13:24.305Z','2026-10-07T21:19:46.272Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","جدة","الرياض"]','["الرياضة السعودية"]','classified','','[{"category":"المناطق","score":3},{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T21:19:46.272Z',200,20,0,'source_article_available','',NULL,NULL,'body:afec2b79909da2c8a2255a36c78258bd71f3840a2117c2af80b3713b44e91841','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('aae542db-281e-42a1-a8db-af9c65d2daf0','news-aae542db-281e-42a1-a8db-af9c65d2daf0','رصد تضاريس القمر بمرحلة التربيع الأخير يكشف تاريخه الجيولوجي في رفحاء','رصد تضاريس القمر بمرحله التربيع الاخير يكشف تاريخه الجيولوجي في رفحاء','شهدت سماء محافظة رفحاء ب منطقة الحدود الشمالية ، أمس، رصدًا فلكيًا لتضاريس القمر خلال مرحلة التربيع الأخير، أتاح للمهتمين فرصة مشاهدة أبرز معالم سطحه، وعلى رأسها الفوهات الصدمية والمناطق المرتفعة والمنخفضات الداكنة، التي تمثل سجلًا طبيعيًا يوثق جزءًا مهمًا من تاريخ القمر الجيولوجي وتطور النظام الشمسي المبكر.','["وأوضح عضو جمعية آفاق لعلوم الفلك برجس الفليح أن الرصد أظهر تفاصيل متنوعة لسطح القمر، من بينها الفوهات الصدمية والمرتفعات والمناطق الداكنة، مشيرًا إلى أن وضوح هذه المعالم يتأثر بمرحلة القمر وتوقيت الرصد وصفاء الأجواء والأدوات الفلكية المستخدمة.","وأضاف الفليح أن تضاريس القمر تشكلت في الأساس بفعل الارتطامات النيزكية الواسعة والنشاط البركاني القديم، ولا تزال آثار هذه العمليات محفوظة بدرجة كبيرة، نتيجة محدودية عمليات التعرية على سطحه مقارنة بالأرض. وأشار إلى أن ذلك يجعل من دراسة تضاريس القمر مصدرًا مهمًا لفهم تاريخه الجيولوجي.","تعد الفوهات الصدمية من أكثر المعالم انتشارًا على سطح القمر، وهي نتاج اصطدام الكويكبات والنيازك والمذنبات بسطحه على مدى مليارات السنين، وتختلف في أحجامها وأشكالها، حيث تكشف بعض الفوهات عن مواد من طبقات أعمق من القشرة القمرية، وتوفر مؤشرات على طبيعة الارتطامات التي أسهمت في تشكيل سطح القمر.","وأوضح الفليح أن الفوهات القمرية تظهر بشكل أوضح عند اقتراب القمر من طور التربيع، حيث تسهم الظلال الممتدة على حوافها ومنحدراتها في إبراز تفاصيلها بشكل أفضل، مقارنة بفترة البدر التي تقل فيها الظلال ويقل التباين بين التضاريس.","وتبرز أيضًا البحار القمرية، التي هي مناطق داكنة واسعة لا تمثل بحارًا مائية، بل سهول بركانية تشكلت عندما غمرت تدفقات الحمم البازلتية أحواضًا ومنخفضات واسعة نتجت عن اصطدامات كبرى، وتتميز بلونها الداكن مقارنة بالمرتفعات القمرية الأكثر سطوعًا، وترتبط باختلافات في التركيب المعدني والعمر الجيولوجي لسطح القمر.","وتكشف التضاريس القمرية عن سلاسل جبلية ومرتفعات شاهقة تختلف في نشأتها عن جبال الأرض، إذ ارتبط تشكل كثير منها بالارتطامات العملاقة التي أحدثت أحواضًا واسعة وأسهمت قوى الاصطدام وارتداد سطح القمر في تشكيل حواف مرتفعة ومعقدة حولها.","وأكد عضو جمعية آفاق لعلوم الفلك أن رصد القمر لا يقتصر على الجانب الجمالي، بل يمثل وسيلة مبسطة للتعرف على تاريخه الجيولوجي، موضحًا أن متابعة تغير الإضاءة والظلال على سطحه تساعد على تمييز الفوهات والجبال والسهول البركانية، وتسهم في نشر الثقافة الفلكية بين أفراد المجتمع."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/o10yx1skb','https://ajel.sa/local/o10yx1skb','https://ajel.sa/local/o10yx1skb','https://ajel.sa/local/o10yx1skb','فريق التحرير','الحدود الشمالية','2026-09-05T14:03:00.000Z','Wed, 07 Oct 2026 21:21:36 GMT','2026-09-05T20:19:03.308Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-09/source-coCVPK9a.jpg','/api/media/aae542db-281e-42a1-a8db-af9c65d2daf0','/api/media/aae542db-281e-42a1-a8db-af9c65d2daf0?variant=thumbnail','رصد تضاريس القمر بمرحلة التربيع الأخير يكشف تاريخه الجيولوجي في رفحاء',1200,675,'valid','published','archived','valid',41,'1be2801c21996393121f8aed2655e745ed8ef94bbf6c13cf6b622fc6e5518065','9e1e83e9315c4d481d4d53ad25db71b82eae38cf8d9266dd3f77d3a959f4dbc9','محدّث','2026-09-05T20:19:03.308Z','2026-10-07T21:21:38.283Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","الاقتصاد والأسواق"]','["الثقافة والفنون","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:21:38.283Z',200,19,0,'source_content_changed','',NULL,NULL,'body:8c4660c2bba9c84d778c409ad306c6487f55c147576f6565afae754dd3ac5fa5','Wed, 07 Oct 2026 21:21:36 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('de3b7fce-47c1-4d4c-b064-8aaec815e95f','news-de3b7fce-47c1-4d4c-b064-8aaec815e95f','اتحاد المبارزة السعودي يعيّن عبدالله السلوم نائبًا للرئيس للدورة الجديدة','اتحاد المبارزه السعودي يعين عبدالله السلوم نائبا للرئيس للدوره الجديده','اعتمد مجلس إدارة الاتحاد السعودي للمبارزة ، برئاسة الدكتور واسم آل حسن، تعيين عبدالله السلوم نائبًا للرئيس، إلى جانب أعضاء المجلس الجديد للدورة الانتخابية 2024–2028، وذلك خلال اجتماع المجلس الذي عُقد أمس في مقر الاتحاد ب الرياض .','["وشهد الاجتماع التصديق على محضر اجتماع الجلسة الرابعة، إلى جانب التصديق على محضر اجتماع مجلس الإدارة بالتمرير.","استعرض مجلس الإدارة التقارير المالية للربع الثاني من عام 2026، وناقش خطة النشاط الخارجي للمنتخبات حتى نهاية عام 2026.","كما تطرق المجلس إلى آخر التحديثات المتعلقة بالتعاون مع مركز التدريب السعودي الأولمبي (SOTC)، إضافة إلى مستجدات نظام دعم النقاط للموسم الداخلي 2026–2027.","وتناول الاجتماع ما تم تنفيذه من برامج تطوير الحكام الدوليين والواعدين، إلى جانب مناقشة عدد من المستجدات والأعمال المدرجة على جدول الأعمال واتخاذ ما يلزم حيالها."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/cvan515ij','https://ajel.sa/sports/cvan515ij','https://ajel.sa/sports/cvan515ij','https://ajel.sa/sports/cvan515ij','فريق التحرير','الرياض','2026-09-05T13:58:00.000Z','Wed, 07 Oct 2026 21:21:40 GMT','2026-09-05T20:19:03.493Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-09/source-OJlTTTy8.jpg','/api/media/de3b7fce-47c1-4d4c-b064-8aaec815e95f','/api/media/de3b7fce-47c1-4d4c-b064-8aaec815e95f?variant=thumbnail','اتحاد المبارزة السعودي يعيّن عبدالله السلوم نائبًا للرئيس للدورة الجديدة',1200,675,'valid','published','archived','valid',41,'c004b6ef86aba6ce8b73775631720df6ba605b639d4fe4cc456cc1622dfef916','16920c7e02d7b412b75c02de7b59788e86e9aee9716d9eb94fd0e49f7e7690ed','محدّث','2026-09-05T20:19:03.493Z','2026-10-07T21:21:42.506Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إدارة الاتحاد السعودي للمبارزة","التعليم والتدريب","الرياض"]','["مجلس إدارة الاتحاد السعودي للمبارزة","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:21:42.506Z',200,22,0,'source_content_changed','',NULL,NULL,'body:c542b07fecfd97e658f4c65f20772f5ee3a41322f6772862dc035099930e4960','Wed, 07 Oct 2026 21:21:40 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b21b6a35-b30e-427a-b6cf-0c4dc0ac6144','news-b21b6a35-b30e-427a-b6cf-0c4dc0ac6144','ضيوف برنامج خادم الحرمين يزورون معالم تاريخية في المدينة المنورة','ضيوف برنامج خادم الحرمين يزورون معالم تاريخيه في المدينه المنوره','زار ضيوف برنامج خادم الحرمين الشريفين للعمرة والزيارة، الذي تشرف عليه وزارة الشؤون الإسلامية والدعوة والإرشاد للعام 1448هـ، اليوم السبت، عدداً من المعالم الإسلامية في المدينة المنورة شملت مقبرة شهداء أحد، وجبل الرماة، ومسجد قباء، وذلك ضمن البرنامج الثقافي الذي أعدته الوزارة للضيوف خلال إقامتهم.','["واستمع الضيوف إلى شرح حول الآداب الشرعية عند زيارة المقابر، بالإضافة إلى شرح مفصل عن معركة أحد، حيث تعرفوا على موقع المعركة وتحولاتها التاريخية.","كما زار الضيوف مسجد قباء، واطلعوا على قيمته التاريخية وفضله، وأدوا فيه ركعتين اقتداءً بسنة النبي محمد صلى الله عليه وسلم.","وأعرب ضيوف البرنامج عن شكرهم لخادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود وسمو ولي العهد الأمير محمد بن سلمان ، على الخدمات المقدمة التي سهلت لهم زيارة المعالم الإسلامية التاريخية، مشيدين بعناية المملكة بالإسلام والمسلمين وسعادتهم بهذه التجربة.","يُذكر أن الدفعة الثالثة من البرنامج تضم 250 معتمرًا ومعتمرة من 23 دولة أفريقية، من بينها مصر ، و المغرب ، و تونس ، و الجزائر ، و السنغال ، وغينيا كوناكري، و الكاميرون ، و نيجيريا ، وغانا، والنيجر، و إثيوبيا ، ورواندا، و موريتانيا ، وساحل العاج، وبوركينا فاسو، وتشاد، وتنزانيا، و جيبوتي ، وجنوب أفريقيا، وزامبيا، وناميبيا، وأنغولا، ومالي."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/2wbcukq6t','https://ajel.sa/local/2wbcukq6t','https://ajel.sa/local/2wbcukq6t','https://ajel.sa/local/2wbcukq6t','فريق التحرير','المدينة المنورة','2026-09-05T13:57:00.000Z','Wed, 07 Oct 2026 21:21:37 GMT','2026-09-05T20:19:03.554Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-09/source-dl6y4Q5C.jpg','/api/media/b21b6a35-b30e-427a-b6cf-0c4dc0ac6144','/api/media/b21b6a35-b30e-427a-b6cf-0c4dc0ac6144?variant=thumbnail','ضيوف برنامج خادم الحرمين يزورون معالم تاريخية في المدينة المنورة',1200,675,'valid','published','archived','valid',99,'d05b0fa5ffcc9ab69e0a6db17645e8751e2701b586a4bbc261d6ee9685f7aa19','e779a5b20c83365d578973ad0b21b5de2f633a66d67bc3aae58c1a57e2c105c0','محدّث','2026-09-05T20:19:03.554Z','2026-10-07T21:21:39.284Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد الأمير محمد بن","خادم الحرمين يزورون معالم تاريخية","وزارة الشؤون الإسلامية والدعوة والإرشاد","المدينة المنورة"]','["ولي العهد الأمير محمد بن","خادم الحرمين يزورون معالم تاريخية","وزارة الشؤون الإسلامية والدعوة والإرشاد","المدينة المنورة"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:21:39.284Z',200,19,0,'source_content_changed','',NULL,NULL,'body:72f3ad4d7d94cbe395ab1035074d47451952344a0436676067f75560dd94900f','Wed, 07 Oct 2026 21:21:37 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ab24708b-f2b2-4679-bd5d-90f5bd5737c4','news-ab24708b-f2b2-4679-bd5d-90f5bd5737c4','أمطار غزيرة تهطل على عدة محافظات في منطقة جازان','امطار غزيره تهطل علي عده محافظات في منطقه جازان','شهدت منطقة جازان مساء اليوم هطول أمطار غزيرة إلى متوسطة، حيث شملت الأمطار محافظات العارضة ، و فيفا ، و الداير (بني مالك)، و العيدابي ، و الحرث ، و أبو عريش ، إضافة إلى عدد من المراكز والقرى التابعة لها.','["وتأتي هذه الأمطار في إطار التقلبات الجوية التي تشهدها المنطقة، ما أدى إلى تلطيف الأجواء وتحسين مستوى الرطوبة في المحافظات المتأثرة.","وفي السياق ذاته، دعا الأهالي إلى توخي الحيطة والحذر أثناء التنقل في المناطق المتضررة من الأمطار، خصوصًا في الطرق الجبلية والمنحدرات."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/y0yl5641j','https://ajel.sa/local/y0yl5641j','https://ajel.sa/local/y0yl5641j','https://ajel.sa/local/y0yl5641j','فريق التحرير','جازان','2026-09-05T13:57:00.000Z','Wed, 07 Oct 2026 21:21:38 GMT','2026-09-05T20:19:03.973Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-09/source-5RJOO5n_.jpg','/api/media/ab24708b-f2b2-4679-bd5d-90f5bd5737c4','/api/media/ab24708b-f2b2-4679-bd5d-90f5bd5737c4?variant=thumbnail','أمطار غزيرة تهطل على عدة محافظات في منطقة جازان',1200,675,'valid','published','archived','valid',88,'45b96f2903fbd6657b7c9cc16d35fabe1b8334dd631358a1bb4c240f73107c34','866b279a5524876d09c216b24e2242c71cd515c85babc5cbc1a5b27409419175','محدّث','2026-09-05T20:19:03.973Z','2026-10-07T21:21:40.421Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","جازان"]','["الطقس والمناخ"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T21:21:40.421Z',200,19,0,'source_content_changed','',NULL,NULL,'body:c732a50f980cfcd23d3436aeeed84c5b0371cb639376a4396b9c35f401010b90','Wed, 07 Oct 2026 21:21:38 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('13bbe723-14cc-450f-a9d6-decd8ccc6fff','news-13bbe723-14cc-450f-a9d6-decd8ccc6fff','الاتحاد يتغلّب على ضيفه النصر في الجولة الخامسة من «دوري روشن»','الاتحاد يتغلب علي ضيفه النصر في الجوله الخامسه من دوري روشن','تغلب فريق الاتحاد على ضيفه النصر بهدفين لهدف في اللقاء الذي جمعهما اليوم، على ملعب مدينة الملك عبدالله الرياضية ب جدة ، ضمن منافسات الجولة الخامسة من الدوري السعودي للمحترفين "دوري روشن". وبهذه النتيجة رفع الاتحاد رصيده إلى (11) نقطة بالمركز الرابع، في حين تجمد رصيد النصر عند النقطة (12) بوصافة الترتيب.','["تغلب فريق الاتحاد على ضيفه النصر بهدفين لهدف في اللقاء الذي جمعهما اليوم، على ملعب مدينة الملك عبدالله الرياضية ب جدة ، ضمن منافسات الجولة الخامسة من الدوري السعودي للمحترفين \"دوري روشن\".","وافتتح الاتحاد نتيجة المواجهة مبكرًا عند الدقيقة (4) عن طريق لاعبه جورج إلينيخينا، قبل أن يتمكن اللاعب ذاته من تعزيز النتيجة بالهدف الثاني عند الدقيقة (22)، في حين تمكن النصر من تقليص الفارق عن طريق لاعبه أنجيلو غابرييل عند الدقيقة (36).","وبهذه النتيجة رفع الاتحاد رصيده إلى (11) نقطة بالمركز الرابع، في حين تجمد رصيد النصر عند النقطة (12) بوصافة الترتيب."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/fr6x8bo16','https://ajel.sa/sports/fr6x8bo16','https://ajel.sa/sports/fr6x8bo16','https://ajel.sa/sports/fr6x8bo16','فريق التحرير','الرياض','2026-09-05T14:31:00.000Z','Wed, 07 Oct 2026 19:34:40 GMT','2026-09-05T20:50:07.539Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%A7%D8%AA%D8%AD%D8%A7%D8%AF--CwrTjcQ.png','/api/media/13bbe723-14cc-450f-a9d6-decd8ccc6fff','/api/media/13bbe723-14cc-450f-a9d6-decd8ccc6fff?variant=thumbnail','الاتحاد يتغلّب على ضيفه النصر في الجولة الخامسة من «دوري روشن»',1200,675,'valid','published','archived','valid',41,'d7a33ffa4a44b85661e79911f49f0183f189b3fba80aed702973ec54a46935a2','e3b4ace6d9669e4f1320c86bbccddea516a45214035bf09fa13b7a313f9a5a89','محدّث','2026-09-05T20:50:07.539Z','2026-10-07T20:25:22.790Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","جدة","الرياض"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:34:42.051Z',200,28,0,'source_content_changed','',NULL,NULL,'body:5068470bdcb0a20b84eb26f37331ed900fd786b81480d27ac07ed51092e3e5c8','Wed, 07 Oct 2026 19:34:40 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6a389068-fe10-439f-8460-5fcd9f2e181a','news-6a389068-fe10-439f-8460-5fcd9f2e181a','فيسينج: الاتحاد ظهر بشكل مختلف أمام النصر.. وقرار رايكوفيتش غدًا','فيسينج الاتحاد ظهر بشكل مختلف امام النصر وقرار رايكوفيتش غدا','أكد الألماني ينس فيسينج، مدرب فريق الاتحاد الأول لكرة القدم، سعادته بالفوز على النصر، مشيرًا إلى أن حضور جماهير الاتحاد في المدرجات عزز رغبته في تحقيق الانتصار، ومشيدًا بما قدمه اللاعبون خلال المباراة.','["وقال فيسينج خلال المؤتمر الصحافي عقب اللقاء: «بوجود جمهور الاتحاد كنت أريد الانتصار فقط، وشكرًا لهم على ما قدموه في المدرج من تشجيع رائع، وسعيد بهذا الانتصار وما قدمه اللاعبون من أداء كبير في المباراة».","وأضاف: «نعلم صعوبة المباراة، وقدمنا أداءً جيدًا في أول 30 دقيقة، وكان بالإمكان تسجيل أهداف أكثر، والنصر حصل على هدف من لا شيء خلال الشوط الأول، والحصول على ثلاث نقاط في مثل هذه الظروف والأجواء الصعبة أمام فريق قوي يعد أمرًا جيدًا».","وتابع: «مباراة النصر تختلف عن القادسية، لقد تطورنا كثيرًا في الجوانب الفنية، وظهرنا اليوم بالأداء المميز، واضطررت إلى إشراك ريتشارد مع بداية الشوط الثاني، على الرغم من مشاركته في تدريب وحيد معنا قبل المباراة، نظرًا لإصابة مختار علي».","وأوضح مدرب الاتحاد: «لا يوجد لاعب في الهجوم والدفاع، الجميع يلعب كمجموعة واحدة دفاعيًا وهجوميًا، وهذه طريقة لعبي وأسلوب عملي».","وعن مجريات المباراة، قال فيسينج: «الجميع شاهد ما حدث في لقاء اليوم، ومن كان مسيطرًا، وهددنا مرمى النصر كثيرًا».","وفيما يخص إصابة حارس المرمى رايكوفيتش، أوضح: «سنرى غدًا فيما يخص إصابة رايكوفيتش، وشاهدته مبتسمًا في غرفة الملابس بعد المباراة، والآن نحتفل، وغدًا سيتضح مدى جاهزيته»"]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/gZqzosg','https://sabq.org/article/gZqzosg','','https://sabq.org/article/gZqzosg','جمال المرشدي','','2026-09-05T15:10:00.000Z','2026-09-05T18:10:00.000Z','2026-09-05T21:17:09.091Z','https://media.sabq.org/news/2026/09/6c953236-000d-4393-9cf1-726d8c1d07ab/w904.webp','/api/media/6a389068-fe10-439f-8460-5fcd9f2e181a','/api/media/6a389068-fe10-439f-8460-5fcd9f2e181a?variant=thumbnail','فيسينج: الاتحاد ظهر بشكل مختلف أمام النصر.. وقرار رايكوفيتش غدًا',904,1205,'valid','published','archived','valid',98,'4bd497ddcf6ca4f40ccaea072523ecd2251d45c86c8445b85b9c3d71263441c9','3b939d2bc69dd2a6144c852968108414f52081e259af024579910cea91e8ae92','محدّث','2026-09-05T21:17:09.091Z','2026-10-07T19:51:28.025Z','','',0,0,'international','عادي',49,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الرياضة السعودية"]','["التعليم والتدريب","الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T19:51:28.025Z',200,19,0,'source_article_available','',NULL,NULL,'body:a96c958df67f691305bf95976c49b6001d759517df73bad0e200957c695f5c3e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0a4a9014-fc2b-4519-9ab2-55bc65455a11','news-0a4a9014-fc2b-4519-9ab2-55bc65455a11','في ليلة عيد الأندية.. الزحمة والمقاضي ما خلصت!','في ليله عيد الانديه الزحمه والمقاضي ما خلصت','-فالشارع الرياضي يعيش منذ أيام حالة انتظار وترقّب لمعرفة أسماء اللاعبين الذين تمكنت الأندية من التعاقد معهم، والذين أصبح بإمكانها تسجيلهم وفق الأنظمة واللوائح. -ولعل حالة معظم أنديتنا تؤكد ذلك؛ فما زلنا نلاحظ أندية تنتظر حتى ليلة العيد، ولا تنهي تعاقداتها إلا في الثواني الأخيرة، وحظها في تلك اللحظات:','["أكاد أشبّه ما يحدث في نهاية هذا اليوم الأحد الموافق 6 سبتمبر 2026، ومع دقة الساعة الثانية عشرة مساءً، حين تنتهي في الثانية الأخيرة فترة التسجيل الأولى للأندية، بـ«ليلة العيد»بكل تفاصيلها؛ زحمة، ومقاضٍ لم تكتمل، وأناس ينتظرون، وآخرون يركضون للحاق بما تبقى من الوقت!","-فالشارع الرياضي يعيش منذ أيام حالة انتظار وترقّب لمعرفة أسماء اللاعبين الذين تمكنت الأندية من التعاقد معهم، والذين أصبح بإمكانها تسجيلهم وفق الأنظمة واللوائح. وفي العادة تبدأ الحكاية باختيار نخبة من اللاعبين يفترض أن يكونوا مميزين، أصحاب قيمة فنية عالية، وفق ما يملكه النادي من وفرة مالية وفكر إداري واعٍ.","-وهنا تشتعل حالة الفرح والبهجة عند جماهير الأندية التي تمكنت إداراتها من إنهاء «مقاضي العيد» مبكراً وبجودة عالية، بينما يحدث العكس تماماً عند أندية تقف على خط «الفقر»؛ فتخرج جماهيرها خائبة الظن، بسبب ما تعانيه من شح مالي وضعف إداري، وهي تتحسس الفارق بينها وبين معشر الأندية «الغنية»، ولسان حالها يقول:","-حال الأندية، مثل الدنيا وناسها «ناس فوق وناس تحت»، وعندما تبحث عن حجم هذه الفروقات وتضعها على أرض الواقع، تجد أن الأندية أيضاً ليست على مستوى واحد؛ هناك أندية «فوق» وأخرى «تحت» وبين هذه وتلك درجات ومستويات، فالطبقة «الفوق» نفسها موزعة إلى قسمين: قسم من النوع الفاخر، وقسم آخر من نوع «تقليد الفاخر»","-أما طبقة «تحت» فهي كذلك نوعان: نوع «نص ونص» ونوع آخر يطبق المثل الشعبي الشهير «افرش لحافك على قد رجولك» وهذا الوضع ليس جديداً علينا، بل هو أمر متعارف عليه في عالم كرة القدم، سواء عندنا أو في مختلف دول العالم. تعايشنا معه منذ زمن الهواية، ثم عصر الاحتراف، لكنه بدأ يتغير مع عصر الشركات والخصخصة؛ إذ أصبحت الأندية محكومة بأنظمة ولوائح، وهياكل إدارية مؤسسية، وأطر مالية وتجارية.","-ومع ذلك، فإن تجربتنا لا تزال في بدايتها، وتعيش حالة مخاض؛ منها ما ينتهي بولادة طبيعية، ومنها ما يتعسر، لأسباب قد نجهلها، أو لأن رؤيتنا لا تزال تسير في اتجاه واحد، لم نستطع الخروج منه حتى الآن، فمهما تغير الزمن، واختلفت معايير الأندية التي كانت تخضع لنظام الأفراد وأصبحت اليوم تحت مظلة الشركات، ما زالت معادلة «أندية فوق وأندية تحت» حاضرة بقوة. ليلة العيد.. والثواني الأخيرة!","-ولعل حالة معظم أنديتنا تؤكد ذلك؛ فما زلنا نلاحظ أندية تنتظر حتى ليلة العيد، ولا تنهي تعاقداتها إلا في الثواني الأخيرة، وحظها في تلك اللحظات:","«تلحق.. ولا ما تلحق؟!» وحتى إذا لحقت، لا تعرف هل جاءت مقاييس اختياراتها «مناسبة» أم أنها كانت مجرد نتيجة للزحمة! الخياط.. أقصد وكيل الأعمال، ربما أكلها «مقلب»! أو ربما ضاعت الصفقة في «سكة التائهين» فضاع معها موعد العيد، واضطر النادي إلى ارتداء ثوبه القديم، والاكتفاء بفرحة «تسلية» تمشي الحال!."]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264579','https://www.okaz.com.sa/articles/authors/2264579','','https://www.okaz.com.sa/articles/authors/2264579','عدنان جستنيه','الرياض','2026-09-05T18:00:00.000Z','Tue, 06 Oct 2026 12:27:05 GMT','2026-09-05T21:41:43.636Z','https://www.okaz.com.sa/okaz/uploads/authors/1828.jpg?v=1782207910','/api/media/0a4a9014-fc2b-4519-9ab2-55bc65455a11','/api/media/0a4a9014-fc2b-4519-9ab2-55bc65455a11?variant=thumbnail','في ليلة عيد الأندية.. الزحمة والمقاضي ما خلصت!',400,400,'valid','published','archived','valid',40,'bc7b0a4806d53060d09f7196b22c6b1bf46eba9646ca48e8e38f97bf6ef3b820','c14edcec690665769b335159837b4174f7c361871418941b298452789c68bba6','محدّث','2026-09-05T21:41:43.636Z','2026-10-07T20:25:22.790Z','','',0,0,'saudi_region','مهم',72,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"السياسة","score":1.5},{"category":"الثقافة","score":1.5},{"category":"المناطق","score":0.5}]','Updated','2026-10-07T19:59:48.284Z',200,30,0,'source_content_changed','',NULL,NULL,'body:f7e77096f5963b750624d19141fa6bf428aede45f582dcb2cb1ad17bd3bab085','Tue, 06 Oct 2026 12:27:05 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('27986a9e-1860-4ffe-8c55-eb269e555b5a','news-27986a9e-1860-4ffe-8c55-eb269e555b5a','عشق «أحد» ووجع التعصب الرياضي','عشق احد ووجع التعصب الرياضي','هل خُلقت من أجل الاستمتاع أم من أجل العداوات والتعصب الرياضي الذي أصبح شعارًا نعتز به في رياضتنا السعودية؟ يحدث تفاوت من وقت لآخر في الجانب السلبي للرياضة، والذي من المفترض ألا يتجاوز الإسقاط على الآخرين للبحث عن العدالة والمساواة.','["- الرياضة أمرها غريب وعجيب! هل خُلقت من أجل الاستمتاع أم من أجل العداوات والتعصب الرياضي الذي أصبح شعارًا نعتز به في رياضتنا السعودية؟ يحدث تفاوت من وقت لآخر في الجانب السلبي للرياضة، والذي من المفترض ألا يتجاوز الإسقاط على الآخرين للبحث عن العدالة والمساواة. إن الشفافية مطلوبة حتى لا تُأوَّل الأحداث وجميع الجوانب المتعلقة بالوسط الرياضي، ونتحدث بشفافية بعيدًا عن الغموض، ولكن دون أن نحوّل الرياضة والكرة إلى وجه سلبي.","- البعض يطارد خلف «الترند» سواءً في بعض البرامج الرياضية أو منصات التواصل الاجتماعي مواصلاً إثارة الجدل والبحث عن المشاهدات على حساب الطرح الموضوعي، عبر تقديم خطاب يجيّش الجماهير ويؤجج الاحتقان، وعدم استيعابهم أن «الرياضة فوز وخسارة»، والتعامل مع الخسارة على أنها هزيمة شخصية أو انكسار للهوية، وفي النهاية أنت مسؤول عن ما تكتب وهناك جهات رقابية تتابع وترصد هذه التجاوزات حتى لا يحدث انفلات إعلامي.","- أكتب مقالاتي بعيدًا والله عن أي ميول لأيٍّ من الأندية الجماهيرية الكبيرة، وقد أشار البعض فيما أكتب إلى أن ميولي هلالية؛ وأصدقكم القول إني أشجع الهلال والأهلي والنصر والاتحاد وجميع هذه الكيانات الكبيرة، لكن ميولي الحقيقية هي أنني (أُحُديّ) العشق منذ صغري، وناديّ الذي أعشقه وأحبه يترنح وهو في شبه غيبوبة، وأنتظر الفرج الذي ينقذ هذا النادي المديني العريق، وقد كتبت عنه كثيرًا، لعل الأيام القادمة تبشر بالخير وأن يعود فارس المدينة إلى عهده السابق بطلًا وشامخًا كشموخ جبل أحد.","- وأنا أكتب بناءً على الأحداث من باب تخصصي الرياضي وتعايشي مع الرياضة السعودية منذ فترة طويلة، وقد تعلمت في مشواري الصحفي الطويل أن ليس كل ما يُعلم يُكتب ويُقال، وتعلمت أن بعض الأمور لا يجب أن تخرج لأن عقليات وثقافات الآخرين مختلفة، وكلٌّ يفسرها حسب وجهة نظره وينظر من زاوية واحدة فقط.","- الآن أصبح العالم مكشوفًا من جميع الجوانب، وأصبح لدى كل شخص منبر يتحدث منه بعد أن كان التلفاز والصحافة هما المتحدث الرسمي، إذ أصبحت لكل فرد منصته التي يتحدث فيها، ولكن ليس كل من لديه وسيلة يستطيع إيصال صوته؛ فهناك من يجيد لغة الكتابة وهناك من يجيد لغة الصوت، لكن أن نحول هذه الوسائل إلى خصومات وعداوات فهذا هو الجانب السلبي. الحياة قصيرة جدًا، وكثير من الرياضيين رحلوا وغادروا، لكن أصواتهم الجميلة وعطاءاتهم ما زالت محفورة في القلب ومحفوظة.","- تكرمًا.. لا تؤججوا الشارع الرياضي بحجة البحث عن العدالة، فهناك جهات معنية تمنح كل ذي حق حقه. لقد خسر البعض الكثير من زملائهم في المهنة، وسمعت بعض القصص المزعجة جدًا التي وصلت إلى الشجار والخصومات الطويلة بسبب الميول، عفواً.. بسبب (التعصب الأعمى)."]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264578','https://www.okaz.com.sa/articles/authors/2264578','','https://www.okaz.com.sa/articles/authors/2264578','سامي المغامسي','الرياض','2026-09-05T18:00:00.000Z','Wed, 07 Oct 2026 19:59:46 GMT','2026-09-07T05:30:44.415Z','https://www.okaz.com.sa/okaz/uploads/authors/1672.jpg?v=1757438909','/api/media/27986a9e-1860-4ffe-8c55-eb269e555b5a','/api/media/27986a9e-1860-4ffe-8c55-eb269e555b5a?variant=thumbnail','عشق «أحد» ووجع التعصب الرياضي',399,400,'valid','published','archived','valid',40,'31fbc8ef0e1d1e19c85ed82a3c901451d009b186c9323d0a5e52561f98776a25','49785266c29355dc5655e7a7c9f1719a10cb9eddf893e97299a094148997df09','محدّث','2026-09-05T21:41:55.148Z','2026-10-07T20:25:22.790Z','','',0,0,'saudi_region','مهم',67,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Updated','2026-10-07T19:59:48.238Z',200,30,0,'source_content_changed','',NULL,NULL,'body:589ebe723c65c2f7d059d1bde13454cf4c0557dfaa977697b9a032a03ff32e49','Wed, 07 Oct 2026 19:59:46 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('026230ed-61dc-4c4e-92a1-6012fdbca78b','news-026230ed-61dc-4c4e-92a1-6012fdbca78b','مانشستر سيتي يحقق فوزه الثالث على التوالي ويحافظ على صدارة الدوري الإنجليزي','مانشستر سيتي يحقق فوزه الثالث علي التوالي ويحافظ علي صداره الدوري الانجليزي','حقق مانشستر سيتي فوزه الثالث على التوالي، بتغلبه على كوفنتري الصاعد حديثا بهدف دون رد، اليوم، ضمن منافسات الجولة الثالثة من الدوري الإنجليزي الممتاز لكرة القدم. وسجل المهاجم الدولي النرويجي إرلينغ هالاند هدف المباراة الوحيد في الدقيقة (26)، ليرفع مانشستر سيتي رصيده إلى تسع نقاط في صدارة الترتيب العام.','["حقق مانشستر سيتي فوزه الثالث على التوالي، بتغلبه على كوفنتري الصاعد حديثا بهدف دون رد، اليوم، ضمن منافسات الجولة الثالثة من الدوري الإنجليزي الممتاز لكرة القدم.","وسجل المهاجم الدولي النرويجي إرلينغ هالاند هدف المباراة الوحيد في الدقيقة (26)، ليرفع مانشستر سيتي رصيده إلى تسع نقاط في صدارة الترتيب العام.","وفي باقي المباريات، تعادل نيوكاسل مع بورنموث بهدفين لمثلهما، وبهذه النتيجة رفع نيوكاسل يونايتد رصيده إلى خمس نقاط، بعد أن حقق فوزًا وتعادلين في أول ثلاث جولات، فيما رفع بورنموث رصيده إلى نقطتين.","وواصل توتنهام تعثره بسقوطه في فخ التعادل السلبي أمام مضيفه نوتنغهام فوريست، فيما قلب كريستال بالاس تأخره أمام مضيفه وجاره فولهام إلى فوز بثلاثة أهداف مقابل هدفين، كما تعادل برنتفورد مع سندرلاند بهدف لمثله.","وتعادل برايتون مع ليدز يونايتد بهدف لمثله، فيما انتهت مواجهة هال سيتي و أستون فيلا بالتعادل السلبي."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/u092b8i90','https://ajel.sa/sports/u092b8i90','https://ajel.sa/sports/u092b8i90','https://ajel.sa/sports/u092b8i90','فريق التحرير','','2026-09-05T16:29:00.000Z','Mon, 07 Sep 2026 04:42:25 GMT','2026-09-05T22:59:56.779Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D9%85%D8%A7%D9%86%D8%B4%D8%B3%D8%AA%D8%B1-%D8%B3%D9%8A%D8%AA%D9%8A-TaGhH57J.png','/api/media/026230ed-61dc-4c4e-92a1-6012fdbca78b','/api/media/026230ed-61dc-4c4e-92a1-6012fdbca78b?variant=thumbnail','مانشستر سيتي يحقق فوزه الثالث على التوالي ويحافظ على صدارة الدوري الإنجليزي',1200,675,'valid','published','archived','valid',41,'5ed778785d24dd6d4367e4e984ac7ae2295e511ecf58540e270a92dfdfa90c02','4e6a8876a2b470c7381578b130127e32b58bb8f81bdfff1cc7a81a5aa15cccb1','محدّث','2026-09-05T22:59:56.779Z','2026-10-07T20:25:22.790Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:32:17.133Z',NULL,23,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f46b64f7-ba6e-4c01-a602-d257ff3b6d7c','news-f46b64f7-ba6e-4c01-a602-d257ff3b6d7c','«فيسينغ» يشيد بانضباط الاتحاد.. و«بوستيكوجلو» يعزو خسارة النصر للبداية المتعثرة','فيسينغ يشيد بانضباط الاتحاد و بوستيكوجلو يعزو خساره النصر للبدايه المتعثره','من جانبه، أوضح بوستيكوجلو أن البداية غير الموفقة كانت العامل الأبرز في خسارة النصر، مبينًا أن الفريق لم يدخل أجواء المباراة بالصورة المطلوبة خلال الدقائق الأولى.','["تحدث المديران الفنيان لفريقي الاتحاد والنصر الألماني ينز فيسينغ والأسترالي آنج بوستيكوجلو، عن مواجهة الفريقين التي أقيمت على ملعب مدينة الملك عبدالله الرياضية ب جدة ، ضمن منافسات الجولة الخامسة من الدوري السعودي للمحترفين \"دوري روشن\"، وانتهت بفوز الاتحاد بهدفين لهدف.","وأوضح فيسينغ خلال المؤتمر الصحفي عقب المباراة، أن الاتحاد قدم مستوى مميزًا في فترات عديدة من اللقاء، مشيدًا بانضباط اللاعبين وروحهم التنافسية، مبينًا أن الفريق فرض أفضليته خلال الدقائق الأولى ونجح في تسجيل هدفين وصناعة فرص أخرى.","وأشار إلى التطور الملحوظ الذي شهده الفريق فنيًا وذهنيًا مقارنة بالمباريات السابقة، مؤكدًا نجاح اللاعبين في تطبيق التعليمات التكتيكية والمحافظة على التوازن، خصوصًا خلال الشوط الثاني الذي شهد تعديلات فنية للحد من خطورة المنافس.","وأكد أن النصر استعاد توازنه تدريجيًا وقدم مستوى أفضل في الشوط الثاني، ونجح في صناعة عدد من الفرص الخطرة، إلا أن غياب التوفيق وتألق حارس الاتحاد حالَ دون تعديل النتيجة، مشيرًا إلى أن مواجهة فريق قوي على أرضه وبين جماهيره تتطلب حضورًا ذهنيًا وفنيًا منذ البداية.","وأشاد بما قدمه اللاعبون في الشوط الثاني، مؤكدًا أن الفريق أظهر قدراته الهجومية ونجح في إيجاد فرص كافية لتعديل النتيجة."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/xegv6cqiw','https://ajel.sa/sports/xegv6cqiw','https://ajel.sa/sports/xegv6cqiw','https://ajel.sa/sports/xegv6cqiw','فريق التحرير','الرياض','2026-09-05T17:36:00.000Z','Wed, 07 Oct 2026 19:59:43 GMT','2026-09-05T23:50:09.343Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop-f86mMHAR.png','/api/media/f46b64f7-ba6e-4c01-a602-d257ff3b6d7c','/api/media/f46b64f7-ba6e-4c01-a602-d257ff3b6d7c?variant=thumbnail','«فيسينغ» يشيد بانضباط الاتحاد.. و«بوستيكوجلو» يعزو خسارة النصر للبداية المتعثرة',1200,675,'valid','published','archived','valid',40,'487de7c97db02c3be19309310c0257ab80f116d6eb122d6a7b0f181e92ef05fc','bb7f15b7ee64a42c14abb0df4630b29ff8fccbeb3b1534be965515f3e91f2ccb','محدّث','2026-09-05T23:50:09.343Z','2026-10-07T20:25:22.790Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الرياضة السعودية","جدة","الرياض"]','["التعليم والتدريب","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Active','2026-10-07T19:59:44.828Z',200,28,0,'source_article_available','',NULL,NULL,'body:b83987431fd9fd432fb39a245caaef4aa2568ceb7567a213bb653f75624ee2bf','Wed, 07 Oct 2026 19:59:43 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('407d2428-5a10-4234-83b2-6e8cc5e5dab5','news-407d2428-5a10-4234-83b2-6e8cc5e5dab5','الحرس الثوري الإيراني: استهدافنا حاملة طائرات ومدمرة أمريكيتين بالصواريخ','الحرس الثوري الايراني استهدافنا حامله طائرات ومدمره امريكيتين بالصواريخ','أعلنت العلاقات العامة للحرس الثوري الإيراني، فجر اليوم الأحد، استهداف حاملة طائرات ومدمرة تابعتين للجيش الأمريكي بصواريخ باليستية. وحذر الحرس الثوري من أن استمرار «الأعمال العدائية» سيقابل بردود قوية من القوات المسلحة الإيرانية، مؤكدا أن إيران «أقوى من أي وقت مضى».','["أعلنت العلاقات العامة للحرس الثوري الإيراني، فجر اليوم الأحد، استهداف حاملة طائرات ومدمرة تابعتين للجيش الأمريكي بصواريخ باليستية.","وقال الحرس الثوري في بيان إن السفينتين العسكريتين الأمريكيتين فرتا من منطقة الاشتباك بعد تعرضهما لأضرار، مضيفا أن الحاملة والمدمرة المستهدفتين شاركتا في «مضايقة» السفن الإيرانية والحصار البحري.","وأضاف البيان أن الولايات المتحدة اضطرت إلى الاعتراف رسميا بتعرض سفينتين حربيتين تابعتين للبحرية الأمريكية للهجوم، معتبرا أن تأكيد القيادة المركزية الأمريكية «سنتكوم» للعملية يمثل دليلا على ما وصفه بـ«الهزيمة الاستراتيجية» للولايات المتحدة، وبرهانا على القدرات الهجومية للحرس الثوري.","وحذر الحرس الثوري من أن استمرار «الأعمال العدائية» سيقابل بردود قوية من القوات المسلحة الإيرانية، مؤكدا أن إيران «أقوى من أي وقت مضى»."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/e58wuhtw9','https://ajel.sa/international/e58wuhtw9','https://ajel.sa/international/e58wuhtw9','https://ajel.sa/international/e58wuhtw9','فريق التحرير','المدينة المنورة','2026-09-05T18:34:00.000Z','Wed, 07 Oct 2026 21:11:38 GMT','2026-09-06T00:44:08.616Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%B5%D9%88%D8%A7%D8%B1%D9%8A%D8%AE-%D8%A7%D9%84%D8%AD%D8%B1%D8%B3-%D8%A7%D9%84%D8%AB%D9%88%D8%B1%D9%8A-%D8%A7%D9%84%D8%A5%D9%8A%D8%B1%D8%A7%D9%86%D9%8A-XhFHia1j.png','/api/media/407d2428-5a10-4234-83b2-6e8cc5e5dab5','/api/media/407d2428-5a10-4234-83b2-6e8cc5e5dab5?variant=thumbnail','الحرس الثوري الإيراني: استهدافنا حاملة طائرات ومدمرة أمريكيتين بالصواريخ',1200,675,'valid','published','archived','valid',41,'25bd82ca73c61e2f31325379a39a7d9834b258825b1526c5b4e6f573166d1908','4634f283fd93af437fec582dbf218e903234ec49a227cb28a3ff09103b90b06c','محدّث','2026-09-06T00:44:08.616Z','2026-10-07T21:11:40.070Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["إيران","الولايات المتحدة"]','["الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:11:40.070Z',200,21,0,'source_content_changed','',NULL,NULL,'body:8ed86d6f6daec01a6920e950c7f1e74b0178391f5679fefcda2d2ba0c10b696b','Wed, 07 Oct 2026 21:11:38 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3e40adfe-c89f-4047-a22c-d4268c51450f','news-3e40adfe-c89f-4047-a22c-d4268c51450f','«الكرملين» يشيد بالمحادثات مع مبعوثي «ترامب» بشأن أوكرانيا','الكرملين يشيد بالمحادثات مع مبعوثي ترامب بشان اوكرانيا','ورددت موسكو جميع هذه التصريحات مرارا خلال الحرب المستمرة منذ أكثر من أربعة أعوام ونصف العام، وشهدت تكثيف الجانبين للضربات الجوية بعيدة المدى في الأسابيع القليلة الماضية، بينما ظلت خطوط الجبهة ثابتة إلى حد كبير.','["قال يوري أوشاكوف مستشار الكرملين إن الرئيس الروسي فلاديمير بوتين أجرى محادثات استمرت أكثر من ثلاث ساعات أمس السبت مع مبعوثين أمريكيين يسعيان للتوصل إلى اتفاق ينهي الحرب في أوكرانيا ، واصفا المناقشات بأنها \"مفيدة للغاية\" لكنه لم يشر إلى إحراز أي تقدم.","وأضاف أوشاكوف أن المبعوثين ستيف ويتكوف و جاريد كوشنر \"طرحا عددا من الأفكار بشأن السبل المحتملة للتوصل إلى تسوية\". ولم يذكر أوشاكوف ماهية تلك الأفكار.","وقال إن بوتين أبلغهما بأن روسيا تحرز \"تقدما حقيقيا\" في ساحة المعركة وأنه واثق من تحقيق أهداف بلاده، وشدد على ضرورة معالجة \"جميع الأسباب الجذرية للصراع\".","ولم يصدر تعليق بعد من ويتكوف وكوشنر، اللذين زارا موسكو للمرة الأولى منذ يناير كانون الثاني نيابة عن الرئيس دونالد ترامب .","وغادر المبعوثان موسكو جوا بعد وقت قصير من المحادثات، ومن المقرر أن يلتقيا الرئيس الأوكراني فولوديمير زيلينسكي في كييف غدا الأحد.","وقال أوشاكوف \"تجاوزت المحادثات مجرد تبادل الآراء بشأن حل الأزمة الأوكرانية. ونوقشت بالتفصيل إلى حد ما قضايا اقتصادية ومشروعات روسية أمريكية كبرى محتملة تعود بالنفع المتبادل على البلدين\".","وأضاف \"بوجه عام، يمكن القول إن المفاوضات جاءت في الوقت المناسب وكانت مفيدة للغاية للجانبين\"."]','العالم','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/mreye4usg','https://ajel.sa/international/mreye4usg','https://ajel.sa/international/mreye4usg','https://ajel.sa/international/mreye4usg','فريق التحرير','','2026-09-05T18:47:00.000Z','Wed, 07 Oct 2026 19:07:35 GMT','2026-09-06T01:02:08.695Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%B1%D9%88%D8%B3%D9%8A%D8%A7-KZwXwG1v.jpg','/api/media/3e40adfe-c89f-4047-a22c-d4268c51450f','/api/media/3e40adfe-c89f-4047-a22c-d4268c51450f?variant=thumbnail','«الكرملين» يشيد بالمحادثات مع مبعوثي «ترامب» بشأن أوكرانيا',1200,675,'valid','published','archived','valid',41,'641426e242f851ff30e5e60c6908c9b0a5ca6a4f7e4e49525b6ea6fc1e1f29e4','0082892cef8f8932ebaa988da587ac34b6a1b0ba64bdfccb15bf3120fe278f05','محدّث','2026-09-06T01:02:08.695Z','2026-10-07T20:25:22.790Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","السياسة والعلاقات الدولية","روسيا","أوكرانيا","الولايات المتحدة"]','["الاقتصاد والأسواق","السياسة والعلاقات الدولية","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:07:37.550Z',200,16,0,'source_content_changed','',NULL,NULL,'body:d97a05b03eb93ce9cbc91d25c7c9cc09505ccaba4bab9805a6535b1bd13c176d','Wed, 07 Oct 2026 19:07:35 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('640becc2-5588-4d5f-8af5-cc6691e7848e','news-640becc2-5588-4d5f-8af5-cc6691e7848e','الاستفادة من الأكاديميين المتقاعدين في جامعاتنا','الاستفاده من الاكاديميين المتقاعدين في جامعاتنا','هذا الارتفاع يأتي بعد العمل على برامج متعددة، تأتي في مقدمتها برامج جودة الحياة والخدمات الصحية والاجتماعية للمواطن السعودي. هذه القفزة في متوسط العمر لدينا تحتم الاستفادة من فترة التقاعد لدى المواطنين في مجالات عدة، وتأتي في مقدمتها الاستفادة من الأساتذة المتقاعدين في جامعاتنا، وهذا لا يعني التوظيف واستقطاب الكفاءات الشابة في الكوادر الجامعية أو…','["هيئة الإحصاءات العامة أعلنت قبل فترة قريبة، أن معدل متوسط العمر المتوقع عند الولادة للمواطن السعودي قد وصلت إلى نسبة 79.9 سنة، وهي نسبة قريبة من المستهدف في مخرجات رؤية المملكة 2030، وهي عمر يصل إلى 80 عاماً للمواطن السعودي. هذا الارتفاع يأتي بعد العمل على برامج متعددة، تأتي في مقدمتها برامج جودة الحياة والخدمات الصحية والاجتماعية للمواطن السعودي. هذه القفزة في متوسط العمر لدينا تحتم الاستفادة من فترة التقاعد لدى المواطنين في مجالات عدة، وتأتي في مقدمتها الاستفادة من الأساتذة المتقاعدين في جامعاتنا، وهذا لا يعني التوظيف واستقطاب الكفاءات الشابة في الكوادر الجامعية أو الاستعانة بأساتذة من الخارج، كما هو معمول به في أغلب الجامعات بدول العالم.","الاستعانة بالأكاديميين ممن تقاعدوا خيار مهم من جوانب معرفية لخبراتهم الطويلة في التدريس والبحث الأكاديمي، إضافة إلى العامل الاقتصادي، فالتعاقد مع الأستاذ السعودي بعقد معقول سوف يوفر على الجامعات مبالغ طائلة في حال تعاقدت مع أساتذة عرب مثلاً، وقد يكون بعضهم قد تقاعد في بلده ويأتي عندنا بعقود رواتبها ليست بقليلة، هذه الحسبة الاقتصادية يجب أخذها بعين الاعتبار، فبعض الأكاديميين السعوديين يقبعون في منازلهم ولديهم الطاقة والرغبة في الاستمرار في العمل الأكاديمي، خاصة الإشراف العلمي على برامج الدراسات العليا، ولكن يتم الاستغناء عنهم ويستمر زملاؤهم من الدول العربية في عملهم الجامعي، وهذا فيه هدر للموارد المالية والبشرية.","التعاقد مع غير السعوديين للتدريس في الجامعات ما زال مستمراً، وتفضل الجامعات عند التعاقد خريجي الجامعات الأجنبية وإجادة اللغة الإنجليزية، إلا أن أغلب من يُتعاقد معهم خريجو جامعات عربية فكيف لا يستفاد من المتقاعدين الأساتذة السعوديين خريجي الجامعات الأجنبية التي ابتعثوا لها من قبل الجامعات نفسها من حيث جودة التعليم فيها وبرامجها الأكاديمية الدقيقة المتخصصة. مثل هذه القرارات تهدر وتؤثر على جودة التعليم الجامعي واستدامة الخبرات، وللأسف نجد بعض الدكاترة غير السعوديين يستمرون في عملهم الأكاديمي لعقود في مخالفة للنظام الذي يحدد فترة التعاقد بعشرة أعوام فقط.","وبنظرة للجامعات العربية حولنا لم أجد فيها تعاقداً أو تعييناً لدكاترة من أبنائنا خريجي أفضل الجامعات العالمية.","أتذكر في بعض الجامعات البريطانية تجد أساتذة كباراً في العمر يمارسون العمل الأكاديمي، بل يعتبرون كنوزاً معرفية، ولا يتركون عملهم إلا باختيارهم. وفي الغالب تجدهم يركزون على الأبحاث الأكاديمية والإشراف على طلبة الدراسات العليا. عندنا الأكاديمي المواطن بعد تسريحه من عمله بسبب أنظمة التقاعد يعيش حالة نفسية وهو قابع في منزله، والبعض يلجأ للتدريس في الجامعات الخاصة، وهذا خيار جيد ولكنه غير متاحٍ للكل.","قصد أحدهم كما قالها لي شخصياً إنه مالياً أوضاعه مرتبة وليس بحاجة ولكنه يعيش حالة من الفراغ ويحن ويعشق الأجواء الأكاديمية، وبعد فترة خاطب رئيس القسم الذي كان فيه، وهذا كان في يوم من الأيام أحد الطلبة الذين درسهم قبل سنوات، يطلب في خطابه التعاون بالتدريس بساعات قليلة في القسم. مرت الأسابيع والأشهر ولم يردوا عليه ولو من باب المجاملة وهو لم يعد يتصل عليهم لحفظ ماء وجهه، ويردد كيف تكون النهاية هكذا بينما زملاؤه العرب باقون في القسم وتجدد عقودهم وهو لا يُرد عليه أصلاً."]','التعليم','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264576','https://www.okaz.com.sa/articles/authors/2264576','','https://www.okaz.com.sa/articles/authors/2264576','عقل العقل','مكة المكرمة','2026-09-05T18:00:00.000Z','Wed, 07 Oct 2026 19:42:01 GMT','2026-09-07T05:30:45.059Z','','','','الاستفادة من الأكاديميين المتقاعدين في جامعاتنا',NULL,NULL,'all_candidates_failed (og:invalid_image_dimensions)','published','archived','valid',54,'075f326a232af419a2bf1c19436b9b3f171d47a4b3962c00787d0f5cefb7a9b5','4f3faca03cd0b384a7405eccd85e9df8ee12d6d999ffa8d1f3cd779bc737f881','محدّث','2026-09-06T01:32:37.644Z','2026-10-07T20:25:22.790Z','','',0,0,'saudi_region','مهم',74,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس القسم الذي كان فيه","هيئة الإحصاءات العامة أعلنت قبل","الطاقة والنفط","التعليم والتدريب","الاقتصاد والأسواق","جدة"]','["رئيس القسم الذي كان فيه","هيئة الإحصاءات العامة أعلنت قبل","الطاقة والنفط","التعليم والتدريب","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الاقتصاد","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":1.5}]','Updated','2026-10-07T19:42:03.120Z',200,22,0,'source_content_changed','',NULL,NULL,'body:ed6e6f3f420dd40cf03d63bf7cb7dea4e4df17701bf690e8b1bf14a51a049842','Wed, 07 Oct 2026 19:42:01 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8df1f1d3-18bf-4058-995a-262a393d9b61','news-8df1f1d3-18bf-4058-995a-262a393d9b61','حسام الباحة.. إدارة تميز ونقلة نوعية لسياحة بيئية','حسام الباحه اداره تميز ونقله نوعيه لسياحه بيئيه','وطن يعيش بأمن وأمان يعمل على تنوع دخله وتميز مناطقه، خلق سمو ولي العهد حالة تنافسية تنموية جاذبة بين مناطق الوطن. ومن هنا تلتقي خصوصية الباحة مع مستهدفات رؤية السعودية 2030 في استثمار الميز النسبية للمناطق، وتنويع الاقتصاد، وتعزيز جودة الحياة.','["وطن يعيش بأمن وأمان يعمل على تنوع دخله وتميز مناطقه، خلق سمو ولي العهد حالة تنافسية تنموية جاذبة بين مناطق الوطن. تحط بنا الرحال في الباحة منطقة الجمال والطبيعة، خلابة بين الضباب وطبيعة استثنائية تجمع الجبال، والغابات والمناخ المعتدل والقرى التراثية والمزارع والمنتجات المحلية، فتملك رصيدًا متنوعًا من الموارد الطبيعية والثقافية والزراعية. غير أن المورد في ذاته لا يصنع تنمية، إذ تبدأ قيمته حين يُكتشف، ويُحسن إدارته، ويُستثمر بصورة مستدامة، فيتحول من مورد طبيعي أو موروث محلي إلى منتج سياحي، وفرصة استثمارية، وقيمة اقتصادية، ثم أثر تنموي يعود على المجتمع والمنطقة.","ومن هنا تلتقي خصوصية الباحة مع مستهدفات رؤية السعودية 2030 في استثمار الميز النسبية للمناطق، وتنويع الاقتصاد، وتعزيز جودة الحياة. فتنوعت المنطقة بين موارد جبلية، وزراعية، وتراثية، ومعارف محلية، حرف ومنتجات وصناعات يدوية، والقيمة الحقيقية تكمن في جمعها ضمن منظومة تحول الموارد إلى تجارب ومنتجات وأسواق واستثمارات.","ولم يكن رهان سمو ولي العهد الأمير محمد بن سلمان بن عبدالعزيز على الباحة نابعًا من فراغ، بل جاء من قراءة لمعطياتها وميزتها النسبية، وما يمكن أن تمثله من نموذج في تنويع الاقتصاد الوطني، وجذب السائح، واستثمار البيئة والتراث والزراعة والمعارف المحلية المتوارثة، وتحويلها إلى فرص اقتصادية وسياحية مستدامة.","وتكتسب هذه الرؤية قوتها من ثقة القيادة بالقيادة المحلية في الباحة، ممثلة في الأمير الدكتور حسام بن سعود بن عبدالعزيز، أمير المنطقة، فسموه مطلع على تفاصيلها، قريب من قضاياها، حاضر في الميدان، ومتابع للمشروعات والفرص والتحديات. والنزول إلى الميدان عنده ليس حضورًا بروتوكوليًا، بل وسيلة لفهم الواقع، واكتشاف الفرص، ورؤية المعوقات، وتحويلها إلى قرارات وحلول. وهنا تتوحد علاقة حسام بالباحة، فالباحة تقدم الموارد والمقومات، وحسام يدفع باتجاه تنظيمها واستثمارها، والغاية تحويل هذه المقومات إلى قيمة اقتصادية وسياحية واجتماعية تعود على المنطقة وأبنائها. ليصبح الجذب السياحي استراتيجية تنموية لا فعالية موسمية. فالمكان الجميل قد يجذب الزائر مرة، أما الوجهة الناجحة فتصنع له سببًا للقدوم، وتجربة للبقاء، وما يدفعه إلى العودة. والباحة مؤهلة لذلك عبر السياحة الجبلية والبيئية والريفية والثقافية، حين تتكامل الطبيعة مع التراث والزراعة والمنتجات المحلية.","وتتسع دائرة المنتج السياحي لتشمل المعارف المحلية المتوارثة (Indigenous Knowledge)، التي ورثها المجتمع عبر أجيال في التعامل مع البيئة والزراعة، والغذاء والحرف والموارد. وهذه المعرفة ليست مجرد موروث، بل رصيد يمكن تحويله إلى قيمة اقتصادية وثقافية حين يوثق ويطور ويقدم للزائر في صورة تجربة أصيلة.","ومن هذه المعرفة تتولد منتجات تحمل هوية الباحة، الحرف ذات الجودة، والمنتجات اليدوية، وأنواع الأكلات من قرص البر، ومشغوثة، ومرضوخة، ودغابيس، والعريكة، إلى جانب العسل والفواكه والخضار وسائر المنتجات المحلية. وهذه ليست مجرد منتجات للاستهلاك، بل عناصر يمكن تطويرها وتسويقها وربطها بتجربة الزائر.","فحسام الباحة وفريق عمله جعل الزائر للباحة يتذوقها، ويقتنيها، ويفهم معارف أهلها. وعندها تتحول المعرفة المحلية إلى مورد يحفظ الهوية ويفتح فرصًا للحرفيين والأسر المنتجة والمزارعين والمنشآت الصغيرة.","وتدخل البيئة في قلب هذه المعادلة، فهي ليست ملفًا منفصلًا عن السياحة، بل رأس مالها الطبيعي. الغابة والجبل والمزرعة والقرية التراثية موارد تدار باقتدار وكفاءة، لأن استدامة السياحة مرتبطة باستدامة المكان. فالسياحة التي تستنزف البيئة تستهلك مصدر نجاحها، بينما السياحة المستدامة تجعل حماية البيئة شرطًا لاستمرار الاستثمار."]','أخبار السعودية','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264577','https://www.okaz.com.sa/articles/authors/2264577','','https://www.okaz.com.sa/articles/authors/2264577','محمد شايع الشايع','الباحة','2026-09-05T18:00:00.000Z','Wed, 07 Oct 2026 19:42:54 GMT','2026-09-07T05:30:44.670Z','https://www.okaz.com.sa/uploads/authors/1624.jpg','/api/media/8df1f1d3-18bf-4058-995a-262a393d9b61','/api/media/8df1f1d3-18bf-4058-995a-262a393d9b61?variant=thumbnail','حسام الباحة.. إدارة تميز ونقلة نوعية لسياحة بيئية',400,400,'valid','published','archived','valid',60,'98c3c087bf68fa63e822c7a90b01007322e1707e82a291835fff2fae7ee4af66','2cea1ba98feb765ca9f1f216a6a8dd2873d55d3b6b69df3798c664b0f71b6969','محدّث','2026-09-06T01:49:31.334Z','2026-10-07T20:25:22.791Z','','',0,0,'saudi_region','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد حالة تنافسية تنموية","الصحة العامة","الطقس والمناخ","السفر والسياحة","الثقافة والفنون","الاقتصاد والأسواق","الباحة"]','["ولي العهد حالة تنافسية تنموية","الصحة العامة","الطقس والمناخ","السفر والسياحة","الثقافة والفنون","الاقتصاد والأسواق"]','needs_review','ambiguous_category','[{"category":"أخبار السعودية","score":7.5},{"category":"الاقتصاد","score":7},{"category":"المجتمع","score":7}]','Updated','2026-10-07T19:42:56.278Z',200,20,0,'source_content_changed','',NULL,NULL,'body:ae09aaef72ee1f4369eb1f97734b818aa34fa8d4a40715d68f6427cf584fcfa9','Wed, 07 Oct 2026 19:42:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b01fa061-8bc3-47d5-a74e-5a2264d08e95','news-b01fa061-8bc3-47d5-a74e-5a2264d08e95','قُل لي أين تقف.. أَقُل لك أين السعودية','قل لي اين تقف اقل لك اين السعوديه','لو جمعت ما يُقال عن المملكة العربية السعودية في عواصم العالم، ثم نزعت أسماء أصحاب الكلام، فقد يخطر لك أنهم يتحدثون عن أكثر من دولة. واقتصادها تجاوز ١٫٢٧ تريليون دولار خلال ٢٠٢٥، فيما تمثل الأنشطة غير النفطية أكثر من نصف الناتج، وهذا اتساع في المصالح نفسها، لا في العلاقات وحدها.','["لو جمعت ما يُقال عن المملكة العربية السعودية في عواصم العالم، ثم نزعت أسماء أصحاب الكلام، فقد يخطر لك أنهم يتحدثون عن أكثر من دولة.","عند طرف، السعودية حليف إستراتيجي لا يمكن تجاوز ثقله، وعند آخر، شريك اقتصادي ينبغي توسيع العلاقة معه، وعند ثالث، قوة إقليمية تملك من التأثير ما يجعل حضورها ضرورياً في معادلات المنطقة، وعند طرف رابع، دولة «صعبة» لا يمكن التكهن بموقفها لمجرد معرفة موقف حلفائها.","والغريب أن هؤلاء يتحدثون عن السعودية نفسها.","في العلاقات الدولية، لا توجد نافذة واحدة تطل منها الدول على بعضها، فالجغرافيا تصنع زاوية، والاقتصاد يصنع أخرى، والأمن، والطاقة، والتجارة، والتحالفات، والتاريخ، والمصالح كلها تعيد ترتيب المشهد بحسب موقع الناظر إليه، والسياسة الدولية ليست مجلساً لاختيار «أطيب الدول»، بل شبكة هائلة من المصالح والحسابات المتقاطعة.","ولذلك قد تكون الدولة نفسها حليفاً في ملف، ومنافساً في آخر، وشريكاً في ثالث، ومختلفاً معها في رابع، من دون أن يكون في ذلك تناقض، فالعالم لم يعد بسيطاً إلى الحد الذي يسمح بتقسيمه إلى معسكرين، ثم سؤال كل دولة: مع من أنتم؟","وهنا تحديداً تبدو التجربة السعودية لافتة..","للمملكة علاقة إستراتيجية راسخة مع الولايات المتحدة، وعلاقات اقتصادية وتجارية واسعة مع الصين، وتعمل مع روسيا ودول أخرى ضمن «أوبك+» في توازنات سوق الطاقة، وتبني شراكات واسعة مع أوروبا، وتوسع علاقاتها مع الهند والاقتصادات الآسيوية، وتتحرك في الوقت نفسه من عمقها العربي والإسلامي، وتنفتح على دوائر جديدة في أفريقيا وأمريكا اللاتينية. واقتصادها تجاوز ١٫٢٧ تريليون دولار خلال ٢٠٢٥، فيما تمثل الأنشطة غير النفطية أكثر من نصف الناتج، وهذا اتساع في المصالح نفسها، لا في العلاقات وحدها.","وأمام شبكة بهذا الاتساع، قد يبدو السؤال التقليدي «مع من أنتم؟» منطقياً، لكنه في الحقيقة سؤال ينتمي إلى زمن أبسط من زمننا."]','أخبار السعودية','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264575','https://www.okaz.com.sa/articles/authors/2264575','','https://www.okaz.com.sa/articles/authors/2264575','عبداللطيف آل الشيخ','الرياض','2026-09-05T18:00:00.000Z','Wed, 07 Oct 2026 19:42:52 GMT','2026-09-06T01:49:32.886Z','https://www.okaz.com.sa/okaz/uploads/authors/1775.jpg?v=1769684372','/api/media/b01fa061-8bc3-47d5-a74e-5a2264d08e95','/api/media/b01fa061-8bc3-47d5-a74e-5a2264d08e95?variant=thumbnail','قُل لي أين تقف.. أَقُل لك أين السعودية',307,400,'valid','published','archived','valid',85,'4066387fcac75f7fb12833b47965870022070eb5cb7bedbb2f1f22b404e222ff','bab89b67597e0390f41ec211d4328bb343e680f3170bf764b14b3810c562f30d','محدّث','2026-09-06T01:49:32.886Z','2026-10-07T20:25:22.791Z','','',0,0,'saudi_region','عادي',61,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الاقتصاد والأسواق","التقنية والتحول الرقمي","السياسة والعلاقات الدولية","روسيا","الصين","الرياض","أوروبا"]','["الطاقة والنفط","الاقتصاد والأسواق","التقنية والتحول الرقمي","السياسة والعلاقات الدولية","الولايات المتحدة"]','classified','','[{"category":"أخبار السعودية","score":4.5},{"category":"المناطق","score":1.5},{"category":"المجتمع","score":1.5}]','Updated','2026-10-07T19:42:54.503Z',200,20,0,'source_content_changed','',NULL,NULL,'body:a08d831de592bfe65f06b1f6558e92a75cf1317366f587c245527508e77179a4','Wed, 07 Oct 2026 19:42:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bdc48f88-8762-40b2-a9d6-c1369df62151','news-bdc48f88-8762-40b2-a9d6-c1369df62151','الأهلي لم يطلب التأجيل..؟','الاهلي لم يطلب التاجيل','الرابطة، مشكورة، تجاوبت مع مطالبنا وأكدت أن النادي الأهلي لم يطلب أي تأجيل. ما قصرت، وصل صوتك ومطالبك للنادي الأهلي، الذي للأسف ثبت رسمياً أنهم لم يفكروا إطلاقاً في طلب تأجيل أي مباراة قبل نهائي القارات.','["ملأنا البرامج احتجاجاً ومطالبات بضرورة تأجيل بعض المباريات للأهلي قبل مواجهة صن داونز، وتعاطف معنا كل الزملاء وأيدوا ما طالبنا به واعتبروه حقاً مشروعاً لممثل الوطن. إلا أن الصدمة جاءت من داخل النادي الذي كنا نتوقع أن يطالب الرابطة بتأجيل بعض المباريات، وهذا شيء طبيعي، ويا ليت الأمر توقف عند صمتهم، بل سرب أحد الأعضاء معلومة ينفي فيها حتى التفكير في طلب التأجيل، كون هذه المباريات تمثل استعداداً قوياً للنهائي.","الرابطة، مشكورة، تجاوبت مع مطالبنا وأكدت أن النادي الأهلي لم يطلب أي تأجيل. فماذا بعد هذه الصدمة يمكن أن نقول؟","ربما هم أدرى وأعرف مع جهازهم الفني بما يخدم مصالحهم، لكن السؤال هنا: من بطل هذه الفعلة؟ بيدرو المطرود أم جهاز فني وضع الجدول قبل أن يصل جدة؟","ما هي الفائدة التي يجنيها الأهلي من هذا الجدول المضغوط؟","ركزوا في الجدول: الخلود الدوري 29 أغسطس، الهلال الدوري 1 سبتمبر، الرياض الدوري 4 سبتمبر، القادسية الدوري 8 سبتمبر، الحزم الدوري 11 سبتمبر، باختاكور النخبة 14 سبتمبر، صن داونز 19 سبتمبر.","وبعد التركيز في المواعيد والملاعب، هل من حقنا نطالب، أم الحق مع زملاء بيدرو، أم مع مدرب لم يحضر إلا متأخراً؟","ما قصرت، وصل صوتك ومطالبك للنادي الأهلي، الذي للأسف ثبت رسمياً أنهم لم يفكروا إطلاقاً في طلب تأجيل أي مباراة قبل نهائي القارات.","تأكدت بما لا يدع مجالاً للشك، أن جمهور هذا النادي على مر التاريخ يفهمون كرة القدم ويستشعرون خطورة ما يواجهون أكثر ممن يسيّرون القرار داخل النادي."]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264573','https://www.okaz.com.sa/articles/authors/2264573','','https://www.okaz.com.sa/articles/authors/2264573','أحمد الشمراني','الرياض','2026-09-05T18:00:00.000Z','Wed, 07 Oct 2026 19:42:56 GMT','2026-09-07T05:30:45.508Z','https://www.okaz.com.sa/okaz/uploads/authors/216.jpg?v=1763061547','/api/media/bdc48f88-8762-40b2-a9d6-c1369df62151','/api/media/bdc48f88-8762-40b2-a9d6-c1369df62151?variant=thumbnail','الأهلي لم يطلب التأجيل..؟',400,400,'valid','published','archived','valid',57,'33db3c6f43054066deae037fc3f3147b7d637c108bb87f598cf57fccc3746b5b','9a9f1293b709258c1e49a56af58e0db1d25e597543bdbf16c19f25dbd2bf8539','محدّث','2026-09-06T01:49:34.133Z','2026-10-07T20:25:22.791Z','','',0,0,'saudi_region','عادي',49,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","الرياضة السعودية","جدة","الرياض"]','["الثقافة والفنون","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":-2},{"category":"السياسة","score":-5}]','Updated','2026-10-07T19:42:57.912Z',200,20,0,'source_content_changed','',NULL,NULL,'body:9f7c9746f045c25e454a6ac7ced8465f8d12069c15244f710ba0c2ea1233eb5a','Wed, 07 Oct 2026 19:42:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7a1178e8-13be-49b3-95ee-93648b14924b','news-7a1178e8-13be-49b3-95ee-93648b14924b','الأمن والتاريخ (٣)','الامن والتاريخ ٣','عمق مؤتمر الأمن والتاريخ، أعمق مما قيل ويقال، إن نحن تنبهنا لعمق المفردتين، فكل مفردة منهما لها عمق سحيق، يستوجب الغوص في المفردتين. أقول ورثة الأزمان والسلطة السابقة، وإن كان الأمر يتعلق بالدين أو بالجغرافيا فنحن معنيون بذلك في كل السرديات السابقة، وحين أتكلم عن تاريخ الجزيرة العربية، أعمّق قولي بحثاً عن تلك السرديات التي كُتبت عن السجلات التاريخية…','["عمق مؤتمر الأمن والتاريخ، أعمق مما قيل ويقال، إن نحن تنبهنا لعمق المفردتين، فكل مفردة منهما لها عمق سحيق، يستوجب الغوص في المفردتين.","فلنا وجود سابقاً وحاضراً، وأثمّن تثميناً فخماً لوزارة الداخلية اختيار هذا العنوان، فهو عنوان يمكن التوغل فيه إلى أبعد نقطة في التاريخ، فالجزيرة العربية (ونحن نمثل مساحة كبيرة منها تكاد تكون هي الجزيرة نفسها، أيضا نحن ورثة لكل الأزمان السابقة)، ولذلك تأتي أهمية التاريخ في العنوان.","أقول ورثة الأزمان والسلطة السابقة، وإن كان الأمر يتعلق بالدين أو بالجغرافيا فنحن معنيون بذلك في كل السرديات السابقة، وحين أتكلم عن تاريخ الجزيرة العربية، أعمّق قولي بحثاً عن تلك السرديات التي كُتبت عن السجلات التاريخية للجزيرة العربية، نعم كانت في البدايات الأولى مجاميع من القبائل تعيش على هذه الأرض حتى ظهر الرسول صلى الله عليه وسلم، ومن خلال (وثيقة المدينة) كون أول نواة لنظام الدولة، ومع الخلفاء (من عهد الخلفاء الراشدين، وبعدهم الأمويون، والعباسيون، والعثمانيون، اتسعت الدولة الإسلامية في جهات العالم حتى غدت إمبراطورية، وقد مثّل القرشيون ثلاثة أرباع الخلافة الإسلامية (إذ كان الانتماء لقريش صلباً ونسباً شرطاً إلزامياً أن يكون الخليفة قرشياً)، ومع الخلافة العثمانية، حدثت الحربان العالميتان الأولى والثانية، وكانت نتيجة الحرب العالمية الأولى توقيع اتفاقية سايس بيكو ١٩١٦م، تم الاتفاق فيها على توزيع دول الخلافة العثمانية (العربية منها) ورسم الحدود الحالية.. في هذا الوضع العالمي لم يتم احتلال المملكة، أو إضافتها لأي دولة كانت، ولم تظل في نزاع إزاء أي استعمار، أو وصاية، ونتذكر الدولة السعودية الأولى، وحربها ضد محمد علي باشا بإيعاز من الخلافة العثمانية، والذي أريد قوله، إن السعودية ظلت حرة أبية، ومع مجيء القائد العظيم عبدالعزيز بن عبدالرحمن بن فيصل، استطاع بالحنكة ونفاذ البصيرة توحيد المملكة العربية السعودية ليسود الأمن على هذه الدولة القارية.. في كل مرحلة زمنية من عهد الرسول صلى الله عليه وسلم وهي مركز العالم الإسلامي. هذا السجل التاريخي الممتد لنا فيه كتابة، ووجود.","هذه الأرض لديها سجل ضخم تاريخاً ووجوداً.. فهل نستوعب مفردتي الأمن والتاريخ؟"]','أخبار السعودية','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264572','https://www.okaz.com.sa/articles/authors/2264572','','https://www.okaz.com.sa/articles/authors/2264572','عبده خال','','2026-09-05T18:00:00.000Z','Wed, 07 Oct 2026 19:42:55 GMT','2026-09-07T05:30:45.540Z','https://www.okaz.com.sa/okaz/uploads/authors/238.jpg?v=1768301522','/api/media/7a1178e8-13be-49b3-95ee-93648b14924b','/api/media/7a1178e8-13be-49b3-95ee-93648b14924b?variant=thumbnail','الأمن والتاريخ (٣)',361,400,'valid','published','archived','valid',44,'a9561d5f8c8457f154c57671f45ef2fde2149018da15739a71574ae84dc7e0e4','0c7384492d5e4830ac658b93ca0f5e8b3dfc4c678034a067e5fe6afe16ecc9dd','محدّث','2026-09-06T01:49:34.571Z','2026-10-07T19:42:57.837Z','','',0,0,'saudi_national','مهم',81,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','needs_review','below_category_threshold','[{"category":"الثقافة","score":3},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Updated','2026-10-07T19:42:57.837Z',200,20,0,'source_content_changed','',NULL,NULL,'body:b5e15e3ca86a50ee44cc9decbaeb3d35180910e141a74389e87d4a4edf8014d8','Wed, 07 Oct 2026 19:42:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8a5117be-d7d0-45fd-a961-a55c43268f2b','news-8a5117be-d7d0-45fd-a961-a55c43268f2b','أخطر ما في الإدارة.. أن نعتقد أننا وحدنا نرى','اخطر ما في الاداره ان نعتقد اننا وحدنا نري','جميعنا، بدرجات متفاوتة، أسرى لما يسمى في علم السلوك بـ «انحياز التأكيد».. من المبادئ التي أحاول أن أتمسك بها في عملي وفي الأمور الشخصية، أن الرأي الآخر ضرورة، حتى عندما أكون مقتنعاً بأنني لن آخذ به.','["ليس كل من ينظر يرى. هناك من يرى بعينيه، من يرى بقلبه، ومن يرى بعقله وتجربته. وهناك، للأسف، من يمتلك البصر كاملاً لكنه يفتقد البصيرة. وربما يكون النوع الآخر هو الأكثر خطورة في عالم الإدارة.. لأنه لا يعرف أنه لا يرى. في مجالس إدارات الشركات، كما في الحياة، لا تكمن المشكلة عادة في نقص الآراء، بل في قدرتنا على احتمال الرأي الذي لا يعجبنا. فالإنسان بطبيعته يحب من يؤكد له أنه كان على حق. والرئيس التنفيذي ليس استثناءً ولا رئيس مجلس الإدارة ولا المساهم ولا حتى المستشار الذي يفترض فيه الاستقلال. جميعنا، بدرجات متفاوتة، أسرى لما يسمى في علم السلوك بـ «انحياز التأكيد».. نبحث عما يؤيد قناعاتنا ونجد ألف سبب للتشكيك في ما يناقضها. ولهذا فإن أخطر مجلس إدارة ليس بالضرورة ذلك الذي تكثر فيه الخلافات، بل ربما ذلك الذي يتفق أعضاؤه دائماً. الإجماع السريع مريح. لكنه قد يكون مكلفاً. من المبادئ التي أحاول أن أتمسك بها في عملي وفي الأمور الشخصية، أن الرأي الآخر ضرورة، حتى عندما أكون مقتنعاً بأنني لن آخذ به. فأنا لا أستمع إليه بالضرورة لكي يغير قراري، بل لكي يختبره. والفرق كبير. قد يقول لك شخص شيئاً ترفض 90% منه، لكن الـ10% الباقية قد تكشف مخاطرة لم ترها أو افتراضاً لم تختبره أو سؤالاً كان ينبغي أن تسأله منذ البداية. هنا تأتي أهمية المراجعة.كي تسأل.. هل ما زالت الإستراتيجية التي أوصلتنا إلى هنا قادرة على إيصالنا إلى هناك؟ هذا السؤال يبدو بسيطاً. لكنه في الحقيقة شديد الصعوبة. لأن مراجعة الإستراتيجية تتطلب شيئاً أصعب من إعدادها.. أن نعترف بأن العالم تغير وربما علينا أن نتغير معه. المراجعة ليست اعترافاً بالفشل. وتغيير الرأي ليس ضعفاً. والعودة عن قرار لم تعد افتراضاته صحيحة ليست هزيمة إدارية. الهزيمة الحقيقية هي أن نعرف أن الطريق تغير ثم نستمر فيه فقط لأننا اخترناه بالأمس. لذلك أدعو نفسي قبل الآخرين إلى ممارسة أمر يبدو سهلاً في الكلام وصعباً في الواقع.. أن أتقبل من يخالفني وأن أستمع إليه حتى النهاية بل وأن أشكره. أشكره ليس لأنني سأتبنى رأيه بالضرورة وإنما لأنه منحني شيئاً لا يستطيع الموافقون دائماً أن يمنحوني إياه.. زاوية أخرى للرؤية. في النهاية.. القرارات الكبرى نادراً ما تفشل لأن أصحابها لم تكن لديهم معلومات كافية فقط. أحياناً تفشل لأن الجميع كانوا ينظرون إلى المشهد من النافذة نفسها. نحن لا نحتاج دائماً إلى من يرى ما نراه. نحتاج أحياناً وبشكل أكثر إلحاحاً إلى من يرى ما لا نراه.","Not everyone who looks sees. There are those who see with their eyes, those who see with their hearts, and those who see with their minds and experiences. Unfortunately, there are also those who have complete sight but lack insight. Perhaps this latter type is the most dangerous in the world of management... because they do not know that they do not see. In corporate boards, as in life, the problem usually does not lie in the lack of opinions, but in our ability to tolerate the opinion we do not like. By nature, humans prefer those who confirm that they were right. The CEO is no exception, nor is the chairman of the board, the shareholder, or even the advisor who is supposed to be independent. All of us, to varying degrees, are prisoners of what is called in behavioral science \"confirmation bias\"... we seek what supports our convictions and find a thousand reasons to doubt what contradicts them. Therefore, the most dangerous board is not necessarily the one with many disagreements, but perhaps the one whose members always agree. Quick consensus is comfortable. But it can be costly. One of the principles I try to adhere to in my work and personal matters is that the other opinion is a necessity, even when I am convinced that I will not adopt it. I do not necessarily listen to it to change my decision, but to test it. The difference is significant. Someone might tell you something that you reject 90% of, but the remaining 10% might reveal a risk you had not seen, an assumption you had not tested, or a question you should have asked from the beginning. Here comes the importance of review. Malaysia''s experience in reviewing its strategies deserves reflection from this angle. Countries, like companies, need, from time to time, the courage to ask... Is the strategy that brought us here still capable of taking us there? This question seems simple. But in reality, it is very difficult. Because reviewing the strategy requires something harder than preparing it... to acknowledge that the world has changed and perhaps we need to change with it. Review is not an admission of failure. Changing one''s mind is not weakness. Reversing a decision whose assumptions are no longer valid is not administrative defeat. The real defeat is to know that the path has changed and then to continue on it just because we chose it yesterday. Therefore, I invite myself before others to practice something that seems easy to say and difficult in reality... to accept those who disagree with me and to listen to them until the end, and even to thank them. I thank them not because I will necessarily adopt their opinion, but because they have given me something that those who agree with me cannot always provide... another angle of vision. In the end... major decisions rarely fail because their owners did not have enough information. Sometimes they fail because everyone was looking at the scene from the same window. We do not always need someone who sees what we see. Sometimes, and more urgently, we need someone who sees what we do not see."]','الصحة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2264574','https://www.okaz.com.sa/articles/authors/2264574','','https://www.okaz.com.sa/articles/authors/2264574','سلمان الجشي','عسير','2026-09-05T18:00:00.000Z','Wed, 07 Oct 2026 19:42:55 GMT','2026-09-06T15:06:08.346Z','https://www.okaz.com.sa/okaz/uploads/authors/1898.jpg?v=1778328290','/api/media/8a5117be-d7d0-45fd-a961-a55c43268f2b','/api/media/8a5117be-d7d0-45fd-a961-a55c43268f2b?variant=thumbnail','أخطر ما في الرؤية.. أن نعتقد أننا وحدنا نرى',600,600,'valid','published','archived','valid',41,'f42b124bff4a59d7251ae52d9335a0a2d6bb23d08c4eb5332cc8f321618e0d6d','6127dd0a9d8c2ee7632b79792967e17d43ac185e6a091de5a58947c8bb3c049d','محدّث','2026-09-06T01:49:38.820Z','2026-10-07T20:25:22.791Z','','',0,0,'saudi_region','عادي',49,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس الإدارة ولا المساهم ولا","رئيس مجلس الإدارة ولا المساهم"]','["مجلس الإدارة ولا المساهم ولا","رئيس مجلس الإدارة ولا المساهم"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Updated','2026-10-07T19:42:57.395Z',200,20,0,'source_content_changed','',NULL,NULL,'body:4c87d1f57d5e4e3705ba5beb84f2098398329317f5ee3a66f987688e7ecdbf76','Wed, 07 Oct 2026 19:42:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('aa000ce6-051f-4150-a87a-58707545a951','news-aa000ce6-051f-4150-a87a-58707545a951','اختتام فعاليات معرض فرص الامتياز التجاري الدولي في نسخته الرابعة بجدة','اختتام فعاليات معرض فرص الامتياز التجاري الدولي في نسخته الرابعه بجده','اختتمت مساء اليوم أعمال النسخة الرابعة من معرض فرص الامتياز التجاري الدولي والشراكات الاستثمارية، الذي نظمته غرفة جدة بمركز جدة للمعارض والفعاليات خلال الفترة من 3 إلى 5 سبتمبر الجاري.','["وشهد المعرض مشاركة علامات تجارية عالمية، مما رسخ مكانته وجهةً موثوقة للشركات الطامحة للتوسع في السوق السعودي ، ومنح الزوار فرصة استثنائية للاطلاع على أنجح نماذج الامتياز وأكثرها ابتكارًا، معززًا دوره كمركز رئيس لدعم المنشآت الصغيرة والمتوسطة عبر بناء شراكات نوعية وربطها مباشرةً بأهم العلامات التجارية في مختلف القطاعات الحيوية.","وتضمنت فعاليات المعرض جلسات وورش عمل تناولت إستراتيجيات التوسع، وإدارة العلامات التجارية، وتجربة العملاء؛ وهي موضوعات اكتسبت أهمية بالغة لرواد الأعمال والمستثمرين، إذ تساعدهم على فهم الجوانب العملية لتقييم فرص الامتياز بعيدًا عن الاكتفاء بشهرة العلامة التجارية.","وشكّل المعرض منصة اقتصادية للتواصل بين أطراف منظومة الامتياز التجاري، وقادة الفكر، ورجال الأعمال، مما فتح آفاقًا جديدة للنمو والتطوير المهني، وأتاح للمنشآت الناشئة والصغيرة الاطلاع على أفضل الممارسات العالمية، ودعم اتخاذ قرارات استثمارية احترافية.","يُذكر أن قطاع الامتياز التجاري في السعودية يواصل تحقيق معدلات نمو ملحوظة، مدعومًا بتطوير البيئة التشريعية، وإصدار نظام الامتياز التجاري ولائحته التنفيذية، إلى جانب المبادرات الحكومية الرامية لتحفيز الاستثمار في العلامات التجارية الوطنية، مما أسهم في رفع مستوى الشفافية وحماية الحقوق."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/lfws1jge3','https://ajel.sa/economy/lfws1jge3','https://ajel.sa/economy/lfws1jge3','https://ajel.sa/economy/lfws1jge3','فريق التحرير','مكة المكرمة','2026-09-05T20:23:00.000Z','Wed, 07 Oct 2026 20:59:36 GMT','2026-09-06T02:38:10.049Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop-I0c5VVn6.png','/api/media/aa000ce6-051f-4150-a87a-58707545a951','/api/media/aa000ce6-051f-4150-a87a-58707545a951?variant=thumbnail','اختتام فعاليات معرض فرص الامتياز التجاري الدولي في نسخته الرابعة بجدة',1200,675,'valid','published','archived','valid',40,'e8976425f4eae554ab75b7b9f49a24b9d77904874635fde7236ef35bc5b17ac4','543fd789b86dadfad359a50878c9056fdafad089e1213475de6b0b20288d3724','محدّث','2026-09-06T02:38:10.049Z','2026-10-07T20:59:37.964Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس لدعم المنشآت الصغيرة والمتوسطة","الاقتصاد والأسواق","جدة"]','["رئيس لدعم المنشآت الصغيرة والمتوسطة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"البيئة والمناخ","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T20:59:37.964Z',200,21,0,'source_content_changed','',NULL,NULL,'body:83823864fb698bbdcf43fd248a66f554e3c28bd58aecefa37d211b66dd990ef1','Wed, 07 Oct 2026 20:59:36 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e2e40922-826a-45a2-818a-0863074815b8','news-e2e40922-826a-45a2-818a-0863074815b8','تتويج ملاك الهجن الفائزين بكؤوس مهرجان ولي العهد لفئة «الحقايق» بالطائف','تتويج ملاك الهجن الفائزين بكؤوس مهرجان ولي العهد لفئه الحقايق بالطائف','وانتزع "الزعيم" لمالكه موسى الموسى كأس "قعدان - مفتوح"، مسجلًا زمنًا قدره (2:52.705) دقيقة، وهو التوقيت الأفضل في الأشواط الختامية لفئة "الحقايق". وشهد اليوم إقامة (33) شوطًا، توزعت على (21) شوطًا عامًا، و(6) أشواط مفتوحة، و(6) أشواط على كؤوس مهرجان ولي العهد، وسط حضور جماهيري، فيما سجلت الهجن السعودية خلال الفترة الصباحية (17) فوزًا من أصل (21) شوطًا،…','["توَّج الأمير فهد بن جلوي بن عبدالعزيز بن مساعد رئيس مجلس إدارة الاتحاد السعودي للهجن ، اليوم، ملاك الهجن الفائزين بكؤوس مهرجان ولي العهد للهجن لفئة \"الحقايق\"، وكأسي المهرجان للإنتاج السعودي، على أرض ميدان الطائف التاريخي لسباقات الهجن.","وتقام النسخة الثامنة من المهرجان تحت رعاية صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء -حفظه الله-، وتستمر حتى الـ(13) من سبتمبر الجاري، بتنظيم الاتحاد السعودي للهجن، وبجوائز مالية تتجاوز (50) مليون ريال.","وانتزع \"الزعيم\" لمالكه موسى الموسى كأس \"قعدان - مفتوح\"، مسجلًا زمنًا قدره (2:52.705) دقيقة، وهو التوقيت الأفضل في الأشواط الختامية لفئة \"الحقايق\".","وذهبت ثلاثة كؤوس للهجن الإماراتية، بعد فوز \"فخر\" لمالكها حمد العامري بكأس \"بكار - مفتوح\" بزمن (2:57.651) دقيقة، و\"صروح\" لمالكها مانع الشامسي بكأس \"بكار - عام\" بتوقيت (2:57.699) دقيقة، و\"جلمود\" لمالكها حمد العامري بكأس “قعدان - عام” مسجلًا (2:57.673) دقيقة.","وفي شوطي الإنتاج السعودي، توّجت \"وعد\" لمالكها عقاب الدهاسي بكأس \"بكار - عام\" بعد تسجيلها (2:55.901) دقيقة، فيما حصد \"منادي\" لمالكه نايف السهلي كأس \"قعدان - عام\" بزمن (3:00.189) دقائق.","وشهد اليوم إقامة (33) شوطًا، توزعت على (21) شوطًا عامًا، و(6) أشواط مفتوحة، و(6) أشواط على كؤوس مهرجان ولي العهد، وسط حضور جماهيري، فيما سجلت الهجن السعودية خلال الفترة الصباحية (17) فوزًا من أصل (21) شوطًا، مقابل (3) انتصارات للهجن القطرية، وفوز واحد للهجن الإماراتية.","ويشهد المهرجان مشاركة واسعة من ملاك الهجن محليًا ودوليًا، ضمن جهوده لتعزيز حضور رياضة الهجن والمحافظة على موروثها، وإبراز امتدادها الثقافي والاقتصادي، من خلال فعاليات متنوعة تسهم في استدامة هذا الموروث وتعكس عمقه الحضاري في المملكة."]','أخبار السعودية','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/n5iv2m2bh','https://ajel.sa/sports/n5iv2m2bh','https://ajel.sa/sports/n5iv2m2bh','https://ajel.sa/sports/n5iv2m2bh','فريق التحرير','','2026-09-05T20:22:00.000Z','Wed, 07 Oct 2026 20:59:04 GMT','2026-09-06T02:38:10.551Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop-WzAnXecI.png','/api/media/e2e40922-826a-45a2-818a-0863074815b8','/api/media/e2e40922-826a-45a2-818a-0863074815b8?variant=thumbnail','تتويج ملاك الهجن الفائزين بكؤوس مهرجان ولي العهد لفئة «الحقايق» بالطائف',1200,675,'valid','published','archived','valid',99,'0173c637d20a922d0012fa9a8be86192600c359955a3a13389c7a6508f44d9e1','911e3ca2d7a620b1e1ec04138ba06c319c328f7a524f864c593297910b4bc5a3','محدّث','2026-09-06T02:38:10.551Z','2026-10-07T20:59:05.667Z','','',0,0,'saudi_national','مهم',77,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","ولي العهد لفئة الحقايق بالطائف","رئيس مجلس إدارة الاتحاد السعودي","مجلس إدارة الاتحاد السعودي للهجن","الرياضة السعودية","الاقتصاد والأسواق"]','["ولي العهد لفئة الحقايق بالطائف","رئيس مجلس إدارة الاتحاد السعودي","مجلس إدارة الاتحاد السعودي للهجن","الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:59:05.667Z',200,21,0,'source_content_changed','',NULL,NULL,'body:6e7cee8d0d9eb9ea7e4dcd51270bb5e1845251e80c830808c5251cbf64751d46','Wed, 07 Oct 2026 20:59:04 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('704a9f78-687f-4576-a9be-d628ec31f3a8','news-704a9f78-687f-4576-a9be-d628ec31f3a8','«محامٍ»: إجازة مدفوعة لمريض الفشل الكلوي يوم الغسيل في القطاع الخاص','محام اجازه مدفوعه لمريض الفشل الكلوي يوم الغسيل في القطاع الخاص','أكد المحامي عبداللطيف النعيم أن مريض الفشل الكلوي العامل في القطاع الخاص يُمنح إجازة مدفوعة الأجر في اليوم الذي يُجرى له فيه الغسيل الكلوي لتنقية الدم.','["وأوضح النعيم أن منح الإجازة يكون بموجب تقرير صادر من الجهة الطبية التي تتولى علاج المريض، أسوةً بأمثاله من العاملين في الدولة، فيما يتحمل صندوق تنمية الموارد البشرية أجر هذا اليوم.","وأشار إلى أن ذلك يأتي وفقًا لقرار مجلس الوزراء رقم (107) وتاريخ 8/4/1429هـ."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/Gd8xwQU','https://sabq.org/article/Gd8xwQU','','https://sabq.org/article/Gd8xwQU','سعد الراشد','','2026-09-05T20:53:00.000Z','2026-09-05T23:53:00.000Z','2026-09-06T03:00:11.997Z','https://media.sabq.org/news/2026/09/5a926ca1-2547-43d9-a81c-fd469e1b794f/w1206.webp','/api/media/704a9f78-687f-4576-a9be-d628ec31f3a8','/api/media/704a9f78-687f-4576-a9be-d628ec31f3a8?variant=thumbnail','«محامٍ»: إجازة مدفوعة لمريض الفشل الكلوي يوم الغسيل في القطاع الخاص',1206,1796,'valid','published','archived','valid',41,'263ed7c2af936c1824c06da6a19b8348c07cadd70d360806be0840b7c565096a','853ca8faa9f9b49e3a7d6448f4abb3375b01e5d017cf2fff948d44cac779df92','محدّث','2026-09-06T03:00:11.997Z','2026-10-07T21:01:52.787Z','','',0,0,'saudi_national','مهم',76,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس الوزراء رقم","الصحة العامة"]','["مجلس الوزراء رقم","الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:01:52.787Z',200,20,0,'source_article_available','',NULL,NULL,'body:21c38cd5baf773076bd062d848ac5267de23377a0b2a48bf6763dc07669c44c4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c1ad8d2c-3738-4aee-a6d1-db5d6869c0b4','news-c1ad8d2c-3738-4aee-a6d1-db5d6869c0b4','المهر «رأس المال» يتوَّج بكأس الطائف للسرعة في ختام الأسبوع السابع من موسم سباقات الطائف','المهر راس المال يتوج بكاس الطائف للسرعه في ختام الاسبوع السابع من موسم سباقات الطائف','وشهد الأسبوع إقامة (22) شوطًا، بواقع (11) شوطًا في كل أمسية، بمشاركة نخبة من الجياد والملاك والمدربين والخيالة، وسط حضور جماهيري ومجموعة من الفعاليات المصاحبة.','["توّج المهر \"رأس المال\" بشعار الشيخ عبدالله حمود المالك الصباح اليوم، بكأس الطائف للسرعة، في أبرز نتائج ختام الأسبوع السابع من موسم سباقات الطائف، الذي أقيم على ميدان الملك خالد للفروسية على مدى يومي الجمعة والسبت.","وسلّم الأمير سلمان بن عبدالله بن سلمان بن محمد الرئيس التنفيذي لنادي سباقات الخيل، الكأس للمدرب عبدالله السدراني والخيّال محمد الدهام، عقب فوز \"رأس المال\" بالشوط المخصص لخيل السنتين على مسافة (1200) متر، وبجائزة مالية قدرها (350) ألف ريال، مسجلًا زمنًا بلغ (1:19.01) دقيقة.","وفي أبرز نتائج سباقات الجمعة، حققت الفرس \"نايت أوف دسري\"، بشعار الوليد ثامر مناحي العصيمي، المركز الأول في الشوط التحضيري لبطولة ميدان الملك خالد للأفراس، الذي أقيم على مسافة (1400) متر، وبجائزة قدرها (120) ألف ريال، مسجلةً زمنًا بلغ (1:32.01) دقيقة.","وفاز المهر \"النجم الساطي\"، بشعار أبناء الملك عبدالله بن عبدالعزيز، بالشوط التحضيري لتحدي نادي سباقات الخيل لمسافة (1600) متر، وبجائزة مالية قدرها (120) ألف ريال، بزمن (1:46.90) دقيقة.","وفي الشوط التحضيري لبطولة ميدان الملك خالد حصد الجواد \"ودعتك الله\"، بشعار إسطبل الخليبص، المركز الأول لمسافة (1600) متر، وبجائزة قدرها (120) ألف ريال، مسجلًا (1:45.11) دقيقة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/r9FarD5','https://sabq.org/article/r9FarD5','','https://sabq.org/article/r9FarD5','صحيفة سبق','','2026-09-05T20:53:00.000Z','2026-09-05T23:53:00.000Z','2026-09-06T03:00:12.655Z','https://media.sabq.org/news/2026/09/72a472c9-de11-4efa-8022-0cd73815eedd/w660.webp','/api/media/c1ad8d2c-3738-4aee-a6d1-db5d6869c0b4','/api/media/c1ad8d2c-3738-4aee-a6d1-db5d6869c0b4?variant=thumbnail','المهر «رأس المال» يتوَّج بكأس الطائف للسرعة في ختام الأسبوع السابع من موسم سباقات الطائف',660,440,'valid','published','archived','valid',53,'387055a0477fd5263dddd2a157ec43d7f93f4c24aa5572669f042061fba02e4c','b5a6215c683184786d7ded4dd85f20fdd2da937005b2c4e33f401e18f5c69aa6','محدّث','2026-09-06T03:00:12.655Z','2026-10-07T21:01:48.403Z','','',0,0,'international','عادي',40,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T21:01:48.403Z',200,21,0,'source_article_available','',NULL,NULL,'body:f873073dc6aa7c08160143a7ffdbd6f9bf93c01188bdc5afe4ffb531b6c25696','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ed953181-f52c-407c-a80a-60adb0535d6b','news-ed953181-f52c-407c-a80a-60adb0535d6b','استشهاد فلسطينية وإصابة 9 آخرين في قصف إسرائيلي على قطاع غزة','استشهاد فلسطينيه واصابه 9 اخرين في قصف اسرائيلي علي قطاع غزه','وأفادت مصادر طبية باستشهاد سيدة متأثرة بجراح أصيبت بها جراء قصف إسرائيلي سابق على مخيم المغازي وسط قطاع غزة . واليوم، ارتفعت حصيلة ضحايا عدوان الاحتلال الإسرائيلي على قطاع غزة منذ السابع من أكتوبر 2023 إلى 73.651 شهيدًا 174.575 مصابًا.','["استشهدت سيدة فلسطينية اليوم، وأصيب 9 آخرون في قصف من قوات الاحتلال الإسرائيلي على قطاع غزة .","وأفادت مصادر طبية باستشهاد سيدة متأثرة بجراح أصيبت بها جراء قصف إسرائيلي سابق على مخيم المغازي وسط قطاع غزة .","وأصيب 9 فلسطينيين بجراح بينهم طفلة، جراء غارة جوية إسرائيلية قرب مفترق \"السنافور\" بحي \"التفاح\" شمال شرقي مدينة غزة.","كما أطلقت طائرة مسيرة إسرائيلية قنبلتين في أجواء المناطق الشرقية ل حي الزيتون جنوب شرقي المدينة، دون أن يبلغ عن وقوع إصابات، وذلك بالتزامن مع قصف مدفعي متواصل يستهدف المناطق الشرقية للمدينة.","واليوم، ارتفعت حصيلة ضحايا عدوان الاحتلال الإسرائيلي على قطاع غزة منذ السابع من أكتوبر 2023 إلى 73.651 شهيدًا 174.575 مصابًا."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/fbuldmt9s','https://ajel.sa/international/fbuldmt9s','https://ajel.sa/international/fbuldmt9s','https://ajel.sa/international/fbuldmt9s','فريق التحرير','المنطقة الشرقية','2026-09-05T21:23:00.000Z','Mon, 07 Sep 2026 02:48:26 GMT','2026-09-06T03:36:10.725Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%BA%D8%B2%D8%A9-AFLwxN3y.png','/api/media/ed953181-f52c-407c-a80a-60adb0535d6b','/api/media/ed953181-f52c-407c-a80a-60adb0535d6b?variant=thumbnail','استشهاد فلسطينية وإصابة 9 آخرين في قصف إسرائيلي على قطاع غزة',1200,675,'valid','published','archived','valid',97,'ba119582a2e961d3dd575eb4b44bbff600a79f5231dc73a8957e780403ff088b','fdf04246483bbeec7168a8778aebebf20f2da73829d86f13117f8964573ad572','محدّث','2026-09-06T03:36:10.725Z','2026-10-07T20:25:22.791Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","غزة","فلسطين"]','["الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Temporarily Unreachable','2026-10-07T19:41:38.634Z',NULL,19,4,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fb3e811a-8b13-4d42-8870-1e6e82e98e1e','news-fb3e811a-8b13-4d42-8870-1e6e82e98e1e','سوريا تعلن القبض على قائد لواء سابق بتهمة ارتكاب جرائم حرب','سوريا تعلن القبض علي قائد لواء سابق بتهمه ارتكاب جرائم حرب','أعلن الأمن الداخلي في اللاذقية السورية القبض على اللواء جلال كامل صقر، قائد اللواء 18 مشاة في قوات نظام الأسد، على خلفية اتهامات بالمشاركة في جرائم حرب وعمليات اعتقال تعسفي بحق مدنيين خلال سنوات الثورة.','["وقال الأمن الداخلي إن جلال صقر شارك في العمليات العسكرية ضد المدنيين في محافظة دمشق والغوطة الشرقية، كما أشرف على حملات اعتقال تعسفي في محافظة درعا .","وأضاف أن توقيفه يأتي على خلفية تورطه في تلك الانتهاكات التي ارتُكبت بحق المدنيين خلال سنوات الثورة."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/j0868wnmz','https://ajel.sa/international/j0868wnmz','https://ajel.sa/international/j0868wnmz','https://ajel.sa/international/j0868wnmz','فريق التحرير','ال