INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b0e9331b-c797-4d0b-bb65-5315a67b1334','news-b0e9331b-c797-4d0b-bb65-5315a67b1334','أمين عام ARCO يلتقي أمين عام جامعة الدول العربية لبحث تحديات العمل الإنساني','امين عام arco يلتقي امين عام جامعه الدول العربيه لبحث تحديات العمل الانساني','التقى أمين عام المنظمة العربية للهلال الأحمر والصليب الأحمر «أركو» عبدالله بن سهيل المهيدلي، بأمين عام جامعة الدول العربية نبيل فهمي، في إطار مساعي تعزيز التنسيق العربي المشترك في الملفات الإنسانية.','["وتناول اللقاء جملةً من المحاور الرئيسية، أبرزها: آليات التعاون بين المنظمة والجامعة في مجال العمل الإنساني، والتحديات التي تواجه هذا القطاع في المنطقة العربية، وسُبل التغلب عليها والحدّ من آثار الأزمات والكوارث على المجتمعات المتضررة.","وتُعدّ المنظمة العربية للهلال الأحمر والصليب الأحمر «أركو» الإطارَ الجامع للعمل الإنساني العربي المشترك، فيما تضطلع جامعة الدول العربية بدور محوري في تنسيق المواقف والجهود العربية على المستويين الإقليمي والدولي."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/D5nfz3X','https://sabq.org/article/D5nfz3X','','https://sabq.org/article/D5nfz3X','فهد العتيبي','','2026-09-06T14:36:00.000Z','2026-09-06T17:36:00.000Z','2026-09-06T20:40:21.551Z','https://media.sabq.org/news/2026/09/73830e0d-ae7c-4a83-a704-4047d6163d82/w962.webp','/api/media/b0e9331b-c797-4d0b-bb65-5315a67b1334','/api/media/b0e9331b-c797-4d0b-bb65-5315a67b1334?variant=thumbnail','أمين عام ARCO يلتقي أمين عام جامعة الدول العربية لبحث تحديات العمل الإنساني',962,1032,'valid','published','archived','valid',41,'060dffdbb06f829f20f3063fa15b35c650dd657c2b3ef09db683705ea5e85c2b','b629a8fed792023bc5311ab68388c32a31759e0b1b8777cac10fdc995df7ddcd','محدّث','2026-09-06T20:40:21.551Z','2026-10-07T20:49:59.400Z','','',0,0,'international','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة الدول العربية لبحث تحديات","التعليم والتدريب"]','["جامعة الدول العربية لبحث تحديات","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:49:59.400Z',200,11,0,'source_article_available','',NULL,NULL,'body:5e88dbde4a0d73d8232754ce289e6e36439a97958ee5568c3e5af0435ec72aaa','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('02cb7a50-a245-40b9-957c-56e55bb38f55','news-02cb7a50-a245-40b9-957c-56e55bb38f55','الهلال يتمسك بصدارة دوري روشن وقمة القادسية والأهلي تبرز في الجولة السادسة','الهلال يتمسك بصداره دوري روشن وقمه القادسيه والاهلي تبرز في الجوله السادسه','ويخوض الهلال المتصدر بـ(15) نقطة مواجهة الجولة السادسة غدًا أمام ضيفه نيوم على ملعب المملكة أرينا بالرياض، بعد أن حقق خمسة انتصارات متتالية منذ انطلاق الموسم، فيما يدخل نيوم اللقاء في المركز السابع بـ(9) نقاط، ساعيًا لمواصلة نتائجه الإيجابية والاقتراب من مراكز المقدمة.','["تنطلق غدًا الاثنين منافسات الجولة السادسة من دوري روشن السعودي للمحترفين، وسط سباق متصاعد على مراكز المقدمة، يتصدره الهلال بالعلامة الكاملة، فيما تبرز مواجهة القادسية والأهلي ضمن أبرز لقاءات الجولة التي تقام على مدى ثلاثة أيام.","وتُفتتح منافسات الجولة غدًا أيضًا بلقاء الخليج والرياض على ملعب الأمير محمد بن فهد بالدمام؛ إذ يدخل الخليج المواجهة في المركز السادس عشر بـ(3) نقاط باحثًا عن انتصاره الأول، فيما يحتل الرياض المركز الثاني عشر بـ(4) نقاط.","وتتواصل منافسات الجولة يوم الثلاثاء بأربع مواجهات؛ إذ يلتقي الاتفاق، صاحب المركز الثامن بـ(9) نقاط، مع الفيصلي على ملعب نادي الاتفاق بالدمام، فيما يستضيف الحزم نظيره التعاون على ملعب نادي الحزم بالرس.","وفي المواجهة الأبرز، تتجه الأنظار إلى ملعب الأمير محمد بن فهد بالدمام، الذي يحتضن قمة القادسية والأهلي، في لقاء يجمع فريقين يفصل بينهما ثلاث نقاط؛ إذ يدخل القادسية الجولة في المركز الثالث بـ(12) نقطة، مقابل (9) نقاط للأهلي صاحب المركز الخامس، ما يمنح المواجهة أهمية كبيرة في صراع المراكز المتقدمة.","وفي جدة، يستضيف الاتحاد نظيره الفيحاء على ملعب الإنماء بمدينة الملك عبدالله الرياضية؛ إذ يدخل الاتحاد اللقاء رابعًا بـ(11) نقطة ودون خسارة خلال الجولات الخمس الماضية، فيما يمتلك الفيحاء (5) نقاط، في مواجهة يسعى خلالها أصحاب الأرض إلى مواصلة المنافسة على مراكز المقدمة.","وتختتم منافسات الجولة يوم الأربعاء بثلاث مواجهات؛ إذ يلتقي في أولاها الخلود والشباب على ملعب نادي الحزم بالرس، فيما يستضيف الفتح نظيره الدرعية على ميدان تمويل الأولى بالأحساء، ويستقبل النصر نظيره أبها على ملعب الأول بارك بالرياض.","ويدخل النصر الجولة في المركز الثاني بـ(12) نقطة، متساويًا مع القادسية ومتأخرًا عن الهلال المتصدر بثلاث نقاط، في حين يحتل أبها المركز الثامن عشر بنقطة واحدة، ليبحث النصر عن العودة إلى طريق الانتصارات ومواصلة ملاحقة المتصدر."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/po99r9z','https://sabq.org/article/po99r9z','','https://sabq.org/article/po99r9z','صحيفة سبق','الرياض','2026-09-06T14:30:00.000Z','2026-09-06T17:30:00.000Z','2026-09-06T20:40:22.427Z','https://media.sabq.org/news/2026/08/8dc65da9-69b5-4bfc-b230-36cf16d68059/w1179.webp','/api/media/02cb7a50-a245-40b9-957c-56e55bb38f55','/api/media/02cb7a50-a245-40b9-957c-56e55bb38f55?variant=thumbnail','الهلال يتمسك بصدارة دوري روشن وقمة القادسية والأهلي تبرز في الجولة السادسة',1179,651,'valid','published','archived','valid',99,'4048c14c29967d50abe448388eb117275c4b7bc7f473534cee9c8b01cb05fc6e','c2719cd1d261e546063ac018b746089937c454b57b87481d0039cb5c1372f2f1','محدّث','2026-09-06T20:40:22.427Z','2026-10-07T20:50:00.079Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","جدة","الرياض","الدمام"]','["الرياضة السعودية"]','classified','','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":0}]','Active','2026-10-07T20:50:00.079Z',200,10,0,'source_article_available','',NULL,NULL,'body:c18f2c99b87a907d5df84a2a60693fad37454bfa9f59044317d449a4cd8e7841','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a4eef95f-7e6a-4591-a472-cb35afb7a1de','news-a4eef95f-7e6a-4591-a472-cb35afb7a1de','السعودية وألمانيا تؤسسان حوارًا استراتيجيًا دائمًا وتدعمان عودة "هرمز" لوضعه الطبيعي','السعوديه والمانيا تؤسسان حوارا استراتيجيا دائما وتدعمان عوده هرمز لوضعه الطبيعي','وجرى خلال اللقاء استعراض العلاقات الثنائية والتاريخية بين البلدين الصديقين، وبحث سبل تطويرها وتعزيزها على الصعيدين السياسي والاقتصادي. كما بحث الجانبان العلاقات الاقتصادية والتجارية بين البلدين، وحجم التبادل التجاري القائم، وسبل رفع مستواه بما يعكس عمق العلاقات ويفتح آفاقاً أوسع للتعاون والاستثمار المشترك.','["وقّع وزير الخارجية السعودي الأمير فيصل بن فرحان ووزير الخارجية الألماني يوهان فاديفول في برلين مذكرة تفاهم بين حكومة المملكة العربية السعودية وحكومة جمهورية ألمانيا الاتحادية، تقضي بإقامة حوار استراتيجي دائم على مستوى وزراء الخارجية، بهدف تعزيز التشاور والتنسيق وتطوير العلاقات الثنائية في مختلف المجالات.","وجرى خلال اللقاء استعراض العلاقات الثنائية والتاريخية بين البلدين الصديقين، وبحث سبل تطويرها وتعزيزها على الصعيدين السياسي والاقتصادي.","وتناول الجانبان الأوضاع الراهنة في المنطقة، مشددَين على أهمية أمن الممرات المائية الدولية وضمان حرية الملاحة البحرية فيها، وضرورة عودة مضيق هرمز إلى وضعه الطبيعي بما يعزز أمن المنطقة واستقرارها ويحافظ على انسيابية حركة التجارة الدولية، مؤكدَين دعمهما لجميع الجهود الرامية إلى إيجاد حلول سلمية ودبلوماسية للأزمات الإقليمية والدولية.","كما بحث الجانبان العلاقات الاقتصادية والتجارية بين البلدين، وحجم التبادل التجاري القائم، وسبل رفع مستواه بما يعكس عمق العلاقات ويفتح آفاقاً أوسع للتعاون والاستثمار المشترك."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/28o0em1','https://sabq.org/article/28o0em1','','https://sabq.org/article/28o0em1','صحيفة سبق','المدينة المنورة','2026-09-06T14:26:00.000Z','2026-09-06T17:28:00.000Z','2026-09-06T20:40:22.805Z','https://media.sabq.org/news/2026/09/9938ff94-7eca-481a-95a8-2210b94fc657/w1600.webp','/api/media/a4eef95f-7e6a-4591-a472-cb35afb7a1de','/api/media/a4eef95f-7e6a-4591-a472-cb35afb7a1de?variant=thumbnail','السعودية وألمانيا تؤسسان حوارًا استراتيجيًا دائمًا وتدعمان عودة "هرمز" لوضعه الطبيعي',1600,1218,'valid','published','archived','valid',53,'dc56d798d49cb8e1189c8f66df2b354abffd35874749793108420d7d606e0e9f','864adead972835d8790868ef7aff46f27a640d4068a5247e30e76c18e9196a96','محدّث','2026-09-06T20:40:22.805Z','2026-10-07T20:50:01.910Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الخارجية السعودي الأمير فيصل","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','["وزير الخارجية السعودي الأمير فيصل","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:50:01.910Z',200,12,0,'source_article_available','',NULL,NULL,'body:9b6358dd1c30e8dd2cabc656fbadd0a16063e540134abfc96b61b563162b2d6d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('20bde535-7c23-4230-85e5-634d11c59327','news-20bde535-7c23-4230-85e5-634d11c59327','مرور المدينة المنورة يضبط قائد مركبة خالف حدود المسارات المحددة','مرور المدينه المنوره يضبط قائد مركبه خالف حدود المسارات المحدده','ضبطت إدارة المرور بمنطقة المدينة المنورة قائد مركبة ارتكب مخالفة عدم الالتزام بحدود المسارات المحددة على الطريق. وأفادت الجهات المختصة بأن الإجراءات النظامية طُبِّقت بحق المخالف وفق الأنظمة المرورية المعمول بها في المملكة العربية السعودية.','["ضبطت إدارة المرور بمنطقة المدينة المنورة قائد مركبة ارتكب مخالفة عدم الالتزام بحدود المسارات المحددة على الطريق.","وأفادت الجهات المختصة بأن الإجراءات النظامية طُبِّقت بحق المخالف وفق الأنظمة المرورية المعمول بها في المملكة العربية السعودية.","وتواصل إدارة المرور جهودها الرقابية الميدانية لضبط المخالفات وتعزيز السلامة المرورية على الطرق."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/txso2kc','https://sabq.org/article/txso2kc','','https://sabq.org/article/txso2kc','صحيفة سبق','المدينة المنورة','2026-09-06T14:46:00.000Z','2026-09-06T17:46:00.000Z','2026-09-06T20:49:21.427Z','https://media.sabq.org/news/2026/09/111d8ea1-c4b6-4061-b601-5da91fe72545/w1051.webp','/api/media/20bde535-7c23-4230-85e5-634d11c59327','/api/media/20bde535-7c23-4230-85e5-634d11c59327?variant=thumbnail','مرور المدينة المنورة يضبط قائد مركبة خالف حدود المسارات المحددة',1051,705,'valid','published','archived','valid',44,'8b8b86c6609d53768dddd8cdb06835ecde28c19df0166f77619cd97072cd6769','747c0f7bb8e8be790f68c634112d8d92f55fee21a3da4824ea5f31a8343a01a9','محدّث','2026-09-06T20:49:21.427Z','2026-10-07T20:51:58.137Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["المدينة المنورة"]','["المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":3},{"category":"المجتمع","score":3},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:51:58.137Z',200,6,0,'source_article_available','',NULL,NULL,'body:06e95f0e623175db544c7a68e2d5d931935be435a8cc5e68088950ff4b2806c5','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f8e80453-4542-470a-8888-c636c7b1c544','news-f8e80453-4542-470a-8888-c636c7b1c544','المدينة المنورة تستضيف معرض «خطوة مؤسس ورحلة وطن» حتى نوفمبر','المدينه المنوره تستضيف معرض خطوه مؤسس ورحله وطن حتي نوفمبر','يستضيف مركز المدينة للفنون معرض «خطوة مؤسس ورحلة وطن» خلال الفترة الممتدة من 1 سبتمبر حتى 30 نوفمبر، في تجربة فنية نوعية تستعرض فصولاً بصرية من محطات رحلة الملك عبدالعزيز بن عبدالرحمن آل سعود، طيب الله ثراه، وجوانب من تاريخ الوطن وإرثه الحضاري.','["يضم المعرض 21 عملاً فنياً من إبداع 13 فناناً وفنانة سعودية، موزعة على ثلاثة محاور رئيسية: «إرث ممتد»، و«رحلة التوحيد»، و«مظاهر من الحياة الاجتماعية»، ترافقها مخطوطات تُعرض لأول مرة، في سرد بصري قصصي يوثق لحظات توحيد المملكة ويبرز القيم الوطنية والإنسانية التي شكّلت رحلة الوطن.","ويأتي المعرض ضمن الجهود الرامية إلى تنويع التجارب الثقافية في المدينة المنورة، وتعزيز حضور المحتوى التاريخي في التجربة السياحية للزوار، انطلاقاً من أن للمملكة موروثاً تاريخياً عظيماً يستحق إعادة تجسيده بصرياً بما يعبر محلياً وعالمياً.","تبدأ رحلة الزائر من مسار «مظاهر الحياة الاجتماعية»، الذي يتتبع القيم الكريمة واستمرارها عبر تطور المجتمع السعودي؛ من قصة المرأة العربية التي حاولت الملك عبدالعزيز دون أن تعرفه فعرّفتها بصنيعه، إلى لوحة «راعية الإبل»، وتجسيد «سنة الجوع»، وأمره بإحياء «عين زبيدة» لسقاية الحجاج والمعتمرين.","وتنتقل التجربة إلى مسار «رحلة التوحيد»، الذي يجسّد الطريق الشاق الذي خاضه الملك عبدالعزيز ورجاله نحو الرياض، عبر أعمال من بينها «إرث التوحيد» و«فجر حوران» و«واحة يبرين» و«حصون التوحيد»، لتجسّد استرداد قلعة المصمك في 5 شوال 1319هـ، الموافق 15 يناير 1902م.","ويحتفي محور «إرث ممتد» بذاكرة الأرض ودور المرأة من خلال ثنائية «المناخ» و«القادمات» و«مريولات»، إلى جانب أعمال تبرز استقطاب أهل الكفاءة في مسيرة البناء الوطني."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/5x783i3','https://sabq.org/article/5x783i3','','https://sabq.org/article/5x783i3','صحيفة سبق','الرياض','2026-09-06T14:40:00.000Z','2026-09-06T17:40:00.000Z','2026-09-06T20:49:22.500Z','https://media.sabq.org/news/2026/09/9a876858-a8b8-464f-b238-765a31c9911e/w642.webp','/api/media/f8e80453-4542-470a-8888-c636c7b1c544','/api/media/f8e80453-4542-470a-8888-c636c7b1c544?variant=thumbnail','المدينة المنورة تستضيف معرض «خطوة مؤسس ورحلة وطن» حتى نوفمبر',642,452,'valid','published','archived','valid',51,'1a6e34a88a6f4ad1c90797c7cb78315799fac8321e1e7445ec22e4eb1e8090f9','91ac7e4eb7ba11312779faec95f15184bd328ea127da7e78b29c39e0b3330d27','محدّث','2026-09-06T20:49:22.500Z','2026-10-07T20:52:37.279Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","الرياض","المدينة المنورة"]','["الطقس والمناخ","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"التقنية","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"المجتمع","score":1.5}]','Active','2026-10-07T20:52:37.279Z',200,6,0,'source_article_available','',NULL,NULL,'body:6761347def7d9aabababa413cb1980e712cd271a76003a29683143131e98b5a2','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dcb641b1-9545-4cf2-bf5e-e40c5d6f99ae','news-dcb641b1-9545-4cf2-bf5e-e40c5d6f99ae','30 فائزًا.. جائزة الأميرة صيتة تحتفي بتميز العمل الاجتماعي','30 فائزا جائزه الاميره صيته تحتفي بتميز العمل الاجتماعي','كرّمت جائزة الأميرة صيتة بنت عبدالعزيز للتميز في العمل الاجتماعي 30 فائزاً بجوائزها الاجتماعية لعام 2026، خلال حفل أُقيم مساء الأحد بالرياض برعاية وزير الموارد البشرية والتنمية الاجتماعية رئيس مجلس أمناء الجائزة المهندس أحمد الراجحي، وبحضور الأمير سعود بن فهد بن عبدالله عضو مجلس الأمناء نائب رئيس اللجنة التنفيذية، وعدد من أصحاب السمو والمعالي ونخبة من…','["واستُهل الحفل بتلاوة آيات من القرآن الكريم، تلاها عرض مرئي تناول الجوائز الاجتماعية الست، وهي: «المواطنة المسؤولة»، و«أم الجود»، و«تنسيق»، و«تحفيز»، و«صيتاثون»، و«امتنان»، وأبرز دورها في تحفيز الأفراد والمؤسسات المتميزة في العمل الاجتماعي وتعزيز ثقافة العطاء المستدام.","وألقى الأمير سعود بن فهد بن عبدالله كلمةً هنأ فيها الفائزين على ما قدموه من عطاء ومبادرات نوعية، مؤكداً أن الجوائز الاجتماعية «تمثل رسالة وفاء وتقدير لكل من جعل خدمة المجتمع نهجاً ثابتاً في مسيرته»، ودليلاً على عناية المملكة بدعم المبادرات الرائدة التي تعزز جودة الحياة وتكرّس قيم التعاون والتكافل.","وأشار سموه إلى أن هذه الجوائز جاءت ثمرة جهد مؤسسي منظّم يحرص على وضوح الرؤية ودقة العمل وقياس أثر المبادرات لضمان استدامتها، بما يدعم مكانة المملكة في ريادة العمل الاجتماعي.","وفي كلمته، أكد الأمين العام للجائزة الدكتور فهد بن حمد المغلوث أن الجوائز الاجتماعية تحتفي بثقافة وطنية جعلت من العطاء قيمة ومن المبادرة مسؤولية ومن الأثر معياراً للتميز، في وطن جعل الإنسان محور التنمية وأعظم ثرواته.","وأعلن الدكتور المغلوث في ختام كلمته عن فتح باب الترشح للجائزة الكبرى في دورتها الرابعة عشرة لعام 2026 تحت عنوان «تنمية الإنسان وتعزيز التماسك المجتمعي والولاء الوطني»، فضلاً عن فتح باب الترشح لجائزتَي «المواطنة المسؤولة» في دورتها السادسة، و«صيتاثون» في دورتها الرابعة.","وعلى صعيد الفائزين، حصد في جائزة «امتنان» كلٌّ من إحسان صالح طيب في فرع «وقار»، وصالح بن عبدالله السيد في فرع «رِفعة».","وفي جائزة «تحفيز» بدورتها الرابعة، فازت هيئة تطوير منطقة عسير عن مبادرة «أجاويد».","وفي جائزة «تنسيق» بدورتها الخامسة، فازت مدارس علم وبناء الأهلية عن المجال التعليمي، وجمعية الأشخاص الاستثنائيين لخدمة ذوي الإعاقة عن المجال الخيري."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/LxUIs3s','https://sabq.org/article/LxUIs3s','','https://sabq.org/article/LxUIs3s','سعود الدعجاني ','الرياض','2026-09-06T14:46:00.000Z','2026-09-06T17:46:00.000Z','2026-09-06T20:49:23.009Z','https://media.sabq.org/news/2026/09/c7b8da83-4894-457e-ad54-85c665818588/w1600.webp','/api/media/dcb641b1-9545-4cf2-bf5e-e40c5d6f99ae','/api/media/dcb641b1-9545-4cf2-bf5e-e40c5d6f99ae?variant=thumbnail',' 30 فائزًا.. جائزة الأميرة صيتة تحتفي بتميز العمل الاجتماعي',1600,1067,'valid','published','archived','valid',95,'7e1238309179bb1ea8a1eef1540b45c95c544d2e7960dec20fedbfccf170153f','0d167d5b38e88c77338eb7eb401fab05d0d187a29631e29ceabde673f8bc3147','محدّث','2026-09-06T20:49:23.009Z','2026-10-07T20:52:37.315Z','','',0,0,'saudi_region','مهم',74,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة تطوير منطقة عسير عن","مجلس أمناء الجائزة المهندس أحمد","رئيس مجلس أمناء الجائزة المهندس","وزير الموارد البشرية والتنمية الاجتماعية","الصحة العامة","الثقافة والفنون","التعليم والتدريب","عسير"]','["هيئة تطوير منطقة عسير عن","مجلس أمناء الجائزة المهندس أحمد","رئيس مجلس أمناء الجائزة المهندس","وزير الموارد البشرية والتنمية الاجتماعية","الصحة العامة","الثقافة والفنون"]','classified','','[{"category":"المناطق","score":3},{"category":"أخبار السعودية","score":1.5},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:52:37.315Z',200,6,0,'source_article_available','',NULL,NULL,'body:1a2d32c9b611e140b1df022002955490f06b728c582d6354e44b5db865c163d1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('05948eb0-8387-478d-bc52-b10704317937','news-05948eb0-8387-478d-bc52-b10704317937','أكثر من 20 حوثيًا بين قتيل وجريح.. الجيش اليمني يصعّد عملياته في 6 جبهات','اكثر من 20 حوثيا بين قتيل وجريح الجيش اليمني يصعد عملياته في 6 جبهات','وأوضح المصدر أن القوات المسلحة تمكّنت مساءً من كسر محاولة تسلل لمليشيا الحوثي في جبهة الضباب، وأوقعت أكثر من 20 عنصراً بين قتيل وجريح، إلى جانب خسائر مادية كبيرة.','["نفّذت القوات المسلحة اليمنية عمليات عسكرية واسعة النطاق في عدد من الجبهات، أسفرت عن استعادة مواقع وتثبيتها، وإفشال محاولات تسلل، واستهداف تجمعات مليشيا الحوثي الإرهابية، وتكبيدها خسائر فادحة في الأرواح والعتاد.","وأفاد مصدر عسكري للمركز الإعلامي للقوات المسلحة بأن العمليات شملت هجوماً واسعاً من ثلاثة محاور في جبهة البرح صباحاً، فضلاً عن استعادة مواقع في منطقة الكدحة غربي تعز، وتثبيت مواقع جديدة جنوب الحديدة.","وبالتزامن مع المعارك الميدانية، نفّذ الطيران الحربي للقوات المسلحة غارات جوية استهدفت مواقع المليشيا في البرح وجنوب الحديدة والأطراف الغربية لمأرب، كما طالت الغارات مواقع وتجمعات في اللبنات والعلم ومركز محافظة الجوف، وألحقت بالمليشيا خسائر فادحة في الأرواح والعتاد."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/wfafc2j','https://sabq.org/article/wfafc2j','','https://sabq.org/article/wfafc2j','صحيفة سبق','الجوف','2026-09-06T14:50:00.000Z','2026-09-06T17:51:00.000Z','2026-09-06T20:56:28.246Z','https://media.sabq.org/news/2026/09/85b8f159-584b-4005-9d0c-37b67166e0d4/w731.webp','/api/media/05948eb0-8387-478d-bc52-b10704317937','/api/media/05948eb0-8387-478d-bc52-b10704317937?variant=thumbnail','أكثر من 20 حوثيًا بين قتيل وجريح.. الجيش اليمني يصعّد عملياته في 6 جبهات',731,419,'valid','published','archived','valid',57,'20d793666bd834d6ebb8fd1812ac85fa899ce8f202d753a7eff7fdf30bb86693','7a92bef9310ecc25209b73760d27c8e188eb37b3198198fc57206b161928eb28','محدّث','2026-09-06T20:56:28.246Z','2026-10-07T20:57:12.533Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["السفر والسياحة","الجوف","اليمن"]','["السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Temporarily Unreachable','2026-10-07T20:57:12.533Z',NULL,9,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('52679922-3df1-4ea0-83f6-46dbb96b4f65','news-52679922-3df1-4ea0-83f6-46dbb96b4f65','جامعة الطائف تحول الدراسة غدًا إلى عن بُعد بسبب حالة الطقس','جامعه الطائف تحول الدراسه غدا الي عن بعد بسبب حاله الطقس','قررت جامعة الطائف تحويل الدراسة الحضورية إلى التعليم عن بُعد، غدًا الاثنين 7 سبتمبر 2026، ابتداءً من الساعة 12 ظهرًا، وذلك بناءً على ما ورد من المركز الوطني للأرصاد وحرصًا على سلامة الطلاب والطالبات ومنسوبي الجامعة.','["وأوضحت الجامعة أن القرار يشمل المقر الرئيس ب الحوية وجميع مقراتها في مدينة الطائف، على أن تُستكمل الدراسة عبر منصة «البلاك بورد».","كما تقرر استمرار دوام الموظفين عن بُعد بعد الساعة 12 ظهرًا، وفق الأنظمة واللوائح المعمول بها.","في المقابل، يستمر دوام الموظفين والدراسة الحضورية بشكل طبيعي في فروع الجامعة بمحافظات تربة و الخرمة و رنية ."]','البيئة والمناخ','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/pilce23ch','https://ajel.sa/local/pilce23ch','https://ajel.sa/local/pilce23ch','https://ajel.sa/local/pilce23ch','فريق التحرير','','2026-09-06T15:07:00.000Z','Wed, 07 Oct 2026 21:00:06 GMT','2026-09-06T21:11:29.033Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%AC%D8%A7%D9%85%D8%B9%D8%A9-%D8%A7%D9%84%D8%B7%D8%A7%D8%A6%D9%81-hyIEGSiZ.png','/api/media/52679922-3df1-4ea0-83f6-46dbb96b4f65','/api/media/52679922-3df1-4ea0-83f6-46dbb96b4f65?variant=thumbnail','جامعة الطائف تحول الدراسة غدًا إلى عن بُعد بسبب حالة الطقس',1200,675,'valid','published','archived','valid',99,'a2404f28cada11a4cc7284e95682f628e53d949453acb494e68c413f767cd51c','6ac768ade68fd853c573b3d465656de4a9b0293e451c24a5bda725e2e023fbce','محدّث','2026-09-06T21:11:29.033Z','2026-10-07T21:00:07.633Z','','',0,0,'international','عادي',48,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة الطائف تحول الدراسة غد","الطقس والمناخ","التعليم والتدريب"]','["جامعة الطائف تحول الدراسة غد","الطقس والمناخ","التعليم والتدريب"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T21:00:07.633Z',200,6,0,'source_content_changed','',NULL,NULL,'body:bef4fbd3a7978b5ced26db50f64a545c4c7df81ff4ab23efa8cff30087974d8d','Wed, 07 Oct 2026 21:00:06 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8c55aaf5-0fbe-436e-b744-aad14779fb2a','news-8c55aaf5-0fbe-436e-b744-aad14779fb2a','إيران تُعلن منطقة بحرية محظورة خارج "هرمز" وتختبر صاروخاً ضد مدمرة أمريكية','ايران تعلن منطقه بحريه محظوره خارج هرمز وتختبر صاروخا ضد مدمره امريكيه','التصعيد العسكري كشف رضائي أن إيران اختبرت قبل 48 ساعة، وللمرة الأولى، صاروخاً إيرانياً مضاداً للمدمرات فوق سفينة حربية أمريكية، فيما نفت الولايات المتحدة الأحد استهداف إيران لسفينة عسكرية أمريكية غير مأهولة في مضيق هرمز.','["أعلن أمين المجلس الأعلى للأمن القومي الإيراني محسن رضائي أن طهران تعتزم إعلان منطقة بحرية «محظورة» خارج مضيق هرمز خلال الأيام المقبلة، تمتد من خط الحصار البحري الأمريكي إلى مناطق في الخليج، محذراً من أن «أي سفينة تدخل المنطقة الجديدة ستُضاف إلى قائمة العقوبات».","وأشار رضائي خلال مقابلة تلفزيونية الأحد، إلى أن مضيق هرمز «مغلق بالكامل»، نافياً تصريحات الرئيس الأمريكي دونالد ترامب بشأن بقاء المضيق مفتوحاً، واصفاً إياها بأنها «كذبة كبيرة»، ومؤكداً أن «القوات الإيرانية ترصد السفن الأمريكية التي تحاول العبور بشكل غير قانوني وتستهدفها».","وأوضح رضائي أن أكثر من 100 سفينة كانت تعبر مضيق هرمز قبل إغلاقه، تنقل أكثر من 100 مليون طن من البضائع، بينما لا يعبره حالياً سوى ما بين 7 و8 سفن كحد أقصى تنقل السلع الأساسية إلى إيران.","وأشار المسؤول الأمني الإيراني إلى أن بلاده «لم تتخذ قراراً بإغراق السفن الأمريكية التي تحاول العبور»، موضحاً أن «هذه السفن تحمل النفط وأن غرقها قد يتسبب في أضرار بيئية في المنطقة».","الوضع الاقتصادي الداخلي نفى رضائي احتمال حدوث مجاعة في إيران جراء الحصار الاقتصادي، مؤكداً أن «الحكومة الإيرانية كانت تستعد لهذا الوضع منذ فترة طويلة وتمتلك مخزونات كافية من المواد الغذائية والسلع الأساسية»، مشيراً إلى أن طهران «تبيع النفط وتعود أمواله إليها» رغم العقوبات والحصار الأمريكي.","مسار المفاوضات دعا رضائي واشنطن إلى «كسب ثقة إيران من أجل مواصلة المسار التفاوضي»، موضحاً أن «المشكلة الكبرى» التي واجهتها طهران بشأن مذكرة التفاهم كانت مرتبطة بالثقة في ضمانات الوسطاء، مؤكداً أن إيران تواصل جهودها الدبلوماسية مع تمسكها بالحصول على ضمانات.","الحصار الأمريكي في المقابل، أعلنت «سنتكوم» مواصلة فرض الحصار البحري على إيران، مشيرةً إلى أنه حتى السادس من سبتمبر غيّرت القوات الأمريكية مسار 92 سفينة تجارية، وعطّلت 3 سفن، وفتّشت سفينتين «بهدف ضمان الامتثال الكامل للحصار».","وتأتي هذه التطورات في أعقاب استئناف الولايات المتحدة وإيران الهجمات الأسبوع الماضي، بعد نحو شهر من الهدوء النسبي، وسط عودة التوتر إلى مضيق هرمز والمناطق الإيرانية المطلة عليه."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/tpmzmqu','https://sabq.org/article/tpmzmqu','','https://sabq.org/article/tpmzmqu','صحيفة سبق','','2026-09-06T15:00:00.000Z','2026-09-06T18:00:00.000Z','2026-09-06T21:11:38.375Z','https://media.sabq.org/news/2026/09/ca93f9e3-659b-4435-a6d0-02fdf71d8ba7/w801.webp','/api/media/8c55aaf5-0fbe-436e-b744-aad14779fb2a','/api/media/8c55aaf5-0fbe-436e-b744-aad14779fb2a?variant=thumbnail','إيران تُعلن منطقة بحرية محظورة خارج "هرمز" وتختبر صاروخاً ضد مدمرة أمريكية',801,451,'valid','published','archived','valid',43,'7fd2c43fc035eda64a970c1a50342b5c0b49bb54fb4ee15da167f301289be5a9','5c6518a7abd266c309000557a6d25ca62f20f1c058710e0d3821c6fc159c1efa','محدّث','2026-09-06T21:11:38.375Z','2026-10-07T21:00:06.127Z','','',0,0,'gulf_arab','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الاقتصاد والأسواق","السياسة والعلاقات الدولية","إيران","الولايات المتحدة"]','["الطاقة والنفط","الاقتصاد والأسواق","السياسة والعلاقات الدولية","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T21:00:06.127Z',200,6,0,'source_article_available','',NULL,NULL,'body:6b71e9065375074d835b3f59d58f07d411c43e3db2ed434f3fd7aee3ccb9d205','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('71041f8a-92e5-458e-8cb8-f910be461193','news-71041f8a-92e5-458e-8cb8-f910be461193','بيئي / هيئة تطوير محمية الملك عبدالعزيز الملكية والأمن البيئي يكثفان الرقابة على مخالفات الصيد','بيئي هيئه تطوير محميه الملك عبدالعزيز الملكيه والامن البيئي يكثفان الرقابه علي مخالفات الصيد','ويُمنع داخل نطاق محمية الملك عبدالعزيز الملكية صيد جميع أنواع الحيوانات الفطرية البرية، بما فيها الطيور؛ لما يمثله الصيد من تأثير مباشر في أعداد الكائنات الفطرية واستقرار تجمعاتها، خصوصًا الأنواع المهددة بالانقراض، وما قد يترتب عليه من إخلال بالتوازن الطبيعي للأنظمة البيئية.','["الرياض 24 ربيع الأول 1448 هـ الموافق 06 سبتمبر 2026 م واس كثّفت هيئة تطوير محمية الملك عبدالعزيز الملكية، بالتعاون مع القوات الخاصة للأمن البيئي، جهود الرصد والرقابة الميدانية داخل نطاق المحمية، ضمن حملة رقابية مشتركة للحد من مخالفات الصيد، وتعزيز حماية الحياة الفطرية وموائلها الطبيعية.","وتشمل الحملة تكثيف الجولات الميدانية في مختلف المواقع داخل نطاق المحمية، ورصد الممارسات المخالفة واتخاذ الإجراءات النظامية حيالها، في إطار التكامل بين هيئة تطوير محمية الملك عبدالعزيز الملكية والقوات الخاصة للأمن البيئي؛ للمحافظة على الموارد الطبيعية وتعزيز الامتثال للأنظمة والتعليمات البيئية.","ويأتي تكثيف أعمال الرقابة بالتزامن مع موسم هجرة العديد من أنواع الطيور، الذي تشهد خلاله بيئات المحمية عبور واستقرار أعداد من الطيور المهاجرة، مما يعزز أهمية المحافظة على سلامتها والحد من الممارسات التي قد تهددها أو تؤثر في مسارات هجرتها وموائلها الطبيعية.","وتؤدي الكائنات الفطرية، بما فيها الطيور والأنواع المهددة بالانقراض، أدوارًا مهمة في بيئاتها الطبيعية، وتسهم في استقرار السلاسل الغذائية والمحافظة على التوازن البيئي واستدامة التنوع الأحيائي، ما يجعل حمايتها والمحافظة على موائلها من الركائز الأساسية لسلامة النظم البيئية واستمرارها.","وتواصل هيئة تطوير محمية الملك عبدالعزيز الملكية جهودها في حماية الحياة الفطرية والمحافظة على الموائل الطبيعية، من خلال أعمال الرصد والحماية الميدانية، ورفع مستوى الرقابة، وتعزيز التعاون مع الجهات ذات العلاقة؛ للحد من الممارسات المخالفة ودعم استدامة الموارد الطبيعية والتنوع الأحيائي داخل المحمية.","وتأتي الحملة المشتركة امتدادًا للجهود الرامية إلى تعزيز حماية البيئة، وترسيخ الالتزام بالأنظمة والتعليمات البيئية، والإسهام في توفير بيئة آمنة للكائنات الفطرية والمحافظة على الموائل الطبيعية وصونها للأجيال القادمة. // انتهى // 15:51 ت مـ 0096"]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2669909?type=news&uuid=N2669909','https://spa.gov.sa/ar/N2669909?type=news&uuid=N2669909','N2669909','N2669909','','الرياض','2026-09-06T09:51:00.000Z',NULL,'2026-09-06T21:11:50.231Z','https://portalcdn.spa.gov.sa/backend/original/202609/F10737705.jpg','/api/media/71041f8a-92e5-458e-8cb8-f910be461193','/api/media/71041f8a-92e5-458e-8cb8-f910be461193?variant=thumbnail','بيئي / هيئة تطوير محمية الملك عبدالعزيز الملكية والأمن البيئي يكثفان الرقابة على مخالفات الصيد',1600,903,'valid','published','archived','valid',57,'a894f350e0cc51f3ad578f60949105783f1d21b4c5bfa8f1a4e2c0331c6d53cc','80d7dc19577564138e2f66913155fc9ceeede6994ec46338e42ceb18fc01d2d5',NULL,'2026-09-06T21:11:50.231Z','2026-10-07T21:00:11.861Z','','',0,0,'saudi_region','مهم',77,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة تطوير محمية الملك عبدالعزيز","التعليم والتدريب","الرياض"]','["هيئة تطوير محمية الملك عبدالعزيز","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T21:00:11.861Z',200,6,0,'source_article_available','',NULL,NULL,'body:852483230c753aeb50de551744f82ad4114a9c0016111174e03ba7fc9c70b213','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('96eea873-4cef-47f1-b210-55ef52fb1c9d','news-96eea873-4cef-47f1-b210-55ef52fb1c9d','برعاية أمير الشرقية.. انطلاق بطولة منتخبات مدن ومحافظات المنطقة بجوائز 150 ألف ريال','برعايه امير الشرقيه انطلاق بطوله منتخبات مدن ومحافظات المنطقه بجوائز 150 الف ريال','ورصدت اللجنة المنظمة 150 ألف ريال إجمالاً لجوائز البطولة، إذ تبلغ جائزة المركز الأول 50 ألف ريال، فيما تُخصَّص 40 ألف ريال لجوائز أبطال المرحلة التمهيدية.','["تُقام تحت رعاية صاحب السمو الملكي الأمير سعود بن نايف بن عبدالعزيز أمير المنطقة الشرقية، بطولة منتخبات مدن ومحافظات المنطقة الشرقية لكرة القدم، بمشاركة عدد من منتخبات مدن ومحافظات المنطقة، وجوائز مالية يبلغ إجماليها 150 ألف ريال.","وتشهد البطولة مشاركة منتخبات «الدمام، والخبر، والظهران، والقطيف، ورأس تنورة، والجبيل، والخفجي، وبقيق»، في منافسات تهدف إلى تعزيز الحراك الرياضي، وإتاحة الفرصة أمام المواهب، وترسيخ قيم التنافس والتعاون بين المشاركين.","وتأتي البطولة تحت شعار يعزز قيم «الاحترام والانضباط والتميز»، إلى جانب تشجيع المشاركة المجتمعية وروح المنافسة الرياضية، والعمل على تطوير اللعبة وإبراز المواهب في مدن ومحافظات المنطقة الشرقية.","وحددت اللجنة المنظمة تاريخ 15 سبتمبر 2026 آخر موعد لتسجيل الفرق المشاركة في البطولة.","وتُقام البطولة بمشاركة عدد من الجهات الداعمة، من بينها «وزارة الرياضة، وأمانة المنطقة الشرقية، والاتحاد السعودي لكرة القدم»، في إطار دعم الأنشطة الرياضية وتعزيز حضور كرة القدم على مستوى مدن ومحافظات المنطقة."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/33ts8er','https://sabq.org/article/33ts8er','','https://sabq.org/article/33ts8er','صحيفة سبق','الرياض','2026-09-06T14:56:00.000Z','2026-09-06T17:56:00.000Z','2026-09-06T21:12:19.539Z','','','','برعاية أمير الشرقية.. انطلاق بطولة منتخبات مدن ومحافظات المنطقة بجوائز 150 ألف ريال',NULL,NULL,'all_candidates_failed (og:fetch failed | structured:fetch failed | structured:fetch failed | structured:fetch failed)','published','archived','valid',92,'d127d7dcd572deb628bb629e1bdce1ce23486b7a150950c7a50edb702046575b','a3c4b60f932cd612a55247b807602027323bae4d704f4018353bdf6423f82e13','محدّث','2026-09-06T21:12:19.539Z','2026-10-07T21:00:06.104Z','','',0,0,'saudi_region','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الرياضة وأمانة المنطقة الشرقية","الرياضة السعودية","الرياض","الدمام"]','["وزارة الرياضة وأمانة المنطقة الشرقية","الرياضة السعودية"]','classified','','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"التقنية","score":0}]','Active','2026-10-07T21:00:06.104Z',200,6,0,'source_article_available','',NULL,NULL,'body:34056a5bc363b956d758d5080cb17c55476d299caafeeebf7586b73cd6fa2ff1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('052fc209-ef15-461c-9f58-0a1d5b53fe35','news-052fc209-ef15-461c-9f58-0a1d5b53fe35','وزير الخارجية يبحث مع نظيره البحريني تطورات الأوضاع في المنطقة','وزير الخارجيه يبحث مع نظيره البحريني تطورات الاوضاع في المنطقه','تلقى الأمير فيصل بن فرحان بن عبد الله وزير الخارجية، اتصالًا هاتفيًا من وزير خارجية مملكة البحرين الشقيقة الدكتور عبداللطيف بن راشد الزياني . وجرى خلال الاتصال، بحث تطورات الأوضاع في المنطقة، والجهود المبذولة للحفاظ على الأمن والاستقرار فيها.','["تلقى الأمير فيصل بن فرحان بن عبد الله وزير الخارجية، اتصالًا هاتفيًا من وزير خارجية مملكة البحرين الشقيقة الدكتور عبداللطيف بن راشد الزياني .","وجرى خلال الاتصال، بحث تطورات الأوضاع في المنطقة، والجهود المبذولة للحفاظ على الأمن والاستقرار فيها."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/mli5jeu7j','https://ajel.sa/local/mli5jeu7j','https://ajel.sa/local/mli5jeu7j','https://ajel.sa/local/mli5jeu7j','فريق التحرير','','2026-09-06T15:01:00.000Z','Wed, 07 Oct 2026 21:00:07 GMT','2026-09-06T21:12:52.423Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D9%88%D8%B2%D9%8A%D8%B1-%D8%A7%D9%84%D8%AE%D8%A7%D8%B1%D8%AC%D9%8A%D8%A9-mBb1HWkz.webp','/api/media/052fc209-ef15-461c-9f58-0a1d5b53fe35','/api/media/052fc209-ef15-461c-9f58-0a1d5b53fe35?variant=thumbnail','وزير الخارجية يبحث مع نظيره البحريني تطورات الأوضاع في المنطقة',1200,675,'valid','published','archived','valid',41,'ea2b274c2f9f82590991662d487d3781520e01e6a7bdc6324b4aee557492a289','2d20b10de29022406db4d9135b2d475369309a51ece118a23385c3303bb4483a','محدّث','2026-09-06T21:12:52.423Z','2026-10-07T21:00:08.823Z','','',0,0,'gulf_arab','عادي',45,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الخارجية يبحث مع نظيره"]','["وزير الخارجية يبحث مع نظيره"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:00:08.823Z',200,6,0,'source_content_changed','',NULL,NULL,'body:60f1ded7c53841aed786b9310f7c3c33781916ccd8d49bec2adca7700cb4873d','Wed, 07 Oct 2026 21:00:07 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('50bbba2f-62d4-4da2-a74f-261c5a894209','news-50bbba2f-62d4-4da2-a74f-261c5a894209','النصر يجدد عقد عبدالرحمن غريب حتى 2028','النصر يجدد عقد عبدالرحمن غريب حتي 2028','أعلنت إدارة نادي النصر تجديد عقد لاعبه الجناح الهجومي عبدالرحمن غريب لمدة موسمين إضافيين، ليستمر في الدفاع عن ألوان بطل الدوري حتى صيف 2028. وكتب النادي عبر حسابه الرسمي على منصة «إكس»: «أنهت إدارة شركة نادي النصر إجراءات تجديد عقد نجم النصر الكابتن عبدالرحمن غريب، وذلك بعقدٍ يمتد حتى عام 2028..','["أعلنت إدارة نادي النصر تجديد عقد لاعبه الجناح الهجومي عبدالرحمن غريب لمدة موسمين إضافيين، ليستمر في الدفاع عن ألوان بطل الدوري حتى صيف 2028.","وكتب النادي عبر حسابه الرسمي على منصة «إكس»: «أنهت إدارة شركة نادي النصر إجراءات تجديد عقد نجم النصر الكابتن عبدالرحمن غريب، وذلك بعقدٍ يمتد حتى عام 2028..","أمنياتنا له بالتوفيق مع ناديه العالمي».","ويأتي قرار التجديد تأكيداً لرغبة الإدارة في الحفاظ على ركائز الفريق الأساسية، لا سيما بعد المستويات المميزة التي قدّمها غريب خلال الموسم الماضي ومساهمته الفاعلة في الخط الأمامي.","وشارك اللاعب البالغ من العمر 29 عاماً في 32 مباراة بمختلف المسابقات خلال الموسم الماضي، لعب خلالها 1091 دقيقة، وسجّل ستة أهداف إلى جانب ست تمريرات حاسمة، وفق إحصاءات موقع «ترانسفير ماركت» العالمي.","وكان النصر قد تعاقد مع غريب في صيف 2022 لمدة أربعة مواسم، قادماً من صفوف نادي الأهلي."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/k2g0sbx','https://sabq.org/article/k2g0sbx','','https://sabq.org/article/k2g0sbx','صحيفة سبق','','2026-09-06T15:18:00.000Z','2026-09-06T18:18:00.000Z','2026-09-06T21:23:22.969Z','https://media.sabq.org/news/2026/09/f0b0f6cf-2535-4b70-a2cc-87045cd4a490/w680.webp','/api/media/50bbba2f-62d4-4da2-a74f-261c5a894209','/api/media/50bbba2f-62d4-4da2-a74f-261c5a894209?variant=thumbnail','النصر يجدد عقد عبدالرحمن غريب حتى 2028',680,522,'valid','published','archived','valid',91,'6984f867b2e21ded3fa483f5164b86d7e28fab8244df1cca0c467e4d573868e2','b4539a34fab0cab69c86afd9b245fb7bd2d05a844b88db71e4690969e6031f05','محدّث','2026-09-06T21:23:22.969Z','2026-10-07T21:00:56.957Z','','',0,0,'international','عادي',49,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة نادي النصر إجراءات تجديد","الرياضة السعودية"]','["شركة نادي النصر إجراءات تجديد","الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"التقنية","score":0},{"category":"المناطق","score":-5}]','Active','2026-10-07T21:00:56.957Z',200,6,0,'source_article_available','',NULL,NULL,'body:035df91674db24689627fe665cac1e174902bf7ecff41534fe87399913add1e4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cdfc7f85-7538-449a-95cb-bc41467311fe','news-cdfc7f85-7538-449a-95cb-bc41467311fe','"الصحة" تستعد للملتقى العالمي التاسع بعد اتفاقيات بـ133 مليار ريال','الصحه تستعد للملتقي العالمي التاسع بعد اتفاقيات بـ133 مليار ريال','تستعد وزارة الصحة لاستضافة النسخة التاسعة من ملتقى الصحة العالمي في مركز الرياض للمعارض والمؤتمرات «ملهم»، خلال الفترة من 26 إلى 29 أكتوبر 2026، في ظل نمو متسارع يشهده القطاع الصحي وتنامٍ ملحوظ في جاذبيته الاستثمارية.','["وجاءت النسخة الثامنة من الملتقى، التي أُقيمت تحت رعاية وزارة الصحة على مدى أربعة أيام بشعار «استثمر في الصحة»، بنتائج لافتة؛ إذ تجاوزت قيمة الاتفاقيات المبرمة 133 مليار ريال، فيما سجّلت الاتفاقيات بين جهات القطاع الخاص نمواً بلغ 6 أضعاف مقارنةً بالنسخ السابقة.","وشارك في الملتقى 2200 علامة تجارية، واستضاف 600 متحدث من أبرز القيادات الصحية حول العالم، فيما تجاوز عدد الزوار 130 ألف زائر، مع ارتفاع نسبة الحضور الدولي بمعدل 54% عن النسخ الماضية، مما يعكس اتساع الاهتمام العالمي بالفرص الاستثمارية والبحثية في القطاع الصحي السعودي.","وتستهدف النسخة التاسعة استقطاب نخبة من المستثمرين والمبتكرين والباحثين وصنّاع القرار والقيادات الصحية من مختلف دول العالم، لتكون منصة عالمية لاستكشاف الفرص الاستثمارية الواعدة، وعقد الشراكات النوعية، وتبادل الخبرات، والاطلاع على أحدث الابتكارات والتقنيات والحلول الصحية، ضمن برنامج حافل بالجلسات والفعاليات المتخصصة.","وتأتي هذه الفعالية في إطار جهود المملكة لاستقطاب الاستثمارات والشراكات النوعية، ودعم تطوير القطاع الصحي ورفع جودة خدماته، بما يواكب مستهدفات برنامج تحول القطاع الصحي المنبثق عن رؤية السعودية 2030.","ودعت وزارة الصحة المهتمين بالقطاع الصحي إلى حجز مقاعدهم والتسجيل في النسخة التاسعة من الملتقى عبر الموقع الرسمي للفعالية."]','الصحة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/gwpnr46','https://sabq.org/article/gwpnr46','','https://sabq.org/article/gwpnr46','صحيفة سبق','الرياض','2026-09-06T15:10:00.000Z','2026-09-06T18:11:00.000Z','2026-09-06T21:23:23.261Z','https://media.sabq.org/news/2026/09/ad78b899-551b-47fc-a503-a45de071f504/w828.webp','/api/media/cdfc7f85-7538-449a-95cb-bc41467311fe','/api/media/cdfc7f85-7538-449a-95cb-bc41467311fe?variant=thumbnail','"الصحة" تستعد للملتقى العالمي التاسع بعد اتفاقيات بـ133 مليار ريال',828,552,'valid','published','archived','valid',46,'6bd02ef648e2a1f6d805261d13f0fa93dbd88e0df13e2a274771d3b3dcdb9d82','eca019c5a6844ca07b4dc17a07a63f2824d2a4b26c1a2ab2f8f51941375c6f9c','محدّث','2026-09-06T21:23:23.261Z','2026-10-07T21:00:56.971Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الصحة لاستضافة النسخة التاسعة","الصحة العامة","الاقتصاد والأسواق","الرياض"]','["وزارة الصحة لاستضافة النسخة التاسعة","الصحة العامة","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T21:00:56.971Z',200,6,0,'source_article_available','',NULL,NULL,'body:d43c44d34b4e8ac9a744c433f92cd3fd652d75ddeb8f09e20510eab0e921b8d3','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2644db34-1158-434b-8cfa-4866df475e5b','news-2644db34-1158-434b-8cfa-4866df475e5b','جامعة الطائف تحوّل الدراسة إلى عن بُعد اليوم ابتداءً من الساعة 12 ظهراً','جامعه الطائف تحول الدراسه الي عن بعد اليوم ابتداء من الساعه 12 ظهرا','أقرّت جامعة الطائف تحويل الدراسة الحضورية إلى التعليم عن بُعد عبر منصة «البلاك بورد»، اعتباراً من الساعة 12:00 ظهر اليوم الاثنين 25 ربيع الأول 1448هـ، الموافق 7 سبتمبر 2026م، وذلك في المقر الرئيس بالحوية وجميع مقرات الجامعة بمدينة الطائف. وأشارت الجامعة إلى أن دوام الموظفين سيستمر عن بُعد بعد الساعة 12:00 ظهراً، وفق الأنظمة واللوائح المعمول بها.','["وأوضحت الجامعة أن هذا القرار جاء بناءً على ما ورد من المركز الوطني للأرصاد، وحرصاً على سلامة الطلاب والطالبات وأعضاء الهيئتين الأكاديمية والإدارية.","وأشارت الجامعة إلى أن دوام الموظفين سيستمر عن بُعد بعد الساعة 12:00 ظهراً، وفق الأنظمة واللوائح المعمول بها.","في المقابل، أكدت الجامعة استمرار الدراسة حضورياً والدوام الوظيفي في فروعها بمحافظات تربة والخرمة ورنية، دون أي تغيير."]','التعليم','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/rrPDJ8k','https://sabq.org/article/rrPDJ8k','','https://sabq.org/article/rrPDJ8k','فهد العتيبي','','2026-09-06T15:26:00.000Z','2026-09-06T18:26:00.000Z','2026-09-06T21:32:20.065Z','','','','جامعة الطائف تحوّل الدراسة إلى عن بُعد اليوم ابتداءً من الساعة 12 ظهراً',NULL,NULL,'all_candidates_failed (og:fetch failed | structured:fetch failed | structured:fetch failed | structured:fetch failed)','published','archived','valid',43,'f017713f0a89224f70812315076b466a240400a6baf5b430b56d7f665e9eb52f','d8e5442e7a6cb2b20cbc148fc58c9ec7d538a7f2ce0382a82aff258e0c0e5e09','محدّث','2026-09-06T21:32:20.065Z','2026-10-07T21:18:06.545Z','','',0,0,'international','عادي',52,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة الطائف تحو ل الدراسة","التعليم والتدريب"]','["جامعة الطائف تحو ل الدراسة","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T21:18:06.545Z',200,7,0,'source_article_available','',NULL,NULL,'body:19c290abdc3857fefd2cc0810e20bf51f95aaaf063d7881507d698771d68da29','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('500b7711-f348-427f-8f1f-8301938fc307','news-500b7711-f348-427f-8f1f-8301938fc307','"كيم" يعلن تسليح بحرية كوريا الشمالية نوويًا وخطة لتعزيزها خلال 8 أشهر','كيم يعلن تسليح بحريه كوريا الشماليه نوويا وخطه لتعزيزها خلال 8 اشهر','أعلن زعيم كوريا الشمالية كيم جونغ أون أن تسليح القوات البحرية لبلاده بالأسلحة النووية سيضع أنظمة القتال النووي موضع الاستخدام العملي، في أحدث تصريحات لبيونغ يانغ بشأن تطوير قدراتها العسكرية البحرية.','["وبحسب وكالة الأنباء المركزية الكورية الشمالية، قال كيم إن البحرية ستكون قادرة على ردع ما وصفه بـ«أسطول العدو الغازي»، مؤكداً أن سفينة حربية جديدة يمكنها تنفيذ «ضربات انتقامية ساحقة» ضد الخصوم في أي وقت.","وأضاف أن السفينة الجديدة تمثل دليلاً على حجم التغيير الذي حققته كوريا الشمالية في غضون عامين أو ثلاثة أعوام فقط.","خطة بحرية خلال 8 أشهر وكشف كيم أن بلاده تنفذ حالياً ما وصفه بـ«خطة مهمة» لتعزيز قواتها البحرية، مشيراً إلى أن نتائجها ستظهر خلال ثمانية أشهر، دون أن تُقدّم الوكالة الرسمية تفاصيل إضافية عن طبيعة الخطة أو القدرات التي ستشملها.","وأشار زعيم كوريا الشمالية إلى أن بلاده تواجه «تهديدات مستمرة» في البحر الواقع شرق شبه الجزيرة الكورية والمياه القريبة منها، قائلاً إن «الظلال الخطرة يجب محوها»، في إشارة إلى ما تعتبره بيونغ يانغ تهديدات عسكرية في محيطها البحري.","وتأتي هذه التصريحات في إطار مساعي كوريا الشمالية المتصاعدة لتعزيز قدراتها البحرية، مع تركيز متزايد على إدخال أنظمة ذات قدرة نووية إلى منظومتها العسكرية البحرية.","ولم تتضمن التصريحات التي نقلتها وكالة الأنباء المركزية تفاصيل فنية بشأن أنظمة القتال النووي التي تحدث عنها كيم أو موعد دخولها الخدمة الفعلية، باستثناء إشارته إلى خطة تعزيز القوات البحرية خلال الأشهر الثمانية المقبلة."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/nn6kcdo','https://sabq.org/article/nn6kcdo','','https://sabq.org/article/nn6kcdo','صحيفة سبق','','2026-09-06T15:41:00.000Z','2026-09-06T18:41:00.000Z','2026-09-06T21:50:21.872Z','https://media.sabq.org/news/2026/09/32ecbbd3-2426-459a-a55a-c2e2de09f1c6/w555.webp','/api/media/500b7711-f348-427f-8f1f-8301938fc307','/api/media/500b7711-f348-427f-8f1f-8301938fc307?variant=thumbnail','"كيم" يعلن تسليح بحرية كوريا الشمالية نوويًا وخطة لتعزيزها خلال 8 أشهر',555,312,'valid','published','archived','valid',35,'abededa85fb67a9e6ce2900ff09b7d51b47980be279ebf564795711029112513','03f20bc6299b68e1b0372d323735b5527e3990d191119c5747176962c3994a5b','محدّث','2026-09-06T21:50:21.872Z','2026-10-07T20:25:22.793Z','','',0,0,'international','عادي',56,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط"]','["الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:07:49.251Z',200,5,0,'source_article_available','',NULL,NULL,'body:2f630eb35f082cec2ec3d90d4baf1396cf46a3093cfe18f7b275f41cc5a5a042','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('37f1d06d-c924-4d5d-8005-1c55f88c85fb','news-37f1d06d-c924-4d5d-8005-1c55f88c85fb','صحة جازان تُبرم 7 اتفاقيات شراكة مجتمعية لدعم الخدمات الصحية والرعاية التكاملية','صحه جازان تبرم 7 اتفاقيات شراكه مجتمعيه لدعم الخدمات الصحيه والرعايه التكامليه','في خطوة تهدف إلى تعزيز التكامل بين القطاع الحكومي والقطاع غير الربحي، وقع مدير عام فرع وزارة الصحة ب منطقة جازان ، الدكتور عواجي بن قاسم النعمي، سبع اتفاقيات شراكة مجتمعية مع عدد من الجمعيات الأهلية والتخصصية بالمنطقة.','["وتأتي هذه الخطوة في إطار رفع كفاءة الخدمات الصحية والاجتماعية المقدمة للمستفيدين، وتفعيل برامج المسؤولية المجتمعية بما يتماشى مع أهداف رؤية السعودية 2030 لتمكين القطاع الثالث.","وشملت الاتفاقيات الموقعة التعاون مع الجمعيات جمعية مأمن لرعاية السجناء وأسرهم لتقديم الدعم الصحي والنفسي للسجناء وعوائلهم و جمعية نماء للخدمات الاجتماعية لتطوير المبادرات الاجتماعية الموجهة للفئات الأكثر حاجة و جمعية مرفأ للخدمات الأسرية، لتعزيز الاستقرار الأسري والمساندة النفسية و","جمعية الرؤية المستقبلية للتوجيه والإرشاد، لتقديم برامج التوجيه والإرشاد النفسي والاجتماعي و","جمعية نبتون للتأهيل الطبي، لتوفير وتطوير خدمات التأهيل الطبي للقطع المستهدفة وجمعية التغذية العلاجية ، لنشر الثقافة الغذائية وتوفير الاستشارات التغذوية المتخصصة و جمعية رتق الرياضية! لدعم الأنشطة الرياضية والصحية التي تعزز نمط الحياة الصحيوالمحافظة على الصحة العامة.","وأكد الدكتور عواجي النعمي خلال مراسم التوقيع أن هذه الشراكات تمثل امتداداً لجهود صحة جازان في توسيع نطاق خدماتها بالتعاون مع المؤسسات المجتمعية، مشيراً إلى أن التكامل مع القطاع غير الربحي يسهم بشكل مباشر في تحسين جودة الحياة ويعزز التكامل بين القطاعات ويلبي احتياجات المجمتع."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/cdzpttl8d','https://ajel.sa/local/cdzpttl8d','https://ajel.sa/local/cdzpttl8d','https://ajel.sa/local/cdzpttl8d','علي الجريبي','الرياض','2026-09-06T15:35:00.000Z','Wed, 07 Oct 2026 19:33:52 GMT','2026-09-06T21:59:20.614Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop-txMG4e-v.png','/api/media/37f1d06d-c924-4d5d-8005-1c55f88c85fb','/api/media/37f1d06d-c924-4d5d-8005-1c55f88c85fb?variant=thumbnail','صحة جازان تُبرم 7 اتفاقيات شراكة مجتمعية لدعم الخدمات الصحية والرعاية التكاملية',1200,675,'valid','published','archived','valid',40,'c4536b108ef20f6ddface0a39e44813e48d38ceaa847d074b575fd50ce732496','4a90680630389f586294191af99c77a74e1ae6486f00dbe138d966cc84ceae52','محدّث','2026-09-06T21:59:20.614Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الصحة ب منطقة جازان","الصحة العامة","الثقافة والفنون","جازان","الرياض"]','["وزارة الصحة ب منطقة جازان","الصحة العامة","الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T19:33:53.747Z',200,5,0,'source_article_available','',NULL,NULL,'body:4752159a1479d9775dbce5a1dfe32d4325d54b4179ede37dcd8303bd32bfa005','Wed, 07 Oct 2026 19:33:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b4100236-4e94-4d99-acc9-a9c2e5d4d023','news-b4100236-4e94-4d99-acc9-a9c2e5d4d023','5 قتلى و5 مصابين.. طائرة "أمازون" تتجاوز مدرج مطار ميامي وتصطدم بمركبات','5 قتلي و5 مصابين طائره امازون تتجاوز مدرج مطار ميامي وتصطدم بمركبات','لقي خمسة أشخاص مصرعهم وأُصيب خمسة آخرون، إثر تجاوز طائرة شحن من طراز «بوينغ 767» تابعة لخدمة «برايم إير» التابعة لأمازون مدرجَ مطار ميامي الدولي في ولاية فلوريدا الأمريكية، الأحد، نحو الساعة الثانية بعد الظهر بالتوقيت المحلي.','["وأفادت رئيسة بلدية ميامي-ديد، دانييلا ليفين كافا، خلال مؤتمر صحفي، بأن المصابين نُقلوا إلى المستشفى لتلقي العلاج، فيما أكدت إدارة الطيران الفيدرالية الأمريكية أن الطائرة كانت قادمةً من مدينة سان خوان في بورتوريكو متجهةً إلى فلوريدا، مشيرةً إلى أنها ستفتح تحقيقاً في ملابسات الحادث.","اصطدام بمركبات واندلاع النيران وأفادت وكالة «فرانس برس»، نقلاً عن مسؤولين، بأن الطائرة اصطدمت بمركبات عقب تجاوزها المدرج، ما أدى إلى اندلاع النيران فيها.","فيما أوضحت وكالة «أسوشيتد برس» أن الطائرة توقفت بجوار أحد الطرق، وأظهرت صور متداولة وجود شاحنتين كبيرتين بالقرب منها وسط تصاعد كثيف للدخان من موقع الحادث.","وتوقفت الطائرة عند الطرف الشمالي الغربي للمطار، ما دفع سلطاته إلى إغلاق جميع المدارج وممرات الطائرات وتعليق حركة الرحلات على الأرض فور وقوع الحادث، وفق ما أوردته وكالة «رويترز».","ويُعدّ مطار ميامي الدولي من أكثر المطارات الأمريكية ازدحاماً، وقد شهد توقفاً كاملاً لحركة الطائرات على الأرض في انتظار التعامل مع الحادث والبدء في التحقيق بملابساته."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/v80pnic','https://sabq.org/article/v80pnic','','https://sabq.org/article/v80pnic','صحيفة سبق','','2026-09-06T15:56:00.000Z','2026-09-06T17:06:00.000Z','2026-09-07T04:44:27.423Z','https://media.sabq.org/news/2026/09/78e4436a-fede-4ad4-bd8e-045aaeb8933a/w801.webp','/api/media/b4100236-4e94-4d99-acc9-a9c2e5d4d023','/api/media/b4100236-4e94-4d99-acc9-a9c2e5d4d023?variant=thumbnail',' 5 قتلى و5 مصابين.. طائرة "أمازون" تتجاوز مدرج مطار ميامي وتصطدم بمركبات ',801,451,'valid','published','archived','valid',41,'c3a2804e77ccd915365d2ac6459ddd6438ac621cbf65af61750ce017fdd0a972','586dbbb0d28abefa893258b75c1da31e531248f25ad73cd8137e179d109132e2','محدّث','2026-09-06T21:59:22.852Z','2026-10-07T20:25:22.793Z','','',0,0,'international','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","السفر والسياحة"]','["الصحة العامة","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:33:50.943Z',200,5,0,'source_article_available','',NULL,NULL,'body:1c9cec2d80d5b3de75702833a09da919aedce7fbdb5100f557e56b6ba57c8c61','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('925d2dad-208b-494e-b538-f7cda796cbca','news-925d2dad-208b-494e-b538-f7cda796cbca','حزب البديل من أجل ألمانيا يتصدر انتخابات سكسونيا أنهالت بـ44% في فوز تاريخي','حزب البديل من اجل المانيا يتصدر انتخابات سكسونيا انهالت بـ44 في فوز تاريخي','حقق حزب البديل من أجل ألمانيا فوزاً تاريخياً في انتخابات ولاية سكسونيا أنهالت، متصدراً النتائج بنسبة 44% من الأصوات وفق استطلاعات الخروج، في سابقة غير مسبوقة تضع حزباً يمينياً متطرفاً على أعتاب السلطة في ولاية ألمانية للمرة الأولى منذ الحرب العالمية الثانية.','["وألحق الحزب هزيمة ساحقة بالمحافظين بزعامة المستشار فريدريش ميرتس، في مشهد يعكس تراجع شعبية الائتلاف الحاكم وصعود الأحزاب المتشددة في ألمانيا.","وبلغت نسبة المشاركة في الانتخابات 77% وفق هيئة البث الألمانية «زد.دي.إف».","وقال أولريش زيجموند (35 عاماً)، المرشح الرئيسي للحزب في الولاية: «صنعنا التاريخ في هذا البلد»، مشيراً إلى أن هذا الفوز يمثل خطوة أولى نحو الوصول إلى السلطة على المستوى الاتحادي في الانتخابات المقررة عام 2029.","وأضاف زيجموند: «أوضح الشعب بشكل قاطع أنه يريد أخيراً تغييراً سياسياً، وقبل أي شيء أظهر أنه يريده معنا».","ونشر الرئيس الأمريكي دونالد ترامب لقطة شاشة للنتيجة على منصة «تروث سوشال» دون تعليق، فيما أشاد زعماء اليمين المتطرف في دول أوروبية أخرى بالنتيجة باعتبارها تفويضاً بالتغيير.","انتكاسة للمستشار ميرتس تمثل النتيجة انتكاسة كبيرة للمستشار ميرتس، الذي تراجعت شعبيته إلى مستويات متدنية في ظل عزوف الناخبين عن إصلاحاته الاقتصادية المزمعة وأخطاء متكررة في أسلوب تواصله.","وأظهر استطلاع أجرته هيئة الإذاعة والتلفزيون الألمانية «إيه.آر.دي» أن 87% من ناخبي الولاية غير راضين عن الحكومة الاتحادية.","وقال مارسيل فراتشر، رئيس المعهد الألماني للأبحاث الاقتصادية، لوكالة رويترز: «نتيجة الانتخابات هي قبل أي شيء تصويت بحجب الثقة عن الحكومة الاتحادية»."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/4cfp4w9','https://sabq.org/article/4cfp4w9','','https://sabq.org/article/4cfp4w9','صحيفة سبق','','2026-09-06T16:00:00.000Z','2026-09-06T19:00:00.000Z','2026-09-06T22:08:22.106Z','https://media.sabq.org/news/2026/09/7a9d3745-353f-4656-a681-e1e628784f8a/w960.webp','/api/media/925d2dad-208b-494e-b538-f7cda796cbca','/api/media/925d2dad-208b-494e-b538-f7cda796cbca?variant=thumbnail','حزب البديل من أجل ألمانيا يتصدر انتخابات سكسونيا أنهالت بـ44% في فوز تاريخي',960,640,'valid','published','archived','valid',35,'3e4dba30b33389f62c846a3651271700ce0c9c350a1d464c90db5fc9a4b64e11','7819a998ad490ddf0268a95379aa98341f535c08a72aabf665d4518f785c7096','محدّث','2026-09-06T22:08:22.106Z','2026-10-07T20:25:22.793Z','','',0,0,'international','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة البث الألمانية زد دي","رئيس المعهد الألماني للأبحاث الاقتصادية","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','["هيئة البث الألمانية زد دي","رئيس المعهد الألماني للأبحاث الاقتصادية","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:42:11.865Z',200,9,0,'source_article_available','',NULL,NULL,'body:3964082f5fb361876cf3b51f4e1a1d8e39a4cb2465ade615eeb7e6646e406499','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('752203f7-67d4-4e7c-90c7-aaa0de4b8728','news-752203f7-67d4-4e7c-90c7-aaa0de4b8728','اختتام فعاليات منتدى «الطائف للهجن في التراث»','اختتام فعاليات منتدي الطائف للهجن في التراث','شهد الأمير فواز بن سلطان بن عبدالعزيز محافظ الطائف اليوم، ختام أعمال "منتدى الطائف للهجن في التراث"، الذي أقيم على مدى يومين، بمشاركة عدد من المختصين والمهتمين بالموروث الثقافي والإعلامي المرتبط بالهجن.','["وكان في استقبال سموه لدى وصوله مقر المنتدى صاحب السمو الأمير فهد بن جلوي بن عبدالعزيز بن مساعد نائب رئيس اللجنة الأولمبية والبارالمبية السعودية رئيس مجلس إدارة الاتحاد السعودي للهجن ، وعدد من قيادات الاتحاد.","وتجوّل سمو محافظ الطائف في المعرض المصاحب، الذي ضم (13) ركنًا اشتملت على مقتنيات ومحتويات تستعرض المكانة التاريخية والثقافية للهجن في الموروث السعودي، وما يرتبط بها من إرث حضاري، إلى جانب عدد من التجارب الإعلامية التي توثق حضورها وتطورها.","عقب ذلك، شاهد سموه والحضور عرضًا مرئيًا استعرض أبرز الجلسات والموضوعات والتوصيات والفعاليات التي شهدها المنتدى خلال فترة انعقاده.","وفي ختام الحفل، كرّم سمو محافظ الطائف الرعاة والجهات الداعمة والمشاركة؛ تقديرًا لإسهاماتهم في إنجاح المنتدى وإثراء برامجه الثقافية والرياضية."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/1ntzcu8zr','https://ajel.sa/misc/1ntzcu8zr','https://ajel.sa/misc/1ntzcu8zr','https://ajel.sa/misc/1ntzcu8zr','فريق التحرير','الرياض','2026-09-06T16:00:00.000Z','Wed, 07 Oct 2026 19:45:03 GMT','2026-09-06T22:17:21.069Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop-UMNFe2c9.png','/api/media/752203f7-67d4-4e7c-90c7-aaa0de4b8728','/api/media/752203f7-67d4-4e7c-90c7-aaa0de4b8728?variant=thumbnail','اختتام فعاليات منتدى «الطائف للهجن في التراث»',1200,675,'valid','published','archived','valid',40,'2371b1705e6993354c3227355e4ceea0a392017a65a3b208e9e4abbaeda64e73','397ff62dbc58ca767620ab77c5cc4106374ecc9e4e4e50c3bff86019375ebdde','محدّث','2026-09-06T22:17:21.069Z','2026-10-07T19:45:04.885Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إدارة الاتحاد السعودي للهجن","رئيس اللجنة الأولمبية والبارالمبية السعودية","الرياض"]','["مجلس إدارة الاتحاد السعودي للهجن","رئيس اللجنة الأولمبية والبارالمبية السعودية"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:45:04.885Z',200,5,0,'source_content_changed','',NULL,NULL,'body:826dad605f35c1e8ef1366a5e9f74a9739e08991d69f962a3278554e7fbce95e','Wed, 07 Oct 2026 19:45:03 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dda982fa-f778-4b94-a1a9-4431494f23e2','news-dda982fa-f778-4b94-a1a9-4431494f23e2','الجزائر تُعدّل قانون العقوبات لتنفيذ الإعدام بحق مفتعلي الحرائق ومختطفي القاصرين','الجزائر تعدل قانون العقوبات لتنفيذ الاعدام بحق مفتعلي الحرائق ومختطفي القاصرين','أكد الرئيس الجزائري عبد المجيد تبون، خلال ترؤسه اجتماع مجلس الوزراء، أن التعديلات المرتقبة على قانون العقوبات ستقتصر على «تنفيذ حكم الإعدام بحق مفتعلي ومدبري الحرائق عمداً، وكذا مختطفي القاصرين والمنكّلين بهم»، وذلك إضافةً إلى توجيهاته السابقة في هذا الشأن.','["وأمر الرئيس تبون بالشروع فوراً في صرف التعويضات للمتضررين من الحرائق خلال الأسبوع الجاري، مشدداً على ضرورة إبعاد المواطن عن أي إجراء بيروقراطي يُعيق حصوله على حقوقه.","كما وجّه وزير الفلاحة بالإشراف الميداني المباشر على تعويضات القطاع الزراعي، ولا سيما تعويض أصحاب المواشي، مؤكداً ضرورة الشروع الفوري في العملية في ظل توفر الإمكانات اللازمة لإنجاحها.","وتعود آخر حالة تنفيذ لعقوبة الإعدام في الجزائر إلى عام 1993، قبل أن تدخل البلاد في مرحلة تجميد فعلي لتنفيذ هذه الأحكام.","ومنذ ذلك الحين، واصل القضاء الجزائري إصدار أحكام بالإعدام، خصوصاً في قضايا الإرهاب والقتل العمد والجرائم بالغة الخطورة، غير أنها بقيت دون تنفيذ.","وأحيت موجة الحرائق التي اجتاحت الجزائر مؤخراً النقاش حول عقوبة الإعدام المجمّدة، إذ أعلن الرئيس تبون في وقت سابق عن قرار العودة إلى تنفيذها بحق كل من يثبت تورطه في إضرام النيران عمداً، موجّهاً وزير العدل لإعداد مشروع التعديل قبل منتصف سبتمبر الجاري.","وتأتي هذه الإجراءات في سياق التعامل مع تداعيات الحرائق التي خلّفت خسائر بشرية ومادية فادحة في مناطق عدة من البلاد."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/bym12y3','https://sabq.org/article/bym12y3','','https://sabq.org/article/bym12y3','صحيفة سبق','','2026-09-06T16:10:00.000Z','2026-09-06T19:10:00.000Z','2026-09-06T22:17:21.936Z','https://media.sabq.org/news/2026/09/46fa9da5-8f87-484b-b5e5-90d29f57feb8/w846.webp','/api/media/dda982fa-f778-4b94-a1a9-4431494f23e2','/api/media/dda982fa-f778-4b94-a1a9-4431494f23e2?variant=thumbnail','الجزائر تُعدّل قانون العقوبات لتنفيذ الإعدام بحق مفتعلي الحرائق ومختطفي القاصرين',846,551,'valid','published','archived','valid',41,'42d03733ae4c0aa769b676b12f3e85e934dff2809eecec4296113bf4519f63f5','ea7a1bb86f81c967182eb0837e9c24dd194bc6e32d1b95d3bb528e60bc24265c','محدّث','2026-09-06T22:17:21.936Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_national','مهم',67,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس الوزراء أن التعديلات المرتقبة","وزير الفلاحة بالإشراف الميداني المباشر"]','["مجلس الوزراء أن التعديلات المرتقبة","وزير الفلاحة بالإشراف الميداني المباشر"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:44:57.903Z',200,5,0,'source_article_available','',NULL,NULL,'body:346a4813966aa64466d0a3e49c80bdab8507efdf39ee81bf51fc098bb1a6a38b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e2fd8641-ae82-48d8-a577-8dfee8f62674','news-e2fd8641-ae82-48d8-a577-8dfee8f62674','الأمين العام لمجلس التعاون: الأمن الخليجي ينتقل إلى استباق الجريمة بأدوات المستقبل','الامين العام لمجلس التعاون الامن الخليجي ينتقل الي استباق الجريمه بادوات المستقبل','واستعرض الأمين العام ما حققته منظومة العمل الخليجي من تقدم في مجالات مكافحة المخدرات وجرائم غسل الأموال، مشيراً إلى الانتهاء من إعداد مشروع الاستراتيجية الخليجية لمكافحة الجرائم الإلكترونية وجرائم الذكاء الاصطناعي.','["أكد الأمين العام لمجلس التعاون لدول الخليج العربية جاسم محمد البديوي، أن ملتقى حوار الأمن والتاريخ يجسّد أهمية كبرى لتعزيز الرؤى المستقبلية حول الأمن والتنمية، مشدداً على أن قوة المنظومة الخليجية تنبع من قوة دولها وقدرتها على العمل المشترك في مواجهة التحديات.","جاء ذلك خلال مشاركته في ملتقى حوار الأمن والتاريخ، الذي نظّمته وزارة الداخلية في الرياض تحت عنوان «تاريخنا ومستقبلنا..","أمن ونماء»، بمشاركة أكثر من 160 متحدثاً من داخل المملكة وخارجها، يمثلون قيادات ومسؤولين وخبراء وأكاديميين متخصصين في مجالات الأمن والتنمية.","وأوضح البديوي أن الأمن كان حاضراً منذ البدايات الأولى لمسيرة مجلس التعاون، وأن المنظومة الخليجية بلغت مرحلة متقدمة من التكامل والجاهزية الأمنية المشتركة، لافتاً إلى أن تطور طبيعة الجريمة والتهديدات العابرة للحدود يستوجب الانتقال من التعامل مع الجريمة بعد وقوعها إلى استباقها وتفكيك شبكاتها وتجفيف مواردها.","وأكد أن الذكاء الاصطناعي والتقنيات الحديثة تمثّل فرصة كبيرة لتطوير العمل الأمني، غير أنها تفرض في الوقت ذاته تحديات جديدة نتيجة استغلالها في أنماط متطورة من الجريمة، مؤكداً أن حماية الإنسان والأسرة والمجتمع تبقى في صميم العمل الأمني.","وأشار البديوي إلى أهمية الجاهزية العملياتية المشتركة، وما تمثله التمارين التعبوية الأمنية المشتركة، وفي مقدمتها تمرين «أمن الخليج العربي»، من ترجمة عملية للتكامل بين الأجهزة الأمنية لدول المجلس، ورفع مستوى التنسيق والاستجابة في مواجهة السيناريوهات الأمنية المتغيرة.","وخلص إلى أن التجارب الناجحة في دول المجلس تمثّل رصيداً خليجياً مشتركاً يمكن تبادل خبراته والبناء عليه، مؤكداً أن العلاقة بين الأمن والتنمية باتت أكثر ترابطاً في ظل التحولات الكبرى التي تشهدها المنطقة، وأن الأمن لا يقف على هامش التنمية، بل يحمي مسيرتها ويحفظ مكتسباتها."]','الذكاء الاصطناعي','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/lxqgvtw','https://sabq.org/article/lxqgvtw','','https://sabq.org/article/lxqgvtw','صحيفة سبق','الرياض','2026-09-06T16:20:00.000Z','2026-09-06T19:20:00.000Z','2026-09-06T22:28:50.121Z','https://media.sabq.org/news/2026/09/cc05e974-a253-4ef5-9218-9fa6b9e52328/w1320.webp','/api/media/e2fd8641-ae82-48d8-a577-8dfee8f62674','/api/media/e2fd8641-ae82-48d8-a577-8dfee8f62674?variant=thumbnail','الأمين العام لمجلس التعاون: الأمن الخليجي ينتقل إلى استباق الجريمة بأدوات المستقبل',1320,907,'valid','published','archived','valid',52,'046b4b99a482f31396c16c080fb2238a10507929fe754f0a5ee21654ad7f3cee','805bdd6158837ef83d1570e7eb6c4a0134eb34278bfd86d11ef7dfbf1038775a','محدّث','2026-09-06T22:28:50.121Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','مهم',69,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية في الرياض تحت","مجلس التعاون وأن المنظومة الخليجية","الرياض","الخليج العربي"]','["وزارة الداخلية في الرياض تحت","مجلس التعاون وأن المنظومة الخليجية","الخليج العربي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"المناطق","score":1.5},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:51:27.285Z',200,5,0,'source_article_available','',NULL,NULL,'body:d0668d973d2e3ae942f8c4ac2a1a687ac7e46135ec86ef0fe8eb33fe539c0413','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d7f16cd0-0d9f-4f0e-b56e-f8c34b028877','news-d7f16cd0-0d9f-4f0e-b56e-f8c34b028877','اختتام مشاركة المملكة في معرض موسكو الدولي للكتاب 2026','اختتام مشاركه المملكه في معرض موسكو الدولي للكتاب 2026','اختتمت هيئة الأدب والنشر والترجمة مشاركة المملكة العربية السعودية في معرض موسكو الدولي للكتاب 2026، الذي أُقيم خلال الفترة من 2 حتى 6 سبتمبر 2026، في العاصمة الروسية موسكو، وسط حضور ثقافي ومعرفي يعكس تنامي مكانة المملكة في قطاع الأدب والنشر والترجمة، ويؤكد حضورها الفاعل في المشهد الثقافي الدولي.','["وأكد الرئيس التنفيذي لهيئة الأدب والنشر والترجمة الدكتور عبداللطيف بن عبدالعزيز الواصل، أن مشاركة المملكة في معرض موسكو الدولي للكتاب تأتي امتدادًا لجهود الهيئة في التعريف بالإنتاج الأدبي والمعرفي السعودي، وإبراز التحولات التي يشهدها قطاع الأدب والنشر والترجمة في المملكة، مشيرًا إلى أن الجناح السعودي قدّم صورة متكاملة عن الحراك الثقافي السعودي وما يشهده من تطور متسارع في ظل رؤية السعودية 2030.","وأوضح أن البرنامج الثقافي المصاحب للمشاركة أسهم في إبراز التجارب الإبداعية السعودية عبر سلسلة من الندوات الحوارية والأمسيات الشعرية، التي ناقشت قضايا الأدب والنشر والترجمة، وسلطت الضوء على المنجز الثقافي السعودي وتأثيره في الفضاء الدولي، بمشاركة نخبة من الأدباء والمثقفين السعوديين.","وأشار إلى أن المشاركة مثّلت فرصة لتعزيز التواصل المهني وبناء الشراكات المعرفية مع العاملين في صناعة الكتاب والنشر، بما يسهم في توسيع آفاق التعاون والتبادل الثقافي، ويدعم وصول المحتوى السعودي إلى شرائح أوسع من القرّاء والمهتمين على الصعيدين الروسي والدولي.","وضم جناح المملكة عددًا من الجهات الحكومية و الثقافية والمعرفية، بقيادة هيئة الأدب والنشر والترجمة، وبمشاركة مكتبة الملك فهد الوطنية ، و مكتبة الملك عبدالعزيز العامة ، ومجمع الملك عبدالعزيز للمكتبات الوقفية، و دارة الملك عبدالعزيز ، ووزارة الشؤون الإسلامية والدعوة والإرشاد، و مجمع الملك فهد لطباعة المصحف الشريف ، وشركة ناشر للنشر والتوزيع، ومركز الملك عبدالعزيز للتواصل الحضاري، و الملحقية الثقافية السعودية في تركيا ، وجامعة الأميرة نورة بنت عبدالرحمن، ومركز الأمير محمد بن سلمان للخط العربي، في مشاركة تعكس تكامل الجهود الوطنية لتعزيز حضور المملكة في المحافل الثقافية الدولية."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/5bam18zyz','https://ajel.sa/misc/5bam18zyz','https://ajel.sa/misc/5bam18zyz','https://ajel.sa/misc/5bam18zyz','فريق التحرير','','2026-09-06T16:26:00.000Z','Wed, 07 Oct 2026 19:52:36 GMT','2026-09-06T22:41:20.631Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop--82qYIWI.png','/api/media/d7f16cd0-0d9f-4f0e-b56e-f8c34b028877','/api/media/d7f16cd0-0d9f-4f0e-b56e-f8c34b028877?variant=thumbnail','اختتام مشاركة المملكة في معرض موسكو الدولي للكتاب 2026',1200,675,'valid','published','archived','valid',60,'9a59646d6fec2e613beb924491e691ebf61d377547f1f4485e627d4e633f750e','242ea9f390ec6df3c2706e8c8d4add9edbc6fc546b01fb0699c70b701f0fc979','محدّث','2026-09-06T22:41:20.631Z','2026-10-07T19:52:37.575Z','','',0,0,'saudi_national','أولوية قصوى',82,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الأدب والنشر والترجمة مشاركة","التعليم والتدريب","الاقتصاد والأسواق","تركيا"]','["هيئة الأدب والنشر والترجمة مشاركة","التعليم والتدريب","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الطاقة والصناعة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:52:37.575Z',200,5,0,'source_content_changed','',NULL,NULL,'body:28761b0d76a083c567dd57fa56ab8a46eede169824a9532fc0f9a3d8bbf184a1','Wed, 07 Oct 2026 19:52:36 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('aaa86cb7-084d-4892-a26c-6cd33b26060f','news-aaa86cb7-084d-4892-a26c-6cd33b26060f','«حماس» تصف مقتل طفلة فلسطينية بالقصف الإسرائيلي بـ"الجريمة المركبة"','حماس تصف مقتل طفله فلسطينيه بالقصف الاسرائيلي بـ الجريمه المركبه','ودعا المتحدث باسم «حماس» الدول العربية والإسلامية المشاركة في مجلس السلام إلى العمل على فضح الموقف الإسرائيلي الذي وصفه بأنه «يتلاعب بمجلس السلام وقراراته».','["اتهمت حركة «حماس» الفلسطينية إسرائيل بمواصلة ما وصفته بـ«حرب الإبادة» في قطاع غزة، عقب مقتل طفلة فلسطينية في قصف إسرائيلي، داعيةً الدول العربية والإسلامية المشاركة في «مجلس السلام» إلى «اتخاذ موقف واضح وعملي إزاء الجرائم الإسرائيلية».","وقال المتحدث باسم الحركة حازم قاسم، إن «مقتل الطفلة وفاء عكيلة في قصف نفذته طائرات إسرائيلية أثناء مغادرتها مكان تلقيها دروس اليوم الأول من العام الدراسي يمثل جريمة مركبة»، مؤكداً أن ذلك يعكس استمرار الحرب التي تستهدف الشعب الفلسطيني في غزة، بما يشمل الأطفال والنساء.","وأضاف قاسم أن «صمت مجلس السلام ومديره ميلادنوف لا يمكن فهمه إلا باعتباره تواطؤاً في هذه الجرائم، وعجزاً عن إلزام إسرائيل بأي من الاتفاقات التي تم التوصل إليها».","وكان الرئيس الأمريكي دونالد ترامب قد أعلن في وقت سابق عن تشكيل «مجلس سلام» بشأن غزة، يضم وزير الخارجية الأمريكي ماركو روبيو، والمبعوث الخاص ستيف ويتكوف، والمستثمر جاريد كوشنر، ورئيس الوزراء البريطاني الأسبق توني بلير، ورئيس البنك الدولي أجاي بانجا، ونائب مستشار الأمن القومي الأمريكي روبرت غابرييل.","وفي منتصف نوفمبر الماضي، وافق مجلس الأمن الدولي على مشروع قرار اقترحته الولايات المتحدة دعماً للخطة الشاملة التي طرحها ترامب لتسوية الأوضاع في قطاع غزة، إذ صوّت لصالحه 13 عضواً من أصل 15، فيما امتنعت روسيا والصين عن التصويت.","وتنصّ الخطة الأمريكية على إنشاء إدارة دولية مؤقتة لقطاع غزة، وتشكيل «مجلس سلام» برئاسة ترامب، فضلاً عن تفويض باستخدام القوة لقوات استقرار دولية يُقرر نشرها بالتنسيق مع إسرائيل ومصر."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/i6r9d30','https://sabq.org/article/i6r9d30','','https://sabq.org/article/i6r9d30','صحيفة سبق','','2026-09-06T16:30:00.000Z','2026-09-06T19:30:00.000Z','2026-09-06T22:41:22.200Z','https://media.sabq.org/news/2026/09/a43db411-d949-44d4-8746-b5905f5b66f4/w1600.webp','/api/media/aaa86cb7-084d-4892-a26c-6cd33b26060f','/api/media/aaa86cb7-084d-4892-a26c-6cd33b26060f?variant=thumbnail','«حماس» تصف مقتل طفلة فلسطينية بالقصف الإسرائيلي بـ"الجريمة المركبة"',1600,900,'valid','published','archived','valid',41,'da07e1b6f93c4a3d5507b7a2877e6fec32dcafbc1787315167bfff8e11454e31','819cd320e20dc4da828e1e664857422110ad2966d0a9788fb4034191672b4276','محدّث','2026-09-06T22:41:22.200Z','2026-10-07T20:25:22.793Z','','',0,0,'gulf_arab','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس السلام إلى اتخاذ موقف","وزير الخارجية الأمريكي ماركو روبيو","غزة","روسيا","الصين","فلسطين","الولايات المتحدة"]','["مجلس السلام إلى اتخاذ موقف","وزير الخارجية الأمريكي ماركو روبيو","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:52:01.643Z',200,5,0,'source_article_available','',NULL,NULL,'body:3f3cbf0698ca2912ca6c8ae9e4254819df0be90f62bbc99cc213692c3e29d9d2','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9c643473-6beb-40da-89ce-740a83f1b021','news-9c643473-6beb-40da-89ce-740a83f1b021','بالفيديو.. هدم مسجد تاريخي في الهند يشعل غضب باكستان واتهامات بـ"معاداة الإسلام"','بالفيديو هدم مسجد تاريخي في الهند يشعل غضب باكستان واتهامات بـ معاداه الاسلام','وربط خان الواقعة بما وصفه بإرث طويل من التوتر الديني في الهند، مستشهداً بهدم مسجد بابري عام 1992 بوصفه نموذجاً بارزاً على التعصب والتمييز الديني. وحثّ المتحدث الباكستاني في بيان رسمي المجتمعَ الدولي على التحرك إزاء ما وصفه بـ«الاضطهاد المنهجي» الذي يتعرض له المسلمون في الهند، مشيراً إلى استمرار استهداف أماكن العبادة الإسلامية وتدميرها في ظل ما وصفه…','["وصف المتحدث باسم وزارة الخارجية الباكستانية سجاد حيدر خان هدمَ المسجد التاريخي في ولاية أوتار براديش الهندية بأنه «عمل مستهجن» استهدف دار عبادة ذات قيمة تاريخية، مؤكداً أن السلطات الهندية ترتكب بذلك انتهاكاً صريحاً بحق التراث الإسلامي، وذلك في تصريحات نقلتها صحيفة «دون» الباكستانية.","وربط خان الواقعة بما وصفه بإرث طويل من التوتر الديني في الهند، مستشهداً بهدم مسجد بابري عام 1992 بوصفه نموذجاً بارزاً على التعصب والتمييز الديني.","وحثّ المتحدث الباكستاني في بيان رسمي المجتمعَ الدولي على التحرك إزاء ما وصفه بـ«الاضطهاد المنهجي» الذي يتعرض له المسلمون في الهند، مشيراً إلى استمرار استهداف أماكن العبادة الإسلامية وتدميرها في ظل ما وصفه بـ«رعاية الدولة»، وفقاً لوكالة «د ب أ».","وطالبت إسلام آباد بمساءلة السلطات الهندية عن الإجراءات التي تمس الحريات الدينية والحقوق الثقافية للأقليات، مؤكدةً أن حماية دور العبادة وصون التراث الثقافي يجب أن يشملا جميع المكونات الدينية وفي مقدمتها المسلمون."]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/7f7age3','https://sabq.org/article/7f7age3','','https://sabq.org/article/7f7age3','صحيفة سبق','','2026-09-06T16:30:00.000Z','2026-09-06T19:30:00.000Z','2026-09-06T22:41:23.903Z','https://media.sabq.org/news/2026/09/a74a90e2-39fe-4dc5-8ea9-9fcfbb25938e/w686.webp','/api/media/9c643473-6beb-40da-89ce-740a83f1b021','/api/media/9c643473-6beb-40da-89ce-740a83f1b021?variant=thumbnail','بالفيديو.. هدم مسجد تاريخي في الهند يشعل غضب باكستان واتهامات بـ"معاداة الإسلام"',686,447,'valid','published','archived','valid',41,'117f782d3925c8a1fcb6ed62a75fef39cc3d19d174b2e77dbf547d07ed3ec5a2','b6935429f0051dcf89121cd9141e3632b3b0ef2c3570f9fd022e71acf1b60b9f','محدّث','2026-09-06T22:41:23.903Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_national','مهم',67,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الخارجية الباكستانية سجاد حيدر"]','["وزارة الخارجية الباكستانية سجاد حيدر"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:52:01.649Z',200,5,0,'source_article_available','',NULL,NULL,'body:77d666a2d4dea2129383796ae0f9d962d60c31afd025fbd9d04aceff2d6dfb1a','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('eeba7cd8-517b-402b-97b5-c145aacb72f8','news-eeba7cd8-517b-402b-97b5-c145aacb72f8','"الأرصاد" يحذر 8 مناطق من أمطار رعدية وسيول وبرد ورياح وغبار','الارصاد يحذر 8 مناطق من امطار رعديه وسيول وبرد ورياح وغبار','أصدر المركز الوطني للأرصاد نشرته الجوية ليوم الاثنين، متوقعاً هطول أمطار رعدية متوسطة إلى غزيرة تؤدي إلى جريان السيول، مصحوبة بزخات من البرد، على أجزاء من مناطق جازان وعسير والباحة ومكة المكرمة.','["وأشار المركز إلى احتمال تكوّن السحب الرعدية الممطرة على أجزاء من منطقة نجران، والأجزاء الجنوبية من منطقتي الشرقية والرياض، إضافة إلى مرتفعات منطقة المدينة المنورة، مع تأثير رياح نشطة مثيرة للأتربة والغبار على أجزاء من تلك المناطق.","حالة الطقس المتوقعة بحسب المدن الرئيسية: • الرياض: سحب رعدية ممطرة مع رياح نشطة وأتربة مثارة، رطوبة 55%، أعلى درجة حرارة 42°م، أدنى درجة 31°م. • مكة المكرمة: صحو إلى غائم جزئي، رطوبة 35%، أعلى درجة حرارة 45°م، أدنى درجة 32°م. • المدينة المنورة: عوالق وغائم جزئي، رطوبة 85%، أعلى درجة حرارة 38°م، أدنى درجة 30°م. • جدة: عوالق وغائم جزئي، رطوبة 85%، أعلى درجة حرارة 43°م، أدنى درجة 30°م. • الدمام: أمطار رعدية متوسطة إلى غزيرة مع رياح نشطة، رطوبة 85%، أعلى درجة حرارة 28°م، أدنى درجة 18°م. • أبها: طقس مستقر، رطوبة 55%، أعلى درجة حرارة 36°م، أدنى درجة 23°م. • تبوك: طقس مستقر، رطوبة 25%، أعلى درجة حرارة 43°م، أدنى درجة 25°م. • بريدة: طقس مستقر، رطوبة 25%، أعلى درجة حرارة 40°م، أدنى درجة 24°م. • حائل: أمطار رعدية متوسطة إلى غزيرة مع رياح نشطة، أعلى درجة حرارة 27°م، أدنى درجة 19°م. • الباحة: رياح نشطة، رطوبة 35%، أعلى درجة حرارة 38°م، أدنى درجة 24°م. • عرعر: رياح نشطة، رطوبة 40%، أعلى درجة حرارة 37°م، أدنى درجة 23°م. • سكاكا: أمطار رعدية متوسطة إلى غزيرة مع رياح نشطة وأتربة مثارة، رطوبة 80%، أعلى درجة حرارة 37°م، أدنى درجة 31°م. • جازان: سحب رعدية ممطرة مع رياح نشطة وأتربة مثارة.","حالة البحار: توقّع المركز في البحر الأحمر أن يكون الجزء الشمالي مائجاً بارتفاع موج يتراوح بين متر ومترين، يصل إلى مترين ونصف باتجاه خليج العقبة، مع رياح شمالية غربية إلى غربية بسرعة 20-45 كم/ساعة تصل إلى 50 كم/ساعة.","أما الجزء الأوسط فيشهد موجاً متوسطاً بارتفاع متر إلى مترين، فيما يتراوح الموج في الجزء الجنوبي بين خفيف ومتوسط مع احتمال وصوله إلى أكثر من مترين عند تكوّن السحب الرعدية، ورياح بسرعة 15-38 كم/ساعة قد تتجاوز 50 كم/ساعة.","وفي الخليج العربي ، يُتوقع أن يكون الموج خفيفاً في الجزء الشمالي بارتفاع نصف متر إلى متر مع رياح شرقية إلى جنوبية شرقية بسرعة 10-28 كم/ساعة، وكذلك في الجزء الجنوبي مع رياح جنوبية غربية إلى غربية بسرعة 10-30 كم/ساعة."]','المناطق','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/172h7dr','https://sabq.org/article/172h7dr','','https://sabq.org/article/172h7dr','صحيفة سبق','الرياض','2026-09-06T16:40:00.000Z','2026-09-06T19:40:00.000Z','2026-09-06T22:50:22.621Z','https://media.sabq.org/news/2026/09/18e416ec-239c-4866-a8b3-03500adcca88/w1600.webp','/api/media/eeba7cd8-517b-402b-97b5-c145aacb72f8','/api/media/eeba7cd8-517b-402b-97b5-c145aacb72f8?variant=thumbnail',' "الأرصاد" يحذر 8 مناطق من أمطار رعدية وسيول وبرد ورياح وغبار',1600,893,'valid','published','archived','valid',99,'f807c1f9fd8029bc65fbb8a31acf4777c7f7bd05c57b64c98fde46c4ad0e2b5a','75875b34a65dd66e3ab8e07ffc1d45d4bbaee557e167210e5bedc532be0dde80','محدّث','2026-09-06T22:50:22.621Z','2026-10-07T20:00:53.928Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة","جدة","عسير","تبوك","جازان","نجران","الرياض"]','["الطقس والمناخ","الخليج العربي","المدينة المنورة"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:00:53.928Z',200,6,0,'source_article_available','',NULL,NULL,'body:df4826fbd84ec9575ef63a04c98616914076161fb4bd43e55d6c7f63db0a68b5','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('277032c1-e16a-4beb-b609-a35697b3b3fd','news-277032c1-e16a-4beb-b609-a35697b3b3fd','مقتل مدنيَّين وإصابة 6 آخرين في هجمات بمسيّرات أوكرانية على بيلغورود وغورلوفكا','مقتل مدنيين واصابه 6 اخرين في هجمات بمسيرات اوكرانيه علي بيلغورود وغورلوفكا','أعلنت السلطات الروسية مقتل مدنيَّين وإصابة اثنين آخرين جراء هجمات نفّذتها طائرات مسيّرة أوكرانية على مناطق في مقاطعة بيلغورود الروسية، فيما أُصيب أربعة مدنيين إثر هجوم مماثل استهدف مدينة غورلوفكا في جمهورية دونيتسك الشعبية.','["وأفادت غرفة العمليات في مقاطعة بيلغورود، مساء الأحد، بأن رجلاً وامرأة لقيا حتفهما متأثرَين بجروحهما، بعد أن استهدفت طائرة مسيّرة من طراز «إف بي في» سيارة قرب قرية أوكتيابرسكايا غوتنيا في منطقة بوريسوف، مع تسجيل أضرار مادية في المركبة.","وأضافت غرفة العمليات في بيان نشرته عبر منصة «ماكس»، أن رجلين أُصيبا أيضاً إثر غارة بطائرة مسيّرة استهدفت مركبة في قرية سولوتي بمنطقة فالويسكي.","وفي حادث منفصل، أعلن عمدة مدينة غورلوفكا إيفان بريخودكو، عبر منصة «ماكس»، إصابة أربعة مدنيين بجروح جراء هجوم نفّذته القوات المسلحة الأوكرانية بطائرة مسيّرة على المدينة، دون الإفصاح عن مزيد من التفاصيل بشأن حالتهم الصحية أو حجم الأضرار.","وتأتي هذه الهجمات في سياق تصاعد العمليات العسكرية المتبادلة بين روسيا وأوكرانيا، إذ تشهد المناطق الحدودية الروسية استهدافاً متكرراً بالطائرات المسيّرة الأوكرانية."]','السياسة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/bq10r2h','https://sabq.org/article/bq10r2h','','https://sabq.org/article/bq10r2h','صحيفة سبق','','2026-09-06T16:50:00.000Z','2026-09-06T19:50:00.000Z','2026-09-06T22:59:22.844Z','https://media.sabq.org/news/2026/09/4f27a656-c076-4dce-94f3-de50a72cb5e3/w1600.webp','/api/media/277032c1-e16a-4beb-b609-a35697b3b3fd','/api/media/277032c1-e16a-4beb-b609-a35697b3b3fd?variant=thumbnail','مقتل مدنيَّين وإصابة 6 آخرين في هجمات بمسيّرات أوكرانية على بيلغورود وغورلوفكا',1600,900,'valid','published','archived','valid',53,'10456bd7ad9bf4be5b7c0be6f79f7be4a75aaee843ff998aa6cd7a1c392a60f1','304b4236121853f91473ef5dbe3a7f322ad1e47421aa1ce3d71c934c329ee670','محدّث','2026-09-06T22:59:22.844Z','2026-10-07T20:27:48.525Z','','',0,0,'international','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["روسيا","أوكرانيا"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:27:48.525Z',200,7,0,'source_article_available','',NULL,NULL,'body:91acd0032844df1190f556e25b2b3848489ee5d6d1a889bfa39bc2120b3f7690','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('87f6c0e3-428a-4ebe-a277-9dde3c61b570','news-87f6c0e3-428a-4ebe-a277-9dde3c61b570','رابطةُ العالم الإسلامي تدين التصريحات الإسرائيلية بشأن تهجير الشعب الفلسطيني','رابطه العالم الاسلامي تدين التصريحات الاسرائيليه بشان تهجير الشعب الفلسطيني','أدانَتْ رابطةُ العالَم الإسلامي - باستنكارٍ شديدٍ- التصريحاتِ الصادرة عن وزير الأمن القومي الإسرائيلي، إيتمار بن غفير ، ووزير الدفاع الإسرائيلي، يسرائيل كاتس ، بشأن تهجير الشّعب الفلسطيني من قطاع " غزة "، وما تضمّنته من طرحِ خططٍ وآلياتٍ تستهدف إخراج الفلسطينيين قسْرًا من أرضهم.','["وفي بيانٍ للأمانة العامة للرابطة، ندَّد معالي الأمين العام، رئيسُ هيئة علماء المسلمين ، الشيخ الدكتور محمد بن عبدالكريم العيسى، بهذه التصريحات المرفوضة والمُدانة، مؤكِّدًا أنها تأتي في سياقِ الانتهاكات الإسرائيلية لكل القوانين والأعرافِ الدّولية والإنسانية في الأرض الفلسطينية المحتلة، وتقويضِ جهود السلام.","وشدَّد العيسى على الضرورةِ المُلحّة لاضطلاع المُجتمع الدوليّ بمسؤولياته القانونية والأخلاقية؛ تجاهَ الوقف الفوريّ لكافّة الانتهاكات الإسرائيلية، ومحاولاتها لفرض واقعٍ ديموغرافيّ أو جغرافيٍّ جديدٍ في الأرض الفلسطينية المحتلة، مثمّنًا- بتأييدٍ كبيرٍ- البيانَ الصادرَ عن وزراء خارجية المملكة العربية السعودية ، و المملكة الأردنية الهاشمية ، ودولة الإمارات العربية المتحدة ، و جمهورية إندونيسيا ، و جمهورية باكستان الإسلامية ، والجمهورية التركية، ودولة قطر ، و جمهورية مصر العربية ، في هذا الشأن، وتضامُنهم الراسِخ مع الشّعب الفلسطيني، ودعْمهم الثابت لحقوقه المَشروعة، وفي مقدّمتها: حقُّه في إقامة الدولة الفلسطينية المُستقِلَّة، وفقَ مسار حلِّ الدولتين، والقرارات الدولية ذات الصِّلة، باعتباره السبيلَ الوحيدَ لتحقيق السّلام العادلِ والدائمِ في المنطقة."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/2zn4ynjjq','https://ajel.sa/international/2zn4ynjjq','https://ajel.sa/international/2zn4ynjjq','https://ajel.sa/international/2zn4ynjjq','فريق التحرير','','2026-09-06T16:52:00.000Z','Wed, 07 Oct 2026 20:58:54 GMT','2026-09-06T23:18:21.816Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%B1%D8%A7%D8%A8%D8%B7%D8%A9-%D8%A7%D9%84%D8%B9%D8%A7%D9%84%D9%85-%D8%A7%D9%84%D8%A5%D8%B3%D9%84%D8%A7%D9%85%D9%8A-kBtvlum-.webp','/api/media/87f6c0e3-428a-4ebe-a277-9dde3c61b570','/api/media/87f6c0e3-428a-4ebe-a277-9dde3c61b570?variant=thumbnail','رابطةُ العالم الإسلامي تدين التصريحات الإسرائيلية بشأن تهجير الشعب الفلسطيني',1200,675,'valid','published','archived','valid',46,'5ca6c3182e34ecaa193974ca72a35d319b171d7c99a65109be63a4e41b77db2e','88b5e9fa83036739a5b4bf90147cbabb68ad03b825f5eec870a876d23d5b562d','محدّث','2026-09-06T23:18:21.816Z','2026-10-07T20:58:56.364Z','','',0,0,'saudi_national','أولوية قصوى',82,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس هيئة علماء المسلمين الشيخ","هيئة علماء المسلمين الشيخ الدكتور","وزير الأمن القومي الإسرائيلي إيتمار","غزة","فلسطين"]','["رئيس هيئة علماء المسلمين الشيخ","هيئة علماء المسلمين الشيخ الدكتور","وزير الأمن القومي الإسرائيلي إيتمار"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:58:56.364Z',200,9,0,'source_content_changed','',NULL,NULL,'body:8381b13c62e4de77127c3632b9719c067e00e352c823e8e08d9a1be3ca3a1eba','Wed, 07 Oct 2026 20:58:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('43ffa23c-8089-4876-893c-9d46b13b708a','news-43ffa23c-8089-4876-893c-9d46b13b708a','مؤتمر «حوار الأمن والتاريخ» يناقش دور المؤسسات في تعزيز الهوية الوطنية لدى الشباب','مؤتمر حوار الامن والتاريخ يناقش دور المؤسسات في تعزيز الهويه الوطنيه لدي الشباب','وتناولت الجلسة الآليات المؤسسية والمجتمعية التي تسهم في بناء الهوية الوطنية، وترسيخ قيمها لدى الشباب، إلى جانب دور الأسرة والمدرسة، والجامعة والبرامج التطوعية وأنشطتها اللاصفية في هذا المجال.','["ناقشت جلسة \"الشباب والهوية الوطنية\" ضمن أعمال \"مؤتمر حوار الأمن والتاريخ 2026\" دور المؤسسات التعليمية والمجتمعية في تعزيز الهوية الوطنية لدى الشباب، في ظل ما يشهده الجيل الحالي من انفتاح واسع على مصادر متعددة للمعلومات والتأثير.","وتناولت الجلسة الآليات المؤسسية والمجتمعية التي تسهم في بناء الهوية الوطنية، وترسيخ قيمها لدى الشباب، إلى جانب دور الأسرة والمدرسة، والجامعة والبرامج التطوعية وأنشطتها اللاصفية في هذا المجال. وأكدت أن البيئة المجتمعية في المملكة أسهمت كذلك في نقل هذه القيم إلى المقيمين وتأثره من خلال التفاعل اليومي، والمشاركة في الأنشطة، والمناسبات المختلفة، بما يعكس طبيعة المجتمع السعودي، وقيمه الأصيلة.","وتطرقت إلى دور البرامج التطوعية والأنشطة اللاصفية في الجامعات السعودية في تعزيز ارتباط الشباب بمجتمعهم، وإسهامها في دعم جودة الحياة وترسيخ الهوية الوطنية بمختلف أبعادها، بما في ذلك الهويات الوطنية المرتبطة بالمناطق وموروثاتها الثقافية والاقتصادية.","واستعرضت الجلسة في هذا السياق نماذج من الخصوصيات الثقافية والمجتمعية للمناطق مثل: ارتباط منطقة الجوف بزراعة الزيتون، و منطقة جازان بزراعة البن، إلى جانب المكانة الدينية والثقافية التي تتميز بها مكة المكرمة والمدينة المنورة، مؤكدًا أن هذه الخصوصيات تشكل مكونات متكاملة ضمن الهوية الوطنية السعودية الجامعة."]','التعليم','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/bw826m5ff','https://ajel.sa/local/bw826m5ff','https://ajel.sa/local/bw826m5ff','https://ajel.sa/local/bw826m5ff','فريق التحرير','مكة المكرمة','2026-09-06T18:32:00.000Z','Wed, 07 Oct 2026 19:45:04 GMT','2026-09-07T00:35:22.391Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop-by3spZN6.png','/api/media/43ffa23c-8089-4876-893c-9d46b13b708a','/api/media/43ffa23c-8089-4876-893c-9d46b13b708a?variant=thumbnail','مؤتمر «حوار الأمن والتاريخ» يناقش دور المؤسسات في تعزيز الهوية الوطنية لدى الشباب',1200,675,'valid','published','archived','valid',46,'d56b8e712132c3156a3237cec1f026c430e938954b51501516c1640aafab5893','bbd5858c7d09038509cf3eb3c9e2edc99b47957355f2a12eccd89541476be667','محدّث','2026-09-07T00:35:22.391Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","التعليم والتدريب","الاقتصاد والأسواق","مكة","جازان","الجوف","المدينة المنورة"]','["التعليم والتدريب","الاقتصاد والأسواق","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"البيئة والمناخ","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:45:05.945Z',200,4,0,'source_content_changed','',NULL,NULL,'body:a9f62f638db150f3e680f409c902d578e7fb62e7a383a919a55d586820a4b52c','Wed, 07 Oct 2026 19:45:04 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8a28fe37-6eee-4250-8595-5038b9580ade','news-8a28fe37-6eee-4250-8595-5038b9580ade','جائزة الأميرة صيتة بنت عبدالعزيز تكرّم 30 فائزًا بجوائزها الاجتماعية لعام 2026','جائزه الاميره صيته بنت عبدالعزيز تكرم 30 فائزا بجوائزها الاجتماعيه لعام 2026','كرّمت جائزة الأميرة صيتة بنت عبدالعزيز للتميز في العمل الاجتماعي 30 فائزًا بجوائزها الاجتماعية لعام 2026م، وذلك خلال الحفل الذي أقيم مساء اليوم الأحد ب الرياض ، بحضور عدد من أصحاب السمو والمعالي ونخبة من قادة المجتمع والمهتمين بالعمل الاجتماعي والإنساني.','["وبدأ الحفل بعرض مرئي عن الجوائز الاجتماعية الست (المواطنة المسؤولة، أم الجود، تنسيق، تحفيز، صيتاثون، امتنان) ودورها في تحفيز وتكريم الأفراد والمؤسسات المتميزة في العمل الاجتماعي وتعزيز ثقافة العمل الاجتماعي المستدام، وإسهامها في دعم النسيج الوطني عبر مبادرات نوعية ومبتكرة.","وألقى صاحب السمو الأمير سعود بن فهد بن عبدالله عضو مجلس أمناء الجائزة نائب رئيس اللجنة التنفيذية، كلمةً هنأ فيها الفائزين على ما قدموه للمجتمع من عطاء ومبادرات نوعية، مؤكدًا أن الجوائز الاجتماعية تمثل رسالة وفاء وتقدير لكل من جعل خدمة المجتمع نهجًا ثابتًا في مسيرته، ودليلًا على ما توليه المملكة من عناية خاصة لدعم المبادرات الرَّائدة التي تعزز جودة الحياة وتكرّس قيم التعاون والتكافل.","وأضاف سموه أن هذه الجوائز، جاءت ثمرة جهد مؤسسي منظّم، يحرص على وضوح الرؤية ودقة العمل، ويقيس أثر المبادرات لضمان استدامتها، بما يدعم مكانة وطننا في ريادة العمل الاجتماعي.","بعدها أشار الأمين العام للجائزة الدكتور فهد بن حمد المغلوث، في كلمة له إلى أن الأوطان العظيمة لا تقيس الإنجازات بعددها، بل بعمق أثرها، مؤكدًا، أن الجوائز الاجتماعية تحتفي بثقافةٍ وطنيةٍ جعلت من العطاء قيمة، ومن المبادرة مسؤولية، ومن الأثر معيارًا للتميز.","وأعلن المغلوث فتح باب الترشح للجائزة الكبرى في دورتها الرابعة عشرة لعام 2026 تحت عنوان \"تنمية الإنسان وتعزيز التماسك المجتمعي والولاء الوطني\"، وفتح باب الترشح لجائزتي المواطنة المسؤولة في دورتها السادسة وصيتاثون في دورتها الرابعة.","واختتمت فقرات الحفل بتكريم الفائزين بالجوائز الاجتماعية، حيث فاز في جائزة \"امتنان\" إحسان صالح طيب في فرع \"وقار\"، و صالح بن عبدالله السيد في فرع \"رِفعة\".","وفي جائزة \"تحفيز\" في دورتها الرابعة، فازت هيئة تطوير منطقة عسير عن مبادرة: \"أجاويد\"، أما في جائزة \"تنسيق\" في دورتها الخامسة، فازت مدارس علم وبناء الأهلية عن المجال التعليمي، وجمعية الأشخاص الاستثنائيين لخدمة ذوي الإعاقة عن المجال الخيري."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/ywx5br1zx','https://ajel.sa/misc/ywx5br1zx','https://ajel.sa/misc/ywx5br1zx','https://ajel.sa/misc/ywx5br1zx','فريق التحرير','الرياض','2026-09-06T18:12:00.000Z','Wed, 07 Oct 2026 19:45:05 GMT','2026-09-07T00:35:23.438Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop-su0Ll3OH.png','/api/media/8a28fe37-6eee-4250-8595-5038b9580ade','/api/media/8a28fe37-6eee-4250-8595-5038b9580ade?variant=thumbnail','جائزة الأميرة صيتة بنت عبدالعزيز تكرّم 30 فائزًا بجوائزها الاجتماعية لعام 2026',1200,675,'valid','published','archived','valid',40,'6f13cf6f7abb58eb826304836a4068bf59cc5ef8dc93b906a5ec3855d71189f1','8dfa17b5e8b939f649c49034a084108e26d88c6c9f495021da84edfeed87b4e0','محدّث','2026-09-07T00:35:23.438Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة تطوير منطقة عسير عن","مجلس أمناء الجائزة نائب رئيس","رئيس اللجنة التنفيذية كلمة هنأ","الصحة العامة","الثقافة والفنون","التعليم والتدريب","مكة","عسير"]','["هيئة تطوير منطقة عسير عن","مجلس أمناء الجائزة نائب رئيس","رئيس اللجنة التنفيذية كلمة هنأ","الصحة العامة","الثقافة والفنون","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:45:06.951Z',200,4,0,'source_content_changed','',NULL,NULL,'body:103cccd7c6320724f85bf6ededaf0836b3bcd7898d7f7dc79e59e8a93f04ed2f','Wed, 07 Oct 2026 19:45:05 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1ec5f1a4-cb91-4372-a464-1edc75c1b998','news-1ec5f1a4-cb91-4372-a464-1edc75c1b998','ضبط مقيمين من الجنسية الفلبينية لممارستهما الصيد دون تصريح','ضبط مقيمين من الجنسيه الفلبينيه لممارستهما الصيد دون تصريح','ضبطت الدوريات الساحلية لحرس الحدود في محافظة جدة بمنطقة مكة المكرمة مقيمين من الجنسية الفلبينية مخالفين للائحة الأمن والسلامة لمزاولي الأنشطة البحرية في المناطق البحرية للمملكة العربية السعودية ؛ وذلك لممارستهما الصيد دون تصريح، واستخدامهما أدوات محظورة، وتم اتخاذ الإجراءات النظامية بحقهما بالتنسيق مع الجهات المختصة.','["وأهاب حرس الحدود بالجميع الالتزام بالأنظمة والتعليمات المتعلقة بحماية الثروات المائية الحية والإبلاغ عن أي حالات تمثل اعتداءً على البيئة أو الحياة الفطرية، وذلك بالاتصال على الرقم (911) بمناطق مكة المكرمة، والمدينة المنورة، و الرياض ، و الشرقية ، و(994) في بقية مناطق المملكة، وستعامل جميع البلاغات بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/337jfqf50','https://ajel.sa/local/337jfqf50','https://ajel.sa/local/337jfqf50','https://ajel.sa/local/337jfqf50','فريق التحرير','الرياض','2026-09-06T19:19:00.000Z','Wed, 07 Oct 2026 20:58:56 GMT','2026-09-07T01:34:21.659Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-5cKXF98P.png','/api/media/1ec5f1a4-cb91-4372-a464-1edc75c1b998','/api/media/1ec5f1a4-cb91-4372-a464-1edc75c1b998?variant=thumbnail','ضبط مقيمين من الجنسية الفلبينية لممارستهما الصيد دون تصريح',1200,675,'valid','published','archived','valid',46,'3d5ed3cbee7c1f287a293fde2f3374b33028fe9fc85a8d0ceac1820a0d87af85','c563a34d0c7fc7cddfdff702dfabc679d3c48246361b931667a39a6a56420c45','محدّث','2026-09-07T01:34:21.659Z','2026-10-07T20:58:58.704Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الرياضة السعودية","مكة","جدة","الرياض","المدينة المنورة"]','["التعليم والتدريب","الرياضة السعودية","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"البيئة والمناخ","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T20:58:58.704Z',200,8,0,'source_content_changed','',NULL,NULL,'body:208e54e6ebc764f477883c734828bb758a4baac5a8294fd8e6c76c7382d0bb75','Wed, 07 Oct 2026 20:58:56 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6d14a81e-51cb-4321-a09a-9f09deddcb16','news-6d14a81e-51cb-4321-a09a-9f09deddcb16','مركز الملك سلمان للإغاثة يوزّع سلالًا غذائية في مديرية حيس بمحافظة الحديدة','مركز الملك سلمان للاغاثه يوزع سلالا غذائيه في مديريه حيس بمحافظه الحديده','وتندرج تلك المشاريع الإغاثية والإنسانية التي تنفذها المملكة عبر مركز الملك سلمان للإغاثة، لمساعدة الفئات المحتاجة والمتضررة في مختلف أنحاء العالم دون تمييز.','["وزّع مركز الملك سلمان للإغاثة والأعمال الإنسانية أمس سلالًا غذائية على النازحين والمتضررين من الأحداث الأخيرة في مديرية حيس ب محافظة الحديدة في الجمهورية اليمنية ، استفادت منها (50) أسرة، ضمن المرحلة الثانية من مشروع التدخلات الغذائية الطارئة في اليمن للعام 2026م."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/cfrsb367q','https://ajel.sa/local/cfrsb367q','https://ajel.sa/local/cfrsb367q','https://ajel.sa/local/cfrsb367q','فريق التحرير','','2026-09-06T19:41:00.000Z','Wed, 07 Oct 2026 21:19:45 GMT','2026-09-07T02:01:23.819Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop-jJHw2lFm.png','/api/media/6d14a81e-51cb-4321-a09a-9f09deddcb16','/api/media/6d14a81e-51cb-4321-a09a-9f09deddcb16?variant=thumbnail','مركز الملك سلمان للإغاثة يوزّع سلالًا غذائية في مديرية حيس بمحافظة الحديدة',1200,675,'valid','published','archived','valid',89,'deac56b9d8a9f29db076c63a17e7e57046899933ec5cf355c236c9da8dee0c87','7ffd54ab52b5028881d325e6d1bc8fa93f36d4710fbda86913bd2560687cd6f3','محدّث','2026-09-07T02:01:23.819Z','2026-10-07T21:19:47.390Z','','',0,0,'saudi_national','مهم',73,NULL,0,0,0,'',NULL,NULL,NULL,'["اليمن"]','[]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T21:19:47.390Z',200,4,0,'source_content_changed','',NULL,NULL,'body:eca78b7fada47ec15ada33081997ec6d17d03d3a499e9995ad3d23fcee0d545b','Wed, 07 Oct 2026 21:19:45 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0b13044b-3bb9-419e-90a6-cfbda6c7879e','news-0b13044b-3bb9-419e-90a6-cfbda6c7879e','«الشؤون الإسلامية» تنفّذ دروسًا شرعية لضيوف خادم الحرمين للعمرة والزيارة بالمدينة المنورة','الشؤون الاسلاميه تنفذ دروسا شرعيه لضيوف خادم الحرمين للعمره والزياره بالمدينه المنوره','نفّذت اللجنة الشرعية بوزارة الشؤون الإسلامية والدعوة والإرشاد دروسًا ورسائل توعوية حول أحكام وضوابط أداء مناسك العمرة، للدفعة الثالثة من ضيوف برنامج خادم الحرمين الشريفين للعمرة والزيارة، وذلك في مقر إقامتهم بالمدينة المنورة، قبيل انطلاقهم إلى مكة المكرمة.','["وتأتي البرامج التوعوية لتعريف الضيوف بالأحكام الشرعية المتعلقة بالعمرة، وتمكينهم من أداء مناسكهم على الوجه الشرعي الصحيح، ضمن الخدمات التي تقدمها الوزارة للمستفيدين من البرنامج خلال وجودهم في المملكة.","وتواصل اللجنة الشرعية تنفيذ برامجها طوال فترة إقامة الضيوف في المدينة المنورة ومكة المكرمة، من خلال تقديم الدروس العلمية، والإجابة عن الأسئلة والاستفسارات الشرعية والفتاوى المتعلقة بالمناسك.","وتُقدَّم الدروس وفق مجموعات الضيوف وجنسياتهم، بمشاركة مترجمين بعدد من اللغات، بما يسهم في إيصال المضامين والرسائل الشرعية إليهم بوضوح ودقة، ومساعدتهم على معرفة الأحكام المرتبطة بأداء مناسك العمرة.","يُذكر أن الدفعة الثالثة من البرنامج تضم 250 معتمرًا ومعتمرة يمثلون 23 دولة من قارة أفريقيا، هي: المغرب ، و مصر ، و تونس ، و الجزائر ، و السنغال ، وغينيا كوناكري، و الكاميرون ، و نيجيريا ، وغانا، والنيجر، و إثيوبيا ، ورواندا، و موريتانيا ، و ساحل العاج ، وبوركينا فاسو، وتشاد، وتنزانيا، و جيبوتي ، وجنوب أفريقيا، وزامبيا، وناميبيا، وأنغولا، ومالي."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/9v8tbcxmo','https://ajel.sa/local/9v8tbcxmo','https://ajel.sa/local/9v8tbcxmo','https://ajel.sa/local/9v8tbcxmo','فريق التحرير','مكة المكرمة','2026-09-06T20:15:00.000Z','Wed, 07 Oct 2026 19:06:53 GMT','2026-09-07T02:20:27.305Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop-r3gt5Q_8.png','/api/media/0b13044b-3bb9-419e-90a6-cfbda6c7879e','/api/media/0b13044b-3bb9-419e-90a6-cfbda6c7879e?variant=thumbnail','«الشؤون الإسلامية» تنفّذ دروسًا شرعية لضيوف خادم الحرمين للعمرة والزيارة بالمدينة المنورة',1200,675,'valid','published','archived','valid',98,'cda70791465197ee3b78eacf43828f23254fc43a58e7d890d12abdd37e97222f','7366ac8173688d738b8f38d2d7b95b48706bb6606db08eeee85cb717d93b1567','محدّث','2026-09-07T02:20:27.305Z','2026-10-07T19:06:55.365Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["خادم الحرمين للعمرة والزيارة بالمدينة","مكة","المدينة المنورة"]','["خادم الحرمين للعمرة والزيارة بالمدينة","المدينة المنورة"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T19:06:55.365Z',200,3,0,'source_content_changed','',NULL,NULL,'body:ff4202089c1c7d2fca7b1fe7ff60e9139e69b53f35cd1109bfb24ad711371b65','Wed, 07 Oct 2026 19:06:53 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f30a19b0-ffbf-4643-8dc4-56e59fe9419c','news-f30a19b0-ffbf-4643-8dc4-56e59fe9419c','حرس الحدود ينفذ مبادرة تطوعية لتنظيف شاطئ العقير بالمنطقة الشرقية','حرس الحدود ينفذ مبادره تطوعيه لتنظيف شاطئ العقير بالمنطقه الشرقيه','نفَّذت أكاديمية وزارة الداخلية لأمن الحدود، مبادرة بيئية تطوعية لتنظيف شاطئ العقير ب المنطقة الشرقية ، بمشاركة عددٍ من المتطوعين، وذلك ضمن جهودها في تعزيز الوعي البيئي والمسؤولية المجتمعية.','["وشملت المبادرة إزالة المخلفات من الشاطئ والمناطق المجاورة له؛ بهدف ترسيخ مفاهيم المحافظة على البيئة البحرية والساحلية، وتعزيز ثقافة التطوع والعمل الجماعي.","وتأتي هذه المبادرة ضمن سلسلة من الأنشطة التوعوية والتطوعية التي ينفذها حرس الحدود في مختلف مناطق المملكة ، للمساهمة في حماية البيئة البحرية والساحلية، ونشر الوعي بأهمية الحفاظ على الموارد الطبيعية."]','البيئة والمناخ','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/karznxk9j','https://ajel.sa/local/karznxk9j','https://ajel.sa/local/karznxk9j','https://ajel.sa/local/karznxk9j','فريق التحرير','المنطقة الشرقية','2026-09-06T20:46:00.000Z','Wed, 07 Oct 2026 19:45:07 GMT','2026-09-07T02:59:22.076Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/Capture-crop-PfnneylZ.png','/api/media/f30a19b0-ffbf-4643-8dc4-56e59fe9419c','/api/media/f30a19b0-ffbf-4643-8dc4-56e59fe9419c?variant=thumbnail','حرس الحدود ينفذ مبادرة تطوعية لتنظيف شاطئ العقير بالمنطقة الشرقية',1200,675,'valid','published','archived','valid',56,'6f756a40e8ce9f1c56e36acdad69f56432af89b71b5d162de3204821340ab12c','63ceb9d30734465f73ad93c67dfb9b79d688ed3ec56113f90f2953f467c61525','محدّث','2026-09-07T02:59:22.076Z','2026-10-07T19:45:08.807Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الداخلية لأمن الحدود مبادرة","الثقافة والفنون"]','["وزارة الداخلية لأمن الحدود مبادرة","الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:45:08.807Z',200,3,0,'source_content_changed','',NULL,NULL,'body:b61cd4317d6c52e380f513445563a2a71dd53bb046b6ab71aa38918ff6582e3d','Wed, 07 Oct 2026 19:45:07 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e4fd80df-9323-4dee-abc8-9b91f96daeb7','news-e4fd80df-9323-4dee-abc8-9b91f96daeb7','ضبط مواطن لإشعاله النار في أماكن محظورة بمحمية الملك عبدالعزيز الملكية','ضبط مواطن لاشعاله النار في اماكن محظوره بمحميه الملك عبدالعزيز الملكيه','ضبطت القوات الخاصة للأمن البيئي مواطنًا مخالفًا لنظام البيئة، لعدم الالتزام بتعليمات وإرشادات المحافظة على الغطاء النباتي بإشعال النار في غير الأماكن المخصصة لها في محمية الملك عبدالعزيز الملكية، وطبقت الإجراءات النظامية بحقه.','["وأكدت القوات أن عقوبة إشعال النار في غير الأماكن المخصصة لها في الغابات والمتنزهات الوطنية غرامة تصل إلى (3,000) ريال، حاثة على الإبلاغ عن أي حالات تمثل اعتداءً على البيئة أو الحياة الفطرية على الرقم (911) بمناطق مكة المكرمة والمدينة المنورة و الرياض و الشرقية ، و(999) و(996) في بقية مناطق المملكة ، وستعامل جميع البلاغات بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/zzj8ehn69','https://ajel.sa/local/zzj8ehn69','https://ajel.sa/local/zzj8ehn69','https://ajel.sa/local/zzj8ehn69','فريق التحرير','الرياض','2026-09-06T20:43:00.000Z','Wed, 07 Oct 2026 19:45:07 GMT','2026-09-07T02:59:24.161Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%A5%D8%B4%D8%B9%D8%A7%D9%84-%D8%A7%D9%84%D9%86%D8%A7%D8%B1-fQ6HdeIy.png','/api/media/e4fd80df-9323-4dee-abc8-9b91f96daeb7','/api/media/e4fd80df-9323-4dee-abc8-9b91f96daeb7?variant=thumbnail','ضبط مواطن لإشعاله النار في أماكن محظورة بمحمية الملك عبدالعزيز الملكية',1200,675,'valid','published','archived','valid',40,'e220572d5f213936e37cbcba42363ac8f3414c6442c5dcd64276434e53299131','a794729ff5b3bad99b5a1efad5d841560bf044c2fce98338e9b3d1db1ddd108e','محدّث','2026-09-07T02:59:24.161Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","مكة","الرياض","المدينة المنورة"]','["التعليم والتدريب","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"البيئة والمناخ","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T19:45:08.742Z',200,3,0,'source_content_changed','',NULL,NULL,'body:b0147502c1b4d5b05e9163b33f5bbd5e8602df4a4b41280632c80062bd6565a1','Wed, 07 Oct 2026 19:45:07 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('40605cf3-3f7d-44a8-969e-9e0340bc8df2','news-40605cf3-3f7d-44a8-969e-9e0340bc8df2','جامعة جازان تحقق نسبة 100% في مستهدفات مبادرة الرفاه والعافية النفسية','جامعه جازان تحقق نسبه 100 في مستهدفات مبادره الرفاه والعافيه النفسيه','حققت جامعة جازان نسبة 100% في مستهدفات مبادرة الرفاه والعافية النفسية في مؤسسات التعليم الجامعي والتقني للعام 1447هـ، التي ينفذها المركز الوطني لتعزيز الصحة النفسية ، لتنضم إلى 13 جامعة حققت مستهدفات المبادرة كاملة على مستوى المملكة .','["ويعكس الإنجاز تكامل جهود الجامعة في توفير بيئة تعليمية داعمة للصحة والرفاه النفسي لطلبتها ومنسوبيها، من خلال تنفيذ البرامج والمبادرات التوعوية والوقائية، وتقديم خدمات الدعم والإرشاد النفسي، وتعزيز الوعي بالممارسات الإيجابية التي تسهم في تحسين جودة الحياة الجامعية.","وأسهمت جهود الجامعة في تحقيق مؤشرات المبادرة المرتبطة بجودة الخدمات النفسية، ورفع مستوى الوعي بالصحة النفسية، وتيسير الوصول إلى برامج الدعم والإرشاد، إلى جانب تفعيل الأنشطة التي تعزز التوازن النفسي والاجتماعي، بما يدعم استدامة الأثر الإيجابي للمبادرة داخل المجتمع الجامعي.","ويأتي تحقيق الجامعة للمستهدفات ضمن اهتمامها ببناء بيئة جامعية متوازنة وآمنة، تسهم في دعم الاستقرار النفسي والاجتماعي للطلبة، وتهيئتهم للتحصيل العلمي والمشاركة الفاعلة في الأنشطة الجامعية، بما ينسجم مع المستهدفات الوطنية الرامية إلى تعزيز جودة الحياة والارتقاء بالصحة النفسية لأفراد المجتمع."]','التعليم','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/elydpcg4c','https://ajel.sa/misc/elydpcg4c','https://ajel.sa/misc/elydpcg4c','https://ajel.sa/misc/elydpcg4c','فريق التحرير','جازان','2026-09-06T20:59:00.000Z','Wed, 07 Oct 2026 20:02:52 GMT','2026-09-07T03:17:23.485Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/bcQuYzRqPgeg06uX.PNG','/api/media/40605cf3-3f7d-44a8-969e-9e0340bc8df2','/api/media/40605cf3-3f7d-44a8-969e-9e0340bc8df2?variant=thumbnail','جامعة جازان تحقق نسبة 100% في مستهدفات مبادرة الرفاه والعافية النفسية',1200,675,'valid','published','archived','valid',40,'f1fb59ad98b532de36feba8e80e061d01695d10a20ff47192c79fc766029f5df','f2a095768c740efa6d6536bb990d335d3c28e3479cf966943851122ce00de9b7','محدّث','2026-09-07T03:17:23.485Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة جازان تحقق نسبة","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق","جازان"]','["جامعة جازان تحقق نسبة","الصحة العامة","التعليم والتدريب","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"البيئة والمناخ","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T20:02:54.174Z',200,3,0,'source_content_changed','',NULL,NULL,'body:6b52d13138fde52aeb8b222080d62aa9bcbfbc2591574887ec79088819e9c869','Wed, 07 Oct 2026 20:02:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7e4b3b3c-9c9b-425a-9259-13aa40227de8','news-7e4b3b3c-9c9b-425a-9259-13aa40227de8','أمانة جدة ترفع مستوى السلامة المرورية في محيط 52 مدرسة','امانه جده ترفع مستوي السلامه المروريه في محيط 52 مدرسه','نفذت أمانة محافظة جدة خلال الشهر الماضي عددًا من أعمال السلامة المرورية في الطرق المحيطة بـ52 مدرسة، بالتنسيق مع مرور المحافظة وإدارة تعليم جدة. وتأتي هذه الجهود ضمن أعمال أمانة محافظة جدة المستمرة لتحسين كفاءة الطرق، وتعزيز معايير السلامة المرورية في المواقع ذات الكثافة والحركة المرتفعة، بالتكامل مع الجهات ذات العلاقة، بما يسهم في توفير بيئة مرورية أكثر…','["نفذت أمانة محافظة جدة خلال الشهر الماضي عددًا من أعمال السلامة المرورية في الطرق المحيطة بـ52 مدرسة، بالتنسيق مع مرور المحافظة وإدارة تعليم جدة.","وشملت الأعمال المنُفذة، إنشاء 161 مطب تهدئة، وتركيب 372 لوحة تحذيرية وإرشادية، إلى جانب تنفيذ أعمال دهانات مرورية بمساحة بلغت 1,652 مترًا مربعًا، بهدف تعزيز وضوح عناصر الطريق وتنظيم حركة المركبات في محيط المنشآت التعليمية.","وتأتي هذه الجهود ضمن أعمال أمانة محافظة جدة المستمرة لتحسين كفاءة الطرق، وتعزيز معايير السلامة المرورية في المواقع ذات الكثافة والحركة المرتفعة، بالتكامل مع الجهات ذات العلاقة، بما يسهم في توفير بيئة مرورية أكثر أمانًا للطلاب ومستخدمي الطريق، ويدعم مستهدفات تحسين المشهد الحضري وجودة الحياة في المحافظة."]','السيارات','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/1m8l5utyq','https://ajel.sa/local/1m8l5utyq','https://ajel.sa/local/1m8l5utyq','https://ajel.sa/local/1m8l5utyq','فريق التحرير','مكة المكرمة','2026-09-06T20:57:00.000Z','Wed, 07 Oct 2026 20:02:52 GMT','2026-09-07T03:17:24.130Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A3%D9%85%D8%A7%D9%86%D8%A9-%D8%AC%D8%AF%D8%A9-TamtCrow.jpg','/api/media/7e4b3b3c-9c9b-425a-9259-13aa40227de8','/api/media/7e4b3b3c-9c9b-425a-9259-13aa40227de8?variant=thumbnail','أمانة جدة ترفع مستوى السلامة المرورية في محيط 52 مدرسة',1200,675,'valid','published','archived','valid',40,'c7b39d1441b904cff5eaa203c426e9c1681129d754fbbebeef43bfd7ea08a75e','950875a262352aba91d5e11d1585ae2bb599b886d20ce8b4081ea7b16ad8af0e','محدّث','2026-09-07T03:17:24.130Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","جدة"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T20:02:54.026Z',200,3,0,'source_content_changed','',NULL,NULL,'body:9c4913a9a965c86f3a4c5c64528a3c13e74dfed8b9f61da82c7c8362f9c15ffb','Wed, 07 Oct 2026 20:02:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d2cbdbca-fdc2-4e2a-9347-328d0abd5d3c','news-d2cbdbca-fdc2-4e2a-9347-328d0abd5d3c','وزارة الحج والعمرة تعزز استخدامات الذكاء الاصطناعي للارتقاء بخدمات ضيوف الرحمن','وزاره الحج والعمره تعزز استخدامات الذكاء الاصطناعي للارتقاء بخدمات ضيوف الرحمن','وتعمل الوزارة على تعظيم القيمة الإستراتيجية للبيانات من خلال التحليلات المتقدمة وتقنيات الذكاء الاصطناعي واكتشاف الأنماط، وإجراء الدراسات المرتبطة باتجاهات الحج والعمرة، وسلوكيات ضيوف الرحمن وتفضيلاتهم، والعرض والطلب، إلى جانب توظيف التحليلات التنبؤية في توقع مواعيد الوصول والمغادرة وفترات الإقامة واتجاهاتها؛ بما يدعم التخطيط والاستعداد المبكر وصنع القرار.','["توظف وزارة الحج والعمرة تقنيات الذكاء الاصطناعي وتحليل البيانات في تطوير الخدمات المقدمة لضيوف الرحمن، وتحويل البيانات إلى رؤى وتنبؤات تدعم التخطيط وصنع القرار، إلى جانب تقديم الحلول الذكية وإدارة الحركة والتفويج؛ بما يسهم في تيسير رحلة الحاج والمعتمر والارتقاء بتجربته، في ظل ما توليه القيادة الرشيدة -أيدها الله- من عناية بخدمة ضيوف الرحمن، وتحقيقًا لمستهدفات رؤية السعودية 2030 و برنامج خدمة ضيوف الرحمن .","وفي الجانب التشغيلي، توظف الوزارة الخوارزميات المتقدمة في إدارة حركة الحجاج والتفويج، وتحليل حركة الحشود والتنبؤ بأوقات الذروة، إلى جانب تحليل حركة الحافلات وتحسين مسارات النقل بين المشاعر المقدسة؛ بما يسهم في رفع كفاءة الحركة والتنقل، ودعم القرارات التشغيلية خلال الموسم.","وعلى مستوى الخدمات المقدمة مباشرةً لضيف الرحمن، تمثل خدمة \"نسك AI\" أحد الحلول القائمة على الذكاء الاصطناعي؛ إذ توفر المعلومات والإرشادات المتعلقة بالحج والعمرة والزيارة، وتجيب عن الاستفسارات والأسئلة، مع دعم أكثر من (180) لغة، وإتاحة التفاعل الصوتي، وقد استفاد منها منذ إطلاقها أكثر من مليوني مستخدم، منهم (393) ألفًا خلال الشهر الماضي فقط.","وتقدم الوزارة خدمة \"المطوف الرقمي\" عبر تطبيق \"نسك\"، بوصفها رفيقًا ذكيًا يرافق ضيف الرحمن أثناء أداء النسك؛ إذ توظف الذكاء الاصطناعي المكاني لفهم موقعه وحركته وسياق رحلته لحظيًا، وتوجيهه إلى المسارات والطوابق الأنسب، واحتساب أشواط الطواف والسعي آليًا، إلى جانب عرض الإرشادات والأدعية المناسبة لكل مرحلة، حيث سجلت الخدمة أكثر من مليوني استخدام خلال شهر واحد، فيما أكمل عبرها أكثر من (1.4) مليون مستفيد رحلة الطواف والسعي رقميًا.","وحصلت وزارة الحج والعمرة مؤخرًا على \"وسم أخلاقيات الذكاء الاصطناعي\" الصادر عن الهيئة السعودية للبيانات والذكاء الاصطناعي \"سدايا\" عن خدمة \"نسك AI\"، تأكيدًا لالتزامها بمبادئ الاستخدام المسؤول والموثوق للتقنيات الذكية، ومواصلة توظيف الذكاء الاصطناعي في تطوير الخدمات ودعم القرار؛ بما يسهم في بناء تجربة أكثر ذكاءً واستباقية لضيوف الرحمن."]','الذكاء الاصطناعي','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/5o0m6s7i4','https://ajel.sa/local/5o0m6s7i4','https://ajel.sa/local/5o0m6s7i4','https://ajel.sa/local/5o0m6s7i4','فريق التحرير','','2026-09-06T20:56:00.000Z','Wed, 07 Oct 2026 20:02:52 GMT','2026-09-07T03:17:24.225Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D9%88%D8%B2%D8%A7%D8%B1%D8%A9-%D8%A7%D9%84%D8%AD%D8%AC-%D9%88%D8%A7%D9%84%D8%B9%D9%85%D8%B1%D8%A9-Q-T2F-4p.png','/api/media/d2cbdbca-fdc2-4e2a-9347-328d0abd5d3c','/api/media/d2cbdbca-fdc2-4e2a-9347-328d0abd5d3c?variant=thumbnail','وزارة الحج والعمرة تعزز استخدامات الذكاء الاصطناعي للارتقاء بخدمات ضيوف الرحمن',1200,675,'valid','published','archived','valid',45,'82b9fadced0d73d8499bd1e3df5ad7e0e4a1dcedf546430d1c88912ba4da0e23','4e072f8c5c85358c522e82f79f9a345fec1d40442bf9bd740ded3ea465fb5c50','محدّث','2026-09-07T03:17:24.225Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_national','مهم',70,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الحج والعمرة تعزز استخدامات","التقنية والتحول الرقمي"]','["وزارة الحج والعمرة تعزز استخدامات","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"الذكاء الاصطناعي","score":2},{"category":"أخبار السعودية","score":1.5},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:02:54.144Z',200,3,0,'source_content_changed','',NULL,NULL,'body:4552e3f14cf4c31b72affddb56162288f870901f607b3563391386935d76dee1','Wed, 07 Oct 2026 20:02:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('01004290-97f0-44b6-96ee-cfa5a3db1279','news-01004290-97f0-44b6-96ee-cfa5a3db1279','اليوم.. بدء منافسات الجولة الرابعة من دوري الدرجة الأولى للمحترفين','اليوم بدء منافسات الجوله الرابعه من دوري الدرجه الاولي للمحترفين','ويدخل العدالة مواجهته أمام الصقر بعد تحقيقه انتصاره الأول في الجولة الماضية على حساب البكيرية ، ليرفع رصيده إلى 4 نقاط في المركز السابع، بينما يبحث الصقر عن انتصاره الأول في دوري الدرجة الأولى بعدما سجل ثلاثة تعادلات متتالية وضعته في المركز الـ12 برصيد 3 نقاط.','["تنطلق اليوم الاثنين منافسات الجولة الرابعة من دوري الدرجة الأولى للمحترفين، وسط مواجهات مرتقبة تمتد على مدى ثلاثة أيام، يتصدرها لقاء العُلا متصدر الترتيب أمام مضيفه ضمك ، في سعيه لمواصلة انطلاقته المثالية وتحقيق انتصاره الرابع تواليًا.","وتُفتتح الجولة بإقامة ثلاث مواجهات غدًا، يلتقي في الأولى العدالة مع الصقر، فيما يستضيف الجبلين نظيره الوحدة ، ويستقبل الأخدود فريق النجمة.","وفي حائل ، يسعى الجبلين للعودة إلى طريق الانتصارات بعد تعادله مع النجمة في الجولة الماضية، إذ يحتل المركز الثامن بـ4 نقاط، فيما يدخل الوحدة المواجهة برصيد 3 نقاط بعد تعادله في مبارياته الثلاث الماضية.","وفي المواجهة الثالثة، يتطلع الأخدود، رابع الترتيب بـ5 نقاط، إلى استعادة نغمة الفوز والبقاء قريبًا من فرق المقدمة عندما يواجه النجمة، الذي يملك 4 نقاط، وذلك بعد تعادل الفريقين في الجولة الماضية.","وتتواصل منافسات الجولة الثلاثاء بثلاث مواجهات، أبرزها حلول العُلا ضيفًا على ضمك، إلى جانب لقاء الزلفي وهجر، ومواجهة الأنوار والطائي.","ويخوض العُلا المواجهة متربعًا على الصدارة بالعلامة الكاملة برصيد 9 نقاط، باحثًا عن انتصاره الرابع تواليًا، في اختبار أمام ضمك الذي لم يتعرض للخسارة حتى الآن، بعدما تعادل في مبارياته الثلاث وجمع 3 نقاط.","وفي مواجهة أخرى، يستضيف الزلفي، صاحب المركز الخامس بـ5 نقاط، نظيره هجر الذي يحتل المركز التاسع بـ4 نقاط، فيما يسعى الطائي لمواصلة انتصاراته عندما يحل ضيفًا على الأنوار، بعد أن رفع رصيده إلى 6 نقاط في المركز الثالث بفوزه على الجندل في الجولة الماضية، مقابل نقطتين للأنوار الذي لا يزال يبحث عن انتصاره الأول."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/iglj0ovq6','https://ajel.sa/sports/iglj0ovq6','https://ajel.sa/sports/iglj0ovq6','https://ajel.sa/sports/iglj0ovq6','فريق التحرير','مكة المكرمة','2026-09-06T21:22:00.000Z','Wed, 07 Oct 2026 20:27:50 GMT','2026-09-07T03:37:48.380Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%AF%D9%88%D8%B1%D9%8A-%D9%8A%D9%84%D9%88-%D8%AF%D9%88%D8%B1%D9%8A-%D8%A7%D9%84%D8%AF%D8%B1%D8%AC%D8%A9-%D8%A7%D9%84%D8%A3%D9%88%D9%84%D9%89-d2msK1QP.png','/api/media/01004290-97f0-44b6-96ee-cfa5a3db1279','/api/media/01004290-97f0-44b6-96ee-cfa5a3db1279?variant=thumbnail','اليوم.. بدء منافسات الجولة الرابعة من دوري الدرجة الأولى للمحترفين',1200,675,'valid','published','archived','valid',41,'61aceb4626ef1537b9643d7bbd74427a0c0de045559ef4cc46abf0a1cc0abb68','0b79267c51b6558df2c476cbf5213cc83a465b100adfe9abe416febab85753d3','محدّث','2026-09-07T03:37:48.380Z','2026-10-07T20:27:55.611Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","جدة"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Updated','2026-10-07T20:27:55.611Z',200,5,0,'source_content_changed','',NULL,NULL,'body:c747de36c960fdc31dc84257bc14d6388bfd0afec42c372562e116a8a41a0eb7','Wed, 07 Oct 2026 20:27:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('890f7d8a-5932-4287-bca6-dff542921bc5','news-890f7d8a-5932-4287-bca6-dff542921bc5','أكثر من 1600 مطية تعزز حضور إنتاج السعودية في مهرجان ولي العهد للهجن','اكثر من 1600 مطيه تعزز حضور انتاج السعوديه في مهرجان ولي العهد للهجن','سجلت الأشواط المخصصة لـ"إنتاج السعودية " في مهرجان ولي العهد للهجن 2026، مشاركة تجاوزت (1600) مطية لفئتي "الحقايق" و"اللقايا"، في مؤشر يعكس تنامي حضور الملاك والمنتجين السعوديين، واتساع قاعدة الإنتاج المحلي في رياضة الهجن.','["وبلغ عدد المشاركين في فئة \"الحقايق\" (989) مطية، فيما شهدت الأشواط الأولى لفئة \"اللقايا\" اليوم مشاركة (671) مطية، على أن تُستكمل منافساتها الثلاثاء المقبل بشوطي كأس مهرجان ولي العهد للإنتاج السعودي، بمشاركة متوقعة تقارب (100) مطية.","وتقام النسخة الثامنة من المهرجان على أرض ميدان الطائف التاريخي لسباقات الهجن بتنظيم الاتحاد السعودي للهجن ، وبجوائز مالية تتجاوز (50) مليون ريال.","وخصص الاتحاد السعودي للهجن جوائز مستقلة لأشواط \"إنتاج السعودية\"، ضمن برامجه الرامية إلى تمكين الملاك والمنتجين المحليين، وتحفيز الاستثمار في السلالات الوطنية، ورفع مستوياتها الفنية والتنافسية.","وأوضح المدير التنفيذي للاتحاد السعودي للهجن المهندس محمود البلوي، أن تجاوز المشاركة حاجز (1600) مطية يعكس نمو قطاع الإنتاج المحلي، مؤكدًا أن دعم الأشواط المخصصة له منح الملاك السعوديين مساحة أكبر للتنافس وتطوير إنتاجهم وبناء استثمارات مجدية في القطاع.","وأشار إلى أن المستويات والسرعات المسجلة في فئتي \"الحقايق\" و\"اللقايا\" تسهم في إبراز جودة السلالات الوطنية ورفع قيمتها السوقية، بما يدعم بناء بيئة رياضية واقتصادية مستدامة ويعزز حضور المنتجين السعوديين في رياضة الهجن.","ويأتي دعم \"إنتاج السعودية\" ضمن جهود الاتحاد السعودي للهجن لتطوير القطاع وتعزيز امتداده الاقتصادي، والمحافظة على الموروث المرتبط به، بما يتوافق مع مستهدفات رؤية السعودية 2030."]','أخبار السعودية','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/nodp9pojq','https://ajel.sa/sports/nodp9pojq','https://ajel.sa/sports/nodp9pojq','https://ajel.sa/sports/nodp9pojq','فريق التحرير','','2026-09-06T21:12:00.000Z','Wed, 07 Oct 2026 20:27:50 GMT','2026-09-07T03:38:00.142Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D9%85%D9%87%D8%B1%D8%AC%D8%A7%D9%86-%D9%88%D9%84%D9%8A-%D8%A7%D9%84%D8%B9%D9%87%D8%AF-%D9%84%D9%84%D9%87%D8%AC%D9%86-vuJqBNzM.png','/api/media/890f7d8a-5932-4287-bca6-dff542921bc5','/api/media/890f7d8a-5932-4287-bca6-dff542921bc5?variant=thumbnail','أكثر من 1600 مطية تعزز حضور إنتاج السعودية في مهرجان ولي العهد للهجن',1200,675,'valid','published','archived','valid',99,'f4ee362a62859a08f18c953133a1a5885cba9614cae00231ef32be9283a65e88','2bca4a1529dfd098f1e098b49157c14cba0e797fdbf9ff1669c9d956e438d1da','محدّث','2026-09-07T03:38:00.142Z','2026-10-07T20:27:55.534Z','','',0,0,'saudi_national','أولوية قصوى',82,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","ولي العهد للهجن صحيفة إلكترونية","الرياضة السعودية","الاقتصاد والأسواق"]','["ولي العهد للهجن صحيفة إلكترونية","الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[{"category":"البيئة والمناخ","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Updated','2026-10-07T20:27:55.534Z',200,4,0,'source_content_changed','',NULL,NULL,'body:7ba6135c56a942b3c05ca13b9cdaa26613a04e43b773b32dd029736d0e81a7e4','Wed, 07 Oct 2026 20:27:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4d92df7b-8e54-4a62-b137-feaac9ac495a','news-4d92df7b-8e54-4a62-b137-feaac9ac495a','البنزين يشتعل في إيران.. زيادة الأسعار لمن يتجاوز 110 لترات','البنزين يشتعل في ايران زياده الاسعار لمن يتجاوز 110 لترات','وأوضحت مهاجراني أن القرار لن يشمل المستهلكين الذين لا يتجاوز استهلاكهم 110 لترات شهريًا، إذ سيظل بإمكان سائقي السيارات شراء 60 لترًا بسعر 15 ألف ريال للتر، إضافة إلى 50 لترًا أخرى بسعر 30 ألف ريال للتر.','["تعتزم إيران رفع سعر البنزين للمستهلكين الذين يتجاوز استهلاكهم 110 لترات شهريًا، اعتبارًا من الثلاثاء، في خطوة تستهدف التعامل مع الضغوط الاقتصادية المتزايدة التي تواجهها البلاد نتيجة الحرب والعقوبات الأمريكية.","وقالت فاطمة مهاجراني، المتحدثة باسم الحكومة الإيرانية ، إن سعر أول حصتين، بإجمالي 110 لترات، لن يتغير، بينما سيرتفع سعر الحصة الثالثة إلى 100 ألف ريال إيراني للتر، أي نحو أربعة سنتات وفق سعر السوق الحرة، بحسب تصريحات نقلتها وسائل إعلام رسمية.","وتأتي الخطوة في وقت تسعى فيه الحكومة الإيرانية إلى معالجة ارتفاع الطلب على الوقود، في ظل الضغوط الاقتصادية التي تعاني منها البلاد.","وكانت الحكومة قد بحثت في وقت سابق زيادة أسعار البنزين، الذي يعد من بين الأرخص عالميًا، لكنها أرجأت القرار وسط مخاوف من اندلاع احتجاجات جديدة، بعدما شهدت إيران احتجاجات واسعة في 2019 بسبب رفع أسعار الوقود.","وفي ديسمبر، رفعت إيران جزئيًا سعر البنزين المدعوم لمعظم المستخدمين، في محاولة للحد من الطلب المتزايد على الوقود."]','السياسة','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/ov5ds4e12','https://ajel.sa/economy/ov5ds4e12','https://ajel.sa/economy/ov5ds4e12','https://ajel.sa/economy/ov5ds4e12','فريق التحرير','','2026-09-06T21:41:00.000Z','Wed, 07 Oct 2026 20:45:02 GMT','2026-09-07T03:50:23.488Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D9%85%D8%AD%D8%B7%D8%A9-%D9%88%D9%82%D9%88%D8%AF-%D9%81%D9%8A-%D8%A5%D9%8A%D8%B1%D8%A7%D9%86-rnd-xuw4.png','/api/media/4d92df7b-8e54-4a62-b137-feaac9ac495a','/api/media/4d92df7b-8e54-4a62-b137-feaac9ac495a?variant=thumbnail','البنزين يشتعل في إيران.. زيادة الأسعار لمن يتجاوز 110 لترات',1200,675,'valid','published','archived','valid',91,'a4701fb9b5c7a709dc9d8ecd87151fcf6e96c996b64942d3f066d44fdbe16681','45b75c4a62d55de80b2abce7ed8412c5c510eff1929101f36e3364e7625293ea','محدّث','2026-09-07T03:50:23.488Z','2026-10-07T20:45:04.006Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","الاقتصاد والأسواق","إيران"]','["الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T20:45:04.006Z',200,3,0,'source_article_available','',NULL,NULL,'body:b2b72b9212a735e0ff8d4b6abd4037ae79505d718966db35d7a3def535538b88','Wed, 07 Oct 2026 20:45:02 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4d53ca67-7cc0-42af-85db-c7535146a9e7','news-4d53ca67-7cc0-42af-85db-c7535146a9e7','اليوم.. انطلاق منافسات الجولة السادسة من «دوري روشن»','اليوم انطلاق منافسات الجوله السادسه من دوري روشن','تنطلق اليوم الاثنين منافسات الجولة السادسة من الدوري السعودي للمحترفين، وسط سباق متصاعد على مراكز المقدمة، يتصدره الهلال بالعلامة الكاملة، فيما تبرز مواجهة القادسية والأهلي ضمن أبرز لقاءات الجولة التي تقام على مدى ثلاثة أيام.','["ويخوض الهلال المتصدر بـ(15) نقطة مواجهة الجولة الأولى غدًا أمام ضيفه نيوم على ملعب المملكة أرينا ب الرياض ، بعد أن حقق خمسة انتصارات متتالية منذ انطلاق الموسم، فيما يدخل نيوم اللقاء في المركز السابع بـ(9) نقاط، ساعيًا لمواصلة نتائجه الإيجابية والاقتراب من مراكز المقدمة، في حين تفتتح منافسات الجولة غدًا أيضًا بلقاء الخليج والرياض على ملعب الأمير محمد بن فهد ب الدمام ، إذ يدخل الخليج المواجهة في المركز السادس عشر بـ(3) نقاط باحثًا عن انتصاره الأول، فيما يحتل الرياض المركز الثاني عشر بـ(4) نقاط.","وتتواصل منافسات الجولة الثلاثاء بأربع مواجهات، إذ يلتقي الاتفاق، صاحب المركز الثامن بـ(9) نقاط، مع الفيصلي على ملعب نادي الاتفاق بالدمام، فيما يستضيف الحزم نظيره التعاون على ملعب نادي الحزم ب الرس .","وتتجه الأنظار إلى ملعب الأمير محمد بن فهد بالدمام، الذي يحتضن مواجهة القادسية والأهلي، في لقاء يجمع فريقين يفصل بينهما ثلاث نقاط؛ إذ يدخل القادسية الجولة في المركز الثالث بـ(12) نقطة، مقابل (9) نقاط للأهلي صاحب المركز الخامس، ما يمنح المواجهة أهمية كبيرة في صراع المراكز المتقدمة.","وفي جدة ، يستضيف الاتحاد نظيره الفيحاء على ملعب الإنماء بمدينة الملك عبدالله الرياضية، إذ يدخل الاتحاد اللقاء رابعًا بـ(11) نقطة ودون خسارة خلال الجولات الخمس الماضية، فيما يمتلك الفيحاء (5) نقاط، في مواجهة يسعى خلالها أصحاب الأرض إلى مواصلة المنافسة على مراكز المقدمة.","وتختتم منافسات الجولة يوم الأربعاء بثلاث مواجهات، إذ يلتقي في أولاها الخلود والشباب على ملعب نادي الحزم بالرس، فيما يستضيف الفتح نظيره الدرعية على ميدان تمويل الأولى ب الأحساء ، ويستقبل النصر نظيره أبها على ملعب الأول بارك بالرياض.","ويدخل النصر الجولة في المركز الثاني بـ(12) نقطة، متساويًا مع القادسية ومتأخرًا عن الهلال المتصدر بثلاث نقاط، في حين يحتل أبها المركز الثامن عشر بنقطة واحدة، ليبحث النصر عن العودة إلى طريق الانتصارات ومواصلة ملاحقة المتصدر."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/520t5clvc','https://ajel.sa/sports/520t5clvc','https://ajel.sa/sports/520t5clvc','https://ajel.sa/sports/520t5clvc','فريق التحرير','الرياض','2026-09-06T21:55:00.000Z','Wed, 07 Oct 2026 21:07:47 GMT','2026-09-07T04:08:24.140Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%AF%D9%88%D8%B1%D9%8A-%D8%B1%D9%88%D8%B4%D9%86-GyfuhwMQ.png','/api/media/4d53ca67-7cc0-42af-85db-c7535146a9e7','/api/media/4d53ca67-7cc0-42af-85db-c7535146a9e7?variant=thumbnail','اليوم.. انطلاق منافسات الجولة السادسة من «دوري روشن»',1200,675,'valid','published','archived','valid',40,'f6550676db43e8b72a4b9b996fd43720942d1701bc88045c45a5e32ede3b45cb','bf83203e6b35ec1ff154ab67b413cc7aa7dbeea7e9df0da3272f0e676b0fd615','محدّث','2026-09-07T04:08:24.140Z','2026-10-07T21:07:51.699Z','','',0,0,'saudi_region','مهم',62,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","جدة","الرياض","الدمام"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T21:07:51.699Z',200,5,0,'source_article_available','',NULL,NULL,'body:47848bbc01f581e911d00547912b9533798046306de55613a030fc2fa7fe952d','Wed, 07 Oct 2026 21:07:47 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('77427fd3-55ba-455b-beb2-3ac13419ecc4','news-77427fd3-55ba-455b-beb2-3ac13419ecc4','بسرعة 206 كم/ساعة تجاوزت المدرج.. طائرة شحن تابعة لـ«أمازون» تدهس مركبات وتشتعل في مطار ميامي ومقتل 5 أشخاص','بسرعه 206 كم ساعه تجاوزت المدرج طائره شحن تابعه لـ امازون تدهس مركبات وتشتعل في مطار ميامي ومقتل 5 اشخاص','قُتل خمسة أشخاص وأصيب خمسة آخرون، ثلاثة منهم في حالة حرجة، حين تجاوزت طائرة شحن من طراز بوينغ 767-300 تابعة لخدمة «برايم إير» شركة أمازون نهاية المدرج 30 في مطار ميامي الدولي بعد هبوطها ظهر الأحد 6 سبتمبر 2026، فاخترقت طريقًا مجاورًا ودهست عدة مركبات قبل أن تستقر في أرض فضاء بجوار المطار وتشتعل فيها النيران.','["وبحسب إدارة الطيران الفيدرالية (FAA)، كانت الرحلة رقم 7598، التي تشغّلها شركة «21 إير» ومقرها نورث كارولاينا، قادمة من مطار لويس مونيوز مارين في سان خوان ببورتوريكو، وتجاوزت المدرج عند الساعة 1:58 ظهرًا بالتوقيت المحلي، وتشير المعطيات الأولية إلى أن سرعتها لحظة الخروج من المدرج بلغت نحو 128 ميلًا في الساعة (206 كيلومترات).","وقالت شريفة مقاطعة ميامي-ديد روزي كورديرو-ستوتز إن الطائرة ضربت مركبات عدة قرب المبنى 2100 من الجادة 42 الشمالية الغربية، وهو طريق يستخدمه عمال المستودعات والشركات المحيطة بالمطار، واستقرت بجوار شاحنتين كبيرتين. «وضع بالغ التعقيد» واستجاب أكثر من 60 وحدة و200 عنصر من إطفاء وإنقاذ ميامي-ديد؛ إذ قال رئيس الجهاز راي جاد الله: «ما وجدناه كان وضعًا بالغ التعقيد»، موضحًا أن فرقه أخرجت أشخاصًا من قمرة القيادة ومن المركبات، بينهم شخص محشور تحت مركبة، وعالجت حريقًا معقدًا في حجرات المحركات وتسربًا للوقود.","ونُقل الطياران إلى مركز جاكسون الجنوبي الطبي وثلاثة آخرون إلى مستشفى جاكسون التذكاري، فيما لم تعلن السلطات هويات القتلى أو المصابين، ولم تحدد رسميًا ما إذا كان القتلى جميعًا من ركاب المركبات على الطريق أو بينهم من طاقم الطائرة.","وطائرة عمرها 32 عامًا وسُجلت عواصف رعدية وهبات رياح بلغت 30 ميلًا في الساعة في المنطقة وقت الحادث، دون تأكيد ما إذا كان الطقس عاملًا فيه، فيما رجّح خبراء طيران أن الطائرة «طفت» مسافة طويلة فوق المدرج قبل أن تلامسه.","والطائرة يبلغ عمرها 32 عامًا؛ صُنعت طائرة ركاب عام 1994 وخدمت لدى شركات عدة لأكثر من عقدين قبل تحويلها إلى الشحن عام 2015.","وأعلن المجلس الوطني لسلامة النقل (NTSB) إرسال فريق تحقيق تقوده رئيسته جينيفر هومندي، فيما قالت أمازون: «قلوبنا مكسورة لعلمنا بأن خمسة أشخاص فقدوا حياتهم في حادث اليوم بمطار ميامي الدولي»، وقدّم كيث وينترز الرئيس التنفيذي لشركة «21 إير» «أحرّ التعازي لأسر وأحبّاء من فقدوا حياتهم».","شلل في المطار وأصدرت إدارة الطيران أمر وقف أرضي شامل وأغلقت مدارج المطار الأربعة، قبل إعادة فتح مدرجين اعتبارًا من 4:15 عصرًا، ورُفع الوقف بعد نحو ثلاث ساعات، فيما تأخرت نحو 250 رحلة وبلغ متوسط التأخير في الرحلات القادمة 6.5 ساعات مساء الأحد، وتعطلت خدمة الخط البرتقالي لمترو ميامي المار بالمطار، مع توقع استمرار التأخيرات حتى صباح الإثنين."]','السفر','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/k9sq510','https://sabq.org/article/k9sq510','','https://sabq.org/article/k9sq510','صحيفة سبق','','2026-09-06T22:02:00.000Z','2026-09-07T01:02:00.000Z','2026-09-07T04:08:25.404Z','https://media.sabq.org/news/2026/09/a5e953e7-bb2c-4dc4-acee-2981ef7a9489/w1500.webp','/api/media/77427fd3-55ba-455b-beb2-3ac13419ecc4','/api/media/77427fd3-55ba-455b-beb2-3ac13419ecc4?variant=thumbnail','بسرعة 206 كم/ساعة تجاوزت المدرج.. طائرة شحن تابعة لـ«أمازون» تدهس مركبات وتشتعل في مطار ميامي ومقتل 5 أشخاص',1500,1000,'valid','published','archived','valid',46,'1f07d24130e618b00b82e0b3ee6c93f016cac2347d94109f26931cc74238b03e','d5a51a949fe9f53b3a9b6a7bd0378a52a459566ce29b0d5f527a6304884173ab','محدّث','2026-09-07T04:08:25.404Z','2026-10-07T21:07:49.212Z','','',0,0,'international','عادي',45,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة أمازون نهاية المدرج","رئيس الجهاز راي جاد الله","الصحة العامة","الطقس والمناخ","السفر والسياحة"]','["شركة أمازون نهاية المدرج","رئيس الجهاز راي جاد الله","الصحة العامة","الطقس والمناخ","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"الرياضة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T21:07:49.212Z',200,5,0,'source_article_available','',NULL,NULL,'body:eab1064e9d4dcf1d7e4229ef01a00fed4fc9d6a07dd086099cef635d0eb45509','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e61c55a5-f447-4e3a-8c4d-f6783780827b','news-e61c55a5-f447-4e3a-8c4d-f6783780827b','عندما يصبح الجميع «إعلاميين» !','عندما يصبح الجميع اعلاميين','أصبحت صفة سهلة، تُمنح بلا ضوابط، وأحياناً يمنحها الشخص لنفسه لمجرد أنه يملك حساباً مشهوراً، أو يظهر أمام الكاميرا، أو يشارك في برنامج، أو يكتب عن فريقه الرياضي. الإعلام مهنة لها أدواتها وأخلاقياتها ومسؤولياتها، تقوم على البحث والتحقق والدقة والفصل بين الخبر والرأي، ومعرفة حدود المسؤولية تجاه المجتمع والمتلقي.','["من أكثر الكلمات التي تعرضت للاستهلاك في السنوات الأخيرة كلمة «إعلامي».","أصبحت صفة سهلة، تُمنح بلا ضوابط، وأحياناً يمنحها الشخص لنفسه لمجرد أنه يملك حساباً مشهوراً، أو يظهر أمام الكاميرا، أو يشارك في برنامج، أو يكتب عن فريقه الرياضي.","المشجع أصبح إعلامياً، ومشهور السناب أصبح إعلامياً، وصاحب الحساب الذي يجمع مئات الآلاف من المتابعين أصبح إعلامياً، حتى بات السؤال مشروعاً: هل كل من امتلك جمهوراً أصبح إعلامياً؟","إذا كان الأمر كذلك، فما الذي بقي من المهنة؟","الإعلام ليس عدد متابعين، ولا كاميرا هاتف، ولا ميكروفوناً، ولا بطاقة تعريف تُكتب فيها كلمة «إعلامي».","الإعلام مهنة لها أدواتها وأخلاقياتها ومسؤولياتها، تقوم على البحث والتحقق والدقة والفصل بين الخبر والرأي، ومعرفة حدود المسؤولية تجاه المجتمع والمتلقي.","المشكلة ليست في مشاهير وسائل التواصل، ولا في المشجعين الذين يقدمون محتوى رياضياً؛ فمن حق الجميع التعبير وصناعة المحتوى والوصول إلى الجمهور.","المشكلة تبدأ عندما تختلط المسميات، فيتحول صانع المحتوى إلى إعلامي، والمؤثر إلى صحفي، والمشجع إلى ناقد مهني، دون أن تكون هناك حدود واضحة بين هذه الصفات."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/r59lhxn','https://sabq.org/article/r59lhxn','','https://sabq.org/article/r59lhxn','ماجد البريكان','الرياض','2026-09-06T21:59:00.000Z','2026-09-07T01:00:00.000Z','2026-09-07T04:08:26.864Z','https://media.sabq.org/news/2026/09/3cc5f588-493a-49ab-91dc-227866e64195/w1600.webp','/api/media/e61c55a5-f447-4e3a-8c4d-f6783780827b','/api/media/e61c55a5-f447-4e3a-8c4d-f6783780827b?variant=thumbnail','عندما يصبح الجميع «إعلاميين» !',1600,893,'valid','published','archived','valid',46,'592d9fa43dde5e98963de965b9d3c9f58390a42ca7f71e8898682342a21f2161','516430d2d771af7ec09350da265229aa38b593169b0f9c3c44e7c5bd16653bf1','محدّث','2026-09-07T04:08:26.864Z','2026-10-07T21:07:49.189Z','','',0,0,'saudi_region','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الرياض"]','["الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T21:07:49.189Z',200,5,0,'source_article_available','',NULL,NULL,'body:c55ff046041bb39181d2307e5d605e4ecf63cfcd8fb4e856a766fa515c5e78b7','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('28fd5864-f25d-456f-930e-0e80089d67a5','news-28fd5864-f25d-456f-930e-0e80089d67a5','أسعار النفط تواصل الارتفاع وسط مخاوف اضطراب الإمدادات في الشرق الأوسط','اسعار النفط تواصل الارتفاع وسط مخاوف اضطراب الامدادات في الشرق الاوسط','سجلت أسعار النفط ارتفاعًا جديدًا اليوم الاثنين، مع استمرار المخاوف من اضطرابات طويلة الأمد في إمدادات الشرق الأوسط ، نتيجة الهجمات المتبادلة بين الولايات المتحدة و إيران على سفن في مضيق هرمز ومناطق أخرى.','["وبحسب بيانات الأسواق، ارتفعت العقود الآجلة لخام برنت بمقدار 52 سنتًا، أو بنسبة 0.54٪، لتصل إلى 96.80 دولارًا للبرميل.","كما صعدت العقود الآجلة لخام غرب تكساس الوسيط الأمريكي بمقدار 66 سنتًا، أو بنسبة 0.72٪، لتبلغ 92.14 دولارًا للبرميل.","وفي السياق ذاته، أشار محللون إلى أن استمرار التوترات الجيوسياسية في منطقة الخليج يُبقي الأسعار تحت ضغط تصاعدي، مع ترقب الأسواق لأي تطورات قد تؤثر على حركة الملاحة وإمدادات الطاقة العالمية."]','الطاقة والصناعة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/fsezc5ykx','https://ajel.sa/economy/fsezc5ykx','https://ajel.sa/economy/fsezc5ykx','https://ajel.sa/economy/fsezc5ykx','فريق التحرير','','2026-09-06T22:12:00.000Z','Wed, 07 Oct 2026 19:04:44 GMT','2026-09-07T04:26:23.895Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-08/%D8%A7%D9%84%D9%86%D9%81%D8%B7-3-vbiC56n6.jpg','/api/media/28fd5864-f25d-456f-930e-0e80089d67a5','/api/media/28fd5864-f25d-456f-930e-0e80089d67a5?variant=thumbnail','أسعار النفط تواصل الارتفاع وسط مخاوف اضطراب الإمدادات في الشرق الأوسط',1200,675,'valid','published','archived','valid',52,'052245a7d6e5ca47f30cc7ee381ab18004d9681a238b064a0939b6b38a4fe839','44c7128e4cebad4808b8aaba2d127034e47e291c3791db15c22915313e4174cd','محدّث','2026-09-07T04:26:23.895Z','2026-10-07T19:04:45.511Z','','',0,0,'gulf_arab','عادي',45,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","إيران","الشرق الأوسط","الولايات المتحدة"]','["الطاقة والنفط","الشرق الأوسط","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Active','2026-10-07T19:04:45.511Z',200,4,0,'source_article_available','',NULL,NULL,'body:33ade2b894e35f736f4b6a40308767cce35389a384c348f9446ddc72564edd9d','Wed, 07 Oct 2026 19:04:44 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('17b83928-a26d-456d-8886-a31d714cf520','news-17b83928-a26d-456d-8886-a31d714cf520','استقرار أسعار الذهب مع ترقب الأسواق لبيانات التضخم الأمريكية','استقرار اسعار الذهب مع ترقب الاسواق لبيانات التضخم الامريكيه','استقرت أسعار الذهب اليوم الاثنين، مع ترقب المستثمرين لصدور بيانات التضخم الأمريكية في وقت لاحق من الأسبوع الجاري، بحثًا عن مؤشرات جديدة لمسار أسعار الفائدة لدى مجلس الاحتياطي الفيدرالي الأمريكي.','["وبلغ سعر الذهب في المعاملات الفورية 4,424.40 دولارًا للأوقية، فيما تراجعت العقود الأمريكية الآجلة للذهب تسليم ديسمبر المقبل بنسبة 0.1٪ إلى 4,471.60 دولارًا للأوقية.","وفي أسواق المعادن النفيسة الأخرى، استقرت الفضة في المعاملات الفورية عند 66.21 دولارًا للأوقية.","وانخفض سعر البلاتين بنسبة 0.7٪ ليصل إلى 1,807.38 دولارًا للأوقية، كما تراجع البلاديوم بنسبة 0.4٪ إلى 1,393 دولارًا.","يُذكر أن الأسواق تتابع عن كثب بيانات التضخم الأمريكية للتعرف على توجهات السياسة النقدية المقبلة في الولايات المتحدة ."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/w9x1fiqfa','https://ajel.sa/economy/w9x1fiqfa','https://ajel.sa/economy/w9x1fiqfa','https://ajel.sa/economy/w9x1fiqfa','فريق التحرير','','2026-09-06T22:10:00.000Z','Wed, 07 Oct 2026 19:04:44 GMT','2026-09-07T04:26:25.215Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%B0%D9%87%D8%A8-3-HMBZBDRm.jpg','/api/media/17b83928-a26d-456d-8886-a31d714cf520','/api/media/17b83928-a26d-456d-8886-a31d714cf520?variant=thumbnail','استقرار أسعار الذهب مع ترقب الأسواق لبيانات التضخم الأمريكية',1200,675,'valid','published','archived','valid',41,'e1ce0412b997020171f6bd3647751142285462e8ffe732b65e9824cf8f18bf08','da8f47e4b1ac736de57dce6b77b831215e3b9512a747e9d17c95ade3df22f86e','محدّث','2026-09-07T04:26:25.215Z','2026-10-07T20:25:22.793Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس الاحتياطي الفيدرالي الأمريكي وبلغ","الاقتصاد والأسواق","السياسة والعلاقات الدولية","الولايات المتحدة"]','["مجلس الاحتياطي الفيدرالي الأمريكي وبلغ","الاقتصاد والأسواق","السياسة والعلاقات الدولية","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T19:04:45.602Z',200,4,0,'source_article_available','',NULL,NULL,'body:357cfd1ae4da82b9f3952881f42923702fae790c586670a0932ea560deadd94c','Wed, 07 Oct 2026 19:04:44 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('158f55e2-98e0-4184-ada4-4879fd9527b9','news-158f55e2-98e0-4184-ada4-4879fd9527b9','أمطار رعدية وسيول وبرد تضرب 5 مناطق سعودية اليوم','امطار رعديه وسيول وبرد تضرب 5 مناطق سعوديه اليوم','توقّع المركز الوطني للأرصاد في تقريره عن حالة الطقس لهذا اليوم -بمشيئة الله تعالى- هطول أمطار رعدية متوسطة إلى غزيرة تؤدي إلى جريان السيول، مصحوبة بزخات من البرد، على أجزاء من مناطق جازان وعسير والباحة ومكة المكرمة.','["كما لا يستبعد التقرير تكوّن السحب الرعدية الممطرة على أجزاء من منطقة نجران، والأجزاء الجنوبية من منطقتي الشرقية والرياض، فضلاً عن مرتفعات منطقة المدينة المنورة، في حين تؤثر الرياح النشطة المثيرة للأتربة والغبار على أجزاء من تلك المناطق.","وعلى صعيد حركة البحار، أشار التقرير إلى أن الرياح السطحية على البحر الأحمر شمالية غربية إلى غربية بسرعة تتراوح بين 20 و45 كم/ساعة، وقد تصل إلى 50 كم/ساعة باتجاه خليج العقبة، مع ارتفاع للموج يتراوح بين متر ومترين، ويصل إلى مترين ونصف باتجاه خليج العقبة، وتُوصف حالة البحر بمتوسط الموج وصولاً إلى المائج باتجاه خليج العقبة.","أما على الخليج العربي، فتكون الرياح السطحية شرقية إلى جنوبية شرقية بسرعة تتراوح بين 10 و28 كم/ساعة، وارتفاع موج يتراوح بين نصف المتر ومتر واحد، وحالة البحر خفيف الموج."]','أخبار السعودية','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/yrqzkqc','https://sabq.org/article/yrqzkqc','','https://sabq.org/article/yrqzkqc','صحيفة سبق','الرياض','2026-09-06T22:14:00.000Z','2026-09-07T01:15:00.000Z','2026-09-07T04:26:25.576Z','https://media.sabq.org/news/2026/09/69e07ab8-0524-439e-b521-c4dbfbbca036/w1600.webp','/api/media/158f55e2-98e0-4184-ada4-4879fd9527b9','/api/media/158f55e2-98e0-4184-ada4-4879fd9527b9?variant=thumbnail','أمطار رعدية وسيول وبرد تضرب 5 مناطق سعودية اليوم',1600,893,'valid','published','archived','valid',99,'bd60bb3eea2188b9f7d5cf778fce1ab5b9f6eefc066346f0d922de99e78ce5d9','55d895be018cb1d393dbf5d6dc036c1948302c4b4dc3a2e978f31219e8f5e567','محدّث','2026-09-07T04:26:25.576Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","مكة","عسير","جازان","نجران","الرياض","الباحة","الخليج العربي"]','["الطقس والمناخ","الخليج العربي","المدينة المنورة"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:04:46.134Z',200,4,0,'source_article_available','',NULL,NULL,'body:11510a85a74ade50868c8c14f4fa2ee7e93252e20913502d5cfaf056e79d3161','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0302bcd6-057b-43e4-b914-61e2992894cf','news-0302bcd6-057b-43e4-b914-61e2992894cf','مالك الخلود يتحول إلى «مندوب توصيل».. هاربورغ يعد جماهير الرياض بإيصال قمصان النادي بنفسه','مالك الخلود يتحول الي مندوب توصيل هاربورغ يعد جماهير الرياض بايصال قمصان النادي بنفسه','في خطوة غير معتادة من مالك نادٍ في دوري روشن، أعلن الأمريكي بن هاربورغ، مالك نادي الخلود، مساء الأحد 6 سبتمبر 2026، أنه سيتولى بنفسه توصيل قمصان النادي إلى من يطلبها في الرياض، وذلك بعد ساعات من طرح متجر النادي طقمه الجديد.','["وكتب هاربورغ عبر حسابه في منصة «إكس»، معيدًا نشر إعلان النادي: «إذا كنت بالرياض وبتطلب وحدة من تيشيرتات النادي فئة اللاعبين (اليوم الأحد أو بكره الاثنين)..","بحاول قد ما أقدر أني أوصلها لك بنفسي بكره بالتعاون مع أقوى تطبيق توصيل ❤️»، مرفقًا صورة القميص ورابط المتجر الرسمي، دون أن يسمّي التطبيق.","وكان الحساب الرسمي لنادي الخلود قد أعلن السبت طرح الطقم الجديد بعبارة: «الطقم اللي تنتظره..","الحين بين يديك»، فيما جاءت خطوة المالك امتدادًا لأسلوبه في التواصل المباشر مع الجماهير باللهجة المحلية، وهو الذي وصف نهجه في إدارة النادي سابقًا بـ«الشفافية المطلقة في كل جوانب النادي».","ويُعد هاربورغ، مؤسس شركة «نوفو كابيتال» الاستثمارية، أول مالك أجنبي لنادٍ سعودي؛ إذ استحوذت «مجموعة هاربورغ» على حصة الأغلبية في نادي الخلود، القادم من مدينة الرس بمنطقة القصيم، في صيف 2025 بإعلان من وزارة الرياضة، ضمن مشروع تخصيص الأندية، وسبق أن قال إنه يجهز الخلود «للانتشار عالميًا»."]','الرياضة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/9zsnzy9','https://sabq.org/article/9zsnzy9','','https://sabq.org/article/9zsnzy9','صحيفة سبق','الرياض','2026-09-06T22:43:00.000Z','2026-09-06T22:44:00.000Z','2026-09-07T05:34:30.352Z','https://media.sabq.org/news/2026/09/74f1c129-10b4-4c9c-8abb-e7f33ba9fbcf/w1144.webp','/api/media/0302bcd6-057b-43e4-b914-61e2992894cf','/api/media/0302bcd6-057b-43e4-b914-61e2992894cf?variant=thumbnail','مالك الخلود يتحول إلى «مندوب توصيل».. هاربورغ يعد جماهير الرياض بإيصال قمصان النادي بنفسه',1144,2048,'valid','published','archived','valid',97,'0af2082ebb3ee8982c8aef5d3df995f7eaa7e36c7af3b9a4578caa0b06a528d9','0927172b45f7bbb2134c706dc8d706a5f04921f26a0ec740419ce271ad49c289','محدّث','2026-09-07T04:44:25.984Z','2026-10-07T19:33:53.632Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الرياضة ضمن مشروع تخصيص","شركة نوفو كابيتال الاستثمارية أول","الرياضة السعودية","الاقتصاد والأسواق","الرياض","القصيم"]','["وزارة الرياضة ضمن مشروع تخصيص","شركة نوفو كابيتال الاستثمارية أول","الرياضة السعودية","الاقتصاد والأسواق"]','classified','','[{"category":"التقنية","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T19:33:53.632Z',200,2,0,'source_article_available','',NULL,NULL,'body:e2322690fc4faa39a83f40c1390e721807e5f654c92e136d8d201dc1fe7102e4','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2639e7ab-c2bb-49bc-a33c-66ac19eb82cb','news-2639e7ab-c2bb-49bc-a33c-66ac19eb82cb','لا تجعل خطأ ابنك في المدرسة معركة!','لا تجعل خطا ابنك في المدرسه معركه','لذلك فإن ظهور بعض المشكلات السلوكية خلال سنوات الدراسة أمر يستحق الفهم والتقويم، لا التهويل أو التبرير. السلوك لا يحدث في فراغ؛ فقد تقف خلفه صعوبة في تنظيم الانفعالات، أو ضعف في مهارات التواصل وحل النزاعات، أو ضغوط اجتماعية ومدرسية.','["المدرسة ليست مكانًا للتعلّم الأكاديمي فقط، بل بيئة اجتماعية يتعلم فيها الطفل ضبط انفعالاته، واحترام الحدود، والتعامل مع الاختلاف والرفض والمنافسة.","لذلك فإن ظهور بعض المشكلات السلوكية خلال سنوات الدراسة أمر يستحق الفهم والتقويم، لا التهويل أو التبرير.","عندما تتواصل المدرسة بشأن سلوك الابن، قد يقع الوالدان بين موقفين متناقضين؛ دفاع مطلق عنه، أو عقاب قاسٍ قبل الاستماع إليه.","وكلاهما قد يحرم الطفل من فرصة مهمة لتعلّم المسؤولية.","فالتربية لا تعني حماية الأبناء من نتائج أخطائهم، كما لا تعني إشعارهم بأن الخطأ ينتقص من قيمتهم.","السلوك لا يحدث في فراغ؛ فقد تقف خلفه صعوبة في تنظيم الانفعالات، أو ضعف في مهارات التواصل وحل النزاعات، أو ضغوط اجتماعية ومدرسية.","ولهذا فإن السؤال التربوي الأهم ليس: «من المخطئ؟» فقط، وإنما: «لماذا حدث هذا السلوك، وما المهارة التي يحتاج الطفل إلى تعلمها حتى لا يتكرر؟».","هنا تتكامل مسؤولية الأسرة والمدرسة: الاستماع، وفهم السياق، ووضع حدود واضحة، ثم مساعدة الطفل على تحمّل نتيجة تصرفه وإصلاح أثره."]','الاقتصاد','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/G6GLfSs','https://sabq.org/article/G6GLfSs','','https://sabq.org/article/G6GLfSs','د.نجوى بنت ذياب المطيري','','2026-09-06T22:46:00.000Z','2026-09-07T01:46:00.000Z','2026-09-07T04:55:21.877Z','https://media.sabq.org/news/2026/09/37f04596-9d6c-4fbf-8cd9-42aa6db19bd2/w1600.webp','/api/media/2639e7ab-c2bb-49bc-a33c-66ac19eb82cb','/api/media/2639e7ab-c2bb-49bc-a33c-66ac19eb82cb?variant=thumbnail','لا تجعل خطأ ابنك في المدرسة معركة!',1600,893,'valid','published','archived','valid',41,'04d539b0e3b33aa7f8cb7bca4d22f3e3e86955ba4a8c97e8720c3cd05c3eda47','fa3fd9cd5fed89da33479494d4d28c03d29e9a0e0cd3010affff5dbaf9b6e617','محدّث','2026-09-07T04:55:21.877Z','2026-10-07T20:25:22.793Z','','',0,0,'international','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T19:34:58.344Z',200,2,0,'source_article_available','',NULL,NULL,'body:ab0f8d1ea513b9b9c27235593b0710be3f6f6dd7e3a54d47dc1c384e4471aeb1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9758d76f-9e90-46b8-8fc3-8adc590274ed','news-9758d76f-9e90-46b8-8fc3-8adc590274ed','بيئي / العُلا.. موطن للنسور وجهود متواصلة لرصد حركتها وتكاثرها وحماية الأنواع المهددة بالانقراض','بيئي العلا موطن للنسور وجهود متواصله لرصد حركتها وتكاثرها وحمايه الانواع المهدده بالانقراض','العُلا 24 ربيع الأول 1448 هـ الموافق 06 سبتمبر 2026 م واس تشكل العُلا بتنوع تضاريسها بيئة طبيعية لعدد من أنواع النسور والطيور المهاجرة، التي أسهمت برامج الرصد والدراسات الميدانية في توثيق حضورها خاصة الأنواع المهددة بالانقراض، ودراسة تحركاتها وسلوكها واحتياجاتها البيئية.','["ويتزامن ذلك مع اليوم العالمي للتوعية بالنسور، الذي يوافق أول سبت من شهر سبتمبر من كل عام، ويسلط الضوء على أهمية هذه الطيور ودورها في التوازن البيئي، وضرورة الحد من المهددات التي تواجهها في مختلف أنحاء العالم.","وتبرز محمية شرعان الطبيعية، التي تتجاوز مساحتها (1500) كيلومتر مربع، ضمن البيئات التي سجلت حضور أنواع نادرة من النسور، إذ وثق فريق الرصد البيئي فيها ظهور نسر \"روبل\" المهدد بالانقراض، في حالة نادرة تُعد التوثيق الرسمي الثاني لهذا النوع في أجواء العُلا.","وتشير نتائج الرصد الميداني إلى تسجيل ما بين (20) و(30) فردًا من نسر الأذون في العُلا بصورة منتظمة، بما يمثل نحو (2.5%) من التعداد الوطني لهذا النوع، إلى جانب رصد أربعة أزواج متكاثرة في المنطقة خلال الموسم الحالي.","وفي جانب البحث العلمي، وظفت الهيئة الملكية لمحافظة العُلا التقنيات الحديثة في دراسة النسور، وأطلقت، بالتعاون مع جامعة الملك عبدالله للعلوم والتقنية \"كاوست\"، برنامجًا لتتبع نسر الأذون باستخدام نظام تحديد المواقع العالمي (GPS)، لجمع بيانات دقيقة عن تحركاته وسلوكه ومناطق وجوده والمخاطر المحتملة التي قد تواجهه، والاستفادة منها في توجيه الإجراءات البيئية ذات الصلة.","وتشمل الأعمال الميدانية كذلك الحد من المخاطر المرتبطة بمسارات الطيور المهاجرة، واستعادة البيئات الطبيعية، وإجراء الدراسات المتخصصة، ضمن منظومة تسهم في استدامة الأنواع الفطرية والمحافظة على التنوع الحيوي في العُلا.","وتؤدي النسور دورًا مهمًا في سلامة النظم البيئية، من خلال التخلص من الجيف وإعادة تدوير العناصر الغذائية، فيما يُعد وجودها ونجاح تكاثرها مؤشرًا على توازن البيئة؛ لتوفر عمليات الرصد والتتبع العلمي في العُلا بيانات مهمة لفهم هذه الطيور، ودعم الإجراءات الرامية إلى حمايتها واستمرارها في بيئاتها الطبيعية. // انتهى // 21:05 ت مـ 0165"]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2670154?type=news&uuid=N2670154','https://spa.gov.sa/ar/N2670154?type=news&uuid=N2670154','N2670154','N2670154','','المدينة المنورة','2026-09-06T15:05:00.000Z',NULL,'2026-09-07T04:55:33.365Z','','','','بيئي / العُلا.. موطن للنسور وجهود متواصلة لرصد حركتها وتكاثرها وحماية الأنواع المهددة بالانقراض',NULL,NULL,'all_candidates_failed (og:fetch failed)','published','archived','valid',50,'4d78d8f4fd03fbb8c845316c8d01090edef756ea36a0965f6e6b9839380ca2e3','a0310976752b2c11b55ba6698a569ac60d1118576865423f3fac792f3ac7c802',NULL,'2026-09-07T04:55:33.365Z','2026-10-07T19:35:00.907Z','','',0,0,'saudi_region','مهم',76,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة الملك عبدالله للعلوم والتقنية","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["جامعة الملك عبدالله للعلوم والتقنية","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"الاقتصاد","score":1.5},{"category":"الرياضة","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T19:35:00.907Z',200,2,0,'source_article_available','',NULL,NULL,'body:5187059c5278a879dad366a99af7fac77c37d9ef651938c19c958c6d5d11c7b5','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f1cf9d72-b8af-4351-9094-dd929f34291a','news-f1cf9d72-b8af-4351-9094-dd929f34291a','مكتب البيئة بمكة المكرمة ينفّذ فرضية طوارئ لمحاكاة التماس كهربائي','مكتب البيئه بمكه المكرمه ينفذ فرضيه طوارئ لمحاكاه التماس كهربائي','نفّذ مكتب وزارة البيئة والمياه والزراعة بالعاصمة المقدسة فرضيةً تدريبيةً تحاكي وقوع التماس كهربائي داخل مقر المكتب، وذلك بمشاركة فريق الطوارئ، وبالتعاون مع قسم القطاع غير الربحي والحلول الزراعية، وبدعم من الخدمات المساندة ممثلةً في وحدة الأمن والسلامة.','["وتضمّنت الفرضية تطبيق إجراءات الإخلاء والتعامل مع موقع الحادثة وفق خطط الطوارئ المعتمدة، فيما أُتيحت فرصة تطوعية للمشاركة في تنفيذها بهدف تعزيز ثقافة التطوع، ورفع الوعي بإجراءات السلامة، وتنمية مهارات التعامل مع الحالات الطارئة، وقياس سرعة الاستجابة والتنسيق بين الفرق المشاركة.","وأكد مدير المكتب المهندس غالب بن يحيى حامظي أن تنفيذ مثل هذه الفرضيات يأتي في إطار حرص المكتب على تعزيز جاهزية منسوبيه ورفع مستوى الوعي بإجراءات الأمن والسلامة، مشيراً إلى أهمية التدريب العملي والتنسيق بين مختلف الأقسام والفرق لضمان سرعة وكفاءة التعامل مع الطوارئ.","وأضاف حامظي أن إشراك المتطوعين يعزز ثقافة العمل التطوعي والمسؤولية المشتركة، ويسهم في بناء بيئة عمل أكثر أماناً وجاهزية، مؤكداً استمرار المكتب في تنفيذ البرامج والفرضيات التدريبية الداعمة لسلامة منسوبيه ومراجعيه، ورفع مستوى الاستعداد لمواجهة مختلف الحالات الطارئة."]','المجتمع','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/P66aO0Y','https://sabq.org/article/P66aO0Y','','https://sabq.org/article/P66aO0Y','فهد العتيبي','مكة المكرمة','2026-09-06T23:03:00.000Z','2026-09-07T02:03:00.000Z','2026-09-07T05:07:26.856Z','https://media.sabq.org/news/2026/09/070c78d9-13d5-4c4e-a3c9-b87a2827526a/w1280.webp','/api/media/f1cf9d72-b8af-4351-9094-dd929f34291a','/api/media/f1cf9d72-b8af-4351-9094-dd929f34291a?variant=thumbnail','مكتب البيئة بمكة المكرمة ينفّذ فرضية طوارئ لمحاكاة التماس كهربائي',1280,960,'valid','published','archived','valid',86,'36dc5e09720e049d6d2e7c389122e0944d4aebdf7f329a7275d7f550023c3482','dc8478ef09a7998f0c6d143f58eaad4f9183a98428082418b834f2efcc34764d','محدّث','2026-09-07T05:07:26.856Z','2026-10-07T19:36:17.529Z','','',0,0,'saudi_region','مهم',74,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البيئة والمياه والزراعة بالعاصمة","الثقافة والفنون","التعليم والتدريب","مكة"]','["وزارة البيئة والمياه والزراعة بالعاصمة","الثقافة والفنون","التعليم والتدريب"]','classified','','[{"category":"المناطق","score":3},{"category":"الرياضة","score":1.5},{"category":"التقنية","score":1.5}]','Active','2026-10-07T19:36:17.529Z',200,2,0,'source_article_available','',NULL,NULL,'body:7dd7982acaeff1166a20002db3a43f5edcd2f32d155d7190ca7a791441eedf7e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cc4047fa-c322-4746-b95d-3b68bf7f064d','news-cc4047fa-c322-4746-b95d-3b68bf7f064d','فيورنتينا يقيل فابيان غروسو بعد ثلاث هزائم متتالية في الدوري الإيطالي','فيورنتينا يقيل فابيان غروسو بعد ثلاث هزائم متتاليه في الدوري الايطالي','أقال نادي فيورنتينا الإيطالي مدربه فابيان غروسو من منصبه، عقب تعرض الفريق لثلاث هزائم متتالية في الدوري الإيطالي خلال الموسم الجديد، ليصبح أول مدرب يُقال من بين أندية الدوريات الخمس الكبرى هذا الموسم.','["وتعرض فيورنتينا لخسارة قاسية أمام روما بنتيجة 4-0، ثم خسر على أرضه من فروزينوني الصاعد حديثاً بثلاثية نظيفة، قبل أن يسقط مجدداً في ملعبه أمام تورينو بنتيجة 2-1، مكتفياً بتسجيل هدف واحد فقط مقابل استقبال تسعة أهداف خلال المباريات الثلاث.","أنهى النادي مهمة غروسو، مدافع منتخب إيطاليا السابق، بعد أقل من ثلاثة أشهر على توليه تدريب الفريق. وكان غروسو قد وقع عقداً لمدة عامين عقب تعيينه بديلاً للمدرب باولو فانولي.","واشتهر غروسو بتسجيل ركلة الترجيح الحاسمة في نهائي كأس العالم 2006 أمام فرنسا، كما سبق له تدريب أولمبيك ليون الفرنسي، وحقق نتائج إيجابية مع ساسولو ، الذي قاده للصعود من الدرجة الثانية.","أشارت تقارير محلية إلى توجه إدارة فيورنتينا نحو تعيين تياغو موتا مدرباً جديداً للفريق، وذلك قبل مواجهة فينيتسيا المرتقبة يوم الجمعة."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/18t0x2tbc','https://ajel.sa/sports/18t0x2tbc','https://ajel.sa/sports/18t0x2tbc','https://ajel.sa/sports/18t0x2tbc','فريق التحرير','','2026-09-06T23:19:00.000Z','2026-09-07T02:19:00.000Z','2026-09-07T05:25:24.580Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/featured-crop-N8tx98Pi.jpg','/api/media/cc4047fa-c322-4746-b95d-3b68bf7f064d','/api/media/cc4047fa-c322-4746-b95d-3b68bf7f064d?variant=thumbnail','فيورنتينا يقيل فابيان غروسو بعد ثلاث هزائم متتالية في الدوري الإيطالي',1200,675,'valid','published','archived','valid',41,'973cfc19dd8b06459564eb19b6cc2ff0273d1f0871d612ed8730a8ab7a9d0611','dba43d029e6b3978ebc2bd4cfb64cd9e2facb24640ed2a45c9cb6985359f8c88','محدّث','2026-09-07T05:25:24.580Z','2026-10-07T20:25:22.793Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب","الرياضة السعودية"]','["التعليم والتدريب","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:59:17.419Z',NULL,3,3,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bf155bde-0b58-4d31-b04a-fa56300ff371','news-bf155bde-0b58-4d31-b04a-fa56300ff371','ما الذي يقرر نشر الكتاب: محتواه أم فاتورة المطبعة؟','ما الذي يقرر نشر الكتاب محتواه ام فاتوره المطبعه','كان قرار نشر الكتاب يبدأ من المخطوط: فكرته، وقيمته، وجودة لغته، وما يضيفه إلى القارئ والمكتبة. فكلما زاد عدد الصفحات، ارتفعت كلفة الورق والتجليد والشحن والتخزين، وارتفع معها سعر الكتاب.','["كان قرار نشر الكتاب يبدأ من المخطوط: فكرته، وقيمته، وجودة لغته، وما يضيفه إلى القارئ والمكتبة.","أما اليوم، فقد دخل سؤال آخر إلى غرفة القرار، وأصبح يسبق الأسئلة التحريرية أحياناً: كم عدد صفحات الكتاب، وكم ستكلف طباعته، وبأي سعر يمكن بيعه؟","لم تتخلَّ دور النشر عن دورها الثقافي، لكنها تعمل في سوق ترتفع فيها كلفة الإنتاج، بينما تظل قدرة القارئ على الشراء محدودة.","فكلما زاد عدد الصفحات، ارتفعت كلفة الورق والتجليد والشحن والتخزين، وارتفع معها سعر الكتاب.","وقد يكون المخطوط جيداً ومستحقاً للنشر، ثم تتوقف الدار أمام عدد صفحاته، لا أمام محتواه.","هذه ليست فرضية عن واقع النشر؛ بل واقع حقيقي، فللورق عالمياً سوق متقلبة، فيما تتجه مصانع كثيرة نحو المنتجات الأعلى طلباً وربحية، مثل أوراق التغليف، على حساب الأوراق المخصصة للكتب.","وفي أوروبا انخفض إنتاج ورق الكتب بنسبة 7% خلال عام واحد، فضاق المعروض من بعض المقاسات والأوزان والأنواع ودرجات الألوان.","وخلال عام 2026، شهدت بعض الأسواق زيادات تجاوزت 15% في أسعار فئات ورقية متعددة، نتيجة انخفاض الإنتاج وارتفاع كلفة المواد الأولية والطاقة والنقل."]','الثقافة','','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/article/lhykc6s','https://sabq.org/article/lhykc6s','','https://sabq.org/article/lhykc6s','إبراهيم آل سنان','','2026-09-06T23:30:00.000Z','2026-09-07T02:30:00.000Z','2026-09-07T05:34:31.025Z','https://media.sabq.org/news/2026/09/4da01fd3-7ba5-4d2c-89bc-08bd9afe59d9/w1448.webp','/api/media/bf155bde-0b58-4d31-b04a-fa56300ff371','/api/media/bf155bde-0b58-4d31-b04a-fa56300ff371?variant=thumbnail','ما الذي يقرر نشر الكتاب: محتواه أم فاتورة المطبعة؟',1448,1086,'valid','published','archived','valid',35,'c50ef039cbf01e679b0a68df3adb3a6991dcd68b74536a8897446678b2ee8fc4','aa63ecde46e7aaa6dc93052327339a2543b0eb1b86a6c2644195289c83f1a1a8','محدّث','2026-09-07T05:34:31.025Z','2026-10-07T20:25:22.793Z','','',0,0,'international','عادي',51,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","أوروبا"]','["الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"المجتمع","score":0},{"category":"الرياضة","score":0}]','Active','2026-10-07T20:01:55.608Z',200,2,0,'source_article_available','',NULL,NULL,'body:fbb6ca9eb23430a2fcf2e969630d767f6955300c9f019a32c1faa185e6d610a7','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0d59c753-7f42-4139-879d-a19993af7df9','news-0d59c753-7f42-4139-879d-a19993af7df9','الطيران المدني: 3 ضحايا و36 إصابة جراء اعتداءين على مطاري أبها والملك خالد','الطيران المدني 3 ضحايا و36 اصابه جراء اعتداءين علي مطاري ابها والملك خالد','أعلنت الهيئة العامة للطيران المدنى أنه خلال يومي الثلاثاء والأربعاء 25 و 26 ربيع الآخر 1448هـ الموافق 6 و 7 أكتوبر 2026م تعرض مطارا أبها والملك خالد الدوليان اعتداءين استهدفا مرافقهما، وقد باشرت فرق الطوارئ والجهات المختصة التعامل مع الاعتداءين فور وقوعهما وفق الإجراءات والخطط المعتمدة.','["وقد نتج عن الاعتداء السافر على مطار أبها الدولي حالنا وفاة المقيمتين من الجنسيتين المغربية والجزائرية - رحمهما الله - و (28) إصابة لمواطنين ومقيمين البين من الجنسيتين البنغلاديشية والفلبينية تراوحت إصاباتهم من الطفيفة إلى البليغة.","فيما أسفر الاعتداء على مطار الملك خالد الدولي عن حالة وفاة لمقيم من الجنسية. السودانية - رحمه الله - و (8) إصابات منها خمسة مواطنين ومقيمين اثنين من الجنسية المصرية، ومقيم من الجنسية الباكستانية تراوحت إصاباتهم من الطفيفة إلى البليغة.","كما تم بشكل فوري نقل كل المصابين إلى المستشفى لتلقي الرعاية الطبية اللازمة. هذا ونتج عن الاعتداءين بعض الأضرار المادية.","وتعمل الهيئة - بالتكامل والتنسيق المستمر مع الجهات الأمنية ذات العلاقة - على تقييم الأضرار واتخاذ جميع الإجراءات اللازمة لضمان سلامة المسافرين والعاملين. والمحافظة على أمن وسلامة منظومة الطيران المدني ب المملكة ."]','السفر','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/tb4gozwac','https://ajel.sa/local/tb4gozwac','https://ajel.sa/local/tb4gozwac','https://ajel.sa/local/tb4gozwac','فريق التحرير','المدينة المنورة','2026-10-07T11:55:00.000Z','2026-10-07T15:00:00.000Z','2026-10-07T18:02:42.362Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/%D8%A7%D9%84%D8%B7%D9%8A%D8%B1%D8%A7%D9%86-oXMxN9i3.jpg','/api/media/0d59c753-7f42-4139-879d-a19993af7df9','/api/media/0d59c753-7f42-4139-879d-a19993af7df9?variant=thumbnail','الطيران المدني: 3 ضحايا و36 إصابة جراء اعتداءين على مطاري أبها والملك خالد',1200,675,'valid','published','current','valid',40,'780c664f6875aa8fe5e4849b3f7b195989aa469f0e648288d5fac6c34526ceb8','76b923d551fbebbbc04e67d90d396c644975b4a4edbdd60bc9a9d67031761e9e','محدّث','2026-10-07T18:02:42.362Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','مهم',80,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","السفر والسياحة"]','["الصحة العامة","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T20:16:39.976Z',NULL,2,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4f68ac59-8220-40e5-8810-b54a7446c500','news-4f68ac59-8220-40e5-8810-b54a7446c500','جازان تسجل أعلى كمية هطول في المملكة بـ33.7 ملم','جازان تسجل اعلي كميه هطول في المملكه بـ33 7 ملم','وأوضح المركز الوطني للأرصاد أن سرعة الرياح الهابطة المصاحبة للأمطار في منطقة جازان بلغت (130) كيلومترًا في الساعة، بالتزامن مع هطول الأمطار التي تأثرت بها المنطقة.','["سجّلت منطقة جازان ، أمس، أعلى كمية هطول أمطار على مستوى مناطق المملكة ، بلغت (33.7) ملم، وذلك ضمن الحالة المطرية التي تشهدها عدة مناطق، وتستمر حتى نهاية الأسبوع الجاري.","وتأتي هذه الحالة المطرية ضمن تأثيرات جوية تشهدها مناطق متفرقة من المملكة، وفقًا لما رصده المركز الوطني للأرصاد، مع استمرار فرص هطول الأمطار حتى نهاية الأسبوع الجاري."]','البيئة والمناخ','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/ugnpf6cpi','https://ajel.sa/local/ugnpf6cpi','https://ajel.sa/local/ugnpf6cpi','https://ajel.sa/local/ugnpf6cpi','فريق التحرير','جازان','2026-10-07T11:25:00.000Z','2026-10-07T14:25:00.000Z','2026-10-07T18:03:00.170Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/%D8%AC%D8%A7%D8%B2%D8%A7%D9%86-y7yyu-68.jpg','/api/media/4f68ac59-8220-40e5-8810-b54a7446c500','/api/media/4f68ac59-8220-40e5-8810-b54a7446c500?variant=thumbnail','جازان تسجل أعلى كمية هطول في المملكة بـ33.7 ملم',1200,675,'valid','published','current','valid',88,'14453d6c9f511b3963684928660d155660a144b5274d727c432dc44222459a9b','76abb2dcc690c3caad06d71be8594de6a5e40c821da57a64cfadd494fff7581b','محدّث','2026-10-07T18:03:00.170Z','2026-10-07T20:16:39.974Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","جازان"]','["الطقس والمناخ"]','classified','','[{"category":"أخبار السعودية","score":3},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Temporarily Unreachable','2026-10-07T20:16:39.974Z',NULL,2,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
