INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('29fe7fe6-c1d4-469a-afb0-a86ba316744c','news-29fe7fe6-c1d4-469a-afb0-a86ba316744c','«بلومبرغ»: سوريا تتوقع استقبال نحو 1000 شاحنة محملة بالنفط العراقي يومياً','بلومبرغ سوريا تتوقع استقبال نحو 1000 شاحنه محمله بالنفط العراقي يوميا','وأضاف في مقابلة مع وكالة بلومبرغ أن الاتفاق بين الحكومتين بات شبه مكتمل، متوقعاً بدء نقل أولى شحنات الخام العراقي عبر الشاحنات إلى سوريا بحلول منتصف أكتوبر الجاري.','["قال يوسف قبلاوي، الرئيس التنفيذي لشركة البترول السورية المملوكة للدولة، إن الحكومة العراقية طلبت من سوريا المساعدة في تصدير النفط الخام، إضافة إلى تدفقات زيت الوقود القائمة بالفعل.","ويأتي هذا التوجه في وقت تستمر فيه الهجمات على السفن العابرة ل مضيق هرمز ، وسط غياب حل نهائي للحرب مع إيران، رغم تحسن تدفقات الشحن عبر المضيق خلال الأسابيع الأخيرة. ومن شأن الخطة الجديدة تعزيز مكانة سوريا كبوابة بديلة وآمنة نسبياً لعبور النفط العراقي، بعدما تأثرت صادرات المنطقة منذ اندلاع الحرب في نهاية فبراير الماضي."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/0hq6koui4','https://ajel.sa/economy/0hq6koui4','https://ajel.sa/economy/0hq6koui4','https://ajel.sa/economy/0hq6koui4','فريق التحرير','','2026-10-07T09:56:00.000Z','Wed, 07 Oct 2026 18:14:32 GMT','2026-10-07T18:03:07.021Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/%D8%A7%D9%84%D9%86%D9%81%D8%B7-3-L8gWWWfZ.jpg','/api/media/29fe7fe6-c1d4-469a-afb0-a86ba316744c','/api/media/29fe7fe6-c1d4-469a-afb0-a86ba316744c?variant=thumbnail','«بلومبرغ»: سوريا تتوقع استقبال نحو 1000 شاحنة محملة بالنفط العراقي يومياً',1200,675,'valid','published','current','valid',46,'6ef386bd7e458078ad9b9d2d4c233e27d60923a485e8747a340d9369663ba038','61816faa9cc09e80747cc75aed44309f80a735bf99df683256d58e63bdbe1a34','محدّث','2026-10-07T18:03:07.021Z','2026-10-07T20:25:22.793Z','','',0,0,'gulf_arab','عادي',49,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","سوريا","إيران","العراق"]','["الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Temporarily Unreachable','2026-10-07T20:17:22.713Z',NULL,2,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('10396b87-10e7-4429-abca-c14cc69b692a','news-10396b87-10e7-4429-abca-c14cc69b692a','Ministry of Municipalities and Housing: More Than 667 Kilometers of Pedestrian Walkways and 1.28 Million Square Meters of Plazas Developed During the First Half of 2026','ministry of municipalities and housing more than 667 kilometers of pedestrian walkways and 1 28 million square meters of plazas developed during the first half of 2026','The Ministry of Municipalities and Housing announced the achievements of municipal authorities during the first half of 2026 in the development of public spaces.','["The Ministry of Municipalities and Housing announced the achievements of municipal authorities during the first half of 2026 in the development of public spaces. The work included more than 667 kilometers of pedestrian walkways and sidewalks, 108 municipal plazas with a total area of approximately 1.28 million square meters, in addition to 44 municipal parks covering more than 803,000 square meters, and 3,070 linear meters of waterfronts. These projects were carried out as part of efforts to develop cities and governorates across various regions of the Kingdom.","The nature of the work carried out by the municipal authorities varied according to the characteristics and needs of each city. The Riyadh Region Municipality recorded the longest network of pedestrian walkways and sidewalks, at approximately 517 kilometers, in addition to 101 municipal plazas. The Madinah Region Municipality recorded the largest park area, totaling 417.6 thousand square meters. In terms of waterfronts, the Eastern Region Municipality ranked first with 1,920 linear meters, followed by the Tabuk Region Municipality with 1,150 linear meters.","The Ministry explained that these projects are part of its approach to developing cities that are more accessible and easier to live in and navigate, by expanding pedestrian networks, facilitating access to parks, plazas, and facilities, and increasing the availability of public spaces within neighborhoods. This enhances residents’ everyday experience and directly connects municipal services with their needs.","The Ministry noted that developing pedestrian walkways, parks, plazas, and waterfronts contributes to enhancing the urban landscape and strengthening the identity of cities. It also supports the role of public spaces as an active part of residents’ daily lives, as part of the Ministry’s approach toward “A Lifestyle from Your Home to Your City.”","The Ministry reaffirmed its continued efforts, in coordination with municipalities and municipal authorities, to develop public spaces and improve the efficiency of municipal facilities and areas. These efforts aim to enhance ease of movement and the vitality of neighborhoods, expand residents’ options for accessing public spaces and services, and support the objectives of Saudi Vision 2030 in developing sustainable and attractive cities.","Minister of Municipalities and Housing Delivers Housing Units to Eligible Families in Partnership with Saudi National Bank","In the presence of His Excellency the Minister of Municipalities and Housing and Chairman of the Board of Trustees of the National Develo","Ministry of Municipalities and Housing Updates Requirements for Ice Cream Shops to Regulate the Activity and Ensure Food Safety Standards"]','أخبار السعودية','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/en/news/ministry-municipalities-and-107','https://momah.gov.sa/en/news/ministry-municipalities-and-107','','https://momah.gov.sa/en/news/ministry-municipalities-and-107','','','2026-10-01T04:02:00.000Z','Wed, 07 Oct 2026 11:56:34 GMT','2026-10-07T18:03:08.022Z','','','','Ministry of Municipalities and Housing: More Than 667 Kilometers of Pedestrian Walkways and 1.28 Million Square Meters of Plazas Developed During the First Half of 2026',NULL,NULL,'no_article_image_candidates','rejected','rejected','invalid',35,'259a4ef3c04f7e81d66504b3c428c553b0bb42efeee41e38d215e8daa00abf9e','24dd0b209993717a4cafaf15e22fe389c5a4f2a78e3ce0242ca2ac60a686c025',NULL,'2026-10-07T18:03:08.022Z','2026-10-07T18:20:32.476Z','','',0,0,'international','عادي',38,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T18:14:52.392Z',200,1,0,'source_article_available','',NULL,NULL,'"1791374194"','Wed, 07 Oct 2026 11:56:34 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c0bc5b86-9ac7-46dd-9d55-708c774baef4','news-c0bc5b86-9ac7-46dd-9d55-708c774baef4','With the Participation of 17 Municipal Authorities, the Ministry of Municipalities and Housing and SNB Expand the Impact of Student Volunteering Through “Cities of Urban Beauty”','with the participation of 17 municipal authorities the ministry of municipalities and housing and snb expand the impact of student volunteering through cities of urban beauty','The initiative is part of efforts to support volunteer work and enhance community participation related to improving the urban landscape and preserving public facilities and the urban environment.','["The Ministry of Municipalities and Housing, in partnership with SNB Group, implemented the “Cities of Urban Beauty” initiative, with the participation of more than 10,000 male and female students and in cooperation with 17 municipal authorities across various regions of the Kingdom. The initiative is part of efforts to support volunteer work and enhance community participation related to improving the urban landscape and preserving public facilities and the urban environment.","The initiative includes several volunteer activities, including addressing visual pollution, planting trees, caring for beaches, and carrying out exterior painting works at schools. These activities aim to engage students in fieldwork that contributes to serving their cities and strengthening their sense of social responsibility.","The Ministry explained that the initiative is part of its partnership with SNB Group to support community initiatives related to the municipal and housing sectors and expand student participation in volunteer activities connected to cities and their facilities. This is part of efforts to strengthen the community’s role in improving the urban landscape, preserving the urban environment, and enhancing the quality of public facilities.","The Ministry noted that the initiative connects volunteer work with cities and their everyday needs by involving students in activities related to tree planting, facility maintenance, and public spaces. This contributes to creating more vibrant neighborhoods and expanding the community’s contribution to improving residents’ experiences within their cities.","In Tabuk, several activities were carried out as part of the initiative in coordination with the Tabuk Region Municipality, with the participation of 800 male and female students over two days. The activities included volunteer work and environmental practices related to improving the urban landscape, preserving public facilities, and encouraging students to contribute to serving their city and community.","The Ministry stated that “Cities of Urban Beauty” represents a model of integration between the municipal and housing sectors, the private sector, and the educational community. It directs volunteer work toward initiatives with urban and community impact, connects student participation with activities that contribute to improving cities and preserving their facilities, and raises awareness of the importance of the urban environment and service quality.","In its previous phase, the “Cities of Urban Beauty” initiative involved more than 10,000 male and female volunteers and generated more than 50,000 volunteer hours across various regions of the Kingdom. The activities included fieldwork and awareness initiatives aimed at promoting a culture of volunteering and improving the urban landscape.","The Ministry of Municipalities and Housing and SNB Group, in cooperation with municipal authorities, continue to support community initiatives related to the municipal sector, expand student volunteering opportunities, and strengthen partnerships that contribute to vibrant cities, improve the urban landscape, and enhance residents’ experiences in public facilities and spaces."]','أخبار السعودية','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/en/news/participation-17-municipal','https://momah.gov.sa/en/news/participation-17-municipal','','https://momah.gov.sa/en/news/participation-17-municipal','','','2026-10-01T05:58:00.000Z','Wed, 07 Oct 2026 11:56:31 GMT','2026-10-07T18:03:08.069Z','','','','With the Participation of 17 Municipal Authorities, the Ministry of Municipalities and Housing and SNB Expand the Impact of Student Volunteering Through “Cities of Urban Beauty”',NULL,NULL,'no_article_image_candidates','rejected','rejected','invalid',35,'455a6d48554c6ad1fc8657710bf9eec56538d2c3a95562fc27b1e83135768b62','dc05895cc3a5777e8701123f5aa740d1c282921150d25f9a1f1c4bacc407c2d9',NULL,'2026-10-07T18:03:08.069Z','2026-10-07T18:20:32.476Z','','',0,0,'international','عادي',38,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T18:14:52.442Z',200,1,0,'source_article_available','',NULL,NULL,'"1791374191"','Wed, 07 Oct 2026 11:56:31 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c704db67-984c-4793-b3ea-45a54a503c78','news-c704db67-984c-4793-b3ea-45a54a503c78','Ministry of Municipalities and Housing: More Than 200,000 Meters of Stormwater Drainage Networks Completed During the First Half of 2026','ministry of municipalities and housing more than 200 000 meters of stormwater drainage networks completed during the first half of 2026','This reflects the expanding scope of field works and the continued development of infrastructure in cities according to their needs and priorities. These works contribute to increasing cities’ capacity to drain rainwater and respond to rainfall events more efficiently.','["The Ministry of Municipalities and Housing completed more than 200,000 linear meters of stormwater drainage networks in a number of cities and regions across the Kingdom during the first half of 2026. These works aim to enhance cities’ readiness to deal with rainfall events, reduce water accumulation, support public safety and smooth traffic flow, protect assets and facilities, and strengthen the continuity of municipal services.","The total length of stormwater drainage networks completed during the period reached approximately 200.3 thousand linear meters, including more than 115,000 meters of main networks and around 85,000 meters of secondary networks, with an average exceeding one kilometer per day during the first half of the year. This reflects the expanding scope of field works and the continued development of infrastructure in cities according to their needs and priorities.","These works contribute to increasing cities’ capacity to drain rainwater and respond to rainfall events more efficiently. This, in turn, supports residents’ quality of life by enhancing road safety and traffic routes, reducing the impacts associated with water accumulation, protecting public facilities and municipal assets, and strengthening the ability of neighborhoods and facilities to continue their activities and services during rainy conditions.","The completed works included various components of the stormwater drainage and flood-risk mitigation system. More than 10,200 meters of box culverts and approximately 4,900 meters of stormwater and flood drainage channels were completed, in addition to the construction of 24 retaining walls. These projects support the integration of the system’s components and enhance its efficiency in managing rainwater and floods while protecting the areas and facilities within their scope.","The projects also involved the use of more than 87,500 cubic meters of reinforced concrete in the construction of box culverts, channels, and retaining walls, as part of the structural works required to develop the drainage system and strengthen its capacity to protect cities, residents, and facilities.","The Ministry, in coordination with municipalities and regional municipal authorities, is working to direct infrastructure projects based on the characteristics and urban and rainfall-related needs of each city. This approach ensures that resources are allocated to priority locations, existing assets are made more efficient, and drainage networks and their components are developed in line with urban growth and expansion.","These works form part of an integrated approach to developing municipal infrastructure that goes beyond constructing networks and facilities. The approach aims to build cities that are better prepared and more capable of responding to rainfall conditions, while supporting service continuity, protecting facilities and assets, improving the urban environment, and directly enhancing residents’ quality of life and experience in their cities.","The Ministry continues to implement and develop stormwater drainage and flood-risk mitigation projects across various regions of the Kingdom, strengthening urban resilience and preparedness while supporting a safer, more efficient, and more sustainable urban environment for residents."]','أخبار السعودية','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/en/news/ministry-municipalities-and-106','https://momah.gov.sa/en/news/ministry-municipalities-and-106','','https://momah.gov.sa/en/news/ministry-municipalities-and-106','','','2026-10-01T04:01:00.000Z','Wed, 07 Oct 2026 11:55:59 GMT','2026-10-07T18:03:08.123Z','','','','Ministry of Municipalities and Housing: More Than 200,000 Meters of Stormwater Drainage Networks Completed During the First Half of 2026',NULL,NULL,'no_article_image_candidates','rejected','rejected','invalid',35,'96b05d388bea9646a7818c1194bba779480828b983792e41f0e97f3bee1fe186','d84f86b459fccf084c87b825d80f77a7888361503ed90298fe5ef6aaa344e1ed',NULL,'2026-10-07T18:03:08.123Z','2026-10-07T18:20:32.476Z','','',0,0,'international','عادي',38,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T18:14:53.223Z',200,1,0,'source_article_available','',NULL,NULL,'"1791374159"','Wed, 07 Oct 2026 11:55:59 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4afe2976-2fdd-49f6-8c1a-0daac9251a47','news-4afe2976-2fdd-49f6-8c1a-0daac9251a47','The Minister of Municipalities and Housing Leads the Kingdom’s Delegation at the GCC Housing Ministers’ Meeting in Manama and Highlights Developments in the Housing and Financing System.','the minister of municipalities and housing leads the kingdom s delegation at the gcc housing ministers meeting in manama and highlights developments in the housing and financing system','These included following up on the implementation of the unified regulations for property owners in the GCC countries, approved by the Supreme Council.','["His Excellency the Minister of Municipalities and Housing, Mr. Majid bin Abdullah Al-Hogail, led the delegation of the Kingdom of Saudi Arabia at the 24th meeting of the Committee of Ministers Responsible for Housing Affairs in the Gulf Cooperation Council (GCC) countries, held today in Manama, with the participation of Their Excellencies and Highnesses, the Ministers of Housing of the GCC countries.","The meeting discussed a number of issues related to developing the housing sector and strengthening joint GCC cooperation, supporting the exchange of expertise and the development of housing policies and practices among the GCC countries. These included following up on the implementation of the unified regulations for property owners in the GCC countries, approved by the Supreme Council.","The Kingdom also undertook the preparation of the “Guidelines for Applying Sustainability Standards in Housing Projects,” which will enhance the exchange of practices and expertise in housing sustainability at the GCC level.","On the sidelines of the meeting, His Excellency the Minister participated in a ministerial dialogue session entitled “The Future of National Housing: Innovative Policies and Sustainable Solutions,” where he highlighted the transformations taking place in the housing sector amid changing family needs, diverse lifestyles, and varying needs across generations and geographic regions.","His Excellency explained that these transformations require a shift from traditional thinking about housing toward a more integrated system based on data and modern technologies, bringing together citizens, developers, financiers, regulators, and technology. This will help better understand demand and accelerate the development of more suitable housing solutions, policies, and products.","His Excellency emphasized that housing empowerment goes beyond simply providing a housing unit, particularly for the most vulnerable groups. He highlighted the importance of integrating support, financing, and housing with family needs and employment opportunities in a way that enhances beneficiaries’ ability to achieve stability and self-reliance.","He also highlighted the important role that the third sector can play within this system, given its closer connection to the most vulnerable groups and its ability to contribute to developing solutions that combine different forms of support and respond to families’ needs.","Regarding financing, His Excellency explained that the transformation of the housing model requires restructuring the financing chain, while strengthening the role of the financing sector in financing housing units and supporting construction, alongside developing financial instruments capable of providing long-term liquidity."]','أخبار السعودية','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/en/news/minister-municipalities-and-16','https://momah.gov.sa/en/news/minister-municipalities-and-16','','https://momah.gov.sa/en/news/minister-municipalities-and-16','','','2026-10-01T03:59:00.000Z','Wed, 07 Oct 2026 11:55:57 GMT','2026-10-07T18:03:09.544Z','','','','The Minister of Municipalities and Housing Leads the Kingdom’s Delegation at the GCC Housing Ministers’ Meeting in Manama and Highlights Developments in the Housing and Financing System.',NULL,NULL,'no_article_image_candidates','rejected','rejected','invalid',35,'c01a1bef3ffac75140887b46b74d134036aede500f3695b40ae8309871369ef0','a397b2bdd9f0cd897e3d5b815eae5a5b8678dd1f22771cbbdc8114e1b9e4fe3f',NULL,'2026-10-07T18:03:09.544Z','2026-10-07T18:20:32.476Z','','',0,0,'international','عادي',38,NULL,0,0,0,'',NULL,NULL,NULL,'["أخبار السعودية"]','["أخبار السعودية"]','needs_review','below_category_threshold','[{"category":"المناطق","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T18:14:53.747Z',200,1,0,'source_article_available','',NULL,NULL,'"1791374157"','Wed, 07 Oct 2026 11:55:57 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('316c3591-fea8-4673-a578-885ddf09cc52','news-316c3591-fea8-4673-a578-885ddf09cc52','المشرف التربوي لا تهدموا ما بدأه!','المشرف التربوي لا تهدموا ما بداه','العدالة في توزيع المشرفين التربويين على المدارس لا يمكن أن تختصر في عدد المدارس التي توزع على كل مشرف، لأن لكل مدرسة واقعاً مختلفاً لا يمكن اختزاله في جدول توزيع، وإنما هي بيئة تعليمية كاملة لها ظروفها واحتياجاتها وقيادتها ومعلموها وطلابها ومستوى نواتج تعلمها وطبيعة التحديات التي تواجهها، ولذلك فإن التوزيع العادل لا يبدأ بالسؤال عن عدد المدارس التي…','["العدالة في توزيع المشرفين التربويين على المدارس لا يمكن أن تختصر في عدد المدارس التي توزع على كل مشرف، لأن لكل مدرسة واقعاً مختلفاً لا يمكن اختزاله في جدول توزيع، وإنما هي بيئة تعليمية كاملة لها ظروفها واحتياجاتها وقيادتها ومعلموها وطلابها ومستوى نواتج تعلمها وطبيعة التحديات التي تواجهها، ولذلك فإن التوزيع العادل لا يبدأ بالسؤال عن عدد المدارس التي يحملها المشرف في جدوله، وإنما يبدأ بقراءة المدرسة نفسها وما تحتاج إليه ومن يستطيع أن يعمل معها ويصنع فيها فرقاً يمكن قياسه ومشاهدته بعد مدة من العمل الحقيقي.","وضع مشرف دعم في مدرسة لعام كامل ثم نقله منها في العام التالي لا يعني مجرد تغيير اسم باسم داخل جدول التوزيع، وإنما قد يعني قطع مشروع بدأ يتشكل وإيقاف علاقة مهنية احتاج بناؤها إلى أشهر وإهدار معرفة تراكمت لدى المشرف عن المدرسة ومعلميها وطلابها ومشكلاتها ونقاط قوتها وضعفها، فالمشرف الذي قضى عاماً يقرأ نتائج الطلاب ويحلل المؤشرات ويعمل مع المعلمين ويضع الخطط ويتابع تنفيذها ويصحح مسارها لا يعود بعد كل ذلك مجرد مشرف يمكن استبداله بسهولة، وإنما يصبح جزءاً من ذاكرة المدرسة التطويرية ويملك معرفة بتفاصيلها لا يمكن نقلها كاملة في تقرير أو جدول أو محضر.","وكم من مشرف دخل مدرسة فوجد أمامه واقعاً يحتاج إلى عمل طويل، ثم بدأ مع إدارتها ومعلميها في بناء مشروع للتحول الرقمي وتقليل الورق وتحسين المتابعة وربط الإجراءات بالمؤشرات وتغيير بعض الممارسات التي استقرت لسنوات، وبعد أن تحركت الفكرة وبدأ الناس يتقبلونها وظهرت ملامحها الأولى جاء قرار نقله إلى مدرسة أخرى قبل أن يرى المشروع نهايته، وفي مثل هذه الحالة لا يكون النقل مجرد تغيير في توزيع المشرفين، وإنما يصبح قطعاً لمسار تطويري بدأ ينضج وإهداراً لخبرة تراكمت داخل المدرسة وإرباكاً لمشروع احتاج وقتاً طويلاً حتى يقف على قدميه، فالتطوير الذي يتغير رجاله في منتصف الطريق يفقد جزءاً من تراكمه ويستهلك وقتاً جديداً في إعادة البناء، بينما كان الأولى أن يكتمل المسار وتُقاس نتائجه ويُعرف أثره قبل الانتقال إلى تجربة أخرى.","التطوير في التعليم لا يشبه تبديل المقاعد في غرفة اجتماعات، لأن بناء الممارسة الجديدة يحتاج إلى وقت والثقة تحتاج إلى وقت وتغيير الثقافة المدرسية يحتاج إلى وقت وقياس أثر الخطط على نواتج التعلم يحتاج إلى وقت، ولذلك فإن الاستقرار المهني للمشرف في المدرسة التي يقود فيها مشروعاً تطويرياً لا يصح النظر إليه بوصفه رغبة شخصية للمشرف أو تمسكاً بمدرسة بعينها، وإنما باعتباره أحد شروط نجاح المشروع نفسه ما دام العمل يسير وفق مؤشرات واضحة وما دام الأثر يتقدم وما دامت المدرسة تتحرك في الاتجاه الذي نبحث عنه.","والأغرب أن نطالب المشرف بأن يكون قائد تغيير وصانع مبادرة ومحلل نتائج ومتابعاً لنواتج التعلم ومسانداً للقيادة المدرسية، ثم لا يكون رأيه المهني حاضراً بالقدر الكافي عند اتخاذ بعض القرارات التي تمس طبيعة عمله والبيئة التي سيعمل فيها، فصناعة خطة تطويرية عميقة تحتاج إلى قراءة طبيعة القيادة المدرسية ودرجة استعدادها للتغيير وحجم التوافق المهني الذي يمكن أن يتشكل بينها وبين المشرف، لأن تحميل المشرف مسؤولية النتائج لا يستقيم إذا لم تكن خبرته ورؤيته المهنية جزءاً من قراءة البيئة التي نطالبه بصناعة تلك النتائج داخلها.","وأنا لا أدعو إلى أن يختار المشرف المدرسة التي يريدها وفق رغبته، لأن العمل المؤسسي لا يقوم على الرغبات الشخصية ولا يمكن أن تدار منظومة كبيرة بهذه الطريقة، وإنما أدعو إلى أن يصبح رأي المشرف المهني جزءاً من معادلة التوزيع إلى جانب حاجة المدرسة ومؤشراتها ونتائجها وطبيعة قيادتها والمشروعات القائمة فيها، لأن العقول الإدارية ليست نسخة واحدة والقيادات المدرسية ليست على درجة واحدة من المرونة والاستعداد للتغيير، والمشرف مهما كانت خبرته وقدرته سيجد صعوبة في صناعة تحول حقيقي إذا اصطدمت أفكاره كل صباح بعقل يرى التطوير تهديداً للمألوف ويرى المبادرة عبئاً إضافياً ويرى النجاح في بقاء الأشياء كما كانت.","ولا يمكن كذلك أن نتحدث عن تمكين المشرف التربوي ومكانته المهنية، ثم يشعر في بعض بيئات العمل أن مساحة صوته أضيق من حجم المسؤوليات التي وضعت على كتفيه وأن قدرته على التواصل والمبادرة داخل بعض القنوات المهنية مقيدة بإجراءات تجعله متلقياً أكثر من كونه شريكاً، لأن المشرف الذي نريده قوياً في المدرسة يجب أن يشعر بقيمته داخل منظومته أولاً وأن يعرف أن رأيه يسمع وأن فكرته تناقش وأن ملاحظته تقرأ وأن المبادرة التي يقدمها تجد مساحة عادلة للنظر فيها، فالمكانة المهنية لا تصنعها المسميات المكتوبة في القرارات وإنما تصنعها الثقة التي يشعر بها الإنسان عندما يدرك أن عقله جزء من صناعة القرار وليس مجرد أداة لتنفيذه.","ولعل من أكثر الممارسات التي تحتاج إلى مراجعة جادة مسألة التواصل بين الميدان والقيادات الإدارية، لأن المشرف الذي يكتب لمسؤول عن مشكلة تواجهه أو يرفع ملاحظة يعتقد أنها تؤثر في جودة العمل لا يبحث عن اهتمام شخصي ولا يريد أن تفتح له الأبواب لأنه أفضل من غيره، وإنما يريد أن يشعر بأن الرسالة المهنية التي خرجت من الميدان وصلت إلى من يملك القدرة على معالجتها وأنها وجدت من يقرأها ويفهم أسبابها ويبحث عن حلها، وعدم الرد أو تأخر التفاعل مهما كانت أسبابه قد يصنع لدى العامل في الميدان شعوراً بأن صوته لا يصل وأن المسافة بينه وبين القيادة أطول مما يجب."]','التعليم','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/na/2269475','https://www.okaz.com.sa/articles/na/2269475','','https://www.okaz.com.sa/articles/na/2269475','علي السعدوني','عسير','2026-10-05T18:32:00.000Z','Tue, 06 Oct 2026 10:05:24 GMT','2026-10-07T18:08:31.310Z','https://www.okaz.com.sa/okaz/uploads/authors/1833.jpg?v=1764063993','/api/media/316c3591-fea8-4673-a578-885ddf09cc52','/api/media/316c3591-fea8-4673-a578-885ddf09cc52?variant=thumbnail','المشرف التربوي لا تهدموا ما بدأه!',400,400,'valid','published','current','valid',40,'913960474cbf90bdff4bc3970bf63ebf7a43da2d0425bf85473a6a82ca04706c','11255e153f8b1d5a9baeb91048fdd7575b3a4552a9fffa19020496045a1622ea','محدّث','2026-10-07T18:08:31.310Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','عادي',57,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة التعليم مشروعات ضخمة وتحولات","الثقافة والفنون","التعليم والتدريب","التقنية والتحول الرقمي"]','["وزارة التعليم مشروعات ضخمة وتحولات","الثقافة والفنون","التعليم والتدريب","التقنية والتحول الرقمي"]','needs_review','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:17:55.115Z',304,2,0,'source_article_available','',NULL,NULL,'body:bb272a42530ba307e55841e7b3577117b6723aec957c84173626f3999e9495cb','Tue, 06 Oct 2026 10:05:24 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('40b6284e-0741-44d2-be9a-e2e92a38b240','news-40b6284e-0741-44d2-be9a-e2e92a38b240','33 عاماً في محراب التعليم.. تأملات في اليوم العالمي للمعلم','33 عاما في محراب التعليم تاملات في اليوم العالمي للمعلم','- أمس، احتفل العالم باليوم العالمي للمعلم، وهي مناسبة استثنائية تستحق الاستحضار والتأمل. - مع اليوم العالمي للمعلم، أستحضر ذكريات (33) عاماً قضيتها في سلك التعليم، قبل أن أودع أشرف وأنبل مهنة منذ أربعة أعوام.','["- أمس، احتفل العالم باليوم العالمي للمعلم، وهي مناسبة استثنائية تستحق الاستحضار والتأمل. جميلٌ جداً أن نُفرد في التقويم يوماً لنقف فيه إجلالاً وتكريماً لهذا الإنسان الذي يحمل شعلة المعرفة ويسهم في بناء الإنسان والعقل، ونستحضر من خلاله عظم الأدوار التي يؤديها المعلم في مسيرة المجتمعات.","- مع اليوم العالمي للمعلم، أستحضر ذكريات (33) عاماً قضيتها في سلك التعليم، قبل أن أودع أشرف وأنبل مهنة منذ أربعة أعوام.","- شاهدت وعرفت عن قرب ما تضعه الدولة من إمكانيات لتعليم وتطوير التعليم ومواكبة متغيرات العصر، والدورات التدريبية التي تقدمها للمعلمين، وعاصرت جيل والدي رحمة الله عليه الذي كان معلماً ومديراً لعدة مدارس في المدينة المنورة، وحرصه على أداء واجبة بكل تفانٍ وإخلاص، وأكرمت الدولة المعلم خير إكرام وفتحت له المجال في تحسين دخله المادي، وفتحت له الأبواب في العمل في الفترة المسائية في المدارس الليلية ومحو الأمية في الإجازة والأندية الصيفية والموسمية، وأكرمت المعلمين المتميزين من خلال عدة جوائز وأصبح المعلم الآن له جائزة باسمه في عدة مناطق في المملكة، كنت شاهداً على جيل روى وترك بصمة كبيرة في التعليم في المملكة من خلال عدة وزراء ومديري تعليم التقيت بهم خلال عملي الصحفي، اطّلعت عن قرب على حرصهم على أن يكون المعلم في أفضل حالاته.","- نعم المعلم تم تكريمه ويبقى الدور عليه في أداء رسالته بكل إخلاص وتفانٍ.","- لكن الوقوف عند هذه المناسبة يسحبنا تلقائياً إلى عقد مقارنة شجية بين الماضي والحاضر؛ فمعلم الأمس ليس كمعلم اليوم، والظروف والمعطيات اختلفت كلياً، تماماً كما تبدلت الفلسفة التعليمية والمناهج الدراسية بين زمنين.","- في الأمس القريب، كانت المسألة التعليمية تدور حول أصول متينة وأساسيات صلبة؛ كان التركيز ينصبّ أولاً وأخيراً على إتقان القراءة والكتابة، والإملاء والتعبير، وجودة الخط. كانت هذه المهارات هي الميزان الذي يُقيم بناءً عليه الطالب، والركن الأساسي الذي يُقاس به نجاح العملية التعليمية. كان القلم والورقة هما أداة المعرفة الوحيدة، وكان المعلم هو المصدر الأول والأنقى للمعلومة، يغرسها بحرص ويتابع نماءها خطوة بخطوة.","- اليوم، ودون أن ندري، أخذنا قطار التقنية إلى واقع تعليمي مختلف تماماً. اختلفت المناهج وتغيرت أدوات التقييم بعد أن صعدت الأجهزة الذكية والتقنيات الرقمية إلى المشهد، لتعيد تشكيل الفصول الدراسية وعلاقة الطالب بالمعرفة. لم يعد الطالب ينتظر المعلومة من المعلم بل بات يصل إليها بلمسة زر، واختلفت المهارات المطلوبة من التركيز التقليدي على الحفظ والإملاء والخط إلى التركيز على التفكير النقدي، والتعامل مع التدفق.","- هذا التحول الجذري فرض على المعلم أدواراً جديدة وأكثر تحدياً؛ فلم يعد مجرد «ملقن» للمادة، بل أصبح موجهاً، ومربياً، ومصفياً لهذا الكم الهائل من المعلومات التي تتدفق إلى أذهان الطلاب عبر الشاشات."]','التعليم','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/na/2269473','https://www.okaz.com.sa/articles/na/2269473','','https://www.okaz.com.sa/articles/na/2269473','سامي المغامسي','المدينة المنورة','2026-10-05T18:23:00.000Z','Tue, 06 Oct 2026 10:05:24 GMT','2026-10-07T18:08:32.425Z','https://www.okaz.com.sa/okaz/uploads/authors/1672.jpg?v=1757438909','/api/media/40b6284e-0741-44d2-be9a-e2e92a38b240','/api/media/40b6284e-0741-44d2-be9a-e2e92a38b240?variant=thumbnail','33 عاماً في محراب التعليم.. تأملات في اليوم العالمي للمعلم',399,400,'valid','published','current','valid',40,'554ff5cf79c3b6ede09f275e6b77b454283c26d567b83ab0e7c3d478701b8107','3a2c166baa6d6ffa105be434245bec521c357c69c30a5c65672993b7a12b65e9','محدّث','2026-10-07T18:08:32.425Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","التعليم والتدريب","التقنية والتحول الرقمي","المدينة المنورة"]','["الصحة العامة","التعليم والتدريب","التقنية والتحول الرقمي","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"المجتمع","score":1.5},{"category":"الثقافة","score":1.5}]','Active','2026-10-07T20:17:55.112Z',304,2,0,'source_article_available','',NULL,NULL,'body:2a950d9b2b2afd4d42b2cc80d0b86df67545a0731622023ebb5c809d3a394e50','Tue, 06 Oct 2026 10:05:24 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('954a8d3f-ffb0-40ef-b239-709a2af7b0d3','news-954a8d3f-ffb0-40ef-b239-709a2af7b0d3','«فجر اليمن».. شعب يستعيد وطنه','فجر اليمن شعب يستعيد وطنه','يتطلع أبناء اليمن إلى استعادة وطنهم من قبضة عصابة الكهوف الحوثية، وإلى إنهاء واقع تُفرض فيه إرادة السلاح على إرادة المجتمع. والأمل المعقود على «فجر اليمن» كبير، لكنه يضع على عاتق القيادات والقوى الوطنية مسؤولية أكبر..','["مع إعلان رئيس مجلس القيادة الرئاسي اليمني انطلاق عملية «فجر اليمن»، الخامس من أكتوبر 2026، بهدف استعادة مؤسسات الدولة وتحرير العاصمة صنعاء، يتجدد الأمل في أن يجد اليمن طريقه إلى الأمن والاستقرار، وأن تنتهي معاناة شعب أنهكته سنوات الصراع والانقسام.","يتطلع أبناء اليمن إلى استعادة وطنهم من قبضة عصابة الكهوف الحوثية، وإلى إنهاء واقع تُفرض فيه إرادة السلاح على إرادة المجتمع. ومن حق اليمنيين أن يعيشوا في وطن يحميهم، ويصون حرياتهم، ويمنح أبناءهم فرصة التعلم والعمل وبناء المستقبل. فاليمن، بتاريخه وحضارته وتنوعه، يستحق مؤسسات تخدم مواطنيه، وقانوناً يتساوى أمامه الجميع.","وفي اسم «فجر اليمن» وعد ينبغي أن يتحوّل إلى واقع يلمسه الناس في حياتهم اليومية، في طفل يعود إلى مدرسته آمناً، ومريض يجد العلاج، وموظف يتقاضى راتبه، وأسرة تستطيع تأمين قوتها، ونازح يعود إلى بيته. هذه هي الغاية التي تمنح استعادة الدولة معناها، وتجعل التضحيات طريقاً إلى حياة أفضل.","إن العزيمة على استعادة كل شبر من البلاد تحتاج إلى وحدة صف تضع مصلحة اليمن فوق الحسابات الحزبية والمناطقية والشخصية، والمطلوب اليوم الاتفاق على هدف واضح.. دولة ذات سيادة، ومؤسسات فاعلة، ومواطنة متساوية، ومستقبل يشارك اليمنيون جميعاً في صنعه.","ولا تكتمل استعادة الأرض إلا باستعادة ثقة الإنسان بالدولة. لذلك يجب أن ترافق أي تقدم إجراءات تحمي المدنيين، وتؤمّن الخدمات، وتمنع التجاوزات، وتفتح المجال أمام المساعدات. ويحتاج المواطن إلى أن يرى في مؤسسات الدولة سنداً له، وأن يجد باباً للإنصاف عندما يُظلم، وفرصة للعيش الكريم عندما تضيق به السبل.","كما أن إنهاء سلطة العصابة الحوثية ومسيريها ينبغي أن يمهد لعدالة تحاسب المسؤولين عن الانتهاكات على أساس الأدلة والقانون، فبناء السلام يحتاج إلى شجاعة في مواجهة الظلم، وحكمة في ترميم المجتمع، وضمانات تحول دون عودة الاستبداد تحت أي اسم.","لقد طال انتظار اليمنيين لفجر يحمل الطمأنينة إلى بيوتهم. والأمل المعقود على «فجر اليمن» كبير، لكنه يضع على عاتق القيادات والقوى الوطنية مسؤولية أكبر.. أن توّحد صفوفها، وتحفظ كرامة شعبها، وتحوّل هدف استعادة الوطن إلى مشروع لإعماره. عندها يصبح الفجر بداية عهد يستطيع فيه اليمني أن يعيش آمناً، ويعمل بكرامة، وينظر إلى الغد بثقة.","With the announcement by the President of the Yemeni Presidential Leadership Council of the launch of the \"Dawn of Yemen\" operation on October 5, 2026, aimed at restoring state institutions and liberating the capital, Sana''a, hope is renewed that Yemen will find its way to security and stability, and that the suffering of a people exhausted by years of conflict and division will come to an end."]','السياسة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/na/2269474','https://www.okaz.com.sa/articles/na/2269474','','https://www.okaz.com.sa/articles/na/2269474','خالد سيف','المدينة المنورة','2026-10-05T18:29:00.000Z','Mon, 05 Oct 2026 22:21:34 GMT','2026-10-07T18:08:32.634Z','https://www.okaz.com.sa/uploads/authors/1612.jpg','/api/media/954a8d3f-ffb0-40ef-b239-709a2af7b0d3','/api/media/954a8d3f-ffb0-40ef-b239-709a2af7b0d3?variant=thumbnail','«فجر اليمن».. شعب يستعيد وطنه',400,400,'valid','published','current','valid',52,'f3603a1f9a6fa51f97216ec9672bf317ec9f837465b193a6afba0c77a84f3229','5e85051628fc519acf0c67f7ec431eb73bd1ab1d2cccb76b4f8d6579ecf1b7f0','محدّث','2026-10-07T18:08:32.634Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','عادي',46,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس القيادة الرئاسي اليمني","مجلس القيادة الرئاسي اليمني انطلاق","الصحة العامة","اليمن"]','["رئيس مجلس القيادة الرئاسي اليمني","مجلس القيادة الرئاسي اليمني انطلاق","الصحة العامة"]','needs_review','below_category_threshold','[{"category":"السياسة","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:17:55.648Z',304,2,0,'source_article_available','',NULL,NULL,'body:9b605998c59bf670dd1767211ecef5dea83848ea642f107a53ab2875e4bbf676','Mon, 05 Oct 2026 22:21:34 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e77072b9-4792-44ce-87ce-7e40ed2ae9b2','news-e77072b9-4792-44ce-87ce-7e40ed2ae9b2','دونيس أم زلاتكو.. من يكسب التحدي الليلة؟','دونيس ام زلاتكو من يكسب التحدي الليله','النهائي المرتقب الذي سيقام هذا المساء بين المنتخبين الشقيقين السعودي والإماراتي، لتحديد هوية بطل خليجي 27، من الصعب ترشيح المنتخب الفائز، ومن منهما سيحقق اللقب، ولكن من الطبيعي جداً أن تتسابق الأمنيات، وتتحدث لغة التحدي بين المحبين من مشجعي كلا المنتخبين؛ فكلٌّ، على قول المثل، «يغني على ليلاه»، وليلاه، وإن غاصت في بحر الأماني وتجاوزت ما هو مكتوب على…','["- فمن حق اللاعب السعودي، ومعه كل من يسانده ويدعمه في المستطيل الأخضر وخارجه، أن يقول: أنا السعودي البطل.. ويا ويل من يتحداني، وشحذ الهمم مطلوب وواجب، وفي عالم كرة القدم لها «شنّة ورنّة» خاصة؛ أصوات تزلزل المدرجات، واليوم في استاد الجوهرة الموعد مع جماهير الأخضر، وهي في حالة شغف لمشاهدة خامس الانتصارات، ويكون الليلة «ختامها مسك»، بأداء مبهر ومستوى فني «يُذهل» الناظرين، وأهداف «تخزي العين»، وكأس البطولة هدية للجهد والعطاء والنهايات السعودية. وحينها يجلجل أرجاء الملعب صوت الفنان الراحل طلال مداح، بكلمات الأمير الراحل بدر بن عبدالمحسن، رحمهما الله، بأغنية «يا ناس الأخضر لا لعب.. بركان يتفجر غضب.. منصور يا أغلى شعار.. يا سعودي يا أفضل منتخب».","- أما الأبيض، المنتخب الإماراتي، فإذا قابل التحدي بتحدٍّ وباللغة نفسها وحدتها، فلا تلوموه؛ فمن حق جماهيره ولاعبيه أن يطلقوا عنان الأمنيات، وأن يعيشوا فرحة الانتصار قبل صافرة النهاية، وقد أعدّ المنتخب الإماراتي العدة والعتاد لهذه البطولة، ويريد أن يكمل اليوم لوحته الجميلة، من خلال مدرب «خبير» وفّر له مجموعة من اللاعبين «لا يُستهان» بهم، ومن المؤكد أنهم، وهم على مقربة من كأس يلمع أمام أعينهم، يقولون بلسان الحال: «نحن لها». وسيكون معهم جمهور إماراتي حضر خصيصاً لهذا النهائي، سيغني ويهتف بأعلى صوته: «أنا الإماراتي وأفتخر إني إماراتي».","- الليلة تُسدل الستارة على منافسات خليجي 27، بتتويج العريس البطل؛ إما السعودية وإما الإمارات، ولو ابتعدنا قليلاً عن لغة التحدي، التي لا مكان لها إلا في «الهواء الطلق»، فإنني أرى أن قوة المنتخبين متقاربة، وخير دليل على ذلك نتائجهما في هذه البطولة، وإن كان المنتخب الإماراتي يتفوق بخط هجوم ناري، فإنه يستحق الحذر منه، ووضع حد لخطورة نجومه الذين يجيدون اللعب الجماعي، وقادرون على خطف الفوز في لحظة، ومن الصعب بعدها على الأخضر السعودي استعادة التعادل سريعاً، ثم البحث عن الفوز.","- ومن وجهة نظري، فإن لغة التحدي الحقيقية ستظهر بصماتها من خلال فكر المدربين، المدرب «الخطير» دونيس، العارف بخفايا الأندية السعودية، الذي استطاع أن يصنع منظومة فريق نالت الإعجاب والتقدير في هذه البطولة حتى الآن، وحقق ما عجز عن تحقيقه مدربون لهم سمعتهم وخبراتهم الدولية التي لم يصل إليها. وفي المقابل، فإن فكر المدرب «العالمي» زلاتكو غني عن التعريف؛ بخبرته الكبيرة بالكرة الإماراتية والخليجية، ناهيك عن سجله وسمعته الدولية.","- خطوط المنتخب السعودي الثلاثة قدمت، بقيادة مدربه السيد «دونيس»، عملاً جباراً، وهي قادرة على أن تكمل ما بدأته، وتواصل هذا التألق الذي لم نشاهده منذ فترة طويلة، بعيداً كل البعد عن «الأنانية»، يلعب اللاعبون «على قلب رجل واحد»، ولا يرددون إلا شعاراً واحداً: الفوز وتحقيق البطولة، والظفر بلقب طال انتظاره.","نتمنى أن نشاهد مواجهة كروية تتسم بالروح الرياضية والأداء المتميز، بما يليق بسمعة البلدين والمنتخبين والنهائي الذي يجمعهما، وإن فاز الأخضر، وهذا ما أتوقعه وأتمناه، فلا غرابة، وهنّأناه.. وإن فاز الأبيض، فلا غرابة أيضاً، وباركنا له.. ففي النهاية، يبقى الأهم أن يكون الفوز للكرة الخليجية، والفرحة للجماهير، والاحترام عنواناً لنهائي يليق بالسعودية والإمارات.","The anticipated final that will take place this evening between the brotherly teams of Saudi Arabia and the UAE, to determine the identity of the champion of Gulf Cup 27, makes it difficult to predict the winning team and who will claim the title. However, it is very natural for wishes to race and for the language of challenge to be spoken among the fans of both teams; each, as the saying goes, \"sings for his own beloved.\" And while the beloved may dive into the sea of wishes and surpass what is written on paper, the end is governed by one truth, whose voice says: \"The field is for the brave.\"","- It is the right of the Saudi player, along with everyone who supports him on and off the field, to say: I am the champion Saudi... and woe to anyone who challenges me. Motivation is required and necessary, and in the world of football, it has a special \"sound and resonance\"; voices that shake the stands. Today, in Al-Jawhara Stadium, the fans of the Green team are eager to witness the fifth victory, and tonight will be \"the grand finale,\" with a stunning performance and a technical level that \"astonishes\" the onlookers, and goals that \"dazzle the eyes,\" with the championship cup as a gift for effort, giving, and Saudi achievements. At that moment, the voice of the late artist Talal Madah will echo throughout the stadium, with the words of the late prince Badr bin Abdul Mohsen, may they both rest in peace, in the song \"Oh people of the Green, no play... a volcano erupts with anger... Mansour, oh dearest emblem... oh Saudi, oh best team.\""]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/na/2269471','https://www.okaz.com.sa/articles/na/2269471','','https://www.okaz.com.sa/articles/na/2269471','عدنان جستنيه','الرياض','2026-10-05T18:20:00.000Z','Tue, 06 Oct 2026 10:05:24 GMT','2026-10-07T18:08:33.941Z','https://www.okaz.com.sa/okaz/uploads/authors/1828.jpg?v=1789038656','/api/media/e77072b9-4792-44ce-87ce-7e40ed2ae9b2','/api/media/e77072b9-4792-44ce-87ce-7e40ed2ae9b2?variant=thumbnail','دونيس أم زلاتكو.. من يكسب التحدي الليلة؟',400,400,'valid','published','current','valid',40,'bb540a0a304ea7e7a4bad8194a0bdaaed003bab4a829386eac2eba3b892f8fd8','405df8a2018e522fe224c7b75672a0fe2becf040450a21e7239ccb493dfaa2ca','محدّث','2026-10-07T18:08:33.941Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','عادي',52,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الرياض"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"الاقتصاد","score":0},{"category":"المجتمع","score":0}]','Active','2026-10-07T20:17:56.810Z',304,2,0,'source_article_available','',NULL,NULL,'body:770d67df4ba1a689541944bc173460c5a696f60da7fd3e25bddcf0847061c572','Tue, 06 Oct 2026 10:05:24 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6b591297-dd54-45d6-9811-ff9b14912cac','news-6b591297-dd54-45d6-9811-ff9b14912cac','‏خلف هذا المنتخب وطنٌ كامل','خلف هذا المنتخب وطن كامل','‏لهذا، حين يرتدي اللاعب هذا القميص، لا يدخل الملعب وحده.. اقتبست لكم هذا المقال الباذخ من حساب وزارة الرياضة عبر موقع (إكس)، ففيه من المشاعر ما يجعله رسالة شعب وقيمة وطن.','["ليس كل ما يُحمل على الصدر يُقرأ كما يُكتب..","‏وحين تقرأ في أعلى هذا الشعار اسم «السعودية»، يصبح لما تراه معنى يتجاوز كرة القدم؛ معنى صنعته أعوامٌ من الحضور، ولحظاتٌ من الفرح، وذكرياتٌ سكنت البيوت والمدرجات، حتى أصبح هذا الشعار جزءاً من ذاكرة وطن، وحكايةً تعرفها أجيال وترويها لأجيال.","‏طفلٌ يرتدي قميص الأخضر، ويقف أمام المرآة متخيّلاً يوماً يرتديه لاعباً..","‏ومشجعٌ يحسب الوقت حتى صافرة البداية..","‏وأبٌ يستعيد مباراةً مضت عليها أعوام، ويتحدث عنها وكأنها حدثت بالأمس..","‏وبيوتٌ ومدنٌ تتوحّد في اللحظة ذاتها، حين يدخل منتخب السعودية الملعب.","‏لهذا، حين يرتدي اللاعب هذا القميص، لا يدخل الملعب وحده..","‏بل يدخل ومعه ذاكرة من سبقوه، وهتاف من ينتظرونه، وحلم من سيأتون بعده."]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/na/2269472','https://www.okaz.com.sa/articles/na/2269472','','https://www.okaz.com.sa/articles/na/2269472','أحمد الشمراني','الرياض','2026-10-05T18:21:00.000Z','Tue, 06 Oct 2026 05:03:45 GMT','2026-10-07T18:08:33.949Z','https://www.okaz.com.sa/okaz/uploads/authors/216.jpg?v=1763061547','/api/media/6b591297-dd54-45d6-9811-ff9b14912cac','/api/media/6b591297-dd54-45d6-9811-ff9b14912cac?variant=thumbnail','‏خلف هذا المنتخب وطنٌ كامل',400,400,'valid','published','current','valid',41,'d54a9b4a7150c8f3f5ae10ac2245b333fd33f9b007573fc4c450f159b21a2780','978ea3cec54c8e03073b8ebc3da2e0427692db95da6d5d4616344a075cc7881c','محدّث','2026-10-07T18:08:33.949Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','عادي',56,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الرياضة عبر موقع إكس","الرياضة السعودية","الرياض"]','["وزارة الرياضة عبر موقع إكس","الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"الثقافة","score":0},{"category":"الاقتصاد","score":-5},{"category":"المجتمع","score":-5}]','Active','2026-10-07T20:17:56.815Z',304,2,0,'source_article_available','',NULL,NULL,'body:0ad1d20b80fd6aad56dd81083423581985f1d80d886a3bde175dc1f01d088355','Tue, 06 Oct 2026 05:03:45 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7eb55733-5b44-430b-a670-1dc59957ef93','news-7eb55733-5b44-430b-a670-1dc59957ef93','اليمن ليس قضية شرعية وتحالفاً فقط','اليمن ليس قضيه شرعيه وتحالفا فقط','وماذا تصنع مع الذين يهدّدون أمنها باستمرار بعد أن أحرقوا بلدانهم لصالح مشاريع تخريبية خارجية، وأجندات هدامة تريد استمرار الفوضى. المشروع الحوثي مشروع تخريبي بامتياز، والتخلص منه واجب حتمي ليس على الحكومة اليمنية والتحالف فقط، بل على كل المجتمع الدولي الذي يلهج بالسلام لليمن.','["عندما توصف المملكة بأنها دولة السلام والإنسانية فذلك ليس وصفاً مجازياً بل حقيقة تسندها وتؤكدها الأفعال، فهي دائماً تسعى من أجل الحوار والتفاهم وتغليب الدبلوماسية والحلول السياسية في كل المشاكل التي تعصف بمحيطها، وتسخّر كل قدراتها وإمكاناتها وثقة المجتمع الدولي بها من أجل تجنيب الشعوب ويلات الحروب، والوصول إلى توافقات سياسية تحقن الدماء، وتنتشل البلدان الغارقة في المشاكل بكل الوسائل المتاحة.","ولكن ماذا تفعل مملكة السلام مع الذين يرفضونه. وماذا تصنع مع الذين يهدّدون أمنها باستمرار بعد أن أحرقوا بلدانهم لصالح مشاريع تخريبية خارجية، وأجندات هدامة تريد استمرار الفوضى. ولعل أوضح مثال على هذه النماذج ما فعلته وتفعله المليشيا الحوثية باليمن، وما قدّمته وما زالت تقدّمه المملكة لإنقاذ اليمن.","لقد ساندت المملكة حكومة الشرعية اليمنية منذ بداية الانقلاب عليها، ومنعت الانهيار التام لكيان الدولة اليمنية، وأنشأت برنامجاً استثنائياً في إنسانيته لإعادة إعمار اليمن وتقديم كل الخدمات الأساسية التي يحتاجها الشعب اليمني. وفي الجانب السياسي دعمت كل فرص الحوار بين المكوّنات اليمنية، وأتاحت مناخاً ملائماً للتوافقات، لكن المليشيا الحوثية تؤكد مرةً تلو الأخرى أنها العنصر الذي يرفض السلام، ويريد المضي باليمن إلى أسوأ نهاية، بالإضافة إلى اعتداءاتها المستمرة على المملكة، وصولاً إلى الدرك الأسفل من الخسة باستهدافها المدينتين المقدستين، مكة المكرمة والمدينة المنورة.","الآن قررت الحكومة اليمنية ومعها الشعب اليمني إنهاء المشروع الحوثي واسترداد اليمن من طغمة جاهلة عميلة. ولأن مشروع استعادة اليمن إلى شرعيته تتوفر فيه كل الاشتراطات القانونية، وله غطاء دولي باعتراف العالم بحكومة الشرعية وتصنيف المليشيا الحوثية كجماعة إرهابية، فإن المملكة من خلال التحالف الدولي الذي ترأسه تقوم بعمل قانوني تماماً بدعمها للحكومة اليمنية في دحر الحوثيين واستعادة كامل الأرض اليمنية، وإنهاء مشروع الإرهاب والفوضى في اليمن الذي بدأ يهدّد المنطقة، ويتجاوزها إلى تهديد ممرات الملاحة وأمن الطاقة والاقتصاد العالمي. المشروع الحوثي مشروع تخريبي بامتياز، والتخلص منه واجب حتمي ليس على الحكومة اليمنية والتحالف فقط، بل على كل المجتمع الدولي الذي يلهج بالسلام لليمن.","When the Kingdom is described as a state of peace and humanity, it is not a metaphorical description but a reality supported and confirmed by actions. It always seeks dialogue and understanding, prioritizing diplomacy and political solutions to all the problems that beset its surroundings. It harnesses all its capabilities and resources, along with the trust of the international community, to spare peoples the horrors of war and to reach political agreements that save lives and rescue countries drowning in problems by all available means.","But what does the Kingdom of Peace do with those who reject it? What does it do with those who continually threaten its security after they have burned their countries for the sake of destructive external projects and destructive agendas that want to perpetuate chaos? Perhaps the clearest example of these models is what the Houthi militia has done and continues to do in Yemen, and what the Kingdom has provided and continues to provide to save Yemen.","The Kingdom has supported the Yemeni legitimate government since the beginning of the coup against it, preventing the complete collapse of the Yemeni state. It has established an exceptional humanitarian program for the reconstruction of Yemen and the provision of all essential services needed by the Yemeni people. Politically, it has supported all opportunities for dialogue among Yemeni components and created a suitable climate for agreements. However, the Houthi militia repeatedly confirms that it is the element that rejects peace and wants to lead Yemen to a worse end, in addition to its ongoing attacks on the Kingdom, reaching the lowest depths of wickedness by targeting the two holy cities, Mecca and Medina.","Now, the Yemeni government, along with the Yemeni people, has decided to end the Houthi project and reclaim Yemen from an ignorant, treacherous clique. Since the project to restore Yemen to its legitimacy meets all legal requirements and has international backing with the world recognizing the legitimate government and classifying the Houthi militia as a terrorist group, the Kingdom, through the international coalition it leads, is acting entirely legally in its support of the Yemeni government to defeat the Houthis and restore all Yemeni territory, thus ending the project of terrorism and chaos in Yemen, which has begun to threaten the region and extend beyond it to threaten shipping routes, energy security, and the global economy. The Houthi project is an exemplary destructive project, and eliminating it is an imperative duty not only for the Yemeni government and the coalition but for the entire international community that advocates for peace in Yemen."]','السياسة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2269469','https://www.okaz.com.sa/articles/authors/2269469','','https://www.okaz.com.sa/articles/authors/2269469','حمود أبو طالب','مكة المكرمة','2026-10-05T18:11:00.000Z','Tue, 06 Oct 2026 10:05:24 GMT','2026-10-07T18:08:35.041Z','https://www.okaz.com.sa/okaz/uploads/authors/225.jpg?v=1764231772','/api/media/7eb55733-5b44-430b-a670-1dc59957ef93','/api/media/7eb55733-5b44-430b-a670-1dc59957ef93?variant=thumbnail','اليمن ليس قضية شرعية وتحالفاً فقط',400,400,'valid','published','current','valid',44,'000672a7a2f6bde79743a4ee5a7ad4eb882d6e53a46759a204d2dfc5083bc41d','cf2841edba87f9bbe68faabe0b5685c33fe3b3b62b0ae24cdcea27ae2bb06a5f','محدّث','2026-10-07T18:08:35.041Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","الطقس والمناخ","الاقتصاد والأسواق","السياسة والعلاقات الدولية","مكة","اليمن","المدينة المنورة"]','["الطاقة والنفط","الطقس والمناخ","الاقتصاد والأسواق","السياسة والعلاقات الدولية","المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"السياسة","score":3},{"category":"المجتمع","score":3},{"category":"أخبار السعودية","score":1.5}]','Active','2026-10-07T20:17:55.644Z',304,2,0,'source_article_available','',NULL,NULL,'body:f20c508c9133075d7d6af5bb2d8aafbd1660aaafebda3df7e82e9cfb01cdc7ec','Tue, 06 Oct 2026 10:05:24 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('84ecb2ed-77fc-400f-8913-cc8228b9e20a','news-84ecb2ed-77fc-400f-8913-cc8228b9e20a','«وجهة للجميع» تخاطب الجيل الجديد.','وجهه للجميع تخاطب الجيل الجديد','هناك فارق بين أن يكبر المعرض، وأن تتسع فكرته، فالأولى يمكن تحقيقها بزيادة المساحة والأجنحة وعدد المشاركين، أما الثانية فتحتاج إلى فهم دقيق لما يجعل الناس يأتون، وما الذي يمكن أن يدفع شخصًا لا ينتمي أصلًا إلى جمهور المعرض التقليدي إلى أن يجد فيه ما يعنيه.','["هذه المسألة تبدو أكثر وضوحًا في معرض الصقور والصيد السعودي الدولي، فاسم المعرض يرسم منذ اللحظة الأولى هوية محددة ترتبط بالصقر والصيد، ومع ذلك فإن المشهد داخله أصبح أوسع بكثير من الدائرة التقليدية للصقارين والمهتمين بالصيد، وأصبح من الممكن أن يأتي الزائر من أجل الصقور، أو الرحلات والمغامرات، أو التراث والفنون، أو الأعمال والتجارة، أو أن يأتي مع أسرته من دون اهتمام مسبق بأيٍّ من ذلك، ثم يجد طريقه إلى التجربة.","وفي هذه الأثناء، يظهر أحد أصعب التحديات في صناعة الفعاليات، فكلما اتسعت دائرة الجمهور زاد خطر أن تفقد الفعالية شخصيتها، وكثير من الأحداث تقع في هذا الفخ حين تحاول إرضاء الجميع، فتضيف المزيد من الأنشطة والتجارب حتى يصبح من الصعب معرفة الفكرة التي تجمعها، وعندها قد تنجح في زيادة عدد الزوّار، لكنها تدفع مقابل ذلك جزءًا من وضوح هويتها.","المعادلة الأذكى هي أن يتسع الجمهور من دون أن يتحرك مركز الحدث، وهذا ما يجعل الصقر مهمًا في قراءة تطور المعرض، فهو لا يحتاج إلى أن يكون حاضرًا في كل تجربة حتى يبقى في قلب الهوية، لأن العالم المحيط به أوسع من الطائر نفسه، ويمتد إلى الصحراء والرحلات والصيد والحرف والأدوات والخيول والهجن والطبيعة والفنون والذاكرة الاجتماعية، وهي دوائر مختلفة يمكن أن تتسع كل واحدة منها لجمهور جديد من دون أن تنفصل عن القصة الأصلية.","بهذه الطريقة يصبح التنوع امتدادًا للهوية، لا منافسًا لها، ويستطيع المعرض أن يخاطب أكثر من اهتمام في الوقت نفسه، من دون أن يبدو كمجموعة فعاليات جُمعت في مكان واحد، فالزائر الذي يبدأ رحلته من السيارات وتجهيزات الرحلات قد يصل إلى جانب آخر من ثقافة الصيد، ومن يأتي بحثًا عن تجربة عائلية قد يخرج بمعرفة لم تكن لديه عن الصقارة، ومن تجذبه الحِرف أو التاريخ قد يجد نفسه أمام تفاصيل ثقافية مرتبطة بالموروث الذي يقوم عليه المعرض.","هذا التحوّل مهم في صناعة الفعاليات، لأن بناء الجمهور لا يعني دائمًا البحث عن أشخاص يشبهون الجمهور الحالي، وأحيانًا يكون النمو الحقيقي في اكتشاف دوائر جديدة يمكن أن ترتبط بالفكرة من مداخل مختلفة، وهنا تتحوّل الفعالية من موعد لفئة محددة إلى وجهة لها أكثر من باب، مع بقاء جميع الأبواب مؤدية إلى الهوية نفسها.","ولعل وصول معرض الصقور والصيد إلى أكثر من 700 ألف زائر في العام الماضي يطرح سؤالًا يتجاوز الرقم نفسه، فمن غير المنطقي النظر إلى هذا الحضور باعتباره امتدادًا لجمهور الصقارين وحدهم، والأقرب أنه يعكس اتساع قاعدة الاهتمام بالحدث، وقدرته على اجتذاب شرائح جاءت لأسباب مختلفة، وهو ما يفسر أيضًا لماذا يبدو شعار هذا العام «وجهة للجميع» معبّرًا عن مرحلة وصل إليها المعرض أكثر من كونه مجرد عبارة موسمية.","لكن الوصول إلى جمهور أوسع يفرض مسؤولية أكبر، لأن الزائر المتخصص يعرف ما يبحث عنه، بينما الزائر الجديد يحتاج إلى أن تُبنى له رحلة يستطيع من خلالها فهم المكان والعلاقة بين مكوّناته، لهذا، ربما يكون هذا أحد أكثر الدروس إثارة للاهتمام في تجربة معرض الصقور والصيد، فالتوسع الحقيقي لا يعني الابتعاد عن نقطة البداية، وإنما اكتشاف مقدار العالم الذي يمكن بناؤه حولها، وكلما كان المركز واضحًا أمكن للدوائر من حوله أن تتسع أكثر.","There is a difference between expanding the exhibition and broadening its concept. The former can be achieved by increasing the space, the wings, and the number of participants, while the latter requires a precise understanding of what draws people in and what might motivate someone who doesn''t originally belong to the traditional audience of the exhibition to find something meaningful within it."]','الثقافة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2269468','https://www.okaz.com.sa/articles/authors/2269468','','https://www.okaz.com.sa/articles/authors/2269468','هيلة المشوح','المدينة المنورة','2026-10-05T18:11:00.000Z','Tue, 06 Oct 2026 10:05:25 GMT','2026-10-07T18:08:35.244Z','https://www.okaz.com.sa/okaz/uploads/authors/255.jpg?v=1768301287','/api/media/84ecb2ed-77fc-400f-8913-cc8228b9e20a','/api/media/84ecb2ed-77fc-400f-8913-cc8228b9e20a?variant=thumbnail','«وجهة للجميع» تخاطب الجيل الجديد.',400,400,'valid','published','current','valid',46,'acb73f927c10ddf7d49400861a7dc207ab8277efc0935abf45c496a774cfeb35','d6877d6dfa20cc48cf8676835d68b73ce359a878fad445e182aa791631881b2d','محدّث','2026-10-07T18:08:35.244Z','2026-10-07T20:17:57.124Z','','',0,0,'saudi_region','عادي',31,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","الاقتصاد والأسواق"]','["الثقافة والفنون","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"الاقتصاد","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0}]','Active','2026-10-07T20:17:57.124Z',304,2,0,'source_article_available','',NULL,NULL,'body:65e65328a5efe1d96777ce805b32fc43946b8104d05c032baaa4f0154ea71f7e','Tue, 06 Oct 2026 10:05:25 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a205093b-9e89-4729-b8f4-8829ed470a35','news-a205093b-9e89-4729-b8f4-8829ed470a35','معرض الصقور.. بين التكرار والتحليق !','معرض الصقور بين التكرار والتحليق','لطالما مثّل معرض الصقور والصيد حدثاً مهماً، يترقبه عشاق الصحراء في المملكة ودول الخليج والمهتمون من مختلف أنحاء العالم، فليكن كما عهدناه سابقاً، محلقاً كالصقور !','["بدا معرض الصقور والصيد لبعض الزائرين هذا العام أقل جودة وجاذبية من المواسم السابقة، فالتكرار سمة المعرض في فعالياته وأقسامه، مما يوحي بنضوب أفكار التطوير وخلق الجاذبية، بينما أصبح القسم المخصص لشركات التخييم ومعدات الصحراء عنصر الجذب الأساسي بسبب عروض التخفيضات، وهذا مقبول، لو كان المعرض تجارياً بحتاً، لكنه اتخذ منذ انطلاقه هوية تجمع بين تعزيز الهوية الثقافية، مع منح العارضين والمهتمين بمعدات التخييم والنزهات البرية ساحة للتلاقي !","بالنسبة لي، كانت السنة قبل الماضية الأميز، مع وجود فعاليات ثقافية في التعريف بالصقور ومكانتها المستمرة في الإرث الثقافي السعودي، بينما كانت نسخة العام الماضي باهتة، مما يؤكد، مع ملاحظات ضعف نسخة هذا العام، وجود انخفاض مستمر أخشى معه أن يفقد المعرض جاذبيته في السنوات المقبلة !","أرجو أن يعود المعرض السنة المقبلة أكثر تألقاً وبأفكار جاذبة، تجعل من زيارته رغبة جامحة للمواطنين والمقيمين والسياح، وليس مجرد ساحة عروض للتخفيضات، فمن المهم أن يكون فعالية ثقافية، بالإضافة إلى أهدافه التجارية، لتعزيز ثقافة كل ما يتصل بالإرث الصحراوي لدى أجيال اليوم !","This year''s Falcon and Hunting Exhibition seemed to some visitors to be of lower quality and appeal than in previous seasons, as repetition has become a characteristic of the exhibition in its events and sections, suggesting a depletion of ideas for development and attraction. Meanwhile, the section dedicated to camping companies and desert equipment has become the main attraction due to discount offers. This is acceptable if the exhibition were purely commercial, but since its inception, it has taken on an identity that combines the enhancement of cultural identity with providing exhibitors and those interested in camping and outdoor equipment a space to meet!","For me, the year before last was the most distinguished, with cultural activities highlighting falcons and their ongoing significance in Saudi cultural heritage, while last year''s edition was dull, which, along with observations of this year''s weak edition, confirms a continuous decline that makes me fear the exhibition will lose its appeal in the coming years!","I hope the exhibition returns next year more brilliant and with attractive ideas, making it a strong desire for citizens, residents, and tourists to visit, rather than just a showcase for discounts. It is important for it to be a cultural event, in addition to its commercial goals, to enhance the culture surrounding the desert heritage for today''s generations!","In short... The Falcon and Hunting Exhibition has always represented an important event, eagerly awaited by desert enthusiasts in the Kingdom and Gulf countries, as well as interested individuals from around the world. Let it be as we have known it before, soaring like the falcons!"]','الثقافة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2269470','https://www.okaz.com.sa/articles/authors/2269470','','https://www.okaz.com.sa/articles/authors/2269470','خالد السليمان','','2026-10-05T18:11:00.000Z','Tue, 06 Oct 2026 10:05:25 GMT','2026-10-07T18:08:35.258Z','https://www.okaz.com.sa/okaz/uploads/authors/226.jpg?v=1763407164','/api/media/a205093b-9e89-4729-b8f4-8829ed470a35','/api/media/a205093b-9e89-4729-b8f4-8829ed470a35?variant=thumbnail','معرض الصقور.. بين التكرار والتحليق !',400,400,'valid','published','current','valid',40,'fd3859492b0e0f706ad2966cfdacaaecd0c620f01f6e7ffd0c8ba45eee6fef55','7371227ebb173f9f16d611ac37172765965d9058e1d6a9384b87653b7649f7b6','محدّث','2026-10-07T18:08:35.258Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_national','عادي',45,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون"]','["الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"الثقافة","score":1.5},{"category":"المناطق","score":0}]','Active','2026-10-07T20:17:57.120Z',304,2,0,'source_article_available','',NULL,NULL,'body:061c59b0ba25619d1de9f6b96114872eb85919f58d4baf5eb5f34b95d30062bb','Tue, 06 Oct 2026 10:05:25 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3acb784e-3251-4064-8091-14c95ce85c06','news-3acb784e-3251-4064-8091-14c95ce85c06','الوقوع في فخ باب المندب','الوقوع في فخ باب المندب','في هذه اللحظة، يسقط الوهم الجغرافي الذي تعايشت معه المليشيا طويلاً. الموقع الذي أراد الحوثي استخدامه لحماية مشروعه أصبح سبباً في تضييق خياراته.','["في هذه اللحظة، يسقط الوهم الجغرافي الذي تعايشت معه المليشيا طويلاً. فقد وقع الحوثي في فخ باب المندب. تعامل مع المضيق باعتباره ورقة ضغط يمكن استخدامها في الصراع اليمني، لكنه اكتشف أن أهميته الإستراتيجية تجعل كلفة العبث به أكبر من المكاسب.","باب المندب ليس ورقة يمنية داخلية. إنه ممر رئيسي للملاحة الدولية، وأي تهديد لحركة السفن فيه يتحول سريعاً إلى قضية تتجاوز حدود اليمن. وهذا تحديداً ما أخطأ الحوثي في تقديره. اعتقدت الجماعة أن تهديد الملاحة سيمنحها نفوذاً إضافياً. أرادت أن تقول للمنطقة والعالم إن تجاهلها غير ممكن. لكن النتيجة كانت عكسية.","هنا تكمن المفارقة. الموقع الذي أراد الحوثي استخدامه لحماية مشروعه أصبح سبباً في تضييق خياراته. فباب المندب يمنحه أهمية جغرافية، لكنه لا يمنحه حق التحكم بالممر. والمضايق ذات الأهمية الدولية لا تدار بمنطق الجماعات المسلحة، ولا تخضع لحسابات الصراع المحلي وحدها.","كما أن الحوثي بالغ في تقدير قيمة سيطرته على الساحل. وجوده قرب البحر يمنحه قدرة على التهديد والمناورة، لكنه في الوقت نفسه يجعل خطوط إمداده مكشوفة أمام أي عملية تستهدف نفوذه على الساحل الغربي.","الخطأ الأكبر كان في الاعتقاد أن أهمية باب المندب ستفرض على الآخرين التعامل مع الحوثي باعتباره قوة لا يمكن تجاوزها. العكس هو ما حدث. تهديد الملاحة وسّع دائرة الأطراف المعنية بالصراع، وجعل أمن البحر الأحمر جزءاً من الحسابات الإقليمية والدولية. غير أن المشكلة الجوهرية في هذه الإستراتيجية العبثية تكمن في أن الورقة نفسها مرشحة دائماً للانقلاب على حاملها؛ فالتاريخ لم يرحم يوماً من حاولوا ركوب أمواج السياسة بأشرعة ممزقة من الأوهام.","لذا، فإن عزل الحوثي عن الساحل الغربي لا يتعلق فقط بتأمين الملاحة. المسألة تتصل أيضاً بقدرته العسكرية والسياسية. فإبعاده عن البحر يقلل خياراته، ويضعف خطوط الإمداد، ويحد من قدرته على استخدام الساحل كورقة تفاوض.","وهنا يصبح باب المندب جزءاً من معادلة أوسع. فالسيطرة على الساحل تعني قدرة أكبر على الحركة والإمداد والضغط. وانتزاع هذه القدرة يعني دفع الحوثي إلى الاعتماد بصورة أكبر على مناطقه الداخلية، حيث تصبح خياراته أقل، واتصاله الخارجي أصعب.","وبالتالي، لا تنفصل معركة الساحل عن معركة صنعاء. كلما تراجع نفوذ الحوثي على البحر، زادت الضغوط على مواقعه في الداخل. وكلما تقلصت قدرته على تأمين الإمداد والمناورة، أصبحت السيطرة على صنعاء أكثر ارتباطاً بموازين القوة على الأرض."]','السياسة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/authors/2269439','https://www.okaz.com.sa/articles/authors/2269439','','https://www.okaz.com.sa/articles/authors/2269439','فارس بن حزام','','2026-10-05T13:03:00.000Z','Tue, 06 Oct 2026 10:05:25 GMT','2026-10-07T18:08:36.487Z','https://www.okaz.com.sa/okaz/uploads/authors/1918.jpg?v=1788191845','/api/media/3acb784e-3251-4064-8091-14c95ce85c06','/api/media/3acb784e-3251-4064-8091-14c95ce85c06?variant=thumbnail','الوقوع في فخ باب المندب',400,400,'valid','published','current','valid',41,'4b4cbc9aac50155c9156989be6696761a9c34fe89f7f55fcc091287adabb43a8','626af92631a7079581db7dc072dad8838e1ee0817dd019bd2474a02a3315a7c0','محدّث','2026-10-07T18:08:36.487Z','2026-10-07T20:25:22.793Z','','',0,0,'gulf_arab','منخفض الأولوية',22,NULL,0,0,0,'',NULL,NULL,NULL,'["السياسة والعلاقات الدولية","اليمن"]','["السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"المناطق","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:17:57.129Z',304,2,0,'source_article_available','',NULL,NULL,'body:d06a662466724629067d5ebf1b296e36134837d4276fbb887480073bf580201c','Tue, 06 Oct 2026 10:05:25 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('922d94ab-443c-46c2-9d18-cbf4748775f4','news-922d94ab-443c-46c2-9d18-cbf4748775f4','جابوها الأبطال','جابوها الابطال','في ليلةٍ ستبقى عالقة في ذاكرة الكرة السعودية، ارتفعت راية الوطن، وتعالت أصوات الفرح، وعانق نجوم منتخبنا الوطني الذهب بعد التتويج بكأس الخليج العربي في نسخته الـ27.','["مبروك لقيادتنا الرشيدة، ومبروك لشعب المملكة، ومبروك لكل سعودي عاش لحظة التتويج وردد بكل فخر: هذا الأخضر.. هذا منتخب الوطن.","لم تكن بطولة عابرة، ولم يكن طريقها مفروشًا بالورود، لكنها كانت بطولة كشفت معدن الرجال. واجه الأخضر التحديات والضغوط، وتعامل مع كل مباراة بروح مختلفة، حتى وصل إلى الموعد الكبير وهو يعرف أن النهائيات لا تعترف إلا بمن يقاتل حتى صافرة النهاية.","قاتلوا من أجل الشعار، ركضوا والتحموا وصبروا، ولم يبحث أحد منهم عن مجد شخصي، لأن الهدف كان أكبر من الجميع: أن تنتصر السعودية وأن يفرح الوطن.","عبارة تختصر الكثير من المشاعر، وتصف منتخبًا استعاد في اللحظات الحاسمة شخصيته وهيبته وروحه. فالبطولات لا تُحسم بالأسماء وحدها، وإنما بالشخصية والإصرار والقدرة على التعامل مع الضغط، وهذا ما ظهر على الأخضر عندما أصبحت البطولة على المحك.","ولا يمكن الحديث عن هذا الإنجاز دون إنصاف الجهاز الفني، الذي كان شريكًا رئيسيًا في الوصول إلى منصة التتويج والتعامل مع الإصابات والمتغيرات، والأهم اتخاذ القرار الصحيح في الوقت المناسب.","ولا ننسى الجماهير السعودية؛ الرقم الصعب والشريك الدائم في الإنجازات. حضرت، وساندت، وغنت للوطن، وحولت المدرجات إلى لوحة خضراء، ومنحت اللاعبين دفعة إضافية في اللحظات التي احتاج فيها الأخضر إلى صوت جماهيره.","وخلف هذا المشهد الرياضي الجميل تقف رؤية وطن جعلت الرياضة جزءًا من مشروع سعودي كبير، ورفعت سقف الطموحات، حتى أصبح الرياضي السعودي يدخل المنافسات وهو يبحث عن الإنجاز، لا عن مجرد المشاركة.","الرياضة السعودية تعيش مرحلة تاريخية، وما نشاهده من دعم واهتمام وتطور يؤكد أن القادم يجب أن يكون أكبر، وأن كل بطولة تتحقق ينبغي أن تكون بداية لطموح جديد."]','الرياضة','','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/articles/people-voice/2269741','https://www.okaz.com.sa/articles/people-voice/2269741','','https://www.okaz.com.sa/articles/people-voice/2269741','ماجد السلمي','الرياض','2026-10-07T08:40:00.000Z','Wed, 07 Oct 2026 18:08:35 GMT','2026-10-07T18:08:37.514Z','https://www.okaz.com.sa/okaz/uploads/images/2026/10/07/2777023.webp','/api/media/922d94ab-443c-46c2-9d18-cbf4748775f4','/api/media/922d94ab-443c-46c2-9d18-cbf4748775f4?variant=thumbnail','جابوها الأبطال',1206,1429,'valid','published','current','valid',46,'2e64e3cebcde3a589730026c3b813dc5a4df586beaa381a76c4ea97c4e8438d2','8e072477050e82cc69e7a55ca314e19df18a606b0141475ee56014a52d926ee6','محدّث','2026-10-07T18:08:37.514Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','مهم',70,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الاقتصاد والأسواق","الرياض","الخليج العربي"]','["الرياضة السعودية","الاقتصاد والأسواق","الخليج العربي"]','needs_review','below_category_threshold','[{"category":"الثقافة","score":1.5},{"category":"المناطق","score":-3.5},{"category":"الاقتصاد","score":-3.5}]','Temporarily Unreachable','2026-10-07T20:17:44.061Z',NULL,2,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('da7b22d9-d237-4b62-bc2e-561b3e1e9927','news-da7b22d9-d237-4b62-bc2e-561b3e1e9927','رياضي / تحت رعاية خادم الحرمين الشريفين ونيابة عنه.. نائب أمير منطقة مكة المكرمة يتوّج المنتخب السعودي بكأس "خليجي الديار العربية 27" لكرة القدم','رياضي تحت رعايه خادم الحرمين الشريفين ونيابه عنه نائب امير منطقه مكه المكرمه يتوج المنتخب السعودي بكاس خليجي الديار العربيه 27 لكره القدم','جدة 26 ربيع الآخر 1448 هـ الموافق 07 أكتوبر 2026 م واس تحت رعاية خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، ونيابة عنه -أيّده الله-، شهد صاحب السمو الملكي الأمير سعود بن مشعل بن عبدالعزيز نائب أمير منطقة مكة المكرمة، المباراة النهائية لبطولة كأس الخليج العربي لكرة القدم في نسختها السابعة والعشرين "خليجي الديار العربية 27"، وتوَّج سموّه…','["جدة 26 ربيع الآخر 1448 هـ الموافق 07 أكتوبر 2026 م واس تحت رعاية خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، ونيابة عنه -أيّده الله-، شهد صاحب السمو الملكي الأمير سعود بن مشعل بن عبدالعزيز نائب أمير منطقة مكة المكرمة، المباراة النهائية لبطولة كأس الخليج العربي لكرة القدم في نسختها السابعة والعشرين \"خليجي الديار العربية 27\"، وتوَّج سموّه المنتخب السعودي بكأس البطولة، بعد فوزه على شقيقه المنتخب الإماراتي بنتيجة (2 - 0)، في المباراة التي أُقيمت بينهما اليوم الثلاثاء على ملعب الإنماء بمدينة الملك عبدالله الرياضية في جدة.","حضر المباراة، صاحب السمو الملكي الأمير عبدالعزيز بن تركي بن فيصل بن عبدالعزيز وزير الرياضة، ورئيس الاتحاد الدولي لكرة القدم جياني إنفانتينو، وسعادة الشيخ حمد بن خليفة بن أحمد آل ثاني رئيس الاتحاد الخليجي لكرة القدم، وصاحب السمو الملكي الأمير سعود بن عبدالله بن عبدالعزيز، وصاحب السمو الملكي الأمير سعود بن تركي بن فيصل بن عبدالعزيز، وصاحب السمو الأمير سعود بن عبدالله بن جلوي محافظ جدة، وصاحب السمو الملكي الأمير فواز بن سلطان بن عبدالعزيز محافظ الطائف، وصاحب السمو الأمير نواف بن محمد، وصاحب السمو الأمير سعود بن نواف بن محمد.","كما حضرها، معالي نائب وزير الرياضة الأستاذ بدر بن عبدالرحمن القاضي، ورئيس مجلس إدارة الاتحاد السعودي لكرة القدم بدر بن سليمان الرزيزاء، ورؤساء وممثلو الاتحادات الرياضية بدول الخليج العربي.","وبهذه المناسبة، رفع صاحب السمو الملكي الأمير عبدالعزيز بن تركي بن فيصل وزير الرياضة رئيس اللجنة الأولمبية والبارالمبية السعودية، خالص الشكر وعظيم الامتنان لخادم الحرمين الشريفين -أيّده الله-، على رعايته الكريمة للبطولة.","وقال سموّه في تصريح صحفي: \"نفخر برعاية مولاي خادم الحرمين الشريفين -أيّده الله- لهذه البطولة؛ إذ يجسّد هذا الاهتمام الكريم من القيادة الرشيدة المكانة التي تحظى بها بطولة كأس الخليج العربي، وما تمثله من قيمة رياضية وتاريخية راسخة لدى الأشقاء في دول الخليج الذين تجمعهم روابط الأخوة والمحبة\".","وأضاف: \"أتقدم بخالص التهاني والتبريكات لقيادتنا الرشيدة -حفظها الله- على فوز منتخبنا بهذه البطولة الغالية؛ التي تمثل أهمية كبرى لدينا كخليجيين، كما أثمن لأخي سمو نائب أمير منطقة مكة المكرمة حضوره وتتويجه للمنتخب الفائز باللقب الغالي، وأهنئ جماهيرنا الوفية، التي كان لها الدور الأكبر في مسيرة الأخضر في هذه البطولة، وكانت خير داعمٍ لصقورنا في تحقيق هذا اللقب الغالي، وكل الشكر لجميع المنتخبات على مشاركتها في هذا التجمع الرياضي الخليجي، وعلى ما قدمته من مستويات مميزة وتنافس رياضي شريف، ونتمنى لها التوفيق في البطولات المقبلة -بإذن الله-\".","واختتم سموّه تصريحه قائلًا: \"أود أن أشكر بكثير من الامتنان والتقدير الجهات واللجان المنظمة كافة، وجميع العاملين والمتطوعين، على ما بذلوه من جهود كبيرة منذ مراحل الإعداد وحتى ختام البطولة، وما أظهروه من تكامل وتعاون وحرص أسهم في نجاح هذه النسخة وخروجها بالصورة التي تليق بمكانة كأس الخليج وقيمتها الكبيرة لدى أبناء المنطقة\".","يذكر أن منافسات \"خليجي الديار العربية 27\"، استضافتها مدينة جدة خلال الفترة من 23 سبتمبر حتى 6 أكتوبر 2026م، بمشاركة ثمانية منتخبات، شهدت خوض 15 مباراة على ملعبي الإنماء بمدينة الملك عبدالله الرياضية، ومدينة الأمير عبدالله الفيصل الرياضية، في أول استضافة لمدينة جدة للبطولة في تاريخها. // انتهى // 00:35 ت مـ 0019"]','الرياضة','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2695028?type=news&uuid=N2695028','https://spa.gov.sa/ar/N2695028?type=news&uuid=N2695028','N2695028','N2695028','','الرياض','2026-10-06T18:35:00.000Z',NULL,'2026-10-07T18:08:39.814Z','https://portalcdn.spa.gov.sa/backend/original/202610/F10967449.jpeg','/api/media/da7b22d9-d237-4b62-bc2e-561b3e1e9927','/api/media/da7b22d9-d237-4b62-bc2e-561b3e1e9927?variant=thumbnail','رياضي / تحت رعاية خادم الحرمين الشريفين ونيابة عنه.. نائب أمير منطقة مكة المكرمة يتوّج المنتخب السعودي بكأس "خليجي الديار العربية 27" لكرة القدم',1600,1066,'valid','published','current','valid',99,'a23cfeea72cf943a7eb170bdd3002b9e23919f08c2dcaf52f300d620078f9e7c','c07c3243e1eb3d9c45c8c46dd64bc92dbc3541560ecb18aa31e9daf453dfe05e',NULL,'2026-10-07T18:08:39.814Z','2026-10-07T20:17:53.378Z','','',0,0,'saudi_region','عادي',61,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس إدارة الاتحاد السعودي لكرة","رئيس الاتحاد الخليجي لكرة القدم","خادم الحرمين الشريفين ونيابة عنه","وزير الرياضة ورئيس الاتحاد الدولي","الثقافة والفنون","الرياضة السعودية","الاقتصاد والأسواق","مكة"]','["مجلس إدارة الاتحاد السعودي لكرة","رئيس الاتحاد الخليجي لكرة القدم","خادم الحرمين الشريفين ونيابة عنه","وزير الرياضة ورئيس الاتحاد الدولي","الثقافة والفنون","الرياضة السعودية"]','classified','','[{"category":"أخبار السعودية","score":12.5},{"category":"الاقتصاد","score":-3.5},{"category":"المناطق","score":-6}]','Active','2026-10-07T20:17:53.378Z',200,2,0,'source_article_available','',NULL,NULL,'body:8f638c883dcd4e739be4d87532b356bd5c4ef385030d1df503b4767df2c48986','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a353d8f0-5f4c-4473-9638-006745c3fc24','news-a353d8f0-5f4c-4473-9638-006745c3fc24','اقتصادي / مزارعو الباحة يبدؤون جني ثمار أكثر من نصف مليون شجرة رمان بإنتاج يتجاوز (10) آلاف طن','اقتصادي مزارعو الباحه يبدؤون جني ثمار اكثر من نصف مليون شجره رمان بانتاج يتجاوز 10 الاف طن','وأوضح مدير عام فرع وزارة البيئة والمياه والزراعة بمنطقة الباحة المهندس فهد بن مفتاح الزهراني، أن المنطقة تضم نحو (750) ألف شجرة رمان، بإنتاج سنوي يقدّر بنحو (10) آلاف طن، مشيرًا إلى الجهود المبذولة لتطوير زراعة الرمان ورفع كفاءة إنتاجه، وتعزيز العائد الاقتصادي للمزارعين.','["الباحة 26 ربيع الآخر 1448 هـ الموافق 07 أكتوبر 2026 م واس بدأ مزارعو منطقة الباحة جني محصول الرمان مع دخول موسم الحصاد، بالتزامن مع قرب انطلاق مهرجان الرمان في نسخته الخامسة عشرة، الذي يجمع المزارعين والمنتجين والمهتمين بأحد أبرز المحاصيل الزراعية التي تشتهر بها المنطقة، ويشكل نافذة لتسويق الإنتاج المحلي والتعريف بجودته وتنوعه.","وتشهد مزارع الرمان في عدد من محافظات المنطقة خلال هذه الفترة حركة متزايدة مع بدء قطف الثمار وتجهيزها وفرزها استعدادًا لطرحها في الأسواق والمشاركة في المهرجان، وسط اهتمام المزارعين بالمحافظة على جودة المحصول والاستفادة من موسم الإنتاج في تعزيز العائد الاقتصادي لمزارعهم.","وأشار إلى أن دعم زراعة الرمان في المنطقة يشمل تطوير سلسلة الإنتاج، ودعم المزارعين والتوسع في زراعة الأشجار، إلى جانب وجود جمعية متخصصة في الرمان، ومشتل تابع لها على مساحة تقدر بنحو (7) آلاف متر مربع، خُصص لإنتاج شتلات الرمان وتوفيرها للمزارعين، بما يدعم استدامة زراعة هذا المحصول وزيادة إنتاجه.","ونوه المزارع طارق بن عواض الزهراني، الذي تضم مزرعته أكثر من (6000) شجرة رمان، أن موسم الجني يمثل ثمرة أشهر من العناية بالأشجار ومتابعتها، بدءًا من أعمال الري والتقليم والخدمة الزراعية، وصولًا إلى نضج الثمار وقطفها وفرزها وتجهيزها للتسويق.","وقال: \"إن زراعة الرمان تعد من الزراعات التي ارتبط بها مزارعو المنطقة منذ سنوات طويلة، لما تتمتع به الباحة من مقومات زراعية ملائمة، مبينًا أن جودة الثمار تسهم في زيادة الإقبال عليها خلال الموسم، وأن المهرجان يمثل فرصة للمزارعين لعرض إنتاجهم والوصول إلى شريحة أوسع من المستهلكين، إلى جانب تبادل الخبرات بين المزارعين والمهتمين بزراعة الرمان\".","وأضاف: \"إن عملية جني الثمار تتطلب عناية في اختيار الثمار المكتملة النضج والتعامل معها أثناء القطف والنقل والفرز، للمحافظة على جودتها حتى وصولها إلى المستهلك\"، مشيرًا إلى أن المزارعين يحرصون مع بداية كل موسم على الاستفادة من الخبرات المتراكمة في تحسين الإنتاج ورفع مستوى جودة المحصول.","ويجسد موسم الرمان في الباحة جانبًا من التنوع الزراعي الذي تتميز به المنطقة، فيما تتجه ثمار الموسم من المزارع إلى منافذ البيع، حاملةً معها نتاج عمل المزارعين على مدار العام، ومؤكدةً حضور الرمان بوصفه أحد المنتجات الزراعية المرتبطة بهوية المنطقة ومواسمها الزراعية. // انتهى // 14:46 ت مـ 0168"]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2695471?type=news&uuid=N2695471','https://spa.gov.sa/ar/N2695471?type=news&uuid=N2695471','N2695471','N2695471','','المنطقة الشرقية','2026-10-07T08:46:00.000Z','2026-10-07T11:46:00.000Z','2026-10-07T18:08:39.832Z','https://portalcdn.spa.gov.sa/backend/original/202610/F10970927.jpeg','/api/media/a353d8f0-5f4c-4473-9638-006745c3fc24','/api/media/a353d8f0-5f4c-4473-9638-006745c3fc24?variant=thumbnail','اقتصادي / مزارعو الباحة يبدؤون جني ثمار أكثر من نصف مليون شجرة رمان بإنتاج يتجاوز (10) آلاف طن',1600,1066,'valid','published','current','valid',86,'e4200514dec5822c413e5bcfb3413746ff7febe121baaeffc1f4393d1b5756c3','77c5f3ccba5f3458fea809919379f2791e45c6ad113aa2f7a5c07f8d1885e8e5','محدّث','2026-10-07T18:08:39.832Z','2026-10-07T20:17:44.057Z','','',0,0,'saudi_region','مهم',78,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة البيئة والمياه والزراعة بمنطقة","الاقتصاد والأسواق","الباحة"]','["وزارة البيئة والمياه والزراعة بمنطقة","الاقتصاد والأسواق"]','classified','','[{"category":"الاقتصاد","score":3},{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0}]','Temporarily Unreachable','2026-10-07T20:17:44.057Z',NULL,2,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ecbb3c74-8ed0-4f61-b13b-cc36a2923953','news-ecbb3c74-8ed0-4f61-b13b-cc36a2923953','بيئي / 10 آلاف متر مربع من المسطحات الخضراء تعزز المشهد الحضري بالمنطقة المركزية المحيطة بالمسجد النبوي','بيئي 10 الاف متر مربع من المسطحات الخضراء تعزز المشهد الحضري بالمنطقه المركزيه المحيطه بالمسجد النبوي','المدينة المنورة 26 ربيع الآخر 1448 هـ الموافق 07 أكتوبر 2026 م واس أضفت أعمال التشجير وتنوّع النباتات وتناغمها مع المسطحات الخضراء والأحواض الزراعية في المنطقة المركزية المحيطة بالمسجد النبوي بعدًا جماليًا وبيئيًا، يعزز جودة المشهد الحضري في منطقة تشهد كثافة في حركة الزوار والمصلين.','["وأوضحت أمانة المدينة المنورة أن أعمال التشجير والزراعة التي تنفذها في المنطقة المركزية تمثّل أحد المكونات الرئيسة للعناية بالمشهد الحضري، إذ شملت زراعة (5444) شجرة في المواقع، والشوارع، والطرق، فيما تمتد المسطحات الخضراء على مساحة تبلغ نحو (9930) مترًا مربعًا، ضمن (1385) حوضًا زراعيًا؛ لتمنح المنطقة حضورًا أخضر متصلًا يتكامل مع عناصرها العمرانية والخدمية.","وأضافت أن جهود تحسين المشهد الحضري للمنطقة المركزية تتضمن العناية بالمكونات النباتية من خلال تنفيذ أعمال الري، والصيانة، وتقليم الأشجار، والنظافة، والمتابعة الدورية؛ بما يضمن استدامة المظهر الجمالي للأشجار، والأحواض الزراعية، ويحافظ على جاهزية المواقع المحيطة بالمسجد النبوي على مدار العام.","وأفادت الأمانة أن الأشجار والأحواض الزراعية المنفّذة على امتداد مسارات الحركة في المنطقة المركزية أسهمت في إبراز المشهد الحضري من خلال المزج بين العناصر الجمالية والامتداد العمراني، مما يعزّز جمالية المواقع المفتوحة، وإيجاد بيئة حضرية أكثر ملاءمة للزوار والمصلين على امتداد الطرق والشوارع المؤدية إلى المسجد النبوي، وصولًا إلى أماكن وقوف الحافلات، والمركبات.","وتأتي هذه الجهود ضمن منظومة أوسع للعناية بالمدينة المنورة ومرافقها ومشهدها الحضري، عبر توظيف العناصر النباتية في المواقع الحيوية، وتحسين البيئة البصرية للشوارع والطرق، وتعزيز حضور المساحات الخضراء، بما ينسجم مع مستهدفات تحسين جودة الحياة، ويرتقي بتجربة سكان المدينة وزائريها. // انتهى // 15:09 ت مـ 0181"]','المجتمع','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2695500?type=news&uuid=N2695500','https://spa.gov.sa/ar/N2695500?type=news&uuid=N2695500','N2695500','N2695500','','المدينة المنورة','2026-10-07T09:09:00.000Z','2026-08-03T05:27:00.000Z','2026-10-07T18:08:40.378Z','https://portalcdn.spa.gov.sa/backend/original/202610/F10971081.jpg','/api/media/ecbb3c74-8ed0-4f61-b13b-cc36a2923953','/api/media/ecbb3c74-8ed0-4f61-b13b-cc36a2923953?variant=thumbnail','بيئي / 10 آلاف متر مربع من المسطحات الخضراء تعزز المشهد الحضري بالمنطقة المركزية المحيطة بالمسجد النبوي',1600,900,'valid','published','current','valid',95,'5bdc085138cb33eaa17a983bad96742188354173b6c31b555053b00732923bd5','befa53d36abf0659d45a5abf7d8eef741ed062d188bf2c5db761d0ce0abfb863','محدّث','2026-10-07T18:08:40.378Z','2026-10-07T20:17:44.050Z','','',0,0,'saudi_region','مهم',65,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية","الاقتصاد والأسواق","المدينة المنورة"]','["الرياضة السعودية","الاقتصاد والأسواق","المدينة المنورة"]','classified','','[{"category":"المناطق","score":1.5},{"category":"الاقتصاد","score":1.5},{"category":"الرياضة","score":1.5}]','Temporarily Unreachable','2026-10-07T20:17:44.050Z',NULL,2,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7459ddec-ebec-4c7a-bf3f-ba8e37fc46cd','news-7459ddec-ebec-4c7a-bf3f-ba8e37fc46cd','ثقافي / العمارة الحجرية في الباحة تجسّد تناغم الإنسان مع بيئته','ثقافي العماره الحجريه في الباحه تجسد تناغم الانسان مع بيئته','الباحة 25 ربيع الآخر 1448 هـ الموافق 06 أكتوبر 2026 م واس تزامنًا مع الاحتفاء باليوم العالمي للعمارة، الذي يوافق الاثنين الأول من أكتوبر من كل عام، تبرز العمارة الحجرية في منطقة الباحة كشاهدٍ حي على عبقرية البناء التي ابتكرها الأهالي قديمًا؛ تكيفًا مع تضاريس المنطقة القاسية ومناخها المتقلب.','["وتتجلى ملامح هذا النمط الفريد في القرى التراثية المترامية على المرتفعات وسفوح الجبال؛ حيث شُيدت المنازل من الحجارة الصلبة والطين، وتراصّت في نسيج عمراني متلاحم تتخلله أزقة وممرات ضيقة.","وقد تنوعت تصاميم البيوت وفقًا لطبيعة التضاريس، إذ تألف بعضها من طابقين؛ خُصص الأرضي منهما لإيواء المواشي وتخزين الأعلاف، في حين استُخدمت الطوابق العليا للسكن.","واعتمد البناؤون في تشييد الجدران على الحجارة المحلية، بينما استُخدمت الأخشاب في الأسقف والأعمدة والأبواب، في توظيفٍ ذكي للموارد المتاحة بما يتلاءم مع البيئة المحيطة.","وتزخر قرى المنطقة بحصونٍ ومساجد ومساكن تراثية، تتقدمها قريتا \"ذي عين\" و\"الأطاولة\"، اللتان لا تزالان تحتفظان بملامح هذا الإرث العمراني الأصيل.","ولا تقتصر أهمية هذه المباني على قيمتها التراثية والسياحية فحسب، بل تُعد وثيقةً تاريخية تروي أنماط العيش وطبيعة التواصل الاجتماعي في المنطقة.","وتتواصل الجهود حاليًا للحفاظ على هذه القرى والمواقع التراثية وتأهيلها، بما يضمن صون إرث الباحة العمراني وإتاحته للزوار لاستكشاف عراقة المكان. // انتهى // 20:36 ت مـ 0266"]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2694774?type=news&uuid=N2694774','https://spa.gov.sa/ar/N2694774?type=news&uuid=N2694774','N2694774','N2694774','','الباحة','2026-10-06T14:36:00.000Z','2026-06-25T05:03:00.000Z','2026-10-07T18:08:43.974Z','https://portalcdn.spa.gov.sa/backend/original/202610/F10965612.jpeg','/api/media/7459ddec-ebec-4c7a-bf3f-ba8e37fc46cd','/api/media/7459ddec-ebec-4c7a-bf3f-ba8e37fc46cd?variant=thumbnail','ثقافي / العمارة الحجرية في الباحة تجسّد تناغم الإنسان مع بيئته',1600,1066,'valid','published','current','valid',47,'11c928edda35fb17d09e45aa8eb7c7f5851ee1ddebb191b87ff03fe3c8703b44','35da3b19a7b2bd73b014e5d40807d3cbdc3ddcab07bec2e2dc642f274f3f84fa','محدّث','2026-10-07T18:08:43.974Z','2026-10-07T20:17:44.064Z','','',0,0,'saudi_region','عادي',60,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","الباحة"]','["الطقس والمناخ"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Temporarily Unreachable','2026-10-07T20:17:44.064Z',NULL,2,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0c292e48-724e-4d6e-afef-31b82b9826e5','news-0c292e48-724e-4d6e-afef-31b82b9826e5','سياسي / سمو ولي العهد يرأس جلسة مجلس الوزراء في الرياض','سياسي سمو ولي العهد يراس جلسه مجلس الوزراء في الرياض','الرياض 25 ربيع الآخر 1448 هـ الموافق 06 أكتوبر 2026 م واس رأس صاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز آل سعود ولي العهد رئيس مجلس الوزراء -حفظه الله-، الجلسة التي عقدها مجلس الوزراء اليوم في الرياض.','["وفي بداية الجلسة؛ أطلع سمو ولي العهد مجلس الوزراء على فحوى لقائه فخامة رئيس الجمهورية العربية السورية أحمد الشرع، وما جرى خلاله من استعراض آفاق العلاقات وأوجه التعاون بين البلدين الشقيقين، إضافة إلى بحث مستجدات الأحداث في المنطقة.","وأكد المجلس إثر متابعته التطورات الإقليمية؛ دعم المملكة العربية السعودية الكامل لمجلس القيادة الرئاسي والحكومة الشرعية والشعب اليمني الشقيق؛ لإنهاء الانقلاب في هذا البلد العزيز واستعادة الدولة ومؤسساتها من ميليشيا الحوثي الإرهابية التي اختارت التصعيد العسكري نهجًا بديلًا عن السلام، والإمعان في تعميق المعاناة الإنسانية والاقتصادية لليمن وشعبه الشقيق، والاستمرار في تهديد المنطقة وحركة الملاحة في جنوب البحر الأحمر ومضيق باب المندب.","وثـمّن المجلس مخرجات الاجتماع الطارئ للجنة الإستراتيجية السياسية والدفاعية لحلف مكة الدفاعي، وما اشتملت عليه من التأكيد على التضامن بين الدول الثلاث ووقوفها صفًا واحدًا في مواجهة الاعتداءات الآثمة على المملكة التي شملت مكة المكرمة والمدينة المنورة والأعيان المدنية والمنشآت المدنية والاقتصادية.","وما نتج عن الاجتماع من الاتفاق على تفعيل الردع الجماعي والانتقال الفوري إلى التنفيذ العملي لالتزامات الدفاع المشترك؛ بما يعزز الجاهزية والتكامل العسكري والقدرة على التصدي لتلك التهديدات.","وفي سياق آخر ثـمّن مجلس الوزراء عاليًا ما اشتمل عليه الخطاب الملكي السنوي لخادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود -أيده الله- في افتتاح أعمال السنة الثالثة من الدورة التاسعة لمجلس الشورى؛ من مضامين سامية أجملت الثوابت والمبادئ الراسخة للدولة وأبرز منجزات (رؤية السعودية2030) ومكتسبات الإصلاحات التنموية والحراك الاقتصادي، ومرتكزات السياسة الخارجية ومواقفها الثابتة التي كان لها الأثر الملموس في تعزيز مكانة المملكة العربية السعودية ودورها الفاعل إقليميًا ودوليًا.","وأعرب المجلس عن تقديره دور مجلس الشورى في دعم مسيرة التنمية الشاملة بالمملكة وتعزيز التكامل والتنسيق مع الجهات الحكومية والإسهام في تطوير المنظومة التشريعية والتنظيمية ورفع مستوى كفاية الأداء، مؤكدًا ضمن هذا الإطار أن تطلعات المواطن ومصلحة الوطن ستظلان دائمًا نصب العين في عمل أجهزة الدولة؛ تستشهد وتسترشد بهما في قراراتها وتوجهاتها الإستراتيجية.","وأوضح معالي وزير الإعلام الأستاذ سلمان بن يوسف الدوسري، في بيانه لوكالة الأنباء السعودية عقب الجلسة، أن المجلس عدّ التقديرات الأولية للميزانية العامة للدولة للعام المالي القادم؛ تأكيدًا على متانة اقتصاد المملكة ومرونته في التعامل مع المتغيرات والتطورات العالمية بسياسات استباقية تدعم تحقيق المستهدفات الوطنية والاستمرار في الإنفاق على الخدمات والأولويات التنموية والاجتماعية مع المحافظة على الاستدامة المالية.","وتناول مجلس الوزراء عددًا من التقارير عن المؤتمرات العالمية التي استضافتها المملكة، مشيدًا بأعمال الملتقى الدولي للمسؤولية الاجتماعية المنعقد تحت رعاية خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود -حفظه الله-، وبما تضمنت نسخته الثانية من إطلاق مبادرات ستسهم -بمشيئة الله- في تفعيل الشراكات ذات الأثر المجتمعي والتنموي وتوسيع نطاق الممكنات المؤسسية المستدامة في هذا المجال؛ بما يدعم الأهداف الوطنية ويعزز مسيرة التنمية الشاملة."]','أخبار السعودية','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2694659?type=news&uuid=N2694659','https://spa.gov.sa/ar/N2694659?type=news&uuid=N2694659','N2694659','N2694659','','الرياض','2026-10-06T12:38:00.000Z',NULL,'2026-10-07T18:08:44.075Z','https://portalcdn.spa.gov.sa/backend/original/202610/F10964762.jpg','/api/media/0c292e48-724e-4d6e-afef-31b82b9826e5','/api/media/0c292e48-724e-4d6e-afef-31b82b9826e5?variant=thumbnail','سياسي / سمو ولي العهد يرأس جلسة مجلس الوزراء في الرياض',1600,1221,'valid','published','current','valid',99,'5549c551e3f2e7b5019061dfe65c79344d7cab54579b557d64ca693324422e2f','0647033083df69a94d20511bc36f4a5ac446d59de87d2b1347daeaa0ac7364bd',NULL,'2026-10-07T18:08:44.075Z','2026-10-07T20:17:53.230Z','','',0,0,'saudi_region','مهم',70,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد يرأس جلسة مجلس","مجلس الوزراء في الرياض الرياض","رئيس مجلس الوزراء -حفظه الله-","وزير الإعلام الأستاذ سلمان بن","وزارة الطاقة في المملكة العربية","خادم الحرمين الشريفين الملك سلمان","الطاقة والنفط","التعليم والتدريب"]','["ولي العهد يرأس جلسة مجلس","مجلس الوزراء في الرياض الرياض","رئيس مجلس الوزراء -حفظه الله-","وزير الإعلام الأستاذ سلمان بن","وزارة الطاقة في المملكة العربية","خادم الحرمين الشريفين الملك سلمان"]','classified','','[{"category":"المناطق","score":10},{"category":"الاقتصاد","score":5.5},{"category":"المجتمع","score":4.5}]','Active','2026-10-07T20:17:53.230Z',200,2,0,'source_article_available','',NULL,NULL,'body:e2737c733e82b858b00853909842e44279c4ce779763d01ebd1100096f382caa','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c6d31c69-97ee-44eb-929a-5cc713d78442','news-c6d31c69-97ee-44eb-929a-5cc713d78442','ثقافي / العمارة المكية.. أصالة المكان وعبقرية الإنسان في صياغة هوية عمرانية متفردة','ثقافي العماره المكيه اصاله المكان وعبقريه الانسان في صياغه هويه عمرانيه متفرده','مكة المكرمة 25 ربيع الآخر 1448 هـ الموافق 06 أكتوبر 2026 م واس تختزن مكة المكرمة في عمرانها ملامح تاريخ طويل تشكلت خلاله هوية معمارية ارتبطت بخصوصية المكان ومكانته الدينية، وتفاعلت مع طبيعة البيئة الجغرافية والمناخية والاجتماعية، لتنتج طرازًا عمرانيًّا مميزًا يجمع الوظيفة والجمال، ويجعل من المبنى وثيقة حية تحكي جانبًا من حياة المجتمع المكي وتحولاته عبر…','["وتتزامن هذه الملامح مع الاحتفاء بـاليوم العالمي للعمارة 2026 الذي يصادف 5 أكتوبر من كل عام، واختار الاتحاد الدولي للمعماريين لهذا العام شعار \"السكن حق من حقوق الإنسان..","فلنبنه\"، في تأكيد لدور العمارة في توفير بيئات عمرانية ملائمة ومستدامة، والاستجابة لاحتياجات الإنسان مع مراعاة خصوصية المكان والثقافة.","ولم تكن العمارة في مكة المكرمة مجرد أسلوب للبناء، بل جاءت انعكاسًا مباشرًا للبيئة التي نشأت فيها؛ فموقع المدينة بين الجبال، ومناخها الحار، وطبيعة الحياة الاجتماعية فيها، أسهمت جميعها في تشكيل حلول معمارية متوارثة، وظّفت المواد المتاحة محليًّا، وراعت التهوية والإضاءة والخصوصية، إلى جانب العناية بالتفاصيل الجمالية، حيث إن العمارة التقليدية في منطقة مكة المكرمة تطورت نتيجة تفاعلها مع الظروف البيئية والاجتماعية، كما تأثرت بموقع مكة التاريخي بوصفها ملتقى للحجاج والقادمين إليها من مناطق وثقافات متعددة، وهو ما انعكس على تنوع الأساليب والتفاصيل المعمارية فيها.","ومن أبرز ما يميز البيت المكي التقليدي الرواشين؛ تلك النوافذ والشرفات الخشبية البارزة التي لم تكن عنصرًا زخرفيًّا فحسب، بل أدت وظائف متعددة، من بينها تنظيم دخول الضوء والهواء، والحد من وهج الشمس، وتحقيق قدر من الخصوصية لسكان المنزل، فضلًا عن إضفاء طابع جمالي على الواجهات.","وتتميز رواشين منطقة مكة المكرمة بأحجامها وارتفاعاتها، وتنوع أشكالها وزخارفها، وامتدادها في بعض المباني على واجهات الأدوار العليا، بما يعكس براعة الحرفيين وقدرتهم على الجمع بين المتطلبات العملية والقيمة الجمالية.","واعتمد البناء التقليدي في مكة المكرمة على مواد ارتبطت ببيئة المنطقة، ومنها الخشب الذي كان حاضرًا في العناصر الإنشائية والزخرفية، ولا سيما الرواشين والأبواب والأسقف.","وتكشف هذه المواد عن معرفة متراكمة لدى البنّاء المكي بخصائص البيئة؛ إذ وظفت بعض مواد البناء وطرق التشييد بما يساعد على التعامل مع الحرارة والرطوبة، فيما أسهم الخشب في توفير العزل والتظليل وإدخال الهواء والضوء بطريقة متوازنة.","ولم تتوقف خصوصية البيت المكي عند واجهاته، بل امتدت إلى تنظيمه الداخلي؛ إذ عُرفت فيه عناصر مثل الدهليز والمجلس والصفة وغرف المبيت والمركب، في توزيع يعكس طبيعة الحياة الاجتماعية والعائلية في البيت الحجازي، ويمنح كل مساحة وظيفتها وخصوصيتها."]','البيئة والمناخ','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2694351?type=news&uuid=N2694351','https://spa.gov.sa/ar/N2694351?type=news&uuid=N2694351','N2694351','N2694351','','مكة المكرمة','2026-10-06T08:10:00.000Z','2026-10-06T11:10:00.000Z','2026-10-07T18:08:44.237Z','https://portalcdn.spa.gov.sa/backend/original/202610/F10962023.jpeg','/api/media/c6d31c69-97ee-44eb-929a-5cc713d78442','/api/media/c6d31c69-97ee-44eb-929a-5cc713d78442?variant=thumbnail','ثقافي / العمارة المكية.. أصالة المكان وعبقرية الإنسان في صياغة هوية عمرانية متفردة',1600,1567,'valid','published','current','valid',58,'e28038292451c8c7d8d5748fb712848d93a586e820b89a44237b30c11b0e70cd','5053796171a5a45404a4e7a099f85b2db42569d7e0cc6da94346acb2ab31da86','محدّث','2026-10-07T18:08:44.237Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","الثقافة والفنون","الاقتصاد والأسواق","مكة"]','["الطقس والمناخ","الثقافة والفنون","الاقتصاد والأسواق"]','needs_review','below_category_threshold','[{"category":"المناطق","score":1.5},{"category":"الاقتصاد","score":1.5},{"category":"أخبار السعودية","score":0}]','Active','2026-10-07T20:17:53.648Z',200,2,0,'source_article_available','',NULL,NULL,'body:8b99ff3da90057d5b2d6e2f689d7db0265cef1a60a54378eaa8611fe65dc48dc','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('cb35249f-c72d-4e0c-97db-956b9d95493d','news-cb35249f-c72d-4e0c-97db-956b9d95493d','ثقافي / عمارة عسير... جماليات شاهقة تشهد على مهارات البنّائين وتكيّفهم مع البيئة','ثقافي عماره عسير جماليات شاهقه تشهد علي مهارات البنائين وتكيفهم مع البيئه','أبها 25 ربيع الآخر 1448 هـ الموافق 06 أكتوبر 2026 م واس في أجواء الاحتفاء باليوم العالمي للعمارة بداية أكتوبر من كل عام تستحضر منطقة عسير جانبًا من تجربتها العمرانية التي جعلت من الجبل مادة للبناء، ومن تضاريسه أساسًا للتشكيل، ومن موارده المحلية عناصر للجمال، في مشهد يكشف خبرة معمارية متوارثة استطاعت منذ قرون أن توائم بين متطلبات السكن والحماية والتخزين…','["وتبرز العمارة التقليدية في عسير بوصفها إحدى صور التفاعل العميق بين الإنسان وبيئته، فالمباني الحجرية والطينية تتدرج على السفوح، وبعضها يرتفع إلى عدة طوابق، فيما تتشكل واجهاتها من الحجر والمَرو والخشب، لتقدم نموذجًا عمرانيًّا لم تكن فيه الوظيفة منفصلة عن الجمال، ولا البناء منفصلًا عن طبيعة المكان.","وتوضح خريطة العمارة السعودية أن منطقة عسير تضم أنماطًا معمارية متعددة، من بينها عمارة مرتفعات أبها، وعمارة جبال السروات، وعمارة أصدار عسير، وعمارة سفوح تهامة، وعمارة ساحل تهامة؛ وهو تنوع يعكس اختلاف التضاريس والموارد والظروف المناخية من جزء إلى آخر.","ومن أبرز سمات العمارة العسيرية التقليدية نزعتها إلى الارتفاع، إذ استغل البناؤون المساحات المحدودة في البيئات الجبلية واتجهوا إلى البناء الرأسي، فظهرت مبانٍ متعددة الطوابق بدت في بعض القرى امتدادًا طبيعيًّا للجبال التي شُيدت عليها.","وتعد بلدة \"رُجال\" بمحافظة رجال ألمع من أبرز النماذج العمرانية القديمة، إذ تشير المصادر التراثية إلى مبانٍ يزيد عمر بعضها على ثلاثة قرون، شُيدت من الحجر والطين والخشب، وبلغ ارتفاع بعض مبانيها ثمانية طوابق، فيما تظهر في القرية حصون ومبانٍ متعددة الأدوار ارتبطت بوظائف السكن والتخزين والحماية.","ولم يكن الارتفاع مجرد خيار جمالي، بل ارتبط بطبيعة الأرض الجبلية وبالحاجة إلى استثمار المساحات المتاحة، إلى جانب الوظائف الدفاعية ومراقبة الممرات والطرق، وتخصيص أجزاء من المبنى للسكن وأخرى لتخزين المؤن والمحاصيل.","وتتجلى هذه الوظائف كذلك في القصبات التي شكلت عنصرًا بارزًا في المشهد العمراني العسيري، إذ أقيمت في مواقع مرتفعة لمراقبة الطرق ومداخل القرى، واستُخدمت بعض نماذجها لحفظ الحبوب والمؤن، فيما زود بعضها بفتحات صغيرة للمراقبة والدفاع.","وفي أجزاء مختلفة من المنطقة، ولا سيما أصدار عسير، تظهر الأبراج الحجرية المرتفعة ذات الهيئة الحصينة، ويصل بعضها إلى ستة طوابق، بينما تتجاوز بعض المنشآت التراثية ارتفاع 20 مترًا، بما يعكس مهارة البنّاء المحلي في التعامل مع البناء الرأسي فوق التضاريس الوعرة.","واستفاد البناؤون من المواد المتوافرة في البيئة، فكان الحجر أحد أهم عناصر البناء في مناطق السراة ورجال ألمع، إلى جانب الطين المستخدم في الجدران وبعض العناصر الإنشائية، وأدى الخشب أدوارًا إنشائية وزخرفية، خصوصًا في الأسقف والأبواب والنوافذ."]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2694315?type=news&uuid=N2694315','https://spa.gov.sa/ar/N2694315?type=news&uuid=N2694315','N2694315','N2694315','','عسير','2026-10-06T07:50:00.000Z',NULL,'2026-10-07T18:08:46.083Z','https://portalcdn.spa.gov.sa/backend/original/202610/F10961709.jpg','/api/media/cb35249f-c72d-4e0c-97db-956b9d95493d','/api/media/cb35249f-c72d-4e0c-97db-956b9d95493d?variant=thumbnail','ثقافي / عمارة عسير... جماليات شاهقة تشهد على مهارات البنّائين وتكيّفهم مع البيئة',1600,895,'valid','published','current','valid',85,'d43f90d6431f83b224978ef1b1e3292f75482faf6733e2452505f8107298c374','44139ec50e23927ebf5391867f58dc6df7e0ae773dd5d07d1811efb546a9dedf',NULL,'2026-10-07T18:08:46.083Z','2026-10-07T20:17:53.337Z','','',0,0,'saudi_region','عادي',57,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","الاقتصاد والأسواق","التقنية والتحول الرقمي","عسير"]','["الطقس والمناخ","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"الاقتصاد","score":4},{"category":"أخبار السعودية","score":1.5},{"category":"السياسة","score":0}]','Active','2026-10-07T20:17:53.337Z',200,2,0,'source_article_available','',NULL,NULL,'body:997a0010a33e7651aaccf3779b91cdb4501edd9a5ef6ab4b132241bd783647dd','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4401f33f-cbcd-4363-b23a-141a84074a6c','news-4401f33f-cbcd-4363-b23a-141a84074a6c','ثقافي / في اليوم العالمي للعمارة.. المدينة المنورة تستحضر هويتها في تفاصيل مشهدها العمراني','ثقافي في اليوم العالمي للعماره المدينه المنوره تستحضر هويتها في تفاصيل مشهدها العمراني','ويجسد طابع المدينة المنورة توجهًا نحو عمارة تستلهم هويتها، من خلال استحضار الملامح المعمارية والعناصر الثقافية لطيبة في التصاميم المعاصرة، مما يعزز ارتباط المشهد العمراني بتاريخها وبيئتها المحلية، ويمنح مشاريعها طابعًا متفردًا.','["المدينة المنورة 25 ربيع الآخر 1448 هـ الموافق 06 أكتوبر 2026 م واس يوافق اليوم الاثنين \"اليوم العالمي للعمارة\"، الذي يُحتفى به لإبراز دور العمارة في تشكيل المدن وتعزيز جودة البيئة العمرانية، فيما تبرز المدينة المنورة بطابع معماري يستمد ملامحه من هويتها الثقافية وإرثها العمراني، ويحافظ على أصالة المكان وخصوصيته.","وتبرز في العمارة المحلية تفاصيل ارتبطت تاريخيًا بالمكان، من بينها الرواشين والأفنية والأحجار البازلتية والعناصر المعمارية الأخرى المستوحاة من التراث، فيما تسهم إعادة توظيفها بأساليب معاصرة في تحقيق التوازن بين الأصالة ومتطلبات الحياة الحديثة، وبناء بيئات عمرانية تراعي احتياجات الإنسان وتوفر له الراحة والخصوصية.","وتسهم الملامح المعمارية والهويات التصميمية المستمدة من البيئة المحلية في تعزيز خصوصية المشهد العمراني والارتقاء بجودة التصميم، بما يواكب تطلعات المستقبل ويحافظ في الوقت ذاته على ذاكرة المكان وهويته.","ويأتي الاهتمام بالهوية المعمارية للمدينة المنورة في إطار مستهدفات \"العمارة السعودية\"، الرامية إلى تعزيز الهوية العمرانية وتحسين المشهد الحضري وتطوير بيئات عمرانية مستدامة تتمحور حول الإنسان، مما ينسجم مع مستهدفات رؤية السعودية 2030. // انتهى // 00:43 ت مـ 0015"]','أخبار السعودية','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2693967?type=news&uuid=N2693967','https://spa.gov.sa/ar/N2693967?type=news&uuid=N2693967','N2693967','N2693967','','المدينة المنورة','2026-10-05T18:43:00.000Z',NULL,'2026-10-07T18:08:46.841Z','https://portalcdn.spa.gov.sa/backend/original/202610/F10959366.jpeg','/api/media/4401f33f-cbcd-4363-b23a-141a84074a6c','/api/media/4401f33f-cbcd-4363-b23a-141a84074a6c?variant=thumbnail','ثقافي / في اليوم العالمي للعمارة.. المدينة المنورة تستحضر هويتها في تفاصيل مشهدها العمراني',1600,1246,'valid','published','current','valid',46,'df1a54d55498791d0035e37ac5015557220585dc10cd38adc5503fceb3e5a39d','b285629c026a56eb8db353b8658ec8cf7e3a154b9486ff67ac44dd73b0325013',NULL,'2026-10-07T18:08:46.841Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','عادي',51,NULL,0,0,0,'',NULL,NULL,NULL,'["المدينة المنورة"]','["المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T20:17:55.339Z',200,2,0,'source_article_available','',NULL,NULL,'body:b3c926f76587f4452c72239e668bcc6f53b8cdcb5679ea01c4238f81f53c2b51','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0996047a-b431-4beb-b240-94452df52836','news-0996047a-b431-4beb-b240-94452df52836','ثقافي / الهيئة الملكية لمدينة مكة المكرمة والمشاعر المقدسة تختتم ورشة "إعادة توظيف المباني التراثية"','ثقافي الهيئه الملكيه لمدينه مكه المكرمه والمشاعر المقدسه تختتم ورشه اعاده توظيف المباني التراثيه','مكة المكرمة 25 ربيع الآخر 1448 هـ الموافق 06 أكتوبر 2026 م واس اختتمت الهيئة الملكية لمدينة مكة المكرمة والمشاعر المقدسة، بالتعاون مع مؤسسة التراث غير الربحية، أعمال ورشة "إعادة توظيف المباني التراثية: من الحماية إلى التشغيل المستدام في مدينة مكة المكرمة"، التي أُقيمت على مدى يومين، بمشاركة أكثر من 390 من الأكاديميين والمتخصصين والممارسين في مجالات…','["وبحثت الورشة آليات إعادة توظيف المباني التراثية بما يصون قيمتها التاريخية والعمرانية والثقافية، ويلائم متطلبات الاستخدام المعاصر.","وتضمن البرنامج ثماني محاضرات وجلسَتين حواريتين، تناولت القيمة التراثية للمبنى وعلاقتها باختيار الاستخدام الجديد، ومعايير تحديد أولويات التأهيل، والأطر النظامية والفنية لإعادة التوظيف، ونماذج التشغيل المستدام، والشراكات والحوكمة.","وركز اليوم الأول على الانتقال من الحماية إلى التأهيل، وفهم قيمة المبنى ومعايير اختيار الوظيفة الملائمة له، وحدود التدخل التي تكفل المحافظة على خصائصه وقيمته، فيما تناول اليوم الثاني مرحلة ما بعد التأهيل، بما يشمل دورة حياة المبنى، ونماذج الإدارة والتشغيل والصيانة والتمويل، وتوزيع المسؤوليات بين الأطراف ذات العلاقة.","كما ناقشت الورشة توظيف التقنيات الحديثة في خدمة المباني التراثية، ومن بينها التوثيق الرقمي، والمسح ثلاثي الأبعاد، ونمذجة معلومات المباني التراثية، ودورها في دعم التأهيل والصيانة والتشغيل وإثراء تجربة الزائر.","وسجّلت الورشة مستوى رضا بلغ 4.87 من 5، في مؤشر يعكس تقدير المشاركين لها.","وجمعت محاورها بين الحفظ المعماري ومتطلبات الإدارة والتشغيل، ووسّعت النقاش حول المباني التراثية بوصفها موارد ثقافية يمكن مواصلة استخدامها مع المحافظة على قيمتها. // انتهى // 13:37 ت مـ 0121"]','الوظائف وسوق العمل','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2694297?type=news&uuid=N2694297','https://spa.gov.sa/ar/N2694297?type=news&uuid=N2694297','N2694297','N2694297','','مكة المكرمة','2026-10-06T07:37:00.000Z','2026-09-02T19:33:00.000Z','2026-10-07T18:08:46.863Z','https://portalcdn.spa.gov.sa/backend/original/202610/F10961507.jpg','/api/media/0996047a-b431-4beb-b240-94452df52836','/api/media/0996047a-b431-4beb-b240-94452df52836?variant=thumbnail','ثقافي / الهيئة الملكية لمدينة مكة المكرمة والمشاعر المقدسة تختتم ورشة "إعادة توظيف المباني التراثية"',1600,1043,'valid','published','current','valid',89,'564f5e67b972b1d7f19170ef49ba27c6e1a4e9a56a69698d59ac30d246365e59','3d115e659636e3fdda1ad8e9fc0662da9a60f7e133b4ad0e07d671011c6bb620','محدّث','2026-10-07T18:08:46.863Z','2026-10-07T20:25:22.793Z','','',0,0,'saudi_region','مهم',66,NULL,0,0,0,'',NULL,NULL,NULL,'["التقنية والتحول الرقمي","مكة"]','["التقنية والتحول الرقمي"]','classified','','[{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0},{"category":"الاقتصاد","score":0}]','Active','2026-10-07T20:17:55.098Z',200,2,0,'source_article_available','',NULL,NULL,'body:62bd026d95b31dbc1806d59aa1b7ef2b2de1810501dd92f00a6e8bde87657671','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f5d96bfe-a619-4ca1-8c89-a24b010f66d0','news-f5d96bfe-a619-4ca1-8c89-a24b010f66d0','سياحة وترفيه / "أجواء الخريف" ضباب يجسّد جمال الطبيعة في الباحة','سياحه وترفيه اجواء الخريف ضباب يجسد جمال الطبيعه في الباحه','ويرتبط فصل الخريف في الباحة بظواهر جوية مميزة، أبرزها تدفّق الغيوم وانخفاض درجات الحرارة، فيما تبدأ أضواء الطرق والأحياء في الظهور تدريجيًا أسفل طبقات الضباب، مشكلةً لوحة تجمع وهج الغروب وإضاءة المدينة، ما ينعكس على جمال الطبيعة والتضاريس وانتعاش الغطاء النباتي، لتواصل المنطقة تقديم مشهد سياحي متجدد مع تعاقب الفصول واختلاف ألوان الطبيعة وأجوائها.','["الباحة 24 ربيع الأخر 1448 هـ الموافق 05 أكتوبر 2026 م واس تزيّنت سماء مدينة الباحة، اليوم، بمشاهد طبيعية آسرة، إذ تدفقت الغيوم الكثيفة على سفوح الجبال لتغمر متنزهات وحدائق وأحياء الباحة، في لوحة بديعة تُجسّد ملامح دخول فصل الخريف إلى منطقة الباحة."]','المناطق','','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://spa.gov.sa/ar/N2693856?type=news&uuid=N2693856','https://spa.gov.sa/ar/N2693856?type=news&uuid=N2693856','N2693856','N2693856','','الباحة','2026-10-05T16:46:00.000Z','2026-10-05T16:46:00.000Z','2026-10-07T18:08:48.817Z','https://portalcdn.spa.gov.sa/backend/original/202610/F10958611.jpeg','/api/media/f5d96bfe-a619-4ca1-8c89-a24b010f66d0','/api/media/f5d96bfe-a619-4ca1-8c89-a24b010f66d0?variant=thumbnail','سياحة وترفيه / "أجواء الخريف" ضباب يجسّد جمال الطبيعة في الباحة',1600,1118,'valid','published','current','valid',46,'3935b50e580277d9758471e89a6191a720ae77d00c1b0112c64bd9b04face69d','724e0a21ddc0468d6ef9e19b242da45315fd64bd77462d39d59cea490ed45a3d','محدّث','2026-10-07T18:08:48.817Z','2026-10-07T20:17:58.292Z','','',0,0,'saudi_region','عادي',51,NULL,0,0,0,'',NULL,NULL,NULL,'["الطقس والمناخ","السفر والسياحة","الباحة"]','["الطقس والمناخ","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"المجتمع","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"السياسة","score":0}]','Active','2026-10-07T20:17:58.292Z',200,2,0,'source_article_available','',NULL,NULL,'body:58ac24e3ec62330ccae63d389d6c33c860c0651a7d78a288e7cf329c3df22e5e','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('06c7efe1-cd88-49df-b6c0-45c16bc598ce','news-06c7efe1-cd88-49df-b6c0-45c16bc598ce','التلفزيون السوري: قوات الاحتلال تتوغل في وادي الرقاد بريف درعا','التلفزيون السوري قوات الاحتلال تتوغل في وادي الرقاد بريف درعا','وأفرجت القوات عن شاب اختطفته صباح اليوم بعد إصابته في بلدة جباتا الخشب بريف القنيطرة، وفق قناة الإخبارية السورية. ودأبت قوات الاحتلال على التوغل في الجنوب السوري بزعم الحاجة إلى فرض ساحات تأمين، بينما اتسعت رقعة سيطرتها على الأراضي السورية.','["أعلن التلفزيون السوري ، أن قوات الاحتلال الإسرائيلي تتوغل في وادي الرقاد بريف درعا .","وأضاف، أن قوات الاحتلال بدأت تستجوب مزارعين وتمنع آخرين من الوصول إلى أراضيهم.","وأفرجت القوات عن شاب اختطفته صباح اليوم بعد إصابته في بلدة جباتا الخشب بريف القنيطرة، وفق قناة الإخبارية السورية.","ودأبت قوات الاحتلال على التوغل في الجنوب السوري بزعم الحاجة إلى فرض ساحات تأمين، بينما اتسعت رقعة سيطرتها على الأراضي السورية."]','العقارات','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/g40o3dfl7','https://ajel.sa/international/g40o3dfl7','https://ajel.sa/international/g40o3dfl7','https://ajel.sa/international/g40o3dfl7','فريق التحرير','','2026-10-07T09:56:00.000Z','2026-10-07T12:56:00.000Z','2026-10-07T18:14:39.165Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/featured-crop-E92bWmbo.png','/api/media/06c7efe1-cd88-49df-b6c0-45c16bc598ce','/api/media/06c7efe1-cd88-49df-b6c0-45c16bc598ce?variant=thumbnail','التلفزيون السوري: قوات الاحتلال تتوغل في وادي الرقاد بريف درعا',1200,675,'valid','published','current','valid',41,'518d51e294145a21c346b93dd274ffa2ccdb5eb868cf8ae63807be1426bb6b7e','950fe037b9c3a031672885dc9331fbd7c7ef8c2b4d28f8e98d3c868c942d2d84','محدّث','2026-10-07T18:14:39.165Z','2026-10-07T20:25:22.793Z','','',0,0,'international','عادي',34,NULL,0,0,0,'',NULL,NULL,NULL,'["الوظائف وسوق العمل"]','["الوظائف وسوق العمل"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T20:21:36.329Z',NULL,2,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7c396b2d-d12c-457d-a6fe-8e944849cb6c','news-7c396b2d-d12c-457d-a6fe-8e944849cb6c','قوات الجيش والمقاومة اليمنية تخوض معارك عنيفة بمواجهة ميليشيا الحوثي في جبل حبشي','قوات الجيش والمقاومه اليمنيه تخوض معارك عنيفه بمواجهه ميليشيا الحوثي في جبل حبشي','وأسقطت القوات اليمنية قتلى وخسائر في صفوف الحوثيين في تعز وسط اشتباكات محتدمة بين الجيش اليمني والمليشيات، وفق " الحدث ". ولا زالت قوات الجيش اليمني تواصل التقدم لمنع المليشيات الحوثية من الوصول إلى المواقع الحيوية والاستراتيجية ومنعها من السيطرة على القمم والمرتفعات الجبلية ضمانا لاستمرار تفوق القوات اليمنية ميدانيا.','["وأسقطت القوات اليمنية قتلى وخسائر في صفوف الحوثيين في تعز وسط اشتباكات محتدمة بين الجيش اليمني والمليشيات، وفق \" الحدث \".","ولا زالت قوات الجيش اليمني تواصل التقدم لمنع المليشيات الحوثية من الوصول إلى المواقع الحيوية والاستراتيجية ومنعها من السيطرة على القمم والمرتفعات الجبلية ضمانا لاستمرار تفوق القوات اليمنية ميدانيا."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/a3fccfgov','https://ajel.sa/international/a3fccfgov','https://ajel.sa/international/a3fccfgov','https://ajel.sa/international/a3fccfgov','فريق التحرير','','2026-10-07T12:21:00.000Z','Wed, 07 Oct 2026 20:52:52 GMT','2026-10-07T18:32:38.413Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%AC%D9%8A%D8%B4-%D8%A7%D9%84%D9%8A%D9%85%D9%86%D9%8A-UZ9KhEHe.jpg','/api/media/7c396b2d-d12c-457d-a6fe-8e944849cb6c','/api/media/7c396b2d-d12c-457d-a6fe-8e944849cb6c?variant=thumbnail','قوات الجيش والمقاومة اليمنية تخوض معارك عنيفة بمواجهة ميليشيا الحوثي في جبل حبشي',1200,675,'valid','published','current','valid',41,'3bf9291d03a33af41d8462f9a38d0967419684f132a3c7c274246246506966cb','2076e8ceacf7b30ba04972b4b51e16813fd3275ca6572521a40f8f5778777125','محدّث','2026-10-07T18:32:38.413Z','2026-10-07T20:52:53.993Z','','',0,0,'gulf_arab','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["اليمن"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T20:52:53.993Z',200,2,0,'source_article_available','',NULL,NULL,'body:465097519066b93e929c8196bcff469f63a00df4e2010ccfec12ae9bdd416363','Wed, 07 Oct 2026 20:52:52 GMT');
