INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('218f4087-a8a8-409a-83b0-d667866ec966','news-218f4087-a8a8-409a-83b0-d667866ec966','العليمي: نثمن توجيهات خادم الحرمين بالاستجابة لطلب تصحيح أوضاع اليمنيين الموجودين بالمملكة بطرق غير نظامية','العليمي نثمن توجيهات خادم الحرمين بالاستجابه لطلب تصحيح اوضاع اليمنيين الموجودين بالمملكه بطرق غير نظاميه','ثمَّن الرئيس الدكتور رشاد محمد العليمي، رئيس مجلس القيادة الرئاسي اليمني، التوجيهات السامية لخادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، بالاستجابة لطلب تصحيح أوضاع اليمنيين الموجودين في المملكة بطرق غير نظامية، ومنحهم التسهيلات اللازمة، معتبراً ذلك امتداداً للدعم السعودي الشامل لليمن وشعبه ومؤسساته.','["كما أعرب عن عظيم تقديره وامتنانه للأشقاء في المملكة العربية السعودية، بقيادة خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، وصاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز، ولي العهد رئيس مجلس الوزراء .","كما ثمن العليمي موقف المملكة الثابت ودعمها الكامل لمجلس القيادة الرئاسي والحكومة والشعب اليمني، وإسناد القوات المسلحة في معركة استعادة مؤسسات الدولة والأمن والاستقرار.","ونوه بما أكده مجلس الوزراء السعودي، برئاسة سمو ولي العهد، من دعم كامل لمجلس القيادة الرئاسي والحكومة والشعب اليمني لإنهاء الانقلاب واستعادة مؤسسات الدولة، وتأكيده أن المليشيات الحوثية اختارت التصعيد العسكري بديلاً عن السلام، واستمرت في تهديد المنطقة والملاحة في جنوب البحر الأحمر و مضيق باب المندب ."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/u0szsumvf','https://ajel.sa/international/u0szsumvf','https://ajel.sa/international/u0szsumvf','https://ajel.sa/international/u0szsumvf','فريق التحرير','','2026-10-07T12:21:00.000Z','Wed, 07 Oct 2026 20:52:52 GMT','2026-10-07T18:32:47.784Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%B1%D8%B4%D8%A7%D8%AF-%D8%A7%D9%84%D8%B9%D9%84%D9%8A%D9%85%D9%8A-oa35oT4r.png','/api/media/218f4087-a8a8-409a-83b0-d667866ec966','/api/media/218f4087-a8a8-409a-83b0-d667866ec966?variant=thumbnail','العليمي: نثمن توجيهات خادم الحرمين بالاستجابة لطلب تصحيح أوضاع اليمنيين الموجودين بالمملكة بطرق غير نظامية',1200,675,'valid','published','current','valid',99,'c37c7b9ce3985d3ba1b096d47fa8180ce65b2543b001780d702e23aa3e111038','4423b5f7bb28998b53888116d972be72a8cdfe73f66dc402146654f3591f9c1c','محدّث','2026-10-07T18:32:47.784Z','2026-10-07T20:52:54.197Z','','',0,0,'saudi_national','أولوية قصوى',82,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","رئيس مجلس القيادة الرئاسي اليمني","خادم الحرمين بالاستجابة لطلب تصحيح","مجلس القيادة الرئاسي اليمني التوجيهات","اليمن"]','["ولي العهد رئيس مجلس الوزراء","رئيس مجلس القيادة الرئاسي اليمني","خادم الحرمين بالاستجابة لطلب تصحيح","مجلس القيادة الرئاسي اليمني التوجيهات"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T20:52:54.197Z',200,2,0,'source_article_available','',NULL,NULL,'body:2719629df9f13308fa4380d36efd9c265335f340c1446c0bef35edb7f8552061','Wed, 07 Oct 2026 20:52:52 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('eb8c0011-99e7-4f51-a474-87356300c067','news-eb8c0011-99e7-4f51-a474-87356300c067','وزير الإعلام الإريتري: إثيوبيا تقرع طبول الحرب علنا','وزير الاعلام الاريتري اثيوبيا تقرع طبول الحرب علنا','وأضاف وزير الإعلام، إثيوبيا تختلق مزاعم ضدنا لتبرير حربها العدوانية، تسعى للوصول إلى "عصب" وبسط نفوذها على سواحلنا. كانت قوات إريترية انتشرت مؤخرا حول بلدة في إقليم تيغراي بشمال إثيوبيا، بعد نحو 14 يوما من نزاع داخلي يهدد بالتحول إلى حرب إقليمية أوسع.','["قال وزير الإعلام الإريتري يماني قبر مسقل، إن إثيوبيا تقرع طبول الحرب علنا.","وأضاف وزير الإعلام، إثيوبيا تختلق مزاعم ضدنا لتبرير حربها العدوانية، تسعى للوصول إلى \"عصب\" وبسط نفوذها على سواحلنا.","كانت قوات إريترية انتشرت مؤخرا حول بلدة في إقليم تيغراي بشمال إثيوبيا، بعد نحو 14 يوما من نزاع داخلي يهدد بالتحول إلى حرب إقليمية أوسع.","تجدر الإشارة إلى أن القتال بدأ بين جبهة تحرير شعب تيغراي والقوات الاتحادية الإثيوبية في 23 سبتمبر الماضي ما أثار مخاوف من عودة الحرب الأهلية للبلاد."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/0tgtm97t5','https://ajel.sa/international/0tgtm97t5','https://ajel.sa/international/0tgtm97t5','https://ajel.sa/international/0tgtm97t5','فريق التحرير','','2026-10-07T12:02:00.000Z','Wed, 07 Oct 2026 20:52:54 GMT','2026-10-07T18:32:49.130Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/featured-crop-tXwrp6CG.png','/api/media/eb8c0011-99e7-4f51-a474-87356300c067','/api/media/eb8c0011-99e7-4f51-a474-87356300c067?variant=thumbnail','وزير الإعلام الإريتري: إثيوبيا تقرع طبول الحرب علنا',1200,675,'valid','published','current','valid',41,'5cd8f59415bfb7d253408c5aa5cc8986013cb5111548b5d1c8609321c1588bd0','b953203b78cbc002d03fe10cb0883fd4883ff8fd7e87f40f4d3bc7a4ad49f5d7','محدّث','2026-10-07T18:32:49.130Z','2026-10-07T20:52:55.487Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الإعلام الإريتري إثيوبيا تقرع"]','["وزير الإعلام الإريتري إثيوبيا تقرع"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T20:52:55.487Z',200,2,0,'source_article_available','',NULL,NULL,'body:b6e8dac7d550eafafb18113fb8a9baa0b9554f8b746b695005fdfadd8ceb631c','Wed, 07 Oct 2026 20:52:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('dae43e81-949d-424b-8b25-783c26decd16','news-dae43e81-949d-424b-8b25-783c26decd16','«الأمن البيئي» تضبط مواطنًا مخالفًا لنظام البيئة لتخزينه حطبًا محليًا في عسير','الامن البيئي تضبط مواطنا مخالفا لنظام البيئه لتخزينه حطبا محليا في عسير','ضبطت القوات الخاصة للأمن البيئي مواطنًا مخالفًا لنظام البيئة، بحوزته مترًا مكعبًا من الحطب المحلي في منطقة عسير ، وطبقت الإجراءات النظامية بحقه، وتسليم الكميات المضبوطة للجهات المختصة.','["وأوضحت القوات أن عقوبة استخدام الحطب والفحم المحليين في الأنشطة التجارية غرامة تصل إلى (32,000) ريال لكل متر مكعب، وعقوبة نقل وبيع وتخزين الحطب والفحم المحليين غرامة تصل إلى (16,000) ريال لكل متر مكعب، حاثةً على الإبلاغ عن أي حالات تمثل اعتداءً على البيئة أو الحياة الفطرية على الرقم (911) بمناطق مكة المكرمة والمدينة المنورة و الرياض و الشرقية ، و(999) و(996) في بقية مناطق المملكة ، وستعامل جميع البلاغات بسرية تامة دون أدنى مسؤولية على المبلّغ."]','المناطق','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/vg1ur8bji','https://ajel.sa/local/vg1ur8bji','https://ajel.sa/local/vg1ur8bji','https://ajel.sa/local/vg1ur8bji','فريق التحرير','الرياض','2026-10-07T12:02:00.000Z','Wed, 07 Oct 2026 20:52:54 GMT','2026-10-07T18:32:49.951Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/%D8%A7%D9%84%D8%A3%D9%85%D9%86-%D8%A7%D9%84%D8%A8%D9%8A%D8%A6%D9%8A-z2CByCd8.jpg','/api/media/dae43e81-949d-424b-8b25-783c26decd16','/api/media/dae43e81-949d-424b-8b25-783c26decd16?variant=thumbnail','«الأمن البيئي» تضبط مواطنًا مخالفًا لنظام البيئة لتخزينه حطبًا محليًا في عسير',1200,675,'valid','published','current','valid',46,'a663b0a52e50f3f802b9af0bece66e02477e9ddf030be23b04e8fe7a4c5e68ed','fe7fb9de14eaac719eef9b060176484e147afbce2fdf37106c47762edfc82816','محدّث','2026-10-07T18:32:49.951Z','2026-10-07T20:52:55.479Z','','',0,0,'saudi_region','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["مكة","عسير","الرياض","المدينة المنورة"]','["المدينة المنورة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Active','2026-10-07T20:52:55.479Z',200,3,0,'source_article_available','',NULL,NULL,'body:95e4c08a90b134734cba462ce3e8394eb5ab3ec68529264d1fadfc6a8b4f8c6c','Wed, 07 Oct 2026 20:52:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4c4094d7-d378-41bb-a32b-5a7d626395ad','news-4c4094d7-d378-41bb-a32b-5a7d626395ad','«ترامب» يشكك في رواية روسيا حول الطاعون: لا نعتقد أنه سلاح بيولوجي','ترامب يشكك في روايه روسيا حول الطاعون لا نعتقد انه سلاح بيولوجي','وأضاف ترامب، أننا «لا نعتقد اتباط حالة الوفاة بالطاعون في روسيا بتطوير سلاح بيولوجي»، وفق «العربية». وأكمل، أن «روسيا لا تقول الكثير عن حادثة الطاعون مثلما فعلت الصين بشأن كورونا، وتؤكد أن الوضع بشأن الطاعون تحت السيطرة ونحن نتحقق».','["شكك الرئيس الأمريكي دونالد ترامب في رواية روسيا حول الطاعون.","وأضاف ترامب، أننا «لا نعتقد اتباط حالة الوفاة بالطاعون في روسيا بتطوير سلاح بيولوجي»، وفق «العربية».","وأكمل، أن «روسيا لا تقول الكثير عن حادثة الطاعون مثلما فعلت الصين بشأن كورونا، وتؤكد أن الوضع بشأن الطاعون تحت السيطرة ونحن نتحقق».","كانت السلطات الروسية فرضت تدابير لمكافحة الأوبئة بعد وفاة باحثة في مختبر بمعهد في سيبيريا مختص بدراسة الطاعون وغيره من الأمراض المعدية، إثر إصابتها بالتهاب رئوي لم يُحدد مصدره."]','العالم','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/lcza64ap8','https://ajel.sa/international/lcza64ap8','https://ajel.sa/international/lcza64ap8','https://ajel.sa/international/lcza64ap8','فريق التحرير','','2026-10-07T12:02:00.000Z','Wed, 07 Oct 2026 20:52:54 GMT','2026-10-07T18:32:50.441Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/1000212305-crop-_uBb7SEK.jpg','/api/media/4c4094d7-d378-41bb-a32b-5a7d626395ad','/api/media/4c4094d7-d378-41bb-a32b-5a7d626395ad?variant=thumbnail','«ترامب» يشكك في رواية روسيا حول الطاعون: لا نعتقد أنه سلاح بيولوجي',1200,675,'valid','published','current','valid',41,'0d2911782ea108ead85dac9879266441652d88409719d40cc446e681370f1199','f2fc4f8c9bd1d27a2f90511ee61ab60a5e2e2618edb6662ecf8bfe087a21ea66','محدّث','2026-10-07T18:32:50.441Z','2026-10-07T20:52:55.514Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["روسيا","الصين"]','[]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T20:52:55.514Z',200,3,0,'source_article_available','',NULL,NULL,'body:53b937b8452396f9be51b461a2931524c66b3bc2974d15ade9ec7e4a5c9438f9','Wed, 07 Oct 2026 20:52:54 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b0bf47aa-30e7-4c3f-814a-d88e37366509','news-b0bf47aa-30e7-4c3f-814a-d88e37366509','أسعار الذهب تسجل أدنى مستوى في شهرين متأثرة بصعود الدولار','اسعار الذهب تسجل ادني مستوي في شهرين متاثره بصعود الدولار','تراجعت أسعار الذهب اليوم الأربعاء إلى أدنى مستوياتها في شهرين، متأثرة بارتفاع الدولار الأمريكي وصعود عوائد سندات الخزانة، وسط ترقب المستثمرين لمسار السياسة النقدية لمجلس الاحتياطي الفيدرالي الأمريكي.','["وانخفض سعر الذهب في المعاملات الفورية بنسبة 1.6٪ ليصل إلى 4,096.13 دولارًا للأوقية، بينما سجلت العقود الأمريكية الآجلة للذهب تسليم ديسمبر تراجعًا بنسبة 1.6٪ لتسجل 4,121.70 دولارًا للأوقية.","وفي سياق متصل، سجلت الفضة خسائر في المعاملات الفورية بنسبة 2.9٪ لتصل إلى 59.89 دولارًا للأوقية. كما هبط البلاتين بنسبة 4.8٪ إلى 1,620.38 دولارًا للأوقية، وتراجع البلاديوم بنسبة 4.2٪ إلى 1,122.75 دولارًا للأوقية.","ويأتي هذا الانخفاض وسط ترقب الأسواق لقرارات السياسة النقدية الأمريكية وتأثيرها على أسعار المعادن النفيسة."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/lcyw3t6lc','https://ajel.sa/economy/lcyw3t6lc','https://ajel.sa/economy/lcyw3t6lc','https://ajel.sa/economy/lcyw3t6lc','فريق التحرير','','2026-10-07T12:31:00.000Z','Wed, 07 Oct 2026 21:02:15 GMT','2026-10-07T18:41:38.577Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%B0%D9%87%D8%A8-3-AHF-Xcty.jpg','/api/media/b0bf47aa-30e7-4c3f-814a-d88e37366509','/api/media/b0bf47aa-30e7-4c3f-814a-d88e37366509?variant=thumbnail','أسعار الذهب تسجل أدنى مستوى في شهرين متأثرة بصعود الدولار',1200,675,'valid','published','current','valid',41,'d17b34b1847488ffc5008e604a63576974d5895caae82e9fbae2fe61a67fc7bc','6ccd4970ffe6bfaf3cefc3ba8042aa3b4a6a4ea6bfcf3dcd0234341ad01960ef','محدّث','2026-10-07T18:41:38.577Z','2026-10-07T21:02:16.784Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','["الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T21:02:16.784Z',200,2,0,'source_article_available','',NULL,NULL,'body:f7795d7851e3f080fbbf2728b22ac54f0387682a38853daa04a0151f37126f34','Wed, 07 Oct 2026 21:02:15 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0c4f853b-3303-4079-8f8e-b5a5dca3a9a8','news-0c4f853b-3303-4079-8f8e-b5a5dca3a9a8','وصول أولى وفود الدفعة الرابعة من ضيوف برنامج خادم الحرمين للعمرة إلى المدينة المنورة','وصول اولي وفود الدفعه الرابعه من ضيوف برنامج خادم الحرمين للعمره الي المدينه المنوره','استقبلت وزارة الشؤون الإسلامية والدعوة والإرشاد، اليوم الثلاثاء، أولى وفود الدفعة الرابعة والأخيرة من ضيوف برنامج خادم الحرمين الشريفين للعمرة والزيارة لعام 1448هـ، لدى وصولهم إلى المدينة المنورة.','["ويأتي وصول هذه الدفعة تمهيدًا لزيارة المسجد النبوي الشريف وعدد من المعالم الإسلامية والتاريخية بالمدينة، قبل انتقالهم إلى مكة المكرمة لأداء مناسك العمرة.","وضمت طلائع الضيوف معتمرين ومعتمرات من عدة دول، منها سريلانكا، و أوزبكستان ، وتركمانستان، ونيبال، و أذربيجان ، وطاجيكستان، وقرغيزستان، و تركيا ، و جورجيا ، و كازاخستان ، و باكستان ، و بنغلاديش ، والمالديف، وكان في استقبالهم مسؤولو الوزارة الذين أكدوا حرصهم على تقديم جميع الخدمات والتسهيلات.","تضم الدفعة الرابعة 250 معتمرًا ومعتمرة يمثلون 21 دولة، بينها باكستان، وبنغلاديش، و الهند ، وسريلانكا، ونيبال، والمالديف، وكازاخستان، وقرغيزستان، وأوزبكستان، وطاجيكستان، وتركمانستان، وأذربيجان، وتركيا، وجورجيا، و روسيا ، وبوتان، و أستراليا ، و نيوزيلندا ، وفانواتو، وجزر سليمان، وفيجي.","وبوصول الدفعة الرابعة والأخيرة، يكتمل عدد المستضافين ضمن برنامج خادم الحرمين الشريفين للعمرة والزيارة لهذا العام إلى 1,000 معتمر ومعتمرة، يمثلون 65 دولة من مختلف أنحاء العالم، ممن صدرت موافقة خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود على استضافتهم على نفقته الخاصة.","تنفذ وزارة الشؤون الإسلامية والدعوة والإرشاد البرنامج بإشراف ومتابعة وزير الشؤون الإسلامية والدعوة والإرشاد المشرف العام على البرنامج الشيخ الدكتور عبداللطيف بن عبدالعزيز آل الشيخ ، الذي يتابع الخدمات المقدمة للضيوف منذ وصولهم إلى المملكة وحتى مغادرتهم، تحقيقًا لتوجيهات القيادة في العناية بضيوف الرحمن وتوفير أفضل الخدمات لهم."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/u3koundas','https://ajel.sa/local/u3koundas','https://ajel.sa/local/u3koundas','https://ajel.sa/local/u3koundas','فريق التحرير','مكة المكرمة','2026-10-07T12:30:00.000Z','Wed, 07 Oct 2026 21:02:15 GMT','2026-10-07T18:41:39.835Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/ingested/2026-10/source-glTLslgr.jpg','/api/media/0c4f853b-3303-4079-8f8e-b5a5dca3a9a8','/api/media/0c4f853b-3303-4079-8f8e-b5a5dca3a9a8?variant=thumbnail','وصول أولى وفود الدفعة الرابعة من ضيوف برنامج خادم الحرمين للعمرة إلى المدينة المنورة',1200,675,'valid','published','current','valid',99,'7dc2949afae6438b62b79b34e19d787a06e34046d850aca51dd9ba916c3efd49','eb66e5eefbd1d50121e24960fe6f5dc327e3c22f3af6a0e31e329d0c876d9adc','محدّث','2026-10-07T18:41:39.835Z','2026-10-07T21:02:16.731Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["خادم الحرمين للعمرة إلى المدينة","وزير الشؤون الإسلامية والدعوة والإرشاد","وزارة الشؤون الإسلامية والدعوة والإرشاد","مكة","تركيا","روسيا","المدينة المنورة"]','["خادم الحرمين للعمرة إلى المدينة","وزير الشؤون الإسلامية والدعوة والإرشاد","وزارة الشؤون الإسلامية والدعوة والإرشاد","المدينة المنورة"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T21:02:16.731Z',200,2,0,'source_article_available','',NULL,NULL,'body:a99b082278491addbeeb77d229b0e5042afd46ee747b712e9707079b5a693f60','Wed, 07 Oct 2026 21:02:15 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('459b47b1-f295-4bc9-aeba-8c684f0e934f','news-459b47b1-f295-4bc9-aeba-8c684f0e934f','اتجاه لتخفيف العقوبة على رونالدو بعد مغادرته معسكر منتخب البرتغال','اتجاه لتخفيف العقوبه علي رونالدو بعد مغادرته معسكر منتخب البرتغال','فتح كريستيانو رونالدو الباب أمام عودته إلى منتخب البرتغال ، بعدما اعتذر عن مغادرته المعسكر، مبدياً استعداده لتقبّل عقوبة قد يفرضها عليه الاتحاد البرتغالي لكرة القدم.','["وأشار رونالد إلى أنه سيكون متاحاً للعودة إلى المنتخب بعد تنفيذه العقوبة، في حال كان جاهزاً بدنياً.","وتتيح اللوائح البرتغالية إيقاف اللاعب الذي يغادر أو يتغيّب من دون مبرّر عن تدريبات أو مباريات المنتخب، لمدة تتراوح بين شهر وستة أشهر، إلى جانب غرامة مالية، تتراوح بين 500 و1000 يورو."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/hlc9r207o','https://ajel.sa/sports/hlc9r207o','https://ajel.sa/sports/hlc9r207o','https://ajel.sa/sports/hlc9r207o','فريق التحرير','','2026-10-07T12:41:00.000Z','2026-10-07T15:41:00.000Z','2026-10-07T18:59:38.571Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D9%83%D8%B1%D9%8A%D8%B3%D8%AA%D9%8A%D8%A7%D9%86%D9%88-%D8%B1%D9%88%D9%86%D8%A7%D9%84%D8%AF%D9%88-%D8%AE%D9%84%D8%A7%D9%84-%D9%85%D8%A8%D8%A7%D8%B1%D8%A7%D8%A9-%D8%A7%D9%84%D8%A8%D8%B1%D8%AA%D8%BA%D8%A7%D9%84-%D9%88%D9%88%D9%8A%D9%84%D8%B2-9NwiK6t1.webp','/api/media/459b47b1-f295-4bc9-aeba-8c684f0e934f','/api/media/459b47b1-f295-4bc9-aeba-8c684f0e934f?variant=thumbnail','اتجاه لتخفيف العقوبة على رونالدو بعد مغادرته معسكر منتخب البرتغال',1200,675,'valid','published','current','valid',41,'78de356ce393eca2d1a21dd5605679230e54bbc6d0d81b95be661106ed829266','bfd93741fea38ba0694504c11495e6985f3307c65047f3fc1a55dbd18eb939f2','محدّث','2026-10-07T18:59:38.571Z','2026-10-07T20:25:22.794Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["التعليم والتدريب"]','["التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:03:14.164Z',NULL,1,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('ecac90f1-d21b-4c36-84eb-b5532aa6d7c5','news-ecac90f1-d21b-4c36-84eb-b5532aa6d7c5','وكالة الأنباء المصرية: تصريحات سموتريتش بشأن سيناء محاولة مكشوفة تحقيقًا لأهداف انتخابية','وكاله الانباء المصريه تصريحات سموتريتش بشان سيناء محاوله مكشوفه تحقيقا لاهداف انتخابيه','وأضاف المصدر أن تصريحات سموتريتش بشأن سيناء وتهجير الفلسطينيين من قطاع غزة تمثل، بحسب تعبيره، "محاولة مكشوفة لاستخدام لهجة تصعيدية فارغة لتحقيق أهداف انتخابية من خلال إطلاق مثل هذه التصريحات".','["رفضت مصر بشكل قاطع الزج باسم سيناء في تصريحات وزير مالية دولة الاحتلال الإسرائيلي بتسلئيل سموتريتش، معتبرة أن ما صدر عنه من تهديدات يأتي في سياق لهجة تصعيدية مرتبطة بأهداف انتخابية.","وقال مصدر مصري مطلع، في تصريحات نقلتها وكالة أنباء الشرق الأوسط المصرية، رداً على استفسارات بشأن تصريحات سموتريتش خلال اليومين الماضيين، إن \"التهديدات الجوفاء\" تتزامن مع احتفالات مصر بالذكرى الـ53 لنصر أكتوبر، مؤكداً أن ذلك \"تنتفي معه الحاجة لأية تأكيدات بشأن قدرة مصر على حماية أراضيها وحفظ استقلالها في مواجهة أية أخطار\".","وكان سموتريتش قد قال، خلال مقابلة مصورة مع موقع إسرائيلي، إن مصر إذا هاجمت إسرائيل \"فلن تكون هناك سيناء\"، مضيفاً أن هذا السيناريو \"لن يحدث مرة أخرى\"."]','التقنية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/mind0vj6y','https://ajel.sa/international/mind0vj6y','https://ajel.sa/international/mind0vj6y','https://ajel.sa/international/mind0vj6y','فريق التحرير','الجوف','2026-10-07T13:02:00.000Z','Wed, 07 Oct 2026 19:26:02 GMT','2026-10-07T19:14:16.127Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D9%85%D8%B5%D8%B1-VnhD_27l.jpg','/api/media/ecac90f1-d21b-4c36-84eb-b5532aa6d7c5','/api/media/ecac90f1-d21b-4c36-84eb-b5532aa6d7c5?variant=thumbnail','وكالة الأنباء المصرية: تصريحات سموتريتش بشأن سيناء محاولة مكشوفة تحقيقًا لأهداف انتخابية',1200,675,'valid','published','current','valid',41,'bff9fb3cd13b8aff8dd3c3d4e2387911b4f78f1ab834836c7750948810270c60','c2653fdd0d0a2ba7ad23266527b2c7495237e01b9eda5e3b33efd93feabd66cc','محدّث','2026-10-07T19:14:16.127Z','2026-10-07T20:25:22.794Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير مالية دولة الاحتلال الإسرائيلي","غزة","الجوف","فلسطين","الشرق الأوسط"]','["وزير مالية دولة الاحتلال الإسرائيلي","الشرق الأوسط"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T19:26:03.407Z',200,1,0,'source_article_available','',NULL,NULL,'body:1661f187cd41359fcfc8a1a949c2652952509fcd60f40eb8ba266eded22c7eea','Wed, 07 Oct 2026 19:26:02 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d72bd26e-273a-4d7d-a29a-23add8373250','news-d72bd26e-273a-4d7d-a29a-23add8373250','نائب رئيس هيئة الأركان اليمنية يشدد على سرعة استكمال إجراءات التعبئة العامة وتجهيز الألوية والوحدات','نائب رئيس هيئه الاركان اليمنيه يشدد علي سرعه استكمال اجراءات التعبئه العامه وتجهيز الالويه والوحدات','جاء ذلك خلال ترأسه اليوم اجتماعاً للجنة المكلفة بتنفيذ توجيهات فخامة الدكتور رشاد محمد العليمي، رئيس مجلس القيادة الرئاسي ، بشأن خطة التعبئة العامة لمنتسبي وزارة الدفاع وتجهيز الألوية والوحدات العسكرية للعمل الفوري، وفق بيان للمركز الإعلامي للقوات المسلحة.','["شدد نائب رئيس هيئة الأركان العامة اللواء الركن أحمد البصر على سرعة استكمال إجراءات التعبئة العامة، وتجهيز الألوية والوحدات وفقاً للخطط والتوجيهات المعتمدة، مؤكداً أهمية رفع مستوى الجاهزية والانضباط، وتعزيز التنسيق بين مختلف الهيئات والدوائر العسكرية وقادة الوحدات. جاء ذلك خلال ترأسه اليوم اجتماعاً للجنة المكلفة بتنفيذ توجيهات فخامة الدكتور رشاد محمد العليمي، رئيس مجلس القيادة الرئاسي ، بشأن خطة التعبئة العامة لمنتسبي وزارة الدفاع وتجهيز الألوية والوحدات العسكرية للعمل الفوري، وفق بيان للمركز الإعلامي للقوات المسلحة. تناول الاجتماع الإجراءات والترتيبات اللازمة لتنفيذ خطة التعبئة العامة، ومستوى جاهزية الوحدات العسكرية واحتياجاتها البشرية والتدريبية واللوجستية.","وأكد اللواء البصر ضرورة حصر الاحتياجات واستكمال توفير المتطلبات اللازمة، بما يمكن الوحدات من أداء مهامها وواجباتها بكفاءة، مشيراً إلى أن المرحلة الراهنة تتطلب مضاعفة الجهود والالتزام بالتعليمات العسكرية، ورفع مستوى الاستعداد والجاهزية.. مشيرا إلى أهمية المتابعة المستمرة لتنفيذ ما تم إقراره، ومعالجة أوجه القصور، وتسريع استكمال الإجراءات المتعلقة بالتعبئة والتجهيز."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/m7vwv05jx','https://ajel.sa/international/m7vwv05jx','https://ajel.sa/international/m7vwv05jx','https://ajel.sa/international/m7vwv05jx','فريق التحرير','','2026-10-07T13:00:00.000Z','Wed, 07 Oct 2026 19:26:02 GMT','2026-10-07T19:14:16.164Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/featured-crop-iJ_z3LxG.png','/api/media/d72bd26e-273a-4d7d-a29a-23add8373250','/api/media/d72bd26e-273a-4d7d-a29a-23add8373250?variant=thumbnail','نائب رئيس هيئة الأركان اليمنية يشدد على سرعة استكمال إجراءات التعبئة العامة وتجهيز الألوية والوحدات',1200,675,'valid','published','current','valid',41,'8a03f1eefe3132c3c400a7028ac0e58f5d86665bfc8a99663fc33222cfb56fed','c377366fdcc34bb7cb4b88c9b4e955da863072ab6d0dcf47a454c9c7cef8ae06','محدّث','2026-10-07T19:14:16.164Z','2026-10-07T20:25:22.794Z','','',0,0,'gulf_arab','عادي',54,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الأركان اليمنية يشدد على","مجلس القيادة الرئاسي بشأن خطة","رئيس هيئة الأركان اليمنية يشدد","وزارة الدفاع وتجهيز الألوية والوحدات","التعليم والتدريب","اليمن"]','["هيئة الأركان اليمنية يشدد على","مجلس القيادة الرئاسي بشأن خطة","رئيس هيئة الأركان اليمنية يشدد","وزارة الدفاع وتجهيز الألوية والوحدات","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T19:26:03.610Z',200,1,0,'source_article_available','',NULL,NULL,'body:cc3734171e9ab654a921ab350fcb65bc3e718320295dd82971aaebdb02ec920f','Wed, 07 Oct 2026 19:26:02 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('648e39eb-2e28-41b1-b6e5-af8b3aae9bb3','news-648e39eb-2e28-41b1-b6e5-af8b3aae9bb3','التجارب اللافتة في «معرض الصقور والصيد السعودي الدولي 2026» بعيون زواره وعارضيه وصقاريه','التجارب اللافته في معرض الصقور والصيد السعودي الدولي 2026 بعيون زواره وعارضيه وصقاريه','تنوعت التجارب الجديدة التي لفتت انتباه زوار وعارضين وصقارين في معرض الصقور والصيد السعودي الدولي 2026، من تجربة التصوير المجانية إلى تنظيم منطقة الصقور وسهولة التنقل بين الأجنحة، حيث كشفت آراؤهم عن تعدد عناصر التجربة التي استوقفتهم هذا العام؛ إذ اهتمت الأسر بتنوع الأنشطة، ورصد العارضون تطور التجهيزات وفرص التواصل، وأشاد الصقارون بترتيب منطقتهم، لترسم هذه…','["وأوضح الزائر عبدالله المطيري ، الذي حضر برفقة أسرته، أن تجربة التصوير المجانية كانت من أبرز الأنشطة التي استوقفته، مشيرًا إلى صعوده إلى الموقع المخصص لها وحصوله على صور مميزة، وبيّن أن أجنحة الصقور والمحميات والسيارات استحوذت على اهتمامه، وأن تنوع المعروضات والفعاليات، وجودة التنظيم، منحا أسرته زيارةً ثريةً وممتعةً.","من جانبه، أوضح العارض غيّيرمو غاري ممثل شركة \"يورو فالكونري\" الإسبانية، أن أبرز ما لفت انتباهه هو التطور الواضح في مستوى المعرض والاهتمام بالتفاصيل، وأشار إلى أن الأجواء تتيح تبادل الخبرات وبناء علاقات جديدة، وتمنح الزوار تجربةً أكثر ثراءً، مؤكدًا أن التحسن المستمر يعكس جهودًا ملموسةً ورؤيةً طموحةً للمستقبل.","وفي منطقة الصقور، بيّن الصقار مشاري الرشيدي أن التنظيم كان أبرز ما استوقفه هذا العام، مشيدًا بترتيب المنطقة والحضور والإقبال، وأشار إلى وجود 32 صقرًا من الحر المنغولي و44 صقرًا من الجيري بيور، تابعة لمزرعة إنتاج \"نوفا فالكون\"، معربًا عن تفاؤله بمزيد من التطور والنجاح.","من جهته، أشار العارض إسلام محروس مدير المبيعات بشركة الحضيرة الإماراتية ومسؤول جناحها، إلى أن التنظيم والإقبال شكّلا أبرز ملامح تجربته هذا العام، موضحًا أن أعداد الزوار فاقت توقعاته، وبيّن أن مستوى الترتيبات يمنح العارضين والزوار تجربةً مميزةً، ويعزز مكانة المعرض منصةً تجمع المهتمين بمنظومة الصيد والصقارة.","بدوره، أوضح العارض حسن عمر مسؤول جناح شركة فيتا فارم قطر ، أن جودة التجهيزات وسهولة التنقل وحسن التنظيم كانت أكثر ما لفت انتباهه، وأشاد بسلاسة الأداء، وبحرص القائمين على المعرض على تقديم إضافات وتحسينات متواصلة عامًا بعد عام.","وبيّن الزائر السوري محمد عبيد، أن ترتيب المناطق والأجنحة وتنوعها وجاذبية أسعارها استوقفته خلال الزيارة، مشيرًا إلى أجواء مريحة وفعاليات أتاحت له الاستفادة والاستمتاع، ومنحت تجربته قيمةً واضحةً.","وتبرز هذه الآراء ارتباط ثراء الزيارة بتكامل الأنشطة وجودة التنظيم وفرص التواصل، في معرض ينظمه المركز الوطني للصقور بمركز الرياض للمعارض والمؤتمرات بمَلهم شمال الرياض، خلال الفترة من 1 إلى 10 أكتوبر، ويجمع الصقور والصيد والمغامرات والرحلات والتجارب الثقافية والمعرفية، بما يمنح شعار \"وجهة للجميع\" حضورًا ملموسًا في تجارب المشاركين."]','الثقافة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/1h7m7ra2v','https://ajel.sa/local/1h7m7ra2v','https://ajel.sa/local/1h7m7ra2v','https://ajel.sa/local/1h7m7ra2v','فريق التحرير','الرياض','2026-10-07T13:21:00.000Z','2026-10-07T16:22:00.000Z','2026-10-07T19:26:39.049Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/WhatsAppImage2026-10-07at91826PM1-crop-ecjyEkxj.jpg','/api/media/648e39eb-2e28-41b1-b6e5-af8b3aae9bb3','/api/media/648e39eb-2e28-41b1-b6e5-af8b3aae9bb3?variant=thumbnail','التجارب اللافتة في «معرض الصقور والصيد السعودي الدولي 2026» بعيون زواره وعارضيه وصقاريه',1200,675,'valid','published','current','valid',41,'2f017894ee0944eb109f2eb9bdfd4047ed638a87577e77fcc4eeda0d00ea4266','cb662f8c95385f2155591a2f9227403be53d5ef7844a9ac45a204e8cb0188c02','محدّث','2026-10-07T19:26:39.049Z','2026-10-07T20:25:22.794Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["شركة يورو فالكونري الإسبانية أن","الثقافة والفنون","الرياض"]','["شركة يورو فالكونري الإسبانية أن","الثقافة والفنون"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:31:56.073Z',NULL,2,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('39275f6e-df54-4b85-86fe-80b1fdff7795','news-39275f6e-df54-4b85-86fe-80b1fdff7795','مسؤولو الفدرالي يتوقعون رفع أسعار الفائدة مجدداً قبل نهاية العام لكبح التضخم','مسؤولو الفدرالي يتوقعون رفع اسعار الفائده مجددا قبل نهايه العام لكبح التضخم','توقع مسؤولو الفدرالي الأمريكي رفع أسعار الفائدة مجدداً قبل نهاية العام لكبح التضخم الذي تجاوز الهدف لأكثر من 5 سنوات. وكان صانعو السياسة النقدية في مجلس الاحتياطي الفيدرالي ، انقسموا الشهر الماضي حول مبررات رفع أسعار الفائدة بين مؤيد ومعارض، وفق " العربية ".','["توقع مسؤولو الفدرالي الأمريكي رفع أسعار الفائدة مجدداً قبل نهاية العام لكبح التضخم الذي تجاوز الهدف لأكثر من 5 سنوات.","وكان صانعو السياسة النقدية في مجلس الاحتياطي الفيدرالي ، انقسموا الشهر الماضي حول مبررات رفع أسعار الفائدة بين مؤيد ومعارض، وفق \" العربية \".","وقد يقود ذلك إلى نقاش حاد في اجتماع السياسة النقدية المقرر عقده في 27 و28 أكتوبر الجاري بشأن ما إذا كان التضخم اتخذ بعدا أوسع نطاقا مدفوعا بالطلب يستدعي اتخاذ مجلس الاحتياطي المزيد من الإجراءات في الوقت الحالي."]','الاقتصاد','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/fjamo5zql','https://ajel.sa/economy/fjamo5zql','https://ajel.sa/economy/fjamo5zql','https://ajel.sa/economy/fjamo5zql','فريق التحرير','','2026-10-07T13:15:00.000Z','2026-10-07T16:15:00.000Z','2026-10-07T19:26:39.837Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/featured-crop--N0c0fFH.png','/api/media/39275f6e-df54-4b85-86fe-80b1fdff7795','/api/media/39275f6e-df54-4b85-86fe-80b1fdff7795?variant=thumbnail','مسؤولو الفدرالي يتوقعون رفع أسعار الفائدة مجدداً قبل نهاية العام لكبح التضخم',1200,675,'valid','published','current','valid',41,'7df5949e03de07a9a749ac42cab84ffd18c7c1a839af1db80e1eeeeb22218929','4c08b69407e9aff7740cc77faad3a61f0a94b703f7ebf9e03816c65a1444f810','محدّث','2026-10-07T19:26:39.837Z','2026-10-07T20:25:22.794Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس الاحتياطي الفيدرالي انقسموا الشهر","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','["مجلس الاحتياطي الفيدرالي انقسموا الشهر","الاقتصاد والأسواق","السياسة والعلاقات الدولية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:31:56.077Z',NULL,2,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('57bd123c-c8e1-4fdd-beb6-c43e409cab0f','news-57bd123c-c8e1-4fdd-beb6-c43e409cab0f','الصحة: 4 إجراءات لازمة قبل التبرع بالدم','الصحه 4 اجراءات لازمه قبل التبرع بالدم','وأضافت الوزارة عبر حسابها "عش بصحة" بمنصة (إكس) أنه قبل التبرع بالدم ينبغي تناول وجبة خفيفة وصحية وشرب 500 مل من الماء وتجنب التمارين الشديدة مثل رفع الأثقال وأخذ قسط كاف من النوم من سبع إلى تسع ساعات ليلة التبرع.','["أوضحت وزارة الصحة الاستعدادات اللازمة قبل التبرع بالدم.","وأضافت الوزارة أنه ينبغي المبادرة بالتبرع بالدم وحجز موعد عن طريق \"صحتي\" أو التوجه إلى أقرب مركز للتبرع بالدم، مشيرة إلى أن الاستعداد قبل التبرع يجعل التجربة أكثر راحة وأمانًا."]','الصحة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/misc/7v6dzik3l','https://ajel.sa/misc/7v6dzik3l','https://ajel.sa/misc/7v6dzik3l','https://ajel.sa/misc/7v6dzik3l','فريق التحرير','عسير','2026-10-07T13:15:00.000Z','2026-10-07T16:15:00.000Z','2026-10-07T19:26:39.91