INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('68c48e82-11f5-4c9e-b023-53bac833b00e','news-68c48e82-11f5-4c9e-b023-53bac833b00e','تراجع أسعار النفط الأمريكي 1.30% إلى 88.28 دولارا للبرميل','تراجع اسعار النفط الامريكي 1 30 الي 88 28 دولارا للبرميل','تراجعت العقود الآجلة للنفط الخام الأمريكي 1.30% إلى 88.28 دولارا للبرميل عند التسوية. وكانت قد ارتفعت أسعار النفط، اليوم الأربعاء، بينما يوازن المتعاملون بين زيادة التدفقات عبر مضيق هرمز وتصاعد الهجمات الإيرانية على السفن.','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","تراجعت العقود الآجلة للنفط الخام الأمريكي 1.30% إلى 88.28 دولارا للبرميل عند التسوية.","وكانت قد ارتفعت أسعار النفط، اليوم الأربعاء، بينما يوازن المتعاملون بين زيادة التدفقات عبر مضيق هرمز وتصاعد الهجمات الإيرانية على السفن.","وصعدت العقود الآجلة لخام برنت 93 سنتاً، أو 0.92 في المائة، إلى 101.51 دولار للبرميل، فيما ارتفع خام غرب تكساس الوسيط 82 سنتاً، أو 0.92 في المائة، إلى 90.25 دولار."]','الطاقة والصناعة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/economy/k78frr2ry','https://ajel.sa/economy/k78frr2ry','https://ajel.sa/economy/k78frr2ry','https://ajel.sa/economy/k78frr2ry','فريق التحرير','','2026-10-07T13:34:00.000Z','2026-10-07T13:34:00.000Z','2026-10-07T21:12:42.267Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/%D8%A7%D9%84%D9%86%D9%81%D8%B7-2-1kDswY2Q.jpg','/api/media/68c48e82-11f5-4c9e-b023-53bac833b00e','/api/media/68c48e82-11f5-4c9e-b023-53bac833b00e?variant=thumbnail','تراجع أسعار النفط الأمريكي 1.30% إلى 88.28 دولارا للبرميل',1200,675,'valid','published','current','valid',46,'9accf132f8179d4ad560edf4ef270d1a9d370b1f301985402babf51edfd682a4','652e95f9803a06696148ed10aa35ba638780f6731f223d6b3b9f7ba667646e5b','محدّث','2026-10-07T19:45:38.558Z','2026-10-07T21:12:42.691Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الطاقة والنفط","إيران"]','["الطاقة والنفط"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Temporarily Unreachable','2026-10-07T19:49:56.264Z',NULL,2,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('95d21cf8-c391-456c-959b-1ea2964f0bc5','news-95d21cf8-c391-456c-959b-1ea2964f0bc5','في مباراة الوداع.. اتهام ميسي بالعنصرية بعد سلوكه مع لاعب بنين','في مباراه الوداع اتهام ميسي بالعنصريه بعد سلوكه مع لاعب بنين','واجه نجم منتخب الأرجنتين ليونيل ميسي ، اتهامات بالعنصرية، بعد أن بدا على ملامحه علامات الانزعاج والغضب إزاء محاولة لاعب من منتخب بنين التقاط صورة تذكارية معه. وودع ليونيل ميسي منتخب الأرجنتين بطريقته الخاصة، فجر الأربعاء، بفوز 3-0 على بنين في ملعب (مونومنتال)، سجل فيه هدفاً من ركلة جزاء وصنع هدفين.','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","واجه نجم منتخب الأرجنتين ليونيل ميسي ، اتهامات بالعنصرية، بعد أن بدا على ملامحه علامات الانزعاج والغضب إزاء محاولة لاعب من منتخب بنين التقاط صورة تذكارية معه.","وبدا الانزعاج واضحاً على وجه ميسي، وهو يحاول التملص بلطف في البداية، قبل أن تظهر عليه علامات الغضب ويرفض الطلب ويطلب أن يُترك وشأنه.","وودع ليونيل ميسي منتخب الأرجنتين بطريقته الخاصة، فجر الأربعاء، بفوز 3-0 على بنين في ملعب (مونومنتال)، سجل فيه هدفاً من ركلة جزاء وصنع هدفين.","وبعد صافرة النهاية، تحول ملعب (مونومنتال) إلى ساحة لتبادل القمصان والصور التذكارية، حيث تهافت لاعبو بنين على ميسي لالتقاط لحظة أخيرة مع أحد أفضل لاعبي كرة القدم في التاريخ.","وأظهر مقطع فيديو لاعباً بنينياً يلاحق ميسي بإصرار شديد للحصول على صورة (سيلفي)، بينما كان ميسي يحاول مغادرة الملعب والتوجه لحفل الوداع."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/6q60gcdyj','https://ajel.sa/sports/6q60gcdyj','https://ajel.sa/sports/6q60gcdyj','https://ajel.sa/sports/6q60gcdyj','فريق التحرير','','2026-10-07T13:30:00.000Z','2026-10-07T16:30:00.000Z','2026-10-07T19:45:39.858Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/%D8%A8%D9%86%D9%8A%D9%86-PnMAelWp.jpg','/api/media/95d21cf8-c391-456c-959b-1ea2964f0bc5','/api/media/95d21cf8-c391-456c-959b-1ea2964f0bc5?variant=thumbnail','في مباراة الوداع.. اتهام ميسي بالعنصرية بعد سلوكه مع لاعب بنين',1200,675,'valid','published','current','valid',41,'7ac82a1880b604971e200b0e1207683747b1759f27ee8f36a36089b2c9878823','02407f484eb1d28ef8d3a5727a2fd27ccc846edad14729409bc18d2a6e73b89d','محدّث','2026-10-07T19:45:39.858Z','2026-10-07T20:25:22.794Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:49:56.266Z',NULL,2,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('c1868901-57fb-46d0-8518-d8af89a6bae1','news-c1868901-57fb-46d0-8518-d8af89a6bae1','وزير الحرب الأمريكي: حاملة الطائرات "لينكولن" أغرقت 64 سفينة حربية إيرانية','وزير الحرب الامريكي حامله الطائرات لينكولن اغرقت 64 سفينه حربيه ايرانيه','قال وزير الحرب الأمريكي، بيت هيجسيث، إن حاملة الطائرات "لينكولن" أغرقت 64 سفينة حربية إيرانية. وكان نائب الرئيس الأمريكي، جيه دي فانس ، قد أشار في وقت سابق إلى إن على إيران تخفيض قدراتها النووية على نحو "ملموس" لإنهاء الحرب.','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","قال وزير الحرب الأمريكي، بيت هيجسيث، إن حاملة الطائرات \"لينكولن\" أغرقت 64 سفينة حربية إيرانية.","وأشار هيجسيث إلى أن \"لينكولن\" نفذت 3693 طلعة جوية قتالية ضد إيران ، وفقا لـ\"العربية\".","وكان نائب الرئيس الأمريكي، جيه دي فانس ، قد أشار في وقت سابق إلى إن على إيران تخفيض قدراتها النووية على نحو \"ملموس\" لإنهاء الحرب."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/7htpskud4','https://ajel.sa/international/7htpskud4','https://ajel.sa/international/7htpskud4','https://ajel.sa/international/7htpskud4','فريق التحرير','','2026-10-07T13:22:00.000Z','2026-10-07T16:22:00.000Z','2026-10-07T19:45:41.334Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D9%88%D8%B2%D9%8A%D8%B1-%D8%A7%D9%84%D8%AD%D8%B1%D8%A8-ptZ1655Y.jpg','/api/media/c1868901-57fb-46d0-8518-d8af89a6bae1','/api/media/c1868901-57fb-46d0-8518-d8af89a6bae1?variant=thumbnail','وزير الحرب الأمريكي: حاملة الطائرات "لينكولن" أغرقت 64 سفينة حربية إيرانية',1200,675,'valid','published','current','valid',41,'6b446262d7a0cb8ed2dfd0d6039162489bfb47560d60652dd1ab57e3a3281368','4d6b5204097161cc9e5de4fb4f9d62ddd41e28122c9c4c1a93540d560dd8baa4','محدّث','2026-10-07T19:45:41.334Z','2026-10-07T20:25:22.794Z','','',0,0,'international','عادي',44,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الحرب الأمريكي حاملة الطائرات","إيران"]','["وزير الحرب الأمريكي حاملة الطائرات"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T19:49:56.280Z',NULL,2,2,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('babdca8f-b1c3-47d1-b43d-75b99437a76e','news-babdca8f-b1c3-47d1-b43d-75b99437a76e','الدفاع السورية: أحبطنا محاولة تهريب على الحدود مع لبنان بريف دمشق','الدفاع السوريه احبطنا محاوله تهريب علي الحدود مع لبنان بريف دمشق','أعلنت وزارة الدفاع السورية ، الأربعاء، أن قوى حرس الحدود في جرد فليطة غرب دمشق ، أحبطت محاولة تهريب أسلحة على الحدود السورية اللبنانية، إثر كمين محكم تم تنفيذه بدقة.','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","وقالت إدارة الإعلام والاتصال في الوزارة إن \"العملية أسفرت عن إلقاء القبض على أربعة أشخاص بينهم اثنان من الجنسية اللبنانية، وضبط كمية من الأسلحة والذخائر المتنوعة، حيث جرى تحويلهم إلى الجهات المختصة لاتخاذ الإجراءات القانونية اللازمة بحقهم\".","ومنذ الإطاحة بحكم بشار الأسد أواخر 2024، يعمل الجانبان اللبناني والسوري على ضبط التهريب عبر حدودهما المشتركة الممتدة على طول 330 كيلومتراً، بما يشمل الأسلحة وحبوب الكبتاغون المخدرة."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/501g1axtb','https://ajel.sa/international/501g1axtb','https://ajel.sa/international/501g1axtb','https://ajel.sa/international/501g1axtb','فريق التحرير','','2026-10-07T13:58:00.000Z','2026-10-07T13:58:00.000Z','2026-10-07T21:22:42.487Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/%D8%B3%D9%88%D8%B1%D9%8A%D8%A7-b47Ua55i.jpg','/api/media/babdca8f-b1c3-47d1-b43d-75b99437a76e','/api/media/babdca8f-b1c3-47d1-b43d-75b99437a76e?variant=thumbnail','الدفاع السورية: أحبطنا محاولة تهريب على الحدود مع لبنان بريف دمشق',1200,675,'valid','published','current','valid',41,'5f6441f242ca423d3f35bef67948c6f70b5275e430072929ef8431a8fba9d703','bdf12c5f9c600a827c3f5cc16b715e186434f37970e94553d11ba2d47902b87a','محدّث','2026-10-07T20:12:39.814Z','2026-10-07T21:22:43.253Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["وزارة الدفاع السورية الأربعاء أن","السفر والسياحة","لبنان"]','["وزارة الدفاع السورية الأربعاء أن","السفر والسياحة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T20:16:18.374Z',NULL,1,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e7925844-a753-4e6f-b87d-f1c3f824e345','news-e7925844-a753-4e6f-b87d-f1c3f824e345','وزير الدفاع المدني: صنعاء ستكون تحت السيطرة بوقت حددته القيادة السياسية','وزير الدفاع المدني صنعاء ستكون تحت السيطره بوقت حددته القياده السياسيه','قال وزير الدفاع اليمني الفريق الركن طاهر العقيلي، إن صنعاء ستكون تحت السيطرة بوقت حددته القيادة السياسية. وأضاف الوزير، إننا ملتزمون بمبادئ القانون الدولي بينما الحوثيون يستخدمون المواطنين دروعا بشرية، وحققنا السيطرة الكاملة في جبهات الوازعية .','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","قال وزير الدفاع اليمني الفريق الركن طاهر العقيلي، إن صنعاء ستكون تحت السيطرة بوقت حددته القيادة السياسية.","وأضاف الوزير، إننا ملتزمون بمبادئ القانون الدولي بينما الحوثيون يستخدمون المواطنين دروعا بشرية، وحققنا السيطرة الكاملة في جبهات الوازعية .","كان الرئيس الدكتور رشاد محمد العليمي، رئيس مجلس القيادة الرئاسي اليمني، أكد أن معركة القوات المسلحة تتطلب جبهة سياسية وشعبية وإعلامية متماسكة، تعمل بأدواتها المشروعة على رفع معنويات المواطنين، وتعزيز الثقة بالدولة، ومواجهة المعلومات المضللة، ومنع المليشيات من تحويل التطورات الميدانية المؤقتة إلى مكاسب سياسية أو نفسية."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/d532fvl96','https://ajel.sa/international/d532fvl96','https://ajel.sa/international/d532fvl96','https://ajel.sa/international/d532fvl96','فريق التحرير','','2026-10-07T13:54:00.000Z','2026-10-07T13:54:00.000Z','2026-10-07T21:22:43.912Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/featured-crop-2aRpX0Bc.png','/api/media/e7925844-a753-4e6f-b87d-f1c3f824e345','/api/media/e7925844-a753-4e6f-b87d-f1c3f824e345?variant=thumbnail','وزير الدفاع المدني: صنعاء ستكون تحت السيطرة بوقت حددته القيادة السياسية',1200,675,'valid','published','current','valid',41,'7b2e3646f398620d12aaadb7095e6272cf44da6b96324c05405454d2a82f559b','a6b60299c2d8a18f1d74c74937a3bf49a679224e7b6baf58f44162bd90041da3','محدّث','2026-10-07T20:12:40.963Z','2026-10-07T21:22:44.301Z','','',0,0,'gulf_arab','عادي',41,NULL,0,0,0,'',NULL,NULL,NULL,'["وزير الدفاع المدني صنعاء ستكون","مجلس القيادة الرئاسي اليمني أكد","رئيس مجلس القيادة الرئاسي اليمني","اليمن"]','["وزير الدفاع المدني صنعاء ستكون","مجلس القيادة الرئاسي اليمني أكد","رئيس مجلس القيادة الرئاسي اليمني"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T20:16:18.380Z',NULL,1,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('d0cdcfcc-ba5e-48e1-8ecc-da913d0f8762','news-d0cdcfcc-ba5e-48e1-8ecc-da913d0f8762','الهلال الأحمر بالباحة يتلقى أكثر من 1722 بلاغا خلال شهر سبتمبر 2026م','الهلال الاحمر بالباحه يتلقي اكثر من 1722 بلاغا خلال شهر سبتمبر 2026م','تلقت هيئة الهلال الأحمر السعودي بمنطقة الباحة أكثر من 1722 بلاغا إسعافيا خلال شهر سبتمبر الماضي، باشرتها الفرق الإسعافية في مختلف محافظات المنطقة. وأوضحت الهيئة أن الحالات المرضية بلغت 1468 حالة، فيما سجلت الحوادث المرورية 254 حالة، تعاملت معها الفرق الإسعافية بكفاءة عالية، من خلال كوادر إسعافية متخصصة وآليات مجهزة بأحدث التقنيات والتجهيزات الطبية…','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","تلقت هيئة الهلال الأحمر السعودي بمنطقة الباحة أكثر من 1722 بلاغا إسعافيا خلال شهر سبتمبر الماضي، باشرتها الفرق الإسعافية في مختلف محافظات المنطقة.","وأوضحت الهيئة أن الحالات المرضية بلغت 1468 حالة، فيما سجلت الحوادث المرورية 254 حالة، تعاملت معها الفرق الإسعافية بكفاءة عالية، من خلال كوادر إسعافية متخصصة وآليات مجهزة بأحدث التقنيات والتجهيزات الطبية والإسعافية.","وأكد المدير العام لفرع هيئة الهلال الأحمر السعودي بمنطقة الباحة، الأستاذ سلطان بن سعد المالكي، أن هذه الجهود تأتي ضمن منظومة عمل متكاملة تهدف إلى تعزيز سرعة الاستجابة ورفع جودة الخدمات الإسعافية المقدمة للمستفيدين، مشيرا إلى أن طلب الخدمة الإسعافية يتم عبر الرقم (997)، أو من خلال تطبيق “أسعفني”، الذي يتيح تحديد موقع الحالة بدقة وتتبع البلاغ، بما يسهم في تسريع وصول الفرق الإسعافية ورفع كفاءة التدخل في الحالات الطارئة.","وأشار إلى أن الهيئة تواصل جهودها في تطوير منظومة العمل الإسعافي ورفع جاهزية الفرق الميدانية، بما يعزز من كفاءة الاستجابة للبلاغات ويوفر خدمات إسعافية ذات جودة عالية في مختلف محافظات المنطقة.","يذكر أن هيئة الهلال الأحمر السعودي بمنطقة الباحة تقدم خدماتها الإسعافية عبر قطاعين تشغيليين، هما قطاع السراة وقطاع تهامة، ويضمان (16) مركزا إسعافيا تعمل على مدار الساعة، بما يسهم في تعزيز التغطية الإسعافية وسرعة الوصول إلى الحالات الطارئة في مختلف محافظات المنطقة."]','المجتمع','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/p8yxnyxnr','https://ajel.sa/local/p8yxnyxnr','https://ajel.sa/local/p8yxnyxnr','https://ajel.sa/local/p8yxnyxnr','عبير الفهد','الباحة','2026-10-07T13:55:00.000Z','2026-10-07T13:55:00.000Z','2026-10-07T21:22:43.878Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/1-crop-ZTvz4yFv.jpg','/api/media/d0cdcfcc-ba5e-48e1-8ecc-da913d0f8762','/api/media/d0cdcfcc-ba5e-48e1-8ecc-da913d0f8762?variant=thumbnail','الهلال الأحمر بالباحة يتلقى أكثر من 1722 بلاغا خلال شهر سبتمبر 2026م',1200,675,'valid','published','current','valid',41,'3536da59c081e2161eccd7a6c6f3169086aadcf3c424137300711545138f672e','86b2d916aacb3ffc57f058ddf791a30dc7da126664530cf8da92f25a68e10571','محدّث','2026-10-07T20:12:41.294Z','2026-10-07T21:22:44.275Z','','',0,0,'saudi_region','عادي',59,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة الهلال الأحمر السعودي بمنطقة","الصحة العامة","الباحة"]','["هيئة الهلال الأحمر السعودي بمنطقة","الصحة العامة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T20:16:18.378Z',NULL,1,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('490c98a8-c2d1-4231-8a09-1da621d06a98','news-490c98a8-c2d1-4231-8a09-1da621d06a98','محور تعز العسكري: قواتنا تخوض معارك عنيفة ضد ميليشيا الحوثي الإرهابية في جبل هان','محور تعز العسكري قواتنا تخوض معارك عنيفه ضد ميليشيا الحوثي الارهابيه في جبل هان','قال محور تعز العسكري، إن قواتنا مسنودة ب المقاومة الشعبية تخوض معارك عنيفة ضد ميليشيا الحوثي الإرهابية في جبل هان غربي تعز. وأضاف، أن المعارك ضد مليشيا الحوثي متواصلة وهي الأعنف بين قواتنا وميليشيا الحوثي في جبهتي جبل حبشي و الأقروض ، وفق " الحدث ".','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","قال محور تعز العسكري، إن قواتنا مسنودة ب المقاومة الشعبية تخوض معارك عنيفة ضد ميليشيا الحوثي الإرهابية في جبل هان غربي تعز.","وأضاف، أن المعارك ضد مليشيا الحوثي متواصلة وهي الأعنف بين قواتنا وميليشيا الحوثي في جبهتي جبل حبشي و الأقروض ، وفق \" الحدث \".","وسياسيا بحث رئيس مجلس القيادة الرئاسي رشاد العليمي مع قيادة التكتل الوطني للأحزاب برئاسة أحمد عبيد بن دغر سبل دعم عملية فجر اليمن سياسياً ومجتمعياً، حيث تمثل مرحلة جديدة في مسار استعادة مؤسسات الدولة وتحرير الأراضي اليمنية وصولاً إلى العاصمة صنعاء ."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/awblm9zru','https://ajel.sa/international/awblm9zru','https://ajel.sa/international/awblm9zru','https://ajel.sa/international/awblm9zru','فريق التحرير','','2026-10-07T13:53:00.000Z','2026-10-07T13:53:00.000Z','2026-10-07T21:22:43.893Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%A7%D9%84%D8%AC%D9%8A%D8%B4-%D8%A7%D9%84%D9%8A%D9%85%D9%86%D9%8A-%D9%81%D9%8A-%D9%85%D8%A3%D8%B1%D8%A8-_E19uGjd.webp','/api/media/490c98a8-c2d1-4231-8a09-1da621d06a98','/api/media/490c98a8-c2d1-4231-8a09-1da621d06a98?variant=thumbnail','محور تعز العسكري: قواتنا تخوض معارك عنيفة ضد ميليشيا الحوثي الإرهابية في جبل هان',1200,675,'valid','published','current','valid',41,'43532d8d1bcae15e8ab9016f05692526f3ee64737a28cb4076b6f809cb5b19de','ac241580a2d788d0f3b8c4f6cf9a54a9924c7734d2c7c762590ab6315433632d','محدّث','2026-10-07T20:12:42.836Z','2026-10-07T21:22:44.387Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس القيادة الرئاسي رشاد","مجلس القيادة الرئاسي رشاد العليمي","اليمن"]','["رئيس مجلس القيادة الرئاسي رشاد","مجلس القيادة الرئاسي رشاد العليمي"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T20:16:18.383Z',NULL,1,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1f6f5a92-c465-4f50-9d7e-3cde2e2081ed','news-1f6f5a92-c465-4f50-9d7e-3cde2e2081ed','المجلس الأعلى للقضاء يعتمد قواعد عمل المكاتب الفنية ويوافق على إنشاء محكمة للتنفيذ','المجلس الاعلي للقضاء يعتمد قواعد عمل المكاتب الفنيه ويوافق علي انشاء محكمه للتنفيذ','عقد المجلس الأعلى للقضاء اجتماعًا في مقر المجلس، برئاسة فضيلة رئيس المجلس الأعلى للقضاء المكلف الشيخ الدكتور وليد بن محمد الصمعاني، وبحضور أصحاب المعالي والفضيلة والسعادة أعضاء المجلس.','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","عقد المجلس الأعلى للقضاء اجتماعًا في مقر المجلس، برئاسة فضيلة رئيس المجلس الأعلى للقضاء المكلف الشيخ الدكتور وليد بن محمد الصمعاني، وبحضور أصحاب المعالي والفضيلة والسعادة أعضاء المجلس. وفي مستهل الاجتماع، رفع المجلس الشكر والتقدير لخادم الحرمين الشريفين الملك سلمان بن عبدالعزيز آل سعود، ولصاحب السمو الملكي الأمير محمد بن سلمان بن عبدالعزيز ولي العهد رئيس مجلس الوزراء -حفظهما الله- بمناسبة صدور تعديلات عدد من مواد نظام القضاء، مؤكدًا أن ما يحظى به المرفق العدلي من دعم واهتمام من القيادة الرشيدة يسهم في مواصلة تطوير العمل القضائي وتعزيز جودته. واعتمد المجلس قواعد عمل المكاتب الفنية، التي تنظم إعداد الدراسات ومسودات الأحكام ومراجعتها؛ بما يعزز جودة الأحكام ووحدة تطبيق الأنظمة والمبادئ القضائية. وتتيح القواعد الاستعانة بتقنيات الذكاء الاصطناعي المعتمدة، وقياس الأداء ومتابعته، والاستفادة من نتائجه في تطوير برامج التدريب والتأهيل. ووافق المجلس على إنشاء محكمة للتنفيذ تضم دوائر ابتدائية واستئنافية، بما يتوافق مع نظام التنفيذ، ويدعم الرقابة على سير إجراءات التنفيذ، ويرفع كفاءة العمل وقياس الأداء، بالتوازي مع التوسع في أتمتة إجراءات وعمليات التنفيذ والاستفادة من تطبيقات الذكاء الاصطناعي. وناقش المجلس الإجراءات المتعلقة بترقيات القضاة، واستعرض العمل التحضيري لأعماله وآلياته ومؤشراته الإحصائية، وتابع تنفيذ قراراته وتوجيهاته السابقة، واتخذ عددًا من القرارات المتعلقة بالشؤون الوظيفية للقضاة ودعم المحاكم."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/3cdroni6m','https://ajel.sa/local/3cdroni6m','https://ajel.sa/local/3cdroni6m','https://ajel.sa/local/3cdroni6m','فريق التحرير','','2026-10-07T13:53:00.000Z','2026-10-07T13:53:00.000Z','2026-10-07T21:22:45.116Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/featured-crop--hGUid9m.png','/api/media/1f6f5a92-c465-4f50-9d7e-3cde2e2081ed','/api/media/1f6f5a92-c465-4f50-9d7e-3cde2e2081ed?variant=thumbnail','المجلس الأعلى للقضاء يعتمد قواعد عمل المكاتب الفنية ويوافق على إنشاء محكمة للتنفيذ',1200,675,'valid','published','current','valid',99,'c4ae9874356a64a4dcf020beaf003cba39b6ffc2a975a0f7e936bc17e9e0bc39','97d66b04a5ff18a2bea3c63bf42f5fd6def796b76c024a6a126415a53f5c6ff5','محدّث','2026-10-07T20:12:43.010Z','2026-10-07T21:22:45.577Z','','',0,0,'saudi_national','أولوية قصوى',82,NULL,0,0,0,'',NULL,NULL,NULL,'["ولي العهد رئيس مجلس الوزراء","رئيس المجلس الأعلى للقضاء المكلف","مجلس الوزراء -حفظهما الله- بمناسبة","الثقافة والفنون","التعليم والتدريب"]','["ولي العهد رئيس مجلس الوزراء","رئيس المجلس الأعلى للقضاء المكلف","مجلس الوزراء -حفظهما الله- بمناسبة","الثقافة والفنون","التعليم والتدريب"]','classified','','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T20:16:39.972Z',NULL,1,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('3ad313e3-a7d3-4c0d-8852-0469791c9854','news-3ad313e3-a7d3-4c0d-8852-0469791c9854','رونالدو يوجه رسالة احترام لميسي بعد اعتزاله اللعب الدولي مع الأرجنتين','رونالدو يوجه رساله احترام لميسي بعد اعتزاله اللعب الدولي مع الارجنتين','وجه نجم منتخب البرتغال ونادي النصر، كريستيانو رونالدو ، رسالة دافئة للأرجنتيني ليونيل ميسي الذي خاض آخر مباراة له مع منتخب بلاده أمام بنين . لقد كانت رحلة رائعة، مليئة بالفرح وبعض الحزن، لكنني متأكد تمامًا أن كل خطوة خطوتها كانت تستحق العناء".','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","وجه نجم منتخب البرتغال ونادي النصر، كريستيانو رونالدو ، رسالة دافئة للأرجنتيني ليونيل ميسي الذي خاض آخر مباراة له مع منتخب بلاده أمام بنين .","وكتب رونالدو تعليقا على منشور اعتزال ميسي عبر إنستجرام جاء فيه: \"ليو، سنوات طويلة من الدفاع عن وطنك، وقصة ستخلد في الذاكرة. كل احترامي لما حققته مع الأرجنتين . تحية حارة\"","وقال ميسي في منشوره: \"كانت مباراتي الأخيرة أمس، وأشتاق بالفعل لارتداء قميص المنتخب الأزرق السماوي والأبيض. أعلم أنني أتخذ القرار الصائب. لقد كانت رحلة رائعة، مليئة بالفرح وبعض الحزن، لكنني متأكد تمامًا أن كل خطوة خطوتها كانت تستحق العناء\"."]','الرياضة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/q959v2tfe','https://ajel.sa/sports/q959v2tfe','https://ajel.sa/sports/q959v2tfe','https://ajel.sa/sports/q959v2tfe','فريق التحرير','','2026-10-07T13:53:00.000Z','2026-10-07T13:53:00.000Z','2026-10-07T21:22:45.071Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/%D8%B1%D9%88%D9%86%D8%A7%D9%84%D8%AF%D9%88-%D9%88%D9%85%D9%8A%D8%B3%D9%8A-J_M-pW1C.jpg','/api/media/3ad313e3-a7d3-4c0d-8852-0469791c9854','/api/media/3ad313e3-a7d3-4c0d-8852-0469791c9854?variant=thumbnail','رونالدو يوجه رسالة احترام لميسي بعد اعتزاله اللعب الدولي مع الأرجنتين',1200,675,'valid','published','current','valid',41,'2ac7c31b4f3d8dbd109b627b8b9e697106b5f393b990714fd8fdaf24797ad1c6','dde084af3f94d71c85493487d0426c8ab4823045b911335391aed86ccddc60bf','محدّث','2026-10-07T20:12:43.228Z','2026-10-07T21:22:45.440Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الرياضة السعودية"]','["الرياضة السعودية"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T20:16:39.977Z',NULL,1,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('6cb0b2bf-98a7-467d-b733-e31462ef2152','news-6cb0b2bf-98a7-467d-b733-e31462ef2152','هيئة بريطانية: إصابة ناقلة بمقذوفات شمالي مدينة الشمال القطرية','هيئه بريطانيه اصابه ناقله بمقذوفات شمالي مدينه الشمال القطريه','ذكرت هيئة عمليات التجارة البحرية البريطانية اليوم الأربعاء أن ناقلة نفط أصيبت بعدة مقذوفات في واقعة على بعد 51 ميلا بحريا شمالي مدينة الشمال القطرية. وتواصل إيران تهديداتها للسفن المارة ل مضيق هرمز الذي يعد أحد أهم الممرات البحرية في العالم، ويُعد نقطة اختناق رئيسية لحركة تجارة النفط والغاز من منطقة الخليج إلى الأسواق العالمية.','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","ذكرت هيئة عمليات التجارة البحرية البريطانية اليوم الأربعاء أن ناقلة نفط أصيبت بعدة مقذوفات في واقعة على بعد 51 ميلا بحريا شمالي مدينة الشمال القطرية.","وتواصل إيران تهديداتها للسفن المارة ل مضيق هرمز الذي يعد أحد أهم الممرات البحرية في العالم، ويُعد نقطة اختناق رئيسية لحركة تجارة النفط والغاز من منطقة الخليج إلى الأسواق العالمية.","ولهذا تستخدم إيران المضيق كورقة ضغط استراتيجية في مواجهة الولايات المتحدة وحلفائها، خصوصًا عندما تتعرض لعقوبات أو هجمات عسكرية أو إجراءات تستهدف صادراتها النفطية."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/a5k7j1bll','https://ajel.sa/international/a5k7j1bll','https://ajel.sa/international/a5k7j1bll','https://ajel.sa/international/a5k7j1bll','فريق التحرير','','2026-10-07T14:11:00.000Z','2026-10-07T14:11:00.000Z','2026-10-07T21:22:42.453Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/%D9%85%D8%B6%D9%8A%D9%82-%D9%87%D8%B1%D9%85%D8%B2--qfOccIh.png','/api/media/6cb0b2bf-98a7-467d-b733-e31462ef2152','/api/media/6cb0b2bf-98a7-467d-b733-e31462ef2152?variant=thumbnail','هيئة بريطانية: إصابة ناقلة بمقذوفات شمالي مدينة الشمال القطرية',1200,675,'valid','published','current','valid',99,'90cf9005e414ca167e151ff2a39e2b2f7692debba6132c208f5a47592b21627c','08879cc58deb87589abc326bf25c4c5c59d5fe82ce985f0371793457516aa449','محدّث','2026-10-07T20:18:06.885Z','2026-10-07T21:22:42.873Z','','',0,0,'gulf_arab','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["هيئة بريطانية إصابة ناقلة بمقذوفات","الطاقة والنفط","الاقتصاد والأسواق","إيران","الولايات المتحدة"]','["هيئة بريطانية إصابة ناقلة بمقذوفات","الطاقة والنفط","الاقتصاد والأسواق","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Temporarily Unreachable','2026-10-07T20:21:36.342Z',NULL,1,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f59fa535-6c82-48e2-b8b8-f636733c1cd1','news-f59fa535-6c82-48e2-b8b8-f636733c1cd1','‎اللجنة المحلية المنظمة تختتم نسخة ناجحة من "خليجي 27"','اللجنه المحليه المنظمه تختتم نسخه ناجحه من خليجي 27','وثمّنت اللجنة المحلية المنظمة التعاون مع الاتحاد الخليجي لكرة القدم خلال مراحل الإعداد والتنظيم، بما أسهم في تنفيذ متطلبات النسخة السابعة والعشرين من بطولة كأس الخليج العربي لكرة القدم.','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","اختتمت اللجنة المحلية المنظمة لبطولة كأس الخليج العربي لكرة القدم في نسختها السابعة والعشرين \"خليجي الديار العربية 27\"، أعمالها التنظيمية والتشغيلية للبطولة، التي استضافتها مدينة جدة خلال الفترة من 23 سبتمبر حتى 6 أكتوبر 2026، وتُوّج المنتخب السعودي بلقبها بعد فوزه على المنتخب الإماراتي في المباراة النهائية التي أقيمت على ملعب مدينة الملك عبدالله الرياضية بجدة.","ورفعت اللجنة المحلية المنظمة شكرها وتقديرها للمنظومة الرياضية في المملكة، بقيادة صاحب السمو الملكي الأمير عبدالعزيز بن تركي بن فيصل ، وزير الرياضة، رئيس اللجنة الأولمبية والبارالمبية السعودية ، ولكافة المسؤولين في المنظومة الرياضية، على الدعم والمتابعة التي حظيت بها البطولة، وما وفرته من إمكانات أسهمت في نجاح استضافة المملكة للحدث الخليجي وخروجه بالمستوى التنظيمي المأمول.","وأكد رئيس مجلس إدارة اللجنة المحلية المنظمة ياسر المسحل، أن نجاح البطولة جاء ثمرة تكامل الجهود بين مختلف الجهات، وقال: \"نفخر بما قدمته المملكة في خليجي 27، وبنسخة جسّدت روح كأس الخليج الحقيقية؛ منافسة في الملعب، وأخوّة ومحبة تجمعنا خارجه، هذا النجاح لم يكن ليتحقق لولا توفيق الله ثم الدعم الكبير الذي تحظى به الرياضة السعودية من قيادتنا الرشيدة، والتكامل بين جميع الجهات والفرق التي عملت على البطولة\".","وأضاف المسحل: \"نتقدم بالشكر للاتحاد الخليجي لكرة القدم، ولأخي الشيخ حمد بن خليفة بن أحمد آل ثاني رئيس مجلس إدارة اتحاد الخليج العربي على دعمه الكبير ومتابعته المستمرة منذ مراحل الإعداد الأولى وحتى ختام البطولة، وما أبداه من ثقة وتعاون مع اللجنة المحلية وفرق العمل، واهتمامه بمختلف تفاصيل البطولة، كما نشكر المنتخبات والاتحادات المشاركة والجماهير الخليجية التي صنعت أجواء البطولة، وكل من أسهم في نجاح هذه النسخة، سعدنا باستضافة أشقائنا في جدة، ونعتز بأن تبقى هذه البطولة مساحة تجمع أهل الخليج وتقرّبهم جيلاً بعد جيل\".","كما أعربت اللجنة عن شكرها وتقديرها لوسائل الإعلام المحلية والخليجية والعربية والدولية، على التغطية الواسعة التي حظيت بها البطولة، بمشاركة أكثر من 600 إعلامي مسجل، وما قدمته من حضور مهني أسهم في نقل أجواء المنافسات وإبراز البطولة ومواكبة أحداثها داخل المملكة وخارجها.","ووجّهت اللجنة شكرًا خاصًا للجماهير التي صنعت أحد أبرز مشاهد البطولة، بحضورها الكبير وتفاعلها طوال أيام المنافسات، مؤكدةً أن الجماهير كانت شريكًا رئيسيًا في نجاح \"خليجي الديار العربية 27\"، وأسهمت في صناعة أجواء عكست المكانة الكبيرة التي تحظى بها البطولة لدى أبناء الخليج.","كما ثمّنت اللجنة جهود كافة الجهات الحكومية والخاصة والشركاء وفرق العمل والمتطوعين، وكل من أسهم في إنجاح البطولة وتقديمها بالمستوى التنظيمي الذي شهدته منذ انطلاقها وحتى ليلة الختام."]','الرياضة','رياضة','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/sports/gied89fy2','https://ajel.sa/sports/gied89fy2','https://ajel.sa/sports/gied89fy2','https://ajel.sa/sports/gied89fy2','فريق التحرير','الرياض','2026-10-07T14:14:00.000Z','2026-10-07T14:14:00.000Z','2026-10-07T21:22:41.063Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/Capture-4ksTAIDU.png','/api/media/f59fa535-6c82-48e2-b8b8-f636733c1cd1','/api/media/f59fa535-6c82-48e2-b8b8-f636733c1cd1?variant=thumbnail','‎اللجنة المحلية المنظمة تختتم نسخة ناجحة من "خليجي 27"',1200,675,'valid','published','current','valid',46,'8fce9d4388100e5c70924880a1125b2d18f9b0bba7436f003a373862597be922','c9bf09c3c57dc1afb3a2170d0d252ef9b5bbd389d204f5c2a1618c8a19c25dba','محدّث','2026-10-07T20:18:06.969Z','2026-10-07T21:22:41.775Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["رياضة","مجلس إدارة اللجنة المحلية المنظمة","وزير الرياضة رئيس اللجنة الأولمبية","رئيس اللجنة الأولمبية والبارالمبية السعودية","الرياضة السعودية","الاقتصاد والأسواق","جدة","الرياض"]','["مجلس إدارة اللجنة المحلية المنظمة","وزير الرياضة رئيس اللجنة الأولمبية","رئيس اللجنة الأولمبية والبارالمبية السعودية","الرياضة السعودية","الاقتصاد والأسواق","الخليج العربي"]','needs_review','below_category_threshold','[{"category":"الطاقة والصناعة","score":1.5},{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0}]','Temporarily Unreachable','2026-10-07T20:21:36.320Z',NULL,1,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('04aa5c7f-50ec-4d19-bbd1-0a99a49c5b6b','news-04aa5c7f-50ec-4d19-bbd1-0a99a49c5b6b','ذا أتلانتيك: ترامب قد يأمر بضرب إيران قبل الانتخابات النصفية','ذا اتلانتيك ترامب قد يامر بضرب ايران قبل الانتخابات النصفيه','أكد موقع "ذا أتلانتيك"، أن الرئيس الأمريكي دونالد ترامب قد يأمر بضرب إيران قبل انتخابات التجديد النصفي للكونجرس. وأضاف، أن الرئيس الأمريكي يريد إظهار تقدم بشأن إيران وسعر البنزين قبل الانتخابات النصفية.','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","أكد موقع \"ذا أتلانتيك\"، أن الرئيس الأمريكي دونالد ترامب قد يأمر بضرب إيران قبل انتخابات التجديد النصفي للكونجرس.","وأضاف، أن الرئيس الأمريكي يريد إظهار تقدم بشأن إيران وسعر البنزين قبل الانتخابات النصفية.","كذلك يدرس البنتاجون الخيارات المتاحة لضرب إيران بعد طلب من البيت الأبيض بهذا الشأن.","يأتي ذلك عقب تعقيد الموقف التفاوضي بين الولايات المتحدة وإيران بسبب تنعت الأخيرة بشأن الملف النووي وعدم قبول أي آلية تفاوض بشأنه."]','السياسة','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/international/p1rsdhjer','https://ajel.sa/international/p1rsdhjer','https://ajel.sa/international/p1rsdhjer','https://ajel.sa/international/p1rsdhjer','فريق التحرير','','2026-10-07T13:59:00.000Z','2026-10-07T13:59:00.000Z','2026-10-07T21:22:42.519Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-09/%D8%AA%D8%B1%D8%A7%D9%85%D8%A8-8SxYw0pM.webp','/api/media/04aa5c7f-50ec-4d19-bbd1-0a99a49c5b6b','/api/media/04aa5c7f-50ec-4d19-bbd1-0a99a49c5b6b?variant=thumbnail','ذا أتلانتيك: ترامب قد يأمر بضرب إيران قبل الانتخابات النصفية',1200,675,'valid','published','current','valid',41,'74db047fc5646426f86e0c7526bbec8a25dfc5cbe2df2a0ecf00c695474105c8','2544bfbae2ab89dc371be5d221004c99d9d0e02178dcb4499d83b175f6fdf233','محدّث','2026-10-07T20:18:07.682Z','2026-10-07T21:22:42.960Z','','',0,0,'international','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السياسة والعلاقات الدولية","إيران","الولايات المتحدة"]','["السياسة والعلاقات الدولية","الولايات المتحدة"]','needs_review','below_category_threshold','[{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Temporarily Unreachable','2026-10-07T20:21:36.336Z',NULL,1,1,'temporary_network_error: fetch failed','',NULL,NULL,'','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a545724f-6751-4ef4-af49-e71842218c73','news-a545724f-6751-4ef4-af49-e71842218c73','"السعودية لإعادة التمويل العقاري SRC" و"البنك السعودي الفرنسي BSF" يوقعان ثالث اتفاقية لشراء محفظة تمويل عقاري','السعوديه لاعاده التمويل العقاري src و البنك السعودي الفرنسي bsf يوقعان ثالث اتفاقيه لشراء محفظه تمويل عقاري','أعلنت الشركة السعودية لإعادة التمويل العقاري ( SRC ) - إحدى شركات صندوق الاستثمارات العامة - توقيع اتفاقية لشراء محفظة تمويل عقاري سكني من البنك السعودي الفرنسي ( BSF )، في ثالث عملية شراء لمحفظة تمويل عقاري بين الجانبين، ضمن جهود الشركة الرامية إلى رفع كفاءة سوق التمويل العقاري ودعم استدامته في المملكة، إذ جرى توقيع الاتفاقية برعاية معالي وزير البلديات…','["وتأتي الاتفاقية امتدادًا للتعاون بين الشركة والبنك في سوق التمويل العقاري السكني، من خلال توفير السيولة لجهات التمويل ورفع قدرتها على مواصلة تقديم الحلول التمويلية، إلى جانب تنمية السوق الثانوية للتمويل العقاري وتوسيع خيارات التمويل السكني، بما يتوافق مع مستهدفات برنامج الإسكان ورؤية السعودية 2030.","وأكد الرئيس التنفيذي للشركة السعودية لإعادة التمويل العقاري مجيد بن فهد العبدالجبار، أن الاتفاقية تعكس متانة الشراكة الاستراتيجية والثقة المتبادلة بين الطرفين، وتؤكد التزامهما المشترك بدعم نمو منظومة التمويل العقاري السكني في المملكة.","وأوضح العبدالجبار، أن استمرار التعاون مع جهات التمويل يسهم في توفير السيولة وتمكينها من توسيع نطاق التمويل العقاري السكني، إلى جانب دعم نمو السوق الثانوية للتمويل العقاري ورفع كفاءة السوق واستدامته عبر تطوير حلول إعادة التمويل العقاري.","من جانبه، قال الرئيس التنفيذي للبنك السعودي الفرنسي بدر بن حمد السلوم، أن هذه الاتفاقية تأتي امتدادًا لشراكتنا الاستراتيجية مع الشركة السعودية لإعادة التمويل العقاري، وتعكس التزامنا المشترك بدعم سوق تمويل عقاري أكثر كفاءة واستدامة، مشيرًا إلى أن البنك يواصل من خلال هذا التعاون توسيع نطاق الحلول التمويلية المقدمة للعملاء، ودعم مستهدفات رؤية السعودية 2030.","وتواصل الشركة السعودية لإعادة التمويل العقاري العمل مع شركائها لرفع كفاءة منظومة التمويل العقاري، وتوسيع قاعدة المستثمرين، وتنمية السوق الثانوية، وتطوير حلول إعادة تمويل مستدامة تدعم نمو القطاع وتزيد من مرونته.","يُذكر أن الشركة السعودية لإعادة التمويل العقاري تأسست عام 2017 من قبل صندوق الاستثمارات العامة، وحصلت على ترخيص من البنك المركزي السعودي لممارسة نشاط إعادة التمويل العقاري، وتعمل على تطوير سوق التمويل العقاري في المملكة من خلال توفير السيولة للممولين ودعم قدرتهم على تقديم حلول تمويل سكني للأفراد، والإسهام في تحقيق مستهدفات منظومة الإسكان ورفع نسبة تملك الأسر السعودية للمساكن.","أعلنت الشركة السعودية لإعادة التمويل العقاري (SRC) - إحدى شركات صندوق الاستثمار","في يوم الإسكان العربي.. منظومة البلديات والإسكان تمضي نحو مجتمعات أكثر مرونة"]','العقارات','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/ar/news/alswdyt-laadt-altmwyl-alqary-src-2','https://momah.gov.sa/ar/news/alswdyt-laadt-altmwyl-alqary-src-2','','https://momah.gov.sa/ar/news/alswdyt-laadt-altmwyl-alqary-src-2','','','2026-10-06T02:50:00.000Z','Wed, 07 Oct 2026 11:31:10 GMT','2026-10-07T20:28:02.345Z','','','','"السعودية لإعادة التمويل العقاري SRC" و"البنك السعودي الفرنسي BSF" يوقعان ثالث اتفاقية لشراء محفظة تمويل عقاري',NULL,NULL,'no_article_image_candidates','published','current','valid',92,'bb177c5aa85fec7f3324a0a50a086df40116137fa5b14f96d3c28312b7cfef34','9b7f65a52801913d1ce35b98d6a01d211b6e200ccf7dc885b8a6002e719a9609',NULL,'2026-10-07T20:28:02.345Z','2026-10-07T20:44:42.399Z','','',0,0,'saudi_national','عادي',55,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس إدارة الشركة السعودية","مجلس إدارة الشركة السعودية لإعادة","البنك المركزي السعودي لممارسة نشاط","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["رئيس مجلس إدارة الشركة السعودية","مجلس إدارة الشركة السعودية لإعادة","البنك المركزي السعودي لممارسة نشاط","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"الاقتصاد","score":9},{"category":"أخبار السعودية","score":4.5},{"category":"المجتمع","score":4.5}]','Active','2026-10-07T20:44:42.399Z',200,1,0,'source_article_available','',NULL,NULL,'"1791372670"','Wed, 07 Oct 2026 11:31:10 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a33019ad-8b71-4247-be58-104a8d127a5f','news-a33019ad-8b71-4247-be58-104a8d127a5f','في يوم الإسكان العربي.. منظومة البلديات والإسكان تمضي نحو مجتمعات أكثر مرونة','في يوم الاسكان العربي منظومه البلديات والاسكان تمضي نحو مجتمعات اكثر مرونه','تحتفي منظومة البلديات والإسكان، اليوم، بيوم الإسكان العربي 2026، الذي يأتي هذا العام تحت شعار "المرونة المجتمعية.. بناء مجتمعات قادرة على التكيف"، وهو الشعار الذي اقترحته المملكة واعتمده مجلس وزراء الإسكان والتعمير العرب التابع لجامعة الدول العربية، في مناسبة تجدد الاهتمام بدور السكن في استقرار الأسر، وقدرة المجتمعات على مواكبة احتياجات سكانها وتحولات المدن.','["وفي المملكة، ارتبط هذا المفهوم خلال السنوات الماضية بمسيرة تطوير متكاملة لقطاع الإسكان، عملت خلالها الوزارة وشركاؤها من الجهات الحكومية والقطاعين الخاص وغير الربحي على توسيع خيارات الأسر، وتيسير الوصول إلى المسكن، وتنويع الحلول التمويلية، وزيادة المعروض السكني، وتطوير مجتمعات ترتبط بالخدمات والمرافق؛ لتصبح رحلة الأسرة نحو المسكن جزءًا من منظومة أشمل تراعي احتياجاتها وقدراتها ومراحل حياتها.","ومنذ إطلاق برنامج سكني عام 2017، شهد القطاع توسعًا في المنتجات السكنية والتمويل العقاري المدعوم، ونموًا في مشاركة المطورين والجهات التمويلية، إلى جانب تحفيز استثمار الأراضي وتطويرها وتيسير الإجراءات المرتبطة بالمشروعات السكنية، ما أسهم في تنويع الخيارات المتاحة أمام الأسر ومواكبة الطلب والنمو العمراني في المدن.","وواكب هذا التحول تطور في الخدمات الرقمية المقدمة للمستفيدين، أتاحت للأسر استعراض الخيارات السكنية، والتحقق من الاستحقاق، والتعرف على الحلول التمويلية، ومتابعة الإجراءات ضمن رحلة أكثر وضوحًا وسهولة، مع تنوع المنتجات والحلول التي تستجيب لاختلاف الاحتياجات والقدرات الشرائية.","وأثمرت هذه المسارات تقدمًا في مستهدفات التملّك؛ إذ بلغت نسبة تملّك الأسر السعودية مساكنها 66.24 في المئة في عام 2025، متجاوزة المستهدف المرحلي البالغ 65 في المئة، فيما يتواصل العمل نحو مستهدف رؤية السعودية 2030 برفع النسبة إلى 70 في المئة.","وامتدت جهود الاستقرار السكني إلى الأسر الأشد حاجة؛ إذ وفّر برنامج الإسكان التنموي آلاف الوحدات السكنية بالشراكة مع أكثر من 350 جمعية غير ربحية، ضمن منظومة تتكامل فيها الجهود الحكومية والمجتمعية لتوسيع وصول الأسر المستحقة إلى السكن المناسب، وتعزيز استقرارها الاجتماعي والسكني.","ويتجاوز تطوير القطاع توفير الوحدة السكنية إلى بناء مجتمعات تتكامل فيها المساكن مع الخدمات والمرافق والمساحات العامة، وتتصل بشبكات الحركة واحتياجات الحياة اليومية، إلى جانب تحفيز تطوير الأراضي وزيادة المعروض وتعزيز مشاركة القطاع الخاص؛ لتصبح التنمية السكنية جزءًا من نمو المدينة وقدرتها على استيعاب سكانها وتغير احتياجاتهم.","وتتقاطع هذه المسارات مع مفهوم \"المرونة المجتمعية\" الذي يحمله يوم الإسكان العربي هذا العام؛ إذ تقوم المجتمعات الأكثر قدرة على التكيف على تنوع الخيارات السكنية، وسهولة الوصول إلى التمويل، وتوافر الخدمات، وكفاءة استخدام الأراضي، وأحياء تستجيب للنمو والتحولات السكانية والاقتصادية، لتدعم استقرار الأسرة وترفع كفاءة الحياة داخل المدينة.","وعلى المستوى العربي، تتولى المملكة رئاسة المكتب التنفيذي لمجلس وزراء الإسكان والتعمير العرب للدورة 2026–2027، بعد اختيارها خلال الدورة الثانية والأربعين للمجلس، وتواصل من خلال هذا الدور دعم التعاون العربي وتبادل الخبرات والممارسات في مجالات الإسكان والتنمية الحضرية، والعمل المشترك على تطوير السياسات والحلول التي تستجيب لتحديات المدن واحتياجات المجتمعات العربية."]','العقارات','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/ar/news/fy-ywm-alaskan-alrby-mnzwmt','https://momah.gov.sa/ar/news/fy-ywm-alaskan-alrby-mnzwmt','','https://momah.gov.sa/ar/news/fy-ywm-alaskan-alrby-mnzwmt','','المنطقة الشرقية','2026-10-06T02:56:00.000Z','Wed, 07 Oct 2026 11:29:15 GMT','2026-10-07T20:28:04.755Z','','','','في يوم الإسكان العربي.. منظومة البلديات والإسكان تمضي نحو مجتمعات أكثر مرونة',NULL,NULL,'no_article_image_candidates','published','current','valid',97,'1b51a3d995a1864a8e652f017a404a9c7bd9c98090b2faad10110b3eca1586a4','ef17dcec47943940f0b8dae9c2a34fa35989e32a35e9c317072534d46f384e09',NULL,'2026-10-07T20:28:04.755Z','2026-10-07T20:44:42.455Z','','',0,0,'saudi_region','عادي',53,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس وزراء الإسكان والتعمير العرب","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["مجلس وزراء الإسكان والتعمير العرب","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"الاقتصاد","score":8.5},{"category":"المجتمع","score":5.5},{"category":"أخبار السعودية","score":3}]','Active','2026-10-07T20:44:42.455Z',200,1,0,'source_article_available','',NULL,NULL,'"1791372555"','Wed, 07 Oct 2026 11:29:15 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8d465d38-a7d1-466f-9b93-bd54683bee35','news-8d465d38-a7d1-466f-9b93-bd54683bee35','وزير البلديات والإسكان يسلّم وحدات سكنية للأسر المستحقة بالشراكة مع البنك الأهلي السعودي','وزير البلديات والاسكان يسلم وحدات سكنيه للاسر المستحقه بالشراكه مع البنك الاهلي السعودي','وأسهمت الشراكة خلال الأعوام العشرة الماضية في توفير 2,269 وحدة سكنية للأسر المستحقة في مختلف مناطق المملكة، بدعم من مساهمات تجاوزت 244 مليون ريال، استفاد منها أكثر من 11 ألف مستفيد .','["بحضور معالي وزير البلديات والإسكان رئيس مجلس أمناء مؤسسة الإسكان التنموي الأهلية \"سكن\" الأستاذ ماجد بن عبدالله الحقيل، أقام البنك الأهلي السعودي حفل تسليم وحدات سكنية للأسر المستحقة عبر منصة \"جود الإسكان\"، احتفاءً بمرور عشرة أعوام على شراكته مع منظومة الإسكان التنموي.","وأكد معالي الحقيل في كلمته خلال الحفل أن استمرار هذه الشراكة يعكس التزام البنك الأهلي السعودي بدوره التنموي، ويجسد أهمية تكامل جهود القطاع الخاص مع منظومة الإسكان التنموي في توسيع نطاق الدعم ووصوله إلى الأسر المستحقة، بما ينسجم مع مستهدفات رؤية السعودية 2030 .","وأعرب معاليه عن شكره لرئيس مجلس إدارة البنك الأهلي السعودي سعيد بن محمد الغامدي، والرئيس التنفيذي للبنك طارق بن عبدالرحمن السدحان، وقيادات البنك ومنسوبيه، ولكل من أسهم في وصول الوحدات السكنية إلى مستحقيها.","\"السعودية لإعادة التمويل العقاري SRC\" و\"البنك السعودي الفرنسي BSF\" يوقعان ثالث اتفاقية لشراء محفظة تمويل عقاري","أعلنت الشركة السعودية لإعادة التمويل العقاري (SRC) - إحدى شركات صندوق الاستثمار","في يوم الإسكان العربي.. منظومة البلديات والإسكان تمضي نحو مجتمعات أكثر مرونة","تحتفي منظومة البلديات والإسكان، اليوم، بيوم الإسكان العربي 2026، الذي يأتي هذا العام تحت شعار \"المرونة المجتمعية..","انطلاق المعرض المتنقل للتوعية بالأمن السيبراني في مقر وزارة البلديات والإسكان"]','العقارات','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/ar/news/wzyr-albldyat-walaskan-yslwm','https://momah.gov.sa/ar/news/wzyr-albldyat-walaskan-yslwm','','https://momah.gov.sa/ar/news/wzyr-albldyat-walaskan-yslwm','','','2026-10-05T01:18:00.000Z','Wed, 07 Oct 2026 11:31:26 GMT','2026-10-07T20:28:04.881Z','','','','وزير البلديات والإسكان يسلّم وحدات سكنية للأسر المستحقة بالشراكة مع البنك الأهلي السعودي',NULL,NULL,'no_article_image_candidates','published','current','valid',93,'a2f5f0cc7489b60f31700bfec65f5ad0b52173f1c0b3a0ec83298d177a888e78','325c6b776d07b4e3614b17eac9875f41208a32fe3437cfc1fde846fd3862b967',NULL,'2026-10-07T20:28:04.881Z','2026-10-07T20:44:43.901Z','','',0,0,'saudi_national','عادي',52,NULL,0,0,0,'',NULL,NULL,NULL,'["رئيس مجلس أمناء مؤسسة الإسكان","مجلس أمناء مؤسسة الإسكان التنموي","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["رئيس مجلس أمناء مؤسسة الإسكان","مجلس أمناء مؤسسة الإسكان التنموي","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"الاقتصاد","score":8.5},{"category":"أخبار السعودية","score":1.5},{"category":"التقنية","score":1.5}]','Active','2026-10-07T20:44:43.901Z',200,1,0,'source_article_available','',NULL,NULL,'"1791372686"','Wed, 07 Oct 2026 11:31:26 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4459be7f-0d4c-444e-8b01-910229440d1b','news-4459be7f-0d4c-444e-8b01-910229440d1b','انطلاق المعرض المتنقل للتوعية بالأمن السيبراني في مقر وزارة البلديات والإسكان','انطلاق المعرض المتنقل للتوعيه بالامن السيبراني في مقر وزاره البلديات والاسكان','افتتح معالي وزير البلديات والإسكان الأستاذ ماجد بن عبدالله الحقيل، اليوم، المعرض المتنقل للتوعية بالأمن السيبراني، الذي تنظمه الوزارة بالتعاون مع الهيئة الوطنية للأمن السيبراني، وذلك بحضور معالي محافظ الهيئة الوطنية للأمن السيبراني المهندس ماجد بن محمد المزيد، وعدد من مسؤولي ومنسوبي الوزارة . تحتفي منظومة البلديات والإسكان، اليوم، بيوم الإسكان العربي…','["ويهدف المعرض الذي يأتي ضمن فعاليات الحملة الوطنية للتوعية بالأمن السيبراني وتستمر فعالياته على مدى يومين، إلى تعزيز قيم المحافظة على الأمن الوطني، ورفع مستوى الوعي بالأمن السيبراني وبناء ثقافة سيبرانية عالية لدى منسوبي الوزارة، بما يسهم في الحد من المخاطر السيبرانية المتجددة، فضلاً عن تحقيق التكامل المشترك بين الجهات الوطنية في مجال التوعية السيبرانية.","ويضم المعرض المتنقل 6 أجنحة متنوعة لإثراء تجربة منسوبي الوزارة، حيث يستعرض مفاهيم الأمن السيبراني وأهميته على المستوى الوطني، وتسليط الضوء على أبرز السلوكيات التي تسهم في الحماية من المخاطر السيبرانية من خلال مجموعة من الأساليب التفاعلية، كما يتضمن مجموعة من الأدوات والتقنيات الحديثة التي تسهم في رفع مستوى الحماية السيبرانية، وتقديم محاكاة حية لأبرز الهجمات السيبرانية على الأفراد والمنظمات، إضافةً إلى تقديم الإرشادات السيبرانية حول أفضل الممارسات في بيئة العمل للحد من المخاطر التي يشهدها الفضاء السيبراني.","وتعد الحملة الوطنية للتوعية بالأمن السيبراني إحدى المبادرات الإستراتيجية التي تنفذها الهيئة الوطنية للأمن السيبراني بهدف رفع مستوى الوعي بالأمن السيبراني لدى مختلف فئات المجتمع في المملكة، وبناء ثقافة سيبرانية عالية لتعزيز قيم المحافظة على الأمن الوطني، والتعريف بأفضل الممارسات الآمنة في الفضاء السيبراني، بما يسهم في تحقيق التكامل المشترك بين الجهات الوطنية في مجال التوعية السيبرانية لتعزيز الأمن السيبراني في المملكة.","\"السعودية لإعادة التمويل العقاري SRC\" و\"البنك السعودي الفرنسي BSF\" يوقعان ثالث اتفاقية لشراء محفظة تمويل عقاري","أعلنت الشركة السعودية لإعادة التمويل العقاري (SRC) - إحدى شركات صندوق الاستثمار","في يوم الإسكان العربي.. منظومة البلديات والإسكان تمضي نحو مجتمعات أكثر مرونة","تحتفي منظومة البلديات والإسكان، اليوم، بيوم الإسكان العربي 2026، الذي يأتي هذا العام تحت شعار \"المرونة المجتمعية..","افتتح معالي وزير البلديات والإسكان الأستاذ ماجد بن عبدالله الحقيل، اليوم، المعرض المتنقل للتوعية بالأمن السيبراني، الذ"]','العقارات','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/ar/news/antlaq-almrd-almtnql-lltwyt','https://momah.gov.sa/ar/news/antlaq-almrd-almtnql-lltwyt','','https://momah.gov.sa/ar/news/antlaq-almrd-almtnql-lltwyt','','','2026-10-05T01:46:00.000Z','Wed, 07 Oct 2026 11:32:42 GMT','2026-10-07T20:28:05.363Z','','','','انطلاق المعرض المتنقل للتوعية بالأمن السيبراني في مقر وزارة البلديات والإسكان',NULL,NULL,'no_article_image_candidates','published','current','valid',99,'120ed2bb42fc482f1a922ca50d1bad972d578b89e8d116b83ae9c764778bbf0f','ada3e4343507b1b8641bc9b20b79864005c894d8fd788d1f0ed68f088c572a43',NULL,'2026-10-07T20:28:05.363Z','2026-10-07T20:44:42.446Z','','',0,0,'saudi_national','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["الثقافة والفنون","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"الاقتصاد","score":5.5},{"category":"المجتمع","score":4.5},{"category":"المناطق","score":4}]','Active','2026-10-07T20:44:42.446Z',200,1,0,'source_article_available','',NULL,NULL,'"1791372762"','Wed, 07 Oct 2026 11:32:42 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('bae991de-89cc-44a5-bf48-20cd60857010','news-bae991de-89cc-44a5-bf48-20cd60857010','وزارة البلديات والإسكان تُحدث اشتراطات محلات المثلجات.. لتنظيم النشاط وضبط متطلبات السلامة الغذائية','وزاره البلديات والاسكان تحدث اشتراطات محلات المثلجات لتنظيم النشاط وضبط متطلبات السلامه الغذائيه','ويمكن الاطلاع على اشتراطات محلات المثلجات والتعرف على متطلبات الترخيص والتجهيز والتشغيل عبر موقع وزارة البلديات والإسكان من خلال الرابط https://momah.gov.sa/ar/node/17477 .','["حدثت وزارة البلديات والإسكان اشتراطات محلات المثلجات \"الآيس كريم\"، بهدف تنظيم ممارسة النشاط، وتحديد متطلبات سلامة الأغذية، وتوضيح الاشتراطات البلدية والفنية أمام المستثمرين، وتحسين جودة الخدمات المقدمة للمستفيدين.","وأوضحت الوزارة أن الاشتراطات المحدثة تضمنت متطلبات تفصيلية لسلامة الأغذية في مراحل استلام المنتجات وتخزينها وتحضيرها وتقديمها، تشمل ضبط درجات الحرارة، والإفصاح عن مسببات الحساسية، وتطبيق إجراءات النظافة والتعقيم، وفق الأنظمة واللوائح الصادرة عن الهيئة العامة للغذاء والدواء والجهات ذات العلاقة؛ للحفاظ على سلامة المنتجات المقدمة للمستهلكين.","وبيّنت أن الاشتراطات المحدثة حددت متطلبات الترخيص والموقع وتجهيز المحلات، وراعت متطلبات كود البناء السعودي، ومعايير الوصول الشامل، واشتراطات الوقاية من الحريق، إلى جانب تنظيم الواجهات واللوحات التجارية، وتحقيق المتطلبات الفنية اللازمة لممارسة النشاط.","وأضافت أن الاشتراطات المحدثة شملت جوانب التشغيل والصيانة والنظافة وإدارة النفايات، وتنظيم تجهيز مرافق المحلات، لرفع كفاءة التشغيل والمحافظة على بيئة مناسبة لتحضير المنتجات وحفظها وتقديمها، ورفع مستوى الامتثال للاشتراطات البلدية.","وفيما يتعلق بالعاملين، أشارت الوزارة إلى أن الاشتراطات المحدثة تضمنت الحصول على الشهادات الصحية، والالتزام بالنظافة الشخصية، وارتداء الملابس الواقية، وتطبيق ممارسات سلامة الغذاء أثناء العمل، كما شملت متطلبات الدفع الإلكتروني واستخدام الرمز الإلكتروني الموحد \" QR \" في المنشآت.","وأكدت الوزارة أن تطوير اشتراطات الأنشطة البلدية وتوحيد متطلباتها يسهمان في توضيح الإجراءات أمام المستثمرين، ويساعدان أصحاب المنشآت على التعرف على التزاماتهم في مراحل التجهيز والتشغيل، وتطوير أعمالهم وفق معايير محددة تراعي سلامة المستفيدين وجودة الخدمات.","\"السعودية لإعادة التمويل العقاري SRC\" و\"البنك السعودي الفرنسي BSF\" يوقعان ثالث اتفاقية لشراء محفظة تمويل عقاري","أعلنت الشركة السعودية لإعادة التمويل العقاري (SRC) - إحدى شركات صندوق الاستثمار"]','العقارات','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-tuhdth','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-tuhdth','','https://momah.gov.sa/ar/news/wzart-albldyat-walaskan-tuhdth','','المدينة المنورة','2026-10-05T01:45:00.000Z','Wed, 07 Oct 2026 11:31:55 GMT','2026-10-07T20:28:06.184Z','','','','وزارة البلديات والإسكان تُحدث اشتراطات محلات المثلجات.. لتنظيم النشاط وضبط متطلبات السلامة الغذائية',NULL,NULL,'no_article_image_candidates','published','current','valid',99,'13b51e01b88f1a04e18e8ebd152b6b68c6133c97e0e7715f2c3d69a6cee42b09','ea7d40cf6334e1c29dcfaaa8f1415a6831f3194b0c50ab5505f24465e1721ec7',NULL,'2026-10-07T20:28:06.184Z','2026-10-07T20:44:42.541Z','','',0,0,'saudi_region','عادي',45,NULL,0,0,0,'',NULL,NULL,NULL,'["الصحة العامة","الطقس والمناخ","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["الصحة العامة","الطقس والمناخ","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"المناطق","score":8},{"category":"الاقتصاد","score":5.5},{"category":"المجتمع","score":4.5}]','Active','2026-10-07T20:44:42.541Z',200,1,0,'source_article_available','',NULL,NULL,'"1791372715"','Wed, 07 Oct 2026 11:31:55 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a3e4d0fd-1c5e-4cbd-8d2f-3bd5b466d314','news-a3e4d0fd-1c5e-4cbd-8d2f-3bd5b466d314','وزير البلديات والإسكان يترأس وفد المملكة في اجتماع وزراء الإسكان الخليجي بالمنامة ويستعرض تطور منظومة الإسكان والتمويل','وزير البلديات والاسكان يتراس وفد المملكه في اجتماع وزراء الاسكان الخليجي بالمنامه ويستعرض تطور منظومه الاسكان والتمويل','كما تكفلت المملكة بإعداد "الدليل الاسترشادي لتطبيق معايير الاستدامة في المشاريع الإسكانية"، بما يعزز تبادل الممارسات والخبرات في مجال الاستدامة الإسكانية على المستوى الخليجي.','["ترأس معالي وزير البلديات والإسكان الأستاذ ماجد بن عبدالله الحقيل وفد المملكة العربية السعودية في الاجتماع الرابع والعشرين للجنة الوزراء المعنيين بشؤون الإسكان بدول مجلس التعاون، الذي عُقد في المنامة اليوم بمشاركة أصحاب المعالي والسعادة وزراء الإسكان بدول المجلس . وناقش الاجتماع عددًا من الملفات المتعلقة بتطوير قطاع الإسكان وتعزيز العمل الخليجي المشترك، بما يدعم تبادل الخبرات وتطوير السياسات والممارسات الإسكانية بين دول المجلس، ومنها متابعة تنفيذ القواعد الموحدة لملاك العقارات بدول مجلس التعاون، المعتمدة من المجلس الأعلى. كما تكفلت المملكة بإعداد \"الدليل الاسترشادي لتطبيق معايير الاستدامة في المشاريع الإسكانية\"، بما يعزز تبادل الممارسات والخبرات في مجال الاستدامة الإسكانية على المستوى الخليجي. وعلى هامش الاجتماع، شارك معالي الوزير في الجلسة الوزارية الحوارية بعنوان \"مستقبل الإسكان الوطني: سياسات مبتكرة وحلول مستدامة\"، حيث استعرض التحولات التي يشهدها قطاع الإسكان، في ظل تغير احتياجات الأسر وتنوع أنماط الحياة واختلاف احتياجات الأجيال والمناطق الجغرافية. وأوضح معاليه أن هذه التحولات تتطلب الانتقال من التفكير التقليدي في الإسكان إلى منظومة أكثر تكاملًا تعتمد على البيانات والتقنيات الحديثة، وتجمع بين المواطن والمطور والممول والمنظم والتقنية؛ بما يساعد على فهم الطلب وتسريع تطوير الحلول والسياسات والمنتجات السكنية الأكثر ملاءمة. وأكد معاليه أن التمكين السكني يتجاوز توفير الوحدة السكنية، خصوصًا للفئات الأشد احتياجًا، مشيرًا إلى أهمية تكامل الدعم والتمويل والسكن مع احتياجات الأسرة وفرص العمل، بما يعزز قدرة المستفيد على الاستقرار والاعتماد على الذات. وأشار معاليه إلى أهمية الدور الذي يمكن أن يؤديه القطاع الثالث في هذه المنظومة، باعتباره أكثر قربًا من الفئات الأشد احتياجًا، وقدرته على الإسهام في تطوير حلول تجمع بين أشكال الدعم المختلفة وتستجيب لاحتياجات الأسر. وفي جانب التمويل، أوضح معاليه أن التحول في نموذج الإسكان يتطلب إعادة هيكلة سلسلة التمويل، مع تعزيز دور القطاع التمويلي في تمويل الوحدات السكنية ودعم الإنشاء، إلى جانب تطوير أدوات مالية قادرة على توفير السيولة طويلة الأجل. وأكد أهمية تطوير أسواق التوريق، وتفعيل دور شركات الضمان وإعادة التمويل، وتوحيد المنتجات والمعايير التمويلية، بما يتيح للمستثمرين فهم السوق وضخ السيولة فيه، مشيرًا إلى أن التمويل السكني طويل الأجل يتطلب أدوات تتناسب مع احتياجات تمتد إلى 20 و30 عامًا، في ظل اعتماد البنوك على ودائع قصيرة الأجل. وأشار معاليه إلى تجربة المملكة في تطوير سوق التمويل والسوق المالية وإنشاء المؤسسات المتخصصة، وما أسهمت به هذه المنظومة في تطوير المنتجات التمويلية وجذب المستثمرين وتوفير حلول تمتد لآجال طويلة. وشهد الحفل المصاحب للاجتماع إعلان جوائز مجلس التعاون في مجال الإسكان في دورتها السابعة، حيث حقق مشروع \"وجهة خيالا السكني\" المركز الثالث على مستوى دول المجلس، كما كُرِّمت مؤسسة عبدالله العثيم وأولاده الخيرية ضمن تكريم المؤسسات، والأستاذ محمد يوسف ناغي ضمن تكريم الأيادي البيضاء؛ تقديرًا لإسهاماتهم في دعم الإسكان التنموي. واختتم معاليه بالتأكيد على أهمية تعزيز التكامل الخليجي في قطاع الإسكان، والاستفادة من القدرات والخبرات الخليجية، والانتقال من تبادل الخبرات إلى مزيد من التكامل بين السياسات والمنظومات، بما يدعم تطوير حلول سكنية وتمويلية تستجيب لاحتياجات مواطني دول المجلس.","\"السعودية لإعادة التمويل العقاري SRC\" و\"البنك السعودي الفرنسي BSF\" يوقعان ثالث اتفاقية لشراء محفظة تمويل عقاري","أعلنت الشركة السعودية لإعادة التمويل العقاري (SRC) - إحدى شركات صندوق الاستثمار","في يوم الإسكان العربي.. منظومة البلديات والإسكان تمضي نحو مجتمعات أكثر مرونة","تحتفي منظومة البلديات والإسكان، اليوم، بيوم الإسكان العربي 2026، الذي يأتي هذا العام تحت شعار \"المرونة المجتمعية..","انطلاق المعرض المتنقل للتوعية بالأمن السيبراني في مقر وزارة البلديات والإسكان","افتتح معالي وزير البلديات والإسكان الأستاذ ماجد بن عبدالله الحقيل، اليوم، المعرض المتنقل للتوعية بالأمن السيبراني، الذ","لأي استفسار أو ملاحظات حول الخدمات الحكومية، يرجى ملء المعلومات المطلوبة."]','العقارات','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/ar/news/wzyr-albldyat-walaskan-ytras-wfd-0','https://momah.gov.sa/ar/news/wzyr-albldyat-walaskan-ytras-wfd-0','','https://momah.gov.sa/ar/news/wzyr-albldyat-walaskan-ytras-wfd-0','','المنطقة الشرقية','2026-10-01T01:36:00.000Z','Wed, 07 Oct 2026 11:55:50 GMT','2026-10-07T20:28:06.706Z','','','','وزير البلديات والإسكان يترأس وفد المملكة في اجتماع وزراء الإسكان الخليجي بالمنامة ويستعرض تطور منظومة الإسكان والتمويل',NULL,NULL,'no_article_image_candidates','published','archived','valid',94,'f22cdba88822d0f6590524866116d7c7cb47e40ebc1ab2cdda1acd636e4721a1','efae980bc0d280b50d10a4771d52e199824f56030cd67a3a5588455430cc4ff4',NULL,'2026-10-07T20:28:06.706Z','2026-10-07T21:00:35.773Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["مجلس التعاون الذي ع قد","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["مجلس التعاون الذي ع قد","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[{"category":"الاقتصاد","score":7},{"category":"أخبار السعودية","score":4.5},{"category":"التقنية","score":4.5}]','Active','2026-10-07T20:44:43.919Z',200,1,0,'source_article_available','',NULL,NULL,'"1791374150"','Wed, 07 Oct 2026 11:55:50 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('59856b84-f7be-4d22-8e7a-bf1eb4228ab2','news-59856b84-f7be-4d22-8e7a-bf1eb4228ab2','بمشاركة 17 أمانة.. "البلديات والإسكان" وSNB توسعان أثر التطوع الطلابي عبر "مدن الجمال الحضري"','بمشاركه 17 امانه البلديات والاسكان وsnb توسعان اثر التطوع الطلابي عبر مدن الجمال الحضري','نفذت وزارة البلديات والإسكان، بالشراكة مع مجموعة SNB ، مبادرة "مدن الجمال الحضري"، بمشاركة أكثر من 10 آلاف طالب وطالبة، وبالتعاون مع 17 أمانة في مختلف مناطق المملكة، ضمن جهود دعم العمل التطوعي وتعزيز المشاركة المجتمعية المرتبطة بتحسين المشهد الحضري والمحافظة على المرافق العامة والبيئة الحضرية.','["وتشمل المبادرة عددًا من المسارات التطوعية، من بينها معالجة مظاهر التشوه البصري، والتشجير، والعناية بالشواطئ، إضافة إلى أعمال الطلاء الخارجي للمدارس، بهدف إشراك الطلاب والطالبات في أعمال ميدانية تسهم في خدمة مدنهم وتعزز المسؤولية المجتمعية لديهم.","وأوضحت الوزارة أن المبادرة تأتي ضمن الشراكة مع مجموعة SNB لدعم المبادرات المجتمعية المرتبطة بالقطاعين البلدي والإسكاني، وتوسيع مشاركة الطلاب والطالبات في الأعمال التطوعية ذات الصلة بالمدينة ومرافقها، في إطار تعزيز دور المجتمع في تحسين المشهد الحضري والمحافظة على البيئة الحضرية ورفع جودة المرافق العامة.","وأشارت إلى أن المبادرة تربط العمل التطوعي بالمدينة واحتياجاتها اليومية، من خلال مشاركة الطلاب والطالبات في أعمال ترتبط بالتشجير والعناية بالمرافق والمساحات العامة، بما يدعم بناء أحياء أكثر حيوية، ويوسع مساهمة المجتمع في تحسين تجربة السكان داخل مدنهم.","وشهدت مدينة تبوك تنفيذ عدد من أنشطة المبادرة بالتنسيق مع أمانة منطقة تبوك، وبمشاركة 800 طالب وطالبة على مدى يومين، تضمنت أعمالًا تطوعية وممارسات بيئية مرتبطة بتحسين المشهد الحضري والمحافظة على المرافق العامة، وتعزيز مشاركة الطلاب والطالبات في خدمة مدينتهم ومجتمعهم.","وبيّنت الوزارة أن \"مدن الجمال الحضري\" تُمثل نموذجًا للتكامل بين القطاعين البلدي والإسكاني والقطاع الخاص والمجتمع التعليمي، من خلال توجيه العمل التطوعي نحو مبادرات ذات أثر حضري ومجتمعي، وربط مشاركة الطلاب والطالبات بأعمال تسهم في تحسين المدينة والمحافظة على مرافقها، وتعزز الوعي بأهمية البيئة الحضرية وجودة الخدمات.","وكانت مبادرة \"مدن الجمال الحضري\" حققت في مرحلتها السابقة بمشاركة أكثر من 10 آلاف متطوعًا ومتطوعة، وتنفيذ أكثر من 50 ألف ساعة تطوعية في مختلف مناطق المملكة، ضمن أعمال ميدانية وتوعوية هدفت إلى تعزيز ثقافة التطوع وتحسين المشهد الحضري.","وتواصل وزارة البلديات والإسكان ومجموعة SNB ، بالتعاون مع الأمانات، دعم المبادرات المجتمعية المرتبطة بالقطاع البلدي، وتوسيع فرص التطوع الطلابي، وتعزيز الشراكات التي تدعم حيوية المدن، وتحسن المشهد الحضري، وترفع جودة تجربة السكان في المرافق والمساحات العامة.","\"السعودية لإعادة التمويل العقاري SRC\" و\"البنك السعودي الفرنسي BSF\" يوقعان ثالث اتفاقية لشراء محفظة تمويل عقاري"]','العقارات','','c7998275-5be2-423f-a8e2-bcd1c6068330','وزارة البلديات والإسكان','https://momah.gov.sa/ar/news/bmsharkt-17-amant-albldyat','https://momah.gov.sa/ar/news/bmsharkt-17-amant-albldyat','','https://momah.gov.sa/ar/news/bmsharkt-17-amant-albldyat','','تبوك','2026-10-01T05:51:00.000Z','Wed, 07 Oct 2026 11:56:09 GMT','2026-10-07T20:28:06.765Z','','','','بمشاركة 17 أمانة.. "البلديات والإسكان" وSNB توسعان أثر التطوع الطلابي عبر "مدن الجمال الحضري"',NULL,NULL,'no_article_image_candidates','published','archived','valid',93,'be695bfe7f9d32d23be28589232b6c001c7b209e3f5ec7861dfe261b1b20b543','2fe5f47b30d1139375a01c3d13daeec239b60cc26c199b45f15b4d7f2b5fd192',NULL,'2026-10-07T20:28:06.765Z','2026-10-07T21:00:35.773Z','','',0,0,'saudi_region','عادي',50,NULL,0,0,0,'',NULL,NULL,NULL,'["الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق","تبوك"]','["الثقافة والفنون","التعليم والتدريب","الاقتصاد والأسواق"]','classified','','[{"category":"المجتمع","score":8.5},{"category":"المناطق","score":5.5},{"category":"الاقتصاد","score":5.5}]','Active','2026-10-07T20:44:44.386Z',200,1,0,'source_article_available','',NULL,NULL,'"1791374169"','Wed, 07 Oct 2026 11:56:09 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('a7db7f76-583e-4755-a272-a56ee612d44d','news-a7db7f76-583e-4755-a272-a56ee612d44d','" الأرصاد " : أمطار أعلى من المعدل خلال أكتوبر ونوفمبر وارتفاع في متوسط درجات الحرارة','الارصاد امطار اعلي من المعدل خلال اكتوبر ونوفمبر وارتفاع في متوسط درجات الحراره','أوضح المركز الوطني للأرصاد أن التوقعات المناخية خلال الفترة من أكتوبر إلى ديسمبر 2026م تشير إلى فرص لهطول أمطار أعلى من المعدل الطبيعي على أغلب مناطق المملكة خلال أكتوبر ومعظم مناطقها خلال نوفمبر، فيما تكون حول المعدل على أغلب المناطق خلال ديسمبر، بالتزامن مع ارتفاع متوقع في متوسط درجات الحرارة السطحية عن المعدل الطبيعي خلال الأشهر الثلاثة. وأشار إلى أن…','["Website belongs to an official government organization in the Kingdom of Saudi Arabia always ends with .gov.sa","Secured governments websites in the Kingdom of Saudi Arabia use Https encryption.","وبيّن المركز أن شهر أكتوبر يُتوقع أن يشهد هطول أمطار أعلى من المعدل على أغلب مناطق المملكة وسواحل البحر الأحمر والخليج العربي، بفرصة حدوث تصل إلى 80%، وتتراوح الأمطار من متوسطة إلى غزيرة، وقد تصل إلى غزيرة جدًا على مناطق تبوك والمدينة المنورة والباحة وعسير والجوف وحائل والقصيم والحدود الشمالية والرياض ما عدا الجنوب، إضافة إلى غرب نجران.","وأشار إلى أن الأمطار خلال أكتوبر قد تصل إلى شديدة الغزارة على مناطق مكة المكرمة وجازان والمنطقة الشرقية، باستثناء جنوب المنطقة الشرقية.","وفي شهر نوفمبر، توقع المركز هطول أمطار أعلى من المعدل على معظم مناطق المملكة، بنسبة احتمال تصل إلى 75%، وقد تتراوح من غزيرة إلى غزيرة جدًا، وتشمل مناطق مكة المكرمة والرياض والباحة وعسير وجازان والجوف والحدود الشمالية وتبوك والمنطقة الشرقية، إضافة إلى القصيم ما عدا الغرب، وحائل ما عدا جنوب غربها، وشمال وجنوب المدينة المنورة.","أما خلال شهر ديسمبر، فتشير التوقعات إلى هطول أمطار حول المعدل الطبيعي على أغلب مناطق المملكة، مع فرص لهطول أمطار أعلى من المعدل على أجزاء من منطقتي الشرقية ومكة المكرمة، بنسبة احتمال تتراوح بين 40 و50%، وقد تتراوح شدتها من غزيرة إلى غزيرة جدًا.","وفيما يتعلق بدرجات الحرارة، أوضح المركز أن التوقعات الاحتمالية خلال أشهر أكتوبر ونوفمبر وديسمبر تشير إلى ارتفاع متوسط درجات الحرارة السطحية عن المعدل الطبيعي على جميع مناطق المملكة.","وبيّن أن أقصى الارتفاعات المتوقعة تتركز على أجزاء من جنوب شرق مكة المكرمة، وشرق الباحة، وعسير ما عدا الغرب، وشمال شرق جازان، ونجران ما عدا الشرق، وجنوب وجنوب غرب المنطقة الشرقية، إضافة إلى جنوب الرياض."]','البيئة والمناخ','','19386499-3b50-46eb-886b-701a70bf67eb','المركز الوطني للأرصاد','https://www.ncm.gov.sa/en/media/news/%D8%A7%D9%84%D8%A3%D8%B1%D8%B5%D8%A7%D8%AF_%D8%A3%D9%85%D8%B7%D8%A7%D8%B1_%D8%A3%D8%B9%D9%84%D9%89_%D9%85%D9%86_%D8%A7%D9%84%D9%85%D8%B9%D8%AF%D9%84_%D8%AE%D9%84%D8%A7%D9%84_%D8%A3%D9%83%D8%AA%D9%88%D8%A8%D8%B1_%D9%88%D9%86%D9%88%D9%81%D9%85%D8%A8%D8%B1_%D9%88%D8%A7%D8%B1%D8%AA%D9%81%D8%A7%D8%B9_%D9%81%D9%8A_%D9%85%D8%AA%D9%88%D8%B3%D8%B7_%D8%AF%D8%B1%D8%AC%D8%A7%D8%AA_%D8%A7%D9%84%D8%AD%D8%B1%D8%A7%D8%B1%D8%A9','https://www.ncm.gov.sa/en/media/news/%D8%A7%D9%84%D8%A3%D8%B1%D8%B5%D8%A7%D8%AF_%D8%A3%D9%85%D8%B7%D8%A7%D8%B1_%D8%A3%D8%B9%D9%84%D9%89_%D