INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('f6944c85-ed50-4ca6-95eb-b6573b6ec1a0','news-f6944c85-ed50-4ca6-95eb-b6573b6ec1a0','أكاديمية «واس» تستضيف الدكتور فهد المالك لبحث تحولات الصحافة الحديثة وتطبيقات الذكاء الاصطناعي','اكاديميه واس تستضيف الدكتور فهد المالك لبحث تحولات الصحافه الحديثه وتطبيقات الذكاء الاصطناعي','استضافت أكاديمية وكالة الأنباء السعودية الدكتور فهد المالك في جلسة حوارية متخصصة تناولت التحولات المتسارعة التي تشهدها غرف الأخبار في ظل تصاعد تطبيقات الذكاء الاصطناعي التوليدي والتحليلي.','["واستعرض اللقاء أبرز الممارسات المهنية لدمج نماذج الذكاء الاصطناعي في عمليات التحقق من الأخبار وصياغة التقارير الفورية، مؤكداً أن التقنية أصبحت أداة تمكينية محورية لرفع جودة التغطيات الإخبارية وتسريع وتيرة الإنتاج الصحفي.","وشدد المشاركون على ضرورة الالتزام بأخلاقيات النشر والمصداقية المهنية، مع بناء برامج تدريبية متقدمة لتأهيل الكوادر الإعلامية الوطنية على التعامل الذكي مع أدوات الذكاء الاصطناعي الحديثة."]','الذكاء الاصطناعي','تقنيات الإعلام الذكي','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://www.spa.gov.sa/news/ai-media-shifts-2026','https://www.spa.gov.sa/news/ai-media-shifts-2026','','','محرر المختصر','الرياض','2026-10-07T19:12:20.000Z',NULL,'2026-10-07T21:00:37.558Z','https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=1200&q=80','/api/media/f6944c85-ed50-4ca6-95eb-b6573b6ec1a0','/api/media/f6944c85-ed50-4ca6-95eb-b6573b6ec1a0?variant=thumbnail','جلسة حوارية حول تطبيقات الذكاء الاصطناعي في الإعلام الحديث',NULL,NULL,'valid','published','current','valid',99,'3d1bf9e2fef1e651c73fc45ab8014f17a8518c1097068192f1899ac06917a2a5','651e52b2eff527c93e84ea4dcf8a83b6bb05df30ffcbdf9f0f86f4f24ed37084',NULL,'2026-10-07T21:00:37.558Z','2026-10-07T21:01:41.382Z','','وكالة الأنباء السعودية (واس)',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["تقنيات الإعلام الذكي","الذكاء الاصطناعي","الرياض","التعليم والتدريب","التقنية والتحول الرقمي"]','["تقنيات الإعلام الذكي","الذكاء الاصطناعي","التعليم والتدريب","التقنية والتحول الرقمي"]','classified','','[]','Redirected','2026-10-07T21:01:41.382Z',200,1,0,'source_redirect_followed','https://www.spa.gov.sa/',NULL,NULL,'body:3e20c6b8d30becee206f5eba7cd99f2300e8f080023806f3e1b33c728c5c3b38','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2c6abdf0-7770-4543-99eb-faff8da853d3','news-2c6abdf0-7770-4543-99eb-faff8da853d3','سباق الذكاء الاصطناعي ينتقل من قوة النماذج التوليدية إلى كفاءة التنفيذ وتكلفة الاستخدام التجاري','سباق الذكاء الاصطناعي ينتقل من قوه النماذج التوليديه الي كفاءه التنفيذ وتكلفه الاستخدام التجاري','أكد تقرير تقني حديث أن المنافسة العالمية بين كبرى شركات التكنولوجيا في قطاع الذكاء الاصطناعي بدأت تتحول من مجرد التباهي بحجم المعلمات الرياضية للنماذج اللغوية الضخمة إلى معايير كفاءة التنفيذ وتكلفة الاستهلاك.','["وأوضح التقرير أن الشركات تركز حالياً على تقليص استهلاك الطاقة ومراكز البيانات بنسب قياسية، مع تطوير نماذج ذكاء اصطناعي مدمجة وقابلة للتشغيل المباشر على الأجهزة الذكية دون الحاجة إلى خوادم سحابية عملاقة.","ويرى خبراء التقنية أن التحول نحو الكفاءة الاقتصادية سيمكّن قطاعات الأعمال المصرفية والتعليمية من تبني حلول الذكاء الاصطناعي التوليدي بمعدلات انتشار أسرع وتكاليف تشغيلية منخفضة."]','الذكاء الاصطناعي','النماذج اللغوية','8aebab4d-43fe-443d-a642-a73ec46152f5','العربية','https://www.alarabiya.net/technology/2026/10/07/ai-efficiency-shift','https://www.alarabiya.net/technology/2026/10/07/ai-efficiency-shift','','','محرر المختصر','الرياض','2026-10-07T14:53:00.000Z',NULL,'2026-10-07T21:00:37.577Z','https://images.unsplash.com/photo-1620712943543-bcc4688e7485?auto=format&fit=crop&w=1200&q=80','/api/media/2c6abdf0-7770-4543-99eb-faff8da853d3','/api/media/2c6abdf0-7770-4543-99eb-faff8da853d3?variant=thumbnail','مراكز حوسبة ونماذج متقدمة للذكاء الاصطناعي التوليدي',NULL,NULL,'valid','published','current','valid',99,'3739921acd38bdf393c4f59f8ba6601619b84a4ef4fbc1d752f3a2bab31b18cd','31ca1af5e97e56b026f6e46329cad92cd264e060e8f2317b44b99df2391da056',NULL,'2026-10-07T21:00:37.577Z','2026-10-07T21:01:38.439Z','','العربية',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["النماذج اللغوية","الذكاء الاصطناعي","الرياض","الطاقة والنفط","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','["النماذج اللغوية","الذكاء الاصطناعي","الطاقة والنفط","التعليم والتدريب","الاقتصاد والأسواق","التقنية والتحول الرقمي"]','classified','','[]','Unavailable','2026-10-07T21:01:38.439Z',403,1,1,'source_access_unavailable_http_403','',NULL,NULL,'body:858cc40703a3739bdc959a9ec62acb89bb5527c6c2e3117adf26d2d5ea8fa971','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('2868cefa-91f9-4ea3-b7aa-698e4db2b80a','news-2868cefa-91f9-4ea3-b7aa-698e4db2b80a','أميركا والصين وأوروبا.. 3 مسارات متباينة لتنظيم وتشريعات حوكمة الذكاء الاصطناعي عالمياً','اميركا والصين واوروبا 3 مسارات متباينه لتنظيم وتشريعات حوكمه الذكاء الاصطناعي عالميا','ترسم القوى الاقتصادية الكبرى ملامح مختلفة للأطر القانونية الحاكمة لتطوير ونشر تقنيات الذكاء الاصطناعي، حيث تسعى كل كتلة دولية إلى الموازنة بين الابتكار وحماية البيانات الشخصية.','["وتعتمد أوروبا نهجاً صارماً يقوم على تصنيف المخاطر وتطبيق غرامات رادعة على الأنظمة غير الممتثلة، في حين تركز الولايات المتحدة على تحفيز الابتكار ووضع معايير أمان طوعية بالشراكة مع رواد الصناعة.","من جهتها، تتبع الصين استراتيجية حكومية تجمع بين دعم الأبحاث الوطنية وتكثيف الرقابة على مخرجات النماذج اللغوية، مما يعكس سباقاً جيوسياسياً محموماً لرسم المعايير العالمية للتقنيات الناشئة."]','الذكاء الاصطناعي','حوكمة الذكاء الاصطناعي','8aebab4d-43fe-443d-a642-a73ec46152f5','العربية','https://www.alarabiya.net/technology/2026/10/07/ai-governance-regulations-2026','https://www.alarabiya.net/technology/2026/10/07/ai-governance-regulations-2026','','','محرر المختصر','الرياض','2026-10-07T11:48:00.000Z',NULL,'2026-10-07T21:00:37.596Z','https://images.unsplash.com/photo-1677442136019-21780efad99a?auto=format&fit=crop&w=1200&q=80','/api/media/2868cefa-91f9-4ea3-b7aa-698e4db2b80a','/api/media/2868cefa-91f9-4ea3-b7aa-698e4db2b80a?variant=thumbnail','تنظيمات وتشريعات حوكمة تقنيات الذكاء الاصطناعي العالمية',NULL,NULL,'valid','published','current','valid',99,'8e58e85fa79fe759a4bf79dffd9ae293ba50a493b4805b702fd6080e91354b11','ff54d4eff24bc30bdd0d303987251832254f598fca66e0f5edc4200243bcf42d',NULL,'2026-10-07T21:00:37.596Z','2026-10-07T21:01:42.991Z','','العربية',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["حوكمة الذكاء الاصطناعي","الذكاء الاصطناعي","الرياض","الصين","أوروبا","الولايات المتحدة"]','["حوكمة الذكاء الاصطناعي","الذكاء الاصطناعي","الولايات المتحدة"]','classified','','[]','Unavailable','2026-10-07T21:01:42.991Z',403,1,1,'source_access_unavailable_http_403','',NULL,NULL,'body:928ad0e360b39ea5d297628edd2cc8c7299cadae5eb1718e309589598817d016','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('11ac5e52-c7ba-4b08-9789-905b456c1d46','news-11ac5e52-c7ba-4b08-9789-905b456c1d46','إتاحة الابتعاث الخارجي لدراسة تخصصات علوم البيانات والذكاء الاصطناعي في أفضل 50 جامعة عالمية','اتاحه الابتعاث الخارجي لدراسه تخصصات علوم البيانات والذكاء الاصطناعي في افضل 50 جامعه عالميه','أعلنت الجهات المعنية عن إتاحة مسار مخصص للابتعاث الخارجي للطلبة السعوديين لدراسة تخصصات علوم البيانات المتقدمة وهندسة الذكاء الاصطناعي في أفضل خمسين جامعة على مستوى العالم.','["ويهدف البرنامج إلى إعداد جيل جديد من الكفاءات الوطنية القادرة على قيادة مراكز الأبحاث والمشاريع التقنية العملاقة بما يواكب مستهدفات الاستراتيجية الوطنية للبيانات والذكاء الاصطناعي سدايا.","ويتضمن المسار برامج أكاديمية وتدريبية متخصصة في مجالات التعلم العميق، ومعالجة اللغات الطبيعية، وتطوير الخوارزميات الذكية لدعم مسيرة التحول الرقمي الشامل في المملكة."]','الذكاء الاصطناعي','الكوادر والابتعاث','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://www.spa.gov.sa/news/scholarship-data-ai-top50','https://www.spa.gov.sa/news/scholarship-data-ai-top50','','','محرر المختصر','الرياض','2026-10-07T11:59:35.000Z',NULL,'2026-10-07T21:00:37.614Z','https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?auto=format&fit=crop&w=1200&q=80','/api/media/11ac5e52-c7ba-4b08-9789-905b456c1d46','/api/media/11ac5e52-c7ba-4b08-9789-905b456c1d46?variant=thumbnail','طلبة في مختبرات أبحاث الذكاء الاصطناعي وعلوم البيانات',NULL,NULL,'valid','published','current','valid',99,'454d1a8529d8f100e8281d507cbddb9f34dc939d989748c53a21be14d483f58e','dbd589e8f3889c278de3b508f4816c973b29ac43e73a5387354b0bb87d90c82a',NULL,'2026-10-07T21:00:37.614Z','2026-10-07T21:01:43.118Z','','وكالة الأنباء السعودية (واس)',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الكوادر والابتعاث","الذكاء الاصطناعي","الرياض","جامعة عالمية ويهدف البرنامج إلى","التعليم والتدريب","التقنية والتحول الرقمي"]','["الكوادر والابتعاث","الذكاء الاصطناعي","جامعة عالمية ويهدف البرنامج إلى","التعليم والتدريب","التقنية والتحول الرقمي"]','classified','','[]','Redirected','2026-10-07T21:01:43.118Z',200,1,0,'source_redirect_followed','https://www.spa.gov.sa/',NULL,NULL,'body:3e20c6b8d30becee206f5eba7cd99f2300e8f080023806f3e1b33c728c5c3b38','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('11e9e600-2d0e-4908-b69b-bca4a287a297','news-11e9e600-2d0e-4908-b69b-bca4a287a297','حائل تطلق برنامج «الذكاء الاصطناعي للقادة» بـ 100 مقعد تدريبي لمنسوبي القطاعات الحكومية','حائل تطلق برنامج الذكاء الاصطناعي للقاده بـ 100 مقعد تدريبي لمنسوبي القطاعات الحكوميه','دشنت إمارة منطقة حائل بالتعاون مع الجهات المختصة فعاليات برنامج «الذكاء الاصطناعي للقادة»، الذي يوفر مئة مقعد تدريبي مكثف للقيادات التنفيذية في القطاعات الحكومية بالمنطقة.','["ويهدف البرنامج التدريبي إلى تمكين القيادات الإدارية من استيعاب المفاهيم الحديثة للذكاء الاصطناعي وأدوات اتخاذ القرار المستندة إلى البيانات الضخمة، لتعزيز كفاءة الإنفاق وتطوير الخدمات المقدمة للمواطنين.","واشتمل اليوم الأول على ورش عمل تطبيقية لاستعراض دراسات حالة واقعية في أتمتة الإجراءات واستثمار حلول الذكاء الاصطناعي التوليدي في التخطيط الاستراتيجي المستدام."]','الذكاء الاصطناعي','التدريب والتأهيل','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/saudia/hail-ai-leaders-program-2026','https://sabq.org/saudia/hail-ai-leaders-program-2026','','','محرر المختصر','الرياض','2026-10-07T09:28:02.000Z',NULL,'2026-10-07T21:00:37.632Z','https://images.unsplash.com/photo-1531482615713-2afd69097998?auto=format&fit=crop&w=1200&q=80','/api/media/11e9e600-2d0e-4908-b69b-bca4a287a297','/api/media/11e9e600-2d0e-4908-b69b-bca4a287a297?variant=thumbnail','ورشة عمل تدريبية للقيادات في مجال تطبيقات الذكاء الاصطناعي',NULL,NULL,'valid','published','current','valid',99,'bc4ac0611795404c78b60e7767d96d88b6b8167ec71ced27d9cf3f5771bf125e','69d4ae3b05cef0d63c91b2d196a28a97f5f4b8a42556645092070b933aecf332',NULL,'2026-10-07T21:00:37.632Z','2026-10-07T21:01:45.704Z','','صحيفة سبق',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["التدريب والتأهيل","الذكاء الاصطناعي","الرياض","التعليم والتدريب","الاقتصاد والأسواق"]','["التدريب والتأهيل","الذكاء الاصطناعي","التعليم والتدريب","الاقتصاد والأسواق"]','classified','','[]','Active','2026-10-07T21:01:45.704Z',200,1,0,'source_article_available','',NULL,NULL,'body:bf05cc0a6973ef26652fa6a3984d9aa9e9fc74d6f5172dae5f99451f4220b2e1','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('9483d672-b161-44a6-912a-574b75840508','news-9483d672-b161-44a6-912a-574b75840508','«بلومبرغ إنتليجنس»: فجوة الذكاء الاصطناعي بين أميركا والصين تتقلص إلى مستوى قياسي جديد','بلومبرغ انتليجنس فجوه الذكاء الاصطناعي بين اميركا والصين تتقلص الي مستوي قياسي جديد','كشف تقرير صادر عن بلومبرغ إنتليجنس أن الفجوة التكنولوجية في أبحاث ونماذج الذكاء الاصطناعي بين الشركات الأميركية ومنافساتها الصينية تراجعت إلى أدنى مستوياتها منذ بدء طفرة النماذج التوليدية.','["وأشار التقرير إلى أن الاستثمارات الضخمة في تطوير الرقائق الإلكترونية المحلية وبناء نماذج مفتوحة المصدر أسهمت في تسريع وتيرة الأداء لدى الشركات الصينية لتضاهي أحدث الإصدارات العالمية.","وتوقع المحللون أن تشهد الأشهر القادمة منافسة شرسة في تطبيقات الذكاء الاصطناعي الصناعية والروبوتات الذكية، مع تركيز متزايد على خفض تكلفة التدريب الحوسبي للنماذج."]','الذكاء الاصطناعي','أبحاث ونماذج','ed4d055f-60cc-4436-9deb-4ac1f308304a','الشرق للأعمال مع بلومبرغ','https://www.asharqbusiness.com/technology/ai-gap-closing-bloomberg-report','https://www.asharqbusiness.com/technology/ai-gap-closing-bloomberg-report','','','محرر المختصر','الرياض','2026-10-07T08:15:28.000Z',NULL,'2026-10-07T21:00:37.651Z','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1200&q=80','/api/media/9483d672-b161-44a6-912a-574b75840508','/api/media/9483d672-b161-44a6-912a-574b75840508?variant=thumbnail','معالجات ورقائق إلكترونية مخصصة لتسريع الذكاء الاصطناعي',NULL,NULL,'valid','published','current','valid',99,'aa6c5e1cd87ed9aad1f4fde533887d5f22d1769186d68cb973b2dda65bc9ff60','76304c72ae599663bcbf8d5ba440cfe19e9cf24bbe85ee8520850d5f3133017b',NULL,'2026-10-07T21:00:37.651Z','2026-10-07T21:01:45.985Z','','الشرق للأعمال مع بلومبرغ',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["أبحاث ونماذج","الذكاء الاصطناعي","الرياض","التعليم والتدريب","الاقتصاد والأسواق","الصين"]','["أبحاث ونماذج","الذكاء الاصطناعي","التعليم والتدريب","الاقتصاد والأسواق"]','classified','','[]','Unavailable','2026-10-07T21:01:45.985Z',403,1,1,'source_access_unavailable_http_403','',NULL,NULL,'body:ca8ea9cdfdbab8a43ed6cb415bc373957a37a4ffecdf7a8848b1701ca7ae798f','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b1a04d3e-4d23-47af-93a5-ea608a667862','news-b1a04d3e-4d23-47af-93a5-ea608a667862','غوغل تطلق أداة «SynthID» عالمياً لكشف المحتوى المرئي والنصوص المولدة بالذكاء الاصطناعي','غوغل تطلق اداه synthid عالميا لكشف المحتوي المرئي والنصوص المولده بالذكاء الاصطناعي','أعلنت شركة غوغل عن الإتاحة العالمية لأداتها المتطورة SynthID، المخصصة لوضع علامات مائية رقمية وتحديد المحتوى المُولد بواسطة الذكاء الاصطناعي سواء كان نصوصاً أو صوراً أو مقاطع صوتية.','["وتعمل التقنية الجديدة على إدراج بصمات خفية داخل بنية الملفات الرقمية دون التأثير على جودتها البصرية أو السمعية، مما يتيح للمنصات الرقمية والمستخدمين التحقق الفوري من أصالة المواد المنشورة.","وتأتي هذه الخطوة في إطار الجهود التقنية العالمية الرامية لمكافحة التزييف العميق والتضليل الإعلامي، وتعزيز الشفافية الرقمية في المحتوى الناتج عن نماذج الذكاء الاصطناعي الحديثة."]','الذكاء الاصطناعي','الأمن والمصداقية','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/tech/2026/10/07/google-synthid-release','https://www.okaz.com.sa/tech/2026/10/07/google-synthid-release','','','محرر المختصر','الرياض','2026-10-07T16:12:00.000Z',NULL,'2026-10-07T21:00:37.668Z','https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&w=1200&q=80','/api/media/b1a04d3e-4d23-47af-93a5-ea608a667862','/api/media/b1a04d3e-4d23-47af-93a5-ea608a667862?variant=thumbnail','التحقق الرقمي من بصمات الذكاء الاصطناعي والأمن السيبراني',NULL,NULL,'valid','review','current','valid',99,'21acf2d184fb435278e45bc7fa7ed88d09abc9a244d9a838cabbad27b763ef07','7f6089019a85421133e1261556c0ba6054be33a7adaf218283dfc60599ac9c0f',NULL,'2026-10-07T21:00:37.668Z','2026-10-07T21:01:38.386Z','','صحيفة عكاظ',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["الأمن والمصداقية","الذكاء الاصطناعي","الرياض","التقنية والتحول الرقمي"]','["الأمن والمصداقية","الذكاء الاصطناعي","التقنية والتحول الرقمي"]','classified','','[]','Removed','2026-10-07T21:01:38.386Z',404,1,0,'source_confirmed_removed_http_404','','2026-10-07T21:01:38.386Z','published','body:c369b65001756d69c60ad592e12dcebfc924203763768f44ef221dd13d320c18','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('04f0f190-4a6b-4920-a377-5cf1aa017dd7','news-04f0f190-4a6b-4920-a377-5cf1aa017dd7','من «الترنبيل» إلى صناعة السيارات المتقدمة.. حكاية مسيرة ممتدة لأكثر من قرن في السعودية','من الترنبيل الي صناعه السيارات المتقدمه حكايه مسيره ممتده لاكثر من قرن في السعوديه','وتستهدف الاستراتيجية الوطنية للصناعة تحويل المملكة إلى مركز إقليمي رائد لتصنيع وتصدير السيارات الصديقة للبيئة وسلاسل الإمداد المرتبطة بها بحلول عام 2030.','["سلطت قراءة تاريخية واقتصادية الضوء على رحلة تطور قطاع النقل والمركبات في المملكة، بدءاً من دخول أولى السيارات التي عُرفت شعبياً باسم الترنبيل قبل نحو مئة عام، وصولاً إلى تدشين مصانع السيارات الكهربائية المتطورة.","وتشهد المملكة اليوم نهضة صناعية غير مسبوقة تقودها مشاريع تصنيع السيارات الكهربائية في مجمع الملك سلمان التابع لمدينة الملك عبدالله الاقتصادية، عبر مصانع عالمية ومحلية لإنتاج أحدث الطرازات الحديثة."]','السيارات','صناعة السيارات','8aebab4d-43fe-443d-a642-a73ec46152f5','العربية','https://www.alarabiya.net/saudi-today/2026/10/07/saudi-automotive-century','https://www.alarabiya.net/saudi-today/2026/10/07/saudi-automotive-century','','','محرر المختصر','الرياض','2026-10-07T12:07:00.000Z',NULL,'2026-10-07T21:00:37.692Z','https://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=1200&q=80','/api/media/04f0f190-4a6b-4920-a377-5cf1aa017dd7','/api/media/04f0f190-4a6b-4920-a377-5cf1aa017dd7?variant=thumbnail','صناعة وتطوير السيارات الحديثة في السعودية',NULL,NULL,'valid','published','current','valid',88,'a3521a1623692379babbb1d8d1b44c71fb9dd42ae129e3c9b066dda5ef2d77a3','66aaea33d47c36c4726ec525e537fa1568614ae7a111b2d8c8bb1304b9fcdbb6',NULL,'2026-10-07T21:00:37.692Z','2026-10-07T21:01:43.002Z','','العربية',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["صناعة السيارات","السيارات","الرياض","الاقتصاد والأسواق"]','["صناعة السيارات","الاقتصاد والأسواق"]','classified','','[]','Unavailable','2026-10-07T21:01:43.002Z',403,1,1,'source_access_unavailable_http_403','',NULL,NULL,'body:eabcc8a45a4998998f6b13ad8a4df642239c721441e5098e0879babdc851b51d','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('fd4ee0aa-3ecb-486f-957f-6804a261c6d3','news-fd4ee0aa-3ecb-486f-957f-6804a261c6d3','«الجميح للسيارات» تشارك بأربع علامات تجارية عالمية في معرض الصقور والصيد السعودي الدولي 2026','الجميح للسيارات تشارك باربع علامات تجاريه عالميه في معرض الصقور والصيد السعودي الدولي 2026','أعلنت شركة الجميح للسيارات عن مشاركتها الواسعة في فعاليات معرض الصقور والصيد السعودي الدولي 2026 في الرياض، مستعرضة أحدث طرازات الدفع الرباعي والمركبات المخصصة للرحلات والمغامرات البرية.','["وتضم منصة الشركة عروضاً حصرية لأربع علامات سيارات رائدة تشمل مركبات حديثة مجهزة بتقنيات قيادة متطورة لمواجهة التضاريس الوعرة وأنظمة سلامة مرورية معتمدة لقائدي المركبات في البيئات الصحراوية.","وشهد الجناح إقبالاً كبيراً من هواة الرحلات والمقتنين الراغبين في التعرف على حزم الدعم الفني وخدمات الضمان الممتد وقطع الغيار الأصلية الموفرة عبر شبكة مراكز الصيانة في مختلف مناطق المملكة."]','السيارات','معارض وطرازات','36c2530f-039b-4249-955f-acc4269325eb','صحيفة سبق','https://sabq.org/business/aljomaih-falcon-exhibition-2026','https://sabq.org/business/aljomaih-falcon-exhibition-2026','','','محرر المختصر','الرياض','2026-10-07T10:44:52.000Z',NULL,'2026-10-07T21:00:37.708Z','https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?auto=format&fit=crop&w=1200&q=80','/api/media/fd4ee0aa-3ecb-486f-957f-6804a261c6d3','/api/media/fd4ee0aa-3ecb-486f-957f-6804a261c6d3?variant=thumbnail','مركبات الدفع الرباعي في معرض الصقور والصيد السعودي',NULL,NULL,'valid','published','current','valid',99,'f7d4c28f4cab42cda081f819fceeaf3853fda6db9afabdbf58dc70150f782cda','d81011cefd7ecea69c0c9d8b4f3f4e22554de5007f8f78a21ac22ae829131c48',NULL,'2026-10-07T21:00:37.708Z','2026-10-07T21:01:45.713Z','','صحيفة سبق',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["معارض وطرازات","السيارات","الرياض"]','["معارض وطرازات"]','classified','','[]','Active','2026-10-07T21:01:45.713Z',200,1,0,'source_article_available','',NULL,NULL,'body:cfbf738504b81eead552cbb99f218206935a88a2123db7e5352d7e8c5400bb5b','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('8f1baecf-9504-44b9-b3a3-78070d54aed9','news-8f1baecf-9504-44b9-b3a3-78070d54aed9','من مرسيدس إلى فولكسفاغن.. احتدام المنافسة في سوق السيارات الكهربائية يدفع الشركات الأوروبية لحلول مبتكرة','من مرسيدس الي فولكسفاغن احتدام المنافسه في سوق السيارات الكهربائيه يدفع الشركات الاوروبيه لحلول مبتكره','وأعلنت الشركات عن حزمة استثمارات لتطوير منصات تصنيع معيارية وبطاريات الحالة الصلبة الجديدة، بهدف خفض تكلفة إنتاج السيارة الكهربائية بنسبة تصل إلى ثلاثين في المئة مقارنة بالجيل السابق.','["تواجه كبرى شركات تصنيع السيارات الأوروبية مثل مرسيدس وفولكسفاغن وبي إم دبليو منافسة قوية في الأسواق العالمية تدفعها إلى إعادة هيكلة خطوط الإنتاج والتركيز على فئات السيارات الكهربائية الأكثر كفاءة واقتصادية.","ويرى محللو سوق السيارات أن وتيرة الابتكار وسرعة توفير التحديثات البرمجية عبر الهواء باتت العنصر الحاسم في كسب ثقة المستهلكين وسط تسارع مبيعات السيارات الكهربائية والهجينة عالمياً."]','السيارات','السيارات الكهربائية','ed4d055f-60cc-4436-9deb-4ac1f308304a','الشرق للأعمال مع بلومبرغ','https://www.asharqbusiness.com/automotive/europe-ev-market-competition-2026','https://www.asharqbusiness.com/automotive/europe-ev-market-competition-2026','','','محرر المختصر','الرياض','2026-10-07T14:51:21.000Z',NULL,'2026-10-07T21:00:37.725Z','https://images.unsplash.com/photo-1563720223185-11003d516935?auto=format&fit=crop&w=1200&q=80','/api/media/8f1baecf-9504-44b9-b3a3-78070d54aed9','/api/media/8f1baecf-9504-44b9-b3a3-78070d54aed9?variant=thumbnail','تصنيع السيارات الكهربائية المتطورة وتحديث خطوط الإنتاج',NULL,NULL,'valid','published','current','valid',99,'69bd9f7e4861b0ecec05cdbc802f114c630a777e36bb9f6f9bbd5d2d89ca9571','0033ee66736a47ad8ba934087cbf4c70e41aaea11d2c5e113a4fc851e897ebe3',NULL,'2026-10-07T21:00:37.725Z','2026-10-07T21:01:44.225Z','','الشرق للأعمال مع بلومبرغ',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السيارات الكهربائية","السيارات","الرياض","الاقتصاد والأسواق"]','["السيارات الكهربائية","الاقتصاد والأسواق"]','classified','','[]','Unavailable','2026-10-07T21:01:44.225Z',403,1,1,'source_access_unavailable_http_403','',NULL,NULL,'body:b94fddf94d78730290916e8f70805ab0346a6c6f1a8efd05dbbd4be98afa1134','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('1d6fdf6b-94f9-46b4-9e2b-df0366077f54','news-1d6fdf6b-94f9-46b4-9e2b-df0366077f54','جاكوار تكشف رسمياً عن طرازها الرياضي الفاخر «تايب 01» بمحرك كهربائي فائق الأداء','جاكوار تكشف رسميا عن طرازها الرياضي الفاخر تايب 01 بمحرك كهربائي فائق الاداء','أزاحت شركة جاكوار البريطانية الستار رسمياً عن أول سيارة رياضية كهربائية بالكامل تحمل اسم تايب 01 إي في، والتي تدشن الهوية البصرية والتقنية الجديدة للعلامة التجارية العريقة.','["وتتميز المركبة الجديدة بتصميم انسيابي فائق يخلو من الزوايا التقليدية، مع محرك كهربائي مزدوج يولد قوة تتجاوز ستمئة حصان ومدى قيادة كهربائي يتخطى سبعمئة كيلومتر للشحنة الواحدة.","وأكدت الشركة المصنعة أن الموديل الجديد يزود بأحدث أنظمة القيادة الذاتية المساعدة، مع شاشات عرض تفاعلية مدعومة بالذكاء الاصطناعي لتوفير تجربة قيادة مستقبلية متكاملة."]','السيارات','طرازات جديدة','283140bf-6727-459e-8a8f-3af49b327d6d','صحيفة عكاظ','https://www.okaz.com.sa/auto/2026/10/07/jaguar-type01-ev','https://www.okaz.com.sa/auto/2026/10/07/jaguar-type01-ev','','','محرر المختصر','الرياض','2026-10-07T16:05:03.000Z',NULL,'2026-10-07T21:00:37.754Z','https://images.unsplash.com/photo-1542282088-72c9c27ed0cd?auto=format&fit=crop&w=1200&q=80','/api/media/1d6fdf6b-94f9-46b4-9e2b-df0366077f54','/api/media/1d6fdf6b-94f9-46b4-9e2b-df0366077f54?variant=thumbnail','طراز جاكوار تايب 01 الكهربائي فائق الأداء',NULL,NULL,'valid','review','current','valid',99,'bfe020655317ac4d4c8ac50f8d81dc6b373465671b917292a35d6e1cce6f0312','a90a1619deca5a92a4d29ad1c4733096c5407ed068f6bff832f7e17e0e94c151',NULL,'2026-10-07T21:00:37.754Z','2026-10-07T21:01:38.909Z','','صحيفة عكاظ',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["طرازات جديدة","السيارات","الرياض"]','["طرازات جديدة"]','classified','','[]','Removed','2026-10-07T21:01:38.909Z',404,1,0,'source_confirmed_removed_http_404','','2026-10-07T21:01:38.909Z','published','body:c369b65001756d69c60ad592e12dcebfc924203763768f44ef221dd13d320c18','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('b3554dae-57f2-4098-bb0c-37f56cb9e740','news-b3554dae-57f2-4098-bb0c-37f56cb9e740','إعلان استدعاء مركبات هيونداي لتعزيز معايير السلامة المرورية وتحديث برمجة وحدة التحكم','اعلان استدعاء مركبات هيونداي لتعزيز معايير السلامه المروريه وتحديث برمجه وحده التحكم','أعلنت وزارة التجارة بالتعاون مع الوكيل المحلي عن استدعاء عدد من مركبات هيونداي من طرازات محددة لإجراء فحص مجاني وتحديث برمجي لوحدة التحكم الإلكترونية في نظام الفرامل المانعة للانغلاق.','["ودعت الوزارة مالكي المركبات المشمولة بالاستدعاء إلى التحقق من أرقام الهياكل عبر الموقع الرسمي المخصص والتواصل مع مراكز الصيانة المعتمدة لحجز مواعيد الفحص المجاني دون أي مقابل مالي.","ويأتي هذا الإجراء المستمر ضمن برامج حماية المستهلك ومراقبة جودة المنتجات للتأكد من التزام وكلاء السيارات بأعلى معايير السلامة والأمان على الطرقات السعودية."]','السيارات','السلامة والاستدعاءات','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/cars/hyundai-safety-recall-oct2026','https://ajel.sa/cars/hyundai-safety-recall-oct2026','','','محرر المختصر','الرياض','2026-10-07T08:30:19.000Z',NULL,'2026-10-07T21:00:37.770Z','https://images.unsplash.com/photo-1486006920555-c77dce18193b?auto=format&fit=crop&w=1200&q=80','/api/media/b3554dae-57f2-4098-bb0c-37f56cb9e740','/api/media/b3554dae-57f2-4098-bb0c-37f56cb9e740?variant=thumbnail','فحص وصيانة أنظمة المركبات في مراكز الخدمة المعتمدة',NULL,NULL,'valid','review','current','valid',99,'1181f39af2deb677807215c8c938f4241a18771ca5da477a399fba389feac3da','3312e570e49f019dd9a76a98841d21901254d2eaf98e1a8319784a250cc224a6',NULL,'2026-10-07T21:00:37.770Z','2026-10-07T21:01:46.224Z','','صحيفة عاجل الإلكترونية',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["السلامة والاستدعاءات","السيارات","الرياض"]','["السلامة والاستدعاءات"]','classified','','[]','Removed','2026-10-07T21:01:46.224Z',404,1,0,'source_confirmed_removed_http_404','','2026-10-07T21:01:46.224Z','published','body:d607b96e0ea79658be6e11395e0a9c5fb9a222cd430e0f5e2ca4547e44fca7bf','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e061d64f-9135-49ba-955d-70cb2b3e9d56','news-e061d64f-9135-49ba-955d-70cb2b3e9d56','الإمارات تتصدر دول المنطقة في جاهزية البنية التحتية لمحطات شحن السيارات الكهربائية','الامارات تتصدر دول المنطقه في جاهزيه البنيه التحتيه لمحطات شحن السيارات الكهربائيه','وأوضح التقرير السنوي أن معدل انتشار المركبات الكهربائية شهد نمواً مضاعفاً بالتزامن مع الحوافز الحكومية المقدمة للمشترين وتوفير مواقف مخصصة ورسوم شحن مدعومة لتشجيع النقل المستدام. وتسعى دول مجلس التعاون الخليجي عموماً إلى تسريع تحول أساطيل النقل العام وسيارات الأجرة نحو الطاقة النظيفة لخفض الانبعاثات الكربونية في المدن الحضرية.','["حلت دولة الإمارات في المرتبة الأولى إقليمياً في مؤشر الجاهزية للتنقل الكهربائي لعام 2026، مدعومة بالتوسع السريع في نشر شبكات محطات الشحن فائق السرعة على الطرق السريعة والمجمعات التجارية.","وأوضح التقرير السنوي أن معدل انتشار المركبات الكهربائية شهد نمواً مضاعفاً بالتزامن مع الحوافز الحكومية المقدمة للمشترين وتوفير مواقف مخصصة ورسوم شحن مدعومة لتشجيع النقل المستدام.","وتسعى دول مجلس التعاون الخليجي عموماً إلى تسريع تحول أساطيل النقل العام وسيارات الأجرة نحو الطاقة النظيفة لخفض الانبعاثات الكربونية في المدن الحضرية."]','السيارات','البنية التحتية للنقل','ed4d055f-60cc-4436-9deb-4ac1f308304a','الشرق للأعمال مع بلومبرغ','https://www.asharqbusiness.com/automotive/uae-ev-infrastructure-index-2026','https://www.asharqbusiness.com/automotive/uae-ev-infrastructure-index-2026','','','محرر المختصر','الرياض','2026-10-07T06:31:04.000Z',NULL,'2026-10-07T21:00:37.786Z','https://images.unsplash.com/photo-1558441719-7589d98e5781?auto=format&fit=crop&w=1200&q=80','/api/media/e061d64f-9135-49ba-955d-70cb2b3e9d56','/api/media/e061d64f-9135-49ba-955d-70cb2b3e9d56?variant=thumbnail','محطة شحن متطورة للسيارات الكهربائية',NULL,NULL,'valid','published','current','valid',88,'520da4528b350a874b159dd0b65e1329761fa2c65067bb7e5134c471879a05e5','c69a4e04a737b63af837420d2a519be26e2b602623ebed22bbca9af52af687a3',NULL,'2026-10-07T21:00:37.786Z','2026-10-07T21:01:46.538Z','','الشرق للأعمال مع بلومبرغ',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["البنية التحتية للنقل","السيارات","الرياض","مجلس التعاون الخليجي عموما إلى","الطاقة والنفط"]','["البنية التحتية للنقل","مجلس التعاون الخليجي عموما إلى","الطاقة والنفط"]','classified','','[]','Unavailable','2026-10-07T21:01:46.538Z',403,1,1,'source_access_unavailable_http_403','',NULL,NULL,'body:04a993c1f7cc8d5696a4fed339e07b18640c4940d8262aee3a19f8d0a26b9bcc','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('7f3471b0-a305-4286-8bef-99bf228aed27','news-7f3471b0-a305-4286-8bef-99bf228aed27','جامعة الملك عبدالعزيز تعلن بدء القبول في برامج الدراسات العليا للعام الأكاديمي الجديد','جامعه الملك عبدالعزيز تعلن بدء القبول في برامج الدراسات العليا للعام الاكاديمي الجديد','أعلنت عمادة الدراسات العليا بجامعة الملك عبدالعزيز عن فتح باب القبول في برامج الماجستير والدكتوراه للعام الأكاديمي الجديد، عبر بوابتها الإلكترونية الموحدة لجميع التخصصات العلمية والإنسانية.','["وأوضحت الجامعة أن الشروط تراعي معايير التميز الأكاديمي واجتياز اختبارات القدرات العامة للجامعيين، مع توفير مقاعد مخصصة للمبتعثين الداخليين وباحثي المراكز العلمية المعتمدة.","ودعت العمادة المتقدمين والمتقدمات إلى مراجعة الجدول الزمني المعتمد واستكمال رفع الوثائق المطلوبة قبل موعد إغلاق البوابة المخصص نهاية الشهر الجاري."]','التعليم','الجامعات والقبول','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://www.spa.gov.sa/news/kau-postgraduate-admission-2026','https://www.spa.gov.sa/news/kau-postgraduate-admission-2026','','','محرر المختصر','الرياض','2026-10-07T14:20:00.000Z',NULL,'2026-10-07T21:02:22.184Z','https://images.unsplash.com/photo-1523050854058-8df90110c9f1?auto=format&fit=crop&w=1200&q=80','/api/media/7f3471b0-a305-4286-8bef-99bf228aed27','/api/media/7f3471b0-a305-4286-8bef-99bf228aed27?variant=thumbnail','مبنى جامعي وقاعات دراسية حديثة',NULL,NULL,'valid','published','current','valid',88,'955503a182212f42a7614f6d4f292e9e1bef17379bdfeb06c55dcc6c6973095d','c297b0ca1769284ba9c14a1aa2f718897ff206706a5d9d219c871d2ea406274b',NULL,'2026-10-07T21:02:22.184Z','2026-10-07T21:07:48.676Z','','وكالة الأنباء السعودية (واس)',0,0,'saudi_region','عادي',47,NULL,0,0,0,'',NULL,NULL,NULL,'["الجامعات والقبول","التعليم","الرياض","جامعة الملك عبدالعزيز تعلن بدء","التعليم والتدريب"]','["الجامعات والقبول","جامعة الملك عبدالعزيز تعلن بدء","التعليم والتدريب"]','classified','','[]','Redirected','2026-10-07T21:07:48.676Z',200,2,0,'source_redirect_followed','https://www.spa.gov.sa/',NULL,NULL,'body:3e20c6b8d30becee206f5eba7cd99f2300e8f080023806f3e1b33c728c5c3b38','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('e8c87a4f-9359-4785-9f7e-95841df52657','news-e8c87a4f-9359-4785-9f7e-95841df52657','«الموارد البشرية»: قرارات التوطين تسهم في توظيف أكثر من 60 ألف كادر وطني في القطاع الهندسي والتقني','الموارد البشريه قرارات التوطين تسهم في توظيف اكثر من 60 الف كادر وطني في القطاع الهندسي والتقني','كشفت وزارة الموارد البشرية والتنمية الاجتماعية عن نجاح مبادرات التوطين النوعي في إدخال أكثر من ستين ألف كادر وطني إلى سوق العمل في القطاعات الهندسية والاستشارية والتقنية خلال الربع الحالي.','["وأكدت الوزارة أن الشراكة الفاعلة مع صندوق تنمية الموارد البشرية «هدف» ومجلس الغرف السعودية أسهمت في رفع نسب الاستقرار الوظيفي وتقديم حزم دعم للأجور وبرامج التدريب على رأس العمل.","وأشارت إلى استمرار الجولات الرقابية الميدانية لمتابعة امتثال المنشآت لقرارات التوطين وتوفير بيئات عمل آمنة ومحفزة للكوادر الوطنية الشابة في مختلف مناطق المملكة."]','الوظائف وسوق العمل','التوطين والتوظيف','d8774f8b-c6c2-4dba-97f8-444bbce66554','وكالة الأنباء السعودية (واس)','https://www.spa.gov.sa/news/hrsd-saudization-milestone-2026','https://www.spa.gov.sa/news/hrsd-saudization-milestone-2026','','','محرر المختصر','الرياض','2026-10-07T13:40:00.000Z',NULL,'2026-10-07T21:02:22.202Z','https://images.unsplash.com/photo-1521791136064-7986c2920216?auto=format&fit=crop&w=1200&q=80','/api/media/e8c87a4f-9359-4785-9f7e-95841df52657','/api/media/e8c87a4f-9359-4785-9f7e-95841df52657?variant=thumbnail','كوادر وطنية في بيئة عمل مهنية متطورة',NULL,NULL,'valid','published','current','valid',99,'c7149ed19587364ff30b9df7ed07529d538b5fb4a10ff5c8a6e8d1c1a62659e5','05f6e97ffa764d92b0d4c705ebb63339eb2296029fdda8b7d2ac90e51e3a3dd6',NULL,'2026-10-07T21:02:22.202Z','2026-10-07T21:07:48.666Z','','وكالة الأنباء السعودية (واس)',0,0,'saudi_region','عادي',35,NULL,0,0,0,'',NULL,NULL,NULL,'["التوطين والتوظيف","الوظائف وسوق العمل","الرياض","التعليم والتدريب","الاقتصاد والأسواق"]','["التوطين والتوظيف","الوظائف وسوق العمل","التعليم والتدريب","الاقتصاد والأسواق"]','classified','','[]','Redirected','2026-10-07T21:07:48.666Z',200,2,0,'source_redirect_followed','https://www.spa.gov.sa/',NULL,NULL,'body:3e20c6b8d30becee206f5eba7cd99f2300e8f080023806f3e1b33c728c5c3b38','');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('0e7a9f6c-b7b1-4bcb-ae94-20f84d83cce9','news-0e7a9f6c-b7b1-4bcb-ae94-20f84d83cce9','التحالف: اعتداءات الميليشيا الحوثية الإرهابية على الأعيان المدنية لن تمر دون حساب','التحالف اعتداءات الميليشيا الحوثيه الارهابيه علي الاعيان المدنيه لن تمر دون حساب','صرّح المتحدث الرسمي باسم قوات التحالف "تحالف دعم الشرعية في اليمن" اللواء الركن تركي المالكي أن الاعتداءات الوحشية من الميليشيا الحوثية الإرهابية على المدنيين والأعيان المدنية ب المملكة والتي كان آخرها استهداف مطار الملك خالد الدولي ب الرياض ومطار أبها الدولي لم ولن تمر دون حساب.','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","وأضاف أن القوات المشتركة للتحالف نفذت هجوم شامل تضمن تدمير ما مجموعه (82) هدف عسكري مشروع تتبع للميليشيا الحوثية الإرهابية في محافظات ( صعدة ، الحديدة ، الجوف ، مأرب ) وشملت مجموعة الأهداف مصادر التهديد للصواريخ الباليستية بعدد (11) مخزن للصواريخ الباليستية بمناطق جبلية في صعدة، ومراكز للقيادة والسيطرة ومنظومات الاتصالات ومخازن صواريخ وأسلحة ومقرات للمجاميع الحوثية الإرهابية."]','أخبار السعودية','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/fd8rvcywk','https://ajel.sa/local/fd8rvcywk','https://ajel.sa/local/fd8rvcywk','https://ajel.sa/local/fd8rvcywk','فريق التحرير','الرياض','2026-10-07T14:48:00.000Z','2026-10-07T14:50:00.000Z','2026-10-07T21:22:41.080Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D8%A7%D9%84%D9%84%D9%88%D8%A7%D8%A1-%D8%A7%D9%84%D8%B1%D9%83%D9%86-%D8%AA%D8%B1%D9%83%D9%8A-%D8%A7%D9%84%D9%85%D8%A7%D9%84%D9%83%D9%8A-561FOBgt.jpg','/api/media/0e7a9f6c-b7b1-4bcb-ae94-20f84d83cce9','/api/media/0e7a9f6c-b7b1-4bcb-ae94-20f84d83cce9?variant=thumbnail','التحالف: اعتداءات الميليشيا الحوثية الإرهابية على الأعيان المدنية لن تمر دون حساب',1200,675,'valid','published','current','valid',40,'09e0c57d9ad475dd43c87dfc22f8c729418b5c5472ab905f6580139ddfb090e3','f8f9e58bcb66d4595b135a93a9919fa7498fdfc686aaaaa28b95d49d86b2250d','محدّث','2026-10-07T21:02:39.031Z','2026-10-07T21:22:41.669Z','','',0,0,'saudi_region','مهم',71,NULL,0,0,0,'',NULL,NULL,NULL,'["الجوف","اليمن","الرياض"]','[]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active','2026-10-07T21:07:45.897Z',200,2,0,'source_article_available','',NULL,NULL,'body:0c1cbb5d91ebde4832db1887384791d82163f61decedc859f93826d55c1d7fa5','Wed, 07 Oct 2026 21:07:44 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('27d9aa31-2f53-4632-944d-7dc90adbd13e','news-27d9aa31-2f53-4632-944d-7dc90adbd13e','تعليم وجامعة جازان يعلنان تحويل الدراسة الحضورية غدًا إلى عن بُعد','تعليم وجامعه جازان يعلنان تحويل الدراسه الحضوريه غدا الي عن بعد','أعلنت الإدارة العامة للتعليم ب منطقة جازان تحويل الدراسة غدًا الخميس إلى نظام التعليم عن بُعد عبر منصة "مدرستي"، في جميع مدارس المنطقة ومحافظاتها. وأكدت الإدارة أهمية متابعة الطلبة لدروسهم والالتزام بأوقات الحصص الدراسية المقررة، بما يضمن انتظام العملية التعليمية واستمرارها عن بُعد.','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","أعلنت الإدارة العامة للتعليم ب منطقة جازان تحويل الدراسة غدًا الخميس إلى نظام التعليم عن بُعد عبر منصة \"مدرستي\"، في جميع مدارس المنطقة ومحافظاتها.","وأوضحت الإدارة أن القرار جاء بناءً على التقارير الصادرة عن المركز الوطني للأرصاد، وحرصًا على سلامة الطلاب والطالبات والهيئتين التعليمية والإدارية، مشيرةً إلى استمرار العملية التعليمية وفق الجداول الدراسية المعتمدة عبر منصة \"مدرستي\".","وأكدت الإدارة أهمية متابعة الطلبة لدروسهم والالتزام بأوقات الحصص الدراسية المقررة، بما يضمن انتظام العملية التعليمية واستمرارها عن بُعد.","كماأعلنت جامعة جازان تعليق الدراسة الحضورية غدًا الخميس.","وأوضحت الجامعة أنه بناءً على ما ورد من المركز الوطني للأرصاد، وحرصًا على سلامة الطلاب والطالبات، ومنسوبي ومنسوبات الهيئتين التعليمية والإدارية، فقد تقرر تعليق الدراسة الحضورية في جميع مقرات الجامعة، ومجمعاتها الأكاديمية، وكليات المحافظات، على أن تكون المحاضرات ليوم الخميس \"عن بُعد\" عبر منصة بلاك بورد."]','البيئة والمناخ','','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/ktkz0q2ao','https://ajel.sa/local/ktkz0q2ao','https://ajel.sa/local/ktkz0q2ao','https://ajel.sa/local/ktkz0q2ao','فريق التحرير','جازان','2026-10-07T14:40:00.000Z','2026-10-07T14:41:00.000Z','2026-10-07T21:12:37.955Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-10/%D8%AA%D8%B9%D9%84%D9%8A%D9%85-%D8%AC%D8%A7%D8%B2%D8%A7%D9%86-RVsP78Tn.png','/api/media/27d9aa31-2f53-4632-944d-7dc90adbd13e','/api/media/27d9aa31-2f53-4632-944d-7dc90adbd13e?variant=thumbnail','تعليم وجامعة جازان يعلنان تحويل الدراسة الحضورية غدًا إلى عن بُعد',1200,675,'valid','published','current','valid',42,'c8131308929997868c50b94b1174a5d0558b77bdb02321c7adca64178179d15d','12e909bec5a5cf81e81778e7daa5aa97ddb335e53901eb6f18619660ded0dc60','محدّث','2026-10-07T21:02:40.216Z','2026-10-07T21:12:38.396Z','','',0,0,'saudi_region','مهم',68,NULL,0,0,0,'',NULL,NULL,NULL,'["جامعة جازان تعليق الدراسة الحضورية","التعليم والتدريب","جازان"]','["جامعة جازان تعليق الدراسة الحضورية","التعليم والتدريب"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"أخبار السعودية","score":0},{"category":"الذكاء الاصطناعي","score":0}]','Active','2026-10-07T21:07:45.878Z',200,2,0,'source_article_available','',NULL,NULL,'body:49dda298ff4077cbd11aacd3cb62895e75ab94652701268540bae5634ac2d508','Wed, 07 Oct 2026 21:07:44 GMT');
INSERT OR REPLACE INTO articles (id,slug,title,normalized_title,summary,content,main_category,subcategory,source_id,source_name,source_url,canonical_url,source_article_id,rss_guid,author,region,source_published_at,source_updated_at,retrieved_at,image_original_url,image_local_url,image_thumbnail_url,image_alt,image_width,image_height,image_status,publication_status,archive_status,validation_status,category_confidence,content_hash,event_fingerprint,badge,created_at,updated_at,image_caption,image_credit,view_count,share_count,geographic_relevance,importance_level,priority_score,manual_priority_override,homepage_pinned,homepage_excluded,is_breaking,breaking_source,breaking_detected_by,breaking_verified_at,breaking_expires_at,tags,keyphrases,classification_status,classification_reason,classification_alternatives,source_status,last_source_check_at,last_source_http_status,source_check_attempts,source_consecutive_failures,source_status_reason,source_redirect_url,source_removed_at,source_previous_publication_status,last_source_etag,last_source_modified) VALUES ('4d0645c3-82ba-432a-b2c4-4841d71b7fb0','news-4d0645c3-82ba-432a-b2c4-4841d71b7fb0','البحرين والأردن يدينان استهداف ميليشيا الحوثي مطارَي أبها والملك خالد الدوليين','البحرين والاردن يدينان استهداف ميليشيا الحوثي مطاري ابها والملك خالد الدوليين','أعربت البحرين عن إدانتها واستنكارها الشديدين للاعتداءين الإرهابيين الآثمين اللذين استهدفا مطاري أبها الدولي والملك خالد الدولي، وأسفرا عن سقوط ضحايا وعدد من المصابين من المواطنين والمقيمين، وإلحاق أضرار مادية بالمرافق.','["صحيفة إلكترونية سعودية تم تأسيسها عام 2007م تهتم بنشر الأخبار المحلية والمنافسة في سبق الأخبار بمهنية ومصداقية وموضوعية","وأكدت وزارة الخارجية البحرينية في بيان اليوم، أن استهداف المطارات والمنشآت المدنية وتعريض حياة المسافرين والعاملين الأبرياء للخطر يمثّل عملًا إجراميًا وانتهاكًا صارخًا لأحكام القانون الدولي والقانون الدولي الإنساني، وتصعيدًا خطيرًا يهدد أمن المنطقة واستقرارها وسلامة الملاحة الجوية المدنية.","وجددت البحرين تضامنها التام ووقوفها الثابت إلى جانب المملكة ، وتأييدها لكل ما تتخذه من إجراءات لصون أمنها واستقرارها وحماية مواطنيها والمقيمين على أرضها، مؤكدةً أن أمن المملكة جزء لا يتجزأ من أمن البحرين ومنظومة مجلس التعاون لدول الخليج العربية.","وأعربت الوزارة عن خالص التعازي وصادق المواساة إلى المملكة العربية السعودية، وإلى المملكة المغربية ، والجمهورية الجزائرية الديمقراطية الشعبية، و جمهورية السودان ، وإلى أسر الضحايا، سائلةً المولى -عز وجل- أن يتغمدهم بواسع رحمته، متمنيةً لجميع المصابين الشفاء العاجل.","كما أدانت الحكومة الأردنية اليوم الاعتداءين اللذين شنّتهما ميليشيا الحوثي، واستهدفا مطارَي أبها والملك خالد الدوليين في المملكة، وأسفرا عن وقوع عددٍ من الوفيات لمقيمين من الجنسيات المغربية والجزائرية والسودانية وعددٍ من الإصابات، وعدتهما انتهاكًا سافرًا لسيادة المملكة العربية السعودية، وتهديدًا لأمنها واستقرارها، وخرقًا فاضحًا للقانون الدولي وميثاق الأمم المتحدة.","وأكّد الناطق الرسمي باسم وزارة الخارجية الأردنية السفير فؤاد المجالي إدانة الأردن الاعتداءات على الأعيان المدنية والاقتصادية في المملكة العربية، وتضامن الأردن المطلق مع المملكة، ووقوفها معها في كل ما تتخذه من خطوات لحماية أمنها واستقرارها ومقدّراتها وسلامة مواطنيها والمقيمين فيها.","وأعرب السفير المجالي عن أصدق التعازي والمواساة لحكومات وشعوب وأسر الضحايا، متمنيًا الشفاء العاجل للمصابين."]','أخبار السعودية','الاقتصاد','14762316-bcc1-4cdc-935c-066342fadaf2','صحيفة عاجل الإلكترونية','https://ajel.sa/local/9w45hqnxb','https://ajel.sa/local/9w45hqnxb','https://ajel.sa/local/9w45hqnxb','https://ajel.sa/local/9w45hqnxb','فريق التحرير','عسير','2026-10-07T14:58:00.000Z','2026-10-07T17:58:00.000Z','2026-10-07T21:22:40.703Z','https://ajel.sa/cdn-cgi/image/width=1200,height=675,fit=cover,gravity=auto,format=jpeg/https://cdn.ajel.sa/articles/2026-07/%D9%88%D8%B2%D8%A7%D8%B1%D8%A9-%D8%A7%D9%84%D8%AE%D8%A7%D8%B1%D8%AC%D9%8A%D8%A9-%D8%A7%D9%84%D8%A8%D8%AD%D8%B1%D9%8A%D9%86%D9%8A%D8%A9-Z5ZXLWvm.jpg','/api/media/4d0645c3-82ba-432a-b2c4-4841d71b7fb0','/api/media/4d0645c3-82ba-432a-b2c4-4841d71b7fb0?variant=thumbnail','البحرين والأردن يدينان استهداف ميليشيا الحوثي مطارَي أبها والملك خالد الدوليين',1200,675,'valid','published','current','valid',46,'6a401a2d76f68a83d58814d4640d8adcb1be25b1c5ca34d8053e653cd9087f17','cc859755bacb21ab745ef3e0b13b1d3e95a242610d9af65c048591942769ff7b','محدّث','2026-10-07T21:22:40.703Z','2026-10-07T21:23:37.044Z','','',0,0,'saudi_region','مهم',75,NULL,0,0,0,'',NULL,NULL,NULL,'["الاقتصاد","الأمم المتحدة وأك د الناطق","وزارة الخارجية البحرينية في بيان","مجلس التعاون لدول الخليج العربية","السفر والسياحة","الاقتصاد والأسواق","الخليج العربي"]','["الأمم المتحدة وأك د الناطق","وزارة الخارجية البحرينية في بيان","مجلس التعاون لدول الخليج العربية","السفر والسياحة","الاقتصاد والأسواق","الخليج العربي"]','needs_review','below_category_threshold','[{"category":"الوظائف وسوق العمل","score":1.5},{"category":"الذكاء الاصطناعي","score":0},{"category":"الطاقة والصناعة","score":0}]','Active',NULL,NULL,0,0,'','',NULL,NULL,'','');
