CREATE TABLE IF NOT EXISTS "legacy_social_posts" (
  id TEXT PRIMARY KEY,platform TEXT NOT NULL,platform_post_id TEXT NOT NULL,post_url TEXT NOT NULL,
  public_account_id TEXT NOT NULL DEFAULT '',public_account_name TEXT NOT NULL DEFAULT '',account_verified INTEGER NOT NULL DEFAULT 0,
  account_created_at TEXT,published_at TEXT NOT NULL,text_excerpt TEXT NOT NULL,hashtags TEXT NOT NULL DEFAULT '[]',
  entities TEXT NOT NULL DEFAULT '[]',language TEXT NOT NULL DEFAULT 'ar',country TEXT NOT NULL DEFAULT '',
  region TEXT NOT NULL DEFAULT '',city TEXT NOT NULL DEFAULT '',engagement_count INTEGER NOT NULL DEFAULT 0,
  repost INTEGER NOT NULL DEFAULT 0,retrieved_at TEXT NOT NULL,content_hash TEXT NOT NULL,related_event_id TEXT,
  verification_status TEXT NOT NULL DEFAULT 'unverified',availability_status TEXT NOT NULL DEFAULT 'available',
  spam_score INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL, account_profile_url TEXT NOT NULL DEFAULT '', engagement_metrics TEXT NOT NULL DEFAULT '{}',
  UNIQUE(platform,platform_post_id),FOREIGN KEY(platform) REFERENCES social_platforms(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS social_hashtags (
  id TEXT PRIMARY KEY,hashtag TEXT NOT NULL,normalized_hashtag TEXT NOT NULL,platform TEXT NOT NULL,language TEXT NOT NULL DEFAULT 'ar',
  country TEXT NOT NULL DEFAULT '',region TEXT NOT NULL DEFAULT '',first_observed_at TEXT NOT NULL,earliest_verified_at TEXT,
  latest_observed_at TEXT NOT NULL,peak_observed_at TEXT,first_post_url TEXT NOT NULL DEFAULT '',
  earliest_verified_post_url TEXT NOT NULL DEFAULT '',latest_post_url TEXT NOT NULL DEFAULT '',
  first_account_id TEXT NOT NULL DEFAULT '',first_account_name TEXT NOT NULL DEFAULT '',first_account_verified_status INTEGER NOT NULL DEFAULT 0,
  mention_count INTEGER NOT NULL DEFAULT 0,unique_account_count INTEGER NOT NULL DEFAULT 0,engagement_count INTEGER NOT NULL DEFAULT 0,
  velocity_score REAL NOT NULL DEFAULT 0,trend_score REAL NOT NULL DEFAULT 0,related_event_id TEXT,related_news_ids TEXT NOT NULL DEFAULT '[]',
  related_hashtags TEXT NOT NULL DEFAULT '[]',tracking_status TEXT NOT NULL DEFAULT 'tracked',confidence_score INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL,UNIQUE(normalized_hashtag,platform,country,region)
);
