CREATE TABLE IF NOT EXISTS trend_events (
  id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,event_title TEXT NOT NULL,event_summary TEXT NOT NULL,event_type TEXT NOT NULL DEFAULT 'public_development',
  status TEXT NOT NULL DEFAULT 'Emerging',main_category TEXT NOT NULL DEFAULT 'المجتمع',subcategory TEXT NOT NULL DEFAULT '',
  first_observed_at TEXT NOT NULL,earliest_verified_at TEXT,latest_activity_at TEXT NOT NULL,peak_activity_at TEXT,
  main_hashtag TEXT NOT NULL DEFAULT '',related_hashtags TEXT NOT NULL DEFAULT '[]',keywords TEXT NOT NULL DEFAULT '[]',
  entities TEXT NOT NULL DEFAULT '[]',locations TEXT NOT NULL DEFAULT '[]',platforms TEXT NOT NULL DEFAULT '[]',
  trend_score REAL NOT NULL DEFAULT 0,reliability_score INTEGER NOT NULL DEFAULT 0,verification_status TEXT NOT NULL DEFAULT 'unverified',
  direction TEXT NOT NULL DEFAULT 'مستقر',country TEXT NOT NULL DEFAULT '',region TEXT NOT NULL DEFAULT '',city TEXT NOT NULL DEFAULT '',
  archive_status TEXT NOT NULL DEFAULT 'live',mention_count INTEGER NOT NULL DEFAULT 0,unique_account_count INTEGER NOT NULL DEFAULT 0,
  engagement_count INTEGER NOT NULL DEFAULT 0,spam_ratio REAL NOT NULL DEFAULT 0,related_news_count INTEGER NOT NULL DEFAULT 0,
  publication_status TEXT NOT NULL DEFAULT 'review',created_at TEXT NOT NULL,updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS trend_event_posts (
  event_id TEXT NOT NULL,post_id TEXT NOT NULL,importance INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(event_id,post_id),
  FOREIGN KEY(event_id) REFERENCES trend_events(id) ON DELETE CASCADE,FOREIGN KEY(post_id) REFERENCES "legacy_social_posts"(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS trend_event_news (
  event_id TEXT NOT NULL,article_id TEXT NOT NULL,match_score REAL NOT NULL DEFAULT 0,PRIMARY KEY(event_id,article_id),
  FOREIGN KEY(event_id) REFERENCES trend_events(id) ON DELETE CASCADE,FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS trend_timeline (
  id TEXT PRIMARY KEY,event_id TEXT NOT NULL,occurred_at TEXT NOT NULL,event_type TEXT NOT NULL,label TEXT NOT NULL,
  source_url TEXT NOT NULL DEFAULT '',verified INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,
  FOREIGN KEY(event_id) REFERENCES trend_events(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS social_runs (
  id TEXT PRIMARY KEY,trigger TEXT NOT NULL,platform_id TEXT,status TEXT NOT NULL,posts_processed INTEGER NOT NULL DEFAULT 0,
  spam_excluded INTEGER NOT NULL DEFAULT 0,duplicates_grouped INTEGER NOT NULL DEFAULT 0,hashtags_updated INTEGER NOT NULL DEFAULT 0,
  events_created INTEGER NOT NULL DEFAULT 0,events_updated INTEGER NOT NULL DEFAULT 0,news_linked INTEGER NOT NULL DEFAULT 0,
  failures INTEGER NOT NULL DEFAULT 0,rate_limit_status TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '',
  started_at TEXT NOT NULL,finished_at TEXT,duration_ms INTEGER
);
CREATE TABLE IF NOT EXISTS social_retrieval_locks (
  platform_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,expires_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS social_settings (
  id INTEGER PRIMARY KEY CHECK(id=1),value TEXT NOT NULL,updated_at TEXT NOT NULL
);
INSERT OR REPLACE INTO social_settings (id,value,updated_at) VALUES (1,'{"countries":["السعودية","الخليج","العالم العربي"],"regions":[],"categories":["أخبار السعودية","السياسة","الاقتصاد والأعمال","المجتمع","الرياضة","التقنية","الذكاء الاصطناعي","الصحة","الثقافة والفنون","السيارات والنقل","السفر والسياحة","التعليم","الطاقة","البيئة","الفعاليات والمواسم"],"trackedAccounts":[],"trackedHashtags":[],"trackedKeywords":[],"retrievalFrequencyMinutes":10,"historicalSearchHours":48,"maximumApiUsage":1000,"minimumTrendScore":35,"automaticPublicationEnabled":false,"requiresEditorialReview":true,"liveHours":24,"decliningHours":48,"archiveHours":168,"spamThreshold":60}','2026-07-30T05:17:12.293Z');
CREATE TABLE IF NOT EXISTS social_tracking_terms (
  id TEXT PRIMARY KEY,kind TEXT NOT NULL,value TEXT NOT NULL,platform TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(kind,value,platform)
);
CREATE TABLE IF NOT EXISTS retrieval_runs (
        id TEXT PRIMARY KEY,trigger TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT,status TEXT NOT NULL,
        discovered INTEGER NOT NULL DEFAULT 0,imported INTEGER NOT NULL DEFAULT 0,rejected INTEGER NOT NULL DEFAULT 0,
        duplicates INTEGER NOT NULL DEFAULT 0,images_retrieved INTEGER NOT NULL DEFAULT 0,image_failures INTEGER NOT NULL DEFAULT 0,
        published INTEGER NOT NULL DEFAULT 0,archived INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',
        started_at TEXT NOT NULL,finished_at TEXT,duration_ms INTEGER
      , known INTEGER NOT NULL DEFAULT 0, processed INTEGER NOT NULL DEFAULT 0, review INTEGER NOT NULL DEFAULT 0, failed INTEGER NOT NULL DEFAULT 0, sources_processed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS source_retrieval_results (
  id TEXT PRIMARY KEY,run_id TEXT NOT NULL,source_id TEXT NOT NULL,status TEXT NOT NULL,method TEXT NOT NULL DEFAULT '',
  checked_at TEXT NOT NULL,articles_available INTEGER NOT NULL DEFAULT 0,discovered INTEGER NOT NULL DEFAULT 0,
  known INTEGER NOT NULL DEFAULT 0,processed INTEGER NOT NULL DEFAULT 0,rejected INTEGER NOT NULL DEFAULT 0,
  published INTEGER NOT NULL DEFAULT 0,review INTEGER NOT NULL DEFAULT 0,failed INTEGER NOT NULL DEFAULT 0,
  latest_source_date TEXT,latest_imported_date TEXT,failure_reason TEXT NOT NULL DEFAULT '',details TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE IF NOT EXISTS article_retrieval_log (
  id TEXT PRIMARY KEY,run_id TEXT NOT NULL,source_id TEXT NOT NULL,url TEXT NOT NULL DEFAULT '',stage TEXT NOT NULL,
  status TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',duplicate_id TEXT,similarity_score REAL,created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS retrieval_locks (source_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS article_source_checks (
  id TEXT PRIMARY KEY,article_id TEXT NOT NULL,source_id TEXT,checked_at TEXT NOT NULL,http_status INTEGER,
  source_status TEXT NOT NULL,content_changed INTEGER NOT NULL DEFAULT 0,source_updated_at TEXT,
  final_url TEXT NOT NULL DEFAULT '',reason TEXT NOT NULL DEFAULT '',attempt INTEGER NOT NULL DEFAULT 1,
  FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS social_posts (
  id TEXT PRIMARY KEY,platform TEXT NOT NULL,post_id TEXT NOT NULL,
  author_username TEXT NOT NULL,author_name TEXT NOT NULL,author_avatar_url TEXT NOT NULL DEFAULT '',author_verified INTEGER NOT NULL DEFAULT 0,
  content TEXT NOT NULL,url TEXT NOT NULL,published_at TEXT NOT NULL,
  media_type TEXT NOT NULL DEFAULT 'text',media_urls TEXT NOT NULL DEFAULT '[]',thumbnail_url TEXT NOT NULL DEFAULT '',
  likes_count INTEGER NOT NULL DEFAULT 0,reposts_count INTEGER NOT NULL DEFAULT 0,replies_count INTEGER NOT NULL DEFAULT 0,views_count INTEGER NOT NULL DEFAULT 0,
  engagement_score REAL NOT NULL DEFAULT 0,trend_score REAL NOT NULL DEFAULT 0,
  hashtags TEXT NOT NULL DEFAULT '[]',language TEXT NOT NULL DEFAULT 'ar',sentiment TEXT NOT NULL DEFAULT 'neutral',
  status TEXT NOT NULL DEFAULT 'published',article_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,
  FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE SET NULL
);
CREATE TABLE IF NOT EXISTS trends (
  id TEXT PRIMARY KEY,topic TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,
  type TEXT NOT NULL DEFAULT 'story',platform TEXT NOT NULL DEFAULT 'all',
  mention_count INTEGER NOT NULL DEFAULT 1,source_count INTEGER NOT NULL DEFAULT 1,
  x_engagement INTEGER NOT NULL DEFAULT 0,ig_engagement INTEGER NOT NULL DEFAULT 0,
  velocity REAL NOT NULL DEFAULT 0,trend_score REAL NOT NULL DEFAULT 0,
  summary TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT 'عام',
  related_article_ids TEXT NOT NULL DEFAULT '[]',related_social_post_ids TEXT NOT NULL DEFAULT '[]',
  first_detected_at TEXT NOT NULL,peak_at TEXT NOT NULL,last_updated_at TEXT NOT NULL,
